    );
    (, uint256 oneDayAgoMine, ) = _getMinerMineData(
        miner,
        currentDay.sub(1)
    );
    (, uint256 todayMine, ) = _getMinerMineData(miner, currentDay);
    return
    twoDaysAgoMine >= serviceMinMine &&
        oneDayAgoMine >= serviceMinMine &&
        todayMine >= serviceMinMine;
}

