function _minMined(
    address miner,
    uint256 dayCount,
    uint256 amount
) internal view returns(bool) {
    if (dayCount == 0 && amount == 0) {
        return true;
    }
    uint256 currentDay = _getCurrentDay();
    uint256 endDay = currentDay.sub(dayCount);
    for (uint256 day = currentDay; day >= endDay; day--) {
        (, uint256 minedAmount, ) = _getMinerMineData(miner, day);
        if (minedAmount < amount) {
            return false;
        }
    }
    return true;
}

function getRewardsDueAll(address miner) public view returns(uint256) {
