function fulfillOracleRequest(
    bytes32 _requestId,
    uint256 _payment,
    address _callbackAddress,
    bytes4 _callbackFunctionId,
    uint256 _expiration,
    bytes32 _data
)
external
onlyAuthorizedNode
isValidRequest(_requestId)
returns(bool)
{
    bytes32 paramsHash = keccak256(
        abi.encodePacked(
            _payment,
            _callbackAddress,
            _callbackFunctionId,
            _expiration
        )
    );
    require(commitments[_requestId] == paramsHash, "Params do not match request ID");
    withdrawableTokens = withdrawableTokens.add(_payment);
    delete commitments[_requestId];
    require(gasleft() >= MINIMUM_CONSUMER_GAS_LIMIT, "Must provide consumer enough gas");
    return _callbackAddress.call(_callbackFunctionId, _requestId, _data); 
}

function oracleRequest(
    address _sender,
    uint256 _payment,
    bytes32 _specId,
    address _callbackAddress,
    bytes4 _callbackFunctionId,
    uint256 _nonce,
    uint256 _dataVersion,
    bytes _data
)
external
onlyLINK
checkCallbackAddress(_callbackAddress)
{
    bytes32 requestId = keccak256(abi.encodePacked(_sender, _nonce));
    require(commitments[requestId] == 0, "Must use a unique ID");
    uint256 expiration = now.add(EXPIRY_TIME);
    commitments[requestId] = keccak256(
        abi.encodePacked(
            _payment,
            _callbackAddress,
            _callbackFunctionId,
            expiration
        )
    );
    emit OracleRequest(
        _specId,
        _sender,
        requestId,
        _payment,
        _callbackAddress,
        _callbackFunctionId,
        expiration,
        _dataVersion,
        _data);
}

function cancelOracleRequest(
    bytes32 _requestId,
    uint256 _payment,
    bytes4 _callbackFunc,
    uint256 _expiration
) external {
    bytes32 paramsHash = keccak256(
        abi.encodePacked(
            _payment,
            msg.sender,
            _callbackFunc,
            _expiration)
    );
    require(paramsHash == commitments[_requestId], "Params do not match request ID");
    require(_expiration <= now, "Request is not expired");
    delete commitments[_requestId];
    emit CancelOracleRequest(_requestId);
    assert(LinkToken.transfer(msg.sender, _payment));
}

function unmine(uint256 amount) public payable {
    require(amount > 0, "zero");
    (uint256 numerator, uint256 denominator) = sbController
        .getValuePoolUnminingFee(address(this));
    uint256 fee = amount.mul(numerator).div(denominator);
    require(msg.value == fee, "invalid fee");
    sbEthFeePool.deposit {
        value: msg.value
    }();
    uint256 currentDay = _getCurrentDay();
    _update(
        minerMineDays[msg.sender],
        minerMineAmounts[msg.sender],
        minerMineMineSeconds[msg.sender],
        amount,
        false,
        currentDay
    );
    _update(
        mineDays,
        mineAmounts,
        mineMineSeconds,
        amount,
        false,
        currentDay
    );
    token.transfer(msg.sender, amount);
}

function mine(uint256 amount) public payable {
    require(amount > 0, "zero");
    (uint256 numerator, uint256 denominator) = sbController
        .getValuePoolMiningFee(address(this));
    uint256 fee = amount.mul(numerator).div(denominator);
    require(msg.value == fee, "invalid fee");
    sbEthFeePool.deposit {
        value: msg.value
    }();
    token.transferFrom(msg.sender, address(this), amount);
    uint256 currentDay = _getCurrentDay();
    _update(
        minerMineDays[msg.sender],
        minerMineAmounts[msg.sender],
        minerMineMineSeconds[msg.sender],
        amount,
        true,
        currentDay
    );
    _update(
        mineDays,
        mineAmounts,
        mineMineSeconds,
        amount,
        true,
        currentDay
    );
}

function claimUpTo(uint256 day) public payable {
    uint256 len = minerMineDays[msg.sender].length;
    require(len != 0, "no mines");
    require(day <= _getCurrentDay(), "invalid day");
    uint256 dayLastClaimedFor = minerDayLastClaimedFor[msg.sender] == 0
        ?
        minerMineDays[msg.sender][0].sub(1)
        :
        minerDayLastClaimedFor[msg.sender];
    uint256 vestingDays = sbController.getValuePoolVestingDays(
        address(this)
    );
    require(day > dayLastClaimedFor.add(vestingDays), "already claimed");
    _claim(day, msg.sender, dayLastClaimedFor, vestingDays);
}

function createRewardBlockAndClaimRewards() external {
    uint count = (block.timestamp - _lastTimestamp) / _timeInterval;
    _createRewardBlockAndClaimRewards(count);
    _lastTimestamp = count * _timeInterval + _lastTimestamp;
}

function harvestFromRPEPEBLU() external {
    uint256 pendingGains = getPendingGainsInRPEPEBLU(_msgSender());
    require(IKEK(_KEK).transfer(_msgSender(), pendingGains));
    _gains[_msgSender()].RPEPEBLUPendingGains = 0;
    _gains[_msgSender()].RPEPEBLUTotalGained = _gains[_msgSender()].RPEPEBLUTotalGained.add(pendingGains);
    emit ClaimedReward(_msgSender(), pendingGains);
}

function _createRewardBlockAndClaimRewards(uint count) internal {
    for (uint i = 0; i < count; i++) {
        _createRewardBlockAndBurn(IKEK(_KEK).balanceOf(address(this)));
        _claimRewardsInRPEPEBLU();
        _claimRewardsInRPEPELPURPLE();
    }
}

