function mine()
external
onlyOnStage(STAGE.ENDING_MINING)
{
    uint currentStepReward;
    if (miningStep == 0)
    {
        mine_requestRandomSeed();
        mine_removeUniswapLiquidityAndTransferProfits();
        uint totalMinerRewards =
            (ending_profitAmount * cfg.minerProfitShare) /
            (_100PERCENT);
        if (cfg.endingAlgoType == uint8(EndingAlgoType.MinedWinnerSelection))
        {
            currentStepReward = (totalMinerRewards * (10 * PERCENT)) /
                (_100PERCENT);
        }
        else
        {
            currentStepReward = (totalMinerRewards * (80 * PERCENT)) /
                (_100PERCENT);
        }
        require(currentStepReward <= totalMinerRewards);
    }
    else
    {
        if (cfg.endingAlgoType != uint8(EndingAlgoType.MinedWinnerSelection))
        {
            require(lotStorage.getRandomSeed() == 0 &&
                alternativeSeedGenerationPossible());
        }
        uint totalMinerRewards =
            (ending_profitAmount * cfg.minerProfitShare) /
            (_100PERCENT);
        if (lotStorage.getRandomSeed() == 0)
        {
            if (alternativeSeedGenerationPossible())
            {
                lotStorage.setRandomSeed(transferHashValue);
                if (cfg.endingAlgoType !=
                    uint8(EndingAlgoType.MinedWinnerSelection))
                {
                    currentStepReward =
                        (totalMinerRewards * (20 * PERCENT)) /
                        (_100PERCENT);
                }
            } else
            {
                require(false);
            }
        }
        if (cfg.endingAlgoType == uint8(EndingAlgoType.MinedWinnerSelection))
        {
            mine_executeEndingAlgorithmStep();
            currentStepReward = (totalMinerRewards * (90 * PERCENT)) /
                (_100PERCENT);
        }
        lotteryStage = uint8(STAGE.COMPLETION);
        completionDate = uint32(now);
        require(currentStepReward <= totalMinerRewards);
    }
    miningStep++;
    require(!reEntrancyMutexLocked);
    reEntrancyMutexLocked = true;
    msg.sender.transfer(currentStepReward);
    reEntrancyMutexLocked = false;
}

function initialize()
external
payable
poolOnly
mutexLOCKED
onlyOnStage(STAGE.INITIAL)
{
    require(address(this).balance == cfg.initialFunds);
    startDate = uint32(now);
    transferHashValue = uint(keccak256(
        abi.encodePacked(msg.sender, now)));
    finishProbablity = cfg.finish_initialProbability;
    _mint(address(this),
        uint(cfg.initialTokenSupply) * (10 ** decimals));
    _approve(address(this), address(uniswapRouter), uint(-1));
    uniswapRouter.addLiquidityETH
    {
        value: address(this).balance
    }
    (
        address(this), 
        totalSupply(), 
        totalSupply(), 
        address(this).balance, 
        address(this), 
        (now + 1000) 
    );
    exchangeAddress = IUniswapFactory(uniswapRouter.factory())
        .getPair(WETHaddress, address(this));
    if (IUniswapPair(exchangeAddress).token0() == WETHaddress)
        uniswap_ethFirst = true;
    else
        uniswap_ethFirst = false;
    lotteryStage = uint8(STAGE.ACTIVE);
    emit LotteryInitialized();
}

function _transfer(address sender,
    address receiver,
    uint256 amount)
internal
override
{
    if (!onStage(STAGE.ACTIVE) &&
        !onStage(STAGE.FINISHING) &&
        (sender == address(this) || receiver == address(this) ||
            specialTransferModeEnabled))
    {
        super._transfer(sender, receiver, amount);
        return;
    }
    require((onStage(STAGE.ACTIVE) ||
        onStage(STAGE.FINISHING)));
    require(amount != 0 && sender != address(0));
    uint burnAmount;
    if (sender == exchangeAddress)
        burnAmount = (amount * cfg.burn_buyerRate) / (_100PERCENT);
    else
        burnAmount = (amount * cfg.burn_defaultRate) / (_100PERCENT);
    uint finalAmount = amount - burnAmount;
    if (receiver != exchangeAddress)
    {
        require(!transferExceedsMaxBalance(receiver, finalAmount));
    }
    bool holderCountChanged = updateHolderData_preTransfer(
        sender,
        receiver,
        amount, 
        finalAmount 
    );
    super._burn(sender, burnAmount);
    super._transfer(sender, receiver, finalAmount);
    transferHashValue = uint(keccak256(abi.encodePacked(
        transferHashValue, msg.sender, sender, receiver, amount)));
    checkFinishingStageConditions();
    if (onStage(STAGE.FINISHING))
        checkForEnding(holderCountChanged);
}

function isMiningAvailable()
external view
returns(bool)
{
    return onStage(STAGE.ENDING_MINING) &&
        (miningStep == 0 ||
            (miningStep == 1 &&
                (lotStorage.getRandomSeed() != 0 ||
                    alternativeSeedGenerationPossible())
            ));
}

function alternativeSeedGenerationPossible()
internal view
returns(bool)
{
    return (onStage(STAGE.ENDING_MINING) &&
        ((now - finish_timeRandomSeedRequested) >
            cfg.REQUIRED_TIME_WAITING_FOR_RANDOM_SEED));
}

function mine_removeUniswapLiquidityAndTransferProfits()
internal
mutexLOCKED
{
    ERC20(exchangeAddress).approve(address(uniswapRouter), uint(-1));
    specialTransferModeEnabled = true;
    uint amountETH = uniswapRouter
        .removeLiquidityETHSupportingFeeOnTransferTokens(
            address(this), 
            ERC20(exchangeAddress).balanceOf(address(this)),
            0, 
            0, 
            address(this), 
            (now + 10000000) 
        );
    specialTransferModeEnabled = false;
    require(address(this).balance >= amountETH &&
        address(this).balance >= cfg.initialFunds);
    ending_totalReturn = uint128(address(this).balance);
    ending_profitAmount = ending_totalReturn - uint128(cfg.initialFunds);
    uint poolShare = (ending_profitAmount * cfg.poolProfitShare) /
        (_100PERCENT);
    uint ownerShare = (ending_profitAmount * cfg.ownerProfitShare) /
        (_100PERCENT);
    IUniLotteryPool(poolAddress).lotteryFinish
    {
        value: poolShare + cfg.initialFunds
    }
    (ending_totalReturn, ending_profitAmount);
    OWNER_ADDRESS.transfer(ownerShare);
    emit LotteryEnd(ending_totalReturn, ending_profitAmount);
}

function getUnclaimedPrizes()
external
poolOnly
onlyOnStage(STAGE.COMPLETION)
mutexLOCKED
{
    require(completionDate != 0 &&
        (now - completionDate) > cfg.prizeClaimTime);
    poolAddress.transfer(address(this).balance);
}

function checkFinishingStageConditions()
internal
{
    if ((now - startDate) > cfg.maxLifetime)
    {
        lotteryStage = uint8(STAGE.FINISHING);
        return;
    }
    if (lotStorage.getHolderCount() >= cfg.finishCriteria_minNumberOfHolders
        &&
        getCurrentEthFunds() >= cfg.finishCriteria_minFunds
        &&
        (now - startDate) >= cfg.finishCriteria_minTimeActive)
    {
        if (onStage(STAGE.ACTIVE))
        {
            lotteryStage = uint8(STAGE.FINISHING);
            emit FinishingStageStarted();
        }
    } else if (onStage(STAGE.FINISHING))
    {
        lotteryStage = uint8(STAGE.ACTIVE);
        if (cfg.finish_resetProbabilityOnStop)
            finishProbablity = cfg.finish_initialProbability;
        emit FinishingStageStopped();
    }
}

function checkForEnding(bool holderCountChanged)
internal
{
    if ((now - startDate) > cfg.maxLifetime)
    {
        startEndingStage();
        return;
    }
    uint prec = 10000;
    uint modAmount = (prec * _100PERCENT) / finishProbablity;
    if ((transferHashValue % modAmount) <= prec)
    {
        startEndingStage();
        return;
    }
    finishProbablity += cfg.finish_probabilityIncreaseStep_transaction;
    if (holderCountChanged)
        finishProbablity += cfg.finish_probabilityIncreaseStep_holder;
}

function updateHolderData_preTransfer(
    address sender,
    address receiver,
    uint256 amountSent,
    uint256 amountReceived)
internal
returns(bool holderCountChanged)
{
    holderCountChanged = false;
    if (balanceOf(sender) == amountSent)
    {
        lotStorage.removeHolder(sender);
        holderCountChanged = true;
    }
    if (balanceOf(receiver) == 0 && amountReceived > 0)
    {
        lotStorage.addHolder(receiver);
        holderCountChanged = true;
    }
    int buySellValue;
    if (sender == exchangeAddress && receiver != exchangeAddress)
    {
        address[] memory path = new address[](2);
        path[0] = WETHaddress;
        path[1] = address(this);
        uint[] memory ethAmountIn = uniswapRouter.getAmountsIn(
            amountSent, 
            path 
        );
        buySellValue = int(ethAmountIn[0]);
        int timeFactorValue = (buySellValue / (10 ** 12)) *
            int((now - startDate) / cfg.timeFactorDivisor);
        lotStorage.updateAndPropagateScoreChanges(
            receiver,
            int80(buySellValue),
            int80(timeFactorValue),
            int80(amountReceived));
    }
    else if (sender != exchangeAddress && receiver == exchangeAddress)
    {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = WETHaddress;
        uint[] memory ethAmountOut = uniswapRouter.getAmountsOut(
            amountReceived, 
            path 
        );
        buySellValue = int(-1) * int(ethAmountOut[1]);
        int timeFactorValue = (buySellValue / (10 ** 12)) *
            int((now - startDate) / cfg.timeFactorDivisor);
        lotStorage.updateAndPropagateScoreChanges(
            sender,
            int80(buySellValue),
            int80(timeFactorValue),
            -1 * int80(amountSent));
    }
    else {
        buySellValue = 0;
        lotStorage.updateAndPropagateScoreChanges(sender, 0, 0,
            -1 * int80(amountSent));
        lotStorage.updateAndPropagateScoreChanges(receiver, 0, 0,
            int80(amountReceived));
    }
    uint ethFunds = getCurrentEthFunds();
    if (!fundGainRequirementReached &&
        ethFunds >= cfg.fundRequirement_denySells)
    {
        fundGainRequirementReached = true;
    }
    if (fundGainRequirementReached &&
        buySellValue < 0 &&
        (uint(-1 * buySellValue) >= ethFunds ||
            ethFunds - uint(-1 * buySellValue) <
            cfg.fundRequirement_denySells))
    {
        require(false);
    }
}

function mine_requestRandomSeed()
internal
{
    IRandomnessProvider(randomnessProvider)
        .requestRandomSeedForLotteryFinish();
    finish_timeRandomSeedRequested = uint32(now);
    emit RandomnessProviderCalled();
}

function finish_randomnessProviderCallback(
    uint256 randomSeed,
    uint256  )
external
randomnessProviderOnly
{
    lotStorage.setRandomSeed(randomSeed);
    if (cfg.endingAlgoType != uint8(EndingAlgoType.MinedWinnerSelection))
    {
        lotteryStage = uint8(STAGE.COMPLETION);
        completionDate = uint32(now);
    }
}

function construct(
    LotteryConfig memory config,
    address payable _poolAddress,
    address _randomProviderAddress,
    address _storageAddress)
external
{
    require(poolAddress == address(0));
    poolAddress = _poolAddress;
    randomnessProvider = _randomProviderAddress;
    require(config.maxLifetime <= MAX_LOTTERY_LIFETIME);
    require(config.poolProfitShare >= MIN_POOL_PROFITS &&
        config.poolProfitShare <= MAX_POOL_PROFITS);
    require(config.ownerProfitShare >= MIN_OWNER_PROFITS &&
        config.ownerProfitShare <= MAX_OWNER_PROFITS);
    require(config.minerProfitShare >= MIN_MINER_PROFITS &&
        config.minerProfitShare <= MAX_MINER_PROFITS);
    uint32 totalWinnerShare =
        (_100PERCENT) - config.poolProfitShare
        -
        config.ownerProfitShare
        -
        config.minerProfitShare;
    require(totalWinnerShare >= MIN_WINNER_PROFIT_SHARE);
    require(config.randRatio_scorePart != 0 &&
        config.randRatio_randPart != 0 &&
        (config.randRatio_scorePart +
            config.randRatio_randPart) < 10000);
    require(config.endingAlgoType ==
        uint8(EndingAlgoType.MinedWinnerSelection) ||
        config.endingAlgoType ==
        uint8(EndingAlgoType.WinnerSelfValidation) ||
        config.endingAlgoType ==
        uint8(EndingAlgoType.RolledRandomness));
    if (config.prizeSequence_winnerCount == 0 &&
        config.winnerProfitShares.length != 0)
        config.prizeSequence_winnerCount =
        uint16(config.winnerProfitShares.length);
    LotteryStorage _lotStorage = LotteryStorage(_storageAddress);
    LotteryStorage.WinnerAlgorithmConfig memory winnerConfig;
    winnerConfig.endingAlgoType = config.endingAlgoType;
    winnerConfig.maxPlayerScore_etherContributed =
        config.maxPlayerScore_etherContributed;
    winnerConfig.maxPlayerScore_tokenHoldingAmount =
        config.maxPlayerScore_tokenHoldingAmount;
    winnerConfig.maxPlayerScore_timeFactor =
        config.maxPlayerScore_timeFactor;
    winnerConfig.maxPlayerScore_refferalBonus =
        config.maxPlayerScore_refferalBonus;
    winnerConfig.randRatio_scorePart = config.randRatio_scorePart;
    winnerConfig.randRatio_randPart = config.randRatio_randPart;
    winnerConfig.winnerCount = config.prizeSequence_winnerCount;
    _lotStorage.initialize(winnerConfig);
    lotStorage = _lotStorage;
    cfg = config;
    WETHaddress = uniswapRouter.WETH();
}

function claimWinnerPrize(
    uint32 rankingPosition)
external
onlyOnStage(STAGE.COMPLETION)
mutexLOCKED
{
    require(!prizeClaimersAddresses[msg.sender]);
    require(balanceOf(msg.sender) != 0);
    require(address(this).balance != 0);
    if (cfg.endingAlgoType == uint8(EndingAlgoType.MinedWinnerSelection))
    {
        require(lotStorage.minedSelection_isAddressOnWinnerPosition(
            msg.sender, rankingPosition));
    }
    else
    {
        bool isWinner;
        (isWinner, rankingPosition) =
        lotStorage.getWinnerStatus(msg.sender);
        require(isWinner);
    }
    uint finalPrizeAmount = getWinnerPrizeAmount(rankingPosition);
    if (finalPrizeAmount > address(this).balance)
        finalPrizeAmount = address(this).balance;
    msg.sender.transfer(finalPrizeAmount);
    prizeClaimersAddresses[msg.sender] = true;
}

function queueTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public returns(bytes32) {
    require(msg.sender == admin, "Timelock::queueTransaction: Call must come from admin.");
    require(eta >= getBlockTimestamp().add(delay), "Timelock::queueTransaction: Estimated execution block must satisfy delay.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

function executeTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public payable returns(bytes memory) {
    require(msg.sender == admin, "Timelock::executeTransaction: Call must come from admin.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "Timelock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "Timelock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "Timelock::executeTransaction: Transaction is stale.");
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call.value(value)(callData);
    require(success, "Timelock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

function reclaimPayment(
    uint256 seed,
    uint256 n_iter,
    uint256 tag
) external randomnessNotRegistered(seed, n_iter) {
    Payment memory userPayment = payments[msg.sender][seed][n_iter][tag];
    require(userPayment.amount > 0, "NO_PAYMENT");
    uint256 lastPaymentTime = userPayment.timeSent;
    uint256 releaseTime = lastPaymentTime + RECLAIM_DELAY;
    assert(releaseTime >= RECLAIM_DELAY);
    require(now >= releaseTime, "PAYMENT_LOCKED");
    prizes[seed][n_iter] -= userPayment.amount;
    payments[msg.sender][seed][n_iter][tag].amount = 0;
    transferOut(userPayment.amount);
    emit LogPaymentReclaimed(
        msg.sender,
        seed,
        n_iter,
        tag,
        userPayment.amount
    );
}

function addPayment(
    uint256 seed,
    uint256 n_iter,
    uint256 tag,
    uint256 paymentAmount
) external randomnessNotRegistered(seed, n_iter) {
    transferIn(paymentAmount);
    payments[msg.sender][seed][n_iter][tag].amount += paymentAmount;
    payments[msg.sender][seed][n_iter][tag].timeSent = now;
    prizes[seed][n_iter] += paymentAmount;
    emit LogNewPayment(seed, n_iter, paymentAmount);
}

function _isPumpOK(
    address stableCoinAddress,
    address tokenAddress,
    uint256 tokenValue,
    address token0,
    uint256 return0,
    address token1,
    uint256 return1,
    uint256 stableCoinAmount
) private view returns(bool) {
    IStableCoin stableCoin = IStableCoin(stableCoinAddress);
    uint256 cumulative = stableCoin.fromTokenToStable(
        tokenAddress,
        tokenValue
    );
    cumulative += stableCoin.fromTokenToStable(token0, return0);
    cumulative += stableCoin.fromTokenToStable(token1, return1);
    uint256 percentage = (cumulative * _percentage[0]) / _percentage[1];
    uint256 cumulativePlus = cumulative + percentage;
    uint256 cumulativeMinus = cumulative - percentage;
    return
    stableCoinAmount >= cumulativeMinus &&
        stableCoinAmount <= cumulativePlus;
}

function earnByPump(
    address stableCoinAddress,
    uint256 pairIndex,
    uint256 pairAmount,
    uint256 amount0,
    uint256 amount1,
    address tokenAddress,
    uint256 tokenValue
) public override {
    require(
        _isValidPairToken(stableCoinAddress, tokenAddress),
        "Choosen token address is not in a valid pair"
    );
    _transferToMeAndCheckAllowance(
        tokenAddress,
        tokenValue,
        UNISWAP_V2_ROUTER
    );
    uint256 stableCoinAmount = _swap(
        tokenAddress,
        stableCoinAddress,
        tokenValue,
        address(this)
    );
    (uint256 return0, uint256 return1) = IStableCoin(stableCoinAddress)
        .burn(pairIndex, pairAmount, amount0, amount1);
    (address token0, address token1, ) = _getPairData(
        stableCoinAddress,
        pairIndex
    );
    require(
        _isPumpOK(
            stableCoinAddress,
            tokenAddress,
            tokenValue,
            token0,
            return0,
            token1,
            return1,
            stableCoinAmount
        ),
        "Values are not coherent"
    );
    _flushToSender(token0, token1, stableCoinAddress);
}

function _updateGuardianFeesAndBootstrap(address guardian, bool inCommittee, bool isCertified, bool nextCertification, uint generalCommitteeSize, uint certifiedCommitteeSize) private {
    uint256 addedBootstrapAmount;
    uint256 addedFeesAmount;
    FeesAndBootstrapState memory _feesAndBootstrapState = _updateFeesAndBootstrapState(generalCommitteeSize, certifiedCommitteeSize);
    (feesAndBootstrap[guardian], addedBootstrapAmount, addedFeesAmount) = _getGuardianFeesAndBootstrap(guardian, inCommittee, isCertified, nextCertification, _feesAndBootstrapState);
    emit BootstrapRewardsAssigned(guardian, addedBootstrapAmount);
    emit FeesAssigned(guardian, addedFeesAmount);
}

function setCertifiedCommitteeAnnualBootstrap(uint256 annualAmount) external override onlyFunctionalManager {
    updateFeesAndBootstrapState();
    _setCertifiedCommitteeAnnualBootstrap(annualAmount);
}

function setGeneralCommitteeAnnualBootstrap(uint256 annualAmount) external override onlyFunctionalManager {
    updateFeesAndBootstrapState();
    _setGeneralCommitteeAnnualBootstrap(annualAmount);
}

function withdrawFees(address guardian) external override onlyWhenActive {
    updateGuardianFeesAndBootstrap(guardian);
    uint256 amount = feesAndBootstrap[guardian].feeBalance;
    feesAndBootstrap[guardian].feeBalance = 0;
    emit FeesWithdrawn(guardian, amount);
    require(erc20.transfer(guardian, amount), "Rewards::withdrawFees - insufficient funds");
}

function _updateFeesAndBootstrapState(uint generalCommitteeSize, uint certifiedCommitteeSize) private returns(FeesAndBootstrapState memory _feesAndBootstrapState) {
    Settings memory _settings = settings;
    if (!_settings.rewardAllocationActive) {
        return feesAndBootstrapState;
    }
    uint256 collectedGeneralFees = generalFeesWallet.collectFees();
    uint256 collectedCertifiedFees = certifiedFeesWallet.collectFees();
    uint256 allocatedBootstrap;
    (_feesAndBootstrapState, allocatedBootstrap) = _getFeesAndBootstrapState(generalCommitteeSize, certifiedCommitteeSize, collectedGeneralFees, collectedCertifiedFees, _settings);
    bootstrapRewardsWallet.withdraw(allocatedBootstrap);
    feesAndBootstrapState = _feesAndBootstrapState;
}

function deactivateRewardDistribution() external override onlyMigrationManager {
    require(settings.rewardAllocationActive, "reward distribution is already deactivated");
    updateFeesAndBootstrapState();
    settings.rewardAllocationActive = false;
    emit RewardDistributionDeactivated();
}

function migrateRewardsBalance(address guardian) external override {
    require(!settings.rewardAllocationActive, "Reward distribution must be deactivated for migration");
    IFeesAndBootstrapRewards currentRewardsContract = IFeesAndBootstrapRewards(getFeesAndBootstrapRewardsContract());
    require(address(currentRewardsContract) != address(this), "New rewards contract is not set");
    updateGuardianFeesAndBootstrap(guardian);
    FeesAndBootstrap memory guardianFeesAndBootstrap = feesAndBootstrap[guardian];
    uint256 fees = guardianFeesAndBootstrap.feeBalance;
    uint256 bootstrap = guardianFeesAndBootstrap.bootstrapBalance;
    guardianFeesAndBootstrap.feeBalance = 0;
    guardianFeesAndBootstrap.bootstrapBalance = 0;
    feesAndBootstrap[guardian] = guardianFeesAndBootstrap;
    require(erc20.approve(address(currentRewardsContract), fees), "migrateRewardsBalance: approve failed");
    require(bootstrapToken.approve(address(currentRewardsContract), bootstrap), "migrateRewardsBalance: approve failed");
    currentRewardsContract.acceptRewardsBalanceMigration(guardian, fees, bootstrap);
    emit FeesAndBootstrapRewardsBalanceMigrated(guardian, fees, bootstrap, address(currentRewardsContract));
}

function withdrawBootstrapFunds(address guardian) external override onlyWhenActive {
    updateGuardianFeesAndBootstrap(guardian);
    uint256 amount = feesAndBootstrap[guardian].bootstrapBalance;
    feesAndBootstrap[guardian].bootstrapBalance = 0;
    emit BootstrapRewardsWithdrawn(guardian, amount);
    require(bootstrapToken.transfer(guardian, amount), "Rewards::withdrawBootstrapFunds - insufficient funds");
}

function _claim(
    uint256 upToDay,
    address miner,
    uint256 dayLastClaimedFor,
    uint256 vestingDays
) internal {
    uint256 rewards = _getRewardsDue(
        upToDay,
        miner,
        dayLastClaimedFor,
        vestingDays
    );
    require(rewards > 0, "no rewards");
    (uint256 numerator, uint256 denominator) = sbController
        .getServicePoolClaimingFee(address(this));
    uint256 fee = rewards.mul(numerator).div(denominator);
    require(msg.value == fee, "invalid fee");
    sbEthFeePool.deposit {
        value: msg.value
    }();
    minerDayLastClaimedFor[miner] = upToDay.sub(vestingDays);
    sbController.requestRewards(miner, rewards);
}

function requestAccess() public payable {
    require(!requestPending[msg.sender], "pending");
    require(!serviceAccepted[msg.sender], "accepted");
    uint256 feeInWei = sbController.getServicePoolRequestFeeInWei(
        address(this)
    );
    require(msg.value == feeInWei, "invalid fee");
    sbEthFeePool.deposit {
        value: msg.value
    }();
    requestPending[msg.sender] = true;
}

function getRewardsDueAll(address miner) public view returns(uint256) {
    uint256 len = minerMineDays[miner].length;
    if (len == 0) {
        return 0;
    }
    uint256 currentDay = _getCurrentDay();
    uint256 dayLastClaimedFor = minerDayLastClaimedFor[miner] == 0
        ?
        minerMineDays[miner][0].sub(1)
        :
        minerDayLastClaimedFor[miner];
    uint256 vestingDays = sbController.getServicePoolVestingDays(
        address(this)
    );
    if (!(currentDay > dayLastClaimedFor.add(vestingDays))) {
        return 0;
    }
    return
    _getRewardsDue(currentDay, miner, dayLastClaimedFor, vestingDays);
}

function getRewardsDueUpTo(uint256 day, address miner)
public
view
returns(uint256)
{
    uint256 len = minerMineDays[miner].length;
    if (len == 0) {
        return 0;
    }
    require(day <= _getCurrentDay(), "invalid day");
    uint256 dayLastClaimedFor = minerDayLastClaimedFor[miner] == 0
        ?
        minerMineDays[miner][0].sub(1)
        :
        minerDayLastClaimedFor[miner];
    uint256 vestingDays = sbController.getServicePoolVestingDays(
        address(this)
    );
    if (!(day > dayLastClaimedFor.add(vestingDays))) {
        return 0;
    }
    return _getRewardsDue(day, miner, dayLastClaimedFor, vestingDays);
}

function _getRewardsDue(
    uint256 upToDay,
    address miner,
    uint256 dayLastClaimedFor,
    uint256 vestingDays
) internal view returns(uint256) {
    uint256 rewards;
    for (
        uint256 day = dayLastClaimedFor.add(1);
        day <= upToDay.sub(vestingDays);
        day++
    ) {
        uint256 availableRewards = sbController.getServicePoolRewards(
            address(this),
            day
        );
        (, , uint256 strongPoolMinerMineSecondsForDay) = sbStrongValuePool
            .getMinerMineData(miner, day);
        (, , uint256 strongPoolMineSecondsForDay) = sbStrongValuePool
            .getMineData(day);
        if (strongPoolMineSecondsForDay == 0) {
            continue;
        }
        uint256 amount = availableRewards
            .mul(strongPoolMinerMineSecondsForDay)
            .div(strongPoolMineSecondsForDay);
        rewards = rewards.add(amount);
    }
    return rewards;
}

function claimUpTo(uint256 day) public payable {
    uint256 len = minerMineDays[msg.sender].length;
    require(len != 0, "no mines");
    require(serviceAccepted[msg.sender], "invalid miner");
    require(sbStrongValuePool.serviceMinMined(msg.sender), "not min mined");
    require(day <= _getCurrentDay(), "invalid day");
    uint256 dayLastClaimedFor = minerDayLastClaimedFor[msg.sender] == 0
        ?
        minerMineDays[msg.sender][0].sub(1)
        :
        minerDayLastClaimedFor[msg.sender];
    uint256 vestingDays = sbController.getServicePoolVestingDays(
        address(this)
    );
    require(day > dayLastClaimedFor.add(vestingDays), "already claimed");
    _claim(day, msg.sender, dayLastClaimedFor, vestingDays);
}

function claimAll() public payable {
    uint256 len = minerMineDays[msg.sender].length;
    require(len != 0, "no mines");
    require(serviceAccepted[msg.sender], "invalid miner");
    require(sbStrongValuePool.serviceMinMined(msg.sender), "not min mined");
    uint256 currentDay = _getCurrentDay();
    uint256 dayLastClaimedFor = minerDayLastClaimedFor[msg.sender] == 0
        ?
        minerMineDays[msg.sender][0].sub(1)
        :
        minerDayLastClaimedFor[msg.sender];
    uint256 vestingDays = sbController.getServicePoolVestingDays(
        address(this)
    );
    require(
        currentDay > dayLastClaimedFor.add(vestingDays),
        "already claimed"
    );
    _claim(currentDay, msg.sender, dayLastClaimedFor, vestingDays);
}

function withdraw(uint wad) public {
    require(balanceOf[msg.sender] >= wad);
    balanceOf[msg.sender] -= wad;
    msg.sender.transfer(wad);
    Withdrawal(msg.sender, wad);
}

function tokensLocked(address _user, bytes32 _reason, uint256 _time) public view returns(uint256 amount) {
    if (locked[_user][_reason].validity > _time)
        amount = locked[_user][_reason].amount;
}

function transferFrom(address from, address to, uint256 tokens) public override returns(bool success) {
    unlockTokens();
    require(tokens <= allowed[from][msg.sender]); 
    require(balances[from] >= tokens);
    if (from == owner) {
        require(balances[msg.sender].sub(tokens) >= lockedTokens);
    }
    balances[from] = balances[from].sub(tokens);
    balances[to] = balances[to].add(tokens);
    allowed[from][msg.sender] = allowed[from][msg.sender].sub(tokens);
    emit Transfer(from, to, tokens);
    return true;
}

function transfer(address to, uint256 tokens) public override returns(bool success) {
    unlockTokens();
    require(address(to) != address(0));
    require(balances[msg.sender] >= tokens);
    require(balances[to] + tokens >= balances[to]);
    if (msg.sender == owner) {
        require(balances[msg.sender].sub(tokens) >= lockedTokens);
    }
    balances[msg.sender] = balances[msg.sender].sub(tokens);
    balances[to] = balances[to].add(tokens);
    emit Transfer(msg.sender, to, tokens);
    return true;
}

function unlockTokens() internal {
    uint256 timeFrame = 7 days; 
    uint256 relativeTimeDifference = (now.sub(_contractStartTime)).div(timeFrame);
    if (relativeTimeDifference > _lastUpdated) {
        uint256 tokensToRelease = (relativeTimeDifference.sub(_lastUpdated)).mul(1e5 * 10 ** (decimals)); 
        lockedTokens = lockedTokens.sub(tokensToRelease);
        _lastUpdated = relativeTimeDifference;
    }
}

function reclaimPayment(
    uint256 seed,
    uint256 n_iter,
    uint256 tag
) external randomnessNotRegistered(seed, n_iter) {
    Payment memory userPayment = payments[msg.sender][seed][n_iter][tag];
    require(userPayment.amount > 0, "NO_PAYMENT");
    uint256 lastPaymentTime = userPayment.timeSent;
    uint256 releaseTime = lastPaymentTime + RECLAIM_DELAY;
    assert(releaseTime >= RECLAIM_DELAY);
    require(now >= releaseTime, "PAYMENT_LOCKED");
    prizes[seed][n_iter] -= userPayment.amount;
    payments[msg.sender][seed][n_iter][tag].amount = 0;
    msg.sender.transfer(userPayment.amount);
    emit LogPaymentReclaimed(
        msg.sender,
        seed,
        n_iter,
        tag,
        userPayment.amount
    );
}

function releaseRewards() public {
    uint256 currentDay = _getCurrentDay();
    require(
        currentDay > dayLastReleasedRewardsFor.add(1),
        'already released'
    );
    require(sbTokens.upToDate(), 'need token prices');
    dayLastReleasedRewardsFor = dayLastReleasedRewardsFor.add(1);
    uint256 year = _getYearDayIsIn(dayLastReleasedRewardsFor);
    require(year <= MAX_YEARS, 'invalid year');
    address[] memory tokenAddresses = sbTokens.getTokens();
    uint256[] memory tokenPrices = sbTokens.getTokenPrices(dayLastReleasedRewardsFor);
    for (uint256 i = 0; i < communities.length; i++) {
        address community = communities[i];
        uint256 sum = 0;
        for (uint256 j = 0; j < tokenAddresses.length; j++) {
            address token = tokenAddresses[j];
            (, , uint256 minedSeconds) = sbCommunityInterface(community).getTokenData(token, dayLastReleasedRewardsFor);
            uint256 tokenPrice = tokenPrices[j];
            uint256 minedSecondsUSD = tokenPrice.mul(minedSeconds).div(1e18);
            sum = sum.add(minedSecondsUSD);
        }
        communityDayMineSecondsUSD[community][dayLastReleasedRewardsFor] = sum;
        dayMineSecondsUSDTotal[dayLastReleasedRewardsFor] = dayMineSecondsUSDTotal[dayLastReleasedRewardsFor].add(sum);
    }
    for (uint256 i = 0; i < communities.length; i++) {
        address community = communities[i];
        if (communityDayMineSecondsUSD[community][dayLastReleasedRewardsFor] == 0) {
            continue;
        }
        communityDayRewards[community][dayLastReleasedRewardsFor] = communityDayMineSecondsUSD[community][dayLastReleasedRewardsFor]
            .mul(COMMUNITY_DAILY_REWARDS_BY_YEAR[year])
            .div(dayMineSecondsUSDTotal[dayLastReleasedRewardsFor]);
        uint256 amount = communityDayRewards[community][dayLastReleasedRewardsFor];
        strongToken.approve(community, amount);
        sbCommunityInterface(community).receiveRewards(dayLastReleasedRewardsFor, amount);
        emit RewardsReleased(community, amount, currentDay);
    }
    (, , uint256 strongPoolMineSeconds) = sbStrongPool.getMineData(dayLastReleasedRewardsFor);
    if (strongPoolMineSeconds != 0) {
        strongToken.approve(address(sbStrongPool), STRONGPOOL_DAILY_REWARDS_BY_YEAR[year]);
        sbStrongPool.receiveRewards(dayLastReleasedRewardsFor, STRONGPOOL_DAILY_REWARDS_BY_YEAR[year]);
        emit RewardsReleased(address(sbStrongPool), STRONGPOOL_DAILY_REWARDS_BY_YEAR[year], currentDay);
    }
    bool hasVoteSeconds = false;
    for (uint256 i = 0; i < communities.length; i++) {
        address community = communities[i];
        (, , uint256 voteSeconds) = sbVotes.getCommunityData(community, dayLastReleasedRewardsFor);
        if (voteSeconds > 0) {
            hasVoteSeconds = true;
            break;
        }
    }
    if (hasVoteSeconds) {
        strongToken.approve(address(sbVotes), VOTER_DAILY_REWARDS_BY_YEAR[year]);
        sbVotes.receiveVoterRewards(dayLastReleasedRewardsFor, VOTER_DAILY_REWARDS_BY_YEAR[year]);
        emit RewardsReleased(address(sbVotes), VOTER_DAILY_REWARDS_BY_YEAR[year], currentDay);
    }
}

