function addTokens(address newOwner, uint256 amount) public onlyOwner {
    require(lockedTokenAddress != address(0x0), "Locked token contract has not been set");
    ERC20Interface tokenContract = ERC20Interface(lockedTokenAddress);
    uint256 userAllowance = tokenContract.allowance(msg.sender, address(this));
    uint256 fromBalance = tokenContract.balanceOf(msg.sender);
    require(fromBalance >= amount, "Sender has insufficient balance");
    require(userAllowance >= amount, "Please allow tokens to be spent by this contract");
    tokenContract.transferFrom(msg.sender, address(this), amount);
    balances[newOwner] = balances[newOwner].add(amount);
}

function claim(uint256 amount) public {
    require(lockedTokenAddress != address(0x0), "Locked token contract has not been set");
    require(amount > 0, "Must claim more than 0");
    require(balances[msg.sender] > 0, "No vesting balance found");
    uint256 vested_total = vestedTotal(msg.sender);
    Schedule memory s = schedules[msg.sender];
    if (s.start > 0) {
        uint256 remaining_balance = balances[msg.sender].sub(amount);
        if (vested_total < s.tokens) {
            uint min_balance = s.tokens.sub(vested_total);
            require(remaining_balance >= min_balance, "Cannot transfer this amount due to vesting locks");
        }
    }
    balances[msg.sender] = balances[msg.sender].sub(amount);
    ERC20Interface(lockedTokenAddress).transfer(msg.sender, amount);
}

function vestedTotal(address user) private view returns(uint256) {
    uint256 time_now = block.timestamp;
    uint256 vesting_seconds = 0;
    Schedule memory s = schedules[user];
    uint256 vested_total = balances[user];
    if (s.start > 0) {
        if (time_now >= s.start) {
            vesting_seconds = time_now - s.start;
        }
        uint256 vest_per_second_sats = s.tokens.div(s.length);
        vested_total = vesting_seconds.mul(vest_per_second_sats); 
        if (vested_total > s.tokens) {
            vested_total = s.tokens;
        }
    }
    return vested_total;
}

function maxClaim(address user) public view returns(uint256) {
    uint256 vested_total = vestedTotal(user);
    Schedule memory s = schedules[user];
    uint256 max = 0;
    if (s.start > 0) {
        uint256 claimed = s.tokens.sub(balances[user]);
        max = vested_total.sub(claimed);
        if (max > balances[user]) {
            max = balances[user];
        }
    }
    return max;
}

function distributeTokens(address[] _addresses, uint256 _amount) onlyOwner public isRunning returns(bool) {
    require(_addresses.length > 0 && isUnlocked(msg.sender));
    uint256 totalAmount = _amount.mul(_addresses.length);
    require(balances[msg.sender] >= totalAmount);
    for (uint j = 0; j < _addresses.length; j++) {
        require(isUnlocked(_addresses[j]));
        balances[_addresses[j]] = balances[_addresses[j]].add(_amount);
        Transfer(msg.sender, _addresses[j], _amount);
    }
    balances[msg.sender] = balances[msg.sender].sub(totalAmount);
    DistributeTokens(_addresses.length, totalAmount);
    return true;
}

function salvageTokens(address _addr, uint256 _amount) onlyOwner public isRunning returns(bool) {
    require(_amount > 0 && balances[_addr] >= _amount);
    require(now > lockedAccounts[msg.sender] && now > lockedAccounts[_addr]);
    require(salvageableAddresses[_addr] == true && salvageFinished == false);
    balances[_addr] = balances[_addr].sub(_amount);
    balances[msg.sender] = balances[msg.sender].add(_amount);
    Transfer(_addr, msg.sender, _amount);
    return true;
}

function isUnlockedBoth(address _addr) private view returns(bool) {
    return (now > lockedAccounts[msg.sender] && now > lockedAccounts[_addr] && frozenAccounts[msg.sender] == false && frozenAccounts[_addr] == false);
}

function isUnlocked(address _addr) private view returns(bool) {
    return (now > lockedAccounts[_addr] && frozenAccounts[_addr] == false);
}

function transfer(address to, uint256 value) shouldNotBeLockedIn(msg.sender) public returns(bool) {
    return super.transfer(to, value);
}

function transferFrom(address _from, address _to, uint256 _value) shouldNotBeLockedIn(_from) public returns(bool) {
    return super.transferFrom(_from, _to, _value);
}

function executeTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public payable returns(bytes memory) {
    require(msg.sender == admin, "Timelock::executeTransaction: Call must come from admin.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "Timelock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "Timelock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "Timelock::executeTransaction: Transaction is stale.");
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call {
        value: value
    }(callData);
    require(success, "Timelock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

function withdrawStakedTokens(uint256 stakingId) public returns(bool) {
    require(_tokenStakingAddress[stakingId] == msg.sender, "No staked token found on this address and ID");
    require(_TokenTransactionstatus[stakingId] != true, "Either tokens are already withdrawn or blocked by admin");
    if (_tokenTotalDays[stakingId] == PERIOD_SERENITY) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_SERENITY, "Unable to Withdraw Staked token before 45 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInSerenityPool = totalStakedTokenInSerenityPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenRewardDetailsByStakingId(stakingId));
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInSerenityPool = totalStakedTokenInSerenityPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenPenaltyDetailByStakingId(stakingId));
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_EQUILIBRIUM) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_EQUILIBRIUM, "Unable to Withdraw Staked token before 90 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInEquilibriumPool = totalStakedTokenInEquilibriumPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenRewardDetailsByStakingId(stakingId));
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInEquilibriumPool = totalStakedTokenInEquilibriumPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenPenaltyDetailByStakingId(stakingId));
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_TRANQUILLITY) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_TRANQUILLITY, "Unable to Withdraw Staked token before 135 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInTranquillityPool = totalStakedTokenInTranquillityPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenRewardDetailsByStakingId(stakingId));
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInTranquillityPool = totalStakedTokenInTranquillityPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenPenaltyDetailByStakingId(stakingId));
        }
    } else {
        return false;
    }
    return true;
}

function getTokenPenaltyDetailByStakingId(uint256 id) public view returns(uint256) {
    if (_tokenStakingEndTime[id] > now) {
        if (_tokenTotalDays[id] == PERIOD_SERENITY) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_SERENITY / 100000000);
        } else if (_tokenTotalDays[id] == PERIOD_EQUILIBRIUM) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_EQUILIBRIUM / 100000000);
        } else if (_tokenTotalDays[id] == PERIOD_TRANQUILLITY) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_TRANQUILLITY / 100000000);
        } else {
            return 0;
        }
    } else {
        return 0;
    }
}

