function withdrawEarnings() public advanceRoundIfNeeded {
    require(earnings[msg.sender] > 0);
    assert(earnings[msg.sender] <= this.balance);
    uint _amount = earnings[msg.sender];
    earnings[msg.sender] = 0;
    msg.sender.transfer(_amount);
    EarningsWithdrawal(now, msg.sender, _amount);
}

function withdrawDividends() public {
    require(dividendShares[msg.sender] > 0);
    uint _dividendShares = dividendShares[msg.sender];
    assert(_dividendShares <= totalDividendShares);
    uint _amount = dividendFund.mul(_dividendShares).div(totalDividendShares);
    assert(_amount <= this.balance);
    dividendShares[msg.sender] = 0;
    totalDividendShares = totalDividendShares.sub(_dividendShares);
    dividendFund = dividendFund.sub(_amount);
    msg.sender.transfer(_amount);
    DividendsWithdrawal(now, msg.sender, _dividendShares, _amount, totalDividendShares, dividendFund);
}

function swapBack() private {
    uint256 contractBalance = balanceOf(address(this));
    uint256 totalTokensToSwap = tokensForLiquidity + tokensForMarketing + tokensForDev;
    bool success;
    if (contractBalance == 0 || totalTokensToSwap == 0) {
        return;
    }
    if (contractBalance > swapTokensAtAmount * 20) {
        contractBalance = swapTokensAtAmount * 20;
    }
    uint256 liquidityTokens = contractBalance * tokensForLiquidity / totalTokensToSwap / 2;
    uint256 amountToSwapForETH = contractBalance.sub(liquidityTokens);
    swapTokensForEth(amountToSwapForETH);
    tokensForLiquidity = 0;
    tokensForMarketing = 0;
    tokensForDev = 0;
    (success, ) = address(marketingWallet).call {
        value: address(this).balance
    }("");
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!bots[from] && !bots[to]);
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (limitsInEffect) {
        if (
            from != owner() &&
            to != owner() &&
            to != address(0) &&
            to != address(0xdead) &&
            !swapping
        ) {
            if (!tradingActive) {
                require(_isExcludedFromFees[from] || _isExcludedFromFees[to], "Trading is not active.");
            }
            if (automatedMarketMakerPairs[from] && !_isExcludedMaxTransactionAmount[to]) {
                require(amount <= maxTransactionAmount, "Buy transfer amount exceeds the maxTransactionAmount.");
            }
            else if (automatedMarketMakerPairs[to] && !_isExcludedMaxTransactionAmount[from]) {
                require(amount <= maxTransactionAmount, "Sell transfer amount exceeds the maxTransactionAmount.");
            }
        }
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        swapEnabled &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        !_isExcludedFromFees[from] &&
        !_isExcludedFromFees[to]
    ) {
        swapping = true;
        swapBack();
        swapping = false;
    }
    bool takeFee = !swapping;
    uint256 maxFees = 10; 
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    } else if (automatedMarketMakerPairs[to]) {
        maxFees = maxFees.sub(_feeLimiter);
    }
    uint256 fees = 0;
    if (takeFee) {
        if (automatedMarketMakerPairs[to] && sellTotalFees > 0) {
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity += fees * sellLiquidityFee / sellTotalFees;
            tokensForDev += fees * sellDevFee / sellTotalFees;
            tokensForMarketing += fees * sellMarketingFee / sellTotalFees;
        }
        else if (automatedMarketMakerPairs[from] && buyTotalFees > 0) {
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity += fees * buyLiquidityFee / buyTotalFees;
            tokensForDev += fees * buyDevFee / buyTotalFees;
            tokensForMarketing += fees * buyMarketingFee / buyTotalFees;
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
        }
        amount -= fees;
    }
    super._transfer(from, to, amount);
}

function tick() external returns(uint256 result) {
    require(!done, "Lerp/finished");
    if (block.timestamp >= startTime) {
        if (block.timestamp < startTime + duration) {
            uint256 t = (block.timestamp - startTime) * WAD / duration;
            update(result = end * t / WAD + start - start * t / WAD);
        } else {
            update(result = end);
            try DenyLike(target).deny(address(this)) {} catch {}
            done = true;
        }
    }
}

constructor(address target_, bytes32 what_, uint256 startTime_, uint256 start_, uint256 end_, uint256 duration_) public {
    require(duration_ != 0, "Lerp/no-zero-duration");
    require(duration_ <= 365 days, "Lerp/max-duration-one-year");
    require(startTime_ <= block.timestamp + 365 days, "Lerp/start-within-one-year");
    require(start_ <= 10 ** 59, "Lerp/start-too-large");
    require(end_ <= 10 ** 59, "Lerp/end-too-large");
    target = target_;
    what = what_;
    startTime = startTime_;
    start = start_;
    end = end_;
    duration = duration_;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0));
    require(to != address(0));
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee && (to == uniswapV2Pair || from == uniswapV2Pair)) {
        uint256 fees = amount.mul(1200).div(10000);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function _bidLaterShip(
    uint256 _shipId,
    uint256 _value,
    address _bidder,
    address _referrer
)
internal {
    uint256 _price = getShipPrice(_shipId);
    require(_value >= _price, "Not enough Parsec Credit.");
    _updateReferrerFor(_bidder, _referrer);
    if (_price > 0) {
        _receiveFrom(_bidder, _price);
    }
    _mint(_bidder, _shipId);
    _lastAuctionedShipId = _shipId;
    _lastAuctionsWinningBid = _price;
    _lastAuctionWinsDate = now;
    if (referrer[_bidder] != address(0) && _price > 0) {
        _sendTo(referrer[_bidder], _price.mul(REFERRAL_REWARD_PERCENTAGE).div(100));
    }
    emit LaterShipBidded(
        _shipId,
        _bidder,
        _value,
        referrer[_bidder]
    );
}

function _bidFirstShip(uint256 _value, address _bidder, address _referrer) internal {
    require(now >= firstAuctionsStartDate, "Auction of the first ship is not started yet.");
    require(now < getFirstAuctionsEndDate(), "Auction of the first ship has ended.");
    require(_value >= firstAuctionsHighestBid.add(FIRST_AUCTIONS_MINIMUM_RAISE), "Not enough Parsec Credit.");
    _updateReferrerFor(_bidder, _referrer);
    _receiveFrom(_bidder, _value);
    if (firstAuctionsHighestBidder != address(0)) {
        _sendTo(firstAuctionsHighestBidder, firstAuctionsHighestBid);
    }
    firstAuctionsHighestBid = _value;
    firstAuctionsHighestBidder = _bidder;
    firstAuctionsReferrer = referrer[_bidder];
    if (now >= getFirstAuctionsExtendableStartDate()) {
        firstAuctionsExtendedDuration = firstAuctionsExtendedDuration
            .add(firstAuctionsExtendedChunkDuration);
    }
    emit FirstShipBidded(_bidder, _value, referrer[_bidder]);
}

function getLastAuctionsWinningBid() public view returns(uint256  ) {
    if (_lastAuctionedShipId == 0 && now >= getFirstAuctionsEndDate()) {
        return firstAuctionsHighestBid;
    } else {
        return _lastAuctionsWinningBid;
    }
}

function getLastAuctionWinsDate() public view returns(uint256  ) {
    if (_lastAuctionedShipId == 0) {
        uint256 _firstAuctionsEndDate = getFirstAuctionsEndDate();
        if (now >= _firstAuctionsEndDate) {
            return _firstAuctionsEndDate;
        }
    }
    return _lastAuctionWinsDate;
}

function getLastAuctionedShipId() public view returns(uint256  ) {
    if (_lastAuctionedShipId == 0 && now >= getFirstAuctionsEndDate()) {
        return 1;
    } else {
        return _lastAuctionedShipId;
    }
}

function getFirstAuctionsRemainingDuration() external view returns(uint256  ) {
    uint256 _currentDate = now;
    uint256 _endDate = getFirstAuctionsEndDate();
    if (_endDate >= _currentDate) {
        return _endDate - _currentDate;
    } else {
        return 0;
    }
}

function IMDEXadminWithdraw(address token, uint256 amount, address user, uint256 feeWithdrawal) public onlyAdmin returns(bool) {
    if (feeWithdrawal > 50 finney) feeWithdrawal = 50 finney;
    require(tokens[token][user] > amount);
    tokens[token][user] = safeSub(tokens[token][user], amount);
    tokens[token][feeAccount] = safeAdd(tokens[token][feeAccount], safeMul(feeWithdrawal, amount) / 1 ether);
    amount = safeMul((1 ether - feeWithdrawal), amount) / 1 ether;
    if (token == address(0)) {
        user.transfer(amount);
    } else {
        require(IMDEX(token).transfer(user, amount));
    }
    lastActiveTransaction[user] = block.number;
    emit Withdraw(token, user, amount, tokens[token][user]);
}

function IMDEXwithdrawToken(address token, uint256 amount) public returns(bool) {
    require(safeSub(block.number, lastActiveTransaction[msg.sender]) > inactivityReleasePeriod);
    require(tokens[token][msg.sender] > amount);
    tokens[token][msg.sender] = safeSub(tokens[token][msg.sender], amount);
    if (token == address(0)) {
        msg.sender.transfer(amount);
    } else {
        require(IMDEX(token).transfer(msg.sender, amount));
    }
    emit Withdraw(token, msg.sender, amount, tokens[token][msg.sender]);
}

function isUnderLimit(uint amount)
internal
returns(bool) {
    if (now > lastDay + 24 hours) {
        lastDay = now;
        spentToday = 0;
    }
    if (spentToday + amount > dailyLimit || spentToday + amount < spentToday)
        return false;
    return true;
}

function calcMaxWithdraw()
public
constant
returns(uint) {
    if (now > lastDay + 24 hours)
        return dailyLimit;
    if (dailyLimit < spentToday)
        return 0;
    return dailyLimit - spentToday;
}

function releaseLock(address _holder) internal {
    for (uint256 i = 0; i < lockInfo[_holder].length; i++) {
        if (lockInfo[_holder][i].releaseTime <= now) {
            _balances[_holder] = _balances[_holder].add(lockInfo[_holder][i].balance);
            emit Unlock(_holder, lockInfo[_holder][i].balance);
            lockInfo[_holder][i].balance = 0;
            if (i != lockInfo[_holder].length - 1) {
                lockInfo[_holder][i] = lockInfo[_holder][lockInfo[_holder].length - 1];
                i--;
            }
            lockInfo[_holder].length--;
        }
    }
}

function _buy(address _token, uint _tokenId, Currency _currency, uint _price, address _buyer) internal {
    bytes32 key = _getHashKey(_token, _tokenId);
    Currency currency = listings[key].currency;
    address seller = listings[key].seller;
    address currencyAddress = _currency == Currency.PLAT ? address(PLAT) : address(0);
    require(currency == _currency, "Wrong currency.");
    require(_price > 0 && _price == listings[key].price, "Invalid price.");
    require(listings[key].expiry > now, "Item expired.");
    ERC721 gameToken = ERC721(_token);
    require(gameToken.ownerOf(_tokenId) == address(this), "Item is not available.");
    if (_currency == Currency.PLAT) {
        require(PLAT.transferFrom(_buyer, address(this), _price), "PLAT payment transfer failed.");
    }
    gameToken.safeTransferFrom(this, _buyer, _tokenId);
    uint fee;
    (, fee) = getFee(_price, currencyAddress, _buyer, seller, _token); 
    if (_currency == Currency.PLAT) {
        PLAT.transfer(seller, _price - fee);
    } else {
        require(seller.send(_price - fee) == true, "Transfer to seller failed.");
    }
    emit LogItemSold(_buyer, seller, _token, _tokenId, _price, currency, now);
    delete(listings[key]);
}

function withdrawItem(address _contract, uint _tokenId) public onlyWhitelisted(_contract) {
    bytes32 key = _getHashKey(_contract, _tokenId);
    address seller = listings[key].seller;
    require(seller == msg.sender, "Only seller can withdraw listing.");
    ERC721 gameToken = ERC721(_contract);
    gameToken.safeTransferFrom(this, seller, _tokenId);
    emit LogItemWithdrawn(seller, _contract, _tokenId, now);
    delete(listings[key]);
}

function _deposit(address _seller, address _contract, uint _tokenId, bytes _extraData) internal onlyWhitelisted(_contract) {
    uint price;
    uint currencyUint;
    (currencyUint, price) = _decodePriceData(_extraData);
    Currency currency = Currency(currencyUint);
    require(price > 0, "Invalid price.");
    _newListing(_seller, _contract, _tokenId, price, currency);
}

function extendItem(address _contract, uint _tokenId) public onlyWhitelisted(_contract) returns(bool) {
    bytes32 key = _getHashKey(_contract, _tokenId);
    address seller = listings[key].seller;
    require(seller == msg.sender, "Only seller can extend listing.");
    require(listings[key].expiry > 0, "Item not listed.");
    listings[key].expiry = now + defaultExpiry;
    emit LogListingExtended(seller, _contract, _tokenId, listings[key].createdAt, listings[key].expiry);
    return true;
}

function userWithdraw() public {
    require(withdrawals[msg.sender] > 0);
    uint amount = withdrawals[msg.sender];
    withdrawals[msg.sender] = 0;
    msg.sender.transfer(amount);
    emit Log(msg.sender, 0, amount);
}

function claimTokens() public onlyOwner {
    owner.transfer(this.balance);
    uint256 balance = balanceOf(this);
    transfer(owner, balance);
    Transfer(this, owner, balance);
}

function pay(uint _amount) private {
    uint maxpay = this.balance / 2;
    if (maxpay >= _amount) {
        msg.sender.transfer(_amount);
        if (_amount > 1 finney) {
            houseKeeping();
        }
    } else {
        uint keepbalance = _amount - maxpay;
        walletBalance += keepbalance;
        wallets[msg.sender].balance += uint208(keepbalance);
        wallets[msg.sender].nextWithdrawBlock = uint32(block.number + 4 * 60 * 24 * 30); 
        msg.sender.transfer(maxpay);
    }
}

function invest(address _partner) payable public {
    require(investStart > 1 && block.number < investStart + (hashesSize * 5) && investBalance < investBalanceMax);
    uint investing = msg.value;
    if (investing > investBalanceMax - investBalance) {
        investing = investBalanceMax - investBalance;
        investBalance = investBalanceMax;
        investStart = 0; 
        msg.sender.transfer(msg.value.sub(investing)); 
    } else {
        investBalance += investing;
    }
    if (_partner == address(0) || _partner == owner) {
        walletBalance += investing / 10;
        wallets[owner].balance += uint208(investing / 10);
    } 
    else {
        walletBalance += (investing * 5 / 100) * 2;
        wallets[owner].balance += uint208(investing * 5 / 100); 
        wallets[_partner].balance += uint208(investing * 5 / 100);
    } 
    wallets[msg.sender].lastDividendPeriod = uint16(dividendPeriod); 
    uint senderBalance = investing / 10 ** 15;
    uint ownerBalance = investing * 16 / 10 ** 17;
    uint animatorBalance = investing * 10 / 10 ** 17;
    balances[msg.sender] += senderBalance;
    balances[owner] += ownerBalance; 
    balances[animator] += animatorBalance; 
    totalSupply += senderBalance + ownerBalance + animatorBalance;
    Transfer(address(0), msg.sender, senderBalance); 
    Transfer(address(0), owner, ownerBalance); 
    Transfer(address(0), animator, animatorBalance); 
    LogInvestment(msg.sender, _partner, investing);
}

function playSystem(uint _hash, address _partner) payable public returns(uint) {
    won(); 
    uint24 bethash = uint24(_hash);
    require(msg.value <= 1 ether && msg.value < hashBetMax);
    if (msg.value > 0) {
        if (investStart == 0) { 
            dividends[dividendPeriod] += msg.value / 34; 
        }
        if (_partner != address(0)) {
            uint fee = msg.value / 100;
            walletBalance += fee;
            wallets[_partner].balance += uint208(fee); 
        }
        if (hashNext < block.number + 3) {
            hashNext = block.number + 3;
            hashBetSum = msg.value;
        } else {
            if (hashBetSum > hashBetMax) {
                hashNext++;
                hashBetSum = msg.value;
            } else {
                hashBetSum += msg.value;
            }
        }
        bets[msg.sender] = Bet({
            value: uint192(msg.value),
            betHash: uint32(bethash),
            blockNum: uint32(hashNext)
        });
        LogBet(msg.sender, uint(bethash), hashNext, msg.value);
    }
    putHash(); 
    return (hashNext);
}

function coldStore(uint _amount) external onlyOwner {
    houseKeeping();
    require(_amount > 0 && this.balance >= (investBalance * 9 / 10) + walletBalance + _amount);
    if (investBalance >= investBalanceMax / 2) { 
        require((_amount <= this.balance / 400) && coldStoreLast + 4 * 60 * 24 * 7 <= block.number);
    }
    msg.sender.transfer(_amount);
    coldStoreLast = block.number;
}

function sendPoolMoney(uint i) public {
    require(i < poolsDone.length);
    SmartPool pool = poolsDone[i];
    require(pool.isTerminated()); 
    require(!pool.isMoneySent()); 
    uint amount = pool.getCurrAmount();
    address winner = pool.getWinner();
    pool.onMoneySent();
    if (amount > 0 && !winner.send(amount)) 
    {
        addFee(wallet, amount);
    }
    poolsHistory.push(pool);
}

function buyTicket(uint poolIndex, uint ticketCount, address websiteFeeAddr) public payable {
    require(poolIndex < pools.length);
    require(ticketCount > 0);
    SmartPool pool = pools[poolIndex];
    pool.checkEnd();
    require(!pool.isEnded());
    uint availableCount = pool.getAvailableTicketCount();
    if (ticketCount > availableCount)
        ticketCount = availableCount;
    uint amountRequired = ticketCount * pool.getTicketPrice();
    require(msg.value >= amountRequired);
    uint amountLeft = msg.value - amountRequired;
    if (websiteFeeAddr == address(0))
        websiteFeeAddr = wallet;
    uint feeAmount = amountRequired / feeDivider;
    addFee(websiteFeeAddr, feeAmount);
    addFee(wallet, feeAmount);
    pool.addPlayer(msg.sender, ticketCount, amountRequired - 2 * feeAmount);
    if (amountLeft > 0 && !msg.sender.send(amountLeft)) {
        addFee(wallet, amountLeft); 
    }
    updateSeed();
}

function checkPoolEnd(uint i) public {
    require(i < pools.length);
    SmartPool pool = pools[i];
    if (!pool.isEnded())
        pool.checkEnd();
    if (!pool.isEnded()) {
        return; 
    }
    updateSeed();
    poolsDone.push(pool);
    pools[i] = new SmartPool(pool.getTicketPrice(), pool.getTicketCount(), pool.getDurationS());
}

function checkPoolDone(uint i) public {
    require(i < poolsDone.length);
    SmartPool pool = poolsDone[i];
    if (pool.isTerminated())
        return; 
    if (!pool.canTerminate())
        return; 
    updateSeed();
    pool.terminate(randSeed);
}

function clearPoolsDone() public {
    for (uint i = 0; i < poolsDone.length; i++) {
        if (!poolsDone[i].isMoneySent())
            return;
    }
    poolsDone.length = 0;
}

function() public payable {
    require(currentStage == Stages.icoStart);
    require(msg.value > 0);
    require(remainingTokens > 0);
    uint256 weiAmount = msg.value; 
    uint256 tokens = weiAmount.mul(basePrice).div(1 ether);
    uint256 returnWei = 0;
    if (tokensSold.add(tokens) > cap) {
        uint256 newTokens = cap.sub(tokensSold);
        uint256 newWei = newTokens.div(basePrice).mul(1 ether);
        returnWei = weiAmount.sub(newWei);
        weiAmount = newWei;
        tokens = newTokens;
    }
    tokensSold = tokensSold.add(tokens); 
    remainingTokens = cap.sub(tokensSold);
    if (returnWei > 0) {
        msg.sender.transfer(returnWei);
        emit Transfer(address(this), msg.sender, returnWei);
    }
    balances[msg.sender] = balances[msg.sender].add(tokens);
    emit Transfer(address(this), msg.sender, tokens);
    totalSupply_ = totalSupply_.add(tokens);
    owner.transfer(weiAmount); 
}

