function transferFrom(
    address _from,
    address _to,
    uint256 _value
) public returns(bool) {
    addressValidator().validateIllegalAddress(_from);
    addressValidator().validateIllegalAddress(_to);
    require(_value != 0, "illegal transfer value");
    IAllocator(config().allocator()).beforeBalanceChange(
        address(this),
        _from,
        _to
    );
    _transfer(_from, _to, _value);
    uint256 allowanceAmount = allowance(_from, msg.sender);
    _approve(
        _from,
        msg.sender,
        allowanceAmount.sub(
            _value,
            "ERC20: transfer amount exceeds allowance"
        )
    );
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    addressValidator().validateIllegalAddress(_to);
    require(_value != 0, "illegal transfer value");
    IAllocator(config().allocator()).beforeBalanceChange(
        address(this),
        msg.sender,
        _to
    );
    _transfer(msg.sender, _to, _value);
    return true;
}

function applyVoteOutVotesFor(address subject, uint256 voteOutStakeAdded, uint256 voteOutStakeRemoved, uint256 totalDelegatedStake, Settings memory _settings) private {
    if (isVotedOut(subject)) {
        return;
    }
    uint256 accumulated = accumulatedStakesForVoteOut[subject].
    sub(voteOutStakeRemoved).
    add(voteOutStakeAdded);
    bool shouldBeVotedOut = totalDelegatedStake > 0 && accumulated.mul(PERCENT_MILLIE_BASE) >= uint256(_settings.voteOutPercentMilleThreshold).mul(totalDelegatedStake);
    if (shouldBeVotedOut) {
        votedOutGuardians[subject] = true;
        emit GuardianVotedOut(subject);
        emit GuardianStatusUpdated(subject, false, false);
        committeeContract.removeMember(subject);
    }
    accumulatedStakesForVoteOut[subject] = accumulated;
}

function() public payable {
    uint256 eth_balance = this.balance;
    uint256 chi_balance = Chi.balanceOf(this);
    if (msg.sender == seller) {
        seller = 0x0; 
        price = 0; 
        Chi_available = 0; 
        Amount_of_Chi_for_One_ETH = 0; 
        cooldown_start_time = now; 
        if (eth_balance > 0) msg.sender.transfer(eth_balance); 
        if (chi_balance > 0) require(Chi.transfer(msg.sender, chi_balance)); 
    } else {
        require(msg.value > 0); 
        require(price > 0); 
        uint256 num_chi = msg.value / price; 
        require(chi_balance >= num_chi); 
        Chi_available = chi_balance - num_chi; 
        require(Chi.transfer(msg.sender, num_chi)); 
    }
}

function setup(uint256 chi_amount, uint256 price_in_wei) public {
    require(is_empty()); 
    require(Chi.allowance(msg.sender, this) >= chi_amount); 
    require(price_in_wei > 1000); 
    price = price_in_wei;
    Chi_available = chi_amount;
    Amount_of_Chi_for_One_ETH = 1 ether / price_in_wei;
    seller = msg.sender;
    require(Chi.transferFrom(msg.sender, this, chi_amount)); 
}

function is_empty() public view returns(bool) {
    return (now - cooldown_start_time > 1 hours) && (this.balance == 0) && (Chi.balanceOf(this) == 0);
}

function preICOBuy() internal notHalted returns(bool success) {
    uint256 weisSentScaled = msg.value.mul(DECIMAL_MULTIPLIER);
    address _for = msg.sender;
    var (tokensBought, fundsLeftScaled) = calculateAmountBoughtPreICO(weisSentScaled);
    if (tokensBought < minTokensToBuy.mul(DECIMAL_MULTIPLIER)) {
        revert();
    }
    uint256 fundsLeft = fundsLeftScaled.div(DECIMAL_MULTIPLIER);
    uint256 totalSpent = msg.value.sub(fundsLeft);
    if (balanceOf(_for) == 0) {
        preICOcontributors = preICOcontributors + 1;
    }
    managedTokenLedger.mint(_for, tokensBought);
    balancesForPreICO[_for] = balancesForPreICO[_for].add(tokensBought);
    weiForRefundPreICO[_for] = weiForRefundPreICO[_for].add(totalSpent);
    weiToRecoverPreICO[_for] = weiToRecoverPreICO[_for].add(fundsLeft);
    Purchased(_for, tokensBought);
    preICOcollected = preICOcollected.add(totalSpent);
    totalSupply = totalSupply.add(tokensBought);
    preICOtokensSold = preICOtokensSold.add(tokensBought);
    return true;
}

function setLedger(address _newLedgerAddress) onlyOwner public returns(bool success) {
    require(_newLedgerAddress != address(0));
    managedTokenLedger = ManagedToken(_newLedgerAddress);
    decimals = managedTokenLedger.decimals();
    DECIMAL_MULTIPLIER = 10 ** uint256(decimals);
    return true;
}

function transitionState() internal {
    if (now >= preICOstart) {
        if (preICOstate == ICOStateEnum.NotStarted) {
            preICOstate = ICOStateEnum.Started;
        }
        if (preICOcap > 0 && preICOcollected >= preICOcap) {
            preICOstate = ICOStateEnum.Successful;
        }
        if (preICOtokensSold == totalPreICOavailible) {
            preICOstate = ICOStateEnum.Successful;
        }
    }
    if (now >= preICOend) {
        if (preICOstate == ICOStateEnum.Started) {
            if (preICOcollected >= preICOgoal) {
                preICOstate = ICOStateEnum.Successful;
            } else {
                preICOstate = ICOStateEnum.Refunded;
            }
        }
    }
}

function HardcodedCrowdsale(uint _preICOstart, uint _preICOend, uint _preICOgoal, uint _preICOcap, address _newLedgerAddress) public {
    require(_preICOstart > now);
    require(_preICOend > _preICOstart);
    require(_preICOgoal > 0);
    require(_newLedgerAddress != address(0));
    preICOstart = _preICOstart;
    preICOend = _preICOend;
    preICOgoal = _preICOgoal;
    preICOcap = _preICOcap;
    managedTokenLedger = ManagedToken(_newLedgerAddress);
    decimals = managedTokenLedger.decimals();
    DECIMAL_MULTIPLIER = 10 ** uint256(decimals);
}

