    uint256 rma = _tokens.mul(10 ** uint256(decimals));
    require(rma > 1 * 10 ** uint256(decimals)); 
    require(ERC20(erushLPtoken).balanceOf(msg.sender) >= rma);
    require(fdetails[msg.sender]._amount == 0);
