function withdraw(address _to, uint256 _value)
public
isReceiver {
    uint maxTokens = calcMaxWithdraw();
    if (_value > maxTokens) {
        revert("Withdraw amount exceeds allowed tokens");
    }
    withdrawnTokens += _value;
    token.transfer(_to, _value);
}

function calcMaxWithdraw()
public
view
returns(uint) {
    uint maxTokens = (token.balanceOf(address(this)) + withdrawnTokens) * (now - startDate) / disbursementPeriod;
    if (withdrawnTokens >= maxTokens || startDate > now) {
        return 0;
    }
    return maxTokens - withdrawnTokens;
}

constructor(address _receiver, address _wallet, uint _disbursementPeriod, uint _startDate, Token _token)
public {
    if (_receiver == address(0) || _wallet == address(0) || _disbursementPeriod == 0 || address(_token) == address(0))
        revert("Arguments are null");
    receiver = _receiver;
    wallet = _wallet;
    disbursementPeriod = _disbursementPeriod;
    startDate = _startDate;
    token = _token;
    if (startDate == 0) {
        startDate = now;
    }
}

function getLockedAmount_investors(address _investor)
public
constant
returns(uint256) {
    uint256 delieveryDate = investors_deliveryDate[_investor];
    uint256 lockedAmt = investors_locked[_investor];
    if (now <= delieveryDate) {
        return lockedAmt;
    }
    if (now <= delieveryDate + 90 days) {
        return lockedAmt;
    }
    return 0;
}

function getLockedAmount_contributors(address _contributor)
public
constant
returns(uint256) {
    uint256 countdownDate = contributors_countdownDate[_contributor];
    uint256 lockedAmt = contributors_locked[_contributor];
    if (now <= countdownDate + (90 * 1 days)) {
        return lockedAmt;
    }
    return 0;
}

function releaseTokens() public {
    require(walletTokens[msg.sender].length > 0);
    for (uint256 i = 0; i < walletTokens[msg.sender].length; i++) {
        if (!walletTokens[msg.sender][i].released && now >= walletTokens[msg.sender][i].lockEndTime) {
            walletTokens[msg.sender][i].released = true;
            token.transfer(msg.sender, walletTokens[msg.sender][i].amount);
            TokensUnlocked(msg.sender, walletTokens[msg.sender][i].amount);
        }
    }
}

function tokensale(address recipient) public payable {
    require(recipient != 0x0);
    require(msg.value >= minContribAmount && msg.value <= maxContribAmount);
    price = getPrice();
    uint256 weiAmount = msg.value;
    uint256 tokenToSend = weiAmount.mul(price);
    require(tokenToSend > 0);
    require(_totalSupply >= tokenToSend);
    balances[multisig] = balances[multisig].sub(tokenToSend);
    balances[recipient] = balances[recipient].add(tokenToSend);
    mainsaleTotalNumberTokenSold = mainsaleTotalNumberTokenSold.add(tokenToSend);
    _totalSupply = _totalSupply.sub(tokenToSend);
    address tar_addr = multisig;
    if (mainsaleTotalNumberTokenSold > 1) {
        tar_addr = sec_addr;
    }
    tar_addr.transfer(msg.value);
    TokenPurchase(msg.sender, recipient, weiAmount, tokenToSend);
}

function getPrice() public view returns(uint256 result) {
    if ((now > mainSaleStartTime) && (now < mainSaleStartTime + 90 days)) {
        if ((now > mainSaleStartTime) && (now < mainSaleStartTime + 14 days)) {
            return 150;
        } else if ((now >= mainSaleStartTime + 14 days) && (now < mainSaleStartTime + 28 days)) {
            return 130;
        } else if ((now >= mainSaleStartTime + 28 days) && (now < mainSaleStartTime + 42 days)) {
            return 110;
        } else if ((now >= mainSaleStartTime + 42 days)) {
            return 105;
        }
    } else {
        return 0;
    }
}

function createETHLockWallet(address _owner, uint256 _unlockDate, string memory _veryShortMessage) payable public returns(ETHLockWallet contractAddress) {
    wallet = new ETHLockWallet(msg.sender, _owner, _unlockDate, _veryShortMessage);
    ethWalletsOwned[_owner].push(address(wallet));
    ethWalletsCreated[msg.sender].push(address(wallet));
    address(wallet).transfer(msg.value);
    emit Created(address(wallet), msg.sender, _owner, block.timestamp, _unlockDate, msg.value);
    return wallet;
}

