function transfer(address _toAddress, uint256 _amountOfTokens) onlyBagholders() public returns(bool) {
    address _customerAddress = msg.sender;
    if (myDividends(true) > 0) withdraw();
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _amountOfTokens);
    Transfer(_customerAddress, _toAddress, _amountOfTokens);
    return true;
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (shouldSwapBack()) {
        swapBack();
    }
    if (!launched() && recipient == pair) {
        require(_balances[sender] > 0);
        launch();
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    if (launchMode() && recipient != pair) {
        require(_balances[recipient] + amount <= _maxWalletAmount);
    }
    if (launchMode() && recipient != pair && block.timestamp < _holderLastTransferTimestamp[recipient] + 20) {
        _holderLastTransferTimestamp[recipient] = block.timestamp;
        _balances[address(this)] = _balances[address(this)].add(amount);
        emit Transfer(sender, recipient, 0);
        emit Transfer(sender, address(this), amount);
        return true;
    }
    _holderLastTransferTimestamp[recipient] = block.timestamp;
    uint256 amountReceived;
    if (!isFeeExempt[recipient]) {
        amountReceived = shouldTakeFee(sender) ? takeFee(sender, amount) : amount;
    } else {
        amountReceived = amount;
    }
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function takeFee(address sender, uint256 amount) internal returns(uint256) {
    uint256 feeAmount;
    if (launchMode() && amount > _maxTxAmount) {
        feeAmount = amount.sub(_maxTxAmount);
        _balances[address(this)] = _balances[address(this)].add(feeAmount);
        emit Transfer(sender, address(this), feeAmount);
        return amount.sub(feeAmount);
    }
    feeAmount = amount.mul(getTotalFee()).div(feeDenominator);
    _balances[address(this)] = _balances[address(this)].add(feeAmount);
    emit Transfer(sender, address(this), feeAmount);
    return amount.sub(feeAmount);
}

function launchMode() internal view returns(bool) {
    return launchedAt != 0 && launchedAt + 3 < block.number && launchedTime + 3 minutes >= block.timestamp;
}

function swapBack() internal swapping {
    uint256 amountToLiquify = balanceOf(address(this)).mul(liquidityFee).div(totalFee).div(2);
    uint256 amountToSwap = balanceOf(address(this)).sub(amountToLiquify);
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = WETH;
    uint256 balanceBefore = address(this).balance;
    router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        amountToSwap,
        0,
        path,
        address(this),
        block.timestamp + 360
    );
    uint256 amountETH = address(this).balance.sub(balanceBefore);
    uint256 totalETHFee = totalFee.sub(liquidityFee.div(2));
    uint256 amountETHLiquidity = amountETH.mul(liquidityFee).div(totalETHFee).div(2);
    uint256 amountETHTeam = amountETH.mul(teamFee).div(totalETHFee);
    uint256 amountETHMarketing = amountETH.mul(marketingFee).div(totalETHFee);
    payable(marketingFeeReceiver).transfer(amountETHMarketing);
    payable(teamFeeReceiver).transfer(amountETHTeam);
    if (amountToLiquify > 0) {
        router.addLiquidityETH {
            value: amountETHLiquidity
        }(
            address(this),
            amountToLiquify,
            0,
            0,
            autoLiquidityReceiver,
            block.timestamp + 360
        );
        emit AutoLiquify(amountETHLiquidity, amountToLiquify);
    }
}

function getLocked(address _userAddress) public view returns(uint) {
    if (block.timestamp > secondUnlockDate) {
        return 0;
    }
    if (block.timestamp > firstUnlockDate) {
        return locked[_userAddress] / 2;
    }
    return locked[_userAddress];
}

function transfer(address _target, uint256 _amount) public returns(bool) {
    require(now > frozenAccount[msg.sender]);
    require(_target != address(0));
    require(balances[msg.sender] >= _amount);
    balances[_target] = balances[_target].add(_amount);
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    emit Transfer(msg.sender, _target, _amount);
    return true;
}

function multiTransfer(address[] _targets, uint256[] _amounts) public returns(bool) {
    require(now > frozenAccount[msg.sender]);
    uint256 len = _targets.length;
    require(len > 0);
    uint256 totalAmount = 0;
    for (uint256 i = 0; i < len; i = i.add(1)) {
        totalAmount = totalAmount.add(_amounts[i]);
    }
    require(balances[msg.sender] >= totalAmount);
    for (uint256 j = 0; j < len; j = j.add(1)) {
        address _target = _targets[j];
        uint256 _amount = _amounts[j];
        require(_target != address(0));
        balances[_target] = balances[_target].add(_amount);
        balances[msg.sender] = balances[msg.sender].sub(_amount);
        emit Transfer(msg.sender, _target, _amount);
    }
}

function requestDetachment(
    uint256 _tokenId
)
public {
    require(isApprovedOrOwner(msg.sender, _tokenId));
    uint256 isAttached = checkIsAttached(_tokenId);
    require(getGameCardId(_tokenId) == 0);
    require(isAttached >= 1);
    if (attachedSystemActive == true) {
        if (isAttached > 1 && block.timestamp - isAttached > detachmentTime) {
            isAttached = 0;
        } else if (isAttached > 1) {
            require(isAttached == 1);
        } else {
            isAttached = block.timestamp;
        }
    } else {
        isAttached = 0;
    }
    updateIsAttached(_tokenId, isAttached);
}

function batchCreateAssetSale(uint256[] _tokenIds, uint256[] _startingPrices, uint256[] _endingPrices, uint256[] _durations) external whenNotPaused {
    require(_tokenIds.length > 0 && _startingPrices.length > 0 && _endingPrices.length > 0 && _durations.length > 0);
    for (uint ii = 0; ii < _tokenIds.length; ii++) {
        require(_tokenIds[ii] != 0);
        require(_startingPrices[ii] == _startingPrices[ii]);
        require(_endingPrices[ii] == _endingPrices[ii]);
        require(_durations[ii] == _durations[ii]);
        address _owner = ownerOf(_tokenIds[ii]);
        address _msgSender = msg.sender;
        require(_owner == _msgSender);
        require(checkIsAttached(_tokenIds[ii]) == 0);
        _approveForSale(msg.sender, address(saleManagerAddress), _tokenIds[ii]);
        saleManagerAddress.createSale(_tokenIds[ii], _startingPrices[ii], _endingPrices[ii], _durations[ii], msg.sender);
    }
}

function predict(uint matchID, uint amountToPredict, uint resultTime, uint predictedtime, uint marketPair, uint valuePredictedAt, uint predictionType, uint marketType) public returns(uint) {
    require(amountToPredict >= minimumToken && amountToPredict <= maximumToken, "Cannot predict with 0 Tokens");
    require(resultTime > predictedtime, "Cannot predict at the time of result");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToPredict), "Insufficient Token Allowance");
    require(predictions[matchID].exists != true, "Match already Exists");
    Prediction storage newprediction = predictions[matchID];
    newprediction.user = msg.sender;
    newprediction.betAmount = amountToPredict;
    newprediction.resultTime = resultTime;
    newprediction.betTime = predictedtime;
    newprediction.marketPair = marketPair;
    newprediction.marketType = marketType;
    newprediction.valuePredictedAt = valuePredictedAt;
    newprediction.valueResult = 0;
    newprediction.predictionType = predictionType;
    newprediction.result = 0;
    newprediction.exists = true;
    matches.push(matchID);
    totalPoints[msg.sender] = totalPoints[msg.sender].add(amountToPredict.mul(scorePrdzEq).div(1e18));
    emit PointsEarned(msg.sender, now, amountToPredict.mul(scorePrdzEq).div(1e18));
    totalStaked[msg.sender] = totalStaked[msg.sender].add(amountToPredict);
    emit PredictionMade(msg.sender, matchID);
}

function updateAccount(address account) private {
    uint pendingDivs = totalAvailableRewards[account];
    if (pendingDivs > 0) {
        require(Token(tokenAddress).transfer(account, pendingDivs), "Could not transfer tokens.");
        totalClaimedTokens[account] = totalClaimedTokens[account].add(pendingDivs);
        totalAvailableRewards[account] = 0;
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
}

function declareresult(uint curMarketValue, uint matchID) public onlyOwner returns(bool) {
    Prediction storage eachparticipant = predictions[matchID];
    if (eachparticipant.resultTime <= now && eachparticipant.result == 0 && curMarketValue > 0) {
        if (eachparticipant.valuePredictedAt < curMarketValue && eachparticipant.predictionType == 1) {
            eachparticipant.result = 1;
            eachparticipant.valueResult = curMarketValue;
            uint reward = eachparticipant.betAmount.mul(payoutPercentage).div(1e4);
            totalEarnedTokens[eachparticipant.user] = totalEarnedTokens[eachparticipant.user].add(eachparticipant.betAmount).add(reward);
            totalAvailableRewards[eachparticipant.user] = totalAvailableRewards[eachparticipant.user].add(eachparticipant.betAmount).add(reward);
        }
        if (eachparticipant.valuePredictedAt > curMarketValue && eachparticipant.predictionType == 1) {
            eachparticipant.result = 2;
            eachparticipant.valueResult = curMarketValue;
            Token(tokenAddress).transfer(lossPool, eachparticipant.betAmount);
        }
        if (eachparticipant.valuePredictedAt < curMarketValue && eachparticipant.predictionType == 0) {
            eachparticipant.result = 2;
            eachparticipant.valueResult = curMarketValue;
            Token(tokenAddress).transfer(lossPool, eachparticipant.betAmount);
        }
        if (eachparticipant.valuePredictedAt > curMarketValue && eachparticipant.predictionType == 0) {
            eachparticipant.result = 1;
            eachparticipant.valueResult = curMarketValue;
            uint reward = eachparticipant.betAmount.mul(payoutPercentage).div(1e4);
            totalEarnedTokens[eachparticipant.user] = totalEarnedTokens[eachparticipant.user].add(eachparticipant.betAmount).add(reward);
            totalAvailableRewards[eachparticipant.user] = totalAvailableRewards[eachparticipant.user].add(eachparticipant.betAmount).add(reward);
        }
        emit ResultDeclared(msg.sender, matchID);
    }
    return true;
}

function withdrawNotExecutedResult(uint _matchID)
public
returns(bool) {
    if (predictions[_matchID].result == 0 && predictions[_matchID].user == msg.sender && now.sub(predictions[_matchID].resultTime) > expresultime) {
        Prediction storage eachparticipant = predictions[_matchID];
        eachparticipant.result = 3;
        Token(tokenAddress).transfer(predictions[_matchID].user, predictions[_matchID].betAmount);
    }
    return true;
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 7000;
    } else {
        tokens = msg.value * 6820;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    totalSupply_ = safeAdd(totalSupply_, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function end() public {
    require(!ended, "end already called");
    require(winning != address(0), "no bids");
    require(!live(), "Auction live");
    IERC1155(token).safeTransferFrom(address(this), winning, id, 1, new bytes(0x0));
    uint256 balance = address(this).balance;
    uint256 hausFee = balance.div(20).mul(3);
    haus.transfer(hausFee);
    seller.transfer(address(this).balance);
    ended = true;
    emit Won(winning, lastBid);
}

function bid() public payable {
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= startTime, "Auction not started");
    require(block.timestamp < endTime, "Auction ended");
    require(msg.value >= lastBid.mul(110).div(100), "Bid too small"); 
    if (winning != address(0)) {
        winning.transfer(lastBid);
    }
    if (endTime - now < 15 minutes) {
        endTime = now + 15 minutes;
    }
    lastBid = msg.value;
    winning = msg.sender;
    emit Bid(msg.sender, msg.value);
}

function pull() public {
    require(!ended, "end already called");
    require(winning == address(0), "There were bids");
    require(!live(), "Auction live");
    IERC1155(token).safeTransferFrom(address(this), seller, id, 1, new bytes(0x0));
    ended = true;
}

function _withdrawDividendOfUser(address payable user, address payable to)
internal
returns(uint256) {
    uint256 _withdrawableDividend = withdrawableDividendOf(user);
    if (_withdrawableDividend > 0) {
        withdrawnDividends[user] = withdrawnDividends[user].add(
            _withdrawableDividend
        );
        emit DividendWithdrawn(user, _withdrawableDividend, to);
        (bool success, ) = to.call {
            value: _withdrawableDividend
        }("");
        if (!success) {
            withdrawnDividends[user] = withdrawnDividends[user].sub(
                _withdrawableDividend
            );
            return 0;
        }
        return _withdrawableDividend;
    }
    return 0;
}

function doApprove(
    address _from,
    address _spender,
    uint256 _amount
)
internal
returns(bool) {
    require(transfersEnabled);
    require((_amount == 0) || (allowed[_from][_spender] == 0));
    if (isContract(controller)) {
        require(TokenController(controller).onApprove(_from, _spender, _amount));
    }
    allowed[_from][_spender] = _amount;
    emit Approval(_from, _spender, _amount);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(_value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    require(_to != address(0));
    if (isLockAddress[_from]) {
        if (isLockAddressMoreSix[_from]) {
            require(now >= (startLockTime[_from] + 180 days));
        }
        uint256 nRelease = getCurrentBalance(_from);
        require(_value <= nRelease);
        outBala[_from] = outBala[_from].add(_value);
    }
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    if (isLockAddress[_to]) {
        inBala[_to] = inBala[_to].add(_value);
    }
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_value <= balances[msg.sender]);
    require(_to != address(0));
    if (isLockAddress[msg.sender]) {
        if (isLockAddressMoreSix[msg.sender]) {
            require(now >= (startLockTime[msg.sender] + 180 days));
        }
        uint256 nRelease = getCurrentBalance(msg.sender);
        require(_value <= nRelease);
        outBala[msg.sender] = outBala[msg.sender].add(_value);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    if (isLockAddress[_to]) {
        inBala[_to] = inBala[_to].add(_value);
    }
    return true;
}

