function cashoutEOSBetStakeTokens(uint256 _amountTokens) public {
    uint256 tokenBalance = balances[msg.sender];
    require(_amountTokens <= tokenBalance &&
        contributionTime[msg.sender] + WAITTIMEUNTILWITHDRAWORTRANSFER <= block.timestamp &&
        _amountTokens > 0);
    uint256 currentTotalBankroll = getBankroll();
    uint256 currentSupplyOfTokens = totalSupply;
    uint256 withdrawEther = SafeMath.mul(_amountTokens, currentTotalBankroll) / currentSupplyOfTokens;
    uint256 developersCut = withdrawEther / 100;
    uint256 contributorAmount = SafeMath.sub(withdrawEther, developersCut);
    totalSupply = SafeMath.sub(currentSupplyOfTokens, _amountTokens);
    balances[msg.sender] = SafeMath.sub(tokenBalance, _amountTokens);
    DEVELOPERSFUND = SafeMath.add(DEVELOPERSFUND, developersCut);
    msg.sender.transfer(contributorAmount);
    emit CashOut(msg.sender, contributorAmount, _amountTokens);
    emit Transfer(msg.sender, 0x0, _amountTokens);
}

function() public payable {
    uint256 currentTotalBankroll = SafeMath.sub(getBankroll(), msg.value);
    uint256 maxInvestmentsAllowed = MAXIMUMINVESTMENTSALLOWED;
    require(currentTotalBankroll < maxInvestmentsAllowed && msg.value != 0);
    uint256 currentSupplyOfTokens = totalSupply;
    uint256 contributedEther;
    bool contributionTakesBankrollOverLimit;
    uint256 ifContributionTakesBankrollOverLimit_Refund;
    uint256 creditedTokens;
    if (SafeMath.add(currentTotalBankroll, msg.value) > maxInvestmentsAllowed) {
        contributionTakesBankrollOverLimit = true;
        contributedEther = SafeMath.sub(maxInvestmentsAllowed, currentTotalBankroll);
        ifContributionTakesBankrollOverLimit_Refund = SafeMath.sub(msg.value, contributedEther);
    } else {
        contributedEther = msg.value;
    }
    if (currentSupplyOfTokens != 0) {
        creditedTokens = SafeMath.mul(contributedEther, currentSupplyOfTokens) / currentTotalBankroll;
    } else {
        creditedTokens = SafeMath.mul(contributedEther, 100);
    }
    totalSupply = SafeMath.add(currentSupplyOfTokens, creditedTokens);
    balances[msg.sender] = SafeMath.add(balances[msg.sender], creditedTokens);
    contributionTime[msg.sender] = block.timestamp;
    if (contributionTakesBankrollOverLimit) {
        msg.sender.transfer(ifContributionTakesBankrollOverLimit_Refund);
    }
    emit FundBankroll(msg.sender, contributedEther, creditedTokens);
    emit Transfer(0x0, msg.sender, creditedTokens);
}

function withdrawDevelopersFund(address receiver) public {
    require(msg.sender == OWNER);
    EOSBetGameInterface(DICE).payDevelopersFund(receiver);
    EOSBetGameInterface(SLOTS).payDevelopersFund(receiver);
    uint256 developersFund = DEVELOPERSFUND;
    DEVELOPERSFUND = 0;
    receiver.transfer(developersFund);
}

function transfer(address _to, uint256 _value) public returns(bool success) {
    require(balances[msg.sender] >= _value &&
        contributionTime[msg.sender] + WAITTIMEUNTILWITHDRAWORTRANSFER <= block.timestamp &&
        _to != address(this) &&
        _to != address(0));
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], _value);
    balances[_to] = SafeMath.add(balances[_to], _value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint _value) public returns(bool) {
    require(allowed[_from][msg.sender] >= _value &&
        balances[_from] >= _value &&
        contributionTime[_from] + WAITTIMEUNTILWITHDRAWORTRANSFER <= block.timestamp &&
        _to != address(this) &&
        _to != address(0));
    balances[_to] = SafeMath.add(balances[_to], _value);
    balances[_from] = SafeMath.sub(balances[_from], _value);
    allowed[_from][msg.sender] = SafeMath.sub(allowed[_from][msg.sender], _value);
    emit Transfer(_from, _to, _value);
    return true;
}

function releaseIthInvestorTokens(uint8 index) public onlyOwner {
    uint256 tokensPerVesting = computeTokensPerVesting(vestibleTokens[index]);
    require(vestibleTokens[index].supplyLeftToVest >= tokensPerVesting, "Not enough to vest");
    uint256 numVestingPeriodsPassed = now.sub(vestibleTokens[index].vestingStartTime).div(vestibleTokens[index].vestingTimeUnit);
    uint256 unlockedTokens = numVestingPeriodsPassed.mul(tokensPerVesting);
    require(unlockedTokens > vestibleTokens[index].supplyVested, "Not enough unlocked");
    require(vestibleTokens[index].supplyVested.div(tokensPerVesting) < vestibleTokens[index].numVestingPeriods, "Cannot vest more than numVestingPeriods");
    vestibleTokens[index].supplyVested = vestibleTokens[index].supplyVested.add(tokensPerVesting);
    vestibleTokens[index].supplyLeftToVest = vestibleTokens[index].supplyLeftToVest.sub(tokensPerVesting);
    _mint(msg.sender, tokensPerVesting);
    emit TokenVested(
        index, numVestingPeriodsPassed, tokensPerVesting,
        vestibleTokens[index].supplyVested, vestibleTokens[index].supplyLeftToVest);
}

function joinBet(uint _id) external payable {
    require(!lock);
    lock = true;
    require(_id > 0 && _id <= betCount, 'ID is not valid');
    Bet memory bet = activeBets[bets[_id]];
    require(bet.id == _id, 'Bet ID is not matched');
    require(msg.value >= bet.price, 'Sent Value is less than bet price');
    require(bet.b1 != msg.sender, 'You can not join your own bet');
    require(tx.origin == msg.sender, "Don't try to hack");
    uint flip = (gasleft() % 10) + (now % 10);
    if (flip % 2 == 1) {
        bet.b1 = msg.sender;
        bet.coinSide = bet.coinSide == 1 ? 2 : 1;
        emit Win(1);
    } else {
        emit Win(0);
    }
    activeBets[bets[_id]] = activeBets[activeBets.length - 1];
    activeBets.pop();
    delete bets[_id];
    bets[betCount] = bets[_id];
    winners.push(bet);
    emit BetWinner(_id, bet.price, bet.coinSide, bet.b1);
    uint256 total = bet.price * 2;
    uint256 commission = ((total) * fees) / 100;
    owner.transfer(commission);
    bet.b1.transfer(total - commission);
    lock = false;
}

function cancelBet(uint _id) external {
    require(!lock);
    lock = true;
    require(_id > 0 && _id <= betCount, 'ID is not valid');
    Bet memory bet = activeBets[bets[_id]];
    require(bet.id == _id, 'Bet ID is not matched');
    require(bet.b1 == msg.sender, 'Bet is not started by you');
    activeBets[bets[_id]] = activeBets[activeBets.length - 1];
    activeBets.pop();
    delete bets[_id];
    bets[betCount] = bets[_id];
    emit BetCanceled(_id);
    bet.b1.transfer(bet.price);
    lock = false;
}

function mint(string hash, string creatorMetadataJson) external {
    require(!hashExists(hash));
    uint256 currentTokenId = tokenIdSeq;
    tokenIdSeq = tokenIdSeq + 1;
    IWasFirstServiceToken serviceToken = IWasFirstServiceToken(_serviceTokenAddress);
    serviceToken.transferByRelatedToken(msg.sender, _shareTokenAddress, 10 ** uint256(serviceToken.DECIMALS()));
    tokenHash[currentTokenId] = hash;
    tokenIdOfHash[hash] = currentTokenId;
    tokenMetaData[currentTokenId].push(TokenMetaData(now, creatorMetadataJson));
    super._mint(msg.sender, currentTokenId);
}

