function settleETHBatch(address[] _custodies, int[] _flows, uint _fee, uint _insurance) external whenNotPaused onlyExchangeOrOwner
onlyAllowedInPhase(SettlementPhase.ONGOING) {
    require(_custodies.length == _flows.length);
    uint preBatchBalance = address(this).balance;
    if (_insurance > 0) {
        Insurance(insuranceAccount).useInsurance(_insurance);
    }
    for (uint flowIndex = 0; flowIndex < _flows.length; flowIndex++) {
        require(custodiesServedETH[lastSettlementStartedTimestamp][_custodies[flowIndex]] == false);
        require(custodyStorage.custodiesMap(_custodies[flowIndex]));
        if (_flows[flowIndex] > 0) {
            var outboundFlow = uint(_flows[flowIndex]);
            if (outboundFlow > 10 ether) {
                require(getTotalBalanceFor(_custodies[flowIndex]) >= outboundFlow);
            }
            _custodies[flowIndex].transfer(uint(_flows[flowIndex]));
        } else if (_flows[flowIndex] < 0) {
            Custody custody = Custody(_custodies[flowIndex]);
            custody.withdraw(uint(-_flows[flowIndex]), address(this));
        }
        custodiesServedETH[lastSettlementStartedTimestamp][_custodies[flowIndex]] = true;
    }
    if (_fee > 0) {
        feeAccount.transfer(_fee);
        totalFeeFlows = totalFeeFlows + _fee;
        require(totalFeeFlows <= startingFeeBalance);
    }
    uint postBatchBalance = address(this).balance;
    if (address(this).balance > preBatchBalance) {
        uint leftovers = address(this).balance - preBatchBalance;
        insuranceAccount.transfer(leftovers);
        totalInsuranceFlows += leftovers;
        require(totalInsuranceFlows <= startingInsuranceBalance);
    }
}

function settleBBDBatch(address[] _custodies, int[] _flows, uint _fee) external whenNotPaused onlyExchangeOrOwner
onlyAllowedInPhase(SettlementPhase.ONGOING) {
    require(_custodies.length == _flows.length);
    uint preBatchBalance = bbdToken.balanceOf(address(this));
    for (uint flowIndex = 0; flowIndex < _flows.length; flowIndex++) {
        require(custodiesServedBBD[lastSettlementStartedTimestamp][_custodies[flowIndex]] == false);
        require(custodyStorage.custodiesMap(_custodies[flowIndex]));
        if (_flows[flowIndex] > 0) {
            var flowValue = ((uint(_flows[flowIndex]) * gweiBBDPriceInWei) / gwei);
            require(flowValue >= 1);
            if (flowValue > 10 ether) {
                require((getTotalBalanceFor(_custodies[flowIndex]) / 2) >= flowValue);
            }
            bbdToken.transfer(_custodies[flowIndex], uint(_flows[flowIndex]));
        } else if (_flows[flowIndex] < 0) {
            Custody custody = Custody(_custodies[flowIndex]);
            custody.transferToken(address(bbdToken), address(this), uint(-(_flows[flowIndex])));
        }
        custodiesServedBBD[lastSettlementStartedTimestamp][_custodies[flowIndex]] = true;
    }
    if (_fee > 0) {
        bbdToken.transfer(feeAccount, _fee);
        totalFeeFlows += ((_fee * gweiBBDPriceInWei) / gwei);
        require(totalFeeFlows <= startingFeeBalance);
    }
    uint postBatchBalance = bbdToken.balanceOf(address(this));
    require(postBatchBalance <= preBatchBalance);
}

function startSettlementPreparation() external whenNotPaused onlyExchangeOrOwner
onlyAllowedInPhase(SettlementPhase.FINISHED) {
    require(now > earliestNextSettlementTimestamp, "A settlement can happen once per day");
    require(gweiBBDPriceInWei > 0, "BBD Price cannot be 0 during settlement");
    lastSettlementStartedTimestamp = now;
    totalFeeFlows = 0;
    totalInsuranceFlows = 0;
    currentSettlementPhase = SettlementPhase.ONGOING;
    startingFeeBalance = feeAccount.balance +
        ((bbdToken.balanceOf(feeAccount) * gweiBBDPriceInWei) / gwei);
    startingInsuranceBalance = insuranceAccount.balance;
}

function setBBDPrice(uint _priceInWei) external onlyExchangeOrOwner whenNotPaused
onlyAllowedInPhase(SettlementPhase.FINISHED) {
    if (gweiBBDPriceInWei == 0) {
        gweiBBDPriceInWei = _priceInWei;
    } else {
        if (_priceInWei > gweiBBDPriceInWei) {
            require(_priceInWei - gweiBBDPriceInWei <= (gweiBBDPriceInWei / 2));
        } else if (_priceInWei < gweiBBDPriceInWei) {
            require(gweiBBDPriceInWei - _priceInWei <= (gweiBBDPriceInWei / 2));
        }
        gweiBBDPriceInWei = _priceInWei;
    }
    require(now - lastTimePriceSet > 23 hours);
    lastTimePriceSet = now;
}

function isExchangeAlive() external view returns(bool) {
    return now - heartBeat < maxTimeIntervalHB;
}

function calcProfit(uint256 _assetId) public view returns(uint256 _profit, uint256 _lastPayment) {
    IERC721 nft = IERC721(nftAddress);
    (, uint32 assetType, , uint32 lastTransfer, uint32 lastPayment) = nft.getTokenDetails(_assetId);
    uint256 cTime = block.timestamp - lastTransfer;
    uint256 dTime = 0;
    if (lastTransfer < lastPayment) {
        dTime = lastPayment - lastTransfer;
    }
    if ((cTime) < wUnit) {
        return (0, lastTransfer);
    } else {
        uint256 weekCount;
        if (dTime == 0) {
            weekCount = ((cTime) / (wUnit));
        } else {
            weekCount = ((cTime) / (wUnit)) - (dTime) / (wUnit);
        }
        if (weekCount < 1) {
            return (0, lastPayment);
        } else {
            uint256 daysCount = weekCount * 7; 
            uint256 variantCount;
            if (assetType == 8 || assetType == 15) {
                variantCount = countTaxis();
            } else {
                variantCount = nft.polkaCitizens();
            }
            uint256 totalPayment;
            paymentByType memory thisPayment = paymentAmount[uint256(assetType)];
            uint256 dailyProfit = ((thisPayment.basePriceFactor * (variantCount * thisPayment.variantFactor)) / 30) * daysCount;
            totalPayment = ((weekCount * thisPayment.weeklyPayment) + dailyProfit);
            return (totalPayment, lastPayment);
        }
    }
}

function profitsPayment(uint256 _assetId) public returns(bool success) {
    require(paused == false, "Contract is paused");
    IERC721 nft = IERC721(nftAddress);
    address assetOwner = nft.ownerOf(_assetId);
    require(assetOwner == msg.sender, "Only asset owner can claim profits");
    require(blackListed[assetOwner] == false, "This address cannot claim profits");
    (uint256 totalPayment, ) = calcProfit(_assetId);
    require(totalPayment > 0, "You need to wait at least 1 week to claim");
    nft.setPaymentDate(_assetId);
    IERC20Token token = IERC20Token(tokenAddress);
    require(token.transferFrom(walletAddress, assetOwner, totalPayment), "ERC20 transfer fail");
    Claim memory thisclaim = Claim(msg.sender, 1, _assetId, totalPayment, block.timestamp);
    payments.push(thisclaim);
    emit Payment(msg.sender, totalPayment, 1);
    return true;
}

function calcTotalEarnings(uint256 _assetId) public view returns(uint256 _profit, uint256 _lastPayment) {
    IERC721 nft = IERC721(nftAddress);
    (, uint32 assetType, , uint32 lastTransfer, ) = nft.getTokenDetails(_assetId);
    uint256 timeFrame = block.timestamp - lastTransfer;
    if (timeFrame < wUnit) {
        return (0, lastTransfer);
    } else {
        uint256 weekCount = timeFrame / (wUnit);
        uint256 daysCount = weekCount * 7;
        uint256 variantCount;
        if (assetType == 8 || assetType == 15) {
            variantCount = countTaxis();
        } else {
            variantCount = nft.polkaCitizens();
        }
        uint256 totalPayment;
        paymentByType memory thisPayment = paymentAmount[uint256(assetType)];
        uint256 dailyProfit = ((thisPayment.basePriceFactor * (variantCount * thisPayment.variantFactor)) / 30) * daysCount;
        totalPayment = ((weekCount * thisPayment.weeklyPayment) + dailyProfit);
        return (totalPayment, lastTransfer);
    }
}

function profitsPaymentBSC(uint256 _assetId) public payable returns(bool success) {
    require(paused == false, "Contract is paused");
    require(msg.value >= gasFee, "Gas fee too low");
    IERC721 nft = IERC721(nftAddress);
    address assetOwner = nft.ownerOf(_assetId);
    require(assetOwner == msg.sender, "Only asset owner can claim profits");
    require(blackListed[assetOwner] == false, "This address cannot claim profits");
    (uint256 totalPayment, ) = calcProfit(_assetId);
    require(totalPayment > 0, "You need to wait at least 1 week to claim");
    nft.setPaymentDate(_assetId);
    Claim memory thisclaim = Claim(msg.sender, 2, _assetId, totalPayment, block.timestamp);
    payments.push(thisclaim);
    emit Payment(msg.sender, totalPayment, 2);
    return true;
}

function buyTokens() public onlyWhitelisted payable {
    require(state == State.Active &&
        block.timestamp <= endAt &&
        msg.value >= lowCapTxWei &&
        msg.value <= hardCapTxWei &&
        collectedWei + msg.value <= hardCapWei);
    uint amountWei = msg.value;
    if (block.timestamp <= personalCapEndAt) {
        personalPurchases[msg.sender] = personalPurchases[msg.sender].add(amountWei);
        require(personalPurchases[msg.sender] <= PERSONAL_CAP);
    }
    uint itokens = amountWei.mul(ETH_TOKEN_EXCHANGE_RATIO).mul(ONE_TOKEN).div(1 ether);
    collectedWei = collectedWei.add(amountWei);
    emit ICOInvestment(msg.sender, amountWei, itokens, 0);
    token.transferFrom(tokenHolder, msg.sender, itokens);
    forwardFunds();
    touch();
}

function start(uint endAt_) public onlyOwner {
    require(endAt_ > block.timestamp && state == State.Inactive);
    endAt = endAt_;
    startAt = block.timestamp;
    state = State.Active;
    emit ICOStarted(endAt, lowCapWei, hardCapWei, lowCapTxWei, hardCapTxWei);
}

function tune(uint endAt_,
    uint lowCapWei_,
    uint hardCapWei_,
    uint lowCapTxWei_,
    uint hardCapTxWei_) public onlyOwner isSuspended {
    if (endAt_ > block.timestamp) {
        endAt = endAt_;
    }
    if (lowCapWei_ > 0) {
        lowCapWei = lowCapWei_;
    }
    if (hardCapWei_ > 0) {
        hardCapWei = hardCapWei_;
    }
    if (lowCapTxWei_ > 0) {
        lowCapTxWei = lowCapTxWei_;
    }
    if (hardCapTxWei_ > 0) {
        hardCapTxWei = hardCapTxWei_;
    }
    require(lowCapWei <= hardCapWei && lowCapTxWei <= hardCapTxWei);
    touch();
}

function touch() public {
    if (state != State.Active && state != State.Suspended) {
        return;
    }
    if (collectedWei >= hardCapWei) {
        state = State.Completed;
        endAt = block.timestamp;
        emit ICOCompleted(collectedWei);
    } else if (block.timestamp >= endAt) {
        if (collectedWei < lowCapWei) {
            state = State.NotCompleted;
            emit ICONotCompleted();
        } else {
            state = State.Completed;
            emit ICOCompleted(collectedWei);
        }
    }
}

function start(uint endAt_) onlyOwner public {
    uint requireTokens = hardCapWei.mul(ETH_TOKEN_EXCHANGE_RATIO).mul(ONE_TOKEN).div(1 ether);
    require(token.balanceOf(tokenHolder) >= requireTokens &&
        token.allowance(tokenHolder, address(this)) >= requireTokens);
    personalCapEndAt = block.timestamp + 48 hours;
    super.start(endAt_);
}

function _attack(uint _heroId, uint _genes, uint _heroStrength, uint _heroCurrentHealth) internal {
    Monster storage monster = heroIdToMonster[_heroId];
    uint8 currentLevel = monster.level;
    uint heroPower;
    (heroPower, , , , ) = edCoreContract.getHeroPower(_genes, dungeonDifficulty);
    uint damageByMonster;
    uint damageByHero;
    if (now > monster.creationTime + monsterFleeTime) {
        damageByMonster = currentLevel + monsterStrength;
    } else {
        if (currentLevel >= 2) {
            damageByMonster = _getRandomNumber(currentLevel / 2);
        }
    }
    if (damageByMonster >= _heroCurrentHealth) {
        heroIdToHealth[_heroId] = 0;
        uint addToJackpot = entranceFee - heroIdToRefundedFee[_heroId];
        if (addToJackpot > 0) {
            jackpot += addToJackpot;
            entranceFeePool -= addToJackpot;
            heroIdToRefundedFee[_heroId] += addToJackpot;
        }
        assert(addToJackpot <= entranceFee);
    } else {
        heroIdToHealth[_heroId] -= damageByMonster;
        if (now > monster.creationTime + monsterFleeTime) {
            currentLevel++;
            heroIdToMonster[_heroId] = Monster(uint64(monster.creationTime + monsterFleeTime),
                currentLevel, currentLevel * monsterHealth, currentLevel * monsterHealth);
            monster = heroIdToMonster[_heroId];
        }
        damageByHero = (_heroStrength * 1e9 + heroPower * 1e9 / (10 * (1 + _getRandomNumber(5)))) / tx.gasprice;
        bool isMonsterDefeated = damageByHero >= monster.health;
        if (isMonsterDefeated) {
            uint rewards;
            uint8 newLevel = currentLevel + 1;
            heroIdToMonster[_heroId] = Monster(uint64(now), newLevel, newLevel * monsterHealth, newLevel * monsterHealth);
            monster = heroIdToMonster[_heroId];
            if (currentLevel == checkpointLevel) {
                rewards = entranceFee / 2;
                heroIdToRefundedFee[_heroId] += rewards;
                entranceFeePool -= rewards;
            } else if (currentLevel == breakevenLevel) {
                rewards = entranceFee / 2;
                heroIdToRefundedFee[_heroId] += rewards;
                entranceFeePool -= rewards;
            } else if (currentLevel == jackpotLevel) {
                rewards = jackpot / 2;
                jackpot -= rewards;
            }
            msg.sender.transfer(rewards);
        } else {
            monster.health -= uint8(damageByHero);
        }
    }
    LogAttack(now, msg.sender, _heroId, currentLevel, damageByHero, damageByMonster, isMonsterDefeated, rewards);
}

function attack(uint _heroId) whenNotPaused onlyHumanAddress external payable {
    uint genes;
    address owner;
    (, , , genes, owner, , ) = edCoreContract.getHeroDetails(_heroId);
    require(msg.sender == owner);
    uint heroInitialHealth = (genes / (32 ** 12)) % 32 + 1;
    uint heroStrength = (genes / (32 ** 8)) % 32 + 1;
    Monster memory monster = heroIdToMonster[_heroId];
    uint currentLevel = monster.level;
    uint heroCurrentHealth = heroIdToHealth[_heroId];
    bool dungeonRunEnded;
    if (currentLevel == 0) {
        require(msg.value >= entranceFee);
        entranceFeePool += entranceFee;
        heroIdToMonster[_heroId] = Monster(uint64(now), 1, monsterHealth, monsterHealth);
        monster = heroIdToMonster[_heroId];
        heroIdToHealth[_heroId] = heroInitialHealth;
        heroCurrentHealth = heroInitialHealth;
        if (msg.value > entranceFee) {
            msg.sender.transfer(msg.value - entranceFee);
        }
    } else {
        require(heroCurrentHealth > 0);
        dungeonRunEnded = now > monster.creationTime + monsterFleeTime * 2 ||
            (monster.health == monster.initialHealth && now > monster.creationTime + monsterFleeTime);
        if (dungeonRunEnded) {
            uint addToJackpot = entranceFee - heroIdToRefundedFee[_heroId];
            if (addToJackpot > 0) {
                jackpot += addToJackpot;
                entranceFeePool -= addToJackpot;
                heroIdToRefundedFee[_heroId] += addToJackpot;
            }
            assert(addToJackpot <= entranceFee);
        }
        msg.sender.transfer(msg.value);
    }
    if (!dungeonRunEnded) {
        _attack(_heroId, genes, heroStrength, heroCurrentHealth);
    }
}

function getRunDetails(uint _heroId) external view returns(
    uint _heroPower,
    uint _heroStrength,
    uint _heroInitialHealth,
    uint _heroHealth,
    uint _monsterCreationTime,
    uint _monsterLevel,
    uint _monsterInitialHealth,
    uint _monsterHealth,
    uint _gameState 
) {
    uint genes;
    address owner;
    (, , , genes, owner, , ) = edCoreContract.getHeroDetails(_heroId);
    (_heroPower, , , , ) = edCoreContract.getHeroPower(genes, dungeonDifficulty);
    _heroStrength = (genes / (32 ** 8)) % 32 + 1;
    _heroInitialHealth = (genes / (32 ** 12)) % 32 + 1;
    _heroHealth = heroIdToHealth[_heroId];
    Monster memory monster = heroIdToMonster[_heroId];
    _monsterCreationTime = monster.creationTime;
    bool _dungeonRunEnded = monster.level > 0 && (
        _heroHealth == 0 ||
        now > _monsterCreationTime + monsterFleeTime * 2 ||
        (monster.health == monster.initialHealth && now > monster.creationTime + monsterFleeTime)
    );
    if (monster.level == 0) {
        _heroHealth = _heroInitialHealth;
        _monsterLevel = 1;
        _monsterInitialHealth = monsterHealth;
        _monsterHealth = _monsterInitialHealth;
        _gameState = 0;
    } else if (_dungeonRunEnded) {
        _monsterLevel = monster.level;
        _monsterInitialHealth = monster.initialHealth;
        _monsterHealth = monster.health;
        _gameState = 3;
    } else if (now > _monsterCreationTime + monsterFleeTime) {
        if (monster.level + monsterStrength > _heroHealth) {
            _heroHealth = 0;
            _monsterLevel = monster.level;
            _monsterInitialHealth = monster.initialHealth;
            _monsterHealth = monster.health;
            _gameState = 2;
        } else {
            _heroHealth -= monster.level + monsterStrength;
            _monsterCreationTime += monsterFleeTime;
            _monsterLevel = monster.level + 1;
            _monsterInitialHealth = _monsterLevel * monsterHealth;
            _monsterHealth = _monsterInitialHealth;
            _gameState = 1;
        }
    } else {
        _monsterLevel = monster.level;
        _monsterInitialHealth = monster.initialHealth;
        _monsterHealth = monster.health;
        _gameState = 2;
    }
}

