function stake(uint256 amount) external override {
    require(amount > 0, "IouVesting: You cannot stake 0");
    require(
        _rewardsPool.balance() > 0,
        "IouVesting: No rewards are available"
    );
    require(
        _iouPool.token().transferFrom(
            msg.sender,
            address(_iouPool),
            amount
        ),
        "IouVesting: transfer into iou pool failed"
    );
    if (userShares[msg.sender] == uint256(0)) {
        totalUsers++;
    }
    userShares[msg.sender] += amount;
    emit TokensStaked(msg.sender, amount, totalStaked());
}

function unstake(uint256 amount, uint256 donationRatio) external override {
    require(
        amount > uint256(0),
        "IouVesting: Unstake amount needs to be greater than 0"
    );
    require(
        userShares[msg.sender] != uint256(0),
        "IouVesting: There is nothing to unstake for you"
    );
    require(
        userShares[msg.sender] >= amount,
        "IouVesting: You cannot unstake more than you staked"
    );
    require(
        donationRatio <= uint256(100),
        "IouVesting: You cannot donate more than you earned"
    );
    uint256 amountVsSharesRatio =
        getRatio(amount, userShares[msg.sender], 18);
    uint256 totalUserPossibleRewards =
        (computeUserTotalPossibleRewards(msg.sender, false) *
            amountVsSharesRatio) / (10 ** 18);
    uint256 totalCurrentUserRewards =
        (getCurrentRewards(true) * amountVsSharesRatio) / (10 ** 18);
    if (totalRewards() > 0) {
        uint256 donationAmount = 0;
        if (donationAddress != address(0) && donationRatio > 0) {
            donationAmount =
                (donationRatio * totalCurrentUserRewards) /
                (10 ** 18);
        }
        uint256 toTransferToUser = totalCurrentUserRewards;
        if (donationAmount > 0) {
            toTransferToUser = totalCurrentUserRewards - donationAmount;
            require(
                _rewardsPool.transfer(donationAddress, donationAmount),
                "IouVesting: transfer from rewards pool to donation receiver failed"
            );
        }
        require(
            _rewardsPool.transfer(msg.sender, toTransferToUser),
            "IouVesting: transfer from rewards pool failed"
        );
        emit RewardsClaimed(msg.sender, toTransferToUser);
        emit RewardsDonated(msg.sender, donationAmount);
        userEarnings[msg.sender] += totalCurrentUserRewards;
        availableForfeitedAmount += (totalUserPossibleRewards -
            totalCurrentUserRewards);
    }
    require(
        _iouPool.transfer(address(_lockedIouPool), amount),
        "IouVesting: transfer from iou pool to locked iou pool failed"
    );
    userShares[msg.sender] -= amount;
    if (userShares[msg.sender] == uint256(0)) {
        totalUsers--;
    }
}

function computeRewards(address user, bool includeForfeited)
private
view
returns(uint256) {
    uint256 nowTimestamp = block.timestamp;
    uint256 endTimestamp = startTimestamp + (totalMonths * 30 days);
    if (nowTimestamp > endTimestamp) {
        nowTimestamp = endTimestamp;
    }
    uint256 stakingMonths =
        (nowTimestamp - startTimestamp) / 60 / 60 / 24 / 30; 
    if (stakingMonths == uint256(0)) {
        stakingMonths = 1;
    }
    if (includeForfeited) {
        uint256 totalUserPossibleReward =
            computeUserTotalPossibleRewards(user, true);
        return (totalUserPossibleReward * stakingMonths) / totalMonths;
    } else {
        uint256 totalUserPossibleRewardWithoutForfeited =
            computeUserTotalPossibleRewards(user, false);
        uint256 rewardsWithoutForfeited =
            ((totalUserPossibleRewardWithoutForfeited * stakingMonths) /
                totalMonths);
        if (!includeForfeited) return rewardsWithoutForfeited;
    }
}

function transfer(address _to, uint _value) public returns(bool success) {
    require(_value > 0 &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]);
    bytes memory empty;
    if (isContract(_to)) {
        return transferToContract(_to, _value, empty);
    } else {
        return transferToAddress(_to, _value, empty);
    }
}

function autoDistribute() payable public {
    require(distributeAmount > 0 &&
        balanceOf[founder] >= distributeAmount &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    if (msg.value > 0) founder.transfer(msg.value);
    balanceOf[founder] = balanceOf[founder].sub(distributeAmount);
    balanceOf[msg.sender] = balanceOf[msg.sender].add(distributeAmount);
    emit Transfer(founder, msg.sender, distributeAmount);
}

function distributeAirdrop(address[] addresses, uint[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e8);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        emit Transfer(msg.sender, addresses[j], amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e8);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        emit Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function extractfee() external onlyOwner() {
    PIKA(address(this)).transfer(_msgSender(), _taxFee);
    _taxFee = 0;
}

function extractOldPIKA() external onlyOwner() {
    ERC20(oldPika).transfer(_msgSender(), oldPika_amount);
    oldPika_amount = 0;
}

function exchnagePika(uint256 tokens) external {
    require(tokens <= PIKA(address(this)).balanceOf(address(this)), "Not enough tokens in the reserve");
    require(ERC20(oldPika).transferFrom(_msgSender(), address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 time = block.timestamp - ContractDeployed;
    uint256 day = time.div(86400);
    require(day <= 4, "Sorry Swaping Time Period is finished");
    if (tokens < 10000000000 * 10 ** 9 * 10 ** 9) {
        uint256 extra = calSwapToken(tokens, 500);
        PIKA(address(this)).transfer(_msgSender(), tokens.add(extra));
    } else if ((tokens >= 10000000000 * 10 ** 9 * 10 ** 9) && (tokens < 100000000000 * 10 ** 9 * 10 ** 9)) {
        uint256 extra = calSwapToken(tokens, 250);
        PIKA(address(this)).transfer(_msgSender(), tokens.add(extra));
    } else if (tokens >= 100000000000 * 10 ** 9 * 10 ** 9) {
        uint256 extra = calSwapToken(tokens, 100);
        PIKA(address(this)).transfer(_msgSender(), tokens.add(extra));
    }
    oldPika_amount = oldPika_amount.add(tokens);
}

function _transfer(address sender, address recipient, uint256 amount) internal virtual {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if (_isExcludedFromFee[sender] || _isExcludedFromFee[recipient]) {
        uint256 senderBalance = balances[sender];
        require(senderBalance >= amount, "ERC20: transfer amount exceeds balance");
        balances[sender] = senderBalance - amount;
        balances[recipient] += amount;
        emit Transfer(sender, recipient, amount);
    } else {
        uint256 _Fee = calSwapToken(amount, _taxFeepercent);
        _taxFee += _Fee;
        if (_taxFee >= minamountTakenOut) {
            swapTokensForEth(_taxFee);
        }
        uint256 senderBalance = balances[sender];
        require(senderBalance >= amount, "ERC20: transfer amount exceeds balance");
        balances[sender] = senderBalance - amount;
        balances[recipient] += amount - _Fee;
        emit Transfer(sender, recipient, amount - _Fee);
    }
}

function swapTokensForEth(uint256 tokenAmount) private {
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = uniswapV2Router.WETH();
    _approve(address(this), address(uniswapV2Router), tokenAmount);
    uniswapV2Router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        tokenAmount,
        0, 
        path,
        owner,
        block.timestamp
    );
    _taxFee = 0;
}

function transferFrom(address sender, address recipient, uint256 amount) public override returns(bool success) {
    _transfer(sender, recipient, amount);
    uint256 currentAllowance = allowed[sender][_msgSender()];
    require(currentAllowance >= amount, "ERC20: transfer amount exceeds allowance");
    _approve(sender, _msgSender(), currentAllowance - amount);
    return true;
}

function unplant(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > PossibleUnstakeTime, "You have not staked for a while yet, kindly wait a bit more");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(liquiditytoken1).transfer(admin, fee), "Could not transfer withdraw fee.");
    require(Token(liquiditytoken1).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function updateAccount(address account) private {
    uint unclaimedDivs = getUnclaimedDivs(account);
    if (unclaimedDivs > 0) {
        require(Token(tokenAddress).transfer(account, unclaimedDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(unclaimedDivs);
        totalClaimedRewards = totalClaimedRewards.add(unclaimedDivs);
        emit RewardsTransferred(account, unclaimedDivs);
    }
    lastClaimedTime[account] = now;
}

function plant(uint amountToStake) public {
    require(stakingStatus == true, "Staking is not yet initialized");
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(liquiditytoken1).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(Token(liquiditytoken1).transfer(admin, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

