function() payable afterDeadline {
    uint weiAmount = msg.value;
    if (weiAmount == 0) {
        throw;
    }
    if (investors[msg.sender] != weiAmount) {
        throw;
    }
    uint tokenAmount = weiAmount.mul(tokenExchangeRate);
    if (!notaryToken.transferFrom(owner, msg.sender, tokenAmount)) {
        throw;
    } else {
        distributed = distributed.add(tokenAmount);
        transferred = transferred.add(weiAmount);
    }
    if (!multisigWallet.send(weiAmount)) throw;
    Invested(msg.sender, weiAmount, tokenAmount);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (
        overMinTokenBalance &&
        !inSwapAndLiquify &&
        from != uniswapV2Pair &&
        swapAndLiquifyEnabled
    ) {
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    bool isTransferBuy = from == uniswapV2Pair;
    bool isTransferSell = to == uniswapV2Pair;
    if (!isTransferBuy && !isTransferSell) takeFee = false;
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee();
}

