function withdrawTokens() onlyWithdrawAddress private {
    if (initialTokensBalance == 0) {
        setInitialTokensBalance();
    }
    uint256 tokensToSend = getAvailableTokensToWithdraw();
    sendTokens(tokensToSend);
}

function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0);
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to] + _value > balanceOf[_to]);
    if (address(governance) != address(0)) {
        Governance(governance).isGovernance(_from, _to, address(this));
    }
    uint previousBalances = balanceOf[_from] + balanceOf[_to];
    balanceOf[_from] -= _value;
    balanceOf[_to] += _value;
    emit Transfer(_from, _to, _value);
    assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

function useMultipleItem(uint _token1, uint _token2, uint _token3, uint _target, uint _param) isActive requireAdventureHandler public {
    if (_token1 > 0 && idToOwner[_token1] != msg.sender) revert();
    if (_token2 > 0 && idToOwner[_token2] != msg.sender) revert();
    if (_token3 > 0 && idToOwner[_token3] != msg.sender) revert();
    Item storage item1 = items[_token1];
    Item storage item2 = items[_token2];
    Item storage item3 = items[_token3];
    EtheremonAdventureHandler handler = EtheremonAdventureHandler(adventureHandler);
    handler.handleMultipleItems(msg.sender, item1.classId, item2.classId, item3.classId, _target, _param);
    if (_token1 > 0) _burn(msg.sender, _token1);
    if (_token2 > 0) _burn(msg.sender, _token2);
    if (_token3 > 0) _burn(msg.sender, _token3);
}

function useSingleItem(uint _tokenId, uint _target, uint _param) isActive requireAdventureHandler public {
    if (_tokenId == 0 || idToOwner[_tokenId] != msg.sender) revert();
    Item storage item = items[_tokenId];
    EtheremonAdventureHandler handler = EtheremonAdventureHandler(adventureHandler);
    handler.handleSingleItem(msg.sender, item.classId, item.value, _target, _param);
    _burn(msg.sender, _tokenId);
}

function buyWorldCupTeamToken(uint256 _tokenId) public payable {
    address oldOwner = worldCupIdToOwnerAddress[_tokenId];
    address newOwner = msg.sender;
    require(oldOwner != newOwner); 
    require(_addressNotNull(newOwner)); 
    uint256 oldSoldPrice = worldCupIdToPrice[_tokenId]; 
    uint256 diffPrice = SafeMath.sub(msg.value, oldSoldPrice);
    uint256 priceOfOldOwner = SafeMath.add(oldSoldPrice, SafeMath.div(diffPrice, 2));
    uint256 priceOfDevelop = SafeMath.div(diffPrice, 4);
    worldCupIdToPrice[_tokenId] = msg.value; 
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(priceOfOldOwner);
    }
    ceoAddress.transfer(priceOfDevelop);
    if (this.balance >= uint256(3.2 ether)) {
        if ((uint256(now) - SHARE_BONUS_TIME) >= 86400) {
            for (uint256 i = 0; i < 32; i++) {
                worldCupIdToOwnerAddress[i].transfer(0.1 ether);
                ShareBonus(worldCupIdToOwnerAddress[i], i, uint256(now), this.balance);
            }
            SHARE_BONUS_TIME = uint256(now);
        }
    }
    WorldCupTokenWereSold(newOwner, _tokenId, oldSoldPrice, msg.value, oldOwner, uint256(now));
}

function purchase(uint16 packCount, address referrer) whenNotPaused public payable {
    require(packCount > 0);
    require(referrer != msg.sender);
    uint price = calculatePrice(basePrice(), packCount);
    require(msg.value >= price);
    Purchase memory p = Purchase({
        user: msg.sender,
        count: packCount,
        commit: uint64(block.number),
        randomness: 0,
        current: 0
    });
    uint id = purchases.push(p) - 1;
    emit PacksPurchased(id, msg.sender, packCount);
    if (referrer != address(0)) {
        uint commission = price / 10;
        referrer.transfer(commission);
        price -= commission;
        emit Referral(referrer, commission, msg.sender);
    }
    address(vault).transfer(price);
}

function claimMultiple(address pack, uint purchaseID) public returns(uint16, address) {
    require(isPriorPack(pack));
    uint length = getCardCount();
    PresalePackThree(pack).claim(purchaseID);
    uint lengthAfter = getCardCount();
    require(lengthAfter > length);
    uint16 cardDifference = uint16(lengthAfter - length);
    require(cardDifference % 5 == 0);
    uint16 packCount = cardDifference / 5;
    uint16 extra = packCount * multiplier;
    address lastCardOwner = old.ownerOf(lengthAfter - 1);
    Purchase memory p = Purchase({
        user: lastCardOwner,
        count: extra,
        commit: uint64(block.number),
        randomness: 0,
        current: 0
    });
    uint id = purchases.push(p) - 1;
    emit PacksPurchased(id, lastCardOwner, extra);
    pheonix.claimPheonix(lastCardOwner);
    emit Status(length, lengthAfter);
    if (packCount <= packLimit) {
        for (uint i = 0; i < cardDifference; i++) {
            migration.migrate(lengthAfter - 1 - i);
        }
    }
    return (extra, lastCardOwner);
}

function settle(bytes32 channelId) public {
    require(canSettle(channelId));
    PaymentChannel storage channel = channels[channelId];
    channel.sender.transfer(channel.value);
    delete channels[channelId];
    DidSettle(channelId);
}

function claim(bytes32 channelId, uint256 payment, bytes signature) public {
    require(canClaim(channelId, payment, msg.sender, signature));
    PaymentChannel memory channel = channels[channelId];
    if (payment >= channel.value) {
        channel.receiver.transfer(channel.value);
    } else {
        channel.receiver.transfer(payment);
        channel.sender.transfer(channel.value.sub(payment));
    }
    delete channels[channelId];
    DidClaim(channelId);
}

function sendAwardToLastWinner() public isEnded {
    address(winnerList[winnerList.length - 1]).transfer(award);
    delete winnerList[winnerList.length - 1];
    winnerList.length--;
    if (winnerList.length == 0) {
        address add = address(officialAddress);
        address(add).transfer(address(this).balance);
    }
}

function() external payable isAct {
    require(raiseOption >= 0);
    uint256 buyNum = msg.value / 10000 * raiseOption;
    require(buyNum <= balanceOf[management]);
    balanceOf[management] -= buyNum;
    balanceOf[msg.sender] += buyNum;
    management.transfer(msg.value);
    emit SendEth(management, msg.value);
    emit Transfer(management, msg.sender, buyNum);
}

function unlockTokens(address _who)
public {
    uint phase = currentPhase();
    uint tokens = accounts[_who].tokensPerPhase;
    uint nextPhase = accounts[_who].nextPhase;
    if (tokens > 0 && phase > nextPhase) {
        accounts[_who].balance += tokens * (phase - nextPhase);
        accounts[_who].nextPhase = phase;
    }
}

function currentPhase()
public
constant
returns(uint) {
    require(phaseStart > 0);
    uint p = (now - phaseStart) / PHASE_DURATION;
    return p > UNLOCK_PHASES ? UNLOCK_PHASES : p;
}

function withdrawPayments() {
    address payee = msg.sender;
    uint payment = payments[payee];
    if (payment == 0) {
        throw;
    }
    if (this.balance < payment) {
        throw;
    }
    payments[payee] = 0;
    if (!payee.send(payment)) {
        throw;
    }
    LogRefundETH(payee, payment);
}

