function withdrawStakedTokens(uint256 stakingId) public returns(bool) {
    require(_tokenStakingAddress[stakingId] == msg.sender, "No staked token found on this address and ID");
    require(_TokenTransactionstatus[stakingId] != true, "Either tokens are already withdrawn or blocked by admin");
    if (_tokenTotalDays[stakingId] == PERIOD_SILVER) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_SILVER, "Unable to Withdraw Staked token before 15 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _usersTokens[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_GOLD) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_GOLD, "Unable to Withdraw Staked token before 30 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_PLATINUM) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_PLATINUM, "Unable to Withdraw Staked token before 60 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        }
    } else {
        return false;
    }
    return true;
}

function getTokenPenaltyDetailByStakingId(uint256 id) public view returns(uint256) {
    if (_tokenStakingEndTime[id] > now) {
        if (_tokenTotalDays[id] == PERIOD_SILVER) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_SILVER / 100000000);
        } else if (_tokenTotalDays[id] == PERIOD_GOLD) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_GOLD / 100000000);
        } else if (_tokenTotalDays[id] == PERIOD_PLATINUM) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_PLATINUM / 100000000);
        } else {
            return 0;
        }
    } else {
        return 0;
    }
}

function ExchangeETHforToken(address _addr, uint256 _amount) private {
    uint256 amount = _amount;
    address userAdd = _addr;
    ethAmount = ((amount.mul(10 ** uint256(tokenDecimal)).div(tokenPriceEth)).mul(10 ** uint256(tokenDecimal))).div(10 ** uint256(tokenDecimal));
    require(Token(tokenAddr).balanceOf(address(this)) >= ethAmount, "There is low token balance in contract");
    require(Token(tokenAddr).transfer(userAdd, ethAmount));
    emit TokenTransfer(userAdd, ethAmount);
    tokenExchanged[msg.sender] = tokenExchanged[msg.sender].add(ethAmount);
}

function() payable external {
    ExchangeETHforToken(msg.sender, msg.value);
    balances[msg.sender] = balances[msg.sender].add(msg.value);
}

function ExchangeETHforTokenMannual() public payable {
    uint256 amount = msg.value;
    address userAdd = msg.sender;
    ethAmount = ((amount.mul(10 ** uint256(tokenDecimal)).div(tokenPriceEth)).mul(10 ** uint256(tokenDecimal))).div(10 ** uint256(tokenDecimal));
    require(Token(tokenAddr).balanceOf(address(this)) >= ethAmount, "There is low token balance in contract");
    require(Token(tokenAddr).transfer(userAdd, ethAmount));
    balances[msg.sender] = balances[msg.sender].add(msg.value);
    emit TokenTransfer(userAdd, ethAmount);
    tokenExchanged[msg.sender] = tokenExchanged[msg.sender].add(ethAmount);
}

function buy() payable public {
    require(now > 1543536000); 
    uint amount = msg.value.div(buyPrice); 
    _transfer(owner, msg.sender, amount); 
}

function sell(uint256 amount) public {
    require(now > 1543536000); 
    require(amount > 0);
    require(balances[msg.sender] >= amount);
    uint256 requiredBalance = amount.mul(sellPrice);
    require(this.balance >= requiredBalance); 
    balances[msg.sender] -= amount;
    balances[owner] += amount;
    Transfer(msg.sender, owner, amount);
    msg.sender.transfer(requiredBalance); 
}

function Buy(address target, uint256 maxamount, uint256 maxprice) public payable {
    require(SellOrders[target][0] > 0);
    require(SellOrders[target][1] <= maxprice);
    uint256 price = SellOrders[target][1];
    uint256 amount_buyable = (mul(msg.value, uint256(10 ** decimals))) / price;
    if (amount_buyable > SellOrders[target][0]) {
        amount_buyable = SellOrders[target][0];
    }
    if (amount_buyable > maxamount) {
        amount_buyable = maxamount;
    }
    uint256 total_payment = mul(amount_buyable, price) / (uint256(10 ** decimals));
    require(amount_buyable > 0 && total_payment > 0);
    uint256 Fee = mul(total_payment, SellFee) / 10000;
    uint256 Left = total_payment - Fee;
    uint256 Excess = msg.value - total_payment;
    uint256 OldTokensSeller = balanceOf[target];
    uint256 OldTokensBuyer = balanceOf[msg.sender];
    _forceTransfer(target, msg.sender, amount_buyable);
    SellOrders[target][0] = sub(SellOrders[target][0], amount_buyable);
    uint256 _sendTarget = _withdraw(target, OldTokensSeller, false);
    uint256 _sendBuyer = _withdraw(msg.sender, OldTokensBuyer, false);
    target.transfer(add(Left, _sendTarget));
    if (add(Excess, _sendBuyer) > 0) {
        msg.sender.transfer(add(Excess, _sendBuyer));
    }
    if (Fee > 0) {
        owner.transfer(Fee);
    }
    emit SellOrderFilled(msg.sender, target, amount_buyable, price, Left);
}

function transferFrom(address _from, address _to, uint256 _value) public validAddress returns(bool success) {
    require(_from != _to);
    require(sub(balanceOf[_from], SellOrders[_from][0]) >= _value);
    require(balanceOf[_to] + _value >= balanceOf[_to]);
    require(allowance[_from][msg.sender] >= _value);
    uint256 _toBal = balanceOf[_to];
    uint256 _fromBal = balanceOf[_from];
    balanceOf[_to] += _value;
    balanceOf[_from] -= _value;
    allowance[_from][msg.sender] -= _value;
    emit Transfer(_from, _to, _value);
    CancelOrder();
    uint256 _sendFrom = _withdraw(_from, _fromBal, false);
    uint256 _sendTo = _withdraw(_to, _toBal, false);
    _from.transfer(_sendFrom);
    _to.transfer(_sendTo);
    return true;
}

function transfer(address _to, uint256 _value) public validAddress returns(bool success) {
    require(balanceOf[msg.sender] >= _value);
    require(balanceOf[_to] + _value >= balanceOf[_to]);
    require(sub(balanceOf[msg.sender], SellOrders[msg.sender][0]) >= _value);
    require(msg.sender != _to);
    uint256 _toBal = balanceOf[_to];
    uint256 _fromBal = balanceOf[msg.sender];
    balanceOf[msg.sender] -= _value;
    balanceOf[_to] += _value;
    emit Transfer(msg.sender, _to, _value);
    uint256 _sendFrom = _withdraw(msg.sender, _fromBal, false);
    uint256 _sendTo = _withdraw(_to, _toBal, false);
    msg.sender.transfer(_sendFrom);
    _to.transfer(_sendTo);
    return true;
}

function WithdrawPotShare() public {
