function requestMortgageId(
    Engine engine,
    uint256 loanId,
    uint256 deposit,
    uint256 landId,
    TokenConverter tokenConverter
) public returns(uint256 id) {
    require(engine.getCurrency(loanId) == MANA_CURRENCY, "Loan currency is not MANA");
    address borrower = engine.getBorrower(loanId);
    require(engine.getStatus(loanId) == Engine.Status.initial, "Loan status is not inital");
    require(msg.sender == engine.getBorrower(loanId) ||
        (msg.sender == engine.getCreator(loanId) && creators[msg.sender]),
        "Creator should be borrower or authorized");
    require(engine.isApproved(loanId), "Loan is not approved");
    require(rcn.allowance(borrower, this) >= REQUIRED_ALLOWANCE, "Manager cannot handle borrower&#39;s funds");
    require(tokenConverter != address(0), "Token converter not defined");
    require(loanToLiability[engine][loanId] == 0, "Liability for loan already exists");
    uint256 landCost;
    (, , landCost, ) = landMarket.auctionByAssetId(landId);
    uint256 loanAmount = engine.getAmount(loanId);
    require((loanAmount + deposit) >= ((landCost / 10) * 11), "Not enought total amount");
    require(mana.transferFrom(msg.sender, this, deposit), "Error pulling mana");
    id = mortgages.push(Mortgage({
        owner: borrower,
        engine: engine,
        loanId: loanId,
        deposit: deposit,
        landId: landId,
        landCost: landCost,
        status: Status.Pending,
        tokenConverter: tokenConverter
    })) - 1;
    loanToLiability[engine][loanId] = id;
    emit RequestedMortgage({
        _id: id,
        _borrower: borrower,
        _engine: engine,
        _loanId: loanId,
        _landId: landId,
        _deposit: deposit,
        _tokenConverter: tokenConverter
    });
}

function claim(address engine, uint256 loanId, bytes) external returns(bool) {
    uint256 mortgageId = loanToLiability[engine][loanId];
    Mortgage storage mortgage = mortgages[mortgageId];
    require(mortgage.status == Status.Ongoing, "Mortgage not ongoing");
    require(mortgage.loanId == loanId, "Mortgage don&#39;t match loan id");
    if (mortgage.engine.getStatus(loanId) == Engine.Status.paid || mortgage.engine.getStatus(loanId) == Engine.Status.destroyed) {
        require(_isAuthorized(msg.sender, mortgageId), "Sender not authorized");
        mortgage.status = Status.Paid;
        land.safeTransferFrom(this, msg.sender, mortgage.landId);
        emit PaidMortgage(msg.sender, mortgageId);
    } else if (isDefaulted(mortgage.engine, loanId)) {
        require(msg.sender == mortgage.engine.ownerOf(loanId), "Sender not lender");
        mortgage.status = Status.Defaulted;
        land.safeTransferFrom(this, msg.sender, mortgage.landId);
        emit DefaultedMortgage(mortgageId);
    } else {
        revert("Mortgage not defaulted/paid");
    }
    _destroy(mortgageId);
    delete mortgageByLandId[mortgage.landId];
    return true;
}

function requestCosign(Engine engine, uint256 index, bytes data, bytes oracleData) public returns(bool) {
    Mortgage storage mortgage = mortgages[uint256(readBytes32(data, 0))];
    require(mortgage.engine == engine, "Engine does not match");
    require(mortgage.loanId == index, "Loan id does not match");
    require(mortgage.status == Status.Pending, "Mortgage is not pending");
    mortgage.status = Status.Ongoing;
    _generate(uint256(readBytes32(data, 0)), mortgage.owner);
    uint256 loanAmount = convertRate(engine.getOracle(index), engine.getCurrency(index), oracleData, engine.getAmount(index));
    require(rcn.transferFrom(mortgage.owner, this, loanAmount), "Error pulling RCN from borrower");
    uint256 boughtMana = convertSafe(mortgage.tokenConverter, rcn, mana, loanAmount);
    delete mortgage.tokenConverter;
    uint256 currentLandCost;
    (, , currentLandCost, ) = landMarket.auctionByAssetId(mortgage.landId);
    require(currentLandCost <= mortgage.landCost, "Parcel is more expensive than expected");
    require(mana.approve(landMarket, currentLandCost));
    flagReceiveLand = mortgage.landId;
    landMarket.executeOrder(mortgage.landId, currentLandCost);
    require(mana.approve(landMarket, 0));
    require(flagReceiveLand == 0, "ERC721 callback not called");
    require(land.ownerOf(mortgage.landId) == address(this), "Error buying parcel");
    uint256 totalMana = boughtMana.add(mortgage.deposit);
    require(mana.transfer(mortgage.owner, totalMana.sub(currentLandCost)), "Error returning MANA");
    require(mortgage.engine.cosign(index, 0), "Error performing cosign");
    mortgageByLandId[mortgage.landId] = uint256(readBytes32(data, 0));
    emit StartedMortgage(uint256(readBytes32(data, 0)));
    return true;
}

function isDefaulted(Engine engine, uint256 index) public view returns(bool) {
    return engine.getStatus(index) == Engine.Status.lent &&
        engine.getDueTime(index).add(7 days) <= block.timestamp;
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function validPurchaseForManual() internal constant returns(bool) {
    bool withinPeriod = now >= start_time && now <= end_Time;
    bool allPhaseFinished = phase_5_remaining_tokens > 0;
    return withinPeriod && allPhaseFinished;
}

function validPurchase() internal constant returns(bool) {
    bool withinPeriod = now >= start_time && now <= end_Time;
    bool allPhaseFinished = phase_5_remaining_tokens > 0;
    bool nonZeroPurchase = msg.value != 0;
    bool minPurchase = eth_to_usd * msg.value >= 100; 
    return withinPeriod && nonZeroPurchase && allPhaseFinished && minPurchase;
}

function hasEnded() public constant returns(bool) {
    return now > end_Time;
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = (weiAmount.mul(getRate())).div(10 ** uint256(10));
    require(transferIfTokenAvailable(tokens, weiAmount, beneficiary));
    weiRaised = weiRaised.add(weiAmount);
    forwardFunds();
}

function setMerchantWallet(MerchantWallet _newWallet) public onlyOwner {
    require(address(_newWallet) != 0x0);
    require(_newWallet.merchantIdHash() == merchantIdHash);
    merchantWallet = _newWallet;
}

function setMerchantDealsHistory(MerchantDealsHistory _merchantHistory) public onlyOwner {
    require(address(_merchantHistory) != 0x0);
    require(_merchantHistory.merchantIdHash() == merchantIdHash);
    merchantHistory = _merchantHistory;
}

function _checkCap(address addr) internal returns(uint) {
    if (!whitelistIsActive) return contributionCaps[0];
    _checkWhitelistContract(addr);
    var c = whitelist[addr];
    if (!c.authorized) return 0;
    if (nextCapTime > 0 && block.timestamp > nextCapTime) {
        contributionCaps = nextContributionCaps;
        nextCapTime = 0;
    }
    if (c.cap < contributionCaps.length) return contributionCaps[c.cap];
    return c.cap;
}

function submitPool(uint amountInWei) public onlyOwner noReentrancy {
    require(contractStage < 3);
    require(receiverAddress != 0x00);
    require(block.number >= addressChangeBlock.add(6000));
    require(contributionMin <= amountInWei && amountInWei <= this.balance);
    finalBalance = this.balance;
    require(receiverAddress.call.value(amountInWei).gas(msg.gas.sub(5000))());
    if (this.balance > 0) ethRefundAmount.push(this.balance);
    contractStage = 3;
    PoolSubmitted(receiverAddress, amountInWei);
}

function _withdraw(address receiver, address tokenAddr) internal {
    assert(contractStage == 3);
    var c = whitelist[receiver];
    if (tokenAddr == 0x00) {
        tokenAddr = activeToken;
    }
    var d = distributionMap[tokenAddr];
    require((ethRefundAmount.length > c.ethRefund) || d.pct.length > c.tokensClaimed[tokenAddr]);
    if (ethRefundAmount.length > c.ethRefund) {
        uint pct = _toPct(c.balance, finalBalance);
        uint ethAmount = 0;
        for (uint i = c.ethRefund; i < ethRefundAmount.length; i++) {
            ethAmount = ethAmount.add(_applyPct(ethRefundAmount[i], pct));
        }
        c.ethRefund = ethRefundAmount.length;
        if (ethAmount > 0) {
            receiver.transfer(ethAmount);
            EthRefunded(receiver, ethAmount);
        }
    }
    if (d.pct.length > c.tokensClaimed[tokenAddr]) {
        uint tokenAmount = 0;
        for (i = c.tokensClaimed[tokenAddr]; i < d.pct.length; i++) {
            tokenAmount = tokenAmount.add(_applyPct(c.balance, d.pct[i]));
        }
        c.tokensClaimed[tokenAddr] = d.pct.length;
        if (tokenAmount > 0) {
            require(d.token.transfer(receiver, tokenAmount));
            d.balanceRemaining = d.balanceRemaining.sub(tokenAmount);
            TokensWithdrawn(receiver, tokenAddr, tokenAmount);
        }
    }
}

function revoke(address addr) public onlyOwner {
    require(contractStage < 3);
    require(whitelist[addr].authorized);
    require(whitelistContract.checkMemberLevel(addr) == 0);
    whitelist[addr].authorized = false;
    if (whitelist[addr].balance > 0) {
        uint amountToTransfer = whitelist[addr].balance;
        whitelist[addr].balance = 0;
        addr.transfer(amountToTransfer);
        ContributorBalanceChanged(addr, 0);
    }
}

function modifyIndividualCap(address addr, uint cap) public onlyOwner {
    require(contractStage < 3);
    require(cap < contributionCaps.length || (cap >= contributionMin && cap <= contributionCaps[0]));
    _checkWhitelistContract(addr);
    var c = whitelist[addr];
    require(c.authorized);
    uint amount = c.balance;
    c.cap = cap;
    uint capAmount = _checkCap(addr);
    if (amount > capAmount) {
        c.balance = capAmount;
        addr.transfer(amount.sub(capAmount));
        ContributorBalanceChanged(addr, capAmount);
    }
}

function withdraw(address tokenAddr) public {
    var c = whitelist[msg.sender];
    require(c.balance > 0);
    if (contractStage < 3) {
        uint amountToTransfer = c.balance;
        c.balance = 0;
        msg.sender.transfer(amountToTransfer);
        ContributorBalanceChanged(msg.sender, 0);
    } else {
        _withdraw(msg.sender, tokenAddr);
    }
}

function authorize(address addr, uint cap) public onlyOwner {
    require(contractStage == 1);
    _checkWhitelistContract(addr);
    require(!whitelist[addr].authorized);
    require((cap > 0 && cap < contributionCaps.length) || (cap >= contributionMin && cap <= contributionCaps[0]));
    uint size;
    assembly {
        size: = extcodesize(addr)
    }
    require(size == 0);
    whitelist[addr].cap = cap;
    whitelist[addr].authorized = true;
}

function _ethDeposit() internal {
    assert(contractStage == 1);
    require(tx.gasprice <= maxGasPrice);
    require(this.balance <= contributionCaps[0]);
    var c = whitelist[msg.sender];
    uint newBalance = c.balance.add(msg.value);
    require(newBalance >= contributionMin);
    require(newBalance <= _checkCap(msg.sender));
    c.balance = newBalance;
    ContributorBalanceChanged(msg.sender, newBalance);
}

function enableTokenWithdrawals(address tokenAddr, bool notDefault) public onlyOwner noReentrancy {
    require(contractStage == 3);
    if (notDefault) {
        require(activeToken != 0x00);
    } else {
        activeToken = tokenAddr;
    }
    var d = distributionMap[tokenAddr];
    if (d.pct.length == 0) d.token = ERC20(tokenAddr);
    uint amount = d.token.balanceOf(this).sub(d.balanceRemaining);
    require(amount > 0);
    if (feePct > 0) {
        require(d.token.transfer(owner, _applyPct(amount, feePct)));
    }
    amount = d.token.balanceOf(this).sub(d.balanceRemaining);
    d.balanceRemaining = d.token.balanceOf(this);
    d.pct.push(_toPct(amount, finalBalance));
}

function _checkWhitelistContract(address addr) internal {
    var c = whitelist[addr];
    if (!c.authorized) {
        var level = whitelistContract.checkMemberLevel(addr);
        if (level == 0 || level >= contributionCaps.length) return;
        c.cap = level;
        c.authorized = true;
    }
}

function modifyAllLevelCaps(uint[] cap, uint time) public onlyOwner {
    require(contractStage < 3);
    require(cap.length == contributionCaps.length - 1);
    require(time == 0 || time > block.timestamp);
    if (time == 0) {
        for (uint8 i = 0; i < cap.length; i++) {
            modifyLevelCap(i + 1, cap[i]);
        }
    } else {
        nextContributionCaps = contributionCaps;
        nextCapTime = time;
        for (i = 0; i < cap.length; i++) {
            require(contributionCaps[i + 1] <= cap[i] && contributionCaps[0] >= cap[i]);
            nextContributionCaps[i + 1] = cap[i];
        }
    }
}

function checkContributorBalance(address addr) view public returns(uint balance, uint cap, uint remaining) {
    var c = whitelist[addr];
    if (!whitelistIsActive) cap = contributionCaps[0];
    else if (!c.authorized) {
        cap = whitelistContract.checkMemberLevel(addr);
        if (cap == 0) return (c.balance, 0, 0);
    } else {
        cap = c.cap;
    }
    balance = c.balance;
    if (contractStage == 1) {
        if (cap < contributionCaps.length) {
            if (nextCapTime == 0 || nextCapTime > block.timestamp) {
                cap = contributionCaps[cap];
            } else {
                cap = nextContributionCaps[cap];
            }
        }
        remaining = cap.sub(balance);
        if (contributionCaps[0].sub(this.balance) < remaining) remaining = contributionCaps[0].sub(this.balance);
    } else {
        remaining = 0;
    }
    return (balance, cap, remaining);
}

function() public payable {
    uint _fee = msg.value / feeRate;
    uint _val = msg.value - _fee;
    kBalance += _val;
    TechnicalRise.transfer(_fee);
    if (_val < 9 finney) {
        timeOut += 2 minutes;
        return;
    }
    if (timeOut <= now) {
        lastBidder.transfer(kBalance - _val);
        kBalance = _val;
        timeOut = now;
    }
    timeOut += (10 minutes) * (9 finney) / _val;
    lastBidder = msg.sender;
}

function exerciseOption(uint _pustBalance) public returns(bool) {
    require(now < ExerciseEndTime);
    require(_pustBalance <= balances[msg.sender]);
    uint _ether = safeMul(_pustBalance, 7 * 10 ** 12);
    require(address(this).balance >= _ether);
    uint _amount = safeMul(_pustBalance, 10 ** 18);
    require(PUST(ustAddress).transferFrom(msg.sender, officialAddress, _amount) == true);
    balances[msg.sender] = safeSub(balances[msg.sender], _pustBalance);
    balances[officialAddress] = safeAdd(balances[officialAddress], _pustBalance);
    msg.sender.transfer(_ether);
    emit exchange(address(this), msg.sender, _pustBalance);
}

function() payable public {
    require(now < ExerciseEndTime);
    uint epochNow = whichEpoch(block.number);
    if (epochNow != epochLast) {
        lastEpochBlock = safeAdd(lastEpochBlock, ((block.number - lastEpochBlock) / initBlockEpoch + 1) * initBlockEpoch);
        eachPUSTprice = calcpustprice(epochNow, epochLast);
        epochLast = epochNow;
    }
    uint _value = msg.value;
    require(_value >= 1 finney);
    uint _PUST = _value / eachPUSTprice;
    require(safeMul(_PUST, eachPUSTprice) <= _value);
    if (safeAdd(totalSupply, _PUST) > topTotalSupply) {
        _PUST = safeSub(topTotalSupply, totalSupply);
    }
    uint _refound = safeSub(_value, safeMul(_PUST, eachPUSTprice));
    if (_refound > 0) {
        msg.sender.transfer(_refound);
    }
    officialAddress.transfer(safeSub(_value, _refound));
    balances[msg.sender] = safeAdd(balances[msg.sender], _PUST);
    totalSupply = safeAdd(totalSupply, _PUST);
    emit Transfer(address(this), msg.sender, _PUST);
    lastEpochBlock = safeAdd(lastEpochBlock, eachUserWeight);
}

