        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    com.transfer(address(this).balance);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function withdraw(
    address _transitAddress,
    address _recipient,
    uint8 _v,
    bytes32 _r,
    bytes32 _s
)
public
onlyVerifier 
whenNotPaused
whenNotStopped
returns(bool success) {
    Transfer memory transferOrder = transferDct[_transitAddress];
    require(verifySignature(_transitAddress,
        _recipient, _v, _r, _s));
    delete transferDct[_transitAddress];
    _recipient.transfer(transferOrder.amount);
    emit LogWithdraw(transferOrder.from, _transitAddress, _recipient, transferOrder.amount);
    return true;
}

function cancelTransfer(address _transitAddress) public returns(bool success) {
    Transfer memory transferOrder = transferDct[_transitAddress];
    require(msg.sender == transferOrder.from);
    delete transferDct[_transitAddress];
    msg.sender.transfer(transferOrder.amount);
    emit LogCancel(msg.sender, _transitAddress);
    return true;
}

function withdrawCommission()
public
whenNotPaused
returns(bool success) {
    uint commissionToTransfer = commissionToWithdraw;
    commissionToWithdraw = 0;
    owner.transfer(commissionToTransfer); 
    emit LogWithdrawCommission(commissionToTransfer);
    return true;
}

function getProofOfStakeReward(address _address) internal returns(uint) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    require(!noPOSRewards[_address]);
    uint _now = now;
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0)
        return 0;
    return _coinAge.mul(REWARDS_PER_AGE);
}

function getCoinAge(address _address, uint _now) internal returns(uint _coinAge) {
    if (transferIns[_address].length <= 0)
        return 0;
    for (uint i = 0; i < transferIns[_address].length; i++) {
        if (_now < uint(transferIns[_address][i].time).add(stakeMinAge))
            continue;
        uint nCoinSeconds = _now.sub(uint(transferIns[_address][i].time));
        if (nCoinSeconds > stakeMaxAge)
            nCoinSeconds = stakeMaxAge;
        _coinAge = _coinAge.add(uint(transferIns[_address][i].amount) * nCoinSeconds.div(1 days));
    }
    _coinAge = _coinAge.div(5000 ether);
}

function ownerSetStakeStartTime(uint timestamp) onlyOwner public {
    require((stakeStartTime <= 0) && (timestamp >= chainStartTime));
    stakeStartTime = timestamp;
}

function yank(uint256 id) external auth lock {
    require(sales[id].usr != address(0), "ProxyManagerClipper/not-running-auction");
    dog.digs(ilk, sales[id].tab);
    uint256 lot = sales[id].lot;
    vat.flux(ilk, address(this), msg.sender, lot);
    proxyMgr.onVatFlux(address(gemJoin), address(this), msg.sender, lot);
    _remove(id);
    emit Yank(id);
}

function take(
    uint256 id, 
    uint256 amt, 
    uint256 max, 
    address who, 
    bytes calldata data 
) external lock isStopped(3) {
    address usr = sales[id].usr;
    uint96 tic = sales[id].tic;
    require(usr != address(0), "ProxyManagerClipper/not-running-auction");
    uint256 price;
    {
        bool done;
        (done, price) = status(tic, sales[id].top);
        require(!done, "ProxyManagerClipper/needs-reset");
    }
    require(max >= price, "ProxyManagerClipper/too-expensive");
    uint256 lot = sales[id].lot;
    uint256 tab = sales[id].tab;
    uint256 owe;
    {
        uint256 slice = min(lot, amt); 
        owe = mul(slice, price);
        if (owe > tab) {
            owe = tab; 
            slice = owe / price; 
        } else if (owe < tab && slice < lot) {
            uint256 _chost = chost;
            if (tab - owe < _chost) { 
                require(tab > _chost, "ProxyManagerClipper/no-partial-purchase");
                owe = tab - _chost; 
                slice = owe / price; 
            }
        }
        tab = tab - owe; 
        lot = lot - slice;
        {
            address urp = proxyMgr.proxy(who);
            require(urp != address(0), "ProxyManagerClipper/no-urn-proxy");
            vat.flux(ilk, address(this), urp, slice);
            proxyMgr.onVatFlux(address(gemJoin), address(this), urp, slice);
        }
        DogLike dog_ = dog;
        if (data.length > 0 && who != address(vat) && who != address(dog_)) {
            ClipperCallee(who).clipperCall(msg.sender, owe, slice, data);
        }
        vat.move(msg.sender, vow, owe);
        dog_.digs(ilk, lot == 0 ? tab + owe : owe);
    }
    if (lot == 0) {
        _remove(id);
    } else if (tab == 0) {
        vat.flux(ilk, address(this), usr, lot);
        proxyMgr.onVatFlux(address(gemJoin), address(this), usr, lot);
        _remove(id);
    } else {
        sales[id].tab = tab;
        sales[id].lot = lot;
    }
    emit Take(id, max, price, owe, tab, lot, usr);
}

function redo(
    uint256 id, 
    address kpr 
) external lock isStopped(2) {
    address usr = sales[id].usr;
    uint96 tic = sales[id].tic;
    uint256 top = sales[id].top;
    require(usr != address(0), "ProxyManagerClipper/not-running-auction");
    (bool done, ) = status(tic, top);
    require(done, "ProxyManagerClipper/cannot-reset");
    uint256 tab = sales[id].tab;
    uint256 lot = sales[id].lot;
    sales[id].tic = uint96(block.timestamp);
    uint256 feedPrice = getFeedPrice();
    top = rmul(feedPrice, buf);
    require(top > 0, "ProxyManagerClipper/zero-top-price");
    sales[id].top = top;
    uint256 _tip = tip;
    uint256 _chip = chip;
    uint256 coin;
    if (_tip > 0 || _chip > 0) {
        uint256 _chost = chost;
        if (tab >= _chost && mul(lot, feedPrice) >= _chost) {
            coin = add(_tip, wmul(tab, _chip));
            vat.suck(vow, kpr, coin);
        }
    }
    emit Redo(id, top, tab, lot, usr, kpr, coin);
}

function kick(
    uint256 tab, 
    uint256 lot, 
    address usr, 
    address kpr 
) external auth lock isStopped(1) returns(uint256 id) {
    require(tab > 0, "ProxyManagerClipper/zero-tab");
    require(lot > 0, "ProxyManagerClipper/zero-lot");
    require(usr != address(0), "ProxyManagerClipper/zero-usr");
    id = ++kicks;
    require(id > 0, "ProxyManagerClipper/overflow");
    active.push(id);
    sales[id].pos = active.length - 1;
    sales[id].tab = tab;
    sales[id].lot = lot;
    sales[id].usr = usr;
    sales[id].tic = uint96(block.timestamp);
    uint256 top;
    top = rmul(getFeedPrice(), buf);
    require(top > 0, "ProxyManagerClipper/zero-top-price");
    sales[id].top = top;
    uint256 _tip = tip;
    uint256 _chip = chip;
    uint256 coin;
    if (_tip > 0 || _chip > 0) {
        coin = add(_tip, wmul(tab, _chip));
        vat.suck(vow, kpr, coin);
    }
    proxyMgr.onLiquidation(address(gemJoin), ProxyLike(usr).usr(), lot);
    emit Kick(id, top, tab, lot, usr, kpr, coin);
}

function getStatus(uint256 id) external view returns(bool needsRedo, uint256 price, uint256 lot, uint256 tab) {
    address usr = sales[id].usr;
    uint96 tic = sales[id].tic;
    bool done;
    (done, price) = status(tic, sales[id].top);
    needsRedo = usr != address(0) && done;
    lot = sales[id].lot;
    tab = sales[id].tab;
}

function add(uint256 x, uint256 y) internal pure returns(uint256 z) {
    require((z = x + y) >= x);
}

function status(uint96 tic, uint256 top) internal view returns(bool done, uint256 price) {
    price = calc.price(top, sub(block.timestamp, tic));
    done = (sub(block.timestamp, tic) > tail || rdiv(price, top) < cusp);
}

function sub(uint256 x, uint256 y) internal pure returns(uint256 z) {
    require((z = x - y) <= x);
}

function mul(uint256 x, uint256 y) internal pure returns(uint256 z) {
    require(y == 0 || (z = x * y) / y == x);
}

function buy() external payable {
    if (stage == 1) {
        require(Whitelist[msg.sender] == true, "You cannot purchase because you were not whitelisted");
        require(startSales == true, "Sales has not been initialized yet");
        require(msg.value >= minBuy && msg.value <= maxBuy, "Invalid buy amount, confirm the maximum and minimum buy amounts");
        require(token != 0x0000000000000000000000000000000000000000, "Selling token not yet configured");
        require((buyamount[msg.sender] + msg.value) <= maxBuy, "Ensure you total buy is not above maximum allowed per wallet");
        buyvalue = msg.value;
        _qtty = buyvalue.div(STAGE_PRICE[1]);
        require(ERC20Interface(token).balanceOf(address(this)) >= _qtty * decimal, "Insufficient tokens in the contract");
        saleswallet.transfer(msg.value);
        buyamount[msg.sender] += msg.value;
        require(ERC20Interface(token).transfer(msg.sender, _qtty * decimal), "Transaction failed");
    } else {
        require(startSales == true, "Sales has not been initialized yet");
        require(msg.value >= minBuy && msg.value <= maxBuy, "Invalid buy amount, confirm the maximum and minimum buy amounts");
        require(token != 0x0000000000000000000000000000000000000000, "Selling token not yet configured");
        require((buyamount[msg.sender] + msg.value) <= maxBuy, "Ensure you total buy is not above maximum allowed per wallet");
        buyvalue = msg.value;
        _qtty = buyvalue.div(STAGE_PRICE[2]);
        require(ERC20Interface(token).balanceOf(address(this)) >= _qtty * decimal, "Insufficient tokens in the contract");
        saleswallet.transfer(msg.value);
        buyamount[msg.sender] += msg.value;
        require(ERC20Interface(token).transfer(msg.sender, _qtty * decimal), "Transaction failed");
    }
}

