function revoke() public onlyOwner {
    require(revocable);
    require(!revoked[token]);
    uint256 balance = token.balanceOf(this);
    uint256 unreleased = releasableAmount();
    uint256 refund = balance.sub(unreleased);
    revoked[token] = true;
    token.safeTransfer(rollback, refund);
    emit Revoked();
}

function release() public {
    require(initialized);
    uint256 unreleased = releasableAmount();
    require(unreleased > 0);
    released[token] = released[token].add(unreleased);
    token.safeTransfer(beneficiary, unreleased);
    emit Released(unreleased);
}

function initialize() public onlyOwner {
    require(tokensAvailable() == initialTokens); 
    currentBalance = token.balanceOf(this);
    totalBalance = currentBalance.add(released[token]);
    initialized = true;
}

function vestedAmount() public returns(uint256) {
    currentBalance = token.balanceOf(this);
    totalBalance = currentBalance.add(released[token]);
    if (block.timestamp < cliff) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked[token]) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration);
    }
}

function distributeReward(address user) private {
    if (userIndex[user] == 0 && index > 0) {
        userIndex[user] = doubleScale;
    }
    uint indexDelta = index - userIndex[user];
    userIndex[user] = index;
    uint rewardDelta = indexDelta.mul(userCollateral[user]).div(doubleScale);
    userAccrued[user] = userAccrued[user].add(rewardDelta);
    if (rewardToken.balanceOf(address(this)) >= userAccrued[user] && userAccrued[user] > 0) {
        if (rewardToken.transfer(user, userAccrued[user])) {
            userAccrued[user] = 0;
        }
    }
    emit RewardDistributed(user, rewardDelta, index);
}

function deposit(uint amount) public {
    updateIndex();
    distributeReward(msg.sender);
    require(stakeToken.transferFrom(msg.sender, address(this), amount), "transferFrom failed");
    userCollateral[msg.sender] = userCollateral[msg.sender].add(amount);
    totalCollateral = totalCollateral.add(amount);
    emit Deposit(msg.sender, amount);
}

function withdraw(uint amount) public {
    updateIndex();
    distributeReward(msg.sender);
    require(stakeToken.transfer(msg.sender, amount), "transfer failed");
    userCollateral[msg.sender] = userCollateral[msg.sender].sub(amount);
    totalCollateral = totalCollateral.sub(amount);
    emit Withdraw(msg.sender, amount);
}

function deposit(uint256 token_amount, uint256 expected_assets) public lock {
    uint256 asset_deposit = calculateAssetIn(token_amount);
    require(asset_deposit > 0, "Hedgehog_Deposit: zero asset deposit");
    require(asset_deposit <= expected_assets, "Hedgehog_Deposit: deposit assets above expected");
    _oracle();
    TransferHelper.safeTransferFrom(asset, msg.sender, address(this), asset_deposit);
    _mint(msg.sender, token_amount);
    Deposit(msg.sender, asset_deposit, token_amount);
}

function _oracle() internal {
    if (timestamp < block.timestamp && totalSupply > 0) {
        timestamp = block.timestamp;
        oracle_prev = oracle;
        oracle = price();
        Oracle(timestamp, oracle, oracle_prev);
    }
}

function peek(bytes calldata data) public view override returns(bool, uint256) {
    IUniswapV2Pair pair = abi.decode(data, (IUniswapV2Pair));
    uint32 blockTimestamp = uint32(block.timestamp);
    if (pairs[pair].blockTimestampLast == 0) {
        return (false, 0);
    }
    uint32 timeElapsed = blockTimestamp - pairs[pair].blockTimestampLast; 
    if (timeElapsed < PERIOD) {
        return (true, pairs[pair].priceAverage);
    }
    uint256 priceCumulative = _get(pair, blockTimestamp);
    uint144 priceAverage =
        FixedPoint.uq112x112(uint224((priceCumulative - pairs[pair].priceCumulativeLast) / timeElapsed)).mul(10 ** 18).decode144();
    return (true, priceAverage);
}

function get(bytes calldata data) external override returns(bool, uint256) {
    IUniswapV2Pair pair = abi.decode(data, (IUniswapV2Pair));
    uint32 blockTimestamp = uint32(block.timestamp);
    if (pairs[pair].blockTimestampLast == 0) {
        pairs[pair].blockTimestampLast = blockTimestamp;
        pairs[pair].priceCumulativeLast = _get(pair, blockTimestamp);
        return (false, 0);
    }
    uint32 timeElapsed = blockTimestamp - pairs[pair].blockTimestampLast; 
    if (timeElapsed < PERIOD) {
        return (true, pairs[pair].priceAverage);
    }
    uint256 priceCumulative = _get(pair, blockTimestamp);
    pairs[pair].priceAverage = FixedPoint
        .uq112x112(uint224((priceCumulative - pairs[pair].priceCumulativeLast) / timeElapsed))
        .mul(10 ** 18)
        .decode144();
    pairs[pair].blockTimestampLast = blockTimestamp;
    pairs[pair].priceCumulativeLast = priceCumulative;
    return (true, pairs[pair].priceAverage);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyPeopleWithTokens()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAdminsFriends && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function withdraw()
onlyPeopleWithProfits()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function executeProposal(uint256 _proposalID) internal {
    Proposal memory prop = proposals[_proposalID];
    bytes memory payload = abi.encodePacked(
        proposalTypes[prop.proposalType],
        prop.proposal
    );
    proposals[_proposalID].executed = true;
    (bool success, bytes memory returnData) = prop.destination.call {
        value: prop.value
    }(payload);
    proposals[_proposalID].success = success;
    proposals[_proposalID].returnData = returnData;
    emit ProposalApprovedAndEnforced(
        _proposalID,
        payload,
        success,
        returnData
    );
}

function depositToken(address token, uint amount) {
    require(token != 0);
    require(Token(token).transferFrom(msg.sender, this, amount));
    tokens[token][msg.sender] = safeAdd(tokens[token][msg.sender], amount);
    Deposit(token, msg.sender, amount, tokens[token][msg.sender]);
}

function tokensAvailable() public constant when_active returns(uint tokens) {
    uint _currentCap = totalAccounted / currentPrice();
    if (_currentCap >= tokenCap) {
        return 0;
    }
    return tokenCap - _currentCap;
}

function flushEra() private {
    uint currentEra = (now - beginTime) / ERA_PERIOD;
    if (currentEra > eraIndex) {
        Ticked(eraIndex, totalReceived, totalAccounted);
    }
    eraIndex = currentEra;
}

function buyin()
public
payable
when_not_halted
when_active
only_eligible(msg.sender) {
    flushEra();
    if (currentBonus > 0) {
        if (now >= beginTime + BONUS_MIN_DURATION 
            &&
            lastNewInterest + BONUS_LATCH <= block.number 
        ) {
            currentBonus--;
        }
        if (now >= beginTime + BONUS_MAX_DURATION) {
            currentBonus = 0;
        }
        if (buyins[msg.sender].received == 0) { 
            lastNewInterest = uint32(block.number);
        }
    }
    uint accounted;
    bool refund;
    uint price;
    (accounted, refund, price) = theDeal(msg.value);
    require(!refund);
    buyins[msg.sender].accounted += uint128(accounted);
    buyins[msg.sender].received += uint128(msg.value);
    totalAccounted += accounted;
    totalReceived += msg.value;
    endTime = calculateEndTime();
    Buyin(msg.sender, accounted, msg.value, price);
    treasury.transfer(msg.value);
}

function isActive() public constant returns(bool) {
    return now >= beginTime && now < endTime;
}

function theDeal(uint _value)
public
constant
when_active
returns(uint accounted, bool refund, uint price) {
    uint _bonus = bonus(_value);
    price = currentPrice();
    accounted = _value + _bonus;
    uint available = tokensAvailable();
    uint tokens = accounted / price;
    refund = (tokens > available);
}

function allFinalised() public constant returns(bool) {
    return now >= endTime && totalAccounted == totalFinalised;
}

function finalise(address _who)
public
when_not_halted
when_ended
only_buyins(_who) {
    if (endPrice == 0) {
        endPrice = totalAccounted / tokenCap;
        Ended(endPrice);
    }
    uint total = buyins[_who].accounted;
    uint tokens = total / endPrice;
    totalFinalised += total;
    delete buyins[_who];
    require(tokenContract.transferFrom(treasury, _who, tokens));
    Finalised(_who, tokens);
    if (totalFinalised == totalAccounted) {
        Retired();
    }
}

function buyTokens(address beneficiary)
public
payable
whenNotPaused
isWhitelisted(beneficiary) {
    require(beneficiary != address(0));
    require(validPurchase() && tokensSold < crowdsaleCap);
    if (isMinting) {
        require(tokenOnSale.owner() == address(this), "The token owner must be contract address!");
    }
    if (!isWeiAccepted) {
        require(msg.value == 0);
    } else if (msg.value > 0) {
        buyTokensWithWei(beneficiary);
    }
    uint256 starAllocationToTokenSale = starToken.allowance(beneficiary, this);
    if (starAllocationToTokenSale > 0) {
        uint256 tokens = starAllocationToTokenSale.mul(starRate).div(1000);
        if (tokensSold.add(tokens) > crowdsaleCap) {
            tokens = crowdsaleCap.sub(tokensSold);
            starAllocationToTokenSale = tokens.div(starRate).div(1000);
        }
        starRaised = starRaised.add(starAllocationToTokenSale);
        tokensSold = tokensSold.add(tokens);
        sendPurchasedTokens(beneficiary, tokens);
        emit TokenPurchaseWithStar(msg.sender, beneficiary, starAllocationToTokenSale, tokens);
        starToken.transferFrom(beneficiary, wallet, starAllocationToTokenSale);
        wallet.splitStarFunds();
    }
}

function hasEnded() public view returns(bool) {
    return now > endTime;
}

function initCrowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate) public {
    require(
        startTime == 0 && endTime == 0 && rate == 0,
        "Global variables must be empty when initializing crowdsale!"
    );
    require(_startTime >= now, "_startTime must be more than current time!");
    require(_endTime >= _startTime, "_endTime must be more than _startTime!");
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
}

function validPurchase() internal view returns(bool) {
    return now >= startTime && now <= endTime;
}

function updateInvestor() public payable {
    require(msg.value >= investmentMin);
    theInvestor.send(msg.value.div(100).mul(60));
    investmentMin = investmentMin.mul(2);
    theInvestor = msg.sender;
}

function updateAd(uint256 id) public payable {
    require(msg.value >= adPriceMultiple.mul(adPriceHour));
    require(block.timestamp > purchaseTimestamp.add(purchaseSeconds));
    require(id > 0);
    theInvestor.send(msg.value.div(10));
    lastOwner.send(msg.value.div(2));
    if (msg.value >= adPriceMultiple.mul(adPriceWeek)) {
        purchaseSeconds = 604800; 
    } else if (msg.value >= adPriceMultiple.mul(adPriceDay)) {
        purchaseSeconds = 86400; 
    } else if (msg.value >= adPriceMultiple.mul(adPriceHalfDay)) {
        purchaseSeconds = 43200; 
    } else {
        purchaseSeconds = 3600; 
    }
    dappId = id;
    purchaseTimestamp = block.timestamp;
    lastOwner = msg.sender;
}

function swapAndLiquify(uint256 tokens) private {
    uint256 half = tokens.div(2);
    uint256 otherHalf = tokens.sub(half);
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(half);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    addLiquidity(otherHalf, newBalance);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(!_isBlacklisted[from] && !_isBlacklisted[to], "To or From address is blacklisted.");
    if (!isTradingEnabled) {
        require(_isExcluded[to] || _isExcluded[from], "Trading is not yet enabled. Be patient!");
    } else if (block.timestamp - startTime < 300 && from == uniswapV2Pair) {
        require(amount <= 10 ** 9 * (10 ** 18), "Over max buy amt.");
    } else if (to == uniswapV2Pair) {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();
        uint[] memory amounts = uniswapV2Router.getAmountsOut(amount, path);
        require(amounts[1] <= maxSellAmt);
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 swapTokens = contractTokenBalance.div(100);
        swapAndLiquify(swapTokens);
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (from == uniswapV2Pair) {
            fees = amount.mul(buyFee).div(1000);
        } else if (to == uniswapV2Pair) {
            fees = amount.mul(sellFee).div(1000);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function buyArtworkETH(uint256[6] memory tradeValues, address payable[2] memory tradeAddresses, uint8 v, bytes32[2] memory rs) public payable returns(bool success) {
    require(tradeValues[3] > block.timestamp, "Expired");
    require(tradeAddresses[0] == address(0), "Not an ETH Trade");
    bytes32 orderHash = keccak256(abi.encodePacked(address(this), tradeAddresses[0], tradeValues[0], tradeValues[1], tradeAddresses[1], tradeValues[2], tradeValues[3], tradeValues[4]));
    require(ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", orderHash)), v, rs[0], rs[1]) == tradeAddresses[1], "Invalid Order");
    require(orderFills[orderHash].add(tradeValues[5]) <= tradeValues[1], "Trade amount too high");
    require(msg.value >= tradeValues[2].mul(tradeValues[5]), "Insufficent Balance");
    uint256 amount = (tradeValues[2].mul(tradeValues[5]));
    IERC1155(baeContract).safeTransferFrom(tradeAddresses[1], msg.sender, tradeValues[0], tradeValues[5], "");
    feeAccount.transfer(amount.mul(10).div(1000));
    owner.transfer(amount.mul(fee).div(1000));
    payable(IERC1155(baeContract).creators(tradeValues[0])).transfer(amount.mul(creatorFee).div(1000));
    tradeAddresses[1].transfer(amount.mul(1000 - fee - creatorFee - 10).div(1000));
    msg.sender.transfer(msg.value - amount);
    orderFills[orderHash] = orderFills[orderHash].add(tradeValues[5]);
    emit Trade(tradeValues[0], tradeValues[5], tradeAddresses[0], tradeValues[2].mul(tradeValues[5]), msg.sender, tradeAddresses[1], orderHash);
    return true;
}

function isValidOrder(uint256[5] memory tradeValues, address[2] memory tradeAddresses, uint8 v, bytes32[2] memory rs) public view returns(bool) {
    bytes32 orderHash = keccak256(abi.encodePacked(address(this), tradeAddresses[0], tradeValues[0], tradeValues[1], tradeAddresses[1], tradeValues[2], tradeValues[3], tradeValues[4]));
    if (ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", orderHash)), v, rs[0], rs[1]) != tradeAddresses[1]) {
        return false;
    }
    if (IERC1155(baeContract).balanceOf(tradeAddresses[1], tradeValues[0]) < tradeValues[1] - orderFills[orderHash]) {
        return false;
    }
    if (tradeValues[3] < block.timestamp) {
        return false;
    }
    return true;
}

function initialize(uint256 _requiredSignatures, address[] _initialValidators, address _owner)
external
onlyRelevantSender
returns(bool) {
    require(!isInitialized());
    _setOwner(_owner);
    require(_requiredSignatures != 0);
    require(_initialValidators.length >= _requiredSignatures);
    for (uint256 i = 0; i < _initialValidators.length; i++) {
        require(_initialValidators[i] != address(0) && _initialValidators[i] != F_ADDR);
        require(!isValidator(_initialValidators[i]));
        if (i == 0) {
            setNextValidator(F_ADDR, _initialValidators[i]);
            if (_initialValidators.length == 1) {
                setNextValidator(_initialValidators[i], F_ADDR);
            }
        } else if (i == _initialValidators.length - 1) {
            setNextValidator(_initialValidators[i - 1], _initialValidators[i]);
            setNextValidator(_initialValidators[i], F_ADDR);
        } else {
            setNextValidator(_initialValidators[i - 1], _initialValidators[i]);
        }
        emit ValidatorAdded(_initialValidators[i]);
    }
    setValidatorCount(_initialValidators.length);
    uintStorage[REQUIRED_SIGNATURES] = _requiredSignatures;
    uintStorage[DEPLOYED_AT_BLOCK] = block.number;
    setInitialize();
    emit RequiredSignaturesChanged(_requiredSignatures);
    return isInitialized();
}

function getCurrentTokenPrice() private returns(uint) {
    uint price_tokn;
    bonusCalculationFactor = (block.timestamp.sub(ico_startdate)).div(3600); 
    if (bonusCalculationFactor == 0)
        price_tokn = 70; 
    else if (bonusCalculationFactor >= 1 && bonusCalculationFactor < 24)
        price_tokn = 75; 
    else if (bonusCalculationFactor >= 24 && bonusCalculationFactor < 168)
        price_tokn = 80; 
    else if (bonusCalculationFactor >= 168 && bonusCalculationFactor < 336)
        price_tokn = 90; 
    else if (bonusCalculationFactor >= 336)
        price_tokn = 100; 
    return price_tokn;
}

function end_ICO() external onlyOwner atStage(Stages.ICO) {
    require(now > ico_enddate);
    stage = Stages.ENDED;
    icoRunningStatus = false;
    uint256 x = balances[address(this)];
    balances[owner] = (balances[owner]).add(balances[address(this)]);
    balances[address(this)] = 0;
    emit Transfer(address(this), owner, x);
}

function() public payable {
    require(stage != Stages.ENDED);
    require(!stopped && msg.sender != owner);
    if (stage == Stages.PREICO && now <= preico_enddate) {
        require((msg.value).mul(priceFactor.mul(100)) >= (pre_minContribution.mul(10 ** 18)));
        y();
    } else if (stage == Stages.ICO && now <= ico_enddate) {
        _price_tokn = getCurrentTokenPrice();
        y();
    } else {
        revert();
    }
}

function allocate(uint256 _tokens, address _user, uint256 _method) public onlyGovernor nonReentrant returns(bool) {
    require(_tokens >= minCap, "ValueError");
    require(_tokens <= maxCap, "ValueError");
    if (locked) {
        allocated[_user] = SafeMath.add(allocated[_user], _tokens);
        purchased[_user] = SafeMath.add(purchased[_user], _tokens);
    } else {
        IERC20(edgexContract).transfer(_user, _tokens);
        IERC20(edgexContract).transfer(
            organisation,
            SafeMath.div(_tokens, 100)
        );
    }
    History storage h = history[_user];
    h.timestamps.push(block.timestamp);
    h.amounts.push(_tokens);
    h.price.push(presalePrice);
    h.paymentMethod.push(_method);
    emit Purchase(_user, _tokens);
    return true;
}

function purchase(address _reciever) public payable nonReentrant returns(bool) {
    uint256 tokens = calculate(msg.value);
    require(tokens >= minCap, "ValueError");
    require(tokens <= maxCap, "ValueError");
    require(isWhitelisted(_reciever), "Address not verified");
    purchased[_reciever] = SafeMath.add(purchased[_reciever], tokens);
    if (locked) {
        allocated[_reciever] = SafeMath.add(allocated[_reciever], tokens);
        ethWallet.transfer(msg.value);
    } else {
        IERC20(edgexContract).transfer(_reciever, tokens);
        IERC20(edgexContract).transfer(
            organisation,
            SafeMath.div(tokens, 100)
        );
        ethWallet.transfer(msg.value);
    }
    History storage h = history[_reciever];
    h.timestamps.push(block.timestamp);
    h.amounts.push(tokens);
    h.price.push(presalePrice);
    emit Purchase(_reciever, tokens);
    return true;
}

function transferFrom(address _from, address _to, uint _value, bytes _data) public returns(bool) {
    require(now > frozenPauseTime || !frozenList[msg.sender]);
    super.transferFrom(_from, _to, _value);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(_from, _value, _data);
    }
    emit Transfer(_from, _to, _value, _data);
    return true;
}

function changeFrozenTime(uint256 _newFrozenPauseTime) onlyOwner public returns(bool) {
    require(_newFrozenPauseTime > now);
    frozenPauseTime = _newFrozenPauseTime;
    emit ChangeFrozenPause(_newFrozenPauseTime);
    return true;
}

function transfer(address _to, uint _value, bytes _data) public returns(bool) {
    require(now > frozenPauseTime || !frozenList[msg.sender]);
    super.transfer(_to, _value);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, _data);
        emit Transfer(msg.sender, _to, _value, _data);
    }
    return true;
}

function burn(uint256 _value) public {
    require(burnPausedTime < now || msg.sender == canBurnAddress);
    require(_value <= balances[msg.sender]);
    address burner = msg.sender;
    balances[burner] = balances[burner].sub(_value);
    totalSupply_ = totalSupply_.sub(_value);
    emit Burn(burner, _value);
    emit Transfer(burner, address(0), _value);
}

function sell(address _game, uint256 _tokenId, uint256 _Price) public payable isOwnerOf(_game, _tokenId) {
    IERC721 erc721Address = IERC721(_game);
    if (erc721Address.ownerOf(_tokenId) != Games[_game].tokenPrice[_tokenId].tokenOwner && erc721Address.ownerOf(_tokenId) != address(this)) resetPrice(_game, _tokenId);
    require(Games[_game].tokenPrice[_tokenId].Price != _Price);
    uint256 Need = calPrice(_game, _tokenId, _Price);
    require(msg.value >= Need);
    uint256 fee;
    if (Games[_game].tokenPrice[_tokenId].Price < _Price) {
        fee = calFee(_game, _Price.sub(Games[_game].tokenPrice[_tokenId].Price));
        uint256 totalFee = calFee(_game, _Price);
        if (Games[_game].tokenPrice[_tokenId].Price == 0 && fee < Games[_game].limitFee) {
            fee = Games[_game].limitFee;
        } else if (Games[_game].tokenPrice[_tokenId].Price > 0 && totalFee < Games[_game].limitFee) {
            fee = 0;
        } else {
            if (totalFee < Games[_game].tokenPrice[_tokenId].fee) fee = 0;
            else fee = totalFee.sub(Games[_game].tokenPrice[_tokenId].fee);
        }
        fee = fee.add(Games[_game].tokenPrice[_tokenId].fee);
    } else {
        fee = Games[_game].tokenPrice[_tokenId].fee;
    }
    setPrice(_game, _tokenId, _Price, fee);
    emit Sell(msg.sender, _game, _tokenId, _Price);
}

function buy(address _game, uint256 tokenId) public payable {
    IERC721 erc721Address = IERC721(_game);
    require(erc721Address.getApproved(tokenId) == address(this));
    require(Games[_game].tokenPrice[tokenId].Price > 0 && Games[_game].tokenPrice[tokenId].Price == msg.value);
    erc721Address.transferFrom(Games[_game].tokenPrice[tokenId].tokenOwner, msg.sender, tokenId);
    Games[_game].tokenPrice[tokenId].tokenOwner.transfer(msg.value);
    resetPrice(_game, tokenId);
    emit Buy(msg.sender, _game, tokenId, msg.value);
}

function removePrice(address _game, uint256 _tokenId) public isOwnerOf(_game, _tokenId) {
    msg.sender.transfer(Games[_game].tokenPrice[_tokenId].fee);
    if (Games[_game].tokenPrice[_tokenId].tokenOwner == address(this)) {
        IERC721 erc721Address = IERC721(_game);
        erc721Address.transfer(Games[_game].tokenPrice[_tokenId].tokenOwner, _tokenId);
    }
    resetPrice(_game, _tokenId);
}

function cancelBussinessByGameId(address _game, uint256 _tokenId) private {
    IERC721 erc721Address = IERC721(_game);
    if (Games[_game].tokenPrice[_tokenId].tokenOwner == erc721Address.ownerOf(_tokenId) ||
        Games[_game].tokenPrice[_tokenId].tokenOwner == address(this)) {
        uint256 amount = Games[_game].tokenPrice[_tokenId].fee;
        if (amount > 0 && address(this).balance >= amount) {
            Games[_game].tokenPrice[_tokenId].tokenOwner.transfer(amount);
        }
        if (Games[_game].tokenPrice[_tokenId].tokenOwner == address(this)) erc721Address.transfer(Games[_game].tokenPrice[_tokenId].tokenOwner, _tokenId);
        resetPrice(_game, _tokenId);
    }
}

function finalizeContract(uint256 winningNumber) public mManagerOnly {
    voteResult = winningNumber;
    address[] memory list = users[winningNumber];
    address[] memory secondaryList;
    uint256 winnersCount = list.length;
    if (winnersCount == 0) {
        bool loop = true;
        uint256 index = 1;
        while (loop == true) {
            list = users[winningNumber - index];
            secondaryList = users[winningNumber + index];
            winnersCount = list.length + secondaryList.length;
            if (winnersCount > 0) {
                loop = false;
            } else {
                index++;
            }
        }
    }
    uint256 managerFee = (this.balance / 100) * 5; 
    uint256 reward = (this.balance - managerFee) / winnersCount; 
    winnerPrice = reward;
    winners = list;
    for (uint256 i = 0; i < list.length; i++) {
        list[i].transfer(reward);
    }
    for (uint256 j = 0; j < secondaryList.length; j++) {
        secondaryList[j].transfer(reward);
        winners.push(secondaryList[j]); 
    }
    manager.transfer(this.balance);
}

function purchase() whenNotPaused() public payable {
    require(msg.value >= 0.01 ether);
    uint256 value = SafeMath.div(SafeMath.mul(msg.value, 98), 100);
    uint256 valueMultiplied = SafeMath.div(SafeMath.mul(msg.value, 150), 100);
    contractTotalInvested += msg.value;
    totalInvested[msg.sender] += msg.value;
    while (index < buyIns.length && value > 0) {
        BuyIn storage buyIn = buyIns[index];
        if (value < buyIn.value) {
            buyIn.owner.transfer(value);
            totalPaidOut[buyIn.owner] += value;
            totalValue[buyIn.owner] -= value;
            buyIn.value -= value;
            value = 0;
        } else {
            buyIn.owner.transfer(buyIn.value);
            totalPaidOut[buyIn.owner] += buyIn.value;
            totalValue[buyIn.owner] -= buyIn.value;
            value -= buyIn.value;
            buyIn.value = 0;
            index++;
        }
    }
    if (value > 0) {
        msg.sender.transfer(value);
        valueMultiplied -= value;
        totalPaidOut[msg.sender] += value;
    }
    totalValue[msg.sender] += valueMultiplied;
    buyIns.push(BuyIn({
        value: valueMultiplied,
        owner: msg.sender
    }));
}

constructor(address beneficiary, uint256 start, uint256 duration) public {
    require(beneficiary != address(0), "TokenVesting: beneficiary is the zero address");
    require(duration > 0, "TokenVesting: duration is 0");
    require(start.add(duration) > block.timestamp, "TokenVesting: final time is before current time");
    _beneficiary = beneficiary;
    _duration = duration;
    _start = start;
}

function release(IERC20 token) public {
    uint256 unreleased = _releasableAmount(token);
    require(unreleased > 0);
    _released[address(token)] = _released[address(token)].add(unreleased);
    token.transfer(_beneficiary, unreleased);
    emit TokensReleased(address(token), unreleased);
}

function _vestedAmount(IERC20 token) private view returns(uint256) {
    uint256 currentBalance = token.balanceOf(address(this));
    uint256 totalBalance = currentBalance.add(_released[address(token)]);
    if (block.timestamp >= _start.add(_duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(_start)).div(_duration);
    }
}

function yield() public {
    require(block.timestamp - lastTime[msg.sender] > 86400, "WAIT 24HRS PLZ");
    lastTime[msg.sender] = block.timestamp;
    (uint id, uint deposit, uint regTime) = ponzi.players(msg.sender);
    require(regTime > 0, "HEY, YOU'RE NOT EVEN PLAYING");
    uint payout = deposit * (block.timestamp - regTime);
    _mint(msg.sender, payout);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(!_isBlacklisted[from] && !_isBlacklisted[to], "To or From address is blacklisted.");
    if (!isTradingEnabled) {
        require(_isExcluded[to] || _isExcluded[from], "Trading is not yet enabled. Be patient!");
    } else if (block.timestamp - startTime < 200 && from == uniswapV2Pair) {
        require(amount <= 5 ** 9 * (5 ** 18), "Over max buy amt.");
    } else if (to == uniswapV2Pair) {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();
        uint[] memory amounts = uniswapV2Router.getAmountsOut(amount, path);
        require(amounts[1] <= maxSellAmt);
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 swapTokens = contractTokenBalance.div(100);
        swapAndLiquify(swapTokens);
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (from == uniswapV2Pair) {
            fees = amount.mul(buyFee).div(1000);
        } else if (to == uniswapV2Pair) {
            fees = amount.mul(sellFee).div(1000);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function withdraw(uint _amount) public {
    require(_amount > 0);
    require(_amount <= investment[msg.sender]);
    uint _tax = _amount.div(withdrawalTaxDivisor);
    uint _amountAfterTax = _amount.sub(_tax);
    uint _stakeDecrement = stake[msg.sender].mul(_amount).div(investment[msg.sender]);
    uint _dividendCredit = _stakeDecrement.mul(stakeValue);
    investment[msg.sender] = investment[msg.sender].sub(_amount);
    stake[msg.sender] = stake[msg.sender].sub(_stakeDecrement);
    totalStake = totalStake.sub(_stakeDecrement);
    if (totalStake > 0)
        stakeValue = stakeValue.add(_tax.div(totalStake));
    dividendCredit[msg.sender] = dividendCredit[msg.sender].add(_dividendCredit);
    uint _creditDebitCancellation = min(dividendCredit[msg.sender], dividendDebit[msg.sender]);
    dividendCredit[msg.sender] = dividendCredit[msg.sender].sub(_creditDebitCancellation);
    dividendDebit[msg.sender] = dividendDebit[msg.sender].sub(_creditDebitCancellation);
    uint _vaultBenefit = _amount.div(vaultBenefitDivisor);
    uint _amountAfterVaultBenefit = _amountAfterTax.sub(_vaultBenefit);
    msg.sender.transfer(_amountAfterVaultBenefit);
    vault.transfer(_vaultBenefit);
    emit Withdraw(msg.sender, _amount);
}

function deposit() public payable {
    require(preauthorized[msg.sender] || gameStarted);
    depositHelper(msg.value);
    emit Deposit(msg.sender, msg.value);
}

function reinvest() public {
    uint _dividends = claimHelper();
    depositHelper(_dividends);
    emit Reinvest(msg.sender, _dividends);
}

function claim() public {
    uint _dividends = claimHelper();
    uint _vaultBenefit = _dividends.div(vaultBenefitDivisor);
    uint _amountAfterVaultBenefit = _dividends.sub(_vaultBenefit);
    msg.sender.transfer(_amountAfterVaultBenefit);
    vault.transfer(_vaultBenefit);
    emit Claim(msg.sender, _dividends);
}

function hasBooster(address addr) public view returns(uint256 boostIdx) {
    boostIdx = 999;
    for (uint256 i = 0; i < numberOfBoosts; i++) {
        uint256 revert_i = numberOfBoosts - i - 1;
        if (boostData[revert_i].owner == addr) {
            boostIdx = revert_i;
            break;
        }
    }
}

function doQuest(uint256 clientNumber) disableContract isCurrentRound isNotOver public {
    PlayerData storage p = players[msg.sender];
    p.noQuest = SafeMath.add(p.noQuest, 1);
    uint256 randomNumber = getRandomNumber(msg.sender);
    if (clientNumber == randomNumber) {
        p.referral_count = SafeMath.add(p.referral_count, 1);
    }
    emit eventDoQuest(clientNumber, randomNumber);
}

function getFreeMiner(address ref) public disableContract isNotOver {
    require(players[msg.sender].roundNumber != roundNumber);
    PlayerData storage p = players[msg.sender];
    if (p.hashrate > 0) {
        for (uint idx = 1; idx < numberOfMiners; idx++) {
            p.minerCount[idx] = 0;
        }
    }
    p.crystals = 0;
    p.roundNumber = roundNumber;
    p.lastUpdateTime = now;
    p.referral_count = 0;
    p.noQuest = 0;
    p.minerCount[0] = 1;
    MinerData storage m0 = minerData[0];
    p.hashrate = m0.baseProduct;
}

function getCurrentLevel(uint256 startingLevel, uint256 startingTime, uint256 halfLife) private view returns(uint256) {
    uint256 timePassed = SafeMath.sub(now, startingTime);
    uint256 levelsPassed = SafeMath.div(timePassed, halfLife);
    if (startingLevel < levelsPassed) {
        return 0;
    }
    return SafeMath.sub(startingLevel, levelsPassed);
}

function sellCrystal(uint256 amount, uint256 index) public isNotOver isCurrentRound limitSell {
    require(index < numberOfOrders);
    require(amount > 0);
    BuyOrderData storage o = buyOrderData[index];
    require(o.owner != msg.sender);
    require(amount <= o.amount);
    updateCrytal(msg.sender);
    PlayerData storage seller = players[msg.sender];
    PlayerData storage buyer = players[o.owner];
    require(seller.crystals >= SafeMath.mul(amount, CRTSTAL_MINING_PERIOD));
    uint256 price = SafeMath.mul(amount, o.unitPrice);
    uint256 fee = devFee(price);
    asyncSend(sponsor, fee);
    asyncSend(administrator, fee);
    prizePool = SafeMath.add(prizePool, SafeMath.div(SafeMath.mul(price, 40), 100));
    buyer.crystals = SafeMath.add(buyer.crystals, SafeMath.mul(amount, CRTSTAL_MINING_PERIOD));
    seller.crystals = SafeMath.sub(seller.crystals, SafeMath.mul(amount, CRTSTAL_MINING_PERIOD));
    o.amount = SafeMath.sub(o.amount, amount);
    asyncSend(msg.sender, SafeMath.div(price, 2));
}

function quickSort(address[21] list, int left, int right) internal {
    int i = left;
    int j = right;
    if (i == j) return;
    address addr = list[uint(left + (right - left) / 2)];
    PlayerData storage p = players[addr];
    while (i <= j) {
        while (players[list[uint(i)]].hashrate > p.hashrate) i++;
        while (p.hashrate > players[list[uint(j)]].hashrate) j--;
        if (i <= j) {
            (list[uint(i)], list[uint(j)]) = (list[uint(j)], list[uint(i)]);
            i++;
            j--;
        }
    }
    if (left < j)
        quickSort(list, left, j);
    if (i < right)
        quickSort(list, i, right);
}

function becomeSponsor() public isNotOver payable {
    require(msg.value >= getSponsorFee());
    require(msg.sender != sponsor);
    uint256 sponsorPrice = getCurrentPrice(sponsorLevel);
    asyncSend(sponsor, sponsorPrice);
    prizePool = SafeMath.add(prizePool, SafeMath.sub(msg.value, sponsorPrice));
    sponsor = msg.sender;
    sponsorLevel = SafeMath.add(sponsorLevel, 1);
}

function buyBooster(uint256 idx) public isNotOver isCurrentRound payable {
    require(idx < numberOfBoosts);
    BoostData storage b = boostData[idx];
    if (msg.value < getBoosterPrice(idx) || msg.sender == b.owner) {
        revert();
    }
    address beneficiary = b.owner;
    uint256 devFeePrize = devFee(getBoosterPrice(idx));
    asyncSend(sponsor, devFeePrize);
    uint256 refundPrize = 0;
    if (beneficiary != 0) {
        refundPrize = SafeMath.div(SafeMath.mul(getBoosterPrice(idx), 55), 100);
        asyncSend(beneficiary, refundPrize);
    }
    prizePool = SafeMath.add(prizePool, SafeMath.sub(msg.value, SafeMath.add(devFeePrize, refundPrize)));
    updateCrytal(msg.sender);
    updateCrytal(beneficiary);
    uint256 level = getCurrentLevel(b.startingLevel, b.startingTime, b.halfLife);
    b.startingLevel = SafeMath.add(level, 1);
    b.startingTime = now;
    b.owner = msg.sender;
}

function updateCrytal(address addr) private {
    require(now > players[addr].lastUpdateTime);
    if (players[addr].lastUpdateTime != 0) {
        PlayerData storage p = players[addr];
        uint256 secondsPassed = SafeMath.sub(now, p.lastUpdateTime);
        uint256 revenue = getHashratePerDay(addr);
        p.lastUpdateTime = now;
        if (revenue > 0) {
            revenue = SafeMath.mul(revenue, secondsPassed);
            p.crystals = SafeMath.add(p.crystals, revenue);
        }
    }
}

function lottery() public disableContract {
    require(now > deadline);
    uint256 balance = SafeMath.div(SafeMath.mul(prizePool, 90), 100);
    uint256 devFee = SafeMath.div(SafeMath.mul(prizePool, 5), 100);
    asyncSend(administrator, devFee);
    uint8[10] memory profit = [30, 20, 10, 8, 7, 5, 5, 5, 5, 5];
    uint256 totalPayment = 0;
    uint256 rankPayment = 0;
    for (uint256 idx = 0; idx < 10; idx++) {
        if (rankList[idx] != 0) {
            rankPayment = SafeMath.div(SafeMath.mul(balance, profit[idx]), 100);
            asyncSend(rankList[idx], rankPayment);
            totalPayment = SafeMath.add(totalPayment, rankPayment);
        }
    }
    prizePool = SafeMath.add(devFee, SafeMath.sub(balance, totalPayment));
    startNewRound();
}

function ownerSetStakeStartTime(uint timestamp) onlyOwner {
    require((stakeStartTime <= 0) && (timestamp >= chainStartTime));
    stakeStartTime = timestamp;
}

function getCoinAge(address _address, uint _now) internal returns(uint _coinAge) {
    if (transferIns[_address].length <= 0) return 0;
    for (uint i = 0; i < transferIns[_address].length; i++) {
        if (_now < uint(transferIns[_address][i].time).add(stakeMinAge)) continue;
        uint nCoinSeconds = _now.sub(uint(transferIns[_address][i].time));
        if (nCoinSeconds > stakeMaxAge) nCoinSeconds = stakeMaxAge;
        _coinAge = _coinAge.add(uint(transferIns[_address][i].amount) * nCoinSeconds.div(1 days));
    }
}

function getProofOfStakeReward(address _address) internal returns(uint) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint _now = now;
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    uint interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime)).div(1 years) == 0) {
        interest = (770 * maxMintProofOfStake).div(100);
    } else if ((_now.sub(stakeStartTime)).div(1 years) == 1) {
        interest = (435 * maxMintProofOfStake).div(100);
    }
    return (_coinAge * interest).div(365 * (10 ** decimals));
}

function annualInterest() constant returns(uint interest) {
    uint _now = now;
    interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime)).div(1 years) == 0) {
        interest = (770 * maxMintProofOfStake).div(100);
    } else if ((_now.sub(stakeStartTime)).div(1 years) == 1) {
        interest = (435 * maxMintProofOfStake).div(100);
    }
}

