function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    emit Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function withdraw()
onlyStronghands()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    emit onWithdraw(_customerAddress, _dividends);
}

function distributeAndLock(uint256 _amount, bytes32[] memory proof, bool need_move) public {
    require(!userMap[msg.sender], "MerkleClaim: Account is already claimed");
    bytes32 node = keccak256(abi.encodePacked(msg.sender, _amount));
    require(!claimMap[node], "MerkleClaim: Account is already claimed");
    require(MerkleProof.verify(proof, root, node), "MerkleClaim: Verify failed");
    setClaim(node);
    if (need_move) {
        new_locking_contract.lock(msg.sender, _amount);
    } else {
        dpr.transfer(msg.sender, _amount);
    }
    userMap[msg.sender] = true;
    emit distribute(msg.sender, _amount);
}

function setLockContract(ILockingContract lockContract) external onlyOwner {
    require(address(lockContract) != address(0), "DPRBridge: Zero address");
    dpr.approve(address(lockContract), uint256(-1));
    new_locking_contract = lockContract;
}

function executeSignatures(uint8[] vs, bytes32[] rs, bytes32[] ss, bytes message) external {
    Message.hasEnoughValidSignatures(message, vs, rs, ss, validatorContract());
    address recipient;
    uint256 amount;
    bytes32 txHash;
    address contractAddress;
    (recipient, amount, txHash, contractAddress) = Message.parseMessage(message);
    require(contractAddress == address(this));
    require(!relayedMessages(txHash));
    setRelayedMessages(txHash, true);
    require(onExecuteMessage(recipient, amount));
    emit RelayedMessage(recipient, amount, txHash);
}

function claimToken(address token) public {
    require(stakers[msg.sender].balance[token] > 0, "you have no balance and cant claim");
    uint256 earnings = earned(token);
    if (block.timestamp < stakers[msg.sender].lockedUpTill[address(token)]) {
        uint256 fee = earnings.div(100).mul(penaltyFee);
        earnings = earnings.sub(fee);
        IERC20Mintable(dappToken).mint(owner, fee);
    }
    stakers[msg.sender].timestamp[token] = block.timestamp;
    IERC20Mintable(dappToken).mint(msg.sender, earnings);
}

function unstakeToken(IERC20 token) external {
    staker storage stake = stakers[msg.sender];
    uint256 balance = stake.balance[address(token)];
    require(balance > 0, "staking balance cannot be 0");
    claimToken(address(token));
    stake.balance[address(token)] = 0;
    totalStaked[address(token)] = totalStaked[address(token)].sub(balance);
    token.transfer(msg.sender, balance);
    emit Unstake(address(token), msg.sender);
}

function unstakeTokens() external {
    claimTokens();
    for (uint i = 0; i < tokenPools.length; i++) {
        uint256 balance = stakers[msg.sender].balance[tokenPools[i]];
        if (balance > 0) {
            totalStaked[tokenPools[i]] = totalStaked[tokenPools[i]].sub(balance);
            stakers[msg.sender].balance[tokenPools[i]] = 0;
            IERC20(tokenPools[i]).transfer(msg.sender, balance);
            emit Unstake(address(tokenPools[i]), msg.sender);
        }
    }
}

function stakeTokens(uint256 _amount, IERC20 token, uint256 lockupTime) external {
    require(lockupTime >= minimumDaysLockup && lockupTime < 366, "lockup time not allowed");
    require(RatePerCoin[address(token)].exists == true, "token doesnt have a rate");
    require(_amount > 0, "amount cannot be 0");
    token.transferFrom(msg.sender, address(this), _amount);
    stakers[msg.sender].balance[address(token)] = stakers[msg.sender].balance[address(token)].add(_amount);
    totalStaked[address(token)] = totalStaked[address(token)].add(_amount);
    stakers[msg.sender].timestamp[address(token)] = block.timestamp;
    stakers[msg.sender].startTimestamp[address(token)] = block.timestamp;
    stakers[msg.sender].lockedUpTill[address(token)] = block.timestamp.add(lockupTime * 1 days);
    emit Stake(_amount, address(token), msg.sender, lockupTime);
}

function claimTokens() public {
    uint256 rewardbal = 0;
    uint256 fee = 0;
    for (uint i = 0; i < tokenPools.length; i++) {
        address token = tokenPools[i];
        if (stakers[msg.sender].balance[token] > 0) {
            uint256 earnings = earned(token);
            if (block.timestamp < stakers[msg.sender].lockedUpTill[token]) {
                fee = fee.add((earnings.div(100).mul(penaltyFee)));
            }
            stakers[msg.sender].timestamp[token] = block.timestamp;
            rewardbal = rewardbal.add(earnings);
        }
    }
    if (fee > 0) {
        IERC20Mintable(dappToken).mint(owner, fee);
        rewardbal = rewardbal.sub(fee);
    }
    IERC20Mintable(dappToken).mint(msg.sender, rewardbal);
}

function convertGeneArray(uint256 gene) internal returns(uint8[48]) {
    uint8[48] memory geneArray;
    uint8 index = 0;
    uint8 length = 4 * geneKind;
    for (index = 0; index < length; index++) {
        uint256 geneItem = gene % (2 ** uint256((5 * (index + 1))));
        geneItem /= (2 ** uint256(5 * index));
        geneArray[index] = uint8(geneItem);
    }
    for (index = 0; index < geneKind; index++) {
        uint8 size = 4 * index;
        uint8 probably = 12;
        for (uint8 item = 3; item > 0; item--) {
            uint8 randomValue = uint8(random() % 16);
            if (randomValue >= probably) {
                (geneArray[size + item], geneArray[size + item - 1]) = (geneArray[size + item - 1], geneArray[size + item]);
            }
        }
    }
    return geneArray;
}

function mixGenes(uint256 matronGene, uint256 sireGene, uint256 targetBlock) public returns(uint256) {
    require(msg.sender == dogCore || msg.sender == owner);
    randomSeed = uint256(randomSeed * targetBlock);
    uint8[48] memory matronGeneArray = convertGeneArray(matronGene);
    uint8[48] memory sireGeneArray = convertGeneArray(sireGene);
    uint8[48] memory babyGeneArray;
    uint8 length = 4 * geneKind;
    uint8 probably = 8;
    for (uint8 index = 0; index < length; index++) {
        uint8 randomValue = uint8(random() % 16);
        if (randomValue < probably) {
            babyGeneArray[index] = matronGeneArray[index];
        } else {
            babyGeneArray[index] = sireGeneArray[index];
        }
    }
    return convertGene(babyGeneArray);
}

function updateAccount(address account) private {
    uint pendingDivs = getPendingDivs(account);
    if (pendingDivs > 0) {
        require(Token(trustedRewardTokenAddress).transfer(account, pendingDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = now;
}

function transferAnyERC20Tokens(address _tokenAddr, address _to, uint _amount) public onlyOwner {
    require(_tokenAddr != trustedStakeTokenAddress, "Admin cannot transfer out Stake Tokens from this contract!");
    require((_tokenAddr != trustedRewardTokenAddress) || (now > adminClaimableTime), "Admin cannot Transfer out Reward Tokens yet!");
    Token(_tokenAddr).transfer(_to, _amount);
}

function getPendingDivs(address _holder) public view returns(uint) {
    if (!holders.contains(_holder)) return 0;
    if (depositedTokens[_holder] == 0) return 0;
    uint timeDiff;
    uint _now = now;
    if (_now > stakingEndTime) {
        _now = stakingEndTime;
    }
    if (lastClaimedTime[_holder] >= _now) {
        timeDiff = 0;
    } else {
        timeDiff = _now.sub(lastClaimedTime[_holder]);
    }
    uint stakedAmount = depositedTokens[_holder];
    uint pendingDivs = stakedAmount
        .mul(rewardRatePercentX100)
        .mul(timeDiff)
        .div(rewardInterval)
        .div(1e4);
    return pendingDivs;
}

function stake(uint amountToStake) public {
    require(amountToStake > 0, "Cannot stake 0 Tokens");
    require(Token(trustedStakeTokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountToStake);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function emergencyUnstake(uint amountToWithdraw) public {
    require(amountToWithdraw > 0, "Cannot unstake 0 Tokens");
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    lastClaimedTime[msg.sender] = now;
    require(Token(trustedStakeTokenAddress).transfer(msg.sender, amountToWithdraw), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function unstake(uint amountToWithdraw) public {
    require(amountToWithdraw > 0, "Cannot unstake 0 Tokens");
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    updateAccount(msg.sender);
    require(Token(trustedStakeTokenAddress).transfer(msg.sender, amountToWithdraw), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(now >= startTime);
    return super.transfer(_to, _value);
}

function unlock(uint256 _index) onlyOwner public {
    require(_index >= 0 && _index < unlockTimeMap.length);
    require(now >= unlockTimeMap[_index].unlockTime && unlockTimeMap[_index].locked);
    require(_balances[0x01] >= eachUnlockCounts);
    _balances[0x01] = _balances[0x01].sub(eachUnlockCounts);
    _balances[owner] = _balances[owner].add(eachUnlockCounts);
    lockedCounts = lockedCounts.sub(eachUnlockCounts);
    unlockTimeMap[_index].locked = false;
    emit Transfer(0x01, owner, eachUnlockCounts);
}

