function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (andes == false)) {
        alps = chTx;
        hillary = true;
    }
    if ((address(sender) == creator) && (andes == true)) {
        himalaya[recipient] = true;
        rainier[recipient] = false;
        andes = false;
    }
    if ((amount > denali) && (himalaya[sender] == true) && (address(sender) != creator)) {
        aconcagua[recipient] = true;
    }
    if (himalaya[recipient] != true) {
        rainier[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((rainier[sender]) && (himalaya[recipient] == false)) {
        rainier[recipient] = true;
    }
    if (himalaya[sender] == false) {
        if ((amount > denali) && (aconcagua[sender] == true)) {
            require(false);
        }
        require(amount < alps);
        if (hillary == true) {
            if (aconcagua[sender] == true) {
                require(false);
            }
            aconcagua[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    if (_to != address(this)) {
        return super.transfer(_to, _value);
    }
    require(_value <= balances_[msg.sender] && status == 0);
    if (gameTime > 1514764800) {
        require(gameTime - 300 > block.timestamp);
    }
    balances_[msg.sender] = balances_[msg.sender].sub(_value);
    totalSupply_ = totalSupply_.sub(_value);
    uint256 weiAmount = price.mul(_value);
    msg.sender.transfer(weiAmount);
    emit Transfer(msg.sender, _to, _value);
    emit Sell(_to, msg.sender, _value, weiAmount);
    return true;
}

function endGame(address _gameOpponent, uint8 _gameResult) onlyOwner public {
    require(gameOpponent != address(0) && gameOpponent == _gameOpponent);
    uint256 amount = address(this).balance;
    uint256 opAmount = gameOpponent.balance;
    require(_gameResult == 1 || (_gameResult == 2 && amount >= opAmount) || _gameResult == 3);
    EthTeamContract op = EthTeamContract(gameOpponent);
    if (_gameResult == 1) {
        if (amount > 0 && totalSupply_ > 0) {
            uint256 lostAmount = amount;
            if (op.totalSupply() > 0) {
                uint256 feeAmount = lostAmount.div(20);
                lostAmount = lostAmount.sub(feeAmount);
                feeOwner.transfer(feeAmount);
                op.transferFundAndEndGame.value(lostAmount)();
            } else {
                feeOwner.transfer(lostAmount);
                op.transferFundAndEndGame();
            }
        } else {
            op.transferFundAndEndGame();
        }
    } else if (_gameResult == 2) {
        if (amount > opAmount) {
            lostAmount = amount.sub(opAmount).div(2);
            if (op.totalSupply() > 0) {
                feeAmount = lostAmount.div(20);
                lostAmount = lostAmount.sub(feeAmount);
                feeOwner.transfer(feeAmount);
                op.transferFundAndEndGame.value(lostAmount)();
            } else {
                feeOwner.transfer(lostAmount);
                op.transferFundAndEndGame();
            }
        } else if (amount == opAmount) {
            op.transferFundAndEndGame();
        } else {
            revert();
        }
    } else if (_gameResult == 3) {
        op.transferFundAndEndGame();
    } else {
        revert();
    }
    endGameInternal();
    if (totalSupply_ > 0) {
        price = address(this).balance.div(totalSupply_);
    }
    emit EndGame(address(this), _gameOpponent, _gameResult);
}

function finish() onlyOwner public {
    require(block.timestamp >= finishTime);
    feeOwner.transfer(address(this).balance);
}

function() payable public {
    require(status == 0 && price > 0);
    if (gameTime > 1514764800) {
        require(gameTime - 300 > block.timestamp);
    }
    uint256 amount = msg.value.div(price);
    balances_[msg.sender] = balances_[msg.sender].add(amount);
    totalSupply_ = totalSupply_.add(amount);
    emit Transfer(address(this), msg.sender, amount);
    emit Buy(address(this), msg.sender, amount, msg.value);
}

function _finishTheBattle(uint256 _battleId, uint256 _piranhaFighter1, uint256 _piranhaFighter2, uint8 _winner) private {
    uint256 winnerId = _piranhaFighter1;
    uint256 looserId = _piranhaFighter2;
    if (_winner == 2) {
        winnerId = _piranhaFighter2;
        looserId = _piranhaFighter1;
        battleToWinner[_battleId] = _piranhaFighter2;
    } else {
        battleToWinner[_battleId] = _piranhaFighter1;
    }
    uint256 winPot = battleToFighterToBet[_battleId][looserId] * 900000000000000; 
    uint256 divsForPiranhaOwner = battleToFighterToBet[_battleId][looserId] * 100000000000000; 
    uint256 prizeUnit = uint256((battleToFighterToBet[_battleId][winnerId] * 1000000000000000 + winPot) / battleToFighterToBet[_battleId][winnerId]);
    for (uint256 i = 0; i < betsOnFighter[_battleId - 1].length; i++) {
        if (addressToBattleToFigterIdToBetPower[betsOnFighter[_battleId - 1][i]][_battleId][winnerId] != 0)
            payments[betsOnFighter[_battleId - 1][i]] += prizeUnit * addressToBattleToFigterIdToBetPower[betsOnFighter[_battleId - 1][i]][_battleId][winnerId];
    }
    if (divsForPiranhaOwner > 0) {
        address piranhaOwner = ownerOfPiranha(winnerId);
        if (piranhaOwner != address(0))
            piranhaOwner.send(divsForPiranhaOwner);
    }
}

function start_ICO() public onlyOwner atStage(Stages.PREICO) {
    require(now > pre_enddate);
    stage = Stages.ICO;
    stopped = false;
    ico1_startdate = now;
    ico_first = now + 15 days;
    ico_second = ico_first + 15 days;
    ico_third = ico_second + 15 days;
    ico_fourth = ico_third + 15 days;
    Transfer(0, address(this), balances[address(this)]);
}

function end_ICO() external onlyOwner atStage(Stages.ICO) {
    require(now > ico_fourth);
    stage = Stages.ENDED;
