function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 2;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 3 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 50 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 75 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 25 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 50 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 666888e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

function register()
public {
    address _customerAddress = msg.sender;
    require(!playerRegistered[_customerAddress]);
    BTCTKN.transferFrom(_customerAddress, address(this), entryFee);
    registeredPlayers = SafeMath.addint256(registeredPlayers, 1);
    playerRegistered[_customerAddress] = true;
    playerGamesScored[_customerAddress] = 0;
    playerList.push(_customerAddress);
    require(playerRegistered[_customerAddress]);
    prizePool = prizePool.add(ninetyPercent);
    givethPool = givethPool.add(fivePercent);
    adminPool = adminPool.add(fivePercent);
    emit Registration(_customerAddress);
}

function refund(address _investor) external {
    require(state == State.Refunding);
    uint256 depositedValue = deposited[step][_investor];
    require(depositedValue > 0);
    deposited[step][_investor] = 0;
    _investor.transfer(depositedValue);
    emit Refunded(_investor, depositedValue);
}

function getPartnerCash(uint8 _user, address _msgsender) external canGetCash {
    require(rightAndRoles.onlyRoles(msg.sender, 1));
    require(_user < wallets.length);
    onlyPartnersOrAdmin(_msgsender);
    uint256 move = ready[_user];
    if (move == 0) return;
    emit Receive(wallets[_user], move);
    ready[_user] = 0;
    took[_user] += move;
    wallets[_user].transfer(move);
}

function getBeneficiaryCash() external canGetCash {
    require(rightAndRoles.onlyRoles(msg.sender, 1));
    address _beneficiary = rightAndRoles.wallets(2, 0);
    uint256 move = benReady;
    benWallet = _beneficiary;
    if (move == 0) return;
    emit Receive(_beneficiary, move);
    benReady = 0;
    benTook += move;
    _beneficiary.transfer(move);
}

function deposit(address _investor) external payable {
    require(rightAndRoles.onlyRoles(msg.sender, 1));
    require(state == State.Active);
    deposited[step][_investor] = deposited[step][_investor].add(msg.value);
    newCash = newCash.add(msg.value);
    cashHistory += msg.value;
    emit Deposited(_investor, msg.value);
}

function setup(uint8 _state, bytes32[] _params) external {
    require(rightAndRoles.onlyRoles(msg.sender, 1));
    if (_state == 0) {
        require(_params.length == 1);
        selfdestruct(address(_params[0]));
    } else if (_state == 1) {
        require(_params.length == 0);
        require(state == State.Active);
        state = State.Closed;
        emit Closed();
    } else if (_state == 2) {
        require(_params.length == 0);
        require(state == State.Closed);
        require(address(this).balance == 0);
        state = State.Active;
        step++;
        emit Started();
    } else if (_state == 3) {
        require(_params.length == 0);
        require(state == State.Active);
        state = State.Refunding;
        emit RefundsEnabled();
    } else if (_state == 4) {
        require(_params.length == 2);
        internalCalc(uint256(_params[0]));
    } else if (_state == 5) {
        require(_params.length == 2);
        for (uint8 user = 0; user < cap.length; user++) cap[user] = cap[user].mul(uint256(_params[0])).div(uint256(_params[1]));
    }
}

function isPreSale() internal view returns(bool) {
    if (now >= startDate && now < endPreICO && preIcoCap.sub(stat.currentFundraiser) > 0) {
        return true;
    } else {
        return false;
    }
}

function isMainSale() internal view returns(bool) {
    if (now >= startICO && now < endDate) {
        return true;
    } else {
        return false;
    }
}

function currentStepIndexByDate() internal view returns(uint8 roundNum) {
    require(now <= endPreICO);
    if (now > preSale3) return 3;
    if (now > preSale5) return 2;
    if (now > preSale10) return 1;
    if (now > preSale20) return 0;
    else return 0;
}

function buyTokens() internal {
    require(msg.value >= 0.001 ether);
    uint256 tokens;
    uint256 xAmount = msg.value;
    uint256 toReturnEth;
    uint256 toTokensReturn;
    uint256 balanceIco;
    if (isPreSale()) {
        balanceIco = preIcoCap.sub(stat.currentFundraiser);
        tokens = computeTokenAmountAll(xAmount);
        if (balanceIco < tokens) {
            uint8 roundNum = currentStepIndexAll();
            toTokensReturn = tokens.sub(balanceIco);
            toReturnEth = (toTokensReturn.mul((100 - (StepDiscount[roundNum]))).div(100)).div(tokenRate);
        }
    } else if (isMainSale()) {
        balanceIco = IcoCap.add(preIcoCap);
        balanceIco = balanceIco.sub(stat.currentFundraiser);
        tokens = xAmount.mul(tokenRate);
        if (balanceIco < tokens) {
            toTokensReturn = tokens.sub(balanceIco);
            toReturnEth = toTokensReturn.mul(tokenRate);
        }
    } else {
        revert();
    }
    if (tokens > 0) {
        if (balanceIco < tokens) {
            msg.sender.transfer(toReturnEth);
            _EnvoisTokens(balanceIco, xAmount - toReturnEth);
        } else {
            _EnvoisTokens(tokens, xAmount);
        }
    } else {
        revert();
    }
}

function addVesting(address[] _beneficiary, uint256[] _token, uint256[] _vestingTime)
external
onlyOwner {
    require((_beneficiary.length == _token.length) && (_beneficiary.length == _vestingTime.length));
    for (uint i = 0; i < _beneficiary.length; i++) {
        require(_vestingTime[i] > now);
        require(checkZeroValue(_token[i]));
        require(uint256(getBalance()) >= totalTokenVested.add(_token[i]));
        vestingObj[_beneficiary[i]].push(VestingObj({
            token: _token[i],
            releaseTime: _vestingTime[i]
        }));
        totalTokenVested = totalTokenVested.add(_token[i]);
        emit AddVesting(_beneficiary[i], _token[i], _vestingTime[i]);
    }
}

function claim() external {
    uint256 transferTokenCount = 0;
    for (uint i = 0; i < vestingObj[msg.sender].length; i++) {
        if (now >= vestingObj[msg.sender][i].releaseTime) {
            transferTokenCount = transferTokenCount.add(vestingObj[msg.sender][i].token);
            delete vestingObj[msg.sender][i];
        }
    }
    require(transferTokenCount > 0);
    token.safeTransfer(msg.sender, transferTokenCount);
    emit Release(msg.sender, transferTokenCount, now);
}

function _offerState(Subscription storage sub) internal constant returns(OfferState status) {
    if (!_isOffer(sub)) {
        return OfferState.NOT_EXIST;
    } else if (sub.startOn > now) {
        return OfferState.BEFORE_START;
    } else if (sub.onHoldSince > 0) {
        return OfferState.ON_HOLD;
    } else if (now <= sub.expireOn) {
        return sub.execCounter > 0 ?
            OfferState.ACTIVE :
            OfferState.SOLD_OUT;
    } else {
        return OfferState.EXPIRED;
    }
}

function unholdSubscriptionOffer(uint offerId) public returns(bool success) {
    Subscription storage offer = subscriptions[offerId];
    assert(_isOffer(offer));
    require(msg.sender == offer.transferTo || msg.sender == owner); 
    if (offer.onHoldSince > 0) {
        offer.onHoldSince = 0;
        OfferOnHold(offerId, false, msg.sender);
        return true;
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function returnSubscriptionDesposit(uint subId) public {
    Subscription storage sub = subscriptions[subId];
    assert(_subscriptionState(sub) == SubState.CANCELED);
    assert(sub.depositAmount > 0); 
    assert(sub.transferTo == msg.sender || owner == msg.sender); 
    sub.expireOn = now;
    _returnSubscriptionDesposit(subId, sub);
}

function createSubscription(uint _offerId, uint _expireOn, uint _startOn) public noReentrancy(L02) returns(uint newSubId) {
    assert(_startOn < _expireOn);
    Subscription storage offer = subscriptions[_offerId];
    assert(_isOffer(offer));
    assert(offer.startOn == 0 || offer.startOn <= now);
    assert(offer.expireOn == 0 || offer.expireOn >= now);
    assert(offer.onHoldSince == 0);
    assert(offer.execCounter > 0);
    --offer.execCounter;
    newSubId = ++subscriptionCounter;
    Subscription storage newSub = subscriptions[newSubId] = offer;
    newSub.transferFrom = msg.sender;
    newSub.execCounter = 0;
    newSub.paidUntil = newSub.startOn = max(_startOn, now); 
    newSub.expireOn = _expireOn;
    newSub.depositAmount = _applyXchangeRate(newSub.depositAmount, newSub); 
    assert(san._burnForDeposit(msg.sender, newSub.depositAmount));
    assert(ServiceProvider(newSub.transferTo).onSubNew(newSubId, _offerId)); 
    NewSubscription(newSub.transferFrom, newSub.transferTo, _offerId, newSubId);
    return newSubId;
}

function unholdSubscription(uint subId) public noReentrancy(L05) returns(bool success) {
    Subscription storage sub = subscriptions[subId];
    assert(_isSubscription(sub));
    var _to = sub.transferTo;
    require(msg.sender == _to || msg.sender == sub.transferFrom); 
    if (sub.onHoldSince > 0) {
        if (msg.sender == _to || ServiceProvider(_to).onSubUnHold(subId, msg.sender, false)) { 
            sub.paidUntil += now - sub.onHoldSince;
            sub.onHoldSince = 0;
            SubOnHold(subId, false, msg.sender);
            return true;
        }
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function cancelSubscription(uint subId, uint gasReserve) public noReentrancy(L03) {
    Subscription storage sub = subscriptions[subId];
    assert(sub.transferFrom == msg.sender || owner == msg.sender); 
    assert(_isSubscription(sub));
    var _to = sub.transferTo;
    sub.expireOn = max(now, sub.paidUntil);
    if (msg.sender != _to) {
        gasReserve = max(gasReserve, 10000); 
        assert(msg.gas > gasReserve); 
        if (_to.call.gas(msg.gas - gasReserve)(bytes4(sha3("onSubCanceled(uint256,address)")), subId, msg.sender)) { 
        }
    }
    SubCanceled(subId, msg.sender);
}

function holdSubscriptionOffer(uint offerId) public returns(bool success) {
    Subscription storage offer = subscriptions[offerId];
    assert(_isOffer(offer));
    require(msg.sender == offer.transferTo || msg.sender == owner); 
    if (offer.onHoldSince == 0) {
        offer.onHoldSince = now;
        OfferOnHold(offerId, true, msg.sender);
        return true;
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function _subscriptionState(Subscription storage sub) internal constant returns(SubState status) {
    if (!_isSubscription(sub)) {
        return SubState.NOT_EXIST;
    } else if (sub.startOn > now) {
        return SubState.BEFORE_START;
    } else if (sub.onHoldSince > 0) {
        return SubState.ON_HOLD;
    } else if (sub.paidUntil >= sub.expireOn) {
        return now < sub.expireOn ?
            SubState.CANCELED :
            sub.depositAmount > 0 ?
            SubState.EXPIRED :
            SubState.FINALIZED;
    } else if (sub.paidUntil <= now) {
        return SubState.CHARGEABLE;
    } else {
        return SubState.PAID;
    }
}

function cancelSubscriptionOffer(uint offerId) public returns(bool) {
    Subscription storage offer = subscriptions[offerId];
    assert(_isOffer(offer));
    assert(offer.transferTo == msg.sender || owner == msg.sender); 
    if (offer.expireOn > now) {
        offer.expireOn = now;
        OfferCanceled(offerId, msg.sender);
        return true;
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function postponeDueDate(uint subId, uint newDueDate) public returns(bool success) {
    Subscription storage sub = subscriptions[subId];
    assert(_isSubscription(sub));
    assert(sub.transferTo == msg.sender); 
    if (sub.paidUntil < newDueDate) {
        sub.paidUntil = newDueDate;
        return true;
    } else if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function holdSubscription(uint subId) public noReentrancy(L04) returns(bool success) {
    Subscription storage sub = subscriptions[subId];
    assert(_isSubscription(sub));
    var _to = sub.transferTo;
    require(msg.sender == _to || msg.sender == sub.transferFrom); 
    if (sub.onHoldSince == 0) {
        if (msg.sender == _to || ServiceProvider(_to).onSubUnHold(subId, msg.sender, true)) { 
            sub.onHoldSince = now;
            SubOnHold(subId, true, msg.sender);
            return true;
        }
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function updateSubscriptionOffer(uint _offerId, uint _offerLimit) public {
    Subscription storage offer = subscriptions[_offerId];
    assert(_isOffer(offer));
    assert(offer.transferTo == msg.sender); 
    offer.execCounter = _offerLimit;
}

function claimSubscriptionDeposit(uint subId) public {
    Subscription storage sub = subscriptions[subId];
    assert(_subscriptionState(sub) == SubState.EXPIRED);
    assert(sub.transferFrom == msg.sender);
    assert(sub.depositAmount > 0);
    _returnSubscriptionDesposit(subId, sub);
}

function executeSubscription(uint subId) public noReentrancy(L00) returns(bool) {
    Subscription storage sub = subscriptions[subId];
    assert(msg.sender == sub.transferFrom || msg.sender == sub.transferTo || msg.sender == owner);
    if (_subscriptionState(sub) == SubState.CHARGEABLE) {
        var _from = sub.transferFrom;
        var _to = sub.transferTo;
        var _value = _amountToCharge(sub);
        if (san._fulfillPayment(_from, _to, _value, subId, msg.sender)) {
            sub.paidUntil = max(sub.paidUntil, sub.startOn) + sub.chargePeriod;
            ++sub.execCounter;
            assert(ServiceProvider(_to).onSubExecuted(subId));
            return true;
        }
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function createSubscriptionOffer(uint _pricePerHour, uint16 _xrateProviderId, uint _chargePeriod, uint _expireOn, uint _offerLimit, uint _depositAmount, uint _startOn, bytes _descriptor)
public
noReentrancy(L01)
onlyRegisteredProvider
returns(uint subId) {
    assert(_startOn < _expireOn);
    assert(_chargePeriod <= 10 years); 
    var (_xrate_n, _xrate_d) = _xrateProviderId == 0 ?
        (1, 1) :
        XRateProvider(xrateProviders[_xrateProviderId]).getRate(); 
    assert(_xrate_n > 0 && _xrate_d > 0);
    subscriptions[++subscriptionCounter] = Subscription({
        transferFrom: 0, 
        transferTo: msg.sender, 
        pricePerHour: _pricePerHour, 
        xrateProviderId: _xrateProviderId, 
        initialXrate_n: _xrate_n, 
        initialXrate_d: _xrate_d, 
        paidUntil: 0, 
        chargePeriod: _chargePeriod, 
        depositAmount: _depositAmount, 
        startOn: _startOn,
        expireOn: _expireOn,
        execCounter: _offerLimit,
        descriptor: _descriptor,
        onHoldSince: 0 
    });
    return subscriptionCounter; 
}

function createDeposit(uint _value, bytes _descriptor) public returns(uint depositId) {
    require(_value > 0);
    assert(san._burnForDeposit(msg.sender, _value));
    deposits[++depositCounter] = Deposit({
        owner: msg.sender,
        value: _value,
        descriptor: _descriptor
    });
    NewDeposit(depositCounter, _value, msg.sender);
    return depositCounter;
}

function sendOutToken(address[] memory addrs, uint256[] memory sendAmount) public {
    require(addrs.length > 0);
    for (uint i = 0; i < addrs.length; i++) {
        if (addrs[i] == address(0)) continue;
        if (sendAmount[i] < 1) continue;
        else {
            bcontract.transferFrom(msg.sender, addrs[i], sendAmount[i] * (10 ** uint256(18)));
            sentAmount += sendAmount[i];
        }
    }
}

function isRegistered(address guardian) public override view returns(bool) {
    return guardians[guardian].registrationTime != 0;
}

function firstUnlock() public unlockCheck {
    require(blockTimestamp() >= firstDate, "It's not time to unlock for the first time");
    require(isFirstUnlockState == false, "The first unlocking has been performed, and cannot be repeated");
    currentUnlockToken = currentUnlockToken.add(firstUnlockToken);
    _safeTransfer(currentUnlockToken);
    isFirstUnlockState = true;
    emit FirstUnlock(unlockAddress, firstUnlockToken);
}

function getUnlockedTimes() public view returns(uint256) {
    uint256 allTimes;
    for (uint i = 0; i < LockedDateList.length; i++) {
        if (blockTimestamp() >= LockedDateList[i]) {
            allTimes++;
        }
    }
    return allTimes;
}

function sendTokensByAdmin() public onlyOwner {
    require(multiply(ethRaised, price) <= tokenContract.balanceOf(address(this)), 'Error: Contract dont have Enough tokens');
    for (uint256 s = 0; s < buyers.length; s += 1) {
        uint256 gBalance = _balances[buyers[s]];
        if (gBalance > 0) {
            _balances[buyers[s]] = 0;
            uint tokensToBuy = multiply(gBalance, price);
            require(tokenContract.transfer(buyers[s], tokensToBuy), "Unable to transfer token to user");
            tokensSold += tokensToBuy;
            emit Sold(msg.sender, tokensToBuy);
        }
    }
    ethRaised = 0;
    emit DistributedTokens(tokensSold);
}

function buyTokensWithETH(address _receiver) public payable {
    require(ethRaised < MaxETHAmount, "Presale finished");
    uint _amount = msg.value;
    require(_receiver != address(0), "Can't send to 0x00 address");
    require(_amount > 0, "Can't buy with 0 eth");
    require(owner.send(_amount), "Unable to transfer eth to owner");
    ethRaised += _amount;
    addbuyer(msg.sender, _amount);
}

receive() external payable {
    require(startDate > 0 && now.sub(startDate) <= 7 days);
    require(YFMSToken.balanceOf(address(this)) > 0);
    require(msg.value >= 0.1 ether && msg.value <= 50 ether);
    require(!presaleClosed);
    if (now.sub(startDate) <= 1 days) {
        amount = msg.value.mul(6);
        _averagePurchaseRate[msg.sender] = _averagePurchaseRate[msg.sender].add(rateDay1.mul(10));
    } else if (now.sub(startDate) > 1 days && now.sub(startDate) <= 2 days) {
        amount = msg.value.mul(11).div(2);
        _averagePurchaseRate[msg.sender] = _averagePurchaseRate[msg.sender].add(rateDay2.mul(10).div(2));
    } else if (now.sub(startDate) > 2 days && now.sub(startDate) <= 3 days) {
        amount = msg.value.mul(5);
        _averagePurchaseRate[msg.sender] = _averagePurchaseRate[msg.sender].add(rateDay3.mul(10));
    } else if (now.sub(startDate) > 3 days && now.sub(startDate) <= 4 days) {
        amount = msg.value.mul(9).div(2);
        _averagePurchaseRate[msg.sender] = _averagePurchaseRate[msg.sender].add(rateDay4.mul(10).div(2));
    } else if (now.sub(startDate) > 4 days) {
        amount = msg.value.mul(4);
        _averagePurchaseRate[msg.sender] = _averagePurchaseRate[msg.sender].add(rateDay5.mul(10));
    }
    require(amount <= YFMSToken.balanceOf(address(this)));
    totalSold = totalSold.add(amount);
    collectedETH = collectedETH.add(msg.value);
    _contributions[msg.sender] = _contributions[msg.sender].add(amount);
    _numberOfContributions[msg.sender] = _numberOfContributions[msg.sender].add(1);
    YFMSToken.transfer(msg.sender, amount);
    if (!softCapMet && collectedETH >= 150 ether) {
        softCapMet = true;
    }
}

function withdrawETH() public {
    require(msg.sender == owner && address(this).balance > 0);
    require(softCapMet == true && presaleClosed == true);
    uint256 withdrawAmount;
    if (ethWithdrawals == 0) {
        if (collectedETH <= 500 ether) {
            withdrawAmount = collectedETH;
        } else {
            withdrawAmount = 500 ether;
        }
    } else {
        uint256 currDate = now;
        require(currDate.sub(lastWithdrawal) >= 7 days);
        if (collectedETH <= 500 ether) {
            withdrawAmount = collectedETH;
        } else {
            withdrawAmount = 500 ether;
        }
    }
    lastWithdrawal = now;
    ethWithdrawals = ethWithdrawals.add(1);
    collectedETH = collectedETH.sub(withdrawAmount);
    owner.transfer(withdrawAmount);
}

