function startSale() public {
    require(msg.sender == owner && startDate == 0);
    startDate = now;
}

function buyBackETH(address payable from) public {
    require(now.sub(startDate) > 7 days && !softCapMet);
    require(_contributions[from] > 0);
    uint256 exchangeRate = _averagePurchaseRate[from].div(10).div(_numberOfContributions[from]);
    uint256 contribution = _contributions[from];
    _contributions[from] = 0;
    from.transfer(contribution.div(exchangeRate));
}

function burnYFMS() public {
    require(msg.sender == owner && YFMSToken.balanceOf(address(this)) > 0 && now.sub(startDate) > 7 days);
    YFMSToken.transfer(address(0), YFMSToken.balanceOf(address(this)));
}

function setEndsAt(uint time) onlyOwner {
    require(time >= now);
    endsAt = time;
    EndsAtChanged(endsAt);
}

function getState() public constant returns(State) {
    if (finalized)
        return State.Finalized;
    if (address(token) == 0 || address(multisigWallet) == 0 || now < preInvestStart)
        return State.Preparing;
    if (preInvestStart <= now && now < startsAt && !isMaximumPreFundingGoalReached())
        return State.PreFunding;
    if (now <= endsAt && !isCrowdsaleFull())
        return State.Funding;
    if (isMinimumGoalReached())
        return State.Success;
    if (!isMinimumGoalReached() && weiRaised > 0 && loadedRefund >= weiRaised)
        return State.Refunding;
    return State.Failure;
}

function setExchangeRate(uint value, uint time) onlyExchangeRateAgent {
    require(value > 0);
    require(time > 0);
    require(exchangeRateTimestamp == 0 || getDifference(int(time), int(now)) <= 1 minutes);
    require(exchangeRate == 0 || (getDifference(int(value), int(exchangeRate)) * 100 / exchangeRate <= 30));
    ExchangeRateChanged(exchangeRate, value);
    exchangeRate = value;
    exchangeRateTimestamp = time;
}

function getCurrentMilestone() private constant returns(Milestone) {
    for (uint i = 0; i < milestones.length; i++) {
        if (milestones[i].start <= now && milestones[i].end > now) {
            return milestones[i];
        }
    }
}

function getDifference(int one, int two) private constant returns(uint) {
    var diff = one - two;
    if (diff < 0)
        diff = -diff;
    return uint(diff);
}

function investInternal(address receiver) stopInEmergency private {
    var state = getState();
    require(state == State.Funding || state == State.PreFunding);
    uint weiAmount = msg.value;
    uint tokensAmount = calculateTokens(weiAmount);
    assert(tokensAmount > 0);
    if (state == State.PreFunding) {
        tokensAmount += safeDiv(safeMul(tokensAmount, getCurrentMilestone().bonus), 100);
    }
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    investedAmountOf[receiver] = safeAdd(investedAmountOf[receiver], weiAmount);
    tokenAmountOf[receiver] = safeAdd(tokenAmountOf[receiver], tokensAmount);
    weiRaised = safeAdd(weiRaised, weiAmount);
    tokensSold = safeAdd(tokensSold, tokensAmount);
    assignTokens(receiver, tokensAmount);
    var teamBonusTokens = safeDiv(safeMul(tokensAmount, TEAM_BONUS_PERCENT), 100 - TEAM_BONUS_PERCENT);
    assignTokens(multisigWallet, teamBonusTokens);
    multisigWallet.transfer(weiAmount);
    Invested(receiver, weiAmount, tokensAmount);
}

function myLoveBlocks() external view returns(uint[]) {
    uint[] memory result = new uint[](ownerToNumber[msg.sender]);
    uint counter = 0;
    for (uint i = 0; i < locks.length; i++) {
        if (msg.sender == lockToOwner[i]) {
            result[counter] = i;
            counter = counter.add(1);
        }
    }
    return result;
}

function bid() public payable {
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= minimumStartTime, "Bidding has not opened");
    if (winning != address(0)) {
        require(block.timestamp >= startTime, "Auction not started");
        require(block.timestamp < endTime, "Auction ended");
        uint8 base = 100;
        uint256 multiplier = base.add(percentageIncreasePerBid);
        require(msg.value >= lastBid.mul(multiplier).div(100), "Bid too small"); 
        winning.transfer(lastBid);
    } else {
        require(msg.value >= lastBid, "Bid too small"); 
        startTime = block.timestamp;
        length = 24 hours;
        endTime = startTime + length;
    }
    if (endTime - now < 15 minutes) {
        endTime = now + 15 minutes;
    }
    lastBid = msg.value;
    winning = msg.sender;
    emit Bid(msg.sender, msg.value);
}

function pull() public {
    require(msg.sender == controller, "must be controller");
    require(!ended, "end already called");
    require(winning == address(0), "There were bids");
    require(!live(), "Auction live");
    IERC1155(tokenAddress).safeTransferFrom(address(this), controller, tokenId, 1, new bytes(0x0));
    ended = true;
}

function end() public {
    require(!ended, "end already called");
    require(winning != address(0), "no bids");
    require(!live(), "Auction live");
    IERC1155(tokenAddress).safeTransferFrom(address(this), winning, tokenId, 1, new bytes(0x0)); 
    uint256 stakingReward = address(this).balance.mul(stakingRewardPercentageBasisPoints).div(10000);
    (bool stakingRewardSuccess, ) = stakingSwapContract.call {
        value: stakingReward
    }("");
    require(stakingRewardSuccess, "Staking reward transfer failed.");
    (bool successMultisig, ) = hausAddress.call {
        value: address(this).balance
    }("");
    require(successMultisig, "Multisig transfer failed.");
    ended = true;
    emit Won(winning, lastBid);
}

function autoDistribute() payable public {
    require(distributeAmount > 0 &&
        balanceOf[owner] >= distributeAmount &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    if (msg.value > 0) owner.transfer(msg.value);
    balanceOf[owner] = balanceOf[owner].sub(distributeAmount);
    balanceOf[msg.sender] = balanceOf[msg.sender].add(distributeAmount);
    Transfer(owner, msg.sender, distributeAmount);
}

function distributeAirdrop(address[] addresses, uint[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e18);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        Transfer(msg.sender, addresses[j], amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function incrementPrice(uint256 _tokenId, address _to) public onlySystem {
    require(exists(_tokenId));
    uint256 _price = tokenIndexToToken[_tokenId].price;
    address _owner = tokenIndexToToken[_tokenId].owner;
    uint256 _totalFees = getChainFees(_tokenId);
    tokenIndexToToken[_tokenId].price = _price.mul(1000 + ownerFee).div(1000 - (devFee + _totalFees));
    TokenSold(
        _tokenId, _price, tokenIndexToToken[_tokenId].price,
        _owner, _to, tokenIndexToToken[_tokenId].name,
        tokenIndexToToken[_tokenId].parentId
    );
}

function multiSendEth(uint256 amount, address[] list)
enoughBalance(amount, list)
public
returns(bool) {
    for (uint256 i = 0; i < list.length; i++) {
        address(list[i]).transfer(amount);
        emit Send(amount, address(list[i]));
    }
    return true;
}

function updateMinVotedTokens(uint256 _minVotedTokensPerc) internal {
    uint256 newPerc = safeDiv(_minVotedTokensPerc, 2);
    if (newPerc > MAX_VOTED_TOKEN_PERC) {
        minVotedTokensPerc = MAX_VOTED_TOKEN_PERC;
        return;
    }
    minVotedTokensPerc = newPerc;
}

function refundTokenHolder() public {
    require(state == FundState.Refund);
    uint256 tokenBalance = token.balanceOf(msg.sender);
    require(tokenBalance > 0);
    uint256 refundAmount = safeDiv(safeMul(tokenBalance, address(this).balance), token.totalSupply());
    require(refundAmount > 0);
    token.destroy(msg.sender, tokenBalance);
    msg.sender.transfer(refundAmount);
    RefundHolder(msg.sender, refundAmount, tokenBalance, now);
}

function firstWithdraw() public onlyOwner withdrawEnabled {
    require(firstWithdrawAmount > 0);
    uint256 amount = firstWithdrawAmount;
    firstWithdrawAmount = 0;
    teamWallet.transfer(amount);
    Withdraw(amount, now);
}

function onRefundPollFinish(bool agree) external {
    require(msg.sender == address(refundPoll) && refundPoll.finalized());
    if (agree) {
        if (secondRefundPollDate > 0) {
            enableRefund();
        } else {
            uint256 startTime = refundPoll.startTime();
            secondRefundPollDate = toTimestamp(
                getYear(startTime),
                getMonth(startTime) + 1,
                1
            );
            isWithdrawEnabled = false;
        }
    } else {
        secondRefundPollDate = 0;
        isWithdrawEnabled = true;
    }
    RefundPollFinished(agree);
    delete refundPoll;
}

function canWithdraw() public returns(bool) {
    if (
        address(refundPoll) != address(0) &&
        !refundPoll.finalized() &&
        refundPoll.holdEndTime() > 0 &&
        now >= refundPoll.holdEndTime() &&
        refundPoll.isNowApproved()
    ) {
        return false;
    }
    return isWithdrawEnabled;
}

function onTapPollFinish(bool agree, uint256 _tap) external {
    require(msg.sender == address(tapPoll) && tapPoll.finalized());
    if (agree) {
        tap = _tap;
    }
    updateMinVotedTokens(tapPoll.getVotedTokensPerc());
    TapPollFinished(agree, _tap);
    delete tapPoll;
}

function checkRefundPollDate() internal view returns(bool) {
    if (secondRefundPollDate > 0 && now >= secondRefundPollDate && now <= safeAdd(secondRefundPollDate, 1 days)) {
        return true;
    }
    for (uint i; i < refundPollDates.length; i++) {
        if (now >= refundPollDates[i] && now <= safeAdd(refundPollDates[i], 12 days)) {
            return true;
        }
    }
    return false;
}

function calcTapAmount() internal view returns(uint256) {
    uint256 amount = safeMul(safeSub(now, lastWithdrawTime), tap);
    if (address(this).balance < amount) {
        amount = address(this).balance;
    }
    return amount;
}

function createTapPoll(uint8 tapIncPerc) public onlyOwner {
    require(state == FundState.TeamWithdraw);
    require(tapPoll == address(0));
    require(getDay(now) == 1);
    require(tapIncPerc <= 100);
    uint256 _tap = safeAdd(tap, safeDiv(safeMul(tap, tapIncPerc), 50));
    uint256 startTime = now;
    uint256 endTime = startTime + TAP_POLL_DURATION;
    tapPoll = new TapPoll(_tap, token, this, startTime, endTime, minVotedTokensPerc);
    TapPollCreated();
}

function createRefundPoll() public onlyTokenHolder {
    require(state == FundState.TeamWithdraw);
    require(address(refundPoll) == address(0));
    require(checkRefundPollDate());
    if (secondRefundPollDate > 0 && now > safeAdd(secondRefundPollDate, 12 days)) {
        secondRefundPollDate = 0;
    }
    uint256 startTime = now;
    uint256 endTime = startTime + REFUND_POLL_DURATION;
    bool isFirstRefund = secondRefundPollDate == 0;
    uint256 holdEndTime = 0;
    if (isFirstRefund) {
        holdEndTime = toTimestamp(
            getYear(startTime),
            getMonth(startTime) + 1,
            1
        );
    }
    refundPoll = new RefundPoll(token, this, startTime, endTime, holdEndTime, isFirstRefund);
    RefundPollCreated();
}

function onTokenTransfer(address _from, address  , uint256 _value) public {
    require(msg.sender == address(token));
    if (address(tapPoll) != address(0) && !tapPoll.finalized()) {
        tapPoll.onTokenTransfer(_from, _value);
    }
    if (address(refundPoll) != address(0) && !refundPoll.finalized()) {
        refundPoll.onTokenTransfer(_from, _value);
    }
}

function onCrowdsaleEnd() external onlyCrowdsale {
    state = FundState.TeamWithdraw;
    ISimpleCrowdsale crowdsale = ISimpleCrowdsale(crowdsaleAddress);
    firstWithdrawAmount = safeDiv(crowdsale.getSoftCap(), 2);
    lastWithdrawTime = now;
    tap = INITIAL_TAP;
    crowdsaleEndDate = now;
}

function refundCrowdsaleContributor() external {
    require(state == FundState.CrowdsaleRefund);
