    uint256 refundAmount = contributions[msg.sender];
    contributions[msg.sender] = 0;
    token.destroy(msg.sender, token.balanceOf(msg.sender));
    msg.sender.transfer(refundAmount);
    RefundContributor(msg.sender, refundAmount, now);
}

function withdraw() public onlyOwner withdrawEnabled {
    require(state == FundState.TeamWithdraw);
    uint256 amount = calcTapAmount();
    lastWithdrawTime = now;
    teamWallet.transfer(amount);
    Withdraw(amount, now);
}

function withdraw(uint _instId) external onlyInstanceOwner(_instId) instanceExists(_instId) whenNotPaused {
    HodlInstance storage curInst = instances[_instId];
    require(now >= curInst.endTime);
    require(curInst.hasBeenWithdrawn == false);
    curInst.hasBeenWithdrawn = true;
    curInst.instOwner.transfer(curInst.hodlAmount);
    HodlWithdrawn(_instId, msg.sender, curInst.hodlAmount);
}

function createNewHodl(uint _endTime) external payable blockCatEntryPoint limitTransactionValue whenNotPaused returns(uint currentId) {
    require(_endTime >= now);
    require((_endTime - now) <= maximumHodlDuration);
    require(msg.value > 0);
    currentId = instanceId;
    address instanceOwner = msg.sender;
    uint hodlAmount = msg.value;
    uint endTime = _endTime;
    HodlInstance storage curInst = instances[currentId];
    curInst.instId = currentId;
    curInst.instOwner = instanceOwner;
    curInst.hasBeenWithdrawn = false;
    curInst.hodlAmount = hodlAmount;
    curInst.endTime = endTime;
    HodlCreated(currentId, instanceOwner, hodlAmount, endTime);
    instanceId++;
}

function _withdraw(address recipient)
internal {
    uint amount = withdrawable(recipient);
    require(amount > 0, "INVALID_AMOUNT");
    Record storage r = records[recipient];
    r.lastWithdrawTime = block.timestamp;
    r.withdrawn = r.withdrawn.add(amount);
    require(ERC20(lrcAddress).transfer(recipient, amount), "transfer failed");
    emit Withdrawal(msg.sender, recipient, amount);
}

function updateRecipient(address oldRecipient, address newRecipient)
external {
    require(canChangeAddressFor(oldRecipient), "UNAUTHORIZED");
    require(newRecipient != address(0), "INVALID_ADDRESS");
    require(records[newRecipient].rewarded == 0, "INVALID_NEW_RECIPIENT");
    Record storage r = records[oldRecipient];
    require(r.rewarded > 0, "INVALID_OLD_RECIPIENT");
    records[newRecipient] = r;
    delete records[oldRecipient];
    emit MemberAddressChanged(oldRecipient, newRecipient);
}

function collect()
external
onlyOwner {
    require(block.timestamp > vestStart + vestPeriod + 60 days, "TOO_EARLY");
    uint amount = ERC20(lrcAddress).balanceOf(address(this));
    require(ERC20(lrcAddress).transfer(msg.sender, amount), "transfer failed");
}

function vested(address recipient)
public
view
returns(uint) {
    if (block.timestamp.sub(vestStart) < vestPeriod) {
        return records[recipient].rewarded.mul(block.timestamp.sub(vestStart)) / vestPeriod;
    } else {
        return records[recipient].rewarded;
    }
}

