function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyFounders && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function processBuy(address _to, uint256 _value) internal returns(bool) {
    require(!halted);
    require(_value > 0);
    uint tokens = _value / price();
    require(balances[owner] > safeMul(tokens, multiplier));
    if (isPreSale) {
        tokens = tokens + (tokens / 2);
    }
    if (isDayFirst) {
        tokens = tokens + safeMul(safeDiv(tokens, 10), 3);
    }
    if (isDaySecond) {
        tokens = tokens + safeDiv(tokens, 5);
    }
    if (isDayThird) {
        tokens = tokens + safeDiv(tokens, 10);
    }
    require(safeAdd(presaleTokenSupply, tokens) < icoCap);
    founder.transfer(_value);
    balances[_to] = safeAdd(balances[_to], safeMul(tokens, multiplier));
    balances[owner] = safeSub(balances[owner], safeMul(tokens, multiplier));
    presaleTokenSupply = safeAdd(presaleTokenSupply, tokens);
    presaleEtherRaised = safeAdd(presaleEtherRaised, _value);
    Buy(_to, _value, safeMul(tokens, multiplier));
    TokensSent(_to, safeMul(tokens, multiplier));
    ContributionReceived(_to, _value);
    Transfer(owner, _to, safeMul(tokens, multiplier));
    return true;
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 110;
    } else {
        tokens = msg.value * 100;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function transfer(address _to, uint256 _value) public returns(bool success) {
    adjustInvestorCount(msg.sender, _to, _value);
    require(verifyTransfer(msg.sender, _to, _value), "Transfer is not valid");
    adjustBalanceCheckpoints(msg.sender);
    adjustBalanceCheckpoints(_to);
    require(super.transfer(_to, _value));
    return true;
}

function burn(uint256 _value) checkGranularity(_value) public {
    adjustInvestorCount(msg.sender, address(0), _value);
    require(tokenBurner != address(0), "Token Burner contract address is not set yet");
    require(verifyTransfer(msg.sender, address(0), _value), "Transfer is not valid");
    require(_value <= balances[msg.sender], "Value should no be greater than the balance of msg.sender");
    adjustBalanceCheckpoints(msg.sender);
    adjustTotalSupplyCheckpoints();
    balances[msg.sender] = balances[msg.sender].sub(_value);
    require(tokenBurner.burn(msg.sender, _value), "Token burner process is not validated");
    totalSupply_ = totalSupply_.sub(_value);
    emit Burnt(msg.sender, _value);
    emit Transfer(msg.sender, address(0), _value);
}

function mint(address _investor, uint256 _amount) public onlyModule(STO_KEY, true) checkGranularity(_amount) isMintingAllowed() returns(bool success) {
    require(_investor != address(0), "Investor address should not be 0x");
    adjustInvestorCount(address(0), _investor, _amount);
    require(verifyTransfer(address(0), _investor, _amount), "Transfer is not valid");
    adjustBalanceCheckpoints(_investor);
    adjustTotalSupplyCheckpoints();
    totalSupply_ = totalSupply_.add(_amount);
    balances[_investor] = balances[_investor].add(_amount);
    emit Minted(_investor, _amount);
    emit Transfer(address(0), _investor, _amount);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    adjustInvestorCount(_from, _to, _value);
    require(verifyTransfer(_from, _to, _value), "Transfer is not valid");
    adjustBalanceCheckpoints(_from);
    adjustBalanceCheckpoints(_to);
    require(super.transferFrom(_from, _to, _value));
    return true;
}

function _addModule(address _moduleFactory, bytes _data, uint256 _maxCost, uint256 _budget) internal {
    IModuleRegistry(moduleRegistry).useModule(_moduleFactory);
    IModuleFactory moduleFactory = IModuleFactory(_moduleFactory);
    uint8 moduleType = moduleFactory.getType();
    require(modules[moduleType].length < MAX_MODULES, "Limit of MAX MODULES is reached");
    uint256 moduleCost = moduleFactory.setupCost();
    require(moduleCost <= _maxCost, "Max Cost is always be greater than module cost");
    require(ERC20(polyToken).approve(_moduleFactory, moduleCost), "Not able to approve the module cost");
    address module = moduleFactory.deploy(_data);
    require(ERC20(polyToken).approve(module, _budget), "Not able to approve the budget");
    bytes32 moduleName = moduleFactory.getName();
    modules[moduleType].push(ModuleData(moduleName, module));
    emit LogModuleAdded(moduleType, moduleName, _moduleFactory, module, moduleCost, _budget, now);
}

function updateFromRegistry() onlyOwner public {
    moduleRegistry = PolymathRegistry(polymathRegistry).getAddress("ModuleRegistry");
    securityTokenRegistry = PolymathRegistry(polymathRegistry).getAddress("SecurityTokenRegistry");
    tickerRegistry = PolymathRegistry(polymathRegistry).getAddress("TickerRegistry");
    polyToken = PolymathRegistry(polymathRegistry).getAddress("PolyToken");
}

function distributeAirdrop(address[] addresses, uint[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e8);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        Transfer(msg.sender, addresses[j], amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function balanceOfLocked(address owner) public view returns(uint256) {
    uint256 lockedBalance;
    if (timelockList[owner].length > 0) {
        for (uint i = 0; i < timelockList[owner].length; i++) {
            if (timelockList[owner][i]._releaseTime > now) {
                lockedBalance = lockedBalance.add(timelockList[owner][i]._amount);
            }
        }
    }
    return lockedBalance;
}

function balanceOf(address owner) public view returns(uint256) {
    uint256 totalBalance = super.balanceOf(owner);
    if (timelockList[owner].length > 0) {
        for (uint i = 0; i < timelockList[owner].length; i++) {
            if (timelockList[owner][i]._releaseTime <= now) {
                totalBalance = totalBalance.add(timelockList[owner][i]._amount);
            }
        }
    }
    return totalBalance;
}

function AmountMNESent(address _address, bool _excludeCurrent, bool _currentOnly) public view returns(uint256) {
    if (mneSentPerDay[_address].length == 0) return 0;
    uint currentDay = GetCurrentDay();
    if (_currentOnly) {
        uint lasti = daysParticipated[_address][daysParticipated[_address].length - 1];
        if (lasti == currentDay)
            return mneSentPerDay[_address][lasti];
    } else {
        uint j = 0;
        uint finalAmount = 0;
        while (j < mneSentPerDay[_address].length) {
            if ((daysParticipated[_address][j] == currentDay) && _excludeCurrent) continue;
            finalAmount += mneSentPerDay[_address][j];
            j++;
        }
        return finalAmount;
    }
    return 0;
}

function PayoutStaking(uint i, address _address) private {
    if (blockPayouts) revert('payouts blocked'); 
    if (mainStk.daysParticipatedLength(msg.sender) == 0) revert('No Staking');
    if (block.timestamp >= mainStk.startDate() + (mainStk.daysParticipatedGetAt(msg.sender, 0) * 86400) + 31556926 + mainStk.contingency()) {
        uint interestRateToPay = mainStk.mneSentPerDayGetAt(msg.sender, i) * mainStk.maxInterestRate(mainStk.daysParticipatedGetAt(msg.sender, i)) * 1000000000000000 / mainStk.mnePerDay(mainStk.daysParticipatedGetAt(msg.sender, i));
        uint coinsToMint = mainStk.mneSentPerDayGetAt(msg.sender, i) * interestRateToPay / 1000000000000000 / 100;
        uint amountToPay = mainStk.mneSentPerDay(msg.sender, i) + coinsToMint;
        if (_address != 0x0000000000000000000000000000000000000000)
            mneContract.transfer(_address, amountToPay);
        else
            mneContract.transfer(msg.sender, amountToPay);
        newStakingCoins += coinsToMint;
        paidStakingCoins += amountToPay;
        RealStakingPaid[msg.sender] = true;
    } else {
        revert('Payout Date Not Valid');
    }
}

function startStaking(address _sender, uint256 _amountToStake, address[] memory _addressList, uint256[] memory uintList) public {
    if (blockStaking) revert('not active'); 
    if (msg.sender != address(mneContract)) revert();
    uint currentPeriod;
    if (block.timestamp < startDate)
        currentPeriod = 0;
    else
        currentPeriod = (block.timestamp - startDate) / 86400;
    if (currentPeriod > 364) revert('invalid period');
    mnePerDay[currentPeriod] += _amountToStake;
    if (daysParticipated[_sender].length > 0) {
        if (daysParticipated[_sender][daysParticipated[_sender].length - 1] == currentPeriod) {
            mneSentPerDay[_sender][daysParticipated[_sender].length - 1] += _amountToStake;
        } else {
            daysParticipated[_sender].push(currentPeriod);
            mneSentPerDay[_sender].push(_amountToStake);
            StakingPaid[_sender].push(false);
        }
    } else {
        participatedAddress.push(_sender);
        daysParticipated[_sender].push(currentPeriod);
        mneSentPerDay[_sender].push(_amountToStake);
        StakingPaid[_sender].push(false);
    }
    overallMNEStaking += _amountToStake;
    if (_addressList.length > 1) {
        if (_sender == _addressList[1] || _addressList[1] == address(this) || _addressList[1] == address(mneContract)) revert('invalid referal');
        uint bonusAmountReferral = _amountToStake * referralRate / 100;
        uint referrerRateFinal;
        if (pc.stakeBalances(_addressList[1]) > 0)
            referrerRateFinal = referrerRateShare;
        else if (!gn.isAnyGenesisAddress(_addressList[1]))
            referrerRateFinal = referrerRateNormal;
        else if (gn.isGenesisAddressLevel1(_addressList[1]))
            referrerRateFinal = referrerRateNormal;
        else if (gn.isGenesisAddressLevel2(_addressList[1]))
            referrerRateFinal = referrerRateLevel2;
        else if (gn.isGenesisAddressLevel3(_addressList[1]))
            referrerRateFinal = referrerRateLevel3;
        uint bonusAmountReferrer = _amountToStake * referrerRateFinal / 100;
        BonusDay[_sender].push(currentPeriod);
        BonusFrom[_sender].push(_addressList[1]);
        BonusAmount[_sender].push(bonusAmountReferral);
        BonusPaid[_sender] = false;
        if (AddressBonus[_sender] == 0)
            bonusAddress.push(_sender);
        AddressBonus[_sender] += bonusAmountReferral;
        BonusDay[_addressList[1]].push(currentPeriod);
        BonusFrom[_addressList[1]].push(_sender);
        BonusAmount[_addressList[1]].push(bonusAmountReferrer);
        BonusPaid[_addressList[1]] = false;
        if (AddressBonus[_addressList[1]] == 0)
            bonusAddress.push(_addressList[1]);
        AddressBonus[_addressList[1]] += bonusAmountReferrer;
        overallBonus += bonusAmountReferral + bonusAmountReferrer;
    }
}

function PayoutBonus(address _address) public {
    if (blockPayouts) revert('payouts blocked'); 
    if (BonusDay[msg.sender].length == 0) revert('No Bonus');
    if (block.timestamp >= startDate + (BonusDay[msg.sender][0] * 86400) + 31556926 + contingency) {
        if (BonusPaid[msg.sender]) revert('Bonus already paid');
        external1.mintNewCoins(AddressBonus[msg.sender]);
        if (_address != 0x0000000000000000000000000000000000000000)
            mneContract.transfer(_address, AddressBonus[msg.sender]);
        else
            mneContract.transfer(msg.sender, AddressBonus[msg.sender]);
        newBonusCoins += AddressBonus[msg.sender];
        BonusPaid[msg.sender] = true;
    } else {
        revert('Payout Date Not Valid');
    }
}

function GetCurrentDay() public view returns(uint256) {
    uint currentPeriod;
    if (block.timestamp < startDate)
        currentPeriod = 0;
    else
        currentPeriod = (block.timestamp - startDate) / 86400;
    return currentPeriod;
}

function AmountToPayStaking(address _address, bool _checkID, uint i, bool _excludeCurrent, bool _currentOnly) public view returns(uint256) {
    if (daysParticipated[_address].length == 0) return 0;
    uint currentDay = GetCurrentDay();
    if (_currentOnly) {
        uint lasti = daysParticipated[_address][daysParticipated[_address].length - 1];
        if (lasti == currentDay) {
            uint interestRateToPay = mneSentPerDay[_address][lasti] * maxInterestRate[daysParticipated[_address][lasti]] * 1000000000000000 / mnePerDay[daysParticipated[_address][lasti]];
            uint coinsToMint = mneSentPerDay[_address][lasti] * interestRateToPay / 1000000000000000 / 100;
            uint amountToPay = mneSentPerDay[_address][lasti] + coinsToMint;
            return amountToPay;
        } else {
            return 0;
        }
    } else if (_checkID) {
        uint interestRateToPay = mneSentPerDay[_address][i] * maxInterestRate[daysParticipated[_address][i]] * 1000000000000000 / mnePerDay[daysParticipated[_address][i]];
        uint coinsToMint = mneSentPerDay[_address][i] * interestRateToPay / 1000000000000000 / 100;
        uint amountToPay = mneSentPerDay[_address][i] + coinsToMint;
        return amountToPay;
    } else {
        uint j = 0;
        uint finalAmount = 0;
        while (j < mneSentPerDay[_address].length) {
            if ((daysParticipated[_address][j] == currentDay) && _excludeCurrent) continue;
            if (!StakingPaid[_address][j]) {
                uint interestRateToPay = mneSentPerDay[_address][j] * maxInterestRate[daysParticipated[_address][j]] * 1000000000000000 / mnePerDay[daysParticipated[_address][j]];
                uint coinsToMint = mneSentPerDay[_address][j] * interestRateToPay / 1000000000000000 / 100;
                uint amountToPay = mneSentPerDay[_address][j] + coinsToMint;
                finalAmount += amountToPay;
            }
            j++;
        }
        return finalAmount;
    }
}

