function openSAFE(
    bytes32 collateralType,
    address usr
) public returns(uint) {
    require(usr != address(0), "usr-address-0");
    safei = add(safei, 1);
    safes[safei] = address(new SAFEHandler(safeEngine));
    ownsSAFE[safei] = usr;
    collateralTypes[safei] = collateralType;
    if (firstSAFEID[usr] == 0) {
        firstSAFEID[usr] = safei;
    }
    if (lastSAFEID[usr] != 0) {
        safeList[safei].prev = lastSAFEID[usr];
        safeList[lastSAFEID[usr]].next = safei;
    }
    lastSAFEID[usr] = safei;
    safeCount[usr] = add(safeCount[usr], 1);
    emit OpenSAFE(msg.sender, usr, safei);
    return safei;
}

function _reward(address _to) private returns(bool) {
    if (rewards[_to].length < repayments.length) {
        uint sum = 0;
        for (uint i = rewards[_to].length; i < repayments.length; i++) {
            uint amount = balances[_to] > 0 ? (repayments[i].amount.mul(balances[_to]).div(totalSupply_)) : 0;
            rewards[_to].push(Payment({
                time: now,
                amount: amount
            }));
            sum = sum.add(amount);
        }
        if (sum > 0) {
            _to.transfer(sum);
            emit Reward(_to, now, sum);
        }
        return true;
    }
    return false;
}

function availableReward(address _to) public view returns(uint256 value) {
    if (rewards[_to].length < repayments.length && balances[_to] > 0) {
        uint sum = 0;
        for (uint i = rewards[_to].length; i < repayments.length; i++) {
            sum = sum.add(repayments[i].amount.mul(balances[_to]).div(totalSupply_));
        }
        return sum;
    }
    return 0;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    _reward(msg.sender);
    _reward(_to);
    return super.transfer(_to, _value);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    _reward(_from);
    _reward(_to);
    return super.transferFrom(_from, _to, _value);
}

