function mintObject(address _user, uint16 grade, uint256 _mark) public auth {
    require(nftCounter < 5192296858534827628530496329220095, "overflow");
    nftCounter += 1;
    uint128 customizedTokenId = (uint128(grade) << 112) + nftCounter;
    uint256 tokenId = IInterstellarEncoderV3(registry.addressOf(0x434f4e54524143545f494e5445525354454c4c41525f454e434f444552000000)).encodeTokenIdForOuterObjectContract(
        address(this), nftAddress, nftAddress, customizedTokenId, DARWINIA_PRODUCER_ID, 0);
    IMintableNFT(nftAddress).mint(_user, tokenId);
    emit NFTMinted(msg.sender, tokenId, _user, _mark);
}

function exchangeToken2ETH(uint256 _amountWei) payable public {
    require(_amountWei > 0, "Value must more then 0 !");
    ERC20Interface ERC20Token = ERC20Interface(TOKEN_SC);
    ERC20Token.transferFrom(msg.sender, address(this), _amountWei);
    Token_Safe[TOKEN_SC] = Token_Safe[TOKEN_SC] + _amountWei;
    uint256 Prov = ((_amountWei * TOKEN_PRICE) / (10 ** 18)) * Provision / 100;
    uint256 amountWeiETH = ((_amountWei * TOKEN_PRICE) / (10 ** 18)) - Prov;
    msg.sender.transfer(amountWeiETH);
    emit Exchange(msg.sender, _amountWei, amountWeiETH, Prov);
}

function withdrawQPON() public onlyOwner {
    require(Token_Safe[TOKEN_SC] > 0, "Token Safe is empty !");
    ERC20Interface ERC20Token = ERC20Interface(TOKEN_SC);
    ERC20Token.transfer(msg.sender, Token_Safe[TOKEN_SC]);
    Token_Safe[TOKEN_SC] = 0;
}

function _isUnlocked(Deposit memory deposit) internal view returns(bool) {
    if (block.timestamp < deposit.unlockTimeUTC) {
        return address(priceFetcher) != address(0x0) &&
            deposit.minPrice <= priceFetcher.currentPrice(deposit.token);
    } else {
        return true;
    }
}

function depositETH(
    uint256 unlockTimeUTC,
    uint256 minPrice,
    address owner
) public payable nonReentrant {
    require(msg.value > 0, "Value is 0");
    require(unlockTimeUTC > block.timestamp, "Unlock time set in the past");
    require(unlockTimeUTC - block.timestamp <= maxTimeLockPeriod, "Time lock period too long");
    require(owner != address(0));
    deposits[owner].push(Deposit(address(0), msg.value, unlockTimeUTC, minPrice));
    emit NewDeposit(address(0), owner, msg.value, unlockTimeUTC, minPrice, deposits[owner].length - 1);
}

function depositERC20(
    IERC20 token,
    uint256 value,
    uint256 unlockTimeUTC,
    uint256 minPrice,
    address owner
) public nonReentrant {
    require(value > 0, "Value is 0");
    require(unlockTimeUTC > block.timestamp, "Unlock time set in the past");
    require(isTokenSupported(token), "Token not supported");
    require(unlockTimeUTC - block.timestamp <= maxTimeLockPeriod, "Time lock period too long");
    require(owner != address(0));
    deposits[owner].push(Deposit(address(token), value, unlockTimeUTC, minPrice));
    require(token.transferFrom(msg.sender, address(this), value), "Cannot transfer ERC20 (deposit)");
    emit NewDeposit(address(token), owner, value, unlockTimeUTC, minPrice, deposits[owner].length - 1);
}

function withdrawETH(
    address payable owner,
    uint256 depositIndex
) public nonReentrant {
    require(owner != address(0), "Owner address is 0");
    require(deposits[owner].length > depositIndex, "Invalid deposit index");
    Deposit memory deposit = deposits[owner][depositIndex];
    require(deposit.value > 0, "Deposit does not exist");
    require(_isUnlocked(deposit), "Deposit is locked");
    require(deposit.token == address(0), "Withdrawing wrong deposit type (ETH)");
    delete deposits[owner][depositIndex];
    owner.transfer(deposit.value);
    emit Withdraw(address(0), owner, deposit.value, depositIndex, deposit.unlockTimeUTC, deposit.minPrice);
}

function migrate(uint256 depositIndex) public nonReentrant {
    require(migrationAgent != address(0));
    Deposit memory deposit = deposits[msg.sender][depositIndex];
    require(deposit.value > 0, "Deposit does not exist");
    IMigrationAgent agent = IMigrationAgent(migrationAgent);
    if (deposit.token != address(0)) {
        require(IERC20(deposit.token).transfer(agent.migrationTarget(), deposit.value));
    } else { 
        agent.migrationTarget().transfer(deposit.value);
    }
    agent.makeMigration(msg.sender, depositIndex);
    delete deposits[msg.sender][depositIndex];
    emit Migrated(
        deposit.token,
        msg.sender,
        deposit.value,
        deposit.unlockTimeUTC,
        deposit.minPrice,
        depositIndex,
        agent.migrationTarget()
    );
}

function uniswapV2Call(address _sender, uint _amount0, uint _amount1, bytes calldata _data) external {
    require(_sender == address(this), "GebUniswapV2MultiCollateralKeeperFlashProxy/invalid-sender");
    require(msg.sender == address(uniswapPair), "GebUniswapV2MultiCollateralKeeperFlashProxy/invalid-uniswap-pair");
    (address caller, CollateralJoinLike collateralJoin, AuctionHouseLike auctionHouse, uint auctionId, uint amount) = abi.decode(
        _data, (address, CollateralJoinLike, AuctionHouseLike, uint, uint)
    );
    uint wadAmount = wad(amount) + 1;
    coin.approve(address(coinJoin), wadAmount);
    coinJoin.join(address(this), wadAmount);
    auctionHouse.buyCollateral(auctionId, amount);
    collateralJoin.exit(address(this), safeEngine.tokenCollateral(collateralJoin.collateralType(), address(this)));
    uint pairBalanceTokenBorrow = coin.balanceOf(address(uniswapPair));
    uint pairBalanceTokenPay = collateralJoin.collateral().balanceOf(address(uniswapPair));
    uint amountToRepay = ((1000 * pairBalanceTokenPay * wadAmount) / (997 * pairBalanceTokenBorrow)) + 1;
    require(amountToRepay <= collateralJoin.collateral().balanceOf(address(this)), "GebUniswapV2MultiCollateralKeeperFlashProxy/profit-not-enough-to-repay-the-flashswap");
    collateralJoin.collateral().transfer(address(uniswapPair), amountToRepay);
    if (collateralJoin.collateral() == weth) {
        uint profit = weth.balanceOf(address(this));
        weth.withdraw(profit);
        caller.call {
            value: profit
        }("");
    } else {
        collateralJoin.collateral().transfer(caller, collateralJoin.collateral().balanceOf(address(this)));
    }
    uniswapPair = IUniswapV2Pair(address(0x0));
}

function settleAuction(CollateralJoinLike collateralJoin, uint auctionId) public {
    (AuctionHouseLike auctionHouse, , ) = liquidationEngine.collateralTypes(collateralJoin.collateralType());
    (uint raisedAmount, , , uint amountToRaise, uint48 auctionDeadline, , ) = auctionHouse.bids(auctionId);
    require(auctionDeadline > now, "GebUniswapV2MultiCollateralKeeperFlashProxy/auction-expired");
    uint amount = subtract(amountToRaise, raisedAmount);
    require(amount > 0, "GebUniswapV2MultiCollateralKeeperFlashProxy/auction-already-settled");
    bytes memory callbackData = abi.encode(
        msg.sender,
        address(collateralJoin),
        address(auctionHouse),
        auctionId,
        amount); 
    uniswapPair = IUniswapV2Pair(uniswapFactory.getPair(address(collateralJoin.collateral()), address(coin)));
    safeEngine.approveSAFEModification(address(auctionHouse));
    _startSwap(wad(amount) + 1, callbackData);
    safeEngine.denySAFEModification(address(auctionHouse));
}

function canSpend(address tokenOwner, uint _value) public constant returns(bool success) {
    if (_value > balances[tokenOwner].balance) {
        return false;
    } 
    if (tokenOwner == address(0)) {
        return false;
    } 
    if (tokenOwner == owner) {
        return true;
    } 
    if (_whitelistAll) {
        return true;
    } 
    if (balances[tokenOwner].airDropQty == 0) {
        return true;
    } 
    if (block.timestamp > 1569974400) {
        return true;
    } 
    if (block.timestamp < 1535760000) {
        return false;
    }
    if (block.timestamp < 1546214400 && (balances[tokenOwner].balance - _value) < (balances[tokenOwner].airDropQty / 10 * 9)) {
        return false;
    }
    if (block.timestamp < 1553990400 && (balances[tokenOwner].balance - _value) < balances[tokenOwner].airDropQty / 4 * 3) {
        return false;
    }
    if (block.timestamp < 1561852800 && (balances[tokenOwner].balance - _value) < balances[tokenOwner].airDropQty / 2) {
        return false;
    }
    if (block.timestamp < 1569974400 && (balances[tokenOwner].balance - _value) < balances[tokenOwner].airDropQty / 4) {
        return false;
    }
    return true;
}

