function getTKBRewardByAddress(address user) public view returns(uint256) {
    TokenStake storage currentStake = userToTokenStakes[user];
    uint256 secondsElapsed;
    if (block.timestamp > currentStake.stakingPeriodEndTime) {
        if (currentStake.stakingPeriodEndTime < currentStake.lastInteractionTimestamp) {
            return 0;
        }
        secondsElapsed = currentStake.stakingPeriodEndTime
            .sub(currentStake.lastInteractionTimestamp);
    } else {
        secondsElapsed = block.timestamp
            .sub(currentStake.lastInteractionTimestamp);
    }
    uint256 stakeAmount = currentStake.amount;
    uint256 blockCountElapsed = secondsElapsed.div(blockMiningTime);
    if (blockCountElapsed == 0 || stakeAmount == 0) {
        return 0;
    }
    return currentStake.rate
        .mul(blockCountElapsed)
        .mul(stakeAmount)
        .div(totalTokensStakedAmount);
}

function _mint(address account, uint256 amount) internal override {
    require(
        totalSupply().add(amount) <= MAX_SUPPLY,
        "total supply exceeds max supply"
    );
    super._mint(account, amount);
}

function unstakeTKB() external {
    uint256 amountToUnstake = userToTokenStakes[_msgSender()].amount;
    bool executeUnstaking;
    if (amountToUnstake != 0) {
        if (userToTokenStakes[_msgSender()].stakingPeriodEndTime <= block.timestamp) {
            executeUnstaking = true;
        }
        if (totalSupply() == MAX_SUPPLY) {
            executeUnstaking = true;
        }
    }
    require(
        executeUnstaking,
        "cannot unstake"
    );
    _withdrawRewardTKB(_msgSender());
    totalTokensStakedAmount = totalTokensStakedAmount.sub(amountToUnstake);
    delete userToTokenStakes[_msgSender()];
    _transfer(address(this), _msgSender(), amountToUnstake);
    emit Unstaked(address(this), _msgSender(), amountToUnstake);
}

function stakeTKB(
    uint256 stakeAmount,
    uint256 lockUpPeriodIdx 
) public {
    require(
        stakeAmount != 0,
        "stakeAmount should be greater than 0"
    );
    require(
        lockUpPeriodIdx <= 7,
        "lock lockUpPeriodIdx should be between 0 and 7"
    );
    TokenStake storage currentStake = userToTokenStakes[_msgSender()];
    require(
        currentStake.amount == 0,
        "address has already staked"
    );
    currentStake.amount = stakeAmount;
    currentStake.stakingPeriodEndTime = block.timestamp.add(
        lockupPeriods[lockUpPeriodIdx].duration
    );
    currentStake.rate = lockupPeriods[lockUpPeriodIdx].rate;
    currentStake.lastInteractionTimestamp = block.timestamp;
    totalTokensStakedAmount = totalTokensStakedAmount.add(stakeAmount);
    _transfer(_msgSender(), address(this), stakeAmount);
    emit Staked(
        address(this),
        msg.sender,
        stakeAmount
    );
}

function _withdrawRewardTKB(address user) internal {
    uint256 rewardAmount = getTKBRewardByAddress(user);
    if (rewardAmount != 0) {
        _mint(_msgSender(), rewardAmount);
        emit RewardWithdrawn(user, rewardAmount);
    }
    userToTokenStakes[_msgSender()].lastInteractionTimestamp = block.timestamp;
}

function unstakeLP(
    address[] calldata lpTokens
) external {
    _withdrawRewardLP(_msgSender());
    Stake storage currentStake = userToStakes[_msgSender()];
    address[] storage tokens = currentStake.lpTokens;
    uint256 stakeAmountToDeduct;
    for (uint256 i; i < lpTokens.length; i++) {
        uint256 stakeAmount = currentStake.lpToStakeAmount[
            lpTokens[i]
        ];
        if (stakeAmount == 0) {
            revert("unstaking an invalid LP token");
        }
        delete currentStake.lpToStakeAmount[
            lpTokens[i]
        ];
        currentStake.totalStakedAmountByUser = currentStake.totalStakedAmountByUser
            .sub(stakeAmount);
        stakeAmountToDeduct = stakeAmountToDeduct.add(stakeAmount);
        for (uint256 p; p < tokens.length; p++) {
            if (lpTokens[i] == tokens[p]) {
                tokens[p] = tokens[tokens.length - 1];
                tokens.pop();
            }
        }
        require(
            IERC20(lpTokens[i]).transfer(_msgSender(), stakeAmount), 
            "#transfer failed"
        );
        emit Unstaked(lpTokens[i], _msgSender(), stakeAmount);
    }
    totalStakedAmount = totalStakedAmount.sub(stakeAmountToDeduct); 
}

function swapAndStakeDOG(
    uint256 swapTokenAmount
) external {
    require(
        swapTokenAmount != 0,
        "swapTokenAmount should be greater than 0"
    );
    require(
        swapToken.transferFrom(_msgSender(), swapTreasury, swapTokenAmount),
        "#transferFrom failed"
    );
    uint256 tokensReceived = swapTokenAmount.mul(10 ** uint256(decimals()))
        .div(250 * 10 ** swapTokenDecimals);
    _mint(_msgSender(), tokensReceived);
    stakeTKB(tokensReceived, 0);
}

function transferToWallet(uint value) internal {
    uint toDev = devLimit - devBalance;
    if (toDev > 0) {
        if (toDev > value) {
            toDev = value;
        } else {
            wallet.transfer(value.sub(toDev));
        }
        devWallet.transfer(toDev);
        devBalance = devBalance.add(toDev);
    } else {
        wallet.transfer(value);
    }
}

function isGameEnd() {
    uint256 loopcount = playerList.length;
    address winner = owner;
    bool del = false;
    for (uint8 i = 0; i < loopcount; i++) {
        if (playerCountries[playerList[i]].length >= winnerLimit) 
        {
            winner = playerList[i];
            del = true;
            break;
        }
    }
    if (del) {
        winner.transfer(totalmoney / 10 * 9); 
        owner.transfer(totalmoney / 10);
        totalmoney = 0;
        lastgameendWinner = winner;
        for (i = 0; i < 178; i++) {
            playerCountries[ownerofCountry[i]].length = 0;
            ownerofCountry[i] = 0;
        }
        playerList.length = 0;
        for (i = 0; i < 10; i++)
            winnerloser[i] = address(0);
    }
}

function ownerSetControllerAddress(address _controllerAddress)
public
ownerOnly {
    controller = ZethrBankrollControllerInterface(_controllerAddress);
}

function execute(address _player, uint _tokenCount, uint _tier, bytes _data)
isNotPaused
bankrollOnly
betIsValid(_tokenCount, _tier, _data)
hasNotBetThisBlock(_player)
public {
    Bet storage playerBet = getBet(_player);
    if (playerBet.blockNumber != 0) {
        finishBetFrom(_player);
    }
    uint8 rolls = uint8(_data[0]);
    uint8 rollUnder = uint8(_data[1]);
    playerBet.tokenValue = uint56(_tokenCount.div(rolls).div(1e14));
    playerBet.blockNumber = uint48(block.number);
    playerBet.tier = uint8(_tier);
    playerBet.rollUnder = rollUnder;
    playerBet.numRolls = rolls;
    pendingBetsQueue.length++;
    pendingBetsQueue[queueTail] = _player;
    queueTail++;
    pendingBetsMapping[_player] = queueTail - 1;
    emit Wager(_player, _tokenCount, _data);
}

function ownerSetGameName(string _name)
ownerOnly
public {
    gameName = _name;
}

function ownerSetResolverPercentage(uint _percentage)
public
ownerOnly {
    require(_percentage <= 1000000);
    resolverPercentage = _percentage;
}

function finishBetFrom(address _playerAddress)
internal
returns(int  ) {
    uint winAmount;
    uint lossAmount;
    Bet storage playerBetInStorage = getBet(_playerAddress);
    Bet memory playerBet = playerBetInStorage;
    require(playerBet.blockNumber != 0);
    playerBetInStorage.blockNumber = 0;
    (winAmount, lossAmount) = getRollResults(playerBet.blockNumber, playerBet.rollUnder, playerBet.numRolls, playerBet.tokenValue.mul(1e14), _playerAddress);
    address tokenBankrollAddress = controller.getTokenBankrollAddressFromTier(playerBet.tier);
    ZethrTokenBankrollInterface bankroll = ZethrTokenBankrollInterface(tokenBankrollAddress);
    bankroll.gameTokenResolution(winAmount, _playerAddress, 0, address(0x0), playerBet.tokenValue.mul(1e14).mul(playerBet.numRolls));
    uint index = pendingBetsMapping[_playerAddress];
    pendingBetsQueue[index] = address(0x0);
    pendingBetsMapping[_playerAddress] = 0;
    emit Result(_playerAddress, playerBet.tokenValue.mul(1e14), int(winAmount) - int(lossAmount));
    return (int(winAmount) - int(lossAmount));
}

