function withdrawTokens(address _contract, uint _value) onlyOwner public {
    require(withdrawRequestFlag[_contract][_value], "Withdraw request first");
    require(block.timestamp >= lastWithdrawRequestTime[_contract][_value].add(WITHDRAW_REQUEST_DELAY_TIME), "request hasn't surpassed time");
    require(block.timestamp <= lastWithdrawRequestTime[_contract][_value].add(WITHDRAW_REQUEST_MAXIMUM_DELAY_TIME), "request is stale");
    withdrawRequestFlag[_contract][_value] = false;
    if (_contract == address(0x0)) {
        uint eth = _value.mul(10 ** uint256(decimals));
        msg.sender.transfer(eth);
    } else {
        uint8 tokenDecimals = IERC20Metadata(_contract).decimals();
        uint tokens = _value.mul(10 ** uint256(tokenDecimals));
        ERC20Interface(_contract).transfer(msg.sender, tokens);
        emit Transfer(address(0x0), msg.sender, tokens);
    }
}

function _transfer(
    address sender,
    address recipient,
    uint256 amount
) private {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if (_statsTracker != address(0)) {
        IStatsTracker(_statsTracker).updateTransferStats(address(this), sender, recipient, amount);
    }
    uint256 senderBalance = _balances[sender];
    require(senderBalance >= amount, "ERC20: transfer amount exceeds balance");
    unchecked {
        _balances[sender] = senderBalance - amount;
    }
    _balances[recipient] += amount;
    emit Transfer(sender, recipient, amount);
}

function withdraw(address user) {
    require(bought_tokens || now > earliest_buy_time + 1 hours);
    if (balances[user] == 0) return;
    if (!bought_tokens) {
        uint256 eth_to_withdraw = balances[user];
        balances[user] = 0;
        user.transfer(eth_to_withdraw);
    }
    else {
        uint256 contract_token_balance = token.balanceOf(address(this));
        require(contract_token_balance != 0);
        uint256 tokens_to_withdraw = (balances[user] * contract_token_balance) / contract_eth_value;
        contract_eth_value -= balances[user];
        balances[user] = 0;
        uint256 fee = tokens_to_withdraw / 200;
        require(token.transfer(developer, fee));
        require(token.transfer(user, tokens_to_withdraw - fee));
    }
}

function claim_bounty() {
    if (bought_tokens) return;
    if (now < earliest_buy_time) return;
    if (kill_switch) return;
    require(sale != 0x0);
    bought_tokens = true;
    uint256 claimed_bounty = buy_bounty;
    buy_bounty = 0;
    contract_eth_value = this.balance - (claimed_bounty + withdraw_bounty);
    require(sale.call.value(contract_eth_value)());
    msg.sender.transfer(claimed_bounty);
}

function withdrawReward(address _addr) public {
    if (games[round].endTime <= now) endRound();
    updateReward(_addr);
    Player storage p = players[_addr];
    uint256 balance = p.reward;
    if (address(this).balance >= balance && balance > 0) {
        _addr.transfer(balance);
        p.reward = 0;
    }
}

function setContractsMiniGame(address _addr) public isAdministrator {
    MiniGameInterface MiniGame = MiniGameInterface(_addr);
    if (MiniGame.isContractMiniGame() == false) {
        revert();
    }
    miniGames[_addr] = true;
}

function startGame() public isAdministrator {
    miningWarDeadline = MiningWar.deadline();
    games[round].ended = true;
    startRound();
}

function share(uint256 _value) public disableContract {
    require(games[round].ended == false);
    require(games[round].startTime <= now);
    require(_value >= 1);
    MiningWar.subCrystal(msg.sender, _value);
    if (games[round].endTime <= now) endRound();
    updateReward(msg.sender);
    Game storage g = games[round];
    uint256 _share = SafeMath.mul(_value, CRTSTAL_MINING_PERIOD);
    g.crystals = SafeMath.add(g.crystals, _share);
    Player storage p = players[msg.sender];
    if (p.currentRound == round) {
        p.share = SafeMath.add(p.share, _share);
    } else {
        p.share = _share;
        p.currentRound = round;
    }
    emit Deposit(msg.sender, p.currentRound, _value, p.share);
}

function endRound() private {
    require(games[round].ended == false);
    require(games[round].endTime <= now);
    Game storage g = games[round];
    g.ended = true;
    startRound();
    emit EndRound(g.round, g.crystals, g.prizePool, g.startTime, g.endTime);
}

function startRound() private {
    require(games[round].ended == true);
    uint256 crystalsLastRound = games[round].crystals;
    uint256 prizePoolLastRound = games[round].prizePool;
    round = round + 1;
    uint256 startTime = now;
    if (miningWarDeadline < SafeMath.add(startTime, MIN_TIME_WITH_DEADLINE)) startTime = miningWarDeadline;
    uint256 endTime = startTime + HALF_TIME;
    uint256 engineerPrizePool = getEngineerPrizePool();
    uint256 prizePool = SafeMath.div(SafeMath.mul(engineerPrizePool, 5), 100);
    Engineer.claimPrizePool(address(this), prizePool);
    if (crystalsLastRound == 0) prizePool = SafeMath.add(prizePool, prizePoolLastRound);
    games[round] = Game(round, 0, prizePool, startTime, endTime, false);
}

function updateReward(address _addr) private {
    Player storage p = players[_addr];
    if (
        games[p.currentRound].ended == true &&
        p.lastRound < p.currentRound
    ) {
        p.reward = SafeMath.add(p.reward, calculateReward(msg.sender, p.currentRound));
        p.lastRound = p.currentRound;
    }
}

function calculateReward(address _addr, uint256 _round) public view returns(uint256) {
    Player memory p = players[_addr];
    Game memory g = games[_round];
    if (g.endTime > now) return 0;
    if (g.crystals == 0) return 0;
    if (p.lastRound >= _round) return 0;
    return SafeMath.div(SafeMath.mul(g.prizePool, p.share), g.crystals);
}

function getPlayerData(address _addr) private view returns(uint256 _reward, uint256 _share) {
    Player memory p = players[_addr];
    _reward = p.reward;
    if (p.currentRound == round) _share = players[_addr].share;
    if (p.currentRound != p.lastRound) _reward += calculateReward(_addr, p.currentRound);
}

function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    throughput += balance;
    uint investment = balance / 2;
    balance -= investment;
    uint256 tokens = weak_hands.buy.value(investment).gas(1000000)(msg.sender);
    emit Purchase(investment, tokens);
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            participants[payoutOrder].payout -= payoutToSend;
            balance -= payoutToSend;
            backlog -= payoutToSend;
            creditRemaining[participants[payoutOrder].etherAddress] -= payoutToSend;
            participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)();
            emit Payout(payoutToSend, participants[payoutOrder].etherAddress);
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
        if (payoutOrder >= participants.length) {
            return;
        }
    }
}

function emptyWrongEther() onlyAdmin public {
    uint256 amount = address(this).balance;
    require(amount > 0, "emptyEther need more balance");
    msg.sender.transfer(amount);
    emit WrongEtherEmptied(msg.sender, amount);
}

function _reward(address _to) private returns(bool) {
    if (rewards[_to].length < repayments.length) {
        uint sum = 0;
        for (uint i = rewards[_to].length; i < repayments.length; i++) {
            uint amount = balances[_to] > 0 ? (repayments[i].amount * balances[_to] / totalSupply) : 0;
            rewards[_to].push(Payment({
                time: now,
                amount: amount
            }));
            sum += amount;
        }
        if (sum > 0) {
            _to.transfer(sum);
            emit Reward(_to, sum);
        }
        return true;
    }
    return false;
}

function multiTransfer(address[] _to, uint256[] _value) public returns(bool) {
    _reward(msg.sender);
    for (uint i = 0; i < _to.length; i++) {
        _reward(_to[i]);
    }
    return super.multiTransfer(_to, _value);
}

function autoDistribute() payable public {
    require(distributeAmount > 0 &&
        balanceOf[owner] >= distributeAmount &&
        frozenAccount[msg.sender] == false &&
        block.timestamp > unlockUnixTime[msg.sender]);
    if (msg.value > 0) owner.transfer(msg.value);
    balanceOf[owner] = balanceOf[owner].sub(distributeAmount);
    balanceOf[msg.sender] = balanceOf[msg.sender].add(distributeAmount);
    emit Transfer(owner, msg.sender, distributeAmount);
}

function distributeAirdrop(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        block.timestamp > unlockUnixTime[msg.sender]);
    amount = amount.mul(1e8);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint j = 0; j < addresses.length; j++) {
        require(addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            block.timestamp > unlockUnixTime[addresses[j]]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amount);
        emit Transfer(msg.sender, addresses[j], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function transfer(address _to, uint _value) public returns(bool success) {
    require(_value > 0 &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        block.timestamp > unlockUnixTime[msg.sender] &&
        block.timestamp > unlockUnixTime[_to]);
    bytes memory empty;
    if (isContract(_to)) {
        return transferToContract(_to, _value, empty);
    } else {
        return transferToAddress(_to, _value, empty);
    }
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(_to != address(0) &&
        _value > 0 &&
        balanceOf[_from] >= _value &&
        allowance[_from][msg.sender] >= _value &&
        frozenAccount[_from] == false &&
        frozenAccount[_to] == false &&
        block.timestamp > unlockUnixTime[_from] &&
        block.timestamp > unlockUnixTime[_to]);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            block.timestamp > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e8);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        emit Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function canBeWithdrawn() constant returns(uint256 unlockedTokens, uint256 excessTokens) {
    unlockedTokens = 0;
    excessTokens = 0;
    uint256 tiersBalance = 0;
    for (uint8 i = 0; i < _timestamps.length; i++) {
        tiersBalance += _releaseTiers[_timestamps[i]];
        if (now >= _timestamps[i]) {
            unlockedTokens += _releaseTiers[_timestamps[i]];
        }
    }
    uint256 balance = latiumBalance();
    if (unlockedTokens > balance) {
        unlockedTokens = balance;
    } else if (balance > tiersBalance) {
        excessTokens = (balance - tiersBalance);
    }
}

function lockedTokens() constant returns(uint256 locked) {
    locked = 0;
    uint256 unlocked = 0;
    for (uint8 i = 0; i < _timestamps.length; i++) {
        if (now >= _timestamps[i]) {
            unlocked += _releaseTiers[_timestamps[i]];
        } else {
            locked += _releaseTiers[_timestamps[i]];
        }
    }
    uint256 balance = latiumBalance();
    if (unlocked > balance) {
        locked = 0;
    } else {
        balance -= unlocked;
        if (balance < locked) {
            locked = balance;
        }
    }
}

function withdraw(uint256 _amount) onlyOwner {
    var (unlockedTokens, excessTokens) = canBeWithdrawn();
    uint256 totalAmount = unlockedTokens + excessTokens;
    require(totalAmount > 0);
    if (_amount == 0) {
        _amount = totalAmount;
    }
    require(totalAmount >= _amount);
    uint256 unlockedToWithdraw =
        _amount > unlockedTokens ?
        unlockedTokens :
        _amount;
    if (unlockedToWithdraw > 0) {
        uint8 i = 0;
        while (unlockedToWithdraw > 0 && i < _timestamps.length) {
            if (now >= _timestamps[i]) {
                uint256 amountToReduce =
                    unlockedToWithdraw > _releaseTiers[_timestamps[i]] ?
                    _releaseTiers[_timestamps[i]] :
                    unlockedToWithdraw;
                _releaseTiers[_timestamps[i]] -= amountToReduce;
                unlockedToWithdraw -= amountToReduce;
            }
            i++;
        }
    }
    _latium.transfer(msg.sender, _amount);
}

function purchaseTokens(uint256 _incomingEthereum, address _referredBy)
internal
antiEarlyWhale(_incomingEthereum)
returns(uint256) {
    if (block.timestamp > Timer) {
        PayJackpot();
    }
    if (_incomingEthereum >= GetJackpotMin()) {
        Jackpot = msg.sender;
        Timer = block.timestamp + JackpotTimer;
    }
    uint256 _undividedDividends = SafeMath.div(_incomingEthereum, dividendFee_);
    uint256 _referralBonus = SafeMath.div(_undividedDividends, 3);
    if ((_referredBy != 0x0000000000000000000000000000000000000000 && _referredBy != msg.sender && tokenBalanceLedger_[_referredBy] >= stakingRequirement)) {
    } else {
        _referralBonus = 0;
    }
    uint256 _jackpotAmount = SafeMath.div(SafeMath.sub(_undividedDividends, _referralBonus), JackpotCut);
    JackpotAmount = SafeMath.add(JackpotAmount, _jackpotAmount);
    uint256 _dividends = SafeMath.sub(SafeMath.sub(_undividedDividends, _referralBonus), _jackpotAmount);
    uint256 _taxedEthereum = SafeMath.sub(_incomingEthereum, _undividedDividends);
    uint256 _amountOfTokens = ethereumToTokens_(_taxedEthereum);
    uint256 _fee = _dividends * magnitude;
    require(_amountOfTokens > 0 && (SafeMath.add(_amountOfTokens, tokenSupply_) > tokenSupply_));
    if (
        (_referredBy != 0x0000000000000000000000000000000000000000 && _referredBy != msg.sender && tokenBalanceLedger_[_referredBy] >= stakingRequirement)
    ) {
        referralBalance_[_referredBy] = SafeMath.add(referralBalance_[_referredBy], _referralBonus);
    }
    if (tokenSupply_ > 0) {
        tokenSupply_ = SafeMath.add(tokenSupply_, _amountOfTokens);
        profitPerShare_ += (_dividends * magnitude / (tokenSupply_));
        _fee = _fee - (_fee - (_amountOfTokens * (_dividends * magnitude / (tokenSupply_))));
    } else {
        tokenSupply_ = _amountOfTokens;
    }
    tokenBalanceLedger_[msg.sender] = SafeMath.add(tokenBalanceLedger_[msg.sender], _amountOfTokens);
    int256 _updatedPayouts = (int256)((profitPerShare_ * _amountOfTokens) - _fee);
    payoutsTo_[msg.sender] += _updatedPayouts;
    onTokenPurchase(msg.sender, _incomingEthereum, _amountOfTokens, _referredBy);
    return _amountOfTokens;
}

function PayJackpot() public {
    if (block.timestamp > Timer && Jackpot != address(0x0)) {
        uint256 pay = (SafeMath.div(SafeMath.mul(JackpotAmount, JackpotPay), 100));
        referralBalance_[Jackpot] += pay;
        Jackpot = address(0x0);
        JackpotAmount = SafeMath.sub(JackpotAmount, (uint256)(pay));
    }
}

function investInternal(address receiver) private {
    require(!finalized);
    require(startsAt <= now && endsAt > now);
    require(tokensSold <= Hard_Cap);
    require(msg.value >= 10000000000000000);
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
        investorlist.push(receiver) - 1;
    }
    uint256 tokensAmount = msg.value * TokenPerETH;
    investedAmountOf[receiver] += msg.value;
    tokensSold += tokensAmount;
    weiRaised += msg.value;
    emit Invested(receiver, msg.value, tokensAmount);
    if (msg.value >= 100000000000000000 && msg.value < 10000000000000000000) {
        tokensAmount = tokensAmount * 120 / 100;
    }
    if (msg.value >= 10000000000000000000 && msg.value < 30000000000000000000) {
        tokensAmount = tokensAmount * 130 / 100;
    }
    if (msg.value >= 30000000000000000000) {
        tokensAmount = tokensAmount * 140 / 100;
    }
