function() external payable {
    address sender = msg.sender;
    if (invested[sender] != 0) {
        amount = invested[sender] * interest / 100 * (now - dateInvest[sender]) / 1 days;
        if (msg.value == 0) {
            if (amount >= address(this).balance) {
                amount = (address(this).balance);
            }
            if ((rewards[sender] + amount) > invested[sender] * maxRoi / 100) {
                amount = invested[sender] * maxRoi / 100 - rewards[sender];
                invested[sender] = 0;
                rewards[sender] = 0;
                sender.send(amount);
                return;
            } else {
                sender.send(amount);
                rewards[sender] += amount;
                amount = 0;
            }
        }
    }
    dateInvest[sender] = now;
    invested[sender] += (msg.value + amount);
    if (msg.value != 0) {
        WhaleAddr.send(msg.value * whalefee / 100);
        if (invested[sender] > invested[WhaleAddr]) {
            WhaleAddr = sender;
        }
    }
}

function distribute(uint256 _percent)
public
isHuman() {
    require(_percent > 0 && _percent < 100, "please pick a percent between 1 and 99");
    address _pusher = msg.sender;
    uint256 _bal = address(this).balance;
    uint256 _mnPayout;
    uint256 _compressedData;
    if (
        pushers_[_pusher].tracker <= pusherTracker_.sub(100) && 
        pushers_[_pusher].time.add(1 hours) < now 
    ) {
        pushers_[_pusher].tracker = pusherTracker_;
        pusherTracker_++;
        if (P3Dcontract_.balanceOf(_pusher) >= P3Dcontract_.stakingRequirement())
            _mnPayout = (_bal / 10) / 3;
        uint256 _stop = (_bal.mul(100 - _percent)) / 100;
        P3Dcontract_.buy.value(_bal)(_pusher);
        P3Dcontract_.sell(P3Dcontract_.balanceOf(address(this)));
        uint256 _tracker = P3Dcontract_.dividendsOf(address(this));
        while (_tracker >= _stop) {
            P3Dcontract_.reinvest();
            P3Dcontract_.sell(P3Dcontract_.balanceOf(address(this)));
            _tracker = (_tracker.mul(81)) / 100;
        }
        P3Dcontract_.withdraw();
    } else {
        _compressedData = _compressedData.insert(1, 47, 47);
    }
    pushers_[_pusher].time = now;
    _compressedData = _compressedData.insert(now, 0, 14);
    _compressedData = _compressedData.insert(pushers_[_pusher].tracker, 15, 29);
    _compressedData = _compressedData.insert(pusherTracker_, 30, 44);
    _compressedData = _compressedData.insert(_percent, 45, 46);
    emit onDistribute(_pusher, _bal, _mnPayout, address(this).balance, _compressedData);
}

function() payable {
    msg.sender.transfer(msg.value); 
    State state = _state();
    if (state == State.INIT) {
        require(indexOf(team_accounts, msg.sender) == -1);
        team_accounts.push(msg.sender);
    } else if (state == State.WITHDRAWAL) {
        if (amount_to_distribute == 0) amount_to_distribute = token.balanceOf(this);
        require(indexOf(team_accounts, msg.sender) >= 0);
        token.transfer(msg.sender, amount_to_distribute / team_accounts.length);
    } else if (state == State.CLOSED) {
        require(msg.sender == TEAM_WALLET);
        var balance = token.balanceOf(this);
        token.transfer(msg.sender, balance);
    } else {
        revert();
    }
}

function _state() internal returns(State) {
    if (locked_since == 0) return State.INIT;
    else if (now < LOCK_RELASE_TIME) return State.LOCKED;
    else if (now < WITHDRAWAL_END_TIME) return State.WITHDRAWAL;
    else return State.CLOSED;
}

function timeToUnlockDDHHMM() external constant returns(uint[3]) {
    if (LOCK_RELASE_TIME > now) {
        uint diff = LOCK_RELASE_TIME - now;
        uint dd = diff / 1 days;
        uint hh = diff % 1 days / 1 hours;
        uint mm = diff % 1 hours / 1 minutes;
        return [dd, hh, mm];
    } else {
        return [uint(0), uint(0), uint(0)];
    }
}

