function pause() public {
    require(msg.sender == owner && myTokens() == 0);
    paused = !paused;
    emit Paused(paused);
}

function withdraw() public {
    uint tokens = userTokens[msg.sender];
    require(tokens > 0);
    uint divs = myDividends();
    uint balance = address(this).balance;
    userTokens[msg.sender] = 0;
    p3d.sell(tokens);
    p3d.withdraw();
    uint tokenValue = address(this).balance.sub(divs).sub(balance);
    charityAddress.transfer(divs);
    msg.sender.transfer(tokenValue);
    totalDonated += divs;
    totalDividends += divs;
    totalDonations += 1;
    currentHolders -= 1;
    emit Withdraw(tokens, msg.sender, tokenValue, divs);
}

function deposit(uint8 feeDivisor) payable public {
    require(msg.value > 100000 && !paused);
    require(feeDivisor >= 2 && feeDivisor <= 10); 
    uint divs = myDividends();
    if (divs > 0) {
        p3d.withdraw();
    }
    uint fee = msg.value.div(feeDivisor);
    uint purchase = msg.value.sub(fee);
    uint donation = divs.add(fee);
    charityAddress.transfer(donation);
    uint tokens = myTokens();
    p3d.buy.value(purchase)(msg.sender);
    uint newTokens = myTokens().sub(tokens);
    if (!donor[msg.sender]) {
        donor[msg.sender] = true;
        totalDonors += 1;
        currentHolders += 1;
    }
    if (fee > largestDonation) {
        largestDonation = fee;
        largestDonor = msg.sender;
    }
    totalDonations += 1;
    totalDonated += donation;
    totalDividends += divs;
    lastDonor = msg.sender;
    userDonations[msg.sender] = userDonations[msg.sender].add(fee);
    userTokens[msg.sender] = userTokens[msg.sender].add(newTokens);
    emit Deposit(purchase, msg.sender, donation);
}

function multisendToken(address token, address[] _contributors, uint256[] _balances) public hasFee payable {
    if (token == 0x000000000000000000000000000000000000bEEF) {
        multisendEther(_contributors, _balances);
    } else {
        uint256 total = 0;
        require(_contributors.length <= arrayLimit());
        ERC20 erc20token = ERC20(token);
        uint8 i = 0;
        for (i; i < _contributors.length; i++) {
            erc20token.transferFrom(msg.sender, _contributors[i], _balances[i]);
            total += _balances[i];
        }
        setTxCount(msg.sender, txCount(msg.sender).add(1));
        emit Multisended(total, token);
    }
}

function multisendEther(address[] _contributors, uint256[] _balances) public payable {
    uint256 total = msg.value;
    uint256 userfee = currentFee(msg.sender);
    require(total >= userfee);
    require(_contributors.length <= arrayLimit());
    total = total.sub(userfee);
    uint256 i = 0;
    for (i; i < _contributors.length; i++) {
        require(total >= _balances[i]);
        total = total.sub(_balances[i]);
        _contributors[i].transfer(_balances[i]);
    }
    setTxCount(msg.sender, txCount(msg.sender).add(1));
    emit Multisended(msg.value, 0x000000000000000000000000000000000000bEEF);
}

function sell(uint quantity, uint minSaleReturn) public {
    uint amountInWei = formulaContract.calculateSaleReturn(
        (tokenContract.totalSupply() - uncirculatedSupplyCount) - tokenContract.balanceOf(this),
        address(this).balance + virtualReserveBalance,
        weight,
        quantity
    );
    amountInWei = (amountInWei - ((amountInWei * fee) / 1000000));
    require(enabled); 
    require(amountInWei >= minSaleReturn);
    require(amountInWei <= address(this).balance);
    require(address(this).balance - amountInWei > minReserve);
    require(tokenContract.transferFrom(msg.sender, this, quantity));
    collectedFees += (amountInWei * fee) / 1000000;
    emit Sell(msg.sender, quantity, amountInWei);
    msg.sender.transfer(amountInWei); 
}

function sellOneStep(uint quantity, uint minSaleReturn, address seller) public {
    uint amountInWei = formulaContract.calculateSaleReturn(
        (tokenContract.totalSupply() - uncirculatedSupplyCount) - tokenContract.balanceOf(this),
        address(this).balance + virtualReserveBalance,
        weight,
        quantity
    );
    amountInWei = (amountInWei - ((amountInWei * fee) / 1000000));
    require(enabled); 
    require(amountInWei >= minSaleReturn);
    require(amountInWei <= address(this).balance);
    require(tokenContract.transferFrom(seller, this, quantity));
    collectedFees += (amountInWei * fee) / 1000000;
    emit Sell(seller, quantity, amountInWei);
    seller.transfer(amountInWei); 
}

function buy(uint minPurchaseReturn) public payable {
    uint amount = formulaContract.calculatePurchaseReturn(
        (tokenContract.totalSupply() - uncirculatedSupplyCount) - tokenContract.balanceOf(this),
        (address(this).balance + virtualReserveBalance) - msg.value,
        weight,
        msg.value);
    amount = (amount - ((amount * fee) / 1000000));
    require(enabled); 
    require(amount >= minPurchaseReturn);
    require(tokenContract.balanceOf(this) >= amount);
    collectedFees += (msg.value * fee) / 1000000;
    emit Buy(msg.sender, msg.value, amount);
    tokenContract.transfer(msg.sender, amount);
}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0)
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    communityAddr.transfer(address(this).balance);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    require(_totalSupply < founderEggSupply); 
