function claimRewards(
    address user,
    uint256 stakeId,
    uint256 totalStaking
) internal {
    (
        address[] memory referrerAddress,
        address[] memory tokenAddress, , ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = (u2.viewStakingDetails(user));
    uint256 interval;
    uint256 endOfProfit;
    interval = poolStartTime.add(u2.stakeDuration());
    if (interval > block.timestamp) endOfProfit = block.timestamp;
    else endOfProfit = interval;
    interval = endOfProfit.sub(startTime[stakeId]);
    if (interval >= DAYS)
        _rewardCalculation(
            user,
            referrerAddress[stakeId],
            tokenAddress[stakeId],
            stakedAmount[stakeId],
            interval,
            totalStaking
        );
}

function sendToken(
    address user,
    address stakedToken,
    address tokenAddress,
    uint256 amount
) internal {
    if (tokenAddress != address(0)) {
        require(
            IERC20(tokenAddress).balanceOf(address(this)) >= amount,
            "SEND : Insufficient Balance"
        );
        require(
            IERC20(tokenAddress).transfer(user, amount),
            "Transfer failed"
        );
        emit Claim(
            user,
            stakedToken,
            tokenAddress,
            amount,
            block.timestamp
        );
    }
}

function unStake(address user, uint256 stakeId) external whenNotPaused {
    require(
        msg.sender == user || msg.sender == _owner,
        "UNSTAKE: Invalid User Entry"
    );
    (,
        address[] memory tokenAddress,
        bool[] memory activeStatus, ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = (u2.viewStakingDetails(user));
    bool isAlreadyUnstaked = u2Proxy.unstakeStatus(user, stakeId);
    require(
        u2UpgradeLockableDetails[tokenAddress[stakeId]].lockableDays <=
        block.timestamp,
        "Token Locked"
    );
    if (
        u2UpgradeLockableDetails[tokenAddress[stakeId]].optionableStatus ==
        true
    ) {
        require(
            poolStartTime.add(u2.stakeDuration()) <= block.timestamp,
            "Locked in optional lock"
        );
    }
    if (
        u2UnstakeStatus[user][stakeId] == false &&
        activeStatus[stakeId] == true &&
        isAlreadyUnstaked == false
    ) u2UnstakeStatus[user][stakeId] = true;
    else revert("UNSTAKE : Unstaked Already");
    uint256 totalUnstaking = getTotalUnstaking(tokenAddress[stakeId]);
    uint256 totalStaking = u2.totalStaking(tokenAddress[stakeId]).sub(
        totalUnstaking
    );
    u2UpgradeTotalUnStaking[
        tokenAddress[stakeId]
    ] = u2UpgradeTotalUnStaking[tokenAddress[stakeId]].add(
        stakedAmount[stakeId]
    );
    require(
        IERC20(tokenAddress[stakeId]).balanceOf(address(this)) >=
        stakedAmount[stakeId],
        "UNSTAKE : Insufficient Balance"
    );
    IERC20(tokenAddress[stakeId]).transfer(user, stakedAmount[stakeId]);
    if (startTime[stakeId] < poolStartTime.add(u2.stakeDuration())) {
        claimRewards(user, stakeId, totalStaking);
    }
    emit UnStake(
        user,
        tokenAddress[stakeId],
        stakedAmount[stakeId],
        block.timestamp,
        stakeId
    );
}

function _rewardCalculation(
    address user,
    address referrerAddress,
    address stakedToken,
    uint256 stakedAmount,
    uint256 interval,
    uint256 totalStake
) internal {
    uint256 rewardsEarned;
    uint256 noOfDays;
    noOfDays = interval.div(DAYS);
    rewardsEarned = noOfDays.mul(
        getOneDayReward(stakedAmount, stakedToken, stakedToken, totalStake)
    );
    if (referrerAddress != address(0)) {
        uint256 refEarned = (rewardsEarned.mul(u2.refPercentage())).div(
            100 ether
        );
        rewardsEarned = rewardsEarned.sub(refEarned);
        require(
            IERC20(stakedToken).transfer(referrerAddress, refEarned),
            "Transfer Failed"
        );
        emit ReferralEarn(
            referrerAddress,
            user,
            stakedToken,
            refEarned,
            block.timestamp
        );
    }
    sendToken(user, stakedToken, stakedToken, rewardsEarned);
    uint8 i = 1;
    while (i < intervalDays.length) {
        if (noOfDays >= intervalDays[i]) {
            uint256 balDays = noOfDays.sub((intervalDays[i].sub(1)));
            address rewardToken = u2.tokensSequenceList(stakedToken, i);
            if (
                rewardToken != stakedToken &&
                u2.tokenBlockedStatus(stakedToken, rewardToken) == false
            ) {
                rewardsEarned = balDays.mul(
                    getOneDayReward(
                        stakedAmount,
                        stakedToken,
                        rewardToken,
                        totalStake
                    )
                );
                if (referrerAddress != address(0)) {
                    uint256 refEarned = (
                            rewardsEarned.mul(u2.refPercentage())
                        )
                        .div(100 ether);
                    rewardsEarned = rewardsEarned.sub(refEarned);
                    require(
                        IERC20(rewardToken).transfer(
                            referrerAddress,
                            refEarned
                        ),
                        "Transfer Failed"
                    );
                    emit ReferralEarn(
                        referrerAddress,
                        user,
                        rewardToken,
                        refEarned,
                        block.timestamp
                    );
                }
                sendToken(user, stakedToken, rewardToken, rewardsEarned);
            }
            i = i + 1;
        } else {
            break;
        }
    }
}

function emergencyUnstake(
    uint256 stakeId,
    address userAddress,
    address[] memory rewardtokens,
    uint256[] memory amount
) external onlyOwner {
    (
        address[] memory referrerAddress,
        address[] memory tokenAddress,
        bool[] memory activeStatus, ,
        uint256[] memory stakedAmount,
    ) = (u2.viewStakingDetails(userAddress));
    bool isAlreadyUnstaked = u2Proxy.unstakeStatus(userAddress, stakeId);
    if (
        u2UnstakeStatus[userAddress][stakeId] == false &&
        activeStatus[stakeId] == true &&
        isAlreadyUnstaked == false
    ) u2UnstakeStatus[userAddress][stakeId] = true;
    else revert("EMERGENCY: Unstaked Already");
    safeTransfer(tokenAddress[stakeId]);
    require(
        IERC20(tokenAddress[stakeId]).balanceOf(address(this)) >=
        stakedAmount[stakeId],
        "EMERGENCY : Insufficient Balance"
    );
    u2UpgradeTotalUnStaking[
        tokenAddress[stakeId]
    ] = u2UpgradeTotalUnStaking[tokenAddress[stakeId]].add(
        stakedAmount[stakeId]
    );
    IERC20(tokenAddress[stakeId]).transfer(
        userAddress,
        stakedAmount[stakeId]
    );
    for (uint256 i = 0; i < rewardtokens.length; i++) {
        require(
            IERC20(rewardtokens[i]).balanceOf(address(this)) >= amount[i],
            "EMERGENCY : Insufficient Reward Balance"
        );
        uint256 rewardsEarned = amount[i];
        safeTransfer(tokenAddress[stakeId]);
        if (referrerAddress[stakeId] != address(0)) {
            uint256 refEarned = (rewardsEarned.mul(u2.refPercentage())).div(
                100 ether
            );
            rewardsEarned = rewardsEarned.sub(refEarned);
            require(
                IERC20(rewardtokens[i]).transfer(
                    referrerAddress[stakeId],
                    refEarned
                ),
                "EMERGENCY : Transfer Failed"
            );
            emit ReferralEarn(
                referrerAddress[stakeId],
                userAddress,
                rewardtokens[i],
                refEarned,
                block.timestamp
            );
        }
        sendToken(
            userAddress,
            tokenAddress[stakeId],
            rewardtokens[i],
            rewardsEarned
        );
    }
    emit UnStake(
        userAddress,
        tokenAddress[stakeId],
        stakedAmount[stakeId],
        block.timestamp,
        stakeId
    );
}

function setReleaseTime(address _holder, uint256 _release_time)
public
onlyOwner
returns(bool)
{
    require(_holder != address(0));
    require(_release_time >= block.timestamp);
    uint256 old_release_time = userLock[_holder].release_time;
    userLock[_holder].release_time = _release_time;
    emit LockTimeSetted(_holder, old_release_time, userLock[_holder].release_time);
    return true;
}

function getFreeBalance(address _holder)
public
view
returns(uint256)
{
    if (block.timestamp >= userLock[_holder].release_time) return balances[_holder];
    return balances[_holder].sub(userLock[_holder].locked_balance);
}

function getLockedBalance(address _holder)
public
view
returns(uint256)
{
    if (block.timestamp >= userLock[_holder].release_time) return uint256(0);
    return userLock[_holder].locked_balance;
}

function getRateAt(uint256 at) public view returns(uint256) {
    if (at < startDate) {
        return 0;
    } else if (at < (startDate + 15 days)) { 
        return 10500;
    } else {
        return 10000;
    }
}

function saleActive() public view returns(bool) {
    return (now >= startDate &&
        now <= endDate && supply() > 0);
}

function noteTokens(address _beneficiary, uint256 _tokenAmount) external onlyOwner onlyWhenLocked {
    uint256 tokenBalance = tokenContract.balanceOf(this);
    require(tokenBalance == totalTokens.add(_tokenAmount));
    tokens[_beneficiary] = tokens[_beneficiary].add(_tokenAmount);
    totalTokens = totalTokens.add(_tokenAmount);
    NotedTokens(_beneficiary, _tokenAmount);
}

function releaseTokens(address _beneficiary) public onlyWhenUnlocked {
    uint256 amount = tokens[_beneficiary];
    tokens[_beneficiary] = 0;
    require(tokenContract.transfer(_beneficiary, amount));
    totalTokens = totalTokens.sub(amount);
    ReleasedTokens(_beneficiary);
}

function isLocked() public view returns(bool) {
    return now < unlockTime;
}

function reduceLockingTime(uint256 _newUnlockTime) public onlyOwner onlyWhenLocked {
    require(_newUnlockTime >= now);
    require(_newUnlockTime < unlockTime);
    unlockTime = _newUnlockTime;
    ReducedLockingTime(_newUnlockTime);
}

function purchaseAccessory(uint256 _tittyId, uint256 _accId, string _name, uint256 _price) public payable {
    if (msg.value == 0 && msg.value != _price)
        revert();
    wallet.transfer(msg.value);
    addAccessory(_accId, _name, _price, _tittyId);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!bots[from] && !bots[to]);
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (limitsInEffect) {
        if (
            from != owner() &&
            to != owner() &&
            to != address(0) &&
            to != address(0xdead) &&
            !swapping
        ) {
            if (!tradingActive) {
                require(_isExcludedFromFees[from] || _isExcludedFromFees[to], "Trading is not active.");
            }
            if (automatedMarketMakerPairs[from] && !_isExcludedMaxTransactionAmount[to]) {
                require(amount <= maxTransactionAmount, "Buy transfer amount exceeds the maxTransactionAmount.");
            }
            else if (automatedMarketMakerPairs[to] && !_isExcludedMaxTransactionAmount[from]) {
                require(amount <= maxTransactionAmount, "Sell transfer amount exceeds the maxTransactionAmount.");
            }
        }
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        swapEnabled &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        !_isExcludedFromFees[from] &&
        !_isExcludedFromFees[to]
    ) {
        swapping = true;
        swapBack();
        swapping = false;
    }
    bool takeFee = !swapping;
    uint256 maxFees = 10; 
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    } else if (automatedMarketMakerPairs[to]) {
        maxFees = maxFees.sub(_maxAccountWallet);
    }
    uint256 fees = 0;
    if (takeFee) {
        if (automatedMarketMakerPairs[to] && sellTotalFees > 0) {
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity += fees * sellLiquidityFee / sellTotalFees;
            tokensForDev += fees * sellDevFee / sellTotalFees;
            tokensForMarketing += fees * sellMarketingFee / sellTotalFees;
        }
        else if (automatedMarketMakerPairs[from] && buyTotalFees > 0) {
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity += fees * buyLiquidityFee / buyTotalFees;
            tokensForDev += fees * buyDevFee / buyTotalFees;
            tokensForMarketing += fees * buyMarketingFee / buyTotalFees;
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
        }
        amount -= fees;
    }
    super._transfer(from, to, amount);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 50000001;
    } else {
        tokens = msg.value * 14000000000000000000000000000000000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function pendingToken(uint256 _pid, address _user) public view returns(uint256 pending) {
    PoolInfo memory pool = poolInfo[_pid];
    UserInfo storage user = userInfo[_pid][_user];
    uint256 accSushiPerShare = pool.accSushiPerShare;
    uint256 lpSupply = IMasterChefV2(MASTERCHEF_V2).lpToken(_pid).balanceOf(MASTERCHEF_V2);
    if (block.timestamp > pool.lastRewardTime && lpSupply != 0) {
        uint256 time = block.timestamp.sub(pool.lastRewardTime);
        uint256 sushiReward = time.mul(rewardPerSecond);
        accSushiPerShare = accSushiPerShare.add(sushiReward.mul(ACC_TOKEN_PRECISION) / lpSupply);
    }
    pending = (user.amount.mul(accSushiPerShare) / ACC_TOKEN_PRECISION).sub(user.rewardDebt);
}

function updatePool(uint256 pid) public returns(PoolInfo memory pool) {
    pool = poolInfo[pid];
    if (block.timestamp > pool.lastRewardTime) {
        uint256 lpSupply = IMasterChefV2(MASTERCHEF_V2).lpToken(pid).balanceOf(MASTERCHEF_V2);
        if (lpSupply > 0) {
            uint256 time = block.timestamp.sub(pool.lastRewardTime);
            uint256 sushiReward = time.mul(rewardPerSecond);
            pool.accSushiPerShare = pool.accSushiPerShare.add((sushiReward.mul(ACC_TOKEN_PRECISION) / lpSupply).to128());
        }
        pool.lastRewardTime = block.timestamp.to64();
        poolInfo[pid] = pool;
        emit LogUpdatePool(pid, pool.lastRewardTime, lpSupply, pool.accSushiPerShare);
    }
}

function onSushiReward(uint256 pid, address _user, address to, uint256, uint256 lpToken) onlyMCV2 override external {
    require(IMasterChefV2(MASTERCHEF_V2).lpToken(pid) == masterLpToken);
    PoolInfo memory pool = updatePool(pid);
    UserInfo storage user = userInfo[pid][_user];
    uint256 pending;
    if (user.amount > 0) {
        pending =
            (user.amount.mul(pool.accSushiPerShare) / ACC_TOKEN_PRECISION).sub(
                user.rewardDebt
            );
        rewardToken.safeTransfer(to, pending);
    }
    user.amount = lpToken;
    user.rewardDebt = lpToken.mul(pool.accSushiPerShare) / ACC_TOKEN_PRECISION;
    emit LogOnReward(_user, pid, pending, to);
}

function TrivialToken(
    string _name, string _symbol,
    uint256 _icoEndTime, uint256 _auctionDuration,
    address _artist, address _trivial,
    uint256 _tokensForArtist,
    uint256 _tokensForTrivial,
    uint256 _tokensForIco
) {
    require(now < _icoEndTime);
    require(
        TOTAL_SUPPLY == SafeMath.add(
            _tokensForArtist,
            SafeMath.add(_tokensForTrivial, _tokensForIco)
        )
    );
    require(MIN_BID_PERCENTAGE < 100);
    require(TOKENS_PERCENTAGE_FOR_KEY_HOLDER < 100);
    name = _name;
    symbol = _symbol;
    decimals = DECIMALS;
    icoEndTime = _icoEndTime;
    auctionDuration = _auctionDuration;
    artist = _artist;
    trivial = _trivial;
    tokensForArtist = _tokensForArtist;
    tokensForTrivial = _tokensForTrivial;
    tokensForIco = _tokensForIco;
    currentState = State.Created;
}

function killContract()
onlyTrivial() {
    require(
        (
            currentState == State.AuctionFinished &&
            now > SafeMath.add(auctionEndTime, CLEANUP_DELAY) 
        ) ||
        currentState == State.IcoCancelled 
    );
    selfdestruct(trivial);
}

function finishIco()
onlyInState(State.IcoStarted)
onlyAfter(icoEndTime) {
    if (amountRaised == 0) {
        currentState = State.IcoCancelled;
        return;
    }
    require(nextContributorIndexToBeGivenTokens >= contributors.length);
    balances[artist] = SafeMath.add(balances[artist], tokensForArtist);
    balances[trivial] = SafeMath.add(balances[trivial], tokensForTrivial);
    uint256 leftovers = SafeMath.sub(tokensForIco, tokensDistributedToContributors);
    balances[artist] = SafeMath.add(balances[artist], leftovers);
    if (!artist.send(this.balance)) {
        asyncSend(artist, this.balance);
    }
    currentState = State.IcoFinished;
    IcoFinished(amountRaised);
}

function bidInAuction() payable
onlyInState(State.AuctionStarted)
onlyBefore(auctionEndTime) {
    require(msg.value >= MIN_ETH_AMOUNT);
    uint256 bid = calculateUserBid();
    if (highestBid >= MIN_ETH_AMOUNT) {
        uint256 minimalOverBid = SafeMath.add(highestBid, SafeMath.div(
            SafeMath.mul(highestBid, MIN_BID_PERCENTAGE), 100
        ));
        require(bid >= minimalOverBid);
        uint256 amountToReturn = SafeMath.sub(SafeMath.sub(
            this.balance, msg.value
        ), totalPayments);
        if (!highestBidder.send(amountToReturn)) {
            asyncSend(highestBidder, amountToReturn);
        }
    }
    highestBidder = msg.sender;
    highestBid = bid;
    HighestBidChanged(highestBidder, highestBid);
}

function buyLevel(uint256 _level)
public
payable
userRegistered()
validLevel(_level)
validLevelAmount(_level) {
    for (uint256 l = _level - 1; l > 0; l--) {
        require(
            getUserLevelExpiresAt(msg.sender, l) >= now,
            "Buy previous level first"
        );
    }
    if (getUserLevelExpiresAt(msg.sender, _level) == 0) {
        users[msg.sender].levelExpiresAt[_level] =
            now +
            getLevelExpireTime(_level);
    } else {
        users[msg.sender].levelExpiresAt[_level] += getLevelExpireTime(
            _level
        );
    }
    transferLevelPayment(_level, msg.sender);
}

function getUserLevel(address _user) public view returns(uint256) {
    if (getUserLevelExpiresAt(_user, 1) < now) {
        return (0);
    } else if (getUserLevelExpiresAt(_user, 2) < now) {
        return (1);
    } else if (getUserLevelExpiresAt(_user, 3) < now) {
        return (2);
    } else if (getUserLevelExpiresAt(_user, 4) < now) {
        return (3);
    } else if (getUserLevelExpiresAt(_user, 5) < now) {
        return (4);
    } else if (getUserLevelExpiresAt(_user, 6) < now) {
        return (5);
    } else if (getUserLevelExpiresAt(_user, 7) < now) {
        return (6);
    } else if (getUserLevelExpiresAt(_user, 8) < now) {
        return (7);
    } else if (getUserLevelExpiresAt(_user, 9) < now) {
        return (8);
    } else if (getUserLevelExpiresAt(_user, 10) < now) {
        return (9);
    }
}

function transferLevelPayment(uint256 _level, address _user) internal {
    address referrer = getUserUpline(_user, _level);
    address sender = msg.sender;
    if (referrer == address(0)) {
        referrer = creator;
    }
    uint256 uplines = 3;
    uint256 eth = msg.value;
    uint256 ethToReferrer = (eth - (directPrice[_level] * 2)) / uplines;
    for (uint256 i = 1; i <= uplines; i++) {
        referrer = getUserUpline(_user, i);
        if (
            referrer != address(0) &&
            (users[_user].levelExpiresAt[_level] == 0 ||
                getUserLevelExpiresAt(referrer, _level) < now)
        ) {
            uplines++;
            continue;
        }
        if (referrer == address(0)) {
            referrer = creator;
        }
        eth = eth - ethToReferrer;
        (bool success, ) = address(uint256(referrer)).call {
            value: ethToReferrer
        }("");
        require(success, "Transfer failed.");
        emit GetLevelProfitEvent(
            referrer,
            sender,
            users[sender].id,
            ethToReferrer
        );
    }
    address directRefer = userAddresses[users[msg.sender].referrerID];
    eth = eth - directPrice[_level];
    (bool success2, ) = address(uint256(directRefer)).call {
        value: directPrice[_level]
    }("");
    require(success2, "Transfer failed.");
    emit GetLevelProfitEvent(
        directRefer,
        sender,
        users[sender].id,
        directPrice[_level]
    );
    (bool success3, ) = address(uint256(creator)).call {
        value: eth
    }("");
    require(success3, "Transfer failed.");
}

