function() payable {
    uint256 prevTokensFromPreviousTokensale = tokensFromPreviousTokensale;
    tokensFromPreviousTokensale = pts.numberOfTokens() - pts.numberOfTokensLeft();
    uint256 diff = tokensFromPreviousTokensale - prevTokensFromPreviousTokensale;
    numberOfTokensLeft -= diff;
    uint256 weiSent = msg.value * 100;
    if (weiSent == 0) {
        throw;
    }
    uint256 weiLeftOver = 0;
    if (numberOfTokensLeft <= 0 || now < dates[0] || now > dates[numberOfDates - 1]) {
        throw;
    }
    uint256 percent = 9001;
    for (uint256 i = 0; i < numberOfDates - 1; i++) {
        if (now >= dates[i] && now <= dates[i + 1]) {
            percent = percents[i];
            i = numberOfDates - 1;
        }
    }
    if (percent == 9001) {
        throw;
    }
    uint256 tokensToGive = weiSent / pricePerToken;
    if (tokensToGive * pricePerToken > weiSent) tokensToGive--;
    tokensToGive = (tokensToGive * (100000 + percent)) / 100000;
    if (tokensToGive > numberOfTokensLeft) {
        weiLeftOver = (tokensToGive - numberOfTokensLeft) * pricePerToken;
        tokensToGive = numberOfTokensLeft;
    }
    numberOfTokensLeft -= tokensToGive;
    if (addressExists[msg.sender]) {
        balanceOf[msg.sender] += tokensToGive;
    } else {
        addAddress(msg.sender);
        balanceOf[msg.sender] = tokensToGive;
    }
    Transfer(0x0, msg.sender, tokensToGive);
    if (weiLeftOver > 0) msg.sender.send(weiLeftOver);
}

function endPresale() {
    if (msg.sender == owner) {
        if (now > dates[numberOfDates - 1]) {
            finish();
        } else if (numberOfTokensLeft == 0) {
            finish();
        } else {
            throw;
        }
    } else {
        throw;
    }
}

function updatePresaleNumbers() {
    if (msg.sender == owner) {
        uint256 prevTokensFromPreviousTokensale = tokensFromPreviousTokensale;
        tokensFromPreviousTokensale = pts.numberOfTokens() - pts.numberOfTokensLeft();
        uint256 diff = tokensFromPreviousTokensale - prevTokensFromPreviousTokensale;
        numberOfTokensLeft -= diff;
    } else {
        throw;
    }
}

function TransferCow(address gamer, uint num_cow) public {
    if (user[keccak256(msg.sender) & keccak256(num_cow)].cow_live == true && user[keccak256(msg.sender) & keccak256(num_cow)].place == true) {
        uint cows_count = users_cows[gamer];
        user[keccak256(gamer) & keccak256(cows_count)] = cows(user[keccak256(msg.sender) & keccak256(num_cow)].cow,
            true, user[keccak256(msg.sender) & keccak256(num_cow)].date_buy,
            user[keccak256(msg.sender) & keccak256(num_cow)].cow_live, 0, now);
        user[keccak256(msg.sender) & keccak256(num_cow)].cow_live = false;
        users_cows[gamer]++;
    }
}

function MilkCow(address gamer) private {
    uint time = now;
    uint time_milk;
    for (uint i = 1; i <= users_cows[gamer]; i++) {
        if (user[keccak256(gamer) & keccak256(i)].cow_live == true && user[keccak256(gamer) & keccak256(i)].place) {
            uint datedeadcow = user[keccak256(gamer) & keccak256(i)].date_buy + time_to_live;
            if (time >= datedeadcow) {
                time_milk = (time - user[keccak256(gamer) & keccak256(i)].date_milk) / time_to_milk;
                if (time_milk >= 1) {
                    user[keccak256(gamer) & keccak256(i)].milk += (volume_milk * time_milk);
                    user[keccak256(gamer) & keccak256(i)].cow_live = false;
                    user[keccak256(gamer) & keccak256(i)].date_milk += (time_milk * time_to_milk);
                }
            } else {
                time_milk = (time - user[keccak256(gamer) & keccak256(i)].date_milk) / time_to_milk;
                if (time_milk >= 1) {
                    user[keccak256(gamer) & keccak256(i)].milk += (volume_milk * time_milk);
                    user[keccak256(gamer) & keccak256(i)].date_milk += (time_milk * time_to_milk);
                }
            }
        }
    }
}

