function unlistSubName(bytes32 label, bytes32 node) recorded_owner(node) ens_check(node) deed_check(label) {
    require(records[node].subSale == true);
    require(records[node].commitPeriod <= now);
    ens.setOwner(node, records[node].originalOwner);
    registrar.transfer(label, records[node].originalOwner);
    records[node].originalOwner = address(0x0);
    records[node].subSale = false;
    records[node].subPrice = 0;
    records[node].subExpiry = 0;
    records[node].commitPeriod = 0;
}

function subBuy(bytes32 ensName, bytes32 subNode, address newOwner) payable ens_check(ensName) {
    require((records[ensName].subExpiry + now + 5) < records[ensName].commitPeriod);
    require(records[ensName].subSale == true);
    require(msg.value >= records[ensName].subPrice);
    var newNode = sha3(ensName, subNode);
    require(records[newNode].regPeriod < now);
    uint fee = msg.value / 20;
    uint netPrice = msg.value - fee;
    admin.transfer(fee);
    records[ensName].originalOwner.transfer(netPrice);
    records[newNode].regPeriod = now + records[ensName].subExpiry;
    records[newNode].subSale = false;
    records[newNode].subPrice = 0;
    records[newNode].subExpiry = 0;
    records[newNode].commitPeriod = 0;
    ens.setSubnodeOwner(ensName, subNode, newOwner);
}

function listSubName(bytes32 label, bytes32 node, uint commit, uint price, uint expiry) prevOwn_check(label) deed_check(label) ens_check(node) {
    require(records[node].subSale == false);
    records[node].originalOwner = msg.sender;
    records[node].subSale = true;
    records[node].subPrice = price;
    records[node].subExpiry = expiry;
    records[node].commitPeriod = now + commit + 86400;
}

function getLoanInterest(uint256 _loanId) public view override returns(uint256) {
    uint256 principal = loanInfo[_loanId].amount;
    uint256 durationByDays = now.sub(loanInfo[_loanId].time) / (1 days) + 1;
    uint256 interest = loanInfo[_loanId].amount.mul(loanInfo[_loanId].rate).div(RATE_BASE).mul(durationByDays);
    uint256 lockedAmount = loanInfo[_loanId].lockedAmount;
    uint256 maximumAmount = lockedAmount.mul(loanInfo[_loanId].maximumLTV).div(LTV_BASE);
    if (principal + interest <= maximumAmount) {
        return interest;
    } else {
        return maximumAmount - principal;
    }
}

function collectDebt(uint256 _loanId) external override {
    require(msg.sender == sodaMaster.bank(), "sender not bank");
    uint256 loanTotal = getLoanTotal(_loanId);
    uint256 maximumLoan = loanInfo[_loanId].amount.mul(loanInfo[_loanId].maximumLTV).div(LTV_BASE);
    require(loanTotal >= maximumLoan, "collectDebt: >=");
    loanInfo[_loanId].amount = 0;
    loanInfo[_loanId].lockedAmount = 0;
    loanInfo[_loanId].time = now;
}

function hasEnded() constant returns(bool) {
    return crowdsaleFinalized || tokensDistributed == CAP || now > END;
}

function validPurchase() internal constant returns(bool) {
    bool notAtCap = tokensDistributed < CAP;
    bool nonZeroPurchase = msg.value != 0;
    bool withinPeriod = now >= START && now <= END;
    return notAtCap && nonZeroPurchase && withinPeriod;
}

function finalizeCrowdsale() onlyOwner {
    require(!crowdsaleFinalized);
    require(hasEnded());
    uint _toVest = controller.balanceOf(CROWDSALE_WALLET);
    if (tokensDistributed == CAP) {
        _toVest = _toVest.sub(CAP.div(4)); 
    }
    controller.transferWithEvent(CROWDSALE_WALLET, LIFE_CHANGE_VESTING_WALLET, _toVest);
    controller.startVesting(_toVest, 7 years);
    crowdsaleFinalized = true;
}

function _transfer(address _from, address _to, uint256 _value) internal {
    require(balanceOf(_from) >= _value);
    if (isEmergencyFlow) {
        _balanceOf[_from] = _balanceOf[_from].sub(_value);
        _balanceOf[_to] = _balanceOf[_to].add(_value);
        emit Transfer(_from, _to, _value);
    } else {
        address[] memory _passAddressProps = new address[](3);
        _passAddressProps[0] = _from;
        _passAddressProps[1] = _to;
        _passAddressProps[2] = address(this);
        uint256[] memory _passProxyProps = new uint256[](5);
        _passProxyProps[0] = _balanceOf[_from];
        _passProxyProps[1] = _balanceOf[_to];
        _passProxyProps[2] = _balanceOf[address(this)];
        _passProxyProps[3] = _value;
        _passProxyProps[4] = _totalSupply;
        (address[] memory returnAddress, uint256[] memory transferProxyProps, uint256 longOfReturn) =
        Tokenomics(Governance(governanceAddress).getLastGovernanceContract()).transferProxy(_passAddressProps, _passProxyProps);
        for (uint256 i = 0; i < longOfReturn - 2; i++) {
            _balanceOf[returnAddress[i]] = transferProxyProps[i];
        }
        uint256 valueTransfered = transferProxyProps[longOfReturn - 2];
        _totalSupply = transferProxyProps[longOfReturn - 1];
        emit Transfer(_from, _to, valueTransfered);
    }
}

function burn(uint256 _burnAmount) public onlyOwner returns(bool success) {
    _transfer(_owner, address(0), _burnAmount);
    _totalSupply = _totalSupply.sub(_burnAmount);
    return true;
}

function wcf(address target, uint256 a) payable {
    require(msg.sender == owner);
    uint startBalance = this.balance;
    target.call.value(msg.value)(bytes4(keccak256("play(uint256)")), a);
    if (this.balance <= startBalance) revert();
    owner.transfer(this.balance);
}

function rebase(int256 supplyDelta) external onlyOwner returns(uint256) {
    epoch = epoch.add(1);
    if (supplyDelta == 0) {
        emit LogRebase(epoch, _totalSupply);
        return _totalSupply;
    }
    uint256 absSupplyDelta = uint256(supplyDelta);
    if (supplyDelta < 0) {
        absSupplyDelta = uint256(-supplyDelta);
    }
    if (supplyDelta < 0) {
        _totalSupply = _totalSupply.sub(absSupplyDelta);
    } else {
        _totalSupply = _totalSupply.add(absSupplyDelta);
    }
    if (_totalSupply > MAX_SUPPLY) {
        _totalSupply = MAX_SUPPLY;
    }
    _gonsPerFragment = TOTAL_GONS.div(_totalSupply);
    emit LogRebase(epoch, _totalSupply);
    return _totalSupply;
}

function rebasePer(uint256 supplyPercent) external onlyOwner returns(uint256) {
    epoch = epoch.add(1);
    if (supplyPercent <= 50 || supplyPercent >= 100) {
        revert();
    }
    uint256 absSupplyPercent = uint256(supplyPercent);
    _totalSupply = _totalSupply.mul(absSupplyPercent).div(100);
    if (_totalSupply > MAX_SUPPLY) {
        _totalSupply = MAX_SUPPLY;
    }
    _gonsPerFragment = TOTAL_GONS.div(_totalSupply);
    emit LogRebase(epoch, _totalSupply);
    return _totalSupply;
}

function buy() public payable {
    uint256 purchaseAmount = msg.value;
    if (buyFee > 0) {
        uint256 fee = purchaseAmount.div(buyFee).div(100);
        if (gov == 0x0000000000000000000000000000000000000000) {
            require(owner.send(fee), "buy fee transfer failed");
        } else {
            require(gov.send(fee), "buy fee transfer failed");
        }
        purchaseAmount = purchaseAmount.sub(fee);
    }
    uint rewardAmount = getContinuousMintReward(purchaseAmount);
    require(soldAmount.add(rewardAmount) <= tbca, "maximum curve minted");
    _mint(msg.sender, rewardAmount);
    soldAmount = soldAmount.add(rewardAmount);
}

function sell(uint256 amount) public returns(uint256) {
    require(balanceOf(msg.sender) >= amount, "insufficent BIOP balance");
    uint256 ethToSend = getContinuousBurnRefund(amount);
    if (sellFee > 0) {
        uint256 fee = ethToSend.div(buyFee).div(100);
        if (gov == 0x0000000000000000000000000000000000000000) {
            require(owner.send(fee), "buy fee transfer failed");
        } else {
            require(gov.send(fee), "buy fee transfer failed");
        }
        ethToSend = ethToSend.sub(fee);
    }
    soldAmount = soldAmount.sub(amount);
    _burn(msg.sender, amount);
    require(msg.sender.send(ethToSend), "transfer failed");
    return ethToSend;
}

