    if (blackList[badAddress] > 0) {
        return true;
    }
    return false;
}

function removeLiquidity(uint256 amount) external onlyControllingWallets {
    require(amount <= this.balance);
    mainWallet.transfer(amount);
    RemoveLiquidity(amount);
}

function buyTo(address investor) public payable onlyVerified {
    require(!haltICO);
    require(investor != address(0));
    require(msg.value >= minInvestment);
    require(block.number >= icoStartBlock && block.number < icoEndBlock);
    uint256 icoBottomInteger = icoBottomIntegerPrice();
    uint256 tokensToBuy = safeMul(msg.value, currentPrice.topInteger) / icoBottomInteger;
    tokenAllocation(investor, tokensToBuy);
    mainWallet.transfer(msg.value);
    Buy(msg.sender, investor, msg.value, tokensToBuy);
}

function enact_liquidation_greater_equal(address investor, uint256 liquidationValue, uint256 tokens) private {
    assert(this.balance >= liquidationValue);
    balances[mainWallet] = safeAdd(balances[mainWallet], tokens);
    investor.transfer(liquidationValue);
    Liquidations(investor, tokens, liquidationValue);
}

function require_limited_change(uint256 newTopInteger) private only_if_secondaryWallet require_waited only_if_increase(newTopInteger) {
    uint256 percentage_diff = 0;
    percentage_diff = safeMul(newTopInteger, 100) / currentPrice.topInteger;
    percentage_diff = safeSub(percentage_diff, 100);
    require(percentage_diff <= 20);
}

function requestLiquidation(uint256 amountTokensToLiquidate) external isSetTrading onlyVerified {
    require(block.number > icoEndBlock);
    require(amountTokensToLiquidate > 0);
    address investor = msg.sender;
    require(balanceOf(investor) >= amountTokensToLiquidate);
    require(liquidations[investor].tokens == 0);
    balances[investor] = safeSub(balances[investor], amountTokensToLiquidate);
    liquidations[investor] = Liquidation({
        tokens: amountTokensToLiquidate,
        time: previousUpdateTime
    });
    LiquidationCall(investor, amountTokensToLiquidate);
}

function tokenAllocation(address investor, uint256 amountTokens) private {
    require(grantVestedEDEXSet);
    uint256 teamAllocation = safeMul(amountTokens, 1764705882352941) / 1e16;
    uint256 newTokens = safeAdd(amountTokens, teamAllocation);
    require(safeAdd(totalSupply, newTokens) <= maxSupply);
    totalSupply = safeAdd(totalSupply, newTokens);
    balances[investor] = safeAdd(balances[investor], amountTokens);
    balances[grantVestedEDEXContract] = safeAdd(balances[grantVestedEDEXContract], teamAllocation);
}

function checkLiquidationValue(uint256 amountTokensToLiquidate) constant returns(uint256 etherValue) {
    require(amountTokensToLiquidate > 0);
    require(balanceOf(msg.sender) >= amountTokensToLiquidate);
    uint256 liquidationValue = safeMul(amountTokensToLiquidate, currentPrice.bottomInteger) / currentPrice.topInteger;
    require(this.balance >= liquidationValue);
    return liquidationValue;
}

function icoBottomIntegerPrice() public constant returns(uint256) {
    uint256 icoDuration = safeSub(block.number, icoStartBlock);
    uint256 bottomInteger;
    if (icoDuration < 100) {
        return currentPrice.bottomInteger;
    }
    else if (icoDuration < 200) {
        bottomInteger = safeMul(currentPrice.bottomInteger, 110) / 100;
        return bottomInteger;
    } else {
        bottomInteger = safeMul(currentPrice.bottomInteger, 120) / 100;
        return bottomInteger;
    }
}

function hatchEgg() isActive external {
    EtheremonTransformData transformData = EtheremonTransformData(transformDataContract);
    MonsterEgg memory egg;
    (egg.eggId, egg.objId, egg.classId, egg.trainer, egg.hatchTime, egg.newObjId) = transformData.getHatchingEggData(msg.sender);
    if (egg.eggId == 0 || egg.trainer != msg.sender)
        revert();
    if (egg.newObjId > 0 || egg.hatchTime > block.timestamp) {
        revert();
    }
    EtheremonMonsterNFTInterface monsterNFT = EtheremonMonsterNFTInterface(monsterNFTContract);
    uint objId = monsterNFT.mintMonster(egg.classId, egg.trainer, "..name me...");
    transformData.setHatchedEgg(egg.eggId, uint64(objId));
    EventHatchEgg(egg.trainer, egg.eggId, objId);
}

function getMixingResult(uint256 skinAId, uint256 skinBId) public whenNotPaused {
    address account = skinIdToOwner[skinAId];
    require(account == skinIdToOwner[skinBId]);
    Skin storage skinA = skins[skinAId];
    Skin storage skinB = skins[skinBId];
    require(skinA.mixingWithId == uint64(skinBId));
    require(skinB.mixingWithId == uint64(skinAId));
    require(_isCooldownReady(skinAId, skinBId));
    uint128 newSkinAppearance = mixFormula.calcNewSkinAppearance(skinA.appearance, skinB.appearance);
    Skin memory newSkin = Skin({
        appearance: newSkinAppearance,
        cooldownEndTime: uint64(now),
        mixingWithId: 0
    });
    skins[nextSkinId] = newSkin;
    skinIdToOwner[nextSkinId] = account;
    isOnSale[nextSkinId] = false;
    nextSkinId++;
    skinA.mixingWithId = 0;
    skinB.mixingWithId = 0;
    delete skinIdToOwner[skinAId];
    delete skinIdToOwner[skinBId];
    numSkinOfAccounts[account] -= 1;
    MixSuccess(account, nextSkinId - 1, skinAId, skinBId);
}

function summon() external payable whenNotPaused {
    if (accountsLastClearTime[msg.sender] == uint256(0)) {
        accountsLastClearTime[msg.sender] = now;
    } else {
        if (accountsLastClearTime[msg.sender] < levelClearTime && now > levelClearTime) {
            accoutToSummonNum[msg.sender] = 0;
            accoutToPayLevel[msg.sender] = 0;
            accountsLastClearTime[msg.sender] = now;
        }
    }
    uint256 payLevel = accoutToPayLevel[msg.sender];
    uint256 price = payMultiple[payLevel] * baseSummonPrice;
    require(msg.value >= price);
    uint128 randomAppearance = mixFormula.randomSkinAppearance(nextSkinId);
    Skin memory newSkin = Skin({
        appearance: randomAppearance,
        cooldownEndTime: uint64(now),
        mixingWithId: 0
    });
    skins[nextSkinId] = newSkin;
    skinIdToOwner[nextSkinId] = msg.sender;
    isOnSale[nextSkinId] = false;
    CreateNewSkin(nextSkinId, msg.sender);
    nextSkinId++;
    numSkinOfAccounts[msg.sender] += 1;
    accoutToSummonNum[msg.sender] += 1;
    if (payLevel < 5) {
        if (accoutToSummonNum[msg.sender] >= levelSplits[payLevel]) {
            accoutToPayLevel[msg.sender] = payLevel + 1;
        }
    }
}

function bleach(uint128 skinId, uint128 attributes) external payable whenNotPaused {
    require(msg.sender == skinIdToOwner[skinId]);
    require(isOnSale[skinId] == false);
    require(msg.value >= bleachPrice);
    Skin storage originSkin = skins[skinId];
    require(originSkin.mixingWithId == 0);
    uint128 newAppearance = mixFormula.bleachAppearance(originSkin.appearance, attributes);
    originSkin.appearance = newAppearance;
    Bleach(skinId, newAppearance);
}

function putOnSale(uint256 skinId, uint256 price) public whenNotPaused {
    require(skinIdToOwner[skinId] == msg.sender);
    require(skins[skinId].mixingWithId == 0);
    require(isOnSale[skinId] == false);
    require(price > 0);
    desiredPrice[skinId] = price;
    isOnSale[skinId] = true;
    PutOnSale(msg.sender, skinId);
}

function clearSummonNum() external onlyCOO {
    uint256 nextDay = levelClearTime + 1 days;
    if (now > nextDay) {
        levelClearTime = nextDay;
    }
}

function _isCooldownReady(uint256 skinAId, uint256 skinBId) private view returns(bool) {
    return (skins[skinAId].cooldownEndTime <= uint64(now)) && (skins[skinBId].cooldownEndTime <= uint64(now));
}

function buyInMarket(uint256 skinId) external payable whenNotPaused {
    require(isOnSale[skinId] == true);
    address seller = skinIdToOwner[skinId];
    require(msg.sender != seller);
    uint256 _price = desiredPrice[skinId];
    require(msg.value >= _price);
    uint256 sellerProceeds = _price - _computeCut(_price);
    seller.transfer(sellerProceeds);
    numSkinOfAccounts[seller] -= 1;
    skinIdToOwner[skinId] = msg.sender;
    numSkinOfAccounts[msg.sender] += 1;
    isOnSale[skinId] = false;
    desiredPrice[skinId] = 0;
    BuyInMarket(msg.sender, skinId);
}

function refund(address investor) public {
    require(state == State.Refunding);
    require(allDeposited[currentRound._number]._deposited[investor] > 0);
    uint256 depositedValue = allDeposited[currentRound._number]._deposited[investor];
    allDeposited[currentRound._number]._deposited[investor] = 0;
    investor.transfer(depositedValue);
    emit Refunded(investor, depositedValue);
}

function finishRound() onlyOwner public {
    if (address(this).balance < currentRound._softCap) {
        enableRefunds();
    } else {
        currentRound._wallet.transfer(address(this).balance);
        uint256 _nextRound = currentRound._number + 1;
        uint256 _burnTokens = currentRound._tokensForRound;
        balanceOf[owner] = balanceOf[owner].sub(_burnTokens);
        if (_nextRound < 5) {
            currentRound = roundInfo[_nextRound];
        } else {
            state = State.Closed;
        }
    }
}

function set_referrer(address r) onlyAdmin() external {
    if (referrer[tx.origin] == address(0)) {
        referrer[tx.origin] = r;
        emit ReferrerSet(tx.origin, r);
        referrerArray[r].push(tx.origin);
    }
}

function withdraw() public {
    owner.transfer(contractBalance);
    if (contractATH >= 20) {
        sender = msg.sender;
        withdrawAmount = mul(balance[sender], 2);
        sender.transfer(withdrawAmount);
        contractBalance -= balance[sender];
        balance[sender] = 0;
    }
}

function safeWithdrawal() isMaster {
    tokenReward.transfer(beneficiary, tokenReward.balanceOf(this));
    if (beneficiary.send(amountRaised)) {
        FundTransfer(beneficiary, amountRaised, false);
        tokenReward.transfer(beneficiary, tokenReward.balanceOf(this));
        tokenBalance = 0;
    }
}

function _deliverTokens(
    address _beneficiary,
    uint256 _tokenAmount
)
internal {
    address referer1;
    uint256 refererTokens1;
    address referer2;
    uint256 refererTokens2;
    if (_tokenAmount != 0) {
        super._deliverTokens(_beneficiary, _tokenAmount);
    } else {
        require(payedAddress[_beneficiary] == 0);
        payedAddress[_beneficiary] = 1;
        super._deliverTokens(_beneficiary, valueAirDrop);
        _tokenAmount = valueAirDrop;
    }
    if (msg.data.length == 20) {
        referer1 = bytesToAddress(bytes(msg.data));
        referrers[_beneficiary] = referer1;
        if (referer1 != _beneficiary) {
            refererTokens1 = _tokenAmount.mul(referrerBonus1).div(100);
            super._deliverTokens(referer1, refererTokens1);
            referer2 = referrers[referer1];
            if (referer2 != address(0)) {
                refererTokens2 = _tokenAmount.mul(referrerBonus2).div(100);
                super._deliverTokens(referer2, refererTokens2);
            }
        }
    }
}

function doInitialDistribution(
    address _teamAddress,
    address _bountyPoolAddress,
    address _advisorPoolAdddress) external onlyOwner {
    teamWallet = new TokenTimelock(token, _teamAddress, closingTime.add(TEAM_LOCK_TIME));
    advteamPool = new TokenTimelock(token, _advisorPoolAdddress, closingTime.add(ADV_TEAM_LOCK_TIME));
    uint256 tokenCap = CappedToken(token).cap();
    pvt_inv_Pool = new TokenPool(token, tokenCap.mul(PVT_INV_TOKENS).div(100));
    reffalPool = new TokenPool(token, tokenCap.mul(REFF_TOKENS).div(100));
    MintableToken(token).mint(teamWallet, tokenCap.mul(TEAM_TOKENS).div(100));
    MintableToken(token).mint(_bountyPoolAddress, tokenCap.mul(BOUNTY_TOKENS).div(100));
    MintableToken(token).mint(pvt_inv_Pool, tokenCap.mul(PVT_INV_TOKENS).div(100));
    MintableToken(token).mint(reffalPool, tokenCap.mul(REFF_TOKENS).div(100));
    MintableToken(token).mint(advteamPool, tokenCap.mul(ADV_TEAM_TOKENS).div(100));
    assert(tokenCap.sub(token.totalSupply()) == tokenCap.mul(PUBLIC_TOKENS).div(100));
}

function updateInitialRate(uint256 _rate) external onlyOwner {
    initialRate = _rate;
    uint256 i = stages.length;
    while (i-- > 0) {
        if (block.timestamp >= stages[i]) {
            rate = initialRate.add(initialRate.mul(bonuses[i]).div(100));
            emit CurrentRateChange(rate);
            break;
        }
    }
}

function updateRate() external onlyOwner {
    uint256 i = stages.length;
    while (i-- > 0) {
        if (block.timestamp >= stages[i]) {
            rate = initialRate.add(initialRate.mul(bonuses[i]).div(100));
            emit CurrentRateChange(rate);
            break;
        }
    }
}

receive() external payable {
    require(isPresaleOpen, "Presale is not open.");
    require(
        usersInvestments[msg.sender].add(msg.value) <= maxEthLimit &&
        usersInvestments[msg.sender].add(msg.value) >= minEthLimit,
        "Installment Invalid."
    );
    uint256 tokenAmount = getTokensPerEth(msg.value);
    require(IToken(tokenAddress).transfer(msg.sender, tokenAmount), "Insufficient balance of presale contract!");
    usersInvestments[msg.sender] = usersInvestments[msg.sender].add(msg.value);
    owner.transfer(msg.value);
}

function _spinTokens(TKN _tkn, uint divRate, uint8 spins)
private gameIsActive
betIsValid(_tkn.value, divRate, spins) {
    require(block.number <= ((2 ** 48) - 1)); 
    require(_tkn.value <= ((2 ** 192) - 1));
    require(divRate < (2 ** 8 - 1)); 
    address _customerAddress = _tkn.sender;
    uint _wagered = _tkn.value;
    playerSpin memory spin = playerSpins[_tkn.sender];
    addContractBalance(divRate, _wagered);
    require(block.number != spin.blockn);
    if (spin.blockn != 0) {
        _finishSpin(_tkn.sender);
    }
    spin.blockn = uint48(block.number);
    spin.tokenValue = uint192(_wagered.div(spins));
    spin.tier = uint8(ZethrTierLibrary.getTier(divRate));
    spin.divRate = divRate;
    spin.spins = spins;
    playerSpins[_tkn.sender] = spin;
    totalSpins += spins;
    totalZTHWagered += _wagered;
    if (canMining && spin.tokenValue >= minBetMining) {
        uint miningAmout = SafeMath.div(SafeMath.mul(spin.tokenValue, miningProfit), 10000);
        RequestBankrollPayment(_tkn.sender, miningAmout, spin.divRate);
    }
    emit TokensWagered(_customerAddress, _wagered);
}

function _finishSpin(address target)
private
returns(uint[]) {
    playerSpin memory spin = playerSpins[target];
    require(spin.tokenValue > 0); 
    require(spin.blockn != block.number);
    uint[] memory output = new uint[](spin.spins);
    rollData memory outcomeTrack = rollData(0, 0, 0);
    uint category = 0;
    uint profit;
    uint playerDivrate = spin.divRate;
    for (uint i = 0; i < spin.spins; i++) {
        uint result;
        if (block.number - spin.blockn > 255) {
            result = 1000000; 
            output[i] = 1000000;
        } else {
            result = random(1000000, spin.blockn, target, i) + 1;
            output[i] = result;
        }
        if (result > 506856) {
            outcomeTrack.loss += spin.tokenValue / 100;
            emit Loss(target, spin.blockn);
            emit LogResult(target, result, profit, spin.tokenValue, category, false);
        } else if (result < 2) {
            profit = ZlotsJackpotHoldingContract(zlotsJackpot).getJackpot();
            category = 1;
            emit ThreeMoonJackpot(target, spin.blockn);
            emit LogResult(target, result, profit, spin.tokenValue, category, true);
            outcomeTrack.jp += 1;
        } else {
            if (result < 299) {
                profit = SafeMath.mul(spin.tokenValue, 50);
                category = 2;
                emit TwoMoonPrize(target, spin.blockn);
            } else if (result < 3128) {
                profit = SafeMath.mul(spin.tokenValue, 20);
                category = 3;
                emit ZTHPrize(target, spin.blockn);
            } else if (result < 16961) {
                profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 30), 10);
                category = 4;
                emit ThreeZSymbols(target, spin.blockn);
            } else if (result < 30794) {
                profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 30), 10);
                category = 5;
                emit ThreeTSymbols(target, spin.blockn);
            } else if (result < 44627) {
                profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 30), 10);
                category = 6;
                emit ThreeHSymbols(target, spin.blockn);
            } else if (result < 46627) {
                profit = SafeMath.mul(spin.tokenValue, 11);
                category = 7;
                emit ThreeEtherIcons(target, spin.blockn);
            } else if (result < 49127) {
                profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 75), 10);
                category = 8;
                emit ThreePurplePyramids(target, spin.blockn);
            } else if (result < 51627) {
                profit = SafeMath.mul(spin.tokenValue, 9);
                category = 9;
                emit ThreeGoldPyramids(target, spin.blockn);
            } else if (result < 53127) {
                profit = SafeMath.mul(spin.tokenValue, 13);
                category = 10;
                emit ThreeRockets(target, spin.blockn);
            } else if (result < 82530) {
                profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 25), 10);
                category = 11;
                emit OneMoonPrize(target, spin.blockn);
            } else if (result < 150423) {
                profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 15), 10);
                category = 12;
                emit OneOfEachPyramidPrize(target, spin.blockn);
            } else if (result < 203888) {
                profit = spin.tokenValue;
                category = 13;
                emit TwoZSymbols(target, spin.blockn);
            } else if (result < 257353) {
                profit = spin.tokenValue;
                category = 14;
                emit TwoTSymbols(target, spin.blockn);
            } else if (result < 310818) {
                profit = spin.tokenValue;
                category = 15;
                emit TwoHSymbols(target, spin.blockn);
            } else if (result < 364283) {
                profit = SafeMath.mul(spin.tokenValue, 2);
                category = 16;
                emit TwoEtherIcons(target, spin.blockn);
            } else if (result < 417748) {
                profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 125), 100);
                category = 17;
                emit TwoPurplePyramids(target, spin.blockn);
            } else if (result < 471213) {
                profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 133), 100);
                category = 18;
                emit TwoGoldPyramids(target, spin.blockn);
            } else {
                profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 25), 10);
                category = 19;
                emit TwoRockets(target, spin.blockn);
            }
            uint newMaxProfit = getNewMaxProfit(playerDivrate, outcomeTrack.win);
            if (profit > newMaxProfit) {
                profit = newMaxProfit;
            }
            emit LogResult(target, result, profit, spin.tokenValue, category, true);
            outcomeTrack.win += profit;
        }
    }
    playerSpins[target] = playerSpin(uint192(0), uint48(0), uint8(0), uint8(0), uint(0));
    if (outcomeTrack.jp > 0) {
        for (i = 0; i < outcomeTrack.jp; i++) {
            ZlotsJackpotHoldingContract(zlotsJackpot).payOutWinner(target);
        }
    }
    if (outcomeTrack.win > 0) {
        RequestBankrollPayment(target, outcomeTrack.win, spin.tier);
    }
    if (outcomeTrack.loss > 0) {
        RequestBankrollPayment(zlotsJackpot, outcomeTrack.loss, spin.tier);
    }
    emit SpinConcluded(target, spin.blockn);
    return output;
}

