function _update_period(address gauge, address reward_token) internal returns(uint) {
    uint _period = active_period[gauge][reward_token];
    if (block.timestamp >= _period + WEEK) {
        _period = block.timestamp / WEEK * WEEK;
        GAUGE_CONTROLLER.checkpoint_gauge(gauge);
        uint _slope = GAUGE_CONTROLLER.points_weight(gauge, _period).slope;
        uint _amount = IERC20(reward_token).balanceOf(address(this));
        reward_per_token[gauge][reward_token] = _amount * PRECISION / _slope;
        active_period[gauge][reward_token] = _period;
    }
    return _period;
}

function add_reward_amount(address gauge, address reward_token, uint amount) external returns(bool) {
    _safeTransferFrom(reward_token, msg.sender, address(this), amount);
    _update_period(gauge, reward_token);
    return true;
}

function _claim_reward(address user, address gauge, address reward_token) internal returns(uint) {
    uint _period = _update_period(gauge, reward_token);
    uint _amount = 0;
    if (last_user_claim[user][gauge][reward_token] < _period) {
        last_user_claim[user][gauge][reward_token] = _period;
        uint _last_vote = GAUGE_CONTROLLER.last_user_vote(user, gauge);
        if (_last_vote < _period) {
            uint _slope = GAUGE_CONTROLLER.vote_user_slopes(user, gauge).slope;
            _amount = _slope * reward_per_token[gauge][reward_token] / PRECISION;
            if (_amount > 0) {
                _safeTransfer(reward_token, user, _amount);
            }
        }
    }
    return _amount;
}

function validPurchase() internal constant returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    bool withinContributionLimit = msg.value >= minimumContribution && msg.value <= maximumContribution;
    return withinPeriod && nonZeroPurchase && withinContributionLimit;
}

function calculateTokens(uint value) internal view returns(uint256 tokens) {
    uint256 timeElapsed = now - startTime;
    uint256 timeElapsedInDays = timeElapsed.div(1 days);
    uint256 bonus = 0;
    if (timeElapsedInDays < 15) {
        tokens = value.mul(ratePerWei);
        bonus = tokens.mul(bonusInPhase1);
        bonus = bonus.div(100);
        tokens = tokens.add(bonus);
        require(TOKENS_SOLD.add(tokens) <= maxTokensToSale);
    }
    else if (timeElapsedInDays >= 15 && timeElapsedInDays < 30) {
        tokens = value.mul(ratePerWei);
        bonus = tokens.mul(bonusInPhase2);
        bonus = bonus.div(100);
        tokens = tokens.add(bonus);
        require(TOKENS_SOLD.add(tokens) <= maxTokensToSale);
    } else {
        bonus = 0;
    }
}

function KRCPreSaleContract(uint256 _startTime, address _wallet, address _tokenAddress) public {
    require(_startTime >= now);
    require(_wallet != 0x0);
    startTime = _startTime;
    endTime = startTime + totalDurationInDays;
    require(endTime >= startTime);
    owner = _wallet;
    maxTokensToSale = 87500000e18;
    bonusInPhase1 = 10;
    bonusInPhase2 = 5;
    minimumContribution = 5e17;
    maximumContribution = 150e18;
    ratePerWei = 10000e18;
    token = TokenInterface(_tokenAddress);
    LongTermFoundationBudgetAccumulated = 0;
    LegalContingencyFundsAccumulated = 0;
    MarketingAndCommunityOutreachAccumulated = 0;
    CashReserveFundAccumulated = 0;
    OperationalExpensesAccumulated = 0;
    SoftwareProductDevelopmentAccumulated = 0;
    FoundersTeamAndAdvisorsAccumulated = 0;
    LongTermFoundationBudgetPercentage = 15;
    LegalContingencyFundsPercentage = 10;
    MarketingAndCommunityOutreachPercentage = 10;
    CashReserveFundPercentage = 20;
    OperationalExpensesPercentage = 10;
    SoftwareProductDevelopmentPercentage = 15;
    FoundersTeamAndAdvisorsPercentage = 20;
}

