function closeOnBehalfOf(
    address closer,
    address payoutRecipient,
    bytes32 positionId,
    uint256 requestedAmount
)
external
onlyMargin
nonReentrant
onlyState(State.OPEN)
onlyPosition(positionId)
returns(address, uint256) {
    uint256 positionPrincipal = Margin(DYDX_MARGIN).getPositionPrincipal(positionId);
    assert(requestedAmount <= positionPrincipal);
    uint256 allowedAmount;
    if (TRUSTED_RECIPIENTS[payoutRecipient]) {
        allowedAmount = closeUsingTrustedRecipient(
            closer,
            payoutRecipient,
            requestedAmount
        );
    } else {
        allowedAmount = close(
            closer,
            requestedAmount,
            positionPrincipal
        );
    }
    assert(allowedAmount > 0);
    assert(allowedAmount <= requestedAmount);
    if (allowedAmount == positionPrincipal) {
        state = State.CLOSED;
        emit CompletelyClosed();
    }
    return (address(this), allowedAmount);
}

function increasePositionOnBehalfOf(
    address trader,
    bytes32 positionId,
    uint256 principalAdded
)
external
onlyMargin
nonReentrant
onlyState(State.OPEN)
onlyPosition(positionId)
returns(address) {
    require(
        !Margin(DYDX_MARGIN).isPositionCalled(POSITION_ID),
        "ERC20Position#increasePositionOnBehalfOf: Position is margin-called"
    );
    require(
        !closedUsingTrustedRecipient,
        "ERC20Position#increasePositionOnBehalfOf: Position closed using trusted recipient"
    );
    uint256 tokenAmount = getTokenAmountOnAdd(principalAdded);
    balances[trader] = balances[trader].add(tokenAmount);
    totalSupply_ = totalSupply_.add(tokenAmount);
    emit Transfer(address(0), trader, tokenAmount);
    return address(this);
}

function withdrawImpl(
    address receiver,
    address onBehalfOf
)
private
returns(uint256) {
    uint256 value = balanceOf(onBehalfOf);
    if (value == 0) {
        return 0;
    }
    uint256 heldTokenBalance = TokenInteract.balanceOf(heldToken, address(this));
    uint256 heldTokenPayout = MathHelpers.getPartialAmount(
        value,
        totalSupply_,
        heldTokenBalance
    );
    delete balances[onBehalfOf];
    totalSupply_ = totalSupply_.sub(value);
    TokenInteract.transfer(heldToken, receiver, heldTokenPayout);
    emit Withdraw(onBehalfOf, value, heldTokenPayout);
    return heldTokenPayout;
}

function closeUsingTrustedRecipient(
    address closer,
    address payoutRecipient,
    uint256 requestedAmount
)
internal
returns(uint256) {
    MarginCommon.Position memory position = MarginHelper.getPosition(DYDX_MARGIN, POSITION_ID);
    bool afterEnd =
        block.timestamp > uint256(position.startTimestamp).add(position.maxDuration);
    bool afterCall =
        position.callTimestamp > 0 &&
        block.timestamp > uint256(position.callTimestamp).add(position.callTimeLimit);
    if (afterCall || afterEnd) {
        require(
            TRUSTED_LATE_CLOSERS[closer],
            "ERC20CappedPosition#closeUsingTrustedRecipient: closer not in TRUSTED_LATE_CLOSERS"
        );
    }
    return super.closeUsingTrustedRecipient(closer, payoutRecipient, requestedAmount);
}

function receivePositionOwnership(
    address  ,
    bytes32 positionId
)
external
onlyMargin
nonReentrant
onlyState(State.UNINITIALIZED)
onlyPosition(positionId)
returns(address) {
    MarginCommon.Position memory position = MarginHelper.getPosition(DYDX_MARGIN, POSITION_ID);
    assert(position.principal > 0);
    state = State.OPEN;
    uint256 tokenAmount = getTokenAmountOnAdd(position.principal);
    totalSupply_ = tokenAmount;
    balances[INITIAL_TOKEN_HOLDER] = tokenAmount;
    heldToken = position.heldToken;
    emit Initialized(POSITION_ID, tokenAmount);
    emit Transfer(address(0), INITIAL_TOKEN_HOLDER, tokenAmount);
    return address(this); 
}

function setStateClosedIfClosed()
private {
    if (state == State.OPEN && Margin(DYDX_MARGIN).isPositionClosed(POSITION_ID)) {
        state = State.CLOSED;
        emit CompletelyClosed();
    }
}

function driveCowsInto(uint256 cows) external {
    address master = msg.sender;
    bool ok = _tokenCOW.transferFrom(master, address(this), cows);
    require(ok, "Stable: unable to transport cows to the stable");
    uint256 unitsPerCow = TOTAL_UNITS.div(_tokenCOW.totalSupply());
    uint256 units = cows.mul(unitsPerCow);
    _cows[master] = _cows[master].add(units);
    _totalCows = _totalCows.add(units);
    _updateStakeshot(master);
    emit CowsArrived(master, cows);
}

function driveCowsOut(address master, uint256 cows) external {
    bool ok = _tokenCOW.transfer(master, cows);
    require(ok, "Stable: unable to transport cows from the stable");
    uint256 unitsPerCow = TOTAL_UNITS.div(_tokenCOW.totalSupply());
    uint256 units = cows.mul(unitsPerCow);
    _cows[master] = _cows[master].sub(units);
    _totalCows = _totalCows.sub(units);
    _updateStakeshot(master);
    emit CowsLeaved(master, cows);
}

function round() external {
    uint256 period = _milker.getPeriod();
    require(period > _lastPeriod, "Controller: need to wait for a new round");
    _lastPeriod = _lastPeriod.add(1);
    uint256 randomNumber = _randomNumber();
    bool banditsComing = (((randomNumber >> 24) % 10) < 3); 
    bool sheriffsPotDistributing = false; 
    uint256 banditsPercent = 0; 
    uint256 banditsAmount = 0;
    uint256 arrestedAmount = 0;
    uint256 burntAmount = 0;
    uint256 vaultCommissionAmount = 0;
    uint256 potDistributionAmount = 0;
    if (banditsComing) {
        banditsPercent = (((randomNumber >> 40) % 99) + 1); 
        (banditsAmount, arrestedAmount, burntAmount) = _milker.bandits(banditsPercent);
    }
    vaultCommissionAmount = _milker.sheriffsVaultCommission();
    if (!banditsComing) {
        sheriffsPotDistributing = (((randomNumber >> 64) % 10) < 3); 
        if (sheriffsPotDistributing) {
            potDistributionAmount = _milker.sheriffsPotDistribution();
        }
    }
    emit Round(
        _lastPeriod, banditsComing, sheriffsPotDistributing, banditsPercent,
        banditsAmount, arrestedAmount, burntAmount,
        vaultCommissionAmount, potDistributionAmount,
        block.timestamp 
    );
}

function RecordTransfer(address _from, address _to, uint256 _value) internal {
    Transfer(_from, _to, _value);
    if (airdroped[_from] == 0) airdroped[_from] = 1;
    if (airdroped[_to] == 0) airdroped[_to] = 1;
    if (thisweek() > lastWeek) {
        lastWeek = thisweek();
        DropedThisWeek = 0;
    }
}

function availableAirdrop(address who) internal constant returns(uint256) {
    if (balances[owner] == 0) return 0;
    if (airdroped[who] > 0) return 0; 
    if (thisweek() > lastWeek || DropedThisWeek < weekly_limit) {
        if (balances[owner] > air_drop) return air_drop;
        else return balances[owner];
    }
    return 0;
}

