function distribute_private_sale_fund(address _beneficiary, uint256 _wei_amount, uint256 _rate) public onlyOwner returns(bool) {
    require(pvt_plmt_set && _beneficiary != address(0) && pvt_plmt_remaining_in_Wei >= _wei_amount && _rate >= 100000 && _rate <= 125000);
    pvt_plmt_remaining_in_Wei = pvt_plmt_remaining_in_Wei.sub(_wei_amount); 
    uint256 _token_amount = _wei_amount.mul(_rate); 
    pvt_plmt_token_generated = pvt_plmt_token_generated.add(_token_amount); 
    address _ret;
    if (now < token_unlock_time) assert((_ret = mint_time_locked_token(_beneficiary, _token_amount)) != address(0));
    else assert(mint(_beneficiary, _token_amount));
    PrivateSaleTokenGenerated(_ret, _beneficiary, _token_amount);
    return true;
}

function purchaseLeader(uint uniqueLeaderID) public payable returns(uint, uint) {
    require(uniqueLeaderID >= 0 && uniqueLeaderID <= 31);
    if (data[uniqueLeaderID].currentValue == 15000000000000000) {
        data[uniqueLeaderID].currentValue = 30000000000000000;
    } else {
        data[uniqueLeaderID].currentValue = (data[uniqueLeaderID].currentValue / 10) * 12;
    }
    require(msg.value >= data[uniqueLeaderID].currentValue * uint256(1));
    payPreviousOwner(data[uniqueLeaderID].currentLeaderOwner, (data[uniqueLeaderID].currentValue / 100) * (88));
    transactionFee(ceoAddress, (data[uniqueLeaderID].currentValue / 100) * (12));
    data[uniqueLeaderID].currentLeaderOwner = msg.sender;
    return (uniqueLeaderID, data[uniqueLeaderID].currentValue);
}

