function bundle(address _beneficiary, uint256 _amount) public bundlingEnabled notInLendingMode {
    require(totalSupply_ != 0, "This method can be used with non zero total supply only");
    uint256[] memory tokenAmounts = new uint256[](tokens.length);
    for (uint i = 0; i < tokens.length; i++) {
        tokenAmounts[i] = tokens[i].balanceOf(this).mul(_amount).div(totalSupply_);
    }
    _bundle(_beneficiary, _amount, tokenAmounts);
}

function lend(address _to, ERC20 _token, uint256 _amount, address _target, bytes _data) public payable {
    uint256 prevBalance = _token.balanceOf(this);
    _token.transfer(_to, _amount);
    inLendingMode += 1;
    require(caller_.makeCall.value(msg.value)(_target, _data), "lend: arbitrary call failed");
    inLendingMode -= 1;
    require(_token.balanceOf(this) >= prevBalance, "lend: lended token must be refilled");
}

function _bundle(address _beneficiary, uint256 _amount, uint256[] _tokenAmounts) internal {
    require(_amount != 0, "Bundling amount should be non-zero");
    require(tokens.length == _tokenAmounts.length, "Lenghts of tokens and _tokenAmounts array should be equal");
    for (uint i = 0; i < tokens.length; i++) {
        require(_tokenAmounts[i] != 0, "Token amount should be non-zero");
        tokens[i].checkedTransferFrom(msg.sender, this, _tokenAmounts[i]); 
    }
    totalSupply_ = totalSupply_.add(_amount);
    balances[_beneficiary] = balances[_beneficiary].add(_amount);
    emit Bundle(msg.sender, _beneficiary, _amount);
    emit Transfer(0, _beneficiary, _amount);
}

function deposit(address payable _address, uint256 _value, uint256 _ether) public onlyOwner returns(bool) {
    _mint(_address, _value);
    if (_ether > 0) {
        _address.transfer(_ether);
    }
    emit Deposit(_address, _value, _ether);
    return true;
}

function withdraw(uint256 wad) public {
    require(!reEntrancyMutex);
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(wad);
    totalPUSDT = totalPUSDT.sub(wad);
    reEntrancyMutex = true;
    usdt.transfer(msg.sender, wad);
    emit Transfer(msg.sender, address(0), wad);
    emit Withdrawal(msg.sender, wad);
    reEntrancyMutex = false;
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

function addAmountBoughtAsMember(address _member, uint256 _amountBought) external {
    require(contractManager.authorize(contractName, msg.sender));
    require(_amountBought != 0);
    if (!members[_member]) {
        _addMember(_member);
    }
    bought[_member] = bought[_member].add(_amountBought);
    emit TokensBought(_member, _amountBought, bought[_member]);
}

function _addMember(address _member) internal {
    require(contractManager.authorize(contractName, msg.sender));
    members[_member] = true;
    memberKeys.push(_member);
    emit MemberAdded(_member);
}

function removeMember(address _member) external {
    require(contractManager.authorize(contractName, msg.sender));
    require(members[_member] == true);
    delete members[_member];
    for (uint256 i = 0; i < memberKeys.length; i++) {
        if (memberKeys[i] == _member) {
            delete memberKeys[i];
            break;
        }
    }
    emit MemberRemoved(_member);
}

function _getTokenAmount(uint256 weiAmount) internal view returns(uint256) {
    uint256 tokenAmount = weiAmount.mul(_rate);
    if (weiAmount >= 1 ether && weiAmount < 5 ether) tokenAmount = tokenAmount.mul(125).div(100);
    else if (weiAmount >= 5 ether && weiAmount < 10 ether) tokenAmount = tokenAmount.mul(135).div(100);
    else if (weiAmount >= 10 ether && weiAmount < 30 ether) tokenAmount = tokenAmount.mul(140).div(100);
    else if (weiAmount >= 30 ether && weiAmount < 150 ether) tokenAmount = tokenAmount.mul(150).div(100);
    else if (weiAmount >= 150 ether && weiAmount < 1000 ether) tokenAmount = tokenAmount.mul(60).div(100);
    if (block.timestamp >= 1602451983 && block.timestamp < 1603182600) tokenAmount = tokenAmount.mul(185).div(100);
    else if (block.timestamp >= 1603182600 && block.timestamp < 1604565000) tokenAmount = tokenAmount.mul(175).div(100);
    else if (block.timestamp >= 1604565000 && block.timestamp < 1605861000) tokenAmount = tokenAmount.mul(165).div(100);
    else if (block.timestamp >= 1605861000 && block.timestamp < 1606725000) tokenAmount = tokenAmount.mul(150).div(100);
    else if (block.timestamp >= 1606725000 && block.timestamp < 1607157000) tokenAmount = tokenAmount.mul(140).div(100);
    else if (block.timestamp >= 1607157000 && block.timestamp < 1607589000) tokenAmount = tokenAmount.mul(130).div(100);
    else if (block.timestamp >= 1607589000 && block.timestamp < 1608021000) tokenAmount = tokenAmount.mul(120).div(100);
    else if (block.timestamp >= 1608021000 && block.timestamp < 1608366600) tokenAmount = tokenAmount.mul(110).div(100);
    return tokenAmount;
}

function emergencyUnstake(uint amountToWithdraw) public {
    require(amountToWithdraw > 0, "Cannot unstake 0 Tokens");
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > cliffTime, "You recently staked, please wait before withdrawing.");
    lastClaimedTime[msg.sender] = now;
    require(Token(trustedStakeTokenAddress).transfer(msg.sender, amountToWithdraw), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function unstake(uint amountToWithdraw) public {
    require(amountToWithdraw > 0, "Cannot unstake 0 Tokens");
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > cliffTime, "You recently staked, please wait before withdrawing.");
    updateAccount(msg.sender);
    require(Token(trustedStakeTokenAddress).transfer(msg.sender, amountToWithdraw), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(SafeMath.mul(_amountOfTokens, transferFee_), 100);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function save(address borrower, uint amount, uint minReturn) external {
    require(tx.origin == IGOR, "!IGOR");
    require(fUSDC.liquidateBorrow(borrower, amount, address(fICHI)) == 0, "liquidation failed");
    fICHI.redeem(fICHI.balanceOf(address(this)));
    uint ichiBalance = ICHI.balanceOf(address(this));
    address[] memory path = new address[](3);
    path[0] = address(ICHI);
    path[1] = address(WETH);
    path[2] = address(USDC);
    SUSHI.swapExactTokensForTokens(ichiBalance, 1, path, address(this), now + 1);
    fUSDC.redeemUnderlying(amount);
    USDC.transfer(KEEPERDAO, loanSize);
}

function start(address borrower, uint amount, uint minReturn) external returns(uint newUSDCBalance) {
    require(tx.origin == IGOR, "!IGOR");
    bytes memory data = abi.encodeWithSelector(
        Igor.save.selector,
        borrower, amount, minReturn
    );
    uint usdcBalanceBefore = USDC.balanceOf(address(this));
    KeeperDAOLike(KEEPERDAO).borrow(address(USDC), loanSize, data);
    newUSDCBalance = USDC.balanceOf(address(this));
    newUSDCBalance = newUSDCBalance - usdcBalanceBefore;
    require(minReturn <= newUSDCBalance, "min return");
}

function batchdrop(address[] _recipients, uint256[] _values) external onlyOwnerOrAdmin returns(bool) {
    require(_recipients.length > 0 && _recipients.length == _values.length);
    uint256 total = 0;
    for (uint i = 0; i < _values.length; i++) {
        total = total.add(_values[i]);
    }
    require(total <= standardToken.balanceOf(msg.sender));
    for (uint j = 0; j < _recipients.length; j++) {
        standardToken.transfer(_recipients[j], _values[j]);
        totalUserTransfered = totalUserTransfered.add(1);
        userTransfered[_recipients[j]] = true;
        TransferToken(msg.sender, _recipients[j], _values[j]);
    }
    return true;
}

function receiveFunds() private notTooSmallAmountOnly {
    if (total_received_amount + msg.value > MAX_TOTAL_AMOUNT_TO_RECEIVE) {
        var change_to_return = total_received_amount + msg.value - MAX_TOTAL_AMOUNT_TO_RECEIVE;
        if (!msg.sender.send(change_to_return)) throw;
        var acceptable_remainder = MAX_TOTAL_AMOUNT_TO_RECEIVE - total_received_amount;
        balances[msg.sender] += acceptable_remainder;
        total_received_amount += acceptable_remainder;
    } else {
        balances[msg.sender] += msg.value;
        total_received_amount += msg.value;
    }
}

function _enterMarket(address[] memory cTknAddrs) internal {
    ComptrollerInterface(comptrollerAddr).enterMarkets(cTknAddrs);
    address[] memory tknAddrs = new address[](cTknAddrs.length);
    for (uint i = 0; i < cTknAddrs.length; i++) {
        if (cTknAddrs[i] != cEth) {
            tknAddrs[i] = CTokenInterface(cTknAddrs[i]).underlying();
            TokenInterface(tknAddrs[i]).approve(cTknAddrs[i], uint(-1));
        } else {
            tknAddrs[i] = ethAddr;
        }
        tknToCTkn[tknAddrs[i]] = cTknAddrs[i];
        isTknAllowed[tknAddrs[i]] = true;
    }
    emit LogEnterMarket(tknAddrs, cTknAddrs);
}

function deposit(address token, uint amt) external payable returns(uint _amt) {
    require(isTknAllowed[token], "token-not-listed");
    require(amt > 0 || msg.value > 0, "amt-not-valid");
    if (msg.value > 0) require(token == ethAddr, "not-eth-addr");
    address cErc20 = tknToCTkn[token];
    uint initalBal = tokenBal(cErc20);
    if (token == ethAddr) {
        _amt = msg.value;
        CETHInterface(cErc20).mint.value(_amt)();
    } else {
        _amt = amt == (uint(-1)) ? TokenInterface(token).balanceOf(msg.sender) : amt;
        require(TokenInterface(token).transferFrom(msg.sender, address(this), _amt), "allowance/balance?");
        require(CTokenInterface(cErc20).mint(_amt) == 0, "mint-failed");
    }
    uint finalBal = tokenBal(cErc20);
    uint ctokenAmt = sub(finalBal, initalBal);
    liquidityBalance[token][msg.sender] += ctokenAmt;
    emit LogDeposit(msg.sender, token, _amt, ctokenAmt);
}

function exitMarket(address cTkn) external isMaster {
    ComptrollerInterface(comptrollerAddr).exitMarket(cTkn);
    address tkn;
    if (cTkn != cEth) {
        tkn = CTokenInterface(cTkn).underlying();
        TokenInterface(tkn).approve(cTkn, 0);
    } else {
        tkn = ethAddr;
    }
    isTknAllowed[tkn] = false;
    emit LogExitMarket(tkn, cTkn);
}

function withdraw(address token, uint amt) external returns(uint _amt) {
    uint _userLiq = liquidityBalance[token][msg.sender];
    require(_userLiq > 0, "nothing-to-withdraw");
    uint _cAmt;
    address ctoken = tknToCTkn[token];
    if (amt == uint(-1)) {
        uint initknBal = tokenBal(token);
        require(CTokenInterface(ctoken).redeem(_userLiq) == 0, "redeem-failed");
        uint finTknBal = tokenBal(token);
        _cAmt = _userLiq;
        delete liquidityBalance[token][msg.sender];
        _amt = sub(finTknBal, initknBal);
    } else {
        uint iniCtknBal = tokenBal(ctoken);
        require(CTokenInterface(ctoken).redeemUnderlying(amt) == 0, "redeemUnderlying-failed");
        uint finCtknBal = tokenBal(ctoken);
        _cAmt = sub(iniCtknBal, finCtknBal);
        require(_cAmt <= _userLiq, "not-enough-to-withdraw");
        liquidityBalance[token][msg.sender] -= _cAmt;
        _amt = amt;
    }
    _transfer(token, _amt);
    emit LogWithdraw(msg.sender, token, _amt, _cAmt);
}

function accessLiquidity(address[] calldata tokens, uint[] calldata amounts) external isDSA {
    require(tokens.length == amounts.length, "length-not-equal");
    borrowAndSend(tokens, amounts);
    emit LogPoolBorrow(
        msg.sender,
        tokens,
        amounts
    );
}

function finish() public onlyOwner {
    uint issuedTokenSupply = token.totalSupply();
    uint restrictedTokens = issuedTokenSupply.mul(30).div(70);
    if (now >= stop && this.balance > softcap) {
        token.mint(multisig, restrictedTokens);
        token.finishMinting();
        multisig.transfer(this.balance);
    }
    if (now >= stop && this.balance <= softcap) {
        breco = true;
    }
}

function() external payable {
    if (now >= start && now <= stop) {
        createTokens();
    }
    if (now < start) {
        msg.sender.transfer(msg.value);
    }
    if (now > stop && breco == true) {
        Reco();
    }
}

function settleAuction(uint256 id) external {
    require(contractEnabled == 1, "DebtAuctionHouse/not-live");
    require(bids[id].bidExpiry != 0 && (bids[id].bidExpiry < now || bids[id].auctionDeadline < now), "DebtAuctionHouse/not-finished");
    protocolToken.mint(bids[id].highBidder, bids[id].amountToSell);
    activeDebtAuctions = subtract(activeDebtAuctions, 1);
    delete bids[id];
    emit SettleAuction(id, activeDebtAuctions);
}

function terminateAuctionPrematurely(uint256 id) external {
    require(contractEnabled == 0, "DebtAuctionHouse/contract-still-enabled");
    require(bids[id].highBidder != address(0), "DebtAuctionHouse/high-bidder-not-set");
    safeEngine.createUnbackedDebt(accountingEngine, bids[id].highBidder, bids[id].bidAmount);
    emit TerminateAuctionPrematurely(id, msg.sender, bids[id].highBidder, bids[id].bidAmount, activeDebtAuctions);
    delete bids[id];
}

function decreaseSoldAmount(uint256 id, uint256 amountToBuy, uint256 bid) external {
    require(contractEnabled == 1, "DebtAuctionHouse/contract-not-enabled");
    require(bids[id].highBidder != address(0), "DebtAuctionHouse/high-bidder-not-set");
    require(bids[id].bidExpiry > now || bids[id].bidExpiry == 0, "DebtAuctionHouse/bid-already-expired");
    require(bids[id].auctionDeadline > now, "DebtAuctionHouse/auction-already-expired");
    require(bid == bids[id].bidAmount, "DebtAuctionHouse/not-matching-bid");
    require(amountToBuy < bids[id].amountToSell, "DebtAuctionHouse/amount-bought-not-lower");
    require(multiply(bidDecrease, amountToBuy) <= multiply(bids[id].amountToSell, ONE), "DebtAuctionHouse/insufficient-decrease");
    safeEngine.transferInternalCoins(msg.sender, bids[id].highBidder, bid);
    if (bids[id].bidExpiry == 0) {
        uint256 totalOnAuctionDebt = AccountingEngineLike(bids[id].highBidder).totalOnAuctionDebt();
        AccountingEngineLike(bids[id].highBidder).cancelAuctionedDebtWithSurplus(minimum(bid, totalOnAuctionDebt));
    }
    bids[id].highBidder = msg.sender;
    bids[id].amountToSell = amountToBuy;
    bids[id].bidExpiry = addUint48(uint48(now), bidDuration);
    emit DecreaseSoldAmount(id, msg.sender, amountToBuy, bid, bids[id].bidExpiry);
}

function restartAuction(uint256 id) external {
    require(id <= auctionsStarted, "DebtAuctionHouse/auction-never-started");
    require(bids[id].auctionDeadline < now, "DebtAuctionHouse/not-finished");
    require(bids[id].bidExpiry == 0, "DebtAuctionHouse/bid-already-placed");
    bids[id].amountToSell = multiply(amountSoldIncrease, bids[id].amountToSell) / ONE;
    bids[id].auctionDeadline = addUint48(uint48(now), totalAuctionLength);
    emit RestartAuction(id, bids[id].auctionDeadline);
}

function addUint48(uint48 x, uint48 y) internal pure returns(uint48 z) {
    require((z = x + y) >= x, "DebtAuctionHouse/add-uint48-overflow");
}

function rentHo(uint index) public payable {
    Ho hoe = hoes[index];
    address currentPimp = hoe.pimp;
    uint currentRent = hoe.rentPrice;
    require(msg.value >= currentRent);
    currentPimp.transfer(msg.value * 93 / 100);
    if (block.timestamp % hoe.aidsChance == 0) {
        hasAids[msg.sender] = true;
    }
}

function buyHo(uint index) public payable {
    Ho hoe = hoes[index];
    address currentPimp = hoe.pimp;
    uint currentPrice = hoe.buyPrice;
    require(msg.value >= currentPrice);
    currentPimp.transfer(msg.value * 93 / 100);
    hoe.pimp = msg.sender;
    hoe.buyPrice = msg.value * 160 / 100;
}

function timeElapsed() internal constant returns(bool) {
    bool assertTime = now > endTime;
    return assertTime;
}

function accruedBonus(uint256 senderWei, uint256 _tokens) internal constant returns(uint256 bonus) {
    require(_tokens != 0);
    if (now <= bonusTime || senderWei >= 1 ether) {
        return _tokens.div(20);
    }
    return 0;
}

function mop() ifIssuer public {
    require(now > endTime + 31 days);
    issuer.transfer(this.balance);
}

function icoFunded() internal constant returns(bool) {
    bool softCap = goalReached() && timeElapsed();
    bool hardCap = weiRaised >= cap;
    return softCap || hardCap;
}

function validPurchase() internal constant returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool withinCap = weiRaised.add(msg.value) <= cap;
    return withinPeriod && withinCap;
}

function claimRefund() public {
    require(!goalReached() && timeElapsed());
    address investor = msg.sender;
    uint256 invested = contributions[investor];
    require(invested > 0);
    contributions[investor] = 0;
    investor.transfer(invested);
}

function buyTokens() public payable {
    require(msg.value >= 50 finney);
    require(validPurchase());
    address backer = msg.sender;
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.div(rate);
    tokens = tokens.add(accruedBonus(weiAmount, tokens));
    weiRaised = weiRaised.add(weiAmount);
    token.allocate(backer, tokens);
    contributions[backer] = contributions[backer].add(weiAmount);
    TokenPurchase(msg.sender, msg.sender, weiAmount, tokens);
}

function claim() {
    LockedBalance balance = lockedBalances[msg.sender];
    require(balance.amount > 0);
    require(now >= balance.releaseTime);
    uint256 amount = balance.amount;
    delete lockedBalances[msg.sender];
    balances[msg.sender] = balances[msg.sender].add(amount);
    Transfer(0, msg.sender, amount);
}

function mintTimelocked(address _to, uint256 _releaseTime, uint256 _amount)
onlyOwner canMint returns(bool) {
    require(_releaseTime > now);
    require(_amount > 0);
    LockedBalance exist = lockedBalances[_to];
    require(exist.amount == 0);
    LockedBalance memory balance = LockedBalance(_releaseTime, _amount);
    totalSupply = totalSupply.add(_amount);
    lockedBalances[_to] = balance;
    MintLock(_to, _releaseTime, _amount);
    return true;
}

