function WITHDRAW(uint256 tokens) external {
    require(breaker == false, "Admin Restricted WITHDRAW");
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    require(farmLock[msg.sender] + 30 days <= block.timestamp, "Withdraw can only be done after 30 days");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(Hype).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(Hype).transferFromStake(address(this), msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function withdraw(address to) public {
    if (to == 0x0000000000000000000000000000000000000000) {
        to = msg.sender;
    }
    trickleUp(msg.sender);
    uint256 balance = dividends(msg.sender);
    payouts[msg.sender] += (int256)(balance * scaleFactor);
    totalPayouts += (int256)(balance * scaleFactor);
    uint256 pocketETH = pocket[msg.sender];
    pocket[msg.sender] = 0;
    trickleSum -= pocketETH;
    balance += pocketETH;
    withdrawSum += balance;
    to.transfer(balance);
    emit onCashDividends(msg.sender, to, balance);
}

function getMeOutOfHere() public {
    sellBonds(holdings[msg.sender]);
    withdraw(msg.sender);
}

function fullCycleSellBonds(uint256 balance) internal {
    withdrawSum += balance;
    msg.sender.transfer(balance);
    emit onWithdraw(msg.sender, balance);
}

function sell(uint256 amount) internal {
    uint256 numEthersBeforeFee = getEtherForTokens(amount);
    uint256 fee = 0;
    uint256 trickle = 0;
    if (totalBondSupply != holdings[msg.sender]) {
        fee = fluxFeed(numEthersBeforeFee, false, false);
        trickle = fee / trickTax;
        fee -= trickle;
        tricklingPass[msg.sender] += trickle;
    }
    uint256 numEthers = numEthersBeforeFee - (fee + trickle);
    uint256 resolved = mint(
        calcResolve(msg.sender, amount, numEthersBeforeFee),
        msg.sender
    );
    avgFactor_ethSpent[msg.sender] = TOKEN_scaleDown(avgFactor_ethSpent[msg.sender], amount);
    color_R[msg.sender] = TOKEN_scaleDown(color_R[msg.sender], amount);
    color_G[msg.sender] = TOKEN_scaleDown(color_G[msg.sender], amount);
    color_B[msg.sender] = TOKEN_scaleDown(color_B[msg.sender], amount);
    totalBondSupply -= amount;
    holdings[msg.sender] -= amount;
    int256 payoutDiff = (int256)(earningsPerBond * amount); 
    payouts[msg.sender] -= payoutDiff;
    totalPayouts -= payoutDiff;
    if (totalBondSupply > 0) {
        uint256 etherFee = fee * scaleFactor;
        uint256 rewardPerShare = etherFee / totalBondSupply;
        earningsPerBond += rewardPerShare;
    }
    fullCycleSellBonds(numEthers);
    trickleSum += trickle;
    trickleUp(msg.sender);
    emit onTokenSell(msg.sender, holdings[msg.sender] + amount, amount, numEthers, resolved, reff[msg.sender]);
}

function updateCoverage()
external {
    ArmorCore.deposit(address(this).balance);
    uint256 available = getAvailableCover();
    ArmorCore.subscribe(protocol, available);
    totalCostPerSec = getCoverageCost(available);
    totalEthCoverage = available;
    checkpoint();
}

function updateShield(
    uint256 _newEthValue
)
external
payable {
    ShieldStats memory stats = shieldStats[msg.sender];
    require(stats.lastUpdate > 0, "Only arShields may access this function.");
    uint256 owed = getShieldOwed(msg.sender);
    uint256 unpaid = owed <= msg.value ?
        0 :
        owed - msg.value;
    totalEthValue = totalEthValue -
        uint256(stats.ethValue) +
        _newEthValue;
    checkpoint();
    shieldStats[msg.sender] = ShieldStats(
        uint128(cumCost),
        uint128(_newEthValue),
        uint128(block.timestamp),
        uint128(unpaid)
    );
}

function checkCoverage(
    uint256 _newEthValue
)
public
view
returns(
    bool allowed
) {
    uint256 desired = (totalEthValue +
            _newEthValue -
            uint256(shieldStats[msg.sender].ethValue)) *
        coverPct /
        DENOMINATOR;
    allowed = ArmorCore.availableCover(protocol, desired) == desired;
}

function disburseClaim(
    address payable _shield,
    uint256 _amount
)
external
onlyGov {
    require(shieldStats[_shield].lastUpdate > 0 && IarShield(_shield).locked(), "Shield is not authorized to use this contract or shield is not locked.");
    _shield.transfer(_amount);
}

function purchase(uint256 _stockId, uint256 _shareId) public payable {
    require(_stockId < stocks.length && _shareId < shares.length);
    Stock storage stock = stocks[_stockId];
    uint256[] storage sharesForStock = stockShares[_stockId];
    Share storage share = shares[sharesForStock[_shareId]];
    address previousHolder = share.holder;
    uint256 currentPrice = getPurchasePrice(
        share.purchasePrice,
        stock.priceIncrease
    );
    require(msg.value >= currentPrice);
    if (msg.value > currentPrice) {
        msg.sender.transfer(SafeMath.sub(msg.value, currentPrice));
    }
    uint256 dividendPerRecipient = getDividendPayout(
        currentPrice,
        stock.dividendAmount,
        sharesForStock.length - 1
    );
    uint256 previousHolderShare = SafeMath.sub(
        currentPrice,
        SafeMath.mul(dividendPerRecipient, sharesForStock.length - 1)
    );
    uint256 fee = SafeMath.div(previousHolderShare, 40);
    owner.transfer(fee);
    previousHolder.transfer(SafeMath.sub(previousHolderShare, fee));
    for (uint8 i = 0; i < sharesForStock.length; i++) {
        if (i != _shareId) {
            shares[sharesForStock[i]].holder.transfer(dividendPerRecipient);
            stock.dividendsPaid = SafeMath.add(stock.dividendsPaid, dividendPerRecipient);
            DividendPaid(
                shares[sharesForStock[i]].holder,
                dividendPerRecipient
            );
        }
    }
    ShareSold(
        _stockId,
        _shareId,
        share.purchasePrice,
        currentPrice,
        share.holder,
        msg.sender
    );
    share.holder = msg.sender;
    share.purchasePrice = currentPrice;
    stock.lastAction = block.timestamp;
}

function getCurrentPrice(
    uint256 _stockId,
    uint256 _shareId
) public view returns(uint256 currentPrice) {
    require(_stockId < stocks.length && _shareId < shares.length);
    currentPrice = SafeMath.div(
        SafeMath.mul(stocks[_stockId].priceIncrease, shares[_shareId].purchasePrice),
        100
    );
}

