function distributeAirdrop(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    amount = amount.mul(1e6);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint j = 0; j < addresses.length; j++) {
        require(addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amount);
        Transfer(msg.sender, addresses[j], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e6);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function withdraw() public returns(bool) {
    require(pendingReturns[msg.sender] > 0, "Nothing left for you");
    uint amount = pendingReturns[msg.sender];
    pendingReturns[msg.sender] = 0;
    msg.sender.transfer(amount);
    if (msg.sender == top) {
        loser = top;
        loserbid = topbid;
        top = 0;
        topbid = 0;
    }
    return true;
}

function isLocked() view public returns(bool) {
    return (now < unlocktime && !manualUnlock);
}

function distributeTokens(address _recipient) public {
    require(now >= step1);
    require(buyers[_recipient]);
    bool _lastWithdraw = false;
    uint256 _availableTokens = 0;
    if (now >= step1 && now >= step2 && now >= step3) {
        _availableTokens = _availableTokens.add(allocations3[_recipient]);
        _availableTokens = _availableTokens.add(allocations2[_recipient]);
        _availableTokens = _availableTokens.add(allocations1[_recipient]);
        allocations3[_recipient] = 0;
        allocations2[_recipient] = 0;
        allocations1[_recipient] = 0;
        _lastWithdraw = true;
    } else if (now >= step1 && now >= step2) {
        _availableTokens = _availableTokens.add(allocations2[_recipient]);
        _availableTokens = _availableTokens.add(allocations1[_recipient]);
        allocations2[_recipient] = 0;
        allocations1[_recipient] = 0;
    } else if (now >= step1) {
        _availableTokens = allocations1[_recipient];
        allocations1[_recipient] = 0;
    }
    require(_availableTokens > 0);
    require(token.balanceOf(this) >= _availableTokens);
    require(token.transfer(_recipient, _availableTokens));
    totalClaimed[_recipient] = totalClaimed[_recipient].add(_availableTokens);
    grandTotalClaimed = grandTotalClaimed.add(_availableTokens);
    emit LogTokenClaimed(_recipient, _availableTokens, allocationsTotal[_recipient], grandTotalClaimed);
    if (_lastWithdraw) {
        buyersReceived[_recipient] = true;
    }
}

function checkAvailableTokens(address _recipient) public view returns(uint256) {
    require(buyers[_recipient]);
    uint256 _availableTokens = 0;
    if (now >= step1) {
        _availableTokens = _availableTokens.add(allocations1[_recipient]);
    }
    if (now >= step2) {
        _availableTokens = _availableTokens.add(allocations2[_recipient]);
    }
    if (now >= step3) {
        _availableTokens = _availableTokens.add(allocations3[_recipient]);
    }
    return _availableTokens;
}

constructor(uint256 _step1, uint256 _step2, uint256 _step3, ERC20 _token) public {
    require(_token != address(0));
    require(_step1 >= now);
    require(_step2 >= _step1);
    require(_step3 >= _step2);
    step1 = _step1;
    step2 = _step2;
    step3 = _step3;
    token = _token;
}

function Play(uint8 _number)
external
payable {
    require(msg.sender == tx.origin);
    if (result == _number && msg.value > 0.1 ether && !finished) {
        msg.sender.transfer(this.balance);
        GiftHasBeenSent();
    }
}

function oraclePriceAndBalanceCallback(uint256 _requestId, uint256 _priceA, uint256 _priceB, uint256[] calldata _balances) external onlySystem returns(bool) {
    require(requestFullFilled[_requestId] == false, "ERR_REQUESTED_IS_FULFILLED");
    address _requestedBy = requestedBy[_requestId];
    Oraclize(_requestedBy).oraclePriceAndBalanceCallback(_requestId, _priceA, _priceB, _balances);
    emit PriceAndBalanceUpdated(_requestId, _priceA, _priceB, _balances);
    requestFullFilled[_requestId] = true;
    return true;
}

function oracleCallback(uint256 _requestId, uint256 _balance) external onlySystem returns(bool) {
    require(requestFullFilled[_requestId] == false, "ERR_REQUESTED_IS_FULFILLED");
    address _requestedBy = requestedBy[_requestId];
    Oraclize(_requestedBy).oracleCallback(_requestId, _balance);
    emit BalanceUpdated(_requestId, _balance);
    requestFullFilled[_requestId] = true;
    return true;
}

function refund(uint _numberOfReturns) public onlyOwner {
    require(_numberOfReturns > 0);
    address currentParticipantAddress;
    for (uint cnt = 0; cnt < _numberOfReturns; cnt++) {
        currentParticipantAddress = registry.getContributorByIndex(nextContributorToTransferEth);
        if (currentParticipantAddress == 0x0)
            return;
        if (!hasWithdrawedEth[currentParticipantAddress]) {
            uint EthAmount = registry.getContributionETH(currentParticipantAddress);
            EthAmount -= EthAmount * (percentage / 100 * currentStage);
            currentParticipantAddress.transfer(EthAmount);
            EthRefunded(currentParticipantAddress, EthAmount);
            hasWithdrawedEth[currentParticipantAddress] = true;
        }
        nextContributorToTransferEth += 1;
    }
}

function releaseETH(uint n) onlyPermitted public {
    require(this.balance >= n);
    require(getBalanceReleased() >= n);
    multisig.transfer(n);
    withdrawed += n;
    EthReleased(n);
}

function releaseAllETH() onlyPermitted public {
    uint balReleased = getBalanceReleased();
    require(balReleased > 0);
    require(this.balance >= balReleased);
    multisig.transfer(balReleased);
    withdrawed += balReleased;
    EthReleased(balReleased);
}

function returnETHByOwner() public onlyOwner {
    require(now > dateDeployed + 183 days);
    uint balance = getBalance();
    owner.transfer(getBalance());
    EthReturnedToOwner(owner, balance);
}

function fallback() internal minInvestLimited(msg.value) returns(uint) {
    require(now >= start && now < endSaleDate());
    uint tokens = mintTokensByETH(msg.sender, msg.value);
    if (msg.value >= referalsMinInvestLimit) {
        address referer = getInputAddress();
        if (referer != address(0)) {
            require(referer != address(token) && referer != msg.sender && referer != address(this));
            mintTokens(referer, tokens.mul(refererPercent).div(percentRate));
        }
    }
    return tokens;
}

function approve(address _spender, uint256 _amount)
public
returns(bool success) {
    require(transfersEnabled);
    require((_amount == 0) || (allowed[msg.sender][_spender] == 0));
    if (isContract(controller)) {
        require(
            TokenController(controller).onApprove(
                msg.sender,
                _spender,
                _amount
            )
        );
    }
    allowed[msg.sender][_spender] = _amount;
    Approval(msg.sender, _spender, _amount);
    return true;
}

function safeWithdrawal() {
    if (beneficiary == msg.sender) {
        if (beneficiary.send(amountRaised)) {
            FundTransfer(beneficiary, amountRaised, false);
        }
    }
}

function refund(address _to) public payable returns(bool) {
    require(address(this).balance > 0);
    uint256 _value = balances[_to];
    uint256 ether_value = ETHBalance[_to];
    require(now > start_sale + presalePeriod * 1 days && soldAmount_USD < maxAmountPresale_USD);
    require(_value > 0);
    require(ether_value > 0);
    balances[_to] = balances[_to].sub(_value);
    balances[contract_owner_address] = balances[contract_owner_address].add(_value);
    ETHBalance[_to] = 0;
    approve(_to, ether_value);
    address(_to).transfer(ether_value);
    return true;
}

function generateInitialCard(uint16 _cardLevel) external whenNotPaused onlyOwner returns(uint256) {
    require(address(marketplace) != address(0), "marketplace not set"); 
    require(_cardLevel <= 20, "maximum level cannot exceed 20"); 
    hogsmashToken.setApprovalForAllByContract(msg.sender, marketplace, true); 
    return _createCard(msg.sender, _cardLevel); 
}

function challenge(uint256 _challengerCardId,
    uint32[5] _statUp, 
    uint256 _defenderCardId,
    uint256 _defenderRank,
    uint16 _defenderLevel) external payable whenNotPaused onlyOwnerOf(_challengerCardId) {
    require(battleStart != false, "battle has not started"); 
    require(msg.sender != hogsmashToken.ownerOf(_defenderCardId), "cannot challenge own cards"); 
    Card storage challenger = cards[_challengerCardId];
    require((_statUp[0] + _statUp[1] + _statUp[2] + _statUp[3] + _statUp[4]) == challenger.flexiGems, "flexi gems not used up"); 
    Card storage defender = cards[_defenderCardId];
    if (defender.rank != _defenderRank) {
        emit RejectChallenge(_challengerCardId, _defenderCardId, _defenderRank, 1, uint256(block.number));
        (msg.sender).transfer(msg.value);
        return;
    }
    if (defender.level != _defenderLevel) {
        emit RejectChallenge(_challengerCardId, _defenderCardId, _defenderRank, 2, uint256(block.number));
        (msg.sender).transfer(msg.value);
        return;
    }
    uint256 requiredChallengeFee = challengeFee;
    if (defender.rank < 150) { 
        requiredChallengeFee = requiredChallengeFee.mul(2);
    }
    require(msg.value == requiredChallengeFee, "fee must be equals to challenge price"); 
    uint256 developerFee = 0;
    if (msg.value > 0) {
        developerFee = _calculateFee(msg.value);
    }
    uint256[] memory stats = new uint256[](14); 
    stats[0] = challenger.attack + (_statUp[0] * gemAttackConversion);
    stats[1] = challenger.defense + (_statUp[1] * gemDefenseConversion);
    stats[2] = challenger.hp + (_statUp[2] * gemHpConversion);
    stats[3] = challenger.speed + (_statUp[3] * gemSpeedConversion);
    stats[4] = challenger.criticalRate + (_statUp[4] * gemCriticalRateConversion);
    stats[5] = defender.criticalRate;
    stats[6] = defender.hp;
    stats[8] = challenger.hp + (_statUp[2] * gemHpConversion); 
    stats[9] = challenger.rank; 
    stats[10] = defender.rank; 
    stats[11] = 0; 
    stats[12] = _challengerCardId;
    stats[13] = _defenderCardId;
    if (stats[4] > 7000) {
        stats[4] = 7000; 
    }
    if (stats[5] > 7000) {
        stats[5] = 7000; 
    }
    if (((challenger.element - 1) == defender.element) || ((challenger.element == 1) && (defender.element == 3)) || ((challenger.element == 8) && (defender.element == 9))) {
        stats[4] += 3000; 
        if (stats[4] > 8000) {
            stats[4] = 8000; 
        }
    }
    if (((defender.element - 1) == challenger.element) || ((defender.element == 1) && (challenger.element == 3)) || ((defender.element == 8) && (challenger.element == 9))) {
        stats[5] += 3000; 
        if (stats[5] > 8000) {
            stats[5] = 8000; 
        }
    }
    uint256 battleSequence = _simulateBattle(challenger, defender, stats);
    stats[11] = _transferFees(_challengerCardId, stats, developerFee);
    emit BattleHistory(
        historyId,
        uint8(stats[7]),
        uint64(now),
        uint256(battleSequence),
        uint256(block.number),
        uint256(stats[11])
    );
    emit BattleHistoryChallenger(
        historyId,
        uint256(_challengerCardId),
        uint8(challenger.element),
        uint16(challenger.level),
        uint32(stats[0]),
        uint32(stats[1]),
        uint32(stats[8]),
        uint32(stats[3]),
        uint16(stats[4]), 
        uint256(stats[9])
    );
    emit BattleHistoryDefender(
        historyId,
        uint256(_defenderCardId),
        uint8(defender.element),
        uint16(defender.level),
        uint32(defender.attack),
        uint32(defender.defense),
        uint32(defender.hp),
        uint32(defender.speed),
        uint16(stats[5]),
        uint256(stats[10])
    );
    historyId = historyId.add(1); 
}

function draftNewCard() external payable whenNotPaused returns(uint256) {
    require(msg.value == cardDrawPrice, "fee must be equal to draw price"); 
    require(address(marketplace) != address(0), "marketplace not set"); 
    hogsmashToken.setApprovalForAllByContract(msg.sender, marketplace, true); 
    totalDeveloperCut = totalDeveloperCut.add(cardDrawPrice);
    return _createCard(msg.sender, 1); 
}

function updateAvatar(uint256 _cardId, uint256 avatarHash) external payable whenNotPaused onlyOwnerOf(_cardId) {
    require(msg.value == avatarFee, "fee must be equals to avatar price");
    Card storage card = cards[_cardId];
    uint256 tempHash = card.cardHash % 1000000000000; 
    card.cardHash = tempHash.add(avatarHash.mul(1000000000000));
    emit HashUpdated(_cardId, card.cardHash);
}

function draftNewCardWithReferrer(address referrer) external payable whenNotPaused returns(uint256 cardId) {
    require(msg.value == cardDrawPrice, "fee must be equal to draw price"); 
    require(address(marketplace) != address(0), "marketplace not set"); 
    hogsmashToken.setApprovalForAllByContract(msg.sender, marketplace, true); 
    cardId = _createCard(msg.sender, 1); 
    if ((referrer != address(0)) && (referrerFee != 0) && (referrer != msg.sender) && (hogsmashToken.balanceOf(referrer) > 0)) {
        uint256 referrerCut = msg.value.mul(referrerFee) / 10000;
        require(referrerCut <= msg.value, "referre cut cannot be larger than fee");
        referrer.transfer(referrerCut);
        totalDeveloperCut = totalDeveloperCut.add(cardDrawPrice.sub(referrerCut));
    } else {
        totalDeveloperCut = totalDeveloperCut.add(cardDrawPrice);
    }
}

function _transferFees(uint256 _challengerCardId, uint[] stats, uint256 developerFee) private returns(uint256 totalGained) {
    totalDeveloperCut = totalDeveloperCut.add(developerFee);
    uint256 remainFee = msg.value.sub(developerFee); 
    totalGained = 0;
    if (stats[7] == 1) { 
        rankTokens[stats[10]] = rankTokens[stats[10]].add(remainFee);
        totalRankTokens = totalRankTokens.add(remainFee);
    } else { 
        address challengerAddress = hogsmashToken.ownerOf(_challengerCardId); 
        if (stats[7] == 0) { 
            if (stats[9] > stats[10]) { 
                if (rankTokens[stats[10]] > 0) {
                    totalGained = totalGained.add(rankTokens[stats[10]]);
                    totalRankTokens = totalRankTokens.sub(rankTokens[stats[10]]);
                    rankTokens[stats[10]] = 0;
                }
                if (rankTokens[stats[9]] > 0) {
                    totalGained = totalGained.add(rankTokens[stats[9]]);
                    totalRankTokens = totalRankTokens.sub(rankTokens[stats[9]]);
                    rankTokens[stats[9]] = 0;
                }
            } else { 
                if (stats[9] < 50) { 
                    if ((stats[10] < 150) && (rankTokens[stats[10]] > 0)) { 
                        totalGained = totalGained.add(rankTokens[stats[10]]);
                        totalRankTokens = totalRankTokens.sub(rankTokens[stats[10]]);
                        rankTokens[stats[10]] = 0;
                    }
                    if ((stats[10] < 150) && (rankTokens[stats[9]] > 0)) { 
                        totalGained = totalGained.add(rankTokens[stats[9]]);
                        totalRankTokens = totalRankTokens.sub(rankTokens[stats[9]]);
                        rankTokens[stats[9]] = 0;
                    }
                }
            }
            challengerAddress.transfer(totalGained.add(remainFee)); 
        } else { 
            challengerAddress.transfer(remainFee); 
        }
    }
}

function setMarketplaceAddress(address _address) external onlyOwner {
    Marketplace candidateContract = Marketplace(_address);
    require(candidateContract.isMarketplace(), "needs to be marketplace");
    marketplace = candidateContract;
}

function buyStarterPack() external payable whenNotPaused returns(uint256) {
    require(starterPackOnSale == true, "starter pack is not on sale");
    require(msg.value == starterPackPrice, "fee must be equals to starter pack price");
    require(address(marketplace) != address(0), "marketplace not set"); 
    totalDeveloperCut = totalDeveloperCut.add(starterPackPrice);
    hogsmashToken.setApprovalForAllByContract(msg.sender, marketplace, true); 
    return _createCard(msg.sender, starterPackCardLevel); 
}

function _createCard(address _to, uint16 _initLevel) private returns(uint256) {
    require(_to != address(0), "cannot create card for unknown address"); 
    currentElement += 1;
    if (currentElement == 4) {
        currentElement = 8;
    }
    if (currentElement == 10) {
        currentElement = 1;
    }
    uint256 tempExpLevel = _initLevel;
    if (tempExpLevel > expToNextLevelArr.length) {
        tempExpLevel = expToNextLevelArr.length; 
    }
    uint32 tempCurrentExp = 0;
    if (_initLevel > 1) { 
        tempCurrentExp = expToNextLevelArr[tempExpLevel];
    }
    uint256 tokenId = hogsmashToken.mint(_to);
    Card memory _card = Card({
        element: currentElement, 
        level: _initLevel, 
        attack: 1, 
        defense: 1, 
        hp: 3, 
        speed: 1, 
        criticalRate: 25, 
        flexiGems: 1, 
        currentExp: tempCurrentExp, 
        expToNextLevel: expToNextLevelArr[tempExpLevel], 
        cardHash: generateHash(),
        createdDatetime: uint64(now),
        rank: tokenId 
    });
    cards[tokenId] = _card;
    ranking.push(tokenId); 
    emit CardCreated(msg.sender, tokenId);
    return tokenId;
}

function levelUp(uint256 _id,
    uint16 _attackLevelUp,
    uint16 _defenseLevelUp,
    uint16 _hpLevelUp,
    uint16 _speedLevelUp,
    uint16 _criticalRateLevelUp,
    uint16 _flexiGemsLevelUp) external payable whenNotPaused onlyOwnerOf(_id) {
    require(
        _attackLevelUp >= 0 &&
        _defenseLevelUp >= 0 &&
        _hpLevelUp >= 0 &&
        _speedLevelUp >= 0 &&
        _criticalRateLevelUp >= 0 &&
        _flexiGemsLevelUp >= 0, "level up attributes must be more than 0"
    ); 
    require(msg.value == upgradeFee, "fee must be equals to upgrade price"); 
    Card storage card = cards[_id];
    require(card.currentExp == card.expToNextLevel, "exp is not max yet for level up"); 
    require(card.level < 65535, "card level maximum has reached"); 
    require((card.criticalRate + (_criticalRateLevelUp * gemCriticalRateConversion)) <= 7000, "critical rate max of 70 has reached"); 
    uint totalInputGems = _attackLevelUp + _defenseLevelUp + _hpLevelUp;
    totalInputGems += _speedLevelUp + _criticalRateLevelUp + _flexiGemsLevelUp;
    uint16 numOfSpecials = 0;
    if ((card.level > 1) && (card.attack == 1) && (card.defense == 1) && (card.hp == 3) && (card.speed == 1) && (card.criticalRate == 25) && (card.flexiGems == 1)) {
        numOfSpecials = (card.level + 1) / 5; 
        uint totalGems = (numOfSpecials * upgradeGemsSpecial) + (((card.level) - numOfSpecials) * upgradeGems);
        require(totalInputGems == totalGems, "upgrade gems not used up"); 
    } else {
        if (((card.level + 1) % 5) == 0) { 
            require(totalInputGems == upgradeGemsSpecial, "upgrade gems not used up"); 
            numOfSpecials = 1;
        } else {
            require(totalInputGems == upgradeGems, "upgrade gems not used up"); 
        }
    }
    totalDeveloperCut = totalDeveloperCut.add(upgradeFee);
    _upgradeLevel(_id, _attackLevelUp, _defenseLevelUp, _hpLevelUp, _speedLevelUp, _criticalRateLevelUp, _flexiGemsLevelUp, numOfSpecials);
    emit LevelUp(_id);
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchBlock + 3 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            sellLiquidityFee = defaultSellLiquidityFee;
            sellTxFee = defaultSellTxFee;
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            if (cooldownEnabled) {
                require(cooldown[to] < block.timestamp);
                cooldown[to] = block.timestamp + (30 seconds);
            }
            if (useBuyMap && _buyMap[to] == 0) {
                _buyMap[to] = block.timestamp;
            }
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

function tokensale(address recipient) public payable {
    require(recipient != 0x0);
    if (now < pre_endTime) {
        ico_stage = STAGE_PRE_ICO;
    } else {
        ico_stage = STAGE_MAIN_ICO;
    }
    if (fundRaised >= _presaleSupply) {
        ico_stage = STAGE_MAIN_ICO;
    }
    uint256 weiAmount = msg.value;
    uint tokens = weiAmount.mul(getPrice());
    require(_icoSupply >= tokens);
    balances[token_addr] = balances[token_addr].sub(tokens);
    balances[recipient] = balances[recipient].add(tokens);
    _icoSupply = _icoSupply.sub(tokens);
    fundRaised = fundRaised.add(tokens);
    TokenPurchase(msg.sender, recipient, weiAmount, tokens);
    if (tokens == 0) {
        recipient.transfer(msg.value);
    } else {
        eth_addr.transfer(msg.value);
    }
}

function myRefund(address investor) public onlyOwner whenNotPaused returns(uint256 refunedValue) {
    require(state == State.Refunding);
    uint256 depositedValue = deposited[investor];
    deposited[investor] = 0;
    investor.transfer(depositedValue);
    Refunded(investor, depositedValue);
    return depositedValue;
}

function refundWhenNotClosed(address contributor) public onlyOwner whenNotPaused returns(uint256 weiRefunded) {
    require(state != State.Closed);
    uint256 depositedValue = deposited[contributor];
    deposited[contributor] = 0;
    uint256 refundFees = depositedValue.div(100);
    uint256 refundValue = depositedValue.sub(refundFees);
    if (refundFees > 0)
        wallet.transfer(refundFees);
    if (refundValue > 0)
        contributor.transfer(refundValue);
    Refunded(contributor, depositedValue);
    return depositedValue;
}

function refund(address investor) public {
    require(state == State.Refunding);
    uint256 depositedValue = deposited[investor];
    deposited[investor] = 0;
    investor.transfer(depositedValue);
    Refunded(investor, depositedValue);
}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0)
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    affWallet.transfer(address(this).balance);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function claimTeamToken() external {
    require(msg.sender == TEAM_ACCOUNT);
    require(now >= icoEndTime.add(TEAM_CAN_CLAIM_AFTER));
    require(teamReserve[20] > 0);
    uint claimableTime = icoEndTime.add(TEAM_CAN_CLAIM_AFTER);
    uint totalClaimable;
    for (uint i = 0; i < 21; i++) {
        if (teamReserve[i] > 0) {
            if (claimableTime.add(i.mul(CLAIM_STAGE)) < now) {
                totalClaimable = totalClaimable.add(teamReserve[i]);
                teamReserve[i] = 0;
            } else {
                break;
            }
        }
    }
    if (totalClaimable > 0) {
        mint(TEAM_ACCOUNT, totalClaimable);
    }
}

function claimCompanyReserve() external {
    require(!companyClaimed);
    require(msg.sender == COMPANY_ACCOUNT);
    require(now >= icoEndTime.add(COMPANY_RESERVE_FOR));
    mint(COMPANY_ACCOUNT, COMPANY_RESERVE);
    companyClaimed = true;
}

function setIcoEndTime(uint _icoEndTime) public onlyOwner {
    require(_icoEndTime >= now);
    icoEndTime = _icoEndTime;
}

function inTradingTime() public view returns(bool) {
    for (uint256 idx = 0; idx < _tradingOpenTime.length; idx = idx + 2) {
        if (now > _tradingOpenTime[idx] && now < _tradingOpenTime[idx + 1]) {
            return true;
        }
    }
    return false;
}

function() payable {
    if (!isCrowdsaleAllowed()) {
        throw;
    }
    if (msg.value < 1 szabo) {
        throw;
    }
    uint256 ethersReceived = msg.value;
    uint256 ethersContributed = 0;
    uint256 tokensIssued = 0;
    do {
        if (ethersReceived >= currentRoundBudget) {
            ethersContributed += currentRoundBudget;
            tokensIssued += currentRoundBudget * currentRoundMultiplier;
            ethersReceived -= currentRoundBudget;
            currentRoundIndex += 1;
            (currentRoundMultiplier, currentRoundBudget) = currentRoundParameters();
        } else {
            ethersContributed += ethersReceived;
            tokensIssued += ethersReceived * currentRoundMultiplier;
            currentRoundBudget -= ethersReceived;
            ethersReceived = 0;
        }
    } while ((ethersReceived > 0) && (isCrowdsaleAllowed()));
    owner.transfer(ethersContributed);
    if (ethersReceived > 0) {
        msg.sender.transfer(ethersReceived);
    }
    totalContribution += ethersContributed;
    balances[msg.sender] += tokensIssued;
    totalIssued += tokensIssued;
    Transfer(address(this), msg.sender, tokensIssued);
}

