function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (
        overMinTokenBalance &&
        !inSwapAndLiquify &&
        from != uniswapV2Pair &&
        swapAndLiquifyEnabled
    ) {
        swapAndLiquify(contractTokenBalance);
    }
    if (_firstBuyTime[to] == 0) _firstBuyTime[to] = block.timestamp;
    uint256 feeType = 1;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        feeType = 0;
    } else {
        require(transfersEnabled, "Transfers are not enabled now");
        if (to == uniswapV2Pair || (to != uniswapV2Pair && from != uniswapV2Pair)) {
            require(!_isSniper[from], "SNIPER!");
            if (to != uniswapV2Pair && from != uniswapV2Pair) {
                feeType = 0;
            }
            if (_firstBuyTime[from] != 0 && (_firstBuyTime[from] + (24 hours) > block.timestamp)) {
                feeType = 2;
            }
        }
        if (from == uniswapV2Pair) {
            if (block.number <= (launchBlock + blocksLimit)) _isSniper[to] = true;
        }
    }
    _tokenTransfer(from, to, amount, feeType);
    if (!_isExcludedFromFee[to] && (to != uniswapV2Pair)) require(balanceOf(to) < _maxWalletHolding, "Max Wallet holding limit exceeded");
}

function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(contractTokenBalance);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    uint256 payDevelopment = _pendingDevelopmentFees.mul(newBalance).div(contractTokenBalance);
    uint256 payAdvocacy = _pendingAdvocacyFees.mul(newBalance).div(contractTokenBalance);
    if (payDevelopment <= address(this).balance && payDevelopment > 0) dev.call {
        value: payDevelopment
    }("");
    if (payAdvocacy <= address(this).balance && payAdvocacy > 0) advocacy.call {
        value: payAdvocacy
    }("");
    if (address(this).balance > 0) treasury.call {
        value: address(this).balance
    }("");
    _pendingDevelopmentFees = 0;
    _pendingAdvocacyFees = 0;
}

function _claim_reward(address user, address gauge, address reward_token) internal returns(uint) {
    uint _period = _update_period(gauge, reward_token);
    uint _amount = 0;
    if (last_user_claim[user][gauge][reward_token] < _period) {
        last_user_claim[user][gauge][reward_token] = _period;
        uint _last_vote = GAUGE.last_user_vote(user, gauge);
        if (_last_vote < _period) {
            uint _slope = GAUGE.vote_user_slopes(user, gauge).slope;
            _amount = _slope * reward_per_token[gauge][reward_token] / PRECISION;
            if (_amount > 0) {
                _claims_per_gauge[gauge][reward_token] -= _amount;
                _safeTransfer(reward_token, user, _amount);
            }
        }
    }
    return _amount;
}

function _update_period(address gauge, address reward_token) internal returns(uint) {
    uint _period = active_period[gauge][reward_token];
    if (block.timestamp >= _period + WEEK) {
        _period = block.timestamp / WEEK * WEEK;
        GAUGE.checkpoint_gauge(gauge);
        uint _slope = GAUGE.points_weight(gauge, _period).slope;
        uint _amount = _reward_per_gauge[gauge][reward_token] - _claims_per_gauge[gauge][reward_token];
        reward_per_token[gauge][reward_token] = _amount * PRECISION / _slope;
        active_period[gauge][reward_token] = _period;
    }
    return _period;
}

function add_reward_amount(address gauge, address reward_token, uint amount) external returns(bool) {
    _safeTransferFrom(reward_token, msg.sender, address(this), amount);
    _reward_per_gauge[gauge][reward_token] += amount;
    _update_period(gauge, reward_token);
    _add(gauge, reward_token);
    return true;
}

function canRebase() public view returns(bool) {
    return (lastRebaseTimestampSec.add(minRebaseTimeIntervalSec) < now);
}

function enter(uint256 _amount) public {
    bool available = false;
    stakes[msg.sender][stakeCount[msg.sender]] = stakeData(
        msg.sender,
        _amount,
        block.number,
        0,
        0
    );
    stakeCount[msg.sender] += 1;
    for (uint i = 0; i < stakers.length; i++) {
        if (stakers[i] == msg.sender) {
            available = true;
            break;
        } else {
            continue;
        }
    }
    if (!available) {
        stakers.push(msg.sender);
    }
    uint256 usersSushi = token.balanceOf(msg.sender);
    uint256 allowedSushi = token.allowance(msg.sender, address(this));
    require(usersSushi >= _amount, "Insufficient Balance to Stake");
    require(allowedSushi >= _amount, "Allowed balance is Insufficient");
    token.transferFrom(msg.sender, address(this), _amount);
    _mint(msg.sender, _amount);
}

function unstake() public {
    uint256 stakeAmount = 0;
    for (uint256 i = 0; i < stakeCount[msg.sender]; i++) {
        stakeAmount = stakeAmount.add(stakes[msg.sender][i].amount);
    }
    require(0 < stakeAmount, "Amount insufficient");
    uint256 reward = _rewards(msg.sender);
    _burn(msg.sender, stakeAmount);
    token.transfer(msg.sender, reward.add(stakeAmount));
    stakes[msg.sender][0].rewards = stakes[msg.sender][0].rewards.add(reward);
    stakes[msg.sender][0].uBlockNumber = block.number;
}

function getrewards() public {
    uint256 stakeAmount = 0;
    for (uint256 i = 0; i < stakeCount[msg.sender]; i++) {
        stakeAmount = stakeAmount.add(stakes[msg.sender][i].amount);
    }
    require(0 < stakeAmount, "Amount insufficient");
    uint256 rewards = _rewards(msg.sender);
    token.transfer(msg.sender, rewards);
    stakes[msg.sender][0].rewards = stakes[msg.sender][0].rewards.add(rewards);
}

