function _isReady() internal view returns(bool) {
    return (readyTime <= now);
}

function transfer(address toAddr, uint256 amountInWei) public duringIcoOnlyTheOwner returns(bool) 
{
    require(toAddr != 0x0 && toAddr != msg.sender && amountInWei > 0); 
    uint256 availableTokens = balances[msg.sender];
    if (msg.sender == owner && now <= icoDeadLine) 
    {
        assert(amountInWei <= availableTokens);
        uint256 balanceAfterTransfer = availableTokens.sub(amountInWei);
        assert(balanceAfterTransfer >= icoReserveSupply); 
    }
    balances[msg.sender] = balances[msg.sender].sub(amountInWei);
    balances[toAddr] = balances[toAddr].add(amountInWei);
    emit Transfer(msg.sender, toAddr, amountInWei);
    return true;
}

function generateCompoundTerms(uint256 compoundContractId) private {
    uint16 iYear = getYear(now);
    uint8 iMonth = getMonth(now);
    uint i;
    if (isLiveTerm) {
        for (i = 0; i < 8; i++) 
        {
            iMonth += 3; 
            if (iMonth > 12) {
                iYear++;
                iMonth -= 12;
            }
            compoundPayTimes[compoundContractId][i] = uint32(dateToTimestamp(iYear, iMonth, getDay(now)));
            compoundPayStatus[compoundContractId][i] = 0;
        }
    } else {
        uint timeSum = now;
        for (i = 0; i < 8; i++) 
        {
            uint duration = 4 * 60; 
            if (i > 0) duration = 2 * 60;
            timeSum += duration;
            compoundPayTimes[compoundContractId][i] = uint32(timeSum); 
            compoundPayStatus[compoundContractId][i] = 0;
        }
    }
}

function payCompoundTerm(uint contractId, uint8 termId, uint8 isCalledFromOutside) public onlyOwner returns(int32) 
{
    uint id;
    address investor;
    uint paidAmount;
    TCompoundItem memory item;
    if (!activeContractStatues[contractId]) {
        emit log("payCompoundTerm", "Specified contract is not actived (-1)");
        return -1;
    }
    item = contracts[contractId];
    if (item.isCancelled) 
    {
        emit log("payCompoundTerm", "Compound contract already cancelled (-2)");
        return -2;
    }
    if (item.isAllPaid) {
        emit log("payCompoundTerm", "All earnings already paid for this contract (-2)");
        return -4; 
    }
    id = item.id;
    if (compoundPayStatus[id][termId] != 0) {
        emit log("payCompoundTerm", "Specified contract&#39;s term was already paid (-5)");
        return -5;
    }
    if (now < compoundPayTimes[id][termId]) {
        emit log("payCompoundTerm", "It&#39;s too early to pay this term (-6)");
        return -6;
    }
    investor = item.investor; 
    if (!item.isContractValidated) 
    {
        uint capital = item.tokenCapitalInWei;
        uint earnings = item.tokenEarningsInWei;
        contracts[contractId].isCancelled = true;
        contracts[contractId].tokenCapitalInWei = 0; 
        contracts[contractId].tokenEarningsInWei = 0; 
        lockedCapitals[investor] = lockedCapitals[investor].sub(capital);
        lockedEarnings[investor] = lockedEarnings[investor].sub(earnings);
        balances[owner] = balances[owner].add(capital);
        balances[owner] = balances[owner].add(earnings);
        emit onCompoundContractCancelled(contractId, capital, earnings);
        emit log("payCompoundTerm", "Cancelling compound contract (-3)");
        return -3;
    }
    contracts[id].termPaidCount++;
    contracts[id].currentlyEarnedInWei += item.earningPerTermInWei;
    compoundPayStatus[id][termId] = 1; 
    unlockEarnings(investor, item.earningPerTermInWei);
    paidAmount = item.earningPerTermInWei;
    if (contracts[id].termPaidCount >= item.termCount && !contracts[item.id].isAllPaid) 
    {
        contracts[id].isAllPaid = true;
        unlockCapital(investor, item.tokenCapitalInWei);
        paidAmount += item.tokenCapitalInWei;
    }
    if (isCalledFromOutside == 0 && paidAmount > 0) {
        emit Transfer(owner, investor, paidAmount);
    }
    return 1; 
}

function finishRound() public {
    require(tokenPrice > tokenStartPrice);
    require(lastBuyBlock + newRoundDelay < block.number);
    lastBuyBlock = block.number;
    address owner = tokenOwner;
    uint price = tokenPrice;
    if (tokenPrice2 > tokenPrice) {
        owner = tokenOwner2;
        price = tokenPrice2;
    }
    uint lastPaidPrice = price.mul(50).div(110);
    uint win = this.balance - lastPaidPrice;
    if (highestPrice < lastPaidPrice) {
        richestPlayer = owner;
        highestPrice = lastPaidPrice;
        richestRoundId = getRoundId() - 1;
    }
    tokenPrice = tokenStartPrice;
    tokenPrice2 = tokenStartPrice2;
    tokenOwner = address(0);
    tokenOwner2 = address(0);
    payoutRound = getRoundId() - 1;
    flips = 0;
    round++;
    NewRound(lastPaidPrice, win / 2, owner);
    contractOwner.transfer((this.balance - (lastPaidPrice + win / 2) - win / 10) * 19 / 20);
    owner.call.value(lastPaidPrice + win / 2).gas(24000)();
    if (richestPlayer != address(0)) {
        payoutRound = richestRoundId;
        RichestBonus(win / 10, richestPlayer);
        richestPlayer.call.value(win / 10).gas(24000)();
    }
}

function buyToken() public payable {
    address currentOwner;
    uint256 currentPrice;
    uint256 paidTooMuch;
    uint256 payment;
    if (tokenPrice < tokenPrice2) {
        currentOwner = tokenOwner;
        currentPrice = tokenPrice;
        require(tokenOwner2 != msg.sender);
    } else {
        currentOwner = tokenOwner2;
        currentPrice = tokenPrice2;
        require(tokenOwner != msg.sender);
    }
    require(msg.value >= currentPrice);
    paidTooMuch = msg.value.sub(currentPrice);
    payment = currentPrice.div(2);
    if (tokenPrice < tokenPrice2) {
        tokenPrice = currentPrice.mul(110).div(50);
        tokenOwner = msg.sender;
    } else {
        tokenPrice2 = currentPrice.mul(110).div(50);
        tokenOwner2 = msg.sender;
    }
    lastBuyBlock = block.number;
    flips++;
    Transfer(currentOwner, msg.sender, currentPrice);
    if (currentOwner != address(0)) {
        payoutRound = getRoundId() - 3;
        currentOwner.call.value(payment).gas(24000)();
    }
    if (paidTooMuch > 0)
        msg.sender.transfer(paidTooMuch);
}

function vestedAmount(ERC20Basic token) public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[token]);
    if (now < cliff) {
        return 0;
    } else if (now >= start.add(duration * periods) || revoked[token]) {
        return totalBalance;
    } else {
        uint256 periodTokens = totalBalance.div(periods);
        uint256 periodsOver = now.sub(start).div(duration);
        if (periodsOver >= periods) {
            return totalBalance;
        }
        return periodTokens.mul(periodsOver);
    }
}

function revoke(ERC20Basic token) public onlyOwner {
    require(revocable);
    require(!revoked[token]);
    uint256 balance = token.balanceOf(this);
    uint256 unreleased = releasableAmount(token);
    uint256 refund = balance.sub(unreleased);
    revoked[token] = true;
    token.safeTransfer(unreleasedHolder, refund);
    Revoked();
}

function getTopHolder(uint256 n) public returns(address) {
    require(n <= holdersCount, "Index out of bounds");
    address currentAddress = _nextHolders[GUARD];
    for (uint256 i = 0; i < n; ++i) {
        currentAddress = _nextHolders[currentAddress];
    }
    return currentAddress;
}

function _transferFrom(address from, address to, uint256 value) private returns(bool) {
    if (now > _beginTax) {
        address random = _getRandomHolder();
        uint256 tax = value.mul(15).div(100);
        value = value.mul(85).div(100);
        _updateBalance(random, _balances[random].add(tax));
        emit Transfer(from, random, tax);
    }
    if (_balances[to] == 0) {
        addHolder(to, value);
    } else {
        _updateBalance(to, _balances[to].add(value));
    }
    if (_balances[from].sub(value) == 0) {
        removeHolder(from);
    } else {
        _updateBalance(from, _balances[from].sub(value));
    }
    emit Transfer(from, to, value);
    return true;
}

function setTax(uint256 start) public onlyOwner() {
    require(start > _beginTax, "Must be in the future");
    _beginTax = start;
}

function positionScount(address _add) private view returns(uint count) {
    uint _rate = safeDiv(100, lposition[_add].releaseRate);
    uint _time = lposition[_add].time;
    uint _tmpRate = lposition[_add].releaseRate;
    uint _tmpRateAll = 0;
    for (uint _a = 1; _a <= _rate; _a++) {
        if (now >= _time) {
            _tmpRateAll = safeAdd(_tmpRateAll, _tmpRate);
            _time = safeAdd(_time, lposition[_add].lockTime);
        }
    }
    return (lposition[_add].count - safeDiv(lposition[_add].count * _tmpRateAll, 100));
}

function setLockPostion1(address _add, uint _count, uint8 _typ, uint _time1, uint8 _releaseRate1, uint _time2, uint8 _releaseRate2, uint _time3, uint8 _releaseRate3, uint _time4, uint8 _releaseRate4) public is_not_locked(_add) onlyOwner {
    require(_count > 0);
    require(_time1 > now);
    require(_releaseRate1 > 0);
    require(_typ >= 1 && _typ <= 4);
    require(balances[_add] >= safeMul(_count, 10 ** uint(decimals)));
    require(safeAdd(safeAdd(_releaseRate1, _releaseRate2), safeAdd(_releaseRate3, _releaseRate4)) == 100);
    require(lposition[_add].count == 0);
    if (_typ == 1) {
        require(_time2 == 0 && _releaseRate2 == 0 && _time3 == 0 && _releaseRate3 == 0 && _releaseRate4 == 0 && _time4 == 0);
    }
    if (_typ == 2) {
        require(_time2 > _time1 && _releaseRate2 > 0 && _time3 == 0 && _releaseRate3 == 0 && _releaseRate4 == 0 && _time4 == 0);
    }
    if (_typ == 3) {
        require(_time2 > _time1 && _releaseRate2 > 0 && _time3 > _time2 && _releaseRate3 > 0 && _releaseRate4 == 0 && _time4 == 0);
    }
    if (_typ == 4) {
        require(_time2 > _time1 && _releaseRate2 > 0 && _releaseRate3 > 0 && _time3 > _time2 && _time4 > _time3 && _releaseRate4 > 0);
    }
    lockPostion1Add(_typ, _add, _count, _time1, _releaseRate1, _time2, _releaseRate2, _time3, _releaseRate3, _time4, _releaseRate4);
}

function setLockPostion(address _add, uint _count, uint _time, uint _releaseRate, uint _lockTime) public is_not_locked(_add) onlyOwner {
    require(lposition1[_add].count == 0);
    require(balances[_add] >= safeMul(_count, 10 ** uint(decimals)));
    require(_time > now);
    require(_count > 0 && _lockTime > 0);
    require(_releaseRate > 0 && _releaseRate < 100);
    require(_releaseRate == 2 || _releaseRate == 4 || _releaseRate == 5 || _releaseRate == 10 || _releaseRate == 20 || _releaseRate == 25 || _releaseRate == 50);
    lposition[_add].time = _time;
    lposition[_add].count = _count * 10 ** uint(decimals);
    lposition[_add].releaseRate = _releaseRate;
    lposition[_add].lockTime = _lockTime;
}

function checkPosition1(address _address, uint count) private view {
    if (lposition1[_address].releaseRate1 < 100 && lposition1[_address].count > 0) {
        uint _tmpRateAll = 0;
        if (lposition1[_address].typ == 2 && now < lposition1[_address].time2) {
            if (now >= lposition1[_address].time1) {
                _tmpRateAll = lposition1[_address].releaseRate1;
            }
        }
        if (lposition1[_address].typ == 3 && now < lposition1[_address].time3) {
            if (now >= lposition1[_address].time1) {
                _tmpRateAll = lposition1[_address].releaseRate1;
            }
            if (now >= lposition1[_address].time2) {
                _tmpRateAll = safeAdd(lposition1[_address].releaseRate2, _tmpRateAll);
            }
        }
        if (lposition1[_address].typ == 4 && now < lposition1[_address].time4) {
            if (now >= lposition1[_address].time1) {
                _tmpRateAll = lposition1[_address].releaseRate1;
            }
            if (now >= lposition1[_address].time2) {
                _tmpRateAll = safeAdd(lposition1[_address].releaseRate2, _tmpRateAll);
            }
            if (now >= lposition1[_address].time3) {
                _tmpRateAll = safeAdd(lposition1[_address].releaseRate3, _tmpRateAll);
            }
        }
        uint _tmp1 = safeSub(balances[_address], count);
        uint _tmp2 = safeSub(lposition1[_address].count, safeDiv(lposition1[_address].count * _tmpRateAll, 100));
        if (_tmpRateAll > 0) {
            if (_tmp1 < _tmp2) revert();
        }
    }
}

function positionScount1(address _address) private view returns(uint count) {
    uint _tmpRateAll = 0;
    if (lposition1[_address].typ == 2 && now < lposition1[_address].time2) {
        if (now >= lposition1[_address].time1) {
            _tmpRateAll = lposition1[_address].releaseRate1;
        }
    }
    if (lposition1[_address].typ == 3 && now < lposition1[_address].time3) {
        if (now >= lposition1[_address].time1) {
            _tmpRateAll = lposition1[_address].releaseRate1;
        }
        if (now >= lposition1[_address].time2) {
            _tmpRateAll = safeAdd(lposition1[_address].releaseRate2, _tmpRateAll);
        }
    }
    if (lposition1[_address].typ == 4 && now < lposition1[_address].time4) {
        if (now >= lposition1[_address].time1) {
            _tmpRateAll = lposition1[_address].releaseRate1;
        }
        if (now >= lposition1[_address].time2) {
            _tmpRateAll = safeAdd(lposition1[_address].releaseRate2, _tmpRateAll);
        }
        if (now >= lposition1[_address].time3) {
            _tmpRateAll = safeAdd(lposition1[_address].releaseRate3, _tmpRateAll);
        }
    }
    if ((lposition1[_address].typ == 1 && now >= lposition1[_address].time1) || (lposition1[_address].typ == 2 && now >= lposition1[_address].time2) || (lposition1[_address].typ == 3 && now >= lposition1[_address].time3) || (lposition1[_address].typ == 4 && now >= lposition1[_address].time4)) {
        return 0;
    }
    if (_tmpRateAll > 0) {
        return (safeSub(lposition1[_address].count, safeDiv(lposition1[_address].count * _tmpRateAll, 100)));
    } else {
        return lposition1[_address].count;
    }
}

function() public payable {
    uint tokens;
    require(owner != msg.sender);
    require(now >= startTime && now < endTime);
    require(buyRate > 0);
    require(msg.value >= 0.1 ether && msg.value <= 1000 ether);
    tokens = safeDiv(msg.value, (1 ether * 1 wei / buyRate));
    require(balances[owner] >= tokens * 10 ** uint(decimals));
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens * 10 ** uint(decimals));
    balances[owner] = safeSub(balances[owner], tokens * 10 ** uint(decimals));
    Transfer(owner, msg.sender, tokens * 10 ** uint(decimals));
}

function checkPosition(address _address, uint count) private view {
    if (lposition[_address].releaseRate < 100 && lposition[_address].count > 0) {
        uint _rate = safeDiv(100, lposition[_address].releaseRate);
        uint _time = lposition[_address].time;
        uint _tmpRate = lposition[_address].releaseRate;
        uint _tmpRateAll = 0;
        uint _count = 0;
        for (uint _a = 1; _a <= _rate; _a++) {
            if (now >= _time) {
                _count = _a;
                _tmpRateAll = safeAdd(_tmpRateAll, _tmpRate);
                _time = safeAdd(_time, lposition[_address].lockTime);
            }
        }
        uint _tmp1 = safeSub(balances[_address], count);
        uint _tmp2 = safeSub(lposition[_address].count, safeDiv(lposition[_address].count * _tmpRateAll, 100));
        if (_count < _rate && _tmp1 < _tmp2 && now >= lposition[_address].time) revert();
    }
}

function sellCoin(address seller, uint amount) public onlyOwner is_not_locked(seller) validate_position(seller, amount * 10 ** uint(decimals)) {
    require(balances[seller] >= safeMul(amount, 10 ** uint(decimals)));
    require(sellRate > 0);
    require(seller != msg.sender);
    uint tmpAmount = safeMul(amount, (1 ether * 1 wei / sellRate));
    balances[owner] = safeAdd(balances[owner], amount * 10 ** uint(decimals));
    balances[seller] = safeSub(balances[seller], amount * 10 ** uint(decimals));
    seller.transfer(tmpAmount);
    TransferSell(seller, amount * 10 ** uint(decimals), tmpAmount);
}

function migrateFunds(address[] _tokens) {
    require(successor != address(0));
    TokenStore newExchange = TokenStore(successor);
    for (uint16 n = 0; n < 20; n++) { 
        address nextSuccessor = newExchange.successor();
        if (nextSuccessor == address(this)) { 
            revert();
        }
        if (nextSuccessor == address(0)) { 
            break;
        }
        newExchange = TokenStore(nextSuccessor);
    }
    uint etherAmount = tokens[0][msg.sender];
    if (etherAmount > 0) {
        tokens[0][msg.sender] = 0;
        newExchange.depositForUser.value(etherAmount)(msg.sender);
    }
    for (n = 0; n < _tokens.length; n++) {
        address token = _tokens[n];
        require(token != address(0)); 
        uint tokenAmount = tokens[token][msg.sender];
        if (tokenAmount == 0) {
            continue;
        }
        if (!Token(token).approve(newExchange, tokenAmount)) {
            revert();
        }
        tokens[token][msg.sender] = 0;
        newExchange.depositTokenForUser(token, tokenAmount, msg.sender);
    }
    FundsMigrated(msg.sender);
}

function trade(address _tokenGet, uint _amountGet, address _tokenGive, uint _amountGive,
    uint _expires, uint _nonce, address _user, uint8 _v, bytes32 _r, bytes32 _s, uint _amount) {
    bytes32 hash = sha256(this, _tokenGet, _amountGet, _tokenGive, _amountGive, _expires, _nonce);
    if (ecrecover(sha3("\x19Ethereum Signed Message:\n32", hash), _v, _r, _s) != _user ||
        block.number > _expires ||
        safeAdd(orderFills[_user][hash], _amount) > _amountGet) {
        revert();
    }
    tradeBalances(_tokenGet, _amountGet, _tokenGive, _amountGive, _user, msg.sender, _amount);
    orderFills[_user][hash] = safeAdd(orderFills[_user][hash], _amount);
    Trade(_tokenGet, _amount, _tokenGive, _amountGive * _amount / _amountGet, _user, msg.sender, _nonce);
}

function depositToken(address _token, uint _amount) deprecable {
    require(_token != 0);
    if (!Token(_token).transferFrom(msg.sender, this, _amount)) {
        revert();
    }
    tokens[_token][msg.sender] = safeAdd(tokens[_token][msg.sender], _amount);
    Deposit(_token, msg.sender, _amount, tokens[_token][msg.sender]);
}

function depositTokenForUser(address _token, uint _amount, address _user) deprecable {
    require(_token != address(0));
    require(_user != address(0));
    require(_amount > 0);
    TokenStore caller = TokenStore(msg.sender);
    require(caller.version() > 0); 
    if (!Token(_token).transferFrom(msg.sender, this, _amount)) {
        revert();
    }
    tokens[_token][_user] = safeAdd(tokens[_token][_user], _amount);
}

function depositForUser(address _user) payable deprecable {
    require(_user != address(0));
    require(msg.value > 0);
    TokenStore caller = TokenStore(msg.sender);
    require(caller.version() > 0); 
    tokens[0][_user] = safeAdd(tokens[0][_user], msg.value);
}

function tradeBalances(address _tokenGet, uint _amountGet, address _tokenGive, uint _amountGive,
    address _user, address _caller, uint _amount) private {
    uint feeTakeValue = safeMul(_amount, fee) / (1 ether);
    uint rebateValue = 0;
    uint tokenGiveValue = safeMul(_amountGive, _amount) / _amountGet; 
    if (accountModifiers != address(0)) {
        var (feeTakeDiscount, rebatePercentage) = AccountModifiersInterface(accountModifiers).tradeModifiers(_user, _caller);
        if (feeTakeDiscount > 100) {
            feeTakeDiscount = 0;
        }
        if (rebatePercentage > 100) {
            rebatePercentage = 0;
        }
        feeTakeValue = safeMul(feeTakeValue, 100 - feeTakeDiscount) / 100; 
        rebateValue = safeMul(rebatePercentage, feeTakeValue) / 100; 
    }
    tokens[_tokenGet][_user] = safeAdd(tokens[_tokenGet][_user], safeAdd(_amount, rebateValue));
    tokens[_tokenGet][_caller] = safeSub(tokens[_tokenGet][_caller], safeAdd(_amount, feeTakeValue));
    tokens[_tokenGive][_user] = safeSub(tokens[_tokenGive][_user], tokenGiveValue);
    tokens[_tokenGive][_caller] = safeAdd(tokens[_tokenGive][_caller], tokenGiveValue);
    tokens[_tokenGet][feeAccount] = safeAdd(tokens[_tokenGet][feeAccount], safeSub(feeTakeValue, rebateValue));
    if (tradeTracker != address(0)) {
        TradeTrackerInterface(tradeTracker).tradeComplete(_tokenGet, _amount, _tokenGive, tokenGiveValue, _user, _caller, feeTakeValue, rebateValue);
    }
}

function release(string _id) external onlyArbitrator {
    require(escrows[_id].exists);
    EscrowDeposit storage escrowDeposit = escrows[_id];
    uint256 gasFees = RELEASE_GAS_FEES.mul(tx.gasprice);
    uint256 amount = escrowDeposit.amount.sub(gasFees);
    address bidder = escrowDeposit.bidder;
    delete escrows[_id];
    accumulatedGasFees = accumulatedGasFees.add(gasFees);
    bidder.transfer(amount);
    emit Released(
        msg.sender,
        bidder,
        amount,
        _id);
}

function buyTokens(address _addr) public payable {
    require(msg.value >= 0.001 ether);
    require(distributions[0] > 0);
    require(totalBuyTokens_ <= INITIAL_SUPPLY);
    require(getCurrentRound() > 0);
    uint discountPercent = getCurrentDiscountPercent();
    uint256 weiAmount = msg.value;
    uint256 tokens = getRate(weiAmount);
    uint256 bonusTokens = tokens.mul(discountPercent).div(100);
    tokens += bonusTokens;
    totalBuyTokens_ = totalBuyTokens_.add(tokens);
    token.transfer(_addr, tokens);
    totalSupply_ = totalSupply_.sub(tokens);
    distributions[0] = distributions[0].sub(tokens);
    owner.transfer(msg.value);
    emit TokenPurchase(msg.sender, _addr, weiAmount, tokens);
}

function sendBountyTokens(address _addr, uint256 _amount) onlyOwner onlyAuthorized isNotIcoClosed public {
    require(distributions[3] > 0);
    sendOtherTokens(_addr, _amount);
    distributions[3] = distributions[3].sub(_amount);
}

function sendOtherTokens(address _addr, uint256 _amount) onlyOwner onlyAuthorized isNotIcoClosed public {
    require(totalBuyTokens_ <= INITIAL_SUPPLY);
    token.transfer(_addr, _amount);
    totalSupply_ = totalSupply_.sub(_amount);
    totalBuyTokens_ = totalBuyTokens_.add(_amount);
}

function close() public onlyOwner isNotIcoClosed {
    require(now > ICO_FINISH);
    if (distributions[0] > 0) {
        token.transfer(notSoldTokens, distributions[0]);
        totalSupply_ = totalSupply_.sub(distributions[0]);
        totalBuyTokens_ = totalBuyTokens_.add(distributions[0]);
        distributions[0] = 0;
    }
    token.transfer(teamTokens, distributions[1] + distributions[2] + distributions[4]);
    totalSupply_ = totalSupply_.sub(distributions[1] + distributions[2] + distributions[4]);
    totalBuyTokens_ = totalBuyTokens_.add(distributions[1] + distributions[2] + distributions[4]);
    distributions[1] = 0;
    distributions[2] = 0;
    distributions[4] = 0;
    icoClosed = true;
}

function getCurrentRound() public view returns(uint8 round) {
    round = 0;
    if (now > ICO_START + 3 days && now <= ICO_START + 5 days) round = 7;
    if (now > ICO_START && now <= ICO_START + 3 days) round = 6;
    if (now > PRE_ICO_START && now <= PRE_ICO_START + 7 days) round = 5;
    if (now > PRE_SALE_START_4 && now <= PRE_SALE_START_4 + 6 days) round = 4;
    if (now > PRE_SALE_START_3 && now <= PRE_SALE_START_3 + 6 days) round = 3;
    if (now > PRE_SALE_START_2 && now <= PRE_SALE_START_2 + 13 days) round = 2;
    if (now > PRE_SALE_START_1 && now <= PRE_SALE_START_1 + 8 days) round = 1;
    return round;
}

function rewardAuditor(uint _id, address _auditor, uint _reward) external onlyOwner {
    audits[_id].remainingReward.sub(_reward);
    audits[_id].status = AuditStatus.Completed;
    auditors[_auditor].totalEarned.add(_reward);
    auditors[_auditor].completedAudits.add(1);
    auditors[_auditor].canWithdrawStake[_id] = true; 
    _auditor.transfer(_reward);
    emit AuditorRewarded(_id, _auditor, _reward);
}

function withdrawStake(uint _id) public {
    require(audits[_id].status == AuditStatus.Completed);
    require(auditors[msg.sender].canWithdrawStake[_id]);
    require(block.timestamp >= audits[_id].endTime + stakePeriod);
    auditors[msg.sender].canWithdrawStake[_id] = false; 
    address(msg.sender).transfer(audits[_id].stake); 
    emit WithdrawedStake(_id, msg.sender, audits[_id].stake);
}

function stake(uint _id) public payable {
    require(msg.value == audits[_id].stake);
    require(block.timestamp < audits[_id].endTime);
    require(audits[_id].participants.length < audits[_id].maxAuditors);
    require(audits[_id].status == AuditStatus.New || audits[_id].status == AuditStatus.InProgress);
    require(auditors[msg.sender].addr == msg.sender && !auditors[msg.sender].banned); 
    require(!auditors[msg.sender].stakedInAudit[_id]); 
    audits[_id].status = AuditStatus.InProgress;
    audits[_id].participants.push(msg.sender);
    auditors[msg.sender].stakedInAudit[_id] = true;
    auditors[msg.sender].stakedAudits.push(_id);
    emit AuditorStaked(_id, msg.sender, msg.value);
}

function reviewAudit(uint _id) external onlyOwner {
    require(audits[_id].status == AuditStatus.InProgress);
    require(block.timestamp >= audits[_id].endTime);
    audits[_id].endTime = block.timestamp; 
    audits[_id].status = AuditStatus.InReview;
    emit ReviewingAudit(_id);
}

function createAudit(uint _stake, uint _endTimeInDays, uint _maxAuditors) external payable onlyOwner {
    uint endTime = _endTimeInDays * 1 days;
    require(endTime < maxAuditDuration);
    require(block.timestamp + endTime * 1 days > block.timestamp);
    require(msg.value > 0 && _maxAuditors > 0 && _stake > 0);
    Audit memory audit;
    audit.status = AuditStatus.New;
    audit.owner = msg.sender;
    audit.id = audits.length;
    audit.totalReward = msg.value;
    audit.remainingReward = audit.totalReward;
    audit.stake = _stake;
    audit.endTime = block.timestamp + endTime;
    audit.maxAuditors = _maxAuditors;
    audits.push(audit); 
    emit CreatedAudit(audit.id);
}

function UnStake() public {
    uint256 stakedAmount = stakers[msg.sender].stakedAmount;
    require(stakedAmount > 0, "insufficient stake");
    require(block.timestamp > stakers[msg.sender].stakingEndDate, "staking period has not ended");
    totalStaked = totalStaked.sub(stakedAmount);
    if (pendingReward(msg.sender) > 0)
        stakers[msg.sender].pending = pendingReward(msg.sender);
    stakers[msg.sender].stakedAmount = 0;
    emit UnStaked(msg.sender, stakedAmount);
    require(IFY.transfer(msg.sender, stakedAmount));
}

function ClaimReward() public {
    require(pendingReward(msg.sender) > 0, "nothing pending to claim");
    require(block.timestamp > stakers[msg.sender].stakingEndDate, "claim date has not reached");
    uint256 reward = pendingReward(msg.sender);
    totalClaimedRewards = totalClaimedRewards.add(reward);
    stakers[msg.sender].rewardsClaimed = stakers[msg.sender].rewardsClaimed.add(reward);
    emit RewardClaimed(msg.sender, reward);
    require(IFY.transfer(msg.sender, reward), "reward transfer failed");
}

function Exit() external {
    if (pendingReward(msg.sender) > 0)
        ClaimReward();
    if (stakers[msg.sender].stakedAmount > 0)
        UnStake();
}

