function _preValidatePurchase(address _beneficiary, uint256 _weiAmount) internal whenNotPaused {
    require(_beneficiary != address(0));
    require(_weiAmount != 0);
    require(now >= openingTime && now <= closingTime);
}

function getCurrentRate() public view returns(uint256) {
    if (now <= openingTime.add(7 days)) return rate.add(rate / 5); 
    if (now > openingTime.add(7 days) && now <= openingTime.add(14 days)) return rate.add(rate / 10); 
    if (now > openingTime.add(14 days) && now <= openingTime.add(28 days)) return rate.add(rate / 20); 
}

function withdrawMNU() public {
    user storage _user = users[msg.sender];
    require(_user.total > _user.releaseAmount, "All released");
    require(block.timestamp > _user.time, "It's not time yet");
    _user.releaseAmount += _user.release;
    _user.time = block.timestamp + 604800;
    ERC20(MNUerc20).transfer(msg.sender, _user.release);
}

function tokenFallback(address _sender, uint _value, bytes) external {
    if (!active) {
        revert();
    }
    ATxAssetProxy _token = token;
    if (msg.sender != _token.getLatestVersion()) {
        revert();
    }
    uint _etherToExchange = _value.mul(price) / (10 ** uint(_token.decimals()));
    if (this.balance < _etherToExchange) {
        revert();
    }
    ATxPlatformInterface _platform = ATxPlatformInterface(address(_token.platform()));
    require(OK == _platform.revokeAsset(_token.smbl(), _value));
    uint _restEther = _takeRdFee(_etherToExchange);
    _sender.transfer(_restEther);
    TokenExchanged(_sender, _token, _value, _restEther, _etherToExchange.sub(_restEther), rdCollectorAddress, price);
}

function allocateToken() onlyOwner public {
    require(block.timestamp > lockStartTime);
    require(allocations[teamWallet] == 0);
    require(token.balanceOf(address(this)) >= totalAllocation);
    allocations[teamWallet] = teamAllocation;
    stageSettings[teamWallet] = teamStageSetting;
    timeLockDurations[teamWallet] = teamTimeLock;
}

function releaseToken() onlyReserveWallets public {
    uint256 totalUnlocked = unlockAmount();
    require(totalUnlocked <= allocations[msg.sender]);
    require(releasedAmounts[msg.sender] < totalUnlocked);
    uint256 payment = totalUnlocked.sub(releasedAmounts[msg.sender]);
    releasedAmounts[msg.sender] = totalUnlocked;
    require(token.transfer(msg.sender, payment));
}

function vestStage() public view onlyReserveWallets returns(uint256) {
    uint256 vestingMonths = timeLockDurations[msg.sender].div(stageSettings[msg.sender]);
    uint256 stage = (block.timestamp.sub(lockStartTime)).div(vestingMonths);
    if (stage > stageSettings[msg.sender]) {
        stage = stageSettings[msg.sender];
    }
    return stage;
}

function buyEggs() public payable {
    require(initialized);
    uint256 eggsBought = calculateEggBuy(msg.value, SafeMath.sub(address(this).balance, msg.value));
    eggsBought = SafeMath.sub(eggsBought, devFee(eggsBought));
    ceoAddress.transfer(devFee(msg.value));
    claimedEggs[msg.sender] = SafeMath.add(claimedEggs[msg.sender], eggsBought);
}

function extendLock(uint extendedUnlockTimestamp) external onlyOwner {
    require(extendedUnlockTimestamp > now && extendedUnlockTimestamp > unlockTime, "Cannot set an unlock time in past!");
    require(extendedUnlockTimestamp.sub(now) <= MAX_EXTENSION_ALLOWED, "Cannot extend beyond MAX_EXTENSION_ALLOWED period!");
    unlockTime = extendedUnlockTimestamp;
}

constructor(uint initialUnlockTime) public {
    require(initialUnlockTime > now, "Cannot set an unlock time in past!");
    unlockTime = initialUnlockTime;
}

function _lock(address from, uint256 amount, uint256 due)
internal
returns(bool success) {
    require(due > now, "ERC20Lockable/lock : Cannot set due to past");
    require(
        _balances[from] >= amount.add(_totalLocked[from]),
        "ERC20Lockable/lock : locked total should be smaller than balance"
    );
    _totalLocked[from] = _totalLocked[from].add(amount);
    _locks[from].push(LockInfo(amount, due));
    emit Lock(from, amount, due);
    success = true;
}

function unlock(address from) external returns(bool success) {
    for (uint256 i = 0; i < _locks[from].length; i++) {
        if (_locks[from][i].due < now) {
            _unlock(from, i);
        }
    }
    success = true;
}

function deposit(address _contributor) onlyOwner external payable {
    require(state == State.Active || state == State.Success);
    if (firstDepositTimestamp == 0) {
        firstDepositTimestamp = now;
    }
    totalDeposited = totalDeposited.add(msg.value);
    deposited[_contributor] = deposited[_contributor].add(msg.value);
}

function sendFundsToWallet() external atState(State.Closed) {
    require(nextDisbursement <= now);
    if (disbursementDuration == 0) {
        trustedWallet.transfer(address(this).balance);
        return;
    }
    uint256 numberOfDisbursements = now.sub(nextDisbursement).div(disbursementDuration).add(1);
    nextDisbursement = nextDisbursement.add(disbursementDuration.mul(numberOfDisbursements));
    transferToWallet(disbursementWei.mul(numberOfDisbursements));
}

function refund(address _contributor) external atState(State.Refunding) {
    require(deposited[_contributor] > 0);
    uint256 refundAmount = deposited[_contributor].mul(refundable).div(totalDeposited);
    deposited[_contributor] = 0;
    _contributor.transfer(refundAmount);
    emit Refunded(_contributor, refundAmount);
}

function buyTokens(address _beneficiary) public payable {
    uint256 ethers = msg.value;
    _preValidatePurchase(_beneficiary, ethers);
    _checkOpenings(ethers);
    _setFunds(_beneficiary, ethers);
    fundsRaised = fundsRaised.add(ethers);
    _forwardFunds(_beneficiary);
}

function _checkOpenings(uint256 _weiAmount) internal {
    if ((fundsRaised + _weiAmount >= hardCap)) {
        presaleOpen = false;
        firstsaleOpen = false;
        secondsaleOpen = true;
    } else if (secondsaleOpen) {
        presaleOpen = false;
        firstsaleOpen = false;
        secondsaleOpen = true;
    } else if (now >= presaleopeningTime && now <= presaleclosingTime) {
        presaleOpen = true;
        firstsaleOpen = false;
        secondsaleOpen = false;
        if (reserveTokens >= 0) {
            if (TokenAllocate(reserverWallet, reserveTokens)) {
                reserveTokens = 0;
            }
        }
    } else if (now >= saleopeningTime && now <= saleclosingTime) {
        presaleOpen = false;
        firstsaleOpen = true;
        secondsaleOpen = false;
    } else if (now >= secondsaleopeningTime && now <= secondsaleclosingTime) {
        presaleOpen = false;
        firstsaleOpen = false;
        secondsaleOpen = true;
    } else {
        presaleOpen = false;
        firstsaleOpen = false;
        secondsaleOpen = false;
        if (teamAdvTokens >= 0 && bountyTokens >= 0) {
            TokenAllocate(teamsWallet, teamAdvTokens);
            teamAdvTokens = 0;
            TokenAllocate(bountyWallet, bountyTokens);
            bountyTokens = 0;
        }
    }
}

function secondSaleDelivery(address _beneficiary, uint256 _tokenAmount) public onlyOwner {
    require(!presaleOpen && !firstsaleOpen && !secondsaleOpen, "Second Sale is NOT CLOSE");
    require(saleTokens >= _tokenAmount, "NO Sale Tokens Available");
    token.transfer(_beneficiary, _tokenAmount);
    saleTokens = saleTokens.sub(_tokenAmount);
}

function stopSecondSale() public onlyOwner {
    presaleOpen = false;
    firstsaleOpen = false;
    secondsaleOpen = false;
    if (teamAdvTokens >= 0 && bountyTokens >= 0) {
        TokenAllocate(teamsWallet, teamAdvTokens);
        teamAdvTokens = 0;
        TokenAllocate(bountyWallet, bountyTokens);
        bountyTokens = 0;
    }
}

function firstSaleDelivery(address _beneficiary, uint256 _tokenAmount) public onlyOwner {
    require(!presaleOpen && !firstsaleOpen, "First Sale is NOT CLOSE");
    if (saleTokens <= _tokenAmount && preSaleTokens >= _tokenAmount) {
        saleTokens = saleTokens.add(_tokenAmount);
        preSaleTokens = preSaleTokens.sub(_tokenAmount);
    }
    token.transfer(_beneficiary, _tokenAmount);
    saleTokens = saleTokens.sub(_tokenAmount);
}

function preSaleDelivery(address _beneficiary, uint256 _tokenAmount) public onlyOwner {
    _checkOpenings(0);
    require(!presaleOpen, "Pre-Sale is NOT CLOSE ");
    require(preSaleTokens >= _tokenAmount, "NO Pre-SALE Tokens Available");
    token.transfer(_beneficiary, _tokenAmount);
    preSaleTokens = preSaleTokens.sub(_tokenAmount);
}

function adjustTap(uint256 _amount) external onlyOwner {
    require(_amount > 0);
    uint256 balance = token.balanceOf(this);
    require(_amount <= balance);
    releasedTokens = _amount;
    emit TokenTapAdjusted(_amount);
}

function liquidateBorrow(
    address targetAccount,
    address assetBorrow,
    address assetCollateral,
    uint256 requestedAmountClose
) public payable returns(uint256) {
    if (paused) {
        return
        fail(
            Error.CONTRACT_PAUSED,
            FailureInfo.LIQUIDATE_CONTRACT_PAUSED
        );
    }
    refreshAlkSupplyIndex(assetCollateral, targetAccount, false);
    refreshAlkSupplyIndex(assetCollateral, msg.sender, false);
    refreshAlkBorrowIndex(assetBorrow, targetAccount, false);
    LiquidateLocalVars memory localResults;
    localResults.targetAccount = targetAccount;
    localResults.assetBorrow = assetBorrow;
    localResults.liquidator = msg.sender;
    localResults.assetCollateral = assetCollateral;
    Market storage borrowMarket = markets[assetBorrow];
    Market storage collateralMarket = markets[assetCollateral];
    Balance storage borrowBalance_TargeUnderwaterAsset = borrowBalances[
        targetAccount
    ][assetBorrow];
    Balance storage supplyBalance_TargetCollateralAsset = supplyBalances[
        targetAccount
    ][assetCollateral];
    Balance storage supplyBalance_LiquidatorCollateralAsset
        = supplyBalances[localResults.liquidator][assetCollateral];
    uint256 rateCalculationResultCode; 
    Error err; 
    (err, localResults.collateralPrice) = fetchAssetPrice(assetCollateral);
    if (err != Error.NO_ERROR) {
        return fail(err, FailureInfo.LIQUIDATE_FETCH_ASSET_PRICE_FAILED);
    }
    (err, localResults.underwaterAssetPrice) = fetchAssetPrice(assetBorrow);
    assert(err == Error.NO_ERROR);
    (
        err,
        localResults.newBorrowIndex_UnderwaterAsset
    ) = calculateInterestIndex(
        borrowMarket.borrowIndex,
        borrowMarket.borrowRateMantissa,
        borrowMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_BORROW_INDEX_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    (
        err,
        localResults.currentBorrowBalance_TargetUnderwaterAsset
    ) = calculateBalance(
        borrowBalance_TargeUnderwaterAsset.principal,
        borrowBalance_TargeUnderwaterAsset.interestIndex,
        localResults.newBorrowIndex_UnderwaterAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_ACCUMULATED_BORROW_BALANCE_CALCULATION_FAILED
        );
    }
    (
        err,
        localResults.newSupplyIndex_CollateralAsset
    ) = calculateInterestIndex(
        collateralMarket.supplyIndex,
        collateralMarket.supplyRateMantissa,
        collateralMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_SUPPLY_INDEX_CALCULATION_FAILED_COLLATERAL_ASSET
        );
    }
    (
        err,
        localResults.currentSupplyBalance_TargetCollateralAsset
    ) = calculateBalance(
        supplyBalance_TargetCollateralAsset.principal,
        supplyBalance_TargetCollateralAsset.interestIndex,
        localResults.newSupplyIndex_CollateralAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_ACCUMULATED_SUPPLY_BALANCE_CALCULATION_FAILED_BORROWER_COLLATERAL_ASSET
        );
    }
    (
        err,
        localResults.currentSupplyBalance_LiquidatorCollateralAsset
    ) = calculateBalance(
        supplyBalance_LiquidatorCollateralAsset.principal,
        supplyBalance_LiquidatorCollateralAsset.interestIndex,
        localResults.newSupplyIndex_CollateralAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_ACCUMULATED_SUPPLY_BALANCE_CALCULATION_FAILED_LIQUIDATOR_COLLATERAL_ASSET
        );
    }
    (err, localResults.newTotalSupply_ProtocolCollateralAsset) = addThenSub(
        collateralMarket.totalSupply,
        localResults.currentSupplyBalance_TargetCollateralAsset,
        supplyBalance_TargetCollateralAsset.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_SUPPLY_BALANCE_CALCULATION_FAILED_BORROWER_COLLATERAL_ASSET
        );
    }
    (err, localResults.newTotalSupply_ProtocolCollateralAsset) = addThenSub(
        localResults.newTotalSupply_ProtocolCollateralAsset,
        localResults.currentSupplyBalance_LiquidatorCollateralAsset,
        supplyBalance_LiquidatorCollateralAsset.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_SUPPLY_BALANCE_CALCULATION_FAILED_LIQUIDATOR_COLLATERAL_ASSET
        );
    }
    (
        err,
        localResults.discountedBorrowDenominatedCollateral
    ) = calculateDiscountedBorrowDenominatedCollateral(
        localResults.underwaterAssetPrice,
        localResults.collateralPrice,
        localResults.currentSupplyBalance_TargetCollateralAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_BORROW_DENOMINATED_COLLATERAL_CALCULATION_FAILED
        );
    }
    if (borrowMarket.isSupported) {
        (
            err,
            localResults.discountedRepayToEvenAmount
        ) = calculateDiscountedRepayToEvenAmount(
            targetAccount,
            localResults.underwaterAssetPrice,
            assetBorrow
        );
        if (err != Error.NO_ERROR) {
            return
            fail(
                err,
                FailureInfo
                .LIQUIDATE_DISCOUNTED_REPAY_TO_EVEN_AMOUNT_CALCULATION_FAILED
            );
        }
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset = min(
            localResults.currentBorrowBalance_TargetUnderwaterAsset,
            localResults.discountedBorrowDenominatedCollateral
        );
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset = min(
            localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset,
            localResults.discountedRepayToEvenAmount
        );
    } else {
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset = min(
            localResults.currentBorrowBalance_TargetUnderwaterAsset,
            localResults.discountedBorrowDenominatedCollateral
        );
    }
    if (assetBorrow != wethAddress) {
        if (requestedAmountClose == uint256(-1)) {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = localResults
                .maxCloseableBorrowAmount_TargetUnderwaterAsset;
        } else {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = requestedAmountClose;
        }
    } else {
        if (
            requestedAmountClose >
            localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset
        ) {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = localResults
                .maxCloseableBorrowAmount_TargetUnderwaterAsset;
            (err, localResults.reimburseAmount) = sub(
                requestedAmountClose,
                localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset
            ); 
            if (err != Error.NO_ERROR) {
                return
                fail(
                    err,
                    FailureInfo
                    .REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
                );
            }
        } else {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = requestedAmountClose;
        }
    }
    if (
        localResults.closeBorrowAmount_TargetUnderwaterAsset >
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset
    ) {
        return
        fail(
            Error.INVALID_CLOSE_AMOUNT_REQUESTED,
            FailureInfo.LIQUIDATE_CLOSE_AMOUNT_TOO_HIGH
        );
    }
    (
        err,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    ) = calculateAmountSeize(
        localResults.underwaterAssetPrice,
        localResults.collateralPrice,
        localResults.closeBorrowAmount_TargetUnderwaterAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.LIQUIDATE_AMOUNT_SEIZE_CALCULATION_FAILED
        );
    }
    if (assetBorrow != wethAddress) {
        err = checkTransferIn(
            assetBorrow,
            localResults.liquidator,
            localResults.closeBorrowAmount_TargetUnderwaterAsset
        );
        if (err != Error.NO_ERROR) {
            return
            fail(err, FailureInfo.LIQUIDATE_TRANSFER_IN_NOT_POSSIBLE);
        }
    }
    (err, localResults.updatedBorrowBalance_TargetUnderwaterAsset) = sub(
        localResults.currentBorrowBalance_TargetUnderwaterAsset,
        localResults.closeBorrowAmount_TargetUnderwaterAsset
    );
    assert(err == Error.NO_ERROR);
    (
        err,
        localResults.newTotalBorrows_ProtocolUnderwaterAsset
    ) = addThenSub(
        borrowMarket.totalBorrows,
        localResults.updatedBorrowBalance_TargetUnderwaterAsset,
        borrowBalance_TargeUnderwaterAsset.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_BORROW_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    localResults.currentCash_ProtocolUnderwaterAsset = getCash(assetBorrow);
    (err, localResults.updatedCash_ProtocolUnderwaterAsset) = add(
        localResults.currentCash_ProtocolUnderwaterAsset,
        localResults.closeBorrowAmount_TargetUnderwaterAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_CASH_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    (
        err,
        localResults.newSupplyIndex_UnderwaterAsset
    ) = calculateInterestIndex(
        borrowMarket.supplyIndex,
        borrowMarket.supplyRateMantissa,
        borrowMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_SUPPLY_INDEX_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    (
        rateCalculationResultCode,
        localResults.newSupplyRateMantissa_ProtocolUnderwaterAsset
    ) = borrowMarket.interestRateModel.getSupplyRate(
        assetBorrow,
        localResults.updatedCash_ProtocolUnderwaterAsset,
        localResults.newTotalBorrows_ProtocolUnderwaterAsset
    );
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo
            .LIQUIDATE_NEW_SUPPLY_RATE_CALCULATION_FAILED_BORROWED_ASSET,
            rateCalculationResultCode
        );
    }
    (
        rateCalculationResultCode,
        localResults.newBorrowRateMantissa_ProtocolUnderwaterAsset
    ) = borrowMarket.interestRateModel.getBorrowRate(
        assetBorrow,
        localResults.updatedCash_ProtocolUnderwaterAsset,
        localResults.newTotalBorrows_ProtocolUnderwaterAsset
    );
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo
            .LIQUIDATE_NEW_BORROW_RATE_CALCULATION_FAILED_BORROWED_ASSET,
            rateCalculationResultCode
        );
    }
    (
        err,
        localResults.newBorrowIndex_CollateralAsset
    ) = calculateInterestIndex(
        collateralMarket.borrowIndex,
        collateralMarket.borrowRateMantissa,
        collateralMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_BORROW_INDEX_CALCULATION_FAILED_COLLATERAL_ASSET
        );
    }
    (err, localResults.updatedSupplyBalance_TargetCollateralAsset) = sub(
        localResults.currentSupplyBalance_TargetCollateralAsset,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    );
    assert(err == Error.NO_ERROR);
    (
        err,
        localResults.updatedSupplyBalance_LiquidatorCollateralAsset
    ) = add(
        localResults.currentSupplyBalance_LiquidatorCollateralAsset,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    );
    assert(err == Error.NO_ERROR);
    borrowMarket.blockNumber = block.number;
    borrowMarket.totalBorrows = localResults
        .newTotalBorrows_ProtocolUnderwaterAsset;
    borrowMarket.supplyRateMantissa = localResults
        .newSupplyRateMantissa_ProtocolUnderwaterAsset;
    borrowMarket.supplyIndex = localResults.newSupplyIndex_UnderwaterAsset;
    borrowMarket.borrowRateMantissa = localResults
        .newBorrowRateMantissa_ProtocolUnderwaterAsset;
    borrowMarket.borrowIndex = localResults.newBorrowIndex_UnderwaterAsset;
    collateralMarket.blockNumber = block.number;
    collateralMarket.totalSupply = localResults
        .newTotalSupply_ProtocolCollateralAsset;
    collateralMarket.supplyIndex = localResults
        .newSupplyIndex_CollateralAsset;
    collateralMarket.borrowIndex = localResults
        .newBorrowIndex_CollateralAsset;
    localResults
        .startingBorrowBalance_TargetUnderwaterAsset = borrowBalance_TargeUnderwaterAsset
        .principal; 
    borrowBalance_TargeUnderwaterAsset.principal = localResults
        .updatedBorrowBalance_TargetUnderwaterAsset;
    borrowBalance_TargeUnderwaterAsset.interestIndex = localResults
        .newBorrowIndex_UnderwaterAsset;
    localResults
        .startingSupplyBalance_TargetCollateralAsset = supplyBalance_TargetCollateralAsset
        .principal; 
    supplyBalance_TargetCollateralAsset.principal = localResults
        .updatedSupplyBalance_TargetCollateralAsset;
    supplyBalance_TargetCollateralAsset.interestIndex = localResults
        .newSupplyIndex_CollateralAsset;
    localResults
        .startingSupplyBalance_LiquidatorCollateralAsset = supplyBalance_LiquidatorCollateralAsset
        .principal; 
    supplyBalance_LiquidatorCollateralAsset.principal = localResults
        .updatedSupplyBalance_LiquidatorCollateralAsset;
    supplyBalance_LiquidatorCollateralAsset.interestIndex = localResults
        .newSupplyIndex_CollateralAsset;
    if (assetBorrow != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = doTransferIn(
            assetBorrow,
            localResults.liquidator,
            localResults.closeBorrowAmount_TargetUnderwaterAsset
        );
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.LIQUIDATE_TRANSFER_IN_FAILED);
        }
    } else {
        if (msg.value == requestedAmountClose) {
            uint256 supplyError = supplyEther(
                localResults.liquidator,
                localResults.closeBorrowAmount_TargetUnderwaterAsset
            );
            if (localResults.reimburseAmount > 0) {
                revertEtherToUser(
                    localResults.liquidator,
                    localResults.reimburseAmount
                );
            }
            if (supplyError != 0) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    Error.WETH_ADDRESS_NOT_SET_ERROR,
                    FailureInfo.WETH_ADDRESS_NOT_SET_ERROR
                );
            }
        } else {
            revertEtherToUser(msg.sender, msg.value);
            return
            fail(
                Error.ETHER_AMOUNT_MISMATCH_ERROR,
                FailureInfo.ETHER_AMOUNT_MISMATCH_ERROR
            );
        }
    }
    supplyOriginationFeeAsAdmin(
        assetBorrow,
        localResults.liquidator,
        localResults.closeBorrowAmount_TargetUnderwaterAsset,
        localResults.newSupplyIndex_UnderwaterAsset
    );
    emit BorrowLiquidated(
        localResults.targetAccount,
        localResults.assetBorrow,
        localResults.currentBorrowBalance_TargetUnderwaterAsset,
        localResults.closeBorrowAmount_TargetUnderwaterAsset,
        localResults.liquidator,
        localResults.assetCollateral,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    );
    return uint256(Error.NO_ERROR); 
}

function repayBorrow(address asset, uint256 amount)
public
payable
nonReentrant
returns(uint256) {
    if (paused) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            Error.CONTRACT_PAUSED,
            FailureInfo.REPAY_BORROW_CONTRACT_PAUSED
        );
    }
    refreshAlkBorrowIndex(asset, msg.sender, false);
    PayBorrowLocalVars memory localResults;
    Market storage market = markets[asset];
    Balance storage borrowBalance = borrowBalances[msg.sender][asset];
    Error err;
    uint256 rateCalculationResultCode;
    (err, localResults.newBorrowIndex) = calculateInterestIndex(
        market.borrowIndex,
        market.borrowRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_BORROW_INDEX_CALCULATION_FAILED
        );
    }
    (err, localResults.userBorrowCurrent) = calculateBalance(
        borrowBalance.principal,
        borrowBalance.interestIndex,
        localResults.newBorrowIndex
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo
            .REPAY_BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED
        );
    }
    uint256 reimburseAmount;
    if (asset != wethAddress) {
        if (amount == uint256(-1)) {
            localResults.repayAmount = min(
                getBalanceOf(asset, msg.sender),
                localResults.userBorrowCurrent
            );
        } else {
            localResults.repayAmount = amount;
        }
    } else {
        if (amount > localResults.userBorrowCurrent) {
            localResults.repayAmount = localResults.userBorrowCurrent;
            (err, reimburseAmount) = sub(
                amount,
                localResults.userBorrowCurrent
            ); 
            if (err != Error.NO_ERROR) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    err,
                    FailureInfo
                    .REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
                );
            }
        } else {
            localResults.repayAmount = amount;
        }
    }
    (err, localResults.userBorrowUpdated) = sub(
        localResults.userBorrowCurrent,
        localResults.repayAmount
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo
            .REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
        );
    }
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = checkTransferIn(asset, msg.sender, localResults.repayAmount);
        if (err != Error.NO_ERROR) {
            return
            fail(
                err,
                FailureInfo.REPAY_BORROW_TRANSFER_IN_NOT_POSSIBLE
            );
        }
    }
    (err, localResults.newTotalBorrows) = addThenSub(
        market.totalBorrows,
        localResults.userBorrowUpdated,
        borrowBalance.principal
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_TOTAL_BORROW_CALCULATION_FAILED
        );
    }
    localResults.currentCash = getCash(asset);
    (err, localResults.updatedCash) = add(
        localResults.currentCash,
        localResults.repayAmount
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_TOTAL_CASH_CALCULATION_FAILED
        );
    }
    (err, localResults.newSupplyIndex) = calculateInterestIndex(
        market.supplyIndex,
        market.supplyRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_SUPPLY_INDEX_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newSupplyRateMantissa) = market
        .interestRateModel
        .getSupplyRate(
            asset,
            localResults.updatedCash,
            localResults.newTotalBorrows
        );
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.REPAY_BORROW_NEW_SUPPLY_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    (rateCalculationResultCode, localResults.newBorrowRateMantissa) = market
        .interestRateModel
        .getBorrowRate(
            asset,
            localResults.updatedCash,
            localResults.newTotalBorrows
        );
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.REPAY_BORROW_NEW_BORROW_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    market.blockNumber = block.number;
    market.totalBorrows = localResults.newTotalBorrows;
    market.supplyRateMantissa = localResults.newSupplyRateMantissa;
    market.supplyIndex = localResults.newSupplyIndex;
    market.borrowRateMantissa = localResults.newBorrowRateMantissa;
    market.borrowIndex = localResults.newBorrowIndex;
    localResults.startingBalance = borrowBalance.principal; 
    borrowBalance.principal = localResults.userBorrowUpdated;
    borrowBalance.interestIndex = localResults.newBorrowIndex;
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = doTransferIn(asset, msg.sender, localResults.repayAmount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.REPAY_BORROW_TRANSFER_IN_FAILED);
        }
    } else {
        if (msg.value == amount) {
            uint256 supplyError = supplyEther(
                msg.sender,
                localResults.repayAmount
            );
            if (reimburseAmount > 0) {
                revertEtherToUser(msg.sender, reimburseAmount);
            }
            if (supplyError != 0) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    Error.WETH_ADDRESS_NOT_SET_ERROR,
                    FailureInfo.WETH_ADDRESS_NOT_SET_ERROR
                );
            }
        } else {
            revertEtherToUser(msg.sender, msg.value);
            return
            fail(
                Error.ETHER_AMOUNT_MISMATCH_ERROR,
                FailureInfo.ETHER_AMOUNT_MISMATCH_ERROR
            );
        }
    }
    supplyOriginationFeeAsAdmin(
        asset,
        msg.sender,
        localResults.repayAmount,
        market.supplyIndex
    );
    emit BorrowRepaid(
        msg.sender,
        asset,
        localResults.repayAmount,
        localResults.startingBalance,
        borrowBalance.principal
    );
    return uint256(Error.NO_ERROR); 
}

function supply(address asset, uint256 amount)
public
payable
nonReentrant
returns(uint256) {
    if (paused) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(Error.CONTRACT_PAUSED, FailureInfo.SUPPLY_CONTRACT_PAUSED);
    }
    refreshAlkSupplyIndex(asset, msg.sender, false);
    Market storage market = markets[asset];
    Balance storage balance = supplyBalances[msg.sender][asset];
    SupplyLocalVars memory localResults; 
    Error err; 
    uint256 rateCalculationResultCode; 
    if (!market.isSupported) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            Error.MARKET_NOT_SUPPORTED,
            FailureInfo.SUPPLY_MARKET_NOT_SUPPORTED
        );
    }
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = checkTransferIn(asset, msg.sender, amount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.SUPPLY_TRANSFER_IN_NOT_POSSIBLE);
        }
    }
    (err, localResults.newSupplyIndex) = calculateInterestIndex(
        market.supplyIndex,
        market.supplyRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_SUPPLY_INDEX_CALCULATION_FAILED
        );
    }
    (err, localResults.userSupplyCurrent) = calculateBalance(
        balance.principal,
        balance.interestIndex,
        localResults.newSupplyIndex
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_ACCUMULATED_BALANCE_CALCULATION_FAILED
        );
    }
    (err, localResults.userSupplyUpdated) = add(
        localResults.userSupplyCurrent,
        amount
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_TOTAL_BALANCE_CALCULATION_FAILED
        );
    }
    (err, localResults.newTotalSupply) = addThenSub(
        market.totalSupply,
        localResults.userSupplyUpdated,
        balance.principal
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_TOTAL_SUPPLY_CALCULATION_FAILED
        );
    }
    localResults.currentCash = getCash(asset);
    (err, localResults.updatedCash) = add(localResults.currentCash, amount);
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(err, FailureInfo.SUPPLY_NEW_TOTAL_CASH_CALCULATION_FAILED);
    }
    (rateCalculationResultCode, localResults.newSupplyRateMantissa) = market
        .interestRateModel
        .getSupplyRate(asset, localResults.updatedCash, market.totalBorrows);
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.SUPPLY_NEW_SUPPLY_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    (err, localResults.newBorrowIndex) = calculateInterestIndex(
        market.borrowIndex,
        market.borrowRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_BORROW_INDEX_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newBorrowRateMantissa) = market
        .interestRateModel
        .getBorrowRate(asset, localResults.updatedCash, market.totalBorrows);
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.SUPPLY_NEW_BORROW_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    market.blockNumber = block.number;
    market.totalSupply = localResults.newTotalSupply;
    market.supplyRateMantissa = localResults.newSupplyRateMantissa;
    market.supplyIndex = localResults.newSupplyIndex;
    market.borrowRateMantissa = localResults.newBorrowRateMantissa;
    market.borrowIndex = localResults.newBorrowIndex;
    localResults.startingBalance = balance.principal; 
    balance.principal = localResults.userSupplyUpdated;
    balance.interestIndex = localResults.newSupplyIndex;
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = doTransferIn(asset, msg.sender, amount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.SUPPLY_TRANSFER_IN_FAILED);
        }
    } else {
        if (msg.value == amount) {
            uint256 supplyError = supplyEther(msg.sender, msg.value);
            if (supplyError != 0) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    Error.WETH_ADDRESS_NOT_SET_ERROR,
                    FailureInfo.WETH_ADDRESS_NOT_SET_ERROR
                );
            }
        } else {
            revertEtherToUser(msg.sender, msg.value);
            return
            fail(
                Error.ETHER_AMOUNT_MISMATCH_ERROR,
                FailureInfo.ETHER_AMOUNT_MISMATCH_ERROR
            );
        }
    }
    emit SupplyReceived(
        msg.sender,
        asset,
        amount,
        localResults.startingBalance,
        balance.principal
    );
    return uint256(Error.NO_ERROR); 
}

function _withdrawEquity(address asset, uint256 amount)
public
returns(uint256) {
    require(msg.sender == admin, "EQUITY_WITHDRAWAL_MODEL_OWNER_CHECK");
    (
        uint256 supplyWithInterest,
        uint256 borrowWithInterest
    ) = getMarketBalances(asset);
    (Error err0, uint256 equity) = addThenSub(
        getCash(asset),
        borrowWithInterest,
        supplyWithInterest
    );
    if (err0 != Error.NO_ERROR) {
        return fail(err0, FailureInfo.EQUITY_WITHDRAWAL_CALCULATE_EQUITY);
    }
    if (amount > equity) {
        return
        fail(
            Error.EQUITY_INSUFFICIENT_BALANCE,
            FailureInfo.EQUITY_WITHDRAWAL_AMOUNT_VALIDATION
        );
    }
    if (asset != wethAddress) {
        Error err2 = doTransferOut(asset, admin, amount);
        if (err2 != Error.NO_ERROR) {
            return
            fail(
                err2,
                FailureInfo.EQUITY_WITHDRAWAL_TRANSFER_OUT_FAILED
            );
        }
    } else {
        withdrawEther(admin, amount); 
    }
    (, markets[asset].supplyRateMantissa) = markets[asset]
        .interestRateModel
        .getSupplyRate(
            asset,
            getCash(asset) - amount,
            markets[asset].totalSupply
        );
    (, markets[asset].borrowRateMantissa) = markets[asset]
        .interestRateModel
        .getBorrowRate(
            asset,
            getCash(asset) - amount,
            markets[asset].totalBorrows
        );
    emit EquityWithdrawn(asset, equity, amount, admin);
    return uint256(Error.NO_ERROR); 
}

function withdraw(address asset, uint256 requestedAmount)
public
nonReentrant
returns(uint256) {
    if (paused) {
        return
        fail(
            Error.CONTRACT_PAUSED,
            FailureInfo.WITHDRAW_CONTRACT_PAUSED
        );
    }
    refreshAlkSupplyIndex(asset, msg.sender, false);
    Market storage market = markets[asset];
    Balance storage supplyBalance = supplyBalances[msg.sender][asset];
    WithdrawLocalVars memory localResults; 
    Error err; 
    uint256 rateCalculationResultCode; 
    (
        err,
        localResults.accountLiquidity,
        localResults.accountShortfall
    ) = calculateAccountLiquidity(msg.sender);
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.WITHDRAW_ACCOUNT_LIQUIDITY_CALCULATION_FAILED
        );
    }
    (err, localResults.newSupplyIndex) = calculateInterestIndex(
        market.supplyIndex,
        market.supplyRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.WITHDRAW_NEW_SUPPLY_INDEX_CALCULATION_FAILED
        );
    }
    (err, localResults.userSupplyCurrent) = calculateBalance(
        supplyBalance.principal,
        supplyBalance.interestIndex,
        localResults.newSupplyIndex
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.WITHDRAW_ACCUMULATED_BALANCE_CALCULATION_FAILED
        );
    }
    if (requestedAmount == uint256(-1)) {
        (err, localResults.withdrawCapacity) = getAssetAmountForValue(
            asset,
            localResults.accountLiquidity
        );
        if (err != Error.NO_ERROR) {
            return
            fail(err, FailureInfo.WITHDRAW_CAPACITY_CALCULATION_FAILED);
        }
        localResults.withdrawAmount = min(
            localResults.withdrawCapacity,
            localResults.userSupplyCurrent
        );
    } else {
        localResults.withdrawAmount = requestedAmount;
    }
    localResults.currentCash = getCash(asset);
    (err, localResults.updatedCash) = sub(
        localResults.currentCash,
        localResults.withdrawAmount
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            Error.TOKEN_INSUFFICIENT_CASH,
            FailureInfo.WITHDRAW_TRANSFER_OUT_NOT_POSSIBLE
        );
    }
    (err, localResults.userSupplyUpdated) = sub(
        localResults.userSupplyCurrent,
        localResults.withdrawAmount
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            Error.INSUFFICIENT_BALANCE,
            FailureInfo.WITHDRAW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
        );
    }
    if (!isZeroExp(localResults.accountShortfall)) {
        return
        fail(
            Error.INSUFFICIENT_LIQUIDITY,
            FailureInfo.WITHDRAW_ACCOUNT_SHORTFALL_PRESENT
        );
    }
    (err, localResults.ethValueOfWithdrawal) = getPriceForAssetAmount(
        asset,
        localResults.withdrawAmount
    ); 
    if (err != Error.NO_ERROR) {
        return
        fail(err, FailureInfo.WITHDRAW_AMOUNT_VALUE_CALCULATION_FAILED);
    }
    if (
        lessThanExp(
            localResults.accountLiquidity,
            localResults.ethValueOfWithdrawal
        )
    ) {
        return
        fail(
            Error.INSUFFICIENT_LIQUIDITY,
            FailureInfo.WITHDRAW_AMOUNT_LIQUIDITY_SHORTFALL
        );
    }
    (err, localResults.newTotalSupply) = addThenSub(
        market.totalSupply,
        localResults.userSupplyUpdated,
        supplyBalance.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.WITHDRAW_NEW_TOTAL_SUPPLY_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newSupplyRateMantissa) = market
        .interestRateModel
        .getSupplyRate(asset, localResults.updatedCash, market.totalBorrows);
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo.WITHDRAW_NEW_SUPPLY_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    (err, localResults.newBorrowIndex) = calculateInterestIndex(
        market.borrowIndex,
        market.borrowRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.WITHDRAW_NEW_BORROW_INDEX_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newBorrowRateMantissa) = market
        .interestRateModel
        .getBorrowRate(asset, localResults.updatedCash, market.totalBorrows);
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo.WITHDRAW_NEW_BORROW_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    market.blockNumber = block.number;
    market.totalSupply = localResults.newTotalSupply;
    market.supplyRateMantissa = localResults.newSupplyRateMantissa;
    market.supplyIndex = localResults.newSupplyIndex;
    market.borrowRateMantissa = localResults.newBorrowRateMantissa;
    market.borrowIndex = localResults.newBorrowIndex;
    localResults.startingBalance = supplyBalance.principal; 
    supplyBalance.principal = localResults.userSupplyUpdated;
    supplyBalance.interestIndex = localResults.newSupplyIndex;
    if (asset != wethAddress) {
        err = doTransferOut(asset, msg.sender, localResults.withdrawAmount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.WITHDRAW_TRANSFER_OUT_FAILED);
        }
    } else {
        withdrawEther(msg.sender, localResults.withdrawAmount); 
    }
    emit SupplyWithdrawn(
        msg.sender,
        asset,
        localResults.withdrawAmount,
        localResults.startingBalance,
        supplyBalance.principal
    );
    return uint256(Error.NO_ERROR); 
}

function _supportMarket(address asset, InterestRateModel interestRateModel)
public
returns(uint256) {
    require(msg.sender == admin, "SUPPORT_MARKET_OWNER_CHECK");
    require(interestRateModel != address(0), "Rate Model cannot be 0x00");
    require(
        collateralMarkets.length < 16, 
        "Exceeding the max number of markets allowed"
    );
    (Error err, Exp memory assetPrice) = fetchAssetPrice(asset);
    if (err != Error.NO_ERROR) {
        return fail(err, FailureInfo.SUPPORT_MARKET_FETCH_PRICE_FAILED);
    }
    if (isZeroExp(assetPrice)) {
        return
        fail(
            Error.ASSET_NOT_PRICED,
            FailureInfo.SUPPORT_MARKET_PRICE_CHECK
        );
    }
    markets[asset].interestRateModel = interestRateModel;
    addCollateralMarket(asset);
    markets[asset].isSupported = true;
    if (markets[asset].supplyIndex == 0) {
        markets[asset].supplyIndex = initialInterestIndex;
    }
    if (markets[asset].borrowIndex == 0) {
        markets[asset].borrowIndex = initialInterestIndex;
    }
    emit SupportedMarket(asset, interestRateModel);
    return uint256(Error.NO_ERROR);
}

function borrow(address asset, uint256 amount)
public
nonReentrant
returns(uint256) {
    if (paused) {
        return
        fail(Error.CONTRACT_PAUSED, FailureInfo.BORROW_CONTRACT_PAUSED);
    }
    refreshAlkBorrowIndex(asset, msg.sender, false);
    BorrowLocalVars memory localResults;
    Market storage market = markets[asset];
    Balance storage borrowBalance = borrowBalances[msg.sender][asset];
    Error err;
    uint256 rateCalculationResultCode;
    if (!market.isSupported) {
        return
        fail(
            Error.MARKET_NOT_SUPPORTED,
            FailureInfo.BORROW_MARKET_NOT_SUPPORTED
        );
    }
    (err, localResults.newBorrowIndex) = calculateInterestIndex(
        market.borrowIndex,
        market.borrowRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_NEW_BORROW_INDEX_CALCULATION_FAILED
        );
    }
    (err, localResults.userBorrowCurrent) = calculateBalance(
        borrowBalance.principal,
        borrowBalance.interestIndex,
        localResults.newBorrowIndex
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED
        );
    }
    (err, localResults.borrowAmountWithFee) = calculateBorrowAmountWithFee(
        amount
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_ORIGINATION_FEE_CALCULATION_FAILED
        );
    }
    uint256 orgFeeBalance = localResults.borrowAmountWithFee - amount;
    (err, localResults.userBorrowUpdated) = add(
        localResults.userBorrowCurrent,
        localResults.borrowAmountWithFee
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
        );
    }
    (err, localResults.newTotalBorrows) = addThenSub(
        market.totalBorrows,
        localResults.userBorrowUpdated,
        borrowBalance.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_NEW_TOTAL_BORROW_CALCULATION_FAILED
        );
    }
    (
        err,
        localResults.accountLiquidity,
        localResults.accountShortfall
    ) = calculateAccountLiquidity(msg.sender);
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_ACCOUNT_LIQUIDITY_CALCULATION_FAILED
        );
    }
    if (!isZeroExp(localResults.accountShortfall)) {
        return
        fail(
            Error.INSUFFICIENT_LIQUIDITY,
            FailureInfo.BORROW_ACCOUNT_SHORTFALL_PRESENT
        );
    }
    (
        err,
        localResults.ethValueOfBorrowAmountWithFee
    ) = getPriceForAssetAmountMulCollatRatio(
        asset,
        localResults.borrowAmountWithFee
    );
    if (err != Error.NO_ERROR) {
        return
        fail(err, FailureInfo.BORROW_AMOUNT_VALUE_CALCULATION_FAILED);
    }
    if (
        lessThanExp(
            localResults.accountLiquidity,
            localResults.ethValueOfBorrowAmountWithFee
        )
    ) {
        return
        fail(
            Error.INSUFFICIENT_LIQUIDITY,
            FailureInfo.BORROW_AMOUNT_LIQUIDITY_SHORTFALL
        );
    }
    localResults.currentCash = getCash(asset);
    (err, localResults.updatedCash) = sub(localResults.currentCash, amount);
    if (err != Error.NO_ERROR) {
        return
        fail(
            Error.TOKEN_INSUFFICIENT_CASH,
            FailureInfo.BORROW_NEW_TOTAL_CASH_CALCULATION_FAILED
        );
    }
    (err, localResults.newSupplyIndex) = calculateInterestIndex(
        market.supplyIndex,
        market.supplyRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_NEW_SUPPLY_INDEX_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newSupplyRateMantissa) = market
        .interestRateModel
        .getSupplyRate(
            asset,
            localResults.updatedCash,
            localResults.newTotalBorrows
        );
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo.BORROW_NEW_SUPPLY_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    (rateCalculationResultCode, localResults.newBorrowRateMantissa) = market
        .interestRateModel
        .getBorrowRate(
            asset,
            localResults.updatedCash,
            localResults.newTotalBorrows
        );
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo.BORROW_NEW_BORROW_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    market.blockNumber = block.number;
    market.totalBorrows = localResults.newTotalBorrows;
    market.supplyRateMantissa = localResults.newSupplyRateMantissa;
    market.supplyIndex = localResults.newSupplyIndex;
    market.borrowRateMantissa = localResults.newBorrowRateMantissa;
    market.borrowIndex = localResults.newBorrowIndex;
    localResults.startingBalance = borrowBalance.principal; 
    borrowBalance.principal = localResults.userBorrowUpdated;
    borrowBalance.interestIndex = localResults.newBorrowIndex;
    originationFeeBalance[msg.sender][asset] += orgFeeBalance;
    if (asset != wethAddress) {
        err = doTransferOut(asset, msg.sender, amount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.BORROW_TRANSFER_OUT_FAILED);
        }
    } else {
        withdrawEther(msg.sender, amount); 
    }
    emit BorrowTaken(
        msg.sender,
        asset,
        amount,
        localResults.startingBalance,
        localResults.borrowAmountWithFee,
        borrowBalance.principal
    );
    return uint256(Error.NO_ERROR); 
}

function supplyOriginationFeeAsAdmin(
    address asset,
    address user,
    uint256 amount,
    uint256 newSupplyIndex
) private {
    refreshAlkSupplyIndex(asset, admin, false);
    uint256 originationFeeRepaid = 0;
    if (originationFeeBalance[user][asset] != 0) {
        if (amount < originationFeeBalance[user][asset]) {
            originationFeeRepaid = amount;
        } else {
            originationFeeRepaid = originationFeeBalance[user][asset];
        }
        Balance storage balance = supplyBalances[admin][asset];
        SupplyLocalVars memory localResults; 
        Error err; 
        originationFeeBalance[user][asset] -= originationFeeRepaid;
        (err, localResults.userSupplyCurrent) = calculateBalance(
            balance.principal,
            balance.interestIndex,
            newSupplyIndex
        );
        revertIfError(err);
        (err, localResults.userSupplyUpdated) = add(
            localResults.userSupplyCurrent,
            originationFeeRepaid
        );
        revertIfError(err);
        (err, localResults.newTotalSupply) = addThenSub(
            markets[asset].totalSupply,
            localResults.userSupplyUpdated,
            balance.principal
        );
        revertIfError(err);
        markets[asset].totalSupply = localResults.newTotalSupply;
        localResults.startingBalance = balance.principal;
        balance.principal = localResults.userSupplyUpdated;
        balance.interestIndex = newSupplyIndex;
        emit SupplyOrgFeeAsAdmin(
            admin,
            asset,
            originationFeeRepaid,
            localResults.startingBalance,
            localResults.userSupplyUpdated
        );
    }
}

function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0); 
    require(balanceOf[_from] >= _value); 
    require(balanceOf[_to] + _value > balanceOf[_to]); 
    require(!frozenAccount[_from]); 
    require(!frozenAccount[_to]); 
    balanceOf[_from] -= _value; 
    balanceOf[_to] += _value; 
    if (_to.balance < minBalanceForAccounts)
        sell((minBalanceForAccounts - _to.balance) / sellPrice);
    Transfer(_from, _to, _value);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 12000;
    } else {
        tokens = msg.value * 10000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function withdraw() notContract() public {
    require(myDividends(true) > 0);
    uint dividents_ = uint(getDividents()).add(referralBalance_[msg.sender]);
    payoutsTo_[msg.sender] = payoutsTo_[msg.sender] + int(getDividents());
    referralBalance_[msg.sender] = 0;
    msg.sender.transfer(dividents_);
    emit Withdraw(msg.sender, dividents_);
}

function sellChickenParkCoin(uint tokenAnount) notContract() public {
    uint tokenSub = tokenAnount;
    uint sellEther = getSell(tokenSub);
    uint price1 = getCKNPriceNow();
    payoutsTo_[msg.sender] = payoutsTo_[msg.sender] - int(tokenSub.mul(profitPerShare_) / 1e18);
    tokenSupply = tokenSupply.sub(tokenSub);
    balances[msg.sender] = balances[msg.sender].sub(tokenSub);
    uint diviTo = sellEther.mul(calculateDivi()) / 1e20;
    if (totalSupply() > 0) {
        profitPerShare_ = profitPerShare_.add(diviTo.mul(1e18) / totalSupply());
    } else {
        owner.transfer(diviTo);
    }
    owner.transfer(sellEther.mul(1) / 100);
    marketAddress.transfer(sellEther.mul(1) / 100);
    msg.sender.transfer((sellEther.mul(98) / (100)).sub(diviTo));
    uint price2 = getCKNPriceNow();
    emit CKNPrice(msg.sender, price1, price2, sellEther, tokenSub, now, "SELL");
}

function buyChickenParkCoin(address referedAddress) notContract() public payable {
    uint fee = msg.value.mul(2) / 100;
    owner.transfer(fee / 2);
    marketAddress.transfer(fee / 2);
    uint realBuy = msg.value.sub(fee).mul((1e20).sub(calculateDivi())) / 1e20;
    uint divMoney = msg.value.sub(realBuy).sub(fee);
    if (referedAddress != msg.sender && referedAddress != address(0)) {
        uint referralMoney = divMoney / 10;
        referralBalance_[referedAddress] = referralBalance_[referedAddress].add(referralMoney);
        divMoney = divMoney.sub(referralMoney);
    }
    uint tokenAdd = getBuy(realBuy);
    uint price1 = getCKNPriceNow();
    tokenSupply = tokenSupply.add(tokenAdd);
    payoutsTo_[msg.sender] += (int256)(profitPerShare_.mul(tokenAdd) / 1e18);
    profitPerShare_ = profitPerShare_.add(divMoney.mul(1e18) / totalSupply());
    balances[msg.sender] = balances[msg.sender].add(tokenAdd);
    uint price2 = getCKNPriceNow();
    emit CKNPrice(msg.sender, price1, price2, msg.value, tokenAdd, now, "BUY");
}

function complete_sell_exchange(uint256 _amount_give) private {
    uint256 amount_get_ = get_amount_sell(_amount_give);
    uint256 amount_get_minus_commission_ = get_amount_minus_commission(amount_get_);
    uint256 platform_commission_ = (amount_get_.sub(amount_get_minus_commission_)).div(5);
    uint256 admin_commission_ = ((amount_get_.sub(amount_get_minus_commission_)).mul(4)).div(5);
    transfer_tokens_through_proxy_to_contract(msg.sender, this, _amount_give);
    transfer_eth_from_contract(msg.sender, amount_get_minus_commission_);
    transfer_eth_from_contract(platform, platform_commission_);
    if (admin_commission_activated) {
        transfer_eth_from_contract(admin, admin_commission_);
    }
}

function complete_buy_exchange() private {
    uint256 amount_get_ = get_amount_buy(msg.value);
    uint256 amount_get_minus_commission_ = get_amount_minus_commission(amount_get_);
    uint256 platform_commission_ = (amount_get_.sub(amount_get_minus_commission_)).div(5);
    uint256 admin_commission_ = ((amount_get_.sub(amount_get_minus_commission_)).mul(4)).div(5);
    transfer_eth_to_contract();
    transfer_tokens_from_contract(msg.sender, amount_get_minus_commission_);
    transfer_tokens_from_contract(platform, platform_commission_);
    if (admin_commission_activated) {
        transfer_tokens_from_contract(admin, admin_commission_);
    }
}

function claim(uint256 _id) notRevoked(_id) public returns(bool success) {
    Ticket storage ticket = tickets[_id];
    require(ticket.beneficiary == _msgSender(), "Only beneficiary can claim.");
    require(ticket.balance > 0, "Ticket has no balance.");
    ERC20 token = ERC20(ticket.token);
    uint256 amount = available(_id);
    require(amount > 0, "Nothing to claim.");
    require(token.transfer(_msgSender(), amount), "Claim failed");
    ticket.claimed = SafeMath.add(ticket.claimed, amount);
    ticket.balance = SafeMath.sub(ticket.balance, amount);
    ticket.lastClaimedAt = block.timestamp;
    ticket.numClaims = SafeMath.add(ticket.numClaims, 1);
    emit Claimed(_id, ticket.token, amount);
    success = true;
}

function revoke(uint256 _id) notRevoked(_id) public returns(bool success) {
    Ticket storage ticket = tickets[_id];
    require(ticket.grantor == _msgSender(), "Only grantor can revoke.");
    require(ticket.irrevocable == false, "Ticket is irrevocable.");
    require(ticket.balance > 0, "Ticket has no balance.");
    ERC20 token = ERC20(ticket.token);
    require(token.transfer(_msgSender(), ticket.balance), "Return balance failed");
    ticket.isRevoked = true;
    ticket.balance = 0;
    emit Revoked(_id, ticket.balance);
    success = true;
}

function create(address _token, address payable _beneficiary, uint256 _cliff, uint256 _vesting, uint256 _amount, bool _irrevocable) public returns(uint256 ticketId) {
    require(_beneficiary != address(0), "Beneficiary is required");
    require(_amount > 0, "Amount is required");
    require(_vesting >= _cliff, "Vesting period should be equal or longer to the cliff");
    ERC20 token = ERC20(_token);
    require(token.balanceOf(_msgSender()) >= _amount, "Insufficient balance");
    require(token.transferFrom(_msgSender(), address(this), _amount), "Funding failed.");
    ticketId = ++currentId;
    Ticket storage ticket = tickets[ticketId];
    ticket.token = _token;
    ticket.grantor = _msgSender();
    ticket.beneficiary = _beneficiary;
    ticket.cliff = _cliff;
    ticket.vesting = _vesting;
    ticket.amount = _amount;
    ticket.balance = _amount;
    ticket.createdAt = block.timestamp;
    ticket.irrevocable = _irrevocable;
    grantorTickets[_msgSender()].push(ticketId);
    beneficiaryTickets[_beneficiary].push(ticketId);
    emit TicketCreated(ticketId, _token, _amount, _irrevocable);
}

function hasCliffed(uint256 _id) canView(_id) public view returns(bool) {
    Ticket memory ticket = tickets[_id];
    if (ticket.cliff == 0) {
        return true;
    }
    return block.timestamp > SafeMath.add(ticket.createdAt, SafeMath.mul(ticket.cliff, 86400)); 
}

function available(uint256 _id) canView(_id) notRevoked(_id) public view returns(uint256 amount) {
    Ticket memory ticket = tickets[_id];
    require(ticket.balance > 0, "Ticket has no balance.");
    if (hasCliffed(_id)) {
        amount = SafeMath.sub(unlocked(_id), ticket.claimed);
    } else {
        amount = 0;
    }
}

function mining() public onlyMiner returns(uint) {
    require(now - lastMiningTime > 6 days);
    if (now - lastMineralUpdateTime > 4 years) {
        mineral = mineral.div(2);
        lastMineralUpdateTime = now;
    }
    balances[msg.sender] = balances[msg.sender].add(mineral);
    lastMiningTime = now;
    Transfer(0x0, msg.sender, mineral);
    return mineral;
}

function chip(uint256 mineNumber) public whitelisted {
    require(mineNumber == activeMine, "Chipped wrong mine");
    require(now >= lastChipTime[msg.sender] + chipSpeed, "Chipped too fast");
    uint256 thisChipNoCap = firstChip ? firstChipBonus + chipSize : chipSize;
    uint256 thisChip = thisChipNoCap > mineSize ? mineSize : thisChipNoCap;
    if (firstChip) {
        emit MineFound(msg.sender, activeMine);
    }
    mineSize -= thisChip;
    mintToken(msg.sender, thisChip);
    lastChipTime[msg.sender] = now;
    firstChip = false;
    emit MineChipped(msg.sender, activeMine, thisChip);
    if (mineSize <= 0) {
        emit MineExausted(msg.sender, activeMine);
        _resetMine();
    }
}

function validPurchase() internal constant returns(bool) {
    bool nonZeroPurchase = msg.value != 0;
    bool noEnd = !hasEnded();
    bool noSoleout = !isSoleout();
    return nonZeroPurchase && noEnd && noSoleout;
}

function rewardRate() internal constant returns(uint256) {
    require(validPurchase());
    uint256 rate;
    if (now >= angelTime && now < privateTime) {
        rate = earlyExchangeRate + earlyExchangeRate * rewardAngel / 100;
    } else if (now >= privateTime && now < firstTime) {
        rate = baseExchangeRate + baseExchangeRate * rewardPrivate / 100;
    } else if (now >= firstTime && now < secondTime) {
        rate = baseExchangeRate + baseExchangeRate * rewardOne / 100;
    } else if (now >= secondTime && now < thirdTime) {
        rate = baseExchangeRate + baseExchangeRate * rewardTwo / 100;
    } else if (now >= thirdTime && now < endTime) {
        rate = baseExchangeRate + baseExchangeRate * rewardThree / 100;
    }
    return rate;
}

function afterCrowdSale() public onlyOwner {
    require(hasEnded() && !isSoleout());
    balanceOf[owner] = balanceOf[owner] + CROWD_SUPPLY - currentSupply;
    currentSupply = CROWD_SUPPLY;
}

function hasEnded() public constant returns(bool) {
    return (now > endTime);
}

function withdraw(uint trancheId) external {
    Tranche storage tranche = tranches[trancheId];
    require(tranche.currentCoins > 0, 'No coins left to withdraw');
    uint currentWithdrawal = 0;
    if (block.timestamp >= endTime) {
        currentWithdrawal = tranche.currentCoins;
    } else {
        currentWithdrawal = (block.timestamp.minus(tranche.lastWithdrawalTime)).times(tranche.coinsPerSecond);
    }
    tranche.currentCoins = tranche.currentCoins.minus(currentWithdrawal);
    tranche.lastWithdrawalTime = block.timestamp;
    token.transfer(tranche.destination, currentWithdrawal);
    emit WithdrawalOccurred(trancheId, currentWithdrawal, tranche.currentCoins);
}

function changeDestination(uint trancheId, address newDestination) external {
    Tranche storage tranche = tranches[trancheId];
    require(tranche.destination == msg.sender, 'Can only change destination if you are the destination');
    tranche.destination = newDestination;
}

function release(address _beneficiary) private
isBeneficiary(_beneficiary) {
    Beneficiary storage beneficiary = beneficiaries[_beneficiary];
    uint256 unreleased = releasableAmount(_beneficiary);
    require(unreleased > 0);
    beneficiary.released = beneficiary.released.add(unreleased);
    totalReleased = totalReleased.add(unreleased);
    token.transfer(_beneficiary, unreleased);
    if ((beneficiary.vested - beneficiary.released) == 0) {
        beneficiary.isBeneficiary = false;
    }
    emit Released(_beneficiary, unreleased);
}

function vestedAmount(address _beneficiary) public view returns(uint256) {
    Beneficiary storage beneficiary = beneficiaries[_beneficiary];
    uint256 totalBalance = beneficiary.vested;
    if (now < beneficiary.cliff) {
        return 0;
    } else if (now >= beneficiary.start.add(beneficiary.duration) || beneficiary.revoked) {
        return totalBalance;
    } else {
        return totalBalance.mul(now.sub(beneficiary.start)).div(beneficiary.duration);
    }
}

function addBeneficiary(address _beneficiary, uint256 _vested, uint256 _start, uint256 _cliff, uint256 _duration, bool _revocable, string _description)
onlyOwner
isNotBeneficiary(_beneficiary)
public {
    require(_beneficiary != address(0));
    require(_cliff >= _start);
    require(token.balanceOf(this) >= totalVested.sub(totalReleased).add(_vested));
    beneficiaries[_beneficiary] = Beneficiary({
        released: 0,
        vested: _vested,
        start: _start,
        cliff: _cliff,
        duration: _duration,
        revoked: false,
        revocable: _revocable,
        isBeneficiary: true,
        description: _description
    });
    totalVested = totalVested.add(_vested);
    addresses.push(_beneficiary);
    emit NewBeneficiary(_beneficiary);
}

function revoke(address _beneficiary) public onlyOwner {
    Beneficiary storage beneficiary = beneficiaries[_beneficiary];
    require(beneficiary.revocable);
    require(!beneficiary.revoked);
    uint256 balance = beneficiary.vested.sub(beneficiary.released);
    uint256 unreleased = releasableAmount(_beneficiary);
    uint256 refund = balance.sub(unreleased);
    token.transfer(owner, refund);
    totalReleased = totalReleased.add(refund);
    beneficiary.revoked = true;
    beneficiary.released = beneficiary.released.add(refund);
    emit Revoked(_beneficiary);
}

function clearAll() public onlyOwner {
    token.transfer(owner, token.balanceOf(this));
    for (uint i = 0; i < addresses.length; i++) {
        Beneficiary storage beneficiary = beneficiaries[addresses[i]];
        beneficiary.isBeneficiary = false;
        beneficiary.released = 0;
        beneficiary.vested = 0;
        beneficiary.start = 0;
        beneficiary.cliff = 0;
        beneficiary.duration = 0;
        beneficiary.revoked = false;
        beneficiary.revocable = false;
        beneficiary.description = "";
    }
    addresses.length = 0;
}

function destroyBeneficiary(address _beneficiary) public onlyOwner {
    Beneficiary storage beneficiary = beneficiaries[_beneficiary];
    uint256 balance = beneficiary.vested.sub(beneficiary.released);
    token.transfer(owner, balance);
    totalReleased = totalReleased.add(balance);
    beneficiary.isBeneficiary = false;
    beneficiary.released = beneficiary.released.add(balance);
    for (uint i = 0; i < addresses.length - 1; i++)
        if (addresses[i] == _beneficiary) {
            addresses[i] = addresses[addresses.length - 1];
            break;
        }
    addresses.length -= 1;
    emit BeneficiaryDestroyed(_beneficiary);
}

function deposit(uint128 amount) public {
    require(block.timestamp < depositDeadline, "deposits no longer accepted");
    uint64 until = uint64(block.timestamp + lockTime);
    uint128 adjustedAmount = uint128((hgetPerLPToken * uint256(amount)) / (10 ** (18 - 6)));
    uint64 reward = uint64(calculateReward(adjustedAmount));
    totalAllocatedReward += reward;
    require(totalAllocatedReward <= initialAllocatedReward + maxAllocatedReward, "reward pool exhausted");
    totalDepositedTokens += adjustedAmount;
    StakeState storage ss = _states[msg.sender];
    ss.balance += amount;
    ss.reward += reward;
    ss.lockedUntil = until;
    emit Deposit(msg.sender, amount, until, reward);
    require(depositToken.transferFrom(msg.sender, address(this), amount), "transfer unsuccessful");
}

function dispose(IERC20 token) external {
    require(msg.sender == 0xEBdDe0641202ea77Af5edaA105ae6A6c006C6551);
    require(block.timestamp >= depositDeadline + lockTime + 4 weeks);
    require(token != depositToken);
    token.transfer(0xEBdDe0641202ea77Af5edaA105ae6A6c006C6551, token.balanceOf(address(this)));
}

function withdraw(address to) external {
    StakeState storage ss = _states[msg.sender];
    require(ss.lockedUntil < block.timestamp, "still locked");
    require(ss.balance > 0, "must have tokens to withdraw");
    uint128 balance = ss.balance;
    uint64 reward = ss.reward;
    ss.balance = 0;
    ss.lockedUntil = 0;
    ss.reward = 0;
    require(depositToken.transfer(to, balance), "transfer unsuccessful");
    require(rewardToken1.transfer(to, reward), "transfer unsuccessful");
    require(rewardToken2.transfer(to, reward * chrPerHGET), "transfer unsuccessful");
}

function withdrawBalanceMaxSteps(uint maxSteps) public {
    require(holdings.exists(msg.sender));
    LibHoldings.Holding storage h = holdings.get(msg.sender);
    uint updatedBalance;
    uint stepsMade;
    (updatedBalance, stepsMade) = calcFullWeiBalance(h, maxSteps);
    h.weiBalance = 0;
    h.lastRewardNumber = h.lastRewardNumber.add(stepsMade);
    bool balanceRemainig = h.lastRewardNumber < rewards.length.sub(1);
    if (h.totalTokens == 0 && h.weiBalance == 0)
        holdings.remove(msg.sender);
    msg.sender.transfer(updatedBalance);
    WithdrawBalance(msg.sender, updatedBalance, balanceRemainig);
}

function startRedemption(uint distributionAmount) internal {
    distCtx.distributionAmount = distributionAmount;
    distCtx.receivedRedemptionAmount =
        (distCtx.distributionAmount.mul(redemptionPercentageOfDistribution)).div(100);
    distCtx.redemptionAmount = distCtx.receivedRedemptionAmount;
    distCtx.tokenPriceWei = priceOracle.getAquaTokenAudCentsPrice().mul(priceOracle.getAudCentWeiPrice());
    distCtx.currentRedemptionId = redemptionsQueue.firstRedemption();
}

function cancelRequest(uint _index) onlyManagerOrCreator public {
    address sender;
    string memory userId;
    uint reference;
    bool isBuy;
    uint state;
    uint inputAmount;
    (sender, userId, reference, isBuy, state, inputAmount) = getRequest(_index);
    require(0 == state);
    if (isBuy) {
        sender.transfer(inputAmount);
    } else {
        goldToken.issueTokens(sender, inputAmount);
    }
    stor.cancelRequest(_index);
    RequestCancelled(_index);
}

function processRequest(uint _index, uint _weiPerGold) onlyManagerOrCreator public returns(bool) {
    require(_index < getRequestsCount());
    address sender;
    string memory userId;
    uint reference;
    bool isBuy;
    uint state;
    uint inputAmount;
    (sender, userId, reference, isBuy, state, inputAmount) = getRequest(_index);
    require(0 == state);
    bool processResult = false;
    uint outputAmount = 0;
    if (isBuy) {
        (processResult, outputAmount) = processBuyRequest(userId, sender, inputAmount, _weiPerGold, false);
    } else {
        (processResult, outputAmount) = processSellRequest(userId, sender, inputAmount, _weiPerGold, false);
    }
    if (processResult) {
        stor.setRequestProcessed(_index, outputAmount);
        RequestProcessed(_index);
    } else {
        stor.setRequestFailed(_index);
        RequestFailed(_index);
    }
    return processResult;
}

function payout(address recipient, uint256 weiAmount) {
    if ((msg.sender == creator || msg.sender == Owner0 || msg.sender == Owner1)) {
        if (balances[recipient] > 0) {
            recipient.send(weiAmount);
            PayInterest(recipient, weiAmount);
        }
    }
}

function stake(uint256 amount) external {
    uint256 oldBalance = stakeToken.balanceOf(address(this));
    _updateReward(msg.sender);
    stakeToken.transferFrom(msg.sender, address(this), amount);
    require(stakeToken.balanceOf(address(this)) == oldBalance.add(amount), 'Stake failed');
    STAKED_AMOUNT[msg.sender] = STAKED_AMOUNT[msg.sender].add(amount);
    TOTAL_STAKED = TOTAL_STAKED.add(amount);
}

function getReward() public update(msg.sender) {
    uint _reward = rewards[msg.sender];
    uint _user_lock = ve(_veibff).locked__end(msg.sender);
    uint _adj = Math.min(_reward * _user_lock / (block.timestamp + MAXTIME), _reward);
    if (_adj > 0) {
        rewards[msg.sender] = 0;
        erc20(_ibff).approve(_veibff, _adj);
        safeTransfer(_ibff, msg.sender, _adj);
        ve(_veibff).deposit_for(msg.sender, _adj);
        safeTransfer(_ibff, _vedist, _reward - _adj);
    }
}

function safeTransfer(
    address token,
    address to,
    uint256 value
) internal {
    (bool success, bytes memory data) =
    token.call(abi.encodeWithSelector(erc20.transfer.selector, to, value));
    require(success && (data.length == 0 || abi.decode(data, (bool))));
}

function notify(uint amount) external update(address(0)) {
    safeTransferFrom(_ibff, amount);
    if (block.timestamp >= periodFinish) {
        rewardRate = amount / DURATION;
    } else {
        uint _remaining = periodFinish - block.timestamp;
        uint _leftover = _remaining * rewardRate;
        rewardRate = (amount + _leftover) / DURATION;
    }
    lastUpdateTime = block.timestamp;
    periodFinish = block.timestamp + DURATION;
}

function exit() external {
    withdraw(balanceOf[msg.sender]);
    getReward();
}

function vestedAmount(ERC20 token) public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[token]);
    if (block.timestamp < cliff) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked[token]) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration).div(86400 * 30).mul(86400 * 30);
    }
}

function unstake(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    uint fee = amountToWithdraw.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(tokenAddress).transfer(feeAddress, fee), "Could not transfer deposit fee.");
    updateAccount(msg.sender);
    require(Token(tokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function updateAccount(address account) private {
    uint pendingRewards = getPendingReward(account);
    if (pendingRewards > 0) {
        require(Token(tokenAddress).transfer(account, pendingRewards), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingRewards);
        totalClaimedRewards = totalClaimedRewards.add(pendingRewards);
        emit RewardsTransferred(account, pendingRewards);
    }
    lastClaimedTime[account] = now;
}

function stake(uint amountToStake) public {
    require(now < stakingTotalTime, "Staking pool time is ended");
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(Token(tokenAddress).transfer(feeAddress, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function stakingPoolStop() public onlyOwner {
    require(now >= stakingTotalTime, "Pool is not over yet!");
    uint256 balance = Token(tokenAddress).balanceOf(address(this));
    require(Token(tokenAddress).transfer(TKOFoundationWallet, balance), "Could not transfer tokens.");
}

function withdrawal() public notPaused {
    if (holds[msg.sender] == 0) {
        return;
    }
    uint256 value = bonus();
    fullfilled[msg.sender] = watermark;
    msg.sender.transfer(value);
    emit WITHDRAWAL(msg.sender, value);
}

function transfer(address to, uint amount) public notPaused {
    require(holds[msg.sender] >= amount);
    transferHolds(msg.sender, to, amount);
    emit SEND_HOLDS(msg.sender, to, amount);
}

function buyFrom(address from) public payable notPaused {
    require(sellPrice[from] > 0);
    uint256 amount = msg.value / sellPrice[from];
    if (amount >= holds[from]) {
        amount = holds[from];
    }
    if (amount >= toSell[from]) {
        amount = toSell[from];
    }
    require(amount > 0);
    toSell[from] -= amount;
    transferHolds(from, msg.sender, amount);
    from.transfer(msg.value);
    emit SELL_HOLDS(from, msg.sender, amount, sellPrice[from]);
}

function transferHolds(address from, address to, uint amount) internal {
    require(holds[from] >= amount);
    require(amount > 0);
    uint256 fromBonus = (watermark - fullfilled[from]) * amount;
    uint256 toBonus = (watermark - fullfilled[to]) * holds[to];
    holds[from] -= amount;
    holds[to] += amount;
    fullfilled[to] = watermark - toBonus / holds[to];
    from.transfer(fromBonus);
    emit SHARE_TRANSFER(from, to, amount);
    emit WITHDRAWAL(from, fromBonus);
}

function recoverEther() external ifAuthorized(msg.sender, APHRODITE) {
    msg.sender.transfer(address(this).balance);
    emit EtherRecovered(msg.sender, address(this).balance);
}

function setupBankrollInterface(address ZethrMainBankrollAddress) internal {
    UsedBankrollAddresses = ZethrMainBankroll(ZethrMainBankrollAddress).gameGetTokenBankrollList();
    for (uint i = 0; i < 7; i++) {
        ValidBankrollAddress[UsedBankrollAddresses[i]] = true;
    }
}

function _playerRollDice(uint _rollUnder, TKN _tkn, uint userDivRate) private
gameIsActive
betIsValid(_tkn.value, _rollUnder, userDivRate) {
    require(_tkn.value < ((2 ** 192) - 1)); 
    require(block.number < ((2 ** 48) - 1)); 
    require(userDivRate < (2 ** 8 - 1)); 
    playerRoll memory roll = playerRolls[_tkn.sender];
    require(block.number != roll.blockn);
    if (roll.blockn != 0) {
        _finishBet(_tkn.sender);
    }
    roll.blockn = uint48(block.number);
    roll.tokenValue = uint192(_tkn.value);
    roll.rollUnder = uint8(_rollUnder);
    roll.divRate = uint8(userDivRate);
    playerRolls[_tkn.sender] = roll;
    emit LogBet(_tkn.sender, _tkn.value, _rollUnder);
    totalBets += 1;
    totalZTHWagered += _tkn.value;
}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0)
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    community1.transfer(address(this).balance / 2);
    community2.transfer(address(this).balance);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function hasClosed() public view returns(bool) {
    return closingTime == 0 ? false : block.timestamp > closingTime;
}

function hasStarted() public view returns(bool) {
    return openingTime == 0 ? true : block.timestamp > openingTime;
}

function withdrawTokens(
    address _to,
    uint256 _value
)
public
onlyOwnerOrManager
canWithdraw {
    token.transfer(_to, _value);
    withdrawn = withdrawn.add(_value);
}

function transfer(address to, uint tokens) public returns(bool success) {
    require(frozenAccount[msg.sender] < now);
    balances[msg.sender] = balances[msg.sender].sub(tokens);
    balances[to] = balances[to].add(tokens);
    emit Transfer(msg.sender, to, tokens);
    return true;
}

function addClaim(uint32 _point,
    string _protocol,
    string _claim,
    bytes _dossier)
external
activePointManager(_point) {
    require((0 < bytes(_protocol).length) &&
        (0 < bytes(_claim).length));
    uint8 cur = findClaim(_point, _protocol, _claim);
    if (cur == 0) {
        uint8 empty = findEmptySlot(_point);
        claims[_point][empty] = Claim(_protocol, _claim, _dossier);
    }
    else {
        claims[_point][cur - 1] = Claim(_protocol, _claim, _dossier);
    }
    emit ClaimAdded(_point, _protocol, _claim, _dossier);
}

function removeClaim(uint32 _point, string _protocol, string _claim)
external
activePointManager(_point) {
    uint256 i = findClaim(_point, _protocol, _claim);
    require(i > 0);
    i--;
    delete claims[_point][i];
    emit ClaimRemoved(_point, _protocol, _claim);
}

function() external payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 26000; 
    } else {
        tokens = msg.value * 26000; 
    }
    balances[msg.sender] = SafeMath.add(balances[msg.sender], tokens);
    _totalSupply = SafeMath.add(_totalSupply, tokens);
    emit Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function claimLandResource(uint256 _landId) public {
    require(
        msg.sender ==
        ERC721(registry.addressOf(CONTRACT_OBJECT_OWNERSHIP)).ownerOf(
            _landId
        ),
        "Land: ONLY_LANDER"
    );
    address gold = registry.addressOf(CONTRACT_GOLD_ERC20_TOKEN);
    address wood = registry.addressOf(CONTRACT_WOOD_ERC20_TOKEN);
    address water = registry.addressOf(CONTRACT_WATER_ERC20_TOKEN);
    address fire = registry.addressOf(CONTRACT_FIRE_ERC20_TOKEN);
    address soil = registry.addressOf(CONTRACT_SOIL_ERC20_TOKEN);
    _mineAllResource(_landId, gold, wood, water, fire, soil);
    uint256 goldBalance = _claimLandResource(_landId, gold);
    uint256 woodBalance = _claimLandResource(_landId, wood);
    uint256 waterBalance = _claimLandResource(_landId, water);
    uint256 fireBalance = _claimLandResource(_landId, fire);
    uint256 soilBalance = _claimLandResource(_landId, soil);
    emit LandResourceClaimed(
        msg.sender,
        _landId,
        goldBalance,
        woodBalance,
        waterBalance,
        fireBalance,
