function finishDeal(uint _dealNumber) public {
    uint deal = dealNumbers[_dealNumber];
    require(deals[deal].balance > 0 && deals[deal].status == statuses.signed);
    if (msg.sender == deals[deal].buyer) {
        signs[deal].finishSignBuyer = msg.sender;
    }
    if (msg.sender == deals[deal].seller) {
        signs[deal].finishSignSeller = msg.sender;
    }
    if (msg.sender == deals[deal].signer) {
        signs[deal].finishSignSigner = msg.sender;
    }
    uint signCount = 0;
    if (deals[deal].buyer == signs[deal].finishSignBuyer) {
        signCount++;
    }
    if (deals[deal].seller == signs[deal].finishSignSeller) {
        signCount++;
    }
    if (deals[deal].signer == signs[deal].finishSignSigner) {
        signCount++;
    }
    if (signCount >= 2) {
        deals[deal].seller.transfer(deals[deal].sum - deals[deal].fee);
        emit MoneyTransfer(this, deals[deal].seller, deals[deal].sum - deals[deal].fee);
        agencyReceiver.transfer(deals[deal].fee);
        emit MoneyTransfer(this, agencyReceiver, deals[deal].fee);
        deals[deal].balance = 0;
        deals[deal].status = statuses.finished;
        deals[deal].atClosed = now;
    }
}

function cancelDeal(uint _dealNumber) onlySigner(_dealNumber) public {
    uint deal = dealNumbers[_dealNumber];
    require(deals[deal].balance > 0 && deals[deal].status == statuses.signed);
    deals[deal].buyer.transfer(deals[deal].balance);
    deals[deal].balance = 0;
    deals[deal].status = statuses.canceled;
    deals[deal].atClosed = now;
}

function sendFeeToWallet(address wallet, address reserve) public {
    uint feeAmount = reserveFeeToWallet[reserve][wallet];
    require(feeAmount > 1);
    reserveFeeToWallet[reserve][wallet] = 1; 
    require(knc.transferFrom(reserveKNCWallet[reserve], wallet, feeAmount - 1));
    feePayedPerReserve[reserve] += (feeAmount - 1);
    SendWalletFees(wallet, reserve, msg.sender);
}

function burnReserveFees(address reserve) public {
    uint burnAmount = reserveFeeToBurn[reserve];
    uint taxToSend = 0;
    require(burnAmount > 2);
    reserveFeeToBurn[reserve] = 1; 
    if (taxWallet != address(0) && taxFeeBps != 0) {
        taxToSend = (burnAmount - 1) * taxFeeBps / 10000;
        require(burnAmount - 1 > taxToSend);
        burnAmount -= taxToSend;
        if (taxToSend > 0) {
            require(knc.transferFrom(reserveKNCWallet[reserve], taxWallet, taxToSend));
            SendTaxFee(reserve, msg.sender, taxWallet, taxToSend);
        }
    }
    require(knc.burnFrom(reserveKNCWallet[reserve], burnAmount - 1));
    feePayedPerReserve[reserve] += (taxToSend + burnAmount - 1);
    BurnAssignedFees(reserve, msg.sender, (burnAmount - 1));
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (!_isExcludedFromFee[to] && !_isExcludedFromFee[from]) {
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to]) {
            require(tradeAllowed);
            require(cooldown[to] < block.timestamp);
            uint walletBalance = balanceOf(address(to));
            require(amount.add(walletBalance) <= _tTotal.div(20));
            require(amount <= _maxTxAmount);
            cooldown[to] = block.timestamp + (30 seconds);
            _fee = 12;
            _reflection = 3;
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        uint impactLimitFive = balanceOf(uniswapV2Pair).div(20);
        if (!inSwap && from != uniswapV2Pair && swapEnabled && !_isExcludedFromFee[to] && !_isExcludedFromFee[from]) {
            require(amount <= impactLimitFive);
            require(cooldown[from] < block.timestamp);
            uint initialBalance = address(this).balance;
            if (contractTokenBalance > impactLimitFive) {
                contractTokenBalance = impactLimitFive;
            }
            swapTokensForEth(contractTokenBalance);
            uint newBalance = address(this).balance;
            uint distributeETHBalance = newBalance.sub(initialBalance);
            if (distributeETHBalance > 0) {
                sendETHToFee(distributeETHBalance);
            }
            _fee = 17;
            _reflection = 3;
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee;
}

