function startICO(uint _startTime, uint _duration, uint _amount) external whenNotActive(currentRound) onlyMasters {
    currentRound++;
    ICO storage ico = ICORounds[currentRound];
    ico.startTime = _startTime;
    ico.finishTime = _startTime.add(_duration);
    ico.active = true;
    tokensOnSale = forceToken.balanceOf(address(this)).sub(reservedTokens);
    if (_amount > tokensOnSale) {
        require(forceToken.serviceTransfer(address(forceToken), address(this), _amount.sub(tokensOnSale)));
        tokensOnSale = _amount;
    }
    ico.tokensOnSale = tokensOnSale;
    reservedTokens = reservedTokens.add(tokensOnSale);
    emit ICOStarted(currentRound);
}

function recall() external whenActive(currentRound) duringRound(currentRound) {
    ICO storage ico = ICORounds[currentRound];
    Participant storage p = ico.participants[msg.sender];
    uint value = p.value;
    require(value > 0);
    ico.participants[ico.participantsList[ico.totalParticipants]].index = p.index;
    ico.participantsList[p.index] = ico.participantsList[ico.totalParticipants];
    delete ico.participantsList[ico.totalParticipants--];
    delete ico.participants[msg.sender];
    ico.weiRaised = ico.weiRaised.sub(value);
    reservedFunds = reservedFunds.sub(value);
    msg.sender.transfer(valueFromPercent(value, recallPercent));
    emit Recall(msg.sender, value, currentRound);
}

function withdrawFunds(address _to, uint _value) external onlyMasters {
    require(address(this).balance.sub(reservedFunds) >= _value);
    _to.transfer(_value);
    emit Withdrawal(_value);
}

function initializeCurve(
    bytes32 specifier,
    bytes32 symbol,
    int256[] curve
) public returns(address) {
    require(curves[specifier] == 0, "Curve specifier already exists");
    RegistryInterface registry = RegistryInterface(coord.getContract("REGISTRY"));
    require(registry.isProviderInitiated(address(this)), "Provider not intiialized");
    registry.initiateProviderCurve(specifier, curve, address(this));
    curves[specifier] = newToken(bytes32ToString(specifier), bytes32ToString(symbol));
    registry.setProviderParameter(specifier, toBytes(curves[specifier]));
    DotTokenCreated(curves[specifier]);
    return curves[specifier];
}

function unbond(bytes32 specifier, uint numDots) public {
    bondage = BondageInterface(coord.getContract("BONDAGE"));
    uint issued = bondage.getDotsIssued(address(this), specifier);
    currentCost = CurrentCostInterface(coord.getContract("CURRENT_COST"));
    uint reserveCost = currentCost._costOfNDots(address(this), specifier, issued + 1 - numDots, numDots - 1);
    bondage.unbond(address(this), specifier, numDots);
    FactoryTokenInterface curveToken = FactoryTokenInterface(curves[specifier]);
    curveToken.burnFrom(msg.sender, numDots);
    require(reserveToken.transfer(msg.sender, reserveCost), "Error: Transfer failed");
}

function uniswapV2Call(address _sender, uint _amount0, uint _amount1, bytes calldata _data) external {
    require(_sender == address(this), "GebUniswapV2KeeperFlashProxyETH/invalid-sender");
    require(msg.sender == address(uniswapPair), "GebUniswapV2KeeperFlashProxyETH/invalid-uniswap-pair");
    uint amount = (_amount0 == ZERO ? _amount1 : _amount0);
    coin.approve(address(coinJoin), amount);
    coinJoin.join(address(this), amount);
    (bool success, ) = address(this).call(_data);
    require(success, "GebUniswapV2KeeperFlashProxyETH/failed-bidding");
    ethJoin.exit(address(this), safeEngine.tokenCollateral(collateralType, address(this)));
    uint pairBalanceTokenBorrow = coin.balanceOf(address(uniswapPair));
    uint pairBalanceTokenPay = weth.balanceOf(address(uniswapPair));
    uint amountToRepay = addition((
        multiply(multiply(THOUSAND, pairBalanceTokenPay), amount) /
        multiply(NET_OUT_AMOUNT, pairBalanceTokenBorrow)
    ), ONE);
    require(amountToRepay <= weth.balanceOf(address(this)), "GebUniswapV2KeeperFlashProxyETH/unprofitable");
    weth.transfer(address(uniswapPair), amountToRepay);
    uint profit = weth.balanceOf(address(this));
    weth.withdraw(profit);
    caller.call {
        value: profit
    }("");
    caller = address(0x0);
}

function liquidateAndSettleSAFE(address safe) public returns(uint auction) {
    if (liquidationEngine.safeSaviours(liquidationEngine.chosenSAFESaviour(collateralType, safe)) == ONE) {
        require(liquidationEngine.chosenSAFESaviour(collateralType, safe) == address(0),
            "GebUniswapV2KeeperFlashProxyETH/safe-is-protected");
    }
    auction = liquidationEngine.liquidateSAFE(collateralType, safe);
    settleAuction(auction);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 10000;
    } else {
        tokens = msg.value * 10000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
