function BuyBSTtokens() payable {
    require(!(msg.value == 0) &&
        (isCrowdSaleSetup) &&
        (block.number >= fundingStartBlock) &&
        (block.number <= fundingEndBlock) &&
        (tokensRemaining > 0));
    uint256 rewardTransferAmount = 0;
    setPrice();
    amountRaisedInWei = safeAdd(amountRaisedInWei, msg.value);
    rewardTransferAmount = safeDiv(safeMul(msg.value, tokensPerEthPrice), 10000000000000000);
    tokensRemaining = safeSub(tokensRemaining, safeDiv(rewardTransferAmount, 100));
    tokenReward.transfer(msg.sender, rewardTransferAmount);
    fundValue[msg.sender] = safeAdd(fundValue[msg.sender], msg.value);
    Transfer(this, msg.sender, msg.value);
    Buy(msg.sender, msg.value, rewardTransferAmount);
}

function saleActive() public constant returns(bool) {
    return (getCurrentTimestamp() >= startDate &&
        getCurrentTimestamp() < endDate && supply() > 0);
}

function initialize(address _wallet, uint256 _start, uint256 _end,
    uint256 _saleCap, uint256 _totalSupply)
onlyOwner uninitialized {
    require(_start >= getCurrentTimestamp());
    require(_start < _end);
    require(_wallet != 0x0);
    require(_totalSupply > _saleCap);
    startDate = _start;
    endDate = _end;
    saleCap = _saleCap;
    wallet = _wallet;
    totalSupply = _totalSupply;
    balances[wallet] = _totalSupply.sub(saleCap);
    balances[0xb1] = saleCap;
}

function getRateAt(uint256 at) constant returns(uint256) {
    if (at < startDate) {
        return 0;
    } else if (at < (startDate + 7 days)) {
        return 840;
    } else if (at < (startDate + 37 days)) {
        return 770;
    } else if (at <= endDate) {
        return 700;
    } else {
        return 0;
    }
}

function buy(uint256 amount) public payable {
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= start, "early");
    require(amount <= supply(), "ordered too many");
    require(amount <= limitPerOrder, "ordered too many");
    require(msg.value == price.mul(amount), "wrong amount");
    nft.safeTransferFrom(address(this), msg.sender, id, amount, new bytes(0x0));
    uint256 stakingReward = (address(this).balance * stakingRewardPercentageBasisPoints) / 10000;
    (bool stakingRewardSuccess, ) = stakingSwapContract.call {
        value: stakingReward
    }("");
    require(stakingRewardSuccess, "Staking reward transfer failed.");
    (bool successMultisig, ) = hausAddress.call {
        value: address(this).balance
    }("");
    require(successMultisig, "Multisig transfer failed.");
    emit Buy(msg.sender, amount);
}

function getCurrentPhaseCloseTime() view returns(int256, int256) {
    if (now < openingTime) {
        return (int256(openingTime), -2);
    }
    for (uint i = 0; i < phases.length; i++) {
        if (now < phases[i])
            return (int256(phases[i]), int256(i));
    }
    if (now < closingTime) {
        return (int256(closingTime), -1);
    }
    return (-1, -3);
}

function airdrop(address recipient, uint256 amount) external onlyOwner() {
    removeAllFee();
    _transfer(_msgSender(), recipient, amount * 10 ** 9);
    restoreAllFee();
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (maxTXEnabled) {
        if (from != owner() && to != owner()) {
            require(amount <= _maxTxAmount, "Transfer amount exceeds the maxTxAmount.");
        }
    }
    if (antiSnipe) {
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && to != address(this)) {
            require(tx.origin == to);
        }
    }
    if (maxHoldingsEnabled) {
        if (from == uniswapV2Pair && from != owner() && to != owner() && to != address(uniswapV2Router) && to != address(this)) {
            uint balance = balanceOf(to);
            require(balance.add(amount) <= _maxHoldings);
        }
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    if (contractTokenBalance >= _maxTxAmount) {
        contractTokenBalance = _maxTxAmount;
    }
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (overMinTokenBalance && !inSwapAndLiquify && from != uniswapV2Pair && swapAndLiquifyEnabled) {
        contractTokenBalance = numTokensSellToAddToLiquidity;
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function airdropInternal(address recipient, uint256 amount) internal {
    removeAllFee();
    _transfer(_msgSender(), recipient, amount);
    restoreAllFee();
}

function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
    uint tokensForLiq = (contractTokenBalance.div(3));
    uint tokensDAFMARKDEV = contractTokenBalance.sub(tokensForLiq).sub(1);
    uint256 half = tokensForLiq.div(2);
    uint256 otherHalf = tokensForLiq.sub(half);
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(half);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    addLiquidity(otherHalf, newBalance);
    uint256 nextBalance = address(this).balance;
    swapTokensForEth(tokensDAFMARKDEV);
    uint256 newestBalance = address(this).balance.sub(nextBalance);
    uint256 DAFGOVIDO = newestBalance.mul(4).div(9);
    uint marketing = newestBalance.sub(DAFGOVIDO).mul(3).div(5);
    payable(owner()).transfer(DAFGOVIDO);
    payable(_marketingWallet).transfer(marketing);
    payable(_dWallet).transfer(address(this).balance);
    emit SwapAndLiquify(half, newBalance, otherHalf);
}

