}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = totIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = totIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 92), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        totIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 92);
    } else if (sellingPrice < secondStepLimit) {
        totIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 92);
    } else {
        totIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 92);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, totIndexToPrice[_tokenId], oldOwner, newOwner, tots[_tokenId].name);
    msg.sender.transfer(purchaseExcess);
}

function getState() public constant returns(State) {
    if (finalized)
        return State.Finalized;
    if (startsAt > now)
        return State.Preparing;
    if (now >= startsAt && now < endsAt)
        return State.Funding;
    if (isGoalReached())
        return State.Success;
    if (!isGoalReached() && this.balance > 0)
        return State.Refunding;
    return State.Failure;
}

function finalize() public inState(State.Success) stopInEmergency {
    require(msg.sender == deployAgent || msg.sender == team);
    require(!finalized);
    finalized = true;
    uint feeAmount = (this.balance * ETHERFUNDME_FEE) / 100;
    uint teamAmount = this.balance - feeAmount;
    Withdraw(team, teamAmount);
    team.transfer(teamAmount);
    Withdraw(feeReceiver, feeAmount);
    feeReceiver.transfer(feeAmount);
}

function invest() public payable stopInEmergency {
    require(getState() == State.Funding);
    require(msg.value > 0);
    uint weiAmount = msg.value;
    address investor = msg.sender;
    if (investedAmountOf[investor] == 0) {
        investorCount++;
    }
    uint onlineFeeAmount = (weiAmount * ETHERFUNDME_ONLINE_FEE) / 100;
    Withdraw(feeReceiver, onlineFeeAmount);
    feeReceiver.transfer(onlineFeeAmount);
    uint investedAmount = weiAmount - onlineFeeAmount;
    investedAmountOf[investor] += investedAmount;
    Invested(investor, investedAmount);
}

function bid() payable public {
    require(msg.value == 5000000000000000);
    if (endTime == 0) {
        endTime = (now + addTime);
    }
    if (endTime != 0 && endTime > now) {
        addTime -= (10 seconds);
        endTime = (now + addTime);
        latestBidder = msg.sender;
        Bid(latestBidder, endTime, addTime, this.balance);
    }
    if (addTime == 0 || endTime <= now) {
        latestWinner = latestBidder;
        addTime = (2 hours);
        endTime = (now + addTime);
        latestBidder = msg.sender;
        Bid(latestBidder, endTime, addTime, ((this.balance / 20) * 17) + 5000000000000000);
        owner.transfer((this.balance / 20) * 1);
        latestWinner.transfer(((this.balance - 5000000000000000) / 10) * 8);
    }
}

function vote(address tokenAddress, uint256 tokenId, address payable creator) public payable {
    require(block.number < _surveyEndBlock, "Survey ended!");
    require(_allowedVotingAmounts[msg.value] > 0, "Vote must be 0.004, 0.03, 0.1 or 0.3 ethers");
    require(_allowedTokenAddresses[tokenAddress], "Unallowed Token Address!");
    require(IERC721(tokenAddress).ownerOf(tokenId) != address(0), "Owner is nobody, maybe wrong tokenId?");
    if (_votes[tokenAddress][tokenId] == 0) {
        emit FirstVote(tokenAddress, tokenId);
    }
    _votes[tokenAddress][tokenId] = _votes[tokenAddress][tokenId] + _allowedVotingAmounts[msg.value];
    _ethers[tokenAddress][tokenId] = _ethers[tokenAddress][tokenId] + msg.value;
    creator.transfer(msg.value);
    emit Vote(msg.sender, tokenAddress, tokenId, creator, _allowedVotingAmounts[msg.value], msg.value);
}

function cashout(address winner, uint256 amount) public {
    uint256 dealerBankroll = bankrolls[msg.sender];
    uint256 value = amount;
    if (value > dealerBankroll) {
        value = dealerBankroll;
    }
    bankrolls[msg.sender] -= value;
    winner.transfer(value);
    emit Cashout(msg.sender, winner, value);
    dealerBankroll = bankrolls[msg.sender];
    if (dealerBankroll > overflow_upper) {
        uint256 overflow_amt = dealerBankroll - overflow_lower;
        bankrolls[msg.sender] -= overflow_amt;
        value = overflow_amt;
        if (msg.sender != pitboss) {
            value = overflow_amt * dealer_cut / 100;
            pitboss.transfer(overflow_amt - value);
        }
        address beneficiary = msg.sender;
        address sender_beneficiary = beneficiaries[msg.sender];
        if (sender_beneficiary > 0) {
            beneficiary = sender_beneficiary;
        }
        beneficiary.transfer(value);
        emit Overflow(msg.sender, value);
    }
}

function() public payable {
    require(fundingEnabled && (tokenPrice > 0) && (msg.value >= tokenPrice));
    totalCollected += msg.value;
    vaultAddress.transfer(msg.value);
    uint tokens = msg.value / tokenPrice;
    require((msg.sender != 0) && (msg.sender != address(this)));
    uint previousBalanceFrom = balances[this];
    require(previousBalanceFrom >= tokens);
    balances[this] = previousBalanceFrom - tokens;
    uint previousBalanceTo = balances[msg.sender];
    require(previousBalanceTo + tokens >= previousBalanceTo); 
    balances[msg.sender] = previousBalanceTo + tokens;
    emit Transfer(this, msg.sender, tokens);
    return;
}

function getTierForLastMiniting() private view returns(uint8 _tier) {
    uint256 nextTierStartTime = mintingStartTime;
    while (nextTierStartTime < lastMintingTime) {
        nextTierStartTime = nextTierStartTime.add(mintingThreshold);
        _tier++;
    }
    return _tier;
}

function currentTier() private view returns(uint8 _tier) {
    uint256 currentTime = now;
    uint256 nextTierStartTime = mintingStartTime;
    while (nextTierStartTime < currentTime) {
        nextTierStartTime = nextTierStartTime.add(mintingThreshold);
        _tier++;
    }
    return _tier;
}

