        require(sucsSlrLmt == true && sucsByrLmt == true);
    }
    uint valtmp = _value;
    uint _valueA = valtmp;
    valtmp = 0;
    allowance[msg.sender][_spender] = _valueA;
    Approval(msg.sender, _spender, _valueA);
