function withdraw(address _token, bool _rewardOnly) external contractAlive nonReentrant returns(bool) {
    require(entryBlock[msg.sender][_token] > 0, "NO_TOKEN_DEPOSIT");
    require(entryBlock[msg.sender][_token] != block.number);
    require(rewards[_token] > 0, "NO_REWARD_OFFERED_FOR_TOKEN");
    uint256 rewardAmount = block.number.sub(entryBlock[msg.sender][_token]).mul(rewards[_token]).mul(balance[msg.sender][_token]).div(totalValue[_token]);
    require(IERC20(rewardToken).balanceOf(address(this)) > rewardAmount, "NOT_ENOUGH_REWARD_TOKEN_USE_EMERGENCY_WITHDRAW");
    require(rewardAmount > 0, "NO_REWARDS_FOR_ADDRESS");
    if (!_rewardOnly) {
        require(balance[msg.sender][_token] > 0);
        IERC20(_token).transfer(msg.sender, balance[msg.sender][_token]);
        totalHolders[_token] = totalHolders[_token].sub(1);
        totalValue[_token] = totalValue[_token].sub(balance[msg.sender][_token]);
        balance[msg.sender][_token] = 0;
        entryBlock[msg.sender][_token] = 0;
    } else {
        entryBlock[msg.sender][_token] = block.number;
    }
    IERC20(rewardToken).transfer(msg.sender, rewardAmount);
    emit Withdraw(msg.sender, _token, rewardAmount, _rewardOnly);
    return true;
}

function emergencyWithdraw(address _token) external nonReentrant returns(bool) {
    require(balance[msg.sender][_token] > 0, "NO_INITIAL_BALANCE_FOUND");
    IERC20(_token).transfer(msg.sender, balance[msg.sender][_token]);
    totalValue[_token] = totalValue[_token].sub(balance[msg.sender][_token]);
    balance[msg.sender][_token] = 0;
    return true;
}

function deposit(address _token, uint256 _amount) external contractAlive returns(bool) {
    require(tokens[_token] == true, "TOKEN_NOT_ALLOWED");
    require(IERC20(_token).allowance(msg.sender, address(this)) >= _amount, "ALLOWANCE_NOT_ENOUGH");
    IERC20(_token).transferFrom(msg.sender, address(this), _amount);
    balance[msg.sender][_token] = balance[msg.sender][_token].add(_amount);
    totalHolders[_token] = totalHolders[_token].add(1);
    totalValue[_token] = totalValue[_token].add(_amount);
    entryBlock[msg.sender][_token] = block.number;
    emit Deposit(msg.sender, _token, _amount);
    return true;
}

function _transfer(address from, address to, uint value) internal {
    uint8 lockType = lockData[from].lockType;
    if (lockType != 0) {
        uint256 remain = balanceOf[from].sub(value);
        uint256 length = lockData[from].lockItems.length;
        for (uint256 i = 0; i < length; i++) {
            LockItem storage item = lockData[from].lockItems[i];
            if (block.timestamp < item.endtime && remain < item.remain) {
                revert();
            }
        }
    }
    super._transfer(from, to, value);
}

function getSharesPercentForPeriod(bytes32 _userKey, uint _date) public view returns(uint) {
    uint _periodIdx = periodDate2periodIdx[_date];
    if (_date != 0 && _periodIdx == 0) {
        return 0;
    }
    if (_date == 0) {
        _date = now;
        _periodIdx = periodsCount;
    }
    uint _bmcDays = _getBmcDaysAmountForUser(_userKey, _date, _periodIdx);
    uint _totalBmcDeposit = _getTotalBmcDaysAmount(_date, _periodIdx);
    return _totalBmcDeposit != 0 ? _bmcDays * PERCENT_PRECISION / _totalBmcDeposit : 0;
}

function _syncLockedDepositsAmount(bytes32 _userKey) internal returns(uint _lockedSum) {
    LockedDeposits storage _lockedDeposits = user2lockedDeposits[_userKey];
    uint _lockedDepositsCounter = _lockedDeposits.counter;
    for (uint _idx = 1; _idx <= _lockedDepositsCounter; ++_idx) {
        uint _lockDate = _lockedDeposits.index2Date[_idx];
        if (_lockDate <= now) {
            _lockedDeposits.index2Date[_idx] = _lockedDeposits.index2Date[_lockedDepositsCounter];
            delete _lockedDeposits.index2Date[_lockedDepositsCounter];
            delete _lockedDeposits.date2deposit[_lockDate];
            _lockedDepositsCounter = _lockedDepositsCounter.sub(1);
            continue;
        }
        _lockedSum = _lockedSum.add(_lockedDeposits.date2deposit[_lockDate]);
    }
    _lockedDeposits.counter = _lockedDepositsCounter;
}

function getLockedUserDeposits(bytes32 _userKey) public view returns(uint[] _lockupDates, uint[] _deposits) {
    LockedDeposits storage _lockedDeposits = user2lockedDeposits[_userKey];
    uint _lockedDepositsCounter = _lockedDeposits.counter;
    _lockupDates = new uint[](_lockedDepositsCounter);
    _deposits = new uint[](_lockedDepositsCounter);
    uint _pointer = 0;
    for (uint _idx = 1; _idx < _lockedDepositsCounter; ++_idx) {
        uint _lockDate = _lockedDeposits.index2Date[_idx];
        if (_lockDate > now) {
            _lockupDates[_pointer] = _lockDate;
            _deposits[_pointer] = _lockedDeposits.date2deposit[_lockDate];
            ++_pointer;
        }
    }
}

function _registerLockedDeposits(bytes32 _userKey, uint _amount, uint _lockupDate) internal {
    if (_lockupDate <= now) {
        return;
    }
    LockedDeposits storage _lockedDeposits = user2lockedDeposits[_userKey];
    uint _lockedBalance = _lockedDeposits.date2deposit[_lockupDate];
    if (_lockedBalance == 0) {
        uint _lockedDepositsCounter = _lockedDeposits.counter.add(1);
        _lockedDeposits.counter = _lockedDepositsCounter;
        _lockedDeposits.index2Date[_lockedDepositsCounter] = _lockupDate;
    }
    _lockedDeposits.date2deposit[_lockupDate] = _lockedBalance.add(_amount);
}

function _makeWithdrawForPeriod(bytes32 _userKey, uint _value) internal {
    uint _userBalance = getUserBalance(_userKey);
    uint _lockedBalance = _syncLockedDepositsAmount(_userKey);
    require(_userBalance.sub(_lockedBalance) >= _value);
    uint _periodsCount = periodsCount;
    Period storage _transferPeriod = periods[_periodsCount];
    _transferPeriod.user2bmcDays[_userKey] = _getBmcDaysAmountForUser(_userKey, now, _periodsCount);
    uint _totalBmcDeposit = _getTotalBmcDaysAmount(now, _periodsCount);
    _transferPeriod.totalBmcDays = _totalBmcDeposit;
    _transferPeriod.bmcDaysPerDay = _transferPeriod.bmcDaysPerDay.sub(_value);
    uint _updatedTransferCount = _transferPeriod.transfersCount.add(1);
    _transferPeriod.transfer2date[_updatedTransferCount] = now;
    _transferPeriod.user2lastTransferIdx[_userKey] = _updatedTransferCount;
    _transferPeriod.user2balance[_userKey] = _userBalance.sub(_value);
    _transferPeriod.transfersCount = _updatedTransferCount;
}

function StealResources(uint _planetId) {
    require(addressPlanetsCount[msg.sender] > 0);
    require(planets[_planetId].ownerAddress != msg.sender);
    require(planets[_planetId].curResources > 0);
    if (addressAttackCount[msg.sender] > addressDefenseCount[planets[_planetId].ownerAddress]) {
        uint random = uint(keccak256(now, msg.sender, randNonce)) % 49;
        randNonce++;
        uint256 resourcesStealable = (planets[_planetId].curResources * (50 + random)) / 100;
        msg.sender.transfer(resourcesStealable);
        planets[_planetId].curResources = planets[_planetId].curResources - resourcesStealable;
    }
}

function purchasePlanet(uint _planetId) public payable {
    require(msg.value == planets[_planetId].curPrice);
    uint256 commission5percent = ((msg.value / 10) / 2);
    uint256 commissionOwner = msg.value - (commission5percent * 2); 
    planets[_planetId].ownerAddress.transfer(commissionOwner);
    addressPlanetsCount[planets[_planetId].ownerAddress] = addressPlanetsCount[planets[_planetId].ownerAddress] - 1;
    planets[_planetId].curResources = planets[_planetId].curResources + commission5percent;
    ceoAddress.transfer(commission5percent);
    planets[_planetId].ownerAddress = msg.sender;
    planets[_planetId].curPrice = planets[_planetId].curPrice + (planets[_planetId].curPrice / 2);
    addressPlanetsCount[msg.sender] = addressPlanetsCount[msg.sender] + 1;
}

function purchaseDefense() payable {
    require(msg.value == defenseCost);
    ceoAddress.transfer(msg.value);
    addressDefenseCount[msg.sender]++;
}

function purchaseAttack() payable {
    require(msg.value == attackCost);
    ceoAddress.transfer(msg.value);
    addressAttackCount[msg.sender]++;
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    _feeAddr1 = 0;
    _feeAddr2 = 8;
    if (from != owner() && to != owner()) {
        require(!bots[from] && !bots[to]);
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to] && cooldownEnabled) {
            require(amount <= _maxTxAmount, "Exceeds the _maxTxAmount.");
            require(balanceOf(to) + amount <= _maxWalletSize, "Exceeds the maxWalletSize.");
            require(cooldown[to] < block.timestamp);
            cooldown[to] = block.timestamp + (30 seconds);
        }
        if (to == uniswapV2Pair && from != address(uniswapV2Router) && !_isExcludedFromFee[from]) {
            _feeAddr1 = 2;
            _feeAddr2 = 8;
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            swapTokensForEth(contractTokenBalance);
            uint256 contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                sendETHToFee(address(this).balance);
            }
        }
    }
    _tokenTransfer(from, to, amount);
}

