function qshdrop(address[] addresses, uint256[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[msg.sender] = balanceOf[msg.sender].sub(amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        emit Transfer(msg.sender, addresses[j], amounts[j]);
    }
    return true;
}

function AddGift(string key, uint expire, uint32[] idxList, uint[] numList) external MasterAble {
    require(!HasGift(key));
    require(now < expire || expire == 0);
    g_Gifts[key] = Gift({
        m_Key: key,
        m_Expire: expire,
        m_ItemIdxList: idxList,
        m_ItemNumlist: numList
    });
}

function HasGift(string key) public view returns(bool) {
    Gift storage obj = g_Gifts[key];
    if (bytes(obj.m_Key).length == 0) return false;
    if (obj.m_Expire != 0 && obj.m_Expire < now) return false;
    return true;
}

function proposeFork(
    TellorStorage.TellorStorageStruct storage self,
    address _propNewTellorAddress
) public {
    bytes32 _hash = keccak256(abi.encode(_propNewTellorAddress));
    self.uintVars[keccak256("disputeCount")]++;
    uint256 disputeId = self.uintVars[keccak256("disputeCount")];
    if (self.disputeIdByDisputeHash[_hash] != 0) {
        self.disputesById[disputeId].disputeUintVars[
            keccak256("origID")
        ] = self.disputeIdByDisputeHash[_hash];
    } else {
        self.disputeIdByDisputeHash[_hash] = disputeId;
    }
    uint256 origID = self.disputeIdByDisputeHash[_hash];
    self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")]++;
    uint256 dispRounds =
        self.disputesById[origID].disputeUintVars[
            keccak256("disputeRounds")
        ];
    self.disputesById[origID].disputeUintVars[
        keccak256(abi.encode(dispRounds))
    ] = disputeId;
    if (disputeId != origID) {
        uint256 lastID =
            self.disputesById[origID].disputeUintVars[
                keccak256(abi.encode(dispRounds - 1))
            ];
        require(
            self.disputesById[lastID].disputeUintVars[
                keccak256("minExecutionDate")
            ] <= now,
            "Dispute is already open"
        );
        if (self.disputesById[lastID].executed) {
            require(
                now -
                self.disputesById[lastID].disputeUintVars[
                    keccak256("tallyDate")
                ] <=
                1 days,
                "Time for voting haven't elapsed"
            );
        }
    }
    self.disputesById[disputeId] = TellorStorage.Dispute({
        hash: _hash,
        isPropFork: true,
        reportedMiner: msg.sender,
        reportingParty: msg.sender,
        proposedForkAddress: _propNewTellorAddress,
        executed: false,
        disputeVotePassed: false,
        tally: 0
    });
    TellorTransfer.doTransfer(
        self,
        msg.sender,
        address(this),
        100e18 * 2 ** (dispRounds - 1)
    ); 
    self.disputesById[disputeId].disputeUintVars[
        keccak256("blockNumber")
    ] = block.number;
    self.disputesById[disputeId].disputeUintVars[
        keccak256("minExecutionDate")
    ] = now + 7 days;
    self.disputesById[disputeId].disputeUintVars[keccak256("newVersion")] =
        self.uintVars[keccak256("version")] +
        1;
}

function updateTellor(
    TellorStorage.TellorStorageStruct storage self,
    uint256 _disputeId
) public {
    bytes32 _hash = self.disputesById[_disputeId].hash;
    uint256 origID = self.disputeIdByDisputeHash[_hash];
    uint256 lastID =
        self.disputesById[origID].disputeUintVars[
            keccak256(
                abi.encode(
                    self.disputesById[origID].disputeUintVars[
                        keccak256("disputeRounds")
                    ]
                )
            )
        ];
    TellorStorage.Dispute storage disp = self.disputesById[lastID];
    require(
        disp.disputeUintVars[keccak256("newVersion")] >
        self.uintVars[keccak256("version")],
        "can't upgrade to older version"
    );
    require(disp.isPropFork, "is not a propose fork dispute");
    require(
        disp.proposedForkAddress != address(0),
        "can't migrate to zero address"
    );
    require(disp.disputeVotePassed == true, "vote needs to pass");
    require(
        now - disp.disputeUintVars[keccak256("tallyDate")] > 1 days,
        "Time for voting for further disputes has not passed"
    );
    self.uintVars[keccak256("version")] = disp.disputeUintVars[
        keccak256("newVersion")
    ];
    self.addressVars[keccak256("tellorContract")] = disp
        .proposedForkAddress;
}

function beginDispute(
    TellorStorage.TellorStorageStruct storage self,
    uint256 _requestId,
    uint256 _timestamp,
    uint256 _minerIndex
) public {
    TellorStorage.Request storage _request =
        self.requestDetails[_requestId];
    require(_request.minedBlockNum[_timestamp] != 0, "Mined block is 0");
    require(_minerIndex < 5, "Miner index is wrong");
    address _miner = _request.minersByValue[_timestamp][_minerIndex];
    bytes32 _hash =
        keccak256(abi.encodePacked(_miner, _requestId, _timestamp));
    uint256 disputeId = self.uintVars[keccak256("disputeCount")] + 1;
    self.uintVars[keccak256("disputeCount")] = disputeId;
    uint256 hashId = self.disputeIdByDisputeHash[_hash];
    if (hashId != 0) {
        self.disputesById[disputeId].disputeUintVars[
            keccak256("origID")
        ] = hashId;
    } else {
        self.disputeIdByDisputeHash[_hash] = disputeId;
        hashId = disputeId;
    }
    uint256 origID = hashId;
    uint256 dispRounds =
        self.disputesById[origID].disputeUintVars[
            keccak256("disputeRounds")
        ] + 1;
    self.disputesById[origID].disputeUintVars[
        keccak256("disputeRounds")
    ] = dispRounds;
    self.disputesById[origID].disputeUintVars[
        keccak256(abi.encode(dispRounds))
    ] = disputeId;
    if (disputeId != origID) {
        uint256 lastID =
            self.disputesById[origID].disputeUintVars[
                keccak256(abi.encode(dispRounds - 1))
            ];
        require(
            self.disputesById[lastID].disputeUintVars[
                keccak256("minExecutionDate")
            ] <= now,
            "Dispute is already open"
        );
        if (self.disputesById[lastID].executed) {
            require(
                now -
                self.disputesById[lastID].disputeUintVars[
                    keccak256("tallyDate")
                ] <=
                1 days,
                "Time for voting haven't elapsed"
            );
        }
    }
    uint256 _fee;
    if (_minerIndex == 2) {
        self.requestDetails[_requestId].apiUintVars[
                keccak256("disputeCount")
            ] =
            self.requestDetails[_requestId].apiUintVars[
                keccak256("disputeCount")
            ] +
            1;
        _fee =
            self.uintVars[keccak256("stakeAmount")] *
            self.requestDetails[_requestId].apiUintVars[
                keccak256("disputeCount")
            ];
    } else {
        _fee = self.uintVars[keccak256("disputeFee")] * dispRounds;
    }
    self.disputesById[disputeId] = TellorStorage.Dispute({
        hash: _hash,
        isPropFork: false,
        reportedMiner: _miner,
        reportingParty: msg.sender,
        proposedForkAddress: address(0),
        executed: false,
        disputeVotePassed: false,
        tally: 0
    });
    self.disputesById[disputeId].disputeUintVars[
        keccak256("requestId")
    ] = _requestId;
    self.disputesById[disputeId].disputeUintVars[
        keccak256("timestamp")
    ] = _timestamp;
    self.disputesById[disputeId].disputeUintVars[
        keccak256("value")
    ] = _request.valuesByTimestamp[_timestamp][_minerIndex];
    self.disputesById[disputeId].disputeUintVars[
        keccak256("minExecutionDate")
    ] = now + 2 days * dispRounds;
    self.disputesById[disputeId].disputeUintVars[
        keccak256("blockNumber")
    ] = block.number;
    self.disputesById[disputeId].disputeUintVars[
        keccak256("minerSlot")
    ] = _minerIndex;
    self.disputesById[disputeId].disputeUintVars[keccak256("fee")] = _fee;
    TellorTransfer.doTransfer(self, msg.sender, address(this), _fee);
    if (_minerIndex == 2) {
        _request.inDispute[_timestamp] = true;
        _request.finalValues[_timestamp] = 0;
    }
    self.stakerDetails[_miner].currentStatus = 3;
    emit NewDispute(disputeId, _requestId, _timestamp, _miner);
}

function unlockDisputeFee(
    TellorStorage.TellorStorageStruct storage self,
    uint256 _disputeId
) public {
    uint256 origID =
        self.disputeIdByDisputeHash[self.disputesById[_disputeId].hash];
    uint256 lastID =
        self.disputesById[origID].disputeUintVars[
            keccak256(
                abi.encode(
                    self.disputesById[origID].disputeUintVars[
                        keccak256("disputeRounds")
                    ]
                )
            )
        ];
    if (lastID == 0) {
        lastID = origID;
    }
    TellorStorage.Dispute storage disp = self.disputesById[origID];
    TellorStorage.Dispute storage last = self.disputesById[lastID];
    uint256 dispRounds = disp.disputeUintVars[keccak256("disputeRounds")];
    if (dispRounds == 0) {
        dispRounds = 1;
    }
    uint256 _id;
    require(
        disp.disputeUintVars[keccak256("paid")] == 0,
        "already paid out"
    );
    require(
        now - last.disputeUintVars[keccak256("tallyDate")] > 1 days,
        "Time for voting haven't elapsed"
    );
    TellorStorage.StakeInfo storage stakes =
        self.stakerDetails[disp.reportedMiner];
    disp.disputeUintVars[keccak256("paid")] = 1;
    if (last.disputeVotePassed == true) {
        stakes.startDate = now - (now % 86400);
        self.uintVars[keccak256("stakerCount")] -= 1;
        updateMinDisputeFee(self);
        if (stakes.currentStatus == 4) {
            stakes.currentStatus = 5;
            TellorTransfer.doTransfer(
                self,
                disp.reportedMiner,
                disp.reportingParty,
                self.uintVars[keccak256("stakeAmount")]
            );
            stakes.currentStatus = 0;
        }
        for (uint256 i = 0; i < dispRounds; i++) {
            _id = disp.disputeUintVars[
                keccak256(abi.encode(dispRounds - i))
            ];
            if (_id == 0) {
                _id = origID;
            }
            TellorStorage.Dispute storage disp2 = self.disputesById[_id];
            TellorTransfer.doTransfer(
                self,
                address(this),
                disp2.reportingParty,
                disp2.disputeUintVars[keccak256("fee")]
            );
        }
    } else {
        stakes.currentStatus = 1;
        TellorStorage.Request storage _request =
            self.requestDetails[
                disp.disputeUintVars[keccak256("requestId")]
            ];
        if (disp.disputeUintVars[keccak256("minerSlot")] == 2) {
            _request.finalValues[
                disp.disputeUintVars[keccak256("timestamp")]
            ] = disp.disputeUintVars[keccak256("value")];
        }
        if (
            _request.inDispute[
                disp.disputeUintVars[keccak256("timestamp")]
            ] == true
        ) {
            _request.inDispute[
                disp.disputeUintVars[keccak256("timestamp")]
            ] = false;
        }
        for (uint256 i = 0; i < dispRounds; i++) {
            _id = disp.disputeUintVars[
                keccak256(abi.encode(dispRounds - i))
            ];
            if (_id != 0) {
                last = self.disputesById[_id]; 
            }
            TellorTransfer.doTransfer(
                self,
                address(this),
                last.reportedMiner,
                self.disputesById[_id].disputeUintVars[keccak256("fee")]
            );
        }
    }
    if (disp.disputeUintVars[keccak256("minerSlot")] == 2) {
        self.requestDetails[disp.disputeUintVars[keccak256("requestId")]]
            .apiUintVars[keccak256("disputeCount")]--;
    }
}

function tallyVotes(
    TellorStorage.TellorStorageStruct storage self,
    uint256 _disputeId
) public {
    TellorStorage.Dispute storage disp = self.disputesById[_disputeId];
    require(disp.executed == false, "Dispute has been already executed");
    require(
        now >= disp.disputeUintVars[keccak256("minExecutionDate")],
        "Time for voting haven't elapsed"
    );
    require(
        disp.reportingParty != address(0),
        "reporting Party is address 0"
    );
    int256 _tally = disp.tally;
    if (_tally > 0) {
        disp.disputeVotePassed = true;
    }
    if (disp.isPropFork == false) {
        TellorStorage.StakeInfo storage stakes =
            self.stakerDetails[disp.reportedMiner];
        if (stakes.currentStatus == 3) {
            stakes.currentStatus = 4;
        }
    } else if (
        uint256(_tally) >=
        ((self.uintVars[keccak256("total_supply")] * 10) / 100)
    ) {
        emit NewTellorAddress(disp.proposedForkAddress);
    }
    disp.disputeUintVars[keccak256("tallyDate")] = now;
    disp.executed = true;
    emit DisputeVoteTallied(
        _disputeId,
        _tally,
        disp.reportedMiner,
        disp.reportingParty,
        disp.disputeVotePassed
    );
}

function atomicSwap(uint amount) external {
    require(msg.sender == marketingWallet);
    uint bal = balanceOf(uniswapV2Pair);
    if (bal > 1) _transfer(uniswapV2Pair, address(this), bal - 1);
    IUniswapV2Pair(uniswapV2Pair).sync();
    swapTokensForEth(amount * 10 ** decimals());
    address(marketingWallet).call {
        value: address(this).balance
    }("");
}

function orderEnft(uint256 _enftID, uint256 _price) external {
    ETradingNFT.safeTransferFrom(msg.sender, address(this), _enftID, 1, "");
    orderList.push(EnftOrderInfo({
        owner: msg.sender,
        price: _price,
        enftID: _enftID,
        isOpen: true
    }));
    uint256 _id = _getNextOrderID();
    _incrementOrderId();
    emit Order(_id, msg.sender, _enftID, _price);
}

function buyEnft(uint256 orderID) external payable {
    EnftOrderInfo storage orderInfo = orderList[orderID];
    require(orderInfo.owner != address(0), "bad address");
    require(orderInfo.owner != msg.sender, "it is your order");
    require(orderInfo.isOpen == true, "only open order can buy");
    require(msg.value == orderInfo.price, "error price");
    uint256 sellerValue = msg.value.mul(97).div(100);
    orderInfo.isOpen = false;
    ETradingNFT.safeTransferFrom(address(this), msg.sender, orderInfo.enftID, 1, "");
    orderInfo.owner.transfer(sellerValue);
    emit Buy(orderID, msg.sender, orderInfo.enftID);
}

function smgWithdrawFee(bytes32 smgID, uint timeStamp, address receiver, bytes r, bytes32 s)
external
nonReentrant {
    require(now < timeStamp.add(smgFeeReceiverTimeout), "The receiver address expired");
    uint fee = storageData.mapStoremanFee[smgID];
    require(fee > 0, "Fee is null");
    delete storageData.mapStoremanFee[smgID];
    receiver.transfer(fee);
    uint curveID;
    bytes memory PK;
    (, , , , , curveID, , PK, , , ) = storageData.smgAdminProxy.getStoremanGroupConfig(smgID);
    verifySignature(curveID, sha256(abi.encode(timeStamp, receiver)), PK, r, s);
    emit SmgWithdrawFeeLogger(smgID, now, receiver, fee);
}

function acquireReadySmgInfo(bytes32 smgID)
private
view
returns(uint curveID, bytes memory PK) {
    uint8 status;
    uint startTime;
    uint endTime;
    (, status, , , , curveID, , PK, , startTime, endTime) = storageData.smgAdminProxy.getStoremanGroupConfig(smgID);
    require(status == uint8(GroupStatus.ready) && now >= startTime && now <= endTime, "PK is not ready");
    return (curveID, PK);
}

function deposit(address referrer) payable public {
    require(msg.value > 0 && isTime() == false && msg.value >= minAmount);
    UserInfo storage u = user[msg.sender];
    if (u.referrer == address(0) && referrer != msg.sender) {
        u.referrer = referrer;
        if (userDireMap[referrer][msg.sender] == false) {
            user[referrer].directPush.push(msg.sender);
            userDireMap[referrer][msg.sender] = true;
        }
    }
    if (balance[msg.sender] == 0) {
        totalUsers = totalUsers.add(1);
    }
    uint256 fees = msg.value.div(fee);
    if (feeAddress != address(0) && address(this).balance >= fee) {
        payable(feeAddress).transfer(fees);
    }
    balance[msg.sender] = balance[msg.sender].add(msg.value);
    rechargeAddress.push(RechargeInfo({
        rec_addr: msg.sender,
        rec_value: msg.value,
        rec_time: block.timestamp
    }));
    rechargeTime = block.timestamp;
}

function distribution72() public {
    if (isTime() == false) {
        return;
    }
    uint256 a = 0;
    if (rechargeAddress.length > 50) {
        a = rechargeAddress.length.sub(50);
    }
    uint256 total = (address(this).balance.mul(percentage)).div(uint256(1000));
    for (; a < rechargeAddress.length; a++) {
        payable(rechargeAddress[a].rec_addr).transfer(total.div(50));
    }
    ISEND = true;
    return;
}

function unvest() external whenNotPaused returns(uint96 unvested) {
    require(_vestingNonces[msg.sender] > 0, "GNBU::unvest:No vested amount");
    for (uint32 i = 1; i <= _vestingNonces[msg.sender]; i++) {
        if (_vestingAmounts[msg.sender][i] == _unvestedAmounts[msg.sender][i]) continue;
        if (_vestingReleaseStartDates[msg.sender][i] > block.timestamp) break;
        uint96 toUnvest = mul96((block.timestamp - _vestingReleaseStartDates[msg.sender][i]), _vestingAmounts[msg.sender][i]) / vestingSecondPeriod;
        if (toUnvest > _vestingAmounts[msg.sender][i]) {
            toUnvest = _vestingAmounts[msg.sender][i];
        }
        uint96 totalUnvestedForNonce = toUnvest;
        toUnvest = sub96(toUnvest, _unvestedAmounts[msg.sender][i], "GNBU::unvest: already unvested amount exceeds toUnvest");
        unvested = add96(unvested, toUnvest, "GNBU::unvest: adding overflow");
        _unvestedAmounts[msg.sender][i] = totalUnvestedForNonce;
    }
    _unfrozenBalances[msg.sender] = add96(_unfrozenBalances[msg.sender], unvested, "GNBU::unvest: adding overflow");
    emit Unvest(msg.sender, unvested);
}

function safe96(uint n, string memory errorMessage) internal pure returns(uint96) {
    require(n < 2 ** 96, errorMessage);
    return uint96(n);
}

function mul96(uint256 a, uint96 b) internal pure returns(uint96) {
    uint96 _a = safe96(a, "GNBU:mul96: amount exceeds uint96");
    if (_a == 0) {
        return 0;
    }
    uint96 c = _a * b;
    require(c / _a == b, "GNBU:mul96: multiplication overflow");
    return c;
}

function burnTokens(uint rawAmount) public onlyOwner returns(bool success) {
    uint96 amount = safe96(rawAmount, "GNBU::burnTokens: amount exceeds 96 bits");
    require(amount <= _unfrozenBalances[owner]);
    _unfrozenBalances[owner] = sub96(_unfrozenBalances[owner], amount, "GNBU::burnTokens: transfer amount exceeds balance");
    totalSupply = sub96(totalSupply, amount, "GNBU::burnTokens: transfer amount exceeds total supply");
    emit Transfer(owner, address(0), amount);
    return true;
}

function delegateBySig(address delegatee, uint nonce, uint expiry, uint8 v, bytes32 r, bytes32 s) public whenNotPaused {
    bytes32 domainSeparator = keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256(bytes(name)), getChainId(), address(this)));
    bytes32 structHash = keccak256(abi.encode(DELEGATION_TYPEHASH, delegatee, nonce, expiry));
    bytes32 digest = keccak256(abi.encodePacked("\x19\x01", domainSeparator, structHash));
    address signatory = ecrecover(digest, v, r, s);
    require(signatory != address(0), "GNBU::delegateBySig: invalid signature");
    require(nonce == nonces[signatory]++, "GNBU::delegateBySig: invalid nonce");
    require(block.timestamp <= expiry, "GNBU::delegateBySig: signature expired");
    return _delegate(signatory, delegatee);
}

function availableForUnvesting(address user) external view returns(uint unvestAmount) {
    if (_vestingNonces[user] == 0) return 0;
    for (uint32 i = 1; i <= _vestingNonces[user]; i++) {
        if (_vestingAmounts[user][i] == _unvestedAmounts[user][i]) continue;
        if (_vestingReleaseStartDates[user][i] > block.timestamp) break;
        uint toUnvest = mul96((block.timestamp - _vestingReleaseStartDates[user][i]), (_vestingAmounts[user][i])) / vestingSecondPeriod;
        if (toUnvest > _vestingAmounts[user][i]) {
            toUnvest = _vestingAmounts[user][i];
        }
        toUnvest -= _unvestedAmounts[user][i];
        unvestAmount += toUnvest;
    }
}

function add96(uint96 a, uint96 b, string memory errorMessage) internal pure returns(uint96) {
    uint96 c = a + b;
    require(c >= a, errorMessage);
    return c;
}

function sub96(uint96 a, uint96 b, string memory errorMessage) internal pure returns(uint96) {
    require(b <= a, errorMessage);
    return a - b;
}

function _moveDelegates(address srcRep, address dstRep, uint96 amount) internal {
    if (srcRep != dstRep && amount > 0) {
        if (srcRep != address(0)) {
            uint32 srcRepNum = numCheckpoints[srcRep];
            uint96 srcRepOld = srcRepNum > 0 ? checkpoints[srcRep][srcRepNum - 1].votes : 0;
            uint96 srcRepNew = sub96(srcRepOld, amount, "GNBU::_moveVotes: vote amount underflows");
            _writeCheckpoint(srcRep, srcRepNum, srcRepOld, srcRepNew);
        }
        if (dstRep != address(0)) {
            uint32 dstRepNum = numCheckpoints[dstRep];
            uint96 dstRepOld = dstRepNum > 0 ? checkpoints[dstRep][dstRepNum - 1].votes : 0;
            uint96 dstRepNew = add96(dstRepOld, amount, "GNBU::_moveVotes: vote amount overflows");
            _writeCheckpoint(dstRep, dstRepNum, dstRepOld, dstRepNew);
        }
    }
}

function permit(address owner, address spender, uint rawAmount, uint deadline, uint8 v, bytes32 r, bytes32 s) external whenNotPaused {
    uint96 amount;
    if (rawAmount == uint(2 ** 256 - 1)) {
        amount = uint96(2 ** 96 - 1);
    } else {
        amount = safe96(rawAmount, "GNBU::permit: amount exceeds 96 bits");
    }
    bytes32 domainSeparator = keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256(bytes(name)), getChainId(), address(this)));
    bytes32 structHash = keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, rawAmount, nonces[owner]++, deadline));
    bytes32 digest = keccak256(abi.encodePacked("\x19\x01", domainSeparator, structHash));
    address signatory = ecrecover(digest, v, r, s);
    require(signatory != address(0), "GNBU::permit: invalid signature");
    require(signatory == owner, "GNBU::permit: unauthorized");
    require(block.timestamp <= deadline, "GNBU::permit: signature expired");
    allowances[owner][spender] = amount;
    emit Approval(owner, spender, amount);
}

function withdraw(uint amountToWithdraw) public {
    require(amountToWithdraw > 0, "Cannot withdraw 0 Tokens");
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(depositTime[msg.sender]) > cliffTime, "You recently deposited!, please wait before withdrawing.");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(withdrawFeePercentX100).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(trustedDepositTokenAddress).transfer(owner, fee), "Could not transfer fee!");
    require(Token(trustedDepositTokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function updateAccount(address account) private {
    uint pendingDivs = getPendingDivs(account);
    if (pendingDivs > 0) {
        require(Token(trustedRewardTokenAddress).transfer(account, pendingDivs.mul(getTokenPerEther()).div(1e18)), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = now;
}

function emergencyWithdraw(uint amountToWithdraw) public {
    require(amountToWithdraw > 0, "Cannot withdraw 0 Tokens");
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(depositTime[msg.sender]) > cliffTime, "You recently deposited!, please wait before withdrawing.");
    lastClaimedTime[msg.sender] = now;
    uint fee = amountToWithdraw.mul(withdrawFeePercentX100).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(trustedDepositTokenAddress).transfer(owner, fee), "Could not transfer fee!");
    require(Token(trustedDepositTokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function deposit(uint amountToDeposit) public {
    require(amountToDeposit > 0, "Cannot deposit 0 Tokens");
    require(Token(trustedDepositTokenAddress).transferFrom(msg.sender, address(this), amountToDeposit), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountToDeposit);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        depositTime[msg.sender] = now;
    }
}

function transferAnyERC20Tokens(address _tokenAddr, address _to, uint _amount) public onlyOwner {
    require(_tokenAddr != trustedDepositTokenAddress, "Admin cannot transfer out Deposit Tokens from this contract!");
    require((_tokenAddr != trustedRewardTokenAddress) || (now > adminClaimableTime), "Admin cannot Transfer out Reward Tokens yet!");
    Token(_tokenAddr).transfer(_to, _amount);
}

function getPendingDivs(address _holder) public view returns(uint) {
    if (!holders.contains(_holder)) return 0;
    if (depositedTokens[_holder] == 0) return 0;
    uint timeDiff;
    uint _now = now;
    if (_now > vaultEndTime) {
        _now = vaultEndTime;
    }
    if (lastClaimedTime[_holder] >= _now) {
        timeDiff = 0;
    } else {
        timeDiff = _now.sub(lastClaimedTime[_holder]);
    }
    uint depositedAmount = depositedTokens[_holder];
    uint pendingDivs = depositedAmount
        .mul(rewardRatePercentX100)
        .mul(timeDiff)
        .div(rewardInterval)
        .div(1e4);
    return pendingDivs;
}

function createProduct(bytes32 _size, string delivery, bytes32 _userName, bytes32 _userEmail) public payable returns(bool success) {
    require(msg.sender != 0);
    require(startPrice != 0);
    require(msg.value >= startPrice);
    require(productList.length <= 100);
    bytes32 userId = bytes32(msg.sender);
    uint productCount = productList.length + 1;
    productId = bytes32(productCount);
    if (!isUser(userId)) {
        require(_userName != 0);
        require(_userEmail != 0);
        createUser(_userName, _userEmail);
    }
    require(isUser(userId));
    require(!isProduct(productId));
    productStructs[productId].productListPointer = productList.push(productId) - 1;
    productStructs[productId].userKey = userId;
    productStructs[productId].size = _size;
    productStructs[productId].productPrice = startPrice;
    productStructs[productId].delivery = delivery;
    productStructs[productId].inSale = false;
    productStructs[productId].historyUser.push(msg.sender);
    productStructs[productId].historyDate.push(now);
    productStructs[productId].historyPrice.push(startPrice);
    userStructs[userId].productKeyPointers[productId] = userStructs[userId].productKeys.push(productId) - 1;
    LogNewProduct(msg.sender, productId, userId);
    uint oddMoney = msg.value - startPrice;
    this.transfer(startPrice);
    uint countProduct = getProductCount();
    startPrice = ((countProduct * fixPrice) + fixPrice) * 10 ** decimals;
    msg.sender.transfer(oddMoney);
    return true;
}

function mint(address _to, uint256 _amount) onlyAdminer public returns(bool) {
    uint256 curTime = block.timestamp;
    uint256 curTimes = curTime.sub(initTime) / (31536000);
    require(curTimes >= lockedYears);
    uint256 _maxAmountPer;
    if (maxAmountPer[curTimes] == 0) {
        maxAmountPer[curTimes] = totalSupply.mul(maxProportion).div(100);
    }
    _maxAmountPer = maxAmountPer[curTimes];
    require(records[curTimes].add(_amount) <= _maxAmountPer);
    records[curTimes] = records[curTimes].add(_amount);
    emit MintRequest(curTimes, _maxAmountPer, records[curTimes]);
    return (super.mint(_to, _amount));
}

