function _rewardCalculation(
    address userAddress,
    address tokenAddress,
    address referrer,
    uint256[3] memory stakingData,
    uint256 interval
) internal {
    uint256 rewardsEarned;
    uint256 refEarned;
    uint256[2] memory noOfDays;
    noOfDays[1] = interval.div(HOURS);
    noOfDays[0] = interval.div(DAYS);
    rewardsEarned = noOfDays[1].mul(
        getOneDayReward(
            stakingData[0],
            tokenAddress,
            tokenAddress,
            stakingData[1]
        )
    );
    address stakedToken = getTokenAddress(tokenAddress);
    if (referrer != address(0)) {
        refEarned = (rewardsEarned.mul(stakingData[2])).div(100 ether);
        rewardsEarned = rewardsEarned.sub(refEarned);
        require(
            IERC20(stakedToken).transfer(referrer, refEarned) == true,
            "Transfer Failed"
        );
        emit ReferralEarn(
            referrer,
            _msgSender(),
            stakedToken,
            refEarned,
            block.timestamp
        );
    }
    sendToken(userAddress, stakedToken, stakedToken, rewardsEarned);
    uint8 i = 1;
    while (i < intervalDays.length) {
        if (noOfDays[0] >= intervalDays[i]) {
            uint256 reductionHours = (intervalDays[i].sub(1)).mul(24);
            uint256 balHours = noOfDays[1].sub(reductionHours);
            address rewardToken = cohort.tokensSequenceList(
                tokenAddress,
                i
            );
            if (
                rewardToken != tokenAddress &&
                cohort.tokenBlockedStatus(tokenAddress, rewardToken) ==
                false
            ) {
                rewardsEarned = balHours.mul(
                    getOneDayReward(
                        stakingData[0],
                        tokenAddress,
                        rewardToken,
                        stakingData[1]
                    )
                );
                address rewardToken1 = getTokenAddress(rewardToken);
                if (referrer != address(0)) {
                    refEarned = (rewardsEarned.mul(stakingData[2])).div(
                        100 ether
                    );
                    rewardsEarned = rewardsEarned.sub(refEarned);
                    require(
                        IERC20(rewardToken1).transfer(referrer, refEarned) ==
                        true,
                        "Transfer Failed"
                    );
                    emit ReferralEarn(
                        referrer,
                        _msgSender(),
                        rewardToken1,
                        refEarned,
                        block.timestamp
                    );
                }
                sendToken(
                    userAddress,
                    tokenAddress,
                    rewardToken1,
                    rewardsEarned
                );
            }
            i = i + 1;
        } else {
            break;
        }
    }
}

function sendToken(
    address userAddress,
    address stakedToken,
    address tokenAddress,
    uint256 amount
) internal {
    if (tokenAddress != address(0)) {
        require(
            IERC20(tokenAddress).balanceOf(address(this)) >= amount,
            "SEND : Insufficient Reward Balance"
        );
        require(
            IERC20(tokenAddress).transfer(userAddress, amount),
            "Transfer failed"
        );
        emit Claim(
            userAddress,
            stakedToken,
            tokenAddress,
            amount,
            block.timestamp
        );
    }
}

function claimRewards(
    address userAddress,
    uint256 stakeId,
    uint256 totalStake
) internal {
    uint256 interval;
    uint256 endOfProfit;
    (
        address[] memory referrar,
        address[] memory tokenAddresses, , ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = cohort.viewStakingDetails(userAddress);
    interval = poolStartTime.add(stakeDuration);
    if (interval > block.timestamp) endOfProfit = block.timestamp;
    else endOfProfit = poolStartTime.add(stakeDuration);
    interval = endOfProfit.sub(startTime[stakeId]);
    uint256 refPercentage = cohort.refPercentage();
    uint256[3] memory stakeData;
    stakeData[0] = (stakedAmount[stakeId]);
    stakeData[1] = (totalStake);
    stakeData[2] = (refPercentage);
    if (interval >= HOURS)
        _rewardCalculation(
            userAddress,
            tokenAddresses[stakeId],
            referrar[stakeId],
            stakeData,
            interval
        );
}

function unStake(address userAddress, uint256 stakeId)
external
whenNotPaused
returns(bool) {
    require(
        _msgSender() == userAddress || _msgSender() == _owner,
        "UNSTAKE: Invalid User Entry"
    );
    (,
        address[] memory tokenAddress,
        bool[] memory isActive, ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = cohort.viewStakingDetails(userAddress);
    uint256 totalStaking = getTotalStaking(tokenAddress[stakeId]);
    address stakedToken = getTokenAddress(tokenAddress[stakeId]);
    require(
        lockableDetails[stakedToken].lockableDays <= block.timestamp,
        "UNSTAKE: Token Locked"
    );
    if (lockableDetails[stakedToken].optionableStatus == true)
        require(
            startTime[stakeId].add(stakeDuration) <= block.timestamp,
            "UNSTAKE: Locked in optional lock"
        );
    require(
        stakedAmount[stakeId] > 0 &&
        isActive[stakeId] == true &&
        unStakeStatus[userAddress][stakeId] == false,
        "UNSTAKE : Already Claimed (or) Insufficient Staked"
    );
    unStakeStatus[userAddress][stakeId] = true;
    require(
        IERC20(stakedToken).balanceOf(address(this)) >=
        stakedAmount[stakeId],
        "UNSTAKE : Insufficient Balance"
    );
    if (tokenBlockedStatus[tokenAddress[stakeId]] == false) {
        IERC20(stakedToken).transfer(
            userAddress,
            stakedAmount[stakeId]
        );
    }
    claimRewards(userAddress, stakeId, totalStaking);
    emit UnStake(
        userAddress,
        stakedToken,
        stakedAmount[stakeId],
        block.timestamp,
        stakeId
    );
    return true;
}

function withdraw(address _betterAddress) public requireState(2) {
    require(bets[winningFighter][_betterAddress].stake > 0);
    require(!bets[winningFighter][_betterAddress].withdrawn);
    address(_betterAddress).transfer(totalPrizePool().mul(bets[winningFighter][_betterAddress].stake).div(totalForFighter[winningFighter]));
    bets[winningFighter][_betterAddress].withdrawn = true;
}

function buy(uint minPurchaseReturn) public payable {
    uint amount = formulaContract.calculatePurchaseReturn(
        (tokenContract.totalSupply() - uncirculatedSupplyCount) - tokenContract.balanceOf(this),
        (address(this).balance + virtualReserveBalance) - msg.value,
        weight,
        msg.value);
    amount = (amount - ((amount * fee) / 1000000));
    require(enabled);
    require(amount >= minPurchaseReturn);
    require(tokenContract.balanceOf(this) >= amount);
    if (msg.value > thresholdSendToSafeWallet) {
        uint transferToSafeWallet = msg.value * sendToSafeWalletPercentage / 100;
        creator.transfer(transferToSafeWallet);
        virtualReserveBalance += transferToSafeWallet;
    }
    collectedFees += (msg.value * fee) / 1000000;
    emit Buy(msg.sender, msg.value, amount);
    tokenContract.transfer(msg.sender, amount);
}

function sell(uint quantity, uint minSaleReturn) public {
    uint amountInWei = formulaContract.calculateSaleReturn(
        (tokenContract.totalSupply() - uncirculatedSupplyCount) - tokenContract.balanceOf(this),
        address(this).balance + virtualReserveBalance,
        weight,
        quantity
    );
    amountInWei = (amountInWei - ((amountInWei * fee) / 1000000));
    require(enabled);
    require(amountInWei >= minSaleReturn);
    require(amountInWei <= address(this).balance);
    require(tokenContract.transferFrom(msg.sender, this, quantity));
    collectedFees += (amountInWei * fee) / 1000000;
    emit Sell(msg.sender, quantity, amountInWei);
    msg.sender.transfer(amountInWei);
}

function LandSale(address _wallet, uint256 _goal,
    uint256 _openingTime, uint256 _closingTime) public {
    require(_wallet != address(0));
    require(_goal > 0);
    require(_openingTime >= block.timestamp);
    require(_closingTime >= _openingTime);
    wallet = _wallet;
    vault = new RefundVault(wallet);
    goal = _goal;
    openingTime = _openingTime;
    closingTime = _closingTime;
}

function finalize() onlyOwner public {
    require(!isFinalized);
    require(hasClosed());
    if (goalReached()) {
        vault.close();
    } else {
        vault.enableRefunds();
    }
    Finalized();
    isFinalized = true;
}

