function purchase(uint256 _drug_id) public payable {
    require(gameOpen == true);
    Drug storage drug = drugs[_drug_id];
    require(drug.owner != msg.sender);
    require(msg.sender != address(0));
    require(msg.value >= drug.price);
    uint256 excess = SafeMath.sub(msg.value, drug.price);
    uint256 half_diff = SafeMath.div(SafeMath.sub(drug.price, drug.last_price), 2);
    uint256 reward = SafeMath.add(half_diff, drug.last_price);
    lastBuyer[1].send(uint256(SafeMath.mul(SafeMath.div(half_diff, 100), 69))); 
    lastBuyer[6].send(uint256(SafeMath.mul(SafeMath.div(half_diff, 100), 2))); 
    lastBuyer[9].send(uint256(SafeMath.mul(SafeMath.div(half_diff, 100), 2))); 
    if (drug.owner == address(this)) {
        ceoAddress.send(reward);
    } else {
        drug.owner.send(reward);
    }
    drug.last_price = drug.price;
    address _old_owner = drug.owner;
    if (drug.price < 1690000000000000000) { 
        drug.price = SafeMath.mul(SafeMath.div(drug.price, 100), 169); 
    } else {
        drug.price = SafeMath.mul(SafeMath.div(drug.price, 100), 125); 
    }
    drug.owner = msg.sender;
    lastBuyer[9] = lastBuyer[8];
    lastBuyer[8] = lastBuyer[7];
    lastBuyer[7] = lastBuyer[6];
    lastBuyer[6] = lastBuyer[5];
    lastBuyer[5] = lastBuyer[4];
    lastBuyer[4] = lastBuyer[3];
    lastBuyer[3] = lastBuyer[2];
    lastBuyer[2] = lastBuyer[1];
    lastBuyer[1] = msg.sender;
    Transfer(_old_owner, drug.owner, _drug_id);
    TokenSold(_drug_id, drug.last_price, drug.price, _old_owner, drug.owner, drug.name);
    msg.sender.send(excess);
}

function withdraw(uint256 amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > cliffTime, "You recently staked, please wait before withdrawing.");
    updateAccount(msg.sender);
    uint256 fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint256 amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(LPtokenAddress).transfer(owner, fee), "Could not transfer deposit fee.");
    require(Token(LPtokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function getPendingDivs(address _holder) public view returns(uint256) {
    if (!holders.contains(_holder)) return 0;
    if (depositedTokens[_holder] == 0) return 0;
    uint256 timeDiff = now.sub(lastClaimedTime[_holder]);
    uint256 stakedAmount = depositedTokens[_holder];
    if (now > farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(40000000000).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    } else if (now <= farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(rewardRate).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    }
}

function getStakingAndDaoAmount() public view returns(uint256) {
    if (totalClaimedRewards >= stakingAndDaoTokens) {
        return 0;
    }
    uint256 remaining = stakingAndDaoTokens.sub(totalClaimedRewards);
    return remaining;
}

function updateAccount(address account) private {
    uint256 pendingDivs = getPendingDivs(account);
    if (pendingDivs > 0) {
        require(Token(tokenAddress).transfer(account, pendingDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = now;
}

function deposit(uint256 amountToStake) public {
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(farmEnabled, "Farming is not enabled");
    require(Token(LPtokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint256 fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint256 amountAfterFee = amountToStake.sub(fee);
    require(Token(LPtokenAddress).transfer(owner, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function getPeriod(uint256 _currentDate) public pure returns(uint) {
    if (1530403200 <= _currentDate && _currentDate <= 1530835199) {
        return 0;
    }
    if (1530835200 <= _currentDate && _currentDate <= 1531699199) {
        return 1;
    }
    if (1531699200 <= _currentDate && _currentDate <= 1532563199) {
        return 2;
    }
    if (1532563200 <= _currentDate && _currentDate <= 1533513599) {
        return 3;
    }
    if (1533513600 <= _currentDate && _currentDate <= 1534377599) {
        return 4;
    }
    return 10;
}

function getAfterIcoPeriod(uint256 _currentDate) public pure returns(uint) {
    uint256 endIco = 1534377600; 
    if (endIco < _currentDate && _currentDate <= endIco + 2 * 365 days) {
        return 100;
    }
    if (endIco + 2 * 365 days < _currentDate && _currentDate <= endIco + 4 * 365 days) {
        return 200;
    }
    if (endIco + 4 * 365 days < _currentDate && _currentDate <= endIco + 6 * 365 days) {
        return 300;
    }
    if (endIco + 6 * 365 days < _currentDate && _currentDate <= endIco + 8 * 365 days) {
        return 400;
    }
    return 0;
}

function _addTimelock(address _beneficary, uint256 _timestamp) internal whenNotTimelocked(_beneficary) {
    require(_timestamp > block.timestamp);
    timelock[_beneficary] = _timestamp;
    emit TimeLocked(_beneficary, _timestamp);
}

function enableTimelock(uint256 _timelockTimestamp) onlyOwner public {
    require(timelockTimestamp == 0 || _timelockTimestamp > block.timestamp);
    timelockTimestamp = _timelockTimestamp;
}

function transferFrom(address _from, address _to, uint256 _value) public whenNotTimelocked(_from) returns(bool) {
    if (timelockTimestamp > block.timestamp)
        _addTimelock(_to, timelockTimestamp);
    return super.transferFrom(_from, _to, _value);
}

function transfer(address _to, uint256 _value) public whenNotTimelocked(msg.sender) returns(bool) {
    if (timelockTimestamp > block.timestamp)
        _addTimelock(_to, timelockTimestamp);
    return super.transfer(_to, _value);
}

function userFinalize() public {
    require(now >= (timestamp + timeWithoutUpdate));
    require(!gameOver);
    gameOverByUser = true;
}

function currentRate() public view returns(uint256) {
    return (now < rateBecomesValidAt) ? oldRate : rate;
}

function updateRate(uint256 newRate) internal {
    require(newRate != 0);
    if (now > rateBecomesValidAt) {
        oldRate = rate;
    }
    rate = newRate;
    rateBecomesValidAt = now + rateUpdateDelay;
    emit RateUpdate(newRate, rateBecomesValidAt);
}

function updateRateByUpdater(uint256 newRate) external onlyUpdater {
    (uint256 rate, uint256 timePriorToApply) = futureRate();
    require(timePriorToApply == 0, "New rate hasn't been applied yet");
    uint256 newRateMultiplied = newRate * 100;
    require(newRateMultiplied / 100 == newRate, "Integer overflow");
    require(newRate * 95 <= rate * 100, "New rate is too high");
    updateRate(newRate);
}

function futureRate() public view returns(uint256, uint256) {
    return (now < rateBecomesValidAt) ? (rate, rateBecomesValidAt - now) : (rate, 0);
}

function buy() public payable returns(uint256) {
    uint256 availableTotal = availableTokens();
    require(availableTotal > 0);
    uint256 amount = weiToTokens(msg.value);
    require(amount >= ONE_TOKEN);
    uint256 actual = amount < availableTotal ? amount : availableTotal;
    require(IERC20Token(token).transfer(msg.sender, actual));
    if (amount != actual) {
        uint256 weiRefund = msg.value - tokensToWei(actual);
        msg.sender.transfer(weiRefund);
    }
    emit Purchase(msg.sender, actual);
    return actual;
}

function buyFromRC(address _buyer, uint256 _rcTokenValue, uint256 _remainingTokens) onlyRC isBuyable public payable returns(uint256) {
    uint256 oneToken = 10 ** uint256(decimals);
    uint256 tokenValue = tokenValueInEther(_rcTokenValue);
    uint256 tokenAmount = msg.value.mul(oneToken).div(tokenValue);
    address _ambassador = msg.sender;
    uint256 remainingTokens = tokenContract.balanceOf(this);
    if (_remainingTokens < remainingTokens) {
        remainingTokens = _remainingTokens;
    }
    if (remainingTokens < tokenAmount) {
        uint256 refund = tokenAmount.sub(remainingTokens).mul(tokenValue).div(oneToken);
        tokenAmount = remainingTokens;
        forward(msg.value.sub(refund));
        remainingTokens = 0; 
        _buyer.transfer(refund);
    } else {
        remainingTokens = remainingTokens.sub(tokenAmount); 
        forward(msg.value);
    }
    tokenContract.transfer(_buyer, tokenAmount);
    emit Buy(_buyer, tokenAmount, _ambassador);
    return tokenAmount;
}

function freeze(address _account, uint _until) public onlyOwner {
    if (_until == 0 || (_until != 0 && _until > now)) {
        frozenAccounts[_account] = Frozen(true, _until);
    }
}

function claim() public noClaimYet(msg.sender) {
    uint amount = 1e21;
    require(ERC20Basic(erc20_address).balanceOf(this) >= amount);
    _claimed[msg.sender] = true;
    ERC20Basic(erc20_address).transfer(msg.sender, amount);
}

function finalize() external {
    if (msg.sender != ethFundDeposit) throw; 
    if (block.number <= fundingEndBlock && totalSupply < tokenCreationCap) throw; 
    if (!ethFundDeposit.send(this.balance)) throw; 
    uint256 remainingSupply = safeSubtract(tokenCreationCap, totalSupply); 
    if (remainingSupply > 0) { 
        uint256 updatedSupply = safeAdd(totalSupply, remainingSupply); 
        totalSupply = updatedSupply; 
        balances[gunsFundDeposit] += remainingSupply; 
        CreateGUNS(gunsFundDeposit, remainingSupply); 
    }
    isFinalized = true; 
}

