function getOrderActualTotalRefundHelper(uint256 _nowDayIndex, uint256 _oID)
internal
view
returns(uint256) {
    if (oID_Order_[_oID].hasWithdrawn) {
        return (
            oID_Order_[_oID].withdrawn
        );
    }
    uint256 _actualTotalRefund = oID_Order_[_oID].orderValue.mul(60).div(100);
    uint256 _dayGap = _nowDayIndex.sub(oID_Order_[_oID].createDayIndex);
    if (_dayGap > 0) {
        _dayGap = _dayGap > 5 ? 5 : _dayGap;
        uint256 _maxRefund = oID_Order_[_oID].orderValue.mul(12).mul(_dayGap).div(100);
        if (oID_Order_[_oID].refund < _maxRefund) {
            _actualTotalRefund = _actualTotalRefund.add(oID_Order_[_oID].refund);
        } else {
            _actualTotalRefund = _actualTotalRefund.add(_maxRefund);
        }
    }
    return (
        _actualTotalRefund
    );
}

function orderCore(uint256 _now, uint256 _nowDayIndex, uint256 _value)
private {
    teamPot_ = teamPot_.add(_value.mul(3).div(100));
    communityPot_ = communityPot_.add(_value.mul(4).div(100));
    require(day_ethIn[_nowDayIndex] < dayEthInLimit_, "beyond the day eth in limit");
    day_ethIn[_nowDayIndex] = day_ethIn[_nowDayIndex].add(_value);
    ethIn_ = ethIn_.add(_value);
    uint256 _pID = addr_pID_[msg.sender];
    if (pID_Player_[_pID].lastOrderDayIndex == _nowDayIndex) {
        require(pID_Player_[_pID].dayEthIn < playerDayEthInLimit_, "beyond the player day eth in limit");
        pID_Player_[_pID].dayEthIn = pID_Player_[_pID].dayEthIn.add(_value);
    } else {
        pID_Player_[_pID].lastOrderDayIndex = _nowDayIndex;
        pID_Player_[_pID].dayEthIn = _value;
    }
    oIDIndex_ = oIDIndex_.add(1);
    oID_Order_[oIDIndex_].pID = _pID;
    oID_Order_[oIDIndex_].createTime = _now;
    oID_Order_[oIDIndex_].createDayIndex = _nowDayIndex;
    oID_Order_[oIDIndex_].orderValue = _value;
    pID_Player_[_pID].oIDs.push(oIDIndex_);
    refundOIDs_.push(oIDIndex_);
    uint256 _percent = 33;
    if (pID_Player_[_pID].oIDs.length < 3) {
        _percent = distributeInviteReward(_pID, _value.mul(5).div(100), _value.mul(2).div(100), _value.mul(1).div(100), _percent);
        refund(_nowDayIndex, _value.mul(_percent).div(100));
    } else {
        refund(_nowDayIndex, _value.mul(_percent).div(100));
    }
    emit PopoEvents.onOrder(
        _pID,
        msg.sender,
        _nowDayIndex,
        oIDIndex_,
        _value,
        now
    );
}

function unpaid(uint256 _id) external view returns(uint256 amt) {
    Award memory _award = awards[_id];
    require(_award.usr != address(0), "DssVest/invalid-award");
    amt = unpaid(block.timestamp, _award.bgn, _award.clf, _award.fin, _award.tot, _award.rxd);
}

function accrued(uint256 _time, uint48 _bgn, uint48 _fin, uint128 _tot) internal pure returns(uint256 amt) {
    if (_time < _bgn) {
        amt = 0;
    } else if (_time >= _fin) {
        amt = _tot;
    } else {
        amt = mul(_tot, sub(_time, _bgn)) / sub(_fin, _bgn); 
    }
}

function getPendingDivs(address _holder) public view returns(uint256) {
    if (!holders.contains(_holder)) return 0;
    if (depositedTokens[_holder] == 0) return 0;
    uint256 timeDiff = now.sub(lastClaimedTime[_holder]);
    uint256 stakedAmount = depositedTokens[_holder];
    if (now > farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(2010797).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    } else if (now <= farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(rewardRate).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    }
}

function buyTokensCrowdsale(address receiver) internal  {
    uint256 weiAmount = msg.value;
    uint256 tokenAmount = 0;
    if (getState() == State.PreFunding) {
        if (weiAmount < PRESALE_ETH_IN_WEI_ACCEPTED_MIN) revert();
        if ((PRESALE_ETH_IN_WEI_FUND_MAX > 0) && ((presale_eth_fund.add(weiAmount)) > PRESALE_ETH_IN_WEI_FUND_MAX)) revert();
        tokenAmount = calculateTokenPresale(weiAmount, token_decimals);
        presale_eth_fund = presale_eth_fund.add(weiAmount);
    } else if ((getState() == State.Funding) || (getState() == State.Success)) {
        if (weiAmount < CROWDSALE_ETH_IN_WEI_ACCEPTED_MIN) revert();
        tokenAmount = calculateTokenCrowsale(weiAmount, token_decimals);
    } else {
        revert();
    }
    if (tokenAmount == 0) {
        revert();
    }
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    investedAmountOf[receiver] = investedAmountOf[receiver].add(weiAmount);
    tokenAmountOf[receiver] = tokenAmountOf[receiver].add(tokenAmount);
    crowdsale_eth_fund = crowdsale_eth_fund.add(weiAmount);
    tokensSold = tokensSold.add(tokenAmount);
    token.mint(receiver, tokenAmount);
    if (!multisigWallet.send(weiAmount)) revert();
    Invested(receiver, weiAmount, tokenAmount);
}

function getState() public constant returns(State) {
    if (finalized) return State.Finalized;
    else if (now < startsAt) return State.PreFunding;
    else if (now <= endsAt && !isMinimumGoalReached()) return State.Funding;
    else if (isMinimumGoalReached()) return State.Success;
    else if (!isMinimumGoalReached() && crowdsale_eth_fund > 0 && loadedRefund >= crowdsale_eth_fund) return State.Refunding;
    else return State.Failure;
}

function setEndsAt(uint time) onlyOwner public {
    if (now > time) {
        revert();
    }
    endsAt = time;
    EndsAtChanged(endsAt);
}

function hasEnded() public constant returns(bool) {
    return now > endsAt;
}

function doFinalize() public inState(State.Success) onlyOwner stopInEmergency {
    if (finalized) {
        revert();
    }
    createTeamTokenByPercentage();
    token.finishMinting();
    finalized = true;
    Finalized();
}

function redeemPreSale(address _address) public returns(bool) {
    if (!redeemed[_address]) {
        uint256 value = AuctusPreSale(auctusPreSaleAddress).getTokenAmount(_address);
        if (value > 0) {
            redeemed[_address] = true;
            escrowedTokens = escrowedTokens.sub(value);
            assert(AuctusToken(auctusTokenAddress).transfer(_address, value));
            emit Redeem(_address, value);
            return true;
        }
    }
    return false;
}

function claim(uint256 _saleId) public nonReentrant returns(bool) {
    Sale storage s = sale[msg.sender][_saleId];
    SaleInfo storage i = info[s.saleId];
    require(
        !s.isAllocated,
        "Already Settled"
    );
    require(
        block.timestamp > i.end,
        "Sale Not Yet Ended"
    );
    uint256 _bonusTokens = resolveBonus(_saleId, msg.sender);
    s.bonus = _bonusTokens;
    s.isAllocated = true;
    IERC20(edgexTokenContract)
        .transfer(
            msg.sender,
            Math.add(s.amountPurchased, _bonusTokens)
        );
    IERC20(edgexTokenContract)
        .transfer(
            organisation,
            Math.div(s.amountPurchased, 100)
        );
    return true;
}

function purchaseWithEth() public payable nonReentrant returns(bool) {
    SaleInfo storage i = info[totalSaleContracts];
    require(
        i.totalPurchased <= i.allocated,
        "Sold Out"
    );
    require(
        block.timestamp < i.end,
        "Purchase Ended"
    );
    require(isWhitelisted(msg.sender), "Address not verified");
    (
        uint256 _amountToken,
        uint256 _pricePurchase,
        uint256 _usdPurchase
    ) = resolverEther(msg.value);
    Sale storage s = sale[msg.sender][Math.add(totalPurchases[msg.sender], 1)];
    s.usdPurchase = _usdPurchase;
    s.amountPurchased = _amountToken;
    s.pricePurchase = _pricePurchase;
    s.timestamp = block.timestamp;
    s.saleId = totalSaleContracts;
    i.totalPurchased = Math.add(i.totalPurchased, _amountToken);
    totalPurchases[msg.sender] = Math.add(totalPurchases[msg.sender], 1);
    payable(ethWallet).transfer(msg.value);
    return true;
}

function adminPurchase(
    uint256 _amountToken,
    uint256 _usdPurchase,
    uint256 _pricePurchase
) public onlyGovernor returns(bool) {
    SaleInfo storage i = info[totalSaleContracts];
    require(
        i.totalPurchased <= i.allocated,
        "Sold Out"
    );
    require(
        block.timestamp < i.end,
        "Purchase Ended"
    );
    Sale storage s = sale[msg.sender][Math.add(totalPurchases[msg.sender], 1)];
    s.usdPurchase = _usdPurchase;
    s.amountPurchased = _amountToken;
    s.pricePurchase = _pricePurchase;
    s.timestamp = block.timestamp;
    s.saleId = totalSaleContracts;
    i.totalPurchased = Math.add(i.totalPurchased, _amountToken);
    totalPurchases[msg.sender] = Math.add(totalPurchases[msg.sender], 1);
    return true;
}

function increaseAllocation(uint256 _amount, uint256 _saleId) public onlyGovernor returns(bool) {
    SaleInfo storage i = info[_saleId];
    require(
        block.timestamp < i.end,
        "Sale Ended"
    );
    i.allocated = Math.add(
        i.allocated,
        Math.mul(_amount, 10 ** 18)
    );
    return true;
}

function createSaleContract(uint256 _allocated, uint8 _source) public onlyGovernor returns(bool) {
    require(
        Math.add(lastCreated, 2 hours) < block.timestamp,
        "Create After Sometime"
    );
    SaleInfo storage i = info[Math.add(totalSaleContracts, 1)];
    i.start = block.timestamp;
    i.end = Math.add(block.timestamp, 2 hours);
    i.allocated = Math.mul(_allocated, 10 ** 18);
    i.priceSource = _source;
    lastCreated = block.timestamp;
    totalSaleContracts = Math.add(totalSaleContracts, 1);
    return true;
}

function processMessage(
    address _sender,
    address _executor,
    bytes32 _messageId,
    uint256 _gasLimit,
    uint8, 
    uint256 _sourceChainId,
    bytes memory _data
) internal {
    bool status = _passMessage(_sender, _executor, _data, _gasLimit, _messageId, _sourceChainId);
    setMessageCallStatus(_messageId, status);
    if (!status) {
        setFailedMessageDataHash(_messageId, _data);
        setFailedMessageReceiver(_messageId, _executor);
        setFailedMessageSender(_messageId, _sender);
    }
    emitEventOnMessageProcessed(_sender, _executor, _messageId, status);
}

function initialize(
    uint256 _sourceChainId,
    uint256 _destinationChainId,
    address _validatorContract,
    uint256 _maxGasPerTx,
    uint256 _gasPrice,
    uint256 _requiredBlockConfirmations,
    address _owner
) external onlyRelevantSender returns(bool) {
    require(!isInitialized());
    require(AddressUtils.isContract(_validatorContract));
    _setChainIds(_sourceChainId, _destinationChainId);
    addressStorage[VALIDATOR_CONTRACT] = _validatorContract;
    uintStorage[DEPLOYED_AT_BLOCK] = block.number;
    uintStorage[MAX_GAS_PER_TX] = _maxGasPerTx;
    _setGasPrice(_gasPrice);
    _setRequiredBlockConfirmations(_requiredBlockConfirmations);
    _setOwner(_owner);
    setInitialize();
    return isInitialized();
}

function safeExecuteSignaturesWithGasLimit(bytes _data, bytes _signatures, uint32 _gas) public {
    _allowMessageExecution(_data, _signatures);
    bytes32 msgId;
    address sender;
    address executor;
    uint8 dataType;
    uint256[2] memory chainIds;
    bytes memory data;
    (msgId, sender, executor, , dataType, chainIds, data) = ArbitraryMessage.unpackData(_data);
    _executeMessage(msgId, sender, executor, _gas, dataType, chainIds, data);
}

function executeSignatures(bytes _data, bytes _signatures) public {
    _allowMessageExecution(_data, _signatures);
    bytes32 msgId;
    address sender;
    address executor;
    uint32 gasLimit;
    uint8 dataType;
    uint256[2] memory chainIds;
    bytes memory data;
    (msgId, sender, executor, gasLimit, dataType, chainIds, data) = ArbitraryMessage.unpackData(_data);
    _executeMessage(msgId, sender, executor, gasLimit, dataType, chainIds, data);
}

