function release(address payable account) public virtual {
    require(_shares[account] > 0, "PaymentSplitter: account has no shares");
    uint256 totalReceived = address(this).balance.add(_totalReleased);
    uint256 payment = totalReceived.mul(_shares[account]).div(_totalShares).sub(_released[account]);
    require(payment != 0, "PaymentSplitter: account is not due payment");
    _released[account] = _released[account].add(payment);
    _totalReleased = _totalReleased.add(payment);
    account.transfer(payment);
    emit PaymentReleased(account, payment);
}

function invest(address _to, uint256 _amount) canReleaseToken onlyOwner public returns(bool success) {
    require((_to != 0) && (_to != address(this)));
    bool IsTransferAllowed = false;
    if (IsPreSaleEnabled) {
        require(preSaleTokenBalances >= _amount);
        IsTransferAllowed = true;
        preSaleTokenBalances = preSaleTokenBalances - _amount;
    } else if (IsSaleEnabled) {
        IsTransferAllowed = true;
    } else {
        revert();
    }
    require(IsTransferAllowed);
    var previousBalanceFrom = balanceOfAt(msg.sender, block.number);
    require(previousBalanceFrom >= _amount);
    updateValueAtNow(balances[msg.sender], previousBalanceFrom - _amount);
    var previousBalanceTo = balanceOfAt(_to, block.number);
    require(previousBalanceTo + _amount >= previousBalanceTo);
    updateValueAtNow(balances[_to], previousBalanceTo + _amount);
    transferFrom(msg.sender, _to, _amount); 
    return true;
}

function generateTokens(address _owner, uint _amount) public onlyOwner returns(bool) {
    uint curTotalSupply = totalSupply();
    require(curTotalSupply + _amount >= curTotalSupply);
    uint previousBalanceTo = balanceOf(_owner);
    require(previousBalanceTo + _amount >= previousBalanceTo);
    updateValueAtNow(totalSupplyHistory, curTotalSupply + _amount);
    updateValueAtNow(balances[_owner], previousBalanceTo + _amount);
    uint256 _bal = _amount * 30;
    preSaleTokenBalances = preSaleTokenBalances + _bal / 100;
    Transfer(0, _owner, _amount);
    return true;
}

function approve(address _spender, uint256 _amount) public returns(bool success) {
    require((_amount == 0) || (allowed[msg.sender][_spender] == 0));
    if (isValidAddress(owner)) {
        require(TokenController(owner).onApprove(msg.sender, _spender, _amount));
    }
    allowed[msg.sender][_spender] = _amount;
    Approval(msg.sender, _spender, _amount);
    return true;
}

function withdraw() external virtual {
    VestingStruct memory result = addressInfo[msg.sender];
    require(
        result.vestedTokens > 0,
        "Vesting: You don't have any vested token"
    );
    require(
        block.timestamp >=
        (result.vestingStartTime + (result.cliffPeriod * 1 days)),
        "Vesting: Cliff period is not over yet"
    );
    uint256 tokensAvailable = getAvailableTokens(msg.sender);
    uint256 alreadyWithdrawn = tokensAlreadyWithdrawn[msg.sender];
    require(
        tokensAvailable + alreadyWithdrawn <= result.vestedTokens,
        "Vesting: Can't withdraw more than vested token amount"
    );
    if (tokensAvailable + alreadyWithdrawn == result.vestedTokens) {
        tokensAlreadyWithdrawn[msg.sender] = 0;
        addressInfo[msg.sender] = VestingStruct(0, 0, 0, 0, 0);
    } else {
        tokensAlreadyWithdrawn[msg.sender] += tokensAvailable;
    }
    emit TokenReleased(msg.sender, tokensAvailable);
    _token.transfer(msg.sender, tokensAvailable);
}

function deposit(
    address beneficiary,
    uint256 amount,
    uint256 cliffPeriod,
    uint256 vestingPeriod
) external returns(bool success) {
    VestingStruct memory result = addressInfo[msg.sender];
    require(
        result.vestedTokens == 0,
        "Vesting: Beneficiary already have vested token. Use another address"
    );
    require(
        _token.transferFrom(msg.sender, address(this), amount),
        "Vesting: Please approve token first"
    );
    addressInfo[beneficiary] = VestingStruct(
        amount,
        cliffPeriod,
        vestingPeriod,
        block.timestamp,
        amount / vestingPeriod
    );
    emit TokenVested(
        beneficiary,
        amount,
        cliffPeriod,
        vestingPeriod,
        block.timestamp,
        amount / vestingPeriod
    );
    return true;
}

function getAvailableTokens(address beneficiary)
public
view
returns(uint256) {
    VestingStruct memory result = addressInfo[beneficiary];
    if (result.vestedTokens > 0) {
        uint256 vestingEndTime =
            (result.vestingStartTime + (result.vestingPeriod * 1 days));
        if (block.timestamp >= vestingEndTime) {
            return
            result.vestedTokens - tokensAlreadyWithdrawn[beneficiary];
        } else {
            uint256 totalDays =
                ((
                    block.timestamp > vestingEndTime ?
                    vestingEndTime :
                    block.timestamp
                ) - result.vestingStartTime) / 1 days;
            return (totalDays * result.withdrawalPerDay) -
            tokensAlreadyWithdrawn[beneficiary];
        }
    } else {
        return 0;
    }
}

function canTeamKeepingWithdraw(uint256 _value) public view returns(bool) {
    if (queryNow() < innerlockStartTime) {
        return false;
    }
    uint256 epoch = queryNow().sub(innerlockStartTime).div(unlockStepLong);
    if (epoch > 12) {
        epoch = 12;
    }
    uint256 releaseAmount = teamKeepingPerEpoch.mul(epoch);
    uint256 canWithdrawAmount = releaseAmount.sub(teamKeepingSupply);
    if (canWithdrawAmount >= _value) {
        return true;
    } else {
        return false;
    }
}

function transferFrom(address _from, address _to, uint256 _value) public whenNotPaused returns(bool) {
    require(_to != address(0));
    uint256 needLockBalance = 0;
    if (lockAmount[_from] > 0) {
        needLockBalance = clacCooperateNeedLockAmount(lockAmount[_from]);
    }
    require(balances[_from].sub(_value) >= needLockBalance);
    uint256 _allowance = allowed[_from][msg.sender];
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = _allowance.sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function canPlatformFundingWithdraw(uint256 _value) public view returns(bool) {
    if (queryNow() < innerlockStartTime) {
        return false;
    }
    uint256 epoch = queryNow().sub(innerlockStartTime).div(unlockStepLong);
    if (epoch > 12) {
        epoch = 12;
    }
    uint256 releaseAmount = platformFundingPerEpoch.mul(epoch);
    uint256 canWithdrawAmount = releaseAmount.sub(platformFundingSupply);
    if (canWithdrawAmount >= _value) {
        return true;
    } else {
        return false;
    }
}

function clacCooperateNeedLockAmount(uint256 totalLockAmount) public view returns(uint256) {
    if (queryNow() < outterlockStartTime) {
        return totalLockAmount;
    }
    uint256 epoch = queryNow().sub(outterlockStartTime).div(unlockStepLong);
    if (epoch > 12) {
        epoch = 12;
    }
    uint256 remainingEpoch = uint256(12).sub(epoch);
    uint256 cooperatePerEpoch = totalLockAmount.div(12);
    return cooperatePerEpoch.mul(remainingEpoch);
}

function transfer(address _to, uint256 _value) public whenNotPaused returns(bool) {
    require(_to != address(0));
    uint256 needLockBalance = 0;
    if (lockAmount[msg.sender] > 0) {
        needLockBalance = clacCooperateNeedLockAmount(lockAmount[msg.sender]);
    }
    require(balances[msg.sender].sub(_value) >= needLockBalance);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

