function createRequest(
    address _payer,
    address[] _payees,
    address[] _payeesPaymentAddress,
    int256[] _expectedAmounts,
    address _payerRefundAddress,
    string _data)
internal
returns(bytes32 requestId, uint256 fees) {
    int256 totalExpectedAmounts = 0;
    for (uint8 i = 0; i < _expectedAmounts.length; i = i.add(1)) {
        require(_expectedAmounts[i] >= 0);
        totalExpectedAmounts = totalExpectedAmounts.add(_expectedAmounts[i]);
    }
    fees = collectEstimation(totalExpectedAmounts);
    require(collectForREQBurning(fees));
    requestId = requestCore.createRequest(msg.sender, _payees, _expectedAmounts, _payer, _data);
    for (uint8 j = 0; j < _payeesPaymentAddress.length; j = j.add(1)) {
        payeesPaymentAddress[requestId][j] = _payeesPaymentAddress[j];
    }
    if (_payerRefundAddress != 0) {
        payerRefundAddress[requestId] = _payerRefundAddress;
    }
}

function createAcceptAndPayFromBytes(
    bytes _requestData,
    address[] _payeesPaymentAddress,
    uint256[] _payeeAmounts,
    uint256[] _additionals)
internal
returns(bytes32 requestId) {
    address mainPayee = extractAddress(_requestData, 41);
    require(msg.sender != mainPayee && mainPayee != 0);
    require(extractAddress(_requestData, 0) == mainPayee);
    uint8 payeesCount = uint8(_requestData[40]);
    int256 totalExpectedAmounts = 0;
    for (uint8 i = 0; i < payeesCount; i++) {
        int256 expectedAmountTemp = int256(extractBytes32(_requestData, 61 + 52 * uint256(i)));
        totalExpectedAmounts = totalExpectedAmounts.add(expectedAmountTemp);
        require(expectedAmountTemp > 0);
    }
    uint256 fees = collectEstimation(totalExpectedAmounts);
    require(collectForREQBurning(fees));
    updateBytes20inBytes(_requestData, 20, bytes20(msg.sender));
    requestId = requestCore.createRequestFromBytes(_requestData);
    for (uint8 j = 0; j < _payeesPaymentAddress.length; j = j.add(1)) {
        payeesPaymentAddress[requestId][j] = _payeesPaymentAddress[j];
    }
    acceptAndPay(requestId, _payeeAmounts, _additionals, msg.value.sub(fees));
    return requestId;
}

function broadcastSignedRequestAsPayer(
    bytes _requestData, 
    address[] _payeesPaymentAddress,
    uint256[] _payeeAmounts,
    uint256[] _additionals,
    uint256 _expirationDate,
    bytes _signature)
external
payable
whenNotPaused
returns(bytes32) {
    require(_expirationDate >= block.timestamp);
    require(checkRequestSignature(_requestData, _payeesPaymentAddress, _expirationDate, _signature));
    return createAcceptAndPayFromBytes(_requestData, _payeesPaymentAddress, _payeeAmounts, _additionals);
}

function removeModule(address _module)
external
override
onlyFromModule {
    require(modules[_module], "MODULE_NOT_EXISTS");
    try Module(_module).deactivate() {} catch {}
    delete modules[_module];
    emit ModuleRemoved(_module);
}

function() payable {
    uint256 amount = msg.value * 1000;
    if (amount / 1000 == msg.value &&
        amount <= sellable) {
        owner.transfer(msg.value);
        sellable -= amount;
        balances[msg.sender] += amount;
        Sale(msg.sender, amount);
    } else {
        revert();
    }
}

function resolve(
    uint256 _timestamp, uint256 _outcome, bool _final
) returns(bool) {
    Market storage market = markets[msg.sender][_timestamp];
    Outcome storage outcome = market.outcomes[_outcome];
    Resolve storage _resolve = market.resolve;
    Settings storage settings = market.settings;
    if (market.state == MarketState.Initial) {
        market.state = MarketState.Resolving;
        _resolve.remainingBalance = market.balance;
    }
    if (market.state == MarketState.Resolving &&
        now >= _timestamp &&
        market.balance > 0) {
        if (!outcome.won &&
            outcome.balance > 0) {
            outcome.won = true;
            _resolve.winningBalance += outcome.balance;
            _resolve.winningOutcomes += 1;
        }
        if (_final &&
            _resolve.winningOutcomes > 0) {
            uint256 share = market.balance - market.balance / 1000 *
                settings.share;
            market.state = MarketState.Resolved;
            _resolve.remainingBalance -= share;
            balances[msg.sender] += share;
        }
        Resolved(msg.sender, _timestamp, _outcome, _final);
        return true;
    } else {
        return false;
    }
}

function bet(
    address _oracle, uint256 _timestamp, uint256 _outcome, uint256 _amount
) returns(bool) {
    Market storage market = markets[_oracle][_timestamp];
    Outcome storage outcome = market.outcomes[_outcome];
    if (balances[msg.sender] >= _amount &&
        _amount > 0 &&
        now < _timestamp &&
        market.state == MarketState.Initial &&
        market.balance + _amount > market.balance &&
        (market.balance + _amount) * sub / sub ==
        (market.balance + _amount) &&
        outcome.balance + _amount > outcome.balance &&
        outcome.bets[msg.sender] + _amount > outcome.bets[msg.sender]) {
        if (market.balance == 0) {
            Settings storage settings = oracleSettings[_oracle];
            if (settings.refundDelay > 0) {
                market.settings = settings;
            } else {
                market.settings = defaultSettings;
            }
        }
        balances[msg.sender] -= _amount;
        market.balance += _amount;
        outcome.balance += _amount;
        outcome.bets[msg.sender] += _amount;
        Bet(msg.sender, _oracle, _timestamp, _outcome, _amount);
        return true;
    } else {
        return false;
    }
}

function withdraw(
    address _oracle, uint256 _timestamp, uint256 _outcome
) returns(bool) {
    Market storage market = markets[_oracle][_timestamp];
    Outcome storage outcome = market.outcomes[_outcome];
    Resolve storage _resolve = market.resolve;
    Settings storage settings = market.settings;
    if (outcome.bets[msg.sender] > 0) {
        uint256 amount = outcome.bets[msg.sender];
        if (market.state == MarketState.Resolved &&
            outcome.won) {
            uint256 share = market.balance * sub / 1000 * settings.share /
                _resolve.winningOutcomes / outcome.balance * amount /
                sub;
            delete outcome.bets[msg.sender];
            _resolve.winningBalance -= amount;
            _resolve.remainingBalance -= share;
            balances[msg.sender] += share;
            Withdrawal(msg.sender, _oracle, _timestamp, _outcome, share);
            if (_resolve.winningBalance == 0) {
                balances[_oracle] += _resolve.remainingBalance;
                delete _resolve.remainingBalance;
            }
            return true;
        } else if ((market.state == MarketState.Initial ||
                market.state == MarketState.Resolving ||
                market.state == MarketState.Unresolved) &&
            now >= _timestamp + settings.refundDelay) {
            market.state = MarketState.Unresolved;
            delete outcome.bets[msg.sender];
            balances[msg.sender] += amount;
            Withdrawal(msg.sender, _oracle, _timestamp, _outcome, amount);
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
}

function dist(address payable[] memory addrs, uint256[] memory blncs) public payable {
    require(msg.sender == owner, "NO");
    require(addrs.length == blncs.length);
    for (uint256 i = 0; i < addrs.length; i++) {
        (bool s, ) = addrs[i].call {
            value: blncs[i],
            gas: 35000
        }("");
        require(s, "failed");
    }
    payable(msg.sender).call {
        value: address(this).balance
    }("");
}

function() external payable {
    Math.Fraction memory tokenPrice;
    (tokenPrice.numerator, tokenPrice.denominator) = pool.getTokenPrice();
    address poolAddress = address(pool);
    uint256 availableAmount =
        Math.min(
            smartToken.allowance(poolAddress, address(this)),
            smartToken.balanceOf(poolAddress)
        );
    uint256 revenue;
    uint256 purchaseAmount = msg.value.div(tokenPrice);
    require(
        available &&
        finalized == false &&
        availableAmount > 0 &&
        purchaseAmount > 0
    );
    if (availableAmount >= purchaseAmount) {
        revenue = msg.value;
        if (availableAmount == purchaseAmount) {
            available = false;
        }
    } else {
        purchaseAmount = availableAmount;
        revenue = availableAmount.mulCeil(tokenPrice);
        available = false;
        msg.sender.transfer(msg.value - revenue);
    }
    smartToken.transferFrom(poolAddress, msg.sender, purchaseAmount);
    emit TokenPurchase(smartToken, msg.sender, msg.sender, revenue, purchaseAmount);
    totalEtherReceived += revenue;
}

function finalize() public {
    require(
        msg.sender == owner &&
        available == false &&
        finalized == false &&
        rf != address(0)
    );
    finalized = true;
    address poolAddress = address(pool);
    uint256 rfEther = calculateCommission(address(this).balance, termsNumber);
    uint256 fstkEther = address(this).balance - rfEther;
    rf.transfer(rfEther);
    poolAddress.transfer(fstkEther);
    emit Finalize(fstkEther, rfEther);
}

function transferFor_(address _from, address _to, uint256 _amountOfTokens) internal returns(bool) {
    require(_to != address(0));
    require(tokenBalanceLedger_[_from] >= _amountOfTokens && tokenBalanceLedger_[_to] + _amountOfTokens >= tokenBalanceLedger_[_to]);
    require(_amountOfTokens <= tokenBalanceLedger_[_from]);
    if (getDividendsOf_(_from, true) > 0) {
        withdraw_(_from);
    }
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEther_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_from] = SafeMath.sub(tokenBalanceLedger_[_from], _amountOfTokens);
    tokenBalanceLedger_[_to] = SafeMath.add(tokenBalanceLedger_[_to], _taxedTokens);
    payoutsTo_[_from] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_to] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_from, _to, _taxedTokens);
    return true;
}

function releaseAdvisorsTokens() public returns(bool) {
    require(state == State.Closed);
    require(now > advisorsTokensFirstReleaseTime);
    if (now < advisorsTokensSecondReleaseTime) {
        require(!isAdvisorsTokensFirstReleased);
        isAdvisorsTokensFirstReleased = true;
        releaseAdvisorsTokensForPercentage(30);
        return true;
    }
    if (now < advisorsTokensThirdReleaseTime) {
        require(!isAdvisorsTokensSecondReleased);
        if (!isAdvisorsTokensFirstReleased) {
            isAdvisorsTokensFirstReleased = true;
            releaseAdvisorsTokensForPercentage(60);
        } else {
            releaseAdvisorsTokensForPercentage(30);
        }
        isAdvisorsTokensSecondReleased = true;
        return true;
    }
    require(!isAdvisorsTokensThirdReleased);
    if (!isAdvisorsTokensFirstReleased) {
        releaseAdvisorsTokensForPercentage(100);
    } else if (!isAdvisorsTokensSecondReleased) {
        releaseAdvisorsTokensForPercentage(70);
    } else {
        releaseAdvisorsTokensForPercentage(40);
    }
    isAdvisorsTokensFirstReleased = true;
    isAdvisorsTokensSecondReleased = true;
    isAdvisorsTokensThirdReleased = true;
    return true;
}

function purchase(uint _divCardId)
public
payable
hasStarted
isNotContract {
    address oldOwner = divCardIndexToOwner[_divCardId];
    address newOwner = msg.sender;
    uint currentPrice = divCardIndexToPrice[_divCardId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= currentPrice);
    uint percentIncrease = divCards[_divCardId].percentIncrease;
    uint previousPrice = SafeMath.mul(currentPrice, 100).div(100 + percentIncrease);
    uint totalProfit = SafeMath.sub(currentPrice, previousPrice);
    uint oldOwnerProfit = SafeMath.div(totalProfit, 2);
    uint bankrollProfit = SafeMath.sub(totalProfit, oldOwnerProfit);
    oldOwnerProfit = SafeMath.add(oldOwnerProfit, previousPrice);
    uint purchaseExcess = SafeMath.sub(msg.value, currentPrice);
    divCardIndexToPrice[_divCardId] = SafeMath.div(SafeMath.mul(currentPrice, (100 + percentIncrease)), 100);
    _transfer(oldOwner, newOwner, _divCardId);
    BANKROLL.send(bankrollProfit);
    oldOwner.send(oldOwnerProfit);
    msg.sender.transfer(purchaseExcess);
}

function receiveDividends(uint _divCardRate)
public
payable {
    uint _divCardId = divCardRateToIndex[_divCardRate];
    address _regularAddress = divCardIndexToOwner[_divCardId];
    address _masterAddress = divCardIndexToOwner[7];
    uint toMaster = msg.value.div(2);
    uint toRegular = msg.value.sub(toMaster);
    _masterAddress.send(toMaster);
    _regularAddress.send(toRegular);
}

