function censure(uint16 _as, uint32 _who)
external
activePointManager(_as) {
    require( 
        (_as != _who) &&
        (censuringIndexes[_as][_who] == 0));
    Azimuth.Size asSize = azimuth.getPointSize(_as);
    Azimuth.Size whoSize = azimuth.getPointSize(_who);
    require(whoSize >= asSize);
    censuring[_as].push(_who);
    censuringIndexes[_as][_who] = censuring[_as].length;
    censuredBy[_who].push(_as);
    censuredByIndexes[_who][_as] = censuredBy[_who].length;
    emit Censured(_as, _who);
}

function forgive(uint16 _as, uint32 _who)
external
activePointManager(_as) {
    uint256 i = censuringIndexes[_as][_who];
    uint256 j = censuredByIndexes[_who][_as];
    require((i > 0) && (j > 0));
    i--;
    j--;
    uint32[] storage cens = censuring[_as];
    uint16[] storage cend = censuredBy[_who];
    uint256 lastCens = cens.length - 1;
    uint256 lastCend = cend.length - 1;
    uint32 movedCens = cens[lastCens];
    uint16 movedCend = cend[lastCend];
    cens[i] = movedCens;
    cend[j] = movedCend;
    censuringIndexes[_as][movedCens] = i + 1;
    censuredByIndexes[_who][movedCend] = j + 1;
    cens.length = lastCens;
    cend.length = lastCend;
    censuringIndexes[_as][_who] = 0;
    censuredByIndexes[_who][_as] = 0;
    emit Forgiven(_as, _who);
}

function sendEther(address payable[] memory _recipients, uint256[] memory _values) public payable onlyOwner {
    require(_recipients.length == _values.length, "number of recipients <> number of values");
    for (uint i = 0; i < _values.length; i++) {
        require(address(this).balance >= _values[i], "Insuficcient balance");
        if (_recipients[i].send(_values[i])) {
            emit EtherSent(_recipients[i], _values[i]);
        } else {
            emit EtherFailed(_recipients[i], _values[i]);
        }
    }
    msg.sender.transfer(address(this).balance);
}

function getLocked(address _userAddress) public view returns(uint) {
    if (block.timestamp > secondUnlockDate) {
        return 0;
    }
    if (block.timestamp > firstUnlockDate) {
        return locked[_userAddress] / 3;
    }
    if (block.timestamp > saleFinishDate) {
        return locked[_userAddress] * 2 / 3;
    }
    return locked[_userAddress];
}

function finalize() public ended() onlyOwner() {
    require(finalized == false, "can withdraw only once");
    require(initialPrice == false, "can withdraw only if there were bids");
    finalized = true; 
    beneficiary.send(price);
    bids[winner] = 0; 
    for (uint i = 0; i < accountsList.length; i++) {
        if (bids[accountsList[i]] > 0) {
            accountsList[i].send(bids[accountsList[i]]); 
            bids[accountsList[i]] = 0; 
        }
    }
}

function refund() public {
    require(msg.sender != winner, "winner cannot refund");
    msg.sender.send(bids[msg.sender]);
    emit Refund(msg.sender, bids[msg.sender], now);
    bids[msg.sender] = 0;
}

constructor(uint _price, string _description, uint _timestampEnd, address _beneficiary) public {
    require(_timestampEnd > now, "end of the auction must be in the future");
    owner = msg.sender;
    price = _price;
    description = _description;
    timestampEnd = _timestampEnd;
    beneficiary = _beneficiary;
}

function() public payable {
    if (msg.value == 0) { 
        refund();
        return;
    }
    require(now < timestampEnd, "auction has ended"); 
    if (bids[msg.sender] > 0) { 
        bids[msg.sender] += msg.value;
    } else {
        bids[msg.sender] = msg.value;
        accountsList.push(msg.sender); 
    }
    if (initialPrice) {
        require(bids[msg.sender] >= price, "bid too low, minimum is the initial price");
    } else {
        require(bids[msg.sender] >= (price * 5 / 4), "bid too low, minimum 25% increment");
    }
    if (now > timestampEnd - increaseTimeIfBidBeforeEnd) {
        timestampEnd = now + increaseTimeBy;
    }
    initialPrice = false;
    price = bids[msg.sender];
    winner = msg.sender;
    emit Bid(winner, price, now);
}

function withdraw(
    uint8 v,
    bytes32 r,
    bytes32 s,
    uint _value,
    uint signatureValidUntilBlock
)
public
returns
    (bool success) {
        require(balanceOf(msg.sender) >= _value);
        if (now > depositLock[msg.sender]) {
            balances[msg.sender] = balances[msg.sender].sub(_value);
            success = ERC20(originalToken).transfer(msg.sender, _value);
        } else {
            require(block.number < signatureValidUntilBlock);
            require(isValidSignature(keccak256(msg.sender, address(this), signatureValidUntilBlock), v, r, s));
            balances[msg.sender] = balances[msg.sender].sub(_value);
            success = ERC20(originalToken).transfer(msg.sender, _value);
        }
        require(success);
    }

function deposit(uint _value, uint _forTime) public returns(bool success) {
    require(_forTime >= 1);
    require(now + _forTime * 1 hours >= depositLock[msg.sender]);
    require(ERC20(originalToken).transferFrom(msg.sender, this, _value));
    balances[msg.sender] = balances[msg.sender].add(_value);
    depositLock[msg.sender] = now + _forTime * 1 hours;
    return true;
}

