function rateAndInvalid(bytes32 currencyKey) external view returns(uint rate, bool isInvalid) {
    RateAndUpdatedTime memory rateAndTime = _getRateAndUpdatedTime(currencyKey);
    if (currencyKey == "sUSD") {
        return (rateAndTime.rate, false);
    }
    return (
        rateAndTime.rate,
        _rateIsStaleWithTime(getRateStalePeriod(), rateAndTime.time) ||
        _rateIsFlagged(currencyKey, FlagsInterface(getAggregatorWarningFlags()))
    );
}

function internalUpdateRates(
    bytes32[] memory currencyKeys,
    uint[] memory newRates,
    uint timeSent
) internal returns(bool) {
    require(currencyKeys.length == newRates.length, "Currency key array length must match rates array length.");
    require(timeSent < (now + ORACLE_FUTURE_LIMIT), "Time is too far into the future");
    for (uint i = 0; i < currencyKeys.length; i++) {
        bytes32 currencyKey = currencyKeys[i];
        require(newRates[i] != 0, "Zero is not a valid rate, please call deleteRate instead.");
        require(currencyKey != "sUSD", "Rate of sUSD cannot be updated, it's always UNIT.");
        if (timeSent < _getUpdatedTime(currencyKey)) {
            continue;
        }
        _setRate(currencyKey, newRates[i], timeSent);
    }
    emit RatesUpdated(currencyKeys, newRates);
    return true;
}

function ratesAndInvalidForCurrencies(bytes32[] calldata currencyKeys)
external
view
returns(uint[] memory rates, bool anyRateInvalid) {
    rates = new uint[](currencyKeys.length);
    uint256 _rateStalePeriod = getRateStalePeriod();
    bool[] memory flagList = getFlagsForRates(currencyKeys);
    for (uint i = 0; i < currencyKeys.length; i++) {
        RateAndUpdatedTime memory rateEntry = _getRateAndUpdatedTime(currencyKeys[i]);
        rates[i] = rateEntry.rate;
        if (!anyRateInvalid && currencyKeys[i] != "sUSD") {
            anyRateInvalid = flagList[i] || _rateIsStaleWithTime(_rateStalePeriod, rateEntry.time);
        }
    }
}

function summon() external payable whenNotPaused {
    if (accountsLastClearTime[msg.sender] == uint256(0)) {
        accountsLastClearTime[msg.sender] = now;
    } else {
        if (accountsLastClearTime[msg.sender] < levelClearTime && now > levelClearTime) {
            accoutToSummonNum[msg.sender] = 0;
            accoutToPayLevel[msg.sender] = 0;
            accountsLastClearTime[msg.sender] = now;
        }
    }
    uint256 payLevel = accoutToPayLevel[msg.sender];
    uint256 price = payMultiple[payLevel] * baseSummonPrice;
    require(msg.value >= price);
    uint128 randomAppearance = mixFormula.randomSkinAppearance();
    Skin memory newSkin = Skin({
        appearance: randomAppearance,
        cooldownEndTime: uint64(now),
        mixingWithId: 0
    });
    skins[nextSkinId] = newSkin;
    skinIdToOwner[nextSkinId] = msg.sender;
    isOnSale[nextSkinId] = false;
    CreateNewSkin(nextSkinId, msg.sender);
    nextSkinId++;
    numSkinOfAccounts[msg.sender] += 1;
    accoutToSummonNum[msg.sender] += 1;
    if (payLevel < 5) {
        if (accoutToSummonNum[msg.sender] >= levelSplits[payLevel]) {
            accoutToPayLevel[msg.sender] = payLevel + 1;
        }
    }
}

function clearSummonNum() external onlyOwner {
    uint256 nextDay = levelClearTime + 1 days;
    if (now > nextDay) {
        levelClearTime = nextDay;
    }
}

function deposit(uint256 amount, uint256 blocksUntilCompleted) public onlyOwner {
    require(!hasDeposited);
    token.transferFrom(msg.sender, address(this), amount);
    depositedAmount = amount;
    finalBlock = block.number.add(blocksUntilCompleted);
    vested_period = blocksUntilCompleted;
    hasDeposited = true;
}

function withdraw() public onlyOwner {
    require(hasDeposited);
    if (block.number > finalBlock) {
        token.transfer(owner, token.balanceOf(address(this)));
        hasDeposited = false;
    } else {
        uint256 numerator = depositedAmount.mul(vested_period.sub(finalBlock.sub(block.number)));
        uint256 allowedAmount = numerator.div(vested_period);
        uint256 toWithdraw = allowedAmount.sub(withdrawnAmount);
        token.transfer(owner, toWithdraw);
        withdrawnAmount = withdrawnAmount.add(toWithdraw);
    }
}

function policyRebase() internal {
    require(inRebaseWindow());
    require(lastRebaseTimestampSec.add(minRebaseTimeIntervalSec) < now);
    lastRebaseTimestampSec = now.sub(
        now.mod(minRebaseTimeIntervalSec)).add(rebaseWindowOffsetSec);
    epoch = epoch.add(1);
    uint256 targetRate;
    bool targetRateValid;
    (targetRate, targetRateValid) = TargetPriceOracle.getData();
    require(targetRateValid);
    uint256 exchangeRate;
    bool rateValid;
    (exchangeRate, rateValid) = MarketPriceOracle.getData(); 
    require(rateValid);
    if (exchangeRate > MAX_RATE) {
        exchangeRate = MAX_RATE;
    }
    int256 supplyDelta = computeSupplyDelta(exchangeRate, targetRate);
    supplyDelta = supplyDelta.div(rebaseLag.toInt256Safe());
    if (supplyDelta > 0 && OracleBase.totalSupply().add(uint256(supplyDelta)) > MAX_SUPPLY) {
        supplyDelta = (MAX_SUPPLY.sub(OracleBase.totalSupply())).toInt256Safe();
    }
    uint256 supplyAfterRebase = OracleBase.rebase(epoch, supplyDelta);
    assert(supplyAfterRebase <= MAX_SUPPLY);
    emit LogRebase(epoch, exchangeRate, targetRate, supplyDelta, now);
}

function inRebaseWindow() public view returns(bool) {
    return (
        now.mod(minRebaseTimeIntervalSec) >= rebaseWindowOffsetSec &&
        now.mod(minRebaseTimeIntervalSec) < (rebaseWindowOffsetSec.add(rebaseWindowLengthSec))
    );
}

