function initNewRewardPeriod() external {
    require(
        block.timestamp >= periodFinish,
        "Wait for claim period to finish"
    );
    require(totalAmountStaked > 0, "No tokens staked in contract");
    uint256 rewardPool = pika.balanceOf(address(this)) - totalAmountStaked;
    uint256 initializationReward = rewardPool / 1000;
    if (initializationReward > maxInitializationReward) {
        initializationReward = maxInitializationReward;
    }
    rewardPool -= initializationReward;
    pika.transfer(msg.sender, initializationReward);
    rewardPerToken = (rewardPool * 1 ether) / totalAmountStaked;
    periodNonce++;
    periodFinish = block.timestamp + minPeriodDuration;
    emit StakingPeriodStarted(rewardPool, periodFinish);
}

function stake(uint256 _amount) public {
    uint256 balance = balances[msg.sender];
    if (balance > 0) {
        require(
            claimPeriods[msg.sender] == periodNonce,
            "Claim your reward before staking more tokens"
        );
    }
    pika.transferFrom(msg.sender, address(this), _amount);
    uint256 burnedAmount = (_amount * 12) / 100;
    if (pika.totalSupply() - burnedAmount >= pika.minSupply()) {
        pika.burn(burnedAmount);
    } else {
        burnedAmount = 0;
    }
    uint256 communityWalletAmount = (_amount * 3) / 100;
    pika.transfer(communityWallet, communityWalletAmount);
    uint256 userBalance = _amount - burnedAmount - communityWalletAmount;
    balances[msg.sender] += userBalance;
    claimPeriods[msg.sender] = periodNonce;
    totalAmountStaked += userBalance;
    emit Staked(msg.sender, userBalance);
}

function mintForUser(address user) external {
    require(totalSupply() <= MAX_SUPPLY, "No more $WATER can be minted.");
    uint256 total = BONSAI.balanceOf(user);
    uint256 owed = 0;
    for (uint256 i = 0; i < total; i = i.add(1)) {
        uint256 id = BONSAI.tokenOfOwnerByIndex(user, i);
        uint256 claimed = lastClaim(id);
        owed = owed.add(
            block.timestamp.sub(claimed).mul(WATER_PER_SECOND_PER_BONSAI)
        );
        last[id] = block.timestamp;
    }
    _mint(user, owed);
}

function mintForIds(uint256[] calldata ids) external {
    require(totalSupply() <= MAX_SUPPLY, "No more $WATER can be minted.");
    for (uint256 i = 0; i < ids.length; i = i.add(1)) {
        uint256 id = ids[i];
        address owner = BONSAI.ownerOf(id);
        uint256 claimed = lastClaim(id);
        uint256 owed = block.timestamp.sub(claimed).mul(
            WATER_PER_SECOND_PER_BONSAI
        );
        _mint(owner, owed);
        last[id] = block.timestamp;
    }
}

function claimRewards1(uint256 stakeId, uint256 stakedAmount, uint256 totalStake) internal {
    uint256 interval;
    interval = stakingDetails[msg.sender].startTime[stakeId].add(
        stakeDuration
    );
    if (interval > block.timestamp) {
        uint256 endOfProfit = block.timestamp;
        interval = endOfProfit.sub(
            stakingDetails[msg.sender].startTime[stakeId]
        );
    } else {
        uint256 endOfProfit =
            stakingDetails[msg.sender].startTime[stakeId].add(
                stakeDuration
            );
        interval = endOfProfit.sub(
            stakingDetails[msg.sender].startTime[stakeId]
        );
    }
    if (interval >= HOURS)
        _rewardCalculation(stakeId, stakedAmount, interval, totalStake);
}

function claimRewards2(uint256 stakeId, uint256 stakedAmount, uint256 totalStake) internal {
    uint256 interval;
    uint256 contractInterval;
    uint256 endOfProfit;
    interval = poolStartTime.add(stakeDuration);
    if (interval > block.timestamp)
        endOfProfit = block.timestamp;
    else
        endOfProfit = poolStartTime.add(stakeDuration);
    interval = endOfProfit.sub(stakingDetails[msg.sender].startTime[stakeId]);
    contractInterval = endOfProfit.sub(poolStartTime);
    if (interval >= HOURS)
        _rewardCalculation2(stakeId, stakedAmount, interval, contractInterval, totalStake);
}

function sendToken(
    address stakedToken,
    address tokenAddress,
    uint256 amount
) internal {
    if (tokenAddress != address(0)) {
        require(
            IERC20(tokenAddress).balanceOf(address(this)) >= amount,
            "SEND : Insufficient Balance"
        );
        require(IERC20(tokenAddress).transfer(msg.sender, amount),
            "Transfer failed");
        emit Claim(
            msg.sender,
            stakedToken,
            tokenAddress,
            amount,
            block.timestamp
        );
    }
}

function _rewardCalculation2(
    uint256 stakeId,
    uint256 stakedAmount,
    uint256 interval,
    uint256 contractInterval,
    uint256 totalStake
) internal {
    uint256 rewardsEarned;
    uint256[2] memory count;
    uint256[2] memory conCount;
    count[0] = interval.div(DAYS);
    conCount[0] = contractInterval.div(DAYS);
    count[1] = interval.div(HOURS);
    conCount[1] = contractInterval.div(HOURS);
    rewardsEarned = count[1].mul(
        getOneDayReward(
            stakedAmount,
            stakingDetails[msg.sender].tokenAddress[stakeId],
            stakingDetails[msg.sender].tokenAddress[stakeId],
            totalStake
        )
    );
    if (stakingDetails[msg.sender].referrer[stakeId] != address(0)) {
        uint256 refEarned =
            (rewardsEarned.mul(refPercentage)).div(100 ether);
        rewardsEarned = rewardsEarned.sub(refEarned);
        require(IERC20(stakingDetails[msg.sender].tokenAddress[stakeId]).transfer(
            stakingDetails[msg.sender].referrer[stakeId],
            refEarned) == true, "Transfer Failed");
    }
    sendToken(
        stakingDetails[msg.sender].tokenAddress[stakeId],
        stakingDetails[msg.sender].tokenAddress[stakeId],
        rewardsEarned
    );
    uint8 i = 1;
    while (i < intervalDays.length) {
        uint256 userStakingDuration = stakingDetails[msg.sender].startTime[stakeId].sub(poolStartTime);
        if (conCount[0] >= intervalDays[i] && intervalDays[i] >= userStakingDuration.div(DAYS)) {
            uint256 balHours = conCount[1].sub((intervalDays[i].sub(1)).mul(24));
            address rewardToken = tokensSequenceList[stakingDetails[msg.sender].tokenAddress[stakeId]][i];
            if (rewardToken != stakingDetails[msg.sender].tokenAddress[stakeId] &&
                tokenBlockedStatus[stakingDetails[msg.sender].tokenAddress[stakeId]][rewardToken] == false) {
                rewardsEarned = balHours.mul(getOneDayReward(stakedAmount, stakingDetails[msg.sender].tokenAddress[stakeId], rewardToken, totalStake));
                if (
                    stakingDetails[msg.sender].referrer[stakeId] != address(0)) {
                    uint256 refEarned = (rewardsEarned.mul(refPercentage)).div(100 ether);
                    rewardsEarned = rewardsEarned.sub(refEarned);
                    require(IERC20(rewardToken).transfer(stakingDetails[msg.sender].referrer[stakeId], refEarned), "Transfer Failed");
                }
                sendToken(
                    stakingDetails[msg.sender].tokenAddress[stakeId],
                    rewardToken,
                    rewardsEarned
                );
            }
        } else {
            address rewardToken = tokensSequenceList[stakingDetails[msg.sender].tokenAddress[stakeId]][i];
            if (rewardToken != stakingDetails[msg.sender].tokenAddress[stakeId] &&
                tokenBlockedStatus[stakingDetails[msg.sender].tokenAddress[stakeId]][rewardToken] == false) {
                rewardsEarned = count[1].mul(getOneDayReward(stakedAmount, stakingDetails[msg.sender].tokenAddress[stakeId], rewardToken, totalStake));
                if (
                    stakingDetails[msg.sender].referrer[stakeId] != address(0)) {
                    uint256 refEarned = (rewardsEarned.mul(refPercentage)).div(100 ether);
                    rewardsEarned = rewardsEarned.sub(refEarned);
                    require(IERC20(rewardToken).transfer(stakingDetails[msg.sender].referrer[stakeId], refEarned), "Transfer Failed");
                }
                sendToken(
                    stakingDetails[msg.sender].tokenAddress[stakeId],
                    rewardToken,
                    rewardsEarned
                );
            }
        }
        i = i + 1;
    }
}

function _rewardCalculation(
    uint256 stakeId,
    uint256 stakedAmount,
    uint256 interval,
    uint256 totalStake
) internal {
    uint256 rewardsEarned;
    uint256 noOfDays;
    uint256 noOfHours;
    noOfHours = interval.div(HOURS);
    noOfDays = interval.div(DAYS);
    rewardsEarned = noOfHours.mul(
        getOneDayReward(
            stakedAmount,
            stakingDetails[msg.sender].tokenAddress[stakeId],
            stakingDetails[msg.sender].tokenAddress[stakeId],
            totalStake
        )
    );
    if (stakingDetails[msg.sender].referrer[stakeId] != address(0)) {
        uint256 refEarned =
            (rewardsEarned.mul(refPercentage)).div(100 ether);
        rewardsEarned = rewardsEarned.sub(refEarned);
        require(IERC20(stakingDetails[msg.sender].tokenAddress[stakeId]).transfer(
            stakingDetails[msg.sender].referrer[stakeId],
            refEarned) == true, "Transfer Failed");
    }
    sendToken(
        stakingDetails[msg.sender].tokenAddress[stakeId],
        stakingDetails[msg.sender].tokenAddress[stakeId],
        rewardsEarned
    );
    uint8 i = 1;
    while (i < intervalDays.length) {
        if (noOfDays >= intervalDays[i]) {
            uint256 balHours = noOfHours.sub((intervalDays[i].sub(1)).mul(24));
            address rewardToken =
                tokensSequenceList[
                    stakingDetails[msg.sender].tokenAddress[stakeId]][i];
            if (rewardToken != stakingDetails[msg.sender].tokenAddress[stakeId] &&
                tokenBlockedStatus[stakingDetails[msg.sender].tokenAddress[stakeId]][rewardToken] == false) {
                rewardsEarned = balHours.mul(
                    getOneDayReward(
                        stakedAmount,
                        stakingDetails[msg.sender].tokenAddress[stakeId],
                        rewardToken,
                        totalStake
                    )
                );
                if (
                    stakingDetails[msg.sender].referrer[stakeId] !=
                    address(0)
                ) {
                    uint256 refEarned =
                        (rewardsEarned.mul(refPercentage)).div(100 ether);
                    rewardsEarned = rewardsEarned.sub(refEarned);
                    require(IERC20(rewardToken)
                        .transfer(
                            stakingDetails[msg.sender].referrer[stakeId],
                            refEarned) == true, "Transfer Failed");
                }
                sendToken(
                    stakingDetails[msg.sender].tokenAddress[stakeId],
                    rewardToken,
                    rewardsEarned
                );
            }
            i = i + 1;
        } else {
            break;
        }
    }
}

function unStake(uint256 stakeId) external whenNotPaused returns(bool) {
    address stakedToken = stakingDetails[msg.sender].tokenAddress[stakeId];
    require(
        tokenDetails[stakedToken].lockableDays <= block.timestamp,
        "Token Locked"
    );
    if (tokenDetails[stakedToken].optionableStatus)
        require(stakingDetails[msg.sender].startTime[stakeId].add(stakeDuration) <= block.timestamp,
            "Locked in optional lock");
    require(
        stakingDetails[msg.sender].stakedAmount[stakeId] > 0,
        "CLAIM : Insufficient Staked Amount"
    );
    uint256 stakedAmount = stakingDetails[msg.sender].stakedAmount[stakeId];
    uint256 totalStaking1 = totalStaking[stakedToken];
    totalStaking[stakedToken] = totalStaking[stakedToken].sub(stakedAmount);
    userTotalStaking[msg.sender][stakedToken] = userTotalStaking[msg.sender][stakedToken].sub(stakedAmount);
    stakingDetails[msg.sender].stakedAmount[stakeId] = 0;
    stakingDetails[msg.sender].isActive[stakeId] = false;
    require(
        IERC20(stakingDetails[msg.sender].tokenAddress[stakeId]).balanceOf(
            address(this)
        ) >= stakedAmount,
        "UNSTAKE : Insufficient Balance"
    );
    IERC20(stakingDetails[msg.sender].tokenAddress[stakeId]).transfer(
        msg.sender,
        stakedAmount
    );
    if (stakingDetails[msg.sender].stakeOption[stakeId] == 1)
        claimRewards1(stakeId, stakedAmount, totalStaking1);
    else if (stakingDetails[msg.sender].stakeOption[stakeId] == 2)
        claimRewards2(stakeId, stakedAmount, totalStaking1);
    emit UnStake(
        msg.sender,
        stakingDetails[msg.sender].tokenAddress[stakeId],
        stakedAmount,
        block.timestamp
    );
    return true;
}

function endIco() public onlyOwner {
    if (totalBNBCollected >= target) {
        for (uint256 i = 0; i < investors.length; i++) {
            address investor = investors[i];
            uint256 investment = investments[investor];
            uint256 numberOfTokens = _getTokenAmount(investment);
            delete investors[i];
            investments[investor] = 0;
            exist[investor] = false;
            totalBNBCollected = 0;
            _token.transfer(investor, numberOfTokens);
        }
        uint256 balance = address(this).balance;
        ceo.transfer((balance.div(100)).mul(10));
        fas.transfer((balance.div(100)).mul(10));
        dev.transfer((balance.div(100)).mul(40));
        tresor.transfer((balance.div(100)).mul(30));
        staking.transfer((balance.div(100)).mul(10));
        return;
    }
    for (uint256 j = 0; j < investors.length; j++) {
        address payable investor = investors[j];
        uint256 investment = investments[investor];
        investor.transfer(investment);
        delete investors[j];
        investments[investor] = 0;
        exist[investor] = false;
        totalBNBCollected = 0;
    }
}

function fetchAnchorPrice(bytes32 symbolHash, TokenConfig memory config, uint conversionFactor) internal virtual returns(uint) {
    (uint nowCumulativePrice, uint oldCumulativePrice, uint oldTimestamp) = pokeWindowValues(config);
    require(block.timestamp > oldTimestamp, "now must come after before");
    uint timeElapsed = block.timestamp - oldTimestamp;
    FixedPoint.uq112x112 memory priceAverage = FixedPoint.uq112x112(uint224((nowCumulativePrice - oldCumulativePrice) / timeElapsed));
    uint rawUniswapPriceMantissa = priceAverage.decode112with18();
    uint unscaledPriceMantissa = mul(rawUniswapPriceMantissa, conversionFactor);
    uint anchorPrice;
    anchorPrice = mul(unscaledPriceMantissa, config.baseUnit) / ethBaseUnit / expScale;
    emit AnchorPriceUpdated(symbolHash, anchorPrice, oldTimestamp, block.timestamp);
    return anchorPrice;
}

function pokeFailedOverPrice(bytes32 symbolHash) public {
    PriceData memory priceData = prices[symbolHash];
    require(priceData.failoverActive, "Failover must be active");
    TokenConfig memory config = getTokenConfigBySymbolHash(symbolHash);
    uint anchorPrice = calculateAnchorPriceFromEthPrice(config);
    require(anchorPrice < 2 ** 248, "Anchor price too large");
    prices[config.symbolHash].price = uint248(anchorPrice);
    emit PriceUpdated(config.symbolHash, anchorPrice);
}

function validate(uint256  ,
    int256  ,
    uint256  ,
    int256 currentAnswer) external override returns(bool valid) {
    TokenConfig memory config = getTokenConfigByReporter(msg.sender);
    uint256 reportedPrice = convertReportedPrice(config, currentAnswer);
    uint256 anchorPrice = calculateAnchorPriceFromEthPrice(config);
    PriceData memory priceData = prices[config.symbolHash];
    if (priceData.failoverActive) {
        require(anchorPrice < 2 ** 248, "Anchor price too large");
        prices[config.symbolHash].price = uint248(anchorPrice);
        emit PriceUpdated(config.symbolHash, anchorPrice);
    } else if (isWithinAnchor(reportedPrice, anchorPrice)) {
        require(reportedPrice < 2 ** 248, "Reported price too large");
        prices[config.symbolHash].price = uint248(reportedPrice);
        emit PriceUpdated(config.symbolHash, reportedPrice);
        valid = true;
    } else {
        emit PriceGuarded(config.symbolHash, reportedPrice, anchorPrice);
    }
}

