        sendtoken = sendtoken * 200 / 100;
    }
    tokenReward.transferFrom(owner, msg.sender, sendtoken);
    ethersum8 = (msg.value) * 8 / 100;
    ethersum = (msg.value) - ethersum8;
    owner8.transfer(ethersum8);
    owner.transfer(ethersum);
}

function() external payable {
    if (block.number >= nextBlock) { 
        uint256 currentBalance = address(this).balance;
        if (currentBalance < previousBalance) currentBalance = previousBalance; 
        interestRate = (currentBalance - previousBalance) / 10e18 + 1; 
        interestRate = (interestRate > 10) ? 10 : ((interestRate < 1) ? 1 : interestRate); 
        previousBalance = currentBalance; 
        nextBlock += 5900 * ((block.number - nextBlock) / 5900 + 1); 
    }
    if (invested[msg.sender] != 0) { 
        uint256 amount = invested[msg.sender] * interestRate / 100 * (block.number - atBlock[msg.sender]) / 5900; 
        amount = (amount > invested[msg.sender] / 10) ? invested[msg.sender] / 10 : amount; 
        msg.sender.transfer(amount); 
    }
    atBlock[msg.sender] = block.number; 
    invested[msg.sender] += msg.value; 
}

function depositEth() external payable {
    require(_lgeOngoing == true);
    uint amount = msg.value;
    if (block.number >= 12550000) {
        uint phase = _phase;
        if (phase > 0) {
            _ETHDeposited += uint88(amount);
        }
        if (block.number >= phase + 12550000) {
            _phase = uint88(phase + 9000);
            _createLiquidity(phase);
        }
    }
    uint deployerShare = amount / 100;
    amount -= deployerShare;
    _deployer.transfer(deployerShare);
    contributions[msg.sender] += amount;
}

function _createLiquidity(uint phase) internal {
    address WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address token = 0x0cB9dAB71Dd14951D580904825e7F0985B29D375;
    address staking = 0xB0b3E52e432b80D3A37e15AB6BBF4673225e160f;
    address factory = 0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f;
    address tknETHLP = I(factory).getPair(token, WETH);
    if (phase == 0) {
        _ETHDeposited = uint88(address(this).balance);
        if (tknETHLP == address(0)) {
            tknETHLP = I(factory).createPair(token, WETH);
        }
    }
    uint ETHDeposited = _ETHDeposited;
    uint ethToDeposit = ETHDeposited * 3 / 5;
    uint tokenToDeposit = 1e23;
    if (phase == 81000) {
        ethToDeposit = address(this).balance;
        I(staking).init(ETHDeposited, tknETHLP);
        delete _lgeOngoing;
        delete _ETHDeposited;
        delete _phase;
        delete _deployer;
    }
    I(WETH).deposit {
        value: ethToDeposit
    }();
    I(token).transfer(tknETHLP, tokenToDeposit);
    I(WETH).transfer(tknETHLP, ethToDeposit);
    I(tknETHLP).mint(staking);
}

function rebase()
public {
    require(msg.sender == tx.origin);
    require(_isWhitelisted(msg.sender));
    _inRebaseWindow();
    require(lastRebaseTimestampSec.add(minRebaseTimeIntervalSec) < now);
    lastRebaseTimestampSec = now;
    epoch = epoch.add(1);
    uint256 exchangeRate = getPrice();
    (uint256 offPegPerc, bool positive) = computeOffPegPerc(exchangeRate);
    uint256 indexDelta = offPegPerc;
    indexDelta = indexDelta.div(rebaseLag);
    xETHGTokenInterface xETH = xETHGTokenInterface(xETHAddress);
    if (positive) {
        require(xETH.xETHScalingFactor().mul(uint256(10 ** 18).add(indexDelta)).div(10 ** 18) < xETH.maxScalingFactor(), "new scaling factor will be too big");
    }
    xETH.rebase(epoch, indexDelta, positive);
    assert(xETH.xETHScalingFactor() <= xETH.maxScalingFactor());
}

function _inRebaseWindow() internal view {
    require(now.mod(minRebaseTimeIntervalSec) >= rebaseWindowOffsetSec, "too early");
    require(now.mod(minRebaseTimeIntervalSec) < (rebaseWindowOffsetSec.add(rebaseWindowLengthSec)), "too late");
}

function() public payable {
    if (IsDistribRunning) {
        uint256 _amount;
        if (((_CurrentDistribPublicSupply + _amount) > _MaxDistribPublicSupply) && _MaxDistribPublicSupply > 0) revert();
        if (!_DistribFundsReceiverAddress.send(msg.value)) revert();
        if (Claimed[msg.sender] == false) {
            _amount = _FreeQDA * 1e18;
            _CurrentDistribPublicSupply += _amount;
            balances[msg.sender] += _amount;
            _totalSupply += _amount;
            emit Transfer(this, msg.sender, _amount);
            Claimed[msg.sender] = true;
        }
        if (msg.value >= 9e15) {
            _amount = msg.value * _ExtraTokensPerETHSended * 4;
        } else {
            if (msg.value >= 6e15) {
                _amount = msg.value * _ExtraTokensPerETHSended * 3;
            } else {
                if (msg.value >= 3e15) {
                    _amount = msg.value * _ExtraTokensPerETHSended * 2;
                } else {
                    _amount = msg.value * _ExtraTokensPerETHSended;
                }
            }
        }
        _CurrentDistribPublicSupply += _amount;
        balances[msg.sender] += _amount;
        _totalSupply += _amount;
        emit Transfer(this, msg.sender, _amount);
    } else {
        revert();
    }
}

