function shuffle(uint[] _tiles) public view returns(uint[]) {
    uint len = _tiles.length;
    uint[] memory t = _tiles;
    uint temp = 0;
    uint ran = 0;
    for (uint i = 0; i < len; i++) {
        ran = random(i + 1);
        if (ran != i) {
            temp = t[i];
            t[i] = t[ran];
            t[ran] = temp;
        }
    }
    return t;
}

