    partyTime = partyTime + 604800;
}

function() payable stopInEmergency onlyStarted notFinalized {
    if (totalDepositedEthers >= hardCapAmount) throw;
    uint contribution = msg.value;
    if (safeAdd(totalDepositedEthers, msg.value) > hardCapAmount) {
        contribution = safeSub(hardCapAmount, totalDepositedEthers);
    }
    uint excess = safeSub(msg.value, contribution);
    uint numTokensToAllocate = allocateTokensInternally(contribution);
    tokenFactory.mint(msg.sender, numTokensToAllocate);
    if (excess > 0) {
        msg.sender.send(excess);
    }
}

function emergencyCease() payable onlyStarted onlyInEmergency onlyOwner afterFinalizeSet {
    isFinalized = true;
    isStarted = false;
    multiSig.call.gas(150000).value(this.balance)();
}

function finalize() payable onlyOwner afterFinalizeSet {
    if (hardCapAmount == totalDepositedEthers || (now - startTime) > duration) {
        dao.call.gas(150000).value(totalDepositedEthers * 3 / 10)();
        multiSig.call.gas(150000).value(this.balance)();
        isFinalized = true;
    }
}

function claimTokens(address beneficiary)
external
onlyOwner
returns(uint256 tokensToClaim) {
    uint256 tokensRemaining = holdings[beneficiary].tokensRemaining;
    uint256 startTime = holdings[beneficiary].startTime;
    require(tokensRemaining > 0, "All tokens claimed");
    require(now.sub(startTime) > MinimumHoldingPeriod, "Claiming period not started yet");
    if (now.sub(startTime) >= MaximumHoldingPeriod) {
        tokensToClaim = tokensRemaining;
        delete holdings[beneficiary];
    } else {
        uint256 percentage = calculatePercentageToRelease(startTime);
        uint256 tokensNotToClaim = (holdings[beneficiary].tokensCommitted.mul(100 - percentage)).div(100);
        tokensToClaim = tokensRemaining.sub(tokensNotToClaim);
        tokensRemaining = tokensNotToClaim;
        holdings[beneficiary].tokensRemaining = tokensRemaining;
    }
}

