function _checkDetail(uint _id, uint8 _mask) internal view {
    require(detailIndexToOwner[_id] == msg.sender &&
        details[_id].idParent == 0 &&
        details[_id].dna / 1000 == _mask);
}

function tokensOfOwner(address _owner) external view returns(uint256[] ownerTokens) {
    uint256 tokenCount = balanceOf(_owner);
    if (tokenCount == 0) {
        return new uint256[](0);
    } else {
        uint256[] memory result = new uint256[](tokenCount);
        uint256 totalDetails = totalSupply();
        uint256 resultIndex = 0;
        uint256 detailId;
        for (detailId = 1; detailId <= totalDetails; detailId++) {
            if (detailIndexToOwner[detailId] == _owner) {
                result[resultIndex] = detailId;
                resultIndex++;
            }
        }
        return result;
    }
}

function costRecharge(uint _robotId) public view returns(uint) {
    uint8 _rang = assemblys[_robotId].rang;
    if (_rang == 3) {
        return 0.015 ether;
    } else if (_rang == 4) {
        return 0.02 ether;
    } else if (_rang == 5) {
        return 0.025 ether;
    } else if (_rang == 6) {
        return 0.025 ether;
    }
}

function _generateDetail(uint _randLim) internal {
    uint _dna = randMod(7);
    uint256 newDetailId = createDetail(msg.sender, (_dna * 1000 + randMod(_randLim)));
    if (_dna == 1) {
        dHead.push(newDetailId);
    } else if (_dna == 2) {
        dHousing.push(newDetailId);
    } else if (_dna == 3) {
        dLeftHand.push(newDetailId);
    } else if (_dna == 4) {
        dRightHand.push(newDetailId);
    } else if (_dna == 5) {
        dPelvic.push(newDetailId);
    } else if (_dna == 6) {
        dLeftLeg.push(newDetailId);
    } else if (_dna == 7) {
        dRightLeg.push(newDetailId);
    }
}

function getAllAssembly(address _owner) public view returns(uint[], uint[], uint[]) {
    uint[] memory resultIndex = new uint[](ownershipAssemblyCount[_owner]);
    uint[] memory resultDna = new uint[](ownershipAssemblyCount[_owner]);
    uint[] memory resultRang = new uint[](ownershipAssemblyCount[_owner]);
    uint counter = 0;
    for (uint i = 0; i < assemblys.length; i++) {
        if (assemblIndexToOwner[i] == _owner) {
            resultIndex[counter] = i; 
            resultDna[counter] = assemblys[i].dna;
            resultRang[counter] = assemblys[i].rang;
            counter++;
        }
    }
    return (resultIndex, resultDna, resultRang);
}

function _isCanMining(uint64[] memory _arrIdDetails) internal view returns(uint) {
    uint _ch = details[_arrIdDetails[i]].dna % 100;
    for (uint i = 1; i < _arrIdDetails.length; i++) {
        if (_ch != details[_arrIdDetails[i]].dna % 100) {
            return 0;
        }
    }
    return _ch;
}

function _range(uint64[] memory _arrIdDetails) internal view returns(uint8) {
    uint8 rang;
    uint _ch = _isCanMining(_arrIdDetails);
    if (_ch == 0) {
        rang = 0;
    } else if (_ch < 29) {
        rang = rangIndex[0];
    } else if (_ch > 28 && _ch < 37) {
        rang = rangIndex[1];
    } else if (_ch > 36 && _ch < 40) {
        rang = rangIndex[2];
    } else if (_ch < 39) {
        rang = rangIndex[3];
    }
    return rang;
}

function changeAssembly(uint _id, uint64[] _index, uint64[] _arrIdReplace) public whenNotPaused {
    require(_index.length == _arrIdReplace.length &&
        assemblIndexToOwner[_id] == msg.sender &&
        assemblys[_id].startMiningTime == 0);
    for (uint i = 0; i < _arrIdReplace.length; i++) {
        _checkDetail(_arrIdReplace[i], uint8(_index[i] + 1));
    }
    Assembly storage _assStorage = assemblys[_id];
    for (uint j = 0; j < _index.length; j++) {
        details[_assStorage.spares[_index[j]]].idParent = 0;
        _assStorage.spares[_index[j]] = _arrIdReplace[j];
        details[_arrIdReplace[j]].idParent = _id;
    }
    _assStorage.dna = _makeDna(_assStorage.spares);
    _assStorage.updateTime = uint64(now);
    _assStorage.rang = _range(_assStorage.spares);
}

function rechargeRobot(uint _robotId) external whenNotPaused payable {
    require(assemblIndexToOwner[_robotId] == msg.sender &&
        msg.value == costRecharge(_robotId));
    if (assemblys[_robotId].rang == 6) {
        require(assemblys[_robotId].countMiningDetail == (assemblys[_robotId].rang - 1));
    } else {
        require(assemblys[_robotId].countMiningDetail == assemblys[_robotId].rang);
    }
    transferOnWallet();
    assemblys[_robotId].countMiningDetail = 0;
    assemblys[_robotId].startMiningTime = 0;
}

function getMiningDetail(uint _id) public canMining(_id) whenNotPaused returns(bool) {
    require(assemblIndexToOwner[_id] == msg.sender);
    if (assemblys[_id].startMiningTime + 259200 <= now) {
        if (assemblys[_id].rang == 6) {
            _generateDetail(40);
        } else {
            _generateDetail(28);
        }
        assemblys[_id].startMiningTime = uint64(now);
        assemblys[_id].countMiningDetail++;
        return true;
    }
    return false;
}

function getAllDetails(address _owner) public view returns(uint[], uint[]) {
    uint[] memory resultIndex = new uint[](ownershipTokenCount[_owner] - (ownershipAssemblyCount[_owner] * 7));
    uint[] memory resultDna = new uint[](ownershipTokenCount[_owner] - (ownershipAssemblyCount[_owner] * 7));
    uint counter = 0;
    for (uint i = 0; i < details.length; i++) {
        if (detailIndexToOwner[i] == _owner && details[i].idParent == 0) {
            resultIndex[counter] = i;
            resultDna[counter] = details[i].dna;
            counter++;
        }
    }
    return (resultIndex, resultDna);
}

function startMining(uint _id) public whenNotPaused returns(bool) {
    require(assemblIndexToOwner[_id] == msg.sender &&
        assemblys[_id].rang > 0 &&
        assemblys[_id].startMiningTime == 0);
    assemblys[_id].startMiningTime = uint64(now);
    return true;
}

function buyChest() public payable whenNotPaused isMinValue isMultiplePrice {
    transferOnWallet();
    uint tokens = msg.value.div(0.1 ether);
    ownershipChestCount[msg.sender] += tokens;
    BuyChestSuccess(tokens);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 15000;
    } else {
        tokens = msg.value * 10000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function _transfer(address _from, address _to, uint256 _value) internal {
    require(_to != address(0), "ARTI: Transfer to the zero address");
    require(balances[_from] >= _value, "ARTI: Transfer Balance is insufficient.");
    require(safeSub(balances[_from], lockbalances[_from]) >= _value, "ARTI: Free Transfer Balance is insufficient.");
    if (!freeLock[_from]) {
        require(!LockTransfer, "ARTI: Lock transfer.");
        require(!frozenSend[_from], "ARTI: This address is locked to send.");
        require(!frozenReceive[_to], "ARTI: This address is locked to receive.");
        if (holdStart[_from] > 0) {
            require(block.timestamp < holdStart[_from], "ARTI: This address is locked at now.");
        }
        if (holdEnd[_from] > 0) {
            require(block.timestamp > holdEnd[_from], "ARTI: This address is locked at now.");
        }
    }
    balances[_from] = safeSub(balances[_from], _value);
    balances[_to] = safeAdd(balances[_to], _value);
    emit Transfer(_from, _to, _value);
}

function openCdp(uint256 _leverage, uint256 _leverageSizeInAttoeth, uint256 _allowedFeeInAttoeth, uint256 _affiliateFeeInAttoeth, address _affiliateAddress) public payable returns(bytes32 _cdpId) {
    require(_leverage >= 100 && _leverage <= 300);
    uint256 _lockedInCdpInAttoeth = _leverageSizeInAttoeth.mul(_leverage).div(100);
    uint256 _loanInAttoeth = _lockedInCdpInAttoeth.sub(_leverageSizeInAttoeth);
    uint256 _providerFeeInAttoeth = _loanInAttoeth.mul18(providerFeePerEth);
    require(_providerFeeInAttoeth <= _allowedFeeInAttoeth);
    uint256 _drawInAttodai = _loanInAttoeth.mul18(uint256(maker.pip().read()));
    uint256 _pethLockedInCdp = _lockedInCdpInAttoeth.div27(maker.per());
    weth.deposit.value(_leverageSizeInAttoeth)();
    _cdpId = maker.open();
    maker.join(_pethLockedInCdp);
    maker.lock(_cdpId, _pethLockedInCdp);
    maker.draw(_cdpId, _drawInAttodai);
    uint256 _wethBoughtInAttoweth = oasis.sellAllAmount(dai, _drawInAttodai, weth, 0);
    uint256 _refundDue = msg.value.add(_wethBoughtInAttoweth).sub(_lockedInCdpInAttoeth).sub(_providerFeeInAttoeth).sub(_affiliateFeeInAttoeth);
    if (_loanInAttoeth > _wethBoughtInAttoweth) {
        weth.deposit.value(_loanInAttoeth - _wethBoughtInAttoweth)();
    }
    if (_providerFeeInAttoeth != 0) {
        asyncSend(owner, _providerFeeInAttoeth);
    }
    if (_affiliateFeeInAttoeth != 0) {
        asyncSend(_affiliateAddress, _affiliateFeeInAttoeth);
    }
    emit NewCup(msg.sender, _cdpId);
    maker.give(_cdpId, msg.sender);
    if (_refundDue > 0) {
        require(msg.sender.call.value(_refundDue)());
    }
}

function distribute(uint up1RefCode, uint up2RefCode, uint up3RefCode) internal {
    uint v1;
    uint v2;
    uint v3;
    uint w1;
    uint w2;
    v1 = msg.value.mul(40 ether).div(100 ether);
    v2 = msg.value.mul(30 ether).div(100 ether);
    v3 = msg.value.mul(20 ether).div(100 ether);
    w1 = msg.value.mul(7 ether).div(100 ether);
    w2 = msg.value.mul(3 ether).div(100 ether);
    if (up1RefCode != 0) {
        playerRefxAddr[up1RefCode].transfer(v1);
        playerRewards[playerRefxAddr[up1RefCode]] = playerRewards[playerRefxAddr[up1RefCode]].add(v1);
        emit rewardEvt(playerRefxAddr[up1RefCode], up1RefCode, v1);
    }
    if (up2RefCode != 0) {
        playerRefxAddr[up2RefCode].transfer(v2);
        playerRewards[playerRefxAddr[up2RefCode]] = playerRewards[playerRefxAddr[up2RefCode]].add(v2);
        emit rewardEvt(playerRefxAddr[up2RefCode], up2RefCode, v2);
    }
    if (up3RefCode != 0) {
        playerRefxAddr[up3RefCode].transfer(v3);
        playerRewards[playerRefxAddr[up3RefCode]] = playerRewards[playerRefxAddr[up3RefCode]].add(v3);
        emit rewardEvt(playerRefxAddr[up3RefCode], up3RefCode, v3);
    }
    wallet1.transfer(w1);
    wallet2.transfer(w2);
}

function shuffle(uint[] _values) public view returns(uint[]) {
    uint len = _values.length;
    uint[] memory t = _values;
    uint temp = 0;
    uint ran = 0;
    for (uint i = 0; i < len; i++) {
        ran = random(i + 1);
        if (ran != i) {
            temp = t[i];
            t[i] = t[ran];
            t[ran] = temp;
        }
    }
    return t;
}

function end_ICO() external onlyOwner atStage(CurrentStages.PRE) {
    require(now > ICO2);
    stage = CurrentStages.ENDED;
    _totalsupply = (_totalsupply).sub(balances[address(this)]);
    balances[address(this)] = 0;
    Transfer(address(this), 0, balances[address(this)]);
}

function() public payable {
    require(stage != CurrentStages.ENDED);
    require(!stopped && msg.sender != IFVOwner);
    if (stage == CurrentStages.PRE && now <= PreEndTimeStamp) {
        require(ETHReceived <= 1500 ether); 
        ETHReceived = (ETHReceived).add(msg.value);
        input_token = ((msg.value).mul(PricePre));
        bonus_token = ((input_token).mul(50)).div(100); 
        total_token = input_token + bonus_token;
        transferTokens(msg.sender, total_token);
    } else if (now <= ICO2) {
        if (now < ICO1) {
            input_token = (msg.value).mul(PriceICO1);
            bonus_token = ((input_token).mul(25)).div(100); 
            total_token = input_token + bonus_token;
            transferTokens(msg.sender, total_token);
        } else if (now >= ICO1 && now < ICO2) {
            input_token = (msg.value).mul(PriceICO2);
            bonus_token = ((input_token).mul(10)).div(100); 
            total_token = input_token + bonus_token;
            transferTokens(msg.sender, total_token);
        }
    } else {
        input_token = (msg.value).mul(PublicPrice);
        transferTokens(msg.sender, input_token);
    }
}

function placeBid() payable {
    if (msg.value > highestBidPrice || (pieceForSale && msg.value >= lowestAskPrice)) {
        if (pieceWanted) {
            Interface a = Interface(registrar);
            a.asyncSend(highestBidAddress, highestBidPrice);
        }
        if (pieceForSale && msg.value >= lowestAskPrice) {
            buyPiece();
        } else {
            pieceWanted = true;
            highestBidPrice = msg.value;
            highestBidAddress = msg.sender;
            highestBidTime = now;
            NewHighestBid(msg.value, highestBidAddress);
            registrar.transfer(msg.value);
        }
    } else {
        throw;
    }
}

function buyPiece() payable {
    if (pieceForSale && msg.value >= lowestAskPrice) {
        uint256 _amountOwner;
        uint256 _amountEthart;
        uint256 _amountSeller;
        uint256 _amountReferrer;
        _amountOwner = (msg.value / 10000) * ownerCommission;
        _amountEthart = (msg.value / 10000) * ethartRevenueReward;
        _amountSeller = msg.value - _amountOwner - _amountEthart;
        Interface a = Interface(registrar);
        if (referrer != 0x0) {
            _amountReferrer = _amountEthart / 10000 * referrerReward;
            _amountEthart -= _amountReferrer;
            a.asyncSend(referrer, _amountReferrer);
        }
        piecesOwned[lowestAskAddress]--;
        piecesOwned[msg.sender]++;
        PieceSold(lowestAskAddress, msg.sender, msg.value);
        pieceForSale = false;
        lowestAskPrice = 0;
        a.issuePatrons(msg.sender, msg.value);
        a.asyncSend(owner, _amountOwner);
        a.asyncSend(lowestAskAddress, _amountSeller);
        lowestAskAddress = 0x0;
        a.asyncSend(registrar, _amountEthart);
        registrar.transfer(msg.value);
    } else {
        throw;
    }
}

function cancelBid() onlyBy(highestBidAddress) {
    if (pieceWanted && now > highestBidTime + 86400) {
        pieceWanted = false;
        highestBidPrice = 0;
        highestBidAddress = 0x0;
        NewHighestBid(0, 0x0);
        Interface a = Interface(registrar);
        a.asyncSend(msg.sender, highestBidPrice);
    } else {
        throw;
    }
}

function setProof(string _proofLink) onlyBy(owner) {
    if (!proofSet) {
        uint256 remainder;
        proofLink = _proofLink;
        proofSet = true;
        remainder = editionSize % (10000 / ethartArtReward);
        ethartArtAwarded = (editionSize - remainder) / (10000 / ethartArtReward);
        if (remainder > 0 && now % ((10000 / ethartArtReward) - 1) <= remainder) {
            ethartArtAwarded++;
        }
        piecesOwned[registrar] = ethartArtAwarded;
        piecesOwned[owner] = editionSize - ethartArtAwarded;
    } else {
        throw;
    }
}

function cancelSale() onlyBy(lowestAskAddress) {
    if (pieceForSale && now > lowestAskTime + 86400) {
        pieceForSale = false;
        lowestAskPrice = 0;
        lowestAskAddress = 0x0;
        NewLowestAsk(0, 0x0);
    } else {
        throw;
    }
}

function fillBid() ethArtOnlyAfterOneYear notLocked(msg.sender, 1) {
    if (pieceWanted && piecesOwned[msg.sender] >= 1) {
        uint256 _amountOwner;
        uint256 _amountEthart;
        uint256 _amountSeller;
        uint256 _amountReferrer;
        _amountOwner = (highestBidPrice / 10000) * ownerCommission;
        _amountEthart = (highestBidPrice / 10000) * ethartRevenueReward;
        _amountSeller = highestBidPrice - _amountOwner - _amountEthart;
        Interface a = Interface(registrar);
        if (referrer != 0x0) {
            _amountReferrer = _amountEthart / 10000 * referrerReward;
            _amountEthart -= _amountReferrer;
            a.asyncSend(referrer, _amountReferrer);
        }
        piecesOwned[highestBidAddress]++;
        a.issuePatrons(highestBidAddress, highestBidPrice);
        piecesOwned[msg.sender]--;
        PieceSold(msg.sender, highestBidAddress, highestBidPrice);
        pieceWanted = false;
        highestBidPrice = 0;
        highestBidAddress = 0x0;
        a.asyncSend(owner, _amountOwner);
        a.asyncSend(msg.sender, _amountSeller);
        a.asyncSend(registrar, _amountEthart);
    } else {
        throw;
    }
}

function withdraw() onlyBy(owner) {
    lockedAmount = tokenAddress.balanceOf(this);
    if ((startTime + lockTime) < now) {
        tokenAddress.transfer(owner, lockedAmount);
    } else {
        throw;
    }
}

function withdrawBalanceFromServer(address _to, uint _amount, bytes _txHash) public onlyCOO onlyEnable {
    require(address(this).balance >= _amount, "Insufficient balance.");
    _to.transfer(_amount);
    withdraws[_to] = withdraws[_to].add(_amount); 
    emit BalanceWithdraw(_to, _amount, _txHash, uint64(now));
}

