function _preValidatePurchase(address beneficiary, uint256 weiAmount) internal view {
    require(now >= _startDates[0]);
    require(now <= _endDates[3]);
    require(beneficiary != address(0));
    require(weiAmount >= _minPayment);
    require(_balances[address(this)] > 0);
}

function currentBonus() public view returns(uint256) {
    require(now >= _startDates[0] && now <= _endDates[3]);
    return _bonuses[currentStage()];
}

function burn() external onlyOwner {
    require(now > _endDates[3]);
    _burn(address(this), _balances[address(this)]);
}

function currentStage() public view returns(uint256) {
    require(now >= _startDates[0] && now <= _endDates[3]);
    if (now >= _startDates[0] && now <= _endDates[0]) return 0;
    if (now >= _startDates[1] && now <= _endDates[1]) return 1;
    if (now >= _startDates[2] && now <= _endDates[2]) return 2;
    if (now >= _startDates[3] && now <= _endDates[3]) return 3;
}

function unstake(uint256 _amount) public {
    StakerInfo storage user = stakerInfo[msg.sender];
    require(user.amount > 0, "E06");
    if (_amount > user.amount) {
        _amount = user.amount;
    }
    dnxcToken.transfer(
        msg.sender,
        _amount
    );
    user.amount = user.amount.sub(_amount);
    user.amounts.push(user.amount);
    user.times.push(block.timestamp);
}

function stake(uint256 _amount) public payable {
    require(paused == false, "E09");
    StakerInfo storage user = stakerInfo[msg.sender];
    require(user.amount.add(_amount) >= minimumStake, "E01");
    require(dnxcToken.transferFrom(msg.sender, address(this), _amount), "E02");
    if (user.startStakeTime == 0) {
        require(msg.value >= stakingFee, "E04");
        user.startStakeTime = block.timestamp;
    }
    user.amount = user.amount.add(_amount);
    user.amounts.push(user.amount);
    user.times.push(block.timestamp);
}

function _withdrawDividendOfUser(address payable user) internal returns(uint256) {
    uint256 _withdrawableDividend = withdrawableDividendOf(user);
    if (_withdrawableDividend > 0) {
        withdrawnDividends[user] = withdrawnDividends[user].add(_withdrawableDividend);
        emit DividendWithdrawn(user, _withdrawableDividend);
        bool success = IERC20(apecoin).transfer(user, _withdrawableDividend);
        if (!success) {
            withdrawnDividends[user] = withdrawnDividends[user].sub(_withdrawableDividend);
            return 0;
        }
        return _withdrawableDividend;
    }
    return 0;
}

function isActive() public view returns(bool) {
    return (
        initialized == true &&
        now >= START &&
        now <= START.add(DAYS * 1 days) &&
        goalReached() == false
    );
}

