function claimPrize(uint _gameId)
hasUserBet(_gameId)
public {
    address gambler = msg.sender;
    game = games[_gameId];
    bet = bets[gambler][_gameId];
    require(game.ended, "Game has not ended yet.");
    require(bet.result == game.result, "You did not win this game");
    require(!bet.isReverted, "You can not claim reverted bet");
    require(!bet.isClaimed, "You can not claim already claimed bet");
    bets[gambler][_gameId].isClaimed = true;
    uint winResultSum = 0;
    uint prize = 0;
    if (game.result == 1) {
        winResultSum = game.firstWinResultSum;
        prize = game.drawResultSum + game.secondWinResultSum;
    } else if (game.result == 2) {
        winResultSum = game.drawResultSum;
        prize = game.firstWinResultSum + game.secondWinResultSum;
    } else if (game.result == 3) {
        winResultSum = game.secondWinResultSum;
        prize = game.firstWinResultSum + game.drawResultSum;
    }
    uint gamblerPrize = prize.mul(bet.amount).mul(8).div(10).div(winResultSum);
    if (!bet.isFree) {
        gamblerPrize = bet.amount + gamblerPrize;
    }
    gambler.transfer(gamblerPrize);
    winResultSum = 0;
    prize = 0;
    gamblerPrize = 0;
    delete game;
    delete bet;
}

function investETH(address referral) public payable {
    require(msg.value >= 0.01 ether);
    if (getProfit(msg.sender) > 0) {
        uint256 profit = getProfit(msg.sender);
        lastInvest[msg.sender] = now;
        msg.sender.transfer(profit);
    }
    uint256 amount = msg.value;
    uint256 commision = SafeMath.div(amount, 20);
    if (referral != msg.sender && referral != 0x1 && referral != dev && referral != promoter) {
        affiliateCommision[referral] = SafeMath.add(affiliateCommision[referral], commision);
    }
    affiliateCommision[dev] = SafeMath.add(affiliateCommision[dev], commision);
    affiliateCommision[promoter] = SafeMath.add(affiliateCommision[promoter], commision);
    investedETH[msg.sender] = SafeMath.add(investedETH[msg.sender], amount);
    lastInvest[msg.sender] = now;
}

function updatePriceFromPair(address token) public returns(uint) {
    Observation storage obs = observations[token];
    uint32 lastObserved = obs.timestamp;
    require(lastObserved > 0, 'updatePriceFromPair/uninitialized');
    unchecked {
        uint32 timeElapsed = uint32(block.timestamp) - lastObserved; 
        if (timeElapsed < minTwapTime) {
            uint lastPrice = obs.lastPrice;
            require(lastPrice > 0, 'updatePriceFromPair/no-price');
            return lastPrice;
        }
        address pair = IUniswapV2Factory(factory).getPair(token, weth);
        uint currCumu = token < weth ? currentPrice0Cumu(pair) : currentPrice1Cumu(pair);
        uint224 price = uint224((currCumu - obs.lastCumu) / timeElapsed); 
        obs.lastPrice = price;
        obs.lastCumu = currCumu;
        obs.timestamp = uint32(block.timestamp);
        emit Observe(token, price);
        return price;
    }
}

function currentPrice1Cumu(address pair) public view returns(uint price1Cumu) {
    uint32 currTime = uint32(block.timestamp);
    price1Cumu = IUniswapV2Pair(pair).price1CumulativeLast();
    (uint reserve0, uint reserve1, uint32 lastTime) = IUniswapV2Pair(pair).getReserves();
    if (lastTime != currTime) {
        unchecked {
            uint32 timeElapsed = currTime - lastTime; 
            price1Cumu += uint((reserve0 << 112) / reserve1) * timeElapsed; 
        }
    }
}

function initPriceFromPair(address token) public {
    Observation storage obs = observations[token];
    require(obs.timestamp == 0, 'initPriceFromPair/already-initialized');
    address pair = IUniswapV2Factory(factory).getPair(token, weth);
    obs.lastCumu = token < weth ? currentPrice0Cumu(pair) : currentPrice1Cumu(pair);
    obs.lastPrice = 0;
    obs.timestamp = uint32(block.timestamp);
    emit Initialize(token);
}

function currentPrice0Cumu(address pair) public view returns(uint price0Cumu) {
    uint32 currTime = uint32(block.timestamp);
    price0Cumu = IUniswapV2Pair(pair).price0CumulativeLast();
    (uint reserve0, uint reserve1, uint32 lastTime) = IUniswapV2Pair(pair).getReserves();
    if (lastTime != currTime) {
        unchecked {
            uint32 timeElapsed = currTime - lastTime; 
            price0Cumu += uint((reserve1 << 112) / reserve0) * timeElapsed; 
        }
    }
}

