            _tmpP.dividendEarnings = _tmpP.dividendEarnings.add(_tmpP.jcTicketCount.mul(_eachMoney));
        }
        _tmpP.dlTicketCount = 0;
        _tmpP.xzTicketCount = 0;
        _tmpP.jcTicketCount = 0;
        _tmpP.ticketCount = 0;
    }
    _initSpaceship();
    totalTicketCount = 0;
    airdropPrizePool = 0;
