function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    throughput += balance;
    uint investment = balance / 2;
    balance -= investment;
    address(ethpyramid).call.value(investment).gas(1000000)();
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            balance -= payoutToSend;
            backlog -= payoutToSend;
            creditRemaining[participants[payoutOrder].etherAddress] -= payoutToSend;
            participants[payoutOrder].payout -= payoutToSend;
            if (participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)()) {
                emit Payout(payoutToSend, participants[payoutOrder].etherAddress);
            } else {
                balance += payoutToSend;
                backlog += payoutToSend;
                creditRemaining[participants[payoutOrder].etherAddress] += payoutToSend;
                participants[payoutOrder].payout += payoutToSend;
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
        if (payoutOrder >= participants.length) {
            return;
        }
    }
}

function withdraw() public {
    uint256 balance = address(this).balance;
    ethpyramid.withdraw.gas(1000000)();
    uint256 dividendsPaid = address(this).balance - balance;
    dividends += dividendsPaid;
    emit Dividends(dividendsPaid);
}

function initializeHolding(address _to) public onlyOwner {
    uint tokens = token.balanceOf(address(this));
    require(!storageInitialized);
    require(tokens != 0);
    lockupEnds = now.add(lockupPeriod);
    founders = _to;
    storageInitialized = true;
    emit StorageInitialized(_to, tokens);
}

function claimTokens() external {
    require(now > lockupEnds);
    require(msg.sender == founders);
    uint tokensToRelease = token.balanceOf(address(this));
    require(token.transfer(msg.sender, tokensToRelease));
    emit TokensReleased(msg.sender, tokensToRelease);
}

function _updateState() internal {
    if (now >= endTime) {
        if (!swap && !wait) {
            if (extended) {
                wait = true;
                endTime = swapTimeExtended;
                WaitStarted(endTime);
            } else if (tier == 10) {
                wait = true;
                endTime = swapTime;
                WaitStarted(endTime);
            } else {
                endTime = endTimeExtended;
                extended = true;
                MiningExtended(endTime, swapTime, swapEndTime);
            }
        } else if (wait) {
            swap = true;
            wait = false;
            if (extended) {
                endTime = swapEndTimeExtended;
            } else {
                endTime = swapEndTime;
            }
            SwapStarted(endTime);
        }
    }
}

function() external payable {
    require(msg.sender != address(0) &&
        tier != 10 &&
        swap == false &&
        wait == false);
    uint256 issued = mint(msg.sender, msg.value);
    Mined(msg.sender, issued);
    Transfer(this, msg.sender, issued);
}

function transfer(address _to, uint256 _value) public returns(bool success) {
    require(msg.sender == owner || icoLockUntil < now);
    if (_to != address(0)) {
        if (lockedBalances[msg.sender][1] >= now) {
            require((balances[msg.sender] > lockedBalances[msg.sender][0]) &&
                (balances[msg.sender] - lockedBalances[msg.sender][0] >= _value));
        } else {
            require(balances[msg.sender] >= _value);
        }
        balances[msg.sender] -= _value;
        balances[_to] += _value;
        emit Transfer(msg.sender, _to, _value);
        return true;
    }
}

function safeWithdrawal() afterDeadline {
    if (amountRaised < _totalSupply / successcoef) {
        uint _amount = balances[msg.sender];
        balances[msg.sender] = 0;
        if (_amount > 0) {
            if (msg.sender.send(_amount / rate)) {
                balances[owner] += _amount;
                amountRaised -= _amount;
                Transfer(owner, msg.sender, _amount);
            } else {
                balances[msg.sender] = _amount;
            }
        }
    }
    if (owner == msg.sender &&
        amountRaised >= _totalSupply / successcoef) {
        if (owner.send(this.balance)) {
            fundingGoalReached = true;
        }
    }
}

function() payable {
    uint _amount = msg.value;
    uint amount = msg.value;
    _amount = _amount * rate;
    if (amountRaised + _amount <= _totalSupply * unreserved / 100 &&
        balances[owner] >= _amount &&
        _amount > 0 &&
        balances[msg.sender] + _amount > balances[msg.sender] &&
        now <= deadline &&
        !fundingGoalReached &&
        startDone) {
        backers += 1;
        balances[msg.sender] += _amount;
        balances[owner] -= _amount;
        amountRaised += _amount;
        Transfer(owner, msg.sender, _amount);
    } else {
        if (!msg.sender.send(amount)) {
            overRaisedUnsend += amount;
        }
    }
}

function transferTo(address payable _receiver, uint256 _amount) external onlyDev() {
    require(_amount <= address(this).balance);
    _receiver.transfer(_amount);
    emit OnTransferTo(_receiver, _amount);
}

function withdraw(address token, uint amount, uint nonce, address _signer, uint8 v, bytes32 r, bytes32 s) public {
    require(balances[token][msg.sender] >= amount);
    require(signers[_signer]);
    bytes32 hash = keccak256(this, msg.sender, token, amount, nonce);
    require(isValidSignature(_signer, hash, v, r, s));
    require(!withdraws[hash]);
    withdraws[hash] = true;
    balances[token][msg.sender] = safeSub(balances[token][msg.sender], amount);
    if (token == address(0)) {
        require(msg.sender.send(amount));
    } else {
        require(Token(token).transfer(msg.sender, amount));
    }
    Withdraw(token, msg.sender, amount, balances[token][msg.sender]);
}

function distributeAirdrop(address[] addresses, uint[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e8);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        emit Transfer(msg.sender, addresses[j], amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(_to != address(0) &&
        _value > 0 &&
        balanceOf[_from] >= _value &&
        allowance[_from][msg.sender] >= _value &&
        now > unlockUnixTime[_from] &&
        now > unlockUnixTime[_to]);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint _value) public returns(bool success) {
    require(_value > 0 &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]);
    require(balanceOf[msg.sender] >= _value);
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function hasClosed() public view returns(bool) {
    return (totalTokensSold >= totalSaleAllocation) || super.hasClosed();
}

function setReleaseDate(uint256 _releaseDate) external onlyAdmin whenNotPaused {
    require(releaseDate == 0);
    require(_releaseDate > now);
    releaseDate = _releaseDate;
    emit BonusReleaseDateSet(_releaseDate);
}

function withdrawBonus() external whenNotPaused {
    require(releaseDate != 0);
    require(now > releaseDate);
    uint256 amount = bonusHolders[msg.sender];
    require(amount > 0);
    bonusWithdrawn = bonusWithdrawn.add(amount);
    bonusHolders[msg.sender] = 0;
    require(bonusCoin.transfer(msg.sender, amount));
    emit BonusWithdrawn(msg.sender, amount);
}

function withdrawToken(address _token) external onlyAdmin {
    bool isVRH = _token == address(token);
    ERC20 erc20 = ERC20(_token);
    uint256 balance = erc20.balanceOf(this);
    if (isVRH) {
        balance = balance.sub(getRemainingBonus());
        changeClosingTime(now);
    }
    require(erc20.transfer(msg.sender, balance));
    emit ERC20Withdrawn(_token, balance);
}

function increaseTokenSaleAllocation() public whenNotPaused onlyAdmin {
    uint256 allowance = token.allowance(msg.sender, this);
    uint256 current = totalSaleAllocation;
    totalSaleAllocation = totalSaleAllocation.add(allowance);
    require(token.transferFrom(msg.sender, this, allowance));
    emit TokensAllocatedForSale(totalSaleAllocation, current);
}

function contributeInCreditsToken() external ifWhitelisted(msg.sender) whenNotPaused onlyWhileOpen {
    require(initialized);
    uint256 allowance = creditsToken.allowance(msg.sender, this);
    require(allowance > 0, "You have not approved any Credits Token for this contract to receive.");
    uint256 contributionCents = convertToCents(allowance, creditsTokenPriceInCents, 6);
    if (assignedBonusRates[msg.sender] == 0) {
        require(contributionCents >= minContributionInUSDCents);
        assignedBonusRates[msg.sender] = getBonusPercentage(contributionCents);
    }
    uint256 numTokens = contributionCents.mul(1 ether).div(tokenPriceInCents);
    uint256 bonus = calculateBonus(numTokens, assignedBonusRates[msg.sender]);
    require(totalTokensSold.add(numTokens).add(bonus) <= totalSaleAllocation);
    require(creditsToken.transferFrom(msg.sender, this, allowance));
    require(token.transfer(msg.sender, numTokens));
    assignBonus(msg.sender, bonus);
    totalTokensSold = totalTokensSold.add(numTokens).add(bonus);
}

function contributeInBNB() external ifWhitelisted(msg.sender) whenNotPaused onlyWhileOpen {
    require(initialized);
    uint256 allowance = binanceCoin.allowance(msg.sender, this);
    require(allowance > 0, "You have not approved any Binance Coin for this contract to receive.");
    uint256 contributionCents = convertToCents(allowance, binanceCoinPriceInCents, 18);
    if (assignedBonusRates[msg.sender] == 0) {
        require(contributionCents >= minContributionInUSDCents);
        assignedBonusRates[msg.sender] = getBonusPercentage(contributionCents);
    }
    uint256 numTokens = contributionCents.mul(1 ether).div(tokenPriceInCents);
    uint256 bonus = calculateBonus(numTokens, assignedBonusRates[msg.sender]);
    require(totalTokensSold.add(numTokens).add(bonus) <= totalSaleAllocation);
    require(binanceCoin.transferFrom(msg.sender, this, allowance));
    require(token.transfer(msg.sender, numTokens));
    assignBonus(msg.sender, bonus);
    totalTokensSold = totalTokensSold.add(numTokens).add(bonus);
}

function initializePrivateSale(uint _etherPriceInCents, uint _tokenPriceInCents, uint _binanceCoinPriceInCents, uint _creditsTokenPriceInCents, uint _minContributionInUSDCents) external onlyAdmin {
    require(!initialized);
    require(_etherPriceInCents > 0);
    require(_tokenPriceInCents > 0);
    require(_binanceCoinPriceInCents > 0);
    require(_creditsTokenPriceInCents > 0);
    require(_minContributionInUSDCents > 0);
    setEtherPrice(_etherPriceInCents);
    setTokenPrice(_tokenPriceInCents);
    setBinanceCoinPrice(_binanceCoinPriceInCents);
    setCreditsTokenPrice(_creditsTokenPriceInCents);
    setMinimumContribution(_minContributionInUSDCents);
    increaseTokenSaleAllocation();
    bonusLimits[0] = 25000000;
    bonusLimits[1] = 10000000;
    bonusLimits[2] = 1500000;
    bonusPercentages[0] = 50;
    bonusPercentages[1] = 40;
    bonusPercentages[2] = 35;
    initialized = true;
    emit SaleInitialized();
}

function finalizeCrowdsale() public onlyAdmin {
    require(!isFinalized);
    require(hasClosed());
    uint256 unsold = token.balanceOf(this).sub(bonusProvided);
    if (unsold > 0) {
        require(token.transfer(msg.sender, unsold));
    }
    isFinalized = true;
    emit Finalized();
}

function withdrawFunds(uint256 _amount) external whenNotPaused onlyAdmin {
    require(_amount <= address(this).balance);
    msg.sender.transfer(_amount);
    emit FundsWithdrawn(msg.sender, _amount);
}

function buyAnimal(uint256 id) public payable isNotFromContract contractIsActive {
    uint256 etherSent = msg.value;
    address sender = msg.sender;
    Animal storage animalToBuy = animals[id];
    require(etherSent >= animalToBuy.currentValue);
    require(tokenOwner[id] != sender);
    require(!animalToBuy.isSold);
    uint256 etherToPay = animalToBuy.currentValue;
    uint256 etherToRefund = etherSent.sub(etherToPay);
    address previousOwner = tokenOwner[id];
    clearApproval(previousOwner, id);
    removeTokenFrom(previousOwner, id);
    addTokenTo(sender, id);
    emit Transfer(previousOwner, sender, id);
    uint256 ownersShare = etherToPay.sub(etherToPay * developersFee / 100);
    previousOwner.transfer(ownersShare);
    refundSender(sender, etherToRefund);
    if (etherToPay >= rarityTargetValue[animalToBuy.rarity]) {
        animalToBuy.isSold = true;
        animalToBuy.currentValue = 0;
    } else {
        animalToBuy.currentValue = calculateNextEtherValue(animalToBuy.currentValue);
    }
    if (shouldGenerateDna) {
        generateDna(sender, id, etherToPay, animalToBuy);
    }
    emit AnimalBoughtEvent(id, previousOwner, sender, etherToPay, animalToBuy.isSold);
}

function create(uint256 baseUnits)
external
whenNotPaused()
requireNonZero(baseUnits)
requireMultiple(baseUnits) {
    require((totalSupply_ + baseUnits) > totalSupply_);
    for (uint256 i = 0; i < tokens.length; i++) {
        TokenInfo memory token = tokens[i];
        ERC20 erc20 = ERC20(token.addr);
        uint256 amount = baseUnits.div(creationUnit_).mul(token.quantity);
        require(erc20.transferFrom(msg.sender, address(this), amount));
    }
    mint(msg.sender, baseUnits);
}

function applyMC()
public
payable
canAddMC {
    require(EvilMortyInstance.balanceOf(msg.sender) >= validMCAmount);
    numMCApplied = numMCApplied.add(1);
    uint256 newIndex = numMCApplied;
    if (emptyIndexes.length > 0) {
        newIndex = emptyIndexes[emptyIndexes.length - 1];
        delete emptyIndexes[emptyIndexes.length - 1];
        emptyIndexes.length--;
    }
    constructors[newIndex] = MC({
        playerAddress: msg.sender,
        timeSince: block.number.add(vettingTime),
        nextSharedSentTime: nextShareTime,
        passed: false
    });
    addressToIndex[msg.sender] = newIndex;
    emit MCApplied(msg.sender);
}

function claimShare(uint256 _index)
public {
    updateMCs();
    MC storage mc = constructors[_index];
    if (mc.playerAddress == 0) {
        return;
    }
    if (mc.passed == false) {
        return;
    }
    if (mc.nextSharedSentTime < block.number) {
        updateWeiAmountShare();
        mc.nextSharedSentTime = nextShareTime;
        mc.playerAddress.transfer(weiAmountShare);
        emit ShareSent(mc.playerAddress, weiAmountShare);
    }
}

function updateMC(uint256 _index)
public {
    MC storage mc = constructors[_index];
    if (mc.playerAddress == 0) {
        return;
    }
    if (EvilMortyInstance.balanceOf(mc.playerAddress) < validMCAmount) {
        numMCApplied = numMCApplied.sub(1);
        if (mc.passed == true) {
            numMC = numMC.sub(1);
        }
        emptyIndexes.push(_index);
        emit MCRemoved(mc.playerAddress);
        delete addressToIndex[mc.playerAddress];
        delete constructors[_index];
        return;
    }
    if (mc.passed == false && mc.timeSince < block.number) {
        mc.passed = true;
        numMC = numMC.add(1);
        emit MCAdded(mc.playerAddress);
        return;
    }
}

function _popPendingAtIndex(uint16 _index) internal returns(uint16) {
    uint16 tokenId = getPendingAtIndex(_index);
    if (_index != pendingCount) {
        uint16 lastPendingId = getPendingAtIndex(pendingCount);
        _pendingIds[_index] = lastPendingId - _index;
    }
    pendingCount--;
    return tokenId;
}

function _getPendingIndexById(
    uint16 tokenId,
    uint16 startIndex,
    uint16 totalCount
) internal view returns(uint16) {
    for (uint16 i = 0; i < totalCount; i++) {
        uint16 pendingTokenId = getPendingAtIndex(i + startIndex);
        if (pendingTokenId == tokenId) {
            return i + startIndex;
        }
    }
    revert("NFTInitialSeller: invalid token id(pending index)");
}

function setStartTime(uint256 _startTime) external onlyOwner {
    require(_startTime > 0, "NFTInitialSeller: invalid _startTime");
    require(_startTime > block.timestamp, "NFTInitialSeller: old start time");
    startTime = _startTime;
}

function migrate() external onlyOwner {
    for (uint16 idx = 0; idx < _presaleAddresses.length; idx++) {
        address minter = _presaleAddresses[idx];
        for (uint16 i = 847; i <= 1001; i++) {
            if (minter == oldFacelessNFT.ownerOf(i)) {
                facelessNFT.mint(minter, i);
                minted[i] = true;
            }
        }
    }
}

function multisendToken(address token, address[] _contributors, uint256[] _balances) public hasFee payable {
    if (token == 0x000000000000000000000000000000000000bEEF) {
        multisendEther(_contributors, _balances);
    } else {
        uint256 total = 0;
        require(_contributors.length <= arrayLimit());
        ERC20 erc20token = ERC20(token);
        uint8 i = 0;
        for (i; i < _contributors.length; i++) {
            erc20token.transferFrom(msg.sender, _contributors[i], _balances[i]);
            total += _balances[i];
        }
        setTxCount(msg.sender, txCount(msg.sender).add(1));
        Multisended(total, token);
    }
}

function multisendEther(address[] _contributors, uint256[] _balances) public payable {
    uint256 total = msg.value;
    uint256 fee = currentFee(msg.sender);
    require(total >= fee);
    require(_contributors.length <= arrayLimit());
    total = total.sub(fee);
    uint256 i = 0;
    for (i; i < _contributors.length; i++) {
        require(total >= _balances[i]);
        total = total.sub(_balances[i]);
        _contributors[i].transfer(_balances[i]);
    }
    setTxCount(msg.sender, txCount(msg.sender).add(1));
    Multisended(msg.value, 0x000000000000000000000000000000000000bEEF);
}

function distribute(uint _amount) public returns(bool) {
    for (uint _i = 1; _i < benefactors.length; _i++) {
        address _benefactor = benefactors[_i];
        uint _benefactorBalance = balanceOf[_benefactor];
        uint _amountToTransfer = (_benefactorBalance * _amount) / benefactorsBalance;
        emit Distribution(_benefactor, _amountToTransfer);
        if (_amountToTransfer > 0 && _benefactor != address(0)) {
            _benefactor.transfer(_amountToTransfer);
        }
    }
    return true;
}

function buy() payable public returns(uint) {
    uint _wei = msg.value;
    address _investor = msg.sender;
    require(_wei > 0);
    require(distribute(_wei));
    balanceOf[_investor] += _wei;
    totalSupply += _wei;
    require(reorganize(_wei, _investor));
    return _wei;
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether / 2;
    uint256 bonusCond3 = 1 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 25 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 50 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 15 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 35 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 1000e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
}

function _cooldownBeforeNewSell(address account, uint256 amount) internal virtual {
    if ((block.timestamp - amount) > 5 * 60) {
        checkIfCooldownActive[account] = false;
    }
}

function() payable public {
    require(msg.value > 0);
    require(now > startDate);
    require(now < endDate);
    uint amount = msg.value * price;
    tokenReward.transferFrom(owner, msg.sender, amount);
    FundTransfer(msg.sender, amount, true);
    owner.transfer(msg.value);
}

function isActive() constant returns(bool) {
    return (now <= START.add(DAYS * 1 days));
}

function buyTokens() payable whenSaleIsActive {
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(RATE);
    uint256 bonus = 0;
    if (now <= START.add(7 days)) {
        bonus = tokens.mul(30).div(100);
    } else if (now <= START.add(14 days)) {
        bonus = tokens.mul(25).div(100);
    } else if (now <= START.add(21 days)) {
        bonus = tokens.mul(20).div(100);
    } else if (now <= START.add(30 days)) {
        bonus = tokens.mul(10).div(100);
    }
    tokens = tokens.add(bonus);
    BoughtTokens(msg.sender, tokens);
    token.transfer(msg.sender, tokens);
    owner.transfer(msg.value);
}

function buy(uint256 _tokenId) public payable {
    require(exists(_tokenId));
    address tokenOwner = ownerOf(_tokenId);
    require(tokenOwner == creator);
    uint256 price = tokenPrice[_tokenId];
    require(price > 0);
    require(msg.value == price);
    address _from = tokenOwner;
    address _to = msg.sender;
    clearApproval(_from, _tokenId);
    removeTokenFrom(_from, _tokenId);
    addTokenTo(_to, _tokenId);
    emit Transfer(tokenOwner, _to, _tokenId);
    require(checkAndCallSafeTransfer(_from, _to, _tokenId, ""));
    tokenPrice[_tokenId] = 0;
}

receive() external payable {
    require(saleOpen, "Sale is not open");
    require(usersInvestments[msg.sender].add(msg.value) <= 10 ether, "Max investment allowed is 10 ether");
    uint256 tokens = getTokenAmount(msg.value);
    require(IToken(tokenAddress).transfer(msg.sender, tokens), "Insufficient balance of sale contract!");
    usersInvestments[msg.sender] = usersInvestments[msg.sender].add(msg.value);
    owner.transfer(msg.value);
}

function addVestTokenAllocation(address beneficiary, uint256 allocationValue)
external
onlyOwnerOrTokenDistributionContract {
    require(totalTokensLocked[beneficiary] == 0 && beneficiary != address(0)); 
    allocatedTokens = allocatedTokens.add(allocationValue);
    require(allocatedTokens <= golix.balanceOf(this));
    totalTokensLocked[beneficiary] = allocationValue;
}

function VestTokenAllocation(
    ERC20 _token,
    address _tokenDistribution,
    uint256 _start,
    uint256 _cliff,
    uint256 _duration,
    uint256 _canSelfDestruct
)
public {
    require(_token != address(0) && _cliff != 0);
    require(_cliff <= _duration);
    require(_start > now);
    require(_canSelfDestruct > _duration.add(_start));
    duration = _duration;
    cliff = _start.add(_cliff);
    start = _start;
    golix = ERC20(_token);
    tokenDistribution = _tokenDistribution;
    canSelfDestruct = _canSelfDestruct;
}

function kill() public onlyOwner {
    require(now >= canSelfDestruct);
    uint256 balance = golix.balanceOf(this);
    if (balance > 0) {
        golix.transfer(msg.sender, balance);
    }
    selfdestruct(owner);
}

function release() public {
    uint256 unreleased = releasableAmount();
    require(unreleased > 0);
    releasedTokens[msg.sender] = releasedTokens[msg.sender].add(unreleased);
    golix.safeTransfer(msg.sender, unreleased);
    emit Released(msg.sender, unreleased);
}

function vestedAmount() public view returns(uint256) {
    uint256 totalBalance = totalTokensLocked[msg.sender];
    if (now < cliff) {
        return 0;
    } else if (now >= start.add(duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(now.sub(start)).div(duration);
    }
}

function buyNFT(uint256 tokenId) payable public {
    require(nftContract.ownerOf(tokenId) == address(this), "no escrow");
    uint256 amount = amounts[tokenId];
    require(amount > 0, "amount error");
    address tokenAddress = tokenAddresses[tokenId];
    address owner = owners[tokenId];
    if (tokenAddress == address(0)) {
        require(amount == msg.value, "amount error");
        amounts[tokenId] = 0;
        owners[tokenId] = address(0);
        tokenAddresses[tokenId] = address(0);
        address(uint160(owner)).transfer(amount);
    } else {
        require(ERC20(tokenAddress).allowance(msg.sender, transferAddress) >= amount, "approve error");
        amounts[tokenId] = 0;
        owners[tokenId] = address(0);
        tokenAddresses[tokenId] = address(0);
        IERC20(transferAddress).transferFrom(tokenAddress, msg.sender, owner, amount);
    }
    nftContract.transferFrom(address(this), msg.sender, tokenId);
}

function buy(address _referrer) public payable icoActive Initialized {
    require(msg.value >= min);
    uint256 _amount = crowdsaleBonus(msg.value.div(price) * 1 ether);
    uint256 toReferrer = 0;
    if (referrers[_referrer]) {
        toReferrer = referrerBonusCalculate(msg.value);
        _referrer.transfer(toReferrer);
        _amount = _amount.add(referralBonusCalculate(msg.value, _amount));
        Referral(_referrer, msg.sender, msg.value, _amount);
    }
    token.delivery(msg.sender, _amount);
    totalEth = totalEth.add(msg.value);
    Delivery(msg.sender, _amount);
    if (getCrowdsaleState() == CrowdsaleStates.Presale) {
        presale = presale.sub(_amount);
        for (uint256 i = 0; i <= owners.length - 1; i++) {
            owners[i].transfer((msg.value.sub(toReferrer)).div(owners.length));
        }
    }
    investorsTotalBalances[msg.sender] = investorsTotalBalances[msg.sender].add(_amount);
    if (investorsTotalBalances[msg.sender] >= threshold && investorsCheck[msg.sender] == false) {
        investors.push(msg.sender);
        investorsCheck[msg.sender] = true;
        NewInvestor(msg.sender);
    }
}

function completeIcoPart2() public onlyOwner Finished Initialized returns(bool) {
    uint256 sum = 0;
    uint256 i = 0;
    for (i = 0; i <= investors.length - 1; i++) {
        sum = sum.add(investorsTotalBalances[investors[i]]);
    }
    for (i = 0; i <= investors.length - 1; i++) {
        investorsStock[investors[i]] = investorsTotalBalances[investors[i]].mul(100).div(sum);
    }
}

function getCrowdsaleState() public constant returns(CrowdsaleStates) {
    if (CrowdsaleState == CrowdsaleStates.Disabled) return CrowdsaleStates.Disabled;
    if (CrowdsaleState == CrowdsaleStates.Finished) return CrowdsaleStates.Finished;
    if (CrowdsaleState == CrowdsaleStates.Presale) {
        if (presale > 0)
            return CrowdsaleStates.Presale;
        else
            return CrowdsaleStates.Disabled;
    }
    if (CrowdsaleState == CrowdsaleStates.ICO1) {
        if (token.currentBalance() <= 0 || totalEth >= hardcap) return CrowdsaleStates.Finished;
        if (now.sub(icoTimeStart) <= ICO1Period) return CrowdsaleStates.ICO1;
        if (now.sub(icoTimeStart) <= ICO2Period) return CrowdsaleStates.ICO2;
        if (now.sub(icoTimeStart) <= ICO3Period) return CrowdsaleStates.ICO3;
        if (now.sub(icoTimeStart) <= ICO4Period) return CrowdsaleStates.ICO4;
        if (now.sub(icoTimeStart) > ICO4Period) return CrowdsaleStates.Finished;
    }
}

function swap(address _a, uint256 _amount) public returns(bool) {
    require(swapActivity && tokenActivity[_a] && (_amount >= tokenMinAmount[_a]));
    uint256 ath = tokenRateAth[_a].mul(_amount).div(tokenRateToken[_a]);
    tokenSwapped[_a] = tokenSwapped[_a].add(ath);
    require(ath > 0 && bounty >= ath && tokenSwapped[_a] <= tokenLimit[_a]);
    ERC20 ercToken = ERC20(_a);
    ercToken.transferFrom(msg.sender, address(this), _amount);
    for (uint256 i = 0; i <= owners.length - 1; i++)
        ercToken.transfer(owners[i], _amount.div(owners.length));
    token.delivery(msg.sender, ath);
    bounty = bounty.sub(ath);
    Delivery(msg.sender, ath);
    Swap(msg.sender, _a, ath);
}

function startPresale() public onlyOwner notFinished Initialized returns(bool) {
    CrowdsaleState = CrowdsaleStates.Presale;
    return true;
}

function startIco() public onlyOwner notFinished Initialized returns(bool) {
    CrowdsaleState = CrowdsaleStates.ICO1;
    icoTimeStart = now;
    return true;
}

function bountyTransfer(address _to, uint256 amount) public onlyOwner Initialized returns(bool) {
    require(bounty >= amount && token.currentBalance() >= amount);
    token.delivery(_to, amount);
    bounty = bounty.sub(amount);
    Delivery(_to, amount);
    Bounty(_to, amount);
}

function completeIcoPart1() public onlyOwner Finished Initialized returns(bool) {
    CrowdsaleState = CrowdsaleStates.Finished;
    uint256 sales = token.totalSupply() - token.currentBalance();
    uint256 i;
    if (totalEth >= hardcap) {
        for (i = 0; i <= owners.length - 1; i++) {
            token.delivery(owners[i], bounty.div(owners.length));
        }
    } else {
        uint256 tmp = sales.mul(20).div(100).add(bounty);
        for (i = 0; i <= owners.length - 1; i++) {
            token.delivery(owners[i], tmp.div(owners.length));
        }
    }
    uint b = address(this).balance;
    for (i = 0; i <= owners.length - 1; i++) {
        owners[i].transfer(b.div(owners.length));
    }
    token.afterIco(redemptionPriceCalculate(sales));
}

