    if (contributionOf[msg.sender] <= 0) {
        contributors.push(msg.sender);
        token.freeze(msg.sender);
    }
    contributionOf[msg.sender] = contributionOf[msg.sender].add(weiAmount);
    token.transfer(msg.sender, numToken);
