function payInterests() isUnlocked public {
    if (fortnightsFromLast() == 0) { 
        emit Message("0 fortnights passed");
        return;
    }
    uint amountToPay = calculateInterest(msg.sender);
    if (amountToPay == 0) {
        emit Message("There are not 150 tokens with interests to pay");
        return;
    }
    lastFortnightPayed[msg.sender] = now;
    require(token.transferFrom(tokenSpender, msg.sender, amountToPay));
}

function interest(uint _batchDate) private view returns(uint _interest) {
    uint _age = secToDays(softSub(now, _batchDate)); 
    while (_age >= 106) { 
        _age = _age - 103; 
    }
    if (_age < 3) return 0;
    if (_age > 91) return 0;
    uint _tokenFortnights = _age / fortNight;
    uint _fortnightsFromLast = fortnightsFromLast();
    if (_tokenFortnights > _fortnightsFromLast) _tokenFortnights = _fortnightsFromLast;
    uint yearsNow = secToDays(now - initialDate) / 365; 
    if (yearsNow > 3) yearsNow = 3;
    _interest = 1 ether * yearlyInterest[yearsNow] * _tokenFortnights / 24; 
}

function softSub(uint x, uint y) private pure returns(uint z) {
    z = x - y;
    if (z > x) z = 0;
}

function calculateInterest(address _address) private returns(uint _amount) {
    uint totalAmount = 0; 
    uint tokenCounted; 
    uint intBatch; 
    uint batchInterest; 
    uint batchAmount;
    uint batchDate;
    for (uint i = token.minIndex(_address); i < token.maxIndex(_address); i++) {
        (batchAmount, batchDate) = token.getBatch(_address, i); 
        intBatch = interest(batchDate); 
        batchInterest = batchAmount * intBatch / 1 ether / 100; 
        if (intBatch > 0) tokenCounted += batchAmount; 
        totalAmount += batchInterest; 
        emit Batch(
            batchAmount,
            secToDays(softSub(now, batchDate)),
            batchInterest
        );
    }
    if (tokenCounted >= 150 ether) return totalAmount;
    else return 0;
}

function contribute(
    address _contributor,
    uint256 _contributionLimitUnits,
    uint256 _payloadExpiration,
    bytes _sig
)
external
payable
checkAllowed
isWhitelisted(keccak256(
    abi.encodePacked(
        _contributor,
        _contributionLimitUnits,
        _payloadExpiration
    )
), _sig) {
    require(msg.sender == _contributor);
    require(now < _payloadExpiration);
    uint256 weiPerUnitRate = ethPriceFeed.getRate();
    require(weiPerUnitRate != 0);
    uint256 previouslyContributedUnits = unitContributions[_contributor];
    uint256 currentContributionUnits = min256(
        _contributionLimitUnits.sub(previouslyContributedUnits),
        totalSaleCapUnits.sub(totalContributedUnits),
        msg.value.div(weiPerUnitRate)
    );
    require(currentContributionUnits != 0);
    require(currentContributionUnits >= minContributionUnits || previouslyContributedUnits != 0);
    unitContributions[_contributor] = previouslyContributedUnits.add(currentContributionUnits);
    totalContributedUnits = totalContributedUnits.add(currentContributionUnits);
    uint256 currentContributionWei = currentContributionUnits.mul(weiPerUnitRate);
    trustedVault.deposit.value(currentContributionWei)(msg.sender);
    if (totalContributedUnits >= minThresholdUnits &&
        trustedVault.state() != Vault.State.Success) {
        trustedVault.saleSuccessful();
    }
    uint256 excessWei = msg.value.sub(currentContributionWei);
    if (excessWei > 0) {
        msg.sender.transfer(excessWei);
    }
    emit Contribution(
        _contributor,
        msg.sender,
        currentContributionUnits,
        currentContributionWei,
        excessWei,
        weiPerUnitRate
    );
    uint256 tokenAmount = currentContributionUnits.mul(saleTokensPerUnit);
    trustedToken.safeTransfer(_contributor, tokenAmount);
    emit TokensAllocated(_contributor, tokenAmount);
}

function onSaleEnded() internal {
    trustedToken.transferOwnership(owner);
    if (totalContributedUnits == 0) {
        trustedToken.safeTransfer(trustedVault.trustedWallet(), tokensForSale);
    } else if (totalContributedUnits < minThresholdUnits) {
        trustedVault.enableRefunds();
    } else {
        extraTokensPerUnit = tokensForSale.div(totalContributedUnits).sub(saleTokensPerUnit);
        trustedVault.close();
        trustedVault.transferOwnership(owner);
    }
}

function setup() external onlyOwner checkAllowed {
    trustedToken.safeTransfer(disbursementHandler, disbursementHandler.totalAmount());
    tokensForSale = trustedToken.balanceOf(this);
    require(tokensForSale >= totalSaleCapUnits);
    saleTokensPerUnit = tokensForSale.div(totalSaleCapUnits);
    goToNextState();
}

function setStateStartTime(bytes32 _stateId, uint256 _timestamp) internal {
    require(block.timestamp < _timestamp);
    if (startTime[_stateId] == 0) {
        addStartCondition(_stateId, hasStartTimePassed);
    }
    startTime[_stateId] = _timestamp;
    emit StateStartTimeSet(_stateId, _timestamp);
}

function setEndTime(uint256 _endTime) external onlyOwner checkAllowed {
    require(now < _endTime);
    require(getStateStartTime(SALE_ENDED) == 0);
    setStateStartTime(SALE_ENDED, _endTime);
}

constructor(
    uint256 _totalSaleCapUnits, 
    uint256 _minContributionUnits, 
    uint256 _minThresholdUnits, 
    uint256 _maxTokens,
    address _whitelistAdmin,
    address _wallet,
    uint256 _vaultInitialDisburseWei, 
    uint256 _vaultDisbursementWei, 
    uint256 _vaultDisbursementDuration,
    uint256 _startTime,
    string _tokenName,
    string _tokenSymbol,
    uint8 _tokenDecimals,
    EthPriceFeedI _ethPriceFeed
)
Whitelistable(_whitelistAdmin)
public {
    require(_totalSaleCapUnits != 0);
    require(_maxTokens != 0);
    require(_wallet != 0);
    require(_minThresholdUnits <= _totalSaleCapUnits);
    require(_ethPriceFeed != address(0));
    require(now < _startTime);
    totalSaleCapUnits = _totalSaleCapUnits;
    minContributionUnits = _minContributionUnits;
    minThresholdUnits = _minThresholdUnits;
    trustedToken = new Token(
        _maxTokens,
        _tokenName,
        _tokenSymbol,
        _tokenDecimals
    );
    disbursementHandler = new DisbursementHandler(trustedToken);
    ethPriceFeed = _ethPriceFeed;
    trustedToken.setController(this);
    trustedVault = new Vault(
        _wallet,
        _vaultInitialDisburseWei,
        _vaultDisbursementWei, 
        _vaultDisbursementDuration
    );
    setStates(states);
    allowFunction(SETUP, this.setup.selector);
    allowFunction(FREEZE, this.setEndTime.selector);
    allowFunction(SALE_IN_PROGRESS, this.setEndTime.selector);
    allowFunction(SALE_IN_PROGRESS, this.contribute.selector);
    allowFunction(SALE_IN_PROGRESS, this.endSale.selector);
    allowFunction(SALE_ENDED, this.allocateExtraTokens.selector);
    addStartCondition(SALE_ENDED, wasCapReached);
    setStateStartTime(SALE_IN_PROGRESS, _startTime);
    addCallback(SALE_ENDED, onSaleEnded);
}

function hasStartTimePassed(bytes32 _stateId) internal returns(bool) {
    return startTime[_stateId] <= block.timestamp;
}

function takeTaxes(address from, address to, uint256 amount) internal returns(uint256) {
    uint256 currentFee;
    if (from == lpPair) {
        if (balanceOf(to) > 0) {
            require(block.timestamp - buyLog[to] >= buyCoolDown, "Buy cooldown");
        }
        buyLog[to] = block.timestamp;
        currentFee = _buyFee;
    } else if (to == lpPair) {
        currentFee = _sellFee;
    } else {
        currentFee = _transferFee;
    }
    if (_hasLimits(from, to)) {
        if (_liqAddStatus == 0 || _liqAddStatus != 69_420) {
            revert();
        }
    }
    uint256 burnAmt = (amount * currentFee * _burnRatio) / (_burnRatio + _liquidityWalletRatios) / masterTaxDivisor;
    uint256 feeAmount = (amount * currentFee / masterTaxDivisor) - burnAmt;
    _tOwned[DEAD] += burnAmt;
    _tOwned[address(this)] += (feeAmount);
    emit Transfer(from, DEAD, burnAmt);
    emit Transfer(from, address(this), feeAmount);
    return amount - feeAmount - burnAmt;
}

function getCoinAge(address _address, uint _now) internal view returns(uint _coinAge) {
    if (transferIns[_address].length <= 0) return 0;
    for (uint i = 0; i < transferIns[_address].length; i++) {
        if (_now < uint(transferIns[_address][i].time).add(stakeMinAge)) continue;
        uint nCoinSeconds = _now.sub(uint(transferIns[_address][i].time));
        if (nCoinSeconds > stakeMaxAge) nCoinSeconds = stakeMaxAge;
        _coinAge = _coinAge.add(uint(transferIns[_address][i].amount).mul(nCoinSeconds).div(1 days));
    }
}

function setStakeStartTime(uint timestamp) onlyOwner public {
    require((stakeStartTime <= 0) && (timestamp >= chainStartTime));
    stakeStartTime = timestamp;
}

function getReward(address _address) internal view returns(uint reward) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint64 _now = uint64(now);
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    reward = _coinAge.mul(50).div(1000).div(365);
    return reward;
}

function transfer(address _to, uint _value, bytes _data, string _custom_fallback) public returns(bool success) {
    require(_value > 0);
    if (isContract(_to)) {
        require(balanceOf[msg.sender] >= _value);
        balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
        balanceOf[_to] = balanceOf[_to].add(_value);
        assert(_to.call.value(0)(bytes4(keccak256(_custom_fallback)), msg.sender, _value, _data));
        emit Transfer(msg.sender, _to, _value, _data);
        emit Transfer(msg.sender, _to, _value);
        if (transferIns[msg.sender].length > 0) delete transferIns[msg.sender];
        uint64 _now = uint64(now);
        transferIns[msg.sender].push(transferInStruct(uint256(balanceOf[msg.sender]), _now));
        transferIns[_to].push(transferInStruct(uint256(_value), _now));
        return true;
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

function transferToContract(address _to, uint _value, bytes _data) private returns(bool success) {
    require(balanceOf[msg.sender] >= _value);
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    ContractReceiver receiver = ContractReceiver(_to);
    receiver.tokenFallback(msg.sender, _value, _data);
    emit Transfer(msg.sender, _to, _value, _data);
    emit Transfer(msg.sender, _to, _value);
    if (transferIns[msg.sender].length > 0) delete transferIns[msg.sender];
    uint64 _now = uint64(now);
    transferIns[msg.sender].push(transferInStruct(uint256(balanceOf[msg.sender]), _now));
    transferIns[_to].push(transferInStruct(uint256(_value), _now));
    return true;
}

function executeTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public payable returns(bytes memory) {
    require(msg.sender == admin, "EliteTimelock::executeTransaction: Call must come from admin.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "EliteTimelock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "EliteTimelock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "EliteTimelock::executeTransaction: Transaction is stale.");
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call.value(value)(callData);
    require(success, "EliteTimelock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

function queueTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public returns(bytes32) {
    require(msg.sender == admin, "EliteTimelock::queueTransaction: Call must come from admin.");
    require(eta >= getBlockTimestamp().add(delay), "EliteTimelock::queueTransaction: Estimated execution block must satisfy delay.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

function joinFarmPool(uint256 liqudityTokenToFarm) public payable {
    uint256 userBalance = liqudityToken.balanceOf(msg.sender);
    require(userBalance >= liqudityTokenToFarm, "Insufficient tokens");
    bool isNewUser = info.users[msg.sender].liqudityBalance == 0;
    if (isNewUser) {
        liqudityToken.transferFrom(msg.sender, address(this), liqudityTokenToFarm);
        adjustTime();
        info.users[msg.sender].appliedFarmTokenCirculation = info.totalFarmSupply;
    } else {
        claimTokens();
        liqudityToken.transferFrom(msg.sender, address(this), liqudityTokenToFarm);
    }
    info.users[msg.sender].liqudityBalance += liqudityTokenToFarm;
}

function tokensToClaim(address _user) public view returns(uint256 tokensToTake) {
    uint256 countOfCoinsToAdd = ((now - info.coinCreationTime) / REBASE_TIME);
    uint256 realTotalSupply = (countOfCoinsToAdd * TOKEN_PRECISION);
    uint256 valueFromLiqudityHistory = info.users[_user].appliedFarmTokenCirculation / TOKEN_PRECISION;
    uint256 valueToLiqudityHistory = realTotalSupply / TOKEN_PRECISION;
    uint256[] memory myArray = new uint256[](valueToLiqudityHistory - valueFromLiqudityHistory);
    uint counter = 0;
    for (uint i = valueFromLiqudityHistory; i < valueToLiqudityHistory; i++) {
        myArray[counter] = historyOfLiqudity[i];
        if (historyOfLiqudity[i] == 0) {
            myArray[counter] = myArray[counter - 1];
        }
        counter++;
    }
    uint256 adjustedAddressBalance = 0;
    for (uint j = 0; j < counter; j++) {
        adjustedAddressBalance += ((TOKEN_PRECISION * info.users[_user].liqudityBalance) / myArray[j]);
    }
    return adjustedAddressBalance;
}

function claimTokens() public payable {
    adjustTime();
    uint256 valueFromLiqudityHistory = info.users[msg.sender].appliedFarmTokenCirculation / TOKEN_PRECISION;
    uint256 valueToLiqudityHistory = info.totalFarmSupply / TOKEN_PRECISION;
    uint256 farmTokenToClaim = 0;
    for (uint i = valueFromLiqudityHistory; i < valueToLiqudityHistory; i++) {
        if (historyOfLiqudity[i] == 0) {
            historyOfLiqudity[i] = historyOfLiqudity[i - 1];
        }
        farmTokenToClaim += ((TOKEN_PRECISION * info.users[msg.sender].liqudityBalance) / historyOfLiqudity[i]);
    }
    farmToken.transfer(msg.sender, farmTokenToClaim);
    info.users[msg.sender].appliedFarmTokenCirculation = info.totalFarmSupply;
}

function adjustTime() private {
    if (info.coinWorkingTime + REBASE_TIME < now) {
        uint256 countOfCoinsToAdd = ((now - info.coinCreationTime) / REBASE_TIME);
        info.coinWorkingTime = now;
        info.totalFarmSupply = (countOfCoinsToAdd * TOKEN_PRECISION);
    }
    uint256 position = info.totalFarmSupply / TOKEN_PRECISION;
    testPosition = position;
    historyOfLiqudity[position] = liqudityToken.balanceOf(address(this));
}

function leaveFarmPool(uint256 liqudityTokenFromFarm) public payable {
    uint256 userBalanceInPool = info.users[msg.sender].liqudityBalance;
    require(userBalanceInPool >= liqudityTokenFromFarm, "Insufficient tokens");
    claimTokens();
    liqudityToken.transfer(msg.sender, liqudityTokenFromFarm);
    info.users[msg.sender].liqudityBalance -= liqudityTokenFromFarm;
}

