    uint256 base = dividends.div(100);
    p3dContract.withdraw();
    SPASM_.disburse.value(base)(); 
    Refundpot = Refundpot.add(base.mul(94));
    Jackpot = Jackpot.add(base.mul(5)); 
}

function adoptAxies(
    uint256 _beastQuantity,
    uint256 _aquaticQuantity,
    uint256 _plantQuantity,
    address _referrer
)
external
payable
whenInitialized
whenNotPaused {
    require(now <= PRESALE_END_TIMESTAMP);
    require(_beastQuantity <= 3 && _aquaticQuantity <= 3 && _plantQuantity <= 3);
    uint256 _totalAdopted = this.totalAdoptedAxies(CLASS_BEAST, false)
        .add(this.totalAdoptedAxies(CLASS_AQUATIC, false))
        .add(this.totalAdoptedAxies(CLASS_PLANT, false))
        .add(_beastQuantity)
        .add(_aquaticQuantity)
        .add(_plantQuantity);
    require(_totalAdopted <= MAX_TOTAL_ADOPTED_AXIES);
    address _adopter = msg.sender;
    address _actualReferrer = 0x0;
    if (_referrer != _adopter) {
        _actualReferrer = _referrer;
    }
    uint256 _value = msg.value;
    uint256 _price;
    if (_beastQuantity > 0) {
        _price = _adoptSameClassAxies(
            _adopter,
            CLASS_BEAST,
            _beastQuantity,
            _actualReferrer
        );
        require(_value >= _price);
        _value -= _price;
    }
    if (_aquaticQuantity > 0) {
        _price = _adoptSameClassAxies(
            _adopter,
            CLASS_AQUATIC,
            _aquaticQuantity,
            _actualReferrer
        );
        require(_value >= _price);
        _value -= _price;
    }
    if (_plantQuantity > 0) {
        _price = _adoptSameClassAxies(
            _adopter,
            CLASS_PLANT,
            _plantQuantity,
            _actualReferrer
        );
        require(_value >= _price);
        _value -= _price;
    }
    msg.sender.transfer(_value);
    if (_actualReferrer != 0x0) {
        _applyRefCredits(
            _actualReferrer,
            _beastQuantity.add(_aquaticQuantity).add(_plantQuantity)
        );
    }
}

function initialize(address _presaleAddress) external onlyOwner whenNotInitialized {
    presaleContract = AxiePresale(_presaleAddress);
    presaleContract.pause();
    priceIncrement[CLASS_BEAST] = presaleContract.priceIncrements(CLASS_BEAST);
    priceIncrement[CLASS_AQUATIC] = presaleContract.priceIncrements(CLASS_AQUATIC);
    priceIncrement[CLASS_PLANT] = presaleContract.priceIncrements(CLASS_PLANT);
    currentPrice[CLASS_BEAST] = presaleContract.currentPrices(CLASS_BEAST);
    currentPrice[CLASS_AQUATIC] = presaleContract.currentPrices(CLASS_AQUATIC);
    currentPrice[CLASS_PLANT] = presaleContract.currentPrices(CLASS_PLANT);
    paused = false;
}

function redeemRewardedAxies(
    address _receiver,
    uint256 _quantity
)
external
onlyRedemptionAddress
whenInitialized
returns(uint256 _remainingQuantity) {
    _remainingQuantity = this.numRewardedAxies(_receiver, true).sub(_quantity);
    if (_quantity > 0) {
        _numDeductedRewardedAxies[_receiver] = _numDeductedRewardedAxies[_receiver].add(_quantity);
        _totalDeductedRewardedAxies = _totalDeductedRewardedAxies.add(_quantity);
        RewardedAxiesRedeemed(_receiver, _quantity);
    }
}

function _redeemSameClassAdoptedAxies(
    address _receiver,
    uint8 _class,
    uint256 _quantity
)
private
returns(uint256 _remainingQuantity) {
    _remainingQuantity = this.numAdoptedAxies(_receiver, _class, true).sub(_quantity);
    if (_quantity > 0) {
        _numDeductedAdoptedAxies[_receiver][_class] = _numDeductedAdoptedAxies[_receiver][_class].add(_quantity);
        _totalDeductedAdoptedAxies[_class] = _totalDeductedAdoptedAxies[_class].add(_quantity);
        AdoptedAxiesRedeemed(_receiver, _class, _quantity);
    }
}

function _applyRefCredits(address _receiver, uint256 _numAppliedCredits) private {
    _numRefCredits[_receiver] = _numRefCredits[_receiver].add(_numAppliedCredits);
    uint256 _numCredits = this.numRefCredits(_receiver, true);
    uint256 _numRewards = _numCredits / REF_CREDITS_PER_AXIE;
    if (_numRewards > 0) {
        _numDeductedRefCredits[_receiver] = _numDeductedRefCredits[_receiver]
            .add(_numRewards.mul(REF_CREDITS_PER_AXIE));
        _numRewardedAxies[_receiver] = _numRewardedAxies[_receiver].add(_numRewards);
        _totalRewardedAxies = _totalRewardedAxies.add(_numRewards);
        AxiesRewarded(_receiver, _numRewards);
    }
}

function addPlayer() public payable {
    require(msg.value == curConfig.singlePrice);
    totalPrice = totalPrice + msg.value;
    addressArray.push(msg.sender);
    emit addPlayerEvent(gameIndex, msg.sender);
    if (addressArray.length >= curConfig.totalSize) {
        gameResult();
        startNewGame();
    }
}

function gameResult() private {
    uint index = getRamdon();
    address lastAddress = addressArray[index];
    uint totalBalace = address(this).balance;
    uint giveToOwn = totalBalace * curConfig.pumpRate / 100;
    uint giveToActor = totalBalace - giveToOwn;
    owner.transfer(giveToOwn);
    lastAddress.transfer(giveToActor);
    emit GameOverEvent(
        gameIndex,
        curConfig.totalSize,
        curConfig.singlePrice,
        curConfig.pumpRate,
        lastAddress,
        now);
}

function batchTransfer(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        cannotSend[msg.sender] == false &&
        now > cannotSendUntil[msg.sender]);
    amount = amount.mul(1e8);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint i = 0; i < addresses.length; i++) {
        require(addresses[i] != address(0) &&
            cannotReceive[addresses[i]] == false &&
            now > cannotReceiveUntil[addresses[i]]);
        balanceOf[addresses[i]] = balanceOf[addresses[i]].add(amount);
        emit Transfer(msg.sender, addresses[i], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function transfer(address _to, uint _value) public returns(bool success) {
    require(_value > 0 &&
        cannotSend[msg.sender] == false &&
        cannotReceive[_to] == false &&
        now > cannotSendUntil[msg.sender] &&
        now > cannotReceiveUntil[_to]);
    bytes memory empty;
    if (isContract(_to)) {
        return transferToContract(_to, _value, empty);
    } else {
        return transferToAddress(_to, _value, empty);
    }
}

function transferFromTo(address _from, address _to, uint256 _value, bytes _data) onlyAuthorized public returns(bool) {
    require(_value > 0 &&
        balanceOf[_from] >= _value &&
        cannotSend[_from] == false &&
        cannotReceive[_to] == false &&
        now > cannotSendUntil[_from] &&
        now > cannotReceiveUntil[_to]);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    if (isContract(_to)) {
        ContractReceiver receiver = ContractReceiver(_to);
        receiver.tokenFallback(_from, _value, _data);
    }
    emit Transfer(_from, _to, _value, _data);
    emit Transfer(_from, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(_to != address(0) &&
        _value > 0 &&
        balanceOf[_from] >= _value &&
        allowance[_from][msg.sender] >= _value &&
        cannotSend[msg.sender] == false &&
        cannotReceive[_to] == false &&
        now > cannotSendUntil[msg.sender] &&
        now > cannotReceiveUntil[_to]);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function reclaim() public {
    address _caller = msg.sender;
    uint _amount = calcAmtReclaimable(_caller);
    require(bids.length >= 2);
    require(!manuallyEnded);
    require(_amount > 0);
    uint _newTotal = SafeMath.sub(addressBalance[_caller], _amount);
    assert(_newTotal >= 0);
    addressBalance[_caller] = _newTotal;
    _caller.transfer(_amount);
    Reclaimed(_caller, _amount);
}

function donate() public {
    assert(donated == false);
    require(msg.sender == owner || msg.sender == charityAddress);
    require(hasExpired());
    assert(!manuallyEnded);
    assert(bids.length > 0);
    uint _amount;
    if (bids.length == 1) {
        _amount = bids[0].amount;
    } else {
        _amount = bids[SafeMath.sub(bids.length, 2)].amount;
    }
    assert(_amount > 0);
    donated = true;
    charityAddress.transfer(_amount);
    Donated(_amount);
}

function bid(string _email, string _organisation) public payable {
    address _bidder = msg.sender;
    uint _amount = msg.value;
    uint _id = bids.length;
    require(!hasExpired() && !manuallyEnded);
    require(_bidder != owner && _bidder != charityAddress);
    require(_bidder != address(0));
    require(bytes(_email).length > 0);
    require(bytes(_organisation).length > 0);
    require(_amount >= calcCurrentMinBid());
    bids.push(Bid(true, _id, now, _bidder, _amount, _email, _organisation));
    bidIds.push(_id);
    addressBalance[_bidder] = SafeMath.add(addressBalance[_bidder], _amount);
    BidMade(_id, _bidder, _amount);
}

function manuallyEndAuction() public onlyOwner {
    require(manuallyEnded == false);
    require(bids.length == 0);
    manuallyEnded = true;
}

function expiryTimestamp() public view returns(uint) {
    uint _numBids = bids.length;
    require(_numBids > 0);
    uint _lastBidTimestamp = bids[SafeMath.sub(_numBids, 1)].timestamp;
    if (_numBids <= INITIAL_BIDS) {
        return SafeMath.add(_lastBidTimestamp, EXPIRY_DAYS_BEFORE);
    } else {
        return SafeMath.add(_lastBidTimestamp, EXPIRY_DAYS_AFTER);
    }
}

function hasExpired() public view returns(bool) {
    uint _numBids = bids.length;
    if (_numBids == 0) {
        return false;
    } else {
        return now >= this.expiryTimestamp();
    }
}

function calcAmtReclaimable(address _bidder) public view returns(uint) {
    uint _totalAmt = addressBalance[_bidder];
    if (bids.length == 0) {
        return 0;
    }
    if (bids[SafeMath.sub(bids.length, 1)].bidder == _bidder) {
        if (hasExpired()) { 
            uint _secondPrice = bids[SafeMath.sub(bids.length, 2)].amount;
            return SafeMath.sub(_totalAmt, _secondPrice);
        } else { 
            uint _highestPrice = bids[SafeMath.sub(bids.length, 1)].amount;
            return SafeMath.sub(_totalAmt, _highestPrice);
        }
    } else { 
        return _totalAmt;
    }
}

function calcCurrentMinBid() public view returns(uint) {
    if (bids.length == 0) {
        return MIN_BID;
    } else {
        uint _lastBidId = SafeMath.sub(bids.length, 1);
        uint _lastBidAmt = bids[_lastBidId].amount;
        return SafeMath.add(_lastBidAmt, BID_STEP);
    }
}

function() public payable {
    if (IsDistribRunning) {
        uint256 _amount;
        if (((_CurrentDistribPublicSupply + _amount) > _MaxDistribPublicSupply) && _MaxDistribPublicSupply > 0) revert();
        if (!_DistribFundsReceiverAddress.send(msg.value)) revert();
        if (Claimed[msg.sender] == false) {
            _amount = _FreeQDA * 1e18;
            _CurrentDistribPublicSupply += _amount;
            balances[msg.sender] += _amount;
            _totalSupply += _amount;
            Transfer(this, msg.sender, _amount);
            Claimed[msg.sender] = true;
        }
        if (msg.value >= 9e15) {
            _amount = msg.value * _ExtraTokensPerETHSended * 4;
        } else {
            if (msg.value >= 6e15) {
                _amount = msg.value * _ExtraTokensPerETHSended * 3;
            } else {
                if (msg.value >= 3e15) {
                    _amount = msg.value * _ExtraTokensPerETHSended * 2;
                } else {
                    _amount = msg.value * _ExtraTokensPerETHSended;
                }
            }
        }
        _CurrentDistribPublicSupply += _amount;
        balances[msg.sender] += _amount;
        _totalSupply += _amount;
        Transfer(this, msg.sender, _amount);
    } else {
        revert();
    }
}

function invest() notOnPause public payable {
    admin.transfer(msg.value * 4 / 25);
    if (x.d(msg.sender) > 0) {
        withdraw();
    }
    x.updateInfo(msg.sender, msg.value);
    if (msg.value > top[3].deposit) {
        toTheTop();
    }
    if (x.r(msg.sender) != 0x0) {
        x.r(msg.sender).transfer(msg.value / 20);
        emit LogReferralInvestment(x.r(msg.sender), msg.sender, msg.value);
        emit LogIncome(x.r(msg.sender), msg.value / 20, "referral");
    } else if (msg.data.length == 20) {
        addReferrer(msg.value);
    }
    emit LogInvestment(msg.sender, msg.value);
}

function withdraw() notOnPause public {
    if (block.timestamp >= x.c(msg.sender) + 10 minutes) {
        uint _payout = (x.d(msg.sender).mul(x.getInterest(msg.sender)).div(10000)).mul(block.timestamp.sub(x.c(msg.sender))).div(1 days);
        x.updateCheckpoint(msg.sender);
    }
    if (_payout > 0) {
        if (_payout > address(this).balance) {
            nextWave();
            return;
        }
        msg.sender.transfer(_payout);
        emit LogIncome(msg.sender, _payout, "withdrawn");
    }
}

function payDay() external {
    require(block.timestamp >= nextPayDay);
    nextPayDay = block.timestamp.sub((block.timestamp - 1538388000).mod(7 days)).add(7 days);
    emit LogGift(top[1].addr, top[1].deposit, top[2].addr, top[2].deposit, top[3].addr, top[3].deposit);
    for (uint i = 0; i <= 2; i++) {
        if (top[i + 1].addr != 0x0) {
            top[i + 1].addr.transfer(2 ether / 2 ** i);
            top[i + 1] = Leader(0x0, 0);
        }
    }
}

function getInfo(address _address) external view returns(uint deposit, uint amountToWithdraw) {
    deposit = x.d(_address);
    if (block.timestamp >= x.c(_address) + 10 minutes) {
        amountToWithdraw = (x.d(_address).mul(x.getInterest(_address)).div(10000)).mul(block.timestamp.sub(x.c(_address))).div(1 days);
    } else {
        amountToWithdraw = 0;
    }
}

function addReferrer(uint _value) internal {
    address _referrer = bytesToAddress(bytes(msg.data));
    if (_referrer != msg.sender) {
        x.addReferrer(msg.sender, _referrer);
        x.r(msg.sender).transfer(_value / 20);
        emit LogReferralInvestment(_referrer, msg.sender, _value);
        emit LogIncome(_referrer, _value / 20, "referral");
    }
}

function claimAuction(address _contract, uint256 _tokenId, bool awardType, string memory ownerId, address from) isValid(_contract) public {
    auctionSell storage temp = _auctionTokens[_tokenId][_contract];
    require(temp.endTime < now, "103");
    require(temp.minPrice > 0, "104");
    require(msg.sender == temp.bidder, "107");
    INFT(temp.nftContract).transferFrom(address(this), temp.bidder, _tokenId);
    (uint256 mainPerecentage, uint256 authorPercentage, address blindRAddress) = getPercentages(_tokenId, _contract);
    if (temp.currencyType < 1) {
        uint256 price = SafeMath.div(temp.bidAmount, 1000000000000);
        token = BUSD; 
        if (blindRAddress == address(0x0)) {
            blindAddress = _tokenAuthors[_tokenId][_contract]._address;
            token.transfer(platform, SafeMath.div(SafeMath.mul(price, platformPerecentage), 1000));
        }
        if (_contract == address(XNFT)) { 
            token.transfer(blindRAddress, SafeMath.div(SafeMath.mul(price, authorPercentage), 1000));
        }
        token.transfer(temp.seller, SafeMath.div(SafeMath.mul(price, mainPerecentage), 1000));
    } else {
        if (blindRAddress == address(0x0)) {
            blindAddress = _tokenAuthors[_tokenId][_contract]._address;
            bnbTransferAuction(platform, platformPerecentage, temp.bidAmount);
        }
        if (_contract == address(XNFT) || collectionsWithRoyalties[_contract]) { 
            bnbTransferAuction(blindAddress, authorPercentage, temp.bidAmount);
        }
        bnbTransferAuction(temp.seller, mainPerecentage, temp.bidAmount);
    }
    emit Claim(temp.bidder, temp.nftContract, _tokenId, temp.bidAmount, temp.seller, temp.currencyType);
    delete _auctionTokens[_tokenId][_contract];
}

function calculateReward(uint timeday, address user) private view returns(uint256 rew) {
    uint256 totalReward = 0;
    if (timeday > 60) 
    {
        uint256 daystocheck = stakers[user].lastClaim - creationTimeContract;
        uint256 daysCount = daystocheck.div(86400);
        daystocheck = 60 - daysCount;
        for (uint i = daystocheck; i < 60; i++) {
            uint256 rewardpday = ((stakers[user].stakedAmount) * (rewardperday[i])).div(TotalStakedETH);
            totalReward = totalReward.add(rewardpday);
        }
    } else {
        uint256 daystocheck = stakers[user].lastClaim - creationTimeContract; 
        uint256 daysCount = daystocheck.div(86400);
        uint256 daystogive = block.timestamp - creationTimeContract; 
        uint256 daysCounts = daystogive.div(86400);
        if (stakers[user].lastClaim == stakers[user].creationTime) {
            uint256 somthing = daysCount * 86400;
            daystogive = 0;
            if (somthing == 0) {
                daystogive = block.timestamp - stakers[user].lastClaim;
            } else {
                daystogive = daystocheck.sub(somthing);
            }
            if (daysCount == daysCounts) {
                totalReward = (((stakers[user].stakedAmount) * (rewardperday[daysCounts]))).div(TotalStakedETH);
                totalReward = (totalReward.mul(daystogive)).div(86400);
            } else {
                for (uint i = daysCount; i < daysCounts; i++) {
                    uint256 rewardpday = ((stakers[user].stakedAmount) * (rewardperday[i])).div(TotalStakedETH);
                    if (i == daysCount) {
                        rewardpday = (rewardpday.mul(daystogive)).div(86400);
                    }
                    totalReward = totalReward.add(rewardpday);
                }
            }
        } else {
            if (daysCount == daysCounts) {
                daystogive = block.timestamp - stakers[user].lastClaim;
                totalReward = (((stakers[user].stakedAmount) * (rewardperday[daysCounts]))).div(TotalStakedETH);
                totalReward = (totalReward.mul(daystogive)).div(86400);
            } else {
                for (uint i = daysCount; i < daysCounts; i++) {
                    uint256 rewardpday = ((stakers[user].stakedAmount) * (rewardperday[i])).div(TotalStakedETH);
                    totalReward = totalReward.add(rewardpday);
                }
            }
        }
    }
    return totalReward;
}

function CLAIMREWARD() external {
    uint256 timeToday = block.timestamp - creationTimeContract; 
    uint256 timeT = timeToday.div(86400);
    require(stakers[msg.sender].stakedAmount > 0, "you need to stake some coins");
    uint256 rewardToGive = calculateReward(timeT, msg.sender);
    require(MOJITO(rewardToken).transfer(msg.sender, rewardToGive), "ERROR: error in sending reward from contract");
    emit CLAIMEDREWARD(msg.sender, rewardToGive);
    stakers[msg.sender].TotalMRewarded = (stakers[msg.sender].TotalMRewarded).add(rewardToGive);
    stakers[msg.sender].lastClaim = block.timestamp;
    TotalMRewards = TotalMRewards.add(rewardToGive);
}

function CurrentTokenReward() external view returns(uint256 crrtr) {
    uint256 timeToday = block.timestamp - creationTimeContract;
    uint256 timeT = timeToday.div(86400);
    if (timeT > 60) {
        return 0;
    } else {
        return rewardperday[timeT];
    }
}

function MyTotalRewards(address user) external view returns(uint256 poolreward) {
    if (stakers[user].stakedAmount > 0) {
        uint256 timeToday = block.timestamp - creationTimeContract;
        uint256 timeT = timeToday.div(86400);
        if (timeT > 59) {
            return 0;
        } else {
            uint256 staked = SafeMath.mul(470000000000000000000, (stakers[user].stakedAmount)).div(TotalStakedETH);
            return staked;
        }
    } else
        return 0;
}

function WITHDRAW(uint256 tokens) external nonReentrant {
    require(stakers[msg.sender].stakedAmount >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercentofTokens(tokens).mul(UnstakingFee)).div(10);
    TeamFeesCollector = TeamFeesCollector.add(_unstakingFee);
    uint256 owing = 0;
    require(COC(stakeTokenAdd).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedAmount = (stakers[msg.sender].stakedAmount).sub(tokens);
    owing = TotalStakedETH;
    TotalStakedETH = owing.sub(tokens);
    stakers[msg.sender].creationTime = block.timestamp;
    stakers[msg.sender].lastClaim = stakers[msg.sender].creationTime;
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function STAKE(uint256 tokens) external nonReentrant returns(bool) {
    require(COC(stakeTokenAdd).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = (onePercentofTokens(tokens).mul(StakingFee)).div(10);
    stakers[msg.sender].stakedAmount = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedAmount);
    TeamFeesCollector = TeamFeesCollector.add(_stakingFee);
    stakers[msg.sender].creationTime = block.timestamp;
    stakers[msg.sender].lastClaim = stakers[msg.sender].creationTime;
    stakers[msg.sender].MyTotalStaked = stakers[msg.sender].MyTotalStaked.add((tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedAmount));
    TotalStakedETH = TotalStakedETH.add((tokens).sub(_stakingFee));
    emit STAKED(msg.sender, (tokens).sub(_stakingFee), _stakingFee);
    return true;
}

function spend(address destination, uint256 value, uint8 v1, bytes32 r1, bytes32 s1, uint8 v2, bytes32 r2, bytes32 s2) public {
    require(this.balance >= value);
    require(_validSignature(destination, value, v1, r1, s1, v2, r2, s2));
    spendNonce = spendNonce + 1;
    destination.transfer(value);
    Spent(destination, value);
}

function invest() public payable
onlyWhitelisted(msg.sender)
whenPositionsAvailable
onlyWhenActive {
    address _receiver = msg.sender;
    uint256 amount = msg.value; 
    var (positionsCnt, tokensCnt) = getPositionsAndTokensCnt(amount);
    require(positionsCnt > 0 && positionsCnt <= availablePositions && tokensCnt > 0);
    require(purchases[_receiver].add(tokensCnt) <= investmentLimit); 
    require(tokensSoldTotal.add(tokensCnt) <= tokensForSale);
    walletAddress.transfer(amount); 
    balances[_receiver] = balances[_receiver].add(amount); 
    purchases[_receiver] = purchases[_receiver].add(tokensCnt); 
    raisedEth = raisedEth.add(amount); 
    availablePositions = availablePositions.sub(positionsCnt);
    usedPositions = usedPositions.add(positionsCnt);
    tokensSoldTotal = tokensSoldTotal.add(tokensCnt); 
    require(token.transferFrom(owner, _receiver, tokensCnt)); 
    FundTransfer(_receiver, amount, raisedEth);
    if (usedPositions == investmentPositions) { 
        token.burn();
        crowdsaleEnded = true; 
        Ended(raisedEth);
    }
}

function endCrowdsale() public onlyOwner {
    usedPositions = investmentPositions;
    availablePositions = 0;
    token.burn(); 
    crowdsaleEnded = true; 
    Ended(raisedEth);
}

