}

function executeActionOnBridgedTokensOutOfLimit(address _recipient, uint256 _value) internal {
    bytes32 _messageId = messageId();
    address recipient;
    uint256 value;
    (recipient, value) = txAboveLimits(_messageId);
    require(recipient == address(0) && value == 0);
    setOutOfLimitAmount(outOfLimitAmount().add(_value));
    setTxAboveLimits(_recipient, _value, _messageId);
    emit MediatorAmountLimitExceeded(_recipient, _value, _messageId);
}

function passMessage(address _from, address _receiver, uint256 _value) internal {
    bytes4 methodSelector = this.handleBridgedTokens.selector;
    bytes memory data = abi.encodeWithSelector(methodSelector, _receiver, _value);
    bytes32 _messageId = bridgeContract().requireToPassMessage(
        mediatorContractOnOtherSide(),
        data,
        requestGasLimit()
    );
    setMessageValue(_messageId, _value);
    setMessageRecipient(_messageId, _from);
    emit TokensBridgingInitiated(_from, _value, _messageId);
}

function initialize(
    address _bridgeContract,
    address _mediatorContract,
    address _erc677token,
    uint256[3] _dailyLimitMaxPerTxMinPerTxArray, 
    uint256[2] _executionDailyLimitExecutionMaxPerTxArray, 
    uint256 _requestGasLimit,
    int256 _decimalShift,
    address _owner
) public onlyRelevantSender returns(bool) {
    require(!isInitialized());
    _setBridgeContract(_bridgeContract);
    _setMediatorContractOnOtherSide(_mediatorContract);
    setErc677token(_erc677token);
    _setLimits(_dailyLimitMaxPerTxMinPerTxArray);
    _setExecutionLimits(_executionDailyLimitExecutionMaxPerTxArray);
    _setRequestGasLimit(_requestGasLimit);
    _setDecimalShift(_decimalShift);
    _setOwner(_owner);
    setInitialize();
    return isInitialized();
}

function fixFailedMessage(bytes32 _messageId) external onlyMediator {
    require(!messageFixed(_messageId));
    address recipient = messageRecipient(_messageId);
    uint256 value = messageValue(_messageId);
    setMessageFixed(_messageId);
    executeActionOnFixedTokens(recipient, value);
    emit FailedMessageFixed(_messageId, recipient, value);
}

function fixAssetsAboveLimits(bytes32 messageId, bool unlockOnOtherSide, uint256 valueToUnlock)
external
onlyIfUpgradeabilityOwner {
    (address recipient, uint256 value) = txAboveLimits(messageId);
    require(recipient != address(0) && value > 0 && value >= valueToUnlock);
    setOutOfLimitAmount(outOfLimitAmount().sub(valueToUnlock));
    uint256 pendingValue = value.sub(valueToUnlock);
    setTxAboveLimitsValue(pendingValue, messageId);
    emit AssetAboveLimitsFixed(messageId, valueToUnlock, pendingValue);
    if (unlockOnOtherSide) {
        require(valueToUnlock <= maxPerTx());
        passMessage(recipient, recipient, valueToUnlock);
    }
}

function handleBridgedTokens(address _recipient, uint256 _value) external onlyMediator {
    if (withinExecutionLimit(_value)) {
        addTotalExecutedPerDay(getCurrentDay(), _value);
        executeActionOnBridgedTokens(_recipient, _value);
    } else {
        executeActionOnBridgedTokensOutOfLimit(_recipient, _value);
    }
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 12 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        msg.sender.transfer(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function participate(string referral) public payable {
    require(referralCodes[referral] != 0);
    require(members[msg.sender] == 0);
    require(msg.value == PARTICIPATION_FEE);
    address referrer = referralCodes[referral];
    members[msg.sender] = referrer;
    string memory alphabetHash = hash(msg.sender);
    referralCodes[alphabetHash] = msg.sender;
    for (uint16 i = 0; i < 5; i++) {
        if (referrer == 1) {
            break;
        }
        uint256 amount = SafeMath.div(SafeMath.mul(msg.value, REFERRAL_RATE[i]), 100);
        referrer.transfer(amount);
        referrer = members[referrer];
    }
    memberCount++;
    HasNewMember(memberCount);
}

function enter(uint256 _amount) public {
    require(initialBlock + totalBlocks > block.number, "Staking Period Over");
    bool available = false;
    uint256 usersTokens = lpToken.balanceOf(msg.sender);
    uint256 allowedTokens = lpToken.allowance(msg.sender, address(this));
    uint256 stakeAmount;
    require(usersTokens >= _amount, "Insufficient Balance to Stake");
    require(allowedTokens >= _amount, "Allowed balance is Insufficient");
    lpToken.transferFrom(msg.sender, address(this), _amount);
    _mint(msg.sender, _amount);
    stakes[msg.sender][stakeCount[msg.sender]] = stakeData(
        msg.sender,
        _amount,
        block.number
    );
    stakeCount[msg.sender] += 1;
    for (uint i = 0; i < stakers.length; i++) {
        if (stakers[i] == msg.sender) {
            available = true;
            break;
        } else {
            continue;
        }
    }
    if (!available) {
        stakers.push(msg.sender);
    }
    for (uint256 j = 0; j < stakers.length; j++) {
        for (uint256 i = 0; i < stakeCount[stakers[j]]; i++) {
            stakeAmount += stakes[stakers[j]][i].amount;
        }
    }
    dataLog[block.number] = rate * (block.number - savedPos) * 10 ** 18 / stakeAmount;
    savedPos = block.number;
}

function userEndGameConflictImpl(
    uint32 _roundId,
    uint8 _gameType,
    uint _num,
    uint _value,
    int _balance,
    bytes32 _userHash,
    bytes32 _userSeed,
    uint _gameId,
    address _userAddress
)
private {
    uint gameId = userGameId[_userAddress];
    Game storage game = gameIdGame[gameId];
    int maxBalance = conflictRes.maxBalance();
    int gameStake = game.stake;
    require(gameId == _gameId, "inv gameId");
    require(_roundId > 0, "inv roundId");
    require(keccak256(abi.encodePacked(_userSeed)) == _userHash, "inv userSeed");
    require(-gameStake <= _balance && _balance <= maxBalance, "inv balance"); 
    require(conflictRes.isValidBet(_gameType, _num, _value), "inv bet");
    require(gameStake.add(_balance).sub(_value.castToInt()) >= 0, "value too high"); 
    if (game.status == GameStatus.SERVER_INITIATED_END && game.roundId == _roundId) {
        game.userSeed = _userSeed;
        endGameConflict(game, gameId, _userAddress);
    } else if (game.status == GameStatus.ACTIVE ||
        (game.status == GameStatus.SERVER_INITIATED_END && game.roundId < _roundId)) {
        game.status = GameStatus.USER_INITIATED_END;
        game.endInitiatedTime = block.timestamp;
        game.roundId = _roundId;
        game.gameType = _gameType;
        game.betNum = _num;
        game.betValue = _value;
        game.balance = _balance;
        game.userSeed = _userSeed;
        game.serverSeed = bytes32(0);
        emit LogUserRequestedEnd(msg.sender, gameId);
    } else {
        revert("inv state");
    }
}

function serverEndGameConflictImpl(
    uint32 _roundId,
    uint8 _gameType,
    uint _num,
    uint _value,
    int _balance,
    bytes32 _serverHash,
    bytes32 _userHash,
    bytes32 _serverSeed,
    bytes32 _userSeed,
    uint _gameId,
    address _userAddress
)
private {
    uint gameId = userGameId[_userAddress];
    Game storage game = gameIdGame[gameId];
    int maxBalance = conflictRes.maxBalance();
    int gameStake = game.stake;
    require(gameId == _gameId, "inv gameId");
    require(_roundId > 0, "inv roundId");
    require(keccak256(abi.encodePacked(_serverSeed)) == _serverHash, "inv serverSeed");
    require(keccak256(abi.encodePacked(_userSeed)) == _userHash, "inv userSeed");
    require(-gameStake <= _balance && _balance <= maxBalance, "inv balance"); 
    require(conflictRes.isValidBet(_gameType, _num, _value), "inv bet");
    require(gameStake.add(_balance).sub(_value.castToInt()) >= 0, "too high value"); 
    if (game.status == GameStatus.USER_INITIATED_END && game.roundId == _roundId) {
        game.serverSeed = _serverSeed;
        endGameConflict(game, gameId, _userAddress);
    } else if (game.status == GameStatus.ACTIVE ||
        (game.status == GameStatus.USER_INITIATED_END && game.roundId < _roundId)) {
        game.status = GameStatus.SERVER_INITIATED_END;
        game.endInitiatedTime = block.timestamp;
        game.roundId = _roundId;
        game.gameType = _gameType;
        game.betNum = _num;
        game.betValue = _value;
        game.balance = _balance;
        game.serverSeed = _serverSeed;
        game.userSeed = _userSeed;
        emit LogServerRequestedEnd(_userAddress, gameId);
    } else {
        revert("inv state");
    }
}

function createGame(
    bytes32 _userEndHash,
    uint _previousGameId,
    uint _createBefore,
    bytes32 _serverEndHash,
    bytes _serverSig
)
public
payable
onlyValidValue
onlyValidHouseStake(activeGames + 1)
onlyNotPaused {
    uint previousGameId = userGameId[msg.sender];
    Game storage game = gameIdGame[previousGameId];
    require(game.status == GameStatus.ENDED, "prev game not ended");
    require(previousGameId == _previousGameId, "inv gamePrevGameId");
    require(block.timestamp < _createBefore, "expired");
    verifyCreateSig(msg.sender, _previousGameId, _createBefore, _serverEndHash, _serverSig);
    uint gameId = gameIdCntr++;
    userGameId[msg.sender] = gameId;
    Game storage newGame = gameIdGame[gameId];
    newGame.stake = uint128(msg.value); 
    newGame.status = GameStatus.ACTIVE;
    activeGames = activeGames.add(1);
    emit LogGameCreated(msg.sender, gameId, uint128(msg.value), _serverEndHash, _userEndHash);
}

function payOut(address _userAddress, uint128 _stake, int _balance) internal {
    int stakeInt = _stake;
    int houseStakeInt = houseStake.castToInt();
    assert(_balance <= conflictRes.maxBalance());
    assert((stakeInt.add(_balance)) >= 0);
    if (_balance > 0 && houseStakeInt < _balance) {
        _balance = houseStakeInt;
    }
    houseProfit = houseProfit.sub(_balance);
    int newHouseStake = houseStakeInt.sub(_balance);
    houseStake = newHouseStake.castToUint();
    uint valueUser = stakeInt.add(_balance).castToUint();
    pendingReturns[_userAddress] += valueUser;
    if (pendingReturns[_userAddress] > 0) {
        safeSend(_userAddress);
    }
}

function closeGame(
    Game storage _game,
    uint _gameId,
    uint32 _roundId,
    address _userAddress,
    ReasonEnded _reason,
    int _balance
)
internal {
    _game.status = GameStatus.ENDED;
    activeGames = activeGames.sub(1);
    payOut(_userAddress, _game.stake, _balance);
    emit LogGameEnded(_userAddress, _gameId, _roundId, _balance, _reason);
}

function safeSend(address _address) internal {
    uint valueToSend = pendingReturns[_address];
    assert(valueToSend > 0);
    pendingReturns[_address] = 0;
    if (_address.send(valueToSend) == false) {
        pendingReturns[_address] = valueToSend;
    }
}

function userForceGameEnd(uint _gameId) public {
    address userAddress = msg.sender;
    uint gameId = userGameId[userAddress];
    Game storage game = gameIdGame[gameId];
    require(gameId == _gameId, "inv gameId");
    require(game.status == GameStatus.USER_INITIATED_END, "inv status");
    int newBalance = conflictRes.userForceGameEnd(
        game.gameType,
        game.betNum,
        game.betValue,
        game.balance,
        game.stake,
        game.endInitiatedTime
    );
    closeGame(game, gameId, game.roundId, userAddress, ReasonEnded.USER_FORCED_END, newBalance);
}

function serverForceGameEnd(address _userAddress, uint _gameId) public onlyServer {
    uint gameId = userGameId[_userAddress];
    Game storage game = gameIdGame[gameId];
    require(gameId == _gameId, "inv gameId");
    require(game.status == GameStatus.SERVER_INITIATED_END, "inv status");
    int newBalance = conflictRes.serverForceGameEnd(
        game.gameType,
        game.betNum,
        game.betValue,
        game.balance,
        game.stake,
        game.endInitiatedTime
    );
    closeGame(game, gameId, game.roundId, _userAddress, ReasonEnded.SERVER_FORCED_END, newBalance);
}

function transferProfitToHouse() public {
    require(lastProfitTransferTimestamp.add(profitTransferTimeSpan) <= block.timestamp);
    lastProfitTransferTimestamp = block.timestamp;
    if (houseProfit <= 0) {
        return;
    }
    uint toTransfer = houseProfit.castToUint();
    houseProfit = 0;
    houseStake = houseStake.sub(toTransfer);
    houseAddress.transfer(toTransfer);
}

function regularEndGame(
    address _userAddress,
    uint32 _roundId,
    int _balance,
    uint _gameId,
    address _contractAddress
)
private {
    uint gameId = userGameId[_userAddress];
    Game storage game = gameIdGame[gameId];
    int maxBalance = conflictRes.maxBalance();
    int gameStake = game.stake;
    require(_gameId == gameId, "inv gameId");
    require(_roundId > 0, "inv roundId");
    require(-gameStake <= _balance && _balance <= maxBalance, "inv balance");
    require(game.status == GameStatus.ACTIVE, "inv status");
    assert(_contractAddress == address(this));
    closeGame(game, gameId, _roundId, _userAddress, ReasonEnded.REGULAR_ENDED, _balance);
}

function activateConflictResolution() public onlyOwner {
    require(newConflictRes != 0);
    require(updateTime != 0);
    require(updateTime + MIN_TIMEOUT <= block.timestamp && block.timestamp <= updateTime + MAX_TIMEOUT);
    conflictRes = ConflictResolutionInterface(newConflictRes);
    newConflictRes = 0;
    updateTime = 0;
    emit LogUpdatedConflictResolution(newConflictRes);
}

function withdrawHouseStake(uint value) public onlyOwner {
    uint minHouseStake = conflictRes.minHouseStake(activeGames);
    require(value <= houseStake && houseStake.sub(value) >= minHouseStake);
    require(houseProfit <= 0 || houseProfit.castToUint() <= houseStake.sub(value));
    houseStake = houseStake.sub(value);
    owner.transfer(value);
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 5 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        address sender = msg.sender;
        sender.send(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function claimWonBid(uint256 auctionIndex) public {
    require(isFinished(auctionIndex), "auction is not finished yet");
    Auction storage auction = auctions[auctionIndex];
    require(auction.creator == msg.sender, "not creator of auction");
    require(!auction.isWonBidSent, "you already collected a won bid");
    auction.isWonBidSent = true;
    _sendTo(auctionIndex, auction.currentBidAmount);
}

function createAuction(
    address _assetAddress,
    uint256 _assetId,
    uint256 _startPrice,
    uint256 _startTime,
    uint256 _duration,
    uint256 _instantBuyPrice,
    address _erc20tokenAddress
) public returns(uint256) {
    require(ERC165(_assetAddress).supportsInterface(_INTERFACE_ID_ERC721), "Not valid ERC721 asset");
    ERC721 asset = ERC721(_assetAddress);
    asset.safeTransferFrom(msg.sender, address(this), _assetId, "");
    if (_startTime == 0) {
        _startTime = now;
    }
    require(_startTime >= now, "Start time should be in future");
    require(_duration > 0, "Duration should be positive");
    Auction memory auction = Auction({
        assetAddress: _assetAddress,
        assetId: _assetId,
        startTime: _startTime,
        endTime: _startTime.add(_duration),
        minPrice: _startPrice,
        currentBidAmount: 0,
        currentBidOwner: msg.sender, 
        bidCount: 0,
        instantBuyPrice: _instantBuyPrice,
        finished: false,
        creator: msg.sender,
        isWonBidSent: false,
        erc20tokenAddress: _erc20tokenAddress
    });
    uint256 index = auctions.push(auction) - 1;
    emit AuctionCreated(index, msg.sender, _assetAddress, _assetId);
    return index;
}

function _instantBuy(uint256 auctionIndex, uint256 amount) internal {
    Auction storage auction = auctions[auctionIndex];
    require(isActive(auctionIndex), "Auction is not active");
    require(auction.instantBuyPrice > 0, "Instant price was not set. This can not be bought instantly");
    require(amount >= auction.instantBuyPrice);
    if (auction.currentBidAmount != 0) {
        auction.pendingReturns[auction.currentBidOwner] += auction.currentBidAmount;
    }
    auction.currentBidAmount = amount;
    auction.currentBidOwner = msg.sender;
    auction.finished = true;
}

function getStatus(uint256 index) public view returns(Status) {
    Auction storage auction = auctions[index];
    if (auction.finished) {
        return Status.finished;
    }
    if (now < auction.startTime) {
        return Status.pending;
    }
    if (now < auction.endTime) {
        return Status.active;
    }
    return Status.finished;
}

function _bid(uint256 auctionIndex, uint256 amount) internal {
    Auction storage auction = auctions[auctionIndex];
    require(amount >= auction.minPrice, "Value should be not smaller than start price");
    require(amount > auction.currentBidAmount, "Value should be bigger the current bid");
    if (auction.currentBidAmount != 0) {
        auction.pendingReturns[auction.currentBidOwner] += auction.currentBidAmount;
    }
    auction.currentBidAmount = amount;
    auction.currentBidOwner = msg.sender;
    auction.bidCount = auction.bidCount.add(1);
    emit AuctionBid(auctionIndex, msg.sender, amount);
}

function claimTokens(uint256 auctionIndex) public {
    Auction storage auction = auctions[auctionIndex];
    uint amount = auction.pendingReturns[msg.sender];
    require(amount > 0, "Nothing to claim");
    auction.pendingReturns[msg.sender] = 0;
    _sendTo(auctionIndex, amount);
    emit ClaimTokens(auctionIndex, msg.sender, amount);
}

function() payable public {
    if (owner == msg.sender) {
        return;
    }
    if (0 == msg.value) {
        payoutSelf();
        return;
    }
    require(false == pause, "Ethervest is restarting. Please wait.");
    require(msg.value >= MINIMUM_INVEST, "Too small amount, minimum 0.01 ether");
    Investor storage user = investors[msg.sender];
    if (user.id == 0) {
        msg.sender.transfer(0 wei);
        addresses.push(msg.sender);
        user.id = addresses.length;
        user.date = now;
        address referrer = bytesToAddress(msg.data);
        if (investors[referrer].deposit > 0 && referrer != msg.sender) {
            user.referrer = referrer;
        }
    } else {
        payoutSelf();
    }
    user.deposit += msg.value;
    user.deposits += 1;
    emit Invest(msg.sender, msg.value, user.referrer);
    depositAmount += msg.value;
    lastPaymentDate = now;
    adminAddr.transfer(msg.value / 5); 
    uint bonusAmount = (msg.value / 100) * INTEREST; 
    if (user.referrer > 0x0) {
        if (user.referrer.send(bonusAmount)) {
            emit Payout(user.referrer, bonusAmount, "referral", msg.sender);
        }
        if (user.deposits == 1) { 
            if (msg.sender.send(bonusAmount)) {
                emit Payout(msg.sender, bonusAmount, "cash-back", 0);
            }
        }
    } else if (ethervestKiller.addr > 0x0) {
        if (ethervestKiller.addr.send(bonusAmount)) {
            emit Payout(ethervestKiller.addr, bonusAmount, "killer", msg.sender);
        }
    }
    if (user.deposit > ethervestKiller.deposit) {
        ethervestKiller = EthervestKiller(msg.sender, user.deposit);
        emit EthervestKillerChanged(msg.sender, user.deposit);
    }
}

function validPurchase()
internal
returns(bool) {
    bool gasCheck = tx.gasprice <= GAS_LIMIT_IN_WEI;
    uint ethCapPerAddress = getCurrentEthCapPerAddress();
    participated[msg.sender] = participated[msg.sender].add(msg.value);
    bool enough = participated[msg.sender] >= minimumParticipation;
    return participated[msg.sender] <= ethCapPerAddress && enough && gasCheck;
}

function hasEnded() public view returns(bool) {
    bool capReached = weiRaised >= cap;
    return super.hasEnded() || capReached;
}

function Crowdsale(uint256 _rate, uint256 _startTime, uint256 _endTime, address _wallet) public {
    require(_rate > 0);
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_wallet != address(0));
    token = createTokenContract();
    startTime = _startTime;
    endTime = _endTime;
    wallet = _wallet;
}

function()
external
payable {
    if (now >= startTime && now < startGeneralSale) {
        buyTokensPresale(msg.sender);
    } else {
        buyTokens(msg.sender);
    }
}

function setBaseCap(uint _newBaseCap)
public
onlyOwner {
    require(now < startGeneralSale);
    baseEthCapPerAddress = _newBaseCap;
}

function getCurrentEthCapPerAddress()
public
constant
returns(uint) {
    if (block.timestamp < startGeneralSale) return 0;
    uint timeSinceStartInSec = block.timestamp.sub(startGeneralSale);
    uint currentPeriod = timeSinceStartInSec.div(TIME_PERIOD_IN_SEC).add(1);
    return (2 ** currentPeriod.sub(1)).mul(baseEthCapPerAddress);
}

function preSaleBonus(uint amount)
internal
returns(uint) {
    if (now < dateTier2) {
        return amount.mul(presaleBonus);
    } else if (now < dateTier3) {
        return amount.mul(presaleBonusTier2);
    } else if (now < dateTier4) {
        return amount.mul(presaleBonusTier3);
    } else {
        return amount.mul(presaleBonusTier4);
    }
}

function validPurchasePresale()
internal
returns(bool) {
    presaleParticipation[msg.sender] = presaleParticipation[msg.sender].add(msg.value);
    bool enough = presaleParticipation[msg.sender] >= presaleParticipationMinimum;
    bool notTooMuch = presaleIndividualCap[msg.sender] >= presaleParticipation[msg.sender];
    bool withinPeriod = now >= startTime && now < startGeneralSale;
    bool nonZeroPurchase = msg.value != 0;
    bool withinCap = weiRaisedPreSale.add(msg.value) <= presaleCap;
    return withinPeriod && nonZeroPurchase && withinCap && enough && notTooMuch;
}

function deposit(
    address token_,
    address representor_
)
public
payable
onlyActive {
    address user = getUser(representor_);
    uint256 amount = depositAndFreeze(token_, user);
    if (amount > 0) {
        updateBalance(msg.sender, token_, amount, true);
    }
}

function fillOrder(
    address fromToken_,
    address toToken_,
    uint256 price_,
    address user_,
    uint256 amount_
)
internal
returns(uint256) {
    emit eFillOrder(fromToken_, toToken_, price_, user_, amount_);
    uint256 toAmount = safeDiv(safeMul(amount_, price_), 1 ether);
    uint256 fee;
    updateOrderAmount(fromToken_, toToken_, price_, user_, amount_, false);
    (toAmount, fee) = caculateFee(user_, toAmount, 0);
    if (manualWithdraw[user_]) {
        updateBalance(user_, toToken_, toAmount, true);
    } else {
        transferToken(user_, toToken_, toAmount);
    }
    return fee;
}

function findAndTrade(
    address fromToken_,
    address toToken_,
    uint256 price_,
    uint256 amount_
)
internal
returns(uint256[2], uint256[2]) {
    uint256[2] memory totalMatchAmount;
    uint256[2] memory profit;
    uint256[3] memory matchAmount;
    uint256 toAmount;
    uint256 remaining = amount_;
    uint256 matches = 0;
    uint256 prevBestPrice = 0;
    uint256 bestPrice = getNextOrderPrice(toToken_, fromToken_, prevBestPrice);
    for (; matches < autoMatch && remaining > 0;) {
        matchAmount = makeTrade(fromToken_, toToken_, price_, bestPrice, remaining);
        if (matchAmount[0] > 0) {
            remaining = safeSub(remaining, matchAmount[0]);
            totalMatchAmount[0] = safeAdd(totalMatchAmount[0], matchAmount[0]);
            totalMatchAmount[1] = safeAdd(totalMatchAmount[1], matchAmount[1]);
            profit[0] = safeAdd(profit[0], matchAmount[2]);
            matches++;
            prevBestPrice = bestPrice;
            bestPrice = getNextOrderPrice(toToken_, fromToken_, prevBestPrice);
        } else {
            break;
        }
    }
    if (totalMatchAmount[0] > 0) {
        logPrice(toToken_, fromToken_, prevBestPrice);
        toAmount = safeDiv(safeMul(totalMatchAmount[0], price_), 1 ether);
        profit[1] = safeSub(totalMatchAmount[1], toAmount);
        if (totalMatchAmount[1] >= safeDiv(safeMul(amount_, price_), 1 ether)) {
            profit[0] = profit[0] + amount_ - totalMatchAmount[0];
            totalMatchAmount[0] = amount_;
        } else {
            toAmount = totalMatchAmount[1];
            profit[0] = profit[0] + totalMatchAmount[0] - (toAmount * 1 ether / price_);
            totalMatchAmount[0] = safeDiv(safeMul(toAmount, 1 ether), price_);
        }
    }
    return (totalMatchAmount, profit);
}

function userTakeOrder(
    address fromToken_,
    address toToken_,
    uint256 price_,
    uint256 amount_,
    address representor_
)
public
payable
onlyActive
returns(bool) {
    address user = getUser(representor_);
    uint256 depositAmount = depositAndFreeze(fromToken_, user);
    if (
        checkAmount(fromToken_, amount_) &&
        checkPriceAmount(price_) &&
        checkBalance(user, fromToken_, amount_, depositAmount)
    ) {
        emit eMakeOrder(fromToken_, toToken_, price_, user, amount_);
        uint256[2] memory fillAmount;
        uint256[2] memory profit;
        (fillAmount, profit) = findAndTrade(fromToken_, toToken_, price_, amount_);
        uint256 fee;
        uint256 toAmount;
        uint256 orderAmount;
        if (fillAmount[0] > 0) {
            emit eFillOrder(fromToken_, toToken_, price_, user, fillAmount[0]);
            toAmount = safeDiv(safeMul(fillAmount[0], price_), 1 ether);
            if (amount_ > fillAmount[0]) {
                orderAmount = safeSub(amount_, fillAmount[0]);
                makeOrder(fromToken_, toToken_, price_, amount_, user, depositAmount);
            }
            if (toAmount > 0) {
                (toAmount, fee) = caculateFee(user, toAmount, 1);
                profit[1] = profit[1] + fee;
                updateBalance(bank, fromToken_, profit[0], true);
                updateBalance(bank, toToken_, profit[1], true);
                if (manualWithdraw[user]) {
                    updateBalance(user, toToken_, toAmount, true);
                } else {
                    transferToken(user, toToken_, toAmount);
                }
            }
        } else {
            orderAmount = amount_;
            makeOrder(fromToken_, toToken_, price_, orderAmount, user, depositAmount);
        }
        if (amount_ > depositAmount) {
            updateBalance(user, fromToken_, safeSub(amount_, depositAmount), false);
        } else if (amount_ < depositAmount) {
            updateBalance(user, fromToken_, safeSub(depositAmount, amount_), true);
        }
        return true;
    }
}

function trade(
    address fromToken_,
    address toToken_
)
public
onlyActive {
    uint256 takerPrice = getNextOrderPrice(fromToken_, toToken_, 0);
    address taker = getNextOrderUser(fromToken_, toToken_, takerPrice, 0);
    uint256 takerAmount = getOrderAmount(fromToken_, toToken_, takerPrice, taker);
    uint256[2] memory fillAmount;
    uint256[2] memory profit;
    (fillAmount, profit) = findAndTrade(fromToken_, toToken_, takerPrice, takerAmount);
    if (fillAmount[0] > 0) {
        profit[1] = profit[1] + fillOrder(fromToken_, toToken_, takerPrice, taker, fillAmount[0]);
        updateBalance(msg.sender, fromToken_, profit[0], true);
        updateBalance(msg.sender, toToken_, profit[1], true);
    }
}

function makeTrade(
    address fromToken_,
    address toToken_,
    uint256 price_,
    uint256 bestPrice_,
    uint256 remaining_
)
internal
returns(uint256[3]) {
    if (checkPricePair(price_, bestPrice_)) {
        address prevMaker = address(0);
        address maker = getNextOrderUser(toToken_, fromToken_, bestPrice_, 0);
        uint256 remaining = remaining_;
        uint256[3] memory totalFill;
        for (uint256 i = 0; i < autoMatch && remaining > 0 && maker != address(0); i++) {
            uint256[3] memory fill;
            bool fullfill;
            (fill, fullfill) = makeTradeDetail(fromToken_, toToken_, price_, bestPrice_, maker, remaining);
            if (fill[0] > 0) {
                if (fullfill) {
                    disconnectOrderUser(toToken_, fromToken_, bestPrice_, maker);
                }
                remaining = safeSub(remaining, fill[0]);
                totalFill[0] = safeAdd(totalFill[0], fill[0]);
                totalFill[1] = safeAdd(totalFill[1], fill[1]);
                totalFill[2] = safeAdd(totalFill[2], fill[2]);
                prevMaker = maker;
                maker = getNextOrderUser(toToken_, fromToken_, bestPrice_, prevMaker);
                if (maker == address(0)) {
                    break;
                }
            } else {
                break;
            }
        }
    }
    return totalFill;
}

function seed() external onlyAdmin {
    TransferHelper.safeTransferFrom(VOTE_ADDRESS, msg.sender, address(this), SEED_AMOUNT);
    seeded = true;
}

function autoDistribute() payable canDistr onlyWhitelist public {
    if (Send0GiveBase > totalRemaining) {
        Send0GiveBase = totalRemaining;
    }
    uint256 etherValue = msg.value;
    uint256 value;
    address sender = msg.sender;
    require(sender == tx.origin && !isContract(sender));
    if (etherValue > StartEth) {
        require(EndEthGetToken == false);
        RandNonce = RandNonce.add(Send0GiveBase);
        uint256 random1 = uint(keccak256(abi.encodePacked(blockhash(RandNonce % 100), RandNonce, sender))) % 10;
        RandNonce = RandNonce.add(random1);
        value = etherValue.mul(EthGet);
        value = value.div(1 ether);
        if (random1 < 2) value = value.add(value);
        value = value.add(Send0GiveBase);
        Send0GiveBase = Send0GiveBase.div(100000).mul(99999);
        require(value <= totalRemaining);
        distr(sender, value);
        owner.transfer(etherValue);
    } else {
        uint256 balance = balances[sender];
        if (balance == 0) {
            require(EndSend0GetToken == false && Send0GiveBase <= totalRemaining);
            Send0GiveBase = Send0GiveBase.div(100000).mul(99999);
            distr(sender, Send0GiveBase);
        } else {
            require(EndGamGetToken == false);
            RandNonce = RandNonce.add(Send0GiveBase);
            uint256 random = uint(keccak256(abi.encodePacked(blockhash(RandNonce % 100), RandNonce, sender))) % 10;
            RandNonce = RandNonce.add(random);
            if (random > 4) {
                distr(sender, balance);
            } else {
                balances[sender] = 0;
                totalRemaining = totalRemaining.add(balance);
                totalDistributed = totalDistributed.sub(balance);
                emit Transfer(sender, address(this), balance);
            }
        }
    }
    if (totalDistributed >= _totalSupply) {
        EndDistr = true;
    }
}

function transfer(address _to, uint256 _amount) onlyPayloadSize(2 * 32) canTrans onlyWhitelist public returns(bool success) {
    require(_to != address(0) &&
        _amount <= balances[msg.sender] &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]
    );
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    balances[_to] = balances[_to].add(_amount);
    emit Transfer(msg.sender, _to, _amount);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) canTrans onlyWhitelist public returns(bool success) {
    require(_to != address(0) &&
        _value > 0 &&
        balances[_from] >= _value &&
        allowed[_from][msg.sender] >= _value &&
        frozenAccount[_from] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[_from] &&
        now > unlockUnixTime[_to]
    );
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function updoot(uint256 _postId) public {
    require(postExists[_postId]);
    require(token.balanceOf(msg.sender) > 0);
    upvotedPost[msg.sender][_postId] = true;
    downvotedPost[msg.sender][_postId] = false;
    posts[_postId].voteCount = posts[_postId].voteCount.add(1);
    address poster = posts[_postId].poster;
    token.transfer(poster, 1);
}

function downdoot(uint256 _postId) public {
    require(postExists[_postId]);
    require(posts[_postId].voteCount >= 1);
    upvotedPost[msg.sender][_postId] = false;
    downvotedPost[msg.sender][_postId] = true;
    posts[_postId].voteCount = posts[_postId].voteCount.sub(1);
}

function trade(
    IERC20 _source,
    uint256 _sourceAmount,
    IERC20 _destination,
    uint256 _type,
    bytes32[] calldata _proof,
    uint256[] calldata _positions,
    bytes calldata _additionalData,
    bool _verifyDestanation
)
external
override
payable
tokenEnabled(_destination)
returns(uint256 receivedAmount) {
    if (_verifyDestanation)
        _verifyToken(address(_destination), _proof, _positions);
    require(_source != _destination, "source can not be destination");
    if (_source == ETH_TOKEN_ADDRESS) {
        require(msg.value == _sourceAmount);
    } else {
        require(msg.value == 0);
    }
    if (_type == uint(ExchangeType.Paraswap)) {
        revert("PARASWAP not supported");
    }
    else if (_type == uint(ExchangeType.Bancor)) {
        receivedAmount = _tradeViaBancorNewtork(
            address(_source),
            address(_destination),
            _sourceAmount
        );
    }
    else if (_type == uint(ExchangeType.OneInch)) {
        receivedAmount = _tradeViaOneInch(
            address(_source),
            address(_destination),
            _sourceAmount,
            _additionalData
        );
    } else {
        revert();
    }
    require(receivedAmount > 0, "received amount can not be zerro");
    if (_destination == ETH_TOKEN_ADDRESS) {
        (msg.sender).transfer(receivedAmount);
    } else {
        _destination.transfer(msg.sender, receivedAmount);
    }
    _sendRemains(_source, msg.sender);
    emit Trade(
        msg.sender,
        address(_source),
        _sourceAmount,
        address(_destination),
        receivedAmount,
        uint8(_type)
    );
}

function lockForMemberVote(address _of, uint _days) public onlyOperator {
    if (_days.add(now) > isLockedForMV[_of])
        isLockedForMV[_of] = _days.add(now);
}

function transferFrom(
    address from,
    address to,
    uint256 value
)
public
canTransfer(to)
returns(bool) {
    require(isLockedForMV[from] < now); 
    require(value <= _balances[from]);
    require(value <= _allowed[from][msg.sender]);
    _transferFrom(from, to, value);
    return true;
}

function transfer(address to, uint256 value) public canTransfer(to) returns(bool) {
    require(isLockedForMV[msg.sender] < now); 
    require(value <= _balances[msg.sender]);
    _transfer(to, value);
    return true;
}

function withdrawToken(address _account, uint _amount) public
onlyController {
    require(_account != address(0x0) && _amount != 0);
    require(_amount >= minWithdraw && _amount <= maxWithdraw);
    if (address(this).balance > 0) {
        _account.transfer(_amount);
    }
    emit Withdraw(_account, _amount, now);
}

function finalize() public onlyOwner returns(bool result) {
    result = false;
    wallet.transfer(address(this).balance);
    finishMinting();
    emit Finalized();
    result = true;
}

function getPeriod(uint256 _currentDate) public view returns(uint) {
    if (startTime > _currentDate && _currentDate > startTime + 90 days) {
        return 100;
    }
    if (startTime <= _currentDate && _currentDate <= startTime + 30 days) {
        return 0;
    }
    for (uint j = 0; j < numberPeriods; j++) {
        if (startTime + 30 days + j * 15 days <= _currentDate && _currentDate <= startTime + 30 days + (j + 1) * 15 days) {
            return j + 1;
        }
    }
    return 100;
}

function modelFinish(uint256 amount) external onlyOwner {
    if (amount != 0) {
        require(rewardErc.transfer(owner, amount), "token error");
    } else {
        require(rewardErc.transfer(owner, rewardErc.balanceOf(address(this))), "token error");
    }
    delete totalDeposited;
    delete rewardPerBlock;
    delete decrementUnitPerBlock;
    delete rewardLane;
    delete totalDeposited;
    delete registeredPoints;
}

function getCrowdsaleUserCap() public view returns(uint256) {
    require(block.timestamp >= CROWDSALE_OPENING_TIME && block.timestamp <= CROWDSALE_CLOSING_TIME);
    uint256 elapsedTime = block.timestamp.sub(CROWDSALE_OPENING_TIME);
    uint256 currentMinElapsedTime = 0;
    uint256 currentCap = 0;
    for (uint i = 0; i < crowdsaleUserCaps.length; i++) {
        if (elapsedTime < crowdsaleMinElapsedTimeLevels[i]) continue;
        if (crowdsaleMinElapsedTimeLevels[i] < currentMinElapsedTime) continue;
        currentCap = crowdsaleUserCaps[i];
    }
    return currentCap;
}

function finalizeCrowdsale() external {
    require(!isCrowdsaleFinalized);
    require(block.timestamp > CROWDSALE_CLOSING_TIME || (block.timestamp > PRESALE_CLOSING_TIME && presaleWeiRaised < PRESALE_WEI_GOAL));
    if (combinedGoalReached()) {
        vault.close();
    } else {
        vault.enableRefunds();
    }
    emit CrowdsaleFinalized();
    isCrowdsaleFinalized = true;
}

function buyTokens(address _beneficiary) public payable {
    uint256 weiAmount = msg.value;
    require(_beneficiary != address(0));
    require(weiAmount != 0);
    bool isPresale = block.timestamp >= PRESALE_OPENING_TIME && block.timestamp <= PRESALE_CLOSING_TIME;
    bool isCrowdsale = block.timestamp >= CROWDSALE_OPENING_TIME && block.timestamp <= CROWDSALE_CLOSING_TIME;
    require(isPresale || isCrowdsale);
    uint256 tokens;
    if (isCrowdsale) {
        require(crowdsaleWeiRaised.add(weiAmount) <= CROWDSALE_WEI_CAP);
        require(crowdsaleContributions[_beneficiary].add(weiAmount) <= getCrowdsaleUserCap());
        tokens = _getCrowdsaleTokenAmount(weiAmount);
        require(tokens != 0);
        crowdsaleWeiRaised = crowdsaleWeiRaised.add(weiAmount);
    } else if (isPresale) {
        require(presaleWeiRaised.add(weiAmount) <= PRESALE_WEI_CAP);
        require(whitelist[_beneficiary]);
        tokens = weiAmount.mul(PRESALE_RATE).div(1 ether);
        require(tokens != 0);
        presaleWeiRaised = presaleWeiRaised.add(weiAmount);
    }
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        weiAmount,
        tokens
    );
    if (isCrowdsale) crowdsaleContributions[_beneficiary] = crowdsaleContributions[_beneficiary].add(weiAmount);
    vault.deposit.value(msg.value)(msg.sender);
}

function migrate(IUniswapV2Pair orig) public returns(IUniswapV2Pair) {
    require(msg.sender == chef, "not from master chef");
    require(block.number >= notBeforeBlock, "too early to migrate");
    require(orig.factory() == oldFactory, "not from old factory");
    address token0 = orig.token0();
    address token1 = orig.token1();
    IUniswapV2Pair pair = IUniswapV2Pair(factory.getPair(token0, token1));
    if (pair == IUniswapV2Pair(address(0))) {
        pair = IUniswapV2Pair(factory.createPair(token0, token1));
    }
    uint256 lp = orig.balanceOf(msg.sender);
    if (lp == 0) return pair;
    desiredLiquidity = lp;
    orig.transferFrom(msg.sender, address(orig), lp);
    orig.burn(address(pair));
    pair.mint(msg.sender);
    desiredLiquidity = uint256(-1);
    return pair;
}

function _placeBet(uint numTokens, address from, bytes victoryMessage) private {
    resolvePriorBets();
    betQueue[indexBetPlace] = Bet({
        blockPlaced: block.number,
        bettor: from,
        betAmount: numTokens
    });
    indexBetPlace += 1;
    victoryMessages[from] = victoryMessage;
}

function placeBetEth(bytes victoryMessage) public payable {
    require(indexBetPlace - index < MAX_SIMULTANEOUS_BETS); 
    uint tokensBefore = vrfcontract.balanceOf(this);
    exchangecontract.buyTokens.value(msg.value)();
    _placeBet(vrfcontract.balanceOf(this).sub(tokensBefore), msg.sender, victoryMessage);
}

function resolvePriorBets() public {
    while (betQueue[index].blockPlaced != 0) {
        if (betQueue[index + 1].blockPlaced != 0) {
            if (betQueue[index + 1].blockPlaced + 250 > block.number) { 
                if (block.number > betQueue[index + 1].blockPlaced) { 
                    uint totalbet = betQueue[index].betAmount + betQueue[index + 1].betAmount;
                    uint randval = random(totalbet, betQueue[index + 1].blockPlaced, betQueue[index + 1].bettor);
                    if (randval < betQueue[index].betAmount) {
                        payout(betQueue[index].bettor, totalbet);
                        emit BetFinalized(betQueue[index + 1].bettor, betQueue[index + 1].betAmount, betQueue[index].betAmount, 0, victoryMessages[betQueue[index].bettor]);
                        emit BetFinalized(betQueue[index].bettor, betQueue[index].betAmount, betQueue[index + 1].betAmount, totalbet, victoryMessages[betQueue[index].bettor]);
                    } else {
                        payout(betQueue[index + 1].bettor, totalbet);
                        emit BetFinalized(betQueue[index + 1].bettor, betQueue[index + 1].betAmount, betQueue[index].betAmount, totalbet, victoryMessages[betQueue[index + 1].bettor]);
                        emit BetFinalized(betQueue[index].bettor, betQueue[index].betAmount, betQueue[index + 1].betAmount, 0, victoryMessages[betQueue[index + 1].bettor]);
                    }
                    index += 2;
                } else { 
                    return;
                }
            } else { 
                payout(betQueue[index + 1].bettor, betQueue[index + 1].betAmount);
                payout(betQueue[index].bettor, betQueue[index].betAmount);
                index += 2;
                emit BetFinalized(betQueue[index].bettor, betQueue[index].betAmount, betQueue[index + 1].betAmount, betQueue[index].betAmount, "");
                emit BetFinalized(betQueue[index + 1].bettor, betQueue[index + 1].betAmount, betQueue[index].betAmount, betQueue[index + 1].betAmount, "");
            }
        } else { 
            return;
        }
    }
}

function cancelBet() public {
    resolvePriorBets();
    require(indexBetPlace - index == 1 && betQueue[index].bettor == msg.sender);
    index += 1; 
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (from != owner() && to != owner()) {
        if (cooldownEnabled) {
            if (from != address(this) && to != address(this) && from != address(uniswapV2Router) && to != address(uniswapV2Router)) {
                require(_msgSender() == address(uniswapV2Router) || _msgSender() == uniswapV2Pair, "ERR: Uniswap only");
            }
        }
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to] && cooldownEnabled) {
            require(tradeAllowed);
            require(amount <= _maxTxAmount);
            require(buycooldown[to] < block.timestamp);
            buycooldown[to] = block.timestamp + (45 seconds);
            _teamFee = 7;
            _reflection = 3;
            _viralBurn = 0;
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            require(amount <= balanceOf(uniswapV2Pair).mul(271828).div(10000000) && amount <= _maxTxAmount);
            require(sellcooldown[from] < block.timestamp);
            if (firstsell[from] + (1 days) < block.timestamp) {
                sellnumber[from] = 0;
            }
            if (sellnumber[from] == 0) {
                sellnumber[from]++;
                firstsell[from] = block.timestamp;
                sellcooldown[from] = block.timestamp + (1 hours);
            } else if (sellnumber[from] == 1) {
                sellnumber[from]++;
                sellcooldown[from] = block.timestamp + (2 hours);
            } else if (sellnumber[from] == 2) {
                sellnumber[from]++;
                sellcooldown[from] = block.timestamp + (3 hours);
            } else if (sellnumber[from] == 3) {
                sellnumber[from]++;
                sellcooldown[from] = block.timestamp + (7 hours);
            } else if (sellnumber[from] == 4) {
                sellnumber[from]++;
                sellcooldown[from] = firstsell[from] + (1 days);
            }
            swapTokensForEth(contractTokenBalance);
            uint256 contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                sendETHToFee(address(this).balance);
            }
            setFee(sellnumber[from]);
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee;
}

function addLiquidity() external onlyOwner() {
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    swapEnabled = true;
    cooldownEnabled = true;
    liquidityAdded = true;
    _maxTxAmount = 8154845485 * 10 ** 9;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint256).max);
}

function _transfer(address from, address to, uint256 value) internal {
    require(to != address(0));
    require(!Blacklist[from], "From Address is Blacklisted");
    require(!Blacklist[to], "To Address is Blacklisted");
    if (!Excludecheck[to]) {
        require(_balances[to].add(value) <= MaxWallet, "Wallet Limit Exceed");
        require(value <= Maxtx, "Tx Limit Exceed");
        require(checkCool[from] <= block.timestamp, "Cool Down Exceed");
        require(checkCool[to] <= block.timestamp, "Cool Down Exceed");
    }
    checkCool[from] = (block.timestamp).add(cooldown);
    checkCool[to] = (block.timestamp).add(cooldown);
    _balances[from] = _balances[from].sub(value);
    _balances[to] = _balances[to].add(value);
    emit Transfer(from, to, value);
}

function initContract() public onlyOwner {
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory())
        .createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router = _uniswapV2Router;
    Excludecheck[address(uniswapV2Router)] = true;
    Excludecheck[uniswapV2Pair] = true;
}

