function claim(
    address _arbitrator,
    uint256 _transactionId
) public {
    Lock memory lock = escrows[_arbitrator][_transactionId];
    require(lock.sender == msg.sender);
    require(lock.paid);
    require(lock.expiration < block.timestamp);
    require(lock.expiration != 0);
    require(lock.expiration != 1);
    delete escrows[_arbitrator][_transactionId];
    token.transfer(msg.sender, lock.value.add(lock.fee));
    Released(
        _arbitrator,
        msg.sender,
        _transactionId
    );
}

function releaseUnlocked(
    address _sender,
    address _recipient,
    uint256 _transactionId,
    uint256 _exchangeRate
) public {
    Lock memory lock = escrows[msg.sender][_transactionId];
    require(lock.expiration == 1);
    require(lock.sender == _sender);
    require(lock.paid);
    if (lock.fee > 0 && lock.sender != _recipient) {
        token.transfer(_recipient, lock.value);
        token.transfer(msg.sender, lock.fee);
    } else {
        token.transfer(_recipient, lock.value.add(lock.fee));
    }
    delete escrows[msg.sender][_transactionId];
    token.issueExchangeRate(
        _sender,
        _recipient,
        msg.sender,
        lock.value,
        _transactionId,
        _exchangeRate
    );
    Released(msg.sender, _recipient, _transactionId);
}

function release(
    address _sender,
    address _recipient,
    uint256 _transactionId,
    uint256 _exchangeRate
) public {
    Lock memory lock = escrows[msg.sender][_transactionId];
    require(lock.expiration != 1);
    require(lock.sender == _sender);
    require(lock.recipient == _recipient || lock.sender == _recipient);
    require(lock.paid);
    if (lock.fee > 0 && lock.recipient == _recipient) {
        token.transfer(_recipient, lock.value);
        token.transfer(msg.sender, lock.fee);
    } else {
        token.transfer(_recipient, lock.value.add(lock.fee));
    }
    delete escrows[msg.sender][_transactionId];
    token.issueExchangeRate(
        _sender,
        _recipient,
        msg.sender,
        lock.value,
        _transactionId,
        _exchangeRate
    );
    Released(msg.sender, _recipient, _transactionId);
}

function lockAccount(address account, uint256 unlockTime) onlyOwner public {
    require(unlockTime > now);
    lockedAccount[account] = unlockTime;
    emit LockAccount(account, unlockTime);
}

function isAccountLocked(address account) public view returns(bool) {
    return lockedAccount[account] > now;
}

function claim() public onlyOwner {
    uint pendingUnlocked = getPendingUnlocked();
    uint contractBalance = Jplus(tokenAddress).balanceOf(address(this));
    uint amountToSend = pendingUnlocked;
    if (contractBalance < pendingUnlocked) {
        amountToSend = contractBalance;
    }
    require(Jplus(tokenAddress).transfer(owner, amountToSend), "Could not transfer Tokens.");
    lastClaimedTime = now;
}

function() payable {
