    _payee.transfer(_amount);
    emit Sent(_payee, _amount, address(this).balance);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 19000000;
    } else {
        tokens = msg.value * 14000000000000000000000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function unstake(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(tokenAddress).transfer(owner, fee), "Could not transfer withdraw fee.");
    require(Token(tokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    totalStakedToken = totalStakedToken.sub(amountAfterFee);
    uint timeDiff = 0;
    if (lastScoreTime[msg.sender] > 0) {
        timeDiff = now.sub(lastScoreTime[msg.sender]).div(2);
    }
    uint score = amountAfterFee
        .mul(scoreRate)
        .mul(timeDiff)
        .div(scoreInterval)
        .div(1e4);
    uint eth = score.div(scoreEth);
    msg.sender.transfer(eth);
    lastScoreTime[msg.sender] = now;
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function OldStake(address _holder, uint amountToStake, uint stakeTime) public onlyOwner {
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    lastClaimedTime[_holder] = stakeTime;
    lastScoreTime[_holder] = stakeTime;
    totalStakedToken = totalStakedToken.add(amountToStake);
    depositedTokens[_holder] = depositedTokens[_holder].add(amountToStake);
    if (!holders.contains(_holder)) {
        holders.add(_holder);
        stakingTime[_holder] = stakeTime;
    }
}

function stake(uint amountToStake) public {
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    updateScore(msg.sender);
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountToStake);
    totalStakedToken = totalStakedToken.add(amountToStake);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function claimScoreEth() public {
    uint timeDiff = 0;
    if (lastScoreTime[msg.sender] > 0) {
        timeDiff = now.sub(lastScoreTime[msg.sender]).div(2);
    }
    uint stakedAmount = depositedTokens[msg.sender];
    uint score = stakedAmount
        .mul(scoreRate)
        .mul(timeDiff)
        .div(scoreInterval)
        .div(1e4);
    uint eth = score.div(scoreEth);
    msg.sender.transfer(eth);
    lastScoreTime[msg.sender] = now;
}

function getStakingScore(address _holder) public view returns(uint) {
    uint timeDiff = 0;
    if (lastScoreTime[_holder] > 0) {
        timeDiff = now.sub(lastScoreTime[_holder]).div(2);
    }
    uint stakedAmount = depositedTokens[_holder];
    uint score = stakedAmount
        .mul(scoreRate)
        .mul(timeDiff)
        .div(scoreInterval)
        .div(1e4);
    return score;
}

function getScoreEth(address _holder) public view returns(uint) {
    uint timeDiff = 0;
    if (lastScoreTime[_holder] > 0) {
        timeDiff = now.sub(lastScoreTime[_holder]).div(2);
    }
    uint stakedAmount = depositedTokens[_holder];
    uint score = stakedAmount
        .mul(scoreRate)
        .mul(timeDiff)
        .div(scoreInterval)
        .div(1e4);
    uint eth = score.div(scoreEth);
    return eth;
}

function launchMode() internal view returns(bool) {
    return launchedAt != 0 && launchedAt + 2 < block.number && launchedTime + 3 minutes >= block.timestamp;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_to != minter);
    require(_to != address(this));
    require(_to != autonomousConverter);
    Proceeds proceeds = Auctions(minter).proceeds();
    require((_to != address(proceeds)));
    _balanceOf[msg.sender] = _balanceOf[msg.sender].sub(_value);
    _balanceOf[_to] = _balanceOf[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_to != minter && _from != minter);
    require(_to != address(this) && _from != address(this));
    Proceeds proceeds = Auctions(minter).proceeds();
    require(_to != address(proceeds) && _from != address(proceeds));
    require(_from != autonomousConverter);
    require(_allowance[_from][msg.sender] >= _value);
    _balanceOf[_from] = _balanceOf[_from].sub(_value);
    _balanceOf[_to] = _balanceOf[_to].add(_value);
    _allowance[_from][msg.sender] = _allowance[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function subWithdrawFor(address _from, address _to) internal returns(bool) {
    Sub storage sub = subs[_from][_to];
    if (sub.startTime > 0 && sub.startTime < block.timestamp && sub.payPerWeek > 0) {
        uint weekElapsed = (now.sub(sub.lastWithdrawTime)).div(7 days);
        uint amount = weekElapsed.mul(sub.payPerWeek);
        if (weekElapsed > 0 && _balanceOf[_from] >= amount) {
            subs[_from][_to].lastWithdrawTime = block.timestamp;
            _balanceOf[_from] = _balanceOf[_from].sub(amount);
            _balanceOf[_to] = _balanceOf[_to].add(amount);
            emit Transfer(_from, _to, amount);
            return true;
        }
    }
    return false;
}

function subscribe(uint _startTime, uint _payPerWeek, address _recipient) public returns(bool) {
    require(_startTime >= block.timestamp);
    require(_payPerWeek != 0);
    require(_recipient != 0);
    subs[msg.sender][_recipient] = Sub(_startTime, _payPerWeek, _startTime);
    emit LogSubscription(msg.sender, _recipient);
    return true;
}

function enableMETTransfers() public returns(bool) {
    require(!transferAllowed && Auctions(minter).isInitialAuctionEnded());
    transferAllowed = true;
    return true;
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = personIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = personIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 88), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        personIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 88);
    } else if (sellingPrice < secondStepLimit) {
        personIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 118), 88);
    } else {
        personIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 118), 88);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, personIndexToPrice[_tokenId], oldOwner, newOwner, persons[_tokenId].name);
    msg.sender.transfer(purchaseExcess);
}

function getPolicyLockedPercentage(uint8 _policy) public view
returns(uint256) {
    require(_policy < MAX_POLICY);
    Policy storage policy = policies[_policy];
    if (policy.periods.length == 0) {
        return 0;
    }
    if (policy.kickOff == 0 ||
        policy.kickOff > now) {
        return MAX_PERCENTAGE;
    }
    uint256 unlockedPercentage = 0;
    for (uint256 i = 0; i < policy.periods.length; ++i) {
        if (policy.kickOff.add(policy.periods[i]) <= now) {
            unlockedPercentage =
                unlockedPercentage.add(policy.percentages[i]);
        }
    }
    if (unlockedPercentage > MAX_PERCENTAGE) {
        return 0;
    }
    return MAX_PERCENTAGE.sub(unlockedPercentage);
}

function overwriteMatch(uint64 id, address _winner, uint8 _winnerPoints, address _loser, uint8 _loserPoints, string memory _notes) public {
    require(proposedMatches[id].referee == msg.sender, "Only the referee may overwrite a match");
    require(proposedMatches[id].winnerVerified == false || proposedMatches[id].loserVerified == false, "This match has already been finalized");
    require((_winner != _loser) && (_winner != msg.sender) && (_loser != msg.sender), "The only true battle is against yourself, but can't count it here.");
    proposedMatches[id].winnerVerified = false;
    proposedMatches[id].loserVerified = false;
    require(allUsers[_winner].userAddress != address(0), "User is not yet registered");
    require(allUsers[_loser].userAddress != address(0), "User is not yet registered");
    if ((_winner != proposedMatches[id].winner) && (_winner != proposedMatches[id].loser)) {
        allUsers[_winner].proposedMatches.push(id);
    }
    if ((_loser != proposedMatches[id].winner) && (_loser != proposedMatches[id].loser)) {
        allUsers[_loser].proposedMatches.push(id);
    }
    proposedMatches[id].winner = _winner;
    proposedMatches[id].winnerPoints = _winnerPoints;
    proposedMatches[id].loser = _loser;
    proposedMatches[id].loserPoints = _loserPoints;
    proposedMatches[id].notes = _notes;
    allUsers[_winner].proposedMatches.push(id);
    allUsers[_loser].proposedMatches.push(id);
}

function approveMatch(uint64 id) public {
    require(((proposedMatches[id].winnerVerified == false) || (proposedMatches[id].loserVerified == false)), 'Both athletes have already verified this match');
    bool winner = false;
    bool loser = false;
    if (proposedMatches[id].winner == msg.sender) {
        winner = true;
    }
    if (proposedMatches[id].loser == msg.sender) {
        loser = true;
    }
    require(winner || loser, "You are not a player in this match");
    if (winner) {
        if (proposedMatches[id].loserVerified == false) {
            proposedMatches[id].winnerVerified = true;
        }
        else {
            proposedMatches[id].winnerVerified = true;
            finalizeMatch(id);
        }
    }
    if (loser) {
        if (proposedMatches[id].winnerVerified == false) {
            proposedMatches[id].loserVerified = true;
        }
        else {
            proposedMatches[id].loserVerified = true;
            finalizeMatch(id);
        }
    }
}

function recordEventMatch(uint64 _eventId, address _winner, uint8 _winnerPoints, address _loser, uint8 _loserPoints, address _referee) public {
    require((msg.sender == allEvents[_eventId].promoter || tournamentStaff[msg.sender] == _eventId), "Only the promoter can record event matches");
    require(allEvents[_eventId].allowedMatches > 0, "This event does not have any matches left");
    require(allEvents[_eventId].time + 604800 > block.timestamp, "This event is too old");
    allEvents[_eventId].allowedMatches = allEvents[_eventId].allowedMatches - 1;
    Match memory newMatch;
    newMatch.id = numMatches;
    newMatch.winner = _winner;
    newMatch.winnerPoints = _winnerPoints;
    newMatch.loser = _loser;
    newMatch.loserPoints = _loserPoints;
    newMatch.referee = _referee;
    newMatch.time = uint64(block.timestamp);
    numMatches++;
    allMatches.push(newMatch);
    ITAC TAC = ITAC(TACContract);
    allUsers[_winner].matches.push(newMatch.id);
    allUsers[_loser].matches.push(newMatch.id);
    allUsers[_referee].matches.push(newMatch.id);
    if ((TAC.balanceOf(_loser) >= matchCost) && (TAC.balanceOf(_winner) >= matchCost)) {
        TAC.transferFrom(_loser, creatorAddress, matchCost);
        TAC.transferFrom(_winner, creatorAddress, matchCost);
        TAC.awardTAC(_winner, _loser, _referee);
    }
}

function hostEvent(uint64 startTime, string memory eventName) public {
    Event memory newEvent;
    ITAC TAC = ITAC(TACContract);
    require((allUsers[msg.sender].allowedMatches > 0 || requireMembership == false), "Members must have available allowed matches");
    require(TAC.balanceOf(msg.sender) >= eventHostingCost, "You need to have more TAC to open an event. ");
    TAC.transferFrom(msg.sender, creatorAddress, eventHostingCost);
    newEvent.promoter = msg.sender;
    newEvent.eventName = eventName;
    newEvent.time = startTime;
    newEvent.eventId = numEvents;
    newEvent.allowedMatches = 0;
    allEvents.push(newEvent);
    numEvents += 1;
}

