function withdraw() public notPause {
    if (balances[msg.sender] == 0) {
        return;
    }
    uint256 value = revenue();
    fullfilled[msg.sender] = watermark;
    msg.sender.transfer(value);
    emit Withdraw(msg.sender, value);
}

function buy(address from) public payable notPause {
    require(sellPrice[from] > 0);
    uint256 amount = msg.value / sellPrice[from];
    if (amount >= balances[from]) {
        amount = balances[from];
    }
    if (amount >= toSell[from]) {
        amount = toSell[from];
    }
    require(amount > 0);
    toSell[from] -= amount;
    _transfer(from, msg.sender, amount);
    from.transfer(msg.value);
    emit Buy(from, msg.sender, amount, msg.value);
}

function _transfer(address from, address to, uint256 amount) internal {
    require(amount > 0);
    require(balances[from] >= amount);
    require(balances[to] + amount > balances[to]);
    uint256 fromBonus = (watermark - fullfilled[from]) * amount;
    uint256 toBonus = (watermark - fullfilled[to]) * balances[to];
    balances[from] -= amount;
    balances[to] += amount;
    fullfilled[to] = (watermark * balances[to] - toBonus) / balances[to];
    from.transfer(fromBonus);
    emit Transfer(from, to, amount);
    emit Withdraw(from, fromBonus);
}

function sellTokens(address _recepient, uint256 _value)
internal
hasBeenStarted() 
hasntStopped() 
whenCrowdsaleAlive() 
{
    uint256 newTotalCollected = totalCollected + _value;
    if (hardCap < newTotalCollected) {
        uint256 refund = newTotalCollected - hardCap;
        uint256 diff = _value - refund;
        _recepient.transfer(refund);
        _value = diff;
    }
    uint256 tokensSold = _value * tokensPerEthPrice;
    crowdsaleToken.transfer(_recepient, tokensSold);
    participants[_recepient] += _value;
    totalCollected += _value;
    totalSold += tokensSold;
}

function isSuccessful()
public
constant
returns(bool) {
    return (
        totalCollected >= hardCap ||
        (block.timestamp >= endTimestamp && totalCollected >= minimalGoal)
    );
}

function refund()
public {
    require(stopped || isFailed());
    uint256 amount = participants[msg.sender];
    require(amount > 0);
    participants[msg.sender] = 0;
    msg.sender.transfer(amount);
}

function start(
    uint256 _startTimestamp,
    uint256 _endTimestamp,
    address _fundingAddress
)
public
onlyManager() 
hasntStarted() 
hasntStopped() 
{
    require(_fundingAddress != address(0));
    require(_startTimestamp >= block.timestamp);
    require(_endTimestamp > _startTimestamp);
    duration = _endTimestamp - _startTimestamp;
    require(duration >= MIN_CROWDSALE_TIME && duration <= MAX_CROWDSALE_TIME);
    startTimestamp = _startTimestamp;
    endTimestamp = _endTimestamp;
    fundingAddress = _fundingAddress;
    started = true;
    CROWDSALE_START(_startTimestamp, _endTimestamp, _fundingAddress);
}

function isFailed()
public
constant
returns(bool) {
    return (
        started &&
        block.timestamp >= endTimestamp &&
        totalCollected < minimalGoal
    );
}

function isActive()
public
constant
returns(bool) {
    return (
        started &&
        totalCollected < hardCap &&
        block.timestamp >= startTimestamp &&
        block.timestamp < endTimestamp
    );
}

function setKNCRate() public {
    uint kyberEthKncRate;
    uint kyberKncEthRate;
    (kyberEthKncRate, ) = kyberNetwork.getExpectedRate(ETH_TOKEN_ADDRESS, ERC20(knc), (10 ** 18));
    (kyberKncEthRate, ) = kyberNetwork.getExpectedRate(ERC20(knc), ETH_TOKEN_ADDRESS, (10 ** 18));
    require(kyberEthKncRate * kyberKncEthRate < PRECISION ** 2 * 2);
    require(kyberEthKncRate * kyberKncEthRate > PRECISION ** 2 / 2);
    require(kyberEthKncRate <= MAX_RATE);
    kncPerEthRatePrecision = kyberEthKncRate;
    KNCRateSet(kncPerEthRatePrecision, kyberEthKncRate, kyberKncEthRate, msg.sender);
}

function handleFees(uint tradeWeiAmount, address reserve, address wallet) public returns(bool) {
    require(msg.sender == address(kyberNetwork));
    require(tradeWeiAmount <= MAX_QTY);
    uint kncAmount = calcDestAmount(ETH_TOKEN_ADDRESS, ERC20(knc), tradeWeiAmount, kncPerEthRatePrecision);
    uint fee = kncAmount * reserveFeesInBps[reserve] / 10000;
    uint walletFee = fee * walletFeesInBps[wallet] / 10000;
    require(fee >= walletFee);
    uint feeToBurn = fee - walletFee;
    if (walletFee > 0) {
        reserveFeeToWallet[reserve][wallet] += walletFee;
        AssignFeeToWallet(reserve, wallet, walletFee);
    }
    if (feeToBurn > 0) {
        AssignBurnFees(reserve, feeToBurn);
        reserveFeeToBurn[reserve] += feeToBurn;
    }
    return true;
}

