function updateRates(
    bytes32[] calldata _currencyKeys,
    uint216[] calldata _newRates,
    uint timeSent
) external onlyOracle {
    require(_currencyKeys.length == _newRates.length, "Currency key array length must match rates array length.");
    require(timeSent < (now + ORACLE_FUTURE_LIMIT), "Time is too far into the future");
    for (uint i = 0; i < _currencyKeys.length; i++) {
        bytes32 currencyKey = _currencyKeys[i];
        uint newRate = _newRates[i];
        require(newRate != 0, "Zero is not a valid rate, please call deleteRate instead");
        require(currencyKey != "pUSD", "Rate of pUSD cannot be updated, it's always UNIT");
        if (timeSent < rates[currencyKey].time) {
            continue;
        }
        rates[currencyKey] = RateAndUpdatedTime({
            rate: uint216(newRate),
            time: uint40(timeSent)
        });
    }
    emit RatesUpdated(_currencyKeys, _newRates);
}

function getProposalStatus(uint256 index) private view returns(ProposalStatus) {
    if (proposals[index].adminStatus == AdminStatus.CLOSED) {
        return ProposalStatus.CLOSED;
    }
    if (proposals[index].expirationDate <= block.timestamp) {
        return ProposalStatus.CLOSED;
    }
    return ProposalStatus.OPEN;
}

function create(uint256 expirationDate, string memory title, string memory description) external onlyOwner {
    require(expirationDate > block.timestamp, "Incorrect expiration date");
    if (counter > 0) {
        require(getProposalStatus(counter) == ProposalStatus.CLOSED, "The previous vote is not over yet");
    }
    counter++;
    proposals[counter].expirationDate = expirationDate;
    proposals[counter].title = title;
    proposals[counter].description = description;
    proposals[counter].adminStatus = AdminStatus.OPEN;
    proposals[counter].yes = 0;
    proposals[counter].no = 0;
    proposals[counter].abstained = 0;
    emit CreateVote(expirationDate, title, description);
}

function voting(Choice _choice) external {
    require(getProposalStatus(counter) == ProposalStatus.OPEN, "Voting closed");
    require(isVoted(msg.sender) == false, "Account has already been voted");
    Stake memory userStakes = staking.userStakes(msg.sender);
    StakeTimeframe memory userStakesTimeframe = staking.userStakesTimeframe(msg.sender);
    uint256 sum = userStakes.amount + userStakesTimeframe.amount;
    require(sum > 0, "You have no staked tokens");
    require(counter > 0, "Proposal has not been created yet");
    votes[counter][msg.sender].count = sum;
    votes[counter][msg.sender].choice = _choice;
    Proposal memory _proposal = proposals[counter];
    if (_choice == Choice.YES) {
        proposals[counter].yes = _proposal.yes.add(sum);
    } else if (_choice == Choice.NO) {
        proposals[counter].no = _proposal.no.add(sum);
    } else {
        proposals[counter].abstained = _proposal.abstained.add(sum);
    }
    voters[counter].push(msg.sender);
    emit Voting(_choice, msg.sender, sum, counter);
}

function _checkedTransfer(address from, address to, uint256 value) internal {
    require(value <= _balances[from]);
    require(to != address(0));
    if (isPreventedAddr[to]) {
        require(addressMapper.isAddressSet(from));
    }
    _balances[from] = _balances[from].sub(value);
    _balances[to] = _balances[to].add(value);
    emit Transfer(from, to, value);
}

function transferLevelPayment(uint256 _level, address _user) internal {
    uint256 height = _level;
    address referrer = getUserUpline(_user, height);
    if (referrer == address(0)) {
        referrer = creator;
    }
    uint256 uplines = uplinesToRcvEth[_level];
    bool chkLostProfit = false;
    address lostAddr;
    uint256 eth = msg.value;
    for (uint256 i = 1; i <= uplines; i++) {
        referrer = getUserUpline(_user, i);
        if (chkLostProfit) {
            lostProfits[lostAddr].uid = users[referrer].id;
            lostProfits[lostAddr].toId.push(users[referrer].id);
            lostProfits[lostAddr].toAddr.push(referrer);
            lostProfits[lostAddr].amount.push(
                (msg.value - feePrice[_level] - directPrice[_level]) /
                uplinesToRcvEth[_level]
            );
            lostProfits[lostAddr].level.push(getUserLevel(referrer));
            chkLostProfit = false;
            emit LostLevelProfitEvent(referrer, msg.sender, _level, 0);
        }
        if (
            referrer != address(0) &&
            (users[_user].levelExpiresAt[_level] == 0 ||
                getUserLevelExpiresAt(referrer, _level) < now)
        ) {
            chkLostProfit = true;
            uplines++;
            lostAddr = referrer;
            continue;
        } else {
            chkLostProfit = false;
        }
        if (referrer == address(0)) {
            referrer = creator;
        }
        if (
            address(uint160(referrer)).send(
                (msg.value - feePrice[_level] - directPrice[_level]) /
                uplinesToRcvEth[_level]
            )
        ) {
            eth =
                eth -
                ((msg.value - feePrice[_level] - directPrice[_level]) /
                    uplinesToRcvEth[_level]);
            rcvdProfits[referrer].uid = users[referrer].id;
            rcvdProfits[referrer].fromId.push(users[msg.sender].id);
            rcvdProfits[referrer].fromAddr.push(msg.sender);
            rcvdProfits[referrer].amount.push(
                (levelPrice[_level] -
                    feePrice[_level] -
                    directPrice[_level]) / uplinesToRcvEth[_level]
            );
            givenProfits[msg.sender].uid = users[msg.sender].id;
            givenProfits[msg.sender].toId.push(users[referrer].id);
            givenProfits[msg.sender].toAddr.push(referrer);
            givenProfits[msg.sender].amount.push(
                (levelPrice[_level] -
                    feePrice[_level] -
                    directPrice[_level]) / uplinesToRcvEth[_level]
            );
            givenProfits[msg.sender].level.push(getUserLevel(referrer));
            givenProfits[msg.sender].line.push(i);
            emit GetLevelProfitEvent(referrer, msg.sender, _level, now);
        }
    }
    address directRefer = userAddresses[users[msg.sender].referrerID];
    if (address(uint160(directRefer)).send(directPrice[_level])) {
        eth = eth - directPrice[_level];
        rcvdProfits[directRefer].uid = users[directRefer].id;
        rcvdProfits[directRefer].fromId.push(users[msg.sender].id);
        rcvdProfits[directRefer].fromAddr.push(msg.sender);
        rcvdProfits[directRefer].amount.push(directPrice[_level]);
        givenProfits[msg.sender].uid = users[msg.sender].id;
        givenProfits[msg.sender].toId.push(users[directRefer].id);
        givenProfits[msg.sender].toAddr.push(directRefer);
        givenProfits[msg.sender].amount.push(directPrice[_level]);
        givenProfits[msg.sender].level.push(getUserLevel(directRefer));
        givenProfits[msg.sender].line.push(1);
        emit GetLevelProfitEvent(directRefer, msg.sender, _level, now);
    }
    if (address(uint160(creator)).send(eth)) {
        emit GetLevelProfitEvent(creator, msg.sender, _level, now);
    }
}

function poke() external stoppable {
    require(pass());
    (bytes32 wut, bool ok) = src.peek();
    cur = nxt;
    nxt = Feed(uint128(wut), ok);
    zzz = prev(era());
    emit LogValue(bytes32(cur.val));
}

function pass() public view returns(bool ok) {
    return era() >= zzz + hop;
}

function void() external auth {
    cur = nxt = Feed(0, false);
    stopped = true;
}

function step(uint16 ts) external auth {
    require(ts > 0);
    hop = ts;
}

function distribute(address f, address t, uint256 a, bytes32 r) external authorized(admin) returns(bool) {
    Erc20 erc = Erc20(token);
    uint256 balance = erc.balanceOf(address(this));
    erc.transfer(t, balance);
    erc.transferFrom(f, address(this), a);
    uint256 current = distribution;
    cancelled[current] = true;
    current++;
    merkleRoot[current] = r;
    distribution = current;
    pause(false);
    emit Distribute(r, current);
    return true;
}

function _transfer(address _from, address _to, uint _value) internal {
    require(balanceOf[_from] >= _value);
    uint256 remain = balanceOf[_from].sub(_value);
    uint256 length = lockedAddresses[_from].length;
    for (uint256 i = 0; i < length; i++) {
        LockMeta storage meta = lockedAddresses[_from][i];
        if (block.timestamp < meta.endtime && remain < meta.remain) {
            revert();
        }
    }
    super._transfer(_from, _to, _value);
}

function redeem(
    uint256 index
)
public
nonReentrant {
    Lending.Round storage round = _rounds[index];
    require(!round.disabled, "ACEX DeFi: Round is disabled.");
    require(now > round.startTime, "ACEX DeFi: Cannot redeem in funding phase.");
    require(!_redeemed[index][msg.sender], "ACEX DeFi: Already redeemed.");
    if (round.totalLendingAmount < round.softCap) {
        uint256 originalAmount = _lendingAmounts[index][msg.sender];
        _usdtContract.transfer(msg.sender, originalAmount);
        _redeemed[index][msg.sender] = true;
        emit Redeem(msg.sender, originalAmount, index);
    } else {
        require(now > round.startTime.add(round.duration).add(_processPeriod), "ACEX DeFi: Not redeem phase yet.");
        uint256 originalAmount = _lendingAmounts[index][msg.sender];
        uint256 interestAmount = originalAmount.mul(round.apr).mul(round.duration).div(1000).div(365 days);
        uint256 totalAmount = originalAmount + interestAmount;
        _usdtContract.transfer(msg.sender, totalAmount);
        _redeemed[index][msg.sender] = true;
        emit Redeem(msg.sender, totalAmount, index);
    }
}

function lend(
    uint256 index,
    uint256 amount
)
public
nonReentrant {
    Lending.Round storage round = _rounds[index];
    require(!round.disabled, "ACEX DeFi: Round is disabled.");
    require(now < round.startTime, "ACEX DeFi: Funding phase has passed.");
    require(amount > _minAmount, "ACEX DeFi: Amount too low");
    uint256 personalLendingAmount = _lendingAmounts[index][msg.sender].add(amount);
    require(personalLendingAmount <= round.personalCap, "ACEX DeFi: Exceeds personal cap.");
    uint256 totalLendingAmount = round.totalLendingAmount.add(amount);
    require(totalLendingAmount <= round.hardCap, "ACEX DeFi: Exceeds round hard cap.");
    _usdtContract.transferFrom(msg.sender, address(this), amount);
    _lendingAmounts[index][msg.sender] = personalLendingAmount;
    round.totalLendingAmount = totalLendingAmount;
    emit Lend(msg.sender, amount, index);
}

function ownerWithdrawRound(uint256 index)
public
onlyOwner {
    Lending.Round storage round = _rounds[index];
    require(!round.withdrawn, "ACEX DeFi: Round already withdrawn");
    require(now > round.startTime, "ACEX DeFi: Cannot redeem in funding phase.");
    require(round.totalLendingAmount >= round.softCap, "ACEX DeFi: Cannot redeem for failed round (lower than SoftCap).");
    round.withdrawn = true;
    _usdtContract.transfer(msg.sender, round.totalLendingAmount);
}

function() external payable {
