    uint256 fee = devFee(msg.value);
    uint256 fee2 = fee / 2;
    ceoAddress.transfer(fee2);
    ceoAddress2.transfer(fee - fee2);
    claimedEggs[msg.sender] = SafeMath.add(claimedEggs[msg.sender], eggsBought);
