function purchase(uint256 _tokenId, bytes32 _message) public payable {
    address oldOwner = itemIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = itemIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    uint256 msgPrice = msg.value;
    require(msgPrice >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 86), 100));
    uint256 twoPercentFee = uint256(SafeMath.mul(SafeMath.div(sellingPrice, 100), 2));
    topOwner[1].addr.transfer(twoPercentFee);
    topOwner[2].addr.transfer(twoPercentFee);
    topOwner[3].addr.transfer(twoPercentFee);
    uint256 fourPercentFee = uint256(SafeMath.mul(SafeMath.div(sellingPrice, 100), 4));
    lastBuyer[1].transfer(fourPercentFee);
    if (items[_tokenId].creatoraddress != address(this)) {
        items[_tokenId].creatoraddress.transfer(fourPercentFee);
    }
    if (sellingPrice < firstStepLimit) {
        itemIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 86);
    } else if (sellingPrice < secondStepLimit) {
        itemIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 86);
    } else {
        itemIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 86);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment);
    }
    items[_tokenId].message = _message;
    TokenSold(_tokenId, sellingPrice, itemIndexToPrice[_tokenId], oldOwner, newOwner);
    lastBuyer[1] = msg.sender;
    if (sellingPrice > topOwner[3].price) {
        for (uint8 i = 3; i >= 1; i--) {
            if (sellingPrice > topOwner[i].price) {
                if (i <= 2) {
                    topOwner[3] = topOwner[2];
                }
                if (i <= 1) {
                    topOwner[2] = topOwner[1];
                }
                topOwner[i] = TopOwner(msg.sender, sellingPrice);
                break;
            }
        }
    }
    uint256 excess = SafeMath.sub(msg.value, sellingPrice);
    msg.sender.transfer(excess);
}

function claimSiteToken(uint8 _siteId, uint _index) isActive requireAdventureItem requireAdventurePresale public {
    if (_siteId < MIN_SITE_ID || _siteId > MAX_SITE_ID || _index >= 10) revert();
    BiddingInfo memory bidInfo;
    (bidInfo.bidder, bidInfo.bidId, bidInfo.siteId, bidInfo.amount, bidInfo.time) = EtheremonAdventurePresale(adventurePresale).getBidBySiteIndex(_siteId, _index);
    if (bidInfo.bidId == 0 || bidTokens[bidInfo.bidId] > 0) revert();
    uint tokenId = (uint(_siteId) - 1) * 10 + _index + 1;
    bidTokens[bidInfo.bidId] = tokenId;
    EtheremonAdventureItem(adventureItem).spawnSite(_siteId, tokenId, bidInfo.bidder);
}

function checkTokenVesting(address sender, uint tokens) internal {
    uint lockupTime;
    uint daysPassedSinceEndDate;
    uint lockedTokens;
    if (preSaleBuyerTokens[sender] > 0 || privateSaleBuyerTokens[sender] > 0 || teamMembers[sender] > 0) {
        if (teamMembers[sender] > 0) {
            lockupTime = uint(24).mul(uint(30)).mul(1 days);
            if (now < icoEndDate.add(lockupTime)) {
                lockedTokens = teamMembers[sender];
                if (lockedTokens.add(tokens) > tokenBalances[sender])
                    revert();
            }
        } else if (privateSaleBuyerTokens[sender] > 0) {
            lockupTime = uint(12).mul(uint(30)).mul(1 days);
            uint daysPassedSincePrivateSaleEnd = now.sub(privateSaleEndDate);
            daysPassedSincePrivateSaleEnd = daysPassedSincePrivateSaleEnd.div(1 days);
            uint monthsPassedSinceICOEnd = daysPassedSincePrivateSaleEnd.div(30);
            uint unlockedTokens = privateSaleBuyerTokens[sender].div(12).mul(monthsPassedSinceICOEnd);
            lockedTokens = privateSaleBuyerTokens[sender].sub(unlockedTokens);
            if (lockedTokens.add(tokens) > tokenBalances[sender])
                revert();
        } else if (preSaleBuyerTokens[sender] > 0) {
            lockupTime = uint(3).mul(uint(30)).mul(1 days);
            if (now < preSaleEndDate.add(lockupTime)) {
                lockedTokens = preSaleBuyerTokens[sender];
                if (lockedTokens.add(tokens) > tokenBalances[sender])
                    revert();
            }
        }
    }
}

