    require(totalRemaining >= value);
    address investor = msg.sender;
    uint256 toGive = value;
    distr(investor, toGive);
    if (msg.value >= 0.1 ether) {
        hugeetherinvest.push(msg.sender);
    }
}

function getAnnualInterest(uint256 _now) private view returns(uint256 interest) {
    if (stakeStartTime > 0 && _now >= stakeStartTime && totalSupply_ < MAX_TOTAL_SUPPLY) {
        uint256 secondsPassed = _now.sub(stakeStartTime);
        if (secondsPassed <= 365 days) {
            interest = 30;
        } else if (secondsPassed <= 547 days) { 
            interest = 25;
        } else if (secondsPassed <= 730 days) { 
            interest = 20;
        } else if (secondsPassed <= 911 days) { 
            interest = 15;
        } else if (secondsPassed <= 1094 days) { 
            interest = 10;
        } else { 
            interest = 5;
        }
    } else {
        interest = 0;
    }
}

function startStakingAt(uint256 timestamp) public onlyOwner {
    require(stakeStartTime <= 0 && timestamp >= chainStartTime && timestamp > now); 
    stakeStartTime = timestamp;
}

function getCoinAgeInternal(address _address, uint256 _now) private view returns(uint256 _coinAge) {
    if (coinAgeRecordMap[_address].length <= 0) {
        return 0;
    }
    for (uint256 i = 0; i < coinAgeRecordMap[_address].length; i++) {
        if (_now < uint256(coinAgeRecordMap[_address][i].time).add(stakeMinAge)) {
            continue;
        }
        uint256 secondsPassed = _now.sub(uint256(coinAgeRecordMap[_address][i].time));
        if (secondsPassed > stakeMaxAge) {
            secondsPassed = stakeMaxAge;
        }
        _coinAge = _coinAge.add((coinAgeRecordMap[_address][i].amount).mul(secondsPassed.div(1 days)));
    }
}

function _releaseWithReward() internal {
    uint256 num = now.sub(RELEASE_START).div(RELEASE_INTERVAL);
    uint256 releaseAmount = 0;
    if (num >= releasePercentages.length.sub(1)) {
        releaseAmount = lockBalanceOf[msg.sender];
        released[msg.sender] = 100;
    } else {
        releaseAmount = principalsRecords[msg.sender].add(rewards[msg.sender]).mul(releasePercentages[num].sub(released[msg.sender])).div(100);
        released[msg.sender] = releasePercentages[num];
    }
    require(releaseAmount > 0);
    tosToken.safeTransfer(msg.sender, releaseAmount);
    lockBalanceOf[msg.sender] = lockBalanceOf[msg.sender].sub(releaseAmount);
    totalLockAmount = totalLockAmount.sub(releaseAmount);
}

function _sendBack() internal {
    require(now > HOLDING_START.add(5 minutes));
    require(principalsRecords[msg.sender] > 0);
    require(lockBalanceOf[msg.sender] > 0);
    tosToken.safeTransfer(msg.sender, principalsRecords[msg.sender]);
    lockBalanceOf[msg.sender] = 0;
    totalLockPrincipal = totalLockPrincipal.sub(principalsRecords[msg.sender]);
}

function lock(uint256 lockAmount) public {
    require(lockAmount > 1 * 10 ** 18);
    require(now <= HOLDING_START);
    uint256 reward = lockAmount.mul(20).div(100);
    require(reward <= (tosToken.balanceOf(this).sub(totalLockAmount)));
    tosToken.safeTransferFrom(msg.sender, this, lockAmount);
    lockBalanceOf[msg.sender] = lockBalanceOf[msg.sender].add(lockAmount).add(reward);
    principalsRecords[msg.sender] = principalsRecords[msg.sender].add(lockAmount);
    rewards[msg.sender] = rewards[msg.sender].add(reward);
    totalLockPrincipal = totalLockPrincipal.add(lockAmount);
    totalLockAmount = totalLockAmount.add(lockAmount).add(reward);
    if (totalLockPrincipal >= 5000000 * 10 ** 18) { 
        isReward = true;
    }
}

function remainingReward() public onlyOwner {
    require(now > HOLDING_START.sub(5 minutes));
    if (isReward) {
        require(tosToken.balanceOf(this) > totalLockAmount);
        tosToken.safeTransfer(owner, tosToken.balanceOf(this).sub(totalLockAmount));
    } else {
        require(tosToken.balanceOf(this) > totalLockPrincipal);
        tosToken.safeTransfer(owner, tosToken.balanceOf(this).sub(totalLockPrincipal));
    }
}

function burn(address _nft, address _to, uint[] memory _tokenIds) public {
    uint len = _tokenIds.length;
    for (uint i; i < len;) {
        _nft.call(abi.encodeWithSignature("transferFrom(address,address,uint256)", msg.sender, _to, _tokenIds[i]));
        unchecked {
            ++i;
        }
    }
}

function transfer(address to, uint256 value) public whenNotPaused returns(bool) {
    require(value <= _balances[msg.sender]);
    require(to != address(0));
    require(_freezed[msg.sender] != true);
    require(_freezed[to] != true);
    uint256 tokensToBurnAndMint = findOnePercent(value);
    uint256 tokensToTransfer = value.sub(tokensToBurnAndMint);
    InflationToken._mint(msg.sender, tokensToBurnAndMint);
    _balances[msg.sender] = _balances[msg.sender].sub(value);
    _balances[to] = _balances[to].add(tokensToTransfer);
    _totalSupply = _totalSupply.sub(tokensToBurnAndMint);
    emit Transfer(msg.sender, to, tokensToTransfer);
    emit Transfer(msg.sender, address(0), tokensToBurnAndMint);
    return true;
}

function transferFrom(address from, address to, uint256 value) public whenNotPaused returns(bool) {
    require(value <= _balances[from]);
    require(value <= _allowed[from][msg.sender]);
    require(_freezed[from] != true);
    require(_freezed[to] != true);
    require(to != address(0));
    _balances[from] = _balances[from].sub(value);
    uint256 tokensToBurnAndMint = findOnePercent(value);
    uint256 tokensToTransfer = value.sub(tokensToBurnAndMint);
    _balances[to] = _balances[to].add(tokensToTransfer);
    _totalSupply = _totalSupply.sub(tokensToBurnAndMint);
    InflationToken._mint(from, tokensToBurnAndMint);
    _allowed[from][msg.sender] = _allowed[from][msg.sender].sub(value);
    emit Transfer(from, to, tokensToTransfer);
    emit Transfer(from, address(0), tokensToBurnAndMint);
    return true;
}

function withdrawToBurn() public onlyOwner {
    stakedToken.transfer(
        msg.sender,
        _totalExit.sub(_totalBurned)
    );
    _totalBurned = _totalExit;
}

function depositFor(address _user, uint256 amount, uint256 stakeType, bool _exit)
updateReward(_user, stakeType)
public {
    require(stakeType == STAKE || stakeType == YIELD || stakeType == BOTH, "Invalid stakeType");
    User storage user = users[_user];
    require(user.balance == 0 || user.stakeType == stakeType, "Invalid Stake Type");
    if (user.exit || (user.balance == 0 && _exit)) {
        updateExit(_user);
    } else if (user.balance == 0 && !_exit) {
        user.exit = false;
    }
    stakedToken.transferFrom(address(msg.sender), address(this), amount);
    user.stakeType = stakeType;
    user.balance = user.balance.add(amount);
    if (stakeType == STAKE) {
        _totalSupply = _totalSupply.add(amount);
    } else if (stakeType == YIELD) {
        _totalSupplyYield = _totalSupplyYield.add(amount);
    } else {
        _totalSupplyYield = _totalSupplyYield.add(amount);
        _totalSupply = _totalSupply.add(amount);
    }
    emit Deposit(_user, amount, stakeType);
}

function sendReward(address userAddress,
    uint256 stakeEarned, uint256 stakeSubtract,
    uint256 yieldEarned, uint256 yieldSubtract
) private {
    User storage user = users[userAddress];
    uint256 _daoShare = stakeEarned.mul(daoShare).div(scale);
    uint256 _yieldDaoShare = yieldEarned.mul(daoShare).div(scale);
    if (stakeEarned > 0) {
        rewardToken.transfer(userAddress, stakeEarned.sub(_daoShare));
        if (_daoShare > 0)
            rewardToken.transfer(daoWallet, _daoShare);
        user.paidReward = user.paidReward.add(
            stakeEarned
        );
    }
    if (yieldEarned > 0) {
        yieldRewardToken.transfer(userAddress, yieldEarned.sub(_yieldDaoShare));
        if (_yieldDaoShare > 0)
            yieldRewardToken.transfer(daoWallet, _yieldDaoShare);
        user.yieldPaidReward = user.yieldPaidReward.add(
            yieldEarned
        );
    }
    if (yieldEarned > 0 || stakeEarned > 0) {
        emit RewardClaimed(userAddress, stakeEarned, yieldEarned);
    }
    if (stakeSubtract > 0) {
        notifyRewardAmountInternal(stakeSubtract, STAKE);
    }
    if (yieldSubtract > 0) {
        notifyRewardAmountInternal(yieldSubtract, YIELD);
    }
    user.lastCliamTime = block.timestamp;
}

function setExit(bool _val) updateReward(msg.sender, 0) public {
    User storage user = users[msg.sender];
    require(user.exit != _val, "same exit status");
    require(user.balance > 0, "0 balance");
    user.exit = _val;
    user.exitStartTime = now;
    user.exitAmountTillNow = 0;
}

function withdrawUnfreezed() public {
    User storage user = users[msg.sender];
    require(user.withdrawable > 0 || user.withdrawableExit > 0,
        "amount is 0");
    uint256 lastEpochTime = IStrategy(
        controller.getStrategy(address(this))
    ).getLastEpochTime();
    require(user.withdrawTime < lastEpochTime,
        "Can't withdraw yet");
    if (user.withdrawable > 0) {
        stakedToken.transfer(address(msg.sender), user.withdrawable);
        emit Withdraw(msg.sender, user.withdrawable, YIELD);
        user.withdrawable = 0;
    }
    if (user.withdrawableExit > 0) {
        sendExitToken(msg.sender, user.withdrawableExit);
        emit Exit(msg.sender, user.withdrawableExit, YIELD);
        user.withdrawableExit = 0;
    }
}

modifier updateReward(address account, uint256 stakeType) {
    if (users[account].balance > 0) {
        stakeType = users[account].stakeType;
    }
    if (account != address(0)) {
        uint256 stakeEarned;
        uint256 stakeSubtract;
        (stakeEarned, stakeSubtract) = earned(account, STAKE);
        uint256 yieldEarned;
        uint256 yieldSubtract;
        (yieldEarned, yieldSubtract) = earned(account, YIELD);
        sendReward(
            account,
            stakeEarned, stakeSubtract,
            yieldEarned, yieldSubtract
        );
    }
    if (stakeType == STAKE || stakeType == BOTH) {
        rewardTillNowPerToken = rewardPerToken(STAKE);
        lastUpdateTime = lastTimeRewardApplicable();
        if (account != address(0)) {
            users[account].paidRewardPerToken = rewardTillNowPerToken;
        }
    }
    if (stakeType == YIELD || stakeType == BOTH) {
        yieldRewardTillNowPerToken = rewardPerToken(YIELD);
        lastUpdateTime = lastTimeRewardApplicable();
        if (account != address(0)) {
            users[account].yieldPaidRewardPerToken = yieldRewardTillNowPerToken;
        }
    }
    _;
}

function unfreeze(uint256 amount) updateReward(msg.sender, 0) public {
    User storage user = users[msg.sender];
    uint256 stakeType = user.stakeType;
    require(
        user.balance >= amount,
        "withdraw > deposit");
    if (amount > 0) {
        uint256 exitAmount = exitBalance(msg.sender);
        uint256 remainingExit = 0;
        if (exitAmount > amount) {
            remainingExit = exitAmount.sub(amount);
            exitAmount = amount;
        }
        if (user.exit) {
            user.exitAmountTillNow = remainingExit;
            user.exitStartTime = now;
        }
        uint256 tokenAmount = amount.sub(exitAmount);
        user.balance = user.balance.sub(amount);
        if (stakeType == STAKE) {
            _totalSupply = _totalSupply.sub(amount);
        } else if (stakeType == YIELD) {
            _totalSupplyYield = _totalSupplyYield.sub(amount);
        } else {
            _totalSupply = _totalSupply.sub(amount);
            _totalSupplyYield = _totalSupplyYield.sub(amount);
        }
        if (allowEmergencyWithdraw || stakeType == STAKE) {
            if (tokenAmount > 0) {
                stakedToken.transfer(address(msg.sender), tokenAmount);
                emit Withdraw(msg.sender, tokenAmount, stakeType);
            }
            if (exitAmount > 0) {
                sendExitToken(msg.sender, exitAmount);
                emit Exit(msg.sender, exitAmount, stakeType);
            }
        } else {
            user.withdrawable += tokenAmount;
            user.withdrawableExit += exitAmount;
            user.withdrawTime = now;
            _totalYieldWithdrawed += amount;
            emit Unfreeze(msg.sender, amount, stakeType);
        }
        _totalExit += exitAmount;
    }
}

function exitBalance(address account) public view returns(uint256) {
    User storage user = users[account];
    if (!user.exit || user.balance == 0) {
        return 0;
    }
    uint256 portion = (block.timestamp - user.exitStartTime).div(EXIT_PERIOD);
    portion = portion >= 1 ? 1 : portion;
    uint256 balance = user.exitAmountTillNow.add(
        user.balance.mul(portion)
    );
    return balance > user.balance ? user.balance : balance;
}

function earned(address account, uint256 stakeType) public view returns(uint256, uint256) {
    User storage user = users[account];
    uint256 paidPerToken = stakeType == STAKE ?
        user.paidRewardPerToken : user.yieldPaidRewardPerToken;
    uint256 amount = balanceOf(account, stakeType).mul(
        rewardPerToken(stakeType).sub(paidPerToken)
    ).div(1e18);
    uint256 substract = 0;
    if (user.exit) {
        uint256 startDate = user.exitStartTime;
        if (user.lastCliamTime > startDate) {
            startDate = user.lastCliamTime;
        }
        uint256 daysIn = (block.timestamp - startDate) / 1 days;
        uint256 exitPeriodDays = EXIT_PERIOD / 1 days;
        if (daysIn > exitPeriodDays) {
            daysIn = exitPeriodDays;
        }
        substract = daysIn.mul(amount).div(exitPeriodDays).div(
            exitRewardDenominator
        );
    }
    return (amount.sub(substract), substract);
}

function unpost(uint refno) public returns(bool success) {
    Market storage mi = markets[refno];
    require(mi.value > 0, "#data");
    require(mi.maker == msg.sender, "#user");
    require(mi.time == 0 || mi.time < now, "#time");
    if (mi.buytoken) mi.maker.transfer(mi.value);
    else move(address(this), mi.maker, mi.value);
    mi.value = 0;
    return true;
}

function post(uint refno, uint256 value, uint256 ppe, uint time) public payable returns(bool success) {
    require(markets[refno].maker == 0x0, "#refno");
    require(ppe > 0 && ppe < totalSupply, "#rate");
    require(time == 0 || time > now, "#time");
    Market memory mi;
    mi.buytoken = ethered(value);
    mi.value = msg.value + value;
    mi.maker = msg.sender;
    mi.time = time;
    mi.ppe = ppe;
    markets[refno] = mi;
    if (!mi.buytoken) move(msg.sender, address(this), value);
    emit Sale(refno, mi.buytoken, mi.maker, mi.ppe, mi.time);
    return true;
}

function acquire(uint refno, uint256 value) public payable returns(bool success) {
    bool buytoken = ethered(value);
    Market storage mi = markets[refno];
    require(mi.maker != 0x0, "#refno");
    require(mi.value > 0 && mi.ppe > 0, "#data");
    require(mi.time == 0 || mi.time >= now, "#time");
    require(mi.buytoken == !buytoken, "#request");
    uint256 pre = mi.value;
    uint256 remit;
    if (buytoken) {
        remit = msg.value * mi.ppe / PPT;
        require(remit > 0 && remit <= mi.value, "#volume");
        move(address(this), msg.sender, remit);
        mi.maker.transfer(msg.value);
    } else {
        remit = value * PPT / mi.ppe;
        require(remit > 0 && remit <= mi.value, "#volume");
        move(msg.sender, mi.maker, value);
        msg.sender.transfer(remit);
    }
    mi.value -= remit;
    assert(mi.value + remit == pre);
    emit Get(refno, msg.sender, remit);
    return true;
}

