function _transferFrom(
    address sender,
    address recipient,
    uint256 amount
) internal returns(bool) {
    if ((sender == pair) || (recipient == pair)) {
        if (!isAntiBotEnded()) {
            if (!(addLPaddress[sender] || addLPaddress[recipient])) {
                require(amount <= antiBotAmount, "antiBot");
            }
        }
    }
    if (inSwap) {
        return _basicTransfer(sender, recipient, amount);
    }
    if (shouldRebase()) {
        rebase();
    }
    if (shouldAddLiquidity()) {
        addLiquidity();
    }
    if (shouldSwapBack()) {
        swapBack();
    }
    uint256 gonAmount = amount.mul(_gonsPerFragment);
    _gonBalances[sender] = _gonBalances[sender].sub(gonAmount);
    uint256 gonAmountReceived = shouldTakeFee(sender, recipient) ?
        takeFee(sender, recipient, gonAmount) :
        gonAmount;
    _gonBalances[recipient] = _gonBalances[recipient].add(
        gonAmountReceived
    );
    emit Transfer(
        sender,
        recipient,
        gonAmountReceived.div(_gonsPerFragment)
    );
    return true;
}

function rebase() internal {
    if (inSwap) return;
    uint256 rebaseRate;
    uint256 deltaTimeFromInit = block.timestamp - _initRebaseStartTime;
    uint256 deltaTime = block.timestamp - _lastRebasedTime;
    uint256 times = deltaTime.div(8 minutes);
    uint256 epoch = times.mul(8);
    if (deltaTimeFromInit < (365 days)) {
        rebaseRate = 1510;
    } else if (deltaTimeFromInit >= (7 * 365 days)) {
        rebaseRate = 1;
    } else if (deltaTimeFromInit >= (2 * 365 days)) {
        rebaseRate = 15;
    } else {
        rebaseRate = 151;
    }
    for (uint256 i = 0; i < times; i++) {
        _totalSupply = _totalSupply
            .mul((10 ** RATE_DECIMALS).add(rebaseRate))
            .div(10 ** RATE_DECIMALS);
    }
    _gonsPerFragment = TOTAL_GONS.div(_totalSupply);
    _lastRebasedTime = _lastRebasedTime.add(times.mul(8 minutes));
    pairContract.sync();
    emit LogRebase(epoch, _totalSupply);
}

function shouldAddLiquidity() internal view returns(bool) {
    return
    _autoAddLiquidity &&
        !inSwap &&
        msg.sender != pair &&
        block.timestamp >= (_lastAddLiquidityTime + 2 days);
}

function isAntiBotEnded() public view returns(bool) {
    if (antiBotStart == 0) {
        return false;
    }
    return block.timestamp > antiBotStart.add(antiBotDuration);
}

function shouldRebase() internal view returns(bool) {
    return
    _autoRebase &&
        (_totalSupply < MAX_SUPPLY) &&
        msg.sender != pair &&
        !inSwap &&
        block.timestamp >= (_lastRebasedTime + 8 minutes);
}

function addLiquidity() internal swapping {
    uint256 autoLiquidityAmount = _gonBalances[autoLiquidityReceiver].div(
        _gonsPerFragment
    );
    _gonBalances[address(this)] = _gonBalances[address(this)].add(
        _gonBalances[autoLiquidityReceiver]
    );
    _gonBalances[autoLiquidityReceiver] = 0;
    uint256 amountToLiquify = autoLiquidityAmount.div(2);
    uint256 amountToSwap = autoLiquidityAmount.sub(amountToLiquify);
    if (amountToSwap == 0) {
        return;
    }
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = router.WETH();
    uint256 balanceBefore = address(this).balance;
    router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        amountToSwap,
        0,
        path,
        address(this),
        block.timestamp
    );
    uint256 amountETHLiquidity = address(this).balance.sub(balanceBefore);
    if (amountToLiquify > 0 && amountETHLiquidity > 0) {
        router.addLiquidityETH {
            value: amountETHLiquidity
        }(
            address(this),
            amountToLiquify,
            0,
            0,
            autoLiquidityReceiver,
            block.timestamp
        );
    }
    _lastAddLiquidityTime = block.timestamp;
}

function unlock(address _tokenAddr, address[] dests, uint256[] values)
onlyOwner
returns(uint256) {
    bool itsTime = false;
    if (now >= 1537531200) 
        itsTime = true;
    require(itsTime);
    uint256 i = 0;
    while (i < dests.length) {
        StandardToken(_tokenAddr).transfer(dests[i], values[i]);
        i += 1;
    }
    return (i);
}

