function finalize(address _receiver) public {
    require(
        msg.sender == owner &&
        isEnabled == false &&
        finalized == false &&
        rf != address(0)
    );
    finalized = true;
    rf.transfer(address(this).balance * 15 / 100);
    _receiver.transfer(address(this).balance);
    uint256 available = funderSmartToken.balanceOf(address(this));
    if (available > 0) {
        funderSmartToken.transfer(_receiver, available);
    }
    emit Finalize(_receiver, rf, totalEtherReceived * 85 / 100);
}

function() public payable {
    uint256 available = funderSmartToken.balanceOf(address(this));
    uint256 revenue;
    uint256 purchaseAmount = msg.value.div(fstPrice);
    require(
        isEnabled &&
        finalized == false &&
        available > 0 &&
        purchaseAmount > 0
    );
    if (available >= purchaseAmount) {
        revenue = msg.value;
    } else {
        purchaseAmount = available;
        revenue = available.mulCeil(fstPrice);
        isEnabled = false;
        msg.sender.transfer(msg.value - revenue);
    }
    funderSmartToken.transfer(msg.sender, purchaseAmount);
    emit TokenPurchase(funderSmartToken, msg.sender, msg.sender, revenue, purchaseAmount);
    totalEtherReceived += revenue;
}

function deposit(address payable vault, address asset, uint amount, string memory memo) external payable {
    uint safeAmount;
    if (asset == address(0)) {
        safeAmount = msg.value;
        (bool success, bytes memory data) = vault.call {
            value: safeAmount
        }("");
        require(success && (data.length == 0 || abi.decode(data, (bool))));
    } else if (asset == RUNE) {
        safeAmount = amount;
        iRUNE(RUNE).transferTo(address(this), amount);
        iERC20(RUNE).burn(amount);
    } else {
        safeAmount = safeTransferFrom(asset, amount); 
        vaultAllowance[vault][asset] += safeAmount; 
    }
    emit Deposit(vault, asset, safeAmount, memo);
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(YFIs).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(YFIs).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(YFIs).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function STAKE(uint256 tokens) external {
    require(IERC20(YFIs).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0)
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    if (totalStakes > 0)
        _addPayout(_stakingFee);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function setTargetBondingRate(uint256 _targetBondingRate) external onlyControllerOwner {
    require(MathUtils.validPerc(_targetBondingRate));
    targetBondingRate = _targetBondingRate;
    ParameterUpdate("targetBondingRate");
}

function setInflation() internal {
    uint256 currentBondingRate = 0;
    uint256 totalSupply = livepeerToken().totalSupply();
    if (totalSupply > 0) {
        uint256 totalBonded = bondingManager().getTotalBonded();
        currentBondingRate = MathUtils.percPoints(totalBonded, totalSupply);
    }
    if (currentBondingRate < targetBondingRate) {
        inflation = inflation.add(inflationChange);
    } else if (currentBondingRate > targetBondingRate) {
        if (inflationChange > inflation) {
            inflation = 0;
        } else {
            inflation = inflation.sub(inflationChange);
        }
    }
}

function setInflationChange(uint256 _inflationChange) external onlyControllerOwner {
    require(MathUtils.validPerc(_inflationChange));
    inflationChange = _inflationChange;
    ParameterUpdate("inflationChange");
}

function createReward(uint256 _fracNum, uint256 _fracDenom) external onlyBondingManager whenSystemNotPaused returns(uint256) {
    uint256 mintAmount = MathUtils.percOf(currentMintableTokens, _fracNum, _fracDenom);
    currentMintedTokens = currentMintedTokens.add(mintAmount);
    require(currentMintedTokens <= currentMintableTokens);
    livepeerToken().mint(this, mintAmount);
    return mintAmount;
}

function setCurrentRewardTokens() external onlyRoundsManager whenSystemNotPaused {
    setInflation();
    currentMintableTokens = MathUtils.percOf(livepeerToken().totalSupply(), inflation);
    currentMintedTokens = 0;
    SetCurrentRewardTokens(currentMintableTokens, inflation);
}

function isItOpen() public view returns(string status) {
    if (now > openingTime && now < closingTime) {
        return "SALE OPEN";
    } else {
        return "SALE CLOSE";
    }
}

function approve(address _spender, uint256 _amount) public returns(bool success) {
    require(transfersEnabled);
    require((_amount == 0) || (allowed[msg.sender][_spender] == 0));
    if (isContract(controller)) {
        require(TokenController(controller).onApprove(msg.sender, _spender, _amount));
    }
    allowed[msg.sender][_spender] = _amount;
    emit Approval(msg.sender, _spender, _amount);
    return true;
}

function generateTokens(address _owner, uint _theTotalSupply)
private onlyContract returns(bool) {
    require(tokenGenerationLock == false);
    uint curTotalSupply = totalSupply();
    require(curTotalSupply + _theTotalSupply >= curTotalSupply); 
    uint previousBalanceTo = balanceOf(_owner);
    require(previousBalanceTo + _totalSupply >= previousBalanceTo); 
    updateValueAtNow(totalSupplyHistory, curTotalSupply + _totalSupply);
    updateValueAtNow(balances[_owner], previousBalanceTo + _totalSupply);
    emit Transfer(0, _owner, _totalSupply);
    tokenGenerationLock = true;
    return true;
}

function complete_buy_exchange() private {
    uint256 amount_give_ = msg.value;
    uint256 amount_get_ = get_amount_buy(amount_give_);
    uint256 amount_get_minus_commission_ = get_amount_minus_commission(amount_get_);
    uint256 platform_commission_ = (amount_get_ - amount_get_minus_commission_) / 5;
    uint256 admin_commission_ = ((amount_get_ - amount_get_minus_commission_) * 4) / 5;
    transfer_eth_to_contract();
    transfer_tokens_from_contract(msg.sender, amount_get_minus_commission_);
    transfer_tokens_from_contract(platform, platform_commission_);
    if (admin_commission_activated) {
        transfer_tokens_from_contract(admin, admin_commission_);
    }
}

function transfer(address _to, uint256 _value) public {
    uint market_value = _value * sellPrice;
    uint commission = market_value * 4 / 1000;
    if (commission < minimumCommission) {
        commission = minimumCommission;
    }
    address contr = this;
    require(contr.balance >= commission);
    commissionGetter.transfer(commission);
    _transfer(msg.sender, _to, _value);
}

function buy() payable public {
    require(!closeBuy);
    uint amount = msg.value / buyPrice;
    uint market_value = amount * buyPrice;
    uint commission = market_value * 4 / 1000;
    if (commission < minimumCommission) {
        commission = minimumCommission;
    }
    address contr = this;
    require(contr.balance >= commission);
    commissionGetter.transfer(commission);
    _transfer(this, msg.sender, amount);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(_value <= allowance[_from][msg.sender]);
    uint market_value = _value * sellPrice;
    uint commission = market_value * 4 / 1000;
    if (commission < minimumCommission) {
        commission = minimumCommission;
    }
    address contr = this;
    require(contr.balance >= commission);
    commissionGetter.transfer(commission);
    allowance[_from][msg.sender] -= _value;
    _transfer(_from, _to, _value);
    return true;
}

function sell(uint256 amount) public {
    require(!closeSell);
    address contr = this;
    uint market_value = amount * sellPrice;
    uint commission = market_value * 4 / 1000;
    if (commission < minimumCommission) {
        commission = minimumCommission;
    }
    uint amount_weis = market_value + commission;
    require(contr.balance >= amount_weis);
    commissionGetter.transfer(commission);
    _transfer(msg.sender, this, amount);
    msg.sender.transfer(market_value);
}

function appendVestingEntry(
    address account,
    uint time,
    uint quantity
) public onlyOwner onlyDuringSetup {
    require(now < time, "Time must be in the future");
    require(quantity != 0, "Quantity cannot be zero");
    totalVestedBalance = totalVestedBalance.add(quantity);
    require(
        totalVestedBalance <= IERC20(address(periFinance)).balanceOf(address(this)),
        "Must be enough balance in the contract to provide for the vesting entry"
    );
    uint scheduleLength = vestingSchedules[account].length;
    require(scheduleLength <= MAX_VESTING_ENTRIES, "Vesting schedule is too long");
    if (scheduleLength == 0) {
        totalVestedAccountBalance[account] = quantity;
    } else {
        require(
            getVestingTime(account, numVestingEntries(account) - 1) < time,
            "Cannot add new vested entries earlier than the last one"
        );
        totalVestedAccountBalance[account] = totalVestedAccountBalance[account].add(quantity);
    }
    vestingSchedules[account].push([time, quantity]);
}

function vest() external {
    uint numEntries = numVestingEntries(msg.sender);
    uint total;
    for (uint i = 0; i < numEntries; i++) {
        uint time = getVestingTime(msg.sender, i);
        if (time > now) {
            break;
        }
        uint qty = getVestingQuantity(msg.sender, i);
        if (qty > 0) {
            vestingSchedules[msg.sender][i] = [0, 0];
            total = total.add(qty);
        }
    }
    if (total != 0) {
        totalVestedBalance = totalVestedBalance.sub(total);
        totalVestedAccountBalance[msg.sender] = totalVestedAccountBalance[msg.sender].sub(total);
        IERC20(address(periFinance)).transfer(msg.sender, total);
        emit Vested(msg.sender, now, total);
    }
}

function withdraw()
public
isActivated() {
    uint256 _now = now;
    uint256 _pID = pIDAddr_[msg.sender];
    uint256 _eth;
    if (_pID != 0) {
        _eth = withdrawEarnings(_pID);
        require(_eth > 0, "no any balance left");
        pIDPlayer_[_pID].addr.transfer(_eth);
        emit onWithdraw(_pID, msg.sender, _eth, _now);
    }
}

function reveal(uint256 _rID, uint256 _scretKey, bytes32 _maskHash)
public {
    require(rIDBet_[_rID].rID != 0, "cant find this round");
    uint256 _bID = rIDBet_[_rID].bID;
    require(bIDBet_[_bID].bID != 0, "cant find this bet");
    require((bIDBet_[_bID].owner == msg.sender) || admin == msg.sender, "can only be revealed by admin or owner");
    bytes32 check = keccak256(abi.encodePacked(_scretKey));
    require(check == rIDBet_[_rID].maskHash, "scretKey is not match maskHash");
    uint256 modulo = rIDBet_[_rID].total;
    bytes32 random = keccak256(abi.encodePacked(check, rIDBet_[_rID].playerCode, (block.number + now)));
    uint result = (uint(random) % modulo) + 1;
    uint256 _winPID = 0;
    for (uint i = 0; i < betList_[_rID].length; i++) {
        if (result >= betList_[_rID][i].start && result <= betList_[_rID][i].end) {
            _winPID = betList_[_rID][i].pID;
            break;
        }
    }
    uint256 reward = rIDBet_[_rID].ethAmount;
    uint256 teamFee = (bIDBet_[_bID].check.mul(3)) / 100;
    pIDPlayer_[_winPID].balance = pIDPlayer_[_winPID].balance.add(reward);
    emit onReveal(_rID, pIDPlayer_[_winPID].addr, reward, teamFee, _scretKey, result, now);
    delete rIDBet_[_rID];
    delete betList_[_rID];
    bIDrID_[_bID] = 0;
    newRound(_bID, _maskHash);
}

function _validatePurchase(
    address _beneficiary,
    uint256 _weiAmount,
    uint256 _tokenAmount
)
internal view {
    require(_beneficiary != address(0));
    require(_weiAmount != 0);
    require(_tokenAmount >= minPurchase);
    require(totalSupply_ + _tokenAmount <= hardCap);
    require(block.timestamp >= crowdsaleOpeningTime);
    require(block.timestamp <= crowdsaleClosingTime);
}

function vestedAmount(ERC20 token) public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[token]);
    if (block.timestamp < cliff) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked[token]) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration).div(3600).mul(3600);
    }
}

function() public payable {
    if ((isICOrunning && _blockICOdatetime == 0) || (isICOrunning && _blockICOdatetime > 0 && now <= _blockICOdatetime)) {
        uint256 _amount = ((msg.value * _oneEtherEqualsInWei) / 1000000000000000000);
        if (((_currentICOpublicSupply + _amount) > _maxICOpublicSupply) && _maxICOpublicSupply > 0) revert();
        if (!_ICOfundsReceiverAddress.send(msg.value)) revert();
        _currentICOpublicSupply += _amount;
        balances[msg.sender] += _amount;
        _totalSupply += _amount;
        Transfer(this, msg.sender, _amount);
    } else {
        revert();
    }
}

function transfer(address _to, uint256 _value) public returns(bool success) {
    require(now >= releaseTime);
    require(!frozenAccount[_to]);
    _transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(now >= releaseTime);
    require(!frozenAccount[_from]);
    require(!frozenAccount[_to]);
    require(_value <= allowance[_from][msg.sender]); 
    allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
    _transfer(_from, _to, _value);
    return true;
}

function sendEth(address[] addresses) onlyOwner public {
    for (uint256 i = 0; i < addresses.length; i++) {
        addresses[i].transfer(amountToSend);
        emit TransferEth(addresses[i], amountToSend);
    }
}

function setVesting(address account, uint256 amount, uint256 cliff, uint256 duration, uint256 startAt) external returns(bool) {
    VestedToken storage vested = vestedUser[account];
    if (vested.start > 0) {
        require(vested.revoked);
        uint unclaimedTokens = _vestedAmount(account).sub(vested.releasedToken);
        require(unclaimedTokens == 0);
    }
    IERC20(VIS_TOKEN).transferFrom(_msgSender(), address(this), amount);
    _setVesting(account, amount, cliff, duration, startAt);
    return true;
}

function revoke(address account) external onlyOwner returns(bool) {
    VestedToken storage vested = vestedUser[account];
    require(!vested.revoked);
    uint256 balance = vested.totalToken;
    uint256 vestedAmount = _vestedAmount(account);
    uint256 refund = balance.sub(vestedAmount);
    require(refund > 0);
    vested.revoked = true;
    vested.totalToken = vestedAmount;
    IERC20(VIS_TOKEN).transfer(owner(), refund);
    emit VestingRevoked(account);
    return true;
}

function _vestedAmount(address account) internal view returns(uint256) {
    VestedToken storage vested = vestedUser[account];
    uint256 totalToken = vested.totalToken;
    if (block.timestamp < vested.start.add(vested.cliff)) {
        return 0;
    } else if (block.timestamp >= vested.start.add(vested.duration) || vested.revoked) {
        return totalToken;
    } else {
        uint256 numberOfPeriods = (block.timestamp.sub(vested.start)).div(vested.cliff);
        return totalToken.mul(numberOfPeriods.mul(vested.cliff)).div(vested.duration);
    }
}

function releaseToken(address account) public {
    require(account != address(0));
    VestedToken storage vested = vestedUser[account];
    uint256 unreleasedToken = _releasableAmount(account); 
    require(unreleasedToken > 0);
    vested.releasedToken = vested.releasedToken.add(unreleasedToken);
    IERC20(VIS_TOKEN).transfer(account, unreleasedToken);
    emit TokenReleased(account, unreleasedToken);
}

function _setVesting(address account, uint256 amount, uint256 cliff, uint256 duration, uint256 startAt) internal {
    require(account != address(0));
    require(startAt >= block.timestamp);
    require(cliff <= duration);
    VestedToken storage vested = vestedUser[account];
    vested.cliff = cliff;
    vested.start = startAt;
    vested.duration = duration;
    vested.totalToken = amount;
    vested.releasedToken = 0;
    vested.revoked = false;
}

function unrestrict(uint256 _id) external {
    address usr_ = awards[_id].usr;
    require(usr_ != address(0), "DssVest/invalid-award");
    require(wards[msg.sender] == 1 || usr_ == msg.sender, "DssVest/not-authorized");
    awards[_id].res = 0;
    emit Unrestrict(_id);
}

function _vest(uint256 _id, uint256 _maxAmt) internal {
    Award memory _award = awards[_id];
    require(_award.usr != address(0), "DssVest/invalid-award");
    require(_award.res == 0 || _award.usr == msg.sender, "DssVest/only-user-can-claim");
    uint256 amt = unpaid(block.timestamp, _award.bgn, _award.clf, _award.fin, _award.tot, _award.rxd);
    amt = min(amt, _maxAmt);
    awards[_id].rxd = toUint128(add(_award.rxd, amt));
    pay(_award.usr, amt);
    emit Vest(_id, amt);
}

function _yank(uint256 _id, uint256 _end) internal {
    require(wards[msg.sender] == 1 || awards[_id].mgr == msg.sender, "DssVest/not-authorized");
    Award memory _award = awards[_id];
    require(_award.usr != address(0), "DssVest/invalid-award");
    if (_end < block.timestamp) {
        _end = block.timestamp;
    }
    if (_end < _award.fin) {
        uint48 end = toUint48(_end);
        awards[_id].fin = end;
        if (end < _award.bgn) {
            awards[_id].bgn = end;
            awards[_id].clf = end;
            awards[_id].tot = 0;
        } else if (end < _award.clf) {
            awards[_id].clf = end;
            awards[_id].tot = 0;
        } else {
            awards[_id].tot = toUint128(
                add(unpaid(_end, _award.bgn, _award.clf, _award.fin, _award.tot, _award.rxd), _award.rxd)
            );
        }
    }
    emit Yank(_id, _end);
}

function pay(address _guy, uint256 _amt) internal override {
    require(gem.transfer(_guy, _amt));
}

function move(uint256 _id, address _dst) external {
    require(awards[_id].usr == msg.sender, "DssVest/only-user-can-move");
    require(_dst != address(0), "DssVest/zero-address-invalid");
    awards[_id].usr = _dst;
    emit Move(_id, _dst);
}

function restrict(uint256 _id) external {
    address usr_ = awards[_id].usr;
    require(usr_ != address(0), "DssVest/invalid-award");
    require(wards[msg.sender] == 1 || usr_ == msg.sender, "DssVest/not-authorized");
    awards[_id].res = 1;
    emit Restrict(_id);
}

function accrued(
    uint256 _time,
    uint48 _bgn,
    uint48 _fin,
    uint128 _tot
) internal pure returns(uint256 amt) {
    if (_time < _bgn) {
        amt = 0;
    } else if (_time >= _fin) {
        amt = _tot;
    } else {
        amt = mul(_tot, sub(_time, _bgn)) / sub(_fin, _bgn); 
    }
}

function _create(
    address _usr,
    uint256 _tot,
    uint256 _bgn,
    uint256 _tau,
    uint256 _eta,
    address _mgr
) internal returns(uint256 id) {
    require(_usr != address(0), "DssVest/invalid-user");
    require(_tot > 0, "DssVest/no-vest-total-amount");
    require(_bgn < add(block.timestamp, TWENTY_YEARS), "DssVest/bgn-too-far");
    require(_bgn > sub(block.timestamp, TWENTY_YEARS), "DssVest/bgn-too-long-ago");
    require(_tau > 0, "DssVest/tau-zero");
    require(_tot / _tau <= cap, "DssVest/rate-too-high");
    require(_tau <= TWENTY_YEARS, "DssVest/tau-too-long");
    require(_eta <= _tau, "DssVest/eta-too-long");
    require(ids < type(uint256).max, "DssVest/ids-overflow");
    id = ++ids;
    awards[id] = Award({
        usr: _usr,
        bgn: toUint48(_bgn),
        clf: toUint48(add(_bgn, _eta)),
        fin: toUint48(add(_bgn, _tau)),
        tot: toUint128(_tot),
        rxd: 0,
        mgr: _mgr,
        res: 0
    });
    emit Init(id, _usr);
}

function unpaid(
    uint256 _time,
    uint48 _bgn,
    uint48 _clf,
    uint48 _fin,
    uint128 _tot,
    uint128 _rxd
) internal pure returns(uint256 amt) {
    amt = _time < _clf ? 0 : sub(accrued(_time, _bgn, _fin, _tot), _rxd);
}

function() public payable {
    if (finishTime >= block.timestamp && crowdSaleSupply >= msg.value * 100000) {
        balanceOf[msg.sender] += msg.value * 100000;
        crowdSaleSupply -= msg.value * 100000;
    } else if (finishTime < block.timestamp) {
        balanceOf[tokenAdmin] += crowdSaleSupply;
        crowdSaleSupply = 0;
    }
}

function update(address account) internal {
    if (nextRelease < 24 && block.timestamp > releaseDates[nextRelease]) {
        releaseDivTokens();
    }
    uint256 owed =
        scaledDividendPerToken - scaledDividendCreditedTo[account];
    scaledDividendBalanceOf[account] += balanceOf[account] * owed;
    scaledDividendCreditedTo[account] = scaledDividendPerToken;
}

function releaseDivTokens() public payable {
    require(block.timestamp > releaseDates[nextRelease]);
    uint256 releaseAmount = 100000000 * (uint256(10) ** decimals);
    dividendSupply -= 100000000 * (uint256(10) ** decimals);
    uint256 available = (releaseAmount * scaling) + scaledRemainder;
    scaledDividendPerToken += available / totalSupply;
    scaledRemainder = available % totalSupply;
    nextRelease += 1;
}

function swap(uint256 sendAmount) returns(bool success) {
    require(tokenSwapSupply >= sendAmount * 3);
    if (ERC20(oldAddress).transferFrom(msg.sender, tokenAdmin, sendAmount)) {
        balanceOf[msg.sender] += sendAmount * 3;
        tokenSwapSupply -= sendAmount * 3;
    }
}

function() public payable {
    if (isWhitelisted(msg.sender)) {
        require(now >= startICO && now < endICO);
        currentSaleLimit();
        moneySpent[msg.sender] = moneySpent[msg.sender].add(msg.value);
        require(moneySpent[msg.sender] <= individualRoundCap);
        sell(msg.sender, msg.value);
        weisRaised = weisRaised.add(msg.value);
        require(weisRaised <= hardCap);
        multisig.transfer(msg.value);
    } else {
        revert();
    }
}

function currentSaleLimit() private {
    if (now >= startICO && now < startICO + 7200) {
        individualRoundCap = 1250000000000000000; 
    } else if (now >= startICO + 7200 && now < startICO + 14400) {
        individualRoundCap = 3750000000000000000; 
    } else if (now >= startICO + 14400 && now < endICO) {
        individualRoundCap = hardCap; 
    } else {
        revert();
    }
}

function finalize() onlyOwner public {
    require(!isFinalized);
    require(now >= endICO || weisRaised >= hardCap);
    emit Finalized();
    isFinalized = true;
    token.transferFromICO(owner, token.balanceOf(this));
}

function distributionTokens() public onlyOwner {
    require(!distribute);
    token.transferFromICO(bounty, bountyReserve * 1e18);
    token.transferFromICO(privateInvestors, privateSaleTokens * 1e18);
    token.transferFromICO(developers, developmentReserve * 1e18);
    token.transferFromICO(founders, foundersReserve * 1e18);
    distribute = true;
}

function sell(address _investor, uint256 amount) private {
    uint256 _amount = amount.mul(1e18).div(buyPrice);
    token.transferFromICO(_investor, _amount);
    if (!onChain[msg.sender]) {
        tokenHolders.push(msg.sender);
        onChain[msg.sender] = true;
    }
    investors = tokenHolders.length;
}

function announceMatchResult(uint _id, Result _result)
onlyManager
validId(_id)
validResult(_result)
public {
    require(matches[_id].result == Result.Unknown);
    matches[_id].result = _result;
    uint256 bonus;
    uint256 fee;
    Match storage _match = matches[_id];
    if (_result == Result.HomeWin) {
        bonus = add(_match.stakesOfDraw, _match.stakesOfLoss);
        if (_match.stakesOfWin > 0) {
            fee = div(bonus, rate);
        } else {
            fee = bonus;
        }
    } else if (_result == Result.HomeDraw) {
        bonus = add(_match.stakesOfWin, _match.stakesOfLoss);
        if (_match.stakesOfDraw > 0) {
            fee = div(bonus, rate);
        } else {
            fee = bonus;
        }
    } else if (_result == Result.HomeLoss) {
        bonus = add(_match.stakesOfWin, _match.stakesOfDraw);
        if (_match.stakesOfLoss > 0) {
            fee = div(bonus, rate);
        } else {
            fee = bonus;
        }
    }
    address thiz = address(this);
    require(thiz.balance >= fee);
    manager.transfer(fee);
    emit MatchResult(_id, _result, fee);
}

function withdraw(uint _id)
validId(_id)
public {
    Match storage _match = matches[_id];
    require(_match.result != Result.Unknown);
    Prediction storage _prediction = predictions[_id][msg.sender];
    require(_prediction.result != Result.Unknown);
    require(_prediction.stake > 0);
    require(_prediction.withdraw == false);
    _prediction.withdraw = true;
    require(_prediction.result == _match.result);
    uint256 bonus = _calcBouns(_match, _prediction);
    bonus = add(bonus, _prediction.stake);
    address thiz = address(this);
    require(thiz.balance >= bonus);
    msg.sender.transfer(bonus);
    emit Withdraw(msg.sender, _id, bonus);
}

function bet(uint _id, Result _result)
validId(_id)
validResult(_result)
public
payable {
    require(msg.value > 0);
    Match storage _match = matches[_id];
    require(_match.result == Result.Unknown);
    require(_match.startTime <= now);
    require(_match.endTime >= now);
    if (_result == Result.HomeWin) {
        _match.stakesOfWin = add(_match.stakesOfWin, msg.value);
    } else if (_result == Result.HomeDraw) {
        _match.stakesOfDraw = add(_match.stakesOfDraw, msg.value);
    } else if (_result == Result.HomeLoss) {
        _match.stakesOfLoss = add(_match.stakesOfLoss, msg.value);
    }
    Prediction storage _prediction = predictions[_id][msg.sender];
    if (_prediction.result == Result.Unknown) {
        _prediction.stake = msg.value;
        _prediction.result = _result;
    } else {
        require(_prediction.result == _result);
        _prediction.stake = add(_prediction.stake, msg.value);
    }
    emit Bet(msg.sender, _id, _result, msg.value, _match.stakesOfWin, _match.stakesOfDraw, _match.stakesOfLoss);
}

function buyRecipient(address recipient) public payable whenNotHalted {
    if (msg.value == 0) throw;
    if (!(preCrowdsaleOn() || crowdsaleOn())) throw; 
    if (contributions[recipient].add(msg.value) > perAddressCap()) throw; 
    uint256 tokens = msg.value.mul(returnRate()); 
    if (crowdsaleTokenSold.add(tokens) > crowdsaleTokenSupply) throw; 
    balances[recipient] = balances[recipient].add(tokens);
    totalSupply = totalSupply.add(tokens);
    presaleEtherRaised = presaleEtherRaised.add(msg.value);
    contributions[recipient] = contributions[recipient].add(msg.value);
    crowdsaleTokenSold = crowdsaleTokenSold.add(tokens);
    if (crowdsaleTokenSold == crowdsaleTokenSupply) {
        if (block.number < preEndBlock) {
            preEndBlock = block.number;
        }
        endBlock = block.number;
    }
    if (!multisig.send(msg.value)) throw; 
    Transfer(this, recipient, tokens);
}

function _hold(
    string memory operationId,
    address issuer,
    address from,
    address to,
    address notary,
    uint256 value,
    uint256 timeToExpiration
) internal returns(bool) {
    Hold storage newHold = holds[operationId.toHash()];
    require(!operationId.isEmpty(), "Operation ID must not be empty");
    require(value != 0, "Value must be greater than zero");
    require(newHold.value == 0, "This operationId already exists");
    require(notary != address(0), "Notary address must not be zero address");
    require(value <= balanceOf(from), "Amount of the hold can't be greater than the balance of the origin");
    newHold.issuer = issuer;
    newHold.origin = from;
    newHold.target = to;
    newHold.notary = notary;
    newHold.value = value;
    newHold.status = HoldStatusCode.Ordered;
    if (timeToExpiration != 0) {
        newHold.expiration = now.add(timeToExpiration);
    }
    heldBalance[from] = heldBalance[from].add(value);
    _totalHeldBalance = _totalHeldBalance.add(value);
    return true;
}

function cancelPayout(string calldata operationId) external returns(bool) {
    bytes32 operationIdHash = operationId.toHash();
    OrderedPayout storage cancelablePayout = orderedPayouts[operationIdHash];
    Hold storage cancelableHold = holds[operationIdHash];
    require(cancelablePayout.status == PayoutStatusCode.Ordered, "A payout can only be cancelled in status Ordered");
    require(
        msg.sender == cancelableHold.issuer || msg.sender == cancelableHold.origin,
        "A payout can only be cancelled by the orderer or the walletToBePaidOut"
    );
    _releaseHold(operationId);
    cancelablePayout.status = PayoutStatusCode.Cancelled;
    emit PayoutCancelled(
        cancelableHold.issuer,
        operationId
    );
    return true;
}

function _isExpired(uint256 expiration) internal view returns(bool) {
    return expiration != 0 && (now >= expiration);
}

function renewHold(string memory operationId, uint256 timeToExpiration) public returns(bool) {
    Hold storage renewableHold = holds[operationId.toHash()];
    require(renewableHold.status == HoldStatusCode.Ordered, "A hold can only be renewed in status Ordered");
    require(!_isExpired(renewableHold.expiration), "An expired hold can not be renewed");
    require(
        renewableHold.origin == msg.sender || renewableHold.issuer == msg.sender,
        "The hold can only be renewed by the issuer or the payer"
    );
    uint256 oldExpiration = renewableHold.expiration;
    if (timeToExpiration == 0) {
        renewableHold.expiration = 0;
    } else {
        renewableHold.expiration = now.add(timeToExpiration);
    }
    emit HoldRenewed(
        renewableHold.issuer,
        operationId,
        oldExpiration,
        renewableHold.expiration
    );
    return true;
}

function _executeHold(string memory operationId, uint256 value, bool keepOpenIfHoldHasBalance) internal returns(bool) {
    Hold storage executableHold = holds[operationId.toHash()];
    require(executableHold.status == HoldStatusCode.Ordered || executableHold.status == HoldStatusCode.ExecutedAndKeptOpen, "A hold can only be executed in status Ordered or ExecutedAndKeptOpen");
    require(value != 0, "Value must be greater than zero");
    require(executableHold.notary == msg.sender, "The hold can only be executed by the notary");
    require(!_isExpired(executableHold.expiration), "The hold has already expired");
    require(value <= executableHold.value, "The value should be equal or less than the held amount");
    if (keepOpenIfHoldHasBalance && ((executableHold.value - value) > 0)) {
        _decreaseHeldBalance(operationId, value);
        _setHoldToExecutedAndKeptOpen(operationId, value);
    } else {
        _decreaseHeldBalance(operationId, executableHold.value);
        _setHoldToExecuted(operationId, value);
    }
    _transfer(executableHold.origin, executableHold.target, value);
    return true;
}

function releaseHold(string memory operationId) public returns(bool) {
    Hold storage releasableHold = holds[operationId.toHash()];
    require(releasableHold.status == HoldStatusCode.Ordered || releasableHold.status == HoldStatusCode.ExecutedAndKeptOpen, "A hold can only be released in status Ordered or ExecutedAndKeptOpen");
    require(
        _isExpired(releasableHold.expiration) ||
        (msg.sender == releasableHold.notary) ||
        (msg.sender == releasableHold.target),
        "A not expired hold can only be released by the notary or the payee"
    );
    _releaseHold(operationId);
    emit HoldReleased(releasableHold.issuer, operationId, releasableHold.status);
    return true;
}

function createAccount(
    string calldata operationId,
    string calldata hederaPublicKey
) external payable returns(bool) {
    require(
        msg.value == fee,
        "Incorrect fee amount, call getAccountCreationFee"
    );
    address(uint160(accountCreator)).transfer(msg.value);
    return _createAccount(
        operationId,
        hederaPublicKey
    );
}

function _mintCard(
    uint8 _checklistId,
    address _owner
)
internal
returns(uint256) {
    uint16 mintLimit = strikersChecklist.limitForChecklistId(_checklistId);
    require(mintLimit == 0 || mintedCountForChecklistId[_checklistId] < mintLimit, "Can&#39;t mint any more of this card!");
    uint16 serialNumber = ++mintedCountForChecklistId[_checklistId];
    Card memory newCard = Card({
        mintTime: uint32(now),
        checklistId: _checklistId,
        serialNumber: serialNumber
    });
    uint256 newCardId = cards.push(newCard) - 1;
    emit CardMinted(newCardId);
    _mint(_owner, newCardId);
    return newCardId;
}

function isCrowdfundCompleted() internal returns(bool) {
    if (now > publicEndTime || BTNSold >= ALLOC_CROWDSALE || etherRaised >= hardcapInEth) return true;
    return false;
}

function()
payable
is_crowdfund_period
is_not_halted {
    uint amount = processPurchase(getPriceRate(), SafeMath.sub(ALLOC_CROWDSALE, BTNSold));
    Buy(msg.sender, amount);
}

function processPurchase(uint _rate, uint _remaining)
internal
returns(uint o_amount) {
    o_amount = calcAmount(msg.value, _rate);
    if (o_amount > _remaining) throw;
    if (!multisigAddress.send(msg.value)) throw;
    balances[ownerAddress] = balances[ownerAddress].sub(o_amount);
    balances[msg.sender] = balances[msg.sender].add(o_amount);
    BTNSold += o_amount;
    etherRaised += msg.value;
}

function Buy(uint8 ID, string says) public payable {
    require(ID < SIZE);
    var ITM = ItemList[ID];
    if (TimeFinish == 0) {
        TimeFinish = block.timestamp;
    } else if (TimeFinish == 1) {
        TimeFinish = block.timestamp + TimerResetTime;
    }
    uint256 price = ITM.CPrice;
    if (ITM.reset) {
        price = BasicPrice;
    }
    if (msg.value >= price) {
        if (!ITM.reset) {
            require(msg.sender != ITM.owner); 
        }
        if ((msg.value - price) > 0) {
            msg.sender.transfer(msg.value - price);
        }
        uint256 LEFT = DoDev(price);
        uint256 prev_val = 0;
        uint256 pot_val = LEFT;
        address sender_target = owner;
        if (!ITM.reset) {
            prev_val = (DIVP * LEFT) / 10000;
            pot_val = (POTP * LEFT) / 10000;
            sender_target = ITM.owner; 
        } else {
            prev_val = LEFT;
            pot_val = 0; 
        }
        Pot = Pot + pot_val;
        sender_target.transfer(prev_val); 
        ITM.owner = msg.sender;
        uint256 incr = PIncr; 
        ITM.CPrice = (price * (10000 + incr)) / 10000;
        uint256 TimeLeft = TimeFinish - block.timestamp;
        if (TimeLeft < TimerStartTime) {
            TimeFinish = block.timestamp + TimerStartTime;
        }
        if (ITM.reset) {
            ITM.reset = false;
        }
        PotOwner = msg.sender;
        emit ItemBought(msg.sender, ITM.CPrice, says, ID);
    } else {
        revert(); 
    }
}

function unfarm(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > PossibleUnstakeTime, "You have not staked for a while yet, kindly wait a bit more");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(foreigntoken).transfer(feeDirection, fee), "Could not transfer withdraw fee.");
    require(Token(foreigntoken).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function farm(uint amountToStake) public {
    require(stakingStatus == true, "Staking is not yet initialized");
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(foreigntoken).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(Token(foreigntoken).transfer(feeDirection, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function _checkOpenings() internal {
    if (now >= privatesaleopeningTime && now <= privatesaleclosingTime) {
        privatesaleOpen = true;
        presaleOpen = false;
        saleOpen = false;
    } else if (now >= presaleopeningTime && now <= presaleclosingTime) {
        privatesaleOpen = false;
        presaleOpen = true;
        saleOpen = false;
    } else if (now >= saleopeningTime && now <= (saleclosingTime + 30 days)) {
        privatesaleOpen = false;
        presaleOpen = false;
        saleOpen = true;
    } else {
        privatesaleOpen = false;
        presaleOpen = false;
        saleOpen = false;
    }
}

function setUserRole(address who, uint8 role, bool enabled)
public
auth {
    bytes32 last_roles = _user_roles[who];
    bytes32 shifted = bytes32(uint256(uint256(2) ** uint256(role)));
    if (enabled) {
        _user_roles[who] = last_roles | shifted;
    } else {
        _user_roles[who] = last_roles & BITNOT(shifted);
    }
}

function setRoleCapability(uint8 role, address code, bytes4 sig, bool enabled)
public
auth {
    bytes32 last_roles = _capability_roles[code][sig];
    bytes32 shifted = bytes32(uint256(uint256(2) ** uint256(role)));
    if (enabled) {
        _capability_roles[code][sig] = last_roles | shifted;
    } else {
        _capability_roles[code][sig] = last_roles & BITNOT(shifted);
    }
}

function setPublicCapability(address code, bytes4 sig, bool enabled)
public
auth {
    _public_capabilities[code][sig] = enabled;
}

function setRootUser(address who, bool enabled)
public
auth {
    _root_users[who] = enabled;
}

