function withdrawERC20(address _token, uint256 _amount)
external
nonReentrant() {
    UserInfo storage user = userInfo[msg.sender][_token];
    require(user.staked >= _amount, "not enough amount to withdraw");
    if (_token != PKF) {
        ExternalToken storage token = externalToken[_token];
        userExternalStaked[msg.sender] = userExternalStaked[msg.sender].sub(
            _amount.mul(token.rate).div(10 ** token.decimals)
        );
    }
    uint256 toPunish = calculateWithdrawFee(msg.sender, _token, _amount);
    if (toPunish > 0) {
        IERC20(_token).transfer(penaltyWallet, toPunish);
    }
    user.staked = user.staked.sub(_amount);
    IERC20(_token).transfer(msg.sender, _amount.sub(toPunish));
    emit WithdrawnERC20(
        msg.sender,
        _token,
        _amount,
        toPunish,
        user.stakedTime
    );
}

function joinHigh(uint32 playerId) internal {
    uint8 segIndex = _high;
    leaveSwap(playerId);
    if (hasCountSegmentSlot(segIndex)) {
        joinSwap(playerId, segIndex);
    } else {
        uint32 leftPlayerId = doLeave(playerId, segIndex);
        joinMid(leftPlayerId);
        joinSwap(playerId, segIndex);
    }
}

function joinMid(uint32 playerId) internal {
    uint8 segIndex = _mid;
    leaveSwap(playerId);
    if (hasCountSegmentSlot(segIndex)) {
        joinSwap(playerId, segIndex);
    } else {
        uint32 leftPlayerId = doLeave(playerId, segIndex);
        joinLow(leftPlayerId);
        joinSwap(playerId, segIndex);
    }
    _degoSegment[segIndex].max = _degoSegment[segIndex + 1].min;
}

function joinLow(uint32 playerId) internal {
    uint8 segIndex = _low;
    leaveSwap(playerId);
    joinSwap(playerId, segIndex);
    _degoSegment[segIndex].max = _degoSegment[segIndex + 1].min;
    if (_countSegment[segIndex].curCount > _countSegment[segIndex].length) {
        _countSegment[segIndex].length = _countSegment[segIndex].curCount;
    }
}

function approveWithdrawal(
    address destination,
    uint256 amount,
    bytes32 txHash,
    bytes32 blockHash,
    uint256 blockNumber
)
external
onlyVerifier {
    require(amount > fees, "Withdrawal amount is less than or equal to fees");
    require(destination != address(0), "Invalid destination address");
    bytes32 hash = keccak256(abi.encodePacked(txHash, blockHash, blockNumber));
    uint256 net = amount.sub(fees);
    if (withdrawals[hash].destination == address(0)) {
        withdrawals[hash] = Withdrawal(destination, net, false);
    }
    Withdrawal storage w = withdrawals[hash];
    address[] storage approvals = withdrawalApprovals[hash];
    require(w.destination == destination, "Destination mismatch");
    require(w.amount == net, "Amount mismatch");
    for (uint256 i = 0; i < approvals.length; i++) {
        require(approvals[i] != msg.sender, "Already approved withdrawal");
    }
    approvals.push(msg.sender);
    if (approvals.length >= requiredVerifiers && !w.processed) {
        if (fees != 0 && feeWallet != address(0)) {
            token.safeTransfer(feeWallet, fees);
        }
        token.safeTransfer(destination, net);
        w.processed = true;
        emit WithdrawalProcessed(destination, net, txHash, blockHash, blockNumber);
    }
}

function updateReward(address _addr) private {
    Player storage p = players[_addr];
    if (
        games[p.currentRound].ended == true &&
        p.lastRound < p.currentRound
    ) {
        p.reward = SafeMath.add(p.reward, calculateReward(_addr, p.currentRound));
        p.lastRound = p.currentRound;
    }
}

