        ChangePixel(_id);
        return true;
    } else {
        require(msg.value >= Image[_id].price);
        address prevOwner = Image[_id].pixelOwner;
        balance[Image[_id].pixelOwner].indexList[_id] = 0;
        balance[Image[_id].pixelOwner].pixelListlength--;
