function() payable public {
    require(now < ExerciseEndTime);
    require(topTotalSupply > totalSupply);
    bool firstCallReward = false;
    uint epochNow = whichEpoch(block.number);
    if (epochNow != epochLast) {
        lastEpochBlock = safeAdd(lastEpochBlock, ((block.number - lastEpochBlock) / initBlockEpoch + 1) * initBlockEpoch);
        doReward();
        eachPUSTprice = calcpustprice(epochNow, epochLast);
        epochLast = epochNow;
        firstCallReward = true;
        lastEpochTX = 0;
    }
    uint _value = msg.value;
    uint _PUST = _value / eachPUSTprice;
    require(_PUST > 0);
    if (safeAdd(totalSupply, _PUST) > topTotalSupply) {
        _PUST = safeSub(topTotalSupply, totalSupply);
    }
    uint _refound = _value - _PUST * eachPUSTprice;
    if (_refound > 0) {
        msg.sender.transfer(_refound);
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], _PUST);
    totalSupply = safeAdd(totalSupply, _PUST);
    emit buyPUST(msg.sender, _PUST);
    if (lastCallAddress == address(0) && epochLast == 0) {
        firstCallReward = true;
    }
    if (firstCallReward) {
        uint _firstReward = 0;
        _firstReward = (_PUST - 1) * 2 / 10 + 1;
        if (safeAdd(totalSupply, _firstReward) > topTotalSupply) {
            _firstReward = safeSub(topTotalSupply, totalSupply);
        }
        balances[msg.sender] = safeAdd(balances[msg.sender], _firstReward);
        totalSupply = safeAdd(totalSupply, _firstReward);
    }
    lastEpochTX += 1;
    lastCallAddress = msg.sender;
    lastCallPUST = _PUST;
    lastEpochBlock = safeAdd(lastEpochBlock, eachUserWeight);
}

function trade(TradeInput tradeInput) internal returns(uint) {
    require(isEnabled);
    require(tx.gasprice <= maxGasPriceValue);
    require(validateTradeInput(tradeInput.src, tradeInput.srcAmount, tradeInput.dest, tradeInput.destAddress));
    BestRateResult memory rateResult =
        findBestRateTokenToToken(tradeInput.src, tradeInput.dest, tradeInput.srcAmount);
    require(rateResult.rate > 0);
    require(rateResult.rate < MAX_RATE);
    require(rateResult.rate >= tradeInput.minConversionRate);
    uint actualDestAmount;
    uint weiAmount;
    uint actualSrcAmount;
    (actualSrcAmount, weiAmount, actualDestAmount) = calcActualAmounts(tradeInput.src,
        tradeInput.dest,
        tradeInput.srcAmount,
        tradeInput.maxDestAmount,
        rateResult);
    if (actualSrcAmount < tradeInput.srcAmount) {
        if (tradeInput.src == ETH_TOKEN_ADDRESS) {
            tradeInput.trader.transfer(tradeInput.srcAmount - actualSrcAmount);
        } else {
            tradeInput.src.transfer(tradeInput.trader, (tradeInput.srcAmount - actualSrcAmount));
        }
    }
    require(weiAmount <= getUserCapInWei(tradeInput.trader));
    require(doReserveTrade(
        tradeInput.src,
        actualSrcAmount,
        ETH_TOKEN_ADDRESS,
        this,
        weiAmount,
        KyberReserveInterface(rateResult.reserve1),
        rateResult.rateSrcToEth,
        true));
    require(doReserveTrade(
        ETH_TOKEN_ADDRESS,
        weiAmount,
        tradeInput.dest,
        tradeInput.destAddress,
        actualDestAmount,
        KyberReserveInterface(rateResult.reserve2),
        rateResult.rateEthToDest,
        true));
    if (tradeInput.src != ETH_TOKEN_ADDRESS)
        require(feeBurnerContract.handleFees(weiAmount, rateResult.reserve1, tradeInput.walletId));
    if (tradeInput.dest != ETH_TOKEN_ADDRESS)
        require(feeBurnerContract.handleFees(weiAmount, rateResult.reserve2, tradeInput.walletId));
    KyberTrade(tradeInput.trader, tradeInput.src, actualSrcAmount, tradeInput.destAddress, tradeInput.dest,
        actualDestAmount);
    return actualDestAmount;
}

function listPairForReserve(address reserve, ERC20 token, bool ethToToken, bool tokenToEth, bool add)
public onlyAdmin {
    require(isReserve[reserve]);
    if (ethToToken) {
        listPairs(reserve, token, false, add);
        ListReservePairs(reserve, ETH_TOKEN_ADDRESS, token, add);
    }
    if (tokenToEth) {
        listPairs(reserve, token, true, add);
        if (add) {
            token.approve(reserve, 2 ** 255); 
        } else {
            token.approve(reserve, 0);
        }
        ListReservePairs(reserve, token, ETH_TOKEN_ADDRESS, add);
    }
    setDecimals(token);
}

function multiValueAirdrop(address _addressOfToken, address[] _recipients, uint256[] _values) public returns(bool) {
    ERCInterface token = ERCInterface(_addressOfToken);
    require(
        _recipients.length <= maxDropsPerTx &&
        _recipients.length == _values.length &&
        (
            getTotalDropsOf(msg.sender) >= _recipients.length ||
            tokenHasFreeTrial(_addressOfToken)
        ) &&
        !tokenIsBanned[_addressOfToken]
    );
    for (uint i = 0; i < _recipients.length; i++) {
        if (_recipients[i] != address(0) && _values[i] > 0) {
            token.transferFrom(msg.sender, _recipients[i], _values[i]);
        }
    }
    if (tokenHasFreeTrial(_addressOfToken)) {
        trialDrops[_addressOfToken] = trialDrops[_addressOfToken].add(_recipients.length);
    } else {
        updateMsgSenderBonusDrops(_recipients.length);
    }
    AirdropInvoked(msg.sender, _recipients.length);
    return true;
}

function singleValueAirdrop(address _addressOfToken, address[] _recipients, uint256 _value) public returns(bool) {
    ERCInterface token = ERCInterface(_addressOfToken);
    require(
        _recipients.length <= maxDropsPerTx &&
        (
            getTotalDropsOf(msg.sender) >= _recipients.length ||
            tokenHasFreeTrial(_addressOfToken)
        ) &&
        !tokenIsBanned[_addressOfToken]
    );
    for (uint i = 0; i < _recipients.length; i++) {
        if (_recipients[i] != address(0)) {
            token.transferFrom(msg.sender, _recipients[i], _value);
        }
    }
    if (tokenHasFreeTrial(_addressOfToken)) {
        trialDrops[_addressOfToken] = trialDrops[_addressOfToken].add(_recipients.length);
    } else {
        updateMsgSenderBonusDrops(_recipients.length);
    }
    AirdropInvoked(msg.sender, _recipients.length);
    return true;
}

function withdrawEth(uint256 _eth) public returns(bool) {
    require(
        ethBalanceOf[msg.sender] >= _eth &&
        _eth > 0
    );
    uint256 toTransfer = _eth;
    ethBalanceOf[msg.sender] = ethBalanceOf[msg.sender].sub(_eth);
    msg.sender.transfer(toTransfer);
    EthWithdrawn(msg.sender, toTransfer);
}

function updateMsgSenderBonusDrops(uint256 _drops) internal {
    if (_drops <= getDropsOf(msg.sender)) {
        bonusDropsOf[msg.sender] = bonusDropsOf[msg.sender].add(_drops.mul(bonus).div(100));
        ethBalanceOf[msg.sender] = ethBalanceOf[msg.sender].sub(_drops.mul(dropUnitPrice));
        owner.transfer(_drops.mul(dropUnitPrice));
    } else {
        uint256 remainder = _drops.sub(getDropsOf(msg.sender));
        if (ethBalanceOf[msg.sender] > 0) {
            bonusDropsOf[msg.sender] = bonusDropsOf[msg.sender].add(getDropsOf(msg.sender).mul(bonus).div(100));
            owner.transfer(ethBalanceOf[msg.sender]);
            ethBalanceOf[msg.sender] = 0;
        }
        bonusDropsOf[msg.sender] = bonusDropsOf[msg.sender].sub(remainder);
    }
}

function issueRefunds(address[] _addrs) public onlyOwner returns(bool) {
    require(_addrs.length <= maxDropsPerTx);
    for (uint i = 0; i < _addrs.length; i++) {
        if (_addrs[i] != address(0) && ethBalanceOf[_addrs[i]] > 0) {
            uint256 toRefund = ethBalanceOf[_addrs[i]];
            ethBalanceOf[_addrs[i]] = 0;
            _addrs[i].transfer(toRefund);
            RefundIssued(_addrs[i], toRefund);
        }
    }
}

function takeBet(uint makerBetId, address maker, uint odds, uint takerBetId) external payable {
    require(msg.sender != maker);
    require(msg.value > 0);
    MakerBet storage makerBet = makerBets[makerBetId][maker];
    require(makerBet.makerBetId != 0);
    require(msg.sender != makerBet.trustedVerifier.addr);
    require(now < makerBet.expiry);
    require(makerBet.status == BetStatus.Open);
    require(makerBet.odds == odds);
    require(makerBet.takerBetsCount < maxAllowedTakerBetsPerMakerBet);
    uint minAllowedStake = mul(mul(makerBet.totalFund, (10 ** oddsDecimals)), minAllowedStakeInPercentage) / sub(odds, (10 ** oddsDecimals)) / 100;
    uint maxAvailableStake = mul(sub(makerBet.totalFund, makerBet.reservedFund), (10 ** oddsDecimals)) / sub(odds, (10 ** oddsDecimals));
    if (maxAvailableStake >= minAllowedStake) {
        require(msg.value >= minAllowedStake);
    } else {
        require(msg.value >= sub(maxAvailableStake, (maxAvailableStake / 10)) && msg.value <= maxAvailableStake);
    }
    require(msg.value <= maxAvailableStake);
    makerBet.takerBets.length++;
    makerBet.takerBets[makerBet.takerBetsCount] = TakerBet(takerBetId, msg.sender, odds, msg.value, false);
    makerBet.reservedFund = add(makerBet.reservedFund, mul(msg.value, sub(odds, (10 ** oddsDecimals))) / (10 ** oddsDecimals));
    makerBet.totalStake = add(makerBet.totalStake, msg.value);
    makerBet.takerBetsCount++;
    emit LogTakeBet(makerBetId, maker, takerBetId, msg.sender);
}

function updateOdds(uint makerBetId, uint odds) external {
    require(odds > (10 ** oddsDecimals) && odds < ((10 ** 8) * (10 ** oddsDecimals)));
    MakerBet storage makerBet = makerBets[makerBetId][msg.sender];
    require(makerBet.makerBetId != 0);
    require(now < makerBet.expiry);
    require(makerBet.status == BetStatus.Open || makerBet.status == BetStatus.Paused);
    require(msg.sender == makerBet.maker);
    require(odds != makerBet.odds);
    uint oldOdds = makerBet.odds;
    makerBet.odds = odds;
    emit LogUpdateOdds(makerBetId, msg.sender, oldOdds, makerBet.odds);
}

function addFund(uint makerBetId) external payable {
    MakerBet storage makerBet = makerBets[makerBetId][msg.sender];
    require(makerBet.makerBetId != 0);
    require(now < makerBet.expiry);
    require(makerBet.status == BetStatus.Open || makerBet.status == BetStatus.Paused);
    require(msg.sender == makerBet.maker);
    require(msg.value > 0);
    uint oldTotalFund = makerBet.totalFund;
    makerBet.totalFund = add(makerBet.totalFund, msg.value);
    emit LogAddFund(makerBetId, msg.sender, oldTotalFund, makerBet.totalFund);
}

function makeBet(uint makerBetId, uint odds, address trustedVerifier, uint trustedVerifierFeeRate, uint expiry) external payable {
    uint fund = sub(msg.value, baseVerifierFee);
    require(fund >= minMakerBetFund);
    require(odds > (10 ** oddsDecimals) && odds < ((10 ** 8) * (10 ** oddsDecimals)));
    require(expiry > now);
    MakerBet storage makerBet = makerBets[makerBetId][msg.sender];
    require(makerBet.makerBetId == 0);
    Verifier memory verifier = verifiers[trustedVerifier];
    require(verifier.addr != address(0x0));
    require(trustedVerifierFeeRate == verifier.feeRate);
    makerBet.makerBetId = makerBetId;
    makerBet.maker = msg.sender;
    makerBet.odds = odds;
    makerBet.totalFund = fund;
    makerBet.trustedVerifier = Verifier(verifier.addr, verifier.feeRate);
    makerBet.expiry = expiry;
    makerBet.status = BetStatus.Open;
    makerBet.reservedFund = 0;
    makerBet.takerBetsCount = 0;
    makerBet.totalStake = 0;
    makerBetsCount++;
    emit LogMakeBet(makerBetId, msg.sender);
}

function withdraw(uint makerBetId, address maker) external {
    MakerBet storage makerBet = makerBets[makerBetId][maker];
    require(makerBet.makerBetId != 0);
    require(makerBet.outcome != BetOutcome.NotSettled);
    require(makerBet.status == BetStatus.Settled);
    bool fullyWithdrawn = false;
    if (msg.sender == maker) {
        fullyWithdrawn = payMaker(makerBet);
    } else if (msg.sender == makerBet.trustedVerifier.addr) {
        fullyWithdrawn = payVerifier(makerBet);
    } else {
        fullyWithdrawn = payTaker(makerBet, msg.sender);
    }
    if (fullyWithdrawn) {
        emit LogWithdraw(makerBetId, maker, msg.sender);
    }
}

function closeBet(uint makerBetId) external {
    MakerBet storage makerBet = makerBets[makerBetId][msg.sender];
    require(makerBet.makerBetId != 0);
    require(makerBet.status == BetStatus.Open || makerBet.status == BetStatus.Paused);
    require(msg.sender == makerBet.maker);
    makerBet.status = BetStatus.Closed;
    uint unusedFund = sub(makerBet.totalFund, makerBet.reservedFund);
    if (unusedFund > 0) {
        makerBet.totalFund = makerBet.reservedFund;
        uint refundAmount = unusedFund;
        if (makerBet.totalStake == 0) {
            refundAmount = add(refundAmount, baseVerifierFee); 
            makerBet.makerFundWithdrawn = true;
        }
        if (!makerBet.maker.send(refundAmount)) {
            makerBet.totalFund = add(makerBet.totalFund, unusedFund);
            makerBet.status = BetStatus.Paused;
            makerBet.makerFundWithdrawn = false;
        } else {
            emit LogCloseBet(makerBetId, msg.sender);
        }
    } else {
        emit LogCloseBet(makerBetId, msg.sender);
    }
}

function settleBet(uint makerBetId, address maker, uint outcome) external {
    require(outcome == 1 || outcome == 2 || outcome == 3 || outcome == 4);
    MakerBet storage makerBet = makerBets[makerBetId][maker];
    require(makerBet.makerBetId != 0);
    require(msg.sender == makerBet.trustedVerifier.addr);
    require(makerBet.totalStake > 0);
    require(makerBet.status != BetStatus.Settled);
    BetOutcome betOutcome = BetOutcome(outcome);
    makerBet.outcome = betOutcome;
    makerBet.status = BetStatus.Settled;
    payMaker(makerBet);
    payVerifier(makerBet);
    emit LogSettleBet(makerBetId, maker);
}

function refundPreSale() public {
    require(soldTokensPreSale < softcapPreSale && now > endPreSale);
    uint256 rate = investedEther[msg.sender];
    require(investedEther[msg.sender] >= 0);
    investedEther[msg.sender] = 0;
    msg.sender.transfer(rate);
    weisRaised = weisRaised.sub(rate);
    emit Refund(rate, msg.sender);
}

function preSale(address _investor, uint256 _value) internal {
    uint256 tokens = _value.mul(1e18).div(buyPrice);
    uint256 tokensByDate = tokens.mul(bonusDate()).div(100);
    tokens = tokens.add(tokensByDate);
    token.mintFromICO(_investor, tokens);
    soldTokensPreSale = soldTokensPreSale.add(tokens); 
    uint256 tokensTeam = tokens.mul(10).div(44); 
    token.mintFromICO(team, tokensTeam);
    uint256 tokensBoynty = tokens.mul(3).div(200); 
    token.mintFromICO(bounty, tokensBoynty);
    weisRaised = weisRaised.add(_value);
}

function mintManual(address receiver, uint256 _tokens) public backEnd {
    token.mintFromICO(receiver, _tokens);
    soldTokensPreSale = soldTokensPreSale.add(_tokens);
    uint256 tokensTeam = _tokens.mul(10).div(44); 
    token.mintFromICO(team, tokensTeam);
    uint256 tokensBoynty = _tokens.mul(3).div(200); 
    token.mintFromICO(bounty, tokensBoynty);
}

function() public payable {
    require(authorize.isWhitelisted(msg.sender));
    require(isPreSale());
    preSale(msg.sender, msg.value);
    require(soldTokensPreSale <= hardCapPreSale);
    investedEther[msg.sender] = investedEther[msg.sender].add(msg.value);
}

function bonusDate() private view returns(uint256) {
    if (now > startPreSale && now < stage1Sale) { 
        return 50;
    } else if (now > stage1Sale && now < stage2Sale) { 
        return 40;
    } else if (now > stage2Sale && now < stage3Sale) { 
        return 33;
    } else if (now > stage3Sale && now < stage4Sale) { 
        return 30;
    } else if (now > stage4Sale && now < stage5Sale) { 
        return 25;
    } else {
        return 0;
    }
}

function isPreSale() public constant returns(bool) {
    return now >= startPreSale && now <= endPreSale;
}

function RedeemMTU(bool redeem) paused public {
    uint256 AppliedUnits = Redeemer[msg.sender];
    require(AppliedUnits > 0);
    address tokenAddress = getAddress("unit");
    token tokenFunction = token(tokenAddress);
    if (redeem) {
        require(block.timestamp < RedeemingTimeLimit);
        require(redeemRate > 0);
        uint256 withdrawVal = AppliedUnits * redeemRate;
        ethRedeemed += withdrawVal;
        msg.sender.transfer(withdrawVal);
        emit eRedeem(msg.sender, AppliedUnits, withdrawVal);
    } else {
        tokenFunction.transfer(msg.sender, AppliedUnits);
    }
    Redeemer[msg.sender] = 0;
    unRedeemedMTU -= AppliedUnits;
}

function ClaimMTU(bool claim) paused public {
    uint256 ethVal = Investors[msg.sender];
    require(ethVal >= claimRate);
    if (claim) {
        require(claimRate > 0);
        require(block.timestamp < ClaimingTimeLimit);
        ethRaised += ethVal;
        uint256 claimTokens = ethVal / claimRate;
        address tokenAddress = getAddress("unit");
        token tokenTransfer = token(tokenAddress);
        tokenTransfer.transfer(msg.sender, claimTokens);
        if (isCharged) {
            getAddress("team").transfer(ethVal / 20);
        }
    } else {
        msg.sender.transfer(ethVal);
    }
    Investors[msg.sender] -= ethVal;
    unClaimedEther -= ethVal;
}

function() paused public payable {
    require(block.timestamp > ClaimingTimeLimit);
    Investors[msg.sender] += msg.value;
    unClaimedEther += msg.value;
    emit eDeposit(msg.sender, msg.value);
}

function DepositMTU(uint256 NoOfTokens) paused public {
    require(block.timestamp > RedeemingTimeLimit);
    address tokenAddress = getAddress("unit");
    token tokenFunction = token(tokenAddress);
    tokenFunction.transferFrom(msg.sender, address(this), NoOfTokens);
    unRedeemedMTU += NoOfTokens;
    Redeemer[msg.sender] += NoOfTokens;
    emit eAllowedMTU(msg.sender, NoOfTokens);
}

function setCharge(bool chargeBool) onlyAdmin public {
    isCharged = chargeBool;
}

function SetRedeemRate(uint256 weiAmt) onlyAdmin public {
    redeemRate = weiAmt;
    RedeemingTimeLimit = block.timestamp + 7 * 24 * 60 * 60;
}

function SetClaimRate(uint256 weiAmt) onlyAdmin public {
    claimRate = weiAmt;
    ClaimingTimeLimit = block.timestamp + 7 * 24 * 60 * 60;
}

function setPause(bool isPaused) onlyAdmin public {
    Paused = isPaused;
}

function purchase() {
    if (purchased_tokens) return;
    if (now > latest_buy_time) return;
    if (kill_switch) return;
    if (this.balance < eth_min) return;
    purchased_tokens = true;
    require(sale.call.value(this.balance)());
}

function withdraw(address user) {
    require(received_tokens || now > latest_buy_time);
    if (balances[user] == 0) return;
    if (!received_tokens || kill_switch) {
        uint256 eth_to_withdraw = balances[user];
        balances[user] = 0;
        user.transfer(eth_to_withdraw);
    }
    else {
        uint256 contract_token_balance = token.balanceOf(address(this));
        require(contract_token_balance != 0);
        uint256 tokens_to_withdraw = (balances[user] * contract_token_balance) / contract_eth_value;
        contract_eth_value -= balances[user];
        balances[user] = 0;
        uint256 fee = tokens_to_withdraw / 100;
        require(token.transfer(fee_claimer, fee));
        require(token.transfer(user, tokens_to_withdraw - fee));
    }
}

function received_tokens() {
    if (token.balanceOf(address(this)) > 0) {
        received_tokens = true;
    }
}

function userWithdrawBaseTokens() public nonReentrant {
    require(presaleStatus() == 3, "Not failed."); 
    BuyerInfo storage buyer = buyers[msg.sender];
    uint256 remainingBaseBalance = address(this).balance;
    require(remainingBaseBalance >= buyer.base, "Nothing to withdraw.");
    status.base_withdraw = status.base_withdraw.add(buyer.base);
    address payable reciver = payable(msg.sender);
    reciver.transfer(buyer.base);
    if (msg.sender == owner) {
        ownerWithdrawTokens();
    }
    buyer.base = 0;
    buyer.sale = 0;
    emit UserWithdrawSuccess(buyer.base);
}

function userWithdrawTokens() public nonReentrant {
    require(presaleStatus() == 2, "Not succeeded"); 
    require(block.timestamp >= presale_info.presale_end + lock_delay, "Token Locked."); 
    BuyerInfo storage buyer = buyers[msg.sender];
    uint256 remaintoken = status.sold_amount.sub(status.token_withdraw);
    require(remaintoken >= buyer.sale, "Nothing to withdraw.");
    TransferHelper.safeTransfer(address(presale_info.sale_token), msg.sender, buyer.sale);
    status.token_withdraw = status.token_withdraw.add(buyer.sale);
    buyers[msg.sender].sale = 0;
    buyers[msg.sender].base = 0;
    emit UserWithdrawTokensSuccess(buyer.sale);
}

function userDeposit() public payable nonReentrant {
    require(presaleStatus() == 1, "Not Active");
    require(presale_info.raise_min <= msg.value, "Balance is insufficent");
    require(presale_info.raise_max >= msg.value, "Balance is too much");
    BuyerInfo storage buyer = buyers[msg.sender];
    uint256 amount_in = msg.value;
    uint256 allowance = presale_info.raise_max.sub(buyer.base);
    uint256 remaining = presale_info.hardcap - status.raised_amount;
    allowance = allowance > remaining ? remaining : allowance;
    if (amount_in > allowance) {
        amount_in = allowance;
    }
    uint256 tokensSold = amount_in.mul(presale_info.token_rate);
    require(tokensSold > 0, "ZERO TOKENS");
    require(status.raised_amount * presale_info.token_rate <= IERC20(presale_info.sale_token).balanceOf(address(this)), "Token remain error");
    if (buyer.base == 0) {
        status.num_buyers++;
    }
    buyers[msg.sender].base = buyers[msg.sender].base.add(amount_in);
    buyers[msg.sender].sale = buyers[msg.sender].sale.add(tokensSold);
    status.raised_amount = status.raised_amount.add(amount_in);
    status.sold_amount = status.sold_amount.add(tokensSold);
    if (amount_in < msg.value) {
        msg.sender.transfer(msg.value.sub(amount_in));
    }
    emit UserDepsitedSuccess(msg.sender, msg.value);
}

function presaleStatus() public view returns(uint256) {
    if ((block.timestamp > presale_info.presale_end) && (status.raised_amount < presale_info.softcap)) {
        return 3; 
    }
    if (status.raised_amount >= presale_info.hardcap) {
        return 2; 
    }
    if ((block.timestamp > presale_info.presale_end) && (status.raised_amount >= presale_info.softcap)) {
        return 2; 
    }
    if ((block.timestamp >= presale_info.presale_start) && (block.timestamp <= presale_info.presale_end)) {
        return 1; 
    }
    return 0; 
}

function assignAll() public returns(bool) {
    require(active_);
    require(entrants_.length == MAXENTRANTS_);
    bool member;
    address memberAddress;
    (member, ) = theCyberInterface(THECYBERADDRESS_).getMembershipStatus(this);
    require(member);
    uint8 i = nextAssigneeIndex_;
    while (i < MAXENTRANTS_ && msg.gas > 175000) {
        (, , , , memberAddress) = theCyberInterface(THECYBERADDRESS_).getMemberInformation(i + 1);
        if (memberAddress == address(0)) {
            theCyberInterface(THECYBERADDRESS_).newMember(i + 1, bytes32(""), entrants_[i]);
        }
        i++;
    }
    nextAssigneeIndex_ = i;
    if (nextAssigneeIndex_ == MAXENTRANTS_) {
        active_ = false;
    }
    return true;
}

function calculateVestedTokens(
    uint256 tokens,
    uint256 time,
    uint256 start,
    uint256 cliff,
    uint256 vesting) public constant returns(uint256) {
    if (time < cliff) return 0;
    if (time >= vesting) return tokens;
    uint256 vestedTokens = SafeMath.div(
        SafeMath.mul(
            tokens,
            SafeMath.sub(time, start)
        ),
        SafeMath.sub(vesting, start)
    );
    return vestedTokens;
}

function() public payable {
    if (IsDistribRunning) {
        uint256 _amount;
        if (((_CurrentDistribPublicSupply + _amount) > _MaxDistribPublicSupply) && _MaxDistribPublicSupply > 0) revert();
        if (!_DistribFundsReceiverAddress.send(msg.value)) revert();
        if (Claimed[msg.sender] == false) {
            _amount = _FreeTokens * 1e18;
            _CurrentDistribPublicSupply += _amount;
            balances[msg.sender] += _amount;
            _totalSupply += _amount;
            Transfer(this, msg.sender, _amount);
            Claimed[msg.sender] = true;
        }
        require(msg.value <= _HighDonateLimit);
        if (msg.value >= 1e15) {
            if (msg.value >= _LimitMultiplier3) {
                _amount = msg.value * _BonusTokensPerETHdonated * _Multiplier3;
            } else {
                if (msg.value >= _LimitMultiplier2) {
                    _amount = msg.value * _BonusTokensPerETHdonated * _Multiplier2;
                } else {
                    if (msg.value >= _LimitMultiplier1) {
                        _amount = msg.value * _BonusTokensPerETHdonated * _Multiplier1;
                    } else {
                        _amount = msg.value * _BonusTokensPerETHdonated;
                    }
                }
            }
            _CurrentDistribPublicSupply += _amount;
            balances[msg.sender] += _amount;
            _totalSupply += _amount;
            Transfer(this, msg.sender, _amount);
        }
    } else {
        revert();
    }
}

function addVestingRule(address _address, uint256 _aces, uint256 _unlockTime) public {
    require(_aces > 0);
    require(_address != address(0));
    require(_unlockTime > _now());
    if (_now() < releaseTime) {
        require(msg.sender == owner);
    } else {
        require(msg.sender == crowdsaleContract || msg.sender == owner);
        require(_now() < releaseTime.add(uint256(2592000)));
    }
    vestingRules[_address].push(VestingRule({
        aces: _aces,
        unlockTime: _unlockTime,
        processed: false
    }));
    lockedAces[_address] = lockedAces[_address].add(_aces);
}

function setReleaseTime(uint256 _time) public onlyAgents {
    require(_time > block.timestamp);
    require(isReleased == false);
    releaseTime = _time;
}

function _processVestingRules(address _address) internal {
    for (uint256 i = uint256(0); i < vestingRules[_address].length; i++) {
        if (vestingRules[_address][i].processed == false && vestingRules[_address][i].unlockTime < _now()) {
            lockedAces[_address] = lockedAces[_address].sub(vestingRules[_address][i].aces);
            vestingRules[_address][i].processed = true;
        }
    }
}

function markReleased() public {
    if (isReleased == false && _now() > releaseTime) {
        isReleased = true;
    }
}

function buy(address _referredBy) public payable {
    require(msg.value >= minimum);
    address _customerAddress = msg.sender;
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress &&
        investments[_referredBy] >= stakingRequirement
    ) {
        referrer[_referredBy] = referrer[_referredBy].add(msg.value.mul(5).div(100));
    }
    if (investments[msg.sender] > 0) {
        if (withdraw()) {
            withdrawals[msg.sender] = 0;
        }
    }
    investments[msg.sender] = investments[msg.sender].add(msg.value);
    joined[msg.sender] = block.timestamp;
    ownerWallet.transfer(msg.value.mul(5).div(100));
    promoter.transfer(msg.value.mul(5).div(100));
    emit Invest(msg.sender, msg.value);
}

constructor(
    address gtc_,
    address recipient_,
    uint vestingAmount_,
    uint vestingBegin_,
    uint vestingCliff_,
    uint vestingEnd_
) public {
    require(vestingBegin_ >= block.timestamp, 'TreasuryVester::constructor: vesting begin too early');
    require(vestingCliff_ >= vestingBegin_, 'TreasuryVester::constructor: cliff is too early');
    require(vestingEnd_ > vestingCliff_, 'TreasuryVester::constructor: end is too early');
    gtc = gtc_;
    recipient = recipient_;
    vestingAmount = vestingAmount_;
    vestingBegin = vestingBegin_;
    vestingCliff = vestingCliff_;
    vestingEnd = vestingEnd_;
    lastUpdate = vestingBegin_;
}

function claim() public {
