function newContract(
    address _tokenContract,
    uint256 _amount,
    string memory _toChain,
    string memory _toAddress
)
external
tokensTransferable(_tokenContract, msg.sender, _amount)
returns(bytes32 contractId) {
    contractId = sha256(
        abi.encodePacked(
            msg.sender,
            _tokenContract,
            _amount,
            block.timestamp
        )
    );
    if (haveContract(contractId))
        revert("Contract already exists");
    if (!ERC20(_tokenContract).transferFrom(msg.sender, owner(), _amount))
        revert("transferFrom sender failed");
    contracts[contractId] = SwapContract(
        msg.sender,
        owner(),
        _tokenContract,
        _amount,
        _toChain,
        _toAddress
    );
    emit SwapNew(
        contractId,
        msg.sender,
        owner(),
        _tokenContract,
        _amount
    );
}

