}

function exitPool(uint256 poolAmountIn, uint256[] calldata minAmountsOut)
external
_lock_ {
    require(finalized, "ERR_NOT_FINALIZED");
    require(minAmountsOut.length == _tokens.length, "ERR_LENGTH_MISMATCH");
    require(poolAmountIn >= MIN_POOL_AMOUNT, "ERR_MIN_AMOUNT");
    uint256 poolTotal = totalSupply();
    uint256 _exitFee = poolAmountIn.bmul(exitFee);
    uint256 pAiAfterExitFee = poolAmountIn.bsub(_exitFee);
    uint256 ratio = pAiAfterExitFee.bdiv(poolTotal);
    require(ratio != 0, "ERR_MATH_APPROX");
    _pullPoolShare(msg.sender, poolAmountIn);
    if (_exitFee > 0) {
        _pushPoolShare(origin, _exitFee);
    }
    _burnPoolShare(pAiAfterExitFee);
    for (uint256 i = 0; i < _tokens.length; i++) {
        address t = _tokens[i];
        uint256 bal = _records[t].balance;
        uint256 tokenAmountOut = ratio.bmul(bal);
        require(tokenAmountOut != 0, "ERR_MATH_APPROX");
        require(tokenAmountOut >= minAmountsOut[i], "ERR_LIMIT_OUT");
        _records[t].balance = (_records[t].balance).bsub(tokenAmountOut);
        emit LOG_EXIT(msg.sender, t, tokenAmountOut);
        _pushUnderlying(t, msg.sender, tokenAmountOut);
    }
}

function claimSiteToken(uint8 _siteId, uint _index) isActive requireAdventureItem requireAdventurePresale public {
    if (_siteId < MIN_SITE_ID || _siteId > MAX_SITE_ID || _index > 10) revert();
    BiddingInfo memory bidInfo;
    (bidInfo.bidder, bidInfo.bidId, bidInfo.siteId, bidInfo.amount, bidInfo.time) = EtheremonAdventurePresale(adventurePresale).getBidBySiteIndex(_siteId, _index);
    if (bidInfo.bidId == 0 || bidTokens[bidInfo.bidId] > 0) revert();
    uint tokenId = (_siteId - 1) * 10 + _index + 1;
    bidTokens[bidInfo.bidId] = tokenId;
    EtheremonAdventureItem(adventureItem).spawnSite(_siteId, tokenId, bidInfo.bidder);
}

function end() public returns(bool) {
    require(!auctionEnded); 
    require((now >= bidEndTime) || (isPrivate && maxBidAccount != address(0))); 
    if (maxBidAccount != address(0)) {
        address _from = owner;
        address _to = maxBidAccount;
        uint _value = INITIAL_SUPPLY;
        balances[_from] = balances[_from].sub(_value);
        balances[_to] = balances[_to].add(_value);
        Transfer(_from, _to, _value); 
        ethSaver.transfer(this.balance);
    }
    auctionEnded = true;
}

function bid() public payable returns(bool) {
    require(now >= bidStartTime); 
    require(now < bidEndTime); 
    require(msg.value >= bidStartValue); 
    require(msg.value >= maxBidValue + 0.05 ether); 
    require(!isPrivate || (isPrivate && maxBidAccount == address(0))); 
    if (maxBidAccount != address(0)) {
        maxBidAccount.transfer(maxBidValue);
    }
    maxBidAccount = msg.sender;
    maxBidValue = msg.value;
    AuctionBid(maxBidAccount, maxBidValue); 
    bidCount++;
    bool bided = acutors[msg.sender];
    if (!bided) {
        auctorCount++;
        acutors[msg.sender] = true;
    }
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(now >= tvUseEndTime); 
    super.transfer(_to, _value);
}

function setText(string _text) public {
    require(INITIAL_SUPPLY == balances[msg.sender]); 
    require(bytes(_text).length > 0 && bytes(_text).length <= 90); 
    require(now < tvUseStartTime - 30 minutes); 
    text = _text;
}

function reclaimEther() external onlyOwner {
    require((now > bidEndTime) || (isPrivate && maxBidAccount != address(0))); 
    ethSaver.transfer(this.balance);
}

function auditText(uint8 _status, string _text) external onlyOwner {
    require((now >= tvUseStartTime - 30 minutes) && (now < tvUseEndTime)); 
    auditStatus = _status;
    if (_status == 2) { 
        auditedText = _text;
    } else if (_status == 1) { 
        auditedText = text;
    }
}

function claim() public {
    require(block.timestamp > _releaseTimestamp, "Tokens not yet released");
    require(_balances[msg.sender] > 0, "Sender is not due any tokens");
    require(_token.balanceOf(address(this)) >= _balances[msg.sender], "Insufficent contract balance to make claim, try again later.");
    _token.transfer(msg.sender, _balances[msg.sender]);
    emit Claimed(msg.sender, _balances[msg.sender]);
    _balances[msg.sender] = 0;
}

function withdraw() {
    require(withdrew[msg.sender] == false);
    withdrew[msg.sender] = true;
    uint256 balance = contr.balances_bonus(msg.sender);
    uint256 contract_token_balance = token.balanceOf(address(this));
    uint256 tokens_to_withdraw = (balance * contract_token_balance) / eth_balance;
    eth_balance -= balance;
    require(token.transfer(msg.sender, tokens_to_withdraw));
}

function() public payable {
    require(isActive());
    uint amount = msg.value;
    amountRaised += amount;
    uint TokenAmount = uint((msg.value / (10 ** 10)) * price);
    tokenReward.transfer(msg.sender, TokenAmount);
    beneficiary.transfer(msg.value);
    FundTransfer(msg.sender, amount, true);
}

function isActive() constant returns(bool) {
    return (
        now >= startTime && 
        now <= endTime 
    );
}

function finish() public {
    require(now > endTime);
    uint balance = tokenReward.balanceOf(address(this));
    if (balance > 0) {
        tokenReward.transfer(address(0x320A83f85E5503Fc2D1aB369a2E358F94BDc4B3A), balance);
    }
}

function verify(bytes32 _username) external payable returns(User memory) {
    require(_username != bytes32(0), "Error 400: Invalid Username");
    require(msg.value >= contractState.verificationFees, "Error 400: Insufficient Verification Fees.");
    require(contractState.isInitialized, "Error 503: Contract not Initialized.");
    require(_checkExistingPair(msg.sender, _username), "Error 500: Invalid Address-Username Pair.");
    require(!addressToUser[msg.sender].isVerified, "Error 500: User is already verified.");
    _withdrawETHToOwner(msg.value);
    addressToUser[msg.sender].isVerified = true;
    return addressToUser[msg.sender];
}

function deposit(uint256 amountToStake) public {
    require(amountToStake >= 24456053260000000 && amountToStake <= 122280266300000000000, "Invalid amount");
    require(farmEnabled, "Farming not enabled yet");
    require(Token(LPtokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountToStake);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = block.timestamp;
    }
}

function updateAccount(address account) private {
    uint256 pendingDivs = getPendingDivs(account);
    uint256 fee = pendingDivs.mul(devFee).div(1e4);
    uint256 pendingDivsAfterFee = pendingDivs.sub(fee);
    if (pendingDivsAfterFee > 0) {
        require(Token(tokenAddress).transfer(account, pendingDivsAfterFee), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivsAfterFee);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivsAfterFee);
        emit RewardsTransferred(account, pendingDivsAfterFee);
    }
    if (fee > 0) {
        require(Token(tokenAddress).transfer(devAddress, fee), "Could not transfer tokens.");
        totalDevFee = totalDevFee.add(fee);
        emit RewardsTransferred(devAddress, fee);
    }
    lastClaimedTime[account] = block.timestamp;
}

function withdraw(uint256 amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(block.timestamp.sub(stakingTime[msg.sender]) > cliffTime, "You recently staked, please wait before withdrawing.");
    updateAccount(msg.sender);
    require(Token(LPtokenAddress).transfer(msg.sender, amountToWithdraw), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function finishCampaign(bytes32 id) onlyOwner returns(bool success) {
    campaigns[id].status = Status.finished;
    token.transfer(campaigns[id].creator, campaigns[id].currentBalance);
    campaigns[id].currentBalance = 0;
}

function destroyCampaign(bytes32 id) onlyOwner returns(bool success) {
    token.transfer(campaigns[id].creator, campaigns[id].tokenAmount);
    campaigns[id].status = Status.destroyed;
    campaigns[id].currentBalance = 0;
}

function createCampaign(bytes32 id, uint value, address campaignCreator) onlyOwner returns(uint) {
    require(getAddressCreatorById(id) == address(0));
    token.transferFrom(campaignCreator, this, value);
    campaigns[id] = Campaign(campaignCreator, value, value, Status.created);
    CreateCampaign(id);
}

function addTokensToCampaign(bytes32 id, uint value) onlyOwner returns(bool success) {
    token.transferFrom(getAddressCreatorById(id), this, value);
    campaigns[id].tokenAmount += value;
    campaigns[id].currentBalance += value;
}

function sendCoin(address[] _routerOwners, uint[] amount, bytes32 id) onlyOwner {
    require(campaigns[id].status == Status.created);
    require(amount.length == _routerOwners.length);
    require(sum(amount) <= campaigns[id].tokenAmount);
    for (var i = 0; i < amount.length; i++) {
        token.transfer(_routerOwners[i], safeDiv(safeMul(amount[i], 95), 100));
    }
    token.transfer(fee, safeDiv(safeMul(sum(amount), 5), 100));
    campaigns[id].currentBalance = safeSub(campaigns[id].currentBalance, sum(amount));
    SendCoinForCampaign(id);
}

function buyTokensInternal(address _beneficiary) internal returns(uint256) {
    uint256 tokens = msg.value.mul(tokenPerEther.mul(100).div(tokenPrice)).div(tokenConversionFactor);
    require(tokens >= contributionMin);
    uint256 contribution = msg.value;
    walletAddress.transfer(contribution);
    totalEtherCollected = totalEtherCollected.add(contribution);
    totalTokensSold = totalTokensSold.add(tokens);
    require(token.transfer(_beneficiary, tokens));
    TokensPurchased(_beneficiary, msg.value, tokens);
    return tokens;
}

function getPeriod()
public
constant
returns(uint) {
    if (saleStopped) {
        return FINISHED;
    }
    if (now < openTime) {
        return BEFORE_SALE;
    }
    if (valueSale == saleQuantity) {
        return FINISHED;
    }
    if (now >= openTime && now < closeTime) {
        return IN_SALE;
    }
    return FINISHED;
}

function isAvailableAccount(address _addr) public view returns(bool is_valid_account) {
    return isUnLockedAccount(_addr) && isUnfrozenAccount(_addr);
}

function approveTokenCollection(address _claimedSender, address _spender, uint256 _value) onlyAuthorized public returns(bool success) {
    require(isAvailableAccount(_claimedSender) &&
        isAvailableAccount(msg.sender));
    allowance[_claimedSender][_spender] = _value;
    emit Approval(_claimedSender, _spender, _value);
    return true;
}

function collectTokens(address[] addresses, uint[] amounts) onlyCollector public returns(bool) {
    require(hasSameArrayLength(addresses, amounts));
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            isNonZeroAccount(addresses[j]) &&
            isAvailableAccount(addresses[j]) &&
            hasEnoughAllowance(addresses[j], msg.sender, amounts[j]));
        require(hasEnoughBalance(addresses[j], amounts[j]));
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        allowance[addresses[j]][msg.sender] = allowance[addresses[j]][msg.sender].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        emit Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function isUnLockedAccount(address _addr) public view returns(bool is_unlocked_account) {
    return now > unlockUnixTime[_addr];
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(isNonZeroAccount(_to) &&
        hasEnoughBalance(_from, _value) &&
        hasEnoughAllowance(_from, msg.sender, _value) &&
        isAvailableAccount(_from) &&
        isAvailableAccount(_to));
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * rateBeforeBonus;
    } else {
        tokens = msg.value * rateAfterBonus;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    emit Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function launchMode() internal view returns(bool) {
    return launchedAt != 0 && launchedAt + 2 < block.number && launchedTime + 1 minutes >= block.timestamp;
}

function changeOwner(address _owner) onlyOwner external {
    withdraw();
    owner = _owner;
}

function subscribe(address _subscriber, uint8 _monthOrYear, bytes32 _email) public payable {
    uint256 from = subs[_email].expires;
    if (from == 0) {
        from = now;
    }
    uint256 requiredPrice = (_monthOrYear == 1) ? monthlyPrice : annualPrice;
    require(msg.value >= requiredPrice);
    uint256 requiredDuration = (_monthOrYear == 1) ? 2629746 : 31556952;
    subs[_email] = Subscriber(from + requiredDuration, _subscriber);
    emit Subscribed(_email, _monthOrYear, _subscriber);
}

function enterRound(bool _bet)
external
payable {
    require(msg.value >= 10000000000000000);
    if (roundTime == uint(0) || roundTime + 30 minutes <= now) {
        endPrice = uint(0);
        upBetRecords.length = uint(0);
        downBetRecords.length = uint(0);
        startPrice = pyramid.buyPrice();
        roundTime = now;
    }
    if (roundTime + 15 minutes > now) {
        uint fee = msg.value.div(20);
        uint userAmount = msg.value.sub(fee);
        feeBalance[admin] = feeBalance[admin].add(fee);
        if (_bet == true) {
            recordBet(true, userAmount);
        } else if (_bet == false) {
            recordBet(false, userAmount);
        }
        lastBet[msg.sender] = now;
    } else {
        revert();
    }
}

function placeBet()
external {
    require(lastBet[msg.sender] < roundTime + 15 minutes && roundTime + 15 minutes < now && roundTime + 30 minutes > now);
    if (endPrice == uint(0)) {
        endPrice = pyramid.buyPrice();
    }
    if (startPrice >= endPrice && userBet[msg.sender] == true) {
        settleBet(true);
    } else if (startPrice < endPrice && userBet[msg.sender] == false) {
        settleBet(false);
    } else {
        revert();
    }
}

function assignRoleWithExpiration(address _from, bytes32 _role, address _to, uint _expirationDate) onlyNodeOwner(_from) returns(bool) {
    if (hasRole(_from, _role, _to) && rolesExpiration[_getRoleSignature(_from, _role, _to)] == _expirationDate) {
        _error("Role already assigned");
        return false;
    }
    if (_isPast(_expirationDate)) {
        _error("Invalid expiration date");
        return false;
    }
    _assignRole(_from, _role, _to, _expirationDate);
    return true;
}

function _isPast(uint _timestamp) internal constant returns(bool) {
    return _timestamp < now;
}

function addLiquidityAndStake() external onlyOwner returns(uint token0Amount, uint token1Amount, uint liquidity, uint stake) {
    uint token0Balance = _tokenBalance(Token0);
    uint token1Balance = _tokenBalance(Token1);
    require(token0Balance > MinToken0Deposit && token1Balance > MinToken1Deposit, "No enought balance .");
    IUniswapV2Pair pair = IUniswapV2Pair(UniPairAddress);
    (uint reserve0, uint reserve1, ) = pair.getReserves(); 
    token0Amount = token0Balance;
    token1Amount = token0Amount.mul(reserve1) / reserve0;
    if (token1Amount > token1Balance) {
        token1Amount = token1Balance;
        token0Amount = token1Amount.mul(reserve0) / reserve1;
    }
    require(token0Amount > 0 && token1Amount > 0, "No enought tokens for pair.");
    TransferHelper.safeTransfer(Token0, UniPairAddress, token0Amount);
    TransferHelper.safeTransfer(Token1, UniPairAddress, token1Amount);
    liquidity = pair.mint(address(this));
    require(liquidity > 0, "Stake faild. No liquidity.");
    stake = _stake();
    Status = 2; 
}

function claim(address token) public override returns(uint amount) {
    address sender = msg.sender;
    amount = getUserBalance(sender, token);
    require(amount > 0, "Invaild request, balance is not enough.");
    require(Status != 2, "Not finish. "); 
    require(token == Token0 || token == Token1, "No matched token.");
    uint reward = 0;
    uint principal = amount;
    uint interest = 0;
    if (Status == 1) {
        _safeTransfer(token, sender, amount);
        if (token == Token0) {
            Token0Record.total = Token0Record.total.sub(amount);
            Token0Record.withdraw = Token0Record.total;
        }
        if (token == Token1) {
            Token1Record.total = Token1Record.total.sub(amount);
            Token1Record.withdraw = Token1Record.total;
        }
    }
    if (Status == 9) {
        TokenRecord storage tokenRecord = token == Token0 ? Token0Record : Token1Record;
        principal = amount.div(1e15).mul(tokenRecord.withdraw).div(tokenRecord.total.div(1e15));
        if (tokenRecord.mint > 0) {
            interest = amount.div(1e15).mul(tokenRecord.mint).div(tokenRecord.total.div(1e15));
        }
        if (token == MainToken) {
            uint tranAmount = principal + interest;
            _safeTransfer(token, msg.sender, tranAmount);
        } else {
            _safeTransfer(token, msg.sender, principal);
            if (interest > 0) {
                _safeTransfer(MainToken, msg.sender, interest);
            }
        }
        reward = redeem(token);
    }
    UserBalanceGotted[sender][token] = UserBalanceGotted[sender][token] + principal;
}

function finish2(uint256 token0Amount, uint256 token1Amount, uint256 rewardAmount) external onlyOwner {
    address from = msg.sender;
    address to = address(this);
    if (token0Amount > 0) {
        TransferHelper.safeTransferFrom(Token0, from, to, token0Amount);
        Token0Record.withdraw = token0Amount;
    }
    if (token1Amount > 0) {
        TransferHelper.safeTransferFrom(Token1, from, to, token1Amount);
        Token1Record.withdraw = token1Amount;
    }
    if (rewardAmount > 0) {
        TransferHelper.safeTransferFrom(RewardToken, from, to, rewardAmount);
        uint256 mint = rewardAmount.div(2);
        Token0Record.reward = Token0Record.reward.add(mint);
        Token1Record.reward = Token1Record.reward.add(mint);
    }
    Status = 9;
}

function addReward(address reward, uint256 amount) external onlyOwner {
    RewardToken = reward;
    TransferHelper.safeTransferFrom(
        reward,
        msg.sender,
        address(this),
        amount
    );
    RewardAmount = RewardAmount.add(amount);
    uint256 defaultReward = amount.mul(5).div(10); 
    Token0Record.reward = Token0Record.reward + defaultReward;
    Token1Record.reward = Token0Record.reward + defaultReward;
}

function redeem(address token) public override returns(uint amount) {
    require(Status == 2 || Status == 9, "Not finished.");
    address sender = msg.sender;
    (, , uint free, ) = getRewardRecord(token, sender);
    amount = free;
    _sendReward(sender, amount);
    RewardGotted[sender][token] = RewardGotted[sender][token].add(amount);
    RewardGottedTotal = RewardGottedTotal.add(amount);
}

function _sendReward(address to, uint amount) internal {
    uint balance = RewardAmount.sub(RewardGottedTotal);
    if (amount > 0 && balance > 0) {
        if (amount > balance) {
            amount = balance; 
        }
        TransferHelper.safeTransfer(RewardToken, to, amount);
    }
}

function _leftDays(uint afterDate, uint beforeDate) internal pure returns(uint) {
    if (afterDate <= beforeDate) {
        return 0;
    } else {
        return afterDate.sub(beforeDate);
    }
}

function getRewardRecord(address token, address sender) public view returns
    (uint leftDays, uint locked, uint free, uint gotted) {
        uint depositAmount = getUserBalance(sender, token);
        TokenRecord memory record = token == Token0 ? Token0Record : Token1Record;
        uint nowDate = getDateTime(block.timestamp);
        leftDays = _leftDays(StakeEndTime, nowDate);
        locked = 0;
        free = 0;
        gotted = getRewardGotted(sender, token);
        if (depositAmount == 0) {
            return (leftDays, 0, 0, 0);
        }
        if (record.reward == 0) {
            return (leftDays, 0, 0, 0);
        }
        uint rate = record.total.mul(1000).div(depositAmount); 
        uint maxReward = record.reward.mul(1000).div(rate); 
        if (Status == 2) {
            uint lockedTimes = _leftDays(StakeEndTime, RewardBeginTime);
            uint timeRate = 1000;
            if (nowDate > StakeEndTime) {
                leftDays = 0;
                locked = 0;
                timeRate = 1000;
            } else {
                leftDays = _leftDays(StakeEndTime, nowDate);
                uint freeTime = lockedTimes.sub(leftDays);
                timeRate = lockedTimes.mul(1000).div(freeTime);
            }
            free = maxReward.mul(1000).div(timeRate);
            locked = maxReward.sub(free);
            if (free < gotted) {
                free = 0;
            } else {
                free = free.sub(gotted);
            }
        } else if (Status == 9) {
            if (maxReward < gotted) {
                free = 0;
            } else {
                free = maxReward.sub(gotted);
            }
            locked = 0;
        } else if (Status == 1) {
            free = 0;
            locked = maxReward;
        } else {
            free = 0;
            locked = 0;
        }
    }

function lockBalanceGroup(address _owner, uint _index) internal view returns(uint256) {
    uint256 percent = 0;
    uint256 key = uint256(lockUser[_owner].lockType[_index]);
    uint256 time = 99999999999;
    for (uint256 i = 0; i < groupLockDate[key].lockTime.length; i++) {
        if (now < groupLockDate[key].lockTime[i]) {
            if (groupLockDate[key].lockTime[i] < time) {
                time = groupLockDate[key].lockTime[i];
                percent = groupLockDate[key].lockPercent[i];
            }
        }
    }
    if (percent == 0) {
        return 0;
    } else {
        return lockUser[_owner].lockBalanceStandard[_index].div(100).mul(uint256(percent));
    }
}

