function issueParityDollar(address StablecoinAddress, uint256 AmountOfParityDollars) external returns(string memory) {
    address msgSender = msg.sender;
    require(!safeguard, 'Safeguard was Activated');
    require(AmountOfParityDollars <= maxTransactionAmount, 'max Transaction Amount');
    require(StablecoinUnderCustody[StablecoinAddress], 'Invalid Stablecoin Address');
    uint256 StablecoinDecimals = IERC20(StablecoinAddress).decimals();
    uint256 StablecoinAmount = AmountOfParityDollars * (10 ** StablecoinDecimals) / (10 ** _decimals);
    IERC20(StablecoinAddress).transferFrom(msgSender, address(this), StablecoinAmount);
    _balanceOf[msgSender] = _balanceOf[msgSender].add(AmountOfParityDollars);
    _totalSupply = _totalSupply.add(AmountOfParityDollars);
    emit Transfer(address(0), msgSender, AmountOfParityDollars);
    emit Mint(msgSender, AmountOfParityDollars, DARSA_UAC, DARSA_UTC);
    return "Parity Dollar minted successfully";
}

function swapBack() internal swapping {
    uint256 amountToLiquify = swapThreshold.mul(liquidityFee).div(totalFee).div(2);
    uint256 amountToSwap = swapThreshold.sub(amountToLiquify);
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = WETH;
    uint256 balanceBefore = address(this).balance;
    router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        amountToSwap,
        0,
        path,
        address(this),
        block.timestamp + 360
    );
    uint256 amountETH = address(this).balance.sub(balanceBefore);
    uint256 totalETHFee = totalFee.sub(liquidityFee.div(2));
    uint256 amountETHLiquidity = amountETH.mul(liquidityFee).div(totalETHFee).div(2);
    uint256 amountETHTeam = amountETH.mul(teamFee).div(totalETHFee);
    uint256 amountETHMarketing = amountETH.mul(marketingFee).div(totalETHFee);
    uint256 amountETHStaking = amountETH.mul(stakingFee).div(totalETHFee);
    payable(teamFeeReceiver).transfer(amountETHTeam.div(2));
    payable(teamFeeReceiver2).transfer(amountETHTeam.div(4));
    payable(teamFeeReceiver3).transfer(amountETHTeam.div(4));
    payable(marketingWallet).transfer(amountETHMarketing);
    payable(stakingWallet).transfer(amountETHStaking);
    if (amountToLiquify > 0) {
        router.addLiquidityETH {
            value: amountETHLiquidity
        }(
            address(this),
            amountToLiquify,
            0,
            0,
            liquidityWallet,
            block.timestamp + 360
        );
        emit AutoLiquify(amountETHLiquidity, amountToLiquify);
    }
}

function getDayIndex_(uint timestamp) internal view returns(uint256) {
    uint16[12] memory offset = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
    uint8 day = DateTimeLib_.getDay(timestamp);
    uint8 month = DateTimeLib_.getMonth(timestamp) - 1;
    bool isLeapYear = DateTimeLib_.isLeapYear(DateTimeLib_.getYear(timestamp));
    if (isLeapYear && month > 1) {
        day = day + 1;
    }
    return offset[month] + day;
}

function getHolidayByIndex_(uint256 _dayIndex) internal view returns(uint result) {
    if (_dayIndex < 122) {
        return getFromList_(0, _dayIndex);
    }
    if (_dayIndex < 244) {
        return getFromList_(1, _dayIndex - 122);
    }
    return getFromList_(2, _dayIndex - 244);
}

function handlePayouts_(uint256 _forDev, uint256 _forPayout, uint256 _forDayOwner, address _takenBy, address _previousLast, address _dayOwner) internal {
    uint256[] memory runnerPortions = new uint256[](3);
    if (_previousLast != address(0)) {
        runnerPortions[2] = _forPayout.mul(10).div(100);
    }
    if (torchRunners[2] != address(0)) {
        runnerPortions[1] = _forPayout.mul(30).div(100);
    }
    runnerPortions[0] = _forPayout.sub(runnerPortions[1]).sub(runnerPortions[2]);
    playerData_[_previousLast].dividends = playerData_[_previousLast].dividends.add(runnerPortions[2]);
    playerData_[torchRunners[2]].dividends = playerData_[torchRunners[2]].dividends.add(runnerPortions[1]);
    playerData_[torchRunners[1]].dividends = playerData_[torchRunners[1]].dividends.add(runnerPortions[0]);
    playerData_[owner].profits = playerData_[owner].profits.add(_forDev);
    if (_dayOwner != _takenBy) {
        playerData_[_dayOwner].profits = playerData_[_dayOwner].profits.add(_forDayOwner);
    }
    owner.transfer(_forDev);
    if (_dayOwner != _takenBy) {
        _dayOwner.transfer(_forDayOwner);
    }
}

function takeTheTorch_(uint256 _amountPaid, address _takenBy, address _referredBy) internal antiWhalePrice(_amountPaid) returns(uint256) {
    require(_takenBy != address(0));
    require(_amountPaid >= 5 finney);
    require(_takenBy != torchRunners[0]); 
    if (_referredBy == address(this)) {
        _referredBy = address(0);
    }
    address previousLast = torchRunners[2];
    torchRunners[2] = torchRunners[1];
    torchRunners[1] = torchRunners[0];
    torchRunners[0] = _takenBy;
    address dayOwner = OwnTheDayContract_.ownerOf(getDayIndex_(now));
    uint256 forDev = _amountPaid.mul(5).div(100);
    uint256 forTokens = _amountPaid.sub(_amountPaid.div(4));
    uint256 forPayout = _amountPaid.sub(forDev).sub(forTokens);
    uint256 forDayOwner = calculateDayOwnerCut_(forPayout);
    if (dayOwner == _takenBy) {
        forTokens = forTokens.add(forDayOwner);
        forPayout = _amountPaid.sub(forDev).sub(forTokens);
        playerData_[_takenBy].champion = true;
    } else {
        forPayout = forPayout.sub(forDayOwner);
    }
    onTorchPassed(torchRunners[1], _takenBy, _amountPaid);
    uint256 mintedTokens = CryptoTorchToken_.mint.value(forTokens)(_takenBy, forTokens, _referredBy);
    updateLeaders_(_takenBy, _amountPaid);
    handlePayouts_(forDev, forPayout, forDayOwner, _takenBy, previousLast, dayOwner);
    return mintedTokens;
}

function updateLeaders_(address _takenBy, uint256 _amountPaid) internal {
    if (_takenBy == owner || _takenBy == donationsReceiver_) {
        return;
    }
    if (_amountPaid > _lowestHighPrice) {
        updateHighestPrices_(_amountPaid, _takenBy);
    }
    uint256 tokenBalance = CryptoTorchToken_.balanceOf(_takenBy);
    if (tokenBalance > _lowestHighMiles) {
        updateHighestMiles_(tokenBalance, _takenBy);
    }
}

function withdrawDividends() public returns(uint256) {
    CryptoTorchToken_.withdrawFor(msg.sender);
    return withdrawFor_(msg.sender);
}

receive() payable external {
    uint256 _supply = totalSupply();
    require(_supply < 1e15, "Sale finished");
    if (msg.value > 0) {
        require(sales, "Sale deactivated");
        if (referrers[msg.sender] == address(0)) referrers[msg.sender] = smart;
        uint256 _rate = EthRateSource.EthToUsdRate();
        require(_rate > 0, "Rate error");
        uint256 _amount = msg.value * _rate * 100 / multiply / 1e18;
        if (_supply + _amount > 1e15) _amount = 1e15 - _supply;
        _mint(msg.sender, _amount);
        emit CheckIn(msg.sender, msg.value, _amount);
    } else {
        require(fixes[msg.sender] > 0, "No profit");
        _payout(msg.sender, _supply);
    }
}

function fnProof(bool all) external {
    uint256 _amount = all ? balanceOf(smart) : balanceOf(smart).safeSub(1e9);
    require(_amount >= 3, "Little amount");
    for (uint8 i = 0; i < 3; i++) {
        _transfer(smart, founders[i], _amount / founders.length);
    }
}

function _payout(address account, uint256 supply) private {
    require(supply < 1e15, "Emition is closed");
    uint256 _profit = _fixProfit(account, supply);
    if (_profit > 0) _fixReward(referrers[account], _profit, supply);
    uint256 _userProfit = holds[account];
    _userProfit = supply + _userProfit > 1e15 ? 1e15 - supply : _userProfit;
    if (_userProfit > 0) {
        holds[account] = 0;
        _mint(account, _userProfit);
        emit Payout(account, _userProfit);
    }
}

function fnBounty() external {
    uint256 _delta = totalSupply().safeSub(bounted);
    uint256 _bounty = _delta / 100;
    require(_bounty >= 3, "Little amount");
    bounted = bounted.safeAdd(_delta);
    for (uint8 i = 0; i < 3; i++) {
        _mint(founders[i], _bounty / 3);
    }
}

function _beforeTokenTransfer(address from, address to, uint256 amount) internal override {
    if (to == stoContract) {
        require(amount >= minimum, "Little amount");
        _swap(from, amount);
    }
    if (referrers[to] == address(0) && amount > 0 && from != address(0)) referrers[to] = from;
    uint256 _supply = totalSupply();
    if (from == to) {
        _payout(from, _supply);
    } else {
        if (_supply < 1e15) {
            if (from != address(0)) {
                uint256 _profit = _fixProfit(from, _supply);
                if (_profit > 0) _fixReward(referrers[from], _profit, _supply);
            }
            if (to != address(0)) {
                if (fixes[to] > 0) {
                    uint256 _profit = _fixProfit(to, _supply);
                    if (_profit > 0) _fixReward(referrers[to], _profit, _supply);
                } else fixes[to] = uint64(block.timestamp);
            }
        }
    }
}

function _fixProfit(address account, uint256 supply) private returns(uint256 _value) {
    uint256 _balance = balanceOf(account);
    uint256 _hold = block.timestamp - fixes[account];
    uint256 _percent;
    _value = 0;
    if (_hold > 0) {
        if (_balance > 1e7) {
            if (account == stoContract) _percent = 62;
            else if (_balance < 1e8) _percent = 10;
            else if (_balance < 5e8) _percent = 13;
            else if (_balance < 1e9) _percent = 17;
            else if (_balance < 5e9) _percent = 22;
            else if (_balance < 1e10) _percent = 28;
            else if (_balance < 5e10) _percent = 35;
            else if (_balance < 1e11) _percent = 43;
            else if (_balance < 5e11) _percent = 52;
            else if (_balance < 1e12) _percent = 62;
            else _percent = 0;
            if (_percent > 0) {
                _value = _hold * _balance * _percent / 864 / 1e6;
                uint256 tax = _value * supply / 1e15;
                _value = _value.safeSub(tax);
                holds[account] = holds[account].safeAdd(_value);
                fixes[account] = uint64(block.timestamp);
                emit Profit(account, _value);
            }
        }
    }
}

function fnProfit(address account) external {
    require(fixes[account] > 0 && holds[account] + balanceOf(account) > 0, "No profit");
    _payout(account, totalSupply());
}

function _fixReward(address referrer, uint256 amount, uint256 supply) private returns(uint256 _value) {
    uint256 _balance = balanceOf(referrer);
    uint256 _percent;
    if (_balance >= 1e8 && _balance < 1e12) {
        if (_balance < 1e9) _percent = 520;
        else if (_balance < 1e10) _percent = 750;
        else if (_balance < 1e11) _percent = 1280;
        else _percent = 2650;
        _value = amount * _percent / 10000;
        uint256 tax = _value * supply / 1e15;
        _value = _value.safeSub(tax);
        holds[referrer] = holds[referrer].safeAdd(_value);
        emit Reward(referrer, _value);
    }
}

function createVariation(uint256 _gene, uint256 _totalSupply) public returns(uint8) {
    require(msg.sender == address(dogCore) || msg.sender == owner);
    randomSeed = uint256(randomSeed * _gene);
    uint256 variationRandom = random();
    uint256 totalRandom = _totalSupply >= 20000 ? _totalSupply : 20000;
    return uint256(variationRandom % uint256(totalRandom * variationProbably)) == 1 ? 1 : 0;
}

function callBackVariations() public {
    uint256 index = 0;
    if (block.number < cVariations[cVariations.length - 1].withdrawBlock) {
        require(cVariations.length > 1);
        CallBackVariations(
            cVariations[cVariations.length - 2].luckyDogs,
            cVariations[cVariations.length - 2].luckyAccounts,
            cVariations[cVariations.length - 2].totalAmount,
            cVariations[cVariations.length - 2].withdrawBlock
        );
        return;
    }
    require(msg.sender == dogCore.cooAddress() || msg.sender == owner);
    CVariation storage currentCVariation = cVariations[cVariations.length - 1];
    currentCVariation.withdrawBlock = block.number;
    var (, , , , , , , spoolAmount, ) = lottery.getCLottery();
    uint256 luckyAmount = (dogCore.getAvailableBlance() - spoolAmount) * 3 / 100;
    require(luckyAmount > 0);
    currentCVariation.totalAmount = luckyAmount;
    CVariation memory newCVariation;
    newCVariation.totalAmount = uint256(0);
    newCVariation.withdrawBlock = uint256(block.number + variationCycle);
    cVariations.push(newCVariation);
    uint256 luckySize = currentCVariation.luckyDogs.length;
    if (luckySize == 0) {
        CallBackVariations(
            currentCVariation.luckyDogs,
            currentCVariation.luckyAccounts,
            currentCVariation.totalAmount,
            currentCVariation.withdrawBlock
        );
        return;
    }
    for (index = 1; index <= luckySize; index++) {
        uint256 dogId = currentCVariation.luckyDogs[luckySize - index];
        var (, , , birthTime, , , , , , ) = dogCore.getDog(dogId);
        if (birthTime < block.number) {
            break;
        }
        cVariations[cVariations.length - 1].luckyDogs.push(dogId);
        cVariations[cVariations.length - 1].luckyAccounts.push(currentCVariation.luckyAccounts[luckySize - index]);
    }
    for (index = 1; index <= cVariations[cVariations.length - 1].luckyDogs.length; index++) {
        delete currentCVariation.luckyDogs[luckySize - index];
        delete currentCVariation.luckyAccounts[luckySize - index];
    }
    luckySize -= cVariations[cVariations.length - 1].luckyDogs.length;
    if (luckySize == 0) {
        CallBackVariations(
            currentCVariation.luckyDogs,
            currentCVariation.luckyAccounts,
            currentCVariation.totalAmount,
            currentCVariation.withdrawBlock
        );
        return;
    }
    uint256 reward = currentCVariation.totalAmount * 9 / (10 * luckySize);
    for (index = 0; index < luckySize; index++) {
        address owner = currentCVariation.luckyAccounts[index];
        dogCore.sendMoney(owner, reward);
    }
    dogCore.sendMoney(dogCore.cfoAddress(), currentCVariation.totalAmount / 10);
    CallBackVariations(
        currentCVariation.luckyDogs,
        currentCVariation.luckyAccounts,
        currentCVariation.totalAmount,
        currentCVariation.withdrawBlock
    );
}

