    uint amount;
    require(now > end_date); 
    amount = holder_balance[msg.sender];
    holder_balance[msg.sender] = 0;
    msg.sender.transfer(amount);
}

function withdrawAllTokens(uint256 _lockID) public ReEntrancyGuard {
    require(block.timestamp >= tokenLocked[_lockID].unlockedAtTime, "Timed lock has not expired");
    require(msg.sender == tokenLocked[_lockID].ownerAddress, "Not authorized to withdraw");
    require(!tokenLocked[_lockID].hasWithdrawn, "Lock already withdrawn");
    require(ERC20(tokenLocked[_lockID].tokenAddress).transfer(msg.sender, tokenLocked[_lockID].amount), "Tokens not withdrawn");
    tokenLocked[_lockID].hasWithdrawn = true;
    emit TokensWithdrawn(_lockID, msg.sender, tokenLocked[_lockID].amount);
}

function addToLock(uint256 _lockID, address _tokenAddress, uint256 _amount) public ReEntrancyGuard {
    require(_amount > 0, "Invalid amount");
    require(tokenLocked[_lockID].unlockedAtTime > block.timestamp, "Lock has expired");
    require(tokenLocked[_lockID].tokenAddress == _tokenAddress, "Token not held in lock");
    require(ERC20(_tokenAddress).balanceOf(msg.sender) >= _amount, "Insuffecient balance");
    require(ERC20(_tokenAddress).approve(address(this), _amount), "Must approve to transfer");
    require(ERC20(_tokenAddress).transferFrom(msg.sender, address(this), _amount), "Tokens not transferred");
    tokenLocked[_lockID].amount = tokenLocked[_lockID].amount.add(_amount);
    emit LockBalanceIncreased(msg.sender, _lockID, _amount);
}

function createVest(address _tokenExemption, address _tokenAddress, address[] calldata _vestOwnersAddresses, uint256 _totalAmount, uint256[] calldata _unlockTimes, uint256[] calldata _unlockAmounts) public payable ReEntrancyGuard {
    bool takeFee = true;
    if (addressExemptFromFee[msg.sender] || (feeExemptToken[_tokenExemption] && (ERC20(_tokenExemption).balanceOf(msg.sender) >= tokenBalanceThreshold[_tokenExemption]))) {
        takeFee = false;
    }
    uint256 feeCost = ethFeePerLock.mul(_vestOwnersAddresses.length);
    if (takeFee) require(msg.value == feeCost, "Fee amount invalid");
    require(_unlockTimes.length == _unlockAmounts.length, "Array sizes must match");
    uint256 _sumOfUnlockAmounts;
    for (uint256 i = 0; i < _unlockAmounts.length; i++) {
        _sumOfUnlockAmounts += _unlockAmounts[i];
    }
    uint256 _totalVestAmount = _sumOfUnlockAmounts.mul(_vestOwnersAddresses.length);
    require(_totalAmount > 0 && _totalAmount == _totalVestAmount, "Invalid amount input");
    require(ERC20(_tokenAddress).balanceOf(msg.sender) >= _totalAmount, "Insufficient balance");
    require(ERC20(_tokenAddress).transferFrom(msg.sender, address(this), _totalAmount), "Transfer failed");
    for (uint256 i = 0; i < _vestOwnersAddresses.length; i++) {
        for (uint256 j = 0; j < _unlockTimes.length; j++) {
            _lockTokens(msg.sender, _tokenAddress, _vestOwnersAddresses[i], _unlockAmounts[j], _unlockTimes[j]);
            emit TokensLocked(_tokenAddress, msg.sender, _vestOwnersAddresses[i], _unlockAmounts[j], _unlockTimes[j]);
        }
    }
}

function lockTokens(address _tokenExemption, address _tokenAddress, address _ownerAddress, uint256 _amount, uint256 _unlockedAtTime) public payable ReEntrancyGuard {
    bool takeFee = true;
    if (addressExemptFromFee[msg.sender] || (feeExemptToken[_tokenExemption] && (ERC20(_tokenExemption).balanceOf(msg.sender) >= tokenBalanceThreshold[_tokenExemption]))) {
        takeFee = false;
    }
    if (takeFee) require(msg.value == ethFeePerLock, "Fee amount invalid");
    require(_amount > 0, "Must be more than 0");
    require(ERC20(_tokenAddress).balanceOf(msg.sender) >= _amount, "Insuffecient balance");
    require(ERC20(_tokenAddress).transferFrom(msg.sender, address(this), _amount), "Transfer failed");
    uint256 _thisLockID = ++lockID;
    locksCreatedByAddress[msg.sender].push(_thisLockID);
    locksOwnedByAddress[_ownerAddress].push(_thisLockID);
    locksByTokenAddress[_tokenAddress].push(_thisLockID);
    Lock memory lock = Lock(_thisLockID, msg.sender, _tokenAddress, _ownerAddress, _amount, _unlockedAtTime, block.timestamp, false);
    tokenLocked[_thisLockID] = lock;
    emit TokensLocked(_tokenAddress, msg.sender, _ownerAddress, _amount, _unlockedAtTime);
}

function transferVestOwnerShip(uint256 _lockID, address _newOwner) external {
    require(msg.sender == tokenLocked[_lockID].ownerAddress, "Not owner");
    tokenLocked[_lockID].ownerAddress = _newOwner;
    emit LockOwnershipTransferred(_lockID, msg.sender, _newOwner);
}

function extendLock(uint256 _lockID, uint256 _newUnlockTime) public ReEntrancyGuard {
    require(msg.sender == tokenLocked[_lockID].ownerAddress);
    require(_newUnlockTime > tokenLocked[_lockID].unlockedAtTime);
    uint256 previousUnlockAtTime = tokenLocked[_lockID].unlockedAtTime;
    tokenLocked[_lockID].unlockedAtTime = _newUnlockTime;
    emit LockExtended(_lockID, previousUnlockAtTime, _newUnlockTime);
}

function withdrawEarnings() external returns(bool success) {
    uint totalReward = (referralRewards[msg.sender]).add(stakeRewards[msg.sender]).add(calculateEarnings(msg.sender));
    require(totalReward > 0, 'No reward to withdraw');
    require((IERC20(lead).balanceOf(address(this))).sub(totalStaked) >= totalReward, 'Insufficient LEAD balance in pool');
    stakeRewards[msg.sender] = 0;
    referralRewards[msg.sender] = 0;
    referralCount[msg.sender] = 0;
    uint remainder = (now.sub(lastClock[msg.sender])).mod(86400);
    lastClock[msg.sender] = now.sub(remainder);
    IERC20(lead).transfer(msg.sender, totalReward);
    emit OnWithdrawal(msg.sender, totalReward);
    return true;
}

function unstake(uint _amount) external onlyRegistered() {
    require(_amount <= stakes[msg.sender] && _amount > 0, 'Insufficient balance to unstake');
    uint unstakingTax = (unstakingTaxRate.mul(_amount)).div(1000);
    uint afterTax = _amount.sub(unstakingTax);
    stakeRewards[msg.sender] = (stakeRewards[msg.sender]).add(calculateEarnings(msg.sender));
    stakes[msg.sender] = (stakes[msg.sender]).sub(_amount);
    uint remainder = (now.sub(lastClock[msg.sender])).mod(86400);
    lastClock[msg.sender] = now.sub(remainder);
    totalStaked = totalStaked.sub(_amount);
    IERC20(lead).transfer(msg.sender, afterTax);
    if (stakes[msg.sender] == 0) {
        registered[msg.sender] = false;
    }
    emit OnUnstake(msg.sender, _amount, unstakingTax);
}

function registerAndStake(uint _amount, address _referrer) external onlyUnregistered() whenActive() {
    require(msg.sender != _referrer, "Cannot refer self");
    require(registered[_referrer] || address(0x0) == _referrer, "Referrer must be registered");
    require(IERC20(lead).balanceOf(msg.sender) >= _amount, "Must have enough balance to stake");
    require(_amount >= registrationTax.add(minimumStakeValue), "Must send at least enough MANDOX to pay registration fee.");
    require(IERC20(lead).transferFrom(msg.sender, address(this), _amount), "Stake failed due to failed amount transfer.");
    uint finalAmount = _amount.sub(registrationTax);
    uint stakingTax = (stakingTaxRate.mul(finalAmount)).div(1000);
    if (_referrer != address(0x0)) {
        referralCount[_referrer]++;
        referralRewards[_referrer] = (referralRewards[_referrer]).add(stakingTax);
    }
    registered[msg.sender] = true;
    lastClock[msg.sender] = now;
    totalStaked = totalStaked.add(finalAmount).sub(stakingTax);
    stakes[msg.sender] = (stakes[msg.sender]).add(finalAmount).sub(stakingTax);
    emit OnRegisterAndStake(msg.sender, _amount, registrationTax.add(stakingTax), _referrer);
}

function stake(uint _amount) external onlyRegistered() whenActive() {
    require(_amount >= minimumStakeValue, "Amount is below minimum stake value.");
    require(IERC20(lead).balanceOf(msg.sender) >= _amount, "Must have enough balance to stake");
    require(IERC20(lead).transferFrom(msg.sender, address(this), _amount), "Stake failed due to failed amount transfer.");
    uint stakingTax = (stakingTaxRate.mul(_amount)).div(1000);
    uint afterTax = _amount.sub(stakingTax);
    totalStaked = totalStaked.add(afterTax);
    stakeRewards[msg.sender] = (stakeRewards[msg.sender]).add(calculateEarnings(msg.sender));
    uint remainder = (now.sub(lastClock[msg.sender])).mod(86400);
    lastClock[msg.sender] = now.sub(remainder);
    stakes[msg.sender] = (stakes[msg.sender]).add(afterTax);
    emit OnStake(msg.sender, afterTax, stakingTax);
}

function buy_planet() public {
    require(msg.sender == tx.origin);
    require(msg.sender != address(0));
    require(msg.sender != address(this));
    require(players[msg.sender].state > 0);
    uint256 price = PLANET_PRICE.div(koef);
    price = price.sub(price.mul(players[msg.sender].discount).div(100)).add(FEE_SILO.div(koef));
    require(players[msg.sender].balance >= price);
    uint256 id = players[msg.sender].position;
    require(nodes[id].planet.owner == address(0));
    players[msg.sender].balance = players[msg.sender].balance.sub(price);
    players[msg.sender].planets.push(id);
    nodes[id].planet.owner = msg.sender;
    if (!create_flag) {
        create_flag = true;
    } else {
        create_planet();
        create_planet();
        create_planet();
        create_flag = false;
    }
    if (now < silo_timer) {
        silo_addr = msg.sender;
        silo_timer = silo_timer.add(TIMER_STEP);
        silo = silo.add(FEE_SILO);
    } else {
        if (silo > 0 && silo_addr != address(0))
            players[silo_addr].balance = players[silo_addr].balance.add(silo);
        silo_addr = msg.sender;
        silo_timer = now.add(TIMER_STEP);
        silo = FEE_SILO;
    }
    if (players[msg.sender].discount < 50)
        players[msg.sender].discount = players[msg.sender].discount.add(1);
    master.transfer(price);
}

function get_info(uint256 id) public view returns(uint256[] fees, bytes32[] datas, address[] addresses, uint256[] infos) {
    fees = new uint256[](12);
    datas = new bytes32[](12);
    addresses = new address[](14);
    infos = new uint256[](14);
    uint8 i;
    for (i = 0; i < 12; i++) {
        if (i < nodes.length) {
            fees[i] = nodes[id].planet.fee.div(koef);
            datas[i] = nodes[id].planet.data;
            addresses[i] = nodes[id].planet.owner;
            infos[i] = id;
            id = nodes[id].next;
        }
    }
    addresses[i] = silo_addr;
    infos[i] = silo;
    i++;
    if (now < silo_timer)
        infos[i] = silo_timer - now;
}

function _ownerReleaseLimit() private view returns(uint256) {
    uint256 time = block.timestamp;
    uint256 limit;
    uint256 amount;
    limit = FOOTSTONE_ROUND_AMOUNT.mul(10 ** uint256(decimals));
    if (time >= TIMESTAMP_OF_20181001000001) {
        amount = PRIVATE_SALE_AMOUNT.mul(10 ** uint256(decimals));
        if (totalPrivateSalesReleased < amount) {
            limit = limit.add(amount).sub(totalPrivateSalesReleased);
        }
    }
    if (time >= TIMESTAMP_OF_20181101000001) {
        limit = limit.add(COMMON_PURPOSE_AMOUNT.sub(OWNER_LOCKED_IN_COMMON).mul(10 ** uint256(decimals)));
    }
    if (time >= TIMESTAMP_OF_20190201000001) {
        limit = limit.add(TEAM_RESERVED_AMOUNT1.mul(10 ** uint256(decimals)));
    }
    if (time >= TIMESTAMP_OF_20190501000001) {
        limit = limit.add(OWNER_LOCKED_IN_COMMON.mul(10 ** uint256(decimals)));
    }
    if (time >= TIMESTAMP_OF_20191101000001) {
        limit = limit.add(TEAM_RESERVED_AMOUNT2.mul(10 ** uint256(decimals)));
    }
    if (time >= TIMESTAMP_OF_20201101000001) {
        limit = limit.add(TEAM_RESERVED_AMOUNT3.mul(10 ** uint256(decimals)));
    }
    if (time >= TIMESTAMP_OF_20211101000001) {
        limit = limit.add(TEAM_RESERVED_AMOUNT4.mul(10 ** uint256(decimals)));
    }
    return limit;
}

function withdrawToTeamStep4(uint256 _amount) public onlyOwner {
    require(block.timestamp >= TIMESTAMP_OF_20211101000001);
