}

function convertToWei(bytes32 bSymbol, uint value) external view returns(uint weiValue) {
    require(rates[bSymbol].rate > 0, "rates[bSymbol] must be > 0");
    return value.mul(1000000000000000000).roundedDiv(rates[bSymbol].rate);
}

function convertFromWei(bytes32 bSymbol, uint weiValue) external view returns(uint value) {
    require(rates[bSymbol].rate > 0, "rates[bSymbol] must be > 0");
    return weiValue.mul(rates[bSymbol].rate).roundedDiv(1000000000000000000);
}

function safeWithdrawal() afterDeadline {
    require(crowdsaleClosed);
    if (!fundingGoalReached) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (fundingGoalReached && beneficiary == msg.sender) {
        if (beneficiary.send(amountRaised)) {
            FundTransfer(beneficiary, amountRaised, false);
        } else {
            fundingGoalReached = false;
        }
    }
}

function distribute() payable public returns(bool) {
    for (uint i = 1; i < index; i++) {
        uint256 balance = balances[addresses[i]];
        uint256 giveAmount = balance.mul(msg.value).div(totalSupply);
        Distribute(addresses[i], balance, giveAmount, i);
        addresses[i].transfer(giveAmount);
    }
    return true;
}

function add_timeAddressMonth(address _address, uint256 _time, uint8 idx, uint8 _percent) public isOwner {
    if (now > _time) {
        revert("Must greater than current time");
    }
    if (idx >= lockCountMonth[_address]) {
        revert("Invalid Setup Period");
    }
    if (idx != 0 && lockTime[_address][idx - 1] >= _time) {
        revert("Must greater than previous time");
    }
    lockPercent[_address][idx] = _percent;
    lockTime[_address][idx] = _time;
}

function refresh_lockPermitBalance(address _address) public {
    if (lockTimeAddress[_address] == false) {
        revert("Address without Lock");
    }
    for (uint8 i = 0; i < lockCountMonth[msg.sender]; i++) {
        if (now >= lockTime[_address][i] && lockCheck[_address][i] == false) {
            lockPermitBalance[_address] += lockBalance[_address][i];
            lockCheck[_address][i] = true;
            if (lockCountMonth[_address] - 1 == i) {
                delete_timeAddress(_address);
            }
        }
    }
}

function migrate(IUniswapV2Pair orig) public returns(IUniswapV2Pair) {
    require(block.number >= notBeforeBlock, "too early to migrate");
    require(orig.factory() == oldFactory, "not from old factory"); 
    address token0 = orig.token0();
    address token1 = orig.token1();
    IUniswapV2Pair pair = IUniswapV2Pair(factory.getPair(token0, token1));
    if (pair == IUniswapV2Pair(address(0))) {
        pair = IUniswapV2Pair(factory.createPair(token0, token1));
    }
    uint256 lp = orig.balanceOf(msg.sender);
    if (lp == 0) return pair;
    desiredLiquidity = lp;
    orig.transferFrom(msg.sender, address(orig), lp);
    orig.burn(address(pair));
    pair.mint(msg.sender);
    desiredLiquidity = uint256(-1);
    return pair;
}

function enablePublicTransfers()
public grantOwner {
    require(crowdsaleSuccessful());
    publicTransfersEnabled = true;
    releaseStartTime = now;
}

function addTokenLock(uint amount, uint timespan)
public grantOwner {
    require(releaseStartTime == 0);
    requireOwnerUnlockedAmount(amount);
    locks.push(TokenLock({
        amount: amount,
        timespan: timespan,
        released: false
    }));
    lockedAmount += amount;
}

function releaseLockedTokens(uint8 idx)
public grantOwner {
    require(releaseStartTime > 0);
    require(!locks[idx].released);
    require((releaseStartTime + locks[idx].timespan) < now);
    locks[idx].released = true;
    lockedAmount -= locks[idx].amount;
}

function pickWinner() public isManager isAnyPlayers payable returns(address) {
    uint index = random();
    uint share = (this.balance) * 20 / 100;
    winner = players[index];
    players[index].transfer(this.balance - share); 
    manager.transfer(share);
    players = new address[](0);
    return winner;
}

function() public payable {
    require(now >= startDate && now <= endDate && totalSupply_ >= startCrowdsale && totalSupply_ < endCrowdsalel);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 8400;
    } else {
        tokens = msg.value * 7350;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    totalSupply_ = safeAdd(totalSupply_, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function releaseToken(address account) public {
    require(account != address(0));
    VestedToken storage vested = vestedUser[account];
    uint256 unreleasedToken = _releasableAmount(account); 
    require(unreleasedToken > 0);
    vested.releasedToken = vested.releasedToken.add(unreleasedToken);
    IERC20(DGMV_TOKEN).transfer(account, unreleasedToken);
    emit TokenReleased(account, unreleasedToken);
}

function setVesting(address account, uint256 amount, uint256 cliff, uint256 duration, uint256 startAt) external returns(bool) {
    VestedToken storage vested = vestedUser[account];
    if (vested.start > 0) {
        require(vested.revoked);
        uint unclaimedTokens = _vestedAmount(account).sub(vested.releasedToken);
        require(unclaimedTokens == 0);
    }
    IERC20(DGMV_TOKEN).transferFrom(_msgSender(), address(this), amount);
    _setVesting(account, amount, cliff, duration, startAt);
    return true;
}

function revoke(address account) external onlyOwner returns(bool) {
    VestedToken storage vested = vestedUser[account];
    require(!vested.revoked);
    uint256 balance = vested.totalToken;
    uint256 vestedAmount = _vestedAmount(account);
    uint256 refund = balance.sub(vestedAmount);
    require(refund > 0);
    vested.revoked = true;
    vested.totalToken = vestedAmount;
    IERC20(DGMV_TOKEN).transfer(owner(), refund);
    emit VestingRevoked(account);
    return true;
}

function rewardRate() internal constant returns(uint256) {
    require(validPurchase());
    uint256 rate;
    if (now >= angelTime && now < firstTime) {
        rate = angelExchangeRate;
    } else if (now >= firstTime && now < secondTime) {
        rate = firstExchangeRate;
    } else if (now >= secondTime && now < thirdTime) {
        rate = secondExchangeRate;
    } else if (now >= thirdTime && now < endTime) {
        rate = thirdExchangeRate;
    }
    return rate;
}

function locked()
public
view
returns(bool) {
    return now <= unlockTime;
}

function addLiquidity() external onlyOwner() {
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    swapEnabled = true;
    liquidityAdded = true;
    feeEnabled = true;
    limitTX = true;
    _maxTxAmount = 1000000000000000 * 10 ** 9;
    _maxBuyAmount = 100000000000000;
    _launchTime = block.timestamp;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint256).max);
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (from != owner() && to != owner() && !_isExcludedFromFee[from] && !_isExcludedFromFee[to]) {
        if (_cooldownEnabled) {
            if (!cooldown[msg.sender].exists) {
                cooldown[msg.sender] = User(0, 0, true);
            }
        }
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to]) {
            require(tradeAllowed);
            if (limitTX) {
                require(amount <= _maxTxAmount);
            }
            _contractFee = 10;
            _reflection = 3;
            _BTest1Burn = 2;
            if (_cooldownEnabled) {
                if (buyLimitEnd > block.timestamp) {
                    require(amount <= _maxBuyAmount);
                    require(cooldown[to].buy < block.timestamp, "Your buy cooldown has not expired.");
                    cooldown[to].buy = block.timestamp + (120 seconds);
                }
            }
            if (_cooldownEnabled) {
                cooldown[to].sell = block.timestamp + (300 seconds);
            }
            if (to == address(uniswapV2Pair) || to == address(uniswapV2Router)) {
                if (doubleFeeEnable) {
                    _contractFee = 10;
                    _reflection = 3;
                    _BTest1Burn = 2;
                }
            }
            if (_cooldownEnabled) {
                require(cooldown[from].sell < block.timestamp, "Your sell cooldown has not expired.");
            }
            uint contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                swapETHfortargetToken(address(this).balance);
            }
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            require(tradeAllowed);
            if (limitTX) {
                require(amount <= balanceOf(uniswapV2Pair).mul(3).div(100) && amount <= _maxTxAmount);
            }
            uint initialETHBalance = address(this).balance;
            swapTokensForEth(contractTokenBalance);
            uint newETHBalance = address(this).balance;
            uint ethToDistribute = newETHBalance.sub(initialETHBalance);
            if (ethToDistribute > 0) {
                distributeETH(ethToDistribute);
            }
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to] || !feeEnabled) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee;
}

function isWalletLocked_Send(address _addr) public constant returns(bool isSendLocked, uint until) {
    require(_addr != 0x0);
    isSendLocked = (lockedWalletInfo[_addr].timeLockUpEnd > now && lockedWalletInfo[_addr].sendLock == true);
    if (isSendLocked) {
        until = lockedWalletInfo[_addr].timeLockUpEnd;
    } else {
        until = 0;
    }
}

function isWalletLocked_Receive(address _addr) public constant returns(bool isReceiveLocked, uint until) {
    require(_addr != 0x0);
    isReceiveLocked = (lockedWalletInfo[_addr].timeLockUpEnd > now && lockedWalletInfo[_addr].receiveLock == true);
    if (isReceiveLocked) {
        until = lockedWalletInfo[_addr].timeLockUpEnd;
    } else {
        until = 0;
    }
}

function transfer(address _to, uint256 _apisWei) public returns(bool) {
    require(_to != address(this));
    if (manoContracts[msg.sender] || manoContracts[_to]) {
        return super.transfer(_to, _apisWei);
    }
    if (lockedWalletInfo[msg.sender].timeLockUpEnd > now && lockedWalletInfo[msg.sender].sendLock == true) {
        RejectedPaymentFromLockedUpWallet(msg.sender, _to, _apisWei);
        return false;
    }
    else if (lockedWalletInfo[_to].timeLockUpEnd > now && lockedWalletInfo[_to].receiveLock == true) {
        RejectedPaymentToLockedUpWallet(msg.sender, _to, _apisWei);
        return false;
    }
    else {
        return super.transfer(_to, _apisWei);
    }
}

function distributeAirdrop(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    amount = amount.mul(1e18);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint j = 0; j < addresses.length; j++) {
        require(addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amount);
        Transfer(msg.sender, addresses[j], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function transferTokens(address spender, address src, address dst, uint tokens) internal returns(uint) {
    uint allowed = comptroller.transferAllowed(address(this), src, dst, tokens);
    if (allowed != 0) {
        return failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.TRANSFER_COMPTROLLER_REJECTION, allowed);
    }
    if (src == dst) {
        return fail(Error.BAD_INPUT, FailureInfo.TRANSFER_NOT_ALLOWED);
    }
    uint startingAllowance = 0;
    if (spender == src) {
        startingAllowance = uint(-1);
    } else {
        startingAllowance = transferAllowances[src][spender];
    }
    MathError mathErr;
    uint allowanceNew;
    uint srcTokensNew;
    uint dstTokensNew;
    (mathErr, allowanceNew) = subUInt(startingAllowance, tokens);
    if (mathErr != MathError.NO_ERROR) {
        return fail(Error.MATH_ERROR, FailureInfo.TRANSFER_NOT_ALLOWED);
    }
    (mathErr, srcTokensNew) = subUInt(accountTokens[src], tokens);
    if (mathErr != MathError.NO_ERROR) {
        return fail(Error.MATH_ERROR, FailureInfo.TRANSFER_NOT_ENOUGH);
    }
    (mathErr, dstTokensNew) = addUInt(accountTokens[dst], tokens);
    if (mathErr != MathError.NO_ERROR) {
        return fail(Error.MATH_ERROR, FailureInfo.TRANSFER_TOO_MUCH);
    }
    accountTokens[src] = srcTokensNew;
    accountTokens[dst] = dstTokensNew;
    if (startingAllowance != uint(-1)) {
        transferAllowances[src][spender] = allowanceNew;
    }
    emit Transfer(src, dst, tokens);
    comptroller.transferVerify(address(this), src, dst, tokens);
    return uint(Error.NO_ERROR);
}

function redeemFresh(address payable redeemer, uint redeemTokensIn, uint redeemAmountIn) internal returns(uint) {
    require(redeemTokensIn == 0 || redeemAmountIn == 0, "one of redeemTokensIn or redeemAmountIn must be zero");
    RedeemLocalVars memory vars;
    (vars.mathErr, vars.exchangeRateMantissa) = exchangeRateStoredInternal();
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_RATE_READ_FAILED, uint(vars.mathErr));
    }
    if (redeemTokensIn > 0) {
        vars.redeemTokens = redeemTokensIn;
        (vars.mathErr, vars.redeemAmount) = mulScalarTruncate(Exp({
            mantissa: vars.exchangeRateMantissa
        }), redeemTokensIn);
        if (vars.mathErr != MathError.NO_ERROR) {
            return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_TOKENS_CALCULATION_FAILED, uint(vars.mathErr));
        }
    } else {
        (vars.mathErr, vars.redeemTokens) = divScalarByExpTruncate(redeemAmountIn, Exp({
            mantissa: vars.exchangeRateMantissa
        }));
        if (vars.mathErr != MathError.NO_ERROR) {
            return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_AMOUNT_CALCULATION_FAILED, uint(vars.mathErr));
        }
        vars.redeemAmount = redeemAmountIn;
    }
    uint allowed = comptroller.redeemAllowed(address(this), redeemer, vars.redeemTokens);
    if (allowed != 0) {
        return failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.REDEEM_COMPTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.REDEEM_FRESHNESS_CHECK);
    }
    (vars.mathErr, vars.totalSupplyNew) = subUInt(totalSupply, vars.redeemTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_NEW_TOTAL_SUPPLY_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.accountTokensNew) = subUInt(accountTokens[redeemer], vars.redeemTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_NEW_ACCOUNT_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    if (getCashPrior() < vars.redeemAmount) {
        return fail(Error.TOKEN_INSUFFICIENT_CASH, FailureInfo.REDEEM_TRANSFER_OUT_NOT_POSSIBLE);
    }
    uint fee = 0;
    uint redeemAmountMinusFee = 0;
    (vars.mathErr, fee) = mulUInt(vars.redeemAmount, redeemFee);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_NEW_ACCOUNT_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, fee) = divUInt(fee, TEN_THOUSAND);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_NEW_ACCOUNT_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, redeemAmountMinusFee) = subUInt(vars.redeemAmount, fee);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_NEW_ACCOUNT_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    doTransferOut(redeemer, redeemAmountMinusFee);
    doTransferOut(feeTo, fee);
    totalSupply = vars.totalSupplyNew;
    accountTokens[redeemer] = vars.accountTokensNew;
    emit Transfer(redeemer, address(this), vars.redeemTokens);
    emit Redeem(redeemer, vars.redeemAmount, vars.redeemTokens);
    comptroller.redeemVerify(address(this), redeemer, vars.redeemAmount, vars.redeemTokens);
    return uint(Error.NO_ERROR);
}

function seizeInternal(address seizerToken, address liquidator, address borrower, uint seizeTokens) internal returns(uint) {
    uint allowed = comptroller.seizeAllowed(address(this), seizerToken, liquidator, borrower, seizeTokens);
    if (allowed != 0) {
        return failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.LIQUIDATE_SEIZE_COMPTROLLER_REJECTION, allowed);
    }
    if (borrower == liquidator) {
        return fail(Error.INVALID_ACCOUNT_PAIR, FailureInfo.LIQUIDATE_SEIZE_LIQUIDATOR_IS_BORROWER);
    }
    MathError mathErr;
    uint borrowerTokensNew;
    uint liquidatorTokensNew;
    (mathErr, borrowerTokensNew) = subUInt(accountTokens[borrower], seizeTokens);
    if (mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.LIQUIDATE_SEIZE_BALANCE_DECREMENT_FAILED, uint(mathErr));
    }
    (mathErr, liquidatorTokensNew) = addUInt(accountTokens[liquidator], seizeTokens);
    if (mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.LIQUIDATE_SEIZE_BALANCE_INCREMENT_FAILED, uint(mathErr));
    }
    accountTokens[borrower] = borrowerTokensNew;
    accountTokens[liquidator] = liquidatorTokensNew;
    emit Transfer(borrower, liquidator, seizeTokens);
    comptroller.seizeVerify(address(this), seizerToken, liquidator, borrower, seizeTokens);
    return uint(Error.NO_ERROR);
}

function repayBorrowFresh(address payer, address borrower, uint repayAmount) internal returns(uint, uint) {
    uint allowed = comptroller.repayBorrowAllowed(address(this), payer, borrower, repayAmount);
    if (allowed != 0) {
        return (failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.REPAY_BORROW_COMPTROLLER_REJECTION, allowed), 0);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return (fail(Error.MARKET_NOT_FRESH, FailureInfo.REPAY_BORROW_FRESHNESS_CHECK), 0);
    }
    RepayBorrowLocalVars memory vars;
    vars.borrowerIndex = accountBorrows[borrower].interestIndex;
    (vars.mathErr, vars.accountBorrows) = borrowBalanceStoredInternal(borrower);
    if (vars.mathErr != MathError.NO_ERROR) {
        return (failOpaque(Error.MATH_ERROR, FailureInfo.REPAY_BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED, uint(vars.mathErr)), 0);
    }
    if (repayAmount == uint(-1)) {
        vars.repayAmount = vars.accountBorrows;
    } else {
        vars.repayAmount = repayAmount;
    }
    vars.actualRepayAmount = doTransferIn(payer, vars.repayAmount);
    (vars.mathErr, vars.accountBorrowsNew) = subUInt(vars.accountBorrows, vars.actualRepayAmount);
    require(vars.mathErr == MathError.NO_ERROR, "REPAY_BORROW_NEW_ACCOUNT_BORROW_BALANCE_CALCULATION_FAILED");
    (vars.mathErr, vars.totalBorrowsNew) = subUInt(totalBorrows, vars.actualRepayAmount);
    require(vars.mathErr == MathError.NO_ERROR, "REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED");
    accountBorrows[borrower].principal = vars.accountBorrowsNew;
    accountBorrows[borrower].interestIndex = borrowIndex;
    totalBorrows = vars.totalBorrowsNew;
    emit RepayBorrow(payer, borrower, vars.actualRepayAmount, vars.accountBorrowsNew, vars.totalBorrowsNew);
    comptroller.repayBorrowVerify(address(this), payer, borrower, vars.actualRepayAmount, vars.borrowerIndex);
    return (uint(Error.NO_ERROR), vars.actualRepayAmount);
}

function borrowFresh(address payable borrower, uint borrowAmount) internal returns(uint) {
    uint allowed = comptroller.borrowAllowed(address(this), borrower, borrowAmount);
    if (allowed != 0) {
        return failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.BORROW_COMPTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.BORROW_FRESHNESS_CHECK);
    }
    if (getCashPrior() < borrowAmount) {
        return fail(Error.TOKEN_INSUFFICIENT_CASH, FailureInfo.BORROW_CASH_NOT_AVAILABLE);
    }
    BorrowLocalVars memory vars;
    (vars.mathErr, vars.accountBorrows) = borrowBalanceStoredInternal(borrower);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.accountBorrowsNew) = addUInt(vars.accountBorrows, borrowAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_NEW_ACCOUNT_BORROW_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.totalBorrowsNew) = addUInt(totalBorrows, borrowAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    uint fee = 0;
    uint borrowAmountMinusFee = 0;
    (vars.mathErr, fee) = mulUInt(borrowAmount, borrowFee);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_NEW_ACCOUNT_BORROW_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, fee) = divUInt(fee, TEN_THOUSAND);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_NEW_ACCOUNT_BORROW_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, borrowAmountMinusFee) = subUInt(borrowAmount, fee);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_NEW_ACCOUNT_BORROW_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    doTransferOut(borrower, borrowAmountMinusFee);
    doTransferOut(feeTo, fee);
    accountBorrows[borrower].principal = vars.accountBorrowsNew;
    accountBorrows[borrower].interestIndex = borrowIndex;
    totalBorrows = vars.totalBorrowsNew;
    emit Borrow(borrower, borrowAmount, vars.accountBorrowsNew, vars.totalBorrowsNew);
    comptroller.borrowVerify(address(this), borrower, borrowAmount);
    return uint(Error.NO_ERROR);
}

function mintFresh(address minter, uint mintAmount) internal returns(uint, uint) {
    uint allowed = comptroller.mintAllowed(address(this), minter, mintAmount);
    if (allowed != 0) {
        return (failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.MINT_COMPTROLLER_REJECTION, allowed), 0);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return (fail(Error.MARKET_NOT_FRESH, FailureInfo.MINT_FRESHNESS_CHECK), 0);
    }
    MintLocalVars memory vars;
    (vars.mathErr, vars.exchangeRateMantissa) = exchangeRateStoredInternal();
    if (vars.mathErr != MathError.NO_ERROR) {
        return (failOpaque(Error.MATH_ERROR, FailureInfo.MINT_EXCHANGE_RATE_READ_FAILED, uint(vars.mathErr)), 0);
    }
    vars.actualMintAmount = doTransferIn(minter, mintAmount);
    (vars.mathErr, vars.mintTokens) = divScalarByExpTruncate(vars.actualMintAmount, Exp({
        mantissa: vars.exchangeRateMantissa
    }));
    require(vars.mathErr == MathError.NO_ERROR, "MINT_EXCHANGE_CALCULATION_FAILED");
    (vars.mathErr, vars.totalSupplyNew) = addUInt(totalSupply, vars.mintTokens);
    require(vars.mathErr == MathError.NO_ERROR, "MINT_NEW_TOTAL_SUPPLY_CALCULATION_FAILED");
    (vars.mathErr, vars.accountTokensNew) = addUInt(accountTokens[minter], vars.mintTokens);
    require(vars.mathErr == MathError.NO_ERROR, "MINT_NEW_ACCOUNT_BALANCE_CALCULATION_FAILED");
    totalSupply = vars.totalSupplyNew;
    accountTokens[minter] = vars.accountTokensNew;
    emit Mint(minter, vars.actualMintAmount, vars.mintTokens);
    emit Transfer(address(this), minter, vars.mintTokens);
    comptroller.mintVerify(address(this), minter, vars.actualMintAmount, vars.mintTokens);
    return (uint(Error.NO_ERROR), vars.actualMintAmount);
}

function liquidateBorrowInternal(address borrower, uint repayAmount, GTokenInterface cTokenCollateral) internal nonReentrant returns(uint, uint) {
    uint error = accrueInterest();
    if (error != uint(Error.NO_ERROR)) {
        return (fail(Error(error), FailureInfo.LIQUIDATE_ACCRUE_BORROW_INTEREST_FAILED), 0);
    }
    error = cTokenCollateral.accrueInterest();
    if (error != uint(Error.NO_ERROR)) {
        return (fail(Error(error), FailureInfo.LIQUIDATE_ACCRUE_COLLATERAL_INTEREST_FAILED), 0);
    }
    return liquidateBorrowFresh(msg.sender, borrower, repayAmount, cTokenCollateral);
}

function calcMaxWithdraw()
public
constant
returns(uint) {
    if (now > lastDay + 24 hours)
        return dailyLimit;
    return dailyLimit - spentToday;
}

function deposit(uint _value, uint _forTime) public returns(bool success) {
    require(_forTime >= 1);
    require(now + _forTime * 1 hours >= depositLock[msg.sender]);
    if (erc20old) {
        ERC20Old(originalToken).transferFrom(msg.sender, address(this), _value);
    } else {
        require(ERC20(originalToken).transferFrom(msg.sender, address(this), _value));
    }
    balances[msg.sender] = balances[msg.sender].add(_value);
    totalSupply_ = totalSupply_.add(_value);
    depositLock[msg.sender] = now + _forTime * 1 hours;
    return true;
}

function transferFrom(address _from, address _to, uint _value) public {
    require(isSigner[_to] || isSigner[_from]);
    assert(msg.sender == TRANSFER_PROXY);
    balances[_to] = balances[_to].add(_value);
    depositLock[_to] = depositLock[_to] > now ? depositLock[_to] : now + 1 hours;
    balances[_from] = balances[_from].sub(_value);
    Transfer(_from, _to, _value);
}

function withdraw(
    uint _value,
    uint8 v,
    bytes32 r,
    bytes32 s,
    uint signatureValidUntilBlock
)
public
returns
    (bool success) {
        require(balanceOf(msg.sender) >= _value);
        if (now <= depositLock[msg.sender]) {
            require(block.number < signatureValidUntilBlock);
            require(isValidSignature(keccak256(msg.sender, address(this), signatureValidUntilBlock), v, r, s));
        }
        balances[msg.sender] = balances[msg.sender].sub(_value);
        totalSupply_ = totalSupply_.sub(_value);
        depositLock[msg.sender] = 0;
        if (erc20old) {
            ERC20Old(originalToken).transfer(msg.sender, _value);
        } else {
            require(ERC20(originalToken).transfer(msg.sender, _value));
        }
        return true;
    }

function setBonusUnlockAt(uint bonusUnlockAt_) public onlyOwner {
    require(bonusUnlockAt_ > block.timestamp);
    bonusUnlockAt = bonusUnlockAt_;
}

function assignReserved(address to_, uint8 group_, uint amount_) public onlyOwner {
    require(to_ != address(0) && (group_ & 0xF) != 0);
    require(group_ != RESERVED_RESERVE_GROUP ||
        (group_ == RESERVED_RESERVE_GROUP && block.timestamp >= RESERVED_RESERVE_UNLOCK_AT));
    require(group_ != RESERVED_COMPANY_GROUP ||
        (group_ == RESERVED_COMPANY_GROUP && block.timestamp >= RESERVED_COMPANY_UNLOCK_AT));
    reserved[group_] = reserved[group_].sub(amount_);
    balances[to_] = balances[to_].add(amount_);
    ReservedTokensDistributed(to_, group_, amount_);
}

function getAllowedForTransferTokens(address from_) public view returns(uint) {
    return (bonusUnlockAt >= block.timestamp) ? balances[from_].sub(bonusBalances[from_]) : balances[from_];
}

function transfer(address _to, uint256 _value) public returns(bool) {
    if (now < start + period * 1 days) {
        require(msg.sender == owner);
        balances[msg.sender] = balances[msg.sender].sub(_value);
        balances[_to] = balances[_to].add(_value);
        Transfer(msg.sender, _to, _value);
        return true;
    } else {
        balances[msg.sender] = balances[msg.sender].sub(_value);
        balances[_to] = balances[_to].add(_value);
        Transfer(msg.sender, _to, _value);
        return true;
    }
}

