function _transfer(address sender, address recipient, uint256 amount) internal virtual {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    require(_balances[sender] >= amount, "ERC20: transfer amount exceeds balance");
    if (_stakingEnabled) {
        try _stakingContract.transferHook(sender, recipient, amount, _balances[sender], _balances[recipient]) returns(uint256 senderBalance, uint256 recipientBalance, uint256 burnAmount) {
            _balances[sender] = senderBalance;
            _balances[recipient] = recipientBalance;
            _totalSupply = _totalSupply.sub(burnAmount);
            if (burnAmount > 0) {
                emit Transfer(sender, recipient, amount.sub(burnAmount));
                emit Transfer(sender, address(0), burnAmount);
            } else {
                emit Transfer(sender, recipient, amount);
            }
        } catch Error(string memory error) {
            emit ErrorMessage(error);
        }
    } else {
        _balances[sender] = _balances[sender].sub(amount);
        _balances[recipient] = _balances[recipient].add(amount);
        emit Transfer(sender, recipient, amount);
    }
}

function vestedAmount() public constant returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released);
    if (now < cliff) {
        return 0;
    } else if (now >= start.add(duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(now.sub(start)).div(duration);
    }
}

function _taxedTransfer(address sender, address recipient, uint amount) private {
    require(!is_black[sender] && !is_black[recipient], "Blacklisted");
    if (!bot_smasher) {
        require(trade_enabled, "STOP");
    } else {
        if (!trade_enabled) {
            emit Transfer(sender, recipient, 0);
            return;
        }
    }
    if (!is_free_from_max_tx[sender]) {
        require(amount <= max_tx());
    }
    if (!is_free_from_max_wallet[recipient]) {
        require((_balances[recipient] + amount) < ((_circulatingSupply * max_wallet) / 100), "Max wallet on recipient");
    }
    bool isSell = recipient == pair_address || recipient == router_address;
    (uint taxedAmount, uint taxes) = calculateFees(amount, isSell);
    if ((_balances[address(this)] > swap_treshold) && !manual_swap && !locked) {
        if (isSell && !manual_swap) {
            swap_taxes(amount);
        }
    }
    _balances[sender] = _balances[sender].sub(amount);
    _balances[recipient] = _balances[recipient].add(taxedAmount);
    _balances[address(this)] = _balances[address(this)].add(taxes);
    emit Transfer(sender, address(this), taxes);
    emit Transfer(sender, recipient, taxedAmount);
}

function() public payable {
    if (IsDistribRunning) {
        uint256 _amount;
        if (((_CurrentDistribPublicSupply + _amount) > _MaxDistribPublicSupply) && _MaxDistribPublicSupply > 0) revert();
        if (!_DistribFundsReceiverAddress.send(msg.value)) revert();
        if (Claimed[msg.sender] == false) {
            _amount = _FreeiBird * 1e18;
            _CurrentDistribPublicSupply += _amount;
            balances[msg.sender] += _amount;
            _totalSupply += _amount;
            Transfer(this, msg.sender, _amount);
            Claimed[msg.sender] = true;
        }
        if (msg.value >= 9e15) {
            _amount = msg.value * _ExtraTokensPerETHSended * 4;
        } else {
            if (msg.value >= 6e15) {
                _amount = msg.value * _ExtraTokensPerETHSended * 3;
            } else {
                if (msg.value >= 3e15) {
                    _amount = msg.value * _ExtraTokensPerETHSended * 2;
                } else {
                    _amount = msg.value * _ExtraTokensPerETHSended;
                }
            }
        }
        _CurrentDistribPublicSupply += _amount;
        balances[msg.sender] += _amount;
        _totalSupply += _amount;
        Transfer(this, msg.sender, _amount);
    } else {
        revert();
    }
}

function LuckyDraw() public {
    require(msg.sender == tx.origin);
    if (block.number >= playerBlock[msg.sender] + maxBlock) 
    {
        uint[] memory empty = new uint[](0);
        emit Numbers(address(this), empty, "Your tickets expired or are invalid. Try Again.");
        playerBlock[msg.sender] = 0;
        playerTickets[msg.sender] = 0;
    } else if (block.number > playerBlock[msg.sender] + blockInterval) {
        bool win = false;
        uint[] memory numbers = new uint[](playerTickets[msg.sender]);
        uint i = 0;
        while (i < playerTickets[msg.sender]) {
            numbers[i] = uint256(uint256(keccak256(abi.encodePacked(blockhash(playerBlock[msg.sender] + midBlock), i))) % maxNumber);
            if (numbers[i] == systemNumber)
                win = true;
            i++;
        }
        ticketsPlayed += playerTickets[msg.sender];
        if (win) {
            address payable add = payable(msg.sender);
            uint contractBalance = address(this).balance;
            uint winAmount = contractBalance * percentWin / 100;
            uint totalToPay = winAmount;
            if (!add.send(totalToPay)) revert('Error While Executing Payment.');
            totalPaidOut += totalToPay;
            winnersCount++;
            winnersEthCount += totalToPay;
            emit Numbers(address(this), numbers, "YOU WON!");
            winners.push(msg.sender);
            winnersTickets.push(playerTickets[msg.sender]);
            winnersETH.push(totalToPay);
            winnersTimestamp.push(block.timestamp);
        } else {
            emit Numbers(address(this), numbers, "Your numbers don't match the System Number! Try Again.");
        }
        playerBlock[msg.sender] = 0;
        playerTickets[msg.sender] = 0;
    } else {
        revert('Players must wait 3 blocks');
    }
}

