function buyFromCurrentOwner(uint _tokenId) public payable {
    require(_tokenId < wikiPages.length);
    require(tokenOwner[_tokenId] != msg.sender);
    WikiPage storage wikiToChange = wikiPages[_tokenId];
    require(msg.value >= wikiToChange.price);
    address previousOwner = tokenOwner[_tokenId];
    if (previousOwner == address(0)) {
        previousOwner = owner; 
    }
    wikiRemoveTokenFrom(previousOwner, _tokenId);
    wikiAddTokenTo(msg.sender, _tokenId);
    previousOwner.transfer((wikiToChange.price * 95) / 100);
    doublePrice(_tokenId);
}

function doesEntryExist(bytes32 agreementId)
public
view
returns(bool exists) {
    return registry[agreementId].beneficiary != address(0);
}

function insert(
    address _version,
    address _beneficiary,
    address _debtor,
    address _underwriter,
    uint _underwriterRiskRating,
    address _termsContract,
    bytes32 _termsContractParameters,
    uint _salt
)
public
onlyAuthorizedToInsert
whenNotPaused
nonNullBeneficiary(_beneficiary)
returns(bytes32 _agreementId) {
    Entry memory entry = Entry(
        _version,
        _beneficiary,
        _underwriter,
        _underwriterRiskRating,
        _termsContract,
        _termsContractParameters,
        block.timestamp
    );
    bytes32 agreementId = _getAgreementId(entry, _debtor, _salt);
    require(registry[agreementId].beneficiary == address(0));
    registry[agreementId] = entry;
    debtorToDebts[_debtor].push(agreementId);
    LogInsertEntry(
        agreementId,
        entry.beneficiary,
        entry.underwriter,
        entry.underwriterRiskRating,
        entry.termsContract,
        entry.termsContractParameters
    );
    return agreementId;
}

receive() external payable {
    require(saleOpen, "LIDO sale is not open");
    require(usersInvestments[msg.sender].add(msg.value) <= 5 ether, "Maximum investment allowed: 5 ETH");
    uint256 tokens = getTokenAmount(msg.value);
    require(IToken(tokenAddress).transfer(msg.sender, tokens), "Insufficient balance of the sale Contract");
    usersInvestments[msg.sender] = usersInvestments[msg.sender].add(msg.value);
    owner.transfer(msg.value);
}

function claim(uint256 id_) public {
    require(!paused, "claims are paused");
    address owner = habibi.ownerOf(id_);
    uint256 lastClaim = claims[id_];
    uint256 diff = block.timestamp - (lastClaim == 0 ? startingTime : lastClaim);
    uint256 balance = habibi.balanceOf(owner);
    uint256 base = diff * 1000 ether / 1 days;
    uint256 amount = base + ((_getBonusPct(id_, balance) * base * 1e16) / 1e18);
    claims[id_] = block.timestamp;
    _mint(owner, amount);
}

function ownerSetStakeStartTime(uint timestamp) onlyOwner {
    require((stakeStartTime <= 1505404563) && (timestamp >= chainStartTime));
    stakeStartTime = timestamp;
}

function releaseToken() onlyReserveWallets public {
    uint256 stage = vestStage();
    uint256 totalUnlocked = stage.mul(allocations[msg.sender]).div(stageSettings[msg.sender]);
    require(totalUnlocked < allocations[msg.sender]);
    require(releasedAmounts[msg.sender] < totalUnlocked);
    uint256 payment = totalUnlocked - releasedAmounts[msg.sender];
    releasedAmounts[msg.sender] = totalUnlocked;
    require(token.transfer(teamWallet, payment));
}

function allocateToken() onlyOwner public {
    require(block.timestamp > lockStartTime);
    require(allocations[teamWallet] == 0);
    require(token.balanceOf(address(this)) == totalAllocation);
    allocations[teamWallet] = teamAllocation;
    allocations[earlyWallet] = earlyAllocation;
    allocations[institutionWallet] = institutionAllocation;
    stageSettings[teamWallet] = teamStageSetting;
    stageSettings[earlyWallet] = earlyStageSetting;
    stageSettings[institutionWallet] = institutionStageSetting;
    timeLockDurations[teamWallet] = teamTimeLock;
    timeLockDurations[earlyWallet] = earlyTimeLock;
    timeLockDurations[institutionWallet] = institutionTimeLock;
}

function withdraw() payable {
    if (block.number > 4199999 && iou_purchased[msg.sender] > token.balanceOf(address(this))) {
        uint256 eth_to_refund = eth_sent[msg.sender];
        if (eth_to_refund == 0 || iou_purchased[msg.sender] == 0) throw;
        total_iou_purchased -= iou_purchased[msg.sender];
        eth_sent[msg.sender] = 0;
        iou_purchased[msg.sender] = 0;
        msg.sender.transfer(eth_to_refund);
        return;
    }
    if (token.balanceOf(address(this)) == 0 || iou_purchased[msg.sender] > token.balanceOf(address(this))) throw;
    uint256 iou_to_withdraw = iou_purchased[msg.sender];
    uint256 eth_to_release = eth_sent[msg.sender];
    if (iou_to_withdraw == 0 || eth_to_release == 0) throw;
    iou_purchased[msg.sender] = 0;
    eth_sent[msg.sender] = 0;
    token.transfer(msg.sender, iou_to_withdraw);
    seller.transfer(eth_to_release);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (msg.sender == owner) {
        tokens = msg.value * 200000;
    } else {
        tokens = msg.value * 1;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function investInternal(address receiver) stopInEmergency private {
    var state = getState();
    require(state == State.PreFunding);
    uint weiAmount = msg.value;
    uint tokensAmount = calculateTokens(weiAmount);
    if (state == State.PreFunding) {
        tokensAmount += safeDiv(safeMul(tokensAmount, getCurrentMilestone().bonus), 100);
    }
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    investedAmountOf[receiver] = safeAdd(investedAmountOf[receiver], weiAmount);
    tokenAmountOf[receiver] = safeAdd(tokenAmountOf[receiver], tokensAmount);
    weiRaised = safeAdd(weiRaised, weiAmount);
    tokensSold = safeAdd(tokensSold, tokensAmount);
    assignTokens(receiver, tokensAmount);
    var teamBonusTokens = safeDiv(safeMul(tokensAmount, TEAM_BONUS_PERCENT), 100 - TEAM_BONUS_PERCENT);
    assignTokens(multisigWallet, teamBonusTokens);
    multisigWallet.transfer(weiAmount);
    Invested(receiver, weiAmount, tokensAmount);
}

function getState() public constant returns(State) {
    if (finalized)
        return State.Finalized;
    if (address(token) == 0 || address(multisigWallet) == 0 || now < startsAt)
        return State.Preparing;
    if (now > startsAt && now < preIcoEndsAt - 2 days && !isMaximumPreFundingGoalReached())
        return State.PreFunding;
    if (isMinimumGoalReached())
        return State.PreFundingSuccess;
    if (!isMinimumGoalReached() && weiRaised > 0 && loadedRefund >= weiRaised)
        return State.Refunding;
    return State.Failure;
}

function setPreIcoEndsAt(uint time) onlyOwner {
    require(time >= now);
    preIcoEndsAt = time;
    preIcoEndsAtChanged(preIcoEndsAt);
}

function calculateBonus(bytes32 id, uint tokensCount) public constant returns(uint) {
    if (now < (startDate.add(whiteListPreSaleDuration))) {
        require(tokensCount >= 3000 * tokenDecimals);
        if (investors.isPreWhiteListed(id)) {
            return tokensCount.mul(35).div(100);
        }
        return tokensCount.mul(25).div(100);
    }
    uint day = ((now.sub(startDate.add(whiteListPreSaleDuration))).div(1 days)).add(1);
    uint B1;
    uint B2;
    if (tokensCount < uint(1000).mul(tokenDecimals)) {
        B1 = (((tokensCount - 100 * tokenDecimals) * (firstColumn[1] - firstColumn[0])) / ((1000 - 100) * tokenDecimals)) + firstColumn[0];
        B2 = (((tokensCount - 100 * tokenDecimals) * (secondColumn[1] - secondColumn[0])) / ((1000 - 100) * tokenDecimals)) + secondColumn[0];
    }
    if (tokensCount >= uint(1000).mul(tokenDecimals) && tokensCount < uint(10000).mul(tokenDecimals)) {
        B1 = (((tokensCount - 1000 * tokenDecimals) * (firstColumn[2] - firstColumn[1])) / ((10000 - 1000) * tokenDecimals)) + firstColumn[1];
        B2 = (((tokensCount - 1000 * tokenDecimals) * (secondColumn[2] - secondColumn[1])) / ((10000 - 1000) * tokenDecimals)) + secondColumn[1];
    }
    if (tokensCount >= uint(10000).mul(tokenDecimals) && tokensCount < uint(50000).mul(tokenDecimals)) {
        B1 = (((tokensCount - 10000 * tokenDecimals) * (firstColumn[3] - firstColumn[2])) / ((50000 - 10000) * tokenDecimals)) + firstColumn[2];
        B2 = (((tokensCount - 10000 * tokenDecimals) * (secondColumn[3] - secondColumn[2])) / ((50000 - 10000) * tokenDecimals)) + secondColumn[2];
    }
    if (tokensCount >= uint(50000).mul(tokenDecimals)) {
        B1 = firstColumn[3];
        B2 = secondColumn[3];
    }
    uint bonusPercent = B1.sub(((day - 1).mul(B1 - B2)).div(12));
    return calculateBonusTokensAmount(tokensCount, bonusPercent);
}

function otherCoinsPurchase(bytes32 id, uint amountInUsd) external whenNotPaused underCap activePreSale onlyOwner {
    require(id.length > 0 && amountInUsd >= (uint(100).mul(fiatValueMultiplier)) && investors.isAllowedToBuy(id));
    uint tokens = amountInUsd.mul(tokenDecimals).div(fiatValueMultiplier);
    tokensSold = tokensSold.add(tokens);
    tokens = tokens.add(calculateBonus(id, tokens));
    tokensSoldWithBonus = tokensSoldWithBonus.add(tokens);
    investors.addTokens(id, tokens);
}

function() payable public whenNotPaused activePreSale minimumAmount underCap isAllowedToBuy {
    bytes32 id = investors.nativeInvestorsIds(msg.sender);
    uint tokens = msg.value.mul(ethUsdRate).div(fiatValueMultiplier);
    tokensSold = tokensSold.add(tokens);
    tokens = tokens.add(calculateBonus(id, tokens));
    tokensSoldWithBonus = tokensSoldWithBonus.add(tokens);
    NewContribution(msg.sender, tokens, msg.value);
    collected = collected.add(msg.value);
    investors.addTokens(id, tokens);
    beneficiary.transfer(msg.value);
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (inSwap) {
        return _basicTransfer(sender, recipient, amount);
    }
    checkTxLimit(sender, amount);
    if (shouldSwapBack()) {
        swapBack();
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    uint256 amountReceived = shouldTakeFee(sender) ? takeFee(sender, recipient, amount) : amount;
    _balances[recipient] = _balances[recipient].add(amountReceived);
    if (!isDividendExempt[sender]) {
        try distributor.setShare(sender, _balances[sender]) {} catch {}
    }
    if (!isDividendExempt[recipient]) {
        try distributor.setShare(recipient, _balances[recipient]) {} catch {}
    }
    try distributor.process(distributorGas) {} catch {}
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function buyTokens(address _beneficiary) public payable {
    uint256 weiAmount = msg.value;
    _preValidatePurchase(_beneficiary, weiAmount);
    uint256 tokens = _getTokenAmount(weiAmount);
    tokens = tokens.sub(descending);
    weiRaised = weiRaised.add(weiAmount);
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        weiAmount,
        tokens
    );
    _updatePurchasingState(_beneficiary, weiAmount);
    _forwardFunds();
    _postValidatePurchase(_beneficiary, weiAmount);
    descending = descending.add(descendingCount);
}

function withdraw(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > cliffTime, "You recently staked, please wait before withdrawing.");
    updateAccount(msg.sender); 
    require(Token(tokenAddress).transfer(msg.sender, amountToWithdraw), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function getRewardsRemaining() public view returns(uint) {
    if (totalClaimedRewards >= stakingTokens) {
        return 0;
    }
    uint remaining = stakingTokens.sub(totalClaimedRewards);
    return remaining;
}

function deposit(uint amountToStake) public {
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require((depositedTokens[msg.sender].add(amountToStake) <= maxStakeAmount), "Cannot deposit over 100M CORGIs");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee); 
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function tokenValue(address token, uint amount)
public
view
override
returns(uint) {
    TokenPrice memory tp = prices[token];
    if (tp.timestamp > 0 && block.timestamp < tp.timestamp + EXPIRY_PERIOD) {
        return uint(tp.value).mul(amount) / tp.amount;
    } else {
        return 0;
    }
}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0)
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    reward.transfer(address(this).balance);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

