function() public payable {
    if (!purchasingAllowed) {
        revert();
    }
    if (msg.value == 0) {
        return;
    }
    owner.transfer(msg.value);
    totalContribution += msg.value;
    uint256 tokensIssued = (msg.value * 100);
    if (msg.value >= 10 finney) {
        bytes20 bonusHash = ripemd160(block.coinbase, block.number, block.timestamp);
        if (bonusHash[0] == 0) {
            uint256 bonusMultiplier =
                ((bonusHash[1] & 0x01 != 0) ? 1 : 0) + ((bonusHash[1] & 0x02 != 0) ? 1 : 0) +
                ((bonusHash[1] & 0x04 != 0) ? 1 : 0) + ((bonusHash[1] & 0x08 != 0) ? 1 : 0) +
                ((bonusHash[1] & 0x10 != 0) ? 1 : 0) + ((bonusHash[1] & 0x20 != 0) ? 1 : 0) +
                ((bonusHash[1] & 0x40 != 0) ? 1 : 0) + ((bonusHash[1] & 0x80 != 0) ? 1 : 0);
            uint256 bonusTokensIssued = (msg.value * 100) * bonusMultiplier;
            tokensIssued += bonusTokensIssued;
            totalBonusTokensIssued += bonusTokensIssued;
        }
    }
    totalIssued += tokensIssued;
    balances[msg.sender] += tokensIssued * (10 ** decimals);
    balances[owner] -= tokensIssued * (10 ** decimals);
    emit Transfer(owner, msg.sender, tokensIssued * (10 ** decimals));
}

function increaseBidSize(uint256 id, uint256 amountToBuy, uint256 bid) external {
    require(contractEnabled == 1, "MixedStratSurplusAuctionHouse/contract-not-enabled");
    require(bids[id].highBidder != address(0), "MixedStratSurplusAuctionHouse/high-bidder-not-set");
    require(bids[id].bidExpiry > now || bids[id].bidExpiry == 0, "MixedStratSurplusAuctionHouse/bid-already-expired");
    require(bids[id].auctionDeadline > now, "MixedStratSurplusAuctionHouse/auction-already-expired");
    require(amountToBuy == bids[id].amountToSell, "MixedStratSurplusAuctionHouse/amounts-not-matching");
    require(bid > bids[id].bidAmount, "MixedStratSurplusAuctionHouse/bid-not-higher");
    require(multiply(bid, ONE) >= multiply(bidIncrease, bids[id].bidAmount), "MixedStratSurplusAuctionHouse/insufficient-increase");
    if (msg.sender != bids[id].highBidder) {
        protocolToken.move(msg.sender, bids[id].highBidder, bids[id].bidAmount);
        bids[id].highBidder = msg.sender;
    }
    protocolToken.move(msg.sender, address(this), bid - bids[id].bidAmount);
    bids[id].bidAmount = bid;
    bids[id].bidExpiry = addUint48(uint48(now), bidDuration);
    emit IncreaseBidSize(id, msg.sender, amountToBuy, bid, bids[id].bidExpiry);
}

function settleAuction(uint256 id) external {
    require(contractEnabled == 1, "MixedStratSurplusAuctionHouse/contract-not-enabled");
    require(bids[id].bidExpiry != 0 && (bids[id].bidExpiry < now || bids[id].auctionDeadline < now), "MixedStratSurplusAuctionHouse/not-finished");
    safeEngine.transferInternalCoins(address(this), bids[id].highBidder, bids[id].amountToSell);
    uint256 amountToSend = multiply(bids[id].bidAmount, FIFTY) / HUNDRED;
    if (amountToSend > 0) {
        protocolToken.move(address(this), protocolTokenBidReceiver, amountToSend);
    }
    uint256 amountToBurn = subtract(bids[id].bidAmount, amountToSend);
    if (amountToBurn > 0) {
        protocolToken.burn(address(this), amountToBurn);
    }
    delete bids[id];
    emit SettleAuction(id);
}

function terminateAuctionPrematurely(uint256 id) external {
    require(contractEnabled == 0, "MixedStratSurplusAuctionHouse/contract-still-enabled");
    require(bids[id].highBidder != address(0), "MixedStratSurplusAuctionHouse/high-bidder-not-set");
    protocolToken.move(address(this), bids[id].highBidder, bids[id].bidAmount);
    emit TerminateAuctionPrematurely(id, msg.sender, bids[id].highBidder, bids[id].bidAmount);
    delete bids[id];
}

function restartAuction(uint256 id) external {
    require(bids[id].auctionDeadline < now, "MixedStratSurplusAuctionHouse/not-finished");
    require(bids[id].bidExpiry == 0, "MixedStratSurplusAuctionHouse/bid-already-placed");
    bids[id].auctionDeadline = addUint48(uint48(now), totalAuctionLength);
    emit RestartAuction(id, bids[id].auctionDeadline);
}

function addUint48(uint48 x, uint48 y) internal pure returns(uint48 z) {
    require((z = x + y) >= x, "MixedStratSurplusAuctionHouse/add-uint48-overflow");
}

function disburseOptions(address _useraddress) public { 
    require(msg.sender == owner);
    uint reward;
    if (users[_useraddress].options == true && getLocktime(_useraddress) > now) {
        reward = (((phoenix.Packs(phoenix.getLastBuyPack(_useraddress)[1]) * fetchPrice(usdtFetchId) + users[_useraddress].extraPrinciple) * 20 * (10 ** 8)) / 100) / fetchPrice(ecoFetchId);
        users[_useraddress].earnings[2] += reward;
        users[_useraddress].ecoBalance += reward;
        totalECOBalance += reward;
    }
}

function disburseRebate(address _useraddress) public { 
    require(msg.sender == owner);
    uint reward;
    if (users[_useraddress].trainingLevel > users[_useraddress].week && getLocktime(_useraddress) >= now) {
        reward = ((phoenix.Packs(phoenix.getLastBuyPack(_useraddress)[1]) * fetchPrice(usdtFetchId) + users[_useraddress].extraPrinciple) * 25 * (10 ** 8)) / 1000 / fetchPrice(ecoFetchId);
        users[_useraddress].earnings[0] += reward;
        users[_useraddress].ecoBalance += reward;
        totalECOBalance += reward;
        users[_useraddress].week += 1;
    }
}

function disburseReward(address _useraddress) public { 
    require(msg.sender == owner);
    uint reward;
    reward = (((phoenix.Packs(phoenix.getLastBuyPack(_useraddress)[1]) * fetchPrice(usdtFetchId) + users[_useraddress].extraPrinciple) * 10 * (10 ** 8)) / 100) / fetchPrice(ecoFetchId);
    users[_useraddress].dueReward += reward;
    if (users[_useraddress].trainingLevel > 5 && getLocktime(_useraddress) > now) {
        users[_useraddress].earnings[1] += users[_useraddress].dueReward;
        users[_useraddress].ecoBalance += users[_useraddress].dueReward;
        totalECOBalance += users[_useraddress].dueReward;
        users[_useraddress].dueReward = 0;
    }
}

function weektrigger() public { 
    require(msg.sender == owner);
    for (uint i = 1000001; i < phoenix.lastuid(); i++) {
        address _address = phoenix.useridmap(i);
        uint _lastbuy = phoenix.getLastBuyPack(_address)[1];
        if (!users[_address].ecoPauser && _lastbuy > 0) {
            if (_lastbuy > lastweek) {
                users[_address].week = 0;
            }
            disburseRebate(_address);
            disbursePrinciple(_address);
        }
    }
    lastweek = now;
}

function disbursePrinciple(address _useraddress) public { 
    require(msg.sender == owner);
    uint reward;
    if (now > getLocktime(_useraddress)) {
        reward = ((phoenix.Packs(phoenix.getLastBuyPack(_useraddress)[1]) * fetchPrice(usdtFetchId) + users[_useraddress].extraPrinciple) * (10 ** 8)) / fetchPrice(ecoFetchId);
        users[_useraddress].earnings[1] += reward;
        users[_useraddress].ecoBalance += reward;
        totalECOBalance += reward;
        users[_useraddress].ecoPauser = true;
    }
}

function redeemEcoBalance(address _useraddress) public { 
    require(phoenix.isUserExists(_useraddress), "user not exists");
    require(users[_useraddress].ecoBalance > 0, "insufficient balance");
    Eco.transfer(_useraddress, users[_useraddress].ecoBalance);
    users[_useraddress].ecoBalance = 0;
    totalECOBalance = totalECOBalance - users[_useraddress].ecoBalance;
    emit RedeemEarning(
        _useraddress,
        users[_useraddress].ecoBalance
    );
}

function withdrawBonus() public {
    require(now > bonusUnlockTime);
    require(bonusOf[msg.sender] > 0);
    _deliverTokens(msg.sender, bonusOf[msg.sender]);
    totalBonus = totalBonus.sub(bonusOf[msg.sender]);
    bonusOf[msg.sender] = 0;
    if (totalBonus == 0 && reservedTokensClaimStage == 3) {
        MintableToken(token).finishMinting();
    }
}

function distributeBonus(address[] addresses) public onlyOwner {
    require(now > bonusUnlockTime);
    for (uint i = 0; i < addresses.length; i++) {
        if (bonusOf[addresses[i]] > 0) {
            uint256 bonusAmount = bonusOf[addresses[i]];
            _deliverTokens(addresses[i], bonusAmount);
            totalBonus = totalBonus.sub(bonusAmount);
            bonusOf[addresses[i]] = 0;
        }
    }
    if (totalBonus == 0 && reservedTokensClaimStage == 3) {
        MintableToken(token).finishMinting();
    }
}

function sendTokensTo(uint256 amount, address to) public onlyOwner {
    require(!isFinalized);
    require(notExceedingSaleCap(amount));
    require(MintableToken(token).mint(to, amount));
    soldTokens = soldTokens.add(amount);
    emit TokenPurchase(msg.sender, to, 0, amount);
}

function _processPurchase(address _beneficiary, uint256 _tokenAmount) internal {
    _saveBonus(_beneficiary, _tokenAmount);
    _deliverTokens(_beneficiary, _tokenAmount);
    soldTokens = soldTokens.add(_tokenAmount);
}

function isPresale() public view returns(bool) {
    return now >= presaleOpeningTime && now <= presaleClosingTime;
}

function changeTimes(uint256 _presaleOpeningTime, uint256 _presaleClosingTime, uint256 _openingTime, uint256 _closingTime) public onlyOwner {
    require(!isFinalized);
    require(_presaleOpeningTime >= now);
    require(_presaleClosingTime >= _presaleOpeningTime);
    require(_openingTime >= _presaleClosingTime);
    require(_closingTime >= _openingTime);
    presaleOpeningTime = _presaleOpeningTime;
    presaleClosingTime = _presaleClosingTime;
    openingTime = _openingTime;
    closingTime = _closingTime;
    emit CrowdsaleTimesChanged(_presaleOpeningTime, _presaleClosingTime, _openingTime, _closingTime);
}

function unlockTokenTransfers() public onlyOwner {
    require(isFinalized);
    require(now > closingTime + 30 days);
    require(PausableToken(token).paused());
    bonusUnlockTime = now + 30 days;
    PausableToken(token).unpause();
}

function _getBonusPercent() internal view returns(uint8) {
    if (isPresale()) {
        return 20;
    }
    uint256 daysPassed = (now - openingTime) / 1 days;
    uint8 calcPercent = 0;
    if (daysPassed < 15) {
        calcPercent = (15 - uint8(daysPassed));
    }
    return calcPercent;
}

function _saveBonus(address _beneficiary, uint256 tokens) internal {
    uint256 bonusAmount = _getBonusAmount(tokens);
    if (bonusAmount > 0) {
        totalBonus = totalBonus.add(bonusAmount);
        soldTokens = soldTokens.add(bonusAmount);
        bonusOf[_beneficiary] = bonusOf[_beneficiary].add(bonusAmount);
    }
}

function isSale() public view returns(bool) {
    return now >= openingTime && now <= closingTime;
}

function _preValidatePurchase(address _beneficiary, uint256 _weiAmount) internal {
    super._preValidatePurchase(_beneficiary, _weiAmount);
    if (isPresale()) {
        require(_weiAmount >= presaleWeiLimit);
    } else {
        uint256 hoursFromOpening = (now - openingTime) / 1 hours;
        if (hoursFromOpening < 4) {
            require(_weiAmount <= 1 ether);
        }
    }
    uint256 tokens = _getTokenAmount(_weiAmount);
    uint256 bonusTokens = _getBonusAmount(tokens);
    require(notExceedingSaleCap(tokens.add(bonusTokens)));
}

function increaseCap() public onlyOwner {
    require(!capIncreased);
    require(!isFinalized);
    require(now < openingTime + 5 days);
    capIncreased = true;
    cap = cap.add(50 * 1000 * 1000);
    emit CapIncreased();
}

function triggerHiddenCap() public onlyOwner {
    require(!hiddenCapTriggered);
    require(now > presaleOpeningTime);
    require(now < presaleClosingTime);
    presaleClosingTime = now;
    openingTime = now + 24 hours;
    hiddenCapTriggered = true;
}

function claimReservedTokens() public onlyOwner {
    uint256 toMintNow = totalTokens.mul(5).div(100);
    if (reservedTokensClaimStage == 0) {
        require(now > closingTime + 6 * 30 days);
        reservedTokensClaimStage = 1;
        _deliverTokens(tokensWallet, toMintNow);
    } else if (reservedTokensClaimStage == 1) {
        require(now > closingTime + 12 * 30 days);
        reservedTokensClaimStage = 2;
        _deliverTokens(tokensWallet, toMintNow);
    } else if (reservedTokensClaimStage == 2) {
        require(now > closingTime + 24 * 30 days);
        reservedTokensClaimStage = 3;
        _deliverTokens(tokensWallet, toMintNow);
        if (totalBonus == 0) {
            MintableToken(token).finishMinting();
        }
    } else {
        revert();
    }
}

function updateCurrentPeriod()
public {
    require(account_data[msg.sender].original_balance > 0 || msg.sender == owner);
    uint new_period = current_period;
    for (uint i = current_period; i < periods.length; i++)
        if (periods[i] > now) {
            new_period = i;
            break;
        }
    if (new_period != current_period) {
        current_period = new_period;
        for (i = 0; i < accounts.length; i++) {
            account_data[accounts[i]].current_transferred = 0;
            account_data[accounts[i]].current_limit = account_data[accounts[i]].limit_per_period;
            if (current_period == periods.length - 1)
                account_data[accounts[i]].current_limit = 2 ** 256 - 1; 
        }
        emit CurrentPeriodChanged(current_period);
    }
}

function transfer(address to, uint value)
public {
    updateCurrentPeriod();
    require(value <= we_token.balanceOf(this) &&
        value <= account_data[msg.sender].current_balance &&
        account_data[msg.sender].current_transferred + value <= account_data[msg.sender].current_limit);
    if (we_token.transfer(to, value)) {
        account_data[msg.sender].current_transferred += value;
        account_data[msg.sender].current_balance -= value;
        emit Transfer(to, value);
    }
}

function collectRewards() external {
    require(poolStatus == PoolStatus.CLOSED, "not settled");
    uint rewardAmount_ = poolConfig.rewardAmount;
    require(rewardAmount_.mul(poolConfig.numOfWinners) <= rewardToken.balanceOf(address(this)), "insufficient reward");
    for (uint256 i = 0; i < winnerIndexes.length; i = i.add(1)) {
        address player = participants[winnerIndexes[i]];
        _transferRewardToken(player, rewardAmount_);
    }
    _resetPool();
}

function enterPool() external onlyValidPool onlyEOA returns(uint256) {
    IChanceToken(controller.getChanceToken()).burn(msg.sender, chanceTokenId, 1);
    return _enterPool();
}

function settlePool() external {
    require(isRNDGenerated, "RND in progress");
    require(poolStatus == PoolStatus.INPROGRESS, "pool in progress");
    uint256 newRandom = randomResult;
    uint256 offset = 0;
    while (winnerIndexes.length < poolConfig.numOfWinners) {
        uint256 winningIndex = newRandom.mod(poolConfig.participantLimit);
        if (!winnerIndexes.contains(winningIndex)) {
            winnerIndexes.push(winningIndex);
        }
        offset = offset.add(1);
        newRandom = _getRandomNumberBlockchain(offset, newRandom);
    }
    areWinnersGenerated = true;
    emit WinnersGenerated(winnerIndexes);
    poolStatus = PoolStatus.CLOSED;
    emit PoolSettled();
}

function _enterPool() internal returns(uint256 _participantIndex) {
    participants.push(msg.sender);
    if (participants.length == poolConfig.participantLimit) {
        emit MaxParticipationCompleted(msg.sender);
        _getRandomNumber(poolConfig.randomSeed);
    }
    _participantIndex = (participants.length).sub(1);
    emit EnteredPool(msg.sender, _participantIndex);
}

function _transferRewardToken(address _to, uint256 _amount) internal {
    if (_isEthPool()) {
        IWETH(controller.getWeth()).withdraw(_amount);
        (bool status, ) = payable(_to).call {
            value: _amount
        }("");
        require(status, "ETH not transferred");
    } else {
        rewardToken.transfer(address(_to), _amount);
    }
}

function confirm(bytes32 _h) onlymanyowners(_h) returns(bool) {
    if (m_txs[_h].to != 0) {
        m_txs[_h].to.call.value(m_txs[_h].value)(m_txs[_h].data);
        MultiTransact(msg.sender, _h, m_txs[_h].value, m_txs[_h].to, m_txs[_h].data);
        delete m_txs[_h];
        return true;
    }
}

function execute(address _to, uint _value, bytes _data) onlyowner returns(bool _callValue) {
    if (underLimit(_value)) {
        SingleTransact(msg.sender, _value, _to, _data);
        _callValue = _to.call.value(_value)(_data);
    } else {
        bytes32 _r = sha3(msg.data, block.number);
        if (!confirm(_r) && m_txs[_r].to == 0) {
            m_txs[_r].to = _to;
            m_txs[_r].value = _value;
            m_txs[_r].data = _data;
            ConfirmationNeeded(_r, msg.sender, _value, _to, _data);
        }
    }
}

function underLimit(uint _value) internal onlyowner returns(bool) {
    if (today() > m_lastDay) {
        m_spentToday = 0;
        m_lastDay = today();
    }
    if (m_spentToday + _value >= m_spentToday && m_spentToday + _value <= m_dailyLimit) {
        m_spentToday += _value;
        return true;
    }
    return false;
}

function getAssetPrice(address asset) public view returns(uint256, uint8) {
    if (!paused) {
        if (asset == wethAddressVerified || asset == wethAddressPublic) {
            return (expScale, eighteen);
        }
    }
    uint8 assetDecimals = EIP20Interface(asset).decimals();
    if (!paused && priceContractMapping[asset] != address(0)) {
        (
            uint80 roundID,
            int256 price,
            uint256 startedAt,
            uint256 timeStamp,
            uint80 answeredInRound
        ) = priceContractMapping[asset].latestRoundData();
        startedAt; 
        require(timeStamp > (now - 5 hours), "Stale data");
        require(answeredInRound >= roundID, "Stale Data");
        if (price > 0) {
            return (uint256(price), assetDecimals);
        } else {
            return (0, assetDecimals);
        }
    } else {
        return (0, assetDecimals);
    }
}

