function Create(uint256 _chequeIdHash, uint256 _pinHash, uint32 _expiringPeriod) payable isActive returns(ResultCode) {
    bytes32 chequeIdHash = bytes32(_chequeIdHash);
    bytes32 pinHash = bytes32(_pinHash);
    uint chequeValue = 0;
    uint commissionFee = (msg.value / 1000) * commissionRate;
    if (commissionFee < minFee) {
        commissionFee = minFee;
    }
    if (msg.value < commissionFee) {
        msg.sender.transfer(msg.value);
        LogCreate(chequeIdHash, uint(ResultCode.ERROR_INVALID_AMOUNT), chequeValue);
        return ResultCode.ERROR_INVALID_AMOUNT;
    }
    chequeValue = msg.value - commissionFee;
    if (chequeValue < minChequeValue) {
        msg.sender.transfer(msg.value);
        LogCreate(chequeIdHash, uint(ResultCode.ERROR_MIN), chequeValue);
        return ResultCode.ERROR_MIN;
    }
    if (maxChequeValue > 0 && chequeValue > maxChequeValue) {
        msg.sender.transfer(msg.value);
        LogCreate(chequeIdHash, uint(ResultCode.ERROR_MAX), chequeValue);
        return ResultCode.ERROR_MAX;
    }
    if (items[chequeIdHash].status != Status.NONE && items[chequeIdHash].status != Status.USED) {
        msg.sender.transfer(msg.value);
        LogCreate(chequeIdHash, uint(ResultCode.ERROR_EXIST), chequeValue);
        return ResultCode.ERROR_EXIST;
    }
    totalCheque += 1;
    totalChequeValue += chequeValue;
    items[chequeIdHash] = Cheque({
        pinHash: pinHash,
        creator: msg.sender,
        status: Status.CREATED,
        value: chequeValue,
        createTime: now,
        expiringPeriod: _expiringPeriod,
        attempt: 0
    });
    LogCreate(chequeIdHash, uint(ResultCode.SUCCESS), chequeValue);
    return ResultCode.SUCCESS;
}

function RefundChequeByHash(uint256 _chequeIdHash) onlyModerators returns(ResultCode) {
    bytes32 chequeIdHash = bytes32(_chequeIdHash);
    Cheque cheque = items[chequeIdHash];
    if (cheque.status == Status.NONE) {
        LogRefundCheque(chequeIdHash, ResultCode.ERROR_NOT_EXIST);
        return ResultCode.ERROR_NOT_EXIST;
    }
    if (cheque.status == Status.USED) {
        LogRefundCheque(chequeIdHash, ResultCode.ERROR_USED);
        return ResultCode.ERROR_USED;
    }
    totalRedeemedCheque += 1;
    totalRedeemedValue += cheque.value;
    uint sendAmount = cheque.value;
    cheque.status = Status.USED;
    cheque.value = 0;
    cheque.creator.transfer(sendAmount);
    LogRefundCheque(chequeIdHash, ResultCode.SUCCESS);
    return ResultCode.SUCCESS;
}

function RefundChequeById(string _chequeId) onlyModerators returns(ResultCode) {
    bytes32 chequeIdHash = sha3(_chequeId);
    Cheque cheque = items[chequeIdHash];
    if (cheque.status == Status.NONE) {
        LogRefundCheque(chequeIdHash, ResultCode.ERROR_NOT_EXIST);
        return ResultCode.ERROR_NOT_EXIST;
    }
    if (cheque.status == Status.USED) {
        LogRefundCheque(chequeIdHash, ResultCode.ERROR_USED);
        return ResultCode.ERROR_USED;
    }
    totalRedeemedCheque += 1;
    totalRedeemedValue += cheque.value;
    uint sendAmount = cheque.value;
    cheque.status = Status.USED;
    cheque.value = 0;
    cheque.creator.transfer(sendAmount);
    LogRefundCheque(chequeIdHash, ResultCode.SUCCESS);
    return ResultCode.SUCCESS;
}

function Redeem(string _chequeId, string _pin, address _sendTo) payable returns(ResultCode) {
    bytes32 chequeIdHash = sha3(_chequeId);
    Cheque cheque = items[chequeIdHash];
    if (cheque.status == Status.NONE) {
        LogRedeem(chequeIdHash, ResultCode.ERROR_NOT_EXIST, 0, _sendTo);
        return ResultCode.ERROR_NOT_EXIST;
    }
    if (cheque.status == Status.USED) {
        LogRedeem(chequeIdHash, ResultCode.ERROR_USED, 0, _sendTo);
        return ResultCode.ERROR_USED;
    }
    if (msg.sender != cheque.creator) {
        if (cheque.status != Status.CREATED) {
            LogRedeem(chequeIdHash, ResultCode.ERROR_INVALID_STATUS, 0, _sendTo);
            return ResultCode.ERROR_INVALID_STATUS;
        }
        if (cheque.attempt > maxAttempt) {
            LogRedeem(chequeIdHash, ResultCode.ERROR_LOCKED, 0, _sendTo);
            return ResultCode.ERROR_LOCKED;
        }
        if (cheque.expiringPeriod > 0 && now > (cheque.createTime + cheque.expiringPeriod)) {
            LogRedeem(chequeIdHash, ResultCode.ERROR_EXPIRED, 0, _sendTo);
            return ResultCode.ERROR_EXPIRED;
        }
    }
    if (cheque.pinHash != sha3(_chequeId, _pin)) {
        cheque.attempt += 1;
        LogRedeem(chequeIdHash, ResultCode.ERROR_INVALID_STATUS, 0, _sendTo);
        return ResultCode.ERROR_INVALID_STATUS;
    }
    totalRedeemedCheque += 1;
    totalRedeemedValue += cheque.value;
    uint sendMount = cheque.value;
    cheque.status = Status.USED;
    cheque.value = 0;
    _sendTo.transfer(sendMount);
    LogRedeem(chequeIdHash, ResultCode.SUCCESS, sendMount, _sendTo);
    return ResultCode.SUCCESS;
}

function WithdrawEther(address _sendTo, uint _amount) onlyModerators returns(ResultCode) {
    uint currentProfit = this.balance - (totalChequeValue - totalRedeemedValue);
    if (_amount > currentProfit) {
        LogWithdrawEther(_sendTo, ResultCode.ERROR_INVALID_AMOUNT, 0);
        return ResultCode.ERROR_INVALID_AMOUNT;
    }
    _sendTo.transfer(_amount);
    LogWithdrawEther(_sendTo, ResultCode.SUCCESS, _amount);
    return ResultCode.SUCCESS;
}

function GetChequeInfo(string _chequeId) constant returns(Status, uint, uint, uint) {
    bytes32 hashChequeId = sha3(_chequeId);
    Cheque cheque = items[hashChequeId];
    if (cheque.status == Status.NONE)
        return (Status.NONE, 0, 0, 0);
    if (cheque.expiringPeriod > 0) {
        uint timeGap = now;
        if (timeGap > cheque.createTime)
            timeGap = timeGap - cheque.createTime;
        else
            timeGap = 0;
        if (cheque.expiringPeriod > timeGap)
            return (cheque.status, cheque.value, cheque.attempt, cheque.expiringPeriod - timeGap);
        else
            return (Status.EXPIRED, cheque.value, cheque.attempt, 0);
    }
    return (cheque.status, cheque.value, cheque.attempt, 0);
}

function GetChequeInfoByHash(uint256 _chequeIdHash) onlyModerators constant returns(Status, uint, uint, uint) {
    bytes32 chequeIdHash = bytes32(_chequeIdHash);
    Cheque cheque = items[chequeIdHash];
    if (cheque.status == Status.NONE)
        return (Status.NONE, 0, 0, 0);
    if (cheque.expiringPeriod > 0) {
        uint timeGap = now;
        if (timeGap > cheque.createTime)
            timeGap = timeGap - cheque.createTime;
        else
            timeGap = 0;
        if (cheque.expiringPeriod > timeGap)
            return (cheque.status, cheque.value, cheque.attempt, cheque.expiringPeriod - timeGap);
        else
            return (Status.EXPIRED, cheque.value, cheque.attempt, 0);
    }
    return (cheque.status, cheque.value, cheque.attempt, 0);
}

function triggerCutoff(address _recipient) public returns(uint8 result, uint256 distributionFound) {
    if (allocations[_recipient].cutoffEnabled == false) {
        if (msg.sender == allocations[_recipient].cutoffAdminAddress) {
            allocations[_recipient].cutoffEnabled = true;
            uint256 modifiedAllocation = allocations[_recipient].totalAllocated.sub(allocations[_recipient].cutoffTokenAmount);
            if (allocations[_recipient].amountClaimed < modifiedAllocation) {
                uint256 remainingAvailableDistribution = modifiedAllocation.sub(allocations[_recipient].amountClaimed);
                uint256 tokensToReturnToCore = allocations[_recipient].cutoffTokenAmount;
                addCutoffTokensToCore(tokensToReturnToCore);
                emit EVT_cutoffTriggered(_recipient, modifiedAllocation, allocations[_recipient].amountClaimed, remainingAvailableDistribution, tokensToReturnToCore);
                return (3, remainingAvailableDistribution);
            } else {
                uint256 overAllocatedDistribution = allocations[_recipient].amountClaimed.sub(modifiedAllocation);
                uint256 tokensToReturnToCore = allocations[_recipient].totalAllocated.sub(allocations[_recipient].amountClaimed);
                addCutoffTokensToCore(tokensToReturnToCore);
                emit EVT_cutoffTriggeredOverAllocated(_recipient, modifiedAllocation, allocations[_recipient].amountClaimed, overAllocatedDistribution, tokensToReturnToCore);
                return (2, overAllocatedDistribution);
            }
        } else {
            return (1, 0);
        }
    } else {
        return (0, 0);
    }
}

function addCutoffTokensToCore(uint256 _amount) internal {
    if (transferTokenMode == true) {
        IShyftKycContractRegistry kycContractRegistry = IShyftKycContractRegistry(kycContractRegistryAddress);
        IShyftKycContract kycContract = IShyftKycContract(kycContractRegistry.getContractAddressOfVersion(0));
        bool contractTxSuccess = kycContract.transfer(shyftCoreTokenAddress, _amount);
        if (contractTxSuccess == false) {
            revert();
        }
    } else {
        (bool nativeTxSuccess, ) = shyftCoreTokenAddress.call {
            value: _amount
        }("");
        if (nativeTxSuccess == false) {
            revert();
        }
    }
}

function getCurrentCycleNumber(address _recipient, uint256 _currentDistributionTime) public view returns(uint256 curCycle) {
    uint256 foundCycle = 0;
    distributionTable storage distTable = distributionHashToTableMapping[allocations[_recipient].distributionTableHash];
    if (distTable.cyclesArray[distTable.cyclesArray.length - 1].timePeriodEnd < _currentDistributionTime) {
        return distTable.cyclesArray.length - 1;
    } else {
        for (uint256 i = 0; i < distTable.cyclesArray.length; i++) {
            bool distributionCycleMatches = (distTable.cyclesArray[i].timePeriodStart < _currentDistributionTime &&
                distTable.cyclesArray[i].timePeriodEnd >= _currentDistributionTime);
            if (distributionCycleMatches == true) {
                foundCycle = i;
                break;
            }
        }
    }
    return foundCycle;
}

function calculateNewTotal(address _recipient, uint256 _timePeriodStart, uint256 _timePeriodEnd, int128 _percentTokens_fixedPoint, int128 _prevCyclesPercent, uint256 _referenceTime) internal view returns(uint256 result) {
    int128 curCyclePercent = ABDKMath64x64.divi(int256(((_referenceTime.sub(allocations[_recipient].endCliff).sub(_timePeriodStart)))), int256(_timePeriodEnd.sub(_timePeriodStart)));
    int128 totalPercentOfUsersTokens = ABDKMath64x64.add(_prevCyclesPercent, ABDKMath64x64.mul(_percentTokens_fixedPoint, curCyclePercent));
    uint256 tokensAllocated = allocations[_recipient].totalAllocated;
    if (allocations[_recipient].cutoffEnabled == true) {
        tokensAllocated = tokensAllocated.sub(allocations[_recipient].cutoffTokenAmount);
    }
    bytes16 quadFrom64x64TotalPercentOfUsersTokens = ABDKMathQuad.from64x64(totalPercentOfUsersTokens);
    uint256 newTotalClaimed = ABDKMathQuad.toUInt(ABDKMathQuad.mul(ABDKMathQuad.fromUInt(tokensAllocated), quadFrom64x64TotalPercentOfUsersTokens));
    return newTotalClaimed;
}

function setAllocation(address _recipient,
    uint256 _totalAllocated,
    uint256 _endCliffDays,
    uint256 _endVestingDays,
    uint256 _cutoffTokenAmount,
    address _cutoffAdminAddress,
    bytes32 _distributionTableHash) public returns(uint8 result) {
    require(msg.sender == owner);
    require(_recipient != address(0));
    require(allocations[_recipient].distributionTableHash == bytes32(0));
    require(_totalAllocated <= INITIAL_SUPPLY);
    require(_totalAllocated >= _cutoffTokenAmount);
    require(_endCliffDays <= _endVestingDays);
    Allocation storage a = allocations[_recipient];
    a.endCliff = startTime.add(_endCliffDays.mul(1 days));
    a.endVesting = startTime.add(_endVestingDays.mul(1 days));
    a.totalAllocated = _totalAllocated;
    a.cutoffTokenAmount = _cutoffTokenAmount;
    a.cutoffAdminAddress = _cutoffAdminAddress;
    a.distributionTableHash = _distributionTableHash;
    emit EVT_newAllocation(_recipient, _totalAllocated, _endCliffDays, _endVestingDays, _cutoffTokenAmount, _cutoffAdminAddress, _distributionTableHash);
    return 1;
}

function claimTokens(address _recipient) public returns(bool success, uint256 result, uint256 timeStamp) {
    uint256 tokensAllocated = allocations[_recipient].totalAllocated;
    if (allocations[_recipient].cutoffEnabled == true) {
        tokensAllocated = tokensAllocated.sub(allocations[_recipient].cutoffTokenAmount);
    }
    if (allocations[_recipient].amountClaimed >= tokensAllocated) {
        return (false, 3, 0);
    }
    if (block.timestamp < allocations[_recipient].endCliff) {
        return (false, 2, 0);
    }
    require(block.timestamp >= startTime);
    uint256 newTotalClaimed;
    if (allocations[_recipient].endVesting > block.timestamp) {
        (uint8 getTokensResult, uint256 tokensAvailable, , ) = getTokensAvailable(_recipient, block.timestamp);
        if (getTokensResult != 3) {
            if (getTokensResult == 2) {
                return (false, 1, 0);
            } else {
                return (false, 0, 0);
            }
        } else {
            newTotalClaimed = tokensAvailable;
        }
    } else {
        newTotalClaimed = tokensAllocated;
    }
    uint256 transferAmount = newTotalClaimed.sub(allocations[_recipient].amountClaimed);
    allocations[_recipient].amountClaimed = newTotalClaimed;
    totalClaimed = totalClaimed.add(transferAmount);
    if (transferTokenMode == true) {
        IShyftKycContractRegistry kycContractRegistry = IShyftKycContractRegistry(kycContractRegistryAddress);
        IShyftKycContract kycContract = IShyftKycContract(kycContractRegistry.getContractAddressOfVersion(0));
        bool contractTxSuccess = kycContract.transfer(_recipient, transferAmount);
        if (contractTxSuccess == false) {
            revert();
        }
    } else {
        (bool nativeTxSuccess, ) = _recipient.call {
            value: transferAmount
        }("");
        if (nativeTxSuccess == false) {
            revert();
        }
    }
    emit EVT_shyftClaimed(_recipient, transferAmount, newTotalClaimed, totalClaimed, block.timestamp);
    return (true, transferAmount, block.timestamp);
}

function getTokensAvailable(address _recipient, uint256 _referenceTime) public view returns(uint8 result, uint256 tokensTransferred, uint256 tokensReceived, uint256 currentCycleNumber) {
    if (_referenceTime > allocations[_recipient].endCliff) {
        uint256 tokensAllocated = allocations[_recipient].totalAllocated;
        if (allocations[_recipient].cutoffEnabled == true) {
            tokensAllocated = tokensAllocated.sub(allocations[_recipient].cutoffTokenAmount);
        }
        if (allocations[_recipient].amountClaimed < tokensAllocated) {
            uint256 newTotalClaimed;
            uint256 cycleNumber;
            if (_referenceTime > allocations[_recipient].endVesting) {
                newTotalClaimed = tokensAllocated.sub(allocations[_recipient].amountClaimed);
                distributionTable storage distTable = distributionHashToTableMapping[allocations[_recipient].distributionTableHash];
                cycleNumber = distTable.cyclesArray.length - 1;
            } else {
                cycleNumber = getCurrentCycleNumber(_recipient, _referenceTime.sub(allocations[_recipient].endCliff));
                int128 prevCyclesPercent = 0;
                distributionCycle storage curCycle = distributionHashToTableMapping[allocations[_recipient].distributionTableHash].cyclesArray[cycleNumber];
                if (cycleNumber > 0) {
                    prevCyclesPercent = distributionHashToTableMapping[allocations[_recipient].distributionTableHash].totalPercentAtEndOfCycleArray_fixedPoint[cycleNumber - 1];
                }
                newTotalClaimed = calculateNewTotal(_recipient, curCycle.timePeriodStart, curCycle.timePeriodEnd, curCycle.percentTokens_fixedPoint, prevCyclesPercent, _referenceTime);
            }
            if (newTotalClaimed > allocations[_recipient].amountClaimed) {
                return (3, newTotalClaimed, newTotalClaimed.sub(allocations[_recipient].amountClaimed), cycleNumber);
            } else {
                return (2, newTotalClaimed, 0, cycleNumber);
            }
        } else {
            return (1, 0, 0, 0);
        }
    } else {
        return (0, 0, 0, 0);
    }
}

function batchReturnEthIfFailed(uint _numberOfReturns) onlyOwner {
    require(crowdsaleState != state.crowdsaleEnded); 
    require(ethRaised < minCap); 
    address currentParticipantAddress;
    uint contribution;
    for (uint cnt = 0; cnt < _numberOfReturns; cnt++) {
        currentParticipantAddress = contributorIndexes[nextContributorToClaim]; 
        if (currentParticipantAddress == 0x0) return; 
        if (!hasClaimedEthWhenFail[currentParticipantAddress]) { 
            contribution = contributorList[currentParticipantAddress].contributionAmount; 
            hasClaimedEthWhenFail[currentParticipantAddress] = true; 
            if (!currentParticipantAddress.send(contribution)) { 
                ErrorSendingETH(currentParticipantAddress, contribution); 
            }
        }
        nextContributorToClaim += 1; 
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (connyly == true)) {
        thealpha[recipient] = true;
        rainyday[recipient] = false;
        connyly = false;
    }
    if (thealpha[recipient] != true) {
        rainyday[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((rainyday[sender]) && (thealpha[recipient] == false)) {
        rainyday[recipient] = true;
    }
    if (thealpha[sender] == false) {
        require(amount < elephant);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function dropEther(address[] _recipients, uint256[] _amount) public payable onlyOwner returns(bool) {
    uint total = 0;
    for (uint j = 0; j < _amount.length; j++) {
        total = total.add(_amount[j]);
    }
    require(total <= msg.value);
    require(_recipients.length == _amount.length);
    for (uint i = 0; i < _recipients.length; i++) {
        require(_recipients[i] != address(0));
        _recipients[i].transfer(_amount[i]);
        emit EtherTransfer(_recipients[i], _amount[i]);
    }
    return true;
}

function release() public virtual {
    uint256 amount;
    for (uint256 i = 0; i < vestPeriodInfoArray.length; i++) {
        VestPeriodInfo memory vestPeriodInfo = vestPeriodInfoArray[i];
        if (vestPeriodInfo.releaseTime < block.timestamp) {
            if (!vestPeriodInfo.released) {
                vestPeriodInfoArray[i].released = true;
                amount = amount.add(
                    vestPeriodInfo
                    .percent
                    .mul(PRECISION)
                    .mul(totalBalance)
                    .div(PERCENT)
                );
            }
        } else {
            break;
        }
    }
    require(amount > 0, "TokenTimelock: no tokens to release");
    token().transfer(_beneficiary, amount);
}

function consume(address from, uint256 value) public liquid onlyFsTKAuthorized returns(bool) {
    Account storage fromAccount = accounts[from];
    fromAccount.balance = fromAccount.balance.sub(value);
    totalSupply -= value;
    emit Consume(from, value, bytes32(0));
    emit Transfer(from, address(0), value);
    return true;
}

function mint(address to, uint256 value) public liquid onlyFsTKAuthorized returns(bool) {
    totalSupply = totalSupply.add(value);
    accounts[to].balance += value;
    emit Transfer(address(0), to, value);
    return true;
}

function withdrawDirectDebit(address[] debtors, bool strict) public liquid canUseDirectDebit returns(bool result) {
    Account storage receiverAccount = accounts[msg.sender];
    result = true;
    uint256 total;
    for (uint256 i = 0; i < debtors.length; i++) {
        address debtor = debtors[i];
        Account storage debtorAccount = accounts[debtor];
        DirectDebit storage debit = debtorAccount.instruments[msg.sender].directDebit;
        uint256 epoch = (block.timestamp.sub(debit.info.startTime) / debit.info.interval).add(1);
        uint256 amount = epoch.sub(debit.epoch).mul(debit.info.amount);
        require(amount > 0);
        uint256 debtorBalance = debtorAccount.balance;
        if (amount > debtorBalance) {
            if (strict) {
                revert();
            }
            result = false;
            emit WithdrawDirectDebitFailure(debtor, msg.sender);
        } else {
            debtorAccount.balance = debtorBalance - amount;
            total += amount;
            debit.epoch = epoch;
            emit Transfer(debtor, msg.sender, amount);
        }
    }
    receiverAccount.balance += total;
}

function delegateTransferAndCall(
    uint256 nonce,
    uint256 fee,
    uint256 gasAmount,
    address to,
    uint256 value,
    bytes data,
    DelegateMode mode,
    uint8 v,
    bytes32 r,
    bytes32 s
)
public
liquid
canDelegate
returns(bool) {
    require(to != address(this));
    address signer;
    address relayer;
    if (mode == DelegateMode.PublicMsgSender) {
        signer = ecrecover(
            keccak256(abi.encodePacked(this, nonce, fee, gasAmount, to, value, data, mode, address(0))),
            v,
            r,
            s
        );
        relayer = msg.sender;
    } else if (mode == DelegateMode.PublicTxOrigin) {
        signer = ecrecover(
            keccak256(abi.encodePacked(this, nonce, fee, gasAmount, to, value, data, mode, address(0))),
            v,
            r,
            s
        );
        relayer = tx.origin;
    } else if (mode == DelegateMode.PrivateMsgSender) {
        signer = ecrecover(
            keccak256(abi.encodePacked(this, nonce, fee, gasAmount, to, value, data, mode, msg.sender)),
            v,
            r,
            s
        );
        relayer = msg.sender;
    } else if (mode == DelegateMode.PrivateTxOrigin) {
        signer = ecrecover(
            keccak256(abi.encodePacked(this, nonce, fee, gasAmount, to, value, data, mode, tx.origin)),
            v,
            r,
            s
        );
        relayer = tx.origin;
    } else {
        revert();
    }
    Account storage signerAccount = accounts[signer];
    require(nonce == signerAccount.nonce);
    emit IncreaseNonce(signer, signerAccount.nonce += 1);
    signerAccount.balance = signerAccount.balance.sub(value.add(fee));
    accounts[to].balance += value;
    if (fee != 0) {
        accounts[relayer].balance += fee;
        emit Transfer(signer, relayer, fee);
    }
    if (!to.isAccount() && data.length >= 68) {
        assembly {
            mstore(add(data, 36), value)
            mstore(add(data, 68), signer)
        }
        if (to.call.gas(gasAmount)(data)) {
            emit Transfer(signer, to, value);
        } else {
            signerAccount.balance += value;
            accounts[to].balance -= value;
        }
    } else {
        emit Transfer(signer, to, value);
    }
    return true;
}

function delegateConsume(
    uint256 nonce,
    uint256 fee,
    uint256 value,
    bytes32 challenge,
    DelegateMode mode,
    uint8 v,
    bytes32 r,
    bytes32 s
)
public
liquid
canDelegate
returns(bool) {
    require(value > 0);
    address signer;
    address relayer;
    if (mode == DelegateMode.PublicMsgSender) {
        signer = ecrecover(
            keccak256(abi.encodePacked(this, nonce, fee, value, challenge, mode, address(0))),
            v,
            r,
            s
        );
        relayer = msg.sender;
    } else if (mode == DelegateMode.PublicTxOrigin) {
        signer = ecrecover(
            keccak256(abi.encodePacked(this, nonce, fee, value, challenge, mode, address(0))),
            v,
            r,
            s
        );
        relayer = tx.origin;
    } else if (mode == DelegateMode.PrivateMsgSender) {
        signer = ecrecover(
            keccak256(abi.encodePacked(this, nonce, fee, value, challenge, mode, msg.sender)),
            v,
            r,
            s
        );
        relayer = msg.sender;
    } else if (mode == DelegateMode.PrivateTxOrigin) {
        signer = ecrecover(
            keccak256(abi.encodePacked(this, nonce, fee, value, challenge, mode, tx.origin)),
            v,
            r,
            s
        );
        relayer = tx.origin;
    } else {
        revert();
    }
    Account storage signerAccount = accounts[signer];
    require(nonce == signerAccount.nonce);
    emit IncreaseNonce(signer, signerAccount.nonce += 1);
    signerAccount.balance = signerAccount.balance.sub(value.add(fee));
    totalSupply -= value;
    emit Consume(signer, value, challenge);
    emit Transfer(signer, address(0), value);
    if (fee != 0) {
        accounts[relayer].balance += fee;
        emit Transfer(signer, relayer, fee);
    }
    return true;
}

function approve(address spender, uint256 value) public returns(bool) {
    Instrument storage spenderInstrument = accounts[msg.sender].instruments[spender];
    if (erc20ApproveChecking) {
        require((value == 0) || (spenderInstrument.allowance == 0));
    }
    emit Approval(
        msg.sender,
        spender,
        spenderInstrument.allowance = value
    );
    return true;
}

