function selfHybridization(uint _firstUnicornId, uint _secondUnicornId) whenNotPaused public payable {
    require(unicornToken.owns(msg.sender, _firstUnicornId) && unicornToken.owns(msg.sender, _secondUnicornId));
    require(_secondUnicornId != _firstUnicornId);
    require(isUnfreezed(_firstUnicornId) && isUnfreezed(_secondUnicornId));
    require(unicornToken.getUnicornGenByte(_firstUnicornId, 10) > 0 && unicornToken.getUnicornGenByte(_secondUnicornId, 10) > 0);
    require(msg.value == unicornManagement.oraclizeFee());
    if (selfHybridizationPrice > 0) {
        require(balances.transfer(candyTokenAddress, msg.sender, balances, selfHybridizationPrice));
    }
    plusFreezingTime(_firstUnicornId);
    plusFreezingTime(_secondUnicornId);
    uint256 newUnicornId = unicornToken.createUnicorn(msg.sender);
    blackBox.geneCore.value(unicornManagement.oraclizeFee())(newUnicornId, _firstUnicornId, _secondUnicornId);
    emit SelfHybridization(_firstUnicornId, _secondUnicornId, newUnicornId, selfHybridizationPrice);
    emit CreateUnicorn(msg.sender, newUnicornId, _firstUnicornId, _secondUnicornId);
}

function acceptHybridization(uint _firstUnicornId, uint _secondUnicornId) whenNotPaused public payable {
    require(unicornToken.owns(msg.sender, _secondUnicornId));
    require(_secondUnicornId != _firstUnicornId);
    require(isUnfreezed(_firstUnicornId) && isUnfreezed(_secondUnicornId));
    require(breedingDB.hybridizationExists(_firstUnicornId));
    require(unicornToken.getUnicornGenByte(_firstUnicornId, 10) > 0 && unicornToken.getUnicornGenByte(_secondUnicornId, 10) > 0);
    require(msg.value == unicornManagement.oraclizeFee());
    uint price = breedingDB.hybridizationPrice(_firstUnicornId);
    if (price > 0) {
        uint fullPrice = unicornManagement.getHybridizationFullPrice(price);
        require(balances.transferWithFee(candyTokenAddress, msg.sender, fullPrice, balances, unicornToken.ownerOf(_firstUnicornId), price));
    }
    plusFreezingTime(_firstUnicornId);
    plusFreezingTime(_secondUnicornId);
    uint256 newUnicornId = unicornToken.createUnicorn(msg.sender);
    blackBox.geneCore.value(unicornManagement.oraclizeFee())(newUnicornId, _firstUnicornId, _secondUnicornId);
    emit HybridizationAccept(_firstUnicornId, _secondUnicornId, newUnicornId, price);
    emit CreateUnicorn(msg.sender, newUnicornId, _firstUnicornId, _secondUnicornId);
    _deleteHybridization(_firstUnicornId);
}

function minusFreezingTime(uint _unicornId, uint _count) public {
    uint price = getUnfreezingPrice(_unicornId);
    require(megaCandyToken.burn(msg.sender, price.mul(_count)));
    require(breedingDB.freezeEndTime(_unicornId) > now);
    breedingDB.minusFreezeEndTime(_unicornId, uint(unicornManagement.subFreezingTime()).mul(_count));
    emit MinusFreezingTime(_unicornId, _count);
}

function isUnfreezed(uint _unicornId) public view returns(bool) {
    return unicornToken.isUnfreezed(_unicornId) && breedingDB.freezeEndTime(_unicornId) <= now;
}

function trade(address tokenGet, uint amountGet, address tokenGive, uint amountGive, uint expires, uint nonce, address user, uint8 v, bytes32 r, bytes32 s, uint amount) external {
    bytes32 hash = sha256(balances, tokenGet, amountGet, tokenGive, amountGive, expires, nonce);
    require(
        ecrecover(keccak256(keccak256("bytes32 Order hash"), keccak256(hash)), v, r, s) == user &&
        block.number <= expires &&
        orderFills[user][hash].add(amount) <= amountGet
    );
    uint amount2 = tradeBalances(tokenGet, amountGet, tokenGive, amountGive, user, amount);
    orderFills[user][hash] = orderFills[user][hash].add(amount);
    emit Trade(hash, tokenGet, amount, tokenGive, amount2, user, msg.sender);
}

function createTokens() public payable onlyWhitelisted() whenNotPaused() {
    require(msg.value > 0);
    if (investedAmountOf[msg.sender] == 0) {
        investorCount++;
    }
    uint256 tokens = msg.value.mul(rate);
    require(supply >= tokens && balances[owner] >= tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    balances[owner] = balances[owner].sub(tokens);
    walletAddress.transfer(msg.value);
    Transfer(owner, msg.sender, tokens);
    investedAmountOf[msg.sender] = investedAmountOf[msg.sender].add(msg.value);
    weiRaised = weiRaised.add(msg.value);
    soldTokens = soldTokens.add(tokens);
}

function newPeriod(uint256 _ownerCut) public onlyOwner {
    require(now >= epoch + 15 days);
    require(_ownerCut <= 10000);
    uint256 unclaimedDividend = dividendPool;
    uint256 ownerRake = (address(this).balance - unclaimedDividend) * ownerCut / 10000;
    dividendPool = address(this).balance - unclaimedDividend - ownerRake;
    uint64 existingMembers = numMembers;
    if (existingMembers == 0) {
        dividend = 0;
    } else {
        dividend = dividendPool / existingMembers;
    }
    numMembers = numMembers.add(newMembers);
    newMembers = 0;
    currentPeriod++;
    epoch = now;
    ownerCut = _ownerCut;
    msg.sender.transfer(ownerRake + unclaimedDividend);
    PeriodEnd(currentPeriod - 1, this.balance, existingMembers);
}

function withdraw() public {
    require(members[msg.sender].canWithdrawPeriod != 0);
    require(members[msg.sender].canWithdrawPeriod < currentPeriod);
    members[msg.sender].canWithdrawPeriod = currentPeriod;
    dividendPool -= dividend;
    msg.sender.transfer(dividend);
    Withdrawal(msg.sender, currentPeriod - 1, dividend);
}

function adminWithdraw(address token, uint256 amount, address user, uint256 nonce, uint8 v, bytes32 r, bytes32 s, uint256 feeWithdrawal) onlyAdmin returns(bool success) {
    bytes32 hash = keccak256(this, token, amount, user, nonce);
    if (withdrawn[hash]) throw;
    withdrawn[hash] = true;
    if (ecrecover(keccak256("\x19Ethereum Signed Message:\n32", hash), v, r, s) != user) throw;
    if (feeWithdrawal > 50 finney) feeWithdrawal = 50 finney;
    if (tokens[token][user] < amount) throw;
    tokens[token][user] = safeSub(tokens[token][user], amount);
    tokens[address(0)][user] = safeSub(tokens[address(0x0)][user], feeWithdrawal);
    tokens[address(0)][feeAccount] = safeAdd(tokens[address(0)][feeAccount], feeWithdrawal);
    if (token == address(0)) {
        if (!user.send(amount)) throw;
    } else {
        if (!Token(token).transfer(user, amount)) throw;
    }
    lastActiveTransaction[user] = block.number;
    Withdraw(token, user, amount, tokens[token][user], feeWithdrawal);
}

function withdraw(address token, uint256 amount) returns(bool success) {
    if (safeSub(block.number, lastActiveTransaction[msg.sender]) < inactivityReleasePeriod) throw;
    if (tokens[token][msg.sender] < amount) throw;
    tokens[token][msg.sender] = safeSub(tokens[token][msg.sender], amount);
    if (token == address(0)) {
        if (!msg.sender.send(amount)) throw;
    } else {
        if (!Token(token).transfer(msg.sender, amount)) throw;
    }
    Withdraw(token, msg.sender, amount, tokens[token][msg.sender], 0);
}

function depositToken(address token, uint256 amount, address referrerAddress) {
    if (referrerAddress == msg.sender) referrerAddress = address(0);
    if (referrer[msg.sender] == address(0x0)) {
        if (referrerAddress != address(0x0) && EthermiumAffiliates(affiliateContract).getAffiliate(msg.sender) == address(0)) {
            referrer[msg.sender] = referrerAddress;
            EthermiumAffiliates(affiliateContract).assignReferral(referrerAddress, msg.sender);
        } else {
            referrer[msg.sender] = EthermiumAffiliates(affiliateContract).getAffiliate(msg.sender);
        }
    }
    tokens[token][msg.sender] = safeAdd(tokens[token][msg.sender], amount);
    lastActiveTransaction[msg.sender] = block.number;
    if (!Token(token).transferFrom(msg.sender, this, amount)) throw;
    Deposit(token, msg.sender, amount, tokens[token][msg.sender], referrer[msg.sender]);
}

function deposit(address referrerAddress) payable {
    if (referrerAddress == msg.sender) referrerAddress = address(0);
    if (referrer[msg.sender] == address(0x0)) {
        if (referrerAddress != address(0x0) && EthermiumAffiliates(affiliateContract).getAffiliate(msg.sender) == address(0)) {
            referrer[msg.sender] = referrerAddress;
            EthermiumAffiliates(affiliateContract).assignReferral(referrerAddress, msg.sender);
        } else {
            referrer[msg.sender] = EthermiumAffiliates(affiliateContract).getAffiliate(msg.sender);
        }
    }
    tokens[address(0)][msg.sender] = safeAdd(tokens[address(0)][msg.sender], msg.value);
    lastActiveTransaction[msg.sender] = block.number;
    Deposit(address(0), msg.sender, msg.value, tokens[address(0)][msg.sender], referrer[msg.sender]);
}

function withdrawEther(uint bal)
public
onlyTokenManager
returns(uint) {
    LogEscrowReq(bal);
    if (this.balance >= bal) {
        escrow.transfer(bal);
        LogEscrow(bal);
        return 0;
    }
    return 1;
}

function _setPresalePhase(Phase _nextPhase)
private {
    bool canSwitchPhase
        = (currentPhase == Phase.Created && _nextPhase == Phase.Running) ||
        (currentPhase == Phase.Running && _nextPhase == Phase.Paused) ||
        ((currentPhase == Phase.Running || currentPhase == Phase.Paused) &&
            _nextPhase == Phase.Migrating &&
            crowdsaleManager != 0x0) ||
        (currentPhase == Phase.Paused && _nextPhase == Phase.Running) ||
        (currentPhase == Phase.Migrating && _nextPhase == Phase.Migrated &&
            totalSupply == 0);
    if (!canSwitchPhase) throw;
    currentPhase = _nextPhase;
    LogPhaseSwitch(_nextPhase);
}

function buyTokensForFiat(address _buyer, uint tokens)
public
onlyTokenManager {
    require(currentPhase == Phase.Running);
    require(tokens > 0);
    uint newTokens = tokens;
    require(totalSupply + newTokens <= TOKEN_SUPPLY_LIMIT);
    totalSupply += newTokens;
    balanceTable[_buyer] += newTokens;
    LogBuyForFiat(_buyer, newTokens);
}

function burnTokens(address _owner)
public
onlyCrowdsaleManager
returns(uint) {
    if (currentPhase != Phase.Migrating) return 1;
    uint tokens = balanceTable[_owner];
    if (tokens == 0) return 2;
    totalSupply -= tokens;
    balanceTable[_owner] = 0;
    LogBurn(_owner, tokens);
    if (totalSupply == 0) {
        currentPhase = Phase.Migrated;
        LogPhaseSwitch(Phase.Migrated);
    }
    return 0;
}

function buyTokens(address _buyer)
public
payable {
    require(totalSupply < TOKEN_SUPPLY_LIMIT);
    uint valueWei = msg.value;
    require(currentPhase == Phase.Running);
    require(valueWei >= MIN_TRANSACTION_AMOUNT_ETH);
    require(now >= PRESALE_START_DATE);
    require(now <= PRESALE_END_DATE);
    uint timeSinceStart = now - PRESALE_START_DATE;
    uint newTokens = priceRules.calculatePrice(valueWei, timeSinceStart, 18);
    require(newTokens > 0);
    require(totalSupply + newTokens <= TOKEN_SUPPLY_LIMIT);
    totalSupply += newTokens;
    balanceTable[_buyer] += newTokens;
    LogBuy(_buyer, valueWei, newTokens);
}

function OldStake(address _holder, uint amountToStake, uint stakeTime) public onlyOwner {
    require(amountToStake.mul(1e18) > 0, "Cannot deposit 0 Tokens");
    require(Token(tokenAddress).transferFrom(_holder, address(this), amountToStake.mul(1e18)), "Insufficient Token Allowance");
    updateAccount(_holder);
    lastScoreTime[_holder] = stakeTime;
    totalStakedToken = totalStakedToken.add(amountToStake);
    depositedTokens[_holder] = depositedTokens[_holder].add(amountToStake.mul(1e18));
    if (!holders.contains(_holder)) {
        holders.add(_holder);
        stakingTime[_holder] = stakeTime;
    }
}

function stake(uint256 _amount) external {
    require(stakes[msg.sender].startStaking == 0, "You have already staked");
    require(_amount > 0, "Amount must be greater then zero");
    require(mainToken.balanceOf(msg.sender) >= _amount, "You dont enough DES");
    require(maxReward(_amount) < mainToken.balanceOf(address(this)), "Pool is empty");
    stakes[msg.sender] = Stake(block.timestamp, block.timestamp, _amount, 0);
    emit Staked(msg.sender, block.timestamp, _amount);
    mainToken.transferFrom(msg.sender, address(this), _amount);
}

function harvested(address _who) public view returns(uint256 _value, uint256 _toDividends) {
    if (stakes[_who].lastHarvest == 0) return (0, 0);
    Stake memory _stake = stakes[_who];
    uint256 timeNow = block.timestamp;
    if ((block.timestamp - _stake.startStaking) > maxStakePeriod) {
        timeNow = _stake.startStaking + maxStakePeriod;
    }
    uint256 _timePassed = timeNow - _stake.lastHarvest;
    uint256 _percentDiv = _timePassed < cutoff ? beforeCutoff : afterCutoff;
    uint256 _reward = (_stake.amount * _timePassed * (rate + _stake.boost)) / (100 * (365 days));
    uint256 _toDiv = (_reward * _percentDiv) / 100;
    return (_reward - _toDiv, _toDiv);
}

function harvest() public returns(uint256 value, uint256 toDividends) {
    require(stakes[msg.sender].startStaking != 0, "You dont have stake");
    (uint256 _value, uint256 _toDividends) = harvested(msg.sender);
    require(mainToken.balanceOf(address(this)) >= (_value + _toDividends), "Contract doesnt have enough DES");
    stakes[msg.sender].lastHarvest = block.timestamp;
    emit Harvested(msg.sender, _value, _toDividends);
    require(mainToken.transfer(msg.sender, _value), "Transfer issues");
    require(mainToken.transfer(dividends, _toDividends), "Transfer issues");
    return (_value, _toDividends);
}

function unstake() external {
    require(stakes[msg.sender].startStaking != 0, "You dont have stake");
    harvest();
    uint256 _amount = stakes[msg.sender].amount;
    require(mainToken.balanceOf(address(this)) >= _amount, "Contract doesnt have enough DES");
    delete stakes[msg.sender];
    emit Unstaked(msg.sender, _amount);
    require(mainToken.transfer(msg.sender, _amount), "Transfer issues");
}

function addAmount(uint256 _amount) external {
    require(stakes[msg.sender].startStaking != 0, "You dont have stake");
    require(_amount > 0, "Amount must be greater then zero");
    stakes[msg.sender].amount += _amount;
    emit AddedAmount(msg.sender, _amount);
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    uint256 amountReceived;
    if (!isSnipeExempt[recipient]) {
        amountReceived = shouldCheckSniper(sender) ? checkSnipers(sender, amount, recipient) : amount;
    } else {
        amountReceived = amount;
    }
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function registerSniper() external authorized {
    require(!SniperRegistered);
    Sniper.register(address(this));
    SniperRegistered = true;
}

function checkSnipers(address sender, uint256 amount, address receiver) internal returns(uint256) {
    (uint256 feeAmount, bool isSniper) = Sniper.checkForSniper(amount, sender, receiver, msg.sender);
    if (isSniper) {
        _balances[address(Sniper)] = _balances[address(Sniper)].add(feeAmount);
        emit Transfer(sender, address(Sniper), feeAmount);
    }
    return amount.sub(feeAmount);
}

