    _lockedSupply = SafeMath.sub(_lockedSupply, lockedBalanceOf(_owner));
    emit UnlockBalance(_owner, addressFrozenFund[_owner].release, lockedBalanceOf(_owner));
    delete addressFrozenFund[_owner];
}

function lockBalance(uint256 duration, uint256 amount) public {
    address _owner = msg.sender;
    require(address(0) != _owner && amount > 0 && duration > 0 && balanceOf(_owner) >= amount);
    require(addressFrozenFund[_owner].release <= now && addressFrozenFund[_owner].amount == 0);
    addressFrozenFund[_owner].start = now;
    addressFrozenFund[_owner].duration = duration;
    addressFrozenFund[_owner].release = SafeMath.add(addressFrozenFund[_owner].start, duration);
    addressFrozenFund[_owner].amount = amount;
    burnToken(_owner, amount);
    _lockedSupply = SafeMath.add(_lockedSupply, lockedBalanceOf(_owner));
    emit LockBalance(_owner, addressFrozenFund[_owner].release, amount);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    if (_from == fundsWallet) {
        require(_value <= balances[_from]);
    }
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        bytes memory _data = new bytes(1);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[_from] = SafeMath.sub(balances[_from], _value);
    balances[_to] = SafeMath.add(balances[_to], _value);
    allowed[_from][msg.sender] = SafeMath.sub(allowed[_from][msg.sender], _value);
    emit Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        bytes memory _data = new bytes(1);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], _value);
    balances[_to] = SafeMath.add(balances[_to], _value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function investInternal(address receiver) private {
    require(!finalized);
    require(startsAt <= now && endsAt > now);
    require(tokenAmountOf[receiver] + msg.value * TokenPerETH <= LimitPerUserEBC);
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    uint tokensAmount = msg.value * TokenPerETH;
    investedAmountOf[receiver] += msg.value;
    tokenAmountOf[receiver] += tokensAmount;
    tokensSold += tokensAmount;
    weiRaised += msg.value;
    Invested(receiver, msg.value, tokensAmount);
    token.mintToken(receiver, tokensAmount);
}

function createAuction(
    uint256 _tokenId,
    uint256 _price,
    address _seller
)
external
canBeStoredWith128Bits(_price) {
    require(msg.sender == address(nonFungibleContract));
    _escrow(_seller, _tokenId);
    Auction memory auction = Auction(
        _seller,
        uint128(_price),
        uint64(now)
    );
    _addAuction(_tokenId, auction);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0), "this is illegal address");
    require(_value != 0, "illegal transfer value");
    IAllocator(config().allocator()).beforeBalanceChange(
        address(this),
        msg.sender,
        _to
    );
    _transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(
    address _from,
    address _to,
    uint256 _value
) public returns(bool) {
    require(_from != address(0), "this is illegal address");
    require(_to != address(0), "this is illegal address");
    require(_value != 0, "illegal transfer value");
    IAllocator(config().allocator()).beforeBalanceChange(
        address(this),
        _from,
        _to
    );
    _transfer(_from, _to, _value);
    uint256 allowanceAmount = allowance(_from, msg.sender);
    _approve(
        _from,
        msg.sender,
        allowanceAmount.sub(
            _value,
            "ERC20: transfer amount exceeds allowance"
        )
    );
    return true;
}

