function enter(uint256 _amount) public {
    require(initialBlock + 2389091 > block.number, "Staking Period Over");
    bool available = false;
    stakes[msg.sender][stakeCount[msg.sender]] = stakeData(
        msg.sender,
        _amount,
        block.number
    );
    stakeCount[msg.sender] += 1;
    for (uint i = 0; i < stakers.length; i++) {
        if (stakers[i] == msg.sender) {
            available = true;
            break;
        } else {
            continue;
        }
    }
    if (!available) {
        stakers.push(msg.sender);
    }
    uint256 usersTokens = token.balanceOf(msg.sender);
    uint256 allowedTokens = token.allowance(msg.sender, address(this));
    require(usersTokens >= _amount, "Insufficient Balance to Stake");
    require(allowedTokens >= _amount, "Allowed balance is Insufficient");
    token.transferFrom(msg.sender, address(this), _amount);
    _mint(msg.sender, _amount);
}

function _preValidatePurchase(address _beneficiary, uint256 _weiAmount) internal whenNotPaused {
    require(_beneficiary != address(0));
    require(_weiAmount >= minInvest);
    require(now >= openingTime && now <= closingTime);
}

function withdrawEther(uint amount, address sendTo) external onlyAdmin {
    sendTo.transfer(amount);
    emit EtherWithdraw(amount, sendTo);
}

function doTrade(
    ERC20 src,
    uint srcAmount,
    ERC20 dest,
    address destAddress,
    uint maxDestAmount,
    uint minConversionRate,
    uint rate100
)
internal
returns(uint) {
    require(tx.gasprice <= maxGasPrice);
    uint supplierInd;
    uint rate;
    (supplierInd, rate) = findBestRate(src, dest, srcAmount);
    SupplierInterface theSupplier = suppliers[supplierInd];
    require(rate > 0 && rate < MAX_RATE);
    if (validateCodeTokens[src] || validateCodeTokens[dest]) {
        require(rate100 > 0 && rate100 >= minConversionRate && rate100 < MAX_RATE);
        rate = rate100;
    } else {
        require(rate >= minConversionRate);
    }
    uint actualSrcAmount = srcAmount;
    uint actualDestAmount = calcDestAmount(src, dest, actualSrcAmount, rate100);
    if (actualDestAmount > maxDestAmount) {
        actualDestAmount = maxDestAmount;
        actualSrcAmount = calcSrcAmount(src, dest, actualDestAmount, rate100);
        require(actualSrcAmount <= srcAmount);
    }
    uint ethAmount;
    if (src == ETH_TOKEN_ADDRESS) {
        ethAmount = actualSrcAmount;
    } else {
        ethAmount = actualDestAmount;
    }
    require(ethAmount <= getUserCapInWei(msg.sender));
    require(doSupplierTrade(src, actualSrcAmount, dest, destAddress, actualDestAmount, theSupplier, rate, true));
    if ((actualSrcAmount < srcAmount) && (src == ETH_TOKEN_ADDRESS)) {
        msg.sender.transfer(srcAmount - actualSrcAmount);
    }
    emit ExecuteTrade(msg.sender, src, dest, actualSrcAmount, actualDestAmount);
    return actualDestAmount;
}

function listPairForSupplier(address supplier, ERC20 src, ERC20 dest, bool add) public onlyAdmin {
    (perSupplierListedPairs[supplier])[keccak256(src, dest)] = add;
    if (src != ETH_TOKEN_ADDRESS) {
        if (add) {
            src.approve(supplier, 2 ** 255); 
        } else {
            src.approve(supplier, 0);
        }
    }
    setDecimals(src);
    setDecimals(dest);
    emit ListSupplierPairs(supplier, src, dest, add);
}

function getReward() public update(msg.sender) {
    uint _reward = rewards[msg.sender];
    uint _user_lock = ve(_veibff).locked__end(msg.sender);
    uint _adj = Math.min(_reward * _user_lock / (block.timestamp + MAXTIME), _reward);
    if (_adj > 0) {
        rewards[msg.sender] = 0;
        erc20(_ibff).approve(_veibff, _adj);
        ve(_veibff).deposit_for(msg.sender, _adj);
        safeTransfer(_ibff, _vedist, _reward - _adj);
    }
}

function createPromise(address recipient, uint256 amount, uint256 lockedUntil)
requires(amount <= uncommittedTokenBalance())
thenAssertState
internal
returns(TokenPromise storage promise) {
    uint256 promiseId = nextPromiseId++;
    promise = promises[promiseId];
    promise.promiseId = promiseId;
    promise.recipient = recipient;
    promise.amount = amount;
    promise.lockedUntil = lockedUntil;
    promise.state = PromiseState.pending;
    promisedTokenBalance = promisedTokenBalance.add(promise.amount);
    logPromiseCreated(promiseId, recipient, amount, lockedUntil);
    return promise;
}

function lockup(address recipient, uint256 amount, uint256 lockedUntil)
onlyOwner
notNull(recipient)
notZero(amount)
nonReentrant
external {
    ensureTokensAvailable(amount);
    TokenPromise storage promise = createPromise(recipient, amount, lockedUntil);
    if (recipient == owner) {
        doConfirm(promise);
    }
}

function doConfirm(TokenPromise storage promise)
thenAssertState
internal {
    transition(promise, PromiseState.confirmed);
    lockedTokenBalance = lockedTokenBalance.add(promise.amount);
    logPromiseConfirmed(promise.promiseId);
}

function salvageTokensFromContract(address tokenAddress, address to, uint amount)
onlyOwner
requiresOne(
    tokenAddress != address(token),
    amount <= uncommittedTokenBalance()
)
nonReentrant
external {
    ERC20(tokenAddress).transfer(to, amount);
}

function withdrawUncommittedTokens(uint amount)
onlyOwner
requires(amount <= uncommittedTokenBalance())
nonReentrant
external {
    token.transfer(owner, amount);
}

function collect(uint256 promiseId)
promiseExists(promiseId)
onlyRecipient(promiseId)
requires(block.timestamp >= promises[promiseId].lockedUntil)
requiresOne(
    promises[promiseId].state == PromiseState.pending,
    promises[promiseId].state == PromiseState.confirmed
)
nonReentrant
external {
    TokenPromise storage promise = promises[promiseId];
    unlockTokens(promise, PromiseState.executed);
    if (token.transfer(promise.recipient, promise.amount)) {
        logPromiseFulfilled(promise.promiseId);
    } else {
        transition(promise, PromiseState.failed);
        logPromiseUnfulfillable(promiseId, promise.recipient, promise.amount);
    }
}

function canCollect(uint256 promiseId)
constant
returns(bool) {
    return (promises[promiseId].state == PromiseState.confirmed || promises[promiseId].state == PromiseState.pending) &&
        block.timestamp >= promises[promiseId].lockedUntil;
}

