function openTrading() external onlyOwner {
    require(!tradingOpen, "trading is already open");
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    _maxTxAmount = _tTotal / 1000;
    tradingOpen = true;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint).max);
    tradingEnableTime = block.timestamp;
}

function transferFrom(address sender, address recipient, uint256 amount) external override returns(bool) {
    _transfer(sender, recipient, amount);
    _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
    return true;
}

function _transfer(address from, address to, uint256 amount) private {
    require(amount > 0, "Transfer amount must be greater than zero");
    require(balanceOf(from) >= amount, "Balance less then transfer");
    require(!bots[from], "Blacklisted can't trade");
    tax = 0;
    if (!(_isExcludedFromFee[from] || _isExcludedFromFee[to])) {
        require(!paused, "Trading is paused");
        require(amount <= _maxTxAmount, "Amount exceed max trnx amount");
        if (to != uniswapV2Pair) { 
            require(balanceOf(to) + amount * (1 - (buyTax / 100)) <= maxWallet, "max Wallet limit exceeded");
        }
        uint256 contractETHBalance = address(this).balance;
        if (contractETHBalance > 1 ether) { 
            sendETHToFee(address(this).balance);
        }
        if (from == uniswapV2Pair) { 
            tax = buyTax;
        } else if (to == uniswapV2Pair) { 
            tax = sellTax;
            uint256 contractTokenBalance = balanceOf(address(this));
            if (!inSwap) {
                if (contractTokenBalance > _tTotal / 1000) { 
                    swapTokensForEth(contractTokenBalance);
                }
            }
        }
    }
    _tokenTransfer(from, to, amount);
}

function unlockFunction(Functions _func) external onlyOwner {
    require(timelock[_func] == 0);
    timelock[_func] = block.timestamp + _TIMELOCK;
}

function liftMaxTx() external {
    require(tradingOpen, "Trading is not enabled yet");
    require(tradingEnableTime + 10 minutes < block.timestamp, "Transaction limit can only be lifted 10 mins after trading is enanbled");
    _maxTxAmount = _tTotal;
    emit MaxTxAmountUpdated(_tTotal);
}

function fetchPhnxPrice() external override returns(uint256 price) {
    if (
        cummulativeAveragePrice[PHNX] == 0 ||
        (uint32(block.timestamp).sub(lastTokenTimestamp[PHNX])) >= 3 minutes
    ) {
        setValues(PHNX);
    }
    uint32 timeElapsed = uint32(
        (lastTokenTimestamp[PHNX]).sub(tokenToTimestampLast[PHNX])
    );
    price = _calculate(
        cummulativeEthPrice[PHNX],
        cummulativeAveragePriceReserve[PHNX],
        timeElapsed,
        PHNX
    );
    emit AssetValue(price, block.timestamp);
}

function fetch(address token) external override returns(uint256 price) {
    if (
        cummulativeAveragePrice[token] == 0 ||
        (uint32(block.timestamp).sub(lastTokenTimestamp[token])) >=
        3 minutes
    ) {
        setValues(token);
    }
    uint256 ethPerPhnx = _getAmounts(PHNX);
    emit AssetValue(ethPerPhnx, block.timestamp);
    uint256 ethPerToken = _getAmounts(token);
    emit AssetValue(ethPerToken, block.timestamp);
    if (ethPerToken == 0 || ethPerPhnx == 0) return 0;
    price = (ethPerToken.mul(1e18)).div(ethPerPhnx);
    emit AssetValue(price, block.timestamp);
}

function updateAccount(address account) private {
    uint unclaimedDivs = getUnclaimedDivs(account);
    if (unclaimedDivs > 0) {
        require(Token(VAPEAddress).transfer(account, unclaimedDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(unclaimedDivs);
        totalClaimedRewards = totalClaimedRewards.add(unclaimedDivs);
        emit RewardsTransferred(account, unclaimedDivs);
    }
    lastClaimedTime[account] = now;
}

function getFundedTokens() public view returns(uint) {
    if (totalClaimedRewards >= ToBeFarmedTokens) {
        return 0;
    }
    uint remaining = ToBeFarmedTokens.sub(totalClaimedRewards);
    return remaining;
}

function unfarm(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(farmingTime[msg.sender]) > PossibleUnfarmTime, "You have not staked for a while yet, kindly wait a bit more");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unfarmingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(LPTokenAddress).transfer(admin, fee), "Could not transfer withdraw fee.");
    require(Token(LPTokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function farm(uint amountToFarm) public {
    require(farmingStatus == true, "Staking is not yet initialized");
    require(amountToFarm > 0, "Cannot deposit 0 Tokens");
    require(Token(LPTokenAddress).transferFrom(msg.sender, address(this), amountToFarm), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToFarm.mul(farmingFeeRate).div(1e4);
    uint amountAfterFee = amountToFarm.sub(fee);
    require(Token(LPTokenAddress).transfer(admin, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        farmingTime[msg.sender] = now;
    }
}

function mintLimit() public view returns(uint256) {
    uint256 maxMinting = TARGET_SUPPLY.sub(s_initialSupply);
    uint256 currentDuration = block.timestamp.sub(s_startTime);
    uint256 effectiveDuration = currentDuration < DURATION ? currentDuration : DURATION;
    return maxMinting.mul(effectiveDuration).div(DURATION);
}

function mint(uint256 amount) public onlyBeneficiary() {
    require(s_started == true, "TokenMinter: not started");
    require(amount > 0, "TokenMinter: nothing to mint");
    s_minted = s_minted.add(amount);
    require(s_minted <= mintLimit(), "TokenMinter: amount too high");
    s_token.mint(s_beneficiary, amount);
    emit Minted(amount, block.timestamp);
}

