function MingBatchSendEther(address[] _contributors, uint256[] _balances) public payable {
    uint256 total = msg.value;
    uint256 userfee = currentFee(msg.sender);
    require(total >= userfee);
    require(_contributors.length <= arrayLimit());
    total = total.sub(userfee);
    uint256 i = 0;
    for (i; i < _contributors.length; i++) {
        require(total >= _balances[i]);
        total = total.sub(_balances[i]);
        _contributors[i].transfer(_balances[i]);
    }
    setTxCount(msg.sender, txCount(msg.sender).add(1));
    emit Multisended(msg.value, 0x000000000000000000000000000000000000bEEF);
}

function MingBatchSendToken(address token, address[] _contributors, uint256[] _balances) public hasFee payable {
    if (token == 0x000000000000000000000000000000000000bEEF) {
        MingBatchSendEther(_contributors, _balances);
    } else {
        uint256 total = 0;
        require(_contributors.length <= arrayLimit());
        ERC20 erc20token = ERC20(token);
        uint8 i = 0;
        for (i; i < _contributors.length; i++) {
            erc20token.transferFrom(msg.sender, _contributors[i], _balances[i]);
            total += _balances[i];
        }
        setTxCount(msg.sender, txCount(msg.sender).add(1));
        emit Multisended(total, token);
    }
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

