function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 10000;
    } else {
        tokens = msg.value * 1000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function isFinished() constant public returns(bool) {
    return now > end;
}

function mint(address dst, uint rawAmount) external {
    require(msg.sender == minter, "Quick::mint: only the minter can mint");
    require(block.timestamp >= mintingAllowedAfter, "Quick::mint: minting not allowed yet");
    require(dst != address(0), "Quick::mint: cannot transfer to the zero address");
    mintingAllowedAfter = SafeMath.add(block.timestamp, minimumTimeBetweenMints);
    uint96 amount = safe96(rawAmount, "Quick::mint: amount exceeds 96 bits");
    require(amount <= SafeMath.div(SafeMath.mul(totalSupply, mintCap), 100), "Quick::mint: exceeded mint cap");
    totalSupply = safe96(SafeMath.add(totalSupply, amount), "Quick::mint: totalSupply exceeds 96 bits");
    balances[dst] = add96(balances[dst], amount, "Quick::mint: transfer amount overflows");
    emit Transfer(address(0), dst, amount);
}

constructor(address account, address minter_, uint mintingAllowedAfter_) public {
    require(mintingAllowedAfter_ >= block.timestamp, "Quick::constructor: minting can only begin after deployment");
    balances[account] = uint96(totalSupply);
    emit Transfer(address(0), account, totalSupply);
    minter = minter_;
    emit MinterChanged(address(0), minter);
    mintingAllowedAfter = mintingAllowedAfter_;
}

function checkUpkeep(bytes calldata) external view override returns(bool, bytes memory) {
    return (block.timestamp - 1 days >= Faucet(faucet).lastUpdateTime(), "0x");
}

function mint(address _to, uint256 _amount) onlyOwner public returns(bool) {
    require((now <= 1526637600));
    _totalSupply = _totalSupply.add(_amount);
    _balanceOf[_to] = _balanceOf[_to].add(_amount);
    emit Mint(_to, _amount);
    emit Transfer(address(0), _to, _amount);
    return true;
}

function _burn(address _who, uint256 _value) internal {
    require((now <= 1526637600));
    require(_value <= _balanceOf[_who]);
    _balanceOf[_who] = _balanceOf[_who].sub(_value);
    _totalSupply = _totalSupply.sub(_value);
    emit Burn(_who, _value);
    emit Transfer(_who, address(0), _value);
}

function burn(uint256 _value, address _who) onlyOwner public {
    require((now <= 1526637600));
    _burn(_who, _value);
}

function mintToContract(bytes32 mintType, address _to) onlyOwner public returns(bool) {
    require((now <= 1526635600));
    require((mintType == "Crowdsale") || (mintType == "Airdrop") || (mintType == "BountyCampaign") || (mintType == "Vesting") || (mintType == "Reserved"));
    uint256 amount = 0;
    if (mintType == "Crowdsale") {
        require(!crowdsale_funded);
        amount = 59000000000000000000000000;
        crowdsale_funded = true;
    }
    if (mintType == "BountyCampaign") {
        require(!bounty_campaign_funded);
        amount = 2834000000000000000000000;
        bounty_campaign_funded = true;
    }
    if (mintType == "Vesting") {
        require(!vest_funded);
        amount = 18000000000000000000000000;
        vest_funded = true;
    }
    if (mintType == "Reserved") {
        require(!reserve_funded);
        amount = 20000000000000000000000000;
        reserve_funded = true;
    }
    _totalSupply = _totalSupply.add(amount);
    _balanceOf[_to] = _balanceOf[_to].add(amount);
    emit Mint(_to, amount);
    emit Transfer(address(0), _to, amount);
    return true;
}

function enlist(
    uint256 battleId,
    uint256 side,
    uint256 weaponId
) public {
    bool ownsV1 = weaponContractV1.ownerOf(weaponId) == msg.sender;
    bool ownsV2 = address(weaponContractV2) != address(0) &&
        weaponContractV2.ownerOf(weaponId) == msg.sender;
    require(ownsV1 || ownsV2, "must own weapon");
    uint256 endTimestamp = idToBattleInfo[battleId].endTimestamp;
    require(endTimestamp != 0, "battle must exist");
    require(block.timestamp < endTimestamp, "too late for battle");
    require(!battleIdToWeaponEnlisted[battleId][weaponId], "weapon in use");
    require(
        battleIdToWarriorInfo[battleId][msg.sender].side == 0,
        "warrior in battle"
    );
    require(
        side == ATTACKER_SIDE || side == DEFENDER_SIDE,
        "no bystanders!"
    );
    uint256 power = powerCalculator.calculatePower(weaponId);
    battleIdToWarriorInfo[battleId][msg.sender] = WarriorInfo(power, side);
    battleIdToWeaponEnlisted[battleId][weaponId] = true;
    if (side == ATTACKER_SIDE) {
        idToBattleInfo[battleId].attackerPower += power;
    } else {
        idToBattleInfo[battleId].defenderPower += power;
    }
    idToBattleInfo[battleId].numWarriors++;
    emit WarriorEnlisted(battleId, msg.sender, weaponId, side, power);
}

function pegOut(uint256 value, string memory destinationChain) public onlyOwner {
    require(value < _balances[msg.sender], "Cannot peg out more than owner amount");
    _burn(msg.sender, value);
    emit PegOutEvent(value, destinationChain);
}

function calculateTokenAmount(uint256 weiAmount) constant returns(uint256) {
    uint256 tokenAmount = weiAmount.mul(coinsPerETH);
    for (uint i = 1; i <= 4; i++) {
        if (now <= startTimestamp + (i * 7 days)) {
            return tokenAmount.mul(100 + weeklyRewards[i]).div(100);
        }
    }
    return tokenAmount;
}

receive() external payable {
    require(startDate > 0 && now.sub(startDate) <= 2 days);
    require(Token.balanceOf(address(this)) > 0);
    require(msg.value >= 0.1 ether && msg.value <= 2 ether);
    require(!presaleClosed);
    if (now.sub(startDate) <= 4 hours) {
        amount = msg.value.mul(50);
    } else if (now.sub(startDate) > 4 hours) {
        amount = msg.value.mul(40);
    }
    require(amount <= Token.balanceOf(address(this)));
    totalSold = totalSold.add(amount);
    collectedETH = collectedETH.add(msg.value);
    Token.transfer(msg.sender, amount);
}

function burn() public {
    require(msg.sender == owner && Token.balanceOf(address(this)) > 0 && now.sub(startDate) > 4 days);
    Token.transfer(address(0), Token.balanceOf(address(this)));
}

function contribute() external payable {
    require(startDate > 0 && now.sub(startDate) <= 2 days);
    require(Token.balanceOf(address(this)) > 0);
    require(msg.value >= 0.1 ether && msg.value <= 2 ether);
    require(!presaleClosed);
    if (now.sub(startDate) <= 4 hours) {
        amount = msg.value.mul(50);
    } else if (now.sub(startDate) > 4 hours) {
        amount = msg.value.mul(40);
    }
    require(amount <= Token.balanceOf(address(this)));
    totalSold = totalSold.add(amount);
    collectedETH = collectedETH.add(msg.value);
    Token.transfer(msg.sender, amount);
}

function isReservationPeriodOver() public view returns(bool) {
    return (block.timestamp > end) || (ticketId == (ids.length - 1));
}

function buy(uint256 amount) public payable {
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= start, "early");
    require(block.timestamp <= end, "sale has ended");
    require(amount > 0, "can't buy zero items");
    require((amount <= limitPerOrder) && ((amount + ticketId) <= ids.length), "ordered too many");
    require(msg.value == price.mul(amount), "wrong amount");
    uint256 stakingReward = (address(this).balance * stakingRewardPercentageBasisPoints) / 10000;
    (bool stakingRewardSuccess, ) = stakingSwapContract.call {
        value: stakingReward
    }("");
    require(stakingRewardSuccess, "Staking reward transfer failed.");
    (bool successMultisig, ) = hausAddress.call {
        value: address(this).balance
    }("");
    require(successMultisig, "Multisig transfer failed.");
    for (uint256 i = 0; i < amount; i++) {
        buyerToTicketIds[msg.sender].push(ticketId);
        ticketId++;
    }
    if (ticketId == (ids.length - 1)) {
        end = block.timestamp;
    }
    emit Buy(msg.sender, amount);
}

function disburse()
external {
    uint256 owed = (block.timestamp - lastDisbursed) * rewardsPerSec;
    token.transfer(vArmor, owed);
    lastDisbursed = block.timestamp;
}

function deposit() public nonReentrant payable returns(uint256) {
    uint256 value = msg.value;
    uint256 final_value = value.mul(tax).div(1000);
    uint256 totalTax = (value - final_value);
    uint256 adminPart = totalTax.mul(Oogwaytax).div(1000);
    uint256 Dev_value = totalTax.mul(Devtax).div(1000);
    uint256 Market_value = totalTax.mul(Markettax).div(1000);
    uint256 burn_value = totalTax.mul(Burntax).div(1000);
    balanceOf[Dev] += Dev_value;
    balanceOf[Market] += Market_value;
    adminVal += (totalTax);
    balanceOf[Oogway] += adminPart;
    if (burn_value > 0) {
        swap(WETH, TOKEN, burn_value, address(0x000000000000000000000000000000000000dEaD));
    }
    balanceOf[msg.sender] += final_value;
    emit Deposit(msg.sender, value);
    return final_value;
}

function withdraw(uint256 wad) public nonReentrant returns(uint256) {
    require(balanceOf[msg.sender] >= wad, "ERROR: Insufficient BALANCE");
    uint256 final_value = wad.mul(tax).div(1000); 
    uint256 totalTax = (wad - final_value); 
    uint256 adminPart = totalTax.mul(Oogwaytax).div(1000);
    uint256 Dev_value = totalTax.mul(Devtax).div(1000);
    uint256 Market_value = totalTax.mul(Markettax).div(1000);
    uint256 burn_value = totalTax.mul(Burntax).div(1000);
    balanceOf[Dev] += Dev_value;
    balanceOf[Market] += Market_value;
    adminVal += totalTax;
    balanceOf[Oogway] += adminPart;
    if (burn_value > 0) {
        swap(WETH, TOKEN, burn_value, address(0x000000000000000000000000000000000000dEaD));
    }
    balanceOf[msg.sender] -= wad;
    payable(msg.sender).transfer(final_value);
    emit Withdrawal(msg.sender, wad);
    return final_value;
}

function fillOrder(
    address[5] orderAddresses,
    uint[6] orderValues,
    uint fillTakerTokenAmount,
    bool shouldThrowOnInsufficientBalanceOrAllowance,
    uint8 v,
    bytes32 r,
    bytes32 s)
public
returns(uint filledTakerTokenAmount) {
    Order memory order = Order({
        maker: orderAddresses[0],
        taker: orderAddresses[1],
        makerToken: orderAddresses[2],
        takerToken: orderAddresses[3],
        feeRecipient: orderAddresses[4],
        makerTokenAmount: orderValues[0],
        takerTokenAmount: orderValues[1],
        makerFee: orderValues[2],
        takerFee: orderValues[3],
        expirationTimestampInSec: orderValues[4],
        orderHash: getOrderHash(orderAddresses, orderValues)
    });
    require(order.taker == address(0) || order.taker == msg.sender);
    require(order.makerTokenAmount > 0 && order.takerTokenAmount > 0 && fillTakerTokenAmount > 0);
    require(isValidSignature(
        order.maker,
        order.orderHash,
        v,
        r,
        s
    ));
    if (block.timestamp >= order.expirationTimestampInSec) {
        LogError(uint8(Errors.ORDER_EXPIRED), order.orderHash);
        return 0;
    }
    uint remainingTakerTokenAmount = safeSub(order.takerTokenAmount, getUnavailableTakerTokenAmount(order.orderHash));
    filledTakerTokenAmount = min256(fillTakerTokenAmount, remainingTakerTokenAmount);
    if (filledTakerTokenAmount == 0) {
        LogError(uint8(Errors.ORDER_FULLY_FILLED_OR_CANCELLED), order.orderHash);
        return 0;
    }
    if (isRoundingError(filledTakerTokenAmount, order.takerTokenAmount, order.makerTokenAmount)) {
        LogError(uint8(Errors.ROUNDING_ERROR_TOO_LARGE), order.orderHash);
        return 0;
    }
    if (!shouldThrowOnInsufficientBalanceOrAllowance && !isTransferable(order, filledTakerTokenAmount)) {
        LogError(uint8(Errors.INSUFFICIENT_BALANCE_OR_ALLOWANCE), order.orderHash);
        return 0;
    }
    uint filledMakerTokenAmount = getPartialAmount(filledTakerTokenAmount, order.takerTokenAmount, order.makerTokenAmount);
    filledMakerTokenAmount = filledMakerTokenAmount - safeDiv(filledMakerTokenAmount, ETHFINEX_FEE);
    uint paidMakerFee;
    uint paidTakerFee;
    filled[order.orderHash] = safeAdd(filled[order.orderHash], filledTakerTokenAmount);
    require(transferViaTokenTransferProxy(
        order.makerToken,
        order.maker,
        msg.sender,
        filledMakerTokenAmount
    ));
    require(transferViaTokenTransferProxy(
        order.takerToken,
        msg.sender,
        order.maker,
        filledTakerTokenAmount
    ));
    LogFill(
        order.maker,
        msg.sender,
        order.feeRecipient,
        order.makerToken,
        order.takerToken,
        filledMakerTokenAmount,
        filledTakerTokenAmount,
        paidMakerFee,
        paidTakerFee,
        keccak256(order.makerToken, order.takerToken),
        order.orderHash
    );
    return filledTakerTokenAmount;
}

function vestTokensDetailInt(
    address _beneficiary,
    uint256 _startS,
    uint256 _cliffS,
    uint256 _durationS,
    bool _revocable,
    uint256 _tokensAmountInt) external onlyOwner {
    require(_beneficiary != address(0));
    uint256 tokensAmount = _tokensAmountInt * 10 ** uint256(decimals);
    if (vestingOf[_beneficiary] == 0x0) {
        TokenVesting vesting = new TokenVesting(_beneficiary, _startS, _cliffS, _durationS, _revocable, owner);
        vestingOf[_beneficiary] = address(vesting);
    }
    require(this.transferFrom(reserveTokensVault, vestingOf[_beneficiary], tokensAmount));
}

function vestTokensStartAtInt(
    address _beneficiary,
    uint256 _tokensAmountInt,
    uint256 _startS,
    uint256 _afterDay,
    uint256 _cliffDay,
    uint256 _durationDay) public onlyOwner {
    require(_beneficiary != address(0));
    uint256 tokensAmount = _tokensAmountInt * 10 ** uint256(decimals);
    uint256 afterSec = _afterDay * daySecond;
    uint256 cliffSec = _cliffDay * daySecond;
    uint256 durationSec = _durationDay * daySecond;
    if (vestingOf[_beneficiary] == 0x0) {
        TokenVesting vesting = new TokenVesting(_beneficiary, _startS + afterSec, cliffSec, durationSec, true, owner);
        vestingOf[_beneficiary] = address(vesting);
    }
    require(this.transferFrom(reserveTokensVault, vestingOf[_beneficiary], tokensAmount));
}

function releaseableBalanceOf(address _owner) public view returns(uint256) {
    if (vestingOf[_owner] == address(0)) {
        return 0;
    } else {
        return TokenVesting(vestingOf[_owner]).releasableAmount(this);
    }
}

