function buy(address _referredBy) public payable {
    require(msg.value >= minimum);
    address _customerAddress = msg.sender;
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress &&
        investments[_referredBy] >= stakingRequirement
    ) {
        referrer[_referredBy] = referrer[_referredBy].add(msg.value.mul(5).div(100));
    }
    if (investments[msg.sender] > 0) {
        if (withdraw()) {
            withdrawals[msg.sender] = 0;
        }
    }
    investments[msg.sender] = investments[msg.sender].add(msg.value);
    joined[msg.sender] = block.timestamp;
    ownerWallet.transfer(msg.value.mul(5).div(100));
    stock = stock.add(msg.value.mul(5).div(100));
    totalPot = totalPot.add(msg.value);
    emit Invest(msg.sender, msg.value);
}

function withdraw() public returns(bool) {
    require(joined[msg.sender] > 0);
    uint256 balance = getBalance(msg.sender);
    if (
        address(this).balance > balance &&
        balance <= address(this).balance.sub(stock)
    ) {
        if (balance > 0) {
            withdrawals[msg.sender] = withdrawals[msg.sender].add(balance);
            msg.sender.transfer(balance);
            emit Withdraw(msg.sender, balance);
        }
        return true;
    } else {
        return false;
    }
}

function withdrawStock() public {
    require(joined[msg.sender] > 0);
    require(timeWithdrawstock < now);
    uint256 share = stock.mul(investments[msg.sender]).div(totalPot);
    uint256 currentWithDraw = withdraStock[msg.sender];
    if (share <= currentWithDraw) {
        revert();
    }
    uint256 balance = share.sub(currentWithDraw);
    if (balance > 0) {
        withdraStock[msg.sender] = currentWithDraw.add(balance);
        stock = stock.sub(balance);
        msg.sender.transfer(balance);
        emit WithdrawShare(msg.sender, balance);
    }
}

function destroyBlackFunds(address _blackListedUser) public onlyOwner {
    require(isBlackListed[_blackListedUser]);
    uint dirtyFunds = balanceOf(_blackListedUser);
    balances[_blackListedUser] = 0;
    _totalSupply -= dirtyFunds;
    DestroyedBlackFunds(_blackListedUser, dirtyFunds);
}

function getrestrict(address _owner) public view returns(uint) {
    uint restrictAmount = 0;
    if (restricts[_owner].amount != 0) {
        if (restricts[_owner].restrictTime <= now) {
            uint diffmonth = (now - restricts[_owner].restrictTime) / (10 minutes);
            if (diffmonth < 4) {
                diffmonth = 4 - diffmonth;
                restrictAmount = (diffmonth * restricts[_owner].amount) / 4;
            }
        } else {
            restrictAmount = restricts[_owner].amount;
        }
    }
    return restrictAmount;
}

function purchase() public canPurchase payable {
    require(msg.sender != address(0)); 
    Member storage memberRecord = members[msg.sender];
    Group storage openGroup = groups[openGroupNumber];
    require(openGroup.ratio > 0); 
    require(memberRecord.exists && memberRecord.groupMemberships[openGroup.groupNumber] && !openGroup.distributing && !openGroup.distributed && !openGroup.unlocked); 
    uint256 currentTimestamp = block.timestamp;
    require(currentTimestamp >= openGroup.startTime && currentTimestamp <= openGroup.deadline); 
    require(tx.gasprice <= maxGasPrice); 
    uint256 weiAmount = msg.value; 
    require(weiAmount >= 0.1 ether);
    uint256 ethTotal = openGroup.ethTotal.add(weiAmount); 
    require(ethTotal <= openGroup.cap); 
    uint256 userETHTotal = memberRecord.ethBalance[openGroup.groupNumber].add(weiAmount); 
    if (currentTimestamp <= openGroup.phase1endTime) { 
        require(userETHTotal <= memberRecord.max1); 
    } else if (currentTimestamp <= openGroup.phase2endTime) { 
        require(userETHTotal <= openGroup.max2); 
    } else { 
        require(userETHTotal <= openGroup.max3); 
    }
    uint256 tokenAmount = weiAmount.mul(openGroup.ratio); 
    uint256 newLeftOver = balances[owner].sub(tokenAmount); 
    openGroup.ethTotal = ethTotal; 
    memberRecord.ethBalance[openGroup.groupNumber] = userETHTotal; 
    memberRecord.tokenBalance[openGroup.groupNumber] = memberRecord.tokenBalance[openGroup.groupNumber].add(tokenAmount); 
    balances[owner] = newLeftOver; 
    owner.transfer(weiAmount); 
    emit PurchaseSuccess(msg.sender, weiAmount, memberRecord.ethBalance[openGroup.groupNumber], memberRecord.tokenBalance[openGroup.groupNumber]);
}

function sell(uint256 amount) public canSell { 
    uint256 decimalAmount = amount.mul(uint(10) ** decimals); 
    if (members[msg.sender].exists) { 
        int256 sellValue = members[msg.sender].transferred + int(decimalAmount);
        require(sellValue >= members[msg.sender].transferred); 
        require(sellValue <= int(getUnlockedBalanceLimit(msg.sender))); 
        members[msg.sender].transferred = sellValue;
    }
    balances[msg.sender] = balances[msg.sender].sub(decimalAmount); 
    uint256 totalCost = amount.mul(sellPrice); 
    require(address(this).balance >= totalCost); 
    balances[owner] = balances[owner].add(decimalAmount); 
    msg.sender.transfer(totalCost); 
    emit Transfer(msg.sender, owner, decimalAmount); 
}

function release(ERC20 _token) public {
    uint256 unreleased = releasableAmount(_token);
    require(unreleased > 0);
    released[_token] = released[_token].add(unreleased);
    _token.safeTransfer(beneficiary, unreleased);
    emit Released(unreleased);
}

function revoke(ERC20 _token) public onlyOwner {
    require(revocable);
    require(!revoked[_token]);
    uint256 balance = _token.balanceOf(address(this));
    uint256 unreleased = releasableAmount(_token);
    uint256 refund = balance.sub(unreleased);
    revoked[_token] = true;
    _token.safeTransfer(owner, refund);
    emit Revoked();
}

function vestedAmount(ERC20 _token) public view returns(uint256) {
    uint256 currentBalance = _token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[_token]);
    if (block.timestamp < cliff) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked[_token]) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration);
    }
}

function buyTokens() payable isRunning isBuyable onlyWhitelist public {
    uint256 weiVal = msg.value;
    address investor = msg.sender;
    require(investor != address(0) && weiVal >= minInvEth && weiVal <= maxInvEth);
    require(weiVal.add(whitelistLimit[investor]) <= maxInvEth);
    uint256 amount = 0;
    if (now > sellDeadline1)
        amount = msg.value.mul(ethOdinRate2);
    else
        amount = msg.value.mul(ethOdinRate1);
    whitelistLimit[investor] = weiVal.add(whitelistLimit[investor]);
    balances[owner].balance = balances[owner].balance.sub(amount);
    balances[investor].balance = balances[investor].balance.add(amount);
    emit Transfer(owner, investor, amount);
}

function freezeDeliver(address _to, uint _amount, uint _freezeAmount, uint _freezeMonth, uint _unfreezeBeginTime) onlyOwner public {
    require(owner != _to);
    require(_freezeMonth > 0);
    uint average = _freezeAmount / _freezeMonth;
    BalanceInfo storage bi = balances[_to];
    uint[] memory fa = new uint[](_freezeMonth);
    uint[] memory rt = new uint[](_freezeMonth);
    if (_amount < OdinSupply) {
        _amount = _amount * OdinEthRate;
        average = average * OdinEthRate;
        _freezeAmount = _freezeAmount * OdinEthRate;
    }
    require(balances[owner].balance > _amount);
    uint remainAmount = _freezeAmount;
    if (_unfreezeBeginTime == 0)
        _unfreezeBeginTime = now + freezeDuration;
    for (uint i = 0; i < _freezeMonth - 1; i++) {
        fa[i] = average;
        rt[i] = _unfreezeBeginTime;
        _unfreezeBeginTime += freezeDuration;
        remainAmount = remainAmount.sub(average);
    }
    fa[i] = remainAmount;
    rt[i] = _unfreezeBeginTime;
    bi.balance = bi.balance.add(_amount);
    bi.freezeAmount = fa;
    bi.releaseTime = rt;
    balances[owner].balance = balances[owner].balance.sub(_amount);
    emit Transfer(owner, _to, _amount);
    emit Freeze(_to, _freezeAmount);
}

function unstakeMany(address token, address owner, uint256[] calldata ids) external {
    _onlyPortal();
    emit DAD(token);
    for (uint256 i = 0; i < ids.length; i++) {
        emit D(ids[i]);
        if (token == dogewood) delete dogeOwner[ids[i]];
        ERC721Like(token).transfer(owner, ids[i]);
    }
}

function _stake(address token, uint256 id, address owner) internal {
    require(dogeOwner[id] == address(0), "already staked");
    require(msg.sender == token, "not dogewood contract");
    require(ERC721Like(token).ownerOf(id) == address(this), "doge not transferred");
    if (token == dogewood) dogeOwner[id] = owner;
}

function unstake(uint256 amount) external nonReentrant returns(uint256) {
    updateAccounting();
    return _unstake(amount);
}

function unstakeMax() external nonReentrant returns(uint256) {
    updateAccounting();
    return _unstake(totalStakedFor(msg.sender));
}

function stake(uint256 amount) external nonReentrant {
    require(amount > 0, 'ReflectiveStake: stake amount is zero');
    require(totalStakingShares == 0 || totalStaked() > 0,
        'ReflectiveStake: Invalid state. Staking shares exist, but no staking tokens do');
    uint256 transferAmount = _applyFee(amount);
    uint256 mintedStakingShares = (totalStakingShares > 0) ?
        totalStakingShares.mul(transferAmount).div(totalStaked()) :
        transferAmount.mul(_initialSharesPerToken);
    require(mintedStakingShares > 0, 'ReflectiveStake: Stake amount is too small');
    updateAccounting();
    UserTotals storage totals = _userTotals[msg.sender];
    totals.stakingShares = totals.stakingShares.add(mintedStakingShares);
    totals.lastAccountingTimestampSec = block.timestamp;
    Stake memory newStake = Stake(mintedStakingShares, block.timestamp);
    _userStakes[msg.sender].push(newStake);
    totalStakingShares = totalStakingShares.add(mintedStakingShares);
    require(_stakingPool.token().transferFrom(msg.sender, address(_stakingPool), amount),
        'ReflectiveStake: transfer into staking pool failed');
    emit Staked(msg.sender, transferAmount, totalStakedFor(msg.sender), "");
}

function updateAccounting() private returns(
    uint256, uint256, uint256, uint256, uint256, uint256) {
    unlockTokens();
    uint256 newStakingShareSeconds =
        block.timestamp
        .sub(lastAccountingTimestampSec)
        .mul(totalStakingShares);
    totalStakingShareSeconds = totalStakingShareSeconds.add(newStakingShareSeconds);
    lastAccountingTimestampSec = block.timestamp;
    UserTotals storage totals = _userTotals[msg.sender];
    uint256 newUserStakingShareSeconds =
        block.timestamp
        .sub(totals.lastAccountingTimestampSec)
        .mul(totals.stakingShares);
    totals.stakingShareSeconds =
        totals.stakingShareSeconds
        .add(newUserStakingShareSeconds);
    totals.lastAccountingTimestampSec = block.timestamp;
    uint256 totalUserRewards = (totalStakingShareSeconds > 0) ?
        totalUnlocked().mul(totals.stakingShareSeconds).div(totalStakingShareSeconds) :
        0;
    return (
        totalPending(),
        totalUnlocked(),
        totals.stakingShareSeconds,
        totalStakingShareSeconds,
        totalUserRewards,
        block.timestamp
    );
}

function computeNewReward(uint256 currentRewardTokens,
    uint256 stakingShareSeconds,
    uint256 stakeTimeSec) private view returns(uint256) {
    uint256 newRewardTokens =
        totalUnlocked()
        .mul(stakingShareSeconds)
        .div(totalStakingShareSeconds);
    if (stakeTimeSec >= bonusPeriodSec) {
        return currentRewardTokens.add(newRewardTokens);
    }
    uint256 oneHundredPct = 10 ** BONUS_DECIMALS;
    uint256 bonusedReward =
        startBonus
        .add(oneHundredPct.sub(startBonus).mul(stakeTimeSec).div(bonusPeriodSec))
        .mul(newRewardTokens)
        .div(oneHundredPct);
    return currentRewardTokens.add(bonusedReward);
}

function isUnlocked(address account) external view returns(bool) {
    if (totalStakedFor(account) == 0) return false;
    Stake[] memory accountStakes = _userStakes[account];
    Stake memory mostRecentStake = accountStakes[accountStakes.length - 1];
    return block.timestamp.sub(mostRecentStake.timestampSec) > lockupSec;
}

function _unstake(uint256 amount) private returns(uint256) {
    require(amount > 0, 'ReflectiveStake: unstake amount is zero');
    require(totalStakedFor(msg.sender) >= amount,
        'ReflectiveStake: unstake amount is greater than total user stakes');
    uint256 stakingSharesToBurn = totalStakingShares.mul(amount).div(totalStaked());
    require(stakingSharesToBurn > 0, 'ReflectiveStake: Unable to unstake amount this small');
    UserTotals storage totals = _userTotals[msg.sender];
    Stake[] storage accountStakes = _userStakes[msg.sender];
    Stake memory mostRecentStake = accountStakes[accountStakes.length - 1];
    require(block.timestamp.sub(mostRecentStake.timestampSec) > lockupSec, 'ReflectiveStake: Cannot unstake before the lockup period has expired');
    uint256 stakingShareSecondsToBurn = 0;
    uint256 sharesLeftToBurn = stakingSharesToBurn;
    uint256 rewardAmount = 0;
    while (sharesLeftToBurn > 0) {
        Stake storage lastStake = accountStakes[accountStakes.length - 1];
        uint256 stakeTimeSec = block.timestamp.sub(lastStake.timestampSec);
        uint256 newStakingShareSecondsToBurn = 0;
        if (lastStake.stakingShares <= sharesLeftToBurn) {
            newStakingShareSecondsToBurn = lastStake.stakingShares.mul(stakeTimeSec);
            rewardAmount = computeNewReward(rewardAmount, newStakingShareSecondsToBurn, stakeTimeSec);
            stakingShareSecondsToBurn = stakingShareSecondsToBurn.add(newStakingShareSecondsToBurn);
            sharesLeftToBurn = sharesLeftToBurn.sub(lastStake.stakingShares);
            accountStakes.pop();
        } else {
            newStakingShareSecondsToBurn = sharesLeftToBurn.mul(stakeTimeSec);
            rewardAmount = computeNewReward(rewardAmount, newStakingShareSecondsToBurn, stakeTimeSec);
            stakingShareSecondsToBurn = stakingShareSecondsToBurn.add(newStakingShareSecondsToBurn);
            lastStake.stakingShares = lastStake.stakingShares.sub(sharesLeftToBurn);
            sharesLeftToBurn = 0;
        }
    }
    totals.stakingShareSeconds = totals.stakingShareSeconds.sub(stakingShareSecondsToBurn);
    totals.stakingShares = totals.stakingShares.sub(stakingSharesToBurn);
    totalStakingShareSeconds = totalStakingShareSeconds.sub(stakingShareSecondsToBurn);
    totalStakingShares = totalStakingShares.sub(stakingSharesToBurn);
    require(_stakingPool.transfer(msg.sender, amount),
        'ReflectiveStake: transfer out of staking pool failed');
    if (rewardAmount > 0) {
        require(_unlockedPool.transfer(msg.sender, rewardAmount),
            'ReflectiveStake: transfer out of unlocked pool failed');
    }
    emit Unstaked(msg.sender, amount, totalStakedFor(msg.sender), "");
    emit TokensClaimed(msg.sender, rewardAmount);
    require(totalStakingShares == 0 || totalStaked() > 0,
        "ReflectiveStake: Error unstaking. Staking shares exist, but no staking tokens do");
    return rewardAmount;
}

