function payout(Deposit deposit) private {
    var (gains, fees) = computeGains(deposit);
    bool success = false;
    bool feesSuccess = false;
    uint payableAmount = deposit.amount + gains;
    address currentDepositor = deposit.depositor;
    if (gains > 0 && this.balance > payableAmount) {
        success = currentDepositor.send(payableAmount);
        if (success) {
            Payout(currentDepositor, payableAmount);
            addNewPayout(PayoutItem(currentDepositor, payableAmount));
            feesSuccess = master.send(fees);
            if (feesSuccess) {
                FeesPayout(fees);
            }
            resetBonuses(currentDepositor);
            addressGains[currentDepositor] += gains;
            totalGains += gains;
            currentPayoutIndex++;
        }
    }
}

function _lock(address to, uint256 value, uint256 time) internal {
    require(EST.transferFrom(msg.sender, address(this), value));
    vault memory v;
    v.amount = value;
    v.unlockTime = time;
    vaults[to].push(v);
    emit Lock(to, value, time);
}

function revoke(address to, uint256 index) public onlyOwner {
    vault storage v = vaults[to][index];
    require(now >= v.unlockTime);
    require(!v.claimed);
    v.claimed = true;
    require(EST.transfer(msg.sender, v.amount));
    emit Revoke(to, index);
}

function redeem(uint256 index) external {
    vault storage v = vaults[msg.sender][index];
    require(now >= v.unlockTime);
    require(!v.claimed);
    v.claimed = true;
    require(EST.transfer(msg.sender, v.amount));
    emit Redeem(msg.sender, index);
}

