    Transfer(msg.sender, this, amount);
}

function onEtherReceived() internal {
    uint256 receivedEther = msg.value;
    address buyer = msg.sender;
    uint256 phase = preSalePhase();
    require(phase == 1 || phase == 2, "preSale not started or ended");
    uint256 amount;
    if (phase == 1) {
        amount = phaseIR.mul(receivedEther);
        if (amount.add(_totalSold) > phaseIQ) {
            uint256 leftQ = phaseIQ.sub(_totalSold);
            amount = receivedEther.sub(leftQ.div(phaseIR)).mul(phaseIIR).add(leftQ);
        }
    } else {
        amount = phaseIIR.mul(receivedEther);
        if (amount.add(_totalSold) > phaseIIQ) {
            amount = phaseIIQ.sub(_totalSold);
            msg.sender.transfer(receivedEther.sub(amount.div(phaseIIR)));
            receivedEther = amount.div(phaseIIR);
        }
    }
    ethReceiver.transfer(receivedEther);
    _mint(buyer, amount);
    _totalSold = _totalSold.add(amount);
    emit OnEtherReceived(buyer, receivedEther, amount);
}

function preSalePhase() public view returns(uint256) {
    uint256 now_ = block.timestamp;
    if (now_ < preSaleStart) {
        return 0;
    }
    if (now_ > preSaleStart.add(2 * duration) || _totalSold >= phaseIIQ) {
        return 3;
    }
    return _totalSold >= phaseIQ || now_ > preSaleStart.add(duration) ? 2 : 1;
}

function mint() public whenStarted {
    uint256 unminted = mintableAmount();
    require(unminted > 0);
    minted = minted.add(unminted);
    BSPToken.safeTransfer(distributor, unminted);
    emit Mint(unminted);
}

function mintableAmount() public view returns(uint256) {
    if (started == false || startTime >= block.timestamp) {
        return 0;
    }
    if (block.timestamp >= startTime.add(duration)) {
        return BSPToken.balanceOf(this);
    }
    uint currentYear = block.timestamp.sub(startTime).div(1 years);
    uint currentDay = (block.timestamp.sub(startTime) % (1 years)).div(1 days);
    uint currentMintable = 0;
    for (uint i = 0; i < currentYear; i++) {
        currentMintable = currentMintable.add(rewardAmount.mul(miningRate[i]).div(100));
    }
    currentMintable = currentMintable.add(rewardAmount.mul(miningRate[currentYear]).div(36500).mul(currentDay));
    return currentMintable.sub(minted);
}

function startMining(uint256 _startTime) public onlyOwner {
    require(started == false && BSPToken.balanceOf(this) >= rewardAmount);
    require(_startTime >= block.timestamp);
    require(_startTime <= block.timestamp + 60 days);
    startTime = _startTime;
    started = true;
}

