function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 5 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 20 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 50 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 100 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 20 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 50 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 500e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

function _vote(uint8 opinion, uint112 addedVoteAmt) private {
    require(_YES <= opinion && opinion <= _NO, "GraSwapGov: INVALID_OPINION");
    require(addedVoteAmt > 0, "GraSwapGov: ZERO_VOTE_AMOUNT");
    (uint24 currProposalID, uint24 votedProposalID,
        uint8 votedOpinion, uint112 votedAmt, uint112 depositedAmt) = _getVoterInfo();
    bool isRevote = false;
    if ((votedProposalID == currProposalID) && (votedOpinion != opinion)) {
        if (votedOpinion == _YES) {
            assert(_totalYes >= votedAmt);
            _totalYes -= votedAmt;
        } else {
            assert(_totalNo >= votedAmt);
            _totalNo -= votedAmt;
        }
        votedAmt = 0;
        isRevote = true;
    }
    assert(depositedAmt >= votedAmt);
    if (addedVoteAmt > depositedAmt - votedAmt) {
        uint112 moreDeposit = addedVoteAmt - (depositedAmt - votedAmt);
        depositedAmt += moreDeposit;
        _totalDeposit += moreDeposit;
        IERC20(graContract).transferFrom(msg.sender, address(this), moreDeposit);
    }
    if (opinion == _YES) {
        _totalYes += addedVoteAmt;
    } else {
        _totalNo += addedVoteAmt;
    }
    votedAmt += addedVoteAmt;
    _setVoterInfo(currProposalID, opinion, votedAmt, depositedAmt);
    if (isRevote) {
        emit Revote(currProposalID, msg.sender, opinion, addedVoteAmt);
    } else if (votedAmt > addedVoteAmt) {
        emit AddVote(currProposalID, msg.sender, opinion, addedVoteAmt);
    } else {
        emit NewVote(currProposalID, msg.sender, opinion, addedVoteAmt);
    }
}

function submitTextProposal(string calldata title, string calldata desc, string calldata url,
    uint112 voteAmt) external override {
    require(uint256(_deadline) + _TEXT_PROPOSAL_INTERVAL < block.timestamp,
        "GraSwapGov: COOLING_DOWN");
    _newProposal(_PROPOSAL_TYPE_TEXT, address(0), 0, voteAmt);
    emit NewTextProposal(_proposalID, title, desc, url, _deadline);
    _vote(_YES, voteAmt);
}

function vote(uint8 opinion, uint112 voteAmt) external override {
    require(_proposalType > 0, "GraSwapGov: NO_PROPOSAL");
    require(uint256(_deadline) > block.timestamp, "GraSwapGov: DEADLINE_REACHED");
    _vote(opinion, voteAmt);
}

function tally() external override {
    require(_proposalType > 0, "GraSwapGov: NO_PROPOSAL");
    require(uint256(_deadline) <= block.timestamp, "GraSwapGov: STILL_VOTING");
    bool ok = _totalYes > _totalNo;
    uint8 _type = _proposalType;
    uint256 val = _value;
    address addr = _addr;
    address proposer = _proposer;
    _resetProposal();
    if (ok) {
        _execProposal(_type, addr, val);
    } else {
        _taxProposer(proposer);
    }
    emit TallyResult(_proposalID, ok);
}

function ClaimStakedTokens() external {
    require(users[msg.sender].activeDeposit > 0, "no running stake");
    uint256 _penaltyFee = 0;
    if (users[msg.sender].startTime + latestStakingPeriod() > now) { 
        _penaltyFee = penaltyFee;
    }
    uint256 toTransfer = users[msg.sender].activeDeposit.sub(_onePercent(users[msg.sender].activeDeposit).mul(_penaltyFee));
    require(ERC20Interface(MIKI).transfer(msg.sender, toTransfer));
    users[msg.sender].pendingGains = pendingReward(msg.sender);
    emit TokensClaimed(msg.sender, toTransfer);
    users[msg.sender].activeDeposit = 0;
}

function ClaimReward() public {
    require(pendingReward(msg.sender) > 0, "nothing pending to claim");
    require(ERC20Interface(MIKI).transfer(msg.sender, pendingReward(msg.sender)));
    emit RewardClaimed(msg.sender, pendingReward(msg.sender));
    totalRewards = totalRewards.add(pendingReward(msg.sender));
    users[msg.sender].totalGained = users[msg.sender].totalGained.add(pendingReward(msg.sender));
    users[msg.sender].lastClaimedDate = now;
    users[msg.sender].pendingGains = 0;
}

function pendingReward(address _caller) public view returns(uint256 _pendingReward) {
    uint256 _totalStakedTime = 0;
    uint256 expiryDate = (latestStakingPeriod()).add(users[_caller].startTime);
    if (now < expiryDate)
        _totalStakedTime = now.sub(users[_caller].lastClaimedDate);
    else {
        if (users[_caller].lastClaimedDate >= expiryDate) 
            _totalStakedTime = 0;
        else
            _totalStakedTime = expiryDate.sub(users[_caller].lastClaimedDate);
    }
    uint256 _reward_token_second = ((latestStakingRate()).mul(10 ** 21)).div(365 days); 
    uint256 reward = ((users[_caller].activeDeposit).mul(_totalStakedTime.mul(_reward_token_second))).div(10 ** 23); 
    return (reward.add(users[_caller].pendingGains));
}

function latestStakingRate() public view returns(uint256 APY) {
    uint256 yearOfContract = (((block.timestamp).sub(contractStartDate)).div(365 days)).add(1);
    uint256 rate;
    if (yearOfContract == 1)
        rate = firstYearRate;
    else if (yearOfContract == 2)
        rate = secondYearRate;
    else
        rate = afterSecondYearRate;
    return rate;
}

function stakingTimeLeft(address _user) public view returns(uint256 _secsLeft) {
    if (users[_user].activeDeposit > 0) {
        uint256 left = 0;
        uint256 expiryDate = (latestStakingPeriod()).add(StakedOn(_user));
        if (now < expiryDate)
            left = expiryDate.sub(now);
        return left;
    } else
        return 0;
}

function latestStakingPeriod() public view returns(uint256 Period) {
    uint256 yearOfContract = (((block.timestamp).sub(contractStartDate)).div(365 days)).add(1);
    uint256 period;
    if (yearOfContract == 1)
        period = firstYearStakingPeriod;
    else if (yearOfContract == 2)
        period = secondYearStakingPeriod;
    else
        period = afterSecondYearStakingPeriod;
    return period;
}

