function ludumTokensPerEther() constant returns(uint) {
    if (now < crowdsaleStart || now > crowdsaleEnd) {
        return 0;
    } else {
        if (now < crowdsaleStart + 1 minutes) return 15000; 
        if (now < crowdsaleStart + 7 minutes) return 13000; 
        if (now < crowdsaleStart + 14 minutes) return 11000; 
        return 10000; 
    }
}

