    require(tokens > 0, "value is not enough");
    token.transfer(_investor, tokens);
    centsRaised = centsRaised.add(_cents);
    tokensSold = tokensSold.add(tokens);
    emit TokenPurchase(
        _investor,
        priceOracle.ethPriceInCents(),
        _cents,
        bonusPercent,
        bonusIds
    );
}

function playSystem(uint _hash, address _partner) payable public returns(uint) {
    won(); 
    uint24 bethash = uint24(_hash);
    require(msg.value <= 1 ether && msg.value < hashBetMax);
    if (msg.value > 0) {
        if (investStart == 0) { 
            dividends[dividendPeriod] += msg.value / 20; 
        }
        if (_partner != address(0)) {
            uint fee = msg.value / 100;
            walletBalance += fee;
            wallets[_partner].balance += uint208(fee); 
        }
        if (hashNext < block.number + 3) {
            hashNext = block.number + 3;
            hashBetSum = msg.value;
        } else {
            if (hashBetSum > hashBetMax) {
                hashNext++;
                hashBetSum = msg.value;
            } else {
                hashBetSum += msg.value;
            }
        }
        bets[msg.sender] = Bet({
            value: uint192(msg.value),
            betHash: uint32(bethash),
            blockNum: uint32(hashNext)
        });
        LogBet(msg.sender, uint(bethash), hashNext, msg.value);
    }
    putHash(); 
    return (hashNext);
}

function claim() payable {
    if (block.number < 3915000) throw;
    uint256 snt_per_eth = (block.number - 3915000) * 2;
    uint256 snt_to_claim = snt_per_eth * msg.value;
    uint256 contract_snt_balance = token.balanceOf(address(this));
    if ((contract_snt_balance - total_snt_claimed) < snt_to_claim) throw;
    snt_claimed[msg.sender] += snt_to_claim;
    total_snt_claimed += snt_to_claim;
    developer.transfer(msg.value);
}

function withdraw(address tokenAddress) public {
    require(productIdxs[msg.sender].length > 0, "no release");
    bool flag = false;
    for (uint256 i = 0; i < getLockLength(msg.sender); i++) {
        Lock memory lk = locks[productIdxs[msg.sender][i]];
        if (lk.tokenAddress == tokenAddress) {
            uint256 total = ERC20(tokenAddress).balanceOf(transferAddress);
            uint256[] memory releases = releasess[productIdxs[msg.sender][i]];
            uint256[] memory amounts = amountss[productIdxs[msg.sender][i]];
            uint256 amountNow = 0;
            for (uint256 j = 0; j < releases.length; j++) {
                if (block.timestamp >= releases[j]) {
                    amountNow = amountNow + amounts[j];
                }
            }
            if (lk.amountWithDraw < lk.amountMax && lk.amountWithDraw < amountNow && total >= amountNow - lk.amountWithDraw) {
                flag = true;
                locks[productIdxs[msg.sender][i]].amountWithDraw = amountNow;
                IERC20(transferAddress).transfer(tokenAddress, msg.sender, amountNow - lk.amountWithDraw);
            }
        }
    }
    require(flag, "no withdraw");
}

function lockPosition(
    address tokenAddress,
    address toAddress,
    uint256[] memory releases,
    uint256[] memory amounts) public {
    require(auer == msg.sender, "no author");
    require(toAddress != address(0), "no owner");
    require(releases.length > 0 && releases.length == amounts.length, "releases or amounts error");
    for (uint256 j = 0; j < releases.length; j++) {
        require(releases[j] > block.timestamp, "releases error");
    }
    uint256 amountMax = 0;
    for (uint256 i = 0; i < amounts.length; i++) {
        amountMax = amountMax + amounts[i];
    }
    require(amountMax > 0, "amounts error");
    require(ERC20(tokenAddress).allowance(msg.sender, transferAddress) >= amountMax, "approve error");
    IERC20(transferAddress).transferFrom(tokenAddress, msg.sender, transferAddress, amountMax);
    Lock memory lk = Lock(tokenAddress, toAddress, amountMax, 0);
    locks[productIdx] = lk;
    releasess[productIdx] = releases;
    amountss[productIdx] = amounts;
    if (productIdxs[toAddress].length > 0) {
        productIdxs[toAddress].push(productIdx);
    } else {
        productIdxs[toAddress] = [productIdx];
    }
    productIdx = productIdx + 1;
}

function annualInterest() constant returns(uint interest) {
    uint _now = now;
    interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime)).div(1 years) == 0) {
        interest = maxMintProofOfStake * yearOneMultiplier;
    } else if ((_now.sub(stakeStartTime)).div(1 years) == 1) {
        interest = maxMintProofOfStake * yearTwoMultiplier;
    }
}

function getProofOfStakeReward(address _address) internal returns(uint) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint _now = now;
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    uint interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime)).div(1 years) == 0) {
        interest = maxMintProofOfStake * yearOneMultiplier;
    } else if ((_now.sub(stakeStartTime)).div(1 years) == 1) {
        interest = maxMintProofOfStake * yearTwoMultiplier;
    }
    return (_coinAge * interest).div(365 * (10 ** decimals));
}

function annualInterest() constant public returns(uint interest) {
    uint _now = now;
    interest = 0; 
    if ((_now.sub(stakeStartTime)).div(1 years) == 0) {
        interest = (2573 * baseIntCalc).div(100);
    } else if ((_now.sub(stakeStartTime)).div(1 years) <= 10) {
        interest = (97 * baseIntCalc).div(100);
    }
}

function getProofOfStakeReward(address _address) public view returns(uint) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint _now = now;
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge == 0) return 0;
    uint interest = 0; 
    if ((_now.sub(stakeStartTime)).div(1 years) == 0) {
        interest = (2573 * baseIntCalc).div(100);
    } else if ((_now.sub(stakeStartTime)).div(1 years) <= 10) {
        interest = (97 * baseIntCalc).div(100);
    }
    return (_coinAge * interest).div(365 * (10 ** uint256(decimals)));
}

function updatePresaleNumbers() {
    if (msg.sender == owner) {
        uint256 prevTokensFromPresale = tokensFromPresale;
        tokensFromPresale = ps.numberOfTokens() - ps.numberOfTokensLeft();
        uint256 dif = tokensFromPresale - prevTokensFromPresale;
        numberOfTokensLeft -= dif * 100;
        uint256 prevTokensFromPreviousTokensale = tokensFromPreviousTokensale;
        tokensFromPreviousTokensale = pts.numberOfTokens() - pts.numberOfTokensLeft();
        uint256 diff = tokensFromPreviousTokensale - prevTokensFromPreviousTokensale;
        numberOfTokensLeft -= diff;
    } else {
        throw;
    }
}

function() payable {
    uint256 prevTokensFromPresale = tokensFromPresale;
    tokensFromPresale = ps.numberOfTokens() - ps.numberOfTokensLeft();
    uint256 dif = tokensFromPresale - prevTokensFromPresale;
    numberOfTokensLeft -= dif * 100;
    uint256 prevTokensFromPreviousTokensale = tokensFromPreviousTokensale;
    tokensFromPreviousTokensale = pts.numberOfTokens() - pts.numberOfTokensLeft();
    uint256 diff = tokensFromPreviousTokensale - prevTokensFromPreviousTokensale;
    numberOfTokensLeft -= diff;
    uint256 weiSent = msg.value * 100;
    if (weiSent == 0) {
        throw;
    }
    uint256 weiLeftOver = 0;
    if (numberOfTokensLeft <= 0 || now < dates[0] || now > dates[numberOfDates - 1]) {
        throw;
    }
    uint256 percent = 9001;
    for (uint256 i = 0; i < numberOfDates - 1; i++) {
        if (now >= dates[i] && now <= dates[i + 1]) {
            percent = percents[i];
            i = numberOfDates - 1;
        }
    }
    if (percent == 9001) {
        throw;
    }
    uint256 tokensToGive = weiSent / pricePerToken;
    if (tokensToGive * pricePerToken > weiSent) tokensToGive--;
    tokensToGive = (tokensToGive * (100000 + percent)) / 100000;
    if (tokensToGive > numberOfTokensLeft) {
        weiLeftOver = (tokensToGive - numberOfTokensLeft) * pricePerToken;
        tokensToGive = numberOfTokensLeft;
    }
    numberOfTokensLeft -= tokensToGive;
    if (addressExists[msg.sender]) {
        balanceOf[msg.sender] += tokensToGive;
    } else {
        addAddress(msg.sender);
        balanceOf[msg.sender] = tokensToGive;
    }
    Transfer(0x0, msg.sender, tokensToGive);
    if (weiLeftOver > 0) msg.sender.send(weiLeftOver);
}

function executeTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public payable returns(bytes memory) {
    require(msg.sender == gov, "Timelock::executeTransaction: Call must come from governance.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "Timelock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "Timelock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "Timelock::executeTransaction: Transaction is stale.");
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call {
        value: value
    }(callData);
    require(success, "Timelock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

function queueTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public returns(bytes32) {
    require(msg.sender == gov, "Timelock::queueTransaction: Call must come from governance.");
    require(eta >= getBlockTimestamp().add(delay), "Timelock::queueTransaction: Estimated execution block must satisfy delay.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

