function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(!_isBlacklisted[from] && !_isBlacklisted[to], "To or From address is blacklisted.");
    if (!isTradingEnabled) {
        require(_isExcluded[to] || _isExcluded[from], "Trading is not yet enabled. Be patient!");
    } else if (block.timestamp - startTime < 200 && from == uniswapV2Pair) {
        require(amount <= 50 ** 9 * (50 ** 18), "Over max buy amt.");
    } else if (to == uniswapV2Pair) {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();
        uint[] memory amounts = uniswapV2Router.getAmountsOut(amount, path);
        require(amounts[1] <= maxSellAmt);
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 swapTokens = contractTokenBalance.div(100);
        swapAndLiquify(swapTokens);
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (from == uniswapV2Pair) {
            fees = amount.mul(buyFee).div(1000);
        } else if (to == uniswapV2Pair) {
            fees = amount.mul(sellFee).div(1000);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

constructor(address socialRocketContract, uint256 duration) public {
    rocks = SocialRocketContrat(socialRocketContract);
    token = socialRocketContract;
    startVesting = now;
    require(duration > 0, "Vesting: duration is 0");
    require(startVesting.add(duration) > block.timestamp, "Vesting: final time is before current time");
    durationVesting = duration;
}

function vestedAmount() public view returns(uint256) {
    uint256 currentBalance = rocks.balanceOf(address(this));
    uint256 totalBalance = currentBalance.add(_released[address(token)]);
    if (block.timestamp >= startVesting.add(durationVesting)) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(startVesting)).div(durationVesting);
    }
}

function release() public onlyOwner {
    uint256 unreleased = releasableAmount();
    require(unreleased > 0, "No tokens are due");
    _released[address(token)] = _released[address(token)].add(unreleased);
    rocks.transfer(owner, unreleased);
}

function buyEditionForPodium(
    uint256 amount,
    uint256 editionId,
    address recipient
) internal returns(uint256) {
    require(
        amount >=
        ICrowdfundWithPodiumEditions(editions).editionPrice(editionId),
        "Unable purchase edition with available amount"
    );
    if (podiumStartTime == 0) {
        podiumStartTime = block.timestamp;
    }
    uint256 podiumEnds = podiumStartTime + podiumDuration;
    require(podiumEnds >= block.timestamp, "podium closed");
    if (podiumEnds < block.timestamp + PODIUM_TIME_BUFFER) {
        podiumDuration += block.timestamp + PODIUM_TIME_BUFFER - podiumEnds;
        emit PodiumDurationExtended(editionId);
    }
    return
    ICrowdfundWithPodiumEditions(editions).buyEdition(
        editionId,
        recipient
    );
}

