    uint256 currentBalance = 0;
    if (walletF[msg.sender] > 0) {
        uint256 unreleasedF = getReleasableBonusAmount(5, msg.sender);
        walletF[msg.sender] = safeSub(walletF[msg.sender], unreleasedF);
        currentBalance = safeAdd(currentBalance, unreleasedF);
        releasedF[msg.sender] = safeAdd(releasedF[msg.sender], unreleasedF);
    }
    if (walletG[msg.sender] > 0) {
        uint256 unreleasedG = getReleasableBonusAmount(6, msg.sender);
        walletG[msg.sender] = safeSub(walletG[msg.sender], unreleasedG);
        currentBalance = safeAdd(currentBalance, unreleasedG);
        releasedG[msg.sender] = safeAdd(releasedG[msg.sender], unreleasedG);
    }
    if (walletH[msg.sender] > 0) {
        uint256 unreleasedH = getReleasableBonusAmount(7, msg.sender);
        walletH[msg.sender] = safeSub(walletH[msg.sender], unreleasedH);
        currentBalance = safeAdd(currentBalance, unreleasedH);
        releasedH[msg.sender] = safeAdd(releasedH[msg.sender], unreleasedH);
    }
    require(currentBalance > 0);
    balances[msg.sender] = safeAdd(balances[msg.sender], currentBalance);
}

function debitWalletLMNO(address _walletAddress, uint256 token) external onlyDSTWalletLMNO returns(bool) {
    require(dstWalletLMNO != address(0));
    require(balances[_walletAddress] >= token && token > 0);
    totalSupply = safeAdd(totalSupply, token);
    balances[_walletAddress] = safeSub(balances[_walletAddress], token);
    return true;
}

function assignToken(address _investor, uint256 _tokens) external {
    require(_investor != address(0) && _tokens > 0);
    require(_tokens <= balances[msg.sender]);
    balances[msg.sender] = safeSub(balances[msg.sender], _tokens);
    totalSupply = safeAdd(totalSupply, _tokens);
    if (msg.sender == walletAddresses[0]) {
        walletA[_investor] = safeAdd(walletA[_investor], _tokens);
    } else if (msg.sender == walletAddresses[1]) {
        walletB[_investor] = safeAdd(walletB[_investor], _tokens);
    } else if (msg.sender == walletAddresses[2]) {
        walletC[_investor] = safeAdd(walletC[_investor], _tokens);
    } else if (msg.sender == walletAddresses[5]) {
        walletF[_investor] = safeAdd(walletF[_investor], _tokens);
    } else if (msg.sender == walletAddresses[6]) {
        walletG[_investor] = safeAdd(walletG[_investor], _tokens);
    } else if (msg.sender == walletAddresses[7]) {
        walletH[_investor] = safeAdd(walletH[_investor], _tokens);
    } else {
        revert();
    }
}

function withdrawToken() public {
    uint256 currentBalance = 0;
    if (walletA[msg.sender] > 0) {
        uint256 unreleasedA = getReleasableAmount(0, msg.sender);
        walletA[msg.sender] = safeSub(walletA[msg.sender], unreleasedA);
        currentBalance = safeAdd(currentBalance, unreleasedA);
        releasedA[msg.sender] = safeAdd(releasedA[msg.sender], unreleasedA);
    }
    if (walletB[msg.sender] > 0) {
        uint256 unreleasedB = getReleasableAmount(1, msg.sender);
        walletB[msg.sender] = safeSub(walletB[msg.sender], unreleasedB);
        currentBalance = safeAdd(currentBalance, unreleasedB);
        releasedB[msg.sender] = safeAdd(releasedB[msg.sender], unreleasedB);
    }
    if (walletC[msg.sender] > 0) {
        uint256 unreleasedC = getReleasableAmount(2, msg.sender);
        walletC[msg.sender] = safeSub(walletC[msg.sender], unreleasedC);
        currentBalance = safeAdd(currentBalance, unreleasedC);
        releasedC[msg.sender] = safeAdd(releasedC[msg.sender], unreleasedC);
    }
    require(currentBalance > 0);
    balances[msg.sender] = safeAdd(balances[msg.sender], currentBalance);
}

function transferFrom(address _from, address _to, uint _value) public returns(bool ok) {
    require(_from != 0 && _to != 0 && _value > 0);
    require(allowed[_from][msg.sender] >= _value && balances[_from] >= _value);
    balances[_from] = safeSub(balances[_from], _value);
    balances[_to] = safeAdd(balances[_to], _value);
    allowed[_from][msg.sender] = safeSub(allowed[_from][msg.sender], _value);
    Transfer(_from, _to, _value);
    return true;
}

function assignTokensWallet(address walletAddress, address investor, uint256 tokens) internal {
    require(tokens <= balances[walletAddress]);
    totalSupply = safeAdd(totalSupply, tokens);
    balances[walletAddress] = safeSub(balances[walletAddress], tokens);
    balances[investor] = safeAdd(balances[investor], tokens);
    Transfer(0, investor, tokens);
}

function getVestedAmount(uint256 _walletId, uint256 _totalBalance) public view returns(uint256) {
    uint256 cliff = allWalletConfig[_walletId].cliff;
    uint256 start = allWalletConfig[_walletId].start;
    uint256 duration = allWalletConfig[_walletId].duration;
    if (now < cliff) {
        return 0;
    } else if (now >= safeAdd(start, duration)) {
        return _totalBalance;
    } else {
        return safeDiv(safeMul(_totalBalance, safeSub(now, start)), duration);
    }
}

function holdedOf(address _owner) public view returns(uint256) {
    uint256 requiredTime = block.timestamp - holdTime;
    uint256 iValid = 0; 
    uint256 iNotValid = holded[_owner].length; 
    if (iNotValid == 0 
        ||
        holded[_owner].time[iValid] >= requiredTime) { 
        return 0;
    }
    uint256 i = iNotValid / 2; 
    while (i > iValid) { 
        if (holded[_owner].time[i] < requiredTime) {
            iValid = i; 
        } else {
            iNotValid = i; 
        }
        i = (iNotValid + iValid) / 2;
    }
    return holded[_owner].amount[iValid];
}

function stakeFor(address staker, uint pseudoAmount, bool tokenOrLiquidity) public {
    if (timeStakingInit == 0)
        timeStakingInit = block.timestamp;
    distributeRewards(tokenOrLiquidity);
    if (tokenOrLiquidity) {
        require(stakingBalancesLiquidity[staker] == 0, "Liquidity staking position already exists");
        ERC20(liquidityAddress).transferFrom(msg.sender, address(this), pseudoAmount);
        totalStakeDepositsLiquidity += pseudoAmount;
        stakingBalancesLiquidity[staker] = pseudoAmount;
        rewardPerStakeInitsLiquidity[staker] = rewardPerStakeTotalLiquidity;
        return;
    }
    require(stakingBalancesToken[staker] == 0, "Token staking position already exists");
    uint amount = pseudoAmount * 1e17 / Rebaser(rebaserAddress).orbiSupplyTotal();
    ERC20(tokenAddress).transferFrom(msg.sender, address(this), pseudoAmount);
    totalStakeDepositsToken += amount;
    stakingBalancesToken[staker] = amount;
    rewardPerStakeInitsToken[staker] = rewardPerStakeTotalToken;
}

function unstake(bool tokenOrLiquidity) public {
    withdraw(tokenOrLiquidity);
    if (tokenOrLiquidity) {
        require(stakingBalancesLiquidity[msg.sender] > 0, "No current liquidity staking position");
        ERC20(liquidityAddress).transfer(msg.sender, stakingBalancesLiquidity[msg.sender]);
        totalStakeDepositsLiquidity -= stakingBalancesLiquidity[msg.sender];
        stakingBalancesLiquidity[msg.sender] = 0;
        return;
    }
    require(stakingBalancesToken[msg.sender] > 0, "No current token staking position");
    ERC20(tokenAddress).transfer(msg.sender, stakingBalancesToken[msg.sender] * Rebaser(rebaserAddress).orbiSupplyTotal() / 1e17);
    totalStakeDepositsToken -= stakingBalancesToken[msg.sender];
    stakingBalancesToken[msg.sender] = 0;
}

function withdraw(bool tokenOrLiquidity) public {
    if (tokenOrLiquidity) {
        distributeRewards(tokenOrLiquidity);
        availableRewardsLiquidity[msg.sender] += (rewardPerStakeTotalLiquidity - rewardPerStakeInitsLiquidity[msg.sender]) * stakingBalancesLiquidity[msg.sender] / 10 ** (currentScaleLiquidity * 18);
        require(stakingBalancesLiquidity[msg.sender] > 0, "No liquidity rewards to withdraw");
        rewardPerStakeInitsLiquidity[msg.sender] = rewardPerStakeTotalLiquidity;
        uint withdrawAmountLiquidity = availableRewardsLiquidity[msg.sender] * Rebaser(rebaserAddress).orbiSupplyTotal() / 1e17;
        totalRewardsWithdrawnLiquidity += withdrawAmountLiquidity;
        ERC20(tokenAddress).transfer(msg.sender, withdrawAmountLiquidity);
        availableRewardsLiquidity[msg.sender] = 0;
        return;
    }
    distributeRewards(tokenOrLiquidity);
    availableRewardsToken[msg.sender] += (rewardPerStakeTotalToken - rewardPerStakeInitsToken[msg.sender]) * stakingBalancesToken[msg.sender] / 10 ** (currentScaleToken * 18);
    require(stakingBalancesToken[msg.sender] > 0, "No token rewards to withdraw");
    rewardPerStakeInitsToken[msg.sender] = rewardPerStakeTotalToken;
    uint withdrawAmountToken = availableRewardsToken[msg.sender] * Rebaser(rebaserAddress).orbiSupplyTotal() / 1e17;
    totalRewardsWithdrawnToken += withdrawAmountToken;
    ERC20(tokenAddress).transfer(msg.sender, withdrawAmountToken);
    availableRewardsToken[msg.sender] = 0;
}

function stake(uint pseudoAmount, bool tokenOrLiquidity) public {
    if (timeStakingInit == 0)
        timeStakingInit = block.timestamp;
    distributeRewards(tokenOrLiquidity);
    if (tokenOrLiquidity) {
        require(stakingBalancesLiquidity[msg.sender] == 0, "Liquidity staking position already exists");
        ERC20(liquidityAddress).transferFrom(msg.sender, address(this), pseudoAmount);
        totalStakeDepositsLiquidity += pseudoAmount;
        stakingBalancesLiquidity[msg.sender] = pseudoAmount;
        rewardPerStakeInitsLiquidity[msg.sender] = rewardPerStakeTotalLiquidity;
        return;
    }
    require(stakingBalancesToken[msg.sender] == 0, "Token staking position already exists");
    uint amount = pseudoAmount * 1e17 / Rebaser(rebaserAddress).orbiSupplyTotal();
    ERC20(tokenAddress).transferFrom(msg.sender, address(this), pseudoAmount);
    totalStakeDepositsToken += amount;
    stakingBalancesToken[msg.sender] = amount;
    rewardPerStakeInitsToken[msg.sender] = rewardPerStakeTotalToken;
}

function withdrawAll() public {
    withdraw(false);
    withdraw(true);
}

function updatePosition(uint amount, bool tokenOrLiquidity) public {
    unstake(tokenOrLiquidity);
    if (amount > 0)
        stake(amount, tokenOrLiquidity);
}

function distributeRewards(bool tokenOrLiquidity) internal {
    if (tokenOrLiquidity && totalStakeDepositsLiquidity > 0) {
        uint tokenEmissionDelta = getTheoreticalTokenEmission(tokenOrLiquidity) - lastRealTokenEmissionLiquidity;
        while (totalStakeDepositsLiquidity * 1e18 > tokenEmissionDelta * 10 ** (currentScaleLiquidity * 18)) {
            currentScaleLiquidity += 1;
            rewardPerStakeTotalLiquidity *= 1e18;
        }
        rewardPerStakeTotalLiquidity += tokenEmissionDelta * 10 ** (currentScaleLiquidity * 18) / totalStakeDepositsLiquidity;
        lastRealTokenEmissionLiquidity = getTheoreticalTokenEmission(tokenOrLiquidity);
    }
    if (!tokenOrLiquidity && totalStakeDepositsToken > 0) {
        uint tokenEmissionDelta = getTheoreticalTokenEmission(tokenOrLiquidity) - lastRealTokenEmissionToken;
        while (totalStakeDepositsToken * 1e18 > tokenEmissionDelta * 10 ** (currentScaleToken * 18)) {
            currentScaleToken += 1;
            rewardPerStakeTotalToken *= 1e18;
        }
        rewardPerStakeTotalToken += tokenEmissionDelta * 10 ** (currentScaleToken * 18) / totalStakeDepositsToken;
        lastRealTokenEmissionToken = getTheoreticalTokenEmission(tokenOrLiquidity);
    }
}

function getAllAvailableRewards(address staker) public view returns(uint) {
    if (totalStakeDepositsToken > 0 && totalStakeDepositsLiquidity > 0)
        return getAvailableRewards(false, staker) + getAvailableRewards(true, staker);
    if (totalStakeDepositsToken > 0)
        return getAvailableRewards(false, staker);
    if (totalStakeDepositsLiquidity > 0)
        return getAvailableRewards(true, staker);
    return 0;
}

function rewardTheoretical() public view returns(uint) {
    if (timeStakingInit == 0)
        return 0;
    return rewardMax - (rewardMax - rewardsLastRewardChange) * distributionConstant / (block.timestamp - timeStakingInit + distributionConstant - timeFromInitToLastRewardChange);
}

function reinvest() public {
    distributeRewards(false);
    availableRewardsToken[msg.sender] += (rewardPerStakeTotalToken - rewardPerStakeInitsToken[msg.sender]) * stakingBalancesToken[msg.sender] / 10 ** (currentScaleToken * 18);
    require(availableRewardsToken[msg.sender] > 0, "No rewards to reinvest");
    totalRewardsWithdrawnToken += availableRewardsToken[msg.sender] * Rebaser(rebaserAddress).orbiSupplyTotal() / 1e17;
    totalStakeDepositsToken += availableRewardsToken[msg.sender];
    stakingBalancesToken[msg.sender] += availableRewardsToken[msg.sender];
    availableRewardsToken[msg.sender] = 0;
    rewardPerStakeInitsToken[msg.sender] = rewardPerStakeTotalToken;
}

function getAvailableRewards(bool tokenOrLiquidity, address staker) public view returns(uint) {
    if (tokenOrLiquidity) {
        uint tokenEmissionDelta = getTheoreticalTokenEmission(tokenOrLiquidity) - lastRealTokenEmissionLiquidity;
        uint pseudoTotalStakeDepositsLiquidity = totalStakeDepositsLiquidity;
        uint pseudoCurrentScaleLiquidity = currentScaleLiquidity;
        uint pseudoRewardPerStakeTotalLiquidity = rewardPerStakeTotalLiquidity;
        while (pseudoTotalStakeDepositsLiquidity * 1e18 > tokenEmissionDelta * 10 ** (pseudoCurrentScaleLiquidity * 18)) {
            pseudoCurrentScaleLiquidity += 1;
            pseudoRewardPerStakeTotalLiquidity *= 1e18;
        }
        pseudoRewardPerStakeTotalLiquidity += tokenEmissionDelta * 10 ** (pseudoCurrentScaleLiquidity * 18) / pseudoTotalStakeDepositsLiquidity;
        uint pseudoAvailableRewardsLiquidity = availableRewardsLiquidity[staker] + (pseudoRewardPerStakeTotalLiquidity - rewardPerStakeInitsLiquidity[staker]) * stakingBalancesLiquidity[staker] / 10 ** (pseudoCurrentScaleLiquidity * 18);
        return pseudoAvailableRewardsLiquidity * Rebaser(rebaserAddress).orbiSupplyTotal() / 1e17;
    } else {
        uint tokenEmissionDelta = getTheoreticalTokenEmission(tokenOrLiquidity) - lastRealTokenEmissionToken;
        uint pseudoTotalStakeDepositsToken = totalStakeDepositsToken;
        uint pseudoCurrentScaleToken = currentScaleToken;
        uint pseudoRewardPerStakeTotalToken = rewardPerStakeTotalToken;
        while (pseudoTotalStakeDepositsToken * 1e18 > tokenEmissionDelta * 10 ** (pseudoCurrentScaleToken * 18)) {
            pseudoCurrentScaleToken += 1;
            pseudoRewardPerStakeTotalToken *= 1e18;
        }
        pseudoRewardPerStakeTotalToken += tokenEmissionDelta * 10 ** (pseudoCurrentScaleToken * 18) / pseudoTotalStakeDepositsToken;
        uint pseudoAvailableRewardsToken = availableRewardsToken[staker] + (pseudoRewardPerStakeTotalToken - rewardPerStakeInitsToken[staker]) * stakingBalancesToken[staker] / 10 ** (pseudoCurrentScaleToken * 18);
        return pseudoAvailableRewardsToken * Rebaser(rebaserAddress).orbiSupplyTotal() / 1e17;
    }
}

function acceptGovernance() external {
    require(msg.sender == pendingGovernance);
    require(block.timestamp > applyGovernance);
    governance = pendingGovernance;
}

function() external payable {
    if ((block.number - prtime[pr]) >= 5900) {
        pr.transfer(ths.balance / 100);
        prtime[pr] = block.number;
    }
    if (balance[msg.sender] != 0) {
        msg.sender.transfer(balance[msg.sender] / 100 * 5 * (block.number - paytime[msg.sender]) / 5900);
    }
    paytime[msg.sender] = block.number;
    balance[msg.sender] += msg.value;
}

function optIn() public returns(bool success) {
    require(migrateFrom != MigrationSource(0));
    User storage user = users[msg.sender];
    uint256 balance = migrateFrom.vacate(msg.sender);
    emit OptIn(msg.sender, balance);
    user.balance = user.balance.add(balance);
    totalSupply_ = totalSupply_.add(balance);
    return true;
}

function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    uint investment = balance / 2;
    balance = -investment;
    flmContract.buy.value(investment)();
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            participants[payoutOrder].payout -= payoutToSend;
            balance -= payoutToSend;
            if (!participants[payoutOrder].etherAddress.send(payoutToSend)) {
                participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)();
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
    }
}

function whitelisting() public returns(bool) {
    require(whiteliststatus == true, "Whitelisting is closed");
    require(whitelist[msg.sender] == false, "You have already whitelisted");
    require(ERC20Interface(conditiontoken).allowance(msg.sender, address(this)) >= _conditionAmount, "Inadequate allowance given to contract by you");
    require(ERC20Interface(conditiontoken).balanceOf(msg.sender) >= _conditionAmount, "You do not have sufficient amount of the condition token");
    ERC20Interface(conditiontoken).transferFrom(msg.sender, address(this), _conditionAmount);
    whitelist[msg.sender] = true;
    return true;
}

function refund() {
    if (isFinalized) throw;
    if (block.number <= icoEndBlock) throw;
    if (msg.sender == token.getOwner()) throw;
    uint256 userBalance = token.balanceOf(msg.sender);
    if (userBalance == 0) throw;
    uint256 userEthers = etherBlance[msg.sender];
    if (userEthers == 0) throw;
    etherBlance[msg.sender] = 0;
    if (!token.transferFrom(msg.sender, kairosOwner, userBalance)) throw;
    if (msg.sender.send(userEthers)) {
        Refund(msg.sender, userEthers);
    } else {
        etherBlance[msg.sender] = userEthers;
        RefundError(msg.sender, userEthers);
        throw;
    }
}

function() payable {
    if (isFinalized && msg.value <= 0) throw;
    if (block.number < icoStartBlock) throw;
    if (block.number > icoEndBlock) throw;
    etherBlance[msg.sender] += msg.value;
    uint256 val = msg.value;
    uint256 bonus = calcBonus(val);
    uint256 level2bonus = calcLevel2Bonus(val);
    uint256 tokens = msg.value.add(level2bonus).add(bonus).mul(exchangeRate);
    uint256 checkedSupply = totalSupply.add(tokens);
    totalSupply = checkedSupply;
    bool transfer = token.transferFrom(token.getOwner(), msg.sender, tokens);
    if (!transfer) {
        totalSupply = totalSupply.sub(tokens);
        throw;
    }
}

function getPercentage() private constant returns(uint) {
    uint duration = now.sub(icoStartTime);
    if (duration > 21 days) {
        return 0;
    } else if (duration <= 21 days && duration > 14 days) {
        return 1;
    } else if (duration <= 14 days && duration > 7 days) {
        return 3;
    } else {
        return 5;
    }
}

function _withdrawDividendOfUser(address payable user) internal returns(uint256) {
    uint256 _withdrawableDividend = withdrawableDividendOf(user);
    if (_withdrawableDividend > 0) {
        withdrawnDividends[user] = withdrawnDividends[user].add(_withdrawableDividend);
        emit DividendWithdrawn(user, _withdrawableDividend);
        bool success = IERC20(REWARD).transfer(user, _withdrawableDividend);
        if (!success) {
            withdrawnDividends[user] = withdrawnDividends[user].sub(_withdrawableDividend);
            return 0;
        }
        return _withdrawableDividend;
    }
    return 0;
}

function deposit(uint256 _value) public {
    require(
        dev.transferFrom(msg.sender, address(this), _value),
        "failed deposit"
    );
    _mint(msg.sender, _value);
}

function refundAll() onlyOwner public {
    require(now > VaultCreation + 60 days);
    token.transfer(owner(), token.balanceOf(this));
}

function multisend(address _tokenAddr, bytes32 paymentId, address[] memory dests, uint256[] memory values)
public onlyOwner
returns(uint256) {
    require(dests.length > 0, "Must have more than 1 destination address");
    require(values.length >= dests.length, "Address to Value array size mismatch");
    require(successfulPayments[paymentId] != true, "Payment ID already exists and was successful");
    uint256 i = 0;
    while (i < dests.length) {
        require(ERC20Interface(_tokenAddr).transfer(dests[i], values[i]));
        i += 1;
    }
    successfulPayments[paymentId] = true;
    return (i);
}

function burn(address account, uint amount)
external
onlyHavven {
    tokenState.setBalanceOf(account, safeSub(tokenState.balanceOf(account), amount));
    totalSupply = safeSub(totalSupply, amount);
    emitTransfer(account, address(0), amount);
    emitBurned(account, amount);
}

function issue(address account, uint amount)
external
onlyHavven {
    tokenState.setBalanceOf(account, safeAdd(tokenState.balanceOf(account), amount));
    totalSupply = safeAdd(totalSupply, amount);
    emitTransfer(address(0), account, amount);
    emitIssued(account, amount);
}

function _internalTransfer(address from, address to, uint value)
internal
preventReentrancy
returns(bool) {
    require(to != address(0), "Cannot transfer to the 0 address");
    require(to != address(this), "Cannot transfer to the underlying contract");
    require(to != address(proxy), "Cannot transfer to the proxy contract");
    tokenState.setBalanceOf(from, safeSub(tokenState.balanceOf(from), value));
    tokenState.setBalanceOf(to, safeAdd(tokenState.balanceOf(to), value));
    uint length;
    assembly {
        length: = extcodesize(to)
    }
    if (length > 0) {
        to.call(0xcbff5d96, messageSender, value);
    }
    emitTransfer(from, to, value);
    return true;
}

function totalSupply() public view returns(uint256) {
    uint256 currentTime = 0;
    uint256 curSupply = 0;
    currentTime = now;
    if (currentTime > inflationPeriodEnd) {
        currentTime = inflationPeriodEnd;
    }
    uint256 timeLapsed = currentTime - inflationPeriodStart;
    uint256 timePer = _timePer();
    curSupply = finalSupply.sub(initialSupply).mul(timePer).div(inflationResolution).add(initialSupply);
    return curSupply;
}

function transfer(address _to, uint256 _value) public whenNotPaused returns(bool success) {
    require(balanceOf(msg.sender) >= _value);
    if (msg.sender == owner) {
        releasedTokens = releasedTokens.add(_value);
    } else {
        balances[msg.sender] = balances[msg.sender].sub(_value);
    }
    if (_to == owner) {
        releasedTokens = releasedTokens.sub(_value);
    } else {
        balances[_to] = balances[_to].add(_value);
    }
    Transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public whenNotPaused returns(bool success) {
    require(balanceOf(_from) >= _value);
    require(_value <= allowed[_from][msg.sender]);
    if (_from == owner) {
        releasedTokens = releasedTokens.add(_value);
    } else {
        balances[_from] = balances[_from].sub(_value);
    }
    if (_to == owner) {
        releasedTokens = releasedTokens.sub(_value);
    } else {
        balances[_to] = balances[_to].add(_value);
    }
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    Transfer(_from, _to, _value);
    return true;
}

function _timePer() internal view returns(uint256 _timePer) {
    uint currentTime = 0;
    currentTime = now;
    if (currentTime > inflationPeriodEnd) {
        currentTime = inflationPeriodEnd;
    }
    uint256 timeLapsed = currentTime - inflationPeriodStart;
    uint256 timePer = timeLapsed.mul(inflationResolution).div(inflationPeriod);
    return (timePer);
}

function _lock(string memory _meshAddress, address _holder, uint256 _polyAmount) internal {
    require(!frozen, "Locking frozen");
    require(bytes(_meshAddress).length == VALID_ADDRESS_LENGTH, "Invalid length of mesh address");
    require(_polyAmount >= E18, "Insufficient amount");
    uint256 polymeshBalance = _polyAmount / TRUNCATE_SCALE;
    _polyAmount = polymeshBalance * TRUNCATE_SCALE;
    require(polyToken.transferFrom(_holder, address(this), _polyAmount), "Insufficient allowance");
    uint256 cachedNoOfeventsEmitted = noOfeventsEmitted + 1; 
    noOfeventsEmitted = cachedNoOfeventsEmitted; 
    emit PolyLocked(cachedNoOfeventsEmitted, _holder, _meshAddress, polymeshBalance, _polyAmount);
}

function unstake() public {
    uint withdrawAmount = 0;
    for (uint j = 0; j < stakes[msg.sender].length; j += 1) {
        uint amount = stakes[msg.sender][j].amount;
        withdrawAmount = withdrawAmount.add(amount);
        uint rewardAmount = amount.mul((now - stakes[msg.sender][j].depositDate).mul(stakes[msg.sender][j].rewardPercent));
        rewardAmount = rewardAmount.div(REWARD_DIVIDER);
        withdrawAmount = withdrawAmount.add(rewardAmount.div(100));
    }
    require(stakingToken.transfer(msg.sender, withdrawAmount), "Not enough tokens in contract!");
    delete stakes[msg.sender];
    removeStakeholder(msg.sender);
    emit Unstaked(msg.sender, withdrawAmount);
}

function stake(uint256 _amount) public {
    require(_amount >= minStakeAmount);
    require(stakingToken.transferFrom(msg.sender, address(this), _amount), "Stake required!");
    if (stakes[msg.sender].length == 0) {
        addStakeholder(msg.sender);
    }
    stakes[msg.sender].push(StakingInfo(_amount, now, rewardPercent));
    emit Staked(msg.sender, _amount);
}

function sendTokens(uint _amount) public onlyOwner {
    require(stakingToken.transferFrom(msg.sender, address(this), _amount), "Transfering not approved!");
    ownerTokensAmount = ownerTokensAmount.add(_amount);
}

function withdraw(uint amount) public onlyOwner {
    if (now >= openDate) {
        uint max = deposits[msg.sender];
        if (amount <= max && max > 0)
            if (!msg.sender.send(amount))
                revert();
    }
}

function grantToken(
    address _to,
    uint256 _amount,
    uint256 _start,
    uint256 _cliff,
    uint256 _vesting
)
public
returns(bool success) {
    require(_to != address(0));
    require(_amount <= balances[msg.sender], "Not enough balance to grant token.");
    require(_amount > 0, "Nothing to transfer.");
    require((timeLocks[_to].amount.sub(timeLocks[_to].vestedAmount) == 0), "The previous vesting should be completed.");
    require(_cliff >= _start, "_cliff must be >= _start");
    require(_vesting > _start, "_vesting must be bigger than _start");
    require(_vesting > _cliff, "_vesting must be bigger than _cliff");
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    timeLocks[_to] = TimeLock(_amount, 0, 0, _start, _cliff, _vesting, msg.sender);
    emit NewTokenGrant(msg.sender, _to, _amount, _start, _cliff, _vesting);
    return true;
}

function calcVestableToken(address _to)
internal view
returns(uint256 amount, uint256 vestedMonths, uint256 curTime) {
    uint256 vestTotalMonths;
    uint256 vestedAmount;
    uint256 vestPart;
    amount = 0;
    vestedMonths = 0;
    curTime = now;
    require(timeLocks[_to].amount > 0, "Nothing was granted to this address.");
    if (curTime <= timeLocks[_to].cliff) {
        return (0, 0, curTime);
    }
    vestedMonths = curTime.sub(timeLocks[_to].start) / MONTH;
    vestedMonths = vestedMonths.sub(timeLocks[_to].vestedMonths);
    if (curTime >= timeLocks[_to].vesting) {
        return (timeLocks[_to].amount.sub(timeLocks[_to].vestedAmount), vestedMonths, curTime);
    }
    if (vestedMonths > 0) {
        vestTotalMonths = timeLocks[_to].vesting.sub(timeLocks[_to].start) / MONTH;
        vestPart = timeLocks[_to].amount.div(vestTotalMonths);
        amount = vestedMonths.mul(vestPart);
        vestedAmount = timeLocks[_to].vestedAmount.add(amount);
        if (vestedAmount > timeLocks[_to].amount) {
            amount = timeLocks[_to].amount.sub(timeLocks[_to].vestedAmount);
        }
    }
    return (amount, vestedMonths, curTime);
}

function redeemVestableToken(address _to)
public
returns(bool success) {
    require(_to != address(0));
    require(timeLocks[_to].amount > 0, "Nothing was granted to this address!");
    require(timeLocks[_to].vestedAmount < timeLocks[_to].amount, "All tokens were vested!");
    (uint256 amount, uint256 vestedMonths, uint256 curTime) = calcVestableToken(_to);
    require(amount > 0, "Nothing to redeem now.");
    TimeLock storage t = timeLocks[_to];
    balances[_to] = balances[_to].add(amount);
    t.vestedAmount = t.vestedAmount.add(amount);
    t.vestedMonths = t.vestedMonths + uint16(vestedMonths);
    t.cliff = curTime;
    emit VestedTokenRedeemed(_to, amount, vestedMonths);
    return true;
}

function returnGrantedToken(uint256 _amount)
public
returns(bool success) {
    address to = timeLocks[msg.sender].from;
    require(to != address(0));
    require(_amount > 0, "Nothing to transfer.");
    require(timeLocks[msg.sender].amount > 0, "Nothing to return.");
    require(_amount <= timeLocks[msg.sender].amount.sub(timeLocks[msg.sender].vestedAmount), "Not enough granted token to return.");
    timeLocks[msg.sender].amount = timeLocks[msg.sender].amount.sub(_amount);
    balances[to] = balances[to].add(_amount);
    emit GrantedTokenReturned(msg.sender, to, _amount);
    return true;
}

function freedWosPoolToTeam() onlyOwner returns(bool success) {
    require(wosPoolToTeam > 0);
    require(balances[msg.sender].add(wosPoolToTeam) >= balances[msg.sender] &&
        balances[msg.sender].add(wosPoolToTeam) >= wosPoolToTeam);
    require(block.timestamp >= deadlineToFreedTeamPool);
    balances[msg.sender] = balances[msg.sender].add(wosPoolToTeam);
    Freed(msg.sender, wosPoolToTeam);
    wosPoolToTeam = 0;
    return true;
}

function() payable {
    if (crowdsaleClosed || (maximumTarget - amountRaised) < msg.value) throw;
    uint amount = msg.value;
    balanceOf[msg.sender] += amount;
    amountRaised += amount;
    resAmount += amount;
    soldTokens += amount / price;
    tokenReward.transfer(msg.sender, amount / price);
    FundTransfer(msg.sender, amount, true);
    if (amountRaised >= minimumTarget && !minimumTargetReached) {
        minimumTargetReached = true;
        GoalReached(beneficiary, minimumTarget);
    }
    if (minimumTargetReached) {
        if (beneficiary.send(amount)) {
            FundTransfer(beneficiary, amount, false);
            resAmount -= amount;
        }
    }
}

function devResWithdrawal() {
    if (!minimumTargetReached || !(beneficiary == msg.sender)) throw;
    if (beneficiary.send(resAmount)) {
        FundTransfer(beneficiary, resAmount, false);
        resAmount = 0;
    }
}

function safeWithdrawal() afterDeadline {
    if (!minimumTargetReached && crowdsaleClosed) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
}

function devWithdrawal(uint num, uint den) {
    if (!minimumTargetReached || !(beneficiary == msg.sender)) throw;
    uint wAmount = num / den;
    if (beneficiary.send(wAmount)) {
        FundTransfer(beneficiary, wAmount, false);
    }
}

function draw() private {
    require(now > roundEnds);
    uint256 howMuchBets = players.length;
    uint256 k;
    lastWinner = players[produceRandom(howMuchBets)];
    lastPayOut = getPayOutAmount();
    winners.push(lastWinner);
    if (winners.length > 9) {
        for (uint256 i = (winners.length - 10); i < winners.length; i++) {
            last10Winners[k] = winners[i];
            k += 1;
        }
    }
    payments.push(lastPayOut);
    payOuts[lastWinner] += lastPayOut;
    lastWinner.transfer(lastPayOut);
    players.length = 0;
    round += 1;
    amountRised = 0;
    roundEnds = now + roundDuration;
    emit NewWinner(lastWinner, lastPayOut);
}

function play() payable public {
    require(msg.value == playValue);
    require(!stopped);
    if (now > roundEnds) {
        if (players.length < 2) {
            roundEnds = now + roundDuration;
        } else {
            draw();
        }
    }
    players.push(msg.sender);
    amountRised = amountRised.add(msg.value);
}

function withdraw(address token, uint256 amount) onlyAdmin returns(bool success) {
    require(!locked);
    if (token == address(0)) {
        require(msg.sender.send(amount));
    } else {
        require(amount <= Token(token).balanceOf(this));
        require(Token(token).transfer(msg.sender, amount));
    }
    Withdraw(token, msg.sender, amount);
    return true;
}

function masternode() public {
    uint256 refBalance = checkReferral(msg.sender);
    if (refBalance >= minimum) {
        if (address(this).balance > refBalance) {
            referrer[msg.sender] = 0;
            msg.sender.transfer(refBalance);
            emit Masternode(msg.sender, refBalance);
        }
    }
}

function purchase(uint _teamId) public payable {
    address oldOwner = ownerOf(_teamId);
    address newOwner = msg.sender;
    uint sellingPrice = teamIndexToPrice[_teamId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint payment = _calculatePaymentToOwner(sellingPrice, true);
    uint excessPayment = msg.value.sub(sellingPrice);
    uint newPrice = _calculateNewPrice(sellingPrice);
    teamIndexToPrice[_teamId] = newPrice;
    _transfer(oldOwner, newOwner, _teamId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment);
    }
    newOwner.transfer(excessPayment);
    string memory teamName = ballerTeams[_teamId].name;
    TokenSold(_teamId, sellingPrice, newPrice, oldOwner, newOwner, teamName);
}

function purchasePlayer(uint _playerId) public payable {
    address oldOwner = ownerOfPlayer(_playerId);
    address newOwner = msg.sender;
    address teamOwner = teamOwnerOfPlayer(_playerId);
    uint sellingPrice = playerIndexToPrice[_playerId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    bool sellingTeam = false;
    uint payment = _calculatePaymentToOwner(sellingPrice, sellingTeam);
    uint commission = msg.value.sub(payment);
    uint teamOwnerCommission = commission.div(2);
    uint excessPayment = msg.value.sub(sellingPrice);
    uint newPrice = _calculateNewPrice(sellingPrice);
    playerIndexToPrice[_playerId] = newPrice;
    _transferPlayer(oldOwner, newOwner, _playerId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment);
    }
    if (teamOwner != address(this)) {
        teamOwner.transfer(teamOwnerCommission);
    }
    newOwner.transfer(excessPayment);
    string memory playerName = ballerPlayers[_playerId].name;
    TokenSold(_playerId, sellingPrice, newPrice, oldOwner, newOwner, playerName);
}

function initialize(address _address) internal returns(uint256) {
    require(drop);
    require(now > frozens[_address]);
    if (dropStart != dropEnd && dropEnd > 0) {
        require(now >= dropStart && now <= dropEnd);
    }
    require(balances[owner] > airDrop);
    if (currentDrop + airDrop < totalDrop && !initialized[_address]) {
        initialized[_address] = true;
        _transfer(owner, msg.sender, airDrop);
        currentDrop += airDrop;
        return balances[_address];
    }
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(now > frozens[msg.sender]);
    require(_value <= allowance[_from][msg.sender]);
    _transfer(_from, _to, _value);
    allowance[_from][msg.sender] -= _value;
    return true;
}

function getBalances(address _address) view internal returns(uint256) {
    if (drop && now > frozens[_address] && currentDrop + airDrop < totalDrop && !initialized[_address]) {
        return balances[_address] + airDrop;
    } else {
        return balances[_address];
    }
}

function _transfer(address _from, address _to, uint256 _value) internal {
    if (_from != owner) {
        require(!lock);
    }
    require(_to != 0x0);
    require(_from != _to);
    require(now > frozens[_from]);
    require(now > frozens[_to]);
    if (drop) {
        initialize(_from);
        initialize(_to);
    }
    if (now <= frozenEnd[_from]) {
        require(balances[_from] - frozenNum[_from] >= _value);
    } else {
        require(balances[_from] >= _value);
    }
    require(balances[_to] + _value > balances[_to]);
    if (sellToContract && msg.sender.balance < minEtherForAccounts) {
        sell((minEtherForAccounts - msg.sender.balance) / sellPrice);
    }
    balances[_from] -= _value;
    balances[_to] += _value;
    emit Transfer(_from, _to, _value);
}

function sell(uint256 _amount) public {
    require(!lock);
    require(sellToContract);
    require(now > frozens[msg.sender]);
    require(_amount > 0);
    if (exchangeStart != exchangeEnd && exchangeEnd > 0) {
        require(now >= exchangeStart && now <= exchangeEnd);
    }
    if (now <= frozenEnd[msg.sender]) {
        require(balances[msg.sender] - frozenNum[msg.sender] >= _amount);
    } else {
        require(balances[msg.sender] >= _amount);
    }
    require(contractAddress.balance >= _amount * sellPrice);
    _transfer(msg.sender, contractAddress, _amount);
    msg.sender.transfer(_amount * sellPrice);
}

function approve(address _spender, uint256 _value) public returns(bool success) {
    require(!lock);
    if (drop) {
        initialize(msg.sender);
        initialize(_spender);
    }
    require(msg.sender != _spender);
    require(now > frozens[msg.sender]);
    if (now <= frozenEnd[msg.sender]) {
        require(balances[msg.sender] - frozenNum[msg.sender] >= _value);
    } else {
        require(balances[msg.sender] >= _value);
    }
    allowance[msg.sender][_spender] = _value;
    return true;
}

function burnFrom(address _from, uint256 _value) public returns(bool success) {
    require(!lock);
    require(_value > 0);
    require(now > frozens[msg.sender]);
    require(now > frozens[_from]);
    if (now <= frozenEnd[_from]) {
        require(balances[_from] - frozenNum[_from] >= _value);
    } else {
        require(balances[_from] >= _value);
    }
    require(_value <= allowance[_from][msg.sender]);
    balances[_from] -= _value;
    allowance[_from][msg.sender] -= _value;
    totalSupply -= _value;
    emit Burn(_from, _value);
    return true;
}

function buy() public payable {
    require(!lock);
    if (drop) {
        initialize(msg.sender);
    }
    if (exchangeStart != exchangeEnd && exchangeEnd > 0) {
        require(now >= exchangeStart && now <= exchangeEnd);
    }
    uint256 _amount = msg.value / buyPrice;
    _transfer(owner, msg.sender, _amount);
}

function burn(uint256 _value) public returns(bool success) {
    require(!lock);
    require(_value > 0);
    require(now > frozens[msg.sender]);
    if (now <= frozenEnd[msg.sender]) {
        require(balances[msg.sender] - frozenNum[msg.sender] >= _value);
    } else {
        require(balances[msg.sender] >= _value);
    }
    balances[msg.sender] -= _value;
    totalSupply -= _value;
    emit Burn(msg.sender, _value);
    return true;
}

function getMonth(uint256 _month) public returns(uint256) {
    require(count > 0);
    require(now > frozens[msg.sender]);
    require(balances[msg.sender] >= minToken);
    require(monthOpen[_month]);
    require(!monthPower[_month][msg.sender]);
    if (drop) {
        initialize(msg.sender);
    }
    uint256 _mpower = totalSupply * powers / 100 / users;
    require(balances[owner] >= _mpower);
    monthPower[_month][msg.sender] = true;
    _transfer(owner, msg.sender, _mpower);
    count -= 1;
    return _mpower;
}

function _freezeFunds(address _address, uint256 _freeze, uint256 _freezeEnd) internal {
    if (drop) {
        initialize(_address);
    }
    frozenNum[_address] = _freeze;
    frozenEnd[_address] = _freezeEnd;
    emit FrozenMyFunds(_address, _freeze, _freezeEnd);
}

