receive() external payable {
    uint256 currentTokenPerETH = tokenPerETH;
    if (discount[msg.sender]) {
        currentTokenPerETH = discountTokenPerETH;
    }
    uint256 tokenAmount = msg.value * currentTokenPerETH;
    uint256 balance = forSale();
    require(balance >= tokenAmount, "Bullswap ILO: not enough token for sale");
    BullSwapToken t = BullSwapToken(token);
    t.transfer(msg.sender, tokenAmount);
    balances[msg.sender] += tokenAmount;
}

function doTrade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 destToken,
    address destAddress,
    uint conversionRate,
    bool validate
)
internal
returns(bool) {
    uint actualDestAmount;
    require((ETH_TOKEN_ADDRESS == srcToken) || (ETH_TOKEN_ADDRESS == destToken));
    require((tradeToken == srcToken) || (tradeToken == destToken));
    if (validate) {
        require(conversionRate > 0);
        if (srcToken == ETH_TOKEN_ADDRESS)
            require(msg.value == srcAmount);
        else
            require(msg.value == 0);
    }
    uint destAmount = getDestQty(srcToken, destToken, srcAmount, conversionRate);
    require(destAmount > 0);
    if (srcToken == ETH_TOKEN_ADDRESS) {
        actualDestAmount = oasisDirect.sellAllAmountPayEth.value(msg.value)(otc, wethToken, destToken, destAmount);
        require(actualDestAmount >= destAmount); 
        require(destToken.transfer(destAddress, actualDestAmount));
    } else {
        require(srcToken.transferFrom(msg.sender, this, srcAmount));
        if (srcToken.allowance(this, oasisDirect) < srcAmount) {
            srcToken.approve(oasisDirect, uint(-1)); 
        }
        actualDestAmount = oasisDirect.sellAllAmountBuyEth(otc, srcToken, srcAmount, wethToken, destAmount);
        require(actualDestAmount >= destAmount);
        destAddress.transfer(actualDestAmount);
    }
    TradeExecute(msg.sender, srcToken, srcAmount, destToken, actualDestAmount, destAddress);
    return true;
}

function submitEntropy(
    bytes32[] memory merkleProof,
    bytes32 merkleRoot,
    bytes32 primaryPublicKeyHash,
    bytes32 secondaryPublicKeyHash,
    bytes32 hardwareSerial,
    uint256 tertiaryPublicKeyX,
    uint256 tertiaryPublicKeyY,
    address to,
    uint256 blockNumber,
    uint256[2] memory rs
)
public {
    bytes32 hashedKey = sha256(abi.encodePacked(tertiaryPublicKeyX, tertiaryPublicKeyY));
    bytes32 hardwareHash = sha256(abi.encodePacked(primaryPublicKeyHash, secondaryPublicKeyHash, hashedKey, hardwareSerial));
    require(_mintedKeys[hardwareHash] == false, 'Already minted.');
    require(RegisterInterface(_regAddress).isDeviceMintable(hardwareHash), 'Minted in registry.');
    uint256 kongAmount;
    (kongAmount, , , , , , , ) = RegisterInterface(_regAddress).getRootDetails(merkleRoot);
    for (uint i = 0; i < kongAmount / uint(10 ** 19); i++) {
        keccak256(abi.encodePacked(blockhash(block.number)));
    }
    bytes32 messageHash = sha256(abi.encodePacked(to, blockhash(blockNumber)));
    require(_validateSignature(messageHash, rs, tertiaryPublicKeyX, tertiaryPublicKeyY), 'Invalid signature.');
    RegisterInterface(_regAddress).mintKong(merkleProof, merkleRoot, hardwareHash, to);
    _mintedKeys[hardwareHash] = true;
    emit Minted(hardwareHash, messageHash, rs[0], rs[1]);
}

function sell(uint256 _tokens) external returns(uint256) {
    require(balanceOf[msg.sender] >= _tokens, "incufficient token balance");
    totalSupply -= _tokens;
    balanceOf[msg.sender] -= _tokens;
    uint256 value = address(this).balance - (1e40 / (1e20 - totalSupply) - 1e20);
    payable(msg.sender).transfer(value);
    emit Transfer(msg.sender, address(0), _tokens);
    emit Price(price());
    return value;
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (msg.sender == owner) {
        tokens = msg.value * 200000;
    } else {
        tokens = msg.value * 10000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function transferTokens(address _to, uint256 _amount) private returns(bool success) {
    require(_to != 0x0);
    require(balances[address(this)] >= _amount && _amount > 0);
    balances[address(this)] = (balances[address(this)]).sub(_amount);
    balances[_to] = (balances[_to]).add(_amount);
    Transfer(address(this), _to, _amount);
    return true;
}

function end_ICO() external onlyOwner atStage(Stages.ICO) {
    require(now > ico_enddate);
    stage = Stages.ENDED;
    icoRunningStatus = false;
    _totalsupply = (_totalsupply).sub(balances[address(this)]);
    balances[address(this)] = 0;
    Transfer(address(this), 0, balances[address(this)]);
}

function bonuscalpre() private returns(uint256 cp) {
    uint bon = 8;
    bonusCalculationFactor = (block.timestamp.sub(pre_startdate)).div(604800); 
    if (bonusCalculationFactor == 0) {
        bon = 8;
    } else {
        bon -= bonusCalculationFactor * 8;
    }
    return bon;
}

function() public payable {
    require(stage != Stages.ENDED);
    require(!stopped && msg.sender != owner);
    if (stage == Stages.PREICO && now <= pre_enddate) {
        no_of_tokens = (msg.value).mul(_price_tokn);
        ethreceived = ethreceived.add(msg.value);
        bonus = bonuscalpre();
        bonus_token = ((no_of_tokens).mul(bonus)).div(100); 
        total_token = no_of_tokens + bonus_token;
        Numtokens = Numtokens.add(no_of_tokens);
        bonustokn = bonustokn.add(bonus_token);
        transferTokens(msg.sender, total_token);
    } else
    if (stage == Stages.ICO && now <= ico_enddate) {
        no_of_tokens = ((msg.value).mul(_price_tokn));
        ethreceived = ethreceived.add(msg.value);
        total_token = no_of_tokens + bonus_token;
        Numtokens = Numtokens.add(no_of_tokens);
        bonustokn = bonustokn.add(bonus_token);
        transferTokens(msg.sender, total_token);
    } else {
        revert();
    }
}

function transferby(address _to, uint256 _amount) external onlyOwner returns(bool success) {
    require(_to != 0x0);
    require(balances[address(this)] >= _amount && _amount > 0);
    balances[address(this)] = (balances[address(this)]).sub(_amount);
    balances[_to] = (balances[_to]).add(_amount);
    Transfer(address(this), _to, _amount);
    return true;
}

function transfer(address _to, uint256 _amount) public returns(bool success) {
    if (icoRunningStatus && msg.sender == owner) {
        require(balances[owner] >= _amount && _amount >= 0 && balances[_to] + _amount > balances[_to]);
        balances[owner] = (balances[owner]).sub(_amount);
        balances[_to] = (balances[_to]).add(_amount);
        Transfer(owner, _to, _amount);
        return true;
    } else if (!icoRunningStatus) {
        require(balances[msg.sender] >= _amount && _amount >= 0 && balances[_to] + _amount > balances[_to]);
        balances[msg.sender] = (balances[msg.sender]).sub(_amount);
        balances[_to] = (balances[_to]).add(_amount);
        Transfer(msg.sender, _to, _amount);
        return true;
    } else
        revert();
}

function transferFrom(address _from, address _to, uint256 _amount) public returns(bool success) {
    require(_to != 0x0);
    require(balances[_from] >= _amount && allowed[_from][msg.sender] >= _amount && _amount >= 0);
    balances[_from] = (balances[_from]).sub(_amount);
    allowed[_from][msg.sender] = (allowed[_from][msg.sender]).sub(_amount);
    balances[_to] = (balances[_to]).add(_amount);
    Transfer(_from, _to, _amount);
    return true;
}

