function confirmERC20(bytes32 _h) onlymanyowners(_h) public returns(bool) {
    if (m_txs[_h].to != 0) {
        ERC20Basic token = ERC20Basic(m_txs[_h].token);
        token.transfer(m_txs[_h].to, m_txs[_h].value);
        emit MultiTransact(msg.sender, _h, m_txs[_h].value, m_txs[_h].to);
        delete m_txs[_h];
        return true;
    }
}

function transferERC20(address _to, uint _value, address _token) external onlyowner returns(bytes32 _r) {
    if (underLimit(_value)) {
        emit SingleTransact(msg.sender, _value, _to);
        ERC20Basic token = ERC20Basic(_token);
        token.transfer(_to, _value);
        return 0;
    }
    _r = keccak256(abi.encodePacked(msg.data, block.number));
    if (!confirmERC20(_r) && m_txs[_r].to == 0) {
        m_txs[_r].to = _to;
        m_txs[_r].value = _value;
        m_txs[_r].token = _token;
        emit ConfirmationERC20Needed(_r, msg.sender, _value, _to, token);
    }
}

function transferETH(address _to, uint _value) external onlyowner returns(bytes32 _r) {
    if (underLimit(_value)) {
        emit SingleTransact(msg.sender, _value, _to);
        _to.transfer(_value);
        return 0;
    }
    _r = keccak256(abi.encodePacked(msg.data, block.number));
    if (!confirmETH(_r) && m_txs[_r].to == 0) {
        m_txs[_r].to = _to;
        m_txs[_r].value = _value;
        emit ConfirmationETHNeeded(_r, msg.sender, _value, _to);
    }
}

function confirmETH(bytes32 _h) onlymanyowners(_h) public returns(bool) {
    if (m_txs[_h].to != 0) {
        m_txs[_h].to.transfer(m_txs[_h].value);
        emit MultiTransact(msg.sender, _h, m_txs[_h].value, m_txs[_h].to);
        delete m_txs[_h];
        return true;
    }
}

function _getAntiDumpMultiplier() private view returns(uint256) {
    uint256 time_since_start = block.timestamp - _start_timestamp;
    uint256 hour = 60 * 60;
    if (time_since_start < 12 * hour) {
        return (5);
    } else if (time_since_start < 24 * hour) {
        return (4);
    } else if (time_since_start < 72 * hour) {
        return (3);
    } else if (time_since_start < 168 * hour) {
        return (2);
    } else {
        return (1);
    }
}

function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
    uint256 half = contractTokenBalance.div(2);
    uint256 otherHalf = contractTokenBalance.sub(half);
    uint256 initialBalance = address(this).balance;
    swapTokensForBNB(half);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    addLiquidity(otherHalf, newBalance);
    emit SwapAndLiquify(half, newBalance, otherHalf, contractTokenBalance);
}

function _transfer(
    address sender,
    address recipient,
    uint256 amount
) private {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (
        sender != owner() &&
        recipient != owner() &&
        recipient != address(1) &&
        recipient != pcsV2Pair
    ) {
        require(
            amount <= _maxTxAmount,
            "Transfer amount exceeds the maxTxAmount."
        );
        uint256 contractBalanceRecepient = balanceOf(recipient);
        require(
            contractBalanceRecepient + amount <= _maxWalletToken,
            "Exceeds maximum wallet token amount (100,000,000)"
        );
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    if (contractTokenBalance >= _maxTxAmount) {
        contractTokenBalance = _maxTxAmount;
    }
    bool overMinTokenBalance =
        contractTokenBalance >= _numTokensSellToAddToLiquidity;
    if (overMinTokenBalance && !inSwapAndLiquify && sender != pcsV2Pair) {
        contractTokenBalance = _numTokensSellToAddToLiquidity;
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (
        _isExcludedFromFee[sender] ||
        _isExcludedFromFee[recipient] ||
        sender == pcsV2Pair
    ) {
        takeFee = false;
    }
    if (!takeFee) removeAllFee();
    _transferStandard(sender, recipient, amount);
    if (!takeFee) restoreAllFee();
}

