function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0);
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to] + _value > balanceOf[_to]);
    uint previousBalances = balanceOf[_from] + balanceOf[_to];
    balanceOf[_from] -= _value;
    balanceOf[_to] += _value;
    Transfer(_from, _to, _value);
    assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

function proofOfWork(uint nonce) public {
    bytes8 n = bytes8(keccak256(nonce, currentChallenge)); 
    require(n >= bytes8(difficulty)); 
    uint timeSinceLastProof = (now - timeOfLastProof); 
    require(timeSinceLastProof >= 5 seconds); 
    require(!miningGoalReached);
    curReward = timeSinceLastProof; 
    if ((curReward + mined) > amounttomine) {
        curReward = amounttomine - mined;
    }
    curReward = curReward * 10 ** uint256(decimals);
    balanceOf[msg.sender] += curReward; 
    mined += curReward;
    if (mined >= amounttomine) {
        miningGoalReached = true;
    }
    difficulty = difficulty * 10 minutes / timeSinceLastProof + 1; 
    timeOfLastProof = now; 
    currentChallenge = keccak256(nonce, currentChallenge, block.blockhash(block.number - 1)); 
}

function burn(uint256 _value) public returns(bool success) {
    require(balanceOf[msg.sender] >= _value); 
    balanceOf[msg.sender] -= _value; 
    totalSupply -= _value; 
    Burn(msg.sender, _value);
    return true;
}

function burnFrom(address _from, uint256 _value) public returns(bool success) {
    require(balanceOf[_from] >= _value); 
    require(_value <= allowance[_from][msg.sender]); 
    balanceOf[_from] -= _value; 
    allowance[_from][msg.sender] -= _value; 
    totalSupply -= _value; 
    Burn(_from, _value);
    return true;
}

