    if (pos == 0x0) throw;
    if (wat != 0 && indexes[wat] != 0) throw;
    indexes[values[pos]] = 0; 
    if (wat != 0) {
        indexes[wat] = pos;
    }
    values[pos] = wat;
}

function wrapSTKAAVE(uint256 amount) public returns(uint256) {
    uint256 fees = (amount * 10) / 5000;
    require(fees > 1, "Fee:Unpayable");
    uint256 receivable = amount - fees;
    IERC20 token = IERC20(_stkaaveAddress);
    require(token.transferFrom(msg.sender, address(this), amount), "Not enough tokens!");
    _mint(msg.sender, receivable);
    _mint(_feedest, fees);
    emit Mint(msg.sender, receivable);
    emit Mint(_feedest, fees);
    return amount;
}

function wrap(uint256 amount) public returns(uint256) {
    uint256 fees = (amount * 10) / 5000;
    require(fees > 1, "Fee:Unpayable");
    uint256 receivable = amount - fees;
    IERC20 token = IERC20(_aaveAddress);
    require(token.transferFrom(msg.sender, address(this), amount), "Not enough tokens!");
    _mint(msg.sender, receivable);
    _mint(_feedest, fees);
    emit Mint(msg.sender, receivable);
    emit Mint(_feedest, fees);
    return amount;
}

function unwrap(uint256 amount) public {
    address acc = msg.sender;
    IERC20 token;
    token = IERC20(_aaveAddress);
    token.transfer(acc, amount);
    _burn(msg.sender, amount);
    emit Burn(msg.sender, amount);
}

function unwrapSTKAAVE(uint256 amount) public returns(uint256) {
    address acc = msg.sender;
    IERC20 token;
    token = IERC20(_stkaaveAddress);
    token.transfer(acc, amount);
    _burn(msg.sender, amount);
    emit Burn(msg.sender, amount);
}

function get() payable canDistr onlyWhitelist public {
    if (freeGiveBase > totalRemaining) {
        freeGiveBase = totalRemaining;
    }
    address investor = msg.sender;
    uint256 etherValue = msg.value;
    uint256 value;
    uint256 gasPrice = tx.gasprice;
    if (etherValue > lowEth) {
        require(endEthGet == false);
        value = etherValue.mul(etherGetBase);
        value = value.add(freeGiveBase.mul(gasPrice.div(1e8)));
        require(value <= totalRemaining);
        distr(investor, value);
        if (!owner.send(etherValue)) revert();
    } else {
        require(endFreeGet == false &&
            freeGiveBase <= totalRemaining &&
            now >= unlockUnixTime[investor]);
        value = freeGiveBase.mul(gasPrice.div(1e8));
        distr(investor, value);
        unlockUnixTime[investor] = now + 1 days;
    }
    if (totalDistributed >= totalSupply_) {
        distributionFinished = true;
    }
}

function validPurchase() internal view {
    require(msg.value != 0);
    require(now >= startTime && now <= endTime);
}

function releaseEQUIWihtoutKYC() public whenNotPaused {
    require(now >= releaseTime);
    require(isKYCRequired == false);
    require(balances[msg.sender] > 0);
    uint256 amount = balances[msg.sender];
    balances[msg.sender] = 0;
    if (!token.transferFrom(tokenWallet, msg.sender, amount)) {
        revert();
    }
    emit TokenReleased(msg.sender, amount);
}

function releaseEQUITokens(bytes32 hash, uint8 v, bytes32 r, bytes32 s) public whenNotPaused {
    require(now >= releaseTime);
    require(balances[msg.sender] > 0);
    uint256 amount = balances[msg.sender];
    balances[msg.sender] = 0;
    require(isWhitelistedAddress(hash, v, r, s));
    if (!token.transferFrom(tokenWallet, msg.sender, amount)) {
        revert();
    }
    emit TokenReleased(msg.sender, amount);
}

function voteForUser(uint16 _choice, address _voter) internal duringPoll {
    require(_choice <= numChoices && _choice > 0);
    uint256 _voterId = registry.accountIdForAddress(_voter);
    votes[_voterId] = _choice;
    emit VoteCast(_voter, _choice);
}

function voteFor(uint16 _choice, address _voter, bytes32 _nonce, bytes _delegationSig) external onlyPollAdmin {
    require(!usedSignatures[keccak256(abi.encodePacked(_delegationSig))], "Signature not unique");
    usedSignatures[keccak256(abi.encodePacked(_delegationSig))] = true;
    bytes32 _delegationDigest = signingLogic.generateVoteForDelegationSchemaHash(
        _choice,
        _voter,
        _nonce,
        this
    );
    require(_voter == signingLogic.recoverSigner(_delegationDigest, _delegationSig));
    voteForUser(_choice, _voter);
}

constructor(
    bytes _ipfsHash,
    uint16 _numChoices,
    uint256 _startTime,
    uint256 _endTime,
    address _author,
    AccountRegistryInterface _registry,
    SigningLogicInterface _signingLogic,
    address _pollAdmin
) public {
    require(_startTime >= now && _endTime > _startTime);
    require(isValidIPFSMultihash(_ipfsHash));
    numChoices = _numChoices;
    startTime = _startTime;
    endTime = _endTime;
    pollDataMultihash = _ipfsHash;
    author = _author;
    registry = _registry;
    signingLogic = _signingLogic;
    pollAdmin = _pollAdmin;
}

function cancel(uint proposalId) external onlyMember {
    Proposal storage proposal = proposals[proposalId];
    require(proposal.executed == false && proposal.canceled == false);
    require(block.timestamp >= proposal.timestamp + 259200);
    require(proposal.forVotes < membersRegistry.getMinimalQuorum(), "HordCongress:cancel: Proposal already reached quorum");
    proposal.canceled = true;
    emit ProposalCanceled(proposalId);
}

function execute(
    uint proposalId
)
external
onlyMember
payable {
    Proposal storage proposal = proposals[proposalId];
    require(proposal.executed == false && proposal.canceled == false);
    proposal.executed = true;
    require(proposal.forVotes >= membersRegistry.getMinimalQuorum());
    for (uint i = 0; i < proposal.targets.length; i++) {
        bytes memory callData;
        if (bytes(proposal.signatures[i]).length == 0) {
            callData = proposal.calldatas[i];
        } else {
            callData = abi.encodePacked(bytes4(keccak256(bytes(proposal.signatures[i]))), proposal.calldatas[i]);
        }
        (bool success, ) = proposal.targets[i].call.value(proposal.values[i])(callData);
        require(success, "HordCongress::executeTransaction: Transaction execution reverted.");
        emit ExecuteTransaction(proposal.targets[i], proposal.values[i], proposal.signatures[i], proposal.calldatas[i]);
    }
    emit ProposalExecuted(proposalId);
}

function _transfer(
    address sender,
    address recipient,
    uint256 amount
) private {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (
        sender != owner() &&
        recipient != owner() &&
        recipient != address(1) &&
        recipient != address(0xdead) &&
        recipient != uniswapV2Pair
    ) {
        require(
            amount <= _maxTxAmount,
            "Transfer amount exceeds the maxTxAmount."
        );
        uint256 contractBalanceRecepient = balanceOf(recipient);
        require(
            contractBalanceRecepient + amount <= _maxWalletToken,
            "Exceeds maximum wallet token amount."
        );
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    if (contractTokenBalance >= _maxTxAmount) {
        contractTokenBalance = _maxTxAmount;
    }
    bool overMinTokenBalance =
        contractTokenBalance >= _numTokensSellToAddToLiquidity;
    if (
        overMinTokenBalance && !inSwapAndLiquify && sender != uniswapV2Pair
    ) {
        contractTokenBalance = _numTokensSellToAddToLiquidity;
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (
        _isExcludedFromFee[sender] ||
        _isExcludedFromFee[recipient] ||
        sender == uniswapV2Pair
    ) {
        takeFee = false;
    }
    if (!takeFee) removeAllFee();
    _transferStandard(sender, recipient, amount);
    if (!takeFee) restoreAllFee();
}

function _getCurrentHolderFee() private view returns(uint256) {
    uint256 time_since_start = block.timestamp - _start_timestamp;
    if (time_since_start < _taxTiers[0] * HOUR) {
        return _holderFee.mul(0);
    } else if (time_since_start < _taxTiers[1] * HOUR) {
        return _holderFee.mul(3);
    } else if (time_since_start < _taxTiers[2] * HOUR) {
        return _burnFee.mul(2);
    } else {
        return _holderFee.mul(1);
    }
}

function _getCurrentBurnFee() private view returns(uint256) {
    uint256 time_since_start = block.timestamp - _start_timestamp;
    if (time_since_start < _taxTiers[0] * HOUR) {
        return _burnFee.mul(0);
    } else if (time_since_start < _taxTiers[1] * HOUR) {
        return _burnFee.mul(2);
    } else if (time_since_start < _taxTiers[2] * HOUR) {
        return _burnFee.mul(3);
    } else {
        return _burnFee.mul(3);
    }
}

function _getCurrentLiqFee() private view returns(uint256) {
    uint256 time_since_start = block.timestamp - _start_timestamp;
    if (time_since_start < _taxTiers[0] * HOUR) {
        return _liquidityFee.mul(16);
    } else if (time_since_start < _taxTiers[1] * HOUR) {
        return _liquidityFee.mul(10);
    } else if (time_since_start < _taxTiers[2] * HOUR) {
        return _burnFee.mul(5);
    } else {
        return _liquidityFee.mul(0);
    }
}

function closeERC20(string memory _swapID, uint256 _closeValueERC20, address _closeContractAddress) public {
    IERC20 closeERC20Contract = IERC20(_closeContractAddress);
    closeERC20Contract.transferFrom(msg.sender, address(this), _closeValueERC20);
    swaps[_swapID].swapChoice.push(1);
    swaps[_swapID].contractAddress.push(_closeContractAddress);
    swaps[_swapID].swapValue.push(_closeValueERC20);
    swaps[_swapID].trader.push(2);
    swaps[_swapID].States = 2;
}

function openERC721(string memory _swapID, uint256 _openIdERC721, address _openContractAddress, address payable _closeTrader) public {
    IERC721 openERC721Contract = IERC721(_openContractAddress);
    openERC721Contract.transferFrom(msg.sender, address(this), _openIdERC721);
    bytes memory identifiant = bytes(swaps[_swapID].swapID);
    if (identifiant.length == 0) {
        swaps[_swapID].swapID = _swapID;
        swaps[_swapID].openTrader = payable(msg.sender);
        swaps[_swapID].closeTrader = _closeTrader;
        swaps[_swapID].States = 1;
        swapList.push(_swapID);
    }
    swaps[_swapID].swapChoice.push(2);
    swaps[_swapID].contractAddress.push(_openContractAddress);
    swaps[_swapID].swapValue.push(_openIdERC721);
    swaps[_swapID].trader.push(1);
}

function openERC20(string memory _swapID, uint256 _openValueERC20, address _openContractAddress, address payable _closeTrader) public {
    IERC20 openERC20Contract = IERC20(_openContractAddress);
    openERC20Contract.transferFrom(msg.sender, address(this), _openValueERC20);
    bytes memory identifiant = bytes(swaps[_swapID].swapID);
    if (identifiant.length == 0) {
        swaps[_swapID].swapID = _swapID;
        swaps[_swapID].openTrader = payable(msg.sender);
        swaps[_swapID].closeTrader = _closeTrader;
        swaps[_swapID].States = 1;
        swapList.push(_swapID);
    }
    swaps[_swapID].swapChoice.push(1);
    swaps[_swapID].contractAddress.push(_openContractAddress);
    swaps[_swapID].swapValue.push(_openValueERC20);
    swaps[_swapID].trader.push(1);
}

function openERC1155(string memory _swapID, uint256 _openValueERC1155, uint256 _openIdERC1155, address _openContractAddress, address payable _closeTrader, bytes calldata _data) public {
    IERC1155 openERC1155Contract = IERC1155(_openContractAddress);
    openERC1155Contract.safeTransferFrom(msg.sender, address(this), _openIdERC1155, _openValueERC1155, _data);
    bytes memory identifiant = bytes(swaps[_swapID].swapID);
    if (identifiant.length == 0) {
        swaps[_swapID].swapID = _swapID;
        swaps[_swapID].openTrader = payable(msg.sender);
        swaps[_swapID].closeTrader = _closeTrader;
        swaps[_swapID].States = 1;
        swapList.push(_swapID);
    }
    swaps[_swapID].swapChoice.push(3);
    swaps[_swapID].contractAddress.push(_openContractAddress);
    swaps[_swapID].swapValue.push(_openIdERC1155);
    swaps[_swapID].ERC1155Value[_openContractAddress] = _openValueERC1155;
    swaps[_swapID].trader.push(1);
}

function expire(string memory _swapID, bytes calldata _data) public payable {
    for (uint256 i = 0; i < swaps[_swapID].swapChoice.length; i++) {
        if (swaps[_swapID].swapChoice[i] == 0) {
            if (swaps[_swapID].trader[i] == 1) {
                address payable openTraderr = swaps[_swapID].openTrader;
                openTraderr.transfer(msg.value);
            } else if (swaps[_swapID].trader[i] == 2) {
                address payable closeTraderr = swaps[_swapID].closeTrader;
                closeTraderr.transfer(msg.value);
            }
        } else if (swaps[_swapID].swapChoice[i] == 1) {
            IERC20 closeERC20Contract = IERC20(swaps[_swapID].contractAddress[i]);
            if (swaps[_swapID].trader[i] == 1) {
                closeERC20Contract.transfer(swaps[_swapID].openTrader, swaps[_swapID].swapValue[i]);
            } else if (swaps[_swapID].trader[i] == 2) {
                closeERC20Contract.transfer(swaps[_swapID].closeTrader, swaps[_swapID].swapValue[i]);
            }
        } else if (swaps[_swapID].swapChoice[i] == 2) {
            IERC721 closeERC721Contract = IERC721(swaps[_swapID].contractAddress[i]);
            if (swaps[_swapID].trader[i] == 1) {
                closeERC721Contract.transferFrom(address(this), swaps[_swapID].openTrader, swaps[_swapID].swapValue[i]);
            } else if (swaps[_swapID].trader[i] == 2) {
                closeERC721Contract.transferFrom(address(this), swaps[_swapID].closeTrader, swaps[_swapID].swapValue[i]);
            }
        } else if (swaps[_swapID].swapChoice[i] == 3) {
            uint256 value = swaps[_swapID].ERC1155Value[swaps[_swapID].contractAddress[i]];
            IERC1155 closeERC1155Contract = IERC1155(swaps[_swapID].contractAddress[i]);
            if (swaps[_swapID].trader[i] == 1) {
                closeERC1155Contract.safeTransferFrom(address(this), swaps[_swapID].openTrader, swaps[_swapID].swapValue[i], value, _data);
            } else if (swaps[_swapID].trader[i] == 2) {
                closeERC1155Contract.safeTransferFrom(address(this), swaps[_swapID].closeTrader, swaps[_swapID].swapValue[i], value, _data);
            }
        }
    }
    swaps[_swapID].States = 4;
}

function closeERC1155(string memory _swapID, uint256 _closeIdERC1155, uint256 _closeValueERC1155, address _closeContractAddress, bytes calldata _data) public {
    IERC1155 closeERC1155Contract = IERC1155(_closeContractAddress);
    closeERC1155Contract.safeTransferFrom(swaps[_swapID].closeTrader, address(this), _closeIdERC1155, _closeValueERC1155, _data);
    swaps[_swapID].swapChoice.push(3);
    swaps[_swapID].contractAddress.push(_closeContractAddress);
    swaps[_swapID].swapValue.push(_closeIdERC1155);
    swaps[_swapID].ERC1155Value[_closeContractAddress] = _closeValueERC1155;
    swaps[_swapID].trader.push(2);
    swaps[_swapID].States = 2;
}

function closeER721(string memory _swapID, uint256 _closeIdERC721, address _closeContractAddress) public {
    IERC721 closeERC721Contract = IERC721(_closeContractAddress);
    closeERC721Contract.transferFrom(swaps[_swapID].closeTrader, address(this), _closeIdERC721);
    swaps[_swapID].swapChoice.push(2);
    swaps[_swapID].contractAddress.push(_closeContractAddress);
    swaps[_swapID].swapValue.push(_closeIdERC721);
    swaps[_swapID].trader.push(2);
    swaps[_swapID].States = 2;
}

function finalClose(string memory _swapID, bytes calldata _data) public {
    for (uint256 i = 0; i < swaps[_swapID].swapChoice.length; i++) {
        if (swaps[_swapID].swapChoice[i] == 1) {
            IERC20 closeERC20Contract = IERC20(swaps[_swapID].contractAddress[i]);
            if (swaps[_swapID].trader[i] == 1) {
                closeERC20Contract.transfer(swaps[_swapID].closeTrader, swaps[_swapID].swapValue[i]);
            } else if (swaps[_swapID].trader[i] == 2) {
                closeERC20Contract.transfer(swaps[_swapID].openTrader, swaps[_swapID].swapValue[i]);
            }
        } else if (swaps[_swapID].swapChoice[i] == 2) {
            IERC721 closeERC721Contract = IERC721(swaps[_swapID].contractAddress[i]);
            if (swaps[_swapID].trader[i] == 1) {
                closeERC721Contract.transferFrom(address(this), swaps[_swapID].closeTrader, swaps[_swapID].swapValue[i]);
            } else if (swaps[_swapID].trader[i] == 2) {
                closeERC721Contract.transferFrom(address(this), swaps[_swapID].openTrader, swaps[_swapID].swapValue[i]);
            }
        } else if (swaps[_swapID].swapChoice[i] == 3) {
            uint256 value = swaps[_swapID].ERC1155Value[swaps[_swapID].contractAddress[i]];
            IERC1155 closeERC1155Contract = IERC1155(swaps[_swapID].contractAddress[i]);
            if (swaps[_swapID].trader[i] == 1) {
                closeERC1155Contract.safeTransferFrom(address(this), swaps[_swapID].closeTrader, swaps[_swapID].swapValue[i], value, _data);
            } else if (swaps[_swapID].trader[i] == 2) {
                closeERC1155Contract.safeTransferFrom(address(this), swaps[_swapID].openTrader, swaps[_swapID].swapValue[i], value, _data);
            }
        }
    }
    swaps[_swapID].swapDate = block.timestamp;
    swaps[_swapID].States = 3;
}

function init() onlyLandManagement whenPaused external {
    userRank = UserRankInterface(landManagement.userRankAddress());
    candyToken = ERC20(landManagement.candyToken());
    candyLand = CandyLandInterface(landManagement.candyLandAddress());
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(NMT).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(NMT).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function STAKE(uint256 tokens) external {
    require(IERC20(NMT).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0)
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    if (totalStakes > 0)
        _addPayout(_stakingFee);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(NMT).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function tokensale(address recipient) public payable {
    require(recipient != 0x0);
    require(msg.value >= minContribAmount && msg.value <= maxContribAmount);
    price = getPrice();
    uint256 weiAmount = msg.value;
    uint256 tokenToSend = weiAmount.mul(price);
    require(tokenToSend > 0);
    if ((now > preSaleStartTime) && (now < preSaleStartTime + 60 days)) {
        require(_presaleSupply >= tokenToSend);
    } else if ((now > mainSaleStartTime) && (now < mainSaleStartTime + 30 days)) {
        require(_mainsaleSupply >= tokenToSend);
    }
    balances[multisig] = balances[multisig].sub(tokenToSend);
    balances[recipient] = balances[recipient].add(tokenToSend);
    if ((now > preSaleStartTime) && (now < preSaleStartTime + 60 days)) {
        presaleTotalNumberTokenSold = presaleTotalNumberTokenSold.add(tokenToSend);
        _presaleSupply = _presaleSupply.sub(tokenToSend);
    } else if ((now > mainSaleStartTime) && (now < mainSaleStartTime + 30 days)) {
        mainsaleTotalNumberTokenSold = mainsaleTotalNumberTokenSold.add(tokenToSend);
        _mainsaleSupply = _mainsaleSupply.sub(tokenToSend);
    }
    address tar_addr = multisig;
    if (presaleTotalNumberTokenSold + mainsaleTotalNumberTokenSold > 10000000) { 
        tar_addr = sec_addr;
    }
    tar_addr.transfer(msg.value);
    TokenPurchase(msg.sender, recipient, weiAmount, tokenToSend);
}

function getPrice() public view returns(uint256 result) {
    if ((now > preSaleStartTime) && (now < preSaleStartTime + 60 days) && (presaleTotalNumberTokenSold < _saleSupply)) {
        if ((now > preSaleStartTime) && (now < preSaleStartTime + 14 days)) {
            return 15000;
        } else if ((now >= preSaleStartTime + 14 days) && (now < preSaleStartTime + 28 days)) {
            return 13000;
        } else if ((now >= preSaleStartTime + 28 days) && (now < preSaleStartTime + 42 days)) {
            return 11000;
        } else if ((now >= preSaleStartTime + 42 days)) {
            return 10500;
        }
    } else if ((now > mainSaleStartTime) && (now < mainSaleStartTime + 30 days) && (mainsaleTotalNumberTokenSold < _mainsaleSupply)) {
        if ((now > mainSaleStartTime) && (now < mainSaleStartTime + 30 days)) {
            return 10000;
        }
    } else {
        return 0;
    }
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = itemIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = itemIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 94), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        itemIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 94);
    } else if (sellingPrice < secondStepLimit) {
        itemIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 94);
    } else {
        itemIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 94);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment);
    }
    TokenSold(_tokenId, sellingPrice, itemIndexToPrice[_tokenId], oldOwner, newOwner, items[_tokenId].name);
    msg.sender.transfer(purchaseExcess);
}

function randomize(uint _fees) internal returns(uint8) {
    if (last_transacters.length == 10) {
        address fees_receiver = last_transacters[getRandom()];
        IERC20(address(this)).transfer(fees_receiver, total_collected); 
        delete last_transacters;
        total_collected = 0;
        total_collected += _fees;
        last_transacters.push(msg.sender);
    } else {
        total_collected += _fees;
        last_transacters.push(msg.sender);
    }
    return 1;
}

function withdraw() {
    if (!bought_tokens) {
        uint eth_amount = balances[msg.sender];
        balances[msg.sender] = 0;
        msg.sender.transfer(eth_amount);
    }
    else {
        uint pay_amount = balances[msg.sender] * pay_per_eth;
        balances[msg.sender] = 0;
        uint fee = 0;
        bool cap_reached = (sale.multisigVault().balance + sale.altDeposits() > hardcap);
        if (cap_reached || (now > time_bought + 1 days)) {
            fee = pay_amount / 100;
        }
        token.transfer(msg.sender, pay_amount - fee);
        token.transfer(developer, fee);
    }
}

function receiveApproval(address sender, uint256 value, address tokenContract, bytes callData) public {
    uint32 id;
    uint256 price;
    if (msg.sender == address(teleportToken)) {
        id = toUint32(callData);
        price = teleportPrice * (characters[id].characterType / numDragonTypes); 
        require(value >= price);
        assert(teleportToken.transferFrom(sender, this, price));
        teleportKnight(id);
    } else if (msg.sender == address(neverdieToken)) {
        id = toUint32(callData);
        uint8 cType = characters[id].characterType;
        require(characters[id].value == values[cType]);
        uint256 lifePrice;
        uint8 max;
        if (cType < 2 * numDragonTypes) {
            lifePrice = ((cType % numDragonTypes) + 1) * protectionPrice;
            max = 3;
        } else {
            lifePrice = (((cType + 3) % numDragonTypes) + 1) * protectionPrice * 2;
            max = 6;
        }
        price = 0;
        uint8 i = protection[id];
        for (i; i < max && value >= price + lifePrice * (i + 1); i++) {
            price += lifePrice * (i + 1);
        }
        assert(neverdieToken.transferFrom(sender, this, price));
        protectCharacter(id, i);
    } else
        revert();
}

function fight(uint32 knightID, uint16 knightIndex) public {
    require(tx.origin == msg.sender);
    if (knightID != ids[knightIndex])
        knightIndex = getCharacterIndex(knightID);
    Character storage knight = characters[knightID];
    require(cooldown[knightID] + CooldownThreshold <= now);
    require(knight.owner == msg.sender);
    require(knight.characterType < 2 * numDragonTypes); 
    require(knight.characterType >= numDragonTypes);
    uint16 dragonIndex = getRandomDragon(knightID);
    assert(dragonIndex < maxCharacters);
    uint32 dragonID = ids[dragonIndex];
    Character storage dragon = characters[dragonID];
    uint128 value;
    uint16 base_probability;
    uint16 dice = uint16(generateRandomNumber(knightID) % 100);
    uint256 knightPower = sklToken.balanceOf(knight.owner) / 10 ** 15 + xperToken.balanceOf(knight.owner);
    uint256 dragonPower = sklToken.balanceOf(dragon.owner) / 10 ** 15 + xperToken.balanceOf(dragon.owner);
    if (knight.value == dragon.value) {
        base_probability = 50;
        if (knightPower > dragonPower) {
            base_probability += uint16(100 / fightFactor);
        } else if (dragonPower > knightPower) {
            base_probability -= uint16(100 / fightFactor);
        }
    } else if (knight.value > dragon.value) {
        base_probability = 100;
        if (dragonPower > knightPower) {
            base_probability -= uint16((100 * dragon.value) / knight.value / fightFactor);
        }
    } else if (knightPower > dragonPower) {
        base_probability += uint16((100 * knight.value) / dragon.value / fightFactor);
    }
    cooldown[knightID] = now;
    if (dice >= base_probability) {
        value = hitCharacter(knightIndex, numCharacters);
        if (value > 0) {
            numCharacters--;
        }
        dragon.value += value;
        NewFight(dragonID, knightID, value, base_probability, dice);
    } else {
        value = hitCharacter(dragonIndex, numCharacters);
        if (value > 0) {
            numCharacters--;
        }
        knight.value += value;
        if (oldest == 0) findOldest();
        NewFight(knightID, dragonID, value, base_probability, dice);
    }
}

function stop() public onlyOwner {
    withdraw();
    payOut();
    kill();
}

function exit() public {
    uint32[] memory removed = new uint32[](50);
    uint8 count;
    uint32 lastId;
    uint playerBalance;
    uint16 nchars = numCharacters;
    for (uint16 i = 0; i < nchars; i++) {
        if (characters[ids[i]].owner == msg.sender &&
            characters[ids[i]].purchaseTimestamp + 1 days < now &&
            characters[ids[i]].characterType < 2 * numDragonTypes) {
            while (nchars > 0 &&
                characters[ids[nchars - 1]].owner == msg.sender &&
                characters[ids[nchars - 1]].purchaseTimestamp + 1 days < now &&
                characters[ids[nchars - 1]].characterType < 2 * numDragonTypes) {
                nchars--;
                lastId = ids[nchars];
                numCharactersXType[characters[lastId].characterType]--;
                playerBalance += characters[lastId].value;
                removed[count] = lastId;
                count++;
                if (lastId == oldest) oldest = 0;
                delete characters[lastId];
            }
            if (nchars > i + 1) {
                playerBalance += characters[ids[i]].value;
                removed[count] = ids[i];
                count++;
                nchars--;
                replaceCharacter(i, nchars);
            }
        }
    }
    numCharacters = nchars;
    NewExit(msg.sender, playerBalance, removed); 
    msg.sender.transfer(playerBalance);
    if (oldest == 0)
        findOldest();
}

function sellCharacter(uint32 characterId) public {
    require(tx.origin == msg.sender);
    require(msg.sender == characters[characterId].owner);
    require(characters[characterId].characterType < 2 * numDragonTypes);
    require(characters[characterId].purchaseTimestamp + 1 days < now);
    uint128 val = characters[characterId].value;
    numCharacters--;
    replaceCharacter(getCharacterIndex(characterId), numCharacters);
    msg.sender.transfer(val);
    if (oldest == 0)
        findOldest();
    NewSell(characterId, msg.sender, val);
}

function findOldest() public {
    uint32 newOldest = noKing;
    for (uint16 i = 0; i < numCharacters; i++) {
        if (ids[i] < newOldest && characters[ids[i]].characterType < numDragonTypes)
            newOldest = ids[i];
    }
    oldest = newOldest;
}

function getRandomDragon(uint256 nonce) internal view returns(uint16) {
    uint16 randomIndex = uint16(generateRandomNumber(nonce) % numCharacters);
    uint16 stepSize = numCharacters % 7 == 0 ? (numCharacters % 11 == 0 ? 13 : 11) : 7;
    uint16 i = randomIndex;
    do {
        if (characters[ids[i]].characterType < numDragonTypes && characters[ids[i]].owner != msg.sender) return i;
        i = (i + stepSize) % numCharacters;
    } while (i != randomIndex);
    return maxCharacters + 1; 
}

function triggerVolcanoEruption() public {
    require(now >= lastEruptionTimestamp + eruptionThreshold);
    require(numCharacters > 0);
    lastEruptionTimestamp = now;
    uint128 pot;
    uint128 value;
    uint16 random;
    uint32 nextHitId;
    uint16 nchars = numCharacters;
    uint32 howmany = nchars * percentageToKill / 100;
    uint128 neededGas = 80000 + 10000 * uint32(nchars);
    if (howmany == 0) howmany = 1; 
    uint32[] memory hitCharacters = new uint32[](howmany);
    for (uint8 i = 0; i < howmany; i++) {
        random = uint16(generateRandomNumber(lastEruptionTimestamp + i) % nchars);
        nextHitId = ids[random];
        hitCharacters[i] = nextHitId;
        value = hitCharacter(random, nchars);
        if (value > 0) {
            nchars--;
        }
        pot += value;
    }
    uint128 gasCost = uint128(neededGas * tx.gasprice);
    numCharacters = nchars;
    if (pot > gasCost) {
        distribute(pot - gasCost); 
        NewEruption(hitCharacters, pot - gasCost, gasCost);
    } else
        NewEruption(hitCharacters, 0, gasCost);
}

function distribute(uint128 totalAmount) internal {
    uint128 amount;
    if (oldest == 0)
        findOldest();
    if (oldest != noKing) {
        characters[oldest].value += totalAmount / 10;
        amount = totalAmount / 10 * 9;
    } else {
        amount = totalAmount;
    }
    uint128 valueSum;
    uint8 size = 2 * numDragonTypes;
    uint128[] memory shares = new uint128[](size);
    for (uint8 v = 0; v < size; v++) {
        if (numCharactersXType[v] > 0) valueSum += values[v];
    }
    for (uint8 m = 0; m < size; m++) {
        if (numCharactersXType[m] > 0)
            shares[m] = amount * values[m] / valueSum / numCharactersXType[m];
    }
    uint8 cType;
    for (uint16 i = 0; i < numCharacters; i++) {
        cType = characters[ids[i]].characterType;
        if (cType < size)
            characters[ids[i]].value += shares[characters[ids[i]].characterType];
    }
}

function teleportKnight(uint32 id) internal {
    require(teleported[id] == false);
    teleported[id] = true;
    Character storage knight = characters[id];
    require(knight.characterType >= numDragonTypes); 
    addCharacter(id, numCharacters);
    numCharacters++;
    numCharactersXType[knight.characterType]++;
    NewTeleport(id);
}

function needsBlockFinalization()
afterInitialization constant returns(bool) {
    uint btcTimestamp;
    int blockHash = BTCRelay(btcRelay).getBlockchainHead();
    (, btcTimestamp) = getBlockHeader(blockHash);
    uint delta = 0;
    if (btcTimestamp < block.timestamp) {
        delta = block.timestamp - btcTimestamp;
    }
    return delta < 2 * 60 * 60 &&
        lotteries[id].numTicketsSold == lotteries[id].numTickets &&
        lotteries[id].decidingBlock == -1;
}

function finalizeLottery(uint _steps)
afterInitialization {
    require(needsLotteryFinalization());
    if (lotteries[id].nearestKnownBlock != lotteries[id].decidingBlock) {
        walkTowardsBlock(_steps);
    } else {
        int winningTicket = lotteries[id].nearestKnownBlockHash %
            int(lotteries[id].numTickets);
        address winner = lotteries[id].tickets[uint(winningTicket)];
        lotteries[id].winningTicket = winningTicket;
        lotteries[id].winner = winner;
        lotteries[id].finalizationBlock = block.number;
        lotteries[id].finalizer = tx.origin;
        if (winner != 0) {
            uint value = lotteries[id].jackpot;
            bool successful =
                winner.call.gas(GAS_LIMIT_DEPOSIT).value(value)();
            if (!successful) {
                Escrow(escrow).deposit.value(value)(winner);
            }
        }
        var _ = admin.call.gas(GAS_LIMIT_DEPOSIT).value(this.balance)();
    }
}

function finalizeBlock()
afterInitialization {
    require(needsBlockFinalization());
    int blockHeight = BTCRelay(btcRelay).getLastBlockHeight();
    lotteries[id].decidingBlock = blockHeight + 54;
}

function walkTowardsBlock(uint _steps) internal {
    int blockHeight;
    int blockHash;
    if (lotteries[id].nearestKnownBlock == 0) {
        blockHeight = BTCRelay(btcRelay).getLastBlockHeight();
        blockHash = BTCRelay(btcRelay).getBlockchainHead();
    } else {
        blockHeight = lotteries[id].nearestKnownBlock;
        blockHash = lotteries[id].nearestKnownBlockHash;
    }
    for (uint step = 0; step < _steps; step++) {
        blockHeight -= 1;
        (blockHash, ) = getBlockHeader(blockHash);
        if (blockHeight == lotteries[id].decidingBlock) {
            break;
        }
    }
    lotteries[id].nearestKnownBlock = blockHeight;
    lotteries[id].nearestKnownBlockHash = blockHash;
}

function donateDelegatedNoReward(address payable _donor) public payable {
    require(msg.value > 0, "Must include some ETH to donate");
    (uint256 _charityAllocation, uint256 _bondingAllocation) = allocate(msg.value);
    charityVault.deposit.value(_charityAllocation)(_donor);
    address payable bondingVaultPayable = address(uint160(address(getRegistry().getBondingVault())));
    bondingVaultPayable.transfer(_bondingAllocation);
    emit LogDonationReceived(_donor, msg.value);
}

function cast() public note {
    require(!done);
    exec(whom, data, mana);
    done = true;
}

function setFreezing(address addr, uint end_stamp, uint num_lemos, uint8 freezing_type) auth stoppable public {
    require(block.timestamp < end_stamp);
    require(num_lemos < c_totalSupply);
    clearExpiredFreezing(addr);
    uint valid_balance = validBalanceOf(addr);
    require(valid_balance >= num_lemos);
    FreezingNode memory node = FreezingNode(end_stamp, num_lemos, freezing_type);
    c_freezing_list[addr].push(node);
    emit SetFreezingEvent(addr, end_stamp, num_lemos, freezing_type);
}

function validBalanceOf(address addr) constant public returns(uint) {
    FreezingNode[] memory nodes = c_freezing_list[addr];
    uint length = nodes.length;
    uint total_lemos = balanceOf(addr);
    for (uint i = 0; i < length; ++i) {
        if (nodes[i].end_stamp > block.timestamp) {
            total_lemos = sub(total_lemos, nodes[i].num_lemos);
        }
    }
    return total_lemos;
}

function STAKE(uint256 tokens) external nonReentrant {
    require(IERC20(TRY).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user for locking");
    uint256 transferTxFee = (onePercent(tokens).mul(txFee)).div(10);
    uint256 tokensToStake = (tokens.sub(transferTxFee));
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = tokensToStake.add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokensToStake);
    addStakeholder(msg.sender);
    emit STAKED(msg.sender, tokens);
}

function claimContract(uint contractId) public whenNotPaused returns(uint) {
    require(TotalAmount[contractId] > 0, "SEER OFFICAL WARNING: Contract has not been created");
    Contract storage _contract = contracts[contractId];
    require(_contract.result > 0, "SEER OFFICAL WARNING: Contract has not been revealed");
    require(_contract.IfPlayed[msg.sender] == true, "SEER OFFICAL WARNING: You did not play this contract");
    require(_contract.IfClaimed[msg.sender] == false, "SEER OFFICAL WARNING: You already claimed reward");
    uint reward;
    uint[4] memory _amount = _contract.PlayerToBet[msg.sender].amount;
    require(_amount[_contract.result - 1] > 0, "SEER OFFICAL WARNING: You are not qualified");
    reward = _amount[_contract.result - 1] * taxRate * TotalAmount[contractId] / EachAmount[contractId][_contract.result - 1] / 10000;
    msg.sender.transfer(reward);
    _contract.IfClaimed[msg.sender] == true;
    emit ContractClaimed(msg.sender, reward);
    return reward;
}

function betContract(uint contractId, uint side, uint amount) public payable whenNotPaused returns(bool) {
    require(TotalAmount[contractId] > 0, "SEER OFFICAL WARNING: Contract has not been created");
    require(amount >= minBet && amount <= maxBet, "SEER OFFICAL WARNING: Does not meet min or max bet requirement");
    require(msg.value >= amount, "SEER OFFICAL WARNING: Does not send enough ETH");
    Contract storage _contract = contracts[contractId];
    require(side < _contract.sides, "SEER OFFICAL WARNING: You did not in correct side range");
    require(now < _contract.BetEndTime, "SEER OFFICAL WARNING: Contract cannot be bet anymore");
    require(_contract.result == 0, "SEER OFFICAL WARNING: Contact terminated");
    uint timeFactor = _calculateTimeFactor(_contract.BetEndTime, _contract.StartTime);
    if (_contract.IfPlayed[msg.sender] == true) {
        Bet storage _bet = _contract.PlayerToBet[msg.sender];
        _bet.amount[side] += amount;
        _bet.timestamp = timeFactor;
        EachAmount[contractId][side] += amount;
        TotalAmount[contractId] += amount;
        emit BetAdjustSuccess(msg.sender, side, _bet.amount, timeFactor);
    } else {
        uint[4] memory _amount;
        _amount[side] = amount;
        Bet memory _bet = Bet({
            amount: _amount,
            timestamp: timeFactor
        });
        _contract.IfPlayed[msg.sender] = true;
        _contract.PlayerToBet[msg.sender] = _bet;
        EachAmount[contractId][side] += amount;
        TotalAmount[contractId] += amount;
        TotalPlayers[contractId] += 1;
        emit NewBetSuccess(msg.sender, side, _amount, timeFactor);
    }
    return true;
}

function revealContract(uint contractId, uint result) public whenNotPaused onlyAdmin {
    require(result >= 1 && result <= 4, "SEER OFFICAL WARNING: Cannot recogonize result");
    Contract storage _contract = contracts[contractId];
    require(now > _contract.ContractTime, "SEER OFFICAL WARNING: Contract cannot be revealed yet");
    _contract.result = result;
    emit ContractRevealed(contractId, result);
}

function createContract(uint sides, uint[4] memory amounts, uint contractTime, uint betEndTime) public payable whenNotPaused returns(uint) {
    require(amounts[0] > 0 || amounts[1] > 0 || amounts[2] > 0 || amounts[3] > 0, "SEER OFFICAL WARNING: At least bet on one side");
    uint total = amounts[0] + amounts[1] + amounts[2] + amounts[3];
    require(sides >= 2 && sides <= 4, "SEER OFFICAL WARNING: Can only have 2-4 sides");
    require(msg.value >= (total + contractFee), "SEER OFFICAL WARNING: Does not send enough ETH");
    require((now + 1 hours) <= betEndTime, "SEER OFFICAL WARNING: At least have one hour bet time");
    require((contractTime - now) / 3 >= (betEndTime - now), "SEER OFFICAL WARNING: Bet time need to be less or equal than 1/3 of total contract time");
    Bet memory _bet = Bet({
        amount: amounts,
        timestamp: _calculateTimeFactor(betEndTime, now)
    });
    Contract memory _contract = Contract({
        result: 0,
        sides: sides,
        StartTime: now,
        BetEndTime: betEndTime,
        ContractTime: contractTime
    });
    uint newContractId = contracts.push(_contract) - 1;
    Contract storage newContract = contracts[newContractId];
    newContract.PlayerToBet[msg.sender] = _bet;
    newContract.IfPlayed[msg.sender] = true;
    TotalAmount[newContractId] = total;
    EachAmount[newContractId] = amounts;
    TotalPlayers[newContractId] = 1;
    emit ContractCreated(newContractId, sides, amounts, msg.sender, contractTime, betEndTime);
    return 0;
}

function cancelAdoptionRequest(bytes5 catId) {
    AdoptionRequest storage existingRequest = adoptionRequests[catId];
    require(existingRequest.exists);
    require(existingRequest.requester == msg.sender);
    uint price = existingRequest.price;
    adoptionRequests[catId] = AdoptionRequest(false, catId, 0x0, 0);
    msg.sender.transfer(price);
    AdoptionRequestCancelled(catId);
}

function _bid(
    uint256 _sireId,
    uint256 _matronId,
    uint256 _bidAmount,
    Auction storage _auction
)
internal
returns(uint256) {
    uint256 _price = _getCurrentPrice(_auction);
    uint256 _priceWithFee = _price + incubatorContract.breedingFee();
    assert(_priceWithFee >= _price);
    require(_bidAmount >= _priceWithFee);
    address _seller = _auction.seller;
    _removeAuction(_sireId);
    if (_price > 0) {
        uint256 _auctioneerCut = _computeCut(_price);
        uint256 _sellerProceeds = _price - _auctioneerCut;
        _seller.transfer(_sellerProceeds);
    }
    if (_bidAmount > _priceWithFee) {
        uint256 _bidExcess = _bidAmount - _priceWithFee;
        msg.sender.transfer(_bidExcess);
    }
    emit AuctionSuccessful(
        _sireId,
        _matronId,
        _price,
        msg.sender
    );
    return _price;
}

function createAuction(
    uint256 _axieId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration
)
external
whenNotPaused
canBeStoredWith128Bits(_startingPrice)
canBeStoredWith128Bits(_endingPrice)
canBeStoredWith64Bits(_duration) {
    address _seller = msg.sender;
    require(coreContract.ownerOf(_axieId) == _seller);
    incubatorContract.requireEnoughExpForBreeding(_axieId); 
    _escrow(_seller, _axieId);
    Auction memory _auction = Auction(
        _seller,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint64(_duration),
        uint64(now)
    );
    _addAuction(
        _axieId,
        _auction,
        _seller
    );
}

function bidOnSiring(
    uint256 _sireId,
    uint256 _matronId,
    uint256 _birthPlace
)
external
payable
whenNotPaused
returns(uint256  ) {
    Auction storage _auction = auctions[_sireId];
    require(_isOnAuction(_auction));
    require(msg.sender == coreContract.ownerOf(_matronId));
    address _seller = _auction.seller;
    _bid(_sireId, _matronId, msg.value, _auction);
    uint256 _axieId = incubatorContract.breedAxies.value(
        incubatorContract.breedingFee()
    )(
        _sireId,
        _matronId,
        _birthPlace
    );
    _transfer(_seller, _sireId);
    return _axieId;
}

function _computeCurrentPrice(
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration,
    uint256 _secondsPassed
)
internal
pure
returns(uint256) {
    if (_secondsPassed >= _duration) {
        return _endingPrice;
    } else {
        int256 _totalPriceChange = int256(_endingPrice) - int256(_startingPrice);
        int256 _currentPriceChange = _totalPriceChange * int256(_secondsPassed) / int256(_duration);
        int256 _currentPrice = int256(_startingPrice) + _currentPriceChange;
        return uint256(_currentPrice);
    }
}

function getAuction(
    uint256 _axieId
)
external
view
returns(
    address seller,
    uint256 startingPrice,
    uint256 endingPrice,
    uint256 duration,
    uint256 startedAt
) {
    Auction storage _auction = auctions[_axieId];
    require(_isOnAuction(_auction));
    return (
        _auction.seller,
        _auction.startingPrice,
        _auction.endingPrice,
        _auction.duration,
        _auction.startedAt
    );
}

function getCurrentPrice(
    uint256 _axieId
)
external
view
returns(uint256) {
    Auction storage _auction = auctions[_axieId];
    require(_isOnAuction(_auction));
    return _getCurrentPrice(_auction);
}

function cancelAuction(uint256 _axieId) external {
    Auction storage _auction = auctions[_axieId];
    require(_isOnAuction(_auction));
    require(msg.sender == _auction.seller);
    _cancelAuction(_axieId, _auction.seller);
}

function cancelAuctionWhenPaused(
    uint256 _axieId
)
external
whenPaused
onlyOwner {
    Auction storage _auction = auctions[_axieId];
    require(_isOnAuction(_auction));
    _cancelAuction(_axieId, _auction.seller);
}

function _addAuction(
    uint256 _axieId,
    Auction memory _auction,
    address _seller
)
internal {
    require(_auction.duration >= 1 minutes);
    auctions[_axieId] = _auction;
    emit AuctionCreated(
        _axieId,
        uint256(_auction.startingPrice),
        uint256(_auction.endingPrice),
        uint256(_auction.duration),
        _seller
    );
}

function _getCurrentPrice(
    Auction storage _auction
)
internal
view
returns(uint256) {
    uint256 _secondsPassed = 0;
    if (now > _auction.startedAt) {
        _secondsPassed = now - _auction.startedAt;
    }
    return _computeCurrentPrice(
        _auction.startingPrice,
        _auction.endingPrice,
        _auction.duration,
        _secondsPassed
    );
}

receive() external payable {
    require(saleOpen, "Sale is not open");
    require(usersInvestments[msg.sender].add(msg.value) <= 1 ether &&
        usersInvestments[msg.sender].add(msg.value) >= 100 finney,
        "Installment must be in range of 1 to 0.1 ether");
    uint256 tokens = getTokenAmount(msg.value);
    require(IToken(tokenAddress).transfer(msg.sender, tokens), "Insufficient balance of sale contract!");
    usersInvestments[msg.sender] = usersInvestments[msg.sender].add(msg.value);
    owner.transfer(msg.value);
}

function withdraw(uint256 amount) external override onlyClient {
    uint256 _lastWithdrawal = lastWithdrawal;
    require(_lastWithdrawal <= block.timestamp, "withdrawal is not yet active");
    uint duration = block.timestamp.sub(_lastWithdrawal);
    require(amount.mul(365 * 24 * 60 * 60) <= maxAnnualRate.mul(duration), "ProtocolWallet::withdraw - requested amount is larger than allowed by rate");
    lastWithdrawal = block.timestamp;
    if (amount > 0) {
        require(token.transfer(msg.sender, amount), "ProtocolWallet::withdraw - transfer failed");
    }
}

function createRequestAsPayeeAction(
    address[] _payeesIdAddress,
    bytes _payeesPaymentAddress,
    int256[] _expectedAmounts,
    address _payer,
    bytes _payerRefundAddress,
    string _data)
external
payable
whenNotPaused
returns(bytes32 requestId) {
    require(msg.sender == _payeesIdAddress[0] && msg.sender != _payer && _payer != 0);
    int256 totalExpectedAmounts;
    (requestId, totalExpectedAmounts) = createCoreRequestInternal(_payer, _payeesIdAddress, _expectedAmounts, _data);
    uint256 fees = collectEstimation(totalExpectedAmounts);
    require(fees == msg.value && collectForREQBurning(fees));
    extractAndStoreBitcoinAddresses(requestId, _payeesIdAddress.length, _payeesPaymentAddress, _payerRefundAddress);
    return requestId;
}

function createAcceptAndAdditionalsFromBytes(
    bytes _requestData,
    bytes _payeesPaymentAddress,
    bytes _payerRefundAddress,
    uint256[] _additionals)
internal
returns(bytes32 requestId) {
    address mainPayee = extractAddress(_requestData, 41);
    require(msg.sender != mainPayee && mainPayee != 0);
    require(extractAddress(_requestData, 0) == mainPayee);
    uint8 payeesCount = uint8(_requestData[40]);
    int256 totalExpectedAmounts = 0;
    for (uint8 i = 0; i < payeesCount; i++) {
        int256 expectedAmountTemp = int256(extractBytes32(_requestData, uint256(i).mul(52).add(61)));
        totalExpectedAmounts = totalExpectedAmounts.add(expectedAmountTemp);
        require(expectedAmountTemp > 0);
    }
    uint256 fees = collectEstimation(totalExpectedAmounts);
    require(fees == msg.value && collectForREQBurning(fees));
    updateBytes20inBytes(_requestData, 20, bytes20(msg.sender));
    requestId = requestCore.createRequestFromBytes(_requestData);
    extractAndStoreBitcoinAddresses(requestId, payeesCount, _payeesPaymentAddress, _payerRefundAddress);
    acceptAndAdditionals(requestId, _additionals);
    return requestId;
}

function broadcastSignedRequestAsPayerAction(
    bytes _requestData, 
    bytes _payeesPaymentAddress,
    bytes _payerRefundAddress,
    uint256[] _additionals,
    uint256 _expirationDate,
    bytes _signature)
external
payable
whenNotPaused
returns(bytes32 requestId) {
    require(_expirationDate >= block.timestamp);
    require(checkRequestSignature(_requestData, _payeesPaymentAddress, _expirationDate, _signature));
    return createAcceptAndAdditionalsFromBytes(_requestData, _payeesPaymentAddress, _payerRefundAddress, _additionals);
}

function annualInterest() constant returns(uint interest) {
    uint _now = now;
    interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime)).div(1 years) == 0) {
        interest = (1650 * maxMintProofOfStake).div(100);
    } else if ((_now.sub(stakeStartTime)).div(1 years) == 1) {
        interest = (770 * maxMintProofOfStake).div(100);
    }
}

function getProofOfStakeReward(address _address) internal returns(uint) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint _now = now;
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    uint interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime)).div(1 years) == 0) {
        interest = (1650 * maxMintProofOfStake).div(100);
    } else if ((_now.sub(stakeStartTime)).div(1 years) == 1) {
        interest = (770 * maxMintProofOfStake).div(100);
    }
    return (_coinAge * interest).div(365 * (10 ** decimals));
}

function balanceOfUnclaimed(address player) public constant returns(uint256) {
    uint256 lSave = lastJadeSaveTime[player];
    if (lSave > 0 && lSave < block.timestamp) {
        return SafeMath.mul(getJadeProduction(player), SafeMath.div(SafeMath.sub(block.timestamp, lSave), 10));
    }
    return 0;
}

