function queue(uint256 proposalId) public {
    require(
        state(proposalId) == ProposalState.Succeeded,
        "GovernorAlpha::queue: proposal can only be queued if it is succeeded"
    );
    Proposal storage proposal = proposals[proposalId];
    uint256 eta = add256(block.timestamp, timelock.delay());
    for (uint256 i = 0; i < proposal.targets.length; i++) {
        _queueOrRevert(
            proposal.targets[i],
            proposal.values[i],
            proposal.signatures[i],
            proposal.calldatas[i],
            eta
        );
    }
    proposal.eta = eta;
    emit ProposalQueued(proposalId, eta);
}

function add256(uint256 a, uint256 b) internal pure returns(uint256) {
    uint256 c = a + b;
    require(c >= a, "addition overflow");
    return c;
}

function state(uint256 proposalId) public view returns(ProposalState) {
    require(
        proposalCount >= proposalId && proposalId > 0,
        "GovernorAlpha::state: invalid proposal id"
    );
    Proposal storage proposal = proposals[proposalId];
    if (proposal.canceled) {
        return ProposalState.Canceled;
    } else if (block.number <= proposal.startBlock) {
        return ProposalState.Pending;
    } else if (block.number <= proposal.endBlock) {
        return ProposalState.Active;
    } else if (
        proposal.forVotes <= proposal.againstVotes ||
        proposal.forVotes < proposal.quorumatPropose
    ) {
        return ProposalState.Defeated;
    } else if (proposal.eta == 0) {
        return ProposalState.Succeeded;
    } else if (proposal.executed) {
        return ProposalState.Executed;
    } else if (
        block.timestamp >= add256(proposal.eta, timelock.GRACE_PERIOD())
    ) {
        return ProposalState.Expired;
    } else {
        return ProposalState.Queued;
    }
}

function _queueOrRevert(
    address target,
    uint256 value,
    string memory signature,
    bytes memory data,
    uint256 eta
) internal {
    require(
        !timelock.queuedTransactions(
            keccak256(abi.encode(target, value, signature, data, eta))
        ),
        "GovernorAlpha::_queueOrRevert: proposal action already queued at eta"
    );
    timelock.queueTransaction(target, value, signature, data, eta);
}

function _castVote(
    address voter,
    uint256 proposalId,
    bool support
) internal {
    require(
        state(proposalId) == ProposalState.Active,
        "GovernorAlpha::_castVote: voting is closed"
    );
    Proposal storage proposal = proposals[proposalId];
    Receipt storage receipt = proposal.receipts[voter];
    require(
        receipt.hasVoted == false,
        "GovernorAlpha::_castVote: voter already voted"
    );
    uint256 votes = pheezez.getPriorVotes(voter, proposal.startBlock);
    uint256 voteLimiter = SafeMath.div(
        SafeMath.mul(pheezez.votesAvailable(), vRatio),
        100
    );
    if (votes > voteLimiter) {
        votes = voteLimiter;
    }
    if (support) {
        proposal.forVotes = add256(proposal.forVotes, votes);
    } else {
        proposal.againstVotes = add256(proposal.againstVotes, votes);
    }
    receipt.hasVoted = true;
    receipt.support = support;
    receipt.votes = votes;
    emit VoteCast(voter, proposalId, support, votes);
}

function cancel(uint256 proposalId) public {
    ProposalState state = state(proposalId);
    require(
        state != ProposalState.Executed,
        "GovernorAlpha::cancel: cannot cancel executed proposal"
    );
    Proposal storage proposal = proposals[proposalId];
    require(
        msg.sender == guardian || proposal.proposer == msg.sender,
        "GovernorAlpha::cancel: Only the creator can cancel a proposal"
    ); 
    proposal.canceled = true;
    for (uint256 i = 0; i < proposal.targets.length; i++) {
        timelock.cancelTransaction(
            proposal.targets[i],
            proposal.values[i],
            proposal.signatures[i],
            proposal.calldatas[i],
            proposal.eta
        );
    }
    emit ProposalCanceled(proposalId);
}

function SpudToDivs(uint256 amount) public {
    address sender = msg.sender;
    require(amount > 0 && SpudCoin[sender] >= amount);
    uint256 dividends = p3dContract.myDividends(true);
    require(dividends > 0);
    uint256 amt = dividends.div(100);
    p3dContract.withdraw();
    SPASM_.disburse.value(amt)(); 
    SpudPot = SpudPot.add(dividends.sub(amt));
    uint256 payouts = SpudPot.mul(amount).div(totalsupply);
    SpudPot = SpudPot.sub(payouts);
    SpudCoin[sender] = SpudCoin[sender].sub(amount);
    totalsupply = totalsupply.sub(amount);
    sender.transfer(payouts);
}

function GetSpud(address MN) public payable {
    require(msg.value >= 1 finney);
    address sender = msg.sender;
    uint256 blocknr = block.number;
    uint256 curround = round;
    uint256 refblocknr = Spudgame[curround].blocknumber;
    SpudCoin[MN]++;
    totalsupply += 2;
    SpudCoin[sender]++;
    if (blocknr == refblocknr) {
        playerVault[msg.sender] += msg.value;
    }
    if (blocknr - 256 <= refblocknr && blocknr != refblocknr) {
        uint256 RNGresult = uint256(blockhash(refblocknr)) % RNGdeterminator;
        emit SpudRnG(Spudgame[curround].player, RNGresult);
        Pot += msg.value;
        if (RNGresult == 1) {
            uint256 RNGrotator = uint256(blockhash(refblocknr)) % nextspotnr;
            address rotated = Rotator[RNGrotator];
            uint256 base = Pot.div(10);
            p3dContract.buy.value(base)(rotated);
            Spudgame[curround].player.transfer(base.mul(5));
            emit payout(Spudgame[curround].player, base.mul(5));
            Pot = Pot.sub(base.mul(6));
            uint256 nextround = curround + 1;
            Spudgame[nextround].player = sender;
            Spudgame[nextround].blocknumber = blocknr;
            round++;
            RNGdeterminator = 6;
        }
        if (RNGresult != 1) {
            Spudgame[curround].player = sender;
            Spudgame[curround].blocknumber = blocknr;
        }
    }
    if (blocknr - 256 > refblocknr) {
        Pot += msg.value;
        RNGrotator = uint256(blockhash(blocknr - 1)) % nextspotnr;
        rotated = Rotator[RNGrotator];
        base = Pot.div(10);
        p3dContract.buy.value(base)(rotated);
        Spudgame[round].player.transfer(base.mul(5));
        emit payout(Spudgame[round].player, base.mul(5));
        Pot = Pot.sub(base.mul(6));
        nextround = curround + 1;
        Spudgame[nextround].player = sender;
        Spudgame[nextround].blocknumber = blocknr;
        round++;
        RNGdeterminator = 6;
    }
}

function remainingMintCapacity()
public
view
returns(uint256) {
    if (now > mintPeriodStart + mintPeriod)
        return mintCapacity;
    if (mintCapacity < amountMinted)
        return 0;
    return mintCapacity - amountMinted;
}

function isUnderMintLimit(uint256 _amount)
internal
view
returns(bool) {
    uint256 effAmountMinted = (now > mintPeriodStart + mintPeriod) ? 0 : amountMinted;
    if (effAmountMinted + _amount > mintCapacity ||
        effAmountMinted + _amount < effAmountMinted) {
        return false;
    }
    return true;
}

function _mint(address _to, uint256 _amount)
internal {
    require(_to != address(0), "ERC20: mint to the zero address");
    require(_to != address(this), "ERC20: mint to token contract");
    if (now > mintPeriodStart + mintPeriod) {
        amountMinted = 0;
        mintPeriodStart = now;
    }
    amountMinted = amountMinted.add(_amount);
    tokenTotalSupply = tokenTotalSupply.add(_amount);
    balances[_to] = balances[_to].add(_amount);
    if (balances[_to] > 0) holders.insert(_to);
    emit Transfer(address(0), _to, _amount);
    emit Mint(_to, _amount);
}

function executeTransaction(bytes32 _transactionId)
public
onlyOwner
confirmed(_transactionId, msg.sender)
notExecuted(_transactionId) {
    if (isConfirmed(_transactionId)) {
        Transaction storage txn = transactions[_transactionId];
        txn.executed = true;
        (bool success, ) = address(this).call(txn.data);
        if (success) {
            emit Execution(_transactionId);
        } else {
            emit ExecutionFailure(_transactionId);
            txn.executed = false;
        }
    }
}

