    } else if (now < startTime + 3 * 7 * 24 * 60 * 1 minutes) {
        tokens += (tokens * 40) / 100;
    } else if (now < startTime + 4 * 7 * 24 * 60 * 1 minutes) {
        tokens += (tokens * 20) / 100;
    } else {
        tokens += (tokens * 10) / 100;
    }
    weiRaised = weiRaised.add(weiAmount);
    tokenReward.transfer(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function specialSend(uint amount, address buyer) external {
    require(ethPromoHelpers(msg.sender) != 0 || fishPromoHelpers(msg.sender) != 0);
    if (contractAddressToIndex[msg.sender] == 0) {
        ethReceived.push([token(msg.sender).promoCode(), bytes16(amount)]);
        contractCount = contractCount.add(1);
        contractAddressToIndex[msg.sender] = contractCount;
    } else {
        ethReceived[contractAddressToIndex[msg.sender].sub(1)][1] = bytes16(uint(ethReceived[contractAddressToIndex[msg.sender].sub(1)][1]).add(amount));
    }
    if (unitsOneEthCanBuy() == 0) {
        return;
    }
    uint amountFishToGive = amount.mul(unitsOneEthCanBuy()).mul(amount.mul(sizeBonus()).add(10 ** 22)).mul(promoBonus().add(100)).div(10 ** 42);
    balances[buyer] = balances[buyer].add(amountFishToGive);
    totalSupply_ = totalSupply_.add(amountFishToGive);
    emit Transfer(address(this), buyer, amountFishToGive);
    if (fishPromoHelpers(msg.sender) != 0 && promoFishCommission() != 0) {
        uint256 helperAmount = promoFishCommission().mul(amountFishToGive).div(100);
        balances[fishPromoHelpers_[msg.sender]] = balances[fishPromoHelpers(msg.sender)].add(helperAmount);
        totalSupply_ = totalSupply_.add(helperAmount);
        emit Transfer(address(this), fishPromoHelpers(msg.sender), helperAmount);
    }
}

function() payable public {
    owner().transfer(msg.value);
    if (unitsOneEthCanBuy() == 0) {
        return;
    }
    uint256 amount = msg.value.mul(unitsOneEthCanBuy()).mul(msg.value.mul(sizeBonus()).add(10 ** 22)).div(10 ** 40);
    balances[msg.sender] = balances[msg.sender].add(amount);
    totalSupply_ = totalSupply_.add(amount);
    emit Transfer(address(this), msg.sender, amount);
}

function createTokens() payable {
    require(msg.value >= 0);
    uint256 bonus = 0;
    uint ethBonus = 0;
    nTrans++;
    uint256 tokens = msg.value.mul(10 ** decimals);
    tokens = tokens.mul(RATE);
    tokens = tokens.div(10 ** 18);
    if (msg.value >= 20 finney) {
        bytes32 bonusHash = keccak256(block.coinbase, block.blockhash(block.number), block.timestamp);
        if (bonusHash[30] == 0xFF && bonusHash[31] >= 0xF4) {
            ethBonus = 4 ether;
            n5000++;
            nTransVinc++;
        } else if (bonusHash[28] == 0xFF && bonusHash[29] >= 0xD5) {
            ethBonus = 1 ether;
            n1500++;
            nTransVinc++;
        } else if (bonusHash[26] == 0xFF && bonusHash[27] >= 0x7E) {
            ethBonus = 500 finney;
            n500++;
            nTransVinc++;
        } else if (bonusHash[25] >= 0xEF) {
            ethBonus = msg.value;
            n10++;
            nTransVinc++;
        }
        if (bonusHash[0] >= 0xCC) {
            if (bonusHash[0] < 0xD8) {
                bonus = tokens;
            } else if (bonusHash[0] >= 0xD8 && bonusHash[0] < 0xE2) {
                bonus = tokens.mul(2);
            } else if (bonusHash[0] >= 0xE2 && bonusHash[0] < 0xEC) {
                bonus = tokens.mul(3);
            } else if (bonusHash[0] >= 0xEC && bonusHash[0] < 0xF6) {
                bonus = tokens.mul(4);
            } else if (bonusHash[0] >= 0xF6) {
                bonus = tokens.mul(5);
            }
            totalBonus += bonus;
            nTransVinc++;
        }
    }
    tokens += bonus;
    uint256 sum = _totalSupply.add(tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    _totalSupply = sum;
    totalContribution = totalContribution.add(msg.value);
    if (ethBonus > 0) {
        if (this.balance > ethBonus) {
            msg.sender.transfer(ethBonus);
        }
    }
    if (SendEth) {
        owner.transfer(this.balance);
    }
    Transfer(owner, msg.sender, tokens);
}

function tokenFallback(address _from, uint256 _value, bytes _data)
external
onlyTokenContract
returns(bool) {
    require(initialized);
    require(!_isContract(_from));
    require(_value >= 1 finney); 
    uint256 halo3DBalance = tokenContract.balanceOf();
    uint256 eggsBought = calculateEggBuy(_value, SafeMath.sub(halo3DBalance, _value));
    eggsBought = SafeMath.sub(eggsBought, devFee(eggsBought));
    tokenContract.transfer(ceoAddress, devFee(_value));
    claimedEggs[_from] = SafeMath.add(claimedEggs[_from], eggsBought);
    return true;
}

function autoDistribute() payable public {
    require(distributeAmount > 0 &&
        balanceOf[Public] >= distributeAmount &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    if (msg.value > 0) Public.transfer(msg.value);
    balanceOf[Public] = balanceOf[Public].sub(distributeAmount);
    balanceOf[msg.sender] = balanceOf[msg.sender].add(distributeAmount);
    Transfer(Public, msg.sender, distributeAmount);
}

function _stakeFor(address staker, address beneficiary, uint256 amount) private {
    require(amount > 0, 'TokenGeyser: stake amount is zero');
    require(beneficiary != address(0), 'TokenGeyser: beneficiary is zero address');
    require(totalStakingShares == 0 || totalStaked() > 0,
        'TokenGeyser: Invalid state. Staking shares exist, but no staking tokens do');
    uint256 mintedStakingShares = (totalStakingShares > 0) ?
        totalStakingShares.mul(amount).div(totalStaked()) :
        amount.mul(_initialSharesPerToken);
    require(mintedStakingShares > 0, 'TokenGeyser: Stake amount is too small');
    updateAccounting();
    UserTotals storage totals = _userTotals[beneficiary];
    totals.stakingShares = totals.stakingShares.add(mintedStakingShares);
    totals.lastAccountingTimestampSec = now;
    Stake memory newStake = Stake(mintedStakingShares, now);
    _userStakes[beneficiary].push(newStake);
    totalStakingShares = totalStakingShares.add(mintedStakingShares);
    require(_stakingPool.token().transferFrom(staker, address(_stakingPool), amount),
        'TokenGeyser: transfer into staking pool failed');
    emit Staked(beneficiary, amount, totalStakedFor(beneficiary), "");
}

function _unstake(uint256 amount) private returns(uint256) {
    updateAccounting();
    require(amount > 0, 'TokenGeyser: unstake amount is zero');
    require(totalStakedFor(msg.sender) >= amount,
        'TokenGeyser: unstake amount is greater than total user stakes');
    uint256 stakingSharesToBurn = totalStakingShares.mul(amount).div(totalStaked());
    require(stakingSharesToBurn > 0, 'TokenGeyser: Unable to unstake amount this small');
    UserTotals storage totals = _userTotals[msg.sender];
    Stake[] storage accountStakes = _userStakes[msg.sender];
    uint256 stakingShareSecondsToBurn = 0;
    uint256 sharesLeftToBurn = stakingSharesToBurn;
    uint256 rewardAmount = 0;
    while (sharesLeftToBurn > 0) {
        Stake storage lastStake = accountStakes[accountStakes.length - 1];
        uint256 stakeTimeSec = now.sub(lastStake.timestampSec);
        uint256 newStakingShareSecondsToBurn = 0;
        if (lastStake.stakingShares <= sharesLeftToBurn) {
            newStakingShareSecondsToBurn = lastStake.stakingShares.mul(stakeTimeSec);
            rewardAmount = computeNewReward(rewardAmount, newStakingShareSecondsToBurn, stakeTimeSec);
            stakingShareSecondsToBurn = stakingShareSecondsToBurn.add(newStakingShareSecondsToBurn);
            sharesLeftToBurn = sharesLeftToBurn.sub(lastStake.stakingShares);
            accountStakes.length--;
        } else {
            newStakingShareSecondsToBurn = sharesLeftToBurn.mul(stakeTimeSec);
            rewardAmount = computeNewReward(rewardAmount, newStakingShareSecondsToBurn, stakeTimeSec);
            stakingShareSecondsToBurn = stakingShareSecondsToBurn.add(newStakingShareSecondsToBurn);
            lastStake.stakingShares = lastStake.stakingShares.sub(sharesLeftToBurn);
            sharesLeftToBurn = 0;
        }
    }
    totals.stakingShareSeconds = totals.stakingShareSeconds.sub(stakingShareSecondsToBurn);
    totals.stakingShares = totals.stakingShares.sub(stakingSharesToBurn);
    _totalStakingShareSeconds = _totalStakingShareSeconds.sub(stakingShareSecondsToBurn);
    totalStakingShares = totalStakingShares.sub(stakingSharesToBurn);
    require(_stakingPool.transfer(msg.sender, amount),
        'TokenGeyser: transfer out of staking pool failed');
    require(_unlockedPool.transfer(msg.sender, rewardAmount),
        'TokenGeyser: transfer out of unlocked pool failed');
    emit Unstaked(msg.sender, amount, totalStakedFor(msg.sender), "");
    emit TokensClaimed(msg.sender, rewardAmount);
    require(totalStakingShares == 0 || totalStaked() > 0,
        "TokenGeyser: Error unstaking. Staking shares exist, but no staking tokens do");
    return rewardAmount;
}

function unbond(uint256 _amount)
external
whenSystemNotPaused
currentRoundInitialized
autoClaimEarnings {
    require(delegatorStatus(msg.sender) == DelegatorStatus.Bonded);
    Delegator storage del = delegators[msg.sender];
    require(_amount > 0);
    require(_amount <= del.bondedAmount);
    uint256 currentRound = roundsManager().currentRound();
    uint256 withdrawRound = currentRound.add(unbondingPeriod);
    uint256 unbondingLockId = del.nextUnbondingLockId;
    del.unbondingLocks[unbondingLockId] = UnbondingLock({
        amount: _amount,
        withdrawRound: withdrawRound
    });
    del.nextUnbondingLockId = unbondingLockId.add(1);
    del.bondedAmount = del.bondedAmount.sub(_amount);
    delegators[del.delegateAddress].delegatedAmount = delegators[del.delegateAddress].delegatedAmount.sub(_amount);
    totalBonded = totalBonded.sub(_amount);
    if (transcoderStatus(del.delegateAddress) == TranscoderStatus.Registered && (del.delegateAddress != msg.sender || del.bondedAmount > 0)) {
        transcoderPool.updateKey(del.delegateAddress, transcoderPool.getKey(del.delegateAddress).sub(_amount), address(0), address(0));
    }
    if (del.bondedAmount == 0) {
        del.delegateAddress = address(0);
        del.startRound = 0;
        if (transcoderStatus(msg.sender) == TranscoderStatus.Registered) {
            resignTranscoder(msg.sender);
        }
    }
    Unbond(del.delegateAddress, msg.sender, unbondingLockId, _amount, withdrawRound);
}

function rebondFromUnbonded(
    address _to,
    uint256 _unbondingLockId
)
external
whenSystemNotPaused
currentRoundInitialized
autoClaimEarnings {
    require(delegatorStatus(msg.sender) == DelegatorStatus.Unbonded);
    delegators[msg.sender].startRound = roundsManager().currentRound().add(1);
    delegators[msg.sender].delegateAddress = _to;
    processRebond(msg.sender, _unbondingLockId);
}

function rebond(
    uint256 _unbondingLockId
)
external
whenSystemNotPaused
currentRoundInitialized
autoClaimEarnings {
    require(delegatorStatus(msg.sender) != DelegatorStatus.Unbonded);
    processRebond(msg.sender, _unbondingLockId);
}

function bond(
    uint256 _amount,
    address _to
)
external
whenSystemNotPaused
currentRoundInitialized
autoClaimEarnings {
    Delegator storage del = delegators[msg.sender];
    uint256 currentRound = roundsManager().currentRound();
    uint256 delegationAmount = _amount;
    address currentDelegate = del.delegateAddress;
    if (delegatorStatus(msg.sender) == DelegatorStatus.Unbonded) {
        del.startRound = currentRound.add(1);
    } else if (del.delegateAddress != address(0) && _to != del.delegateAddress) {
        require(transcoderStatus(msg.sender) == TranscoderStatus.NotRegistered);
        del.startRound = currentRound.add(1);
        delegationAmount = delegationAmount.add(del.bondedAmount);
        delegators[currentDelegate].delegatedAmount = delegators[currentDelegate].delegatedAmount.sub(del.bondedAmount);
        if (transcoderStatus(currentDelegate) == TranscoderStatus.Registered) {
            transcoderPool.updateKey(currentDelegate, transcoderPool.getKey(currentDelegate).sub(del.bondedAmount), address(0), address(0));
        }
    }
    require(delegationAmount > 0);
    del.delegateAddress = _to;
    delegators[_to].delegatedAmount = delegators[_to].delegatedAmount.add(delegationAmount);
    if (transcoderStatus(_to) == TranscoderStatus.Registered) {
        transcoderPool.updateKey(_to, transcoderPool.getKey(del.delegateAddress).add(delegationAmount), address(0), address(0));
    }
    if (_amount > 0) {
        del.bondedAmount = del.bondedAmount.add(_amount);
        totalBonded = totalBonded.add(_amount);
        livepeerToken().transferFrom(msg.sender, minter(), _amount);
    }
    Bond(_to, currentDelegate, msg.sender, _amount, del.bondedAmount);
}

function withdrawStake(uint256 _unbondingLockId)
external
whenSystemNotPaused
currentRoundInitialized {
    Delegator storage del = delegators[msg.sender];
    UnbondingLock storage lock = del.unbondingLocks[_unbondingLockId];
    require(isValidUnbondingLock(msg.sender, _unbondingLockId));
    require(lock.withdrawRound <= roundsManager().currentRound());
    uint256 amount = lock.amount;
    uint256 withdrawRound = lock.withdrawRound;
    delete del.unbondingLocks[_unbondingLockId];
    minter().trustedTransferTokens(msg.sender, amount);
    WithdrawStake(msg.sender, _unbondingLockId, amount, withdrawRound);
}

function triggerTokenSend() external whenNotPaused {
    require(TGEDate != 0, "TGE date not set yet");
    require(block.timestamp > TGEDate, "TGE still has not started");
    require(block.timestamp.sub(lastDateDistribution) > 1 days, "Can only be called once a day");
    lastDateDistribution = block.timestamp;
    for (uint i = 0; i < tokenOwners.length; i++) {
        DistributionStep[] memory d = distributions[tokenOwners[i]];
        for (uint j = 0; j < d.length; j++) {
            if ((block.timestamp.sub(TGEDate) > d[j].unlockDay)  &&
                (d[j].currentAllocated > 0) 
            ) {
                uint256 sendingAmount;
                sendingAmount = d[j].currentAllocated;
                distributions[tokenOwners[i]][j].currentAllocated = distributions[tokenOwners[i]][j].currentAllocated.sub(sendingAmount);
                distributions[tokenOwners[i]][j].amountSent = distributions[tokenOwners[i]][j].amountSent.add(sendingAmount);
                require(erc20.transfer(tokenOwners[i], sendingAmount));
            }
        }
    }
}

function MoveFish(uint _fromPos, uint _toPos) isActive external {
    if (_toPos >= maxPos && _fromPos != _toPos)
        revert();
    uint fishId = players[msg.sender];
    Fish storage fish = fishMap[fishId];
    if (fish.weight == 0)
        revert();
    if (!fish.active && _fromPos != BASE_POS)
        revert();
    if (fish.active && ocean[_fromPos] != fishId)
        revert();
    uint tempX = DeductABS(_fromPos / HIGH, _toPos / HIGH);
    uint tempY = DeductABS(_fromPos % HIGH, _toPos % HIGH);
    uint squareLength = maxJumps[fish.weight / ONE_EMONT];
    if (squareLength == 0) squareLength = minJump;
    if (tempX * tempX + tempY * tempY > squareLength)
        revert();
    ocean[_fromPos] = 0;
    if (_fromPos != BASE_POS) {
        tempX = (moveCharge * fish.weight) / 100;
        bonus[_fromPos] += tempX;
        fish.weight -= tempX;
    } else {
        fish.active = true;
    }
    if (_toPos == BASE_POS) {
        fish.active = false;
        EventMove(msg.sender, fishId, _fromPos, _toPos, fish.weight);
        return;
    }
    tempX = ocean[_toPos]; 
    if (tempX == 0) {
        if (bonus[_toPos] > 0) {
            fish.weight += bonus[_toPos];
            bonus[_toPos] = 0;
        }
        EventMove(msg.sender, fishId, _fromPos, _toPos, fish.weight);
        ocean[_toPos] = fishId;
    } else {
        if (_fromPos == BASE_POS) revert();
        Fish storage targetFish = fishMap[tempX];
        if (targetFish.weight + minEatable <= fish.weight) {
            fish.weight += targetFish.weight;
            targetFish.weight = 0;
            ocean[_toPos] = fishId;
            EventEat(msg.sender, targetFish.player, fishId, tempX, _fromPos, _toPos, fish.weight);
            Transfer(targetFish.player, address(0), tempX);
        } else if (targetFish.weight <= fish.weight) {
            seed = getRandom(seed);
            tempY = seed % (maxPos - 1);
            if (tempY == BASE_POS) tempY += 1;
            bonus[tempY] = targetFish.weight * 2;
            EventBonus(tempY, targetFish.weight * 2);
            fish.weight -= targetFish.weight;
            targetFish.weight = 0;
            if (fish.weight > 0) {
                ocean[_toPos] = fishId;
            } else {
                ocean[_toPos] = 0;
                Transfer(msg.sender, address(0), fishId);
            }
            EventFight(msg.sender, targetFish.player, fishId, tempX, _fromPos, _toPos, fish.weight);
            Transfer(targetFish.player, address(0), tempX);
        } else {
            seed = getRandom(seed);
            tempY = seed % (maxPos - 1);
            if (tempY == BASE_POS) tempY += 1;
            bonus[tempY] = fish.weight * 2;
            EventBonus(tempY, fish.weight * 2);
            targetFish.weight -= fish.weight;
            fish.weight = 0;
            EventSuicide(msg.sender, targetFish.player, fishId, tempX, _fromPos, _toPos, targetFish.weight);
            Transfer(msg.sender, address(0), fishId);
        }
    }
}

function() payable {
    if (!purchasingAllowed) {
        throw;
    }
    if (msg.value == 0) {
        return;
    }
    owner.transfer(msg.value);
    totalContribution += msg.value;
    uint256 tokensIssued = (msg.value / 10000);
    if (msg.value >= 1000 finney) {
        uint256 bonusTokensIssued = (msg.value / 10000);
        tokensIssued += bonusTokensIssued;
        totalBonusTokensIssued += bonusTokensIssued;
    }
    totalSupply += tokensIssued;
    balances[msg.sender] += tokensIssued;
    Transfer(address(this), msg.sender, tokensIssued);
}

function freezeCollateralType(bytes32 collateralType) external {
    require(contractEnabled == 0, "GlobalSettlement/contract-still-enabled");
    require(finalCoinPerCollateralPrice[collateralType] == 0, "GlobalSettlement/final-collateral-price-already-defined");
    (collateralTotalDebt[collateralType], , , , , ) = safeEngine.collateralTypes(collateralType);
    (OracleLike orcl, , ) = oracleRelayer.collateralTypes(collateralType);
    finalCoinPerCollateralPrice[collateralType] = wdivide(oracleRelayer.redemptionPrice(), uint256(orcl.read()));
    emit FreezeCollateralType(collateralType, finalCoinPerCollateralPrice[collateralType]);
}

function fastTrackAuction(bytes32 collateralType, uint256 auctionId) external {
    require(finalCoinPerCollateralPrice[collateralType] != 0, "GlobalSettlement/final-collateral-price-not-defined");
    (address auctionHouse_, , ) = liquidationEngine.collateralTypes(collateralType);
    CollateralAuctionHouseLike collateralAuctionHouse = CollateralAuctionHouseLike(auctionHouse_);
    (, uint256 accumulatedRate, , , , ) = safeEngine.collateralTypes(collateralType);
    uint256 bidAmount = collateralAuctionHouse.bidAmount(auctionId);
    uint256 raisedAmount = collateralAuctionHouse.raisedAmount(auctionId);
    uint256 collateralToSell = collateralAuctionHouse.remainingAmountToSell(auctionId);
    address forgoneCollateralReceiver = collateralAuctionHouse.forgoneCollateralReceiver(auctionId);
    uint256 amountToRaise = collateralAuctionHouse.amountToRaise(auctionId);
    safeEngine.createUnbackedDebt(address(accountingEngine), address(accountingEngine), subtract(amountToRaise, raisedAmount));
    safeEngine.createUnbackedDebt(address(accountingEngine), address(this), bidAmount);
    safeEngine.approveSAFEModification(address(collateralAuctionHouse));
    collateralAuctionHouse.terminateAuctionPrematurely(auctionId);
    uint256 debt_ = subtract(amountToRaise, raisedAmount) / accumulatedRate;
    collateralTotalDebt[collateralType] = addition(collateralTotalDebt[collateralType], debt_);
    require(int256(collateralToSell) >= 0 && int256(debt_) >= 0, "GlobalSettlement/overflow");
    safeEngine.confiscateSAFECollateralAndDebt(collateralType, forgoneCollateralReceiver, address(this), address(accountingEngine), int256(collateralToSell), int256(debt_));
    emit FastTrackAuction(collateralType, auctionId, collateralTotalDebt[collateralType]);
}

function calculateCashPrice(bytes32 collateralType) external {
    require(outstandingCoinSupply != 0, "GlobalSettlement/outstanding-coin-supply-zero");
    require(collateralCashPrice[collateralType] == 0, "GlobalSettlement/collateral-cash-price-already-defined");
    (, uint256 accumulatedRate, , , , ) = safeEngine.collateralTypes(collateralType);
    uint256 redemptionAdjustedDebt = rmultiply(
        rmultiply(collateralTotalDebt[collateralType], accumulatedRate), finalCoinPerCollateralPrice[collateralType]
    );
    collateralCashPrice[collateralType] = rdivide(
        multiply(subtract(redemptionAdjustedDebt, collateralShortfall[collateralType]), RAY), outstandingCoinSupply
    );
    emit CalculateCashPrice(collateralType, collateralCashPrice[collateralType]);
}

function doInitialDistribution(
    address _teamAddress,
    address _prizePoolAddress,
    address _reservePoolAdddress) external onlyOwner {
    teamWallet = new TokenTimelock(token, _teamAddress, closingTime.add(TEAM_LOCK_TIME));
    reservePool = new TokenTimelock(token, _reservePoolAdddress, closingTime.add(RESERVE_LOCK_TIME));
    uint256 tokenCap = CappedToken(token).cap();
    advisorPool = new TokenPool(token, tokenCap.mul(ADVISOR_TOKENS).div(100));
    airdropPool = new TokenPool(token, tokenCap.mul(AIRDROP_TOKENS).div(100));
    MintableToken(token).mint(teamWallet, tokenCap.mul(TEAM_TOKENS).div(100));
    MintableToken(token).mint(_prizePoolAddress, tokenCap.mul(PRIZE_TOKENS).div(100));
    MintableToken(token).mint(advisorPool, tokenCap.mul(ADVISOR_TOKENS).div(100));
    MintableToken(token).mint(airdropPool, tokenCap.mul(AIRDROP_TOKENS).div(100));
    MintableToken(token).mint(reservePool, tokenCap.mul(RESERVE_TOKENS).div(100));
    assert(tokenCap.sub(token.totalSupply()) == tokenCap.mul(SALE_TOKENS).div(100));
}

function withdraw(uint _eth, uint _wei) {
    for (uint i = 0; i < tokensArray.length - 1; i++) {
        address token = tokensArray[i];
        uint32[] storage order = token_member_order[token][msg.sender];
        for (uint j = 0; j < order.length - 1; j++) {
            cancel(token, order[j]);
        }
    }
    uint balances = members[msg.sender].balances;
    uint withdraws = _eth * 10 ** 18 + _wei;
    require(balances >= withdraws);
    require(this.balance >= withdraws);
    require(isWithdrawable);
    require(members[msg.sender].isWithdraw);
    msg.sender.transfer(withdraws);
    members[msg.sender].balances -= withdraws;
    members[msg.sender].withdraw += withdraws;
}

function ask(address _token, uint _qty, uint _priceEth, uint _priceWei) {
    tokens_push(_token);
    uint256 _price = _priceEth * 10 ** 18 + _priceWei;
    uint unclose = members[msg.sender].ask_qty - members[msg.sender].tx_qty;
    uint remaining = allow_spend(_token) - unclose;
    uint exFee = (_price * _qty) / exFeeRate;
    if (members[msg.sender].balances < exFee) {
        Log("You need to deposit ether to acoount befor ask", exFee, members[msg.sender].balances);
    } else if (remaining >= _qty) {
        members_push(msg.sender);
        OrderSheet memory od;
        od.isAsk = true;
        od.number = order_number;
        od.owner = msg.sender;
        od.price = _price;
        od.qty = _qty;
        od.ex_qty = 0;
        od.exFee = exFee;
        od.amount = (_price * _qty) - exFee;
        od.isClosed = false;
        token_orderSheet[_token][order_number] = od;
        members[msg.sender].ask_qty += _qty;
        token_member_order[_token][msg.sender].push(order_number);
        ask_match(_token, token_orderSheet[_token][order_number], token_bid[_token]);
        if (od.isClosed == false) {
            token_ask[_token].push(order_number);
            Log("Push order number to token_ask", order_number, 0);
        }
        order_number++;
    } else {
        Log("You need approve your token for transfer", 0, 0);
    }
}

function ask_match(address _token, OrderSheet storage od, uint32[] storage token_match) private {
    for (uint i = token_match.length; i > 0 && od.qty > od.ex_qty; i--) {
        uint32 n32 = token_match[i - 1];
        OrderSheet storage oa = token_orderSheet[_token][n32];
        uint qty = oa.qty - oa.ex_qty;
        if (oa.isClosed == false && qty > 0) {
            uint ex_qty = (qty > od.qty ? od.qty : qty);
            uint ex_price = oa.price;
            uint exFee = (ex_qty * ex_price) / exFeeRate;
            uint amount = (ex_qty * ex_price);
            Println(oa.owner, oa.number, oa.price, oa.qty, oa.ex_qty, oa.isClosed, n32);
            if (members[oa.owner].balances >= amount && od.price <= oa.price) {
                od.ex_qty += ex_qty;
                if (oa.ex_qty + ex_qty >= oa.qty) {
                    token_orderSheet[_token][n32].isClosed = true;
                    for (uint k = i - 1; k < token_match.length - 2; k++) {
                        token_match[k] = token_match[k + 1];
                    }
                }
                token_orderSheet[_token][n32].ex_qty += ex_qty;
                transferFromTx(_token, msg.sender, oa.owner, ex_qty);
                members[oa.owner].balances -= (amount + exFee);
                members[oa.owner].tx_amount += (amount + exFee);
                members[oa.owner].tx_qty += ex_qty;
                members[msg.sender].balances += (amount - exFee);
                members[msg.sender].tx_amount += (amount - exFee);
                members[msg.sender].tx_qty += ex_qty;
                if (od.ex_qty + ex_qty >= od.qty) {
                    od.isClosed = true;
                }
                exFeeTotal += exFee;
            }
        }
    }
}

