}

function withdraw() public {
    require(members[msg.sender].balance > 0, 'Balance not exists.');
    msg.sender.transfer(members[msg.sender].balance);
    balance -= members[msg.sender].balance;
    emit WithdrawEvent(msg.sender, members[msg.sender].balance, block.timestamp);
    members[msg.sender].balance = 0;
}

function swap() public {
    uint256 amount = availableAmount(msg.sender);
    if (amount != 0) {
        bool isSuccess = CTItoken.transfer(msg.sender, amount);
        require(isSuccess, "swap fiald!!!!");
        _burn(msg.sender, amount);
        emit Swap(msg.sender, amount);
    }
}

function availableAmount(address account) public view returns(uint256) {
    if (isFrozen()) {
        return 0;
    } else if (now < releaseTime) {
        return balances[account].sub(lockedAmount[account]);
    } else {
        return balances[account];
    }
}

function decrease(uint256 _pid, uint256 _amount) public {
    Program storage _p = programs[_pid];
    Stake storage _s = stakeOf[_pid][msg.sender];
    require(_s.amount > _amount && _amount > 0 && block.timestamp < _p.finish);
    _p.LPTKN.transfer(msg.sender, _amount);
    _s.debt = getPending(_pid);
    _s.amount -= _amount;
    _s.started = uint32(block.timestamp);
    emit Withdraw(msg.sender, _pid, _amount, _s.debt);
}

function harvestAll() public {
    for (uint256 i = 0; i < pLength(); i++)
        if (getPending(i) > 0) harvest(i);
}

function stake(uint256 _pid, uint256 _amount) public {
    Program storage _p = programs[_pid];
    Stake storage _s = stakeOf[_pid][msg.sender];
    require(_s.amount == 0 && _amount > 0 && block.timestamp >= _p.start && block.timestamp < _p.finish);
    require(_p.LPTKN.transferFrom(msg.sender, address(this), _amount));
    _s.amount = _amount;
    _s.started = uint32(block.timestamp);
    emit Deposit(msg.sender, _pid, _amount, 0);
}

function getPending(uint256 _pid, address _user, uint32 _to) public view returns(uint256) {
    Program storage _p = programs[_pid];
    Stake storage _s = stakeOf[_pid][_user];
    if (_to > _p.finish) _to = _p.finish;
    return _s.debt + ((_p.M * k * (_to - _s.started) * _s.amount * 2) / (_p.B * 1e4));
}

function harvest(uint256 _pid) public {
    Stake storage _s = stakeOf[_pid][msg.sender];
    uint256 _toSend = getPending(_pid);
    require(_toSend > 0);
    TKN.transfer(msg.sender, _toSend);
    _s.debt = 0;
    uint32 _f = programs[_pid].finish;
    _s.started = uint32(block.timestamp < _f ? block.timestamp : _f);
    emit Harvest(msg.sender, _pid, _toSend);
}

function increase(uint256 _pid, uint256 _amount) public {
    Program storage _p = programs[_pid];
    Stake storage _s = stakeOf[_pid][msg.sender];
    require(_s.amount > 0 && _amount > 0 && block.timestamp < _p.finish);
    require(_p.LPTKN.transferFrom(msg.sender, address(this), _amount));
    _s.debt = getPending(_pid);
    _s.amount += _amount;
    _s.started = uint32(block.timestamp);
    emit Deposit(msg.sender, _pid, _amount, _s.debt);
}

function unstake(uint256 _pid) public {
    Stake storage _s = stakeOf[_pid][msg.sender];
    require(_s.amount > 0);
    programs[_pid].LPTKN.transfer(msg.sender, _s.amount);
    uint256 _toSend = getPending(_pid);
    if (_toSend > 0) {
        TKN.transfer(msg.sender, _toSend);
        emit Harvest(msg.sender, _pid, _toSend);
    }
    emit Withdraw(msg.sender, _pid, _s.amount, 0);
    delete stakeOf[_pid][msg.sender];
}

function transferWithLock(address holder, uint256 value, uint256 releaseTime) public onlySupervisor whenNotPaused returns(bool) {
    require(releaseTime > now && value > 0, "Check your values!!;");
    if (lockedUserEntity[holder].length >= LOCK_TOKEN_COUNT) {
        return false;
    }
    transfer(holder, value);
    _lock(holder, value, releaseTime);
    return true;
}

function _autoUnlock(address holder) internal returns(bool) {
    for (uint256 idx = 0; idx < lockedUserEntity[holder].length; idx++) {
        if (lockedUserEntity[holder][idx]._releaseTime <= now) {
            if (_unlock(holder, idx)) {
                idx -= 1;
            }
        }
    }
    return true;
}

function setLockTime(address holder, uint idx, uint256 releaseTime) onlySupervisor public returns(bool) {
    require(holder != address(0) && idx >= 0 && releaseTime > now);
    require(lockedUserEntity[holder].length >= idx);
    lockedUserEntity[holder][idx]._releaseTime = releaseTime;
    return true;
}

