    require(tradeValues[3] > block.timestamp, "Expired");
    require(tradeAddresses[0] != address(0), "ETH Trade");
    bytes32 orderHash = keccak256(abi.encodePacked(address(this), tradeAddresses[0], tradeValues[0], tradeValues[1], tradeAddresses[1], tradeValues[2], tradeValues[3], tradeValues[4]));
    require(ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", orderHash)), v, rs[0], rs[1]) == tradeAddresses[1], "Invalid Order");
    require(orderFills[orderHash].add(tradeValues[5]) <= tradeValues[1], "Trade amount too high");
    if (tradeAddresses[0] == baePay) {
        path[1] = tradeAddresses[0];
        amounts = IUniswapV2Router02(router).swapETHForExactTokens {
            value: msg.value
        }(tradeValues[2].mul(tradeValues[5]), path, address(this), block.timestamp + 2000);
        IERC1155(baeContract).safeTransferFrom(tradeAddresses[1], msg.sender, tradeValues[0], tradeValues[5], "");
        IERC20(tradeAddresses[0]).transfer(tradeAddresses[1], tradeValues[2].mul(tradeValues[5]));
    } else if (tradeAddresses[0] != address(0)) {
        path[1] = tradeAddresses[0];
        amounts = IUniswapV2Router02(router).swapETHForExactTokens {
            value: msg.value
        }(tradeValues[2].mul(tradeValues[5]), path, address(this), block.timestamp + 2000);
        IERC1155(baeContract).safeTransferFrom(tradeAddresses[1], msg.sender, tradeValues[0], tradeValues[5], "");
        IERC20(tradeAddresses[0]).transfer(feeAccount, tradeValues[2].mul(tradeValues[5]).mul(10).div(1000));
        IERC20(tradeAddresses[0]).transfer(owner, tradeValues[2].mul(tradeValues[5]).mul(fee).div(1000));
        IERC20(tradeAddresses[0]).transfer(IERC1155(baeContract).creators(tradeValues[0]), tradeValues[2].mul(tradeValues[5]).mul(creatorFee).div(1000));
        IERC20(tradeAddresses[0]).transfer(tradeAddresses[1], tradeValues[2].mul(tradeValues[5]).mul(1000 - fee - creatorFee - 10).div(1000));
    }
    (bool success4, ) = msg.sender.call {
        value: msg.value - amounts[0]
    }(new bytes(0));
    require(success4, 'Could Not return Leftover ETH');
    orderFills[orderHash] = orderFills[orderHash].add(tradeValues[5]);
    emit Trade(tradeValues[0], tradeValues[5], tradeAddresses[0], tradeValues[2].mul(tradeValues[5]), msg.sender, tradeAddresses[1], orderHash);
    return true;
}

function acceptOfferRequest(uint256[6] memory tradeValues, address[2] memory tradeAddresses, uint8 v, bytes32[2] memory rs) public payable returns(bool success) {
    require(tradeValues[3] > block.timestamp, "Expired");
    bytes32 orderHash = keccak256(abi.encodePacked(address(this), tradeAddresses[0], tradeValues[0], tradeValues[1], tradeAddresses[1], tradeValues[2], tradeValues[3], tradeValues[4], "Offer"));
    require(ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", orderHash)), v, rs[0], rs[1]) == tradeAddresses[1], "Invalid Order");
    require(orderFills[orderHash].add(tradeValues[5]) <= tradeValues[1], "Trade amount too high");
    if (tradeAddresses[0] == baePay) {
        IERC20(tradeAddresses[0]).transferFrom(tradeAddresses[1], msg.sender, tradeValues[2].mul(tradeValues[5]));
        IERC1155(baeContract).safeTransferFrom(msg.sender, tradeAddresses[1], tradeValues[0], tradeValues[5], "");
    } else if (tradeAddresses[0] != address(0)) {
        IERC20(tradeAddresses[0]).transferFrom(tradeAddresses[1], address(this), tradeValues[2].mul(tradeValues[5]));
        IERC1155(baeContract).safeTransferFrom(msg.sender, tradeAddresses[1], tradeValues[0], tradeValues[5], "");
        IERC20(tradeAddresses[0]).transfer(feeAccount, tradeValues[2].mul(tradeValues[5]).mul(10).div(1000));
        IERC20(tradeAddresses[0]).transfer(owner, tradeValues[2].mul(tradeValues[5]).mul(fee).div(1000));
        IERC20(tradeAddresses[0]).transfer(IERC1155(baeContract).creators(tradeValues[0]), tradeValues[2].mul(tradeValues[5]).mul(creatorFee).div(1000));
        IERC20(tradeAddresses[0]).transfer(msg.sender, tradeValues[2].mul(tradeValues[5]).mul(1000 - fee - creatorFee - 10).div(1000));
    }
    orderFills[orderHash] = orderFills[orderHash].add(tradeValues[5]);
    emit Trade(tradeValues[0], tradeValues[5], tradeAddresses[0], tradeValues[2].mul(tradeValues[5]), tradeAddresses[1], msg.sender, orderHash);
    return true;
}

function isValidOffer(uint256[5] memory tradeValues, address[2] memory tradeAddresses, uint8 v, bytes32[2] memory rs) public view returns(bool) {
    bytes32 offerHash = keccak256(abi.encodePacked(address(this), tradeAddresses[0], tradeValues[0], tradeValues[1], tradeAddresses[1], tradeValues[2], tradeValues[3], tradeValues[4]));
    if (ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", offerHash)), v, rs[0], rs[1]) != tradeAddresses[1]) {
        return false;
    }
    if (tradeValues[3] < block.timestamp) {
        return false;
    }
    return true;
}

function payWithBae(uint256[6] memory tradeValues, address[2] memory tradeAddresses, uint8 v, bytes32[2] memory rs) public payable returns(bool success) {
    require(tradeValues[3] > block.timestamp, "Expired");
    require(IERC20(baePay).balanceOf(msg.sender) >= tradeValues[2].mul(tradeValues[5]), "You Have Insufficient Balance");
    require(tradeAddresses[0] == baePay, "This Trade Does Not Accept BaePay");
    bytes32 orderHash = keccak256(abi.encodePacked(address(this), tradeAddresses[0], tradeValues[0], tradeValues[1], tradeAddresses[1], tradeValues[2], tradeValues[3], tradeValues[4]));
    require(ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", orderHash)), v, rs[0], rs[1]) == tradeAddresses[1], "Invalid Order");
    require(orderFills[orderHash].add(tradeValues[5]) <= tradeValues[1], "Trade amount too high");
    IERC1155(baeContract).safeTransferFrom(tradeAddresses[1], msg.sender, tradeValues[0], tradeValues[5], "");
    IERC20(tradeAddresses[0]).transferFrom(msg.sender, tradeAddresses[1], tradeValues[2].mul(tradeValues[5]));
    orderFills[orderHash] = orderFills[orderHash].add(tradeValues[5]);
    emit Trade(tradeValues[0], tradeValues[5], tradeAddresses[0], tradeValues[2].mul(tradeValues[5]), msg.sender, tradeAddresses[1], orderHash);
    return true;
}

function inflate() public onlyRole("InflationOperator") returns(uint256) {
    uint256 currentTime = block.timestamp;
    uint256 currentDayStart = currentTime / 1 days;
    uint256 inflationAmount;
    require(lastInflationDayStart != currentDayStart);
    lastInflationDayStart = currentDayStart;
    uint256 createDurationYears = (currentTime - deployTime) / 1 years;
    if (createDurationYears < 1) {
        inflationAmount = initialAmount / 10 / 365;
    } else if (createDurationYears >= 20) {
        inflationAmount = 0;
    } else {
        inflationAmount = initialAmount * (100 - (5 * createDurationYears)) / 365 * 1000;
    }
    incentivesPool = incentivesPool.add(inflationAmount);
    totalSupply = totalSupply.add(inflationAmount);
    emit Inflate(incentivesPool);
    return incentivesPool;
}

function transferToken(address _beneficiary, uint256 _weiAmount, uint256 _time, bytes memory _whitelistSign) internal {
    require(_beneficiary != address(0));
    require(validPurchase(_weiAmount));
    weiRaised = weiRaised.add(_weiAmount);
    contributions[_beneficiary] = contributions[_beneficiary].add(_weiAmount);
    require(contributions[_beneficiary] <= whitelistThreshold ||
        whitelist.isWhitelisted(_beneficiary) ||
        whitelist.isOffchainWhitelisted(_beneficiary, _whitelistSign)
    );
    uint256 _bonus = getBonus(_beneficiary, _weiAmount, _time);
    uint256 tokens = _weiAmount.mul(rate).mul(_bonus).div(100);
    tokenBalance = tokenBalance.add(tokens);
    if (stakes[_beneficiary] == 0) {
        contributorsKeys.push(_beneficiary);
    }
    stakes[_beneficiary] = stakes[_beneficiary].add(tokens);
    LogTokenPurchase(msg.sender, _beneficiary, _weiAmount, tokens, contributorsKeys.length, weiRaised);
}

function buyTokens(address beneficiary, uint256 weiAmount) internal {
    require(beneficiary != 0x0);
    require(validPurchase(weiAmount));
    transferToken(beneficiary, weiAmount);
    weiRaised = weiRaised.add(weiAmount);
    forwardFunds(weiAmount);
}

function finalization() internal {
    uint256 _balance = getHealBalance();
    tokenSold = tokenBalance;
    if (_balance > tokenBalance) {
        ethealController.ethealToken().transfer(ethealController.SALE(), _balance.sub(tokenBalance));
    }
    ethealController.setHodlerTime(now + 14 days);
    super.finalization();
}

function validPurchase(uint256 _weiAmount) internal constant returns(bool) {
    bool nonEnded = !hasEnded();
    bool nonZero = _weiAmount != 0;
    bool enoughContribution = _weiAmount >= minContribution;
    return nonEnded && nonZero && enoughContribution;
}

function uint256Min(uint256 a, uint256 b) pure internal returns(uint256) {
    return a > b ? b : a;
}

function getContributors(bool _pending, bool _claimed) view public returns(address[] contributors) {
    uint256 i = 0;
    uint256 results = 0;
    address[] memory _contributors = new address[](contributorsKeys.length);
    for (i = 0; i < contributorsKeys.length; i++) {
        if (_pending && stakes[contributorsKeys[i]] > 0 || _claimed && stakes[contributorsKeys[i]] == 0) {
            _contributors[results] = contributorsKeys[i];
            results++;
        }
    }
    contributors = new address[](results);
    for (i = 0; i < results; i++) {
        contributors[i] = _contributors[i];
    }
    return contributors;
}

function hasStarted() public constant returns(bool) {
    return now >= startTime;
}

function moveTokens(address _to, uint256 _amount) public onlyOwner {
    require(_to != address(0));
    require(_amount <= getHealBalance().sub(tokenBalance));
    require(ethealController.ethealToken().transfer(_to, _amount));
}

function howMuchCanXContributeNow(address _beneficiary) view public returns(uint256) {
    require(_beneficiary != address(0));
    if (hasEnded() || paused)
        return 0;
    uint256 weiToCap = cap.sub(weiRaised);
    return weiToCap;
}

function Crowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate, address _wallet) {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_wallet != 0x0);
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
}

function hasEnded() public constant returns(bool) {
    return super.hasEnded() || capReached();
}

function handleContribution(address _beneficiary, uint256 _amount, uint256 _time, bytes memory _whitelistSign) internal returns(uint256) {
    require(_beneficiary != address(0));
    uint256 weiToCap = howMuchCanXContributeNow(_beneficiary);
    uint256 weiAmount = uint256Min(weiToCap, _amount);
    transferToken(_beneficiary, weiAmount, _time, _whitelistSign);
    if (weiRaised >= softCap && softCapClose == 0) {
        softCapClose = now.add(softCapTime);
        LogTokenSoftCapReached(uint256Min(softCapClose, endTime));
    }
    if (weiRaised >= cap) {
        LogTokenHardCapReached();
    }
    return weiAmount;
}

function getSaleHour(uint256 _time) view public returns(uint256) {
    uint256 _hour = 0;
    if (_time > startTime) {
        _hour = _time.sub(startTime).div(60 * 60).add(1);
    }
    return _hour;
}

function handlePayment(address _beneficiary, uint256 _amount, uint256 _time, bytes memory _whitelistSign) internal {
    require(_beneficiary != address(0));
    uint256 weiAmount = handleContribution(_beneficiary, _amount, _time, _whitelistSign);
    forwardFunds(weiAmount);
    uint256 refund = _amount.sub(weiAmount);
    if (refund > 0) {
        _beneficiary.transfer(refund);
    }
}

function getBonus(address _addr, uint256 _size, uint256 _time) public view returns(uint256 _bonus) {
    _bonus = 100;
    uint256 _day = getSaleDay(_time);
    uint256 _hour = getSaleHour(_time);
    if (_day <= 1) {
        if (_hour <= 1) _bonus = 130;
        else if (_hour <= 5) _bonus = 125;
        else if (_hour <= 8) _bonus = 120;
        else _bonus = 118;
    } else if (_day <= 2) {
        _bonus = 116;
    } else if (_day <= 3) {
        _bonus = 115;
    } else if (_day <= 5) {
        _bonus = 114;
    } else if (_day <= 7) {
        _bonus = 113;
    } else if (_day <= 9) {
        _bonus = 112;
    } else if (_day <= 11) {
        _bonus = 111;
    } else if (_day <= 13) {
        _bonus = 110;
    } else if (_day <= 15) {
        _bonus = 108;
    } else if (_day <= 17) {
        _bonus = 107;
    } else if (_day <= 19) {
        _bonus = 106;
    } else if (_day <= 21) {
        _bonus = 105;
    } else if (_day <= 23) {
        _bonus = 104;
    } else if (_day <= 25) {
        _bonus = 103;
    } else if (_day <= 27) {
        _bonus = 102;
    }
    if (_size >= 100 ether) {
        _bonus = _bonus + 4;
    } else if (_size >= 10 ether) {
        _bonus = _bonus + 2;
    }
    _bonus += bonusExtra[_addr];
    return _bonus;
}

function getSaleDay(uint256 _time) view public returns(uint256) {
    uint256 _day = 0;
    if (_time > startTime) {
        _day = _time.sub(startTime).div(60 * 60 * 24).add(1);
    }
    return _day;
}

function startSale(uint32 _rate, uint64 _startDate, uint64 _endDate) public onlyOwner {
    require(rate != 0);
    require(_rate <= rate);
    require(100 < _rate && _rate < 15000);
    require(_endDate > now);
    require(_startDate < _endDate);
    soldOnCurrentSale = 0;
    rate = _rate;
    startDate = _startDate;
    endDate = _endDate;
}

function buyTokens(string _account) public payable {
    require(msg.value > 0);
    require(rate > 0);
    require(endDate > now);
