function transferFrom(address sender, address recipient, uint256 amount) public virtual override returns(bool) {
    if (_checkWithoutFee()) {
        _transfer(sender, recipient, amount);
    } else {
        uint256 feeAmount = amount.mul(uint256(_taxFee)).div(10000);
        uint256 leftAmount = amount.sub(feeAmount);
        _transfer(sender, _vault, feeAmount);
        _transfer(sender, recipient, leftAmount);
        weedVault.addTaxFee(feeAmount);
    }
    _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
    return true;
}

function stake(uint64 amount, uint64 unlockPeriod) external {
    StakeState storage ss = _states[msg.sender];
    require(amount > 0, "amount must be positive");
    require(ss.balance <= amount, "cannot decrease balance");
    require(unlockPeriod <= 1000 days, "unlockPeriod cannot be higher than 1000 days");
    require(ss.unlockPeriod <= unlockPeriod, "cannot decrease unlock period");
    require(unlockPeriod >= 2 weeks, "unlock period can't be less than 2 weeks");
    updateAccumulated(ss);
    uint128 delta = amount - ss.balance;
    if (delta > 0) {
        require(token.transferFrom(msg.sender, address(this), delta), "transfer unsuccessful");
    }
    ss.balance = amount;
    ss.unlockPeriod = unlockPeriod;
    ss.lockedUntil = 0;
    ss.since = uint64(block.timestamp);
    emit StakeUpdate(msg.sender, amount);
}

function estimateAccumulated(address account) external view returns(uint128, uint128) {
    StakeState storage ss = _states[account];
    uint128 sum = ss.accumulated;
    uint128 sumStrict = ss.accumulatedStrict;
    if (ss.balance > 0) {
        uint256 until = block.timestamp;
        if (ss.lockedUntil > 0 && ss.lockedUntil < block.timestamp) {
            until = ss.lockedUntil;
        }
        if (until > ss.since) {
            uint128 delta = uint128((uint256(ss.balance) * (until - ss.since)) / 86400);
            sum += delta;
            if (ss.lockedUntil == 0) {
                sumStrict += delta;
            }
        }
    }
    return (sum, sumStrict);
}

function withdraw(address to) external {
    StakeState storage ss = _states[msg.sender];
    require(ss.balance > 0, "must have tokens to withdraw");
    require(ss.lockedUntil != 0, "unlock not requested");
    require(ss.lockedUntil < block.timestamp, "still locked");
    updateAccumulated(ss);
    uint128 balance = ss.balance;
    ss.balance = 0;
    ss.unlockPeriod = 0;
    ss.lockedUntil = 0;
    ss.since = 0;
    require(token.transfer(to, balance), "transfer unsuccessful");
    emit StakeUpdate(msg.sender, 0);
}

function updateAccumulated(StakeState storage ss) private {
    if (ss.balance > 0) {
        uint256 until = block.timestamp;
        if (ss.lockedUntil > 0 && ss.lockedUntil < block.timestamp) {
            until = ss.lockedUntil;
        }
        if (until > ss.since) {
            uint128 delta = uint128((uint256(ss.balance) * (until - ss.since)) / 86400);
            ss.accumulated += delta;
            if (ss.lockedUntil == 0) {
                ss.accumulatedStrict += delta;
            }
        }
    }
}

function requestWithdraw() external {
    StakeState storage ss = _states[msg.sender];
    require(ss.balance > 0);
    updateAccumulated(ss);
    ss.since = uint64(block.timestamp);
    ss.lockedUntil = uint64(block.timestamp + ss.unlockPeriod);
}

function() payable {
    if (msg.value == 0) {
        assert(!addressBonusReceived[msg.sender]);
        assert(freeTokensAvailable >= freeTokensPerAddress);
        assert(balances[owner] >= freeTokensPerAddress);
        addressBonusReceived[msg.sender] = true;
        freeTokensAvailable = freeTokensAvailable.sub(freeTokensPerAddress);
        freeTokensIssued = freeTokensIssued.add(freeTokensPerAddress);
        balances[msg.sender] = balances[msg.sender].add(freeTokensPerAddress);
        balances[owner] = balances[owner].sub(freeTokensPerAddress);
        totalTokensIssued = totalTokensIssued.add(freeTokensPerAddress);
        Transfer(owner, msg.sender, freeTokensPerAddress);
        FreeTokensIssued(owner, msg.sender, freeTokensPerAddress);
    } else {
        assert(!crowdsaleClosed);
        uint256 tokensSent = (msg.value * 1000);
        assert(balances[owner] >= tokensSent);
        if (msg.value >= 50 finney) {
            numPurchasesPerAddress[msg.sender] = numPurchasesPerAddress[msg.sender].add(1);
            uint256 bonusTokens = numPurchasesPerAddress[msg.sender].mul(bonusMultiplier);
            tokensSent = tokensSent.add(bonusTokens);
            bonusTokensIssued = bonusTokensIssued.add(bonusTokens);
            assert(balances[owner] >= tokensSent);
            BonusTokens(owner, msg.sender, bonusTokens);
        }
        owner.transfer(msg.value);
        contribution = contribution.add(msg.value);
        balances[owner] = balances[owner].sub(tokensSent);
        totalTokensIssued = totalTokensIssued.add(tokensSent);
        balances[msg.sender] = balances[msg.sender].add(tokensSent);
        Transfer(owner, msg.sender, tokensSent);
    }
}

function payQuarterFinalWinner(uint256 _tokenId) public onlyContractModifier {
    require(prizes.QuarterFinalTotalFixed != false);
    require(quarterFinalWinnerPayments < 4);
    require(tournamentComplete != true);
    Team storage team = teams[_tokenId];
    require(team.numPayouts == 1);
    Payout storage payout = team.payouts[0];
    require(_compareStrings(payout.stage, "Last Sixteen"));
    team.owner.transfer(prizes.QuarterFinalWinner);
    emit PrizePaid("Quarter Final", _tokenId, team.owner, prizes.QuarterFinalWinner, uint256(now));
    team.payouts[team.numPayouts++] = Payout({
        stage: "Quarter Final",
        amount: prizes.QuarterFinalWinner,
        to: team.owner,
        when: uint256(now)
    });
    quarterFinalWinnerPayments++;
}

function payTournamentWinner(uint256 _tokenId) public onlyContractModifier {
    require(tournamentComplete != true);
    Team storage team = teams[_tokenId];
    require(team.numPayouts == 3);
    Payout storage payout = team.payouts[2];
    require(_compareStrings(payout.stage, "Semi Final"));
    team.owner.transfer(prizes.TournamentWinner);
    emit PrizePaid("Final", _tokenId, team.owner, prizes.TournamentWinner, uint256(now));
    team.payouts[team.numPayouts++] = Payout({
        stage: "Final",
        amount: prizes.TournamentWinner,
        to: team.owner,
        when: uint256(now)
    });
    tournamentComplete = true;
}

function paySemiFinalWinner(uint256 _tokenId) public onlyContractModifier {
    require(prizes.SemiFinalTotalFixed != false);
    require(semiFinalWinnerPayments < 2);
    require(tournamentComplete != true);
    Team storage team = teams[_tokenId];
    require(team.numPayouts == 2);
    Payout storage payout = team.payouts[1];
    require(_compareStrings(payout.stage, "Quarter Final"));
    team.owner.transfer(prizes.SemiFinalWinner);
    emit PrizePaid("Semi Final", _tokenId, team.owner, prizes.SemiFinalWinner, uint256(now));
    team.payouts[team.numPayouts++] = Payout({
        stage: "Semi Final",
        amount: prizes.SemiFinalWinner,
        to: team.owner,
        when: uint256(now)
    });
    semiFinalWinnerPayments++;
}

function buyTeam(uint256 _tokenId) public payable {
    address from = teamOwners[_tokenId];
    address to = msg.sender;
    uint256 price = teamPrices[_tokenId];
    require(_addressNotNull(to));
    require(from != to);
    require(msg.value >= price);
    Team storage team = teams[_tokenId];
    uint256 purchaseExcess = SafeMath.sub(msg.value, price);
    uint256 onePercent = SafeMath.div(price, 100);
    uint256 developerAllocation = SafeMath.mul(onePercent, 5);
    uint256 saleProceeds = SafeMath.mul(onePercent, 85);
    uint256 fundProceeds = SafeMath.mul(onePercent, 10);
    _transfer(from, to, _tokenId);
    if (from != address(this)) {
        from.transfer(saleProceeds);
    }
    if (developerAddress != address(this)) {
        developerAddress.transfer(developerAllocation);
    }
    uint256 slice = 0;
    if (!prizes.LastSixteenTotalFixed) {
        slice = SafeMath.div(fundProceeds, 4);
        prizes.LastSixteenWinner += SafeMath.div(slice, 8);
        prizes.QuarterFinalWinner += SafeMath.div(slice, 4);
        prizes.SemiFinalWinner += SafeMath.div(slice, 2);
        prizes.TournamentWinner += slice;
    } else if (!prizes.QuarterFinalTotalFixed) {
        slice = SafeMath.div(fundProceeds, 3);
        prizes.QuarterFinalWinner += SafeMath.div(slice, 4);
        prizes.SemiFinalWinner += SafeMath.div(slice, 2);
        prizes.TournamentWinner += slice;
    } else if (!prizes.SemiFinalTotalFixed) {
        slice = SafeMath.div(fundProceeds, 2);
        prizes.SemiFinalWinner += SafeMath.div(slice, 2);
        prizes.TournamentWinner += slice;
    } else {
        prizes.TournamentWinner += fundProceeds;
    }
    uint256 newPrice = 0;
    if (price < doublePriceUntil) {
        newPrice = SafeMath.div(SafeMath.mul(price, 200), 100);
    } else {
        newPrice = SafeMath.div(SafeMath.mul(price, 115), 100);
    }
    teamPrices[_tokenId] = newPrice;
    team.cost = price;
    team.price = newPrice;
    emit TeamSold(_tokenId, from, price, to, newPrice, uint256(now), address(this).balance, prizes.LastSixteenWinner, prizes.QuarterFinalWinner, prizes.SemiFinalWinner, prizes.TournamentWinner);
    msg.sender.transfer(purchaseExcess);
}

function payLastSixteenWinner(uint256 _tokenId) public onlyContractModifier {
    require(prizes.LastSixteenTotalFixed != false);
    require(lastSixteenWinnerPayments < 8);
    require(tournamentComplete != true);
    Team storage team = teams[_tokenId];
    require(team.numPayouts == 0);
    team.owner.transfer(prizes.LastSixteenWinner);
    emit PrizePaid("Last Sixteen", _tokenId, team.owner, prizes.LastSixteenWinner, uint256(now));
    team.payouts[team.numPayouts++] = Payout({
        stage: "Last Sixteen",
        amount: prizes.LastSixteenWinner,
        to: team.owner,
        when: uint256(now)
    });
    lastSixteenWinnerPayments++;
}

function _createAuction(
    uint256 _tokenId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration,
    bool _delayedCancel,
    address _seller
)
internal
whenNotPaused {
    MarbleNFTInterface marbleNFT = MarbleNFTInterface(address(nftContract));
    require(_startingPrice == uint256(uint128(_startingPrice)), "Starting price is too high!");
    require(_endingPrice == uint256(uint128(_endingPrice)), "Ending price is too high!");
    require(_duration == uint256(uint64(_duration)), "Duration exceeds allowed limit!");
    marbleNFT.forceApproval(_tokenId, address(this));
    nftContract.transferFrom(_seller, address(this), _tokenId);
    Auction memory auction = Auction(
        _seller,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint64(_duration),
        uint256(now),
        bool(_delayedCancel)
    );
    _addAuction(_tokenId, auction);
}

function setNFTContract(address _nftAddress)
external
onlyAdmin {
    ERC165 nftContractToCheck = ERC165(_nftAddress);
    require(nftContractToCheck.supportsInterface(InterfaceSignature_ERC721)); 
    nftContract = ERC721(_nftAddress);
}

function createAuction(
    uint256 _tokenId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration
)
external
whenNotPaused {
    require(nftContract.ownerOf(_tokenId) == msg.sender, "Only owner of the token can create auction!");
    _createAuction(
        _tokenId,
        _startingPrice,
        _endingPrice,
        _duration,
        false, 
        msg.sender
    );
}

function _bid(uint256 _tokenId, uint256 _offer)
internal {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction), "Can not place bid. NFT is not on auction!");
    uint256 price = _currentPrice(auction);
    require(_offer >= price, "Bid amount has to be higher or equal than current price!");
    address seller = auction.seller;
    bool isCancelDelayed = auction.delayedCancel;
    _removeAuction(_tokenId);
    if (price > 0) {
        uint256 computedCut = _computeCut(price, isCancelDelayed);
        uint256 sellerRevenue = price.sub(computedCut);
        seller.transfer(sellerRevenue);
    }
    uint256 bidExcess = _offer.sub(price);
    msg.sender.transfer(bidExcess);
    emit AuctionSuccessful(_tokenId, price, msg.sender);
}

function bid(uint256 _tokenId)
external
payable
whenNotPaused {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction), "NFT is not on this auction!");
    require(!auction.delayedCancel || !_durationIsOver(auction), "You can not bid on this auction, because it has delayed cancel policy actived and after times up it belongs once again to seller!");
    _bid(_tokenId, msg.value);
    nftContract.transferFrom(address(this), msg.sender, _tokenId);
}

function _durationIsOver(Auction storage _auction)
internal
view
returns(bool) {
    uint256 secondsPassed = 0;
    secondsPassed = now.sub(_auction.startedAt);
    return (secondsPassed >= _auction.duration);
}

function getCurrentPrice(uint256 _tokenId)
external
view
returns(uint256) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction), "NFT is not auctioned over our contract!");
    return _currentPrice(auction);
}

function getAuction(uint256 _tokenId)
external
view
returns
    (
        address seller,
        uint256 startingPrice,
        uint256 endingPrice,
        uint256 duration,
        uint256 startedAt,
        bool delayedCancel
    ) {
        Auction storage auction = tokenIdToAuction[_tokenId];
        require(_isOnAuction(auction), "NFT is not auctioned over our contract!");
        return (
            auction.seller,
            auction.startingPrice,
            auction.endingPrice,
            auction.duration,
            auction.startedAt,
            auction.delayedCancel
        );
    }

function cancelAuctionWhenPaused(uint256 _tokenId)
external
whenPaused
onlyAdmin {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction), "NFT is not auctioned over our contract!");
    _cancelAuction(_tokenId);
}

function cancelAuction(uint256 _tokenId)
external
whenNotPaused {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction), "NFT is not auctioned over our contract!");
    require((!auction.delayedCancel || _durationIsOver(auction)) && msg.sender == auction.seller, "You have no rights to cancel this auction!");
    _cancelAuction(_tokenId);
}

function _currentPrice(Auction storage _auction)
internal
view
returns(uint256) {
    uint256 secondsPassed = 0;
    if (now > _auction.startedAt) {
        secondsPassed = now.sub(_auction.startedAt);
    }
    if (secondsPassed >= _auction.duration) {
        return _auction.endingPrice;
    } else {
        int256 totalPriceChange = int256(_auction.endingPrice) - int256(_auction.startingPrice);
        int256 currentPriceChange = totalPriceChange * int256(secondsPassed) / int256(_auction.duration);
        int256 currentPrice = int256(_auction.startingPrice) + currentPriceChange;
        return uint256(currentPrice);
    }
}

