    if (now >= start.add(duration) || revoked[token]) {
        return totalBalance;
    }
    return totalBalance.mul(now.sub(start).div(divider).mul(divider)).div(duration);
}

function atomicMatch(Order memory buy, Sig memory buySig, Order memory sell, Sig memory sellSig, bytes32 metadata)
internal
reentrancyGuard {
    bytes32 buyHash;
    if (buy.maker == msg.sender) {
        require(validateOrderParameters(buy));
    } else {
        buyHash = _requireValidOrderWithNonce(buy, buySig);
    }
    bytes32 sellHash;
    if (sell.maker == msg.sender) {
        require(validateOrderParameters(sell));
    } else {
        sellHash = _requireValidOrderWithNonce(sell, sellSig);
    }
    require(ordersCanMatch(buy, sell));
    uint size;
    address target = sell.target;
    assembly {
        size: = extcodesize(target)
    }
    require(size > 0);
    if (buy.replacementPattern.length > 0) {
        ArrayUtils.guardedArrayReplace(buy.calldata, sell.calldata, buy.replacementPattern);
    }
    if (sell.replacementPattern.length > 0) {
        ArrayUtils.guardedArrayReplace(sell.calldata, buy.calldata, sell.replacementPattern);
    }
    require(ArrayUtils.arrayEq(buy.calldata, sell.calldata));
    OwnableDelegateProxy delegateProxy = registry.proxies(sell.maker);
    require(delegateProxy != address(0));
    AuthenticatedProxy proxy = AuthenticatedProxy(delegateProxy);
    if (msg.sender != buy.maker) {
        cancelledOrFinalized[buyHash] = true;
    }
    if (msg.sender != sell.maker) {
        cancelledOrFinalized[sellHash] = true;
    }
    uint price = executeFundsTransfer(buy, sell);
    require(delegateProxy.implementation() == registry.delegateProxyImplementation());
    require(proxy.proxy(sell.target, sell.howToCall, sell.calldata));
    if (buy.staticTarget != address(0)) {
        require(staticCall(buy.staticTarget, sell.calldata, buy.staticExtradata));
    }
    if (sell.staticTarget != address(0)) {
        require(staticCall(sell.staticTarget, sell.calldata, sell.staticExtradata));
    }
    emit OrdersMatched(buyHash, sellHash, sell.feeRecipient != address(0) ? sell.maker : buy.maker, sell.feeRecipient != address(0) ? buy.maker : sell.maker, price, metadata);
}

function addLiquidity(
    ILiquidityPoolConverter _converter,
    IERC20Token _reserveToken1,
    IERC20Token _reserveToken2,
    uint256 _reserveAmount1,
    uint256 _reserveAmount2,
    uint256 _value
) internal {
    updatingLiquidity = true;
    IERC20Token[] memory reserveTokens = new IERC20Token[](2);
    uint256[] memory amounts = new uint256[](2);
    reserveTokens[0] = _reserveToken1;
    reserveTokens[1] = _reserveToken2;
    amounts[0] = _reserveAmount1;
    amounts[1] = _reserveAmount2;
    _converter.addLiquidity {
        value: _value
    }(reserveTokens, amounts, 1);
    updatingLiquidity = false;
}

function removeLiquidity(
    IDSToken _poolToken,
    uint256 _poolAmount,
    IERC20Token _reserveToken1,
    IERC20Token _reserveToken2
) internal {
    ILiquidityPoolConverter converter = ILiquidityPoolConverter(payable(ownedBy(_poolToken)));
    updatingLiquidity = true;
    IERC20Token[] memory reserveTokens = new IERC20Token[](2);
    uint256[] memory minReturns = new uint256[](2);
    reserveTokens[0] = _reserveToken1;
    reserveTokens[1] = _reserveToken2;
    minReturns[0] = 1;
    minReturns[1] = 1;
    converter.removeLiquidity(_poolAmount, reserveTokens, minReturns);
    updatingLiquidity = false;
}

function addBaseTokenLiquidity(
    address _owner,
    IConverterAnchor _poolAnchor,
    IERC20Token _baseToken,
    IERC20Token _networkToken,
    uint256 _amount
) internal returns(uint256) {
    IDSToken poolToken = IDSToken(address(_poolAnchor));
    ILiquidityPoolConverter converter = ILiquidityPoolConverter(payable(ownedBy(_poolAnchor)));
    (uint256 reserveBalanceBase, uint256 reserveBalanceNetwork) =
    converterReserveBalances(converter, _baseToken, _networkToken);
    require(reserveBalanceNetwork >= settings.minNetworkTokenLiquidityForMinting(), "ERR_NOT_ENOUGH_LIQUIDITY");
    uint256 newNetworkLiquidityAmount = _amount.mul(reserveBalanceNetwork).div(reserveBalanceBase);
    uint256 mintingLimit = settings.networkTokenMintingLimits(_poolAnchor);
    if (mintingLimit == 0) {
        mintingLimit = settings.defaultNetworkTokenMintingLimit();
    }
    uint256 newNetworkTokensMinted = systemStore.networkTokensMinted(_poolAnchor).add(newNetworkLiquidityAmount);
    require(newNetworkTokensMinted <= mintingLimit, "ERR_MAX_AMOUNT_REACHED");
    mintNetworkTokens(address(this), _poolAnchor, newNetworkLiquidityAmount);
    ensureAllowance(_networkToken, address(converter), newNetworkLiquidityAmount);
    if (_baseToken != ETH_RESERVE_ADDRESS) {
        safeTransferFrom(_baseToken, msg.sender, address(this), _amount);
        ensureAllowance(_baseToken, address(converter), _amount);
    }
    addLiquidity(converter, _baseToken, _networkToken, _amount, newNetworkLiquidityAmount, msg.value);
    uint256 poolTokenAmount = poolToken.balanceOf(address(this));
    safeTransfer(poolToken, address(wallet), poolTokenAmount);
    systemStore.incSystemBalance(poolToken, poolTokenAmount - poolTokenAmount / 2); 
    return addProtectedLiquidity(_owner, poolToken, _baseToken, poolTokenAmount / 2, _amount);
}

function removeLiquidityReturn(
    uint256 _id,
    uint32 _portion,
    uint256 _removeTimestamp
)
external
view
validPortion(_portion)
returns(
    uint256,
    uint256,
    uint256
) {
    ProtectedLiquidity memory liquidity = protectedLiquidity(_id);
    require(liquidity.provider != address(0), "ERR_INVALID_ID");
    require(_removeTimestamp >= liquidity.timestamp, "ERR_INVALID_TIMESTAMP");
    if (_portion != PPM_RESOLUTION) {
        liquidity.poolAmount = liquidity.poolAmount.mul(_portion) / PPM_RESOLUTION;
        liquidity.reserveAmount = liquidity.reserveAmount.mul(_portion) / PPM_RESOLUTION;
    }
    PackedRates memory packedRates =
        packRates(
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.reserveRateN,
            liquidity.reserveRateD,
            false
        );
    uint256 targetAmount =
        removeLiquidityTargetAmount(
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.poolAmount,
            liquidity.reserveAmount,
            packedRates,
            liquidity.timestamp,
            _removeTimestamp
        );
    if (liquidity.reserveToken == networkToken) {
        return (targetAmount, targetAmount, 0);
    }
    Fraction memory poolRate = poolTokenRate(liquidity.poolToken, liquidity.reserveToken);
    uint256 poolAmount = targetAmount.mul(poolRate.d).div(poolRate.n / 2);
    uint256 availableBalance = systemStore.systemBalance(liquidity.poolToken).add(liquidity.poolAmount);
    poolAmount = poolAmount > availableBalance ? availableBalance : poolAmount;
    uint256 baseAmount = poolAmount.mul(poolRate.n / 2).div(poolRate.d);
    uint256 networkAmount = getNetworkCompensation(targetAmount, baseAmount, packedRates);
    return (targetAmount, baseAmount, networkAmount);
}

function claimBalance(uint256 _startIndex, uint256 _endIndex) external protected {
    (uint256[] memory amounts, uint256[] memory expirationTimes) =
    store.lockedBalanceRange(msg.sender, _startIndex, _endIndex);
    uint256 totalAmount = 0;
    uint256 length = amounts.length;
    assert(length == expirationTimes.length);
    for (uint256 i = length; i > 0; i--) {
        uint256 index = i - 1;
        if (expirationTimes[index] > time()) {
            continue;
        }
        store.removeLockedBalance(msg.sender, _startIndex + index);
        totalAmount = totalAmount.add(amounts[index]);
    }
    if (totalAmount > 0) {
        wallet.withdrawTokens(networkToken, msg.sender, totalAmount);
    }
}

function removeLiquidity(
    address payable _provider,
    uint256 _id,
    uint32 _portion
) internal {
    ProtectedLiquidity memory liquidity = protectedLiquidity(_id, _provider);
    IERC20Token networkTokenLocal = networkToken;
    _poolWhitelisted(liquidity.poolToken);
    require(liquidity.timestamp < time(), "ERR_TOO_EARLY");
    if (_portion == PPM_RESOLUTION) {
        if (address(eventsSubscriber) != address(0)) {
            eventsSubscriber.onRemovingLiquidity(
                _id,
                _provider,
                liquidity.poolToken,
                liquidity.reserveToken,
                liquidity.poolAmount,
                liquidity.reserveAmount
            );
        }
        store.removeProtectedLiquidity(_id);
    } else {
        uint256 fullPoolAmount = liquidity.poolAmount;
        uint256 fullReserveAmount = liquidity.reserveAmount;
        liquidity.poolAmount = liquidity.poolAmount.mul(_portion) / PPM_RESOLUTION;
        liquidity.reserveAmount = liquidity.reserveAmount.mul(_portion) / PPM_RESOLUTION;
        if (address(eventsSubscriber) != address(0)) {
            eventsSubscriber.onRemovingLiquidity(
                _id,
                _provider,
                liquidity.poolToken,
                liquidity.reserveToken,
                liquidity.poolAmount,
                liquidity.reserveAmount
            );
        }
        store.updateProtectedLiquidityAmounts(
            _id,
            fullPoolAmount - liquidity.poolAmount,
            fullReserveAmount - liquidity.reserveAmount
        );
    }
    stats.decreaseTotalAmounts(
        liquidity.provider,
        liquidity.poolToken,
        liquidity.reserveToken,
        liquidity.poolAmount,
        liquidity.reserveAmount
    );
    lastRemoveCheckpointStore.addCheckpoint(_provider);
    systemStore.incSystemBalance(liquidity.poolToken, liquidity.poolAmount);
    if (liquidity.reserveToken == networkTokenLocal) {
        safeTransferFrom(govToken, _provider, address(this), liquidity.reserveAmount);
        govTokenGovernance.burn(liquidity.reserveAmount);
    }
    PackedRates memory packedRates =
        packRates(
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.reserveRateN,
            liquidity.reserveRateD,
            true
        );
    uint256 targetAmount =
        removeLiquidityTargetAmount(
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.poolAmount,
            liquidity.reserveAmount,
            packedRates,
            liquidity.timestamp,
            time()
        );
    if (liquidity.reserveToken == networkTokenLocal) {
        mintNetworkTokens(address(wallet), liquidity.poolToken, targetAmount);
        lockTokens(_provider, targetAmount);
        return;
    }
    Fraction memory poolRate = poolTokenRate(liquidity.poolToken, liquidity.reserveToken);
    uint256 poolAmount = targetAmount.mul(poolRate.d).div(poolRate.n / 2);
    uint256 systemBalance = systemStore.systemBalance(liquidity.poolToken);
    poolAmount = poolAmount > systemBalance ? systemBalance : poolAmount;
    systemStore.decSystemBalance(liquidity.poolToken, poolAmount);
    wallet.withdrawTokens(liquidity.poolToken, address(this), poolAmount);
    removeLiquidity(liquidity.poolToken, poolAmount, liquidity.reserveToken, networkTokenLocal);
    uint256 baseBalance;
    if (liquidity.reserveToken == ETH_RESERVE_ADDRESS) {
        baseBalance = address(this).balance;
        _provider.transfer(baseBalance);
    } else {
        baseBalance = liquidity.reserveToken.balanceOf(address(this));
        safeTransfer(liquidity.reserveToken, _provider, baseBalance);
    }
    uint256 delta = getNetworkCompensation(targetAmount, baseBalance, packedRates);
    if (delta > 0) {
        uint256 networkBalance = networkTokenLocal.balanceOf(address(this));
        if (networkBalance < delta) {
            networkTokenGovernance.mint(address(this), delta - networkBalance);
        }
        safeTransfer(networkTokenLocal, address(wallet), delta);
        lockTokens(_provider, delta);
    }
    uint256 networkBalance = networkTokenLocal.balanceOf(address(this));
    if (networkBalance > 0) {
        burnNetworkTokens(liquidity.poolToken, networkBalance);
    }
}

function getNetworkCompensation(
    uint256 _targetAmount,
    uint256 _baseAmount,
    PackedRates memory _packedRates
) internal view returns(uint256) {
    if (_targetAmount <= _baseAmount) {
        return 0;
    }
    uint256 delta =
        (_targetAmount - _baseAmount).mul(_packedRates.removeAverageRateN).div(_packedRates.removeAverageRateD);
    if (delta >= settings.minNetworkCompensation()) {
        return delta;
    }
    return 0;
}

function protectionLevel(uint256 _addTimestamp, uint256 _removeTimestamp) internal view returns(Fraction memory) {
    uint256 timeElapsed = _removeTimestamp.sub(_addTimestamp);
    uint256 minProtectionDelay = settings.minProtectionDelay();
    uint256 maxProtectionDelay = settings.maxProtectionDelay();
    if (timeElapsed < minProtectionDelay) {
        return Fraction({
            n: 0,
            d: 1
        });
    }
    if (timeElapsed >= maxProtectionDelay) {
        return Fraction({
            n: 1,
            d: 1
        });
    }
    return Fraction({
        n: timeElapsed,
        d: maxProtectionDelay
    });
}

function transferPostSettlementSurplus() external {
    require(contractEnabled == 0, "AccountingEngine/still-enabled");
    require(addition(disableTimestamp, disableCooldown) <= now, "AccountingEngine/cooldown-not-passed");
    safeEngine.settleDebt(minimum(safeEngine.coinBalance(address(this)), safeEngine.debtBalance(address(this))));
    safeEngine.transferInternalCoins(address(this), postSettlementSurplusDrain, safeEngine.coinBalance(address(this)));
    emit TransferPostSettlementSurplus(
        postSettlementSurplusDrain,
        safeEngine.coinBalance(address(this)),
        safeEngine.debtBalance(address(this))
    );
}

function modifyParameters(bytes32 parameter, uint256 data) external isAuthorized {
    if (parameter == "surplusAuctionDelay") surplusAuctionDelay = data;
    else if (parameter == "surplusTransferDelay") surplusTransferDelay = data;
    else if (parameter == "popDebtDelay") popDebtDelay = data;
    else if (parameter == "surplusAuctionAmountToSell") surplusAuctionAmountToSell = data;
    else if (parameter == "surplusTransferAmount") surplusTransferAmount = data;
    else if (parameter == "extraSurplusIsTransferred") extraSurplusIsTransferred = data;
    else if (parameter == "debtAuctionBidSize") debtAuctionBidSize = data;
    else if (parameter == "initialDebtAuctionMintedTokens") initialDebtAuctionMintedTokens = data;
    else if (parameter == "surplusBuffer") surplusBuffer = data;
    else if (parameter == "lastSurplusTransferTime") {
        require(data > now, "AccountingEngine/invalid-lastSurplusTransferTime");
        lastSurplusTransferTime = data;
    } else if (parameter == "lastSurplusAuctionTime") {
        require(data > now, "AccountingEngine/invalid-lastSurplusAuctionTime");
        lastSurplusAuctionTime = data;
    } else if (parameter == "disableCooldown") disableCooldown = data;
    else revert("AccountingEngine/modify-unrecognized-param");
    emit ModifyParameters(parameter, data);
}

function popDebtFromQueue(uint256 debtBlockTimestamp) external {
    require(addition(debtBlockTimestamp, popDebtDelay) <= now, "AccountingEngine/pop-debt-delay-not-passed");
    require(debtQueue[debtBlockTimestamp] > 0, "AccountingEngine/null-debt-block");
    totalQueuedDebt = subtract(totalQueuedDebt, debtQueue[debtBlockTimestamp]);
    debtPoppers[debtBlockTimestamp] = msg.sender;
    emit PopDebtFromQueue(now, debtQueue[debtBlockTimestamp], totalQueuedDebt);
    debtQueue[debtBlockTimestamp] = 0;
}

function auctionSurplus() external returns(uint256 id) {
    require(extraSurplusIsTransferred != 1, "AccountingEngine/surplus-transfer-no-auction");
    require(surplusAuctionAmountToSell > 0, "AccountingEngine/null-amount-to-auction");
    settleDebt(unqueuedUnauctionedDebt());
    require(
        now >= addition(lastSurplusAuctionTime, surplusAuctionDelay),
        "AccountingEngine/surplus-auction-delay-not-passed"
    );
    require(
        safeEngine.coinBalance(address(this)) >=
        addition(addition(safeEngine.debtBalance(address(this)), surplusAuctionAmountToSell), surplusBuffer),
        "AccountingEngine/insufficient-surplus"
    );
    require(
        unqueuedUnauctionedDebt() == 0,
        "AccountingEngine/debt-not-zero"
    );
    require(surplusAuctionHouse.protocolToken() != address(0), "AccountingEngine/surplus-auction-house-null-prot");
    lastSurplusAuctionTime = now;
    lastSurplusTransferTime = now;
    id = surplusAuctionHouse.startAuction(surplusAuctionAmountToSell, 0);
    emit AuctionSurplus(id, lastSurplusAuctionTime, safeEngine.coinBalance(address(this)));
}

function transferExtraSurplus() external {
    require(extraSurplusIsTransferred == 1, "AccountingEngine/surplus-auction-not-transfer");
    require(extraSurplusReceiver != address(0), "AccountingEngine/null-surplus-receiver");
    require(surplusTransferAmount > 0, "AccountingEngine/null-amount-to-transfer");
    settleDebt(unqueuedUnauctionedDebt());
    require(
        now >= addition(lastSurplusTransferTime, surplusTransferDelay),
        "AccountingEngine/surplus-transfer-delay-not-passed"
    );
    require(
        safeEngine.coinBalance(address(this)) >=
        addition(addition(safeEngine.debtBalance(address(this)), surplusTransferAmount), surplusBuffer),
        "AccountingEngine/insufficient-surplus"
    );
    require(
        unqueuedUnauctionedDebt() == 0,
        "AccountingEngine/debt-not-zero"
    );
    lastSurplusTransferTime = now;
    lastSurplusAuctionTime = now;
    safeEngine.transferInternalCoins(address(this), extraSurplusReceiver, surplusTransferAmount);
    emit TransferExtraSurplus(extraSurplusReceiver, lastSurplusTransferTime, safeEngine.coinBalance(address(this)));
}

function modifyParameters(bytes32 parameter, address data) external isAuthorized {
    if (parameter == "surplusAuctionHouse") {
        safeEngine.denySAFEModification(address(surplusAuctionHouse));
        surplusAuctionHouse = SurplusAuctionHouseLike(data);
        safeEngine.approveSAFEModification(data);
    } else if (parameter == "systemStakingPool") {
        systemStakingPool = SystemStakingPoolLike(data);
        systemStakingPool.canPrintProtocolTokens();
    } else if (parameter == "debtAuctionHouse") debtAuctionHouse = DebtAuctionHouseLike(data);
    else if (parameter == "postSettlementSurplusDrain") postSettlementSurplusDrain = data;
    else if (parameter == "protocolTokenAuthority") protocolTokenAuthority = ProtocolTokenAuthorityLike(data);
    else if (parameter == "extraSurplusReceiver") extraSurplusReceiver = data;
    else revert("AccountingEngine/modify-unrecognized-param");
    emit ModifyParameters(parameter, data);
}

function auctionDebt() external returns(uint256 id) {
    require(debtAuctionBidSize <= unqueuedUnauctionedDebt(), "AccountingEngine/insufficient-debt");
    settleDebt(safeEngine.coinBalance(address(this)));
    require(safeEngine.coinBalance(address(this)) == 0, "AccountingEngine/surplus-not-zero");
    require(debtAuctionHouse.protocolToken() != address(0), "AccountingEngine/debt-auction-house-null-prot");
    require(protocolTokenAuthority.authorizedAccounts(address(debtAuctionHouse)) == 1, "AccountingEngine/debt-auction-house-cannot-print-prot");
    require(canPrintProtocolTokens(), "AccountingEngine/staking-pool-denies-printing");
    totalOnAuctionDebt = addition(totalOnAuctionDebt, debtAuctionBidSize);
    id = debtAuctionHouse.startAuction(address(this), initialDebtAuctionMintedTokens, debtAuctionBidSize);
    emit AuctionDebt(id, totalOnAuctionDebt, safeEngine.debtBalance(address(this)));
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 5 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        msg.sender.transfer(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function fillOrder(
    address[5] orderAddresses,
    uint[6] orderValues,
    uint fillTakerTokenAmount,
    bool shouldThrowOnInsufficientBalanceOrAllowance,
    uint8 v,
    bytes32 r,
    bytes32 s)
public
returns(uint filledTakerTokenAmount) {
    Order memory order = Order({
        maker: orderAddresses[0],
        taker: orderAddresses[1],
        makerToken: orderAddresses[2],
        takerToken: orderAddresses[3],
        feeRecipient: orderAddresses[4],
        makerTokenAmount: orderValues[0],
        takerTokenAmount: orderValues[1],
        makerFee: orderValues[2],
        takerFee: orderValues[3],
        expirationTimestampInSec: orderValues[4],
        orderHash: getOrderHash(orderAddresses, orderValues)
    });
    require(order.taker == address(0) || order.taker == msg.sender);
    require(order.makerTokenAmount > 0 && order.takerTokenAmount > 0 && fillTakerTokenAmount > 0);
    require(isValidSignature(
        order.maker,
        order.orderHash,
        v,
        r,
        s
    ));
    if (block.timestamp >= order.expirationTimestampInSec) {
        LogError(uint8(Errors.ORDER_EXPIRED), order.orderHash);
        return 0;
    }
    uint remainingTakerTokenAmount = safeSub(order.takerTokenAmount, getUnavailableTakerTokenAmount(order.orderHash));
    filledTakerTokenAmount = min256(fillTakerTokenAmount, remainingTakerTokenAmount);
    if (filledTakerTokenAmount == 0) {
        LogError(uint8(Errors.ORDER_FULLY_FILLED_OR_CANCELLED), order.orderHash);
        return 0;
    }
    if (isRoundingError(filledTakerTokenAmount, order.takerTokenAmount, order.makerTokenAmount)) {
        LogError(uint8(Errors.ROUNDING_ERROR_TOO_LARGE), order.orderHash);
        return 0;
    }
    if (!shouldThrowOnInsufficientBalanceOrAllowance && !isTransferable(order, filledTakerTokenAmount)) {
        LogError(uint8(Errors.INSUFFICIENT_BALANCE_OR_ALLOWANCE), order.orderHash);
        return 0;
    }
    uint filledMakerTokenAmount = getPartialAmount(filledTakerTokenAmount, order.takerTokenAmount, order.makerTokenAmount);
    uint paidMakerFee;
    uint paidTakerFee;
    filled[order.orderHash] = safeAdd(filled[order.orderHash], filledTakerTokenAmount);
    require(transferViaTokenTransferProxy(
        order.makerToken,
        order.maker,
        msg.sender,
        filledMakerTokenAmount
    ));
    require(transferViaTokenTransferProxy(
        order.takerToken,
        msg.sender,
        order.maker,
        filledTakerTokenAmount - safeDiv(filledTakerTokenAmount, ETHFINEX_FEE)
    ));
    LogFill(
        order.maker,
        msg.sender,
        order.feeRecipient,
        order.makerToken,
        order.takerToken,
        filledMakerTokenAmount,
        filledTakerTokenAmount,
        paidMakerFee,
        paidTakerFee,
        keccak256(order.makerToken, order.takerToken),
        order.orderHash
    );
    return filledTakerTokenAmount;
}

function unStake(address user, uint256 stakeId) external whenNotPaused {
    require(
        msg.sender == user || msg.sender == _owner,
        "UNSTAKE: Invalid User Entry"
    );
    (,
        address[] memory tokenAddress,
        bool[] memory activeStatus, ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = (u2.viewStakingDetails(user));
    bool isAlreadyUnstaked = u2Proxy.unstakeStatus(user, stakeId);
    bool isAlreadyUnstakedFromReproxy = u2Reproxy.u2UnstakeStatus(user, stakeId);
    require(
        u2UpgradeLockableDetails[tokenAddress[stakeId]].lockableDays <=
        block.timestamp,
        "Token Locked"
    );
    if (
        u2UpgradeLockableDetails[tokenAddress[stakeId]].optionableStatus ==
        true
    ) {
        require(
            poolStartTime.add(u2.stakeDuration()) <= block.timestamp,
            "Locked in optional lock"
        );
    }
    if (
        u2ReproxyUnstakeStatus[user][stakeId] == false &&
        activeStatus[stakeId] == true &&
        isAlreadyUnstaked == false &&
        isAlreadyUnstakedFromReproxy == false
    ) u2ReproxyUnstakeStatus[user][stakeId] = true;
    else revert("UNSTAKE : Unstaked Already");
    uint256 totalStaking = getTotalStaking(tokenAddress[stakeId]);
    require(
        IERC20(tokenAddress[stakeId]).balanceOf(address(this)) >=
        stakedAmount[stakeId],
        "UNSTAKE : Insufficient Balance"
    );
    IERC20(tokenAddress[stakeId]).transfer(user, stakedAmount[stakeId]);
    if (startTime[stakeId] < poolStartTime.add(u2.stakeDuration())) {
        claimRewards(user, stakeId, totalStaking);
    }
    emit UnStake(
        user,
        tokenAddress[stakeId],
        stakedAmount[stakeId],
        block.timestamp,
        stakeId
    );
}

constructor(address _tokenAddr, uint256 _tokenLockEndTime) public {
    require(_tokenAddr != address(0), "");
    require(_tokenLockEndTime > now, "");
    tokenLockEndTime = _tokenLockEndTime;
    tokenContract = LVECoin(_tokenAddr);
}

function withdrawBatchTokenToInvestor() public onlyOwner returns(bool) {
    require(now > tokenLockEndTime, "");
    uint256 investorCount = getInvestorCount();
    require(investorCount > 0, "");
    for (uint256 i = 0; i < investorCount; i++) {
        address investorAddr = investorsList[i];
        Investor memory investor = investorMap[investorAddr];
        if (investor.isLocked && now > investor.endTime && !freezeAccountMap[investor.addr]) {
            require(tokenContract.transfer(investor.addr, investor.lockAmount), "");
            emit WithdrawalToken(investor.addr, investor.lockAmount);
            investor.endTime = 0;
            investor.isLocked = false;
            investor.lockAmount = 0;
            investorMap[investor.addr] = investor;
            emit UnLock(investor.addr, investor.lockAmount);
        }
    }
    return true;
}

function recyclingRemainToken() public onlyOwner whenNotPaused returns(bool) {
    require(now > tokenLockEndTime, "");
    uint256 remainToken = tokenSupplyQuota.sub(tokensSold);
    require(remainToken > 0, "");
    require(tokenContract.transfer(msg.sender, remainToken), "");
    pause();
    return true;
}

function addlockAccount(address _lockAddr, uint256 _endTime, uint256 _lockAmount) internal returns(bool) {
    require(_lockAddr != address(0), "");
    require(_endTime >= now, "");
    require(_lockAmount > 0, "");
    if (investorMap[_lockAddr].addr != _lockAddr) {
        investorsList.push(_lockAddr);
    }
    Investor memory investor;
    investor.endTime = _endTime;
    investor.addr = _lockAddr;
    investor.isLocked = true;
    investor.lockAmount = investorMap[_lockAddr].lockAmount.add(_lockAmount);
    investor.investAmount = investorMap[_lockAddr].investAmount.add(_lockAmount);
    investorMap[_lockAddr] = investor;
    emit Lock(_lockAddr, _lockAmount, _endTime);
    return true;
}

function withdrawTokenToInvestorOwner(address _investorAddr) public onlyOwner returns(bool) {
    require(_investorAddr != address(0), "");
    require(now > tokenLockEndTime, "");
    Investor memory investor = investorMap[_investorAddr];
    if (investor.isLocked && now > investor.endTime && !freezeAccountMap[investor.addr]) {
        require(tokenContract.transfer(investor.addr, investor.lockAmount), "");
        emit WithdrawalToken(investor.addr, investor.lockAmount);
        investor.endTime = 0;
        investor.isLocked = false;
        investor.lockAmount = 0;
        investorMap[investor.addr] = investor;
        emit UnLock(investor.addr, investor.lockAmount);
    }
    return true;
}

function claim() public returns(uint) {
    require(unclaimed[msg.sender] > 0, "Cannot claim 0 or less");
    uint amount = unclaimed[msg.sender];
    uint fee = amount.mul(500).div(1e4);
    amount = amount.sub(fee);
    Token(tokenAddress).transfer(msg.sender, amount);
    Token(tokenAddress).transfer(rewardAddress, fee);
    emit CashbackClaimed(msg.sender, unclaimed[msg.sender]);
    claimed[msg.sender] = claimed[msg.sender].add(unclaimed[msg.sender]);
    unclaimed[msg.sender] = 0;
}

function withdrawTokens() public onlyOwner {
    IERC20(PhuketTokenAddress).transfer(
        owner(),
        IERC20(PhuketTokenAddress).balanceOf(address(this))
    );
    pause();
}

function stakeALT(uint256 _altQuantity, uint256 _days)
public
whenNotPaused
returns(uint256 rewardAmount) {
    require(_days <= stakeDays && _days > 0, "Invalid Days"); 
    require(
        _altQuantity <= maxStakedQuantity && _altQuantity > 0,
        "Invalid Phuket quantity"
    ); 
    IERC20(PhuketTokenAddress).transferFrom(
        msg.sender,
        address(this),
        _altQuantity
    );
    rewardAmount = 0;
    uint256 _timestamp = block.timestamp;
    if (stakerData[_timestamp].staker != address(0)) {
        _timestamp = _timestamp.add(1);
    }
    stakerData[_timestamp] = StakerData(
        _altQuantity,
        _timestamp,
        _days.mul(ONE_DAY),
        (_days.mul(ONE_DAY)).add(_timestamp),
        rewardAmount,
        msg.sender,
        _days.mul(1e18),
        0,
        0,
        false
    );
    stakerBalance[msg.sender] = stakerBalance[msg.sender].add(_altQuantity);
    totalStakedTokens = totalStakedTokens.add(_altQuantity);
    Storetimes[msg.sender].invTime.push(_timestamp);
    laststake[msg.sender] = _timestamp;
    emit StakeCompleted(
        _altQuantity,
        _timestamp,
        _days.mul(ONE_DAY),
        rewardAmount,
        msg.sender,
        PhuketTokenAddress,
        address(this)
    );
}

function unstakeALT(uint256[] calldata _expiredTimestamps)
external
whenNotPaused
returns(bool) {
    for (uint256 i = 0; i < _expiredTimestamps.length; i = i.add(1)) {
        uint256 withdrawAmount = 0;
        uint256 rewardAmount = 0;
        uint256 timestamp = block.timestamp;
        require(!(stakerData[_expiredTimestamps[i]].isCompleted), "Already Unstaked");
        withdrawAmount = stakerData[_expiredTimestamps[i]].altQuantity;
        uint256 initiate_time = stakerData[_expiredTimestamps[i]].initiationTimestamp;
        uint256 exactDays = (timestamp).sub(initiate_time);
        rewardAmount = _calculateReward(withdrawAmount, ratio, exactDays);
        IERC20(PhuketTokenAddress).transfer(msg.sender, rewardAmount);
        stakerData[_expiredTimestamps[i]].withdrawable = withdrawAmount;
        stakerBalance[msg.sender] = stakerBalance[msg.sender].sub(withdrawAmount);
        totalStakedTokens = totalStakedTokens.sub(withdrawAmount);
        IERC20(PhuketTokenAddress).transfer(msg.sender, withdrawAmount);
        emit Unstake(msg.sender,
            PhuketTokenAddress,
            address(this),
            stakerData[_expiredTimestamps[i]].altQuantity,
            _expiredTimestamps[i],
            rewardAmount
        );
        stakerData[_expiredTimestamps[i]].rewardAmountdata = rewardAmount;
        stakerData[_expiredTimestamps[i]].isCompleted = true;
    }
    return true;
}

function earnedReward(uint256 _id) public view returns(uint256) {
    uint256 rewardAmount;
    if (stakerData[_id].endTime <= block.timestamp) {
        uint256 exactDays = (stakerData[_id].exactdate).mul(ONE_DAY);
        rewardAmount = _calculateReward(stakerData[_id].altQuantity, ratio, exactDays);
    } else {
        uint256 days_remaining = (block.timestamp).sub(stakerData[_id].initiationTimestamp);
        rewardAmount = _calculateReward(stakerData[_id].altQuantity, ratio, days_remaining);
    }
    return rewardAmount;
}

