function receiveFod() public {
    uint256 unlockAmount;
    uint256 currentAmount;
    Pledge[] pledges = addressToPledge[msg.sender];
    for (uint i = 0; i < pledges.length; i++) {
        if (pledges[i].end == 1) continue;
        uint day = (now.sub(pledges[i].createTime)).div(intervalTime);
        uint256 dayAmount = pledges[i].earnings.div(pledges[i].day);
        if (now > pledges[i].dueTime) {
            if (day.add(pledges[i].receivedDay) >= pledges[i].day) {
                currentAmount = (pledges[i].day.sub(pledges[i].receivedDay)).mul(dayAmount).add(pledges[i].investAmount);
            } else {
                currentAmount = (day.sub(pledges[i].receivedDay)).mul(dayAmount).add(pledges[i].investAmount);
            }
            pledges[i].end = 1;
        } else {
            currentAmount = (day.sub(pledges[i].receivedDay)).mul(dayAmount);
            pledges[i].receivedDay = day;
        }
        unlockAmount = unlockAmount.add(currentAmount);
    }
    bytes4 inviteCode = bytes4(keccak256((msg.sender)));
    Invite[] Invites = inviteLogs[inviteCode];
    for (uint j = 0; j < Invites.length; j++) {
        if (Invites[j].end == 1) continue;
        uint day2 = (now.sub(Invites[j].createTime)).div(intervalTime);
        uint256 dayAmount2 = Invites[j].earnings.div(Invites[j].day);
        if (day2.add(Invites[j].receivedDay) >= Invites[j].day) {
            currentAmount = (Invites[j].day.sub(Invites[j].receivedDay)).mul(dayAmount2);
            Invites[j].end = 1;
        } else {
            currentAmount = (day2.sub(Invites[j].receivedDay)).mul(dayAmount2);
            Invites[j].receivedDay = day2;
        }
        unlockAmount = unlockAmount.add(currentAmount);
    }
    IERC20 fodToken = IERC20(fod);
    fodToken.transfer(msg.sender, unlockAmount);
    emit GetFod(msg.sender, unlockAmount);
}

function trade(TradeInput tradeInput) internal returns(uint) {
    require(isEnabled);
    require(tx.gasprice <= maxGasPriceValue);
    require(validateTradeInput(tradeInput.src, tradeInput.srcAmount, tradeInput.dest, tradeInput.destAddress));
    BestRateResult memory rateResult =
        findBestRateTokenToToken(tradeInput.src, tradeInput.dest, tradeInput.srcAmount, tradeInput.hint);
    require(rateResult.rate > 0);
    require(rateResult.rate < MAX_RATE);
    require(rateResult.rate >= tradeInput.minConversionRate);
    uint actualDestAmount;
    uint weiAmount;
    uint actualSrcAmount;
    (actualSrcAmount, weiAmount, actualDestAmount) = calcActualAmounts(tradeInput.src,
        tradeInput.dest,
        tradeInput.srcAmount,
        tradeInput.maxDestAmount,
        rateResult);
    require(getUserCapInWei(tradeInput.trader) >= weiAmount);
    require(handleChange(tradeInput.src, tradeInput.srcAmount, actualSrcAmount, tradeInput.trader));
    require(doReserveTrade( 
        tradeInput.src,
        actualSrcAmount,
        ETH_TOKEN_ADDRESS,
        this,
        weiAmount,
        KyberReserveInterface(rateResult.reserve1),
        rateResult.rateSrcToEth,
        true));
    require(doReserveTrade( 
        ETH_TOKEN_ADDRESS,
        weiAmount,
        tradeInput.dest,
        tradeInput.destAddress,
        actualDestAmount,
        KyberReserveInterface(rateResult.reserve2),
        rateResult.rateEthToDest,
        true));
    if (tradeInput.src != ETH_TOKEN_ADDRESS) 
        require(feeBurnerContract.handleFees(weiAmount, rateResult.reserve1, tradeInput.walletId));
    if (tradeInput.dest != ETH_TOKEN_ADDRESS) 
        require(feeBurnerContract.handleFees(weiAmount, rateResult.reserve2, tradeInput.walletId));
    KyberTrade({
        trader: tradeInput.trader,
        src: tradeInput.src,
        dest: tradeInput.dest,
        srcAmount: actualSrcAmount,
        dstAmount: actualDestAmount,
        destAddress: tradeInput.destAddress,
        ethWeiValue: weiAmount,
        reserve1: (tradeInput.src == ETH_TOKEN_ADDRESS) ? address(0) : rateResult.reserve1,
        reserve2: (tradeInput.dest == ETH_TOKEN_ADDRESS) ? address(0) : rateResult.reserve2,
        hint: tradeInput.hint
    });
    return actualDestAmount;
}

function listPairForReserve(address reserve, ERC20 token, bool ethToToken, bool tokenToEth, bool add)
public
onlyOperator
returns(bool) {
    require(reserveType[reserve] != ReserveType.NONE);
    if (ethToToken) {
        listPairs(reserve, token, false, add);
        ListReservePairs(reserve, ETH_TOKEN_ADDRESS, token, add);
    }
    if (tokenToEth) {
        listPairs(reserve, token, true, add);
        if (add) {
            require(token.approve(reserve, 2 ** 255)); 
        } else {
            require(token.approve(reserve, 0));
        }
        ListReservePairs(reserve, token, ETH_TOKEN_ADDRESS, add);
    }
    setDecimals(token);
    return true;
}

function airDrop(address[] recipients, uint amount) onlyOwner public {
    require(amount > 0);
    for (uint i = 0; i < recipients.length; i++) {
        myToken.transfer(recipients[i], amount);
        emit TokenDrop(recipients[i], amount);
    }
    numDrops += recipients.length;
    dropAmount += recipients.length * amount;
}

function pushPrivateInvestment(uint256 _weiAmount, uint256 _tokenAmount, address _beneficiary) external onlyOwner {
    require(block.timestamp <= closingTime);
    require(_weiAmount >= minimumInvestment, "Wei amount lower than minimum investment");
    require(_beneficiary != address(0));
    require(weiRaised.add(_weiAmount) <= cap);
    _deliverTokens(_beneficiary, _tokenAmount);
    weiRaised = weiRaised.add(_weiAmount);
    _addToWhitelist(_beneficiary);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        _weiAmount,
        _tokenAmount
    );
}

