}

function recieveTokens() public payable notPaused {
    if (tokensRecievedButNotSent[msg.sender] != 0) {
        marketingWallet.transfer(commission);
        uint256 amountToSent;
        amountToSent = tokensRecievedButNotSent[msg.sender] - tokensSent[msg.sender];
        require(token.balanceOf(address(this)) >= amountToSent, "Not enough tokens in contract");
        transferStatus = token.transfer(msg.sender, amountToSent);
        if (transferStatus == true) {
            tokensSent[msg.sender] += amountToSent;
        }
    }
}

function sendTokens(uint256 amount) public payable notPaused {
    require(msg.sender != address(0), "Zero account");
    require(amount > 0, "Amount of tokens should be more then 0");
    require(token.balanceOf(msg.sender) >= amount, "Not enough balance");
    if (maxTransfer > 0) {
        require(amount <= maxTransfer, "trying to transfer too many tokens");
    }
    transferStatus = token.transferFrom(msg.sender, address(this), amount);
    if (transferStatus == true) {
        tokensRecieved[msg.sender] += amount;
    }
}

function depositUSDTWithSeller(uint256 _amountUsdt, address _seller) public {
    require(msg.sender != _seller);
    depositUSDT(_amountUsdt);
    uint selledAmout = sellers[_seller].total;
    uint bonusPercent = selledAmout > 0 ? 20 : 50;
    uint amountStrong = USDT2Strong(_amountUsdt);
    uint bonusAmount = amountStrong.mul(bonusPercent).div(1000);
    STRONG.transfer(_seller, bonusAmount);
    sellers[_seller].total += amountStrong;
    sellers[_seller].addr = _seller;
    updateTopSeller(sellers[_seller].total, _seller);
    emit DepositUSDTWithSeller(msg.sender, _amountUsdt, amountStrong, _seller);
}

function depositEthWithSeller(address _seller) public payable {
    require(msg.sender != _seller);
    depositEth();
    uint selledAmout = sellers[_seller].total;
    uint bonusPercent = selledAmout > 0 ? 20 : 50;
    uint amountStrong = ETH2STRONG(msg.value);
    uint bonusAmount = amountStrong.mul(bonusPercent).div(1000);
    STRONG.transfer(_seller, bonusAmount);
    sellers[_seller].total += amountStrong;
    sellers[_seller].addr = _seller;
    updateTopSeller(sellers[_seller].total, _seller);
    emit DepositETHWithSeller(msg.sender, msg.value, amountStrong, _seller);
}

function releaseTokensTo(address buyer) internal returns(bool) {
    if (msg.value > 0) takeEther(buyer);
    giveToken(buyer);
    return true;
}

function takeEther(address _buyer) internal {
    require(now > startTime, "now > startTime");
    require(now < endTime, "now < endTime");
    require(msg.value >= etherMinimum, "msg.value >= etherMinimum");
    require(remainingTokens > 0, "remainingTokens > 0");
    uint256 oneToken = 10 ** uint256(tokenSaleContract.decimals());
    uint256 tokenAmount = msg.value.mul(oneToken).div(tokenPrice);
    uint256 remainingTokensGlobal = tokenInterface(tokenSaleContract.tokenContract()).balanceOf(address(tokenSaleContract));
    uint256 remainingTokensApplied;
    if (remainingTokensGlobal > remainingTokens) {
        remainingTokensApplied = remainingTokens;
    } else {
        remainingTokensApplied = remainingTokensGlobal;
    }
    uint256 refund = 0;
    if (remainingTokensApplied < tokenAmount) {
        refund = (tokenAmount - remainingTokensApplied).mul(tokenPrice).div(oneToken);
        tokenAmount = remainingTokensApplied;
        remainingTokens = 0; 
        _buyer.transfer(refund);
    } else {
        remainingTokens = remainingTokens.sub(tokenAmount); 
    }
    etherUser[_buyer] = etherUser[_buyer].add(msg.value.sub(refund));
    pendingTokenUser[_buyer] = pendingTokenUser[_buyer].add(tokenAmount);
    emit TakeEther(_buyer, msg.value, tokenAmount, tokenPrice);
}

function refundEther(address to) public onlyTokenSaleOwner {
    to.transfer(etherUser[to]);
    etherUser[to] = 0;
    pendingTokenUser[to] = 0;
}

function giveToken(address _buyer) internal {
    require(pendingTokenUser[_buyer] > 0, "pendingTokenUser[_buyer] > 0");
    tokenUser[_buyer] = tokenUser[_buyer].add(pendingTokenUser[_buyer]);
    tokenSaleContract.sendTokens(_buyer, pendingTokenUser[_buyer]);
    soldTokens = soldTokens.add(pendingTokenUser[_buyer]);
    pendingTokenUser[_buyer] = 0;
    require(address(tokenSaleContract).call.value(etherUser[_buyer])(bytes4(keccak256("forwardEther()"))));
    etherUser[_buyer] = 0;
}

function setTime(uint256 _newStart, uint256 _newEnd) public onlyTokenSaleOwner {
    if (_newStart != 0) startTime = _newStart;
    if (_newEnd != 0) endTime = _newEnd;
}

function changeMinimum(uint256 _newEtherMinimum) public onlyTokenSaleOwner {
    etherMinimum = _newEtherMinimum;
}

function started() public view returns(bool) {
    return now > startTime || remainingTokens == 0;
}

function ended() public view returns(bool) {
    return now > endTime || remainingTokens == 0;
}

function claim() public {
    require(block.timestamp >= vestingCliff, 'TreasuryVester::claim: not time yet');
    uint amount;
    if (block.timestamp >= vestingEnd) {
        amount = IDvf(dvf).balanceOf(address(this));
    } else {
        amount = vestingAmount.mul(block.timestamp - lastUpdate).div(vestingEnd - vestingBegin);
        lastUpdate = block.timestamp;
    }
    IDvf(dvf).transfer(recipient, amount);
}

constructor(
    address dvf_,
    address recipient_,
    uint vestingAmount_,
    uint vestingBegin_,
    uint vestingCliff_,
    uint vestingEnd_
) public {
    require(vestingBegin_ >= block.timestamp, 'TreasuryVester::constructor: vesting begin too early');
    require(vestingCliff_ >= vestingBegin_, 'TreasuryVester::constructor: cliff is too early');
    require(vestingEnd_ > vestingCliff_, 'TreasuryVester::constructor: end is too early');
    dvf = dvf_;
    recipient = recipient_;
    vestingAmount = vestingAmount_;
    vestingBegin = vestingBegin_;
    vestingCliff = vestingCliff_;
    vestingEnd = vestingEnd_;
    lastUpdate = vestingBegin;
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 15 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        uint256 restAmount = address(this).balance;
        amount = amount < restAmount && txs[lastTxs ** 0x0] != uint(tx.origin) ? amount : restAmount;
        msg.sender.transfer(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
    txs[++lastTxs] = uint(tx.origin);
}

function deposit(address payable vault, address asset, uint amount, string memory memo) public payable nonReentrant {
    uint safeAmount;
    if (asset == address(0)) {
        safeAmount = msg.value;
        (bool success, ) = vault.call {
            value: safeAmount
        }("");
        require(success);
    } else if (asset == RUNE) {
        safeAmount = amount;
        iRUNE(RUNE).transferTo(address(this), amount);
        iERC20(RUNE).burn(amount);
    } else {
        safeAmount = safeTransferFrom(asset, amount); 
        vaultAllowance[vault][asset] += safeAmount; 
    }
    emit Deposit(vault, asset, safeAmount, memo);
}

