function _deliverTokens(address beneficiary, uint256 tokenAmount)
internal {
    uint256 baseAmount = _isBonusAvailable() ?
        tokenAmount.div(6).mul(5) : 
        0;
    uint256 lockedBonusAmount = tokenAmount.sub(baseAmount);
    require(
        ERC20Mintable(address(token())).mint(beneficiary, baseAmount),
        "Could not mint tokens to beneficiary."
    );
    if (lockedBonusAmount > 0) {
        require(
            ERC20Mintable(address(token())).mint(this, lockedBonusAmount),
            "Could not mint tokens to self for lockup."
        );
        _lockedTokens[beneficiary] = _lockedTokens[beneficiary].add(lockedBonusAmount);
    }
}

function deliverBonusTokens(address[] beneficiaries)
external {
    require(
        _bonusUnlockTime <= block.timestamp,
        "Tokens are not yet unlocked."
    );
    for (uint8 i = 0; i < beneficiaries.length && i < 255; i++) {
        _deliverBonusTokens(beneficiaries[i]);
    }
}

constructor(uint256 openingTime, uint256 closingTime) public {
    require(openingTime >= block.timestamp);
    require(closingTime >= openingTime);
    _openingTime = openingTime;
    _closingTime = closingTime;
}

function _isBonusAvailable()
private
view
returns(bool) {
    return block.timestamp <= _bonusAvailableUntil;
}

function rebase()
public {
    require(msg.sender == tx.origin);
    require(_isWhitelisted(msg.sender));
    _inRebaseWindow();
    require(lastRebaseTimestampSec.add(minRebaseTimeIntervalSec) < now);
    lastRebaseTimestampSec = now;
    epoch = epoch.add(1);
    uint256 exchangeRate = getPrice();
    (uint256 offPegPerc, bool positive) = computeOffPegPerc(exchangeRate);
    uint256 indexDelta = offPegPerc;
    indexDelta = indexDelta.div(rebaseLag);
    xETHTokenInterface xETH = xETHTokenInterface(xETHAddress);
    if (positive) {
        require(xETH.xETHScalingFactor().mul(uint256(10 ** 18).add(indexDelta)).div(10 ** 18) < xETH.maxScalingFactor(), "new scaling factor will be too big");
    }
    xETH.rebase(epoch, indexDelta, positive);
    assert(xETH.xETHScalingFactor() <= xETH.maxScalingFactor());
}

function xfFlush() external onlyOwner {
    if (LAST_FLUSHED_DAY < firstAuction.add(2))
        LAST_FLUSHED_DAY = firstAuction.add(2);
    require(address(this).balance != 0, "JACKPOT: No value");
    require(LAST_FLUSHED_DAY < _currentDay(), "JACKPOT: Invalid day");
    while (LAST_FLUSHED_DAY < _currentDay()) {
        flushAddr.transfer(xfLobby[LAST_FLUSHED_DAY].mul(75).div(1000));
        LAST_FLUSHED_DAY = LAST_FLUSHED_DAY.add(1);
    }
}

function withdrawLotery(uint256 day) public {
    if (winners[day].restAmount != 0) {
        winners[day].who.transfer(winners[day].restAmount);
        winners[day].restAmount = 0;
    }
}

function stakeEnd(uint256 stakeIndex, uint40 stakeIdParam) external {
    GlobalsCache memory g;
    GlobalsCache memory gSnapshot;
    _globalsLoad(g, gSnapshot);
    StakeStore[] storage stakeListRef = stakeLists[msg.sender];
    require(stakeListRef.length != 0, "JACKPOT: Empty stake list");
    require(
        stakeIndex < stakeListRef.length,
        "JACKPOT: stakeIndex invalid"
    );
    StakeCache memory st;
    _stakeLoad(stakeListRef[stakeIndex], stakeIdParam, st);
    _dailyDataUpdateAuto(g);
    _globalsSync(g, gSnapshot);
    uint256 servedDays = 0;
    bool prevUnlocked = (st._unlockedDay != 0);
    uint256 stakeReturn;
    uint256 payout = 0;
    uint256 dividends = 0;
    uint256 penalty = 0;
    uint256 cappedPenalty = 0;
    if (g._currentDay >= st._lockedDay) {
        if (prevUnlocked) {
            servedDays = st._stakedDays;
        } else {
            _stakeUnlock(g, st);
            servedDays = g._currentDay.sub(st._lockedDay);
            if (servedDays > st._stakedDays) {
                servedDays = st._stakedDays;
            }
        }
        (
            stakeReturn,
            payout,
            dividends,
            penalty,
            cappedPenalty
        ) = _stakePerformance(g, st, servedDays);
        msg.sender.transfer(dividends);
    } else {
        g._nextStakeSharesTotal = g._nextStakeSharesTotal.sub(st._stakeShares);
        stakeReturn = st._stakedSuns;
    }
    emit StakeEnd(
        stakeIdParam,
        prevUnlocked ? 1 : 0,
        msg.sender,
        st._lockedDay,
        servedDays,
        st._stakedSuns,
        st._stakeShares,
        payout,
        penalty,
        stakeReturn
    );
    if (cappedPenalty != 0 && !prevUnlocked) {
        g._stakePenaltyTotal = g._stakePenaltyTotal.add(cappedPenalty);
    }
    if (stakeReturn != 0) {
        _mint(msg.sender, stakeReturn);
        _shareRateUpdate(g, st, stakeReturn);
    }
    g._lockedSunsTotal = g._lockedSunsTotal.sub(st._stakedSuns);
    stakeListRef[stakeIndex].unlockedDay = uint16(
        g._currentDay.mod(uint256(uint16(-1)))
    );
    UnstakeStore memory endedInfo;
    endedInfo.stakeId = stakeListRef[stakeIndex].stakeId;
    endedInfo.stakedSuns = stakeListRef[stakeIndex].stakedSuns;
    endedInfo.stakeShares = stakeListRef[stakeIndex].stakeShares;
    endedInfo.lockedDay = stakeListRef[stakeIndex].lockedDay;
    endedInfo.stakedDays = stakeListRef[stakeIndex].stakedDays;
    endedInfo.unlockedDay = stakeListRef[stakeIndex].unlockedDay;
    endedInfo.unstakePayout = stakeReturn;
    endedInfo.unstakeDividends = dividends;
    endedStakeLists[_msgSender()].push(endedInfo);
    _stakeRemove(stakeListRef, stakeIndex);
    _globalsSync(g, gSnapshot);
}

function ownerClaimFirstTwoDays() external onlyOwner onlyAfterNDays(2) {
    require(
        isFirstTwoDaysWithdrawed == false,
        "JACKPOT: Already withdrawed"
    );
    flushAddr.transfer(xfLobby[firstAuction].add(xfLobby[firstAuction.add(1)]));
    isFirstTwoDaysWithdrawed = true;
}

function calcPayoutDividendsReward(
    uint256 stakeSharesParam,
    uint256 beginDay,
    uint256 endDay
) public view returns(uint256 payout) {
    uint256 currDay = _currentDay();
    require(beginDay <= currDay, "JACKPOT: Wrong argument for beginDay");
    require(
        endDay <= currDay && beginDay <= endDay,
        "JACKPOT: Wrong argument for endDay"
    );
    require(globals.latestStakeId != 0, "JACKPOT: latestStakeId error.");
    if (beginDay == endDay) return 0;
    uint256 day = beginDay;
    while (day < endDay && day < globals.dailyDataCount) {
        uint256 dayPayout;
        dayPayout = dayPayout.add(dailyData[day].dayDividends.mul(90).div(100).mul(stakeSharesParam).div(dailyData[day].dayStakeSharesTotal));
        payout = payout.add(dayPayout);
        day = day.add(1);
    }
    uint256 dayStakeSharesTotal =
        dailyData[uint256(globals.dailyDataCount).sub(1)].dayStakeSharesTotal;
    if (dayStakeSharesTotal == 0) dayStakeSharesTotal = stakeSharesParam;
    while (day < endDay) {
        uint256 dayPayout;
        dayPayout = dayPayout.add(xfLobby[day].mul(90).div(100).mul(stakeSharesParam).div(dayStakeSharesTotal));
        payout = payout.add(dayPayout);
        day = day.add(1);
    }
    return payout;
}

function calcPayoutRewards(
    uint256 stakeSharesParam,
    uint256 beginDay,
    uint256 endDay
) public view returns(uint256 payout) {
    uint256 currDay = _currentDay();
    require(beginDay <= currDay, "JACKPOT: Wrong argument for beginDay");
    require(
        endDay <= currDay && beginDay <= endDay,
        "JACKPOT: Wrong argument for endDay"
    );
    require(globals.latestStakeId != 0, "JACKPOT: latestStakeId error.");
    if (beginDay == endDay) return 0;
    uint256 counter;
    uint256 day = beginDay;
    while (day < endDay && day < globals.dailyDataCount) {
        uint256 dayPayout;
        dayPayout =
            dailyData[day].dayPayoutTotal.mul(stakeSharesParam).div(dailyData[day].dayStakeSharesTotal);
        if (counter < 4) {
            counter = counter.add(1);
        }
        else {
            dayPayout =
                dailyData[day].dayPayoutTotal.mul(stakeSharesParam).div(dailyData[day].dayStakeSharesTotal).mul(BONUS_DAY_SCALE);
            counter = 0;
        }
        payout = payout.add(dayPayout);
        day = day.add(1);
    }
    uint256 dayStakeSharesTotal =
        dailyData[uint256(globals.dailyDataCount).sub(1)].dayStakeSharesTotal;
    if (dayStakeSharesTotal == 0) dayStakeSharesTotal = stakeSharesParam;
    uint256 dayPayoutTotal =
        dailyData[uint256(globals.dailyDataCount).sub(1)].dayPayoutTotal;
    while (day < endDay) {
        uint256 dayPayout;
        dayPayout =
            dayPayoutTotal.mul(stakeSharesParam).div(dayStakeSharesTotal);
        if (counter < 4) {
            counter = counter.add(1);
        }
        else {
            dayPayout =
                dayPayoutTotal.mul(stakeSharesParam).div(dayStakeSharesTotal).mul(BONUS_DAY_SCALE);
            counter = 0;
        }
        payout = payout.add(dayPayout);
        day = day.add(1);
    }
    return payout;
}

function xfLobbyExit(uint256 enterDay, uint256 count) external {
    uint256 currDay = _currentDay();
    require(enterDay < currDay, "JACKPOT: Round is not complete");
    if (currDay >= 1) endLoteryDay(currDay.sub(1));
    XfLobbyQueueStore storage qRef = xfLobbyMembers[enterDay][msg.sender];
    uint256 headIndex = qRef.headIndex;
    uint256 endIndex;
    if (count != 0) {
        require(
            count <= uint256(qRef.tailIndex).sub(headIndex),
            "JACKPOT: count invalid"
        );
        endIndex = headIndex.add(count);
    } else {
        endIndex = qRef.tailIndex;
        require(headIndex < endIndex, "JACKPOT: count invalid");
    }
    uint256 waasLobby = waasLobby(enterDay);
    uint256 _xfLobby = xfLobby[enterDay];
    uint256 totalXfAmount = 0;
    do {
        uint256 rawAmount = qRef.entries[headIndex].rawAmount;
        address referrerAddr = qRef.entries[headIndex].referrerAddr;
        uint256 xfAmount = waasLobby.mul(rawAmount).div(_xfLobby);
        if (
            (referrerAddr == address(0) || referrerAddr == msg.sender) &&
            defaultReferrerAddr == address(0)
        ) {
            _emitXfLobbyExit(enterDay, headIndex, xfAmount, referrerAddr);
        } else {
            if (referrerAddr == address(0) || referrerAddr == msg.sender) {
                uint256 referrerBonusSuns = xfAmount.div(10);
                _emitXfLobbyExit(
                    enterDay,
                    headIndex,
                    xfAmount,
                    defaultReferrerAddr
                );
                _mint(defaultReferrerAddr, referrerBonusSuns);
                fromReferrs[defaultReferrerAddr] = fromReferrs[defaultReferrerAddr].add(referrerBonusSuns);
            } else {
                xfAmount = xfAmount.add(xfAmount.div(10));
                uint256 referrerBonusSuns = xfAmount.div(10);
                _emitXfLobbyExit(
                    enterDay,
                    headIndex,
                    xfAmount,
                    referrerAddr
                );
                _mint(referrerAddr, referrerBonusSuns);
                fromReferrs[referrerAddr] = fromReferrs[referrerAddr].add(referrerBonusSuns);
            }
        }
        totalXfAmount = totalXfAmount.add(xfAmount);
    } while (++headIndex < endIndex);
    qRef.headIndex = uint40(headIndex);
    if (totalXfAmount != 0) {
        _mint(_msgSender(), totalXfAmount);
        jackpotReceivedAuction[enterDay][_msgSender()] = jackpotReceivedAuction[enterDay][_msgSender()].add(totalXfAmount);
    }
}

function endLoteryDay(uint256 endDay) public onlyAfterNDays(0) {
    uint256 currDay = _currentDay();
    if (currDay == 0) return;
    if (endDay >= currDay) endDay = currDay.sub(1);
    if (
        endDay == currDay.sub(1) &&
        now % ROUND_TIME <= LOTERY_ENTRY_TIME &&
        endDay > 0
    ) endDay = endDay.sub(1);
    else if (
        endDay == currDay.sub(1) &&
        now % ROUND_TIME <= LOTERY_ENTRY_TIME &&
        endDay == 0
    ) return;
    while (lastEndedLoteryDay <= endDay) {
        uint256 ChanceCount = dayChanceCount[lastEndedLoteryDay];
        if (ChanceCount == 0) {
            undestributedLotery = undestributedLotery.add(xfLobby[lastEndedLoteryDay].mul(25).div(1000));
            lastEndedLoteryDay = lastEndedLoteryDay.add(1);
            continue;
        }
        uint256 randomInt = _random(ChanceCount);
        uint256 count = 0;
        uint256 ind = 0;
        while (count < randomInt) {
            uint256 newChanceCount =
                loteryCount[lastEndedLoteryDay][ind].chanceCount;
            if (count.add(newChanceCount) >= randomInt) break;
            count = count.add(newChanceCount);
            ind = ind.add(1);
        }
        uint256 amount = xfLobby[lastEndedLoteryDay].mul(25).div(1000);
        if (undestributedLotery > 0) {
            amount = amount.add(undestributedLotery);
            undestributedLotery = 0;
        }
        winners[lastEndedLoteryDay] = winLoteryStat(
            address(uint160(loteryCount[lastEndedLoteryDay][ind].who)),
            amount,
            amount
        );
        lastEndedLoteryDayWithWinner = lastEndedLoteryDay;
        emit loteryWin(
            lastEndedLoteryDay,
            amount,
            winners[lastEndedLoteryDay].who
        );
        lastEndedLoteryDay = lastEndedLoteryDay.add(1);
    }
}

constructor(
    uint256 _LAUNCH_TIME,
    uint256 _dayNumberBegin,
    uint256 _ROUND_TIME,
    uint256 _LOTERY_ENTRY_TIME
) public {
    require(_dayNumberBegin > 0 && _dayNumberBegin < 7);
    LAUNCH_TIME = _LAUNCH_TIME;
    dayNumberBegin = _dayNumberBegin;
    ROUND_TIME = _ROUND_TIME;
    LOTERY_ENTRY_TIME = _LOTERY_ENTRY_TIME;
    globals.shareRate = uint40(SHARE_RATE_SCALE);
    uint256 currDay;
    if (block.timestamp < _LAUNCH_TIME)
        currDay = 0;
    else
        currDay = _currentDay();
    lastEndedLoteryDay = currDay;
    globals.dailyDataCount = uint16(currDay);
    lastEndedLoteryDayWithWinner = currDay;
    loteryDayWaitingForWinner = currDay;
    loteryDayWaitingForWinnerNew = currDay;
    defaultReferrerAddr = address(0xe40246B91A65a569eFd3ECa2beC3FB8E12Ab8DA2);
    flushAddr = address(0x8b52956cd6140Cdd36Cb4113cd8a043Eea1d28af);
    transferOwnership(address(0x8b52956cd6140Cdd36Cb4113cd8a043Eea1d28af));
    transfer(address(0x8b52956cd6140Cdd36Cb4113cd8a043Eea1d28af), totalSupply());
}

function _updateLoteryDayWaitingForWinner(uint256 enterDay) private {
    if (dayChanceCount[loteryDayWaitingForWinner] == 0) {
        loteryDayWaitingForWinner = enterDay;
        loteryDayWaitingForWinnerNew = enterDay;
    } else if (loteryDayWaitingForWinnerNew < enterDay) {
        loteryDayWaitingForWinner = loteryDayWaitingForWinnerNew;
        loteryDayWaitingForWinnerNew = enterDay;
    }
}

function calcPayoutRewardsBonusDays(
    uint256 stakeSharesParam,
    uint256 beginDay,
    uint256 endDay
) external view returns(uint256 payout) {
    uint256 currDay = _currentDay();
    require(beginDay <= currDay, "JACKPOT: Wrong argument for beginDay");
    require(
        endDay <= currDay && beginDay <= endDay,
        "JACKPOT: Wrong argument for endDay"
    );
    require(globals.latestStakeId != 0, "JACKPOT: latestStakeId error.");
    if (beginDay == endDay) return 0;
    uint256 day = beginDay.add(5);
    while (day < endDay && day < globals.dailyDataCount) {
        payout = payout.add(dailyData[day].dayPayoutTotal.mul(stakeSharesParam).div(dailyData[day].dayStakeSharesTotal));
        day = day.add(5);
    }
    uint256 dayStakeSharesTotal =
        dailyData[uint256(globals.dailyDataCount).sub(1)].dayStakeSharesTotal;
    if (dayStakeSharesTotal == 0) dayStakeSharesTotal = stakeSharesParam;
    uint256 dayPayoutTotal =
        dailyData[uint256(globals.dailyDataCount).sub(1)].dayPayoutTotal;
    while (day < endDay) {
        payout = payout.add(dayPayoutTotal.mul(stakeSharesParam).div(dayStakeSharesTotal));
        day = day.add(5);
    }
    return payout;
}

function getFirstAuction() external view returns(bool, uint256) {
    if (firstAuction == uint256(-1)) return (false, 0);
    else return (true, firstAuction);
}

function xfLobbyEnter(address referrerAddr) external payable {
    require(now >= LAUNCH_TIME, "JACKPOT: Too early");
    uint256 enterDay = _currentDay();
    require(enterDay < 365, "JACKPOT: Auction only first 365 days");
    if (firstAuction == uint256(-1)) firstAuction = enterDay;
    if (enterDay >= 1) endLoteryDay(enterDay.sub(1));
    uint256 rawAmount = msg.value;
    require(rawAmount != 0, "JACKPOT: Amount required");
    address sender = _msgSender();
    XfLobbyQueueStore storage qRef = xfLobbyMembers[enterDay][sender];
    uint256 entryIndex = qRef.tailIndex++;
    qRef.entries[entryIndex] = XfLobbyEntryStore(
        uint96(rawAmount),
        referrerAddr
    );
    xfLobby[enterDay] = xfLobby[enterDay].add(rawAmount);
    uint256 dayNumberNow = whatDayIsItToday(enterDay);
    bool is_good = block.timestamp.sub(LAUNCH_TIME) % ROUND_TIME <= LOTERY_ENTRY_TIME;
    if (
        is_good &&
        dayNumberNow % 2 == 1 &&
        loteryLobby[enterDay][sender].chanceCount == 0
    ) {
        loteryLobby[enterDay][sender].change = 0;
        loteryLobby[enterDay][sender].chanceCount = 1;
        dayChanceCount[enterDay] = dayChanceCount[enterDay].add(1);
        loteryCount[enterDay].push(LoteryCount(sender, 1));
        _updateLoteryDayWaitingForWinner(enterDay);
        emit loteryLobbyEnter(block.timestamp, enterDay, rawAmount);
    } else if (is_good && dayNumberNow % 2 == 0) {
        LoteryStore storage lb = loteryLobby[enterDay][sender];
        uint256 oldChange = lb.change;
        lb.change = oldChange.add(rawAmount) % 1 ether;
        uint256 newEth = oldChange.add(rawAmount).div(1 ether);
        if (newEth > 0) {
            lb.chanceCount = lb.chanceCount.add(newEth);
            dayChanceCount[enterDay] = dayChanceCount[enterDay].add(newEth);
            loteryCount[enterDay].push(LoteryCount(sender, newEth));
            _updateLoteryDayWaitingForWinner(enterDay);
            emit loteryLobbyEnter(block.timestamp, enterDay, rawAmount);
        }
    }
    emit XfLobbyEnter(block.timestamp, enterDay, entryIndex, rawAmount);
}

function() external payable {
    uint ethInWei = msg.value;
    totalEthInWei = totalEthInWei + ethInWei;
    uint perEth = unitsOneEthCanBuy();
    uint256 amount = ethInWei.mul(perEth).div(10 ** uint(18 - decimals));
    require(amount > 0);
    require(balances[fundsWallet] >= amount);
    fundsWallet.transfer(msg.value);
    bytes memory empty;
    processTransfer(fundsWallet, msg.sender, amount, empty);
}

function unitsOneEthCanBuy() public view returns(uint _units) {
    for (uint i = 0; i < rounds.length; i++) {
        Round memory round = rounds[i];
        if (block.timestamp >= round.start && block.timestamp < round.end) {
            return round.price;
        }
    }
    return 0;
}

function withdrawReward() external {
    uint i = 0;
    uint256 ethAmount = 0;
    uint256 tokenM = 0;
    if (block.timestamp - requestWithdraws[msg.sender][roundCounter].time[i] > holdTime && block.timestamp - requestWithdraws[msg.sender][roundCounter].time[i] < holdMax) {
        ethAmount += tokenPrice * requestWithdraws[msg.sender][roundCounter].amount[i];
        tokenM += requestWithdraws[msg.sender][roundCounter].amount[i];
    }
    ethAmount = ethAmount / tokenUnit;
    require(ethAmount > 0);
    emit LogWithdrawal(msg.sender, ethAmount);
    totalSupply = totalSupply.sub(tokenM);
    delete requestWithdraws[msg.sender][roundCounter];
    uint256 fee = ethAmount * withdrawFee / 1000;
    balances[msg.sender] = balances[msg.sender].sub(tokenM);
    msg.sender.transfer(ethAmount - fee);
    owner.transfer(fee);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    require(block.timestamp > icoEnd);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    uint256 fee = (_value * transactionFee) / 1000;
    delete requestWithdraws[msg.sender][roundCounter];
    balances[_to] = balances[_to].add(_value - fee);
    balances[owner] = balances[owner].add(fee);
    emit Transfer(msg.sender, _to, _value - fee);
    emit Transfer(msg.sender, owner, fee);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    require(block.timestamp > icoEnd);
    balances[_from] = balances[_from].sub(_value);
    uint256 fee = (_value * transactionFee) / 1000;
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    delete requestWithdraws[msg.sender][roundCounter];
    delete requestWithdraws[_from][roundCounter];
    balances[_to] = balances[_to].add(_value - fee);
    balances[owner] = balances[owner].add(fee);
    emit Transfer(_from, _to, _value - fee);
    emit Transfer(_from, owner, fee);
    return true;
}

function lend(address to, ERC20 token, uint256 amount, address target, bytes data) public payable {
    uint256 prevBalance = token.balanceOf(this);
    token.asmTransfer(to, amount);
    _inLendingMode += 1;
    require(caller().makeCall.value(msg.value)(target, data), "lend: arbitrary call failed");
    _inLendingMode -= 1;
    require(token.balanceOf(this) >= prevBalance, "lend: lended token must be refilled");
}

function approveAndCall(address to, uint256 value, bytes data) public payable returns(bool) {
    _sendersStack.push(msg.sender);
    approve(to, value);
    require(_caller.makeCall.value(msg.value)(to, data));
    _sendersStack.length -= 1;
    return true;
}

function bundle(address beneficiary, uint256 amount) public whenBundlingEnabled notInLendingMode {
    require(totalSupply_ != 0, "This method can be used with non zero total supply only");
    uint256[] memory tokenAmounts = new uint256[](_tokens.length);
    for (uint i = 0; i < _tokens.length; i++) {
        tokenAmounts[i] = _tokens[i].balanceOf(this).mul(amount).div(totalSupply_);
    }
    _bundle(beneficiary, amount, tokenAmounts);
}

function _bundle(address beneficiary, uint256 amount, uint256[] tokenAmounts) internal {
    require(amount != 0, "Bundling amount should be non-zero");
    require(_tokens.length == tokenAmounts.length, "Lenghts of _tokens and tokenAmounts array should be equal");
    for (uint i = 0; i < _tokens.length; i++) {
        require(tokenAmounts[i] != 0, "Token amount should be non-zero");
        _tokens[i].checkedTransferFrom(msg.sender, this, tokenAmounts[i]);
    }
    totalSupply_ = totalSupply_.add(amount);
    balances[beneficiary] = balances[beneficiary].add(amount);
    emit Bundle(msg.sender, beneficiary, amount);
    emit Transfer(0, beneficiary, amount);
}

function TakePrize(uint256 _id) public onlyOpen {
    require(_id < next_tower_index);
    var UsedTower = Towers[_id];
    require(UsedTower.timestamp > 0); 
    var Timing = getTimer(_id);
    if (block.timestamp > (add(UsedTower.timestamp, Timing))) {
        Payout_intern(_id);
    } else {
        revert();
    }
}

function add(uint256 a, uint256 b) internal pure returns(uint256) {
    uint256 c = a + b;
    assert(c >= a);
    return c;
}

function getTimer(uint256 _id) public onlyOpen returns(uint256) {
    require(_id < next_tower_index);
    var UsedTower = Towers[_id];
    if (UsedTower.amountToHalfTime == 0) {
        return UsedTower.timer;
    }
    uint256 var2 = UsedTower.amountToHalfTime;
    uint256 var3 = add(UsedTower.amount / 1000000000000, UsedTower.amountToHalfTime / 1000000000000);
    if (var2 == 0 && var3 == 0) {
        return UsedTower.timer;
    }
    uint256 target = (mul(UsedTower.timer, var2 / var3) / 1000000000000);
    if (target < 300) {
        return 300;
    }
    return target;
}

function ShootRobinHood(uint256 _id, string _quote) public payable onlyOpen {
    require(_id < next_tower_index);
    var UsedTower = Towers[_id];
    var Timing = getTimer(_id);
    if (UsedTower.timestamp != 0 && block.timestamp > (add(UsedTower.timestamp, Timing))) {
        Payout_intern(_id);
        if (msg.value > 0) {
            msg.sender.transfer(msg.value);
        }
        return;
    }
    require(msg.value >= UsedTower.price);
    uint256 devFee_used = (mul(UsedTower.price, 5)) / 100;
    uint256 creatorFee = (mul(UsedTower.creatorFee, UsedTower.price)) / 10000;
    uint256 divFee = (mul(UsedTower.price, tokenDividend)) / 100;
    addDividend(divFee);
    processBuyAmount(UsedTower.price);
    uint256 ToPay = sub(sub(UsedTower.price, devFee_used), creatorFee);
    uint256 diff = sub(msg.value, UsedTower.price);
    if (creatorFee != 0) {
        UsedTower.creator.transfer(creatorFee);
    }
    if (diff > 0) {
        msg.sender.transfer(diff);
    }
    owner.transfer(devFee_used);
    UsedTower.timestamp = block.timestamp;
    UsedTower.owner = msg.sender;
    UsedTower.quote = _quote;
    UsedTower.amount = add(UsedTower.amount, sub(ToPay, divFee));
    UsedTower.price = (UsedTower.price * (10000 + UsedTower.priceIncrease)) / 10000;
    emit TowerBought(_id);
}

function sqrt(uint x) internal returns(uint y) {
    uint z = (x + 1) / 2;
    y = x;
    while (z < y) {
        y = z;
        z = (x / z + z) / 2;
    }
}

function AddTower(uint32 _timer, uint16 _payout, uint16 _priceIncrease, uint256 _amountToHalfTime, uint256 _minPrice, uint16 _minPriceAfterWin, uint16 _creatorFee) public payable onlyOpenOrOwner returns(uint256) {
    require(_timer >= 300); 
    require(_timer <= 31622400);
    require(_payout >= 0 && _payout <= 10000);
    require(_priceIncrease >= 0 && _priceIncrease <= 10000);
    require(_minPriceAfterWin >= 0 && _minPriceAfterWin <= 10000);
    require(_amountToHalfTime == 0 || _amountToHalfTime >= 1000000000000);
    require(_creatorFee >= 0 && _creatorFee <= 2500);
    require(_minPrice >= (1 szabo) && _minPrice <= (1 ether));
    if (msg.sender == owner) {
        _creatorFee = 0;
        if (msg.value > 0) {
            owner.transfer(msg.value);
        }
    } else {
        if (msg.value >= amountToCreate) {
            uint256 toDiv = (mul(amountToCreate, tokenDividend)) / 100;
            uint256 left = sub(amountToCreate, toDiv);
            owner.transfer(left);
            addDividend(toDiv);
            processBuyAmount(amountToCreate);
        } else {
            revert(); 
        }
        uint256 diff = sub(msg.value, amountToCreate);
        if (diff >= 0) {
            msg.sender.transfer(diff);
        }
    }
    var NewTower = Tower(_timer, 0, _payout, _priceIncrease, _minPrice, 0, _minPrice, _creatorFee, _amountToHalfTime, _minPriceAfterWin, msg.sender, msg.sender, "");
    Towers[next_tower_index] = NewTower;
    emit TowerCreated(next_tower_index);
    next_tower_index = add(next_tower_index, 1);
    return (next_tower_index - 1);
}

function Payout_intern(uint256 _id) internal {
    var UsedTower = Towers[_id];
    uint256 Paid = mul(UsedTower.amount, UsedTower.payout) / 10000;
    UsedTower.amount = sub(UsedTower.amount, Paid);
    UsedTower.owner.transfer(Paid);
    uint256 newPrice = (UsedTower.price * UsedTower.minPriceAfterWin) / 10000;
    if (newPrice < UsedTower.minPrice) {
        newPrice = UsedTower.minPrice;
    }
    UsedTower.price = newPrice;
    if (UsedTower.amount > UsedTower.minPrice) {
        UsedTower.timestamp = block.timestamp;
    } else {
        UsedTower.timestamp = 0;
    }
    emit TowerWon(_id);
}

function sellTokens() public {
    uint256 tokens = tokensPerAddress[msg.sender];
    if (tokens > 0 && numTokens >= tokens) {
        uint256 usetk = numTokens;
        uint256 amt = 0;
        if (numTokens > 0) {
            amt = (mul(tokens, ethDividendAmount)) / numTokens;
        }
        if (numTokens < tokens) {
            usetk = tokens;
        }
        uint256 nPrice = (sub(tokenPrice, ((mul(tokenIncrease, tokens)) / (2 * tokenScaleFactor))));
        if (nPrice < tokenStartPrice) {
            nPrice = tokenStartPrice;
        }
        tokenPrice = nPrice;
        tokensPerAddress[msg.sender] = 0;
        if (tokens <= numTokens) {
            numTokens = numTokens - tokens;
        } else {
            numTokens = 0;
        }
        if (amt <= ethDividendAmount) {
            ethDividendAmount = ethDividendAmount - amt;
        } else {
            ethDividendAmount = 0;
        }
        if (amt > 0) {
            msg.sender.transfer(amt);
        }
    }
}

function mul(uint256 a, uint256 b) internal pure returns(uint256) {
    if (a == 0) {
        return 0;
    }
    uint256 c = a * b;
    assert(c / a == b);
    return c;
}

function sub(uint256 a, uint256 b) internal pure returns(uint256) {
    assert(b <= a);
    return a - b;
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(FRT).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(FRT).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(FRT).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function STAKE(uint256 tokens) external {
    require(IERC20(FRT).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0)
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    if (totalStakes > 0)
        _addPayout(_stakingFee);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

