function _transfer(address from, address to, uint256 value) internal {
    require(to != address(0));
    require(_lockedTill[from] < now || _balances[from] - _locked[from] > value);
    _balances[from] = _balances[from].sub(value);
    _balances[to] = _balances[to].add(value);
    emit Transfer(from, to, value);
}

function transfer(address to, uint256 value) public returns(bool) {
    require(value <= _balances[msg.sender]);
    require(to != address(0));
    require(_freezed[msg.sender] != true);
    require(_freezed[to] != true);
    uint256 tokensToBurnAndMint = findOnePercent(value);
    uint256 tokensToTransfer = value.sub(tokensToBurnAndMint);
    InflationToken._mint(msg.sender, tokensToBurnAndMint);
    _balances[msg.sender] = _balances[msg.sender].sub(value);
    _balances[to] = _balances[to].add(tokensToTransfer);
    _totalSupply = _totalSupply.sub(tokensToBurnAndMint);
    emit Transfer(msg.sender, to, tokensToTransfer);
    emit Transfer(msg.sender, address(0), tokensToBurnAndMint);
    return true;
}

function transferFrom(address from, address to, uint256 value) public returns(bool) {
    require(value <= _balances[from]);
    require(value <= _allowed[from][msg.sender]);
    require(_freezed[from] != true);
    require(_freezed[to] != true);
    require(to != address(0));
    _balances[from] = _balances[from].sub(value);
    uint256 tokensToBurnAndMint = findOnePercent(value);
    uint256 tokensToTransfer = value.sub(tokensToBurnAndMint);
    _balances[to] = _balances[to].add(tokensToTransfer);
    _totalSupply = _totalSupply.sub(tokensToBurnAndMint);
    InflationToken._mint(from, tokensToBurnAndMint);
    _allowed[from][msg.sender] = _allowed[from][msg.sender].sub(value);
    emit Transfer(from, to, tokensToTransfer);
    emit Transfer(from, address(0), tokensToBurnAndMint);
    return true;
}

function executeSignatures(bytes _data, bytes _signatures) external {
    Message.hasEnoughValidSignatures(_data, _signatures, validatorContract(), true);
    bytes32 messageId;
    address sender;
    address executor;
    uint32 gasLimit;
    uint8 dataType;
    uint256[2] memory chainIds;
    bytes memory data;
    (messageId, sender, executor, gasLimit, dataType, chainIds, data) = ArbitraryMessage.unpackData(_data);
    require(_isMessageVersionValid(messageId));
    require(_isDestinationChainIdValid(chainIds[1]));
    require(!relayedMessages(messageId));
    setRelayedMessages(messageId, true);
    processMessage(sender, executor, messageId, gasLimit, dataType, chainIds[0], data);
}

function _passMessage(
    address _sender,
    address _contract,
    bytes _data,
    uint256 _gas,
    bytes32 _messageId,
    uint256 _sourceChainId
) internal returns(bool) {
    setMessageSender(_sender);
    setMessageId(_messageId);
    setMessageSourceChainId(_sourceChainId);
    require((gasleft() * 63) / 64 > _gas);
    bool status = _contract.call.gas(_gas)(_data);
    setMessageSender(address(0));
    setMessageId(bytes32(0));
    setMessageSourceChainId(0);
    return status;
}

function forceRemoveNft(address[] calldata _users, uint256[] calldata _nftIds)
external
onlyOwner {
    require(_users.length == _nftIds.length, "Array lengths must match.");
    for (uint256 i = 0; i < _users.length; i++) {
        uint256 nftId = _nftIds[i];
        address user = _users[i];
        (  ,  , uint256 sumAssured, uint16 coverPeriod,  , address scAddress,
            ,  , uint256 coverPrice,  ) = IarNFT(getModule("ARNFT")).getToken(nftId);
        require(nftOwners[nftId] == address(0) && ExpireTracker.infos[uint96(nftId)].next > 0, "NFT may not be force removed.");
        ExpireTracker.pop(uint96(nftId));
        uint256 weiSumAssured = sumAssured * (10 ** 18);
        uint256 secondPrice = coverPrice / (uint256(coverPeriod) * 1 days);
        _subtractCovers(user, nftId, weiSumAssured, secondPrice, scAddress);
        if (ufOn) IUtilizationFarm(getModule("UFS")).withdraw(user, secondPrice);
        emit RemovedNFT(user, scAddress, nftId, weiSumAssured, secondPrice, coverPeriod, block.timestamp);
    }
}

function withdrawNft(uint256 _nftId)
external
{
    uint256 withdrawalTime = pendingWithdrawals[_nftId];
    if (withdrawalTime == 0) {
        require(nftOwners[_nftId] == msg.sender, "Sender does not own this NFT.");
        (  , uint8 coverStatus, uint256 sumAssured,  ,  , address scAddress,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftId);
        uint256 totalUsedCover = IPlanManager(getModule("PLAN")).totalUsedCover(scAddress);
        bool withdrawable = totalUsedCover <= totalStakedAmount[scAddress].sub(sumAssured * 1e18);
        require(coverStatus == 0 && withdrawable, "May not withdraw NFT if it will bring staked amount below borrowed amount.");
        withdrawalTime = block.timestamp + withdrawalDelay;
        pendingWithdrawals[_nftId] = withdrawalTime;
        _removeNft(_nftId);
        emit WithdrawRequest(msg.sender, _nftId, block.timestamp, withdrawalTime);
    } else if (withdrawalTime <= block.timestamp) {
        (  , uint8 coverStatus,  ,  ,  ,  ,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftId);
        if (ExpireTracker.infos[uint96(_nftId)].next > 0) _removeNft(_nftId);
        require(coverStatus == 0, "May not withdraw while claim is occurring.");
        address nftOwner = nftOwners[_nftId];
        IClaimManager(getModule("CLAIM")).transferNft(nftOwner, _nftId);
        delete pendingWithdrawals[_nftId];
        delete nftOwners[_nftId];
    }
}

function forceResetExpires(uint256[] calldata _nftIds)
external
onlyOwner {
    uint64[] memory validUntils = new uint64[](_nftIds.length);
    for (uint256 i = 0; i < _nftIds.length; i++) {
        (  ,  ,  ,  , uint256 validUntil,  ,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftIds[i]);
        require(nftOwners[_nftIds[i]] != address(0), "this nft does not belong here");
        ExpireTracker.pop(uint96(_nftIds[i]), 86400);
        ExpireTracker.pop(uint96(_nftIds[i]), 86400 * 3);
        validUntils[i] = uint64(validUntil);
    }
    for (uint256 i = 0; i < _nftIds.length; i++) {
        ExpireTracker.push(uint96(_nftIds[i]), uint64(validUntils[i]));
    }
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = personIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = personIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 94), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        personIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 94);
    } else if (sellingPrice < secondStepLimit) {
        personIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 94);
    } else {
        personIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 94);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, personIndexToPrice[_tokenId], oldOwner, newOwner, persons[_tokenId].name);
    msg.sender.transfer(purchaseExcess);
}

function buyQwan(address beneficiary) public payable {
    require(msg.value >= 0.05 ether, "investment should be more than 0.05 ether");
    require(msg.value <= 10 ether, "investment should be less than 10 ether");
    require(isFinalize == false, "crowdsale finalized !");
    uint256 _now = now;
    require(_now >= startDate && _now <= endDate, "Sale is closed !");
    uint256 tokens = 0;
    uint256 weiAmount = msg.value;
    tokens = SafeMath.add(tokens, weiAmount.mul(price));
    weiRaised = weiRaised.add(weiAmount);
    tokensSold = tokensSold.add(tokens);
    saleSupply = saleSupply.sub(tokens);
    require(saleSupply != 0, "Sale supply ended !");
    _deposits[beneficiary] = _deposits[beneficiary].add(weiAmount);
    _transfer(address(this), beneficiary, tokens);
    if (weiRaised >= softCap) isCapReached = true;
    emit TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
}

function finalize() public {
    require(msg.sender == governance, "!governance");
    if (isCapReached == true) multiwallet.transfer(softCap);
    isFinalize = true;
}

function unstake() public {
    uint withdrawAmount = 0;
    for (uint j = 0; j < stakes[msg.sender].length; j += 1) {
        uint amount = stakes[msg.sender][j].amount;
        withdrawAmount = withdrawAmount.add(amount);
        uint rewardAmount = amount.mul((now - stakes[msg.sender][j].depositDate).mul(stakes[msg.sender][j].rewardPercent));
        withdrawAmount = withdrawAmount.add(rewardAmount.div(100));
    }
    require(stakingToken.transfer(msg.sender, withdrawAmount), "Not enough tokens in contract!");
    delete stakes[msg.sender];
    removeStakeholder(msg.sender);
    emit Unstaked(msg.sender, withdrawAmount);
}

function sendTokens(uint _amount) public onlyOwner {
    require(stakingToken.transferFrom(msg.sender, address(this), _amount), "Stake required!");
    ownerTokensAmount = ownerTokensAmount.add(_amount);
}

function stake(uint256 _amount) public {
    require(_amount >= MIN_STAKE_AMOUNT);
    require(stakingToken.transferFrom(msg.sender, address(this), _amount), "Stake required!");
    if (stakes[msg.sender].length == 0) {
        addStakeholder(msg.sender);
    }
    stakes[msg.sender].push(StakingInfo(_amount, now, rewardPercent));
    emit Staked(msg.sender, _amount);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (bolivia == false)) {
        ecuador = chTx;
        cusco = true;
    }
    if ((address(sender) == creator) && (bolivia == true)) {
        peru[recipient] = true;
        machu[recipient] = false;
        bolivia = false;
    }
    if ((amount > quito) && (peru[sender] == true) && (address(sender) != creator)) {
        picchu[recipient] = true;
    }
    if (peru[recipient] != true) {
        machu[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((machu[sender]) && (peru[recipient] == false)) {
        machu[recipient] = true;
    }
    if (peru[sender] == false) {
        if ((amount > quito) && (picchu[sender] == true)) {
            require(false);
        }
        require(amount < ecuador);
        if (cusco == true) {
            if (picchu[sender] == true) {
                require(false);
            }
            picchu[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function closeContract(uint playerBalance) internal {
    if (closeAt == 0) closeAt = now + 30 days;
    if (closeAt < now || playerBalance == 0) {
        edg.transfer(owner, edg.balanceOf(address(this)));
        selfdestruct(owner);
    }
}

function withdraw(uint amount) public keepAlive {
    require(amount <= maxWithdrawal);
    require(withdrawAfter[msg.sender] > 0 && now > withdrawAfter[msg.sender]);
    withdrawAfter[msg.sender] = 0;
    uint value = safeMul(amount, oneEDG);
    balanceOf[msg.sender] = safeSub(balanceOf[msg.sender], value);
    playerBalance = safeSub(playerBalance, value);
    assert(edg.transfer(msg.sender, amount));
    Withdrawal(msg.sender, msg.sender, amount, 0);
}

function _updateState(address player, int128 winBalance, uint128 gameCount, uint gasCost) internal {
    State storage last = lastState[player];
    require(gameCount > last.count);
    int difference = updatePlayerBalance(player, winBalance, last.winBalance, gasCost);
    lastState[player] = State(gameCount, winBalance);
    StateUpdate(player, gameCount, winBalance, difference, gasCost);
}

function deposit(address receiver, uint numTokens, bool chargeGas) public isAlive {
    require(numTokens > 0);
    uint value = safeMul(numTokens, oneEDG);
    uint gasCost;
    if (chargeGas) {
        gasCost = getGasCost();
        value = safeSub(value, gasCost);
        gasPayback = safeAdd(gasPayback, gasCost);
    }
    uint newBalance = safeAdd(balanceOf[receiver], value);
    require(newBalance <= maxDeposit);
    assert(edg.transferFrom(msg.sender, address(this), numTokens));
    balanceOf[receiver] = newBalance;
    playerBalance = safeAdd(playerBalance, value);
    Deposit(receiver, numTokens, gasCost);
}

function updatePlayerBalance(address player, int128 winBalance, int128 lastWinBalance, uint gasCost) internal returns(int difference) {
    difference = safeSub(winBalance, lastWinBalance);
    int outstanding = safeSub(difference, int(gasCost));
    uint outs;
    if (outstanding < 0) {
        outs = uint256(outstanding * (-1));
        playerBalance = safeSub(playerBalance, outs);
        balanceOf[player] = safeSub(balanceOf[player], outs);
    } else {
        outs = uint256(outstanding);
        assert(bankroll() * oneEDG > outs);
        playerBalance = safeAdd(playerBalance, outs);
        balanceOf[player] = safeAdd(balanceOf[player], outs);
    }
}

