function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        _swapTokensForETH(swapAtAmount);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchDeadBlock + 5 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(txFees).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function withdraw() external {
    User storage user = users[msg.sender];
    uint256 userPercentRate = getUserPerc(msg.sender);
    uint256 totalAmount;
    uint256 dividends;
    for (uint256 i = 0; i < user.deposits.length; i++) {
        if (user.deposits[i].withdrawn < user.deposits[i].amount.mul(MAX_TRIG).div(100)) {
            if (user.deposits[i].start > user.checkpoint) {
                dividends = (user.deposits[i].amount.mul(userPercentRate).div(PERCENTS_DIVIDER))
                    .mul(block.timestamp.sub(user.deposits[i].start))
                    .div(TIME_STEP);
            } else {
                dividends = (user.deposits[i].amount.mul(userPercentRate).div(PERCENTS_DIVIDER))
                    .mul(block.timestamp.sub(user.checkpoint))
                    .div(TIME_STEP);
            }
            if (user.deposits[i].withdrawn.add(dividends) > user.deposits[i].amount.mul(MAX_TRIG).div(100)) {
                dividends = (user.deposits[i].amount.mul(MAX_TRIG).div(100)).sub(user.deposits[i].withdrawn);
            }
            user.deposits[i].withdrawn = user.deposits[i].withdrawn.add(dividends); 
            totalAmount = totalAmount.add(dividends);
        }
    }
    uint256 referralBonus = getUserReferralBonus(msg.sender);
    if (referralBonus > 0) {
        totalAmount = totalAmount.add(referralBonus);
        user.bonus = 0;
    }
    require(totalAmount > 0, "User has no dividends");
    user.checkpoint = block.timestamp;
    MoondayToken.mint(msg.sender, totalAmount);
    totalWithdrawn = totalWithdrawn.add(totalAmount);
    emit Withdrawn(msg.sender, totalAmount);
}

