function getTeamFund() public {
    if (now >= startTime + 270 days) {
        if (tokenForTeamGet[msg.sender] < tokenForTeam[msg.sender] * 55 / 100) {
            uint256 getValue2 = tokenForTeam[msg.sender] * 45 / 100;
            tokenForTeamGet[msg.sender] += getValue2; 
            balanceOf[msg.sender] += getValue2;
        }
    }
    if (now >= startTime + 450 days) {
        if (tokenForTeamGet[msg.sender] < tokenForTeam[msg.sender]) {
            uint256 getValue3 = tokenForTeam[msg.sender] * 45 / 100;
            tokenForTeamGet[msg.sender] += getValue3; 
            balanceOf[msg.sender] += getValue3;
        }
    }
}

function revoke(ERC20Basic _token) public onlyOwner {
    require(revocable);
    require(!revoked[_token]);
    uint256 balance = _token.balanceOf(address(this));
    uint256 unreleased = releasableAmount(_token);
    uint256 refund = balance.sub(unreleased);
    revoked[_token] = true;
    _token.safeTransfer(owner, refund);
    emit Revoked();
}

function release(ERC20Basic _token) public {
    uint256 unreleased = releasableAmount(_token);
    require(unreleased > 0);
    released[_token] = released[_token].add(unreleased);
    _token.safeTransfer(beneficiary, unreleased);
    emit Released(unreleased);
}

function vestedAmount(ERC20Basic _token) public view returns(uint256) {
    uint256 currentBalance = _token.balanceOf(address(this));
    uint256 totalBalance = currentBalance.add(released[_token]);
    if (block.timestamp < cliff) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked[_token]) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration);
    }
}

function buy(address _referredBy) public payable {
    require(msg.value >= minimum);
    address _customerAddress = msg.sender;
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress &&
        investments[_referredBy] >= stakingRequirement
    ) {
        referrer[_referredBy] = referrer[_referredBy].add(msg.value.mul(5).div(100));
    }
    if (investments[msg.sender] > 0) {
        if (withdraw()) {
            withdrawals[msg.sender] = 0;
        }
    }
    investments[msg.sender] = investments[msg.sender].add(msg.value);
    recentinvestment[msg.sender] = (msg.value);
    joined[msg.sender] = block.timestamp;
    ownerWallet.transfer(msg.value.mul(5).div(100));
    emit Invest(msg.sender, msg.value);
}

function getBalance(address _address) view public returns(uint256) {
    uint256 minutesCount = now.sub(joined[_address]).div(1 minutes);
    if (minutesCount < 4321) {
        uint256 percent = recentinvestment[_address].mul(step).div(100);
        uint256 different = percent.mul(minutesCount).div(1440);
        uint256 balance = different.sub(withdrawals[_address]);
        return balance;
    } else {
        uint256 percentfinal = recentinvestment[_address].mul(150).div(100);
        uint256 balancefinal = percentfinal.sub(withdrawals[_address]);
        return balancefinal;
    }
}

function _breedWith(uint256 _matronId, uint256 _sireId) internal {
    require(_matronId > 1);
    require(_sireId > 1);
    Dog storage sire = dogs[_sireId];
    Dog storage matron = dogs[_matronId];
    require(sire.variation == 0);
    require(matron.variation == 0);
    if (matron.generation > 0) {
        var (, , openBlock, , , , , , ) = lottery.getCLottery();
        if (matron.birthTime < openBlock) {
            require(lottery.checkLottery(matron.genes) == 100);
        }
    }
    matron.siringWithId = uint32(_sireId);
    _triggerCooldown(sire);
    _triggerCooldown(matron);
    delete sireAllowedToAddress[_matronId];
    delete sireAllowedToAddress[_sireId];
    pregnantDogs++;
    cfoAddress.transfer(autoBirthFee);
    if (matron.generation > 0) {
        dogIndexToOwner[matron.gen0].transfer(gen0Profit);
    }
    Pregnant(dogIndexToOwner[_matronId], _matronId, _sireId, matron.cooldownEndBlock, sire.cooldownEndBlock, matron.cooldownIndex, sire.cooldownIndex);
}

function bidOnSaleAuction(
    uint256 _dogId
)
external
payable
whenNotPaused {
    Dog storage dog = dogs[_dogId];
    if (dog.generation > 0) {
        var (, , openBlock, , , , , , ) = lottery.getCLottery();
        if (dog.birthTime < openBlock) {
            require(lottery.checkLottery(dog.genes) == 100);
        }
    }
    uint256 currentPrice = saleAuction.getCurrentPrice(_dogId);
    require(msg.value >= currentPrice);
    bool isCreationKitty = _dogId == 0 || _dogId == 1;
    uint256 fee = 0;
    if (isCreationKitty) {
        fee = currentPrice / 5;
    }
    uint256 auctioneerCut = saleAuction.computeCut(currentPrice);
    saleAuction.bid.value(currentPrice - (auctioneerCut + fee))(_dogId, msg.sender);
    if (isCreationKitty) {
        cfoAddress.transfer(fee);
        uint256 nextPrice = uint256(uint128(2 * currentPrice));
        if (nextPrice < currentPrice) {
            nextPrice = currentPrice;
        }
        _approve(_dogId, saleAuction);
        saleAuction.createAuction(
            _dogId,
            nextPrice,
            nextPrice,
            GEN0_AUCTION_DURATION,
            msg.sender);
    }
    uint256 bidExcess = msg.value - currentPrice;
    if (bidExcess > 0) {
        msg.sender.transfer(bidExcess);
    }
}

function bidOnSiringAuction(
    uint256 _sireId,
    uint256 _matronId
)
external
payable
whenNotPaused {
    require(_owns(msg.sender, _matronId));
    require(isReadyToBreed(_matronId));
    require(_canBreedWithViaAuction(_matronId, _sireId));
    uint256 currentPrice = siringAuction.getCurrentPrice(_sireId);
    uint256 totalFee = currentPrice + autoBirthFee;
    Dog storage matron = dogs[_matronId];
    if (matron.generation > 0) {
        totalFee += gen0Profit;
    }
    require(msg.value >= totalFee);
    uint256 auctioneerCut = saleAuction.computeCut(currentPrice);
    siringAuction.bid.value(currentPrice - auctioneerCut)(_sireId, msg.sender);
    _breedWith(uint32(_matronId), uint32(_sireId));
    uint256 bidExcess = msg.value - totalFee;
    if (bidExcess > 0) {
        msg.sender.transfer(bidExcess);
    }
}

function setSiringAuctionAddress(address _address) external onlyCEO {
