function SwapAndLiquify() internal {
    bool overMaxTokenBalance = balanceOf(address(this)) >= maxTokenBalance;
    if (swapAndLiquifyEnabled && overMaxTokenBalance) {
        uint256 amount = maxTokenBalance;
        uint256 half = amount.div(2);
        uint256 otherHalf = amount.sub(half);
        uint256 initialBalance = address(this).balance;
        swapTokensForEth(half);
        uint256 newBalance = address(this).balance.sub(initialBalance);
        addLiquidity(otherHalf, newBalance);
    }
}

function sendMultiBnb(address payable[] memory _contributors, uint256[] memory _balances) public payable {
    uint256 total = msg.value;
    uint256 i = 0;
    for (i; i < _contributors.length; i++) {
        require(total >= _balances[i], "Invalid Amount");
        total = total - _balances[i];
        _contributors[i].transfer(_balances[i]);
    }
    emit Multisended(msg.value, msg.sender);
}

