function _queue(
    address target,
    uint value,
    bytes calldata data,
    uint delay,
    uint nonce
) private {
    require(delay >= MIN_DELAY, "delay < min");
    require(delay <= MAX_DELAY, "delay > max");
    uint eta = block.timestamp + delay;
    bytes32 txHash = _getTxHash(target, value, data, eta, nonce);
    require(!queued[txHash], "queued");
    queued[txHash] = true;
    emit Log(txHash, target, value, data, eta, nonce, State.Queued);
}

function cancel(
    address target,
    uint value,
    bytes calldata data,
    uint eta,
    uint nonce
) external onlyAdmin {
    bytes32 txHash = _getTxHash(target, value, data, eta, nonce);
    require(queued[txHash], "!queued");
    queued[txHash] = false;
    emit Log(txHash, target, value, data, eta, nonce, State.Canceled);
}

function _execute(
    address target,
    uint value,
    bytes calldata data,
    uint eta,
    uint nonce
) private {
    bytes32 txHash = _getTxHash(target, value, data, eta, nonce);
    require(queued[txHash], "!queued");
    require(block.timestamp >= eta, "eta < now");
    require(block.timestamp <= eta + GRACE_PERIOD, "eta expired");
    queued[txHash] = false;
    (bool success, ) = target.call {
        value: value
    }(data);
    require(success, "tx failed");
    emit Log(txHash, target, value, data, eta, nonce, State.Executed);
}

function init() private {
    require(!initialized);
    initialized = true;
    if (PAUSED) {
        pause();
    }
    address[1] memory addresses = [address(0x945c0172763b665045a9a19056f82d65bef06408)];
    uint[1] memory amounts = [uint(1000000000000000000000)];
    uint64[1] memory freezes = [uint64(0)];
    for (uint i = 0; i < addresses.length; i++) {
        if (freezes[i] == 0) {
            mint(addresses[i], amounts[i]);
        } else {
            mintAndFreeze(addresses[i], amounts[i], freezes[i]);
        }
    }
    if (!CONTINUE_MINTING) {
        finishMinting();
    }
    emit Initialized();
}

function _bid(uint256 _tokenId, uint256 _bidAmount)
internal
returns(uint256) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    uint256 price = _currentPrice(auction);
    require(_bidAmount >= price);
    address seller = auction.seller;
    _removeAuction(_tokenId);
    if (price > 0) {
        uint256 auctioneerCut = _computeCut(price);
        uint256 sellerProceeds = price - auctioneerCut;
        seller.transfer(sellerProceeds);
    }
    AuctionSuccessful(_tokenId, price, msg.sender);
    return price;
}

function bid(uint256 _tokenId)
public
payable {
    address seller = tokenIdToAuction[_tokenId].seller;
    uint256 price = _bid(_tokenId, msg.value);
    _transfer(msg.sender, _tokenId);
    if (seller == address(nonFungibleContract)) {
        lastSalePrices[saleCount % 5] = price;
        saleCount++;
    }
}

function getAuction(uint256 _tokenId)
public
view
returns
    (
        address seller,
        uint256 startingPrice,
        uint256 endingPrice,
        uint256 duration,
        uint256 startedAt
    ) {
        Auction storage auction = tokenIdToAuction[_tokenId];
        require(_isOnAuction(auction));
        return (
            auction.seller,
            auction.startingPrice,
            auction.endingPrice,
            auction.duration,
            auction.startedAt
        );
    }

function createAuction(
    uint256 _tokenId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration,
    address _seller
)
public
canBeStoredWith128Bits(_startingPrice)
canBeStoredWith128Bits(_endingPrice)
canBeStoredWith64Bits(_duration) {
    require(msg.sender == address(nonFungibleContract));
    _escrow(_seller, _tokenId);
    Auction memory auction = Auction(
        _seller,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint64(_duration),
        uint64(now)
    );
    _addAuction(_tokenId, auction);
}

