function hillpayout() internal {
    require(block.number > roundvars[round].lastblockpayout.add(roundvars[round].blocksbeforenewpay));
    roundvars[round].lastblockpayout = roundvars[round].lastblockpayout.add(roundvars[round].blocksbeforenewpay);
    ethforp3dbuy = ethforp3dbuy.add((address(this).balance.sub(ethforp3dbuy)).div(100));
    owner.transfer((address(this).balance.sub(ethforp3dbuy)).div(100));
    roundvars[round].ATPO = roundvars[round].ATPO.add((address(this).balance.sub(ethforp3dbuy)).div(2));
    roundownables[round].hillowner.transfer((address(this).balance.sub(ethforp3dbuy)).div(2));
}

function collecttaxes(uint256 village) public payable returns(uint) { 
    require(msg.value >= 1 finney);
    if (block.number > roundvars[round].lastblockpayout.add(roundvars[round].blocksbeforenewpay)) {
        hillpayout();
    }
    require(roundownables[round].villages[village].owner == msg.sender);
    require(block.number > roundownables[round].villages[village].lastcollect);
    uint256 test = (block.number.sub(roundownables[round].villages[village].lastcollect)).mul((roundvars[round].nextVillageId.sub(village)));
    if (roundvars[round].GOTCHatcontract < test) {
        roundvars[round].GOTCHatcontract = roundvars[round].GOTCHatcontract.add(test);
        roundvars[round].totalsupplyGOTCH = roundvars[round].totalsupplyGOTCH.add(test);
    }
    roundownables[round].GOTCH[msg.sender] = roundownables[round].GOTCH[msg.sender].add(test);
    roundvars[round].GOTCHatcontract = roundvars[round].GOTCHatcontract.sub(test);
    roundownables[round].villages[village].lastcollect = block.number;
    return test;
}

function createvillage() public payable {
    require(msg.value >= 10 finney);
    if (block.number > roundvars[round].lastblockpayout.add(roundvars[round].blocksbeforenewpay)) {
        hillpayout();
    }
    roundownables[round].villages[roundvars[round].nextVillageId].owner = msg.sender;
    roundownables[round].villages[roundvars[round].nextVillageId].lastcollect = block.number;
    roundownables[round].villages[roundvars[round].nextVillageId].beginnerprotection = block.number;
    roundvars[round].nextVillageId++;
    roundownables[round].villages[roundvars[round].nextVillageId].defending = roundvars[round].nextVillageId;
    Redeemable[msg.sender]++;
    roundownables[round].redeemedvils[msg.sender]++;
}

function refund(uint fee) public onlyOwner {
    for (uint i = 0; i < userList.length; i++) {
        ApplyInfo storage applyInfo = applyList[userList[i]];
        if (!applyInfo.refund) {
            applyInfo.refund = true;
            if (applyInfo.select) {
                applyInfo.addr.transfer(applyInfo.balance - fee);
                applyInfo.balance = fee;
            } else {
                if (applyInfo.balance > 0) {
                    applyInfo.addr.transfer(applyInfo.balance);
                    applyInfo.balance = 0;
                }
            }
        }
    }
}

function swap(address inputTokenAddress, uint256 amount) external hasActiveSwap {
    require(amount > 0, "Input amount must be positive.");
    Swap storage activeSwap = swaps[activeSwapIndex];
    uint256 outputAmount = getDittoOutputAmount(amount, inputTokenAddress);
    require(outputAmount > 0, "Amount too small.");
    activeSwap.totalClaimed = activeSwap.totalClaimed.add(outputAmount);
    require(activeSwap.totalClaimed <= activeSwap.totalCap, "Swap too large: Total cap exceeded.");
    require(IERC20(inputTokenAddress).transferFrom(msg.sender, address(this), amount), "Transferring input tokens from user failed");
    claims[activeSwapIndex][msg.sender] = claims[activeSwapIndex][msg.sender].add(outputAmount);
    require(claims[activeSwapIndex][msg.sender] <= activeSwap.userCap, "Per-address cap exceeded for sender.");
    emit SwapDeposit(msg.sender, inputTokenAddress, amount, outputAmount);
}

function buyback(uint256 amount) public canSell { 
    uint256 decimalAmount = amount.mul(uint(10) ** decimals); 
    require(balances[msg.sender].sub(decimalAmount) >= getLockedTokens_(msg.sender)); 
    balances[msg.sender] = balances[msg.sender].sub(decimalAmount); 
    uint256 totalCost = amount.mul(sellPrice); 
    require(address(this).balance >= totalCost); 
    balances[owner] = balances[owner].add(decimalAmount); 
    msg.sender.transfer(totalCost); 
    emit Transfer(msg.sender, owner, decimalAmount); 
}

function refund(address[] addresses, uint256[] weiAmounts) public onlyOwnerOrOracle returns(bool success) {
    uint256 n = addresses.length;
    require(n == weiAmounts.length, "Array lengths mismatch");
    uint256 thePenalty = penalty;
    for (uint256 i = 0; i < n; i++) {
        uint256 weiAmount = weiAmounts[i];
        address theAddress = addresses[i];
        if (thePenalty <= weiAmount) {
            weiAmount = weiAmount.sub(thePenalty);
            require(address(this).balance >= weiAmount);
            theAddress.transfer(weiAmount);
        }
    }
    emit RefundedBatch(addresses);
    return true;
}

function triggerVolcanoEruption() public {
    require(tx.origin == msg.sender);
    require(now >= lastEruptionTimestamp + eruptionThreshold);
    require(numCharacters > 0);
    lastEruptionTimestamp = now;
    uint128 pot;
    uint128 value;
    uint16 random;
    uint32 nextHitId;
    uint16 nchars = numCharacters;
    uint32 howmany = nchars * percentageToKill / 100;
    uint128 neededGas = 80000 + 10000 * uint32(nchars);
    if (howmany == 0) howmany = 1; 
    uint32[] memory hitCharacters = new uint32[](howmany);
    for (uint8 i = 0; i < howmany; i++) {
        random = uint16(generateRandomNumber(lastEruptionTimestamp + i) % nchars);
        nextHitId = ids[random];
        hitCharacters[i] = nextHitId;
        value = hitCharacter(random, nchars);
        if (value > 0) {
            nchars--;
        }
        pot += value;
    }
    uint128 gasCost = uint128(neededGas * tx.gasprice);
    numCharacters = nchars;
    if (pot > gasCost) {
        distribute(pot - gasCost); 
        NewEruption(hitCharacters, pot - gasCost, gasCost);
    } else
        NewEruption(hitCharacters, 0, gasCost);
}

