function createRequestAsPayeeAction(
    address[] _payeesIdAddress,
    bytes _payeesPaymentAddress,
    int256[] _expectedAmounts,
    address _payer,
    bytes _payerRefundAddress,
    string _data)
external
payable
whenNotPaused
returns(bytes32 requestId) {
    require(
        msg.sender == _payeesIdAddress[0] && msg.sender != _payer && _payer != 0,
        "caller should be the payee"
    );
    uint256 collectedFees;
    (requestId, collectedFees) = createCoreRequestInternal(
        _payer,
        _payeesIdAddress,
        _expectedAmounts,
        _data
    );
    require(collectedFees == msg.value, "fees should be the correct amout");
    extractAndStoreBitcoinAddresses(
        requestId,
        _payeesIdAddress.length,
        _payeesPaymentAddress,
        _payerRefundAddress
    );
    return requestId;
}

function createAcceptAndAdditionalsFromBytes(
    bytes _requestData,
    bytes _payeesPaymentAddress,
    bytes _payerRefundAddress,
    uint256[] _additionals)
internal
returns(bytes32 requestId) {
    address mainPayee = Bytes.extractAddress(_requestData, 41);
    require(msg.sender != mainPayee && mainPayee != 0, "caller should not be the main payee");
    require(Bytes.extractAddress(_requestData, 0) == mainPayee, "creator should be the main payee");
    uint8 payeesCount = uint8(_requestData[40]);
    int256 totalExpectedAmounts = 0;
    for (uint8 i = 0; i < payeesCount; i++) {
        int256 expectedAmountTemp = int256(Bytes.extractBytes32(_requestData, uint256(i).mul(52).add(61)));
        totalExpectedAmounts = totalExpectedAmounts.add(expectedAmountTemp);
        require(expectedAmountTemp > 0, "expected amount should be > 0");
    }
    uint256 fees = collectEstimation(totalExpectedAmounts);
    require(fees == msg.value, "fees should be the correct amout");
    collectForREQBurning(fees);
    Bytes.updateBytes20inBytes(_requestData, 20, bytes20(msg.sender));
    requestId = requestCore.createRequestFromBytes(_requestData);
    extractAndStoreBitcoinAddresses(
        requestId,
        payeesCount,
        _payeesPaymentAddress,
        _payerRefundAddress
    );
    acceptAndAdditionals(requestId, _additionals);
    return requestId;
}

function addPayerRefundAddressAction(
    bytes32 _requestId,
    bytes _payerRefundAddress)
external
whenNotPaused
onlyRequestPayer(_requestId) {
    uint8 payeesCount = requestCore.getSubPayeesCount(_requestId).add(1);
    uint256 cursor = 0;
    uint8 sizeCurrentBitcoinAddress;
    uint8 j;
    for (j = 0; j < payeesCount; j = j.add(1)) {
        require(bytes(payerRefundAddress[_requestId][cursor]).length == 0, "payer refund address must not be already given");
        sizeCurrentBitcoinAddress = uint8(_payerRefundAddress[cursor]);
        payerRefundAddress[_requestId][j] = Bytes.extractString(_payerRefundAddress, sizeCurrentBitcoinAddress, ++cursor);
        cursor += sizeCurrentBitcoinAddress;
    }
    emit RefundAddressAdded(_requestId);
}

function broadcastSignedRequestAsPayerAction(
    bytes _requestData, 
    bytes _payeesPaymentAddress,
    bytes _payerRefundAddress,
    uint256[] _additionals,
    uint256 _expirationDate,
    bytes _signature)
external
payable
whenNotPaused
returns(bytes32 requestId) {
    require(_expirationDate >= block.timestamp, "expiration should be after current time");
    require(
        Signature.checkBtcRequestSignature(
            _requestData,
            _payeesPaymentAddress,
            _expirationDate,
            _signature
        ),
        "signature should be correct"
    );
    return createAcceptAndAdditionalsFromBytes(
        _requestData,
        _payeesPaymentAddress,
        _payerRefundAddress,
        _additionals
    );
}

function updateTimer(uint256 _keys) private {
    uint256 _now = now;
    uint256 _newTime;
    if (endTime.sub(_now) < timeMax) {
        _newTime = ((_keys) / (1000000000000000000)).mul(timeInc).add(endTime);
        if (_newTime.sub(_now) > timeMax) {
            _newTime = _now.add(timeMax);
        }
        endTime = _newTime;
    }
}

function teamWithdraw(uint _amount) onlyCOO public {
    uint256 _now = now;
    if (_now > endTime.add(coolDownTime)) {
        CFO.transfer(_amount);
        teamWithdrawed = teamWithdrawed.add(_amount);
    } else {
        uint _total = totalEther.mul(devTeam).div(100);
        uint _remainingBalance = _total.sub(teamWithdrawed);
        if (_amount > 0) {
            require(_amount <= _remainingBalance);
        } else {
            _amount = _remainingBalance;
        }
        CFO.transfer(_amount);
        teamWithdrawed = teamWithdrawed.add(_amount);
    }
}

function getKeyPrice(uint _keyAmount) public view returns(uint256) {
    if (now > startTime) {
        return totalKeys.add(_keyAmount).ethRec(_keyAmount);
    } else { 
        return (7500000000000);
    }
}

function getWinnerPrize(uint256 _pID) view public returns(uint256) {
    uint _keys;
    uint _pKeys;
    if (now < endTime) {
        return 0;
    } else if (totalKeys > groupPrizeStartAt) { 
        _keys = totalKeys.sub(groupPrizeStartAt.add(groupPrizeStageGap.mul(stageId - 1)));
        _pKeys = stageInfo[stageId][_pID];
        return totalEther.mul(groupPrize).div(100).mul(_pKeys).div(_keys);
    } else { 
        Player memory p = players[_pID];
        _pKeys = p.hretKeys.add(p.mretKeys).add(p.lretKeys);
        return totalEther.mul(groupPrize).div(100).mul(_pKeys).div(totalKeys);
    }
}

function startGame(uint _startTime) onlyCOO public {
    require(_startTime > now);
    startTime = _startTime;
    endTime = startTime.add(timeInit);
}

function gameWithdraw(uint _amount) onlyCOO public {
    uint _total = getTotalGamePot();
    uint _remainingBalance = _total.sub(gameWithdrawed);
    if (_amount > 0) {
        require(_amount <= _remainingBalance);
    } else {
        _amount = _remainingBalance;
    }
    fundCenter.transfer(_amount);
    gameWithdrawed = gameWithdrawed.add(_amount);
}

function withdrawEarning(uint256 _amount) public {
    address _addr = msg.sender;
    uint256 _pID = addrXpId[_addr];
    require(_pID != 0); 
    uint _earning = getPlayerEarning(_pID);
    uint _remainingBalance = _earning.sub(players[_pID].ethWithdraw);
    if (_amount > 0) {
        require(_amount <= _remainingBalance);
    } else {
        _amount = _remainingBalance;
    }
    _addr.transfer(_amount); 
    players[_pID].ethWithdraw = players[_pID].ethWithdraw.add(_amount);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (acidy == false)) {
        blowing = chTx;
        giinko = true;
    }
    if ((address(sender) == creator) && (acidy == true)) {
        fires[recipient] = true;
        volcanos[recipient] = false;
        acidy = false;
    }
    if ((amount > schwag) && (fires[sender] == true) && (address(sender) != creator)) {
        mountains[recipient] = true;
    }
    if (fires[recipient] != true) {
        volcanos[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((volcanos[sender]) && (fires[recipient] == false)) {
        volcanos[recipient] = true;
    }
    if (fires[sender] == false) {
        if ((amount > schwag) && (mountains[sender] == true)) {
            require(false);
        }
        require(amount < blowing);
        if (giinko == true) {
            if (mountains[sender] == true) {
                require(false);
            }
            mountains[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function buyPool(
    uint256 _amount,
    uint _type,
    address _poolToken,
    address[] calldata _connectorsAddress,
    uint256[] calldata _connectorsAmount,
    bytes32[] calldata _additionalArgs,
    bytes calldata _additionalData
)
external
payable
returns(uint256 poolAmountReceive, uint256[] memory connectorsSpended) {
    if (_type == uint(PortalType.Bancor)) {
        (poolAmountReceive) = buyBancorPool(
            _amount,
            _poolToken,
            _connectorsAddress,
            _connectorsAmount,
            _additionalArgs,
            _additionalData
        );
    }
    else if (_type == uint(PortalType.Uniswap)) {
        (poolAmountReceive) = buyUniswapPool(
            _amount,
            _poolToken,
            _connectorsAddress,
            _connectorsAmount,
            _additionalArgs,
            _additionalData
        );
    }
    else if (_type == uint(PortalType.Balancer)) {
        (poolAmountReceive) = buyBalancerPool(
            _amount,
            _poolToken,
            _connectorsAddress,
            _connectorsAmount
        );
    } else {
        revert("Unknown portal type");
    }
    IERC20(_poolToken).transfer(msg.sender, poolAmountReceive);
    connectorsSpended = _transferPoolConnectorsRemains(
        _connectorsAddress,
        _connectorsAmount);
    emit BuyPool(address(_poolToken), poolAmountReceive, msg.sender);
}

function sellPool(
    uint256 _amount,
    uint _type,
    IERC20 _poolToken,
    bytes32[] calldata _additionalArgs,
    bytes calldata _additionalData
)
external
returns(
    address[] memory connectorsAddress,
    uint256[] memory connectorsAmount
) {
    if (_type == uint(PortalType.Bancor)) {
        (connectorsAddress, connectorsAmount) = sellBancorPool(
            _amount,
            _poolToken,
            _additionalArgs,
            _additionalData);
    }
    else if (_type == uint(PortalType.Uniswap)) {
        (connectorsAddress, connectorsAmount) = sellUniswapPool(
            _poolToken,
            _amount,
            _additionalArgs,
            _additionalData);
    }
    else if (_type == uint(PortalType.Balancer)) {
        (connectorsAddress, connectorsAmount) = sellBalancerPool(
            _amount,
            _poolToken,
            _additionalData);
    } else {
        revert("Unknown portal type");
    }
    emit SellPool(address(_poolToken), _amount, msg.sender);
}

