function executeOfferIfSignatureMatch(
    uint8 v,
    bytes32 r,
    bytes32 s,
    address contractaddress,
    uint256 tokenid,
    uint256 ethamt,
    uint256 deadline,
    uint256 feeamt,
    address signer,
    uint256 salt
) external {
    require(block.timestamp < deadline, "Signed transaction expired");
    bytes32 hashStruct = keccak256(
        abi.encode(
            keccak256("matchoffer(address contractaddress,uint tokenid,uint ethamt,uint deadline,uint feeamt,address signer,uint salt)"),
            contractaddress,
            tokenid,
            ethamt,
            deadline,
            feeamt,
            signer,
            salt
        )
    );
    bytes32 hash = keccak256(abi.encodePacked("\x19\x01", _eip712DomainHash(), hashStruct));
    address signaturesigner = ecrecover(hash, v, r, s);
    require(signaturesigner == signer, "invalid signature");
    require(offerhashes[hashStruct] == false, "order filled or cancelled");
    offerhashes[hashStruct] = true;
    if (feeamt > 0) {
        require(wethcontract.transferFrom(signer, owner, feeamt), "error in weth transfer");
    }
    require(wethcontract.transferFrom(signer, msg.sender, ethamt - feeamt), "error in weth transfer");
    ERC721 nftcontract = ERC721(contractaddress);
    nftcontract.safeTransferFrom(msg.sender, signer, tokenid);
    emit Offerfilled(signer, msg.sender, hashStruct, ethamt, feeamt);
}

function executeOrderIfSignatureMatch(
    uint8 v,
    bytes32 r,
    bytes32 s,
    address contractaddress,
    uint256 tokenid,
    uint256 ethamt,
    uint256 deadline,
    uint256 feeamt,
    address payable signer,
    uint256 salt,
    address refferer
) external payable {
    require(block.timestamp < deadline, "Signed transaction expired");
    bytes32 hashStruct = keccak256(
        abi.encode(
            keccak256("matchorder(address contractaddress,uint tokenid,uint ethamt,uint deadline,uint feeamt,address signer,uint salt)"),
            contractaddress,
            tokenid,
            ethamt,
            deadline,
            feeamt,
            signer,
            salt
        )
    );
    bytes32 hash = keccak256(abi.encodePacked("\x19\x01", _eip712DomainHash(), hashStruct));
    address signaturesigner = ecrecover(hash, v, r, s);
    require(signaturesigner == signer, "invalid signature");
    require(msg.value == ethamt, "wrong eth amt");
    require(orderhashes[hashStruct] == false, "order filled or cancelled");
    orderhashes[hashStruct] = true; 
    ERC721 nftcontract = ERC721(contractaddress);
    nftcontract.safeTransferFrom(signer, msg.sender, tokenid); 
    if (feeamt > 0) {
        owner.transfer(feeamt); 
    }
    signer.transfer(msg.value - feeamt); 
    emit Orderfilled(signer, msg.sender, hashStruct, ethamt, refferer, feeamt);
}

function register(string label) payable {
    uint256 position;
    uint256 length;
    assembly {
        length: = mload(label)
        position: = add(label, 1)
    }
    if (length < 4 || length > 20) {
        throw;
    }
    for (uint256 i = 0; i < length; i++) {
        uint8 c;
        assembly {
            c: = and(mload(position), 0xFF)
        }
        if ((c < 0x61 || c > 0x7a) && (c < 0x30 || c > 0x39) && c != 0x2d) {
            throw;
        }
        position++;
    }
    if (msg.value < _fee) {
        throw;
    }
    var labelHash = sha3(label);
    var nodeHash = sha3(_nodeHash, labelHash);
    if (_ens.owner(nodeHash) != address(0)) {
        throw;
    }
    _ens.setSubnodeOwner(_nodeHash, labelHash, this);
    _ens.setResolver(nodeHash, _defaultResolver);
    _defaultResolver.setAddr(nodeHash, msg.sender);
    _ens.setOwner(nodeHash, msg.sender);
    _totalPaid += msg.value;
    _nameCount++;
    _donations[nodeHash] += msg.value;
    nameRegistered(nodeHash, msg.sender, msg.value);
    donation(nodeHash, msg.value);
}

