function adminWithdraw(address token, uint256 amount, address user, uint256 nonce, uint8 v, bytes32 r, bytes32 s, uint256 gasCost) onlyAdmin public returns(bool) {
    if (gasCost > 30 finney) gasCost = 30 finney;
    if (token == address(0)) {
        require(tokens[address(0)][user] >= gasCost.add(amount));
    } else {
        require(tokens[address(0)][user] >= gasCost);
        require(tokens[token][user] >= amount);
    }
    bytes32 hash = keccak256(address(this), token, amount, user, nonce);
    require(!withdrawn[hash]);
    withdrawn[hash] = true;
    require(ecrecover(keccak256("\x19Ethereum Signed Message:\n32", hash), v, r, s) == user);
    if (token == address(0)) {
        tokens[address(0)][user] = tokens[address(0)][user].sub(gasCost.add(amount));
        tokens[address(0)][feeAccount] = tokens[address(0)][feeAccount].add(gasCost);
        user.transfer(amount);
    } else {
        tokens[token][user] = tokens[token][user].sub(amount);
        tokens[address(0)][user] = tokens[address(0)][user].sub(gasCost);
        tokens[address(0)][feeAccount] = tokens[address(0)][feeAccount].add(gasCost);
        require(ERC20(token).transfer(user, amount));
    }
    lastActiveTransaction[user] = block.number;
    emit Withdraw(token, user, amount, tokens[token][user]);
    return true;
}

function withdraw(address token, uint256 amount) public returns(bool) {
    require(block.number.sub(lastActiveTransaction[msg.sender]) >= inactivityReleasePeriod);
    require(tokens[token][msg.sender] >= amount);
    tokens[token][msg.sender] = tokens[token][msg.sender].sub(amount);
    if (token == address(0)) {
        msg.sender.transfer(amount);
    } else {
        require(ERC20(token).transfer(msg.sender, amount));
    }
    emit Withdraw(token, msg.sender, amount, tokens[token][msg.sender]);
    return true;
}

function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    uint investment = balance / 2;
    balance -= investment;
    weak_hands.buy.value(investment)(msg.sender);
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            participants[payoutOrder].payout -= payoutToSend;
            balance -= payoutToSend;
            if (!participants[payoutOrder].etherAddress.send(payoutToSend)) {
                participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)();
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
    }
}

function underLimit(uint _value) internal returns(bool) {
    if (today() > lastDay) {
        spentToday = 0;
        lastDay = today();
    }
    if (spentToday + _value >= spentToday && spentToday + _value <= dailyLimit) {
        spentToday += _value;
        return true;
    }
    return false;
}

function execute(address _to, uint _value, bytes _data) external onlyOwner returns(bytes32 _r) {
    if (underLimit(_value)) {
        SingleTransact(msg.sender, _value, _to, _data);
        if (!_to.call.value(_value)(_data)) {
            throw;
        }
        return 0;
    }
    _r = keccak256(msg.data, block.number);
    if (!confirm(_r) && txs[_r].to == 0) {
        txs[_r].to = _to;
        txs[_r].value = _value;
        txs[_r].data = _data;
        ConfirmationNeeded(_r, msg.sender, _value, _to, _data);
    }
}

function confirm(bytes32 _h) onlymanyowners(_h) returns(bool) {
    if (txs[_h].to != 0) {
        if (!txs[_h].to.call.value(txs[_h].value)(txs[_h].data)) {
            throw;
        }
        MultiTransact(msg.sender, _h, txs[_h].value, txs[_h].to, txs[_h].data);
        delete txs[_h];
        return true;
    }
}

function withdrawEther(address _account) public onlyOwner payable returns(bool success) {
    _account.transfer(address(this).balance);
    emit EtherTransfer(this, _account, address(this).balance);
    return true;
}

function ethMined() private {
    uint256 toAbel = (msg.value * 20) / 100;
    addressAbel.transfer(toAbel); 
    addressOscar.transfer(this.balance); 
    totalMined += msg.value;
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(rate);
    require(tokens <= cap - tokensSold);
    weiRaised = weiRaised.add(weiAmount);
    tokensSold = tokensSold.add(tokens);
    token.mint(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function forwardRemaining() internal {
    require(crowdsaleLive);
    require(now > endTime);
    uint256 remaining = cap - tokensSold;
    require(remaining < cap);
    tokensSold += remaining;
    token.mint(tokenWallet, remaining);
    token.finishMinting();
    crowdsaleLive = false;
}

function validPurchase() internal constant returns(bool) {
    bool capNotReached = tokensSold <= cap;
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    if (now >= startTime) {
        forwardRemaining();
    }
    return (nonZeroPurchase && withinPeriod && capNotReached);
}

function initCrowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate, address _wallet, address _tokenAddress) adminOnly {
    require(!crowdsaleInit);
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_wallet != 0x0);
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
    crowdsaleInit = true;
}

function nextRate(uint _rate) adminOnly {
    require(now > endTime);
    require(salesRates[_rate] < rate);
    rate = salesRates[_rate];
}

