function() external payable {
    require(msg.sender != address(0));
    require(msg.value >= minInvestment);
    if (now > rounds[currentRoundId].endTime) {
        switchToNextRound();
    }
    uint256 tokenPrice = rounds[currentRoundId].tokenPrice;
    uint256 tokens = msg.value.div(tokenPrice);
    token.mint(msg.sender, tokens);
    emit TokenPurchase(msg.sender, msg.value, tokens);
    tokensIssued = tokensIssued.add(tokens);
    rounds[currentRoundId].tokensIssued = rounds[currentRoundId].tokensIssued.add(tokens);
    weiRaised = weiRaised.add(msg.value);
    rounds[currentRoundId].weiRaised = rounds[currentRoundId].weiRaised.add(msg.value);
    if (rounds[currentRoundId].tokensIssued >= rounds[currentRoundId].tokensCap) {
        switchToNextRound();
    }
    forwardFunds();
}

function switchToNextRound() public {
    uint256 prevRoundId = currentRoundId;
    uint256 nextRoundId = currentRoundId + 1;
    require(nextRoundId < rounds.length);
    rounds[prevRoundId].endTime = now;
    rounds[nextRoundId].startTime = now + 1;
    rounds[nextRoundId].endTime = now + 30;
    if (nextRoundId == rounds.length - 1) {
        rounds[nextRoundId].tokensCap = tokensCap.sub(tokensIssued);
    } else {
        rounds[nextRoundId].tokensCap = tokensCap.sub(tokensIssued).div(5);
    }
    currentRoundId = nextRoundId;
    emit SwitchedToNextRound(currentRoundId);
}

function claim()
external
returns(bool status) {
    require(isStarted, 'The claim has not started yet');
    uint value_ = calculateUnclaimed(msg.sender);
    require(value_ > 0);
    require(token.balanceOf(address(this)) >= value_, 'Not enough tokens on contract');
    users[msg.sender].claimed += value_;
    users[msg.sender].claimTimestamp = block.timestamp;
    token.transfer(msg.sender, value_);
    emit Claimed(msg.sender, value_);
    return true;
}

function calculateRound(string memory roundName_, uint allocation_)
internal
view
returns(uint unclaimedFromRound) {
    require(isStarted, 'The claim has not started yet');
    Round memory round_ = rounds[roundName_];
    uint timePassed_ = block.timestamp - startTimestamp;
    uint bank_ = allocation_;
    if (timePassed_ < (round_.cliff * MONTH)) return 0;
    timePassed_ -= (round_.cliff * MONTH);
    uint constReward_ = (bank_ * round_.constReward) / 100;
    if (round_.cliff == 0) {
        if (timePassed_ < CONST_PERIOD / 2) return constReward_ / 2;
    }
    if (timePassed_ < CONST_RELAX) return constReward_;
    timePassed_ -= CONST_RELAX;
    uint minutesPassed_ = timePassed_ / MINUTE;
    uint leftInBank_ = bank_ - constReward_;
    return (leftInBank_ * MINUTE * minutesPassed_) / (MONTH * round_.linearPeriod) + constReward_;
}

