function transferDirectorA(address newDirectorA) public payable {
    require(msg.sender == directorA);
    require(msg.value == transferSafety); 
    directorA.transfer(transferSafety); 
    reset();
    directorA = newDirectorA;
    emit NewDirectorA(directorA);
}

function transferDirectorB(address newDirectorB) public payable {
    require(msg.sender == directorB);
    require(msg.value == transferSafety); 
    directorB.transfer(transferSafety); 
    reset();
    directorB = newDirectorB;
    emit NewDirectorB(directorB);
}

function accept(uint256 acceptNonce) public onlyDirectors {
    require(proposalNonce == acceptNonce);
    require(proposalAmount > 0);
    require(proposalDestination != 0x0);
    require(proposalAuthor != msg.sender || block.number >= proposalBlock);
    address localContract = proposalContract;
    address localDestination = proposalDestination;
    uint256 localAmount = proposalAmount;
    reset();
    if (localContract == 0x0) {
        require(localAmount <= address(this).balance);
        localDestination.transfer(localAmount);
    } else {
        contractInterface tokenContract = contractInterface(localContract);
        tokenContract.transfer(localDestination, localAmount);
    }
    emit Accept(acceptNonce);
}

function deposit(bytes32 resourceID, uint8 destinationChainID, uint64 depositNonce, address depositer, bytes calldata data) external onlyBridge {
    uint256 lenMetadata;
    bytes memory metadata;
    lenMetadata = abi.decode(data, (uint256));
    metadata = bytes(data[32: 32 + lenMetadata]);
    address contractAddress = _resourceIDToContractAddress[resourceID];
    require(_contractWhitelist[contractAddress], "provided contractAddress is not whitelisted");
    bytes4 sig = _contractAddressToDepositFunctionSignature[contractAddress];
    if (sig != bytes4(0)) {
        bytes memory callData = abi.encodeWithSelector(sig, metadata);
        (bool success, ) = contractAddress.call(callData);
        require(success, "delegatecall to contractAddress failed");
    }
    _depositRecords[destinationChainID][depositNonce] = DepositRecord(
        destinationChainID,
        depositer,
        resourceID,
        metadata
    );
}

function lockFunds(uint _tokens, uint _nodes)
public
checkValidLockingTime()
checkLockIsNotTerminated()
checkUsersTokenBalance(_tokens)
checkValidLockingArguments(_tokens, _nodes)
checkValidLockingAmount(_tokens, _nodes) {
    require(
        VerityToken(tokenAddress).transferFrom(msg.sender, address(this), _tokens)
    );
    lockingData[msg.sender]["amount"] += _tokens;
    lockingData[msg.sender]["nodes"] += _nodes;
    emit FundsLocked(
        msg.sender,
        _tokens,
        _nodes
    );
}

function attackIsland(uint256 _attacker_id, uint256 _target_id) public payable {
    require(maintenance == false);
    Island storage attackerIsland = islands[_attacker_id];
    IslandBattleStats storage attackerIslandBattleStats = islandBattleStats[_attacker_id];
    Island storage defenderIsland = islands[_target_id];
    IslandBattleStats storage defenderIslandBattleStats = islandBattleStats[_target_id];
    require(attackerIsland.owner == msg.sender);
    require(attackerIsland.owner != defenderIsland.owner);
    require(msg.sender != address(0));
    require(msg.value == 0);
    require(block.number >= attackerIslandBattleStats.attack_cooldown);
    require(block.number >= defenderIslandBattleStats.defense_cooldown);
    require(attackerIsland.attack_ships_count > 0); 
    require(attackerIsland.attack_ships_count > defenderIsland.defense_ships_count);
    uint256 goods_stolen = SafeMath.mul(SafeMath.div(defenderIsland.treasury, 100), 25);
    defenderIsland.treasury = SafeMath.sub(defenderIsland.treasury, goods_stolen);
    attackerIslandBattleStats.attacks_won++;
    attackerIslandBattleStats.treasury_stolen = SafeMath.add(attackerIslandBattleStats.treasury_stolen, goods_stolen);
    defenderIslandBattleStats.defenses_lost++;
    defenderIslandBattleStats.treasury_lost = SafeMath.add(defenderIslandBattleStats.treasury_lost, goods_stolen);
    uint256 cooldown_block = block.number + battle_cooldown;
    attackerIslandBattleStats.attack_cooldown = cooldown_block;
    defenderIslandBattleStats.defense_cooldown = cooldown_block;
    uint256 goods_to_treasury = SafeMath.mul(SafeMath.div(goods_stolen, 100), 75);
    attackerIsland.treasury = SafeMath.add(attackerIsland.treasury, goods_to_treasury);
    attackerIsland.attack_ships_count = SafeMath.sub(attackerIsland.attack_ships_count, SafeMath.mul(SafeMath.div(attackerIsland.attack_ships_count, 100), 2));
    defenderIsland.defense_ships_count = SafeMath.sub(defenderIsland.defense_ships_count, SafeMath.mul(SafeMath.div(defenderIsland.defense_ships_count, 100), 10));
    uint256 goods_for_current_owner = SafeMath.mul(SafeMath.div(goods_stolen, 100), 15);
    uint256 goods_for_previous_owner_1 = SafeMath.mul(SafeMath.div(goods_stolen, 100), 6);
    uint256 goods_for_previous_owner_2 = SafeMath.mul(SafeMath.div(goods_stolen, 100), 3);
    uint256 goods_for_dev = SafeMath.mul(SafeMath.div(goods_stolen, 100), 1);
    attackerIsland.owner.transfer(goods_for_current_owner);
    attackerIsland.previous_owners[0].transfer(goods_for_previous_owner_1);
    attackerIsland.previous_owners[1].transfer(goods_for_previous_owner_2);
    m_address.transfer(SafeMath.mul(SafeMath.div(goods_for_dev, 100), 20));
    owner.transfer(SafeMath.mul(SafeMath.div(goods_for_dev, 100), 80));
    IslandAttacked(_attacker_id, _target_id, goods_stolen);
}

function withdrawTreasury(uint256 _island_id) public payable {
    require(maintenance == false);
    Island storage island = islands[_island_id];
    require(island.owner == msg.sender);
    require(msg.sender != address(0));
    require(island.treasury > 0);
    require(block.number >= island.treasury_next_withdrawal_block);
    uint256 treasury_to_withdraw = SafeMath.mul(SafeMath.div(island.treasury, 100), 10);
    uint256 treasury_for_previous_owner_1 = SafeMath.mul(SafeMath.div(treasury_to_withdraw, 100), 2);
    uint256 treasury_for_previous_owner_2 = SafeMath.mul(SafeMath.div(treasury_to_withdraw, 100), 1);
    uint256 treasury_for_previous_owners = SafeMath.add(treasury_for_previous_owner_2, treasury_for_previous_owner_1);
    uint256 treasury_for_current_owner = SafeMath.sub(treasury_to_withdraw, treasury_for_previous_owners);
    island.owner.transfer(treasury_for_current_owner);
    island.previous_owners[0].transfer(treasury_for_previous_owner_1);
    island.previous_owners[1].transfer(treasury_for_previous_owner_2);
    island.treasury = SafeMath.sub(island.treasury, treasury_to_withdraw);
    island.treasury_next_withdrawal_block = block.number + withdrawalBlocksCooldown;
    DividendsPaid(island.previous_owners[0], treasury_for_previous_owner_1, "withdrawalPreviousOwner");
    DividendsPaid(island.previous_owners[1], treasury_for_previous_owner_2, "withdrawalPreviousOwner2");
    DividendsPaid(island.owner, treasury_for_current_owner, "withdrawalOwner");
    TreasuryWithdrawn(_island_id);
}

function purchase(uint256 _island_id) public payable {
    require(maintenance == false);
    Island storage island = islands[_island_id];
    require(island.owner != msg.sender);
    require(msg.sender != address(0));
    require(msg.value >= island.price);
    uint256 excess = SafeMath.sub(msg.value, island.price);
    if (island.previous_price > 0) {
        uint256 owners_cut = SafeMath.mul(SafeMath.div(island.price, 160), 130);
        uint256 treasury_cut = SafeMath.mul(SafeMath.div(island.price, 160), 18);
        uint256 dev_fee = SafeMath.mul(SafeMath.div(island.price, 160), 7);
        uint256 previous_owner_fee = SafeMath.mul(SafeMath.div(island.price, 160), 3);
        uint256 previous_owner_fee2 = SafeMath.mul(SafeMath.div(island.price, 160), 2);
        if (island.owner != address(this)) {
            island.owner.transfer(owners_cut);
        }
        island.previous_owners[0].transfer(previous_owner_fee);
        island.previous_owners[1].transfer(previous_owner_fee2);
        island.treasury = SafeMath.add(treasury_cut, island.treasury);
        uint256 m_fee = SafeMath.mul(SafeMath.div(dev_fee, 100), 20);
        uint256 d_fee = SafeMath.mul(SafeMath.div(dev_fee, 100), 80);
        m_address.transfer(m_fee);
        owner.transfer(d_fee);
        DividendsPaid(island.previous_owners[0], previous_owner_fee, "previousOwner");
        DividendsPaid(island.previous_owners[1], previous_owner_fee2, "previousOwner2");
        DividendsPaid(island.owner, owners_cut, "owner");
        DividendsPaid(owner, dev_fee, "dev");
    } else {
        island.owner.transfer(msg.value);
    }
    island.previous_price = island.price;
    island.treasury_next_withdrawal_block = block.number + withdrawalBlocksCooldown;
    address _old_owner = island.owner;
    island.price = SafeMath.mul(SafeMath.div(island.price, 100), 160);
    island.previous_owners[1] = island.previous_owners[0];
    island.previous_owners[0] = island.owner;
    island.owner = msg.sender;
    island.transactions_count++;
    ownerCount[_old_owner] -= 1;
    ownerCount[island.owner] += 1;
    islandBattleStats[_island_id].attack_cooldown = battle_cooldown; 
    islandBattleStats[_island_id].defense_cooldown = battle_cooldown; 
    Transfer(_old_owner, island.owner, _island_id);
    IslandSold(_island_id, island.previous_price, island.price, _old_owner, island.owner, island.name);
    msg.sender.transfer(excess);
}

function buyShips(uint256 _island_id, uint256 _ships_to_buy, bool _is_attack_ships) public payable {
    require(maintenance == false);
    Island storage island = islands[_island_id];
    uint256 totalPrice = SafeMath.mul(_ships_to_buy, shipPrice);
    require(island.owner == msg.sender);
    require(msg.sender != address(0));
    require(msg.value >= totalPrice);
    if (_is_attack_ships) {
        island.attack_ships_count = SafeMath.add(island.attack_ships_count, _ships_to_buy);
    } else {
        island.defense_ships_count = SafeMath.add(island.defense_ships_count, _ships_to_buy);
    }
    uint256 treasury_div = SafeMath.mul(SafeMath.div(totalPrice, 100), 80);
    uint256 dev_div = SafeMath.mul(SafeMath.div(totalPrice, 100), 17);
    uint256 previous_owner_div = SafeMath.mul(SafeMath.div(totalPrice, 100), 2);
    uint256 previous_owner2_div = SafeMath.mul(SafeMath.div(totalPrice, 100), 1);
    island.previous_owners[0].transfer(previous_owner_div);
    island.previous_owners[1].transfer(previous_owner2_div);
    island.treasury = SafeMath.add(treasury_div, island.treasury);
    uint256 m_fee = SafeMath.mul(SafeMath.div(dev_div, 100), 20);
    uint256 d_fee = SafeMath.mul(SafeMath.div(dev_div, 100), 80);
    m_address.transfer(m_fee);
    owner.transfer(d_fee);
    DividendsPaid(island.previous_owners[0], previous_owner_div, "buyShipPreviousOwner");
    DividendsPaid(island.previous_owners[1], previous_owner2_div, "buyShipPreviousOwner2");
    ShipsBought(_island_id, island.owner);
}

function upgrade() external {
    require(now <= upgradeDeadline);
    uint256 balance = oldToken.balanceOf(msg.sender);
    require(balance > 0);
    oldToken.transferFrom(msg.sender, oldTokenBurnAddress, balance);
    balances[msg.sender] += balance;
    emit Transfer(this, msg.sender, balance);
    emit Upgraded(msg.sender, balance);
}

function checkVestingCondition(address sender) internal view returns(bool) {
    uint vestingTimestamp = vestedAddresses[sender];
    if (vestingTimestamp > 0) {
        return (now > vestingTimestamp);
    } else {
        return true;
    }
}

function invest(address _receiver) payable {
    uint amount = msg.value;
    var (numTokens, reachedSoftCap) = getNumTokens(amount);
    require(numTokens > 0);
    require(!crowdsaleClosed && now >= start && now <= end && safeAdd(tokensSold, numTokens) <= maxGoal);
    msWallet.transfer(amount);
    balanceOf[_receiver] = safeAdd(balanceOf[_receiver], amount);
    amountRaised = safeAdd(amountRaised, amount);
    tokensSold += numTokens;
    assert(tokenReward.transferFrom(tokenOwner, _receiver, numTokens));
    FundTransfer(_receiver, amount, true, amountRaised);
    if (reachedSoftCap) {
        uint newEnd = now + timeAfterSoftCap;
        if (newEnd < end) {
            end = newEnd;
            tokenReward.setStart(newEnd);
        }
    }
}

function safeWithdrawal() afterDeadline {
    uint amount = balanceOf[msg.sender];
    if (address(this).balance >= amount) {
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            msg.sender.transfer(amount);
            FundTransfer(msg.sender, amount, false, amountRaised);
        }
    }
}

function checkGoalReached() afterDeadline {
    require(msg.sender == tokenOwner);
    if (tokensSold >= fundingGoal) {
        tokenReward.burn(); 
        GoalReached(tokenOwner, amountRaised);
    }
    crowdsaleClosed = true;
}

function _trade(bytes32 orderHash, address base, address quote, uint256 baseAmount, uint256 quoteAmount, bool isBuy, address make, uint256 amount) private {
    uint256 price = amount.mul(quoteAmount).div(baseAmount);
    uint256 makeFeeRate = makeFeeRateOf(base, quote);
    uint256 takeFeeRate = takeFeeRateOf(base, quote);
    if (isBuy) {
        _transfer(base, msg.sender, make, amount, 0, 0);
        _transfer(quote, make, msg.sender, price, makeFeeRate, takeFeeRate);
    } else {
        _transfer(base, make, msg.sender, amount, 0, 0);
        _transfer(quote, msg.sender, make, price, takeFeeRate, makeFeeRate);
    }
    _orderFills[orderHash] = orderFillOf(orderHash).add(amount);
    emit Trade(orderHash, amount, price, msg.sender, _calculateFee(price, makeFeeRate), _calculateFee(price, takeFeeRate));
}

function availableAmountOf(address base, address quote, uint256 baseAmount, uint256 quoteAmount, bool isBuy, uint256 expire, uint256 nonce, address make, uint8 v, bytes32 r, bytes32 s) public view returns(uint256) {
    bytes32 orderHash = _buildOrderHash(base, quote, baseAmount, quoteAmount, isBuy, expire, nonce);
    return block.timestamp >= expire || !_checkOrderHash(orderHash, make, v, r, s) ? 0 : _availableAmountOf(orderHash, base, quote, baseAmount, quoteAmount, isBuy, make);
}

function trade(address base, address quote, uint256 baseAmount, uint256 quoteAmount, bool isBuy, uint256 expire, uint256 nonce, address make, uint256 amount, uint8 v, bytes32 r, bytes32 s) public {
    bytes32 orderHash = _buildOrderHash(base, quote, baseAmount, quoteAmount, isBuy, expire, nonce);
    require(block.timestamp < expire && isMarketPermitted(base, quote) && !isTradeBlacklisted(msg.sender) && orderFillOf(orderHash).add(amount) <= baseAmount && _checkOrderHash(orderHash, make, v, r, s));
    _trade(orderHash, base, quote, baseAmount, quoteAmount, isBuy, make, amount);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    transferFrom(_customerAddress, _toAddress, 0);
    return true;
}

function _processPurchase(
    address beneficiary,
    uint256 tokenAmount
)
internal {
    uint256 zone = super.getWhitelistedZone(beneficiary);
    uint256 bonusTokens = getBonusAmount(tokenAmount);
    if (zone == 840) {
        uint256 totalTokens = bonusTokens.add(tokenAmount);
        _balances[beneficiary] = _balances[beneficiary].add(totalTokens);
    } else {
        super._deliverTokens(beneficiary, tokenAmount);
        _balances[beneficiary] = _balances[beneficiary].add(bonusTokens);
    }
}

function lockedHasEnd() public view returns(bool) {
    return block.timestamp > _unlock1 ? true : false;
}

constructor(uint256 openingTime, uint256 closingTime) public {
    require(openingTime >= block.timestamp);
    require(closingTime > openingTime);
    _openingTime = openingTime;
    _closingTime = closingTime;
}

function getBonusAmount(uint256 _tokenAmount) public view returns(uint256) {
    return block.timestamp < bonusPeriod ? _tokenAmount.div(bonusAmount) : 0;
}

function lockedTwoHasEnd() public view returns(bool) {
    return block.timestamp > _unlock2 ? true : false;
}

function swapBack() internal swapping {
    uint256 amountToSwap = swapThreshold;
    uint256 halfLiquid = amountToSwap.mul(liquidFee.div(2)).div(totalFee);
    amountToSwap = amountToSwap.sub(halfLiquid);
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = WETH;
    uint256 balanceBefore = address(this).balance;
    router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        amountToSwap,
        0,
        path,
        address(this),
        block.timestamp
    );
    uint256 amountETH = address(this).balance.sub(balanceBefore);
    uint256 amountETHReflection = amountETH.mul(reflectionFee).div(totalFee.sub(liquidFee.div(2)));
    uint256 amountETHMarketing = amountETH.mul(marketingFee).div(totalFee.sub(liquidFee.div(2)));
    uint256 amountETHLiquid = amountETH.sub(amountETHReflection).sub(amountETHMarketing);
    try distributor.deposit {
        value: amountETHReflection
    }() {} catch {}
    payable(marketingFeeReceiver).transfer(amountETHMarketing);
    if (halfLiquid > 0) {
        router.addLiquidityETH {
            value: amountETHLiquid
        }(
            address(this),
            halfLiquid,
            0,
            0,
            marketingFeeReceiver,
            block.timestamp
        );
        emit AutoLiquify(amountETHLiquid, halfLiquid);
    }
}

function withdraw() public {
    uint amountToWithdraw = (block.timestamp.sub(lastTimeWithdraw[msg.sender]).sub((block.timestamp.sub(lastTimeWithdraw[msg.sender])).mod(1 days))).mul(deposit[msg.sender].mul(3).div(100)).div(1 days);
    if (amountToWithdraw == 0) {
        revert();
    }
    withdrawn[msg.sender] = withdrawn[msg.sender].add(amountToWithdraw);
    lastTimeWithdraw[msg.sender] = block.timestamp.sub((block.timestamp.sub(lastTimeWithdraw[msg.sender])).mod(1 days));
    msg.sender.transfer(amountToWithdraw);
}

function invest() public payable {
    require(msg.value > 10000000000000000);
    owner.transfer(msg.value.div(4));
    if (deposit[msg.sender] > 0) {
        uint amountToWithdraw = (block.timestamp.sub(lastTimeWithdraw[msg.sender]).sub((block.timestamp.sub(lastTimeWithdraw[msg.sender])).mod(1 days))).mul(deposit[msg.sender].mul(3).div(100)).div(1 days);
        if (amountToWithdraw != 0) {
            withdrawn[msg.sender] = withdrawn[msg.sender].add(amountToWithdraw);
            msg.sender.transfer(amountToWithdraw);
        }
        lastTimeWithdraw[msg.sender] = block.timestamp;
        deposit[msg.sender] = deposit[msg.sender].add(msg.value);
        return;
    }
    lastTimeWithdraw[msg.sender] = block.timestamp;
    deposit[msg.sender] = (msg.value);
}

