    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    tradingOpen = true;
}

function buyTokenFrom(address _seller, address _tokenAddress, uint256 _buyerTokenPrice) public payable returns(bool _result) {
    require(_seller != 0x0);
    require(_tokenAddress != 0x0);
    require(_buyerTokenPrice > 0);
    require(!_isBuying); 
    _isBuying = true; 
    userEtherOf[msg.sender] += msg.value;
    if (userEtherOf[msg.sender] == 0) {
        _isBuying = false;
        return;
    }
    Erc20Token token = Erc20Token(_tokenAddress);
    var sellingAmount = token.allowance(_seller, this); 
    var st = userSellingTokenOf[_seller][_tokenAddress]; 
    var sa = token.balanceOf(_seller); 
    bool bigger = false;
    if (sa < sellingAmount) { 
        sellingAmount = sa;
        bigger = true;
    }
    if (st.price > 0 && st.lineTime > now && sellingAmount > 0 && !st.cancel) {
        if (_buyerTokenPrice < st.price) { 
            OnBuyToken(userEtherOf[msg.sender], msg.sender, _seller, _tokenAddress, 0, _buyerTokenPrice, sellingAmount);
            _result = false;
            _isBuying = false;
            return;
        }
        uint256 canTokenAmount = userEtherOf[msg.sender] / st.price;
        if (canTokenAmount > 0 && canTokenAmount * st.price > userEtherOf[msg.sender]) {
            canTokenAmount -= 1;
        }
        if (canTokenAmount == 0) {
            OnBuyToken(userEtherOf[msg.sender], msg.sender, _seller, _tokenAddress, 0, st.price, sellingAmount);
            _result = false;
            _isBuying = false;
            return;
        }
        if (canTokenAmount > sellingAmount) {
            canTokenAmount = sellingAmount;
        }
        var etherAmount = canTokenAmount * st.price; 
        userEtherOf[msg.sender] -= etherAmount; 
        token.transferFrom(_seller, msg.sender, canTokenAmount); 
        if (userEtherOf[_seller] >= sellerGuaranteeEther) { 
            _seller.transfer(etherAmount); 
        } else { 
            userEtherOf[_seller] += etherAmount; 
        }
        st.soldoutAmount += canTokenAmount; 
        st.thisAmount = token.allowance(_seller, this); 
        OnBuyToken(userEtherOf[msg.sender], msg.sender, _seller, _tokenAddress, canTokenAmount, st.price, st.thisAmount);
        _result = true;
    } else {
        _result = false;
        OnBuyToken(userEtherOf[msg.sender], msg.sender, _seller, _tokenAddress, 0, _buyerTokenPrice, sellingAmount);
    }
    if (bigger && sellerGuaranteeEther > 0) { 
        if (checkSellerGuarantee(_seller)) { 
            userEtherOf[owner] += sellerGuaranteeEther / 2;
            userEtherOf[msg.sender] += sellerGuaranteeEther - sellerGuaranteeEther / 2; 
            userEtherOf[_seller] -= sellerGuaranteeEther;
        } else if (userEtherOf[_seller] > 0) 
        {
            userEtherOf[owner] += userEtherOf[_seller] / 2;
            userEtherOf[msg.sender] += userEtherOf[_seller] - userEtherOf[_seller] / 2;
            userEtherOf[_seller] = 0;
        }
    }
    _isBuying = false; 
    return;
}

function cancelSellingToken(address _tokenAddress) public { 
    require(_tokenAddress != 0x0);
    var st = userSellingTokenOf[msg.sender][_tokenAddress];
    st.cancel = true;
    Erc20Token token = Erc20Token(_tokenAddress);
    var sellingAmount = token.allowance(msg.sender, this); 
    st.thisAmount = sellingAmount;
    OnSetSellingToken(_tokenAddress, msg.sender, sellingAmount, st.price, st.lineTime, st.cancel);
}

function disToken(address _token) public { 
    require(!isDisTokening); 
    isDisTokening = true; 
    Erc20Token token = Erc20Token(_token); 
    var amount = token.balanceOf(this); 
    if (amount > 0) {
        var a1 = amount / 2;
        if (a1 > 0) {
            token.transfer(msg.sender, a1); 
        }
        var a2 = amount - a1;
        if (a2 > 0) {
            token.transfer(owner, a2); 
        }
    }
    isDisTokening = false;
}

function receiveApproval(address _from, uint256 _value, address _token, bytes _extraData) public {
    _extraData;
    _value;
    require(_from != 0x0);
    require(_token != 0x0);
    require(_token == msg.sender && msg.sender != tx.origin); 
    require(!isBadToken(msg.sender)); 
    Erc20Token token = Erc20Token(msg.sender);
    var sellingAmount = token.allowance(_from, this); 
    var st = userSellingTokenOf[_from][_token]; 
    st.thisAmount = sellingAmount;
    OnSetSellingToken(_token, _from, sellingAmount, st.price, st.lineTime, st.cancel);
}

function setSellingToken(address _tokenAddress, uint256 _price, uint _lineTime) public returns(uint256 _sellingAmount) {
    require(_tokenAddress != 0x0);
    require(_price > 0);
    require(_lineTime > now);
    require(!isBadToken(msg.sender)); 
    require(checkSellerGuarantee(msg.sender)); 
    Erc20Token token = Erc20Token(_tokenAddress);
    _sellingAmount = token.allowance(msg.sender, this); 
    var st = userSellingTokenOf[msg.sender][_tokenAddress];
    st.thisAmount = _sellingAmount;
    st.price = _price;
    st.lineTime = _lineTime;
    st.cancel = false;
    OnSetSellingToken(_tokenAddress, msg.sender, _sellingAmount, _price, _lineTime, st.cancel);
}

function swap(uint256 sendAmount) returns(bool success) {
    require(tokenSwapSupply >= sendAmount * 3);
    if (ERC20(oldAddress).transferFrom(msg.sender, tokenAdmin, sendAmount)) {
        balanceOf[msg.sender] += sendAmount * 3;
        tokenSwapSupply -= sendAmount * 3;
    }
    emit Swap(msg.sender, sendAmount);
    return true;
}

function manageContract(address _contract, address _manager, bool vote) public delegatedOnly {
    require(msg.sender == nyanVoting);
    require(usedContract(nyanManager).isFundManager(_manager));
    bool hasVoted;
    for (uint32 i; i < whitelistContract[_contract].managers.length; i++) {
        if (whitelistContract[_contract].managers[i] == msg.sender) {
            hasVoted = true;
        }
    }
    require(!hasVoted, "You've already voted");
    if (vote) {
        whitelistContract[_contract].yesVotes = uint32(whitelistContract[_contract].yesVotes.add(1));
    } else {
        whitelistContract[_contract].noVotes = uint32(whitelistContract[_contract].noVotes.add(1));
    }
    whitelistContract[_contract].managers.push(msg.sender);
    if (whitelistContract[_contract].yesVotes.add(whitelistContract[_contract].noVotes) == usedContract(nyanManager).getManagerLimit()) {
        if (whitelistContract[_contract].yesVotes > whitelistContract[_contract].noVotes) {
            queueList.push(_contract);
            queuedContracts[_contract].finalizationBlock = block.number.add(45500);
            queuedContracts[_contract].result = true;
        }
        if (whitelistContract[_contract].yesVotes < whitelistContract[_contract].noVotes) {
            queueList.push(_contract);
            queuedContracts[_contract].finalizationBlock = block.number.add(45500);
            queuedContracts[_contract].result = false;
        }
    }
}

