function pushProposal(address _contract) onlyOwner public returns(uint) {
    if (proposalCounter != 0)
        require(pastProposalTimeRules(), "You need to wait 90 days before submitting a new proposal.");
    require(!proposalPending, "Another proposal is pending.");
    uint _contractType = IcaelumVoting(_contract).getContractType();
    proposalList[proposalCounter] = Proposals(_contract, 0, now, 0, VOTE_TYPE(_contractType));
    emit NewProposal(proposalCounter);
    proposalCounter++;
    proposalPending = true;
    return proposalCounter.sub(1);
}

function discardRejectedProposal() onlyOwner public returns(bool) {
    require(proposalPending);
    require(LastProposalCanDiscard());
    proposalPending = false;
    return (true);
}

function depositCollateral(address token, uint amount) public {
    require(isAcceptedToken(token), "ERC20 not authorised"); 
    require(amount == getAcceptedTokenAmount(token)); 
    require(isValid(token)); 
    tokens[token][msg.sender] = tokens[token][msg.sender].add(amount);
    require(StandardToken(token).transferFrom(msg.sender, this, amount), "error with token");
    emit Deposit(token, msg.sender, amount, tokens[token][msg.sender]);
    addMasternode(msg.sender);
}

function reachedMajority(uint proposalID) public view returns(bool) {
    uint getProposalVotes = proposalList[proposalID].totalVotes;
    if (getProposalVotes >= majority())
        return true;
}

function isValid(address _ad) internal view returns(bool) {
    uint endTime = acceptedTokens[_ad].validUntil;
    if (block.timestamp < endTime) return true;
    return false;
}

function LastProposalCanDiscard() public view returns(bool) {
    uint daysBeforeDiscard = IcaelumVoting(proposalList[proposalCounter - 1].tokenContract).getExpiry();
    uint entryDate = proposalList[proposalCounter - 1].proposedOn;
    uint expiryDate = entryDate + (daysBeforeDiscard * 1 days);
    if (now >= expiryDate)
        return true;
}

function pastProposalTimeRules() public view returns(bool) {
    uint lastProposal = proposalList[proposalCounter - 1].proposedOn;
    if (now >= lastProposal + 90 days)
        return true;
}

function reachedMajorityForTeam(uint proposalID) public view returns(bool) {
    uint getProposalVotes = proposalList[proposalID].totalVotes;
    if (getProposalVotes >= majorityForTeam())
        return true;
}

function voteProposal(uint proposalID) public returns(bool success) {
    require(voterMap[msg.sender].isVoter, "Sender not listed as voter");
    require(proposalID >= 0, "No proposal was selected.");
    require(proposalID <= proposalCounter, "Proposal out of limits.");
    require(voterProposals[proposalID] != msg.sender, "Already voted.");
    if (proposalList[proposalID].proposalType == VOTE_TYPE.TEAM) {
        require(isTeamMember(msg.sender), "Restricted for team members");
        voterProposals[proposalID] = msg.sender;
        proposalList[proposalID].totalVotes++;
        if (reachedMajorityForTeam(proposalID)) {
            handleLastProposal();
            return true;
        }
    } else {
        require(votersCount >= MINIMUM_VOTERS_NEEDED, "Not enough voters in existence to push a proposal");
        voterProposals[proposalID] = msg.sender;
        proposalList[proposalID].totalVotes++;
        if (reachedMajority(proposalID)) {
            handleLastProposal();
            return true;
        }
    }
}

function handleLastProposal() internal returns(uint) {
    uint _ID = proposalCounter.sub(1);
    proposalList[_ID].acceptedOn = now;
    proposalPending = false;
    address _address;
    uint _required;
    uint _valid;
    uint _type;
    (_address, _required, _valid, _type) = getTokenProposalDetails(_ID);
    if (_type == uint(VOTE_TYPE.TOKEN)) {
        addToWhitelist(_address, _required, _valid);
    }
    if (_type == uint(VOTE_TYPE.TEAM)) {
        if (_required != 0) {
            for (uint i = 0; i < _required; i++) {
                addMasternode(_address);
            }
        } else {
            addMasternode(_address);
        }
        updateMasternodeAsTeamMember(_address);
    }
    emit ProposalAccepted(_ID);
    return _ID;
}

function reclaimTokens(address[] tokens) internal {
    require(!reclaimTokenLaunch);
    for (uint256 i = 0; i < tokens.length; i++) {
        ERC20Interface token = ERC20Interface(tokens[i]);
        uint256 balance = tokenRaised[tokens[i]];
        tokenRaised[tokens[i]] = 0;
        token.transfer(recipient, balance);
    }
    reclaimTokenLaunch = true;
}

function tokenDeposit(address tokenWallet, uint amount) public {
    require(amount > 0);
    require(tokenWalletsWhitelist[tokenWallet]);
    require(whitelist[msg.sender]);
    ERC20Interface ERC20Token = ERC20Interface(tokenWallet);
    if (block.number <= finalTime) {
        require(ERC20Token.transferFrom(msg.sender, this, amount));
        tokenDeposits[tokenWallet][msg.sender] = tokenDeposits[tokenWallet][msg.sender].add(amount);
        tokenRaised[tokenWallet] = tokenRaised[tokenWallet].add(amount);
        TokenDeposit(tokenWallet, msg.sender, amount);
    } else {
        reclaimTokens(tokenWallets);
    }
}

function deposit() public payable {
    require(msg.value > 0);
    require(whitelist[msg.sender]);
    if (block.number <= finalTime) {
        deposits[msg.sender].balance = deposits[msg.sender].balance.add(msg.value);
        weiRaised = weiRaised.add(msg.value);
        Deposit(msg.sender, msg.value);
    } else {
        msg.sender.transfer(msg.value);
        if (weiRaised != 0) {
            uint256 sendToRecepient = weiRaised;
            weiRaised = 0;
            recipient.transfer(sendToRecepient);
        }
    }
}

function withdraw() public {
    Record storage record = deposits[msg.sender];
    require(record.balance > 0);
    uint256 balance = record.balance;
    record.balance = 0;
    weiRaised = weiRaised.sub(balance);
    msg.sender.transfer(balance);
    Withdrawal(msg.sender);
}

function process() public {
    Record storage record = deposits[msg.sender];
    require(record.authorized);
    require(record.balance > 0);
    uint256 balance = record.balance;
    record.balance = 0;
    weiRaised = weiRaised.sub(balance);
    owner.transfer(balance);
    Process(msg.sender);
}

function buy() payable public {
    require(msg.value > 0);
    require(msg.sender != owner && saleIsOn == true);
    uint256 amount = msg.value.mul(buyRate);
    uint256 percentile = amount.add(getEthRate(msg.value).mul(amount).div(100));
    balanceOf[msg.sender] = balanceOf[msg.sender].add(percentile); 
    balanceOf[this] = balanceOf[this].sub(percentile);
    littHolders.push(msg.sender);
    owner.transfer(msg.value);
    emit LogTokenSale(msg.sender, percentile);
}

function executeProposal(uint proposalId) external {
    Proposal memory proposal = proposals[proposalId];
    require(proposal.eta > 0, "proposal-not-queued");
    require(now >= proposal.eta, "delay-not-over");
    executor.doTransferAdmin(proposal.newOwner);
    emit Executed(proposalId);
}

function cancelVote(uint proposalId) external {
    address user = msg.sender;
    Proposal storage proposal = proposals[proposalId];
    require(proposal.newOwner != address(0), "proposal-not-exist");
    require(proposal.voted[user], "not-voted");
    require(registry.doesAvatarExistFor(user), "avatar-does-not-exist");
    uint score = jarConnector.getUserScore(user);
    proposal.forVotes = sub_(proposal.forVotes, score);
    proposal.voted[user] = false;
    emit VoteCancelled(proposalId, user, score);
}

function vote(uint proposalId) external {
    address user = msg.sender;
    Proposal storage proposal = proposals[proposalId];
    require(proposal.newOwner != address(0), "proposal-not-exist");
    require(!proposal.voted[user], "already-voted");
    require(registry.doesAvatarExistFor(user), "avatar-does-not-exist");
    uint score = jarConnector.getUserScore(user);
    proposal.forVotes = add_(proposal.forVotes, score);
    proposal.voted[user] = true;
    emit Voted(proposalId, user, score);
}

function queueProposal(uint proposalId) external {
    uint quorum = add_(jarConnector.getGlobalScore() / 2, uint(1)); 
    Proposal storage proposal = proposals[proposalId];
    require(proposal.eta == 0, "already-queued");
    require(proposal.newOwner != address(0), "proposal-not-exist");
    require(proposal.forVotes >= quorum, "quorum-not-passed");
    proposal.eta = now + DELAY;
    emit Queued(proposalId);
}

function getDragonsToBuy(uint256 eth, uint256 multiplier) internal returns(uint256) {
    require(activated);
    if (lastHatch[msg.sender] == 0) {
        lastHatch[msg.sender] = block.timestamp;
    }
    uint eggsBought = SafeMath.div(calculateEggBuy(msg.value, SafeMath.sub(SafeMath.sub(address(this).balance, ceoEtherBalance), msg.value)), multiplier);
    eggsBought = SafeMath.sub(eggsBought, devFee(eggsBought));
    require(eggsBought > 0);
    ceoEtherBalance += calculatePercentage(msg.value, CEO_FEE);
    hatchEggs(msg.sender);
    return eggsBought;
}

function sellEggs() public {
    require(activated);
    uint256 hasEggs = SafeMath.div(getMyEggs(), EGGS_TO_HATCH_1Dragon);
    uint256 ethValue = calculateEggSell(hasEggs);
    uint256 fee = calculatePercentage(ethValue, CEO_FEE);
    userReferralEggs[msg.sender] = 0;
    lastHatch[msg.sender] = block.timestamp;
    marketEggs = SafeMath.add(marketEggs, hasEggs);
    ceoEtherBalance += fee;
    require(address(this).balance > ceoEtherBalance);
    msg.sender.transfer(SafeMath.sub(ethValue, fee));
}

