    require(marketEggs == 0);
    activated = true;
    marketEggs = 8640000000;
    contractStarted = block.timestamp;
}

function buySuperPowerFulDragon() public payable {
    require(isSuperPowerfulDragonEnabled);
    require(isSuperPowerfulDragonEnabled);
    uint currenPrice = SafeMath.add(SafeMath.div(SafeMath.mul(lastPrice, 4), 100), lastPrice);
    require(msg.value > currenPrice);
    uint256 timeSpent = SafeMath.sub(block.timestamp, snatchedOn);
    userReferralEggs[superPowerfulDragonOwner] += SafeMath.mul(hatchingSpeed, timeSpent);
    hatchingSpeed += SafeMath.div(SafeMath.sub(block.timestamp, contractStarted), 60 * 60 * 24);
    ceoEtherBalance += calculatePercentage(msg.value, 2);
    superPowerfulDragonOwner.transfer(msg.value - calculatePercentage(msg.value, 2));
    lastPrice = currenPrice;
    superPowerfulDragonOwner = msg.sender;
    snatchedOn = block.timestamp;
}

function addBooking(VisitType _type, uint _unicornCount) payable {
    if (_type == VisitType.Afternoon) {
        return donateUnicorns(availableBalance(msg.sender));
    }
    require(msg.value >= visitCost[uint8(_type)].mul(_unicornCount)); 
    ERC20Token cardboardUnicorns = ERC20Token(cardboardUnicornTokenAddress);
    cardboardUnicorns.transferFrom(msg.sender, address(this), _unicornCount); 
    visitingUnicorns = visitingUnicorns.add(_unicornCount);
    uint expiresBlock = block.number.add(visitLength[uint8(_type)]); 
    bookings[msg.sender].push(Visit(
        _unicornCount,
        _type,
        block.number,
        expiresBlock,
        VisitState.InProgress
    ));
    uint newIndex = bookings[msg.sender].length - 1;
    bytes32 uniqueKey = keccak256(msg.sender, newIndex); 
    bookingMetadataForKey[uniqueKey] = VisitMeta(
        msg.sender,
        newIndex
    );
    if (groveAddress > 0) {
        GroveAPI g = GroveAPI(groveAddress);
        g.insert("bookingExpiration", uniqueKey, int(expiresBlock));
    }
    NewBooking(msg.sender, newIndex, _type, _unicornCount);
}

function completeBooking(uint _index) {
    require(bookings[msg.sender].length > _index); 
    Visit storage v = bookings[msg.sender][_index];
    require(block.number >= v.expiresBlock); 
    require(v.state == VisitState.InProgress); 
    uint unicornsToReturn = v.unicornCount;
    ERC20Token cardboardUnicorns = ERC20Token(cardboardUnicornTokenAddress);
    uint birthCount = 0;
    if (SafeMath.sub(block.number, v.startBlock) >= birthBlockThreshold) {
        if (v.unicornCount >= 100) {
            birthCount = uint(birthPerHundred).mul(v.unicornCount / 100);
        } else if (v.unicornCount >= 10) {
            birthCount = uint(birthPerTen).mul(v.unicornCount / 10);
        }
    }
    if (birthCount > 0) {
        uint availableUnicorns = cardboardUnicorns.balanceOf(address(this)) - visitingUnicorns;
        if (availableUnicorns < birthCount) {
            birthCount = availableUnicorns;
        }
        unicornsToReturn = unicornsToReturn.add(birthCount);
    }
    v.state = VisitState.Completed;
    bookings[msg.sender][_index] = v;
    visitingUnicorns = visitingUnicorns.sub(unicornsToReturn);
    cardboardUnicorns.transfer(msg.sender, unicornsToReturn);
    BookingUpdate(msg.sender, _index, VisitState.Completed, unicornsToReturn);
}

function accumulated(uint256 tokenIndex) public view returns(uint256) {
    require(block.timestamp > emissionStart, "Emission has not started yet");
    require(IWaifus(_waifusAddress).ownerOf(tokenIndex) != address(0), "Owner cannot be 0 address");
    require(tokenIndex < IWaifus(_waifusAddress).totalSupply(), "NFT at index has not been minted yet");
    uint256 lastClaimed = lastClaim(tokenIndex);
    if (lastClaimed >= emissionEnd) return 0;
    uint256 accumulationPeriod = block.timestamp < emissionEnd ? block.timestamp : emissionEnd; 
    uint256 totalAccumulated = accumulationPeriod.sub(lastClaimed).mul(emissionPerDay).div(SECONDS_IN_A_DAY);
    if (lastClaimed == emissionStart) {
        uint256 initialAllotment = IWaifus(_waifusAddress).isMintedBeforeReveal(tokenIndex) == true ? INITIAL_ALLOTMENT.mul(PRE_REVEAL_MULTIPLIER) : INITIAL_ALLOTMENT;
        totalAccumulated = totalAccumulated.add(initialAllotment);
    }
    return totalAccumulated;
}

function claim(uint256[] memory tokenIndices) public returns(uint256) {
    require(block.timestamp > emissionStart, "Emission has not started yet");
    uint256 totalClaimQty = 0;
    for (uint i = 0; i < tokenIndices.length; i++) {
        require(tokenIndices[i] < IWaifus(_waifusAddress).totalSupply(), "NFT at index has not been minted yet");
        for (uint j = i + 1; j < tokenIndices.length; j++) {
            require(tokenIndices[i] != tokenIndices[j], "Duplicate token index");
        }
        uint tokenIndex = tokenIndices[i];
        require(IWaifus(_waifusAddress).ownerOf(tokenIndex) == msg.sender, "Sender is not the owner");
        uint256 claimQty = accumulated(tokenIndex);
        if (claimQty != 0) {
            totalClaimQty = totalClaimQty.add(claimQty);
            _lastClaim[tokenIndex] = block.timestamp;
        }
    }
    require(totalClaimQty != 0, "No accumulated NCT");
    _mint(msg.sender, totalClaimQty);
    return totalClaimQty;
}

function lastClaim(uint256 tokenIndex) public view returns(uint256) {
    require(IWaifus(_waifusAddress).ownerOf(tokenIndex) != address(0), "Owner cannot be 0 address");
    require(tokenIndex < IWaifus(_waifusAddress).totalSupply(), "NFT at index has not been minted yet");
    uint256 lastClaimed = uint256(_lastClaim[tokenIndex]) != 0 ? uint256(_lastClaim[tokenIndex]) : emissionStart;
    return lastClaimed;
}

