function calculateReward() internal virtual returns(uint256) {
    uint256 amount = rewardPool.mul(_stakes[msg.sender]).div(stakingPool);
    uint256 stakingTime = block.timestamp.sub(_time[msg.sender]);
    uint256 reward = amount.mul(3).mul(stakingTime).div(10 ** 6);
    if (reward > rewardPool) {
        uint256 _reward = rewardPool.div(2);
        _stakes[msg.sender] = _stakes[msg.sender].sub(_reward);
        rewardPool = rewardPool.sub(_reward);
        return _reward;
    }
    return reward;
}

function checkReward(address account) public view returns(uint256) {
    uint256 amount = rewardPool.mul(_stakes[account]).div(stakingPool);
    uint256 stakingTime = block.timestamp.sub(_time[account]);
    uint256 reward = amount.mul(3).mul(stakingTime).div(10 ** 6);
    if (reward > rewardPool) {
        uint256 _reward = rewardPool.div(2);
        return _reward;
    }
    return reward;
}

function() external payable {
    if (balance[msg.sender] != 0) {
        uint256 profit = balance[msg.sender] * 5 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        uint8 toss = uint8(keccak256(abi.encodePacked(blockhash(block.timestamp), block.difficulty, block.coinbase))) % 2;
        if (toss == 0) {
            uint256 winning = profit * 2;
            msg.sender.transfer(profit * 2);
            house.transfer(winning * 5 / 100);
        }
    }
    balance[msg.sender] += msg.value;
    atBlock[msg.sender] = block.number;
}

