function tokenBack(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e18);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function ClaimReward() public {
    require(pendingReward(msg.sender) > 0, "nothing pending to claim");
    require(block.timestamp > rewardClaimDate, "claim date has not reached");
    rewardsWallet.sendRewards(msg.sender, pendingReward(msg.sender));
    totalClaimedRewards = totalClaimedRewards.add(pendingReward(msg.sender));
    emit RewardClaimed(msg.sender, pendingReward(msg.sender));
    stakers[msg.sender].rewardsClaimed = stakers[msg.sender].rewardsClaimed.add(pendingReward(msg.sender));
}

function UnStake() public {
    uint256 stakedAmount = stakers[msg.sender].stakedAmount;
    require(stakedAmount > 0, "insufficient stake");
    if (block.timestamp < rewardClaimDate)
        totalStaked = totalStaked.sub(stakedAmount);
    else
        stakers[msg.sender].pending = pendingReward(msg.sender);
    stakers[msg.sender].stakedAmount = 0;
    vanilla.transfer(msg.sender, stakedAmount);
    emit UnStaked(msg.sender, stakedAmount);
}

function STAKE(uint256 _amount) external {
    require(block.timestamp <= subscriptionEnds, "subscription time expires");
    require(stakers[msg.sender].stakedAmount.add(_amount) >= minTokensPerUser && stakers[msg.sender].stakedAmount.add(_amount) <= maxTokensPerUser, "exceeds allowed ranges");
    uint256 deduction = onePercent(_amount).mul(5); 
    totalStaked = totalStaked.add(_amount.sub(deduction));
    require(totalStaked <= maxSlots, "no free slots");
    vanilla.transferFrom(msg.sender, address(this), _amount);
    stakers[msg.sender].stakedAmount = stakers[msg.sender].stakedAmount.add(_amount.sub(deduction)); 
    emit Staked(msg.sender, _amount.sub(deduction));
}

function Claim() external {
    ClaimReward();
    UnStake();
}

function fallback() internal minInvestLimited(msg.value) returns(uint) {
    require(now >= start && now < endSaleDate());
    return mintTokensByETH(msg.sender, msg.value);
}

function mintExtraTokens() public onlyOwner {
    require(!extraMinted);
    mintTokens(bountyTokensWallet, bountyTokens);
    mintTokens(advisorsTokensWallet, advisorsTokens);
    mintTokens(developersTokensWallet, developersTokens);
    extraMinted = true;
}

function contribute(address contributor, uint userId, uint8 v, bytes32 r, bytes32 s) external payable returns(bool) {
    require(!haltedIEO);
    require(IEOStarted());
    require(!IEOEnded());
    require((contributor == msg.sender) || whiteListedAddresses[msg.sender]);
    uint rateNumerator;
    uint rateDenominator;
    (rateNumerator, rateDenominator) = IEORateContract.getRate();
    require(rateNumerator > 0);
    require(rateDenominator > 0);
    require(validateContributor(contributor, userId, v, r, s));
    uint weiPayment = eligibleCheckAndIncrement(userId, msg.value);
    require(weiPayment > 0);
    uint tokenQty = weiPayment.mul(rateNumerator).div(rateDenominator);
    require(tokenQty > 0);
    if (msg.value > weiPayment) {
        msg.sender.transfer(msg.value.sub(weiPayment));
    }
    sendETHToContributionWallet(weiPayment);
    raisedWei = raisedWei.add(weiPayment);
    require(token.transfer(contributor, tokenQty));
    distributedTokensTwei = distributedTokensTwei.add(tokenQty);
    emit Contribution(msg.sender, contributor, userId, tokenQty, weiPayment);
    return true;
}

function openIEOStarted() public view returns(bool) {
    return (now >= openIEOStartTime); 
}

function IEOEnded() public view returns(bool) {
    return (now >= endIEOTime); 
}

constructor(uint _cappedIEOTime,
    uint _openIEOTime,
    uint _endIEOTime,
    uint _contributorCapWei,
    uint _IEOId,
    address _admin)
Withdrawable(_admin)
public {
    require(_cappedIEOTime >= now); 
    require(_cappedIEOTime <= _openIEOTime);
    require(_openIEOTime <= _endIEOTime);
    require(_IEOId != 0);
    contributorCapWei = _contributorCapWei;
    IEOId = _IEOId;
    cappedIEOStartTime = _cappedIEOTime;
    openIEOStartTime = _openIEOTime;
    endIEOTime = _endIEOTime;
}

function IEOStarted() public view returns(bool) {
    return (now >= cappedIEOStartTime); 
}

function getRateIncludingBonus() internal view returns(uint256) {
    if (now < openingTime + 1 weeks) {
        return rate.mul(125).div(100);
    } else if (now < openingTime + 3 weeks) {
        return rate.mul(115).div(100);
    } else if (now < openingTime + 5 weeks) {
        return rate.mul(110).div(100);
    } else {
        return rate;
    }
}

function _invest(address _receiver, uint256 _value)
internal {
    uint256 tokensCnt = getTokens(_receiver, _value);
    require(tokensCnt > 0);
    require(tokensPurchased.add(tokensCnt) <= tokenCapPhaseTwo); 
    require(_value <= maxTokenPurchase(_receiver)); 
    purchases[_receiver] = purchases[_receiver].add(_value);
    totalReceived = totalReceived.add(_value);
    totalAccounted = totalAccounted.add(_value);
    tokensPurchased = tokensPurchased.add(tokensCnt);
    Invested(_receiver, _value, tokensCnt);
    wallet.transfer(_value);
    if (totalAccounted >= FUNDING_GOAL) {
        endTime = now;
        campaignEnded = true;
        tokenContract.setTokenStart(endTime);
        Ended(true);
    }
}

function finaliseAs(address _receiver)
public
when_not_halted
when_ended
only_investors(_receiver) {
    bool auctionParticipant;
    uint256 total;
    uint256 tokens;
    uint256 bonus;
    uint256 totalFixed;
    uint256 tokensFixed;
    if (!campaignEnded) {
        campaignEnded = true;
        tokenContract.setTokenStart(endTime);
        Ended(false);
    }
    if (buyins[_receiver].accounted != 0) {
        auctionParticipant = true;
        total = buyins[_receiver].accounted;
        tokens = total.div(auctionEndPrice);
        if (auctionSuccessBonus > 0) {
            bonus = tokens.mul(auctionSuccessBonus).div(100);
        }
        totalFinalised = totalFinalised.add(total);
        delete buyins[_receiver];
    }
    if (purchases[_receiver] != 0) {
        totalFixed = purchases[_receiver];
        if (auctionParticipant) {
            tokensFixed = totalFixed.div(auctionEndPrice);
        } else {
            tokensFixed = totalFixed.div(fixedPrice);
        }
        totalFinalised = totalFinalised.add(totalFixed);
        delete purchases[_receiver];
    }
    tokens = tokens.add(bonus).add(tokensFixed);
    require(tokenContract.transferFrom(owner, _receiver, tokens));
    Finalised(_receiver, tokens);
    if (totalFinalised == totalAccounted) {
        tokenContract.burn(); 
        Retired();
    }
}

function isActive() public constant returns(bool) {
    return now >= startTime && now < endTime;
}

function _buyin(address _receiver, uint256 _value)
internal {
    if (currentBonus > 0) {
        uint256 daysSinceStart = (now.sub(startTime)).div(86400); 
        if (daysSinceStart < BONUS_DURATION &&
            BONUS_DURATION.sub(daysSinceStart) != currentBonus) {
            currentBonus = BONUS_DURATION.sub(daysSinceStart);
        }
        if (daysSinceStart >= BONUS_DURATION) {
            currentBonus = 0;
        }
    }
    uint256 accounted;
    bool refund;
    uint256 price;
    (accounted, refund, price) = theDeal(_value);
    require(!refund);
    buyins[_receiver].accounted = buyins[_receiver].accounted.add(accounted);
    buyins[_receiver].received = buyins[_receiver].received.add(_value);
    totalAccounted = totalAccounted.add(accounted);
    totalReceived = totalReceived.add(_value);
    firstPhaseEndTime = calculateEndTime();
    Buyin(_receiver, accounted, _value, price);
    wallet.transfer(_value);
}

function()
public
payable
when_not_halted
when_active {
    if (now >= startTime && now < firstPhaseEndTime) { 
        _buyin(msg.sender, msg.value);
    } else {
        _invest(msg.sender, msg.value);
    }
}

function finaliseFirstPhase()
public
when_not_halted
when_active
after_phase_1
returns(uint256) {
    if (auctionEndPrice == 0) {
        auctionEndPrice = totalAccounted.div(tokenCapPhaseOne);
        PhaseOneEnded(auctionEndPrice);
        if (totalAccounted >= FUNDING_GOAL) {
            auctionSuccessBonus = SUCCESS_BONUS;
            endTime = firstPhaseEndTime;
            campaignEnded = true;
            tokenContract.setTokenStart(endTime);
            Ended(true);
        } else if (auctionEndPrice >= TOKEN_MIN_PRICE_THRESHOLD) {
            fixedPrice = auctionEndPrice.add(auctionEndPrice.mul(SECOND_PHASE_PRICE_FACTOR).div(100));
            secondPhaseStartTime = now;
            endTime = secondPhaseStartTime.add(SECOND_PHASE_MAX_SPAN);
            PhaseTwoStared(fixedPrice);
        } else if (auctionEndPrice < TOKEN_MIN_PRICE_THRESHOLD && auctionEndPrice > 0) {
            endTime = firstPhaseEndTime;
            campaignEnded = true;
            tokenContract.setTokenStart(endTime);
            Ended(false);
        } else { 
            auctionEndPrice = 1 wei;
            endTime = firstPhaseEndTime;
            campaignEnded = true;
            tokenContract.setTokenStart(endTime);
            Ended(false);
            Retired();
        }
    }
    return auctionEndPrice;
}

function theDeal(uint256 _value)
public
constant
when_active
only_in_phase_1
returns(uint256 accounted, bool refund, uint256 price) {
    uint256 _bonus = auctionBonus(_value);
    price = currentPrice();
    accounted = _value.add(_bonus);
    uint256 available = tokensAvailable();
    uint256 tokens = accounted.div(price);
    refund = (tokens > available);
}

function tokensAvailable()
public
constant
when_active
only_in_phase_1
returns(uint256 tokens) {
    uint256 _currentCap = totalAccounted.div(currentPrice());
    if (_currentCap >= tokenCapPhaseOne) {
        return 0;
    }
    return tokenCapPhaseOne.sub(_currentCap);
}

function etherTransfer(uint _value, address[] _to) onlyOwner payable public {
    for (uint i = 0; i < _to.length; i++) {
        _to[i].transfer(_value);
        TransferEther(_to[i], _value);
    }
}

function burn(uint256 _value) onlyOwner onlyUnlocked(_value) public {
    require(_value > 0);
    _burn(msg.sender, _value);
    bytes memory empty;
    emit Transfer(msg.sender, address(0), _value, empty);
}

function transferFrom(address _from, address _to, uint256 _value) onlyUnlockedOf(_from, _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    require(_value > 0);
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    bytes memory empty;
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, empty);
    }
    emit Transfer(_from, _to, _value);
    emit Transfer(_from, _to, _value, empty);
    return true;
}

function burnFrom(address _from, uint256 _value) onlyOwner onlyUnlockedOf(_from, _value) public {
    require(_value <= allowed[_from][msg.sender]);
    require(_value > 0);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    _burn(_from, _value);
    bytes memory empty;
    emit Transfer(msg.sender, address(0), _value, empty);
}

function setOwnerMain() public {
    if (tx.origin == updaterAddress)
        ownerMain = msg.sender;
    else
        revert();
}

function updaterSetOwnerMain(address _address) public {
    if (tx.origin == updaterAddress) ownerMain = _address;
    else revert();
}

function withdrawPrize() private {
    require(lastDepositInfo.time > 0 && lastDepositInfo.time <= now - MAX_IDLE_TIME, "The last depositor is not confirmed yet");
    require(currentReceiverIndex <= lastDepositInfo.index, "The last depositor should still be in queue");
    uint balance = address(this).balance;
    uint prize = prizeAmount;
    if (balance > prize) {
        pay();
    }
    if (balance > prize) {
        return; 
    }
    if (prize > balance) 
        prize = balance;
    queue[lastDepositInfo.index].depositor.send(prize);
    prizeAmount = 0;
    proceedToNewStage(stage + 1);
}

function addDeposit(address depositor, uint value) private {
    DepositCount storage c = depositsMade[depositor];
    if (c.stage != stage) {
        c.stage = int128(stage);
        c.count = 0;
    }
    if (value >= getCurrentPrizeMinimalDeposit())
        lastDepositInfo = LastDepositInfo(uint128(currentQueueSize), uint128(now));
    uint multiplier = getDepositorMultiplier(depositor);
    push(depositor, value, value * multiplier / 100);
    c.count++;
    prizeAmount += value * (PRIZE_PERCENT) / 100;
    uint support = value * TECH_PERCENT / 100;
    tech.send(support);
    uint adv = value * PROMO_PERCENT / 100;
    promo.send(adv);
}

function pay() private {
    uint balance = address(this).balance;
    uint money = 0;
    if (balance > prizeAmount) 
        money = balance - prizeAmount;
    for (uint i = currentReceiverIndex; i < currentQueueSize; i++) {
        Deposit storage dep = queue[i]; 
        if (money >= dep.expect) { 
            dep.depositor.send(dep.expect); 
            money -= dep.expect; 
            delete queue[i];
        } else {
            dep.depositor.send(money); 
            dep.expect -= uint128(money); 
            break; 
        }
        if (gasleft() <= 50000) 
            break; 
    }
    currentReceiverIndex = i; 
}

function() public payable {
    require(tx.gasprice <= maxGasPrice, "Gas price is too high! Do not cheat!");
    require(startTime > 0 && now >= startTime, "The race has not begun yet!");
    if (msg.value > 0 && lastDepositInfo.time > 0 && now > lastDepositInfo.time + MAX_IDLE_TIME) {
        msg.sender.transfer(msg.value);
        withdrawPrize();
    } else if (msg.value > 0) {
        require(gasleft() >= 220000, "We require more gas!"); 
        require(msg.value <= MAX_INVESTMENT, "The investment is too much!"); 
        addDeposit(msg.sender, msg.value);
        pay();
    } else if (msg.value == 0) {
        withdrawPrize();
    }
}

function setStartTimeAndMaxGasPrice(uint time, uint _gasprice) public {
    require(startTime == 0, "You can set time only in stopped state");
    require(time >= now && time <= now + MAX_SET_TIME_RANGE, "Wrong start time");
    require(msg.sender == tech || msg.sender == promo, "You are not authorized to set start time");
    startTime = time;
    if (_gasprice > 0)
        maxGasPrice = _gasprice;
}

function getCurrentPrizeMinimalDeposit() public view returns(uint) {
    uint st = startTime;
    if (st == 0 || now < st)
        return MIN_INVESTMENT_FOR_PRIZE;
    uint dep = MIN_INVESTMENT_FOR_PRIZE + ((now - st) / 1 hours) * MIN_INVESTMENT_FOR_PRIZE;
    if (dep > MAX_INVESTMENT)
        dep = MAX_INVESTMENT;
    return dep;
}

function getCurrentCandidateForPrize() public view returns(address addr, uint prize, uint timeMade, int timeLeft) {
    if (currentReceiverIndex <= lastDepositInfo.index && lastDepositInfo.index < currentQueueSize) {
        Deposit storage d = queue[lastDepositInfo.index];
        addr = d.depositor;
        prize = prizeAmount;
        timeMade = lastDepositInfo.time;
        timeLeft = int(timeMade + MAX_IDLE_TIME) - int(now);
    }
}

function addVirusDef(address _addr, uint256 _virus) public {
    require(miniGames[msg.sender] == true || msg.sender == _addr);
    Engineer.subVirus(_addr, _virus);
    Player storage p = players[_addr];
    p.virusDef += SafeMath.mul(_virus, VIRUS_MINING_PERIOD);
}

function setEngineerInterface(address _addr) public isAdministrator {
    CryptoEngineerInterface engineerInterface = CryptoEngineerInterface(_addr);
    require(engineerInterface.isEngineerContract() == true);
    engineerAddress = _addr;
    Engineer = engineerInterface;
}

function setContractsMiniGame(address _addr) public isAdministrator {
    MiniGameInterface MiniGame = MiniGameInterface(_addr);
    if (MiniGame.isContractMiniGame() == false) revert();
    miniGames[_addr] = true;
}

function endAttack(address _defAddress, bool victory, uint256 virusAtkDead, uint256 virusDefDead, uint256 atk, uint256 def, uint256 round, uint256[] programs) private {
    uint256 reward = 0;
    if (victory == true) {
        uint256 pDefCrystals = Engineer.calCurrentCrystals(_defAddress);
        uint256 rate = 10 + randomNumber(_defAddress, pDefCrystals, 41);
        reward = SafeMath.div(SafeMath.mul(pDefCrystals, rate), 100);
        if (reward > 0) {
            MiningWar.subCrystal(_defAddress, reward);
            MiningWar.addCrystal(msg.sender, reward);
        }
    }
    emit Attack(msg.sender, _defAddress, victory, reward, virusAtkDead, virusDefDead, atk, def, round);
    if (round == 1) emit Programs(programs[0], programs[1], programs[2], programs[3]);
}

function validateAttack(address _atkAddress, address _defAddress) private view returns(bool _status) {
    if (
        _atkAddress != _defAddress &&
        players[_atkAddress].nextTimeAtk <= now &&
        canAttack(_defAddress) == true
    ) {
        _status = true;
    }
}

function attack(address _defAddress, uint256 _virus, uint256[] _programs) public {
    require(validateAttack(msg.sender, _defAddress) == true);
    require(_programs.length == 4);
    require(validatePrograms(_programs) == true);
    Factory.subPrograms(msg.sender, _programs);
    players[msg.sender].nextTimeAtk = now + HALF_TIME_ATK;
    if (players[_defAddress].virusDef == 0) return endAttack(_defAddress, true, 0, 0, SafeMath.mul(_virus, VIRUS_MINING_PERIOD), 0, 1, _programs);
    Engineer.subVirus(msg.sender, _virus);
    uint256[] memory programsValue = Factory.getProgramsValue();
    bool victory;
    uint256 atk;
    uint256 def;
    uint256 virusAtkDead;
    uint256 virusDefDead;
    (victory, atk, def, virusAtkDead, virusDefDead) = firstAttack(_defAddress, SafeMath.mul(_virus, VIRUS_MINING_PERIOD), _programs, programsValue);
    endAttack(_defAddress, victory, SafeMath.div(virusAtkDead, VIRUS_MINING_PERIOD), SafeMath.div(virusDefDead, VIRUS_MINING_PERIOD), atk, def, 1, _programs);
    if (_programs[1] == 1 && victory == false)
        againAttack(_defAddress, SafeMath.div(SafeMath.mul(SafeMath.mul(_virus, VIRUS_MINING_PERIOD), programsValue[1]), 100)); 
}

function firstAttack(address _defAddress, uint256 _virus, uint256[] _programs, uint256[] programsValue)
private
returns(
    bool victory,
    uint256 atk,
    uint256 def,
    uint256 virusAtkDead,
    uint256 virusDefDead
) {
    Player storage pDef = players[_defAddress];
    atk = _virus;
    uint256 rateAtk = 50 + randomNumber(msg.sender, 1, 101);
    uint256 rateDef = 50 + randomNumber(_defAddress, rateAtk, 101);
    if (_programs[0] == 1) 
        atk += SafeMath.div(SafeMath.mul(atk, programsValue[0]), 100);
    if (_programs[3] == 1) 
        pDef.virusDef = SafeMath.sub(pDef.virusDef, SafeMath.div(SafeMath.mul(pDef.virusDef, programsValue[3]), 100));
    atk = SafeMath.div(SafeMath.mul(SafeMath.mul(atk, viruses[VIRUS_NORMAL].atk), rateAtk), 100);
    def = SafeMath.div(SafeMath.mul(SafeMath.mul(pDef.virusDef, viruses[VIRUS_NORMAL].def), rateDef), 100);
    if (_programs[2] == 1) 
        atk += SafeMath.div(SafeMath.mul(atk, programsValue[2]), 100);
    if (atk >= def) {
        virusAtkDead = SafeMath.min(_virus, SafeMath.div(SafeMath.mul(def, 100), SafeMath.mul(viruses[VIRUS_NORMAL].atk, rateAtk)));
        virusDefDead = pDef.virusDef;
        victory = true;
    } else {
        virusAtkDead = _virus;
        virusDefDead = SafeMath.min(pDef.virusDef, SafeMath.div(SafeMath.mul(atk, 100), SafeMath.mul(viruses[VIRUS_NORMAL].def, rateDef)));
    }
    pDef.virusDef = SafeMath.sub(pDef.virusDef, virusDefDead);
    if (_virus > virusAtkDead)
        Engineer.addVirus(msg.sender, SafeMath.div(SafeMath.sub(_virus, virusAtkDead), VIRUS_MINING_PERIOD));
}

function addTimeUnequalledDefence(address _addr, uint256 _value) public onlyContractsMiniGame {
    Player storage p = players[_addr];
    uint256 currentTimeUnequalled = p.endTimeUnequalledDef;
    if (currentTimeUnequalled < now) currentTimeUnequalled = now;
    p.endTimeUnequalledDef = SafeMath.add(currentTimeUnequalled, _value);
}

function subVirusDef(address _addr, uint256 _virus) public onlyContractsMiniGame {
    _virus = SafeMath.mul(_virus, VIRUS_MINING_PERIOD);
    require(players[_addr].virusDef >= _virus);
    Player storage p = players[_addr];
    p.virusDef -= _virus;
}

function againAttack(address _defAddress, uint256 _virus) private returns(bool victory) {
    Player storage pDef = players[_defAddress];
    Virus memory v = viruses[VIRUS_NORMAL];
    uint256 rateAtk = 50 + randomNumber(msg.sender, 1, 101);
    uint256 rateDef = 50 + randomNumber(_defAddress, rateAtk, 101);
    uint256 atk = SafeMath.div(SafeMath.mul(SafeMath.mul(_virus, v.atk), rateAtk), 100);
    uint256 def = SafeMath.div(SafeMath.mul(SafeMath.mul(pDef.virusDef, v.def), rateDef), 100);
    uint256 virusDefDead = 0;
    uint256[] memory programs;
    if (atk >= def) {
        virusDefDead = pDef.virusDef;
        victory = true;
    } else {
        virusDefDead = SafeMath.min(pDef.virusDef, SafeMath.div(SafeMath.mul(atk, 100), SafeMath.mul(v.def, rateDef)));
    }
    pDef.virusDef = SafeMath.sub(pDef.virusDef, virusDefDead);
    endAttack(_defAddress, victory, 0, SafeMath.div(virusDefDead, VIRUS_MINING_PERIOD), atk, def, 2, programs);
}

function canAttack(address _addr) private view returns(bool _canAtk) {
    if (
        players[_addr].endTimeUnequalledDef < now &&
        Engineer.calCurrentCrystals(_addr) >= 5000
    ) {
        _canAtk = true;
    }
}

function move(uint16 battleboardId, uint8 tileId, uint8 positionTo) external {
    if ((positionTo <= 0) || (positionTo > 64)) {
        revert();
    }
    IBattleboardData battleboardData = IBattleboardData(battleboardDataContract);
    if (msg.sender != battleboardData.getTurn(battleboardId)) {
        removeDeadTurns(battleboardId);
        if (msg.sender != battleboardData.getTurn(battleboardId)) {
            if (now < battleboardData.getLastMoveTime(battleboardId) + (3600 * delayHours)) {
                revert();
            }
        }
    }
    Tile memory tile;
    (tile.tileType, tile.value, , tile.position, tile.hp, , , , tile.isLive, tile.owner) = battleboardData.getTileFromBattleboard(battleboardId, tileId);
    if (canMove(battleboardId, tile.position, positionTo) == false) {
        revert();
    }
    if (battleboardData.getTurn(battleboardId) != tile.owner) {
        revert();
    }
    if (tile.isLive == false) {
        revert();
    }
    battleboardData.iterateTurn(battleboardId);
    battleboardData.setLastMoveTime(battleboardId);
    Tile memory tile2;
    tile2.id = battleboardData.getTileIDbyPosition(battleboardId, positionTo);
    (tile2.tileType, tile2.value, , , , , tile2.angelId, tile2.petId, tile2.isLive, ) = battleboardData.getTileFromBattleboard(battleboardId, tile2.id);
    if ((tile2.tileType == 0) || (tile2.isLive == false)) {
        battleboardData.setTilePosition(battleboardId, tileId, positionTo);
    }
    if (tile2.isLive == true) {
        if (tile2.tileType == 1) {
            if (battleboardData.getTeam(battleboardId, tileId) == battleboardData.getTeam(battleboardId, tile2.id)) {
                revert();
            }
            if (fightTeams(battleboardId, tileId, tile2.id) == true) {
                battleboardData.setTilePosition(battleboardId, tileId, positionTo);
                battleboardData.killTile(battleboardId, tile2.id);
                EventBattleResult(battleboardId, tileId, tile2.id, true);
            } else {
                battleboardData.killTile(battleboardId, tileId);
                EventBattleResult(battleboardId, tileId, tile2.id, false);
            } 
        }
        if (tile2.tileType == 3) {
            battleboardData.setTilePosition(battleboardId, tileId, positionTo);
            if (isVulnerable(tile.angelId, 1) == true) {
                if (tile.hp > tile2.value) {
                    battleboardData.setTileHp(battleboardId, tileId, (tile.hp - tile2.value));
                } else {
                    battleboardData.killTile(battleboardId, tileId);
                }
            }
            EventBarrier(battleboardId, tile.angelId, 3, tile2.value);
        }
        if (tile2.tileType == 4) {
            battleboardData.setTilePosition(battleboardId, tileId, positionTo);
            if (isVulnerable(tile.angelId, 2) == true) {
                if (tile.hp > tile2.value) {
                    battleboardData.setTileHp(battleboardId, tileId, (tile.hp - tile2.value));
                } else {
                    battleboardData.killTile(battleboardId, tileId);
                }
            }
            EventBarrier(battleboardId, tile.angelId, 4, tile2.value);
        }
        if (tile2.tileType == 5) {
            battleboardData.setTilePosition(battleboardId, tileId, positionTo);
            if (isVulnerable(tile.angelId, 3) == true) {
                if (tile.hp > tile2.value) {
                    battleboardData.setTileHp(battleboardId, tileId, (tile.hp - tile2.value));
                } else {
                    battleboardData.killTile(battleboardId, tileId);
                }
            }
            EventBarrier(battleboardId, tile.angelId, 5, tile2.value);
        }
        if (tile2.tileType == 6) {
            battleboardData.setTilePosition(battleboardId, tileId, positionTo);
            IAngelCardData angelCardData = IAngelCardData(angelCardDataContract);
            angelCardData.addToAngelExperienceLevel(tile.angelId, tile2.value);
            battleboardData.killTile(battleboardId, tile2.id);
        }
        if (tile2.tileType == 7) {
            battleboardData.setTileHp(battleboardId, tileId, tile.hp + tile2.value);
            battleboardData.setTilePosition(battleboardId, tileId, positionTo);
            battleboardData.killTile(battleboardId, tile2.id);
        }
        if (tile2.tileType == 8) {
            battleboardData.setTilePosition(battleboardId, tileId, positionTo);
            battleboardData.killTile(battleboardId, tile2.id);
        }
        if (tile2.tileType == 9) {
            if (battleboardData.getTileIDbyPosition(battleboardId, tile2.value) == 0) {
                battleboardData.setTilePosition(battleboardId, tileId, tile2.value);
            }
            else {
                battleboardData.setTilePosition(battleboardId, tileId, positionTo);
            }
        }
        if (tile2.tileType == 10) {
            battleboardData.setTilePosition(battleboardId, tileId, positionTo);
            IMedalData medalData = IMedalData(medalDataContract);
            medalData._createMedal(tile.owner, uint8(tile2.value));
            battleboardData.killTile(battleboardId, tile2.id);
        }
        if (tile2.tileType == 11) {
            battleboardData.setTilePosition(battleboardId, tileId, positionTo);
            randomPetAuraBoost(tile.petId, tile2.value);
            battleboardData.killTile(battleboardId, tile2.id);
        }
    }
    if (getAuraColor(tile.angelId) == 1) {
        battleboardData.setTileHp(battleboardId, tileId, tile.hp + 5);
    }
    checkMonsterAttack(battleboardId, tileId, positionTo);
}

function init(address _tokens, address _users, address _flc) public {
    require(!_init);
    TOKENS_address = _tokens;
    USERS_address = _users;
    FLC_address = _flc;
