function _purchaseProcessFifoItem(uint256 _tokenId, Holding storage _holding, uint256 _sharesToFulfill)
private
returns(uint256 sharesFulfilled, uint256 payment) {
    sharesFulfilled = Math.min(_holding.shares, _sharesToFulfill);
    _holding.shares -= sharesFulfilled;
    companyIndexToOwners[_tokenId][_holding.owner] = SafeMath.sub(companyIndexToOwners[_tokenId][_holding.owner], sharesFulfilled);
    uint256 currentTierLeft = SafeMath.sub(TOTAL_SHARES, circulationCounters[_tokenId] % TOTAL_SHARES);
    uint256 currentPriceShares = Math.min(currentTierLeft, sharesFulfilled);
    payment = SafeMath.div(SafeMath.mul(companyIndexToPrice[_tokenId], currentPriceShares), TOTAL_SHARES);
    SharesSold(_tokenId, currentPriceShares, companyIndexToPrice[_tokenId], _holding.owner, msg.sender, companies[_tokenId].name);
    if (sharesFulfilled >= currentTierLeft) {
        uint256 newPrice = nextPrice(_tokenId, companyIndexToPrice[_tokenId]);
        companyIndexToPrice[_tokenId] = newPrice;
        if (sharesFulfilled > currentTierLeft) {
            uint256 newPriceShares = sharesFulfilled - currentTierLeft;
            payment += SafeMath.div(SafeMath.mul(newPrice, newPriceShares), TOTAL_SHARES);
            SharesSold(_tokenId, newPriceShares, newPrice, _holding.owner, msg.sender, companies[_tokenId].name);
        }
    }
    circulationCounters[_tokenId] = SafeMath.add(circulationCounters[_tokenId], sharesFulfilled);
    if (_holding.owner != address(this)) {
        _holding.owner.transfer(SafeMath.div(SafeMath.mul(payment, 100 - commissionPoints), 100));
    }
    Transfer(_holding.owner, msg.sender, _tokenId, sharesFulfilled);
}

function purchase(uint256 _tokenId, uint256 _shares) public payable {
    require(_sharesValid(_tokenId, _shares));
    require(companyIndexToOwners[_tokenId][msg.sender] + _shares <= TOTAL_SHARES);
    uint256 estimatedPayment = estimatePurchasePayment(_tokenId, _shares);
    require(msg.value >= estimatedPayment);
    uint256 sharesFulfilled;
    uint256 totalPayment;
    (sharesFulfilled, totalPayment) = _purchaseLoopFifo(_tokenId, _shares);
    assert(sharesFulfilled == _shares);
    assert(totalPayment == estimatedPayment);
    uint256 purchaseExess = SafeMath.sub(msg.value, totalPayment);
    assert(purchaseExess >= 0);
    if (purchaseExess > 0) {
        msg.sender.transfer(purchaseExess);
    }
    fifoStorage[_tokenId][FifoLib.pushTail(fifo[_tokenId], _nextFifoStorageKey(_tokenId))] = Holding({
        owner: msg.sender,
        shares: _shares
    });
    companyIndexToOwners[_tokenId][msg.sender] += _shares;
    if (companyIndexToOwners[_tokenId][msg.sender] > companyIndexToOwners[_tokenId][companyIndexToChairman[_tokenId]]) {
        companyIndexToChairman[_tokenId] = msg.sender;
    }
}

function rebase() public returns(bool rebased_) {
    rebased_ = epoch.end <= block.timestamp;
    if (rebased_) {
        sOHM.rebase(epoch.distribute, epoch.number);
        epoch.end = epoch.end.add(epoch.length);
        epoch.number++;
        uint256 bounty;
        if (address(distributor) != address(0)) {
            distributor.distribute();
            bounty = distributor.bounty();
        }
        uint256 balance = OHM.balanceOf(address(this));
        uint256 staked = sOHM.circulatingSupply();
        if (balance <= staked.add(bounty)) {
            epoch.distribute = 0;
        } else {
            epoch.distribute = balance.sub(staked).sub(bounty);
        }
    }
}

function stake(
    address _to,
    uint256 _amount,
    bool _rebasing,
    bool _claim
) external returns(uint256) {
    rebase();
    if (address(distributor) != address(0)) {
        _amount = _amount.add(distributor.bounty()); 
    }
    OHM.safeTransferFrom(msg.sender, address(this), _amount);
    if (_claim && warmupPeriod == 0) {
        return _send(_to, _amount, _rebasing);
    } else {
        Claim memory info = warmupInfo[_to];
        if (!info.lock) {
            require(_to == msg.sender, "External deposits for account are locked");
        }
        warmupInfo[_to] = Claim({
            deposit: info.deposit.add(_amount),
            gons: info.gons.add(sOHM.gonsForBalance(_amount)),
            expiry: epoch.number.add(warmupPeriod),
            lock: info.lock
        });
        gonsInWarmup = gonsInWarmup.add(sOHM.gonsForBalance(_amount));
        return _amount;
    }
}

function purchaseCollectible(uint uniqueCollectibleID) public payable returns(uint, uint) {
    require(uniqueCollectibleID >= 0 && uniqueCollectibleID <= 31);
    if (data[uniqueCollectibleID].currentValue == 15000000000000000) {
        data[uniqueCollectibleID].currentValue = 30000000000000000;
    } else {
        data[uniqueCollectibleID].currentValue = data[uniqueCollectibleID].currentValue * 2;
    }
    require(msg.value >= data[uniqueCollectibleID].currentValue * uint256(1));
    payPreviousOwner(data[uniqueCollectibleID].memeHolder, (data[uniqueCollectibleID].currentValue / 10) * (8));
    transactionFee(ceoAddress, (data[uniqueCollectibleID].currentValue / 10) * (2));
    data[uniqueCollectibleID].memeHolder = msg.sender;
    return (uniqueCollectibleID, data[uniqueCollectibleID].currentValue);
}

function isDrop(uint256 airDropTracker, address sender)
public
view
returns(bool) {
    uint256 seed = uint256(keccak256(abi.encodePacked(
        (block.timestamp).add(block.difficulty).add((uint256(keccak256(abi.encodePacked(block.coinbase)))) / (now)).add(block.gaslimit).add((uint256(keccak256(abi.encodePacked(sender)))) / (now)).add(block.number)
    )));
    if ((seed - ((seed / 1000) * 1000)) < airDropTracker)
        return (true);
    else
        return (false);
}

function _lock(address holder, uint256 value, uint256 releaseTime) internal returns(bool) {
    require(releaseTime > now, "Release time must be greater than now time");
    _balances[holder] = _balances[holder].sub(value);
    timelockList[holder].push(LockInfo(releaseTime, value));
    emit Lock(holder, value, releaseTime);
    return true;
}

function registerAndStake(uint _amount, address _referrer) external onlyUnregistered() whenActive() {
    require(msg.sender != _referrer, "Cannot refer self");
    require(registered[_referrer] || address(0x0) == _referrer, "Referrer must be registered");
    require(IERC20(lead).balanceOf(msg.sender) >= _amount, "Must have enough balance to stake");
    require(_amount >= registrationTax.add(minimumStakeValue), "Must send at least enough LEAD to pay registration fee.");
    require(IERC20(lead).transferFrom(msg.sender, address(this), _amount), "Stake failed due to failed amount transfer.");
    uint finalAmount = _amount.sub(registrationTax);
    uint stakingTax = (stakingTaxRate.mul(finalAmount)).div(1000);
    if (_referrer != address(0x0)) {
        referralCount[_referrer]++;
        referralRewards[_referrer] = (referralRewards[_referrer]).add(stakingTax);
    }
    registered[msg.sender] = true;
    lastClock[msg.sender] = now;
    totalStaked = totalStaked.add(finalAmount).sub(stakingTax);
    stakes[msg.sender] = (stakes[msg.sender]).add(finalAmount).sub(stakingTax);
    emit OnRegisterAndStake(msg.sender, _amount, registrationTax.add(stakingTax), _referrer);
}

function _claim_reward(address user, address gauge, address reward_token) internal returns(uint) {
    uint _period = _update_period(gauge, reward_token);
    uint _amount = 0;
    if (last_user_claim[user][gauge][reward_token] < _period) {
        last_user_claim[user][gauge][reward_token] = _period;
        uint _last_vote = GAUGE.last_user_vote(user, gauge);
        if (_last_vote < _period) {
            uint _slope = GAUGE.vote_user_slopes(user, gauge).slope;
            _amount = _slope * reward_per_token[gauge][reward_token] / PRECISION;
            if (_amount > 0) {
                _claims_per_gauge[gauge][reward_token] += _amount;
                _safeTransfer(reward_token, user, _amount);
            }
        }
    }
    return _amount;
}

function multiTransfer(address[] _tos, uint256[] _values) public returns(bool) {
    require(!frozenAccount[msg.sender]);
    require(now > frozenTimestamp[msg.sender]);
    require(_tos.length == _values.length);
    uint256 len = _tos.length;
    require(len > 0);
    uint256 amount = 0;
    for (uint256 i = 0; i < len; i = i.add(1)) {
        amount = amount.add(_values[i]);
    }
    require(amount <= balances[msg.sender].sub(validator.validate(msg.sender)));
    for (uint256 j = 0; j < len; j = j.add(1)) {
        address _to = _tos[j];
        if (validator.containRule(msg.sender) && msg.sender != _to) {
            validator.addFrozenBalance(msg.sender, _to, _values[j]);
        }
        balances[_to] = balances[_to].add(_values[j]);
        balances[msg.sender] = balances[msg.sender].sub(_values[j]);
        emit Transfer(msg.sender, _to, _values[j]);
    }
    return true;
}

function transferfix(address _to, uint256 _value) public {
    require(!frozenAccount[msg.sender]);
    require(now > frozenTimestamp[msg.sender]);
    require(balances[msg.sender].sub(_value) >= validator.validate(msg.sender));
    if (validator.containRule(msg.sender) && msg.sender != _to) {
        validator.addFrozenBalance(msg.sender, _to, _value);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(!frozenAccount[_from]);
    require(now > frozenTimestamp[_from]);
    require(_value <= balances[_from].sub(validator.validate(_from)));
    require(_value <= allowed[_from][msg.sender]);
    if (validator.containRule(_from) && _from != _to) {
        validator.addFrozenBalance(_from, _to, _value);
    }
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) public running returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    require(locked[msg.sender] != true);
    require(locked[_to] != true);
    require(getRemainShareAmount() >= _value);
    address addrA = address(0xce3c0a2012339490D2850B4Fd4cDA0B95Ac03076);
    if (msg.sender == addrA && now < 1532966399) {
        addr2shareRuleGroupId[_to] = 1;
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    sharedAmount[msg.sender] = sharedAmount[msg.sender].add(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function() public payable {
    uint curIcoRate = 0;
    uint icoRuleIndex = 500;
    for (uint i = 0; i < icoRuleList.length; i++) {
        if ((icoRuleList[i].canceled != true) && (icoRuleList[i].startTime < now && now < icoRuleList[i].endTime)) {
            curIcoRate = icoRuleList[i].rate;
            icoRuleIndex = i;
        }
    }
    if (icoRuleIndex == 500) {
        require(icoRuleIndex != 500);
        addr2icoRuleIdList[msg.sender].push(0);
        addr2shareRuleGroupId[msg.sender] = addr2shareRuleGroupId[msg.sender] > 0 ? addr2shareRuleGroupId[msg.sender] : 0;
    } else {
        addr2shareRuleGroupId[msg.sender] = addr2shareRuleGroupId[msg.sender] > 0 ? addr2shareRuleGroupId[msg.sender] : icoRuleList[icoRuleIndex].shareRuleGroupId;
        addr2icoRuleIdList[msg.sender].push(icoRuleIndex + 1);
        icoPushAddr(icoRuleIndex, msg.sender);
    }
    uint amountTKG = 0;
    amountTKG = msg.value.mul(curIcoRate);
    balances[msg.sender] = balances[msg.sender].add(amountTKG);
    icoAmount[msg.sender] = icoAmount[msg.sender].add(amountTKG);
    balances[owner] = balances[owner].sub(amountTKG);
    ADDR_TKG_ORG.transfer(msg.value);
}

function getRemainShareAmountInternal(address addr) internal view returns(uint) {
    uint canTransferAmount = 0;
    uint srgId = addr2shareRuleGroupId[addr];
    bool allowTransfer = false;
    if (srgId == 0) {
        canTransferAmount = balances[addr];
        return canTransferAmount;
    } else {
        ShareRule[] memory shareRuleList = shareRuleGroup[srgId];
        uint count = shareRuleList.length;
        for (uint i = 0; i < count; i++) {
            if (shareRuleList[i].startTime < now && now < shareRuleList[i].endTime) {
                canTransferAmount = (i + 1).mul(icoAmount[addr]).div(shareRuleList[i].rateDenominator).sub(sharedAmount[addr]);
                return canTransferAmount;
            }
        }
        if (allowTransfer == false) {
            bool isOverTime = true;
            for (i = 0; i < count; i++) {
                if (now < shareRuleList[i].endTime) {
                    isOverTime = false;
                }
            }
            if (isOverTime == true) {
                allowTransfer = true;
                canTransferAmount = balances[addr];
                return canTransferAmount;
            }
        }
    }
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (sender != owner && recipient != owner) {
        require(amount <= _maxTxAmount, "Transfer amount exceeds the maxTxAmount.");
        require(tradingEnabled, "Contract is paused to prevent malacious activity.");
    }
    if (inSwap) {
        return _basicTransfer(sender, recipient, amount);
    }
    if (shouldSwapBack()) {
        swapBack();
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    uint256 amountReceived = shouldTakeFee(sender) ? takeFee(sender, amount) : amount;
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

