function buyToken(
    address _token
)
external
inState(_token, States.Active)
nonZeroAddress(_token)
payable {
    require(
        msg.value >= crowdsales[_token].minInvest,
        "Failed to buy token due to less than minimum investment."
    );
    require(
        crowdsales[_token].raised.add(msg.value) <= (
            crowdsales[_token].cap
        ),
        "Failed to buy token due to exceed cap."
    );
    require(
        block.timestamp < crowdsales[_token].closingTime,
        "Failed to buy token due to crowdsale is closed."
    );
    deposits[msg.sender][_token] = (
        deposits[msg.sender][_token].add(msg.value)
    );
    crowdsales[_token].raised = crowdsales[_token].raised.add(msg.value);
    emit TokenBought(msg.sender, _token, msg.value);
}

function finalize(
    address _token
)
external
nonZeroAddress(_token)
inState(_token, States.Active)
onlyCrowdsaleOwner(_token) {
    require(
        crowdsales[_token].earlyClosure || (
            block.timestamp >= crowdsales[_token].closingTime),
        "Failed to finalize due to crowdsale is opening."
    );
    if (_goalReached(ERC20(_token))) {
        crowdsales[_token].state = States.Closed;
        emit CrowdsaleClosed(msg.sender, _token);
        _refundSurplusTokens(
            ERC20(_token),
            crowdsales[_token].refundWallet
        );
        _payCommission(_token);
    } else {
        _enableRefunds(_token);
        _refundCrowdsaleTokens(
            ERC20(_token),
            crowdsales[_token].refundWallet
        );
    }
}

function deposit(address beneficiary, uint totalAmount, uint trenchAmount, uint firstRelease, uint releaseStride) public returns(bool success) {
    require(token.transferFrom(msg.sender, address(this), totalAmount));
    LockBoxStruct memory l;
    l.beneficiary = beneficiary;
    l.balance = trenchAmount;
    l.releaseTime = firstRelease;
    lockBoxStructs.push(l);
    for (uint i = 1; i < 18; ++i) {
        uint time = firstRelease + (releaseStride * i);
        l.releaseTime = time;
        lockBoxStructs.push(l);
        emit LogLockBoxDeposit(msg.sender, trenchAmount, time);
    }
    return true;
}

function burn() public {
    require(block.number >= _startBlock, "Survey not yet started");
    require(block.number >= _endBlock, "Survey is still running");
    require(!_burnt, "Already burnt");
    IERC20(_votingTokenAddress).burn(_toBurn);
    _burnt = true;
}

function vote(uint256 tokenId) public {
    require(block.number >= _startBlock, "Survey not yet started");
    require(block.number <= _endBlock, "Survey has ended");
    require(!_voted[msg.sender], "User Already Voted");
    require(
        _isCandidate[tokenId],
        "The chosen tokenId is not concurring in the challenge"
    );
    IERC20(_votingTokenAddress).transferFrom(
        msg.sender,
        address(this),
        _singleVoteAmount
    );
    _voters[msg.sender] = tokenId;
    _voted[msg.sender] = true;
    _votes[tokenId] = _votes[tokenId] + 1;
    _toBurn += _singleVoteAmountToBurn;
}

function becomeNorsefire() public payable {
    require(initialized);
    address oldNorseAddr = currentNorsefire;
    uint oldNorsePrice = norsefirePrice;
    require(msg.value >= norsefirePrice);
    uint excess = msg.value.sub(oldNorsePrice);
    norsefirePrice = oldNorsePrice.add(oldNorsePrice.div(10));
    uint diffFivePct = (norsefirePrice.sub(oldNorsePrice)).div(20);
    uint flipPrize = diffFivePct.mul(10);
    uint marketBoost = diffFivePct.mul(9);
    address _newNorse = msg.sender;
    uint _toRefund = (oldNorsePrice.add(flipPrize)).add(excess);
    currentNorsefire = _newNorse;
    oldNorseAddr.send(_toRefund);
    actualNorse.send(diffFivePct);
    boostCloneMarket(marketBoost);
    emit NorsefireSwitch(oldNorseAddr, _newNorse, norsefirePrice);
}

function handlePayment(address src, uint eth) tokenOnly returns(uint) {
    require(eth > 0);
    require(now >= icoStart && now <= icoEnd);
    require(icoSale < maxIco);
    uint tokenAmount = mul(tokensPerWei, eth);
    if (!presale) {
        if (now < icoStart + (168 * 3600)) {
            tokenAmount = tokenAmount * 150 / 100;
        }
        else if (now < icoStart + (312 * 3600)) {
            tokenAmount = tokenAmount * 130 / 100;
        }
        else if (now < icoStart + (456 * 3600)) {
            tokenAmount = tokenAmount * 110 / 100;
        }
    }
    icoSale += tokenAmount;
    if (icoSale > maxIco) {
        uint excess = sub(icoSale, maxIco);
        tokenAmount = sub(tokenAmount, excess);
        token.transferEth(src, div(excess, tokensPerWei));
        icoSale = maxIco;
    }
    require(balanceOf(owner) >= tokenAmount);
    data.setBalances(owner, sub(data.balances(owner), tokenAmount));
    data.setBalances(src, add(data.balances(src), tokenAmount));
    contributors.push(src);
    token.triggerTansferEvent(owner, src, tokenAmount);
    return tokenAmount;
}

