function transfer(
    uint256 fromPool,
    uint256 toPool,
    uint256 amount
)
public
poolExists(fromPool)
poolExists(toPool)
updateReward(msg.sender, fromPool)
updateReward(msg.sender, toPool)
whenNotPaused() {
    Pool memory toP = pools[toPool];
    require(block.timestamp >= toP.periodStart, "pool not open");
    super.transfer(fromPool, toPool, amount);
    emit Transferred(msg.sender, fromPool, toPool, amount);
}

function stake(uint256 pool, uint256 amount)
public
poolExists(pool)
updateReward(msg.sender, pool)
whenNotPaused() {
    Pool memory p = pools[pool];
    require(block.timestamp >= p.periodStart, "pool not open");
    require(amount.add(balanceOf(msg.sender, pool)) >= min, "must stake min");
    super.stake(pool, amount);
    emit Staked(msg.sender, pool, amount);
}

function redeem(uint256 pool, uint256 card)
public
payable
poolExists(pool)
cardExists(pool, card)
updateReward(msg.sender, pool) {
    Pool storage p = pools[pool];
    Card memory c = p.cards[card];
    require(block.timestamp >= c.releaseTime, "card not released");
    require(p.points[msg.sender] >= c.points, "not enough pineapples");
    require(msg.value == c.mintFee, "support our artists, send eth");
    if (c.mintFee > 0) {
        uint256 _controllerShare = msg.value.mul(p.controllerShare).div(1000);
        uint256 _artistRoyalty = msg.value.sub(_controllerShare);
        require(_artistRoyalty.add(_controllerShare) == msg.value, "problem with fee");
        p.feesCollected = p.feesCollected.add(c.mintFee);
        pendingWithdrawals[controller] = pendingWithdrawals[controller].add(_controllerShare);
        pendingWithdrawals[p.artist] = pendingWithdrawals[p.artist].add(_artistRoyalty);
    }
    p.points[msg.sender] = p.points[msg.sender].sub(c.points);
    p.spentPineapples = p.spentPineapples.add(c.points);
    memeLtd.mint(msg.sender, card, 1, "");
    emit Redeemed(msg.sender, pool, c.points);
}

function forceRecoverCollateralOnBehalfOf(
    address  ,
    bytes32 positionId,
    address recipient
)
external
onlyMargin
nonReentrant
onlyPosition(positionId)
returns(address) {
    MarginCommon.Position memory position = MarginHelper.getPosition(DYDX_MARGIN, positionId);
    uint256 positionEnd = uint256(position.startTimestamp).add(position.maxDuration);
    if (position.callTimestamp > 0) {
        uint256 marginCallEnd = uint256(position.callTimestamp).add(position.callTimeLimit);
        positionEnd = Math.min256(positionEnd, marginCallEnd);
    }
    require(
        block.timestamp >= positionEnd.add(RECOVERY_DELAY),
        "BucketLenderWithRecoveryDelay#forceRecoverCollateralOnBehalfOf: Recovery too early"
    );
    return forceRecoverCollateralInternal(recipient);
}

function _effectiveDay(uint32 onDayOrToday) internal view returns(uint32 dayNumber) {
    return onDayOrToday == 0 ? today() : onDayOrToday;
}

function _getNotVestedAmount(address grantHolder, uint32 onDayOrToday) internal view returns(uint256 amountNotVested) {
    tokenGrant storage grant = _tokenGrants[grantHolder];
    vestingSchedule storage vesting = _vestingSchedules[grant.vestingLocation];
    uint32 onDay = _effectiveDay(onDayOrToday);
    if (!grant.isActive || onDay < grant.startDay + vesting.cliffDuration) {
        return grant.amount;
    }
    else if (onDay >= grant.startDay + vesting.duration) {
        return uint256(0);
    }
    else {
        uint32 daysVested = onDay - grant.startDay;
        uint32 effectiveDaysVested = (daysVested / vesting.interval) * vesting.interval;
        uint256 vested = grant.amount.mul(effectiveDaysVested).div(vesting.duration);
        return grant.amount.sub(vested);
    }
}

function _fundsAreAvailableOn(address account, uint256 amount, uint32 onDay) internal view returns(bool ok) {
    return (amount <= _getAvailableAmount(account, onDay));
}

function revokeGrant(address grantHolder, uint32 onDay) public onlyGrantor returns(bool ok) {
    tokenGrant storage grant = _tokenGrants[grantHolder];
    vestingSchedule storage vesting = _vestingSchedules[grant.vestingLocation];
    uint256 notVestedAmount;
    require(msg.sender == owner() || msg.sender == grant.grantor, "not allowed");
    require(grant.isActive, "no active grant");
    require(vesting.isRevocable, "irrevocable");
    require(onDay <= grant.startDay + vesting.duration, "no effect");
    require(onDay >= today(), "cannot revoke vested holdings");
    notVestedAmount = _getNotVestedAmount(grantHolder, onDay);
    _approve(grantHolder, grant.grantor, notVestedAmount);
    transferFrom(grantHolder, grant.grantor, notVestedAmount);
    _tokenGrants[grantHolder].wasRevoked = true;
    _tokenGrants[grantHolder].isActive = false;
    emit GrantRevoked(grantHolder, onDay);
    return true;
}

function setRestrictions(
    address grantor,
    uint32 minStartDay,
    uint32 maxStartDay,
    uint32 expirationDay
)
public
onlyOwner
onlyExistingAccount(grantor)
returns(bool ok) {
    require(
        isUniformGrantor(grantor) &&
        maxStartDay > minStartDay &&
        expirationDay > today(), "invalid params");
    _restrictions[grantor] = restrictions(
        true  ,
        minStartDay,
        maxStartDay,
        expirationDay
    );
    emit GrantorRestrictionsSet(grantor, minStartDay, maxStartDay, expirationDay);
    return true;
}

function purchaseHero(uint _heroId) public payable {
    require(msg.value == heroes[_heroId].currentPrice);
    require(isPaused == false);
    uint256 TournamentPrizeFee = (msg.value / 10); 
    uint256 devFee = ((msg.value / 10) / 2); 
    uint256 DBZHeroOwnerCommission = (msg.value / 10); 
    uint256 commissionOwner = (msg.value - (devFee + TournamentPrizeFee + DBZHeroOwnerCommission));
    heroes[_heroId].ownerAddress.transfer(commissionOwner); 
    heroes[_heroId].DBZHeroOwnerAddress.transfer(DBZHeroOwnerCommission); 
    devFeeAddress.transfer(devFee); 
    heroes[_heroId].currentLevel += 1;
    heroes[_heroId].ownerAddress = msg.sender;
    heroes[_heroId].currentPrice = mul(heroes[_heroId].currentPrice, 2);
}

function transferFrom(address from, address to, uint256 value) public returns(bool) {
    require(value > 0);
    require(to != address(0));
    require(value <= balances[from]);
    require(value <= allowed[from][msg.sender]);
    if (now < icoEnds) 
        require(from == ownerAddr);
    if (msg.sender == ownerAddr || msg.sender == companyAddr)
        require(now >= teamCompanyLock);
    balances[from] = balances[from].sub(value);
    balances[to] = balances[to].add(value);
    allowed[from][msg.sender] = allowed[from][msg.sender].sub(value);
    emit Transfer(from, to, value);
    return true;
}

function transfer(address to, uint256 value) public returns(bool) {
    require(now >= startTime); 
    require(value > 0);
    if (msg.sender == ownerAddr || msg.sender == companyAddr)
        require(now >= teamCompanyLock);
    balances[msg.sender] = balances[msg.sender].sub(value);
    balances[to] = balances[to].add(value);
    emit Transfer(msg.sender, to, value);
    return true;
}

function burn() public {
    require(!burned && now > icoEnds);
    uint256 totalReserve = teamReserve.add(companyReserve);
    uint256 difference = balances[ownerAddr].sub(totalReserve);
    balances[ownerAddr] = teamReserve;
    balances[companyAddr] = companyReserve;
    balances[giveawayAddr] = giveawayReserve;
    _totalSupply = _totalSupply.sub(difference);
    burned = true;
    emit Burned(difference);
}

function claim() public returns(bool) {
    require(_balances[msg.sender] > 0);
    require(block.timestamp > starttime.add(6 days), "you cannot sell under the selling time");
    dunk.transferFrom(owner, msg.sender, _balances[msg.sender]);
    _balances[msg.sender] = 0;
    return true;
}

function sellback(uint256 _amount) public returns(bool) {
    require(block.timestamp > starttime.add(6 days), "you cannot sell under the selling time");
    require(tokensold < softcap, "sale hits the hardcap so you cannot sellback it");
    dunk.transferFrom(msg.sender, owner, _amount * 1e18);
    msg.sender.transfer(_balances[msg.sender].mul(10));
    return true;
}

function generate(uint256 length) public onlyOwner {
    require(currentIndex < 10000, 'Already generated all info.');
    uint256 endIndex = currentIndex + length < 10000 ? currentIndex + length : 10000;
    for (uint256 i = currentIndex; i < endIndex; i++) {
        if (stud.length < 5000) {
            if (dam.length < 5000) {
                bytes32 hashOfRandom = keccak256(abi.encodePacked(block.number, block.timestamp, block.difficulty, i));
                uint256 numberRepresentation = uint256(hashOfRandom);
                if (numberRepresentation % 2 == 0)
                    stud.push(i);
                else
                    dam.push(i);
            } else
                stud.push(i);
        } else {
            dam.push(i);
        }
    }
    currentIndex = endIndex;
}

function setRecovery(bytes32 name, address recovery) public {
    ID storage id = citizens[name];
    require(id.primary == msg.sender);
    require(recovery != address(0x0));
    require(id.recovery == address(0x0));
    require(addressAvailable(recovery));
    associate[recovery] = name;
    id.recovery = recovery;
    emit SetRecovery(name, recovery);
}

function nameAvailable(bytes32 name) public view returns(bool) {
    return getPrimary(name) == address(0x0);
}

function setPrimary(bytes32 name, address primary) public {
    ID storage id = citizens[name];
    require(id.primary == msg.sender);
    require(primary != address(0x0));
    require(addressAvailable(primary));
    associate[primary] = name;
    directory[primary] = name;
    directory[msg.sender] = bytes32(0x0);
    id.primary = primary;
    emit SetPrimary(name, primary);
}

function recover(bytes32 name, address newRecovery) public {
    ID storage id = citizens[name];
    require(id.recovery == msg.sender);
    if (newRecovery != address(0x0)) {
        require(addressAvailable(newRecovery));
        associate[newRecovery] = name;
    }
    id.recovery = newRecovery;
    directory[id.primary] = bytes32(0x0);
    directory[msg.sender] = name;
    id.primary = msg.sender;
    emit Recover(name, msg.sender, newRecovery);
}

