function annualInterest() public constant returns(uint interest) {
    uint _now = now;
    interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime)) <= 30 years) {
        interest = 4 * maxMintProofOfStake; 
    } else if ((_now.sub(stakeStartTime)) > 30 years && (_now.sub(stakeStartTime)) <= 50 years) {
        interest = 2 * maxMintProofOfStake; 
    }
}

function getCoinAge(address _address, uint _now) internal returns(uint _coinAge) {
    if (transferIns[_address].length <= 0) return 0;
    for (uint i = 0; i < transferIns[_address].length; i++) {
        if (_now < uint(transferIns[_address][i].time).add(stakeMinAge)) continue;
        uint nCoinSeconds = _now.sub(uint(transferIns[_address][i].time));
        _coinAge = _coinAge.add(uint(transferIns[_address][i].amount) * nCoinSeconds.div(1 days));
    }
}

function getProofOfStakeReward(address _address) internal returns(uint) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint _now = now;
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    uint interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime)) <= 30 years) {
        interest = 4 * maxMintProofOfStake; 
    } else if ((_now.sub(stakeStartTime)) > 30 years && (_now.sub(stakeStartTime)) <= 50 years) {
        interest = 2 * maxMintProofOfStake; 
    }
    return (_coinAge * interest).div(365 * 10 ** uint256(decimals));
}

function calculateReleased() public onlyOwner returns(uint tokens) {
    require(now > _startTime);
    uint _monthDiff = (now.sub(_startTime)).div(30 days);
    if (_monthDiff >= 10) {
        _released = _locked;
    } else {
        _released = _monthDiff.mul(_locked.div(10));
    }
    emit ReleasedTokens(_released);
    return _released;
}

function allocateTokens(address to, uint tokens) public onlyOwner returns(bool success) {
    require(address(0) != to && 0 <= tokens && tokens <= _released.sub(_allocated));
    balances[to] = balances[to].add(tokens);
    _allocated = _allocated.add(tokens);
    emit AllocateTokens(to, tokens);
    return true;
}

function transfer(
    address _to,
    uint256 _value
)
public
returns(bool) {
    require(now > frozenTimestamp[msg.sender]);
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function release() public virtual {
    require(block.timestamp >= _releaseTime, "TokenTimelock: current time is before release time");
    uint256 amount = _token.balanceOf(address(this));
    require(amount > 0, "TokenTimelock: no tokens to release");
    _token.transfer(_beneficiary, amount);
}

constructor(IERC20 token_, address beneficiary_, uint256 releaseTime_) {
    require(releaseTime_ > block.timestamp, "TokenTimelock: release time is before current time");
    _token = token_;
    _beneficiary = beneficiary_;
    _releaseTime = releaseTime_;
}

function unfarm(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > PossibleUnstakeTime, "You have not staked for a while yet, kindly wait a bit more");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(liquiditytoken1).transfer(feeDirection, fee), "Could not transfer withdraw fee.");
    require(Token(liquiditytoken1).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function farm(uint amountToStake) public {
    require(stakingStatus == true, "Staking is not yet initialized");
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(liquiditytoken1).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(Token(liquiditytoken1).transfer(feeDirection, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function buyToken(uint _tokenId) public payable {
    address oldOwner = tokenIndexToOwner[_tokenId];
    uint256 sellingPrice = tokenIndexToPrice[_tokenId];
    require(oldOwner != msg.sender);
    require(msg.value >= sellingPrice);
    require(sellingPrice > 0);
    uint256 purchaseExcess = msg.value.sub(sellingPrice);
    uint256 payment = sellingPrice.mul(87).div(100);
    uint256 feeOnce = sellingPrice.sub(payment).div(13);
    uint256 feeThree = feeOnce.mul(3);
    uint256 nextPrice = getNextPrice(sellingPrice);
    tokenIndexToPrice[_tokenId] = nextPrice;
    tokenIndexToOwner[_tokenId] = msg.sender;
    lastBuyBlock = block.number;
    if (_tokenId > 0) {
        if (tokenIndexToOwner[0] != address(0))
            tokenIndexToOwner[0].transfer(feeThree);
        if (nextPrice > highestPrice) {
            highestPrice = nextPrice;
            nextRoundWinner = msg.sender;
        }
    }
    donateAddress[_tokenId].transfer(feeThree);
    if (tokenWinner[_tokenId] != address(0))
        tokenWinner[_tokenId].transfer(feeThree);
    yct.ownerOf(0).transfer(feeOnce);
    if (oldOwner != address(0)) {
        oldOwner.transfer(payment);
    }
    TokenSold(_tokenId, sellingPrice, oldOwner, msg.sender);
    if (purchaseExcess > 0)
        msg.sender.transfer(purchaseExcess);
}

function() whenNotPaused whenSaleNotFinish payable {
    require(msg.value >= etherOne.div(tokenPrice).mul(minimumTokens));
    uint256 amountWei = msg.value;
    uint256 amount = amountWei.div(zeroAmount);
    uint256 tokens = amount.mul(getRate());
    if (msg.data.length == 20) {
        address referer = bytesToAddress(bytes(msg.data));
        require(referer != msg.sender);
        referer.transfer(amountWei.div(100).mul(20));
    }
    tokenReward.transfer(msg.sender, tokens);
    investWallet.transfer(this.balance);
    totalRaised = totalRaised.add(tokens);
    if (totalRaised >= minCap) {
        finished = true;
    }
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 8 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        address sender = msg.sender;
        sender.send(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

