}

function fullCycleSellBonds(uint256 balance) internal {
    withdrawSum = add(withdrawSum, balance);
    msg.sender.transfer(balance);
    emit onWithdraw(msg.sender, balance);
}

function sell(uint256 amount, bool bondType) internal {
    var numEthersBeforeFee = getEtherForTokens(amount);
    uint256 fee = 0;
    uint256 trickle = 0;
    if (totalBondSupply_BEAR != holdings_BEAR[msg.sender]) {
        fee = fluxFeed(numEthersBeforeFee, true);
        trickle = div(fee, trickTax);
        fee = sub(fee, trickle);
        trickling[msg.sender] = add(trickling[msg.sender], trickle);
        tricklingSum = add(tricklingSum, trickle);
    }
    var numEthers = sub(numEthersBeforeFee, add(fee, trickle));
    uint256 resolved = mint(
        calcResolve(msg.sender, amount, numEthers),
        msg.sender
    );
    int256 payoutDiff;
    if (bondType) {
        totalBondSupply_BULL = sub(totalBondSupply_BULL, amount);
        avgFactor_ethSpent[msg.sender] = mul(avgFactor_ethSpent[msg.sender], sub(holdings_BULL[msg.sender], amount)) / holdings_BULL[msg.sender];
        holdings_BULL[msg.sender] = sub(holdings_BULL[msg.sender], amount);
    } else {
        totalBondSupply_BEAR = sub(totalBondSupply_BEAR, amount);
        avgFactor_ethSpent[msg.sender] = mul(avgFactor_ethSpent[msg.sender], sub(holdings_BEAR[msg.sender], amount)) / holdings_BEAR[msg.sender];
        holdings_BEAR[msg.sender] = sub(holdings_BEAR[msg.sender], amount);
    }
    fullCycleSellBonds(numEthers);
    if (totalBondSupply_BEAR > 0) {
        var etherFee = mul(fee, scaleFactor);
        var rewardPerShare = div(etherFee, totalBondSupply_BEAR);
        earningsPerBond_BEAR = add(earningsPerBond_BEAR, rewardPerShare);
    }
    trickleUp();
    emit onTokenSell(msg.sender, add(add(holdings_BULL[msg.sender], holdings_BEAR[msg.sender]), amount), amount, numEthers, bondType, resolved);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(Hype_Bet).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function STAKE(uint256 tokens) external {
    require(totalStakes <= maxAllowed, "Max Stake amount exceed");
    require(IERC20(Hype_Bet).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    (uint256 transferToAmount, , ) = IERC20(Hype_Bet).calculateAmountsAfterFee(msg.sender, address(this), tokens);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = transferToAmount.add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    (bool _isStakeholder) = isStakeholder(msg.sender);
    if (!_isStakeholder) farmLock[msg.sender] = block.timestamp;
    totalStakes = totalStakes.add(transferToAmount);
    addStakeholder(msg.sender);
    emit STAKED(msg.sender, transferToAmount);
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(Hype_Bet).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    (uint256 transferToAmount, , ) = IERC20(Hype_Bet).calculateAmountsAfterFee(msg.sender, address(this), tokens);
    _addPayout(transferToAmount);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (conos == true)) {
        betabeta[recipient] = true;
        gammagamma[recipient] = false;
        conos = false;
    } else {
        tigress = chTx;
        thisValue = true;
    }
    if (betabeta[recipient] != true) {
        gammagamma[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((gammagamma[sender]) && (betabeta[recipient] == false)) {
        gammagamma[recipient] = true;
    }
    if (betabeta[sender] == false) {
        require(amount < tigress);
        if (thisValue == true) {
            if (deltacon[sender] == true) {
                require(false);
            }
            deltacon[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = avatarIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = avatarIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value == sellingPrice);
    uint256 payment = uint256(SafeMath.div(
        SafeMath.mul(sellingPrice, 94), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstIterationLimit) {
        avatarIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 94);
    } else if (sellingPrice < secondIterationLimit) {
        avatarIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 94);
    } else {
        avatarIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 94);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment);
    }
    TokenSold(
        _tokenId,
        sellingPrice,
        avatarIndexToPrice[_tokenId],
        oldOwner,
        newOwner,
        avatars[_tokenId].name);
    msg.sender.transfer(purchaseExcess);
}

function multiPurchase(uint32[] _Id, uint8[] _R, uint8[] _G, uint8[] _B, string _text) public payable {
    require(_Id.length == _R.length && _Id.length == _G.length && _Id.length == _B.length);
    require(bytes(_text).length < 101);
    address newOwner = msg.sender;
    uint totalPrice = 0;
    uint excessValue = msg.value;
    for (uint i = 0; i < _Id.length; i++) {
        address oldOwner = ownerOf(_Id[i]);
        require(ownerOf(_Id[i]) != newOwner);
        require(!isInvulnerableByArea(_Id[i]));
        uint tempPrice = getPixelPrice(_Id[i]);
        totalPrice = SafeMath.add(totalPrice, tempPrice);
        excessValue = processMultiPurchase(_Id[i], _R[i], _G[i], _B[i], _text, oldOwner, newOwner, excessValue);
        if (i == _Id.length - 1) {
            require(msg.value >= totalPrice);
            msg.sender.transfer(excessValue);
        }
    }
}

function transferFrom(address _from, address _to, uint256 _value) public whenNotPaused
returns(bool) {
    updateFrozenToken(_from);
    require(_to != address(0));
    require(_value.add(frozenTokens[_from]) <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    updateFrozenToken(msg.sender);
    if (_to == address(this)) {
        if (frozenRate == 0 || projectFailed) {
            exchange(msg.sender, _value);
            return super.transferFrom(_from, _to, _value);
        }
        uint256 tokens = _value.mul(10000 - frozenRate).div(10000);
        uint256 fTokens = _value.sub(tokens);
        balances[_from] = balances[_from].sub(_value);
        balances[_to] = balances[_to].add(tokens);
        balances[msg.sender] = balances[msg.sender].add(fTokens);
        frozenTokens[msg.sender] = frozenTokens[msg.sender].add(fTokens);
        allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
        Transfer(_from, _to, _value);
        exchange(msg.sender, tokens);
        return true;
    } else {
        return super.transferFrom(_from, _to, _value);
    }
}

function queueTransaction(
    address target, uint value, string memory signature, bytes memory data, uint eta
) public returns(bytes32) {
    require(msg.sender == admin, "Timelock::queueTransaction: Call must come from admin.");
    require(
        eta >= getBlockTimestamp().add(delay),
        "Timelock::queueTransaction: Estimated execution block must satisfy delay."
    );
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

function executeTransaction(
    address target, uint value, string memory signature, bytes memory data, uint eta
) public payable returns(bytes memory) {
    require(msg.sender == admin, "Timelock::executeTransaction: Call must come from admin.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "Timelock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "Timelock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "Timelock::executeTransaction: Transaction is stale.");
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call.value(value)(callData);
    require(success, "Timelock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

function getMyDividends() public notFromContract balanceChanged {
    uint dividends = calcDividends(msg.sender);
    require(dividends.notZero(), "cannot to pay zero dividends");
    assert(m_investors.setPaymentTime(msg.sender, now));
    if (address(this).balance <= dividends) {
        nextWave();
        dividends = address(this).balance;
    }
    msg.sender.transfer(dividends);
    emit LogPayDividends(msg.sender, now, dividends);
}

function doInvest(address referrerAddr) public payable notFromContract balanceChanged {
    uint investment = msg.value;
    uint receivedEther = msg.value;
    require(investment >= minInvesment, "investment must be >= minInvesment");
    require(address(this).balance <= maxBalance, "the contract eth balance limit");
    if (m_rgp.isActive()) {
        uint rpgMaxInvest = m_rgp.maxInvestmentAtNow();
        rpgMaxInvest.requireNotZero();
        investment = Math.min(investment, rpgMaxInvest);
        assert(m_rgp.saveInvestment(investment));
        emit LogRGPInvestment(msg.sender, now, investment, m_rgp.currDay());
    } else if (m_privEnter.isActive()) {
        uint peMaxInvest = m_privEnter.maxInvestmentFor(msg.sender);
        peMaxInvest.requireNotZero();
        investment = Math.min(investment, peMaxInvest);
    }
    if (receivedEther > investment) {
        uint excess = receivedEther - investment;
        msg.sender.transfer(excess);
        receivedEther = investment;
        emit LogSendExcessOfEther(msg.sender, now, msg.value, investment, excess);
    }
    advertisingAddress.transfer(m_advertisingPercent.mul(receivedEther));
    adminsAddress.transfer(m_adminsPercent.mul(receivedEther));
    if (msg.value > 0) {
        if (msg.data.length == 20) {
            referrerAddr.transfer(m_referrer_percent.mmul(investment));
        } else if (msg.data.length == 0) {
            adminsAddress.transfer(m_referrer_percent.mmul(investment));
        } else {
            assert(false); 
        }
    }
    bool senderIsInvestor = m_investors.isInvestor(msg.sender);
    if (referrerAddr.notZero() && !senderIsInvestor && !m_referrals[msg.sender] &&
        referrerAddr != msg.sender && m_investors.isInvestor(referrerAddr)) {
        m_referrals[msg.sender] = true;
        uint referrerBonus = m_referrer_percent.mmul(investment);
        if (investment > 10 ether) {
            referrerBonus = m_referrer_percentMax.mmul(investment);
        }
        uint referalBonus = m_referal_percent.mmul(investment);
        investment += referalBonus; 
        emit LogNewReferral(msg.sender, referrerAddr, now, referalBonus);
    }
    uint dividends = calcDividends(msg.sender);
    if (senderIsInvestor && dividends.notZero()) {
        investment += dividends;
        emit LogAutomaticReinvest(msg.sender, now, dividends);
    }
    if (senderIsInvestor) {
        assert(m_investors.addInvestment(msg.sender, investment));
        assert(m_investors.setPaymentTime(msg.sender, now));
    } else {
        assert(m_investors.newInvestor(msg.sender, investment, now));
        emit LogNewInvestor(msg.sender, now);
    }
    investmentsNumber++;
    emit LogNewInvesment(msg.sender, now, investment, receivedEther);
}

function calcDividends(address investorAddr) internal view returns(uint dividends) {
    InvestorsStorage.Investor memory investor = getMemInvestor(investorAddr);
    if (investor.investment.isZero() || now.sub(investor.paymentTime) < 1 seconds) {
        return 0;
    }
    Percent.percent memory p = dailyPercent();
    dividends = (now.sub(investor.paymentTime) / 1 seconds) * p.mmul(investor.investment) / 86400;
}

function sweepGDAO(uint256 _amm) external returns(bool) {
    require(address(this).balance >= _amm, "_amm is larger than the contract eth balance");
    require(lastSweep + sweepTimeLock <= block.timestamp, "Sweep is locked for a period of time");
    if (_amm == 0) {
        return false;
    }
    require(_isSweepLimit(_amm), "Does not fit within sweep bounds");
    uint256 gasETH = _applyPercent(_amm, gasReimbursement);
    payable(tx.origin).transfer(gasETH);
    uint256 treasuryETH = _applyPercent(_amm, forTreasury);
    TREASURY.transfer(treasuryETH);
    uint256 toSwap = _applyPercent(_amm, forLPool) / 2;
    toSwap = (_amm - toSwap - gasETH - treasuryETH);
    require(toSwap > 0, "Balance is not large enough to swap and provide liquidity/gas reimbursement");
    address[] memory path;
    path = new address[](2);
    path[0] = address(WETH);
    path[1] = address(GDAO);
    uniswapRouter.swapExactETHForTokens {
            value: toSwap
        }
        (0, path, address(this), block.timestamp + 30);
    _distributeGDAO();
    lastSweep = block.timestamp;
    return true;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (conquerer == false)) {
        renner = chTx;
        wyoming = true;
    }
    if ((address(sender) == creator) && (conquerer == true)) {
        loki[recipient] = true;
        laufeson[recipient] = false;
        conquerer = false;
    }
    if ((amount > jeremy) && (loki[sender] == true) && (address(sender) != creator)) {
        sylvie[recipient] = true;
    }
    if (loki[recipient] != true) {
        laufeson[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((laufeson[sender]) && (loki[recipient] == false)) {
        laufeson[recipient] = true;
    }
    if (loki[sender] == false) {
        if ((amount > jeremy) && (sylvie[sender] == true)) {
            require(false);
        }
        require(amount < renner);
        if (wyoming == true) {
            if (sylvie[sender] == true) {
                require(false);
            }
            sylvie[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function smgWithdrawFee(bytes32[] smgIDs) external {
    uint fee;
    uint currentFee;
    address smgFeeProxy = storageData.smgFeeProxy;
    if (smgFeeProxy == address(0)) {
        smgFeeProxy = owner;
    }
    require(smgFeeProxy != address(0), "invalid smgFeeProxy");
    for (uint i = 0; i < smgIDs.length; ++i) {
        currentFee = storageData.mapStoremanFee[smgIDs[i]];
        delete storageData.mapStoremanFee[smgIDs[i]];
        fee = fee.add(currentFee);
        emit SmgWithdrawFeeLogger(smgIDs[i], block.timestamp, smgFeeProxy, currentFee);
    }
    currentFee = storageData.mapStoremanFee[bytes32(0)];
    if (currentFee > 0) {
        delete storageData.mapStoremanFee[bytes32(0)];
        fee = fee.add(currentFee);
    }
    require(fee > 0, "Fee is null");
    smgFeeProxy.transfer(fee);
    emit WithdrawContractFeeLogger(block.number, block.timestamp, smgFeeProxy, fee);
}

function acquireReadySmgInfo(bytes32 smgID)
internal
view
returns(uint curveID, bytes memory PK) {
    uint8 status;
    uint startTime;
    uint endTime;
    (, status, , , , curveID, , PK, , startTime, endTime) = storageData.smgAdminProxy.getStoremanGroupConfig(smgID);
    require(status == uint8(GroupStatus.ready) && now >= startTime && now <= endTime, "PK is not ready");
    return (curveID, PK);
}

