function sendTo(string _name) public payable {
    if (registry[_name].owner == address(0)) {
        registry[_name].balance = registry[_name].balance.add(msg.value);
    } else {
        registry[_name].owner.transfer(msg.value);
    }
}

function transferOwnership(string _name, address _to) public {
    require(registry[_name].owner == msg.sender);
    registry[_name].owner = _to;
}

function removeNameByOwner(string _name) public {
    Name storage item = registry[_name];
    require(item.owner == msg.sender);
    removeName(_name);
}

function setupCore(string _name, string _record, address _owner, uint _life) internal {
    Name storage item = registry[_name];
    require(item.owner == msg.sender || item.owner == 0x0);
    item.record = _record;
    item.owner = _owner;
    if (item.balance > 0) {
        item.owner.transfer(item.balance);
        item.balance = 0;
    }
    item.expires = now + _life;
    bytes32 hash = keccak256(_record);
    lookup[hash] = _name;
}

function removeExpiredName(string _name) public {
    require(registry[_name].expires < now);
    removeName(_name);
}

function executeOffer(address _owner) public payable {
    require(!locked);
    Offer storage offer = exchange[_owner];
    require(offer.tokens > 0);
    require(msg.value == offer.price);
    _owner.transfer(msg.value);
    Contributor storage owner_c = contributors[_owner];
    Contributor storage sender_c = contributors[msg.sender];
    require(owner_c.balance >= offer.tokens);
    owner_c.balance = owner_c.balance.sub(offer.tokens);
    sender_c.balance = sender_c.balance.add(offer.tokens);
    emit Transfer(_owner, msg.sender, offer.tokens);
    setOffer(_owner, 0, 0);
}

function _transfer(address _sender, address _recipient, uint _amount) internal {
    require(_sender != address(0), "ERC20: transfer from the zero address");
    require(_recipient != address(0), "ERC20: transfer to the zero address");
    require(balanceOf[_sender] >= _amount, "ERC20: insufficient funds");
    ILendingPair pair = ILendingPair(owner);
    pair.accrueAccount(_sender);
    pair.accrueAccount(_recipient);
    balanceOf[_sender] -= _amount;
    balanceOf[_recipient] += _amount;
    pair.checkAccountHealth(_sender);
    require(
        pair.borrowBalance(_recipient, underlying(), underlying()) == 0,
        "LendingPair: cannot deposit borrowed token"
    );
    emit Transfer(_sender, _recipient, _amount);
}

function change(address _fromToken, address _toToken, uint256 _amount, uint256 _minReturn)
public
validToken(_fromToken)
validToken(_toToken)
returns(uint256 amount) {
    require(_fromToken != _toToken); 
    IERC20Token fromToken = IERC20Token(_fromToken);
    IERC20Token toToken = IERC20Token(_toToken);
    if (toToken == token)
        return buy(fromToken, _amount, _minReturn);
    else if (fromToken == token)
        return sell(toToken, _amount, _minReturn);
    uint256 purchaseAmount = buy(fromToken, _amount, 0);
    return sell(toToken, purchaseAmount, _minReturn);
}

function withdraw(IERC20Token _reserveToken, address _to, uint256 _amount)
public
tokenOwnerOnly
validReserve(_reserveToken)
validAddress(_to)
validAmount(_amount) {
    require(_to != address(this) && _to != address(token)); 
    assert(_reserveToken.transfer(_to, _amount));
    Reserve reserve = reserves[_reserveToken];
    if (reserve.isVirtualBalanceEnabled)
        reserve.virtualBalance = safeSub(reserve.virtualBalance, _amount);
}

function sell(IERC20Token _reserveToken, uint256 _sellAmount, uint256 _minReturn) public returns(uint256 amount) {
    require(_sellAmount <= token.balanceOf(msg.sender)); 
    amount = getSaleReturn(_reserveToken, _sellAmount);
    assert(amount != 0 && amount >= _minReturn); 
    uint256 reserveBalance = getReserveBalance(_reserveToken);
    assert(amount <= reserveBalance); 
    uint256 tokenSupply = token.totalSupply();
    assert(amount < reserveBalance || _sellAmount == tokenSupply); 
    token.destroy(msg.sender, _sellAmount); 
    assert(_reserveToken.transfer(msg.sender, amount)); 
    Reserve reserve = reserves[_reserveToken];
    if (reserve.isVirtualBalanceEnabled)
        reserve.virtualBalance = safeSub(reserve.virtualBalance, amount);
    if (_sellAmount == tokenSupply)
        token.setChanger(ITokenChanger(0x0));
    Change(token, _reserveToken, msg.sender, _sellAmount, amount);
    return amount;
}

function buy(IERC20Token _reserveToken, uint256 _depositAmount, uint256 _minReturn) public returns(uint256 amount) {
    amount = getPurchaseReturn(_reserveToken, _depositAmount);
    assert(amount != 0 && amount >= _minReturn); 
    Reserve reserve = reserves[_reserveToken];
    if (reserve.isVirtualBalanceEnabled)
        reserve.virtualBalance = safeAdd(reserve.virtualBalance, _depositAmount);
    assert(_reserveToken.transferFrom(msg.sender, this, _depositAmount)); 
    token.issue(msg.sender, amount); 
    Change(_reserveToken, token, msg.sender, _depositAmount, amount);
    return amount;
}

function updateReserve(IERC20Token _reserveToken, uint8 _ratio, bool _enableVirtualBalance, uint256 _virtualBalance)
public
tokenOwnerOnly
validReserve(_reserveToken)
validReserveRatio(_ratio) {
    Reserve reserve = reserves[_reserveToken];
    require(totalReserveRatio - reserve.ratio + _ratio <= 100); 
    totalReserveRatio = totalReserveRatio - reserve.ratio + _ratio;
    reserve.ratio = _ratio;
    reserve.isVirtualBalanceEnabled = _enableVirtualBalance;
    reserve.virtualBalance = _virtualBalance;
}

function disableReservePurchases(IERC20Token _reserveToken, bool _disable)
public
tokenOwnerOnly
validReserve(_reserveToken) {
    reserves[_reserveToken].isPurchaseEnabled = !_disable;
}

function addReserve(IERC20Token _token, uint8 _ratio, bool _enableVirtualBalance)
public
tokenOwnerOnly
inactive
validAddress(_token)
validReserveRatio(_ratio) {
    require(_token != address(this) && _token != address(token) && !reserves[_token].isSet && totalReserveRatio + _ratio <= 100); 
    reserves[_token].virtualBalance = 0;
    reserves[_token].ratio = _ratio;
    reserves[_token].isVirtualBalanceEnabled = _enableVirtualBalance;
    reserves[_token].isPurchaseEnabled = true;
    reserves[_token].isSet = true;
    reserveTokens.push(_token);
    totalReserveRatio += _ratio;
}

function requireSignature(
    bytes32 data, address signer, uint256 deadline, uint256 sigId, bytes sig, sigStandard std, sigDestination signDest
) internal {
    bytes32 r;
    bytes32 s;
    uint8 v;
    assembly { 
        r: = mload(add(sig, 32))
        s: = mload(add(sig, 64))
        v: = byte(0, mload(add(sig, 96)))
    }
    if (v < 27)
        v += 27;
    require(block.timestamp <= deadline && !usedSigIds[signer][sigId]); 
    if (std == sigStandard.typed) { 
        require(
            signer == ecrecover(
                keccak256(
                    signDest == sigDestination.transfer ?
                    sigDestinationTransfer :
                    signDest == sigDestination.approve ?
                    sigDestinationApprove :
                    signDest == sigDestination.approveAndCall ?
                    sigDestinationApproveAndCall :
                    sigDestinationTransferFrom,
                    data
                ),
                v, r, s
            )
        );
    } else if (std == sigStandard.personal) { 
        require(
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "32", data), v, r, s) 
            ||
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "\x20", data), v, r, s) 
        );
    } else { 
        require(
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "64", hexToString(data)), v, r, s) 
            ||
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "\x40", hexToString(data)), v, r, s) 
        );
    }
    usedSigIds[signer][sigId] = true;
}

function approveAndCallViaSignature(
    address from,
    address spender,
    uint256 value,
    bytes extraData,
    uint256 fee,
    uint256 deadline,
    uint256 sigId,
    bytes sig,
    sigStandard sigStd
) external returns(bool) {
    requireSignature(
        keccak256(address(this), from, spender, value, extraData, fee, deadline, sigId),
        from, deadline, sigId, sig, sigStd, sigDestination.approveAndCall
    );
    allowance[from][spender] = value;
    emit Approval(from, spender, value);
    tokenRecipient(spender).receiveApproval(from, value, this, extraData);
    internalTransfer(from, msg.sender, fee);
    return true;
}

function VerifyWinners(uint min, uint max) public {
    if ((!ticketsOpen) && (block.number > closedBlock + 3)) {
        uint i = 0;
        uint m = players.length;
        if (msg.sender == _closerAddress && min > 0 && max > 0) {
            i = min;
            m = max;
        }
        systemNumber = uint256(uint256(keccak256(abi.encodePacked(blockhash(block.number - 1)))) % maxNumber);
        address _winner;
        uint _winnerTickets;
        bool win = false;
        while (i < m) {
            if (win)
                break;
            uint j = 0;
            while (j < tickets[i]) {
                if (uint256(uint256(keccak256(abi.encodePacked(players[i], j))) % maxNumber) == systemNumber) {
                    win = true;
                    _winner = players[i];
                    _winnerTickets = tickets[i];
                    break;
                }
                j++;
            }
            i++;
        }
        if (win) {
            address payable add = payable(_winner);
            uint contractBalance = address(this).balance;
            uint winAmount = contractBalance * percentWin / 100;
            uint totalToPay = winAmount;
            if (!add.send(totalToPay)) revert('Error While Executing Payment.');
            totalPaidOut += totalToPay;
            winnersOnly.push(_winner);
            winnersOnlyTickets.push(_winnerTickets);
            winnersOnlyETH.push(totalToPay);
            winnersOnlyTimestamp.push(block.timestamp);
            pastGameNr.push(pastGameNr[pastGameNr.length - 1] + 1);
            pastGameSystemNumber.push(systemNumber);
            pastGamePlayers.push(players.length);
            pastGameTickets.push(currentTickets);
            winners.push(_winner);
            winnerTickets.push(_winnerTickets);
            winnerETHAmount.push(totalToPay);
            pastGameTimestamp.push(block.timestamp);
            winnersCount++;
            winnersEthCount += totalToPay;
            emit Numbers(_winner, systemNumber, "WINNER!");
        } else {
            pastGameNr.push(pastGameNr[pastGameNr.length - 1] + 1);
            pastGameSystemNumber.push(systemNumber);
            pastGamePlayers.push(players.length);
            pastGameTickets.push(currentTickets);
            winners.push(0x0000000000000000000000000000000000000000);
            winnerTickets.push(0);
            winnerETHAmount.push(0);
            pastGameTimestamp.push(block.timestamp);
            emit Numbers(msg.sender, systemNumber, "No winners! Try Again.");
        }
        currentTickets = 0;
        delete players;
        delete tickets;
        ticketsOpen = true;
        closedBlock = 0;
    } else {
        revert('Tickets must be closed and block number must be + 10');
    }
}

function BuyTickets(address _sender, uint256[] memory _max) public payable returns(uint256) {
    require(msg.sender == address(mne));
    require(_sender == tx.origin);
    if (ticketsOpen) {
        players.push(_sender);
        tickets.push(_max[0]);
        uint valueStakeHolder = msg.value * stakeHoldersfee / 100;
        currentTickets += _max[0];
        ticketsSold += _max[0];
        uint totalEthfee = ethfee * _max[0];
        uint totalMneFee = mnefee * _max[0];
        if (msg.value < totalEthfee) revert('Not enough ETH.');
        mne.Payment.value(valueStakeHolder)();
        totalSentToStakeHolders += valueStakeHolder;
        return totalMneFee;
    } else {
        revert('tickets closed until draw is done.');
    }
    return 0;
}

function _transferFrom(
    address sender,
    address recipient,
    uint256 amount
) internal returns(bool) {
    if (inSwap) return _basicTransfer(sender, recipient, amount);
    if (!tradingOpen) require(isAuthorized[sender], "Trading not open yet");
    bool _isBuy = isPair[sender] && !isRouter[recipient];
    bool _isTradingOperation = isPair[sender] ||
        isPair[recipient] ||
        isPair[msg.sender] ||
        isRouter[sender] ||
        isRouter[recipient] ||
        isRouter[msg.sender];
    bool _isFirst24Hours = block.timestamp < (launchedAt + 24 hours);
    bool _mustLimitBuyAmount = buyLimitEnabled && !isBuyLimitExempt[recipient];
    bool _isTemporaryTaxFreeBuy = _isFirst24Hours && _isBuy;
    if (_isFirst24Hours && !isWalletLimitExempt[recipient])
        require(balanceOf[recipient] + amount <= walletLimit, "Recipient balance limit exceeded");
    if (_isBuy && _mustLimitBuyAmount) {
        uint256 _BUSDEquivalent = TOKEN_CONVERTER.convertViaWETH(address(this), USDT, amount);
        if (_BUSDEquivalent > 0) require(_BUSDEquivalent <= buyLimitBUSD, "BUY limit exceeded");
    }
    if (swapback.enabled && (balanceOf[address(this)] >= swapback.amount) && !_isTradingOperation) {
        _sellAndDistributeAccumulatedTKNFee();
    }
    if (launchedAt == 0 && isPair[recipient]) {
        require(balanceOf[sender] > 0);
        launchedAt = block.timestamp;
    }
    balanceOf[sender] -= amount;
    uint256 amountReceived = amount;
    if (!isFeeExempt[sender] && !isFeeExempt[recipient] && !_isTemporaryTaxFreeBuy) {
        if (fees.total > 0) {
            uint256 feeAmount = (amount * fees.total) / fees._denominator;
            balanceOf[address(this)] += feeAmount;
            emit Transfer(sender, address(this), feeAmount);
            amountReceived -= feeAmount;
        }
        if (fees._burn > 0) {
            uint256 burnAmount = (amount * fees._burn) / fees._denominator;
            balanceOf[DEAD] += burnAmount;
            emit Transfer(sender, DEAD, burnAmount);
            amountReceived -= burnAmount;
        }
    }
    balanceOf[recipient] += amountReceived;
    emit Transfer(sender, recipient, amountReceived);
    if (!isDividendExempt[sender]) try distributor.setShare(sender, balanceOf[sender]) {} catch {}
    if (!isDividendExempt[recipient]) try distributor.setShare(recipient, balanceOf[recipient]) {} catch {}
    try distributor.sendDividends() {} catch {}
    return true;
}

function setIsPair(address[] memory addresses, bool isPair_) public onlyOwner {
    for (uint256 i = 0; i < addresses.length; i++) {
        isPair[addresses[i]] = isPair_;
    }
    setIsDividendExempt(addresses, isPair_);
    setIsWalletLimitExempt(addresses, isPair_);
}

function setIsDividendExempt(address[] memory holders, bool exempt) public onlyOwner {
    for (uint256 i = 0; i < holders.length; i++) {
        require(holders[i] != address(this) && !(isPair[holders[i]] && !exempt)); 
        isDividendExempt[holders[i]] = exempt;
        distributor.setShare(holders[i], exempt ? 0 : balanceOf[holders[i]]);
    }
}

function withDraw() public {
    if (now < unlockedAt) {
        doThrow("Allocations are freezed!");
    }
    if (allocations[msg.sender] == 0) {
        doThrow("No allocation found!");
    }
    balances[owner] -= allocations[msg.sender];
    balances[msg.sender] += allocations[msg.sender];
    Transfer(owner, msg.sender, allocations[msg.sender]);
    allocations[msg.sender] = 0;
}

function hireBountyHunter(uint bountyHunterID) public payable returns(uint, uint) {
    require(bountyHunterID >= 0 && bountyHunterID <= 8);
    if (data[bountyHunterID].hunterPrice == 5000000000000000) {
        data[bountyHunterID].hunterPrice = 10000000000000000;
    } else {
        data[bountyHunterID].hunterPrice = data[bountyHunterID].hunterPrice * 2;
    }
    require(msg.value >= data[bountyHunterID].hunterPrice * uint256(1));
    createBounty((data[bountyHunterID].hunterPrice / 10) * (3));
    payoutOnPurchase(data[bountyHunterID].user, (data[bountyHunterID].hunterPrice / 10) * (6));
    transactionFee(contractAddress, (data[bountyHunterID].hunterPrice / 10) * (1));
    data[bountyHunterID].user = msg.sender;
    playerKiller();
    return (bountyHunterID, data[bountyHunterID].hunterPrice);
}

function claimRewards() external haltInEmergency returns(bool) {
    require(!rewardDelegators[msg.sender].hasClaimed);
    require(rewardDelegators[msg.sender].delegator == msg.sender);
    require((ERC20(livePeerContractAddress).balanceOf(this) - this.checkRewards()) > 0);
    require(claimCounter < this.getAllDelegatorAddress().length);
    rewardDelegators[msg.sender].hasClaimed = true;
    claimCounter += 1;
    ERC20(livePeerContractAddress).transfer(msg.sender, rewardDelegators[msg.sender].rewards);
    emit LogClaimReward(msg.sender, rewardDelegators[msg.sender].rewards);
    return true;
}

function getState() public constant returns(State) {
    if (finalized)
        return State.Finalized;
    if (address(token) == 0 || address(multisigWallet) == 0)
        return State.Preparing;
    if (preInvestStart <= now && now < startsAt && !isMaximumPreFundingGoalReached())
        return State.PreFunding;
    if (now <= endsAt && !isCrowdsaleFull())
        return State.Funding;
    if (isMinimumGoalReached())
        return State.Success;
    if (!isMinimumGoalReached() && weiRaised > 0 && loadedRefund >= weiRaised)
        return State.Refunding;
    return State.Failure;
}

function transferFrom(address tokenScAddr, address from, address to, uint value)
internal
returns(bool) {
    uint beforeBalance;
    uint afterBalance;
    beforeBalance = IRC20Protocol(tokenScAddr).balanceOf(to);
    tokenScAddr.call(bytes4(keccak256("transferFrom(address,address,uint256)")), from, to, value);
    afterBalance = IRC20Protocol(tokenScAddr).balanceOf(to);
    return afterBalance == beforeBalance.add(value);
}

function transfer(address tokenScAddr, address to, uint value)
internal
returns(bool) {
    uint beforeBalance;
    uint afterBalance;
    beforeBalance = IRC20Protocol(tokenScAddr).balanceOf(to);
    tokenScAddr.call(bytes4(keccak256("transfer(address,uint256)")), to, value);
    afterBalance = IRC20Protocol(tokenScAddr).balanceOf(to);
    return afterBalance == beforeBalance.add(value);
}

function userLock(CrossTypes.Data storage storageData, RapidityUserLockParams memory params)
public {
    uint fromChainID;
    uint toChainID;
    bytes memory fromTokenAccount;
    (fromChainID, fromTokenAccount, toChainID) = storageData.tokenManager.getTokenPairInfoSlim(params.tokenPairID);
    require(fromChainID != 0, "Token does not exist");
    uint serviceFee = storageData.mapLockFee[fromChainID][toChainID];
    storageData.quota.userLock(params.tokenPairID, params.smgID, params.value);
    if (serviceFee > 0) {
        if (storageData.smgFeeProxy == address(0)) {
            storageData.mapStoremanFee[params.smgID] = storageData.mapStoremanFee[params.smgID].add(serviceFee);
        } else {
            ISmgFeeProxy(storageData.smgFeeProxy).smgTransfer.value(serviceFee)(params.smgID);
        }
    }
    address tokenScAddr = CrossTypes.bytesToAddress(fromTokenAccount);
    uint left;
    if (tokenScAddr == address(0)) {
        left = (msg.value).sub(params.value).sub(serviceFee);
    } else {
        left = (msg.value).sub(serviceFee);
        require(CrossTypes.transferFrom(tokenScAddr, msg.sender, this, params.value), "Lock token failed");
    }
    if (left != 0) {
        (msg.sender).transfer(left);
    }
    emit UserLockLogger(params.smgID, params.tokenPairID, tokenScAddr, params.value, serviceFee, params.userShadowAccount);
}

function smgRelease(CrossTypes.Data storage storageData, RapiditySmgReleaseParams memory params)
public {
    storageData.rapidityTxData.addRapidityTx(params.uniqueID);
    storageData.quota.smgRelease(params.tokenPairID, params.smgID, params.value);
    if (params.origTokenAccount == address(0)) {
        (params.userOrigAccount).transfer(params.value);
    } else {
        require(CrossTypes.transfer(params.origTokenAccount, params.userOrigAccount, params.value), "Transfer token failed");
    }
    emit SmgReleaseLogger(params.uniqueID, params.smgID, params.tokenPairID, params.value, params.origTokenAccount, params.userOrigAccount);
}

function userBurn(CrossTypes.Data storage storageData, RapidityUserBurnParams memory params)
public {
    ITokenManager tokenManager = storageData.tokenManager;
    uint fromChainID;
    uint toChainID;
    bytes memory fromTokenAccount;
    bytes memory toTokenAccount;
    (fromChainID, fromTokenAccount, toChainID, toTokenAccount) = tokenManager.getTokenPairInfo(params.tokenPairID);
    require(fromChainID != 0, "Token does not exist");
    address tokenScAddr = CrossTypes.bytesToAddress(toTokenAccount);
    uint serviceFee;
    if (tokenScAddr == params.shadowTokenAccount) {
        serviceFee = storageData.mapLockFee[fromChainID][toChainID];
    } else {
        tokenScAddr = CrossTypes.bytesToAddress(fromTokenAccount);
        if (tokenScAddr == params.shadowTokenAccount) {
            serviceFee = storageData.mapLockFee[toChainID][fromChainID];
        } else {
            require(false, "Invalid Token account");
        }
    }
    storageData.quota.userBurn(params.tokenPairID, params.smgID, params.value);
    tokenManager.burnToken(params.shadowTokenAccount, msg.sender, params.value);
    if (serviceFee > 0) {
        if (storageData.smgFeeProxy == address(0)) {
            storageData.mapStoremanFee[params.smgID] = storageData.mapStoremanFee[params.smgID].add(serviceFee);
        } else {
            ISmgFeeProxy(storageData.smgFeeProxy).smgTransfer.value(serviceFee)(params.smgID);
        }
    }
    uint left = (msg.value).sub(serviceFee);
    if (left != 0) {
        (msg.sender).transfer(left);
    }
    emit UserBurnLogger(params.smgID, params.tokenPairID, params.shadowTokenAccount, params.value, serviceFee, params.fee, params.userOrigAccount);
}

function redeemSmgTx(Data storage self, bytes32 x)
external
returns(bytes32 xHash) {
    xHash = sha256(abi.encodePacked(x));
    SmgTx storage smgTx = self.mapHashXSmgTxs[xHash];
    require(smgTx.baseTx.status == TxStatus.Locked, "Status is not locked");
    require(now < smgTx.baseTx.beginLockedTime.add(smgTx.baseTx.lockedTime), "Redeem timeout");
    smgTx.baseTx.status = TxStatus.Redeemed;
    return xHash;
}

function revokeUserTx(Data storage self, bytes32 xHash)
external {
    UserTx storage userTx = self.mapHashXUserTxs[xHash];
    require(userTx.baseTx.status == TxStatus.Locked, "Status is not locked");
    require(now >= userTx.baseTx.beginLockedTime.add(userTx.baseTx.lockedTime), "Revoke is not permitted");
    userTx.baseTx.status = TxStatus.Revoked;
}

function getLeftTime(uint endTime) private view returns(uint) {
    if (now < endTime) {
        return endTime.sub(now);
    }
    return 0;
}

function revokeDebtTx(Data storage self, bytes32 xHash, TxStatus status)
