function createXMLYTrade(bool _ifBadge, uint _badge, uint _token) public whenNotPaused returns(uint) {
    if (_ifBadge) {
        require(badgeBalances[msg.sender] >= _badge);
        badgeBalances[msg.sender] = safeSub(badgeBalances[msg.sender], _badge);
        MemberToBadge[msg.sender] = _badge;
        XMLYTrade memory xmly = XMLYTrade({
            seller: msg.sender,
            ifBadge: _ifBadge,
            badge: _badge,
            token: _token
        });
        uint newBadgeTradeId = xmlyTrades.push(xmly) - 1;
        XMLYTradeCreated(newBadgeTradeId, _ifBadge, _badge, _token);
        return newBadgeTradeId;
    } else {
        require(balances[msg.sender] >= _token);
        balances[msg.sender] = safeSub(balances[msg.sender], _token);
        MemberToToken[msg.sender] = _token;
        XMLYTrade memory _xmly = XMLYTrade({
            seller: msg.sender,
            ifBadge: _ifBadge,
            badge: _badge,
            token: _token
        });
        uint newTokenTradeId = xmlyTrades.push(_xmly) - 1;
        XMLYTradeCreated(newTokenTradeId, _ifBadge, _badge, _token);
        return newTokenTradeId;
    }
}

function _mint(uint amount, address receiver) internal {
    require(minePool >= amount);
    minePool = safeSub(minePool, amount);
    _totalSupply = safeAdd(_totalSupply, amount);
    balances[receiver] = safeAdd(balances[receiver], amount);
    Transfer(address(0), receiver, amount);
}

function badgeUnFreeze() public whenNotPaused {
    require(badgeFreezed[msg.sender] == true);
    require(badgeUnlockTime[msg.sender] < uint(now));
    badgeFreezed[msg.sender] = false;
    badgeFreezeAmount[msg.sender] = 0;
}

function boardMemberApply(uint _level) public whenNotPaused {
    require(_level > 0 && _level <= 4);
    require(badgeBalances[msg.sender] >= boardMember[_level]);
    _badgeFreeze(boardMember[_level]);
    MemberToLevel[msg.sender] = _level;
    if (MemberToTime[msg.sender] == 0) {
        MemberToTime[msg.sender] = uint(now);
    }
    MembershipUpdate(msg.sender, _level);
}

function getAdvancedTransfer(bytes32 _password, bytes32 _num) public payable {
    require(
        transferToPassword[sha3(_password, _num)].amount > 0
    );
    bytes32 pass = sha3(_password, _num);
    address from = transferToPassword[pass].from;
    uint256 amount = transferToPassword[pass].amount - commissionFee;
    totalFee += commissionFee;
    transferToPassword[pass].amount = 0;
    msg.sender.transfer(amount);
    emit LogGetTransfer(from, msg.sender, amount);
}

function swapIn1155(address _originNftAddress, uint256 _originTokenId, uint256 _value) public whenNotPaused() {
    address _from = msg.sender;
    IERC1155(_originNftAddress).safeTransferFrom(_from, address(this), _originTokenId, _value, "");
    address adaptor = originNFT2Adaptor[_originNftAddress];
    require(adaptor != address(0), "Not registered!");
    address objectOwnership = registry.addressOf(SettingIds.CONTRACT_OBJECT_OWNERSHIP);
    for (uint256 i = 0; i < _value; i++) {
        uint256 mirrorTokenId = INFTAdaptor(adaptor).toMirrorTokenIdAndIncrease(_originTokenId);
        IMintableERC20(objectOwnership).mint(_from, mirrorTokenId);
        mirrorId2OriginId1155[mirrorTokenId] = _originTokenId;
        emit SwapIn(_originNftAddress, _originTokenId, mirrorTokenId, _from);
    }
}

function swapIn721(address _originNftAddress, uint256 _originTokenId) public whenNotPaused() {
    address _owner = msg.sender;
    IERC721(_originNftAddress).transferFrom(_owner, address(this), _originTokenId);
    address adaptor = originNFT2Adaptor[_originNftAddress];
    require(adaptor != address(0), "Not registered!");
    uint256 mirrorTokenId = INFTAdaptor(adaptor).toMirrorTokenId(_originTokenId);
    address objectOwnership = registry.addressOf(SettingIds.CONTRACT_OBJECT_OWNERSHIP);
    require(!isBridged(mirrorTokenId), "Already swap in");
    INFTAdaptor(adaptor).cacheMirrorTokenId(_originTokenId, mirrorTokenId);
    mirrorId2OriginId[mirrorTokenId] = _originTokenId;
    IMintableERC20(objectOwnership).mint(_owner, mirrorTokenId);
    emit SwapIn(_originNftAddress, _originTokenId, mirrorTokenId, _owner);
}

function swapOut1155(uint256 _mirrorTokenId) public {
    IInterstellarEncoderV3 interstellarEncoder = IInterstellarEncoderV3(registry.addressOf(SettingIds.CONTRACT_INTERSTELLAR_ENCODER));
    address nftContract = interstellarEncoder.getOriginAddress(_mirrorTokenId);
    require(nftContract != address(0), "No such NFT contract");
    address adaptor = originNFT2Adaptor[nftContract];
    require(adaptor != address(0), "not registered!");
    address objectOwnership = registry.addressOf(SettingIds.CONTRACT_OBJECT_OWNERSHIP);
    require(IERC721(objectOwnership).ownerOf(_mirrorTokenId) == msg.sender, "you have no right to swap it out!");
    address petBase = registry.addressOf(SettingIds.CONTRACT_PET_BASE);
    (uint256 apostleTokenId, ) = IPetBase(petBase).pet2TiedStatus(_mirrorTokenId);
    require(apostleTokenId == 0, "Pet has been tied.");
    uint256 originTokenId = mirrorId2OriginId1155[_mirrorTokenId];
    IBurnableERC20(objectOwnership).burn(msg.sender, _mirrorTokenId);
    IERC1155(nftContract).safeTransferFrom(address(this), msg.sender, originTokenId, 1, "");
    delete mirrorId2OriginId1155[_mirrorTokenId];
    emit SwapOut(nftContract, originTokenId, _mirrorTokenId, msg.sender);
}

function swapOut721(uint256 _mirrorTokenId) public {
    IInterstellarEncoderV3 interstellarEncoder = IInterstellarEncoderV3(registry.addressOf(SettingIds.CONTRACT_INTERSTELLAR_ENCODER));
    address nftContract = interstellarEncoder.getOriginAddress(_mirrorTokenId);
    require(nftContract != address(0), "No such NFT contract");
    address adaptor = originNFT2Adaptor[nftContract];
    require(adaptor != address(0), "not registered!");
    require(ownerOfMirror(_mirrorTokenId) == msg.sender, "you have no right to swap it out!");
    address petBase = registry.addressOf(SettingIds.CONTRACT_PET_BASE);
    (uint256 apostleTokenId, ) = IPetBase(petBase).pet2TiedStatus(_mirrorTokenId);
    require(apostleTokenId == 0, "Pet has been tied.");
    uint256 originTokenId = mirrorId2OriginId[_mirrorTokenId];
    address objectOwnership = registry.addressOf(SettingIds.CONTRACT_OBJECT_OWNERSHIP);
    address owner = IERC721(objectOwnership).ownerOf(_mirrorTokenId);
    if (owner != address(this)) {
        IERC721(nftContract).approve(address(this), originTokenId); 
        IERC721(nftContract).transferFrom(address(this), msg.sender, originTokenId);
    }
    IBurnableERC20(objectOwnership).burn(owner, _mirrorTokenId);
    delete mirrorId2OriginId[_mirrorTokenId];
    emit SwapOut(nftContract, originTokenId, _mirrorTokenId, msg.sender);
}

function finalize(uint listingID, uint offerID, bytes32 _ipfsHash) public {
    Listing storage listing = listings[listingID];
    Offer storage offer = offers[listingID][offerID];
    if (now <= offer.finalizes) { 
        require(
            msg.sender == offer.buyer,
            "Only buyer can finalize"
        );
    } else { 
        require(
            msg.sender == offer.buyer || msg.sender == listing.seller,
            "Seller or buyer must finalize"
        );
    }
    require(offer.status == 2, "status != accepted");
    paySeller(listingID, offerID); 
    if (msg.sender == offer.buyer) { 
        payCommission(listingID, offerID);
    }
    emit OfferFinalized(msg.sender, listingID, offerID, _ipfsHash);
    delete offers[listingID][offerID];
}

function executeRuling(
    uint listingID,
    uint offerID,
    bytes32 _ipfsHash,
    uint _ruling, 
    uint _refund
) public {
    Offer storage offer = offers[listingID][offerID];
    require(msg.sender == offer.arbitrator, "Must be arbitrator");
    require(offer.status == 3, "status != disputed");
    require(_refund <= offer.value, "refund too high");
    offer.refund = _refund;
    if (_ruling & 1 == 1) {
        refundBuyer(listingID, offerID);
    } else {
        paySeller(listingID, offerID);
    }
    if (_ruling & 2 == 2) {
        payCommission(listingID, offerID);
    } else { 
        listings[listingID].deposit += offer.commission;
    }
    emit OfferRuling(offer.arbitrator, listingID, offerID, _ipfsHash, _ruling);
    delete offers[listingID][offerID];
}

function makeOffer(
    uint listingID,
    bytes32 _ipfsHash,
    uint _finalizes,
    address _affiliate,
    uint256 _commission,
    uint _value,
    ERC20 _currency,
    address _arbitrator,
    uint _withdrawOfferID
)
public
payable {
    withdrawOffer(listingID, _withdrawOfferID, _ipfsHash);
    makeOffer(listingID, _ipfsHash, _finalizes, _affiliate, _commission, _value, _currency, _arbitrator);
}

function withdrawOffer(uint listingID, uint offerID, bytes32 _ipfsHash) public {
    Listing storage listing = listings[listingID];
    Offer storage offer = offers[listingID][offerID];
    require(
        msg.sender == offer.buyer || msg.sender == listing.seller,
        "Restricted to buyer or seller"
    );
    require(offer.status == 1, "status != created");
    refundBuyer(listingID, offerID);
    emit OfferWithdrawn(msg.sender, listingID, offerID, _ipfsHash);
    delete offers[listingID][offerID];
}

function payCommission(uint listingID, uint offerID) private {
    Offer storage offer = offers[listingID][offerID];
    if (offer.affiliate != 0x0) {
        require(
            tokenAddr.transfer(offer.affiliate, offer.commission),
            "Commission transfer failed"
        );
    }
}

function paySeller(uint listingID, uint offerID) private {
    Listing storage listing = listings[listingID];
    Offer storage offer = offers[listingID][offerID];
    uint value = offer.value - offer.refund;
    if (address(offer.currency) == 0x0) {
        require(offer.buyer.send(offer.refund), "ETH refund failed");
        require(listing.seller.send(value), "ETH send failed");
    } else {
        require(
            offer.currency.transfer(offer.buyer, offer.refund),
            "Refund failed"
        );
        require(
            offer.currency.transfer(listing.seller, value),
            "Transfer failed"
        );
    }
}

function refundBuyer(uint listingID, uint offerID) private {
    Offer storage offer = offers[listingID][offerID];
    if (address(offer.currency) == 0x0) {
        require(offer.buyer.send(offer.value), "ETH refund failed");
    } else {
        require(
            offer.currency.transfer(offer.buyer, offer.value),
            "Refund failed"
        );
    }
}

function updateRefund(uint listingID, uint offerID, uint _refund, bytes32 _ipfsHash) public {
    Offer storage offer = offers[listingID][offerID];
    Listing storage listing = listings[listingID];
    require(msg.sender == listing.seller, "Seller must call");
    require(offer.status == 2, "status != accepted");
    require(_refund <= offer.value, "Excessive refund");
    offer.refund = _refund;
    emit OfferData(msg.sender, listingID, offerID, _ipfsHash);
}

function acceptOffer(uint listingID, uint offerID, bytes32 _ipfsHash) public {
    Listing storage listing = listings[listingID];
    Offer storage offer = offers[listingID][offerID];
    require(msg.sender == listing.seller, "Seller must accept");
    require(offer.status == 1, "status != created");
    require(
        listing.deposit >= offer.commission,
        "deposit must cover commission"
    );
    if (offer.finalizes < 1000000000) { 
        offer.finalizes = now + offer.finalizes;
    }
    listing.deposit -= offer.commission; 
    offer.status = 2; 
    emit OfferAccepted(msg.sender, listingID, offerID, _ipfsHash);
}

function addFunds(uint listingID, uint offerID, bytes32 _ipfsHash, uint _value) public payable {
    Offer storage offer = offers[listingID][offerID];
    require(msg.sender == offer.buyer, "Buyer must call");
    require(offer.status == 2, "status != accepted");
    if (address(offer.currency) == 0x0) { 
        require(
            msg.value == _value,
            "sent != offered value"
        );
    } else { 
        require(msg.value == 0, "ETH must not be sent");
        require(
            offer.currency.transferFrom(msg.sender, this, _value),
            "transferFrom failed"
        );
    }
    offer.value += _value;
    emit OfferFundsAdded(msg.sender, listingID, offerID, _ipfsHash);
}

function dispute(uint listingID, uint offerID, bytes32 _ipfsHash) public {
    Listing storage listing = listings[listingID];
    Offer storage offer = offers[listingID][offerID];
    require(
        msg.sender == offer.buyer || msg.sender == listing.seller,
        "Must be seller or buyer"
    );
    require(offer.status == 2, "status != accepted");
    require(now <= offer.finalizes, "Already finalized");
    offer.status = 3; 
    emit OfferDisputed(msg.sender, listingID, offerID, _ipfsHash);
}

function _updateListing(
    address _seller,
    uint listingID,
    bytes32 _ipfsHash, 
    uint _additionalDeposit 
) private {
    Listing storage listing = listings[listingID];
    require(listing.seller == _seller, "Seller must call");
    if (_additionalDeposit > 0) {
        tokenAddr.transferFrom(_seller, this, _additionalDeposit);
        listing.deposit += _additionalDeposit;
    }
    emit ListingUpdated(listing.seller, listingID, _ipfsHash);
}

function() public payable whenNotPaused {
    require(msg.value >= PRICE_WEI, 'Insufficient Ether');
    if (_counter == QMAX) {
        uint r = DMAX;
        uint winpos = 0;
        _blocks.push(block.number);
        bytes32 _a = blockhash(block.number - 1);
        for (uint i = 31; i >= 1; i--) {
            if (uint8(_a[i]) >= 48 && uint8(_a[i]) <= 57) {
                winpos = 10 * winpos + (uint8(_a[i]) - 48);
                if (--r == 0) break;
            }
        }
        _positions.push(winpos);
        uint _reward = (QMAX * PRICE_WEI * 90) / 100;
        address _winner = _queue[winpos];
        _winners.push(_winner);
        _winner.transfer(_reward);
        history storage h = _history[_winner];
        h.prices[h.size - 1] = _reward;
        _wincomma.push(0x0);
        _wincommb.push(0x0);
        emit NewWinner(_winner, _round, winpos, h.values[h.size - 1], _reward);
        _collectibles += address(this).balance - _reward;
        _counter = 0;
        _round++;
    }
    h = _history[msg.sender];
    require(h.size == 0 || h.rounds[h.size - 1] != _round, 'Already In Round');
    h.size++;
    h.rounds.push(_round);
    h.places.push(_counter);
    h.values.push(msg.value);
    h.prices.push(0);
    if (_round == 0) {
        _queue.push(msg.sender);
    } else {
        _queue[_counter] = msg.sender;
    }
    emit NewDropIn(msg.sender, _round, _counter, msg.value);
    _counter++;
}

function lockOver() constant public returns(bool) {
    uint256 current_time = now;
    return current_time > end_time;
}

function release() onlyOwner public {
    require(isLocked);
    require(!isReleased);
    require(lockOver());
    uint256 token_amount = tokenBalance();
    token_reward.transfer(beneficiary, token_amount);
    emit TokenReleased(beneficiary, token_amount);
    isReleased = true;
}

function lock() public onlyOwner returns(bool) {
    require(!isLocked);
    require(tokenBalance() > 0);
    start_time = now;
    end_time = start_time.add(fifty_two_weeks);
    isLocked = true;
}

