}

function getMilk() public {
    require(count[msg.sender] == 1);
    uint _cowId = ownerCow[msg.sender];
    Cow storage currentCow = cows[_cowId];
    require(_isReady(currentCow));
    uint32 addMilk = uint32(random());
    allMilk = allMilk + uint(addMilk);
    currentCow.milk += addMilk;
    currentCow.readyTime = uint32(now + 1 hours);
    emit GetMilkEvent(addMilk, currentCow.readyTime);
}

function _isReady(Cow storage _cow) internal view returns(bool) {
    return (_cow.readyTime <= now);
}

function increaseBidSize(uint256 id, uint256 amountToBuy, uint256 bid) external {
    require(bids[id].highBidder != address(0), "PostSettlementSurplusAuctionHouse/high-bidder-not-set");
    require(bids[id].bidExpiry > now || bids[id].bidExpiry == 0, "PostSettlementSurplusAuctionHouse/bid-already-expired");
    require(bids[id].auctionDeadline > now, "PostSettlementSurplusAuctionHouse/auction-already-expired");
    require(amountToBuy == bids[id].amountToSell, "PostSettlementSurplusAuctionHouse/amounts-not-matching");
    require(bid > bids[id].bidAmount, "PostSettlementSurplusAuctionHouse/bid-not-higher");
    require(multiply(bid, ONE) >= multiply(bidIncrease, bids[id].bidAmount), "PostSettlementSurplusAuctionHouse/insufficient-increase");
    if (msg.sender != bids[id].highBidder) {
        protocolToken.move(msg.sender, bids[id].highBidder, bids[id].bidAmount);
        bids[id].highBidder = msg.sender;
    }
    protocolToken.move(msg.sender, address(this), bid - bids[id].bidAmount);
    bids[id].bidAmount = bid;
    bids[id].bidExpiry = addUint48(uint48(now), bidDuration);
    emit IncreaseBidSize(id, msg.sender, amountToBuy, bid, bids[id].bidExpiry);
}

function addUint48(uint48 x, uint48 y) internal pure returns(uint48 z) {
    require((z = x + y) >= x);
}

function restartAuction(uint256 id) external {
    require(bids[id].auctionDeadline < now, "PostSettlementSurplusAuctionHouse/not-finished");
    require(bids[id].bidExpiry == 0, "PostSettlementSurplusAuctionHouse/bid-already-placed");
    bids[id].auctionDeadline = addUint48(uint48(now), totalAuctionLength);
    emit RestartAuction(id, bids[id].auctionDeadline);
}

function settleAuction(uint256 id) external {
    require(bids[id].bidExpiry != 0 && (bids[id].bidExpiry < now || bids[id].auctionDeadline < now), "PostSettlementSurplusAuctionHouse/not-finished");
    safeEngine.transferInternalCoins(address(this), bids[id].highBidder, bids[id].amountToSell);
    protocolToken.burn(address(this), bids[id].bidAmount);
    delete bids[id];
    emit SettleAuction(id);
}

function _updateBalance(address holder) private {
    uint256 undistributed = getProductedAmount().sub(_distributed);
    uint256 undistributedCow = undistributed.div(5); 
    uint256 undistributedCowLP = (undistributed.sub(undistributedCow)).div(2); 
    uint256 undistributedMilkLP = (undistributed.sub(undistributedCow)).sub(undistributedCowLP); 
    if (address(_stableCow) != address(0)) {
        (uint256 power, uint256 totalPower) = (_stableCow.power(holder), _stableCow.totalPower());
        if (power > 0) {
            power = _stableCow.usePower(holder);
            undistributedCow = totalPower > 0 ? undistributedCow.mul(power).div(totalPower) : 0;
        }
    } else {
        undistributedCow = 0;
    }
    if (address(_stableCowLP) != address(0)) {
        (uint256 power, uint256 totalPower) = (_stableCowLP.power(holder), _stableCowLP.totalPower());
        if (power > 0) {
            power = _stableCowLP.usePower(holder);
            undistributedCowLP = totalPower > 0 ? undistributedCowLP.mul(power).div(totalPower) : 0;
        }
    } else {
        undistributedCowLP = 0;
    }
    if (address(_stableMilkLP) != address(0)) {
        (uint256 power, uint256 totalPower) = (_stableMilkLP.power(holder), _stableMilkLP.totalPower());
        if (power > 0) {
            power = _stableMilkLP.usePower(holder);
            undistributedMilkLP = totalPower > 0 ? undistributedMilkLP.mul(power).div(totalPower) : 0;
        }
    } else {
        undistributedMilkLP = 0;
    }
    uint256 devTeamFee = (undistributedCow.add(undistributedCowLP).add(undistributedMilkLP)).div(20);
    uint256 tokens = undistributedCow.add(undistributedCowLP).add(undistributedMilkLP).sub(devTeamFee);
    _balances[holder] = _balances[holder].add(tokens.mul(_unitsPerTokenInBalances));
    _balances[DEV_TEAM_ADDRESS] = _balances[DEV_TEAM_ADDRESS].add(devTeamFee.mul(_unitsPerTokenWhitelisted));
    _distributed = _distributed.add(tokens).add(devTeamFee);
    _totalSupply = _totalSupply.add(tokens).add(devTeamFee);
    if (isWhitelisted(holder)) {
        _supplyWhitelisted = _supplyWhitelisted.add(tokens);
    } else {
        _supplyInBalances = _supplyInBalances.add(tokens);
    }
    if (isWhitelisted(DEV_TEAM_ADDRESS)) {
        _supplyWhitelisted = _supplyWhitelisted.add(devTeamFee);
    } else {
        _supplyInBalances = _supplyInBalances.add(devTeamFee);
    }
}

function transferFrom(address from, address to, uint256 value) public validRecipient(to) returns(bool) {
    _updateBalance(from);
    _allowances[from][msg.sender] = _allowances[from][msg.sender].sub(value);
    uint256 units = value.mul(_unitsPerTokenInBalances);
    uint256 wunits = value.mul(_unitsPerTokenWhitelisted);
    if (isWhitelisted(from) && isWhitelisted(to)) {
        _whitelistedBalances[from] = _whitelistedBalances[from].sub(wunits);
        _whitelistedBalances[to] = _whitelistedBalances[to].add(wunits);
    } else if (isWhitelisted(from)) {
        _whitelistedBalances[from] = _whitelistedBalances[from].sub(wunits);
        _balances[to] = _balances[to].add(units);
        _supplyInBalances = _supplyInBalances.add(value);
        _supplyWhitelisted = _supplyWhitelisted.sub(value);
    } else if (isWhitelisted(to)) {
        _balances[from] = _balances[from].sub(units);
        _whitelistedBalances[to] = _whitelistedBalances[to].add(wunits);
        _supplyInBalances = _supplyInBalances.sub(value);
        _supplyWhitelisted = _supplyWhitelisted.add(value);
    } else {
        _balances[from] = _balances[from].sub(units);
        _balances[to] = _balances[to].add(units);
    }
    emit Transfer(from, to, value);
    return true;
}

function transfer(address to, uint256 value) public validRecipient(to) returns(bool) {
    address from = msg.sender;
    _updateBalance(from);
    uint256 units = value.mul(_unitsPerTokenInBalances);
    uint256 wunits = value.mul(_unitsPerTokenWhitelisted);
    if (isWhitelisted(from) && isWhitelisted(to)) {
        _whitelistedBalances[from] = _whitelistedBalances[from].sub(wunits);
        _whitelistedBalances[to] = _whitelistedBalances[to].add(wunits);
    } else if (isWhitelisted(from)) {
        _whitelistedBalances[from] = _whitelistedBalances[from].sub(wunits);
        _balances[to] = _balances[to].add(units);
        _supplyInBalances = _supplyInBalances.add(value);
        _supplyWhitelisted = _supplyWhitelisted.sub(value);
    } else if (isWhitelisted(to)) {
        _balances[from] = _balances[from].sub(units);
        _whitelistedBalances[to] = _whitelistedBalances[to].add(wunits);
        _supplyInBalances = _supplyInBalances.sub(value);
        _supplyWhitelisted = _supplyWhitelisted.add(value);
    } else {
        _balances[from] = _balances[from].sub(units);
        _balances[to] = _balances[to].add(units);
    }
    emit Transfer(from, to, value);
    return true;
}

function putToSheriffsVault(uint256 amount) external {
    address holder = msg.sender;
    require(!_whitelist[holder], "Milk: whitelisted holders cannot use Sheriff's Vault");
    _updateBalance(holder);
    uint256 unitsInBalances = amount.mul(_unitsPerTokenInBalances);
    uint256 unitsInSheriffsVault = amount.mul(_unitsPerTokenInSheriffsVault);
    _balances[holder] = _balances[holder].sub(unitsInBalances);
    _vaults[holder] = _vaults[holder].add(unitsInSheriffsVault);
    _supplyInBalances = _supplyInBalances.sub(amount);
    _supplyInSheriffsVault = _supplyInSheriffsVault.add(amount);
    emit SheriffsVaultDeposit(holder, amount);
}

function takeFromSheriffsVault(uint256 amount) external {
    address holder = msg.sender;
    require(!_whitelist[holder], "Milk: whitelisted holders cannot use Sheriff's Vault");
    _updateBalance(holder);
    uint256 unitsInBalances = amount.mul(_unitsPerTokenInBalances);
    uint256 unitsInSheriffsVault = amount.mul(_unitsPerTokenInSheriffsVault);
    _balances[holder] = _balances[holder].add(unitsInBalances);
    _vaults[holder] = _vaults[holder].sub(unitsInSheriffsVault);
    _supplyInBalances = _supplyInBalances.add(amount);
    _supplyInSheriffsVault = _supplyInSheriffsVault.sub(amount);
    emit SheriffsVaultWithdraw(holder, amount);
}

function getPeriod() public view override returns(uint256) {
    if (block.timestamp <= _startTime) {
        return 0;
    }
    return block.timestamp.sub(_startTime).div(PERIOD_LENGTH);
}

function getProductedAmount() public view returns(uint256) {
    uint256 period = getPeriod();
    uint256 reducings = period.div(REDUCING_PERIODS);
    uint256 productionAmount = INITIAL_PRODUCTION;
    uint256 productedAmount = 0;
    for (uint256 i = 0; i < reducings; i++) {
        productedAmount = productedAmount.add(productionAmount.mul(REDUCING_PERIODS));
        productionAmount = productionAmount.sub(productionAmount.div(REDUCING_FACTOR));
    }
    productedAmount = productedAmount.add(productionAmount.mul(period.sub(reducings.mul(REDUCING_PERIODS))));
    productedAmount = productedAmount.add(productionAmount.mul(getPeriodPart()).div(10 ** 18));
    return productedAmount;
}

function sheriffsPotDistribution() external override onlyController returns(uint256 amount) {
    amount = _supplyInSheriffsPot;
    if (amount > 0 && _supplyInBalances > 0) {
        uint256 maxBalancesSupplyDelta = _maxBalancesSupply.mul(amount).div(_supplyInBalances);
        _supplyInBalances = _supplyInBalances.add(amount);
        _supplyInSheriffsPot = 0;
        _maxBalancesSupply = _maxBalancesSupply.add(maxBalancesSupplyDelta);
        _unitsPerTokenInBalances = TOTAL_UNITS.div(_maxBalancesSupply);
    }
    emit SheriffsPotDistribution(amount);
}

function getPeriodPart() public view returns(uint256) {
    if (block.timestamp <= _startTime) {
        return 0;
    }
    uint256 durationFromPeriodStart = block.timestamp
        .sub(_startTime.add(getPeriod().mul(PERIOD_LENGTH)));
    return durationFromPeriodStart.mul(10 ** 18).div(PERIOD_LENGTH);
}

function addToWhitelist(address holder) external onlyOwner {
    require(address(_stableCow) != address(0), "Milk: StableV2 contract staking COW tokens is not set up");
    require(!_whitelist[holder], "Milk: already whitelisted");
    require(_stableCow.power(holder) == 0, "Milk: unable to whitelist COW tokens staker");
    _whitelist[holder] = true;
    uint256 tokens = _balances[holder].div(_unitsPerTokenInBalances);
    if (tokens > 0) {
        _whitelistedBalances[holder] = tokens.mul(_unitsPerTokenWhitelisted);
        _balances[holder] = 0;
        _supplyInBalances = _supplyInBalances.sub(tokens);
        _supplyWhitelisted = _supplyWhitelisted.add(tokens);
    }
    emit AddedToWhitelist(holder);
}

function getProductionAmount() public view returns(uint256) {
    uint256 reducings = getPeriod().div(REDUCING_PERIODS);
    uint256 production = INITIAL_PRODUCTION;
    for (uint256 i = 0; i < reducings; i++) {
        production = production.sub(production.div(REDUCING_FACTOR));
    }
    return production;
}

function transfer(address _to, uint _value, bytes _data) public {
    require(_value > 0);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = subSafe(balances[msg.sender], _value);
    balances[_to] = addSafe(balances[_to], _value);
    Transfer(msg.sender, _to, _value, _data);
}

function getReleaseAmount() internal returns(uint256 _actualRelease) {
    uint256 _amountToRelease;
    if (now >= firstAnnual &&
        now < secondAnnual &&
        firstAnnualReleasedAmount > 0) {
        _amountToRelease = firstAnnualReleasedAmount;
        firstAnnualReleasedAmount = 0;
    } else if (now >= secondAnnual &&
        now < thirdAnnual &&
        secondAnnualReleasedAmount > 0) {
        _amountToRelease = secondAnnualReleasedAmount;
        secondAnnualReleasedAmount = 0;
    } else if (now >= thirdAnnual &&
        thirdAnnualReleasedAmount > 0) {
        _amountToRelease = thirdAnnualReleasedAmount;
        thirdAnnualReleasedAmount = 0;
    } else {
        _amountToRelease = 0;
    }
    return _amountToRelease;
}

function() public payable {
    require(now >= createTime && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 2480;
    } else {
        tokens = msg.value * 2000;
    }
    require(tokens <= balances[owner]);
    balances[msg.sender] = addSafe(balances[msg.sender], tokens);
    balances[owner] = subSafe(balances[owner], tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function validPurchase() internal view {
    require(msg.value != 0);
    require(remainingTokens() > 0, "contract doesn't have tokens");
    require(now >= startTime && now <= endTime);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    require(from == owner() || to == owner() || launched, "Not launched yet");
    if (block.number == launchedAt || block.number == launchedAt + 1) {
        if (from == uniswapPair && from != owner() && to != owner()) {
            to = burnAddress;
        }
    }
    if (limit == true && !_isExcludedFromFee[from] && !_isExcludedFromFee[to] && to != burnAddress) {
        if (to != uniswapPair && from == uniswapPair) {
            require(((balanceOf(to).add(amount)) <= 200000000000 * 10 ** 4 * 10 ** 9));
        }
        require(amount <= 100000000000 * 10 ** 4 * 10 ** 9, 'Transfer amount must be less');
    }
    if (from != owner() && to != owner())
        require(amount <= _maxTxAmount);
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinTokenBalance = contractTokenBalance >= minTokensBeforeSwap;
    if (
        overMinTokenBalance &&
        !inSwapAndLiquify &&
        from != uniswapPair &&
        swapAndLiquifyEnabled
    ) {
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function bid(uint _tokenId) external payable whenNotPaused {
    require(isNotContract(msg.sender));
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(auction.startedAt > 0);
    uint price = _calcCurrentPrice(auction);
    require(msg.value >= price);
    address seller = auction.seller;
    require(_owns(this, _tokenId));
    delete tokenIdToAuction[_tokenId];
    if (price > 0) {
        uint auctioneerCut = price * masterCut / 10000;
        uint sellerProceeds = price - auctioneerCut;
        require(sellerProceeds <= price);
        seller.transfer(sellerProceeds);
    }
    uint bidExcess = msg.value - price;
    if (bidExcess >= 1 finney) {
        msg.sender.transfer(bidExcess);
    }
    emit AuctionSuccessful(_tokenId, price, msg.sender);
    _transItem(this, msg.sender, _tokenId);
}

function getAuctionData(uint _tokenId) external view returns(
    address seller,
    uint startingPrice,
    uint endingPrice,
    uint duration,
    uint startedAt,
    uint currentPrice
) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(auction.startedAt > 0);
    seller = auction.seller;
    startingPrice = auction.startingPrice;
    endingPrice = auction.endingPrice;
    duration = auction.duration;
    startedAt = auction.startedAt;
    currentPrice = _calcCurrentPrice(auction);
}

function transferOnError(address _to, uint _tokenId) external onlyCOO {
    require(_owns(this, _tokenId));
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(auction.startedAt == 0);
    _transItem(this, _to, _tokenId);
}

function _calcCurrentPrice(Auction storage _auction)
internal
view
returns(uint outPrice) {
    int256 duration = _auction.duration;
    int256 price0 = _auction.startingPrice;
    int256 price2 = _auction.endingPrice;
    require(duration > 0);
    int256 secondsPassed = int256(now) - int256(_auction.startedAt);
    require(secondsPassed >= 0);
    if (secondsPassed < _auction.duration) {
        int256 priceChanged = (price2 - price0) * secondsPassed / duration;
        int256 currentPrice = price0 + priceChanged;
        outPrice = uint(currentPrice);
    } else {
        outPrice = _auction.endingPrice;
    }
}

function setRabbitData(
    uint _tokenId,
    uint32 _explosive,
    uint32 _endurance,
    uint32 _nimble,
    uint _taskId,
    uint8 v,
    bytes32 r,
    bytes32 s
) external {
    require(usedSignId[_taskId] == 0);
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(auction.startedAt == 0);
    uint[5] memory arr = [_tokenId, _explosive, _endurance, _nimble, _taskId];
    string memory text = uint5ToStr(arr);
    address signer = verify(text, v, r, s);
    require(signer == cooAddress);
    RabbitData storage rdata = rabbits[_tokenId];
    rdata.explosive = _explosive;
    rdata.endurance = _endurance;
    rdata.nimble = _nimble;
    rabbits[_tokenId] = rdata;
    usedSignId[_taskId] = 1;
    emit UpdateComplete(msg.sender, _tokenId);
}

function cancelAuction(uint _tokenId) external whenNotPaused {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(auction.startedAt > 0);
    address seller = auction.seller;
    require(msg.sender == seller);
    _cancelAuction(_tokenId);
}

function _addAuction(uint _tokenId, Auction _auction) internal {
    require(_auction.duration >= 1 minutes);
    tokenIdToAuction[_tokenId] = _auction;
    RabbitData storage rdata = rabbits[_tokenId];
    emit AuctionCreated(
        uint(_tokenId),
        uint(_auction.startingPrice),
        uint(_auction.endingPrice),
        uint(_auction.duration),
        uint(_auction.startedAt),
        uint32(rdata.explosive),
        uint32(rdata.endurance),
        uint32(rdata.nimble),
        uint32(rdata.star)
    );
}

function tokensOfOwner(address _owner) external view returns(uint[] ownerTokens) {
    uint tokenCount = balanceOf(_owner);
    if (tokenCount == 0) {
        return new uint[](0);
    } else {
        uint[] memory result = new uint[](tokenCount);
        uint totalCats = totalSupply();
        uint resultIndex = 0;
        uint rabbitId;
        for (rabbitId = 1; rabbitId <= totalCats; rabbitId++) {
            if (rabbitToOwner[rabbitId] == _owner) {
                result[resultIndex] = rabbitId;
                resultIndex++;
            }
        }
        return result;
    }
}

function safeWithdrawal() public {
    if (beneficiary == msg.sender) {
        if (beneficiary.send(amountRaised)) {
            FundTransfer(beneficiary, amountRaised, false);
        } else {
        }
    }
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = pooIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = pooIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 62), 100));
    ceoAddress.transfer(uint256(SafeMath.div(SafeMath.mul(sellingPrice, 8), 100)));
    pooIndexToPrice[_tokenId] = uint256(SafeMath.mul(sellingPrice, 2));
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment);
    }
    _checkToiletFlush(false, _tokenId);
    lastPurchaseTime = now;
    ToiletPotChange();
}

function tryFlush() public payable {
    require(msg.value >= minFlushPrice);
    ceoAddress.transfer(uint256(SafeMath.div(SafeMath.mul(msg.value, 10), 100)));
    _checkToiletFlush(true, 0);
    lastPurchaseTime = now;
    ToiletPotChange();
}

function _checkToiletFlush(bool _manualFlush, uint256 _purchasedTokenId) private {
    uint256 winningChance = 25;
    if (_manualFlush) {
        winningChance = 50;
    } else if (_purchasedTokenId == goldenPooId) {
        winningChance = uint256(SafeMath.div(SafeMath.mul(winningChance, 90), 100));
    }
    if (_increaseWinPotChance()) {
        winningChance = uint256(SafeMath.div(winningChance, 3));
    }
    if (ownershipTokenCount[msg.sender] == 0) {
        winningChance = uint256(SafeMath.mul(winningChance, 2));
    }
    uint256 flushPooIndex = rand(winningChance);
    if ((flushPooIndex < 6) && (flushPooIndex != goldenPooId) && (msg.sender != pooIndexToOwner[flushPooIndex])) {
        lastFlusher = msg.sender;
        flushedTokenId = flushPooIndex;
        _transfer(pooIndexToOwner[flushPooIndex], address(this), flushPooIndex);
        pooIndexToPrice[flushPooIndex] = startingPrice;
        uint256 reward = uint256(SafeMath.div(SafeMath.mul(this.balance, 95), 100));
        lastPotSize = reward;
        msg.sender.transfer(reward); 
        goldenPooId = rand(6); 
        roundCounter += 1; 
    }
}

function _increaseWinPotChance() constant private returns(bool) {
    if (now >= lastPurchaseTime + 120 minutes) {
        return true;
    }
    return false;
}

function confirm(uint256 index, address destination, uint256 value) external onlyOwner {
    requireMatchingOpenProposal(index, destination, value);
    require(proposals[index].time < now, "too early");
    proposals[index].closed = true;
    emit TransferConfirmed(index, destination, value, proposals[index].notes);
    require(token.transfer(destination, value));
}

function propose(address destination, uint256 value, string calldata notes) external onlyOwner {
    uint256 delayUntil = now + delay;
    require(delayUntil >= now, "delay overflowed");
    proposals[proposalsLength] = TransferProposal({
        destination: destination,
        value: value,
        time: delayUntil,
        notes: notes,
        closed: false
    });
    proposalsLength++;
    emit TransferProposed(proposalsLength - 1, destination, value, delayUntil, notes);
}

function requireMatchingOpenProposal(uint256 index, address destination, uint256 value) private view {
    require(index < proposalsLength, "index too high, or transfer voided");
    require(!proposals[index].closed, "transfer already closed");
    require(proposals[index].destination == destination, "destination mismatched");
    require(proposals[index].value == value, "value mismatched");
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFeeraw = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _tokenFee = SafeMath.mul(_tokenFeeraw, 3);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function airdrop(address to, uint256 animalId) external contractIsActive {
    require(now <= airdropEndTimestamp, "airdrop ended");
    donateDnaFromContract(to, animalId, AIRDROP_EFFECTIVENESS);
    emit NewAirdrop(to, animalId);
}

function ico() public payable {
    require(now >= icoBegintime && now <= icoEndtime);
    uint256 tokenValue = (msg.value * icoRatio * 10 ** uint256(decimals)) / (1 ether / 1 wei);
    if (tokenValue == 0 || balanceOf[icoSender] < tokenValue) {
        revert();
    }
    _transfer(icoSender, msg.sender, tokenValue);
    ICO(msg.sender, msg.value, tokenValue);
}

function airdrop() public payable {
    require(now >= airBegintime && now <= airEndtime);
    require(msg.value == 0);
    if (airLimitCount > 0 && airCountOf[msg.sender] >= airLimitCount) {
        revert();
    }
    _transfer(airSender, msg.sender, airAmount);
    airCountOf[msg.sender] += 1;
    Airdrop(msg.sender, airCountOf[msg.sender], airAmount);
}

function withdraw() public {
    uint256 balance = this.balance;
    icoHolder.transfer(balance);
    Withdraw(msg.sender, icoHolder, balance);
}

function supply(address asset, uint256 amount)
public
payable
nonReentrant
onlyCustomerWithKYC
returns(uint256) {
    if (paused) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(Error.CONTRACT_PAUSED, FailureInfo.SUPPLY_CONTRACT_PAUSED);
    }
    if (asset == wethAddress && amount != msg.value) {
        revertEtherToUser(msg.sender, msg.value);
        revert("ETHER_AMOUNT_MISMATCH_ERROR");
    }
    refreshAlkIndex(asset, msg.sender, true, true);
    Market storage market = markets[asset];
    Balance storage balance = supplyBalances[msg.sender][asset];
    SupplyLocalVars memory localResults; 
    Error err; 
    uint256 rateCalculationResultCode; 
    if (!market.isSupported) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            Error.MARKET_NOT_SUPPORTED,
            FailureInfo.SUPPLY_MARKET_NOT_SUPPORTED
        );
    }
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = checkTransferIn(asset, msg.sender, amount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.SUPPLY_TRANSFER_IN_NOT_POSSIBLE);
        }
    }
    (err, localResults.newSupplyIndex) = calculateInterestIndex(
        market.supplyIndex,
        market.supplyRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_SUPPLY_INDEX_CALCULATION_FAILED
        );
    }
    (err, localResults.userSupplyCurrent) = calculateBalance(
        balance.principal,
        balance.interestIndex,
        localResults.newSupplyIndex
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_ACCUMULATED_BALANCE_CALCULATION_FAILED
        );
    }
    (err, localResults.userSupplyUpdated) = add(
        localResults.userSupplyCurrent,
        amount
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_TOTAL_BALANCE_CALCULATION_FAILED
        );
    }
    (err, localResults.newTotalSupply) = addThenSub(
        market.totalSupply,
        localResults.userSupplyUpdated,
        balance.principal
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_TOTAL_SUPPLY_CALCULATION_FAILED
        );
    }
    localResults.currentCash = getCash(asset);
    (err, localResults.updatedCash) = add(localResults.currentCash, amount);
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(err, FailureInfo.SUPPLY_NEW_TOTAL_CASH_CALCULATION_FAILED);
    }
    (rateCalculationResultCode, localResults.newSupplyRateMantissa) = market
        .interestRateModel
        .getSupplyRate(asset, localResults.updatedCash, market.totalBorrows);
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.SUPPLY_NEW_SUPPLY_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    (err, localResults.newBorrowIndex) = calculateInterestIndex(
        market.borrowIndex,
        market.borrowRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_BORROW_INDEX_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newBorrowRateMantissa) = market
        .interestRateModel
        .getBorrowRate(asset, localResults.updatedCash, market.totalBorrows);
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.SUPPLY_NEW_BORROW_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    market.blockNumber = block.number;
    market.totalSupply = localResults.newTotalSupply;
    market.supplyRateMantissa = localResults.newSupplyRateMantissa;
    market.supplyIndex = localResults.newSupplyIndex;
    market.borrowRateMantissa = localResults.newBorrowRateMantissa;
    market.borrowIndex = localResults.newBorrowIndex;
    localResults.startingBalance = balance.principal; 
    balance.principal = localResults.userSupplyUpdated;
    balance.interestIndex = localResults.newSupplyIndex;
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = doTransferIn(asset, msg.sender, amount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.SUPPLY_TRANSFER_IN_FAILED);
        }
    } else {
        if (msg.value == amount) {
            uint256 supplyError = supplyEther(msg.value);
            if (supplyError != 0) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    Error.WETH_ADDRESS_NOT_SET_ERROR,
                    FailureInfo.WETH_ADDRESS_NOT_SET_ERROR
                );
            }
        } else {
            revertEtherToUser(msg.sender, msg.value);
            return
            fail(
                Error.ETHER_AMOUNT_MISMATCH_ERROR,
                FailureInfo.ETHER_AMOUNT_MISMATCH_ERROR
            );
        }
    }
    emit SupplyReceived(
        msg.sender,
        asset,
        amount,
        localResults.startingBalance,
        balance.principal
    );
    return uint256(Error.NO_ERROR); 
}

function repayBorrow(address asset, uint256 amount)
public
payable
nonReentrant
returns(uint256) {
    if (paused) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            Error.CONTRACT_PAUSED,
            FailureInfo.REPAY_BORROW_CONTRACT_PAUSED
        );
    }
    if (asset == wethAddress && amount != msg.value) {
        revertEtherToUser(msg.sender, msg.value);
        revert("ETHER_AMOUNT_MISMATCH_ERROR");
    }
    refreshAlkIndex(asset, msg.sender, false, true);
    PayBorrowLocalVars memory localResults;
    Market storage market = markets[asset];
    Balance storage borrowBalance = borrowBalances[msg.sender][asset];
    Error err;
    uint256 rateCalculationResultCode;
    (err, localResults.newBorrowIndex) = calculateInterestIndex(
        market.borrowIndex,
        market.borrowRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_BORROW_INDEX_CALCULATION_FAILED
        );
    }
    (err, localResults.userBorrowCurrent) = calculateBalance(
        borrowBalance.principal,
        borrowBalance.interestIndex,
        localResults.newBorrowIndex
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo
            .REPAY_BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED
        );
    }
    uint256 reimburseAmount;
    if (asset != wethAddress) {
        if (amount == uint256(-1)) {
            localResults.repayAmount = min(
                getBalanceOf(asset, msg.sender),
                localResults.userBorrowCurrent
            );
        } else {
            localResults.repayAmount = amount;
        }
    } else {
        if (amount > localResults.userBorrowCurrent) {
            localResults.repayAmount = localResults.userBorrowCurrent;
            (err, reimburseAmount) = sub(
                amount,
                localResults.userBorrowCurrent
            ); 
            if (err != Error.NO_ERROR) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    err,
                    FailureInfo
                    .REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
                );
            }
        } else {
            localResults.repayAmount = amount;
        }
    }
    (err, localResults.userBorrowUpdated) = sub(
        localResults.userBorrowCurrent,
        localResults.repayAmount
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo
            .REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
        );
    }
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = checkTransferIn(asset, msg.sender, localResults.repayAmount);
        if (err != Error.NO_ERROR) {
            return
            fail(
                err,
                FailureInfo.REPAY_BORROW_TRANSFER_IN_NOT_POSSIBLE
            );
        }
    }
    (err, localResults.newTotalBorrows) = addThenSub(
        market.totalBorrows,
        localResults.userBorrowUpdated,
        borrowBalance.principal
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_TOTAL_BORROW_CALCULATION_FAILED
        );
    }
    localResults.currentCash = getCash(asset);
    (err, localResults.updatedCash) = add(
        localResults.currentCash,
        localResults.repayAmount
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_TOTAL_CASH_CALCULATION_FAILED
        );
    }
    (err, localResults.newSupplyIndex) = calculateInterestIndex(
        market.supplyIndex,
        market.supplyRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_SUPPLY_INDEX_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newSupplyRateMantissa) = market
        .interestRateModel
        .getSupplyRate(
            asset,
            localResults.updatedCash,
            localResults.newTotalBorrows
        );
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.REPAY_BORROW_NEW_SUPPLY_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    (rateCalculationResultCode, localResults.newBorrowRateMantissa) = market
        .interestRateModel
        .getBorrowRate(
            asset,
            localResults.updatedCash,
            localResults.newTotalBorrows
        );
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.REPAY_BORROW_NEW_BORROW_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    market.blockNumber = block.number;
    market.totalBorrows = localResults.newTotalBorrows;
    market.supplyRateMantissa = localResults.newSupplyRateMantissa;
    market.supplyIndex = localResults.newSupplyIndex;
    market.borrowRateMantissa = localResults.newBorrowRateMantissa;
    market.borrowIndex = localResults.newBorrowIndex;
    localResults.startingBalance = borrowBalance.principal; 
    borrowBalance.principal = localResults.userBorrowUpdated;
    borrowBalance.interestIndex = localResults.newBorrowIndex;
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = doTransferIn(asset, msg.sender, localResults.repayAmount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.REPAY_BORROW_TRANSFER_IN_FAILED);
        }
    } else {
        if (msg.value == amount) {
            uint256 supplyError = supplyEther(localResults.repayAmount);
            if (reimburseAmount > 0) {
                revertEtherToUser(msg.sender, reimburseAmount);
            }
            if (supplyError != 0) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    Error.WETH_ADDRESS_NOT_SET_ERROR,
                    FailureInfo.WETH_ADDRESS_NOT_SET_ERROR
                );
            }
        } else {
            revertEtherToUser(msg.sender, msg.value);
            return
            fail(
                Error.ETHER_AMOUNT_MISMATCH_ERROR,
                FailureInfo.ETHER_AMOUNT_MISMATCH_ERROR
            );
        }
    }
    supplyOriginationFeeAsAdmin(
        asset,
        msg.sender,
        localResults.repayAmount,
        market.supplyIndex
    );
    emit BorrowRepaid(
        msg.sender,
        asset,
        localResults.repayAmount,
        localResults.startingBalance,
        borrowBalance.principal
    );
    return uint256(Error.NO_ERROR); 
}

function liquidateBorrow(
    address targetAccount,
    address assetBorrow,
    address assetCollateral,
    uint256 requestedAmountClose
) public payable returns(uint256) {
    if (paused) {
        return
        fail(
            Error.CONTRACT_PAUSED,
            FailureInfo.LIQUIDATE_CONTRACT_PAUSED
        );
    }
    if (assetBorrow == wethAddress && requestedAmountClose != msg.value) {
        revertEtherToUser(msg.sender, msg.value);
        revert("ETHER_AMOUNT_MISMATCH_ERROR");
    }
    require(liquidators[msg.sender], "LIQUIDATOR_CHECK_FAILED");
    refreshAlkIndex(assetCollateral, targetAccount, true, true);
    refreshAlkIndex(assetCollateral, msg.sender, true, true);
    refreshAlkIndex(assetBorrow, targetAccount, false, true);
    LiquidateLocalVars memory localResults;
    localResults.targetAccount = targetAccount;
    localResults.assetBorrow = assetBorrow;
    localResults.liquidator = msg.sender;
    localResults.assetCollateral = assetCollateral;
    Market storage borrowMarket = markets[assetBorrow];
    Market storage collateralMarket = markets[assetCollateral];
    Balance storage borrowBalance_TargeUnderwaterAsset = borrowBalances[
        targetAccount
    ][assetBorrow];
    Balance storage supplyBalance_TargetCollateralAsset = supplyBalances[
        targetAccount
    ][assetCollateral];
    Balance storage supplyBalance_LiquidatorCollateralAsset
        = supplyBalances[localResults.liquidator][assetCollateral];
    uint256 rateCalculationResultCode; 
    Error err; 
    (err, localResults.collateralPrice) = fetchAssetPrice(assetCollateral);
    if (err != Error.NO_ERROR) {
        return fail(err, FailureInfo.LIQUIDATE_FETCH_ASSET_PRICE_FAILED);
    }
    (err, localResults.underwaterAssetPrice) = fetchAssetPrice(assetBorrow);
    revertIfError(err);
    (
        err,
        localResults.newBorrowIndex_UnderwaterAsset
    ) = calculateInterestIndex(
        borrowMarket.borrowIndex,
        borrowMarket.borrowRateMantissa,
        borrowMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_BORROW_INDEX_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    (
        err,
        localResults.currentBorrowBalance_TargetUnderwaterAsset
    ) = calculateBalance(
        borrowBalance_TargeUnderwaterAsset.principal,
        borrowBalance_TargeUnderwaterAsset.interestIndex,
        localResults.newBorrowIndex_UnderwaterAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_ACCUMULATED_BORROW_BALANCE_CALCULATION_FAILED
        );
    }
    (
        err,
        localResults.newSupplyIndex_CollateralAsset
    ) = calculateInterestIndex(
        collateralMarket.supplyIndex,
        collateralMarket.supplyRateMantissa,
        collateralMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_SUPPLY_INDEX_CALCULATION_FAILED_COLLATERAL_ASSET
        );
    }
    (
        err,
        localResults.currentSupplyBalance_TargetCollateralAsset
    ) = calculateBalance(
        supplyBalance_TargetCollateralAsset.principal,
        supplyBalance_TargetCollateralAsset.interestIndex,
        localResults.newSupplyIndex_CollateralAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_ACCUMULATED_SUPPLY_BALANCE_CALCULATION_FAILED_BORROWER_COLLATERAL_ASSET
        );
    }
    (
        err,
        localResults.currentSupplyBalance_LiquidatorCollateralAsset
    ) = calculateBalance(
        supplyBalance_LiquidatorCollateralAsset.principal,
        supplyBalance_LiquidatorCollateralAsset.interestIndex,
        localResults.newSupplyIndex_CollateralAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_ACCUMULATED_SUPPLY_BALANCE_CALCULATION_FAILED_LIQUIDATOR_COLLATERAL_ASSET
        );
    }
    (err, localResults.newTotalSupply_ProtocolCollateralAsset) = addThenSub(
        collateralMarket.totalSupply,
        localResults.currentSupplyBalance_TargetCollateralAsset,
        supplyBalance_TargetCollateralAsset.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_SUPPLY_BALANCE_CALCULATION_FAILED_BORROWER_COLLATERAL_ASSET
        );
    }
    (err, localResults.newTotalSupply_ProtocolCollateralAsset) = addThenSub(
        localResults.newTotalSupply_ProtocolCollateralAsset,
        localResults.currentSupplyBalance_LiquidatorCollateralAsset,
        supplyBalance_LiquidatorCollateralAsset.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_SUPPLY_BALANCE_CALCULATION_FAILED_LIQUIDATOR_COLLATERAL_ASSET
        );
    }
    (
        err,
        localResults.discountedBorrowDenominatedCollateral
    ) = calculateDiscountedBorrowDenominatedCollateral(
        localResults.underwaterAssetPrice,
        localResults.collateralPrice,
        localResults.currentSupplyBalance_TargetCollateralAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_BORROW_DENOMINATED_COLLATERAL_CALCULATION_FAILED
        );
    }
    if (borrowMarket.isSupported) {
        (
            err,
            localResults.discountedRepayToEvenAmount
        ) = calculateDiscountedRepayToEvenAmount(
            targetAccount,
            localResults.underwaterAssetPrice,
            assetBorrow
        );
        if (err != Error.NO_ERROR) {
            return
            fail(
                err,
                FailureInfo
                .LIQUIDATE_DISCOUNTED_REPAY_TO_EVEN_AMOUNT_CALCULATION_FAILED
            );
        }
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset = min(
            localResults.currentBorrowBalance_TargetUnderwaterAsset,
            localResults.discountedBorrowDenominatedCollateral
        );
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset = min(
            localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset,
            localResults.discountedRepayToEvenAmount
        );
    } else {
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset = min(
            localResults.currentBorrowBalance_TargetUnderwaterAsset,
            localResults.discountedBorrowDenominatedCollateral
        );
    }
    if (assetBorrow != wethAddress) {
        if (requestedAmountClose == uint256(-1)) {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = localResults
                .maxCloseableBorrowAmount_TargetUnderwaterAsset;
        } else {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = requestedAmountClose;
        }
    } else {
        if (
            requestedAmountClose >
            localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset
        ) {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = localResults
                .maxCloseableBorrowAmount_TargetUnderwaterAsset;
            (err, localResults.reimburseAmount) = sub(
                requestedAmountClose,
                localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset
            ); 
            if (err != Error.NO_ERROR) {
                return
                fail(
                    err,
                    FailureInfo
                    .REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
                );
            }
        } else {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = requestedAmountClose;
        }
    }
    if (
        localResults.closeBorrowAmount_TargetUnderwaterAsset >
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset
    ) {
        return
        fail(
            Error.INVALID_CLOSE_AMOUNT_REQUESTED,
            FailureInfo.LIQUIDATE_CLOSE_AMOUNT_TOO_HIGH
        );
    }
    (
        err,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    ) = calculateAmountSeize(
        localResults.underwaterAssetPrice,
        localResults.collateralPrice,
        localResults.closeBorrowAmount_TargetUnderwaterAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.LIQUIDATE_AMOUNT_SEIZE_CALCULATION_FAILED
        );
    }
    if (assetBorrow != wethAddress) {
        err = checkTransferIn(
            assetBorrow,
            localResults.liquidator,
            localResults.closeBorrowAmount_TargetUnderwaterAsset
        );
        if (err != Error.NO_ERROR) {
            return
            fail(err, FailureInfo.LIQUIDATE_TRANSFER_IN_NOT_POSSIBLE);
        }
    }
    (err, localResults.updatedBorrowBalance_TargetUnderwaterAsset) = sub(
        localResults.currentBorrowBalance_TargetUnderwaterAsset,
        localResults.closeBorrowAmount_TargetUnderwaterAsset
    );
    revertIfError(err);
    (
        err,
        localResults.newTotalBorrows_ProtocolUnderwaterAsset
    ) = addThenSub(
        borrowMarket.totalBorrows,
        localResults.updatedBorrowBalance_TargetUnderwaterAsset,
        borrowBalance_TargeUnderwaterAsset.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_BORROW_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    localResults.currentCash_ProtocolUnderwaterAsset = getCash(assetBorrow);
    (err, localResults.updatedCash_ProtocolUnderwaterAsset) = add(
        localResults.currentCash_ProtocolUnderwaterAsset,
        localResults.closeBorrowAmount_TargetUnderwaterAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_CASH_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    (
        err,
        localResults.newSupplyIndex_UnderwaterAsset
    ) = calculateInterestIndex(
        borrowMarket.supplyIndex,
        borrowMarket.supplyRateMantissa,
        borrowMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_SUPPLY_INDEX_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    (
        rateCalculationResultCode,
        localResults.newSupplyRateMantissa_ProtocolUnderwaterAsset
    ) = borrowMarket.interestRateModel.getSupplyRate(
        assetBorrow,
        localResults.updatedCash_ProtocolUnderwaterAsset,
        localResults.newTotalBorrows_ProtocolUnderwaterAsset
    );
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo
            .LIQUIDATE_NEW_SUPPLY_RATE_CALCULATION_FAILED_BORROWED_ASSET,
            rateCalculationResultCode
        );
    }
    (
        rateCalculationResultCode,
        localResults.newBorrowRateMantissa_ProtocolUnderwaterAsset
    ) = borrowMarket.interestRateModel.getBorrowRate(
        assetBorrow,
        localResults.updatedCash_ProtocolUnderwaterAsset,
        localResults.newTotalBorrows_ProtocolUnderwaterAsset
    );
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo
            .LIQUIDATE_NEW_BORROW_RATE_CALCULATION_FAILED_BORROWED_ASSET,
            rateCalculationResultCode
        );
    }
    (
        err,
        localResults.newBorrowIndex_CollateralAsset
    ) = calculateInterestIndex(
        collateralMarket.borrowIndex,
        collateralMarket.borrowRateMantissa,
        collateralMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_BORROW_INDEX_CALCULATION_FAILED_COLLATERAL_ASSET
        );
    }
    (err, localResults.updatedSupplyBalance_TargetCollateralAsset) = sub(
        localResults.currentSupplyBalance_TargetCollateralAsset,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    );
    revertIfError(err);
    (
        err,
        localResults.updatedSupplyBalance_LiquidatorCollateralAsset
    ) = add(
        localResults.currentSupplyBalance_LiquidatorCollateralAsset,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    );
    revertIfError(err);
    borrowMarket.blockNumber = block.number;
    borrowMarket.totalBorrows = localResults
        .newTotalBorrows_ProtocolUnderwaterAsset;
    borrowMarket.supplyRateMantissa = localResults
        .newSupplyRateMantissa_ProtocolUnderwaterAsset;
    borrowMarket.supplyIndex = localResults.newSupplyIndex_UnderwaterAsset;
    borrowMarket.borrowRateMantissa = localResults
        .newBorrowRateMantissa_ProtocolUnderwaterAsset;
    borrowMarket.borrowIndex = localResults.newBorrowIndex_UnderwaterAsset;
    collateralMarket.blockNumber = block.number;
    collateralMarket.totalSupply = localResults
        .newTotalSupply_ProtocolCollateralAsset;
    collateralMarket.supplyIndex = localResults
        .newSupplyIndex_CollateralAsset;
    collateralMarket.borrowIndex = localResults
        .newBorrowIndex_CollateralAsset;
    localResults
        .startingBorrowBalance_TargetUnderwaterAsset = borrowBalance_TargeUnderwaterAsset
        .principal; 
    borrowBalance_TargeUnderwaterAsset.principal = localResults
        .updatedBorrowBalance_TargetUnderwaterAsset;
    borrowBalance_TargeUnderwaterAsset.interestIndex = localResults
        .newBorrowIndex_UnderwaterAsset;
    localResults
        .startingSupplyBalance_TargetCollateralAsset = supplyBalance_TargetCollateralAsset
        .principal; 
    supplyBalance_TargetCollateralAsset.principal = localResults
        .updatedSupplyBalance_TargetCollateralAsset;
    supplyBalance_TargetCollateralAsset.interestIndex = localResults
        .newSupplyIndex_CollateralAsset;
    localResults
        .startingSupplyBalance_LiquidatorCollateralAsset = supplyBalance_LiquidatorCollateralAsset
        .principal; 
    supplyBalance_LiquidatorCollateralAsset.principal = localResults
        .updatedSupplyBalance_LiquidatorCollateralAsset;
    supplyBalance_LiquidatorCollateralAsset.interestIndex = localResults
        .newSupplyIndex_CollateralAsset;
    if (assetBorrow != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = doTransferIn(
            assetBorrow,
            localResults.liquidator,
            localResults.closeBorrowAmount_TargetUnderwaterAsset
        );
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.LIQUIDATE_TRANSFER_IN_FAILED);
        }
    } else {
        if (msg.value == requestedAmountClose) {
            uint256 supplyError = supplyEther(
                localResults.closeBorrowAmount_TargetUnderwaterAsset
            );
            if (localResults.reimburseAmount > 0) {
                revertEtherToUser(
                    localResults.liquidator,
                    localResults.reimburseAmount
                );
            }
            if (supplyError != 0) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    Error.WETH_ADDRESS_NOT_SET_ERROR,
                    FailureInfo.WETH_ADDRESS_NOT_SET_ERROR
                );
            }
        } else {
            revertEtherToUser(msg.sender, msg.value);
            return
            fail(
                Error.ETHER_AMOUNT_MISMATCH_ERROR,
                FailureInfo.ETHER_AMOUNT_MISMATCH_ERROR
            );
        }
    }
    supplyOriginationFeeAsAdmin(
        assetBorrow,
        localResults.liquidator,
        localResults.closeBorrowAmount_TargetUnderwaterAsset,
        localResults.newSupplyIndex_UnderwaterAsset
    );
    emit BorrowLiquidated(
        localResults.targetAccount,
        localResults.assetBorrow,
        localResults.currentBorrowBalance_TargetUnderwaterAsset,
        localResults.closeBorrowAmount_TargetUnderwaterAsset,
        localResults.liquidator,
        localResults.assetCollateral,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    );
    return uint256(Error.NO_ERROR); 
}

