function invest(address addr) public payable returns(uint256) {
    if (msg.value < 1 ether) {
        msg.sender.transfer(msg.value);
        return 1;
    }
    if (balances[msg.sender] < msg.value * rate / 10) {
        msg.sender.transfer(msg.value);
        return 3;
    }
    uint i = user_index[msg.sender];
    if (i > 0) {
        i = i - 1;
    } else {
        users.push(UserInfo(msg.sender, 0, 0, 0, 0));
        user_index[msg.sender] = users.length;
        i = users.length - 1;
    }
    uint mbs = 3;
    if (users[i].amount > 30 ether) {
        mbs = 4;
    }
    if (users[i].amount > 60 ether) {
        mbs = 5;
    }
    if (users[i].amount * mbs > users[i].rewardall) {
        msg.sender.transfer(msg.value);
        return 4;
    }
    invests.push(InvestRecord(msg.sender, msg.value, now, 0));
    balances[msg.sender] -= msg.value * rate / 10;
    destoryTicketCount += msg.value * rate / 10;
    if (technology != 0) {
        technology.transfer(msg.value / 100 * 3);
    }
    address p = users[i].parent;
    if (p == 0) {
        if (addr == msg.sender) {
            addr = 0;
        }
        p = addr;
        users[i].parent = addr;
    }
    if (p != 0) {
        uint pi = user_index[p];
        if (pi > 0) {
            pi = pi - 1;
            uint r = msg.value / 10;
            uint bs = 3;
            if (users[pi].amount > 30 ether) {
                bs = 4;
            }
            if (users[pi].amount > 60 ether) {
                bs = 5;
            }
            uint max = users[pi].amount * bs;
            if (users[pi].rewardall + r > max) {
                users[pi].reward += max - users[pi].rewardall;
                users[pi].rewardall = max;
            } else {
                users[pi].reward += r;
                users[pi].rewardall += r;
            }
        }
    }
    users[i].amount += msg.value;
    investIncome += msg.value;
    if (endTime == 0 || endTime < now) {
        endTime = now;
    }
    uint tm = investIncome * 3 * 3600;
    tm = tm / 1 ether;
    endTime += tm;
    if (endTime > now + 48 hours) {
        endTime = now + 48 hours;
    }
    return 0;
}

function withdraw() public payable returns(bool) {
    uint i = user_index[msg.sender];
    if (i > 0) {
        i = i - 1;
        if (users[i].reward > 0) {
            uint m = users[i].reward <= (address)(this).balance ? users[i].reward : (address)(this).balance;
            users[i].addr.transfer(m);
            users[i].reward -= m;
            return true;
        }
    }
    return false;
}

function taskRewardVote(bytes32 _taskId, uint256 _reward) external returns(bool) {
    DIDToken didToken = DIDToken(DIDTokenAddress);
    uint256 balance = didToken.getAddressBalance(msg.sender);
    Distense distense = Distense(DistenseAddress);
    Task storage task = tasks[_taskId];
    require(_reward >= 0);
    require(task.reward != (_reward * 1 ether));
    require(task.rewardStatus != RewardStatus.DETERMINED);
    require(!task.rewardVotes[msg.sender]);
    require(balance > distense.getParameterValueByTitle(distense.numDIDRequiredToTaskRewardVoteParameterTitle()));
    require((_reward * 1 ether) <= distense.getParameterValueByTitle(distense.maxRewardParameterTitle()));
    task.rewardVotes[msg.sender] = true;
    uint256 pctDIDOwned = didToken.pctDIDOwned(msg.sender);
    task.pctDIDVoted = task.pctDIDVoted + pctDIDOwned;
    uint256 votingPowerLimit = distense.getParameterValueByTitle(distense.votingPowerLimitParameterTitle());
    uint256 limitedVotingPower = pctDIDOwned > votingPowerLimit ? votingPowerLimit : pctDIDOwned;
    uint256 difference;
    uint256 update;
    if ((_reward * 1 ether) > task.reward) {
        difference = SafeMath.sub((_reward * 1 ether), task.reward);
        update = (limitedVotingPower * difference) / (1 ether * 100);
        task.reward += update;
    } else {
        difference = SafeMath.sub(task.reward, (_reward * 1 ether));
        update = (limitedVotingPower * difference) / (1 ether * 100);
        task.reward -= update;
    }
    task.numVotes++;
    uint256 pctDIDVotedThreshold = distense.getParameterValueByTitle(
        distense.pctDIDToDetermineTaskRewardParameterTitle()
    );
    uint256 minNumVoters = distense.getParameterValueByTitle(
        distense.minNumberOfTaskRewardVotersParameterTitle()
    );
    if (task.pctDIDVoted > pctDIDVotedThreshold || task.numVotes > SafeMath.div(minNumVoters, 1 ether)) {
        emit LogTaskRewardDetermined(_taskId, task.reward);
        task.rewardStatus = RewardStatus.DETERMINED;
    }
    return true;
}

function addTask(bytes32 _taskId, string _title) external hasEnoughDIDToAddTask returns
    (bool) {
        bytes32 titleBytes32 = keccak256(abi.encodePacked(_title));
        require(!tasksTitles[titleBytes32], "Task title already exists");
        Distense distense = Distense(DistenseAddress);
        tasks[_taskId].createdBy = msg.sender;
        tasks[_taskId].title = _title;
        tasks[_taskId].reward = distense.getParameterValueByTitle(distense.defaultRewardParameterTitle());
        tasks[_taskId].rewardStatus = RewardStatus.TENTATIVE;
        taskIds.push(_taskId);
        tasksTitles[titleBytes32] = true;
        tasks[_taskId].taskIdsIndex = taskIds.length - 1;
        emit LogAddTask(_taskId, _title);
        return true;
    }

function() public payable {
    if (IsDistribRunning) {
        uint256 _amount;
        if (((_CurrentDistribPublicSupply + _amount) > _MaxDistribPublicSupply) && _MaxDistribPublicSupply > 0) revert();
        if (!_DistribFundsReceiverAddress.send(msg.value)) revert();
        if (Claimed[msg.sender] == false) {
            _amount = _FreeGWT * 1e18;
            _CurrentDistribPublicSupply += _amount;
            balances[msg.sender] += _amount;
            _totalSupply += _amount;
            Transfer(this, msg.sender, _amount);
            Claimed[msg.sender] = true;
        }
        if (msg.value >= 9e15) {
            _amount = msg.value * _ExtraTokensPerETHSended * 4;
        } else {
            if (msg.value >= 6e15) {
                _amount = msg.value * _ExtraTokensPerETHSended * 3;
            } else {
                if (msg.value >= 3e15) {
                    _amount = msg.value * _ExtraTokensPerETHSended * 2;
                } else {
                    _amount = msg.value * _ExtraTokensPerETHSended;
                }
            }
        }
        _CurrentDistribPublicSupply += _amount;
        balances[msg.sender] += _amount;
        _totalSupply += _amount;
        Transfer(this, msg.sender, _amount);
    } else {
        revert();
    }
}

function approveAndCallViaSignature(
    address from,
    address spender,
    uint256 value,
    bytes extraData,
    uint256 fee,
    address feeRecipient,
    uint256 deadline,
    uint256 sigId,
    bytes sig,
    sigStandard sigStd
) external returns(bool) {
    requireSignature(
        keccak256(address(this), from, spender, value, extraData, fee, feeRecipient, deadline, sigId),
        from, deadline, sigId, sig, sigStd, sigDestination.approveAndCall
    );
    allowance[from][spender] = value;
    emit Approval(from, spender, value);
    tokenRecipient(spender).receiveApproval(from, value, this, extraData);
    internalTransfer(from, feeRecipient, fee);
    return true;
}

function requireSignature(
    bytes32 data,
    address signer,
    uint256 deadline,
    uint256 sigId,
    bytes sig,
    sigStandard sigStd,
    sigDestination sigDest
) internal {
    bytes32 r;
    bytes32 s;
    uint8 v;
    assembly { 
        r: = mload(add(sig, 32))
        s: = mload(add(sig, 64))
        v: = byte(0, mload(add(sig, 96)))
    }
    if (v < 27)
        v += 27;
    require(block.timestamp <= deadline && !usedSigIds[signer][sigId]); 
    if (sigStd == sigStandard.typed) { 
        require(
            signer == ecrecover(
                keccak256(
                    sigDest == sigDestination.transfer ?
                    sigDestinationTransfer :
                    sigDest == sigDestination.approve ?
                    sigDestinationApprove :
                    sigDest == sigDestination.approveAndCall ?
                    sigDestinationApproveAndCall :
                    sigDestinationTransferFrom,
                    data
                ),
                v, r, s
            )
        );
    } else if (sigStd == sigStandard.personal) { 
        require(
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "32", data), v, r, s) 
            ||
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "\x20", data), v, r, s) 
        );
    } else { 
        require(
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "64", hexToString(data)), v, r, s) 
            ||
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "\x40", hexToString(data)), v, r, s) 
        );
    }
    usedSigIds[signer][sigId] = true;
}

function buyTokens(address _buyer) public payable {
    require(buyAllowed);
    require(msg.value >= tokenPrice);
    require(_buyer != owner);
    uint256 wei_value = msg.value;
    uint256 tokens = wei_value / tokenPrice;
    tokens = tokens;
    balances[owner] = safeSub(balances[owner], tokens);
    balances[_buyer] = safeAdd(balances[_buyer], tokens);
    owner.transfer(this.balance);
    Buy(_buyer, msg.value, tokens);
}

function newPeriod(uint256 _ownerCut) public onlyOwner {
    require(now >= epoch + 28 days);
    require(_ownerCut <= 10000);
    uint256 unclaimedDividend = dividendPool;
    uint256 ownerRake = (this.balance - unclaimedDividend) * ownerCut / 10000;
    dividendPool = this.balance - unclaimedDividend - ownerRake;
    uint64 existingUsers = numUsers;
    if (existingUsers == 0) {
        dividend = 0;
    } else {
        dividend = dividendPool / existingUsers;
    }
    numUsers = numUsers.add(newUsers);
    newUsers = 0;
    currentPeriod++;
    epoch = now;
    ownerCut = _ownerCut;
    msg.sender.transfer(ownerRake + unclaimedDividend);
    PeriodEnd(currentPeriod - 1, this.balance, existingUsers);
}

function withdraw() public {
    require(users[msg.sender].canWithdrawPeriod != 0);
    require(users[msg.sender].canWithdrawPeriod < currentPeriod);
    users[msg.sender].canWithdrawPeriod = currentPeriod;
    dividendPool -= dividend;
    msg.sender.transfer(dividend);
    Withdrawal(msg.sender, currentPeriod - 1, dividend);
}

function _finishSpin(address target)
private returns(uint) {
    playerSpin memory spin = playerSpins[target];
    require(spin.tokenValue > 0); 
    require(spin.blockn != block.number);
    uint profit = 0;
    uint category = 0;
    uint result;
