function buyTokens(address _recipient, uint256 _value) internal nonZero returns(bool success) {
    uint256 boughtTokens = calculateTokens(_value);
    require(boughtTokens != 0);
    boughtTokens = boughtTokens * (10 ** decimals);
    if (balanceOf(_recipient) == 0) {
        investorCount++;
    }
    if (isCrowdSaleStatePreSale()) {
        transferTokens(_recipient, boughtTokens);
        vault.deposit.value(_value)(_recipient);
        preSaleRaised = preSaleRaised.add(_value);
        return true;
    } else if (isCrowdSaleStateICO()) {
        transferTokens(_recipient, boughtTokens);
        vault.deposit.value(_value)(_recipient);
        icoRaised = icoRaised.add(_value);
        return true;
    }
}

function transferFrom(address _from, address _to, uint256 _tokens_in_cents) public returns(bool success) {
    require(_tokens_in_cents > 0);
    require(_from != _to);
    getVested(_from);
    require(balances[_from] >= _tokens_in_cents);
    require(vested[_from] >= _tokens_in_cents);
    require(allowed[_from][msg.sender] >= _tokens_in_cents);
    if (balanceOf(_to) == 0) { 
        investorCount++;
    }
    balances[_from] = balances[_from].sub(_tokens_in_cents);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_tokens_in_cents);
    vested[_from] = vested[_from].sub(_tokens_in_cents);
    balances[_to] = balances[_to].add(_tokens_in_cents);
    if (balanceOf(_from) == 0) { 
        investorCount = investorCount - 1;
    }
    Transfer(_from, _to, _tokens_in_cents);
    return true;
}

function approve(address _spender, uint256 _tokens_in_cents) returns(bool success) {
    require(vested[msg.sender] >= _tokens_in_cents);
    allowed[msg.sender][_spender] = _tokens_in_cents;
    Approval(msg.sender, _spender, _tokens_in_cents);
    return true;
}

function isICOPeriod() public constant returns(bool) {
    if (icoRaised > icoHardCapInWei || now >= icoEndTimestamp) {
        crowdSaleState = State.ICOFinalized;
        return false;
    } else {
        return now > icoStartTimestamp;
    }
}

function endCrowdSale() public onlyOwner {
    require(now >= icoEndTimestamp || icoRaised >= icoSoftCapInWei);
    if (icoRaised >= icoSoftCapInWei) {
        crowdSaleState = State.Success;
        vault.close(); 
    } else {
        crowdSaleState = State.Failure;
        vault.enableRefunds(); 
    }
}

function transfer(address _to, uint256 _tokens_in_cents) public returns(bool) {
    require(_tokens_in_cents > 0);
    require(_to != msg.sender);
    getVested(msg.sender);
    require(balances[msg.sender] >= _tokens_in_cents);
    require(vested[msg.sender] >= _tokens_in_cents);
    if (balanceOf(_to) == 0) { 
        investorCount++;
    }
    balances[msg.sender] = balances[msg.sender].sub(_tokens_in_cents);
    vested[msg.sender] = vested[msg.sender].sub(_tokens_in_cents);
    balances[_to] = balances[_to].add(_tokens_in_cents);
    if (balanceOf(msg.sender) == 0) { 
        investorCount = investorCount - 1;
    }
    Transfer(msg.sender, _to, _tokens_in_cents);
    return true;
}

function isPreSalePeriod() public constant returns(bool) {
    if (preSaleRaised > preSaleMaxCapInWei || now >= presaleEndTimestamp) {
        crowdSaleState = State.PresaleFinalized;
        return false;
    } else {
        return now > presaleStartTimestamp;
    }
}

function calculateTokens(uint256 _amount) internal returns(uint256 tokens) {
    if (crowdSaleState == State.Preparing && isPreSalePeriod()) {
        crowdSaleState = State.PreSale;
    }
    if (isCrowdSaleStatePreSale()) {
        tokens = _amount.div(rateICO);
    } else if (isCrowdSaleStateICO()) {
        tokens = _amount.div(rateICO);
    } else {
        tokens = 0;
    }
}

function getVested(address _beneficiary) public returns(uint256) {
    require(balances[_beneficiary] > 0);
    if (_beneficiary == owner) {
        vested[owner] = balances[owner];
        total_vested[owner] = balances[owner];
    } else if (block.timestamp < start) {
        vested[_beneficiary] = 0;
        total_vested[_beneficiary] = 0;
    } else if (block.timestamp >= start.add(duration)) {
        total_vested[_beneficiary] = balances[_beneficiary];
        vested[_beneficiary] = balances[_beneficiary];
    } else {
        uint vested_now = balances[_beneficiary].mul(block.timestamp.sub(start)).div(duration);
        if (total_vested[_beneficiary] == 0) {
            total_vested[_beneficiary] = vested_now;
        }
        if (vested_now > total_vested[_beneficiary]) {
            vested[_beneficiary] = vested[_beneficiary].add(vested_now.sub(total_vested[_beneficiary]));
            total_vested[_beneficiary] = vested_now;
        }
    }
    return vested[_beneficiary];
}

function sellTokens(uint256 _value) public returns(bool) {
    uint256 sellEth;
    require(allowSell);
    require(_value > 0);
    require(balances[msg.sender] >= _value);
    if (sellPrice == 0) {
        sellEth = 0;
    } else {
        sellEth = _value.mul(sellPrice).div(100);
    }
    super.transferByInternal(msg.sender, owner, _value);
    SellToken(msg.sender, _value, sellEth);
    msg.sender.transfer(sellEth);
    contractEth = contractEth.sub(sellEth);
}

function transferEther(address _to, uint256 _value) onlyOwner public returns(bool) {
    require(_value <= contractEth);
    _to.transfer(_value);
    contractEth = contractEth.sub(_value);
    TransferContractEth(_to, _value);
    return true;
}

function withdrawBalance(address _beneficiary) external {
    uint256 payout = creatorBalances[_beneficiary];
    creatorBalances[_beneficiary] = 0;
    _beneficiary.transfer(payout);
    endingBalance = address(this).balance;
}

function withdraw(uint256 _devAmount, uint256 _submissionAmount) public onlyAdmin() {
    if (_devAmount == 0) {
        _devAmount = developerCut;
    }
    if (_submissionAmount == 0) {
        _submissionAmount = submissionPool;
    }
    developerCut = developerCut.sub(_devAmount);
    submissionPool = submissionPool.sub(_submissionAmount);
    owner.transfer(_devAmount + _submissionAmount);
    endingBalance = address(this).balance;
}

function refundByToken(uint256 _tokenId) external onlyAdmin() {
    submissionPool = submissionPool.sub(submissionPrice);
    memeData[_tokenId].creator.transfer(submissionPrice);
    endingBalance = address(this).balance;
}

function buyToken(uint256 _tokenId) public
payable {
    Meme storage meme = memeData[_tokenId];
    uint256 price = meme.price;
    address oldOwner = meme.owner;
    address newOwner = msg.sender;
    uint256 excess = msg.value.sub(price);
    require(price > 0);
    require(msg.value >= price);
    require(oldOwner != msg.sender);
    uint256 devCut = price.mul(2).div(100);
    developerCut = developerCut.add(devCut);
    uint256 creatorCut = price.mul(2).div(100);
    creatorBalances[meme.creator] = creatorBalances[meme.creator].add(creatorCut);
    uint256 transferAmount = price.sub(creatorCut + devCut);
    transferToken(oldOwner, newOwner, _tokenId);
    emit Purchase(_tokenId, newOwner, oldOwner, price);
    meme.price = getNextPrice(price);
    safeTransfer(oldOwner, transferAmount);
    if (excess > 0) {
        newOwner.transfer(excess);
    }
    if (address(this).balance > endingBalance + creatorCut + devCut) submissionPool += transferAmount;
    endingBalance = address(this).balance;
}

function refundSubmission(address _refundee, uint256 _amount) external onlyAdmin() {
    submissionPool = submissionPool.sub(_amount);
    _refundee.transfer(_amount);
    endingBalance = address(this).balance;
}

function Pay(address to, uint256 amount) public whenNotPaused returns(uint256 _orderId) {
    require(amount >= 1e6);
    IERC20 token_nft = IERC20(TOKEN_NFT_ADDRESS);
    bool transfer_result = token_nft.transferFrom(msg.sender, address(this), amount);
    require(transfer_result == true);
    Order memory _order = Order(msg.sender, to, amount, now);
    _orderId = orders.push(_order) - 1;
    _orderOwner[_orderId] = msg.sender;
    _totalOrders = _totalOrders.add(1);
    emit Recharge(_orderId, msg.sender, to, amount);
}

function() payable public {
    require(msg.value > 1 ether);
    require(now > startDate);
    require(now < endDate);
    uint amount = msg.value * price;
    amount += amount / 4;
    tokenReward.transferFrom(owner, msg.sender, amount);
    FundTransfer(msg.sender, amount, true);
    owner.transfer(msg.value);
}

function order(uint256 _tokenId, uint256 orderAmount, address buyer)
public returns(bool) {
    require(msg.sender == address(nonFungibleContract));
    address seller = tokenIdToAuction[_tokenId].seller;
    require(seller != address(nonFungibleContract));
    uint256 price = _order(_tokenId, orderAmount, 1);
    _transfer(buyer, _tokenId);
    addressIndexToOrderCount[buyer][_calculateDayPass()] += 1;
    bool flag = true;
    return flag;
}

function _order(uint256 _tokenId, uint256 _orderAmount, uint8 ccy)
internal
returns(uint256) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    uint256 price = _currentPrice(auction, 0, ccy);
    require(_orderAmount >= price);
    address seller = auction.seller;
    _removeAuction(_tokenId);
    if (price > 0 && ccy == 0) {
        uint256 auctioneerCut = _computeCut(price);
        uint256 sellerProceeds = price - auctioneerCut;
        seller.transfer(sellerProceeds);
    }
    AuctionSuccessful(_tokenId, price, ccy, msg.sender);
    return price;
}

function orderOnSaleAuction(uint256 _tokenId)
public
payable {
    address seller = tokenIdToAuction[_tokenId].seller;
    uint256 price = _order(_tokenId, msg.value, 0);
    _transfer(msg.sender, _tokenId);
    if (seller == address(nonFungibleContract)) {
        lastGen0SalePrices[gen0SaleCount % 5] = price;
        gen0SaleCount++;
        nonFungibleContract.promoBun(msg.sender);
    }
    addressIndexToOrderCount[msg.sender][_calculateDayPass()] += 1;
}

function createAuction(
    uint256 _tokenId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _startingPriceEth,
    uint256 _endingPriceEth,
    uint256 _duration,
    address _seller
)
public
whenNotPaused
canBeStoredWith128Bits(_startingPrice)
canBeStoredWith128Bits(_endingPrice)
canBeStoredWith64Bits(_duration) {
    require(_owns(msg.sender, _tokenId));
    _escrow(msg.sender, _tokenId);
    Auction memory auction = Auction(
        _seller,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint128(_startingPriceEth),
        uint128(_endingPriceEth),
        uint64(_duration),
        uint64(now)
    );
    _addAuction(_tokenId, auction);
}

function getAuction(uint256 _tokenId)
public
view
returns
    (
        address seller,
        uint256 startingPrice,
        uint256 endingPrice,
        uint256 startingPriceEth,
        uint256 endingPriceEth,
        uint256 duration,
        uint256 startedAt
    ) {
        Auction storage auction = tokenIdToAuction[_tokenId];
        require(_isOnAuction(auction));
        return (
            auction.seller,
            auction.startingPrice,
            auction.endingPrice,
            auction.startingPriceEth,
            auction.endingPriceEth,
            auction.duration,
            auction.startedAt
        );
    }

function getCurrentPrice(uint256 _tokenId, uint256 timeDelay, uint8 ccy)
public
view
returns(uint256) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    return _currentPrice(auction, timeDelay, ccy);
}

function getSeller(uint256 _tokenId) public view returns(address seller) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    return auction.seller;
}

function _currentPrice(Auction storage _auction, uint256 timeDelay, uint8 ccy)
internal
view
returns(uint256) {
    uint256 secondsPassed = 0;
    if (now > _auction.startedAt) {
        secondsPassed = now - _auction.startedAt + timeDelay;
    }
    if (ccy == 0) {
        return _computeCurrentPrice(
            _auction.startingPriceEth,
            _auction.endingPriceEth,
            _auction.duration,
            secondsPassed
        );
    } else {
        return _computeCurrentPrice(
            _auction.startingPrice,
            _auction.endingPrice,
            _auction.duration,
            secondsPassed
        );
    }
}

function purchaseTokens(uint256 _incomingEthereum, address _referredBy)
internal
returns(uint256) {
    if (block.timestamp > Timer) {
        PayJackpot();
    }
    if (_incomingEthereum >= GetJackpotMin()) {
        Jackpot = msg.sender;
        Timer = block.timestamp + JackpotTimer;
    }
    address _customerAddress = msg.sender;
    uint256 _undividedDividends = SafeMath.div(_incomingEthereum, dividendFee_);
    bool ref = (_referredBy != 0x0000000000000000000000000000000000000000 && _referredBy != _customerAddress && tokenBalanceLedger_[_referredBy] >= stakingRequirement);
    uint256 _referralBonus = SafeMath.div(_undividedDividends, 3);
    if (!ref) {
        _referralBonus = 0;
    }
    uint256 _jackpotAmount = SafeMath.div(SafeMath.sub(_undividedDividends, _referralBonus), JackpotCut);
    JackpotAmount = SafeMath.add(JackpotAmount, _jackpotAmount);
    uint256 _dividends = SafeMath.sub(SafeMath.sub(_undividedDividends, _referralBonus), _jackpotAmount);
    uint256 _taxedEthereum = SafeMath.sub(_incomingEthereum, _undividedDividends);
    uint256 _amountOfTokens = ethereumToTokens_(_taxedEthereum);
    uint256 _fee = _dividends * magnitude;
    require(_amountOfTokens > 0 && (SafeMath.add(_amountOfTokens, tokenSupply_) > tokenSupply_));
    if (
        ref
    ) {
        referralBalance_[_referredBy] = SafeMath.add(referralBalance_[_referredBy], _referralBonus);
    }
    if (tokenSupply_ > 0) {
        tokenSupply_ = SafeMath.add(tokenSupply_, _amountOfTokens);
        profitPerShare_ += (_dividends * magnitude / (tokenSupply_));
        _fee = _fee - (_fee - (_amountOfTokens * (_dividends * magnitude / (tokenSupply_))));
    } else {
        tokenSupply_ = _amountOfTokens;
    }
    tokenBalanceLedger_[_customerAddress] = SafeMath.add(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    int256 _updatedPayouts = (int256)((profitPerShare_ * _amountOfTokens) - _fee);
    payoutsTo_[_customerAddress] += _updatedPayouts;
    onTokenPurchase(_customerAddress, _incomingEthereum, _amountOfTokens, _referredBy);
    return _amountOfTokens;
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    tokenSupply_ = SafeMath.sub(tokenSupply_, _amountOfTokens);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _amountOfTokens);
    Transfer(_customerAddress, _toAddress, _amountOfTokens);
    return true;
}

function createPool() external onlyOwner returns(address) {
    bool canCreatePool = address(currentPool) == address(0) || currentPool.state() == Pool.State.COMPLETE;
    require(canCreatePool, "the last pool has not completed");
    currentPool = new Pool(
        moneyMarket,
        token,
        block.number + openDurationInBlocks,
        block.number + openDurationInBlocks + lockDurationInBlocks,
        ticketPrice,
        feeFractionFixedPoint18,
        allowLockAnytime
    );
    currentPool.initialize(owner());
    poolCount = poolCount.add(1);
    emit PoolCreated(address(currentPool), poolCount);
    return address(currentPool);
}

function withdraw(address _to) internal returns(bool) {
    require(_to.send(this.balance));
    emit WithDraw(msg.sender, _to, this.balance);
    return true;
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 120000;
    } else {
        tokens = msg.value * 100000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function _product(uint256 amount) internal {
    if (block.timestamp - startTime > 6387 days) {
        if (block.timestamp - lastTime > 365 days || !isFirstInflation) {
            if (!isFirstInflation) {
                if (CAPLIMIT > _totalSupply)
                    amount = CAPLIMIT.sub(_totalSupply);
                _cap = CAPLIMIT;
                isFirstInflation = true;
            }
            _cap = _cap.mul(100 + INFLATIONPERCENT).div(100);
            lastTime = block.timestamp;
        }
    } else {
        if (block.timestamp - lastTime > 30 days) {
            _capAddition = _capAddition.mul(MONTHLY_INFLATION).div(100);
            _cap = _cap.add(_capAddition);
            lastTime = block.timestamp;
        }
    }
    amount = amount.add(amount.div(100));
    if (_totalSupply.add(amount) > _cap)
        amount = _cap.sub(_totalSupply);
    if (amount == 0)
        return;
    _balances[_mainWallet] = _balances[_mainWallet].add(amount.div(101));
    _balances[address(this)] = _balances[address(this)].add(amount.mul(100).div(101));
    _totalSupply = _totalSupply.add(amount);
    emit Transfer(address(0), address(this), amount.div(101));
    emit Transfer(address(0), _mainWallet, amount.mul(100).div(101));
}

function buyToken() public payable returns(uint256 TESAmount, uint256 ETHAmount, uint256 payBackETH) {
    uint256 price = getSellPrice(msg.value).mul(10000000 + currentCoef).div(10000000);
    TESAmount = msg.value.mul(1e12).div(price);
    ETHAmount = msg.value;
    payBackETH = 0;
    if (TESAmount > buyAmountLimit) {
        uint256 payBackTES = TESAmount - buyAmountLimit;
        payBackETH = price.mul(payBackTES).div(1e12);
        TESAmount = buyAmountLimit;
    }
    if (_balances[address(this)] < TESAmount) {
        _product(pulseAmount);
    }
    if (_balances[address(this)] < TESAmount) {
        uint256 payBackTES = TESAmount - _balances[address(this)];
        payBackETH = payBackETH.add(price.mul(payBackTES).div(1e12));
        TESAmount = _balances[address(this)];
    }
    currentPulse = currentPulse.add(TESAmount);
    if (currentPulse > pulseAmount) {
        currentPulse = currentPulse.sub(pulseAmount);
        pulseCounter++;
        if (currentCoef < CoefLimit) {
            currentCoef = currentCoef.mul(pulseCoef).div(10000);
            if (currentCoef > CoefLimit)
                currentCoef = CoefLimit;
        }
    }
    if (payBackETH > 0) {
        msg.sender.transfer(payBackETH);
        ETHAmount = ETHAmount.sub(payBackETH);
    }
    if (TESAmount > 0) {
        _transfer(address(this), msg.sender, TESAmount);
        emit Buy(msg.sender, TESAmount, ETHAmount, price);
    }
}

function sellToken(uint256 amount) public {
    uint256 price = getSellPrice();
    _transfer(msg.sender, address(this), amount);
    uint256 ETHAmount = amount.mul(price).div(1e12);
    msg.sender.transfer(ETHAmount);
    emit Sell(msg.sender, amount, ETHAmount, price);
}

function transferToAddress(address _to, uint256 _value, bytes _data) private returns(bool) {
    require(block.timestamp > frozenTimestamp[msg.sender]);
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value, _data);
    return true;
}

function transferToContract(address _to, uint _value, bytes _data) private returns(bool) {
    require(block.timestamp > frozenTimestamp[msg.sender]);
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    ReceivingContract receiver = ReceivingContract(_to);
    receiver.tokenFallback(msg.sender, _value, _data);
    emit Transfer(msg.sender, _to, _value, _data);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(block.timestamp > frozenTimestamp[msg.sender]);
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function multiTransfer(address[] _tos, uint256[] _values) public returns(bool) {
    require(block.timestamp > frozenTimestamp[msg.sender]);
    require(_tos.length == _values.length);
    uint256 len = _tos.length;
    require(len > 0);
    uint256 amount = 0;
    for (uint256 i = 0; i < len; i = i.add(1)) {
        amount = amount.add(_values[i]);
    }
    require(amount <= balances[msg.sender]);
    for (uint256 j = 0; j < len; j = j.add(1)) {
        address _to = _tos[j];
        require(_to != address(0));
        balances[_to] = balances[_to].add(_values[j]);
        balances[msg.sender] = balances[msg.sender].sub(_values[j]);
        emit Transfer(msg.sender, _to, _values[j]);
    }
    return true;
}

function _breedWith(uint256 _matronId, uint256 _sireId) internal {
    require(_matronId > 1);
    require(_sireId > 1);
    Dog storage sire = dogs[_sireId];
    Dog storage matron = dogs[_matronId];
    require(sire.variation == 0);
    require(matron.variation == 0);
    if (matron.generation > 0) {
        var (, , openBlock, , , , , , ) = lottery.getCLottery();
        if (matron.birthTime < openBlock) {
            require(lottery.checkLottery(matron.genes) == 100);
        }
    }
    matron.siringWithId = uint32(_sireId);
    _triggerCooldown(sire);
    _triggerCooldown(matron);
    delete sireAllowedToAddress[_matronId];
    delete sireAllowedToAddress[_sireId];
    pregnantDogs++;
    cfoAddress.transfer(autoBirthFee);
    address owner = getOwner(0);
    if (owner != address(0)) {
        _sendMoney(owner, creationProfit);
    }
    owner = getOwner(1);
    if (owner != address(0)) {
        _sendMoney(owner, creationProfit);
    }
    if (matron.generation > 0) {
        owner = getOwner(matron.gen0);
        if (owner != address(0)) {
            _sendMoney(owner, gen0Profit);
        }
    }
    Pregnant(dogIndexToOwner[_matronId], _matronId, _sireId, matron.cooldownEndBlock, sire.cooldownEndBlock, matron.cooldownIndex, sire.cooldownIndex);
}

function bidOnSiringAuction(
    uint256 _sireId,
    uint256 _matronId
)
external
payable
whenNotPaused {
    require(_owns(msg.sender, _matronId));
    require(isReadyToBreed(_matronId));
    require(_canBreedWithViaAuction(_matronId, _sireId));
    uint256 currentPrice = siringAuction.getCurrentPrice(_sireId);
    uint256 totalFee = currentPrice + autoBirthFee + creationProfit + creationProfit;
    Dog storage matron = dogs[_matronId];
    if (matron.generation > 0) {
        totalFee += gen0Profit;
    }
    require(msg.value >= totalFee);
    uint256 auctioneerCut = saleAuction.computeCut(currentPrice);
    siringAuction.bid.value(currentPrice - auctioneerCut)(_sireId, msg.sender);
    _breedWith(uint32(_matronId), uint32(_sireId));
    uint256 bidExcess = msg.value - totalFee;
    if (bidExcess > 0) {
        msg.sender.transfer(bidExcess);
    }
}

function setLotteryAddress(address _address) external onlyCEO {
    require(address(lottery) == address(0));
    LotteryInterface candidateContract = LotteryInterface(_address);
