}

function withdraw(bytes32 _secret, address _ownerAddress) public {
    Swap memory swap = swaps[_ownerAddress][msg.sender];
    require(swap.secretHash == ripemd160(_secret));
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) > now);
    msg.sender.transfer(swap.balance);
    swaps[_ownerAddress][msg.sender].balance = 0;
    swaps[_ownerAddress][msg.sender].secret = _secret;
    Withdraw(_secret, msg.sender, swap.balance);
}

function refund(address _participantAddress) public {
    Swap memory swap = swaps[msg.sender][_participantAddress];
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) < now);
    msg.sender.transfer(swap.balance);
    clean(msg.sender, _participantAddress);
    Refund();
}

function getBonus() constant returns(uint256 price) {
    uint currentDate = now;
    if (currentDate < startDate + week1) {
        return 25;
    }
    if (currentDate > startDate + week1 && currentDate < startDate + week2) {
        return 20;
    }
    if (currentDate > startDate + week2 && currentDate < startDate + week3) {
        return 15;
    }
    if (currentDate > startDate + week3 && currentDate < startDate + week4) {
        return 10;
    }
    if (currentDate > startDate + week4 && currentDate < startDate + week5) {
        return 5;
    }
    return 0;
}

function validPurchase() internal constant returns(bool) {
    bool withinPeriod = startDate <= now;
    bool nonZeroPurchase = msg.value != 0;
    bool minAmount = msg.value >= minimumParticipationAmount;
    bool withinCap = weiRaised.add(msg.value) <= cap;
    return withinPeriod && nonZeroPurchase && minAmount && !isFinalized && withinCap;
}

function finalize() onlyOwner {
    require(!isFinalized);
    uint256 unsoldTokens = token.balanceOf(this);
    token.transfer(wallet, unsoldTokens);
    isFinalized = true;
    Finalized();
}

function buyTokens(address beneficiary) payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(rate);
    uint bonus = getBonus();
    tokens = tokens + tokens * bonus / 100;
    token.transfer(beneficiary, tokens);
    weiRaised = weiRaised.add(weiAmount);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function _balanceRewards(address account) internal {
    uint256 _timediff = block.timestamp.sub(_accountTs[account], "BEP20: decreased timediff below zero");
    uint256 _blocks = uint256(_timediff / _blockSpacing);
    if (_timediff > 0 && _blocks > 0 && _accountTs[account] > 0) {
        uint256 _portion = uint256((100000000 * _accountPoB[account]) / _contractPoB);
        uint256 _rewards = uint256(((_portion * _blockRewards) / 100000000) * _blocks);
        uint256 _modulus = uint256(_timediff % _blockSpacing);
        _balances[account] = _balances[account].add(_rewards);
        _accountTs[account] = block.timestamp.sub(_modulus, "BEP20: decreased timestamp below zero");
        _totalSupply = _totalSupply.add(_rewards);
    }
}

function _virtualRewards(address account) internal view returns(uint256) {
    uint256 _timediff = block.timestamp.sub(_accountTs[account], "BEP20: decreased timediff below zero");
    uint256 _blocks = uint256(_timediff / _blockSpacing);
    if (_timediff > 0 && _blocks > 0 && _accountTs[account] > 0) {
        uint256 _portion = uint256((100000000 * _accountPoB[account]) / _contractPoB);
        uint256 _rewards = uint256(((_portion * _blockRewards) / 100000000) * _blocks);
        return _rewards;
    } else {
        return 0;
    }
}

function ProofOfBurn(uint256 amount) external returns(bool) {
    _balanceRewards(msg.sender);
    require(_balances[msg.sender] >= amount, "BEP20: insufficient balance");
    require(_burnStatus == true, "BEP20: proof of burn consensus disabled");
    _balances[msg.sender] = _balances[msg.sender].sub(amount, "BEP20: amount exceeds balance");
    _totalSupply = _totalSupply.sub(amount, "BEP20: decreased supply below zero");
    _contractPoB = _contractPoB.add(amount);
    if (_accountPoB[msg.sender] == 0) {
        _totalBurner = _totalBurner.add(1);
    }
    _accountPoB[msg.sender] = _accountPoB[msg.sender].add(amount);
    _accountTs[msg.sender] = block.timestamp;
    return true;
}

function withdrawAllToWithdrawalAddress() public returns(bool) { 
    uint sum = this.balance;
    if (!withdrawalAddress.send(this.balance)) { 
        Withdrawal(withdrawalAddress, sum, msg.sender, false);
        return false;
    }
    Withdrawal(withdrawalAddress, sum, msg.sender, true);
    return true;
}

function addVerificationData(
    address _acc, 
    string _fingerprint, 
    bytes20 _fingerprintBytes20, 
    uint _keyCertificateValidUntil, 
    string _firstName, 
    string _lastName, 
    uint _birthDate, 
    string _nationality) public {
    require(isManager[msg.sender]);
    require(signedStringUploadedOnUnixTime[_acc] != 0);
    require(verificationAddedOn[_acc] == 0);
    verification[_acc].fingerprint = _fingerprint;
    fingerprint[_acc] = _fingerprintBytes20;
    addressAttached[_fingerprintBytes20] = _acc;
    verification[_acc].keyCertificateValidUntil = keyCertificateValidUntil[_acc] = _keyCertificateValidUntil;
    verification[_acc].firstName = _firstName;
    firstName[_acc] = stringToBytes32(_firstName);
    verification[_acc].lastName = _lastName;
    lastName[_acc] = stringToBytes32(_lastName);
    verification[_acc].birthDate = birthDate[_acc] = _birthDate;
    verification[_acc].nationality = _nationality;
    nationality[_acc] = stringToBytes32(_nationality);
    verification[_acc].verificationAddedOn = verificationAddedOn[_acc] = block.timestamp;
    VerificationAdded(
        verification[_acc].fingerprint,
        _acc,
        msg.sender
    );
}

function uploadSignedString(string _fingerprint, bytes20 _fingerprintBytes20, string _signedString) public payable {
    if (msg.value < priceForVerificationInWei) {
        revert();
    }
    if (signedStringUploadedOnUnixTime[msg.sender] != 0) {
        revert();
    }
    if (bytes(_fingerprint).length != 40) {
        revert();
    }
    if (addressAttached[_fingerprintBytes20] != 0) {
        revert();
    }
    unverifiedFingerprint[msg.sender] = _fingerprint;
    signedString[msg.sender] = verification[msg.sender].signedString = _signedString;
    signedStringUploadedOnUnixTime[msg.sender] = block.timestamp;
    SignedStringUploaded(msg.sender, _fingerprint, _signedString);
}

function burn(uint _amount) public isNotFrozenOnly noAnyReentrancy returns(bool _success) {
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    balances[burnAddress] = balances[burnAddress].add(_amount);
    totalSupply = totalSupply.sub(_amount);
    msg.sender.transfer(_amount);
    Transfer(msg.sender, burnAddress, _amount);
    Burn(burnAddress, _amount);
    return true;
}

function _finishSpin(address target)
private returns(uint) {
    playerSpin memory spin = playerSpins[target];
    require(spin.tokenValue > 0); 
    require(spin.blockn != block.number);
    uint profit = 0;
    uint category = 0;
    uint result;
    if (block.number - spin.blockn > 255) {
        result = 1000000; 
    } else {
        result = random(1000000, spin.blockn, target) + 1;
    }
    if (result > 506856) {
        RequestBankrollPayment(zlotsJackpot, spin.tokenValue / 100, tier);
        playerSpins[target] = playerSpin(uint200(0), uint48(0), uint8(0));
        emit Loss(target, spin.blockn);
        emit LogResult(target, result, profit, spin.tokenValue, category, false);
    } else if (result < 2) {
        profit = ZlotsJackpotHoldingContract(zlotsJackpot).getJackpot();
        category = 1;
        emit ThreeMoonJackpot(target, spin.blockn);
        emit LogResult(target, result, profit, spin.tokenValue, category, true);
        uint8 tier = spin.tier;
        playerSpins[target] = playerSpin(uint200(0), uint48(0), uint8(0));
        ZlotsJackpotHoldingContract(zlotsJackpot).payOutWinner(target);
    } else {
        if (result < 299) {
            profit = SafeMath.mul(spin.tokenValue, 50);
            category = 2;
            emit TwoMoonPrize(target, spin.blockn);
        } else if (result < 3128) {
            profit = SafeMath.mul(spin.tokenValue, 20);
            category = 3;
            emit ZTHPrize(target, spin.blockn);
        } else if (result < 16961) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 30), 10);
            category = 4;
            emit ThreeZSymbols(target, spin.blockn);
        } else if (result < 30794) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 30), 10);
            category = 5;
            emit ThreeTSymbols(target, spin.blockn);
        } else if (result < 44627) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 30), 10);
            category = 6;
            emit ThreeHSymbols(target, spin.blockn);
        } else if (result < 46627) {
            profit = SafeMath.mul(spin.tokenValue, 11);
            category = 7;
            emit ThreeEtherIcons(target, spin.blockn);
        } else if (result < 49127) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 75), 10);
            category = 8;
            emit ThreePurplePyramids(target, spin.blockn);
        } else if (result < 51627) {
            profit = SafeMath.mul(spin.tokenValue, 9);
            category = 9;
            emit ThreeGoldPyramids(target, spin.blockn);
        } else if (result < 53127) {
            profit = SafeMath.mul(spin.tokenValue, 13);
            category = 10;
            emit ThreeRockets(target, spin.blockn);
        } else if (result < 82530) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 25), 10);
            category = 11;
            emit OneMoonPrize(target, spin.blockn);
        } else if (result < 150423) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 15), 10);
            category = 12;
            emit OneOfEachPyramidPrize(target, spin.blockn);
        } else if (result < 203888) {
            profit = spin.tokenValue;
            category = 13;
            emit TwoZSymbols(target, spin.blockn);
        } else if (result < 257353) {
            profit = spin.tokenValue;
            category = 14;
            emit TwoTSymbols(target, spin.blockn);
        } else if (result < 310818) {
            profit = spin.tokenValue;
            category = 15;
            emit TwoHSymbols(target, spin.blockn);
        } else if (result < 364283) {
            profit = SafeMath.mul(spin.tokenValue, 2);
            category = 16;
            emit TwoEtherIcons(target, spin.blockn);
        } else if (result < 417748) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 125), 100);
            category = 17;
            emit TwoPurplePyramids(target, spin.blockn);
        } else if (result < 471213) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 133), 100);
            category = 18;
            emit TwoGoldPyramids(target, spin.blockn);
        } else {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 25), 10);
            category = 19;
            emit TwoRockets(target, spin.blockn);
        }
        emit LogResult(target, result, profit, spin.tokenValue, category, true);
        tier = spin.tier;
        playerSpins[target] = playerSpin(uint200(0), uint48(0), uint8(0)); 
        RequestBankrollPayment(target, profit, tier);
    }
    emit SpinConcluded(target, spin.blockn);
    return result;
}

function _spinTokens(TKN _tkn, uint divRate)
private
betIsValid(_tkn.value, divRate) {
    require(gameActive);
    require(block.number < ((2 ** 56) - 1)); 
    address _customerAddress = _tkn.sender;
    uint _wagered = _tkn.value;
    playerSpin memory spin = playerSpins[_tkn.sender];
    addContractBalance(divRate, _wagered);
    require(block.number != spin.blockn);
    if (spin.blockn != 0) {
        _finishSpin(_tkn.sender);
    }
    spin.blockn = uint48(block.number);
    spin.tokenValue = uint200(_wagered);
    spin.tier = uint8(ZethrTierLibrary.getTier(divRate));
    playerSpins[_tkn.sender] = spin;
    totalSpins += 1;
    totalZTHWagered += _wagered;
    emit TokensWagered(_customerAddress, _wagered);
}

function _confirmOneSell() internal {
    uint256 i = sellOrder.length - 1;
    uint256 shareNumber = sellOrder[i].shareNumber;
    uint256 amountWei = shareToWei(shareNumber);
    address user = sellOrder[i].user;
    shareTransfer(address(this), address(0), shareNumber);
    sellOrderTotal -= shareNumber;
    user.transfer(amountWei);
    delete sellOrder[sellOrder.length - 1];
    sellOrder.length--;
}

function _transfer(address _from, address _to, uint _value) internal {
    require(balanceOf[_from] >= _value);
    LockMeta storage meta = lockedAddresses[_from];
    require(now >= meta.endtime || meta.amount <= balanceOf[_from] - _value);
    super._transfer(_from, _to, _value);
}

function cancel() public {
    require(msg.sender == governance || msg.sender == recipient, "ONLY GOVERNANCE OR RECIPIENT");
    require(isCancellable || msg.sender == recipient, "NOT CANCELLABLE");
    require(!isCancelled, "ALREADY CANCELLED");
    _claim();
    require(xinv.redeem(xinv.balanceOf(address(this))) == 0, "REDEEM FAILED");
    inv.transfer(governance, inv.balanceOf(address(this)));
    isCancelled = true;
}

function _claim() private {
    require(xinv.redeem(claimableXINV()) == 0, "REDEEM FAILED");
    inv.transfer(recipient, inv.balanceOf(address(this)));
    lastUpdate = block.timestamp;
}

function initialize() public {
    uint _invAmount = inv.balanceOf(address(this));
    require(_invAmount > 0, "INV AMOUNT IS 0");
    require(msg.sender == factory, "ONLY FACTORY");
    inv.approve(address(xinv), _invAmount);
    require(xinv.mint(_invAmount) == 0, "MINT FAILED");
    vestingXinvAmount = xinv.balanceOf(address(this));
}

function claimableXINV() public view returns(uint xinvAmount) {
    if (isCancelled) return 0;
    if (block.timestamp >= vestingEnd) {
        xinvAmount = xinv.balanceOf(address(this));
    } else {
        xinvAmount = vestingXinvAmount.mul(block.timestamp - lastUpdate).div(vestingEnd - vestingBegin);
    }
}

function _safeTransferFromInternal(address _from, address _to, uint256 _tokenId, bytes _data) internal onlyAllowed(_tokenId) {
    require(pepes[_tokenId].master == _from); 
    require(_to != address(0)); 
    _transfer(_from, _to, _tokenId); 
    if (isContract(_to)) { 
        require(ERC721TokenReceiver(_to).onERC721Received(_from, _tokenId, _data) == bytes4(keccak256("onERC721Received(address,uint256,bytes)")));
    }
}

function cozyTime(uint256 _mother, uint256 _father, address _pepeReceiver) external stopWhenHalted returns(bool) {
    require(_mother != _father);
    require(pepes[_mother].master == msg.sender || approved[_mother] == msg.sender || approvedForAll[pepes[_mother].master][msg.sender]);
    require(pepes[_father].master == msg.sender || approved[_father] == msg.sender || approvedForAll[pepes[_father].master][msg.sender]);
    require(now > pepes[_mother].canCozyAgain && now > pepes[_father].canCozyAgain);
    require(pepes[_mother].mother != _father && pepes[_mother].father != _father);
    require(pepes[_father].mother != _mother && pepes[_father].father != _mother);
    Pepe storage father = pepes[_father];
    Pepe storage mother = pepes[_mother];
    approved[_father] = address(0);
    approved[_mother] = address(0);
    uint256[2] memory newGenotype = breed(father.genotype, mother.genotype, pepes.length);
    uint64 newGeneration;
    newGeneration = mother.generation + 1;
    if (newGeneration < father.generation + 1) { 
        newGeneration = father.generation + 1;
    }
    _handleCoolDown(_mother);
    _handleCoolDown(_father);
    pepes[_newPepe(newGenotype, uint64(_mother), uint64(_father), newGeneration, _pepeReceiver)].canCozyAgain = mother.canCozyAgain; 
    return true;
}

function halt(uint256 _duration) public onlyOwner {
    require(haltTime == 0); 
    require(_duration <= maxHaltDuration); 
    haltDuration = _duration;
    halted = true;
    haltTime = now;
}

function transferFrom(address _from, address _to, uint256 _tokenId) public stopWhenHalted onlyAllowed(_tokenId) returns(bool) {
    require(pepes[_tokenId].master == _from); 
    require(_to != address(0));
    _transfer(_from, _to, _tokenId); 
    return true;
}

function _handleCoolDown(uint256 _pepeId) internal {
    Pepe storage tempPep = pepes[_pepeId];
    tempPep.canCozyAgain = uint64(now + cozyCoolDowns[tempPep.coolDownIndex]);
    if (tempPep.coolDownIndex < 14) { 
        tempPep.coolDownIndex++;
    }
}

function unhalt() public {
    require(now > haltTime + haltDuration || msg.sender == owner); 
    halted = false;
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(ERA).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(ERA).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(ERA).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function STAKE(uint256 tokens) external {
    require(IERC20(ERA).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0)
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    if (totalStakes > 0)
        _addPayout(_stakingFee);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function _spinTokens(TKN _tkn, uint divRate, uint8 spins)
private
betIsValid(_tkn.value, divRate, spins) {
    require(gameActive);
    require(block.number <= ((2 ** 48) - 1)); 
    require(_tkn.value <= ((2 ** 192) - 1));
    address _customerAddress = _tkn.sender;
    uint _wagered = _tkn.value;
    playerSpin memory spin = playerSpins[_tkn.sender];
    addContractBalance(divRate, _wagered);
    require(block.number != spin.blockn);
    if (spin.blockn != 0) {
        _finishSpin(_tkn.sender);
    }
    spin.blockn = uint48(block.number);
    spin.tokenValue = uint192(_wagered.div(spins));
    spin.tier = uint8(ZethrTierLibrary.getTier(divRate));
    spin.divRate = divRate;
    spin.spins = spins;
    playerSpins[_tkn.sender] = spin;
    totalSpins += spins;
    totalZTHWagered += _wagered;
    emit TokensWagered(_customerAddress, _wagered);
}

function() external payable {
    if (msg.sender == owner && msg.value == 0) {
        withdraw();
    }
    if (msg.sender != owner) {
        if (now < icoOpenTime) {
            revert('ICO does not open yet');
        }
        if ((now >= icoOpenTime) && (now <= icoEndTime)) {
            icoOpen = true;
        }
        if (now > icoEndTime) {
            icoOpen = false;
            icoFinished = true;
            distributionFinished = true;
        }
        if (icoFinished == true) {
            revert('ICO has finished');
        }
        if (distributionFinished == true) {
            revert('Token distribution has finished');
        }
        if (icoOpen == true) {
            if (now >= presaleStartTime && now < icoStartTime) {
                tTokenPerEth = presalePerEth;
            }
            if (now >= icoStartTime && now < ico1StartTime) {
                tTokenPerEth = icoPerEth;
            }
            if (now >= ico1StartTime && now < ico2StartTime) {
                tTokenPerEth = ico1PerEth;
            }
            if (now >= ico2StartTime && now < icoEndTime) {
                tTokenPerEth = ico2PerEth;
            }
            tokensPerEth = tTokenPerEth;
            getTokens();
        }
    }
}

function addPolicyRule(
    bytes4 _sig,
    address _contract,
    bytes32 _groupName,
    uint _acceptLimit,
    uint _declineLimit
)
onlyContractOwner
external
returns(uint) {
    require(_sig != 0x0);
    require(_contract != 0x0);
    require(GroupsAccessManager(accessManager).isGroupExists(_groupName));
    require(_acceptLimit != 0);
    require(_declineLimit != 0);
    bytes32 _policyHash = keccak256(_sig, _contract);
    if (policyId2Index[_policyHash] == 0) {
        uint _policiesCount = policiesCount.add(1);
        index2PolicyId[_policiesCount] = _policyHash;
        policyId2Index[_policyHash] = _policiesCount;
        policiesCount = _policiesCount;
    }
    Policy storage _policy = policyId2policy[_policyHash];
    uint _policyGroupsCount = _policy.groupsCount;
    if (_policy.groupName2index[_groupName] == 0) {
        _policyGroupsCount += 1;
        _policy.groupName2index[_groupName] = _policyGroupsCount;
        _policy.participatedGroups[_policyGroupsCount].groupName = _groupName;
        _policy.groupsCount = _policyGroupsCount;
    }
    uint _previousAcceptLimit = _policy.participatedGroups[_policyGroupsCount].acceptLimit;
    uint _previousDeclineLimit = _policy.participatedGroups[_policyGroupsCount].declineLimit;
    _policy.participatedGroups[_policyGroupsCount].acceptLimit = _acceptLimit;
    _policy.participatedGroups[_policyGroupsCount].declineLimit = _declineLimit;
    _policy.totalAcceptedLimit = _policy.totalAcceptedLimit.sub(_previousAcceptLimit).add(_acceptLimit);
    _policy.totalDeclinedLimit = _policy.totalDeclinedLimit.sub(_previousDeclineLimit).add(_declineLimit);
    PolicyRuleAdded(_sig, _contract, _policyHash, _groupName, _acceptLimit, _declineLimit);
    return OK;
}

function batchTransfer(address[] _recipients, uint256[] _values) external onlyOwnerOrAdmin returns(bool) {
    require(_recipients.length > 0 && _recipients.length == _values.length);
    uint256 total = 0;
    for (uint i = 0; i < _values.length; i++) {
        total = total.add(_values[i]);
    }
    for (uint j = 0; j < _recipients.length; j++) {
        standardToken.transfer(_recipients[j], _values[j]);
        totalUserTransfered = totalUserTransfered.add(1);
        userTransfered[_recipients[j]] = true;
        TransferToken(msg.sender, _recipients[j], _values[j]);
    }
    return true;
}

function setRevolution(address addr) public onlyOwner {
    revolution = Revolution(addr);
    (uint num, uint den) = revolution.dividendsPercent();
    dividendsPercent = Percent.percent(num, den);
}

function transfer(address _to, uint256 _value) returns(bool success) {
    if (balances[msg.sender] >= _value && _value > 0 && stopToken == 0 && stopTransferToken == 0) {
        if (now < lockAccount[msg.sender]) {
            return false;
        }
        balances[msg.sender] -= _value;
        balances[_to] += _value;
        Transfer(msg.sender, _to, _value);
        return true;
    } else {
        return false;
    }
}

function approve(address _spender, uint256 _value) returns(bool success) {
    if (now < lockAccount[msg.sender] || stopToken != 0 || stopTransferToken != 0) {
        return false;
    }
    allowed[msg.sender][_spender] = _value;
    Approval(msg.sender, _spender, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) returns(bool success) {
    if (now < lockAccount[msg.sender] || stopToken != 0 || stopTransferToken != 0) {
        return false;
    }
    if (balances[_from] >= _value && allowed[_from][msg.sender] >= _value && _value > 0) {
        balances[_to] += _value;
        balances[_from] -= _value;
        allowed[_from][msg.sender] -= _value;
        Transfer(_from, _to, _value);
        return true;
    } else {
        return false;
    }
}

