function didCloseLoan(
    bytes32 loanOrderHash,
    address loanCloser,
    bool isLiquidation,
    uint gasUsed)
public
onlyBZx
updatesEMA(tx.gasprice)
returns(bool) {
    for (uint i = 0; i < gasRefunds[loanOrderHash].length; i++) {
        GasData storage gasData = gasRefunds[loanOrderHash][i];
        if (!gasData.isPaid) {
            if (sendRefund(
                    gasData.payer,
                    gasData.gasUsed,
                    emaValue,
                    gasRewardPercent))
                gasData.isPaid = true;
        }
    }
    if (isLiquidation) {
        calculateAndSendRefund(
            loanCloser,
            gasUsed,
            emaValue,
            bountyRewardPercent);
    }
    return true;
}

function sendRefund(
    address payer,
    uint gasUsed,
    uint gasPrice,
    uint percentMultiplier)
internal
returns(bool) {
    if (percentMultiplier == 0) 
        percentMultiplier = 100;
    uint refundAmount = gasUsed.mul(gasPrice).mul(percentMultiplier).div(100);
    if (throwOnGasRefundFail) {
        payer.transfer(refundAmount);
        emit GasRefund(
            payer,
            gasUsed,
            gasPrice,
            refundAmount,
            true
        );
    } else {
        emit GasRefund(
            payer,
            gasUsed,
            gasPrice,
            refundAmount,
            payer.send(refundAmount)
        );
    }
    return true;
}

