function getAdminFee() adminOnly external {
    require(admin_profit > 0);
    msg.sender.transfer(admin_profit);
    admin_profit = 0;
}

function claimProfit(uint _gameID) external {
    require(now >= games[_gameID].claimingPhaseStart &&
        now < games[_gameID].claimingPhaseEnd);
    require(games[_gameID].tickets[msg.sender] > 0);
    require(games[_gameID].numPrizeClaimed <
        games[_gameID].numTickets / games[_gameID].winningMultiplier);
    games[_gameID].numPrizeClaimed += 1;
    games[_gameID].tickets[msg.sender] -= 1;
    uint reward = games[_gameID].ticketPrice *
        games[_gameID].winningMultiplier * (100 - MAINTENANCE_FEE_PERCENT) / 100;
    msg.sender.transfer(reward);
    games[_gameID].balance -= reward;
}

function getUnclaimedEtherIfAny(uint _gameID) adminOnly external {
    require(now >= games[_gameID].claimingPhaseEnd);
    require(games[_gameID].balance > 0);
    msg.sender.transfer(games[_gameID].balance);
    games[_gameID].balance = 0;
}

function getRefund(uint _gameID) external {
    require(now < games[_gameID].claimingPhaseStart - 1 days);
    require(games[_gameID].tickets[msg.sender] > 0);
    games[_gameID].tickets[msg.sender] -= 1;
    games[_gameID].numTickets -= 1;
    uint refund = games[_gameID].ticketPrice * REFUND_PERCENT / 100;
    uint admin_fee = games[_gameID].ticketPrice *
        (100 - REFUND_PERCENT - MAINTENANCE_FEE_PERCENT) / 100;
    admin_profit += admin_fee;
    games[_gameID].balance -= games[_gameID].ticketPrice *
        (100 - MAINTENANCE_FEE_PERCENT) / 100;
    msg.sender.transfer(refund);
}

function purchaseTicket(uint _gameID) external payable {
    require(msg.value >= games[_gameID].ticketPrice);
    require(now >= games[_gameID].bettingPhaseStart &&
        now < games[_gameID].bettingPhaseEnd);
    games[_gameID].tickets[msg.sender] += 1;
    games[_gameID].numTickets += 1;
    uint admin_fee = games[_gameID].ticketPrice * MAINTENANCE_FEE_PERCENT / 100;
    admin_profit += admin_fee;
    games[_gameID].balance += msg.value - admin_fee;
}

function unlockTeamTokens() public {
    require(owner == msg.sender, "Sender not owner");
    require(now > unlockUnix, "Unlock Time not reached yet");
    token.transfer(owner, token.balanceOf(address(this)));
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (!_isExcludedFromFee[to] && !_isExcludedFromFee[from]) {
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to]) {
            require(tradeAllowed);
            require(cooldown[to] < block.timestamp);
            uint walletBalance = balanceOf(address(to));
            require(amount.add(walletBalance) <= _tTotal.div(20));
            require(amount <= _maxTxAmount);
            cooldown[to] = block.timestamp + (30 seconds);
            _fee = 12;
            _reflection = 3;
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (!inSwap && from != uniswapV2Pair && swapEnabled && !_isExcludedFromFee[to] && !_isExcludedFromFee[from]) {
            require(amount <= balanceOf(uniswapV2Pair).div(20));
            require(cooldown[from] < block.timestamp);
            uint initialBalance = address(this).balance;
            swapTokensForEth(contractTokenBalance);
            uint newBalance = address(this).balance;
            uint distributeETHBalance = newBalance.sub(initialBalance);
            if (distributeETHBalance > 0) {
                sendETHToFee(distributeETHBalance);
            }
            _fee = 17;
            _reflection = 3;
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee;
}

function doSellerCancel(
    bytes16 _tradeID,
    address _seller,
    address _buyer,
    uint256 _value,
    uint16 _fee,
    uint128 _additionalGas
) private returns(bool) {
    Escrow memory _escrow;
    bytes32 _tradeHash;
    (_escrow, _tradeHash) = getEscrowAndHash(_tradeID, _seller, _buyer, _value, _fee);
    if (!_escrow.exists) {
        return false;
    }
    if (_escrow.sellerCanCancelAfter <= 1 || _escrow.sellerCanCancelAfter > block.timestamp) {
        return false;
    }
    uint128 _gasFees = _escrow.totalGasFeesSpentByRelayer +
        (msg.sender == relayer ?
            (GAS_doSellerCancel + _additionalGas) * uint128(tx.gasprice) :
            0
        );
    delete escrows[_tradeHash];
    emit CancelledBySeller(_tradeHash);
    transferMinusFees(_seller, _value, _gasFees, 0);
    return true;
}

function doDisableSellerCancel(
    bytes16 _tradeID,
    address _seller,
    address _buyer,
    uint256 _value,
    uint16 _fee,
    uint128 _additionalGas
) private returns(bool) {
    Escrow memory _escrow;
    bytes32 _tradeHash;
    (_escrow, _tradeHash) = getEscrowAndHash(_tradeID, _seller, _buyer, _value, _fee);
    if (!_escrow.exists) return false;
    if (_escrow.sellerCanCancelAfter == 0) return false;
    escrows[_tradeHash].sellerCanCancelAfter = 0;
    emit SellerCancelDisabled(_tradeHash);
    if (msg.sender == relayer) {
        increaseGasSpent(_tradeHash, GAS_doDisableSellerCancel + _additionalGas);
    }
    return true;
}

function transferMinusFees(
    address _to,
    uint256 _value,
    uint128 _totalGasFeesSpentByRelayer,
    uint16 _fee
) private {
    uint256 _totalFees = (_value * _fee / 10000) + _totalGasFeesSpentByRelayer;
    if (_value - _totalFees > _value) {
        return;
    }
    feesAvailableForWithdraw += _totalFees;
    _to.transfer(_value - _totalFees);
}

function createEscrow(
    bytes16 _tradeID,
    address _seller,
    address _buyer,
    uint256 _value,
    uint16 _fee,
    uint32 _paymentWindowInSeconds,
    uint32 _expiry,
    uint8 _v,
    bytes32 _r,
    bytes32 _s
) payable external {
    bytes32 _tradeHash = keccak256(abi.encodePacked(_tradeID, _seller, _buyer, _value, _fee));
    require(!escrows[_tradeHash].exists, "Trade already exists");
    bytes32 _invitationHash = keccak256(abi.encodePacked(
        _tradeHash,
        _paymentWindowInSeconds,
        _expiry
    ));
    require(recoverAddress(_invitationHash, _v, _r, _s) == relayer, "Must be relayer");
    require(block.timestamp < _expiry, "Signature has expired");
    require(msg.value == _value && msg.value > 0, "Incorrect ether sent");
    uint32 _sellerCanCancelAfter = _paymentWindowInSeconds == 0 ?
        1 :
        uint32(block.timestamp) + _paymentWindowInSeconds;
    escrows[_tradeHash] = Escrow(true, _sellerCanCancelAfter, 0);
    emit Created(_tradeHash);
}

function withdrawFees(address _to, uint256 _amount) onlyOwner external {
    require(_amount <= feesAvailableForWithdraw, "Amount is higher than amount available");
    feesAvailableForWithdraw -= _amount;
    _to.transfer(_amount);
}

function doSellerRequestCancel(
    bytes16 _tradeID,
    address _seller,
    address _buyer,
    uint256 _value,
    uint16 _fee,
    uint128 _additionalGas
) private returns(bool) {
    Escrow memory _escrow;
    bytes32 _tradeHash;
    (_escrow, _tradeHash) = getEscrowAndHash(_tradeID, _seller, _buyer, _value, _fee);
    if (!_escrow.exists) {
        return false;
    }
    if (_escrow.sellerCanCancelAfter != 1) {
        return false;
    }
    escrows[_tradeHash].sellerCanCancelAfter = uint32(block.timestamp) +
        requestCancellationMinimumTime;
    emit SellerRequestedCancel(_tradeHash);
    if (msg.sender == relayer) {
        increaseGasSpent(_tradeHash, GAS_doSellerRequestCancel + _additionalGas);
    }
    return true;
}

function resolveDispute(
    bytes16 _tradeID,
    address _seller,
    address _buyer,
    uint256 _value,
    uint16 _fee,
    uint8 _v,
    bytes32 _r,
    bytes32 _s,
    uint8 _buyerPercent
) external onlyArbitrator {
    address _signature = recoverAddress(keccak256(abi.encodePacked(
        _tradeID,
        INSTRUCTION_RESOLVE
    )), _v, _r, _s);
    require(_signature == _buyer || _signature == _seller, "Must be buyer or seller");
    Escrow memory _escrow;
    bytes32 _tradeHash;
    (_escrow, _tradeHash) = getEscrowAndHash(_tradeID, _seller, _buyer, _value, _fee);
    require(_escrow.exists, "Escrow does not exist");
    require(_buyerPercent <= 100, "_buyerPercent must be 100 or lower");
    uint256 _totalFees = _escrow.totalGasFeesSpentByRelayer + (GAS_doResolveDispute * uint128(tx.gasprice));
    require(_value - _totalFees <= _value, "Overflow error"); 
    feesAvailableForWithdraw += _totalFees; 
    delete escrows[_tradeHash];
    emit DisputeResolved(_tradeHash);
    if (_buyerPercent > 0)
        _buyer.transfer((_value - _totalFees) * _buyerPercent / 100);
    if (_buyerPercent < 100)
        _seller.transfer((_value - _totalFees) * (100 - _buyerPercent) / 100);
}

