    totalSupply = (totalSupply.add(rewardTransferAmount));
    balances[msg.sender] = (balances[msg.sender].add(rewardTransferAmount));
    owner.transfer(msg.value);
    Transfer(address(this), msg.sender, rewardTransferAmount);
}

function doSend(
    address _from,
    address _to,
    uint256 _amount,
    bytes _userData,
    address _operator,
    bytes _operatorData,
    bool _preventLocking
)
internal {
    requireMultiple(_amount);
    callSender(_operator, _from, _to, _amount, _userData, _operatorData);
    require(_to != address(0)); 
    require(mBalances[_from] >= _amount); 
    mBalances[_from] = mBalances[_from].sub(_amount);
    mBalances[_to] = mBalances[_to].add(_amount);
    callRecipient(_operator, _from, _to, _amount, _userData, _operatorData, _preventLocking);
    emit Sent(_operator, _from, _to, _amount, _userData, _operatorData);
    if (mErc20compatible) {
        emit Transfer(_from, _to, _amount);
    }
}

function isActive() public view override returns(bool) {
    return block.timestamp < endTime;
}

constructor(
    address _token,
    bytes32 _merkleRoot,
    uint256 _endTime
) public {
    token = _token;
    merkleRoot = _merkleRoot;
    require(block.timestamp < _endTime, "Invalid endTime");
