function cashoutable(address _address)
public
view
returns(bool) {
    return (round[curRoundId].pTicketSum[_address] > 0) || (round[curRoundId].startTime > block.timestamp);
}

function getWinSlot(uint256 _keyNumber)
public
view
returns(uint256) {
    uint256 _to = slot.length - 1;
    uint256 _from = round[curRoundId - 1].slotSum + 1; 
    uint256 _pivot;
    uint256 _pivotWTo;
    while (_from <= _to) {
        _pivot = (_from + _to) / 2;
        _pivotWTo = slot[_pivot].wTo;
        if (isWinSlot(_pivot, _keyNumber)) return _pivot;
        if (_pivotWTo < _keyNumber) { 
            _from = _pivot + 1;
        } else { 
            _to = _pivot - 1;
        }
    }
    return _pivot; 
}

function claimEarlyIncomebyAddressRound(address _buyer, uint256 _rId)
private
returns(uint256) {
    uint256 _amount = getCurEarlyIncomeByAddressRound(_buyer, _rId);
    if (_amount == 0) return 0;
    round[_rId].pEarlyIncomeClaimed[_buyer] = _amount.add(round[_rId].pEarlyIncomeClaimed[_buyer]);
    rewardBalance[_buyer] = _amount.add(rewardBalance[_buyer]);
    return _amount;
}

function finalize()
public {
    require(finalizeable(), "Not ready to draw results");
    require((round[curRoundId].pTicketSum[msg.sender] > 0) || (curRTicketSum == 0), "must buy at least 1 ticket");
    endRound(msg.sender);
    initRound();
}

function getSeed(uint256 _keyBlockNr)
public
view
returns(uint256) {
    if (block.number <= _keyBlockNr) return block.number;
    return uint256(blockhash(_keyBlockNr));
}

function getKeyBlockNr(uint256 _estKeyBlockNr)
public
view
returns(uint256) {
    require(block.number > _estKeyBlockNr, "blockHash not avaiable");
    uint256 jump = (block.number - _estKeyBlockNr) / MAX_BLOCK_DISTANCE * MAX_BLOCK_DISTANCE;
    return _estKeyBlockNr + jump;
}

function isWinSlot(uint256 _slotId, uint256 _keyNumber)
public
view
returns(bool) {
    return (slot[_slotId - 1].wTo < _keyNumber) && (slot[_slotId].wTo >= _keyNumber);
}

function endRound(address _bountyHunter)
private {
    uint256 _rId = curRoundId;
    uint256 keyBlockNr = getKeyBlockNr(round[_rId].keyBlockNr);
    uint256 _seed = getSeed(keyBlockNr) + curRSalt;
    uint256 onePercent = grandPot / 100;
    uint256 rGrandReward = onePercent * grandRewardPercent;
    uint256 toF2mAmount = onePercent * toTokenPercent;
    grandPot = grandPot - toF2mAmount - onePercent;
    f2mContract.pushDividends.value(toF2mAmount)();
    uint256 weightRange = getWeightRange();
    for (uint256 i = 0; i < 3; i++) {
        uint256 winNr = Helper.getRandom(_seed, weightRange);
        if (winNr <= curRWeight) {
            grandPot -= rGrandReward;
            uint256 _winSlot = getWinSlot(winNr);
            address _winner = slot[_winSlot].buyer;
            mintReward(_winner, _winSlot, rGrandReward, RewardType.Grand);
            _seed = _seed + (_seed / 10);
        }
    }
    mintReward(_bountyHunter, 0, onePercent * 3 / 10, RewardType.Bounty);
    rewardContract.pushBounty.value(onePercent * 7 / 10)(curRoundId);
}

function finalizeable()
public
view
returns(bool) {
    uint256 finalizeTime = FINALIZE_WAIT_DURATION.add(round[curRoundId].slideEndTime);
    if (finalizeTime > block.timestamp) return false; 
    if (getEstKeyBlockNr(curRoundId) >= block.number) return false; 
    return curRoundId > 0;
}

function jackpot()
private {
    uint256 keyBlockNr = getKeyBlockNr(lastBlockNr); 
    uint256 seed = getSeed(keyBlockNr);
    uint256 jReward;
    uint256 toF2mAmount;
    address winner;
    while (jSlot + 1 < round[curRoundId].slotSum) {
        if ((seed % MAJOR_RATE == 6) &&
            (slot[jSlot].ethAmount >= MAJOR_MIN)) {
            winner = slot[jSlot].buyer;
            jReward = majorPot / 100 * jRewardPercent;
            mintReward(winner, jSlot, jReward, RewardType.Major);
            toF2mAmount = majorPot / 100 * toTokenPercent;
            f2mContract.pushDividends.value(toF2mAmount)();
            majorPot = majorPot - jReward - toF2mAmount;
        }
        if (((seed + jSlot) % MINOR_RATE == 8) &&
            (slot[jSlot].ethAmount >= MINOR_MIN)) {
            winner = slot[jSlot].buyer;
            jReward = minorPot / 100 * jRewardPercent;
            mintReward(winner, jSlot, jReward, RewardType.Minor);
            toF2mAmount = minorPot / 100 * toTokenPercent;
            f2mContract.pushDividends.value(toF2mAmount)();
            minorPot = minorPot - jReward - toF2mAmount;
        }
        seed = seed + 1;
        jSlot = jSlot + 1;
    }
}

function genEstKeyBlockNr(uint256 _endTime)
public
view
returns(uint256) {
    if (block.timestamp >= _endTime) return block.number + 8;
    uint256 timeDist = _endTime - block.timestamp;
    uint256 estBlockDist = timeDist / BLOCK_TIME;
    return block.number + estBlockDist + 8;
}

function distributeSlotBuy(address _sender, uint256 _rId, uint256 _ethAmount)
private {
    uint256 onePercent = _ethAmount / 100;
    uint256 toF2mAmount = onePercent * toTokenPercent; 
    uint256 toRefAmount = onePercent * toRefPercent; 
    uint256 toBuyTokenAmount = onePercent * toBuyTokenPercent; 
    uint256 earlyIncomeAmount = onePercent * earlyIncomePercent; 
    uint256 taxAmount = toF2mAmount + toRefAmount + toBuyTokenAmount + earlyIncomeAmount; 
    uint256 taxedEthAmount = _ethAmount.sub(taxAmount); 
    addPot(taxedEthAmount);
    citizenContract.pushRefIncome.value(toRefAmount)(_sender);
    f2mContract.pushDividends.value(toF2mAmount)();
    f2mContract.buyFor.value(toBuyTokenAmount)(_sender);
    uint256 deltaPpw = (earlyIncomeAmount * ZOOM).div(round[_rId].rEarlyIncomeWeight);
    round[_rId].ppw = deltaPpw.add(round[_rId].ppw);
}

function goNext()
private {
    uint256 _totalPot = getTotalPot();
    grandPot = 0;
    majorPot = 0;
    minorPot = 0;
    f2mContract.pushDividends.value(_totalPot)();
    round[curRoundId].startTime = block.timestamp * 10;
    round[curRoundId].slideEndTime = block.timestamp * 10 + 1;
}

function buyFor(string _sSalt, address _sender)
public
payable
buyable() {
    uint256 _salt = Helper.stringToUint(_sSalt);
    uint256 _ethAmount = msg.value;
    uint256 _ticketSum = curRTicketSum;
    require(_ethAmount >= Helper.getTPrice(_ticketSum), "not enough to buy 1 ticket");
    updateInvested(_sender, _ethAmount);
    curRSalt = curRSalt + _salt;
    Slot memory _slot;
    _slot.rId = curRoundId;
    _slot.buyer = _sender;
    _slot.ethAmount = _ethAmount;
    _slot.salt = _salt;
    uint256 _tAmount = Helper.getTAmount(_ethAmount, _ticketSum);
    uint256 _tMul = Helper.getTMul(_ticketSum);
    uint256 _pMul = Helper.getEarlyIncomeMul(_ticketSum);
    uint256 _pWeight = _pMul.mul(_tAmount);
    uint256 _toAddTime = Helper.getAddedTime(_ticketSum, _tAmount);
    addTime(curRoundId, _toAddTime);
    uint256 _slotWeight = (_tAmount).mul(_tMul);
    curRWeight = curRWeight.add(_slotWeight);
    _slot.wTo = curRWeight;
    uint256 lastSlot = slot.length - 1;
    _slot.tNumberFrom = slot[lastSlot].tNumberTo + 1;
    _slot.tNumberTo = slot[lastSlot].tNumberTo + _tAmount;
    updateTicketSum(_sender, _tAmount);
    updateEarlyIncome(_sender, _pWeight);
    slot.push(_slot);
    round[curRoundId].slotSum = slot.length;
    pSlot[_sender].push(slot.length - 1);
    if (lastBlockNr != block.number) {
        jackpot();
        lastBlockNr = block.number;
    }
    distributeSlotBuy(_sender, curRoundId, _ethAmount);
    round[curRoundId].keyBlockNr = genEstKeyBlockNr(round[curRoundId].slideEndTime);
}

function devTeamAutoBuy(uint256 _reserved, uint256 _buyPrice)
private {
    uint256 _refClaim = citizenContract.devTeamReinvest();
    credit[devTeam] -= int256(_refClaim);
    uint256 _ethAmount = ethBalance(devTeam);
    if ((_ethAmount + _reserved) / _buyPrice + totalSupply > HARD_TOTAL_SUPPLY) return;
    uint256 _rDividends = getRDividends(devTeam);
    uint256 _todayDividends = getTodayDividendsByAddress(devTeam);
    mintToken(devTeam, _ethAmount, _buyPrice);
    updateCredit(devTeam, 0, _rDividends, _todayDividends);
}

function transferFrom(address _from, address _to, uint256 _tokenAmount)
public
returns(bool) {
    updateAllowed(_from, _to, _tokenAmount);
    updateLastActive(_from);
    updateLastActive(_to);
    uint256 curEthBalance_from = ethBalance(_from);
    uint256 _rDividends_from = getRDividends(_from);
    uint256 _todayDividends_from = getTodayDividendsByAddress(_from);
    uint256 curEthBalance_to = ethBalance(_to);
    uint256 _rDividends_to = getRDividends(_to);
    uint256 _todayDividends_to = getTodayDividendsByAddress(_to);
    uint256 taxedTokenAmount = _tokenAmount;
    balances[_from] -= taxedTokenAmount;
    balances[_to] += taxedTokenAmount;
    updateCredit(_from, curEthBalance_from, _rDividends_from, _todayDividends_from);
    updateCredit(_to, curEthBalance_to, _rDividends_to, _todayDividends_to);
    emit Transfer(_from, _to, taxedTokenAmount);
    return true;
}

function sell(uint256 _tokenAmount)
public
onlyTokenHolders() {
    updateLastActive(msg.sender);
    address seller = msg.sender;
    uint256 curEthBalance = ethBalance(seller);
    uint256 _rDividends = getRDividends(seller);
    uint256 _todayDividends = getTodayDividendsByAddress(seller);
    uint256 ethAmount = burnToken(seller, _tokenAmount);
    uint256 fund = ethAmount.mul(fundPercent) / 100;
    uint256 taxedAmount = ethAmount.sub(fund);
    totalSellVolume = totalSellVolume + ethAmount;
    totalSellVolumeInDay[getToday()] += ethAmount;
    curEthBalance = curEthBalance.add(taxedAmount);
    fromSellingAmount[seller] += taxedAmount;
    updateCredit(seller, curEthBalance, _rDividends, _todayDividends);
    distributeTax(fund, 0, 0, 0);
}

function addDividends(uint256 _dividends)
private {
    if (_dividends == 0) return;
    totalDividends += _dividends;
    uint256 today = getToday();
    divInDay[today] = _dividends.add(divInDay[today]);
    if (totalSupply == 0) {
        addFund(_dividends);
    } else {
        addFund(_dividends % totalSupply);
        uint256 deltaShare = _dividends / totalSupply;
        pps = pps.add(deltaShare);
        uint256 curRoundId = getCurRoundId();
        rPps[curRoundId] += deltaShare;
        totalDividendsByRound[curRoundId] += _dividends;
        ppsInDay[today] = deltaShare + ppsInDay[today];
    }
}

function buyFor(address _buyer)
public
payable {
    updateLastActive(_buyer);
    uint256 _buyPrice = getBuyPrice();
    uint256 ethAmount = msg.value;
    pInvestedSum[_buyer] += ethAmount;
    checkLimit(_buyer);
    uint256 onePercent = ethAmount / 100;
    uint256 fund = onePercent.mul(fundPercent);
    uint256 dividends = onePercent.mul(divPercent);
    uint256 toRef = onePercent.mul(refPercent);
    uint256 toPot = onePercent.mul(potPercent);
    uint256 tax = fund + dividends + toRef + toPot;
    uint256 taxedAmount = ethAmount.sub(tax);
    totalBuyVolume = totalBuyVolume + ethAmount;
    totalBuyVolumeInDay[getToday()] += ethAmount;
    distributeTax(fund, dividends, toRef, toPot);
    if (autoBuy) devTeamAutoBuy(taxedAmount, _buyPrice);
    uint256 curEthBalance = ethBalance(_buyer);
    uint256 _rDividends = getRDividends(_buyer);
    uint256 _todayDividends = getTodayDividendsByAddress(_buyer);
    mintToken(_buyer, taxedAmount, _buyPrice);
    updateCredit(_buyer, curEthBalance, _rDividends, _todayDividends);
}

function setNewToken(address _newTokenAddress)
public
onlyAdmin() {
    bool _isLastRound = lotteryContract.isLastRound();
    require(_isLastRound, "too early");
    require(swapActived == false, "already set");
    swapTime = block.timestamp;
    swapActived = true;
    newTokenContract = NewTokenInterface(_newTokenAddress);
    autoBuy = false;
}

function distributeTax(
    uint256 _fund,
    uint256 _dividends,
    uint256 _toRef,
    uint256 _toPot)
private {
    addFund(_fund);
    addDividends(_dividends);
    addToRef(_toRef);
    addToPot(_toPot);
}

function updateCredit(address _owner, uint256 _currentEthAmount, uint256 _rDividends, uint256 _todayDividends)
private {
    uint256 curRoundId = getCurRoundId();
    credit[_owner] = int256(pps.mul(balances[_owner])).sub(int256(_currentEthAmount));
    rCredit[_owner][curRoundId] = int256(rPps[curRoundId] * balances[_owner]) - int256(_rDividends);
    todayCredit[_owner] = int256(ppsInDay[getToday()] * balances[_owner]) - int256(_todayDividends);
}

function addToPot(uint256 _toPot)
private {
    if (_toPot == 0) return;
    lotteryContract.pushToPot.value(_toPot)();
    uint256 _totalPot = lotteryContract.getTotalPot();
    if (_totalPot >= FIRST_POT_MAXIMUM) {
        round0 = false;
        potPercent = 0;
    }
}

function getRound0MinDuration()
public
view
returns(uint256) {
    if (!round0) return 0;
    if (block.timestamp > ROUND0_MIN_DURATION.add(deployedTime)) return 0;
    return ROUND0_MIN_DURATION + deployedTime - block.timestamp;
}

function getAvgPps()
public
view
returns(uint256) {
    uint256 divSum = 0;
    uint256 _today = getToday();
    uint256 _fromDay = _today - 6;
    if (_fromDay < deployedDay) _fromDay = deployedDay;
    for (uint256 i = _fromDay; i <= _today; i++) {
        divSum = divSum.add(divInDay[i]);
    }
    if (totalSupply == 0) return 0;
    return divSum / (_today + 1 - _fromDay) / totalSupply;
}

function updateLastActive(address _sender)
private {
    if (lastActiveDay[_sender] != getToday()) {
        lastActiveDay[_sender] = getToday();
        todayCredit[_sender] = 0;
    }
}

function getTodayDividendsByAddress(address _invester)
public
view
returns(uint256) {
    int256 _todayCredit = (getToday() == lastActiveDay[_invester]) ? todayCredit[_invester] : 0;
    return (uint256)((int256)(ppsInDay[getToday()] * balances[_invester]) - _todayCredit);
}

function mintToken(address _buyer, uint256 _taxedAmount, uint256 _buyPrice)
private
swapNotActived()
buyable()
returns(uint256) {
    uint256 revTokens = ethToToken(_taxedAmount, _buyPrice);
    investedAmount = investedAmount.add(_taxedAmount);
    if (revTokens + totalSupply > HARD_TOTAL_SUPPLY)
        revTokens = HARD_TOTAL_SUPPLY.sub(totalSupply);
    balances[_buyer] = balances[_buyer].add(revTokens);
    totalSupply = totalSupply.add(revTokens);
    return revTokens;
}

function getWeeklySellVolume()
public
view
returns(uint256) {
    uint256 _total = 0;
    uint256 _today = getToday();
    for (uint256 i = _today; i + 7 > _today; i--) {
        _total = _total + totalSellVolumeInDay[i];
    }
    return _total;
}

function burnToken(address _seller, uint256 _tokenAmount)
private
returns(uint256) {
    require(balances[_seller] >= _tokenAmount, "not enough to burn");
    uint256 revEthAmount = tokenToEth(_tokenAmount);
    investedAmount = investedAmount.sub(revEthAmount);
    balances[_seller] = balances[_seller].sub(_tokenAmount);
    totalSupply = totalSupply.sub(_tokenAmount);
    return revEthAmount;
}

function withdrawFor(address sender)
public
withdrawRight()
returns(uint256) {
    uint256 amount = ethBalance(sender);
    if (amount == 0) return 0;
    credit[sender] = credit[sender].add(int256(amount));
    withdrawnAmount[sender] = amount.add(withdrawnAmount[sender]);
    bankContract.pushToBank.value(amount)(sender);
    return amount;
}

function sleep()
public {
    require(swapActived, "swap not actived");
    require(swapTime + BEFORE_SLEEP_DURAION < block.timestamp, "too early");
    uint256 _ethAmount = address(this).balance;
    devTeam.transfer(_ethAmount);
}

function updateAllowed(address _from, address _to, uint256 _tokenAmount)
private {
    require(balances[_from] >= _tokenAmount, "not enough to transfer");
    if (_from != msg.sender)
        allowed[_from][_to] = allowed[_from][_to].sub(_tokenAmount);
}

function getWeeklyBuyVolume()
public
view
returns(uint256) {
    uint256 _total = 0;
    uint256 _today = getToday();
    for (uint256 i = _today; i + 7 > _today; i--) {
        _total = _total + totalBuyVolumeInDay[i];
    }
    return _total;
}

function getSellPrice()
public
view
returns(uint256) {
    if (totalSupply == 0) {
        return 0;
    } else {
