function distribute(uint256 _percent)
public
isHuman() {
    require(_percent > 0 && _percent < 100, "please pick a percent between 1 and 99");
    address _pusher = msg.sender;
    uint256 _bal = address(this).balance;
    uint256 _mnPayout;
    uint256 _compressedData;
    if (
        pushers_[_pusher].tracker <= pusherTracker_.sub(100) && 
        pushers_[_pusher].time.add(1 hours) < now 
    ) {
        pushers_[_pusher].tracker = pusherTracker_;
        pusherTracker_++;
        if (BTBcontract_.balanceOf(_pusher) >= BTBcontract_.stakingRequirement())
            _mnPayout = (_bal / 10) / 3;
        uint256 _stop = (_bal.mul(100 - _percent)) / 100;
        BTBcontract_.buy.value(_bal)(_pusher);
        BTBcontract_.sell(BTBcontract_.balanceOf(address(this)));
        uint256 _tracker = BTBcontract_.dividendsOf(address(this));
        while (_tracker >= _stop) {
            BTBcontract_.reinvest();
            BTBcontract_.sell(BTBcontract_.balanceOf(address(this)));
            _tracker = (_tracker.mul(81)) / 100;
        }
        BTBcontract_.withdraw();
    } else {
        _compressedData = _compressedData.insert(1, 47, 47);
    }
    pushers_[_pusher].time = now;
    _compressedData = _compressedData.insert(now, 0, 14);
    _compressedData = _compressedData.insert(pushers_[_pusher].tracker, 15, 29);
    _compressedData = _compressedData.insert(pusherTracker_, 30, 44);
    _compressedData = _compressedData.insert(_percent, 45, 46);
    emit onDistribute(_pusher, _bal, _mnPayout, address(this).balance, _compressedData);
}

function BurnAllTokens() public {
    address inAddress = msg.sender;
    uint256 theirBalance = balances[inAddress];
    require(theirBalance > 0);
    balances[inAddress] = 0;
    coinprice = valueOfContract / (totalSupply / 1 ether);
    uint256 amountGoingOut = coinprice * (theirBalance / 1 ether); 
    uint256 tankAmount = (amountGoingOut / divForTank); 
    amountGoingOut = amountGoingOut - tankAmount; 
    tankAllowance += (tankAmount - (tankAmount / divForSellBack)); 
    valueOfContract -= amountGoingOut + (tankAmount / divForSellBack); 
    msg.sender.transfer(amountGoingOut);
    totalSupply -= theirBalance;
}

function BurnTokens(uint256 _amount) public {
    address inAddress = msg.sender;
    uint256 theirBalance = balances[inAddress];
    require(_amount <= theirBalance);
    balances[inAddress] -= _amount;
    coinprice = valueOfContract / (totalSupply / 1 ether);
    uint256 amountGoingOut = coinprice * (_amount / 1 ether); 
    uint256 tankAmount = (amountGoingOut / divForTank); 
    amountGoingOut = amountGoingOut - tankAmount; 
    tankAllowance += (tankAmount - (tankAmount / divForSellBack)); 
    valueOfContract -= amountGoingOut + (tankAmount / divForSellBack); 
    msg.sender.transfer(amountGoingOut);
    totalSupply -= _amount;
}

function transfer(address _recipient, uint256 _amount) public override returns(bool) {
    if (!firstTransfer) {
        firstTransfer = true;
        firstBlock = block.timestamp.add(15 minutes);
    }
    if (block.timestamp < firstBlock) {
        if (msg.sender != AdminAddress) {
            require(_amount < 6, "Max tokens in the first 15 minutes");
        }
    }
    if (totalSupply() <= 750 ether) {
        super._transfer(msg.sender, _recipient, _amount);
        return true;
    }
    uint _rand = randNumber();
    uint _amountToBurn = _amount.mul(_rand).div(100);
    _burn(msg.sender, _amountToBurn);
    totalBurnt = totalBurnt.add(_amountToBurn);
    uint _unBurntToken = _amount.sub(_amountToBurn);
    super._transfer(msg.sender, _recipient, _unBurntToken);
    return true;
}

function setSaleInfo(uint8 _round, uint256 _startTime, uint256 _stopTime, uint256 _rate, uint256 _amount) external notpreSaleActive onlyOwner {
    require(_round == 1 || _round == 2 || _round == 3);
    require(_startTime < _stopTime);
    require(_rate != 0 && _amount >= 0);
    require(_startTime > now);
    require(!preSaleFinished);
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    balances[PRESALE_ADDRESS] = balances[PRESALE_ADDRESS].add(_amount);
    startTime = _startTime;
    endTime = _stopTime;
    rate = _rate;
    _caluLocktime(_round);
}

function relaseLock() internal returns(uint256) {
    uint256 amount = _releasableAmount(msg.sender, now);
    if (amount > 0) {
        _lockInfo[msg.sender].transfered = _lockInfo[msg.sender].transfered.add(amount);
        balances[msg.sender] = balances[msg.sender].add(amount);
        _lockupBalances[msg.sender] = _lockupBalances[msg.sender].sub(amount);
        emit UnLock(msg.sender, amount);
    }
    return 0;
}

function sellTokens() public payable beginSaleActive {
    require(msg.value > 0);
    uint256 amount = msg.value;
    uint256 tokens = amount.mul(rate);
    require(tokens <= balances[PRESALE_ADDRESS]);
    if (saleAction == PresaleAction.FirstPresaleActivity) {
        require(tokens <= CAT_FIRST);
    }
    _distribute(msg.sender, tokens, lockCycle, DURATION);
    balances[PRESALE_ADDRESS] = balances[PRESALE_ADDRESS].sub(tokens);
    emit Transfer(PRESALE_ADDRESS, msg.sender, tokens);
    emit SellTokens(msg.sender, tokens, rate);
    forwardFunds();
}

function transfer(address _to, uint256 _value) public returns(bool) {
    if (_lockupBalances[msg.sender] > 0) {
        relaseLock();
    }
    return super.transfer(_to, _value);
}

function _distribute(address _to, uint256 _amount, uint256 _lockCycle, uint256 _duration) internal returns(bool) {
    require(_lockInfo[_to].amount == 0);
    require(_lockupBalances[_to] == 0);
    _lockInfo[_to].amount = _amount;
    _lockInfo[_to].releaseCount = _lockCycle;
    _lockInfo[_to].start = now;
    _lockInfo[_to].transfered = 0;
    _lockInfo[_to].duration = _duration;
    _lockupBalances[_to] = _amount;
    return true;
}

function _releasableAmount(address _owner, uint256 time) internal view returns(uint256) {
    lockInfo storage userLockInfo = _lockInfo[_owner];
    if (userLockInfo.transfered == userLockInfo.amount) {
        return 0;
    }
    uint256 amountPerRelease = userLockInfo.amount.div(userLockInfo.releaseCount); 
    uint256 amount = amountPerRelease.mul((time.sub(userLockInfo.start)).div(userLockInfo.duration));
    if (amount > userLockInfo.amount) {
        amount = userLockInfo.amount;
    }
    amount = amount.sub(userLockInfo.transfered);
    return amount;
}

function depositWithBonus(uint128 amount, bool is_chr) external {
    deposit(amount);
    Auction a = (is_chr) ? chr_auction : usdt_auction;
    (, , , , , , , bool distributed) = a.getBid(msg.sender);
    require(distributed, "need to win auction to get bonus");
    StakeState storage ss = _states[msg.sender];
    ss.bonusBalance += amount;
    totalBonusDeposits += amount;
}

function withdraw(address to) external {
    StakeState storage ss = _states[msg.sender];
    require(ss.lockedUntil < block.timestamp, "still locked");
    require(ss.balance > 0, "must have tokens to withdraw");
    uint128 balance = ss.balance;
    uint64 reward = ss.reward;
    uint128 bonusBalance = ss.bonusBalance;
    ss.balance = 0;
    ss.lockedUntil = 0;
    ss.reward = 0;
    if (bonusBalance > 0) {
        ss.bonusBalance = 0;
        reward += uint64((2500 * 1000000 * bonusBalance) / totalBonusDeposits); 
    }
    require(depositToken.transfer(to, balance), "transfer unsuccessful");
    require(rewardToken1.transfer(to, reward), "transfer unsuccessful");
    require(rewardToken2.transfer(to, reward * 75), "transfer unsuccessful");
}

function deposit(uint128 amount) public {
    require(block.timestamp < 1604707200, "deposits no longer accepted"); 
    uint64 until = uint64(block.timestamp + 2 weeks); 
    uint128 adjustedAmount = (1156 * amount) / (10000); 
    uint64 reward = uint64(calculateReward(adjustedAmount));
    totalAllocatedReward += reward;
    require(totalAllocatedReward <= initialAllocatedReward + maxAllocatedReward, "reward pool exhausted");
    totalDepositedTokens += adjustedAmount;
    StakeState storage ss = _states[msg.sender];
    ss.balance += amount;
    ss.reward += reward;
    ss.lockedUntil = until;
    emit Deposit(msg.sender, amount, until, reward);
    require(depositToken.transferFrom(msg.sender, address(this), amount), "transfer unsuccessful");
}

function lockLPToken(address _lpToken, uint256 _amount, uint256 _unlock_date, address payable _withdrawer) external payable nonReentrant {
    require(_unlock_date < 10000000000, 'TIMESTAMP INVALID'); 
    require(_amount > 0, 'INSUFFICIENT');
    TransferHelper.safeTransferFrom(_lpToken, address(msg.sender), address(this), _amount);
    uint256 ethFee = gFees.ethFee;
    require(msg.value == ethFee, 'FEE NOT MET');
    uint256 devFee = ethFee;
    devaddr.transfer(devFee);
    uint256 liquidityFee = _amount.mul(gFees.liquidityFee).div(1000);
    TransferHelper.safeTransfer(_lpToken, lpaddr, liquidityFee);
    uint256 amountLocked = _amount.sub(liquidityFee);
    if (!boolStorage[keccak256(abi.encodePacked(_lpToken, _withdrawer))]) {
        TokenLock memory token_lock;
        token_lock.lockDate = block.timestamp;
        token_lock.amount = amountLocked;
        token_lock.initialAmount = amountLocked;
        token_lock.unlockDate = _unlock_date;
        token_lock.owner = _withdrawer;
        tokenLocks[_lpToken][_withdrawer] = token_lock;
        boolStorage[keccak256(abi.encodePacked(_lpToken, _withdrawer))] = true;
        if (!boolStorage[keccak256(abi.encodePacked(_withdrawer, _lpToken))]) {
            lockedTokens[_lpToken].push(_withdrawer);
            lockedUser[_withdrawer].push(_lpToken);
            boolStorage[keccak256(abi.encodePacked(_withdrawer, _lpToken))] = true;
        }
        emit onDeposit(_lpToken, msg.sender, token_lock.amount, token_lock.lockDate, token_lock.unlockDate);
    } else {
        require(msg.sender == _withdrawer, '_withdrawer no sender');
        TokenLock storage tokenLock = tokenLocks[_lpToken][_withdrawer];
        tokenLock.amount = tokenLock.amount.add(amountLocked);
        tokenLock.initialAmount = tokenLock.initialAmount.add(amountLocked);
        tokenLock.lockDate = block.timestamp;
        tokenLock.unlockDate = _unlock_date;
        emit onDeposit(_lpToken, msg.sender, tokenLock.amount, tokenLock.lockDate, tokenLock.unlockDate);
    }
}

