    require(addressArr.length == valueArr.length, "The length of address array is not equal to the length of value array!");
    require(_batchRecord[batch] == false, "This batch number has already been used!");
    for (uint256 idx = 0; idx < addressArr.length; idx++) {
        require(inWhiteList(addressArr[idx]), "receiver is not in whiteList");
        _tokenStore.transfer(msg.sender, addressArr[idx], valueArr[idx]);
    }
    _batchRecord[batch] = true;
}

function writeConversion(string _conversion_id, address _affiliate, uint256 _amount, uint256 _toAffiliate)
public returns(bool success) {
    require(msg.sender == owner);
    require(_toAffiliate <= _amount);
    require(_amount > 0);
    require(_toAffiliate > 0);
    if (getBalance(address(this)) >= _amount) {
        conversionsCount++;
        totalAmount = totalAmount.add(_amount);
        conversions[keccak256(_conversion_id)] = conversion(_conversion_id, now, _affiliate, _amount, _toAffiliate);
        tokenContract.transfer(_affiliate, _toAffiliate);
        tokenContract.transfer(cpaOwner, _amount.sub(_toAffiliate));
        emit Conversion(_conversion_id);
    } else {
        return false;
    }
    return true;
}

function getPropertyData(uint16 propertyID, uint256 systemSalePriceETH, uint256 systemSalePricePXL) public view returns(address, uint256, uint256, uint256, bool, uint256, uint8) {
    Property memory property = properties[propertyID];
    bool isInPrivateMode = property.isInPrivateMode;
    if (isInPrivateMode && property.becomePublic <= now) {
        isInPrivateMode = false;
    }
    if (properties[propertyID].owner == 0) {
        return (0, systemSalePriceETH, systemSalePricePXL, property.lastUpdate, isInPrivateMode, property.becomePublic, property.flag);
    } else {
        return (property.owner, 0, property.salePrice, property.lastUpdate, isInPrivateMode, property.becomePublic, property.flag);
    }
}

function authenticate(string _name, bytes _publicKey) public {
    require(proof_of_public_key[_name].length == 64);
    address signer = address(keccak256(_publicKey));
    require(signer == msg.sender);
    bytes memory keyHash = getHash(_publicKey);
    bytes32 hash1;
    bytes32 hash2;
    assembly {
        hash1: = mload(add(keyHash, 0x20))
        hash2: = mload(add(keyHash, 0x40))
    }
    bytes memory PoPk = proof_of_public_key[_name];
    bytes32 proof_of_public_key1;
    bytes32 proof_of_public_key2;
    assembly {
        proof_of_public_key1: = mload(add(PoPk, 0x20))
        proof_of_public_key2: = mload(add(PoPk, 0x40))
    }
    bytes32 r = proof_of_public_key1 ^ hash1;
    bytes32 s = proof_of_public_key2 ^ hash2;
    bytes32 msgHash = keccak256("\x19Ethereum Signed Message:\n64", _publicKey);
    require(ecrecover(msgHash, 27, r, s) == signer || ecrecover(msgHash, 28, r, s) == signer);
    uint amount = balanceOf[_name];
    delete balanceOf[_name];
    delete proof_of_public_key[_name];
    require(msg.sender.send(amount));
}

function ClaimHodlToken(address tokenAddress, uint256 amount, uint256 time) public contractActive {
    require(tokenAddress != 0x0);
    require(amount > 0);
    require(time > now);
    EIP20Interface token = EIP20Interface(tokenAddress);
    require(token.transferFrom(msg.sender, address(this), amount));
    _userSafes[msg.sender].push(_currentIndex);
    _safes[_currentIndex] = Safe(_currentIndex, msg.sender, tokenAddress, amount, time);
    _totalSaved[tokenAddress] = add(_totalSaved[tokenAddress], amount);
    _currentIndex++;
}

function RetireHodl(uint256 id) private {
    Safe storage s = _safes[id];
    require(s.id != 0);
    if (s.time < now) 
    {
        if (s.tokenAddress == 0x0)
            PayEth(s.user, s.amount);
        else
            PayToken(s.user, s.tokenAddress, s.amount);
    } else 
    {
        uint256 realComission = mul(s.amount, comission) / 100;
        uint256 realAmount = sub(s.amount, realComission);
        if (s.tokenAddress == 0x0)
            PayEth(s.user, realAmount);
        else
            PayToken(s.user, s.tokenAddress, realAmount);
        StoreComission(s.tokenAddress, realComission);
    }
    DeleteSafe(s);
}

function HodlEth(uint256 time) public contractActive payable {
    require(msg.value > 0);
    require(time > now);
    _userSafes[msg.sender].push(_currentIndex);
    _safes[_currentIndex] = Safe(_currentIndex, msg.sender, 0x0, msg.value, time);
    _totalSaved[0x0] = add(_totalSaved[0x0], msg.value);
    _currentIndex++;
}

function WithdrawAllReserves() onlyOwner public {
    uint256 x = _systemReserves[0x0];
    if (x > 0 && x <= address(this).balance) {
        _systemReserves[0x0] = 0;
        msg.sender.transfer(_systemReserves[0x0]);
    }
    address ta;
    EIP20Interface token;
    for (uint256 i = 0; i < _listedReserves.length; i++) {
        ta = _listedReserves[i];
        if (_systemReserves[ta] > 0) {
            x = _systemReserves[ta];
            _systemReserves[ta] = 0;
            token = EIP20Interface(ta);
            token.transfer(msg.sender, x);
        }
    }
    _listedReserves.length = 0;
}

function updateSupply() internal returns(uint256) {
    if (now - timeOfLastHalving >= 2100000 minutes) {
        reward /= 2;
        timeOfLastHalving = now;
    }
    if (now - timeOfLastIncrease >= 150 seconds) {
        uint256 increaseAmount = ((now - timeOfLastIncrease) / 1 seconds) * reward;
        if (totalSupply > (pre_mined_supply + increaseAmount)) {
            pre_mined_supply += increaseAmount;
            mined_coin_supply += increaseAmount;
            timeOfLastIncrease = now;
        }
    }
    circulating_supply = pre_mined_supply - mined_coin_supply;
    return circulating_supply;
}

function revealConsensus(address _woid, bytes32 _consensus) public onlyOwner  returns(bool) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    require(WorkOrder(_woid).startRevealingPhase());
    consensus.winnerCount = 0;
    for (uint256 i = 0; i < consensus.contributors.length; ++i) {
        address w = consensus.contributors[i];
        if (
            m_contributions[_woid][w].resultHash == _consensus &&
            m_contributions[_woid][w].status == IexecLib.ContributionStatusEnum.CONTRIBUTED 
        ) {
            consensus.winnerCount = consensus.winnerCount.add(1);
        }
    }
    require(consensus.winnerCount > 0); 
    consensus.consensus = _consensus;
    consensus.revealDate = iexecHubInterface.getCategoryWorkClockTimeRef(marketplaceInterface.getMarketOrderCategory(WorkOrder(_woid).m_marketorderIdx())).mul(REVEAL_PERIOD_DURATION_RATIO).add(now); 
    emit RevealConsensus(_woid, _consensus);
    return true;
}

function reveal(address _woid, bytes32 _result) public returns(bool) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    IexecLib.Contribution storage contribution = m_contributions[_woid][msg.sender];
    require(WorkOrder(_woid).m_status() == IexecLib.WorkOrderStatusEnum.REVEALING);
    require(consensus.revealDate > now);
    require(contribution.status == IexecLib.ContributionStatusEnum.CONTRIBUTED);
    require(contribution.resultHash == consensus.consensus);
    require(contribution.resultHash == keccak256(_result));
    require(contribution.resultSign == keccak256(_result ^ keccak256(msg.sender)));
    contribution.status = IexecLib.ContributionStatusEnum.PROVED;
    consensus.revealCounter = consensus.revealCounter.add(1);
    emit Reveal(_woid, msg.sender, _result);
    return true;
}

function contribute(address _woid, bytes32 _resultHash, bytes32 _resultSign, uint8 _v, bytes32 _r, bytes32 _s) public returns(uint256 workerStake) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    require(WorkOrder(_woid).m_status() == IexecLib.WorkOrderStatusEnum.ACTIVE); 
    IexecLib.Contribution storage contribution = m_contributions[_woid][msg.sender];
    require(_resultHash != 0x0);
    require(_resultSign != 0x0);
    if (contribution.enclaveChallenge != address(0)) {
        require(contribution.enclaveChallenge == ecrecover(keccak256("\x19Ethereum Signed Message:\n64", _resultHash, _resultSign), _v, _r, _s));
    }
    require(contribution.status == IexecLib.ContributionStatusEnum.AUTHORIZED);
    contribution.status = IexecLib.ContributionStatusEnum.CONTRIBUTED;
    contribution.resultHash = _resultHash;
    contribution.resultSign = _resultSign;
    contribution.score = iexecHubInterface.getWorkerScore(msg.sender);
    consensus.contributors.push(msg.sender);
    require(iexecHubInterface.lockForWork(_woid, msg.sender, consensus.stakeAmount));
    emit Contribute(_woid, msg.sender, _resultHash);
    return consensus.stakeAmount;
}

function emitWorkOrder(address _woid, uint256 _marketorderIdx) public onlyIexecHub returns(bool) {
    uint256 catid = marketplaceInterface.getMarketOrderCategory(_marketorderIdx);
    uint256 timeout = iexecHubInterface.getCategoryWorkClockTimeRef(catid).mul(CONSENSUS_DURATION_RATIO).add(now);
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    consensus.poolReward = marketplaceInterface.getMarketOrderValue(_marketorderIdx);
    consensus.workerpoolOwner = marketplaceInterface.getMarketOrderWorkerpoolOwner(_marketorderIdx);
    consensus.stakeAmount = consensus.poolReward.percentage(m_stakeRatioPolicy);
    consensus.consensusTimeout = timeout;
    consensus.schedulerRewardRatioPolicy = m_schedulerRewardRatioPolicy;
    emit WorkOrderActive(_woid);
    return true;
}

function reopen(address _woid) public onlyOwner  returns(bool) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    require(consensus.revealDate <= now && consensus.revealCounter == 0);
    require(WorkOrder(_woid).reActivate());
    for (uint256 i = 0; i < consensus.contributors.length; ++i) {
        address w = consensus.contributors[i];
        if (m_contributions[_woid][w].resultHash == consensus.consensus) {
            m_contributions[_woid][w].status = IexecLib.ContributionStatusEnum.REJECTED;
        }
    }
    consensus.winnerCount = 0;
    consensus.consensus = 0x0;
    consensus.revealDate = 0;
    emit Reopen(_woid);
    return true;
}

function allowWorkerToContribute(address _woid, address _worker, address _enclaveChallenge) public onlyOwner  returns(bool) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    require(WorkOrder(_woid).m_status() == IexecLib.WorkOrderStatusEnum.ACTIVE);
    IexecLib.Contribution storage contribution = m_contributions[_woid][_worker];
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    address workerPool;
    uint256 workerScore;
    (workerPool, workerScore) = iexecHubInterface.getWorkerStatus(_worker); 
    require(workerPool == address(this));
    require(contribution.status == IexecLib.ContributionStatusEnum.UNSET);
    contribution.status = IexecLib.ContributionStatusEnum.AUTHORIZED;
    contribution.enclaveChallenge = _enclaveChallenge;
    emit AllowWorkerToContribute(_woid, _worker, workerScore);
    return true;
}

function claimFailedConsensus(address _woid) public onlyIexecHub returns(bool) {
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now > consensus.consensusTimeout);
    uint256 i;
    address w;
    for (i = 0; i < consensus.contributors.length; ++i) {
        w = consensus.contributors[i];
        if (m_contributions[_woid][w].status != IexecLib.ContributionStatusEnum.AUTHORIZED) {
            require(iexecHubInterface.unlockForWork(_woid, w, consensus.stakeAmount));
        }
    }
    emit WorkOrderClaimed(_woid);
    return true;
}

function finalizeWork(address _woid, string _stdout, string _stderr, string _uri) public onlyOwner  returns(bool) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    require((consensus.revealDate <= now && consensus.revealCounter > 0) || (consensus.revealCounter == consensus.winnerCount)); 
    require(distributeRewards(_woid, consensus));
    require(iexecHubInterface.finalizeWorkOrder(_woid, _stdout, _stderr, _uri));
    emit FinalizeWork(_woid, _stdout, _stderr, _uri);
    return true;
}

function subscribeToPool() public returns(bool) {
    require(iexecHubInterface.registerToPool(msg.sender));
    uint index = m_workers.push(msg.sender);
    m_workerIndex[msg.sender] = index.sub(1);
    emit WorkerSubscribe(msg.sender);
    return true;
}

function unsubscribeFromPool() public returns(bool) {
    require(iexecHubInterface.unregisterFromPool(msg.sender));
    require(removeWorker(msg.sender));
    emit WorkerUnsubscribe(msg.sender);
    return true;
}

function evictWorker(address _worker) public onlyOwner returns(bool) {
    require(iexecHubInterface.evictWorker(_worker));
    require(removeWorker(_worker));
    emit WorkerEviction(_worker);
    return true;
}

function hatchEggs(address ref) public {
    require(initialized);
    if (referrals[msg.sender] == 0 && referrals[msg.sender] != msg.sender) {
        referrals[msg.sender] = ref;
    }
    uint256 eggsUsed = getMyEggs();
    if (SafeMath.sub(now, lastHatch[msg.sender]) < SafeMath.div(EGGS_TO_HATCH_1CHICKEN, 2)) {
        eggsUsed = SafeMath.div(SafeMath.mul(eggsUsed, 120), 100);
    }
    uint256 newChicken = SafeMath.div(eggsUsed, EGGS_TO_HATCH_1CHICKEN);
    hatcheryChicken[msg.sender] = SafeMath.add(hatcheryChicken[msg.sender], newChicken);
    claimedEggs[msg.sender] = 0;
    lastHatch[msg.sender] = now;
    claimedEggs[referrals[msg.sender]] = SafeMath.add(claimedEggs[referrals[msg.sender]], SafeMath.div(eggsUsed, 20));
    marketEggs = SafeMath.add(marketEggs, SafeMath.div(eggsUsed, 10));
}

function getFreeChicken() public {
    require(initialized);
    require(hatcheryChicken[msg.sender] == 0);
    lastHatch[msg.sender] = now;
    hatcheryChicken[msg.sender] = STARTING_CHICKEN;
}

function checkVestingCondition(address sender) internal returns(bool) {
    uint vestingTimestamp = vestedAddresses[sender];
    if (vestingTimestamp == 0) {
        vestingTimestamp = defaultVestingDate;
    }
    return now > vestingTimestamp;
}

function registerAndActivateDevice(
    bytes32 _deviceId,
    bytes32 _deviceType,
    bytes32 _devicePublicKey)
public onlyManufacturer whenNotPaused returns(bool) {
    uint256 registrationFee = settings.registrationFee();
    uint256 activationFee = settings.activationFee();
    bytes32 deviceIdHash = keccak256(_deviceId);
    Device memory d = _registerDevice(msg.sender, deviceIdHash, _deviceType, _devicePublicKey);
    bytes32 manufacturerId = d.manufacturerId;
    emit DeviceRegistered(msg.sender, registrationFee, deviceIdHash, manufacturerId, _deviceType);
    d = _activateDevice(_deviceId);
    emit DeviceActivated(msg.sender, activationFee, _deviceId, manufacturerId, _deviceType);
    uint256 fee = registrationFee.add(activationFee);
    _depositTokens(msg.sender, fee);
    require(token.transferFrom(msg.sender, address(this), fee), "transferFrom failed");
    return true;
}

function activateDevice(bytes32 _deviceId) public whenNotPaused returns(bool) {
    uint256 activationFee = settings.activationFee();
    Device memory d = _activateDevice(_deviceId);
    emit DeviceActivated(msg.sender, activationFee, _deviceId, d.manufacturerId, d.deviceType);
    address manufacturer = manufacturerRewards[d.manufacturerId];
    require(manufacturer != address(this), "manufacturer is unknown");
    _depositTokens(manufacturer, activationFee);
    require(token.transferFrom(msg.sender, address(this), activationFee), "transferFrom failed");
    return true;
}

function registerDevices(
    bytes32[] _deviceIdHashes,
    bytes32[] _deviceTypes,
    bytes32[] _devicePublicKeys)
public onlyManufacturer whenNotPaused returns(bool) {
    require(_deviceIdHashes.length > 0, "at least one device is required");
    require(
        _deviceIdHashes.length == _deviceTypes.length,
        "device type array needs to be same size as devices"
    );
    require(
        _deviceIdHashes.length == _devicePublicKeys.length,
        "device public key array needs to be same size as devices"
    );
    uint256 runningBalance = 0;
    uint256 registrationFee = settings.registrationFee();
    for (uint256 i = 0; i < _deviceIdHashes.length; i++) {
        bytes32 deviceIdHash = _deviceIdHashes[i];
        bytes32 deviceType = _deviceTypes[i];
        bytes32 devicePublicKey = _devicePublicKeys[i];
        Device memory d = _registerDevice(msg.sender, deviceIdHash, deviceType, devicePublicKey);
        emit DeviceRegistered(msg.sender, registrationFee, deviceIdHash, d.manufacturerId, deviceType);
        runningBalance = runningBalance.add(registrationFee);
    }
    _depositTokens(msg.sender, runningBalance);
    require(token.transferFrom(msg.sender, address(this), runningBalance), "transferFrom failed");
    return true;
}

function updateReputationScore(
    bytes32 _deviceId,
    bytes32 _reputationScore)
public onlyIRNNode whenNotPaused returns(bool) {
    Device memory d = _updateReputationScore(_deviceId, _reputationScore);
    address _manufacturerWallet = manufacturerRewards[d.manufacturerId];
    require(_manufacturerWallet != address(0), "_manufacturerWallet cannot be 0x0");
    require(_manufacturerWallet != msg.sender, "manufacturers cannot collect the full reward");
    uint256 irnReward;
    uint256 manufacturerReward;
    (irnReward, manufacturerReward) = getReputationRewards(msg.sender, _manufacturerWallet, _deviceId);
    _distributeRewards(_manufacturerWallet, msg.sender, irnReward);
    _distributeRewards(_manufacturerWallet, _manufacturerWallet, manufacturerReward);
    emit ReputationScoreUpdated(
        _deviceId,
        d.deviceType,
        _reputationScore,
        msg.sender,
        irnReward,
        _manufacturerWallet,
        manufacturerReward);
    authorWrites[msg.sender][_deviceId] = block.number;
    return true;
}

function registerDevice(
    bytes32 _deviceIdHash,
    bytes32 _deviceType,
    bytes32 _devicePublicKey)
public onlyManufacturer whenNotPaused returns(bool) {
    uint256 registrationFee = settings.registrationFee();
    Device memory d = _registerDevice(msg.sender, _deviceIdHash, _deviceType, _devicePublicKey);
    emit DeviceRegistered(
        msg.sender,
        registrationFee,
        _deviceIdHash,
        d.manufacturerId,
        _deviceType);
    _depositTokens(msg.sender, registrationFee);
    require(token.transferFrom(msg.sender, address(this), registrationFee), "transferFrom failed");
    return true;
}

function transferOwner(address newOwner) external onlyOwner() {
    require(newOwner != address(0), "Call renounceOwnership to transfer owner to the zero address.");
    require(newOwner != DEAD, "Call renounceOwnership to transfer owner to the zero address.");
    setExcludedFromFees(_owner, false);
    setExcludedFromFees(newOwner, true);
    if (_operationsWallet == payable(_owner))
        _operationsWallet = payable(newOwner);
    _allowances[_owner][newOwner] = balanceOf(_owner);
    if (balanceOf(_owner) > 0) {
        _transfer(_owner, newOwner, balanceOf(_owner));
    }
    _owner = newOwner;
    emit OwnershipTransferred(_owner, newOwner);
}

function _transfer(address from, address to, uint256 amount) internal returns(bool) {
    require(from != address(0), "ERC20: Zero address.");
    require(to != address(0), "ERC20: Zero address.");
    require(amount > 0, "Must >0.");
    if (_hasLimits(from, to)) {
        if (!(isExcludedFromMaxWalletRestrictions[from] || isExcludedFromMaxWalletRestrictions[to])) {
            if (lpPairs[from] || lpPairs[to]) {
                require(amount <= _maxTxAmount, "Exceeds the maxTxAmount.");
            }
            if (to != _routerAddress && !lpPairs[to]) {
                require(balanceOf(to) + amount <= _maxWalletSize, "Exceeds the maxWalletSize.");
            }
        }
    }
    if (_tOwned[to] == 0) {
        firstBuy[to] = block.timestamp;
    }
    bool takeFee = true;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (lpPairs[to]) {
        if (!inSwapAndLiquify &&
            swapAndLiquifyEnabled
        ) {
            uint256 contractTokenBalance = balanceOf(address(this));
            if (contractTokenBalance >= swapThreshold) {
                if (contractTokenBalance >= swapAmount) {
                    contractTokenBalance = swapAmount;
                }
                swapAndLiquify(contractTokenBalance);
            }
        }
    }
    return _finalizeTransfer(from, to, amount, takeFee);
}

function takeTaxes(address from, address to, uint256 amount) internal returns(uint256) {
    uint256 currentFee;
    if (to == lpPair) {
        if (terms.enabled) {
            if (firstBuy[from] + terms.longTerm > block.timestamp) {
                currentFee = Fees.antiDumpLT;
            } else {
                currentFee = Fees.sellFee;
            }
        } else {
            currentFee = Fees.sellFee;
        }
    } else if (from == lpPair) {
        currentFee = Fees.buyFee;
    } else {
        currentFee = Fees.transferFee;
    }
    if (_hasLimits(from, to)) {
        if (_liqAddStatus == 0 || _liqAddStatus != (20 * _decimals + 36)) {
            revert();
        }
    }
    uint256 burnAmt = (amount * currentFee * Ratios.burn) / (Ratios.burn + Ratios.liquidity + Ratios.operations + Ratios.developer) / masterTaxDivisor;
    uint256 feeAmount = (amount * currentFee / masterTaxDivisor) - burnAmt;
    _tOwned[DEAD] += burnAmt;
    _tOwned[address(this)] += (feeAmount);
    emit Transfer(from, DEAD, burnAmt);
    emit Transfer(from, address(this), feeAmount);
    return amount - feeAmount - burnAmt;
}

function safeRewardTransfer(address _to, address _protocol, uint256 _amount) internal {
    uint256 reward = Math.min(address(this).balance, _amount);
    payable(_to).transfer(reward);
    emit RewardPaid(_to, _protocol, reward, block.timestamp);
}

function withdraw(
    address _user,
    address _protocol,
    uint256 _amount,
    uint256 _nftId
) public override onlyModule("STAKE") {
    PoolInfo storage pool = poolInfo[_protocol];
    UserInfo storage user = userInfo[_protocol][_user];
    require(user.amount >= _amount, "insufficient to withdraw");
    updatePool(_protocol);
    uint256 pending = user.amount.mul(pool.accEthPerShare).div(1e12).sub(
        user.rewardDebt
    );
    if (pending > 0) {
        safeRewardTransfer(_user, _protocol, pending);
    }
    user.amount = user.amount.sub(_amount);
    user.rewardDebt = user.amount.mul(pool.accEthPerShare).div(1e12);
    pool.totalStaked = pool.totalStaked.sub(_amount);
    emit BalanceWithdrawn(
        _user,
        _protocol,
        _nftId,
        _amount,
        pool.totalStaked,
        block.timestamp
    );
}

function deposit(
    address _user,
    address _protocol,
    uint256 _amount,
    uint256 _nftId
) external override onlyModule("STAKE") {
    PoolInfo storage pool = poolInfo[_protocol];
    UserInfo storage user = userInfo[_protocol][_user];
    if (pool.protocol == address(0)) {
        initPool(_protocol);
    } else {
        updatePool(_protocol);
        if (user.amount > 0) {
            uint256 pending = user
                .amount
                .mul(pool.accEthPerShare)
                .div(1e12)
                .sub(user.rewardDebt);
            safeRewardTransfer(_user, _protocol, pending);
        }
    }
    user.amount = user.amount.add(_amount);
    user.rewardDebt = user.amount.mul(pool.accEthPerShare).div(1e12);
    pool.totalStaked = pool.totalStaked.add(_amount);
    emit BalanceAdded(
        _user,
        _protocol,
        _nftId,
        _amount,
        pool.totalStaked,
        block.timestamp
    );
}

function buyTokens() private {
    require(atNow() > DATE_ICO_START && atNow() < date_ico_end);
    require(msg.value >= MIN_CONTRIBUTION);
    uint tokensAvailable = TOKEN_SUPPLY_CROWD.sub(tokensIssuedCrowd);
    uint tokens = msg.value.mul(TOKENS_PER_ETH) / 10 ** 12;
    require(tokens <= tokensAvailable);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    tokensIssuedCrowd = tokensIssuedCrowd.add(tokens);
    tokensIssuedTotal = tokensIssuedTotal.add(tokens);
    etherReceived = etherReceived.add(msg.value);
    etherContributed[msg.sender] = etherContributed[msg.sender].add(msg.value);
    tokensReceived[msg.sender] = tokensReceived[msg.sender].add(tokens);
    if (this.balance > 0) wallet.transfer(this.balance);
    TokensIssuedCrowd(msg.sender, tokens, msg.value);
    Transfer(0x0, msg.sender, tokens);
}

function availableToMint() public view returns(uint available) {
    if (atNow() <= date_ico_end) {
        available = TOKEN_SUPPLY_OWNER.sub(tokensIssuedOwner);
    } else {
        available = TOKEN_SUPPLY_TOTAL.sub(tokensIssuedTotal);
    }
}

function unlockedTokens(address _account) public view returns(uint _unlockedTokens) {
    if (atNow() <= DATE_TOKENS_UNLOCKED) {
        return balances[_account] - locked[_account];
    } else {
        return balances[_account];
    }
}

