function transferOnBehalf(address _to, uint _amount, uint _nonce, uint8 _v, bytes32 _r, bytes32 _s) onlyStaker public returns(bool success) {
    uint256 fee;
    uint256 resultAmount;
    bytes32 hash = keccak256(_to, _amount, _nonce, address(this));
    address sender = ecrecover(hash, _v, _r, _s);
    require(lastUsedNonce[sender] < _nonce);
    require(_amount <= balances[sender]);
    fee = comissionList.calcTransfer(_amount);
    resultAmount = _amount.sub(fee);
    balances[sender] = balances[sender].sub(_amount);
    balances[_to] = balances[_to].add(resultAmount);
    balances[staker] = balances[staker].add(fee);
    lastUsedNonce[sender] = _nonce;
    emit Transfer(sender, _to, _amount);
    emit Transfer(sender, address(0), fee);
    return true;
}

function buy() payable {
    uint256 fee = (msg.value * 42 / 100000);
    if (msg.value < (buyPrice + fee)) throw; 
    uint256 amount = (msg.value - fee) / buyPrice;
    if (totalSupply + amount < totalSupply) throw; 
    if (balanceOf[msg.sender] + amount < balanceOf[msg.sender]) throw; 
    balanceOf[msg.sender] += amount;
    profit.transfer(fee);
    msg.sender.transfer(msg.value - fee - (amount * buyPrice)); 
    totalSupply += amount;
    if (buyPrice < maxBuyPrice) {
        buyPrice = buyPrice * 100015 / 100000;
        if (buyPrice > maxBuyPrice) buyPrice = maxBuyPrice;
        NewBuyPrice(buyPrice);
    }
    setSellPrice();
}

function sell(uint256 _amount) {
    if (balanceOf[msg.sender] < _amount) throw;
    uint256 ethAmount = sellPrice * _amount;
    uint256 fee = (ethAmount * 42 / 100000);
    profit.transfer(fee);
    msg.sender.transfer(ethAmount - fee);
    balanceOf[msg.sender] -= _amount;
    totalSupply -= _amount;
}

function burn(uint256 _value) returns(bool success) {
    if (balanceOf[msg.sender] < _value) throw; 
    balanceOf[msg.sender] -= _value; 
    totalSupply -= _value; 
    profit.transfer(((_value * (110000 - flame) / 100000)) * sellPrice);
    setSellPrice();
    Burn(msg.sender, _value);
    return true;
}

function burnFrom(address _from, uint256 _value) returns(bool success) {
    if (balanceOf[_from] < _value) throw; 
    if (_value > allowance[_from][msg.sender]) throw; 
    balanceOf[_from] -= _value; 
    totalSupply -= _value; 
    profit.transfer((_value * (110000 - flame) / 100000) * sellPrice);
    setSellPrice();
    Burn(_from, _value);
    return true;
}

function autoDistribute() payable public {
    require(distributeAmount > 0 &&
        balanceOf[publicityFunds] >= distributeAmount &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    if (msg.value > 0) publicityFunds.transfer(msg.value);
    balanceOf[publicityFunds] = balanceOf[publicityFunds].sub(distributeAmount);
    balanceOf[msg.sender] = balanceOf[msg.sender].add(distributeAmount);
    Transfer(publicityFunds, msg.sender, distributeAmount);
}

function destroyRemainingTokens() public onlyAdmin icoFinished icoNotPaused returns(uint) {
    require(msg.sender == owner && now > icoDeadLine);
    address toAddr = 0x0000000000000000000000000000000000000000;
    uint256 amountToBurn = balances[owner];
    if (amountToBurn > icoReserveSupply) {
        amountToBurn = amountToBurn.sub(icoReserveSupply);
    }
    balances[owner] = balances[owner].sub(amountToBurn);
    balances[toAddr] = balances[toAddr].add(amountToBurn);
    emit Transfer(msg.sender, toAddr, amountToBurn);
    return 1;
}

function IsLockAddress(address _adr) public view returns(bool) {
    for (uint i = 0; i < LockedAddresses.length; i++) {
        if (LockedAddresses[i].adr == _adr) {
            if (LockedAddresses[i].ExpireTime > block.timestamp) {
                return true;
            } else {
                return false;
            }
        }
    }
    return false;
}

function LockAddress(uint _days) external {
    for (uint i = 0; i < LockedAddresses.length; i++) {
        if (LockedAddresses[i].adr == msg.sender) {
            if (LockedAddresses[i].ExpireTime > block.timestamp) {
                LockedAddresses[i].ExpireTime = LockedAddresses[i].ExpireTime + _days * 24 * 3600;
            } else {
                LockedAddresses[i].ExpireTime = block.timestamp + _days * 24 * 3600;
            }
            return;
        }
    }
    LockedAddresses.push(LockedAddress(block.timestamp + _days * 24 * 3600, msg.sender));
}

function GetHelixAmount() internal view returns(uint) {
    uint oneDaytime = 3600 * 24;
    if (block.timestamp.sub(ReleaseTime) < oneDaytime * 30) {
        return 10; 
    }
    if (block.timestamp.sub(ReleaseTime) < oneDaytime * 60) {
        return 8; 
    }
    if (block.timestamp.sub(ReleaseTime) < oneDaytime * 90) {
        return 6; 
    }
    if (block.timestamp.sub(ReleaseTime) < oneDaytime * 120) {
        return 4; 
    }
    if (block.timestamp.sub(ReleaseTime) < oneDaytime * 150) {
        return 2; 
    }
    if (block.timestamp.sub(ReleaseTime) > oneDaytime * 150) {
        return 1; 
    }
}

function GetAddressExpTime(address _adr) external view returns(uint) {
    for (uint i = 0; i < LockedAddresses.length; i++) {
        if (LockedAddresses[i].adr == _adr) {
            return LockedAddresses[i].ExpireTime;
        }
    }
    return 0;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    if (whiteListAddress != 0x0) {
        require(WhiteList(whiteListAddress).canTransfer(msg.sender, _to));
    }
    return super.transfer(_to, _value);
}

function burnTokensAndWithdrawCards(uint256[] calldata _cardIds, address[] calldata _destinationAddresses) external nonReentrant {
    require(_cardIds.length == _destinationAddresses.length, 'you did not provide a destination address for each of the cards you wish to withdraw');
    require(_cardIds.length > 0, 'you must submit an array with at least one element');
    uint256 numTokensToBurn = _cardIds.length;
    require(balanceOf(msg.sender) >= numTokensToBurn.mul(cardInWei), 'you do not own enough tokens to withdraw this many ERC721 cards');
    _burn(msg.sender, numTokensToBurn.mul(cardInWei));
    for (uint i = 0; i < numTokensToBurn; i++) {
        uint256 cardToWithdraw = _cardIds[i];
        if (cardToWithdraw == 0) {
            cardToWithdraw = _popCard();
        } else {
            require(isCardInDeck(cardToWithdraw), 'this card is not in the deck');
            require(address(this) == cardCore.ownerOf(cardToWithdraw), 'the contract does not own this card');
            _removeFromDeck(cardToWithdraw);
        }
        cardCore.transferFrom(address(this), _destinationAddresses[i], cardToWithdraw);
        emit BurnTokenAndWithdrawCard(cardToWithdraw);
    }
}

function depositCardsAndMintTokens(uint256[] calldata _cardIds) external nonReentrant {
    require(_cardIds.length > 0, 'you must submit an array with at least one element');
    for (uint i = 0; i < _cardIds.length; i++) {
        uint256 cardToDeposit = _cardIds[i];
        require(msg.sender == cardCore.ownerOf(cardToDeposit), 'you do not own this card');
        require(cardCore.getApproved(cardToDeposit) == address(this), 'you must approve() this contract to give it permission to withdraw this card before you can deposit a card');
        cardCore.transferFrom(msg.sender, address(this), cardToDeposit);
        _pushCard(cardToDeposit);
        emit DepositCardAndMintToken(cardToDeposit);
    }
    _mint(msg.sender, (_cardIds.length).mul(cardInWei));
}

function withdraw(uint amount) public {
    if (tokens[0][msg.sender] < amount) revert("Cannot withdraw more than you have");
    tokens[0][msg.sender] = SafeMath.sub(tokens[0][msg.sender], amount);
    msg.sender.transfer(amount);
    emit Withdraw(0, msg.sender, amount, tokens[0][msg.sender]);
}

function migrateFunds(address[] tokens_) public {
    require(nextContract != address(0));
    EtherDEX newExchange = findNewExchangeContract();
    migrateEther(newExchange);
    migrateTokens(newExchange, tokens_);
    emit FundsMigrated(msg.sender);
}

function migrateTokens(EtherDEX newExchange, address[] tokens_) private {
    for (uint16 n = 0; n < tokens_.length; n++) {
        address token = tokens_[n];
        require(token != address(0));
        uint tokenAmount = tokens[token][msg.sender];
        if (tokenAmount == 0) {
            continue;
        }
        if (!ERC20(token).approve(newExchange, tokenAmount)) {
            revert();
        }
        tokens[token][msg.sender] = 0;
        newExchange.depositTokenForUser(token, tokenAmount, msg.sender);
    }
}

function depositToken(address token, uint amount) public {
    if (token == 0) revert("Cannot deposit ETH with depositToken method");
    if (!ERC20(token).transferFrom(msg.sender, this, amount)) revert("You didn't call approve method on Token contract");
    tokens[token][msg.sender] = SafeMath.add(tokens[token][msg.sender], amount);
    emit Deposit(token, msg.sender, amount, tokens[token][msg.sender]);
}

function depositEtherForUser(address _user) public payable {
    require(!isContractDeprecated);
    require(_user != address(0));
    require(msg.value > 0);
    EtherDEX caller = EtherDEX(msg.sender);
    require(caller.contractVersion() > 0); 
    tokens[0][_user] = tokens[0][_user].add(msg.value);
}

function depositTokenForUser(address _token, uint _amount, address _user) public {
    require(!isContractDeprecated);
    require(_token != address(0));
    require(_user != address(0));
    require(_amount > 0);
    EtherDEX caller = EtherDEX(msg.sender);
    require(caller.contractVersion() > 0); 
    if (!ERC20(_token).transferFrom(msg.sender, this, _amount)) {
        revert();
    }
    tokens[_token][_user] = tokens[_token][_user].add(_amount);
}

function doPayments() public {
    Recipient storage rec = recs[msg.sender];
    require(rec.balance >= 1e12);
    rec.addr.transfer(rec.balance);
    emit Payment(rec.addr, rec.balance);
    rec.received = (rec.received).add(rec.balance);
    rec.balance = 0;
}

