function rescueToken(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 && addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e18);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function transfer(address _to, uint256 _value) public onlyPayloadSize(2) returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    require(transfersEnabled);
    if (msg.sender == addressFundTeam) {
        require(checkVesting(_value, now) > 0);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function checkVesting(uint256 _value, uint256 _currentTime) public view returns(uint8 period) {
    period = 0;
    require(endTimeIco <= _currentTime);
    if (endTimeIco + 26 weeks <= _currentTime && _currentTime < endTimeIco + 52 weeks) {
        period = 1;
        require(balances[addressFundTeam].sub(_value) >= fundTeam.mul(95).div(100));
    }
    if (endTimeIco + 52 weeks <= _currentTime && _currentTime < endTimeIco + 78 weeks) {
        period = 2;
        require(balances[addressFundTeam].sub(_value) >= fundTeam.mul(85).div(100));
    }
    if (endTimeIco + 78 weeks <= _currentTime && _currentTime < endTimeIco + 104 weeks) {
        period = 3;
        require(balances[addressFundTeam].sub(_value) >= fundTeam.mul(65).div(100));
    }
    if (endTimeIco + 104 weeks <= _currentTime && _currentTime < endTimeIco + 130 weeks) {
        period = 4;
        require(balances[addressFundTeam].sub(_value) >= fundTeam.mul(35).div(100));
    }
    if (endTimeIco + 130 weeks <= _currentTime) {
        period = 5;
        require(balances[addressFundTeam].sub(_value) >= 0);
    }
}

function putIntoPackage(uint256 _tokenId, uint256 _ratio, address _issuer) onlyAdmins() public {
    Issuer issuer = Issuer(_issuer);
    require(issuer.ownerOf(_tokenId) == msg.sender);
    issuer.transferFrom(msg.sender, address(this), _tokenId);
    if (packageSize >= package.length) {
        package.push(Package(_tokenId, _ratio, _issuer));
    } else {
        package[packageSize].tokenId = _tokenId;
        package[packageSize].ratio = _ratio;
        package[packageSize].issuer = _issuer;
    }
    packageSize += 1;
    sigmaRatio += _ratio;
}

function rollDice(uint256 _tokenId) public {
    require(msg.sender == ownerOfToken[_tokenId]);
    require(packageSize > 0);
    _transfer(msg.sender, owner, _tokenId);
    uint256 result = uint(keccak256(block.timestamp + block.difficulty)); 
    result %= sigmaRatio;
    uint256 rt;
    for (uint256 i = 0; i < packageSize; i++) {
        if (result >= package[i].ratio) {
            result -= package[i].ratio;
        } else {
            rt = i;
            break;
        }
    }
    Issuer issuer = Issuer(package[rt].issuer);
    issuer.transfer(msg.sender, package[rt].tokenId);
    sigmaRatio -= package[rt].ratio;
    package[rt] = package[packageSize - 1];
    packageSize -= 1;
    emit RollDice(msg.sender, package[rt].issuer, package[rt].tokenId);
}

function transfer(address _to, uint _value, bytes _data) external {
    require(_value > 0);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value, _data);
}

