function() public payable {
    require(stage != Stages.ENDED);
    require(msg.value >= minContribution);
    require(!stopped && msg.sender != owner);
    ContributionAmount = ((msg.value).mul(priceFactor.mul(1000))); 
    if (stage == Stages.PREICO && now <= preico_enddate) {
        dis = getCurrentTokenPricepreICO(ContributionAmount);
        _price_token = _price_token.sub(_price_token.mul(dis).div(100));
        y();
    } else if (stage == Stages.ICO) {
        dis = getCurrentTokenPriceICO(ContributionAmount);
        _price_token = _price_token.sub(_price_token.mul(dis).div(100));
        y();
    } else {
        revert();
    }
}

function getCurrentTokenPriceICO(uint256 individuallyContributedEtherInWei) private returns(uint) {
    require(individuallyContributedEtherInWei >= (minContribution.mul(ETH_DECIMALS)));
    uint disc;
    bonusCalculationFactor = (block.timestamp.sub(ico_startdate)).div(604800); 
    if (bonusCalculationFactor == 0)
        disc = 30; 
    else if (bonusCalculationFactor == 1)
        disc = 20; 
    else if (bonusCalculationFactor == 2)
        disc = 10; 
    else if (bonusCalculationFactor == 3)
        disc = 5; 
    else if (bonusCalculationFactor > 3)
        disc = 0; 
    return disc;
}

function getCurrentTokenPricepreICO(uint256 individuallyContributedEtherInWei) private returns(uint) {
    require(individuallyContributedEtherInWei >= (minContribution.mul(ETH_DECIMALS)));
    uint disc;
    bonusCalculationFactor = (block.timestamp.sub(preico_startdate)).div(604800); 
    if (bonusCalculationFactor == 0)
        disc = 30; 
    else if (bonusCalculationFactor == 1)
        disc = 20; 
    else if (bonusCalculationFactor == 2)
        disc = 10; 
    else if (bonusCalculationFactor == 3)
        disc = 5; 
    return disc;
}

function refund(address buyer, uint signId, uint value) external onlyOperator {
    require(refunds[signId] == address(0));
    refunds[signId] = buyer;
    buyer.transfer(value);
    emit Refund(buyer, signId, value);
}

function transferToLimited(address _from, address _to, uint _amount, uint8 _limitType) internal {
    require((_limitType >= limitTeamType) && (_limitType <= limitBranchType));
    require((limited_balances[_to].limitType == 0) || (limited_balances[_to].limitType == _limitType));
    doTransfer(_from, _to, _amount);
    uint previousLimitedBalanceInitial = limited_balances[_to].initial;
    require(previousLimitedBalanceInitial + _amount >= previousLimitedBalanceInitial); 
    limited_balances[_to].initial = previousLimitedBalanceInitial + _amount;
    limited_balances[_to].limitType = _limitType;
}

function doTransfer(address _from, address _to, uint _amount) internal {
    if (_amount == 0) {
        emit Transfer(_from, _to, _amount); 
        return;
    }
    require((_to != 0) && (_to != address(this)));
    uint previousBalanceFrom = balanceOf(_from);
    require(previousBalanceFrom >= _amount);
    if (controller != 0) {
        require(TokenController(controller).onTransfer(_from, _to, _amount));
    }
    balances[_from] = previousBalanceFrom - _amount;
    if (limited_balances[_from].limitType > 0) {
        require(limited_balances[_from].limitType <= limitBranchType);
        uint minimumLimit = (limited_balances[_from].initial * limits[limited_balances[_from].limitType - 1]) / 100;
        require(balances[_from] >= minimumLimit);
    }
    uint previousBalanceTo = balanceOf(_to);
    require(previousBalanceTo + _amount >= previousBalanceTo); 
    balances[_to] = previousBalanceTo + _amount;
    emit Transfer(_from, _to, _amount);
}

function approve(address _spender, uint _amount) public returns(bool success) {
    require(transfersEnabled);
    if (controller != 0) {
        require(TokenController(controller).onApprove(msg.sender, _spender, allowed[msg.sender][_spender], _amount));
    }
    allowed[msg.sender][_spender] = _amount;
    emit Approval(msg.sender, _spender, _amount);
    return true;
}

function giveKarma(uint _upOrDown, string _coinName, string _coinSymbol) payable public {
    require(msg.value >= giveKarmaFee);
    uint upVote = 0;
    uint downVote = 0;
    if (_upOrDown == 1) {
        downVote = 1;
    } else if (_upOrDown == 2) {
        upVote = 1;
    }
    uint id;
    if (coinsKarmaCreated[_coinSymbol] == 0) {
        id = coinkarma.push(CoinsKarma(_coinName, _coinSymbol, 0, 0, true)) - 1;
        emit NewCoinsKarma(id, _coinName, _coinSymbol, 0, 0, true);
        coinsKarmaMap[_coinSymbol] = id;
        coinsKarmaCreated[_coinSymbol] = 1;
    } else {
        id = coinsKarmaMap[_coinSymbol];
    }
    if (karmaVoterCreated[msg.sender][id] == 0) {
        uint idd = karmavoters.push(KarmaVotes(id, msg.sender, upVote, downVote, now, true)) - 1;
        emit NewKarmaVoter(idd, id, msg.sender, upVote, downVote, now, true);
        karmaVoterCreated[msg.sender][id] = 1;
        karmaVoterMap[msg.sender][id] = idd;
        coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaUp = coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaUp + upVote;
        coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaDown = coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaDown + downVote;
    } else {
        if (karmavoters[karmaVoterMap[msg.sender][id]].up > 0) {
            coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaUp = coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaUp - 1;
        } else if (karmavoters[karmaVoterMap[msg.sender][id]].down > 0) {
            coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaDown = coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaDown - 1;
        }
        karmavoters[karmaVoterMap[msg.sender][id]].up = upVote;
        karmavoters[karmaVoterMap[msg.sender][id]].down = downVote;
        karmavoters[karmaVoterMap[msg.sender][id]].voteTime = now;
        coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaUp = coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaUp + upVote;
        coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaDown = coinkarma[coinsKarmaMap[_coinSymbol]].totalKarmaDown + downVote;
    }
}

function viewKarmaVotesBySymbol(string _coinSymbol, address _userAddress) view public returns(uint, address, uint, uint, uint, string) {
    uint getCoinsId = coinsKarmaMap[_coinSymbol];
    if (karmavoters[karmaVoterMap[_userAddress][getCoinsId]].exists == true) {
        return (karmavoters[karmaVoterMap[_userAddress][getCoinsId]].coinsKarmaId, karmavoters[karmaVoterMap[_userAddress][getCoinsId]].voterAddress, karmavoters[karmaVoterMap[_userAddress][getCoinsId]].up, karmavoters[karmaVoterMap[_userAddress][getCoinsId]].down, karmavoters[karmaVoterMap[_userAddress][getCoinsId]].voteTime, _coinSymbol);
    } else {
        return (0, 0x0, 0, 0, 0, "");
    }
}

function thawSomeTokens(address owner, uint requiredAmount)
private {
    if (balances[owner] >= requiredAmount)
        return; 
    require(availableBalanceOf(owner) >= requiredAmount);
    for (uint cellIndex = 0; cellIndex < frozenBalances[owner].length; ++cellIndex) {
        if (isSpendableFrozenCell(owner, cellIndex)) {
            uint amount = frozenBalances[owner][cellIndex].amount;
            frozenBalances[owner][cellIndex].amount = 0;
            balances[owner] = balances[owner].add(amount);
        }
    }
    assert(balances[owner] >= requiredAmount);
}

function transferFrom(address _from, address _to, uint256 _value)
public
payloadSizeIs(3 * 32)
returns(bool) {
    thawSomeTokens(_from, _value);
    return super.transferFrom(_from, _to, _value);
}

function transfer(address _to, uint256 _value)
public
payloadSizeIs(2 * 32)
returns(bool) {
    thawSomeTokens(msg.sender, _value);
    return super.transfer(_to, _value);
}

function burn(uint256 _amount)
public
payloadSizeIs(1 * 32)
returns(bool) {
    thawSomeTokens(msg.sender, _amount);
    return super.burn(_amount);
}

function isSpendableFrozenCell(address owner, uint cellIndex)
private
view
returns(bool) {
    FrozenCell storage cell = frozenBalances[owner][cellIndex];
    if (uint(cell.thawTS) > getTime())
        return false;
    if (0 == cell.amount) 
        return false;
    if (decodeKYCFlag(cell.isKYCRequired) && !m_KYCProvider.isKYCPassed(owner))
        return false;
    return true;
}

function buy() payable {
    uint thisBalance = ERC20Token.balanceOf(this);
    require(thisBalance > 0 && sale);
    uint countToken;
    uint countBonusToken;
    countToken = msg.value / price;
    require(countToken > 0);
    if (thisBalance > countToken) {
        thisBalance -= countToken;
        countBonusToken = (countToken / bonusLine) * bonusSize;
        if (countBonusToken > 0 && thisBalance <= countBonusToken) {
            countBonusToken = thisBalance;
        }
    } else {
        countToken = thisBalance;
    }
    require(ERC20Token.transfer(msg.sender, countToken + countBonusToken));
    msg.sender.transfer(msg.value - (countToken * price));
    Buy(msg.sender, addressERC20Token, countToken, countBonusToken, msg.value);
}

