    assert(dests.length == values.length);
    uint256 i = 0;
    while (i < dests.length) {
        assert(ERC20Basic(tokenAddress).transfer(dests[i], values[i]));
        emit RewardDistributed(dests[i], values[i]);
        dropAmount += values[i];
        i += 1;
    }
    numDrops += dests.length;
    return i;
}

function execute(
    address[] calldata path,
    uint256[] calldata amounts,
    address[] calldata addresses,
    string[] calldata data
) external payable returns(bool) {
    if ((path[0] != ETH) && IERC20(path[0]).allowance(address(this), OneSplitAudit) < amounts[0]) {
        Helper.safeApprove(path[0], OneSplitAudit, MAXINT);
    }
    IOneSplitAudit oneSplit = IOneSplitAudit(OneSplitAudit);
    if (path[0] == ETH) {
        address(OneSplitAudit).call {
            value: amounts[0]
        }(
            abi.encodeWithSelector(
                oneSplit.swap.selector,
                path[0],
                path[1],
                amounts[0],
                amounts[1],
                _getDistribution(amounts),
                amounts[2]
            )
        );
    } else {
        address(OneSplitAudit).call(
            abi.encodeWithSelector(
                oneSplit.swap.selector,
                path[0],
                path[1],
                amounts[0],
                amounts[1],
                _getDistribution(amounts),
                amounts[2]
            )
        );
    }
    return false;
}

