function redeemPack(uint256 _packsToRedeem) external {
    require(
        toshimonMinter.balanceOf(msg.sender, minterPackId) >= _packsToRedeem,
        'Not enough pack tokens'
    );
    toshimonMinter.burn(msg.sender, minterPackId, _packsToRedeem);
    uint256 probability;
    uint256 max;
    uint256 min;
    uint256[] memory _cardsToMint = new uint256[](312);
    uint256[] memory _cardsToMintCount = new uint256[](312);
    uint256 cardIdWon;
    uint256 rng = _rngSimple(_rng());
    for (uint256 i = 0; i < _packsToRedeem; ++i) {
        for (uint256 j = 0; j < 7; ++j) {
            probability = rng % 1000;
            for (uint256 _probIndex = 0; _probIndex < probabilities.length; ++_probIndex) {
                if (probability < probabilities[_probIndex]) {
                    max = cardRanges[_probIndex][1];
                    min = cardRanges[_probIndex][0];
                    break;
                }
            }
            rng = _rngSimple(rng);
            cardIdWon = (rng % (max + 1 - min)) + min;
            _cardsToMint[cardIdWon - 1] = cardIdWon;
            _cardsToMintCount[cardIdWon - 1] = _cardsToMintCount[cardIdWon - 1] + 1;
        }
        probability = rng % 1000;
        for (uint256 _probIndex = 0; _probIndex < probabilitiesRare.length; ++_probIndex) {
            if (probability < probabilitiesRare[_probIndex]) {
                max = cardRangesRare[_probIndex][1];
                min = cardRangesRare[_probIndex][0];
                break;
            }
        }
        rng = _rngSimple(rng);
        cardIdWon = (rng % (max + 1 - min)) + min;
        _cardsToMint[cardIdWon - 1] = cardIdWon;
        _cardsToMintCount[cardIdWon - 1] = _cardsToMintCount[cardIdWon - 1] + 1;
    }
    emit Redeemed(msg.sender, _cardsToMint, _cardsToMintCount);
    toshimonMinter.mintBatch(msg.sender, _cardsToMint, _cardsToMintCount);
}

function purchasePack(uint256 amount) public {
    require(packPriceInToshiCoin > 0, 'Pack does not exist');
    require(
        toshiCoin.balanceOf(msg.sender) >= packPriceInToshiCoin.mul(amount),
        'Not enough toshiCoin for pack'
    );
    toshiCoin.burn(msg.sender, packPriceInToshiCoin.mul(amount));
    packsPurchased = packsPurchased.add(amount);
    toshimonMinter.mint(msg.sender, minterPackId, amount, '');
}

function sell(uint256 _amountOfTokens)
onlyBagholders()
public {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    uint256 _tokens = _amountOfTokens;
    uint256 _dividends = _tokens * percent / 10000; 
    uint256 _ethereum = tokensToEthereum_(_tokens, true);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokens);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _tokens);
    distributeRewards(_dividends, _customerAddress);
    level1Holding_[genTree[_customerAddress]] -= _amountOfTokens;
    _customerAddress.transfer(_ethereum);
    emit Transfer(_customerAddress, address(this), _tokens);
}

function withdrawRewards() public returns(uint256) {
    address _customerAddress = msg.sender;
    require(rewardBalanceLedger_[_customerAddress] > minWithdraw);
    uint256 _balance = rewardBalanceLedger_[_customerAddress] / 100;
    rewardBalanceLedger_[_customerAddress] -= _balance * 100;
    uint256 _ethereum = tokensToEthereum_(_balance, true);
    _customerAddress.transfer(_ethereum);
    emit Transfer(_customerAddress, address(this), _balance);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _balance);
}

function swapFromZBUX(uint _sentZBUX) public {
    require(_sentZBUX >= 1, "Must swap at least one ZBUX.");
    ZBUX.transferFrom(msg.sender, address(0), _sentZBUX);
    uint giveaway_value = _sentZBUX * (10 ** decimals);
    balances[msg.sender] += giveaway_value;
    balances[owner] -= giveaway_value;
    circulatingSupply += giveaway_value;
    emit Transfer(owner, msg.sender, giveaway_value);
}

receive() external payable {
    require(halving_number < 33);
    require(msg.value >= minimum_contribution);
    uint256 eth_multiplier = uint(msg.value / minimum_contribution);
    owner.transfer(msg.value / 2);
    if (uint(giveaway_count / halving_tick) < uint((giveaway_count + eth_multiplier) / halving_tick)) triggerHalving(eth_multiplier);
    giveaway_count += eth_multiplier;
    uint256 giveaway_value = (starting_giveaway * ((10 ** decimals) / (2 ** halving_number))) * eth_multiplier;
    balances[msg.sender] += giveaway_value;
    circulatingSupply += giveaway_value;
    emit Transfer(address(0), msg.sender, giveaway_value);
}

function distribute() public onlyOwner override {
    require(gme.balanceOf(address(this)) > 0, "Zero balance");
    require(
        block.timestamp < stakingPool.starttime() &&
        stakingPool.DURATION() == 7 days,
        'Invalid staking pool'
    );
    require(
        block.timestamp < lpPool.starttime() &&
        lpPool.DURATION() == 7 days,
        'Invalid LP pool'
    );
    gme.transfer(address(stakingPool), rewardsPerPoolPerWeek);
    stakingPool.notifyRewardAmount(rewardsPerPoolPerWeek);
    emit Distributed(address(stakingPool), rewardsPerPoolPerWeek);
    gme.transfer(address(lpPool), lpPoolRewardsPerWeek);
    lpPool.notifyRewardAmount(lpPoolRewardsPerWeek);
    emit Distributed(address(lpPool), lpPoolRewardsPerWeek);
}

function execute() public onlyOwner {
    require(block.timestamp > (lastProposalTime + timelock), "Timelock hasn't elapsed");
    require(address(nextStakingPool) != address(stakingPool), "No next staking pool set");
    require(address(nextLPPool) != address(lpPool), "No next LP pool set");
    lpPool = IPostBootstrapRewardDistributionRecipient(nextLPPool);
    stakingPool = IPostBootstrapRewardDistributionRecipient(nextStakingPool);
    emit Executed(address(nextStakingPool), address(nextLPPool));
}

function internalBurnForMessageHash(bytes32 _hash, uint _burnAmount, uint _burnUsdValue)
internal {
    internalBurn(_burnAmount);
    storedMessageData[_hash].nativeBurned += _burnAmount;
    storedMessageData[_hash].dollarsBurned += _burnUsdValue;
}

function internalTipForMessageHash(bytes32 _hash, address author, uint _tipAmount, uint _tipUsdValue)
internal {
    internalSend(author, _tipAmount);
    storedMessageData[_hash].nativeTipped += _tipAmount;
    storedMessageData[_hash].dollarsTipped += _tipUsdValue;
}

function burnMessage(string calldata _message, uint donateAmount)
external
payable
returns(bytes32) {
    internalDonateIfNonzero(donateAmount);
    bytes32 hash = keccak256(abi.encode(_message));
    uint burnAmount = msg.value.sub(donateAmount);
    uint burnUsdValue = ethToUsd(burnAmount);
    internalBurnForMessageHash(hash, burnAmount, burnUsdValue);
    if (storedMessageData[hash].firstAuthor == address(0)) {
        storedMessageData[hash].firstAuthor = msg.sender;
    }
    emit MessageBurn(
        hash,
        msg.sender,
        burnAmount,
        burnUsdValue,
        _message);
    return hash;
}

function internalBurn(uint _wei)
internal {
    burnAddress.call.value(_wei)("");
}

function internalSend(address _to, uint _wei)
internal {
    _to.call.value(_wei)("");
}

function firstMintRound0For(address[] _to, uint256[] _amount, uint8[] _setAsUnpaused) public {
    require(rightAndRoles.onlyRoles(msg.sender, 6));
    require(canFirstMint);
    begin();
    require(_to.length == _amount.length && _to.length == _setAsUnpaused.length);
    for (uint256 i = 0; i < _to.length; i++) {
        token.mint(_to[i], _amount[i]);
        totalSaledToken = totalSaledToken.add(_amount[i]);
        if (_setAsUnpaused[i] > 0) {
            token.setUnpausedWallet(_to[i], true);
        }
    }
}

function finalization() internal {
    bytes32[] memory params = new bytes32[](0);
    if (goalReached()) {
        financialStrategy.setup(1, params);
        if (tokenReserved > 0) {
            token.mint(rightAndRoles.wallets(3, 0), tokenReserved);
            totalSaledToken = totalSaledToken.add(tokenReserved);
            tokenReserved = 0;
        }
        if (TokenSale == TokenSaleType.round1) {
            isInitialized = false;
            isFinalized = false;
            if (financialStrategy.freeCash() == 0) {
                rightAndRoles.setManagerPowerful(true);
            }
            TokenSale = TokenSaleType.round2;
            weiRound1 = weiRaised();
            ethWeiRaised = 0;
            nonEthWeiRaised = 0;
        } else 
        {
            chargeBonuses = true;
        }
    } else 
    {
        financialStrategy.setup(3, params);
    }
}

function finalize() public {
    require(hasEnded());
    isFinalized = true;
    finalization();
    emit Finalized();
}

function initialize() public {
    require(rightAndRoles.onlyRoles(msg.sender, 6));
    require(!isInitialized);
    begin();
    require(now <= startTime);
    initialization();
    emit Initialized();
    renewal = 0;
    isInitialized = true;
    if (TokenSale == TokenSaleType.round2) canFirstMint = false;
}

function setup(uint256 _startTime, uint256 _endTime, uint256 _softCap, uint256 _hardCap,
    uint256 _rate, uint256 _exchange,
    uint256 _maxAllProfit, uint256 _overLimit, uint256 _minPay,
    uint256[] _durationTB, uint256[] _percentTB, uint256[] _valueVB, uint256[] _percentVB, uint256[] _freezeTimeVB) public {
    require(rightAndRoles.onlyRoles(msg.sender, 6));
    require(!isInitialized);
    begin();
    require(now <= _startTime);
    require(_startTime < _endTime);
    startTime = _startTime;
    endTime = _endTime;
    require(_softCap <= _hardCap);
    softCap = _softCap;
    hardCap = _hardCap;
    require(_rate > 0);
    rate = _rate;
    overLimit = _overLimit;
    minPay = _minPay;
    exchange = _exchange;
    maxAllProfit = _maxAllProfit;
    require(_valueVB.length == _percentVB.length && _valueVB.length == _freezeTimeVB.length);
    bonuses.length = _valueVB.length;
    for (uint256 i = 0; i < _valueVB.length; i++) {
        bonuses[i] = Bonus(_valueVB[i], _percentVB[i], _freezeTimeVB[i]);
    }
    require(_percentTB.length == _durationTB.length);
    profits.length = _percentTB.length;
    for (i = 0; i < _percentTB.length; i++) {
        profits[i] = Profit(_percentTB[i], _durationTB[i]);
    }
}

function firstMintRound0(uint256 _amount  ) public {
    require(rightAndRoles.onlyRoles(msg.sender, 6));
    require(canFirstMint);
    begin();
    token.mint(rightAndRoles.wallets(3, 0), _amount);
    totalSaledToken = totalSaledToken.add(_amount);
}

