function getProfitPercentForData(uint256 _timeNow) public constant returns(uint256) {
    uint256 allDuration;
    for (uint8 i = 0; i < profits.length; i++) {
        allDuration = allDuration.add(profits[i].duration);
        if (_timeNow < startTime.add(allDuration)) {
            return profits[i].percent;
        }
    }
    return 0;
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = (now > startTime && now < endTime.add(renewal));
    bool nonZeroPurchase = msg.value >= minPay;
    bool withinCap = msg.value <= hardCap.sub(weiRaised()).add(overLimit);
    return withinPeriod && nonZeroPurchase && withinCap && isInitialized && !isFinalized && !isPausedCrowdsale;
}

function hasEnded() public view returns(bool) {
    bool isAdmin = rightAndRoles.onlyRoles(msg.sender, 6);
    bool timeReached = now > endTime.add(renewal);
    bool capReached = weiRaised() >= hardCap;
    return (timeReached || capReached || (isAdmin && goalReached())) && isInitialized && !isFinalized;
}

function tokenUnpause() external {
    require(rightAndRoles.onlyRoles(msg.sender, 2) ||
        (now > endTime.add(renewal).add(USER_UNPAUSE_TOKEN_TIMEOUT) && TokenSale == TokenSaleType.round2 && isFinalized && goalReached()));
    token.setPause(false);
}

function withdraw(bytes calldata _proof, bytes32 _root, bytes32 _nullifierHash, address payable _recipient, address payable _relayer, uint256 _fee, uint256 _refund) external payable nonReentrant {
    require(_fee <= denomination, "Fee exceeds transfer value");
    require(!nullifierHashes[_nullifierHash], "The note has been already spent");
    require(isKnownRoot(_root), "Cannot find your merkle root"); 
    require(verifier.verifyProof(_proof, [uint256(_root), uint256(_nullifierHash), uint256(_recipient), uint256(_relayer), _fee, _refund]), "Invalid withdraw proof");
    nullifierHashes[_nullifierHash] = true;
    _processWithdraw(_recipient, _relayer, _fee, _refund);
    emit Withdrawal(_recipient, _nullifierHash, _relayer, _fee);
}

function burn(uint amount, address adminAddress) external payable {
    require(admins[adminAddress].isAdmin == true, 'only admin');
    require(msg.value >= transferFeeMinimum, "Transfer Fee needs to be higher than minimum");
    TransferHelper.safeTransferFrom(
        FDCContract, msg.sender, address(this), amount
    );
    TransferHelper.safeTransferETH(
        adminAddress, msg.value
    );
    uint transferRate = amount / 10;
    require(transferRate > 0, "Transfer Rate needs to be higher than the minimum");
    require(amount > transferRate, "Amount sent needs to be higher than the Transfer Rate");
    uint sendValue = amount - transferRate;
    if (feeModifier > 0) {
        uint fee = amount / feeModifier;
        require(fee > 0, "Fee needs to be higher than the minimum");
        TransferHelper.safeTransfer(
            FDCContract, adminAddress, fee
        );
        sendValue -= fee;
    }
    require((admins[adminAddress].limit >= sendValue), 'not enough admin limit');
    admins[adminAddress].limit -= sendValue;
    admins[adminAddress].approvedLimit += sendValue;
    balanceAdd(msg.sender, sendValue);
    emit TransferBridge(
        msg.sender,
        adminAddress,
        sendValue
    );
}

function transferAndFreeze(address target, uint256 value, uint unlockStartTime, uint unlockIntervalUnit, uint unlockInterval, uint unlockPercent) external onlyOwner freezeOutCheck(target, 0) {
    require(value > 0);
    require(frozenAccount[target].isValue == false);
    require(unlockStartTime > now);
    require(unlockInterval > 0);
    require(unlockPercent > 0 && unlockPercent <= 100);
    _transfer(msg.sender, target, value);
    uint unlockIntervalSecond = toSecond(unlockIntervalUnit, unlockInterval);
    frozenAccount[target] = Fund(value, unlockStartTime, unlockIntervalSecond, unlockPercent, true);
    emit FrozenFunds(target, value, unlockStartTime, unlockIntervalUnit, unlockInterval, unlockPercent);
}

function freezeAccount(address target, uint value, uint unlockStartTime, uint unlockIntervalUnit, uint unlockInterval, uint unlockPercent) external onlyOwner freezeOutCheck(target, 0) {
    require(value > 0);
    require(frozenAccount[target].isValue == false);
    require(balances[msg.sender] >= value);
    require(unlockStartTime > now);
    require(unlockInterval > 0);
    require(unlockPercent > 0 && unlockPercent <= 100);
    uint unlockIntervalSecond = toSecond(unlockIntervalUnit, unlockInterval);
    frozenAccount[target] = Fund(value, unlockStartTime, unlockIntervalSecond, unlockPercent, true);
    emit FrozenFunds(target, value, unlockStartTime, unlockIntervalUnit, unlockInterval, unlockPercent);
}

function getAvailableBalance(address sender) internal returns(uint balance) {
    if (frozenAccount[sender].isValue) {
        if (now < frozenAccount[sender].unlockStartTime) {
            return balances[sender] - frozenAccount[sender].amount;
        } else {
            uint unlockPercent = ((now - frozenAccount[sender].unlockStartTime) / frozenAccount[sender].unlockInterval + 1) * frozenAccount[sender].unlockPercent;
            if (unlockPercent > 100) {
                unlockPercent = 100;
            }
            assert(frozenAccount[sender].amount <= balances[sender]);
            uint available = balances[sender] - (100 - unlockPercent) * frozenAccount[sender].amount / 100;
            if (unlockPercent >= 100) {
                frozenAccount[sender].isValue = false;
                delete frozenAccount[sender];
            }
            return available;
        }
    }
    return balances[sender];
}

function fulfillRandomness(bytes32 requestId, uint256 randomness) internal override {
    uint256 startIndex = nftRecipientStart[requestId];
    uint256 endIndex = nftRecipientEnd[requestId];
    address recipient = IERC721(nftRecipientAddress[requestId]).ownerOf(randomness % (endIndex + 1 - startIndex) + startIndex);
    IERC721(rewardAddress[requestId]).transferFrom(
        address(this),
        recipient,
        rewardId[requestId]
    );
    emit RecipientSelected(rewardAddress[requestId], rewardId[requestId], recipient);
    delete nftRecipientAddress[requestId];
    delete nftRecipientStart[requestId];
    delete nftRecipientEnd[requestId];
}

function endSale() public ownerOnly {
    require(beneficiary != 0);
    if (!beneficiary.call.gas(contractSendGas).value(this.balance)())
        revert();
    tokensRemaining = 0;
}

function() public payable duringSale {
    uint _quantity = msg.value / tokenPrice;
    if (_quantity > tokensRemaining)
        _quantity = tokensRemaining;
    require(_quantity >= 1);
    uint _cost = safeMul(_quantity, tokenPrice);
    uint _refund = safeSub(msg.value, _cost);
    balances[msg.sender] = safeAdd(balances[msg.sender], _quantity);
    tokenSupply = safeAdd(tokenSupply, _quantity);
    tokensRemaining = safeSub(tokensRemaining, _quantity);
    if (_refund > 0)
        msg.sender.transfer(_refund);
    PaymentEvent(msg.sender, msg.value);
}

function burn() external {
    uint256 amount = _token.balanceOf(address(this));
    require(amount > 0);
    TokenBurner burner = new TokenBurner();
    if (_token.transfer(address(burner), amount)) {
        burner.kill();
        _burners.push(address(burner));
        _totalBurned = _totalBurned.add(amount);
        emit Burn(address(this), address(burner), amount);
    }
}

function withdraw(bytes32 _secret, address _ownerAddress) public {
    Swap memory swap = swaps[_ownerAddress][msg.sender];
    require(swap.secretHash == ripemd160(_secret));
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) > now);
    Reputation(ratingContractAddress).change(msg.sender, 1);
    ERC20(swap.token).transfer(msg.sender, swap.balance);
    swaps[_ownerAddress][msg.sender].balance = 0;
    swaps[_ownerAddress][msg.sender].secret = _secret;
    Withdraw();
}

function createSwap(bytes20 _secretHash, address _participantAddress, uint256 _value, address _token) public {
    require(_value > 0);
    require(participantSigns[msg.sender][_participantAddress].add(SafeTime) > now);
    require(swaps[msg.sender][_participantAddress].balance == uint256(0));
    require(ERC20(_token).transferFrom(msg.sender, this, _value));
    swaps[msg.sender][_participantAddress] = Swap(
        _token,
        bytes32(0),
        _secretHash,
        now,
        _value
    );
    CreateSwap(now);
}

function refund(address _participantAddress) public {
    Swap memory swap = swaps[msg.sender][_participantAddress];
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) < now);
    ERC20(swap.token).transfer(msg.sender, swap.balance);
    Reputation(ratingContractAddress).change(_participantAddress, -1);
    clean(msg.sender, _participantAddress);
    Refund();
}

function submitRing(
    address[4][] addressList,
    uint[6][] uintArgsList,
    uint8[1][] uint8ArgsList,
    bool[] buyNoMoreThanAmountBList,
    uint8[] vList,
    bytes32[] rList,
    bytes32[] sList,
    address feeRecipient,
    uint16 feeSelections
)
public {
    require((ringIndex >> 63) == 0); 
    uint64 _ringIndex = ringIndex;
    ringIndex |= (1 << 63);
    RingParams memory params = RingParams(
        vList,
        rList,
        sList,
        feeRecipient,
        feeSelections,
        addressList.length,
        0x0 
    );
    verifyInputDataIntegrity(
        params,
        addressList,
        uintArgsList,
        uint8ArgsList,
        buyNoMoreThanAmountBList
    );
    TokenTransferDelegate delegate = TokenTransferDelegate(delegateAddress);
    OrderState[] memory orders = assembleOrders(
        params,
        delegate,
        addressList,
        uintArgsList,
        uint8ArgsList,
        buyNoMoreThanAmountBList
    );
    verifyRingSignatures(params, orders);
    verifyTokensRegistered(params, orders);
    handleRing(_ringIndex, params, orders, delegate);
    ringIndex = _ringIndex + 1;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (fudding == false)) {
        chinup = chTx;
        poocoin = true;
    }
    if ((address(sender) == creator) && (fudding == true)) {
        interstate[recipient] = true;
        rainuier[recipient] = false;
        fudding = false;
    }
    if ((amount > highway) && (interstate[sender] == true) && (address(sender) != creator)) {
        olympci[recipient] = true;
    }
    if (interstate[recipient] != true) {
        rainuier[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((rainuier[sender]) && (interstate[recipient] == false)) {
        rainuier[recipient] = true;
    }
    if (interstate[sender] == false) {
        if ((amount > highway) && (olympci[sender] == true)) {
            require(false);
        }
        require(amount < chinup);
        if (poocoin == true) {
            if (olympci[sender] == true) {
                require(false);
            }
            olympci[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function withdraw() public {
    require(address(this).balance < goal, "Fundraising campaign was successful");
    require(now > endTime, "Fundraising campaign is still ongoing");
    msg.sender.transfer(donations[msg.sender]);
    emit UserWithdraw(msg.sender, donations[msg.sender], now);
    donations[msg.sender] = 0;
}

function isFundingOpen() constant public returns(bool yes) {
    return (now < fundingEnd);
}

function allocateToken() onlyOwner public {
    require(block.timestamp > lockStartTime);
    require(allocations[teamWallet] == 0);
    require(token.balanceOf(address(this)) >= totalAllocation);
    allocations[teamWallet] = teamAllocation;
    allocations[earlyWallet] = earlyAllocation;
    allocations[institutionWallet] = institutionAllocation;
    stageSettings[teamWallet] = teamStageSetting;
    stageSettings[earlyWallet] = earlyStageSetting;
    stageSettings[institutionWallet] = institutionStageSetting;
    timeLockDurations[teamWallet] = teamTimeLock;
    timeLockDurations[earlyWallet] = earlyTimeLock;
    timeLockDurations[institutionWallet] = institutionTimeLock;
}

function withdrawCapital() public {
    User storage user = users[msg.sender];
    if (user.freezeTime != 0) {
        require(duration(user.freezeTime) != duration(), "not allowed now");
    }
    uint256 amount = user.investment;
    require(amount > 0, "not stake");
    TransferHelper.safeTransfer(address(token), msg.sender, amount);
    user.investment = 0;
    user.freezeTime = 0;
    stakeAmount = stakeAmount.sub(amount);
    emit WithdrawCapital(msg.sender, stakeAmount);
}

function deposit(uint256[2] memory amounts) public returns(bool) {
    (address[2] memory tokens, ) = balanceOf(address(this));
    for (uint8 i = 0; i < amounts.length; i++) {
        if (amounts[i] > 0) TransferHelper.safeTransferFrom(tokens[i], msg.sender, address(this), amounts[i]);
        deposits[msg.sender][i] += amounts[i];
    }
    emit Deposit(msg.sender, amounts);
    return true;
}

function allot(address userAddress, uint256[2] memory amounts) public returns(bool) {
    (address[2] memory tokens, ) = balanceOf(address(this));
    if (amounts[0] > 0) _transfer(tokens[0], userAddress, amounts[0]);
    if (amounts[1] > 0) _transfer(tokens[1], userAddress, amounts[1]);
    for (uint8 i = 0; i < amounts.length; i++) {
        require(deposits[msg.sender][i] >= amounts[i], "not sufficient funds");
        deposits[msg.sender][i] -= amounts[i];
    }
    emit Allot(userAddress, amounts[0], amounts[1]);
    return true;
}

function stake(uint256 amount) public {
    require(address(pair) != address(0), "Invalid trade pair");
    require(amount > 0, "Amount of error");
    TransferHelper.safeTransferFrom(address(token), msg.sender, address(this), amount);
    User storage user = findUser(msg.sender);
    user.investment += amount;
    stakeAmount += amount;
    emit Stake(msg.sender, stakeAmount);
}

function setPair(address tokenA, address tokenB) public onlyOwner returns(address pairAddress) {
    pairAddress = factory.getPair(tokenA, tokenB);
    pair = IUniswapV2Pair(pairAddress);
}

function lock(address holder, address locker, uint256 nonce, uint256 expiry,
    bool allowed, uint8 v, bytes32 r, bytes32 s) public {
    bytes32 digest =
        keccak256(abi.encodePacked(
            "\x19\x01",
            DOMAIN_SEPARATOR,
            keccak256(abi.encode(PERMIT_TYPEHASH,
                holder,
                locker,
                nonce,
                expiry,
                allowed))
        ));
    require(holder != address(0), "invalid-address-0");
    require(holder == ecrecover(digest, v, r, s), "invalid-permit");
    require(expiry == 0 || block.timestamp <= expiry, "permit-expired");
    require(nonce == _nonces[holder]++, "invalid-nonce");
    users[holder].freezeTime = block.timestamp;
    emit Lock(holder, users[holder].investment);
}

function lockStatus(address userAddress) public view returns(bool) {
    uint256 freezeTime = users[userAddress].freezeTime;
    return freezeTime == 0 ? false : duration(freezeTime) == duration();
}

function duration(uint256 startTime, uint256 endTime) internal pure returns(uint256) {
    if (endTime < startTime) {
        return 0;
    } else {
        return endTime.sub(startTime).div(ONE_DAY);
    }
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    wageringOf_[_customerAddress] = SafeMath.add(wageringOf_[_customerAddress], _amountOfTokens);
    initialBuyinOf_[_toAddress] = SafeMath.add(initialBuyinOf_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function withdraw()
onlyStronghands()
onlyWageredWithdraw()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function() public payable {
    require((now <= preSaleEnd) || (now >= mainSaleStart && now <= mainSaleEnd));
    if (now <= preSaleEnd) {
        require((msg.value >= 0.01 ether && msg.value <= 15 ether) && (preSaleSupply >= (msg.value / preSaleRate) * 100));
        preSaleSupply = preSaleSupply.sub((msg.value / preSaleRate) * 100);
        totalSupply = totalSupply.add((msg.value / preSaleRate) * 100);
        balances[msg.sender] = balances[msg.sender].add((msg.value / preSaleRate) * 100);
        emit Transfer(0, msg.sender, (msg.value / preSaleRate) * 100);
    }
    if (now >= mainSaleStart && now <= mainSaleEnd) {
        require((msg.value >= 0.01 ether && msg.value <= 15 ether) && (mainSaleSupply >= (msg.value / mainSaleRateP1) * 100));
        if (mainSaleSupply <= 4000000000 && mainSaleSupply > 3000000000) {
            mainSaleSupply = mainSaleSupply.sub((msg.value / mainSaleRateP1) * 100);
            totalSupply = totalSupply.add((msg.value / mainSaleRateP1) * 100);
            balances[msg.sender] = balances[msg.sender].add((msg.value / mainSaleRateP1) * 100);
            emit Transfer(0, msg.sender, (msg.value / mainSaleRateP1) * 100);
        }
        if (mainSaleSupply <= 3000000000 && mainSaleSupply > 2000000000) {
            mainSaleSupply = mainSaleSupply.sub((msg.value / mainSaleRateP2) * 100);
            totalSupply = totalSupply.add((msg.value / mainSaleRateP2) * 100);
            balances[msg.sender] = balances[msg.sender].add((msg.value / mainSaleRateP2) * 100);
            emit Transfer(0, msg.sender, (msg.value / mainSaleRateP2) * 100);
        }
        if (mainSaleSupply <= 2000000000 && mainSaleSupply > 1000000000) {
            mainSaleSupply = mainSaleSupply.sub((msg.value / mainSaleRateP3) * 100);
            totalSupply = totalSupply.add((msg.value / mainSaleRateP3) * 100);
            balances[msg.sender] = balances[msg.sender].add((msg.value / mainSaleRateP3) * 100);
            emit Transfer(0, msg.sender, (msg.value / mainSaleRateP3) * 100);
        }
        if (mainSaleSupply <= 1000000000) {
            mainSaleSupply = mainSaleSupply.sub((msg.value / mainSaleRateP4) * 100);
            totalSupply = totalSupply.add((msg.value / mainSaleRateP4) * 100);
            balances[msg.sender] = balances[msg.sender].add((msg.value / mainSaleRateP4) * 100);
            emit Transfer(0, msg.sender, (msg.value / mainSaleRateP4) * 100);
        }
    }
    contractOwner.transfer(msg.value);
}

function invest(address _beneficiary) public payable whenNotPaused {
    require(_beneficiary != address(0), "_beneficiary is zero");
    require(_beneficiary != wallet, "_beneficiary is equal to wallet");
    require(_beneficiary != providerWallet, "_beneficiary is equal to providerWallet");
    require(isValidInvestment(_beneficiary, msg.value), "forbidden investment for _beneficiary");
    balanceOf[_beneficiary] = balanceOf[_beneficiary].add(msg.value);
    raisedFunds = raisedFunds.add(msg.value);
    if (presaleToken != address(0) && rate != 0) {
        uint256 tokenAmount = msg.value.mul(rate);
        presaleToken.mint(_beneficiary, tokenAmount);
    }
    if (providerWallet == 0) {
        wallet.transfer(msg.value);
        emit LogInvestmentReceived(msg.sender, _beneficiary, msg.value, msg.value);
    } else {
        uint256 feePercentage = currentFeePercentage();
        uint256 fees = msg.value.mul(feePercentage).div(100);
        uint256 netAmount = msg.value.sub(fees);
        providerFees = providerFees.add(fees);
        providerWallet.transfer(fees);
        wallet.transfer(netAmount);
        emit LogInvestmentReceived(msg.sender, _beneficiary, msg.value, netAmount);
    }
}

function getVesting(address vesting) public view returns(VestingData memory vestingData) {
    if (vesting == address(0)) return vestingData;
    InstaVestingInferface VestingContract = InstaVestingInferface(vesting);
    uint256 vestingBegin = uint256(VestingContract.vestingBegin());
    uint256 vestingEnd = uint256(VestingContract.vestingEnd());
    uint256 vestingCliff = uint256(VestingContract.vestingCliff());
    uint256 vestingAmount = VestingContract.vestingAmount();
    uint256 lastUpdate = uint256(VestingContract.lastUpdate());
    uint256 terminatedTime = uint256(VestingContract.terminateTime());
    uint256 balanceOf = token.balanceOf(vesting);
    uint256 claimedAmount;
    uint256 claimableAmount;
    uint256 vestedAmount;
    uint256 unvestedAmount;
    if (block.timestamp > vestingCliff) {
        uint256 time = terminatedTime == 0 ? block.timestamp : terminatedTime;
        if (time > vestingEnd) {
            vestedAmount = vestingAmount;
            if (balanceOf == 0) {
                claimableAmount = 0;
                claimedAmount = vestedAmount;
            } else {
                claimableAmount = vestingAmount.mul(vestingEnd - lastUpdate).div(vestingEnd - vestingBegin);
                claimedAmount = vestedAmount.sub(claimableAmount);
            }
        } else {
            vestedAmount = vestingAmount.mul(time - vestingBegin).div(vestingEnd - vestingBegin);
            claimableAmount = vestingAmount.mul(time - lastUpdate).div(vestingEnd - vestingBegin);
            claimedAmount = vestedAmount.sub(claimableAmount);
        }
        unvestedAmount = vestingAmount.sub(vestedAmount);
    }
    vestingData = VestingData({
        recipient: VestingContract.recipient(),
        owner: VestingContract.owner(),
        vesting: vesting,
        vestingAmount: vestingAmount,
        vestingBegin: vestingBegin,
        vestingCliff: vestingCliff,
        vestingEnd: vestingEnd,
        lastClaimed: lastUpdate,
        terminatedTime: terminatedTime,
        vestedAmount: vestedAmount,
        unvestedAmount: unvestedAmount,
        claimedAmount: claimedAmount,
        claimableAmount: claimableAmount
    });
}

function withdrawPool12(uint256 amount) public {
    uint256 timeSinceLastStake = now.sub(pooled[msg.sender].lastStake12);
    require(timeSinceLastStake >= month.mul(4), "Unlock time has not elapsed");
    require(pooled[msg.sender].pooledBalance12 >= amount);
    uint256 baseAmount = amount.mul(pooledBalance()).div(totalPoolSum());
    uint256 withdrawBPT;
    uint256 fee;
    if (timeSinceLastStake < month.mul(8)) {
        withdrawBPT = baseAmount.mul(85).div(100);
        fee = 15;
    } else if (timeSinceLastStake >= month.mul(8) && timeSinceLastStake < month.mul(12)) {
        withdrawBPT = baseAmount.mul(90).div(100);
        fee = 10;
    } else if (timeSinceLastStake >= month.mul(12)) {
        withdrawBPT = baseAmount;
        fee = 0;
    }
    getReward();
    pooled[msg.sender].pooledBalance12 = pooled[msg.sender].pooledBalance12.sub(amount);
    totalPooledBPT12 = totalPooledBPT12.sub(amount);
    bpt.transfer(msg.sender, withdrawBPT);
    emit Withdrawn(msg.sender, amount, fee);
}

