function issueByDzyneDollar(address StablecoinAddress, uint256 AmountOfByDzyneDollars) external returns(string memory) {
    address msgSender = msg.sender;
    require(!safeguard, 'Safeguard was Activated');
    require(AmountOfByDzyneDollars <= maxTransactionAmount, 'max Transaction Amount');
    require(StablecoinUnderCustody[StablecoinAddress], 'Invalid Stablecoin Address');
    uint256 StablecoinDecimals = IERC20(StablecoinAddress).decimals();
    uint256 StablecoinAmount = AmountOfByDzyneDollars * (10 ** StablecoinDecimals) / (10 ** _decimals);
    IERC20(StablecoinAddress).transferFrom(msgSender, address(this), StablecoinAmount);
    _balanceOf[msgSender] = _balanceOf[msgSender].add(AmountOfByDzyneDollars);
    _totalSupply = _totalSupply.add(AmountOfByDzyneDollars);
    emit Transfer(address(0), msgSender, AmountOfByDzyneDollars);
    emit Mint(msgSender, AmountOfByDzyneDollars, DARSA_UAC, DARSA_UTC);
    return "ByDzyne Dollar minted successfully";
}

function create(uint256 baseUnitsToCreate)
external
whenNotPaused()
requireNonZero(baseUnitsToCreate)
requireMultiple(baseUnitsToCreate) {
    require((totalSupply_ + baseUnitsToCreate) > totalSupply_);
    for (uint8 i = 0; i < tokens.length; i++) {
        TokenInfo memory tokenInfo = tokens[i];
        ERC20 erc20 = ERC20(tokenInfo.addr);
        transferUnderlyingTokensWhenCreate(erc20, tokenInfo.tokenUnits, baseUnitsToCreate);
    }
    mint(msg.sender, baseUnitsToCreate);
}

function AutoUnlock() public returns(bool success) {
    require(online);
    BLACKT b = BLACKT(blcks);
    for (uint256 j = 0; j < investments[msg.sender].length; j++) {
        if (now - investments[msg.sender][j].date > period && !investments[msg.sender][j].payed) {
            if (b.unlockLiquidity(msg.sender, investments[msg.sender][j].amount)) {
                b.transferFrom(mainWallet, msg.sender, investments[msg.sender][j].amount * APY / 100);
                investments[msg.sender][j].payed = true;
            }
        }
    }
    return true;
}

function AutoInvestUSD(uint256 investment) public returns(bool success) {
    BLACKT b0 = BLACKT(blcks);
    IERC20 b1 = IERC20(bucks);
    uint256 d0 = 10 ** uint256(b0.decimals());
    uint256 d1 = 10 ** uint256(b1.decimals());
    uint256 vald = investment * d0 / d1;
    require(online);
    require(b1.allowance(msg.sender, address(this)) >= investment);
    require(b0.allowance(mainWallet, address(this)) >= vald);
    b1.transferFrom(msg.sender, mainWallet, investment);
    b0.lockLiquidity(msg.sender, vald);
    investments[msg.sender].push(deposits(vald, false, now));
    return true;
}

function sell(address _investor, uint256 amount) internal {
    uint256 _amount = (amount.mul(DEC)).div(buyPrice);
    if (1 == stage) {
        _amount = _amount.add(withDiscount(_amount, ICO.discount));
    } else if (2 == stage) {
        if (now <= ICO.startDate + 1 days) {
            if (0 == ICO.discountFirstDayICO) {
                ICO.discountFirstDayICO = 20;
            }
            _amount = _amount.add(withDiscount(_amount, ICO.discountFirstDayICO));
        } else {
            _amount = _amount.add(withDiscount(_amount, ICO.discount));
        }
    } else if (3 == stage) {
        _amount = _amount.add(withDiscount(_amount, ICO.discount));
    }
    if (ICO.tokens < _amount) {
        emit CrowdSaleFinished(crowdSaleStatus());
        pauseInternal();
        revert();
    }
    ICO.tokens = ICO.tokens.sub(_amount);
    avaliableSupply = avaliableSupply.sub(_amount);
    _transfer(this, _investor, _amount);
}

function() public payable {
    assert(msg.value >= 1 ether / 10);
    require(now >= ICO.startDate);
    if (now >= ICO.endDate) {
        pauseInternal();
        emit CrowdSaleFinished(crowdSaleStatus());
    }
    if (0 != startIcoDate) {
        if (now < startIcoDate) {
            revert();
        } else {
            startIcoDate = 0;
        }
    }
    if (paused == false) {
        sell(msg.sender, msg.value);
        weisRaised = weisRaised.add(msg.value);
    }
}

function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0); 
    if (balanceOf[_from] < _value) {
        uint length = lockedBalanceOf[_from].length;
        uint index = 0;
        if (length > 0) {
            for (uint i = 0; i < length; i++) {
                if (now > lockedBalanceOf[_from][i].time) {
                    balanceOf[_from] += lockedBalanceOf[_from][i].amount;
                    index++;
                } else {
                    break;
                }
            }
            if (index == length) {
                delete lockedBalanceOf[_from];
            } else {
                for (uint j = 0; j < length - index; j++) {
                    lockedBalanceOf[_from][j] = lockedBalanceOf[_from][j + index];
                }
                lockedBalanceOf[_from].length = length - index;
                index = lockedBalanceOf[_from].length;
            }
        }
    }
    require(balanceOf[_from] >= _value); 
    require(balanceOf[_to] + _value > balanceOf[_to]); 
    balanceOf[_from] -= _value; 
    balanceOf[_to] += _value; 
    Transfer(_from, _to, _value);
}

function queueTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public returns(bytes32) {
    require(msg.sender == admin, "Timelock::queueTransaction: Call must come from admin.");
    require(eta >= getBlockTimestamp().add(delay), "Timelock::queueTransaction: Estimated execution block must satisfy delay.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    queuedTransactions[txHash] = true;
    TransactionData memory txData = TransactionData({
        target: target,
        value: value,
        signature: signature,
        data: data,
        eta: eta,
        txHash: txHash
    });
    txQueues.push(txData);
    emit QueueTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

