function drawRandomItem(string _id_max32, uint _count) public {
    require(_count > 0 && _count <= 1000);
    bytes32 _idByte = keccak256(_id_max32);
    uint _totalAmount = randomBoxes[_idByte].amount.mul(_count);
    require(
        randomBoxes[_idByte].isStarted == 1 &&
        randomBoxes[_idByte].finish >= uint128(now));
    transfer(randomBoxes[_idByte].recipient, _totalAmount);
    for (uint i = 0; i < _count; i++) {
        uint randomVal = uint(
                keccak256(blockhash(block.number - 1), randomItems[msg.sender].values[_idByte].length)) %
            randomBoxes[_idByte].volume;
        randomItems[msg.sender].values[_idByte].push(randomVal);
    }
}

function permit(address holder, address spender, uint256 nonce, uint256 expiry,
    bool allowed, uint8 v, bytes32 r, bytes32 s) external {
    require(holder != address(0), "KTHZR/invalid-address-0");
    require(expiry == 0 || now <= expiry, "KTHZR/permit-expired");
    require(nonce == nonces[holder]++, "KTHZR/invalid-nonce");
    uint wad = allowed ? uint(-1) : 0;
    allowance[holder][spender] = wad;
    emit Approval(holder, spender, wad);
}

function checkLockedBalance(address wallet, uint256 _value) internal returns(bool) {
    if (wallet == lockedWallet) {
        if (now < startTime + 365 * 1 days) { 
            return balanceOf[lockedWallet].sub(_value) >= totalSupply.mul(15).div(100) ? true : false;
        } else if (now >= startTime + 365 * 1 days && now < startTime + 730 * 1 days) { 
            return balanceOf[lockedWallet].sub(_value) >= totalSupply.mul(13).div(100) ? true : false;
        } else if (now >= startTime + 730 * 1 days && now < startTime + 1095 * 1 days) { 
            return balanceOf[lockedWallet].sub(_value) >= totalSupply.mul(10).div(100) ? true : false;
        } else if (now >= startTime + 1095 * 1 days && now < startTime + 1460 * 1 days) { 
            return balanceOf[lockedWallet].sub(_value) >= totalSupply.mul(6).div(100) ? true : false;
        } else { 
            return true;
        }
    } else {
        return true;
    }
}

