function agentMakeOrder(
    address fromToken_,
    address toToken_,
    uint256 price_,
    uint256 amount_,
    address representor_
)
public
payable
returns(bool) {
    uint256 depositAmount = depositAndFreeze(fromToken_, representor_);
    if (
        checkAmount(fromToken_, amount_) &&
        checkPriceAmount(price_)
    ) {
        require(representor_ != address(0));
        address user = representor_;
        uint256 costAmount = makeOrder(fromToken_, toToken_, price_, amount_, user, depositAmount);
        emit eMakeOrder(fromToken_, toToken_, price_, user, amount_);
        require(costAmount <= depositAmount);
        updateBalance(msg.sender, fromToken_, safeSub(depositAmount, costAmount), true);
        return true;
    }
}

function userTakeOrder(
    address fromToken_,
    address toToken_,
    uint256 price_,
    uint256 amount_,
    address representor_
)
public
payable
onlyActive
returns(bool) {
    address user = getUser(representor_);
    uint256 depositAmount = depositAndFreeze(fromToken_, user);
    if (
        checkAmount(fromToken_, amount_) &&
        checkPriceAmount(price_) &&
        checkBalance(user, fromToken_, amount_, depositAmount)
    ) {
        emit eMakeOrder(fromToken_, toToken_, price_, user, amount_);
        uint256[2] memory fillAmount;
        uint256[2] memory profit;
        (fillAmount, profit) = findAndTrade(fromToken_, toToken_, price_, amount_);
        uint256 fee;
        uint256 toAmount;
        uint256 orderAmount;
        if (fillAmount[0] > 0) {
            emit eFillOrder(fromToken_, toToken_, price_, user, fillAmount[0]);
            toAmount = safeDiv(safeMul(fillAmount[0], price_), 1 ether);
            if (amount_ > fillAmount[0]) {
                orderAmount = safeSub(amount_, fillAmount[0]);
                makeOrder(fromToken_, toToken_, price_, orderAmount, user, depositAmount);
            }
            if (toAmount > 0) {
                (toAmount, fee) = caculateFee(user, toAmount, 1);
                profit[1] = profit[1] + fee;
                updateBalance(bank, fromToken_, profit[0], true);
                updateBalance(bank, toToken_, profit[1], true);
                if (manualWithdraw[user]) {
                    updateBalance(user, toToken_, toAmount, true);
                } else {
                    transferToken(user, toToken_, toAmount);
                }
            }
        } else {
            orderAmount = amount_;
            makeOrder(fromToken_, toToken_, price_, orderAmount, user, depositAmount);
        }
        if (amount_ > depositAmount) {
            updateBalance(user, fromToken_, safeSub(amount_, depositAmount), false);
        } else if (amount_ < depositAmount) {
            updateBalance(user, fromToken_, safeSub(depositAmount, amount_), true);
        }
        return true;
    } else if (depositAmount > 0) {
        updateBalance(user, fromToken_, depositAmount, true);
    }
}

function tokensOwedByInterval(uint256 balance, uint256 lastInterval, uint256 currInterval) public view returns(uint256) {
    if (lastInterval >= currInterval || lastInterval >= finalIntervalForTokenGen) {
        return 0;
    }
    uint256 tokensHeld = balance; 
    uint256 intPerWin = intervalsPerWindow;
    uint256 totalRateWinds = totalRateWindows;
    uint256 intPerBatch = 5; 
    mapping(uint256 => uint256) ratByYear = ratesByYear;
    uint256 ratMultiplier = rateMultiplier;
    uint256 minRateWindow = (lastInterval / intPerWin).add(1);
    uint256 maxRateWindow = (currInterval / intPerWin).add(1);
    if (maxRateWindow > totalRateWinds) {
        maxRateWindow = totalRateWinds;
    }
    for (uint256 rateWindow = minRateWindow; rateWindow <= maxRateWindow; rateWindow++) {
        uint256 intervals = getIntervalsForWindow(rateWindow, lastInterval, currInterval, intPerWin);
        while (intervals > 0) {
            if (intervals >= intPerBatch) {
                tokensHeld = (tokensHeld.mul(ratByYear[rateWindow] ** intPerBatch)) / (ratMultiplier ** intPerBatch);
                intervals = intervals.sub(intPerBatch);
            } else {
                tokensHeld = (tokensHeld.mul(ratByYear[rateWindow] ** intervals)) / (ratMultiplier ** intervals);
                intervals = 0;
            }
        }
    }
    return (tokensHeld.sub(balance));
}

function intervalAtTime(uint256 time) public view returns(uint256) {
    if (time <= startTime) {
        return 0;
    }
    uint256 interval = (time.sub(startTime)) / tokenGenInterval;
    uint256 finalInt = finalIntervalForTokenGen; 
    if (interval > finalInt) {
        return finalInt;
    } else {
        return interval;
    }
}

function getIntervalsForWindow(uint256 rateWindow, uint256 lastInterval, uint256 currInterval, uint256 intPerWind) public pure returns(uint256) {
    if (lastInterval < ((rateWindow.sub(1)).mul(intPerWind))) {
        lastInterval = ((rateWindow.sub(1)).mul(intPerWind));
    }
    if (currInterval > rateWindow.mul(intPerWind)) {
        currInterval = rateWindow.mul(intPerWind);
    }
    return currInterval.sub(lastInterval);
}

function vestTokens() public returns(bool) {
    require(pendingInstallments > 0);
    require(paidInstallments < 7);
    require(pendingVestingPool > 0);
    require(now - startTime > cliff);
    if (!rewardGenerationComplete) {
        for (uint256 i = 1; i <= 5; i++) {
            addReward(distributionAddresses[i]);
        }
    }
    uint256 currInterval = intervalAtTime(now);
    uint256 tokensToVest = 0;
    uint256 totalTokensToVest = 0;
    uint256 totalPool = totalVestingPool;
    uint256[2] memory founderCat;
    founderCat[0] = 0;
    founderCat[1] = 0;
    uint256[5] memory origFounderBal;
    origFounderBal[0] = accounts[distributionAddresses[1]].balance;
    origFounderBal[1] = accounts[distributionAddresses[2]].balance;
    origFounderBal[2] = accounts[distributionAddresses[3]].balance;
    origFounderBal[3] = accounts[distributionAddresses[4]].balance;
    origFounderBal[4] = accounts[distributionAddresses[5]].balance;
    uint256[2] memory rewardCat;
    rewardCat[0] = 0;
    rewardCat[1] = 0;
    if (paidInstallments < 1) {
        uint256 intervalAtCliff = intervalAtTime(cliff + startTime);
        tokensToVest = totalPool / 4;
        founderCat[0] = tokensToVest / 4;
        founderCat[1] = tokensToVest / 8;
        pendingVestingPool -= tokensToVest;
        if (currInterval > intervalAtCliff && !rewardGenerationComplete) {
            rewardCat[0] = tokensOwedByInterval(founderCat[0], intervalAtCliff, currInterval);
            rewardCat[1] = rewardCat[0] / 2;
            founderCat[0] += rewardCat[0];
            founderCat[1] += rewardCat[1];
            tokensToVest += ((3 * rewardCat[0]) + (2 * rewardCat[1]));
            pendingRewardsToMint -= ((3 * rewardCat[0]) + (2 * rewardCat[1]));
        }
        accounts[distributionAddresses[1]].balance += founderCat[0];
        accounts[distributionAddresses[2]].balance += founderCat[0];
        accounts[distributionAddresses[3]].balance += founderCat[0];
        accounts[distributionAddresses[4]].balance += founderCat[1];
        accounts[distributionAddresses[5]].balance += founderCat[1];
        totalTokensToVest = tokensToVest;
        pendingInstallments -= 1;
        paidInstallments += 1;
    }
    uint256 installments = ((currInterval * tokenGenInterval) - cliff) / vestingPeriod;
    uint256 installmentsToPay = installments + 1 - paidInstallments;
    if (installmentsToPay > 0) {
        if (installmentsToPay > pendingInstallments) {
            installmentsToPay = pendingInstallments;
        }
        tokensToVest = (totalPool * 125) / 1000;
        founderCat[0] = tokensToVest / 4;
        founderCat[1] = tokensToVest / 8;
        uint256 intervalsAtVest = 0;
        for (uint256 installment = paidInstallments; installment < (installmentsToPay + paidInstallments); installment++) {
            intervalsAtVest = intervalAtTime(cliff + (installment * vestingPeriod) + startTime);
            if (currInterval >= intervalsAtVest && !rewardGenerationComplete) {
                rewardCat[0] = tokensOwedByInterval(founderCat[0], intervalsAtVest, currInterval);
                rewardCat[1] = rewardCat[0] / 2;
                totalTokensToVest += tokensToVest;
                totalTokensToVest += ((3 * rewardCat[0]) + (2 * rewardCat[1]));
                pendingRewardsToMint -= ((3 * rewardCat[0]) + (2 * rewardCat[1]));
                accounts[distributionAddresses[1]].balance += (founderCat[0] + rewardCat[0]);
                accounts[distributionAddresses[2]].balance += (founderCat[0] + rewardCat[0]);
                accounts[distributionAddresses[3]].balance += (founderCat[0] + rewardCat[0]);
                accounts[distributionAddresses[4]].balance += (founderCat[1] + rewardCat[1]);
                accounts[distributionAddresses[5]].balance += (founderCat[1] + rewardCat[1]);
            }
        }
        pendingVestingPool -= (installmentsToPay * tokensToVest);
        pendingInstallments -= installmentsToPay;
        paidInstallments += installmentsToPay;
    }
    increaseTotalSupply(totalTokensToVest);
    accounts[distributionAddresses[1]].lastInterval = currInterval;
    accounts[distributionAddresses[2]].lastInterval = currInterval;
    accounts[distributionAddresses[3]].lastInterval = currInterval;
    accounts[distributionAddresses[4]].lastInterval = currInterval;
    accounts[distributionAddresses[5]].lastInterval = currInterval;
    generateMintEvents(distributionAddresses[1], (accounts[distributionAddresses[1]].balance - origFounderBal[0]));
    generateMintEvents(distributionAddresses[2], (accounts[distributionAddresses[2]].balance - origFounderBal[1]));
    generateMintEvents(distributionAddresses[3], (accounts[distributionAddresses[3]].balance - origFounderBal[2]));
    generateMintEvents(distributionAddresses[4], (accounts[distributionAddresses[4]].balance - origFounderBal[3]));
    generateMintEvents(distributionAddresses[5], (accounts[distributionAddresses[5]].balance - origFounderBal[4]));
}

function updateCumulative() public {
    uint256 _nextUpdateHour = lastUpdateHour.add(updatePeriod);
    if (now >= _nextUpdateHour) {
        uint totalMainPriceWeight;
        uint totalMainPoolBal;
        for (uint256 i = 0; i < pools.length; i++) {
            uint _decimalFactor = 10 ** (uint256(18).sub(sideTokenDecimals[i]));
            uint tokenMainPrice = pools[i].getSpotPrice(sideTokens[i], mainToken).mul(_decimalFactor);
            require(tokenMainPrice != 0, "!price");
            uint reserveBal = pools[i].getBalance(sideTokens[i]).mul(_decimalFactor);
            require(reserveBal >= ORACLE_RESERVE_MINIMUM, "!min reserve");
            uint tokenBal = pools[i].getBalance(mainToken);
            totalMainPriceWeight = totalMainPriceWeight.add(tokenMainPrice.mul(tokenBal).div(BPOOL_BONE));
            totalMainPoolBal = totalMainPoolBal.add(tokenBal);
        }
        require(totalMainPriceWeight <= uint112(-1) && totalMainPoolBal <= uint112(-1), 'BPool: OVERFLOW');
        uint32 blockTimestamp = uint32(block.timestamp % 2 ** 32);
        uint32 timeElapsed = blockTimestamp - blockTimestampCumulativeLast; 
        if (timeElapsed > 0 && totalMainPoolBal != 0) {
            priceCumulative += uint(UQ112x112.encode(uint112(totalMainPriceWeight)).uqdiv(uint112(totalMainPoolBal))) * timeElapsed;
            blockTimestampCumulativeLast = blockTimestamp;
        }
        lastUpdateHour = _nextUpdateHour;
    }
}

function update() external checkEpoch {
    updateCumulative();
    uint32 timeElapsed = blockTimestampCumulativeLast - blockTimestampLast; 
    if (timeElapsed == 0) {
        return;
    }
    priceAverage = FixedPoint.uq112x112(uint224((priceCumulative - priceCumulativeLast) / timeElapsed));
    priceCumulativeLast = priceCumulative;
    blockTimestampLast = blockTimestampCumulativeLast;
    epochPrice[epoch] = priceAverage.decode();
    emit Updated(priceCumulative);
}

function consult(address token, uint256 amountIn) external view returns(uint144 amountOut) {
    require(token == mainToken, "OracleMultiPair: INVALID_TOKEN");
    require(now.sub(blockTimestampLast) <= epochPeriod, "OracleMultiPair: Price out-of-date");
    amountOut = priceAverage.mul(amountIn).decode144();
}

function twap(uint256 _amountIn) external view returns(uint144) {
    uint32 timeElapsed = blockTimestampCumulativeLast - blockTimestampLast;
    return (timeElapsed == 0) ? priceAverage.mul(_amountIn).decode144() : FixedPoint.uq112x112(uint224((priceCumulative - priceCumulativeLast) / timeElapsed)).mul(_amountIn).decode144();
}

function withdraw()
public
isActivated()
isHuman() {
    uint256 _pID = pIDxAddr_[msg.sender];
    require(_pID != 0, "Please join the game first!");
    uint256 _eth;
    if (rID_ > 1) {
        for (uint256 i = 1; i < rID_; i++) {
            if (plyrRnds_[_pID][i].withdrawn == false) {
                if (plyrRnds_[_pID][i].plyrTmKeys[round_[i].team] != 0) {
                    _eth = _eth.add(round_[i].ethPerKey.mul(plyrRnds_[_pID][i].plyrTmKeys[round_[i].team]) / 1000000000000000000);
                }
                plyrRnds_[_pID][i].withdrawn = true;
            }
        }
    }
    _eth = _eth.add(plyr_[_pID].gen).add(plyr_[_pID].aff);
    if (_eth > 0) {
        plyr_[_pID].addr.transfer(_eth);
    }
    plyr_[_pID].gen = 0;
    plyr_[_pID].aff = 0;
    emit onWithdraw(_pID, plyr_[_pID].addr, plyr_[_pID].name, _eth, now);
}

function getNextKillingAfter()
public
view
returns(uint256) {
    require(round_[rID_].state == 2, "Not in killing period.");
    uint256 _tNext = round_[rID_].lastKillingTime.add(killingGap_);
    uint256 _t = _tNext > now ? _tNext.sub(now) : 0;
    return _t;
}

function buy(uint256 _team, bytes32 _affCode)
public
payable
isActivated()
isHuman()
isWithinLimits(msg.value) {
    require(round_[rID_].state < 3, "This round has ended.");
    if (round_[rID_].state == 0) {
        require(now >= round_[rID_].start, "This round hasn't started yet.");
        round_[rID_].state = 1;
    }
    determinePID(msg.sender);
    uint256 _pID = pIDxAddr_[msg.sender];
    uint256 _tID;
    uint256 _affID;
    if (_affCode == "" || _affCode == plyr_[_pID].name) {
        _affID = plyr_[_pID].laff;
    } else {
        _affID = pIDxName_[_affCode];
        if (_affID != plyr_[_pID].laff) {
            plyr_[_pID].laff = _affID;
        }
    }
    if (round_[rID_].state == 1) {
        _tID = determinTID(_team, _pID);
        buyCore(_pID, _affID, _tID, msg.value);
        if (round_[rID_].tID_ >= minTms_) {
            round_[rID_].state = 2;
            startKilling();
        }
    } else if (round_[rID_].state == 2) {
        if (round_[rID_].liveTeams == 1) {
            endRound();
            refund(_pID, msg.value);
            return;
        }
        _tID = determinTID(_team, _pID);
        buyCore(_pID, _affID, _tID, msg.value);
        if (now > round_[rID_].lastKillingTime.add(killingGap_)) {
            kill();
        }
    }
}

