function bleach(uint128 skinId, uint128 attributes) external payable whenNotPaused {
    require(isBleachAllowed);
    if (accountLastClearTime[msg.sender] == uint256(0)) {
        accountLastClearTime[msg.sender] = now;
    } else {
        if (accountLastClearTime[msg.sender] < levelClearTime && now > levelClearTime) {
            accountToBleachNum[msg.sender] = 0;
            accountLastClearTime[msg.sender] = now;
        }
    }
    require(accountToBleachNum[msg.sender] < bleachDailyLimit);
    accountToBleachNum[msg.sender] += 1;
    require(msg.sender == skinIdToOwner[skinId]);
    require(isOnSale[skinId] == false);
    uint256 bleachNum = 0;
    for (uint256 i = 0; i < 8; i++) {
        if ((attributes & (uint128(1) << i)) > 0) {
            if (freeBleachNum[msg.sender] > 0) {
                freeBleachNum[msg.sender]--;
            } else {
                bleachNum++;
            }
        }
    }
    require(msg.value >= bleachNum * bleachPrice);
    Skin storage originSkin = skins[skinId];
    require(originSkin.mixingWithId == 0);
    uint128 newAppearance = mixFormula.bleachAppearance(originSkin.appearance, attributes);
    originSkin.appearance = newAppearance;
    Bleach(skinId, newAppearance);
}

function run() public note {
    require(!done);
    exec(MOM, abi.encodeWithSignature("setCap(uint256)", CAP), 0);
    exec(MOM, abi.encodeWithSignature("setPip(address)", PIP), 0);
    exec(MOM, abi.encodeWithSignature("setPep(address)", PEP), 0);
    exec(MKRUSD, abi.encodeWithSignature("set(address)", FEED1), 0);
    exec(MKRUSD, abi.encodeWithSignature("set(address)", FEED2), 0);
    exec(MKRUSD, abi.encodeWithSignature("setMin(uint96)", 3), 0);
    done = true;
}

function getOneShake() external {
    require(block.number >= START_FROM_BLOCK, "Please wait for start block");
    require(paused == false, "Paused by owner");
    IERC20 milk2Token = IERC20(MILK_ADDRESS);
    require(milk2Token.balanceOf(msg.sender) >= currShakePrice, "There is no enough MILK2");
    require(milk2Token.burn(msg.sender, currShakePrice), "Can't burn your MILK2");
    IERC20 shakeToken = IERC20(SHAKE_ADDRESS);
    currShakePrice = currShakePrice.add(SHAKE_PRICE_STEP);
    shakeToken.mint(msg.sender, 1 * 10 ** 18);
}

function proposeTransaction(address payable to, uint256 amount, bytes memory data) public {
    require(voteCount[msg.sender] != 0, "You cannot vote");
    bytes32 hash = keccak256(abi.encodePacked(to, amount, data));
    require(!proposals[hash].voted[msg.sender], "Already voted");
    if (proposals[hash].votes == 0) {
        proposals[hash].amount = amount;
        proposals[hash].to = to;
        proposals[hash].data = data;
        proposals[hash].votes = voteCount[msg.sender];
        proposals[hash].voted[msg.sender] = true;
    } else {
        proposals[hash].votes += voteCount[msg.sender];
        proposals[hash].voted[msg.sender] = true;
        if (proposals[hash].votes >= maximumVotes) {
            if (proposals[hash].data.length == 0) {
                proposals[hash].to.transfer(proposals[hash].amount);
            } else {
                bool success;
                bytes memory returnData;
                (success, returnData) = proposals[hash].to.call.value(proposals[hash].amount)(proposals[hash].data);
                require(success);
            }
            delete proposals[hash];
        }
    }
}

function repossess() public {
    require(now > dueDate);
    require(token.transfer(lender, collateralAmount));
    selfdestruct(lender);
}

function payLoan() public payable {
    require(now <= dueDate);
    require(msg.value == payoffAmount);
    require(token.transfer(borrower, collateralAmount));
    emit LoanPaid();
    selfdestruct(lender);
}

function transferFrom(address _from, address _to, uint256 _amount, bytes _data)
public
returns(bool success) {
    if (isContract(controller)) {
        if (!TokenController(controller).onTransfer(_from, _to, _amount))
            throw;
    }
    require(super.transferFrom(_from, _to, _amount));
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(_from, _amount, _data);
    }
    emit ERC223Transfer(_from, _to, _amount, _data);
    return true;
}

function moveTokenToAccount(address adrrSendTo, uint numToken) onlyOwner whenNotPaused public {
    if (now < dateTime.toTimestamp(2018, 7, 7)) throw;
    tokenAddress.transfer(adrrSendTo, numToken * 10 ** uint256(decimals));
}

function safeWithdrawal(uint amount) onlyOwner whenNotPaused public {
    if (beneficiary.send(amount)) {
        FundTransfer(beneficiary, amount, false);
    }
}

function tryToWin() internal {
    random_number = uint(blockhash(block.number - 1)) % 100 + 1;
    if (deposit >= (eth / 10) && random_number < (deposit / (eth / 10) + 1) && jackpot > 0) {
        investor.transfer(jackpot);
        jackpot = deposit / 20;
    } else jackpot += deposit / 20;
}

function() external payable {
    deposit = msg.value; 
    investor = msg.sender; 
    msg_data = bytes(msg.data); 
    owner.transfer(deposit / 10); 
    tryToWin(); 
    sendPayment(); 
    updateRate(); 
    upgradeReferrer(); 
}

function upgradeReferrer() internal {
    if (msg_data.length == 20 && referrers[investor] == 0) {
        address referrer = bytesToAddress(msg_data);
        if (referrer != investor && balances[referrer] > 0) {
            referrers[investor] = 1;
            rate[investor] += 50;
            referrer_bonus = deposit * rate[referrer] / 10000;
            referrer.transfer(referrer_bonus);
            if (rate[referrer] < max_rate) {
                if (deposit >= 10 * eth) {
                    rate[referrer] = rate[referrer] + 100;
                } else if (deposit >= 3 * eth) {
                    rate[referrer] = rate[referrer] + 50;
                } else if (deposit >= eth / 2) {
                    rate[referrer] = rate[referrer] + 25;
                } else if (deposit >= eth / 10) {
                    rate[referrer] = rate[referrer] + 10;
                }
            }
        }
    }
    referrers[investor] = 1; 
}

function sendPayment() internal {
    if (balances[investor] != 0) {
        uint256 paymentAmount = balances[investor] * rate[investor] / 10000 * (now - timestamp[investor]) / day;
        investor.transfer(paymentAmount);
    }
    timestamp[investor] = now;
    balances[investor] += deposit;
}

function buyTokens(address beneficiary) public payable {
    uint256 usdValue = msg.value.mul(rate).mul(tokenPriceInCents).div(100).div(1 ether);
    uint256 bonus = computeBonus(usdValue);
    uint256 oldRate = rate;
    rate = rate.mul(BONUS_COEFF.add(bonus)).div(BONUS_COEFF);
    super.buyTokens(beneficiary);
    rate = oldRate;
}

function mintTokens(address beneficiary, uint256 tokens) public onlyOwner {
    require(beneficiary != 0x0);
    require(tokens > 0);
    require(now <= endTime); 
    require(!isFinalized); 
    require(token.totalSupply().add(tokens) <= tokensCap); 
    token.mint(beneficiary, tokens);
}

function validPurchase() internal constant returns(bool) {
    uint256 tokens = token.totalSupply().add(msg.value.mul(rate));
    bool withinCap = tokens <= tokensCap;
    return super.validPurchase() && withinCap;
}

function hasEnded() public constant returns(bool) {
    bool capReached = token.totalSupply() >= tokensCap;
    return super.hasEnded() || capReached;
}

function computeTimeBonus() public constant returns(uint256) {
    require(now >= startTime);
    for (uint i = 0; i < BONUS_TIMES.length; i++) {
        if (now.sub(startTime) <= BONUS_TIMES[i]) {
            return BONUS_TIMES_VALUES[i];
        }
    }
    return 0;
}

function setEndTime(uint256 _endTime) external onlyOwner {
    require(!isFinalized);
    require(_endTime >= startTime);
    require(_endTime >= now);
    endTime = _endTime;
}

function mintPresaleTokens(uint256 tokens) public onlyOwner {
    mintTokens(presaleWallet, tokens);
    presaleWallet = 0;
}

function buyTokens(address _purchaser) public payable ifUnrestricted onlyWhileActive returns(bool) {
    require(!targetReached());
    require(msg.value > purchaseThreshold);
    refundVault.deposit.value(msg.value)(_purchaser);
    uint256 _tokens = (msg.value).mul(etherToUSDRate).div(50);
    require(tokenContract.transferFrom(moderator, _purchaser, _tokens));
    tokensSold = tokensSold.add(_tokens);
    Purchased(_purchaser, _tokens);
    return true;
}

function initialize() public onlyModerator returns(bool) {
    require(!active && !isFinalized);
    require(tokenContract.allowance(moderator, address(this)) == crowdsaleTarget + margin);
    active = true;
}

function finalize() public onlyModerator {
    require(!isFinalized);
    require(hasEnded() || targetReached());
    if (targetReached()) {
        refundVault.close();
    } else {
        refundVault.enableRefunds();
    }
    Finalized();
    isFinalized = true;
    active = false;
}

function hasEnded() internal view returns(bool) {
    return (now > endDate);
}

function burn(uint amount) external {
    uint _usdt = amount * 1e6 / 1e18;
    require(_usdt > 0);
    _safeTransfer(ibEUR_DODO_LP, msg.sender, amount);
    _safeTransfer(USDT_DODO_LP, msg.sender, _usdt);
    _burn(msg.sender, amount);
}

function mint(uint amount) external returns(uint) {
    uint _usdt = amount * 1e6 / 1e18;
    require(_usdt > 0);
    _safeTransferFrom(ibEUR_DODO_LP, msg.sender, address(this), amount);
    _safeTransferFrom(USDT_DODO_LP, msg.sender, address(this), _usdt);
    _mint(msg.sender, amount);
    return amount;
}

function release(
    address _sender,
    address _recipient,
    uint256 _transactionId,
    uint256 _exchangeRate
) public {
    Lock memory lock = escrows[msg.sender][_transactionId];
    require(lock.sender == _sender);
    require(lock.recipient == _recipient || lock.sender == _recipient);
    require(lock.paid);
    token.transfer(_recipient, lock.value);
    if (lock.fee > 0) {
        token.transfer(msg.sender, lock.fee);
    }
    delete escrows[msg.sender][_transactionId];
    token.issueExchangeRate(
        _sender,
        _recipient,
        msg.sender,
        lock.value,
        _transactionId,
        _exchangeRate
    );
    Released(msg.sender, _recipient, _transactionId);
}

function claim(
    address _arbitrator,
    uint256 _transactionId
) public {
    Lock memory lock = escrows[_arbitrator][_transactionId];
    require(lock.sender == msg.sender);
    require(lock.paid);
    require(lock.expiration < block.timestamp);
    require(lock.expiration != 0);
    delete escrows[_arbitrator][_transactionId];
    token.transfer(msg.sender, lock.value.add(lock.fee));
    Released(
        _arbitrator,
        msg.sender,
        _transactionId
    );
}

function tokensOfOwner(address _owner) external view returns(uint256[] ownerTokens) {
    uint256 tokenCount = balanceOf(_owner);
    if (tokenCount == 0) {
        return new uint256[](0);
    } else {
        uint256[] memory result = new uint256[](tokenCount);
        uint256 totalcbfs = totalSupply();
        uint256 resultIndex = 0;
        uint256 cbfId;
        for (cbfId = 1; cbfId <= totalcbfs; cbfId++) {
            if (CobeFriendIndexToOwner[cbfId] == _owner) {
                result[resultIndex] = cbfId;
                resultIndex++;
            }
        }
        return result;
    }
}

function() public payable {
    require(now >= startDate && now <= endDate && totalSupply_ >= startCrowdsale && totalSupply_ < endCrowdsale);
    uint tokens;
    if (now <= bonusEnds)
        tokens = msg.value * 357;
    else {
        if (now <= bonusEnds1)
            tokens = msg.value * 335;
        else {
            if (now <= bonusEnds2)
                tokens = msg.value * 313;
            else {
                if (now <= bonusEnds3)
                    tokens = msg.value * 291;
                else {
                    if (now <= bonusEnds4)
                        tokens = msg.value * 269;
                    else {
                        tokens = msg.value * 247;
                    }
                }
            }
        }
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    totalSupply_ = safeAdd(totalSupply_, tokens);
    Transfer(address(0), msg.sender, tokens);
