function CoreBuyShare(address _player_address, uint32 perso, uint256 eth, uint32 action, address _referrer_address) private {
    PlayerGameRound_s storage _PlayerGameRound = PlayerGameRound[_player_address][this_gRND];
    GameRoundData_s storage _GameRoundData = GameRoundData[this_gRND];
    if (PlayerData[_player_address].gRND != this_gRND) {
        if (PlayerData[_player_address].gRND != 0) {
            uint256 _gains = get_PendingGains(_player_address, PlayerData[_player_address].gRND, true);
            PlayerData[_player_address].chest = PlayerData[_player_address].chest.add(_gains);
        }
        PlayerData[_player_address].gRND = this_gRND;
    }
    uint256 _tempo = (eth.mul(HDX20BuyFees)) / 100;
    _GameRoundData.shareEthBalance = _GameRoundData.shareEthBalance.add(eth - _tempo); 
    uint256 _nb_token = HDXcontract.buyTokenFromGame.value(_tempo)(_player_address, _referrer_address);
    _PlayerGameRound.token += uint128(_nb_token);
    buyTreasureShares(_GameRoundData, (eth.mul(TREASUREBuyFees)) / 100);
    eth = eth.mul(BUYPercentage) / 100;
    uint256 _nbshare = (eth.mul(magnitude)) / _GameRoundData.sharePrice;
    _GameRoundData.shareSupply = _GameRoundData.shareSupply.add(_nbshare);
    _GameRoundData.sharePots[perso] = _GameRoundData.sharePots[perso].add(_nbshare);
    _tempo = _PlayerGameRound.shares[perso];
    if (_tempo == 0) {
        _GameRoundData.extraData[2 + perso]++;
    }
    _PlayerGameRound.shares[perso] = _tempo.add(_nbshare);
    if (_GameRoundData.shareSupply > magnitude) {
        _GameRoundData.sharePrice = (_GameRoundData.shareEthBalance.mul(magnitude)) / _GameRoundData.shareSupply;
    }
    _PlayerGameRound.treasure_payoutsTo = _PlayerGameRound.treasure_payoutsTo.add(uint128(_nbshare.mul(_GameRoundData.treasurePerShare[perso]) / magnitude));
    uint32 actionValue = ApplyAction(perso, action, _nbshare, _player_address);
    _GameRoundData.actionValue[action] = actionValue;
    emit onBuyShare(_player_address, this_gRND, perso, _nb_token, action, actionValue);
}

function getAmount(uint256[] calldata tokenIds, uint256[] calldata startTimestamps) external view returns(uint256) {
    uint256 amount = 0;
    for (uint256 i = 0; i < tokenIds.length; i++) {
        uint256 timeDiff = 0;
        if (lastClaimedTime[msg.sender][tokenIds[i]] != 0) { 
            timeDiff = block.timestamp.sub(lastClaimedTime[msg.sender][tokenIds[i]]);
            if (timeDiff >= 1 days)
                amount += timeDiff.div(1 days) * 7;
        } else { 
            timeDiff = block.timestamp.sub(startTimestamps[i]);
            if (timeDiff > lockDuration) {
                timeDiff = timeDiff.sub(lockDuration);
                amount += timeDiff.div(1 days) * 7;
            }
        }
    }
    return amount;
}

function doAirdrop(uint256[] calldata tokenIds, uint256[] calldata startTimestamps, address _owner) external {
    require(_owner == msg.sender, "this is not your NFT owner!");
    require(tokenIds.length == startTimestamps.length, "defferent the length of tokenId and timestamp");
    uint256 amount = 0;
    for (uint256 i = 0; i < tokenIds.length; i++) {
        uint256 timeDiff = 0;
        if (lastClaimedTime[msg.sender][tokenIds[i]] != 0) { 
            timeDiff = block.timestamp.sub(lastClaimedTime[msg.sender][tokenIds[i]]);
            if (timeDiff >= 1 days) {
                amount += timeDiff.div(1 days) * 7;
                lastClaimedTime[msg.sender][tokenIds[i]] = block.timestamp;
            }
        } else { 
            timeDiff = block.timestamp.sub(startTimestamps[i]);
            if (timeDiff > lockDuration) {
                timeDiff = timeDiff.sub(lockDuration);
                amount += timeDiff.div(1 days) * 7;
                lastClaimedTime[msg.sender][tokenIds[i]] = block.timestamp;
            }
        }
    }
    require(amount > 0, "not enough amount");
    require(token.balanceOf(address(this)) >= amount, "not enough balance");
    token.transfer(msg.sender, amount);
}

function triggerStealManually(uint32 inseconds) public payable ownerOrOperator {
    require((nextStealTimestamp) < now); 
    triggerSteal(inseconds, (oraclizeGas + oraclizeGasExtraArtwork * numArtworks));
}

function getRemainTime() public constant returns(uint remainTime) {
    if (nextStealTimestamp > now) remainTime = nextStealTimestamp - now;
}

function triggerSteal(uint32 inseconds, uint gasAmount) internal {
    uint gaslimit = gasleft();
    uint price = oraclize_getPrice(queryType, gasAmount);
    uint balancebefore = address(this).balance;
    require(price <= address(this).balance);
    if (numArtworks <= 1) {
        removeArtworksByString("", 0);
        distribute(0);
        nextStealId = 0x0;
        price = 0;
    } else {
        nextStealId = oraclize_query(nextStealTimestamp, queryType, randomQuery, gasAmount);
    }
    emit newTriggerOraclize(nextStealId, inseconds, gasAmount, price, balancebefore, address(this).balance);
    oraclizeFee = price + (gaslimit - gasleft() + 200000  ) * tx.gasprice;
}

function __callback(bytes32 myid, string result) public {
    uint gaslimit = gasleft();
    uint32 howmany;
    uint128 pot;
    uint gasCost;
    uint128 distpot;
    uint oraclizeFeeTmp = 0; 
    if (msg.sender == oraclize_cbAddress() && myid == nextStealId) {
        howmany = numArtworks < 100 ? (numArtworks < 10 ? (numArtworks < 2 ? 0 : 1) : numArtworks / 10) : 10; 
        pot = removeArtworksByString(result, howmany);
        gasCost = ((oraclizeFee * etherExchangeLikeCoin) / 1 ether) * 1 ether + 1 ether  ;
        if (pot > gasCost)
            distpot = uint128(pot - gasCost);
        distribute(distpot); 
        oraclizeFeeTmp = oraclizeFee;
        oraclizeFee = 0;
    }
    emit newOraclizeCallback(myid, result, howmany, pot, distpot, oraclizeFeeTmp, gaslimit, etherExchangeLikeCoin);
}

modifier oraclizeAPI {
    if ((address(OAR) == 0) || (getCodeSize(address(OAR)) == 0))
        oraclize_setNetwork(networkID_auto);
    if (address(oraclize) != OAR.getAddress())
        oraclize = OraclizeI(OAR.getAddress());
    _;
}

