function _ltvV(address token) internal view returns(uint, bool) {
    if (block.timestamp > _ltvCaches[token]) {
        uint _max = 0;
        uint _tmp = _getLTVIB(token);
        if (_tmp > _max) {
            _max = _tmp;
        }
        _tmp = _getLTVAaveV2(token);
        if (_tmp > _max) {
            _max = _tmp;
        }
        _tmp = _getLTVUnit(token);
        if (_tmp > _max) {
            _max = _tmp;
        }
        _max = _max / 5 * 5;
        if (_max < 60) {
            _max = 0;
        }
        return (_max, true);
    } else {
        return (ltvs[token], false);
    }
}

function _liquidity(address token, uint amount) internal returns(uint) {
    if (_liquidityCaches[token] == 0) {
        liquidities[token] = _minLiquidity;
    }
    (uint _val, bool _updated) = _liquidityV(token, amount);
    if (_updated) {
        _liquidityCaches[token] = block.timestamp + _CACHE;
        liquidities[token] = _val;
    }
    return _val;
}

function _liquidityV(address token, uint amount) internal view returns(uint, bool) {
    if (block.timestamp > _liquidityCaches[token]) {
        if (token == _weth) {
            return (_liquidityVWETH(amount), true);
        } else {
            address[] memory _path = new address[](3);
            _path[0] = token;
            _path[1] = _weth;
            _path[2] = _stable;
            uint _liq = SushiswapV2Router02(_router).getAmountsOut(amount, _path)[2];
            uint _liquid = liquidities[token];
            if (_liq > _liquid) {
                _liquid += _liquid * _LIQUIDITY_THRESHOLD / _BASE;
                _liq = Math.min(_liq, _liquid);
                _liq = _liq < _minLiquidity ? _minLiquidity : _liq;
            }
            return (_liq, true);
        }
    } else {
        return (liquidities[token], false);
    }
}

function _mint(address asset, uint amount, uint minted, address recipient) internal {
    if (amount > 0) {
        _safeTransferFrom(asset, msg.sender, address(this), amount);
    }
    collateral[msg.sender][asset] += amount;
    collaterals[asset] += amount;
    credit[msg.sender][asset] += minted;
    credits[asset] += minted;
    require(_liquidity(asset, collaterals[asset]) >= credits[asset]);
    require(_lookup(asset, collateral[msg.sender][asset]) >= credit[msg.sender][asset]);
    _mint(recipient, minted);
    emit Mint(msg.sender, asset, recipient, amount);
}

function _burnArb(uint amount, address recipient) internal {
    _burn(msg.sender, amount);
    _safeTransfer(_stable, recipient, amount);
    arb -= amount;
    emit Burn(msg.sender, _stable, recipient, amount);
}

function _mintArb(uint amount, address recipient) internal {
    _safeTransferFrom(_stable, msg.sender, address(this), amount);
    _mint(recipient, amount);
    arb += amount;
    emit Mint(msg.sender, _stable, recipient, amount);
}

function endLottery() public {
    require(now > end && end != 0);
    uint256 cudlBalance = cudl.balanceOf(address(this));
    end = 0;
    start = 0;
    winner1 = players[currentRound][
        randomNumber(block.number, players[currentRound].length)
    ];
    IERC721(0xc3f733ca98E0daD0386979Eb96fb1722A1A05E69).safeTransferFrom(
        address(this),
        winner1,
        nftOriginId
    );
    winner2 = players[currentRound][
        randomNumber(block.number - 1, players[currentRound].length)
    ];
    require(cudl.transfer(winner2, cudlBalance.mul(37).div(100)));
    winner3 = players[currentRound][
        randomNumber(block.number - 3, players[currentRound].length)
    ];
    require(cudl.transfer(winner3, cudlBalance.mul(19).div(100)));
    winner4 = players[currentRound][
        randomNumber(block.number - 4, players[currentRound].length)
    ];
    require(cudl.transfer(winner4, cudlBalance.mul(19).div(100)));
    cudl.burn(cudl.balanceOf(address(this)));
    emit LotteryEnded(
        currentRound,
        currentPet,
        cudlBalance,
        winner1,
        winner2,
        winner3,
        winner4
    );
}

function buyTicket(address _player) external {
    require(start != 0, "The lottery did not start yet");
    if (now > end) {
        endLottery();
        return;
    }
    uint256 lastTimeMined = cudlFinance.lastTimeMined(currentPet);
    uint8 tickets = 1;
    require(
        cudl.transferFrom(
            msg.sender,
            address(this),
            cudlFinance.itemPrice(food)
        )
    );
    cudlFinance.buyAccesory(currentPet, food);
    if (lastTimeMined + 1 days < now) {
        cudlFinance.claimMiningRewards(currentPet);
        tickets = 2;
    }
    for (uint256 i = 0; i < tickets; i++) {
        players[currentRound].push(_player);
        ticketsByPlayers[currentRound][_player] =
            ticketsByPlayers[currentRound][_player] +
            1;
    }
    emit LotteryTicketBought(_player, tickets);
}

function startLottery(
    uint256 _food,
    uint256 _days,
    uint256 _petId,
    uint256 _nftOriginId
) external {
    require(msg.sender == owner, "!owner");
    food = _food;
    currentRound = currentRound + 1;
    end = now + _days * 1 days;
    start = now;
    cudl.approve(address(cudlFinance), MAX_INT);
    currentPet = _petId;
    nftOriginId = _nftOriginId;
    emit LotteryStarted(currentRound, start, end, currentPet, food);
}

