function _spinTokens(TKN _tkn, uint divRate, uint8 spins)
private gameIsActive
betIsValid(_tkn.value, divRate, spins) {
    require(block.number <= ((2 ** 48) - 1)); 
    require(_tkn.value <= ((2 ** 192) - 1));
    require(divRate < (2 ** 8 - 1)); 
    address _customerAddress = _tkn.sender;
    uint _wagered = _tkn.value;
    playerSpin memory spin = playerSpins[_tkn.sender];
    addContractBalance(divRate, _wagered);
    require(block.number != spin.blockn);
    if (spin.blockn != 0) {
        _finishSpin(_tkn.sender);
    }
    spin.blockn = uint48(block.number);
    spin.tokenValue = uint192(_wagered.div(spins));
    spin.tier = uint8(ZethrTierLibrary.getTier(divRate));
    spin.divRate = divRate;
    spin.spins = spins;
    playerSpins[_tkn.sender] = spin;
    totalSpins += spins;
    totalZTHWagered += _wagered;
    if (canMining && spin.tokenValue >= minBetMining) {
        uint miningAmout = SafeMath.div(SafeMath.mul(_wagered, miningProfit), 10000);
        RequestBankrollPayment(_tkn.sender, miningAmout, spin.divRate);
    }
    emit TokensWagered(_customerAddress, _wagered);
}

function checkPermissions(address _address) internal view returns(bool) {
    if ((_address == adrInvestor || _address == adrDevTeam) && (block.timestamp < ITSEndTime)) {
        return false;
    } else if ((block.timestamp < unlockTimeF1) && (_address == adrFounder1)) {
        return false;
    } else if ((block.timestamp < unlockTimeF2) && (_address == adrFounder2)) {
        return false;
    } else if (_address == owner) {
        return true;
    } else if (block.timestamp < ITSEndTime) {
        return false;
    } else {
        return true;
    }
}

function preValidatePurchase(uint256 _amount) internal {
    require(_amount > 0);
    require(isOfferingStarted);
    require(offeringEnabled);
    require(currentTokenOfferingRaised.add(_amount) <= currentTotalTokenOffering);
    require(block.timestamp >= startTime && block.timestamp <= endTime);
}

function startOffering(
    uint256 _tokenOffering,
    uint256 _bonusRateOneEth,
    uint256 _startTime,
    uint256 _endTime,
    bool _isBurnInClose
) public onlyOwner returns(bool) {
    require(_tokenOffering <= balances[owner]);
    require(_startTime <= _endTime);
    require(_startTime >= block.timestamp);
    require(!isOfferingStarted);
    isOfferingStarted = true;
    startTime = _startTime;
    endTime = _endTime;
    isBurnInClose = _isBurnInClose;
    currentTokenOfferingRaised = 0;
    currentTotalTokenOffering = _tokenOffering;
    offeringEnabled = true;
    setBonusRate(_bonusRateOneEth);
    emit OfferingOpens(startTime, endTime, currentTotalTokenOffering, bonusRateOneEth);
    return true;
}

function updateStartTime(uint256 _startTime) public onlyOwner {
    require(isOfferingStarted);
    require(_startTime <= endTime);
    require(_startTime >= block.timestamp);
    startTime = _startTime;
}

function addUserVestingInfo(address _address, uint256 _totalAmount) public {
    require(msgSender == msg.sender, "You do not have permission to operate");
    require(_address != address(0), "The lock address cannot be a black hole address");
    UserVestingInfo storage _userVestingInfo = UserVesting[_address];
    require(_totalAmount > 0, "Lock up amount cannot be 0");
    require(_userVestingInfo.totalAmount == 0, "Lock has been added");
    _userVestingInfo.totalAmount = _totalAmount.mul(10 ** tokenDecimals);
    _userVestingInfo.firstAmount = _userVestingInfo.totalAmount.mul(10).div(100); 
    _userVestingInfo.secondUnlock = _userVestingInfo.totalAmount.sub(_userVestingInfo.firstAmount).div(maxUnlockTimes);
    unlockAmountTotal = unlockAmountTotal.add(_userVestingInfo.totalAmount);
}

function buyVip() public payable {
    uint8 addP = uint8(msg.value / vipBasePrice);
    uint8 oldP = _vipPowerMap[msg.sender];
    uint8 newP = oldP + addP;
    require(newP > 0, "vip level over min");
    require(newP <= 5, "vip level over max");
    require(addP * vipBasePrice == msg.value, "1 to 5 ether only");
    totalVipCount[newP - 1] = totalVipCount[newP - 1] + 1;
    if (oldP > 0) {
        totalVipCount[oldP - 1] = totalVipCount[oldP - 1] - 1;
    }
    _vipPowerMap[msg.sender] = newP;
    doVipLevelProfit(oldP, addP);
    emit BuyVip(msg.sender, msg.value);
}

