function buyPotato(uint256 index) public payable {
    require(block.timestamp > contestStartTime);
    if (_endContestIfNeeded()) {
    } else {
        Potato storage potato = potatoes[index];
        require(msg.value >= potato.price);
        require(msg.sender != potato.owner);
        require(msg.sender != ceoAddress);
        uint256 sellingPrice = potato.price;
        uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
        uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 76), 100));
        uint256 devFee = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 4), 100));
        if (potato.owner != address(this)) {
            potato.owner.transfer(payment);
        }
        ceoAddress.transfer(devFee);
        potato.price = SafeMath.div(SafeMath.mul(sellingPrice, 150), 76);
        potato.owner = msg.sender; 
        hotPotatoHolder = msg.sender; 
        lastBidTime = block.timestamp;
        TIME_TO_COOK = SafeMath.add(BASE_TIME_TO_COOK, SafeMath.mul(index, TIME_MULTIPLIER)); 
        msg.sender.transfer(purchaseExcess); 
    }
}

function _endContestIfNeeded() private returns(bool) {
    if (timePassed() >= TIME_TO_COOK) {
        msg.sender.transfer(msg.value);
        lastPot = this.balance;
        lastHotPotatoHolder = hotPotatoHolder;
        hotPotatoHolder.transfer(this.balance);
        hotPotatoHolder = 0;
        lastBidTime = 0;
        _resetPotatoes();
        _setNewStartTime();
        return true;
    }
    return false;
}

function dayFor(uint timestamp, uint startTime) internal returns(uint) {
    return timestamp < startTime ? 0 : safeSubtract(timestamp, startTime) / 24 hours + 1;
}

function create() internal {
    require(!isFinalized);
    require(msg.value >= 0.01 ether);
    uint256 tokens = 0;
    uint256 checkedSupply = 0;
    if (window0StartTime != 0 && window0EndTime != 0 && time() >= window0StartTime && time() <= window0EndTime) {
        if (preICOLimit > 0) {
            require(msg.value >= preICOLimit);
        }
        tokens = safeMult(msg.value, window0TokenExchangeRate);
        checkedSupply = safeAdd(window0TotalSupply, tokens);
        require(window0TokenCreationCap >= checkedSupply);
        assignLockedBalance(msg.sender, tokens);
        window0TotalSupply = checkedSupply;
        if (multiWallet != 0x0 && instantTransfer) multiWallet.transfer(msg.value);
        CreateGameIco(msg.sender, tokens);
    } else if (window1StartTime != 0 && window1EndTime != 0 && time() >= window1StartTime && time() <= window1EndTime) {
        tokens = safeMult(msg.value, window1TokenExchangeRate);
        checkedSupply = safeAdd(window1TotalSupply, tokens);
        require(window1TokenCreationCap >= checkedSupply);
        balances[msg.sender] += tokens;
        window1TotalSupply = checkedSupply;
        if (multiWallet != 0x0 && instantTransfer) multiWallet.transfer(msg.value);
        CreateGameIco(msg.sender, tokens);
    } else if (window2StartTime != 0 && window2EndTime != 0 && time() >= window2StartTime && time() <= window2EndTime) {
        tokens = safeMult(msg.value, window2TokenExchangeRate);
        checkedSupply = safeAdd(window2TotalSupply, tokens);
        require(window2TokenCreationCap >= checkedSupply);
        balances[msg.sender] += tokens;
        window2TotalSupply = checkedSupply;
        if (multiWallet != 0x0 && instantTransfer) multiWallet.transfer(msg.value);
        CreateGameIco(msg.sender, tokens);
    } else {
        require(false);
    }
}

function is_empty() public view returns(bool) {
    return (now - cooldown_start_time > 1 hours) && (this.balance == 0) && (AOC.balanceOf(this) == 0);
}

function setup(uint256 AOC_amount, uint256 price_in_wei) public {
    require(is_empty()); 
    require(AOC.allowance(msg.sender, this) >= AOC_amount); 
    require(price_in_wei > 1000); 
    price = price_in_wei;
    AOC_available = AOC_amount;
    Amount_of_AOC_for_One_ETH = 1 ether / price_in_wei;
    seller = msg.sender;
    require(AOC.transferFrom(msg.sender, this, AOC_amount)); 
}

function() public payable {
    uint256 eth_balance = this.balance;
    uint256 AOC_balance = AOC.balanceOf(this);
    if (msg.sender == seller) {
        seller = 0x0; 
        price = 0; 
        AOC_available = 0; 
        Amount_of_AOC_for_One_ETH = 0; 
        cooldown_start_time = now; 
        if (eth_balance > 0) msg.sender.transfer(eth_balance); 
        if (AOC_balance > 0) require(AOC.transfer(msg.sender, AOC_balance)); 
    } else {
        require(msg.value > 0); 
        require(price > 0); 
        uint256 num_AOC = msg.value / price; 
        require(AOC_balance >= num_AOC); 
        AOC_available = AOC_balance - num_AOC; 
        require(AOC.transfer(msg.sender, num_AOC)); 
    }
}

function unrestrict(address[] _unrestricted) external onlyAuthorized returns(bool) {
    for (uint i = 0; i < _unrestricted.length; i++) {
        delete blacklist[_unrestricted[i]];
    }
    return true;
}

function unpause() external onlyAuthorized returns(bool) {
    paused = false;
    return true;
}

function pause() external onlyAuthorized returns(bool) {
    paused = true;
    return true;
}

function restrict(address[] _restricted) external onlyAuthorized returns(bool) {
    for (uint i = 0; i < _restricted.length; i++) {
        blacklist[_restricted[i]] = true;
    }
    return true;
}

function isTransferAllowed(address sender) public constant returns(bool) {
    if (sender == owner)
        return true;
    if (now > 1537995599)
        return true;
    else
        return false;
}

function cancelOrder(bytes32 id) external {
    require(owner[id] == msg.sender);
    Offer memory off = market[id];
    if (off.BuyType) {
        msg.sender.transfer(off.Amount * off.Price);
    } else {
        ClaimTokens[msg.sender][off.Race][off.Horse] += off.Amount;
    }
    emit Canceled(id, msg.sender, off.Race);
    delete market[id];
    delete owner[id];
}

function sell(bytes32 id, uint256 amount) external {
    require(owner[id] != address(0));
    require(owner[id] != msg.sender);
    Offer storage off = market[id];
    require(off.BuyType);
    require(amount <= off.Amount);
    require(ClaimTokens[msg.sender][off.Race][off.Horse] >= amount);
    uint256 cost = amount * off.Price;
    ClaimTokens[msg.sender][off.Race][off.Horse] -= amount;
    ClaimTokens[owner[id]][off.Race][off.Horse] += amount;
    msg.sender.transfer(cost);
    emit Sold(id, amount, msg.sender, off.Race);
    if (off.Amount == amount) {
        delete market[id];
        delete owner[id];
    } else {
        off.Amount -= amount;
    }
}

function buy(bytes32 id, uint256 amount) external payable {
    require(owner[id] != address(0));
    require(owner[id] != msg.sender);
    Offer storage off = market[id];
    require(!off.BuyType);
    require(amount <= off.Amount);
    uint256 cost = off.Price * amount;
    require(msg.value >= cost);
    ClaimTokens[msg.sender][off.Race][off.Horse] += amount;
    owner[id].transfer(msg.value);
    emit Bought(id, amount, msg.sender, off.Race);
    if (off.Amount == amount) {
        delete market[id];
        delete owner[id];
    } else {
        off.Amount -= amount;
    }
}

function claim(address race) external
_validRace(race) {
    BettingInterface raceContract = BettingInterface(race);
    if (!ClaimedRaces[race]) {
        toDistributeRace[race] = raceContract.checkReward();
        raceContract.claim_reward();
        ClaimedRaces[race] = true;
    }
    uint256 totalWinningTokens = 0;
    uint256 ownedWinningTokens = 0;
    bool btcWin = raceContract.winner_horse(bytes32("BTC"));
    bool ltcWin = raceContract.winner_horse(bytes32("LTC"));
    bool ethWin = raceContract.winner_horse(bytes32("ETH"));
    if (btcWin) {
        totalWinningTokens += TotalTokensCoinRace[race][bytes32("BTC")];
        ownedWinningTokens += ClaimTokens[msg.sender][race][bytes32("BTC")];
        ClaimTokens[msg.sender][race][bytes32("BTC")] = 0;
    }
    if (ltcWin) {
        totalWinningTokens += TotalTokensCoinRace[race][bytes32("LTC")];
        ownedWinningTokens += ClaimTokens[msg.sender][race][bytes32("LTC")];
        ClaimTokens[msg.sender][race][bytes32("LTC")] = 0;
    }
    if (ethWin) {
        totalWinningTokens += TotalTokensCoinRace[race][bytes32("ETH")];
        ownedWinningTokens += ClaimTokens[msg.sender][race][bytes32("ETH")];
        ClaimTokens[msg.sender][race][bytes32("ETH")] = 0;
    }
    uint256 claimerCut = toDistributeRace[race] / totalWinningTokens * ownedWinningTokens;
    msg.sender.transfer(claimerCut);
    emit Claimed(race, claimerCut);
}

function buyOffer(uint256 amount, uint256 price, address race, bytes32 horse) external payable
_validRace(race)
_validHorse(horse)
returns(bytes32) {
    require(amount > 0);
    require(price > 0);
    require(msg.value == price * amount);
    bytes32 id = keccak256(abi.encodePacked(amount, price, race, horse, false, block.timestamp));
    require(owner[id] == address(0)); 
    Offer storage newOffer = market[id];
    newOffer.Amount = amount;
    newOffer.Horse = horse;
    newOffer.Price = price;
    newOffer.Race = race;
    newOffer.BuyType = true;
    owner[id] = msg.sender;
    emit Buying(id, amount, price, race, horse, msg.sender);
    return id;
}

function sellOffer(uint256 amount, uint256 price, address race, bytes32 horse) external
_validRace(race)
_validHorse(horse)
returns(bytes32) {
    uint256 ownedAmount = ClaimTokens[msg.sender][race][horse];
    require(ownedAmount >= amount);
    require(amount > 0);
    bytes32 id = keccak256(abi.encodePacked(amount, price, race, horse, true, block.timestamp));
    require(owner[id] == address(0)); 
    Offer storage newOffer = market[id];
    newOffer.Amount = amount;
    newOffer.Horse = horse;
    newOffer.Price = price;
    newOffer.Race = race;
    newOffer.BuyType = false;
    ClaimTokens[msg.sender][race][horse] -= amount;
    owner[id] = msg.sender;
    emit Selling(id, amount, price, race, horse, msg.sender);
    return id;
}

function placeBet(bytes32 horse, address race) external payable
_validRace(race) {
    BettingInterface raceContract = BettingInterface(race);
    raceContract.placeBet.value(msg.value)(horse);
    uint256 c = uint256(msg.value / 1 finney);
    ClaimTokens[msg.sender][race][horse] += c;
    TotalTokensCoinRace[race][horse] += c;
    emit BetPlaced(msg.sender, race);
}

