function purchase() public canPurchase payable returns(bool success) {
    require(msg.sender != address(0)); 
    Member storage memberRecord = members[msg.sender];
    Group storage openGroup = groups[openGroupNumber];
    require(openGroup.ratio > 0); 
    uint256 currentTimestamp = block.timestamp;
    require(currentTimestamp >= openGroup.startTime && currentTimestamp <= openGroup.deadline); 
    require(!openGroup.distributing && !openGroup.distributed); 
    require(tx.gasprice <= maxGasPrice); 
    uint256 weiAmount = msg.value; 
    require(weiAmount >= 0.1 ether);
    uint256 weiTotal = openGroup.weiTotal.add(weiAmount); 
    require(weiTotal <= openGroup.cap); 
    uint256 userWeiTotal = memberRecord.weiBalance[openGroupNumber].add(weiAmount); 
    if (!openGroup.exists[msg.sender]) { 
        openGroup.addresses.push(msg.sender);
        openGroup.exists[msg.sender] = true;
    }
    if (currentTimestamp <= openGroup.phase1endTime) { 
        emit WantsToPurchase(msg.sender, weiAmount, openGroupNumber, true);
        return true;
    } else if (currentTimestamp <= openGroup.phase2endTime) { 
        require(userWeiTotal <= openGroup.max2); 
        emit WantsToPurchase(msg.sender, weiAmount, openGroupNumber, false);
        return true;
    } else { 
        require(userWeiTotal <= openGroup.max3); 
        emit WantsToPurchase(msg.sender, weiAmount, openGroupNumber, false);
        return true;
    }
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether;
    uint256 bonusCond2 = 1 ether * 5;
    uint256 bonusCond3 = 1 ether * 10;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 30 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 40 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 50 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 20 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 30 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 40 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 12500e8;
        if (Claimed[investor] == false && progress0drop < target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
}

function() public payable {
    require(!ico_finish);
    require(block.timestamp < fundingEndTime);
    require(msg.value != 0);
    totalEthInWei = totalEthInWei + msg.value;
    uint256 amount = 0;
    uint256 tokenPrice = unitsOneEthCanBuy;
    if (block.timestamp < preIcoFinishTimestamp) {
        require(msg.value * tokenPrice * 13 / 10 <= (preIcoTotalSupply - preIcoSupply));
        tokenPrice = safeMul(tokenPrice, 13);
        tokenPrice = safeDiv(tokenPrice, 10);
        amount = safeMul(msg.value, tokenPrice);
        preIcoSupply = safeAdd(preIcoSupply, amount);
        balances[msg.sender] = safeAdd(balances[msg.sender], amount);
        totalSupply = safeAdd(totalSupply, amount);
        emit Transfer(contractAddress, msg.sender, amount);
    } else {
        require(msg.value * tokenPrice <= (IcoTotalSupply - IcoSupply));
        amount = safeMul(msg.value, tokenPrice);
        IcoSupply = safeAdd(IcoSupply, amount);
        balances[msg.sender] = safeAdd(balances[msg.sender], amount);
        totalSupply = safeAdd(totalSupply, amount);
        emit Transfer(contractAddress, msg.sender, amount);
    }
}

function stopIco() public returns(bool success) {
    if (block.timestamp > fundingEndTime) {
        ico_finish = true;
        return true;
    }
}

function createTokensForCrypton() public returns(bool success) {
    require(ico_finish);
    require(!token_was_created);
    if (block.timestamp > finalTokensIssueTime) {
        uint256 amount = safeAdd(preIcoSupply, IcoSupply);
        amount = safeMul(amount, 3);
        amount = safeDiv(amount, 10);
        balances[fundsWallet] = safeAdd(balances[fundsWallet], amount);
        totalSupply = safeAdd(totalSupply, amount);
        emit Transfer(contractAddress, fundsWallet, amount);
        token_was_created = true;
        return true;
    }
}

function purchase(uint32 _id) payable public {
    uint price = personToPrice[_id];
    address personOwner = personToOwner[_id];
    require(msg.sender != 0x0);
    require(msg.sender != personOwner);
    require(price <= msg.value);
    Person storage person = people[_id];
    if (price < msg.value) {
        msg.sender.transfer(msg.value - price);
    }
    _handlePurchase(person, personOwner, price);
    uint newPrice = _onPersonSale(person);
    if (!isUserAdded[msg.sender]) {
        users.push(msg.sender);
        isUserAdded[msg.sender] = true;
    }
    Purchase(_id, msg.sender, personOwner, price, newPrice);
}

function _handlePurchase(Person storage _person, address _owner, uint _price) internal {
    uint oldPrice = personToOldPrice[_person.id];
    if (_person.discounted) {
        _shareDiscountPrice(_price, _owner);
    } else {
        _shareProfit(_price, oldPrice, _owner);
    }
    personToOwner[_person.id] = msg.sender;
    noOfPersonsOwned[_owner]--;
    noOfPersonsOwned[msg.sender]++;
}

function claimBonus(address user) public {
    require(influencers[msg.sender], "NBUInfluencerBonusPart: Not influencer");
    require(!processedUsers[msg.sender][user], "NBUInfluencerBonusPart: Bonus for user already received");
    require(referralProgram.userSponsorByAddress(user) == referralProgram.userIdByAddress(msg.sender), "NBUInfluencerBonusPart: Not user sponsor");
    uint amount;
    for (uint i; i < stakingPools.length; i++) {
        amount = amount.add(stakingPools[i].balanceOf(user));
    }
    address[] memory path = new address[](2);
    path[0] = swapToken;
    path[1] = address(NBU);
    uint minNbuAmountForBonus = swapRouter.getAmountsOut(swapTokenAmountForBonusThreshold, path)[1];
    require(amount >= minNbuAmountForBonus, "NBUInfluencerBonusPart: Bonus threshold not met");
    NBU.transfer(msg.sender, nbuBonusAmount);
    processedUsers[msg.sender][user] = true;
    emit ProcessInfluencerBonus(msg.sender, user, amount, nbuBonusAmount);
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = sceneIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = sceneIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 80), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    Scene memory _scene = scenes[_tokenId];
    require(_scene.stars.length > 0); 
    uint256 holderFee = uint256(SafeMath.div(SafeMath.div(SafeMath.mul(sellingPrice, 10), 100), _scene.stars.length));
    uint256 awardOwnerFee = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 4), 100));
    if (sellingPrice < firstStepLimit) {
        sceneIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 80);
    } else if (sellingPrice < secondStepLimit) {
        sceneIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 80);
    } else {
        sceneIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 80);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    _paySceneStarOwners(_scene, holderFee);
    _payAwardOwner(awardOwnerFee);
    TokenSold(_tokenId, sellingPrice, sceneIndexToPrice[_tokenId], oldOwner, newOwner, _scene.name, _scene.stars);
    msg.sender.transfer(purchaseExcess);
}

