function startPhase(uint _phase, uint _currentPhaseRate, uint256 _startsAt, uint256 _endsAt) external onlyOwner {
    require(_phase >= 0 && _phase <= 2);
    require(_startsAt > endsAt && _endsAt > _startsAt);
    require(_currentPhaseRate > 0);
    currentPhase = CurrentPhase(_phase);
    currentPhaseAddress = getPhaseAddress();
    assert(currentPhaseAddress != 0x0);
    currentPhaseRate = _currentPhaseRate;
    if (currentPhase == CurrentPhase.Privatesale) ethMin = numToWei(10, decimals);
    else {
        ethMin = 0;
        ethMax = numToWei(15, decimals);
    }
    startsAt = _startsAt;
    endsAt = _endsAt;
    TokenPhaseStarted(currentPhase, startsAt, endsAt);
}

function buyTokens(address _to) tokenPhaseIsActive whenNotPaused payable {
    require(whitelist[_to]);
    require(msg.value >= ethMin && msg.value <= ethMax);
    require(_to != 0x0);
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(currentPhaseRate);
    if (currentPhase == CurrentPhase.Privatesale) tokens = tokens.add(tokens);
    weiRaised = weiRaised.add(weiAmount);
    wallet.transfer(weiAmount);
    if (!token.transferFromTokenSell(_to, currentPhaseAddress, tokens)) revert();
    TokenPurchased(_to, tokens, weiAmount);
}

function finalizeIto(uint256 _burnAmount, uint256 _ecoAmount, uint256 _airdropAmount) external onlyOwner {
    token.finalizeCrowdsale(numToWei(_burnAmount, decimals), numToWei(_ecoAmount, decimals), numToWei(_airdropAmount, decimals));
    endsAt = block.timestamp;
    currentPhase = CurrentPhase.None;
    TokenPhaseEnded(currentPhase);
}

function finalizePhase() external onlyOwner {
    if (currentPhase == CurrentPhase.Privatesale) token.finalizePrivatesale();
    else if (currentPhase == CurrentPhase.Presale) token.finalizePresale();
    endsAt = block.timestamp;
    currentPhase = CurrentPhase.None;
    TokenPhaseEnded(currentPhase);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
isNotInICO()
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!inICO && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    emit Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function purchaseTokensInICO(uint256 _incomingEthereum, address _referredBy)
isInICO()
ceilingNotReached()
internal
returns(uint256) {
    address _customerAddress = msg.sender;
    uint256 _oldFundETH = okamiFunds_[_customerAddress];
    require(_incomingEthereum > 0, "no money");
    require((_oldFundETH >= okamiMinPurchase_) || _incomingEthereum >= okamiMinPurchase_, "min 5 eth");
    require(SafeMath.add(_oldFundETH, _incomingEthereum) <= okamiMaxPurchase_, "max 10 eth");
    uint256 _newFundETH = _incomingEthereum;
    if (SafeMath.add(_newFundETH, okamiCurrentPurchase_) > okamiTotalPurchase_) {
        _newFundETH = SafeMath.sub(okamiTotalPurchase_, okamiCurrentPurchase_);
        msg.sender.transfer(SafeMath.sub(_incomingEthereum, _newFundETH));
    }
    uint256 _amountOfTokens = SafeMath.mul(SafeMath.div(_newFundETH, icoPrice_), 10 ** 18);
    tokenSupply_ = SafeMath.add(tokenSupply_, _amountOfTokens);
    tokenBalanceLedger_[_customerAddress] = SafeMath.add(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    okamiFunds_[_customerAddress] = SafeMath.add(okamiFunds_[_customerAddress], _newFundETH);
    okamiCurrentPurchase_ = SafeMath.add(okamiCurrentPurchase_, _newFundETH);
    if (okamiCurrentPurchase_ >= okamiTotalPurchase_) {
        inICO = false;
    }
    emit onTokenPurchase(_customerAddress, _newFundETH, _amountOfTokens, _referredBy);
}

function STAKE(uint256 tokens) external {
    require(totalStakes < maxAllowed, "MAX AMOUNT REACHED CANNOT STAKE NO MORE");
    require(IERC20(GLXYLP).transferFrom(msg.sender, address(lpLockAddress), tokens), "Tokens cannot be transferred from user for locking");
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = tokens.add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    (bool _isStakeholder) = isStakeholder(msg.sender);
    if (!_isStakeholder) farmTime[msg.sender] = block.timestamp;
    totalStakes = totalStakes.add(tokens);
    addStakeholder(msg.sender);
    emit STAKED(msg.sender, tokens);
}

function initDutchAuction(
    address _token,
    uint256 _tokenSupply,
    uint256 _auctionDuration,
    uint256 _startPrice,
    uint256 _minimumPrice,
    uint256 _withdrawDelay,
    address payable _wallet
)
external onlyOwner {
    require(_auctionDuration > 0, "Auction duration should be longer than 0 seconds");
    require(_startPrice > _minimumPrice, "Start price should be bigger than minimum price");
    require(_minimumPrice > 0, "Minimum price should be bigger than 0");
    auctionToken = IERC20(_token);
    require(IERC20(auctionToken).transferFrom(msg.sender, address(this), _tokenSupply), "Fail to transfer tokens to this contract");
    tokenSupply = _tokenSupply.sub(100000000000000000000);
    startDate = block.timestamp;
    endDate = block.timestamp.add(_auctionDuration);
    startPrice = _startPrice;
    minimumPrice = _minimumPrice;
    withdrawDelay = _withdrawDelay;
    wallet = _wallet;
    finalised = false;
}

function withdrawTokens() public lock {
    require(auctionEnded(), "DutchSwapAuction: Auction still live");
    (bool canWithdraw, ) = checkWithdraw();
    require(canWithdraw == true, "DutchSwapAuction: Withdraw Delay");
    uint256 fundsCommitted = commitments[msg.sender];
    require(fundsCommitted > 0, "You have no bidded tokens");
    uint256 tokensToClaim = tokensClaimable(msg.sender);
    commitments[msg.sender] = 0;
    tokenWithdrawn = tokenWithdrawn.add(tokensToClaim);
    if (tokensToClaim > 0) {
        _tokenPayment(auctionToken, msg.sender, tokensToClaim);
    }
}

function finaliseAuction() public {
    require(!finalised && auctionEnded());
    finalised = true;
    wallet.transfer(amountRaised);
}

function commitEth(address payable _from) public payable lock {
    require(block.timestamp >= startDate && block.timestamp <= endDate);
    uint256 tokensToPurchase = msg.value.mul(TENPOW18).div(priceFunction());
    uint256 tokensPurchased = calculatePurchasable(tokensToPurchase);
    tokenSold = tokenSold.add(tokensPurchased);
    uint256 ethToTransfer = tokensPurchased < tokensToPurchase ? msg.value.mul(tokensPurchased).div(tokensToPurchase) : msg.value;
    uint256 ethToRefund = msg.value.sub(ethToTransfer);
    if (ethToTransfer > 0) {
        addCommitment(_from, ethToTransfer);
    }
    if (ethToRefund > 0) {
        _from.transfer(ethToRefund);
    }
}

function priceFunction() public view returns(uint256) {
    if (block.timestamp <= startDate) {
        return startPrice;
    }
    if (block.timestamp >= endDate) {
        return minimumPrice;
    }
    uint256 priceDiff = block.timestamp.sub(startDate).mul(priceGradient());
    uint256 price = startPrice.sub(priceDiff);
    return price;
}

function getTokenNotYetWithdrawn() public view returns(uint256) {
    if (block.timestamp < endDate) {
        return tokenSold;
    }
    uint256 totalTokenSold = amountRaised.mul(TENPOW18).div(tokenPrice());
    return totalTokenSold.sub(tokenWithdrawn);
}

function auctionEnded() public view returns(bool) {
    return block.timestamp > endDate;
}

function transferLeftOver(uint256 _amount, address payable _addr) external onlyOwner returns(bool) {
    require(block.timestamp > endDate.add(withdrawDelay).add(7 * 24 * 60 * 60), "Cannot transfer auction tokens within 7 days after withdraw day");
    require(_amount > 0, "Cannot transfer 0 tokens");
    _tokenPayment(auctionToken, _addr, _amount);
    return true;
}

function calculatePurchasable(uint256 _tokensToPurchase)
public view returns(uint256) {
    uint256 maxPurchasable = tokenSupply.sub(tokenSold);
    if (_tokensToPurchase > maxPurchasable) {
        return maxPurchasable;
    }
    return _tokensToPurchase;
}

function checkWithdraw() public view returns(bool, uint256) {
    if (block.timestamp < endDate) {
        return (false, endDate.sub(block.timestamp).add(withdrawDelay));
    }
    uint256 _elapsed = block.timestamp.sub(endDate);
    if (_elapsed >= withdrawDelay) {
        return (true, 0);
    } else {
        return (false, withdrawDelay.sub(_elapsed));
    }
}

function _tokenPayment(IERC20 _token, address payable _to, uint256 _amount) internal {
    require(_token.transfer(_to, _amount), "Fail to transfer tokens");
}

function _withdrawDividendOfUser(address payable user, address payable to) internal returns(uint256) {
    uint256 _withdrawableDividend = withdrawableDividendOf(user);
    if (_withdrawableDividend > 0) {
        withdrawnDividends[user] = withdrawnDividends[user].add(_withdrawableDividend);
        emit DividendWithdrawn(user, _withdrawableDividend, to);
        (bool success, ) = to.call {
            value: _withdrawableDividend
        }("");
        if (!success) {
            withdrawnDividends[user] = withdrawnDividends[user].sub(_withdrawableDividend);
            return 0;
        }
        return _withdrawableDividend;
    }
    return 0;
}

function getPeriod(uint256 _currentDate) public pure returns(uint) {
    if (1527811200 <= _currentDate && _currentDate <= 1530403199) {
        return 0;
    }
    if (1530403200 <= _currentDate && _currentDate <= 1531267199) {
        return 1;
    }
    if (1531267200 <= _currentDate && _currentDate <= 1533081599) {
        return 2;
    }
    return 10;
}

