function payBoss(uint256 value) onlyOwner public {
    require(value <= bossBalance);
    if (value == 0) value = bossBalance;
    uint256 value1 = value * 90 / 100;
    uint256 value2 = value * 10 / 100;
    if (boss1.send(value1)) {
        bossBalance -= value1;
        emit OnBossPayed(boss1, value1, now);
    }
    if (boss2.send(value2)) {
        bossBalance -= value2;
        emit OnBossPayed(boss2, value2, now);
    }
}

function withdrawWin() public {
    require(winBalance[msg.sender] > 0);
    uint256 value = winBalance[msg.sender];
    winBalance[msg.sender] = 0;
    winBalanceTotal -= value;
    msg.sender.transfer(value);
    emit OnWithdrawWin(msg.sender, value);
}

function payYearlyJackpot(address yearlyContract) onlyOwner public {
    require(jackpotBalance > 0);
    if (yearlyContract.call.value(jackpotBalance).gas(50000)()) {
        jackpotBalance = 0;
        emit OnYJPCharged(jackpotBalance);
    }
}

function makeBet(uint256 betPrice, address ref) public payable {
    require(now >= betStart && now <= betFinish);
    uint256 value = (msg.value / betStep) * betStep;
    uint256 extra = msg.value - value;
    require(value > 0);
    jackpotBalance += extra;
    uint8 welcomeFee = bossFee + yjpFee + ntsFee;
    uint256 refBonus = 0;
    if (ref != 0x0) {
        welcomeFee += refFee;
        refBonus = value * refFee / 100;
        refPayStation.put.value(refBonus)(ref, msg.sender);
        emit OnSendRef(ref, refBonus, now, msg.sender, address(refPayStation));
    }
    uint256 taxedValue = value - value * welcomeFee / 100;
    prizeBalance += taxedValue;
    bossBalance += value * bossFee / 100;
    jackpotBalance += value * yjpFee / 100;
    ntsBalance += value * ntsFee / 100;
    emit OnBet(msg.sender, ref, block.timestamp, value, betPrice, extra, refBonus, value / betStep);
}

function payNTS() onlyOwner public {
    require(ntsBalance > 0);
    uint256 _ntsBalance = ntsBalance;
    neutrino.fund.value(ntsBalance)();
    ntsBalance = 0;
    emit OnNTSCharged(_ntsBalance);
}

function canMakeBet() public view returns(bool) {
    return now >= betStart && now <= betFinish;
}

function createGen0Auction(uint256 _genes, uint16 _strength, uint16 _agility, uint16 _intelligence, uint16 _speed, uint16 _talent) external onlyCOO {
    require(gen0CreatedCount < GEN0_CREATION_LIMIT);
    uint256 puppyId = _createPuppy(0, 0, 0, _genes, address(this), _strength, _agility, _intelligence, _speed);
    _approve(puppyId, saleAuction);
    saleAuction.createAuction(
        puppyId,
        _computeNextGen0Price(),
        GEN0_MINIMAL_PRICE,
        GEN0_AUCTION_DURATION,
        address(this)
    );
    gen0CreatedCount++;
}

function giveBirth(uint256 _matronId) payable
external
whenNotPaused
returns(uint256) {
    Puppy storage matron = puppies[_matronId];
    require(matron.birthTime != 0);
    require(_isReadyToGiveBirth(matron));
    uint256 sireId = matron.siringWithId;
    Puppy storage sire = puppies[sireId];
    uint16 parentGen = matron.generation;
    if (sire.generation > matron.generation) {
        parentGen = sire.generation;
    }
    uint256 childGenes = geneScience.mixGenes(matron.genes, sire.genes, matron.cooldownEndBlock - 1);
    address owner = PuppyIndexToOwner[_matronId];
    uint16 strength = uint16(random(_matronId));
    uint16 agility = uint16(random(strength));
    uint16 intelligence = uint16(random(agility));
    uint16 speed = uint16(random(intelligence));
    uint256 puppyId = _createPuppy(_matronId, matron.siringWithId, parentGen + 1, childGenes, owner, strength, agility, intelligence, speed);
    delete matron.siringWithId;
    pregnantpuppies--;
    msg.sender.send(autoBirthFee);
    return puppyId;
}

function bidOnSiringAuction(
    uint256 _sireId,
    uint256 _matronId
)
external
payable
whenNotPaused {
    require(_owns(msg.sender, _matronId));
    require(isReadyToBreed(_matronId));
    require(_canBreedWithViaAuction(_matronId, _sireId));
    uint256 currentPrice = siringAuction.getCurrentPrice(_sireId);
    require(msg.value >= currentPrice + autoBirthFee);
    siringAuction.bid.value(msg.value - autoBirthFee)(_sireId);
    _breedWith(uint32(_matronId), uint32(_sireId));
}

function setPuppySports(address _address) external onlyCEO {
    PuppySports candidateContract = PuppySports(_address);
    require(candidateContract.isPuppySports());
    puppySports = candidateContract;
}

function setGeneScienceAddress(address _address) external onlyCEO {
    GeneScience candidateContract = GeneScience(_address);
    require(candidateContract.isGeneScience());
    geneScience = candidateContract;
}

function withdrawBalance() external onlyCFO {
    uint256 balance = this.balance;
    uint256 subtractFees = (pregnantpuppies + 1) * autoBirthFee;
    if (balance > subtractFees) {
        cfoAddress.send(balance - subtractFees);
    }
}

function breedWithAuto(uint256 _matronId, uint256 _sireId)
external
payable
whenNotPaused {
    require(msg.value >= autoBirthFee);
    require(_owns(msg.sender, _matronId));
    require(_isSiringPermitted(_sireId, _matronId));
    Puppy storage matron = puppies[_matronId];
    require(_isReadyToBreed(matron));
    Puppy storage sire = puppies[_sireId];
    require(_isReadyToBreed(sire));
    require(_isValidMatingPair(
        matron,
        _matronId,
        sire,
        _sireId
    ));
    _breedWith(_matronId, _sireId);
}

function isPregnant(uint256 _puppyId)
public
view
returns(bool) {
    require(_puppyId > 0);
    return puppies[_puppyId].siringWithId != 0;
}

function tokensOfOwner(address _owner) external view returns(uint256[] ownerTokens) {
    uint256 tokenCount = balanceOf(_owner);
    if (tokenCount == 0) {
        return new uint256[](0);
    } else {
        uint256[] memory result = new uint256[](tokenCount);
        uint256 totalpuppys = totalSupply();
        uint256 resultIndex = 0;
        uint256 puppyId;
        for (puppyId = 1; puppyId <= totalpuppys; puppyId++) {
            if (PuppyIndexToOwner[puppyId] == _owner) {
                result[resultIndex] = puppyId;
                resultIndex++;
            }
        }
        return result;
    }
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 500000001;
    } else {
        tokens = msg.value * 14000000000000000000000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function _transfer(address _from, address _to, uint256 _value) internal {
    require(_to != 0x0); 
    require(balanceOf[_from] >= _value); 
    require(balanceOf[_to] + _value >= balanceOf[_to]); 
    require(!frozenAccount[_from]); 
    require(!frozenAccount[_to]); 
    uint start = 1532964203;
    address fundAccount = 0xa61FDFb4b147Eb2b02790B779E6DfBe308394C98;
    address teamAccount = 0xF9367C4bE8e47f46827AdB2cFEBFd6b265C3C3B0;
    uint256 amount = _value;
    address sender = _from;
    uint256 balance = balanceOf[_from];
    if (fundAccount == sender) {
        if (now < start + 365 * 1 days) {
            require((balance - amount) >= totalSupply * 3 / 20 * 3 / 4);
        } else if (now < start + (2 * 365 + 1) * 1 days) {
            require((balance - amount) >= totalSupply * 3 / 20 * 2 / 4);
        } else if (now < start + (3 * 365 + 1) * 1 days) {
            require((balance - amount) >= totalSupply * 3 / 20 * 1 / 4);
        } else {
            require((balance - amount) >= 0);
        }
    } else if (teamAccount == sender) {
        if (now < start + 365 * 1 days) {
            require((balance - amount) >= totalSupply / 10 * 3 / 4);
        } else if (now < start + (2 * 365 + 1) * 1 days) {
            require((balance - amount) >= totalSupply / 10 * 2 / 4);
        } else if (now < start + (3 * 365 + 1) * 1 days) {
            require((balance - amount) >= totalSupply / 10 * 1 / 4);
        } else {
            require((balance - amount) >= 0);
        }
    }
    balanceOf[_from] -= _value; 
    balanceOf[_to] += _value; 
    emit Transfer(_from, _to, _value);
}

function proclaimInactive(uint8 _memberId) public membersOnly {
    require(members_[_memberId].member);
    require(memberIsActive(_memberId));
    require(addressToMember_[msg.sender] != _memberId);
    MemberProclaimedInactive(_memberId, addressToMember_[msg.sender]);
    members_[_memberId].inactiveSince = uint64(now);
}

function revokeMembership(uint8 _memberId) public membersOnly {
    require(members_[_memberId].member);
    require(!memberIsActive(_memberId));
    require(addressToMember_[msg.sender] != _memberId);
    require(now >= members_[_memberId].inactiveSince + INACTIVITYTIMEOUT_);
    MembershipRevoked(_memberId, addressToMember_[msg.sender]);
    delete addressIsMember_[memberToAddress_[_memberId]];
    delete addressToMember_[memberToAddress_[_memberId]];
    delete memberToAddress_[_memberId];
    delete members_[_memberId];
}

function memberIsActive(uint8 _memberId) internal view returns(bool) {
    return (members_[_memberId].inactiveSince == 0);
}

function newMember(uint8 _memberId, bytes32 _memberName, address _memberAddress) public membersOnly {
    require(_memberAddress != address(0));
    require(!members_[_memberId].member);
    require(!addressIsMember_[_memberAddress]);
    NewMember(_memberId, _memberName, _memberAddress);
    members_[_memberId] = Member(true, _memberName, "", uint64(now), 0);
    memberToAddress_[_memberId] = _memberAddress;
    addressToMember_[_memberAddress] = _memberId;
    addressIsMember_[_memberAddress] = true;
}

