function createSaleAuction(
    uint256 _tokenId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration
)
external
whenNotPaused {
    require(_startingPrice == uint256(uint128(_startingPrice)));
    require(_endingPrice == uint256(uint128(_endingPrice)));
    require(_duration == uint256(uint64(_duration)));
    require(_owns(msg.sender, _tokenId));
    require(ethernautsStorage.hasAllAttrs(_tokenId, ATTR_TRADABLE));
    require(!ethernautsStorage.hasAllAttrs(_tokenId, ATTR_GOLDENGOOSE));
    require(ethernautsStorage.isState(_tokenId, uint8(AssetState.Available)));
    require(!isExploring(_tokenId));
    ethernautsStorage.approve(_tokenId, address(this));
    _transferFrom(msg.sender, this, _tokenId);
    Auction memory auction = Auction(
        msg.sender,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint64(_duration),
        uint64(now)
    );
    _addAuction(_tokenId, auction);
}

function createAuctionWhenPaused(
    address _contract,
    address _seller,
    uint256 _tokenId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration
)
whenPaused
onlyCLevel
external {
    require(_startingPrice == uint256(uint128(_startingPrice)));
    require(_endingPrice == uint256(uint128(_endingPrice)));
    require(_duration == uint256(uint64(_duration)));
    require(_owns(_contract, _tokenId));
    require(_seller != address(0));
    ethernautsStorage.approve(_tokenId, address(this));
    _transferFrom(_contract, this, _tokenId);
    Auction memory auction = Auction(
        _seller,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint64(_duration),
        uint64(now)
    );
    _addAuction(_tokenId, auction);
}

function purchase(uint256 _tokenId) external payable whenNotPaused {
    require(ethernautsStorage.hasAnyAttrs(_tokenId, ATTR_GOLDENGOOSE));
    require(!isExploring(_tokenId));
    address oldOwner = ethernautsStorage.ownerOf(_tokenId);
    address newOwner = msg.sender;
    uint256 sellingPrice = ethernautsStorage.priceOf(_tokenId);
    require(oldOwner != newOwner);
    require(newOwner != address(0));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, percentageFee1Step), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    uint256 newPrice = sellingPrice;
    if (sellingPrice < firstStepLimit) {
        newPrice = SafeMath.div(SafeMath.mul(sellingPrice, percentage1Step), percentageBase);
    } else if (sellingPrice < secondStepLimit) {
        payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, percentageFee2Step), 100));
        newPrice = SafeMath.div(SafeMath.mul(sellingPrice, percentage2Step), percentageBase);
    } else {
        payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, percentageFeeSteps), 100));
        newPrice = SafeMath.div(SafeMath.mul(sellingPrice, percentageSteps), percentageBase);
    }
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    ethernautsStorage.transfer(oldOwner, newOwner, _tokenId);
    ethernautsStorage.setPrice(_tokenId, newPrice);
    Purchase(_tokenId, sellingPrice, newPrice, oldOwner, newOwner);
    msg.sender.transfer(purchaseExcess);
}

function cancelAuctionWhenPaused(uint256 _tokenId)
whenPaused
onlyCLevel
external {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    _cancelAuction(_tokenId, auction.seller);
}

function determineBonus(uint tokens, uint ethersSent) internal view returns(uint256 bonus) {
    uint256 timeElapsed = now - startTime;
    uint256 timeElapsedInDays = timeElapsed.div(1 days);
    if (timeElapsedInDays < 16) {
        require(ethersSent >= minimumContributionPhase1);
        bonus = tokens.mul(bonusInPhase1);
        bonus = bonus.div(100);
    }
    else if (timeElapsedInDays >= 16 && timeElapsedInDays < 47) {
        require(ethersSent >= minimumContributionPhase2);
        bonus = tokens.mul(bonusInPhase2);
        bonus = bonus.div(100);
    }
    else if (timeElapsedInDays >= 47 && timeElapsedInDays < 62) {
        require(ethersSent >= minimumContributionPhase3);
        bonus = tokens.mul(bonusInPhase3);
        bonus = bonus.div(100);
    }
    else if (timeElapsedInDays >= 62 && timeElapsedInDays < 78) {
        revert();
    }
    else if (timeElapsedInDays >= 78 && timeElapsedInDays < 93) {
        require(ethersSent >= minimumContributionPhase4);
        bonus = tokens.mul(bonusInPhase4);
        bonus = bonus.div(100);
    }
    else if (timeElapsedInDays >= 93 && timeElapsedInDays < 108) {
        require(ethersSent >= minimumContributionPhase5);
        bonus = tokens.mul(bonusInPhase5);
        bonus = bonus.div(10); 
        bonus = bonus.div(100);
    }
    else if (timeElapsedInDays >= 108 && timeElapsedInDays < 123) {
        require(ethersSent >= minimumContributionPhase6);
        bonus = tokens.mul(bonusInPhase6);
        bonus = bonus.div(100);
    } else {
        bonus = 0;
    }
}

constructor(uint256 _startTime, address _wallet, address _tokenAddress) public {
    require(_wallet != 0x0);
    require(_startTime >= now);
    startTime = _startTime;
    endTime = startTime + totalDurationInDays;
    require(endTime >= startTime);
    owner = _wallet;
    bonusInPhase1 = 30;
    bonusInPhase2 = 20;
    bonusInPhase3 = 15;
    bonusInPhase4 = 10;
    bonusInPhase5 = 75;
    bonusInPhase6 = 5;
    minimumContributionPhase1 = uint(3).mul(10 ** 17); 
    minimumContributionPhase2 = uint(5).mul(10 ** 16); 
    minimumContributionPhase3 = uint(5).mul(10 ** 16); 
    minimumContributionPhase4 = uint(5).mul(10 ** 16); 
    minimumContributionPhase5 = uint(5).mul(10 ** 16); 
    minimumContributionPhase6 = uint(5).mul(10 ** 16); 
    token = TokenInterface(_tokenAddress);
}

