        plyr_[msg.sender].eth = plyr_[msg.sender].eth.add(earnAmount);
        milFold_.addPot.value(_eth.sub(earnAmount))();
    }
    emit onSellMFCoins(msg.sender, earnAmount, _coins, now);
}

