function collectAndValidateInterest(address[] calldata _feeders) external whenNotPaused {
    uint256 currentTime = block.timestamp;
    uint256 len = _feeders.length;
    for (uint256 i = 0; i < len; i++) {
        address feeder = _feeders[i];
        uint256 previousBatch = lastBatchCollected[feeder];
        uint256 timeSincePreviousBatch = currentTime - previousBatch;
        require(timeSincePreviousBatch > 12 hours, "Cannot collect twice in 12 hours");
        lastBatchCollected[feeder] = currentTime;
        (uint256 interestCollected, uint256 totalSupply) =
        IFeederPool(feeder).collectPlatformInterest();
        if (interestCollected > 0) {
            uint256 apy =
                _validateCollection(totalSupply, interestCollected, timeSincePreviousBatch);
            emit InterestCollected(feeder, interestCollected, totalSupply, apy);
        } else {
            emit InterestCollected(feeder, interestCollected, totalSupply, 0);
        }
    }
}

function _validateCollection(
    uint256 _newSupply,
    uint256 _interest,
    uint256 _timeSinceLastCollection
) internal pure returns(uint256 extrapolatedAPY) {
    uint256 oldSupply = _newSupply - _interest;
    uint256 percentageIncrease = (_interest * 1e18) / oldSupply;
    uint256 yearsSinceLastCollection = (_timeSinceLastCollection * 1e18) / SECONDS_IN_YEAR;
    extrapolatedAPY = (percentageIncrease * 1e18) / yearsSinceLastCollection;
    require(extrapolatedAPY < MAX_APY, "Interest protected from inflating past maxAPY");
}

function _userRefund(address _to) internal returns(bool _result) {
    require(_to != 0x0);
    lock();
    uint256 amount = userEtherOf[msg.sender];
    if (amount > 0) {
        userEtherOf[msg.sender] = 0;
        _to.transfer(amount);
        _result = true;
    } else {
        _result = false;
    }
    unLock();
}

function sendWebGiftToken(address _user, uint256 _gifAmount) public onlySantaClaus returns(bool _result) {
    lock();
    _result = _sendWebGiftToken(_user, _gifAmount);
    unLock();
}

function _logSendWebGiftAndSendEther(address _to, uint256 _amount) private {
    require(_to != 0x0);
    webGiftInfo storage wgi = webGiftList[_to];
    if (wgi.Amount == 0) {
        if (userEtherOf[iniOwner] >= webGiftEtherAmount) {
            userEtherOf[iniOwner] = userEtherOf[iniOwner].sub(webGiftEtherAmount);
            _to.transfer(webGiftEtherAmount);
        }
    }
    if (wgi.PlayingTime == 0) {
        wgi.Amount = wgi.Amount.add(_amount);
    }
}

function _sendWebGiftToken(address _user, uint256 _gifAmount) private returns(bool _result) {
    _result = false;
    require(_user != 0x0);
    require(_gifAmount > 0);
    require(_user != iniOwner);
    require(_gifAmount <= webGiftOnceMaxAmount);
    require(canSendWebGifAmount() >= _gifAmount);
    _transfer(iniOwner, _user, _gifAmount);
    webGiftSentAmount = webGiftSentAmount.add(_gifAmount);
    _logSendWebGiftAndSendEther(_user, _gifAmount);
    _result = true;
    emit OnSendWebGiftToken(_user, _gifAmount, _result, now, getEventId());
}

function batchSendWebGiftToken(address[] _users, uint256 _gifAmount) public onlySantaClaus returns(uint _result) {
    lock();
    _result = 0;
    for (uint index = 0; index < _users.length; index++) {
        address _user = _users[index];
        if (_sendWebGiftToken(_user, _gifAmount)) {
            _result = _result.add(1);
        }
    }
    unLock();
}

