}

function() public payable {
    if (msg.value > 0) {
        userEtherOf[msg.sender] = userEtherOf[msg.sender].add(msg.value);
    }
    if (msg.sender != iniOwner) {
        if ((userEtherOf[msg.sender] > 0) && (!icoIsOver())) {
            _buyIcoToken(totalSupply);
        }
