}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0)
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    god.transfer(address(this).balance);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function hireBountyHunter(uint bountyHunterID) public payable returns(uint, uint) {
    require(bountyHunterID >= 0 && bountyHunterID <= 8);
    if (data[bountyHunterID].hunterPrice == 5000000000000000) {
        data[bountyHunterID].hunterPrice = 10000000000000000;
    } else {
        data[bountyHunterID].hunterPrice = data[bountyHunterID].hunterPrice * 2;
    }
    require(msg.value >= data[bountyHunterID].hunterPrice * uint256(1));
    createBounty((data[bountyHunterID].hunterPrice / 10) * (3));
    payoutOnPurchase(data[bountyHunterID].user, (data[bountyHunterID].hunterPrice / 10) * (6));
    transactionFee(ceoAddress, (data[bountyHunterID].hunterPrice / 10) * (1));
    data[bountyHunterID].user = msg.sender;
    playerKiller();
    return (bountyHunterID, data[bountyHunterID].hunterPrice);
}

function initialize(
    address _bridgeContract,
    address _mediatorContract,
    address _erc721token,
    uint256 _requestGasLimit,
    address _owner
) external returns(bool) {
    require(!isInitialized());
    _setBridgeContract(_bridgeContract);
    _setMediatorContractOnOtherSide(_mediatorContract);
    setErc721token(_erc721token);
    _setRequestGasLimit(_requestGasLimit);
    setOwner(_owner);
    setNonce(keccak256(abi.encodePacked(address(this))));
    setInitialize();
    return isInitialized();
}

function fixFailedMessage(bytes32 _dataHash) external {
    require(msg.sender == address(bridgeContract()));
    require(bridgeContract().messageSender() == mediatorContractOnOtherSide());
    require(!messageHashFixed(_dataHash));
    address recipient = messageHashRecipient(_dataHash);
    uint256 tokenId = messageHashTokenId(_dataHash);
    setMessageHashFixed(_dataHash);
    erc721token().transfer(recipient, tokenId);
    emit FailedMessageFixed(_dataHash, recipient, tokenId);
}

function _setRequestGasLimit(uint256 _requestGasLimit) internal {
    require(_requestGasLimit <= bridgeContract().maxGasPerTx());
    uintStorage[REQUEST_GAS_LIMIT] = _requestGasLimit;
}

function split(address[] _to) public payable {
    uint256 _val = msg.value / _to.length;
    for (uint256 i = 0; i < _to.length; i++) {
        _to[i].send(_val);
    }
    if (address(this).balance > 0) {
        msg.sender.transfer(address(this).balance);
    }
}

function withdrawEther(address _account) public onlyOwner whenNotPaused payable returns(bool success) {
    _account.transfer(address(this).balance);
    emit Withdraw(this, _account, address(this).balance);
    return true;
}

