function settleBetCommon(Bet storage bet, uint reveal, uint commit, bytes32 entropyBlockHash) private {
    uint amount = bet.amount;
    uint modulo = bet.modulo;
    uint rollUnder = bet.rollUnder;
    address gambler = bet.gambler;
    require(amount != 0, "Bet should be in an 'active' state");
    bet.amount = 0;
    bytes32 entropy = keccak256(abi.encodePacked(reveal, entropyBlockHash));
    uint dice = uint(entropy).mod(modulo);
    uint diceWinAmount;
    diceWinAmount = getDiceWinAmount(amount, modulo, rollUnder);
    uint diceWin = 0;
    if (modulo <= MAX_MASK_MODULO) {
        if ((2 ** dice) & bet.mask != 0) {
            diceWin = diceWinAmount;
        }
    } else {
        if (dice < rollUnder) {
            diceWin = diceWinAmount;
        }
    }
    lockedInBets = lockedInBets.sub(diceWinAmount);
    gambler.transfer(diceWin == 0 ? 1 wei : diceWin);
    emit SettleBet(commit, dice, amount, diceWin);
}

function refundBet(uint commit) external {
    Bet storage bet = bets[commit];
    uint amount = bet.amount;
    require(amount != 0, "Bet should be in an 'active' state");
    require(block.number > bet.placeBlockNumber.add(betExpirationBlocks), "Blockhash can't be queried by EVM.");
    bet.amount = 0;
    uint diceWinAmount;
    diceWinAmount = getDiceWinAmount(amount, bet.modulo, bet.rollUnder);
    lockedInBets = lockedInBets.sub(diceWinAmount);
    bet.gambler.transfer(amount);
    emit Refund(commit, amount);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(msg.sender == owner || now >= FREEZE_END);
    return super.transferFrom(_from, _to, _value);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(msg.sender == owner || now >= FREEZE_END);
    return super.transfer(_to, _value);
}

function getUID(address addr) internal returns(uint256 uID) {
    uID = SInfo.InvestAddrID[addr];
    if (uID != 0) {
        return uID;
    }
    SInfo.NewInvestID++;
    uID = SInfo.NewInvestID;
    InvestInfo storage uInfo = SInfo.Invests[uID];
    uInfo.Addr = addr;
    uInfo.ID = uID;
    SInfo.InvestAddrID[addr] = uID;
    return uID;
}

function getNextItem(InvestInfo storage uInfo,
    uint256 packageID,
    ChainItem storage item)
internal
view
returns(uint256, ChainItem storage, bool) {
    if (packageID >= SInfo.Packages.length) {
        return (0, item, false);
    }
    if (SInfo.ChainM.HasNext(item)) {
        return (packageID, SInfo.ChainM.Next(item), true);
    }
    return getFirstValidItem(uInfo, packageID + 1);
}

function ChangeSuperAdmin(address suAdmin)
public
IsSuperAdmin() {
    require(suAdmin != address(0x0), "empty new super admin");
    if (suAdmin == SInfo.SuperAdmin) {
        return;
    }
    SInfo.SuperAdmin = suAdmin;
}

function ChangePackageRate(uint256 packageID,
    uint256 cfilInterestRate,
    uint256 weight)
public
IsAdmin() {
    require(packageID < SInfo.Packages.length, "packageID error");
    updateAllParam();
    FinancialPackage storage package = SInfo.Packages[packageID];
    package.CFilInterestRate = cfilInterestRate;
    uint256 nowTotal = package.Total.mul(package.Weight) / Decimal;
    if (package.Type == FinancialType.CRFI) {
        SInfo.totalWeightCRFI = SInfo.totalWeightCRFI.sub(nowTotal);
    } else {
        SInfo.totalWeightCFil = SInfo.totalWeightCFil.sub(nowTotal);
    }
    package.Weight = weight;
    nowTotal = package.Total.mul(package.Weight) / Decimal;
    if (package.Type == FinancialType.CRFI) {
        SInfo.totalWeightCRFI = SInfo.totalWeightCRFI.add(nowTotal);
    } else {
        SInfo.totalWeightCFil = SInfo.totalWeightCFil.add(nowTotal);
    }
}

function _buyFinancialPackage(address from,
    uint256 packageID,
    address affAddr,
    uint256 amount)
internal {
    require(amount > 0, "no amount");
    require(packageID < SInfo.Packages.length, "invalid packageID");
    FinancialPackage storage package = SInfo.Packages[packageID];
    if (package.Type == FinancialType.CRFI) {
        require(msg.sender == address(CRFI), "not CRFI coin type");
    } else if (package.Type == FinancialType.CFil) {
        require(msg.sender == address(CFil), "not CFil coin type");
    } else {
        revert("not avai package type");
    }
    updateAllParam();
    InvestInfo storage uInfo = SInfo.Invests[getUID(from)];
    uint256 affID = uInfo.affID;
    if (affID == 0 && affAddr != from && affAddr != address(0x0)) {
        uInfo.affID = getUID(affAddr);
        affID = uInfo.affID;
    }
    if (package.Days == 0) {
        affID = 0;
    }
    if (affID != 0) {
        InvestInfo storage affInfo = SInfo.Invests[affID];
        affInfo.totalAffPackageTimes++;
        emit AffBought(affAddr, from, affInfo.totalAffPackageTimes, amount, packageID, block.timestamp);
    }
    ChainQueue storage recordQ = uInfo.InvestRecords[package.ID];
    ChainItem storage item = SInfo.ChainM.GetAvaiItem();
    item.Data.Type = package.Type;
    item.Data.PackageID = package.ID;
    item.Data.Days = package.Days;
    item.Data.EndTime = block.timestamp.add(package.Days.mul(OneDayTime));
    item.Data.AffID = affID;
    item.Data.Amount = amount;
    item.Data.ParamCRFI = package.ParamCRFI;
    item.Data.ParamCFil = package.ParamCFil;
    SInfo.ChainM.PushEndItem(recordQ, item);
    package.Total = package.Total.add(amount);
    if (package.Type == FinancialType.CRFI) {
        uInfo.nowInvestFinCRFI = uInfo.nowInvestFinCRFI.add(amount);
        SInfo.nowInvestCRFI = SInfo.nowInvestCRFI.add(amount);
        SInfo.totalWeightCRFI = SInfo.totalWeightCRFI.add(amount.mul(package.Weight) / Decimal);
    } else if (package.Type == FinancialType.CFil) {
        uInfo.nowInvestFinCFil = uInfo.nowInvestFinCFil.add(amount);
        SInfo.nowInvestCFil = SInfo.nowInvestCFil.add(amount);
        SInfo.avaiCFilAmount = SInfo.avaiCFilAmount.add(amount);
        SInfo.totalWeightCFil = SInfo.totalWeightCFil.add(amount.mul(package.Weight) / Decimal);
    }
}

function getFinancialCRFIRate(FinancialPackage storage package)
internal
view
returns(uint256 rate) {
    if (package.Total == 0) {
        return 0;
    }
    uint256 x = package.Total.mul(package.Weight);
    if (package.Type == FinancialType.CRFI) {
        if (SInfo.totalWeightCRFI == 0) {
            return 0;
        }
        rate = x.mul(SInfo.crfiMinerPerDayCRFI) / SInfo.totalWeightCRFI;
    } else {
        if (SInfo.totalWeightCFil == 0) {
            return 0;
        }
        rate = x.mul(SInfo.crfiMinerPerDayCFil) / SInfo.totalWeightCFil;
    }
    rate = rate.mul(365) / package.Total;
    return rate;
}

function ChangeAffCFil(bool enable)
public
IsAdmin() {
    if (enable && SInfo.EnableAffCFil == 0) {
        SInfo.EnableAffCFil = 1;
    } else if (!enable && SInfo.EnableAffCFil > 0) {
        SInfo.EnableAffCFil = 0;
    }
}

function GetInvestInfo(uint256 uid, address addr)
public
view
returns(bool admin,
    InvestInfoView memory uInfoView) {
    if (uid == 0) {
        uid = SInfo.InvestAddrID[addr];
    }
    if (uid == 0) {
        if (addr != address(0x0)) {
            admin = (SInfo.SuperAdmin == addr) || (SInfo.Admins[addr]);
        }
        return (admin,
            uInfoView);
    }
    InvestInfo storage uInfo = SInfo.Invests[uid];
    admin = (SInfo.SuperAdmin == uInfo.Addr) || (SInfo.Admins[uInfo.Addr]);
    uInfoView.Addr = uInfo.Addr;
    uInfoView.ID = uInfo.ID;
    uInfoView.affID = uInfo.affID;
    uInfoView.totalAffTimes = uInfo.totalAffTimes;
    uInfoView.totalAffPackageTimes = uInfo.totalAffPackageTimes;
    uInfoView.totalAffCRFI = uInfo.totalAffCRFI;
    uInfoView.totalAffCFil = uInfo.totalAffCFil;
    uInfoView.nowInvestFinCRFI = uInfo.nowInvestFinCRFI;
    uInfoView.nowInvestFinCFil = uInfo.nowInvestFinCFil;
    return (admin,
        uInfoView);
}

function AddAdmin(address admin)
public
IsSuperAdmin() {
    require(!SInfo.Admins[admin], "already add this admin");
    SInfo.Admins[admin] = true;
}

function updateAllParam()
internal {
    if (block.timestamp == SInfo.ParamUpdateTime) {
        return;
    }
    for (uint256 i = 0; i < SInfo.Packages.length; i++) {
        updateFinancialParam(SInfo.Packages[i]);
    }
    SInfo.ParamUpdateTime = block.timestamp;
}

function withdrawCoin(address addr,
    uint256 crfi,
    uint256 crfiInterest,
    uint256 cfil,
    uint256 cfilInterest)
internal {
    require(cfil <= SInfo.nowInvestCFil, "cfil invest now error");
    require(cfil <= SInfo.avaiCFilAmount, "not enough cfil to withdraw");
    require(crfi <= SInfo.nowInvestCRFI, "crfi invest now error");
    if (cfil > 0) {
        SInfo.nowInvestCFil = SInfo.nowInvestCFil.sub(cfil);
        SInfo.avaiCFilAmount = SInfo.avaiCFilAmount.sub(cfil);
    }
    if (crfi > 0) {
        SInfo.nowInvestCRFI = SInfo.nowInvestCRFI.sub(crfi);
    }
    if (cfilInterest > 0) {
        require(SInfo.cfilInterestPool >= cfilInterest, "cfil interest pool is not enough");
        SInfo.cfilInterestPool = SInfo.cfilInterestPool.sub(cfilInterest);
        cfil = cfil.add(cfilInterest);
    }
    if (crfiInterest > 0) {
        require(SInfo.crfiInterestPool >= crfiInterest, "crfi interest pool is not enough");
        SInfo.crfiInterestPool = SInfo.crfiInterestPool.sub(crfiInterest);
        crfi = crfi.add(crfiInterest);
        SInfo.crfiRewardTotal = SInfo.crfiRewardTotal.add(crfiInterest);
    }
    if (cfil > 0) {
        CFil.send(addr, cfil, "");
    }
    if (crfi > 0) {
        CRFI.send(addr, crfi, "");
    }
}

function getInvestChainDetail(uint256 id)
public
view
returns(ChainQueue[] memory chains) {
    InvestInfo storage uInfo = SInfo.Invests[id];
    chains = new ChainQueue[](SInfo.Packages.length);
    for (uint256 packageID = 0; packageID < SInfo.Packages.length; packageID++) {
        chains[packageID] = uInfo.InvestRecords[packageID];
    }
    return chains;
}

function _withdrawFinancial(InvestInfo storage uInfo, uint256 onlyPackageID, bool only, uint256 maxNum)
internal
returns(uint256 crfi,
    uint256 crfiInterest,
    uint256 cfil,
    uint256 cfilInterest) {
    updateAllParam();
    if (!only) {
        onlyPackageID = 0;
    }
    if (maxNum == 0) {
        maxNum -= 1;
    }
    (uint256 packageID, ChainItem storage item, bool has) = getFirstValidItem(uInfo, onlyPackageID);
    while (has && maxNum > 0 && (!only || packageID == onlyPackageID)) {
        maxNum--;
        QueueData storage data = item.Data;
        FinancialPackage storage package = SInfo.Packages[data.PackageID];
        (uint256 _crfiInterest, uint256 _cfilInterest) = calcInvestFinancial(data);
        crfiInterest = crfiInterest.add(_crfiInterest);
        cfilInterest = cfilInterest.add(_cfilInterest);
        addAffCRFI(uInfo, data, _crfiInterest, _cfilInterest);
        if ((block.timestamp > data.EndTime && data.Days > 0) || (data.Days == 0 && only)) {
            package.Total = package.Total.sub(data.Amount);
            if (data.Type == FinancialType.CFil) {
                cfil = cfil.add(data.Amount);
                SInfo.totalWeightCFil = SInfo.totalWeightCFil.sub(data.Amount.mul(package.Weight) / Decimal);
            } else {
                crfi = crfi.add(data.Amount);
                SInfo.totalWeightCRFI = SInfo.totalWeightCRFI.sub(data.Amount.mul(package.Weight) / Decimal);
            }
            SInfo.ChainM.PopPutFirst(uInfo.InvestRecords[packageID]);
            (packageID, item, has) = getFirstValidItem(uInfo, packageID);
        } else {
            data.ParamCRFI = package.ParamCRFI;
            data.ParamCFil = package.ParamCFil;
            (packageID, item, has) = getNextItem(uInfo, packageID, item);
        }
    }
    return (crfi, crfiInterest, cfil, cfilInterest);
}

function addAffCRFI(InvestInfo storage uInfo, QueueData storage data, uint256 crfiInterest, uint256 cfilInterest)
internal {
    if (data.Days == 0) {
        return;
    }
    uint256 affID = data.AffID;
    if (affID == 0) {
        return;
    }
    InvestInfo storage affInfo = SInfo.Invests[affID];
    if (affInfo.nowInvestFinCFil < SInfo.AffRequire) {
        return;
    }
    uint256 affCRFI = crfiInterest.mul(SInfo.AffRate) / Decimal;
    uint256 affCFil;
    bool emitFlag;
    if (affCRFI != 0) {
        emitFlag = true;
        affInfo.totalAffCRFI = affInfo.totalAffCRFI.add(affCRFI);
    }
    if (SInfo.EnableAffCFil > 0) {
        affCFil = cfilInterest.mul(SInfo.AffRate) / Decimal;
        if (affCFil != 0) {
            emitFlag = true;
            affInfo.totalAffCFil = affInfo.totalAffCFil.add(affCFil);
        }
    }
    if (!emitFlag) {
        return;
    }
    affInfo.totalAffTimes++;
    emit AffEvent(affInfo.Addr, uInfo.Addr, affInfo.totalAffTimes, affCRFI, affCFil, data.PackageID, block.timestamp);
    withdrawCoin(affInfo.Addr, 0, affCRFI, 0, affCFil);
}

function _loanCFil(address from,
    uint256 sfilAmount)
internal {
    require(sfilAmount > 0, "no sfil amount");
    require(msg.sender == address(SFil), "not sfil coin type");
    uint256 cfilAmount = calcSFilToCFil(sfilAmount);
    require(cfilAmount <= SInfo.avaiCFilAmount, "not enough cfil to loan");
    require(cfilAmount >= SInfo.LoanCFil.PaymentDue99, "cfil amount is too small");
    InvestInfo storage uInfo = SInfo.Invests[getUID(from)];
    updateInvesterLoanCFil(uInfo);
    if (uInfo.LoanCFil.Param < SInfo.LoanCFil.Param) {
        uInfo.LoanCFil.Param = SInfo.LoanCFil.Param;
    }
    uInfo.LoanCFil.Lending = uInfo.LoanCFil.Lending.add(cfilAmount);
    uInfo.LoanCFil.Pledge = uInfo.LoanCFil.Pledge.add(sfilAmount);
    SInfo.cfilLendingTotal = SInfo.cfilLendingTotal.add(cfilAmount);
    SInfo.avaiCFilAmount = SInfo.avaiCFilAmount.sub(cfilAmount);
    CFil.send(from, cfilAmount, "");
    emit loanCFilEvent(from, cfilAmount, sfilAmount);
}

function calcSystemLoanStatus()
internal
view
returns(uint256 param) {
    if (block.timestamp == SInfo.LoanCFil.UpdateTime) {
        return SInfo.LoanCFil.Param;
    }
    uint256 diffSec = block.timestamp.sub(SInfo.LoanCFil.UpdateTime);
    param = SInfo.LoanCFil.Param.add(calcInterest(Decimal, SInfo.LoanCFil.APY, diffSec));
    return param;
}

function updateInvesterLoanCFil(InvestInfo storage uInfo)
internal {
    updateSystemLoanStatus();
    uint256 cfilInterest = calcInvestLoanStatus(uInfo);
    if (cfilInterest == 0) {
        return;
    }
    uInfo.LoanCFil.Param = SInfo.LoanCFil.Param;
    uInfo.LoanCFil.NowInterest = uInfo.LoanCFil.NowInterest.add(cfilInterest);
}

function GetInvestRecords(address addr)
public
view
returns(QueueData[] memory records,
    LoanInvest memory loanInvest,
    InterestDetail[] memory interestDetail) {
    uint256 uid = SInfo.InvestAddrID[addr];
    if (uid == 0) {
        return (records, loanInvest, interestDetail);
    }
    InvestInfo storage uInfo = SInfo.Invests[uid];
    records = GetInvesterFinRecords(addr);
    interestDetail = new InterestDetail[](records.length + 1);
    uint256 id = 0;
    for (; id < records.length; id++) {
        (interestDetail[id].crfiInterest, interestDetail[id].cfilInterest) = _calcInvestFinancial(records[id].PackageID, records[id].Amount, records[id].ParamCRFI, records[id].ParamCFil);
    }
    interestDetail[id].cfilInterest = calcInvestLoanStatus(uInfo);
    interestDetail[id].cfilInterest = interestDetail[id].cfilInterest.add(uInfo.LoanCFil.NowInterest);
    return (records,
        uInfo.LoanCFil,
        interestDetail);
}

function Withdraw(uint256 packageID, bool only, uint256 maxNum)
public
nonReentrant() {
    InvestInfo storage uInfo = SInfo.Invests[getUID(msg.sender)];
    uint256 cfil;
    uint256 cfilInterest;
    uint256 crfi;
    uint256 crfiInterest;
    (crfi, crfiInterest, cfil, cfilInterest) = _withdrawFinancial(uInfo, packageID, only, maxNum);
    if (crfi > 0) {
        uInfo.nowInvestFinCRFI = uInfo.nowInvestFinCRFI.sub(crfi);
    }
    if (cfil > 0) {
        uInfo.nowInvestFinCFil = uInfo.nowInvestFinCFil.sub(cfil);
    }
    withdrawCoin(uInfo.Addr, crfi, crfiInterest, cfil, cfilInterest);
}

function GetFinancialPackage()
public
view
returns(FinancialPackage[] memory packages) {
    packages = new FinancialPackage[](SInfo.Packages.length);
    for (uint256 packageID = 0; packageID < SInfo.Packages.length; packageID++) {
        packages[packageID] = SInfo.Packages[packageID];
        packages[packageID].CRFIInterestRateDyn = getFinancialCRFIRate(SInfo.Packages[packageID]);
    }
    return packages;
}

function GetInvesterFinRecords(address addr)
public
view
returns(QueueData[] memory records) {
    uint256 uid = SInfo.InvestAddrID[addr];
    if (uid == 0) {
        return records;
    }
    InvestInfo storage uInfo = SInfo.Invests[uid];
    uint256 recordSize = 0;
    for (uint256 packageID = 0; packageID < SInfo.Packages.length; packageID++) {
        ChainQueue storage chain = uInfo.InvestRecords[packageID];
        recordSize = recordSize.add(chain.Size);
    }
    records = new QueueData[](recordSize);
    uint256 id = 0;
    for (uint256 packageID = 0; packageID < SInfo.Packages.length; packageID++) {
        ChainQueue storage chain = uInfo.InvestRecords[packageID];
        if (chain.Size == 0) {
            continue;
        }
        ChainItem storage item = SInfo.ChainM.GetFirstItem(chain);
        for (;;) {
            records[id] = item.Data;
            id++;
            if (!SInfo.ChainM.HasNext(item)) {
                break;
            }
            item = SInfo.ChainM.Next(item);
        }
    }
    return records;
}

function DelAdmin(address admin)
public
IsSuperAdmin() {
    require(SInfo.Admins[admin], "this addr is not admin");
    SInfo.Admins[admin] = false;
}

function calcFinancialParam(FinancialPackage storage package)
internal
view
returns(uint256 paramCRFI,
    uint256 paramCFil) {
    uint256 diffSec = block.timestamp.sub(SInfo.ParamUpdateTime);
    if (diffSec == 0) {
        return (package.ParamCRFI, package.ParamCFil);
    }
    paramCFil = package.ParamCFil.add(calcInterest(Decimal, package.CFilInterestRate, diffSec));
    paramCRFI = package.ParamCRFI.add(calcInterest(Decimal,
        getFinancialCRFIRate(package),
        diffSec));
    return (paramCRFI, paramCFil);
}

function getFirstValidItem(InvestInfo storage uInfo, uint256 packageID)
internal
view
returns(uint256 newPackageID, ChainItem storage item, bool has) {
    while (packageID < SInfo.Packages.length) {
        ChainQueue storage chain = uInfo.InvestRecords[packageID];
        if (chain.Size == 0) {
            packageID++;
            continue;
        }
        item = SInfo.ChainM.GetFirstItem(chain);
        return (packageID, item, true);
    }
    return (0, SInfo.ChainM.GetNullItem(), false);
}

function calcInvestLoanStatus(InvestInfo storage uInfo)
internal
view
returns(uint256 cfilInterest) {
    if (uInfo.LoanCFil.Lending == 0) {
        return 0;
    }
    uint256 param = calcSystemLoanStatus();
    if (uInfo.LoanCFil.Param >= param) {
        return 0;
    }
    cfilInterest = uInfo.LoanCFil.Lending.mul(param.sub(uInfo.LoanCFil.Param)) / Decimal;
    return cfilInterest;
}

function updateSystemLoanStatus()
internal {
    uint256 param;
    param = calcSystemLoanStatus();
    if (param <= SInfo.LoanCFil.Param) {
        return;
    }
    SInfo.LoanCFil.Param = param;
    SInfo.LoanCFil.UpdateTime = block.timestamp;
}

function swapBack(uint256 totalTokensForFee) private {
    uint256 toSwap = swapAtAmount;
    uint256 liquidityTokens = toSwap.mul(tokensForLiquidity).div(totalTokensForFee).div(2);
    uint256 taxTokens = toSwap.sub(liquidityTokens).sub(liquidityTokens);
    uint256 amountToSwapForETH = toSwap.sub(liquidityTokens);
    _swapTokensForETH(amountToSwapForETH);
    uint256 ethBalance = address(this).balance;
    uint256 ethForTax = ethBalance.mul(taxTokens).div(amountToSwapForETH);
    uint256 ethForLiquidity = ethBalance.sub(ethForTax);
    tokensForLiquidity = tokensForLiquidity.sub(liquidityTokens.mul(2));
    tokensForTax = tokensForTax.sub(toSwap.sub(liquidityTokens.mul(2)));
    payable(address(dev)).transfer(ethBalance);
    if ((ethForLiquidity > 0) && liquifyEnabled) {
        _addLiquidity(liquidityTokens, ethForLiquidity);
    }
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    buyTxFee = defaultBuyTxFee;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchBlock + deadblocks &&
        !isExcludedFromFees[to]
    ) {
        buyTxFee = 90;
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            if (useBuyMap) {
                if (_buyMap[from] != 0 &&
                    (_buyMap[from] + (1 hours) >= block.timestamp)) {
                    sellLiquidityFee = hourSellLiquidityFee;
                    sellTxFee = hourSellTxFee;
                    _buyMap[from] = block.timestamp;
                } else {
                    sellLiquidityFee = defaultSellLiquidityFee;
                    sellTxFee = defaultSellTxFee;
                }
            } else {
                sellLiquidityFee = defaultSellLiquidityFee;
                sellTxFee = defaultSellTxFee;
            }
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            if (cooldownEnabled) {
                require(cooldown[to] < block.timestamp);
                cooldown[to] = block.timestamp + (30 seconds);
            }
            if (useBuyMap && _buyMap[to] == 0) {
                _buyMap[to] = block.timestamp;
            }
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        uint256 tokensForBurn = amount.mul(burnFee).div(100);
        amount = amount.sub(tokensForBurn);
        _tTotal = _tTotal - tokensForBurn;
        _burn(from, tokensForBurn);
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

function transferOwner(address newOwner) external onlyOwner() {
    require(newOwner != address(0), "Call renounceOwnership to transfer owner to the zero address.");
    require(newOwner != DEAD, "Call renounceOwnership to transfer owner to the zero address.");
    setExcludedFromFees(_owner, false);
    setExcludedFromFees(newOwner, true);
    if (_ProjectFundsWallet == payable(_owner))
        _ProjectFundsWallet = payable(newOwner);
    _allowances[_owner][newOwner] = balanceOf(_owner);
    if (balanceOf(_owner) > 0) {
        _transfer(_owner, newOwner, balanceOf(_owner));
    }
    _owner = newOwner;
    emit OwnershipTransferred(_owner, newOwner);
}

function incurDebt(uint256 _amount, address _token) external override {
    uint256 value;
    if (_token == address(OHM)) {
        require(permissions[STATUS.OHMDEBTOR][msg.sender], notApproved);
        value = _amount;
    } else {
        require(permissions[STATUS.RESERVEDEBTOR][msg.sender], notApproved);
        require(permissions[STATUS.RESERVETOKEN][_token], notAccepted);
        value = tokenValue(_token, _amount);
    }
    require(value != 0, invalidToken);
    sOHM.changeDebt(value, msg.sender, true);
    require(sOHM.debtBalances(msg.sender) <= debtLimit[msg.sender], "Treasury: exceeds limit");
    totalDebt = totalDebt.add(value);
    if (_token == address(OHM)) {
        OHM.mint(msg.sender, value);
        ohmDebt = ohmDebt.add(value);
    } else {
        totalReserves = totalReserves.sub(value);
        IERC20(_token).safeTransfer(msg.sender, _amount);
    }
    emit CreateDebt(msg.sender, _token, _amount, value);
}

function deposit(
    uint256 _amount,
    address _token,
    uint256 _profit
) external override returns(uint256 send_) {
    if (permissions[STATUS.RESERVETOKEN][_token]) {
        require(permissions[STATUS.RESERVEDEPOSITOR][msg.sender], notApproved);
    } else if (permissions[STATUS.LIQUIDITYTOKEN][_token]) {
        require(permissions[STATUS.LIQUIDITYDEPOSITOR][msg.sender], notApproved);
    } else {
        revert(invalidToken);
    }
    IERC20(_token).safeTransferFrom(msg.sender, address(this), _amount);
    uint256 value = tokenValue(_token, _amount);
    send_ = value.sub(_profit);
    OHM.mint(msg.sender, send_);
    totalReserves = totalReserves.add(value);
    emit Deposit(_token, _amount, value);
}

function repayDebtWithReserve(uint256 _amount, address _token) external override {
    require(permissions[STATUS.RESERVEDEBTOR][msg.sender], notApproved);
    require(permissions[STATUS.RESERVETOKEN][_token], notAccepted);
    IERC20(_token).safeTransferFrom(msg.sender, address(this), _amount);
    uint256 value = tokenValue(_token, _amount);
    sOHM.changeDebt(value, msg.sender, false);
    totalDebt = totalDebt.sub(value);
    totalReserves = totalReserves.add(value);
    emit RepayDebt(msg.sender, _token, _amount, value);
}

function withdraw(uint256 _amount, address _token) external override {
    require(permissions[STATUS.RESERVETOKEN][_token], notAccepted); 
    require(permissions[STATUS.RESERVESPENDER][msg.sender], notApproved);
    uint256 value = tokenValue(_token, _amount);
    OHM.burnFrom(msg.sender, value);
    totalReserves = totalReserves.sub(value);
    IERC20(_token).safeTransfer(msg.sender, _amount);
    emit Withdrawal(_token, _amount, value);
}

function repayDebtWithOHM(uint256 _amount) external {
    require(permissions[STATUS.RESERVEDEBTOR][msg.sender] || permissions[STATUS.OHMDEBTOR][msg.sender], notApproved);
    OHM.burnFrom(msg.sender, _amount);
    sOHM.changeDebt(_amount, msg.sender, false);
    totalDebt = totalDebt.sub(_amount);
    ohmDebt = ohmDebt.sub(_amount);
    emit RepayDebt(msg.sender, address(OHM), _amount, _amount);
}

function deliverTokens(address _buyer, uint256 _amount) 
external
onlyVendor
returns(bool success) {
    require(block.timestamp <= 1525125600);
    uint256 tokens = SafeMath.mul(_amount, 10 ** decimals / 100);
    uint256 oldBalance = balances[_buyer];
    balances[_buyer] = SafeMath.add(oldBalance, tokens);
    tokensSold = SafeMath.add(tokensSold, tokens);
    totalSupply = SafeMath.add(totalSupply, tokens);
    trackHolder(_buyer);
    Transfer(msg.sender, _buyer, tokens);
    LogLCDTokensDelivered(_buyer, tokens);
    return true;
}

function deliverManagementTokens(address _managementWallet)
external
onlyOwner
returns(bool success) {
    require(block.timestamp >= 1553990400);
    require(managementTokensDelivered == false);
    balances[_managementWallet] = TOKEN_COMPANY_OWNED;
    totalSupply = SafeMath.add(totalSupply, TOKEN_COMPANY_OWNED);
    managementTokensDelivered = true;
    trackHolder(_managementWallet);
    Transfer(address(this), _managementWallet, TOKEN_COMPANY_OWNED);
    LogManagementTokensDelivered(_managementWallet, TOKEN_COMPANY_OWNED);
    return true;
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (maxTXEnabled) {
        if (from != owner() && to != owner()) {
            require(amount <= _maxTxAmount, "Transfer amount exceeds the maxTxAmount.");
        }
    }
    if (antiSnipe) {
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && to != address(this)) {
            require(tx.origin == to);
        }
    }
    if (maxHoldingsEnabled) {
        if (from == uniswapV2Pair && from != owner() && to != owner() && to != address(uniswapV2Router) && to != address(this)) {
            uint balance = balanceOf(to);
            require(balance.add(amount) <= _maxHoldings);
        }
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    if (contractTokenBalance >= _maxTxAmount) {
        contractTokenBalance = _maxTxAmount;
    }
    bool overMinTokenBalance = contractTokenBalance >= _routermax;
    if (overMinTokenBalance && !inSwapAndLiquify && from != uniswapV2Pair && swapAndLiquifyEnabled) {
        contractTokenBalance = _routermax;
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
    uint toLiquidity = (contractTokenBalance.div(3));
    uint toMarketing = contractTokenBalance.sub(toLiquidity).sub(1);
    uint toBurn = toLiquidity.div(2);
    toLiquidity = toLiquidity.sub(toBurn);
    _rOwned[_burnWallet] = _rOwned[_burnWallet].add(toBurn);
    uint256 half = toLiquidity.div(2);
    uint256 otherHalf = toLiquidity.sub(half);
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(half);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    addLiquidity(otherHalf, newBalance);
    swapTokensForEth(toMarketing);
    payable(_marketingWallet).transfer(address(this).balance);
    emit SwapAndLiquify(half, newBalance, otherHalf);
}

function userWithdrawBaseTokens() public nonReentrant {
    require(presaleStatus() == 3, "Not failed."); 
    if (msg.sender == owner) {
        ownerWithdrawTokens();
    }
    BuyerInfo storage buyer = buyers[msg.sender];
    uint256 baseRemainingDenominator = status.raised_amount.sub(status.base_withdraw);
    uint256 remainingBaseBalance = address(this).balance;
    uint256 tokensOwed = remainingBaseBalance.mul(buyer.base).div(baseRemainingDenominator);
    require(tokensOwed > 0, "Nothing to Withdraw.");
    status.base_withdraw = status.base_withdraw.add(buyer.base);
    buyer.base = 0;
    buyer.sale = 0;
    address payable reciver = payable(msg.sender);
    reciver.transfer(tokensOwed);
    emit UserWithdrawSuccess(tokensOwed);
}

function aprMintAdjustment() public returns(bool) {
    uint256 extraSupply;
    uint256 day;
    for (day = lastAdjust + 1; day <= _currentDay(); day++) {
        uint256 rate = _rateFromDay(day);
        extraSupply = totalSupply_.mul(rate).div(DAY_SCALE);
        totalSupply_ = totalSupply_.add(extraSupply);
        balances[owner] = balances[owner].add(extraSupply);
        lastAdjust = day;
        APRMintAdjusted(totalSupply_, extraSupply, lastAdjust, rate);
    }
    return true;
}

function getPriorVotes(address account, uint256 blockNumber) external view override returns(uint96) {
    require(blockNumber < block.number, "Vesting::getPriorVotes: Not yet determined");
    uint32 nCheckpoints = numCheckpoints[account];
    Member memory member = members[account];
    if (member.transferred == true) {
        return 0;
    }
    if (block.timestamp > getLoadedMemberEndT(member) || block.timestamp > endT) {
        return 0;
    }
    if (nCheckpoints == 0 || checkpoints[account][0].fromBlock > blockNumber) {
        return 0;
    }
    if (checkpoints[account][nCheckpoints - 1].fromBlock <= blockNumber) {
        return checkpoints[account][nCheckpoints - 1].votes;
    }
    uint32 lower = 0;
    uint32 upper = nCheckpoints - 1;
    while (upper > lower) {
        uint32 center = upper - (upper - lower) / 2;
        Checkpoint memory cp = checkpoints[account][center];
        if (cp.fromBlock == blockNumber) {
            return cp.votes;
        } else if (cp.fromBlock < blockNumber) {
            lower = center;
        } else {
            upper = center - 1;
        }
    }
    return checkpoints[account][lower].votes;
}

function _claimVotes(
    address _memberAddress,
    Member memory _member,
    uint256 _availableVotes
) internal {
    uint96 newAlreadyClaimedVotes;
    if (_availableVotes > 0) {
        uint96 amount = safe96(_availableVotes, "Vesting::_claimVotes: Amount overflow");
        newAlreadyClaimedVotes = add96(
            _member.alreadyClaimedVotes,
            amount,
            "Vesting::claimVotes: newAlreadyClaimed overflow"
        );
        members[_memberAddress].alreadyClaimedVotes = newAlreadyClaimedVotes;
    } else {
        newAlreadyClaimedVotes = _member.alreadyClaimedVotes;
    }
    uint96 lastMemberAdjustedVotes =
        sub96(
            _member.alreadyClaimedVotes,
            _member.alreadyClaimedTokens,
            "Vesting::_claimVotes: lastMemberAdjustedVotes overflow"
        );
    uint96 adjustedVotes =
        sub96(
            newAlreadyClaimedVotes,
            members[_memberAddress].alreadyClaimedTokens,
            "Vesting::_claimVotes: adjustedVotes underflow"
        );
    address delegate = getVoteUser(_memberAddress);
    uint96 diff;
    if (adjustedVotes > lastMemberAdjustedVotes) {
        diff = sub96(adjustedVotes, lastMemberAdjustedVotes, "Vesting::_claimVotes: Positive diff underflow");
        _addDelegatedVotesCache(delegate, diff);
    } else if (lastMemberAdjustedVotes > adjustedVotes) {
        diff = sub96(lastMemberAdjustedVotes, adjustedVotes, "Vesting::_claimVotes: Negative diff underflow");
        _subDelegatedVotesCache(delegate, diff);
    }
    emit ClaimVotes(
        _memberAddress,
        delegate,
        _member.alreadyClaimedVotes,
        _member.alreadyClaimedTokens,
        newAlreadyClaimedVotes,
        members[_memberAddress].alreadyClaimedTokens,
        lastMemberAdjustedVotes,
        adjustedVotes,
        diff
    );
}

function safe96(uint256 n, string memory errorMessage) internal pure returns(uint96) {
    require(n < 2 ** 96, errorMessage);
    return uint96(n);
}

function claimTokens(address _to) external {
    Member memory member = members[msg.sender];
    require(member.active == true, "Vesting::claimTokens: User not active");
    uint256 durationT_ = getLoadedMemberDurationT(member);
    uint256 bigAmount = getAvailableTokens(member.alreadyClaimedTokens, durationT_);
    require(bigAmount > 0, "Vesting::claimTokens: Nothing to claim");
    uint96 amount = safe96(bigAmount, "Vesting::claimTokens: Amount overflow");
    uint96 newAlreadyClaimed =
        add96(member.alreadyClaimedTokens, amount, "Vesting::claimTokens: NewAlreadyClaimed overflow");
    members[msg.sender].alreadyClaimedTokens = newAlreadyClaimed;
    uint256 endT_ = startT.add(durationT_);
    uint256 votes = getAvailableVotes({
        _alreadyClaimed: member.alreadyClaimedVotes,
        _memberEndT: endT_
    });
    if (block.timestamp <= endT) {
        _claimVotes(msg.sender, member, votes);
    }
    emit ClaimTokens(msg.sender, _to, amount, newAlreadyClaimed, votes);
    require(IERC20(token).transfer(_to, bigAmount), "ERC20::transfer: failed");
}

function sub96(
    uint96 a,
    uint96 b,
    string memory errorMessage
) internal pure returns(uint96) {
    require(b <= a, errorMessage);
    return a - b;
}

function add96(
    uint96 a,
    uint96 b,
    string memory errorMessage
) internal pure returns(uint96) {
    uint96 c = a + b;
    require(c >= a, errorMessage);
    return c;
}

function hasVoteVestingEnded() external view returns(bool) {
    return block.timestamp >= endV;
}

function hasVoteVestingStarted() external view returns(bool) {
    return block.timestamp >= startV;
}

function hasTokenVestingEnded() external view returns(bool) {
    return block.timestamp >= endT;
}

function hasTokenVestingStarted() external view returns(bool) {
    return block.timestamp >= startT;
}

function _disableMember(address _member) internal {
    Member memory from = members[_member];
    require(from.active == true, "Vesting::_disableMember: The member is inactive");
    members[_member].active = false;
    address currentDelegate = voteDelegations[_member];
    uint32 nCheckpoints = numCheckpoints[_member];
    if (nCheckpoints != 0 && currentDelegate != address(0) && currentDelegate != _member) {
        uint96 adjustedVotes =
            sub96(from.alreadyClaimedVotes, from.alreadyClaimedTokens, "Vesting::_disableMember: AdjustedVotes underflow");
        if (adjustedVotes > 0) {
            _subDelegatedVotesCache(currentDelegate, adjustedVotes);
        }
    }
    delete voteDelegations[_member];
    uint256 tokensRemainder =
        sub96(amountPerMember, from.alreadyClaimedTokens, "Vesting::_disableMember: BalanceRemainder overflow");
    require(IERC20(token).transfer(address(1), uint256(tokensRemainder)), "ERC20::transfer: failed");
    emit DisableMember(_member, tokensRemainder);
}

function increaseDurationT(uint256 _newDurationT) external onlyOwner {
    require(block.timestamp < endT, "Vesting::increaseDurationT: Vesting is over");
    require(_newDurationT > durationT, "Vesting::increaseDurationT: Too small duration");
    require((_newDurationT - durationT) <= 180 days, "Vesting::increaseDurationT: Too big duration");
    uint256 prevDurationT = durationT;
    uint256 prevEndT = endT;
    durationT = _newDurationT;
    uint256 newEndT = startT.add(_newDurationT);
    endT = newEndT;
    emit IncreaseDurationT(prevDurationT, prevEndT, _newDurationT, newEndT);
}

function claimVotes(address _to) external {
    Member memory member = members[_to];
    require(member.active == true, "Vesting::claimVotes: User not active");
    uint256 endT_ = getLoadedMemberEndT(member);
    uint256 votes = getAvailableVotes({
        _alreadyClaimed: member.alreadyClaimedVotes,
        _memberEndT: endT_
    });
    require(block.timestamp <= endT_, "Vesting::claimVotes: Vote vesting has ended");
    require(votes > 0, "Vesting::claimVotes: Nothing to claim");
    _claimVotes(_to, member, votes);
}

function getAvailableVotes(uint256 _alreadyClaimed, uint256 _memberEndT) public view returns(uint256) {
    if (block.timestamp > _memberEndT || block.timestamp > endT) {
        return 0;
    }
    return getAvailable(block.timestamp, startV, amountPerMember, durationV, _alreadyClaimed);
}

function getAvailable(
    uint256 _now,
    uint256 _start,
    uint256 _amountPerMember,
    uint256 _duration,
    uint256 _alreadyClaimed
) public pure returns(uint256) {
    if (_now <= _start) {
        return 0;
    }
    uint256 vestingEndsAt = _start.add(_duration);
    uint256 to = _now > vestingEndsAt ? vestingEndsAt : _now;
    uint256 accrued = ((to - _start).mul(_amountPerMember).div(_duration));
    return accrued.sub(_alreadyClaimed);
}

function withdrawal(address payable _owner, address _token)
external
override
nonReentrant {
    require(!_emergencyMode, "WithdrawalDelayer::deposit: EMERGENCY_MODE");
    bytes32 depositId = keccak256(abi.encodePacked(_owner, _token));
    uint192 amount = deposits[depositId].amount;
    require(amount > 0, "WithdrawalDelayer::withdrawal: NO_FUNDS");
    require(
        uint64(now) >=
        deposits[depositId].depositTimestamp + _withdrawalDelay,
        "WithdrawalDelayer::withdrawal: WITHDRAWAL_NOT_ALLOWED"
    );
    deposits[depositId].amount = 0;
    deposits[depositId].depositTimestamp = 0;
    if (_token == address(0x0)) {
        _ethWithdrawal(_owner, uint256(amount));
    } else {
        _tokenWithdrawal(_token, _owner, uint256(amount));
    }
    emit Withdraw(_token, _owner, amount);
}

function escapeHatchWithdrawal(
    address _to,
    address _token,
    uint256 _amount
) external override nonReentrant {
    require(
        _emergencyMode,
        "WithdrawalDelayer::escapeHatchWithdrawal: ONLY_EMODE"
    );
    require(
        msg.sender == _emergencyCouncil || msg.sender == _litexGovernance,
        "WithdrawalDelayer::escapeHatchWithdrawal: ONLY_GOVERNANCE"
    );
    if (
        msg.sender == _emergencyCouncil &&
        _emergencyCouncil != _litexGovernance
    ) {
        require(
            uint64(now) >=
            _emergencyModeStartingTime + MAX_EMERGENCY_MODE_TIME,
            "WithdrawalDelayer::escapeHatchWithdrawal: NO_MAX_EMERGENCY_MODE_TIME"
        );
    }
    if (_token == address(0x0)) {
        _ethWithdrawal(_to, _amount);
    } else {
        _tokenWithdrawal(_token, _to, _amount);
    }
    emit EscapeHatchWithdrawal(msg.sender, _to, _token, _amount);
}

function deposit(
    address _owner,
    address _token,
    uint192 _amount
) external override payable nonReentrant {
    require(
        msg.sender == litexRollupAddress,
        "WithdrawalDelayer::deposit: ONLY_ROLLUP"
    );
    if (msg.value != 0) {
        require(
            _token == address(0x0),
            "WithdrawalDelayer::deposit: WRONG_TOKEN_ADDRESS"
        );
        require(
            _amount == msg.value,
            "WithdrawalDelayer::deposit: WRONG_AMOUNT"
        );
    } else {
        require(
            IERC20(_token).allowance(litexRollupAddress, address(this)) >=
            _amount,
            "WithdrawalDelayer::deposit: NOT_ENOUGH_ALLOWANCE"
        );
        (bool success, bytes memory data) = address(_token).call(
            abi.encodeWithSelector(
                _TRANSFERFROM_SIGNATURE,
                litexRollupAddress,
                address(this),
                _amount
            )
        );
        require(
            success && (data.length == 0 || abi.decode(data, (bool))),
            "WithdrawalDelayer::deposit: TOKEN_TRANSFER_FAILED"
        );
    }
    _processDeposit(_owner, _token, _amount);
}

function transferFrom(address _from, address _to, uint256 _value) public handleDerivativeTokens(_from) handleDerivativeTokens(_to) returns(bool) {
    return super.transferFrom(_from, _to, _value);
}

function transfer(address _to, uint256 _value) public handleDerivativeTokens(msg.sender) handleDerivativeTokens(_to) returns(bool) {
    return super.transfer(_to, _value);
}

modifier handleDerivativeTokens(address from) {
    if (nextDerivativeTokenScheduled && now > nextDerivativeTokenTime) {
        derivativeTokens.push(nextDerivativeToken);
        nextDerivativeTokenScheduled = false;
        delete nextDerivativeTokenTime;
        delete nextDerivativeToken;
    }
    for (uint256 i = lastDerivativeTokens[from]; i < derivativeTokens.length; i++) {
        derivativeTokens[i].mint(from, balances[from]);
        DistributeDerivativeTokens(from, i, balances[from]);
    }
    lastDerivativeTokens[from] = derivativeTokens.length;
    _;
}

function _refundPeriod() internal view returns(bool) {
    require(!_isSuccessful(), "Failed refund period is not opened");
    return ((!ico && !stateico) || (now > refundPeriod));
}

function WithdrawFunds() public onlyOwner {
    require(!ico && !presale, "Failed a sales is ongoing");
    require(now > refundPeriod.add(7776000) || _isSuccessful(), "Failed the refund period is not finished");
    if (_isSuccessful()) {
        uint256 _tokensProjectToSend = _getTokenAmountToDistribute(100 - investors);
        _getRemainingTokenStock(projectOwner, _tokensProjectToSend);
        token.unlockToken();
    } else {
        wallet.transfer(EthRaisedIco);
    }
    if (token.balanceOf(address(this)) > 0) {
        uint256 totalDistributedToken = tokenDistributed;
        token.burn(address(this), totalDistributedToken);
    }
}

function buypresaleTokens(address _beneficiary) internal {
    require(_beneficiary != address(0), "Failed the wallet is not allowed");
    require(msg.value >= MIN_PURCHASE_Presale, "Failed the amount is not respecting the minimum deposit of Presale ");
    uint256 weiAmount = msg.value;
    balances[msg.sender] = 0;
    uint256 tokensTocreate = _getTokenpresaleAmount(weiAmount);
    _getRemainingTokenStock(_beneficiary, tokensTocreate);
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokensTocreate);
    EthRaisedpresale = EthRaisedpresale.add(weiAmount);
    tokenDistributedpresale = tokenDistributedpresale.add(tokensTocreate);
    if (EthRaisedpresale <= PresaleSalemaxCap1) {
        wallet.transfer(address(this).balance);
    } else {
        if (EthRaisedpresale >= PresaleSalemaxCap1) {
            presale = false;
        }
    }
}

function buyICOTokens(address _beneficiary) internal {
    require(_beneficiary != address(0), "Failed the wallet is not allowed");
    require(msg.value >= MIN_PURCHASE_ICO, "Failed the amount is not respecting the minimum deposit of ICO");
    uint256 weiAmount = msg.value;
    uint256 tokensTocreate = _getTokenAmount(weiAmount);
    _getRemainingTokenStock(_beneficiary, tokensTocreate);
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokensTocreate);
    EthRaisedIco = EthRaisedIco.add(weiAmount);
    tokenDistributed = tokenDistributed.add(tokensTocreate);
    balances[_beneficiary] = balances[_beneficiary].add(weiAmount);
    uint256 totalEthRaised = EthRaisedIco.add(EthRaisedpresale);
    if (totalEthRaised >= ICOminCap && totalEthRaised <= ICOmaxCap) {
        wallet.transfer(address(this).balance);
    }
    if (totalEthRaised >= ICOmaxCap) {
        ico = false;
    }
}

function reimburse() public {
    require(_refundPeriod());
    withdrawPayments();
    EthRaisedIco = address(this).balance;
}

receive() external payable {
    if (presale) {
        buypresaleTokens(msg.sender);
    }
    if (ico) {
        buyICOTokens(msg.sender);
    }
}

function startICO() public onlyOwner {
    require(stateico && !presale, "Failed the ICO was already started or another salae is ongoing");
    refundPeriod = now.add(2764800);
    ico = true;
    token.lockToken();
    stateico = false;
}

function _executeOrder(
    address nftAddress,
    uint256 assetId,
    uint256 price,
    bytes fingerprint
)
internal returns(Order) {
    _requireERC721(nftAddress);
    ERC721Verifiable nftRegistry = ERC721Verifiable(nftAddress);
    if (nftRegistry.supportsInterface(InterfaceId_ValidateFingerprint)) {
        require(
            nftRegistry.verifyFingerprint(assetId, fingerprint),
            "The asset fingerprint is not valid"
        );
    }
    Order memory order = orderByAssetId[nftAddress][assetId];
    require(order.id != 0, "Asset not published");
    address seller = order.seller;
    require(seller != address(0), "Invalid address");
    require(seller != msg.sender, "Unauthorized user");
    require(order.price == price, "The price is not correct");
    require(block.timestamp < order.expiresAt, "The order expired");
    require(seller == nftRegistry.ownerOf(assetId), "The seller is no longer the owner");
    uint saleShareAmount = 0;
    bytes32 orderId = order.id;
    delete orderByAssetId[nftAddress][assetId];
    if (ownerCutPercentage > 0) {
        saleShareAmount = price.mul(ownerCutPercentage).div(100);
        require(
            acceptedToken.transferFrom(msg.sender, owner, saleShareAmount),
            "Transfering the cut to the Marketplace owner failed"
        );
    }
    require(
        acceptedToken.transferFrom(msg.sender, seller, price.sub(saleShareAmount)),
        "Transfering the sale amount to the seller failed"
    );
    nftRegistry.safeTransferFrom(
        seller,
        msg.sender,
        assetId
    );
    emit OrderSuccessful(
        orderId,
        assetId,
        seller,
        nftAddress,
        price,
        msg.sender
    );
    return order;
}

function _createOrder(
    address nftAddress,
    uint256 assetId,
    uint256 priceInWei,
    uint256 expiresAt
)
internal {
    _requireERC721(nftAddress);
    ERC721Interface nftRegistry = ERC721Interface(nftAddress);
    address assetOwner = nftRegistry.ownerOf(assetId);
    require(msg.sender == assetOwner, "Only the owner can create orders");
    require(
        nftRegistry.getApproved(assetId) == address(this) || nftRegistry.isApprovedForAll(assetOwner, address(this)),
        "The contract is not authorized to manage the asset"
    );
    require(priceInWei > 0, "Price should be bigger than 0");
    require(expiresAt > block.timestamp.add(1 minutes), "Expires should be bigger than 1 minute");
    bytes32 orderId = keccak256(
        abi.encodePacked(
            block.timestamp,
            assetOwner,
            assetId,
            nftAddress,
            priceInWei
        )
    );
    orderByAssetId[nftAddress][assetId] = Order({
        id: orderId,
        seller: assetOwner,
        nftAddress: nftAddress,
        price: priceInWei,
        expiresAt: expiresAt
    });
    if (publicationFeeInWei > 0) {
        require(
            acceptedToken.transferFrom(msg.sender, owner, publicationFeeInWei),
            "Transfering the publication fee to the Marketplace owner failed"
        );
    }
    emit OrderCreated(
        orderId,
        assetId,
        assetOwner,
        nftAddress,
        priceInWei,
        expiresAt
    );
}

