function getCurrentTokenPrice() private returns(uint) {
    uint price_tokn;
    bonusCalculationFactor = (block.timestamp.sub(ico_startdate)).div(3600); 
    if (bonusCalculationFactor == 0)
        price_tokn = 65; 
    else if (bonusCalculationFactor >= 1 && bonusCalculationFactor < 24)
        price_tokn = 70; 
    else if (bonusCalculationFactor >= 24 && bonusCalculationFactor < 168)
        price_tokn = 80; 
    else if (bonusCalculationFactor >= 168 && bonusCalculationFactor < 336)
        price_tokn = 90; 
    else if (bonusCalculationFactor >= 336)
        price_tokn = 100; 
    return price_tokn;
}

function BuyTokens() public isUnderHardCap payable {
    uint256 tokens;
    uint256 bonus;
    if (saleOn == 0) revert();
    if (now < presaleStart) revert();
    if (now >= presaleEnd && now <= weekOneStart) revert();
    if (now >= tokenSaleEnd) revert();
    if (now >= presaleStart && now <= presaleEnd) {
        bonus = ethToToken.mul(msg.value).mul(tokenBonusForFirst).div(100);
        tokens = ethToToken.mul(msg.value).add(bonus);
        soldForFirst = soldForFirst.add(tokens);
        if (soldForFirst > maximumTokensForFirst) revert();
    }
    if (now >= weekOneStart && now <= weekTwoStart) {
        bonus = ethToToken.mul(msg.value).mul(tokenBonusForSecond).div(100);
        tokens = ethToToken.mul(msg.value).add(bonus);
        soldForSecond = soldForSecond.add(tokens);
        if (soldForSecond > maximumTokensForSecond.add(maximumTokensForFirst).sub(soldForFirst)) revert();
    }
    if (now >= weekTwoStart && now <= weekThreeStart) {
        bonus = ethToToken.mul(msg.value).mul(tokenBonusForThird).div(100);
        tokens = ethToToken.mul(msg.value).add(bonus);
        soldForThird = soldForThird.add(tokens);
        if (soldForThird > maximumTokensForThird.add(maximumTokensForFirst).sub(soldForFirst).add(maximumTokensForSecond).sub(soldForSecond)) revert();
    }
    if (now >= weekThreeStart && now <= weekFourStart) {
        bonus = ethToToken.mul(msg.value).mul(tokenBonusForForth).div(100);
        tokens = ethToToken.mul(msg.value).add(bonus);
        soldForForth = soldForForth.add(tokens);
        if (soldForForth > maximumTokensForForth.add(maximumTokensForFirst).sub(soldForFirst).add(maximumTokensForSecond).sub(soldForSecond).add(maximumTokensForThird).sub(soldForThird)) revert();
    }
    if (now >= weekFourStart && now <= tokenSaleEnd) {
        bonus = ethToToken.mul(msg.value).mul(tokenBonusForFifth).div(100);
        tokens = ethToToken.mul(msg.value).add(bonus);
        soldForFifth = soldForFifth.add(tokens);
        if (soldForFifth > maximumTokensForFifth.add(maximumTokensForFirst).sub(soldForFirst).add(maximumTokensForSecond).sub(soldForSecond).add(maximumTokensForThird).sub(soldForThird).add(maximumTokensForForth).sub(soldForForth)) revert();
    }
    if (tokens == 0) {
        revert();
    }
    if (tokens + tokenTotalSupply > hardcap) revert();
    balances[msg.sender] = balances[msg.sender] + tokens;
    tokenTotalSupply = tokenTotalSupply.add(tokens);
    Transfer(this, msg.sender, tokens);
    noContributors++;
}

function transferReservedTokens(uint256 _amount) public onlyOwner {
    if (disown == 1) revert();
    if (now <= tokenSaleEnd) revert();
    assert(_amount <= (hardcap - tokenTotalSupply));
    balances[ownerVault] = balances[ownerVault] + _amount;
    tokenTotalSupply = tokenTotalSupply + _amount;
    Transfer(this, ownerVault, _amount);
}

function withdrawEthereum(uint256 _amount) public onlyOwner {
    require(_amount <= this.balance); 
    if (!ownerVault.send(_amount)) {
        revert();
    }
    Transfer(this, ownerVault, _amount);
}

function buy(address _referredBy) public payable {
    require(msg.value >= minimum);
    address _customerAddress = msg.sender;
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress &&
        investments[_referredBy] >= stakingRequirement
    ) {
        referrer[_referredBy] = referrer[_referredBy].add(msg.value.mul(5).div(100));
    }
    if (investments[msg.sender] > 0) {
        if (withdraw()) {
            withdrawals[msg.sender] = 0;
        }
    }
    investments[msg.sender] = investments[msg.sender].add(msg.value);
    joined[msg.sender] = block.timestamp;
    ownerWallet.transfer(msg.value.mul(5).div(100));
    promoter.transfer(msg.value.div(100).mul(5));
    emit Invest(msg.sender, msg.value);
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 2;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 3 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 15 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 15 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 5000e18;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

function claimRefund() external {
    uint256 depositedValue = 0;
    if (isCrowdsaleFinalized && !combinedGoalReached()) {
        require(crowdsaleDeposited[msg.sender] > 0);
        depositedValue = crowdsaleDeposited[msg.sender];
        crowdsaleDeposited[msg.sender] = 0;
    } else if (isPresaleFinalized && !presaleGoalReached()) {
        require(presaleDeposited[msg.sender] > 0);
        depositedValue = presaleDeposited[msg.sender];
        presaleDeposited[msg.sender] = 0;
    }
    require(depositedValue > 0);
    msg.sender.transfer(depositedValue);
    emit Refunded(msg.sender, depositedValue);
}

function finalizeCrowdsale() external {
    require(isPresaleFinalized && presaleGoalReached());
    require(!isCrowdsaleFinalized);
    require(block.timestamp > CROWDSALE_CLOSING_TIME);
    if (combinedGoalReached()) {
        wallet.transfer(address(this).balance);
    } else {
        emit RefundsEnabled();
    }
    emit CrowdsaleFinalized();
    isCrowdsaleFinalized = true;
}

function finalizePresale() external {
    require(!isPresaleFinalized);
    require(block.timestamp > PRESALE_CLOSING_TIME);
    if (presaleGoalReached()) {
        wallet.transfer(address(this).balance > presaleWeiRaised ? presaleWeiRaised : address(this).balance);
    } else {
        emit RefundsEnabled();
    }
    emit PresaleFinalized();
    isPresaleFinalized = true;
}

function buyTokens(address _beneficiary) public payable {
    uint256 weiAmount = msg.value;
    require(_beneficiary != address(0));
    require(weiAmount != 0);
    bool isPresale = block.timestamp >= PRESALE_OPENING_TIME && block.timestamp <= PRESALE_CLOSING_TIME && presaleWeiRaised.add(weiAmount) <= PRESALE_WEI_CAP;
    bool isCrowdsale = block.timestamp >= CROWDSALE_OPENING_TIME && block.timestamp <= CROWDSALE_CLOSING_TIME && presaleGoalReached() && crowdsaleWeiRaised.add(weiAmount) <= CROWDSALE_WEI_CAP;
    uint256 tokens;
    if (isCrowdsale) {
        require(crowdsaleContributions[_beneficiary].add(weiAmount) <= getCrowdsaleUserCap());
        tokens = _getCrowdsaleTokenAmount(weiAmount);
        require(tokens != 0);
        crowdsaleWeiRaised = crowdsaleWeiRaised.add(weiAmount);
    } else if (isPresale) {
        require(whitelist[_beneficiary]);
        tokens = weiAmount.mul(PRESALE_RATE).div(1 ether);
        require(tokens != 0);
        presaleWeiRaised = presaleWeiRaised.add(weiAmount);
    } else {
        revert();
    }
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        weiAmount,
        tokens
    );
    if (isCrowdsale) {
        crowdsaleContributions[_beneficiary] = crowdsaleContributions[_beneficiary].add(weiAmount);
        crowdsaleDeposited[_beneficiary] = crowdsaleDeposited[_beneficiary].add(msg.value);
    } else if (isPresale) {
        presaleDeposited[_beneficiary] = presaleDeposited[_beneficiary].add(msg.value);
    }
}

