constructor(
    address drupe,
    uint basePriceN, uint basePriceD,
    uint refBonusN, uint refBonusD,
    uint presale1Start, uint presale1BonusN, uint presale1BonusD,
    uint presale2Start, uint presale2BonusN, uint presale2BonusD,
    uint mainsaleStart, uint mainsaleEnd
) public {
    require(drupe != address(0));
    require(basePriceN > 0 && basePriceD > 0);
    require(refBonusN > 0 && basePriceD > 0);
    require(presale1Start > now);
    require(presale1BonusN > 0 && presale1BonusD > 0);
    require(presale2Start > presale1Start);
    require(presale2BonusN > 0 && presale2BonusD > 0);
    require(mainsaleStart > presale2Start);
    require(mainsaleEnd > mainsaleStart);
    _owner = msg.sender;
    _newOwner = address(0);
    _drupe = DrupeCoin(drupe);
    _basePrice = Fraction({
        n: basePriceN,
        d: basePriceD
    });
    _refBonus = Fraction({
        n: refBonusN,
        d: refBonusD
    });
    _presale1 = Presale({
        start: presale1Start,
        bonus: Fraction({
            n: presale1BonusN,
            d: presale1BonusD
        })
    });
    _presale2 = Presale({
        start: presale2Start,
        bonus: Fraction({
            n: presale2BonusN,
            d: presale2BonusD
        })
    });
    _mainsale = Mainsale({
        start: mainsaleStart,
        end: mainsaleEnd
    });
}

function addLiquidity() internal {
    uint256 ETH = address(this).balance;
    uint256 tokensForUniswap = address(this).balance.mul(7000);
    uint256 tokensToBurn = ABS.balanceOf(address(this)).sub(tokensForUniswap).sub(teamTokens);
    ABS.unPauseTransferForever();
    ABS.approve(address(uniswap), tokensForUniswap);
    uniswap.addLiquidityETH {
            value: ETH
        }
        (
            address(ABS),
            tokensForUniswap,
            tokensForUniswap,
            ETH,
            address(this),
            block.timestamp
        );
    if (tokensToBurn > 0) {
        ABS.transfer(_burnPool, tokensToBurn);
    }
    justTrigger = true;
    if (!isStopped)
        isStopped = true;
}

