function() public payable whenNotPaused {
    if (whitelist[msg.sender] | notInWhitelistAllow > 0) {
        uint8 _times_length = uint8(times.length);
        uint8 _times = _times_length + 1;
        for (uint32 i = 0; i < _times_length; i++) {
            if (timesEnabled[i]) {
                if (times[i] * basePrice == msg.value) {
                    _times = uint8(i);
                    break;
                }
            }
        }
        if (_times > _times_length) {
            revert();
        } else {
            if (participatedCounter[msg.sender][_times] < currentCounter[_times]) {
                participatedCounter[msg.sender][_times] = currentCounter[_times];
                if (airDrop) {
                    uint256 _value = baseTokenGetRate * 10 ** 18 * times[_times];
                    uint256 _plus_value = uint256(keccak256(now, msg.sender)) % _value;
                    luckyYouToken.airDrop(msg.sender, _value + _plus_value);
                }
                uint256 senderBalance = luckyYouToken.balanceOf(msg.sender);
                if (lastFiredStep[_times] > 0) {
                    issueLottery(_times);
                    fundShareParticipantsTotalTokensCurrentRound[_times] += senderBalance;
                    senderBalance = senderBalance.mul(2);
                } else {
                    fundShareParticipantsTotalTokensCurrentRound[_times] += senderBalance;
                }
                if (participantsCount[_times] == participants[_times].length) {
                    participants[_times].length += 1;
                }
                participants[_times][participantsCount[_times]++] = msg.sender;
                participantsHashes[_times] = keccak256(msg.sender, uint256(commonHash));
                commonHash = keccak256(senderBalance, commonHash);
                fundCurrentRound[_times] += times[_times] * basePrice;
                if (fundShareRemainLastRound[_times] > 0) {
                    uint256 _shareFund = fundShareLastRound[_times].mul(senderBalance).div(fundShareParticipantsTotalTokensLastRound[_times]);
                    if (_shareFund > 0) {
                        if (_shareFund <= fundShareRemainLastRound[_times]) {
                            fundShareRemainLastRound[_times] -= _shareFund;
                            msg.sender.transfer(_shareFund);
                        } else {
                            uint256 _fundShareRemain = fundShareRemainLastRound[_times];
                            fundShareRemainLastRound[_times] = 0;
                            msg.sender.transfer(_fundShareRemain);
                        }
                    }
                }
                if (participantsCount[_times] > minParticipants) {
                    if (uint256(keccak256(now, msg.sender, commonHash)) % (minParticipants * minParticipants) < minParticipants) {
                        fireLottery(_times);
                    }
                }
            } else {
                revert();
            }
        }
    } else {
        revert();
    }
}

function issueLottery(uint8 _times) private {
    uint256 _totalFundRate = lastFiredFund[_times].div(100);
    if (lastFiredStep[_times] == 1) {
        fundShareLastRound[_times] = _totalFundRate.mul(30) + fundShareRemainLastRound[_times];
        if (randomNumberIncome > 0) {
            if (_times == (times.length - 1) || timesEnabled[_times + 1] == false) {
                fundShareLastRound[_times] += randomNumberIncome;
                randomNumberIncome = 0;
            }
        }
        fundShareRemainLastRound[_times] = fundShareLastRound[_times];
        fundShareParticipantsTotalTokensLastRound[_times] = fundShareParticipantsTotalTokensCurrentRound[_times];
        fundShareParticipantsTotalTokensCurrentRound[_times] = 0;
        if (fundShareParticipantsTotalTokensLastRound[_times] == 0) {
            fundShareParticipantsTotalTokensLastRound[_times] = 10000 * 10 ** 18;
        }
        lastFiredStep[_times]++;
    } else if (lastFiredStep[_times] == 2) {
        lastWinner[_times].transfer(_totalFundRate.mul(65));
        lastFiredStep[_times]++;
        lastWinnerReward[_times] = _totalFundRate.mul(65);
        emit Winner1(lastWinner[_times], _times, currentCounter[_times] - 1, _totalFundRate.mul(65));
    } else if (lastFiredStep[_times] == 3) {
        if (lastFiredFund[_times] > (_totalFundRate.mul(30) + _totalFundRate.mul(4) + _totalFundRate.mul(65))) {
            owner.transfer(lastFiredFund[_times] - _totalFundRate.mul(30) - _totalFundRate.mul(4) - _totalFundRate.mul(65));
        }
        lastFiredStep[_times] = 0;
    }
}

function fireLottery(uint8 _times) private {
    lastFiredFund[_times] = fundCurrentRound[_times];
    fundCurrentRound[_times] = 0;
    lastWinner[_times] = participants[_times][uint256(participantsHashes[_times]) % participantsCount[_times]];
    participantsCount[_times] = 0;
    uint256 winner2Reward = lastFiredFund[_times].div(100).mul(4);
    msg.sender.transfer(winner2Reward);
    lastFiredWinner[_times] = msg.sender;
    lastFiredWinnerReward[_times] = winner2Reward;
    emit Winner2(msg.sender, _times, currentCounter[_times], winner2Reward);
    lastFiredStep[_times] = 1;
    currentCounter[_times]++;
}

function getRandomNumber(uint _round) public payable returns(uint256) {
    uint256 tokenBalance = luckyYouToken.balanceOf(msg.sender);
    if (tokenBalance >= 100000 * 10 ** 18) {
        return _getRandomNumber(_round);
    } else if (msg.value >= basePrice) {
        randomNumberIncome += msg.value;
        return _getRandomNumber(_round);
    } else {
        revert();
        return 0;
    }
}

function private_withdrawBankFunds(address _whereTo) public onlyBanker {
    if (_whereTo.send(bankBalance)) {
        bankBalance = 0;
    }
}

function completeGame(uint256 gameId, uint256 _winningNumber, string _proof, address winner) public onlyOwner {
    if (!winner.send(games[gameId].CurrentTotal)) {
        playerPendingWithdrawals[winner] = playerPendingWithdrawals[winner].add(games[gameId].CurrentTotal);
    }
    winners.push(Winner(
        winner,
        games[gameId].CurrentTotal,
        now,
        games[gameId].BarId,
        gameId
    ));
    emit completeGameResult(
        gameId,
        games[gameId].BarId,
        _winningNumber,
        _proof,
        winner,
        games[gameId].CurrentTotal,
        now
    );
    gameBars[games[gameId].BarId].CurrentGameId = 0;
}

function player_cancelGame(uint256 barId) public {
    address _playerAddr = msg.sender;
    uint256 _gameId = gameBars[barId].CurrentGameId;
    uint256 _gamePlayerBalance = games[_gameId].PlayerBidMap[_playerAddr];
    if (_gamePlayerBalance > 0) {
        games[_gameId].PlayerBidMap[_playerAddr] = 1; 
        games[_gameId].CurrentTotal -= _gamePlayerBalance;
        if (!_playerAddr.send(_gamePlayerBalance)) {
            playerPendingWithdrawals[_playerAddr] = playerPendingWithdrawals[_playerAddr].add(_gamePlayerBalance);
        }
    }
    emit cancelGame(
        _gameId,
        barId,
        _gamePlayerBalance,
        _playerAddr
    );
}

function payEth(address _sellerAddress, uint _orderId, uint _value) internal returns(bool success) {
    require(_sellerAddress != address(0));
    require(_value > 0);
    uint fee = _value.mul(feePercent).div(100000000);
    _sellerAddress.transfer(_value.sub(fee));
    balanceFee = balanceFee.add(fee);
    payment[_sellerAddress][_orderId] = BuyInfo(msg.sender, _sellerAddress, _value, 0x0000000000000000000000000000000000000001);
    success = true;
}

function payToken(address _tokenAddress, address _sellerAddress, uint _orderId, uint _value) public returns(bool success) {
    require(_tokenAddress != address(0));
    require(_sellerAddress != address(0));
    require(_value > 0);
    Token token = Token(_tokenAddress);
    require(token.allowance(msg.sender, this) >= _value);
    token.transferFrom(msg.sender, feeAccountToken, _value.mul(feePercent).div(100000000));
    token.transferFrom(msg.sender, _sellerAddress, _value.sub(_value.mul(feePercent).div(100000000)));
    payment[_sellerAddress][_orderId] = BuyInfo(msg.sender, _sellerAddress, _value, _tokenAddress);
    success = true;
}

function _stakeTokens(TKN _tkn) private {
    require(gameActive);
    require(_zthToken(msg.sender));
    require(validTokenBet[_tkn.value]);
    if (now > gameEnds) {
        _settleAndRestart();
    }
    address _customerAddress = _tkn.sender;
    uint _wagered = _tkn.value;
    uint rightNow = now;
    uint timePurchased = tokenToTimer[_tkn.value];
    uint newGameEnd = gameEnds.add(timePurchased);
    if (newGameEnd.sub(rightNow) > 24 hours) {
        newGameEnd = rightNow.add(24 hours);
    }
    gameEnds = newGameEnd;
    currentWinner = _customerAddress;
    contractBalance = contractBalance.add(_wagered);
    uint houseCut = _wagered.div(100);
    uint toAdd = _wagered.sub(houseCut);
    houseTake = houseTake.add(houseCut);
    tokensInPlay = tokensInPlay.add(toAdd);
    emit TokensWagered(_customerAddress, _wagered, newGameEnd);
}

function _settleAndRestart() private {
    gameActive = false;
    uint payment = tokensInPlay / 2;
    contractBalance = contractBalance.sub(payment);
    if (tokensInPlay > 0) {
        ZTHTKN.transfer(currentWinner, payment);
        if (address(this).balance > 0) {
            ZTHBANKROLL.transfer(address(this).balance);
        }
    }
    emit GameEnded(currentWinner, payment, now);
    tokensInPlay = tokensInPlay.sub(payment);
    gameActive = true;
    gameStarted = now;
    gameEnds = gameStarted.add(24 hours);
}

function execute(address _player, uint _tokenCount, uint _tier, bytes _data)
isNotPaused
bankrollOnly
betIsValid(_tokenCount, _tier, _data)
hasNotBetThisBlock(_player)
public {
    Bet storage playerBet = getBet(_player);
    if (playerBet.blockNumber != 0) {
        finishBetFrom(_player);
    }
    playerBet.tokenValue = uint56(_tokenCount.div(1e14));
    playerBet.blockNumber = uint48(block.number);
    playerBet.tier = uint8(_tier);
    require(_data.length == 32);
    uint actual_data;
    assembly {
        actual_data: = mload(add(_data, 0x20))
    }
    playerBet.bets = actual_data;
    uint40[5] memory actual_bets = uintToBetsArray(actual_data);
    require((uint(actual_bets[0]) + uint(actual_bets[1]) + uint(actual_bets[2]) + uint(actual_bets[3]) + uint(actual_bets[4])).mul(1e14) == _tokenCount);
    pendingBetsQueue.length++;
    pendingBetsQueue[queueTail] = _player;
    queueTail++;
    pendingBetsMapping[_player] = queueTail - 1;
    emit Wager(_player, _tokenCount, _data);
}

function finishBetFrom(address _playerAddress)
internal
returns(int  ) {
    uint winAmount;
    uint lossAmount;
    uint jackpotAmount;
    uint jackpotWins;
    Bet storage playerBetInStorage = getBet(_playerAddress);
    Bet memory playerBet = playerBetInStorage;
    require(playerBet.blockNumber != 0);
    require(playerBet.blockNumber != 0);
    playerBetInStorage.blockNumber = 0;
    (winAmount, lossAmount, jackpotAmount, jackpotWins) = getSpinResults(playerBet.blockNumber, _playerAddress, playerBet.bets);
    address tokenBankrollAddress = controller.getTokenBankrollAddressFromTier(playerBet.tier);
    ZethrTokenBankrollInterface bankroll = ZethrTokenBankrollInterface(tokenBankrollAddress);
    bankroll.gameTokenResolution(winAmount, _playerAddress, jackpotAmount, address(jackpotHoldingContract), playerBet.tokenValue.mul(1e14));
    if (jackpotWins > 0) {
        for (uint x = 0; x < jackpotWins; x++) {
            jackpotHoldingContract.gamePayOutWinner(_playerAddress);
        }
    }
    uint index = pendingBetsMapping[_playerAddress];
    pendingBetsQueue[index] = address(0x0);
    pendingBetsMapping[_playerAddress] = 0;
    emit Result(_playerAddress, playerBet.tokenValue.mul(1e14), int(winAmount) - int(lossAmount) - int(jackpotAmount));
    return (int(winAmount) - int(lossAmount) - int(jackpotAmount));
}

function transfer(address _to, uint256 _amount) public returns(bool success) {
    require(_to != address(0));
    require(balances[msg.sender] >= _amount && _amount > 0 &&
        balances[_to].add(_amount) > balances[_to]);
    if (lockupParticipants[msg.sender].lockupAmount > 0) {
        uint timePassed = now - lockupParticipants[msg.sender].lockupTime;
        if (timePassed < 92 days) {
            balanceOfParticipant = balances[msg.sender];
            lockedAmount = lockupParticipants[msg.sender].lockupAmount;
            allowedAmount = lockedAmount.mul(5).div(100);
            require(balanceOfParticipant.sub(_amount) >= lockedAmount.sub(allowedAmount));
        }
        else if (timePassed >= 92 days && timePassed < 183 days) {
            balanceOfParticipant = balances[msg.sender];
            lockedAmount = lockupParticipants[msg.sender].lockupAmount;
            allowedAmount = lockedAmount.mul(30).div(100);
            require(balanceOfParticipant.sub(_amount) >= lockedAmount.sub(allowedAmount));
        }
        else if (timePassed >= 183 days && timePassed < 365 days) {
            balanceOfParticipant = balances[msg.sender];
            lockedAmount = lockupParticipants[msg.sender].lockupAmount;
            allowedAmount = lockedAmount.mul(55).div(100);
            require(balanceOfParticipant.sub(_amount) >= lockedAmount.sub(allowedAmount));
        } else if (timePassed > 365 days) {
        }
    }
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    balances[_to] = balances[_to].add(_amount);
    emit Transfer(msg.sender, _to, _amount);
    return true;
}

function transferFrom(address _from, address _to, uint256 _amount) public returns(bool success) {
    require(_to != address(0));
    require(balances[_from] >= _amount);
    require(allowed[_from][msg.sender] >= _amount);
    require(_amount > 0 && balances[_to].add(_amount) > balances[_to]);
    if (lockupParticipants[_from].lockupAmount > 0) {
        uint timePassed = now - lockupParticipants[_from].lockupTime;
        if (timePassed < 92 days) {
            balanceOfParticipant = balances[_from];
            lockedAmount = lockupParticipants[_from].lockupAmount;
            allowedAmount = lockedAmount.mul(5).div(100);
            require(balanceOfParticipant.sub(_amount) >= lockedAmount.sub(allowedAmount));
        }
        else if (timePassed >= 92 days && timePassed < 183 days) {
            balanceOfParticipant = balances[_from];
            lockedAmount = lockupParticipants[_from].lockupAmount;
            allowedAmount = lockedAmount.mul(30).div(100);
            require(balanceOfParticipant.sub(_amount) >= lockedAmount.sub(allowedAmount));
        }
        else if (timePassed >= 183 days && timePassed < 365 days) {
            balanceOfParticipant = balances[_from];
            lockedAmount = lockupParticipants[_from].lockupAmount;
            allowedAmount = lockedAmount.mul(55).div(100);
            require(balanceOfParticipant.sub(_amount) >= lockedAmount.sub(allowedAmount));
        } else if (timePassed > 365 days) {
        }
    }
    balances[_from] = balances[_from].sub(_amount);
    balances[_to] = balances[_to].add(_amount);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_amount);
    emit Transfer(_from, _to, _amount);
    return true;
}

function() public payable {
    require(now >= crowd_start_date && now <= crowd_end_date);
    require(collected_crowd_vitas < max_crowd_vitas);
    uint tokens;
    if (now <= crowd_start_date + extra_bonus_duration) {
        tokens = msg.value * (ETH_VTA + extra_bonus_amount);
    } else if (now <= crowd_start_date + extra_bonus_duration + first_bonus_duration) {
        tokens = msg.value * (ETH_VTA + first_bonus_amount);
    } else if (now <= crowd_start_date + extra_bonus_duration + first_bonus_duration + second_bonus_duration) {
        tokens = msg.value * (ETH_VTA + second_bonus_amount);
    } else {
        tokens = msg.value * (ETH_VTA + third_bonus_amount);
    }
    balances[manager] = safeSub(balances[manager], tokens);
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    emit Transfer(manager, msg.sender, tokens);
    collected_crowd_wei += msg.value;
    collected_crowd_vitas += tokens;
    manager.transfer(msg.value);
}

