function receiveApproval(address _from, uint _amountOfTokens, address _token, bytes _data)
external
senderIsToken
contractNotPaused {
    require(_amountOfTokens > 0, "amount should be > 0");
    require(_from != address(0), "not valid from");
    require(_data.length == 64, "not valid _data length");
    bytes32 poolIdString = bytesToFixedBytes32(_data, 0);
    bytes32 contributionIdString = bytesToFixedBytes32(_data, 32);
    require(pools[poolIdString].status == PoolStatus.Active, "Status should be active");
    require(pools[poolIdString].contributionStartUtc < now, "Contribution is not started");
    require(pools[poolIdString].contributionEndUtc > now, "Contribution is ended");
    require(pools[poolIdString].contributions[contributionIdString].amount == 0, 'Contribution duplicated');
    require(pools[poolIdString].amountLimit == 0 ||
        pools[poolIdString].amountLimit >= pools[poolIdString].amountCollected.add(_amountOfTokens), "Contribution limit reached");
    require(IERC20(_token).transferFrom(_from, address(this), _amountOfTokens), "Tokens transfer failed.");
    walletPools[_from].push(ContributionIndex(poolIdString, contributionIdString));
    pools[poolIdString].amountCollected = pools[poolIdString].amountCollected.add(_amountOfTokens);
    pools[poolIdString].contributions[contributionIdString].owner = _from;
    pools[poolIdString].contributions[contributionIdString].amount = _amountOfTokens;
    emit ContributionAdded(poolIdString, contributionIdString);
}

function payout(bytes32 _poolId, bytes32 _contributionId) public contractNotPaused {
    require(pools[_poolId].status == PoolStatus.Distributing, "Pool should be Distributing");
    require(pools[_poolId].amountDistributing > pools[_poolId].paidout, "Pool should be not empty");
    Contribution storage con = pools[_poolId].contributions[_contributionId];
    require(con.paidout == 0, "Contribution already paidout");
    IPrizeCalculator calculator = IPrizeCalculator(pools[_poolId].prizeCalculator);
    uint winAmount = calculator.calculatePrizeAmount(
        pools[_poolId].amountDistributing,
        pools[_poolId].amountCollected,
        con.amount
    );
    assert(winAmount > 0);
    con.paidout = winAmount;
    pools[_poolId].paidout = pools[_poolId].paidout.add(winAmount);
    assert(IERC20(token).transfer(con.owner, winAmount));
    emit Paidout(_poolId, _contributionId);
}

function transferToDestination(bytes32 _poolId) external onlyOwnerOrSuperOwner {
    assert(IERC20(token).transfer(pools[_poolId].destination, pools[_poolId].amountCollected));
    setPoolStatus(_poolId, PoolStatus.Funding);
}

function canBeTransfered(address addr, uint256 value) returns(bool) {
    for (uint i = 0; i < locks.length; i++) {
        if (locks[i].ADDRESS == addr) {
            if (value > balanceOf(addr).sub(locks[i].AMOUNT) && locks[i].TIME > now) {
                return false;
            }
        }
    }
    return true;
}

function tokens_buy() payable returns(bool) {
    require(active > 0);
    require(msg.value >= token_price);
    uint tokens_buy = msg.value * 10 ** 18 / token_price;
    require(tokens_buy > 0);
    if (!c.call(bytes4(sha3("transferFrom(address,address,uint256)")), owner, msg.sender, tokens_buy)) {
        return false;
    }
    uint sum2 = msg.value * 3 / 10;
    owner2.send(sum2);
    return true;
}

constructor(IERC20 token, address beneficiary, uint256 releaseTime) public {
    require(releaseTime > block.timestamp, 'release time is before');
    _token = token;
    _beneficiary = beneficiary;
    _deployeTime = block.timestamp;
    _releaseTime = releaseTime;
}

function releasePartOne() public {
    require(block.timestamp >= _deployeTime + part1Time, 'before release time');
    require(_token.balanceOf(address(this)) > 0, 'release done');
    require(part1Statue == true, 'release done');
    _token.transfer(_beneficiary, Part1Qty);
    part1Statue = false;
}

function release() public {
    require(block.timestamp >= _releaseTime + (stepTime * releaseCount), 'before release time');
    uint thisBalance = _token.balanceOf(address(this));
    require(thisBalance > 0, 'release done');
    if (thisBalance >= releaseQty) {
        _token.transfer(_beneficiary, releaseQty);
    } else {
        _token.transfer(_beneficiary, thisBalance);
    }
    releaseCount++;
}

function annualInterest() public constant returns(uint interest) {
    uint _now = now;
    interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime)).div(1 years) == 0) {
        interest = (770 * maxMintProofOfStake).div(100);
    } else if ((_now.sub(stakeStartTime)).div(1 years) == 1) {
        interest = (435 * maxMintProofOfStake).div(100);
    }
}

function trade(OrderLibrary.Order memory order, address taker, bytes signature, uint maxFillAmount) internal {
    require(taker != order.maker);
    bytes32 hash = order.hash();
    require(order.makerToken != order.takerToken);
    require(canTrade(order, signature, hash));
    uint fillAmount = SafeMath.min256(maxFillAmount, availableAmount(order, hash));
    require(roundingPercent(fillAmount, order.takerTokenAmount, order.makerTokenAmount) <= MAX_ROUNDING_PERCENTAGE);
    require(vault.balanceOf(order.takerToken, taker) >= fillAmount);
    uint makeAmount = order.makerTokenAmount.mul(fillAmount).div(order.takerTokenAmount);
    uint tradeTakerFee = makeAmount.mul(takerFee).div(1 ether);
    if (tradeTakerFee > 0) {
        vault.transfer(order.makerToken, order.maker, feeAccount, tradeTakerFee);
    }
    vault.transfer(order.takerToken, taker, order.maker, fillAmount);
    vault.transfer(order.makerToken, order.maker, taker, makeAmount.sub(tradeTakerFee));
    fills[hash] = fills[hash].add(fillAmount);
    assert(fills[hash] <= order.takerTokenAmount);
    if (subscribed[order.maker]) {
        order.maker.call.gas(MAX_HOOK_GAS)(HookSubscriber(order.maker).tradeExecuted.selector, order.takerToken, fillAmount);
    }
    emit Traded(
        hash,
        order.makerToken,
        makeAmount,
        order.takerToken,
        fillAmount,
        order.maker,
        taker
    );
}

function canTrade(OrderLibrary.Order memory order, bytes signature, bytes32 hash)
internal
view
returns(bool) {
    if (fills[hash] == 0) {
        if (!isOrdered(order.maker, hash) && !SignatureValidator.isValidSignature(hash, order.maker, signature)) {
            return false;
        }
    }
    if (cancelled[hash]) {
        return false;
    }
    if (!vault.isApproved(order.maker, this)) {
        return false;
    }
    if (order.takerTokenAmount == 0) {
        return false;
    }
    if (order.makerTokenAmount == 0) {
        return false;
    }
    if (availableAmount(order, hash) == 0) {
        return false;
    }
    return order.expires > now;
}

function order(address[2] addresses, uint[4] values) external {
    OrderLibrary.Order memory order = OrderLibrary.createOrder(
        [msg.sender, addresses[0], addresses[1]],
        values
    );
    require(vault.isApproved(order.maker, this));
    require(vault.balanceOf(order.makerToken, order.maker) >= order.makerTokenAmount);
    require(order.makerToken != order.takerToken);
    require(order.makerTokenAmount > 0);
    require(order.takerTokenAmount > 0);
    bytes32 hash = order.hash();
    require(!orders[msg.sender][hash]);
    orders[msg.sender][hash] = true;
    emit Ordered(
        order.maker,
        order.makerToken,
        order.takerToken,
        order.makerTokenAmount,
        order.takerTokenAmount,
        order.expires,
        order.nonce
    );
}

