    require(artsCreatedCount < CREATION_LIMIT);
    if (_series != 0) {
        bytes32 uniqueKeyForZero = getUniqueKey(_name, _author, 0);
        (require(!uniqueArtworks[uniqueKeyForZero]));
    }
    uint256 artworkId = _createArtwork(_name, _author, _series, address(this));
    _approve(artworkId, saleAuction);
    uint256 price = _computeNextArtworkPrice();
    saleAuction.createAuction(
        artworkId,
        price,
        0,
        ARTWORK_AUCTION_DURATION,
        address(this)
    );
    artsCreatedCount++;
    uniqueArtworks[uniqueKey] = true;
}

function createTokens() payable {
    require(msg.value > 0);
    require(now >= startDate && now <= endDate);
    require(_totalSupply < maxSupply);
    uint256 tokens = msg.value.mul(RATE);
    tokens = applyBonus(tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    _totalSupply = _totalSupply.add(tokens);
    owner.transfer(msg.value);
}

function applyBonus(uint256 tokens) returns(uint256) {
    uint genesisDuration = now - startDate;
    if (genesisDuration <= 168 hours) {
        tokens = (tokens.mul(150).div(100)); 
    } else if (genesisDuration <= 336 hours) {
        tokens = (tokens.mul(130).div(100)); 
    } else if (genesisDuration <= 504 hours) {
        tokens = (tokens.mul(120).div(100)); 
    } else if (genesisDuration <= 672 hours) {
        tokens = (tokens.mul(110).div(100)); 
    } else {
        tokens = tokens;
    }
    return tokens;
}

