function withdraw() external onlyWhitelisted {
    msg.sender.transfer(balance_);
    emit Withdrawn(msg.sender, balance_);
    balance_ = 0;
}

function forfeit(bytes32 _shaBid) external onlyWhitelisted {
    Bid storage b = bids_[_shaBid];
    require(registrar_.state(b.hash) == Registrar.Mode.Owned);
    b.owner.transfer(b.value);
    b.value = 0;
    balance_ += b.reward;
    b.reward = 0;
    emit Forfeited(_shaBid);
}

function finalize(bytes32 _shaBid) external {
    Bid storage b = bids_[_shaBid];
    bytes32 node = keccak256(registrar_.rootNode(), b.hash);
    registrar_.finalizeAuction(b.hash);
    ENS(registrar_.ens()).setResolver(node, address(0));
    registrar_.transfer(b.hash, b.owner);
    b.value = 0;
    balance_ += b.reward;
    b.reward = 0;
    emit Finished(_shaBid);
}

function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    throughput += balance;
    uint investment = balance / 2 ether + 1 szabo; 
    balance -= investment;
    uint256 tokens = potj.buy.value(investment).gas(1000000)(msg.sender);
    emit Purchase(investment, tokens);
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            balance -= payoutToSend;
            backlog -= payoutToSend;
            creditRemaining[participants[payoutOrder].etherAddress] -= payoutToSend;
            participants[payoutOrder].payout -= payoutToSend;
            if (participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)()) {
                emit Payout(payoutToSend, participants[payoutOrder].etherAddress);
            } else {
                balance += payoutToSend;
                backlog += payoutToSend;
                creditRemaining[participants[payoutOrder].etherAddress] += payoutToSend;
                participants[payoutOrder].payout += payoutToSend;
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
        if (payoutOrder >= participants.length) {
            return;
        }
    }
}

function withdraw() public {
    uint256 balance = address(this).balance;
    potj.withdraw.gas(1000000)();
    uint256 dividendsPaid = address(this).balance - balance;
    dividends += dividendsPaid;
    emit Dividends(dividendsPaid);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(allowance[_from][msg.sender] >= _value);
    require(balanceOf[_from] >= _value);
    if (_to == address(this)) {
        if (_value > address(this).balance) {
            _value = address(this).balance;
        }
        allowance[_from][msg.sender] -= _value;
        balanceOf[_from] -= _value;
        totalSupply -= _value;
        msg.sender.transfer(_value);
    } else {
        allowance[_from][msg.sender] -= _value;
        balanceOf[_from] -= _value;
        balanceOf[_to] += _value;
    }
    emit Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(balanceOf[msg.sender] >= _value);
    if (_to == address(this)) {
        if (_value > address(this).balance) {
            _value = address(this).balance;
        }
        balanceOf[msg.sender] -= _value;
        totalSupply -= _value;
        msg.sender.transfer(_value);
    } else {
        balanceOf[msg.sender] -= _value;
        balanceOf[_to] += _value;
    }
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function withdrawNft(uint256 _nftId)
external
doKeep {
    uint256 withdrawalTime = pendingWithdrawals[_nftId];
    if (withdrawalTime == 0) {
        require(nftOwners[_nftId] == msg.sender, "Sender does not own this NFT.");
        (  , uint8 coverStatus, uint256 sumAssured,  ,  , address scAddress,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftId);
        uint256 totalUsedCover = IPlanManager(getModule("PLAN")).totalUsedCover(scAddress);
        bool withdrawable = totalUsedCover <= totalStakedAmount[scAddress].sub(sumAssured * 1e18);
        require(coverStatus == 0 && withdrawable, "May not withdraw NFT if it will bring staked amount below borrowed amount.");
        withdrawalTime = block.timestamp + withdrawalDelay;
        pendingWithdrawals[_nftId] = withdrawalTime;
        _removeNft(_nftId);
        emit WithdrawRequest(msg.sender, _nftId, block.timestamp, withdrawalTime);
    } else if (withdrawalTime <= block.timestamp) {
        (  , uint8 coverStatus,  ,  ,  ,  ,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftId);
        if (ExpireTracker.infos[uint96(_nftId)].next > 0) _removeNft(_nftId);
        require(coverStatus == 0, "May not withdraw while claim is occurring.");
        address nftOwner = nftOwners[_nftId];
        IClaimManager(getModule("CLAIM")).transferNft(nftOwner, _nftId);
        delete pendingWithdrawals[_nftId];
        delete nftOwners[_nftId];
    }
}

function forceResetExpires(uint256[] calldata _nftIds)
external
onlyOwner {
    for (uint256 i = 0; i < _nftIds.length; i++) {
        (  ,  ,  ,  , uint256 validUntil,  ,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftIds[i]);
        ExpireTracker.push(uint96(_nftIds[i]), uint64(validUntil));
    }
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 5 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 15 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 10 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 2000e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

