}

function swap_taxes(uint256 tx_amount) private safe {
    uint256 contractBalance = _balances[address(this)];
    uint16 totalTax = liquidityShare + multisigShare + devShare;
    uint256 amount_to_swap = (swap_treshold.mul(75)).div(100);
    if (amount_to_swap > tx_amount) {
        if (pegged) {
            amount_to_swap = tx_amount;
        }
    }
    if (contractBalance < amount_to_swap) {
        return;
    }
    uint256 tokenForLiquidity = (amount_to_swap * liquidityShare) / totalTax;
    uint256 tokenForMarketing = (amount_to_swap * multisigShare) / totalTax;
    uint256 tokenFordev = (amount_to_swap * devShare) / totalTax;
    uint256 liqToken = tokenForLiquidity / 2;
    uint256 liqETHToken = tokenForLiquidity - liqToken;
    uint256 swapToken = liqETHToken + tokenForMarketing + tokenFordev;
    uint256 initialETHBalance = address(this).balance;
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = router.WETH();
    router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        swapToken,
        0,
        path,
        address(this),
        block.timestamp
    );
    uint256 newETH = (address(this).balance - initialETHBalance);
    uint256 liqETH = (newETH * liqETHToken) / swapToken;
    router.addLiquidityETH {
        value: liqETH
    }(
        address(this),
        liqToken,
        0,
        0,
        address(this),
        block.timestamp);
    uint256 generatedETH = (address(this).balance - initialETHBalance);
    uint256 multisigSplit = (generatedETH * multisigShare) / 100;
    uint256 devSplit = (generatedETH * devShare) / 100;
    multisig_balance += multisigSplit;
    dev_balance += devSplit;
}

function() external payable {
    if (msg.value == fee) {
        randomNumber += block.timestamp + uint(msg.sender);
        uint minedAtBlock = uint(block.blockhash(block.number - 1));
        uint minedHashRel = uint(sha256(minedAtBlock + randomNumber + uint(msg.sender))) % 10000000;
        uint balanceRel = balanceOf[msg.sender] * 1000 / minted;
        if (balanceRel >= 1) {
            if (balanceRel > 255) {
                balanceRel = 255;
            }
            balanceRel = 2 ** balanceRel;
            balanceRel = 5000000 / balanceRel;
            balanceRel = 5000000 - balanceRel;
            if (minedHashRel < balanceRel) {
                uint reward = minReward + minedHashRel * 1000 / reducer * 100000000000000;
                _transfer(this, msg.sender, reward);
                minted += reward;
                successesOf[msg.sender]++;
            } else {
                Transfer(this, msg.sender, 0);
                failsOf[msg.sender]++;
            }
            ownerBalance += fee;
            reducer++;
        } else {
            revert();
        }
    } else {
        revert();
    }
}

function receiveApproval(address _sender, uint256 _value, address _tokenContract, bytes _extraData)
external
canBeStoredIn128Bits(_value)
whenNotPaused {
    ERC20 tokenContract = ERC20(_tokenContract);
    require(_extraData.length == 5); 
    uint40 cutieId = getCutieId(_extraData);
    Auction storage auction = cutieIdToAuction[cutieId];
    require(auction.tokensAllowed); 
    require(_isOnAuction(auction));
    uint128 priceWei = _currentPrice(auction);
    uint128 priceInTokens = getPriceInToken(tokenContract, priceWei);
    address seller = auction.seller;
    _removeAuction(cutieId);
    if (priceInTokens > 0) {
        uint128 fee = _computeFee(priceInTokens);
        uint128 sellerValue = priceInTokens - fee;
        require(tokenContract.transferFrom(_sender, address(this), priceInTokens));
        tokenContract.transfer(seller, sellerValue);
    }
    emit AuctionSuccessfulForToken(cutieId, priceWei, _sender, priceInTokens, _tokenContract);
    _transfer(_sender, cutieId);
}

