    require(userBalance > 0 && _amount > 0, "You can't unstake less than zero");
    require(_amount <= userBalance, "You can't withdraw more than your balance");
    stakes[msg.sender] = Stake(now, stakes[msg.sender].yeldBalance.sub(_amount));
    totalStaked = totalStaked.sub(_amount);
    yeld.transfer(msg.sender, _amount);
}

function finish(uint256 _count) public onlyOwner finishOrHardcap overSoftcap returns(bool) {
    require(_count > 0);
    require(distributionDate > 0 && distributionDate <= now);
    if (finishCurrentLimit == 0) {
        finishCurrentLimit = bountyLimit.add(teamLimit.add(advisersLimit));
    }
    uint256 totalCnt = adviser.length.add(bounty.length);
    if (finishLastCount < adviser.length) {
        for (uint256 i = finishLastCount; i <= adviser.length - 1; i++) {
            finishCurrentLimit = finishCurrentLimit.sub(adviserAmount[adviser[i]]);
            bgxTokenInterface.distribute(adviser[i], adviserAmount[adviser[i]]);
            finishLastCount++;
            _count--;
            if (_count <= 0) {
                return true;
            }
        }
    }
    if (finishLastCount < totalCnt) {
        for (i = finishLastCount.sub(adviser.length); i <= bounty.length - 1; i++) {
            finishCurrentLimit = finishCurrentLimit.sub(bountyAmount[bounty[i]]);
            bgxTokenInterface.distribute(bounty[i], bountyAmount[bounty[i]]);
            finishLastCount++;
            _count--;
            if (_count <= 0) {
                return true;
            }
        }
    }
    if (finishLastCount >= totalCnt && finishLastCount < totalCnt.add(team.length)) {
        for (i = finishLastCount.sub(totalCnt); i <= team.length - 1; i++) {
            finishCurrentLimit = finishCurrentLimit.sub(teamAmount[team[i]]);
            bgxTokenInterface.distribute(team[i], teamAmount[team[i]]);
            finishLastCount++;
            _count--;
            if (_count <= 0) {
                return true;
            }
        }
    }
    reserved = reserved.add(finishCurrentLimit);
    return true;
}

function getState() public returns(CrowdsaleStates) {
    if (state == CrowdsaleStates.Pause || paused) return CrowdsaleStates.Pause;
    if (state == CrowdsaleStates.Finish) return CrowdsaleStates.Finish;
    if (totalBGX >= hardcap) return CrowdsaleStates.OverHardcap;
    if (now >= presaleDateStart && now <= presaleDateFinish) {
        if (totalBGX >= presaleHardcap) return CrowdsaleStates.Pause;
        return CrowdsaleStates.Presale;
    }
    if (now >= saleDateStart && now <= saleDateFinish) {
        if (totalBGX >= hardcap) {
            _startCounter();
            return CrowdsaleStates.OverHardcap;
        }
        return CrowdsaleStates.Sale;
    }
    if (now > saleDateFinish) {
        _startCounter();
        return CrowdsaleStates.Finish;
    }
    return CrowdsaleStates.Pause;
}

function _startCounter() internal {
    if (distributionDate <= 0) {
        distributionDate = now + 2 days;
    }
}

function sendNow(uint256 _count) public onlyOwner overSoftcap returns(bool) {
    require(sendNowLastCount.add(_count) <= investors.length);
    uint256 to = sendNowLastCount.add(_count);
    for (uint256 i = sendNowLastCount; i <= to - 1; i++)
        if (!inBlackList[investors[i]]) {
            investorBalance[investors[i]] = 0;
            bgxTokenInterface.distribute(investors[i], investorBalance[investors[i]]);
        }
    sendNowLastCount = sendNowLastCount.add(_count);
}

function _harvest(uint256 _bankPoolId, uint256 _poolId) internal {
    _claim(_poolId);
    IERC20 targetToken = poolMap[_poolId].targetToken;
    uint256 targetTokenBal = targetToken.balanceOf(address(this));
    log_golffBal = targetTokenBal;
    if (targetTokenBal < poolMap[_poolId].minHarvestForTakeProfit) return;
    _swapTokens(address(targetToken), address(lpToken), targetTokenBal);
    uint256 wethBal = lpToken.balanceOf(address(this));
    log_wethBal = wethBal;
    if (wethBal > 0) {
        address profitSharer = valueVaultMaster.profitSharer();
        address performanceReward = valueVaultMaster.performanceReward();
        address bank = valueVaultMaster.bank();
        if (valueVaultMaster.govVaultProfitShareFee() > 0 && profitSharer != address(0)) {
            address yfv = valueVaultMaster.yfv();
            uint256 _govVaultProfitShareFee = wethBal.mul(valueVaultMaster.govVaultProfitShareFee()).div(FEE_DENOMINATOR);
            _swapTokens(address(lpToken), yfv, _govVaultProfitShareFee);
            log_yfvGovVault = IERC20(yfv).balanceOf(address(this));
            IERC20(yfv).transfer(profitSharer, IERC20(yfv).balanceOf(address(this)));
            IProfitSharer(profitSharer).shareProfit();
        }
        if (valueVaultMaster.gasFee() > 0 && performanceReward != address(0)) {
            uint256 _gasFee = wethBal.mul(valueVaultMaster.gasFee()).div(FEE_DENOMINATOR);
            lpToken.transfer(performanceReward, _gasFee);
        }
        uint256 balanceLeft = lpToken.balanceOf(address(this));
        if (lpToken.allowance(address(this), bank) < balanceLeft) {
            lpToken.approve(bank, 0);
            lpToken.approve(bank, balanceLeft);
        }
        IValueVaultBank(bank).make_profit(_bankPoolId, balanceLeft);
    }
}

function _deposit(uint256 _poolId, uint256 _amount) internal {
    if (aggressiveMode) {
        _amount = lpToken.balanceOf(address(this));
    }
    if (poolMap[_poolId].poolType == 0) {
        IStakingRewards(poolMap[_poolId].targetPool).stake(_amount);
    } else {
        ISushiPool(poolMap[_poolId].targetPool).deposit(poolMap[_poolId].targetPoolId, _amount);
    }
    poolMap[_poolId].balance = poolMap[_poolId].balance.add(_amount);
    totalBalance = totalBalance.add(_amount);
}

function _withdraw(uint256 _poolId, uint256 _amount) internal {
    if (poolMap[_poolId].poolType == 0) {
        IStakingRewards(poolMap[_poolId].targetPool).withdraw(_amount);
    } else {
        ISushiPool(poolMap[_poolId].targetPool).withdraw(poolMap[_poolId].targetPoolId, _amount);
    }
    if (poolMap[_poolId].balance < _amount) {
        _amount = poolMap[_poolId].balance;
    }
    poolMap[_poolId].balance = poolMap[_poolId].balance - _amount;
    if (totalBalance >= _amount) totalBalance = totalBalance - _amount;
}

function withdrawalComplete() returns(bool) {
    withdrawalRequest r = withdrawalRequests[msg.sender];
    if (r.sinceTime == 0) throw;
    if ((r.sinceTime + timeWait) > now) {
        WithdrawalPremature(msg.sender, r.sinceTime + timeWait - now);
        return false;
    }
    uint256 amount = withdrawalRequests[msg.sender].amount;
    uint256 reward = calculateReward(r.amount);
    withdrawalRequests[msg.sender].sinceTime = 0; 
    withdrawalRequests[msg.sender].amount = 0; 
    if (reward > 0) {
        if (feePot - reward > feePot) { 
            feePot = 0;
        } else {
            feePot -= reward;
        }
    }
    doWithdrawal(reward); 
    WithdrawalDone(msg.sender, amount, reward);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value)
returns(bool success) {
    if (withdrawalRequests[_from].sinceTime > 0) throw; 
    if (withdrawalRequests[_to].sinceTime > 0) throw; 
    if (balanceOf[_from] < _value) throw; 
    if (balanceOf[_to] + _value < balanceOf[_to]) throw; 
    if (_value > allowance[_from][msg.sender]) throw; 
    balanceOf[_from] -= _value; 
    balanceOf[_to] += _value; 
    allowance[_from][msg.sender] -= _value;
    Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) notPendingWithdrawal {
    if (balanceOf[msg.sender] < _value) throw; 
    if (balanceOf[_to] + _value < balanceOf[_to]) throw; 
    if (withdrawalRequests[_to].sinceTime > 0) throw; 
    balanceOf[msg.sender] -= _value; 
    balanceOf[_to] += _value; 
    Transfer(msg.sender, _to, _value); 
}

function quickWithdraw() payable notPendingWithdrawal returns(bool) {
    uint256 amount = balanceOf[msg.sender];
    if (amount == 0) throw;
    uint256 feeRequired = calculateFee(amount);
    if (msg.value != feeRequired) {
        IncorrectFee(msg.sender, feeRequired); 
        throw;
    }
    feePot += msg.value; 
    doWithdrawal(0); 
    WithdrawalDone(msg.sender, amount, 0);
    return true;
}

