function availableForWithdrawal(address _address) public view returns(uint256) {
    if (now < cliffTime) {
        return 0;
    } else if (now < timelockEndTime) {
        uint256 cliffTokens = (cliffReleasePercentage.mul(allocatedTokens[_address])).div(100);
        uint256 slopeTokens = (allocatedTokens[_address].mul(slopeReleasePercentage)).div(100);
        uint256 timeAtSlope = now.sub(cliffTime);
        uint256 slopeTokensByNow = (slopeTokens.mul(timeAtSlope)).div(slopeDuration);
        return (cliffTokens.add(slopeTokensByNow)).sub(withdrawnTokens[_address]);
    } else {
        return allocatedTokens[_address].sub(withdrawnTokens[_address]);
    }
}

function Timelock(ERC20Basic _token, uint256 _startTime, uint256 _cliffDuration, uint256 _cliffReleasePercent, uint256 _slopeDuration, uint256 _slopeReleasePercentage) public {
    require(_cliffReleasePercent.add(_slopeReleasePercentage) <= 100);
    require(_startTime > now);
    require(_token != address(0));
    allocationFinished = false;
    token = _token;
    startTime = _startTime;
    cliffDuration = _cliffDuration;
    cliffReleasePercentage = _cliffReleasePercent;
    slopeDuration = _slopeDuration;
    slopeReleasePercentage = _slopeReleasePercentage;
    cliffTime = startTime.add(cliffDuration);
    timelockEndTime = cliffTime.add(slopeDuration);
}

function withdraw() external returns(bool) {
    require(!withdrawalPaused[msg.sender]);
    uint256 availableTokens = availableForWithdrawal(msg.sender);
    require(availableTokens > 0);
    withdrawnTokens[msg.sender] = withdrawnTokens[msg.sender].add(availableTokens);
    token.safeTransfer(msg.sender, availableTokens);
    return true;
}

function finishGame() public payable returns(uint256[18] memory, address payable[18] memory) {
    jackpotWinners[0] = 0x0000000000000000000000000000000000000000;
    jackpotWinners[1] = 0x0000000000000000000000000000000000000000;
    jackpotWinners[2] = 0x0000000000000000000000000000000000000000;
    jackpotAmts[0] = 0;
    jackpotAmts[1] = 0;
    jackpotAmts[2] = 0;
    for (uint zx = 0; zx < boxes.length; zx++) {
        boxes[zx] = msg.sender;
    }
    bool allBoxesPurchased = true;
    for (uint i = 0; i < boxes.length; i++) {
        if (boxes[i] == address(0)) {
            allBoxesPurchased = false;
        }
    }
    uint256 jackpotWinHappenedMini = 0;
    uint256 jackpotWinHappenedMega = 0;
    uint256 jackpotWinHappenedUltra = 0;
    if (allBoxesPurchased == false) {
    }
    if (random(10, 1337) == 1) {
        jackpotWinHappenedMini = jackpotMini;
        jackpotMini = 0;
    }
    if (random(50, 13378) == 1) {
        jackpotWinHappenedMega = jackpotMega;
        jackpotMega = 0;
    }
    if (random(200, 13379) == 1) {
        jackpotWinHappenedUltra = jackpotUltra;
        jackpotUltra = 0;
    }
    uint256 bigChunks = 200000000000000000;
    uint256 mediumChunks = 50000000000000000;
    uint256 tinyChunks = 50000000000000000;
    uint256 tempRandom;
    uint256 counterbruh;
    while (bigChunks > 0) {
        tempRandom = random(15, counterbruh);
        boxPayoutAmounts[tempRandom - 1] = boxPayoutAmounts[tempRandom - 1] + 100000000000000000;
        bigChunks = bigChunks - 100000000000000000;
        counterbruh++;
    }
    while (mediumChunks > 0) {
        tempRandom = random(15, counterbruh);
        boxPayoutAmounts[tempRandom - 1] = boxPayoutAmounts[tempRandom - 1] + 50000000000000000;
        mediumChunks = mediumChunks - 50000000000000000;
        counterbruh++;
    }
    while (tinyChunks > 0) {
        tempRandom = random(15, counterbruh);
        boxPayoutAmounts[tempRandom - 1] = boxPayoutAmounts[tempRandom - 1] + 25000000000000000;
        tinyChunks = tinyChunks - 25000000000000000;
        counterbruh++;
    }
    tempRandom = random(15, counterbruh);
    boxPayoutAmounts[tempRandom - 1] = boxPayoutAmounts[tempRandom - 1] + 250000000000000000;
    if (jackpotWinHappenedMini > 0) {
        uint256 anotherTempRandom = random(15, counterbruh);
        jackpotWinners[0] = boxes[anotherTempRandom];
        jackpotAmts[0] = jackpotWinHappenedMini;
        jackpotMini = 0; 
        jackpotWinners[0].transfer(jackpotWinHappenedMini);
        counterbruh++;
    }
    if (jackpotWinHappenedMega > 0) {
        uint256 anotherTempRandom = random(15, counterbruh);
        jackpotWinners[1] = boxes[anotherTempRandom];
        jackpotAmts[1] = jackpotWinHappenedMega;
        jackpotMega = 0; 
        jackpotWinners[1].transfer(jackpotWinHappenedMega);
        counterbruh++;
    }
    if (jackpotWinHappenedUltra > 0) {
        uint256 anotherTempRandom = random(15, counterbruh);
        jackpotWinners[2] = boxes[anotherTempRandom];
        jackpotAmts[2] = jackpotWinHappenedUltra;
        jackpotUltra = 0; 
        jackpotWinners[2].transfer(jackpotWinHappenedUltra);
        counterbruh++;
    }
    for (uint uu = 0; uu < 15; uu++) {
        if (boxPayoutAmounts[uu] > 0) {
            boxes[uu].transfer(boxPayoutAmounts[uu]);
        }
    }
    jackpotMini = jackpotMini + 20000000000000000;
    jackpotMega = jackpotMega + 25000000000000000;
    jackpotUltra = jackpotUltra + 30000000000000000;
    uint256 safezone = jackpotMini + jackpotMega + jackpotUltra + 100000000000000000;
    uint256 amountToPayDevs = address(this).balance - safezone;
    if (amountToPayDevs > 100000000000000000) {
        owner.transfer(amountToPayDevs);
    }
    boxPayoutAmounts[15] = jackpotAmts[0];
    boxPayoutAmounts[16] = jackpotAmts[1];
    boxPayoutAmounts[17] = jackpotAmts[2];
    boxes[15] = jackpotWinners[0];
    boxes[16] = jackpotWinners[1];
    boxes[17] = jackpotWinners[2];
    gameNumber = gameNumber + 1;
    gameBlockFinishedOn = block.number;
    for (uint ii = 0; ii < 18; ii++) {
        lastResultAddresses[ii] = boxes[ii];
        lastResultAmounts[ii] = boxPayoutAmounts[ii];
        boxPayoutAmounts[ii] = 0;
        boxes[ii] = 0x0000000000000000000000000000000000000000;
    }
    emit gameResults(lastResultAddresses, lastResultAmounts, gameNumber, gameBlockFinishedOn);
}

function buy(uint256 _auctionId, address _referral) payable public {
    NFTToken CNDERC721 = NFTToken(ERC721Contract);
    require(auctions[_auctionId].endTime > now);
    require(CNDERC721.ownerOf(auctions[_auctionId].monsterId) != address(0));
    require(ceil(msg.value) >= ceil(auctions[_auctionId].price + increaseRate));
    require(CNDERC721.ownerOf(auctions[_auctionId].monsterId) != msg.sender);
    require(!isContract(msg.sender));
    require(msg.sender != address(0));
    address oldOwner = CNDERC721.ownerOf(auctions[_auctionId].monsterId);
    address newOwner = msg.sender;
    uint256 oldPrice = auctions[_auctionId].price;
    uint256 price = ceil(msg.value);
    setGenes(price, auctions[_auctionId].monsterId);
    CNDERC721.transferAuction(oldOwner, newOwner, auctions[_auctionId].monsterId);
    auctions[_auctionId].price = ceil(price);
    auctions[_auctionId].bidder = msg.sender;
    DTT DTTtoken = DTT(dragonTreasureToken);
    if (masterToReferral[msg.sender] != address(0) && masterToReferral[msg.sender] != msg.sender) {
        DTTtoken.approve(masterToReferral[msg.sender], DTTtoken.allowance(this, masterToReferral[msg.sender]) + (price - oldPrice) / 1000000000 * 5);
    } else if (_referral != address(0) && _referral != msg.sender) {
        masterToReferral[msg.sender] = _referral;
        DTTtoken.approve(_referral, DTTtoken.allowance(this, _referral) + (price - oldPrice) / 1000000000 * 5);
    }
    DTTtoken.approve(msg.sender, DTTtoken.allowance(this, msg.sender) + (price - oldPrice) / 1000000000 * 5);
    if (oldPrice > 0)
        oldOwner.transfer(oldPrice);
    Bought(auctions[_auctionId].monsterId, newOwner, price);
    Sold(auctions[_auctionId].monsterId, oldOwner, price);
}

function burnAuction() onlyOwner external {
    uint256 counter = 0;
    for (uint256 i = 0; i < totalAuction; i++) {
        if (auctions[i].endTime < now - 86400 * 3) {
            delete auctions[i];
            counter++;
        }
    }
    totalAuction -= counter;
}

