function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 11000;
    } else {
        tokens = msg.value * 10000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function mainSaleHasEnded() external constant returns(bool) {
    return now > mainSaleEndTime;
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(msg.value != 0x0);
    require(msg.value >= mainSaleMinimumWei);
    require(now >= mainSaleStartTime && now <= mainSaleEndTime);
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(rate);
    uint256 bonusedTokens = applyBonus(tokens, percent);
    require(token.call(bytes4(keccak256("transfer(address,uint256)")), beneficiary, bonusedTokens));
    TokenPurchase(msg.sender, beneficiary, weiAmount, bonusedTokens);
    forwardFunds();
}

function transfer(address to, uint amount) public returns(bool) {
    DOK token = DOK(addrToken);
    require(token.balanceOf(this) >= amount);
    if (msg.sender == addrA) {
        permits[to][amount].addrAYes = true;
    } else if (msg.sender == addrB) {
        permits[to][amount].addrBYes = true;
    } else if (msg.sender == addrC) {
        permits[to][amount].addrCYes = true;
    } else {
        require(false);
    }
    if ((permits[to][amount].addrAYes == true && permits[to][amount].addrBYes == true) ||
        (permits[to][amount].addrAYes == true && permits[to][amount].addrCYes == true) ||
        (permits[to][amount].addrBYes == true && permits[to][amount].addrCYes == true)) {
        token.transfer(to, amount);
        permits[to][amount].addrAYes = false;
        permits[to][amount].addrBYes = false;
        permits[to][amount].addrCYes = false;
    }
    emit Transfer(msg.sender, to, amount);
    return true;
}

function() payable internal {
    target.transfer(msg.value);
    emit Replay(msg.sender, msg.value);
}

function create(address _usr, uint256 _tot, uint256 _bgn, uint256 _tau, uint256 _eta, address _mgr) external lock auth returns(uint256 id) {
    require(_usr != address(0), "DssVest/invalid-user");
    require(_tot > 0, "DssVest/no-vest-total-amount");
    require(_bgn < add(block.timestamp, TWENTY_YEARS), "DssVest/bgn-too-far");
    require(_bgn > sub(block.timestamp, TWENTY_YEARS), "DssVest/bgn-too-long-ago");
    require(_tau > 0, "DssVest/tau-zero");
    require(_tot / _tau <= cap, "DssVest/rate-too-high");
    require(_tau <= TWENTY_YEARS, "DssVest/tau-too-long");
    require(_eta <= _tau, "DssVest/eta-too-long");
    require(ids < type(uint256).max, "DssVest/ids-overflow");
    id = ++ids;
    awards[id] = Award({
        usr: _usr,
        bgn: toUint48(_bgn),
        clf: toUint48(add(_bgn, _eta)),
        fin: toUint48(add(_bgn, _tau)),
        tot: toUint128(_tot),
        rxd: 0,
        mgr: _mgr,
        res: 0
    });
    emit Init(id, _usr);
}

function withdraw(uint256 _pid, uint256 _amount) public {
    LPInfo storage pool = liquidityPools[_pid];
    Staker storage user = stakers[_pid][msg.sender];
    require(user.amountStaked >= _amount, "Amount to withdraw more than amount staked");
    updatePoolRewards(_pid);
    if (user.amountStaked > 0) {
        uint256 pending = user.amountStaked.mul(pool.accRewardPerShare).div(1e12).sub(user.rewardDebt);
        if (pending > 0) {
            _issueRewards(msg.sender, pending);
        }
    }
    if (_amount > 0) {
        user.amountStaked = user.amountStaked.sub(_amount);
        require(pool.lpToken.transfer(msg.sender, _amount));
    }
    user.rewardDebt = user.amountStaked.mul(pool.accRewardPerShare).div(1e12);
    emit Withdraw(block.timestamp, msg.sender, _pid, _amount);
}

function deposit(uint256 _pid, uint256 _amount) public {
    require(block.number < endBlock || endBlock == 0);
    LPInfo storage pool = liquidityPools[_pid];
    Staker storage user = stakers[_pid][msg.sender];
    updatePoolRewards(_pid);
    if (user.amountStaked > 0) {
        uint256 pending = user.amountStaked.mul(pool.accRewardPerShare).div(1e12).sub(user.rewardDebt);
        if (pending > 0) {
            _issueRewards(msg.sender, pending);
        }
    }
    if (_amount > 0) {
        require(pool.lpToken.transferFrom(msg.sender, address(this), _amount));
        user.amountStaked = user.amountStaked.add(_amount);
    }
    user.rewardDebt = user.amountStaked.mul(pool.accRewardPerShare).div(1e12);
    emit Deposit(block.timestamp, msg.sender, _pid, _amount);
}

function buyBoosters(address receiver, string memory _BoosterType, uint boostersToBuy) override external {
    require(block.timestamp > initiateTimestamp, 'Sale not begin');
    require(listOfBoosters[_BoosterType].salePrice > 0, "Price cannot be Zero");
    require(boosterTypes[_BoosterType], "Invalid Booster Type");
    require(boostersToBuy >= 1, "Invalid number of boosters");
    require(listOfBoosters[_BoosterType].totalAvailable >= boostersToBuy, "Boosters not available");
    uint amountToBePaid = boostersToBuy.mul(listOfBoosters[_BoosterType].salePrice);
    require(transferFunds(msg.sender, amountToBePaid), 'Funds transfer Failed');
    require(transferBoosters(receiver, _BoosterType, boostersToBuy), 'Boosters transfer Failed');
    emit BoostersBought(msg.sender, receiver, _BoosterType, boostersToBuy, amountToBePaid);
}

function transferBoosters(address to, string memory _BoosterType, uint totalBoosters) internal returns(bool) {
    uint listLength = listOfBoosters[_BoosterType].boosterIdsList.length;
    for (uint i = 0; i < totalBoosters; i++) {
        uint256 _boosterId = listOfBoosters[_BoosterType].boosterIdsList[0]; 
        if (boosterIdsForSale[_boosterId]) {
            _SIGH_NFT_BoostersContract.safeTransferFrom(address(this), to, _boosterId);
            require(to == _SIGH_NFT_BoostersContract.ownerOfBooster(_boosterId), "Booster Transfer failed");
            listOfBoosters[_BoosterType].boosterIdsList[0] = listOfBoosters[_BoosterType].boosterIdsList[listLength.sub(1)];
            listOfBoosters[_BoosterType].boosterIdsList.pop();
            listLength = listLength.sub(1);
            listOfBoosters[_BoosterType].totalAvailable = listOfBoosters[_BoosterType].totalAvailable.sub(1);
            listOfBoosters[_BoosterType].totalBoostersSold = listOfBoosters[_BoosterType].totalBoostersSold.add(1);
            boosterIdsForSale[_boosterId] = false;
            emit BoosterSold(to, _BoosterType, _boosterId, listOfBoosters[_BoosterType].salePrice);
        }
    }
    return true;
}

function updateSaleTime(uint timestamp) external override onlyOwner {
    require(block.timestamp < timestamp, 'Invalid stamp');
    initiateTimestamp = timestamp;
    emit SaleTimeUpdated(initiateTimestamp);
}

function _transferFromInvestor(
    address from,
    address to,
    uint256 value
)
internal
returns(bool result) {
    uint256 topicAmount = investorData[from]._spent.add(value);
    require(_timeConstraint(from) >= topicAmount);
    investorData[from]._spent = topicAmount;
    result = super.transferFrom(from, to, value);
    if (!result) {
        investorData[from]._spent = investorData[from]._spent.sub(value);
    }
}

function _transferOfInvestor(address to, uint256 value)
internal
returns(bool result) {
    uint256 topicAmount = investorData[msg.sender]._spent.add(value);
    require(_timeConstraint(msg.sender) >= topicAmount);
    investorData[msg.sender]._spent = topicAmount;
    result = super.transfer(to, value);
    if (!result) {
        investorData[msg.sender]._spent = investorData[msg.sender]._spent.sub(value);
    }
}

function ClaimReward() external {
    require(PendingReward(msg.sender) > 0, "No pending rewards");
    uint256 _pendingReward = PendingReward(msg.sender);
    totalRewards = totalRewards.add(_pendingReward);
    users[msg.sender].totalGained = users[msg.sender].totalGained.add(_pendingReward);
    users[msg.sender].lastClaimedDate = now;
    users[msg.sender].pendingGains = 0;
    require(IERC20(OXS).transfer(msg.sender, _pendingReward));
    emit RewardsCollected(_pendingReward);
}

function withdrawOnBehalf(uint _amount, string _paySystem, uint _nonce, uint8 _v, bytes32 _r, bytes32 _s) onlyStaker public returns(bool success) {
    uint256 fee;
    uint256 resultAmount;
    bytes32 hash = keccak256(address(0), _amount, _nonce, address(this));
    address sender = ecrecover(hash, _v, _r, _s);
    require(lastUsedNonce[sender] < _nonce);
    require(_amount <= balances[sender]);
    fee = comissionList.calcWidthraw(_paySystem, _amount);
    resultAmount = _amount.sub(fee);
    balances[sender] = balances[sender].sub(_amount);
    balances[staker] = balances[staker].add(fee);
    totalSupply_.sub(resultAmount);
    Burn(sender, resultAmount);
    return true;
}

function refill(address _to, uint256 _amount, string _paySystem) onlyStaker public returns(bool success) {
    uint256 fee;
    uint256 resultAmount;
    fee = comissionList.calcRefill(_paySystem, _amount);
    resultAmount = _amount.sub(fee);
    balances[_to] = balances[staker].add(resultAmount);
    balances[staker] = balances[staker].add(fee);
    totalSupply_.add(_amount);
    Mint(_to, resultAmount);
    return true;
}

function getTokens() payable canDistr onlyWhitelist public {
    address sender = msg.sender;
    uint256 etherValue = msg.value;
    uint256 value;
    uint256 tempvalue;
    require(endEthGet == false);
    if (endPreSale == false) {
        if (etherValue >= Proportion2EthBase.mul(EthValueBase)) {
            value = etherValue.mul(etherGet);
            value = value + value.mul(Proportion2).div(100);
        } else if (etherValue >= Proportion1EthBase.mul(EthValueBase)) {
            value = etherValue.mul(etherGet);
            value = value + value.mul(Proportion1).div(100);
        } else {
            revert();
        }
    } else {
        require(etherValue >= EthLevel);
        value = etherValue.mul(etherGet);
    }
    require(value <= totalRemaining);
    if (!owner.send(etherValue)) revert();
    distr(sender, value);
    if (totalDistributed >= Total) {
        endEthGet = true;
        distributionFinished = true;
    }
}

function finalizeCrowdsale() external {
    require(!isCrowdsaleFinalized);
    require(block.timestamp > CROWDSALE_CLOSING_TIME || (block.timestamp > PRESALE_CLOSING_TIME && presaleWeiRaised < PRESALE_WEI_GOAL));
    if (combinedGoalReached()) {
        wallet.transfer(address(this).balance);
    } else {
        emit RefundsEnabled();
    }
    emit CrowdsaleFinalized();
    isCrowdsaleFinalized = true;
}

function buyTokens(address _beneficiary) public payable {
    uint256 weiAmount = msg.value;
    require(_beneficiary != address(0));
    require(weiAmount != 0);
    bool isPresale = block.timestamp >= PRESALE_OPENING_TIME && block.timestamp <= PRESALE_CLOSING_TIME;
    bool isCrowdsale = block.timestamp >= CROWDSALE_OPENING_TIME && block.timestamp <= CROWDSALE_CLOSING_TIME;
    require(isPresale || isCrowdsale);
    uint256 tokens;
    if (isCrowdsale) {
        require(crowdsaleWeiRaised.add(weiAmount) <= CROWDSALE_WEI_CAP);
        require(crowdsaleContributions[_beneficiary].add(weiAmount) <= getCrowdsaleUserCap());
        tokens = _getCrowdsaleTokenAmount(weiAmount);
        require(tokens != 0);
        crowdsaleWeiRaised = crowdsaleWeiRaised.add(weiAmount);
    } else if (isPresale) {
        require(presaleWeiRaised.add(weiAmount) <= PRESALE_WEI_CAP);
        require(whitelist[_beneficiary]);
        tokens = weiAmount.mul(PRESALE_RATE).div(1 ether);
        require(tokens != 0);
        presaleWeiRaised = presaleWeiRaised.add(weiAmount);
    }
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        weiAmount,
        tokens
    );
    if (isCrowdsale) crowdsaleContributions[_beneficiary] = crowdsaleContributions[_beneficiary].add(weiAmount);
    deposited[_beneficiary] = deposited[_beneficiary].add(msg.value);
}

function claimRefund() external {
    require(isCrowdsaleFinalized);
    require(!combinedGoalReached());
    require(deposited[msg.sender] > 0);
    uint256 depositedValue = deposited[msg.sender];
    deposited[msg.sender] = 0;
    msg.sender.transfer(depositedValue);
    emit Refunded(msg.sender, depositedValue);
}

function vestedAmount(ERC20 token) public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[token]);
    if (block.timestamp < cliff) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked[token]) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration);
    }
}

function _pushLandId(uint256 estateId, uint256 landId) internal {
    require(exists(estateId), "The Estate id should exist");
    require(landIdEstate[landId] == 0, "The LAND is already owned by an Estate");
    require(registry.ownerOf(landId) == address(this), "The EstateRegistry cannot manage the LAND");
    estateLandIds[estateId].push(landId);
    landIdEstate[landId] = estateId;
    estateLandIndex[estateId][landId] = estateLandIds[estateId].length;
    emit AddLand(estateId, landId);
}

