    (art_price, art_price_blockHeight) = oracle.getHistoricalPrice(price_index);
    bids[bids_count] = Bid(_bid_hash, art_price, price_index, true, false, false, false);
    index = bids_count;
    emit BidAdded(bids_count++);
}

function refundIgnoredBids(uint _count) public onlyOwner {
    require(status == state.success || status == state.failure);
    uint count = _count;
    if (bids_ignored_count < bids_ignored_refunded.add(count)) {
        count = bids_ignored_count.sub(bids_ignored_refunded);
    }
    require(count > 0);
    uint cursor = bids_ignored_refunded;
    bids_ignored_refunded = bids_ignored_refunded.add(count);
    BidData storage bid;
    while (count > 0) {
        bid = bids_ignored[cursor];
        if (bid.closed) {
            continue;
        }
        bid.closed = true;
        art_token_contract.transfer(bid.investor_address, bid.transfer_token);
        emit Refunded(bid.origin_index, bid.transfer_token);
        cursor++;
        count--;
    }
}

function refundLosersBids(uint _count) public onlyOwner {
    require(status == state.success || status == state.failure);
    uint count = _count;
    if (bids_sorted_count.sub(winner_bids) < bids_sorted_refunded.add(count)) {
        count = bids_sorted_count.sub(winner_bids).sub(bids_sorted_refunded);
    }
    require(count > 0);
    uint cursor = bids_sorted_refunded.add(winner_bids);
    bids_sorted_refunded = bids_sorted_refunded.add(count);
    BidData memory bid;
    while (count > 0) {
        bid = bids_sorted[cursor];
        if (bid.closed) {
            continue;
        }
        bids_sorted[cursor].closed = true;
        art_token_contract.transfer(bid.investor_address, bid.transfer_token);
        emit Refunded(bid.origin_index, bid.transfer_token);
        cursor++;
        count--;
    }
}

function buy() public payable {
    require(!closeBuy); 
    uint amount = msg.value / buyPrice; 
    uint market_value = amount * buyPrice; 
    uint comision = market_value * 4 / 1000; 
    uint profit_in_transaction = market_value - (amount * sellPrice) - comision; 
    require(this.balance >= comision); 
    comisionGetter.transfer(comision); 
    _transfer(this, msg.sender, amount); 
    _updateSolvency((this.balance - profit_in_transaction)); 
    _updateProfit(profit_in_transaction, true); 
    owner.transfer(profit_in_transaction); 
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(_value <= allowance[_from][msg.sender]); 
    uint market_value = _value * sellPrice;
    uint comision = market_value * 4 / 1000;
    require(this.balance >= comision);
    comisionGetter.transfer(comision); 
    allowance[_from][msg.sender] -= _value; 
    _transfer(_from, _to, _value); 
    return true;
}

function sell(uint256 amount) public {
    require(!closeSell); 
    uint market_value = amount * sellPrice; 
    uint comision = market_value * 4 / 1000; 
    uint amount_weis = market_value + comision; 
    require(this.balance >= amount_weis); 
    comisionGetter.transfer(comision); 
    _transfer(msg.sender, this, amount); 
    _updateSolvency((this.balance - amount_weis)); 
    msg.sender.transfer(market_value); 
}

function transfer(address _to, uint256 _value) public {
    uint market_value = _value * sellPrice;
    uint comision = market_value * 4 / 1000;
    require(this.balance >= comision);
    comisionGetter.transfer(comision); 
    _transfer(msg.sender, _to, _value);
}

function tokenFallback(address _from, uint256 _value, bytes _data)
external
onlyTokenContract
returns(bool) {
    require(!_isContract(_from));
    require(_value <= 100 ether); 
    require(_value >= 1 ether); 
    uint256 amountCredited = (_value * multiplier) / 100;
    participants.push(Participant(_from, amountCredited));
    backlog += amountCredited;
    creditRemaining[_from] += amountCredited;
    emit Deposit(_value, _from);
    throughput += _value;
    uint balance = _value;
    reinvest(); 
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            balance -= payoutToSend;
            backlog -= payoutToSend;
            creditRemaining[participants[payoutOrder].etherAddress] -= payoutToSend;
            participants[payoutOrder].payout -= payoutToSend;
            if (tokenContract.transfer(participants[payoutOrder].etherAddress, payoutToSend)) {
                emit Payout(payoutToSend, participants[payoutOrder].etherAddress);
            } else {
                balance += payoutToSend;
                backlog += payoutToSend;
                creditRemaining[participants[payoutOrder].etherAddress] += payoutToSend;
                participants[payoutOrder].payout += payoutToSend;
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
        if (payoutOrder >= participants.length) {
            return true;
        }
    }
    return true;
}

function tokenFallback(address _from, uint256 _value, bytes) public {
    require(msg.sender == address(token));
    for (uint256 i = 0; i < phases.length; i++) {
        if (phases[i].startDate <= now && now <= phases[i].endDate) {
            require(token.burn(_value));
            emit Burn(_from, _value, phases[i].discount);
            return;
        }
    }
    revert();
}

