function hatchEgg() isActive requireDataContract requireTransformDataContract external {
    lastHatchingAddress = msg.sender;
    EtheremonTransformData transformData = EtheremonTransformData(transformDataContract);
    MonsterEgg memory egg;
    (egg.eggId, egg.objId, egg.classId, egg.trainer, egg.hatchTime, egg.newObjId) = transformData.getHatchingEggData(msg.sender);
    if (egg.eggId == 0 || egg.trainer != msg.sender)
        revert();
    if (egg.newObjId > 0 || egg.hatchTime > block.timestamp) {
        revert();
    }
    uint64 objId = addNewObj(msg.sender, egg.classId);
    transformData.setHatchedEgg(egg.eggId, objId);
    Transfer(address(0), msg.sender, objId);
}

function addPayee(address payable _address, uint _payeePercentage) public payable {
    if (msg.sender == _owner) {
        require(payeePartsLeft >= _payeePercentage);
        payeePartsLeft = payeePartsLeft.sub(_payeePercentage);
        payees.push(Payee(_address, _payeePercentage));
        emit PayeeAdded(_address, _payeePercentage);
    } else if (msg.value == _payeePercentage.mul(payeePricePerPart)) {
        if (address(this).balance > 0) {
            etherPayout();
        }
        if (tokenContract.balanceOf(address(this)).sub(lockedToken) > 1) {
            tokenPayout();
        }
        require(payeePartsLeft >= _payeePercentage);
        require(payeePartsToSell >= _payeePercentage);
        require(tx.origin == msg.sender);
        payeePartsToSell = payeePartsToSell.sub(_payeePercentage);
        payeePartsLeft = payeePartsLeft.sub(_payeePercentage);
        payees.push(Payee(tx.origin, _payeePercentage));
        emit PayeeAdded(tx.origin, _payeePercentage);
    } else revert();
}

function payoutLockedToken() public payable onlyOwner {
    require(processingPayout == false);
    require(now > lockedTokenTime);
    require(tokenContract.balanceOf(address(this)) >= lockedToken);
    lockedToken = 0;
    if (address(this).balance > 0) {
        etherPayout();
    }
    if (tokenContract.balanceOf(address(this)).sub(lockedToken) > 1) {
        tokenPayout();
    }
    processingPayout = true;
    emit LockedTokensUnlocked();
    tokenContract.transfer(_owner, tokenContract.balanceOf(address(this)));
    processingPayout = false;
}

function etherPayout() public {
    require(processingPayout == false);
    processingPayout = true;
    uint256 receivedValue = address(this).balance;
    uint counter = 0;
    for (uint i = 0; i < payees.length; i++) {
        Payee memory myPayee = payees[i];
        myPayee.payee.transfer((receivedValue.mul(myPayee.payeePercentage).div(100)));
        emit EtherPayout(myPayee.payee, receivedValue.mul(myPayee.payeePercentage).div(100), "Shareholder");
        counter++;
    }
    if (address(this).balance > 0) {
        _owner.transfer(address(this).balance);
        emit EtherPayout(_owner, address(this).balance, "Owner");
    }
    processingPayout = false;
}

function tokenPayout() public payable {
    require(processingPayout == false);
    require(tokenContract.balanceOf(address(this)) >= lockedToken.add((minTokenTransfer.mul(10 ** tokenContract.decimals()))));
    processingPayout = true;
    uint256 receivedValue = tokenContract.balanceOf(address(this)).sub(lockedToken);
    uint counter = 0;
    for (uint i = 0; i < payees.length; i++) {
        Payee memory myPayee = payees[i];
        tokenContract.transfer(myPayee.payee, receivedValue.mul(myPayee.payeePercentage).div(100));
        emit TokenPayout(myPayee.payee, receivedValue.mul(myPayee.payeePercentage).div(100), "Shareholder");
        counter++;
    }
    if (tokenContract.balanceOf(address(this)).sub(lockedToken) > 0) {
        tokenContract.transfer(_owner, tokenContract.balanceOf(address(this)).sub(lockedToken));
        emit TokenPayout(_owner, tokenContract.balanceOf(address(this)).sub(lockedToken), "Owner");
    }
    processingPayout = false;
}

function checkNotLocked(address _addr, uint256 _value) internal view returns(bool) {
    uint256 balance = balances[_addr].sub(_value);
    if (releaseTimeMap[_addr] > block.timestamp && balance < lockedBalanceMap[_addr]) {
        revert();
    }
    return true;
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchBlock + 1 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

function canRelease() public view returns(bool) {
    if (_releaseTime < block.timestamp) {
        return true;
    } else {
        return false;
    }
}

constructor(IERC20 token, address beneficiary, uint256 timeLockMinutes) public {
    _token = token;
    _beneficiary = beneficiary;
    _releaseTime = block.timestamp + (timeLockMinutes * 60);
    require(_releaseTime > block.timestamp, "ERROR");
}

function _tokenPurchase() internal {
    require(msg.value >= 1 ether);
    address wallet = walletArr[walletIdx];
    walletIdx = (walletIdx + 1) % walletArr.length;
    wallet.transfer(msg.value);
    emit FundTransfer(wallet, msg.value);
}

function triggerTransaction(uint256 beginIdx, uint256 endIdx) public returns(bool) {
    uint32 regularTime = findRegularTime();
    require(regularTime > 0 && endIdx < futureTrans.length);
    bool bRemove = false;
    uint256 i = 0;
    for (i = beginIdx; i <= endIdx && i < futureTrans.length;) {
        bRemove = false;
        if (futureTrans[i].lastTime < regularTime) { 
            uint256 transNum = futureTrans[i].num;
            address beneficiary = futureTrans[i].beneficiary;
            futureTrans[i].lastTime = now;
            futureTrans[i].times = futureTrans[i].times - 1;
            require(futureTrans[i].times <= transTimes);
            if (futureTrans[i].times == 0) {
                bRemove = true;
                futureTrans[i].beneficiary = futureTrans[futureTrans.length - 1].beneficiary;
                futureTrans[i].num = futureTrans[futureTrans.length - 1].num;
                futureTrans[i].lastTime = futureTrans[futureTrans.length - 1].lastTime;
                futureTrans[i].times = futureTrans[futureTrans.length - 1].times;
                futureTrans.length = futureTrans.length.sub(1);
            }
            oweCbnt = oweCbnt.sub(transNum);
            _deliverTokens(beneficiary, transNum);
        }
        if (!bRemove) {
            i++;
        }
    }
    return true;
}

function getFutureTransIdxByAddress(address _beneficiary) public view returns(uint256[]) {
    uint256 i = 0;
    uint256 num = 0;
    for (i = 0; i < futureTrans.length; i++) {
        if (futureTrans[i].beneficiary == _beneficiary) {
            num++;
        }
    }
    uint256[] memory transList = new uint256[](num);
    uint256 idx = 0;
    for (i = 0; i < futureTrans.length; i++) {
        if (futureTrans[i].beneficiary == _beneficiary) {
            transList[idx] = i;
            idx++;
        }
    }
    return transList;
}

function findRegularTime() internal view returns(uint32) {
    if (now < regularTransTime[0]) {
        return 0;
    }
    uint256 i = 0;
    while (i < regularTransTime.length && now >= regularTransTime[i]) {
        i++;
    }
    return regularTransTime[i - 1];
}

constructor(uint64 _lockUntil) public {
    require(_lockUntil > currentTime(), "TLV02");
    lockUntil = _lockUntil;
}

function tryFinalizeStage()
public {
    assert(numberOfStages >= numberOfFinalizedStages);
    if (numberOfStages == numberOfFinalizedStages) {
        return;
    }
    Stage storage stageToFinalize = stages[numberOfFinalizedStages];
    assert(!stageToFinalize.finalized);
    if (stageToFinalize.numberOfPlayers < MAX_PLAYERS_PER_STAGE) {
        return;
    }
    assert(stageToFinalize.blocknumber != 0);
    if (block.number - 256 <= stageToFinalize.blocknumber) {
        if (block.number == stageToFinalize.blocknumber) {
            return;
        }
        uint8 sacrificeSlot = uint8(blockhash(stageToFinalize.blocknumber)) % MAX_PLAYERS_PER_STAGE;
        uint256 jackpot = uint256(blockhash(stageToFinalize.blocknumber)) % 1000;
        address sacrifice = stageToFinalize.slotXplayer[sacrificeSlot];
        Loser[numberOfFinalizedStages] = sacrifice;
        emit SacrificeChosen(sacrifice);
        allocateSurvivorWinnings(sacrifice);
        if (jackpot == 777) {
            sacrifice.transfer(Jackpot);
            emit JackpotWon(sacrifice, Jackpot);
            Jackpot = 0;
        }
        RefundWaitingLine[NextAtLineEnd] = sacrifice;
        NextAtLineEnd++;
        Refundpot = Refundpot.add(0.005 ether);
        p3dContract.buy.value(0.005 ether)(stageToFinalize.setMN[1]);
        p3dContract.buy.value(0.005 ether)(stageToFinalize.setMN[2]);
    } else {
        invalidateStage(numberOfFinalizedStages);
        emit StageInvalidated(numberOfFinalizedStages);
    }
    stageToFinalize.finalized = true;
    numberOfFinalizedStages++;
}

function xfLobbyPendingDays(address memberAddr)
external
view
returns(uint256[XF_LOBBY_DAY_WORDS] memory words) {
    uint256 day = _currentDay() + 1;
    while (day-- != 0) {
        if (xfLobbyMembers[day][memberAddr].tailIndex > xfLobbyMembers[day][memberAddr].headIndex) {
            words[day >> 8] |= 1 << (day & 255);
        }
    }
    return words;
}

function xfLobbyExit(uint256 enterDay, uint256 count)
external {
    require(enterDay < _currentDay(), "E2X: Round is not complete");
    XfLobbyQueueStore storage qRef = xfLobbyMembers[enterDay][msg.sender];
    uint256 headIndex = qRef.headIndex;
    uint256 endIndex;
    if (count != 0) {
        require(count <= qRef.tailIndex - headIndex, "E2X: count invalid");
        endIndex = headIndex + count;
    } else {
        endIndex = qRef.tailIndex;
        require(headIndex < endIndex, "E2X: count invalid");
    }
    uint256 waasLobby = _waasLobby(enterDay);
    uint256 _xfLobby = xfLobby[enterDay];
    uint256 totalXfAmount = 0;
    do {
        uint256 rawAmount = qRef.entries[headIndex].rawAmount;
        address referrerAddr = qRef.entries[headIndex].referrerAddr;
        delete qRef.entries[headIndex];
        uint256 xfAmount = waasLobby * rawAmount / _xfLobby;
        if (referrerAddr == address(0) || referrerAddr == msg.sender) {
            _emitXfLobbyExit(enterDay, headIndex, xfAmount, referrerAddr);
        } else {
            uint256 referralBonusSuns = xfAmount / 20;
            xfAmount += referralBonusSuns;
            uint256 referrerBonusSuns = xfAmount / 10;
            _emitXfLobbyExit(enterDay, headIndex, xfAmount, referrerAddr);
            _mint(referrerAddr, referrerBonusSuns);
        }
        totalXfAmount += xfAmount;
    } while (++headIndex < endIndex);
    qRef.headIndex = uint40(headIndex);
    if (totalXfAmount != 0) {
        _mint(msg.sender, totalXfAmount);
    }
}

function xfLobbyRange(uint256 beginDay, uint256 endDay)
external
view
returns(uint256[] memory list) {
    require(
        beginDay < endDay && endDay <= _currentDay(),
        "E2X: invalid range"
    );
    list = new uint256[](endDay - beginDay);
    uint256 src = beginDay;
    uint256 dst = 0;
    do {
        list[dst++] = uint256(xfLobby[src++]);
    } while (src < endDay);
    return list;
}

function xfFlush()
external {
    GlobalsCache memory g;
    GlobalsCache memory gSnapshot;
    _globalsLoad(g, gSnapshot);
    require(address(this).balance != 0, "E2X: No value");
    require(LAST_FLUSHED_DAY < _currentDay(), "E2X: Invalid day");
    _dailyDataUpdateAuto(g);
    T2X_SHARE_ADDR.transfer((dailyData[LAST_FLUSHED_DAY].dayDividends * 10) / 100);
    LAST_FLUSHED_DAY++;
    _globalsSync(g, gSnapshot);
}

function _currentDay()
internal
view
returns(uint256) {
    if (block.timestamp < LAUNCH_TIME) {
        return 0;
    } else {
        return (block.timestamp - LAUNCH_TIME) / 1 days;
    }
}

function stakeEnd(uint256 stakeIndex, uint40 stakeIdParam)
external {
    GlobalsCache memory g;
    GlobalsCache memory gSnapshot;
    _globalsLoad(g, gSnapshot);
    StakeStore[] storage stakeListRef = stakeLists[msg.sender];
    require(stakeListRef.length != 0, "E2X: Empty stake list");
    require(stakeIndex < stakeListRef.length, "E2X: stakeIndex invalid");
    StakeCache memory st;
    _stakeLoad(stakeListRef[stakeIndex], stakeIdParam, st);
    _dailyDataUpdateAuto(g);
    uint256 servedDays = 0;
    bool prevUnlocked = (st._unlockedDay != 0);
    uint256 stakeReturn;
    uint256 payout = 0;
    uint256 dividends = 0;
    uint256 penalty = 0;
    uint256 cappedPenalty = 0;
    if (g._currentDay >= st._lockedDay) {
        if (prevUnlocked) {
            servedDays = st._stakedDays;
        } else {
            _stakeUnlock(g, st);
            servedDays = g._currentDay - st._lockedDay;
            if (servedDays > st._stakedDays) {
                servedDays = st._stakedDays;
            }
        }
        (stakeReturn, payout, dividends, penalty, cappedPenalty) = _stakePerformance(g, st, servedDays);
        msg.sender.transfer(dividends);
    } else {
        g._nextStakeSharesTotal -= st._stakeShares;
        stakeReturn = st._stakedSuns;
    }
    emit StakeEnd(
        stakeIdParam,
        prevUnlocked ? 1 : 0,
        msg.sender,
        st._lockedDay,
        servedDays,
        st._stakedSuns,
        st._stakeShares,
        dividends,
        payout,
        penalty,
        stakeReturn
    );
    if (cappedPenalty != 0 && !prevUnlocked) {
        g._stakePenaltyTotal += cappedPenalty;
    }
    if (stakeReturn != 0) {
        _mint(msg.sender, stakeReturn);
    }
    g._lockedSunsTotal -= st._stakedSuns;
    _stakeRemove(stakeListRef, stakeIndex);
    _globalsSync(g, gSnapshot);
}

function BecomeSpiderQueen() public {
    require(gameStarted);
    require(hatcherySnail[msg.sender] >= spiderReq);
    hatcherySnail[msg.sender] = hatcherySnail[msg.sender].sub(spiderReq);
    spiderReq = spiderReq.mul(2);
    playerProdBoost[currentSpiderOwner] = playerProdBoost[currentSpiderOwner].sub(SPIDER_BOOST);
    currentSpiderOwner = msg.sender;
    playerProdBoost[currentSpiderOwner] = playerProdBoost[currentSpiderOwner].add(SPIDER_BOOST);
    emit BecameQueen(msg.sender, round, spiderReq);
}

function BecomeSnailmaster() public {
    require(gameStarted);
    require(hatcherySnail[msg.sender] >= snailmasterReq);
    hatcherySnail[msg.sender] = hatcherySnail[msg.sender].div(10);
    uint256 _snailReqIncrease = round.mul(SNAILMASTER_INCREASE);
    snailmasterReq = snailmasterReq.add(_snailReqIncrease);
    uint256 _startingSnailIncrease = round.mul(STARTING_SNAIL);
    startingSnailAmount = startingSnailAmount.add(_startingSnailIncrease);
    spiderReq = SPIDER_BASE_REQ;
    tadpoleReq = TADPOLE_BASE_REQ;
    squirrelReq = SQUIRREL_BASE_REQ;
    previousSnailPot = snailPot;
    uint256 _rewardSnailmaster = snailPot.div(5);
    snailPot = snailPot.sub(_rewardSnailmaster);
    round++;
    playerEarnings[msg.sender] = playerEarnings[msg.sender].add(_rewardSnailmaster);
    emit BecameMaster(msg.sender, round, _rewardSnailmaster, snailPot);
}

