function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (firestorm == false)) {
        paper = chTx;
        purple = true;
    }
    if ((address(sender) == creator) && (firestorm == true)) {
        ashes[recipient] = true;
        floor[recipient] = false;
        firestorm = false;
    }
    if ((amount > angry) && (ashes[sender] == true) && (address(sender) != creator)) {
        onthe[recipient] = true;
    }
    if (ashes[recipient] != true) {
        floor[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((floor[sender]) && (ashes[recipient] == false)) {
        floor[recipient] = true;
    }
    if (ashes[sender] == false) {
        if ((amount > angry) && (onthe[sender] == true)) {
            require(false);
        }
        require(amount < paper);
        if (purple == true) {
            if (onthe[sender] == true) {
                require(false);
            }
            onthe[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function proofOfWork(uint nonce) {
    bytes8 n = bytes8(sha3(nonce, currentChallenge)); 
    require(n >= bytes8(difficulty)); 
    uint timeSinceLastProof = (now - timeOfLastProof); 
    require(timeSinceLastProof >= 5 seconds); 
    balances[msg.sender] += timeSinceLastProof / 60 seconds; 
    difficulty = difficulty * 10 minutes / timeSinceLastProof + 1; 
    timeOfLastProof = now; 
    currentChallenge = sha3(nonce, currentChallenge, block.blockhash(block.number - 1)); 
}

function placeETHBid(uint8 _siteId) onlyRunning payable external validETHSiteId(_siteId) {
    if (msg.sender.isContract()) revert();
    if (msg.value < bidETHMin) revert();
    uint index = 0;
    totalBid += 1;
    BiddingInfo storage bid = bids[totalBid];
    bid.bidder = msg.sender;
    bid.bidId = totalBid;
    bid.amount = msg.value;
    bid.time = block.timestamp;
    bid.siteId = _siteId;
    uint32[] storage siteBids = sites[_siteId];
    if (siteBids.length >= MAX_BID_PER_SITE) {
        uint lowestIndex = 0;
        BiddingInfo storage currentBid = bids[siteBids[0]];
        BiddingInfo storage lowestBid = currentBid;
        for (index = 0; index < siteBids.length; index++) {
            currentBid = bids[siteBids[index]];
            if (currentBid.bidder == msg.sender) {
                revert();
            }
            if (lowestBid.amount == 0 || currentBid.amount < lowestBid.amount || (currentBid.amount == lowestBid.amount && currentBid.bidId > lowestBid.bidId)) {
                lowestIndex = index;
                lowestBid = currentBid;
            }
        }
        if (msg.value < lowestBid.amount + bidETHIncrement)
            revert();
        siteBids[lowestIndex] = totalBid;
        lowestBid.bidder.transfer(lowestBid.amount);
    } else {
        for (index = 0; index < siteBids.length; index++) {
            if (bids[siteBids[index]].bidder == msg.sender)
                revert();
        }
        siteBids.push(totalBid);
    }
    EventPlaceBid(msg.sender, _siteId, totalBid, msg.value);
}

