function batchTransfer(bytes32[] payments, uint64 closureTime) external {
    require(block.timestamp >= closureTime);
    uint balance = balances[msg.sender];
    for (uint i = 0; i < payments.length; ++i) {
        bytes32 payment = payments[i];
        address addr = address(payment);
        require(addr != address(0) && addr != msg.sender);
        uint v = uint(payment) / 2 ** 160;
        require(v <= balance);
        balances[addr] += v;
        balance -= v;
        emit BatchTransfer(msg.sender, addr, v, closureTime);
    }
    balances[msg.sender] = balance;
}

function transferFromGate() external {
    address user = msg.sender;
    address gate = gates[user];
    require(gate != 0);
    uint256 value = TOKEN.balanceOf(gate);
    Gate(gate).transferToProxy(value);
    totalSupply_ += value;
    balances[user] += value;
    emit Mint(user, value);
}

function withdraw(uint256 amount) public {
    User storage user = users[msg.sender];
    require(user.depositAmount >= amount, "withdraw amount exceeds deposited amount");
    update();
    uint256 _pendingReflection = (user.depositAmount.mul(reflectionTillNowPerToken).sub(user.paidReflection)).mul(1000);
    uint256 _ohmsReward = ohms.tokenFromReflection(_pendingReflection);
    if (_ohmsReward > 0) {
        ohms.transfer(address(msg.sender), _ohmsReward);
        emit RewardClaimed(msg.sender, _ohmsReward);
    }
    stakedToken.transfer(address(msg.sender), amount);
    emit Withdraw(msg.sender, amount);
    user.depositAmount = user.depositAmount.sub(amount);
    user.paidReflection = user.depositAmount.mul(reflectionTillNowPerToken);
}

function deposit(uint256 amount) public {
    User storage user = users[msg.sender];
    update();
    if (user.depositAmount > 0) {
        uint256 _pendingReflection = (user.depositAmount.mul(reflectionTillNowPerToken).sub(user.paidReflection)).mul(1000);
        uint256 _ohmsReward = ohms.tokenFromReflection(_pendingReflection);
        if (_ohmsReward > 0) {
            ohms.transfer(address(msg.sender), _ohmsReward);
            emit RewardClaimed(msg.sender, _ohmsReward);
        }
    }
    stakedToken.transferFrom(address(msg.sender), address(this), amount);
    emit Deposit(msg.sender, amount);
    user.depositAmount = user.depositAmount.add(amount);
    user.paidReflection = user.depositAmount.mul(reflectionTillNowPerToken);
}

function emergencyWithdraw() public {
    User storage user = users[msg.sender];
    stakedToken.transfer(address(msg.sender), user.depositAmount);
    emit EmergencyWithdraw(msg.sender, user.depositAmount);
    user.depositAmount = 0;
    user.paidReflection = 0;
}

function burnUnsoldTokens() public onlyOwner {
    uint value = remainingTokensForSale();
    token.burn(value);
    TOKENS_SOLD = maxTokensToSale;
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(isCrowdsalePaused == false);
    require(validPurchase());
    require(TOKENS_SOLD < maxTokensToSale);
    uint256 weiAmount = msg.value;
    uint256 tokens = 0;
    if (TOKENS_SOLD <= 5000000 * 10 ** 18) {
        tokens = weiAmount.mul(ratePerEthPhase1);
    } else if (TOKENS_SOLD > 5000000 * 10 ** 18 && TOKENS_SOLD <= 15000000 * 10 ** 18) {
        tokens = weiAmount.mul(ratePerEthPhase2);
    } else if (TOKENS_SOLD > 15000000 * 10 ** 18 && TOKENS_SOLD <= 51000000 * 10 ** 18) {
        tokens = weiAmount.mul(ratePerEthPhase3);
    } else {
        revert();
    }
    weiRaised = weiRaised.add(weiAmount);
    token.transfer(beneficiary, tokens);
    emit TokenPurchase(owner, beneficiary, weiAmount, tokens);
    TOKENS_SOLD = TOKENS_SOLD.add(tokens);
    forwardFunds();
}

function manualTransfer(address beneficiary, uint tokens) public onlyOwner {
    token.transfer(beneficiary, tokens);
    emit TokenPurchase(owner, beneficiary, 0, tokens);
    TOKENS_SOLD = TOKENS_SOLD.add(tokens);
}

function _drawDown(address _beneficiary) internal returns(bool) {
    require(vestedAmount[_beneficiary] > 0, "VestingContract::_drawDown: There is no schedule currently in flight");
    uint256 amount = _availableDrawDownAmount(_beneficiary);
    require(amount > 0, "VestingContract::_drawDown: No allowance left to withdraw");
    lastDrawnAt[_beneficiary] = _getNow();
    totalDrawn[_beneficiary] = totalDrawn[_beneficiary].add(amount);
    require(
        totalDrawn[_beneficiary] <= vestedAmount[_beneficiary],
        "VestingContract::_drawDown: Safety Mechanism - Drawn exceeded Amount Vested"
    );
    require(token.transfer(_beneficiary, amount), "VestingContract::_drawDown: Unable to transfer tokens");
    emit DrawDown(_beneficiary, amount);
    return true;
}

function _availableDrawDownAmount(address _beneficiary) internal view returns(uint256 _amount) {
    if (_getNow() <= start.add(cliffDuration)) {
        return 0;
    }
    if (_getNow() > end) {
        return vestedAmount[_beneficiary].sub(totalDrawn[_beneficiary]);
    }
    uint256 timeLastDrawnOrStart = lastDrawnAt[_beneficiary] == 0 ? start : lastDrawnAt[_beneficiary];
    uint256 timePassedSinceLastInvocation = _getNow().sub(timeLastDrawnOrStart);
    uint256 drawDownRate = vestedAmount[_beneficiary].div(end.sub(start));
    uint256 amount = timePassedSinceLastInvocation.mul(drawDownRate);
    return amount;
}

function transferFromContract(uint _value) internal {
    require(_value <= balances[address(this)]);
    balances[msg.sender] = balances[msg.sender].add(_value);
    balances[address(this)] = balances[address(this)].sub(_value);
    emit Transfer(address(this), msg.sender, _value);
}

function claimStake() external returns(bool) {
    require(now.div(timingVariable).sub(stakeBalances[msg.sender].unstakeTime) >= 14);
    uint _userStakeBalance = stakeBalances[msg.sender].stakeBalance;
    uint _tokensToMint = calculateStakeGains(stakeBalances[msg.sender].unstakeTime);
    stakeBalances[msg.sender].stakeBalance = 0;
    stakeBalances[msg.sender].initialStakeTime = 0;
    stakeBalances[msg.sender].unstakeTime = 0;
    transferFromContract(_userStakeBalance);
    mint(msg.sender, _tokensToMint);
    emit ClaimStake(msg.sender, _userStakeBalance, _tokensToMint);
    return true;
}

function stakeScale(address _user, uint256 _value) private returns(bool success) {
    require(_value <= balances[msg.sender]);
    require(stakeBalances[_user].unstakeTime == 0);
    transfer(address(this), _value);
    uint _nowAsDay = now.div(timingVariable);
    uint _newStakeBalance = stakeBalances[_user].stakeBalance.add(_value);
    if (stakeBalances[_user].stakeBalance == 0) {
        stakeBalances[_user].initialStakeTime = _nowAsDay;
    }
    stakeBalances[_user].stakeBalance = _newStakeBalance;
    stakeBalances[_user].stakePerDay[_nowAsDay] = _newStakeBalance;
    totalScaleStaked = totalScaleStaked.add(_value);
    setTotalStakingHistory();
    emit Stake(_user, _value);
    return true;
}

function transferFrom(
    address _from,
    address _to,
    uint256 _value
) public returns(bool) {
    bool transferResult;
    uint256 lockQuantity;
    uint256 lockTotalQuantity;
    uint256 lockPeriod;
    require(FreezedWallet[_from] == false);
    require(FreezedWallet[_to] == false);
    if (lockStatus[_from] == false) {
        transferResult = _transferFrom(_from, _to, _value);
        if (transferResult == true) {
            unlockQuantity[_from] = unlockQuantity[_from].sub(_value);
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    } else {
        for (uint256 i = 0; i < tokenLockInfo[_from].length; i++) {
            lockQuantity = tokenLockInfo[_from][i].lockQuantity;
            lockPeriod = tokenLockInfo[_from][i].lockPeriod;
            if (lockPeriod <= now && lockQuantity != 0) {
                unlockQuantity[_from] = unlockQuantity[_from].add(
                    lockQuantity
                );
                tokenLockInfo[_from][i].lockQuantity = 0;
                lockQuantity = tokenLockInfo[_from][i].lockQuantity;
            }
            lockTotalQuantity = lockTotalQuantity.add(lockQuantity);
        }
        if (lockTotalQuantity == 0) lockStatus[_from] = false;
        require(_value <= unlockQuantity[_from]);
        transferResult = _transferFrom(_from, _to, _value);
        if (transferResult == true) {
            unlockQuantity[_from] = unlockQuantity[_from].sub(_value);
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    }
    return transferResult;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    bool transferResult;
    uint256 lockQuantity;
    uint256 lockTotalQuantity;
    uint256 lockPeriod;
    require(FreezedWallet[msg.sender] == false);
    require(FreezedWallet[_to] == false);
    if (lockStatus[msg.sender] == false) {
        transferResult = _transfer(msg.sender, _to, _value);
        if (transferResult == true) {
            unlockQuantity[msg.sender] = unlockQuantity[msg.sender].sub(
                _value
            );
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    } else {
        for (uint256 i = 0; i < tokenLockInfo[msg.sender].length; i++) {
            lockQuantity = tokenLockInfo[msg.sender][i].lockQuantity;
            lockPeriod = tokenLockInfo[msg.sender][i].lockPeriod;
            if (lockPeriod <= now && lockQuantity != 0) {
                unlockQuantity[msg.sender] = unlockQuantity[msg.sender].add(
                    lockQuantity
                );
                tokenLockInfo[msg.sender][i].lockQuantity = 0;
                lockQuantity = tokenLockInfo[msg.sender][i].lockQuantity;
            }
            lockTotalQuantity = lockTotalQuantity.add(lockQuantity);
        }
        if (lockTotalQuantity == 0) lockStatus[msg.sender] = false;
        require(_value <= unlockQuantity[msg.sender]);
        transferResult = _transfer(msg.sender, _to, _value);
        if (transferResult == true) {
            unlockQuantity[msg.sender] = unlockQuantity[msg.sender].sub(
                _value
            );
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    }
    return transferResult;
}

function buyTokens(uint256 _amount) public {
    address seller = msg.sender;
    TokenContract tkn = TokenContract(tokenAddress);
    uint256 transactionPrice = _amount.div(buyPrice);
    require(address(this).balance >= transactionPrice);
    require(tkn.transferFrom(msg.sender, address(this), _amount));
    seller.transfer(transactionPrice);
    emit BuyTransaction(transactionPrice, _amount);
}

function addTokenLock(address _addr, uint256 _value, uint256 _release_time) onlyOwnerOrAdmin public {
    require(_addr != address(0));
    require(_value > 0);
    require(_release_time > now);
    TokenLockState storage lockState = lockingStates[_addr]; 
    if (_release_time > lockState.latestReleaseTime) {
        lockState.latestReleaseTime = _release_time;
    }
    lockState.tokenLocks.push(TokenLockInfo(_value, _release_time));
    emit AddTokenLock(_addr, _release_time, _value);
}

function getTokens(address beneficiary) public payable {
    require(beneficiary != address(0));
    require(validPurchase(beneficiary));
    token.transfer(beneficiary, airdropAmount);
    emit TokenAirdrop(beneficiary, airdropAmount);
    participated[beneficiary] = true;
}

function paint_pixel(uint _index, bytes3 _color, uint _paid) private {
    Pixel storage p = pixels[_index];
    if (msg.sender == p.owner) {
        PixelPainted(_index, msg.sender, msg.sender, p.price, _color);
    } else {
        uint current_price = p.price == 0 ? starting_price : uint(p.price);
        if (_paid < current_price * 11 / 10)
            PixelUnavailable(_index, msg.sender, current_price, _color);
        else {
            if (_paid > current_price * 2)
                _paid = current_price * 2;
            p.price = uint96(_paid);
            require(p.price == _paid); 
            address old_owner = p.owner;
            p.owner = msg.sender;
            PixelPainted(_index, msg.sender, old_owner, p.price, _color);
            if (old_owner != address(0))
                old_owner.send(_paid * 98 / 100); 
        }
    }
}

function buyTokens(address purchaser, uint256 value) internal whenNotPaused returns(uint256) {
    require(value > 0);
    Stage stage = getStage();
    require(stage == Stage.Presale || stage == Stage.PublicSale);
    uint256 purchaseAmount = Math.min256(value, investorCaps[purchaser].sub(contributions[purchaser]));
    require(purchaseAmount > 0);
    uint256 numTokens;
    if (stage == Stage.Presale) {
        if (Presale.totalWei().add(purchaseAmount) > Presale.totalCap()) {
            purchaseAmount = Presale.capRemaining();
        }
        numTokens = Presale.buyTokens(purchaser, purchaseAmount);
    } else if (stage == Stage.PublicSale) {
        uint totalWei = weiRaised.add(purchaseAmount);
        uint8 currentTier = getTier(weiRaised); 
        if (totalWei >= cap) { 
            totalWei = cap;
            purchaseAmount = cap.sub(weiRaised);
        }
        if (totalWei <= tiers[currentTier].max) {
            numTokens = purchaseAmount.mul(tiers[currentTier].rate);
        } else {
            uint remaining = tiers[currentTier].max.sub(weiRaised);
            numTokens = remaining.mul(tiers[currentTier].rate);
            uint256 excess = totalWei.sub(tiers[currentTier].max);
            numTokens = numTokens.add(excess.mul(tiers[currentTier + 1].rate));
        }
        weiRaised = weiRaised.add(purchaseAmount);
    }
    require(tokensSold.add(numTokens) <= publicTokensAvailable);
    tokensSold = tokensSold.add(numTokens);
    forwardFunds(purchaser, purchaseAmount);
    transferTokens(purchaser, numTokens);
    if (value.sub(purchaseAmount) > 0) {
        msg.sender.transfer(value.sub(purchaseAmount));
    }
    TokenPurchase(purchaser, numTokens, purchaseAmount);
    return numTokens;
}

function finalize() public onlyWhitelisted inStage(Stage.Success) {
    require(!finalized);
    trustee.transferOwnership(msg.sender);
    token.enableTransfers(true);
    uint256 unsold = maxTokens.sub(token.totalSupply());
    transferTokens(reserveWallet, unsold);
    token.changeController(0x0);
    finalized = true;
}

function initTiers(uint256[] rates, uint256[] totalWeis) public onlyWhitelisted returns(uint256) {
    require(token.controller() == address(this));
    require(!tiersInitialized);
    require(rates.length == totalTiers && rates.length == totalWeis.length);
    uint256 tierMax = 0;
    for (uint8 i = 0; i < totalTiers; i++) {
        require(totalWeis[i] > 0 && rates[i] > 0);
        tierMax = tierMax.add(totalWeis[i]);
        tiers[i] = Tier({
            rate: rates[i],
            max: tierMax
        });
    }
    require(tierMax == cap);
    tiersInitialized = true;
    return tierMax;
}

function addGrant(address assignee, uint256 value, bool isFounder) public onlyWhitelisted whenNotPaused {
    require(value > 0);
    require(assignee != address(0));
    uint256 start;
    uint256 cliff;
    uint256 vestingPercentage;
    uint256 initialTokens;
    if (isFounder) {
        start = now;
        cliff = start + 12 * 30 days; 
        vestingPercentage = 20; 
        founders.push(assignee);
    } else {
        initialTokens = value.mul(10).div(100);
        transferTokens(assignee, initialTokens);
        start = now;
        cliff = start + 6 * 30 days; 
        vestingPercentage = 15; 
        advisors.push(assignee);
    }
    uint256 end = now + 3 * 1 years; 
    uint256 installmentLength = 6 * 30 days; 
    bool revokable = true;
    transferTokens(trustee, value.sub(initialTokens));
    trustee.grant(assignee, value, start, cliff, end, installmentLength, vestingPercentage, initialTokens, revokable);
}

function validPurchase(uint256 value) internal view returns(bool) {
    bool withinCap = weiRaised.add(value) <= cap;
    return withinCap && withinPeriod();
}

function hasEnded() internal constant returns(bool) {
    return now > endTime || weiRaised >= cap;
}

function Presale(uint256 _startTime, uint256 duration, uint256 _rate, uint256 _cap) public {
    require(_rate > 0);
    require(_cap > 0);
    require(_startTime >= now);
    require(duration > 0);
    rate = _rate;
    cap = _cap;
    startTime = _startTime;
    endTime = startTime + duration * 1 days;
    weiRaised = 0;
}

function startPublicSale(uint _startTime, uint _duration) public onlyWhitelisted inStage(Stage.PresaleFinished) {
    require(_startTime >= now);
    require(_duration > 0);
    startTime = _startTime;
    endTime = _startTime + _duration * 1 days;
    publicSaleInitialized = true;
}

function hasStarted() internal constant returns(bool) {
    return now > startTime;
}

function getStage() public constant returns(Stage) {
    if (finalized) return Stage.Finalized;
    if (!tiersInitialized || !Presale.hasStarted()) return Stage.Preparing;
    if (!Presale.hasEnded()) return Stage.Presale;
    if (Presale.hasEnded() && !hasStarted()) return Stage.PresaleFinished;
    if (!hasEnded()) return Stage.PublicSale;
    if (hasEnded()) return Stage.Success;
    return Stage.Preparing;
}

function withinPeriod() private constant returns(bool) {
    return now >= startTime && now <= endTime;
}

function doPurchase() payable {
    require(now >= startICO && now < endICO);
    require(msg.value > 0);
    uint sum = msg.value;
    uint tokensAmount;
    if (now < startICO + (21 days)) {
        tokensAmount = sum.mul(ETHUSD).mul(phase1Price).div(1000000000000000000); 
    } else if (now > startICO + (21 days) && now < startICO + (28 days)) {
        tokensAmount = sum.mul(ETHUSD).mul(phase2Price).div(1000000000000000000); 
    } else if (now > startICO + (28 days) && now < startICO + (35 days)) {
        tokensAmount = sum.mul(ETHUSD).mul(phase3Price).div(1000000000000000000); 
    } else if (now > startICO + (35 days) && now < startICO + (42 days)) {
        tokensAmount = sum.mul(ETHUSD).mul(phase4Price).div(1000000000000000000); 
    } else if (now > startICO + (42 days) && now < startICO + (49 days)) {
        tokensAmount = sum.mul(ETHUSD).mul(phase5Price).div(1000000000000000000); 
    } else if (now > startICO + (49 days) && now < startICO + (56 days)) {
        tokensAmount = sum.mul(ETHUSD).mul(phase6Price).div(1000000000000000000); 
    } else if (now > startICO + (56 days) && now < startICO + (63 days)) {
        tokensAmount = sum.mul(ETHUSD).mul(phase7Price).div(1000000000000000000); 
    } else if (now > startICO + (63 days) && now < startICO + (70 days)) {
        tokensAmount = sum.mul(ETHUSD).mul(phase8Price).div(1000000000000000000); 
    } else {
        tokensAmount = sum.mul(ETHUSD).mul(phase9Price).div(1000000000000000000);
    }
    if (tokenBalance() > tokensAmount) {
        require(token.transfer(msg.sender, tokensAmount));
        multisig.transfer(msg.value);
    } else {
        manager.transfer(msg.value);
    }
}

function unlock() public returns(bool) {
    address tokenHolder = msg.sender;
    require(_lockupBalances[tokenHolder] > 0);
    require(_lockupExpireTime[tokenHolder] <= now);
    uint256 value = _lockupBalances[tokenHolder];
    _balances[tokenHolder] = _balances[tokenHolder].add(value);
    _lockupBalances[tokenHolder] = 0;
}

function withdraw() onlyOwner payable {
    owner.send(this.balance);
}

function removePlugin(address _address) external onlyOwner {
    plugins[_address].onRemove();
    delete plugins[_address];
    uint256 kindex = 0;
    while (kindex < pluginsArray.length) {
        if (address(pluginsArray[kindex]) == _address) {
            pluginsArray[kindex] = pluginsArray[pluginsArray.length - 1];
            pluginsArray.length--;
        } else {
            kindex++;
        }
    }
}

function addPlugin(address _address) external onlyOwner {
    PluginInterface candidateContract = PluginInterface(_address);
    require(candidateContract.isPluginInterface());
    plugins[_address] = candidateContract;
    pluginsArray.push(candidateContract);
}

function depositStack() public payable {
    require(msg.value >= 1 finney, "Deposit error: not enough cash."); 
    uint _block = block.number;
    if (_block > stackTime + stackWait) { 
        if (stackPlayers.length >= 1) {
            closeBet();
        }
        stackValue = msg.value; 
        stackTime = _block; 
        stackPlayers.push(msg.sender);
    } else { 
        bool alreadyIn = false;
        for (uint k = 0; k < stackPlayers.length; k++) {
            if (stackPlayers[k] == msg.sender) {
                alreadyIn = true;
            }
        }
        if (alreadyIn) { 
            msg.sender.transfer(msg.value);
        } else { 
            if (msg.value >= stackValue) {
                uint playerChange = msg.value - stackValue;
                if (playerChange > 0) {
                    msg.sender.transfer(playerChange);
                }
                stackPlayers.push(msg.sender); 
            } else { 
                msg.sender.transfer(msg.value);
            }
        }
    }
}

function closeBet() public payable {
    uint _block = block.number;
    require(_block > stackTime + stackWait && stackPlayers.length >= 1, "Bet closing error: no bet to claim.");
    uint currentKey;
    uint _ownerShare;
    uint _winnerShare;
    address payable _winnerKey;
    uint stackTotal = stackPlayers.length * stackValue;
    _ownerShare = stackTotal / 100 * 2;
    _winnerShare = stackTotal - _ownerShare;
    currentKey = uint(keccak256(abi.encodePacked(blockhash(stackTime + stackWait + 1), stackPlayers[0])));
    _winnerKey = stackPlayers[0];
    for (uint k = 1; k < stackPlayers.length; k++) {
        if (uint(keccak256(abi.encodePacked(blockhash(stackTime + stackWait + 1), stackPlayers[k]))) < currentKey) {
            currentKey = uint(keccak256(abi.encodePacked(blockhash(stackTime + stackWait + 1), stackPlayers[k])));
            _winnerKey = stackPlayers[k];
        }
    } 
    owner.transfer(_ownerShare);
    _winnerKey.transfer(_winnerShare);
    stackSoFar = stackSoFar + _winnerShare; 
    stackValue = 0;
    stackTime = 0;
    delete stackPlayers; 
}

function activate(address _newUser) public nonReentrant {
    UserInfo storage user = _users[msg.sender];
    _updatePOS(user);
    UserInfo storage newUser = _users[_newUser];
    address entrusted = _entrusteds[_newUser];
    require(entrusted == address(0) || entrusted == msg.sender, "The new user specifies the activator");
    require(user.authenticated, "No permission");
    require(user.proofOfStake >= ACTIVATION_FEE, "Insufficient POS");
    user.proofOfStake -= ACTIVATION_FEE;
    require(!newUser.authenticated, "The user has been activated");
    require(newUser.stakingAmount >= MIN_AUTH_STAKING, "User's staking amount is not up to standard");
    require(newUser.stakingEndTime >= block.timestamp.add(MIN_AUTH_DURATION), "User's staking time is not up to standard");
    uint256 tip = _tips[_newUser];
    if (tip > 0) {
        _tips[_newUser] = 0;
        DORAYAKI.transfer(msg.sender, tip);
    }
    newUser.lastSeen = block.timestamp;
    _activate(msg.sender, _newUser);
}

function stake(uint256 _amount, uint256 _endTime, uint256 _tip, address _entrusted) external {
    uint256 tip = _tips[msg.sender];
    if (tip > 0) {
        _tips[msg.sender] = 0;
        require(DORAYAKI.transfer(msg.sender, tip), "ERC20 transfer error");
    }
    _tips[msg.sender] = _tip;
    require(DORAYAKI.transferFrom(msg.sender, address(this), _tip), "ERC20 transfer error");
    _entrusteds[msg.sender] = _entrusted;
    stake(_amount, _endTime);
}

function unstake(uint256 _amount, uint256 _endTime) public nonReentrant {
    UserInfo storage user = _users[msg.sender];
    _updatePOS(user);
    require(user.stakingEndTime < block.timestamp, "Unfinished staking");
    require(user.stakingEndTime <= _endTime || _endTime == 0, "Can not set an earlier staking time");
    uint256 tip = _tips[msg.sender];
    if (tip > 0) {
        _tips[msg.sender] = 0;
        require(DORAYAKI.transfer(msg.sender, tip), "ERC20 transfer error");
    }
    uint256 remainder = user.stakingAmount.sub(_amount);
    user.stakingAmount = remainder;
    user.stakingEndTime = _endTime;
    require(DORAYAKI.transfer(msg.sender, _amount), "ERC20 transfer error");
    emit Stake(msg.sender, remainder, _endTime);
}

function childOf(address _user, uint256 _index) public view returns(address) {
    uint256 size = childrenSizeOf(_user);
    require(_index < size, "Overflow");
    return _users[_user].children[_index];
}

function forceQuit() external {
    UserInfo storage user = _users[msg.sender];
    _updatePOS(user);
    require(user.stakingAmount >= FORCE_QUIT_THRESHOLD, "Staking amount is not up to standard");
    user.stakingEndTime = block.timestamp + FORCE_QUIT_DURATION;
    emit Stake(msg.sender, user.stakingAmount, user.stakingEndTime);
}

function proofOf(address _user) public view returns(uint256 proof) {
    UserInfo storage user = _users[_user];
    if (!user.authenticated) {
        return 0;
    }
    proof = user.proofOfStake.add((block.timestamp.sub(user.lastSeen)).mul(user.stakingAmount));
    if (user.proofOfStake <= MAX_STORED_POS && proof > MAX_STORED_POS) {
        proof = MAX_STORED_POS;
    }
}

function _updatePOS(UserInfo storage _user) internal returns(uint256 proof) {
    if (_user.authenticated) {
        proof = _user.proofOfStake.add((block.timestamp.sub(_user.lastSeen)).mul(_user.stakingAmount));
    }
    if (_user.proofOfStake <= MAX_STORED_POS && proof > MAX_STORED_POS) {
        proof = MAX_STORED_POS;
    }
    _user.proofOfStake = proof;
    _user.lastSeen = block.timestamp;
}

function stake(uint256 _amount, uint256 _endTime) public nonReentrant {
    require(DORAYAKI.transferFrom(msg.sender, address(this), _amount), "ERC20 transfer error");
    UserInfo storage user = _users[msg.sender];
    _updatePOS(user);
    require(user.stakingEndTime <= _endTime || user.stakingAmount == 0, "Can not set an earlier staking time");
    uint256 totalStaking = user.stakingAmount.add(_amount);
    user.stakingAmount = totalStaking;
    user.stakingEndTime = _endTime;
    emit Stake(msg.sender, totalStaking, _endTime);
}

function close(uint gameid) public returns(bool) {
    Game storage game = games[gameid];
    require(!game.closed);
    require(now > game.expireTime || (game.dealerChoice != NONE && game.playerChoice != NONE));
    uint8 result = payoff[game.dealerChoice][game.playerChoice];
    if (result == DEALERWIN) {
        require(game.dealer.send(amountWithTip(safeAdd(game.dealerValue, game.playerValue))));
    } else if (result == PLAYERWIN) {
        require(game.player.send(amountWithTip(safeAdd(game.dealerValue, game.playerValue))));
    } else if (result == DRAW) {
        require(game.dealer.send(game.dealerValue) && game.player.send(game.playerValue));
    }
    game.closed = true;
    game.result = result;
    emit CloseGame(gameid, game.dealer, game.player, result);
    return game.closed;
}

function allocate() public notLocked notAllocated onlyOwner {
    require(token.balanceOf(address(this)) == totalAllocation);
    allocations[teamReserveWallet] = teamReserveAllocation;
    allocations[lifeReserveWallet] = lifeReserveAllocation;
    allocations[finanReserveWallet] = finanReserveAllocation;
    allocations[econReserveWallet] = econReserveAllocation;
    allocations[developReserveWallet] = developReserveAllocation;
    Allocated(teamReserveWallet, teamReserveAllocation);
    Allocated(lifeReserveWallet, lifeReserveAllocation);
    Allocated(finanReserveWallet, finanReserveAllocation);
    Allocated(econReserveWallet, econReserveAllocation);
    Allocated(developReserveWallet, developReserveAllocation);
    lock();
}

function claimTokenReserveFinan() onlyTokenReserveFinance locked public {
    address reserveWallet = msg.sender;
    require(block.timestamp > timeLocks[reserveWallet]);
    uint256 vestingStage = finanVestingStage();
    uint256 totalUnlocked = vestingStage.mul(2.4 * (10 ** 7) * (10 ** 8));
    require(totalUnlocked <= allocations[finanReserveWallet]);
    require(claimed[finanReserveWallet] < totalUnlocked);
    uint256 payment = totalUnlocked.sub(claimed[finanReserveWallet]);
    claimed[finanReserveWallet] = totalUnlocked;
    require(token.transfer(reserveWallet, payment));
    Distributed(reserveWallet, payment);
}

function claimTokenReserveDevelop() onlyTokenReserveDevelop locked public {
    address reserveWallet = msg.sender;
    require(block.timestamp > timeLocks[reserveWallet]);
    require(claimed[reserveWallet] == 0);
    uint256 payment = allocations[reserveWallet];
    claimed[reserveWallet] = payment;
    require(token.transfer(reserveWallet, payment));
    Distributed(reserveWallet, payment);
}

function lifeVestingStage() public view onlyTokenReserveLife returns(uint256) {
    uint256 nowTime = block.timestamp;
    uint256 stage = (nowTime.sub(lifeReserveTimeLock)).div(2592000);
    if (stage > lifeVestingStages) {
        stage = lifeVestingStages;
    }
    return stage;
}

function finanVestingStage() public view onlyTokenReserveFinance returns(uint256) {
    uint256 nowTime = block.timestamp;
    uint256 stage = (nowTime.sub(finanReserveTimeLock)).div(2592000);
    if (stage > finanVestingStages) {
        stage = finanVestingStages;
    }
    return stage;
}

function teamVestingStage() public view onlyTeamReserve returns(uint256) {
    uint256 nowTime = block.timestamp;
    uint256 stage = (nowTime.sub(teamReserveTimeLock)).div(2592000);
    if (stage > teamVestingStages) {
        stage = teamVestingStages;
    }
    return stage;
}

function econVestingStage() public view onlyTokenReserveEcon returns(uint256) {
    uint256 nowTime = block.timestamp;
    uint256 stage = (nowTime.sub(timeLocks[econReserveWallet])).div(2592000);
    if (stage > econVestingStages) {
        stage = econVestingStages;
    }
    return stage;
}

function claimTeamReserve() onlyTeamReserve locked public {
    address reserveWallet = msg.sender;
    require(block.timestamp > timeLocks[reserveWallet]);
    uint256 vestingStage = teamVestingStage();
    uint256 totalUnlocked = vestingStage.mul(7.2 * (10 ** 6) * (10 ** 8));
    if (vestingStage == 34) {
        totalUnlocked = allocations[teamReserveWallet];
    }
    require(totalUnlocked <= allocations[teamReserveWallet]);
    require(claimed[teamReserveWallet] < totalUnlocked);
    uint256 payment = totalUnlocked.sub(claimed[teamReserveWallet]);
    claimed[teamReserveWallet] = totalUnlocked;
    require(token.transfer(teamReserveWallet, payment));
    Distributed(teamReserveWallet, payment);
}

function claimTokenReserveEcon() onlyTokenReserveEcon locked public {
    address reserveWallet = msg.sender;
    require(block.timestamp > timeLocks[reserveWallet]);
    uint256 vestingStage = econVestingStage();
    uint256 totalUnlocked;
    if (vestingStage <= 72) {
        totalUnlocked = vestingStage.mul(1200000 * (10 ** 8));
    } else { 
        totalUnlocked = ((vestingStage.sub(72)).mul(200000 * (10 ** 8))).add(86400000 * (10 ** 8));
    }
    require(totalUnlocked <= allocations[econReserveWallet]);
    require(claimed[econReserveWallet] < totalUnlocked);
    uint256 payment = totalUnlocked.sub(claimed[econReserveWallet]);
    claimed[econReserveWallet] = totalUnlocked;
    require(token.transfer(reserveWallet, payment));
    Distributed(reserveWallet, payment);
}

function claimTokenReserveLife() onlyTokenReserveLife locked public {
    address reserveWallet = msg.sender;
    require(block.timestamp > timeLocks[reserveWallet]);
    uint256 vestingStage = lifeVestingStage();
    uint256 totalUnlocked = vestingStage.mul(2.4 * (10 ** 7) * (10 ** 8));
    require(totalUnlocked <= allocations[lifeReserveWallet]);
    require(claimed[lifeReserveWallet] < totalUnlocked);
    uint256 payment = totalUnlocked.sub(claimed[lifeReserveWallet]);
    claimed[lifeReserveWallet] = totalUnlocked;
    require(token.transfer(reserveWallet, payment));
    Distributed(reserveWallet, payment);
}

function join(bytes32 _hash)
public
payable
circleIsPublic(closed)
ticketIsAffordable(ticketPrice)
returns(uint gameId) {
    require(
        counter < 40,
        "Game is full."
    );
    if (counter == 0) {
        elapsed = block.number;
        emit FirstBlock(block.number);
    }
    player[lastId][msg.sender].commit = _hash;
    if (counter == 39) {
        closed = true;
        uint temp = sub(block.number, elapsed);
        timeout = add(temp, block.number);
        emit LastBlock(timeout);
    }
    counter++;
    emit Join(counter);
    return lastId;
}

function disputePrivateDataExchange(uint256 _exchangeIdx, bytes32 _exchangeKey) external {
    require(_exchangeIdx < privateDataExchanges.length, "invalid exchange index");
    PrivateDataExchange storage exchange = privateDataExchanges[_exchangeIdx];
    require(PrivateDataExchangeState.Accepted == exchange.state, "exchange must be in accepted state");
    require(msg.sender == exchange.dataRequester, "only data requester allowed");
    require(_nowSeconds() < exchange.stateExpired, "exchange must not be expired");
    require(keccak256(abi.encodePacked(_exchangeKey)) == exchange.exchangeKeyHash, "exchange key hash must match");
    bytes32 dataKey = _exchangeKey ^ exchange.encryptedDataKey;
    bool validDataKey = keccak256(abi.encodePacked(dataKey)) == exchange.dataKeyHash;
    exchange.state = PrivateDataExchangeState.Closed;
    uint256 val = exchange.dataRequesterValue.add(exchange.passportOwnerValue);
    address cheater;
    if (validDataKey) { 
        require(exchange.passportOwner.send(val));
        cheater = exchange.dataRequester;
    } else { 
        require(exchange.dataRequester.send(val));
        cheater = exchange.passportOwner;
    }
    _decOpenPrivateDataExchangesCount();
    emit PrivateDataExchangeClosed(_exchangeIdx);
    emit PrivateDataExchangeDisputed(_exchangeIdx, !validDataKey, cheater);
}

function finishPrivateDataExchange(uint256 _exchangeIdx) external {
    require(_exchangeIdx < privateDataExchanges.length, "invalid exchange index");
    PrivateDataExchange storage exchange = privateDataExchanges[_exchangeIdx];
    require(PrivateDataExchangeState.Accepted == exchange.state, "exchange must be in accepted state");
    require(_nowSeconds() > exchange.stateExpired || msg.sender == exchange.dataRequester, "exchange must be either expired or be finished by the data requester");
    exchange.state = PrivateDataExchangeState.Closed;
    uint256 val = exchange.dataRequesterValue.add(exchange.passportOwnerValue);
    require(exchange.passportOwner.send(val));
    _decOpenPrivateDataExchangesCount();
    emit PrivateDataExchangeClosed(_exchangeIdx);
}

function timeoutPrivateDataExchange(uint256 _exchangeIdx) external {
    require(_exchangeIdx < privateDataExchanges.length, "invalid exchange index");
    PrivateDataExchange storage exchange = privateDataExchanges[_exchangeIdx];
    require(PrivateDataExchangeState.Proposed == exchange.state, "exchange must be in proposed state");
    require(msg.sender == exchange.dataRequester, "only data requester allowed");
    require(_nowSeconds() > exchange.stateExpired, "exchange must be expired");
    exchange.state = PrivateDataExchangeState.Closed;
    require(exchange.dataRequester.send(exchange.dataRequesterValue));
    _decOpenPrivateDataExchangesCount();
    emit PrivateDataExchangeClosed(_exchangeIdx);
}

function _nowSeconds() private view returns(uint256) {
    uint256 t = now;
    if (t > 150000000000000000) {
        t /= 1000000000;
    }
    return t;
}

function acceptPrivateDataExchange(uint256 _exchangeIdx, bytes32 _encryptedDataKey) external payable {
    require(_exchangeIdx < privateDataExchanges.length, "invalid exchange index");
    PrivateDataExchange storage exchange = privateDataExchanges[_exchangeIdx];
    require(msg.sender == exchange.passportOwner, "only passport owner allowed");
    require(PrivateDataExchangeState.Proposed == exchange.state, "exchange must be in proposed state");
    require(msg.value >= exchange.dataRequesterValue, "need to stake at least data requester amount");
    require(_nowSeconds() < exchange.stateExpired, "exchange state expired");
    exchange.passportOwnerValue = msg.value;
    exchange.encryptedDataKey = _encryptedDataKey;
    exchange.state = PrivateDataExchangeState.Accepted;
    exchange.stateExpired = _nowSeconds() + privateDataExchangeAcceptTimeout;
    emit PrivateDataExchangeAccepted(_exchangeIdx, exchange.dataRequester, msg.sender);
}

function fillSellOrder(uint _key) public payable {
    uint order = orderBook.get(_key);
    ORDER_TYPE orderType = ORDER_TYPE(order >> 254);
    require(orderType == ORDER_TYPE.SELL, "This is not a sell order");
    uint index = addressRegister(msg.sender);
    require(index != (order << 2) >> 224, "You cannot fill your own order");
    uint price = (order << 34) >> 145;
    uint amount = (order << 145) >> 145;
    uint orderFee = feeForOrder(price, amount);
    require(feeBalances[index] >= orderFee, "You do not have enough deposited fees to fill this order");
    uint cost = price.mul(amount).div(1 ether);
    require(msg.value == cost, "ETH sent needs to equal the cost");
    require(orderBook.remove(_key), "Map remove failed");
    addressRegistry[(order << 2) >> 224].transfer(msg.value);
    poolOwners.sendOwnership(msg.sender, amount);
    if (orderFee > 0) {
        feeBalances[index] = feeBalances[index].sub(orderFee);
        uint totalFee = orderFee.mul(2);
        totalFees = totalFees.sub(totalFee);
        feeToken.transfer(poolOwners, totalFee);
    }
    emit OrderFilled(orderType, addressRegistry[(order << 2) >> 224], msg.sender, price, amount);
}

function fillBuyOrder(uint _key) public {
    uint order = orderBook.get(_key);
    ORDER_TYPE orderType = ORDER_TYPE(order >> 254);
    require(orderType == ORDER_TYPE.BUY, "This is not a buy order");
    uint index = addressRegister(msg.sender);
    require(index != (order << 2) >> 224, "You cannot fill your own order");
    uint price = (order << 34) >> 145;
    uint amount = (order << 145) >> 145;
    uint orderFee = feeForOrder(price, amount);
    require(feeBalances[index] >= orderFee, "You do not have enough deposited fees to fill this order");
    uint cost = price.mul(amount).div(1 ether);
    require(orderBook.remove(_key), "Map remove failed");
    msg.sender.transfer(cost);
    poolOwners.sendOwnershipFrom(msg.sender, addressRegistry[(order << 2) >> 224], amount);
    if (orderFee > 0) {
        feeBalances[index] = feeBalances[index].sub(orderFee);
        uint totalFee = orderFee.mul(2);
        totalFees = totalFees.sub(totalFee);
        feeToken.transfer(poolOwners, totalFee);
    }
    emit OrderFilled(orderType, addressRegistry[(order << 2) >> 224], msg.sender, price, amount);
}

function addSellOrder(uint _price, uint _amount) public {
    require(is111bit(_price) && is111bit(_amount), "Price or amount exceeds 111 bits");
    require(_price > 0, "Price needs to be greater than 0");
    require(_amount > 0, "Amount needs to be greater than 0");
    uint orderFee = feeForOrder(_price, _amount);
    uint index = addressRegister(msg.sender);
    if (orderFee > 0) {
        require(feeBalances[index] >= orderFee, "You do not have enough deposited for fees");
        feeBalances[index] = feeBalances[index].sub(orderFee);
    }
    poolOwners.sendOwnershipFrom(msg.sender, this, _amount);
    require(
        !orderBook.insert(orderCount, (((uint(ORDER_TYPE.SELL) << 32 | index) << 111 | _price) << 111) | _amount),
        "Map replacement detected"
    );
    orderCount += 1;
    emit NewOrder(ORDER_TYPE.SELL, msg.sender, _price, _amount);
}

function removeBuyOrder(uint _key) public {
    uint order = orderBook.get(_key);
    ORDER_TYPE orderType = ORDER_TYPE(order >> 254);
    require(orderType == ORDER_TYPE.BUY, "This is not a buy order");
    uint index = addressIndex[msg.sender];
    require(index == (order << 2) >> 224, "You are not the sender of this order");
    uint price = (order << 34) >> 145;
    uint amount = (order << 145) >> 145;
    require(orderBook.remove(_key), "Map remove failed");
    uint orderFee = feeForOrder(price, amount);
    if (orderFee > 0) {
        feeBalances[index] = feeBalances[index].add(orderFee);
    }
    uint cost = price.mul(amount).div(1 ether);
    msg.sender.transfer(cost);
    emit OrderRemoved(orderType, msg.sender, price, amount);
}

