function grant(address _to, uint256 _value, uint256 _duration, uint256 _periods) public returns(bool success) {
    require(msg.sender != _to);
    require(_balancesMap[msg.sender].tokens >= _value);
    require(_balancesMap[_to].unlockLastTime == 0);
    _balancesMap[msg.sender].tokens = _balancesMap[msg.sender].tokens.sub(_value);
    if (_balancesMap[_to].index == 0) {
        UserToken memory user;
        user.index = _balancesArray.length;
        user.addr = _to;
        user.tokens = 0;
        user.unlockUnit = _value.div(_periods);
        user.unlockPeriod = _duration.mul(1 days).div(_periods); 
        user.unlockLeft = _value;
        user.unlockLastTime = now;
        _balancesMap[_to] = user;
        _balancesArray.push(_to);
    } else {
        _balancesMap[_to].unlockUnit = _value.div(_periods);
        _balancesMap[_to].unlockPeriod = _duration.mul(1 days).div(_periods); 
        _balancesMap[_to].unlockLeft = _value;
        _balancesMap[_to].unlockLastTime = now;
    }
    emit Grant(msg.sender, _to, _value);
    log(actionGrant, msg.sender, _to, _value, _duration, _periods);
    success = true;
}

function getLog(uint256 _index) public view returns(uint time, uint32 action, address from, address to, uint256 _v1, uint256 _v2, uint256 _v3) {
    require(_index < _logs.length);
    require(_index >= 0);
    LogEntry storage entry = _logs[_index];
    action = entry.action;
    time = entry.time;
    from = entry.from;
    to = entry.to;
    _v1 = entry.v1;
    _v2 = entry.v2;
    _v3 = entry.v3;
}

function transfer(address _to, uint256 _value) public returns(bool success) {
    require(!paused);
    require(msg.sender != cfoAddress);
    require(msg.sender != _to);
    if (_balancesMap[msg.sender].unlockLeft > 0) {
        UserToken storage sender = _balancesMap[msg.sender];
        uint256 diff = now.sub(sender.unlockLastTime);
        uint256 round = diff.div(sender.unlockPeriod);
        if (round > 0) {
            uint256 unlocked = sender.unlockUnit.mul(round);
            if (unlocked > sender.unlockLeft) {
                unlocked = sender.unlockLeft;
            }
            sender.unlockLeft = sender.unlockLeft.sub(unlocked);
            sender.tokens = sender.tokens.add(unlocked);
            sender.unlockLastTime = sender.unlockLastTime.add(sender.unlockPeriod.mul(round));
            emit Unlock(msg.sender, unlocked);
            log(actionUnlock, msg.sender, 0, unlocked, 0, 0);
        }
    }
    require(_balancesMap[msg.sender].tokens >= _value);
    _balancesMap[msg.sender].tokens = _balancesMap[msg.sender].tokens.sub(_value);
    uint index = _balancesMap[_to].index;
    if (index == 0) {
        UserToken memory user;
        user.index = _balancesArray.length;
        user.addr = _to;
        user.tokens = _value;
        user.unlockUnit = 0;
        user.unlockPeriod = 0;
        user.unlockLeft = 0;
        user.unlockLastTime = 0;
        _balancesMap[_to] = user;
        _balancesArray.push(_to);
    } else {
        _balancesMap[_to].tokens = _balancesMap[_to].tokens.add(_value);
    }
    emit Transfer(msg.sender, _to, _value);
    log(actionTransfer, msg.sender, _to, _value, 0, 0);
    success = true;
}

function buy(IERC20Token _connectorToken, uint256 _depositAmount, uint256 _minReturn) internal returns(uint256) {
    uint256 amount = getPurchaseReturn(_connectorToken, _depositAmount);
    require(amount != 0 && amount >= _minReturn);
    Connector storage connector = connectors[_connectorToken];
    if (connector.isVirtualBalanceEnabled)
        connector.virtualBalance = safeAdd(connector.virtualBalance, _depositAmount);
    assert(_connectorToken.transferFrom(msg.sender, this, _depositAmount));
    token.issue(msg.sender, amount);
    uint256 feeAmount = safeSub(amount, getFinalAmount(amount, 1));
    dispatchConversionEvent(_connectorToken, token, _depositAmount, amount, feeAmount);
    emit PriceDataUpdate(_connectorToken, token.totalSupply(), getConnectorBalance(_connectorToken), connector.weight);
    return amount;
}

function convertInternal(IERC20Token _fromToken, IERC20Token _toToken, uint256 _amount, uint256 _minReturn)
public
bancorNetworkOnly
conversionsAllowed
greaterThanZero(_minReturn)
returns(uint256) {
    require(_fromToken != _toToken); 
    if (_toToken == token)
        return buy(_fromToken, _amount, _minReturn);
    else if (_fromToken == token)
        return sell(_toToken, _amount, _minReturn);
    uint256 amount = getCrossConnectorReturn(_fromToken, _toToken, _amount);
    require(amount != 0 && amount >= _minReturn);
    Connector storage fromConnector = connectors[_fromToken];
    if (fromConnector.isVirtualBalanceEnabled)
        fromConnector.virtualBalance = safeAdd(fromConnector.virtualBalance, _amount);
    Connector storage toConnector = connectors[_toToken];
    if (toConnector.isVirtualBalanceEnabled)
        toConnector.virtualBalance = safeSub(toConnector.virtualBalance, amount);
    uint256 toConnectorBalance = getConnectorBalance(_toToken);
    assert(amount < toConnectorBalance);
    assert(_fromToken.transferFrom(msg.sender, this, _amount));
    assert(_toToken.transfer(msg.sender, amount));
    uint256 feeAmount = safeSub(amount, getFinalAmount(amount, 2));
    dispatchConversionEvent(_fromToken, _toToken, _amount, amount, feeAmount);
    emit PriceDataUpdate(_fromToken, token.totalSupply(), getConnectorBalance(_fromToken), fromConnector.weight);
    emit PriceDataUpdate(_toToken, token.totalSupply(), getConnectorBalance(_toToken), toConnector.weight);
    return amount;
}

function sell(IERC20Token _connectorToken, uint256 _sellAmount, uint256 _minReturn) internal returns(uint256) {
    require(_sellAmount <= token.balanceOf(msg.sender)); 
    uint256 amount = getSaleReturn(_connectorToken, _sellAmount);
    require(amount != 0 && amount >= _minReturn);
    uint256 tokenSupply = token.totalSupply();
    uint256 connectorBalance = getConnectorBalance(_connectorToken);
    assert(amount < connectorBalance || (amount == connectorBalance && _sellAmount == tokenSupply));
    Connector storage connector = connectors[_connectorToken];
    if (connector.isVirtualBalanceEnabled)
        connector.virtualBalance = safeSub(connector.virtualBalance, amount);
    token.destroy(msg.sender, _sellAmount);
    assert(_connectorToken.transfer(msg.sender, amount));
    uint256 feeAmount = safeSub(amount, getFinalAmount(amount, 1));
    dispatchConversionEvent(token, _connectorToken, _sellAmount, amount, feeAmount);
    emit PriceDataUpdate(_connectorToken, token.totalSupply(), getConnectorBalance(_connectorToken), connector.weight);
    return amount;
}

function addConnector(IERC20Token _token, uint32 _weight, bool _enableVirtualBalance)
public
ownerOnly
inactive
validAddress(_token)
notThis(_token)
validConnectorWeight(_weight) {
    require(_token != token && !connectors[_token].isSet && totalConnectorWeight + _weight <= MAX_WEIGHT); 
    connectors[_token].virtualBalance = 0;
    connectors[_token].weight = _weight;
    connectors[_token].isVirtualBalanceEnabled = _enableVirtualBalance;
    connectors[_token].isPurchaseEnabled = true;
    connectors[_token].isSet = true;
    connectorTokens.push(_token);
    totalConnectorWeight += _weight;
}

