    }
}

function setCollateralConfig(
    address _collateralType,
    uint256 _debtLimit,
    uint256 _liquidationRatio,
    uint256 _minCollateralRatio,
    uint256 _borrowRate,
    uint256 _originationFee,
    uint256 _liquidationBonus,
    uint256 _liquidationFee
) public override onlyManager {
    require(address(_collateralType) != address(0));
    require(_minCollateralRatio >= _liquidationRatio);
    if (collateralIds[_collateralType] == 0) {
        a.core().state().initializeRates(_collateralType);
        CollateralConfig memory config = CollateralConfig({
            collateralType: _collateralType,
            debtLimit: _debtLimit,
            liquidationRatio: _liquidationRatio,
            minCollateralRatio: _minCollateralRatio,
            borrowRate: _borrowRate,
            originationFee: _originationFee,
            liquidationBonus: _liquidationBonus,
            liquidationFee: _liquidationFee
        });
        numCollateralConfigs++;
        _collateralConfigs[numCollateralConfigs] = config;
        collateralIds[_collateralType] = numCollateralConfigs;
    } else {
        a.core().state().refreshCollateral(_collateralType);
        uint256 id = collateralIds[_collateralType];
        _collateralConfigs[id].collateralType = _collateralType;
        _collateralConfigs[id].debtLimit = _debtLimit;
        _collateralConfigs[id].liquidationRatio = _liquidationRatio;
        _collateralConfigs[id].minCollateralRatio = _minCollateralRatio;
        _collateralConfigs[id].borrowRate = _borrowRate;
        _collateralConfigs[id].originationFee = _originationFee;
        _collateralConfigs[id].liquidationBonus = _liquidationBonus;
        _collateralConfigs[id].liquidationFee = _liquidationFee;
    }
    emit CollateralUpdated(
        _collateralType,
        _debtLimit,
        _liquidationRatio,
        _minCollateralRatio,
        _borrowRate,
        _originationFee,
        _liquidationBonus,
        _liquidationFee
    );
}

function setCollateralBorrowRate(address _collateralType, uint256 _borrowRate) public override onlyManager {
    a.core().state().refreshCollateral(_collateralType);
    _collateralConfigs[collateralIds[_collateralType]].borrowRate = _borrowRate;
    _emitUpdateEvent(_collateralType);
}

function deposit(address payable vault, address asset, uint amount, string memory memo) public payable {
    uint safeAmount;
    if (asset == address(0)) {
        safeAmount = msg.value;
        vault.call {
            value: safeAmount
        }("");
    } else if (asset == RUNE) {
        safeAmount = amount;
        iRUNE(RUNE).transferTo(address(this), amount);
        iERC20(RUNE).burn(amount);
    } else {
        safeAmount = safeTransferFrom(asset, amount); 
        vaultAllowance[vault][asset] = vaultAllowance[vault][asset].add(safeAmount); 
    }
    emit Deposit(vault, asset, safeAmount, memo);
}

function transferOut(address payable to, address asset, uint amount, string memory memo) public payable {
    uint safeAmount;
    if (asset == address(0)) {
        safeAmount = msg.value;
        to.call {
            value: msg.value
        }(""); 
    } else {
        vaultAllowance[msg.sender][asset] = vaultAllowance[msg.sender][asset].sub(amount); 
        iERC20(asset).transfer(to, amount); 
        safeAmount = amount;
    }
    emit TransferOut(msg.sender, to, asset, safeAmount, memo);
}

function withdraw(uint256 _amount) external returns(bool success) {
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(_amount, "Withdraw amount exceeds balance!");
    payable(address(msg.sender)).transfer(_amount);
    emit Withdraw(msg.sender, _amount);
    return true;
}

function recordVotes(uint[] votes) private {
    require(kksAddress != address(0));
    if (!kks.voterExists(msg.sender)) {
        kks.createVoter(msg.sender);
    }
    for (uint i = 0; i < votes.length; i++) {
        if (kks.proposalExists(votes[i])) {
            require(kks.proposalOwner(votes[i]) != msg.sender);
            if (kks.proposalCreateTime(votes[i]) + kks.getProposalTTL() <= now) {
                continue;
            }
            require(kks.getProposalVoterVotesCount(votes[i], msg.sender) == uint(0));
            kks.addProposalVote(votes[i], msg.sender);
        }
        kks.addVoterVote(msg.sender);
    }
    kks.updateVoterTimes(msg.sender, now);
    VotesRecorded(msg.sender, votes);
}

function withdrawEther() public onlyOwner {
