function harvested(address who_, address lpTokenAddress_, uint pool_)
public
view
returns(uint value_, uint toDividends_) {
    require(stakes[who_][lpTokenAddress_].startStaking != 0, 'You dont have stake');
    if (stakes[who_][lpTokenAddress_].lastHarvest == 0) return (0, 0);
    Stake memory stake_ = stakes[who_][lpTokenAddress_];
    uint timePassed_ = block.timestamp - stake_.lastHarvest;
    uint percentDiv_ = timePassed_ < cutoff ? beforeCutoff : afterCutoff;
    uint reward_ = (stake_.amount * timePassed_ * (getRate(pool_) + stake_.boost)) / (100 * year) + stake_.bonus;
    uint toDiv_ = (reward_ * percentDiv_) / 100;
    return (reward_ - toDiv_, toDiv_);
}

function getCurrentRound() internal view returns(SaleRound) {
    require(saleRoundsSet);
    uint256 currentTime = block.timestamp;
    if (currentTime > seedRound.start && currentTime <= seedRound.end) {
        return seedRound;
    } else if (currentTime > presale.start && currentTime <= presale.end) {
        return presale;
    } else if (currentTime > crowdsaleWeek1.start && currentTime <= crowdsaleWeek1.end) {
        return crowdsaleWeek1;
    } else if (currentTime > crowdsaleWeek2.start && currentTime <= crowdsaleWeek2.end) {
        return crowdsaleWeek2;
    } else if (currentTime > crowdsaleWeek3.start && currentTime <= crowdsaleWeek3.end) {
        return crowdsaleWeek3;
    } else if (currentTime > crowdsaleWeek4.start && currentTime <= crowdsaleWeek4.end) {
        return crowdsaleWeek4;
    } else {
        revert();
    }
}

