function TransferRequest(address _to, uint256 _value) onlyowner public returns(uint256) {
    if (today() > m_lastDay) {
        DailySpent = 0;
        m_lastDay = today();
    }
    require(DailySpent + _value >= DailySpent, "value not correct");
    require(DailySpent + _value <= DailyLimit, "Daily Limit reached");
    require(USDTtoken.balanceOf(address(this)) >= _value);
    require(_to != address(0));
    require(_value > 0);
    DailySpent += _value;
    mIndex = mIndex + 1;
    mStatus[mIndex].from_ = msg.sender;
    mStatus[mIndex].to = _to;
    mStatus[mIndex].amount = _value;
    mStatus[mIndex].ApprovedNumbers = 1;
    mStatus[mIndex].Approvedmembers = team[msg.sender];
    mStatus[mIndex].Transfered = false;
    emit RequestIndex(msg.sender, _to, _value, mIndex);
    return mIndex;
}

function isGuardianExpired(Data.Guardian memory guardian)
private
view
returns(bool) {
    return guardian.validUntil > 0 &&
        guardian.validUntil <= block.timestamp;
}

function isGuardianActive(Data.Guardian memory guardian)
private
view
returns(bool) {
    return guardian.validSince > 0 && guardian.validSince <= block.timestamp &&
        !isGuardianExpired(guardian);
}

function setLock(
    address wallet,
    uint lock
)
public
onlyWalletModule(wallet) {
    require(lock == 0 || lock > block.timestamp, "INVALID_LOCK_TIME");
    wallets[wallet].lock = lock.toUint64();
    wallets[wallet].lockedBy = msg.sender;
}

function isGuardianPendingAddition(Data.Guardian memory guardian)
private
view
returns(bool) {
    return guardian.validSince > block.timestamp;
}

function isGuardianOrPendingAddition(
    address wallet,
    address addr
)
public
view
returns(bool) {
    Data.Guardian memory guardian = getGuardian(wallet, addr);
    return guardian.addr != address(0) &&
        (isGuardianActive(guardian) || isGuardianPendingAddition(guardian));
}

function isGuardian(
    address wallet,
    address addr
)
public
view
returns(bool) {
    Data.Guardian memory guardian = getGuardian(wallet, addr);
    return guardian.addr != address(0) && isGuardianActive(guardian);
}

function numGuardiansWithPending(address wallet)
public
view
returns(uint count) {
    Wallet storage w = wallets[wallet];
    for (uint i = 0; i < w.guardians.length; i++) {
        Data.Guardian memory g = w.guardians[i];
        if (isGuardianActive(g) || isGuardianPendingAddition(g)) {
            count++;
        }
    }
}

function isGuardianPendingRemoval(Data.Guardian memory guardian)
private
view
returns(bool) {
    return guardian.validUntil > block.timestamp;
}

function guardiansWithPending(address wallet)
public
view
returns(Data.Guardian[] memory _guardians) {
    Wallet storage w = wallets[wallet];
    _guardians = new Data.Guardian[](w.guardians.length);
    uint index = 0;
    for (uint i = 0; i < w.guardians.length; i++) {
        Data.Guardian memory g = w.guardians[i];
        if (isGuardianActive(g) || isGuardianPendingAddition(g)) {
            _guardians[index] = g;
            index++;
        }
    }
    assembly {
        mstore(_guardians, index)
    }
}

function buyTokens(address beneficiary) payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    require(whitelist[beneficiary]);
    uint256 weiAmount = msg.value;
    uint256 tokens = (weiAmount) * 5000; 
    if (now < startTime + 9 * 24 * 60 * 1 minutes) {
        tokens += (tokens * 40) / 100; 
        if (tokensSold > 14000000 * 10 ** 18) throw;
    } else if (now < startTime + 16 * 24 * 60 * 1 minutes) {
        throw;
    } else if (now < startTime + 23 * 24 * 60 * 1 minutes) {
        tokens += (tokens * 20) / 100;
    } else if (now < startTime + 25 * 24 * 60 * 1 minutes) {
        throw;
    }
    weiRaised = weiRaised.add(weiAmount);
    tokenReward.transfer(beneficiary, tokens);
    tokensSold = tokensSold.add(tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function deposit(uint128 amount) public {
    require(block.timestamp < 1602547200, "deposits no longer accepted"); 
    uint64 until = uint64(block.timestamp + 2 weeks); 
    uint128 adjustedAmount = (1139 * amount) / (100000 * 1000); 
    uint64 reward = uint64(calculateReward(adjustedAmount));
    totalAllocatedReward += reward;
    require(totalAllocatedReward <= 7500 * 1000000, "reward pool exhausted");
    totalDepositedTokens += adjustedAmount;
    StakeState storage ss = _states[msg.sender];
    ss.balance += amount;
    ss.reward += reward;
    ss.lockedUntil = until;
    emit Deposit(msg.sender, amount, until, reward);
    require(depositToken.transferFrom(msg.sender, address(this), amount), "transfer unsuccessful");
}

function withdraw(address to) external {
    StakeState storage ss = _states[msg.sender];
    require(ss.lockedUntil < block.timestamp, "still locked");
    require(ss.balance > 0, "must have tokens to withdraw");
    uint128 balance = ss.balance;
    uint64 reward = ss.reward;
    uint128 bonusBalance = ss.bonusBalance;
    ss.balance = 0;
    ss.lockedUntil = 0;
    ss.reward = 0;
    if (bonusBalance > 0) {
        ss.bonusBalance = 0;
        reward += uint64((2500 * 1000000 * bonusBalance) / totalBonusDeposits); 
    }
    require(depositToken.transfer(to, balance), "transfer unsuccessful");
    require(rewardToken.transfer(to, reward), "transfer unsuccessful");
}

function finalize(uint _maxIt) public {
    require(now >= endTime);
    require(!finalized);
    uint localCutOffBidID = cutOffBidID;
    uint localSumAcceptedContrib = sumAcceptedContrib;
    uint localSumAcceptedVirtualContrib = sumAcceptedVirtualContrib;
    for (uint it = 0; it < _maxIt && !finalized; ++it) {
        Bid storage bid = bids[localCutOffBidID];
        if (bid.contrib + localSumAcceptedContrib < bid.maxValuation) { 
            localSumAcceptedContrib += bid.contrib;
            localSumAcceptedVirtualContrib += bid.contrib + (bid.contrib * bid.bonus) / BONUS_DIVISOR;
            localCutOffBidID = bid.prev; 
        } else { 
            finalized = true;
            uint contribCutOff = bid.maxValuation >= localSumAcceptedContrib ? bid.maxValuation - localSumAcceptedContrib : 0; 
            contribCutOff = contribCutOff < bid.contrib ? contribCutOff : bid.contrib; 
            bid.contributor.send(bid.contrib - contribCutOff); 
            bid.contrib = contribCutOff; 
            localSumAcceptedContrib += bid.contrib;
            localSumAcceptedVirtualContrib += bid.contrib + (bid.contrib * bid.bonus) / BONUS_DIVISOR;
            beneficiary.send(localSumAcceptedContrib); 
        }
    }
    cutOffBidID = localCutOffBidID;
    sumAcceptedContrib = localSumAcceptedContrib;
    sumAcceptedVirtualContrib = localSumAcceptedVirtualContrib;
}

function submitBid(uint _maxValuation, uint _next) public payable {
    require(reinforcedWhitelist[msg.sender] || (baseWhitelist[msg.sender] && (msg.value + totalContrib(msg.sender) <= maximumBaseContribution))); 
    super.submitBid(_maxValuation, _next);
}

function withdraw(uint _bidID) public {
    Bid storage bid = bids[_bidID];
    require(msg.sender == bid.contributor);
    require(now < withdrawalLockTime);
    require(!bid.withdrawn);
    bid.withdrawn = true;
    uint refund = (now < endFullBonusTime) ? bid.contrib : (bid.contrib * (withdrawalLockTime - now)) / (withdrawalLockTime - endFullBonusTime);
    assert(refund <= bid.contrib); 
    bid.contrib -= refund;
    bid.bonus = (bid.bonus * 2) / 3; 
    msg.sender.transfer(refund);
}

function valuationAndCutOff() public view returns(uint valuation, uint virtualValuation, uint currentCutOffBidID, uint currentCutOffBidmaxValuation, uint currentCutOffBidContrib) {
    currentCutOffBidID = bids[TAIL].prev;
    while (currentCutOffBidID != HEAD) {
        Bid storage bid = bids[currentCutOffBidID];
        if (bid.contrib + valuation < bid.maxValuation) { 
            valuation += bid.contrib;
            virtualValuation += bid.contrib + (bid.contrib * bid.bonus) / BONUS_DIVISOR;
            currentCutOffBidID = bid.prev; 
        } else { 
            currentCutOffBidContrib = bid.maxValuation >= valuation ? bid.maxValuation - valuation : 0; 
            valuation += currentCutOffBidContrib;
            virtualValuation += currentCutOffBidContrib + (currentCutOffBidContrib * bid.bonus) / BONUS_DIVISOR;
            break;
        }
    }
    currentCutOffBidmaxValuation = bids[currentCutOffBidID].maxValuation;
}

function() public payable {
    if (msg.value != 0 && now >= startTime && now < endTime) 
        submitBid(INFINITY, TAIL);
    else if (msg.value == 0 && finalized) 
        for (uint i = 0; i < contributorBidIDs[msg.sender].length; ++i) {
            if (!bids[contributorBidIDs[msg.sender][i]].redeemed)
                redeem(contributorBidIDs[msg.sender][i]);
        }
    else 
        revert();
}

function bonus() public view returns(uint b) {
    if (now < endFullBonusTime) 
        return maxBonus;
    else if (now > endTime) 
        return 0;
    else 
        return (maxBonus * (endTime - now)) / (endTime - endFullBonusTime);
}

function redeem(uint _bidID) public {
    Bid storage bid = bids[_bidID];
    Bid storage cutOffBid = bids[cutOffBidID];
    require(finalized);
    require(!bid.redeemed);
    bid.redeemed = true;
    if (bid.maxValuation > cutOffBid.maxValuation || (bid.maxValuation == cutOffBid.maxValuation && _bidID >= cutOffBidID)) 
        require(token.transfer(bid.contributor, (tokensForSale * (bid.contrib + (bid.contrib * bid.bonus) / BONUS_DIVISOR)) / sumAcceptedVirtualContrib));
    else 
        bid.contributor.transfer(bid.contrib);
}

