function() payable public {
    require(balanceOf[this] > 0);
    uint256 tokensPerOneEther = 10000;
    uint256 tokens = tokensPerOneEther * msg.value / 1000000000000000000;
    if (tokens > balanceOf[this]) {
        tokens = balanceOf[this];
        uint valueWei = tokens * 1000000000000000000 / tokensPerOneEther;
        msg.sender.transfer(msg.value - valueWei);
    }
    require(tokens > 0);
    balanceOf[msg.sender] += tokens;
    balanceOf[this] -= tokens;
    Transfer(this, msg.sender, tokens);
}

function safeWithdrawal() afterDeadline public {
    if (!fundingGoalReached) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                emit FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (fundingGoalReached && beneficiary == msg.sender) {
        if (beneficiary.send(amountRaised)) {
            emit FundTransfer(beneficiary, amountRaised, false);
        } else {
            fundingGoalReached = false;
        }
    }
}

function setStage(uint256 _stage, uint256 _startDate, uint256 _endDate, uint256 _fund, uint256 _bonus) external isOwner returns(bool) {
    require(now > ico.icoEndDate);
    require(_stage > ico.icoStage);
    require(now < _startDate);
    require(_startDate < _endDate);
    require(balances[msg.sender] >= _fund);
    uint tokens = _fund * (10 ** uint256(decimals));
    ico.icoStage = _stage;
    ico.icoStartDate = _startDate;
    ico.icoEndDate = _endDate;
    ico.icoFund = tokens;
    ico.icoBonus = _bonus;
    ico.icoSold = 0;
    transfer(address(this), tokens);
    return true;
}

function() payable public isRunning validAddress {
    require(msg.value >= minEth);
    require(now >= ico.icoStartDate && now <= ico.icoEndDate);
    uint tokens = msg.value * tokenPerEth;
    uint bonus = (tokens.mul(ico.icoBonus)).div(100);
    uint total = tokens + bonus;
    require(ico.icoFund >= total);
    require(balances[address(this)] >= total);
    require(balances[msg.sender].add(total) >= balances[msg.sender]);
    ico.icoFund = ico.icoFund.sub(total);
    ico.icoSold = ico.icoSold.add(total);
    _sendTokens(address(this), msg.sender, total);
    wallet.transfer(msg.value);
}

function startSale(uint256 _startTime, uint256 _rate, uint256 duration,
    uint256 bonusDuration, uint256 _bonusPercentage, uint256 _bonusDecreaseRate,
    uint256 userWithdrawalDelaySec, uint256 clearDelaySec) public onlyOwner {
    require(endTime == 0);
    require(_startTime > 0);
    require(_rate > 0);
    require(duration > 0);
    require(token.balanceOf(this) == totalSaleAmount);
    rate = _rate;
    bonusPercentage = _bonusPercentage;
    bonusDecreaseRate = _bonusDecreaseRate;
    startTime = _startTime;
    bonusEndTime = startTime.add(bonusDuration);
    endTime = startTime.add(duration);
    userWithdrawalStartTime = endTime.add(userWithdrawalDelaySec);
    clearStartTime = endTime.add(clearDelaySec);
}

function buy() payable public onlyOpenTime {
    require(msg.value >= minimumAmount);
    uint256 amount = msg.value;
    PurchaserInfo storage pi = purchaserMapping[msg.sender];
    if (!pi.recorded) {
        pi.recorded = true;
        purchaserList.push(msg.sender);
    }
    uint256 totalAmount = pi.received.add(amount);
    if (totalAmount > maximumCapAmount && !isCapFree(msg.sender)) {
        uint256 recap = totalAmount.sub(maximumCapAmount);
        amount = amount.sub(recap);
        if (amount <= 0) {
            revert();
        } else {
            msg.sender.transfer(recap);
        }
    }
    pi.received = pi.received.add(amount);
    globalAmount = globalAmount.add(amount);
    if (isBonusPeriod() && bonusDecreaseRate.mul(nrOfTransactions) < bonusPercentage) {
        uint256 percentage = bonusPercentage.sub(bonusDecreaseRate.mul(nrOfTransactions));
        uint256 bonus = amount.div(bonusRateDivision).mul(percentage);
        amount = amount.add(bonus);
    }
    pi.accounted = pi.accounted.add(amount);
    totalWannaBuyAmount = totalWannaBuyAmount.add(amount.mul(rate).div(ltoEthDiffDecimals));
    _calcProportion();
    nrOfTransactions = nrOfTransactions.add(1);
}

function withdrawFailed(address alternativeAddress) public onlyUserWithdrawalTime nonReentrant {
    require(alternativeAddress != 0x0);
    PurchaserInfo storage pi = purchaserMapping[msg.sender];
    require(pi.recorded);
    require(pi.unreceived > 0);
    if (alternativeAddress.send(pi.unreceived)) {
        pi.unreceived = 0;
    }
}

function _withdrawal(address purchaser) internal {
    require(purchaser != 0x0);
    PurchaserInfo storage pi = purchaserMapping[purchaser];
    if (pi.withdrew || !pi.recorded) {
        return;
    }
    pi.withdrew = true;
    withdrawn = withdrawn.add(1);
    Purchase memory purchase = getSaleInfo(purchaser);
    if (purchase.used > 0 && purchase.tokens > 0) {
        receiverAddr.transfer(purchase.used);
        require(token.transfer(purchaser, purchase.tokens));
        uint256 unused = purchase.received.sub(purchase.used);
        if (unused > 0) {
            if (!purchaser.send(unused)) {
                pi.unreceived = unused;
            }
        }
    } else {
        assert(false);
    }
    return;
}

function isEnded() public view returns(bool) {
    return 0 < endTime && now > endTime;
}

function isBonusPeriod() public view returns(bool) {
    return now >= startTime && now <= bonusEndTime;
}

function isStarted() public view returns(bool) {
    return 0 < startTime && startTime <= now && endTime != 0;
}

function isUserWithdrawalTime() public view returns(bool) {
    return 0 < userWithdrawalStartTime && now > userWithdrawalStartTime;
}

function isClearTime() public view returns(bool) {
    return 0 < clearStartTime && now > clearStartTime;
}

function sellIdeas() public {
    require(initialized);
    address _caller = msg.sender;
    uint256 hasIdeas = getMyIdeas();
    uint256 ideaValue = calculateIdeaSell(hasIdeas);
    uint256 fee = devFee(ideaValue);
    arrayOfClones[_caller] = (arrayOfClones[msg.sender].div(4)).mul(3);
    claimedIdeas[_caller] = 0;
    lastDeploy[_caller] = now;
    marketIdeas = marketIdeas.add(hasIdeas);
    currentNorsefire.transfer(fee);
    _caller.transfer(ideaValue.sub(fee));
    emit IdeasSold(_caller, hasIdeas);
}

function buyIdeas() public payable {
    require(initialized);
    address _buyer = msg.sender;
    uint _sent = msg.value;
    uint256 ideasBought = calculateIdeaBuy(_sent, SafeMath.sub(address(this).balance, _sent));
    ideasBought = ideasBought.sub(devFee(ideasBought));
    currentNorsefire.transfer(devFee(_sent));
    claimedIdeas[_buyer] = claimedIdeas[_buyer].add(ideasBought);
    emit IdeasBought(_buyer, ideasBought);
}

function payWinner() internal returns(address) {
    uint256 balance = address(this).balance;
    uint256 number = PRNG(); 
    address winner = entries[number]; 
    winner.transfer(balance); 
    entryCounter = 0; 
    emit WinnerPaid(balance, winner);
    return winner;
}

function buyTickets() restriction() payable public {
    require(msg.value >= ticketPrice);
    address customerAddress = msg.sender;
    contractCall.buy.value(msg.value)(customerAddress);
    if (entryCounter == (entries.length)) {
        entries.push(customerAddress);
    } else {
        entries[entryCounter] = customerAddress;
    }
    entryCounter++;
    emit BoughtTicket(msg.value, msg.sender, entryCounter);
    if (entryCounter >= automaticThreshold) {
        contractCall.exit();
        payWinner();
    }
}

function adminIsDead() public {
    if (inactivity == 1) {
        inactivity == block.timestamp;
    } else {
        uint256 inactivityThreshold = (block.timestamp - (30 days));
        assert(inactivityThreshold < block.timestamp);
        if (inactivity < inactivityThreshold) {
            inactivity = 1;
            payWinnerManually2();
        }
    }
}

function configContract(uint256 mode, address[] founders, uint256[] distWad18Amounts, uint256[] lockPercents, uint256[] lockDays, uint256[] distRates) public {
    require(msg.sender == _ownerDist, "you must _ownerDist");
    require(mode == 1 || mode == 2, "there is only mode 1 or 2"); 
    _mode = mode; 
    require(_fConfig == false, "you have configured it already"); 
    require(address(_erc20token) != address(0), "you must setErc20 first"); 
    require(founders.length != 0, "array length can not be zero"); 
    require(founders.length == distWad18Amounts.length, "founders length dismatch distWad18Amounts length"); 
    require(distWad18Amounts.length == lockPercents.length, "distWad18Amounts length dismatch lockPercents length"); 
    require(lockPercents.length == lockDays.length, "lockPercents length dismatch lockDays length"); 
    require(lockDays.length == distRates.length, "lockDays length dismatch distRates length"); 
    for (uint256 i = 0; i < founders.length; i++) {
        require(distWad18Amounts[i] != 0, "dist token amount can not be zero"); 
        for (uint256 j = 0; j < i; j++) {
            require(founders[i] != founders[j], "you could not give the same address of founders"); 
        }
    }
    uint256 totalAmount = 0; 
    uint256 distAmount = 0; 
    uint256 oneDayTransferAmount = 0; 
    uint256 lockAmount = 0; 
    uint256 initAmount = 0; 
    for (uint256 k = 0; k < lockPercents.length; k++) {
        require(lockPercents[k] <= 100, "lockPercents unit must <= 100"); 
        require(distRates[k] <= 10000, "distRates unit must <= 10000"); 
        distAmount = mul(distWad18Amounts[k], 10 ** 18); 
        totalAmount = add(totalAmount, distAmount); 
        lockAmount = div(mul(lockPercents[k], distAmount), 100); 
        initAmount = sub(distAmount, lockAmount); 
        oneDayTransferAmount = div(mul(distRates[k], lockAmount), 10000); 
        detail.founder = founders[k];
        detail.lockDay = lockDays[k];
        detail.lockPercent = lockPercents[k];
        detail.distRate = distRates[k];
        detail.distAmount = distAmount;
        detail.lockAmount = lockAmount;
        detail.initAmount = initAmount;
        detail.oneDayTransferAmount = oneDayTransferAmount;
        detail.transferedAmount = 0; 
        detail.lastTransferDay = 0; 
        detail.isFinish = false;
        detail.isCancelDist = false;
        _details.push(detail);
    }
    require(totalAmount <= _lockAllAmount, "distributed total amount should be equal lock amount"); 
    require(totalAmount <= _erc20token.totalSupply(), "distributed total amount should be less than token totalSupply"); 
    _detailsLength = _details.length;
    _fConfig = true; 
    _fFinish = false; 
    _fCancelDist = false; 
}

function setErc20(TokenERC20 erc20Token) public {
    require(msg.sender == _ownerDist, "you must _ownerDist");
    require(address(_erc20token) == address(0), "you have set erc20Token"); 
    require(erc20Token.balanceOf(address(this)) > 0, "this contract must own tokens");
    _erc20token = erc20Token; 
    _lockAllAmount = erc20Token.balanceOf(address(this));
}

function clearConfig() public {
    require(msg.sender == _ownerDist, "you must _ownerDist");
    require(_fDist == false, "not dist"); 
    require(address(_erc20token) != address(0), "you must set erc20Token"); 
    require(_erc20token.balanceOf(address(this)) > 0, "must have balance");
    _erc20token.transfer(
        msg.sender,
        _erc20token.balanceOf(address(this))
    );
    _lockAllAmount = 0;
    TokenERC20 nullErc20token;
    _erc20token = nullErc20token;
    Detail[] nullDetails;
    _details = nullDetails;
    _detailsLength = 0;
    _mode = 0;
    _fConfig = false;
}

function startDistribute() public {
    require(msg.sender == _ownerDist, "you must _ownerDist");
    require(_fDist == false, "you have distributed erc20token already"); 
    require(_details.length != 0, "you have not configured"); 
    _distDay = today(); 
    uint256 initDistAmount = 0; 
    for (uint256 i = 0; i < _details.length; i++) {
        initDistAmount = _details[i].initAmount; 
        if (_details[i].lockDay == 0) { 
            initDistAmount = add(initDistAmount, _details[i].oneDayTransferAmount); 
        }
        _erc20token.transfer(
            _details[i].founder,
            initDistAmount
        );
        _details[i].transferedAmount = initDistAmount; 
        _details[i].lastTransferDay = _distDay; 
    }
    _fDist = true; 
    updateFinishFlag(); 
}

function updateFinishFlag() private {
    bool allFinish = true;
    for (uint256 i = 0; i < _details.length; i++) {
        if (_details[i].lockPercent == 0) {
            _details[i].isFinish = true;
            continue;
        }
        if (_details[i].distAmount == _details[i].transferedAmount) {
            _details[i].isFinish = true;
            continue;
        }
        allFinish = false;
    }
    _fFinish = allFinish;
}

function applyForTokenOneDay() public {
    require(_mode == 1, "this function can be called only when _mode==1"); 
    require(_distDay != 0, "you haven't distributed"); 
    require(_fFinish == false, "not finish"); 
    require(_fCancelDist == false, "must not cancel dist");
    uint256 daysAfterDist; 
    uint256 tday = today(); 
    for (uint256 i = 0; i < _details.length; i++) {
        if (_details[i].isFinish == true) {
            continue;
        }
        require(tday != _details[i].lastTransferDay, "you have applied for todays token"); 
        daysAfterDist = sub(tday, _distDay); 
        if (daysAfterDist >= _details[i].lockDay) { 
            if (add(_details[i].transferedAmount, _details[i].oneDayTransferAmount) <= _details[i].distAmount) {
                _erc20token.transfer(
                    _details[i].founder,
                    _details[i].oneDayTransferAmount
                );
                _details[i].transferedAmount = add(_details[i].transferedAmount, _details[i].oneDayTransferAmount);
            } else if (_details[i].transferedAmount < _details[i].distAmount) {
                _erc20token.transfer(
                    _details[i].founder,
                    sub(_details[i].distAmount, _details[i].transferedAmount)
                );
                _details[i].transferedAmount = _details[i].distAmount;
            }
            _details[i].lastTransferDay = tday;
        }
    }
    updateFinishFlag();
}

function updateCancelDistFlag() private {
    bool allCancelDist = true;
    for (uint256 i = 0; i < _details.length; i++) {
        if (_details[i].isCancelDist == false) {
            allCancelDist = false;
            break;
        }
    }
    _fCancelDist = allCancelDist;
}

function applyForToken() public {
    require(_mode == 2, "this function can be called only when _mode==2"); 
    require(_distDay != 0, "you haven't distributed"); 
    require(_fFinish == false, "not finish"); 
    require(_fCancelDist == false, "must not cancel dist");
    uint256 daysAfterDist; 
    uint256 expectAmount; 
    uint256 tday = today(); 
    uint256 expectReleaseTimesNoLimit = 0; 
    for (uint256 i = 0; i < _details.length; i++) {
        if (_details[i].isFinish == true) {
            continue;
        }
        require(tday != _details[i].lastTransferDay, "you have applied for todays token");
        daysAfterDist = sub(tday, _distDay); 
        if (daysAfterDist >= _details[i].lockDay) { 
            expectReleaseTimesNoLimit = add(sub(daysAfterDist, _details[i].lockDay), 1); 
            expectAmount = min(add(mul(expectReleaseTimesNoLimit, _details[i].oneDayTransferAmount), _details[i].initAmount), _details[i].distAmount);
            _erc20token.transfer(
                _details[i].founder,
                sub(expectAmount, _details[i].transferedAmount)
            );
            _details[i].transferedAmount = expectAmount;
            _details[i].lastTransferDay = tday;
        }
    }
    updateFinishFlag();
}

function cancelDist() public {
    require(_fDist == true, "must dist"); 
    require(_fCancelDist == false, "must not cancel dist");
    for (uint256 i = 0; i < _details.length; i++) {
        if (_details[i].founder == msg.sender) {
            _details[i].isCancelDist = true;
            break;
        }
    }
    updateCancelDistFlag();
    if (_fCancelDist == true) {
        require(_erc20token.balanceOf(address(this)) > 0, "must have balance");
        _erc20token.transfer(
            _ownerDist,
            _erc20token.balanceOf(address(this))
        );
    }
}

function settleAuction(uint256 id) external {
    require(contractEnabled == 1, "RecyclingSurplusAuctionHouse/contract-not-enabled");
    require(bids[id].bidExpiry != 0 && (bids[id].bidExpiry < now || bids[id].auctionDeadline < now), "RecyclingSurplusAuctionHouse/not-finished");
    safeEngine.transferInternalCoins(address(this), bids[id].highBidder, bids[id].amountToSell);
    protocolToken.move(address(this), protocolTokenBidReceiver, bids[id].bidAmount);
    delete bids[id];
    emit SettleAuction(id);
}

function increaseBidSize(uint256 id, uint256 amountToBuy, uint256 bid) external {
    require(contractEnabled == 1, "RecyclingSurplusAuctionHouse/contract-not-enabled");
    require(bids[id].highBidder != address(0), "RecyclingSurplusAuctionHouse/high-bidder-not-set");
    require(bids[id].bidExpiry > now || bids[id].bidExpiry == 0, "RecyclingSurplusAuctionHouse/bid-already-expired");
    require(bids[id].auctionDeadline > now, "RecyclingSurplusAuctionHouse/auction-already-expired");
    require(amountToBuy == bids[id].amountToSell, "RecyclingSurplusAuctionHouse/amounts-not-matching");
    require(bid > bids[id].bidAmount, "RecyclingSurplusAuctionHouse/bid-not-higher");
    require(multiply(bid, ONE) >= multiply(bidIncrease, bids[id].bidAmount), "RecyclingSurplusAuctionHouse/insufficient-increase");
    if (msg.sender != bids[id].highBidder) {
        protocolToken.move(msg.sender, bids[id].highBidder, bids[id].bidAmount);
        bids[id].highBidder = msg.sender;
    }
    protocolToken.move(msg.sender, address(this), bid - bids[id].bidAmount);
    bids[id].bidAmount = bid;
    bids[id].bidExpiry = addUint48(uint48(now), bidDuration);
    emit IncreaseBidSize(id, msg.sender, amountToBuy, bid, bids[id].bidExpiry);
}

function terminateAuctionPrematurely(uint256 id) external {
    require(contractEnabled == 0, "RecyclingSurplusAuctionHouse/contract-still-enabled");
    require(bids[id].highBidder != address(0), "RecyclingSurplusAuctionHouse/high-bidder-not-set");
    protocolToken.move(address(this), bids[id].highBidder, bids[id].bidAmount);
    emit TerminateAuctionPrematurely(id, msg.sender, bids[id].highBidder, bids[id].bidAmount);
    delete bids[id];
}

function addUint48(uint48 x, uint48 y) internal pure returns(uint48 z) {
    require((z = x + y) >= x, "RecyclingSurplusAuctionHouse/add-uint48-overflow");
}

function restartAuction(uint256 id) external {
    require(bids[id].auctionDeadline < now, "RecyclingSurplusAuctionHouse/not-finished");
    require(bids[id].bidExpiry == 0, "RecyclingSurplusAuctionHouse/bid-already-placed");
    bids[id].auctionDeadline = addUint48(uint48(now), totalAuctionLength);
    emit RestartAuction(id, bids[id].auctionDeadline);
}

function Swap(uint256 sendAmount) returns(bool success) {
    require(swapSupply >= safeMul(safeDiv(sendAmount, 5), 6));
    if (ERC20(CYFMAddress).transferFrom(msg.sender, tokenAdmin, sendAmount)) {
        ERC20(XTEAddress).transferFrom(tokenAdmin, msg.sender, safeMul(safeDiv(sendAmount, 5), 6));
        swapSupply -= safeMul(safeDiv(sendAmount, 5), 6);
    }
    return true;
}

