function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(NPT).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function STAKE(uint256 tokens) external {
    require(IERC20(NPT).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0)
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    if (totalStakes > 0)
        _addPayout(_stakingFee);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(NPT).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(NPT).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function execute()
external {
    uint[3] memory IDstack = stackMap[stackID];
    for (uint x = 0; x < 3; x++)
        if (IWLEV(_wlev).checkClaim(IDstack[x]) > 0)
            IRelease(_claim).release(IDstack[x]);
    stackID++;
    if (stackID > 10)
        stackID = 0;
}

function buyToken() external payable {
    require(presaleTimeEnds > block.timestamp, "Presale Finished");
    uint8 memberType = getMemberType(msg.sender);
    uint256 noOfTokens = calculateTokens(msg.value, memberType);
    if (memberType == TYPE_WHITELIST) {
        if (whitelistingSold.add(noOfTokens) <= WHITELISTING_SHARE) {
            whitelistingSold = whitelistingSold.add(noOfTokens);
        } else {
            revert("Whitelist Sale Quota has finished");
        }
    }
    if (memberType == TYPE_PRIVATEMEMBER) {
        if (privateSaleSold.add(noOfTokens) <= PRIVATE_SALE_SHARE) {
            privateSaleSold = privateSaleSold.add(noOfTokens);
        } else {
            revert("PRIVATE Sale Quota has finished");
        }
    } else {
        if (normalSaleSold.add(noOfTokens) <= NORMAL_SALE_SHARE) {
            normalSaleSold = normalSaleSold.add(noOfTokens);
        } else {
            revert("Normal Sale Quota has finished");
        }
    }
    require(getTokenBalance() >= noOfTokens, "Contract has no balance");
    token.transfer(msg.sender, noOfTokens);
    totalTokenSold = totalTokenSold.add(noOfTokens);
}

function daysToUnfreeze(address _address) public view returns(uint256) {
    require(_address != 0x0);
    uint256 _now = now;
    uint256 result = 0;
    if (_now <= creationDate + freezingPeriod[_address] * 1 days) {
        uint256 finalPeriod = (creationDate + freezingPeriod[_address] * 1 days) / 1 days;
        uint256 currePeriod = _now / 1 days;
        result = finalPeriod - currePeriod;
    }
    return result;
}

function _isTransferAllowed(address _address) view public returns(bool) {
    if (now >= creationDate + freezingPeriod[_address] * 1 days) {
        return (true);
    } else {
        return (false);
    }
}

function freezeTokens(address _beneficiary, uint256 _amount, uint256 _when) public {
    onlyAdmin();
    freeze storage _freeze = freezedTokens[_beneficiary];
    _freeze.amount = _amount;
    _freeze.when = _when;
}

function() payable external {
    uint256 marketingPerc = msg.value.mul(5).div(100);
    marketingAddress.transfer(marketingPerc);
    if (deposited[msg.sender] != 0) {
        address investor = msg.sender;
        uint256 depositsPercents = deposited[msg.sender].mul(5).div(100).mul(block.number - blocklock[msg.sender]).div(5900);
        investor.transfer(depositsPercents);
        withdrew[msg.sender] += depositsPercents;
        totalWithdrewWei = totalWithdrewWei.add(depositsPercents);
    }
    address referrer = bytesToAddress(msg.data);
    uint256 refPerc = msg.value.mul(5).div(100);
    if (referrer > 0x0 && referrer != msg.sender) {
        referrer.transfer(refPerc);
        refearned[referrer] += refPerc;
    }
    blocklock[msg.sender] = block.number;
    deposited[msg.sender] += msg.value;
    totalDepositedWei = totalDepositedWei.add(msg.value);
}

function distribute() external {
    require(distributing == true);
    require(checkAgentPercentage() == true);
    require(getDistributionAmount() > 0);
    for (uint256 i = 0; i < agents.length; i++) {
        uint256 amount = getAgentDistributionAmount(i);
        if (amount > 0) {
            require(token.transfer(agents[i].agent, amount));
        }
    }
    lastDistributionTimestamp = block.timestamp;
}

function getElapsedTime() public view returns(uint256) {
    require(block.timestamp >= lastDistributionTimestamp);
    return (block.timestamp - lastDistributionTimestamp);
}

function transferSgrToSgnHolder(address _to, uint256 _value) external only(_SgnToSgrExchangeInitiator_) {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    sgrTokenManager.uponTransferSgrToSgnHolder(_to, _value);
    _transfer(SGR_MINTED_FOR_SGN_HOLDERS, _to, _value);
    sgrTokenManager.afterTransferSgrToSgnHolder(_to, _value);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    if (_to == address(this)) {
        uint256 amount = sgrTokenManager.exchangeSgrForEth(msg.sender, _value);
        _burn(msg.sender, _value);
        msg.sender.transfer(amount);
        return sgrTokenManager.afterExchangeSgrForEth(msg.sender, _value, amount);
    }
    sgrTokenManager.uponTransfer(msg.sender, _to, _value);
    bool transferResult = super.transfer(_to, _value);
    return sgrTokenManager.afterTransfer(msg.sender, _to, _value, transferResult);
}

function exchange() external payable {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    uint256 amount = sgrTokenManager.exchangeEthForSgr(msg.sender, msg.value);
    _mint(msg.sender, amount);
    sgrTokenManager.afterExchangeEthForSgr(msg.sender, msg.value, amount);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    require(_to != address(this), "custodian-transfer of SGR into this contract is illegal");
    sgrTokenManager.uponTransferFrom(msg.sender, _from, _to, _value);
    bool transferFromResult = super.transferFrom(_from, _to, _value);
    return sgrTokenManager.afterTransferFrom(msg.sender, _from, _to, _value, transferFromResult);
}

function mintSgrForSgnHolders(uint256 _value) external only(_IMintManager_) {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    sgrTokenManager.uponMintSgrForSgnHolders(_value);
    _mint(SGR_MINTED_FOR_SGN_HOLDERS, _value);
    sgrTokenManager.afterMintSgrForSgnHolders(_value);
}

function() external payable {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    uint256 amount = sgrTokenManager.exchangeEthForSgr(msg.sender, msg.value);
    _mint(msg.sender, amount);
    sgrTokenManager.afterExchangeEthForSgr(msg.sender, msg.value, amount);
}

function init(address _sgaToSGRTokenExchangeAddress, uint256 _sgaToSGRTokenExchangeSGRSupply) external onlyIfNotInitialized only(_SGAToSGRInitializer_) {
    require(_sgaToSGRTokenExchangeAddress != address(0), "SGA to SGR token exchange address is illegal");
