constructor(uint256 _openingTimePeriodOne, uint256 _closingTimePeriodOne, uint256 _openingTimePeriodTwo, uint256 _closingTimePeriodTwo, uint256 _bonusDeliverTime,
    uint256 _rate, uint256 _bonusRatePrivateSale, uint256 _bonusRatePeriodOne, uint256 _bonusRatePeriodTwo,
    address _wallet, ERC20 _token, uint256 _decimals, uint256 _tokenUnsold, uint256 _bonusUnsold) public {
    require(_wallet != address(0));
    require(_token != address(0));
    require(_openingTimePeriodOne >= block.timestamp);
    require(_closingTimePeriodOne >= _openingTimePeriodOne);
    require(_openingTimePeriodTwo >= _closingTimePeriodOne);
    require(_closingTimePeriodTwo >= _openingTimePeriodTwo);
    wallet = _wallet;
    token = _token;
    openingTimePeriodOne = _openingTimePeriodOne;
    closingTimePeriodOne = _closingTimePeriodOne;
    openingTimePeriodTwo = _openingTimePeriodTwo;
    closingTimePeriodTwo = _closingTimePeriodTwo;
    bonusDeliverTime = _bonusDeliverTime;
    rate = _rate;
    bonusRatePrivateSale = _bonusRatePrivateSale;
    bonusRatePeriodOne = _bonusRatePeriodOne;
    bonusRatePeriodTwo = _bonusRatePeriodTwo;
    tokenUnsold = _tokenUnsold;
    bonusUnsold = _bonusUnsold;
    decimals = _decimals;
}

function deliverBonus() public onlyOwner {
    require(bonusDeliverTime <= block.timestamp);
    for (uint i = 0; i < buyerList.length; i++) {
        uint256 amount = buyerBonus[buyerList[i]];
        token.transfer(buyerList[i], amount);
        buyerBonus[buyerList[i]] = 0;
    }
}

function isClosed() public view returns(bool) {
    return block.timestamp > closingTimePeriodTwo;
}

function _getTokenBonus(uint256 _weiAmount) internal view returns(uint256) {
    uint256 bonusRate = 0;
    if (block.timestamp > openingTimePeriodOne && block.timestamp < closingTimePeriodOne) {
        bonusRate = bonusRatePeriodOne;
    } else if (block.timestamp > openingTimePeriodTwo && block.timestamp < closingTimePeriodTwo) {
        bonusRate = bonusRatePeriodTwo;
    }
    return _weiAmount.mul(10 ** uint256(decimals)).div(1 ether).mul(bonusRate);
}

function returnToken() external onlyOwner {
    require(block.timestamp > closingTimePeriodTwo);
    require(tokenUnsold > 0);
    token.transfer(wallet, tokenUnsold);
    tokenUnsold = tokenUnsold.sub(tokenUnsold);
}

function isOpened() public view returns(bool) {
    return (block.timestamp < closingTimePeriodOne && block.timestamp > openingTimePeriodOne) || (block.timestamp < closingTimePeriodTwo && block.timestamp > openingTimePeriodTwo);
}

function returnBonus() external onlyOwner {
    require(block.timestamp > bonusDeliverTime);
    require(bonusUnsold > 0);
    token.transfer(wallet, bonusUnsold);
    bonusUnsold = bonusUnsold.sub(bonusUnsold);
}

function buyTokens(address _beneficiary) public payable {
    uint256 weiAmount = msg.value;
    _preValidatePurchase(_beneficiary, weiAmount);
    uint256 tokens = _getTokenAmount(weiAmount);
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        weiAmount,
        tokens
    );
    uint256 bonus = _getTokenBonus(weiAmount);
    _addBonus(_beneficiary, bonus);
    bonusUnsold = bonusUnsold.sub(bonus);
    emit TokenBonus(
        msg.sender,
        _beneficiary,
        bonus
    );
    _forwardFunds();
}

function _deliverTokens(address _beneficiary, uint256 _tokenAmount) internal {
    token.transfer(_beneficiary, _tokenAmount);
    tokenUnsold = tokenUnsold.sub(_tokenAmount);
}

function privateCrowdsale(address _beneficiary, uint256 _ethAmount) external onlyOwner {
    _preValidatePurchase(_beneficiary, _ethAmount);
    uint256 tokens = _getTokenAmount(_ethAmount);
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        _ethAmount,
        tokens
    );
    uint256 bonus = _ethAmount.mul(10 ** uint256(decimals)).div(1 ether).mul(bonusRatePrivateSale);
    _addBonus(_beneficiary, bonus);
    bonusUnsold = bonusUnsold.sub(bonus);
    emit TokenBonus(
        msg.sender,
        _beneficiary,
        bonus
    );
}

function getLockAmount(address myaddress) public view returns(uint256 lockSum) {
    uint256 lockAmount = 0;
    for (uint32 i = 0; i < addressTimeLock[myaddress].lockList.length; i++) {
        if (addressTimeLock[myaddress].lockList[i].time > now) {
            lockAmount += addressTimeLock[myaddress].lockList[i].amount;
        }
    }
    return lockAmount;
}

function transferWithLock(address _to, uint256 _value, uint256 _lockValue, uint32 _lockTime) public whenNotPaused {
    if (lockAdminList[msg.sender] != true) {
        return;
    }
    assert(_lockTime > now);
    assert(_lockValue > 0 && _lockValue <= _value);
    transfer(_to, _value);
    bool needNewLock = true;
    for (uint32 i = 0; i < addressTimeLock[_to].lockList.length; i++) {
        if (addressTimeLock[_to].lockList[i].time < now) {
            addressTimeLock[_to].lockList[i].time = _lockTime;
            addressTimeLock[_to].lockList[i].amount = _lockValue;
            emit TransferWithLockEvt(msg.sender, _to, _value, _lockValue, _lockTime);
            needNewLock = false;
            break;
        }
    }
    if (needNewLock == true) {
        addressTimeLock[_to].lockList.length++;
        addressTimeLock[_to].lockList[(addressTimeLock[_to].lockList.length - 1)].time = _lockTime;
        addressTimeLock[_to].lockList[(addressTimeLock[_to].lockList.length - 1)].amount = _lockValue;
        emit TransferWithLockEvt(msg.sender, _to, _value, _lockValue, _lockTime);
    }
}

function unlock() public returns(bool) {
    uint8 step = unlockStep;
    bool success = false;
    while (step < TOTAL_LOCKS) {
        Lock memory lock = locks[step];
        if (now < lock.releaseDate) {
            break;
        }
        require(SQR_TOKEN.transfer(lock.receiver, lock.amount), 'Transfer failed');
        delete locks[step];
        emit Released(step, lock.releaseDate, lock.receiver, lock.amount);
        success = true;
        step++;
    }
    unlockStep = step;
    return success;
}

function recoverTokens(ERC20Interface _token) public returns(bool) {
    if (_token == SQR_TOKEN && (now < JUL_15_2020 || unlockStep != TOTAL_LOCKS)) {
        return false;
    }
    return _token.transfer(PLATFORM_WALLET, _token.balanceOf(this));
}

function() payable public {
    require(!crowdsaleClosed);
    uint amount = msg.value;
    balanceOf[msg.sender] += amount;
    amountRaised += amount;
    uint price = priceT1;
    if (startDate + 7 days <= now)
        price = priceT4;
    else if (startDate + 14 days <= now)
        price = priceT3;
    else if (startDate + 90 days <= now)
        price = priceT2;
    tokenReward.transfer(msg.sender, amount / price * 1 ether);
    emit FundTransfer(msg.sender, amount, true);
}

function sellTokensForEth(
    address _buyer,
    uint256 _amountWei
) ifNotPaused internal {
    if (whitelistEnabled) require(whitelist.isAllowed(_buyer));
    require(startTime <= now && now <= endTime);
    require(_amountWei >= minPaymentWei);
    require(totalWeiReceived < maxCapWei);
    uint256 newTotalReceived = totalWeiReceived.add(_amountWei);
    if (newTotalReceived > maxCapWei) {
        uint refundWei = newTotalReceived.sub(maxCapWei);
        _buyer.transfer(refundWei);
        _amountWei = _amountWei.sub(refundWei);
    }
    uint tokensE18 = weiToTokens(_amountWei);
    token.sell(_buyer, tokensE18);
    totalTokensSold = totalTokensSold.add(tokensE18);
    totalWeiReceived = totalWeiReceived.add(_amountWei);
    buyerToSentWei[_buyer] = buyerToSentWei[_buyer].add(_amountWei);
    ReceiveEthEvent(_buyer, _amountWei);
    uint bsTokens = totalTokensSold.mul(75).div(10000);
    token.sell(bsWallet, bsTokens);
    notifySale(_amountWei, tokensE18);
}

function isFinishedSuccessfully() public view returns(bool) {
    return now >= endTime && totalWeiReceived >= minCapWei;
}

function canWithdraw() public view returns(bool) {
    return totalWeiReceived >= minCapWei || now > refundDeadlineTime;
}

function canRefund() public view returns(bool) {
    return totalWeiReceived < minCapWei && endTime < now && now <= refundDeadlineTime;
}

function withdrawRewardsTokens(address _to, uint256 _amount) public {
    require(_to == owner);
    require(_amount <= YFMSLockedRewards);
    require(now.sub(unlockDateRewards) >= 7 days);
    YFMSLockedRewards = YFMSLockedRewards.sub(_amount);
    YFMSToken.transfer(_to, _amount);
}

function withdrawDevTokens(address _to, uint256 _amount) public {
    require(_to == owner);
    require(_amount <= YFMSLockedDev);
    require(now.sub(unlockDateDev) >= 21 days);
    YFMSLockedDev = YFMSLockedDev.sub(_amount);
    YFMSToken.transfer(_to, _amount);
}

function release() public onlyOwner {
    require(block.timestamp >= releaseTimes[releaseCounter]);
    require(releaseCounter < 20);
    balances[owner] = balances[owner] + _releaseAmount;
    emit Transfer(address(0), owner, _releaseAmount);
    releaseCounter = releaseCounter + 1;
}

function() public payable stopInEmergency {
    require(msg.value >= price);
    uint tokens = msg.value / price;
    require(token.balanceOf(this) >= tokens);
    tokensSoldTotal = tokensSoldTotal.add(tokens);
    if (token.balanceOf(msg.sender) == 0) investorCount++;
    weiRaisedTotal = weiRaisedTotal.add(msg.value);
    token.transfer(msg.sender, tokens);
    uint reservePie = msg.value.div(10);
    uint beneficiaryPie = msg.value.sub(reservePie);
    reserve.transfer(reservePie);
    beneficiary.transfer(beneficiaryPie);
    emit NewContribution(msg.sender, tokens, msg.value);
}

function withdraw() external {
    require(_stakers[msg.sender].amount > 0, "there is no staked amount");
    require(_stakers[msg.sender].lockedtime < block.timestamp, "not ready to withdraw");
    _token.transfer(msg.sender, _stakers[msg.sender].amount);
    _stakers[msg.sender] = staker(0, 0, 0);
}

function stake(uint256 amount, uint256 stakestep) external {
    require(_stakers[msg.sender].amount == 0, "already stake exist");
    require(amount != 0, "amount must not 0");
    require(times[stakestep] != 0, "lockedtime must not 0");
    _token.transferFrom(msg.sender, address(this), amount);
    uint256 lockBalance = amount.mul(rates[stakestep].add(100)).div(100);
    lockedBalance = lockedBalance.add(lockBalance);
    require(lockedBalance < _token.balanceOf(address(this)), "Stake : staking is full");
    _stakers[msg.sender] = staker(lockBalance, block.timestamp.add(times[stakestep]), rates[stakestep]);
    emit Stake(msg.sender, lockBalance, block.timestamp.add(times[stakestep]));
}

function buyforstakingwithexactEHTforToken(uint256 stakestep, uint256 tokenAmount) external payable {
    lockedBalance = lockedBalance.add(tokenAmount);
    require(lockedBalance < _token.balanceOf(address(this)), "Stake : staking is full");
    _stakers[msg.sender] = staker(tokenAmount, block.timestamp.add(times[stakestep]), rates[stakestep]);
    payable(owner()).transfer(msg.value);
    emit Stake(msg.sender, tokenAmount, block.timestamp.add(times[stakestep]));
}

function getlocktime(address a) external view returns(uint256) {
    if (block.timestamp > _stakers[a].lockedtime)
        return 0;
    return _stakers[a].lockedtime.sub(block.timestamp);
}

function buyforstakingwithexactUsdtforToken(uint256 stakestep, uint256 amount, uint256 tokenAmount) external {
