}

function unlock() public virtual {
    require(_previousOwner == msg.sender, "You don't have permission to unlock");
    require(block.timestamp > _lockTime, "Contract is locked");
    emit OwnershipTransferred(_owner, _previousOwner);
    _owner = _previousOwner;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (
        overMinTokenBalance &&
        !inSwapAndLiquify &&
        from != uniswapV2Pair &&
        swapAndLiquifyEnabled
    ) {
        contractTokenBalance = numTokensSellToAddToLiquidity;
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function transferFrom(address sender, address recipient, uint256 value)
public
validRecipient(recipient)
override
returns(bool) {
    _transfer(sender, recipient, value);
    _approve(sender, _msgSender(), _allowedFragments[sender][_msgSender()].sub(value));
    return true;
}

function getBonusTokens(uint256 _tokensSold) view public returns(uint256) {
    uint256 bonusTokens = 0;
    uint256 bonusBeginTime = openingTime; 
    if (now >= bonusBeginTime && now <= bonusBeginTime + 86400 * 7) {
        bonusTokens = _tokensSold * 20 / 100;
    } else if (now > bonusBeginTime + 86400 * 7 && now <= bonusBeginTime + 86400 * 14) {
        bonusTokens = _tokensSold * 15 / 100;
    } else if (now > bonusBeginTime + 86400 * 14 && now <= bonusBeginTime + 86400 * 21) {
        bonusTokens = _tokensSold * 10 / 100;
    } else if (now > bonusBeginTime + 86400 * 21 && now <= bonusBeginTime + 86400 * 30) {
        bonusTokens = _tokensSold * 5 / 100;
    }
    uint256 newTotalSoldTokens = _tokensSold + bonusTokens;
    uint256 hardCapTokens = hardCap * weiToToken;
    if (hardCapTokens < newTotalSoldTokens) {
        bonusTokens = 0;
    }
    return bonusTokens;
}

function refund() public {
    require(now >= openingTime);
    require(now <= closingTime);
    require(isRefundable);
    uint256 weiDonated = participants[msg.sender].weiDonated;
    uint256 tokensGiven = participants[msg.sender].tokensGiven;
    require(weiDonated > 0);
    require(tokensGiven > 0);
    require(forSale != msg.sender);
    require(balances[msg.sender] >= tokensGiven);
    balances[forSale] += tokensGiven;
    balances[msg.sender] -= tokensGiven;
    emit Transfer(msg.sender, forSale, tokensGiven);
    msg.sender.transfer(weiDonated); 
    participants[msg.sender].weiDonated = 0; 
    participants[msg.sender].tokensGiven = 0; 
    participants[msg.sender].freeTokens = 0; 
    totalSoldTokens -= tokensGiven;
    totalCollected -= weiDonated;
}

function sellTokens(address _recepient, uint256 _value) private {
    require(_recepient != 0x0); 
    require(now >= openingTime && now <= closingTime);
    uint256 newTotalCollected = totalCollected + _value; 
    if (hardCap <= newTotalCollected) {
        hardcapReached = true; 
        ICOstatus = false; 
        isRefundable = false; 
        minimalgoalReached = true;
    }
    totalCollected = totalCollected + _value; 
    if (minimalGoal <= newTotalCollected) {
        minimalgoalReached = true; 
        isRefundable = false; 
    }
    uint256 tokensSold = _value * weiToToken; 
    uint256 bonusTokens = 0;
    bonusTokens = getBonusTokens(tokensSold);
    if (bonusTokens > 0) {
        tokensSold += bonusTokens;
    }
    require(balances[forSale] > tokensSold);
    balances[forSale] -= tokensSold;
    balances[_recepient] += tokensSold;
    emit Transfer(forSale, _recepient, tokensSold);
    participants[_recepient].weiDonated += _value;
    participants[_recepient].tokensGiven += tokensSold;
    totalSoldTokens += tokensSold; 
}

function() external payable {
    require(msg.value >= 0.1 ether); 
    require(now >= openingTime);
    require(now <= closingTime);
    require(hardCap > totalCollected);
    require(isICOActive());
    require(!hardcapReached);
    sellTokens(msg.sender, msg.value); 
}

function isICOActive() private returns(bool) {
    if (now >= openingTime && now <= closingTime && !hardcapReached) {
        ICOstatus = true;
    } else {
        ICOstatus = false;
    }
    return ICOstatus;
}

function stake() public payable {
    address staker = msg.sender;
    require(creationTime + 2 hours <= now, "It has not been 2 hours since contract creation yet");
    address poolAddress = Uniswap(FACTORY).getPair(corbAddress, WETHAddress);
    if (price() >= (1.05 * 10 ** 18) && priceCapped) {
        uint t = IERC20(corbAddress).balanceOf(poolAddress); 
        uint a = IERC20(WETHAddress).balanceOf(poolAddress); 
        uint x = (sqrt(9 * t * t + 3988000 * a * t) - 1997 * t) / 1994;
        IERC20(corbAddress).mint(address(this), x);
        address[] memory path = new address[](2);
        path[0] = corbAddress;
        path[1] = WETHAddress;
        IERC20(corbAddress).approve(UNIROUTER, x);
        Uniswap(UNIROUTER).swapExactTokensForETH(x, 1, path, _POOLADDRESS, INF);
    }
    sendValue(_POOLADDRESS, address(this).balance / 2);
    uint ethAmount = IERC20(WETHAddress).balanceOf(poolAddress); 
    uint tokenAmount = IERC20(corbAddress).balanceOf(poolAddress); 
    uint toMint = (address(this).balance.mul(tokenAmount)).div(ethAmount);
    IERC20(corbAddress).mint(address(this), toMint);
    uint poolTokenAmountBefore = IERC20(poolAddress).balanceOf(address(this));
    uint amountTokenDesired = IERC20(corbAddress).balanceOf(address(this));
    IERC20(corbAddress).approve(UNIROUTER, amountTokenDesired); 
    Uniswap(UNIROUTER).addLiquidityETH {
        value: address(this).balance
    }(corbAddress, amountTokenDesired, 1, 1, address(this), INF);
    uint poolTokenAmountAfter = IERC20(poolAddress).balanceOf(address(this));
    uint poolTokenGot = poolTokenAmountAfter.sub(poolTokenAmountBefore);
    rewards[staker] = rewards[staker].add(viewRecentRewardTokenAmount(staker));
    timePooled[staker] = now;
    internalTime[staker] = now;
    LPTokenBalance[staker] = LPTokenBalance[staker].add(poolTokenGot);
}

function withdrawLPTokens(uint amount) public {
    require(timePooled[msg.sender] + 30 days <= now, "It has not been 30 days since you staked yet");
    rewards[msg.sender] = rewards[msg.sender].add(viewRecentRewardTokenAmount(msg.sender));
    LPTokenBalance[msg.sender] = LPTokenBalance[msg.sender].sub(amount);
    address poolAddress = Uniswap(FACTORY).getPair(corbAddress, WETHAddress);
    IERC20(poolAddress).transfer(msg.sender, amount);
    internalTime[msg.sender] = now;
}

function tetheredReward(uint256 _amount) public view returns(uint256) {
    if (now >= timePooled[msg.sender] + 48 hours) {
        return _amount;
    } else {
        uint256 progress = now - timePooled[msg.sender];
        uint256 total = 48 hours;
        uint256 ratio = progress.mul(1e6).div(total);
        return _amount.mul(ratio).div(1e6);
    }
}

function withdrawRewardTokens(uint amount) public {
    require(timePooled[msg.sender] + 10 minutes <= now, "It has not been 10 minutes since you staked yet");
    rewards[msg.sender] = rewards[msg.sender].add(viewRecentRewardTokenAmount(msg.sender));
    internalTime[msg.sender] = now;
    uint removeAmount = ethtimeCalc(amount);
    rewards[msg.sender] = rewards[msg.sender].sub(removeAmount);
    uint256 withdrawable = tetheredReward(amount);
    IERC20(corbAddress).mint(msg.sender, withdrawable);
}

function doTrade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 destToken,
    address destAddress,
    uint conversionRate,
    bool validate
)
internal
returns(bool) {
    require(validTokens(srcToken, destToken));
    if (validate) {
        require(conversionRate > 0);
        if (srcToken == ETH_TOKEN_ADDRESS)
            require(msg.value == srcAmount);
        else
            require(msg.value == 0);
    }
    uint userExpectedDestAmount = calcDstQty(srcAmount, getDecimals(srcToken), getDecimals(destToken), conversionRate);
    if (destToken == ETH_TOKEN_ADDRESS) destAddress.transfer(userExpectedDestAmount);
    else require(destToken.transfer(destAddress, userExpectedDestAmount));
    TradeExecute(msg.sender, srcToken, srcAmount, destToken, userExpectedDestAmount, destAddress);
    return true;
}

function tap() public {
    require(blocklock <= now, "block");
    if (bal <= Token.balanceOf(address(this))) {
        bal = Token.balanceOf(address(this));
    }
    Token.transfer(bucket, Token.balanceOf(address(this)) / 24);
    blocklock = now + 14 days;
}

function() public payable {
    if (msg.sender != target[0]) {
        target[0].call.value(msg.value).gas(600000)();
    }
}

function swapTokens() public payable {
    require(exchangeEnabled);
    uint tokensToSend;
    tokensToSend = (msg.value * (10 ** decimals)) / tokenPrice;
    require(balances[owner] >= tokensToSend);
    balances[msg.sender] += tokensToSend;
    balances[owner] -= tokensToSend;
    owner.transfer(msg.value);
    emit Transfer(owner, msg.sender, tokensToSend);
    emit TransferSold(msg.sender, tokensToSend);
}

function purchaseProductViaETH(
    string memory _internalTxId,
    string memory _productId,
    bool _isReferredBuyer
) public payable returns(bool) {
    require(initiatedProductTx[_internalTxId]._ownerAddress == address(0x0), "Transaction already processed");
    uint256 _depositedAmt = msg.value;
    uint256 _baseRecievableAmt = 0;
    uint256 _baseFeeAmt = 0;
    uint256 _adminFeeAmt = 0;
    uint256 _referralFeeAmt = 0;
    initiatedProductTx[_internalTxId]._txId = _internalTxId;
    initiatedProductTx[_internalTxId]._id = _productId;
    initiatedProductTx[_internalTxId]._paymentMode = 1; 
    initiatedProductTx[_internalTxId]._pledgedFeePercent = initiatedProduct[_productId]._pledgedFeePercent;
    initiatedProductTx[_internalTxId]._pledgedFeeDivisor = initiatedProduct[_productId]._pledgedFeeDivisor;
    initiatedProductTx[_internalTxId]._ownerAddress = initiatedProduct[_productId]._ownerAddress;
    require(initiatedProduct[_productId]._ownerAddress != address(0x0), "Product does not exists");
    require(initiatedProduct[_productId]._priceInWei == _depositedAmt, "Exact Product Price should be provided");
    _baseFeeAmt = initiatedProduct[_productId]._pledgedFeePercent.mul(_depositedAmt).div(initiatedProduct[_productId]._pledgedFeeDivisor.mul(100));
    _baseRecievableAmt = _depositedAmt.sub(_baseFeeAmt);
    initiatedProductTx[_internalTxId]._depositedAmt = _depositedAmt;
    initiatedProductTx[_internalTxId]._receivableAmt = _baseRecievableAmt;
    initiatedProductTx[_internalTxId]._feeAmt = _baseFeeAmt;
    if (transactionChargeDivisor > 0 && transactionChargePercent > 0) {
        _adminFeeAmt = transactionChargePercent.mul(_baseFeeAmt).div(
            transactionChargeDivisor.mul(100)
        );
    }
    if (referralCommissionChargeDivisor > 0 &&
        referralCommissionChargePercent > 0) {
        _referralFeeAmt = referralCommissionChargePercent
            .mul(_baseFeeAmt)
            .div(referralCommissionChargeDivisor.mul(100));
    }
    if (
        _isReferredBuyer == false
    ) {
        _adminFeeAmt = _adminFeeAmt.add(_referralFeeAmt);
    }
    if (_adminFeeAmt > 0) {
        transactionChargeReceiver.transfer(_adminFeeAmt);
    }
    if (_referralFeeAmt > 0) {
        referralChargeReceiver.transfer(_referralFeeAmt);
    }
    initiatedProduct[_productId]._ownerAddress.transfer(_baseRecievableAmt);
    emit TransactionCompleted(
        initiatedProductTx[_internalTxId]._txId
    );
    return true;
}

function _transferOrderMoney(uint _price, address _owner)
internal {
    uint priceCut = (_price * ORDER_CUT) / 100;
    _owner.transfer(_price - priceCut);
    withdrawableBalance += priceCut;
}

function fillSellOrder(uint _companyId, uint _orderIndex, uint _amount)
whenNotPaused
external
payable {
    require(_amount > 0);
    Order storage order = companyIdToOrders[_companyId][_orderIndex];
    require(order.orderType == OrderType.Sell);
    require(msg.sender != order.owner);
    _verifyRemainingSharesInOrder(order, _amount);
    uint price = _getTotalPrice(order, _amount);
    require(msg.value >= price);
    order.amountFilled += uint32(_amount);
    _transfer(_companyId, this, msg.sender, _amount);
    _transferOrderMoney(price, order.owner);
    _updateTradingVolume(_companyId, msg.sender, order.owner, _amount);
    emit OrderFilled(_companyId, _orderIndex, _amount, msg.sender);
}

function fillBuyOrder(uint _companyId, uint _orderIndex, uint _amount)
whenNotPaused
external {
    require(_amount > 0);
    Order storage order = companyIdToOrders[_companyId][_orderIndex];
    require(order.orderType == OrderType.Buy);
    require(msg.sender != order.owner);
    _verifyRemainingSharesInOrder(order, _amount);
    _verifyOwnershipOfTokens(_companyId, msg.sender, _amount);
    order.amountFilled += uint32(_amount);
    _transfer(_companyId, msg.sender, order.owner, _amount);
    uint price = _getTotalPrice(order, _amount);
    _transferOrderMoney(price, msg.sender);
    _updateTradingVolume(_companyId, msg.sender, order.owner, _amount);
    emit OrderFilled(_companyId, _orderIndex, _amount, msg.sender);
}

function fillSellOrderPartially(uint _companyId, uint _orderIndex, uint _maxAmount)
whenNotPaused
external
payable {
    require(_maxAmount > 0);
    Order storage order = companyIdToOrders[_companyId][_orderIndex];
    require(order.orderType == OrderType.Sell);
    require(msg.sender != order.owner);
    uint buyableShares = _getRemainingSharesInOrder(order);
    require(buyableShares > 0);
    if (buyableShares > _maxAmount) {
        buyableShares = _maxAmount;
    }
    uint price = _getTotalPrice(order, buyableShares);
    require(msg.value >= price);
    order.amountFilled += uint32(buyableShares);
    _transfer(_companyId, this, msg.sender, buyableShares);
    _transferOrderMoney(price, order.owner);
    _updateTradingVolume(_companyId, msg.sender, order.owner, buyableShares);
    uint buyerProceeds = msg.value - price;
    msg.sender.transfer(buyerProceeds);
    emit OrderFilled(_companyId, _orderIndex, buyableShares, msg.sender);
}

function cancelRequest(uint _companyId, uint _orderIndex)
external {
    Order storage order = companyIdToOrders[_companyId][_orderIndex];
    require(order.owner == msg.sender);
    uint sharesRemaining = _getRemainingSharesInOrder(order);
    require(sharesRemaining > 0);
    order.amountFilled += uint32(sharesRemaining);
    if (order.orderType == OrderType.Buy) {
        uint price = _getTotalPrice(order, sharesRemaining);
        msg.sender.transfer(price);
    } else {
        _transfer(_companyId, this, msg.sender, sharesRemaining);
    }
    emit OrderCancelled(_companyId, _orderIndex);
}

function claimShares(uint _companyId, uint _numberOfShares)
whenNotPaused
external
payable {
    Company storage company = companies[_companyId];
    require(_numberOfShares > 0 &&
        _numberOfShares <= (company.sharesInCirculation * MAX_CLAIM_SHARES_PERCENTAGE) / 100);
    require(company.unclaimedShares >= _numberOfShares);
    uint totalPrice = company.pricePerShare * _numberOfShares;
    require(msg.value >= totalPrice);
    company.unclaimedShares -= uint32(_numberOfShares);
    _sharesBought(company.shareHolders, msg.sender, _numberOfShares);
    _updateCEOIfRequired(company, _companyId, msg.sender);
    if (totalPrice > 0) {
        uint salesCut = _computeSalesCut(totalPrice);
        withdrawableBalance += salesCut;
        uint sellerProceeds = totalPrice - salesCut;
        company.ownedBy.transfer(sellerProceeds);
    }
    emit Claimed(_companyId, _numberOfShares, msg.sender);
}

function fillBuyOrderPartially(uint _companyId, uint _orderIndex, uint _maxAmount)
whenNotPaused
external {
    require(_maxAmount > 0);
    Order storage order = companyIdToOrders[_companyId][_orderIndex];
    require(order.orderType == OrderType.Buy);
    require(msg.sender != order.owner);
    uint buyableShares = _getRemainingSharesInOrder(order);
    require(buyableShares > 0);
    if (buyableShares > _maxAmount) {
        buyableShares = _maxAmount;
    }
    _verifyOwnershipOfTokens(_companyId, msg.sender, buyableShares);
    order.amountFilled += uint32(buyableShares);
    _transfer(_companyId, msg.sender, order.owner, buyableShares);
    uint price = _getTotalPrice(order, buyableShares);
    _transferOrderMoney(price, msg.sender);
    _updateTradingVolume(_companyId, msg.sender, order.owner, buyableShares);
    emit OrderFilled(_companyId, _orderIndex, buyableShares, msg.sender);
}

function transferPromotionalShares(uint _companyId, address _to, uint _amount)
onlyCLevel
whenNotPaused
external {
    Company storage company = companies[_companyId];
    require(company.pricePerShare == 0);
    require(companies[_companyId].shareHolders.ownerAddressToShares[msg.sender] >= _amount);
    _transfer(_companyId, msg.sender, _to, _amount);
}

function _updateTradingVolume(uint _companyId, address _from, address _to, uint _amount)
internal {
    Traders storage traders = companyIdToTraders[_companyId];
    _updateTradingVolume(traders, _from, _to, _amount);
    if (now < traders.relaseTime) {
        return;
    }
    Company storage company = companies[_companyId];
    uint _newShares = company.sharesInCirculation / 100;
    if (_newShares > MAX_SHARES_RELEASE_IN_ONE_CYCLE) {
        _newShares = 100;
    }
    company.sharesInCirculation += uint32(_newShares);
    _sharesBought(company.shareHolders, traders.winningTrader, _newShares);
    _updateCEOIfRequired(company, _companyId, traders.winningTrader);
    emit TradingWinnerAnnounced(_companyId, traders.winningTrader, _newShares);
    _clearWinner(traders);
}

function releaseNextShares(uint _companyId)
external
whenNotPaused {
    Company storage company = companies[_companyId];
    require(company.ceoOfCompany == msg.sender);
    require(company.unclaimedShares == 0);
    require(now >= company.nextSharesReleaseTime);
    company.nextSharesReleaseTime = now + company.coolDownTime * 1 days;
    uint sharesToRelease = (company.sharesInCirculation * company.percentageSharesToRelease) / 100;
    if (sharesToRelease > MAX_SHARES_RELEASE_IN_ONE_CYCLE) {
        sharesToRelease = MAX_SHARES_RELEASE_IN_ONE_CYCLE;
    }
    if (sharesToRelease > 0) {
        company.sharesInCirculation += uint32(sharesToRelease);
        _sharesBought(company.shareHolders, company.ceoOfCompany, sharesToRelease);
        emit SharesReleased(_companyId, company.ceoOfCompany, sharesToRelease, company.nextSharesReleaseTime);
    }
}

function _verifyOwnershipOfTokens(uint _companyId, address _owner, uint _amount)
view
internal {
    require(companies[_companyId].shareHolders.ownerAddressToShares[_owner] >= _amount);
}

function queueTransaction(address target, uint256 value, string memory signature, bytes memory data, uint256 eta) public returns(bytes32) {
    require(msg.sender == admin, "Timelock::queueTransaction: Call must come from admin.");
    require(eta >= getBlockTimestamp().add(delay), "Timelock::queueTransaction: Estimated execution block must satisfy delay.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

function executeTransaction(address target, uint256 value, string memory signature, bytes memory data, uint256 eta) public payable returns(bytes memory) {
    require(msg.sender == admin, "Timelock::executeTransaction: Call must come from admin.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "Timelock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "Timelock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "Timelock::executeTransaction: Transaction is stale.");
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call.value(value)(callData);
    require(success, "Timelock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

