function mintReserve() public onlyOwner {
    require(mintStart < _currentTime(), "Minting has not been allowed yet.");
    require(totalMinted < mintSize, "No tokens are available for minting.");
    MintStage memory currentStage = _getCurrentStage();
    uint256 mintAmount = currentStage.volume.sub(totalMinted);
    if (mintAmount > 0 && _mint(mintAmount)) {
        emit MintReserveLog(mintAmount);
        totalMinted = totalMinted.add(mintAmount);
    }
}

function _setStages(uint256 _mintStart) private {
    require(_mintStart >= _currentTime(), "Mint start date is invalid.");
    mintStart = _mintStart;
    stages.push(MintStage(_mintStart, uint256(200000000).mul(10 ** 18)));
    stages.push(MintStage(_mintStart.add(365 days), uint256(325000000).mul(10 ** 18)));
    stages.push(MintStage(_mintStart.add(2 * 365 days), uint256(450000000).mul(10 ** 18)));
    stages.push(MintStage(_mintStart.add(3 * 365 days), uint256(575000000).mul(10 ** 18)));
}

function _getCurrentStage() private view returns(MintStage) {
    uint256 index = 0;
    uint256 time = _currentTime();
    MintStage memory result;
    while (index < stages.length) {
        MintStage memory activeStage = stages[index];
        if (time >= activeStage.start) {
            result = activeStage;
        }
        index++;
    }
    return result;
}

function sell(uint256 amount)
external {
    require(amount <= ledger[msg.sender], INSUFFICIENT_TOKENS);
    uint256 exitValue = calcBurnReward(amount);
    msg.sender.transfer(exitValue);
    exitVar = exitValue;
    ledger[msg.sender] = sub(ledger[msg.sender], amount);
    currentSupply = sub(currentSupply, amount);
}

function buy(uint256 amount)
external payable {
    uint256 price = calcMintPrice(amount);
    require(msg.value >= price, INSUFFICIENT_ETH);
    uint256 refund = msg.value - price;
    if (refund > 0) {
        msg.sender.transfer(refund);
    }
    ledger[msg.sender] = add(ledger[msg.sender], amount);
    currentSupply = add(currentSupply, amount);
    uint256 newBuyPrice = calcMintPrice(1);
    uint256 newSellPrice = calcBurnReward(1);
    emit NewPrice(newBuyPrice, newSellPrice);
}

function buy(uint _discount, bytes _promocode) public payable {
    require(fundingEnabled);
    uint tokenPrice = tokenPriceProvider.tokenPrice(); 
    require(tokenPrice > 10 ** 9);
    require(msg.value >= tokenPrice);
    require(_discount <= 20);
    require(_promocode.length == 97);
    bytes32 r;
    bytes32 s;
    uint8 v;
    bytes32 h;
    assembly {
        r: = mload(add(_promocode, 32))
        s: = mload(add(_promocode, 64))
        v: = and(mload(add(_promocode, 65)), 255)
        h: = mload(add(_promocode, 97))
    }
    if (v < 27) {
        v += 27;
    }
    require((v == 27) || (v == 28));
    address agentSigner = ecrecover(h, v, r, s);
    require(agentSigner != 0);
    require(agents[agentSigner] != 0);
    bytes32 check_h = keccak256(abi.encodePacked(_discount, msg.sender));
    require(check_h == h);
    uint remVal = ((20 - _discount) * msg.value) / 100;
    totalCollected += msg.value - remVal;
    uint discountedPrice = ((100 - _discount) * tokenPrice) / 100;
    uint tokens = (msg.value * 10 ** uint256(tokenContract.decimals())) / discountedPrice;
    require(tokenContract.transferFrom(spenderAddress, msg.sender, tokens));
    vaultAddress.transfer(msg.value - remVal);
    agents[agentSigner].transfer(remVal);
    return;
}

function lockLPToken(address _lpToken, uint256 _amount, uint256 _unlock_date, address payable _referral, bool _fee_in_eth, address payable _withdrawer) external payable nonReentrant {
    require(_unlock_date < 10000000000, 'TIMESTAMP INVALID'); 
    require(_amount > 0, 'INSUFFICIENT');
    IUniswapV2Pair lpair = IUniswapV2Pair(address(_lpToken));
    address factoryPairAddress = uniswapFactory.getPair(lpair.token0(), lpair.token1());
    require(factoryPairAddress == address(_lpToken), 'NOT UNIV2');
    TransferHelper.safeTransferFrom(_lpToken, address(msg.sender), address(this), _amount);
    if (_referral != address(0) && address(gFees.referralToken) != address(0)) {
        require(gFees.referralToken.balanceOf(_referral) >= gFees.referralHold, 'INADEQUATE BALANCE');
    }
    if (!feeWhitelist.contains(msg.sender)) {
        if (_fee_in_eth) { 
            uint256 ethFee = gFees.ethFee;
            if (_referral != address(0)) {
                ethFee = ethFee.mul(1000 - gFees.referralDiscount).div(1000);
            }
            require(msg.value == ethFee, 'FEE NOT MET');
            uint256 devFee = ethFee;
            if (ethFee != 0 && _referral != address(0)) { 
                uint256 referralFee = devFee.mul(gFees.referralPercent).div(1000);
                _referral.transfer(referralFee);
                devFee = devFee.sub(referralFee);
            }
            devaddr.transfer(devFee);
        } else { 
            uint256 burnFee = gFees.secondaryTokenFee;
            if (_referral != address(0)) {
                burnFee = burnFee.mul(1000 - gFees.referralDiscount).div(1000);
            }
            TransferHelper.safeTransferFrom(address(gFees.secondaryFeeToken), address(msg.sender), address(this), burnFee);
            if (gFees.referralPercent != 0 && _referral != address(0)) { 
                uint256 referralFee = burnFee.mul(gFees.referralPercent).div(1000);
                TransferHelper.safeApprove(address(gFees.secondaryFeeToken), _referral, referralFee);
                TransferHelper.safeTransfer(address(gFees.secondaryFeeToken), _referral, referralFee);
                burnFee = burnFee.sub(referralFee);
            }
            gFees.secondaryFeeToken.burn(burnFee);
        }
    } else if (msg.value > 0) {
        msg.sender.transfer(msg.value);
    }
    uint256 liquidityFee = _amount.mul(gFees.liquidityFee).div(1000);
    if (!_fee_in_eth && !feeWhitelist.contains(msg.sender)) { 
        liquidityFee = liquidityFee.mul(1000 - gFees.secondaryTokenDiscount).div(1000);
    }
    TransferHelper.safeTransfer(_lpToken, devaddr, liquidityFee);
    uint256 amountLocked = _amount.sub(liquidityFee);
    TokenLock memory token_lock;
    token_lock.lockDate = block.timestamp;
    token_lock.amount = amountLocked;
    token_lock.initialAmount = amountLocked;
    token_lock.unlockDate = _unlock_date;
    token_lock.lockID = tokenLocks[_lpToken].length;
    token_lock.owner = _withdrawer;
    tokenLocks[_lpToken].push(token_lock);
    lockedTokens.add(_lpToken);
    UserInfo storage user = users[_withdrawer];
    user.lockedTokens.add(_lpToken);
    uint256[] storage user_locks = user.locksForToken[_lpToken];
    user_locks.push(token_lock.lockID);
    emit onDeposit(_lpToken, msg.sender, token_lock.amount, token_lock.lockDate, token_lock.unlockDate);
}

