function transfer(address _toAddress, uint256 _amountOfTokens) onlyBagholders public returns(bool) {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) {
        withdraw();
    }
    uint256 _tokenFee = SafeMath.div(SafeMath.mul(_amountOfTokens, transferFee_), 100);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    if (tokenBalanceLedger_[_toAddress] >= lotteryRequirement && !isAdded[_toAddress]) {
        participants.push(_toAddress);
        participantsIndex[_toAddress] = participants.length - 1;
        isAdded[msg.sender] = true;
    }
    if (tokenBalanceLedger_[_customerAddress] < lotteryRequirement && isAdded[_customerAddress]) {
        isAdded[_customerAddress] = false;
        uint indexToDelete = participantsIndex[_customerAddress];
        address lastAddress = participants[participants.length - 1];
        participants[indexToDelete] = lastAddress;
        participants.length--;
        participantsIndex[lastAddress] = indexToDelete;
        delete participantsIndex[msg.sender];
    }
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function requestMortgageId(
    Engine engine,
    uint256 loanId,
    uint256 deposit,
    uint256 landId,
    TokenConverter tokenConverter
) public returns(uint256 id) {
    require(engine.getCurrency(loanId) == MANA_CURRENCY, "Loan currency is not MANA");
    address borrower = engine.getBorrower(loanId);
    require(engine.getStatus(loanId) == Engine.Status.initial, "Loan status is not inital");
    require(msg.sender == engine.getBorrower(loanId) ||
        (msg.sender == engine.getCreator(loanId) && creators[msg.sender]),
        "Creator should be borrower or authorized");
    require(engine.isApproved(loanId), "Loan is not approved");
    require(rcn.allowance(borrower, this) >= REQUIRED_ALLOWANCE, "Manager cannot handle borrower's funds");
    require(tokenConverter != address(0), "Token converter not defined");
    require(loanToLiability[engine][loanId] == 0, "Liability for loan already exists");
    uint256 landCost;
    (, , landCost, ) = landMarket.auctionByAssetId(landId);
    uint256 loanAmount = engine.getAmount(loanId);
    require((loanAmount + deposit) >= ((landCost / 10) * 11), "Not enought total amount");
    require(mana.transferFrom(msg.sender, this, deposit));
    id = mortgages.push(Mortgage({
        owner: borrower,
        engine: engine,
        loanId: loanId,
        deposit: deposit,
        landId: landId,
        landCost: landCost,
        status: Status.Pending,
        tokenConverter: tokenConverter
    })) - 1;
    loanToLiability[engine][loanId] = id;
    emit RequestedMortgage({
        _id: id,
        _borrower: borrower,
        _engine: engine,
        _loanId: loanId,
        _landId: landId,
        _deposit: deposit,
        _tokenConverter: tokenConverter
    });
}

function claim(address engine, uint256 loanId, bytes) external returns(bool) {
    uint256 mortgageId = loanToLiability[engine][loanId];
    Mortgage storage mortgage = mortgages[mortgageId];
    require(mortgage.status == Status.Ongoing, "Mortgage not ongoing");
    require(mortgage.loanId == loanId, "Mortgage don't match loan id");
    if (mortgage.engine.getStatus(loanId) == Engine.Status.paid || mortgage.engine.getStatus(loanId) == Engine.Status.destroyed) {
        require(_isAuthorized(msg.sender, mortgageId), "Sender not authorized");
        mortgage.status = Status.Paid;
        land.safeTransferFrom(this, msg.sender, mortgage.landId);
        emit PaidMortgage(msg.sender, mortgageId);
    } else if (isDefaulted(mortgage.engine, loanId)) {
        require(msg.sender == mortgage.engine.ownerOf(loanId), "Sender not lender");
        mortgage.status = Status.Defaulted;
        land.safeTransferFrom(this, msg.sender, mortgage.landId);
        emit DefaultedMortgage(mortgageId);
    } else {
        revert("Mortgage not defaulted/paid");
    }
    _destroy(mortgageId);
    delete mortgageByLandId[mortgage.landId];
    return true;
}

function claim() public onlyOwner {
    uint pendingUnlocked = getPendingUnlocked();
    uint contractBalance = UniD(tokenAddress).balanceOf(address(this));
    uint amountToSend = pendingUnlocked;
    if (contractBalance < pendingUnlocked) {
        amountToSend = contractBalance;
    }
    require(UniD(tokenAddress).transfer(owner, amountToSend), "Could not transfer Tokens.");
    lastClaimedTime = now;
}

function exec(address _sender, bytes32 _exec_id, bytes _calldata) external payable returns(uint n_emitted, uint n_paid, uint n_stored) {
    require(_calldata.length >= 4 && _sender != address(0) && _exec_id != bytes32(0));
    address target = getTarget(_exec_id, getSelector(_calldata));
    require(target != address(0), 'Uninitialized application');
    setContext(_exec_id, _sender);
    require(address(target).delegatecall(_calldata) == false, 'Unsafe execution');
    (n_emitted, n_paid, n_stored) = executeAppReturn(_exec_id);
    if (n_emitted == 0 && n_paid == 0 && n_stored == 0)
        revert('No state change occured');
    emit ApplicationExecution(_exec_id, target);
    if (address(this).balance > 0)
        address(msg.sender).transfer(address(this).balance);
}

function doPay(bytes32 _exec_id, uint _ptr, uint _ptr_bound) internal returns(uint ptr, uint n_paid) {
    require(msg.value > 0);
    assert(getAction(_ptr) == PAYS);
    _ptr += 4;
    uint num_destinations = getLength(_ptr);
    _ptr += 32;
    address pay_to;
    uint amt;
    while (_ptr <= _ptr_bound && n_paid < num_destinations) {
        assembly {
            amt: = mload(_ptr)
            pay_to: = mload(add(0x20, _ptr))
        }
        if (pay_to == address(0) || pay_to == address(this))
            revert('PAYS: invalid destination');
        address(pay_to).transfer(amt);
        n_paid++;
        _ptr += 64;
        emit DeliveredPayment(_exec_id, pay_to, amt);
    }
    ptr = _ptr;
    assert(n_paid == num_destinations);
}

function createInstance(address _sender, bytes32 _app_name, address _provider, bytes32 _registry_id, bytes _calldata) external payable returns(bytes32 new_exec_id, bytes32 version) {
    require(_sender != 0 && _app_name != 0 && _provider != 0 && _registry_id != 0 && _calldata.length >= 4, 'invalid input');
    new_exec_id = keccak256(++nonce);
    assert(getIndex(new_exec_id) == address(0));
    address index;
    (index, version) = setImplementation(new_exec_id, _app_name, _provider, _registry_id);
    setContext(new_exec_id, _sender);
    require(address(index).delegatecall(_calldata) == false, 'Unsafe execution');
    executeAppReturn(new_exec_id);
    emit ApplicationInitialized(new_exec_id, index, msg.sender);
    assert(new_exec_id != bytes32(0));
    if (address(this).balance > 0)
        address(msg.sender).transfer(address(this).balance);
}

