function transferFrom(address _from, address _to, uint256 _value) NotPaused public returns(bool success) {
    uint256 _lastTransfer;
    _lastTransfer = lastTransfer[_from] + timeFrame;
    if (_lastTransfer < now) {
        transfered[_from] = 0;
        lastTransfer[_from] = now;
    }
    if ((_value <= (maxTransferPerTimeframe - transfered[_from])) || !restrictTransfers) {
        if (restrictTransfers) {
            transfered[_from] += _value;
        }
        super.transferFrom(_from, _to, _value);
        return true;
    } else {
        return false;
    }
}

function transfer(address _to, uint256 _value) NotPaused public returns(bool success) {
    uint256 _lastTransfer;
    _lastTransfer = lastTransfer[msg.sender] + timeFrame;
    if (_lastTransfer < now) {
        transfered[msg.sender] = 0;
        lastTransfer[msg.sender] = now;
    }
    if ((_value <= (maxTransferPerTimeframe - transfered[msg.sender])) || !restrictTransfers) {
        if (restrictTransfers) {
            transfered[msg.sender] += _value;
        }
        super.transfer(_to, _value);
        return true;
    } else {
        return false;
    }
}

function() payable {
    totalEthInWei = totalEthInWei + msg.value;
    if (now < startTime + 1 weeks) {
        unitsOneEthCanBuy = 140000;
    } else if (now > startTime + 1 weeks && now < startTime + 10 weeks) {
        unitsOneEthCanBuy = 120000;
    } else {
        return;
    }
    uint256 amount = msg.value * unitsOneEthCanBuy;
    if (balances[fundsWallet] < amount) {
        return;
    }
    balances[fundsWallet] = balances[fundsWallet] - amount;
    balances[msg.sender] = balances[msg.sender] + amount;
    Transfer(fundsWallet, msg.sender, amount); 
    fundsWallet.transfer(msg.value);
}

function core(uint256 _rID, uint256 _pID, uint256 _eth, uint256 _affID, uint256 _team, NTech3DDatasets.EventReturns memory _eventData_) private {
    if (plyrRnds_[_pID][_rID].keys == 0)
        _eventData_ = managePlayer(_pID, _eventData_);
    if (round_[_rID].eth < 100000000000000000000 && plyrRnds_[_pID][_rID].eth.add(_eth) > 10000000000000000000) {
        uint256 _availableLimit = (10000000000000000000).sub(plyrRnds_[_pID][_rID].eth);
        uint256 _refund = _eth.sub(_availableLimit);
        plyr_[_pID].gen = plyr_[_pID].gen.add(_refund);
        _eth = _availableLimit;
    }
    if (_eth > 1000000000) {
        uint256 _keys = (round_[_rID].eth).keysRec(_eth);
        if (_keys >= 1000000000000000000) {
            updateTimer(_keys, _rID);
            if (round_[_rID].plyr != _pID)
                round_[_rID].plyr = _pID;
            if (round_[_rID].team != _team)
                round_[_rID].team = _team;
            _eventData_.compressedData = _eventData_.compressedData + 100;
        }
        if (_eth >= 100000000000000000) {
            airDropTracker_++;
            if (airdrop() == true) {
                uint256 _prize;
                if (_eth >= 10000000000000000000) {
                    _prize = ((airDropPot_).mul(75)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                    _eventData_.compressedData += 300000000000000000000000000000000;
                } else if (_eth >= 1000000000000000000 && _eth < 10000000000000000000) {
                    _prize = ((airDropPot_).mul(50)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                    _eventData_.compressedData += 200000000000000000000000000000000;
                } else if (_eth >= 100000000000000000 && _eth < 1000000000000000000) {
                    _prize = ((airDropPot_).mul(25)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                    _eventData_.compressedData += 300000000000000000000000000000000;
                }
                _eventData_.compressedData += 10000000000000000000000000000000;
                _eventData_.compressedData += _prize * 1000000000000000000000000000000000;
                airDropTracker_ = 0;
            }
        }
        _eventData_.compressedData = _eventData_.compressedData + (airDropTracker_ * 1000);
        plyrRnds_[_pID][_rID].keys = _keys.add(plyrRnds_[_pID][_rID].keys);
        plyrRnds_[_pID][_rID].eth = _eth.add(plyrRnds_[_pID][_rID].eth);
        round_[_rID].keys = _keys.add(round_[_rID].keys);
        round_[_rID].eth = _eth.add(round_[_rID].eth);
        rndTmEth_[_rID][_team] = _eth.add(rndTmEth_[_rID][_team]);
        _eventData_ = distributeExternal(_rID, _pID, _eth, _affID, _team, _eventData_);
        _eventData_ = distributeInternal(_rID, _pID, _eth, _team, _keys, _eventData_);
        endTx(_pID, _team, _eth, _keys, _eventData_);
    }
}

