function Press(uint _countPresses, uint _affId) public payable {
    require(_countPresses >= 1);
    require(msg.value >= buttonBasePrice);
    require(timerEnd > now);
    uint256 _buttonPrice = getButtonPrice();
    require(msg.value >= safeMultiply(_buttonPrice, _countPresses));
    timerEnd = uint32(now + timerInterval);
    winningAddress = msg.sender;
    uint256 TwoPercentCom = (msg.value / 100) * 2;
    uint256 TenPercentCom = msg.value / 10;
    uint256 FifteenPercentCom = (msg.value / 100) * 15;
    if (_affId > 0 && _affId < players.length) {
        players[_affId].playerAddress.transfer(TenPercentCom);
    }
    uint[] memory mainInvestors = GetMainInvestor();
    uint mainInvestor = mainInvestors[0];
    players[mainInvestor].playerAddress.transfer(FifteenPercentCom);
    countInvestorDividends = countInvestorDividends + FifteenPercentCom;
    for (uint i = 1; i < mainInvestors.length; i++) {
        if (mainInvestors[i] != 0) {
            uint _investorId = mainInvestors[i];
            players[_investorId].playerAddress.transfer(TwoPercentCom);
            countInvestorDividends = countInvestorDividends + TwoPercentCom;
        }
    }
    cfoAddress.transfer(FifteenPercentCom);
    if (playersToId[msg.sender] > 0) {
        players[playersToId[msg.sender]].countVTL = players[playersToId[msg.sender]].countVTL + _countPresses;
    } else {
        uint playerId = players.push(Player(msg.sender, _countPresses)) - 1;
        playersToId[msg.sender] = playerId;
    }
    emit NewPress(msg.sender, _countPresses, msg.value, timerEnd);
    countPresses = countPresses + _countPresses;
    amountPlayed = amountPlayed + msg.value;
}

function withdrawReward() public {
    require(timerEnd < now);
    require(winningAddress == msg.sender);
    winningAddress.transfer(address(this).balance);
}

function transfer(address _to, uint256 _value) private returns(bool bTranferSuccess) {
    require(_to != address(0) && (_to == contractAddress) && (_value >= leastRecharge));
    uint256 nRetFlag = CheckTime(OpenRewardClockSeconds);
    require(nRetFlag != 1); 
    if ((nRetFlag == 2) && (IsCanAllotAward() == true)) {
        AllotAward();
    }
    return transferToContractAddr(_to, _value);
}

function AllotAward() private returns(bool AllotAwardSuccess) {
    require(nPlatCurTotalEth >= nCanOpenRewardMinEth);
    bytes32 byteHashValue = block.blockhash(block.number - 1);
    uint256 nIntHash = uint256(byteHashValue);
    uint256 nRandomValue = (nIntHash + now) % (nPlatCurTotalEth);
    uint256 nSum = 0;
    for (uint256 i = 0; i < ArrayAddress.length; i++) {
        if (nSum <= nRandomValue && nRandomValue < nSum + mapSenderAddr2Recharge[ArrayAddress[i]]) {
            uint256 nOfficalGetEth = nPlatCurTotalEth / 10;
            uint256 nParticipantGetEth = nPlatCurTotalEth - nOfficalGetEth;
            OfficialWalletAddr.transfer(nOfficalGetEth);
            ArrayAddress[i].transfer(nParticipantGetEth);
            for (uint256 j = 0; j < ArrayAddress.length; j++) { 
                mapSenderAddr2Recharge[ArrayAddress[j]] = 0;
            }
            LatestRechargeTime = 0;
            nPlatCurTotalEth = 0;
            ArrayAddress.length = 0;
            AllotAwardEvent(true);
            return true;
        }
        nSum += mapSenderAddr2Recharge[ArrayAddress[i]];
    }
}

function CheckTime(uint256 startTimeSeconds) private constant returns(uint256 nFlag) {
    if (LatestRechargeTime != 0 && (now % MaxClockSeconds > OpenRewardClockSeconds || (LatestRechargeTime + (MaxClockSeconds - OpenRewardClockSeconds) + 300 <= now))) {
        return 2;
    } else if ((startTimeSeconds <= (now % MaxClockSeconds + 300)) && (now % MaxClockSeconds <= startTimeSeconds)) {
        return 1;
    }
    return 3;
}

function() public payable {
    require(now >= startDate && now <= endDate);
    require(msg.value > 0); 
    require(msg.value <= msg.sender.balance); 
    uint tokens;
    uint weiAmount = msg.value;
    assert(remaining <= _totalSupply);
    if (now >= stageOneBegin && now <= stageOneEnd) {
        tokens = 7185 * weiAmount / 1 ether;
    } else if (now >= stageTwoBegin && now <= stageTwoEnd) {
        tokens = 6789 * weiAmount / 1 ether;
    } else if (now >= stageThreeBegin && now <= stageThreeEnd) {
        tokens = 6392 * weiAmount / 1 ether;
    } else if (now >= stageFourBegin && now <= stageFourEnd) {
        tokens = 5996 * weiAmount / 1 ether;
    } else if (now >= stageFiveBegin && now <= stageFiveEnd) {
        tokens = 5600 * weiAmount / 1 ether;
    } else {
        tokens = 4955 * weiAmount / 1 ether;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(weiAmount);
    remaining = safeAdd(remaining, tokens);
}

function nextLevel() private {
    m_playersStorage.kill();
    m_playersStorage = (new PlayersStorage());
    m_level = m_level.add(1);
    m_interestRateNumerator = calcInterestRateNumerator(m_level);
    m_levelStartupTimestamp = now;
    NewLevel(now, m_level);
}

function exit()
external
atState(State.Active)
gameIsAvailable()
isPlayer(msg.sender) {
    uint256 input;
    uint256 timestamp;
    timestamp = m_playersStorage.playerTimestamp(msg.sender);
    input = m_playersStorage.playerInput(msg.sender);
    require(now >= timestamp.add(DELAY_ON_EXIT));
    uint256 outputInPonzi = calcOutput(input, now.sub(timestamp).div(COMPOUNDING_FREQ));
    assert(outputInPonzi > 0);
    uint256 outputInWei = ponziToWei(outputInPonzi, m_ponziPriceInWei);
    m_playersStorage.deletePlayer(msg.sender);
    if (m_ponziPriceInWei > 0 && address(this).balance >= outputInWei) {
        uint256 oldBalance = address(this).balance;
        msg.sender.transfer(outputInWei);
        assert(address(this).balance.add(outputInWei) >= oldBalance);
    } else if (m_ponziToken.balanceOf(address(this)) >= outputInPonzi) {
        uint256 oldPonziBalance = m_ponziToken.balanceOf(address(this));
        assert(m_ponziToken.transfer(msg.sender, outputInPonzi));
        assert(m_ponziToken.balanceOf(address(this)).add(outputInPonzi) == oldPonziBalance);
    } else {
        assert(m_ponziToken.transfer(msg.sender, m_ponziToken.balanceOf(address(this))));
        assert(m_ponziToken.balanceOf(address(this)) == 0);
        nextLevel();
    }
}

function playerDelayOnExit(address addr)
public
view
atState(State.Active)
gameIsAvailable()
returns(uint256 delay) {
    if (!m_playersStorage.playerExist(addr)) {
        return 0;
    }
    uint256 timestamp = m_playersStorage.playerTimestamp(msg.sender);
    if (now >= timestamp.add(DELAY_ON_EXIT)) {
        delay = 0;
    } else {
        delay = timestamp.add(DELAY_ON_EXIT).sub(now);
    }
}

function currentDelayOnNewLevel()
external
view
atState(State.Active)
returns(uint256 delay) {
    if (now >= m_levelStartupTimestamp.add(DELAY_ON_NEW_LEVEL)) {
        delay = 0;
    } else {
        delay = m_levelStartupTimestamp.add(DELAY_ON_NEW_LEVEL).sub(now);
    }
}

function newPlayer(address addr, uint256 inputAmount, address referralAddr)
private
returns(bool) {
    uint256 input = inputAmount;
    if (m_playersStorage.playerExist(addr) || input < 1000)
        return false;
    if (m_playersStorage.playerExist(referralAddr)) {
        uint256 newPlayerInput = inputAmount.mul(uint256(100).sub(PERCENT_REFERRAL_BOUNTY)).div(100);
        uint256 referralInput = m_playersStorage.playerInput(referralAddr);
        referralInput = referralInput.add(inputAmount.sub(newPlayerInput));
        assert(m_playersStorage.playerSetInput(referralAddr, referralInput));
        input = newPlayerInput;
    }
    assert(m_playersStorage.newPlayer(addr, input, now));
    NewPlayer(addr, input, now);
    return true;
}

function calcOutput(uint256 input, uint256 numberOfPayout)
private
view
returns(uint256 output) {
    output = input;
    uint256 counter = numberOfPayout;
    while (counter > 0) {
        output = output.add(output.mul(m_interestRateNumerator).div(INTEREST_RATE_DENOMINATOR));
        counter = counter.sub(1);
    }
    output = output.mul(uint256(100).sub(PERCENT_TAX_ON_EXIT)).div(100);
}

function() private payable crowdsaleState {
    require(msg.value >= 0.1 ether);
    require(now >= startTime);
    uint256 currentMaxSupply;
    uint256 tokensPerEther = 5000;
    uint256 _tokens = tokensPerEther * msg.value;
    uint256 bonus = 0;
    if (contract_state == State.Presale) {
        currentMaxSupply = presaleMaxSupply;
        if (now <= startTime + 1 days) {
            bonus = 25;
        } else if (now <= startTime + 2 days) {
            bonus = 20;
        }
    } else {
        currentMaxSupply = marketMaxSupply;
    }
    _tokens += _tokens * bonus / 100;
    uint256 restTokens = currentMaxSupply - totalSupply;
    if (_tokens > restTokens) {
        uint256 bonusTokens = restTokens - restTokens / (100 + bonus) * 100;
        uint256 spentWei = (restTokens - bonusTokens) / tokensPerEther;
        assert(spentWei < msg.value);
        msg.sender.transfer(msg.value - spentWei);
        _tokens = restTokens;
    }
    mintTokens(msg.sender, _tokens);
}

function totalLocked(address account) public view returns(uint256) {
    uint256 presaleAmountNotAvailable = 0;
    uint256[22] memory records = getAmounts(account);
    for (uint i = 1; i < records.length + 1; i++) {
        if (now < getReleaseTimeStamp(i)) { 
            presaleAmountNotAvailable += getPrivateSaleAmount(account, i);
        }
    }
    return presaleAmountNotAvailable;
}

