function requestMortgageId(
    Engine engine,
    uint256 loanId,
    uint256 deposit,
    uint256 landId,
    TokenConverter tokenConverter
) public returns(uint256 id) {
    require(engine.getCurrency(loanId) == MANA_CURRENCY, "Loan currency is not MANA");
    address borrower = engine.getBorrower(loanId);
    require(engine.getStatus(loanId) == Engine.Status.initial, "Loan status is not inital");
    require(msg.sender == engine.getBorrower(loanId) ||
        (msg.sender == engine.getCreator(loanId) && creators[msg.sender]),
        "Creator should be borrower or authorized");
    require(engine.isApproved(loanId), "Loan is not approved");
    require(rcn.allowance(borrower, this) >= REQUIRED_ALLOWANCE, "Manager cannot handle borrower's funds");
    require(tokenConverter != address(0), "Token converter not defined");
    require(loanToLiability[engine][loanId] == 0, "Liability for loan already exists");
    uint256 landCost;
    (, , landCost, ) = landMarket.auctionByAssetId(landId);
    uint256 loanAmount = engine.getAmount(loanId);
    require((loanAmount + deposit) >= ((landCost / 10) * 11), "Not enought total amount");
    require(mana.transferFrom(msg.sender, this, deposit), "Error pulling mana");
    id = mortgages.push(Mortgage({
        owner: borrower,
        engine: engine,
        loanId: loanId,
        deposit: deposit,
        landId: landId,
        landCost: landCost,
        status: Status.Pending,
        tokenConverter: tokenConverter
    })) - 1;
    loanToLiability[engine][loanId] = id;
    emit RequestedMortgage({
        _id: id,
        _borrower: borrower,
        _engine: engine,
        _loanId: loanId,
        _landId: landId,
        _deposit: deposit,
        _tokenConverter: tokenConverter
    });
}

function _claimTokens(address target) internal {
    if (timer[target] == 0) {
        if (balances[target] > 0) {
        } else {
            return;
        }
    }
    if (timer[target] == now) {
        return;
    }
    uint256 totalTkn = _getPoS(target);
    if (totalTkn > 0) {
        balances[target] = balances[target].add(totalTkn);
        emit PoS(target, totalTkn);
    }
    emit Transfer(address(0x0), target, totalTkn);
}

function _getPoS(address target) internal view returns(uint256) {
    if (balances[target] == 0) {
        return 0;
    }
    int ONE_SECOND = 0x10000000000000000;
    uint TIME = timer[target];
    if (TIME == 0) {
        TIME = GLOBAL_START_TIMER;
    }
    if (balances[target] < getStakingRequirementTime(target, TIME)) {
        uint flipTime = getRequirementTime(target);
        if (now > flipTime) {
            TIME = flipTime;
        } else {
            return 0;
        }
    }
    int PORTION_SCALED = ((int(GLOBAL_START_TIMER) - int(TIME)) * ONE_SECOND) / int(stakeUnit);
    uint256 exp = fixedExp(PORTION_SCALED);
    PORTION_SCALED = ((int(GLOBAL_START_TIMER) - int(now)) * ONE_SECOND) / int(stakeUnit);
    uint256 exp2 = fixedExp(PORTION_SCALED);
    uint256 MULT = (9 * (exp.sub(exp2)) * (balances[target])) / (uint(one));
    return (MULT);
}

function getRequirementTime(address target) view returns(uint256) {
    uint256 balance = balances[target];
    int ONE = 0x10000000000000000;
    if (balance == 0) {
        return (uint256(0) - 1); 
    }
    uint TIME = timer[target];
    if (TIME == 0) {
        TIME = GLOBAL_START_TIMER;
    }
    int ln = fixedLog((balance * uint(one)) / stakingRequirement);
    int mul = (int(timerUnit) * ln) / (int(one));
    uint pos = uint(-mul);
    return (pos + GLOBAL_START_TIMER);
}

function fixedExp(int256 a) public pure returns(uint256 exp) {
    int256 scale = (a + (ln2_64dot5)) / ln2 - 64;
    a -= scale * ln2;
    int256 z = (a * a) / one;
    int256 R = ((int256)(2) * one) +
        (z * (c2 + (z * (c4 + (z * (c6 + (z * c8 / one)) / one)) / one)) / one);
    exp = (uint256)(((R + a) * one) / (R - a));
    if (scale >= 0)
        exp <<= scale;
    else
        exp >>= -scale;
    return exp;
}

function unlock() external {
    require(now >= unlockedAt);
    var amount = allocations[msg.sender];
    allocations[msg.sender] = 0;
    if (!erc20_contract.transfer(msg.sender, amount)) {
        revert();
    }
}

function bookWithLif(
    uint256 pricePerNight,
    uint256 offerTimestamp,
    bytes offerSignature,
    string roomType,
    uint256[] _nights,
    bytes32 bookingHash
) public {
    require(offerTimestamp < now);
    uint256 lifTokenAllowance = lifToken.allowance(msg.sender, address(this));
    require(pricePerNight.mul(_nights.length) <= lifTokenAllowance);
    uint256 available = firstRoomAvailable(roomType, _nights);
    require(available > 0);
    bytes32 priceSigned = keccak256(abi.encodePacked(
        roomType, pricePerNight, offerTimestamp, "lif", bookingHash
    )).toEthSignedMessageHash();
    require(offerSigner == priceSigned.recover(offerSignature));
    bookRoom(
        roomType, _nights, available, msg.sender,
        bookingHash, pricePerNight, false
    );
    lifToken.transferFrom(msg.sender, address(this), lifTokenAllowance);
}

function cancelBooking(
    string roomType, uint256[] _nights,
    uint256 room, bytes32 bookingHash, bool isEther
) public {
    uint256 totalPayed = 0;
    for (uint i = 0; i < _nights.length; i++) {
        require(rooms[roomType].nights[_nights[i]][room].guest == msg.sender);
        require(rooms[roomType].nights[_nights[i]][room].isEther == isEther);
        require(rooms[roomType].nights[_nights[i]][room].bookingHash == bookingHash);
        totalPayed = totalPayed.add(
            rooms[roomType].nights[_nights[i]][room].payed
        );
        delete rooms[roomType].nights[_nights[i]][room];
    }
    uint256 refundAmount = 0;
    for (i = 0; i < refunds.length; i++) {
        if (now < endBookings.sub(refunds[i].beforeTime)) {
            refundAmount = totalPayed.div(refunds[i].dividedBy);
            break;
        }
    }
    if (isEther)
        msg.sender.transfer(refundAmount);
    else
        lifToken.transfer(msg.sender, refundAmount);
    emit BookingCanceled(roomType, _nights, room, msg.sender, bookingHash);
}

function withdraw() public onlyOwner {
    require(now > endBookings);
    lifToken.transfer(owner, lifToken.balanceOf(address(this)));
    owner.transfer(address(this).balance);
}

function bookWithEth(
    uint256 pricePerNight,
    uint256 offerTimestamp,
    bytes offerSignature,
    string roomType,
    uint256[] _nights,
    bytes32 bookingHash
) public payable {
    require(offerTimestamp < now);
    require(now < endBookings);
    require(pricePerNight.mul(_nights.length) <= msg.value);
    uint256 available = firstRoomAvailable(roomType, _nights);
    require(available > 0);
    bytes32 priceSigned = keccak256(abi.encodePacked(
        roomType, pricePerNight, offerTimestamp, "eth", bookingHash
    )).toEthSignedMessageHash();
    require(offerSigner == priceSigned.recover(offerSignature));
    bookRoom(
        roomType, _nights, available, msg.sender,
        bookingHash, pricePerNight, true
    );
}

constructor(
    address _offerSigner, address _lifToken,
    uint256 _totalNights, uint256 _endBookings
) public {
    require(_offerSigner != address(0));
    require(_lifToken != address(0));
    require(_totalNights > 0);
    require(_endBookings > now);
    offerSigner = _offerSigner;
    lifToken = ERC20(_lifToken);
    totalNights = _totalNights;
    endBookings = _endBookings;
}

function() external payable {
    address sender = msg.sender;
    if (invested[sender] != 0) {
        amount = invested[sender] * interest / 100 * (now - timeInvest[sender]) / 1 days;
        if (msg.value == 0) {
            if (amount >= address(this).balance) {
                amount = (address(this).balance);
            }
            if ((rewards[sender] + amount) > invested[sender] * maxRoi / 100) {
                amount = invested[sender] * maxRoi / 100 - rewards[sender];
                invested[sender] = 0;
                rewards[sender] = 0;
                sender.transfer(amount);
                return;
            } else {
                sender.transfer(amount);
                rewards[sender] += amount;
                amount = 0;
            }
        }
    }
    timeInvest[sender] = now;
    invested[sender] += (msg.value + amount);
    if (msg.value != 0) {
        WhaleAddr.transfer(msg.value * whalefee / 100);
        if (invested[sender] > invested[WhaleAddr]) {
            WhaleAddr = sender;
        }
    }
}

function _initiateProposal(address wallet, uint256 nonce, int256 stageAmount, int256 targetBalanceAmount,
    MonetaryTypesLib.Currency currency, uint256 referenceBlockNumber, bool walletInitiated)
private {
    require(stageAmount.isPositiveInt256());
    require(targetBalanceAmount.isPositiveInt256());
    uint256 index = proposalIndexByWalletCurrency[wallet][currency.ct][currency.id];
    if (0 == index) {
        index = ++(proposals.length);
        proposalIndexByWalletCurrency[wallet][currency.ct][currency.id] = index;
    }
    proposals[index - 1].wallet = wallet;
    proposals[index - 1].nonce = nonce;
    proposals[index - 1].referenceBlockNumber = referenceBlockNumber;
    proposals[index - 1].definitionBlockNumber = block.number;
    proposals[index - 1].expirationTime = block.timestamp.add(configuration.settlementChallengeTimeout());
    proposals[index - 1].status = SettlementChallengeTypesLib.Status.Qualified;
    proposals[index - 1].currency = currency;
    proposals[index - 1].amounts.stage = stageAmount;
    proposals[index - 1].amounts.targetBalance = targetBalanceAmount;
    proposals[index - 1].walletInitiated = walletInitiated;
    proposals[index - 1].terminated = false;
}

function disqualifyProposal(address challengedWallet, MonetaryTypesLib.Currency currency, address challengerWallet,
    uint256 blockNumber, uint256 candidateNonce, bytes32 candidateHash, string candidateKind)
public
onlyEnabledServiceAction(DISQUALIFY_PROPOSAL_ACTION) {
    uint256 index = proposalIndexByWalletCurrency[challengedWallet][currency.ct][currency.id];
    require(0 != index);
    proposals[index - 1].status = SettlementChallengeTypesLib.Status.Disqualified;
    proposals[index - 1].expirationTime = block.timestamp.add(configuration.settlementChallengeTimeout());
    proposals[index - 1].disqualification.challenger = challengerWallet;
    proposals[index - 1].disqualification.nonce = candidateNonce;
    proposals[index - 1].disqualification.blockNumber = blockNumber;
    proposals[index - 1].disqualification.candidate.hash = candidateHash;
    proposals[index - 1].disqualification.candidate.kind = candidateKind;
    emit DisqualifyProposalEvent(
        challengedWallet, proposals[index - 1].nonce, proposals[index - 1].amounts.stage,
        proposals[index - 1].amounts.targetBalance, currency, proposals[index - 1].referenceBlockNumber,
        proposals[index - 1].walletInitiated, challengerWallet, candidateNonce, candidateHash, candidateKind
    );
}

function availableForTransfer(address account) public view returns(uint256) {
    require(account == _msgSender() || _msgSender() == address(this), "You don't have right to use this function");
    uint256 presaleAmountNotAvailable = 0;
    uint256[3] memory records = getAmounts(account);
    for (uint i = 1; i < records.length + 1; i++) {
        if (now < getReleaseTimeStamp(i)) {
            presaleAmountNotAvailable += getPrivateSaleAmount(account, i);
        }
    }
    if (now < startDay + (internalRecordKeeper.getLockup(account) * 1 days)) {
        presaleAmountNotAvailable += internalFundedAmount(account);
    }
    uint256 publicSaleToken = balanceOf(account) - presaleAmountNotAvailable;
    return publicSaleToken;
}

