    uint8[5] memory numbers = [number1, number2, number3, number4, 0];
    uint8[5] memory randoms = [getRN(), getRN(), getRN(), getRN(), 0];
    emit UserBet(msg.sender, number1, number2, number3, number4, 0);
    emit DiceRoll(randoms[0], randoms[1], randoms[2], randoms[3], 0);
    if (isWinner(4, numbers, randoms)) {
        rewardTheWinner(rewardFour);
    } else {
        emit Loser(msg.sender);
    }
}

function setLockUser(address _to, uint256 _value, uint256 _endTime) onlyOwner public {
    require(_endTime > now);
    require(_value > 0);
    uint256 balance = balanceOf(_to);
    uint256 usedLockBalance = lockBalanceAll(_to);
    require(balance >= usedLockBalance.add(_value));
    lockUser[_to].lockBalanceStandard.push(_value);
    lockUser[_to].endTime.push(_endTime);
    emit Lock(_to, _value, _endTime);
}

function finalize() public onlyOwner {
    require(!isFinalized);
    require(getNow() > icoEndTime || token.totalSupply() == ICO_TOKENS);
    if (goalReached()) {
        if (vault.state() != EscrowVault.State.Closed) {
            vault.close();
        }
        uint256 totalSupply = token.totalSupply();
        teamTimelock = new TokenTimelock(token, TEAM_WALLET, getNow().add(TEAM_TOKENS_LOCK_PERIOD));
        token.mint(teamTimelock, uint256(TEAM_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        companyTimelock = new TokenTimelock(token, COMPANY_WALLET, getNow().add(COMPANY_TOKENS_LOCK_PERIOD));
        token.mint(companyTimelock, uint256(COMPANY_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        token.mint(AIRDROP_WALLET, uint256(AIRDROP_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        token.mint(JACKPOT_WALLET, uint256(JACKPOT_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        token.finishMinting();
        token.transferOwnership(token);
    } else {
        vault.enableRefunds();
    }
    Finalized();
    isFinalized = true;
}

