function completedFlag(uint16 cntryId) private {
    uint16 randomSpot = uint16(uint(keccak256(now, msg.sender)) % 600);
    cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotOwner[randomSpot].transfer(cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].prize);
    cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotWon = randomSpot;
}

function regSpots(uint16 cntryId, uint16 numOfSpots, bytes32 stxt) external payable {
    require(numOfSpots > 0 && numOfSpots <= 600);
    uint i;
    uint j;
    uint j1;
    uint flagCompleted;
    if (cntry_flgs[cntryId].length > 0) {
        require(msg.value == cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotRate * numOfSpots);
        i = cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotOwner.length;
        if (600 - i >= numOfSpots) {
            j = numOfSpots;
            while (j > 0) {
                regSpot(cntryId, stxt);
                j--;
                i++;
            }
        } else {
            j1 = 600 - i;
            j = numOfSpots - j1;
            while (j1 > 0) {
                regSpot(cntryId, stxt);
                j1--;
                i++;
            }
            uint currRateHolder = cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotRate;
            completedFlag(cntryId);
            flagCompleted = 1;
            createFlag(cntryId, currRateHolder);
            i = 0;
            while (j > 0) {
                regSpot(cntryId, stxt);
                j--;
                i++;
            }
        }
    } else {
        require(msg.value == curr_rate * numOfSpots);
        createFlag(cntryId, curr_rate);
        i = 0;
        j = numOfSpots;
        while (j > 0) {
            regSpot(cntryId, stxt);
            j--;
            i++;
        }
    }
    if (i == 600) {
        completedFlag(cntryId);
        flagCompleted = 1;
        createFlag(cntryId, curr_rate);
    }
    UpdateFlagList(cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotOwner, cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotTxt, flagCompleted);
}

function fund() public payable {
    uint _fee = msg.value / feeRate;
    uint _val = msg.value - _fee;
    kBalance += _val;
    TechnicalRise.transfer(_fee);
    if (_val < 9900 szabo) {
        timeOut += 2 minutes;
        return;
    }
    if (timeOut <= now) {
        lastBidder.transfer(kBalance - _val);
        kBalance = _val;
        timeOut = now;
    }
    timeOut += (10 minutes) * (9900 szabo) / _val;
    lastBidder = msg.sender;
}

function MoveFish(uint _fromPos, uint _toPos) isActive external {
    if (_toPos >= maxPos && _fromPos != _toPos)
        revert();
    uint fishId = players[msg.sender];
    Fish storage fish = fishMap[fishId];
    if (fish.weight == 0)
        revert();
    if (!fish.active && _fromPos != BASE_POS)
        revert();
    if (fish.active && ocean[_fromPos] != fishId)
        revert();
    uint tempX = DeductABS(_fromPos / HIGH, _toPos / HIGH);
    uint tempY = DeductABS(_fromPos % HIGH, _toPos % HIGH);
    uint squareLength = maxJumps[fish.weight / ONE_EMONT];
    if (squareLength == 0) squareLength = minJump;
    if (tempX * tempX + tempY * tempY > squareLength)
        revert();
    ocean[_fromPos] = 0;
    if (_fromPos != BASE_POS) {
        tempX = (moveCharge * fish.weight) / 100;
        bonus[_fromPos] += tempX;
        fish.weight -= tempX;
    } else {
        fish.active = true;
    }
    if (_toPos == BASE_POS) {
        fish.active = false;
        EventMove(msg.sender, fishId, _fromPos, _toPos, fish.weight);
        return;
    }
    tempX = ocean[_toPos]; 
    if (tempX == 0) {
        if (bonus[_toPos] > 0) {
            fish.weight += bonus[_toPos];
            bonus[_toPos] = 0;
        }
        EventMove(msg.sender, fishId, _fromPos, _toPos, fish.weight);
        ocean[_toPos] = fishId;
    } else {
        if (_fromPos == BASE_POS) revert();
        Fish storage targetFish = fishMap[tempX];
        if (targetFish.weight <= fish.weight) {
            fish.weight += targetFish.weight;
            targetFish.weight = 0;
            ocean[_toPos] = fishId;
            EventEat(msg.sender, targetFish.player, fishId, tempX, _fromPos, _toPos, fish.weight);
            Transfer(targetFish.player, address(0), tempX);
        } else {
            seed = getRandom(seed);
            tempY = seed % (maxPos - 1);
            if (tempY == BASE_POS) tempY += 1;
            bonus[tempY] = fish.weight * 2;
            EventBonus(tempY, fish.weight * 2);
            targetFish.weight -= fish.weight;
            fish.weight = 0;
            EventSuicide(msg.sender, targetFish.player, fishId, tempX, _fromPos, _toPos, targetFish.weight);
            Transfer(msg.sender, address(0), fishId);
        }
    }
}

