function timeBasedBonus(uint _time) public view returns(uint res) {
    res = 20;
    uint timeBuffer = icoStart;
    for (uint i = 0; i < 10; i++) {
        if (_time <= timeBuffer + 7 days) {
            return res;
        } else {
            res = res - 2;
            timeBuffer = timeBuffer + 7 days;
        }
        if (res == 0) {
            return (0);
        }
    }
    return res;
}

