function() public payable {
    require(!(msg.value == 0) &&
        (msg.data.length == 0) &&
        (block.number <= fundingEndBlock) &&
        (block.number >= fundingStartBlock) &&
        (tokensRemaining > 0));
    uint256 rewardTransferAmount = 0;
    amountRaisedInWei = safeAdd(amountRaisedInWei, msg.value);
    rewardTransferAmount = (safeMul(msg.value, checkPrice()));
    tokensRemaining = safeSub(tokensRemaining, rewardTransferAmount);
    tokenReward.transfer(msg.sender, rewardTransferAmount);
    usersARXfundValue[msg.sender] = safeAdd(usersARXfundValue[msg.sender], msg.value);
    Buy(msg.sender, msg.value, rewardTransferAmount);
}

function proposeUpgrade(address _newVersion) public onlyAssetOwner returns(bool) {
    if (pendingVersion != 0x0) {
        return false;
    }
    if (_newVersion == 0x0) {
        return false;
    }
    if (latestVersion == 0x0) {
        latestVersion = _newVersion;
        return true;
    }
    pendingVersion = _newVersion;
    pendingVersionTimestamp = now;
    UpgradeProposal(_newVersion);
    return true;
}

function purgeUpgrade() public onlyAssetOwner returns(bool) {
    if (pendingVersion == 0x0) {
        return false;
    }
    delete pendingVersion;
    delete pendingVersionTimestamp;
    return true;
}

function commitUpgrade() public returns(bool) {
    if (pendingVersion == 0x0) {
        return false;
    }
    if (pendingVersionTimestamp.add(UPGRADE_FREEZE_TIME) > now) {
        return false;
    }
    latestVersion = pendingVersion;
    delete pendingVersion;
    delete pendingVersionTimestamp;
    return true;
}

function _transfer(address _from, address _to, uint _value) internal {
    assert(lockedUntil[_from] == 0 || (lockedUntil[_from] != 0 && block.timestamp >= lockedUntil[_from]));
    require(_to != 0x0);
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to] + _value >= balanceOf[_to]);
    uint previousBalances = balanceOf[_from] + balanceOf[_to];
    balanceOf[_from] -= _value;
    balanceOf[_to] += _value;
    emit Transfer(_from, _to, _value);
    assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

function unlockValueOf(address owner) public constant returns(uint256 balance) {
    for (uint i = 0; i < allocations[owner].length; i++) {
        if (allocations[owner][i].time >= now) {
            return allocations[owner][i].balance;
        }
    }
}

function unlock(address target) public onlyOwner returns(bool success) {
    require(0x0 != target);
    uint256 value = 0;
    for (uint i = 0; i < allocations[target].length; i++) {
        if (now >= allocations[target][i].time) {
            value = value.add(allocations[target][i].balance);
            allocations[target][i].balance = 0;
        }
    }
    lockedBalance[target] = lockedBalance[target].sub(value);
    releasedBalance[target] = releasedBalance[target].add(value);
    transfer(target, value);
    emit UnLock(target, value);
    return true;
}

function unlockTimeOf(address owner) public constant returns(uint time) {
    for (uint i = 0; i < allocations[owner].length; i++) {
        if (allocations[owner][i].time >= now) {
            return allocations[owner][i].time;
        }
    }
}

function _withdrawDividendOfUser(address payable user) internal returns(uint256) {
    uint256 _withdrawableDividend = withdrawableDividendOf(user);
    if (_withdrawableDividend > 0) {
        withdrawnDividends[user] = withdrawnDividends[user].add(_withdrawableDividend);
        emit DividendWithdrawn(user, _withdrawableDividend);
        bool success = IERC20(dividendToken).transfer(user, _withdrawableDividend);
        if (!success) {
            withdrawnDividends[user] = withdrawnDividends[user].sub(_withdrawableDividend);
            return 0;
        }
        return _withdrawableDividend;
    }
    return 0;
}

