function saneIt()
inState(State.Setup) onlyOwner public {
    require(startTime < endTime);
    require(endTime > now);
    require(price > 0);
    require(wallet != address(0));
    require(token != address(0));
    if (isKnownOnly) {
        require(userRegistry != address(0));
    }
    if (isAmountBonus) {
        require(amountSlicesCount > 0);
    }
    if (isExtraDistribution) {
        require(extraTokensHolder != address(0));
    }
    if (isTransferShipment) {
        require(token.balanceOf(address(this)) >= hardCap);
    } else {
        require(token.owner() == address(this));
    }
    state = State.Active;
}

function finalizeIt(address _futureOwner) inState(State.Active) onlyOwner public {
    require(ended());
    token.transferOwnership(_futureOwner);
    if (success()) {
        state = State.Claim;
    } else {
        state = State.Refund;
    }
}

function sellTokens(address _beneficiary, uint _weiAmount, uint timestamp)
inState(State.Active) internal returns(uint) {
    uint beneficiaryTokens;
    uint extraTokens;
    uint totalTokens;
    uint refererTokens;
    address refererAddress;
    (totalTokens, beneficiaryTokens, extraTokens, refererTokens, refererAddress) = calculateEthAmount(
        _beneficiary,
        _weiAmount,
        timestamp,
        token.totalSupply());
    require(validPurchase(_beneficiary, 
        _weiAmount,
        beneficiaryTokens,
        extraTokens,
        totalTokens,
        timestamp));
    weiRaised = weiRaised.add(_weiAmount); 
    beneficiaryInvest[_beneficiary] = beneficiaryInvest[_beneficiary].add(_weiAmount);
    shipTokens(_beneficiary, beneficiaryTokens); 
    EthBuy(msg.sender, 
        _beneficiary,
        _weiAmount,
        beneficiaryTokens);
    ShipTokens(_beneficiary, beneficiaryTokens);
    if (isExtraDistribution) { 
        shipTokens(extraTokensHolder, extraTokens);
        ShipTokens(extraTokensHolder, extraTokens);
    }
    if (isPersonalBonuses) {
        PersonalBonusRecord storage record = personalBonuses[_beneficiary];
        if (record.refererAddress != address(0) && record.refererBonus > 0) {
            shipTokens(record.refererAddress, refererTokens);
            ShipTokens(record.refererAddress, refererTokens);
        }
    }
    soldTokens = soldTokens.add(totalTokens);
    return beneficiaryTokens;
}

function buyTokens(address _beneficiary) inState(State.Active) public payable {
    require(!isDisableEther);
    uint shipAmount = sellTokens(_beneficiary, msg.value, block.timestamp);
    require(shipAmount > 0);
    forwardEther();
}

function forwardTokens(address _beneficiary, address _tokenAddress, uint _amount) internal returns(bool) {
    TokenInterface allowedToken = allowedTokens[_tokenAddress];
    allowedToken.transferFrom(_beneficiary, address(this), _amount);
    altDeposit[_tokenAddress][_beneficiary] = _amount;
    return true;
}

function setTime(uint _start, uint _end)
inState(State.Setup) onlyOwner public {
    require(_start < _end);
    require(_end > block.timestamp);
    startTime = _start;
    endTime = _end;
}

function validPurchase(
    address _beneficiary,
    uint _weiAmount,
    uint _tokenAmount,
    uint _extraAmount,
    uint _totalAmount,
    uint _time)
public constant returns(bool) {
    _tokenAmount;
    _extraAmount;
    if (isMinimumValue) {
        if (isMinimumInEther && _weiAmount < minimumPurchaseValue) {
            return false;
        }
        if (!isMinimumInEther && _tokenAmount < minimumPurchaseValue) {
            return false;
        }
    }
    if (_time < startTime || _time > endTime) {
        return false;
    }
    if (isKnownOnly && !userRegistry.knownAddress(_beneficiary)) {
        return false;
    }
    uint finalBeneficiaryInvest = beneficiaryInvest[_beneficiary].add(_weiAmount);
    uint finalTotalSupply = soldTokens.add(_totalAmount);
    if (isWhitelisted) {
        WhitelistRecord storage record = whitelist[_beneficiary];
        if (!record.allow ||
            record.min > finalBeneficiaryInvest ||
            record.max < finalBeneficiaryInvest) {
            return false;
        }
    }
    if (isCappedInEther) {
        if (weiRaised.add(_weiAmount) > hardCap) {
            return false;
        }
    } else {
        if (finalTotalSupply > hardCap) {
            return false;
        }
    }
    return true;
}

function ended() public constant returns(bool) {
    return capped() || block.timestamp >= endTime;
}

function calculateTimeBonus(uint _at) public constant returns(uint) {
    uint bonus = 0;
    for (uint index = timeSlices.length; index > 0; index--) {
        if (timeSlices[index - 1] < _at) {
            break;
        }
        bonus = timeBonuses[timeSlices[index - 1]];
    }
    return bonus;
}

function countUp(address _referralAddress) public payable {
    require(block.timestamp < lastTransactionTime + 7 days);
    require(msg.value == nextPrice);
    uint128 _price = uint128(msg.value);
    uint128 _processing;
    totalCount++;
    currentCount++;
    _processing = _payFee(_price, _referralAddress);
    if (currentCount > 1) {
        lastCountAddress.transfer(_processing);
    } else {
        sumPrice = sumPrice + _processing;
    }
    if (currentCount == randomCount) {
        Hit(msg.sender, currentCount);
        _renew();
    } else {
        if (currentCount == 7) {
            if (sevenWinnerAddresses.length < 7) {
                sevenWinnerAddresses.push(msg.sender);
            } else {
                if (sumPrice <= bonusPrice) {
                    msg.sender.transfer(sumPrice);
                    sumPrice = 0;
                } else {
                    msg.sender.transfer(bonusPrice);
                    sumPrice = sumPrice - bonusPrice;
                }
            }
            _renew();
        } else {
            nextPrice = nextPrice * 3 / 2;
        }
        Count(msg.sender, currentCount);
    }
    _keepLastTransaction();
}

function ownerWithdraw() public onlyOwner {
    require(block.timestamp > lastTransactionTime + 7 days);
    if (round_after < 77 && sevenWinnerAddresses.length > 0) {
        uint128 sevensWinnerBack = (ownerBank + sumPrice) / uint8(sevenWinnerAddresses.length) - 0.0000007 ether;
        uint8 i;
        for (i = 0; i < sevenWinnerAddresses.length; i++) {
            addressToBalance[sevenWinnerAddresses[i]] = addressToBalance[sevenWinnerAddresses[i]] + sevensWinnerBack;
        }
    } else {
        owner.transfer(this.balance);
    }
    sumPrice = 0;
    ownerBank = 0;
}

function sevenWinnerWithdraw() public {
    require(addressToBalance[msg.sender] > 0);
    msg.sender.transfer(addressToBalance[msg.sender]);
    addressToBalance[msg.sender] = 0;
}

function _payFee(uint128 _price, address _referralAddress) internal returns(uint128 _processing) {
    uint128 _cut = _price / 100;
    _processing = _price - _cut;
    if (_referralAddress != address(0)) {
        _referralAddress.transfer(_cut);
    } else {
        ownerBank = ownerBank + _cut;
    }
    uint8 i;
    for (i = 0; i < sevenWinnerAddresses.length; i++) {
        addressToBalance[sevenWinnerAddresses[i]] = addressToBalance[sevenWinnerAddresses[i]] + _cut;
        _processing = _processing - _cut;
    }
    uint128 _remaining = (7 - uint8(sevenWinnerAddresses.length)) * _cut;
    ownerBank = ownerBank + _remaining;
    _processing = _processing - _remaining;
}

function delegateFrom(address from, address to) private {
    require(to != address(0), "cannot delegate to a zero address");
    DelegateFromVars memory vars;
    StakeOwnerData memory delegatorData = getStakeOwnerData(from);
    address prevDelegate = delegatorData.delegation;
    if (to == prevDelegate) return; 
    if (delegatorData.stake == 0 && uncappedDelegatedStake[from] == 0) {
        stakeOwnersData[from].delegation = to;
        emit Delegated(from, to);
        return;
    }
    vars.prevDelegateStatusBefore = getDelegateStatus(prevDelegate);
    vars.newDelegateStatusBefore = getDelegateStatus(to);
    stakingRewardsContract.delegationWillChange(prevDelegate, vars.prevDelegateStatusBefore.delegatedStake, from, delegatorData.stake, to, vars.newDelegateStatusBefore.delegatedStake);
    stakeOwnersData[from].delegation = to;
    uint256 delegatorStake = delegatorData.stake;
    uncappedDelegatedStake[prevDelegate] = vars.prevDelegateStatusBefore.uncappedDelegatedStake.sub(delegatorStake);
    uncappedDelegatedStake[to] = vars.newDelegateStatusBefore.uncappedDelegatedStake.add(delegatorStake);
    vars.prevDelegateStatusAfter = getDelegateStatus(prevDelegate);
    vars.newDelegateStatusAfter = getDelegateStatus(to);
    uint256 _totalDelegatedStake = totalDelegatedStake.sub(
        vars.prevDelegateStatusBefore.delegatedStake
    ).add(
        vars.prevDelegateStatusAfter.delegatedStake
    ).sub(
        vars.newDelegateStatusBefore.delegatedStake
    ).add(
        vars.newDelegateStatusAfter.delegatedStake
    );
    totalDelegatedStake = _totalDelegatedStake;
    emit Delegated(from, to);
    IElections _electionsContract = electionsContract;
    if (vars.prevDelegateStatusBefore.delegatedStake != vars.prevDelegateStatusAfter.delegatedStake) {
        _electionsContract.delegatedStakeChange(
            prevDelegate,
            vars.prevDelegateStatusAfter.selfDelegatedStake,
            vars.prevDelegateStatusAfter.delegatedStake,
            _totalDelegatedStake
        );
        emit DelegatedStakeChanged(
            prevDelegate,
            vars.prevDelegateStatusAfter.selfDelegatedStake,
            vars.prevDelegateStatusAfter.delegatedStake,
            from,
            0
        );
    }
    if (vars.newDelegateStatusBefore.delegatedStake != vars.newDelegateStatusAfter.delegatedStake) {
        _electionsContract.delegatedStakeChange(
            to,
            vars.newDelegateStatusAfter.selfDelegatedStake,
            vars.newDelegateStatusAfter.delegatedStake,
            _totalDelegatedStake
        );
        emit DelegatedStakeChanged(
            to,
            vars.newDelegateStatusAfter.selfDelegatedStake,
            vars.newDelegateStatusAfter.delegatedStake,
            from,
            delegatorStake
        );
    }
}

