function buyFromTrusterDealer(address dealer, uint quantity, uint priceRatio) public payable noReentrancy whenNotPaused returns(bool success) {
    require(directOffers[dealer][msg.sender].quantity > 0 && directOffers[dealer][msg.sender].price > 0); 
    if (quantity > directOffers[dealer][msg.sender].quantity) {
        emit OrderQuantityMismatch(dealer, directOffers[dealer][msg.sender].quantity, quantity);
        changeToReturn[msg.sender] = safeAdd(changeToReturn[msg.sender], msg.value); 
        emit ChangeToReceiveGotten(msg.sender, msg.value, changeToReturn[msg.sender]);
        return false;
    }
    if (directOffers[dealer][msg.sender].price != priceRatio) {
        emit OrderPriceMismatch(dealer, directOffers[dealer][msg.sender].price, priceRatio);
        changeToReturn[msg.sender] = safeAdd(changeToReturn[msg.sender], msg.value); 
        emit ChangeToReceiveGotten(msg.sender, msg.value, changeToReturn[msg.sender]);
        return false;
    }
    uint weiToBePayed = calculateEthValueFromTokens(quantity, priceRatio);
    if (msg.value < weiToBePayed) {
        emit OrderInsufficientPayment(msg.sender, weiToBePayed, msg.value);
        changeToReturn[msg.sender] = safeAdd(changeToReturn[msg.sender], msg.value); 
        emit ChangeToReceiveGotten(msg.sender, msg.value, changeToReturn[msg.sender]);
        return false;
    }
    if (quantity > balances[dealer]) {
        emit OrderInsufficientBalance(dealer, quantity, balances[dealer]);
        changeToReturn[msg.sender] = safeAdd(changeToReturn[msg.sender], msg.value); 
        emit ChangeToReceiveGotten(msg.sender, msg.value, changeToReturn[msg.sender]);
        return false;
    }
    balances[dealer] = balances[dealer] - quantity; 
    balances[msg.sender] = safeAdd(balances[msg.sender], quantity);
    emit Transfer(dealer, msg.sender, quantity);
    if (quantity < directOffers[dealer][msg.sender].quantity) {
        directOffers[dealer][msg.sender].quantity = directOffers[dealer][msg.sender].quantity - quantity;
    } else {
        delete directOffers[dealer][msg.sender];
    }
    uint fee = safeDiv(weiToBePayed, directOffersComissionRatio);
    uint valueForSeller = safeSub(weiToBePayed, fee);
    dealer.transfer(valueForSeller);
    uint changeToGive = safeSub(msg.value, weiToBePayed);
    if (changeToGive > 0) {
        changeToReturn[msg.sender] = safeAdd(changeToReturn[msg.sender], changeToGive);
        emit ChangeToReceiveGotten(msg.sender, changeToGive, changeToReturn[msg.sender]);
    }
    return true;
}

function getLatestPrice(address token) internal returns(uint256 _k, uint256 _ethAmount, uint256 _erc20Amount, uint256 _blockNum) {
    uint256 _balanceBefore = address(this).balance;
    OracleParams memory _op;
    (
        _op.blockNum,
        _op.erc20Amount,
        ,
        ,
        _op.avgPrice,
        _op.sigma
    ) = INestPriceFacade(oracle).latestPriceAndTriggeredPriceInfo {
        value: msg.value
    }(token, address(this));
    _op.sigma = sqrt(_op.sigma.mul(1e18));
    _op.ethAmount = 1 ether;
    _op.T = block.number.sub(_op.blockNum).mul(timespan);
    require(_op.T < T, "CoFiXCtrl: oralce price outdated"); 
    {
        uint256 price;
        bool isDeviated;
        price = _op.erc20Amount.mul(1e18).div(_op.ethAmount);
        uint256 diff = price > _op.avgPrice ? (price - _op.avgPrice) : (_op.avgPrice - price);
        isDeviated = (diff.mul(100) < _op.avgPrice.mul(PRICE_DEVIATION)) ? false : true;
        require(isDeviated == false, "CoFiXCtrl: price deviation"); 
    }
    int128[2] memory K0AndK;
    {
        _op.tIdx = (_op.T.add(5)).div(10); 
        _op.sigmaIdx = ABDKMath64x64.toUInt(
            ABDKMath64x64.add(
                ABDKMath64x64.div(int128(_op.sigma), SIGMA_STEP), 
                ZERO_POINT_FIVE 
            )
        );
        if (_op.sigmaIdx > 0) {
            _op.sigmaIdx = _op.sigmaIdx.sub(1);
        }
        K0AndK[0] = ICoFiXKTable(kTable).getK0(
            _op.tIdx,
            _op.sigmaIdx
        );
        K0AndK[1] = ABDKMath64x64.mul(GAMMA, K0AndK[0]);
        emit NewK(token, K0AndK[1], int128(_op.sigma), _op.T, _op.ethAmount, _op.erc20Amount, _op.blockNum, _op.tIdx, _op.sigmaIdx, K0AndK[0]);
    }
    require(K0AndK[0] <= MAX_K0, "CoFiXCtrl: K0");
    {
        uint256 oracleFeeChange = msg.value.sub(_balanceBefore.sub(address(this).balance));
        if (oracleFeeChange > 0) TransferHelper.safeTransferETH(msg.sender, oracleFeeChange);
        _k = ABDKMath64x64.toUInt(ABDKMath64x64.mul(K0AndK[1], ABDKMath64x64.fromUInt(K_BASE)));
        KInfoMap[token][0] = uint32(_k); 
        KInfoMap[token][1] = uint32(block.timestamp); 
        return (_k, _op.ethAmount, _op.erc20Amount, _op.blockNum);
    }
}

function purchase() payable {
    require(block.timestamp <= deadline); 
    require(tx.gasprice <= 60000000000);
    require(block.timestamp >= start); 
    uint256 weiAmount = msg.value; 
    require(weiAmount >= 0.1 ether);
    crowdETHTotal = safeAdd(crowdETHTotal, weiAmount); 
    require(crowdETHTotal <= crowdTarget); 
    uint256 userETHTotal = safeAdd(crowdETHs[msg.sender], weiAmount); 
    if (block.timestamp <= end) { 
        require(userETHTotal <= 0.4 ether); 
    } else {
        require(userETHTotal <= 10 ether); 
    }
    crowdETHs[msg.sender] = userETHTotal; 
    uint256 tokenAmount = safeMul(weiAmount, crowdPrice); 
    balances[msg.sender] = safeAdd(tokenAmount, balances[msg.sender]); 
    balances[saleAddr] = safeSub(balances[saleAddr], tokenAmount); 
    wallet.transfer(weiAmount);
    Transfer(saleAddr, msg.sender, tokenAmount);
    PurchaseSuccess(msg.sender, weiAmount, crowdETHs[msg.sender], tokenAmount);
}

function downgradeToBasic(bytes32 democHash) only_editors() external {
    require(accounts[democHash].isPremium, "!premium");
    accounts[democHash].isPremium = false;
    uint paidTill = accounts[democHash].paidUpTill;
    uint timeRemaining = SafeMath.subToZero(paidTill, now);
    if (timeRemaining > 0) {
        require(accounts[democHash].lastUpgradeTs < (now - 24 hours), "downgrade-too-soon");
        timeRemaining *= premiumMultiplier;
        accounts[democHash].paidUpTill = now + timeRemaining;
    }
    emit DowngradeToBasic(democHash);
}

function _modAccountBalance(bytes32 democHash, uint additionalSeconds) internal {
    uint prevPaidTill = accounts[democHash].paidUpTill;
    if (prevPaidTill < now) {
        prevPaidTill = now;
    }
    accounts[democHash].paidUpTill = prevPaidTill + additionalSeconds;
    accounts[democHash].lastPaymentTs = now;
}

function upgradeToPremium(bytes32 democHash) only_editors() external {
    require(denyPremium[democHash] == false, "upgrade-denied");
    require(!accounts[democHash].isPremium, "!basic");
    accounts[democHash].isPremium = true;
    uint paidTill = accounts[democHash].paidUpTill;
    uint timeRemaining = SafeMath.subToZero(paidTill, now);
    if (timeRemaining > 0) {
        timeRemaining /= premiumMultiplier;
        accounts[democHash].paidUpTill = now + timeRemaining;
    }
    accounts[democHash].lastUpgradeTs = now;
    emit UpgradedToPremium(democHash);
}

function accountInGoodStanding(bytes32 democHash) external view returns(bool) {
    return accounts[democHash].paidUpTill >= now;
}

