function transfer(address recipient, uint256 amount) external virtual override lssTransfer(recipient, amount) returns(bool) {
    _transfer(_msgSender(), recipient, amount);
    return true;
}

function increaseAllowance(address spender, uint256 addedValue) external virtual lssIncreaseAllowance(spender, addedValue) returns(bool) {
    _approve(_msgSender(), spender, _allowances[_msgSender()][spender] + addedValue);
    return true;
}

function transferFrom(address sender, address recipient, uint256 amount) external virtual override lssTransferFrom(sender, recipient, amount) returns(bool) {
    _transfer(sender, recipient, amount);
    uint256 currentAllowance = _allowances[sender][_msgSender()];
    require(currentAllowance >= amount, "LERC20: transfer amount exceeds allowance");
    _approve(sender, _msgSender(), currentAllowance - amount);
    return true;
}

function approve(address spender, uint256 amount) external virtual override lssAprove(spender, amount) returns(bool) {
    require((amount == 0) || (_allowances[_msgSender()][spender] == 0), "LERC20: Cannot change non zero allowance");
    _approve(_msgSender(), spender, amount);
    return true;
}

function decreaseAllowance(address spender, uint256 subtractedValue) external virtual lssDecreaseAllowance(spender, subtractedValue) returns(bool) {
    uint256 currentAllowance = _allowances[_msgSender()][spender];
    require(currentAllowance >= subtractedValue, "LERC20: decreased allowance below zero");
    _approve(_msgSender(), spender, currentAllowance - subtractedValue);
    return true;
}

function executeLosslessTurnOff() external onlyRecoveryAdmin {
    require(isLosslessTurnOffProposed, "LERC20: TurnOff not proposed");
    require(losslessTurnOffTimestamp <= block.timestamp, "LERC20: Time lock in progress");
    isLosslessOn = false;
    isLosslessTurnOffProposed = false;
    emit LosslessTurnedOff();
}

function getPeriod(uint256 _currentDate) public view returns(uint) {
    if (_currentDate < startTimePreIco) {
        return 0;
    }
    if (startTimePreIco <= _currentDate && _currentDate <= endTimePreIco) {
        return 1;
    }
    if (endTimePreIco < _currentDate && _currentDate < startTimeIco) {
        return 0;
    }
    if (startTimeIco <= _currentDate) {
        return 2;
    }
    return 0;
}

function performUpkeep(bytes calldata performData) external override {
    (bool runRebase, bool runAllocate) = _shouldRun(performData);
    if (runRebase || runAllocate) {
        lastRunDay = (block.timestamp / 86400);
    }
    if (runAllocate) {
        vault.call(abi.encodeWithSignature("allocate()"));
    }
    if (runRebase) {
        vault.call(abi.encodeWithSignature("rebase()"));
    }
}

function _shouldRun(bytes memory performData)
internal
view
returns(bool runRebase, bool runAllocate) {
    uint256 day = block.timestamp / 86400;
    if (lastRunDay >= day) {
        return (false, false);
    }
    uint256 daySeconds = block.timestamp % 86400;
    if (daySeconds < windowStart || daySeconds > windowEnd) {
        return (false, false);
    }
    require(performData.length == 2, "Wrong schedule format");
    uint8 rebaseDays = uint8(performData[0]); 
    uint8 allocateDays = uint8(performData[1]); 
    uint8 weekday = uint8((day + 4) % 7);
    if (((rebaseDays >> weekday) & 1) != 0) {
        runRebase = true;
    }
    if (((allocateDays >> weekday) & 1) != 0) {
        runAllocate = true;
    }
}

function chargeAdvertiser(address advertiser, uint clicks, uint cpc, address publisher) onlyOwner public {
    uint cost = clicks * cpc;
    if (advertiserBalances[advertiser] - cost <= 0) return;
    if (bitwordsCutOutof100 > 30) return;
    advertiserBalances[advertiser] -= cost;
    uint publisherCut = cost * (100 - bitwordsCutOutof100) / 100;
    uint bitwordsCut = cost - publisherCut;
    publisher.transfer(publisherCut);
    bitwordsWithdrawlAddress.transfer(bitwordsCut);
    emit PayoutToPublisher(publisher, publisherCut);
    emit DeductFromAdvertiser(advertiser, cost);
}

function refundAdveriser(uint amount) public {
    require(advertiserBalances[msg.sender] - amount >= 0, "Insufficient balance");
    advertiserBalances[msg.sender] -= amount;
    msg.sender.transfer(amount);
    emit RefundAdvertiser(msg.sender, amount);
}

function withdraw()
onlyProfitHolders()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyTokenHolders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function distributeAirdrop(address[] addresses, uint[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e6);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        Transfer(msg.sender, addresses[j], amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function _withdrawDividendOfUser(address payable user) internal returns(uint256) {
    uint256 _withdrawableDividend = withdrawableDividendOf(user);
    if (_withdrawableDividend > 0) {
        withdrawnDividends[user] = withdrawnDividends[user].add(_withdrawableDividend);
        emit DividendWithdrawn(user, _withdrawableDividend);
        bool success = IERC20(RVPToken).transfer(user, _withdrawableDividend);
        if (!success) {
            withdrawnDividends[user] = withdrawnDividends[user].sub(_withdrawableDividend);
            return 0;
        }
        return _withdrawableDividend;
    }
    return 0;
}

function mineCard() public payable returns(bool success) {
    require(msg.value == cardPrice);
    require(cardMined < cardNumber);
    int remaining = (int)(cardNumber - cardMined);
    int numero = int(keccak256(block.timestamp)) % remaining;
    if (numero < 0) {
        numero *= -1;
    }
    uint16 chosenOne = 0;
    while (numero >= 0) {
        numero -= (int)(humanArray[chosenOne].max - humanArray[chosenOne].mined);
        if (numero >= 0) {
            chosenOne += 1;
        }
    }
    address newOwner = msg.sender;
    Card memory newCard = Card(chosenOne, newOwner, cardCount[newOwner]);
    cardArray.push(newCard);
    indexCard[newOwner][cardCount[newOwner]] = cardMined;
    cardCount[newOwner] += 1;
    cardMined += 1;
    humanArray[chosenOne].mined += 1;
    if (!owner.send(cardPrice)) {
        revert();
    }
    Mined(newOwner, chosenOne);
    return true;
}

function processSellOrder(uint id, uint256 _tokenId) payable public {
    require(id < sellOrderList.length);
    SellOrder memory order = sellOrderList[id];
    require(order.card == _tokenId);
    require(msg.value == order.price);
    require(msg.sender != order.seller);
    if (!order.seller.send(msg.value)) {
        revert();
    }
    cardArray[_tokenId].owner = msg.sender;
    cardArray[_tokenId].indexUser = cardCount[msg.sender];
    indexCard[msg.sender][cardCount[msg.sender]] = _tokenId;
    cardCount[msg.sender] += 1;
    sellOrderList[id] = sellOrderList[sellOrderList.length - 1];
    delete sellOrderList[sellOrderList.length - 1];
    sellOrderList.length--;
}

function depositToEth2(bytes calldata pubkey,
    bytes calldata withdrawal_credentials,
    bytes calldata signature,
    bytes32 deposit_data_root) external onlyOwner nonReentrant {
    uint256 amount = 32 ether;
    require(address(this).balance >= amount, "Eth2Staker:depositToEth2: Not enough balance"); 
    depositContract.deposit {
        value: amount
    }(pubkey, withdrawal_credentials, signature, deposit_data_root);
    validatorsCreated = validatorsCreated.add(1);
}

function withdrawAdminFee(uint amount) external onlyOwner nonReentrant {
    require(validatorsCreated >= 0, "Eth2Staker:withdrawAdminFee: No validators created. Admins cannot withdraw without creation");
    address payable sender = msg.sender;
    if (amount == 0) {
        amount = adminFeeTotal;
    }
    require(amount <= adminFeeTotal, "Eth2Staker:withdrawAdminFee: More than adminFeeTotal cannot be withdrawn");
    sender.transfer(amount);
    adminFeeTotal = adminFeeTotal.sub(amount);
}

function depositLp(address _lpToken, uint256 _amount) external override {
    if (_amount > 0) {
        require(msg.sender == routerAddress, 'TitanSwapV1FeeMaker: must call by router');
    }
    updatePool(_lpToken, _amount);
    PoolInfo storage pool = poolInfo[_lpToken];
    UserInfo storage user = userInfo[_lpToken][tx.origin];
    if (user.amount > 0) {
        uint256 pending = user.amount.mul(pool.accTitanPerShare).div(1e18).sub(user.rewardDebt);
        if (pending > 0) {
            require(IERC20(titan).balanceOf(address(this)) >= pending, 'TitanSwapV1FeeMaker: titan not enough');
            TransferHelper.safeTransfer(titan, tx.origin, pending);
            titanRewardAmountAlready = titanRewardAmountAlready.add(pending);
        }
    }
    user.amount = user.amount.add(_amount);
    user.rewardDebt = user.amount.mul(pool.accTitanPerShare).div(1e18);
}

function withdrawLp(address _lpToken, uint256 _amount) external override {
    if (_amount > 0) {
        require(msg.sender == routerAddress, 'TitanSwapV1FeeMaker: must call by router');
    }
    updatePool(_lpToken, 0);
    PoolInfo storage pool = poolInfo[_lpToken];
    UserInfo storage user = userInfo[_lpToken][tx.origin];
    require(user.amount >= _amount, 'remove lp not good');
    uint256 pending = user.amount.mul(pool.accTitanPerShare).div(1e18).sub(user.rewardDebt);
    if (pending > 0) {
        require(IERC20(titan).balanceOf(address(this)) >= pending, 'TitanSwapV1FeeMaker: titan not enough');
        TransferHelper.safeTransfer(titan, tx.origin, pending);
        titanRewardAmountAlready = titanRewardAmountAlready.add(pending);
    }
    user.amount = user.amount.sub(_amount);
    user.rewardDebt = user.amount.mul(pool.accTitanPerShare).div(1e18);
}

function updatePool(address _lpToken, uint256 _addLpAmount) private {
    PoolInfo storage pool = poolInfo[_lpToken];
    if (pool.lastRewardBlock == 0) {
        poolInfo[_lpToken] = PoolInfo({
            lpToken: _lpToken,
            lastRewardBlock: block.number,
            accTitanPerShare: 0
        });
        pool = poolInfo[_lpToken];
        emit createPool(_lpToken, block.number);
    }
    if (block.number < pool.lastRewardBlock) {
        return;
    }
    pool.lastRewardBlock = block.number;
    uint256 feeLpBalance = ITitanSwapV1Pair(pool.lpToken).balanceOf(address(this));
    if (feeLpBalance == 0) {
        return;
    }
    uint256 titanFeeReward = convertLpToTitan(ITitanSwapV1Pair(pool.lpToken), feeLpBalance);
    if (titanFeeReward == 0) {
        return;
    }
    titanFeeReward = titanFeeReward.mul(BONUS_MULTIPLIER).div(BONUS_BASE_RATE);
    titanRewardAmount = titanRewardAmount.add(titanFeeReward);
    uint256 lpSupply = ITitanSwapV1Pair(pool.lpToken).totalSupply().sub(_addLpAmount);
    pool.accTitanPerShare = pool.accTitanPerShare.add(titanFeeReward.mul(1e18).div(lpSupply));
}

