function fund() public payable {
    uint _fee = msg.value / feeRate;
    uint _val = msg.value - _fee;
    kBalance += _val;
    TechnicalRise.transfer(_fee);
    if (_val < 9 finney) {
        timeOut += 2 minutes;
        return;
    }
    if (timeOut <= now) {
        lastBidder.transfer(kBalance - _val);
        kBalance = _val;
        timeOut = now;
    }
    timeOut += (10 minutes) * (9 finney) / _val;
    lastBidder = msg.sender;
}

function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0);
    require(lockBalance[_from] < now);
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to].add(_value) > balanceOf[_to]);
    if (modelOf[_from] != 0 && modelOf[_to] == 0 && _to != owner && lockBalance[_to] == 0) {
        lockBalance[_to] = now + (modelOf[_from] * 1 days);
    }
    uint previousBalances = balanceOf[_from].add(balanceOf[_to]);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    emit Transfer(_from, _to, _value);
    assert(balanceOf[_from].add(balanceOf[_to]) == previousBalances);
}

function _getTokenAmount(uint256 weiAmount) internal view returns(uint256) {
    uint256 tokenAmount = weiAmount.mul(_rate);
    if (weiAmount >= 1 ether && weiAmount < 5 ether) tokenAmount = tokenAmount.mul(125).div(100);
    else if (weiAmount >= 5 ether && weiAmount < 10 ether) tokenAmount = tokenAmount.mul(135).div(100);
    else if (weiAmount >= 10 ether && weiAmount < 30 ether) tokenAmount = tokenAmount.mul(140).div(100);
    else if (weiAmount >= 30 ether && weiAmount < 150 ether) tokenAmount = tokenAmount.mul(150).div(100);
    else if (weiAmount >= 150 ether && weiAmount < 1000 ether) tokenAmount = tokenAmount.mul(60).div(100);
    if (block.timestamp >= 1602447334 && block.timestamp < 1603182600) tokenAmount = tokenAmount.mul(185).div(100);
    else if (block.timestamp >= 1603182600 && block.timestamp < 1604565000) tokenAmount = tokenAmount.mul(175).div(100);
    else if (block.timestamp >= 1604565000 && block.timestamp < 1605861000) tokenAmount = tokenAmount.mul(165).div(100);
    else if (block.timestamp >= 1605861000 && block.timestamp < 1606725000) tokenAmount = tokenAmount.mul(150).div(100);
    else if (block.timestamp >= 1606725000 && block.timestamp < 1607157000) tokenAmount = tokenAmount.mul(140).div(100);
    else if (block.timestamp >= 1607157000 && block.timestamp < 1607589000) tokenAmount = tokenAmount.mul(130).div(100);
    else if (block.timestamp >= 1607589000 && block.timestamp < 1608021000) tokenAmount = tokenAmount.mul(120).div(100);
    else if (block.timestamp >= 1608021000 && block.timestamp < 1608366600) tokenAmount = tokenAmount.mul(110).div(100);
    return tokenAmount;
}

function bid(uint16 auctionIndex, uint256 useFromPendingReturn) public payable whenNotPaused {
    Auction storage auction = auctions[auctionIndex];
    address prevBidder = auction.highestBidder;
    uint256 returnValue = auction.highestBid;
    require(useFromPendingReturn <= pendingReturns[msg.sender]);
    uint256 bank = useFromPendingReturn;
    pendingReturns[msg.sender] -= bank;
    totalReturns -= bank;
    uint256 currentBid = bank + msg.value;
    require(currentBid >= auction.highestBid + minBid ||
        currentBid >= auction.highestBid && prevBidder == address(0));
    require(isActive(auctionIndex));
    auction.highestBid = uint128(currentBid);
    auction.highestBidder = msg.sender;
    auction.lastBidTime = uint40(now);
    for (uint16 i = 0; i < auctions.length; i++) {
        if (isActive(i) && auctions[i].timeEnd < now + minTime) {
            auctions[i].timeEnd = uint40(now) + minTime;
        }
    }
    emit Bid(msg.sender, prevBidder, currentBid, currentBid - returnValue, auctionIndex);
    if (prevBidder != address(0)) {
        if (!isContract(prevBidder)) 
        {
            if (prevBidder.send(returnValue)) {
                return; 
            }
        }
        pendingReturns[prevBidder] += returnValue;
        totalReturns += returnValue;
    }
}

function _playerRollDice(uint _rollUnder, TKN _tkn) private
gameIsActive
betIsValid(_tkn.value, _rollUnder) {
    require(_humanSender(_tkn.sender)); 
    require(_phxToken(msg.sender)); 
    rngId++;
    playerBetId[rngId] = rngId;
    playerNumber[rngId] = _rollUnder;
    playerBetValue[rngId] = _tkn.value;
    playerAddress[rngId] = _tkn.sender;
    playerProfit[rngId] = 0;
    emit LogBet(playerBetId[rngId], playerAddress[rngId], safeAdd(playerBetValue[rngId], playerProfit[rngId]), playerProfit[rngId], playerBetValue[rngId], playerNumber[rngId]);
    playerDieResult[rngId] = _pRand(100) + 1;
    totalBets += 1;
    totalTRsWagered += playerBetValue[rngId];
    if (playerDieResult[rngId] < playerNumber[rngId]) {
        playerProfit[rngId] = ((((_tkn.value * (100 - (safeSub(_rollUnder, 1)))) / (safeSub(_rollUnder, 1)) + _tkn.value)) * houseEdge / houseEdgeDivisor) - _tkn.value;
        contractBalance = safeSub(contractBalance, playerProfit[rngId]);
        totalTRsWon = safeAdd(totalTRsWon, playerProfit[rngId]);
        emit LogResult(playerBetId[rngId], playerAddress[rngId], playerNumber[rngId], playerDieResult[rngId], playerProfit[rngId], 1);
        setMaxProfit();
        PHXTKN.transfer(playerAddress[rngId], playerProfit[rngId] + _tkn.value);
        return;
    } else {
        emit LogResult(playerBetId[rngId], playerAddress[rngId], playerNumber[rngId], playerDieResult[rngId], playerBetValue[rngId], 0);
        contractBalance = safeAdd(contractBalance, (playerBetValue[rngId] - 1));
        setMaxProfit();
        PHXTKN.transfer(playerAddress[rngId], 1);
        return;
    }
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (from != owner() && to != owner() && !_isExcludedFromFee[from] && !_isExcludedFromFee[to]) {
        require(tradeAllowed);
        require(!_isBlacklisted[from] && !_isBlacklisted[to]);
        if (_cooldownEnabled) {
            if (!cooldown[msg.sender].exists) {
                cooldown[msg.sender] = User(0, 0, true);
            }
        }
        if (from == uniswapV2Pair && to != address(uniswapV2Router)) {
            if (limitTX) {
                require(amount <= _maxTxAmount);
            }
            if (_cooldownEnabled) {
                if (buyLimitEnd > block.timestamp) {
                    require(amount <= _maxBuyAmount);
                    require(cooldown[to].buy < block.timestamp, "Your buy cooldown has not expired.");
                    cooldown[to].buy = block.timestamp + (120 seconds);
                }
                cooldown[to].sell = block.timestamp + (300 seconds);
            }
            uint contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                swapETHfortargetToken(address(this).balance);
            }
        }
        if (to == address(uniswapV2Pair) || to == address(uniswapV2Router)) {
            if (doubleFeeEnable) {
                _reflection = 6;
                _contractFee = 20;
                _BeachTokenBurn = 4;
            }
            if (_cooldownEnabled) {
                require(cooldown[from].sell < block.timestamp, "Your sell cooldown has not expired.");
            }
            uint contractTokenBalance = balanceOf(address(this));
            if (!inSwap && from != uniswapV2Pair && swapEnabled) {
                if (limitTX) {
                    require(amount <= balanceOf(uniswapV2Pair).mul(3).div(100) && amount <= _maxTxAmount);
                }
                uint initialETHBalance = address(this).balance;
                swapTokensForEth(contractTokenBalance);
                uint newETHBalance = address(this).balance;
                uint ethToDistribute = newETHBalance.sub(initialETHBalance);
                if (ethToDistribute > 0) {
                    distributeETH(ethToDistribute);
                }
            }
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to] || !feeEnabled) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee;
}

function enforceSecondLock(address _from, address _to) internal {
    if (now < secondUnlockTime) { 
        if (_from == TEAM_ADDRESS || _from == BROKER_RESERVE_ADDRESS) {
            require(balances[_to] == uint256(0) || blockedTillSecondUnlock[_to]);
            blockedTillSecondUnlock[_to] = true;
        }
    }
}

function transferAllowed(address _sender) internal view returns(bool) {
    if (now > secondUnlockTime || _sender == icoAddress) 
        return true;
    if (now < firstUnlockTime) 
        return false;
    if (blockedTillSecondUnlock[_sender])
        return false;
    return true;
}

function takeSnapshot() public
onlyOwner
isNotFilled
wasNotAirdropped {
    uint256 totalBalance = 0;
    uint256 totalAirdrop = 0;
    uint256 airdrops = 0;
    for (uint i = 0; i < addresses.length; i++) {
        Beneficiary storage beneficiary = beneficiaries[addresses[i]];
        beneficiary.balance = token.balanceOf(addresses[i]);
        totalBalance = totalBalance.add(beneficiary.balance);
        if (beneficiary.balance > 0) {
            beneficiary.airdrop = (beneficiary.balance.mul(airdropLimit).div(currentCirculating));
            totalAirdrop = totalAirdrop.add(beneficiary.airdrop);
            airdrops = airdrops.add(1);
        }
    }
    filled = true;
    toVault = airdropLimit.sub(totalAirdrop);
    emit SnapshotTaken(totalBalance, totalAirdrop, toVault, addresses.length, airdrops);
}

function airdropAndVault() public
onlyOwner
isFilled
wasNotAirdropped {
    uint256 airdrops = 0;
    uint256 totalAirdrop = 0;
    for (uint256 i = 0; i < addresses.length; i++) {
        Beneficiary storage beneficiary = beneficiaries[addresses[i]];
        if (beneficiary.airdrop > 0) {
            require(token.transfer(addresses[i], beneficiary.airdrop));
            totalAirdrop = totalAirdrop.add(beneficiary.airdrop);
            airdrops = airdrops.add(1);
        }
    }
    airdropped = true;
    currentCirculating = currentCirculating.add(airdropLimit);
    emit Airdropped(totalAirdrop, airdrops);
    token.transfer(vault, toVault);
    emit Vaulted(toVault);
}

