        }
    }
    require(false);
}

function hasClosed() public view returns(bool) {
    for (uint i = 0; i < MAX_FUND_SIZE; ++i) {
        if (openingTimeArray[i] <= now && now <= closingTimeArray[i]) {
            return false;
        }
    }
    return true;
}

