            ERC820_ACCEPT_MAGIC);
    }
    interfaces[addr][iHash] = implementer;
    InterfaceImplementerSet(addr, iHash, implementer);
}

function lowCompose(uint256 token1, uint256 token2)
external
whenNotPaused {
    require(tokenContract.ownerOf(token1) == msg.sender);
    require(tokenContract.ownerOf(token2) == msg.sender);
    require(!equipContract.isEquipedAny2(msg.sender, token1, token2));
    if (address(auctionContract) != address(0)) {
        require(!auctionContract.isOnSaleAny2(token1, token2));
    }
    tokenContract.ownerOf(token1);
    uint16 protoId;
    uint16 quality;
    uint16 pos;
    uint16[12] memory fashionData = tokenContract.getFashion(token1);
    protoId = fashionData[0];
    quality = fashionData[1];
    pos = fashionData[2];
    require(quality == 1 || quality == 2);
    fashionData = tokenContract.getFashion(token2);
    require(protoId == fashionData[0]);
    require(quality == fashionData[1]);
    require(pos == fashionData[2]);
    uint256 seed = _rand();
    uint16[9] memory attrs = _getFashionParam(seed, protoId, quality + 1, pos);
    tokenContract.destroyFashion(token1, 1);
    tokenContract.destroyFashion(token2, 1);
    uint256 newTokenId = tokenContract.createFashion(msg.sender, attrs, 3);
    ComposeSuccess(msg.sender, newTokenId, attrs[0], attrs[1], attrs[2]);
}

function highCompose(uint256 token1, uint256 token2, uint256 token3)
external
whenNotPaused {
    require(tokenContract.ownerOf(token1) == msg.sender);
    require(tokenContract.ownerOf(token2) == msg.sender);
    require(tokenContract.ownerOf(token3) == msg.sender);
    require(!equipContract.isEquipedAny3(msg.sender, token1, token2, token3));
    if (address(auctionContract) != address(0)) {
        require(!auctionContract.isOnSaleAny3(token1, token2, token3));
    }
    uint16 protoId;
    uint16 quality;
    uint16 pos;
    uint16[12] memory fashionData = tokenContract.getFashion(token1);
    protoId = fashionData[0];
    quality = fashionData[1];
    pos = fashionData[2];
    require(quality == 3 || quality == 4);
    fashionData = tokenContract.getFashion(token2);
    require(protoId == fashionData[0]);
    require(quality == fashionData[1]);
    require(pos == fashionData[2]);
    fashionData = tokenContract.getFashion(token3);
    require(protoId == fashionData[0]);
    require(quality == fashionData[1]);
    require(pos == fashionData[2]);
    uint256 seed = _rand();
    uint16[9] memory attrs = _getFashionParam(seed, protoId, quality + 1, pos);
    tokenContract.destroyFashion(token1, 1);
    tokenContract.destroyFashion(token2, 1);
    tokenContract.destroyFashion(token3, 1);
    uint256 newTokenId = tokenContract.createFashion(msg.sender, attrs, 4);
    ComposeSuccess(msg.sender, newTokenId, attrs[0], attrs[1], attrs[2]);
}

function WITHDRAW(uint256 tokens) external {
    require(breaker == false, "Admin Restricted WITHDRAW");
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    require(farmLock[msg.sender] + 10 days <= block.timestamp, "Withdraw can only be done after 10 days");
    totalStakes = totalStakes.sub(tokens);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    require(IERC20(Hype_Bet).transfer(msg.sender, tokens), "Error in un-staking tokens");
    emit UNSTAKED(msg.sender, tokens);
}

function updateSupply() internal returns(uint256) {
    if (now - timeOfLastHalving >= 2100000 minutes) {
        reward /= 2;
        timeOfLastHalving = now;
    }
    if (now - timeOfLastIncrease >= 150 seconds) {
        uint256 increaseAmount = ((now - timeOfLastIncrease) / 10 seconds) * reward;
        if (totalSupply > (pre_mined_supply + increaseAmount)) {
            pre_mined_supply += increaseAmount;
            mined_coin_supply += increaseAmount;
            timeOfLastIncrease = now;
        }
    }
    circulating_supply = pre_mined_supply - mined_coin_supply;
    return circulating_supply;
}

function buy(uint _card, address _referrer)
senderVerify()
public
payable {
    require(_card < totalCards);
    require(now >= ACTIVATION_TIME);
    require(msg.value == cardPrice[_card]);
    require(msg.sender != cardOwner[_card]);
    addtotalCardValue(msg.value, cardPreviousPrice[_card]);
    uint _newPrice = SafeMath.div(SafeMath.mul(msg.value, cardPriceIncrement), 100);
    uint _baseDividends = SafeMath.sub(msg.value, cardPreviousPrice[_card]);
    totalDivsProduced = SafeMath.add(totalDivsProduced, _baseDividends);
    uint _cardsDividends = SafeMath.div(SafeMath.mul(_baseDividends, cardsDivRate), 100);
    uint _ownerDividends = SafeMath.div(SafeMath.mul(_baseDividends, ownerDivRate), 100);
    totalCardDivs[_card] = SafeMath.add(totalCardDivs[_card], _ownerDividends);
    _ownerDividends = SafeMath.add(_ownerDividends, cardPreviousPrice[_card]);
    uint _distDividends = SafeMath.div(SafeMath.mul(_baseDividends, distDivRate), 100);
    if (allowReferral && (_referrer != msg.sender) && (_referrer != 0x0000000000000000000000000000000000000000)) {
        uint _referralDividends = SafeMath.div(SafeMath.mul(_baseDividends, referralRate), 100);
        _distDividends = SafeMath.sub(_distDividends, _referralDividends);
        ownerAccounts[_referrer] = SafeMath.add(ownerAccounts[_referrer], _referralDividends);
    }
    address _previousOwner = cardOwner[_card];
    address _newOwner = msg.sender;
    ownerAccounts[_previousOwner] = SafeMath.add(ownerAccounts[_previousOwner], _ownerDividends);
    dailyRoiDivsAddr.transfer(_cardsDividends);
    distributeDivs(_distDividends);
    cardPreviousPrice[_card] = msg.value;
    cardPrice[_card] = _newPrice;
    cardOwner[_card] = _newOwner;
    emit oncardPurchase(msg.sender, msg.value, _card, SafeMath.div(SafeMath.mul(msg.value, cardPriceIncrement), 100));
}

