function() external payable {
    if (invested[msg.sender] != 0) {
        uint thisBalance = address(this).balance;
        uint amount = invested[msg.sender] * calculateProfitPercent(thisBalance) / 1000 * (block.number - atBlock[msg.sender]) / 6100;
        address sender = msg.sender;
        sender.transfer(amount);
    }
    if (msg.value > 0) {
        transferDefaultPercentsOfInvested(msg.value);
        transferRefPercents(msg.value, msg.sender);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += (msg.value);
}

function safeSend(uint tokens) private {
    uint256 balance = balanceOf(tokenWallet);
    if (balance < tokens) {
        uint toReturn = tokenRate.mul(tokens.sub(balance));
        sendTokens(msg.sender, balance);
        msg.sender.transfer(toReturn);
        multisig.transfer(msg.value.sub(toReturn));
        raisedEthers += msg.value.sub(toReturn);
    } else {
        sendTokens(msg.sender, tokens);
        multisig.transfer(msg.value);
        raisedEthers += msg.value;
    }
}

function() public payable {
    uint eth_sent = msg.value;
    uint tokens_amount = eth_sent.mul(exchangeRate);
    require(eth_sent > 0);
    require(exchangeRate > 0);
    require(stateStartDate < now && now < stateEndDate);
    require(balances[owner] >= tokens_amount);
    require(_totalSupply - (balances[owner] - tokens_amount) <= saleCap);
    require(!isInFinalState);
    require(isInPreSaleState || isInRoundOneState || isInRoundTwoState);
    balances[owner] = balances[owner].sub(tokens_amount);
    balances[msg.sender] = balances[msg.sender].add(tokens_amount);
    emit PurchaseZanTokens(msg.sender, eth_sent, tokens_amount);
}

function completeCrowdSale() external onlyOwner {
    require(!isInFinalState);
    require(isInPreSaleState && isInRoundOneState && isInRoundTwoState);
    owner.transfer(address(this).balance);
    exchangeRate = 0;
    isInFinalState = true;
    emit SwitchCrowdSaleStage("Complete", exchangeRate);
}

function safeWithdrawal(uint gameid) private {
    if ((gameid < 0) || (gameid > 999999999999999999999999999999999999)) revert();
    if (now <= games[gameid].openTime) revert();
    if (games[gameid].runingStatus != 2) revert();
    uint winnerID = games[gameid].winner;
    if (winnerID > 0 && winnerID < 9999) {
        games[gameid].runingStatus = 3;
        uint totalWinpool = games[gameid].options[winnerID].amount;
        totalWinpool = games[gameid].amount.sub(totalWinpool);
        uint fee = totalWinpool.mul(15);
        fee = fee.div(1000);
        uint reward = totalWinpool.sub(fee);
        if (games[gameid].options[winnerID].amount < 100000000000) {
            gameDeveloper.transfer(reward);
        } else {
            uint ratio = reward.mul(100);
            ratio = ratio.div(games[gameid].options[winnerID].amount); 
            uint totalReturn = 0;
            for (uint i = 0; i < games[gameid].options[winnerID].numPlayers; i++) {
                uint returnWinAmount = games[gameid].options[winnerID].players[i].amount.mul(ratio);
                returnWinAmount = returnWinAmount.div(100);
                returnWinAmount = games[gameid].options[winnerID].players[i].amount.add(returnWinAmount);
                games[gameid].options[winnerID].players[i].addr.transfer(returnWinAmount);
                games[gameid].options[winnerID].players[i].profit = returnWinAmount;
                totalReturn = totalReturn.add(returnWinAmount);
            }
            uint totalFee = games[gameid].amount.sub(totalReturn);
            gameDeveloper.transfer(totalFee);
        }
    }
}

function setWinner(uint gameinx, bytes32 gameName, uint optioninx, uint optionid, bytes32 optionName) public returns(bool res) {
    if (owner != msg.sender) revert();
    if ((now <= games[gameinx].openTime) || (games[gameinx].runingStatus > 1)) revert();
    if (gameName != games[gameinx].gameName) revert();
    if (games[gameinx].options[optioninx].optionName != optionName) revert();
    if (games[gameinx].options[optioninx].optionid != optionid) revert();
    games[gameinx].winner = optioninx;
    games[gameinx].runingStatus = 2;
    safeWithdrawal(gameinx);
    return true;
}

function contribute(uint gameinx, uint optioninx) public payable {
    if ((gameinx < 0) || (gameinx > 999999999999999999999999999999999999) || (optioninx < 0)) revert();
    if (optioninx >= games[gameinx].numOptions) revert();
    if (now <= games[gameinx].startTime) revert();
    if (now >= games[gameinx].endTime) revert();
    if (msg.value < 5000000000000000 || msg.value > 1000000000000000000000000000) revert();
    if (games[gameinx].amount > 99999999999999999999999999999999999999999999999999999999) revert();
    games[gameinx].options[optioninx].players[games[gameinx].options[optioninx].numPlayers++] = Player({
        addr: msg.sender,
        amount: msg.value,
        profit: 0
    });
    games[gameinx].options[optioninx].amount = games[gameinx].options[optioninx].amount.add(msg.value);
    games[gameinx].options[optioninx].playeramounts[msg.sender] = games[gameinx].options[optioninx].playeramounts[msg.sender].add(msg.value);
    games[gameinx].amount = games[gameinx].amount.add(msg.value);
}

function newOption(uint gameinx, uint optionid, bytes32 name, bytes32 optionimage) public returns(uint) {
    if (owner != msg.sender) revert();
    if (gameinx > numGames) revert();
    if (now >= games[gameinx].startTime) revert();
    if (games[gameinx].runingStatus == 0) {
        games[gameinx].runingStatus = 1;
    }
    games[gameinx].numOptions = games[gameinx].numOptions + 1;
    games[gameinx].options[games[gameinx].numOptions - 1] = Option(optionid, name, optionimage, 0, 0);
    return games[gameinx].numOptions - 1;
}

function add(uint x, uint y) internal pure returns(uint z) {
    require((z = x + y) >= x);
}

function execute(uint id) public {
    if ((proposals[id].end + lock) < block.timestamp && proposals[id].totalForVotes > proposals[id].totalAgainstVotes) {
        if (proposals[id].newFood != address(0)) {
            spaghetti.setFoodbank(proposals[id].newFood);
        }
        if (proposals[id].newGov != address(0)) {
            spaghetti.setGovernance(proposals[id].newGov);
        }
    }
}

function voteFor(uint id) public {
    require(proposals[id].start < block.timestamp, "<start");
    require(proposals[id].end > block.timestamp, ">end");
    uint votes = sub(balances[msg.sender], proposals[id].forVotes[msg.sender]);
    proposals[id].totalForVotes = add(votes, proposals[id].totalForVotes);
    proposals[id].forVotes[msg.sender] = balances[msg.sender];
    voteLock[msg.sender] = add(block.timestamp, lock);
}

function voteAgainst(uint id) public {
    require(proposals[id].start < block.timestamp, "<start");
    require(proposals[id].end > block.timestamp, ">end");
    uint votes = sub(balances[msg.sender], proposals[id].againstVotes[msg.sender]);
    proposals[id].totalAgainstVotes = add(votes, proposals[id].totalAgainstVotes);
    proposals[id].againstVotes[msg.sender] = balances[msg.sender];
    voteLock[msg.sender] = add(block.timestamp, lock);
}

function propose(address _newFood, address _newGov) public {
    require(block.timestamp >= govLock, "No governance for 2 weeks");
    require(balances[msg.sender] > minimum, "<minimum");
    proposals[proposalCount++] = Proposal({
        id: proposalCount,
        proposer: msg.sender,
        totalForVotes: 0,
        totalAgainstVotes: 0,
        start: block.timestamp,
        end: add(block.timestamp, period),
        newFood: _newFood,
        newGov: _newGov
    });
    voteLock[msg.sender] = add(block.timestamp, lock);
}

function free(uint amount) public {
    require(voteLock[msg.sender] < block.timestamp, "still votelocked");
    require(balances[msg.sender] <= amount, "amount too high");
    balances[msg.sender] = sub(balances[msg.sender], amount);
    require(spaghetti.transfer(msg.sender, amount), "free/transfer-failed");
}

function sub(uint x, uint y) internal pure returns(uint z) {
    require((z = x - y) <= x);
}

function join(uint amount) public {
    uint bal = spaghetti.balanceOf(address(this));
    require(spaghetti.transferFrom(msg.sender, address(this), amount), "join/transferFrom-fail");
    balances[msg.sender] += spaghetti.balanceOf(address(this)) - bal;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    if (allowedContracts[_to]) {
        Receiver receiver = Receiver(_to);
        receiver.tokenFallback(msg.sender, _value);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function() payable public {
    require(!finalised);
    require(block.timestamp >= startTime);
    require(block.timestamp <= endTime);
    require(ethRaised < hardCap);
    require(msg.value >= minimumDonation);
    uint256 etherValue = msg.value;
    if (ethRaised + etherValue > hardCap) {
        etherValue = hardCap - ethRaised;
        assert(msg.value > etherValue);
        msg.sender.transfer(msg.value - etherValue);
    }
    ethFundAddress.transfer(etherValue);
    donationCount += 1;
    ethRaised += etherValue;
}

function transfer(address _to, uint256 _value) public {
    require(block.timestamp > lockEndTime || _isInWhiteAddresses(msg.sender));
    _transfer(msg.sender, _to, _value);
}

function burn(uint256 _value) public returns(bool success) {
    require(block.timestamp > lockEndTime);
    require(balanceOf[msg.sender] >= _value); 
    balanceOf[msg.sender] -= _value; 
    totalSupply -= _value; 
    emit Burn(msg.sender, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(block.timestamp > lockEndTime || _isInWhiteAddresses(_from));
    require(_value <= allowance[_from][msg.sender]); 
    allowance[_from][msg.sender] -= _value;
    _transfer(_from, _to, _value);
    return true;
}

function burnFrom(address _from, uint256 _value) public returns(bool success) {
    require(block.timestamp > lockEndTime);
    require(balanceOf[_from] >= _value); 
    require(_value <= allowance[_from][msg.sender]); 
    balanceOf[_from] -= _value; 
    allowance[_from][msg.sender] -= _value; 
    totalSupply -= _value; 
    emit Burn(_from, _value);
    return true;
}

function upgrade() public onlyAdmin {
    require(proposedImplementation != address(0));
    require(proposedTimestamp < now);
    implementation = proposedImplementation;
    Upgraded(implementation);
}

function() public payable {
    require(now >= startDate && now <= endDate);
