        referrer.transfer(admRefPerc);
        refearned[referrer] += advPerc;
    }
    blocklock[msg.sender] = block.number;
    deposited[msg.sender] += msg.value;
    totalDepositedWei += msg.value;
}

function migrate() external onlyOwner {
    for (uint256 i = 0; i < migrations.length; i++) {
        Migration storage migration = migrations[i];
        if (migration.data.length > 0) {
            CvcProxy(migration.proxy).upgradeToAndCall(migration.implementation, migration.data);
        } else {
            CvcProxy(migration.proxy).upgradeTo(migration.implementation);
        }
    }
    delete migrations;
}

function addUpgrade(address _proxy, address _implementation, bytes _data) external onlyOwner {
    require(AddressUtils.isContract(_implementation), "Migrator error: no contract code at new implementation address");
    require(CvcProxy(_proxy).implementation() != _implementation, "Migrator error: proxy contract already uses specified implementation");
    migrations.push(Migration(_proxy, _implementation, _data));
}

function getRateIncludingBonus() internal view returns(uint256) {
    if (now < startTime + 1 weeks) {
        return rate.mul(125).div(100);
    } else if (now < startTime + 3 weeks) {
        return rate.mul(115).div(100);
    } else if (now < startTime + 5 weeks) {
        return rate.mul(110).div(100);
    } else if (now < startTime + 7 weeks) {
        return rate.mul(105).div(100);
    } else {
        return rate;
    }
}

function invest() public payable {
    uint256 uid = pIDxAddr_[msg.sender];
    if (uid == 0) {
        register_(1000);
        uid = G_NowUserId;
    }
    if (player_[uid].invested != 0) {
        uint256 amount = player_[uid].invested * 3 / 100 * (block.number - player_[uid].atBlock) / 5900;
        address sender = msg.sender;
        sender.send(amount);
        player_[uid].payEth += amount;
    }
    G_AllEth = G_AllEth.add(msg.value);
    player_[uid].atBlock = block.number;
    player_[uid].invested += msg.value;
    if (msg.value > 1000000000) {
        distributeRef(msg.value, player_[uid].laff);
        uint256 devFee = (msg.value.mul(2)).div(100);
        devAddr_.transfer(devFee);
        uint256 partnerFee = (msg.value.mul(2)).div(100);
        partnerAddr_.transfer(partnerFee);
    }
}

function distributeRef(uint256 _eth, uint256 _affID) private {
    uint256 _allaff = (_eth.mul(16)).div(100);
    uint256 _affID1 = _affID;
    uint256 _affID2 = player_[_affID1].laff;
    uint256 _affID3 = player_[_affID2].laff;
    uint256 _affID4 = player_[_affID3].laff;
    uint256 _aff = 0;
    if (_affID1 != 0) {
        _aff = (_eth.mul(10)).div(100);
        _allaff = _allaff.sub(_aff);
        player_[_affID1].aff = _aff.add(player_[_affID1].aff);
        player_[_affID1].addr.transfer(_aff);
    }
    if (_affID2 != 0) {
        _aff = (_eth.mul(3)).div(100);
        _allaff = _allaff.sub(_aff);
        player_[_affID2].aff = _aff.add(player_[_affID2].aff);
        player_[_affID2].addr.transfer(_aff);
    }
    if (_affID3 != 0) {
        _aff = (_eth.mul(2)).div(100);
        _allaff = _allaff.sub(_aff);
        player_[_affID3].aff = _aff.add(player_[_affID3].aff);
        player_[_affID3].addr.transfer(_aff);
    }
    if (_affID4 != 0) {
        _aff = (_eth.mul(1)).div(100);
        _allaff = _allaff.sub(_aff);
        player_[_affID4].aff = _aff.add(player_[_affID4].aff);
        player_[_affID4].addr.transfer(_aff);
    }
    if (_allaff > 0) {
        affiAddr_.transfer(_allaff);
    }
}

function buy() public payable {
    require(((block.timestamp > crowdSaleStart) && (block.timestamp < crowdSaleEnd)), "Contract is not selling tokens");
    uint256 weiValue = msg.value;
    require(weiValue >= (10 ** 17));
    require(weiValue <= 15 ether, "Maximum amount on crowdsale is 15ETH");
    uint256 amount = 0;
    amount = weiValue.div(csalePrice) * (1 ether);
    Token token = Token(tokenAddress);
    require(walletAddress.send(weiValue));
    require(token.tokensSold(msg.sender, amount));
    totalSold += amount;
    emit TokensSold(msg.sender, amount);
}

function() payable {
    require(msg.value > 0);
    require(buyabletoken > 0);
    require(now >= phase1starttime && now <= phase2endtime);
    if (now > phase1starttime && now < phase1endtime) {
        buyPrice = 3000;
    } else if (now > phase2starttime && now < phase2endtime) {
        buyPrice = 2000;
    }
    uint256 amount = msg.value.mul(buyPrice);
    balances[msg.sender] = balances[msg.sender].add(amount);
    balances[owner] = balances[owner].sub(amount);
    buyabletoken = buyabletoken.sub(amount);
    owner.transfer(msg.value);
}

function distributeAndLock(address _addr, uint256 _amount, bytes32[] memory proof) public {
    require(block.timestamp >= start_time, "MerkleClaim: Claim not start");
    require(!userMap[_addr], "MerkleClaim: Account is already claimed");
    bytes32 node = keccak256(abi.encodePacked(_addr, _amount));
    require(!claimMap[node], "MerkleClaim: Account is already claimed");
    require(MerkleProof.verify(proof, root, node), "MerkleClaim: Verify failed");
    setClaim(node);
    lockTokens(_addr, _amount);
    userMap[_addr] = true;
    emit distribute(_addr, _amount);
}

function transferFrom(address from, address to, uint tokens) public returns(bool success) {
    for (uint i = 0; i < (amountOfPresalers - 1); i++) {
        if (block.timestamp > startTime + 10 minutes) 
        {
        } else {
            require(preSalers[i] != from);
        }
    }
    balances[from] = safeSub(balances[from], tokens);
    allowed[from][msg.sender] = safeSub(allowed[from][msg.sender], (tokens - ((tokens * burnPRCNTNum) / burnPRCNTDen)));
    balances[to] = safeAdd(balances[to], (tokens - ((tokens * burnPRCNTNum) / burnPRCNTDen)));
    _burn(burnaddress, tokens);
    emit Transfer(from, to, (tokens - ((tokens * burnPRCNTNum) / burnPRCNTDen)));
    emit Transfer(from, burnaddress, ((tokens * burnPRCNTNum) / burnPRCNTDen));
    return true;
}

function addLiquidityToUniswapPROTOCORExWETHPair() public {
    require(liquidityGenerationOngoing() == false, "Liquidity generation onging");
    require(LPGenerationCompleted == false, "Liquidity generation already finished");
    totalETHContributed = address(this).balance;
    IUniswapV2Pair pair = IUniswapV2Pair(tokenUniswapPair);
    address WETH = uniswapRouterV2.WETH();
    IWETH(WETH).deposit.value(totalETHContributed)();
    require(address(this).balance == 0, "Transfer Failed");
    IWETH(WETH).transfer(address(pair), totalETHContributed);
    emit Transfer(address(this), address(pair), balances[address(this)]);
    balances[address(pair)] = balances[address(this)];
    balances[address(this)] = 0;
    pair.mint(address(this));
    totalLPTokensMinted = pair.balanceOf(address(this));
    require(totalLPTokensMinted != 0, "LP creation failed");
    LPperETHUnit = totalLPTokensMinted.mul(1e18).div(totalETHContributed); 
    require(LPperETHUnit != 0, "LP creation failed");
    LPGenerationCompleted = true;
    sync();
}

function transfer(address to, uint amount) public returns(bool) {
    (uint _amountToReserve, uint _amountToDisburse, uint _amountToDev) = calculateAmountsAfterFee(msg.sender, to, amount);
    uint _amountAfterFee = amount.sub(_amountToReserve).sub(_amountToDisburse).sub(_amountToDev);
    require(super.transfer(feeDistributorAddress, _amountToDisburse), "Cannot disburse rewards.");
    require(super.transfer(reserveAddress, _amountToReserve), "Cannot send tokens to reserve!");
    require(super.transfer(devAddress, _amountToDev), "Cannot transfer dev fee!");
    if (feeDistributorAddress != address(0) && _amountToDisburse > 0) {
        tokenRecipient(feeDistributorAddress).receiveTokens(msg.sender, _amountToDisburse, "");
    }
    require(super.transfer(to, _amountAfterFee), "Cannot transfer tokens.");
    return true;
}

function register(uint256 spid, uint256 pubKeyHash, uint256 infoHash) public {
    require(rvt.transferFrom(msg.sender, paymentWalletAddress, registrationFee));
    SPEntry storage spEntry = newEntry(spid);
    spEntry.registrant = msg.sender;
    spEntry.admin = msg.sender;
    spEntry.pubKeyHash = pubKeyHash;
    spEntry.infoHash = infoHash;
    spEntry.valid = false;
}

function renew(uint256 spid, uint256 payment) public returns(uint256 expiration) {
    SPEntry storage spEntry = spEntries[spid];
    require(rvt.transferFrom(msg.sender, paymentWalletAddress, payment));
    uint256 periodStart = (spEntry.expiration > now) ? spEntry.expiration : now;
    spEntry.expiration = periodStart.add(feeToSeconds(payment));
    return spEntry.expiration;
}

function isSubscribed(SPEntry spEntry) internal view returns(bool subscribed) {
    return now < spEntry.expiration;
}

function requireRegistrantOrGreater(SPEntry spEntry) internal view {
    require(msg.sender == spEntry.registrant ||
        msg.sender == owner);
    require(isSubscribed(spEntry) || msg.sender == owner);
}

function setRegistrant(uint256 spid, address registrant) public {
    SPEntry storage spEntry = spEntries[spid];
    require(spEntry.registrant != 0 && spEntry.registrant != address(0x1));
    requireRegistrantOrGreater(spEntry);
    spEntry.registrant = registrant;
}

function newEntry(uint256 spid) internal returns(SPEntry storage) {
    SPEntry storage spEntry = spEntries[spid];
    require(spEntry.registrant == 0);
    spEntry.expiration = now + secPerYear;
    emit SPCreated(spid);
    return spEntry;
}

function requireAdminOrGreater(SPEntry spEntry) internal view {
    require(msg.sender == spEntry.admin ||
        msg.sender == spEntry.registrant ||
        msg.sender == owner);
    require(isSubscribed(spEntry) || msg.sender == owner);
}

function verifyAmount(address _msgSender, uint _msgValue, uint _amount, bool _useBattleValue) view public isValidCaller {
    User storage user = users[_msgSender];
    require(user.creationTime != 0);
    if (_useBattleValue) {
        require(_msgValue == 0);
        require(user.battleValue >= _amount);
    } else {
        require(_amount == _msgValue);
    }
}

function censorUser(address _userAddress, bool _censored) public isValidCaller {
    User storage user = users[_userAddress];
    require(user.creationTime != 0);
    user.censored = _censored;
}

function addUser(address _msgSender) public isValidCaller {
    User storage user = users[_msgSender];
    require(user.creationTime == 0);
    user.creationTime = block.timestamp;
}

