function redeem() public {
    if (purchased[msg.sender] == 0) {
        revert();
    }
    if (now < lockup[msg.sender]) {
        revert();
    }
    uint256 withdrawal = purchased[msg.sender];
    purchased[msg.sender] = 0;
    ERC223 token = ERC223(tokenAddress);
    token.transfer(msg.sender, withdrawal);
}

function buyTokens() payable public {
    if (!active) {
        revert();
    }
    if (msg.value < purchaseLimit) {
        revert();
    }
    uint256 purchasedAmount = msg.value.div(priceDiv);
    if (purchasedAmount == 0) {
        revert();
    }
    if (purchasedAmount > hardCap - sold) {
        revert();
    }
    if (lockup[msg.sender] == 0) {
        lockup[msg.sender] = now + 1 years;
    }
    purchased[msg.sender] = purchased[msg.sender] + purchasedAmount;
    sold = sold + purchasedAmount;
    treasury.transfer(msg.value);
    Purchase(msg.sender, purchasedAmount, now, lockup[msg.sender]);
}

function getPendingDivs(address _holder) public view returns(uint256) {
    if (!holders.contains(_holder)) return 0;
    if (depositedTokens[_holder] == 0) return 0;
    uint256 timeDiff = now.sub(lastClaimedTime[_holder]);
    uint256 stakedAmount = depositedTokens[_holder];
    if (now > farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(38502858097).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    } else if (now <= farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(rewardRate).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    }
}

function VerifyWinners(uint min, uint max) public {
    require(msg.sender == tx.origin);
    if ((!ticketsOpen) && (block.number > closedBlock + 3)) {
        uint i = 0;
        uint m = players.length;
        if (msg.sender == _closerAddress && min > 0 && max > 0) {
            i = min;
            m = max;
        }
        systemNumber = uint256(uint256(keccak256(abi.encodePacked(blockhash(block.number - 1)))) % maxNumber);
        address _winner;
        uint _winnerTickets;
        bool win = false;
        while (i < m) {
            if (win)
                break;
            uint j = 0;
            while (j < tickets[i]) {
                if (uint256(uint256(keccak256(abi.encodePacked(players[i], j))) % maxNumber) == systemNumber) {
                    win = true;
                    _winner = players[i];
                    _winnerTickets = tickets[i];
                    break;
                }
                j++;
            }
            i++;
        }
        if (win) {
            address payable add = payable(_winner);
            uint contractBalance = address(this).balance;
            uint winAmount = contractBalance * percentWin / 100;
            uint totalToPay = winAmount;
            if (!add.send(totalToPay)) revert('Error While Executing Payment.');
            totalPaidOut += totalToPay;
            winnersOnly.push(_winner);
            winnersOnlyTickets.push(_winnerTickets);
            winnersOnlyETH.push(totalToPay);
            winnersOnlyTimestamp.push(block.timestamp);
            pastGameNr.push(pastGameNr[pastGameNr.length - 1] + 1);
            pastGameSystemNumber.push(systemNumber);
            pastGamePlayers.push(players.length);
            pastGameTickets.push(currentTickets);
            winners.push(_winner);
            winnerTickets.push(_winnerTickets);
            winnerETHAmount.push(totalToPay);
            pastGameTimestamp.push(block.timestamp);
            winnersCount++;
            winnersEthCount += totalToPay;
            emit Numbers(_winner, systemNumber, "WINNER!");
        } else {
            pastGameNr.push(pastGameNr[pastGameNr.length - 1] + 1);
            pastGameSystemNumber.push(systemNumber);
            pastGamePlayers.push(players.length);
            pastGameTickets.push(currentTickets);
            winners.push(0x0000000000000000000000000000000000000000);
            winnerTickets.push(0);
            winnerETHAmount.push(0);
            pastGameTimestamp.push(block.timestamp);
            emit Numbers(msg.sender, systemNumber, "No winners! Try Again.");
        }
        currentTickets = 0;
        delete players;
        delete tickets;
        ticketsOpen = true;
        closedBlock = 0;
    } else {
        revert('Tickets must be closed and block number must be + 10');
    }
}

function prepurchase(uint32 _captainId) external payable {
    uint32 color;
    uint32 atk;
    uint32 defense;
    uint256 price;
    uint256 captainCount;
    uint256 SellCount = captainToCount[_captainId];
    (color, atk, , , defense, price, captainCount) = config.getCardInfo(_captainId);
    require(config.getSellable(_captainId) == true);
    SellCount += 1;
    require(SellCount <= captainCount);
    require(msg.sender != address(0));
    require(msg.value >= price);
    captains.CreateCaptainToken(msg.sender, price, _captainId, color, atk, defense, 1, 0);
    captainToCount[_captainId] = SellCount;
    devAddress.transfer(msg.value);
    BuyToken(_captainId, price, address(this), msg.sender);
}

function buyPixel(address beneficiary, uint16 _pixelNumber, uint24 _color, string _message)
payable
public {
