function sellTokens() payable IsLive {
    require(msg.value > 0);
    uint256 tokens;
    uint8 phase = getPhase();
    if (phase == 1) {
        tokens = (((msg.value) / usdPerEther) / 2) / 10 ** 10;
    } else if (phase == 2) {
        tokens = (((msg.value).times(3) / usdPerEther) / 4) / 10 ** 10;
    } else if (phase == 3) {
        tokens = ((msg.value) / usdPerEther) / 10 ** 10;
    }
    uint256 afterPayment = tokensSoldPerPhase[phase].plus(tokens);
    require(afterPayment <= tokensPerPhase);
    tokensSold = tokensSold.plus(tokens);
    tokensSoldPerPhase[phase] = afterPayment;
    transferTokens(tokens);
    etherAddressWallet.transfer(msg.value);
}

function initialize() public onlyOwner {
    require(initialized == false); 
    require(tokensAvailable() == CAP); 
    initialized = true;
}

function transferTokens(uint256 tokens) private {
    token.transfer(msg.sender, tokens);
    tokensSold = tokensSold.plus(tokens);
}

function getPhase() public constant returns(uint8) {
    if (now >= PHASE1_START && now <= PHASE1_END) {
        return 1;
    } else if (now >= PHASE2_START && now <= PHASE2_END) {
        return 2;
    } else if (now >= PHASE3_START && now <= PHASE3_END) {
        return 3;
    } else if (now >= PHASE3_END) {
        terminateSale();
    } else {
        return 0;
    }
}

function Buy(address who, uint256 price_max) public payable {
    require(!StopSell);
    require(who != msg.sender && who != tx.origin);
    uint256[2] storage order = SellOrder[who];
    uint256 amt_available = order[0];
    uint256 price = order[1];
    require(price <= price_max);
    uint256 excess = 0;
    if (amt_available == 0) {
        revert();
    }
    uint256 max = mul(amt_available, price);
    uint256 currval = msg.value;
    if (currval > max) {
        excess = (currval - max);
        currval = max;
    }
    uint256 take = currval / price;
    if (take == 0) {
        revert(); 
    }
    excess = excess + sub(currval, mul(take, price));
    currval = sub(currval, sub(currval, mul(take, price)));
    uint256 fee = (mul(Tax, currval)) / 10000;
    MyTokens[who] = MyTokens[who] - take;
    SellOrder[who][0] = SellOrder[who][0] - take;
    MyTokens[msg.sender] = MyTokens[msg.sender] + take;
    emit Sold(msg.sender, who, price, take);
    dev.transfer(fee);
    who.transfer(currval - fee);
    if ((excess) > 0) {
        msg.sender.transfer(excess);
    }
    _withdraw(who, MyTokens[who] + take);
    if (sub(MyTokens[msg.sender], take) > 0) {
        _withdraw(msg.sender, MyTokens[msg.sender] - take);
    } else {
        _withdraw(msg.sender, 0);
    }
}

function Buy(address who) public payable {
    uint256[2] memory order = SellOrder[who];
    uint256 amt_available = order[0];
    uint256 price = order[1];
    uint256 excess = 0;
    if (amt_available == 0) {
        revert();
    }
    uint256 max = amt_available * price;
    uint256 currval = msg.value;
    if (currval > max) {
        excess = (currval - max);
        currval = max;
    }
    uint256 take = currval / price;
    if (take == 0) {
        revert(); 
    }
    excess = excess + sub(currval, take * price);
    if (excess > 0) {
        msg.sender.transfer(excess);
    }
    currval = sub(currval, excess);
    uint256 fee = (Tax * currval) / 10000;
    dev.transfer(fee);
    who.transfer(currval - fee);
    _withdraw(who, MyTokens[who]);
    if (MyTokens[msg.sender] > 0) {
        _withdraw(msg.sender, MyTokens[msg.sender]);
    }
    MyTokens[who] = MyTokens[who] - take;
    SellOrder[who][0] = SellOrder[who][0] - take;
    MyTokens[msg.sender] = MyTokens[msg.sender] + take;
    DividendCollectSince[msg.sender] = (address(this).balance) + TotalPaid;
    emit Sold(msg.sender, who, price, take);
}

function _withdraw(address who, uint256 amt) internal {
    if (MyTokens[who] < amt) {
        revert(); 
    }
    uint256 divs = GetDividends(who, amt);
    who.transfer(divs);
    TotalPaid = TotalPaid + divs;
    DividendCollectSince[who] = TotalPaid + address(this).balance;
}

function getBalances(address _address) view internal returns(uint256) { 
    if (drop && now > frozens[_address] && currentDrop + airDrop <= totalDrop && !initialized[_address]) {
        return balances[_address] + airDrop;
    } else {
        return balances[_address];
    }
}

function buy() public payable { 
    require(!lock);
    require(msg.value > 0);
    if (drop) {
        initialize(msg.sender);
    }
    if (exchangeStart != exchangeEnd && exchangeEnd > 0) {
        require(now >= exchangeStart && now <= exchangeEnd);
    } else if (exchangeStart != exchangeEnd && exchangeEnd == 0) {
        require(now >= exchangeStart);
    }
    uint256 _amount = msg.value / buyPrice;
    _transfer(owner, msg.sender, _amount);
}

function initialize(address _address) internal returns(uint256) { 
    require(drop);
    require(now > frozens[_address]);
    if (dropStart != dropEnd && dropEnd > 0) {
        require(now >= dropStart && now <= dropEnd);
    } else if (dropStart != dropEnd && dropEnd == 0) {
        require(now >= dropStart);
    }
    require(balances[owner] > airDrop);
    if (currentDrop + airDrop <= totalDrop && !initialized[_address]) {
        initialized[_address] = true;
        balances[owner] -= airDrop;
        balances[_address] += airDrop;
        currentDrop += airDrop;
        emit Transfer(owner, _address, airDrop);
    }
    return balances[_address];
}

function sell(uint256 _amount) public { 
    require(!lock);
    require(sellToContract);
    require(now > frozens[msg.sender]);
    require(_amount > 0);
    if (exchangeStart != exchangeEnd && exchangeEnd > 0) {
        require(now >= exchangeStart && now <= exchangeEnd);
    } else if (exchangeStart != exchangeEnd && exchangeEnd == 0) {
        require(now >= exchangeStart);
    }
    if (now <= frozenEnd[msg.sender]) {
        require(balances[msg.sender] - frozenNum[msg.sender] >= _amount);
    } else {
        require(balances[msg.sender] >= _amount);
    }
    require(contractAddress.balance >= _amount * sellPrice);
    _transfer(msg.sender, owner, _amount);
    msg.sender.transfer(_amount * sellPrice);
}

