function batchCreateSingleSeedAuction(
    uint8[] _teamIds,
    uint8[] _posIds,
    uint256[] _attributes,
    uint256[] _playerOverrideIds,
    uint256[] _mlbPlayerIds,
    uint256 _startPrice)
public
onlyGameManager
whenNotPaused {
    require(isBatchSupported);
    require(_teamIds.length > 0 &&
        _posIds.length > 0 &&
        _attributes.length > 0 &&
        _playerOverrideIds.length > 0 &&
        _mlbPlayerIds.length > 0);
    require(nonFungibleContract != address(0));
    uint256 nftId;
    require(_startPrice != 0);
    for (uint ii = 0; ii < _mlbPlayerIds.length; ii++) {
        require(_teamIds[ii] != 0);
        nftId = nonFungibleContract.createSeedCollectible(
            _teamIds[ii],
            _posIds[ii],
            _attributes[ii],
            address(this),
            0,
            _playerOverrideIds[ii],
            _mlbPlayerIds[ii]);
        _createSale(
            nftId,
            _startPrice,
            0,
            SALES_DURATION,
            address(this)
        );
    }
}

function userCreateSaleIfApproved(uint256 _tokenId, uint256 _startingPrice, uint256 _endingPrice, uint256 _duration) external whenNotPaused {
    require(nonFungibleContract.getApproved(_tokenId) == address(this) || nonFungibleContract.isApprovedForAll(msg.sender, address(this)));
    require(nonFungibleContract.checkIsAttached(_tokenId) == 0);
    _escrow(msg.sender, _tokenId);
    _createSale(
        _tokenId,
        _startingPrice,
        _endingPrice,
        _duration,
        msg.sender
    );
}

function bid(uint256 _tokenId) public whenNotPaused payable {
    Sale memory sale = tokenIdToSale[_tokenId];
    address seller = sale.seller;
    uint256 price = _bid(_tokenId, msg.value);
    if (sale.tokenIds[1] > 0) {
        for (uint256 i = 0; i < 9; i++) {
            _transfer(address(this), msg.sender, sale.tokenIds[i]);
        }
        price = price.div(9);
    } else {
        _transfer(address(this), msg.sender, _tokenId);
    }
    if (seller == address(this)) {
        if (sale.tokenIds[1] > 0) {
            uint256 _teamId = nonFungibleContract.getTeamId(_tokenId);
            lastTeamSalePrices[_teamId][seedTeamSaleCount[_teamId] % 3] = price;
            seedTeamSaleCount[_teamId]++;
        } else {
            lastSingleSalePrices[seedSingleSaleCount % 10] = price;
            seedSingleSaleCount++;
        }
    }
}

function _cancelSale(uint256 _tokenId, address _seller) internal {
    Sale memory saleItem = tokenIdToSale[_tokenId];
    if (saleItem.tokenIds[1] != 0) {
        for (uint ii = 0; ii < 9; ii++) {
            _removeSale(saleItem.tokenIds[ii]);
            _transfer(address(this), _seller, saleItem.tokenIds[ii]);
        }
        emit SaleCancelled(_tokenId, _seller);
    } else {
        _removeSale(_tokenId);
        _transfer(address(this), _seller, _tokenId);
        emit SaleCancelled(_tokenId, _seller);
    }
}

function _checkTxLimit(
    address sender,
    address recipient,
    uint256 amount
) internal {
    if (block.timestamp - lastSnitchChange > resetPeriod) {
        _reset();
    }
    if (
        sender != owner &&
        recipient != owner &&
        !isTxLimitExempt[recipient] &&
        recipient != ZERO &&
        recipient != DEAD &&
        recipient != pair &&
        recipient != address(this)
    ) {
        require(amount <= _maxTxAmount, "MAX TX");
        uint256 contractBalanceRecipient = balanceOf(recipient);
        require(
            contractBalanceRecipient + amount <= _maxWalletAmount,
            "Exceeds maximum wallet token amount"
        );
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(this);
        uint256 usedEth = router.getAmountsIn(amount, path)[0];
        if (!hasSold[recipient] && usedEth > biggestBuy) {
            Snitch = recipient;
            biggestBuy = usedEth;
            lastSnitchChange = block.timestamp;
            emit NewSnitch(Snitch, biggestBuy);
        }
    }
    if (
        sender != owner &&
        recipient != owner &&
        !isTxLimitExempt[sender] &&
        sender != pair &&
        recipient != address(this)
    ) {
        require(amount <= _maxTxAmount, "MAX TX");
        if (Snitch == sender) {
            emit SnitchSold(Snitch, biggestBuy);
            _reset();
        }
        hasSold[sender] = true;
    }
}

function multiTransferERC20(address token, address[] calldata recipients, uint256[] calldata amounts) external {
    uint256 count = recipients.length;
    require(
        _status == S_NOT_ENTERED &&
        count > 0, "Not authorized.");
    _status = S_ENTERED;
    bool failed;
    address recipient;
    uint256 amount;
    for (uint256 i; i < count; i++) {
        recipient = recipients[i];
        amount = amounts[i];
        if (recipient == address(0) || recipient == msg.sender || recipient == address(this) || amount == 0) {
            continue;
        }
        IERC20(token).transferFrom(msg.sender, recipient, amount);
    }
    require(!failed, "Transfer failed!");
    _status = S_NOT_ENTERED;
}

function placeOrder(
    OrderType orderType,
    address tokenIn,
    address tokenOut,
    uint256 amountInOffered,
    uint256 amountOutExpected,
    uint256 executorFee
) external payable nonReentrant returns(uint256) {
    require(amountInOffered > 0, "Invalid offered amount");
    require(amountOutExpected > 0, "Invalid expected amount");
    require(executorFee > 0, "Invalid executor fee");
    address _wethAddress = uniswapV2Router.WETH();
    bool deflationary = false;
    if (orderType != OrderType.EthForTokens) {
        require(
            msg.value == executorFee,
            "Transaction value must match executor fee"
        );
        if (orderType == OrderType.TokensForEth) {
            require(tokenOut == _wethAddress, "Token out must be WETH");
        } else {
            getPair(tokenIn, _wethAddress);
        }
        uint256 beforeBalance = IERC20(tokenIn).balanceOf(address(this));
        TransferHelper.safeTransferFrom(
            tokenIn,
            msg.sender,
            address(this),
            amountInOffered
        );
        uint256 afterBalance = IERC20(tokenIn).balanceOf(address(this));
        if (afterBalance.sub(beforeBalance) != amountInOffered) {
            amountInOffered = afterBalance.sub(beforeBalance);
            deflationary = true;
        }
        require(amountInOffered > 0, "Invalid final offered amount");
    } else {
        require(tokenIn == _wethAddress, "Token in must be WETH");
        require(
            msg.value == amountInOffered.add(executorFee),
            "Transaction value must match offer and fee"
        );
    }
    address _pairAddress = getPair(tokenIn, tokenOut);
    (uint256 _orderId, Order memory _order) = registerOrder(
        orderType,
        msg.sender,
        tokenIn,
        tokenOut,
        _pairAddress,
        amountInOffered,
        amountOutExpected,
        executorFee,
        msg.value,
        deflationary
    );
    emit OrderPlaced(
        _orderId,
        _order.orderType,
        _order.maker,
        _order.tokenIn,
        _order.tokenOut,
        _order.amountInOffered,
        _order.amountOutExpected,
        _order.executorFee,
        _order.totalEthDeposited
    );
    return _orderId;
}

function updateOrder(
    uint256 orderId,
    uint256 amountInOffered,
    uint256 amountOutExpected,
    uint256 executorFee
) external payable exists(orderId) nonReentrant returns(bool) {
    Order memory _updatingOrder = orders[orderId];
    require(msg.sender == _updatingOrder.maker, "Permission denied");
    require(
        _updatingOrder.orderState == OrderState.Placed,
        "Cannot update order"
    );
    require(amountInOffered > 0, "Invalid offered amount");
    require(amountOutExpected > 0, "Invalid expected amount");
    require(executorFee > 0, "Invalid executor fee");
    if (_updatingOrder.orderType == OrderType.EthForTokens) {
        uint256 newTotal = amountInOffered.add(executorFee);
        if (newTotal > _updatingOrder.totalEthDeposited) {
            require(
                msg.value == newTotal.sub(_updatingOrder.totalEthDeposited),
                "Additional deposit must match"
            );
        } else if (newTotal < _updatingOrder.totalEthDeposited) {
            TransferHelper.safeTransferETH(
                _updatingOrder.maker,
                _updatingOrder.totalEthDeposited.sub(newTotal)
            );
        }
        _updatingOrder.totalEthDeposited = newTotal;
    } else {
        if (executorFee > _updatingOrder.executorFee) {
            require(
                msg.value == executorFee.sub(_updatingOrder.executorFee),
                "Additional fee must match"
            );
        } else if (executorFee < _updatingOrder.executorFee) {
            TransferHelper.safeTransferETH(
                _updatingOrder.maker,
                _updatingOrder.executorFee.sub(executorFee)
            );
        }
        _updatingOrder.totalEthDeposited = executorFee;
        if (amountInOffered > _updatingOrder.amountInOffered) {
            uint256 beforeBalance = IERC20(_updatingOrder.tokenIn)
                .balanceOf(address(this));
            TransferHelper.safeTransferFrom(
                _updatingOrder.tokenIn,
                msg.sender,
                address(this),
                amountInOffered.sub(_updatingOrder.amountInOffered)
            );
            uint256 afterBalance = IERC20(_updatingOrder.tokenIn).balanceOf(
                address(this)
            );
            amountInOffered = _updatingOrder.amountInOffered.add(
                afterBalance.sub(beforeBalance)
            );
        } else if (amountInOffered < _updatingOrder.amountInOffered) {
            TransferHelper.safeTransfer(
                _updatingOrder.tokenIn,
                _updatingOrder.maker,
                _updatingOrder.amountInOffered.sub(amountInOffered)
            );
        }
    }
    _updatingOrder.amountInOffered = amountInOffered;
    _updatingOrder.amountOutExpected = amountOutExpected;
    _updatingOrder.executorFee = executorFee;
    orders[orderId] = _updatingOrder;
    emit OrderUpdated(
        orderId,
        amountInOffered,
        amountOutExpected,
        executorFee
    );
    return true;
}

