        } else {
            playerReferedByCount[refAddr] += 1;
            playerReferedMoneyGain[refAddr] += fee;
        }
    } else {
        totalPot += msg.value;
    }
    clickers[clikerIndex] = msg.sender;
    clikerIndex += 1;
    if (clikerIndex >= CLICKERS_SIZE) {
        clickPrice += 0.01 ether;
        clikerIndex = 0;
    }
}

