function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    if (
        from != owner() &&
        to != owner() &&
        to != address(0xdead) &&
        to != uniswapV2Pair &&
        automatedMarketMakerPairs[from]
    ) {
        require(amount <= maxBuyTranscationAmount, "Transfer amount exceeds the maxTxAmount.");
        uint256 contractBalanceRecepient = balanceOf(to);
        require(contractBalanceRecepient + amount <= maxWalletTokens, "Exceeds maximum wallet token amount.");
    } else if (
        from != owner() &&
        to != owner() &&
        to != address(0xdead) &&
        to != uniswapV2Pair &&
        automatedMarketMakerPairs[to]
    ) {
        require(amount <= maxSellTransactionAmount, "Sell transfer amount exceeds the maxSellTransactionAmount.");
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (canSwap &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 marketingTokens = contractTokenBalance.mul(marketingFee).div(totalFees);
        uint256 developmentTokens = contractTokenBalance.mul(developmentFee).div(totalFees);
        swapAndSendToFee(_developmentWalletAddress, developmentTokens, _marketingWalletAddress, marketingTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFees).div(100);
        if (automatedMarketMakerPairs[to]) {
            fees += amount.mul(1).div(100);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

