        .createPair(address(this), uniswapV2Router.WETH());
    uniswapV2Pair = _uniswapV2Pair;
}

function vestedTransfer(address _to, uint256 _amount, uint _lockMonths) public whenNotPaused onlyPayloadSize(3 * 32) returns(bool) {
    require(
        msg.sender == fundsWallet ||
        msg.sender == teamWallet
    );
    require(_lockMonths >= minVestLockMonths);
    Vesting storage vesting = vestingMap[_to];
    require(vesting.amount == 0);
    if (msg.sender == fundsWallet) {
        require(allowPurchase(_amount));
        require(isPurchaseWithinCap(tokenSold, _amount));
        require(allowTransfer(msg.sender, _amount));
        uint256 transferAmount = _amount.mul(15).div(100);
        uint256 vestingAmount = _amount.sub(transferAmount);
        vesting.amount = vestingAmount;
        vesting.startTime = now;
        vesting.lockMonths = _lockMonths;
        emit VestTransfer(msg.sender, _to, vesting.amount, vesting.startTime, _lockMonths);
        balances[msg.sender] = balances[msg.sender].sub(_amount);
        tokenSold = tokenSold.add(_amount);
        balances[_to] = balances[_to].add(transferAmount);
        emit Transfer(msg.sender, _to, transferAmount);
    } else if (msg.sender == teamWallet) {
        Vesting storage teamVesting = vestingMap[teamWallet];
        require(now < teamVesting.startTime);
        require(
            teamVesting.amount.sub(teamVesting.released) > _amount
        );
        teamVesting.amount = teamVesting.amount.sub(_amount);
        vesting.amount = _amount;
        vesting.startTime = teamVesting.startTime;
        vesting.lockMonths = _lockMonths;
        emit VestTransfer(msg.sender, _to, vesting.amount, vesting.startTime, _lockMonths);
    }
    return true;
}

function vestedAmount(address _wallet) public view returns(uint256) {
    uint amonth = 30 days;
    Vesting memory vesting = vestingMap[_wallet];
    uint lockPeriod = vesting.lockMonths.mul(amonth);
    uint lockEndTime = vesting.startTime.add(lockPeriod);
    if (now >= lockEndTime) {
        return vesting.amount;
    } else if (now > vesting.startTime) {
        uint roundedPeriod = now
            .sub(vesting.startTime)
            .div(amonth)
            .mul(amonth);
        return vesting.amount
            .mul(roundedPeriod)
            .div(lockPeriod);
    } else {
        return 0;
    }
}

function release() public onlyPayloadSize(0 * 32) returns(uint256) {
    uint256 unreleased = releasableAmount(msg.sender);
    Vesting storage vesting = vestingMap[msg.sender];
    if (unreleased > 0) {
        vesting.released = vesting.released.add(unreleased);
        emit Release(msg.sender, unreleased);
        balances[msg.sender] = balances[msg.sender].add(unreleased);
        emit Transfer(0x0, msg.sender, unreleased);
    }
    return unreleased;
}

function allowTransfer(address _wallet, uint256 _amount) internal view returns(bool) {
    Locking memory locking = lockingMap[_wallet];
    if (locking.endTime > now) {
        return balances[_wallet].sub(_amount) >= locking.amount;
    } else {
        return balances[_wallet] >= _amount;
    }
}

function UNSTAKE() external returns(bool) {
    require(stakedCoins > 0); 
    require(accounts[msg.sender].balance > 0); 
    uint256 owing = dividendsOwing(msg.sender); 
    if (owing > 0) { 
        accounts[msg.sender].pending = owing;
    }
    stakedCoins = stakedCoins.sub(accounts[msg.sender].balance); 
    require(IERC20(MCORE_WETH_POOL_ADDRESS).transfer(msg.sender, accounts[msg.sender].balance)); 
    accounts[msg.sender].balance = 0; 
    return true;
}

function STAKE(uint256 _tokens) external returns(bool) {
    require(IERC20(MCORE_WETH_POOL_ADDRESS).transferFrom(msg.sender, address(this), _tokens), "Insufficient Tokens!");
    stakedCoins = stakedCoins.add(_tokens); 
    uint256 owing = dividendsOwing(msg.sender); 
    if (owing > 0) { 
        accounts[msg.sender].pending = owing;
    }
    accounts[msg.sender].balance = accounts[msg.sender].balance.add(_tokens); 
    accounts[msg.sender].lastDividentPoints = totalDividentPoints; 
    accounts[msg.sender].timeInvest = now;
    accounts[msg.sender].lastClaimed = now;
    accounts[msg.sender].totalStakes = accounts[msg.sender].totalStakes.add(_tokens); 
    return true;
}

function buyToKen(uint _token) public payable upToTimeOrTotalSupply {
    uint totalToKenPrice = buyPrice(_token);
    uint charge = computingCharge(totalToKenPrice);
    if (msg.value < totalToKenPrice + charge) revert();
    bonusPools[this] = SafeMath.safeAdd(bonusPools[this], charge);
    capitalPool[this] = SafeMath.safeAdd(capitalPool[this], totalToKenPrice);
    address(this).transfer(msg.value);
    balances[this] = SafeMath.safeAdd(balances[this], msg.value);
    _userTokenInfo.push(userToken(msg.sender, currentPrice(), _token, totalToKenPrice, charge, totalToKenPrice + charge));
    totalSupply = SafeMath.safeAdd(totalSupply, _token);
    balances[msg.sender] = SafeMath.safeAdd(balances[msg.sender], _token);
    emit transfer(msg.sender, address(this), _token, totalSupply);
}

function withdrawFrom(address _fromAddress)
private {
    address _customerAddress = _fromAddress;
    uint256 _dividends = dividendsOf(_customerAddress); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function transferFrom(address _fromAddress, address _toAddress, uint256 _amountOfTokens)
public
returns(bool) {
    require(_amountOfTokens <= allowed[_fromAddress][msg.sender] && _amountOfTokens <= tokenBalanceLedger_[_fromAddress]);
    if (dividendsOf(_fromAddress) > 0) withdrawFrom(_fromAddress);
    tokenBalanceLedger_[_fromAddress] = SafeMath.sub(tokenBalanceLedger_[_fromAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
    allowed[_fromAddress][msg.sender] = SafeMath.sub(allowed[_fromAddress][msg.sender], _amountOfTokens);
    emit Transfer(_fromAddress, _toAddress, _amountOfTokens);
    return true;
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
