function withdraw(bytes32 _secret, address _ownerAddress) public {
    Swap memory swap = swaps[_ownerAddress][msg.sender];
    require(swap.secretHash == ripemd160(abi.encodePacked(_secret)));
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) > now);
    require(swap.secretHash == ripemd160(abi.encodePacked(_secret)));
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) > now);
    uint256 actualValue = swap.balance;
    uint256 tradeFee = actualValue.div(exchangeFee);
    uint256 balanceAfterDeduction = actualValue.sub(tradeFee);
    ERC20(swap.token).transfer(msg.sender, balanceAfterDeduction);
    ERC20(swap.token).transfer(exchangeFeeAddress, tradeFee);
    swaps[_ownerAddress][msg.sender].balance = 0;
    swaps[_ownerAddress][msg.sender].secret = _secret;
    emit Withdraw();
}

function refund(address _participantAddress) public {
    Swap memory swap = swaps[msg.sender][_participantAddress];
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) < now);
    ERC20(swap.token).transfer(msg.sender, swap.balance);
    clean(msg.sender, _participantAddress);
    emit Refund();
}

function createSwap(bytes20 _secretHash, address _participantAddress, uint256 _value, address _token) public {
    require(_value > 0);
    require(swaps[msg.sender][_participantAddress].balance == uint256(0));
    require(ERC20(_token).transferFrom(msg.sender, address(this), _value));
    swaps[msg.sender][_participantAddress] = Swap(
        _token,
        bytes32(0),
        _secretHash,
        now,
        _value
    );
    emit CreateSwap(now);
}

function renewSubscriptionByDays(uint256 _appId, uint256 _userId, uint _day) external {
    Application storage app = applications[_appId];
    require(app.appId == _appId);
    require(_day >= 1);
    uint256 amount = getPrice(_appId, _day);
    require(amount > 0);
    uint256 currentExpiration = app.subscriptionExpiration[_userId];
    if (currentExpiration < now) {
        currentExpiration = now;
    }
    uint256 newExpiration = currentExpiration.add(_day.mul(1 days));
    app.subscriptionExpiration[_userId] = newExpiration;
    uint256 txFee = processFee(amount);
    uint256 toAppOwner = amount.sub(txFee);
    require(token.transferFrom(msg.sender, app.beneficiary, toAppOwner));
    emit SubscriptionPurchase(
        msg.sender,
        _appId,
        _userId,
        _day,
        amount,
        newExpiration);
}

function refund(bytes32 _swapID) external onlyOpenSwaps(_swapID) onlyExpirableSwaps(_swapID) {
    Swap memory swap = swaps[_swapID];
    swapStates[_swapID] = States.EXPIRED;
    swap.ethTrader.transfer(swap.value);
    emit LogExpire(_swapID);
}

function redeem(bytes32 _swapID, bytes32 _secretKey) external onlyOpenSwaps(_swapID) onlyWithSecretKey(_swapID, _secretKey) {
    Swap memory swap = swaps[_swapID];
    swaps[_swapID].secretKey = _secretKey;
    swapStates[_swapID] = States.CLOSED;
    redeemedAt[_swapID] = now;
    swap.withdrawTrader.transfer(swap.value);
    emit LogClose(_swapID, _secretKey);
}

function refundable(bytes32 _swapID) external view returns(bool) {
    return (now >= swaps[_swapID].timelock && swapStates[_swapID] == States.OPEN);
}

function claimAuction(address _contract, uint256 _tokenId, bool awardType, string memory ownerId, address from) isValid(_contract) public {
    auctionSell storage temp = _auctionTokens[_tokenId][_contract];
    require(temp.endTime < now, "103");
    require(temp.minPrice > 0, "104");
    require(msg.sender == temp.bidder, "107");
    INFT(temp.nftContract).transferFrom(address(this), temp.bidder, _tokenId);
    (uint256 mainPerecentage, uint256 authorPercentage, address blindRAddress) = getPercentages(_tokenId, _contract);
    if (temp.currencyType < 1) {
        uint256 price = SafeMath.div(temp.bidAmount, 1000000000000);
        token = BUSD; 
        if (blindRAddress == address(0x0)) {
            token.transfer(platform, SafeMath.div(SafeMath.mul(price, platformPerecentage), 1000));
        }
        if (_contract == address(XNFT)) { 
            token.transfer(blindRAddress, SafeMath.div(SafeMath.mul(price, authorPercentage), 1000));
        }
        token.transfer(temp.seller, SafeMath.div(SafeMath.mul(price, mainPerecentage), 1000));
    } else {
        if (blindRAddress == address(0x0)) {
            bnbTransferAuction(platform, platformPerecentage, temp.bidAmount);
        }
        if (_contract == address(XNFT) || collectionsWithRoyalties[_contract]) { 
            bnbTransferAuction(platform, authorPercentage, temp.bidAmount);
        }
        bnbTransferAuction(platform, mainPerecentage, temp.bidAmount);
    }
    emit Claim(temp.bidder, temp.nftContract, _tokenId, temp.bidAmount, temp.seller, temp.currencyType);
    delete _auctionTokens[_tokenId][_contract];
}

