function transfer(
    address _to,
    uint256 _value
)
public
returns(bool) {
    require(!frozenAccount[msg.sender]);
    require(now > frozenTimestamp[msg.sender]);
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    balances[msg.sender] = balances[msg.sender] - _value;
    balances[_to] = balances[_to] + _value;
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function multiTransfer(
    address[] _tos,
    uint256[] _values
)
public
returns(bool) {
    require(!frozenAccount[msg.sender]);
    require(now > frozenTimestamp[msg.sender]);
    require(_tos.length == _values.length);
    uint256 len = _tos.length;
    require(len > 0);
    uint256 amount = 0;
    for (uint256 i = 0; i < len; i += 1) {
        amount = amount + _values[i];
    }
    require(amount <= balances[msg.sender]);
    for (uint256 j = 0; j < len; j += 1) {
        address _to = _tos[j];
        require(_to != address(0));
        balances[_to] = balances[_to] + _values[j];
        balances[msg.sender] = balances[msg.sender] - _values[j];
        emit Transfer(msg.sender, _to, _values[j]);
    }
    return true;
}

function transferFrom(
    address _from,
    address _to,
    uint256 _value
)
public
returns(bool) {
    require(!frozenAccount[_from]);
    require(now > frozenTimestamp[msg.sender]);
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    balances[_from] = balances[_from] - _value;
    balances[_to] = balances[_to] + _value;
    allowed[_from][msg.sender] = allowed[_from][msg.sender] - _value;
    emit Transfer(_from, _to, _value);
    return true;
}

function()
public payable {
    require(msg.value > 0);
    if (exchangeFlag) {
        if (msg.value >= minWei && msg.value <= maxWei) {
            if (raisedAmount < maxRaiseAmount) {
                uint256 valueNeed = msg.value;
                raisedAmount = raisedAmount + msg.value;
                if (raisedAmount > maxRaiseAmount) {
                    uint256 valueLeft = raisedAmount - maxRaiseAmount;
                    valueNeed = msg.value - valueLeft;
                    msg.sender.transfer(valueLeft);
                    raisedAmount = maxRaiseAmount;
                }
                if (raisedAmount >= maxRaiseAmount) {
                    exchangeFlag = false;
                }
                uint256 _value = valueNeed * raiseRatio;
                require(_value <= balances[admin]);
                balances[admin] = balances[admin] - _value;
                balances[msg.sender] = balances[msg.sender] + _value;
                emit Transfer(admin, msg.sender, _value);
            }
        } else {
            msg.sender.transfer(msg.value);
        }
    } else {
        msg.sender.transfer(msg.value);
    }
}

function _purchaseTokens(uint256 _incomingEthereum, address _referredBy) internal returns(uint256) {
    address _customerAddress = msg.sender;
    uint256 _undividedDividends = SafeMath.div(SafeMath.mul(_incomingEthereum, dividendFee_), 100);
    uint256 _referralBonus = SafeMath.div(_undividedDividends, 3);
    uint256 _greedyFee = SafeMath.div(SafeMath.mul(_undividedDividends, greedFee_), 100);
    uint256 _jackpotPay = SafeMath.div(SafeMath.mul(_incomingEthereum, jackpotFee_), 100);
    uint256 _dividends = SafeMath.sub(SafeMath.sub(_undividedDividends, _referralBonus), _greedyFee);
    uint256 _taxedEthereum = SafeMath.sub(SafeMath.sub(SafeMath.sub(_incomingEthereum, _undividedDividends), _jackpotPay), _greedyFee);
    jackpotCollected = SafeMath.add(jackpotCollected, _jackpotPay);
    devGreed.transfer(_greedyFee);
    uint256 _amountOfTokens = ethereumToTokens_(_taxedEthereum);
    uint256 _fee = _dividends * magnitude;
    require(_amountOfTokens > 0 && (SafeMath.add(_amountOfTokens, tokenSupply_) > tokenSupply_));
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress &&
        tokenBalanceLedger_[_referredBy] >= stakingRequirement
    ) {
        referralBalance_[_referredBy] = SafeMath.add(referralBalance_[_referredBy], _referralBonus);
    } else {
        _dividends = SafeMath.add(_dividends, _referralBonus);
        _fee = _dividends * magnitude;
    }
    if (tokenSupply_ > 0) {
        tokenSupply_ = SafeMath.add(tokenSupply_, _amountOfTokens);
        profitPerShare_ += (_dividends * magnitude / (tokenSupply_));
        _fee = _fee - (_fee - (_amountOfTokens * (_dividends * magnitude / (tokenSupply_))));
    } else {
        tokenSupply_ = _amountOfTokens;
    }
    tokenBalanceLedger_[_customerAddress] = SafeMath.add(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    int256 _updatedPayouts = (int256)((profitPerShare_ * _amountOfTokens) - _fee);
    payoutsTo_[_customerAddress] += _updatedPayouts;
    emit onTokenPurchase(_customerAddress, _incomingEthereum, _amountOfTokens, _referredBy);
    return _amountOfTokens;
}

