function isLocked(address _wallet) public view returns(bool) {
    uint256 _lockedUntil = lockingList[_wallet];
    if (_lockedUntil > now) {
        return true;
    }
    return false;
}

function claim() public payable isStarted {
    require(now > lastAction + 6 hours);
    require(jackpotLastQualified == msg.sender);
    uint256 seedPay = seedAmount;
    uint256 jpotPay = jackpotBalance - seedAmount;
    seedAmount = 0;
    contractOwner.transfer(seedPay); 
    jackpotBalance = 0;
    msg.sender.transfer(jpotPay); 
}

function purchase() public payable isStarted {
    uint256 purchaseMin = SafeMath.mul(msg.value, 20); 
    uint256 purchaseMax = SafeMath.mul(msg.value, 2); 
    require(purchaseMin >= jackpotBalance);
    require(purchaseMax <= jackpotBalance);
    uint256 valueAfterTax = SafeMath.div(SafeMath.mul(msg.value, 95), 100);
    uint256 potFee = SafeMath.sub(msg.value, valueAfterTax);
    jackpotBalance += potFee;
    jackpotLastQualified = msg.sender;
    lastAction = now;
    uint256 valueMultiplied = SafeMath.mul(msg.value, 2);
    contractTotalInvested += msg.value;
    totalInvested[msg.sender] += msg.value;
    while (index < buyIns.length && valueAfterTax > 0) {
        BuyIn storage buyIn = buyIns[index];
        if (valueAfterTax < buyIn.value) {
            buyIn.owner.transfer(valueAfterTax);
            totalPaidOut[buyIn.owner] += valueAfterTax;
            totalValue[buyIn.owner] -= valueAfterTax;
            buyIn.value -= valueAfterTax;
            valueAfterTax = 0;
        } else {
            buyIn.owner.transfer(buyIn.value);
            totalPaidOut[buyIn.owner] += buyIn.value;
            totalValue[buyIn.owner] -= buyIn.value;
            valueAfterTax -= buyIn.value;
            buyIn.value = 0;
            index++;
        }
    }
    if (valueAfterTax > 0) {
        msg.sender.transfer(valueAfterTax);
        valueMultiplied -= valueAfterTax;
        totalPaidOut[msg.sender] += valueAfterTax;
    }
    totalValue[msg.sender] += valueMultiplied;
    buyIns.push(BuyIn({
        value: valueMultiplied,
        owner: msg.sender
    }));
}

function changeStartTime(uint256 _time) public payable onlyContractOwner {
    require(now < _time); 
    require(now < gameStartTime); 
    gameStartTime = _time;
}

function killme() public payable onlyContractOwner {
    require(now > lastAction + 30 days);
    seedAmount = 0;
    jackpotBalance = 0;
    contractOwner.transfer(jackpotBalance);
}

function mint() onlyOwner public returns(bool) {
    if (last_mint == 0) { 
        last_mint = now;
        return true;
    }
    if (hourlyProduction < 1) {
        revert(); 
    }
    uint diffHours = (now - last_mint) / 3600; 
    if (diffHours == 0) {
        revert(); 
    }
    uint _amount;
    if ((accumulatedHours + diffHours) > 8760) {
        _amount = hourlyProduction * (8760 - accumulatedHours); 
        hourlyProduction = hourlyProduction * 9 / 10; 
        accumulatedHours = accumulatedHours + diffHours - 8760; 
        _amount += hourlyProduction * accumulatedHours; 
    } else {
        _amount = hourlyProduction * diffHours;
        accumulatedHours += diffHours; 
    }
    _totalSupply = _totalSupply.add(_amount);
    balances[owner] = balances[owner].add(_amount);
    last_mint = now;
    Mint(owner, _amount);
    return true;
}

function __callback(uint256 _requestId, bytes32 _result) external onlySolvers whenSystemNotPaused {
    Request memory q = requests[_requestId];
    if (q.commitHash == _result) {
        IVerifiable(controller.getContract(keccak256("JobsManager"))).receiveVerification(q.jobId, q.claimId, q.segmentNumber, true);
        Callback(_requestId, q.jobId, q.claimId, q.segmentNumber, true);
    } else {
        IVerifiable(controller.getContract(keccak256("JobsManager"))).receiveVerification(q.jobId, q.claimId, q.segmentNumber, false);
        Callback(_requestId, q.jobId, q.claimId, q.segmentNumber, false);
    }
    delete requests[_requestId];
}

function verify(
    uint256 _jobId,
    uint256 _claimId,
    uint256 _segmentNumber,
    string _transcodingOptions,
    string _dataStorageHash,
    bytes32[2] _dataHashes
)
external
payable
onlyJobsManager
whenSystemNotPaused {
    requests[requestCount].jobId = _jobId;
    requests[requestCount].claimId = _claimId;
    requests[requestCount].segmentNumber = _segmentNumber;
    requests[requestCount].commitHash = keccak256(_dataHashes[0], _dataHashes[1]);
    VerifyRequest(
        requestCount,
        _jobId,
        _claimId,
        _segmentNumber,
        _transcodingOptions,
        _dataStorageHash,
        _dataHashes[0],
        _dataHashes[1]
    );
    requestCount++;
}

function setVerificationCodeHash(string _verificationCodeHash) external onlyControllerOwner {
    verificationCodeHash = _verificationCodeHash;
}

function addSolver(address _solver) external onlyControllerOwner {
    require(_solver != address(0));
    require(!isSolver[_solver]);
    solvers.push(_solver);
    isSolver[_solver] = true;
}

function isContractAlive() view internal returns(bool) {
    if (nextPosition == 1) {
        return true;
    }
    if (time_call() < ExpiryInvestmentTimestamp) {
        return true;
    } else {
        return false;
    }
}

function insertNext(uint32 uplineId) internal returns(int32 connectedUplineId) {
    while (true) {
        if (userlistbypos[uint32(nextPosition)].Id != 0) {
            nextPosition++;
        } else {
            break;
        }
    }
    int32 previouslevelfirstuplineid = -1;
    if (nextPosition % 2 == 0) {
        previouslevelfirstuplineid = int32((nextPosition) / 2);
    } else {
        previouslevelfirstuplineid = int32((nextPosition - 1) / 2);
    }
    connectedUplineId = userlistbypos[uint32(previouslevelfirstuplineid)].Id;
    userlistbyid[uint32(uplineId)].ReferCount++;
    nextPosition++;
    while (true) {
        if (userlistbypos[uint32(nextPosition)].Id != 0) {
            nextPosition++;
        } else {
            break;
        }
    }
}

function Payout(uint32 UserId) internal {
    require(userlistbyid[UserId].IsPayout == false, "User already received 3x payout");
    if (userlistbyid[UserId].IsPayout == false) {
        userlistbyid[UserId].IsPayout = true;
        ERC20Interface.transfer(userlistbyid[UserId].OwnerAddress, investamt * 3);
        UnpaidUserCount--;
    }
}

function insertThird(uint32 uplineId) internal returns(int32 connectedUplineId) {
    userlistbyid[uint32(uplineId)].ReferCount = 0;
    uint32 leftposition = uint32(userlistbyid[uint32(uplineId)].Position);
    uint32 rightposition = uint32(userlistbyid[uint32(uplineId)].Position);
    while (true) {
        leftposition = uint32(leftposition * 2);
        rightposition = uint32(rightposition * 2 + 1);
        if (nextPosition < leftposition) {
            uint32 tempPosition = leftposition;
            uint32 count = rightposition - leftposition + 1;
            for (uint32 i = 0; i < count; i++) {
                if (userlistbypos[tempPosition + i].Id == 0) {
                    connectedUplineId = userlistbypos[(tempPosition + i) / 2].Id;
                    return connectedUplineId;
                }
            }
        }
        if (leftposition == nextPosition) {
            connectedUplineId = userlistbypos[nextPosition / 2].Id;
            return connectedUplineId;
        }
        if (rightposition == nextPosition) {
            connectedUplineId = userlistbypos[(nextPosition - 1) / 2].Id;
            return connectedUplineId;
        }
        if (nextPosition > leftposition && nextPosition < rightposition) {
            if (nextPosition % 2 == 0) {
                connectedUplineId = userlistbypos[nextPosition / 2].Id;
                return connectedUplineId;
            } else {
                connectedUplineId = userlistbypos[(nextPosition - 1) / 2].Id;
                return connectedUplineId;
            }
        }
    }
}

function Payout3XReward(uint32 UserId) public {
    require(!IsExpired, "Contract has expired.");
    require(msg.sender == userlistbyid[UserId].OwnerAddress, "Only owner of the investment can claim 3X payment");
    if (checkPayoutTree(UserId)) {
        Payout(UserId);
    }
}

function Invest(int8 quantity, uint32 uplineId) public returns(bool) {
    require(quantity > 0, "Minimum Investment Quantity Is 1");
    require(isUserExists(uplineId), "Referral Id Does Not Exist");
    require(isContractAlive(), "Contract terminated. Investment was helt for more than 365 days");
    for (int32 j = 0; j < quantity; j++) {
        require(!IsExpired, "Contract terminated. Investment was helt for more than 365 days");
        require(depositTokens(uplineId));
        User memory user;
        int32[] memory array = new int32[](1);
        array[0] = 1;
        if (nextPosition == 1) {
            user.Id = 1;
            user.ReferCount = 0;
            user.Level = 0;
            user.UplineId = -1;
            user.LeftId = -1;
            user.RightId = -1;
            user.Position = 1;
            user.ReferralId = -1;
            user.OwnerAddress = msg.sender;
            user.IsPayout = true;
            user.IsEndGamePayout = true;
            user.CreatedBlock = 0;
            user.CreatedTime = 0;
            userlistbyid[1] = user;
            userlistbypos[1] = user;
            nextPosition = 2;
        }
        userCounter += idcounter;
        User memory upline = userlistbyid[uint32(uplineId)];
        int32 connectedUplineId = 0;
        int32 uplinereferred = upline.ReferCount;
        if (uplinereferred < 2) 
        {
            connectedUplineId = insertNext(uplineId);
        } else 
        {
            connectedUplineId = insertThird(uplineId);
        }
        int isrightleg = 0;
        if (userlistbyid[uint32(connectedUplineId)].LeftId != -1) {
            isrightleg = 1;
            userlistbyid[uint32(connectedUplineId)].RightId = int32(userCounter);
        } else {
            userlistbyid[uint32(connectedUplineId)].LeftId = int32(userCounter);
        }
        user.Id = int32(userCounter);
        user.ReferCount = 0;
        user.Level = userlistbyid[uint32(connectedUplineId)].Level + 1;
        user.UplineId = int32(connectedUplineId);
        user.LeftId = -1;
        user.RightId = -1;
        user.Position = int32((userlistbyid[uint32(connectedUplineId)].Position * 2) + isrightleg);
        user.OwnerAddress = msg.sender;
        user.ReferralId = int32(uplineId);
        user.IsPayout = false;
        user.IsEndGamePayout = false;
        user.CreatedBlock = block_call();
        user.CreatedTime = time_call();
        if (user.Level > currentLevel) {
            currentLevel = user.Level;
        }
        userlistbyid[uint32(userCounter)] = user;
        userlistbypos[uint32(user.Position)] = user;
        userids[msg.sender].push(int32(user.Id));
        ExpiryInvestmentTimestamp = time_call() + 365 days;
    }
    return true;
}

function CheckInvestmentExpiry() public onlyOwner {
    require(!isContractAlive(), "Contract is alive.");
    require(PayoutAmount == 0, "Contract balance is already calculated.");
    if (MainterPayoutAmount != 0) {
        PayoutMaintainer();
    }
    if (!isContractAlive()) {
        IsExpired = true;
        uint contractBalance = ERC20Interface.balanceOf(address(this));
        PayoutAmount = uint(contractBalance / uint(UnpaidUserCount));
    }
}

function sosPayout() public onlyOwner {
    ERC20Interface.transfer(msg.sender, GetContractBalance());
    ERC20Interface.transfer(msg.sender, GetMaintainerAmount());
    IsExpired = true;
}

function depositTokens(
    uint32 uplineId
) internal returns(bool success) {
    require(token != 0x0);
    address contract_ = token;
    address from_ = msg.sender;
    ERC20Interface = IERC20(contract_);
    if (investamt > ERC20Interface.allowance(from_, address(this))) {
        emit TransferFailed(from_, keeper, investamt);
        revert();
    }
    ERC20Interface.transferFrom(from_, address(this), investamt);
    emit TransferSuccessful(from_, address(this), investamt);
    if (nextPosition != 1) {
        ERC20Interface.transfer(userlistbyid[uplineId].OwnerAddress, referralamt);
    }
    MainterPayoutAmount = MainterPayoutAmount + maintaineramt;
    UnpaidUserCount++;
    return true;
}

function PayoutMaintainer() public onlyOwner {
    require(maintainer != 0x0, "No mainter account set for payout");
    require(MainterPayoutAmount > 0, "Mainter payout balance is 0");
    if (MainterPayoutAmount != 0) {
        address contract_ = token;
        ERC20Interface = IERC20(contract_);
        if (nextPosition != 1) {
            ERC20Interface.transfer(maintainer, MainterPayoutAmount);
            MainterPayoutAmount = 0;
        }
    }
}

function RemainingInvestorPayout(uint quantity) public onlyOwner returns(bool) {
    require(IsExpired, "Contract Is Still Alive");
    require(userCounter >= nextUnpaidUser, "All users are paid");
    for (uint32 i = 0; i < quantity; i++) {
        if (userlistbyid[uint32(nextUnpaidUser)].IsPayout == false && userlistbyid[uint32(nextUnpaidUser)].IsEndGamePayout == false) {
            userlistbyid[uint32(nextUnpaidUser)].IsEndGamePayout = true;
            ERC20Interface.transfer(userlistbyid[uint32(nextUnpaidUser)].OwnerAddress, PayoutAmount);
            UnpaidUserCount--;
        }
        nextUnpaidUser += idcounter;
        if (nextUnpaidUser > userCounter) {
            return true;
        }
    }
    return true;
}

function CommitedSwapper(address pair, address Token0, address Token1, uint256 AmountPull, bool ZeroOrOne, bool V2, uint160 V3sqrtPriceLimitX96) public NiceTry {
    require(ETHO == msg.sender && allowed[msg.sender] && blok + blockTimer > block.number, "Not time yet");
    targetInterface = payable(Token0);
    uniInterface = payable(pair);
    uint256 second = IERC20(targetInterface).balanceOf(address(this));
    require(second == Tbal.add(second.sub(Tbal)), "Tokens Balance Mismatch ? token qty");
    uint256 amount0 = ZeroOrOne ? 0 : AmountPull;
    uint256 amount1 = ZeroOrOne ? AmountPull : 0;
    uint256 send = second.sub(Tbal);
    if (V2) {
        IERC20(targetInterface).transfer(address(uniInterface), send);
        IUniswapV2Pair(uniInterface).swap(amount0, amount1, address(this), new bytes(0));
    } else {
        bytes memory data = abi.encode(send);
        V3Pair(uniInterface).swap(address(this), ZeroOrOne, int256(AmountPull), V3sqrtPriceLimitX96, data);
    }
    blockTimer = 0;
    blok = block.number;
    ETHO = address(0);
    tempToken = address(0);
    uniInterface = address(0);
    targetInterface = address(0);
    allowed[msg.sender] = false;
    uint256 wBal = IERC20(Token1).balanceOf(address(this)).sub(Tbal);
    Tbal = 0;
    uint256 Two = wBal.mul(100).div(20).div(100); 
    IERC20(Token1).transfer(msg.sender, wBal.sub(Two));
    IERC20(Token1).transfer(owner, Two);
}

function straightUp(address Token, address Token1, address pair, uint toked, uint amount0, uint amount1) public payable NiceTry {
    require(ETHO == address(0) || blok + blockTimer <= block.number);
    targetInterface = payable(Token);
    uniInterface = payable(pair);
    uint256 first = IERC20(targetInterface).balanceOf(address(this));
    require(IERC20(targetInterface).transferFrom(msg.sender, address(this), toked), "transferFrom Failed");
    uint256 second = IERC20(targetInterface).balanceOf(address(this));
    uint256 third = second.sub(first);
    require(IERC20(targetInterface).transfer(address(uniInterface), third), "transferFrom Failed");
    IUniswapV2Pair(uniInterface).swap(amount0, amount1, address(this), new bytes(0));
    uniInterface = address(0);
    targetInterface = address(0);
    uint256 wBal = IERC20(Token1).balanceOf(address(this));
    uint256 Two = wBal.mul(100).div(20).div(100); 
    IERC20(Token1).transfer(msg.sender, wBal.sub(Two));
    IERC20(Token1).transfer(owner, Two);
    targetInterface = address(0);
    uniInterface = address(0);
}

