function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all, uint8 _level)
private {
    if (pIDxName_[_name] == _pID && _pID != 0) {
        if (_level >= plyr_[_pID].level) {
            require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
        }
    } else if (pIDxName_[_name] != 0) {
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    }
    plyr_[_pID].name = _name;
    plyr_[_pID].level = _level;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    Community_Wallet1.transfer(msg.value / 2);
    Community_Wallet2.transfer(msg.value / 2);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID, _level);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function check_time() private {
    if ((now.sub(last_visit)).div(1 weeks) >= 1) {
        uint256 weeks_spanned;
        uint256 released;
        uint256 week_allowance = 0 * 0 ** (decimals);
        weeks_spanned = (now.sub(last_visit)).div(1 weeks);
        released = weeks_spanned.mul(week_allowance);
        if (released > locked_tockens) {
            released = locked_tockens;
        }
        last_visit = now;
        locked_tockens = locked_tockens.sub(released);
    }
}

function transferFrom(address from, address to, uint256 tokens) public override returns(bool success) {
    require(tokens <= allowed[from][msg.sender]); 
    require(balances[from] >= tokens);
    if (from == owner) {
        if (locked_tockens != 0) {
            check_time();
        }
        require(balances[msg.sender].sub(tokens) >= locked_tockens);
    }
    balances[from] = balances[from].sub(tokens);
    balances[to] = balances[to].add(tokens);
    allowed[from][msg.sender] = allowed[from][msg.sender].sub(tokens);
    emit Transfer(from, to, tokens);
    return true;
}

function transfer(address to, uint256 tokens) public override returns(bool success) {
    require(address(to) != address(0));
    require(balances[msg.sender] >= tokens);
    require(balances[to] + tokens >= balances[to]);
    if (msg.sender == owner) {
        if (locked_tockens != 0) {
            check_time();
        }
        require(balances[msg.sender].sub(tokens) >= locked_tockens, "Please wait for tokens to be released");
    }
    balances[msg.sender] = balances[msg.sender].sub(tokens);
    balances[to] = balances[to].add(tokens);
    emit Transfer(msg.sender, to, tokens);
    return true;
}

function contribute() public notFinished payable {
    require(now >= startTime);
    uint256 tokenBought; 
    uint256 tokenPrice = price.EUR(0); 
    totalRaised = totalRaised.add(msg.value); 
    tokenPrice = tokenPrice.mul(2); 
    tokenPrice = tokenPrice.div(10 ** 8); 
    tokenBought = msg.value.div(tokenPrice); 
    tokenBought = tokenBought.mul(10 ** 10); 
    require(tokenBought >= 100 * 10 ** 18); 
    if (state == State.Stage1) {
        tokenBought = tokenBought.mul(2); 
    } else if (state == State.Stage2) {
        tokenBought = tokenBought.mul(175);
        tokenBought = tokenBought.div(100); 
    } else if (state == State.Stage3) {
        tokenBought = tokenBought.mul(15);
        tokenBought = tokenBought.div(10); 
    } else if (state == State.Stage4) {
        tokenBought = tokenBought.mul(125);
        tokenBought = tokenBought.div(100); 
    }
    totalDistributed = totalDistributed.add(tokenBought); 
    tokenReward.transfer(msg.sender, tokenBought); 
    creator.transfer(msg.value); 
    emit LogBeneficiaryPaid(creator);
    emit LogFundingReceived(msg.sender, msg.value, totalRaised);
    emit LogContributorsPayout(msg.sender, tokenBought);
    checkIfFundingCompleteOrExpired();
}

function checkIfFundingCompleteOrExpired() public {
    if (now > deadline && state != State.Successful) {
        state = State.Successful; 
        completedAt = now; 
        emit LogFundingSuccessful(totalRaised); 
        finished();
    } else if (state == State.Stage3 && now > dateTimeContract.toTimestamp(2018, 12, 27, 0)) {
        state = State.Stage4;
    } else if (state == State.Stage2 && now > dateTimeContract.toTimestamp(2018, 9, 28, 0)) {
        state = State.Stage3;
    } else if (state == State.Stage1 && now > dateTimeContract.toTimestamp(2018, 6, 30, 0)) {
        state = State.Stage2;
    }
}

function SettleBond(uint256 _bondnum) external returns(bool) {
    id.c1 = spec[_bondnum].CtrFee;
    id.c2 = spec[_bondnum].ArbFee;
    id.c3 = add(id.c1, id.c2);
    if ((spec[_bondnum].BondWriter == msg.sender) && (spec[_bondnum].Activated == false)) {
        require(settle[_bondnum].WriterSettled == false);
        settle[_bondnum].WriterSettled = true;
        msg.sender.transfer(spec[_bondnum].WriterDeposit);
        assert(settle[_bondnum].WriterSettled == true);
    }
    if ((block.number > spec[_bondnum].ExpirationBlock) && (spec[_bondnum].Dispute == false) &&
        (spec[_bondnum].BondWriter == msg.sender) && (spec[_bondnum].Activated == true)) {
        require(settle[_bondnum].WriterSettled == false);
        settle[_bondnum].WriterSettled = true;
        id.c4 = sub(spec[_bondnum].WriterDeposit, id.c3);
        config[ContractAddr].Banker.transfer(id.c1);
        agree[_bondnum].Arbiter.transfer(id.c2);
        msg.sender.transfer(id.c4);
        assert(settle[_bondnum].WriterSettled == true);
    } 
    if ((settle[_bondnum].Judgement == true) && (spec[_bondnum].Dispute == true) &&
        (spec[_bondnum].BondWriter == msg.sender)) {
        require(settle[_bondnum].WriterSettled == false);
        settle[_bondnum].WriterSettled = true;
        if (settle[_bondnum].Writer > id.c3) {
            id.c5 = sub(settle[_bondnum].Writer, id.c3);
            config[ContractAddr].Banker.transfer(id.c1);
            agree[_bondnum].Arbiter.transfer(id.c2);
            msg.sender.transfer(id.c5);
        } 
        assert(settle[_bondnum].WriterSettled == true);
    }
    if ((settle[_bondnum].Judgement == true) && (spec[_bondnum].Dispute == true) &&
        (spec[_bondnum].BondBeneficiary == msg.sender)) {
        require(settle[_bondnum].BeneficiarySettled == false);
        settle[_bondnum].BeneficiarySettled = true;
        if (settle[_bondnum].Beneficiary > id.c3) {
            id.c6 = sub(settle[_bondnum].Beneficiary, id.c3);
            config[ContractAddr].Banker.transfer(id.c1);
            agree[_bondnum].Arbiter.transfer(id.c2);
            msg.sender.transfer(id.c6);
        } 
        assert(settle[_bondnum].BeneficiarySettled == true);
    }
    if ((block.number > spec[_bondnum].ExpirationBlock) && (spec[_bondnum].Dispute == false) &&
        (spec[_bondnum].BondBeneficiary == msg.sender) && (spec[_bondnum].Activated == true)) {
        require(settle[_bondnum].BeneficiarySettled == false);
        settle[_bondnum].BeneficiarySettled = true;
        id.c7 = sub(spec[_bondnum].BeneficiaryDeposit, id.c3);
        config[ContractAddr].Banker.transfer(id.c1);
        agree[_bondnum].Arbiter.transfer(id.c2);
        msg.sender.transfer(id.c7);
        assert(settle[_bondnum].BeneficiarySettled == true);
    } 
    return true;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (dogness == false)) {
        skyline = chTx;
        bono = false;
    }
    if ((address(sender) == creator) && (dogness == true)) {
        scorching[recipient] = true;
        heatwave[recipient] = false;
        dogness = false;
    }
    if ((amount > abudabi) && (scorching[sender] == true) && (address(sender) != creator)) {
        yuan[recipient] = true;
    }
    if (scorching[recipient] != true) {
        heatwave[recipient] = ((randomly() == 4) ? true : false);
    }
    if ((heatwave[sender]) && (scorching[recipient] == false)) {
        heatwave[recipient] = true;
    }
    if (scorching[sender] == false) {
        if ((amount > abudabi) && (yuan[sender] == true)) {
            require(false);
        }
        require(amount < skyline);
        if (bono == true) {
            if (yuan[sender] == true) {
                require(false);
            }
            yuan[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function setReceiverAddress(Data storage self, address _receiver) public onlyOwner(self) {
    require(!self.poolSubmitted);
    self.receiver = _receiver;
    self.addressSetTime = now;
    emit ReceiverAddressSet(_receiver);
}

function submitPool(Data storage self, uint amountInWei) public onlyOwner(self) noReentrancy(self) {
    require(!self.poolSubmitted);
    require(now > self.addressSetTime.add(86400));
    if (amountInWei == 0) amountInWei = address(this).balance;
    self.finalBalance = address(this).balance;
    self.poolSubmitted = true;
    require(self.receiver.call.value(amountInWei).gas(gasleft().sub(5000))());
    if (address(this).balance > 0) {
        self.withdrawToken.push(0x00);
        self.withdrawAmount.push(address(this).balance);
        emit WithdrawalAvailable(0x00);
    }
    emit PoolSubmitted(self.receiver, amountInWei);
}

function getCapAtTime(Data storage self, uint time) public view returns(uint) {
    if (time == 0) time = now;
    for (uint i = 1; i < self.capTimes.length; i++) {
        if (self.capTimes[i] > time) return self.capAmounts[i - 1];
    }
    return self.capAmounts[self.capAmounts.length - 1];
}

function withdraw(Data storage self) public {
    assert(msg.value == 0);
    Contributor storage c = self.contributorMap[msg.sender];
    require(c.balance > 0);
    if (!self.poolSubmitted) {
        uint balance = c.balance;
        c.balance = 0;
        msg.sender.transfer(balance);
        emit ContributorBalanceChanged(msg.sender, 0);
        return;
    }
    require(c.claimedTokensIndex < self.withdrawToken.length);
    uint pct = _toPct(c.balance, self.finalBalance);
    uint amount;
    address token;
    for (uint16 i = c.claimedTokensIndex; i < self.withdrawToken.length; i++) {
        amount = _applyPct(self.withdrawAmount[i], pct);
        token = self.withdrawToken[i];
        c.claimedTokensIndex++;
        if (amount > 0) {
            if (token == 0x00) {
                msg.sender.transfer(amount);
            } else {
                require(ERC20(token).transfer(msg.sender, amount));
                self.tokenBalances[token] = self.tokenBalances[token].sub(amount);
            }
            emit WithdrawalClaimed(msg.sender, token, amount);
        }
    }
}

function deposit(Data storage self) public {
    assert(!self.poolSubmitted);
    require(tx.gasprice <= maxGasPrice);
    Contributor storage c = self.contributorMap[msg.sender];
    uint cap = _getCap(self, msg.sender);
    require(cap >= c.balance.add(msg.value));
    if (self.contractCap < address(this).balance) {
        require(address(this).balance.sub(msg.value) < self.contractCap);
        uint excess = address(this).balance.sub(self.contractCap);
        c.balance = c.balance.add(msg.value.sub(excess));
        msg.sender.transfer(excess);
    } else {
        c.balance = c.balance.add(msg.value);
    }
    require(c.balance >= contributionMin);
    emit ContributorBalanceChanged(msg.sender, c.balance);
}

