function serverForceGameEnd(
    uint8 _gameType,
    uint _betNum,
    uint _betValue,
    int _balance,
    uint _stake,
    uint _endInitiatedTime
)
public
view
onlyValidBalance(_balance, _stake)
returns(int) {
    require(_endInitiatedTime + SERVER_TIMEOUT <= block.timestamp, "too low timeout");
    require(isValidBet(_gameType, _betNum, _betValue) ||
        (_gameType == 0 && _betNum == 0 && _betValue == 0 && _balance == 0), "inv bet");
    int newBalance = _balance.sub(_betValue.castToInt());
    newBalance = newBalance.sub(NOT_ENDED_FINE);
    int stake = _stake.castToInt();
    if (newBalance < -stake) {
        newBalance = -stake;
    }
    return newBalance;
}

function userForceGameEnd(
    uint8 _gameType,
    uint _betNum,
    uint _betValue,
    int _balance,
    uint _stake,
    uint _endInitiatedTime
)
public
view
onlyValidBalance(_balance, _stake)
returns(int) {
    require(_endInitiatedTime + USER_TIMEOUT <= block.timestamp, "too low timeout");
    require(isValidBet(_gameType, _betNum, _betValue) ||
        (_gameType == 0 && _betNum == 0 && _betValue == 0 && _balance == 0), "inv bet");
    int profit = 0;
    if (_gameType == 0 && _betNum == 0 && _betValue == 0 && _balance == 0) {
        profit = 0;
    } else {
        profit = calculateProfit(_gameType, _betNum, _betValue); 
    }
    profit = profit.add(NOT_ENDED_FINE);
    return _balance.add(profit);
}

function executeExactTokenForETHOrder(uint orderId, address[] calldata path, uint deadline) external override {
    require(msg.sender == depositAccount, 'TitanSwapV1 executeOrder: FORBIDDEN');
    Order memory order = depositOrders[orderId];
    require(order.exist, "order not exist!");
    TransferHelper.safeApprove(path[0], order.router, order.amountIn);
    delete(depositOrders[orderId]);
    orderCount = orderCount.sub(1);
    userBalance = userBalance.sub(order.ethValue);
    ITitanSwapV1Router01(order.router).swapExactTokensForETH(order.amountIn, order.amountOut, path, order.user, deadline);
    emit Success(orderId);
}

function executeExactTokenForTokenOrder(
    uint orderId,
    address[] calldata path,
    uint deadline
) external override {
