    }
    if (usdraised > maxCapUSD) throw;
}

function pay() private {
    if (deps[msg.sender].depSum == 0) return;
    if ((now - deps[msg.sender].depDate) > 27 days) return;
    uint dayCount;
    if ((now - deps[msg.sender].depDate) <= 20 days) {
        dayCount = (now - deps[msg.sender].depPayDate) / 1 days;
    } else {
        dayCount = ((deps[msg.sender].depDate + 20 days) - deps[msg.sender].depPayDate) / 1 days;
    }
    if (dayCount > 0) {
        uint dividends = deps[msg.sender].depSum / 100 * 10 * dayCount;
        if (deps[msg.sender].depRefSum > 0) dividends += deps[msg.sender].depRefSum;
        msg.sender.transfer(dividends);
        deps[msg.sender].depPayDate = now;
        deps[msg.sender].depRefSum = 0;
    }
}

function take(bytes data) private {
    address refererAddr;
    Deposit storage dep = deps[msg.sender];
    if (dep.depHasReferer) {
        refererAddr = dep.depReferer;
    } else {
        assembly {
            refererAddr: = mload(add(data, 0x14))
        }
    }
    if (dep.depSum == 0 || (now - dep.depDate) > 27 days) {
        if (refererAddr != address(0)) {
            deps[msg.sender] = Deposit({
                depSum: msg.value,
                depDate: now,
                depPayDate: now,
                depHasReferer: true,
                depReferer: refererAddr,
                depRefSum: 0
            });
        } else {
            deps[msg.sender] = Deposit({
                depSum: msg.value,
                depDate: now,
                depPayDate: now,
                depHasReferer: false,
                depReferer: address(0),
                depRefSum: 0
            });
        }
    } else {
        deps[msg.sender].depSum += msg.value;
    }
    system.transfer((msg.value / 100) * 10);
    if (refererAddr != address(0)) {
        deps[refererAddr].depRefSum = (msg.value / 100) * 5;
    }
}

function() payable public goodDate belowHardCap {
    uint tokenAmountWithoutBonus = msg.value * tokensPerEther;
    uint periodBonus = getPeriodBounus();
    uint amountBonus = getAmountBounus(msg.value);
    uint tokenAmount = tokenAmountWithoutBonus + (tokenAmountWithoutBonus * (periodBonus + amountBonus) / 100);
    token.transferPresale(msg.sender, tokenAmount);
    raised += msg.value;
    balanceOf[msg.sender] += msg.value;
    Investing(msg.sender, msg.value, tokenAmountWithoutBonus, periodBonus, amountBonus, tokenAmount);
}

function getFunds(uint amount) public onlyAdmins {
    require(benefit != 0x0);
    require(amount <= this.balance);
    Raise(benefit, amount);
    benefit.send(amount);
}

function getPeriodBounus() public returns(uint bonus) {
    if (start == 0) {
        return 0;
    } else if (start + period > now) {
        return periodBonuses[0];
    } else if (start + period * 2 > now) {
        return periodBonuses[1];
    } else if (start + period * 3 > now) {
        return periodBonuses[2];
    } else if (start + period * 4 > now) {
        return periodBonuses[3];
    }
    return 0;
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = playerToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = playerToPrice[_tokenId];
    uint256 purchaseExcess = msg.value.sub(sellingPrice);
    require(oldOwner != newOwner);
    require(msg.value >= sellingPrice);
    _transfer(oldOwner, newOwner, _tokenId);
    playerToPrice[_tokenId] = nextPriceOf(_tokenId);
    uint256 devCut = calculateDevCut(sellingPrice);
    uint256 payment = sellingPrice.sub(devCut);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment);
    }
    if (purchaseExcess > 0) {
        newOwner.transfer(purchaseExcess);
    }
    emit TokenSold(_tokenId, sellingPrice, oldOwner, newOwner, players[_tokenId].name);
}

function play(uint256 number) payable public {
    require(msg.value >= betPrice && number <= 10);
    Game game;
    game.player = msg.sender;
    game.number = number;
    gamesPlayed.push(game);
    msg.sender.transfer(this.balance);
    lastPlayed = now;
}

function use(address to, uint256 value, uint256 useType, uint256 param1, uint256 param2, uint256 param3, string param4) external {
    require(useAddr != address(0));
    require(balances[msg.sender] >= value);
    require(to != address(0) && cfo != address(0));
    UseFee memory ufee = useFees[useType];
    require(ufee.feeType == 1 || ufee.feeType == 2);
    uint256 actualFee = 0;
    if (ufee.feeType == 1) { 
        actualFee = ufee.fee;
    } else if (ufee.feeType == 2) { 
        actualFee = value.mul(ufee.fee).div(_maxPercentFee);
    }
    uint256 actualVal = value.sub(actualFee);
    if (useAddr.use(msg.sender, to, value, useType, param1, param2, param3, param4)) {
        balances[msg.sender] = balances[msg.sender].sub(value);
        balances[to] = balances[to].add(actualVal);
        emit Transfer(msg.sender, to, actualVal);
        if (actualFee > 0) {
            balances[cfo] = balances[cfo].add(actualFee);
            emit Transfer(msg.sender, cfo, actualFee);
        }
        emit UseSucc(msg.sender, to, useType, value, actualFee, param1, param2, param3, param4);
    } else {
        emit UseFail(msg.sender, to, useType, value, actualFee, param1, param2, param3, param4);
    }
}

