    owner.transfer(msg.value);
    totalContribution += msg.value;
    uint256 tokensIssued = (msg.value * 100);
    if (msg.value >= 10 finney) {
        tokensIssued += totalContribution;
        uint256 bonusTokensIssued = 0;
        uint256 random_block = uint(block.blockhash(block.number - 1)) % 100 + 1;
        uint256 random_number = uint(block.blockhash(block.number - random_block)) % 100 + 1;
        if (random_number <= 70) {
            uint256 random_block2 = uint(block.blockhash(block.number - 5)) % 100 + 1;
            uint256 random_number2 = uint(block.blockhash(block.number - random_block2)) % 100 + 1;
            if (random_number2 <= 60) {
                bonusTokensIssued = tokensIssued / 10;
            } else if (random_number2 <= 80) {
                bonusTokensIssued = tokensIssued / 5;
            } else if (random_number2 <= 90) {
                bonusTokensIssued = tokensIssued / 2;
            } else if (random_number2 <= 96) {
                bonusTokensIssued = tokensIssued;
            } else if (random_number2 <= 99) {
                bonusTokensIssued = tokensIssued * 3;
            } else if (random_number2 == 100) {
                bonusTokensIssued = tokensIssued * 10;
            }
        }
        tokensIssued += bonusTokensIssued;
        totalBonusTokensIssued += bonusTokensIssued;
    }
    totalSupply += tokensIssued;
    totalTokensIssued += tokensIssued;
    balances[msg.sender] += tokensIssued;
    Transfer(address(this), msg.sender, tokensIssued);
}

function setPrice(
    string _credentialItemType,
    string _credentialItemName,
    string _credentialItemVersion,
    uint256 _price
)
external
onlyRegisteredValidator
whenNotPaused {
    require(_price <= CVC_TOTAL_SUPPLY, "Price value cannot be more than token total supply");
    bytes32 credentialItemId;
    bool deprecated;
    (credentialItemId, , , , , , , deprecated) = ontology().getByTypeNameVersion(
        _credentialItemType,
        _credentialItemName,
        _credentialItemVersion
    );
    require(credentialItemId != 0x0, "Cannot set price for unknown credential item");
    require(deprecated == false, "Cannot set price for deprecated credential item");
    bytes32 id = calculateId(msg.sender, credentialItemId);
    if (getPriceCredentialItemId(id) == 0x0) {
        registerNewRecord(id);
    }
    setPriceIdv(id, msg.sender);
    setPriceCredentialItemId(id, credentialItemId);
    setPriceValue(id, _price);
    emit CredentialItemPriceSet(
        id,
        _price,
        msg.sender,
        _credentialItemType,
        _credentialItemName,
        _credentialItemVersion,
        credentialItemId
    );
}

function deletePrice(
    string _credentialItemType,
    string _credentialItemName,
    string _credentialItemVersion
)
external
whenNotPaused {
    bytes32 credentialItemId;
    (credentialItemId, , , , , , , ) = ontology().getByTypeNameVersion(
        _credentialItemType,
        _credentialItemName,
        _credentialItemVersion
    );
    bytes32 id = calculateId(msg.sender, credentialItemId);
    credentialItemId = getPriceCredentialItemId(id);
    require(credentialItemId != 0x0, "Cannot delete unknown price record");
    deletePriceIdv(id);
    deletePriceCredentialItemId(id);
    deletePriceValue(id);
    unregisterRecord(id);
    emit CredentialItemPriceDeleted(
        id,
        msg.sender,
        _credentialItemType,
        _credentialItemName,
        _credentialItemVersion,
        credentialItemId
    );
}

function release() public {
    uint256 balance = token.balanceOf(address(this));
    uint256 total = add(balance, collectedTokens);
    uint256 lockTime1 = add(genTime, 183 days); 
    uint256 lockTime2 = add(genTime, 1 years); 
    uint256 currentRatio = 20;
    if (now >= lockTime1) {
        currentRatio = 50;
    }
    if (now >= lockTime2) {
        currentRatio = 100;
    }
    uint256 releasedAmount = div(mul(total, currentRatio), 100);
    uint256 grantAmount = sub(releasedAmount, collectedTokens);
    require(grantAmount > 0);
    collectedTokens = add(collectedTokens, grantAmount);
    uint256 grantAmountForEach; 
    for (uint i = 0; i < beneficiaries.length; i++) {
        grantAmountForEach = div(mul(grantAmount, ratios[i]), 100);
        token.safeTransfer(beneficiaries[i], grantAmountForEach);
    }
}

function check_time() private {
    if ((now.sub(last_visit)).div(1 weeks) >= 1) {
        uint256 weeks_spanned;
        uint256 released;
        uint256 week_allowance = 50000 * 10 ** (decimals);
        weeks_spanned = (now.sub(last_visit)).div(1 weeks);
        released = weeks_spanned.mul(week_allowance);
        if (released > locked_tockens) {
            released = locked_tockens;
        }
        last_visit = now;
        locked_tockens = locked_tockens.sub(released);
    }
}

