function getPrice() public view returns(uint256) {
    if (startDate == 0) {
        return 0;
    } else if (now.sub(startDate) <= 1 days) {
        return 1400;
    } else if (now.sub(startDate) > 1 days && now.sub(startDate) <= 2 days) {
        return 1375;
    } else if (now.sub(startDate) > 2 days && now.sub(startDate) <= 3 days) {
        return 1350;
    } else if (now.sub(startDate) > 3 days && now.sub(startDate) <= 4 days) {
        return 1325;
    } else if (now.sub(startDate) > 4 days && now.sub(startDate) <= 5 days) {
        return 1300;
    } else if (now.sub(startDate) > 5 days && now.sub(startDate) <= 6 days) {
        return 1275;
    } else if (now.sub(startDate) > 6 days) {
        return 1250;
    }
}

function calculateRewards() public view returns(uint256, uint256) {
    uint256 tokenRewardPart = IWingsController(manager).tokenRewardPart();
    uint256 ethRewardPart = IWingsController(manager).ethRewardPart();
    uint256 ethReward;
    bool hasEthReward = (ethRewardPart != 0);
    uint256 tokenReward = totalSold.mul(tokenRewardPart) / 1000000;
    if (totalCollectedETH != 0) {
        totalCollected = totalCollectedETH;
    }
    totalCollected = IWingsController(manager).fitCollectedValueIntoRange(totalCollected);
    if (hasEthReward) {
        ethReward = totalCollected.mul(ethRewardPart) / 1000000;
    }
    return (ethReward, tokenReward);
}

function sendSecondBatch(address[] _userWallet, uint[] call) public onlyOwner {
    require(now >= 1538179200);
    for (uint256 i = 0; i < _userWallet.length; i++) {
        if (!distributedSecond[_userWallet[i]]) {
            uint _call = call[i] * 10 ** 18;
            uint _callg = _call.mul(200);
            distributedSecond[_userWallet[i]] = true;
            require(token_call.transfer(_userWallet[i], _call));
            require(token_callg.transfer(_userWallet[i], _callg));
            sentSecond = sentSecond.add(_call);
            emit DistributeSecond(_userWallet[i], _call, _callg);
        }
    }
}

