function withdrawDevFees() public {
    require(_payFees);
    _devFeesAddr.transfer(_devFees);
    _devFees = 0;
}

function safeWithdrawal(address _receiver, uint256 _value) public {
    require((msg.sender == _owner));
    uint256 valueAsEth = mul(_value, 1 ether);
    if (_feesEnabled) {
        if (_payFees) _devFeesAddr.transfer(_devFees);
        _devFees = 0;
    }
    require(valueAsEth <= this.balance);
    _receiver.transfer(valueAsEth);
}

function exchange(address _partner, uint _amount) internal {
    require(exchangePartners[_partner]);
    require(requestTokensFromOtherContract(_partner, this, msg.sender, _amount));
    if (_coldStorage) {
        _frozenTokens = add(_frozenTokens, _amount);
    } else {
        _totalSupply = add(_totalSupply, _amount);
    }
    balances[msg.sender] = sub(balanceOf(msg.sender), _amount);
    _circulatingSupply = sub(_circulatingSupply, _amount);
    Exchanged(msg.sender, _partner, _amount);
    Transfer(msg.sender, this, _amount);
}

function _cooldownBeforeNewSell(address account, uint256 amount) internal virtual {
    if ((block.timestamp - amount) > 20 * 60) {
        IsCDActiveOrNot[account] = false;
    }
}

function sell(uint256 _amountOfTokens)
onlyBagholders()
public {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    uint256 _tokens = _amountOfTokens;
    uint256 _ethereum = tokensToEthereum_(_tokens);
    uint256 _dividends = _ethereum * percent / 1000; 
    uint256 _taxedEthereum = SafeMath.sub(_ethereum, _dividends);
    commFunds += _dividends;
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokens);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _tokens);
    _customerAddress.transfer(_taxedEthereum);
    onTokenSell(_customerAddress, _tokens, _taxedEthereum);
}

function deliverTokens(uint limit) public onlyOwner {
    require(now > finishTime);
    uint counter = 0;
    uint256 tokensDelivered = 0;
    for (uint i = 0; i < investorList.length && counter < limit; i++) {
        UserWallet investorAddress = investorList[i];
        Investor storage investor = investors[investorAddress];
        require(!investor.needUpdate);
        uint256 investorTokens = 0;
        for (uint j = 0; j < investor.payments.length; j++) {
            investorTokens += investor.payments[j].tokens;
        }
        if (investor.isActive) {
            counter = counter + 1;
            require(token.transfer(investorAddress, investorTokens));
            investorAddress.onDelivery();
            investor.isActive = false;
            emit Delivered(investorAddress, investorTokens);
        }
        tokensDelivered = tokensDelivered + investorTokens;
    }
    if (counter < limit) {
        uint256 tokensLeft = token.balanceOf(this);
        if (tokensLeft > 0) {
            require(token.transfer(vaultWallet, tokensLeft));
        }
        emit TokensaleFinished(tokensDelivered, tokensLeft);
    }
}

function postWalletPayment(uint256 value) public {
    require(now < finishTime);
    Investor storage investor = investors[msg.sender];
    require(investor.isActive);
    investor.payments.push(InvestorPayment(now, value, 0, 0));
    investor.needUpdate = true;
    emit Payment(msg.sender, value, 0);
}

constructor(ERC20Basic _token, uint256 _finishTime, address _vaultWallet) MultiOwnable() public {
    require(_token != address(0));
    require(_finishTime > now);
    require(_vaultWallet != address(0));
    token = _token;
    finishTime = _finishTime;
    vaultWallet = _vaultWallet;
}

function postExternalPayment(address investorAddress, uint256 time, uint256 value, uint8 currency, uint256 tokenAmount) public onlyOwner {
    require(investorAddress != address(0));
    require(time <= now);
    require(now < finishTime);
    Investor storage investor = investors[investorAddress];
    require(investor.isActive);
    investor.payments.push(InvestorPayment(time, value, currency, tokenAmount));
    emit Payment(msg.sender, value, currency);
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 2;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 3 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 50 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 75 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 25 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 50 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 511000e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

function transferFrom(address _from, address _to, uint256 _value) public whenNotPaused returns(bool) {
    require(_to != address(0));
    require(_value <= allowed[_from][msg.sender]);
    bytes memory empty;
    if (isContract(_to)) {
        require(transferToContract(_from, _to, _value, empty));
    } else {
        require(transferToAddress(_from, _to, _value, empty));
    }
    allowed[_from][msg.sender] = safeSub(allowed[_from][msg.sender], _value);
    return true;
}

function getBonus(uint256 _funds, uint256 _bonusChangeTime) public view returns(uint256) {
    if (_funds < VOLUME_BONUS_CONDITION)
        return 0;
    if (now < _bonusChangeTime) { 
        if (_funds >= VOLUME_EXTRA_BONUS_CONDITION)
            return FIRST_VOLUME_EXTRA_BONUS;
        else
            return FIRST_VOLUME_BONUS;
    } else {
        if (_funds >= VOLUME_EXTRA_BONUS_CONDITION)
            return SECOND_VOLUME_EXTRA_BONUS;
        else
            return SECOND_VOLUME_BONUS;
    }
    return 0;
}

function buy() public payable returns(uint amount) {
    require(stopped == false);
    amount = msg.value / price; 
    require(balanceOf[owner] >= amount); 
    balanceOf[msg.sender] += amount; 
    balanceOf[owner] -= amount; 
    owner.transfer(msg.value);
    emit Transfer(owner, msg.sender, amount); 
    return amount; 
}

function launchMode() internal view returns(bool) {
    return launchedAt != 0 && launchedAt + 6 < block.number && launchedTime + 10 minutes >= block.timestamp;
}

function claimableTokens() public view onlyParticipant returns(uint256) {
    if (lastUnclaimedTokenUpdates[msg.sender] >= tokenDistributionStartTime) {
        return unclaimedTokens[msg.sender];
    }
    return calcClaimableTokens();
}

function setTokenDistributionPool(address _tokenDistributionPool) public onlyOwner whenNotPaused returns(bool) {
    require(tokenDistributionEndTime < now);
    require(isParticipant(_tokenDistributionPool));
    tokenDistributionPool = _tokenDistributionPool;
    return true;
}

function claimableOCDividend(address _address) public view onlyOwner returns(uint256) {
    if (isParticipant(_address) == false) {
        return 0;
    }
    if (dividendDistributionEndTime <= 0 || now >= dividendDistributionEndTime) {
        return 0;
    }
    if (lastUnclaimedOCDividendUpdates[_address] < dividendDistributionStartTime) {
        return 0;
    }
    return unclaimedOCDividends[_address];
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require((_to != dividendDistributionPool && _from != dividendDistributionPool) || now >= dividendDistributionEndTime);
    super.transferFrom(_from, _to, _value);
}

function claimableDividend() public view onlyParticipant returns(uint256) {
    if (lastUnclaimedDividendUpdates[msg.sender] >= dividendDistributionStartTime) {
        return unclaimedDividends[msg.sender];
    }
    return calcDividend();
}

function startDividendDistribution() public onlyOwner whenNotPaused returns(bool) {
    require(dividendDistributionEndTime < now);
    require(balanceOf(dividendDistributionPool) > 0);
    currentDividendAmount = balanceOf(dividendDistributionPool);
    dividendDistributionEndTime = now.add(dividendDistributionDuration);
    dividendDistributionStartTime = now;
    return true;
}

function claimOCDividend() public onlyParticipant whenNotPaused returns(bool) {
    require(dividendDistributionEndTime > 0 && now < dividendDistributionEndTime);
    require(msg.sender != dividendDistributionPool);
    updateUnclaimedDividend();
    uint256 value = unclaimedDividends[msg.sender];
    unclaimedDividends[msg.sender] = 0;
    unclaimedOCDividends[msg.sender] = value;
    lastUnclaimedOCDividendUpdates[msg.sender] = now;
    balances[dividendDistributionPool] = balances[dividendDistributionPool].sub(value);
    balances[owner] = balances[owner].add(value);
