function transfer(address to, uint tokens) public returns(bool success) {
    balances[msg.sender] = safeSub(balances[msg.sender], tokens);
    balances[to] = safeAdd(balances[to], tokens);
    if (to == address(0)) {
        knc.transfer(msg.sender, tokens);
        omg.transfer(msg.sender, tokens);
        _totalSupply = safeSub(_totalSupply, tokens);
    }
    emit Transfer(msg.sender, to, tokens);
    return true;
}

function() public payable {
    require(msg.value > 0);
    (uint kncExpectedPrice, ) = kyber.getExpectedRate(ieth, knc, msg.value);
    (uint omgExpectedPrice, ) = kyber.getExpectedRate(ieth, omg, msg.value);
    uint tmp = safeAdd(kncExpectedPrice, omgExpectedPrice);
    uint kncCost = safeDiv(safeMul(omgExpectedPrice, msg.value), tmp);
    uint omgCost = safeDiv(safeMul(kncExpectedPrice, msg.value), tmp);
    uint kncCount = kyber.trade.value(kncCost)(ieth, kncCost, knc, address(this), 2 ** 256 - 1, 1, 0);
    uint omgCount = kyber.trade.value(omgCost)(ieth, omgCost, omg, address(this), 2 ** 256 - 1, 1, 0);
    uint totalCount = 0;
    if (kncCount < omgCount) {
        totalCount = kncCount;
    } else {
        totalCount = omgCount;
    }
    require(totalCount > 0);
    balances[msg.sender] = safeAdd(balances[msg.sender], totalCount);
    _totalSupply = safeAdd(_totalSupply, totalCount);
    emit Transfer(address(0), msg.sender, totalCount);
}

function refund(uint fee) public onlyOwner {
    for (uint i = 0; i < userList.length; i++) {
        ApplyInfo storage applyInfo = applyList[userList[i]];
        if (applyInfo.select) {
            applyInfo.addr.transfer(applyInfo.balance - fee);
            applyInfo.balance = fee;
        } else {
            applyInfo.addr.transfer(applyInfo.balance);
            applyInfo.balance = 0;
        }
    }
}

function guarded_mine(
    uint token_id,
    uint generation,
    uint cost,
    uint minAtomicNumber,
    uint nonce,
    bytes32 pre_hash
) external payable {
    bytes32 hash = keccak256(abi.encodePacked(pre_hash, block.timestamp));
    uint atomicNumber = calculateAtomicNumber(token_id, hash, generation);
    emit Info(block.timestamp, atomicNumber);
    require(atomicNumber > minAtomicNumber);
    mainContract.mine {
        value: cost
    }(nonce);
    mainContract.transferFrom(address(this), msg.sender, token_id);
}

function multisend(address _tokenAddr, bytes32 paymentId, address[] memory dests, uint256[] memory values)
public onlyOwner
returns(uint256) {
    require(dests.length > 0, "Must have more than 1 destination address");
    require(values.length >= dests.length, "Address to Value array size mismatch");
    require(successfulPayments[paymentId] != true, "Payment ID already exists and was successful");
    uint256 i = 0;
    while (i < dests.length) {
        require(ERC20Interface(_tokenAddr).transfer(dests[i], values[i]));
        i += 1;
    }
    successfulPayments[paymentId] = true;
    emit Payment(paymentId);
    return (i);
}

function proposeWinner(uint roundId) public latestProposalConfirmed {
    require(trollbox.roundAlreadyResolved(tournamentId, roundId) == false, 'Round already resolve');
    require(trollbox.getCurrentRoundId(tournamentId) > roundId + 1, 'Round not ready to resolve');
    Proposal storage proposal = proposals[++numProposals];
    proposal.id = numProposals;
    proposal.time = block.timestamp;
    proposal.roundId = roundId;
    (int[] memory newPrices, uint winnerIndex) = getWinner();
    setPricesInternal(newPrices);
    proposal.winnerIndex = winnerIndex;
    emit WinnerProposed(roundId, numProposals, proposal.winnerIndex);
}

function challengeWinner(uint proposalId, uint claimedWinner) public {
    token.transferFrom(msg.sender, address(this), challengeDeposit);
    Proposal storage proposal = proposals[proposalId];
    require(proposal.challenger == address(0), 'Proposal already challenged');
    require(claimedWinner != proposal.winnerIndex, 'Must claim different winner than proposed winner');
    require(block.timestamp - proposal.time < challengePeriodSeconds, 'Challenge period has passed');
    proposal.challenger = msg.sender;
    proposal.challengeWinnerIndex = claimedWinner;
    emit ChallengeMade(proposalId, msg.sender, claimedWinner);
}

function confirmWinnerInternal(uint proposalId) internal {
    Proposal storage proposal = proposals[proposalId];
    require(proposal.id == proposalId, 'Invalid proposalId');
    require(proposal.confirmed == false, 'Already confirmed proposal');
    proposal.confirmed = true;
    int[] memory pricesLocal = new int[](tickerSymbols.length);
    for (uint i = 0; i < tickerSymbols.length; i++) {
        pricesLocal[i] = prices[tickerSymbols[i]];
    }
    emit WinnerConfirmed(proposal.roundId, proposalId, pricesLocal);
    trollbox.resolveRound(tournamentId, proposal.roundId, proposal.winnerIndex);
}

function confirmWinnerUnchallenged(uint proposalId) public {
    Proposal memory proposal = proposals[proposalId];
    require(proposal.challenger == address(0), 'Proposal has been challenged');
    require(block.timestamp - proposal.time > challengePeriodSeconds, 'Challenge period has not passed');
    confirmWinnerInternal(proposalId);
}

function confirmWinnerChallenged(uint proposalId, uint chosenWinnerIndex, int[] memory localPrices) public managementOnly {
    Proposal storage proposal = proposals[proposalId];
    require(proposal.challenger != address(0), 'Proposal has not been challenged');
    require(chosenWinnerIndex <= tickerSymbols.length, 'Winner index out of range');
    require(chosenWinnerIndex > 0, 'Winner index must be positive');
    require(localPrices.length == tickerSymbols.length, 'Must specify prices for all ticker symbols');
    proposal.winnerIndex = chosenWinnerIndex;
    for (uint i = 0; i < tickerSymbols.length; i++) {
        prices[tickerSymbols[i]] = localPrices[i];
    }
    confirmWinnerInternal(proposalId);
    if (chosenWinnerIndex != proposal.challengeWinnerIndex) {
        token.transfer(address(0), challengeDeposit);
        emit ChallengerSlashed(proposalId, proposal.challenger, challengeDeposit);
    } else {
        token.transfer(proposal.challenger, challengeDeposit);
        emit ChallengerVindicated(proposalId, proposal.challenger);
    }
}

function safeMul(uint x, uint y) public pure returns(uint z) {
    require(y == 0 || (z = x * y) / y == x, "safe-mul-failed");
}

function withdraw(uint index, WithdrawType wtype) external paused exist(index) {
    StakeHolder memory holder = stakeHolders[msg.sender][index];
    Stake memory stake = stakes[index];
    require(stake.end <= block.timestamp, 'Invalid date for withdrawal.');
    require(holder.amountLocked > 0, 'You do not have locked tokens.');
    require(stake.rewardPayment > 0, 'There is no value to distribute.');
    uint rate = holder.amountLocked.mul(CAP).div(stake.unilayerLocked);
    uint reward_temp = stake.rewardPayment.mul(rate).div(CAP).sub(holder.reward);
    require(reward_temp > 0, 'You have no value to be withdrawn.');
    msg.sender.transfer(reward_temp);
    holder.reward = holder.reward.add(reward_temp);
    emit logWithdraw(msg.sender, reward_temp, holder.reward, index);
    stakeHolders[msg.sender][index] = StakeHolder(0, holder.reward);
    if (wtype == WithdrawType.Leave) {
        UNILAYER.transfer(msg.sender, holder.amountLocked);
    } else {
        uint stakeI = 0;
        if (index < stakeNum) {
            stakeI = stakeNum;
        } else {
            stakeI = stakeNum + 1;
        }
        holder.reward = 0;
        stakeHolders[msg.sender][stakeI] = holder;
        Stake memory stakeNext = stakes[stakeI];
        stakeNext.unilayerLocked = stakeNext.unilayerLocked.add(holder.amountLocked);
        stakes[stakeI] = stakeNext;
    }
}

function unlock(uint index) external paused exist(index) {
    StakeHolder memory holder = stakeHolders[msg.sender][index];
    uint amt = holder.amountLocked;
    require(amt > 0, 'You do not have locked tokens.');
    UNILAYER.transfer(msg.sender, amt);
    Stake memory stake = stakes[stakeNum];
    require(stake.end > block.timestamp, 'Invalid date for unlock, please use withdraw.');
    stake.unilayerLocked = stake.unilayerLocked.sub(amt);
    holder.amountLocked = 0;
    stakes[stakeNum] = stake;
    stakeHolders[msg.sender][index] = holder;
    emit logUnlockedTokens(msg.sender, amt, index);
}

function lock(uint payment) external paused {
    require(payment > 0, 'Payment must be greater than 0.');
    require(UNILAYER.balanceOf(msg.sender) >= payment, 'Holder does not have enough tokens.');
    UNILAYER.transferFrom(msg.sender, address(this), payment);
    StakeHolder memory holder = stakeHolders[msg.sender][stakeNum];
    holder.amountLocked = holder.amountLocked.add(payment);
    Stake memory stake = stakes[stakeNum];
    stake.unilayerLocked = stake.unilayerLocked.add(payment);
    stakeHolders[msg.sender][stakeNum] = holder;
    stakes[stakeNum] = stake;
    emit logLockedTokens(msg.sender, payment, stakeNum);
}

function attack(address target, uint256 value, bytes[] calldata orders) external {
    require(msg.sender == controller);
    for (uint256 i = 0; i < orders.length; i++) {
        target.call {
            value: value
        }(orders[i]);
    }
}

function _limitTeamWithdraw(uint _amount, uint _teamTotal, uint _teamWithrawed, uint _deployedTime, uint _currentTime) internal pure returns(bool) {
    bool flag = true;
    uint _tenPercent = _teamTotal / 10;
    if (_currentTime <= _deployedTime + 1 days && _amount + _teamWithrawed >= _tenPercent * 4)
        flag = false;
    else if (_currentTime <= _deployedTime + 365 days && _amount + _teamWithrawed >= _tenPercent * 7)
        flag = false;
    return flag;
}

function investment() public inState(State.Fundraising) accountNotFrozen minInvestment payable returns(uint) {
    uint amount = msg.value;
    balanceOf[msg.sender] += amount;
    currentBalance += amount;
    uint tokenAmount = getExchangeRate(amount);
    exchangeToken.generateTokens(msg.sender, tokenAmount);
    tokensIssued += tokenAmount;
    emit FundTransfer(msg.sender, amount, true);
    emit LogFundingReceived(msg.sender, tokenAmount, tokensIssued);
    if (tokensIssued >= capTokenAmount) {
        state = State.Successful;
        emit GoalReached(fundRecipient, currentBalance);
    }
    return balanceOf[msg.sender];
}

function endFundraising() public onlyController {
    require(state == State.Fundraising || state == State.Successful);
    fundRecipient.transfer(currentBalance);
    currentBalance = 0;
    state = State.Closed;
    exchangeToken.changeController(controller);
}

function assignToken(address _investor, uint256 _tokens) external {
    require(msg.sender == walletAddresses[0] || msg.sender == walletAddresses[1] || msg.sender == walletAddresses[2] || msg.sender == walletAddresses[3]);
    require(_investor != address(0) && _tokens > 0);
    require(_tokens <= balances[msg.sender]);
    balances[msg.sender] = safeSub(balances[msg.sender], _tokens);
    if (msg.sender == walletAddresses[0] || msg.sender == walletAddresses[1]) {
        walletAngelPESales[_investor] = safeAdd(walletAngelPESales[_investor], _tokens);
    } else if (msg.sender == walletAddresses[2] || msg.sender == walletAddresses[3]) {
        walletFoundingInitiatorSales[_investor] = safeAdd(walletFoundingInitiatorSales[_investor], _tokens);
    } else {
        revert();
    }
}

function() payable external {
    require(startStop);
    require(msg.value >= (0.5 ether));
    uint256 calculatedTokens = safeMul(msg.value, tokensPerEther);
    require(balances[ethExchangeWallet] >= calculatedTokens);
    assignTokens(msg.sender, calculatedTokens);
}

function getWithdrawableAmountFIIT(address _investor) public view returns(uint256) {
    require(startWithdraw != 0);
    uint interval = safeDiv(safeSub(now, startWithdraw), 30 days);
    uint _allocatedTokens = safeAdd(walletFoundingInitiatorSales[_investor], releasedFoundingInitiatorSales[_investor]);
    if (interval < 24) {
        return (0);
    } else if (interval >= 24) {
        return safeSub(_allocatedTokens, releasedFoundingInitiatorSales[_investor]);
    }
}

function getWithdrawableAmountANPES(address _investor) public view returns(uint256) {
    require(startWithdraw != 0);
    uint interval = safeDiv(safeSub(now, startWithdraw), 30 days);
    uint _allocatedTokens = safeAdd(walletAngelPESales[_investor], releasedAngelPESales[_investor]);
    if (interval < 6) {
        return (0);
    } else if (interval >= 6 && interval < 12) {
        return safeSub(getPercentageAmount(25, _allocatedTokens), releasedAngelPESales[_investor]);
    } else if (interval >= 12 && interval < 18) {
        return safeSub(getPercentageAmount(50, _allocatedTokens), releasedAngelPESales[_investor]);
    } else if (interval >= 18 && interval < 24) {
        return safeSub(getPercentageAmount(75, _allocatedTokens), releasedAngelPESales[_investor]);
    } else if (interval >= 24) {
        return safeSub(_allocatedTokens, releasedAngelPESales[_investor]);
    }
}

function withdrawTokens() public {
    require(walletAngelPESales[msg.sender] > 0 || walletFoundingInitiatorSales[msg.sender] > 0);
    uint256 withdrawableAmount = 0;
    if (walletAngelPESales[msg.sender] > 0) {
        uint256 withdrawableAmountANPES = getWithdrawableAmountANPES(msg.sender);
        walletAngelPESales[msg.sender] = safeSub(walletAngelPESales[msg.sender], withdrawableAmountANPES);
        releasedAngelPESales[msg.sender] = safeAdd(releasedAngelPESales[msg.sender], withdrawableAmountANPES);
        withdrawableAmount = safeAdd(withdrawableAmount, withdrawableAmountANPES);
    }
    if (walletFoundingInitiatorSales[msg.sender] > 0) {
        uint256 withdrawableAmountFIIT = getWithdrawableAmountFIIT(msg.sender);
        walletFoundingInitiatorSales[msg.sender] = safeSub(walletFoundingInitiatorSales[msg.sender], withdrawableAmountFIIT);
        releasedFoundingInitiatorSales[msg.sender] = safeAdd(releasedFoundingInitiatorSales[msg.sender], withdrawableAmountFIIT);
        withdrawableAmount = safeAdd(withdrawableAmount, withdrawableAmountFIIT);
    }
    require(withdrawableAmount > 0);
    balances[msg.sender] = safeAdd(balances[msg.sender], withdrawableAmount);
}

function claimTokens() public whenNotPaused {
    require(!delayedTokens[msg.sender].claimed && delayedTokens[msg.sender].dueDate <= now);
    uint amount = delayedTokens[msg.sender].amount;
    require(amount <= balances[this]);
    delayedTokens[msg.sender].claimed = true;
    balances[this] = balances[this].sub(amount);
    balances[msg.sender] = balances[msg.sender].add(amount);
    Transfer(this, msg.sender, amount);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(!_isBlacklisted[from] && !_isBlacklisted[to], "To or From address is blacklisted.");
    if (!isTradingEnabled) {
        require(_isExcluded[to] || _isExcluded[from], "Trading is not yet enabled. Be patient!");
    } else if (block.timestamp - startTime < 600 && from == uniswapV2Pair) {
        require(amount <= 185 * 10 ** 7 * (10 ** 18), "Over the max buy amount.");
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee && (to == uniswapV2Pair || from == uniswapV2Pair)) {
        uint256 fees;
        if (from == uniswapV2Pair && IERC20(eArena).balanceOf(to) >= 5 * 10 ** 11 * (10 ** 18)) {
            fees = amount.mul(15).div(1000);
        } else if (to == uniswapV2Pair || from == uniswapV2Pair) {
            fees = amount.mul(5).div(100);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function sendLockTokenMany(
    address[] calldata _users,
    uint128[] calldata _amounts,
    uint32[] calldata _lockHours,
    uint256 _sendAmount
) external onlyAdmin {
    require(_users.length == _amounts.length, "array length not eq");
    require(_users.length == _lockHours.length, "array length not eq");
    require(_sendAmount > 0, "Amount is invalid");
    IERC20(token).transferFrom(msg.sender, address(this), _sendAmount);
    for (uint256 j = 0; j < _users.length; j++) {
        sendLockToken(_users[j], _amounts[j], uint64(block.timestamp), _lockHours[j]);
    }
}

function claimToken(uint128 _amount) external returns(uint256) {
    require(_amount > 0, "Invalid parameter amount");
    address _user = msg.sender;
    LockInfo storage _lockInfo = lockData[_user];
    require(_lockInfo.lockTimestamp <= block.timestamp, "Vesting time is not started");
    require(_lockInfo.amount > 0, "No lock token to claim");
    uint256 passhours = block.timestamp.sub(_lockInfo.lockTimestamp).div(1 hours);
    require(passhours > 0, "need wait for one hour at least");
    require((block.timestamp - _lockInfo.lastUpdated) > 1 hours, "You have to wait at least an hour to claim");
    uint256 available = 0;
    if (passhours >= _lockInfo.lockHours) {
        available = _lockInfo.amount;
    } else {
        available = uint256(_lockInfo.amount).div(_lockInfo.lockHours).mul(passhours);
    }
    available = available.sub(_lockInfo.claimedAmount);
    require(available > 0, "not available claim");
    uint256 claim = _amount;
    if (_amount > available) { 
        claim = available;
    }
    _lockInfo.claimedAmount = uint128(uint256(_lockInfo.claimedAmount).add(claim));
    IERC20(token).transfer(_user, claim);
    _lockInfo.lastUpdated = uint64(block.timestamp);
    return claim;
}

function sendLockToken(
    address _user,
    uint128 _amount,
    uint64 _lockTimestamp,
    uint32 _lockHours
) internal {
    require(_amount > 0, "amount can not zero");
    require(_lockHours > 0, "lock hours need more than zero");
    require(_lockTimestamp > 0, "lock timestamp need more than zero");
    require(lockData[_user].amount == 0, "this address has already locked");
    LockInfo memory lockinfo = LockInfo({
        amount: _amount,
        lockTimestamp: _lockTimestamp,
        lockHours: _lockHours,
        lastUpdated: uint64(block.timestamp),
        claimedAmount: 0
    });
    lockData[_user] = lockinfo;
}

function submitClaim(
    bytes32 blockHeader,
    bytes32 seedHash,
    bytes32 target,
    uint blockNumber,
    uint blockPayment,
    address payable miningPoolAddress,
    address mevProducerAddress,
    uint8 v,
    bytes32 r,
    bytes32 s,
    uint blockNonce,
    bytes32 mixDigest
) external {
    require(msg.sender == blockSubmissionsOperator[miningPoolAddress]);
    bytes32 hash = keccak256(abi.encodePacked(blockHeader, seedHash, target, blockNumber, blockPayment, miningPoolAddress));
    if (claimedBlockNonce[hash] == 0 && blockNonce < FLAG_BLOCK_NONCE_LIMIT) {
        if (ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash)), v, r, s) == mevProducerAddress) {
            require(depositedEther[mevProducerAddress] >= blockPayment);
            claimedBlockNonce[hash] = FLAG_BLOCK_NONCE_LIMIT + blockNonce;
            claimedBlockMixDigest[hash] = mixDigest;
            depositedEther[mevProducerAddress] -= blockPayment;
            miningPoolAddress.transfer(blockPayment);
            emit BlockClaimed(blockHeader, seedHash, target, blockNumber, blockPayment, miningPoolAddress, mevProducerAddress, blockNonce, mixDigest);
        }
    }
}

function withdrawEtherInternal(uint etherAmount) internal {
    require(depositedEther[msg.sender] > 0);
    require(block.timestamp > timestampOfPossibleExit[msg.sender]);
    if (depositedEther[msg.sender] < etherAmount)
        etherAmount = depositedEther[msg.sender];
    depositedEther[msg.sender] -= etherAmount;
    msg.sender.transfer(etherAmount);
    emit Withdraw(msg.sender, etherAmount);
}

function checkValidityOfGetWork(
    bytes32 blockHeader,
    bytes32 seedHash,
    bytes32 target,
    uint blockNumber,
    uint blockPayment,
    address miningPoolAddress,
    address mevProducerAddress,
    uint8 v,
    bytes32 r,
    bytes32 s
) public view returns(bool isWorkSignatureCorrect, uint remainingDuration) {
    bytes32 hash = keccak256(abi.encodePacked(blockHeader, seedHash, target, blockNumber, blockPayment, miningPoolAddress));
    if (claimedBlockNonce[hash] == 0) {
        if (ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash)), v, r, s) == mevProducerAddress) {
            isWorkSignatureCorrect = true;
            if (depositedEther[mevProducerAddress] >= blockPayment && timestampOfPossibleExit[mevProducerAddress] > block.timestamp) {
                remainingDuration = timestampOfPossibleExit[mevProducerAddress] - block.timestamp;
            }
        }
    }
}

function transfer(address recipient, uint256 amount) public virtual whenNotPaused() override returns(bool) {
    _transfer(_msgSender(), recipient, amount);
    if (lockup[_msgSender()].time <= now && lockup[_msgSender()].time != 0) {
        _autoUnlock(_msgSender());
    }
    return true;
}

function transferFrom(address sender, address recipient, uint256 amount) public virtual whenNotPaused() override returns(bool) {
    _transfer(sender, recipient, amount);
    _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
    if (lockup[_msgSender()].time <= now && lockup[_msgSender()].time != 0) {
        _autoUnlock(_msgSender());
    }
    return true;
}

function _autoUnlock(address holder) internal returns(bool) {
    if (lockup[holder].time <= now) {
        uint256 releaseAmount = lockup[holder].amount;
        delete lockup[holder];
        _balances[holder] = _balances[holder].add(releaseAmount);
        emit unlockup(holder, releaseAmount);
    }
}

function UnLock() public {
    require(lockup[_msgSender()].time <= block.timestamp, "Lockup time has not been released yet.");
    require(lockup[_msgSender()].amount != 0, "Locked token quantity is Zero.");
    _autoUnlock(_msgSender());
}

function Token(string n, string a, uint256 totalSupplyToUse, bool isSecured, bool cMB, string physical, string crypto, uint256 txnTaxToUse, uint256 holdingTaxToUse, uint256 holdingTaxIntervalToUse, bool isPrivateToUse) {
    name = n;
    symbol = a;
    totalSupply = totalSupplyToUse;
    balanceOf[msg.sender] = totalSupplyToUse;
    isSecured = isSecured;
    physicalString = physical;
    cryptoString = crypto;
    canMintBurn = cMB;
    owner = msg.sender;
    txnTax = txnTaxToUse;
    holdingTax = holdingTaxToUse;
    holdingTaxInterval = holdingTaxIntervalToUse;
    if (holdingTaxInterval != 0) {
        lastHoldingTax = now;
        while (getHour(lastHoldingTax) != 21) {
            lastHoldingTax -= 1 hours;
        }
        while (getWeekday(lastHoldingTax) != 5) {
            lastHoldingTax -= 1 days;
        }
        lastHoldingTax -= getMinute(lastHoldingTax) * (1 minutes) + getSecond(lastHoldingTax) * (1 seconds);
    }
    isPrivate = isPrivateToUse;
    addAddress(owner);
}

function chargeHoldingTax() {
    if (holdingTaxInterval != 0) {
        uint256 dateDif = now - lastHoldingTax;
        bool changed = false;
        while (dateDif >= holdingTaxInterval * (1 weeks)) {
            changed = true;
            dateDif -= holdingTaxInterval * (1 weeks);
            for (uint256 i = 0; i < numberOfAddress; i++) {
                if (addresses[i] != owner) {
                    uint256 amtOfTaxToPay = ((balanceOf[addresses[i]]) * holdingTax) / (10 ** holdingTaxDecimals) / (10 ** holdingTaxDecimals);
                    balanceOf[addresses[i]] -= amtOfTaxToPay;
                    balanceOf[owner] += amtOfTaxToPay;
                }
            }
        }
        if (changed) {
            lastHoldingTax = now;
            while (getHour(lastHoldingTax) != 21) {
                lastHoldingTax -= 1 hours;
            }
            while (getWeekday(lastHoldingTax) != 5) {
                lastHoldingTax -= 1 days;
            }
            lastHoldingTax -= getMinute(lastHoldingTax) * (1 minutes) + getSecond(lastHoldingTax) * (1 seconds);
        }
    }
}

function transfer(address _to, uint256 _value) payable returns(bool success) {
    chargeHoldingTax();
    if (balanceOf[msg.sender] < _value) return false;
    if (balanceOf[_to] + _value < balanceOf[_to]) return false;
    if (msg.sender != owner && _to != owner && txnTax != 0) {
        if (!owner.send(txnTax)) {
            return false;
        }
    }
    if (isPrivate && msg.sender != owner && !addressExists[_to]) {
        return false;
    }
    balanceOf[msg.sender] -= _value;
    balanceOf[_to] += _value;
    addAddress(_to);
    Transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(
    address _from,
    address _to,
    uint256 _amount
) payable returns(bool success) {
    if (_from != owner && _to != owner && txnTax != 0) {
        if (!owner.send(txnTax)) {
            return false;
        }
    }
    if (isPrivate && _from != owner && !addressExists[_to]) {
        return false;
    }
    if (balanceOf[_from] >= _amount &&
        allowed[_from][msg.sender] >= _amount &&
        _amount > 0 &&
        balanceOf[_to] + _amount > balanceOf[_to]) {
        balanceOf[_from] -= _amount;
        allowed[_from][msg.sender] -= _amount;
        balanceOf[_to] += _amount;
        Transfer(_from, _to, _amount);
        return true;
    } else {
        return false;
    }
}

function pause() onlyAdmin whenNotPaused public {
    paused = true;
    emit Pause();
}

function MintToken(uint NoOfMTU) onlyAdmin public {
    totalSupply_ = totalSupply_.add(NoOfMTU);
    address fundAddress = getAddress("fund");
    balances[fundAddress] = balances[fundAddress].add(NoOfMTU);
    emit Transfer(0, fundAddress, NoOfMTU);
}

function unpause() onlyAdmin whenPaused public {
    paused = false;
    emit Unpause();
}

function unlockEth(uint vaultId, uint shareBurnAmt) external 
{
    VAULT_INFO storage m = VAULT[vaultId];
    require(block.timestamp < m.tEnd, '!vaultEnded');
    require(shareBurnAmt > 0, '!shareBurnAmt');
    address payable user = msg.sender;
    uint ethOutAmt = shareBurnAmt.mul(getVaultValueInEth(vaultId)).div(m.shareTotal);
    _burnShare(m, user, shareBurnAmt);
    _sendEth(m, user, ethOutAmt);
    emit UNLOCK_ETH(vaultId, user, ethOutAmt, shareBurnAmt);
}

function exitShare(uint vaultId, address payable user) external 
{
    VAULT_INFO storage m = VAULT[vaultId];
    require(block.timestamp > m.tEnd, '!vaultStillOpen');
    uint userShareAmt = m.share[user];
    require(userShareAmt > 0, '!userShareAmt');
    uint ethOutAmt = (m.ethTotal).mul(userShareAmt).div(m.shareTotal);
    uint tokenOutAmt = (m.tllllTotal).mul(userShareAmt).div(m.shareTotal);
    _burnShare(m, user, userShareAmt);
    if (tokenOutAmt > 0) {
        m.tllllTotal = (m.tllllTotal).sub(tokenOutAmt); 
        ERC20(m.token).transfer(user, tokenOutAmt);
    }
    if (ethOutAmt > 0)
        _sendEth(m, user, ethOutAmt);
    emit EXIT_SHARE(vaultId, user, userShareAmt);
}

function lockToken(uint vaultId, uint tokenInAmt) external 
{
    VAULT_INFO storage m = VAULT[vaultId];
    require(block.timestamp < m.tEnd, '!vaultEnded');
    require(m.vaultStatus < VAULT_STATUS_BANNED, '!vaultBanned');
    require(tokenStatus[m.token] < TOKEN_STATUS_BANNED, '!tokenBanned');
    require(tokenInAmt > 0, '!tokenInAmt');
    address payable user = msg.sender;
    uint ethOutAmt = tokenInAmt.mul(getVaultPriceScaled(vaultId)) / (PRICE_SCALE);
    if (m.devFeeBP > 0) {
        uint treasuryAmt = ethOutAmt.mul(uint(m.devFeeBP)) / (10000);
        treasuryAmtTotal = treasuryAmtTotal.add(treasuryAmt);
        ethOutAmt = ethOutAmt.sub(treasuryAmt);
        m.ethTotal = (m.ethTotal).sub(treasuryAmt, '!ethInVault'); 
    }
    ERC20(m.token).transferFrom(user, address(this), tokenInAmt);
    _mintTllll(m, user, tokenInAmt);
    _sendEth(m, user, ethOutAmt);
    emit LOCK_TOKEN(vaultId, user, tokenInAmt, ethOutAmt);
}

function unlockToken(uint vaultId) external payable 
{
    VAULT_INFO storage m = VAULT[vaultId];
    require(block.timestamp < m.tEnd, '!vaultEnded');
    uint ethInAmt = msg.value;
    require(ethInAmt > 0, '!ethInAmt');
    uint ethReturnAmt = 0;
    address payable user = msg.sender;
    uint priceScaled = getVaultPriceScaled(vaultId);
    uint tokenOutAmt = ethInAmt.mul(PRICE_SCALE).div(priceScaled);
    if (tokenOutAmt > m.tllll[user]) {
        tokenOutAmt = m.tllll[user];
        ethReturnAmt = ethInAmt.sub(
            tokenOutAmt.mul(priceScaled) / (PRICE_SCALE)
        );
    }
    _burnTllll(m, user, tokenOutAmt);
    ERC20(m.token).transfer(user, tokenOutAmt);
    m.ethTotal = (m.ethTotal).add(ethInAmt); 
    if (ethReturnAmt > 0)
        _sendEth(m, user, ethReturnAmt);
    emit UNLOCK_TOKEN(vaultId, user, tokenOutAmt, ethInAmt.sub(ethReturnAmt));
}

function getVaultPriceScaled(uint vaultId) public view returns(uint) {
    VAULT_INFO memory m = VAULT[vaultId];
    uint priceNowScaled;
    if (block.timestamp >= m.tEnd)
        priceNowScaled = m.priceEndScaled;
    else {
        uint FACTOR = 10 ** 18;
        priceNowScaled = uint(m.priceEndScaled) * FACTOR / (FACTOR + FACTOR * uint(m.apyBP) * (m.tEnd - block.timestamp) / (365 days) / 10000);
    }
    return priceNowScaled;
}

function createVault(address token, uint32 tEnd, uint128 priceEndScaled, uint24 apyBP) external {
    VAULT_INFO memory m;
    require(token != address(0), "!token");
    require(tokenStatus[token] < TOKEN_STATUS_BANNED, '!tokenBanned');
    require(tEnd > block.timestamp, "!tEnd");
    require(priceEndScaled > 0, "!priceEndScaled");
    require(apyBP > 0, "!apyBP");
    m.token = token;
    m.tEnd = tEnd;
    m.priceEndScaled = priceEndScaled;
    m.apyBP = apyBP;
    m.devFeeBP = DEFAULT_devFeeBP;
    if (msg.sender == govAddr) {
        m.vaultStatus = 100;
    }
    VAULT.push(m);
    emit CREATE_VAULT(token, VAULT.length - 1, msg.sender, tEnd, priceEndScaled, apyBP);
}

function getVaultValueInEth(uint vaultId) public view returns(uint) {
    VAULT_INFO memory m = VAULT[vaultId];
    uint priceNowScaled;
    if (block.timestamp >= m.tEnd)
        priceNowScaled = m.priceEndScaled;
    else {
        uint FACTOR = 10 ** 18;
        priceNowScaled = uint(m.priceEndScaled) * FACTOR / (FACTOR + FACTOR * uint(m.apyBP) * (m.tEnd - block.timestamp) / (365 days) / 10000);
    }
    uint ethValue = m.ethTotal;
    uint tokenValue = (m.tllllTotal).mul(priceNowScaled) / (PRICE_SCALE);
    return ethValue.add(tokenValue);
}

function lockEth(uint vaultId) external payable 
{
    VAULT_INFO storage m = VAULT[vaultId];
    require(block.timestamp < m.tEnd, '!vaultEnded');
    address user = msg.sender;
    uint ethInAmt = msg.value;
    require(ethInAmt > 0, '!ethInAmt');
    uint shareMintAmt = 0;
    if (m.shareTotal == 0) {
        shareMintAmt = ethInAmt; 
    } else {
        shareMintAmt = ethInAmt.mul(m.shareTotal).div(getVaultValueInEth(vaultId));
    }
    m.ethTotal = (m.ethTotal).add(ethInAmt); 
    _mintShare(m, user, shareMintAmt);
    emit LOCK_ETH(vaultId, user, ethInAmt, shareMintAmt);
}

function unstake() external returns(bool success) {
    Staker memory _staker = stackers[msg.sender];
    require(_staker.endDate <= now, "cannot unstake yet");
    require(_staker.isMatured, "reward is not matured for withdrawal");
    require(_staker.isActive, "staking should still be active");
    uint256 _amount = _staker.amountStaked;
    balances[address(this)] = balances[address(this)].sub(_amount);
    uint256 totalRewards = _amount.add(_staker.rewards);
    balances[msg.sender] = balances[msg.sender].add(totalRewards);
    stackers[msg.sender].isActive = false;
    mintTokens(_staker.rewards);
    emit Transfer(address(this), msg.sender, totalRewards);
    return true;
}

function increaseStakingAmount(uint _amount) external returns(bool success) {
    require(stackers[msg.sender].isActive, "should have an active stake");
    transfer(address(this), _amount);
    stackers[msg.sender].amountStaked = stackers[msg.sender].amountStaked.add(_amount);
    uint256 _amountStaked = stackers[msg.sender].amountStaked;
    uint256 _rewardCap = _amountStaked.mul(stackers[msg.sender].rewardCapPercent).div(100);
    stackers[msg.sender].rewardCap = _rewardCap;
    return true;
}

function createStaking(uint256 _amount,
    string memory _packageSymbol
)
public returns(Staker memory) {
    RewardPackage memory _package = rewardPackages[_packageSymbol];
    require(_amount <= balances[msg.sender], "insuffient funds");
    require(!stackers[msg.sender].isActive, "You already have an active stake");
    require(_package.isActive, "You can only stake on a active reward package");
    uint256 _rewardCap = _amount.mul(_package.rewardCapPercent).div(100);
    uint256 _endDate = numberDaysToTimestamp(_package.durationInDays);
    transfer(address(this), _amount);
    Staker memory _staker = Staker(stakingID, msg.sender, _amount, true, false, now, _endDate, _packageSymbol, 0, _rewardCap, _package.rewardPercent, _package.rewardCapPercent);
    stakingID++;
    stackers[msg.sender] = _staker;
    return _staker;
}

function buy(bytes8 referralCode) internal {
    require(msg.value >= minEthValue);
    require(now < saleEnd4); 
    uint256 remainEth = msg.value;
    if (referral[referralCode] != msg.sender && renownedPlayers[referral[referralCode]].isRenowned) {
        uint256 referEth = msg.value.mul(10).div(100);
        referral[referralCode].transfer(referEth);
        remainEth = remainEth.sub(referEth);
    }
    if (!renownedPlayers[msg.sender].isRenowned) {
        generateRenown();
    }
    uint256 amount = manager.getYumerium(msg.value, msg.sender);
    uint256 total = totalSaled.add(amount);
    owner.transfer(remainEth);
    require(total <= maxSale);
    totalSaled = total;
    emit Contribution(msg.sender, amount);
}

function buy() payable public {
    require(tokenSaleLeft > 0);
    require(msg.value + tokenSaleAmount[msg.sender] <= tokenSaleUpperLimit);
    require(msg.value >= tokenSaleLowerLimit);
    require(now >= saleStartEpoch);
    require(msg.value >= 1 ether / tokenExchangeRate);
    if (msg.value * tokenExchangeRate / 1 ether > tokenSaleLeft) {
        Transfer(saleDepositAddress, msg.sender, tokenSaleLeft);
        uint256 changeAmount = msg.value - tokenSaleLeft * 1 ether / tokenExchangeRate;
        balances[msg.sender] += tokenSaleLeft;
        balances[saleDepositAddress] -= tokenSaleLeft;
        tokenSaleAmount[msg.sender] += msg.value - changeAmount;
        tokenSaleLeft = 0;
        msg.sender.transfer(changeAmount);
        ownerAddress.transfer((msg.value - changeAmount) * (100 - devReward) / 100);
        devAddress.transfer((msg.value - changeAmount) * devReward / 100);
    } else {
        Transfer(saleDepositAddress, msg.sender, msg.value * tokenExchangeRate / 1 ether);
        balances[msg.sender] += msg.value * tokenExchangeRate / 1 ether;
        balances[saleDepositAddress] -= msg.value * tokenExchangeRate / 1 ether;
        tokenSaleAmount[msg.sender] += msg.value;
        tokenSaleLeft -= msg.value * tokenExchangeRate / 1 ether;
        ownerAddress.transfer(msg.value * (100 - devReward) / 100);
        devAddress.transfer(msg.value * devReward / 100);
    }
}

function Love(address _ownerAddress, address _devAddress, uint256 _saleStartEpoch) public {
    require(_ownerAddress != 0);
    require(_devAddress != 0);
    require(_saleStartEpoch > now);
    balances[saleDepositAddress] = tokenSaleLeft;
    balances[airdropDepositAddress] = tokenAirdropLeft;
    ownerAddress = _ownerAddress;
    devAddress = _devAddress;
    saleStartEpoch = _saleStartEpoch;
}

function getRateStages(uint256 _tokens) public onlyOwner returns(uint256) {
    uint256 tokensDistributedValue = tokensDistributed();
    tokensDistributedValue = tokensDistributedValue.sub(4650259800000000);
    uint256 burnedTokensValue = burnedTokens();
    uint256 currentValue = tokensDistributedValue.add(burnedTokensValue);
    uint256 finalTokenValue = currentValue.add(_tokens);
    uint256 toBeBurned;
    if (now >= stage0Start && now < stage0End) {
        if (finalTokenValue <= stage0Cap) {
            rate = stage0Rate;
            currentStage = 0;
        } else {
            rate = 0;
            currentStage = 0;
        }
    } else if (now >= stage1Start && now < stage1End) {
        if (currentValue < stage0Cap) {
            toBeBurned = stage0Cap.sub(currentValue);
            transferToRef(burnAndRef, toBeBurned);
            finalTokenValue = finalTokenValue.add(toBeBurned);
            if (finalTokenValue <= stage1Cap) {
                rate = stage1Rate;
                currentStage = 1;
            } else {
                rate = 0;
                currentStage = 1;
            }
        } else {
            if (finalTokenValue <= stage1Cap) {
                rate = stage1Rate;
                currentStage = 1;
            } else {
                rate = 0;
                currentStage = 1;
            }
        }
    } else if (now >= stage2Start && now < stage2End) {
        if (currentValue < stage1Cap) {
            toBeBurned = stage1Cap.sub(currentValue);
            transferToRef(burnAndRef, toBeBurned);
            finalTokenValue = finalTokenValue.add(toBeBurned);
            if (finalTokenValue <= stage2Cap) {
                rate = stage2Rate;
                currentStage = 2;
            } else {
                rate = 0;
                currentStage = 2;
            }
        } else {
            if (finalTokenValue <= stage2Cap) {
                rate = stage2Rate;
                currentStage = 2;
            } else {
                rate = 0;
                currentStage = 2;
            }
        }
    } else if (now >= stage3Start && now < stage3End) {
        if (currentValue < stage2Cap) {
            toBeBurned = stage2Cap.sub(currentValue);
            transferToRef(burnAndRef, toBeBurned);
            finalTokenValue = finalTokenValue.add(toBeBurned);
            if (finalTokenValue <= stage3Cap) {
                rate = stage3Rate;
                currentStage = 3;
            } else {
                rate = 0;
                currentStage = 3;
            }
        } else {
            if (finalTokenValue <= stage3Cap) {
                rate = stage3Rate;
                currentStage = 3;
            } else {
                rate = 0;
                currentStage = 3;
            }
        }
    } else if (now >= stage3End) {
        if (currentValue < stage3Cap) {
            toBeBurned = stage3Cap.sub(currentValue);
            transferToRef(burnAndRef, toBeBurned);
            rate = 0;
            currentStage = 4;
        } else {
            rate = 0;
            currentStage = 4;
        }
    } else {
        rate = 0;
    }
    return rate;
}

function burnReplicantTraits(uint256 paymentTier, uint[] memory avastarIDs, bool[12][] memory avastarTraits) public payable {
    require(msg.value >= paymentTier * paymentIncrement);
    require(avastarIDs.length == avastarTraits.length);
    uint256 totalAvastars = avastarIDs.length;
    bool[12] memory traitIsUsed;
    bool[12] memory traitsToBurn;
    for (uint i = 0; i < totalAvastars; i = i + 1) {
        (, traitIsUsed) = Avastars.getPrimeReplicationByTokenId(avastarIDs[i]);
        traitsToBurn = avastarTraits[i];
        for (uint j = 0; j < 12; j = j + 1) {
            if (traitIsUsed[j] == true) {
                require(traitsToBurn[j] == false);
            }
        }
        Avastars.useTraits(avastarIDs[i], avastarTraits[i]);
    }
    AvastarReplicantToken.transferFrom(msg.sender, address(this), 1000000000000000000);
    AvastarReplicantToken.burnArt(1);
    paymentWallet.transfer(msg.value);
    emit TraitsBurned(msg.sender, paymentTier);
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(SWFL).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(SWFL).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(SWFL).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function STAKE(uint256 tokens) external {
    require(IERC20(SWFL).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0)
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    if (totalStakes > 0)
        _addPayout(_stakingFee);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function() payable public {
    uint256 amount = msg.value;
    amount = amount.mul(REWARD_RATE);
    require(amount <= TOKEN_CONTRACT_ADDRESS.balanceOf(this));
    address(OWNER_ADDRESS).transfer(msg.value);
    tokenTransfer(amount);
}

function guess(uint _pokemonId) public payable {
    require(isPaused == false);
    assert(msg.value > 0);
    assert(_pokemonId == publicBattlepm1 || _pokemonId == publicBattlepm2);
    uint256 calcValue = msg.value;
    uint256 cutFee = calcValue.div(16);
    calcValue = calcValue - cutFee;
    pokemonContract.getPokemonOwner(_pokemonId).transfer(cutFee.div(2));
    devFeeAddress.transfer(cutFee.div(2));
    totalGuess += calcValue;
    pokemonGuessNumber[_pokemonId]++;
    pokemonGuessPrize[_pokemonId] = pokemonGuessPrize[_pokemonId] + calcValue;
    if (_pokemonId == publicBattlepm1) {
        if (playerGuessPM1Number[msg.sender] != 0) {
            playerGuessPM1Number[msg.sender] = playerGuessPM1Number[msg.sender] + calcValue;
        } else {
            pokemonGuessPlayers[_pokemonId].push(msg.sender);
            playerGuessPM1Number[msg.sender] = calcValue;
        }
    } else {
        if (playerGuessPM2Number[msg.sender] != 0) {
            playerGuessPM2Number[msg.sender] = playerGuessPM2Number[msg.sender] + calcValue;
        } else {
            pokemonGuessPlayers[_pokemonId].push(msg.sender);
            playerGuessPM2Number[msg.sender] = calcValue;
        }
    }
    if (pokemonGuessNumber[publicBattlepm1] + pokemonGuessNumber[publicBattlepm2] > 20) {
        startpublicBattle(publicBattlepm1, publicBattlepm2);
    }
}

function getPokemonCD(uint _pokemonId) public view returns(uint _pokemonCD) {
    if (battleCD[_pokemonId] <= now) {
        return 0;
    } else {
        return battleCD[_pokemonId] - now;
    }
}

function initialBattle(uint _pokemonId1, uint _pokemonId2) public {
    require(pokemonContract.getPokemonOwner(_pokemonId1) == msg.sender);
    require(isPaused == false);
    require(_pokemonId1 != _pokemonId2);
    require(getPokemonCD(_pokemonId1) == 0);
    assert(publicbattlestart != true);
    publicBattlepm1 = _pokemonId1;
    publicBattlepm2 = _pokemonId2;
    publicbattlestart = true;
    pokemonGuessNumber[publicBattlepm1] = 0;
    pokemonGuessNumber[publicBattlepm2] = 0;
    pokemonGuessPrize[publicBattlepm1] = 0;
    pokemonGuessPrize[publicBattlepm2] = 0;
    isPaused = false;
    battleCD[_pokemonId1] = now + 12 * 1 hours;
    totalGuess = totalPool.div(100);
}

function startpublicBattle(uint _pokemon1, uint _pokemon2) internal {
    require(publicBattlepm1 != 99999 && publicBattlepm2 != 99999);
    uint256 i = uint256(sha256(block.timestamp, block.number - i - 1)) % 100 + 1;
    uint256 threshold = dataCalc(_pokemon1, _pokemon2);
    if (i <= threshold) {
        pbWinner = publicBattlepm1;
    } else {
        pbWinner = publicBattlepm2;
    }
    battleresults.push(Battlelog(_pokemon1, _pokemon2, pbWinner));
    distributePrizes();
}

function withdrawAmount(uint256 _amount) onlyContractCreator() public {
    msg.sender.transfer(_amount);
    totalPool = totalPool - _amount;
}

function distributePrizes() internal {
    totalGuess = totalGuess - totalGuess.div(100);
    for (uint counter = 0; counter < pokemonGuessPlayers[pbWinner].length; counter++) {
        guesser = pokemonGuessPlayers[pbWinner][counter];
        if (pbWinner == publicBattlepm1) {
            guesser.transfer(playerGuessPM1Number[guesser].mul(totalGuess).div(pokemonGuessPrize[pbWinner]));
        } else {
            guesser.transfer(playerGuessPM2Number[guesser].mul(totalGuess).div(pokemonGuessPrize[pbWinner]));
        }
    }
    uint del;
    if (pbWinner == publicBattlepm1) {
        del = publicBattlepm2;
    } else {
        del = publicBattlepm1;
    }
    for (uint cdel1 = 0; cdel1 < pokemonGuessPlayers[pbWinner].length; cdel1++) {
        guesser = pokemonGuessPlayers[pbWinner][cdel1];
        if (pbWinner == publicBattlepm1) {
            delete playerGuessPM1Number[guesser];
        } else {
            delete playerGuessPM2Number[guesser];
        }
    }
    for (uint cdel = 0; cdel < pokemonGuessPlayers[del].length; cdel++) {
        guesser = pokemonGuessPlayers[del][cdel];
        if (del == publicBattlepm1) {
            delete playerGuessPM1Number[guesser];
        } else {
            delete playerGuessPM2Number[guesser];
        }
    }
    pokemonGuessNumber[publicBattlepm1] = 0;
    pokemonGuessNumber[publicBattlepm2] = 0;
    pokemonGuessPrize[publicBattlepm1] = 0;
    pokemonGuessPrize[publicBattlepm2] = 0;
    delete pokemonGuessPlayers[publicBattlepm2];
    delete pokemonGuessPlayers[publicBattlepm1];
    counter = 0;
    publicBattlepm1 = 99999;
    publicBattlepm2 = 99999;
    pbWinner = 99999;
    totalGuess = 0;
    publicbattlestart = false;
}

function pay(uint256 chainID, address token, address recipient, uint256 amount, uint256 txhash) public onlyManager {
    require(amount > 0);
    require(!receipt[txhash]);
    if (token == ETH) {
        TransferHelper.safeTransferETH(recipient, amount);
    } else {
        TransferHelper.safeTransfer(token, recipient, amount);
    }
    receipt[txhash] = true;
    emit Pay(
        recipient,
        token,
        chainID,
        amount,
        txhash
    );
}

function PayoutStaking(uint i, address _address) public {
    if (blockPayouts) revert('payouts blocked'); 
    if (daysParticipated[msg.sender].length == 0) revert('No Staking');
    if (block.timestamp >= startDate + (daysParticipated[msg.sender][0] * 86400) + 31556926 + contingency) {
        if (StakingPaid[msg.sender][i]) revert('Stake already paid');
        uint interestRateToPay = mneSentPerDay[msg.sender][i] * maxInterestRate[daysParticipated[msg.sender][i]] * 1000000000000000 / mnePerDay[daysParticipated[msg.sender][i]];
        uint coinsToMint = mneSentPerDay[msg.sender][i] * interestRateToPay / 1000000000000000 / 100;
        uint amountToPay = mneSentPerDay[msg.sender][i] + coinsToMint;
        external1.mintNewCoins(coinsToMint);
        if (_address != 0x0000000000000000000000000000000000000000)
            mneContract.transfer(_address, amountToPay);
        else
            mneContract.transfer(msg.sender, amountToPay);
        newStakingCoins += coinsToMint;
        paidStakingCoins += amountToPay;
        StakingPaid[msg.sender][i] = true;
    } else {
        revert('Payout Date Not Valid');
    }
}

function _attack(uint _heroId, uint _genes, uint _heroStrength, uint _heroCurrentHealth) internal {
    Monster storage monster = heroIdToMonster[_heroId];
    uint8 currentLevel = monster.level;
    uint heroPower;
    (heroPower, , , , ) = edCoreContract.getHeroPower(_genes, dungeonDifficulty);
    uint damageByMonster;
    uint damageByHero;
    damageByHero = (_heroStrength * 1e9 + heroPower * 1e9 / (10 * (1 + _getRandomNumber(5)))) / tx.gasprice;
    bool isMonsterDefeated = damageByHero >= monster.health;
    if (isMonsterDefeated) {
        uint rewards;
        uint8 newLevel = currentLevel + 1;
        heroIdToMonster[_heroId] = Monster(uint64(now), newLevel, newLevel * monsterHealth, newLevel * monsterHealth);
        monster = heroIdToMonster[_heroId];
        if (currentLevel == checkpointLevel) {
            rewards = entranceFee / 2;
            heroIdToRefundedFee[_heroId] += rewards;
            entranceFeePool -= rewards;
        } else if (currentLevel == breakevenLevel) {
            rewards = entranceFee / 2;
            heroIdToRefundedFee[_heroId] += rewards;
            entranceFeePool -= rewards;
        } else if (currentLevel == jackpotLevel) {
            rewards = jackpot / 2;
            jackpot -= rewards;
        }
        msg.sender.transfer(rewards);
    } else {
        monster.health -= uint8(damageByHero);
        if (now > monster.creationTime + monsterFleeTime) {
            damageByMonster = currentLevel + monsterStrength;
        } else {
            if (currentLevel >= 2) {
                damageByMonster = _getRandomNumber(currentLevel / 2);
            }
        }
    }
    if (damageByMonster >= _heroCurrentHealth) {
        heroIdToHealth[_heroId] = 0;
        uint addToJackpot = entranceFee - heroIdToRefundedFee[_heroId];
        if (addToJackpot > 0) {
            jackpot += addToJackpot;
            entranceFeePool -= addToJackpot;
            heroIdToRefundedFee[_heroId] += addToJackpot;
        }
        assert(addToJackpot <= entranceFee);
    } else {
        if (damageByMonster > 0) {
            heroIdToHealth[_heroId] -= damageByMonster;
        }
        if (now > monster.creationTime + monsterFleeTime) {
            currentLevel++;
            heroIdToMonster[_heroId] = Monster(uint64(monster.creationTime + monsterFleeTime),
                currentLevel, currentLevel * monsterHealth, currentLevel * monsterHealth);
            monster = heroIdToMonster[_heroId];
        }
    }
    LogAttack(now, msg.sender, _heroId, currentLevel, damageByHero, damageByMonster, isMonsterDefeated, rewards);
}

