    satoshiMood = _satoshiMood;
    name = _name;
}

function endRoundWhenTimeout(RoundLib.Round storage curRound) private isActive {
    if (now >= roundEndTime) {
        uint256 preRoundMax = 0;
        if (curRound.roundNum > 1) {
            RoundLib.Round storage preRound = roundList[roundList.length - 2];
            preRoundMax = preRound.max;
        }
        uint256 last2RoundsRaised = preRoundMax + curRound.raised;
        if (last2RoundsRaised > 0) {
            if (curRound.addressOfMaxInvestment != 0) {
                uint256 amountToLuckyDog = fundPoolSize * 2 / 10;
                coinHolders.add(curRound.addressOfMaxInvestment, amountToLuckyDog);
                poolSub(amountToLuckyDog);
            }
            curRound.pot = curRound.raised * fundPoolSize / last2RoundsRaised;
            if (curRound.roundNum > 1) {
                preRound.pot = preRound.raised * fundPoolSize / last2RoundsRaised;
                poolSub(preRound.pot);
            }
            poolSub(curRound.pot);
        }
        mIsActive = isAutoRestart;
        startNextRound(curRound);
        bigRound++;
    }
}

function roundIn(uint256 amt, string code) private isActive {
    require(coinHolders.getNum(msg.sender) >= amt, "not enough coin");
    RoundLib.Round storage curRound = roundList[roundList.length - 1];
    if (now >= roundEndTime) {
        endRoundWhenTimeout(curRound);
        return;
    }
    (bool isFinished, uint256 amountUsed) = curRound.add(msg.sender, amt);
    totalAmountInvested = totalAmountInvested.add(amountUsed);
    require(amountUsed > 0, 'amountUsed must greater than 0');
    emit RoundIn(msg.sender, amountUsed, curRound.raised, curRound.roundNum, bigRound, code);
    coinHolders.addRelatedRoundId(msg.sender, curRound.roundId);
    coinHolders.sub(msg.sender, amountUsed);
    uint256 amountToDealer = dealers.addAmount(code, amountUsed);
    uint256 amountToOwner = (amountUsed * rate / 10000).sub(amountToDealer);
    coinHolders.add(owner, amountToOwner);
    coinHolders.add(dealers.query(code).addr, amountToDealer);
    poolAdd(amountUsed.sub(amountToDealer).sub(amountToOwner));
    if (isFinished) {
        if (curRound.roundNum > 1) {
            RoundLib.Round storage preRound2 = roundList[roundList.length - 2];
            preRound2.pot = preRound2.max * 11 / 10;
            poolSub(preRound2.pot);
        }
        startNextRound(curRound);
    }
}

function unlock(address _locker, uint _delta, uint8 _locktype) private
returns(bool success) {
    if (_locktype == 1) {
        if (_delta < 6 * 30 days) {
            return false;
        }
        uint _more1 = _delta.sub(6 * 30 days);
        uint _step1 = _more1 / 30 days;
        for (uint8 i = 0; i < 10; i++) {
            if (unlockedstep[_locker] == i && i < 9 && i <= _step1) {
                ownerance[_locker] = ownerance[_locker].add(lockedance[_locker] / (10 - i));
                lockedance[_locker] = lockedance[_locker].sub(lockedance[_locker] / (10 - i));
                unlockedstep[_locker] = i + 1;
            } else if (i == 9 && unlockedstep[_locker] == 9 && _step1 == 9) {
                ownerance[_locker] = ownerance[_locker].add(lockedance[_locker]);
                lockedance[_locker] = 0;
                unlockedstep[_locker] = 0;
                lockedtype[_locker] = 0;
            }
        }
    } else if (_locktype == 2) {
        if (_delta < 30 days) {
            return false;
        }
        uint _more2 = _delta - 30 days;
        uint _step2 = _more2 / 30 days;
        for (uint8 j = 0; j < 11; j++) {
            if (unlockedstep[_locker] == j && j < 10 && j <= _step2) {
                ownerance[_locker] = ownerance[_locker].add(lockedance[_locker] / (11 - j));
                lockedance[_locker] = lockedance[_locker].sub(lockedance[_locker] / (11 - j));
                unlockedstep[_locker] = j + 1;
            } else if (j == 10 && unlockedstep[_locker] == 10 && _step2 == 10) {
                ownerance[_locker] = ownerance[_locker].add(lockedance[_locker]);
                lockedance[_locker] = 0;
                unlockedstep[_locker] = 0;
                lockedtype[_locker] = 0;
            }
        }
    }
    return true;
}

function releaseLocked() public
isNotFrozen
returns(bool success) {
    require(now > RELEASE_BASE_TIME);
    uint delta = now - RELEASE_BASE_TIME;
    uint lockedAmount;
    for (uint i = 0; i < lockedOwner.length; i++) {
        if (lockedance[lockedOwner[i]] > 0) {
            lockedAmount = lockedance[lockedOwner[i]];
            unlock(lockedOwner[i], delta, lockedtype[lockedOwner[i]]);
            totalCirculating = totalCirculating.add(lockedAmount - lockedance[lockedOwner[i]]);
        }
    }
    return true;
}

function safeWithdrawal() afterDeadline public {
    if (!fundingGoalReached) {
        uint256 amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                emit FundTransfer(beneficiary, amountRaised, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (fundingGoalReached && beneficiary == msg.sender) {
        if (beneficiary.send(amountRaised)) {
            emit FundTransfer(beneficiary, amountRaised, false);
        } else {
            fundingGoalReached = false;
        }
    }
}

function proofOfWork(uint256 nonce) public {
    bytes8 n = bytes8(keccak256(abi.encodePacked(nonce, currentChallenge))); 
    require(n >= bytes8(difficulty)); 
    uint256 timeSinceLastProof = (now - timeOfLastProof); 
    require(timeSinceLastProof >= 5 seconds); 
    balanceOf[msg.sender] += timeSinceLastProof / 60 seconds; 
    difficulty = difficulty * 10 minutes / timeSinceLastProof + 1; 
    timeOfLastProof = now; 
    currentChallenge = keccak256(abi.encodePacked(nonce, currentChallenge, blockhash(block.number - 1))); 
}

function burn(uint256 _value) public returns(bool success) {
    require(balanceOf[msg.sender] >= _value); 
    balanceOf[msg.sender] -= _value; 
    totalSupply -= _value; 
    emit Burn(msg.sender, _value);
    return true;
}

function _transfer(address _from, address _to, uint256 _value) internal {
    require(_to != 0x0);
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to] + _value >= balanceOf[_to]);
    uint256 previousBalances = balanceOf[_from] + balanceOf[_to];
    balanceOf[_from] -= _value;
    balanceOf[_to] += _value;
    emit Transfer(_from, _to, _value);
    assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

function burnFrom(address _from, uint256 _value) public returns(bool success) {
    require(balanceOf[_from] >= _value); 
    require(_value <= allowance[_from][msg.sender]); 
    balanceOf[_from] -= _value; 
    allowance[_from][msg.sender] -= _value; 
    totalSupply -= _value; 
    emit Burn(_from, _value);
    return true;
}

