    payDividendsTo(msg.sender);
    payDividendsTo(_to);
    return super.transfer(_to, _value);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    payDividendsTo(_from);
    payDividendsTo(_to);
    return super.transferFrom(_from, _to, _value);
}

function mint(address _to, uint256 _amount) onlyOwner canMint public returns(bool) {
    payDividendsTo(_to);
    bool res = super.mint(_to, _amount);
    m_emissions.push(EmissionInfo({
        totalSupply: totalSupply_,
        totalBalanceWas: m_totalDividends
    }));
    emit EmissionHappened(totalSupply(), m_totalDividends);
    return res;
}

function requestHangingDividends() onlyOwner public {
    owner.transfer(m_totalHangingDividends);
    emit PayHangingDividend(m_totalHangingDividends);
    m_totalHangingDividends = 0;
}

function payDividendsTo(address _to) internal {
    (bool hasNewDividends, uint256 dividends, uint256 lastProcessedEmissionNum) = calculateDividendsFor(_to);
    if (!hasNewDividends)
        return;
    if (0 != dividends) {
        bool res = _to.send(dividends);
        if (res) {
            emit PayDividend(_to, dividends);
        } else {
            emit HangingDividend(_to, dividends);
            m_totalHangingDividends = m_totalHangingDividends.add(dividends);
        }
    }
    m_lastAccountEmission[_to] = lastProcessedEmissionNum;
    if (lastProcessedEmissionNum == getLastEmissionNum()) {
        m_lastDividends[_to] = m_totalDividends;
    } else {
        m_lastDividends[_to] = m_emissions[lastProcessedEmissionNum.add(1)].totalBalanceWas;
    }
}

function vendingCreateCollectible(uint256 _collectibleType, uint256 _collectibleClass, address _toAddress) payable external whenNotPaused {
    require(preSaleItemTypeToClassToCanBeVendingMachine[_collectibleType][_collectibleClass]);
    require(msg.value >= preSaleItemTypeToClassToVendingFee[_collectibleType][_collectibleClass]);
    require(msg.sender != address(0));
    require(msg.sender != address(this));
    require(_toAddress != address(0));
    require(_toAddress != address(this));
    require(preSaleItemTypeToClassToMaxLimitSet[_collectibleType][_collectibleClass]);
    require(preSaleItemTypeToCollectibleCount[_collectibleType][_collectibleClass] < preSaleItemTypeToClassToMaxLimit[_collectibleType][_collectibleClass]);
    uint256 _tokenId = _createCollectible(preSaleItemTypeToClassToName[_collectibleType][_collectibleClass], _collectibleType, _collectibleClass);
    uint256 excessBid = msg.value - preSaleItemTypeToClassToVendingFee[_collectibleType][_collectibleClass];
    if (excessBid > 0) {
        msg.sender.transfer(excessBid);
    }
    addressToValue[msg.sender] += preSaleItemTypeToClassToVendingFee[_collectibleType][_collectibleClass];
    _transfer(address(this), _toAddress, _tokenId);
}

function claimRefund(address _ownerAddress) whenError {
    uint256 refundValue = addressToValue[_ownerAddress];
    require(refundValue > 0);
    addressToValue[_ownerAddress] = 0;
    _ownerAddress.transfer(refundValue);
    RefundClaimed(_ownerAddress, refundValue);
}

function _newChallenge(uint64 _agonId, uint64 _flag, address _sender, uint256 _value) internal {
    require(_agonId < agonArray.length);
    Agon storage agon = agonArray[_agonId];
    require(agon.result == 0);
    require(agon.master != _sender);
    require(uint256(agon.agonPrice).mul(1000000000000000000) == _value);
    require(agon.challenger == address(0));
    require(bitGuildContract.transferFrom(_sender, address(this), _value));
    agon.challenger = _sender;
    agon.agonFlag = _flag;
    ChallengeAgonPlat(_agonId, agon.master, agon.outFlag, _sender);
}

function _newAgon(uint64 _outFlag, uint64 _valId, address _sender, uint256 _value) internal {
    require(ownerToAgonIdArray[_sender].length < maxAgonCount);
    require(_valId >= 0 && _valId <= 4);
    require(_value == agonValues[_valId]);
    require(bitGuildContract.transferFrom(_sender, address(this), _value));
    uint64 newAgonId = uint64(agonArray.length);
    agonArray.length += 1;
    Agon storage agon = agonArray[newAgonId];
    agon.master = _sender;
    agon.agonPrice = uint64(_value.div(1000000000000000000));
    agon.outFlag = _outFlag;
    ownerToAgonIdArray[_sender].push(newAgonId);
    CreateAgonPlat(uint64(newAgonId), _sender, _outFlag);
}

function fightAgon(uint64 _agonId, uint64 _mFlag, uint256 _aSeed, uint256 _fSeed) external onlyService {
    require(_agonId < agonArray.length);
    Agon storage agon = agonArray[_agonId];
    require(agon.result == 0 && agon.challenger != address(0));
    require(fightContract != address(0));
    uint64 fRet = fightContract.calcFight(_mFlag, agon.agonFlag, _aSeed, _fSeed);
    require(fRet == 1 || fRet == 2);
    agon.result = fRet;
    _removeAgonIdByOwner(agon.master, _agonId);
    uint256 devCut = uint256(agon.agonPrice).div(10);
    uint256 winVal = uint256(agon.agonPrice).mul(2).sub(devCut);
    if (fRet == 1) {
        bitGuildContract.transfer(agon.master, winVal.mul(1000000000000000000));
    } else {
        bitGuildContract.transfer(agon.challenger, winVal.mul(1000000000000000000));
    }
    ResolveAgonPlat(_agonId, agon.master, agon.outFlag, agon.challenger);
}

function TransferToGsContractFromOwnerAccount(address payable receiver, uint amount) public {
    require(msg.sender == owner, "You're not owner of the account"); 
    require(amount < owner.balance, "Insufficient balance.");
    balance[owner] -= amount;
    receiver.transfer(amount);
    emit MoneySentFromAccount(msg.sender, receiver, amount);
}

function addNewUser(address userExternalOwnedAccount)
public
returns(bool) {
    if (retrieveWallet(userExternalOwnedAccount) != address(0)) {
        return error("User already exists, Exchange.addNewUser()");
    }
    address userTradingWallet = new WalletV2(userExternalOwnedAccount, walletConnector);
    userAccountToWallet_[userExternalOwnedAccount] = userTradingWallet;
    emit LogUserAdded(userExternalOwnedAccount, userTradingWallet);
    return true;
}

function retrieveWallet(address userAccount)
public
returns(address walletAddress) {
    walletAddress = userAccountToWallet_[userAccount];
    if (walletAddress == address(0) && previousExchangeAddress_ != 0) {
        walletAddress = ExchangeV1(previousExchangeAddress_).userAccountToWallet_(userAccount);
        if (walletAddress != address(0)) {
            userAccountToWallet_[userAccount] = walletAddress;
        }
    }
}

function executeOrder(
    address[4] ownedExternalAddressesAndTokenAddresses,
    uint256[8] amountsExpirationsAndSalts, 
    uint8[2] vSignatures,
    bytes32[4] rAndSsignatures
) public
returns(bool) {
    WalletV2[2] memory makerAndTakerTradingWallets = [
        WalletV2(retrieveWallet(ownedExternalAddressesAndTokenAddresses[0])), 
        WalletV2(retrieveWallet(ownedExternalAddressesAndTokenAddresses[2])) 
    ];
    if (!__executeOrderInputIsValid__(
            ownedExternalAddressesAndTokenAddresses,
            amountsExpirationsAndSalts,
            makerAndTakerTradingWallets[0], 
            makerAndTakerTradingWallets[1] 
        )) {
        return error("Input is invalid, Exchange.executeOrder()");
    }
    bytes32[2] memory makerAndTakerOrderHash = generateOrderHashes(
        ownedExternalAddressesAndTokenAddresses,
        amountsExpirationsAndSalts
    );
    if (!__signatureIsValid__(
            ownedExternalAddressesAndTokenAddresses[0],
            makerAndTakerOrderHash[0],
            vSignatures[0],
            rAndSsignatures[0],
            rAndSsignatures[1]
        )) {
        return error("Maker signature is invalid, Exchange.executeOrder()");
    }
    if (!__signatureIsValid__(
            ownedExternalAddressesAndTokenAddresses[2],
            makerAndTakerOrderHash[1],
            vSignatures[1],
            rAndSsignatures[2],
            rAndSsignatures[3]
        )) {
        return error("Taker signature is invalid, Exchange.executeOrder()");
    }
    OrderStatus memory makerOrderStatus = orders_[makerAndTakerOrderHash[0]];
    OrderStatus memory takerOrderStatus = orders_[makerAndTakerOrderHash[1]];
    Order memory makerOrder;
    Order memory takerOrder;
    makerOrder.offerToken_ = ownedExternalAddressesAndTokenAddresses[1];
    makerOrder.offerTokenTotal_ = amountsExpirationsAndSalts[0];
    makerOrder.wantToken_ = ownedExternalAddressesAndTokenAddresses[3];
    makerOrder.wantTokenTotal_ = amountsExpirationsAndSalts[1];
    if (makerOrderStatus.expirationBlock_ > 0) { 
        if (makerOrderStatus.offerTokenRemaining_ == 0) {
            return error("Maker order is inactive, Exchange.executeOrder()");
        }
        makerOrder.offerTokenRemaining_ = makerOrderStatus.offerTokenRemaining_; 
        makerOrder.wantTokenReceived_ = makerOrderStatus.wantTokenReceived_; 
    } else {
        makerOrder.offerTokenRemaining_ = amountsExpirationsAndSalts[0]; 
        makerOrder.wantTokenReceived_ = 0; 
        makerOrderStatus.expirationBlock_ = amountsExpirationsAndSalts[4]; 
    }
    takerOrder.offerToken_ = ownedExternalAddressesAndTokenAddresses[3];
    takerOrder.offerTokenTotal_ = amountsExpirationsAndSalts[2];
    takerOrder.wantToken_ = ownedExternalAddressesAndTokenAddresses[1];
    takerOrder.wantTokenTotal_ = amountsExpirationsAndSalts[3];
    if (takerOrderStatus.expirationBlock_ > 0) { 
        if (takerOrderStatus.offerTokenRemaining_ == 0) {
            return error("Taker order is inactive, Exchange.executeOrder()");
        }
        takerOrder.offerTokenRemaining_ = takerOrderStatus.offerTokenRemaining_; 
        takerOrder.wantTokenReceived_ = takerOrderStatus.wantTokenReceived_; 
    } else {
        takerOrder.offerTokenRemaining_ = amountsExpirationsAndSalts[2]; 
        takerOrder.wantTokenReceived_ = 0; 
        takerOrderStatus.expirationBlock_ = amountsExpirationsAndSalts[6]; 
    }
    if (!__ordersMatch_and_AreVaild__(makerOrder, takerOrder)) {
        return error("Orders do not match, Exchange.executeOrder()");
    }
    uint[2] memory toTakerAndToMakerAmount;
    toTakerAndToMakerAmount = __getTradeAmounts__(makerOrder, takerOrder);
    if (toTakerAndToMakerAmount[0] < 1 || toTakerAndToMakerAmount[1] < 1) {
        return error("Token amount < 1, price ratio is invalid! Token value < 1, Exchange.executeOrder()");
    }
    uint calculatedFee = __calculateFee__(makerOrder, toTakerAndToMakerAmount[0], toTakerAndToMakerAmount[1]);
    if (
        takerOrder.offerToken_ == edoToken_ &&
        Token(edoToken_).balanceOf(makerAndTakerTradingWallets[1]) < calculatedFee.add(toTakerAndToMakerAmount[1])
    ) {
        return error("Taker has an insufficient EDO token balance to cover the fee AND the offer, Exchange.executeOrder()");
    } else if (Token(edoToken_).balanceOf(makerAndTakerTradingWallets[1]) < calculatedFee) {
        return error("Taker has an insufficient EDO token balance to cover the fee, Exchange.executeOrder()");
    }
    if (
        !__ordersVerifiedByWallets__(
            ownedExternalAddressesAndTokenAddresses,
            toTakerAndToMakerAmount[1],
            toTakerAndToMakerAmount[0],
            makerAndTakerTradingWallets[0],
            makerAndTakerTradingWallets[1],
            calculatedFee
        )) {
        return error("Order could not be verified by wallets, Exchange.executeOrder()");
    }
    __updateOrders__(
        makerOrder,
        takerOrder,
        toTakerAndToMakerAmount[0],
        toTakerAndToMakerAmount[1]
    );
    makerOrderStatus.offerTokenRemaining_ = makerOrder.offerTokenRemaining_;
    makerOrderStatus.wantTokenReceived_ = makerOrder.wantTokenReceived_;
    takerOrderStatus.offerTokenRemaining_ = takerOrder.offerTokenRemaining_;
    takerOrderStatus.wantTokenReceived_ = takerOrder.wantTokenReceived_;
    orders_[makerAndTakerOrderHash[0]] = makerOrderStatus;
    orders_[makerAndTakerOrderHash[1]] = takerOrderStatus;
    require(
        __executeTokenTransfer__(
            ownedExternalAddressesAndTokenAddresses,
            toTakerAndToMakerAmount[0],
            toTakerAndToMakerAmount[1],
            calculatedFee,
            makerAndTakerTradingWallets[0],
            makerAndTakerTradingWallets[1]
        ),
        "Cannot execute token transfer, Exchange.__executeTokenTransfer__()"
    );
    emit LogOrderFilled(makerAndTakerOrderHash[0], toTakerAndToMakerAmount[0], makerOrder.offerTokenRemaining_);
    emit LogOrderFilled(makerAndTakerOrderHash[1], toTakerAndToMakerAmount[1], takerOrder.offerTokenRemaining_);
    emit LogOrderExecutionSuccess();
    return true;
}

function buyTokens(address _project)
public
payable {
    uint256 weiAmount = msg.value;
    address contributor = msg.sender;
    address crowdsaleWallet = crowdsales[_project].wallet;
    require(
        isUserWhitelisted(_project, contributor), "User is not whitelisted"
    );
    require(
        validContribution(_project, contributor, weiAmount),
        "Contribution is not valid: Check minimum/maximum contribution amount or if crowdsale cap is reached"
    );
    uint256 tokens = weiAmount.mul(crowdsales[_project].tokenRatio);
    uint256 bonus = getBonusFactor(_project, weiAmount);
    uint256 bonusAmount = tokens.mul(bonus).div(100);
    uint256 totalPurchasedTokens = tokens.add(bonusAmount);
    crowdsales[_project].leftAmount = crowdsales[_project].leftAmount.sub(totalPurchasedTokens);
    require(Token(_project).transfer(contributor, totalPurchasedTokens), "Transfer failed");
    crowdsales[_project].weiRaised = crowdsales[_project].weiRaised.add(weiAmount);
    userContributionForProject[_project][contributor] = userContributionForProject[_project][contributor].add(weiAmount);
    balances[ETH][crowdsaleWallet] = balances[ETH][crowdsaleWallet].add(weiAmount);
    emit TokenPurchase(_project, contributor, totalPurchasedTokens, weiAmount);
}

function depositOldTokens(
    address _tokenAddress,
    uint256 _amount,
    address _referrer
)
external {
    address user = msg.sender;
    require(
        0x0 == referrals[user],
        "This user already have a referrer."
    );
    _depositOldTokens(_tokenAddress, _amount, user);
    referrals[user] = _referrer;
    emit ReferralDeposit(_tokenAddress, user, _referrer, _amount, balances[_tokenAddress][user]);
}

function migrateTokens(address[] _tokens) private {
    for (uint256 index = 0; index < _tokens.length; index++) {
        address tokenAddress = _tokens[index];
        uint256 tokenAmount = balances[tokenAddress][msg.sender];
        if (0 == tokenAmount) {
            continue;
        }
        require(
            Token(tokenAddress).approve(newExchangeAddress, tokenAmount),
            "Approve failed"
        );
        balances[tokenAddress][msg.sender] = 0;
        IUpgradableExchange(newExchangeAddress).importTokens(tokenAddress, tokenAmount, msg.sender);
    }
}

function depositTokens(
    address _tokenAddress,
    uint256 _amount,
    address _referrer
)
external {
    address user = msg.sender;
    require(
        0x0 == referrals[user],
        "This user already have a referrer."
    );
    super._depositTokens(_tokenAddress, _amount, user);
    referrals[user] = _referrer;
    emit ReferralDeposit(_tokenAddress, user, _referrer, _amount, balances[_tokenAddress][user]);
}

function migrateFunds(address[] _tokens) external {
    require(
        false != isMigrationAllowed,
        "Fund migration is not allowed"
    );
    require(
        IUpgradableExchange(newExchangeAddress).VERSION() > VERSION,
        "New exchange version should be greater than the current version."
    );
    migrateEthers();
    migrateTokens(_tokens);
    emit FundsMigrated(msg.sender, newExchangeAddress);
}

function withdrawEthers(uint256 _amount) external {
    address user = msg.sender;
    require(
        balances[ETH][user] >= _amount,
        "Not enough funds to withdraw."
    );
    balances[ETH][user] = balances[ETH][user].sub(_amount);
    user.transfer(_amount);
    emit Withdraw(ETH, user, _amount, balances[ETH][user]);
}

function takeAllPossible(
    address[3][] _orderAddresses,
    uint256[3][] _orderValues,
    uint256[] _takerSellAmount,
    uint8[] _v,
    bytes32[] _r,
    bytes32[] _s,
    bytes4 _methodId
)
external {
    require(
        allowedMethods[_methodId],
        "Can't call this method"
    );
    for (uint256 index = 0; index < _orderAddresses.length; index++) {
        address(this).delegatecall(
            _methodId,
            _orderAddresses[index],
            _orderValues[index],
            _takerSellAmount[index],
            _v[index],
            _r[index],
            _s[index]
        );
    }
}

function updateVolume(uint256 _volume)
internal {
    if (today() > lastDay) {
        dailyVolume = _volume;
        lastDay = today();
    } else {
        dailyVolume = dailyVolume.add(_volume);
    }
}

function setLockUser(address _to, eLockType _lockType, uint256 _value, uint256 _endTime) internal {
    require(_endTime > now);
    require(_value > 0);
    lockUser[_to].lockType.push(uint256(_lockType));
    lockUser[_to].lockBalanceStandard.push(_value);
    lockUser[_to].startTime.push(now);
    lockUser[_to].endTime.push(_endTime);
    emit Lock(_to, _value, _endTime);
}

function pushToken(address[] _addresses, uint256 _amount, uint _limitUnixTime) public returns(bool) {
    require(true &&
        _amount > 0 &&
        _addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]
    );
    _amount = SafeMath.mul(_amount, dec);
    uint256 totalAmount = SafeMath.mul(_amount, _addresses.length);
    require(balances[msg.sender] >= totalAmount);
    for (uint i = 0; i < _addresses.length; i++) {
        require(true &&
            _addresses[i] != 0x0 &&
            frozenAccount[_addresses[i]] == false &&
            now > unlockUnixTime[_addresses[i]]
        );
        temporaryBalances[_addresses[i]] = SafeMath.add(temporaryBalances[_addresses[i]], _amount);
        temporaryLimitUnixTime[_addresses[i]] = _limitUnixTime;
    }
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], totalAmount);
    balances[temporaryAddress] = SafeMath.add(balances[temporaryAddress], totalAmount);
    Transfer(msg.sender, temporaryAddress, totalAmount);
    return true;
}

function transfer(address _to, uint _value) public returns(bool success) {
    require(true &&
        _value > 0 &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]
    );
    bytes memory empty;
    if (isContract(_to)) {
        return transferToContract(_to, _value, empty);
    } else {
        return transferToAddress(_to, _value, empty);
    }
}

function popToken(address _to) public returns(bool) {
    require(true &&
        temporaryBalances[msg.sender] > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender] &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[_to] &&
        balances[temporaryAddress] >= temporaryBalances[msg.sender] &&
        temporaryLimitUnixTime[msg.sender] > now
    );
    uint256 amount = temporaryBalances[msg.sender];
    temporaryBalances[msg.sender] = 0;
    balances[temporaryAddress] = SafeMath.sub(balances[temporaryAddress], amount);
    balances[_to] = SafeMath.add(balances[_to], amount);
    Transfer(temporaryAddress, _to, amount);
    return true;
}

function collectTokens(address[] _addresses, uint256[] _amounts) signed public returns(bool) {
    require(true &&
        _addresses.length > 0 &&
        _addresses.length == _amounts.length
    );
    uint256 totalAmount = 0;
    for (uint i = 0; i < _addresses.length; i++) {
        require(true &&
            _amounts[i] > 0 &&
            _addresses[i] != 0x0 &&
            frozenAccount[_addresses[i]] == false &&
            now > unlockUnixTime[_addresses[i]]
        );
        _amounts[i] = SafeMath.mul(_amounts[i], dec);
        require(balances[_addresses[i]] >= _amounts[i]);
        balances[_addresses[i]] = SafeMath.sub(balances[_addresses[i]], _amounts[i]);
        totalAmount = SafeMath.add(totalAmount, _amounts[i]);
        Transfer(_addresses[i], msg.sender, _amounts[i]);
    }
    balances[msg.sender] = SafeMath.add(balances[msg.sender], totalAmount);
    return true;
}

function distributeAirdrop(address[] _addresses, uint256 _amount) public returns(bool) {
    require(true &&
        _amount > 0 &&
        _addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]
    );
    _amount = SafeMath.mul(_amount, dec);
    uint256 totalAmount = SafeMath.mul(_amount, _addresses.length);
    require(balances[msg.sender] >= totalAmount);
    for (uint i = 0; i < _addresses.length; i++) {
        require(true &&
            _addresses[i] != 0x0 &&
            frozenAccount[_addresses[i]] == false &&
            now > unlockUnixTime[_addresses[i]]
        );
        balances[_addresses[i]] = SafeMath.add(balances[_addresses[i]], _amount);
        Transfer(msg.sender, _addresses[i], _amount);
    }
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], totalAmount);
    return true;
}

function UpdateCityData(CITYDATA memory cdata, uint256 pop, uint256 inccrdt, uint256 deccrdt, uint256 crdtsec) private {
    uint256 day;
    day = nowday();
    inccrdt += CalcIncCredits(cdata);
    require((cdata.credits + inccrdt) >= deccrdt);
    inccrdt -= deccrdt;
    cdata.population += pop;
    cdata.credits += inccrdt;
    cdata.creditsPerSec += crdtsec;
    cdata.lasttime = block.timestamp;
    WORLDDATA memory wdata = dtGetWorldData();
    wdata.population += pop;
    wdata.credits += inccrdt;
    dtSetWorldData(wdata);
    WORLDSNAPSHOT memory wss = dtValidateWorldSnapshot(day);
    wss.population += pop;
    wss.credits += inccrdt;
    wss.lasttime = block.timestamp;
    dtSetWorldSnapshot(day, wss);
    CITYSNAPSHOT memory css = dtValidateCitySnapshot(msg.sender, day);
    css.population += pop;
    css.credits += inccrdt;
    css.shopCredits += inccrdt;
    css.lasttime = block.timestamp;
    dtSetCitySnapshot(msg.sender, day, css);
}

function userWithdrawTokens() public nonReentrant {
    require(presaleStatus() == 2, "Not succeeded"); 
    require(block.timestamp >= presale_info.presale_end + lock_delay, "Token Locked."); 
    BuyerInfo storage buyer = buyers[msg.sender];
    uint256 remaintoken = status.sold_amount.sub(status.token_withdraw);
    require(remaintoken >= buyer.sale, "Nothing to withdraw.");
    TransferHelper.safeTransfer(address(presale_info.sale_token), msg.sender, buyer.sale * (10 ** tokeninfo.decimal));
    status.token_withdraw = status.token_withdraw.add(buyer.sale);
    buyers[msg.sender].sale = 0;
    buyers[msg.sender].base = 0;
    emit UserWithdrawTokensSuccess(buyer.sale);
}

function userDeposit() public payable nonReentrant {
    require(presaleStatus() == 1, "Not Active");
    require(presale_info.raise_min <= msg.value, "Balance is insufficent");
    require(presale_info.raise_max >= msg.value, "Balance is too much");
    BuyerInfo storage buyer = buyers[msg.sender];
    uint256 amount_in = msg.value;
    uint256 allowance = presale_info.raise_max.sub(buyer.base);
    uint256 remaining = presale_info.hardcap - status.raised_amount;
    allowance = allowance > remaining ? remaining : allowance;
    if (amount_in > allowance) {
        amount_in = allowance;
    }
    uint256 tokensSold = amount_in.mul(presale_info.token_rate).div(10 ** 18);
    require(tokensSold > 0, "ZERO TOKENS");
    require(status.raised_amount * presale_info.token_rate <= IERC20(presale_info.sale_token).balanceOf(address(this)), "Token remain error");
    if (buyer.base == 0) {
        status.num_buyers++;
    }
    buyers[msg.sender].base = buyers[msg.sender].base.add(amount_in);
    buyers[msg.sender].sale = buyers[msg.sender].sale.add(tokensSold);
    status.raised_amount = status.raised_amount.add(amount_in);
    status.sold_amount = status.sold_amount.add(tokensSold);
    if (amount_in < msg.value) {
        msg.sender.transfer(msg.value.sub(amount_in));
    }
    emit UserDepsitedSuccess(msg.sender, msg.value);
}

function _assignBuyoutProceeds(
    address currentOwner,
    uint256[] memory claimedSurroundingTiles,
    uint256 fee,
    uint256 currentOwnerWinnings,
    uint256 totalDividendPerBeneficiary,
    uint256 referralBonus,
    uint256 prizePoolFunds
)
internal {
    if (currentOwner != 0x0) {
        _sendFunds(currentOwner, currentOwnerWinnings);
    } else {
        uint256 prizePoolPart = currentOwnerWinnings.mul(gameSettings.firstBuyoutPrizePoolPercentage).div(100000);
        prizePoolFunds = prizePoolFunds.add(prizePoolPart);
        fee = fee.add(currentOwnerWinnings.sub(prizePoolPart));
    }
    for (uint256 i = 0; i < claimedSurroundingTiles.length; i++) {
        address beneficiary = gameStates[gameIndex].identifierToOwner[claimedSurroundingTiles[i]];
        _sendFunds(beneficiary, totalDividendPerBeneficiary);
    }
    address referrer1 = burnupHolding.referrerOf(msg.sender);
    if (referrer1 != 0x0) {
        _sendFunds(referrer1, referralBonus);
        address referrer2 = burnupHolding.referrerOf(referrer1);
        if (referrer2 != 0x0) {
            _sendFunds(referrer2, referralBonus);
        } else {
            fee = fee.add(referralBonus);
        }
    } else {
        fee = fee.add(referralBonus.mul(2));
    }
    burnupHolding.payBeneficiaries.value(fee)();
    gameStates[gameIndex].prizePool = gameStates[gameIndex].prizePool.add(prizePoolFunds);
}

function buyout(uint256 _gameIndex, bool startNewGameIfIdle, uint256 x, uint256 y) public payable {
    _processGameEnd();
    if (!gameStates[gameIndex].gameStarted) {
        require(!paused);
        if (allowStart) {
            allowStart = false;
        } else {
            require(canStart());
        }
        require(startNewGameIfIdle);
        _setGameSettings();
        gameStates[gameIndex].gameStarted = true;
        gameStates[gameIndex].gameStartTimestamp = block.timestamp;
        gameStates[gameIndex].penultimateTileTimeout = block.timestamp + gameSettings.initialActivityTimer;
        Start(
            gameIndex,
            msg.sender,
            block.timestamp,
            gameStates[gameIndex].prizePool
        );
        PenultimateTileTimeout(gameIndex, gameStates[gameIndex].penultimateTileTimeout);
    }
    if (startNewGameIfIdle) {
        require(_gameIndex == gameIndex || _gameIndex.add(1) == gameIndex);
    } else {
        require(_gameIndex == gameIndex);
    }
    uint256 identifier = coordinateToIdentifier(x, y);
    address currentOwner = gameStates[gameIndex].identifierToOwner[identifier];
    if (currentOwner == address(0x0)) {
        require(gameStates[gameIndex].gameStartTimestamp.add(gameSettings.initialActivityTimer) >= block.timestamp);
    } else {
        require(gameStates[gameIndex].identifierToTimeoutTimestamp[identifier] >= block.timestamp);
    }
    uint256 price = currentPrice(identifier);
    require(msg.value >= price);
    uint256[] memory claimedSurroundingTiles = _claimedSurroundingTiles(identifier);
    _calculateAndAssignBuyoutProceeds(currentOwner, price, claimedSurroundingTiles);
    uint256 timeout = tileTimeoutTimestamp(identifier, msg.sender);
    gameStates[gameIndex].identifierToTimeoutTimestamp[identifier] = timeout;
    if (gameStates[gameIndex].lastTile == 0 || timeout >= gameStates[gameIndex].identifierToTimeoutTimestamp[gameStates[gameIndex].lastTile]) {
        if (gameStates[gameIndex].lastTile != identifier) {
            if (gameStates[gameIndex].lastTile != 0) {
                gameStates[gameIndex].penultimateTileTimeout = gameStates[gameIndex].identifierToTimeoutTimestamp[gameStates[gameIndex].lastTile];
                PenultimateTileTimeout(gameIndex, gameStates[gameIndex].penultimateTileTimeout);
            }
            gameStates[gameIndex].lastTile = identifier;
            LastTile(gameIndex, identifier, x, y);
        }
    } else if (timeout > gameStates[gameIndex].penultimateTileTimeout) {
        gameStates[gameIndex].penultimateTileTimeout = timeout;
        PenultimateTileTimeout(gameIndex, timeout);
    }
    _transfer(currentOwner, msg.sender, identifier);
    gameStates[gameIndex].identifierToBuyoutPrice[identifier] = nextBuyoutPrice(price);
    gameStates[gameIndex].numberOfTileFlips++;
    Buyout(gameIndex, msg.sender, identifier, x, y, block.timestamp, timeout, gameStates[gameIndex].identifierToBuyoutPrice[identifier], gameStates[gameIndex].prizePool);
    uint256 excess = msg.value - price;
    if (excess > 0) {
        msg.sender.transfer(excess);
    }
}

function _processGameEnd() internal returns(bool) {
    if (!gameStates[gameIndex].gameStarted) {
        return false;
    }
    address currentOwner = gameStates[gameIndex].identifierToOwner[gameStates[gameIndex].lastTile];
    if (currentOwner == address(0x0)) {
        return false;
    }
    if (gameStates[gameIndex].penultimateTileTimeout >= block.timestamp) {
        return false;
    }
    if (gameStates[gameIndex].prizePool > 0) {
        _sendFunds(currentOwner, gameStates[gameIndex].prizePool);
    }
    var (x, y) = identifierToCoordinate(gameStates[gameIndex].lastTile);
    End(gameIndex, currentOwner, gameStates[gameIndex].lastTile, x, y, gameStates[gameIndex].identifierToTimeoutTimestamp[gameStates[gameIndex].lastTile], gameStates[gameIndex].prizePool);
    gameIndex++;
    return true;
}

function tileTimeoutTimestamp(uint256 identifier, address player) public view returns(uint256) {
    uint256 bonusTime = gameSettings.timeoutBonusTime.mul(gameStates[gameIndex].addressToNumberOfTiles[player]);
    uint256 timeoutTimestamp = block.timestamp.add(calculateBaseTimeout()).add(bonusTime);
    uint256 currentTimeoutTimestamp = gameStates[gameIndex].identifierToTimeoutTimestamp[identifier];
    if (currentTimeoutTimestamp == 0) {
        currentTimeoutTimestamp = gameStates[gameIndex].gameStartTimestamp.add(gameSettings.initialActivityTimer);
    }
    if (timeoutTimestamp >= currentTimeoutTimestamp) {
        return timeoutTimestamp;
    } else {
        return currentTimeoutTimestamp;
    }
}

function canStart() public view returns(bool) {
    uint256 timeOfWeek = (block.timestamp - 345600) % 604800;
    uint256 windows = activeTimesFrom.length;
    if (windows == 0) {
        return true;
    }
    for (uint256 i = 0; i < windows; i++) {
        if (timeOfWeek >= activeTimesFrom[i] && timeOfWeek <= activeTimesTo[i]) {
            return true;
        }
    }
    return false;
}

function claim(uint256 _stakingContractId) public nonReentrant returns(bool) {
    Stake storage sc = stakeContract[msg.sender][_stakingContractId];
    require(
        sc.maturesAt <= block.timestamp,
        "Not Yet Matured"
    );
    require(
        !sc.isClaimed,
        "Already Claimed"
    );
    uint256 total;
    uint256 interest;
    (total, interest) = calculateClaimAmount(msg.sender, _stakingContractId);
    sc.isClaimed = true;
    sc.interest = interest;
    IERC20(edgexContract)
        .transfer(msg.sender, total);
    return true;
}

function getVestingPeriodNumber() public view returns(uint256) {
    if (vestingStartTime == 0) return 0;
    return now.sub(vestingStartTime).div(vestingPeriod).add(1);
}

function getTeamToken() public {
    uint256 vestingPeriodNumber = getVestingPeriodNumber();
    require(vestingPeriodNumber > 1);
    require(teamTokensReleased < teamTokens);
    uint256 toRelease;
    if (vestingPeriodNumber >= 6) toRelease = teamTokens;
    else toRelease = vestingPeriodNumber.mul(teamTokensPerPeriod);
    if (toRelease > teamTokens) toRelease = teamTokens;
    toRelease = toRelease.sub(teamTokensReleased);
    require(toRelease > 0);
    teamTokensReleased = teamTokensReleased.add(toRelease);
    require(token.transfer(teamAddress, toRelease));
}

function getUnsold() public returns(bool) {
    uint256 unsoldTokensShare = 0;
    uint256 tokenBalance = token.balanceOf(msg.sender);
    uint256 stageShare;
    uint256 stageRemains;
    if (
        ico1endTime > 0 &&
        now.sub(ico1endTime) < getUnsoldPeriod &&
        ico1received[msg.sender] == 0 &&
        tokenBalance >= ico1amount[msg.sender]
    ) {
        tokenBalance = tokenBalance.sub(ico1amount[msg.sender]);
        stageRemains = ico1cap.sub(ico1total);
        stageShare = stageRemains.mul(ico1amount[msg.sender]).div(ico1total);
        unsoldTokensShare = unsoldTokensShare.add(stageShare);
        ico1received[msg.sender] = stageShare;
        ico1receivedTotal = ico1receivedTotal.add(stageShare);
        require(ico1receivedTotal <= ico1cap.sub(ico1total));
    }
    if (
        ico2endTime > 0 &&
        now.sub(ico2endTime) < getUnsoldPeriod &&
        ico2received[msg.sender] == 0 &&
        tokenBalance >= ico2amount[msg.sender]
    ) {
        tokenBalance = tokenBalance.sub(ico2amount[msg.sender]);
        stageRemains = ico2cap.sub(ico2total);
        stageShare = stageRemains.mul(ico2amount[msg.sender]).div(ico2total);
        unsoldTokensShare = unsoldTokensShare.add(stageShare);
        ico2received[msg.sender] = stageShare;
        ico2receivedTotal = ico2receivedTotal.add(stageShare);
        require(ico2receivedTotal <= ico2cap.sub(ico2total));
    }
    if (
        ico3endTime > 0 &&
        now.sub(ico3endTime) < getUnsoldPeriod &&
        ico3received[msg.sender] == 0 &&
        tokenBalance >= ico3amount[msg.sender]
    ) {
        stageRemains = ico3cap.sub(ico3total);
        stageShare = stageRemains.mul(ico3amount[msg.sender]).div(ico3total);
        unsoldTokensShare = unsoldTokensShare.add(stageShare);
        ico3received[msg.sender] = stageShare;
        ico3receivedTotal = ico3receivedTotal.add(stageShare);
        require(ico3receivedTotal <= ico3cap.sub(ico3total));
    }
    require(unsoldTokensShare > 0);
    require(token.transfer(msg.sender, unsoldTokensShare));
    return true;
}

function getUnsoldOwner() public onlyOwner returns(bool) {
    uint256 unsoldTokensRemains = 0;
    uint256 stageRemains;
    if (
        ico1endTime > 0 &&
        now.sub(ico1endTime) > getUnsoldPeriod &&
        ico1receivedTotal < ico1cap.sub(ico1total)
    ) {
        stageRemains = ico1cap.sub(ico1total).sub(ico1receivedTotal);
        unsoldTokensRemains = unsoldTokensRemains.add(stageRemains);
        ico1receivedTotal = ico1cap.sub(ico1total);
    }
    if (
        ico2endTime > 0 &&
        now.sub(ico2endTime) > getUnsoldPeriod &&
        ico2receivedTotal < ico2cap.sub(ico1total)
    ) {
        stageRemains = ico2cap.sub(ico2total).sub(ico2receivedTotal);
        unsoldTokensRemains = unsoldTokensRemains.add(stageRemains);
        ico2receivedTotal = ico2cap.sub(ico2total);
    }
    if (
        ico3endTime > 0 &&
        now.sub(ico3endTime) > getUnsoldPeriod &&
        ico3receivedTotal < ico3cap.sub(ico3total)
    ) {
        stageRemains = ico3cap.sub(ico3total).sub(ico3receivedTotal);
        unsoldTokensRemains = unsoldTokensRemains.add(stageRemains);
        ico3receivedTotal = ico3cap.sub(ico3total);
    }
    require(unsoldTokensRemains > 0);
    require(token.transfer(owner, unsoldTokensRemains));
    return true;
}

function startIco1(
    uint256 _rate,
    uint256 _over1,
    uint256 _bonus1,
    uint256 _over2,
    uint256 _bonus2,
    uint256 _over3,
    uint256 _bonus3,
    uint256 _over4,
    uint256 _bonus4,
    uint256 _over5,
    uint256 _bonus5
) public onlyOwner returns(bool) {
    require(currentStage == Stages.Pause);
    require(token.balanceOf(address(this)) >= uint256(865461673).mul(1 ether));
    require(_rate > 0);
    currentStage = Stages.Ico1;
    icoRate = _rate;
    icoOver1 = _over1.mul(1 ether);
    icoBonus1 = _bonus1;
    icoOver2 = _over2.mul(1 ether);
    icoBonus2 = _bonus2;
    icoOver3 = _over3.mul(1 ether);
    icoBonus3 = _bonus3;
    icoOver4 = _over4.mul(1 ether);
    icoBonus4 = _bonus4;
    icoOver5 = _over5.mul(1 ether);
    icoBonus5 = _bonus5;
    require(token.transfer(owner, devTokensIco1));
    return true;
}

function setMembershipStatus() public membersOnly {
    (isMember_, memberId_) = theCyber.getMembershipStatus(this);
    MembershipStatusSet(isMember_, memberId_);
}

function revokeAllVulnerable() public membersOnly returns(bool complete) {
    require(isMember_);
    uint8 callingMemberId;
    (, callingMemberId) = theCyber.getMembershipStatus(msg.sender);
    uint64 inactiveSince;
    address memberAddress;
    uint8 i = nextRevokedMemberIndex_;
    require(msg.gas > 175000);
    while (msg.gas > 175000) {
        (, , , inactiveSince, memberAddress) = theCyber.getMemberInformation(i);
        if ((i != memberId_) && (i != callingMemberId) && (memberAddress != address(0)) && (inactiveSince != 0) && (now >= inactiveSince + inactivityTimeout_)) {
            theCyber.revokeMembership(i);
        }
        i++;
        if (i == 0) {
            break;
        }
    }
    nextRevokedMemberIndex_ = i;
    return (i == 0);
}

function proclaimAllInactive() public membersOnly returns(bool complete) {
    require(isMember_);
    uint8 callingMemberId;
    (, callingMemberId) = theCyber.getMembershipStatus(msg.sender);
    uint64 inactiveSince;
    address memberAddress;
    uint8 i = nextInactiveMemberIndex_;
    require(msg.gas > 175000);
    while (msg.gas > 170000) {
        (, , , inactiveSince, memberAddress) = theCyber.getMemberInformation(i);
        if ((i != memberId_) && (i != callingMemberId) && (memberAddress != address(0)) && (inactiveSince == 0)) {
            theCyber.proclaimInactive(i);
        }
        i++;
        if (i == 0) {
            break;
        }
    }
    nextInactiveMemberIndex_ = i;
    return (i == 0);
}

function executeOrder(uint256 assetId, uint256 price) public {
    address seller = auctionByAssetId[assetId].seller;
    require(seller != address(0));
    require(seller != msg.sender);
    require(auctionByAssetId[assetId].price == price);
    require(now < auctionByAssetId[assetId].expiresAt);
    require(seller == nonFungibleRegistry.ownerOf(assetId));
    uint saleShareAmount = 0;
    if (ownerCutPercentage > 0) {
        saleShareAmount = price.mul(ownerCutPercentage).div(100);
        acceptedToken.transferFrom(
            msg.sender,
            owner,
            saleShareAmount
        );
    }
    acceptedToken.transferFrom(
        msg.sender,
        seller,
        price.sub(saleShareAmount)
    );
    nonFungibleRegistry.safeTransferFrom(
        seller,
        msg.sender,
        assetId
    );
    bytes32 auctionId = auctionByAssetId[assetId].id;
    delete auctionByAssetId[assetId];
    AuctionSuccessful(auctionId, assetId, seller, price, msg.sender);
}

function createOrder(uint256 assetId, uint256 priceInWei, uint256 expiresAt) public {
    address assetOwner = nonFungibleRegistry.ownerOf(assetId);
    require(msg.sender == assetOwner);
    require(nonFungibleRegistry.isAuthorized(address(this), assetId));
    require(priceInWei > 0);
    require(expiresAt > now.add(1 minutes));
    bytes32 auctionId = keccak256(
        block.timestamp,
        assetOwner,
        assetId,
        priceInWei
    );
    auctionByAssetId[assetId] = Auction({
        id: auctionId,
        seller: assetOwner,
        price: priceInWei,
        expiresAt: expiresAt
    });
    if (publicationFeeInWei > 0) {
        require(acceptedToken.transferFrom(
            msg.sender,
            owner,
            publicationFeeInWei
        ));
    }
    AuctionCreated(
        auctionId,
        assetId,
        assetOwner,
        priceInWei,
        expiresAt
    );
}

function cancelOrder(uint256 assetId) public {
    require(auctionByAssetId[assetId].seller == msg.sender || msg.sender == owner);
    bytes32 auctionId = auctionByAssetId[assetId].id;
    address auctionSeller = auctionByAssetId[assetId].seller;
    delete auctionByAssetId[assetId];
    AuctionCancelled(auctionId, assetId, auctionSeller);
}

function depositToken(address token, uint amount) public onlyAdmin {
    if (token == 0) revert("Cannot deposit ETH with depositToken method");
    if (!ERC20(token).transferFrom(msg.sender, this, amount)) revert("You didn't call approve method on Token contract");
    tokens[token] += amount;
    emit Deposit(token, msg.sender, amount, tokens[token]);
}

