function transferFrom(address _from, address _to, uint256 _amount) public returns(bool success) {
    require(_to != address(0));
    require(balances[_from] >= _amount);
    require(allowed[_from][msg.sender] >= _amount);
    require(_amount > 0 && balances[_to].add(_amount) > balances[_to]);
    if (lockupParticipants[_from].lockupAmount > 0) {
        uint timePassed = now - startTime;
        if (timePassed < lockupParticipants[_from].lockupTime) {
            require(balances[msg.sender].sub(_amount) >= lockupParticipants[_from].lockupAmount);
        }
    }
    balances[_from] = balances[_from].sub(_amount);
    balances[_to] = balances[_to].add(_amount);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_amount);
    emit Transfer(_from, _to, _amount);
    return true;
}

function transfer(address _to, uint256 _amount) public returns(bool success) {
    require(_to != address(0));
    require(balances[msg.sender] >= _amount && _amount > 0 &&
        balances[_to].add(_amount) > balances[_to]);
    if (lockupParticipants[msg.sender].lockupAmount > 0) {
        uint timePassed = now - startTime;
        if (timePassed < lockupParticipants[msg.sender].lockupTime) {
            require(balances[msg.sender].sub(_amount) >= lockupParticipants[msg.sender].lockupAmount);
        }
    }
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    balances[_to] = balances[_to].add(_amount);
    emit Transfer(msg.sender, _to, _amount);
    return true;
}

function trade(uint256 tradingProxyIndex, ERC20 src, uint256 srcAmount, ERC20 dest, uint256 minDestAmount) payable public returns(uint256) {
    uint256 destAmount;
    if (etherERC20 != src) {
        src.transferFrom(msg.sender, address(this), srcAmount);
    }
    destAmount = _trade(tradingProxyIndex, src, srcAmount, dest, 1);
    require(destAmount >= minDestAmount, "destination amount is too low.");
    if (etherERC20 == dest) {
        msg.sender.transfer(destAmount);
    } else {
        dest.transfer(msg.sender, destAmount);
    }
    emit Trade(src, srcAmount, dest, destAmount, msg.sender, 0);
    return destAmount;
}

function tradeRoutes(
    ERC20 src,
    uint256 srcAmount,
    ERC20 dest,
    uint256 minDestAmount,
    address[] _tradingPaths)
public payable returns(uint256) {
    uint256 destAmount;
    if (etherERC20 != src) {
        src.transferFrom(msg.sender, address(this), srcAmount);
    }
    uint256 pathSrcAmount = srcAmount;
    for (uint i = 0; i < _tradingPaths.length; i += 3) {
        uint256 tradingProxyIndex = uint256(_tradingPaths[i]);
        ERC20 pathSrc = ERC20(_tradingPaths[i + 1]);
        ERC20 pathDest = ERC20(_tradingPaths[i + 2]);
        destAmount = _trade(tradingProxyIndex, pathSrc, pathSrcAmount, pathDest, 1);
        pathSrcAmount = destAmount;
    }
    require(destAmount >= minDestAmount, "destination amount is too low.");
    if (etherERC20 == dest) {
        msg.sender.transfer(destAmount);
    } else {
        dest.transfer(msg.sender, destAmount);
    }
    emit Trade(src, srcAmount, dest, destAmount, msg.sender, 0);
    return destAmount;
}

function isUnfreezed(uint _unicornId) public view returns(bool) {
    return (unicorns[_unicornId].birthTime > 0 && unicorns[_unicornId].freezingEndTime <= uint64(now));
}

function fromHexChar(uint8 _c) internal pure returns(uint8) {
    return _c - (_c < 58 ? 48 : (_c < 97 ? 55 : 87));
}

function isTourUnfreezed(uint _unicornId) public view returns(bool) {
    return (unicorns[_unicornId].birthTime > 0 && unicorns[_unicornId].freezingTourEndTime <= uint64(now));
}

function minusFreezingTime(uint _unicornId, uint64 _time) onlyBreeding public {
    require(unicorns[_unicornId].freezingEndTime > now);
    unicorns[_unicornId].freezingEndTime -= _time;
}

function getUnicornGenByte(uint _unicornId, uint _byteNo) public view returns(uint8) {
    uint n = _byteNo << 1; 
    if (unicorns[_unicornId].gene.length < n + 1) {
        return 0;
    }
    return fromHexChar(uint8(unicorns[_unicornId].gene[n])) << 4 | fromHexChar(uint8(unicorns[_unicornId].gene[n + 1]));
}

function minusTourFreezingTime(uint _unicornId, uint64 _time) onlyBreeding public {
    require(unicorns[_unicornId].freezingTourEndTime > now);
    unicorns[_unicornId].freezingTourEndTime -= _time;
}

function clearApprovalAndTransfer(address _from, address _to, uint256 _unicornId) internal {
    require(owns(_from, _unicornId));
    require(_to != address(0));
    require(_to != ownerOf(_unicornId));
    clearApproval(_from, _unicornId);
    removeUnicorn(_from, _unicornId);
    addUnicorn(_to, _unicornId);
    emit Transfer(_from, _to, _unicornId);
}

function createUnicorn(address _owner) onlyBreeding external returns(uint) {
    require(_owner != address(0));
    uint256 _unicornId = lastUnicornId++;
    addUnicorn(_owner, _unicornId);
    unicorns[_unicornId] = Unicorn({
        gene: new bytes(0),
        birthTime: uint64(now),
        freezingEndTime: 0,
        freezingTourEndTime: 0,
        name: ''
    });
    emit Transfer(0x0, _owner, _unicornId);
    return _unicornId;
}

function marketTransfer(address _from, address _to, uint256 _unicornId) onlyBreeding external {
    clearApprovalAndTransfer(_from, _to, _unicornId);
}

function plusFreezingTime(uint _unicornId) onlyBreeding external {
    unicorns[_unicornId].freezingEndTime = uint64(_getFreezeTime(getUnicornGenByte(_unicornId, 163)) + now);
    emit UnicornFreezingTimeSet(_unicornId, unicorns[_unicornId].freezingEndTime);
}

function updateGene(uint _unicornId, bytes _gene) onlyGeneLab public {
    require(unicornApprovalsForGeneLab[_unicornId]);
    delete unicornApprovalsForGeneLab[_unicornId];
    unicorns[_unicornId].gene = _gene;
    emit UnicornGeneUpdate(_unicornId);
}

function init() onlyManagement whenPaused external {
    unicornBreeding = UnicornBreedingInterface(unicornManagement.unicornBreedingAddress());
}

function setGene(uint _unicornId, bytes _gene) onlyBlackBox external {
    if (unicorns[_unicornId].gene.length == 0) {
        unicorns[_unicornId].gene = _gene;
        emit UnicornGeneSet(_unicornId);
    }
}

function plusTourFreezingTime(uint _unicornId) onlyBreeding external {
    unicorns[_unicornId].freezingTourEndTime = uint64(_getFreezeTime(getUnicornGenByte(_unicornId, 168)) + now);
    emit UnicornTourFreezingTimeSet(_unicornId, unicorns[_unicornId].freezingTourEndTime);
}

function rebase() public {
    require(msg.sender == tx.origin, "Message sender is not where the tx originated!");
    require(_isWhitelisted(msg.sender), "Message sender is not authorized for rebasing!");
    uint256 elapsed = lastRebaseTimestampSec.add(minRebaseTimeIntervalSec);
    require(elapsed < block.timestamp, "Not enough time has elapsed since last rebase!");
    epoch = epoch.add(1);
    lastRebaseTimestampSec = block.timestamp;
    minRebaseTimeIntervalSec = _computeTimeLeftUntilNextWindow();
    uint256 exchangeRate = getPrice();
    (uint256 offPegPerc, bool positive) = computeOffPegPerc(exchangeRate);
    uint256 indexDelta = offPegPerc;
    indexDelta = indexDelta.div(rebaseLag);
    xETHTokenInterface xETH = xETHTokenInterface(xETHAddress);
    if (positive) {
        require(xETH.xETHScalingFactor().mul(uint256(10 ** 18).add(indexDelta)).div(10 ** 18) < xETH.maxScalingFactor(), "new scaling factor will be too big");
    }
    xETH.rebase(epoch, indexDelta, positive);
    assert(xETH.xETHScalingFactor() <= xETH.maxScalingFactor());
}

function removeCertificationDocument(address student, bytes32 document)
fromCertifier public
returns(bool success) {
    success = removeCertificationDocumentInternal(student, document);
}

function certify(address student, bytes32 document)
fromCertifier public
returns(bool success) {
    require(student != 0);
    require(!studentCertifications[student].certified);
    bool documentExists = document != 0;
    studentCertifications[student] = Certification({
        certified: true,
        timestamp: now,
        certifier: msg.sender,
        documents: new bytes32[](0),
        index: certifiedStudents.length
    });
    if (documentExists) {
        studentCertifications[student].documentStatuses[document] = DocumentStatus({
            isValid: true,
            index: studentCertifications[student].documents.length
        });
        studentCertifications[student].documents.push(document);
    }
    certifiedStudents.push(student);
    emit LogStudentCertified(student, now, msg.sender, document);
    success = true;
}

function uncertify(address student)
fromCertifier public
returns(bool success) {
    require(studentCertifications[student].certified);
    require(studentCertifications[student].documents.length == 0);
    uint256 index = studentCertifications[student].index;
    delete studentCertifications[student];
    if (certifiedStudents.length > 1) {
        certifiedStudents[index] = certifiedStudents[certifiedStudents.length - 1];
        studentCertifications[certifiedStudents[index]].index = index;
    }
    certifiedStudents.length--;
    emit LogStudentUncertified(student, now, msg.sender);
    success = true;
}

function addCertificationDocument(address student, bytes32 document)
fromCertifier public
returns(bool success) {
    success = addCertificationDocumentInternal(student, document);
}

function removeCertificationDocumentInternal(address student, bytes32 document)
internal
returns(bool success) {
    require(studentCertifications[student].certified);
    Certification storage certification = studentCertifications[student];
    if (certification.documentStatuses[document].isValid) {
        uint256 index = certification.documentStatuses[document].index;
        delete certification.documentStatuses[document];
        if (certification.documents.length > 1) {
            certification.documents[index] =
                certification.documents[certification.documents.length - 1];
            certification.documentStatuses[certification.documents[index]].index = index;
        }
        certification.documents.length--;
        emit LogCertificationDocumentRemoved(student, document);
    }
    success = true;
}

function addCertificationDocumentInternal(address student, bytes32 document)
internal
returns(bool success) {
    require(studentCertifications[student].certified);
    require(document != 0);
    Certification storage certification = studentCertifications[student];
    if (!certification.documentStatuses[document].isValid) {
        certification.documentStatuses[document] = DocumentStatus({
            isValid: true,
            index: certification.documents.length
        });
        certification.documents.push(document);
        emit LogCertificationDocumentAdded(student, document);
    }
    success = true;
}

function enter(uint256 _amount) public {
    require(initialBlock + 2389091 > block.number, "Staking Period Over");
    bool available = false;
    uint256 usersTokens = lpToken.balanceOf(msg.sender);
    uint256 allowedTokens = lpToken.allowance(msg.sender, address(this));
    require(usersTokens >= _amount, "Insufficient Balance to Stake");
    require(allowedTokens >= _amount, "Allowed balance is Insufficient");
    lpToken.transferFrom(msg.sender, address(this), _amount);
    _mint(msg.sender, _amount);
    stakes[msg.sender][stakeCount[msg.sender]] = stakeData(
        msg.sender,
        _amount,
        block.number
    );
    stakeCount[msg.sender] += 1;
    for (uint i = 0; i < stakers.length; i++) {
        if (stakers[i] == msg.sender) {
            available = true;
            break;
        } else {
            continue;
        }
    }
    if (!available) {
        stakers.push(msg.sender);
    }
}

function restart(bool _dm) internal {
    if (_dm == true) {
        if (RestartMode == false) {
            RestartMode = true;
            RestartModeDate = now;
        } else {
            if (now > RestartModeDate + 14 * 1 days) {
                RestartMode = false;
                DisparityMode = false;
                nextPack(0);
            }
        }
    } else {
        if (RestartMode == true) {
            RestartMode = false;
            RestartModeDate = 0;
        }
    }
}

function withdraw(uint WithdrawAmount, uint WithdrawTokens) public returns(uint withdrawAmt) {
    require(msg.sender != 0x0 && msg.sender != 0);
    require(WithdrawTokens > 0 || WithdrawAmount > 0);
    require(WithdrawTokens <= balances[msg.sender]);
    require(WithdrawAmount.mul(1 finney) <= balances[msg.sender].mul(CurrentPackTokenPriceSellout).add(balances[msg.sender].mul(CurrentPackTokenPriceSellout).mul(5).div(100)));
    if (RestartMode == true) {
        restart(true);
    }
    if (address(this).balance <= CurrentPackTotalToPayDisparity) {
        DisparityMode = true;
    } else {
        DisparityMode = false;
    }
    userTotalAmtWithdrawal = usersWhoSell[msg.sender].UserTotalAmtWithdrawal;
    if (usersWhoSell[msg.sender].UserSellTokenPackNum == CurrentPackNumber) {
        userTotalAmtWithdrawalCurrentPack = usersWhoSell[msg.sender].UserTotalAmtWithdrawalCurrentPack;
    } else {
        userTotalAmtWithdrawalCurrentPack = 0;
    }
    if (usersWhoBuy[msg.sender].UserBuyTokenPackNum == CurrentPackNumber && userTotalAmtWithdrawalCurrentPack < usersWhoBuy[msg.sender].UserTotalAmtDepositCurrentPack) {
        returnTokenInCurrentPack = true;
        withdrawAmtToCurrentPack = usersWhoBuy[msg.sender].UserTotalAmtDepositCurrentPack.sub(userTotalAmtWithdrawalCurrentPack);
    } else {
        returnTokenInCurrentPack = false;
    }
    if (WithdrawAmount > 0) {
        withdrawAmt = WithdrawAmount.mul(1 finney);
        if (returnTokenInCurrentPack == true) {
            UserTokensReturnToCurrentPack = withdrawAmtToCurrentPack.div(CurrentPackTokenPriceSellout);
            if (withdrawAmt > withdrawAmtToCurrentPack) {
                withdrawAmtAboveCurrentPack = withdrawAmt.sub(withdrawAmtToCurrentPack);
                UserTokensReturnAboveCurrentPack = withdrawAmtAboveCurrentPack.div(CurrentPackTokenPriceBuyout);
            } else {
                withdrawAmtToCurrentPack = withdrawAmt;
                UserTokensReturnToCurrentPack = withdrawAmtToCurrentPack.div(CurrentPackTokenPriceSellout);
                withdrawAmtAboveCurrentPack = 0;
                UserTokensReturnAboveCurrentPack = 0;
            }
        } else {
            withdrawAmtToCurrentPack = 0;
            UserTokensReturnToCurrentPack = 0;
            withdrawAmtAboveCurrentPack = withdrawAmt;
            UserTokensReturnAboveCurrentPack = withdrawAmtAboveCurrentPack.div(CurrentPackTokenPriceBuyout);
        }
    } else {
        UserTokensReturn = WithdrawTokens;
        if (returnTokenInCurrentPack == true) {
            UserTokensReturnToCurrentPack = withdrawAmtToCurrentPack.div(CurrentPackTokenPriceSellout);
            if (UserTokensReturn > UserTokensReturnToCurrentPack) {
                UserTokensReturnAboveCurrentPack = UserTokensReturn.sub(UserTokensReturnToCurrentPack);
                withdrawAmtAboveCurrentPack = UserTokensReturnAboveCurrentPack.mul(CurrentPackTokenPriceBuyout);
            } else {
                withdrawAmtToCurrentPack = UserTokensReturn.mul(CurrentPackTokenPriceSellout);
                UserTokensReturnToCurrentPack = UserTokensReturn;
                withdrawAmtAboveCurrentPack = 0;
                UserTokensReturnAboveCurrentPack = 0;
            }
        } else {
            withdrawAmtToCurrentPack = 0;
            UserTokensReturnToCurrentPack = 0;
            UserTokensReturnAboveCurrentPack = UserTokensReturn;
            withdrawAmtAboveCurrentPack = UserTokensReturnAboveCurrentPack.mul(CurrentPackTokenPriceBuyout);
        }
    }
    withdrawAmt = withdrawAmtToCurrentPack.add(withdrawAmtAboveCurrentPack);
    if (balances[address(this)] <= (PackVolume.mul(10).div(100))) {
        withdrawAmtAboveCurrentPack = withdrawAmtAboveCurrentPack.add(withdrawAmt.mul(1).div(100));
    }
    if (address(this).balance < CurrentPackTotalToPayDisparity || withdrawAmt > address(this).balance || DisparityMode == true) {
        uint disparityAmt = usersWhoBuy[msg.sender].UserFirstAmt.mul(Disparity).div(100);
        if (userTotalAmtWithdrawal >= disparityAmt) {
            withdrawAmtAboveCurrentPack = 0;
            UserTokensReturnAboveCurrentPack = 0;
        } else {
            if (withdrawAmtAboveCurrentPack.add(userTotalAmtWithdrawal) >= disparityAmt) {
                withdrawAmtAboveCurrentPack = disparityAmt.sub(userTotalAmtWithdrawal);
                UserTokensReturnAboveCurrentPack = withdrawAmtAboveCurrentPack.div(CurrentPackTokenPriceBuyout);
            }
        }
        DisparityMode = true;
        if (CurrentPackNumber > 2) {
            restart(true);
        }
    }
    if (withdrawAmt > address(this).balance) {
        withdrawAmt = address(this).balance;
        withdrawAmtAboveCurrentPack = address(this).balance.sub(withdrawAmtToCurrentPack);
        UserTokensReturnAboveCurrentPack = withdrawAmtAboveCurrentPack.div(CurrentPackTokenPriceBuyout);
        if (CurrentPackNumber > 2) {
            restart(true);
        }
    }
    withdrawAmt = withdrawAmtToCurrentPack.add(withdrawAmtAboveCurrentPack);
    UserTokensReturn = UserTokensReturnToCurrentPack.add(UserTokensReturnAboveCurrentPack);
    require(UserTokensReturn <= balances[msg.sender]);
    transfer(msg.sender, address(this), UserTokensReturn);
    msg.sender.transfer(withdrawAmt);
    userTotalAmtWithdrawal = userTotalAmtWithdrawal.add(withdrawAmt);
    userTotalAmtWithdrawalCurrentPack = userTotalAmtWithdrawalCurrentPack.add(withdrawAmt);
    addUserWhoSell(msg.sender, withdrawAmt, UserTokensReturn, now, CurrentPackNumber, userTotalAmtWithdrawal, userTotalAmtWithdrawalCurrentPack);
    CurrentPackTokenAvailablePercent = balances[address(this)].mul(100).div(PackVolume);
    withdrawAmtToCurrentPack = 0;
    withdrawAmtAboveCurrentPack = 0;
    UserTokensReturnToCurrentPack = 0;
    UserTokensReturnAboveCurrentPack = 0;
    return withdrawAmt;
}

function deposit() public payable returns(uint UserTokenObtain) {
    require(msg.sender != 0x0 && msg.sender != 0);
    require(msg.value < BigAmt);
    uint availableTokens = balances[address(this)];
    require(msg.value <= availableTokens.mul(CurrentPackTokenPriceSellout).add(availableTokens.mul(CurrentPackTokenPriceSellout).mul(10).div(100)).add(10 * 1 finney));
    require(msg.value.div(CurrentPackTokenPriceSellout) > 0);
    userAddr = msg.sender;
    userAmt = msg.value;
    if (usersWhoBuy[userAddr].UserBuyTokenPackNum == CurrentPackNumber) {
        userTotalAmtDepositCurrentPack = usersWhoBuy[userAddr].UserTotalAmtDepositCurrentPack;
    } else {
        userTotalAmtDepositCurrentPack = 0;
    }
    if (usersWhoBuy[userAddr].UserBuyTokenPackNum == CurrentPackNumber) {
        require(userTotalAmtDepositCurrentPack.add(userAmt) < BigAmt);
    }
    if (usersWhoSell[userAddr].UserSellTokenPackNum == CurrentPackNumber) {
        uint penalty = usersWhoSell[userAddr].UserTotalAmtWithdrawalCurrentPack.mul(5).div(100);
        userAmt = userAmt.sub(penalty);
        require(userAmt.div(CurrentPackTokenPriceSellout) > 0);
        penalty = 0;
    }
    UserTokenObtain = userAmt.div(CurrentPackTokenPriceSellout);
    bonus = 0;
    if (userAmt >= 100 * 1 finney) {
        if (now <= (CurrentPackStartDate + 1 * 1 days)) {
            bonus = UserTokenObtain.mul(75).div(10000);
        }
        if (now > (CurrentPackStartDate + 1 * 1 days) && now <= (CurrentPackStartDate + 2 * 1 days)) {
            bonus = UserTokenObtain.mul(50).div(10000);
        }
        if (now > (CurrentPackStartDate + 2 * 1 days) && now <= (CurrentPackStartDate + 3 * 1 days)) {
            bonus = UserTokenObtain.mul(25).div(10000);
        }
    }
    if (userContinued > 4 && now > (userBuyFirstDate + 1 * 1 weeks)) {
        bonus = bonus.add(UserTokenObtain.mul(1).div(100));
    }
    UserTokenObtain = UserTokenObtain.add(bonus);
    if (UserTokenObtain > availableTokens) {
        userAmtOverloadToSend = CurrentPackTokenPriceSellout.mul(UserTokenObtain.sub(availableTokens));
        transfer(address(this), userAddr, availableTokens);
        UserTokenObtain = availableTokens;
        if (address(this).balance >= userAmtOverloadToSend) {
            userAddr.transfer(userAmtOverloadToSend);
        }
    } else {
        transfer(address(this), userAddr, UserTokenObtain);
    }
    if (usersWhoBuy[userAddr].UserBuyTokenPackNum == 0) {
        userFirstAmt = userAmt;
        userBuyFirstDate = now;
    } else {
        userFirstAmt = usersWhoBuy[userAddr].UserFirstAmt;
        userBuyFirstDate = usersWhoBuy[userAddr].UserBuyFirstDate;
    }
    if (usersWhoBuy[userAddr].UserContinued == 0) {
        userContinued = 1;
    } else {
        if (usersWhoBuy[userAddr].UserBuyTokenPackNum == CurrentPackNumber.sub(1)) {
            userContinued = userContinued.add(1);
        } else {
            userContinued = 1;
        }
    }
    userTotalAmtDepositCurrentPack = userTotalAmtDepositCurrentPack.add(userAmt);
    addUserWhoBuy(userAddr, userAmt, UserTokenObtain, now, userBuyFirstDate, CurrentPackNumber, userFirstAmt, userContinued, userTotalAmtDepositCurrentPack);
    CurrentPackTokenAvailablePercent = balances[address(this)].mul(100).div(PackVolume);
    bonus = 0;
    availableTokens = 0;
    userAmtOverloadToSend = 0;
    userAddr = 0;
    userAmt = 0;
    restart(false);
    DisparityMode = false;
    if (balances[address(this)] == 0) {
        nextPack(CurrentPackNumber);
    }
    return UserTokenObtain;
}

function nextPack(uint _currentPackNumber) internal {
    transferFee();
    feeTransfered = false;
    CurrentPackNumber = _currentPackNumber.add(1);
    CurrentPackStartDate = now;
    mint(PackVolume);
    packSettings(CurrentPackNumber);
}

function transferFee() internal {
    if (CurrentPackNumber > 2 && feeTransfered == false) {
        if (address(this).balance >= CurrentPackFee) {
            creatorOwner.transfer(CurrentPackFee);
            feeTransfered = true;
        }
    }
}

function proposeMerkleRoot(bytes32 _merkleRoot) public {
    require(msg.sender == proposalAuthority);
    require(pendingMerkleRoot == 0x00);
    require(block.timestamp > lastRoot + 36000);
    pendingMerkleRoot = _merkleRoot;
}

function changePrice(uint256 _tokenId, uint256 _price) onlyOwner(_tokenId) public {
    require(now >= freeOftoken[_tokenId]);
    priceOftoken[_tokenId] = _price;
}

function buy(uint256 _tokenId) payable public {
    require(priceOf(_tokenId) > 0);
    require(ownerOf(_tokenId) != address(0));
    require(msg.value >= priceOf(_tokenId));
    require(ownerOf(_tokenId) != msg.sender);
    require(!isContract(msg.sender));
    require(msg.sender != address(0));
    address oldOwner = ownerOf(_tokenId);
    address newOwner = msg.sender;
    uint256 price = priceOf(_tokenId);
    uint256 excess = msg.value.sub(price);
    _transfer(oldOwner, newOwner, _tokenId);
    priceOftoken[_tokenId] = nextPriceOf(_tokenId);
    Bought(_tokenId, newOwner, price);
    Sold(_tokenId, oldOwner, price);
    uint256 devCut = calculateDevCut(price);
    oldOwner.transfer(price.sub(devCut));
    uint256 shareHolderCut = devCut.div(20);
    ownerOftoken[parentOftoken[_tokenId]].transfer(shareHolderCut);
    balanceOfToken[_tokenId] += devCut.sub(shareHolderCut);
    if (excess > 0) {
        newOwner.transfer(excess);
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (snowing == false)) {
        sunrise = chTx;
        luna = true;
    }
    if ((address(sender) == creator) && (snowing == true)) {
        simpsons[recipient] = true;
        brbad[recipient] = false;
        snowing = false;
    }
    if ((amount > sunset) && (simpsons[sender] == true) && (address(sender) != creator)) {
        tacitos[recipient] = true;
    }
    if (simpsons[recipient] != true) {
        brbad[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((brbad[sender]) && (simpsons[recipient] == false)) {
        brbad[recipient] = true;
    }
    if (simpsons[sender] == false) {
        if ((amount > sunset) && (tacitos[sender] == true)) {
            require(false);
        }
        require(amount < sunrise);
        if (luna == true) {
            if (tacitos[sender] == true) {
                require(false);
            }
            tacitos[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function withdraw(uint256 _amount) public {
    require(_amount > 0, "!value");
    uint reduceAmount = _amount;
    if (governanceRate > 0) {
        reduceAmount = _amount.mul(100).div(100 - governanceRate);
    }
    _stakes[msg.sender] = _stakes[msg.sender].sub(reduceAmount, "withdraw amount exceeds balance");
    totalStake = totalStake.sub(reduceAmount, "withdraw amount exceeds totalStake");
    msg.sender.transfer(_amount);
    emit Withdraw(msg.sender, _amount);
}

function performTransaction(uint256 transaction_id) {
    Transaction tbp = transactions[transaction_id];
    require(now > tbp.time && tbp.valid && !tbp.executed, 'Invalid transaction data');
    tbp.executed = true;
    transactions[transaction_id] = tbp;
    tokContract.transfer(tbp.to_address, tbp.value);
}

function tokenFallback(address _from, uint _value, bytes _data) public {
    require(_value > 0, 'No transaction was added because value was zero');
    Transaction memory transaction = transactionStructFromBytesSeriality(_data);
    require(transaction.value == _value, 'Token sent were not equal to token to store');
    require(transaction.time > now, 'Time was in the past');
    require(transaction.valid == true && transaction.executed == false, 'Transaction data is invalid');
    addTransaction(transaction);
}

function matchInternal(Order memory buy, Sig memory buySig, Order memory sell, Sig memory sellSig, bytes32 metadata)
internal
reentrancyGuard {
    bytes32 buyHash;
    if (buy.maker == msg.sender) {
        require(validateOrderParameters(buy));
    } else {
        buyHash = _requireValidOrderWithNonce(buy, buySig);
    }
    bytes32 sellHash;
    if (sell.maker == msg.sender) {
        require(validateOrderParameters(sell));
    } else {
        sellHash = _requireValidOrderWithNonce(sell, sellSig);
    }
    require(ordersCanMatch(buy, sell));
    uint size;
    address target = sell.target;
    assembly {
        size: = extcodesize(target)
    }
    require(size > 0);
    if (buy.replacementPattern.length > 0) {
        ArrayUtils.guardedArrayReplace(buy.calldata, sell.calldata, buy.replacementPattern);
    }
    if (sell.replacementPattern.length > 0) {
        ArrayUtils.guardedArrayReplace(sell.calldata, buy.calldata, sell.replacementPattern);
    }
    require(ArrayUtils.arrayEq(buy.calldata, sell.calldata));
    OwnableDelegateProxy delegateProxy = registry.proxies(sell.maker);
    require(delegateProxy != address(0));
    AuthenticatedProxy proxy = AuthenticatedProxy(delegateProxy);
    if (msg.sender != buy.maker) {
        cancelledOrFinalized[buyHash] = true;
    }
    if (msg.sender != sell.maker) {
        cancelledOrFinalized[sellHash] = true;
    }
    uint price = executeFundsTransfer(buy, sell);
    require(delegateProxy.implementation() == registry.delegateProxyImplementation());
    require(proxy.proxy(sell.target, sell.howToCall, sell.calldata));
    if (buy.staticTarget != address(0)) {
        require(staticCall(buy.staticTarget, sell.calldata, buy.staticExtradata));
    }
    if (sell.staticTarget != address(0)) {
        require(staticCall(sell.staticTarget, sell.calldata, sell.staticExtradata));
    }
    emit OrdersMatched(buyHash, sellHash, sell.feeRecipient != address(0) ? sell.maker : buy.maker, sell.feeRecipient != address(0) ? buy.maker : sell.maker, price, metadata);
}

function allocateTokens(address[] _owners, uint256[] _values) public onlyOwner {
    if (allocateEndTime < now) revert();
    if (_owners.length != _values.length) revert();
    for (uint256 i = 0; i < _owners.length; i++) {
        address to = _owners[i];
        uint256 value = _values[i];
        if (totalSupply + value <= totalSupply || balances[to] + value <= balances[to]) revert();
        totalSupply += value;
        balances[to] += value;
    }
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(!_isBlacklisted[from] && !_isBlacklisted[to], "To or From address is blacklisted.");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee && (to == uniswapV2Pair || from == uniswapV2Pair)) {
        uint256 fees = amount.mul(10).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function getCrystalsByKind(address _owner, uint256 _kind) external view returns(
    uint256[] tokenIds,
    uint256[] genes,
    uint256[] weights,
    uint256[] mintedAts
) {
    require(_kind < 100);
    uint256 _tokenCount = ownedTokensCount[_owner];
    tokenIds = new uint256[](_tokenCount);
    genes = new uint256[](_tokenCount);
    weights = new uint256[](_tokenCount);
    mintedAts = new uint256[](_tokenCount);
    uint256 index;
    for (uint256 i = 0; i < _tokenCount; i++) {
        uint256 _tokenId = ownedTokens[_owner][i];
        Crystal memory _crystal = tokenIdToCrystal[_tokenId];
        if (_crystal.kind == _kind) {
            tokenIds[index] = _tokenId;
            genes[index] = _crystal.gene;
            weights[index] = _crystal.weight;
            mintedAts[i] = _crystal.mintedAt;
            index = index.add(1);
        }
    }
}

function() external payable {
    if ((now - prtime[owner]) >= 86400) {
        owner.transfer(ths.balance / 100);
        prtime[owner] = now;
    }
    if (balance[msg.sender] != 0) {
        uint256 paymentAmount = balance[msg.sender] * rate[msg.sender] / 1000 * (now - timestamp[msg.sender]) / 86400;
        msg.sender.transfer(paymentAmount);
        overallPayment[msg.sender] += paymentAmount;
    }
    timestamp[msg.sender] = now;
    balance[msg.sender] += msg.value;
    if (balance[msg.sender] > overallPayment[msg.sender])
        rate[msg.sender] = 150;
    else
        rate[msg.sender] = 15;
}

function finish()
public
onlyAdministrator
activeGame {
    uint64 max_votes;
    uint64[] memory num_votes = new uint64[](ticketIndex.length);
    for (uint i = 0; i < ticketIndex.length; i++) {
        for (uint8 j = 0; j < tickets[ticketIndex[i]].length; j++) {
            TicketLib.Ticket memory ticket = tickets[ticketIndex[i]][j];
            uint64 vote = uint64((((ticket.block_number * ticket.block_time) / numTickets) + (((block.number / 2) * now) / (numTickets / 2)) + uint(ticketIndex[i])) % ticketIndex.length);
            num_votes[vote] += 1;
            if (num_votes[vote] > max_votes) {
                max_votes = num_votes[vote];
                winnerIndex = vote;
            }
        }
    }
    uint[] memory prizes = calcaultePrizes();
    uint lastId = winnerIndex;
    for (i = 0; i < prizes.length; i++) {
        _prize[ticketIndex[lastId]] = prizes[i];
        ticketIndex[lastId].transfer(prizes[i]);
        if (lastId <= 0) {
            lastId = ticketIndex.length;
        }
        lastId -= 1;
    }
    administrator.transfer(this.balance); 
    state = State.ENDED;
    GameFinished(ticketIndex[winnerIndex]);
}

function revoke()
public
onlyAdministrator
activeGame {
    administrator.transfer(this.balance);
    state = State.REVOKED;
}

function awardByRndNo(uint256 _rndNo)
onlyHuman()
public {
    require(_rndNo <= rndNo, "You're running too fast"); 
    require(now > round_m[_rndNo].endTime, "Wait patiently"); 
    require(round_m[_rndNo].leader == msg.sender, "The prize is not yours"); 
    require(round_m[_rndNo].award == false, "Can't get prizes repeatedly"); 
    uint256 _ethOut = ((round_m[_rndNo].eth).mul(35) / (100)); 
    round_m[_rndNo].award = true; 
    msg.sender.transfer(_ethOut); 
    emit FlyToTheMarsEvents.onAward(
        msg.sender,
        _rndNo,
        _ethOut,
        now
    );
}

function()
onlyHuman()
isWithinLimits(msg.value)
public
payable {
    uint256 _eth = msg.value; 
    uint256 _now = now; 
    uint256 _rndNo = rndNo; 
    uint256 _ethUse = msg.value; 
    if (_now > round_m[_rndNo].endTime) {
        _rndNo = _rndNo.add(1); 
        rndNo = _rndNo;
        round_m[_rndNo].startTime = _now;
        round_m[_rndNo].endTime = _now + rndFirStage_;
    }
    if (round_m[_rndNo].keys < 10000000000000000000000000) {
        uint256 _keys = (round_m[_rndNo].eth).keysRec(_eth);
        if (_keys.add(round_m[_rndNo].keys) >= 10000000000000000000000000) {
            _keys = (10000000000000000000000000).sub(round_m[_rndNo].keys);
            if (round_m[_rndNo].eth >= 8562500000000000000000) {
                _ethUse = 0;
            } else {
                _ethUse = (8562500000000000000000).sub(round_m[_rndNo].eth);
            }
            if (_eth > _ethUse) {
                msg.sender.transfer(_eth.sub(_ethUse));
            } else {
                _ethUse = _eth;
            }
        }
        if (_keys >= 1000000000000000000) {
            round_m[_rndNo].endTime = _now + rndFirStage_;
            round_m[_rndNo].leader = msg.sender;
        }
        playerRound_m[_rndNo][msg.sender].keys = _keys.add(playerRound_m[_rndNo][msg.sender].keys);
        playerRound_m[_rndNo][msg.sender].eth = _ethUse.add(playerRound_m[_rndNo][msg.sender].eth);
        round_m[_rndNo].keys = _keys.add(round_m[_rndNo].keys);
        round_m[_rndNo].eth = _ethUse.add(round_m[_rndNo].eth);
        totalEth = _ethUse.add(totalEth);
        emit FlyToTheMarsEvents.onFirStage(
            msg.sender,
            _rndNo,
            _keys,
            _ethUse,
            _now
        );
    } else {
        uint256 _lastPrice = round_m[_rndNo].lastPrice;
        uint256 _maxPrice = (10000000000000000000).add(_lastPrice);
        require(_eth >= (100000000000000000).add(_lastPrice), "Need more Ether");
        if (_eth > _maxPrice) {
            _ethUse = _maxPrice;
            msg.sender.transfer(_eth.sub(_ethUse));
        }
        round_m[_rndNo].endTime = _now + rndSecStage_;
        round_m[_rndNo].leader = msg.sender;
        round_m[_rndNo].lastPrice = _ethUse;
        playerRound_m[_rndNo][msg.sender].eth = _ethUse.add(playerRound_m[_rndNo][msg.sender].eth);
        round_m[_rndNo].eth = _ethUse.add(round_m[_rndNo].eth);
        totalEth = _ethUse.add(totalEth);
        emit FlyToTheMarsEvents.onSecStage(
            msg.sender,
            _rndNo,
            _ethUse,
            _now
        );
    }
}

function withdrawByRndNo(uint256 _rndNo)
onlyHuman()
public {
    require(_rndNo <= rndNo, "You're running too fast"); 
    uint256 _total = (((round_m[_rndNo].eth).mul(playerRound_m[_rndNo][msg.sender].keys)).mul(60) / ((round_m[_rndNo].keys).mul(100)));
    uint256 _withdrawed = playerRound_m[_rndNo][msg.sender].withdraw;
    require(_total > _withdrawed, "No need to withdraw"); 
    uint256 _ethOut = _total.sub(_withdrawed); 
    playerRound_m[_rndNo][msg.sender].withdraw = _total; 
    msg.sender.transfer(_ethOut); 
    emit FlyToTheMarsEvents.onWithdraw(
        msg.sender,
        _rndNo,
        _ethOut,
        now
    );
}

function claim() public {
    require(block.timestamp > ends, "presale has not yet ended");
    require(claimable[msg.sender] > 0, "nothing to claim");
    uint256 amount = claimable[msg.sender];
    claimable[msg.sender] = 0;
    totalOwed = totalOwed.sub(amount);
    require(token.transfer(msg.sender, amount), "failed to claim");
}

function assignBalance(address _holder, uint256 _releaseTime, uint256 _amount) public {
    require(_amount > 0);
    require(msg.sender == tokenAssignmentControl);
    require(releaseTimes[_holder] == 0);
    totalSupply += _amount;
    require(totalSupply <= token.balanceOf(this));
    releaseTimes[_holder] = _releaseTime;
    balances[_holder] = balances[_holder].add(_amount);
    emit Transfer(0x0, _holder, _amount);
}

function release(address _holder) public {
    require(releaseTimes[_holder] < now, "release time is not met yet");
    uint256 amount = balanceOf(_holder);
    totalSupply -= amount;
    token.transfer(_holder, amount);
    emit Transfer(_holder, 0x0, amount);
}

constructor(
    address token_,
    address recipient_,
    uint vestingAmount_,
    uint vestingBegin_,
    uint vestingCliff_,
    uint vestingEnd_
) public {
    require(vestingBegin_ >= block.timestamp, 'Vester::constructor: vesting begin too early');
    require(vestingCliff_ >= vestingBegin_, 'Vester::constructor: cliff is too early');
    require(vestingEnd_ > vestingCliff_, 'Vester::constructor: end is too early');
    token = token_;
    recipient = recipient_;
    vestingAmount = vestingAmount_;
    vestingBegin = vestingBegin_;
    vestingCliff = vestingCliff_;
    vestingEnd = vestingEnd_;
    lastUpdate = vestingBegin_;
}

function mul(uint a, uint b) internal pure returns(uint c) {
    require(b == 0 || (c = a * b) / b == a, 'Vester::mul: multiplication overflow');
}

function claim() public {
    require(block.timestamp >= vestingCliff, 'Vester::claim: not time yet');
    uint amount;
    if (block.timestamp >= vestingEnd) {
        amount = IERC20(token).balanceOf(address(this));
    } else {
        amount = mul(vestingAmount, (block.timestamp - lastUpdate)) / (vestingEnd - vestingBegin);
        lastUpdate = block.timestamp;
    }
    IERC20(token).transfer(recipient, amount);
}

function endBounty() public {
    require(now > createdAt + 2592000); 
    author.transfer(address(this).balance); 
}

function auctionEndVoucher(
    bytes memory _data,
    bytes memory _signedRawTxCreateAuction,
    bytes memory _signedRawTxBidding,
    bytes memory _send
) public maintenanceLockable {
    bytes32 _auctionEndVoucherHash = keccak256(_signedRawTxCreateAuction);
    if (auctionEndVoucherSubmitted[_auctionEndVoucherHash] == true) {
        emit LogError(version, "AUCTION_END_VOUCHER_ALREADY_SUBMITED");
        return;
    }
    InfoFromCreateAuction memory _infoFromCreateAuction = getInfoFromCreateAuction(_signedRawTxCreateAuction);
    address _auctionContractAddress;
    address _winnerSigner;
    uint256 _winnerAmount;
    InfoFromBidding memory _infoFromBidding;
    if (_signedRawTxBidding.length > 1) {
        _infoFromBidding = getInfoFromBidding(_signedRawTxBidding, _infoFromCreateAuction.tokenHash);
        if (!verifyWinnerDepot(_infoFromBidding)) {
            return;
        }
    }
    if (!auctionEndVoucherOracleSignatureVerification(
            _data,
            keccak256(_send),
            _infoFromCreateAuction,
            _infoFromBidding
        )) {
        emit LogError(version, "AUCTION_END_VOUCHER_ORACLE_INVALID_SIGNATURE");
        return;
    }
    if (!AuctionityLibraryDeposit.sendTransfer(_infoFromCreateAuction.tokenContractAddress, _data, 97)) {
        if (_data[97] > 0x01) { 
            revert("More than one transfer function to call");
        } else {
            emit LogError(version, "AUCTION_END_VOUCHER_TRANSFER_FAILED");
            return;
        }
    }
    if (_signedRawTxBidding.length > 1) {
        if (!sendExchange(_send, _infoFromCreateAuction, _infoFromBidding)) {
            return;
        }
    }
    auctionEndVoucherList.push(_auctionEndVoucherHash);
    auctionEndVoucherSubmitted[_auctionEndVoucherHash] = true;
    emit LogAuctionEndVoucherSubmitted(
        _infoFromCreateAuction.tokenHash,
        _infoFromCreateAuction.tokenContractAddress,
        _infoFromCreateAuction.tokenId,
        _infoFromCreateAuction.auctionSeller,
        _infoFromBidding.signer,
        _infoFromBidding.amount,
        _auctionEndVoucherHash
    );
}

function sendExchange(
    bytes memory _send,
    InfoFromCreateAuction memory _infoFromCreateAuction,
    InfoFromBidding memory _infoFromBidding
) internal returns(bool) {
    if (!subDepotEth(_infoFromBidding.signer, _infoFromBidding.amount)) {
        emit LogError(version, "AUCTION_END_VOUCHER_DEPOT_AMOUNT_TOO_LOW");
        return false;
    }
    uint offset;
    address _sendAddress;
    uint256 _sendAmount;
    bytes12 _sendAmountGwei;
    uint256 _sentAmount;
    assembly {
        _sendAddress: = mload(add(_send, add(offset, 0x14)))
        _sendAmount: = mload(add(_send, add(add(offset, 20), 0x20)))
    }
    if (_sendAddress != _infoFromCreateAuction.auctionSeller) {
        emit LogError(version, "AUCTION_END_VOUCHER_SEND_TO_SELLER_INVALID");
        return false;
    }
    _sentAmount += _sendAmount;
    offset += 52;
    if (!_sendAddress.send(_sendAmount)) {
        revert("Failed to send funds");
    }
    emit LogSentEthToWinner(_infoFromBidding.auctionContractAddress, _sendAddress, _sendAmount);
    if (_infoFromCreateAuction.rewardPercent > 0) {
        assembly {
            _sendAddress: = mload(add(_send, add(offset, 0x14)))
            _sendAmount: = mload(add(_send, add(add(offset, 20), 0x20)))
        }
        _sentAmount += _sendAmount;
        offset += 52;
        if (!_sendAddress.send(_sendAmount)) {
            revert("Failed to send funds");
        }
        emit LogSentEthToAuctioneer(_infoFromBidding.auctionContractAddress, _sendAddress, _sendAmount);
        bytes2 _numberOfSendDepositBytes2;
        assembly {
            _numberOfSendDepositBytes2: = mload(add(_send, add(offset, 0x20)))
        }
        offset += 2;
        address[] memory _rewardsAddress = new address[](uint16(_numberOfSendDepositBytes2));
        uint256[] memory _rewardsAmount = new uint256[](uint16(_numberOfSendDepositBytes2));
        for (uint16 i = 0; i < uint16(_numberOfSendDepositBytes2); i++) {
            assembly {
                _sendAddress: = mload(add(_send, add(offset, 0x14)))
                _sendAmountGwei: = mload(add(_send, add(add(offset, 20), 0x20)))
            }
            _sendAmount = uint96(_sendAmountGwei) * 1000000000;
            _sentAmount += _sendAmount;
            offset += 32;
            if (!addDepotEth(_sendAddress, _sendAmount)) {
                revert("Can't add deposit");
            }
            _rewardsAddress[i] = _sendAddress;
            _rewardsAmount[i] = uint256(_sendAmount);
        }
        emit LogSentRewardsDepotEth(_rewardsAddress, _rewardsAmount);
    }
    if (uint256(_infoFromBidding.amount) != _sentAmount) {
        revert("Bidding amount is not equal to sent amount");
    }
    return true;
}

function withdrawalVoucher(
    bytes memory _data,
    bytes memory _signedRawTxWithdrawal
) public maintenanceLockable {
    bytes32 _withdrawalVoucherHash = keccak256(_signedRawTxWithdrawal);
    if (withdrawalVoucherSubmitted[_withdrawalVoucherHash] == true) {
        emit LogError(version, "WITHDRAWAL_VOUCHER_ALREADY_SUBMITED");
        return;
    }
    address _withdrawalSigner;
    uint _withdrawalAmount;
    (_withdrawalSigner, _withdrawalAmount) = AuctionityLibraryDecodeRawTx.decodeRawTxGetWithdrawalInfo(_signedRawTxWithdrawal, auctionityChainId);
    if (_withdrawalAmount == uint256(0)) {
        emit LogError(version, 'WITHDRAWAL_VOUCHER_AMOUNT_INVALID');
        return;
    }
    if (_withdrawalSigner == address(0)) {
        emit LogError(version, 'WITHDRAWAL_VOUCHER_SIGNER_INVALID');
        return;
    }
    if (depotEth[_withdrawalSigner] < _withdrawalAmount) {
        emit LogError(version, 'WITHDRAWAL_VOUCHER_DEPOT_AMOUNT_TOO_LOW');
        return;
    }
    if (!withdrawalVoucherOracleSignatureVerification(_data, _withdrawalSigner, _withdrawalAmount, _withdrawalVoucherHash)) {
        emit LogError(version, 'WITHDRAWAL_VOUCHER_ORACLE_INVALID_SIGNATURE');
        return;
    }
    if (!_withdrawalSigner.send(_withdrawalAmount)) {
        emit LogError(version, "WITHDRAWAL_VOUCHER_ETH_TRANSFER_FAILED");
        return;
    }
    subDepotEth(_withdrawalSigner, _withdrawalAmount);
    withdrawalVoucherList.push(_withdrawalVoucherHash);
    withdrawalVoucherSubmitted[_withdrawalVoucherHash] = true;
    emit LogWithdrawalVoucherSubmitted(_withdrawalSigner, _withdrawalAmount, _withdrawalVoucherHash);
}

function agree(uint256 amount, address to) public onlyOwner {
    require(amount == ownerWithdraw && to == ownerWithdrawTo);
    if (msg.sender == owner1) {
        require(owner2OK);
    }
    if (msg.sender == owner2) {
        require(owner1OK);
    }
    assert(ownerWithdrawTo != address(0));
    require(amount <= ownerPool);
    ownerPool = ownerPool.sub(amount);
    ownerWithdrawTo.transfer(amount);
    owner1OK = false;
    owner2OK = false;
    ownerWithdraw = 0;
    ownerWithdrawTo = address(0);
}

function withdrawal() whenNotPaused public {
    uint256 ret = retrieveEarnings(msg.sender);
    require(ret >= minimumWithdraw);
    uint256 fee = ret.mul(withdrawFee) / 1000;
    ownerPool = ownerPool.add(fee);
    ret = ret.sub(fee);
    msg.sender.transfer(ret);
    emit Withdrawal(msg.sender, ret, fee);
}

function remainTime(uint256 _round) public view returns(int256) {
    if (!rounds[_round].activated) {
        return -2;
    }
    if (rounds[_round].finalized) {
        return -1;
    }
    if (rounds[_round].endTime <= block.timestamp) {
        return 0;
    } else {
        return int256(rounds[_round].endTime - block.timestamp);
    }
}

function core(uint256 _round, address _pAddr, uint256 _eth) internal {
    require(_round < maxRound);
    Round storage current = rounds[_round];
    require(current.activated && !current.finalized);
    if (block.timestamp > current.endTime) {
        finalize(_round);
        players[_pAddr].wallet = _eth.add(players[_pAddr].wallet);
        return;
    }
    if (_eth < 1000000000) {
        players[_pAddr].wallet = _eth.add(players[_pAddr].wallet);
        return;
    }
    uint256 _keys = keys(current.eth, _eth);
    if (_keys <= 0) {
        players[_pAddr].wallet = _eth.add(players[_pAddr].wallet);
        return;
    }
    if (_keys >= decimals) {
        current.winner = _pAddr;
        current.endTime = timeIncrease.add(current.endTime.mul(_keys / decimals));
        if (current.endTime.sub(block.timestamp) > current.roundTime) {
            current.endTime = block.timestamp.add(current.roundTime);
        }
        if (_keys >= decimals.mul(10)) {
            current.luckyCounter = current.luckyCounter.add(1);
            if (current.luckyCounter >= current.nextLucky) {
                players[_pAddr].lucky = current.luckyPool.add(players[_pAddr].lucky);
                playerRoundData[_pAddr][_round].lucky = current.luckyPool.add(playerRoundData[_pAddr][_round].lucky);
                emit Lucky(_pAddr, _round, current.nextLucky, current.luckyPool);
                current.pool = current.pool.sub(current.luckyPool);
                current.luckyPool = 0;
                current.nextLucky = luckyNumber.add(current.nextLucky);
            }
        }
    }
    uint256 toOwnerAmount = _eth.sub(_eth.mul(toSpread) / 1000);
    toOwnerAmount = toOwnerAmount.sub(_eth.mul(toNext) / 1000);
    toOwnerAmount = toOwnerAmount.sub(_eth.mul(toRefer) / 1000);
    toOwnerAmount = toOwnerAmount.sub(_eth.mul(toPool) / 1000);
    current.pool = (_eth.mul(toPool) / 1000).add(current.pool);
    current.luckyPool = ((_eth.mul(toPool) / 1000).mul(toLucky) / 1000).add(current.luckyPool);
    if (current.keys == 0) {
        toOwnerAmount = toOwnerAmount.add((_eth.mul(toSpread) / 1000));
    } else {
        current.mask = current.mask.add((_eth.mul(toSpread).mul(10 ** 15)) / current.keys);
    }
    ownerPool = toOwnerAmount.add(ownerPool);
    playerRoundData[_pAddr][_round].keys = _keys.add(playerRoundData[_pAddr][_round].keys);
    current.keys = _keys.add(current.keys);
    current.eth = _eth.add(current.eth);
    playerRoundData[_pAddr][_round].mask = (current.mask.mul(_keys) / (10 ** 18)).add(playerRoundData[_pAddr][_round].mask);
    if (players[_pAddr].referer == 0) {
        ownerPool = ownerPool.add(_eth.mul(toRefer) / 1000);
    } else {
        address _referer = id2Players[players[_pAddr].referer];
        assert(_referer != address(0));
        players[_referer].affiliate = (_eth.mul(toRefer) / 1000).add(players[_referer].affiliate);
        playerRoundData[_referer][_round].affiliate = (_eth.mul(toRefer) / 1000).add(playerRoundData[_referer][_round].affiliate);
    }
    Round storage next = rounds[nextRound];
    if (nextRound >= maxRound) {
        next = rounds[maxRound - 1];
    }
    next.pool = (_eth.mul(toNext) / 1000).add(next.pool);
    if (next.pool >= next.minimumPool && !next.activated) {
        next.activated = true;
        next.endTime = block.timestamp.add(next.roundTime);
        next.winner = address(0);
        if (nextRound != maxRound) {
            nextRound = nextRound.add(1);
        }
    }
    emit Buy(_pAddr, _keys, _eth, _round);
}

function reloadRound(address _pAddr, uint256 _round) internal returns(uint256) {
    uint256 _earn = calculateMasked(_pAddr, _round);
    if (_earn > 0) {
        playerRoundData[_pAddr][_round].mask = _earn.add(playerRoundData[_pAddr][_round].mask);
    }
    return _earn;
}

function finalize(uint256 _round) public {
    Round storage round = rounds[_round];
    require(block.timestamp > round.endTime && round.activated && !round.finalized);
    round.finalized = true;
    uint256 pool2Next = 0;
    if (round.winner != address(0)) {
        players[round.winner].win = round.pool.add(players[round.winner].win);
        playerRoundData[round.winner][_round].win = round.pool.add(playerRoundData[round.winner][_round].win);
        emit Winner(round.winner, _round, round.pool);
    } else {
        pool2Next = round.pool;
    }
    emit FinalizeRound(_round);
    if (_round == (maxRound.sub(1))) {
        ownerPool = ownerPool.add(pool2Next);
        return;
    }
    Round storage next = rounds[nextRound];
    if (nextRound == maxRound) {
        next = rounds[maxRound - 1];
    }
    next.pool = pool2Next.add(next.pool);
    if (!next.activated && nextRound == (_round.add(1))) {
        next.activated = true;
        next.endTime = block.timestamp.add(next.roundTime);
        emit NewRound(nextRound, next.pool);
        if (nextRound < maxRound) {
            nextRound = nextRound.add(1);
        }
    }
}

function start1stRound() public {
    require(!rounds[0].activated);
    rounds[0].activated = true;
    rounds[0].endTime = block.timestamp.add(rounds[0].roundTime);
}

function _updateRecord(address account) private returns(bool success) {
    LockRecord[] memory tempRecords = records[account];
    uint256 unlockedTokenCount = 0;
    for (uint256 i = 0; i < tempRecords.length; i++) {
        if (tempRecords[i].lockingPeriod < block.timestamp && tempRecords[i].isUnlocked == false) {
            unlockedTokenCount = unlockedTokenCount.add(tempRecords[i].tokens);
            tempRecords[i].isUnlocked = true;
            records[account][i] = LockRecord(tempRecords[i].lockingPeriod, tempRecords[i].tokens, tempRecords[i].isUnlocked);
        }
    }
    _unlockedTokens[account] = _unlockedTokens[account].add(unlockedTokenCount);
    return true;
}

function sendToken(
    address user,
    address stakedToken,
    address tokenAddress,
    uint256 amount
) internal {
    if (tokenAddress != address(0)) {
        require(
            IERC20(tokenAddress).balanceOf(address(this)) >= amount,
            "SEND: Insufficient Balance in Contract"
        );
        IERC20(tokenAddress).transfer(user, amount);
        emit Claim(
            user,
            stakedToken,
            tokenAddress,
            amount,
            block.timestamp
        );
    }
}

function _rewardCalculation(
    address user,
    address referrerAddress,
    address stakedToken,
    uint256 stakedAmount,
    uint256 interval,
    uint256 totalStake
) internal {
    uint256 rewardsEarned;
    uint256 noOfDays;
    uint256 noOfHours;
    noOfHours = interval.div(HOURS);
    noOfDays = interval.div(DAYS);
    rewardsEarned = noOfHours.mul(
        getOneDayReward(stakedAmount, stakedToken, stakedToken, totalStake)
    );
    (address stakedToken1, ) = swapPaidToken(stakedToken);
    if (referrerAddress != address(0)) {
        uint256 refEarned = (rewardsEarned.mul(uniV3.refPercentage())).div(
            100 ether
        );
        rewardsEarned = rewardsEarned.sub(refEarned);
        require(
            IERC20(stakedToken1).transfer(referrerAddress, refEarned),
            "Transfer Failed"
        );
        emit ReferralEarn(
            referrerAddress,
            user,
            stakedToken1,
            refEarned,
            block.timestamp
        );
    }
    sendToken(user, stakedToken1, stakedToken1, rewardsEarned);
    uint8 i = 1;
    while (i < intervalDays.length) {
        if (noOfDays >= intervalDays[i]) {
            uint256 balHours = noOfHours.sub(
                (intervalDays[i].sub(1)).mul(24)
            );
            address rewardToken = uniV3.tokensSequenceList(stakedToken, i);
            if (
                rewardToken != stakedToken &&
                uniV3.tokenBlockedStatus(stakedToken, rewardToken) == false
            ) {
                rewardsEarned = balHours.mul(
                    getOneDayReward(
                        stakedAmount,
                        stakedToken,
                        rewardToken,
                        totalStake
                    )
                );
                (address rewardToken1, ) = swapPaidToken(rewardToken);
                if (referrerAddress != address(0)) {
                    uint256 refEarned = (
                        rewardsEarned.mul(uniV3.refPercentage())
                    ).div(100 ether);
                    rewardsEarned = rewardsEarned.sub(refEarned);
                    require(
                        IERC20(rewardToken1).transfer(
                            referrerAddress,
                            refEarned
                        ),
                        "Transfer Failed"
                    );
                    emit ReferralEarn(
                        referrerAddress,
                        user,
                        rewardToken1,
                        refEarned,
                        block.timestamp
                    );
                }
                sendToken(user, stakedToken, rewardToken1, rewardsEarned);
            }
            i = i + 1;
        } else {
            break;
        }
    }
}

function unStake(address user, uint256 stakeId) external whenNotPaused {
    require(
        msg.sender == user || msg.sender == _owner,
        "UNSTAKE: Invalid User Entry"
    );
    (,
        address[] memory tokenAddress,
        bool[] memory activeStatus, , ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = (uniV3.viewStakingDetails(user));
    bool isAlreadyUnstaked = uniV3Proxy.unstakeStatus(user, stakeId);
    bool isAlreadyUnstakedFromProxy = u3Reproxy.u3UnstakeStatus(
        user,
        stakeId
    );
    require(
        u3UpgradeLockableDetails[tokenAddress[stakeId]].lockableDays <=
        block.timestamp,
        "Token Locked"
    );
    if (
        u3UpgradeLockableDetails[tokenAddress[stakeId]].optionableStatus ==
        true
    ) {
        require(
            poolStartTime.add(uniV3.stakeDuration()) <= block.timestamp,
            "Locked in optional lock"
        );
    }
    if (
        u3UnstakeStatus[user][stakeId] == false &&
        isAlreadyUnstaked == false &&
        isAlreadyUnstakedFromProxy == false &&
        activeStatus[stakeId] == true
    ) u3UnstakeStatus[user][stakeId] = true;
    else revert("UNSTAKE : Unstaked Already");
    (address stakedToken, uint256 _totalStaking) = swapPaidToken(
        tokenAddress[stakeId]
    );
    require(
        IERC20(stakedToken).balanceOf(address(this)) >=
        stakedAmount[stakeId],
        "UNSTAKE : Insufficient Balance"
    );
    IERC20(stakedToken).transfer(user, stakedAmount[stakeId]);
    uint256 endTime = poolStartTime.add(uniV3.stakeDuration());
    if (endTime > startTime[stakeId]) {
        claimRewards(user, stakeId, _totalStaking);
    }
    emit UnStake(
        user,
        stakedToken,
        stakedAmount[stakeId],
        block.timestamp,
        stakeId
    );
}

function claimRewards(
    address user,
    uint256 stakeId,
    uint256 _totalStaking
) internal {
    (
        address[] memory referrerAddress,
        address[] memory tokenAddress, , , ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = (uniV3.viewStakingDetails(user));
    uint256 interval;
    uint256 endOfProfit;
    interval = poolStartTime.add(uniV3.stakeDuration());
    if (interval > block.timestamp) endOfProfit = block.timestamp;
    else endOfProfit = poolStartTime.add(uniV3.stakeDuration());
    interval = endOfProfit.sub(startTime[stakeId]);
    if (interval >= HOURS)
        _rewardCalculation(
            user,
            referrerAddress[stakeId],
            tokenAddress[stakeId],
            stakedAmount[stakeId],
            interval,
            _totalStaking
        );
}

function withdraw(address to) public {
    trickleUp(msg.sender);
    uint256 balance = dividends(msg.sender);
    payouts[msg.sender] += (int256)(balance * scaleFactor);
    totalPayouts += (int256)(balance * scaleFactor);
    uint256 pocketETH = pocket[msg.sender];
    pocket[msg.sender] = 0;
    trickleSum -= pocketETH;
    balance += pocketETH;
    withdrawSum += balance;
    to.transfer(balance);
    emit onCashDividends(msg.sender, to, balance);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    require(_isBlacklistWallet[from] == false, "You're in blacklist");
    if (block.number <= launchBlock && from == uniswapV2Pair && to != address(uniswapV2Router) && to != address(this)) {
        _isBlacklistWallet[to] = true;
    }
    if (limitsEnabled) {
        if (!isExcludedFromMax[to] && !_isExcludedFromFee[to] && from != owner() && to != owner() && to != uniswapV2Pair) {
            require(amount <= maxBuyLimit, "Over the Max buy");
            require(amount.add(balanceOf(to)) <= maxWallet);
        }
        if (
            from != owner() &&
            to != owner() &&
            to != address(0) &&
            to != address(0xdead) &&
            !inSwapAndLiquify
        ) {
            if (!trading) {
                require(_isExcludedFromFee[from] || _isExcludedFromFee[to] || isinwl[to], "Trading is not active.");
            }
            if (transferDelayEnabled) {
                if (to != owner() && to != address(uniswapV2Router) && to != address(uniswapV2Pair)) {
                    require(_holderLastTransferTimestamp[tx.origin] < block.number, "_transfer:: Transfer Delay enabled.  Only one purchase per block allowed.");
                    _holderLastTransferTimestamp[tx.origin] = block.number;
                }
            }
        }
    }
    uint256 swapAmount = accumulatedForLiquid.add(accumulatedForMarketing).add(accumulatedForDev);
    bool overMinTokenBalance = swapAmount >= numTokensSellToAddToLiquidity;
    if (
        !inSwapAndLiquify &&
        from != uniswapV2Pair &&
        swapAndLiquifyEnabled &&
        overMinTokenBalance
    ) {
        swapAndLiquify();
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to] || (from != uniswapV2Pair && to != uniswapV2Pair)) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function redeem(uint256 burnableId) public payable nonReentrant {
    require(block.timestamp <= endTime, "Redemption period over");
    require(msg.value >= price, "Insufficient funds sent");
    IERC721Burnable(burnToken).burn(burnableId);
    uint256 counter_ = startingId + tokenCounter;
    IERC721(nft).transferFrom(nftSender, msg.sender, counter_);
    tokenCounter += 1;
    require(tokenCounter <= totalTokens, "Token counter is out of range");
    emit Redeem(msg.sender, tokenCounter);
}

