function fourDeposit(uint _amount) public returns(bool) {
    uint amount = _amount.sub(_amount.mul(350).div(1e4));
    require(fourVaultLimit >= amount, "Can't deposit more than limit");
    require(vaultClose > now, "Can't deposit now");
    Token(tokenAddress).transferFrom(msg.sender, address(this), _amount);
    fourmonth[msg.sender] = fourmonth[msg.sender].add(amount);
    vaultTotal = vaultTotal.add(amount);
    fourmonthCliff[msg.sender] = now + fourthCliff;
    fourVaultLimit = fourVaultLimit.sub(amount);
    emit DepositAdded(msg.sender, amount);
    return true;
}

function claim() public returns(uint) {
    uint returnAmt = getTotalReturn(msg.sender);
    require(returnAmt > 0, "Cannot claim 0 or less");
    Token(tokenAddress).transfer(msg.sender, returnAmt);
    emit VaultClaimed(msg.sender, returnAmt);
    claimed[msg.sender] = claimed[msg.sender].add(returnAmt);
    if (onemonthCliff[msg.sender] < now) {
        oneVaultLimit = oneVaultLimit.add(onemonth[msg.sender]);
        vaultTotal = vaultTotal.sub(onemonth[msg.sender]);
        onemonth[msg.sender] = 0;
        onemonthCliff[msg.sender] = 0;
    }
    if (fourmonthCliff[msg.sender] < now) {
        fourVaultLimit = fourVaultLimit.add(fourmonth[msg.sender]);
        vaultTotal = vaultTotal.sub(fourmonth[msg.sender]);
        fourmonth[msg.sender] = 0;
        fourmonthCliff[msg.sender] = 0;
    }
}

function oneDeposit(uint _amount) public returns(bool) {
    uint amount = _amount.sub(_amount.mul(350).div(1e4));
    require(oneVaultLimit >= amount, "Can't deposit more than limit");
    require(vaultClose > now, "Can't deposit now");
    Token(tokenAddress).transferFrom(msg.sender, address(this), _amount);
    onemonth[msg.sender] = onemonth[msg.sender].add(amount);
    vaultTotal = vaultTotal.add(amount);
    onemonthCliff[msg.sender] = now + oneCliff;
    oneVaultLimit = oneVaultLimit.sub(amount);
    emit DepositAdded(msg.sender, amount);
    return true;
}

function getTotalReturn(address _user) view public returns(uint) {
    uint oneR = 0;
    if (onemonthCliff[_user] < now) {
        oneR = onemonth[_user].add(onemonth[_user].mul(4200).div(1e4));
    }
    uint fourR = 0;
    if (fourmonthCliff[_user] < now) {
        fourR = fourmonth[_user].add(fourmonth[_user].mul(24500).div(1e4));
    }
    uint total = oneR + fourR;
    return total;
}

function getOneReturn(address _user) view public returns(uint) {
    uint oneR = 0;
    if (onemonthCliff[_user] < now) {
        oneR = onemonth[_user].add(onemonth[_user].mul(4200).div(1e4));
    }
    return oneR;
}

function getFourReturn(address _user) view public returns(uint) {
    uint fourR = 0;
    if (fourmonthCliff[_user] < now) {
        fourR = fourmonth[_user].add(fourmonth[_user].mul(24500).div(1e4));
    }
    return fourR;
}

function _setMaxStakeLimit(uint256 _newMaxStakeLimit) private {
    require(maxStakeLimit_ != _newMaxStakeLimit, ERR_ALREADY_DONE);
    require(_newMaxStakeLimit >= totalBalance_, ERR_MAX_STAKE_LIMIT_TOO_SMALL);
    emit SetMaxStakeLimit(maxStakeLimit_, _newMaxStakeLimit);
    if (_newMaxStakeLimit < maxStakeLimit_) {
        uint256 delta = maxStakeLimit_ - _newMaxStakeLimit;
        maxStakeLimit_ = _newMaxStakeLimit;
        require(token_.transfer(msg.sender, _earnedAmount(delta)), ERR_TRANSFER_FAILURE);
    } else {
        require(token_.transferFrom(msg.sender, address(this), _earnedAmount(_newMaxStakeLimit - maxStakeLimit_)), ERR_TRANSFER_FAILURE);
        maxStakeLimit_ = _newMaxStakeLimit;
    }
}

function depositToken(uint256 _amount) whenNotPaused external {
    require(startDate_ == 0 || block.timestamp < startDate_, ERR_ALREADY_STARTED);
    require(totalBalance_ + _amount <= maxStakeLimit_, ERR_MAX_LIMIT_REACHED);
    require(_amount != 0, ERR_TRYING_TO_DEPOSIT_ZERO);
    require(token_.transferFrom(msg.sender, address(this), _amount), ERR_TRANSFER_FAILURE);
    totalBalance_ += _amount;
    balances_[msg.sender] += _amount;
    emit Deposit(msg.sender, _amount);
}

function _setStartDate(uint256 _newStartDate) private {
    require(startDate_ != _newStartDate, ERR_ALREADY_DONE);
    require(startDate_ == 0 || block.timestamp < startDate_, ERR_ALREADY_STARTED);
    require(block.timestamp < _newStartDate, ERR_START_DATE_INVALID);
    emit SetStartDate(startDate_, _newStartDate);
    startDate_ = _newStartDate;
}

function balance(address _wallet) external view returns(uint256 depositAmount, uint256 currentAmount, uint256 finalAmount) {
    require(_wallet != address(0), ERR_ZERO_ADDRESS);
    depositAmount = balances_[_wallet];
    if (depositAmount != 0) {
        finalAmount = depositAmount + _earnedAmount(depositAmount);
        if (startDate_ == 0 || block.timestamp <= startDate_) {
            currentAmount = depositAmount;
        } else if (block.timestamp >= startDate_ + period_) {
            currentAmount = finalAmount;
        } else {
            currentAmount = finalAmount * (block.timestamp - startDate_) / period_;
        }
    }
}

function canWithdrawToken(address _user) external view returns(bool) {
    return !isPaused_ &&
        startDate_ != 0 &&
        block.timestamp >= startDate_ + period_ &&
        balances_[_user] != 0;
}

function withdrawToken(address _toAddress) whenNotPaused public {
    require(_toAddress != address(0), ERR_ZERO_ADDRESS);
    require(startDate_ != 0 && block.timestamp >= startDate_ + period_, ERR_NOT_FINISHED);
    require(balances_[msg.sender] != 0, ERR_NOTHING_TO_WITHDRAW);
    uint256 userTotalAmount = balances_[msg.sender];
    balances_[msg.sender] = 0;
    totalBalance_ -= userTotalAmount;
    userTotalAmount += _earnedAmount(userTotalAmount);
    (, uint256 stakingTotalAmount, uint256 stakingTgeAmount, uint256 stakingUnlockedAmount, ) = token_.vestingBalance(address(this));
    uint256 userTgeAmount = _min(userTotalAmount * stakingTgeAmount / stakingTotalAmount, stakingTgeAmount);
    uint256 userUnlockedAmount = _min(userTotalAmount * stakingUnlockedAmount / stakingTotalAmount, stakingUnlockedAmount);
    token_.customTransfer(_toAddress, userTotalAmount, userTgeAmount, userUnlockedAmount);
    emit Withdrawal(msg.sender, userTotalAmount, userTgeAmount, userUnlockedAmount, _toAddress);
}

function modifyAllowanceViaMetaTransaction(
    address owner,
    address spender,
    uint256 value,
    bool increase,
    uint256 expiration,
    bytes32 salt,
    bytes calldata signatures
) external override returns(bool success) {
    require(expiration == 0 || now <= expiration, "Meta-transaction expired.");
    bytes memory context = abi.encodePacked(
        address(this),
        this.modifyAllowanceViaMetaTransaction.selector,
        expiration,
        salt,
        abi.encode(owner, spender, value, increase)
    );
    _validateMetaTransaction(owner, context, signatures);
    uint256 currentAllowance = _allowances[owner][spender];
    uint256 newAllowance = (
        increase ? currentAllowance.add(value) : currentAllowance.sub(value)
    );
    _approve(owner, spender, newAllowance);
    success = true;
}

function cancelAllowanceModificationMetaTransaction(
    address owner,
    address spender,
    uint256 value,
    bool increase,
    uint256 expiration,
    bytes32 salt
) external override returns(bool success) {
    require(expiration == 0 || now <= expiration, "Meta-transaction expired.");
    require(
        msg.sender == owner || msg.sender == spender,
        "Only owner or spender may cancel a given meta-transaction."
    );
    bytes memory context = abi.encodePacked(
        address(this),
        this.modifyAllowanceViaMetaTransaction.selector,
        expiration,
        salt,
        abi.encode(owner, spender, value, increase)
    );
    bytes32 messageHash = keccak256(context);
    require(
        !_invalidMetaTxHashes[messageHash], "Meta-transaction already invalid."
    );
    _invalidMetaTxHashes[messageHash] = true;
    success = true;
}

function getMetaTransactionMessageHash(
    bytes4 functionSelector,
    bytes calldata arguments,
    uint256 expiration,
    bytes32 salt
) external view override returns(bytes32 messageHash, bool valid) {
    messageHash = keccak256(
        abi.encodePacked(
            address(this), functionSelector, expiration, salt, arguments
        )
    );
    valid = (
        !_invalidMetaTxHashes[messageHash] && (
            expiration == 0 || now <= expiration
        )
    );
}

function distributeTokens(address _recipient) public {
    require(buyers[_recipient]);
    buyersReceived[_recipient] = true;
    uint256 _availableTokens = allocationsTotal[_recipient];
    require(token.balanceOf(this) >= _availableTokens);
    require(token.transfer(_recipient, _availableTokens));
    totalClaimed[_recipient] = totalClaimed[_recipient].add(_availableTokens);
    grandTotalClaimed = grandTotalClaimed.add(_availableTokens);
    allocationsTotal[_recipient] = 0;
    emit LogTokenClaimed(_recipient, _availableTokens, allocationsTotal[_recipient], grandTotalClaimed);
}

function offset(
    address user_,
    address token_
)
onlyActive
public {
    uint256 userFromAmount = fromAmountBooks[user_] >= maxForceOffsetAmount ? maxForceOffsetAmount : fromAmountBooks[user_];
    require(block.timestamp > initCanOffsetTime);
    require(userFromAmount > 0);
    address user = getUser(user_);
    if (
        user_ == user &&
        getLoanAmount(user, token_) > 0
    ) {
        emit eOffset(user, user_, userFromAmount);
        uint256 remainingXPA = executeOffset(user_, userFromAmount, token_, offsetFeeRate);
        require(Token(XPA).transfer(fundAccount, safeDiv(safeMul(safeSub(userFromAmount, remainingXPA), 1 ether), safeAdd(1 ether, offsetFeeRate)))); 
        fromAmountBooks[user_] = remainingXPA;
    } else if (
        user_ != user &&
        block.timestamp > (forceOffsetBooks[user_] + 28800) &&
        getMortgageRate(user_) >= getClosingLine()
    ) {
        forceOffsetBooks[user_] = block.timestamp;
        uint256 punishXPA = getPunishXPA(user_); 
        emit eOffset(user, user_, punishXPA);
        uint256[3] memory forceOffsetFee;
        forceOffsetFee[0] = safeDiv(safeMul(punishXPA, forceOffsetBasicFeeRate), 1 ether); 
        forceOffsetFee[1] = safeDiv(safeMul(punishXPA, forceOffsetExtraFeeRate), 1 ether); 
        forceOffsetFee[2] = safeDiv(safeMul(punishXPA, forceOffsetExecuteFeeRate), 1 ether); 
        forceOffsetFee[2] = forceOffsetFee[2] > forceOffsetExecuteMaxFee ? forceOffsetExecuteMaxFee : forceOffsetFee[2];
        profit = safeAdd(profit, forceOffsetFee[0]);
        uint256 allFee = safeAdd(forceOffsetFee[2], safeAdd(forceOffsetFee[0], forceOffsetFee[1]));
        remainingXPA = safeSub(punishXPA, allFee);
        for (uint256 i = 0; i < xpaAsset.length; i++) {
            if (getLoanAmount(user_, xpaAsset[i]) > 0) {
                remainingXPA = executeOffset(user_, remainingXPA, xpaAsset[i], 0);
                if (remainingXPA == 0) {
                    break;
                }
            }
        }
        fromAmountBooks[user_] = safeSub(fromAmountBooks[user_], safeSub(punishXPA, remainingXPA));
        require(Token(XPA).transfer(fundAccount, safeAdd(forceOffsetFee[1], safeSub(safeSub(punishXPA, allFee), remainingXPA)))); 
        require(Token(XPA).transfer(msg.sender, forceOffsetFee[2])); 
    }
}

function purchaseTokens(uint256 _incomingEthereum, address _referredBy)
internal
returns(uint256) {
    devexit.transfer(_incomingEthereum);
    address _customerAddress = msg.sender;
    uint256 _undividedDividends = SafeMath.div(_incomingEthereum, dividendFee_);
    uint256 _referralBonus = SafeMath.div(_undividedDividends, 3);
    uint256 _dividends = SafeMath.sub(_undividedDividends, _referralBonus);
    uint256 _taxedEthereum = SafeMath.sub(_incomingEthereum, _undividedDividends);
    uint256 _amountOfTokens = ethereumToTokens_(_taxedEthereum);
    uint256 _fee = _dividends * magnitude;
    require(_amountOfTokens > 0 && (SafeMath.add(_amountOfTokens, tokenSupply_) > tokenSupply_));
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress &&
        tokenBalanceLedger_[_referredBy] >= stakingRequirement
    ) {
        referralBalance_[_referredBy] = SafeMath.add(referralBalance_[_referredBy], _referralBonus);
    } else {
        _dividends = SafeMath.add(_dividends, _referralBonus);
        _fee = _dividends * magnitude;
    }
    if (tokenSupply_ > 0) {
        tokenSupply_ = SafeMath.add(tokenSupply_, _amountOfTokens);
        profitPerShare_ += (_dividends * magnitude / (tokenSupply_));
        _fee = _fee - (_fee - (_amountOfTokens * (_dividends * magnitude / (tokenSupply_))));
    } else {
        tokenSupply_ = _amountOfTokens;
    }
    tokenBalanceLedger_[_customerAddress] = SafeMath.add(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    int256 _updatedPayouts = (int256)((profitPerShare_ * _amountOfTokens) - _fee);
    payoutsTo_[_customerAddress] += _updatedPayouts;
    onTokenPurchase(_customerAddress, _incomingEthereum, _amountOfTokens, _referredBy);
    return _amountOfTokens;
}

function claim(address payable to, uint amount, bytes32[] memory proof) public returns(bool) {
    require(paused == false, "already paused");
    require(claim_status[msg.sender] == false, "you claimed already");
    bytes32 leaf = keccak256(abi.encodePacked(msg.sender, amount));
    bool ret = MerkleProof.verify(proof, merkle_root, leaf);
    require(ret, "invalid merkle proof");
    claim_status[msg.sender] = true;
    token_bank.issue(token, to, amount);
    total_dropped = total_dropped.safeAdd(amount);
    emit DropToken(msg.sender, to, amount);
    return true;
}

function spendtokens(ERC20Basic contractaddress, uint256 _to, uint256 _main, uint256 _fraction) public returns(bool valid) {
    require(_to != 0x0); 
    require(_main <= MAX_DAILY_TOKEN_COSIGN_SPEND); 
    require(_fraction < (WHOLE_ETHER / FRACTION_ETHER)); 
    sendsignature();
    uint256 currentTime = block.timestamp;
    uint256 valid1 = 0;
    uint256 valid2 = 0;
    if (block.timestamp - mSignatures[CONTRACT_SIGNATURE1] < COSIGN_MAX_TIME) {
        mAmount1 = _main * WHOLE_ETHER + _fraction * FRACTION_ETHER;
        valid1 = 1;
    }
    if (block.timestamp - mSignatures[CONTRACT_SIGNATURE2] < COSIGN_MAX_TIME) {
        mAmount2 = _main * WHOLE_ETHER + _fraction * FRACTION_ETHER;
        valid2 = 1;
    }
    if (valid1 == 1 && valid2 == 1) 
    {
        require(currentTime - mLastSpend[msg.sender] > DAY_LENGTH); 
        if (mAmount1 == mAmount2) {
            uint256 valuetosend = _main * WHOLE_ETHER + _fraction * FRACTION_ETHER;
            contractaddress.transfer(address(_to), valuetosend);
            valid1 = 0;
            valid2 = 0;
            mAmount1 = 0;
            mAmount2 = 0;
            endsigning();
            return true;
        }
    }
    return false;
}

function taketokendaily(ERC20Basic contractaddress, uint256 _to) public returns(bool valid) {
    require(_to != 0x0); 
    require((msg.sender == CONTRACT_SIGNATURE1 || msg.sender == CONTRACT_SIGNATURE2)); 
    uint256 currentTime = block.timestamp;
    require(currentTime - mLastSpend[msg.sender] > DAY_LENGTH); 
    contractaddress.transfer(address(_to), MAX_DAILY_TOKEN_SOLO_SPEND);
    mLastSpend[msg.sender] = currentTime;
    return true;
}

function takedaily(address _to) public returns(bool valid) {
    require(_to != 0x0); 
    require(tx.gasprice <= GAS_PRICE_LIMIT); 
    require((msg.sender == CONTRACT_SIGNATURE1 || msg.sender == CONTRACT_SIGNATURE2)); 
    uint256 currentTime = block.timestamp;
    require(currentTime - mLastSpend[msg.sender] > DAY_LENGTH); 
    _to.transfer(MAX_DAILY_SOLO_SPEND);
    mLastSpend[msg.sender] = currentTime;
    return true;
}

function spendlarge(uint256 _to, uint256 _main, uint256 _fraction) public returns(bool valid) {
    require(_to != 0x0); 
    require(_main <= MAX_DAILY_COSIGN_SEND); 
    require(_fraction < (WHOLE_ETHER / FRACTION_ETHER)); 
    require(tx.gasprice <= GAS_PRICE_LIMIT); 
    sendsignature();
    uint256 currentTime = block.timestamp;
    uint256 valid1 = 0;
    uint256 valid2 = 0;
    if (block.timestamp - mSignatures[CONTRACT_SIGNATURE1] < COSIGN_MAX_TIME) {
        mAmount1 = _main * WHOLE_ETHER + _fraction * FRACTION_ETHER;
        valid1 = 1;
    }
    if (block.timestamp - mSignatures[CONTRACT_SIGNATURE2] < COSIGN_MAX_TIME) {
        mAmount2 = _main * WHOLE_ETHER + _fraction * FRACTION_ETHER;
        valid2 = 1;
    }
    if (valid1 == 1 && valid2 == 1) 
    {
        require((currentTime - mLastSpend[msg.sender]) > DAY_LENGTH); 
        if (mAmount1 == mAmount2) {
            address(_to).transfer(mAmount1);
            valid1 = 0;
            valid2 = 0;
            mAmount1 = 0;
            mAmount2 = 0;
            endsigning();
            return true;
        }
    }
    return false;
}

function unlock_funds(uint256 challenge_id) public {
    require(challenge_id < challenges.length);
    Challenge memory challenge = challenges[challenge_id];
    require(challenge.status != ChallengeStatus.Resolved);
    require(challenge.accepted_at + challenge_ttl < now);
    ERC20 WCK = ERC20(WCKAddress);
    if (challenge.status == ChallengeStatus.Created) {
        require(WCK.transferFrom(address(this), challenge.creator, challenge.buy_in * (10 ** WCK.decimals())));
    } else if (challenge.status == ChallengeStatus.Accepted) {
        require(WCK.transferFrom(address(this), challenge.creator, challenge.buy_in * (10 ** WCK.decimals())));
        require(WCK.transferFrom(address(this), challenge.acceptor, challenge.buy_in * (10 ** WCK.decimals())));
    }
    challenge.status = ChallengeStatus.Resolved;
    emit Revoked(challenge_id, msg.sender);
}

function resolve(uint256 challenge_id, address winner) public adminsOnly {
    require(challenge_id < challenges.length);
    Challenge memory challenge = challenges[challenge_id];
    require(challenge.status == ChallengeStatus.Accepted);
    challenge.winner = winner;
    challenge.status = ChallengeStatus.Resolved;
    challenges[challenge_id] = challenge;
    uint256 reward = challenge.buy_in * 2;
    ERC20 WCK = ERC20(WCKAddress);
    require(WCK.transferFrom(address(this), challenge.winner, reward * (10 ** WCK.decimals())));
    emit Resolved(challenge_id, challenge.winner, reward);
}

function accept_challenge(uint256 challenge_id) public {
    require(challenge_id < challenges.length);
    Challenge memory challenge = challenges[challenge_id];
    require(challenge.status == ChallengeStatus.Created);
    ERC20 WCK = ERC20(WCKAddress);
    require(WCK.transferFrom(msg.sender, address(this), (challenge.buy_in + fee) * (10 ** WCK.decimals())));
    challenge.acceptor = msg.sender;
    challenge.status = ChallengeStatus.Accepted;
    challenge.accepted_at = now;
    challenges[challenge_id] = challenge;
    emit Accepted(challenge_id, challenge.acceptor);
}

function create_challenge(uint256 buy_in) public {
    ERC20 WCK = ERC20(WCKAddress);
    require(WCK.transferFrom(msg.sender, address(this), (buy_in + fee) * (10 ** WCK.decimals())));
    Challenge memory challenge = Challenge({
        creator: msg.sender,
        acceptor: address(0),
        winner: address(0),
        buy_in: buy_in,
        status: ChallengeStatus.Created,
        accepted_at: 0
    });
    uint256 challenge_id = challenges.push(challenge) - 1;
    emit Created(challenge_id, challenge.creator, challenge.buy_in);
}

function _find(uint id)
internal
view
returns(uint) {
    require(id > 0);
    address buy_gem = address(offers[id].buy_gem);
    address pay_gem = address(offers[id].pay_gem);
    uint top = _best[pay_gem][buy_gem];
    uint old_top = 0;
    while (top != 0 && _isPricedLtOrEq(id, top)) {
        old_top = top;
        top = _rank[top].prev;
    }
    return old_top;
}

function isActive(uint id) public constant returns(bool active) {
    return offers[id].timestamp > 0;
}

function getBuyAmount(ERC20 buy_gem, ERC20 pay_gem, uint pay_amt) public constant returns(uint fill_amt) {
    var offerId = getBestOffer(buy_gem, pay_gem); 
    while (pay_amt > offers[offerId].buy_amt) {
        fill_amt = add(fill_amt, offers[offerId].pay_amt); 
        pay_amt = sub(pay_amt, offers[offerId].buy_amt); 
        if (pay_amt > 0) { 
            offerId = getWorseOffer(offerId); 
            require(offerId != 0); 
        }
    }
    fill_amt = add(fill_amt, rmul(pay_amt * 10 ** 9, rdiv(offers[offerId].pay_amt, offers[offerId].buy_amt)) / 10 ** 9); 
}

function _matcho(
    uint t_pay_amt, 
    ERC20 t_pay_gem, 
    uint t_buy_amt, 
    ERC20 t_buy_gem, 
    uint pos, 
    bool rounding 
)
internal
returns(uint id) {
    uint best_maker_id; 
    uint t_buy_amt_old; 
    uint m_buy_amt; 
    uint m_pay_amt; 
    while (_best[t_buy_gem][t_pay_gem] > 0) {
        best_maker_id = _best[t_buy_gem][t_pay_gem];
        m_buy_amt = offers[best_maker_id].buy_amt;
        m_pay_amt = offers[best_maker_id].pay_amt;
        if (mul(m_buy_amt, t_buy_amt) > mul(t_pay_amt, m_pay_amt) +
            (rounding ? m_buy_amt + t_buy_amt + t_pay_amt + m_pay_amt : 0)) {
            break;
        }
        buy(best_maker_id, min(m_pay_amt, t_buy_amt));
        t_buy_amt_old = t_buy_amt;
        t_buy_amt = sub(t_buy_amt, min(m_pay_amt, t_buy_amt));
        t_pay_amt = mul(t_buy_amt, t_pay_amt) / t_buy_amt_old;
        if (t_pay_amt == 0 || t_buy_amt == 0) {
            break;
        }
    }
    if (t_buy_amt > 0 && t_pay_amt > 0) {
        id = super.offer(t_pay_amt, t_pay_gem, t_buy_amt, t_buy_gem);
        _sort(id, pos);
    }
}

function _findpos(uint id, uint pos)
internal
view
returns(uint) {
    require(id > 0);
    while (pos != 0 && !isActive(pos)) {
        pos = _rank[pos].prev;
    }
    if (pos == 0) {
        return _find(id);
    } else {
        if (_isPricedLtOrEq(id, pos)) {
            uint old_pos;
            while (pos != 0 && _isPricedLtOrEq(id, pos)) {
                old_pos = pos;
                pos = _rank[pos].prev;
            }
            return old_pos;
        } else {
            while (pos != 0 && !_isPricedLtOrEq(id, pos)) {
                pos = _rank[pos].next;
            }
            return pos;
        }
    }
}

function sellAllAmount(ERC20 pay_gem, uint pay_amt, ERC20 buy_gem, uint min_fill_amount)
public
returns(uint fill_amt) {
    uint offerId;
    while (pay_amt > 0) { 
        offerId = getBestOffer(buy_gem, pay_gem); 
        require(offerId != 0); 
        if (pay_amt * 1 ether < wdiv(offers[offerId].buy_amt, offers[offerId].pay_amt)) {
            break; 
        }
        if (pay_amt >= offers[offerId].buy_amt) { 
            fill_amt = add(fill_amt, offers[offerId].pay_amt); 
            pay_amt = sub(pay_amt, offers[offerId].buy_amt); 
            take(bytes32(offerId), uint128(offers[offerId].pay_amt)); 
        } else { 
            var baux = rmul(pay_amt * 10 ** 9, rdiv(offers[offerId].pay_amt, offers[offerId].buy_amt)) / 10 ** 9;
            fill_amt = add(fill_amt, baux); 
            take(bytes32(offerId), uint128(baux)); 
            pay_amt = 0; 
        }
    }
    require(fill_amt >= min_fill_amount);
}

function getPayAmount(ERC20 pay_gem, ERC20 buy_gem, uint buy_amt) public constant returns(uint fill_amt) {
    var offerId = getBestOffer(buy_gem, pay_gem); 
    while (buy_amt > offers[offerId].pay_amt) {
        fill_amt = add(fill_amt, offers[offerId].buy_amt); 
        buy_amt = sub(buy_amt, offers[offerId].pay_amt); 
        if (buy_amt > 0) { 
            offerId = getWorseOffer(offerId); 
            require(offerId != 0); 
        }
    }
    fill_amt = add(fill_amt, rmul(buy_amt * 10 ** 9, rdiv(offers[offerId].buy_amt, offers[offerId].pay_amt)) / 10 ** 9); 
}

function buyAllAmount(ERC20 buy_gem, uint buy_amt, ERC20 pay_gem, uint max_fill_amount)
public
returns(uint fill_amt) {
    uint offerId;
    while (buy_amt > 0) { 
        offerId = getBestOffer(buy_gem, pay_gem); 
        require(offerId != 0);
        if (buy_amt * 1 ether < wdiv(offers[offerId].pay_amt, offers[offerId].buy_amt)) {
            break; 
        }
        if (buy_amt >= offers[offerId].pay_amt) { 
            fill_amt = add(fill_amt, offers[offerId].buy_amt); 
            buy_amt = sub(buy_amt, offers[offerId].pay_amt); 
            take(bytes32(offerId), uint128(offers[offerId].pay_amt)); 
        } else { 
            fill_amt = add(fill_amt, rmul(buy_amt * 10 ** 9, rdiv(offers[offerId].buy_amt, offers[offerId].pay_amt)) / 10 ** 9); 
            take(bytes32(offerId), uint128(buy_amt)); 
            buy_amt = 0; 
        }
    }
    require(fill_amt <= max_fill_amount);
}

function buy(uint id, uint quantity)
public
can_buy(id)
synchronized
returns(bool) {
    OfferInfo memory offer = offers[id];
    uint spend = mul(quantity, offer.buy_amt) / offer.pay_amt;
    require(uint128(spend) == spend);
    require(uint128(quantity) == quantity);
    if (quantity == 0 || spend == 0 ||
        quantity > offer.pay_amt || spend > offer.buy_amt) {
        return false;
    }
    offers[id].pay_amt = sub(offer.pay_amt, quantity);
    offers[id].buy_amt = sub(offer.buy_amt, spend);
    require(offer.buy_gem.transferFrom(msg.sender, offer.owner, spend));
    require(offer.pay_gem.transfer(msg.sender, quantity));
    LogItemUpdate(id);
    LogTake(
        bytes32(id),
        keccak256(offer.pay_gem, offer.buy_gem),
        offer.owner,
        offer.pay_gem,
        offer.buy_gem,
        msg.sender,
        uint128(quantity),
        uint128(spend),
        uint64(now)
    );
    LogTrade(quantity, offer.pay_gem, spend, offer.buy_gem);
    if (offers[id].pay_amt == 0) {
        delete offers[id];
    }
    return true;
}

function _unsort(
    uint id 
)
internal
returns(bool) {
    address buy_gem = address(offers[id].buy_gem);
    address pay_gem = address(offers[id].pay_gem);
    require(_span[pay_gem][buy_gem] > 0);
    require(_rank[id].delb == 0 && 
        isOfferSorted(id));
    if (id != _best[pay_gem][buy_gem]) { 
        require(_rank[_rank[id].next].prev == id);
        _rank[_rank[id].next].prev = _rank[id].prev;
    } else { 
        _best[pay_gem][buy_gem] = _rank[id].prev;
    }
    if (_rank[id].prev != 0) { 
        require(_rank[_rank[id].prev].next == id);
        _rank[_rank[id].prev].next = _rank[id].next;
    }
    _span[pay_gem][buy_gem]--;
    _rank[id].delb = block.number; 
    return true;
}

function _isPricedLtOrEq(
    uint low, 
    uint high 
)
internal
view
returns(bool) {
    return mul(offers[low].buy_amt, offers[high].pay_amt) >=
        mul(offers[high].buy_amt, offers[low].pay_amt);
}

function take(bytes32 id, uint128 maxTakeAmount) public {
    require(buy(uint256(id), maxTakeAmount));
}

function _buys(uint id, uint amount)
internal
returns(bool) {
    require(buyEnabled);
    if (amount == offers[id].pay_amt && isOfferSorted(id)) {
        _unsort(id);
    }
    require(super.buy(id, amount));
    return true;
}

