function cancelJobByProvider(bytes32 _jobId)
public
returns(bool) {
    require(_jobId[0] != 0);
    require(jobs[_jobId].status == JobStatus.New);
    require(jobs[_jobId].provider == msg.sender);
    require(cancelEscrowByProvider(jobs[_jobId].escrowId));
    jobs[_jobId].status = JobStatus.Cancelled;
    emit OnCancelJobByProvider(dApp, _jobId);
    return true;
}

function cancelEscrow(uint256 _escrowId, uint256 _payToProviderAmount, address arbiter, uint256 _payToArbiterAmount)
internal
returns(bool) {
    require(escrows[_escrowId].status == EscrowStatus.New);
    require(_payToProviderAmount >= 0 && _payToArbiterAmount >= 0);
    require(escrows[_escrowId].amount >= escrows[_escrowId].paidToDappAmount.add(_payToArbiterAmount).add(_payToProviderAmount));
    escrows[_escrowId].status = EscrowStatus.Cancelled;
    escrows[_escrowId].closedAt = block.number;
    if (_payToArbiterAmount > 0) {
        require(arbiter != address(0));
        escrows[_escrowId].paidToArbiterAmount = _payToArbiterAmount;
        require(escrowToken.transfer(arbiter, _payToArbiterAmount));
    }
    if (_payToProviderAmount > 0) {
        escrows[_escrowId].paidToProviderAmount = _payToProviderAmount;
        require(escrowToken.transfer(escrows[_escrowId].provider, _payToProviderAmount));
    }
    uint256 totalPaid = escrows[_escrowId].paidToDappAmount.add(_payToArbiterAmount).add(_payToProviderAmount);
    escrows[_escrowId].paidToClientAmount = escrows[_escrowId].amount.sub(totalPaid);
    if (escrows[_escrowId].paidToClientAmount > 0) {
        require(escrowToken.transfer(escrows[_escrowId].client, escrows[_escrowId].paidToClientAmount));
    }
    emit OnCancelEscrow(escrowDapp, _escrowId, _payToProviderAmount, arbiter, _payToArbiterAmount);
    return true;
}

function cancelJobByAdmin(bytes32 _jobId, uint256 _payToProviderAmount, address _arbiter, uint256 _payToArbiterAmount)
public
returns(bool) {
    require(_jobId[0] != 0);
    require(jobs[_jobId].status == JobStatus.New);
    require(canworkAdmin.hasRole(msg.sender, ROLE_ADMIN));
    uint maxArbiterPayment = jobs[_jobId].amount.mul(5).div(100);
    require(_payToArbiterAmount <= maxArbiterPayment);
    require(cancelEscrow(jobs[_jobId].escrowId, _payToProviderAmount, _arbiter, _payToArbiterAmount));
    jobs[_jobId].status = JobStatus.Cancelled;
    emit OnCancelJobByAdmin(dApp, _jobId, _payToProviderAmount, _arbiter, _payToArbiterAmount);
    return true;
}

function completeJob(bytes32 _jobId)
public
returns(bool) {
    require(_jobId[0] != 0);
    require(jobs[_jobId].status == JobStatus.New);
    require(jobs[_jobId].client == msg.sender);
    require(completeEscrow(jobs[_jobId].escrowId));
    jobs[_jobId].status = JobStatus.Completed;
    emit OnCompleteJob(dApp, _jobId);
    return true;
}

function createEscrow(address _client, address _provider, uint256 _amount, uint256 _payToDappAmount)
internal
returns(uint256) {
    require(_client != address(0) && _provider != address(0) && _amount > 0 && _payToDappAmount >= 0);
    require(escrowToken.transferFrom(_client, address(this), _amount));
    uint256 id = ++escrowId;
    EscrowRecord storage escrow = escrows[id];
    escrow.id = id;
    escrow.client = _client;
    escrow.provider = _provider;
    escrow.amount = _amount;
    escrow.createdAt = block.number;
    escrow.status = EscrowStatus.New;
    escrow.paidToProviderAmount = 0;
    escrow.paidToClientAmount = 0;
    escrow.paidToArbiterAmount = 0;
    if (_payToDappAmount > 0) {
        escrow.paidToDappAmount = _payToDappAmount;
        require(escrowToken.transfer(escrowDapp, _payToDappAmount));
    }
    emit OnCreateEscrow(escrowDapp, _client, _provider, _amount, _payToDappAmount);
    return id;
}

function setFeeAuthority(FeeInterface newSource) public auth {
    fees = newSource;
}

function confirmReceivedAt(uint index)
public
onlyBroker
inState(State.Locked) {
    if (index >= buyinfo.length)
        return;
    if (buyinfo[index].completed)
        return;
    seller.transfer(item.price - brokerFee - developerfee);
    broker.transfer(brokerFee);
    developer.transfer(developerfee);
    buyinfo[index].completed = true;
    emit IndividualItemReceived(buyinfo[index].buyer);
}

function returnMoneyToBuyers()
private {
    require(state != State.Finished);
    if (buyinfo.length > 0) {
        uint val = address(this).balance / buyinfo.length;
        for (uint256 x = 0; x < buyinfo.length; x++) {
            if (buyinfo[x].completed == false) {
                buyinfo[x].buyer.transfer(val);
            }
        }
    }
    state = State.Finished;
}

function confirmPurchase()
public
condition(msg.value == item.price)
payable {
    if (bBrokerRequired) {
        if (state != State.Validated || state != State.Locked) {
            return;
        }
    }
    if (state == State.Finished) {
        return;
    }
    state = State.Locked;
    emit PurchaseConfirmed(msg.sender);
    bool complete = false;
    if (!bBrokerRequired) {
        complete = true;
        seller.transfer(item.price - developerfee);
        developer.transfer(developerfee);
    }
    buyinfo.push(BuyInfo(msg.sender, complete));
}

function abortByBroker()
public
onlyBroker {
    if (!bBrokerRequired)
        return;
    returnMoneyToBuyers();
    emit AbortedByBroker();
}

function abort()
public
onlySeller {
    returnMoneyToBuyers();
    emit AbortedBySeller();
    seller.transfer(address(this).balance);
}

function incurDebt(uint256 _amount, address _token) external override {
    uint256 value;
    if (_token == address(Stax)) {
        require(permissions[STATUS.StaxDEBTOR][msg.sender], notApproved);
        value = _amount;
    } else {
        require(permissions[STATUS.RESERVEDEBTOR][msg.sender], notApproved);
        require(permissions[STATUS.RESERVETOKEN][_token], notAccepted);
        value = tokenValue(_token, _amount);
    }
    require(value != 0, invalidToken);
    sStax.changeDebt(value, msg.sender, true);
    require(sStax.debtBalances(msg.sender) <= debtLimit[msg.sender], "Treasury: exceeds limit");
    totalDebt = totalDebt.add(value);
    if (_token == address(Stax)) {
        Stax.mint(msg.sender, value);
        StaxDebt = StaxDebt.add(value);
    } else {
        totalReserves = totalReserves.sub(value);
        IERC20(_token).safeTransfer(msg.sender, _amount);
    }
    emit CreateDebt(msg.sender, _token, _amount, value);
}

function withdraw(uint256 _amount, address _token) external override {
    require(permissions[STATUS.RESERVETOKEN][_token], notAccepted); 
    require(permissions[STATUS.RESERVESPENDER][msg.sender], notApproved);
    uint256 value = tokenValue(_token, _amount);
    Stax.burnFrom(msg.sender, value);
    totalReserves = totalReserves.sub(value);
    IERC20(_token).safeTransfer(msg.sender, _amount);
    emit Withdrawal(_token, _amount, value);
}

function repayDebtWithStax(uint256 _amount) external {
    require(permissions[STATUS.RESERVEDEBTOR][msg.sender] || permissions[STATUS.StaxDEBTOR][msg.sender], notApproved);
    Stax.burnFrom(msg.sender, _amount);
    sStax.changeDebt(_amount, msg.sender, false);
    totalDebt = totalDebt.sub(_amount);
    StaxDebt = StaxDebt.sub(_amount);
    emit RepayDebt(msg.sender, address(Stax), _amount, _amount);
}

function deposit(
    uint256 _amount,
    address _token,
    uint256 _profit
) external override returns(uint256 send_) {
    if (permissions[STATUS.RESERVETOKEN][_token]) {
        require(permissions[STATUS.RESERVEDEPOSITOR][msg.sender], notApproved);
    } else if (permissions[STATUS.LIQUIDITYTOKEN][_token]) {
        require(permissions[STATUS.LIQUIDITYDEPOSITOR][msg.sender], notApproved);
    } else {
        revert(invalidToken);
    }
    IERC20(_token).safeTransferFrom(msg.sender, address(this), _amount);
    uint256 value = tokenValue(_token, _amount);
    send_ = value.sub(_profit);
    Stax.mint(msg.sender, send_);
    totalReserves = totalReserves.add(value);
    emit Deposit(_token, _amount, value);
}

function repayDebtWithReserve(uint256 _amount, address _token) external override {
    require(permissions[STATUS.RESERVEDEBTOR][msg.sender], notApproved);
    require(permissions[STATUS.RESERVETOKEN][_token], notAccepted);
    IERC20(_token).safeTransferFrom(msg.sender, address(this), _amount);
    uint256 value = tokenValue(_token, _amount);
    sStax.changeDebt(value, msg.sender, false);
    totalDebt = totalDebt.sub(value);
    totalReserves = totalReserves.add(value);
    emit RepayDebt(msg.sender, _token, _amount, value);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    if (_to != address(this)) {
        return super.transfer(_to, _value);
    }
    require(_value <= balances_[msg.sender] && status == 0 && gameTime == 0);
    balances_[msg.sender] = balances_[msg.sender].sub(_value);
    totalSupply_ = totalSupply_.sub(_value);
    uint256 weiAmount = price.mul(_value);
    msg.sender.transfer(weiAmount);
    emit Transfer(msg.sender, _to, _value);
    emit Sell(_to, msg.sender, _value, weiAmount);
    return true;
}

function() payable public {
    require(status == 0 && price > 0 && gameTime > block.timestamp);
    uint256 amount = msg.value.div(price);
    balances_[msg.sender] = balances_[msg.sender].add(amount);
    totalSupply_ = totalSupply_.add(amount);
    emit Transfer(address(this), msg.sender, amount);
    emit Buy(address(this), msg.sender, amount, msg.value);
}

function advanceAndRedeemMax(address _user, uint256 _epoch, uint256 _targetEpoch) external useCHI {
    uint256 targetEpochStartTime = getEpochStartTime(_targetEpoch);
    if (block.timestamp < targetEpochStartTime) {
        return;
    }
    if (ESDS.epoch() != _targetEpoch) {
        ESDS.advance();
    }
    uint256 totalRedeemable = ESDS.totalRedeemable();
    uint256 userBalance = ESDS.balanceOfCoupons(_user, _epoch);
    uint256 maxRedeemableAmount = totalRedeemable < userBalance ? totalRedeemable : userBalance;
    _redeem(_user, _epoch, maxRedeemableAmount);
}

