    uint256 invested = msg.value;
    uint256 numberOfTokens = invested.mul(price);
    beneficiary.transfer(msg.value);
    token.transfer(msg.sender, numberOfTokens);
    raisedETH = raisedETH.add(msg.value);
    soldTokens = soldTokens.add(numberOfTokens);
    emit BoughtTokens(msg.sender, numberOfTokens, invested);
}

function send(address target, uint256 amount) {
    if (!target.send(amount)) throw;
    LogFundsSent(target, amount);
}

function end() public {
    require(!ended, "end already called");
    require(winning != address(0), "no bids");
    require(!live(), "Auction live");
    IERC721(token).safeTransferFrom(address(seller), winning, id); 
    uint256 balance = address(this).balance;
    uint256 hausFee = balance.div(20);
    haus.transfer(hausFee);
    seller.transfer(address(this).balance);
    ended = true;
    emit Won(winning, lastBid);
}

function bid() public payable {
    require(blacklistedBidders[msg.sender] == false, "blacklisted address");
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= startTime, "Auction not started");
    require(block.timestamp < endTime, "Auction ended");
    require(msg.value >= lastBid.mul(102).div(100), "Bid too small"); 
    if (winning != address(0)) {
        winning.transfer(lastBid);
    }
    if (endTime - now < 15 minutes) {
        endTime = now + 15 minutes;
    }
    lastBid = msg.value;
    winning = msg.sender;
    emit Bid(msg.sender, msg.value);
}

function settleBet(uint reveal, uint clean_commit) external {
    uint commit = uint(keccak256(abi.encodePacked(reveal)));
    Bet storage bet = bets[commit];
    uint amount = bet.amount;
    uint modulo = bet.modulo;
    uint rollUnder = bet.rollUnder;
    uint placeBlockNumber = bet.placeBlockNumber;
    address gambler = bet.gambler;
    require(amount != 0);
    require(block.number > placeBlockNumber);
    require(block.number <= placeBlockNumber + BET_EXPIRATION_BLOCKS);
    bet.amount = 0;
    bytes32 entropy = keccak256(abi.encodePacked(reveal, blockhash(placeBlockNumber)));
    uint dice = uint(entropy) % modulo;
    uint diceWinAmount = getDiceWinAmount(amount, modulo, rollUnder);
    uint diceWin = 0;
    uint jackpotWin = 0;
    if (modulo <= MAX_MASK_MODULO) {
        if ((2 ** dice) & bet.mask != 0) {
            diceWin = diceWinAmount;
        }
    } else {
        if (dice < rollUnder) {
            diceWin = diceWinAmount;
        }
    }
    lockedInBets -= uint128(diceWinAmount);
    if (amount >= MIN_JACKPOT_BET) {
        uint jackpotRng = (uint(entropy) / modulo) % JACKPOT_MODULO;
        if (jackpotRng == 0) {
            jackpotWin = jackpotSize;
            jackpotSize = 0;
        }
    }
    uint totalWin = diceWin + jackpotWin;
    if (totalWin == 0) {
        totalWin = 1 wei;
    }
    if (jackpotWin > 0) {
        emit JackpotPayment(gambler, jackpotWin);
    }
    sendFunds(gambler, totalWin, diceWin);
    if (clean_commit == 0) {
        return;
    }
    clearProcessedBet(clean_commit);
}

