            diceWin = diceWinAmount;
        }
    }
    lockedInBets -= uint128(diceWinAmount);
    if (amount >= MIN_JACKPOT_BET) {
        uint jackpotRng = (uint(entropy) / modulo) % JACKPOT_MODULO;
        if (jackpotRng == 0) {
            jackpotWin = jackpotSize;
            jackpotSize = 0;
        }
    }
    if (jackpotWin > 0) {
        emit JackpotPayment(gambler, jackpotWin);
    }
    sendFunds(gambler, diceWin + jackpotWin == 0 ? 1 wei : diceWin + jackpotWin, diceWin);
    if (cleanCommit == 0) {
        return;
    }
    clearProcessedBet(cleanCommit);
}

function _reAdjustDifficulty() internal {
    uint timeTarget = 188; 
    if (epochCount > 28) {
        uint i = 0;
        uint sumD = 0;
        uint sumST = 0; 
        uint solvetime;
        for (i = epochCount.sub(28); i < epochCount; i++) {
            sumD = sumD.add(targetForEpoch[i]);
            solvetime = timeStampForEpoch[i] - timeStampForEpoch[i - 1];
            if (solvetime > timeTarget.mul(7)) {
                solvetime = timeTarget.mul(7);
            }
            sumST += solvetime; 
        }
        sumST = sumST.mul(10000).div(2523).add(1260); 
        miningTarget = sumD.mul(60).div(sumST); 
    }
    latestDifficultyPeriodStarted = block.number;
    if (miningTarget < _MINIMUM_TARGET) 
    {
        miningTarget = _MINIMUM_TARGET;
    }
    if (miningTarget > _MAXIMUM_TARGET) 
    {
        miningTarget = _MAXIMUM_TARGET;
    }
    targetForEpoch[epochCount] = miningTarget;
}

function mint(uint256 nonce, bytes32 challenge_digest) public returns(bool success) {
    bytes32 digest = keccak256(challengeNumber, msg.sender, nonce);
    if (digest != challenge_digest) revert();
    if (uint256(digest) > miningTarget) revert();
    bytes32 solution = solutionForChallenge[challengeNumber];
    solutionForChallenge[challengeNumber] = digest;
    if (solution != 0x0) revert(); 
    uint reward_amount = getMiningReward(digest);
    balances[msg.sender] = balances[msg.sender].add(reward_amount);
    _totalSupply = _totalSupply.add(reward_amount);
    lastRewardTo = msg.sender;
    lastRewardAmount = reward_amount;
    lastRewardEthBlockNumber = block.number;
    _startNewMiningEpoch();
    emit Mint(msg.sender, reward_amount, epochCount, challengeNumber);
    return true;
}

function _getYear(uint256 timestamp)
internal
pure
returns(uint16) {
    uint16 ORIGIN_YEAR = 1970;
    uint256 YEAR_IN_SECONDS = 31536000;
    uint256 LEAP_YEAR_IN_SECONDS = 31622400;
    uint secondsAccountedFor = 0;
    uint16 year;
    uint numLeapYears;
    year = uint16(ORIGIN_YEAR + timestamp / YEAR_IN_SECONDS);
    numLeapYears = _leapYearsBefore(year) - _leapYearsBefore(ORIGIN_YEAR);
    secondsAccountedFor += LEAP_YEAR_IN_SECONDS * numLeapYears;
    secondsAccountedFor += YEAR_IN_SECONDS * (year - ORIGIN_YEAR - numLeapYears);
    while (secondsAccountedFor > timestamp) {
        if (_isLeapYear(uint16(year - 1))) {
            secondsAccountedFor -= LEAP_YEAR_IN_SECONDS;
        } else {
            secondsAccountedFor -= YEAR_IN_SECONDS;
        }
        year -= 1;
    }
    return year;
}

function mint(
    address _to
)
onlyOwner
external
returns(bool) {
    uint16 year = _getYear(now);
    require(year >= mintStartYear && year <= mintEndYear && !minted[year]);
    require(_to != address(0));
    totalSupply_ = totalSupply_.add(yearlyMintCap);
    balances[_to] = balances[_to].add(yearlyMintCap);
    minted[year] = true;
    emit Mint(_to, yearlyMintCap);
    emit Transfer(address(0), _to, yearlyMintCap);
    return true;
}

function _isLeapYear(uint16 year)
internal
pure
returns(bool) {
    if (year % 4 != 0) {
        return false;
    }
    if (year % 100 != 0) {
        return true;
    }
    if (year % 400 != 0) {
        return false;
    }
    return true;
}

function calcBalanceLockedOfInboundRule(TransferRuleInbound memory trInbound) internal view returns(uint) {
    if (trInbound.timelockUntil > uint32(block.timestamp)) {
        return trInbound.tokens;
    }
    if (trInbound.percUnlockedAtTimeUnlock > 0) {
        trInbound.tokens -= uint96(trInbound.tokens * trInbound.percUnlockedAtTimeUnlock / PERC_BASE);
    }
    if (trInbound.vestingDurationDays > 0) {
        uint256 daysPassedSinceUnlock = (uint32(block.timestamp) - trInbound.timelockUntil) / SECONDS_IN_ONE_DAY;
        if (daysPassedSinceUnlock <= trInbound.vestingStartsAfterDays) {
            return trInbound.tokens;
        }
        uint256 daysPassedSinceVestingStart = daysPassedSinceUnlock - trInbound.vestingStartsAfterDays;
        if (daysPassedSinceVestingStart >= trInbound.vestingDurationDays) {
            return 0;
        }
        uint256 amountUnlockedPerDay = trInbound.tokens / trInbound.vestingDurationDays;
        uint256 totalUnlocked = daysPassedSinceVestingStart * amountUnlockedPerDay;
        return trInbound.tokens - totalUnlocked;
    }
    return 0;
}

function registerTransferRule(
    address account_,
    TransferRuleType ruleType,
    uint32 timelockUntil_,
    uint16 vestingStartsAfterDays_,
    uint16 vestingDurationDays_,
    uint16 percUnlockedAtTimeUnlock_,
    bool isPool_
) public onlyOwner {
    require(account_ != address(0), 'account is address zero');
    require(timelockUntil_ > uint32(block.timestamp), 'timelockUntil already passed');
    require(percUnlockedAtTimeUnlock_ > 0 || vestingDurationDays_ > 0, 'percUnlockedAtTimeUnlock and vestingDurationDays are zero');
    require(percUnlockedAtTimeUnlock_ <= uint16(PERC_BASE), 'percUnlockedAtTimeUnlock above 100%');
    if (ruleType == TransferRuleType.outbound) {
        require(transferRulesOutbound[account_].id == 0, 'account already has outbound rule');
        transferRulesOutbound[account_] = TransferRuleOutbound({
            id: uint8(++ruleIdCounter), 
            timelockUntil: timelockUntil_,
            vestingDurationDays: vestingDurationDays_,
            vestingStartsAfterDays: vestingStartsAfterDays_,
            percUnlockedAtTimeUnlock: percUnlockedAtTimeUnlock_
        });
        emit TransferRuleOutboundRegistered(account_, transferRulesOutbound[account_]);
    } else { 
        transferRulesInbound[account_].push(TransferRuleInbound({
            id: uint8(++ruleIdCounter), 
            timelockUntil: timelockUntil_,
            vestingDurationDays: vestingDurationDays_,
            vestingStartsAfterDays: vestingStartsAfterDays_,
            percUnlockedAtTimeUnlock: percUnlockedAtTimeUnlock_,
            tokens: 0,
            isPool: isPool_
        }));
        emit TransferRuleInboundRegistered(account_, transferRulesInbound[account_][transferRulesInbound[account_].length - 1]);
    }
}

function _beforeTokenTransfer(address from_, address to_, uint256 amount_) internal virtual {
    require(amount_ <= calcBalanceUnlocked(from_), "insufficient unlocked tokens");
    if (transferRulesInbound[to_].length >= 1 && transferRulesInbound[to_][0].isPool) {
        transferRulesInbound[to_][0].tokens += uint96(amount_);
        return;
    }
    if (transferRulesOutbound[from_].id != 0) {
        TransferRuleOutbound memory trFromOutbound = transferRulesOutbound[from_];
        bool foundMatchingToRule = false;
        for (uint256 i = 0; i < transferRulesInbound[to_].length; i++) {
            if (trFromOutbound.id == transferRulesInbound[to_][i].id) {
                foundMatchingToRule = true;
                transferRulesInbound[to_][i].tokens += uint96(amount_);
                break;
            }
        }
        if (!foundMatchingToRule) {
            transferRulesInbound[to_].push(TransferRuleInbound({
                id: trFromOutbound.id,
                timelockUntil: trFromOutbound.timelockUntil,
                vestingStartsAfterDays: trFromOutbound.vestingStartsAfterDays,
                vestingDurationDays: trFromOutbound.vestingDurationDays,
                percUnlockedAtTimeUnlock: trFromOutbound.percUnlockedAtTimeUnlock,
                tokens: uint96(amount_),
                isPool: false
            }));
        }
    }
}

function withdraw(address payable _to, uint256 _tokenId, uint256 _supportEther, bytes32 _eventHash) public payable whenNotPaused() onlyOperator() {
    require(!isTransactedEventHash(_eventHash), "_eventHash is already transacted");
    if (assetContract.isAlreadyMinted(_tokenId)) {
        assetContract.safeTransferFrom(address(this), _to, _tokenId);
    } else {
        assetContract.mintCardAsset(_to, _tokenId);
    }
    setTransactedEventHash(_eventHash, true);
    if (_supportEther != 0) {
        _to.transfer(_supportEther);
    }
    emit Withdraw(msg.sender, _tokenId, _supportEther, _eventHash);
}

function isTransferAllowed(address trans_from, uint amt) internal returns(bool) {
    for (uint i = 0; i < listofVest.length; i++) {
        if (listofVest[i].vestAddress == trans_from) {
            if (now <= listofVest[i].vestTill) {
                if ((balanceOf(trans_from).sub(amt) < listofVest[i].vestTokensLimit)) {
                    return false;
                }
            }
        }
    }
    return true;
}

function redeemClaim(address _protocol, uint256 _hackTime, uint256 _amount)
external
doKeep {
    bytes32 hackId = keccak256(abi.encodePacked(_protocol, _hackTime));
    require(confirmedHacks[hackId], "No hack with these parameters has been confirmed.");
    (uint256 planIndex, bool covered) = IPlanManager(getModule("PLAN")).checkCoverage(msg.sender, _protocol, _hackTime, _amount);
    require(covered, "User does not have cover for hack");
    IPlanManager(getModule("PLAN")).planRedeemed(msg.sender, planIndex, _protocol);
    msg.sender.transfer(_amount);
    emit ClaimPayout(hackId, msg.sender, _amount);
}

function executeProposal(uint proposalNumber, bytes transactionBytecode) public {
    Proposal storage p = proposals[proposalNumber];
    require(now > p.minExecutionDate 
        &&
        !p.executed 
        &&
        p.proposalHash == keccak256(abi.encodePacked(p.recipient, p.amount, transactionBytecode))); 
    uint quorum = 0;
    uint yea = 0;
    uint nay = 0;
    for (uint i = 0; i < p.votes.length; ++i) {
        Vote storage v = p.votes[i];
        uint voteWeight = sharesTokenAddress.balanceOf(v.voter);
        quorum += voteWeight;
        if (v.inSupport) {
            yea += voteWeight;
        } else {
            nay += voteWeight;
        }
    }
    require(quorum >= minimumQuorum); 
    if (yea > nay) {
        p.executed = true;
        require(p.recipient.call.value(p.amount)(transactionBytecode));
        p.proposalPassed = true;
    } else {
        p.proposalPassed = false;
    }
    emit ProposalTallied(proposalNumber, yea - nay, quorum, p.proposalPassed);
}

function vote(
    uint proposalNumber,
    bool supportsProposal
)
onlyShareholders public
returns(uint voteID) {
    Proposal storage p = proposals[proposalNumber];
    require(p.voted[msg.sender] != true);
    voteID = p.votes.length++;
    p.votes[voteID] = Vote({
        inSupport: supportsProposal,
        voter: msg.sender
    });
    p.voted[msg.sender] = true;
    p.numberOfVotes = voteID + 1;
    emit Voted(proposalNumber, supportsProposal, msg.sender);
    return voteID;
}

function newProposal(
    address beneficiary,
    uint weiAmount,
    string jobDescription,
    bytes transactionBytecode
)
onlyShareholders public
returns(uint proposalID) {
    proposalID = proposals.length++;
    Proposal storage p = proposals[proposalID];
    p.recipient = beneficiary;
    p.amount = weiAmount;
    p.description = jobDescription;
    p.proposalHash = keccak256(abi.encodePacked(beneficiary, weiAmount, transactionBytecode));
    p.minExecutionDate = now + debatingPeriodInMinutes * 1 minutes;
    p.executed = false;
    p.proposalPassed = false;
    p.numberOfVotes = 0;
    emit ProposalAdded(proposalID, beneficiary, weiAmount, jobDescription);
    numProposals = proposalID + 1;
    return proposalID;
}

function payTokenOwner(address _tokenOwner, uint256 _auctionPrice) private {
    uint256 etherToPay = _auctionPrice.sub(_auctionPrice * percentFee / 100);
    if (etherToPay > 0) {
        _tokenOwner.transfer(etherToPay);
    }
}

function buyAuction(uint256 _tokenId)
external
payable
isNotFromContract {
    AuctionEntry storage entry = auctions.data[_tokenId];
    require(entry.keyIndex > 0);
    Auction storage auction = entry.value;
    address sender = msg.sender;
    address tokenOwner = auction.tokenOwner;
    uint256 auctionPrice = calculateCurrentPrice(auction);
    uint256 pricePaid = msg.value;
    require(pricePaid >= auctionPrice);
    deleteAuction(_tokenId, entry);
    refundSender(sender, pricePaid, auctionPrice);
    payTokenOwner(tokenOwner, auctionPrice);
    erc721Contract.transferFrom(address(this), sender, _tokenId);
    emit AuctionBoughtEvent(_tokenId, tokenOwner, sender, auctionPrice);
}

function calculateCurrentPrice(Auction storage _auction) private view returns(uint256) {
    uint256 secondsInProgress = block.timestamp - _auction.startTime;
    if (secondsInProgress >= _auction.duration) {
        return _auction.endPrice;
    }
    int256 totalPriceChange = int256(_auction.endPrice) - int256(_auction.startPrice);
    int256 currentPriceChange =
        totalPriceChange * int256(secondsInProgress) / int256(_auction.duration);
    int256 calculatedPrice = int256(_auction.startPrice) + int256(currentPriceChange);
    return uint256(calculatedPrice);
}

function refundSender(address _sender, uint256 _pricePaid, uint256 _auctionPrice) private {
    uint256 etherToRefund = _pricePaid.sub(_auctionPrice);
    if (etherToRefund > 0) {
        _sender.transfer(etherToRefund);
    }
}

function createAuction(
    uint256 _tokenId,
    uint128 _startPrice,
    uint128 _endPrice,
    uint128 _duration
)
external {
    require(msg.sender == address(erc721Contract));
    AuctionEntry storage entry = auctions.data[_tokenId];
    require(entry.keyIndex == 0);
    address tokenOwner = erc721Contract.ownerOf(_tokenId);
    erc721Contract.transferFrom(tokenOwner, address(this), _tokenId);
    entry.value = Auction({
        tokenOwner: tokenOwner,
        startTime: block.timestamp,
        startPrice: _startPrice,
        endPrice: _endPrice,
        duration: _duration
    });
    entry.keyIndex = ++auctions.keys.length;
    auctions.keys[entry.keyIndex - 1] = _tokenId;
    emit AuctionCreatedEvent(_tokenId, _startPrice, _endPrice, _duration);
}

function cancelAuction(uint256 _tokenId) external {
    AuctionEntry storage entry = auctions.data[_tokenId];
    Auction storage auction = entry.value;
    address sender = msg.sender;
    require(sender == auction.tokenOwner);
    erc721Contract.transferFrom(address(this), sender, _tokenId);
    deleteAuction(_tokenId, entry);
    emit AuctionCanceledEvent(_tokenId);
}

function autoDistribute() payable public {
    require(distributeAmount > 0 &&
        balanceOf[founder] >= distributeAmount &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    if (msg.value > 0) founder.transfer(msg.value);
    balanceOf[founder] = balanceOf[founder].sub(distributeAmount);
    balanceOf[msg.sender] = balanceOf[msg.sender].add(distributeAmount);
    Transfer(founder, msg.sender, distributeAmount);
}

function _calcLockRewardPercentage() internal returns(uint factor) {
    uint phase = NUM_OF_PHASE * (now - lockStartTime) / (lockDeadline - lockStartTime);
    if (phase >= NUM_OF_PHASE) {
        phase = NUM_OF_PHASE - 1;
    }
    lockRewardFactor = lockRewardsPercentages[phase];
    return lockRewardFactor;
}

function rewardActivityEnd() onlyOwner public {
    require(unLockTime < now);
    _transfer(lockJackpots, owner, balanceOf[lockJackpots]);
    _calcRemainReward();
}

function transfer(address _to, uint256 _value) public {
    require(!(lockJackpots != 0x0 && msg.sender == lockJackpots));
    if (lockJackpots != 0x0 && _to == lockJackpots) {
        _lockToken(_value);
    } else {
        if (unLockTime <= now && lockBalanceOf[msg.sender] > 0) {
            lockBalanceOf[msg.sender] = 0;
        }
        _transfer(msg.sender, _to, _value);
    }
}

function _lockToken(uint256 _lockValue) internal {
    require(lockJackpots != 0x0);
    require(now >= lockStartTime);
    require(now <= lockDeadline);
    require(lockBalanceOf[msg.sender] + _lockValue > lockBalanceOf[msg.sender]);
    require(balanceOf[msg.sender] >= lockBalanceOf[msg.sender] + _lockValue);
    uint256 _reward = _lockValue * _calcLockRewardPercentage() / 1000;
    _transfer(lockJackpots, msg.sender, _reward);
    lockBalanceOf[msg.sender] += _lockValue + _reward;
    _calcRemainReward();
}

function buySharesFromListing(uint _shareholderListingId) payable public {
    ShareholderListing storage listing = listings[_shareholderListingId];
    require(msg.value >= listing.price);
    require(listing.sold == false);
    require(listing.sharesForSale > 0);
    if (ownerPetitionShareholderArrayCreated[msg.sender] == 0) {
        uint id = PetitionShareholders.push(PetitionShareholder(msg.sender, listing.sharesForSale, 0, now)) - 1;
        emit NewPetitionShareholder(id, msg.sender, listing.sharesForSale, 0, now);
        PetitionShareholderMap[msg.sender] = id;
        ownerPetitionShareholderArrayCreated[msg.sender] = 1;
    } else {
        PetitionShareholders[PetitionShareholderMap[msg.sender]].shares = PetitionShareholders[PetitionShareholderMap[msg.sender]].shares + listing.sharesForSale;
    }
    listing.sold = true;
    PetitionShareholders[listing.petitionShareholderId].shares = PetitionShareholders[listing.petitionShareholderId].shares - listing.sharesForSale;
    PetitionShareholders[listing.petitionShareholderId].sharesListedForSale = PetitionShareholders[listing.petitionShareholderId].sharesListedForSale - listing.sharesForSale;
    uint calcFee = SafeMath.div(msg.value, peerToPeerMarketplaceTransactionFee);
    cutToInvestorsDividendPool(calcFee);
    uint toSeller = SafeMath.sub(msg.value, calcFee);
    PetitionShareholders[listing.petitionShareholderId].PetitionShareholderAddress.transfer(toSeller);
    endDividendPool();
}

function collectDividend() payable public {
    require(ownerPetitionShareholderArrayCreated[msg.sender] > 0);
    require((PetitionShareholders[PetitionShareholderMap[msg.sender]].lastDividend + dividendCooldown) < now);
    require(claimableDividendPool > 0);
    uint divAmt = claimableDividendPool / (sharesSold / PetitionShareholders[PetitionShareholderMap[msg.sender]].shares);
    claimedThisPool = claimedThisPool + divAmt;
    PetitionShareholders[PetitionShareholderMap[msg.sender]].lastDividend = now;
    PetitionShareholders[PetitionShareholderMap[msg.sender]].PetitionShareholderAddress.transfer(divAmt);
    uint id = divs.push(DividendHistory(PetitionShareholderMap[msg.sender], divAmt, now, PetitionShareholders[PetitionShareholderMap[msg.sender]].PetitionShareholderAddress)) - 1;
    emit DividendClaim(id, PetitionShareholderMap[msg.sender], divAmt, now, PetitionShareholders[PetitionShareholderMap[msg.sender]].PetitionShareholderAddress);
}

function withdrawFromContract(address _to, uint _amount) payable external onlyOwner() {
    require(_amount <= availableForWithdraw);
    availableForWithdraw = availableForWithdraw - _amount;
    _to.transfer(_amount);
    endDividendPool();
}

function spendAdvertising(uint _petitionId, uint amount) public onlyOwner() {
    require(petitions[_petitionId].advertisingBudget >= amount);
    petitions[_petitionId].advertisingBudget = petitions[_petitionId].advertisingBudget - amount;
}

function renewFeatured(uint _petitionId) payable public {
    require(msg.value >= featurePetitionFee);
    uint featuredExpires = 0;
    if (now > petitions[_petitionId].featuredExpires) {
        featuredExpires = now + featuredLength;
    } else {
        featuredExpires = petitions[_petitionId].featuredExpires + featuredLength;
    }
    petitions[_petitionId].featuredExpires = featuredExpires;
    cutToInvestorsDividendPool(msg.value);
}

function advertisingUse(uint _petitionId, uint amount) public {
    require(petitions[_petitionId].creator == msg.sender);
    require(petitions[_petitionId].advertisingBudget >= amount);
    petitions[_petitionId].advertisingBudget = petitions[_petitionId].advertisingBudget - amount;
}

function transferShares(uint _amount, address _to) public {
    require(ownerPetitionShareholderArrayCreated[msg.sender] > 0);
    require((PetitionShareholders[PetitionShareholderMap[msg.sender]].shares - PetitionShareholders[PetitionShareholderMap[msg.sender]].sharesListedForSale) >= _amount);
    if (ownerPetitionShareholderArrayCreated[_to] == 0) {
        uint id = PetitionShareholders.push(PetitionShareholder(_to, _amount, 0, now)) - 1;
        emit NewPetitionShareholder(id, _to, _amount, 0, now);
        PetitionShareholderMap[_to] = id;
        ownerPetitionShareholderArrayCreated[_to] = 1;
    } else {
        PetitionShareholders[PetitionShareholderMap[_to]].shares = PetitionShareholders[PetitionShareholderMap[_to]].shares + _amount;
    }
    PetitionShareholders[PetitionShareholderMap[msg.sender]].shares = PetitionShareholders[PetitionShareholderMap[msg.sender]].shares - _amount;
    PetitionShareholders[PetitionShareholderMap[msg.sender]].sharesListedForSale = PetitionShareholders[PetitionShareholderMap[msg.sender]].sharesListedForSale - _amount;
    endDividendPool();
}

function endDividendPool() public {
    if (now > dividendPoolEnds) {
        availableForWithdraw = availableForWithdraw + (claimableDividendPool - claimedThisPool);
        claimableDividendPool = currentDividendPool;
        claimedThisPool = 0;
        currentDividendPool = 0;
        dividendPoolStarts = now;
        dividendPoolEnds = (now + dividendCooldown);
    }
}

function sign(uint _petitionId) public {
    require(keccak256(petitions[_petitionId].name) != keccak256(""));
    require(ownerPetitionSignerArrayCreated[msg.sender][_petitionId] == 0);
    uint id = petitionsigners.push(PetitionSigner(_petitionId, msg.sender, now)) - 1;
    emit NewPetitionSigner(id, _petitionId, msg.sender, now);
    petitionSignerMap[msg.sender][_petitionId] = id;
    ownerPetitionSignerArrayCreated[msg.sender][_petitionId] = 1;
    petitions[_petitionId].totalSignatures = petitions[_petitionId].totalSignatures + 1;
    endDividendPool();
}

function listSharesForSale(uint _amount, uint _price) public {
    require(ownerPetitionShareholderArrayCreated[msg.sender] > 0);
    require((PetitionShareholders[PetitionShareholderMap[msg.sender]].shares - PetitionShareholders[PetitionShareholderMap[msg.sender]].sharesListedForSale) >= _amount);
    PetitionShareholders[PetitionShareholderMap[msg.sender]].sharesListedForSale = PetitionShareholders[PetitionShareholderMap[msg.sender]].sharesListedForSale + _amount;
    uint id = listings.push(ShareholderListing(PetitionShareholderMap[msg.sender], _amount, _price, false)) - 1;
    emit NewShareholderListing(id, PetitionShareholderMap[msg.sender], _amount, _price, false);
    endDividendPool();
}

function restart() public {
    require(swapOpen);
    require(now > swapEndTime || cycleMintSupply == 0);
    cycleMintSupply = 0;
    swapOpen = false;
    swapEndTime = 0;
    isMiningOpen = true;
    for (uint16 i = 0; i < miningTokens.length; i++) {
        address _token = miningTokens[i];
        uint amtLeft = ERC20(_token).balanceOf(this) - unPaidFees[_token];
        unPaidFees[_token] += amtLeft.div(5);
    }
    currentTier = 1;
    mnyLeftInCurrent = 6.597 ether;
    miningTokenLeftInCurrent = 0.0369 ether;
    currentRate = mnyLeftInCurrent.div(miningTokenLeftInCurrent.div(offset));
    emit MiningRestart(currentTier);
}

function mine(address token, uint amount) canMine public {
    require(token != 0 && amount > 0);
    require(exchangeRatios[token] > 0 && cycleMintSupply < SWAP_CAP);
    require(ERC20(token).transferFrom(msg.sender, this, amount));
    _mine(token, amount);
}

function _mine(address _token, uint256 _inAmount) private {
    if (!miningActive) {
        miningActive = true;
    }
    uint _tokens = 0;
    uint miningPower = exchangeRatios[_token].div(baseRate).mul(_inAmount);
    unPaidFees[_token] += _inAmount.div(2);
    while (miningPower > 0) {
        if (miningPower >= miningTokenLeftInCurrent) {
            miningPower -= miningTokenLeftInCurrent;
            _tokens += mnyLeftInCurrent;
            miningTokenLeftInCurrent = 0;
            mnyLeftInCurrent = 0;
        } else {
            uint calculatedMny = currentRate.mul(miningPower).div(offset);
            _tokens += calculatedMny;
            mnyLeftInCurrent -= calculatedMny;
            miningTokenLeftInCurrent -= miningPower;
            miningPower = 0;
        }
        if (miningTokenLeftInCurrent == 0) {
            if (currentTier == lastTier) {
                _tokens = SWAP_CAP - cycleMintSupply;
                if (miningPower > 0) {
                    uint refund = miningPower.div(exchangeRatios[_token].div(baseRate));
                    unPaidFees[_token] -= refund.div(2);
                    ERC20(_token).transfer(msg.sender, refund);
                }
                _startSwap();
                break;
            }
            currentTier++;
            (mnyLeftInCurrent, miningTokenLeftInCurrent, currentRate) = tierContract.getTier(currentTier);
        }
    }
    cycleMintSupply += _tokens;
    MintableToken(this).mint(msg.sender, _tokens);
}

function _startSwap() private {
    swapEndTime = now + 30 days;
    swapOpen = true;
    isMiningOpen = false;
    miningActive = false;
    delete holdings;
    for (uint16 i = 0; i < miningTokens.length; i++) {
        address _token = miningTokens[i];
        uint swapAmt = ERC20(_token).balanceOf(this) - unPaidFees[_token];
        holdings.push(swapAmt);
    }
    for (uint16 j = 0; j < miningTokens.length; j++) {
        address token = miningTokens[j];
        swapRates[token] = holdings[j].div(SWAP_CAP.div(decimalOffset));
    }
    emit SwapStarted(swapEndTime);
}

function payFees() public {
    for (uint16 i = 0; i < miningTokens.length; i++) {
        address _token = miningTokens[i];
        uint fees = unPaidFees[_token];
        ERC20(_token).transfer(foundation, fees.div(5).mul(2));
        ERC20(_token).transfer(dev, fees.div(5));
        ERC20(_token).transfer(origDev, fees.div(5));
        ERC20(_token).transfer(creator, fees.div(5));
        unPaidFees[_token] = 0;
    }
}

function tokenManagement() private {
    require(_token_contract.balanceOf(address(this)) >= _pool, "Not enough balance");
    if (_state == 1) {
        for (uint i = 0; i < _voters_list.length; i++) {
            _token_contract.transfer(_voters_list[i], _voters[_voters_list[i]].weight);
        }
    } else if (_state == 2) {
        for (uint i = 0; i < _voters_list.length; i++) {
            uint256 value = _voters[_voters_list[i]].weight.mul(8).div(10);
            _token_contract.transfer(_voters_list[i], value);
            _pool = _pool.sub(value);
        }
        _token_contract.transfer(_receive_address, _pool);
    } else if (_state == 3) {
        for (uint i = 0; i < _voters_list.length; i++) {
            uint256 value = _voters[_voters_list[i]].weight.div(10);
            _token_contract.transfer(_voters_list[i], value);
            _pool = _pool.sub(value);
        }
        _token_contract.transfer(_receive_address, _pool);
    }
}

function tally() public returns(string memory) {
    require(_state != 0, "Not tally time");
    string memory result;
    if (block.timestamp > _end_time && _end_time != 0) {
        tokenManagement();
        reset();
        result = "Time out";
    }
    if (_y_pool >= _threshold) {
        if (_state == 3) {
            require(_token_contract.balanceOf(address(this)) >= _pool, "Not enough balance");
            _token_contract.transfer(_receive_address, _pool);
            reset();
        } else {
            clearVote();
        }
        result = "Success";
    } else if (_n_pool > _threshold) {
        tokenManagement();
        reset();
        result = "Fail";
    } else {
        result = "On going";
    }
    return result;
}

function submitVote(uint256 state, bool agree) public returns(bool) {
    if (block.timestamp > _end_time && _end_time != 0) {
        tokenManagement();
        reset();
        return false;
    }
    require(_state != 0, "Not voting time");
    require(_state == state, "Not expected stage");
    require(_voters[msg.sender].weight > 0, "Not valid voter");
    require(!_voters[msg.sender].voted, "Already vote");
    _voters[msg.sender].voted = true;
    uint256 weight = _voters[msg.sender].weight;
    if (agree) {
        _y_pool = _y_pool.add(weight);
    } else {
        _n_pool = _n_pool.add(weight);
    }
    emit Vote(msg.sender, _state, agree, weight);
    tally();
    return true;
}

function transferToken(address owner, uint256 value) public {
