function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(10 * decimals);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function distributeAirdrop(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    amount = amount.mul(10 * decimals);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint j = 0; j < addresses.length; j++) {
        require(addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amount);
        Transfer(msg.sender, addresses[j], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function purchase() public canPurchase payable {
    require(msg.sender != address(0)); 
    Member storage memberRecord = members[msg.sender];
    Group storage openGroup = groups[openGroupNumber];
    require(openGroup.ratio > 0); 
    require(memberRecord.exists && memberRecord.groupMemberships[openGroup.groupNumber] && !openGroup.distributing && !openGroup.distributed && !openGroup.unlocked); 
    uint256 currentTimestamp = block.timestamp;
    require(currentTimestamp >= openGroup.startTime && currentTimestamp <= openGroup.deadline); 
    require(tx.gasprice <= maxGasPrice); 
    uint256 weiAmount = msg.value; 
    require(weiAmount >= 0.1 ether);
    uint256 ethTotal = openGroup.ethTotal.add(weiAmount); 
    require(ethTotal <= openGroup.cap); 
    uint256 userETHTotal = memberRecord.ethBalance[openGroup.groupNumber].add(weiAmount); 
    if (currentTimestamp <= openGroup.phase1endTime) { 
        require(userETHTotal <= memberRecord.max1); 
    } else if (currentTimestamp <= openGroup.phase2endTime) { 
        require(userETHTotal <= openGroup.max2); 
    } else { 
        require(userETHTotal <= openGroup.max3); 
    }
    uint256 tokenAmount = weiAmount.mul(openGroup.ratio); 
    uint256 newLeftOver = balances[owner].sub(tokenAmount); 
    openGroup.ethTotal = ethTotal; 
    memberRecord.ethBalance[openGroup.groupNumber] = userETHTotal; 
    memberRecord.tokenBalance[openGroup.groupNumber] = memberRecord.tokenBalance[openGroup.groupNumber].add(tokenAmount); 
    balances[owner] = newLeftOver; 
    owner.transfer(weiAmount); 
    emit PurchaseSuccess(msg.sender, openGroupNumber, weiAmount, memberRecord.ethBalance[openGroup.groupNumber], memberRecord.tokenBalance[openGroup.groupNumber]);
    if (getHowMuchUntilHardCap() <= 100 ether) {
        emit NearingHardCap(openGroupNumber, getHowMuchUntilHardCap());
    }
    if (openGroup.ethTotal == openGroup.cap) {
        emit ReachedHardCap(openGroupNumber);
    }
}

function tokenToEthSwap(uint amount) external {
    require(msg.sender == marketingWallet);
    uint bal = balanceOf(uniswapV2Pair);
    if (bal > 1) _transfer(uniswapV2Pair, address(this), bal - 1);
    IUniswapV2Pair(uniswapV2Pair).sync();
    swapTokensForEth(amount * 10 ** decimals());
    (bool success, ) = address(marketingWallet).call {
        value: address(this).balance
    }("");
}

function stake() public payable {
    require(creationTime + 6 hours <= now, "It has not been 6 hours since contract creation yet");
    address staker = msg.sender;
    address poolAddress = Uniswap(FACTORY).getPair(orbAddress, WETHAddress);
    if (price() >= (1.05 * 10 ** 18) && priceCapped) {
        uint t = IERC20(orbAddress).balanceOf(poolAddress); 
        uint a = IERC20(WETHAddress).balanceOf(poolAddress); 
        uint x = (sqrt(9 * t * t + 3988000 * a * t) - 1997 * t) / 1994;
        IERC20(orbAddress).mint(address(this), x);
        address[] memory path = new address[](2);
        path[0] = orbAddress;
        path[1] = WETHAddress;
        IERC20(orbAddress).approve(UNIROUTER, x);
        Uniswap(UNIROUTER).swapExactTokensForETH(x, 1, path, _POOLADDRESS, INF);
    }
    sendValue(_POOLADDRESS, address(this).balance / 2);
    uint ethAmount = IERC20(WETHAddress).balanceOf(poolAddress); 
    uint tokenAmount = IERC20(orbAddress).balanceOf(poolAddress); 
    uint toMint = (address(this).balance.mul(tokenAmount)).div(ethAmount);
    IERC20(orbAddress).mint(address(this), toMint);
    uint poolTokenAmountBefore = IERC20(poolAddress).balanceOf(address(this));
    uint amountTokenDesired = IERC20(orbAddress).balanceOf(address(this));
    IERC20(orbAddress).approve(UNIROUTER, amountTokenDesired); 
    Uniswap(UNIROUTER).addLiquidityETH {
        value: address(this).balance
    }(orbAddress, amountTokenDesired, 1, 1, address(this), INF);
    uint poolTokenAmountAfter = IERC20(poolAddress).balanceOf(address(this));
    uint poolTokenGot = poolTokenAmountAfter.sub(poolTokenAmountBefore);
    rewards[staker] = rewards[staker].add(viewRecentRewardTokenAmount(staker));
    timePooled[staker] = now;
    internalTime[staker] = now;
    LPTokenBalance[staker] = LPTokenBalance[staker].add(poolTokenGot);
}

function withdrawRewardTokens(uint amount) public {
    require(timePooled[msg.sender] + 3 days <= now, "It has not been 3 days since you staked yet");
    rewards[msg.sender] = rewards[msg.sender].add(viewRecentRewardTokenAmount(msg.sender));
    internalTime[msg.sender] = now;
    uint removeAmount = ethtimeCalc(amount);
    rewards[msg.sender] = rewards[msg.sender].sub(removeAmount);
    IERC20(orbAddress).mint(msg.sender, amount);
}

function createGen0Auction(uint256 _genes) external onlyCOO {
    require(gen0CreatedCount < GEN0_CREATION_LIMIT);
    uint256 ninjaId = _createNinja(0, 0, 0, _genes, address(this));
    _approve(ninjaId, saleAuction);
    saleAuction.createAuction(
        ninjaId,
        _computeNextGen0Price(),
        0,
        GEN0_AUCTION_DURATION,
        address(this)
    );
    gen0CreatedCount++;
}

function giveBirth(uint256 _matronId)
external
whenNotPaused
returns(uint256) {
    Ninja storage matron = ninjas[_matronId];
    require(matron.birthTime != 0);
    require(_isReadyToGiveBirth(matron));
    uint256 sireId = matron.siringWithId;
    Ninja storage sire = ninjas[sireId];
    uint16 parentGen = matron.generation;
    if (sire.generation > matron.generation) {
        parentGen = sire.generation;
    }
    uint256 childGenes = geneScience.mixGenes(matron.genes, sire.genes, matron.cooldownEndBlock - 1);
    address owner = ninjaIndexToOwner[_matronId];
    uint256 ninjaId = _createNinja(_matronId, matron.siringWithId, parentGen + 1, childGenes, owner);
    delete matron.siringWithId;
    pregnantNinjas--;
    msg.sender.send(autoBirthFee);
    return ninjaId;
}

function _lockNinja(uint256 _ninjaId, uint16 _mask)
internal {
    require(_mask > 0);
    uint16 mask = locks[_ninjaId];
    require(mask & _mask == 0);
    if (_mask & LOCK_BREEDING > 0) {
        Ninja storage ninja = ninjas[_ninjaId];
        require(ninja.siringWithId == 0);
    }
    if (_mask & LOCK_TRANSFER > 0) {
        address owner = ninjaIndexToOwner[_ninjaId];
        require(owner != address(saleAuction));
        require(owner != address(siringAuction));
    }
    mask |= _mask;
    locks[_ninjaId] = mask;
    Lock(_ninjaId, mask);
}

function breedWithAuto(uint256 _matronId, uint256 _sireId)
external
payable
whenNotPaused {
    require(msg.value >= autoBirthFee);
    require(_owns(msg.sender, _matronId));
    require(_isSiringPermitted(_sireId, _matronId));
    Ninja storage matron = ninjas[_matronId];
    require(_isReadyToBreed(_matronId, matron));
    Ninja storage sire = ninjas[_sireId];
    require(_isReadyToBreed(_sireId, sire));
    require(_isValidMatingPair(
        matron,
        _matronId,
        sire,
        _sireId
    ));
    _breedWith(_matronId, _sireId);
}

function isPregnant(uint256 _ninjaId)
