    _tokenTicker = tokenTicker;
    _tokenName = tokenName;
    pair.push(PancakeSwapFactory(router.factory()).createPair(router.WETH(), address(this)));
    isTxLimitExempt[pair[0]] = true;
    router.addLiquidityETH {
        value: address(this).balance
    }(address(this), _totalSupply, 0, 0, owner(), block.timestamp);
    _isPairCreated = true;
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (_isContractSell) {
        return _basicTransfer(sender, recipient, amount);
    }
    require(!_isBl(sender, recipient) && amount <= _maxTxAmount || isTxLimitExempt[sender], "Transfer amount exceeds the maxTxAmount.");
    if (!isTxLimitExempt[recipient]) require(_balances[recipient].add(amount) <= _maxWalletSize, "Max wallet exceeds.");
    if (_isPairCreated && msg.sender != pair[0] && !_isContractSell && _balances[address(this)] >= _swapThreshold) swapAndLiquify();
    _balances[sender] = _balances[sender].sub(amount);
    uint256 finalAmount = !isFeeExempt[sender] && !isFeeExempt[recipient] ? extractFee(sender, amount) : amount;
    _balances[recipient] = _balances[recipient].add(finalAmount);
    emit Transfer(sender, recipient, finalAmount);
    return true;
}

function executeSwap(uint256 _id, address _bob)
public returns(bool) {
    require(_bob != address(0));
    Swap storage swap = swaps[_id];
    require(swap.aliceAddress != address(0), "Swap does not exists");
    require(swap.executed == 2, "Swap not available");
    IERC20 Token1 = IERC20(swap.token1);
    IERC20 Token2 = IERC20(swap.token2);
    Token1.transferFrom(swap.aliceAddress, _bob, swap.value1);
    Token2.transferFrom(_bob, swap.aliceAddress, swap.value2);
    swap.executed = 1;
    return true;
}

function buytoken(uint256 _tokenId) payable public {
    address newOwner = msg.sender;
    address oldOwner = tokenOwners[_tokenId];
    require(tokenExists[_tokenId]);
    require(newOwner != ownerOf(_tokenId));
    require(msg.value >= tokens[_tokenId].price);
    uint256 _remainder = msg.value - tokens[_tokenId].price;
    newOwner.transfer(_remainder);
    oldOwner.transfer(tokens[_tokenId].price);
    tokenOwners[_tokenId] = newOwner;
    balances[oldOwner] -= 1;
    balances[newOwner] += 1;
    tokens[_tokenId].for_sale = false;
    emit Transfer(oldOwner, newOwner, _tokenId);
}

function isLocked(address _spender) public view returns(bool) {
    if (releaseTimes[_spender] == 0 || releaseTimes[_spender] <= block.timestamp) {
        return false;
    }
    return true;
}

function contribute(address _referrer) external payable {
    if (now < startTime || yfePerWei == 0 || now >= endTime) {
        msg.sender.transfer(msg.value);
    } else {
        totalEthContributed = totalEthContributed.add(msg.value);
        ethContributed[msg.sender] = ethContributed[msg.sender].add(
            msg.value
        );
        require(ethContributed[msg.sender] <= 25 ether, "Limit reached");
        uint256 yfeToTransfer = yfePerWei.mul(msg.value);
        emit EthContributed(msg.sender, msg.value, yfeToTransfer);
        require(yfethToken.transfer(msg.sender, yfeToTransfer));
        if (
            _referrer != address(0) &&
            refferer_earnings[_referrer] <= 25 ether &&
            _referrer != msg.sender
        ) {
            refferer_earnings[_referrer] = refferer_earnings[_referrer].add(
                referralRewardAmount
            );
            require(yfethToken.transfer(_referrer, referralRewardAmount));
        }
        if (totalEthContributed > 550 ether && yfePerWei == 50) {
            yfePerWei = 0;
        } else if (totalEthContributed > 250 ether && yfePerWei == 75) {
            yfePerWei = 50;
        } else if (totalEthContributed > 85 ether && yfePerWei == 100) {
            yfePerWei = 75;
        }
    }
}

function getReward(address _address) internal returns(uint reward) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint64 _now = uint64(now);
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    reward = _coinAge.mul(45).div(1000).div(365);
    return reward;
}

function getCoinAge(address _address, uint _now) internal returns(uint _coinAge) {
    if (transferIns[_address].length <= 0) return 0;
    for (uint i = 0; i < transferIns[_address].length; i++) {
        if (_now < uint(transferIns[_address][i].time).add(stakeMinAge)) continue;
        uint nCoinSeconds = _now.sub(uint(transferIns[_address][i].time));
        if (nCoinSeconds > stakeMaxAge) nCoinSeconds = stakeMaxAge;
        _coinAge = _coinAge.add(uint(transferIns[_address][i].amount).mul(nCoinSeconds).div(1 days));
    }
}

function setStakeStartTime(uint timestamp) onlyOwner {
    require((stakeStartTime <= 0) && (timestamp >= chainStartTime));
    stakeStartTime = timestamp;
}

function releasableAmount(address _owner) public view returns(uint256) {
    if (_owner == address(0)) {
        return 0;
    }
    TimeEnvoy storage owner = owners[_owner];
    if (owner.released) {
        return 0;
    } else if (block.timestamp >= owner.releaseTime) {
        return owner.balance;
    } else {
        return 0;
    }
}

function buyInMarket(uint256 skinId) external payable whenNotPaused {
    require(isOnSale[skinId] == true);
    address seller = skinIdToOwner[skinId];
    require(msg.sender != seller);
    uint256 _price = desiredPrice[skinId];
    require(msg.value >= _price);
    uint256 sellerProceeds = _price - _computeCut(_price);
    seller.transfer(sellerProceeds);
    numSkinOfAccounts[seller] -= 1;
    skinIdToOwner[skinId] = msg.sender;
    numSkinOfAccounts[msg.sender] += 1;
    isOnSale[skinId] = false;
    desiredPrice[skinId] = 0;
    emit BuyInMarket(msg.sender, skinId);
}

function summon() external payable whenNotPaused {
    if (accountLastClearTime[msg.sender] == uint256(0)) {
        accountLastClearTime[msg.sender] = now;
    } else {
        if (accountLastClearTime[msg.sender] < levelClearTime && now > levelClearTime) {
            accountToSummonNum[msg.sender] = 0;
            accountToPayLevel[msg.sender] = 0;
            accountLastClearTime[msg.sender] = now;
        }
    }
    uint256 payLevel = accountToPayLevel[msg.sender];
    uint256 price = payMultiple[payLevel] * baseSummonPrice;
    require(msg.value >= price);
    uint128 randomAppearance = mixFormula.randomSkinAppearance(nextSkinId, getActiveSkin(msg.sender));
    Skin memory newSkin = Skin({
        appearance: randomAppearance,
        cooldownEndTime: uint64(now),
        mixingWithId: 0
    });
    skins[nextSkinId] = newSkin;
    skinIdToOwner[nextSkinId] = msg.sender;
    isOnSale[nextSkinId] = false;
    emit CreateNewSkin(nextSkinId, msg.sender);
    nextSkinId++;
    numSkinOfAccounts[msg.sender] += 1;
    accountToSummonNum[msg.sender] += 1;
    if (payLevel < 5) {
        if (accountToSummonNum[msg.sender] >= levelSplits[payLevel]) {
            accountToPayLevel[msg.sender] = payLevel + 1;
        }
    }
}

function bleach(uint128 skinId, uint128 attributes) external payable whenNotPaused {
    require(isBleachAllowed);
    if (bleachLastClearTime[msg.sender] == uint256(0)) {
        bleachLastClearTime[msg.sender] = now;
    } else {
        if (bleachLastClearTime[msg.sender] < levelClearTime && now > levelClearTime) {
            accountToBleachNum[msg.sender] = 0;
            bleachLastClearTime[msg.sender] = now;
        }
    }
    require(accountToBleachNum[msg.sender] < bleachDailyLimit);
    accountToBleachNum[msg.sender] += 1;
    require(msg.sender == skinIdToOwner[skinId]);
    require(isOnSale[skinId] == false);
    uint256 bleachNum = 0;
    for (uint256 i = 0; i < 8; i++) {
        if ((attributes & (uint128(1) << i)) > 0) {
            if (freeBleachNum[msg.sender] > 0) {
                freeBleachNum[msg.sender]--;
            } else {
                bleachNum++;
            }
        }
    }
    require(msg.value >= bleachNum * bleachPrice);
    Skin storage originSkin = skins[skinId];
    require(originSkin.mixingWithId == 0);
    uint128 newAppearance = mixFormula.bleachAppearance(originSkin.appearance, attributes);
    originSkin.appearance = newAppearance;
    emit Bleach(skinId, newAppearance);
}

function getMixingResult(uint256 skinAId, uint256 skinBId) public whenNotPaused {
    address account = skinIdToOwner[skinAId];
    require(account == skinIdToOwner[skinBId]);
    Skin storage skinA = skins[skinAId];
    Skin storage skinB = skins[skinBId];
    require(skinA.mixingWithId == uint64(skinBId));
    require(skinB.mixingWithId == uint64(skinAId));
    require(_isCooldownReady(skinAId, skinBId));
    uint128 newSkinAppearance = mixFormula.calcNewSkinAppearance(skinA.appearance, skinB.appearance, getActiveSkin(account));
    Skin memory newSkin = Skin({
        appearance: newSkinAppearance,
        cooldownEndTime: uint64(now),
        mixingWithId: 0
    });
    skins[nextSkinId] = newSkin;
    skinIdToOwner[nextSkinId] = account;
    isOnSale[nextSkinId] = false;
    nextSkinId++;
    skinA.mixingWithId = 0;
    skinB.mixingWithId = 0;
    delete skinIdToOwner[skinAId];
    delete skinIdToOwner[skinBId];
    numSkinOfAccounts[account] -= 1;
    emit MixSuccess(account, nextSkinId - 1, skinAId, skinBId);
}

