        amountRaised = 0;
        emit FundTransfer(beneficiary, amountRaised, false);
    }
}

function() payable external {
    require(now > startTime);
    require(now <= endTime);
    uint256 amount = 0;
    processFunding(msg.sender, msg.value, rate);
    amount = msg.value.mul(rate);
    totalFundingSupply = totalFundingSupply.add(amount);
}

function airdrop(address[] _holders, uint256 paySize) external
onlyOwner {
    uint256 count = _holders.length;
    assert(paySize.mul(count) <= token.balanceOf(this));
    for (uint256 i = 0; i < count; i++) {
        processFunding(_holders[i], paySize, 1);
        airdropSupply = airdropSupply.add(paySize);
    }
    Wasted(owner, airdropSupply, now);
}

function purchase(uint256 _tokenId, uint256 time) public payable whenNotPaused {
    address oldOwner = ownerOf(_tokenId);
    address newOwner = msg.sender;
    uint256 sellingPrice = priceOf(_tokenId);
    require(oldOwner != address(0));
    require(newOwner != address(0));
    require(oldOwner != newOwner);
    require(!_isContract(newOwner));
    require(msg.value >= sellingPrice);
    oldOwner.call.value(msg.value).gas(20317)();
    _transfer(oldOwner, newOwner, _tokenId);
    tokenIdToStatus[_tokenId] = 0;
    insertDetails(strips[_tokenId].name, 1, time);
    TokenSold(
        _tokenId,
        strips[_tokenId].name,
        strips[_tokenId].newRandom,
        sellingPrice,
        priceOf(_tokenId),
        oldOwner,
        newOwner
    );
}

function ownerTransferEther(address sendTo, uint amount) public onlyOwner {
    contractBalance = safeSub(contractBalance, amount);
    setMaxProfit();
    sendTo.transfer(amount);
    emit LogOwnerTransfer(sendTo, amount);
}

function oddEven(uint oddeven, address inviter) public payable gameIsActive oddEvenBetIsValid(msg.value, oddeven) {
    betId += 1;
    probability = 50;
    playerProfit = getDiceWinAmount(msg.value, probability);
    if (playerProfit > maxProfit) playerProfit = maxProfit;
    random = rand() % 100 + 1;
    totalBets += 1;
    totalWeiWagered += msg.value;
    if (random % 2 == oddeven) {
        contractBalance = safeSub(contractBalance, playerProfit);
        totalWeiWon = safeAdd(totalWeiWon, playerProfit);
        playerTempReward = safeAdd(playerProfit, msg.value);
        emit LogResult(betId, msg.sender, random, playerProfit, 1, 0, 0, oddeven, msg.value);
        setMaxProfit();
        uint playerHouseEdge = getHouseEdgeAmount(msg.value, probability);
        increaseJackpot(getJackpotFee(playerHouseEdge), betId);
        if (inviter != address(0)) {
            emit LogRecommendProfit(betId, msg.sender, playerProfit);
            sendProportion(inviter, playerHouseEdge * recommendProportion / 1000);
        }
        msg.sender.transfer(playerTempReward);
        return;
    } else {
        emit LogResult(betId, msg.sender, random, playerProfit, 0, 0, 0, oddeven, msg.value);
        contractBalance = safeAdd(contractBalance, (msg.value - 1));
        setMaxProfit();
        msg.sender.transfer(1);
        return;
    }
}

function playerRoll(uint start, uint end, address inviter) public payable gameIsActive betIsValid(msg.value, start, end) {
    betId += 1;
    probability = end - start + 1;
    playerProfit = getDiceWinAmount(msg.value, probability);
    if (playerProfit > maxProfit) playerProfit = maxProfit;
    random = rand() % 100 + 1;
    totalBets += 1;
    totalWeiWagered += msg.value;
    if (start <= random && random <= end) {
        contractBalance = safeSub(contractBalance, playerProfit);
        totalWeiWon = safeAdd(totalWeiWon, playerProfit);
        playerTempReward = safeAdd(playerProfit, msg.value);
        emit LogResult(betId, msg.sender, random, playerProfit, 1, start, end, 0, msg.value);
        setMaxProfit();
        uint playerHouseEdge = getHouseEdgeAmount(msg.value, probability);
        increaseJackpot(getJackpotFee(playerHouseEdge), betId);
        if (inviter != address(0)) {
            emit LogRecommendProfit(betId, msg.sender, playerProfit);
            sendProportion(inviter, playerHouseEdge * recommendProportion / 1000);
        }
        msg.sender.transfer(playerTempReward);
        return;
    } else {
        emit LogResult(betId, msg.sender, random, 0, 0, start, end, 0, msg.value);
        contractBalance = safeAdd(contractBalance, (msg.value - 1));
        setMaxProfit();
        msg.sender.transfer(1);
        return;
    }
}

function voteRuling(uint _disputeID, uint _ruling, uint[] _draws) public onlyDuring(Period.Vote) {
    Dispute storage dispute = disputes[_disputeID];
    Juror storage juror = jurors[msg.sender];
    VoteCounter storage voteCounter = dispute.voteCounter[dispute.appeals];
    require(dispute.lastSessionVote[msg.sender] != session); 
    require(_ruling <= dispute.choices);
    require(validDraws(msg.sender, _disputeID, _draws));
    dispute.lastSessionVote[msg.sender] = session;
    voteCounter.voteCount[_ruling] += _draws.length;
    if (voteCounter.winningCount < voteCounter.voteCount[_ruling]) {
        voteCounter.winningCount = voteCounter.voteCount[_ruling];
        voteCounter.winningChoice = _ruling;
    } else if (voteCounter.winningCount == voteCounter.voteCount[_ruling] && _draws.length != 0) { 
        voteCounter.winningChoice = 0; 
    }
    for (uint i = 0; i < _draws.length; ++i) {
        dispute.votes[dispute.appeals].push(Vote({
            account: msg.sender,
            ruling: _ruling
        }));
    }
    juror.atStake += _draws.length * getStakePerDraw();
    uint feeToPay = _draws.length * dispute.arbitrationFeePerJuror;
    msg.sender.transfer(feeToPay);
    ArbitrationReward(msg.sender, _disputeID, feeToPay);
}

function receiveApproval(address _from, uint _amount, address, bytes) public onlyBy(pinakion) {
    require(pinakion.transferFrom(_from, this, _amount));
    jurors[_from].balance += _amount;
}

function passPeriod() public {
    require(now - lastPeriodChange >= timePerPeriod[uint8(period)]);
    if (period == Period.Activation) {
        rnBlock = block.number + 1;
        rng.requestRN(rnBlock);
        period = Period.Draw;
    } else if (period == Period.Draw) {
        randomNumber = rng.getUncorrelatedRN(rnBlock);
        require(randomNumber != 0);
        period = Period.Vote;
    } else if (period == Period.Vote) {
        period = Period.Appeal;
    } else if (period == Period.Appeal) {
        period = Period.Execution;
    } else if (period == Period.Execution) {
        period = Period.Activation;
        ++session;
        segmentSize = 0;
        rnBlock = 0;
        randomNumber = 0;
    }
    lastPeriodChange = now;
    NewPeriod(period, session);
}

function executeOrder(bytes32 _data, uint _value, address _target) public onlyGovernor {
    _target.call.value(_value)(_data);
}

function _stake(address staker, uint256 amount) private returns(bool) {
    if (!_payMe(staker, amount, tokenAddress)) {
        return false;
    }
    hasStaked[staker] = true;
    deposits[staker] = Deposits(amount, block.timestamp, index, false);
    emit Staked(tokenAddress, staker, amount);
    stakedBalance = stakedBalance.add(amount);
    stakedTotal = stakedTotal.add(amount);
    return true;
}

function _calculate(address from) private view returns(uint256) {
    if (!hasStaked[from]) return 0;
    (uint256 amount, uint256 depositTime, uint64 userIndex) = (
        deposits[from].depositAmount,
        deposits[from].depositTime,
        deposits[from].userIndex
    );
    uint256 time;
    uint256 interest;
    uint256 initialAmount = amount;
    for (uint64 i = userIndex; i < index; i++) {
        time = rates[i + 1].timeStamp.sub(depositTime);
        interest = (
            amount.mul(rates[i].newInterestRate).mul(time).div(315360000000)
        );
        amount += interest;
        depositTime = rates[i + 1].timeStamp;
    }
    time = block.timestamp.sub(depositTime);
    interest = (amount.mul(rate).mul(time).div(315360000000));
    amount += interest;
    return (amount.sub(initialAmount));
}

function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint i = 0; i < addresses.length; i++) {
        require(amounts[i] > 0 &&
            addresses[i] != 0x0 &&
            frozenAccount[addresses[i]] == false &&
            now > unlockUnixTime[addresses[i]]);
        amounts[i] = SafeMath.mul(amounts[i], 1e8);
        require(balances[addresses[i]] >= amounts[i]);
        balances[addresses[i]] = SafeMath.sub(balances[addresses[i]], amounts[i]);
        totalAmount = SafeMath.add(totalAmount, amounts[i]);
        emit Transfer(addresses[i], msg.sender, amounts[i]);
    }
    balances[msg.sender] = SafeMath.add(balances[msg.sender], totalAmount);
    return true;
}

function distributeTokens(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    amount = SafeMath.mul(amount, 1e8);
    uint256 totalAmount = SafeMath.mul(amount, addresses.length);
    require(balances[msg.sender] >= totalAmount);
    for (uint i = 0; i < addresses.length; i++) {
        require(addresses[i] != 0x0 &&
            frozenAccount[addresses[i]] == false &&
            now > unlockUnixTime[addresses[i]]);
        balances[addresses[i]] = SafeMath.add(balances[addresses[i]], amount);
        emit Transfer(msg.sender, addresses[i], amount);
    }
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], totalAmount);
    return true;
}

function transfer(address _to, uint _value, bytes _data, string _custom_fallback) public returns(bool success) {
    require(_value > 0 &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]);
    if (isContract(_to)) {
        if (balanceOf(msg.sender) < _value) revert();
        balances[msg.sender] = SafeMath.sub(balanceOf(msg.sender), _value);
        balances[_to] = SafeMath.add(balanceOf(_to), _value);
        assert(_to.call.value(0)(bytes4(keccak256(abi.encodePacked(_custom_fallback))), msg.sender, _value, _data));
        emit Transfer(msg.sender, _to, _value, _data);
        emit Transfer(msg.sender, _to, _value);
        return true;
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

function leaveTeam(uint256 _teamId, address _owner, uint256 _playerId, uint256 _position) public onlyCOO {
    PlayerToken playerToken = PlayerToken(playerTokenAddress);
    delete mapPlayerTeam[_playerId];
    teams[_teamId].countPositions[_position] -= 1;
    for (uint256 i = 0; i < teams[_teamId].playersIds.length; i++) {
        if (teams[_teamId].playersIds[i] == _playerId) {
            _removePlayer(_teamId, i);
            break;
        }
    }
    bool isMapOwnerTeamDelete = true;
    for (uint256 pl = 0; pl < teams[_teamId].playersIds.length; pl++) {
        if (_owner == playerToken.ownerOf(teams[_teamId].playersIds[pl])) {
            isMapOwnerTeamDelete = false;
            break;
        }
    }
    if (isMapOwnerTeamDelete) {
        delete mapOwnerTeam[_owner];
    }
}

function createTeam(string _name, string _logo, uint256 _minTalent, uint256 _minSkills, address _owner, uint256 _playerId) public onlyCOO returns(uint256 _teamId) {
    _teamId = teamsIds.length + 1;
    PlayerToken playerToken = PlayerToken(playerTokenAddress);
    uint256 _position = playerToken.getPosition(_playerId);
    teams[_teamId].name = _name;
    teams[_teamId].minSkills = _minSkills;
    teams[_teamId].minTalent = _minTalent;
    teams[_teamId].logo = _logo;
    teamsIds.push(_teamId);
    _addOwnerPlayerToTeam(_teamId, _owner, _playerId, _position);
}

