    } else {
        _affID = pIDxName_[_affCode];
        if (_affID != plyr_[_pID].laff) {
            plyr_[_pID].laff = _affID;
        }
    }
    if (round_[rID_].state == 1) {
        _tID = determinTID(_team, _pID);
        buyCore(_pID, _affID, _tID, msg.value);
        if (round_[rID_].tID_ >= 16) {
            round_[rID_].state = 2;
            startKilling();
        }
    } else if (round_[rID_].state == 2) {
        if (round_[rID_].liveTeams == 1) {
            endRound();
            refund(_pID, msg.value);
            return;
        }
        _tID = determinTID(_team, _pID);
        buyCore(_pID, _affID, _tID, msg.value);
        if (now > round_[rID_].lastKillingTime.add(killingGap_)) {
            kill();
        }
    }
}

function createContribution(address beneficiary, uint usdAmount) public
onlyOwner
addressNotZero(beneficiary)
hasValue(usdAmount)
crowdsaleNotOver {
    usdRaised = usdRaised.add(usdAmount); 
    uint aoraTgeAmount = usdAmount.mul(tokensPerUsdRate).mul(centsToWholeTokenFactor);
    if (isPresale())
        aoraTgeAmount = aoraTgeAmount.mul(11).div(10); 
    uint newTokensSoldAmount = tokensSold.add(aoraTgeAmount);
    require(newTokensSoldAmount <= cap);
    tokensSold = newTokensSoldAmount;
    token.transfer(beneficiary, aoraTgeAmount);
    addToWhitelist(beneficiary);
    emit OnContributionCreated(beneficiary, usdAmount);
}

function isCrowdsale() public view returns(bool) {
    return now < endOfCrowdsale;
}

function isPresale() public view returns(bool) {
    return now < endOfPresale;
}

function hasEnded() public view returns(bool) {
    bool isEnd = now > endTime || weiRaised >= 20000000000000000000000000;
    return isEnd;
}

function releaseSbtToken() public returns(bool) {
    require(msg.sender == setWallet);
    require(hasEnded() && startTime != 0);
    uint256 remainedSbt = ERC20Basic(SBT).balanceOf(this);
    require(ERC20Basic(SBT).transfer(starbitWallet, remainedSbt));
    SBTTokenAbstract(SBT).unlock();
}

function checkRate() public returns(bool) {
    if (now >= startTime && now < 1533657600) {
        rate = 6000;
    } else if (now >= 1533657600 && now < 1534867200) {
        rate = 5500;
    } else if (now >= 1534867200) {
        rate = 5000;
    }
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    return withinPeriod;
}

function transfer(address _to, uint256 _value) public {
    if (balanceOf[msg.sender] < _value) return;
    if (balanceOf[_to] + _value < balanceOf[_to]) return;
    if (blackList[msg.sender] > 0) {
        emit RejectedPaymentFromBlacklistedAddr(msg.sender, _to, _value);
    } else if (blackList[_to] > 0) {
        emit RejectedPaymentToBlacklistedAddr(msg.sender, _to, _value);
    } else {
        uint256 cashback = 0;
        if (members[_to] > address(0)) {
            cashback = _value / 100 * uint256(members[_to].getCashbackRate(msg.sender));
            members[_to].updateHistory(msg.sender, _value);
        }
        balanceOf[msg.sender] -= (_value - cashback);
        balanceOf[_to] += (_value - cashback);
        emit Transfer(msg.sender, _to, _value);
        emit Cashback(_to, msg.sender, cashback);
    }
}

function requestRefund() public {
    require(didGive[msg.sender]);
    Donate storage record = donationRecords[msg.sender];
    require(record.funder == msg.sender);
    record.funder.transfer(record.value);
    didGive[msg.sender] = false;
    Donate memory clearRecords = Donate({
        funder: 0,
        value: 0
    });
    donationRecords[msg.sender] = clearRecords;
}

function withdraw() public restricted {
    require(withdrawalDate < now);
    author.transfer(address(this).balance);
    withdrawalDate = now + 30 days;
}

function buyInBatch(uint256 _vendorId, uint256 _rpid, uint256[] _dates, uint256 _token)
external
payable
ratePlanExist(_vendorId, _rpid)
validDates(_dates)
returns(bool) {
    (, address vendor, , ) = dataSource.getVendor(_vendorId);
    bool result = _buyInBatch(_vendorId, vendor, _rpid, _dates, _token);
    require(result);
    emit BuyInBatch(msg.sender, vendor, _rpid, _dates, _token);
    return true;
}

function refund(uint256 _rnid)
external
payable
validToken(_rnid)
returns(bool) {
    require(dataSource.refundApplications(dataSource.roomNightIndexToOwner(_rnid), _rnid));
    (uint256 vendorId, uint256 rpid, uint256 token, uint256 price, , uint256 date, ) = dataSource.roomnights(_rnid);
    (, address vendor, , ) = dataSource.getVendor(vendorId);
    require(msg.sender == vendor);
    address ownerAddress = dataSource.roomNightIndexToOwner(_rnid);
    if (token == 0) {
        uint256 value = price;
        require(msg.value >= value);
        ownerAddress.transfer(value);
    } else {
        require(price > 0);
        TripioToken tripio = TripioToken(dataSource.tokenIndexToAddress(token));
        tripio.transferFrom(msg.sender, ownerAddress, price);
    }
    _refund(_rnid, vendorId, rpid, date);
    emit Refund(msg.sender, _rnid);
    return true;
}

function createSmartFund(
    string memory _name,
    uint256 _successFee,
    bool _isStableBasedFund
) public {
    require(_successFee <= maximumSuccessFee);
    address owner = msg.sender;
    address smartFund;
    if (_isStableBasedFund) {
        smartFund = smartFundUSDFactory.createSmartFund(
            owner,
            _name,
            _successFee,
            platformFee,
            exchangePortalAddress,
            address(permittedExchanges),
            address(permittedPools),
            address(permittedStables),
            poolPortalAddress,
            stableCoinAddress,
            convertPortalAddress,
