function bet(uint _pingPong, uint256 _randomSeed) public payable {
    uint256 currentRound = getCurrentRoundNumber();
    require(msg.value == rounds[currentRound].amount, "ERROR: amount not allowed");
    if (rounds[currentRound].endTime != 0)
        require(rounds[currentRound].endTime >= now, "ERROR: round is over");
    bool isBet;
    for (uint256 i = 0; i < players[currentRound].length; i++) {
        if (players[currentRound][i].addr == msg.sender) {
            isBet = true;
        }
    }
    require(isBet == false, "ERROR: already bet");
    if (!isBet) {
        players[currentRound].push(Player({
            addr: msg.sender,
            balance: msg.value,
            randomSeed: _randomSeed,
            choice: Choice(_pingPong),
            state: State.UNDEFINED
        }));
        updateRoundFirstDeposit();
        emit Bet(currentRound, msg.sender, msg.value, _pingPong);
    }
}

function _calculate(uint256 _round) internal {
    uint256 totalPing;
    uint256 totalPong;
    uint256 totalReward;
    for (uint256 i = 0; i < players[_round].length; i++) {
        if (players[_round][i].choice == Choice.PING) {
            totalPing = totalPing.add(1);
        } else {
            totalPong = totalPong.add(1);
        }
        totalReward = totalReward.add(players[_round][i].balance);
    }
    if (totalPing == 0 || totalPong == 0) {
        for (uint256 i = 0; i < players[_round].length; i++) {
            TransferHelper.safeTransferETH(players[_round][i].addr, players[_round][i].balance);
            players[_round][i].state = State.REFUND;
        }
    } else {
        uint256 feeAmount = totalReward.mul(fee).div(100).div(10 ** 6);
        TransferHelper.safeTransferETH(owner(), feeAmount);
        totalReward = totalReward.sub(feeAmount);
        uint256 winAmount;
        Choice theWinner = Choice(_random(_round));
        if (theWinner == Choice.PING) {
            winAmount = totalReward.div(totalPing);
        } else {
            winAmount = totalReward.div(totalPong);
        }
        for (uint256 i = 0; i < players[_round].length; i++) {
            if (players[_round][i].choice == theWinner) {
                players[_round][i].state = State.WIN;
                players[_round][i].balance = winAmount;
                addBalance(players[_round][i].addr, winAmount);
                totalReward = totalReward.sub(winAmount);
            } else {
                players[_round][i].state = State.LOSE;
            }
        }
        if (totalReward > 0) {
            TransferHelper.safeTransferETH(owner(), totalReward);
        }
    }
}

function sell(uint256 _amountOfTokens)
onlyBagholders()
public {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    uint256 _tokens = _amountOfTokens;
    uint256 _ethereum = tokensToEthereum_(_tokens);
    uint256 _feesEthereum = SafeMath.div(_ethereum, exchangesellFee_);
    uint256 _sellfeeEthereum = SafeMath.div(_ethereum, sellFee_);
    if (ambassadors_[_customerAddress] == true) {
        _sellfeeEthereum = SafeMath.div(_ethereum, exchangesellFee_);
    }
    uint256 _dividends = SafeMath.sub(_sellfeeEthereum, _feesEthereum);
    uint256 _taxedEthereum = SafeMath.sub(_ethereum, _sellfeeEthereum);
    exchangefees.transfer(_feesEthereum);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokens);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _tokens);
    int256 _updatedPayouts = (int256)(profitPerShare_ * _tokens + (_taxedEthereum * magnitude));
    payoutsTo_[_customerAddress] -= _updatedPayouts;
    if (tokenSupply_ > 0) {
        profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
        payoutsTo_[measurement] -= (int256)(SafeMath.sub((_dividends * magnitude), SafeMath.div((_dividends * magnitude), tokenSupply_) * tokenSupply_));
    }
    onTokenSell(_customerAddress, _tokens, _taxedEthereum);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, transferFee_);
    if (ambassadors_[_customerAddress] == true) {
        _tokenFee = SafeMath.div(_amountOfTokens, presaletransferFee_);
    }
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _feesEthereum = SafeMath.div(tokensToEthereum_(_tokenFee), exchangebuyFee_);
    uint256 _dividends = SafeMath.sub(tokensToEthereum_(_tokenFee), _feesEthereum);
    exchangefees.transfer(_feesEthereum);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    payoutsTo_[measurement] -= (int256)(SafeMath.sub((_dividends * magnitude), SafeMath.div((_dividends * magnitude), tokenSupply_) * tokenSupply_));
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function purchaseTokens(uint256 _incomingEthereum, address _referredBy)
antiEarlyWhale(_incomingEthereum)
internal
returns(uint256) {
    address _customerAddress = msg.sender;
    uint256 _feesEthereum = SafeMath.div(_incomingEthereum, exchangebuyFee_);
    uint256 _referralBonus = SafeMath.div(_incomingEthereum, referralFeenormal_);
    if (tokenBalanceLedger_[_referredBy] >= stakingRequirement) {
        _referralBonus = SafeMath.div(_incomingEthereum, referralFeedouble_);
    }
    uint256 _dividends = SafeMath.sub((SafeMath.div(_incomingEthereum, buyFee_)), (SafeMath.add(_feesEthereum, _referralBonus)));
    uint256 _taxedEthereum = SafeMath.sub(_incomingEthereum, (SafeMath.div(_incomingEthereum, buyFee_)));
    uint256 _amountOfTokens = ethereumToTokens_(_taxedEthereum);
    uint256 _fee = _dividends * magnitude;
    exchangefees.transfer(_feesEthereum);
    require(_amountOfTokens > 0 && (SafeMath.add(_amountOfTokens, tokenSupply_) > tokenSupply_));
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress
    ) {
        referralBalance_[_referredBy] = SafeMath.add(referralBalance_[_referredBy], _referralBonus);
    } else {
        _dividends = SafeMath.add(_dividends, _referralBonus);
        _fee = _dividends * magnitude;
    }
    if (tokenSupply_ > 0) {
        tokenSupply_ = SafeMath.add(tokenSupply_, _amountOfTokens);
        profitPerShare_ += (_dividends * magnitude / (tokenSupply_));
        payoutsTo_[measurement] -= (int256)(SafeMath.sub((_dividends * magnitude), SafeMath.div((_dividends * magnitude), tokenSupply_) * tokenSupply_));
        _fee = _fee - (_fee - (_amountOfTokens * (_dividends * magnitude / (tokenSupply_))));
    } else {
        tokenSupply_ = _amountOfTokens;
    }
    payoutsTo_[measurement] -= (int256)(SafeMath.sub(SafeMath.sub(_taxedEthereum, SafeMath.div(_taxedEthereum, sellFee_)), SafeMath.sub(tokensToEthereum_(_amountOfTokens), SafeMath.div(tokensToEthereum_(_amountOfTokens), sellFee_))) * magnitude);
    tokenBalanceLedger_[_customerAddress] = SafeMath.add(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    int256 _updatedPayouts = (int256)((profitPerShare_ * _amountOfTokens) - _fee);
    payoutsTo_[_customerAddress] += _updatedPayouts;
    onTokenPurchase(_customerAddress, _incomingEthereum, _amountOfTokens, _referredBy);
    return _amountOfTokens;
}

