function purchaseTicket(uint256 _ticketNumbers, uint256 ticketCount) external payable returns(bool) {
    if (_ticketNumbers == 0) {
        totalDonation = totalDonation + 1;
        return true;
    }
    require(msg.value >= ticketCount.mul(_ticketPrice), "Insufficient eth value");
    require(_ticketNumbers.div(10 ** (ticketCount.mul(12))) == 0 && _ticketNumbers.div(10 ** (ticketCount.mul(12).sub(2))) > 0, "Invalid ticket value/count");
    uint256 saleId;
    if ((saleStartTimeStamp[saleIdNow] + elapsedTime) > now) {
        saleId = saleIdNow;
    } else {
        saleId = saleIdNow.add(1);
    }
    AllParticipantAddresses.push(msg.sender);
    totalSaleAmount[saleId] = totalSaleAmount[saleId] + msg.value;
    totalSaleAmountForAllSales = totalSaleAmountForAllSales + msg.value;
    totalSaleAmountByAddAndSaleID[saleId][msg.sender] = totalSaleAmountByAddAndSaleID[saleId][msg.sender] + msg.value;
    ticketNumberByAddress[saleId][msg.sender].push(_ticketNumbers);
    if (ticketCount == 5) {
        lottoCoin.transfer(msg.sender, _purchaseTokenAmount);
        allAddressList[saleId].push(msg.sender);
        saleParticipants[saleId] = saleParticipants[saleId] + 1;
        return true;
    }
}

function declareWinner(uint256[] calldata _winningSequence, uint256 _powerballNumber, address payable[] calldata _winnerAddressArray, uint256[] calldata _winnerPositions, uint256[] calldata _winnerAmountInWei) external payable onlyOwner returns(bool) {
    require(_winnerAddressArray.length == _winnerAmountInWei.length || _winnerAmountInWei.length == _winnerPositions.length, "Invalid winner declaration data");
    for (uint256 i = 0; i < _winnerAddressArray.length; i++) {
        winner[saleIdNow].push(_winnerAddressArray[i]);
        winningAmount[saleIdNow].push(_winnerAmountInWei[i]);
        _winnerAddressArray[i].transfer(_winnerAmountInWei[i]);
    }
    for (uint256 j = 0; j < _winningSequence.length; j++) {
        winningNumber[saleIdNow].push(_winningSequence[j]);
    }
    winningPowerBallNumber[saleIdNow] = _powerballNumber;
    saleEndTimeStamp[saleIdNow] = now;
    saleStartTimeStamp[saleIdNow + 1] = now;
    saleIdNow = saleIdNow + 1;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(!frozenAccount[_from]);
    require(block.timestamp > frozenTimestamp[_from]);
    require(_value <= balances[_from].sub(validator.validate(_from)));
    require(_value <= allowed[_from][msg.sender]);
    if (validator.containRule(_from) && _from != _to) {
        validator.addFrozenBalance(_from, _to, _value);
    }
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function multiTransfer(address[] memory _tos, uint256[] memory _values) public returns(bool) {
    require(!frozenAccount[msg.sender]);
    require(block.timestamp > frozenTimestamp[msg.sender]);
    require(_tos.length == _values.length);
    uint256 len = _tos.length;
    require(len > 0);
    uint256 amount = 0;
    for (uint256 i = 0; i < len; i = i.add(1)) {
        amount = amount.add(_values[i]);
    }
    require(amount <= balances[msg.sender].sub(validator.validate(msg.sender)));
    for (uint256 j = 0; j < len; j = j.add(1)) {
        address _to = _tos[j];
        if (validator.containRule(msg.sender) && msg.sender != _to) {
            validator.addFrozenBalance(msg.sender, _to, _values[j]);
        }
        balances[_to] = balances[_to].add(_values[j]);
        balances[msg.sender] = balances[msg.sender].sub(_values[j]);
        emit Transfer(msg.sender, _to, _values[j]);
    }
    return true;
}

function transferfix(address _to, uint256 _value) public {
    require(!frozenAccount[msg.sender]);
    require(block.timestamp > frozenTimestamp[msg.sender]);
    require(balances[msg.sender].sub(_value) >= validator.validate(msg.sender));
    if (validator.containRule(msg.sender) && msg.sender != _to) {
        validator.addFrozenBalance(msg.sender, _to, _value);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
}

function burn(address target, uint256 value) public returns(bool) {
    require(msg.sender == admin);
    require(!frozenAccount[target]);
    require(block.timestamp > frozenTimestamp[target]);
    require(totalSupply >= value);
    require(balances[target].sub(value) >= validator.validate(target));
    balances[target] = balances[target].sub(value);
    totalSupply = totalSupply.sub(value);
    emit Burn(target, value);
    emit Transfer(target, address(0), value);
    return true;
}

function mint(address target, uint256 value) public returns(bool) {
    require(msg.sender == admin);
    require(!frozenAccount[target]);
    require(block.timestamp > frozenTimestamp[target]);
    balances[target] = balances[target].add(value);
    totalSupply = totalSupply.add(value);
    emit Mint(target, value);
    emit Transfer(address(0), target, value);
    return true;
}

function shareReward(address[] memory _accounts, uint[] memory _rewards) public {
    require(_msgSender() == admin, "GasPayDistribution: Caller is not the admin");
    uint _totalRewards = 0;
    for (uint i = 0; i < _accounts.length; i++) {
        address _user = _accounts[i];
        require(_user != address(0), "GasPayDistribution: Zero address found in distribution list");
        uint _reward = _rewards[i];
        _totalRewards = _totalRewards.add(_reward);
        rewardsEarned[_user] = rewardsEarned[_user].add(_reward);
    }
    GasPayTokenAddress.transferFrom(_msgSender(), address(this), _totalRewards);
    rewardPool = rewardPool.add(_totalRewards);
    totalSharedRewards = totalSharedRewards.add(_totalRewards);
    emit _RewardShared(block.timestamp, _totalRewards);
}

function payForLevel(uint _level, address _user) internal {
    address referer;
    address referer1;
    address referer2;
    address referer3;
    address referer4;
    if (_level == 1 || _level == 6) {
        referer = userLists[users[_user].referrerID];
    } else if (_level == 2 || _level == 7) {
        referer1 = userLists[users[_user].referrerID];
        referer = userLists[users[referer1].referrerID];
    } else if (_level == 3 || _level == 8) {
        referer1 = userLists[users[_user].referrerID];
        referer2 = userLists[users[referer1].referrerID];
        referer = userLists[users[referer2].referrerID];
    } else if (_level == 4 || _level == 9) {
        referer1 = userLists[users[_user].referrerID];
        referer2 = userLists[users[referer1].referrerID];
        referer3 = userLists[users[referer2].referrerID];
        referer = userLists[users[referer3].referrerID];
    } else if (_level == 5 || _level == 10) {
        referer1 = userLists[users[_user].referrerID];
        referer2 = userLists[users[referer1].referrerID];
        referer3 = userLists[users[referer2].referrerID];
        referer4 = userLists[users[referer3].referrerID];
        referer = userLists[users[referer4].referrerID];
    }
    if (users[referer].isExist && users[referer].id > 0) {
        bool sent = false;
        if (users[referer].levelExpired[_level] >= now && users[referer].level == _level) {
            sent = address(uint160(referer)).send(LEVEL_PRICE[_level]);
            if (sent) {
                emit MoneyReceived(referer, users[referer].id, msg.sender, _level, LEVEL_PRICE[_level], now);
            }
        }
        if (!sent) {
            emit MoneyMissed(referer, users[referer].id, msg.sender, _level, LEVEL_PRICE[_level], now);
            payForLevel(_level, referer);
        }
    } else {
        cAccount.transfer(LEVEL_PRICE[_level]);
    }
}

function buyLevel(uint _level) public payable {
    require(users[msg.sender].isExist, 'User not exist');
    require(_level > 0 && _level <= 10, 'Incorrect level');
    if (_level == 1) {
        require(msg.value == LEVEL_PRICE[1], 'Incorrect Value');
        users[msg.sender].levelExpired[1] += PERIOD_LENGTH;
    } else {
        require(msg.value == LEVEL_PRICE[_level], 'Incorrect Value');
        for (uint l = _level - 1; l > 0; l--) require(users[msg.sender].levelExpired[l] >= now, 'Buy the previous level');
        if (users[msg.sender].levelExpired[_level] == 0 || users[msg.sender].levelExpired[_level] < now) {
            users[msg.sender].levelExpired[_level] = now + PERIOD_LENGTH;
        } else {
            users[msg.sender].levelExpired[_level] += PERIOD_LENGTH;
        }
    }
    users[msg.sender].level = _level;
    emit LevelBought(msg.sender, users[msg.sender].id, _level, now);
    payForLevel(_level, msg.sender);
}

function endRound(DRSDatasets.EventReturns memory _eventData_)
private
returns(DRSDatasets.EventReturns) {
    uint256 _rID = rID_;
    uint256 _winPID = round_[_rID].plyr;
    uint256 _pot = round_[_rID].pot;
    uint256 _win = getWin(_pot);
    uint256 _drsCoinDividend = getDRSCoinDividend(_pot);
    uint256 _com = getTeamPerfit(_pot);
    uint256 _newPot = _pot.sub(_win).sub(_drsCoinDividend).sub(_com);
    depositTeamPerfit(_com);
    plyr_[_winPID].win = _win.add(plyr_[_winPID].win);
    mintDRSCoin();
    drsCoin.profitEth.value(_drsCoinDividend)();
    _eventData_ = _eventData_.setRoundEndTime(round_[_rID].end);
    _eventData_ = _eventData_.setWinPID(_winPID);
    _eventData_ = _eventData_.setWinner(plyr_[_winPID].addr, plyr_[_winPID].name, _win);
    _eventData_ = _eventData_.setNewPot(_newPot);
    rID_++;
    _rID++;
    round_[_rID].strt = now;
    round_[_rID].end = now.add(rndMax_).add(rndGap_);
    keyPrice = initKeyPrice;
    keyBought = 0;
    startIndex = 0;
    endIndex = 0;
    round_[_rID].pot = _newPot;
    return _eventData_;
}

function core(uint256 _rID, uint256 _pID, uint256 _eth, DRSDatasets.EventReturns memory _eventData_) private {
    if (_eth < keyPrice) {
        plyr_[_pID].gen = plyr_[_pID].gen.add(_eth);
        emit onBuyKeyFailure(_rID, _pID, _eth, keyPrice, now);
        return;
    }
    if (plyrRnds_[_pID][_rID].keys == 0) {
        _eventData_ = managePlayer(_pID, _eventData_);
    }
    uint256 _keys = 1;
    uint256 _ethUsed = keyPrice;
    uint256 _ethLeft = _eth.sub(keyPrice);
    updateTimer(_rID);
    if (round_[_rID].plyr != _pID) {
        round_[_rID].plyr = _pID;
    }
    _eventData_ = _eventData_.setNewLeaderFlag();
    plyrRnds_[_pID][_rID].keys = _keys.add(plyrRnds_[_pID][_rID].keys);
    plyrRnds_[_pID][_rID].eth = _ethUsed.add(plyrRnds_[_pID][_rID].eth);
    round_[_rID].keys = _keys.add(round_[_rID].keys);
    round_[_rID].eth = _ethUsed.add(round_[_rID].eth);
    uint256 _ethExt = distributeExternal(_ethUsed);
    _eventData_ = distributeInternal(_rID, _ethUsed, _ethExt, _eventData_);
    bytes32 _name = plyr_[_pID].name;
    pushBuyInfo(DRSDatasets.BuyInfo(msg.sender, _name, _pID, keyPrice, keyBought));
    uint256 _keyIndex = keyBought;
    keyBought = keyBought.add(1);
    keyPrice = keyPrice.mul(1000 + keyPriceIncreaseRatio).div(1000);
    if (_ethLeft > 0) {
        plyr_[_pID].gen = _ethLeft.add(plyr_[_pID].gen);
    }
    endTx(_pID, _ethUsed, _keyIndex, _eventData_);
}

function determinePID(DRSDatasets.EventReturns memory _eventData_) private returns(DRSDatasets.EventReturns) {
    uint256 _pID = pIDxAddr_[msg.sender];
    if (_pID == 0) {
        _pID = playerBook.getPlayerID(msg.sender);
        bytes32 _name = playerBook.getPlayerName(_pID);
        pIDxAddr_[msg.sender] = _pID;
        plyr_[_pID].addr = msg.sender;
        if (_name != "") {
            pIDxName_[_name] = _pID;
            plyr_[_pID].name = _name;
            plyrNames_[_pID][_name] = true;
        }
        _eventData_ = _eventData_.setNewPlayerFlag();
    }
    return _eventData_;
}

function depositTeamPerfit(uint256 _eth) private {
    if (teamPerfit == address(0)) {
        teamPerfitAmuont = teamPerfitAmuont.add(_eth);
        return;
    }
    bool res = teamPerfit.deposit.value(_eth)();
    if (!res) {
        teamPerfitAmuont = teamPerfitAmuont.add(_eth);
        return;
    }
}

function getPlayerVaults(uint256 _pID) public view returns(uint256, uint256) {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_now > round_[_rID].end && !round_[_rID].ended && round_[_rID].plyr != 0) {
        if (round_[_rID].plyr == _pID) {
            return (
                (plyr_[_pID].win).add(getWin(round_[_rID].pot)),
                plyr_[_pID].gen
            );
        }
    }
    return (plyr_[_pID].win, plyr_[_pID].gen);
}

function reLoadCore(uint256 _pID, uint256 _eth, DRSDatasets.EventReturns memory _eventData_) private {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_now > round_[_rID].strt.add(rndGap_) && (_now <= round_[_rID].end || round_[_rID].plyr == 0)) {
        plyr_[_pID].gen = withdrawEarnings(_pID).sub(_eth);
        core(_rID, _pID, _eth, _eventData_);
    } else {
        if (_now > round_[_rID].end && !round_[_rID].ended) {
            round_[_rID].ended = true;
            _eventData_ = endRound(_eventData_);
            _eventData_ = _eventData_.setTimestamp(_now);
            _eventData_ = _eventData_.setPID(_pID);
            emit DRSEvents.onReLoadAndDistribute(
                msg.sender,
                plyr_[_pID].name,
                _eventData_.compressedData,
                _eventData_.compressedIDs,
                _eventData_.winnerAddr,
                _eventData_.winnerName,
                _eventData_.amountWon,
                _eventData_.newPot,
                _eventData_.genAmount
            );
        }
    }
}

function getTimeLeft() public view returns(uint256) {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_now < round_[_rID].end)
        if (_now > round_[_rID].strt + rndGap_)
            return (round_[_rID].end).sub(_now);
        else
            return (round_[_rID].strt + rndGap_).sub(_now);
    else
        return 0;
}

