function getPeriod(uint256 _currentDate) public pure returns(uint) {
    if (1522454400 <= _currentDate && _currentDate <= 1523059199) {
        return 0;
    }
    if (1523059200 <= _currentDate && _currentDate <= 1523923199) {
        return 1;
    }
    if (1523923200 <= _currentDate && _currentDate <= 1524787199) {
        return 2;
    }
    if (1524787200 <= _currentDate && _currentDate <= 1525651199) {
        return 3;
    }
    if (1525651200 <= _currentDate && _currentDate <= 1526515199) {
        return 4;
    }
    if (1526515200 <= _currentDate && _currentDate <= 1527811199) {
        return 5;
    }
    return 10;
}

function getAfterIcoPeriod(uint256 _currentDate) public pure returns(uint) {
    uint256 endIco = 1527811199; 
    if (endIco < _currentDate && _currentDate <= endIco + 2 years) {
        return 100;
    }
    if (endIco + 2 years < _currentDate && _currentDate <= endIco + 4 years) {
        return 200;
    }
    if (endIco + 4 years < _currentDate && _currentDate <= endIco + 6 years) {
        return 300;
    }
    if (endIco + 6 years < _currentDate && _currentDate <= endIco + 8 years) {
        return 400;
    }
    return 0;
}

function awardTAC(address winner, address loser, address referee) public {
    require(msg.sender == coopDataContract, "Only the CoopData Contract may call this function");
    ITACLockup TACLockup = ITACLockup(lockupContract);
    uint256 tokensToIssue = (athleteBase + athleteBase + poolBase + refBase) * multiplier;
    if ((tokensToIssue + reserveIssued) <= maxTokenReserve) {
        reserveIssued += tokensToIssue;
        _mint(lockupContract, athleteBase * multiplier);
        TACLockup.adjustBalance(winner, athleteBase * multiplier);
        _mint(lockupContract, athleteBase * multiplier);
        TACLockup.adjustBalance(loser, athleteBase * multiplier);
        _mint(lockupContract, refBase * multiplier);
        TACLockup.adjustBalance(referee, refBase * multiplier);
        _mint(votingPoolContract, poolBase * multiplier);
    }
}

