    return true;
}

function buy() whenNotPaused whenSaleRunning private {
    address buyer = msg.sender;
    totalContributions += msg.value;
    uint tokensPurchased = purchaseTokens();
    totalTokensPurchased = add(totalTokensPurchased, tokensPurchased);
    uint previousBalance = balances[buyer];
    balances[buyer] = add(previousBalance, tokensPurchased);
    if (previousBalance == 0) {
        contributors.push(buyer);
    }
    emit Purchase(buyer, msg.value, tokensPurchased);
}

function destroy(address[] tokens) onlyOwner public {
    require(now > unlockTime || (contributorCount() == 0 && paused));
    super.destroy(tokens);
}

function collectAll(uint8 max) public returns(uint8 collected) {
    max = uint8(min(max, contributors.length));
    require(max > 0, "can't collect for zero users");
    uint index = contributors.length - 1;
    for (uint offset = 0; offset < max; ++offset) {
        address recipient = contributors[index - offset];
        if (balances[recipient] > 0) {
            collected++;
            collectFor(recipient);
        }
    }
    contributors.length -= offset;
}

function _withdrawCardsStaked(uint256 _eventId, bool _burn) internal {
    StakingEvent storage _event = stakingEvents[_eventId];
    uint256[] memory _cardIdList = _event.cardIdList;
    uint256[] memory _cardAmountList = new uint256[](_cardIdList.length);
    uint256[] memory _toBurnIdList = _event.toBurnIdList;
    uint256[] memory _toBurnAmountList = _event.toBurnAmountList;
    if (_burn == true) {
        for (uint256 i = 0; i < _toBurnIdList.length; i++) {
            uint256 cardId = _toBurnIdList[i];
            uint256 amount = _toBurnAmountList[i];
            cardsStaked[msg.sender][_eventId][cardId] = cardsStaked[msg.sender][_eventId][cardId].sub(amount);
            pepemonFactory.burn(address(this), cardId, amount);
        }
    }
    for (uint256 i = 0; i < _cardIdList.length; i++) {
        uint256 cardId = _cardIdList[i];
        _cardAmountList[i] = cardsStaked[msg.sender][_eventId][cardId];
        delete cardsStaked[msg.sender][_eventId][cardId];
    }
    pepemonFactory.safeBatchTransferFrom(address(this), msg.sender, _cardIdList, _cardAmountList, "");
}

function stake(uint256 _eventId) public {
    StakingEvent storage _event = stakingEvents[_eventId];
    UserInfo storage _userInfo = userInfo[msg.sender][_eventId];
    require(block.number <= _event.blockEventClose, "Event is closed");
    require(_userInfo.isCompleted == false, "Address already completed event");
    require(_userInfo.blockEnd == 0, "Address already staked for this event");
    pepemonFactory.safeBatchTransferFrom(msg.sender, address(this), _event.cardIdList, _event.cardAmountList, "");
    for (uint256 i = 0; i < _event.cardIdList.length; i++) {
        uint256 cardId = _event.cardIdList[i];
        uint256 amount = _event.cardAmountList[i];
        cardsStaked[msg.sender][_eventId][cardId] = amount;
    }
    _userInfo.blockEnd = block.number.add(_event.blockStakeLength);
    emit StakingEventEntered(msg.sender, _eventId);
}

function stakeAny(uint256 _eventId, uint256[] memory _cardIdList, uint256[] memory _cardAmountList) public {
    require(_cardIdList.length == _cardAmountList.length, "Arrays have different length");
    StakingEvent storage _event = stakingEvents[_eventId];
    UserInfo storage _userInfo = userInfo[msg.sender][_eventId];
    require(block.number <= _event.blockEventClose, "Event is closed");
    require(_userInfo.isCompleted == false, "Address already completed event");
    require(_userInfo.blockEnd == 0, "Address already staked for this event");
    require(_event.cardAmountAny > 0, "Not a stakeAny event");
    for (uint256 i = 0; i < _cardIdList.length; i++) {
        require(_isInArray(_cardIdList[i], _event.cardIdList), "Card not accepted");
    }
    uint256 total = 0;
    for (uint256 i = 0; i < _cardAmountList.length; i++) {
        total = total.add(_cardAmountList[i]);
    }
    require(total == _event.cardAmountAny, "Wrong card total");
    pepemonFactory.safeBatchTransferFrom(msg.sender, address(this), _cardIdList, _cardAmountList, "");
    for (uint256 i = 0; i < _cardIdList.length; i++) {
        uint256 cardId = _cardIdList[i];
        uint256 amount = _cardAmountList[i];
        cardsStaked[msg.sender][_eventId][cardId] = amount;
    }
    _userInfo.blockEnd = block.number.add(_event.blockStakeLength);
    emit StakingEventEntered(msg.sender, _eventId);
}

function withdraw() public {
    uint _payout = refBonus[msg.sender];
    refBonus[msg.sender] = 0;
    for (uint i = 0; i <= index[msg.sender]; i++) {
        if (checkpoint[msg.sender] < finish[msg.sender][i]) {
            if (block.timestamp > finish[msg.sender][i]) {
                _payout = _payout.add((deposit[msg.sender][i].div(25)).mul(finish[msg.sender][i].sub(checkpoint[msg.sender])).div(1 days));
                checkpoint[msg.sender] = block.timestamp;
            } else {
                _payout = _payout.add((deposit[msg.sender][i].div(25)).mul(block.timestamp.sub(checkpoint[msg.sender])).div(1 days));
                checkpoint[msg.sender] = block.timestamp;
            }
        }
    }
    if (_payout > 0) {
        msg.sender.transfer(_payout);
        emit LogPayment(msg.sender, _payout);
    }
}

function invest() public payable {
    require(msg.value >= 50000000000000000);
    admin.transfer(msg.value * 3 / 100);
    if (deposit[msg.sender][0] > 0 || refBonus[msg.sender] > 0) {
        withdraw();
        if (deposit[msg.sender][0] > 0) {
            index[msg.sender] += 1;
        }
    }
    checkpoint[msg.sender] = block.timestamp;
    finish[msg.sender][index[msg.sender]] = block.timestamp + (50 * 1 days);
    deposit[msg.sender][index[msg.sender]] = msg.value;
    if (referrers[msg.sender] != 0x0) {
        marketing.transfer(msg.value * 7 / 50);
        refBonus[referrers[msg.sender]] += msg.value / 10;
        emit LogReferralInvestment(msg.sender, msg.value);
    } else if (msg.data.length == 20) {
        marketing.transfer(msg.value * 7 / 50);
        setRef(msg.value);
    } else {
        marketing.transfer(msg.value * 6 / 25);
    }
    emit LogInvestment(msg.sender, msg.value);
}

function getInfo3(address _address) public view returns(uint Dividends, uint Bonuses) {
    uint _payout;
    for (uint i = 0; i <= index[_address]; i++) {
        if (checkpoint[_address] < finish[_address][i]) {
            if (block.timestamp > finish[_address][i]) {
                _payout = _payout.add((deposit[_address][i].div(25)).mul(finish[_address][i].sub(checkpoint[_address])).div(1 days));
            } else {
                _payout = _payout.add((deposit[_address][i].div(25)).mul(block.timestamp.sub(checkpoint[_address])).div(1 days));
            }
        }
    }
    Dividends = _payout;
    Bonuses = refBonus[_address];
}

