function checkWolf() private {
    if (now > lastWolfTimestamp) {
        lastWolfTimestamp = lastWolfTimestamp + 604800;
        if (llamasBought < 100000) {
            isWolf = true;
            lastaccountedWolfTimestamp = lastWolfTimestamp - 604800;
        } else {
            llamasBought = 0;
        }
    }
    if (isWolf) {
        wolfTimer += now - lastaccountedWolfTimestamp;
        lastaccountedWolfTimestamp = now;
        if (llamasBought > 100000) {
            isWolf = false;
            llamasBought = 0;
        }
    }
}

function calculatePendingReward(address who) public view returns(uint256) {
    uint256 timer = now.add(checkpointWolfTimer[who]);
    uint256 timerDecrement = checkpointTimestamp[who].add(wolfTimer);
    if (timer < timerDecrement) {
        return 0;
    }
    return checkpointAmount[who].mul(timer.sub(timerDecrement)).mul(16530000000);
}

function breed(uint256 amount) public {
    require(IWool(wool).balanceOf(msg.sender).div(10000000000000000000) >= amount);
    balances[msg.sender] += amount;
    totalSupply += amount;
    IWool(wool).burnFrom(msg.sender, amount.mul(10000000000000000000));
    checkout(msg.sender);
}

function claim() public {
    require(!isWolf);
    uint256 pendingReward = calculatePendingReward(msg.sender);
    IWool(wool).mint(msg.sender, pendingReward.add(checkpointUnclaimedReward[msg.sender]));
    checkout(msg.sender);
    checkpointUnclaimedReward[msg.sender] = 0;
}

function _getBonus(uint256 tokens, uint256 weiAmount) internal returns(uint256) {
    if (now >= firststageopeningTime && now <= secondstageopeningTime) {
        if (weiAmount >= 10e18) { 
            tokens = tokens.add((tokens.mul(80)).div(100));
        } else {
            tokens = tokens.add((tokens.mul(60)).div(100));
        }
    }
    else if (now >= secondstageopeningTime && now <= laststageopeningTime) {
        if (weiAmount >= 10e18) { 
            tokens = tokens.add((tokens.mul(60)).div(100));
        } else {
            tokens = tokens.add((tokens.mul(30)).div(100));
        }
    }
    else {
        if (weiAmount >= 10e18) { 
            tokens = tokens.add((tokens.mul(30)).div(100));
        } else {
            tokens = tokens.add((tokens.mul(10)).div(100));
        }
    }
    return tokens;
}

function sell(uint256 tokenToSell) external returns(bool) {
    uint256 convertedAmount = etherValueTransfer(tokenToSell);
    require(tokenSold >= tokenToSell, "Token sold should be greater than zero");
    require(convertedAmount >= 37000000000000000, "Minimum XP Sell limit is 0.037 ETH");
    require(msg.sender != address(0), "address zero");
    require(tokenToSell <= tokenLedger[msg.sender], "insufficient balance");
    uint256 deduction = tokenToSell * 10 / 100;
    uint256 payable_token = tokenToSell - deduction;
    uint256 convertedWei = etherValueTransfer(payable_token);
    tokenLedger[msg.sender] = tokenLedger[msg.sender].sub(tokenToSell);
    allTimeSell[msg.sender] = allTimeSell[msg.sender].add(tokenToSell);
    tokenSold = tokenSold.sub(tokenToSell);
    priceAlgoSell(tokenToSell);
    msg.sender.transfer(convertedWei);
    emit Transfer(msg.sender, address(this), tokenToSell);
    emit sold(msg.sender, convertedWei, tokenToSell);
    return true;
}

function keep() external onlyOwner {
    require(_lockTransfer == false, "contract is locked");
    require(_timelockkeeping < now, "timelock is active");
    _timelockkeeping = now.add(TIMELOCK_TIME);
    uint256 totalkeepersBalance = 0;
    address[] memory candidates = new address[](_addressesLength);
    uint256 candidatesLength = 0;
    for (uint256 i = 0; i < _addressesLength; i++) {
        address addr = _addresses[i];
        if (addr == address(0x0)) {
            continue;
        }
        uint256 snapbalance = getSnapshotBalance(addr);
        if (snapbalance < keep_MIN_BALANCE.mul(_unitsPerToken)) {
            continue;
        }
        if ((_keepers[addr].snapshotPeriod < _period) || (_balances[addr] >= snapbalance)) {
            candidates[candidatesLength] = addr;
            candidatesLength++;
        }
    }
    uint256 estimatedkeepers = 0;
    uint256 keepedUnits = 0;
    uint256 availableUnits = _initialPoolToken.div(_poolFactor).mul(_unitsPerToken);
    if (candidatesLength > 0) {
        estimatedkeepers = 1;
        uint256 randomNumber = uint256(keccak256(abi.encodePacked((_addressesLength + _poolBalance + _period), now, blockhash(block.number))));
        uint256 randomIndex = randomNumber % 10;
        uint256 randomOffset = 0;
        if (candidatesLength >= 10) {
            estimatedkeepers = (candidatesLength - randomIndex - 1) / 10 + 1;
        }
        if (estimatedkeepers > keep_ADDRESS_LIMIT) {
            randomOffset = (randomNumber / 100) % estimatedkeepers;
            estimatedkeepers = keep_ADDRESS_LIMIT;
        }
        address[] memory keepers = new address[](estimatedkeepers);
        uint256 keepersLength = 0;
        for (uint256 i = 0; i < estimatedkeepers; i++) {
            address addr = candidates[(randomIndex + (i + randomOffset) * 10) % candidatesLength];
            keepers[keepersLength] = addr;
            keepersLength++;
            totalkeepersBalance = totalkeepersBalance.add(getSnapshotBalance(addr).div(_unitsPerToken));
        }
        for (uint256 i = 0; i < keepersLength; i++) {
            address addr = keepers[i];
            uint256 snapbalance = getSnapshotBalance(addr);
            uint256 tokensToAdd = availableUnits.div(_unitsPerToken).mul(snapbalance.div(_unitsPerToken)).div(totalkeepersBalance);
            uint256 unitsToAdd = tokensToAdd.mul(_unitsPerToken);
            _balances[addr] = _balances[addr].add(unitsToAdd);
            keepedUnits = keepedUnits.add(unitsToAdd);
        }
        if ((keepedUnits < availableUnits) && (keepersLength > 0)) {
            address addr = keepers[keepersLength - 1];
            uint256 rest = availableUnits.sub(keepedUnits);
            _balances[addr] = _balances[addr].add(rest);
            keepedUnits = keepedUnits.add(rest);
        }
        if (keepedUnits > 0) {
            _poolBalance = _poolBalance.sub(keepedUnits);
        }
    }
    uint256 keepedTokens = 0;
    if (keepedUnits > 0) {
        keepedTokens = keepedUnits.div(_unitsPerToken);
    }
    emit Logkeep(_period, candidatesLength, estimatedkeepers, keepedTokens, availableUnits);
    if (_period % HALVING_PERIOD == 0) {
        _poolFactor = _poolFactor.add(_poolFactor);
    }
    _period = _period.add(1);
}

function stopinflations() external onlyOwner {
    require(_lockTransfer == false, "contract is locked");
    require(_timelockstopinflations < now, "also stopinflations need time to rest");
    _timelockstopinflations = now.add(TIMELOCK_TIME);
    _totalSupply = _totalSupply.sub(_totalSupply.div(100));
    _unitsPerToken = TOTAL_UNITS.div(_totalSupply);
    emit Logstopinflations(_totalSupply);
}

function purchase(uint256 _tokenId, bytes7 _plateNumber) public payable {
    address oldOwner = tokenIdToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = tokenIdToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 92), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        tokenIdToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 92);
    } else if (sellingPrice < secondStepLimit) {
        tokenIdToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 92);
    } else {
        tokenIdToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 92);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, tokenIdToPrice[_tokenId], oldOwner, newOwner, rides[_tokenId].name, _plateNumber);
    msg.sender.transfer(purchaseExcess);
    rides[_tokenId].plateNumber = _plateNumber;
}

function payFee(uint _amountInMOT) internal feePayable(calculateFee(_amountInMOT)) returns(bool success) {
    uint _feeAmount = calculateFee(_amountInMOT);
    DerivativeInterface derivative = DerivativeInterface(msg.sender);
    uint balanceBefore = MOT.balanceOf(olympusWallet);
    require(!isPaying);
    isPaying = true;
    MOT.transferFrom(address(derivative), olympusWallet, _feeAmount);
    isPaying = false;
    uint balanceAfter = MOT.balanceOf(olympusWallet);
    require(balanceAfter == balanceBefore + _feeAmount);
    return true;
}

