function _play(uint _betNum, uint256 _betAmount) private returns(bool _result) {
    _result = false;
    require(!gameOver);
    require(loseNum == _betNum || _betNum == winNum || _betNum == sameNum);
    require(msg.sender != currentBanker);
    require(now < betLastTime);
    require(_betAmount >= gameMinBetAmount);
    if (_betAmount > gameMaxBetAmount) {
        _betAmount = gameMaxBetAmount;
    }
    _betAmount = _betAmount / 100 * 100;
    uint _odd = _seekOdd(_betNum, _betAmount);
    require(userEtherOf[msg.sender] >= _betAmount);
    betInfo memory bi = betInfo({
        Odd: _odd,
        Player: msg.sender,
        BetNum: _betNum,
        BetAmount: _betAmount,
        BetTime: now,
        IsReturnAward: false,
        ResultNO: 9
    });
    playerBetInfoOf[playNo] = bi;
    userEtherOf[msg.sender] = userEtherOf[msg.sender].sub(_betAmount);
    userEtherOf[this] = userEtherOf[this].add(_betAmount);
    uint _maxpooling = _getMaxPooling();
    if (userEtherOf[this] < _maxpooling) {
        uint BankerAmount = _maxpooling.sub(userEtherOf[this]);
        require(userEtherOf[currentBanker] >= BankerAmount);
        userEtherOf[currentBanker] = userEtherOf[currentBanker].sub(BankerAmount);
        userEtherOf[this] = userEtherOf[this].add(BankerAmount);
        bankerAllDeposit = bankerAllDeposit.add(BankerAmount);
    }
    emit OnPlay(gameID, playNo, msg.sender, gameName, _odd, team1, _betNum, _betAmount, now, getEventId());
    playNo = playNo.add(1);
    _result = true;
}

function canSetBanker() public view returns(bool _result) {
    _result = false;
    if (now < bankerEndTime) {
        return;
    }
    if (userEtherOf[this] == 0) {
        _result = true;
    }
}

function _checkOpenGame() private view {
    require(!gameOver);
    require(gameResult == loseNum || gameResult == winNum || gameResult == sameNum);
    require(betLastTime + 90 minutes < now);
}

function _openGamePlayNo(uint _playNo) private returns(bool _result) {
    _result = false;
    require(_playNo >= gameBeginPlayNo && _playNo < playNo);
    _checkOpenGame();
    betInfo storage p = playerBetInfoOf[_playNo];
    require(!p.IsReturnAward);
    uint256 allAmount = 0;
    _cashPrize(p, allAmount, _playNo);
    _setGameOver();
    _result = true;
}

function setGameResult(uint _gameResult) public onlyDecider {
    require(!gameOver);
    require(betLastTime + 90 minutes < now);
    require(now < betLastTime + 30 days);
    require(gameResult == 9);
    require(_gameResult == loseNum || _gameResult == winNum || _gameResult == sameNum);
    gameResult = _gameResult;
    if (gameResult == 3) {
        unpayPooling = winPooling;
    } else if (gameResult == 1) {
        unpayPooling = losePooling;
    } else if (gameResult == 0) {
        unpayPooling = samePooling;
    }
}

function setBanker(address _banker, uint _beginTime, uint _endTime) public onlyAuction returns(bool _result) {
    _result = false;
    require(_banker != 0x0);
    if (now < bankerEndTime) {
        emit OnSetNewBanker(gameID, msg.sender, _banker, _beginTime, _endTime, 1, now, getEventId());
        return;
    }
    if (userEtherOf[this] > 0) {
        emit OnSetNewBanker(gameID, msg.sender, _banker, _beginTime, _endTime, 5, now, getEventId());
        return;
    }
    if (_beginTime > now) {
        emit OnSetNewBanker(gameID, msg.sender, _banker, _beginTime, _endTime, 3, now, getEventId());
        return;
    }
    if (_endTime <= now) {
        emit OnSetNewBanker(gameID, msg.sender, _banker, _beginTime, _endTime, 4, now, getEventId());
        return;
    }
    currentBanker = _banker;
    bankerBeginTime = _beginTime;
    bankerEndTime = _endTime;
    unpayPooling = 0;
    losePooling = 0;
    winPooling = 0;
    samePooling = 0;
    bankerAllDeposit = 0;
    gameResult = 9;
    gameOver = true;
    emit OnSetNewBanker(gameID, msg.sender, _banker, _beginTime, _endTime, 0, now, getEventId());
    _result = true;
}

function newGame(string _team1, string _team2, uint _loseOdd, uint _winOdd, uint _sameOdd, uint _betLastTime, uint256 _gameMinBetAmount, uint256 _gameMaxBetAmount) public onlyBanker payable returns(bool _result) {
    if (msg.value > 0) {
        userEtherOf[msg.sender] = userEtherOf[msg.sender].add(msg.value);
    }
    require(bytes(_team1).length < 100);
    require(bytes(_team2).length < 100);
    require(gameOver);
    require(now > bankerBeginTime);
    require(_gameMinBetAmount >= 100000000000000);
    require(_gameMaxBetAmount >= _gameMinBetAmount);
    require(now < _betLastTime);
    require(_betLastTime + 1 days < bankerEndTime);
    _result = _newGame(_team1, _team2, _loseOdd, _winOdd, _sameOdd, _betLastTime, _gameMinBetAmount, _gameMaxBetAmount);
}

function failUserRefund(uint[] _playNos) public returns(bool _result) {
    _result = false;
    require(!gameOver);
    require(gameResult == 9);
    require(betLastTime + 31 days < now);
    for (uint _index = 0; _index < _playNos.length; _index++) {
        uint _playNo = _playNos[_index];
        if (_playNo >= gameBeginPlayNo && _playNo < playNo) {
            betInfo storage p = playerBetInfoOf[_playNo];
            if (!p.IsReturnAward) {
                p.IsReturnAward = true;
                uint256 ToUser = p.BetAmount;
                userEtherOf[this] = userEtherOf[this].sub(ToUser);
                userEtherOf[p.Player] = userEtherOf[p.Player].add(ToUser);
            }
        }
    }
    if (msg.sender == currentBanker && bankerAllDeposit > 0) {
        userEtherOf[this] = userEtherOf[this].sub(bankerAllDeposit);
        userEtherOf[currentBanker] = userEtherOf[currentBanker].add(bankerAllDeposit);
        bankerAllDeposit = 0;
    }
    if (userEtherOf[this] == 0) {
        gameOver = true;
    }
    _result = true;
}

function _userRefund(address _to) internal returns(bool _result) {
    require(_to != 0x0);
    require(_to != currentBanker || gameOver);
    lock();
    uint256 amount = userEtherOf[_to];
    if (amount > 0) {
        userEtherOf[msg.sender] = 0;
        _to.transfer(amount);
        _result = true;
    } else {
        _result = false;
    }
    emit OnRefund(gameID, _to, amount, _result, now, getEventId());
    unLock();
}

function _flashloan(
    uint256 handlerID,
    address receiverAddress,
    uint256 amount,
    bytes calldata params
) internal returns(bool) {
    ContractInfo memory handlerInfo;
    (handlerInfo.support, handlerInfo.addr) = dataStorageInstance.getTokenHandlerInfo(handlerID);
    require(handlerInfo.support);
    handlerInfo.tokenHandler = IProxy(handlerInfo.addr);
    IFlashloanReceiver receiver = IFlashloanReceiver(receiverAddress);
    bool success;
    uint256 fee = _getFee(handlerID, amount);
    (handlerInfo.tokenAddr, handlerInfo.expectedBalance) = _getThisBalance(handlerInfo, handlerID);
    handlerInfo.expectedBalance = handlerInfo.expectedBalance.add(_convertUnifiedToUnderlying(handlerInfo, amount)).add(_convertUnifiedToUnderlying(handlerInfo, fee));
    (success, handlerInfo.data) = handlerInfo.tokenHandler.handlerProxy(
        abi.encodeWithSelector(
            handlerInfo.handlerFunction
            .executeFlashloan.selector,
            receiverAddress,
            amount
        )
    );
    require(success);
    success = receiver.executeOperation(handlerInfo.tokenAddr, _convertUnifiedToUnderlying(handlerInfo, amount), _convertUnifiedToUnderlying(handlerInfo, fee), params);
    require(success);
    (, handlerInfo.afterBalance) = _getThisBalance(handlerInfo, handlerID);
    require(handlerInfo.expectedBalance <= handlerInfo.afterBalance);
    if (handlerID == 0) { 
        if (handlerInfo.expectedBalance < handlerInfo.afterBalance) {
            msg.sender.transfer(handlerInfo.afterBalance.sub(handlerInfo.expectedBalance));
        }
        payable(handlerInfo.addr).transfer(handlerInfo.expectedBalance);
    } else { 
        IERC20 token = IERC20(handlerInfo.tokenAddr);
        if (handlerInfo.afterBalance > handlerInfo.expectedBalance) {
            token.transfer(msg.sender, handlerInfo.afterBalance.sub(handlerInfo.expectedBalance));
        }
        token.transfer(handlerInfo.addr, handlerInfo.expectedBalance);
    }
    handlerFlashloan[handlerID].feeTotal = handlerFlashloan[handlerID].feeTotal.add(fee);
    (success, handlerInfo.data) = handlerInfo.tokenHandler.handlerProxy(
        abi.encodeWithSelector(
            handlerInfo.handlerFunction
            .depositFlashloanFee.selector,
            fee
        )
    );
    require(success);
    emit FlashLoan(receiverAddress, handlerInfo.addr, amount, fee);
    return true;
}

function withdrawFlashloanFee(uint256 handlerID) onlyOwner external returns(bool) {
    ContractInfo memory handlerInfo;
    (handlerInfo.support, handlerInfo.addr) = dataStorageInstance.getTokenHandlerInfo(handlerID);
    if (handlerInfo.support) {
        handlerInfo.tokenHandler = IProxy(handlerInfo.addr);
        (bool success, ) = handlerInfo.tokenHandler.handlerProxy(
            abi.encodeWithSelector(
                handlerInfo.handlerFunction
                .withdrawFlashloanFee.selector,
                handlerFlashloan[handlerID].feeTotal
            )
        );
        require(success);
        handlerFlashloan[handlerID].feeTotal = 0;
    }
    return true;
}

function deposit() public payable nonReentrant {
    require(controller != CFETHControllerInterface(0x0) && controller.get_current_pool() != ICurvePoolForETH(0x0), "paused");
    require(msg.value > 0, "CFVault: zero amount");
    require(slip != 0, "Slippage not set");
    uint _amount = msg.value;
    require(_amount <= max_amount, "too large amount");
    if (deposit_fee_ratio != 0 && fee_pool != address(0x0)) {
        uint256 f = _amount.safeMul(deposit_fee_ratio).safeDiv(ratio_base);
        emit CFFDepositFee(msg.sender, _amount, f);
        _amount = _amount.safeSub(f);
        if (f != 0) {
            fee_pool.call.value(f)("");
        }
    }
    uint eth_before = address(this).balance;
    uint vir = controller.get_current_pool().get_virtual_price();
    uint min_amount = _amount.safeMul(uint(1e14)).safeMul(slip).safeDiv(vir);
    uint lp_before = controller.get_current_pool().get_lp_token_balance();
    controller.get_current_pool().deposit.value(_amount)();
    uint eth_after = address(this).balance;
    uint actual_deposit = eth_before - eth_after;
    require(actual_deposit <= _amount, "deposit overflow");
    if (_amount != actual_deposit) {
        msg.sender.call.value(_amount - actual_deposit)("");
    }
    uint lp_after = controller.get_current_pool().get_lp_token_balance();
    uint256 lp_amount = lp_after.safeSub(lp_before);
    require(lp_amount >= min_amount, "Slippage");
    uint256 d = ERC20Base(controller.get_current_pool().get_lp_token_addr()).decimals();
    require(d <= 18, "invalid decimal");
    uint cff_amount = 0;
    if (lp_before == 0) {
        cff_amount = lp_amount.safeMul(uint256(10) ** 18).safeDiv(uint256(10) ** d);
    } else {
        cff_amount = lp_amount.safeMul(IERC20(lp_token).totalSupply()).safeDiv(lp_before);
    }
    TokenInterfaceETH(lp_token).generateTokens(msg.sender, cff_amount);
    emit CFFDeposit(msg.sender, actual_deposit, cff_amount, get_virtual_price());
}

function withdraw(uint256 _amount) public nonReentrant {
    require(controller != CFETHControllerInterface(0x0) && controller.get_current_pool() != ICurvePoolForETH(0x0), "paused");
    require(slip != 0, "Slippage not set");
    uint256 amount = IERC20(lp_token).balanceOf(msg.sender);
    require(amount >= _amount, "no enough LP tokens");
    uint LP_token_amount = _amount.safeMul(controller.get_current_pool().get_lp_token_balance()).safeDiv(IERC20(lp_token).totalSupply());
    uint vir = controller.get_current_pool().get_virtual_price();
    uint min_amount = _amount.safeMul(vir).safeMul(slip).safeDiv(uint(1e22));
    uint256 _before = address(this).balance;
    controller.get_current_pool().withdraw(LP_token_amount);
    uint256 _after = address(this).balance;
    uint256 eth_amount = _after.safeSub(_before);
    require(eth_amount >= min_amount, "Slippage");
    if (withdraw_fee_ratio != 0 && fee_pool != address(0x0)) {
        uint256 f = eth_amount.safeMul(withdraw_fee_ratio).safeDiv(ratio_base);
        uint256 r = eth_amount.safeSub(f);
        TokenInterfaceETH(lp_token).destroyTokens(msg.sender, _amount);
        msg.sender.call.value(r)("");
        fee_pool.call.value(f)("");
        emit CFFWithdraw(msg.sender, r, _amount, f, get_virtual_price());
    } else {
        TokenInterfaceETH(lp_token).destroyTokens(msg.sender, _amount);
        msg.sender.call.value(eth_amount)("");
        emit CFFWithdraw(msg.sender, eth_amount, _amount, 0, get_virtual_price());
    }
}

function permit(bytes32 src, bytes32 dst, bytes32 sig) public auth {
    acl[src][dst][sig] = true;
    emit LogPermit(src, dst, sig);
}

function forbid(bytes32 src, bytes32 dst, bytes32 sig) public auth {
    acl[src][dst][sig] = false;
    emit LogForbid(src, dst, sig);
}

function safeWithdrawal() public afterDeadline {
    if (returnFunds) {
        uint amount = balanceOf[msg.sender];
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                emit FundTransfer(msg.sender, amount, false);
                balanceOf[msg.sender] = 0;
                fundTransferred = fundTransferred.add(amount);
            }
        }
    }
    if (returnFunds == false && beneficiary == msg.sender) {
        uint256 ethToSend = amountRaised - fundTransferred;
        if (beneficiary.send(ethToSend)) {
            fundTransferred = fundTransferred.add(ethToSend);
        }
    }
}

function() payable public {
    uint256 bonus = 0;
    uint256 amount;
    uint256 ethamount = msg.value;
    require(!crowdsaleClosed);
    uint256 onlyAdt = ethamount.div(price);
    uint256 weiAdt = SafeMath.mul(onlyAdt, 100000000000000);
    require(isValidUser(msg.sender, weiAdt));
    balanceOf[msg.sender] = balanceOf[msg.sender].add(ethamount);
    amountRaised = amountRaised.add(ethamount);
    if (now >= preSaleStartdate && now <= preSaleDeadline) {
        amount = ethamount.div(price);
        bonus = amount * 33 / 100;
        amount = amount.add(bonus);
    } else if (now >= mainSaleStartdate && now <= mainSaleStartdate + 30 days) {
        amount = ethamount.div(price);
        bonus = amount * 25 / 100;
        amount = amount.add(bonus);
    } else if (now >= mainSaleStartdate + 30 days && now <= mainSaleStartdate + 45 days) {
        amount = ethamount.div(price);
        bonus = amount * 15 / 100;
        amount = amount.add(bonus);
    } else if (now >= mainSaleStartdate + 45 days && now <= mainSaleStartdate + 60 days) {
        amount = ethamount.div(price);
        bonus = amount * 10 / 100;
        amount = amount.add(bonus);
    } else {
        amount = ethamount.div(price);
        bonus = amount * 7 / 100;
        amount = amount.add(bonus);
    }
    amount = amount.mul(100000000000000);
    tokenReward.transfer(msg.sender, amount);
    tokenSold = tokenSold.add(amount);
    resetUserWhiteListAmount();
    emit FundTransfer(msg.sender, ethamount, true);
}

