function investInternal(address receiver, uint128 customerId) private stopInEmergency {
    if (getState() == State.PreFunding) {
        revert();
    } else if (getState() == State.Funding) {
        if (isWhiteListed) {
            if (!earlyParticipantWhitelist[receiver].status) {
                revert();
            }
        }
    } else {
        revert();
    }
    uint weiAmount = msg.value;
    uint tokenAmount = pricingStrategy.calculatePrice(weiAmount, tokensSold, token.decimals());
    if (tokenAmount == 0) {
        revert();
    }
    if (isWhiteListed) {
        if (weiAmount < earlyParticipantWhitelist[receiver].minCap && tokenAmountOf[receiver] == 0) {
            revert();
        }
        if (isBreakingInvestorCap(receiver, weiAmount)) {
            revert();
        }
        updateInheritedEarlyParticipantWhitelist(receiver, weiAmount);
    } else {
        if (weiAmount < token.minCap() && tokenAmountOf[receiver] == 0) {
            revert();
        }
    }
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    investedAmountOf[receiver] = investedAmountOf[receiver].plus(weiAmount);
    tokenAmountOf[receiver] = tokenAmountOf[receiver].plus(tokenAmount);
    weiRaised = weiRaised.plus(weiAmount);
    tokensSold = tokensSold.plus(tokenAmount);
    if (isBreakingCap(tokensSold)) {
        revert();
    }
    assignTokens(receiver, tokenAmount);
    if (!multisigWallet.send(weiAmount)) revert();
    emit Invested(receiver, weiAmount, tokenAmount, customerId);
}

function allocate(address receiver, uint256 tokenAmount, uint128 customerId, uint256 lockedTokenAmount) public onlyAllocateAgent {
    require(lockedTokenAmount <= tokenAmount);
    uint weiPrice = pricingStrategy.oneTokenInWei(tokensSold, token.decimals());
    uint256 weiAmount = (weiPrice * tokenAmount) / 10 ** uint256(token.decimals());
    weiRaised = weiRaised.plus(weiAmount);
    tokensSold = tokensSold.plus(tokenAmount);
    investedAmountOf[receiver] = investedAmountOf[receiver].plus(weiAmount);
    tokenAmountOf[receiver] = tokenAmountOf[receiver].plus(tokenAmount);
    if (lockedTokenAmount > 0) {
        tokenVesting = TokenVesting(tokenVestingAddress);
        require(!tokenVesting.isVestingSet(receiver));
        assignTokens(tokenVestingAddress, lockedTokenAmount);
        tokenVesting.setVestingWithDefaultSchedule(receiver, lockedTokenAmount);
    }
    if (tokenAmount - lockedTokenAmount > 0) {
        assignTokens(receiver, tokenAmount - lockedTokenAmount);
    }
    emit Invested(receiver, weiAmount, tokenAmount, customerId);
}

function setMaximumSellableTokens(uint tokens) public onlyOwner {
    assert(!finalized);
    assert(isUpdatable);
    assert(now <= startsAt);
    CrowdsaleExt lastTierCntrct = CrowdsaleExt(getLastTier());
    assert(!lastTierCntrct.finalized());
    maximumSellableTokens = tokens;
    emit MaximumSellableTokensChanged(maximumSellableTokens);
}

function getState() public view returns(State) {
    if (finalized) return State.Finalized;
    else if (address(finalizeAgent) == 0) return State.Preparing;
    else if (!finalizeAgent.isSane()) return State.Preparing;
    else if (!pricingStrategy.isSane()) return State.Preparing;
    else if (block.timestamp < startsAt) return State.PreFunding;
    else if (block.timestamp <= endsAt && !isCrowdsaleFull()) return State.Funding;
    else if (isMinimumGoalReached()) return State.Success;
    else return State.Failure;
}

function updateEarlyParticipantWhitelist(address addr, uint weiAmount) public {
    if (!isWhiteListed) revert();
    assert(addr != address(0));
    assert(now <= endsAt);
    assert(isTierJoined(msg.sender));
    if (weiAmount < earlyParticipantWhitelist[addr].minCap && tokenAmountOf[addr] == 0) revert();
    uint newMaxCap = earlyParticipantWhitelist[addr].maxCap;
    newMaxCap = newMaxCap.minus(weiAmount);
    earlyParticipantWhitelist[addr] = WhiteListData({
        status: earlyParticipantWhitelist[addr].status,
        minCap: 0,
        maxCap: newMaxCap
    });
}

function setEarlyParticipantWhitelist(address addr, bool status, uint minCap, uint maxCap) public onlyOwner {
    if (!isWhiteListed) revert();
    assert(addr != address(0));
    assert(maxCap > 0);
    assert(minCap <= maxCap);
    assert(now <= endsAt);
    if (!isAddressWhitelisted(addr)) {
        whitelistedParticipants.push(addr);
        emit Whitelisted(addr, status, minCap, maxCap);
    } else {
        emit WhitelistItemChanged(addr, status, minCap, maxCap);
    }
    earlyParticipantWhitelist[addr] = WhiteListData({
        status: status,
        minCap: minCap,
        maxCap: maxCap
    });
}

function setEarlyParticipantWhitelistMultiple(address[] addrs, bool[] statuses, uint[] minCaps, uint[] maxCaps)
public onlyOwner {
    if (!isWhiteListed) revert();
    assert(now <= endsAt);
    assert(addrs.length == statuses.length);
    assert(statuses.length == minCaps.length);
    assert(minCaps.length == maxCaps.length);
    for (uint iterator = 0; iterator < addrs.length; iterator++) {
        setEarlyParticipantWhitelist(addrs[iterator], statuses[iterator], minCaps[iterator], maxCaps[iterator]);
    }
}

function setStartsAt(uint time) public onlyOwner {
    assert(!finalized);
    assert(isUpdatable);
    assert(now <= time); 
    assert(time <= endsAt);
    assert(now <= startsAt);
    CrowdsaleExt lastTierCntrct = CrowdsaleExt(getLastTier());
    if (lastTierCntrct.finalized()) revert();
    uint8 tierPosition = getTierPosition(this);
    for (uint8 j = 0; j < tierPosition; j++) {
        CrowdsaleExt crowdsale = CrowdsaleExt(joinedCrowdsales[j]);
        assert(time >= crowdsale.endsAt());
    }
    startsAt = time;
    emit StartsAtChanged(startsAt);
}

function updateRate(uint oneTokenInCents) public onlyOwner {
    assert(!finalized);
    assert(isUpdatable);
    assert(now <= startsAt);
    CrowdsaleExt lastTierCntrct = CrowdsaleExt(getLastTier());
    assert(!lastTierCntrct.finalized());
    pricingStrategy.updateRate(oneTokenInCents);
}

function setEndsAt(uint time) public onlyOwner {
    assert(!finalized);
    assert(isUpdatable);
    assert(now <= time); 
    assert(startsAt <= time);
    assert(now <= endsAt);
    CrowdsaleExt lastTierCntrct = CrowdsaleExt(getLastTier());
    if (lastTierCntrct.finalized()) revert();
    uint8 tierPosition = getTierPosition(this);
    for (uint8 j = tierPosition + 1; j < joinedCrowdsalesLen; j++) {
        CrowdsaleExt crowdsale = CrowdsaleExt(joinedCrowdsales[j]);
        assert(time <= crowdsale.startsAt());
    }
    endsAt = time;
    emit EndsAtChanged(endsAt);
}

function finalize() public inState(State.Success) onlyOwner stopInEmergency {
    if (finalized) {
        revert();
    }
    if (address(finalizeAgent) != address(0)) {
        finalizeAgent.finalizeCrowdsale();
    }
    finalized = true;
}

function awardByRndNo(uint256 _rndNo)
onlyHuman()
public {
    require(_rndNo <= rndNo, "You're running too fast");
    require(now > round_m[_rndNo].endTime, "Wait patiently");
    require(round_m[_rndNo].leader == msg.sender, "The prize is not yours");
    require(round_m[_rndNo].award == false, "Can't get prizes repeatedly");
    uint256 _ethOut = ((round_m[_rndNo].eth).mul(35) / (100));
    round_m[_rndNo].award = true;
    msg.sender.transfer(_ethOut);
    emit FlyToTheMoonEvents.onAward(
        msg.sender,
        _rndNo,
        _ethOut,
        now
    );
}

function withdrawByRndNo(uint256 _rndNo)
onlyHuman()
public {
    require(_rndNo <= rndNo, "You're running too fast");
    uint256 _total = (((round_m[_rndNo].eth).mul(playerRound_m[_rndNo][msg.sender].keys)).mul(60) / ((round_m[_rndNo].keys).mul(100)));
    uint256 _withdrawed = playerRound_m[_rndNo][msg.sender].withdraw;
    require(_total > _withdrawed, "No need to withdraw");
    uint256 _ethOut = _total.sub(_withdrawed);
    playerRound_m[_rndNo][msg.sender].withdraw = _total;
    msg.sender.transfer(_ethOut);
    emit FlyToTheMoonEvents.onWithdraw(
        msg.sender,
        _rndNo,
        _ethOut,
        now
    );
}

function vestedAmount(address _beneficiary) public view returns(uint256) {
    Vesting storage vesting = vestings[_beneficiary];
    if (block.timestamp < vesting.start.add(vesting.cliff)) {
        return 0;
    } else if (block.timestamp >= vesting.start.add(vesting.duration)) {
        return vesting.totalAmount;
    } else {
        return vesting.totalAmount.mul(
            block.timestamp.sub(vesting.start)).div(vesting.duration);
    }
}

function revoke(address _beneficiary) public onlyOwner returns(bool) {
    Vesting storage vesting = vestings[_beneficiary];
    require(vesting.status == VestingStatus.ACTIVE);
    vesting.status = VestingStatus.REVOKED;
    emit Revoke(_beneficiary);
    return true;
}

function mint(
    address _beneficiary,
    uint256 _start,
    uint256 _cliff,
    uint256 _duration,
    uint256 _amount
)
public
onlyOwner
returns(bool) {
    Vesting storage vesting = vestings[_beneficiary];
    require(vesting.status == VestingStatus.NONEXISTENT);
    vesting.start = _start;
    vesting.cliff = _cliff;
    vesting.duration = _duration;
    vesting.totalAmount = _amount;
    vesting.releasedAmount = 0;
    vesting.status = VestingStatus.ACTIVE;
    emit Mint(_beneficiary, _start, _cliff, _duration, _amount);
    return true;
}

function release() public returns(bool) {
    address beneficiary = msg.sender;
    Vesting storage vesting = vestings[beneficiary];
    require(vesting.status == VestingStatus.ACTIVE);
    uint256 amount = vestedAmount(beneficiary).sub(vesting.releasedAmount);
    require(amount > 0);
    vesting.releasedAmount = vesting.releasedAmount.add(amount);
    totalSupply_ = totalSupply_.add(amount);
    balances[beneficiary] = balances[beneficiary].add(amount);
    emit Release(beneficiary, amount);
    emit Transfer(address(0), beneficiary, amount);
    return true;
}

function release() public {
    uint256 unreleased = releasableAmount();
    require(addressToken != address(0));
    require(unreleased > 0);
    released[token] = released[token].add(unreleased);
    token.safeTransfer(beneficiary, unreleased);
    emit Released(unreleased);
}

function vestedAmount() public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[token]);
    if (block.timestamp < cliff) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked[token]) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration);
    }
}

function queueTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public returns(bytes32) {
    require(msg.sender == admin, "Bentolock::queueTransaction: Call must come from admin.");
    require(eta >= getBlockTimestamp().add(delay), "Bentolock::queueTransaction: Estimated execution block must satisfy delay.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

function executeTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public payable returns(bytes memory) {
    require(msg.sender == admin, "Bentolock::executeTransaction: Call must come from admin.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "Bentolock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "Bentolock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "Bentolock::executeTransaction: Transaction is stale.");
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call.value(value)(callData);
    require(success, "Bentolock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

