function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0);
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to] + _value > balanceOf[_to]);
    if (address(spender) != address(0)) {
        spender.receiveApproval(_from, _to, address(this));
    }
    uint previousBalances = balanceOf[_from] + balanceOf[_to];
    balanceOf[_from] -= _value;
    balanceOf[_to] += _value;
    emit Transfer(_from, _to, _value);
    assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

function isDeprecated() public view returns(bool deprecated) {
    return (deprecatedSince != 0);
}

function setDeprecated(address _newAddress, string _newVersion, string _reason) external
ownerOnly
returns(bool success) {
    require(!isDeprecated());
    require(_newAddress != address(this));
    require(!Upgradable(_newAddress).isDeprecated());
    deprecatedSince = now;
    newAddress = _newAddress;
    newVersion = _newVersion;
    reason = _reason;
    emit LogSetDeprecated(_newAddress, _newVersion, _reason);
    return true;
}

function permit(
    address user,
    address spender,
    uint256 value,
    uint256 deadline,
    uint8 v,
    bytes32 r,
    bytes32 s
) external {
    require(deadline >= block.timestamp, "permit: EXPIRED");
    bytes32 digest =
        keccak256(
            abi.encodePacked(
                "\x19\x01",
                DOMAIN_SEPARATOR,
                keccak256(
                    abi.encode(
                        PERMIT_TYPEHASH,
                        user,
                        spender,
                        value,
                        nonces[user]++,
                        deadline
                    )
                )
            )
        );
    address recoveredAddress = ecrecover(digest, v, r, s);
    require(
        recoveredAddress != address(0) && recoveredAddress == user,
        "permit: INVALID_SIGNATURE"
    );
    _approve(user, spender, value);
}

