    uint256 _tokens = 0;
    if (now <= startSale + 3 days) {
        _tokens = amount * 100;
    }
    if (now > startSale + 3 days) {
        _tokens = amount * 80;
    }
    return _tokens;
}

function setSolver(address _solver) external onlyControllerOwner {
    require(_solver != address(0));
    solver = _solver;
    SolverUpdate(_solver);
}

function __callback(uint256 _requestId, bytes32 _result) external onlySolver whenSystemNotPaused {
    Request memory q = requests[_requestId];
    if (q.commitHash == _result) {
        IVerifiable(controller.getContract(keccak256("JobsManager"))).receiveVerification(q.jobId, q.claimId, q.segmentNumber, true);
        Callback(_requestId, q.jobId, q.claimId, q.segmentNumber, true);
    } else {
        IVerifiable(controller.getContract(keccak256("JobsManager"))).receiveVerification(q.jobId, q.claimId, q.segmentNumber, false);
        Callback(_requestId, q.jobId, q.claimId, q.segmentNumber, false);
    }
    delete requests[_requestId];
}

function setPriceForTokenList(address[] calldata _tokens, uint184[] calldata _prices) external onlyManager {
    require(_tokens.length == _prices.length, "TPS: Array length mismatch");
    for (uint i = 0; i < _tokens.length; i++) {
        uint64 updatedAt = tokenInfo[_tokens[i]].updatedAt;
        require(updatedAt == 0 || block.timestamp >= updatedAt + minPriceUpdatePeriod, "TPS: Price updated too early");
        tokenInfo[_tokens[i]].cachedPrice = _prices[i];
        tokenInfo[_tokens[i]].updatedAt = uint64(block.timestamp);
    }
}

function defrosting() onlyOwner public {
    uint _totalMined = 0;
    uint timePassed = now.sub(start);
    uint blockPassed = timePassed.div(blockTime);
    uint blockProfit = startBlockProfit;
    while (blockPassed > 0) {
        if (blockPassed > blockBeforeChange) {
            _totalMined = _totalMined.add(blockBeforeChange.mul(blockProfit));
            blockProfit = blockProfit.div(2);
            blockPassed = blockPassed.sub(blockBeforeChange);
        } else {
            _totalMined = _totalMined.add(blockPassed.mul(blockProfit));
            blockPassed = 0;
        }
    }
    totalMined = _totalMined;
    totalMined = totalMined.mul(1000000000000000000);
}

function() payable public goodDate belowHardCap {
