    uint tokenAmount = tokenAmountWithoutBonus + (tokenAmountWithoutBonus * bonus / 100);
    token.transferPresale(msg.sender, tokenAmount);
    raised += msg.value;
    balanceOf[msg.sender] += msg.value;
    Investing(msg.sender, msg.value, tokenAmountWithoutBonus, tokenAmount);
}

function buy(uint _cardIndex) public payable {
    require(_cardIndex <= 1000);
    require(_cardIndex > 0);
    require(cardsForSale[_cardIndex].cardIndex == _cardIndex);
    require(cardsForSale[_cardIndex].seller != msg.sender);
    require(msg.sender != address(0));
    require(msg.sender != owner);
    require(cardsForSale[_cardIndex].minValue > 0);
    require(msg.value >= cardsForSale[_cardIndex].minValue);
    address _buyer = msg.sender;
    address _seller = cardsForSale[_cardIndex].seller;
    string _name = cardsForSale[_cardIndex].name;
    uint _intName = cardsForSale[_cardIndex].intName;
    address _UnitedOwner = UnitedCardsForSale[_intName].seller;
    uint256 _price = cardsForSale[_cardIndex].minValue;
    uint256 _nextPrice = calculateNextPrice(_price);
    uint256 _devCut = calculateDevCut(_price);
    uint256 _totalPrice = _price - _devCut - (_devCut / 4);
    uint256 _extra = msg.value - _price;
    _seller.transfer(_totalPrice);
    _UnitedOwner.transfer((_devCut / 4));
    if (_extra > 0) {
        Transfer(_buyer, _buyer, _cardIndex, _extra);
        _buyer.transfer(_extra);
    }
    cardsForSale[_cardIndex].seller = _buyer;
    cardsForSale[_cardIndex].minValue = _nextPrice;
    if (_cardIndex == UnitedCardsForSale[_intName].cardIndex)
        UnitedCardsForSale[_intName].seller = _buyer;
    Transfer(_buyer, _seller, _cardIndex, _totalPrice);
    Assign(_cardIndex, _buyer, _nextPrice, _intName, _name); 
}

function claimRefund(address _ownerAddress) whenError {
    uint256 refundValue = addressToValue[_ownerAddress];
    addressToValue[_ownerAddress] = 0;
    _ownerAddress.transfer(refundValue);
    RefundClaimed(_ownerAddress, refundValue);
}

function harvest()
public
returns(uint value, uint toDividends) {
    require(stakes[msg.sender].startStaking != 0, 'You dont have stake');
    (uint value_, uint toDividends_) = harvested(msg.sender);
    require(mainToken.balanceOf(address(this)) >= (value_ + toDividends_), 'Contract doesnt have enough DES');
    stakes[msg.sender].lastHarvest = block.timestamp;
    emit Harvested(msg.sender, value_, toDividends_);
    require(mainToken.transfer(msg.sender, value_), 'Transfer issues');
    require(mainToken.transfer(dividends, toDividends_), 'Transfer issues');
    return (value_, toDividends_);
}

function stake(uint amount_)
external {
    require(stakes[msg.sender].startStaking == 0, 'You have already staked');
    require(amount_ > 0, 'Amount must be greater then zero');
    require(mainToken.balanceOf(msg.sender) >= amount_, 'You dont enough DES');
    require(maxReward(amount_) < mainToken.balanceOf(address(this)), 'Pool is empty');
    stakes[msg.sender] = Stake(block.timestamp, block.timestamp, amount_, 0);
    emit Staked(msg.sender, block.timestamp, amount_);
    mainToken.transferFrom(msg.sender, address(this), amount_);
}

function unstake()
external {
    require(stakes[msg.sender].startStaking != 0, 'You dont have stake');
    require((block.timestamp - stakes[msg.sender].startStaking) >= stakePeriod, 'Time does not pass');
    harvest();
    uint amount_ = stakes[msg.sender].amount;
    require(mainToken.balanceOf(address(this)) >= amount_, 'Contract doesnt have enough DES');
    delete stakes[msg.sender];
    emit Unstaked(msg.sender, amount_);
    require(mainToken.transfer(msg.sender, amount_), 'Transfer issues');
}

function fulfillOrder(address _user, uint256 _artBlocksProjectId, uint256 _tokenId, uint256 _expectedPriceInWeiEach, address _profitTo, bool _sendNow) public returns(uint256) {
    Order memory order = orders[_user][_artBlocksProjectId];
    require(order.quantity > 0, 'user order DNE');
    require(order.priceInWeiEach >= _expectedPriceInWeiEach, 'user offer insufficient'); 
    require(ARTBLOCKS_FACTORY.tokenIdToProjectId(_tokenId) == _artBlocksProjectId, 'user did not request this NFT');
    Order memory newOrder;
    if (order.quantity > 1) {
        newOrder.priceInWeiEach = order.priceInWeiEach;
        newOrder.quantity = order.quantity - 1;
    }
    orders[_user][_artBlocksProjectId] = newOrder;
    uint256 artBlocksBrokerFee = order.priceInWeiEach * artBlocksBrokerFeeBips / 10_000;
    balances[profitReceiver] += artBlocksBrokerFee;
    ARTBLOCKS_FACTORY.safeTransferFrom(msg.sender, _user, _tokenId); 
    if (_sendNow) {
        sendValue(payable(_profitTo), order.priceInWeiEach - artBlocksBrokerFee);
    } else {
        balances[_profitTo] += order.priceInWeiEach - artBlocksBrokerFee;
    }
    emit Action(_user, _artBlocksProjectId, newOrder.priceInWeiEach, newOrder.quantity, 'order fulfilled', _tokenId);
    return order.priceInWeiEach - artBlocksBrokerFee; 
}

function isFrozen(address _acc) internal view returns(bool frozen) {
    if (_acc == accFoundation && now < UNFREEZE_FOUNDATION)
        return true;
    return (frozenAccounts[_acc] && now < UNFREEZE_TEAM_BOUNTY);
}

function freezeUntil(address _acc, bool _isfrozen) external onlyOwner returns(bool success) {
    require(now <= UNFREEZE_TEAM_BOUNTY); 
    frozenAccounts[_acc] = _isfrozen;
    emit NewFreeze(_acc, _isfrozen);
    return true;
}

