function freezeTokens(uint256 amount) external {
    token.transferFrom(_msgSender(), address(this), amount);
    LockData storage _freezingInfo = freezingInfo[_msgSender()];
    require(_freezingInfo.balance == 0, "Already froze tokens");
    require(amount > 0, "Incorrect freeze amount");
    _freezingInfo.start = uint64(block.timestamp);
    _freezingInfo.duration = uint64(freezingTime);
    _freezingInfo.nextUnfreezeTime = uint64(block.timestamp + freezingTime.div(4));
    _freezingInfo.freezingAmount = amount;
    _freezingInfo.balance = amount;
    totalFreezingAmount = totalFreezingAmount.add(amount);
    emit Locked(_msgSender(), amount, block.timestamp + freezingTime);
}

function unfreezeTokens() external {
    LockData storage _freezingInfo = freezingInfo[_msgSender()];
    require(_freezingInfo.balance > 0, "snowman not found");
    require(_freezingInfo.nextUnfreezeTime < block.timestamp, "Next unfreeze is not unlocked");
    uint256 amount = _freezingInfo.freezingAmount.div(4);
    if (amount >= _freezingInfo.balance) {
        amount = _freezingInfo.balance;
    }
    _freezingInfo.balance = _freezingInfo.balance.sub(amount);
    _freezingInfo.nextUnfreezeTime = uint64(_freezingInfo.nextUnfreezeTime + _freezingInfo.duration.div(4));
    token.transfer(_msgSender(), amount);
    emit Unlocked(_msgSender(), amount);
}

function IsBoilerExpire(address acc, uint idx) external view returns(bool) {
    Boiler storage obj = g_Boilers[acc][idx];
    return obj.m_Expire <= now;
}

function triggerDestruction(uint ein, address[] memory firstChunk, address[] memory lastChunk, bool resetResolvers)
public _identityExists(ein) {
    require(!canRecover(ein), "Recovery has not recently been triggered.");
    Identity storage _identity = identityDirectory[ein];
    address payable[1] memory middleChunk = [msg.sender];
    require(
        keccak256(
            abi.encodePacked(firstChunk, middleChunk, lastChunk)
        ) == recoveryLogs[ein].hashedOldAssociatedAddresses,
        "Cannot destroy an EIN from an address that was not recently removed from said EIN via recovery."
    );
    emit IdentityDestroyed(msg.sender, ein, _identity.recoveryAddress, resetResolvers);
    resetIdentityData(_identity, address(0), resetResolvers);
}

function canChangeRecoveryAddress(uint ein) private view returns(bool) {
    return block.timestamp > recoveryAddressChangeLogs[ein].timestamp + recoveryTimeout;
}

function canRecover(uint ein) private view returns(bool) {
    return block.timestamp > recoveryLogs[ein].timestamp + recoveryTimeout;
}

function triggerRecovery(uint ein, address newAssociatedAddress, uint8 v, bytes32 r, bytes32 s, uint timestamp)
public _identityExists(ein) _hasIdentity(newAssociatedAddress, false) ensureSignatureTimeValid(timestamp) {
    require(canRecover(ein), "Cannot trigger recovery yet.");
    Identity storage _identity = identityDirectory[ein];
    if (canChangeRecoveryAddress(ein)) {
        require(
            msg.sender == _identity.recoveryAddress, "Only the current recovery address can trigger recovery."
        );
    } else {
        require(
            msg.sender == recoveryAddressChangeLogs[ein].oldRecoveryAddress,
            "Only the recently removed recovery address can trigger recovery."
        );
    }
    require(
        isSigned(
            newAssociatedAddress,
            keccak256(
                abi.encodePacked(
                    byte(0x19), byte(0), address(this),
                    "I authorize being added to this Identity via recovery.",
                    ein, newAssociatedAddress, timestamp
                )
            ),
            v, r, s
        ),
        "Permission denied."
    );
    recoveryLogs[ein] = Recovery(
        block.timestamp, 
        keccak256(abi.encodePacked(_identity.associatedAddresses.members))
    );
    emit RecoveryTriggered(msg.sender, ein, _identity.associatedAddresses.members, newAssociatedAddress);
    resetIdentityData(_identity, msg.sender, false);
    addAssociatedAddress(ein, newAssociatedAddress);
}

function lock(address holder, uint256 value, uint256 releaseTime) public onlyAdmin returns(bool) {
    require(releaseTime > now, "require(releaseTime > now)");
    require(_balances[holder] >= value, "There is not enough balance of holder.");
    _lock(holder, value, releaseTime);
    return true;
}

function transferWithLock(address holder, uint256 value, uint256 releaseTime) public onlyAdmin returns(bool) {
    require(releaseTime > now, "require(releaseTime > now)");
    _transfer(msg.sender, holder, value);
    _lock(holder, value, releaseTime);
    return true;
}

function createKitties() external payable {
    uint256 kittycount = kittyContract.balanceOf(msg.sender);
    require(kittyGetOrNot[msg.sender] == false);
    if (kittycount >= 99) {
        kittycount = 99;
    }
    if (kittycount > 0 && kittyToCount[msg.sender] == 0) {
        kittyToCount[msg.sender] = kittycount;
        kittyGetOrNot[msg.sender] = true;
        for (uint i = 0; i < kittycount; i++) {
            kittyToken.CreateKittyToken(msg.sender, 0, 1);
        }
        CreateKitty(kittycount, msg.sender);
    }
}

receive() external payable {
