function _transfer(address from, address to, uint256 amount) internal {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    if (to == uniswapV2Pair && from != owner()) {
        if (block.timestamp - lastSell[from] < 1 days) {
            require(amount <= daySellLimit);
            require(amount + tokensSold[from] <= daySellLimit, "Can only sell 200,000 every 24 hours");
            lastSell[from] = block.timestamp;
            tokensSold[from] = tokensSold[from].add(amount);
        } else { 
            tokensSold[from] = 0;
            require(amount <= daySellLimit, "Can only sell 200,000 every 24 hours");
            tokensSold[from] = amount;
            lastSell[from] = block.timestamp;
        }
    }
    _balances[from] = _balances[from].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[to] = _balances[to].add(amount);
    emit Transfer(from, to, amount);
}

function accrueInternal() internal {
    uint blockNumber = getBlockNumber();
    if (accrualBlockNumber == blockNumber) {
        return;
    }
    uint newSuperiorAccruedAmount = superior.accrue();
    if (totalShares == 0) {
        accrualBlockNumber = blockNumber;
        return;
    }
    uint delta = sub_(newSuperiorAccruedAmount, superiorAccruedAmount);
    Double memory ratio = fraction(delta, totalShares);
    Double memory doubleAccruedIndex = add_(Double({
        mantissa: globalAccruedIndex
    }), ratio);
    globalAccruedIndex = doubleAccruedIndex.mantissa;
    superiorAccruedAmount = newSuperiorAccruedAmount;
    accrualBlockNumber = blockNumber;
    emit Accrued(delta, doubleAccruedIndex.mantissa);
}

function claimAll() external {
    address account = msg.sender;
    accrueInternal();
    distributeInternal(account);
    AccountState storage state = accountStates[account];
    uint amount = state.accruedAmount;
    require(superior.claim(account, amount) == amount, "claim: amount mismatch");
    state.accruedAmount = 0;
    superiorAccruedAmount = sub_(superiorAccruedAmount, amount);
    emit Claimed(account, account, amount);
}

function _setPercentages(uint[] calldata newPercentages) external onlyOwner {
    uint sumNewPercentagesMantissa;
    for (uint i = 0; i < newPercentages.length; i++) {
        sumNewPercentagesMantissa = add_(sumNewPercentagesMantissa, newPercentages[i]);
    }
    require(sumNewPercentagesMantissa == mantissaOne, "_setPercentages: bad sum");
    address[] storage storedMembers = members;
    require(storedMembers.length == newPercentages.length, "_setPercentages: bad length");
    accrueInternal();
    for (uint i = 0; i < storedMembers.length; i++) {
        AccountState storage state = accountStates[storedMembers[i]];
        distributeInternal(storedMembers[i]);
        state.share = newPercentages[i];
    }
    emit Changed(storedMembers, newPercentages);
}

function _setMembers(address[] memory newMembers, uint[] memory newPercentages) public onlyOwner {
    require(newMembers.length == newPercentages.length, "_setMembers: bad length");
    uint sumNewPercentagesMantissa;
    for (uint i = 0; i < newPercentages.length; i++) {
        require(newPercentages[i] != 0, "_setMembers: bad percentage");
        sumNewPercentagesMantissa = add_(sumNewPercentagesMantissa, newPercentages[i]);
    }
    require(sumNewPercentagesMantissa == mantissaOne, "_setMembers: bad sum");
    accrueInternal();
    address[] storage storedMembers = members;
    for (uint i = 0; i < storedMembers.length; i++) {
        distributeInternal(storedMembers[i]);
        AccountState storage state = accountStates[storedMembers[i]];
        state.share = 0;
    }
    storedMembers.length = 0;
    for (uint i = 0; i < newMembers.length; i++) {
        AccountState storage state = accountStates[newMembers[i]];
        accountStates[newMembers[i]] = AccountState({
            share: newPercentages[i],
            accruedIndex: globalAccruedIndex,
            accruedAmount: state.accruedAmount
        });
        storedMembers.push(newMembers[i]);
    }
    totalShares = mantissaOne;
    emit Changed(newMembers, newPercentages);
}

function transfer(address to, uint amount) external {
    address from = msg.sender;
    accrueInternal();
    distributeInternal(from);
    AccountState storage fromState = accountStates[from];
    uint actualAmount = amount;
    if (actualAmount == 0) {
        actualAmount = fromState.accruedAmount;
    }
    require(fromState.accruedAmount >= actualAmount, "transfer: insufficient value");
    AccountState storage toState = accountStates[to];
    fromState.accruedAmount = sub_(fromState.accruedAmount, actualAmount);
    toState.accruedAmount = add_(toState.accruedAmount, actualAmount);
    emit Transferred(from, to, actualAmount);
}

function claim(address receiver, uint amount) external returns(uint) {
    address account = msg.sender;
    accrueInternal();
    distributeInternal(account);
    AccountState storage state = accountStates[account];
    require(amount <= state.accruedAmount, "claim: insufficient value");
    require(superior.claim(receiver, amount) == amount, "claim: amount mismatch");
    state.accruedAmount = sub_(state.accruedAmount, amount);
    superiorAccruedAmount = sub_(superiorAccruedAmount, amount);
    emit Claimed(account, receiver, amount);
    return amount;
}

function checkForValidChallenge(address _sender, uint _partnerId) public view returns(uint value) {
    if (hydroPartnerMap[_partnerId][_sender].timestamp > block.timestamp) {
        return hydroPartnerMap[_partnerId][_sender].value;
    }
    return 1;
}

function validateAuthentication(address _sender, uint _challenge, uint _partnerId) public constant returns(bool _isValid) {
    if (partnerMap[_partnerId][_sender].value == hydroPartnerMap[_partnerId][_sender].value &&
        block.timestamp < hydroPartnerMap[_partnerId][_sender].timestamp &&
        partnerMap[_partnerId][_sender].challenge == _challenge) {
        return true;
    }
    return false;
}

function invest() notOnPause public payable {
    fee_address.transfer(msg.value * 16 / 100);
    if (x.d(msg.sender) > 0) {
        withdraw();
    }
    x.updateInfo(msg.sender, msg.value);
    if (msg.value > top[3].deposit) {
        toTheTop();
    }
    if (x.r(msg.sender) != 0x0) {
        x.r(msg.sender).transfer(msg.value / 20);
        emit LogReferralInvestment(msg.sender, msg.value);
    } else if (msg.data.length == 20) {
        addReferrer(msg.value);
    }
    emit LogInvestment(msg.sender, msg.value);
}

function payDay() external {
    require(block.timestamp >= nextPayDay);
    nextPayDay = block.timestamp.sub((block.timestamp - 1538388000).mod(7 days)).add(7 days);
    emit LogGift(top[1].addr, top[2].addr, top[3].addr);
    for (uint i = 0; i <= 2; i++) {
        top[i + 1].addr.transfer(2 ether / 2 ** i);
        top[i + 1] = Leader(0x0, 0);
    }
}

function withdraw() notOnPause public {
    if (block.timestamp >= x.c(msg.sender) + 10 minutes) {
        uint _payout = (x.d(msg.sender).mul(12).div(1000)).mul(block.timestamp.sub(x.c(msg.sender))).div(1 days);
        x.updateCheckpoint(msg.sender);
    }
    if (_payout > 0) {
        if (_payout > address(this).balance) {
            nextWave();
            return;
        }
        msg.sender.transfer(_payout);
        emit LogPayment(msg.sender, _payout);
    }
}

function addReferrer(uint _value) internal {
    address _referrer = bytesToAddress(bytes(msg.data));
    if (_referrer != msg.sender) {
        x.addReferrer(msg.sender, _referrer);
        x.r(msg.sender).transfer(_value / 20);
        emit LogNewReferrer(msg.sender, _referrer);
        emit LogReferralInvestment(msg.sender, _value);
    }
}

function getInfo(address _address) external view returns(uint deposit, uint amountToWithdraw) {
    deposit = x.d(_address);
    if (block.timestamp >= x.c(_address) + 10 minutes) {
        amountToWithdraw = (x.d(_address).mul(12).div(1000)).mul(block.timestamp.sub(x.c(_address))).div(1 days);
    } else {
        amountToWithdraw = 0;
    }
}

