}

function approveAndCallPreSigned(
    bytes _signature,
    address _to,
    uint256 _value,
    bytes _extraData,
    uint256 _gasPrice,
    uint256 _nonce)
public
validPayload(356)
returns(bool) {
    uint256 gas = gasleft();
    address from = recoverPreSigned(_signature, approveAndCallSig, _to, _value, _extraData, _gasPrice, _nonce);
    require(from != address(0));
    require(!invalidSignatures[from][_signature]);
    invalidSignatures[from][_signature] = true;
    nonces[from]++;
    require(_approve(from, _to, _value));
    ApproveAndCallFallBack(_to).receiveApproval(from, _value, address(this), _extraData);
    if (_gasPrice > 0) {
        gas = 35000 + gas.sub(gasleft());
        require(_transfer(from, msg.sender, _gasPrice.mul(gas)));
    }
    emit SignatureRedeemed(_signature, from);
    return true;
}

function getConversions(
    address[] memory _path,
    uint256 _requestAmount,
    uint256 _feeAmount,
    uint256 _maxRateTimespan
) internal
view
returns(uint256 amountToPay, uint256 amountToPayInFees) {
    (uint256 rate, uint256 oldestTimestampRate, uint256 decimals) = chainlinkConversionPath.getRate(_path);
    require(_maxRateTimespan == 0 || block.timestamp.sub(oldestTimestampRate) <= _maxRateTimespan, "aggregator rate is outdated");
    amountToPay = _requestAmount.mul(rate).div(decimals);
    amountToPayInFees = _feeAmount.mul(rate).div(decimals);
}

