function refund() external {
    require(isFinalized == false); 
    require(isActive == true);
    require(now > fundingEndTime); 
    require(_totalSupply < tokenCreationMin + allstocksFund); 
    require(msg.sender != owner); 
    uint256 allstocksVal = balances[msg.sender];
    uint256 ethValRefund = refunds[msg.sender];
    require(allstocksVal > 0);
    require(ethValRefund > 0);
    balances[msg.sender] = 0;
    refunds[msg.sender] = 0;
    _totalSupply = _totalSupply.sub(allstocksVal); 
    uint256 ethValToken = allstocksVal / tokenExchangeRate; 
    require(ethValRefund <= ethValToken);
    msg.sender.transfer(ethValRefund); 
    LogRefund(msg.sender, ethValRefund); 
}

function finalize() external onlyOwner {
    require(isFinalized == false);
    require(msg.sender == owner); 
    require(_totalSupply >= tokenCreationMin + allstocksFund); 
    require(_totalSupply > 0);
    if (now < fundingEndTime) { 
        require(_totalSupply >= tokenCreationCap);
    } else
        require(now >= fundingEndTime);
    isFinalized = true;
    ethFundDeposit.transfer(this.balance); 
}

function createTokens(uint256 _value) internal {
    require(isFinalized == false);
    require(now >= fundingStartTime);
    require(now < fundingEndTime);
    require(msg.value > 0);
    uint256 tokens = _value.mul(tokenExchangeRate); 
    uint256 checkedSupply = _totalSupply.add(tokens);
    require(checkedSupply <= tokenCreationCap);
    _totalSupply = checkedSupply;
    balances[msg.sender] += tokens; 
    refunds[msg.sender] = _value.add(refunds[msg.sender]); 
    CreateAllstocksToken(msg.sender, tokens); 
    Transfer(address(0), owner, _totalSupply);
}

function isActive() public view returns(bool) {
    return (
        initialized == true && 
        block.timestamp >= START &&
        block.timestamp <= START.add(DAYS * 1 days) &&
        goalReached() == false
    );
}

function incise(uint256 value) public returns(uint) {
    require(jewelContract != address(0));
    uint256 balance = balances[msg.sender];
    require(balance >= value);
    uint256 count = (value / (10 ** uint256(decimals)));
    require(count >= 1);
    uint ret = jewelContract.incise(msg.sender, count);
    burn(count * 10 ** uint256(decimals));
    return ret;
}

function collect(address user, uint32[] area) public checkWhiteList whenNotPaused {
    require(address(dayQualitysContract) != address(0));
    uint32 current = uint32((now - constractDeployTime) * timeScale / 1 hours);
    require(area.length > 0);
    address _user = user;
    if (_user == address(0)) {
        _user = msg.sender;
    }
    uint total = 0;
    for (uint a = 0; a < area.length; ++a) {
        uint len = deployRange[msg.sender][area[a]].length;
        bool finish = true;
        for (uint i = 0; i < len; i += 1) {
            uint s = uint128(deployRange[msg.sender][area[a]][i]);
            uint e = uint128(deployRange[msg.sender][area[a]][i] >> 128);
            if (current < e && current >= s) {
                total += _collect(_user, uint32(s), current, area[a]);
                deployRange[msg.sender][area[a]][i] = current | (e << 128);
                finish = false;
            } else if (current >= e) {
                total += _collect(_user, uint32(s), uint32(e), area[a]);
            }
        }
        if (finish) {
            deployRange[msg.sender][area[a]].length = 0;
        } else {
            deployRange[msg.sender][area[a]][0] = deployRange[msg.sender][area[a]][len - 1];
            deployRange[msg.sender][area[a]].length = 1;
        }
    }
    ERC20(this).transfer(_user, total);
}

function _collect(address _user, uint32 start, uint32 end, uint32 area) internal returns(uint) {
    uint result = 0;
    uint32 writeCount = 1;
    uint income = 0;
    uint32[] memory totalMiners = new uint32[](CHECK_POINT_HOUR);
    uint32[] memory userMiners = new uint32[](CHECK_POINT_HOUR);
    uint32 ps = start / CHECK_POINT_HOUR * CHECK_POINT_HOUR + CHECK_POINT_HOUR;
    if (ps >= end) {
        (income, writeCount) = _collectMinersByCheckPoints(_user, area, start, end, totalMiners, userMiners, writeCount);
        result += income;
    } else {
        (income, writeCount) = _collectMinersByCheckPoints(_user, area, start, ps, totalMiners, userMiners, writeCount);
        result += income;
        while (ps < end) {
            (income, writeCount) = _collectMinersByCheckPoints(_user, area, ps, uint32(Math.min64(end, ps + CHECK_POINT_HOUR)), totalMiners, userMiners, writeCount);
            result += income;
            ps += CHECK_POINT_HOUR;
        }
    }
    Collect(_user, area, start, end, result);
    return result;
}

function _updateCheckPoints(address _user, uint32 _hour, uint32[] memory area, uint32[] memory period, uint32[] memory count) internal {
    uint32 _area = 0;
    uint32 _count = 0;
    uint32 ce4 = _hour + 4;
    uint32 ce8 = _hour + 8;
    uint32 ce24 = _hour + 24;
    uint32 cs = (_hour / CHECK_POINT_HOUR + 1) * CHECK_POINT_HOUR;
    AreaCheckPoint storage _userAreaCheckPoints = userAreaCheckPoints[_user];
    uint32 cp = 0;
    for (uint index = 0; index < area.length; ++index) {
        _area = area[index];
        _count = count[index];
        if (period[index] == 4) {
            for (cp = cs; cp <= ce4; cp += CHECK_POINT_HOUR) {
                areaCheckPoints[cp][_area] += _count;
                _userAreaCheckPoints.hour[cp][_area] += _count;
            }
        } else if (period[index] == 8) {
            for (cp = cs; cp <= ce8; cp += CHECK_POINT_HOUR) {
                areaCheckPoints[cp][_area] += _count;
                _userAreaCheckPoints.hour[cp][_area] += _count;
            }
        } else if (period[index] == 24) {
            for (cp = cs; cp <= ce24; cp += CHECK_POINT_HOUR) {
                areaCheckPoints[cp][_area] += _count;
                _userAreaCheckPoints.hour[cp][_area] += _count;
            }
        }
    }
}

function _getTotalIncomeAt(uint32 hourLength, uint32[] memory userMiners, uint32[] memory totalMiners, uint areaOutput, uint week) internal view returns(uint) {
    uint income = 0;
    for (uint i = 0; i < hourLength; ++i) {
        if (userMiners[i] != 0 && totalMiners[i] != 0) {
            income += (Math.min256(10 ** uint256(decimals), areaOutput / totalMiners[i]) * userMiners[i]);
        }
    }
    return income;
}

function adjustDeployRange(uint area, uint start, uint end) internal {
    uint len = deployRange[msg.sender][area].length;
    if (len == 0) {
        deployRange[msg.sender][area].push(start | (end << 128));
    } else {
        uint s = uint128(deployRange[msg.sender][area][len - 1]);
        uint e = uint128(deployRange[msg.sender][area][len - 1] >> 128);
        if (start >= s && start < e) {
            end = e > end ? e : end;
            deployRange[msg.sender][area][len - 1] = s | (end << 128);
        } else {
            deployRange[msg.sender][area].push(start | (end << 128));
        }
    }
}

function _getMinersByCheckPoints(address _user, uint32 area, uint32 start, uint32 end, uint32[] memory totalMiners, uint32[] memory userMiners) internal view {
    require((end - start) <= CHECK_POINT_HOUR);
    uint32 h = 0;
    int64 userInc = 0;
    int64 totalInc = 0;
    uint32[3] storage ptUser;
    uint32[3] storage ptArea;
    AreaHourDeployed storage _userAreaHourDeployed = userAreaHourDeployed[_user];
    for (h = start / CHECK_POINT_HOUR * CHECK_POINT_HOUR; h <= start; ++h) {
        ptUser = _userAreaHourDeployed.hour[h][area];
        ptArea = areaHourDeployed[h][area];
        totalInc += ptArea[0] + ptArea[1] + ptArea[2] - areaHourDeployed[h - 4][area][0] - areaHourDeployed[h - 8][area][1] - areaHourDeployed[h - 24][area][2];
        userInc += ptUser[0] + ptUser[1] + ptUser[2] - _userAreaHourDeployed.hour[h - 4][area][0] - _userAreaHourDeployed.hour[h - 8][area][1] - _userAreaHourDeployed.hour[h - 24][area][2];
    }
    totalMiners[0] = areaCheckPoints[start / CHECK_POINT_HOUR * CHECK_POINT_HOUR][area] + uint32(totalInc);
    userMiners[0] = userAreaCheckPoints[_user].hour[start / CHECK_POINT_HOUR * CHECK_POINT_HOUR][area] + uint32(userInc);
    uint32 i = 1;
    for (h = start + 1; h < end; ++h) {
        ptUser = _userAreaHourDeployed.hour[h][area];
        ptArea = areaHourDeployed[h][area];
        totalMiners[i] = totalMiners[i - 1] + ptArea[0] + ptArea[1] + ptArea[2] - areaHourDeployed[h - 4][area][0] - areaHourDeployed[h - 8][area][1] - areaHourDeployed[h - 24][area][2];
        userMiners[i] = userMiners[i - 1] + ptUser[0] + ptUser[1] + ptUser[2] - _userAreaHourDeployed.hour[h - 4][area][0] - _userAreaHourDeployed.hour[h - 8][area][1] - _userAreaHourDeployed.hour[h - 24][area][2];
        ++i;
    }
}

function withdrawMinerFee() public onlyOwner {
    require(amountEther > 0);
    owner.transfer(amountEther);
    amountEther = 0;
}

function refund(address seller, uint bidId) external returns(bool) {
    require(bids[seller][bidId].buyer == msg.sender && bids[seller][bidId].isLimited == true && bids[seller][bidId].timeout < block.number && bids[seller][bidId].status == dealStatus.Pending);
    Bid storage a = bids[seller][bidId];
    a.status = dealStatus.Refund;
    pendingWithdrawals[a.buyer] = a.price;
    withdraw(a.buyer);
    refundDone(seller, bidId);
    return true;
}

function rejectBid(address seller, uint bidId) external returns(bool) {
    if (bids[seller][bidId].isLimited == true) {
        require(bids[seller][bidId].timeout > block.number);
    }
    require(msg.sender == bids[seller][bidId].oracle && bids[seller][bidId].status == dealStatus.Pending);
    Bid storage bid = bids[seller][bidId];
    bid.status = dealStatus.Rejected;
    pendingWithdrawals[bid.oracle] = bid.fee;
    pendingWithdrawals[bid.buyer] = bid.price - bid.fee;
    withdraw(bid.buyer);
    withdraw(bid.oracle);
    bidRejected(seller, bidId);
    return true;
}

function withdraw(address person) private {
    uint amount = pendingWithdrawals[person];
    pendingWithdrawals[person] = 0;
    person.transfer(amount);
    withdrawDone(person, amount);
}

function closeBid(address seller, uint bidId) external returns(bool) {
    Bid storage bid = bids[seller][bidId];
    if (bid.isLimited == true) {
        require(bid.timeout > block.number);
    }
    require(msg.sender == bid.oracle && bid.status == dealStatus.Pending);
    bid.status = dealStatus.Closed;
    pendingWithdrawals[bid.seller] += bid.price - bid.fee;
    pendingWithdrawals[bid.oracle] += bid.fee;
    withdraw(bid.seller);
    withdraw(bid.oracle);
    bidClosed(seller, bidId);
    return true;
}

function tokenFallback(address _from, uint _value, bytes _data) public {
    require(_humanSender(_from)); 
    require(_phxToken(msg.sender));
    uint _possibleWinnings = 2 * _value;
    if (_prand(2) == 1) { 
        if (PHXTKN.balanceOf(this) >= _possibleWinnings) {
            PHXTKN.transfer(_from, _possibleWinnings);
        } else {
            PHXTKN.transfer(_from, PHXTKN.balanceOf(this));
        }
    } else {
    }
}

function _unstake(address user, uint256 amount) private returns(uint256) {
    updateAccounting(user);
    uint256 stakingSharesToBurn =
        totalStakingShares.mul(amount).div(totalStaked());
    require(
        stakingSharesToBurn > 0,
        "TokenGeyser: Unable to unstake amount this small"
    );
    UserTotals storage totals = _userTotals[user];
    Stake[] storage accountStakes = _userStakes[user];
    uint256 stakingShareSecondsToBurn = 0;
    uint256 sharesLeftToBurn = stakingSharesToBurn;
    uint256 rewardAmount = 0;
    while (sharesLeftToBurn > 0) {
        Stake storage lastStake = accountStakes[accountStakes.length - 1];
        uint256 stakeTimeSec = now.sub(lastStake.timestampSec);
        uint256 newStakingShareSecondsToBurn = 0;
        if (lastStake.stakingShares <= sharesLeftToBurn) {
            newStakingShareSecondsToBurn = lastStake.stakingShares.mul(
                stakeTimeSec
            );
            rewardAmount = computeNewReward(
                rewardAmount,
                newStakingShareSecondsToBurn,
                stakeTimeSec
            );
            stakingShareSecondsToBurn = stakingShareSecondsToBurn.add(
                newStakingShareSecondsToBurn
            );
            sharesLeftToBurn = sharesLeftToBurn.sub(
                lastStake.stakingShares
            );
            accountStakes.pop();
        } else {
            newStakingShareSecondsToBurn = sharesLeftToBurn.mul(
                stakeTimeSec
            );
            rewardAmount = computeNewReward(
                rewardAmount,
                newStakingShareSecondsToBurn,
                stakeTimeSec
            );
            stakingShareSecondsToBurn = stakingShareSecondsToBurn.add(
                newStakingShareSecondsToBurn
            );
            lastStake.stakingShares = lastStake.stakingShares.sub(
                sharesLeftToBurn
            );
            sharesLeftToBurn = 0;
        }
    }
    totals.stakingShareSeconds = totals.stakingShareSeconds.sub(
        stakingShareSecondsToBurn
    );
    totals.stakingShares = totals.stakingShares.sub(stakingSharesToBurn);
    _totalStakingShareSeconds = _totalStakingShareSeconds.sub(
        stakingShareSecondsToBurn
    );
    totalStakingShares = totalStakingShares.sub(stakingSharesToBurn);
    require(
        _stakingPool.transfer(user, amount),
        "TokenGeyser: transfer out of staking pool failed"
    );
    if (totalUnlocked() >= rewardAmount) {
        require(
            _unlockedPool.transfer(user, rewardAmount),
            "TokenGeyser: transfer out of unlocked pool failed"
        );
        emit TokensClaimed(user, rewardAmount);
        userEarnings[user] += rewardAmount;
    }
    emit Unstaked(user, amount, totalStakedFor(user), "");
    require(
        totalStakingShares == 0 || totalStaked() > 0,
        "TokenGeyser: Error unstaking. Staking shares exist, but no staking tokens do"
    );
    return rewardAmount;
}

function lockTokens(uint256 amount, uint256 durationSec)
external
onlyOwner {
    require(
        unlockSchedules.length < _maxUnlockSchedules,
        "TokenGeyser: reached maximum unlock schedules"
    );
    updateAccounting(msg.sender);
    uint256 lockedTokens = totalLocked();
    uint256 mintedLockedShares =
        (lockedTokens > 0) ?
        totalLockedShares.mul(amount).div(lockedTokens) :
        amount.mul(_initialSharesPerToken);
    UnlockSchedule memory schedule;
    schedule.initialLockedShares = mintedLockedShares;
    schedule.lastUnlockTimestampSec = now;
    schedule.endAtSec = now.add(durationSec);
    schedule.durationSec = durationSec;
    unlockSchedules.push(schedule);
    totalLockedShares = totalLockedShares.add(mintedLockedShares);
    require(
        _lockedPool.token().transferFrom(
            msg.sender,
            address(_lockedPool),
            amount
        ),
        "TokenGeyser: transfer into locked pool failed"
    );
    emit TokensLocked(amount, durationSec, totalLocked());
}

function _stakeFor(
    address staker,
    address beneficiary,
    uint256 amount
) private {
    require(amount > 0, "TokenGeyser: stake amount is zero");
    require(
        beneficiary != address(0),
        "TokenGeyser: beneficiary is zero address"
    );
    require(
        totalStakingShares == 0 || totalStaked() > 0,
        "TokenGeyser: Invalid state. Staking shares exist, but no staking tokens do"
    );
    uint256 mintedStakingShares =
        (totalStakingShares > 0) ?
        totalStakingShares.mul(amount).div(totalStaked()) :
        amount.mul(_initialSharesPerToken);
    require(
        mintedStakingShares > 0,
        "TokenGeyser: Stake amount is too small"
    );
    updateAccounting(beneficiary);
    UserTotals storage totals = _userTotals[beneficiary];
    totals.stakingShares = totals.stakingShares.add(mintedStakingShares);
    totals.lastAccountingTimestampSec = now;
    Stake memory newStake = Stake(mintedStakingShares, now);
    _userStakes[beneficiary].push(newStake);
    totalStakingShares = totalStakingShares.add(mintedStakingShares);
    require(
        _stakingPool.token().transferFrom(
            staker,
            address(_stakingPool),
            amount
        ),
        "TokenGeyser: transfer into staking pool failed"
    );
    emit Staked(beneficiary, amount, totalStakedFor(beneficiary), "");
}

function updateAccounting(address user)
public
returns(
    uint256,
    uint256,
    uint256,
    uint256,
    uint256,
    uint256
) {
    _unlockTokens();
    uint256 newStakingShareSeconds =
        now.sub(_lastAccountingTimestampSec).mul(totalStakingShares);
    _totalStakingShareSeconds = _totalStakingShareSeconds.add(
        newStakingShareSeconds
    );
    _lastAccountingTimestampSec = now;
    UserTotals storage totals = _userTotals[user];
    uint256 newUserStakingShareSeconds =
        now.sub(totals.lastAccountingTimestampSec).mul(
            totals.stakingShares
        );
    totals.stakingShareSeconds = totals.stakingShareSeconds.add(
        newUserStakingShareSeconds
    );
    totals.lastAccountingTimestampSec = now;
    uint256 totalUserRewards =
        (_totalStakingShareSeconds > 0) ?
        totalUnlocked().mul(totals.stakingShareSeconds).div(
            _totalStakingShareSeconds
        ) :
        0;
    return (
        totalLocked(),
        totalUnlocked(),
        totals.stakingShareSeconds,
        _totalStakingShareSeconds,
        totalUserRewards,
        now
    );
}

function unlockScheduleShares(uint256 s) private returns(uint256) {
    UnlockSchedule storage schedule = unlockSchedules[s];
    if (schedule.unlockedShares >= schedule.initialLockedShares) {
        return 0;
    }
    uint256 sharesToUnlock = 0;
    if (now >= schedule.endAtSec) {
        sharesToUnlock = (
            schedule.initialLockedShares.sub(schedule.unlockedShares)
        );
        schedule.lastUnlockTimestampSec = schedule.endAtSec;
    } else {
        sharesToUnlock = now
            .sub(schedule.lastUnlockTimestampSec)
            .mul(schedule.initialLockedShares)
            .div(schedule.durationSec);
        schedule.lastUnlockTimestampSec = now;
    }
    schedule.unlockedShares = schedule.unlockedShares.add(sharesToUnlock);
    return sharesToUnlock;
}

function computeNewReward(
    uint256 currentRewardTokens,
    uint256 stakingShareSeconds,
    uint256 stakeTimeSec
) private view returns(uint256) {
    uint256 newRewardTokens =
        totalUnlocked().mul(stakingShareSeconds).div(
            _totalStakingShareSeconds
        );
    if (stakeTimeSec >= bonusPeriodSec) {
        return currentRewardTokens.add(newRewardTokens);
    }
    uint256 oneHundredPct = 10 ** bonusDecimals;
    uint256 bonusedReward =
        startBonus
        .add(
            oneHundredPct.sub(startBonus).mul(stakeTimeSec).div(
                bonusPeriodSec
            )
        )
        .mul(newRewardTokens)
        .div(oneHundredPct);
    return currentRewardTokens.add(bonusedReward);
}

function _unlockTokens() private returns(uint256) {
    uint256 unlockedTokens = 0;
    uint256 lockedTokens = totalLocked();
    if (totalLockedShares == 0) {
        unlockedTokens = lockedTokens;
    } else {
        uint256 unlockedShares = 0;
        for (uint256 s = 0; s < unlockSchedules.length; s++) {
            unlockedShares = unlockedShares.add(unlockScheduleShares(s));
        }
        unlockedTokens = unlockedShares.mul(lockedTokens).div(
            totalLockedShares
        );
        totalLockedShares = totalLockedShares.sub(unlockedShares);
    }
    if (unlockedTokens > 0) {
        require(
            _lockedPool.transfer(address(_unlockedPool), unlockedTokens),
            "TokenGeyser: transfer out of locked pool failed"
        );
        emit TokensUnlocked(unlockedTokens, totalLocked());
    }
    return unlockedTokens;
}

function start_ICO() public onlyOwner atStage(Stages.PREICO) {
    require(now > pre_enddate || eth_received >= 100 ether);
    stage = Stages.ICO;
    stopped = false;
    ico1_startdate = now;
    ico_first = now + 20 days;
    ico_second = ico_first + 20 days;
    Transfer(0, address(this), balances[address(this)]);
}

function() public payable
{
    require(stage != Stages.ENDED);
    require(!stopped && msg.sender != owner);
    if (stage == Stages.PREICO && now <= pre_enddate) {
        require(eth_received <= 100 ether);
        eth_received = (eth_received).add(msg.value);
        no_of_tokens = ((msg.value).mul(_price_tokn_PRE));
        bonus_token = ((no_of_tokens).mul(50)).div(100); 
        total_token = no_of_tokens + bonus_token;
        transferTokens(msg.sender, total_token);
    } else if (stage == Stages.ICO && now <= ico_second) {
        if (now < ico_first) {
            no_of_tokens = (msg.value).mul(_price_tokn_ICO_first);
            bonus_token = ((no_of_tokens).mul(25)).div(100); 
            total_token = no_of_tokens + bonus_token;
            transferTokens(msg.sender, total_token);
        } else if (now >= ico_first && now < ico_second) {
            no_of_tokens = (msg.value).mul(_price_tokn_ICO_first);
            bonus_token = ((no_of_tokens).mul(10)).div(100); 
            total_token = no_of_tokens + bonus_token;
            transferTokens(msg.sender, total_token);
        }
    } else {
        revert();
    }
}

function end_ICO() external onlyOwner atStage(Stages.ICO) {
    require(now > ico_second);
    stage = Stages.ENDED;
    _totalsupply = (_totalsupply).sub(balances[address(this)]);
    balances[address(this)] = 0;
    Transfer(address(this), 0, balances[address(this)]);
}

function _createLiquidity() internal {
    address WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address token = 0xdff92dCc99150Df99D54BC3291bD7e5522bB1Edd; 
    address staking = _staking;
    address factory = 0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f;
    address tknETHLP = I(factory).getPair(token, WETH);
    if (tknETHLP == address(0)) {
        tknETHLP = I(factory).createPair(token, WETH);
    }
    uint ETHDeposited = address(this).balance;
    I(WETH).deposit {
        value: ETHDeposited
    }();
    I(token).transfer(tknETHLP, 1e24);
    I(WETH).transfer(tknETHLP, ETHDeposited);
    I(tknETHLP).mint(staking);
    I(staking).init(ETHDeposited, tknETHLP);
    delete _staking;
    delete _lgeOngoing;
    delete _deployer;
}

function depositEth() external payable {
    require(_lgeOngoing == true);
    uint amount = msg.value;
    uint deployerShare = amount / 200;
    amount -= deployerShare;
    _deployer.transfer(deployerShare);
    contributions[msg.sender] += amount;
    if (block.number >= 12638999) {
        _createLiquidity();
    }
}

