function getLockAccount(address addr, uint isAvailable) public constant returns(uint256) {
    uint256 total = 0;
    for (uint i = 0; i < accs[addr].length; i++) {
        if ((isAvailable == 1) && (accs[addr][i].unlockTime > now)) {
            continue;
        }
        total = add(total, accs[addr][i].count);
    }
    return total;
}

function unlock() public {
    uint[] memory d_list = new uint[](accs[msg.sender].length);
    uint dlen = 0;
    for (uint i = 0; i < accs[msg.sender].length; i++) {
        if (accs[msg.sender][i].unlockTime < now) {
            _balances[msg.sender] = add(_balances[msg.sender], accs[msg.sender][i].count);
            d_list[dlen] = i;
            dlen++;
        }
    }
    for (i = 0; i < dlen; i++) {
        delete(accs[msg.sender][d_list[i]]);
    }
}

function transferByLock(address to, uint c, uint256 lockTime, uint stages) public {
    assert(owner == msg.sender);
    assert(_balances[msg.sender] >= c);
    assert(stages >= 1);
    uint256 nowtime = now;
    assert(lockTime > nowtime);
    _balances[msg.sender] = sub(_balances[msg.sender], c);
    uint256 waittime = div(sub(lockTime, nowtime), stages);
    for (uint i = 1; i <= stages; i++) {
        accs[to].push(TokenData(div(c, stages), add(now, mul(i, waittime))));
    }
    Transfer(msg.sender, to, c);
}

function stake(uint256 _amount) public payable {
    require(paused == false, "E09");
    require(block.timestamp >= stakingStart, "E07");
    require(block.timestamp <= stakingClosed, "E08");
    require(currentStakers < maximumStakers, "E09");
    require(_amount % minimumStake == 0, 'E10');
    StakerInfo storage user = stakerInfo[msg.sender];
    require(user.amount.add(_amount) >= minimumStake, "E01");
    require(dnxcToken.transferFrom(msg.sender, address(this), _amount), "E02");
    uint256 count = _amount.div(minimumStake);
    require(msg.value >= stakingFee.mul(count), "E04");
    currentStakers = currentStakers.add(count);
    if (user.amount == 0) {
        user.startStakeTime = block.timestamp;
    }
    user.amount = user.amount.add(_amount);
    user.count = user.count.add(count);
    user.amounts.push(user.amount);
    user.times.push(block.timestamp);
}

function unstake() public {
    require(emergencyUnstake || block.timestamp >= stakingEnd || block.timestamp <= stakingClosed, "E08");
    StakerInfo storage user = stakerInfo[msg.sender];
    dnxcToken.transfer(
        msg.sender,
        user.amount
    );
    currentStakers = currentStakers.sub(user.count);
    user.amount = 0;
    user.count = 0;
}

