function bleach(uint128 skinId, uint128 attributes) external payable whenNotPaused {
    if (accountLastClearTime[msg.sender] == uint256(0)) {
        accountLastClearTime[msg.sender] = now;
    } else {
        if (accountLastClearTime[msg.sender] < levelClearTime && now > levelClearTime) {
            accountToBleachNum[msg.sender] = 0;
            accountLastClearTime[msg.sender] = now;
        }
    }
    require(accountToBleachNum[msg.sender] < bleachDailyLimit);
    accountToBleachNum[msg.sender] += 1;
    require(msg.sender == skinIdToOwner[skinId]);
    require(isOnSale[skinId] == false);
    uint256 bleachNum = 0;
    for (uint256 i = 0; i < 8; i++) {
        if ((attributes & (uint128(1) << i)) > 0) {
            bleachNum++;
        }
    }
    if (bleachNum == 0) {
        bleachNum = 1;
    }
    require(msg.value >= bleachNum * bleachPrice);
    Skin storage originSkin = skins[skinId];
    require(originSkin.mixingWithId == 0);
    uint128 newAppearance = mixFormula.bleachAppearance(originSkin.appearance, attributes);
    originSkin.appearance = newAppearance;
    Bleach(skinId, newAppearance);
}

function epoch(uint256 ETHPerToken) public onlyOwnerOrOperator {
    uint256 balance = pendingBalance();
    harvest(balance.mul(ETHPerToken).div(1 ether));
    lastEpochTime = block.timestamp;
    lastBalance = lastBalance.add(balance);
    uint256 currentWithdrawd = vault.totalYieldWithdrawed();
    uint256 withdrawAmountToken = currentWithdrawd.sub(lastYieldWithdrawed);
    if (withdrawAmountToken > 0) {
        lastYieldWithdrawed = currentWithdrawd;
        uint256 ethWithdrawed = withdrawAmountToken.mul(
            ETHPerToken
        ).div(1 ether);
        withdrawFromYearn(ethWithdrawed);
    }
}

function token2Player(address _sender, uint256 _count) public whenNotPaused returns(bool) {
    require(msg.sender == address(joyTokenContract) || msg.sender == _sender);
    require(_count > 0);
    uint256 totalTokenCount = _count.mul(exchangePlayerTokenCount);
    require(joyTokenContract.transferFrom(_sender, cfoAddress, totalTokenCount));
    uint256 typeId;
    uint256 attack;
    uint256 defense;
    uint256 stamina;
    uint256 xp;
    uint256 isKeeper;
    uint256 skillId;
    for (uint256 i = 0; i < _count; i++) {
        (typeId, attack, defense, stamina, xp, isKeeper, skillId) = randomPlayer.gen();
        _createPlayer(_sender, typeId, attack, defense, stamina, xp, isKeeper, skillId);
    }
    if (now < promoEndTime) {
        _onPromo(_sender, _count);
    }
    ExchangePlayer(_sender, _count);
    return true;
}

