    if (now > STAGE_3_FINISH) {
        return false;
    }
    return true;
}

function distribute() public onlyOwner {
    if (!ended) {
        return;
    }
    for (uint i = 0; i < buyers.length; i++) {
        address toSendTo = buyers[i];
        nft.safeTransferFrom(address(this), toSendTo, idToSend, 1, new bytes(0x0));
        buyerMapping[toSendTo] = false;
        idToSend = idToSend.add(1);
        if (idToSend > maxId) {
            idToSend = id;
        }
    }
    amountSold = amountSold.add(buyers.length);
    delete buyers;
}

function buy(uint256 amount) public payable {
    require(amountSold + buyers.length < MAX_SUPPLY, "sold out");
    require(!buyerMapping[msg.sender], "already purchased");
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= start, "early");
    require(amount <= MAX_SUPPLY, "ordered too many");
    require(amount <= 1, "ordered too many");
    require(msg.value == price.mul(amount), "wrong amount");
    uint256 balance = address(this).balance;
    uint256 hausFee = balance.div(20).mul(3);
    haus.transfer(hausFee);
    seller.transfer(address(this).balance);
    buyerMapping[msg.sender] = true;
    buyers.push(msg.sender);
    emit Buy(msg.sender, amount);
}

function withdraw(uint256 _xSHDAmountIn, bool _isUpdateSHDInBar) public {
    require(_xSHDAmountIn > 0, "Insufficient xSHDToken");
    if (_isUpdateSHDInBar) {
        swapAllForSHD();
    }
    uint256 timeForWithdraw = lockDeadline[msg.sender];
    require(now > timeForWithdraw, "still locked");
    uint256 totalShares = totalSupply;
    uint256 SHDBalance = IERC20(SHDToken).balanceOf(address(this));
    uint256 SHDAmountOut = _xSHDAmountIn.mul(SHDBalance).div(totalShares);
    _burn(msg.sender, _xSHDAmountIn);
    IERC20(SHDToken).transfer(msg.sender, SHDAmountOut);
    emit Withdraw(
        msg.sender,
        _xSHDAmountIn,
        SHDAmountOut,
        _isUpdateSHDInBar
    );
}

function returnPercPub(address investor) public view returns(uint256 _perc) {
    uint256 balanceOf = nftContract.balanceOf(investor);
    if (balanceOf < 1) {
        return 0;
    }
    (uint256 userPower, uint256 userEnergy, uint256 lastWithdrawDate, ) = nftContract.getUserData(investor);
    uint256 medianEnergy = userEnergy.div(balanceOf);
    uint256 intervalDiff = (block.timestamp).sub(lastWithdrawDate);
    if (intervalDiff.div(1 days) >= medianEnergy) {
        _perc = userPower;
    } else {
        _perc = userPower.sub(userPower.mul((medianEnergy.sub(intervalDiff.div(1 days))).div(medianEnergy)));
    }
    if (_perc.mul(5) > 4166) {
        _perc = 4166;
    } else {
        _perc = _perc.mul(5);
    }
    return _perc;
}

function returnPerc(address investor) external returns(uint256 _perc) {
    _perc = returnPercPub(investor);
    if (_perc > 0) {
        nftContract.updateDate(block.timestamp, investor);
    }
    return _perc;
}

function CreateContract(uint256 _num) public payable {
    require(msg.value > 0, "Amount must be greater than 0");
    uint256 _value = msg.value.mul(60).div(100);
    IWETH(WETH).deposit {
        value: msg.value
    }();
    if (team[_num] == address(0)) {
        IWETH(WETH).withdraw(_value);
        TransferHelper.safeTransferETH(onwer, _value);
    } else {
        IWETH(WETH).withdraw(_value);
        TransferHelper.safeTransferETH(team[_num], _value);
    }
    uint256 _EYB = msg.value.mul(1 ether).div(Price);
    _mint(msg.sender, _EYB);
    Price = Price.add(getPrice(msg.value));
}

function transfer(address _to, uint _value, bytes _data) public {
    require(_value > 0);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = subSafe(balances[msg.sender], _value);
    balances[_to] = addSafe(balances[_to], _value);
    emit Transfer(msg.sender, _to, _value, _data);
}

function() public payable {
    require(now >= createTime && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 2480;
    } else {
        tokens = msg.value * 2000;
    }
    require(tokens <= balances[owner]);
    balances[msg.sender] = addSafe(balances[msg.sender], tokens);
    balances[owner] = subSafe(balances[owner], tokens);
    emit Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function harvest(uint256 ethBalance) private returns(
    uint256 withdrawable
) {
    uint256 rewards = calculateRewards();
    uint256 depositable = ethBalance > rewards ? ethBalance.sub(rewards) : 0;
    if (depositable >= minDepositable) {
        controller.depositTokenForStrategy(
            depositable,
            address(yearnVault));
        ethPushedToYearn = ethPushedToYearn.add(
            depositable
        );
    }
    if (rewards > minRewards) {
        withdrawable = rewards > ethBalance ? rewards.sub(ethBalance) : 0;
        controller.buyForStrategy(
            rewards,
            vault.getRewardToken(),
            address(vault)
        );
    } else {
        withdrawable = 0;
    }
}

function updateLastScoreTime(address _holder) private {
    if (lastScoreTime[_holder] > 0) {
        uint timeDiff = 0;
        timeDiff = now.sub(lastScoreTime[_holder]).div(2);
        lastScoreTime[_holder] = now.sub(timeDiff);
    } else {
        lastScoreTime[_holder] = now;
    }
}

function unstake(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(tokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    emit TokenUnstaked(msg.sender, amountAfterFee, now);
    require(Token(tokenAddress).transfer(burnAddress, fee), "Could not burn fee.");
    emit TokenBurned(fee, now);
    totalUnstakedToken = totalUnstakedToken.add(amountAfterFee);
    totalFeeCollected = totalFeeCollected.add(fee);
    emit AllTokenUnStaked(totalUnstakedToken, now);
    uint timeDiff = 0;
    if (lastScoreTime[msg.sender] > 0) {
        timeDiff = now.sub(lastScoreTime[msg.sender]).div(2);
    }
    uint score = amountAfterFee
        .mul(scoreRate)
        .mul(timeDiff)
        .div(scoreInterval)
        .div(1e4);
    uint eth = score.div(scoreEth);
    totalEthClaimed = totalEthClaimed.add(eth);
    msg.sender.transfer(eth);
    emit EthClaimed(msg.sender, eth, now);
    lastScoreTime[msg.sender] = now;
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function claimScoreEth() public {
    uint timeDiff = 0;
    if (lastScoreTime[msg.sender] > 0) {
        timeDiff = now.sub(lastScoreTime[msg.sender]).div(2);
    }
    uint stakedAmount = depositedTokens[msg.sender];
    uint score = stakedAmount
        .mul(scoreRate)
        .mul(timeDiff)
        .div(scoreInterval)
        .div(1e4);
    uint eth = score.div(scoreEth);
    totalEthClaimed = totalEthClaimed.add(eth);
    msg.sender.transfer(eth);
    emit EthClaimed(msg.sender, eth, now);
    lastScoreTime[msg.sender] = now;
}

function stake(uint amountToStake) public {
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    emit TokenStaked(msg.sender, amountToStake, now);
    updateAccount(msg.sender);
    updateLastScoreTime(msg.sender);
    totalStakedToken = totalStakedToken.add(amountToStake);
    if (stakingOffer > now) {
        uint offerRaise = amountToStake.mul(stakingOfferRaise).div(1e4);
        totalOfferRaise = totalOfferRaise.add(offerRaise);
        totalOfferUser[msg.sender] = offerRaise;
        emit OfferStaked(totalStakedToken, now);
        amountToStake = amountToStake.add(offerRaise);
    }
    emit AllTokenStaked(totalStakedToken, now);
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountToStake);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function updateAccount(address account) private {
    uint pendingDivs = getPendingReward(account);
    if (pendingDivs > 0) {
        require(Token(tokenAddress).transfer(account, pendingDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsClaimed(account, pendingDivs, now);
        emit AllTokenClaimed(totalClaimedRewards, now);
    }
    lastClaimedTime[account] = now;
}

function distributeOwnedTokensFromOtherContracts(address _contract, address _recipient, uint256 _tokens) {
    require(now >= swapEndTime);
    require(msg.sender == owner);
    require(tokenBalances[_contract] >= _tokens);
    Target t = Target(_contract);
    t.transfer(_recipient, _tokens);
    tokenBalances[_contract] = sub(tokenBalances[_contract], _tokens);
}

function shareStoredTokens(address _recipient, uint256 mny) internal {
    Target t;
    uint256 share = 0;
    for (uint i = 0; i < contractCount; i++) {
        share = mul(mny, tokenShare[exchangePartners[i]]);
        t = Target(exchangePartners[i]);
        t.transfer(_recipient, share);
        tokenBalances[exchangePartners[i]] = sub(tokenBalances[exchangePartners[i]], share);
    }
}

function checkReward() public view returns(uint256) {
    uint256 amount = rewardPool.mul(_stakes[msg.sender]).div(stakingPool);
    uint256 stakingTime = block.timestamp.sub(_time[msg.sender]);
    uint256 reward = amount.mul(3).mul(stakingTime).div(10 ** 6);
    if (reward > rewardPool) {
        uint256 _reward = rewardPool.div(2);
        return _reward;
    }
    return reward;
}

function overthrow(bytes23 _decree)
public
payable {
    if (isEnded())
        return errorAndRefund("Game has already ended.");
    if (msg.sender == vars.monarch)
        return errorAndRefund("You are already the Monarch.");
    if (msg.value != fee())
        return errorAndRefund("Value sent must match fee.");
    int _newPrizeGwei = int(vars.prizeGwei) + settings.prizeIncrGwei;
    uint32 _newBlockEnded = uint32(block.number) + settings.reignBlocks;
    uint32 _newNumOverthrows = vars.numOverthrows + 1;
    address _prevMonarch = vars.monarch;
    bool _isClean = (block.number != vars.prevBlock);
    if (_newPrizeGwei < 0)
        return errorAndRefund("Overthrowing would result in a negative prize.");
    bool _wasRefundSuccess;
    if (!_isClean) {
        _wasRefundSuccess = _prevMonarch.send(msg.value);
    }
    if (_isClean) {
        vars.monarch = msg.sender;
        vars.numOverthrows = _newNumOverthrows;
        vars.prizeGwei = uint64(_newPrizeGwei);
        vars.blockEnded = _newBlockEnded;
        vars.prevBlock = uint32(block.number);
        vars.decree = _decree;
    }
    if (!_isClean && _wasRefundSuccess) {
        vars.monarch = msg.sender;
        vars.decree = _decree;
    }
    if (!_isClean && !_wasRefundSuccess) {
        vars.monarch = msg.sender;
        vars.prizeGwei = uint64(_newPrizeGwei);
        vars.numOverthrows = _newNumOverthrows;
        vars.decree = _decree;
    }
    if (!_isClean) {
        if (_wasRefundSuccess)
            emit OverthrowRefundSuccess(now, "Another overthrow occurred on the same block.", _prevMonarch, msg.value);
        else
            emit OverthrowRefundFailure(now, ".send() failed.", _prevMonarch, msg.value);
    }
    emit OverthrowOccurred(now, msg.sender, _decree, _prevMonarch, msg.value);
}

function sendPrize(uint _gasLimit)
public
returns(bool _success, uint _prizeSent) {
    if (!isEnded()) {
        emit SendPrizeError(now, "The game has not ended.");
        return (false, 0);
    }
    if (vars.isPaid) {
        emit SendPrizeError(now, "The prize has already been paid.");
        return (false, 0);
    }
    address _winner = vars.monarch;
    uint _prize = prize();
    bool _paySuccessful = false;
    vars.isPaid = true;
    if (_gasLimit == 0) {
        _paySuccessful = _winner.call.value(_prize)();
    } else {
        _paySuccessful = _winner.call.value(_prize).gas(_gasLimit)();
    }
    if (_paySuccessful) {
        emit SendPrizeSuccess({
            time: now,
            redeemer: msg.sender,
            recipient: _winner,
            amount: _prize,
            gasLimit: _gasLimit
        });
        return (true, _prize);
    } else {
        vars.isPaid = false;
        emit SendPrizeFailure({
            time: now,
            redeemer: msg.sender,
            recipient: _winner,
            amount: _prize,
            gasLimit: _gasLimit
        });
        return (false, 0);
    }
}

function settleBetCommon(Bet storage bet, uint reveal, bytes32 entropyBlockHash) private {
    uint amount = bet.amount;
    uint rollUnder = bet.rollUnder;
    address payable gambler = bet.gambler;
    require(amount != 0, "Bet should be in an 'active' state");
    applyVIPLevel(gambler, amount);
    bet.amount = 0;
    bytes32 entropy = keccak256(abi.encodePacked(reveal, entropyBlockHash));
    uint modulo = 100;
    uint dice = uint(entropy) % modulo;
    uint diceWinAmount;
    uint _jackpotFee;
    (diceWinAmount, _jackpotFee) = getDiceWinAmount(amount, rollUnder);
    uint diceWin = 0;
    uint jackpotWin = 0;
    if (modulo <= MAX_MASK_MODULO) {
        if ((2 ** dice) & bet.mask != 0) {
            diceWin = diceWinAmount;
        }
    } else {
        if (dice < rollUnder) {
            diceWin = diceWinAmount;
        }
    }
    lockedInBets -= uint128(diceWinAmount);
    if (amount >= MIN_JACKPOT_BET) {
        if ((uint(entropy) / modulo) % JACKPOT_MODULO == 0) {
            jackpotWin = jackpotSize;
            jackpotSize = 0;
        }
    }
    if (jackpotWin > 0) {
        emit JackpotPayment(gambler, jackpotWin, dice, rollUnder, amount);
    }
    if (bet.inviter != address(0)) {
        bet.inviter.transfer(amount * HOUSE_EDGE_PERCENT / 100 * 10 / 100);
    }
    todaysRewardSize += amount * HOUSE_EDGE_PERCENT / 100 * 9 / 100;
    sendFunds(gambler, diceWin + jackpotWin == 0 ? 1 wei : diceWin + jackpotWin, diceWin, dice, rollUnder, amount);
}

function applyVIPLevel(address payable gambler, uint amount) private {
    CryptoTycoonsVIPLib vipLib = CryptoTycoonsVIPLib(VIPLibraryAddress);
    uint rate = vipLib.getVIPBounusRate(gambler);
    if (rate <= 0)
        return;
    uint vipPayback = amount * rate / 10000;
    if (gambler.send(vipPayback)) {
        emit VIPPayback(gambler, vipPayback);
    }
}

function sendFunds(address payable beneficiary, uint amount, uint successLogAmount, uint dice, uint rollUnder, uint betAmount) private {
    if (beneficiary.send(amount)) {
        emit Payment(beneficiary, successLogAmount, dice, rollUnder, betAmount);
    } else {
        emit FailedPayment(beneficiary, amount);
    }
}

function payTodayReward(address payable to) external onlyOwner {
    uint prize = todaysRewardSize / 2;
    todaysRewardSize = todaysRewardSize - prize;
    if (to.send(prize)) {
        emit TodaysRankingPayment(to, prize);
    }
}

function addTxToCustomerRegistry(address _customer, uint256 _amountMCW, uint256 _amountKWh) public onlyOwner returns(bool) {
    require(isValidCustomer(_customer));
    require(_amountMCW != 0 && _amountKWh != 0);
    uint256 timestamp = now;
    bytes32 txPaymentForMCW = keccak256(
        abi.encodePacked(
            _customer,
            _amountMCW,
            _amountKWh,
            timestamp)
    );
    TxRegistry txRegistry = TxRegistry(registry[_customer]);
    require(txRegistry.getTxTimestampPaymentMCW(txPaymentForMCW) == 0);
    if (!txRegistry.addTxToRegistry(
            txPaymentForMCW,
            _amountMCW,
            _amountKWh,
            timestamp))
        revert();
    emit NewCustomerTx(
        _customer,
        txPaymentForMCW,
        _amountMCW,
        _amountKWh,
        timestamp);
    return true;
}

