function totalUnLockAmount() internal view returns(uint256 _unLockTotalAmount) {
    if (startTime == 0) {
        return 0;
    }
    if (now <= startTime) {
        return 0;
    }
    uint256 dayDiff = (now.sub(startTime)).div(1 days);
    uint256 totalUnLock = dayDiff.mul(9800).mul(1000000000000000000);
    if (totalUnLock >= (980 * 10000 * 1000000000000000000)) {
        return 980 * 10000 * 1000000000000000000;
    }
    return totalUnLock;
}

function superUnLock(address _poolAddress, uint256 _amount) public onlySuper {
    require(pool == _poolAddress, 'Mine pool address error');
    require(totalToPool.add(_amount) <= totalSupply, 'totalSupply balance low');
    uint256 _unLockTotalAmount = totalUnLockAmount();
    require(totalToPool.add(_amount) <= _unLockTotalAmount, 'Not enough dnss has been unlocked');
    balanceOf[_poolAddress] = balanceOf[_poolAddress].add(_amount);
    balanceOf[superAdmin] = balanceOf[superAdmin].sub(_amount);
    totalToPool = totalToPool.add(_amount);
}

function setTime(uint256 _startTime) public onlySuper returns(bool success) {
    require(startTime == 0, 'already started');
    require(_startTime > now, 'The start time cannot be less than or equal to the current time');
    startTime = _startTime;
    require(startTime == _startTime, 'The start time was not set successfully');
    return true;
}

function addBamm(address newBamm) external {
    require(msg.sender == admin, "!admin");
    arb.approve(newBamm);
    bamms.push(newBamm);
}

function cancelVesting() external onlyOwner {
    require(startTime > block.timestamp, "VESTING_ALREADY_STARTED");
    token.transfer(owner(), token.balanceOf(address(this)));
    startTime = ~uint256(0);
    releaseInterval = 0;
    totalReleaseCount = 0;
    paidAmount = 0;
    recipient = address(0);
}

function nextReleaseTimestamp() public view returns(uint256) {
    if (totalReleaseCount == 0 || releaseInterval == 0) {
        return 0;
    }
    if (startTime > block.timestamp) {
        return startTime.add(releaseInterval);
    }
    uint256 elapsedTime = block.timestamp.sub(startTime);
    uint256 pastReleaseCount = elapsedTime.div(releaseInterval);
    if (pastReleaseCount > totalReleaseCount) {
        return 0;
    }
    return startTime.add(releaseInterval.mul(pastReleaseCount + 1));
}

function unStake(address user, uint256 stakeId) external whenNotPaused {
    require(
        msg.sender == user || msg.sender == _owner,
        "UNSTAKE: Invalid User Entry"
    );
    (,
        address[] memory tokenAddress,
        bool[] memory activeStatus, , ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = (uniV3.viewStakingDetails(user));
    bool isAlreadyUnstaked = uniV3Proxy.unstakeStatus(user, stakeId);
    require(
        u3UpgradeLockableDetails[tokenAddress[stakeId]].lockableDays <=
        block.timestamp,
        "Token Locked"
    );
    if (
        u3UpgradeLockableDetails[tokenAddress[stakeId]].optionableStatus ==
        true
    ) {
        require(
            poolStartTime.add(uniV3.stakeDuration()) <= block.timestamp,
            "Locked in optional lock"
        );
    }
    if (
        u3UnstakeStatus[user][stakeId] == false &&
        isAlreadyUnstaked == false &&
        activeStatus[stakeId] == true
    ) u3UnstakeStatus[user][stakeId] = true;
    else revert("UNSTAKE : Unstaked Already");
    (address stakedToken, uint256 totalStaking) = swapPaidToken(
        tokenAddress[stakeId]
    );
    u3UpgradeTotalUnStaking[stakedToken] = u3UpgradeTotalUnStaking[
        stakedToken
    ].add(stakedAmount[stakeId]);
    require(
        IERC20(stakedToken).balanceOf(address(this)) >=
        stakedAmount[stakeId],
        "UNSTAKE : Insufficient Balance"
    );
    IERC20(stakedToken).transfer(user, stakedAmount[stakeId]);
    if (startTime[stakeId] < poolStartTime.add(uniV3.stakeDuration())) {
        claimRewards(user, stakeId, totalStaking);
    }
    emit UnStake(
        user,
        stakedToken,
        stakedAmount[stakeId],
        block.timestamp,
        stakeId
    );
}

function claimRewards(
    address user,
    uint256 stakeId,
    uint256 totalStaking
) internal {
    (
        address[] memory referrerAddress,
        address[] memory tokenAddress, , , ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = (uniV3.viewStakingDetails(user));
    uint256 interval;
    uint256 endOfProfit;
    interval = poolStartTime.add(uniV3.stakeDuration());
    if (interval > block.timestamp) endOfProfit = block.timestamp;
    else endOfProfit = poolStartTime.add(uniV3.stakeDuration());
    interval = endOfProfit.sub(startTime[stakeId]);
    if (interval >= HOURS)
        _rewardCalculation(
            user,
            referrerAddress[stakeId],
            tokenAddress[stakeId],
            stakedAmount[stakeId],
            interval,
            totalStaking
        );
}

