function _payPercents(address _user, uint128 _charged)
internal {
    uint128 refAmount = referrers[_user] != address(0) ? _charged * refPercent / DENOMINATOR : 0;
    uint128 devAmount = _charged * devPercent / DENOMINATOR;
    uint128 govAmount = _charged * govPercent / DENOMINATOR;
    uint128 nftAmount = uint128(_charged.sub(refAmount).sub(devAmount).sub(govAmount));
    if (refAmount > 0) {
        balances[referrers[_user]].lastBalance = uint128(balances[referrers[_user]].lastBalance.add(refAmount));
        emit AffiliatePaid(referrers[_user], _user, refAmount, block.timestamp);
    }
    if (devAmount > 0) balances[devWallet].lastBalance = uint128(balances[devWallet].lastBalance.add(devAmount));
    if (govAmount > 0) balances[getModule("GOVSTAKE")].lastBalance = uint128(balances[getModule("GOVSTAKE")].lastBalance.add(govAmount));
    if (nftAmount > 0) balances[getModule("REWARDV2")].lastBalance = uint128(balances[getModule("REWARDV2")].lastBalance.add(nftAmount));
}

function permit(address owner, address spender, uint amount, uint deadline, uint8 v, bytes32 r, bytes32 s) external whenNotPaused {
    bytes32 structHash = keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, amount, nonces[owner]++, deadline));
    bytes32 digest = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash));
    address signatory = ecrecover(digest, v, r, s);
    require(signatory != address(0), "NBU::permit: invalid signature");
    require(signatory == owner, "NBU::permit: unauthorized");
    require(block.timestamp <= deadline, "NBU::permit: signature expired");
    _allowances[owner][spender] = amount;
    emit Approval(owner, spender, amount);
}

function availableForUnvesting(address user) external view returns(uint unvestAmount) {
    if (_vestingNonces[user] == 0) return 0;
    for (uint i = 1; i <= _vestingNonces[user]; i++) {
        if (_vestingAmounts[user][i] == _unvestedAmounts[user][i]) continue;
        if (_vestingReleaseStartDates[user][i] > block.timestamp) break;
        uint toUnvest = block.timestamp.sub(_vestingReleaseStartDates[user][i]).mul(_vestingAmounts[user][i]) / vestingSecondPeriod;
        if (toUnvest > _vestingAmounts[user][i]) {
            toUnvest = _vestingAmounts[user][i];
        }
        toUnvest = toUnvest.sub(_unvestedAmounts[user][i]);
        unvestAmount = unvestAmount.add(toUnvest);
    }
}

function unvest() external whenNotPaused returns(uint unvested) {
    require(_vestingNonces[msg.sender] > 0, "NBU::unvest:No vested amount");
    for (uint i = 1; i <= _vestingNonces[msg.sender]; i++) {
        if (_vestingAmounts[msg.sender][i] == _unvestedAmounts[msg.sender][i]) continue;
        if (_vestingReleaseStartDates[msg.sender][i] > block.timestamp) break;
        uint toUnvest = block.timestamp.sub(_vestingReleaseStartDates[msg.sender][i]).mul(_vestingAmounts[msg.sender][i]) / vestingSecondPeriod;
        if (toUnvest > _vestingAmounts[msg.sender][i]) {
            toUnvest = _vestingAmounts[msg.sender][i];
        }
        uint totalUnvestedForNonce = toUnvest;
        toUnvest = toUnvest.sub(_unvestedAmounts[msg.sender][i]);
        unvested = unvested.add(toUnvest);
        _unvestedAmounts[msg.sender][i] = totalUnvestedForNonce;
    }
    _unfrozenBalances[msg.sender] = _unfrozenBalances[msg.sender].add(unvested);
    emit Unvest(msg.sender, unvested);
}

function proposeUpgrade(address _newVersion) public onlyAssetOwner() returns(bool) {
    if (pendingVersion != 0x0) {
        return false;
    }
    if (_newVersion == 0x0) {
        return false;
    }
    if (latestVersion == 0x0) {
        latestVersion = _newVersion;
        return true;
    }
    pendingVersion = _newVersion;
    pendingVersionTimestamp = now;
    emit UpgradeProposed(_newVersion);
    return true;
}

function purgeUpgrade() public onlyAssetOwner() returns(bool) {
    if (pendingVersion == 0x0) {
        return false;
    }
    emit UpgradePurged(pendingVersion);
    delete pendingVersion;
    delete pendingVersionTimestamp;
    return true;
}

function commitUpgrade() public returns(bool) {
    if (pendingVersion == 0x0) {
        return false;
    }
    if (pendingVersionTimestamp + UPGRADE_FREEZE_TIME > now) {
        return false;
    }
    latestVersion = pendingVersion;
    delete pendingVersion;
    delete pendingVersionTimestamp;
    emit UpgradeCommited(latestVersion);
    return true;
}

function _attack(uint _heroId, uint _genes, uint _heroStrength, uint _heroCurrentHealth) internal {
    Monster storage monster = heroIdToMonster[_heroId];
    uint8 currentLevel = monster.level;
    uint heroPower;
    (heroPower, , , , ) = edCoreContract.getHeroPower(_genes, dungeonDifficulty);
    uint damageByMonster;
    if (now > monster.creationTime + monsterFleeTime) {
        damageByMonster = currentLevel + monsterStrength;
    } else {
        if (currentLevel >= 2) {
            damageByMonster = _getRandomNumber(currentLevel / 2);
        }
    }
    if (damageByMonster >= _heroCurrentHealth) {
        heroIdToHealth[_heroId] = 0;
        uint addToJackpot = entranceFee - heroIdToRefundedFee[_heroId];
        jackpot += addToJackpot;
        entranceFeePool -= addToJackpot;
        assert(addToJackpot <= entranceFee);
    } else {
        heroIdToHealth[_heroId] -= damageByMonster;
        currentLevel++;
        heroIdToMonster[_heroId] = Monster(uint64(monster.creationTime + monsterFleeTime),
            currentLevel, currentLevel * monsterHealth, currentLevel * monsterHealth);
        monster = heroIdToMonster[_heroId];
    }
    uint damageByHero = (_heroStrength + heroPower / (10 * (1 + _getRandomNumber(5)))) / tx.gasprice / 1e9;
    bool isMonsterDefeated = damageByHero >= monster.health;
    uint rewards;
    if (isMonsterDefeated) {
        uint8 newLevel = currentLevel + 1;
        heroIdToMonster[_heroId] = Monster(uint64(now), newLevel, newLevel * monsterHealth, newLevel * monsterHealth);
        monster = heroIdToMonster[_heroId];
        if (currentLevel == checkpointLevel) {
            rewards = entranceFee / 2;
            heroIdToRefundedFee[_heroId] += rewards;
            entranceFeePool -= rewards;
        } else if (currentLevel == breakevenLevel) {
            rewards = entranceFee / 2;
            heroIdToRefundedFee[_heroId] += rewards;
            entranceFeePool -= rewards;
        } else if (currentLevel == jackpotLevel) {
            rewards = jackpot / 2;
            jackpot -= rewards;
        }
        msg.sender.transfer(rewards);
    } else {
        monster.health -= uint8(damageByHero);
    }
    LogAttack(now, msg.sender, _heroId, currentLevel, damageByHero, damageByMonster, isMonsterDefeated, rewards);
}

