function() payable isCrowdsale beforeDeadline public {
    uint amount = msg.value;
    if (amount == 0) revert(); 
    else if (amount < 250 finney) {
        if (sehrRaised < fundingGoal) {
            if (now < startTime + 31 days) revert(); 
        }
    }
    uint tokenAmount = (amount / price) * 1 ether; 
    if (sehrRaised < fundingGoal) { 
        if (now < startTime + 10 days) {
            tokenAmount = (13 * tokenAmount) / 10; 
        } else if (now < startTime + 20 days) {
            tokenAmount = (12 * tokenAmount) / 10; 
        } else if (now < startTime + 31 days) {
            tokenAmount = (11 * tokenAmount) / 10; 
        }
    }
    balanceOf[msg.sender] += amount;
    amountRaised += amount;
    sehrRaised += tokenAmount;
    tokenReward.transferFrom(SEHR_WALLET_ADDRESS, msg.sender, tokenAmount); 
    emit FundTransfer(msg.sender, amount, true);
}

function safeWithdrawal() afterDeadline isCheckDone public {
    if (!fundingGoalReached) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                emit FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (fundingGoalReached && SSOTHEALTH_FUNDS_ADDRESS == msg.sender) {
        if (SSOTHEALTH_FUNDS_ADDRESS.send(amountRaised)) {
            emit FundTransfer(SSOTHEALTH_FUNDS_ADDRESS, amountRaised, false);
        } else {
            fundingGoalReached = false;
        }
    }
}

function() payable public {
    require(msg.value > 0);
    require(now > startDate);
    require(now < endDate);
    require(whitelist[msg.sender]);
    if (categorie1[msg.sender] == false) {
    }
    uint256 amount = msg.value * price;
    if (now > startDate && now <= bonusDate) {
        uint256 _amount = amount / 10;
        amount += _amount * 3;
    }
    balanceOfEther[msg.sender] += msg.value / 1 ether;
    tokenReward.transfer(msg.sender, amount);
    FundTransfer(msg.sender, amount, true);
    owner.transfer(msg.value);
}

function finalize() public onlyOwner onlyInitialized {
    require(!isFinalized);
    require(preSaleTokens == 0);
    Stage storage lastStage = stages[stages.length - 1];
    require(getNow() >= lastStage.endDate || (lastStage.cap == 0 && icoTokensLeft == 0));
    token.finishMinting();
    token.transferOwnership(owner);
    communityLock.transferOwnership(owner); 
    emit Finalized(); 
    isFinalized = true;
}

function mintTokens(address[] _receivers, uint256[] _amounts) external onlyInitialized {
    require(msg.sender == tokenMinter || msg.sender == owner);
    require(_receivers.length > 0 && _receivers.length <= 100);
    require(_receivers.length == _amounts.length);
    require(!isFinalized);
    ensureCurrentStage();
    address receiver;
    uint256 amount;
    uint256 excessTokens;
    for (uint256 i = 0; i < _receivers.length; i++) {
        receiver = _receivers[i];
        amount = _amounts[i];
        require(receiver != address(0));
        require(amount > 0);
        excessTokens = updateStageCap(amount);
        uint256 tokens = amount.sub(excessTokens);
        token.mint(receiver, tokens, '');
        if (excessTokens > 0) {
            emit ManualTokenMintRequiresRefund(receiver, excessTokens); 
        }
    }
}

function buyTokens(address _beneficiary) public payable onlyInitialized {
    require(_beneficiary != address(0));
    ensureCurrentStage();
    validatePurchase();
    uint256 weiReceived = msg.value;
    uint256 usdReceived = weiToUsd(weiReceived);
    uint8 stageIndex = currentStage;
    uint256 tokens = usdToTokens(usdReceived, stageIndex);
    uint256 weiToReturn = 0;
    uint256 excessTokens = updateStageCap(tokens);
    if (excessTokens > 0) {
        uint256 usdToReturn = tokensToUsd(excessTokens, stageIndex);
        usdReceived = usdReceived.sub(usdToReturn);
        weiToReturn = weiToReturn.add(usdToWei(usdToReturn));
        weiReceived = weiReceived.sub(weiToReturn);
        tokens = tokens.sub(excessTokens);
    }
    token.mint(_beneficiary, tokens, '');
    WALLET.transfer(weiReceived);
    emit TokenPurchase(msg.sender, _beneficiary, weiReceived, usdReceived, exchangeRate, tokens); 
    if (weiToReturn > 0) {
        msg.sender.transfer(weiToReturn);
    }
}

function initialize() public onlyOwner {
    require(!initialized);
    token.mint(timelock, TEAM_TOKENS, '');
    timelock.scheduleTimelock(TEAM_WALLET, TEAM_TOKENS, TEAM_TOKEN_LOCK_DATE);
    token.mint(ADVISORS_WALLET, ADVISORS_TOKENS, '');
    token.mint(PARTNER_WALLET, PARTNER_TOKENS, '');
    communityLock = new CommunityLock(token);
    token.mint(communityLock, COMMUNITY_TOKENS, '');
    initialized = true;
}

function ensureCurrentStage() internal {
    uint256 currentTime = getNow();
    uint256 stageCount = stages.length;
    uint8 curStage = currentStage;
    uint8 nextStage = curStage + 1;
    while (nextStage < stageCount && stages[nextStage].startDate <= currentTime) {
        stages[nextStage].cap = stages[nextStage].cap.add(stages[curStage].cap);
        curStage = nextStage;
        nextStage = nextStage + 1;
    }
    if (currentStage != curStage) {
        currentStage = curStage;
    }
}

function validatePurchase() internal view {
    require(!isFinalized);
    require(msg.value != 0);
    require(currentStage < stages.length);
    Stage storage stage = stages[currentStage];
    require(stage.cap > 0);
    uint256 currentTime = getNow();
    require(stage.startDate <= currentTime && currentTime <= stage.endDate);
    uint256 userId = whitelist.whitelist(msg.sender);
    require(userId > 0);
    if (stage.priorityDate > currentTime) {
        require(userId < stage.maxPriorityId);
    }
}

function addStage(uint256 startDate, uint256 endDate, uint256 cap, uint64 bonus, uint64 maxPriorityId, uint256 priorityTime) public onlyOwner onlyInitialized {
    require(!isFinalized);
    require(startDate > getNow());
    require(endDate > startDate);
    Stage storage lastStage = stages[stages.length - 1];
    require(startDate > lastStage.endDate);
    require(startDate.add(priorityTime) <= endDate);
    require(icoTokensLeft >= cap);
    require(maxPriorityId >= lastStage.maxPriorityId);
    stages.push(Stage({
        startDate: startDate,
        endDate: endDate,
        cap: cap,
        bonus: bonus,
        maxPriorityId: maxPriorityId,
        priorityDate: startDate.add(priorityTime)
    }));
}

function mintPreSaleTokens(address[] _receivers, uint256[] _amounts, uint256[] _lockPeroids) external onlyInitialized {
    require(msg.sender == tokenMinter || msg.sender == owner);
    require(_receivers.length > 0 && _receivers.length <= 100);
    require(_receivers.length == _amounts.length);
    require(_receivers.length == _lockPeroids.length);
    require(!isFinalized);
    uint256 tokensInBatch = 0;
    for (uint256 i = 0; i < _amounts.length; i++) {
        tokensInBatch = tokensInBatch.add(_amounts[i]);
    }
    require(preSaleTokens >= tokensInBatch);
    preSaleTokens = preSaleTokens.sub(tokensInBatch);
    token.mint(timelock, tokensInBatch, '');
    address receiver;
    uint256 lockTill;
    uint256 timestamp = getNow();
    for (i = 0; i < _receivers.length; i++) {
        receiver = _receivers[i];
        require(receiver != address(0));
        lockTill = _lockPeroids[i];
        require(lockTill > timestamp);
        timelock.scheduleTimelock(receiver, _amounts[i], lockTill);
    }
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 20 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        msg.sender.transfer(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function getWithdrawableAmountAS(address _investor) public view returns(uint256) {
    require(startWithdraw != 0);
    uint interval = safeDiv(safeSub(now, startWithdraw), 30 days);
    uint _allocatedTokens = safeAdd(walletAngelSales[_investor], releasedAngelSales[_investor]);
    if (interval < 6) {
        return (0);
    } else if (interval >= 6 && interval < 9) {
        return safeSub(getPercentageAmount(40, _allocatedTokens), releasedAngelSales[_investor]);
    } else if (interval >= 9 && interval < 12) {
        return safeSub(getPercentageAmount(60, _allocatedTokens), releasedAngelSales[_investor]);
    } else if (interval >= 12 && interval < 15) {
        return safeSub(getPercentageAmount(80, _allocatedTokens), releasedAngelSales[_investor]);
    } else if (interval >= 15) {
        return safeSub(_allocatedTokens, releasedAngelSales[_investor]);
    }
}

function getWithdrawableAmountPES(address _investor) public view returns(uint256) {
    require(startWithdraw != 0);
    uint interval = safeDiv(safeSub(now, startWithdraw), 30 days);
    uint _allocatedTokens = safeAdd(walletPESales[_investor], releasedPESales[_investor]);
    if (interval < 12) {
        return (0);
    } else if (interval >= 12 && interval < 18) {
        return safeSub(getPercentageAmount(40, _allocatedTokens), releasedPESales[_investor]);
    } else if (interval >= 18 && interval < 24) {
        return safeSub(getPercentageAmount(60, _allocatedTokens), releasedPESales[_investor]);
    } else if (interval >= 24 && interval < 30) {
        return safeSub(getPercentageAmount(80, _allocatedTokens), releasedPESales[_investor]);
    } else if (interval >= 30) {
        return safeSub(_allocatedTokens, releasedPESales[_investor]);
    }
}

function assignToken(address _investor, uint256 _tokens) external {
    require(msg.sender == walletAddresses[0] || msg.sender == walletAddresses[1]);
    require(_investor != address(0) && _tokens > 0);
    require(_tokens <= balances[msg.sender]);
    balances[msg.sender] = safeSub(balances[msg.sender], _tokens);
    uint256 calCurrentTokens = getPercentageAmount(_tokens, 20);
    uint256 allocateTokens = safeSub(_tokens, calCurrentTokens);
    balances[_investor] = safeAdd(balances[_investor], calCurrentTokens);
    if (msg.sender == walletAddresses[0]) {
        walletAngelSales[_investor] = safeAdd(walletAngelSales[_investor], allocateTokens);
        releasedAngelSales[_investor] = safeAdd(releasedAngelSales[_investor], calCurrentTokens);
    } else if (msg.sender == walletAddresses[1]) {
        walletPESales[_investor] = safeAdd(walletPESales[_investor], allocateTokens);
        releasedPESales[_investor] = safeAdd(releasedPESales[_investor], calCurrentTokens);
    } else {
        revert();
    }
}

function withdrawTokens() public {
    require(walletAngelSales[msg.sender] > 0 || walletPESales[msg.sender] > 0);
    uint256 withdrawableAmount = 0;
    if (walletAngelSales[msg.sender] > 0) {
        uint256 withdrawableAmountAS = getWithdrawableAmountAS(msg.sender);
        walletAngelSales[msg.sender] = safeSub(walletAngelSales[msg.sender], withdrawableAmountAS);
        releasedAngelSales[msg.sender] = safeAdd(releasedAngelSales[msg.sender], withdrawableAmountAS);
        withdrawableAmount = safeAdd(withdrawableAmount, withdrawableAmountAS);
    }
    if (walletPESales[msg.sender] > 0) {
        uint256 withdrawableAmountPS = getWithdrawableAmountPES(msg.sender);
        walletPESales[msg.sender] = safeSub(walletPESales[msg.sender], withdrawableAmountPS);
        releasedPESales[msg.sender] = safeAdd(releasedPESales[msg.sender], withdrawableAmountPS);
        withdrawableAmount = safeAdd(withdrawableAmount, withdrawableAmountPS);
    }
    require(withdrawableAmount > 0);
    balances[msg.sender] = safeAdd(balances[msg.sender], withdrawableAmount);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now >= SaleStage3_start) {
        tokens = safeDiv(msg.value * (10 ** 18), SaleStage3_tokenPrice);
        _supply = safeAdd(SaleStage3_supply, safeAdd(SaleStage2_supply, SaleStage1_supply));
    } else if (now >= SaleStage2_start) {
        tokens = safeDiv(msg.value * (10 ** 18), SaleStage2_tokenPrice);
        _supply = safeAdd(SaleStage2_supply, SaleStage1_supply);
    } else if (now >= SaleStage1_start) {
        tokens = safeDiv(msg.value * (10 ** 18), SaleStage1_tokenPrice);
        _supply = SaleStage1_supply;
    } else {}
    require(_totalSupply < _supply);
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function bulkTransfer(address _from, address[] _to, uint256[] _amount) external forToken returns(bool _success) {
    uint256 _senderBalance = _getBalance(_from);
    uint256 _receiverBalance;
    uint256 i;
    for (i = 0; i < _to.length; i++) {
        _receiverBalance = _getBalance(_to[i]);
        _senderBalance = _senderBalance.sub(_amount[i]);
        balances[_to[i]].amount = _receiverBalance.add(_amount[i]);
    }
    balances[_from].amount = _senderBalance;
    return true;
}

function transfer(address _from, address _to, uint256 _amount) external forToken returns(bool _success) {
    uint256 _senderBalance = _getBalance(_from);
    uint256 _receiverBalance = _getBalance(_to);
    balances[_from].amount = _senderBalance.sub(_amount);
    balances[_to].amount = _receiverBalance.add(_amount);
    return true;
}

function _getBalance(address _owner) internal returns(uint256 _balance) {
    if ((!balances[_owner].valid) && oldDBAddress != 0x00) {
        bool _subResult;
        (_subResult, _balance) = TokenDB(oldDBAddress).balanceOf(_owner);
        balances[_owner].amount = _balance;
        balances[_owner].valid = true;
    }
    return balances[_owner].amount;
}

function forceResetExpires(uint256[] calldata _nftIds)
external
onlyOwner {
    for (uint256 i = 0; i < _nftIds.length; i++) {
        (  ,  ,  ,  , uint256 validUntil,  ,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftIds[i]);
        require(nftOwners[_nftIds[i]] != address(0), "this nft does not belong here");
        ExpireTracker.pop(uint96(_nftIds[i]), 86400);
        ExpireTracker.pop(uint96(_nftIds[i]), 86400 * 3);
        ExpireTracker.push(uint96(_nftIds[i]), uint64(validUntil));
    }
}

function buy(uint256 amount) public payable {
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= start, "early");
    require(isClosed() == false, "Sale has closed");
    require(amount <= supply(), "ordered too many");
    require(amount <= limitPerOrder, "ordered too many");
    require(msg.value == price.mul(amount), "wrong amount");
    nft.safeTransferFrom(address(this), msg.sender, id, amount, new bytes(0x0));
    uint256 stakingReward = (address(this).balance * stakingRewardPercentageBasisPoints) / 10000;
    (bool stakingRewardSuccess, ) = stakingSwapContract.call {
        value: stakingReward
    }("");
    require(stakingRewardSuccess, "Staking reward transfer failed.");
    (bool successMultisig, ) = hausAddress.call {
        value: address(this).balance
    }("");
    require(successMultisig, "Multisig transfer failed.");
    buyCount += amount;
    emit Buy(msg.sender, amount);
}

function isClosed() public view returns(bool) {
    return (block.timestamp >= endTime) || (supply() == 0);
}

function revoke(address userAddress)
public
onlyValidAuthority(msg.sender)
onlyAuthoritativeAuthority(msg.sender, userAddress) {
    KYC memory kyc = KYC({
        verified: false,
        verifiedBy: msg.sender,
        verifiedAt: block.number,
        verifiedAttributes: 0
    });
    records[userAddress] = kyc;
    emit IdentityRevoke(msg.sender, userAddress);
}

function claim(address verifier, uint verifiedAttributes, uint expires, uint8 v, bytes32 r, bytes32 s)
public
onlyValidAuthority(verifier)
onlyAuthoritativeAuthority(verifier, msg.sender) {
    if (verificationFee > 0) {
        if (!chargeVerificationFee(msg.sender, verifier)) {
            revert();
        }
    }
    bytes32 hash = sha256(this, msg.sender, verifiedAttributes, expires);
    bytes memory prefix = "\x19Ethereum Signed Message:\n32";
    bytes32 prefixedHash = keccak256(prefix, hash);
    if (!((ecrecover(prefixedHash, v, r, s) == verifier) && block.number <= expires)) {
        revert();
    }
    KYC memory kyc = KYC({
        verified: true,
        verifiedBy: verifier,
        verifiedAt: block.number,
        verifiedAttributes: verifiedAttributes
    });
    records[msg.sender] = kyc;
    emit IdentityApproval(verifier, msg.sender, verifiedAttributes);
}

function approve(address userAddress, uint verifiedAttributes)
public
onlyValidAuthority(msg.sender)
onlyAuthoritativeAuthority(msg.sender, userAddress) {
    KYC memory kyc = KYC({
        verified: true,
        verifiedBy: msg.sender,
        verifiedAt: block.number,
        verifiedAttributes: verifiedAttributes
    });
    records[userAddress] = kyc;
    emit IdentityApproval(msg.sender, userAddress, verifiedAttributes);
}

function withdrawFee()
public
onlyValidAuthority(msg.sender) {
    require(paymentContractAddress != 0x0);
    uint balance = verificationFeeBalances[msg.sender];
    require(balance > 0);
    verificationFeeBalances[msg.sender] = 0;
    if (!ERC20(paymentContractAddress).transfer(msg.sender, balance)) {
        revert();
    }
}

function chargeVerificationFee(address userAddress, address authorityAddress)
private
returns(bool) {
    if (!ERC20(paymentContractAddress).transferFrom(userAddress, this, verificationFee)) {
        return false;
    }
    uint currentBalance = verificationFeeBalances[authorityAddress];
    verificationFeeBalances[authorityAddress] = safeAdd(currentBalance, verificationFee);
    return true;
}

function _withdrawReward(address user) internal {
    uint256 rewardAmount = getRewardByAddress(user);
    if (rewardAmount != 0) {
        require(
            IERC20(token).transferFrom(address(this), user, rewardAmount), 
            "#transferFrom failed"
        );
        emit RewardWithdrawn(user, rewardAmount);
    }
    userToStakes[user].lastInteractionBlockNumber = block.number;
}

function unstake() external {
    _withdrawReward(_msgSender());
    Stake storage currentStake = userToStakes[_msgSender()];
    uint256 stakeAmountToDeduct;
    bool executeUnstaking;
    uint256 stakeAmount = currentStake.stakeAmount;
    if (currentStake.stakeAmount == 0) {
        revert("no stake");
    }
    if (currentStake.stakingPeriodEndTime <= block.timestamp) {
        executeUnstaking = true;
    }
    require(
        executeUnstaking,
        "cannot unstake"
    );
    currentStake.stakeAmount = 0;
    currentStake.totalStakedAmountByUser = currentStake.totalStakedAmountByUser
        .sub(stakeAmount);
    stakeAmountToDeduct = stakeAmountToDeduct.add(stakeAmount);
    require(
        IERC20(lpToken).transferFrom(address(this), _msgSender(), stakeAmount), 
        "#transfer failed"
    );
    emit Unstaked(lpToken, _msgSender(), stakeAmount);
    totalStakedAmount = totalStakedAmount.sub(stakeAmountToDeduct); 
}

function getRewardByAddress(
    address user
) public view returns(uint256) {
    if (totalStakedAmount == 0) {
        return 0;
    }
    Stake storage currentStake = userToStakes[user];
    uint256 blockCount = block.number
        .sub(currentStake.lastInteractionBlockNumber);
    uint256 totalReward = blockCount.mul(blockReward);
    return totalReward
        .mul(currentStake.totalStakedAmountByUser)
        .div(totalStakedAmount);
}

function supplyAirpool(
    uint256 amountTokenDesired,
    uint256 amountTokenMin,
    uint256 amountETHMin
) external payable {
    require(
        msg.value != 0, 
        "amount should be greater than 0"
    );
    require(
        msg.value >= minimumAmount,
        "amount too low"
    );
    require(
        msg.value > maximumAmount,
        "amount too high"
    );
    uint deadline = block.timestamp.add(2 hours); 
    (uint amountToken, uint amountETH, uint liquidity) = uniswapRouter.addLiquidityETH.value(msg.value)(
        token,
        amountTokenDesired,
        amountTokenMin,
        amountETHMin,
        address(this),
        deadline
    );
    _withdrawReward(_msgSender()); 
    totalStakedAmount = totalStakedAmount.add(liquidity); 
    Stake storage currentStake = userToStakes[_msgSender()];
    currentStake.stakingPeriodEndTime = block.timestamp.add(
        stakingDuration
    ); 
    currentStake.stakeAmount = currentStake.stakeAmount 
        .add(liquidity);
    currentStake.totalStakedAmountByUser = currentStake.totalStakedAmountByUser 
        .add(liquidity);
    emit Staked(
        lpToken,
        _msgSender(),
        amountToken,
        amountETH,
        liquidity
    ); 
}

function ClaimReward() public {
    require(pendingReward(msg.sender) > 0, "nothing pending to claim");
    ERC20Interface(DGN).transfer(msg.sender, pendingReward(msg.sender));
    emit RewardClaimed(msg.sender, pendingReward(msg.sender));
    totalRewards += pendingReward(msg.sender);
    users[msg.sender].totalGained += pendingReward(msg.sender);
    users[msg.sender].lastClaimedDate = now;
    users[msg.sender].pendingGains = 0;
}

function ClaimStakedTokens() external {
    require(users[msg.sender].activeDeposit > 0, "no running stake");
    uint256 _penaltyFee = 0;
    if (users[msg.sender].startTime + latestStakingPeriod() > now) { 
        _penaltyFee = penaltyFee;
    }
    uint256 toTransfer = users[msg.sender].activeDeposit.sub(_onePercent(users[msg.sender].activeDeposit).mul(_penaltyFee));
    ERC20Interface(DGN).transfer(msg.sender, toTransfer);
    users[msg.sender].pendingGains = pendingReward(msg.sender);
    emit TokensClaimed(msg.sender, toTransfer);
    users[msg.sender].activeDeposit = 0;
}

function isActive(uint16 auctionIndex) public view returns(bool) {
    Auction storage auction = auctions[auctionIndex];
    return
    auction.timeStart <= now &&
        (now < auction.timeEnd || auction.timeEnd != 0 && auction.highestBidder == address(0));
}

function isEnded(uint16 auction) public view returns(bool) {
    return
    auctions[auction].timeEnd < now &&
        auctions[auction].highestBidder != address(0);
}

function submitTransaction() public onlyHolder {
    require(transactionTo_ != address(0) && transactionValue_ > 0);
    require(holder1Transaction_ && holder2Transaction_ && holder3Transaction_);
    require(!holder1Reset_ && !holder2Reset_ && !holder3Reset_);
    ERC20 _token = ERC20(token_);
    _token.approve(this, transactionValue_);
    _token.transferFrom(this, transactionTo_, transactionValue_);
    emit TransactionSubmitted(transactionTo_, transactionValue_);
    clearTransaction();
}

function confirmTransaction(uint256 _nonce, bool _vote) public onlyHolder {
    require(transactionNonce_ == _nonce);
    if (msg.sender == holder1_) {
        holder1Transaction_ = _vote;
    }
    if (msg.sender == holder2_) {
        holder2Transaction_ = _vote;
    }
    if (msg.sender == holder3_) {
        holder3Transaction_ = _vote;
    }
    emit TransactionConfirmed(msg.sender, _vote);
}

function depositeFod(uint256 _amount, uint _mode) public {
    uint256 yie = 100;
    if (useInviteCodeMap[msg.sender] != 0) {
        yie = yieldRate;
    }
    IERC20 fodToken = IERC20(fod);
    fodToken.transferFrom(msg.sender, this, _amount);
    uint256 dueTime = now.add(dayMap[_mode].mul(intervalTime));
    uint256 earnings = _amount.mul(yie).mul(dateToYields[_mode]).mul(dayMap[_mode]).div(3650000);
    Pledge memory pledge = Pledge(dayMap[_mode], _amount, earnings, dateToYields[_mode], yie, now, dueTime, 0, 0);
    addressToPledge[msg.sender].push(pledge);
    if (useInviteCodeMap[msg.sender] != 0) {
        Invite memory invite = Invite(msg.sender, _amount, earnings.mul(inviteYieldRate).div(100), dateToYields[_mode], yie, dayMap[_mode], now, dueTime, 0, 0);
        inviteLogs[useInviteCodeMap[msg.sender]].push(invite);
    }
    if (inviteCodeMap[bytes4(keccak256((msg.sender)))] == 0) {
        inviteCodeMap[bytes4(keccak256((msg.sender)))] = msg.sender;
    }
    emit DepositeFod(msg.sender, _amount);
}

function() public payable {
    require(msg.value > 0);
    require(crowdSaleOngoing);
    require(now > 1531267200);
    uint tokens = (msg.value * (10 ** uint(decimals))) / weiCostOfToken;
    uint remainder = msg.value % weiCostOfToken;
    if (now < 1533081600) {
        tokens = (125 * tokens) / 100;
    } else if (now < 1535932800) {
        tokens = (110 * tokens) / 100;
    }
    crowdSaleAllowed[msg.sender] = crowdSaleAllowed[msg.sender].sub(tokens);
    crowdSaleBalance = crowdSaleBalance.sub(tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    crowdSaleAmountRaised = crowdSaleAmountRaised.add(msg.value);
    owner.transfer(msg.value - remainder);
    emit Transfer(owner, msg.sender, tokens);
    emit CrowdSalePurchaseCompleted(msg.sender, msg.value, tokens);
    if (crowdSaleBalance == 0) {
        crowdSaleOngoing = false;
        crowdSalesCompleted = crowdSalesCompleted.add(1);
        emit CrowdSaleLocked(!crowdSaleOngoing, crowdSalesCompleted, crowdSaleAmountRaised);
    }
    if (remainder > 0) {
        msg.sender.transfer(remainder);
    }
}

function withdraw()
onlyStronghands()
sellLimit()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
sellLimit()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _amountOfTokens);
    Transfer(_customerAddress, _toAddress, _amountOfTokens);
    return true;
}

function removeLiquidity(
    address payable _provider,
    uint256 _id,
    uint32 _portion
) internal {
    ProtectedLiquidity memory liquidity = protectedLiquidity(_id, _provider);
    IERC20Token networkTokenLocal = networkToken;
    _poolWhitelisted(liquidity.poolToken);
    require(liquidity.timestamp < time(), "ERR_TOO_EARLY");
    if (_portion == PPM_RESOLUTION) {
        notifyEventSubscribersOnRemovingLiquidity(
            _id,
            _provider,
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.poolAmount,
            liquidity.reserveAmount
        );
        store.removeProtectedLiquidity(_id);
    } else {
        uint256 fullPoolAmount = liquidity.poolAmount;
        uint256 fullReserveAmount = liquidity.reserveAmount;
        liquidity.poolAmount = liquidity.poolAmount.mul(_portion) / PPM_RESOLUTION;
        liquidity.reserveAmount = liquidity.reserveAmount.mul(_portion) / PPM_RESOLUTION;
        notifyEventSubscribersOnRemovingLiquidity(
            _id,
            _provider,
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.poolAmount,
            liquidity.reserveAmount
        );
        store.updateProtectedLiquidityAmounts(
            _id,
            fullPoolAmount - liquidity.poolAmount,
            fullReserveAmount - liquidity.reserveAmount
        );
    }
    stats.decreaseTotalAmounts(
        liquidity.provider,
        liquidity.poolToken,
        liquidity.reserveToken,
        liquidity.poolAmount,
        liquidity.reserveAmount
    );
    lastRemoveCheckpointStore.addCheckpoint(_provider);
    systemStore.incSystemBalance(liquidity.poolToken, liquidity.poolAmount);
    if (liquidity.reserveToken == networkTokenLocal) {
        safeTransferFrom(govToken, _provider, address(this), liquidity.reserveAmount);
        govTokenGovernance.burn(liquidity.reserveAmount);
    }
    PackedRates memory packedRates =
        packRates(
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.reserveRateN,
            liquidity.reserveRateD,
            true
        );
    uint256 targetAmount =
        removeLiquidityTargetAmount(
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.poolAmount,
            liquidity.reserveAmount,
            packedRates,
            liquidity.timestamp,
            time()
        );
    if (liquidity.reserveToken == networkTokenLocal) {
        mintNetworkTokens(address(wallet), liquidity.poolToken, targetAmount);
        lockTokens(_provider, targetAmount);
        return;
    }
    Fraction memory poolRate = poolTokenRate(liquidity.poolToken, liquidity.reserveToken);
    uint256 poolAmount = targetAmount.mul(poolRate.d).div(poolRate.n / 2);
    uint256 systemBalance = systemStore.systemBalance(liquidity.poolToken);
    poolAmount = poolAmount > systemBalance ? systemBalance : poolAmount;
    systemStore.decSystemBalance(liquidity.poolToken, poolAmount);
    wallet.withdrawTokens(liquidity.poolToken, address(this), poolAmount);
    removeLiquidity(liquidity.poolToken, poolAmount, liquidity.reserveToken, networkTokenLocal);
    uint256 baseBalance;
    if (liquidity.reserveToken == ETH_RESERVE_ADDRESS) {
        baseBalance = address(this).balance;
        _provider.transfer(baseBalance);
    } else {
        baseBalance = liquidity.reserveToken.balanceOf(address(this));
        safeTransfer(liquidity.reserveToken, _provider, baseBalance);
    }
    uint256 delta = getNetworkCompensation(targetAmount, baseBalance, packedRates);
    if (delta > 0) {
        uint256 networkBalance = networkTokenLocal.balanceOf(address(this));
        if (networkBalance < delta) {
            networkTokenGovernance.mint(address(this), delta - networkBalance);
        }
        safeTransfer(networkTokenLocal, address(wallet), delta);
        lockTokens(_provider, delta);
    }
    uint256 networkBalance = networkTokenLocal.balanceOf(address(this));
    if (networkBalance > 0) {
        burnNetworkTokens(liquidity.poolToken, networkBalance);
    }
}

