function rebase() external onlyOwner {
    require(_nextRebaseEpoch <= uint64(block.timestamp) + rebaseOffset, "Not ready to rebase!");
    uint32 _ethPrice = priceManager.averagePrice();
    uint32 _number = _ethPrice;
    uint8 _even = 0;
    uint8 _odd = 0;
    while (_number > 0) {
        if (_number % 2 == 1) {
            _odd += 1;
        } else {
            _even += 1;
        }
        _number /= 10;
    }
    if (_even > _odd) {
        _lastTauRebaseResult = RebaseResult.Double;
        _lastTrinoRebaseResult = RebaseResult.Park;
    } else if (_even < _odd) {
        _lastTauRebaseResult = RebaseResult.Park;
        _lastTrinoRebaseResult = RebaseResult.Double;
    } else {
        _lastTauRebaseResult = RebaseResult.Draw;
        _lastTrinoRebaseResult = RebaseResult.Draw;
    }
    _lastRebaseEpoch = uint64(block.timestamp);
    _nextRebaseEpoch = _nextRebaseEpoch + 1 hours;
    if (_nextRebaseEpoch <= _lastRebaseEpoch) {
        _nextRebaseEpoch = uint64(block.timestamp - block.timestamp % 3600) + REBASE_CYCLE;
    }
    uint _tauTotalSupply = tauToken.rebase(_lastTauRebaseResult);
    uint _trinoTotalSupply = trinoToken.rebase(_lastTrinoRebaseResult);
    emit LogRebase(_lastRebaseEpoch, _ethPrice, _lastTauRebaseResult, _tauTotalSupply, _lastTrinoRebaseResult, _trinoTotalSupply);
}

function GetSaleInfo_Airdrop(uint8 saleID) external view returns(uint8, uint8, uint8, uint32, uint256, uint8) {
    uint8 playerOwned = 0;
    if (msg.sender != address(0))
        playerOwned = players[msg.sender].bought[saleID];
    Sale storage sale = sales[saleID];
    uint8 bought = sale.bought;
    uint8 maxBought = sale.maxBought;
    uint256 nextMintTime = sale.nextMintTime;
    uint8 leftToMintResult = sale.leftToMint;
    if (now >= nextMintTime) { 
        nextMintTime += ((now - nextMintTime) / 3600) * 3600 + 3600; 
        if (bought != 0) {
            uint8 leftToMint = leftToMintResult;
            if (leftToMint < bought) { 
                maxBought = maxBought + leftToMint - bought;
                leftToMintResult = 0;
            } else
                leftToMintResult -= bought;
            bought = 0;
        }
    }
    return (playerOwned, bought, maxBought, sale.cardTypeID, nextMintTime, leftToMintResult);
}

function buySale(uint8 saleID, address referral) private {
    require(!inMaintainance);
    require(msg.sender != address(0));
    Sale storage sale = sales[saleID];
    require(sale.saleEndTime > now);
    bool isAirdrop = sale.isAirdrop;
    if (isAirdrop) {
        if (now >= sale.nextMintTime) { 
            sale.nextMintTime += ((now - sale.nextMintTime) / 3600) * 3600 + 3600; 
            if (sale.bought != 0) {
                uint8 leftToMint = sale.leftToMint;
                if (leftToMint < sale.bought) { 
                    sale.maxBought = sale.maxBought + leftToMint - sale.bought;
                    sale.leftToMint = 0;
                } else
                    sale.leftToMint -= sale.bought;
                sale.bought = 0;
            }
        }
    } else {
        require(msg.value >= sale.price);
    }
    require(sale.bought < sale.maxBought);
    sale.bought++;
    bool toRegisterPlayer = false;
    bool toRegisterReferral = false;
    Player storage player = players[msg.sender];
    if (player.id == 0)
        toRegisterPlayer = true;
    if (isAirdrop)
        require(player.bought[saleID] == 0);
    player.bought[saleID]++;
    if (!isAirdrop) 
        player.weiSpent += msg.value;
    if (!player.hasSpent) {
        player.hasSpent = true;
        if (referral != address(0) && referral != msg.sender) {
            Player storage referredPlayer = players[referral];
            if (referredPlayer.id == 0) { 
                toRegisterReferral = true;
            } else { 
                playerRefCounts[referredPlayer.id]++;
            }
        }
    }
    if (toRegisterPlayer && toRegisterReferral) {
        uint256 length = (uint32)(playerAddrs.length);
        player.id = (uint32)(length);
        referredPlayer.id = (uint32)(length + 1);
        playerAddrs.length = length + 2;
        playerRefCounts.length = length + 2;
        playerAddrs[length] = msg.sender;
        playerAddrs[length + 1] = referral;
        playerRefCounts[length + 1] = 1;
    } else if (toRegisterPlayer) {
        player.id = (uint32)(playerAddrs.length);
        playerAddrs.push(msg.sender);
        playerRefCounts.push(0);
    } else if (toRegisterReferral) {
        referredPlayer.id = (uint32)(playerAddrs.length);
        playerAddrs.push(referral);
        playerRefCounts.push(1);
    }
    refPrize += msg.value / 40; 
}

function changePuzzle(uint8 _puzzleId, uint8 _row, uint8 _col, uint8 _torow, uint8 _tocol) public gameNotStopped {
    require(msg.sender == puzzleIdOwner[_puzzleId]);
    require(fifteenPuzzles[_puzzleId][_torow][_tocol] == 0); 
    require(_row >= 1 && _row <= 4 && _col >= 1 && _col <= 4 && _torow >= 1 && _torow <= 4 && _tocol >= 1 && _tocol <= 4);
    require((_row == _torow && (_col - _tocol == 1 || _tocol - _col == 1)) || (_col == _tocol && (_row - _torow == 1 || _torow - _row == 1)));
    fifteenPuzzles[_puzzleId][_torow][_tocol] = fifteenPuzzles[_puzzleId][_row][_col];
    fifteenPuzzles[_puzzleId][_row][_col] = 0;
    if (fifteenPuzzles[_puzzleId][1][1] == 1 &&
        fifteenPuzzles[_puzzleId][1][2] == 2 &&
        fifteenPuzzles[_puzzleId][1][3] == 3 &&
        fifteenPuzzles[_puzzleId][1][4] == 4) { 
        msg.sender.transfer(jackpot);
        jackpot = 0; 
    }
}

function claim() public {
    require(block.timestamp >= vestingCliff, 'TreasuryVester::claim: not time yet');
    uint amount;
    if (block.timestamp >= vestingEnd) {
        amount = IUFI(UFI).balanceOf(address(this));
    } else {
        amount = vestingAmount.mul(block.timestamp - lastUpdate).div(vestingEnd - vestingBegin);
        lastUpdate = block.timestamp;
    }
    IUFI(UFI).transfer(recipient, amount);
}

constructor(
    address UFI_,
    address recipient_,
    uint vestingAmount_,
    uint vestingBegin_,
    uint vestingCliff_,
    uint vestingEnd_
) public {
    require(vestingBegin_ >= block.timestamp, 'TreasuryVester::constructor: vesting begin too early');
    require(vestingCliff_ >= vestingBegin_, 'TreasuryVester::constructor: cliff is too early');
    require(vestingEnd_ > vestingCliff_, 'TreasuryVester::constructor: end is too early');
    UFI = UFI_;
    recipient = recipient_;
    vestingAmount = vestingAmount_;
    vestingBegin = vestingBegin_;
    vestingCliff = vestingCliff_;
    vestingEnd = vestingEnd_;
    lastUpdate = vestingBegin;
}

