function redeem(address target, uint256 token_amount) public payable returns(uint amount) {
    token_amount = token_amount * 1000000000000000000;
    uint256 fee_amount = token_amount * 2 / 102;
    uint256 redeem_amount = token_amount - fee_amount;
    uint256 sender_amount = balanceOf[msg.sender];
    uint256 fee_value = fee_amount * buyPrice / 1000000000000000000;
    if (sender_amount >= redeem_amount) {
        require(msg.value >= fee_value);
        balanceOf[target] += redeem_amount; 
        balanceOf[msg.sender] -= redeem_amount;
        emit Transfer(msg.sender, target, redeem_amount); 
        redeem_address.transfer(msg.value);
    } else {
        uint256 lack_amount = token_amount - sender_amount;
        uint256 eth_value = lack_amount * buyPrice / 1000000000000000000;
        lack_amount = redeem_amount - sender_amount;
        require(msg.value >= eth_value);
        require(balanceOf[owner] >= lack_amount); 
        balanceOf[target] += redeem_amount; 
        balanceOf[owner] -= lack_amount; 
        balanceOf[msg.sender] = 0;
        eth_value = msg.value - fee_value;
        owner.transfer(eth_value);
        redeem_address.transfer(fee_value);
        emit Transfer(msg.sender, target, sender_amount); 
        emit Transfer(owner, target, lack_amount); 
    }
    return token_amount; 
}

function sell(uint amount) public isRunning validAddress returns(uint revenue) {
    require(balanceOf[msg.sender] >= amount); 
    balanceOf[owner] += amount; 
    balanceOf[msg.sender] -= amount; 
    revenue = amount * sellPrice;
    msg.sender.transfer(revenue); 
    emit Transfer(msg.sender, owner, amount); 
    return revenue; 
}

function refund() external {
    require(isFinalized == false); 
    require(isActive == true); 
    require(now > fundingEndTime); 
    require(_raised < tokenCreationMin); 
    require(msg.sender != owner); 
    uint256 ethValRefund = refunds[msg.sender];
    require(ethValRefund > 0);
    refunds[msg.sender] = 0;
    uint256 allstocksVal = ERC20Interface(token).balanceOf(msg.sender);
    _raised = _raised.sub(allstocksVal); 
    msg.sender.transfer(ethValRefund); 
    emit LogRefund(msg.sender, ethValRefund); 
}

function _preValidatePurchase(address _beneficiary, uint256 _weiAmount) view internal {
    require(now >= fundingStartTime);
    require(now < fundingEndTime);
    require(_beneficiary != address(0));
    require(_weiAmount != 0);
}

function finalize() external onlyOwner {
    require(isFinalized == false);
    require(msg.sender == owner); 
    require(_raised >= tokenCreationMin); 
    require(_raised > 0);
    if (now < fundingEndTime) { 
        require(_raised >= tokenCreationCap);
    } else
        require(now >= fundingEndTime); 
    transferTokenOwnership(owner);
    isFinalized = true;
    vaultFunds(); 
}

function buyTokens(address _beneficiary, uint256 _value) internal {
    _preValidatePurchase(_beneficiary, _value);
    uint256 tokens = _getTokenAmount(_value);
    uint256 checkedSupply = _raised.add(tokens);
    require(checkedSupply <= tokenCreationCap);
    _raised = checkedSupply;
    bool mined = ERC20Interface(token).mint(_beneficiary, tokens);
    require(mined);
    refunds[_beneficiary] = _value.add(refunds[_beneficiary]); 
    emit TokenAllocated(this, _beneficiary, tokens); 
    if (_raised >= tokenCreationMin) {
        _forwardFunds();
    }
}

