function transfer(address _to, uint256 _value) public returns(bool success) {
    require(_to != 0x0);
    if (now > voteEndTime) {
        require((balances[msg.sender] >= _value));
        balances[msg.sender] = SafeMath.sub(balances[msg.sender], _value);
        balances[_to] = SafeMath.add(balances[_to], _value);
        emit Transfer(msg.sender, _to, _value);
        return true;
    } else {
        require(balances[msg.sender] >= SafeMath.add(frozen[msg.sender], _value));
        balances[msg.sender] = SafeMath.sub(balances[msg.sender], _value);
        balances[_to] = SafeMath.add(balances[_to], _value);
        emit Transfer(msg.sender, _to, _value);
        return true;
    }
}

function vote(address _to, uint256 _value) public returns(bool success) {
    require(_to != 0x0 && now < voteEndTime);
    require(balances[msg.sender] >= SafeMath.add(frozen[msg.sender], _value));
    frozen[msg.sender] = SafeMath.add(frozen[msg.sender], _value);
    totalVotes[_to] = SafeMath.add(totalVotes[_to], _value);
    votingInfo[_to][msg.sender] = SafeMath.add(votingInfo[_to][msg.sender], _value);
    emit Vote(msg.sender, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(_to != 0x0);
    if (now > voteEndTime) {
        require(balances[_from] >= _value && allowed[_from][msg.sender] >= _value);
        balances[_from] = SafeMath.sub(balances[_from], _value);
        balances[_to] = SafeMath.add(balances[_to], _value);
        emit Transfer(_from, _to, _value);
        return true;
    } else {
        require(balances[_from] >= SafeMath.add(frozen[_from], _value) && allowed[_from][msg.sender] >= _value);
        balances[_from] = SafeMath.sub(balances[_from], _value);
        balances[_to] = SafeMath.add(balances[_to], _value);
        emit Transfer(_from, _to, _value);
        return true;
    }
}

function balanceOf(address _owner) public returns(uint256 balance) {
    if (!touched[_owner] && SafeMath.add(distributed, airdropNum) < _totalSupply && now < voteEndTime) {
        touched[_owner] = true;
        distributed = SafeMath.add(distributed, airdropNum);
        balances[_owner] = SafeMath.add(balances[_owner], airdropNum);
        emit Transfer(this, _owner, airdropNum);
    }
    return balances[_owner];
}

function voteAll(address _to) public returns(bool success) {
    require(_to != 0x0 && now < voteEndTime);
    require(balances[msg.sender] > frozen[msg.sender]);
    uint256 votesNum = SafeMath.sub(balances[msg.sender], frozen[msg.sender]);
    frozen[msg.sender] = balances[msg.sender];
    totalVotes[_to] = SafeMath.add(totalVotes[_to], votesNum);
    votingInfo[_to][msg.sender] = SafeMath.add(votingInfo[_to][msg.sender], votesNum);
    emit Vote(msg.sender, _to, votesNum);
    return true;
}

function _turnOverAvailable() internal view returns(bool _available) {
    uint256 _votingRound = _currentVotingRound();
    return _votingRound > votingRound && pendingChanges;
}

function _turnOver() internal {
    votingRound = _currentVotingRound();
    uint256 _candidateCount = candidates.length();
    for (uint256 _index = 0; _index < _candidateCount; _index++) {
        address _candidate = candidates.at(_index);
        if (Multisig._isOwner(safe, _candidate)) continue;
        bool _success = Multisig._addOwnerWithThreshold(safe, _candidate, 1);
        assert(_success);
    }
    address[] memory _owners = Multisig._getOwners(safe);
    uint256 _ownersCount = _owners.length;
    address _prevOwner = address(0x1); 
    for (uint256 _index = 0; _index < _ownersCount; _index++) {
        address _owner = _owners[_index];
        if (candidates.contains(_owner)) {
            _prevOwner = _owner;
            continue;
        }
        bool _success = Multisig._removeOwner(safe, _prevOwner, _owner, 1);
        assert(_success);
    }
    uint256 _threshold = Math._min(_candidateCount, SIGNING_THRESHOLD);
    bool _success = Multisig._changeThreshold(safe, _threshold);
    assert(_success);
    pendingChanges = false;
    emit TurnOver(votingRound);
}

function appointCandidate() public onlyEOA nonReentrant {
    address _candidate = msg.sender;
    if (_turnOverAvailable()) _turnOver();
    require(!candidates.contains(_candidate), "already eligible");
    require(_appointCandidate(_candidate), "not eligible");
}

function buyDepo(address _depo) public payable {
    require(isSale[_depo] == true, "So sorry, but this deposit is not for sale.");
    isSale[_depo] = false; 
    require(forSale[_depo] == msg.value, "Summ for buying deposit is incorrect.");
    address seller = _depo;
    uint256 amount = invested[_depo] * 4 / 100 * (block.number - atBlock[_depo]) / 5900;
    invested[_depo] += amount;
    if (invested[msg.sender] > 0) {
        amount = invested[msg.sender] * 4 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        invested[msg.sender] += amount;
    }
    invested[msg.sender] += invested[_depo];
    atBlock[msg.sender] = block.number;
    invested[_depo] = 0;
    atBlock[_depo] = block.number;
    isSale[_depo] = false;
    seller.transfer(msg.value * 9 / 10); 
    emit Deals(_depo, msg.sender, msg.value);
}

