function attackMonster(uint monsterId) public {
    require(!listedEtherMonster[monsterId].defeated); 
    require(address(this).balance >= listedEtherMonster[monsterId].balance); 
    require(mapUserLastAttackMonsterTimestamp[msg.sender].add(userAttackMonsterCDSeconds) < now);
    require(listedEtherMonster[monsterId].produceTime.add(etherMonsterHuntSeconds) > now);
    require(mapUserHasHunterLicence[msg.sender]); 
    require(mapUserCurrentMartialId[msg.sender] == listedEtherMonster[monsterId].martialId);
    uint monsterCurrentBlood = listedEtherMonster[monsterId].currentBlood;
    uint monsterTotalBlood = listedEtherMonster[monsterId].blood;
    mapUserLastAttackMonsterTimestamp[msg.sender] = now;
    if (mapUserPower[msg.sender] >= monsterCurrentBlood) {
        listedEtherMonster[monsterId].defeated = true;
        listedEtherMonster[monsterId].winner = msg.sender;
        _sendMonsterPrize(monsterId, msg.sender);
    } else {
        uint randomNumber = getRandomNumber(monsterTotalBlood);
        if (randomNumber < mapUserPower[msg.sender]) {
            listedEtherMonster[monsterId].defeated = true;
            listedEtherMonster[monsterId].winner = msg.sender;
            _sendMonsterPrize(monsterId, msg.sender);
        } else {
            listedEtherMonster[monsterId].currentBlood = monsterCurrentBlood.sub(mapUserPower[msg.sender]);
        }
    }
}

function _canLotteryFree(address userAddress) private view returns(bool) {
    uint lastLotteryTimestamp = mapUserLastFreeLotteryTimestamp[userAddress];
    return now - lastLotteryTimestamp > freeLotterySeconds;
}

function getCanAttackMonsterIds() public view returns(uint[]) {
    uint[] memory result = new uint[](listedEtherMonster.length + 1);
    uint index = 0;
    for (uint i = 0; i < listedEtherMonster.length; i++) {
        EtherMonster memory monster = listedEtherMonster[i];
        if (monster.produceTime.add(etherMonsterHuntSeconds) > now && !monster.defeated) {
            result[index] = i + 1;
            index += 1;
        }
    }
    return result;
}

function getOnSellCardIds() public view returns(uint[]) {
    uint[] memory result = new uint[](listedCard.length + 1);
    uint index = 0;
    for (uint i = 0; i < listedCard.length; i++) {
        if (listedCard[i].onSell) {
            result[index] = i + 1;
            index += 1;
        }
    }
    return result;
}

function getEtherMonsterInfo(uint monsterId) public view returns(uint, uint, uint, uint, uint, uint, bool, address) {
    require(monsterId < listedEtherMonster.length);
    EtherMonster memory monster = listedEtherMonster[monsterId];
    return (monster.monsterId, monster.martialId, monster.balance, monster.blood, monster.produceTime, monster.currentBlood, monster.defeated, monster.winner);
}

function getMartialInfo(uint martialId) public view returns(uint, uint, address, uint, uint, uint, uint, uint, uint, uint[]) {
    require(martialId < listedMartials.length);
    Martial memory martial = listedMartials[martialId];
    return (martial.x, martial.y, martial.owner, martial.lastProduceTime, martial.martialId, martial.rareNumber, martial.epicNumber, martial.mythNumber, martial.enterPrice, martial.cardTypeList);
}

function createNewCardType(uint martialId, uint initPower, uint growthFactor, uint category) onlyOwner() public {
    require(initPower >= 1);
    require(growthFactor >= 2);
    require(category >= 1);
    require(category <= 4); 
    require(martialId < listedMartials.length);
    listedMartials[martialId].cardTypeList.push(listedCardType.length);
    CardType memory cardType = CardType(listedCardType.length, martialId, initPower, growthFactor, category);
    listedCardType.push(cardType);
}

function _tryCreateEtherMonster(uint price_a, uint price_b) private {
    uint priceTimes = price_b.div(0.5 ether);
    if (price_a < priceTimes * 0.5 ether && price_b >= priceTimes * 0.5 ether) {
        uint martialId = getRandomNumber(listedMartials.length);
        EtherMonster memory monster = EtherMonster(listedEtherMonster.length, martialId, 0.2 ether, maxUserPower.mul(smallMonsterPowerFactor), now, maxUserPower.mul(smallMonsterPowerFactor), false, address(0));
        listedEtherMonster.push(monster);
    }
    priceTimes = price_b.div(5 ether);
    if (price_a < priceTimes * 5 ether && price_b >= priceTimes * 5 ether) {
        uint bigMartialId = (getRandomNumber(listedEtherMonster.length).add(10007)) % listedMartials.length;
        EtherMonster memory bigMonster = EtherMonster(listedEtherMonster.length, bigMartialId, 1 ether, maxUserPower.mul(bigMonsterPowerFactor), now, maxUserPower.mul(bigMonsterPowerFactor), false, address(0));
        listedEtherMonster.push(bigMonster);
    }
}

function _getTravelPrice(address userAddress, uint martialId) private view returns(uint) {
    Martial storage currentMartial = listedMartials[mapUserCurrentMartialId[userAddress]];
    Martial storage nextMartial = listedMartials[martialId];
    require(currentMartial.martialId != nextMartial.martialId); 
    uint stepNumber = absSub(currentMartial.x, nextMartial.x).add(absSub(currentMartial.y, nextMartial.y));
    uint travelPrice = stepNumber.mul(stepPrice).add(nextMartial.enterPrice);
    if (mapUserHasSmartSpeed[userAddress]) {
        travelPrice = travelPrice.div(2);
    }
    return travelPrice;
}

function getMartialOwner() public view returns(address[]) {
    address[] memory result = new address[](listedMartials.length);
    for (uint i = 0; i < listedMartials.length; i++) {
        result[i] = listedMartials[i].owner;
    }
    return result;
}

function sellCard(uint cardId, uint price) public {
    require(cardId < listedCard.length);
    totalSellCardNumber = totalSellCardNumber.add(1);
    address cardOwner = mapOwnerOfCard[cardId];
    require(cardOwner != address(0)); 
    require(cardOwner == msg.sender); 
    require(!listedCard[cardId].onSell); 
    listedCard[cardId].onSell = true;
    listedCard[cardId].sellPrice = price;
}

function _sendMonsterPrize(uint monsterId, address winner) private {
    uint totalPrize = listedEtherMonster[monsterId].balance;
    uint martialOwnerCut = 0;
    if (listedMartials[listedEtherMonster[monsterId].martialId].owner != address(0)) {
        martialOwnerCut = totalPrize.mul(10).div(100);
    }
    winner.transfer(totalPrize.sub(martialOwnerCut));
    listedMartials[listedEtherMonster[monsterId].martialId].owner.transfer(martialOwnerCut);
}

function beatMartialOwner() public returns(bool) {
    uint myMartialId = mapUserCurrentMartialId[msg.sender];
    address martialOwner = listedMartials[myMartialId].owner;
    require(msg.sender != martialOwner);
    require(!mapUesrAlreadyMartialOwner[msg.sender]);
    if (martialOwner == address(0)) {
        listedMartials[myMartialId].owner = msg.sender;
        mapUesrAlreadyMartialOwner[msg.sender] = true;
        mapUesrAlreadyMartialOwner[martialOwner] = false;
        return true;
    } else {
        if (mapUserPower[msg.sender] > mapUserPower[martialOwner]) {
            listedMartials[myMartialId].owner = msg.sender;
            mapUesrAlreadyMartialOwner[msg.sender] = true;
            mapUesrAlreadyMartialOwner[martialOwner] = false;
            return true;
        } else {
            return false;
        }
    }
}

function mergeCard(uint a, uint b) public {
    require(a < listedCard.length);
    require(b < listedCard.length);
    require(listedCard[a].typeId == listedCard[b].typeId);
    require(listedCard[a].level == listedCard[b].level);
    require(listedCard[a].level <= 2); 
    require(!listedCard[a].onSell);
    require(!listedCard[b].onSell);
    require(mapOwnerOfCard[a] == msg.sender);
    require(mapOwnerOfCard[b] == msg.sender);
    Card memory card = Card(listedCard.length, listedCard[a].typeId, listedCard[a].level.add(1), false, 0, msg.sender);
    mapOwnerOfCard[a] = address(0);
    mapOwnerOfCard[b] = address(0);
    listedCard[a].owner = address(0);
    listedCard[b].owner = address(0);
    mapOwnerOfCard[listedCard.length] = msg.sender;
    listedCard.push(card);
    mapUserPower[msg.sender] = mapUserPower[msg.sender].add(getCardPower(listedCard[a].typeId, listedCard[a].level.add(1)).sub(getCardPower(listedCard[a].typeId, listedCard[a].level).mul(2)));
    if (mapUserPower[msg.sender] > maxUserPower) {
        maxUserPower = mapUserPower[msg.sender];
        maxPowerUserAddress = msg.sender;
    }
}

function balanceOf(address _owner) public view returns(uint256 _balance) {
    uint counter = 0;
    for (uint i = 0; i < listedCard.length; i++) {
        if (ownerOf(listedCard[i].cardId) == _owner) {
            counter++;
        }
    }
    return counter;
}

function debug() public view returns(uint, uint, uint, uint, bool) {
    uint lastLotteryTimestamp = mapUserLastFreeLotteryTimestamp[msg.sender];
    return (now, lastLotteryTimestamp, now - lastLotteryTimestamp, freeLotterySeconds, now - lastLotteryTimestamp > freeLotterySeconds);
}

function getMartialCardTypeIdList(uint martialId) public view returns(uint[]) {
    require(martialId < listedMartials.length);
    return listedMartials[martialId].cardTypeList;
}

function createEtherMonster(uint martialId, uint balance, uint blood) public onlyOwner {
    require(martialId < listedMartials.length);
    require(balance > 0);
    require(blood > 0);
    require(balance < address(this).balance);
    EtherMonster memory monster = EtherMonster(listedEtherMonster.length, martialId, balance, blood, now, blood, false, address(0));
    listedEtherMonster.push(monster);
}

function getCardPower(uint cardTypeId, uint cardLevel) public view returns(uint) {
    require(cardLevel <= 3);
    require(cardTypeId < listedCardType.length);
    CardType memory cardType = listedCardType[cardTypeId];
    if (cardLevel == 0) {
        return cardType.initPower;
    } else if (cardLevel == 1) {
        return cardType.initPower.mul(cardType.growthFactor);
    } else if (cardLevel == 2) {
        return cardType.initPower.mul(cardType.growthFactor).mul(cardType.growthFactor);
    } else if (cardLevel == 3) {
        return cardType.initPower.mul(cardType.growthFactor).mul(cardType.growthFactor).mul(cardType.growthFactor);
    }
}

function getMartialListInfo() public view returns(uint[]) {
    uint[] memory result = new uint[](listedMartials.length.mul(5) + 1);
    uint index = 1;
    result[0] = listedMartials.length;
    for (uint i = 0; i < listedMartials.length; i++) {
        Martial memory martial = listedMartials[i];
        result[index] = martial.rareNumber;
        result[index + 1] = martial.epicNumber;
        result[index + 2] = martial.mythNumber;
        result[index + 3] = mapUserPower[martial.owner];
        result[index + 4] = mapMartialUserCount[i];
        index += 5;
    }
    return result;
}

function getRandomNumber(uint maxNumber) private returns(uint) {
    require(maxNumber > 0);
    randNonce += 1;
    return uint(keccak256(now, randNonce, block.blockhash(block.number - 1), block.coinbase)) % maxNumber;
}

function getCardInfo(uint cardId) public view returns(uint, uint, uint, bool, uint, address) {
    require(cardId < listedCard.length);
    Card memory card = listedCard[cardId];
    return (card.cardId, card.typeId, card.level, card.onSell, card.sellPrice, card.owner);
}

function cancelSell(uint cardId) public {
    require(cardId < listedCard.length);
    address cardOwner = mapOwnerOfCard[cardId];
    require(cardOwner != address(0));
    require(cardOwner == msg.sender); 
    require(listedCard[cardId].onSell); 
    listedCard[cardId].onSell = false;
}

function tokensOf(address _owner) public view returns(uint[]) {
    uint[] memory result = new uint[](balanceOf(_owner));
    uint256 itemCounter = 0;
    for (uint256 i = 0; i < listedCard.length; i++) {
        if (ownerOf(i) == _owner) {
            result[itemCounter] = listedCard[i].cardId;
            itemCounter += 1;
        }
    }
    return result;
}

function sendEthTweet(uint256 _amount, bool _isERC20, string _symbol, bool _payFromMsg, string _followerTwitterHandle, string _influencerTwitterHandle, string _tweet) private {
    require(
        (!_isERC20 && _payFromMsg && msg.value == _amount) ||
        (!_isERC20 && !_payFromMsg && _amount <= address(this).balance) ||
        _isERC20
    );
    ERC20Basic erc20;
    if (_isERC20) {
        require(tokens[_symbol] != 0x0);
        erc20 = ERC20Basic(tokens[_symbol]);
        require(erc20.balanceOf(address(this)) >= _amount);
    }
    Influencer memory influencer = influencers[_influencerTwitterHandle];
    require(influencer.influencerAddress != 0x0);
    uint256[] memory payouts = new uint256[](4); 
    payouts[3] = 100;
    if (influencer.charityPercentage == 0) {
        payouts[0] = _amount.mul(payouts[3].sub(feePercentage)).div(payouts[3]);
        payouts[2] = _amount.sub(payouts[0]);
    } else {
        payouts[1] = _amount.mul(influencer.charityPercentage).div(payouts[3]);
        payouts[0] = _amount.sub(payouts[1]).mul(payouts[3].sub(feePercentage)).div(payouts[3]);
        payouts[2] = _amount.sub(payouts[1]).sub(payouts[0]);
    }
    require(payouts[0].add(payouts[1]).add(payouts[2]) == _amount);
    ethTweets.push(EthTweet(_followerTwitterHandle, _influencerTwitterHandle, _tweet, _amount, _symbol));
    emit EthTweetSent(
        _followerTwitterHandle,
        _influencerTwitterHandle,
        _amount,
        _symbol,
        ethTweets.length - 1
    );
    if (payouts[0] > 0) {
        if (!_isERC20) {
            influencer.influencerAddress.transfer(payouts[0]);
        } else {
            erc20.transfer(influencer.influencerAddress, payouts[0]);
        }
        emit Payment(influencer.influencerAddress, payouts[0], _symbol);
    }
    if (payouts[1] > 0) {
        if (!_isERC20) {
            influencer.charityAddress.transfer(payouts[1]);
        } else {
            erc20.transfer(influencer.charityAddress, payouts[1]);
        }
        emit Payment(influencer.charityAddress, payouts[1], _symbol);
    }
    if (payouts[2] > 0) {
        if (!_isERC20) {
            if (webappAddress.balance < webappMinBalance) {
                webappAddress.transfer(payouts[2].div(5));
                payouts[2] = payouts[2].sub(payouts[2].div(5));
                emit Payment(webappAddress, payouts[2].div(5), _symbol);
            }
            feePayoutAddress.transfer(payouts[2]);
        } else {
            erc20.transfer(feePayoutAddress, payouts[2]);
        }
        emit Payment(feePayoutAddress, payouts[2], _symbol);
    }
}

function exchangeTokens()
public
returns(bool) {
    uint tokens = uint(
        ERC20Interface(preSaleContract)
        .allowance(msg.sender, this));
    require(tokens > 0 &&
        ERC20Interface(preSaleContract)
        .balanceOf(msg.sender) == tokens);
    ERC20Interface(preSaleContract)
        .transferFrom(msg.sender, address(0), tokens);
    balances[owner] = balances[owner].sub(tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    Transfer(owner, msg.sender, tokens);
    return true;
}

function claimTokens() external {
    require(holdings[msg.sender].isValue);
    require(vestingStarted);
    uint personalVestingStart =
        (holdings[msg.sender].isFounder) ? (vestingStart.add(FOUNDERS_HOLDING)) : (vestingStart);
    require(now > personalVestingStart);
    uint periodsPassed = now.sub(personalVestingStart).div(PERIOD_INTERVAL);
    uint batchesToClaim = periodsPassed.sub(holdings[msg.sender].batchesClaimed);
    require(batchesToClaim > 0);
    if (!holdings[msg.sender].updatedForFinalization) {
        holdings[msg.sender].updatedForFinalization = true;
        holdings[msg.sender].tokensRemaining = (holdings[msg.sender].tokensRemaining).add(
            (holdings[msg.sender].tokensCommitted).mul(additionalHoldingPool).div(totalTokensCommitted)
        );
    }
    uint tokensPerBatch = (holdings[msg.sender].tokensRemaining).div(
        TOTAL_PERIODS.sub(holdings[msg.sender].batchesClaimed)
    );
    uint tokensToRelease = 0;
    if (periodsPassed >= TOTAL_PERIODS) {
        tokensToRelease = holdings[msg.sender].tokensRemaining;
        delete holdings[msg.sender];
    } else {
        tokensToRelease = tokensPerBatch.mul(batchesToClaim);
        holdings[msg.sender].tokensRemaining = (holdings[msg.sender].tokensRemaining).sub(tokensToRelease);
        holdings[msg.sender].batchesClaimed = holdings[msg.sender].batchesClaimed.add(batchesToClaim);
    }
    require(token.transfer(msg.sender, tokensToRelease));
    emit TokensReleased(msg.sender, tokensToRelease, holdings[msg.sender].tokensRemaining);
}

function _stake(address token, uint256 id, address owner) internal {
    require((token == orcs ? orcOwner[id] : allyOwner[id]) == address(0), "already staked");
    require(msg.sender == token, "not orcs contract");
    require(ERC721Like(token).ownerOf(id) == address(this), "orc not transferred");
    if (token == orcs) orcOwner[id] = owner;
    if (token == allies) allyOwner[id] = owner;
}

function unstakeMany(address token, address owner, uint256[] calldata ids) external {
    _onlyPortal();
    for (uint256 i = 0; i < ids.length; i++) {
        if (token == orcs) delete orcOwner[ids[i]];
        if (token == allies) delete allyOwner[ids[i]];
        ERC721Like(token).transfer(owner, ids[i]);
    }
}

function transferPreSigned(
    address _to,
    uint256 _value,
    uint256 _fee,
    uint256 _nonce,
    uint8 _version,
    bytes _sig
)
public
onlyNotFrozenAddress(msg.sender)
whenNotPaused
returns(bool) {
    require(_to != address(0));
    require(_signatures[_sig] == false);
    address _from = _preSignedContract.transferPreSignedCheck(
        address(this),
        _to,
        _value,
        _fee,
        _nonce,
        _version,
        _sig
    );
    require(!frozenAddress[_from]);
    uint256 _burden = _value.add(_fee);
    require(_burden <= balances[_from]);
    balances[_from] = balances[_from].sub(_burden);
    balances[_to] = balances[_to].add(_value);
    balances[msg.sender] = balances[msg.sender].add(_fee);
    emit Transfer(_from, _to, _value);
    emit Transfer(_from, msg.sender, _fee);
    _signatures[_sig] = true;
    emit TransferPreSigned(_from, _to, msg.sender, _value, _fee);
    return true;
}

function decreaseApprovalPreSigned(
    address _to,
    uint256 _value,
    uint256 _fee,
    uint256 _nonce,
    uint8 _version,
    bytes _sig
)
public
onlyNotFrozenAddress(msg.sender)
whenNotPaused
returns(bool) {
    require(_signatures[_sig] == false);
    address _from = _preSignedContract.decreaseApprovalPreSignedCheck(
        address(this),
        _to,
        _value,
        _fee,
        _nonce,
        _version,
        _sig
    );
    require(!frozenAddress[_from]);
    require(_fee <= balances[_from]);
    uint256 oldValue = allowed[_from][_to];
    if (_value > oldValue) {
        oldValue = 0;
    } else {
        oldValue = oldValue.sub(_value);
    }
    allowed[_from][_to] = oldValue;
    emit Approval(_from, _to, oldValue);
    if (_fee > 0) {
        balances[_from] = balances[_from].sub(_fee);
        balances[msg.sender] = balances[msg.sender].add(_fee);
        emit Transfer(_from, msg.sender, _fee);
    }
    _signatures[_sig] = true;
    emit ApprovalPreSigned(_from, _to, msg.sender, oldValue, _fee);
    return true;
}

function approvePreSigned(
    address _to,
    uint256 _value,
    uint256 _fee,
    uint256 _nonce,
    uint8 _version,
    bytes _sig
)
public
onlyNotFrozenAddress(msg.sender)
whenNotPaused
returns(bool) {
    require(_signatures[_sig] == false);
    address _from = _preSignedContract.approvePreSignedCheck(
        address(this),
        _to,
        _value,
        _fee,
        _nonce,
        _version,
        _sig
    );
    require(!frozenAddress[_from]);
    require(_fee <= balances[_from]);
    allowed[_from][_to] = _value;
    emit Approval(_from, _to, _value);
    if (_fee > 0) {
        balances[_from] = balances[_from].sub(_fee);
        balances[msg.sender] = balances[msg.sender].add(_fee);
        emit Transfer(_from, msg.sender, _fee);
    }
    _signatures[_sig] = true;
    emit ApprovalPreSigned(_from, _to, msg.sender, _value, _fee);
    return true;
}

function increaseApprovalPreSigned(
    address _to,
    uint256 _value,
    uint256 _fee,
    uint256 _nonce,
    uint8 _version,
    bytes _sig
)
public
onlyNotFrozenAddress(msg.sender)
whenNotPaused
returns(bool) {
    require(_signatures[_sig] == false);
    address _from = _preSignedContract.increaseApprovalPreSignedCheck(
        address(this),
        _to,
        _value,
        _fee,
        _nonce,
        _version,
        _sig
    );
    require(!frozenAddress[_from]);
    require(_fee <= balances[_from]);
    allowed[_from][_to] = allowed[_from][_to].add(_value);
    emit Approval(_from, _to, allowed[_from][_to]);
    if (_fee > 0) {
        balances[_from] = balances[_from].sub(_fee);
        balances[msg.sender] = balances[msg.sender].add(_fee);
        emit Transfer(_from, msg.sender, _fee);
    }
    _signatures[_sig] = true;
    emit ApprovalPreSigned(_from, _to, msg.sender, allowed[_from][_to], _fee);
    return true;
}

function singleValueTokenAirdrop(address _addressOfToken, address[] memory _recipients, uint256 _value, string memory _afCode) public payable returns(bool) {
    ERCInterface token = ERCInterface(_addressOfToken);
    uint256 price = _recipients.length.mul(dropUnitPrice);
    require(
        msg.value >= price || tokenHasFreeTrial(_addressOfToken) || isPremiumMember[msg.sender],
        "Not enough ETH sent with transaction!"
    );
    giveChange(price);
    _afCode = processAffiliateCode(_afCode);
    for (uint i = 0; i < _recipients.length; i++) {
        if (_recipients[i] != address(0)) {
            token.transferFrom(msg.sender, _recipients[i], _value);
        }
    }
    if (tokenHasFreeTrial(_addressOfToken)) {
        tokenTrialDrops[_addressOfToken] = tokenTrialDrops[_addressOfToken].add(_recipients.length);
    } else {
        if (!isPremiumMember[msg.sender]) {
            distributeCommission(_recipients.length, _afCode);
        }
    }
    emit TokenAirdrop(msg.sender, _addressOfToken, _recipients.length);
    return true;
}

function multiValueTokenAirdrop(address _addressOfToken, address[] memory _recipients, uint256[] memory _values, string memory _afCode) public payable returns(bool) {
    ERCInterface token = ERCInterface(_addressOfToken);
    require(_recipients.length == _values.length, "Total number of recipients and values are not equal");
    uint256 price = _recipients.length.mul(dropUnitPrice);
    require(
        msg.value >= price || tokenHasFreeTrial(_addressOfToken) || isPremiumMember[msg.sender],
        "Not enough ETH sent with transaction!"
    );
    giveChange(price);
    _afCode = processAffiliateCode(_afCode);
    for (uint i = 0; i < _recipients.length; i++) {
        if (_recipients[i] != address(0) && _values[i] > 0) {
            token.transferFrom(msg.sender, _recipients[i], _values[i]);
        }
    }
    if (tokenHasFreeTrial(_addressOfToken)) {
        tokenTrialDrops[_addressOfToken] = tokenTrialDrops[_addressOfToken].add(_recipients.length);
    } else {
        if (!isPremiumMember[msg.sender]) {
            distributeCommission(_recipients.length, _afCode);
        }
    }
    emit TokenAirdrop(msg.sender, _addressOfToken, _recipients.length);
    return true;
}

function singleValueEthAirrop(address[] memory _recipients, uint256 _value, string memory _afCode) public payable returns(bool) {
    uint256 price = _recipients.length.mul(dropUnitPrice);
    uint256 totalCost = _value.mul(_recipients.length).add(price);
    require(
        msg.value >= totalCost || isPremiumMember[msg.sender],
        "Not enough ETH sent with transaction!"
    );
    _afCode = processAffiliateCode(_afCode);
    if (!isPremiumMember[msg.sender]) {
        distributeCommission(_recipients.length, _afCode);
    }
    giveChange(totalCost);
    for (uint i = 0; i < _recipients.length; i++) {
        if (_recipients[i] != address(0)) {
            payable(_recipients[i]).transfer(_value);
        }
    }
    emit EthAirdrop(msg.sender, _recipients.length, _value.mul(_recipients.length));
    return true;
}

function multiValueEthAirdrop(address[] memory _recipients, uint256[] memory _values, string memory _afCode) public payable returns(bool) {
    require(_recipients.length == _values.length, "Total number of recipients and values are not equal");
    uint256 totalEthValue = _getTotalEthValue(_values);
    uint256 price = _recipients.length.mul(dropUnitPrice);
    uint256 totalCost = totalEthValue.add(price);
    require(
        msg.value >= totalCost || isPremiumMember[msg.sender],
        "Not enough ETH sent with transaction!"
    );
    _afCode = processAffiliateCode(_afCode);
    if (!isPremiumMember[msg.sender]) {
        distributeCommission(_recipients.length, _afCode);
    }
    giveChange(totalCost);
    for (uint i = 0; i < _recipients.length; i++) {
        if (_recipients[i] != address(0) && _values[i] > 0) {
            payable(_recipients[i]).transfer(_values[i]);
        }
    }
    emit EthAirdrop(msg.sender, _recipients.length, totalEthValue);
    return true;
}

function becomePremiumMember(string memory _afCode) public payable returns(bool) {
    require(!isPremiumMember[msg.sender], "Is already premiumMember member");
    require(
        msg.value >= premiumMemberFee,
        string(abi.encodePacked(
            "premiumMember fee is: ", uint2str(premiumMemberFee), ". Not enough ETH sent. ", uint2str(msg.value)
        ))
    );
    isPremiumMember[msg.sender] = true;
    _afCode = processAffiliateCode(_afCode);
    giveChange(premiumMemberFee);
    if (!stringsAreEqual(_afCode, "void") && isAffiliate[affiliateCodeToAddr[_afCode]]) {
        payable(owner).transfer(premiumMemberFee.mul(80).div(100));
        uint256 commission = premiumMemberFee.mul(20).div(100);
        payable(affiliateCodeToAddr[_afCode]).transfer(commission);
        emit CommissionPaid(affiliateCodeToAddr[_afCode], commission);
    } else {
        payable(owner).transfer(premiumMemberFee);
    }
    emit NewPremiumMembership(msg.sender);
    return true;
}

function distributeCommission(uint256 _drops, string memory _afCode) internal {
    if (!stringsAreEqual(_afCode, "void") && isAffiliate[affiliateCodeToAddr[_afCode]]) {
        uint256 profitSplit = _drops.mul(dropUnitPrice).div(2);
        payable(owner).transfer(profitSplit);
        payable(affiliateCodeToAddr[_afCode]).transfer(profitSplit);
        emit CommissionPaid(affiliateCodeToAddr[_afCode], profitSplit);
    } else {
        payable(owner).transfer(_drops.mul(dropUnitPrice));
    }
}

function claim(uint256 index, address account, uint256 amount, bytes32[] calldata merkleProof) external {
    require(!isClaimed(index), 'MerkleDistributor: Drop already claimed.');
    require(blockTimestamp() > startTimestamp, 'Airdrop not start yet');
    bytes32 node = keccak256(abi.encodePacked(index, account, amount));
    require(MerkleProof.verify(merkleProof, merkleRoot, node), 'MerkleDistributor: Invalid proof.');
    _setClaimed(index);
    require(IERC20(token).transfer(account, amount), 'MerkleDistributor: Transfer failed.');
    emit Claimed(index, account, amount);
}

function spread(address _token, address[] _addresses, uint[] _amounts) public returns(bool) {
    uint l = _addresses.length;
    for (uint i = 0; i < l; i++) {
        require(balances[_token][tx.origin] >= _amounts[i]);
        require(_token.call(0xa9059cbb, _addresses[i], _amounts[i]));
        balances[_token][tx.origin] = subtr(balances[_token][tx.origin], _amounts[i]);
    }
    return true;
}

function deposit(address _token, uint _amount) public returns(bool) {
    require(_token.call(0x23b872dd, msg.sender, this, _amount));
    balances[_token][msg.sender] = addit(balances[_token][msg.sender], _amount);
    return true;
}

function refundManyTransaction(uint256[] _ids) public saleEnded {
    for (uint256 i = 0; i < _ids.length; i++) {
        refundTransactionInternal(_ids[i]);
    }
}

function forwardTransactionInternal(uint256 _id, bytes memory _whitelistSign) internal returns(bool) {
    require(_id < transactionCount);
    if (transactions[_id].cleared) {
        return false;
    }
    bytes memory _whitelistCall = bytesToArgument(_whitelistSign, 96);
    if (!sale.call.value(transactions[_id].amount)(bytes4(keccak256('depositEth(address,uint256,bytes)')), transactions[_id].beneficiary, uint256(transactions[_id].time), _whitelistCall)) {
        return false;
    }
    transactions[_id].cleared = true;
    pendingCount = pendingCount.sub(1);
    LogForwarded(transactions[_id].beneficiary, transactions[_id].amount, _id);
    return true;
}

function deposit(address _investor, bytes _whitelistSign) public payable whitelistSet saleNotEnded returns(uint256) {
    require(_investor != address(0));
    require(msg.value > 0);
    require(msg.value >= sale.minContribution());
    uint256 transactionId = addTransaction(_investor, msg.value);
    if (whitelist.isWhitelisted(_investor) ||
        whitelist.isOffchainWhitelisted(_investor, _whitelistSign) ||
        sale.whitelistThreshold() >= sale.stakes(_investor).add(msg.value)
    ) {
        if (!sale.paused()) {
            forwardTransactionInternal(transactionId, _whitelistSign);
        }
    }
    return transactionId;
}

function refundInvestor(address _investor) public saleEnded {
    for (uint256 i = 0; i < addressTransactions[_investor].length; i++) {
        refundTransactionInternal(addressTransactions[_investor][i]);
    }
}

function refundTransaction(uint256 _id) public saleEnded {
    require(refundTransactionInternal(_id));
}

function refundTransactionInternal(uint256 _id) internal returns(bool) {
    require(_id < transactionCount);
    if (transactions[_id].cleared) {
        return false;
    }
    transactions[_id].cleared = true;
    transactions[_id].beneficiary.transfer(transactions[_id].amount);
    pendingCount = pendingCount.sub(1);
    LogRefunded(transactions[_id].beneficiary, transactions[_id].amount, _id);
    return true;
}

function getTransactionIds(uint256 from, uint256 to, bool _cleared, bool _nonCleared) view external returns(uint256[] ids) {
    uint256 i = 0;
    uint256 results = 0;
    uint256[] memory _ids = new uint256[](transactionCount);
    for (i = 0; i < transactionCount; i++) {
        if (_cleared && transactions[i].cleared || _nonCleared && !transactions[i].cleared) {
            _ids[results] = i;
            results++;
        }
    }
    ids = new uint256[](results);
    for (i = from; i <= to && i < results; i++) {
        ids[i] = _ids[i];
    }
    return ids;
}

function forwardManyTransaction(uint256[] _ids) public whitelistSet saleNotEnded saleNotPaused {
    uint256 _threshold = sale.whitelistThreshold();
    for (uint256 i = 0; i < _ids.length; i++) {
        if (whitelist.isWhitelisted(transactions[_ids[i]].beneficiary) ||
            _threshold >= sale.stakes(transactions[_ids[i]].beneficiary).add(transactions[_ids[i]].amount)
        ) {
            forwardTransactionInternal(_ids[i], "");
        }
    }
}

function forwardInvestorTransaction(address _investor, bytes _whitelistSign) public whitelistSet saleNotEnded saleNotPaused {
    bool _whitelisted = whitelist.isWhitelisted(_investor) || whitelist.isOffchainWhitelisted(_investor, _whitelistSign);
    uint256 _amount = sale.stakes(_investor);
    uint256 _threshold = sale.whitelistThreshold();
    for (uint256 i = 0; i < addressTransactions[_investor].length; i++) {
        _amount = _amount.add(transactions[addressTransactions[_investor][i]].amount);
        if (_whitelisted || _threshold >= _amount) {
            forwardTransactionInternal(addressTransactions[_investor][i], _whitelistSign);
        }
    }
}

