function deposit(uint _referrerID) public payable isHuman {
    require(_referrerID <= currentStakeID, "Who referred you?");
    require(msg.value >= minBetLevel, "Doesn't meet minimum stake.");
    uint nextPayAfterTime = getNextPayoutTime();
    if (investorToDepostIndex[msg.sender].isExist) {
        if (investorToDepostIndex[msg.sender].nextPayAfterTime < now) {
            collectPayoutForAddress(msg.sender);
        }
        investorToDepostIndex[msg.sender].value += msg.value;
        investorToDepostIndex[msg.sender].lastBetTime = now;
    } else {
        DepositInfo memory newDeposit;
        newDeposit = DepositInfo({
            value: msg.value,
            firstBetTime: now,
            lastBetTime: now,
            lastPaymentTime: 0,
            nextPayAfterTime: nextPayAfterTime,
            isExist: true,
            id: currentStakeID,
            referrerID: _referrerID
        });
        investorToDepostIndex[msg.sender] = newDeposit;
        idToAddressIndex[currentStakeID] = msg.sender;
        currentStakeID++;
    }
    if (now > nextPrizeTime) {
        doMidnightRun();
    }
    currentPrizeStakeID++;
    MidnightRunDeposit memory midnitrunDeposit;
    midnitrunDeposit.user = msg.sender;
    midnitrunDeposit.value = msg.value;
    stakeIDToDepositIndex[currentPrizeStakeID] = midnitrunDeposit;
    midnightPrize += msg.value.mul(midnightPrizePercent).div(10000);
    if (investorToDepostIndex[msg.sender].referrerID != 0) {
        uint refToPay = msg.value.mul(referrerPercent).div(10000);
        idToAddressIndex[investorToDepostIndex[msg.sender].referrerID].transfer(refToPay);
        owner().transfer(msg.value.mul(referrerAndOwnerPercent - referrerPercent).div(10000));
        emit ReferralPayout(msg.sender, idToAddressIndex[investorToDepostIndex[msg.sender].referrerID], refToPay, referrerPercent, now);
    } else {
        owner().transfer(msg.value.mul(referrerAndOwnerPercent).div(10000));
    }
}

function auctionEndVoucher(
    bytes memory _data,
    bytes memory _signedRawTxCreateAuction,
    bytes memory _signedRawTxBidding,
    bytes memory _send
) public maintenanceLockable {
    bytes32 _auctionEndVoucherHash = keccak256(_signedRawTxCreateAuction);
    if (auctionEndVoucherSubmitted[_auctionEndVoucherHash] == true) {
        emit LogError(version, "AUCTION_END_VOUCHER_ALREADY_SUBMITED");
        return;
    }
    InfoFromCreateAuction memory _infoFromCreateAuction = getInfoFromCreateAuction(_signedRawTxCreateAuction);
    address _auctionContractAddress;
    address _winnerSigner;
    uint256 _winnerAmount;
    InfoFromBidding memory _infoFromBidding;
    if (_signedRawTxBidding.length > 1) {
        _infoFromBidding = getInfoFromBidding(_signedRawTxBidding, _infoFromCreateAuction.tokenHash);
        if (!verifyWinnerDepot(_infoFromBidding)) {
            return;
        }
    }
    if (!auctionEndVoucherOracleSignatureVerification(
            _data,
            keccak256(_send),
            _infoFromCreateAuction,
            _infoFromBidding
        )) {
        emit LogError(version, "AUCTION_END_VOUCHER_ORACLE_INVALID_SIGNATURE");
        return;
    }
    if (!AuctionityLibraryDeposit.sendTransfer(_infoFromCreateAuction.tokenContractAddress, _data, 97)) {
        if (_data[97] > 0x01) { 
            revert("More than one transfer function to call");
        } else {
            emit LogError(version, "AUCTION_END_VOUCHER_TRANSFER_FAILED");
            return;
        }
    }
    if (_signedRawTxBidding.length > 1) {
        if (!sendExchange(_send, _infoFromCreateAuction, _infoFromBidding)) {
            return;
        }
    }
    auctionEndVoucherList.push(_auctionEndVoucherHash);
    auctionEndVoucherSubmitted[_auctionEndVoucherHash] = true;
    emit LogAuctionEndVoucherSubmitted(
        _infoFromBidding.auctionContractAddress,
        _infoFromCreateAuction.tokenContractAddress,
        _infoFromCreateAuction.tokenId,
        _infoFromCreateAuction.auctionSeller,
        _infoFromBidding.signer,
        _infoFromBidding.amount
    );
}

