    withdraw(false);
}

function calculateEthereumReceived(uint256 _tokensToSell)
public
view
returns(uint256) {
    require(_tokensToSell <= tokenSupply_);
    uint256 _ethereum = tokensToEthereum_(_tokensToSell);
    uint256 _dividends = SafeMath.div(SafeMath.mul(_ethereum, exitFee()), 100);
    uint256 _fundPayout = SafeMath.div(SafeMath.mul(_ethereum, fundFee_), 100);
    uint256 _taxedEthereum = SafeMath.sub(SafeMath.sub(_ethereum, _dividends), _fundPayout);
    return _taxedEthereum;
}

function unfreeze(uint256 timestamp) public returns(uint256 unfreezeAmount) {
    require(timestamp <= block.timestamp);
    uint256 unfreezeIndex = uint256(timestamp.parseTimestamp().year) * 10000 + uint256(timestamp.parseTimestamp().month) * 100 + uint256(timestamp.parseTimestamp().day);
    frozenBalance = frozenBalance.sub(frozenRecords[unfreezeIndex].value);
    balances[owner] = balances[owner].add(frozenRecords[unfreezeIndex].value);
    unfreezeAmount = frozenRecords[unfreezeIndex].value;
    emit Unfreeze(owner, unfreezeAmount, timestamp);
    frozenRecords[unfreezeIndex].value = 0;
    return unfreezeAmount;
}

function release(uint256 timestamp, uint256 sysAmount) public onlyOperator returns(uint256 _actualRelease) {
    require(timestamp >= createTime && timestamp <= block.timestamp);
    require(!checkIsReleaseRecordExist(timestamp));
    updateReleaseAmount(timestamp);
    require(sysAmount <= releaseAmountPerDay.mul(4).div(5));
    require(totalSupply_ >= releasedSupply.add(releaseAmountPerDay));
    balances[owner] = balances[owner].add(releaseAmountPerDay);
    releasedSupply = releasedSupply.add(releaseAmountPerDay);
    uint256 _releaseIndex = uint256(timestamp.parseTimestamp().year) * 10000 + uint256(timestamp.parseTimestamp().month) * 100 + uint256(timestamp.parseTimestamp().day);
    releaseRecords[_releaseIndex] = ReleaseRecord(releaseAmountPerDay, _releaseIndex);
    emit Release(owner, releaseAmountPerDay, sysAmount, timestamp);
    systemFreeze(sysAmount.div(5), timestamp.add(180 days));
    systemFreeze(sysAmount.mul(6).div(10), timestamp.add(200 years));
    return releaseAmountPerDay;
}

function enableReturnContribution() external onlyOwner {
    require(totalContributed < totalLendingAmount);
    require(now > fundingEndTime);
    state = LendingState.ProjectNotFunded;
    StateChange(uint(state));
}

function isContribPeriodRunning() public constant returns(bool) {
    return fundingStartTime <= now && fundingEndTime > now && !capReached;
}

function contributeWithAddress(address contributor) public payable whenNotPaused {
    require(msg.value >= minContribAmount);
    require(isContribPeriodRunning());
    uint contribValue = msg.value;
    uint excessContribValue = 0;
    uint oldTotalContributed = totalContributed;
    totalContributed = oldTotalContributed.add(contribValue);
    uint newTotalContributed = totalContributed;
    if (newTotalContributed >= totalLendingAmount &&
        oldTotalContributed < totalLendingAmount) {
        capReached = true;
        fundingEndTime = now;
        onCapReached(fundingEndTime);
        excessContribValue = newTotalContributed.sub(totalLendingAmount);
        contribValue = contribValue.sub(excessContribValue);
        totalContributed = totalLendingAmount;
    }
    if (investors[contributor].amount == 0) {
        investorsKeys.push(contributor);
    }
    investors[contributor].amount = investors[contributor].amount.add(contribValue);
    if (excessContribValue > 0) {
        msg.sender.transfer(excessContribValue);
        excessContributionReturned(msg.sender, excessContribValue);
    }
    onContribution(newTotalContributed, contributor, contribValue, investorsKeys.length);
}

function finishContributionPeriod(uint256 _initialFiatPerEthRate) onlyOwner {
    require(capReached == true);
    initialFiatPerEthRate = _initialFiatPerEthRate;
    borrower.transfer(totalContributed);
    state = LendingState.AwaitingReturn;
    StateChange(uint(state));
    totalLendingFiatAmount = totalLendingAmount.mul(initialFiatPerEthRate);
    borrowerReturnFiatAmount = totalLendingFiatAmount.mul(lendingInterestRatePercentage).div(100);
}

function successful() public {
    require(state == State.Successful); 
    uint256 temp = pending[creator]; 
    pending[creator] = 0; 
    require(tokenReward.transfer(creator, temp)); 
    emit LogContributorsPayout(creator, temp); 
    creator.transfer(address(this).balance); 
    emit LogBeneficiaryPaid(creator); 
}

function checkIfFundingCompleteOrExpired() public {
    if ((totalDistributed == hardCap || now > SaleDeadline) &&
        state != State.Successful &&
        state != State.Paused) {
        pending[creator] = tokenReward.balanceOf(address(this)).sub(totalDistributed);
        state = State.Successful; 
        completedAt = now; 
        emit LogFundingSuccessful(totalRaised); 
        successful(); 
    }
}

function contribute(address _target) public notFinished payable {
    require(now > SaleStart); 
    address user;
    if (_target != address(0) && level[msg.sender] >= 1) {
        user = _target;
    } else {
        user = msg.sender; 
    }
    require(whiteList[user] == true); 
    totalRaised = totalRaised.add(msg.value); 
    uint256 tokenBought = msg.value.mul(rate); 
    uint256 bonus = 0; 
    uint256 buyHelper = tokenBought; 
    if (bonus1Remain > 0) { 
        if (buyHelper <= bonus1Remain) { 
            bonus1Remain = bonus1Remain.sub(buyHelper); 
            bonus = bonus.add((buyHelper.mul(2)).div(10)); 
            buyHelper = 0; 
        } else { 
            buyHelper = buyHelper.sub(bonus1Remain); 
            bonus = bonus.add((bonus1Remain.mul(2)).div(10)); 
            bonus1Remain = 0; 
        }
    }
    if (bonus2Remain > 0 && buyHelper > 0) {
        if (buyHelper <= bonus2Remain) { 
            bonus2Remain = bonus2Remain.sub(buyHelper); 
            bonus = bonus.add((buyHelper.mul(15)).div(100)); 
            buyHelper = 0; 
        } else { 
            buyHelper = buyHelper.sub(bonus2Remain); 
            bonus = bonus.add((bonus2Remain.mul(15)).div(100)); 
            bonus2Remain = 0; 
        }
    }
    if (bonus3Remain > 0 && buyHelper > 0) {
        if (buyHelper <= bonus3Remain) { 
            bonus3Remain = bonus3Remain.sub(buyHelper); 
            bonus = bonus.add(buyHelper.div(10)); 
            buyHelper = 0; 
        } else { 
            buyHelper = buyHelper.sub(bonus3Remain); 
            bonus = bonus.add(bonus3Remain.div(10)); 
            bonus3Remain = 0; 
        }
    }
    if (bonus4Remain > 0 && buyHelper > 0) {
        if (buyHelper <= bonus4Remain) { 
            bonus4Remain = bonus4Remain.sub(buyHelper); 
            bonus = bonus.add((buyHelper.mul(5)).div(100)); 
            buyHelper = 0; 
        } else { 
            buyHelper = buyHelper.sub(bonus4Remain); 
            bonus = bonus.add((bonus4Remain.mul(5)).div(100)); 
            bonus4Remain = 0; 
        }
    }
    tokenBought = tokenBought.add(bonus); 
    require(totalDistributed.add(tokenBought) <= hardCap); 
    pending[user] = pending[user].add(tokenBought); 
    totalDistributed = totalDistributed.add(tokenBought); 
    emit LogFundingReceived(user, msg.value, totalRaised); 
    checkIfFundingCompleteOrExpired(); 
}

function purchase(uint _teamId) public payable {
    address oldOwner = ownerOf(_teamId);
    address newOwner = msg.sender;
    uint sellingPrice = teamIndexToPrice[_teamId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint payment = _calculatePaymentToOwner(sellingPrice);
    uint excessPayment = msg.value.sub(sellingPrice);
    uint newPrice = _calculateNewPrice(sellingPrice);
    teamIndexToPrice[_teamId] = newPrice;
