function withdraw() public returns(bool success) {
    uint value = WinchainInterface(winToken).balanceOf(address(this));
    bytes4 methodId = bytes4(keccak256("transfer(address,uint256)"));
    require(value > 0);
    require(block.timestamp >= deadlineToFreedTeamPool);
    require(winToken.call(methodId, receiverAddress, value));
    emit Withdraw(receiverAddress, value);
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    require(!frozenAccount[msg.sender]);
    require(now > frozenTimestamp[msg.sender]);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function contribute(address _buyer, uint256 _weiAmount) internal {
    require(_buyer != address(0));
    require(!_buyer.isContract());
    require(whitelist.whitelist(_buyer));
    if (_weiAmount == 0) {
        return;
    }
    require(totalTokensSold < totalTokensForSale);
    uint currentRate = stages[currentStage].rate;
    uint256 tokensToMint = _weiAmount.mul(currentRate);
    uint256 saleableTokens;
    uint256 acceptedWei;
    if (currentStage == (totalStages - 1) && totalTokensSold.add(tokensToMint) > totalTokensForSale) {
        saleableTokens = totalTokensForSale - totalTokensSold;
        acceptedWei = saleableTokens.div(currentRate);
        _buyTokensInCurrentStage(_buyer, acceptedWei, saleableTokens);
        uint256 weiToRefund = _weiAmount.sub(acceptedWei);
        _buyer.transfer(weiToRefund);
        emit EthRefunded(_buyer, weiToRefund);
    } else if (totalTokensSold.add(tokensToMint) < stages[currentStage].tokenAllocated) {
        _buyTokensInCurrentStage(_buyer, _weiAmount, tokensToMint);
    } else {
        saleableTokens = stages[currentStage].tokenAllocated.sub(totalTokensSold);
        acceptedWei = saleableTokens.div(currentRate);
        _buyTokensInCurrentStage(_buyer, acceptedWei, saleableTokens);
        if (totalTokensSold >= stages[currentStage].tokenAllocated && currentStage + 1 < totalStages) {
            _setCrowdsaleStage(currentStage + 1);
        }
        if (_weiAmount.sub(acceptedWei) > 0) {
            contribute(_buyer, _weiAmount.sub(acceptedWei));
        }
    }
}

function _buyTokensInCurrentStage(address _buyer, uint _weiAmount, uint _tokenAmount) internal {
    totalWeiRaised = totalWeiRaised.add(_weiAmount);
    totalTokensSold = totalTokensSold.add(_tokenAmount);
    mintableToken.mint(_buyer, _tokenAmount);
    wallet.transfer(_weiAmount);
    emit TokenPurchase(_buyer, _weiAmount, _tokenAmount);
}

function hasClosed() public view returns(bool) {
    return block.timestamp > closingTime || totalTokensSold >= totalTokensForSale;
}

function proxyPayment(address participant) public payable {
    require(participant != address(0x0));
    uint nowTime = getNow();
    require(nowTime >= startDate && nowTime <= endDate);
    require(isInWhitelist(msg.sender));
    require(isInWhitelist(participant));
    uint weiRaised = msg.value;
    require(weiRaised >= CONTRIBUTIONS_MIN);
    uint tokens = TOKEN_PER_ETHER.mul(weiRaised);
    crowsaleShare = crowsaleShare.add(tokens);
    require(crowsaleShare <= TOKENS_CAP_ICO);
    weiBalances[participant] = weiBalances[participant].add(weiRaised);
    balances[participant] = balances[participant].add(tokens);
    balances[wallet] = balances[wallet].sub(tokens);
    wallet.transfer(weiRaised);
    TokenPurchase(wallet, msg.sender, participant, weiRaised, tokens);
}

function setEndDate(uint _endDate) public onlyOwner {
    uint nowTime = getNow();
    require(endDate > nowTime);
    require(_endDate > nowTime);
    endDate = _endDate;
}

function setStartDate(uint _startDate) public onlyOwner {
    uint nowTime = getNow();
    require(startDate > nowTime);
    require(_startDate > nowTime);
    startDate = _startDate;
    uint tempEndDate = startDate.add(MIN_CROWSALE_TIME);
    if (endDate < tempEndDate) {
        endDate = tempEndDate;
    }
}

function hasEnded() public view returns(bool) {
    return getNow() > endDate;
}

function play(uint256 number) payable public {
    require(msg.value >= betPrice && number < 16);
    Game game;
    game.player = msg.sender;
    game.number = number;
    gamesPlayed.push(game);
    if (number == secretNumber) {
        if (msg.value * 15 > this.balance) {
            msg.sender.transfer(this.balance);
        } else {
            msg.sender.transfer(msg.value * 15);
        }
    }
    generateNewRandom();
    lastPlayed = now;
}

function checkTimeBonusPercentage() internal view returns(uint) {
    uint timeBonusInPercentage = 0;
    if (now < icoTimeBonusPhase1End) {
        timeBonusInPercentage = icoPhase1TimeBonusInPercentage;
    } else if (now < icoTimeBonusPhase2End) {
        timeBonusInPercentage = icoPhase2TimeBonusInPercentage;
    }
    return timeBonusInPercentage;
}

function claimToken() external {
    require(currentSaleStage == SaleStage.ICO || currentSaleStage == SaleStage.Closed);
    if (currentSaleStage == SaleStage.ICO) {
        if (ibcFunded == totalFundingGoalInIBC || now >= icoEnd) {
            updateSaleStage(SaleStage.Closed);
        } else {
            revert();
        }
    }
    require(ibcVaultBalanceOf[msg.sender] > 0);
    uint tokenAmount = ibcVaultBalanceOf[msg.sender];
    if (now < icoEnd + fundingRatePredictionBonusClaimWindow) {
        if (fundingRatePredictionBonusPoolInIBC > 0) {
            uint finalFundingRate = mul(ibcFunded, 100) / totalFundingGoalInIBC;
            if (finalFundingRate > 100) {
                finalFundingRate = 100;
            }
            if (fundingRatePredictionOf[msg.sender] == finalFundingRate) {
                if (!fundingRatePredictionBingoOf[msg.sender]) {
                    fundingRatePredictionBingoOf[msg.sender] = true;
                    uint fundingRatePredictionBingoBonus = mul(baseRewardTokenBalanceOf[msg.sender], icoFundingRatePredictionBonusInPercentage) / 100;
                    if (fundingRatePredictionBingoBonus > fundingRatePredictionBonusPoolInIBC) {
                        fundingRatePredictionBingoBonus = fundingRatePredictionBonusPoolInIBC;
                    }
                    fundingRatePredictionBonusPoolInIBC = sub(fundingRatePredictionBonusPoolInIBC, fundingRatePredictionBingoBonus);
                    tokenAmount = add(tokenAmount, fundingRatePredictionBingoBonus);
                }
            }
        }
    }
    ibcVaultBalanceOf[msg.sender] = 0;
    ibcDistributed = add(ibcDistributed, tokenAmount);
    tokenReward.transfer(msg.sender, tokenAmount);
    emit TokenClaimed(msg.sender, tokenAmount);
}

function burnAllRemainingIBC() external {
    require(currentSaleStage == SaleStage.Closed);
    require(now >= icoEnd + fundingRatePredictionBonusClaimWindow);
    require(msg.sender == admin);
    require(fundingRatePredictionBonusPoolInIBC > 0);
    uint currentFundingRatePredictionBonusPoolInIBC = fundingRatePredictionBonusPoolInIBC;
    fundingRatePredictionBonusPoolInIBC = 0;
    if (!tokenReward.burn(currentFundingRatePredictionBonusPoolInIBC)) {
        fundingRatePredictionBonusPoolInIBC = currentFundingRatePredictionBonusPoolInIBC;
    }
}

function participateICONow(address referrer, uint fundingRatePrediction) private {
    require(currentSaleStage == SaleStage.Break || currentSaleStage == SaleStage.ICO);
    if (currentSaleStage == SaleStage.Break) {
        if (now >= icoStart && now < icoEnd) {
            updateSaleStage(SaleStage.ICO);
        } else {
            revert();
        }
    } else if (currentSaleStage == SaleStage.ICO) {
        require(now >= icoStart && now < icoEnd);
    }
    require(referrer != msg.sender);
    require(fundingRatePrediction >= 1 && fundingRatePrediction <= 100);
    uint amount = msg.value;
    uint price = icoPrice;
    uint baseRewardTokenAmount = mul(amount, price);
    uint tokenAmount = add(baseRewardTokenAmount, calculateInstantBonusAmount(baseRewardTokenAmount, referrer));
    uint referrerReferralBonus = 0;
    if (referrer != address(0)) {
        referrerReferralBonus = mul(baseRewardTokenAmount, icoReferralBonusInPercentage) / 100;
    }
    if (add(add(ibcFunded, tokenAmount), referrerReferralBonus) < totalFundingGoalInIBC) {
        require(msg.value >= minFundInEther);
    } else {
        require(add(add(ibcFunded, tokenAmount), referrerReferralBonus) == totalFundingGoalInIBC);
    }
    if (add(add(ibcFunded, tokenAmount), referrerReferralBonus) == totalFundingGoalInIBC) {
        updateSaleStage(SaleStage.Closed);
    }
    balanceOf[msg.sender] = add(balanceOf[msg.sender], amount);
    baseRewardTokenBalanceOf[msg.sender] = add(baseRewardTokenBalanceOf[msg.sender], baseRewardTokenAmount);
    fundingRatePredictionOf[msg.sender] = fundingRatePrediction;
    etherRaised = add(etherRaised, amount);
    contributionCount++;
    ibcFunded = add(ibcFunded, tokenAmount);
    ibcVaultBalanceOf[msg.sender] = add(ibcVaultBalanceOf[msg.sender], tokenAmount);
    if (referrerReferralBonus != 0) {
        ibcFunded = add(ibcFunded, referrerReferralBonus);
        ibcVaultBalanceOf[referrer] = add(ibcVaultBalanceOf[referrer], referrerReferralBonus);
    }
    emit FundTransfer(SaleStage.ICO, msg.sender, amount, true);
}

function updateSaleStage(SaleStage saleStage) private {
    currentSaleStage = saleStage;
    if (saleStage == SaleStage.Break) {
        icoStart = now + breakDurationBetweenPresaleAndICO;
        icoTimeBonusPhase1End = icoStart + icoPhaseTimeInterval;
        icoTimeBonusPhase2End = icoTimeBonusPhase1End + icoPhaseTimeInterval;
        icoEnd = icoTimeBonusPhase2End + icoPhaseTimeInterval;
    } else if (saleStage == SaleStage.Closed) {
        if (now < icoEnd) {
            icoEnd = now;
        }
        if (ibcFunded < totalFundingGoalInIBC) {
            fundingRatePredictionBonusPoolInIBC = add(fundingRatePredictionBonusPoolInIBC, sub(totalFundingGoalInIBC, ibcFunded));
        }
        emit CrowdsaleClosed(beneficiary, etherRaised);
    }
}

function withdrawEther(uint amount) external {
    require(msg.sender == beneficiary);
    if (beneficiary.send(amount)) {
        emit FundTransfer(SaleStage.Closed, beneficiary, amount, false);
    }
}

function changePayees(address[] memory _payees, uint256[] memory _shares) public override onlyManager {
    require(_payees.length == _shares.length, "Payees and shares mismatched");
    require(_payees.length > 0, "No payees");
    if (payees.length > 0 && mintableTokens() > 0) {
        release();
    }
    for (uint256 i = 0; i < payees.length; i++) {
        delete shares[payees[i]];
    }
    delete payees;
    totalShares = 0;
    for (uint256 i = 0; i < _payees.length; i++) {
        _addPayee(_payees[i], _shares[i]);
    }
}

function release() public override {
    uint256 newTokens = mintableTokens();
    require(newTokens > 0, "newTokens is 0");
    require(payees.length > 0, "Payees not configured yet");
    for (uint256 i = 0; i < payees.length; i++) {
        address payee = payees[i];
        _release(newTokens, payee);
    }
    emit TokensReleased(newTokens, now);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = 0; 
    uint256 _taxedTokens = _amountOfTokens; 
    uint256 _dividends = 0; 
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function inRebaseWindow() public view returns(bool) {
    require(rebasingActive, 'inRebaseWindow: rebasing not active');
    uint256 nowTimestamp = getNow();
    require(
        nowTimestamp.mod(minRebaseTimeIntervalSec) >= rebaseWindowOffsetSec,
        'inRebaseWindow: too early'
    );
    require(
        nowTimestamp.mod(minRebaseTimeIntervalSec) <
        (rebaseWindowOffsetSec.add(rebaseWindowLengthSec)),
        'inRebaseWindow: too late'
    );
    return true;
}

function rebase() public {
    inRebaseWindow();
    uint256 nowTimestamp = getNow();
    require(
        lastRebaseTimestamp.add(minRebaseTimeIntervalSec) < nowTimestamp,
        'rebase: Rebase already triggered'
    );
    lastRebaseTimestamp = nowTimestamp.sub(nowTimestamp.mod(minRebaseTimeIntervalSec)).add(
        rebaseWindowOffsetSec
    );
    epoch++;
    (uint256 priceCumulative, uint32 blockTimestamp, uint256 twap) = getCurrentTwap();
    priceCumulativeLast = priceCumulative;
    blockTimestampLast = blockTimestamp;
    bool inCircuitBreaker = false;
    (
        uint256 newHotpotBasePerBlock,
        uint256 newFarmHotpotBasePerBlock,
        uint256 newHalvingCounter
    ) = getNewHotpotBasePerBlock(twap);
    farmHotpotBasePerBlock = newFarmHotpotBasePerBlock;
    halvingCounter = newHalvingCounter;
    uint256 newRedShare = getNewRedShare(twap);
    if (!withinDeviationThreshold(twap)) {
        uint256 absoluteDeviationMovement = targetPrice.mul(deviationMovement).div(1e18);
        if (twap > targetPrice) {
            upwardCounter++;
            if (downwardCounter > 0) {
                downwardCounter = 0;
            }
            if (upwardCounter >= retargetThreshold) {
                targetPrice = targetPrice.add(absoluteDeviationMovement);
            }
        } else {
            inCircuitBreaker = true;
            downwardCounter++;
            if (upwardCounter > 0) {
                upwardCounter = 0;
            }
            if (downwardCounter >= retargetThreshold) {
                targetPrice = targetPrice.sub(absoluteDeviationMovement);
            }
        }
    } else {
        upwardCounter = 0;
        downwardCounter = 0;
    }
    masterPot.massUpdatePools();
    masterPot.setHotpotBasePerBlock(newHotpotBasePerBlock);
    masterPot.setRedPotShare(newRedShare);
    masterPot.setCircuitBreaker(inCircuitBreaker);
}

function activateRebasing() public {
    require(timeOfTwapInit > 0, 'activateRebasing: twap wasnt intitiated, call init_twap()');
    require(getNow() >= timeOfTwapInit + rebaseDelay, 'activateRebasing: !end_delay');
    rebasingActive = true;
}

