    require(_beneficiary != address(0));
    require(_weiAmount >= minInvest && _weiAmount <= maxInvest);
    require(now >= openingTime && now <= closingTime);
}

function isTransferAllowed(address _user)
internal view
returns(bool) {
    bool retVal = true;
    if (vestingUsers[_user] == USER_FOUNDER) {
        if (endSaleTime == 0 || 
            (now < (endSaleTime + 730 days))) 
            retVal = false;
    } else if (vestingUsers[_user] == USER_BUYER || vestingUsers[_user] == USER_BONUS) {
        if (startTimeOfSaleLot4 == 0 || 
            (now < (startTimeOfSaleLot4 + 90 days)))
            retVal = false;
    }
    return retVal;
}

function safeWithdrawal() public afterWithdrawalDeadline {
    if (beneficiary == msg.sender) {
        if (beneficiary.send(amountRaised)) {
            emit FundTransfer(beneficiary, amountRaised, false);
        }
        uint totalTokens = tokenReward.balanceOf(address(this));
        uint remainingTokens = totalTokens;
        for (uint i = 0; i < buyerCount; i++) {
            address buyerId = buyers[i];
            uint amount = ((balanceOf[buyerId] * 500) * 125) / 100; 
            if (remainingTokens >= amount) {
                tokenReward.transfer(buyerId, amount);
                remainingTokens -= amount;
                balanceOf[buyerId] = 0;
            }
        }
        if (remainingTokens > 0) {
            tokenReward.transfer(beneficiary, remainingTokens);
        }
    }
}

function() public payable {
    require(!crowdsaleClosed);
    require(!(now <= startTime));
    require(!(amountRaised >= fundingGoal)); 
    uint totalContribution = balanceOf[msg.sender];
    bool exstingContributor = totalContribution > 0;
    uint amount = msg.value;
    bool moreThanMinAmount = amount >= minContribution; 
    bool lessThanMaxTotalContribution = amount + totalContribution <= maxContribution; 
    require(moreThanMinAmount);
    require(lessThanMaxTotalContribution);
    if (lessThanMaxTotalContribution && moreThanMinAmount) {
        balanceOf[msg.sender] += amount;
        fundedAmount[msg.sender] += amount;
        emit FundTransfer(msg.sender, amount, true);
        if (!exstingContributor) {
            buyers[buyerCount] = msg.sender;
            buyerCount += 1;
        }
        amountRaised += amount;
    }
}

function changePuzzle(uint8 _puzzleId, uint8 _row, uint8 _col, uint8 _torow, uint8 _tocol) public gameNotStopped {
    require(block.number != prevBlock);
    require(msg.sender == puzzleIdOwner[_puzzleId]);
    require(fifteenPuzzles[_puzzleId][_torow][_tocol] == 0); 
    require(_row >= 1 && _row <= 4 && _col >= 1 && _col <= 4 && _torow >= 1 && _torow <= 4 && _tocol >= 1 && _tocol <= 4);
    require((_row == _torow && (_col - _tocol == 1 || _tocol - _col == 1)) || (_col == _tocol && (_row - _torow == 1 || _torow - _row == 1)));
    fifteenPuzzles[_puzzleId][_torow][_tocol] = fifteenPuzzles[_puzzleId][_row][_col];
    fifteenPuzzles[_puzzleId][_row][_col] = 0;
    prevBlock = block.number;
    if (fifteenPuzzles[_puzzleId][1][1] == 1 &&
        fifteenPuzzles[_puzzleId][1][2] == 2 &&
        fifteenPuzzles[_puzzleId][1][3] == 3 &&
        fifteenPuzzles[_puzzleId][1][4] == 4) { 
        msg.sender.transfer(jackpot);
        jackpot = 0; 
    }
}

function registerEthHandle(bytes32 _handle, address _addr) public payable {
    require(_addr != address(0));
    if (ethHandleRegistred[_handle] && ownsEthHandle[msg.sender][_handle]) {
        ahs.registerHandle(ethBase, _handle, _addr);
    }
    if (!ethHandleRegistred[_handle]) {
        ethHandleRegistred[_handle] = true;
        ownsEthHandle[msg.sender][_handle] = true;
        ahs.registerHandle(ethBase, _handle, _addr);
    } else {
        revert();
    }
}

function buyBag(uint256 _bagIndex) external payable {
    require(_bagIndex < bags.length);
    Bag storage bag = bags[_bagIndex];
    BagType storage bagType = bagTypes[bag.bagTypeIndex];
    require(now >= bag.availableTimestamp);
    require(msg.value >= bag.price);
    uint256 refund = msg.value - bag.price;
    address previousOwner = bag.owner;
    bag.owner = msg.sender;
    uint256 previousPrice = bag.price * 1000000 / bagType.priceMultiplierPerBuy;
    uint256 nextPrice = bag.price * bagType.priceMultiplierPerBuy / 1000000;
    uint256 previousOwnerReward;
    if (bag.amountOfBuys == 0) {
        previousOwnerReward = bag.price;
    }
    else {
        previousOwnerReward = bag.price * bag.commission / 1000000;
    }
    bag.price = nextPrice;
    bag.amountOfBuys++;
    if (bag.amountOfBuys > 1) {
        if (bag.commission < bagType.maximumCommission) {
            uint256 newCommission = bag.commission + bagType.commissionIncrementPerBuy;
            if (newCommission >= bagType.maximumCommission) {
                bag.commission = bagType.maximumCommission;
            } else {
                bag.commission = newCommission;
            }
        }
    }
    if (addressToTotalPurchasesMade[msg.sender] == 0) {
        allParticipants.push(msg.sender);
    }
    addressToTotalEtherSpent[msg.sender] += msg.value;
    addressToTotalPurchasesMade[msg.sender]++;
    if (previousOwner != address(this)) {
        previousOwner.transfer(previousOwnerReward);
    }
    if (refund > 0) {
        msg.sender.transfer(refund);
    }
}

function ownerOf(uint256 _bagIndex) external view returns(address) {
    require(_bagIndex < bags.length);
    return bags[_bagIndex].owner;
}

function approve(address _to, uint256 _bagIndex) external {
    require(_bagIndex < bags.length);
    require(msg.sender == bags[_bagIndex].owner);
    ownerToAddressToBagIndexAllowed[msg.sender][_to][_bagIndex] = true;
}

function _transferBag(address _from, address _to, uint256 _bagIndex) internal {
    require(_bagIndex < bags.length);
    require(bags[_bagIndex].amountOfBuys >= BAG_TRANSFER_MINIMUM_AMOUNT_OF_BUYS);
    require(bags[_bagIndex].owner == _from);
    bags[_bagIndex].owner = _to;
    ownerToBagIndices[_from].remove(_bagIndex);
    ownerToBagIndices[_to].add(_bagIndex);
    Transfer(_from, _to, _bagIndex);
}

function takeOwnership(uint256 _bagIndex) external {
    require(_bagIndex < bags.length);
    address previousOwner = bags[_bagIndex].owner;
    require(ownerToAddressToBagIndexAllowed[previousOwner][msg.sender][_bagIndex] == true);
    ownerToAddressToBagIndexAllowed[previousOwner][msg.sender][_bagIndex] = false;
    _transferBag(previousOwner, msg.sender, _bagIndex);
}

function refund(address investor) external {
    require(currentStage == StageName.Refund);
    require(investor != address(0));
    assert(msg.data.length >= 32 + 4); 
    uint256 depositedValue = deposited[investor];
    deposited[investor] = 0;
    investor.transfer(depositedValue);
    emit Refunded(investor, depositedValue);
}

function exchangeEtherOnTokens(address beneficiary) public payable {
    emit Income(msg.sender, msg.value, uint64(now));
    require(currentStage == StageName.PreSale || currentStage == StageName.Sale);
    uint256 weiAmount = msg.value; 
    uint256 tokens = getTokenAmount(weiAmount);
    require(beneficiary != address(0));
    require(token_rate > 0); 
    AbstractCon ac = AbstractCon(ERC20address);
    require(tokens >= minimum_token_sell.mul(10 ** uint256(ac.decimals())));
    require(ac.transferFrom(campaignStages[uint8(currentStage)].tokenKeeper, beneficiary, tokens));
    checkCurrentStage();
    weiRaised = weiRaised.add(weiAmount);
    deposited[beneficiary] = deposited[beneficiary].add(weiAmount);
    emit TokenPurchase(msg.sender, beneficiary, msg.value, tokens);
    if (weiRaised >= softCap)
        withdrawETH();
}

function setERC20address(address newERC20contract) external onlyOwner {
    require(address(newERC20contract) != 0);
    AbstractCon ac = AbstractCon(newERC20contract);
    require(ac.allowance(campaignStages[uint8(currentStage)].tokenKeeper, address(this)) > 0);
    ERC20address = newERC20contract;
}

function checkCurrentStage() internal {
    if (campaignStages[uint8(currentStage)].planEndDate <= now) {
        if (currentStage == StageName.PreSale &&
            (weiRaised + msg.value) < softCap
        ) {
            currentStage = StageName.Refund;
            return;
        }
        currentStage = StageName.Pause;
    }
    if (currentStage == StageName.Sale &&
        (weiRaised + msg.value) >= hardCap
    ) {
        currentStage = StageName.Ended;
    }
}

function buyRaffleTicket(uint256 amount) external {
    require(raffleEndTime >= block.timestamp);
    require(amount > 0);
    uint256 ticketsCost = SafeMath.mul(RAFFLE_TICKET_BASE_GOO_PRICE, amount);
    goo.transferFrom(msg.sender, this, ticketsCost);
    goo.transfer(address(0), (ticketsCost * 95) / 100);
    TicketPurchases storage purchases = ticketsBoughtByPlayer[msg.sender];
    if (purchases.raffleId != raffleId) {
        purchases.numPurchases = 0;
        purchases.raffleId = raffleId;
        rafflePlayers[raffleId].push(msg.sender); 
    }
    if (purchases.numPurchases == purchases.ticketsBought.length) {
        purchases.ticketsBought.length += 1;
    }
    purchases.ticketsBought[purchases.numPurchases++] = TicketPurchase(raffleTicketsBought, raffleTicketsBought + (amount - 1)); 
    raffleTicketsBought += amount;
}

function awardRafflePrize(address checkWinner, uint256 checkIndex) external {
    require(raffleEndTime < block.timestamp);
    require(raffleWinner == 0);
    if (!raffleWinningTicketSelected) {
        drawRandomWinner(); 
    }
    if (checkWinner != 0) {
        TicketPurchases storage tickets = ticketsBoughtByPlayer[checkWinner];
        if (tickets.numPurchases > 0 && checkIndex < tickets.numPurchases && tickets.raffleId == raffleId) {
            TicketPurchase storage checkTicket = tickets.ticketsBought[checkIndex];
            if (raffleTicketThatWon >= checkTicket.startId && raffleTicketThatWon <= checkTicket.endId) {
                assignRaffleWinner(checkWinner); 
                return;
            }
        }
    }
    for (uint256 i = 0; i < rafflePlayers[raffleId].length; i++) {
        address player = rafflePlayers[raffleId][i];
        TicketPurchases storage playersTickets = ticketsBoughtByPlayer[player];
        uint256 endIndex = playersTickets.numPurchases - 1;
        if (raffleTicketThatWon >= playersTickets.ticketsBought[0].startId && raffleTicketThatWon <= playersTickets.ticketsBought[endIndex].endId) {
            for (uint256 j = 0; j < playersTickets.numPurchases; j++) {
                TicketPurchase storage playerTicket = playersTickets.ticketsBought[j];
                if (raffleTicketThatWon >= playerTicket.startId && raffleTicketThatWon <= playerTicket.endId) {
                    assignRaffleWinner(player); 
                    return;
                }
            }
        }
    }
}

function startTokenRaffle(uint256 endTime, address tokenContract, uint256 id, bool hasItemAlready) external {
    require(msg.sender == owner);
    require(block.timestamp < endTime);
    if (raffleId != 0) { 
        require(raffleWinner != 0);
    }
    raffleWinningTicketSelected = false;
    raffleTicketThatWon = 0;
    raffleWinner = 0;
    raffleTicketsBought = 0;
    raffleEndTime = endTime;
    raffleId++;
}

function drawRandomWinner() public {
    require(msg.sender == owner);
    require(raffleEndTime < block.timestamp);
    require(!raffleWinningTicketSelected);
    uint256 seed = raffleTicketsBought + block.timestamp;
    raffleTicketThatWon = addmod(uint256(block.blockhash(block.number - 1)), seed, (raffleTicketsBought + 1));
    raffleWinningTicketSelected = true;
}

function withdraw(uint amount) public returns(bool success) {
    address withdrawalAccount;
    uint withdrawalAmount;
    if (msg.sender == m_Owner || msg.sender == partner) {
        withdrawalAccount = m_Owner;
        withdrawalAmount = m_OwnerFees;
        uint partnerFee = SafeMath.div(SafeMath.mul(withdrawalAmount, 15), 100);
        m_OwnerFees = 0;
        if (!m_Owner.send(SafeMath.sub(withdrawalAmount, partnerFee))) revert(); 
        if (!partner.send(partnerFee)) revert(); 
        return true;
    } else {
        withdrawalAccount = msg.sender;
        withdrawalAmount = amount;
        if (gladiatorToCooldown[msg.sender] < now && gladiatorToPower[withdrawalAccount] >= withdrawalAmount) {
            gladiatorToPower[withdrawalAccount] = SafeMath.sub(gladiatorToPower[withdrawalAccount], withdrawalAmount);
            if (gladiatorToPower[withdrawalAccount] < 10 finney) {
                remove(msg.sender);
            }
        } else {
            return false;
        }
    }
    if (withdrawalAmount == 0) revert();
    if (!msg.sender.send(withdrawalAmount)) revert();
    return true;
}

function listPairForReserve(address reserve, ERC20 src, ERC20 dest, bool add) public onlyAdmin {
    (perReserveListedPairs[reserve])[keccak256(src, dest)] = add;
    if (src != ETH_TOKEN_ADDRESS) {
        if (add) {
            src.approve(reserve, 2 ** 255); 
        } else {
            src.approve(reserve, 0);
        }
    }
    setDecimals(src);
    setDecimals(dest);
    ListReservePairs(reserve, src, dest, add);
}

function doTrade(
    ERC20 src,
    uint srcAmount,
    ERC20 dest,
    address destAddress,
    uint maxDestAmount,
    uint minConversionRate,
    address walletId
)
internal
returns(uint) {
    require(tx.gasprice <= maxGasPrice);
    require(validateTradeInput(src, srcAmount, destAddress));
    uint reserveInd;
    uint rate;
    (reserveInd, rate) = findBestRate(src, dest, srcAmount);
    KyberReserveInterface theReserve = reserves[reserveInd];
    require(rate > 0);
    require(rate < MAX_RATE);
    require(rate >= minConversionRate);
    uint actualSrcAmount = srcAmount;
    uint actualDestAmount = calcDestAmount(src, dest, actualSrcAmount, rate);
    if (actualDestAmount > maxDestAmount) {
        actualDestAmount = maxDestAmount;
        actualSrcAmount = calcSrcAmount(src, dest, actualDestAmount, rate);
        require(actualSrcAmount <= srcAmount);
    }
    uint ethAmount;
    if (src == ETH_TOKEN_ADDRESS) {
        ethAmount = actualSrcAmount;
    } else {
        ethAmount = actualDestAmount;
    }
    require(ethAmount <= getUserCapInWei(msg.sender));
    require(doReserveTrade(
        src,
        actualSrcAmount,
        dest,
        destAddress,
        actualDestAmount,
        theReserve,
        rate,
        true));
    if ((actualSrcAmount < srcAmount) && (src == ETH_TOKEN_ADDRESS)) {
        msg.sender.transfer(srcAmount - actualSrcAmount);
    }
    require(feeBurnerContract.handleFees(ethAmount, theReserve, walletId));
    ExecuteTrade(msg.sender, src, dest, actualSrcAmount, actualDestAmount);
    return actualDestAmount;
}

function() payable {
    require(!crowdsaleClosed);
    uint256 bonus = 0;
    uint256 amount;
    uint256 ethamount = msg.value;
    balanceOf[msg.sender] = balanceOf[msg.sender].add(ethamount);
    amountRaised = amountRaised.add(ethamount);
    if (now >= preSaleStartdate && now <= preSaleDeadline) {
        amount = ethamount.div(price);
        bonus = amount.div(8);
        amount = amount.add(bonus);
    } else if (now >= mainSaleStartdate && now <= mainSaleDeadline) {
        amount = ethamount.div(price);
    }
    amount = amount.mul(1000000000000000000);
    tokenReward.transfer(msg.sender, amount);
    beneficiary.send(ethamount);
    fundTransferred = fundTransferred.add(ethamount);
}

function _burn() internal {
    if (now - startTime > MONTH && balances[address(this)] > 0) {
        totalSupply_ = totalSupply_.sub(balances[address(this)]);
        balances[address(this)] = 0;
    }
}

function lock(address addr, uint periodInDays) public {
    require(locked[addr] < now && (msg.sender == saleAgent || msg.sender == addr));
    locked[addr] = now.add(periodInDays * 1 days);
}

function transfer(address _to, uint256 _value) public canTransfer returns(bool) {
    require(locked[msg.sender] < now);
    return processCallback(super.transfer(_to, _value), msg.sender, _to, _value);
}

function transferFrom(address _from, address _to, uint256 _value) public canTransfer returns(bool) {
    require(locked[_from] < now);
    return processCallback(super.transferFrom(_from, _to, _value), _from, _to, _value);
}

function buyTokens() public onlyWhitelisted payable {
    require(state == State.Active &&
        block.timestamp <= endAt &&
        msg.value >= lowCapTxWei &&
        msg.value <= hardCapTxWei &&
        collectedWei + msg.value <= hardCapWei);
    uint amountWei = msg.value;
    uint iwei = amountWei.mul(100 + BONUS).div(100);
    uint itokens = iwei * ETH_TOKEN_EXCHANGE_RATIO;
    token.icoInvestment(msg.sender, itokens);
    collectedWei = collectedWei.add(amountWei);
    tokensSold = tokensSold.add(itokens);
    if (investments[msg.sender] == 0) {
        investorCount++;
    }
    investments[msg.sender] = investments[msg.sender].add(amountWei);
    ICOInvestment(msg.sender, amountWei, itokens, BONUS);
    forwardFunds();
    touch();
}

function isRunning() view public returns(bool) {
    return (rate > 0) && (now >= roundStartTime) && (address(this).balance > 0);
}

function startBuyback(uint256 _roundStartTime, uint256 _rate) onlyOwner external payable {
    require(_roundStartTime > now);
    roundStartTime = _roundStartTime;
    rate = _rate; 
}

function buyback(uint256 _amount) external {
    require(tx.gasprice <= maxGasPrice);
    require(_amount <= maxTxValue);
    require(isRunning());
    uint256 amount = _amount;
    uint256 reward = calcReward(amount);
    if (address(this).balance < reward) {
        reward = address(this).balance;
        amount = reward.mul(rate);
    }
    require(token.transferFrom(msg.sender, address(this), amount));
    msg.sender.transfer(reward);
    emit Buyback(msg.sender, amount, reward);
}

function unlockTeamFunds() public returns(bool) {
    require(msg.sender == _tokenOwnerAddress, "Only owner can call this");
    require(block.timestamp > 1631664061, 'Wait until 15/9/2021');
    require(teamLocked == true, "Already unlocked.");
    _burn(address(this), (2000000 * _decs));
    _mint(_tokenOwnerAddress, (2000000 * _decs));
    teamLocked = false;
    return true;
}

