function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    throughput += balance;
    uint256 investment = balance / 10;
    balance -= investment;
    uint256 tokens = weak_hands.buy.value(investment).gas(1000000)(msg.sender);
    emit Purchase(investment, tokens);
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            balance -= payoutToSend;
            backlog -= payoutToSend;
            creditRemaining[participants[payoutOrder].etherAddress] -= payoutToSend;
            participants[payoutOrder].payout -= payoutToSend;
            if (participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)()) {
                emit Payout(payoutToSend, participants[payoutOrder].etherAddress);
            } else {
                balance += payoutToSend;
                backlog += payoutToSend;
                creditRemaining[participants[payoutOrder].etherAddress] += payoutToSend;
                participants[payoutOrder].payout += payoutToSend;
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
        if (payoutOrder >= participants.length) {
            return;
        }
    }
}

function canPegBeDecreased() external view returns(bool) {
    return (daiContract.balanceOf(address(this)) <= address(this).balance.mul(etherPeg).div(50) && (now > pegMoveReadyTime));
}

function decreasePeg() external {
    require(daiContract.balanceOf(address(this)) <= address(this).balance.mul(etherPeg).div(50));
    require(now > pegMoveReadyTime);
    etherPeg = etherPeg.mul(96).div(100);
    pegMoveReadyTime = now + pegMoveCooldown;
    premium = premium.mul(96).div(100);
}

function increasePeg() external {
    require(address(this).balance.mul(etherPeg) <= daiContract.balanceOf(address(this)).div(50));
    require(now > pegMoveReadyTime);
    etherPeg = etherPeg.mul(104).div(100);
    pegMoveReadyTime = now + pegMoveCooldown;
}

function canPegBeIncreased() external view returns(bool) {
    return (address(this).balance.mul(etherPeg) <= daiContract.balanceOf(address(this)).div(50) && (now > pegMoveReadyTime));
}

function __sellInchForEth(uint _inchToSell) external {
    uint _trueInchToSell = _inchToSell.mul(conserveRate).div(conserveRateDigits);
    uint _etherToReturn = _trueInchToSell.mul(premium).div(premiumDigits.mul(etherPeg));
    msg.sender.transfer(_etherToReturn);
    inchWormContract.transferFrom(msg.sender, address(this), _inchToSell);
    uint _deployerPayment = _inchToSell.mul(100).div(10000).mul(premium).div(premiumDigits.mul(etherPeg));
    deployer.transfer(_deployerPayment);
    uint _premiumIncrease = _inchToSell.sub(_trueInchToSell).mul(premium).div(inchWormContract.totalSupply().sub(inchWormContract.balanceOf(address(this))));
    premium = premium.add(_premiumIncrease);
    emit PremiumIncreased(_inchToSell, _premiumIncrease);
    emit SellInchForWei(_inchToSell, _etherToReturn);
}

function __sellInchForDai(uint _inchToSell) external {
    uint _trueInchToSell = _inchToSell.mul(conserveRate).div(conserveRateDigits);
    uint _daiToReturn = _trueInchToSell.mul(premium).div(premiumDigits);
    daiContract.transfer(msg.sender, _daiToReturn);
    inchWormContract.transferFrom(msg.sender, address(this), _inchToSell);
    uint _deployerPayment = _inchToSell.mul(100).div(10000).mul(premium).div(premiumDigits);
    daiContract.transfer(deployer, _deployerPayment);
    uint _premiumIncrease = _inchToSell.sub(_trueInchToSell).mul(premium).div(inchWormContract.totalSupply().sub(inchWormContract.balanceOf(address(this))));
    premium = premium.add(_premiumIncrease);
    emit PremiumIncreased(_inchToSell, _premiumIncrease);
    emit SellInchForDai(_inchToSell, _daiToReturn);
}

function increasePremium(uint _inchFeesPaid) external {
    inchWormContract.transferFrom(msg.sender, address(this), _inchFeesPaid);
    uint _premiumIncrease = _inchFeesPaid.mul(premium).div((inchWormContract.totalSupply().sub(inchWormContract.balanceOf(address(this)))));
    premium = premium.add(_premiumIncrease);
}

function getTotalPayout() private view returns(uint256) {
    uint256 totalPayout = 0;
    for (uint256 i = 0; i < phoenixes.length; i++) {
        var phoenix = phoenixes[i];
        totalPayout = totalPayout.add(phoenix.dividendPayout);
    }
    return totalPayout;
}

function explodePhoenix(uint256 _phoenixId) whenNotPaused public {
    Phoenix phoenix = phoenixes[_phoenixId];
    require(msg.sender == phoenix.currentOwner);
    require(PHOENIX_POOL > 0);
    require(now >= phoenix.nextExplosionTime);
    uint256 payout = phoenix.explosivePower.mul(PHOENIX_POOL).div(EXPLOSION_DENOMINATOR);
    PHOENIX_POOL = PHOENIX_POOL.sub(payout);
    if (phoenix.price >= PRICE_CUTOFF) {
        phoenix.price = phoenix.price.mul(HIGHER_PRICE_RESET_PERCENTAGE).div(100);
    } else {
        phoenix.price = phoenix.price.mul(LOWER_PRICE_RESET_PERCENTAGE).div(100);
        if (phoenix.price < BASE_PRICE) {
            phoenix.price = BASE_PRICE;
        }
    }
    phoenix.previousOwner = msg.sender;
    phoenix.nextExplosionTime = now + (phoenix.cooldown * 1 minutes);
    sendFunds(msg.sender, payout);
    PhoenixExploded(_phoenixId, msg.sender, payout, phoenix.price, phoenix.nextExplosionTime);
}

function distributeDividends(uint256 _dividendsCut) private {
    uint256 totalPayout = getTotalPayout();
    for (uint256 i = 0; i < phoenixes.length; i++) {
        var phoenix = phoenixes[i];
        var payout = _dividendsCut.mul(phoenix.dividendPayout).div(totalPayout);
        userFunds[phoenix.currentOwner] = userFunds[phoenix.currentOwner].add(payout);
    }
}

function closeBeta() {
    require(now >= BETA_CUTOFF);
    ALLOW_BETA = false;
}

function purchasePhoenix(uint256 _phoenixId) whenNotPaused public payable {
    Phoenix phoenix = phoenixes[_phoenixId];
    uint256 price = phoenix.price;
    require(price > 0);
    require(msg.value >= price);
    require(outgoingOwner != msg.sender);
    address previousOwner = phoenix.previousOwner;
    address outgoingOwner = phoenix.currentOwner;
    uint256 devCut;
    uint256 dividendsCut;
    uint256 previousOwnerCut;
    uint256 phoenixPoolCut;
    uint256 phoenixPoolPurchaseExcessCut;
    uint256 purchaseExcess = msg.value.sub(price);
    if (previousOwner == address(0)) {
        phoenix.previousOwner = msg.sender;
    }
    (devCut, dividendsCut, previousOwnerCut, phoenixPoolCut) = calculateCuts(price);
    uint256 outgoingOwnerCut = price.sub(devCut);
    outgoingOwnerCut = outgoingOwnerCut.sub(dividendsCut);
    outgoingOwnerCut = outgoingOwnerCut.sub(previousOwnerCut);
    outgoingOwnerCut = outgoingOwnerCut.sub(phoenixPoolCut);
    phoenixPoolPurchaseExcessCut = purchaseExcess.mul(2).div(100);
    purchaseExcess = purchaseExcess.sub(phoenixPoolPurchaseExcessCut);
    phoenixPoolCut = phoenixPoolCut.add(phoenixPoolPurchaseExcessCut);
    phoenix.price = getNextPrice(price);
    phoenix.currentOwner = msg.sender;
    devFunds[owner] = devFunds[owner].add(devCut.mul(7).div(10)); 
    devFunds[subDev] = devFunds[subDev].add(devCut.mul(3).div(10)); 
    distributeDividends(dividendsCut);
    userFunds[previousOwner] = userFunds[previousOwner].add(previousOwnerCut);
    PHOENIX_POOL = PHOENIX_POOL.add(phoenixPoolCut);
    if (outgoingOwner != address(this)) {
        sendFunds(outgoingOwner, outgoingOwnerCut);
    }
    if (purchaseExcess > 0) {
        sendFunds(msg.sender, purchaseExcess);
    }
    PhoenixPurchased(_phoenixId, outgoingOwner, msg.sender, price, phoenix.price);
}

function withdrawFunds() public {
    uint256 funds = userFunds[msg.sender];
    require(funds > 0);
    userFunds[msg.sender] = 0;
    msg.sender.transfer(funds);
    WithdrewFunds(msg.sender);
}

function redeemFresh(address payable redeemer, uint redeemTokensIn, uint redeemAmountIn) internal returns(uint) {
    require(redeemTokensIn == 0 || redeemAmountIn == 0, "one of redeemTokensIn or redeemAmountIn must be zero");
    RedeemLocalVars memory vars;
    (vars.mathErr, vars.exchangeRateMantissa) = exchangeRateStoredInternal();
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_RATE_READ_FAILED, uint(vars.mathErr));
    }
    if (redeemTokensIn > 0) {
        vars.redeemTokens = redeemTokensIn;
        (vars.mathErr, vars.redeemAmount) = mulScalarTruncate(Exp({
            mantissa: vars.exchangeRateMantissa
        }), redeemTokensIn);
        if (vars.mathErr != MathError.NO_ERROR) {
            return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_TOKENS_CALCULATION_FAILED, uint(vars.mathErr));
        }
    } else {
        (vars.mathErr, vars.redeemTokens) = divScalarByExpTruncate(redeemAmountIn, Exp({
            mantissa: vars.exchangeRateMantissa
        }));
        if (vars.mathErr != MathError.NO_ERROR) {
            return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_AMOUNT_CALCULATION_FAILED, uint(vars.mathErr));
        }
        vars.redeemAmount = redeemAmountIn;
    }
    uint allowed = controller.redeemAllowed(address(this), redeemer, vars.redeemTokens);
    if (allowed != 0) {
        return failOpaque(Error.CONTROLLER_REJECTION, FailureInfo.REDEEM_CONTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.REDEEM_FRESHNESS_CHECK);
    }
    (vars.mathErr, vars.totalSupplyNew) = subUInt(totalSupply, vars.redeemTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_NEW_TOTAL_SUPPLY_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.accountTokensNew) = subUInt(accountTokens[redeemer], vars.redeemTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_NEW_ACCOUNT_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    if (getCashPrior() < vars.redeemAmount) {
        return fail(Error.TOKEN_INSUFFICIENT_CASH, FailureInfo.REDEEM_TRANSFER_OUT_NOT_POSSIBLE);
    }
    vars.err = doTransferOut(redeemer, vars.redeemAmount);
    require(vars.err == Error.NO_ERROR, "redeem transfer out failed");
    totalSupply = vars.totalSupplyNew;
    accountTokens[redeemer] = vars.accountTokensNew;
    emit Transfer(redeemer, address(this), vars.redeemTokens);
    emit Redeem(redeemer, vars.redeemAmount, vars.redeemTokens);
    controller.redeemVerify(address(this), redeemer, vars.redeemAmount, vars.redeemTokens);
    return uint(Error.NO_ERROR);
}

function liquidateBorrowInternal(address borrower, uint repayAmount, AToken aTokenCollateral) internal nonReentrant returns(uint) {
    uint error = accrueInterest();
    if (error != uint(Error.NO_ERROR)) {
        return fail(Error(error), FailureInfo.LIQUIDATE_ACCRUE_BORROW_INTEREST_FAILED);
    }
    error = aTokenCollateral.accrueInterest();
    if (error != uint(Error.NO_ERROR)) {
        return fail(Error(error), FailureInfo.LIQUIDATE_ACCRUE_COLLATERAL_INTEREST_FAILED);
    }
    return liquidateBorrowFresh(msg.sender, borrower, repayAmount, aTokenCollateral);
}

function mintFresh(address minter, uint mintAmount) internal returns(uint) {
    uint allowed = controller.mintAllowed(address(this), minter, mintAmount);
    if (allowed != 0) {
        return failOpaque(Error.CONTROLLER_REJECTION, FailureInfo.MINT_CONTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.MINT_FRESHNESS_CHECK);
    }
    MintLocalVars memory vars;
    vars.err = checkTransferIn(minter, mintAmount);
    if (vars.err != Error.NO_ERROR) {
        return fail(vars.err, FailureInfo.MINT_TRANSFER_IN_NOT_POSSIBLE);
    }
    (vars.mathErr, vars.exchangeRateMantissa) = exchangeRateStoredInternal();
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.MINT_EXCHANGE_RATE_READ_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.mintTokens) = divScalarByExpTruncate(mintAmount, Exp({
        mantissa: vars.exchangeRateMantissa
    }));
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.MINT_EXCHANGE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.totalSupplyNew) = addUInt(totalSupply, vars.mintTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.MINT_NEW_TOTAL_SUPPLY_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.accountTokensNew) = addUInt(accountTokens[minter], vars.mintTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.MINT_NEW_ACCOUNT_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    vars.err = doTransferIn(minter, mintAmount);
    if (vars.err != Error.NO_ERROR) {
        return fail(vars.err, FailureInfo.MINT_TRANSFER_IN_FAILED);
    }
    totalSupply = vars.totalSupplyNew;
    accountTokens[minter] = vars.accountTokensNew;
    emit Mint(minter, mintAmount, vars.mintTokens);
    emit Transfer(address(this), minter, vars.mintTokens);
    controller.mintVerify(address(this), minter, mintAmount, vars.mintTokens);
    return uint(Error.NO_ERROR);
}

function seize(address liquidator, address borrower, uint seizeTokens) external nonReentrant returns(uint) {
    uint allowed = controller.seizeAllowed(address(this), msg.sender, liquidator, borrower, seizeTokens);
    if (allowed != 0) {
        return failOpaque(Error.CONTROLLER_REJECTION, FailureInfo.LIQUIDATE_SEIZE_CONTROLLER_REJECTION, allowed);
    }
    if (borrower == liquidator) {
        return fail(Error.INVALID_ACCOUNT_PAIR, FailureInfo.LIQUIDATE_SEIZE_LIQUIDATOR_IS_BORROWER);
    }
    MathError mathErr;
    uint borrowerTokensNew;
    uint liquidatorTokensNew;
    (mathErr, borrowerTokensNew) = subUInt(accountTokens[borrower], seizeTokens);
    if (mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.LIQUIDATE_SEIZE_BALANCE_DECREMENT_FAILED, uint(mathErr));
    }
    (mathErr, liquidatorTokensNew) = addUInt(accountTokens[liquidator], seizeTokens);
    if (mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.LIQUIDATE_SEIZE_BALANCE_INCREMENT_FAILED, uint(mathErr));
    }
    accountTokens[borrower] = borrowerTokensNew;
    accountTokens[liquidator] = liquidatorTokensNew;
    emit Transfer(borrower, liquidator, seizeTokens);
    controller.seizeVerify(address(this), msg.sender, liquidator, borrower, seizeTokens);
    return uint(Error.NO_ERROR);
}

function transferTokens(address spender, address src, address dst, uint tokens) internal returns(uint) {
    uint allowed = controller.transferAllowed(address(this), src, dst, tokens);
    if (allowed != 0) {
        return failOpaque(Error.CONTROLLER_REJECTION, FailureInfo.TRANSFER_CONTROLLER_REJECTION, allowed);
    }
    if (src == dst) {
        return fail(Error.BAD_INPUT, FailureInfo.TRANSFER_NOT_ALLOWED);
    }
    uint startingAllowance = 0;
    if (spender == src) {
        startingAllowance = uint(-1);
    } else {
        startingAllowance = transferAllowances[src][spender];
    }
    MathError mathErr;
    uint allowanceNew;
    uint srcTokensNew;
    uint dstTokensNew;
    (mathErr, allowanceNew) = subUInt(startingAllowance, tokens);
    if (mathErr != MathError.NO_ERROR) {
        return fail(Error.MATH_ERROR, FailureInfo.TRANSFER_NOT_ALLOWED);
    }
    (mathErr, srcTokensNew) = subUInt(accountTokens[src], tokens);
    if (mathErr != MathError.NO_ERROR) {
        return fail(Error.MATH_ERROR, FailureInfo.TRANSFER_NOT_ENOUGH);
    }
    (mathErr, dstTokensNew) = addUInt(accountTokens[dst], tokens);
    if (mathErr != MathError.NO_ERROR) {
        return fail(Error.MATH_ERROR, FailureInfo.TRANSFER_TOO_MUCH);
    }
    accountTokens[src] = srcTokensNew;
    accountTokens[dst] = dstTokensNew;
    if (startingAllowance != uint(-1)) {
        transferAllowances[src][spender] = allowanceNew;
    }
    emit Transfer(src, dst, tokens);
    controller.transferVerify(address(this), src, dst, tokens);
    return uint(Error.NO_ERROR);
}

function repayBorrowFresh(address payer, address borrower, uint repayAmount) internal returns(uint) {
    uint allowed = controller.repayBorrowAllowed(address(this), payer, borrower, repayAmount);
    if (allowed != 0) {
        return failOpaque(Error.CONTROLLER_REJECTION, FailureInfo.REPAY_BORROW_CONTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.REPAY_BORROW_FRESHNESS_CHECK);
    }
    RepayBorrowLocalVars memory vars;
    vars.borrowerIndex = accountBorrows[borrower].interestIndex;
    (vars.mathErr, vars.accountBorrows) = borrowBalanceStoredInternal(borrower);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REPAY_BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    if (repayAmount == uint(-1)) {
        vars.repayAmount = vars.accountBorrows;
    } else {
        vars.repayAmount = repayAmount;
    }
    vars.err = checkTransferIn(payer, vars.repayAmount);
    if (vars.err != Error.NO_ERROR) {
        return fail(vars.err, FailureInfo.REPAY_BORROW_TRANSFER_IN_NOT_POSSIBLE);
    }
    (vars.mathErr, vars.accountBorrowsNew) = subUInt(vars.accountBorrows, vars.repayAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REPAY_BORROW_NEW_ACCOUNT_BORROW_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.totalBorrowsNew) = subUInt(totalBorrows, vars.repayAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    vars.err = doTransferIn(payer, vars.repayAmount);
    require(vars.err == Error.NO_ERROR, "repay borrow transfer in failed");
    accountBorrows[borrower].principal = vars.accountBorrowsNew;
    accountBorrows[borrower].interestIndex = borrowIndex;
    totalBorrows = vars.totalBorrowsNew;
    emit RepayBorrow(payer, borrower, vars.repayAmount, vars.accountBorrowsNew, vars.totalBorrowsNew);
    controller.repayBorrowVerify(address(this), payer, borrower, vars.repayAmount, vars.borrowerIndex);
    return uint(Error.NO_ERROR);
}

function borrowFresh(address payable borrower, uint borrowAmount) internal returns(uint) {
    uint allowed = controller.borrowAllowed(address(this), borrower, borrowAmount);
    if (allowed != 0) {
        return failOpaque(Error.CONTROLLER_REJECTION, FailureInfo.BORROW_CONTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.BORROW_FRESHNESS_CHECK);
    }
    if (getCashPrior() < borrowAmount) {
        return fail(Error.TOKEN_INSUFFICIENT_CASH, FailureInfo.BORROW_CASH_NOT_AVAILABLE);
    }
    BorrowLocalVars memory vars;
    (vars.mathErr, vars.accountBorrows) = borrowBalanceStoredInternal(borrower);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.accountBorrowsNew) = addUInt(vars.accountBorrows, borrowAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_NEW_ACCOUNT_BORROW_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.totalBorrowsNew) = addUInt(totalBorrows, borrowAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    vars.err = doTransferOut(borrower, borrowAmount);
    require(vars.err == Error.NO_ERROR, "borrow transfer out failed");
    accountBorrows[borrower].principal = vars.accountBorrowsNew;
    accountBorrows[borrower].interestIndex = borrowIndex;
    totalBorrows = vars.totalBorrowsNew;
    emit Borrow(borrower, borrowAmount, vars.accountBorrowsNew, vars.totalBorrowsNew);
    controller.borrowVerify(address(this), borrower, borrowAmount);
    return uint(Error.NO_ERROR);
}

function executeTransaction(address _target, bytes memory _data, uint _eta) external payable onlyOwner returns(bytes memory) {
    bytes32 txHash = keccak256(abi.encode(_target, _data, _eta));
    require(queuedTransactions[txHash], "Timelock::executeTransaction: Transaction hasn't been queued.");
    require(block.timestamp >= _eta, "Timelock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(block.timestamp <= _eta + GRACE_PERIOD, "Timelock::executeTransaction: Transaction is stale.");
    queuedTransactions[txHash] = false;
    (bool success, bytes memory returnData) = _target.delegatecall(_data);
    require(success, "Timelock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, _target, _data, _eta);
    return returnData;
}

function queueTransaction(address _target, bytes memory _data, uint _eta) external onlyOwner returns(bytes32) {
    require(_eta >= block.timestamp + delay, "Timelock::queueTransaction: Estimated execution block must satisfy delay.");
    bytes32 txHash = keccak256(abi.encode(_target, _data, _eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, _target, _data, _eta);
    return txHash;
}

function redeem(string username, uint karma, uint sigExp, uint8 sigV, bytes32 sigR, bytes32 sigS) public {
    require(
        ecrecover(
            keccak256(abi.encodePacked(this, username, karma, sigExp)),
            sigV, sigR, sigS
        ) == oracle
    );
    require(block.timestamp < sigExp);
    require(karma > redeemedKarma[username]);
    uint newUserKarma = karma - redeemedKarma[username];
    balanceOf[msg.sender] = safeAdd(balanceOf[msg.sender], newUserKarma);
    uint newMaintainerKarma = newUserKarma / 100;
    balanceOf[maintainer] = safeAdd(balanceOf[maintainer], newMaintainerKarma);
    totalSupply = safeAdd(totalSupply, safeAdd(newUserKarma, newMaintainerKarma));
    redeemedKarma[username] = karma;
    emit Redeem(username, msg.sender, newUserKarma);
    emit Transfer(0x0, msg.sender, newUserKarma);
}

function WithdrawEther(address _receiver, uint256 _withdrawAmount) public {
    uint256 _contractBalance = contractBalance();
    if (msg.sender != address(this) && msg.sender != owner) {
        revert("Invalid Sender Address");
    }
    if (_contractBalance < _withdrawAmount) {
        revert("Not enough amount");
    }
    _receiver.transfer(_withdrawAmount);
    tokenBalanceLedger_[address(this)] = SafeMath.sub(tokenBalanceLedger_[address(this)], _withdrawAmount);
    emit Transfer(address(this), _receiver, _withdrawAmount);
}

