function createStream(
    address recipient,
    uint256 depositAmount,
    uint256 streamType,
    uint256 startBlock
)
external
nonReentrant
validStreamType(streamType)
returns(uint256 streamId) {
    require(msg.sender == xdexFarmMaster, "only farmMaster could create");
    require(recipient != address(0), "stream to the zero address");
    require(recipient != address(this), "stream to the contract itself");
    require(recipient != msg.sender, "stream to the caller");
    require(depositAmount > 0, "depositAmount is zero");
    require(startBlock >= block.number, "start block before block.number");
    if (streamType == 0) {
        require(
            !(votingStreams[recipient].isEntity),
            "voting stream exists"
        );
    }
    if (streamType == 1) {
        require(
            !(normalStreams[recipient].isEntity),
            "normal stream exists"
        );
    }
    uint256 unlockKBlocks = unlockKBlocksN;
    if (streamType == 0) {
        unlockKBlocks = unlockKBlocksV;
    }
    IERC20(xdex).approve(address(halflife), depositAmount);
    IERC20(xdex).transferFrom(msg.sender, address(this), depositAmount);
    streamId = halflife.createStream(
        xdex,
        recipient,
        depositAmount,
        startBlock,
        unlockKBlocks,
        unlockRatio,
        cancelable
    );
    if (streamType == 0) {
        votingStreams[recipient] = LockStream({
            depositor: msg.sender,
            isEntity: true,
            streamId: streamId
        });
    } else if (streamType == 1) {
        normalStreams[recipient] = LockStream({
            depositor: msg.sender,
            isEntity: true,
            streamId: streamId
        });
    }
}

function updatePlan(address[] calldata _protocols, uint256[] calldata _coverAmounts)
external
override {
    require(_protocols.length == _coverAmounts.length, "protocol and coverAmount length mismatch");
    require(_protocols.length <= 30, "You may not protect more than 30 protocols at once.");
    if (plans[msg.sender].length > 0) {
        Plan storage lastPlan = plans[msg.sender][plans[msg.sender].length - 1];
        _removeLatestTotals(msg.sender);
        lastPlan.endTime = lastPlan.endTime <= now ? lastPlan.endTime : uint64(now);
    }
    _addNewTotals(_protocols, _coverAmounts);
    uint256 newPricePerSec;
    uint256 _markup = markup;
    for (uint256 i = 0; i < _protocols.length; i++) {
        require(nftCoverPrice[_protocols[i]] != 0, "Protocol price is zero");
        uint256 pricePerSec = nftCoverPrice[_protocols[i]].mul(_coverAmounts[i]);
        newPricePerSec = newPricePerSec.add(pricePerSec);
    }
    newPricePerSec = newPricePerSec.mul(_markup).div(1e18).div(100);
    if (newPricePerSec == 0) {
        Plan memory newPlan;
        newPlan = Plan(uint64(now), uint64(-1), uint128(0));
        plans[msg.sender].push(newPlan);
        IBalanceManager(getModule("BALANCE")).changePrice(msg.sender, 0);
        emit PlanUpdate(msg.sender, _protocols, _coverAmounts, uint64(-1));
        return;
    }
    uint256 balance = IBalanceManager(getModule("BALANCE")).balanceOf(msg.sender);
    uint256 endTime = balance.div(newPricePerSec).add(block.timestamp);
    require(endTime >= block.timestamp.add(7 days), "Balance must be enough for 7 days of coverage.");
    Plan memory newPlan;
    newPlan = Plan(uint64(now), uint64(endTime), uint128(_protocols.length));
    plans[msg.sender].push(newPlan);
    for (uint256 i = 0; i < _protocols.length; i++) {
        bytes32 key = _hashKey(msg.sender, plans[msg.sender].length - 1, i);
        uint64 protocolId = IStakeManager(getModule("STAKE")).protocolId(_protocols[i]);
        protocolPlan[key] = ProtocolPlan(protocolId, uint192(_coverAmounts[i]));
    }
    uint64 castPricePerSec = uint64(newPricePerSec);
    require(uint256(castPricePerSec) == newPricePerSec);
    IBalanceManager(getModule("BALANCE")).changePrice(msg.sender, castPricePerSec);
    emit PlanUpdate(msg.sender, _protocols, _coverAmounts, endTime);
}

function checkStageCondition() private {
    uint timeDiff = now - stageStartTime;
    if (timeDiff > stageTime && currentStage < 3) {
        currentStage++;
        stageMin += 10;
        stageMax -= 10;
        stageStartTime = now;
        emit EvStageChanged(curIteration, timeDiff, currentStage);
    }
}

function withdrawJackpotBalance(uint amount) public onlyOwner {
    require(jackpotBalance >= amount / toGwei && msg.sender != address(0));
    require(now - lastTransaction > 4 weeks);
    uint256 tmpJP = amount / toGwei;
    jackpotBalance -= tmpJP;
    aOwner.transfer(amount);
    emit EvUpdateJackpot(curIteration, amount, jackpotBalance);
}

function payoutInvestors() public {
    uint256 paymentAmount = 0;
    bool isSuccess = false;
    uint256[] memory payouts = new uint256[](investorsCount);
    bool[] memory statuses = new bool[](investorsCount);
    uint256 mFeeAmount = feeAmount;
    uint256 iteration = curIteration;
    for (uint256 i = 0; i < investorsCount; i++) {
        uint256 iEarned = investorsEarned[i];
        if (iEarned == 0) {
            continue;
        }
        paymentAmount = iEarned * toGwei; 
        mFeeAmount -= iEarned;
        investorsEarned[i] = 0;
        isSuccess = investorsAddress[i].send(paymentAmount);
        payouts[i] = iEarned;
        statuses[i] = isSuccess;
    }
    emit EvInvestorsPayout(iteration, bankAmount, payouts, statuses);
    feeAmount = mFeeAmount;
}

function depositPayout(uint depositIndex, uint pAmount) public onlyOwner returns(bool) {
    require(depositIndex < depositsCount && depositIndex >= 0 && depContractidToAmount[depositIndex] > 0);
    require(pAmount <= 5);
    uint256 payoutAmount = depContractidToAmount[depositIndex];
    payoutAmount += (payoutAmount * pAmount) / 100;
    if (payoutAmount > bankAmount) {
        isWipeAllowed = true;
        emit EvBankBecomeEmpty(curIteration, depositIndex, depContractidToAddress[depositIndex], payoutAmount, bankAmount);
        return false;
    }
    uint256 ownerComission = (payoutAmount * ownerFeePercent) / 1000;
    investorsEarned[0] += ownerComission;
    uint256 addToJackpot = (payoutAmount * jackpotPercent) / 1000;
    jackpotBalance += addToJackpot;
    uint256 investorsComission = (payoutAmount * investorsFeePercent) / 1000;
    uint256 payoutComission = ownerComission + addToJackpot + investorsComission;
    uint256 paymentAmount = payoutAmount - payoutComission;
    bankAmount -= payoutAmount;
    feeAmount += ownerComission + investorsComission;
    emit EvDepositPayout(curIteration, bankAmount, depositIndex, depContractidToAddress[depositIndex], paymentAmount, payoutComission, jackpotBalance);
    updateInvestorsComission(investorsComission);
    depContractidToAmount[depositIndex] = 0;
    paymentAmount *= toGwei; 
    depContractidToAddress[depositIndex].transfer(paymentAmount);
    if (depContractidToLottery[depositIndex]) {
        lottery(depContractidToAddress[depositIndex], depositIndex);
    }
    return true;
}

function payoutInvestor(uint256 investorId) public {
    require(investorId < investorsCount && investorsEarned[investorId] > 0);
    uint256 paymentAmount = investorsEarned[investorId] * toGwei; 
    feeAmount -= investorsEarned[investorId];
    investorsEarned[investorId] = 0;
    bool isSuccess = investorsAddress[investorId].send(paymentAmount);
    emit EvInvestorPayout(curIteration, bankAmount, investorId, paymentAmount, isSuccess);
}

function newIteration() public onlyOwner {
    require(isWipeAllowed);
    payoutInvestors();
    investorsInvested[0] = 0;
    investorsCount = 1;
    totalInvestmentAmount = 0;
    bankAmount = 0;
    feeAmount = 0;
    depositsCount = 0;
    currentStage = 1;
    stageStartTime = now;
    stageMin = 0;
    stageMax = 72;
    curIteration += 1;
    emit EvNewIteration(curIteration);
    uint256 realBalance = address(this).balance - (jackpotBalance * toGwei);
    if (realBalance > 0) {
        aOwner.transfer(realBalance);
    }
}

function buyTeam(uint256 _tokenId) public payable {
    address from = teamOwners[_tokenId];
    address to = msg.sender;
    uint256 price = teamPrices[_tokenId];
    require(_addressNotNull(to));
    require(from != to);
    require(msg.value >= price);
    Team storage team = teams[_tokenId];
    uint256 purchaseExcess = SafeMath.sub(msg.value, price);
    uint256 profit = SafeMath.sub(price, team.cost);
    uint256 onePercent = SafeMath.div(profit, 100);
    uint256 developerAllocation = SafeMath.mul(onePercent, 5);
    uint256 saleProceeds = SafeMath.add(SafeMath.mul(onePercent, 85), team.cost);
    uint256 fundProceeds = SafeMath.mul(onePercent, 10);
    _transfer(from, to, _tokenId);
    if (from != address(this)) {
        from.transfer(saleProceeds);
    }
    if (developerAddress != address(this)) {
        developerAddress.transfer(developerAllocation);
    }
    uint256 slice = 0;
    if (!prizes.LastSixteenTotalFixed) {
        slice = SafeMath.div(fundProceeds, 4);
        prizes.LastSixteenWinner += SafeMath.div(slice, 8);
        prizes.QuarterFinalWinner += SafeMath.div(slice, 4);
        prizes.SemiFinalWinner += SafeMath.div(slice, 2);
        prizes.TournamentWinner += slice;
    } else if (!prizes.QuarterFinalTotalFixed) {
        slice = SafeMath.div(fundProceeds, 3);
        prizes.QuarterFinalWinner += SafeMath.div(slice, 4);
        prizes.SemiFinalWinner += SafeMath.div(slice, 2);
        prizes.TournamentWinner += slice;
    } else if (!prizes.SemiFinalTotalFixed) {
        slice = SafeMath.div(fundProceeds, 2);
        prizes.SemiFinalWinner += SafeMath.div(slice, 2);
        prizes.TournamentWinner += slice;
    } else {
        prizes.TournamentWinner += fundProceeds;
    }
    uint256 newPrice = 0;
    if (price < doublePriceUntil) {
        newPrice = SafeMath.div(SafeMath.mul(price, 200), 100);
    } else {
        newPrice = SafeMath.div(SafeMath.mul(price, 115), 100);
    }
    teamPrices[_tokenId] = newPrice;
    team.cost = price;
    team.price = newPrice;
    emit TeamSold(_tokenId, from, price, to, newPrice, uint256(now), address(this).balance, prizes.LastSixteenWinner, prizes.QuarterFinalWinner, prizes.SemiFinalWinner, prizes.TournamentWinner);
    msg.sender.transfer(purchaseExcess);
}

function _checkExpiration(uint256 expiration) private view {
    require(expiration > now || expiration == 0, "Expiration date must be greater than block timestamp or zero");
}

function _renewHold(address token, bytes32 holdId, uint256 expiration) internal returns(bool) {
    Hold storage renewableHold = _holds[token][holdId];
    require(
        renewableHold.status == HoldStatusCode.Ordered ||
        renewableHold.status == HoldStatusCode.ExecutedAndKeptOpen,
        "A hold can only be renewed in status Ordered or ExecutedAndKeptOpen"
    );
    require(!_isExpired(renewableHold.expiration), "An expired hold can not be renewed");
    if (renewableHold.sender == address(0)) { 
        require(
            _canPreHold(token, msg.sender),
            "The pre-hold can only be renewed by the minter"
        );
    } else { 
        require(
            _canPostHold(token, renewableHold.partition, msg.sender, renewableHold.sender),
            "The hold can only be renewed by the issuer or the payer"
        );
    }
    uint256 oldExpiration = renewableHold.expiration;
    renewableHold.expiration = expiration;
    emit HoldRenewed(
        token,
        holdId,
        renewableHold.notary,
        oldExpiration,
        expiration
    );
    return true;
}

function _releaseHold(address token, bytes32 holdId) internal returns(bool) {
    Hold storage releasableHold = _holds[token][holdId];
    require(
        releasableHold.status == HoldStatusCode.Ordered || releasableHold.status == HoldStatusCode.ExecutedAndKeptOpen,
        "A hold can only be released in status Ordered or ExecutedAndKeptOpen"
    );
    require(
        _isExpired(releasableHold.expiration) ||
        (msg.sender == releasableHold.notary) ||
        (msg.sender == releasableHold.recipient),
        "A not expired hold can only be released by the notary or the payee"
    );
    if (_isExpired(releasableHold.expiration)) {
        releasableHold.status = HoldStatusCode.ReleasedOnExpiration;
    } else {
        if (releasableHold.notary == msg.sender) {
            releasableHold.status = HoldStatusCode.ReleasedByNotary;
        } else {
            releasableHold.status = HoldStatusCode.ReleasedByPayee;
        }
    }
    if (releasableHold.sender != address(0)) { 
        _decreaseHeldBalance(token, releasableHold, releasableHold.value);
    }
    emit HoldReleased(token, holdId, releasableHold.notary, releasableHold.status);
    return true;
}

function _createHold(
    address token,
    bytes32 holdId,
    address sender,
    address recipient,
    address notary,
    bytes32 partition,
    uint256 value,
    uint256 expiration,
    bytes32 secretHash
) internal returns(bool) {
    Hold storage newHold = _holds[token][holdId];
    require(recipient != address(0), "Payee address must not be zero address");
    require(value != 0, "Value must be greater than zero");
    require(newHold.value == 0, "This holdId already exists");
    require(notary != address(0), "Notary address must not be zero address");
    if (sender == address(0)) { 
        require(
            _canPreHold(token, msg.sender),
            "The pre-hold can only be created by the minter"
        );
    } else { 
        require(value <= _spendableBalanceOfByPartition(token, partition, sender), "Amount of the hold can't be greater than the spendable balance of the sender");
        require(
            _canPostHold(token, partition, msg.sender, sender),
            "The hold can only be renewed by the issuer or the payer"
        );
    }
    newHold.partition = partition;
    newHold.sender = sender;
    newHold.recipient = recipient;
    newHold.notary = notary;
    newHold.value = value;
    newHold.expiration = expiration;
    newHold.secretHash = secretHash;
    newHold.status = HoldStatusCode.Ordered;
    if (sender != address(0)) {
        _increaseHeldBalance(token, newHold, holdId);
    }
    emit HoldCreated(
        token,
        holdId,
        partition,
        sender,
        recipient,
        notary,
        value,
        expiration,
        secretHash
    );
    return true;
}

function buyTokens(address _beneficiary) public payable onlyAllowed whenNotPaused {
    uint256 weiAmount = msg.value;
    if (weiAmount > weiRaiseLimit.sub(weiRaised)) {
        weiAmount = weiRaiseLimit.sub(weiRaised);
    }
    uint256 tokens = _getTokenAmount(weiAmount);
    if (address(wallet) != address(0)) {
        wallet.onIncome.value(weiAmount)();
    }
    weiRaised = weiRaised.add(weiAmount);
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        weiAmount,
        tokens
    );
    if (msg.value.sub(weiAmount) > 0) {
        msg.sender.transfer(msg.value.sub(weiAmount));
    }
}

